window.CLASSIC_CORPUS = [{"id":"manifesto-1-1","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"中文马克思主义文库 -> 马克思 恩格斯","language":"中文","translation":false},{"id":"manifesto-1-2","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"· 1872年德文版序言","language":"中文","translation":false},{"id":"manifesto-1-3","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"· 1882年俄文版序言","language":"中文","translation":false},{"id":"manifesto-1-4","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"· 1883年德文版序言","language":"中文","translation":false},{"id":"manifesto-1-5","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"· 1888年英文版序言","language":"中文","translation":false},{"id":"manifesto-1-6","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"· 1890年德文版序言","language":"中文","translation":false},{"id":"manifesto-1-7","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"· 1892年波兰文版序言","language":"中文","translation":false},{"id":"manifesto-1-8","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"· 1893年意大利文版序言","language":"中文","translation":false},{"id":"manifesto-1-9","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"三、社会主义的和共产主义的文献","language":"中文","translation":false},{"id":"manifesto-1-10","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"四、共产党人对各种反对党派的态度","language":"中文","translation":false},{"id":"manifesto-1-11","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"〔来源〕原载中共中央马克思恩格斯列宁斯大林著作编译局《共产党宣言（纪念马克思诞辰200周年马克思恩格斯著作特辑》（人民出版社，2018-4-1）","language":"中文","translation":false},{"id":"manifesto-1-12","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"中文马克思主义文库2022年11月更新。","language":"中文","translation":false},{"id":"manifesto-1-13","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1872年德文版序言[1]","language":"中文","translation":false},{"id":"manifesto-1-14","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产主义者同盟[2]这个在当时条件下自然只能是秘密团体的国际工人组织，1847年11月在伦敦举行的代表大会上委托我们两人起草一个准备公布的详细的理论和实践的党纲。结果就产生了这个《宣言》，《宣言》原稿在二月革命[3]前几星期送到伦敦付印。《宣言》最初用德文出版，它用这种文字在德国、英国和美国至少印过12种不同的版本。第一个英译本是由海伦·麦克法林女士翻译的，于1850年在伦敦《红色共和党人》[4]杂志上发表，1871年至少又有三种不同的英译本在美国出版。法译本于1848年六月起义[5]前不久第一次在巴黎印行，最近又有法译本在纽约《社会主义者报》[6]上发表；现在有人在准备新译本。波兰文译本在德文本初版问世后不久就在伦敦出现。俄译本是60年代在日内瓦出版的。丹麦文译本也是在原书问世后不久就出版了。","language":"中文","translation":false},{"id":"manifesto-1-15","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"不管最近25年来的情况发生了多大的变化，这个《宣言》中所阐述的一般原理整个说来直到现在还是完全正确的。某些地方本来可以作一些修改。这些原理的实际运用，正如《宣言》中所说的，随时随地都要以当时的历史条件为转移，所以第二章末尾提出的那些革命措施根本没有特别的意义。如果是在今天，这一段在许多方面都会有不同的写法了。由于最近25年来大工业有了巨大发展而工人阶级的政党组织也跟着发展起来，由于首先有了二月革命的实际经验而后来尤其是有了无产阶级第一次掌握政权达两月之久的巴黎公社[7]的实际经验，所以这个纲领现在有些地方已经过时了。特别是公社已经证明：“工人阶级不能简单地掌握现成的国家机器，并运用它来达到自己的目的。”（见《法兰西内战。国际工人协会总委员会宣言》德文版第19页，那里对这个思想作了更详细的阐述。）〔注：见《马克思恩格斯选集》第3版第3卷第95页。——编者注〕其次，很明显，对于社会主义文献所作的批判在今天看来是不完全的，因为这一批判只包括到1847年为止；同样也很明显，关于共产党人对待各种反对党派的态度的论述（第四章）虽然在原则上今天还是正确的，但是就其实际运用来说今天毕竟已经过时，因为政治形势已经完全改变，当时所列举的那些党派大部分已被历史的发展彻底扫除了。","language":"中文","translation":false},{"id":"manifesto-1-16","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是《宣言》是一个历史文件，我们已没有权利来加以修改。下次再版时也许能加上一篇论述1847年到现在这段时期的导言。这次再版太仓促了，我们来不及做这件工作。","language":"中文","translation":false},{"id":"manifesto-1-17","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卡尔·马克思 弗里德里希·恩格斯","language":"中文","translation":false},{"id":"manifesto-1-18","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1872年6月24日于伦敦","language":"中文","translation":false},{"id":"manifesto-1-19","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卡·马克思和弗·恩格斯写于1872年6月24日","language":"中文","translation":false},{"id":"manifesto-1-20","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"载于1872年在莱比锡出版的德文版《共产主义宣言》一书","language":"中文","translation":false},{"id":"manifesto-1-21","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第376-377页","language":"中文","translation":false},{"id":"manifesto-1-22","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1882年俄文版序言[8]","language":"中文","translation":false},{"id":"manifesto-1-23","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"巴枯宁翻译的《共产党宣言》俄文第一版，60年代初〔注：应是1869年。——编者注〕由《钟声》印刷所出版。当时西方认为这件事（《宣言》译成俄文出版）不过是著作界的一件奇闻。这种看法今天是不可能有了。","language":"中文","translation":false},{"id":"manifesto-1-24","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"当时（1847年12月），卷入无产阶级运动的地区是多么狭小，这从《宣言》最后一章《共产党人对各国各种反对党派的态度》〔注：《宣言》最后一章的标题应是《共产党人对各种反对党派的态度》。——编者注〕中可以看得很清楚。在这一章里，正好没有说到俄国和美国。那时，俄国是欧洲全部反动势力的最后一支庞大后备军；美国正通过移民吸收欧洲无产阶级的过剩力量。这两个国家，都向欧洲提供原料，同时又都是欧洲工业品的销售市场。所以，这两个国家不管怎样当时都是欧洲现存秩序的支柱。","language":"中文","translation":false},{"id":"manifesto-1-25","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"今天，情况完全不同了！正是欧洲移民，使北美能够进行大规模的农业生产，这种农业生产的竞争震撼着欧洲大小土地所有制的根基。此外，这种移民还使美国能够以巨大的力量和规模开发其丰富的工业资源，以至于很快就会摧毁西欧特别是英国迄今为止的工业垄断地位。这两种情况反过来对美国本身也起着革命作用。作为整个政治制度基础的农场主的中小土地所有制，正逐渐被大农场的竞争所征服；同时，在各工业区，人数众多的无产阶级和神话般的资本积聚第一次发展起来了。","language":"中文","translation":false},{"id":"manifesto-1-26","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现在来看看俄国吧！在1848-1849年革命期间，不仅欧洲的君主，而且连欧洲的资产者，都把俄国的干涉看作是帮助他们对付刚刚开始觉醒的无产阶级的唯一救星。沙皇被宣布为欧洲反动势力的首领。现在，沙皇在加特契纳成了革命的俘虏[10]，而俄国已是欧洲革命运动的先进部队了。","language":"中文","translation":false},{"id":"manifesto-1-27","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《共产主义宣言》〔注：即《共产党宣言》。——编者注〕的任务，是宣告现代资产阶级所有制必然灭亡。但是在俄国，我们看见，除了迅速盛行起来的资本主义狂热和刚开始发展的资产阶级土地所有制外，大半土地仍归农民公共占有。那么试问：俄国公社，这一固然已经大遭破坏的原始土地公共占有形式，是能够直接过渡到高级的共产主义的公共占有形式呢？或者相反，它还必须先经历西方的历史发展所经历的那个瓦解过程呢？","language":"中文","translation":false},{"id":"manifesto-1-28","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"对于这个问题，目前唯一可能的答复是：假如俄国革命将成为西方无产阶级革命的信号而双方互相补充的话，那么现今的俄国土地公有制便能成为共产主义发展的起点。","language":"中文","translation":false},{"id":"manifesto-1-29","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卡尔·马克思 弗里德里希·恩格斯","language":"中文","translation":false},{"id":"manifesto-1-30","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1882年1月21日于伦敦","language":"中文","translation":false},{"id":"manifesto-1-31","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卡·马克思和弗·恩格斯写于1882年1月21日","language":"中文","translation":false},{"id":"manifesto-1-32","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"载于1882年2月5日《民意》杂志第8-9期","language":"中文","translation":false},{"id":"manifesto-1-33","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第378-379页","language":"中文","translation":false},{"id":"manifesto-1-34","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1883年德文版序言[11]","language":"中文","translation":false},{"id":"manifesto-1-35","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"本版序言不幸只能由我一个人署名了。马克思这位比其他任何人都更应受到欧美整个工人阶级感谢的人物，已经长眠于海格特公墓，他的墓上已经初次长出了青草。在他逝世以后，就更谈不上对《宣言》作什么修改或补充了。因此，我认为更有必要在这里再一次明确地申述下面这一点。","language":"中文","translation":false},{"id":"manifesto-1-36","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"贯穿《宣言》的基本思想：每一历史时代的经济生产以及必然由此产生的社会结构，是该时代政治的和精神的历史的基础；因此（从原始土地公有制解体以来）全部历史都是阶级斗争的历史，即社会发展各个阶段上被剥削阶级和剥削阶级之间、被统治阶级和统治阶级之间斗争的历史；而这个斗争现在已经达到这样一个阶段，即被剥削被压迫的阶级（无产阶级），如果不同时使整个社会永远摆脱剥削、压迫和阶级斗争，就不再能使自己从剥削它压迫它的那个阶级（资产阶级）下解放出来。——这个基本思想完全是属于马克思一个人的。〔注：恩格斯在1890年德文版转载该序言时在此处加了一个注：“我在英译本序言中说过：‘在我看来这一思想对历史学必定会起到像达尔文学说对生物学所起的那样的作用，我们两人早在1845年前的几年中就已经逐渐接近了这个思想。当时我个人独自在这方面达到什么程度，我的《英国工人阶级状况》一书就是最好的说明。但是到1845年春我在布鲁塞尔再次见到马克思时，他已经把这个思想考虑成熟，并且用几乎像我在上面所用的那样明晰的语句向我说明了。’”——编者注〕","language":"中文","translation":false},{"id":"manifesto-1-37","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这一点我已经屡次说过，但正是现在必须在《宣言》正文的前面也写明这一点。","language":"中文","translation":false},{"id":"manifesto-1-38","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1883年6月28日于伦敦","language":"中文","translation":false},{"id":"manifesto-1-39","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"弗·恩格斯写于1883年6月28日","language":"中文","translation":false},{"id":"manifesto-1-40","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"载于1883年在霍廷根-苏黎世出版的德文版《共产主义宣言》一书","language":"中文","translation":false},{"id":"manifesto-1-41","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第380-381页","language":"中文","translation":false},{"id":"manifesto-1-42","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1888年英文版序言[12]","language":"中文","translation":false},{"id":"manifesto-1-43","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《宣言》是作为共产主义者同盟 的纲领发表的，这个同盟起初纯粹是德国工人团体，后来成为国际工人团体，而在1848年以前欧洲大陆的政治条件下必然是一个秘密的团体。1847年11月在伦敦举行的同盟代表大会，委托马克思和恩格斯起草一个准备公布的完备的理论和实践的党纲。手稿于1848年1月用德文写成，并在2月24日的法国革命[3]前几星期送到伦敦付印。法译本于1848年六月起义[5]前不久在巴黎出版。第一个英译本是由海伦·麦克法林女士翻译的，于1850年刊载在乔治·朱利安·哈尼的伦敦《红色共和党人》[4]杂志上。还出版了丹麦文译本和波兰文译本。","language":"中文","translation":false},{"id":"manifesto-1-44","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1848年巴黎六月起义这一无产阶级和资产阶级间的第一次大搏斗的失败，又把欧洲工人阶级的社会的和政治的要求暂时推到后面去了。从那时起，争夺统治权的斗争，又像二月革命以前那样只是在有产阶级的各个集团之间进行了；工人阶级被迫局限于争取一些政治上的活动自由，并采取资产阶级激进派极左翼的立场。凡是继续显露出生机的独立的无产阶级运动，都遭到无情的镇压。例如，普鲁士警察发觉了当时设在科隆的共产主义者同盟中央委员会。一些成员被逮捕，并且在经过18个月监禁之后于1852年10月被交付法庭审判。这次有名的“科隆共产党人案件”[13]从10月4日一直继续到11月12日；被捕者中有七人被判处三至六年的要塞监禁。宣判之后，同盟即由剩下的成员正式解散。至于《宣言》，似乎注定从此要被人遗忘了。","language":"中文","translation":false},{"id":"manifesto-1-45","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"当欧洲工人阶级重新聚集了足以对统治阶级发动另一次进攻的力量的时候，产生了国际工人协会[14]。但是，这个协会成立的明确目的是要把欧美正在进行战斗的整个无产阶级团结为一个整体，因此，它不能立刻宣布《宣言》中所提出的那些原则。国际必须有一个充分广泛的纲领，使英国工联[15]，法国、比利时、意大利和西班牙的蒲鲁东派[16]以及德国的拉萨尔派〔注：恩格斯在这里加了一个注：“拉萨尔本人在我们面前总是自认为是马克思的学生，他作为马克思的学生是站在《宣言》的立场上的。但是他在1862-1864年期间进行的公开鼓动中，却始终没有超出靠国家贷款建立生产合作社的要求。”——编者注〕[17]都能接受。马克思起草了这个能使一切党派都满意的纲领，他对共同行动和共同讨论必然会产生的工人阶级的精神发展充满信心。反资本斗争中的种种事件和变迁——失败更甚于胜利——不能不使人们认识到他们的各种心爱的万应灵丹都不灵，并为他们更透彻地了解工人阶级解放的真正的条件开辟道路。马克思是正确的。当1874年国际解散时，工人已经全然不是1864年国际成立时的那个样子了。法国的蒲鲁东主义和德国的拉萨尔主义已经奄奄一息，甚至那些很久以前大多数已同国际决裂的保守的英国工联也渐有进步，以致去年在斯旺西，工联的主席能够用工联的名义声明说：“大陆社会主义对我们来说再不可怕了。”[18]的确，《宣言》的原则在世界各国工人中间都已传播得很广了。","language":"中文","translation":false},{"id":"manifesto-1-46","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这样，《宣言》本身又重新走上了前台。从1850年起，德文本在瑞士、英国和美国重版过数次。1872年，有人在纽约把它译成英文，并在那里的《伍德赫尔和克拉夫林周刊》[19]上发表。接着又有人根据这个英文本把它译成法文，刊载在纽约的《社会主义者报》[6]上。以后在美国又至少出现过两种多少有些损害原意的英文译本，其中一种还在英国重版过。由巴枯宁翻译的第一个俄文本约于1863年〔注：应是1869年。——编者注〕在日内瓦由赫尔岑办的《钟声》[9]印刷所出版；由英勇无畏的维拉·查苏利奇翻译的第二个俄文本[20]于1882年也在日内瓦出版。新的丹麦文译本[21]于1885年在哥本哈根作为《社会民主主义丛书》的一种出版，新的法文译本于1886年刊载在巴黎的《社会主义者报》上[22]。有人根据这个译本译成西班牙文，并于1886年在马德里发表[23]。至于德文的翻印版本，则为数极多，总共至少有12个。亚美尼亚文译本原应于几个月前在君士坦丁堡印出，但是没有问世，有人告诉我，这是因为出版人害怕在书上标明马克思的姓名，而译者又拒绝把《宣言》当做自己的作品。关于用其它文字出版的其它译本，我虽然听说过，但是没有亲眼看到。因此，《宣言》的历史在很大程度上反映着现代工人阶级运动的历史；现在，它无疑是全部社会主义文献中传播最广和最具有国际性的著作，是从西伯利亚到加利福尼亚的千百万工人公认的共同纲领。","language":"中文","translation":false},{"id":"manifesto-1-47","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"可是，当我们写这个《宣言》时，我们不能把它叫作社会主义宣言。在1847年，所谓社会主义者，一方面是指各种空想主义体系的信徒，即英国的欧文派[24]和法国的傅立叶派[25]，这两个流派都已经降到纯粹宗派的地位，并在逐渐走向灭亡；另一方面是指形形色色的社会庸医，他们凭着各种各样的补缀办法，自称要消除一切社会弊病而毫不危及资本和利润。这两种人都是站在工人阶级运动以外，宁愿向“有教养的”阶级寻求支持。只有工人阶级中确信单纯政治变革还不够而公开表明必须根本改造全部社会的那一部分人，只有他们当时把自己叫作共产主义者。这是一种粗糙的、尚欠修琢的、纯粹出于本能的共产主义；但它却接触到了最主要之点，并且在工人阶级当中已经强大到足以形成空想共产主义，在法国有卡贝的共产主义[26]，在德国有魏特林的共产主义[27]。可见，在1847年，社会主义是资产阶级的运动，而共产主义则是工人阶级的运动。当时，社会主义，至少在大陆上，是“上流社会的”，而共产主义却恰恰相反。既然我们自始就认定“工人阶级的解放应当是工人阶级自己的事情”[28]，那么，在这两个名称中间我们应该选择哪一个，就是毫无疑义的了。而且后来我们也从没有想到要把这个名称拋弃。","language":"中文","translation":false},{"id":"manifesto-1-48","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"虽然《宣言》是我们两人共同的作品，但我认为自己有责任指出，构成《宣言》核心的基本思想是属于马克思的。这个思想就是：每一历史时代主要的经济生产方式和交换方式以及必然由此产生的社会结构，是该时代政治的和精神的历史所赖以确立的基础，并且只有从这一基础出发，这一历史才能得到说明；因此人类的全部历史（从土地公有的原始氏族社会解体以来）都是阶级斗争的历史，即剥削阶级和被剥削阶级之间、统治阶级和被压迫阶级之间斗争的历史；这个阶级斗争的历史包括有一系列发展阶段，现在已经达到这样一个阶段，即被剥削被压迫的阶级（无产阶级），如果不同时使整个社会一劳永逸地摆脱任何剥削、压迫以及阶级差别和阶级斗争，就不能使自己从进行剥削和统治的那个阶级（资产阶级）的奴役下解放出来。","language":"中文","translation":false},{"id":"manifesto-1-49","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在我看来这一思想对历史学必定会起到像达尔文学说对生物学所起的那样的作用，我们两人早在1845年前的几年中就已经逐渐接近了这个思想。当时我个人独自在这方面达到什么程度，我的《英国工人阶级状况》〔注：恩格斯在这里加了一个注：“《1844年的英国工人阶级状况》，弗里德里希·恩格斯著，弗洛伦斯·凯利-威士涅威茨基译，1888年纽约-伦敦拉弗尔出版社版，威·里夫斯发行。”——编者注〕一书就是最好的说明。但是到1845年春我在布鲁塞尔再次见到马克思时，他已经把这个思想考虑成熟，并且用几乎像我在上面所用的那样明晰的语句向我说明了。","language":"中文","translation":false},{"id":"manifesto-1-50","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现在我从我们共同为1872年德文版写的序言中引录如下一段话：","language":"中文","translation":false},{"id":"manifesto-1-51","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"“不管最近25年来的情况发生了多大变化，这个《宣言》中所阐述的一般原理整个说来直到现在还是完全正确的。某些地方本来可以作一些修改。这些原理的实际运用，正如《宣言》中所说的，随时随地都要以当时的历史条件为转移，所以第二章末尾提出的那些革命措施根本没有特别的意义。如果是在今天，这一段在许多方面都会有不同的写法了。由于1848年以来大工业已有了巨大发展而工人阶级的组织也跟着有了改进和增长，由于首先有了二月革命的实际经验而后来尤其是有了无产阶级第一次掌握政权达两月之久的巴黎公社[7]的实际经验，所以这个纲领现在有些地方已经过时了。特别是公社已经证明：‘工人阶级不能简单地掌握现成的国家机器，并运用它来达到自己的目的。’（见《法兰西内战。国际工人协会总委员会宣言》伦敦1871年特鲁拉夫版第15页，那里把这个思想作了更详细的阐述。）〔注：见《马克思恩格斯选集》第3版第3卷第95页。——编者注〕其次，很明显，对于社会主义文献所作的批判在今天看来是不完全的，因为这一批判只包括到1847年为止；同样也很明显，关于共产党人对待各种反对党派的态度的论述（第四章）虽然在原则上今天还是正确的，但是就其实际运用来说今天毕竟已经过时，因为政治形势已经完全改变，当时所列举的那些党派大部分已被历史的发展彻底扫除了。","language":"中文","translation":false},{"id":"manifesto-1-52","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是《宣言》是一个历史文件，我们已没有权利来加以修改。”","language":"中文","translation":false},{"id":"manifesto-1-53","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"本版译文是由译过马克思《资本论》一书大部分的赛米尔·穆尔先生翻译的。我们共同把译文校阅过一遍，并且我还加了一些有关历史情况的注释。","language":"中文","translation":false},{"id":"manifesto-1-54","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1888年1月30日于伦敦","language":"中文","translation":false},{"id":"manifesto-1-55","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"弗·恩格斯写于1888年1月30日","language":"中文","translation":false},{"id":"manifesto-1-56","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"载于1888年在伦敦出版的英文版《共产主义宣言》一书","language":"中文","translation":false},{"id":"manifesto-1-57","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第382-387页","language":"中文","translation":false},{"id":"manifesto-1-58","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1890年德文版序言[29]","language":"中文","translation":false},{"id":"manifesto-1-59","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"自从我写了上面那篇序言〔注：指1883年德文版序言，见本书第7-8页。——编者注〕以来，又需要刊印《宣言》的新的德文版本了，同时《宣言》本身也有种种遭遇，应该在这里提一提。","language":"中文","translation":false},{"id":"manifesto-1-60","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1882年在日内瓦出版了由维拉·查苏利奇翻译的第二个俄文本[20]，马克思和我曾为这个译本写过一篇序言。可惜我把这篇序言的德文原稿遗失了[30]，所以现在我只好再从俄文译过来，这样做当然不会使原稿增色。下面就是这篇序言：","language":"中文","translation":false},{"id":"manifesto-1-61","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"“巴枯宁翻译的《共产党宣言》俄文第一版，60年代初〔注：应是1869年。——编者注〕由《钟声》[9]印刷所出版。当时西方认为《宣言》译成俄文出版不过是著作界的一件奇闻。这种看法今天是不可能有了。在《宣言》最初发表时期（1848年1月）卷入无产阶级运动的地区是多么狭小，这从《宣言》最后一章《共产党人对各种反对党派的态度》中可以看得很清楚。在这一章里，首先没有说到俄国和美国。那时，俄国是欧洲反动势力的最后一支庞大后备军；向美国境内移民吸收着欧洲无产阶级的过剩力量。这两个国家，都向欧洲提供原料，同时又都是欧洲工业品的销售市场。所以，这两个国家不管怎样当时都是欧洲现存秩序的支柱。","language":"中文","translation":false},{"id":"manifesto-1-62","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"今天，情况完全不同了！正是欧洲移民，使北美的农业生产能够大大发展，这种发展通过竞争震撼着欧洲大小土地所有制的根基。此外，这种移民还使美国能够以巨大的力量和规模开发其丰富的工业资源，以至于很快就会摧毁西欧的工业垄断地位。这两种情况反过来对美国本身也起着革命作用。作为美国整个政治制度基础的自耕农场主的中小土地所有制，正逐渐被大农场的竞争所征服；同时，在各工业区，人数众多的无产阶级和神话般的资本积聚第一次发展起来了。","language":"中文","translation":false},{"id":"manifesto-1-63","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现在来看看俄国吧！在1848-1849年革命期间，不仅欧洲的君主，而且连欧洲的资产者，都把俄国的干涉看做是帮助他们对付当时刚刚开始意识到自己力量的无产阶级的唯一救星。他们把沙皇宣布为欧洲反动势力的首领。现在，沙皇在加特契纳已成了革命的俘虏[10]，而俄国已是欧洲革命运动的先进部队了。","language":"中文","translation":false},{"id":"manifesto-1-64","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《共产主义宣言》〔注：即《共产党宣言》。——编者注〕的任务，是宣告现代资产阶级所有制必然灭亡。但是在俄国，我们看见，除了狂热发展的资本主义制度和刚开始形成的资产阶级土地所有制外，大半土地仍归农民公共占有。","language":"中文","translation":false},{"id":"manifesto-1-65","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"那么试问：俄国农民公社，这一固然已经大遭破坏的原始土地公有制形式，是能直接过渡到高级的共产主义的土地所有制形式呢？或者，它还必须先经历西方的历史发展所经历的那个瓦解过程呢？","language":"中文","translation":false},{"id":"manifesto-1-66","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"对于这个问题，目前唯一可能的答复是：假如俄国革命将成为西方工人革命的信号而双方互相补充的话，那么现今的俄国公有制便能成为共产主义发展的起点。","language":"中文","translation":false},{"id":"manifesto-1-67","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1882年1月21日于伦敦”","language":"中文","translation":false},{"id":"manifesto-1-68","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"大约在同一时候，在日内瓦出版了新的波兰文译本：《共产主义宣言》〔注：即《共产党宣言》。——编者注〕。","language":"中文","translation":false},{"id":"manifesto-1-69","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"随后又于1885年在哥本哈根作为《社会民主主义丛书》的一种出版了新的丹麦文译本。可惜这一译本不够完备；有几个重要的地方大概是因为译者感到难译而被删掉了，并且有些地方可以看到草率从事的痕迹，尤其令人遗憾的是，从译文中可以看出，要是译者细心一点，他是能够译得很好的。","language":"中文","translation":false},{"id":"manifesto-1-70","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1886年在巴黎《社会主义者报》上刊载了新的法译文；这是到目前为止最好的译文。[22]","language":"中文","translation":false},{"id":"manifesto-1-71","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"同年又有人根据这个法文本译成西班牙文，起初刊登在马德里的《社会主义者报》上[23]，接着又印成单行本：《共产党宣言》，卡·马克思和弗·恩格斯著，马德里，社会主义者报社，埃尔南·科尔特斯街8号。","language":"中文","translation":false},{"id":"manifesto-1-72","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这里我还要提到一件奇怪的事。1887年，君士坦丁堡的一位出版商收到了亚美尼亚文的《宣言》译稿；但是这位好心人却没有勇气把这本署有马克思的名字的作品刊印出来，竟认为最好是由译者本人冒充作者，可是译者拒绝这样做。","language":"中文","translation":false},{"id":"manifesto-1-73","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在英国多次刊印过好几种美国译本，但都不大确切。到1888年终于出版了一种可靠的译本。这个译本是由我的友人赛米尔·穆尔翻译的，并且在付印以前还由我们两人一起重新校阅过一遍。标题是：《共产党宣言》，卡尔·马克思和弗里德里希·恩格斯著。经作者认可的英译本，由弗里德里希·恩格斯校订并加注，1888年伦敦，威廉·里夫斯，东中央区弗利特街185号。这个版本中的某些注释，我已收入本版。","language":"中文","translation":false},{"id":"manifesto-1-74","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《宣言》有它本身的经历。它出现的时候曾受到当时人数尚少的科学社会主义先锋队的热烈欢迎（第一篇序言里提到的那些译本便可以证明这一点），但是不久它就被随着1848年6月巴黎工人失败[5]而抬起头来的反动势力排挤到后台去了，最后，由于1852年11月科隆共产党人被判刑[13]，它被“依法”宣布为非法。随着由二月革命[3]开始的工人运动退出公开舞台，《宣言》也退到后台去了。","language":"中文","translation":false},{"id":"manifesto-1-75","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"当欧洲工人阶级又强大到足以对统治阶级政权发动另一次进攻的时候，产生了国际工人协会[14]。它的目的是要把欧美整个战斗的工人阶级联合成一支大军。因此，它不能从《宣言》中提出的那些原则出发。它必须有一个不致把英国工联[15]，法国、比利时、意大利和西班牙的蒲鲁东派[16]以及德国的拉萨尔派〔注：恩格斯在这里加了一个注：“拉萨尔本人在我们面前总是自认为是马克思的‘学生’，他作为马克思的‘学生’当然是站在《宣言》的立场上的。但是他的那些信徒却不是如此，他们始终没有超出他所主张的靠国家贷款建立生产合作社的要求，并且把整个工人阶级划分为国家帮助派和自助派。”——编者注〕[17]拒之于门外的纲领。这样一个纲领即国际章程绪论部分，是马克思起草的，其行文之巧妙连巴枯宁和无政府主义者也不能不承认。至于说到《宣言》中所提出的那些原则的最终胜利，马克思把希望完全寄托于共同行动和讨论必然会产生的工人阶级的精神的发展。反资本斗争中的种种事件和变迁——失败更甚于胜利——不能不使进行斗争的人们明白自己一向所崇奉的那些万应灵丹都不灵，并使他们的头脑更容易透彻地了解工人解放的真正的条件。马克思是正确的。1874年，当国际解散的时候，工人阶级已经全然不是1864年国际成立时的那个样子了。罗曼语各国的蒲鲁东主义和德国特有的拉萨尔主义已经奄奄一息，甚至当时极端保守的英国工联也渐有进步，以致1887年在斯温西，工联代表大会的主席能够用工联的名义声明说：“大陆社会主义对我们来说再不可怕了。”[18]而在1887年，大陆社会主义已经差不多完全是《宣言》中所宣布的那个理论了。因此，《宣言》的历史在某种程度上反映着1848年以来现代工人运动的历史。现在，它无疑是全部社会主义文献中传播最广和最具有国际性的著作，是从西伯利亚到加利福尼亚的所有国家的千百万工人的共同纲领。","language":"中文","translation":false},{"id":"manifesto-1-76","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"可是，当《宣言》出版的时候，我们不能把它叫做社会主义宣言。在1847年，所谓社会主义者是指两种人。一方面是指各种空想主义体系的信徒，特别是英国的欧文派[24]和法国的傅立叶派[25]，这两个流派当时都已经缩小成逐渐走向灭亡的纯粹的宗派。另一方面是指形形色色的社会庸医，他们想用各种万应灵丹和各种补缀办法来消除社会弊病而毫不伤及资本和利润。这两种人都是站在工人运动以外，宁愿向“有教养的”阶级寻求支持。相反，当时确信单纯政治变革还不够而要求根本改造社会的那一部分工人，则把自己叫做共产主义者。这是一种还没有很好加工的、只是出于本能的、往往有些粗陋的共产主义；但它已经强大到足以形成两种空想的共产主义体系：在法国有卡贝的“伊加利亚”共产主义[26]，在德国有魏特林的共产主义[27]。在1847年，社会主义意味着资产阶级的运动，共产主义则意味着工人的运动。当时，社会主义，至少在大陆上，是上流社会的，而共产主义却恰恰相反。既然我们当时已经十分坚决地认定“工人的解放应当是工人阶级自己的事情”[28]，所以我们一刻也不怀疑究竟应该在这两个名称中间选定哪一个名称。而且后来我们也根本没有想到要把这个名称拋弃。","language":"中文","translation":false},{"id":"manifesto-1-77","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"“全世界无产者，联合起来！”当42年前我们在巴黎革命即无产阶级带着自己的要求参加的第一次革命的前夜向世界上发出这个号召时，响应者还是寥寥无几。可是，1864年9月28日，大多数西欧国家中的无产者已经联合成为流芳百世的国际工人协会了。固然，国际本身只存在了九年，但它所创立的全世界无产者永久的联合依然存在，并且比任何时候更加强固，而今天这个日子就是最好的证明。因为今天我写这个序言的时候，欧美无产阶级正在检阅自己第一次动员起来的战斗力量，他们动员起来，组成一支大军，在一个旗帜下，为了一个最近的目的，即早已由国际1866年日内瓦代表大会宣布、后来又由1889年巴黎工人代表大会再度宣布的在法律上确立八小时正常工作日[31]。今天的情景将会使全世界的资本家和地主看到：全世界的无产者现在真正联合起来了。","language":"中文","translation":false},{"id":"manifesto-1-78","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"如果马克思今天还能同我站在一起亲眼看见这种情景，那该多好啊！","language":"中文","translation":false},{"id":"manifesto-1-79","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1890年5月1日于伦敦","language":"中文","translation":false},{"id":"manifesto-1-80","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"弗·恩格斯写于1890年5月1日","language":"中文","translation":false},{"id":"manifesto-1-81","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"载于1890年在伦敦出版的德文版《共产主义宣言》一书","language":"中文","translation":false},{"id":"manifesto-1-82","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第388-393页","language":"中文","translation":false},{"id":"manifesto-1-83","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1892年波兰文版序言[32]","language":"中文","translation":false},{"id":"manifesto-1-84","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"目前已有必要出版《共产主义宣言》〔注：即《共产党宣言》。——编者注〕波兰文新版本这一事实，可以引起许多联想。","language":"中文","translation":false},{"id":"manifesto-1-85","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"首先值得注意的是，近来《宣言》在某种程度上已经成为测量欧洲大陆大工业发展的一种尺度。某一国家的大工业越发展，该国工人想要弄清他们作为工人阶级在有产阶级面前所处地位的愿望也就越强烈，工人中间的社会主义运动也就越扩大，对《宣言》的需求也就越增长。因此，根据《宣言》用某国文字发行的份数，不仅可以相当准确地判断该国工人运动的状况，而且可以相当准确地判断该国大工业发展的程度。","language":"中文","translation":false},{"id":"manifesto-1-86","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，《宣言》波兰文新版本，标志着波兰工业的重大发展。而且从10年前上一版问世以来确实已有这种发展，这是丝毫不容置疑的。俄罗斯的波兰，会议桌上的波兰[33]，已成为俄罗斯帝国的巨大的工业区。俄国的大工业分散于各处，一部分在芬兰湾沿岸，一部分在中央区（莫斯科和弗拉基米尔），一部分在黑海和亚速海沿岸，还有一些分散在其他地方；波兰的大工业则集中于一个比较狭小的地区，这种集中所产生的益处和害处，它都感受到了。这种益处是竞争对手俄国工厂主所承认的，他们虽然拼命想把波兰人变成俄罗斯人，同时却要求实行对付波兰的保护关税。至于这种害处，即对波兰工厂主和俄国政府的害处，则表现为社会主义思想在波兰工人中间的迅速传播和对《宣言》的需求日益增长。","language":"中文","translation":false},{"id":"manifesto-1-87","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，波兰工业的迅速发展（它已经超过了俄国工业），又是波兰人民拥有强大生命力的新的证明，是波兰人民即将达到民族复兴的新的保证。而一个独立强盛的波兰的复兴是一件不仅关系到波兰人而且关系到我们大家的事情。欧洲各民族的真诚的国际合作，只有当每个民族自己完全当家作主的时候才能实现。1848年革命在无产阶级的旗帜下使无产阶级战士归根到底只是做了资产阶级的工作，这次革命也通过自己的遗嘱执行人[34]路易·波拿巴和俾斯麦实现了意大利、德国和匈牙利的独立。至于波兰，虽然它从1792年以来对革命所作的贡献比这三个国家所作的全部贡献还要大，可是它于1863年在十倍于自己的俄国优势下失败的时候，却被拋弃不管了。波兰贵族既没有能够保持住波兰独立，也没有能够重新争得波兰独立；在资产阶级看来，波兰独立在今天至少是一件无关痛痒的事情。然而这种独立却是实现欧洲各民族和谐的合作所必需的。这种独立只有年轻的波兰无产阶级才能争得，而且在波兰无产阶级手里会很好地保持住。因为欧洲所有其余各国工人都像波兰工人本身一样需要波兰的独立。","language":"中文","translation":false},{"id":"manifesto-1-88","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1892年2月10日于伦敦","language":"中文","translation":false},{"id":"manifesto-1-89","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"弗·恩格斯写于1892年2月10日","language":"中文","translation":false},{"id":"manifesto-1-90","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"载于1892年2月27日《黎明》杂志第35期","language":"中文","translation":false},{"id":"manifesto-1-91","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第394-395页","language":"中文","translation":false},{"id":"manifesto-1-92","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1893年意大利文版序言[35]","language":"中文","translation":false},{"id":"manifesto-1-93","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《共产党宣言》的发表，可以说正好碰上1848年3月18日这个日子，碰上米兰和柏林发生革命，这是两个民族的武装起义[36]，其中一个处于欧洲大陆中心，另一个处于地中海各国中心；这两个民族在此以前都由于分裂和内部纷争而被削弱并因而遭到外族的统治。意大利受奥皇支配，而德国则受到俄国沙皇那种虽然不那么直接，但是同样可以感觉得到的压迫。1848年3月18日的结果使意大利和德国免除了这种耻辱；如果说，这两个伟大民族在1848-1871年期间得到复兴并以这种或那种形式重新获得独立，那么，这是因为，正如马克思所说，那些镇压1848年革命的人违反自己的意志充当了这次革命的遗嘱执行人。[34]","language":"中文","translation":false},{"id":"manifesto-1-94","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这次革命到处都是由工人阶级干的；构筑街垒和流血牺牲的都是工人阶级。只有巴黎工人在推翻政府的同时也抱有推翻资产阶级统治的明确意图。但是，虽然他们已经认识到他们这个阶级和资产阶级之间存在着不可避免的对抗，然而无论法国经济的进展或法国工人群众的精神的发展，都还没有达到可能实现社会改造的程度。因此，革命的果实最终必然被资本家阶级拿去。在其他国家，在意大利、德国、奥地利，工人从一开始就只限于帮助资产阶级取得政权。但是在任何国家，资产阶级的统治离开民族独立都是不行的。因此，1848年革命必然给那些直到那时还没有统一和独立的那些民族——意大利、德国、匈牙利——带来统一和独立。现在轮到波兰了。","language":"中文","translation":false},{"id":"manifesto-1-95","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"由此可见，1848年革命虽然不是社会主义革命，但它毕竟为社会主义革命扫清了道路，为这个革命准备了基础。最近45年来，资产阶级制度在各国引起了大工业的飞速发展，同时造成了人数众多的、紧密团结的、强大的无产阶级；这样它就产生了——正如《宣言》所说——它自身的掘墓人。不恢复每个民族的独立和统一，那就既不可能有无产阶级的国际联合，也不可能有各民族为达到共同目的而必须实行的和睦的与自觉的合作。试想想看，在1848年以前的政治条件下，哪能有意大利工人、匈牙利工人、德意志工人、波兰工人、俄罗斯工人的共同国际行动！","language":"中文","translation":false},{"id":"manifesto-1-96","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"可见，1848年的战斗并不是白白进行的。从这个革命时期起直到今日的这45年，也不是白白过去的。这个革命时期的果实已开始成熟，而我的唯一愿望是这个意大利文译本的出版能成为良好的预兆，成为意大利无产阶级胜利的预兆，如同《宣言》原文的出版成了国际革命的预兆一样。","language":"中文","translation":false},{"id":"manifesto-1-97","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《宣言》十分公正地评价了资本主义在先前所起过的革命作用。意大利是第一个资本主义民族。封建的中世纪的终结和现代资本主义纪元的开端，是以一位大人物为标志的。这位人物就是意大利人但丁，他是中世纪的最后一位诗人，同时又是新时代的最初一位诗人。现在也如1300年那样，新的历史纪元正在到来。意大利是否会给我们一个新的但丁来宣告这个无产阶级新纪元的诞生呢？","language":"中文","translation":false},{"id":"manifesto-1-98","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1893年2月1日于伦敦","language":"中文","translation":false},{"id":"manifesto-1-99","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"弗·恩格斯写于1893年1月31日-2月1日","language":"中文","translation":false},{"id":"manifesto-1-100","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"载于1893年在米兰出版的意大利文版《共产党宣言》一书","language":"中文","translation":false},{"id":"manifesto-1-101","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第396-398页","language":"中文","translation":false},{"id":"manifesto-1-102","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"一个幽灵，共产主义的幽灵，在欧洲游荡。为了对这个幽灵进行神圣的围剿，旧欧洲的一切势力，教皇和沙皇、梅特涅和基佐、法国的激进派和德国的警察，都联合起来了。","language":"中文","translation":false},{"id":"manifesto-1-103","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"有哪一个反对党不被它的当政的敌人骂为共产党呢？又有哪一个反对党不拿共产主义这个罪名去回敬更进步的反对党人和自己的反动敌人呢？","language":"中文","translation":false},{"id":"manifesto-1-104","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"从这一事实中可以得出两个结论：","language":"中文","translation":false},{"id":"manifesto-1-105","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产主义已经被欧洲的一切势力公认为一种势力；","language":"中文","translation":false},{"id":"manifesto-1-106","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现在是共产党人向全世界公开说明自己的观点、自己的目的、自己的意图并且拿党自己的宣言来反驳关于共产主义幽灵的神话的时候了。","language":"中文","translation":false},{"id":"manifesto-1-107","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"为了这个目的，各国共产党人集会于伦敦，拟定了如下的宣言，用英文、法文、德文、意大利文、佛拉芒文和丹麦文公布于世。","language":"中文","translation":false},{"id":"manifesto-1-108","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"〔注：恩格斯在1888年英文版上加了一个注：“资产阶级是指占有社会生产资料并使用雇佣劳动的现代资本家阶级。无产阶级是指没有自己的生产资料，因而不得不靠出卖劳动力来维持生活的现代雇佣工人阶级。”——编者注〕","language":"中文","translation":false},{"id":"manifesto-1-109","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"至今一切社会的历史〔注：恩格斯在1888年英文版上加了一个注：“这是指有文字记载的全部历史。在1847年，社会的史前史、成文史以前的社会组织，几乎还没有人知道。后来，哈克斯特豪森发现了俄国的土地公有制，毛勒证明了这种公有制是一切条顿族的历史起源的社会基础，而且人们逐渐发现，农村公社是或者曾经是从印度到爱尔兰的各地社会的原始形态。最后，摩尔根发现了氏族的真正本质及其对部落的关系，这一卓绝发现把这种原始共产主义社会的内部组织的典型形式揭示出来了。随着这种原始公社的解体，社会开始分裂为各个独特的、终于彼此对立的阶级。关于这个解体过程，我曾经试图在《家庭、私有制和国家的起源》（1886年斯图加特第2版）中加以探讨。”——编者注〕都是阶级斗争的历史。","language":"中文","translation":false},{"id":"manifesto-1-110","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"自由民和奴隶、贵族和平民、领主和农奴、行会师傅〔注：恩格斯在1888年英文版上加了一个注：“行会师傅就是在行会中享有全权的会员，是行会内部的师傅，而不是行会的首领。”——编者注〕和帮工，一句话，压迫者和被压迫者，始终处于相互对立的地位，进行不断的、有时隐蔽有时公开的斗争，而每一次斗争的结局都是整个社会受到革命改造或者斗争的各阶级同归于尽。","language":"中文","translation":false},{"id":"manifesto-1-111","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在过去的各个历史时代，我们几乎到处都可以看到社会完全划分为各个不同的等级，看到社会地位分成的多种多样的层次。在古罗马，有贵族、骑士、平民、奴隶，在中世纪，有封建主、臣仆、行会师傅、帮工、农奴，而且几乎在每一个阶级内部又有一些特殊的阶层。","language":"中文","translation":false},{"id":"manifesto-1-112","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"从封建社会的灭亡中产生出来的现代资产阶级社会并没有消灭阶级对立。它只是用新的阶级、新的压迫条件、新的斗争形式代替了旧的。","language":"中文","translation":false},{"id":"manifesto-1-113","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，我们的时代，资产阶级时代，却有一个特点：它使阶级对立简单化了。整个社会日益分裂为两大敌对的阵营，分裂为两大相互直接对立的阶级：资产阶级和无产阶级。","language":"中文","translation":false},{"id":"manifesto-1-114","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"从中世纪的农奴中产生了初期城市的城关市民；从这个市民等级中发展出最初的资产阶级分子。","language":"中文","translation":false},{"id":"manifesto-1-115","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"美洲的发现、绕过非洲的航行，给新兴的资产阶级开辟了新天地。东印度和中国的市场、美洲的殖民化、对殖民地的贸易、交换手段和一般商品的增加，使商业、航海业和工业空前高涨，因而使正在崩溃的封建社会内部的革命因素迅速发展。","language":"中文","translation":false},{"id":"manifesto-1-116","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"以前那种封建的或行会的工业经营方式已经不能满足随着新市场的出现而增加的需求了。工场手工业代替了这种经营方式。行会师傅被工业的中间等级排挤掉了；各种行业组织之间的分工随着各个作坊内部的分工的出现而消失了。","language":"中文","translation":false},{"id":"manifesto-1-117","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，市场总是在扩大，需求总是在增加。甚至工场手工业也不再能满足需要了。于是，蒸汽和机器引起了工业生产的革命。现代大工业代替了工场手工业；工业中的百万富翁、一支一支产业大军的首领、现代资产者，代替了工业的中间等级。","language":"中文","translation":false},{"id":"manifesto-1-118","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"大工业建立了由美洲的发现所准备好的世界市场。世界市场使商业、航海业和陆路交通得到了巨大的发展。这种发展又反过来促进了工业的扩展，同时，随着工业、商业、航海业和铁路的扩展，资产阶级也在同一程度上发展起来，增加自己的资本，把中世纪遗留下来的一切阶级排挤到后面去。","language":"中文","translation":false},{"id":"manifesto-1-119","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"由此可见，现代资产阶级本身是一个长期发展过程的产物，是生产方式和交换方式的一系列变革的产物。","language":"中文","translation":false},{"id":"manifesto-1-120","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级的这种发展的每一个阶段，都伴随着相应的政治上的进展〔注：“相应的政治上的进展”在1888年英文版中是“这个阶级的相应的政治上的进展”。——编者注〕。它在封建主统治下是被压迫的等级，在公社〔注：恩格斯在1888年英文版上加了一个注：“法国的新兴城市，甚至在它们从封建主手里争得地方自治和‘第三等级’的政治权利以前，就已经称为‘公社’了。一般说来，这里是把英国当做资产阶级经济发展的典型国家，而把法国当做资产阶级政治发展的典型国家。”恩格斯在1890年德文版上加了一个注：“意大利和法国的市民，从他们的封建主手中买得或争得最初的自治权以后，就把自己的城市共同体称为‘公社’。”——编者注〕里是武装的和自治的团体，在一些地方组成独立的城市共和国〔注：在1888年英文版中这里加上了“（例如在意大利和德国）”。——编者注〕，在另一些地方组成君主国中的纳税的第三等级〔注：在1888年英文版中这里加上了“（例如在法国）”。——编者注〕；后来，在工场手工业时期，它是等级君主国〔注：“等级君主国”在1888年英文版中是“半封建君主国”。——编者注〕或专制君主国中同贵族抗衡的势力，而且是大君主国的主要基础；最后，从大工业和世界市场建立的时候起，它在现代的代议制国家里夺得了独占的政治统治。现代的国家政权不过是管理整个资产阶级的共同事务的委员会罢了。","language":"中文","translation":false},{"id":"manifesto-1-121","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级在历史上曾经起过非常革命的作用。","language":"中文","translation":false},{"id":"manifesto-1-122","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级在它已经取得了统治的地方把一切封建的、宗法的和田园诗般的关系都破坏了。它无情地斩断了把人们束缚于天然尊长的形形色色的封建羁绊，它使人和人之间除了赤裸裸的利害关系，除了冷酷无情的“现金交易”，就再也没有任何别的联系了。它把宗教虔诚、骑士热忱、小市民伤感这些情感的神圣发作，淹没在利己主义打算的冰水之中。它把人的尊严变成了交换价值，用一种没有良心的贸易自由代替了无数特许的和自力挣得的自由。总而言之，它用公开的、无耻的、直接的、露骨的剥削代替了由宗教幻想和政治幻想掩盖着的剥削。","language":"中文","translation":false},{"id":"manifesto-1-123","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级抹去了一切向来受人尊崇和令人敬畏的职业的神圣光环。它把医生、律师、教士、诗人和学者变成了它出钱招雇的雇佣劳动者。","language":"中文","translation":false},{"id":"manifesto-1-124","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级撕下了罩在家庭关系上的温情脉脉的面纱，把这种关系变成了纯粹的金钱关系。","language":"中文","translation":false},{"id":"manifesto-1-125","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级揭示了，在中世纪深受反动派称许的那种人力的野蛮使用，是以极端怠惰作为相应补充的。它第一个证明了，人的活动能够取得什么样的成就。它创造了完全不同于埃及金字塔、罗马水道和哥特式教堂的奇迹；它完成了完全不同于民族大迁徙[37]和十字军征讨[38]的远征。","language":"中文","translation":false},{"id":"manifesto-1-126","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级除非对生产工具，从而对生产关系，从而对全部社会关系不断地进行革命，否则就不能生存下去。反之，原封不动地保持旧的生产方式，却是过去的一切工业阶级生存的首要条件。生产的不断变革，一切社会状况不停的动荡，永远的不安定和变动，这就是资产阶级时代不同于过去一切时代的地方。一切固定的僵化的关系以及与之相适应的素被尊崇的观念和见解都被消除了，一切新形成的关系等不到固定下来就陈旧了。一切等级的和固定的东西都烟消云散了，一切神圣的东西都被亵渎了。人们终于不得不用冷静的眼光来看他们的生活地位、他们的相互关系。","language":"中文","translation":false},{"id":"manifesto-1-127","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"不断扩大产品销路的需要，驱使资产阶级奔走于全球各地。它必须到处落户，到处开发，到处建立联系。","language":"中文","translation":false},{"id":"manifesto-1-128","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级，由于开拓了世界市场，使一切国家的生产和消费都成为世界性的了。使反动派大为惋惜的是，资产阶级挖掉了工业脚下的民族基础。古老的民族工业被消灭了，并且每天都还在被消灭。它们被新的工业排挤掉了，新的工业的建立已经成为一切文明民族的生命攸关的问题；这些工业所加工的，已经不是本地的原料，而是来自极其遥远的地区的原料；它们的产品不仅供本国消费，而且同时供世界各地消费。旧的、靠本国产品来满足的需要，被新的、要靠极其遥远的国家和地带的产品来满足的需要所代替了。过去那种地方的和民族的自给自足和闭关自守状态，被各民族的各方面的互相往来和各方面的互相依赖所代替了。物质的生产是如此，精神的生产也是如此。各民族的精神产品成了公共的财产。民族的片面性和局限性日益成为不可能，于是由许多种民族的和地方的文学形成了一种世界的文学〔注：“文学”一词德文是“Literatur”，这里泛指科学、艺术、哲学、政治等等方面的著作。——编者注〕。","language":"中文","translation":false},{"id":"manifesto-1-129","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级，由于一切生产工具的迅速改进，由于交通的极其便利，把一切民族甚至最野蛮的民族都卷到文明中来了。它的商品的低廉价格，是它用来摧毁一切万里长城、征服野蛮人最顽强的仇外心理的重炮。它迫使一切民族——如果它们不想灭亡的话——采用资产阶级的生产方式；它迫使它们在自己那里推行所谓的文明，即变成资产者。一句话，它按照自己的面貌为自己创造出一个世界。","language":"中文","translation":false},{"id":"manifesto-1-130","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级使农村屈服于城市的统治。它创立了巨大的城市，使城市人口比农村人口大大增加起来，因而使很大一部分居民脱离了农村生活的愚昧状态。正像它使农村从属于城市一样，它使未开化和半开化的国家从属于文明的国家，使农民的民族从属于资产阶级的民族，使东方从属于西方。","language":"中文","translation":false},{"id":"manifesto-1-131","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级日甚一日地消灭生产资料、财产和人口的分散状态。它使人口密集起来，使生产资料集中起来，使财产聚集在少数人的手里。由此必然产生的结果就是政治的集中。各自独立的、几乎只有同盟关系的、各有不同利益、不同法律、不同政府、不同关税的各个地区，现在已经结合为一个拥有统一的政府、统一的法律、统一的民族阶级利益和统一的关税的统一的民族。","language":"中文","translation":false},{"id":"manifesto-1-132","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。自然力的征服，机器的采用，化学在工业和农业中的应用，轮船的行驶，铁路的通行，电报的使用，整个整个大陆的开垦，河川的通航，仿佛用法术从地下呼唤出来的大量人口——过去哪一个世纪料想到在社会劳动里蕴藏有这样的生产力呢？","language":"中文","translation":false},{"id":"manifesto-1-133","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"由此可见，资产阶级赖以形成的生产资料和交换手段，是在封建社会里造成的。在这些生产资料和交换手段发展的一定阶段上，封建社会的生产和交换在其中进行的关系，封建的农业和工场手工业组织，一句话，封建的所有制关系，就不再适应已经发展的生产力了。这种关系已经在阻碍生产而不是促进生产了。它变成了束缚生产的桎梏。它必须被炸毁，它已经被炸毁了。","language":"中文","translation":false},{"id":"manifesto-1-134","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"起而代之的是自由竞争以及与自由竞争相适应的社会制度和政治制度、资产阶级的经济统治和政治统治。","language":"中文","translation":false},{"id":"manifesto-1-135","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现在，我们眼前又进行着类似的运动。资产阶级的生产关系和交换关系，资产阶级的所有制关系，这个曾经仿佛用法术创造了如此庞大的生产资料和交换手段的现代资产阶级社会，现在像一个魔法师一样不能再支配自己用法术呼唤出来的魔鬼了。几十年来的工业和商业的历史，只不过是现代生产力反抗现代生产关系、反抗作为资产阶级及其统治的存在条件的所有制关系的历史。只要指出在周期性的重复中越来越危及整个资产阶级社会生存的商业危机就够了。在商业危机期间，总是不仅有很大一部分制成的产品被毁灭掉，而且有很大一部分已经造成的生产力被毁灭掉。在危机期间，发生一种在过去一切时代看来都好像是荒唐现象的社会瘟疫，即生产过剩的瘟疫。社会突然发现自己回到了一时的野蛮状态；仿佛是一次饥荒、一场普遍的毁灭性战争，使社会失去了全部生活资料；仿佛是工业和商业全被毁灭了。这是什么缘故呢？因为社会上文明过度，生活资料太多，工业和商业太发达。社会所拥有的生产力已经不能再促进资产阶级文明和资产阶级所有制关系的发展；相反，生产力已经强大到这种关系所不能适应的地步，它已经受到这种关系的阻碍；而它一着手克服这种障碍，就使整个资产阶级社会陷入混乱，就使资产阶级所有制的存在受到威胁。资产阶级的关系已经太狭窄了，再容纳不了它本身所造成的财富了。资产阶级用什么办法来克服这种危机呢？一方面不得不消灭大量生产力，另一方面夺取新的市场，更加彻底地利用旧的市场。这究竟是怎样的一种办法呢？这不过是资产阶级准备更全面更猛烈的危机的办法，不过是使防止危机的手段越来越少的办法。","language":"中文","translation":false},{"id":"manifesto-1-136","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级用来推翻封建制度的武器，现在却对准资产阶级自己了。","language":"中文","translation":false},{"id":"manifesto-1-137","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，资产阶级不仅锻造了置自身于死地的武器；它还产生了将要运用这种武器的人——现代的工人，即无产者。","language":"中文","translation":false},{"id":"manifesto-1-138","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"随着资产阶级即资本的发展，无产阶级即现代工人阶级也在同一程度上得到发展；现代的工人只有当他们找到工作的时候才能生存，而且只有当他们的劳动增殖资本的时候才能找到工作。这些不得不把自己零星出卖的工人，像其他任何货物一样，也是一种商品，所以他们同样地受到竞争的一切变化、市场的一切波动的影响。","language":"中文","translation":false},{"id":"manifesto-1-139","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"由于推广机器和分工，无产者的劳动已经失去了任何独立的性质，因而对工人也失去了任何吸引力。工人变成了机器的单纯的附属品，要求他做的只是极其简单、极其单调和极容易学会的操作。因此，花在工人身上的费用，几乎只限于维持工人生活和延续工人后代所必需的生活资料。但是，商品的价格，从而劳动的价格[39]，是同它的生产费用相等的。因此，劳动越使人感到厌恶，工资也就越减少。不仅如此，机器越推广，分工越细致，劳动量〔注：“劳动量”在1888年英文版中是“劳动负担”。——编者注〕也就越增加，这或者是由于工作时间的延长，或者是由于在一定时间内所要求的劳动的增加，机器运转的加速，等等。","language":"中文","translation":false},{"id":"manifesto-1-140","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现代工业已经把家长式的师傅的小作坊变成了工业资本家的大工厂。挤在工厂里的工人群众就像士兵一样被组织起来。他们是产业军的普通士兵，受着各级军士和军官的层层监视。他们不仅仅是资产阶级的、资产阶级国家的奴隶，他们每日每时都受机器、受监工、首先是受各个经营工厂的资产者本人的奴役。这种专制制度越是公开地把营利宣布为自己的最终目的，它就越是可鄙、可恨和可恶。","language":"中文","translation":false},{"id":"manifesto-1-141","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"手的操作所要求的技巧和气力越少，换句话说，现代工业越发达，男工也就越受到女工和童工的排挤。对工人阶级来说，性别和年龄的差别再没有什么社会意义了。他们都只是劳动工具，不过因为年龄和性别的不同而需要不同的费用罢了。","language":"中文","translation":false},{"id":"manifesto-1-142","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"当厂主对工人的剥削告一段落，工人领到了用现钱支付的工资的时候，马上就有资产阶级中的另一部分人——房东、小店主、当铺老板等等向他们扑来。","language":"中文","translation":false},{"id":"manifesto-1-143","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"以前的中间等级的下层，即小工业家、小商人和小食利者，手工业者和农民——所有这些阶级都降落到无产阶级的队伍里来了，有的是因为他们的小资本不足以经营大工业，经不起较大的资本家的竞争；有的是因为他们的手艺已经被新的生产方法弄得不值钱了。无产阶级就是这样从居民的所有阶级中得到补充的。","language":"中文","translation":false},{"id":"manifesto-1-144","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"无产阶级经历了各个不同的发展阶段。它反对资产阶级的斗争是和它的存在同时开始的。","language":"中文","translation":false},{"id":"manifesto-1-145","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"最初是单个的工人，然后是某一工厂的工人，然后是某一地方的某一劳动部门的工人，同直接剥削他们的单个资产者作斗争。他们不仅仅攻击资产阶级的生产关系，而且攻击生产工具本身〔注：这句话在1888年英文版中是“他们不是攻击资产阶级的生产关系，而是攻击生产工具本身”。——编者注〕；他们毁坏那些来竞争的外国商品，捣毁机器，烧毁工厂，力图恢复已经失去的中世纪工人的地位。","language":"中文","translation":false},{"id":"manifesto-1-146","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在这个阶段上，工人们是分散在全国各地并为竞争所分裂的群众。工人的大规模集结，还不是他们自己联合的结果，而是资产阶级联合的结果，当时资产阶级为了达到自己的政治目的必须而且暂时还能够把整个无产阶级发动起来。因此，在这个阶段上，无产者不是同自己的敌人作斗争，而是同自己的敌人的敌人作斗争，即同专制君主制的残余、地主、非工业资产者和小资产者作斗争。因此，整个历史运动都集中在资产阶级手里；在这种条件下取得的每一个胜利都是资产阶级的胜利。","language":"中文","translation":false},{"id":"manifesto-1-147","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，随着工业的发展，无产阶级不仅人数增加了，而且结合成更大的集体，它的力量日益增长，而且它越来越感觉到自己的力量。机器使劳动的差别越来越小，使工资几乎到处都降到同样低的水平，因而无产阶级内部的利益、生活状况也越来越趋于一致。资产者彼此间日益加剧的竞争以及由此引起的商业危机，使工人的工资越来越不稳定；机器的日益迅速的和继续不断的改良，使工人的整个生活地位越来越没有保障；单个工人和单个资产者之间的冲突越来越具有两个阶级的冲突的性质。工人开始成立反对资产者的同盟〔注：在1888年英文版中这里加上了“（工联）”。——编者注〕；他们联合起来保卫自己的工资。他们甚至建立了经常性的团体，以便为可能发生的反抗准备食品。有些地方，斗争爆发为起义。","language":"中文","translation":false},{"id":"manifesto-1-148","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"工人有时也得到胜利，但这种胜利只是暂时的。他们斗争的真正成果并不是直接取得的成功，而是工人的越来越扩大的联合。这种联合由于大工业所造成的日益发达的交通工具而得到发展，这种交通工具把各地的工人彼此联系起来。只要有了这种联系，就能把许多性质相同的地方性的斗争汇合成全国性的斗争，汇合成阶级斗争。而一切阶级斗争都是政治斗争。中世纪的市民靠乡间小道需要几百年才能达到的联合，现代的无产者利用铁路只要几年就可以达到了。","language":"中文","translation":false},{"id":"manifesto-1-149","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"无产者组织成为阶级，从而组织成为政党这件事，不断地由于工人的自相竞争而受到破坏。但是，这种组织总是重新产生，并且一次比一次更强大、更坚固、更有力。它利用资产阶级内部的分裂，迫使他们用法律形式承认工人的个别利益。英国的十小时工作日法案[40]就是一个例子。","language":"中文","translation":false},{"id":"manifesto-1-150","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"旧社会内部的所有冲突在许多方面都促进了无产阶级的发展。资产阶级处于不断的斗争中：最初反对贵族；后来反对同工业进步有利害冲突的那部分资产阶级；经常反对一切外国的资产阶级。在这一切斗争中，资产阶级都不得不向无产阶级呼吁，要求无产阶级援助，这样就把无产阶级卷进了政治运动。于是，资产阶级自己就把自己的教育因素〔注：“教育因素”在1888年英文版中是“政治教育和普通教育的因素”。——编者注〕即反对自身的武器给予了无产阶级。","language":"中文","translation":false},{"id":"manifesto-1-151","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"其次，我们已经看到，工业的进步把统治阶级的整批成员拋到无产阶级队伍里去，或者至少也使他们的生活条件受到威胁。他们也给无产阶级带来了大量的教育因素〔注：“大量的教育因素”在1888年英文版中是“启蒙和进步的新因素”。——编者注〕。","language":"中文","translation":false},{"id":"manifesto-1-152","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"最后，在阶级斗争接近决战的时期，统治阶级内部的、整个旧社会内部的瓦解过程，就达到非常强烈、非常尖锐的程度，甚至使得统治阶级中的一小部分人脱离统治阶级而归附于革命的阶级，即掌握着未来的阶级。所以，正像过去贵族中有一部分人转到资产阶级方面一样，现在资产阶级中也有一部分人，特别是已经提高到能从理论上认识整个历史运动的一部分资产阶级思想家，转到无产阶级方面来了。","language":"中文","translation":false},{"id":"manifesto-1-153","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在当前同资产阶级对立的一切阶级中，只有无产阶级是真正革命的阶级。其余的阶级都随着大工业的发展而日趋没落和灭亡，无产阶级却是大工业本身的产物。","language":"中文","translation":false},{"id":"manifesto-1-154","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"中间等级，即小工业家、小商人、手工业者、农民，他们同资产阶级作斗争，都是为了维护他们这种中间等级的生存，以免于灭亡。所以，他们不是革命的，而是保守的。不仅如此，他们甚至是反动的，因为他们力图使历史的车轮倒转。如果说他们是革命的，那是鉴于他们行将转入无产阶级的队伍，这样，他们就不是维护他们目前的利益，而是维护他们将来的利益，他们就离开自己原来的立场，而站到无产阶级的立场上来。","language":"中文","translation":false},{"id":"manifesto-1-155","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"流氓无产阶级是旧社会最下层中消极的腐化的部分，他们在一些地方也被无产阶级革命卷到运动里来，但是，由于他们的整个生活状况，他们更甘心于被人收买，去干反动的勾当。","language":"中文","translation":false},{"id":"manifesto-1-156","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在无产阶级的生活条件中，旧社会的生活条件已经被消灭了。无产者是没有财产的；他们和妻子儿女的关系同资产阶级的家庭关系再没有任何共同之处了；现代的工业劳动，现代的资本压迫，无论在英国或法国，无论在美国或德国，都是一样的，都使无产者失去了任何民族性。法律、道德、宗教在他们看来全都是资产阶级偏见，隐藏在这些偏见后面的全都是资产阶级利益。","language":"中文","translation":false},{"id":"manifesto-1-157","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"过去一切阶级在争得统治之后，总是使整个社会服从于它们发财致富的条件，企图以此来巩固它们已经获得的生活地位。无产者只有废除自己的现存的占有方式，从而废除全部现存的占有方式，才能取得社会生产力。无产者没有什么自己的东西必须加以保护，他们必须摧毁至今保护和保障私有财产的一切。","language":"中文","translation":false},{"id":"manifesto-1-158","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"过去的一切运动都是少数人的，或者为少数人谋利益的运动。无产阶级的运动是绝大多数人的，为绝大多数人谋利益的独立的运动。无产阶级，现今社会的最下层，如果不炸毁构成官方社会的整个上层，就不能抬起头来，挺起胸来。","language":"中文","translation":false},{"id":"manifesto-1-159","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"如果不就内容而就形式来说，无产阶级反对资产阶级的斗争首先是一国范围内的斗争。每一个国家的无产阶级当然首先应该打倒本国的资产阶级。","language":"中文","translation":false},{"id":"manifesto-1-160","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在叙述无产阶级发展的最一般的阶段的时候，我们循序探讨了现存社会内部或多或少隐蔽着的国内战争，直到这个战争爆发为公开的革命，无产阶级用暴力推翻资产阶级而建立自己的统治。","language":"中文","translation":false},{"id":"manifesto-1-161","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"我们已经看到，至今的一切社会都是建立在压迫阶级和被压迫阶级的对立之上的。但是，为了有可能压迫一个阶级，就必须保证这个阶级至少有能够勉强维持它的奴隶般的生存的条件。农奴曾经在农奴制度下挣扎到公社成员的地位，小资产者曾经在封建专制制度的束缚下挣扎到资产者的地位。现代的工人却相反，他们并不是随着工业的进步而上升，而是越来越降到本阶级的生存条件以下。工人变成赤贫者，贫困比人口和财富增长得还要快。由此可以明显地看出，资产阶级再不能做社会的统治阶级了，再不能把自己阶级的生存条件当做支配一切的规律强加于社会了。资产阶级不能统治下去了，因为它甚至不能保证自己的奴隶维持奴隶的生活，因为它不得不让自己的奴隶落到不能养活它反而要它来养活的地步。社会再不能在它统治下生存下去了，就是说，它的生存不再同社会相容了。","language":"中文","translation":false},{"id":"manifesto-1-162","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级生存和统治的根本条件，是财富在私人手里的积累，是资本的形成和增殖；资本的条件是雇佣劳动。雇佣劳动完全是建立在工人的自相竞争之上的。资产阶级无意中造成而又无力抵抗的工业进步，使工人通过结社而达到的革命联合代替了他们由于竞争而造成的分散状态。于是，随着大工业的发展，资产阶级赖以生产和占有产品的基础本身也就从它的脚下被挖掉了。它首先生产的是它自身的掘墓人。资产阶级的灭亡和无产阶级的胜利是同样不可避免的。","language":"中文","translation":false},{"id":"manifesto-1-163","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人同全体无产者的关系是怎样的呢？","language":"中文","translation":false},{"id":"manifesto-1-164","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人不是同其它工人政党相对立的特殊政党。","language":"中文","translation":false},{"id":"manifesto-1-165","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"他们没有任何同整个无产阶级的利益不同的利益。","language":"中文","translation":false},{"id":"manifesto-1-166","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"他们不提出任何特殊的〔注：“特殊的”在1888年英文版中是“宗派的”。——编者注〕原则，用以塑造无产阶级的运动。","language":"中文","translation":false},{"id":"manifesto-1-167","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人同其它无产阶级政党不同的地方只是：一方面，在无产者不同的民族的斗争中，共产党人强调和坚持整个无产阶级共同的不分民族的利益；另一方面，在无产阶级和资产阶级的斗争所经历的各个发展阶段上，共产党人始终代表整个运动的利益。","language":"中文","translation":false},{"id":"manifesto-1-168","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，在实践方面，共产党人是各国工人政党中最坚决的、始终起推动作用的部分〔注：“最坚决的、始终起推动作用的部分”在1888年英文版中是“最先进的和最坚决的部分，推动所有其他部分前进的部分”。——编者注〕；在理论方面，他们胜过其余无产阶级群众的地方在于他们了解无产阶级运动的条件、进程和一般结果。","language":"中文","translation":false},{"id":"manifesto-1-169","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人的最近目的是和其他一切无产阶级政党的最近目的一样的：使无产阶级形成为阶级，推翻资产阶级的统治，由无产阶级夺取政权。","language":"中文","translation":false},{"id":"manifesto-1-170","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人的理论原理，决不是以这个或那个世界改革家所发明或发现的思想、原则为根据的。","language":"中文","translation":false},{"id":"manifesto-1-171","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这些原理不过是现存的阶级斗争、我们眼前的历史运动的真实关系的一般表述。废除先前存在的所有制关系，并不是共产主义所独具的特征。","language":"中文","translation":false},{"id":"manifesto-1-172","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"一切所有制关系都经历了经常的历史更替、经常的历史变更。","language":"中文","translation":false},{"id":"manifesto-1-173","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"例如，法国革命废除了封建的所有制，代之以资产阶级的所有制。","language":"中文","translation":false},{"id":"manifesto-1-174","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产主义的特征并不是要废除一般的所有制，而是要废除资产阶级的所有制。","language":"中文","translation":false},{"id":"manifesto-1-175","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，现代的资产阶级私有制是建立在阶级对立上面、建立在一些人对另一些人的剥削〔注：“一些人对另一些人的剥削”在1888年英文版中是“少数人对多数人的剥削”。——编者注〕上面的产品生产和占有的最后而又最完备的表现。","language":"中文","translation":false},{"id":"manifesto-1-176","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"从这个意义上说，共产党人可以把自己的理论概括为一句话：消灭私有制。","language":"中文","translation":false},{"id":"manifesto-1-177","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":177,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"有人责备我们共产党人，说我们要消灭个人挣得的、自己劳动得来的财产，要消灭构成个人的一切自由、活动和独立的基础的财产。","language":"中文","translation":false},{"id":"manifesto-1-178","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":178,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"好一个劳动得来的、自己挣得的、自己赚来的财产！你们说的是资产阶级财产出现以前的那种小资产阶级的、小农的财产吗？那种财产用不着我们去消灭，工业的发展已经把它消灭了，而且每天都在消灭它。","language":"中文","translation":false},{"id":"manifesto-1-179","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":179,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"或者，你们说的是现代的资产阶级的私有财产吧？","language":"中文","translation":false},{"id":"manifesto-1-180","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":180,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，难道雇佣劳动、无产者的劳动，会给无产者创造出财产来吗？没有的事。这种劳动所创造的是资本，即剥削雇佣劳动的财产，只有在不断产生出新的雇佣劳动来重新加以剥削的条件下才能增殖的财产。现今的这种财产是在资本和雇佣劳动的对立中运动的。让我们来看看这种对立的两个方面吧。","language":"中文","translation":false},{"id":"manifesto-1-181","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":181,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"做一个资本家，这就是说，他在生产中不仅占有一种纯粹个人的地位，而且占有一种社会的地位。资本是集体的产物，它只有通过社会许多成员的共同活动，而且归根到底只有通过社会全体成员的共同活动，才能运动起来。","language":"中文","translation":false},{"id":"manifesto-1-182","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":182,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，资本不是一种个人力量，而是一种社会力量。","language":"中文","translation":false},{"id":"manifesto-1-183","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":183,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，把资本变为公共的、属于社会全体成员的财产，这并不是把个人财产变为社会财产。这里所改变的只是财产的社会性质。它将失掉它的阶级性质。","language":"中文","translation":false},{"id":"manifesto-1-184","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":184,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现在，我们来看看雇佣劳动。","language":"中文","translation":false},{"id":"manifesto-1-185","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":185,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"雇佣劳动的平均价格是最低限度的工资，即工人为维持其工人的生活所必需的生活资料的数额。因此，雇佣工人靠自己的劳动所占有的东西，只够勉强维持他的生命的再生产。我们决不打算消灭这种供直接生命再生产用的劳动产品的个人占有，这种占有并不会留下任何剩余的东西使人们有可能支配别人的劳动。我们要消灭的只是这种占有的可怜的性质，在这种占有下，工人仅仅为增殖资本而活着，只有在统治阶级的利益需要他活着的时候才能活着。","language":"中文","translation":false},{"id":"manifesto-1-186","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":186,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在资产阶级社会里，活的劳动只是增殖已经积累起来的劳动的一种手段。在共产主义社会里，已经积累起来的劳动只是扩大、丰富和提高工人的生活的一种手段。","language":"中文","translation":false},{"id":"manifesto-1-187","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":187,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，在资产阶级社会里是过去支配现在，在共产主义社会里是现在支配过去。在资产阶级社会里，资本具有独立性和个性，而活动着的个人却没有独立性和个性。","language":"中文","translation":false},{"id":"manifesto-1-188","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":188,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"而资产阶级却把消灭这种关系说成是消灭个性和自由！说对了。的确，正是要消灭资产者的个性、独立性和自由。","language":"中文","translation":false},{"id":"manifesto-1-189","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":189,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在现今的资产阶级生产关系的范围内，所谓自由就是自由贸易、自由买卖。","language":"中文","translation":false},{"id":"manifesto-1-190","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":190,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，买卖一消失，自由买卖也就会消失。关于自由买卖的言论，也像我们的资产者的其他一切关于自由的大话一样，仅仅对于不自由的买卖来说，对于中世纪被奴役的市民来说，才是有意义的，而对于共产主义要消灭买卖、消灭资产阶级生产关系和资产阶级本身这一点来说，却是毫无意义的。","language":"中文","translation":false},{"id":"manifesto-1-191","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":191,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"我们要消灭私有制，你们就惊慌起来。但是，在你们的现存社会里，私有财产对十分之九的成员来说已经被消灭了；这种私有制之所以存在，正是因为私有财产对十分之九的成员来说已经不存在。可见，你们责备我们，是说我们要消灭那种以社会上的绝大多数人没有财产为必要条件的所有制。","language":"中文","translation":false},{"id":"manifesto-1-192","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":192,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"总而言之，你们责备我们，是说我们要消灭你们的那种所有制。的确，我们是要这样做的。","language":"中文","translation":false},{"id":"manifesto-1-193","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":193,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"从劳动不再能变为资本、货币、地租，一句话，不再能变为可以垄断的社会力量的时候起，就是说，从个人财产不再能变为资产阶级财产〔注：在1888年英文版中这里加上了“变为资本”。——编者注〕的时候起，你们说，个性被消灭了。","language":"中文","translation":false},{"id":"manifesto-1-194","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":194,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"由此可见，你们是承认，你们所理解的个性，不外是资产者、资产阶级私有者。这样的个性确实应当被消灭。","language":"中文","translation":false},{"id":"manifesto-1-195","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":195,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产主义并不剥夺任何人占有社会产品的权力，它只剥夺利用这种占有去奴役他人劳动的权力。","language":"中文","translation":false},{"id":"manifesto-1-196","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":196,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"有人反驳说，私有制一消灭，一切活动就会停止，懒惰之风就会兴起。","language":"中文","translation":false},{"id":"manifesto-1-197","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":197,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这样说来，资产阶级社会早就应该因懒惰而灭亡了，因为在这个社会里劳者不获，获者不劳。所有这些顾虑，都可以归结为这样一个同义反复：一旦没有资本，也就不再有雇佣劳动了。","language":"中文","translation":false},{"id":"manifesto-1-198","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":198,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"所有这些对共产主义的物质产品的占有方式和生产方式的责备，也被扩展到精神产品的占有和生产方面。正如阶级的所有制的终止在资产者看来是生产本身的终止一样，阶级的教育的终止在他们看来就等于一切教育的终止。","language":"中文","translation":false},{"id":"manifesto-1-199","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":199,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产者唯恐失去的那种教育，对绝大多数人来说是把人训练成机器。","language":"中文","translation":false},{"id":"manifesto-1-200","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":200,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，你们既然用你们资产阶级关于自由、教育、法等等的观念来衡量废除资产阶级所有制的主张，那就请你们不要同我们争论了。你们的观念本身是资产阶级的生产关系和所有制关系的产物，正像你们的法不过是被奉为法律的你们这个阶级的意志一样，而这种意志的内容是由你们这个阶级的物质生活条件来决定的。","language":"中文","translation":false},{"id":"manifesto-1-201","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":201,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"你们的利己观念使你们把自己的生产关系和所有制关系从历史的、在生产过程中是暂时的关系变成永恒的自然规律和理性规律，这种利己观念是你们和一切灭亡了的统治阶级所共有的。谈到古代所有制的时候你们所能理解的，谈到封建所有制的时候你们所能理解的，一谈到资产阶级所有制你们就再也不能理解了。","language":"中文","translation":false},{"id":"manifesto-1-202","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":202,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"消灭家庭！连极端的激进派也对共产党人的这种可耻的意图表示愤慨。","language":"中文","translation":false},{"id":"manifesto-1-203","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":203,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"现代的、资产阶级的家庭是建立在什么基础上的呢？是建立在资本上面，建立在私人发财上面的。这种家庭只是在资产阶级那里才以充分发展的形式存在着，而无产者的被迫独居和公开的卖淫则是它的补充。","language":"中文","translation":false},{"id":"manifesto-1-204","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":204,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产者的家庭自然会随着它的这种补充的消失而消失，两者都要随着资本的消失而消失。","language":"中文","translation":false},{"id":"manifesto-1-205","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":205,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"你们是责备我们要消灭父母对子女的剥削吗？我们承认这种罪状。","language":"中文","translation":false},{"id":"manifesto-1-206","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":206,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，你们说，我们用社会教育代替家庭教育，就是要消灭人们最亲密的关系。","language":"中文","translation":false},{"id":"manifesto-1-207","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":207,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"而你们的教育不也是由社会决定的吗？不也是由你们进行教育时所处的那种社会关系决定的吗？不也是由社会通过学校等等进行的直接的或间接的干涉决定的吗？共产党人并没有发明社会对教育的作用；他们仅仅是要改变这种作用的性质，要使教育摆脱统治阶级的影响。","language":"中文","translation":false},{"id":"manifesto-1-208","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":208,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"无产者的一切家庭联系越是由于大工业的发展而被破坏，他们的子女越是由于这种发展而被变成单纯的商品和劳动工具，资产阶级关于家庭和教育、关于父母和子女的亲密关系的空话就越是令人作呕。","language":"中文","translation":false},{"id":"manifesto-1-209","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":209,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，你们共产党人是要实行公妻制的啊。整个资产阶级异口同声地向我们这样叫喊。","language":"中文","translation":false},{"id":"manifesto-1-210","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":210,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产者是把自己的妻子看作单纯的生产工具的。他们听说生产工具将要公共使用，自然就不能不想到妇女也会遭到同样的命运。","language":"中文","translation":false},{"id":"manifesto-1-211","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":211,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"他们想也没有想到，问题正在于使妇女不再处于单纯生产工具的地位。","language":"中文","translation":false},{"id":"manifesto-1-212","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":212,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"其实，我们的资产者装得道貌岸然，对所谓的共产党人的正式公妻制表示惊讶，那是再可笑不过了。公妻制无需共产党人来实行，它差不多是一向就有的。","language":"中文","translation":false},{"id":"manifesto-1-213","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":213,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"我们的资产者不以他们的无产者的妻子和女儿受他们支配为满足，正式的卖淫更不必说了，他们还以互相诱奸妻子为最大的享乐。","language":"中文","translation":false},{"id":"manifesto-1-214","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":214,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级的婚姻实际上是公妻制。人们至多只能责备共产党人，说他们想用正式的、公开的公妻制来代替伪善地掩蔽着的公妻制。其实，不言而喻，随着现在的生产关系的消灭，从这种关系中产生的公妻制，即正式的和非正式的卖淫，也就消失了。","language":"中文","translation":false},{"id":"manifesto-1-215","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":215,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"还有人责备共产党人，说他们要取消祖国，取消民族。","language":"中文","translation":false},{"id":"manifesto-1-216","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":216,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"工人没有祖国。决不能剥夺他们所没有的东西。因为无产阶级首先必须取得政治统治，上升为民族的阶级〔注：“民族的阶级”在1888年英文版中是“民族的领导阶级”。——编者注〕，把自身组织成为民族，所以它本身还是民族的，虽然完全不是资产阶级所理解的那种意思。","language":"中文","translation":false},{"id":"manifesto-1-217","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":217,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"随着资产阶级的发展，随着贸易自由的实现和世界市场的建立，随着工业生产以及与之相适应的生活条件的趋于一致，各国人民之间的民族隔绝和对立日益消失。","language":"中文","translation":false},{"id":"manifesto-1-218","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":218,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"无产阶级的统治将使它们更快地消失。联合的行动，至少是各文明国家的联合的行动，是无产阶级获得解放的首要条件之一。","language":"中文","translation":false},{"id":"manifesto-1-219","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":219,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"人对人的剥削一消灭，民族对民族的剥削就会随之消灭。","language":"中文","translation":false},{"id":"manifesto-1-220","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":220,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"民族内部的阶级对立一消失，民族之间的敌对关系就会随之消失。","language":"中文","translation":false},{"id":"manifesto-1-221","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":221,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"从宗教的、哲学的和一切意识形态的观点对共产主义提出的种种责难，都不值得详细讨论了。","language":"中文","translation":false},{"id":"manifesto-1-222","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":222,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"人们的观念、观点和概念，一句话，人们的意识，随着人们的生活条件、人们的社会关系、人们的社会存在的改变而改变，这难道需要经过深思才能了解吗？","language":"中文","translation":false},{"id":"manifesto-1-223","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":223,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"思想的历史除了证明精神生产随着物质生产的改造而改造，还证明了什么呢？任何一个时代的统治思想始终都不过是统治阶级的思想。","language":"中文","translation":false},{"id":"manifesto-1-224","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":224,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"当人们谈到使整个社会革命化的思想时，他们只是表明了一个事实：在旧社会内部已经形成了新社会的因素，旧思想的瓦解是同旧生活条件的瓦解步调一致的。","language":"中文","translation":false},{"id":"manifesto-1-225","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":225,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"当古代世界走向灭亡的时候，古代的各种宗教就被基督教战胜了。当基督教思想在18世纪被启蒙思想击败的时候，封建社会正在同当时革命的资产阶级进行殊死的斗争。信仰自由和宗教自由的思想，不过表明自由竞争在信仰领域〔注：“信仰领域”在1872、1883和1890年德文版中是“知识领域”。——编者注〕里占统治地位罢了。","language":"中文","translation":false},{"id":"manifesto-1-226","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":226,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"“但是”，有人会说，“宗教的、道德的、哲学的、政治的、法的观念等等在历史发展的进程中固然是不断改变的，而宗教、道德、哲学、政治和法在这种变化中却始终保存着。","language":"中文","translation":false},{"id":"manifesto-1-227","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":227,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"此外，还存在着一切社会状态所共有的永恒的真理，如自由、正义等等。但是共产主义要废除永恒真理，它要废除宗教、道德，而不是加以革新，所以共产主义是同至今的全部历史发展相矛盾的。”","language":"中文","translation":false},{"id":"manifesto-1-228","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":228,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种责难归结为什么呢？至今的一切社会的历史都是在阶级对立中运动的，而这种对立在不同的时代具有不同的形式。","language":"中文","translation":false},{"id":"manifesto-1-229","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":229,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，不管阶级对立具有什么样的形式，社会上一部分人对另一部分人的剥削却是过去各个世纪所共有的事实。因此，毫不奇怪，各个世纪的社会意识，尽管形形色色、千差万别，总是在某些共同的形式中运动的，这些形式，这些意识形式，只有当阶级对立完全消失的时候才会完全消失。","language":"中文","translation":false},{"id":"manifesto-1-230","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":230,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产主义革命就是同传统的所有制关系实行最彻底的决裂；毫不奇怪，它在自己的发展进程中要同传统的观念实行最彻底的决裂。","language":"中文","translation":false},{"id":"manifesto-1-231","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":231,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"不过，我们还是把资产阶级对共产主义的种种责难撇开吧。","language":"中文","translation":false},{"id":"manifesto-1-232","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":232,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"前面我们已经看到，工人革命的第一步就是使无产阶级上升为统治阶级，争得民主。","language":"中文","translation":false},{"id":"manifesto-1-233","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":233,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"无产阶级将利用自己的政治统治，一步一步地夺取资产阶级的全部资本，把一切生产工具集中在国家即组织成为统治阶级的无产阶级手里，并且尽可能快地增加生产力的总量。","language":"中文","translation":false},{"id":"manifesto-1-234","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":234,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"要做到这一点，当然首先必须对所有权和资产阶级生产关系实行强制性的干涉，也就是采取这样一些措施，这些措施在经济上似乎是不够充分的和无法持续的，但是在运动进程中它们会越出本身，〔注：在1888年英文版中这里加上了“使进一步向旧的社会制度进攻成为必要”。——编者注〕而且作为变革全部生产方式的手段是必不可少的。","language":"中文","translation":false},{"id":"manifesto-1-235","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":235,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这些措施在不同的国家里当然会是不同的。","language":"中文","translation":false},{"id":"manifesto-1-236","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":236,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，最先进的国家几乎都可以采取下面的措施：","language":"中文","translation":false},{"id":"manifesto-1-237","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":237,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1．剥夺地产，把地租用于国家支出。","language":"中文","translation":false},{"id":"manifesto-1-238","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":238,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"4．没收一切流亡分子和叛乱分子的财产。","language":"中文","translation":false},{"id":"manifesto-1-239","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":239,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"5．通过拥有国家资本和独享垄断权的国家银行，把信贷集中在国家手里。","language":"中文","translation":false},{"id":"manifesto-1-240","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":240,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"6．把全部运输业集中在国家手里。","language":"中文","translation":false},{"id":"manifesto-1-241","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":241,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"7．按照共同的计划增加国家工厂和生产工具，开垦荒地和改良土壤。","language":"中文","translation":false},{"id":"manifesto-1-242","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":242,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"8．实行普遍劳动义务制，成立产业军，特别是在农业方面。","language":"中文","translation":false},{"id":"manifesto-1-243","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":243,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"9．把农业和工业结合起来，促使城乡对立〔注：“对立”在1872、1883和1890年德文版中是“差别”。——编者注〕逐步消灭。〔注：在1888年英文版中这一条是：“把农业和工业结合起来；通过把人口更平均地分布于全国的办法逐步消灭城乡差别。”——编者注〕","language":"中文","translation":false},{"id":"manifesto-1-244","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":244,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"10．对所有儿童实行公共的和免费的教育。取消现在这种形式的儿童的工厂劳动。把教育同物质生产结合起来，等等。","language":"中文","translation":false},{"id":"manifesto-1-245","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":245,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"当阶级差别在发展进程中已经消失而全部生产集中在联合起来的个人〔注：“联合起来的个人”在1888年英文版中是“巨大的全国联合体”。——编者注〕的手里的时候，公共权力就失去政治性质。原来意义上的政治权力，是一个阶级用以压迫另一个阶级的有组织的暴力。如果说无产阶级在反对资产阶级的斗争中一定要联合为阶级，通过革命使自己成为统治阶级，并以统治阶级的资格用暴力消灭旧的生产关系，那么它在消灭这种生产关系的同时，也就消灭了阶级对立的存在条件，消灭了阶级本身的存在条件〔注：“消灭了阶级本身的存在条件”在1872、1883和1890年德文版中是“消灭了阶级本身”。——编者注〕，从而消灭了它自己这个阶级的统治。","language":"中文","translation":false},{"id":"manifesto-1-246","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":246,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"代替那存在着阶级和阶级对立的资产阶级旧社会的，将是这样一个联合体，在那里，每个人的自由发展是一切人的自由发展的条件。","language":"中文","translation":false},{"id":"manifesto-1-247","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":247,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"三、社会主义的和共产主义的文献","language":"中文","translation":false},{"id":"manifesto-1-248","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":248,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"法国和英国的贵族，按照他们的历史地位所负的使命，就是写一些抨击现代资产阶级社会的作品。在法国的1830年七月革命[41]和英国的改革运动[42]中，他们再一次被可恨的暴发户打败了。从此就再谈不上严重的政治斗争了。他们还能进行的只是文字斗争。但是，即使在文字方面也不可能重弹复辟时期〔注：恩格斯在1888年英文版上加了一个注：“这里所指的不是1660-1689年英国的复辟时期，而是1814-1830年法国的复辟时期。”——编者注〕的老调了。为了激起同情，贵族们不得不装模做样，似乎他们已经不关心自身的利益，只是为了被剥削的工人阶级的利益才去写对资产阶级的控诉书。他们用来泄愤的手段是：唱唱诅咒他们的新统治者的歌，并向他叽叽咕咕地说一些或多或少凶险的预言。","language":"中文","translation":false},{"id":"manifesto-1-249","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":249,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这样就产生了封建的社会主义，半是挽歌，半是谤文，半是过去的回音，半是未来的恫吓；它有时也能用辛辣、俏皮而尖刻的评论刺中资产阶级的心，但是它由于完全不能理解现代历史的进程而总是令人感到可笑。","language":"中文","translation":false},{"id":"manifesto-1-250","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":250,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"为了拉拢人民，贵族们把无产阶级的乞食袋当做旗帜来挥舞。但是，每当人民跟着他们走的时候，都发现他们的臀部带有旧的封建纹章，于是就哈哈大笑，一哄而散。","language":"中文","translation":false},{"id":"manifesto-1-251","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":251,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"一部分法国正统派[43]和“青年英国”[44]，都演过这出戏。","language":"中文","translation":false},{"id":"manifesto-1-252","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":252,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"封建主说，他们的剥削方式和资产阶级的剥削不同，那他们只是忘记了，他们是在完全不同的、目前已经过时的情况和条件下进行剥削的。他们说，在他们的统治下并没有出现过现代的无产阶级，那他们只是忘记了，现代的资产阶级正是他们的社会制度的必然产物。","language":"中文","translation":false},{"id":"manifesto-1-253","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":253,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"不过，他们毫不掩饰自己的批评的反动性质，他们控告资产阶级的主要罪状正是在于：在资产阶级的统治下有一个将把整个旧社会制度炸毁的阶级发展起来。","language":"中文","translation":false},{"id":"manifesto-1-254","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":254,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"他们责备资产阶级，与其说是因为它产生了无产阶级，不如说是因为它产生了革命的无产阶级。","language":"中文","translation":false},{"id":"manifesto-1-255","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":255,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，在政治实践中，他们参与对工人阶级采取的一切暴力措施，在日常生活中，他们违背自己的那一套冠冕堂皇的言辞，屈尊拾取金苹果〔注：“金苹果”在1888年英文版中是“工业树上掉下来的金苹果”。——编者注〕，不顾信义、仁爱和名誉去做羊毛、甜菜和烧酒的买卖。〔注：恩格斯在1888年英文版上加了一个注：“这里主要是指德国，那里的土地贵族和容克通过管事自行经营自己的很大一部分土地，他们还开设大规模的甜菜糖厂和土豆酒厂。较富有的英国贵族还没有落到这种地步；但是，他们也知道怎样让人家用他们的名义创办颇为可疑的股份公司，以补偿地租的下降。”——编者注〕","language":"中文","translation":false},{"id":"manifesto-1-256","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":256,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"正如僧侣总是同封建主携手同行一样，僧侣的社会主义也总是同封建的社会主义携手同行的。","language":"中文","translation":false},{"id":"manifesto-1-257","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":257,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"要给基督教禁欲主义涂上一层社会主义的色彩，是再容易不过了。基督教不是也激烈反对私有制，反对婚姻，反对国家吗？它不是提倡用行善和求乞、独身和禁欲、修道和礼拜来代替这一切吗？基督教的社会主义，只不过是僧侣用来使贵族的怨愤神圣化的圣水罢了。","language":"中文","translation":false},{"id":"manifesto-1-258","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":258,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"（乙）小资产阶级的社会主义","language":"中文","translation":false},{"id":"manifesto-1-259","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":259,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"封建贵族并不是被资产阶级所推翻的、其生活条件在现代资产阶级社会里日益恶化和消失的唯一阶级。中世纪的城关市民和小农等级是现代资产阶级的前身。在工商业不很发达的国家里，这个阶级还在新兴的资产阶级身旁勉强生存着。","language":"中文","translation":false},{"id":"manifesto-1-260","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":260,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在现代文明已经发展的国家里，形成了一个新的小资产阶级，它摇摆于无产阶级和资产阶级之间，并且作为资产阶级社会的补充部分不断地重新组成。但是，这一阶级的成员经常被竞争拋到无产阶级队伍里去，而且，随着大工业的发展，他们甚至觉察到，他们很快就会完全失去他们作为现代社会中一个独立部分的地位，在商业、工场手工业和农业中很快就会被监工和雇员所代替。","language":"中文","translation":false},{"id":"manifesto-1-261","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":261,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在农民阶级远远超过人口半数的国家，例如在法国，那些站在无产阶级方面反对资产阶级的著作家，自然是用小资产阶级和小农的尺度去批判资产阶级制度的，是从小资产阶级的立场出发替工人说话的。这样就形成了小资产阶级的社会主义。西斯蒙第不仅对法国而且对英国来说都是这类著作家的首领。","language":"中文","translation":false},{"id":"manifesto-1-262","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":262,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种社会主义非常透彻地分析了现代生产关系中的矛盾。它揭穿了经济学家的虚伪的粉饰。它确凿地证明了机器和分工的破坏作用、资本和地产的积聚、生产过剩、危机、小资产者和小农的必然没落、无产阶级的贫困、生产的无政府状态、财富分配的极不平均、各民族之间的毁灭性的工业战争，以及旧风尚、旧家庭关系和旧民族性的解体。","language":"中文","translation":false},{"id":"manifesto-1-263","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":263,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，这种社会主义按其实际内容来说，或者是企图恢复旧的生产资料和交换手段，从而恢复旧的所有制关系和旧的社会，或者是企图重新把现代的生产资料和交换手段硬塞到已被它们突破而且必然被突破的旧的所有制关系的框子里去。它在这两种场合都是反动的，同时又是空想的。","language":"中文","translation":false},{"id":"manifesto-1-264","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":264,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"工场手工业中的行会制度，农业中的宗法经济。这就是它的结论。","language":"中文","translation":false},{"id":"manifesto-1-265","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":265,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这一思潮在它以后的发展中变成了一种怯懦的悲叹。〔注：在1888年英文版中这一句是：“最后，当顽强的历史事实把自我欺骗的一切醉梦驱散的时候，这种形式的社会主义就化为一种可怜的哀愁。”——编者注〕","language":"中文","translation":false},{"id":"manifesto-1-266","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":266,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"（丙）德国的或“真正的”社会主义","language":"中文","translation":false},{"id":"manifesto-1-267","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":267,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"法国的社会主义和共产主义的文献是在居于统治地位的资产阶级的压迫下产生的，并且是同这种统治作斗争的文字表现，这种文献被搬到德国的时候，那里的资产阶级才刚刚开始进行反对封建专制制度的斗争。","language":"中文","translation":false},{"id":"manifesto-1-268","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":268,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"德国的哲学家、半哲学家和美文学家，贪婪地抓住了这种文献，不过他们忘记了：在这种著作从法国搬到德国的时候，法国的生活条件却没有同时搬过去。在德国的条件下，法国的文献完全失去了直接实践的意义，而只具有纯粹文献的形式。它必然表现为关于真正的社会、关于实现人的本质的无谓思辨。这样，第一次法国革命的要求，在18世纪的德国哲学家看来，不过是一般“实践理性”的要求，而革命的法国资产阶级的意志的表现，在他们心目中就是纯粹意志、本来的意志、真正人的意志的规律。","language":"中文","translation":false},{"id":"manifesto-1-269","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":269,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"德国著作家的唯一工作，就是把新的法国的思想同他们的旧的哲学信仰调和起来，或者毋宁说，就是从他们的哲学观点出发去掌握法国的思想。","language":"中文","translation":false},{"id":"manifesto-1-270","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":270,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种掌握，就像掌握外国语一样，是通过翻译的。","language":"中文","translation":false},{"id":"manifesto-1-271","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":271,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"大家知道，僧侣们曾经在古代异教经典的手抄本上面写上荒诞的天主教圣徒传。德国著作家对世俗的法国文献采取相反的做法。他们在法国的原著下面写上自己的哲学胡说。例如，他们在法国人对货币关系的批判下面写上“人的本质的外化”，在法国人对资产阶级国家的批判下面写上所谓“抽象普遍物的统治的扬弃”，等等。","language":"中文","translation":false},{"id":"manifesto-1-272","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":272,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种在法国人的论述下面塞进自己哲学词句的做法，他们称之为“行动的哲学”、“真正的社会主义”、“德国的社会主义科学”、“社会主义的哲学论证”，等等。","language":"中文","translation":false},{"id":"manifesto-1-273","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":273,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"法国的社会主义和共产主义的文献就这样被完全阉割了。既然这种文献在德国人手里已不再表现一个阶级反对另一个阶级的斗争，于是德国人就认为：他们克服了“法国人的片面性”，他们不代表真实的要求，而代表真理的要求，不代表无产者的利益，而代表人的本质的利益，即一般人的利益，这种人不属于任何阶级，根本不存在于现实界，而只存在于云雾弥漫的哲学幻想的太空。","language":"中文","translation":false},{"id":"manifesto-1-274","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":274,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种曾经郑重其事地看待自己那一套拙劣的小学生作业并且大言不惭地加以吹嘘的德国社会主义，现在渐渐失去了它的自炫博学的天真。","language":"中文","translation":false},{"id":"manifesto-1-275","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":275,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"德国的特别是普鲁士的资产阶级反对封建主和专制王朝的斗争，一句话，自由主义运动，越来越严重了。","language":"中文","translation":false},{"id":"manifesto-1-276","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":276,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"于是，“真正的”社会主义就得到了一个好机会，把社会主义的要求同政治运动对立起来，用诅咒异端邪说的传统办法诅咒自由主义，诅咒代议制国家，诅咒资产阶级的竞争、资产阶级的新闻出版自由、资产阶级的法、资产阶级的自由和平等，并且向人民群众大肆宣扬，说什么在这个资产阶级运动中，人民群众非但一无所得，反而会失去一切。德国的社会主义恰好忘记了，法国的批判（德国的社会主义是这种批判的可怜的回声）是以现代的资产阶级社会以及相应的物质生活条件和相当的政治制度为前提的，而这一切前提当时在德国正是尚待争取的。","language":"中文","translation":false},{"id":"manifesto-1-277","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":277,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种社会主义成了德意志各邦专制政府及其随从——僧侣、教员、容克和官僚求之不得的、吓唬来势汹汹的资产阶级的稻草人。","language":"中文","translation":false},{"id":"manifesto-1-278","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":278,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种社会主义是这些政府用来镇压德国工人起义的毒辣的皮鞭和枪弹的甜蜜的补充。","language":"中文","translation":false},{"id":"manifesto-1-279","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":279,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"既然“真正的”社会主义就这样成了这些政府对付德国资产阶级的武器，那么它也就直接代表了一种反动的利益，即德国小市民的利益。在德国，16世纪遗留下来的、从那时起经常以不同形式重新出现的小资产阶级，是现存制度的真实的社会基础。","language":"中文","translation":false},{"id":"manifesto-1-280","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":280,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"保存这个小资产阶级，就是保存德国的现存制度。这个阶级胆战心惊地从资产阶级的工业统治和政治统治那里等候着无可幸免的灭亡，这一方面是由于资本的积聚，另一方面是由于革命无产阶级的兴起。在它看来，“真正的”社会主义能起一箭双雕的作用。“真正的”社会主义像瘟疫一样流行起来了。","language":"中文","translation":false},{"id":"manifesto-1-281","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":281,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"德国的社会主义者给自己的那几条干瘪的“永恒真理”披上一件用思辨的蛛丝织成的、绣满华丽辞藻的花朵和浸透甜情蜜意的甘露的外衣，这件光彩夺目的外衣只是使他们的货物在这些顾客中间增加销路罢了。","language":"中文","translation":false},{"id":"manifesto-1-282","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":282,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"同时，德国的社会主义也越来越认识到自己的使命就是充当这种小市民的夸夸其谈的代言人。","language":"中文","translation":false},{"id":"manifesto-1-283","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":283,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"它宣布德意志民族是模范的民族，德国小市民是模范的人。它给这些小市民的每一种丑行都加上奥秘的、高尚的、社会主义的意义，使之变成完全相反的东西。它发展到最后，就直接反对共产主义的“野蛮破坏的”倾向，并且宣布自己是不偏不倚地超乎任何阶级斗争之上的。现今在德国流行的一切所谓社会主义和共产主义的著作，除了极少数的例外，都属于这一类卑鄙龌龊的、令人委靡的文献。〔注：恩格斯在1890年德文版上加了一个注：“1848年的革命风暴已经把这个可恶的流派一扫而光，并且使这一流派的代表人物再也没有兴趣搞社会主义了。这一流派的主要代表和典型人物是卡尔·格律恩先生。”——编者注〕","language":"中文","translation":false},{"id":"manifesto-1-284","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":284,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"2．保守的或资产阶级的社会主义","language":"中文","translation":false},{"id":"manifesto-1-285","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":285,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级中的一部分人想要消除社会的弊病，以便保障资产阶级社会的生存。","language":"中文","translation":false},{"id":"manifesto-1-286","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":286,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这一部分人包括：经济学家、博爱主义者、人道主义者、劳动阶级状况改善派、慈善事业组织者、动物保护协会会员、戒酒协会发起人以及形形色色的小改良家。这种资产阶级的社会主义甚至被制成一些完整的体系。","language":"中文","translation":false},{"id":"manifesto-1-287","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":287,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"我们可以举蒲鲁东的《贫困的哲学》〔注：皮·约·蒲鲁东《经济矛盾的体系，或贫困的哲学》1846年巴黎版第1-2卷。——编者注〕作为例子。","language":"中文","translation":false},{"id":"manifesto-1-288","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":288,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"社会主义的资产者愿意要现代社会的生存条件，但是不要由这些条件必然产生的斗争和危险。他们愿意要现存的社会，但是不要那些使这个社会革命化和瓦解的因素。他们愿意要资产阶级，但是不要无产阶级。在资产阶级看来，它所统治的世界自然是最美好的世界。资产阶级的社会主义把这种安慰人心的观念制成半套或整套的体系。它要求无产阶级实现它的体系，走进新的耶路撒冷，其实它不过是要求无产阶级停留在现今的社会里，但是要拋弃他们关于这个社会的可恶的观念。","language":"中文","translation":false},{"id":"manifesto-1-289","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":289,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种社会主义的另一种不够系统、但是比较实际的形式，力图使工人阶级厌弃一切革命运动，硬说能给工人阶级带来好处的并不是这样或那样的政治改革，而仅仅是物质生活条件即经济关系的改变。但是，这种社会主义所理解的物质生活条件的改变，绝对不是只有通过革命的途径才能实现的资产阶级生产关系的废除，而是一些在这种生产关系的基础上实行的行政上的改良，因而丝毫不会改变资本和雇佣劳动的关系，至多只能减少资产阶级的统治费用和简化它的财政管理。","language":"中文","translation":false},{"id":"manifesto-1-290","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":290,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级的社会主义只有在它变成纯粹的演说辞令的时候，才获得自己的适当的表现。","language":"中文","translation":false},{"id":"manifesto-1-291","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":291,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"自由贸易！为了工人阶级的利益；保护关税！为了工人阶级的利益；单人牢房！为了工人阶级的利益。这才是资产阶级的社会主义唯一真实的结论。","language":"中文","translation":false},{"id":"manifesto-1-292","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":292,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"资产阶级的社会主义就是这样一个论断：资产者之为资产者，是为了工人阶级的利益。","language":"中文","translation":false},{"id":"manifesto-1-293","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":293,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"3．批判的空想的社会主义和共产主义","language":"中文","translation":false},{"id":"manifesto-1-294","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":294,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在这里，我们不谈在现代一切大革命中表达过无产阶级要求的文献（巴贝夫等人的著作）。","language":"中文","translation":false},{"id":"manifesto-1-295","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":295,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"无产阶级在普遍激动的时代、在推翻封建社会的时期直接实现自己阶级利益的最初尝试，都不可避免地遭到了失败，这是由于当时无产阶级本身还不够发展，由于无产阶级解放的物质条件还没有具备，这些条件只是资产阶级时代的产物。随着这些早期的无产阶级运动而出现的革命文献，就其内容来说必然是反动的。这种文献倡导普遍的禁欲主义和粗陋的平均主义。","language":"中文","translation":false},{"id":"manifesto-1-296","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":296,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"本来意义的社会主义和共产主义的体系，圣西门、傅立叶、欧文等人的体系，是在无产阶级和资产阶级之间的斗争还不发展的最初时期出现的。关于这个时期，我们在前面已经叙述过了（见《资产阶级和无产阶级》〔注：指《共产党宣言》第1章《资产者和无产者》。——编者注〕）。","language":"中文","translation":false},{"id":"manifesto-1-297","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":297,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"诚然，这些体系的发明家看到了阶级的对立，以及占统治地位的社会本身中的瓦解因素的作用。但是，他们看不到无产阶级方面的任何历史主动性，看不到它所特有的任何政治运动。","language":"中文","translation":false},{"id":"manifesto-1-298","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":298,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"由于阶级对立的发展是同工业的发展步调一致的，所以这些发明家也不可能看到无产阶级解放的物质条件，于是他们就去探求某种社会科学、社会规律，以便创造这些条件。","language":"中文","translation":false},{"id":"manifesto-1-299","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":299,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"社会的活动要由他们个人的发明活动来代替，解放的历史条件要由幻想的条件来代替，无产阶级的逐步组织成为阶级要由一种特意设计出来的社会组织来代替。在他们看来，今后的世界历史不过是宣传和实施他们的社会计划。","language":"中文","translation":false},{"id":"manifesto-1-300","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":300,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"诚然，他们也意识到，他们的计划主要是代表工人阶级这一受苦最深的阶级的利益。在他们的心目中，无产阶级只是一个受苦最深的阶级。","language":"中文","translation":false},{"id":"manifesto-1-301","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":301,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，由于阶级斗争不发展，由于他们本身的生活状况，他们就以为自己是高高超乎这种阶级对立之上的。他们要改善社会一切成员的生活状况，甚至生活最优裕的成员也包括在内。因此，他们总是不加区别地向整个社会呼吁，而且主要是向统治阶级呼吁。他们以为，人们只要理解他们的体系，就会承认这种体系是最美好的社会的最美好的计划。","language":"中文","translation":false},{"id":"manifesto-1-302","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":302,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，他们拒绝一切政治行动，特别是一切革命行动；他们想通过和平的途径达到自己的目的，并且企图通过一些小型的、当然不会成功的试验，通过示范的力量来为新的社会福音开辟道路。","language":"中文","translation":false},{"id":"manifesto-1-303","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":303,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这种对未来社会的幻想的描绘，在无产阶级还很不发展，因而对本身的地位的认识还基于幻想的时候，是同无产阶级对社会普遍改造的最初的本能的渴望相适应的。〔注：这段话在1872、1883和1890年德文版中是：“这种对未来社会的幻想的描绘，是在无产阶级还很不发展，因而对本身的地位的认识还基于幻想的时候，从无产阶级对社会普遍改造的最初的本能的渴望中产生的。”——编者注〕","language":"中文","translation":false},{"id":"manifesto-1-304","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":304,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，这些社会主义和共产主义的著作也含有批判的成分。这些著作抨击现存社会的全部基础。因此，它们提供了启发工人觉悟的极为宝贵的材料。它们关于未来社会的积极的主张，例如消灭城乡对立〔注：“城乡对立”在1888年英文版中是“城乡差别”。——编者注〕、消灭家庭、消灭私人营利、消灭雇佣劳动、提倡社会和谐、把国家变成纯粹的生产管理机构——所有这些主张都只是表明要消灭阶级对立，而这种阶级对立在当时刚刚开始发展，它们所知道的只是这种对立的早期的、不明显的、不确定的形式。因此，这些主张本身还带有纯粹空想的性质。","language":"中文","translation":false},{"id":"manifesto-1-305","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":305,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"批判的空想的社会主义和共产主义的意义，是同历史的发展成反比的。阶级斗争越发展和越具有确定的形式，这种超乎阶级斗争的幻想，这种反对阶级斗争的幻想，就越失去任何实践意义和任何理论根据。所以，虽然这些体系的创始人在许多方面是革命的，但是他们的信徒总是组成一些反动的宗派。这些信徒无视无产阶级的历史进展，还是死守着老师们的旧观点。因此，他们一贯企图削弱阶级斗争，调和对立。他们还总是梦想用试验的办法来实现自己的社会空想，创办单个的法伦斯泰尔，建立国内移民区，创立小伊加利亚〔注：恩格斯在1888年英文版上加了一个注：“法伦斯秦尔是沙尔·傅立叶所设计的社会主义移民区；伊加利亚是卡贝给自己的理想国和后来他在美洲创立的共产主义移民区所起的名称。”恩格斯在1890年德文版上加了一个注：“国内移民区是欧文给他的共产主义的模范社会所起的名称。法伦斯泰尔是傅立叶所设计的社会宫的名称。伊加利亚是卡贝所描绘的那种共产主义制度的乌托邦幻想国。”——编者注〕，即袖珍版的新耶路撒冷。而为了建造这一切空中楼阁，他们就不得不呼吁资产阶级发善心和慷慨解囊。他们逐渐地堕落到上述反动的或保守的社会主义者的一伙中去了，所不同的只是他们更加系统地卖弄学问，狂热地迷信自己那一套社会科学的奇功异效。","language":"中文","translation":false},{"id":"manifesto-1-306","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":306,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"因此，他们激烈地反对工人的一切政治运动，认为这种运动只是由于盲目地不相信新福音才发生的。","language":"中文","translation":false},{"id":"manifesto-1-307","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":307,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在英国，有欧文派[24]反对宪章派[45]，在法国，有傅立叶派[25]反对改革派[46]。","language":"中文","translation":false},{"id":"manifesto-1-308","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":308,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"四、共产党人对各种反对党派的态度","language":"中文","translation":false},{"id":"manifesto-1-309","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":309,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"看过第二章之后，就可以了解共产党人同已经形成的工人政党的关系，因而也就可以了解他们同英国宪章派和北美土地改革派[47]的关系。","language":"中文","translation":false},{"id":"manifesto-1-310","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":310,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人为工人阶级的最近的目的和利益而斗争，但是他们在当前的运动中同时代表运动的未来。在法国，共产党人同社会主义民主党〔注：恩格斯在1888年英文版上加了一个注：“当时这个党在议会中的代表是赖德律-洛兰，在著作界的代表是路易·勃朗，在报纸方面的代表是《改革报》[46]。‘社会主义民主党’这个名称在它的发明者那里是指民主党或共和党中或多或少带有社会主义色彩的一部分人。”恩格斯在1890年德文版上加了一个注：“当时在法国以社会主义民主党自称的政党，在政治方面的代表是赖德律-洛兰，在著作界的代表是路易·勃朗；因此，它同现今的德国社会民主党是有天壤之别的。”——编者注〕联合起来反对保守的和激进的资产阶级，但是并不因此放弃对那些从革命的传统中承袭下来的空谈和幻想采取批判态度的权利。","language":"中文","translation":false},{"id":"manifesto-1-311","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":311,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在瑞士，共产党人支持激进派，但是并不忽略这个政党是由互相矛盾的分子组成的，其中一部分是法国式的民主社会主义者，一部分是激进的资产者。","language":"中文","translation":false},{"id":"manifesto-1-312","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":312,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在波兰人中间，共产党人支持那个把土地革命当做民族解放的条件的政党，即发动过1846年克拉科夫起义[48]的政党。","language":"中文","translation":false},{"id":"manifesto-1-313","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":313,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在德国，只要资产阶级采取革命的行动，共产党就同它一起去反对专制君主制、封建土地所有制和小资产阶级。","language":"中文","translation":false},{"id":"manifesto-1-314","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":314,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但是，共产党一分钟也不忽略教育工人尽可能明确地意识到资产阶级和无产阶级的敌对的对立，以便德国工人能够立刻利用资产阶级统治所必然带来的社会的和政治的条件作为反对资产阶级的武器，以便在推翻德国的反动阶级之后立即开始反对资产阶级本身的斗争。","language":"中文","translation":false},{"id":"manifesto-1-315","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":315,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人把自己的主要注意力集中在德国，因为德国正处在资产阶级革命的前夜，因为同17世纪的英国和18世纪的法国相比，德国将在整个欧洲文明更进步的条件下，拥有发展得多的无产阶级去实现这个变革，因而德国的资产阶级革命只能是无产阶级革命的直接序幕。","language":"中文","translation":false},{"id":"manifesto-1-316","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":316,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"总之，共产党人到处都支持一切反对现存的社会制度和政治制度的革命运动。","language":"中文","translation":false},{"id":"manifesto-1-317","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":317,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"在所有这些运动中，他们都强调所有制问题是运动的基本问题，不管这个问题的发展程度怎样。","language":"中文","translation":false},{"id":"manifesto-1-318","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":318,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"最后，共产党人到处都努力争取全世界民主政党之间的团结和协调。","language":"中文","translation":false},{"id":"manifesto-1-319","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":319,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产党人不屑于隐瞒自己的观点和意图。他们公开宣布：他们的目的只有用暴力推翻全部现存的社会制度才能达到。让统治阶级在共产主义革命面前发抖吧。无产者在这个革命中失去的只是锁链。他们获得的将是整个世界。","language":"中文","translation":false},{"id":"manifesto-1-320","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":320,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"全世界无产者，联合起来！","language":"中文","translation":false},{"id":"manifesto-1-321","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":321,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卡·马克思和弗·恩格斯写于1847年12月-1848年1月底","language":"中文","translation":false},{"id":"manifesto-1-322","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":322,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1848年2月以小册子形式在伦敦出版","language":"中文","translation":false},{"id":"manifesto-1-323","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":323,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"选自《马克思恩格斯选集》第3版第1卷第399-435页","language":"中文","translation":false},{"id":"manifesto-1-324","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":324,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[1] 《1872年德文版序言》是马克思和恩格斯为《共产党宣言》新的德文版合写的第一篇序言。马克思和恩格斯在序言中明确指出，“不管最近25年来的情况发生了多大的变化，这个《宣言》中所阐述的一般原理整个说来直到现在还是完全正确的”；同时又强调，这些原理的实际运用，“随时随地都要以当时的历史条件为转移”（见本书第3页）。他们还谈到，由于情况的变化，由于有了法国二月革命特别是巴黎公社的实际经验，《宣言》的某些地方本来可以作一些修改，但考虑到《宣言》是一个历史文件，所以对内容未作修改。","language":"中文","translation":false},{"id":"manifesto-1-325","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":325,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《共产党宣言》新的德文版由《人民国家报》编辑部倡议，于1872年在莱比锡出版。这一版只对个别用词作了改动。——3。","language":"中文","translation":false},{"id":"manifesto-1-326","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":326,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[2] 共产主义者同盟是历史上第一个以科学社会主义为指导的无产阶级政党，1847年在伦敦成立。共产主义者同盟的前身是1836年成立的正义者同盟（见注57），这是一个主要由德国工人和手工业者组成的德国政治流亡者秘密革命组织，后期也有其他国家的人参加。随着形势的发展，正义者同盟的领导成员逐步认识到必须使同盟摆脱旧的密谋传统和方式，并且确信马克思和恩格斯的理论是正确的，遂于1847年邀请马克思和恩格斯参加正义者同盟，协助同盟改组。1847年6月，正义者同盟在伦敦召开代表大会，恩格斯出席了大会，按照他的倡议，同盟的名称改为共产主义者同盟，因此这次大会也是共产主义者同盟的第一次代表大会。大会批准了同盟的章程草案（见《马克思恩格斯全集》中文第1版第42卷第419-423页），并用“全世界无产者，联合起来！”的战斗口号取代了正义者同盟原来的“人人皆兄弟”的口号。同年11月29日-12月8日，同盟召开第二次代表大会，马克思和恩格斯出席了大会。大会通过了同盟的章程（见本书），并委托马克思和恩格斯起草同盟的纲领，这就是1848年2月问世的《共产党宣言》。","language":"中文","translation":false},{"id":"manifesto-1-327","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":327,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1848年2月法国爆发革命，在伦敦的同盟中央委员会于1848年2月底把同盟的领导权移交给了以马克思为首的布鲁塞尔区部委员会。3月初，马克思被驱逐出布鲁塞尔并迁居巴黎。同盟在巴黎成立新的中央委员会，马克思当选为中央委员会主席，恩格斯当选为中央委员。","language":"中文","translation":false},{"id":"manifesto-1-328","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":328,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1848年3月下半月至4月初，马克思、恩格斯和数百名德国工人（他们多半是共产主义者同盟盟员）回国参加已经爆发的德国革命。马克思和恩格斯在3月底写成的《共产党在德国的要求》（见《马克思恩格斯全集》中文第1版第5卷；参看本书第106-107页）是共产主义者同盟在这次革命中的政治纲领。同年6月，马克思和恩格斯创办了《新莱茵报》（见注77），该报成为革命的指导中心。","language":"中文","translation":false},{"id":"manifesto-1-329","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":329,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"欧洲1848-1849年革命失败后，共产主义者同盟进行了改组并继续开展活动。1850年夏，同盟中央委员会内部在斗争策略问题上发生严重分歧。以马克思和恩格斯为首的中央委员会多数派坚决反对维利希-沙佩尔集团提出的宗派主义、冒险主义的策略，反对该集团无视革命发展的客观规律和欧洲现实政治形势而主张立即发动革命。1850年9月中，维利希-沙佩尔集团的分裂活动最终导致同盟与该集团决裂。1851年5月，由于警察的迫害和大批盟员被捕，共产主义者同盟在德国的活动实际上已陷于停顿。1852年11月17日，科隆共产党人案件（见注13）宣判后不久，同盟根据马克思的建议宣告解散。","language":"中文","translation":false},{"id":"manifesto-1-330","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":330,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"共产主义者同盟在国际工人运动史上起了巨大的作用，它是培养无产阶级革命家的学校，很多共产主义者同盟盟员后来都积极参加了国际工人协会（见注14）的活动。——3、9、94、105、117、118、126。","language":"中文","translation":false},{"id":"manifesto-1-331","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":331,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[3] 二月革命指1848年2月爆发的法国资产阶级民主革命。代表金融资产阶级利益的“七月王朝”推行极端反动的政策，反对任何政治改革和经济改革，阻碍资本主义发展，加剧对无产阶级和农民的剥削，引起全国人民的不满；农业歉收和经济危机进一步加深了国内矛盾。1848年2月22-24日巴黎爆发革命，推翻了“七月王朝”，建立了资产阶级共和派的临时政府，宣布成立了法兰西第二共和国。法国二月革命在欧洲1848-1849年革命中具有重要影响。无产阶级和小资产阶级积极参加了这次革命，但革命果实却落到了资产阶级手里。——3、9、18、102、117、122、126。","language":"中文","translation":false},{"id":"manifesto-1-332","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":332,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[4] 《红色共和党人》（The Red Republican）是英国的一家周刊，宪章派左翼的机关报，1850年6-11月在伦敦出版，主编是乔·朱·哈尼。——3、9。","language":"中文","translation":false},{"id":"manifesto-1-333","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":333,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[5] 指1848年6月巴黎无产阶级的起义。二月革命后，无产阶级要求把革命推向前进，资产阶级共和派政府推行反对无产阶级的政策，6月22日颁布了封闭“国家工场”的挑衅性法令，激起巴黎工人的强烈反抗。6月23-26日，巴黎工人举行了大规模武装起义。6月25日，镇压起义的让·巴·菲·布雷亚将军在枫丹白露哨兵站被起义者打死，两名起义者后来被判处死刑。经过四天英勇斗争，起义被资产阶级共和派政府残酷镇压下去。马克思论述这次起义时指出：“这是分裂现代社会的两个阶级之间的第一次大规模的战斗。这是保存还是消灭资产阶级制度的斗争。”（见《马克思恩格斯选集》第3版第1卷第467页）——3、9、18、125。","language":"中文","translation":false},{"id":"manifesto-1-334","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":334,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[6] 《社会主义者报》（Le Socialiste）是美国的一家法文日报，1871年10月-1873年5月在纽约出版，国际法国人支部的机关报；海牙代表大会（1872年9月2-7日）以后与国际断绝了关系。1872年1-2月该报曾发表《共产党宣言》。——3、11。","language":"中文","translation":false},{"id":"manifesto-1-335","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":335,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[7] 巴黎公社是1871年法国无产阶级在巴黎建立的人类历史上第一个无产阶级政权。1871年3月18日，巴黎无产者举行武装起义，夺取了政权；28日巴黎公社宣告成立。公社打碎了资产阶级国家机器，废除常备军代之以人民武装，废除官僚制度代之以民主选举产生的、对选民负责的、受群众监督的公职人员。公社没收逃亡资本家的企业交给工人管理，并颁布一系列保护劳动者利益的法令。5月28日，巴黎公社在国内外反动势力的打击下遭到失败，总共只存在了72天。——4、13、126。","language":"中文","translation":false},{"id":"manifesto-1-336","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":336,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[8] 《1882年俄文版序言》是马克思和恩格斯为《共产党宣言》的第二个俄译本合写的序言。该译本由格·普列汉诺夫翻译。马克思和恩格斯在序言中强调：“《共产主义宣言》的任务，是宣告现代资产阶级所有制必然灭亡。”（见本书第6页）他们通过对俄美两国资本主义发展进程的分析，论证了自《共产党宣言》发表以来无产阶级运动不断扩大的趋势，指出俄国已经从欧洲全部反动势力的最后一支庞大后备军变成了欧洲革命运动的先进部队，并对当时俄国农村公社土地公有制的前途提出这样的设想：“假如俄国革命将成为西方无产阶级革命的信号而双方互相补充的话，那么现今的俄国土地公有制便能成为共产主义发展的起点。”（见本书第6页）","language":"中文","translation":false},{"id":"manifesto-1-337","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":337,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"这篇序言最初于1882年2月5日在俄国民意党人的《民意》杂志第8-9期用俄译文发表。附有这篇序言的《共产党宣言》俄文版单行本于1882年在日内瓦作为《俄国社会革命丛书》之一出版。1882年4月，德国社会民主党中央机关报《社会民主党人报》准备发表这篇序言，因找不到德文原稿，只好请帕·波·阿克雪里罗得将俄译文再转译成德文，于1882年4月13日发表在《社会民主党人报》第16号。恩格斯在《共产党宣言》1890年德文版序言中，全文引用了他本人由俄文转译成德文的这篇序言，个别地方与德文原稿略有差别。直到20世纪30年代，这篇序言的德文手稿才被重新发现。1939年莫斯科外国文书籍出版局出版的德文版《共产党宣言》首次按德文原文发表了这篇序言，本书刊出的序言就是据此翻译的。——5。","language":"中文","translation":false},{"id":"manifesto-1-338","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":338,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[9] 《钟声》（Колоколь）是俄国革命民主主义的报纸，1857-1865年由亚·伊·赫尔岑和尼·普·奥格辽夫用俄文在伦敦不定期出版，1865-1867年在日内瓦出版，1868-1869年改用法文出版，同时出版俄文版附刊。——5、11、15。","language":"中文","translation":false},{"id":"manifesto-1-339","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":339,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[10] 1881年3月13日民意党人刺杀沙皇亚历山大二世以后，亚历山大三世因害怕民意党人采取新的恐怖行动，终日藏匿在彼得堡附近的加特契纳行宫内，因而被人们戏谑地称为“加特契纳的俘虏”。——6、16。","language":"中文","translation":false},{"id":"manifesto-1-340","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":340,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[11] 《1883年德文版序言》是恩格斯为1883年在霍廷根-黎世出版的《共产党宣言》第三个德文版写的序言，该版本是马克思逝世后经恩格斯同意出版的第一个德文本。序言明确表述了贯穿《宣言》的基本思想：“每一历史时代的经济生产以及必然由此产生的社会结构，是该时代政治的和精神的历史的基础；因此（从原始土地公有制解体以来）全部历史都是阶级斗争的历史，即社会发展各个阶段上被剥削阶级和剥削阶级之间、被统治阶级和统治阶级之间斗争的历史；而这个斗争现在已经达到这样一个阶段，即被剥削被压迫的阶级（无产阶级），如果不同时使整个社会永远摆脱剥削、压迫和阶级斗争，就不再能使自己从剥削它压迫它的那个阶级（资产阶级）下解放出来。”（见本书第7页）恩格斯的这一表述，概括了唯物史观的主要内容。——7。","language":"中文","translation":false},{"id":"manifesto-1-341","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":341,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[12] 《1888年英文版序言》是恩格斯为1888年在伦敦出版的英文版《共产党宣言》写的序言。该版本由赛·穆尔翻译，恩格斯亲自校订并加了一些注释。恩格斯在序言中回顾了国际工人运动的历史和《宣言》在各国的传播史，指出：“《宣言》的历史在很大程度上反映着现代工人阶级运动的历史；现在，它无疑是全部社会主义文献中传播最广和最具有国际性的著作，是从西伯利亚到加利福尼亚的千百万工人公认的共同纲领。”（见本书第11页）恩格斯重申了1883年德文版序言所表述的《宣言》的基本思想，并强调“这一思想对历史学必定会起到像达尔文学说对生物学所起的那样的作用”（见本书第13页）。他还引录了1872年德文版序言的主要内容。——9。","language":"中文","translation":false},{"id":"manifesto-1-342","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":342,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[13] 科隆共产党人案件（1852年10月4日-11月12日）是普鲁士政府策动的一次挑衅性案件。共产主义者同盟（见注2）的11名成员被送交法庭审判，其罪名是“进行叛国性密谋”。被指控的证据是普鲁士警探们假造的中央委员会会议《原本记录》和其他一些伪造文件，以及警察局从已被开除出共产主义者同盟的维利希-沙佩尔冒险主义宗派集团那里窃得的一些文件。法庭根据伪造文件和虚假证词，判处七名被告三年至六年徒刑。马克思和恩格斯对这一案件的策动者的挑衅行为和普鲁士警察国家对付国际工人运动的卑鄙手段进行了彻底的揭露（参看马克思《揭露科隆共产党人案件》和恩格斯《最近的科隆案件》，《马克思恩格斯全集》中文第2版第11卷）。——10、18、94、114。","language":"中文","translation":false},{"id":"manifesto-1-343","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":343,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[14] 国际工人协会简称国际，后通称第一国际，是无产阶级第一个国际性的革命联合组织，1864年9月28日在伦敦成立。马克思参与了国际工人协会的创建，是它的实际领袖，恩格斯参加了国际后期的领导工作。在马克思和恩格斯的指导下，国际工人协会领导了各国工人的经济斗争和政治斗争，积极支持了被压迫民族的解放运动，坚决地揭露和批判了蒲鲁东主义、巴枯宁主义、拉萨尔主义、工联主义等错误思潮，促进了各国工人的国际团结。国际工人协会在1872年海牙代表大会以后实际上已停止了活动，1876年7月15日正式宣布解散。国际工人协会的历史意义在于它“奠定了工人国际组织的基础，使工人做好向资本进行革命进攻的准备”（见《列宁选集》第3版修订版第3卷第790页）。——10、18、94、115、125。","language":"中文","translation":false},{"id":"manifesto-1-344","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":344,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[15] 英国工联即英国工会。1824年英国工人获得了自由结社的权利，工联遂在英国普遍建立起来。工联是按行业组织的，加入工联的人必须是满师的技术工人，须缴纳很高的会费；工联设有全国性的领导机关；工联的任务是维护本行业熟练工人的经济利益。工联的机会主义领袖把无产阶级的斗争局限于经济斗争，鼓吹阶级调和。许多工联组织曾经加入国际。马克思和恩格斯从国际成立时起，就同工联领导人的机会主义，即工联主义进行了坚决的斗争。——10、18。","language":"中文","translation":false},{"id":"manifesto-1-345","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":345,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[16] 蒲鲁东派是法国小资产阶级社会主义者、无政府主义者蒲鲁东的信徒。蒲鲁东派从小资产阶级立场出发批判资本主义，幻想使小私有制万古长存；主张建立“交换银行”和发放无息贷款，以维护小生产者的私有制；宣传用改良的办法消除资本主义“坏的”方面，保留资本主义“好的”方面；反对无产阶级进行暴力革命和政治斗争，主张取消任何政府和国家。马克思和恩格斯在国际工人协会中对蒲鲁东派的机会主义路线进行了坚决的斗争。——10、18。","language":"中文","translation":false},{"id":"manifesto-1-346","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":346,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[17] 拉萨尔派是19世纪60-70年代德国工人运动中的机会主义派别，斐·拉萨尔的信徒，主要代表人物是约·巴·冯·施韦泽、威·哈森克莱维尔、威·哈赛尔曼等。该派的组织是1863年5月由拉萨尔创立的“全德工人联合会”。拉萨尔派反对暴力革命，认为只要进行议会斗争，争取普选权，就可以把普鲁士君主国家变为“自由的人民国家”；主张在国家帮助下建立生产合作社，把资本主义和平地改造为社会主义；支持普鲁士政府通过王朝战争自上而下地统一德国的政策。马克思和恩格斯同拉萨尔派的机会主义路线进行了坚决的斗争。","language":"中文","translation":false},{"id":"manifesto-1-347","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":347,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"1875年拉萨尔派与爱森纳赫派（参看注98）合并为德国社会主义工人党。——10、18、133。","language":"中文","translation":false},{"id":"manifesto-1-348","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":348,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[18] 1887年9月5-12日在英国斯旺西举行了工联年度代表大会，即斯旺西代表大会。这次代表大会通过了建立单独的工人政党等项决议。恩格斯提到的这句话引自斯旺西工联理事会主席比万在大会上的发言，比万担任这次代表大会的主席。这篇发言载于1887年9月17日伦敦《公益》周刊。——10、19。","language":"中文","translation":false},{"id":"manifesto-1-349","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":349,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[19] 《伍德赫尔和克拉夫林周刊》（Woodhull & Claflin’s Weekly）是美国的一家周刊，1870-1876年由资产阶级女权主义者维·伍德赫尔和田·克拉夫林在纽约出版。—11。","language":"中文","translation":false},{"id":"manifesto-1-350","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":350,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[20] 《共产党宣言》第二个俄文本的译者不是维·查苏利奇，而是格·瓦·普列汉诺夫。恩格斯于1894年曾在《〈论俄国的社会问题〉跋》中指出，《宣言》的第二个俄文本是普列汉诺夫翻译的（见《马克思恩格斯选集》第3版第4卷第313-314页）。——1l、15。","language":"中文","translation":false},{"id":"manifesto-1-351","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":351,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[21] 这里提到的《共产党宣言》丹麦文译本（1885年哥本哈根版）删去了一些重要的地方，因而不够完备；有些译文也不太确切。恩格斯在《宣言》1890年德文版序言中指出了这一点（见本书第17页）。——11。","language":"中文","translation":false},{"id":"manifesto-1-352","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":352,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[22] 劳·拉法格翻译的《共产党宣言》法文译本刊登在1885年8月29日-11月7日的《社会主义者报》上，以后又作为附录收入1886年在巴黎出版的梅尔麦著的《社会主义法国》。","language":"中文","translation":false},{"id":"manifesto-1-353","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":353,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《社会主义者报》（Le Socialiste）是法国的一家周报，1885年由茹·盖得在巴黎创办，1902年以前是工人党的机关报，后来是法国社会党机关报；19世纪80-90年代恩格斯曾为该报撰稿。——11、17。","language":"中文","translation":false},{"id":"manifesto-1-354","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":354,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[23] 《共产党宣言》西班牙文译本发表在1886年7-8月的《社会主义者报》上，并出版过单行本。","language":"中文","translation":false},{"id":"manifesto-1-355","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":355,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《社会主义者报》（El Socialista）是西班牙的一家周报，西班牙社会主义工人党的中央机关报，从1885年起在马德里出版。——11、17。","language":"中文","translation":false},{"id":"manifesto-1-356","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":356,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[24] 欧文派指英国空想社会主义者罗·欧文的拥护者。欧文认为，人是环境的产物，只有实现社会主义才能克服社会的一切罪恶。他曾在美国试办共产主义移民区，实行集体劳动和生产资料公有，最后宣告失败。欧文反对宪章运动，不主张工人开展政治斗争。认为靠知识的传播可以消除社会弊病，解决社会矛盾，并把希望寄托在统治者身上。——1、19、63。","language":"中文","translation":false},{"id":"manifesto-1-357","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":357,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[25] 傅立叶派指法国空想社会主义者沙·傅立叶的拥护者。傅立叶认为，现存制度应当由理想的和谐制度所取代。在这种和谐制度下，社会的基层单位是工农结合与城乡结合的生产消费协作社法郎吉（Phalange）。在法郎吉中，人人参加劳动，劳动者和资本家都可以入股，产品按资本、劳动和才能进行分配。协作社成员居住和劳动的场所称做法伦斯泰尔（Phalanstère）。傅立叶派在法国和美国都曾进行过法郎吉移民区实验，这些实验均以失败告终。——11、19、63。","language":"中文","translation":false},{"id":"manifesto-1-358","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":358,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[26] 埃·卡贝是法国空想共产主义者。他认为人类的不平等是违反自然规律的，人类最严重的错误是建立私有制。他揭露了资本主义的罪恶，主张废除私有制，建立公有制，实现人人平等和幸福的社会。但是，他反对暴力革命，主张通过和平宣传来改造资本主义社会。卡贝在1840年发表的《伊加利亚旅行记》中描绘了他的理想社会。——12、19。","language":"中文","translation":false},{"id":"manifesto-1-359","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":359,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[27] 威·魏特林是德国早期工人运动活动家，空想共产主义者。魏特林在1842年出版了《和谐与自由的保证》一书，抨击资本主义社会，提出了他的空想共产主义计划。他认为，理想的社会是和谐与自由的社会，在这个社会中，人人从事劳动，产品平均分配；他承认使用暴力实现社会革命的必要性。魏特林的学说是一种粗陋的平均共产主义的理论，在早期德国工人运动中起过一定的积极作用，但后来成为工人运动发展的障碍。——12、19、97、119、132。","language":"中文","translation":false},{"id":"manifesto-1-360","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":360,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[28] 关于“工人的解放应当是工人阶级自己的事情”这一思想，马克思和恩格斯在19世纪40年代以后的一系列著作中都表述过。这一思想在《国际工人协会共同章程》中是这样表述的：“工人阶级的解放应该由工人阶级自己去争取”（见《马克思恩格斯选集》第3版第3卷第171页）。——12、20。","language":"中文","translation":false},{"id":"manifesto-1-361","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":361,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[29] 《1890年德文版序言》是恩格斯为1890年在伦敦作为《社会民主主义丛书》之一出版的德文版《共产党宣言》写的序言。该版本是经恩格斯同意出版的《宣言》第四个德文本。它除了发表恩格斯的新序言外，还收入了1872年和1883年德文版序言。1890年11月28日《工人报》第48号在庆祝恩格斯七十寿辰的社论中也摘要刊登了这篇新序言。恩格斯在序言中再次回顾了国际工人运动的历史和《宣言》在各国的传播史，不仅全文引录了1882年俄文版序言，而且援引了1888年英文版序言的主要内容。——15。","language":"中文","translation":false},{"id":"manifesto-1-362","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":362,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[30] 《共产党宣言》1882年俄文版序言的德文原稿后来找到了。恩格斯在这里引用的序言是他亲自从俄文翻译成德文的，个别地方同德文原稿有细微差别。参看注8。——15。","language":"中文","translation":false},{"id":"manifesto-1-363","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":363,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[31] 日内瓦代表大会是国际工人协会于1866年9月3-8日在瑞士日内瓦举行的第一次代表大会。出席大会的有中央委员会，协会各支部以及英、法、德和瑞士的工人团体等的60名代表。大会批准了协会的章程和条例。由马克思执笔的《给临时中央委员会代表的关于若干问题的指示》（见《马克思恩格斯全集》中文第2版第21卷）作为中央委员会的正式报告提交大会讨论。参加大会的蒲鲁东主义者对《指示》几乎逐点加以反对。经过辩论，中央委员会的拥护者取得了胜利。《指示》九项内容中有六项作为大会决议通过，其中之一是要求法律规定八小时工作日，并把这一要求作为全世界工人阶级共同行动的纲领。","language":"中文","translation":false},{"id":"manifesto-1-364","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":364,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"巴黎工人代表大会是1889年7月14-20日在巴黎举行的国际社会主义工人代表大会，这次大会实际上是第二国际的成立大会。出席大会的有来自欧美22个国家和地区的393名代表。大会主席是前巴黎公社委员爱·瓦扬和德国社会民主党领导人威·李卜克内西。这次大会听取了各社会主义政党代表关于本国工人运动的报告并通过了一些重要决议，要求在法律上规定八小时工作日，规定五月一日为全世界无产阶级团结战斗的节日。——20。","language":"中文","translation":false},{"id":"manifesto-1-365","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":365,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[32] 《1892年波兰文版序言》是恩格斯为1892年由波兰社会党人的《黎明》杂志出版社在伦敦出版的波兰文版《共产党宣言》写的序言。恩格斯在序言中指出：“近来《宣言》在某种程度上已经成为测量欧洲大陆大工业发展的一种尺度。某一国家的大工业越发展，该国工人想要弄清他们作为工人阶级在有产阶级面前所处地位的愿望也就越强烈，工人中间的社会主义运动也就越扩大，对《宣言》的需求也就越增长。”（见本书第21页）他还指出，波兰的独立只有年轻的波兰无产阶级才能争得，而欧洲其余国家的工人也像波兰工人一样需要波兰的独立和复兴，因为“欧洲各民族的真诚的国际合作，只有当每个民族自己完全当家作主的时候才能实现”（见本书第22页）。这篇序言发表于1892年2月27日《黎明》杂志第35期。——21。","language":"中文","translation":false},{"id":"manifesto-1-366","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":366,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[33] 会议桌上的波兰指沙皇俄国根据1814-1815年维也纳会议的决定所吞并的波兰领土。维也纳会议后，波兰再度被俄、普、奥三国瓜分，沙皇俄国吞并了大部分波兰国土，成立了波兰王国，由沙皇亚历山大一世兼任国王。会议桌上的波兰或俄罗斯的波兰，即指这部分波兰领土。——21。","language":"中文","translation":false},{"id":"manifesto-1-367","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":367,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[34] 马克思在其他著作里，例如在《1859年的爱尔福特精神》（见《马克思恩格斯全集》中文第1版第13卷）一文中阐述过这样的思想：反动派在1848年以后扮演了特殊的革命遗嘱执行人的角色，不可避免地实现了革命的要求，尽管这是在一种滑稽可笑的歪曲的方式下进行的。——22、23。","language":"中文","translation":false},{"id":"manifesto-1-368","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":368,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[35] 《1893年意大利文版序言》是恩格斯应意大利社会党领袖菲·屠拉梯的请求，用法文为1893年意大利文版《共产党宣言》写的序言。该版本由蓬·贝蒂尼翻译，序言由屠拉梯翻译，于1893年由社会党理论刊物《社会评论》杂志社在米兰出版。恩格斯在序言中回顾了1848年革命以来的历史进程，特别是意大利、德国、匈牙利等民族取得统一和独立的进程，指出：“1848年革命虽然不是社会主义革命，但它毕竟为社会主义革命扫清了道路，为这个革命准备了基础。最近45年来，资产阶级制度在各国引起了大工业的飞速发展，同时造成了人数众多的、紧密团结的、强大的无产阶级；这样它就产生了——正如《宣言》所说——它自身的掘墓人。不恢复每个民族的独立和统一，那就既不可能有无产阶级的国际联合，也不可能有各民族为达到共同目的而必须实行的和睦的与自觉的合作。”（见本书第24页）——23。","language":"中文","translation":false},{"id":"manifesto-1-369","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":369,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[36] 1848年3月18日米兰人民举行了反对奥地利统治的武装起义，赶走了奥地利军队，成立了资产阶级自由派和民主派领导的临时政府，推动了意大利其他各地的革命。","language":"中文","translation":false},{"id":"manifesto-1-370","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":370,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"同一天，柏林人民也发动了武装起义，迫使国王宣布立即召开国民议会，制定宪法，撤出城内驻军，改组政府。——23。","language":"中文","translation":false},{"id":"manifesto-1-371","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":371,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[37] 民族大迁徙指公元3-7世纪日耳曼、斯拉夫及其他部落向罗马帝国的大规模迁徙。4世纪上半叶，日耳曼部落中的西哥特人因遭到匈奴人的进攻侵入罗马帝国。经过长期的战争，西哥特人于5世纪在西罗马帝国境内定居下来，建立了自己的国家。日耳曼人的其他部落也相继在欧洲和北非建立了独立的国家。民族大迁徙对摧毁罗马帝国的奴隶制度和推动西欧封建制度的产生起了重要的作用。——30。","language":"中文","translation":false},{"id":"manifesto-1-372","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":372,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[38] 十字军征讨指11-13世纪西欧天主教会、封建主和大商人打着从伊斯兰教徒手中解放圣地耶路撒冷的宗教旗帜，主要对东地中海沿岸伊斯兰教国家发动的侵略战争。因参加者的衣服上缝有红十字，故称“十字军”。十字军征讨前后共八次，历时近200年，最后以失败而告终。十字军征讨给东方国家的人民带来了深重的灾难，也使西欧国家的人民遭受惨重的牺牲，但是，它在客观上也对东西方的经济和文化交流起到了一定的促进作用。——30。","language":"中文","translation":false},{"id":"manifesto-1-373","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":373,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[39] 马克思和恩格斯在19世纪40-50年代，即马克思制定出剩余价值理论以前所写的著作中使用过“劳动价值”、“劳动价格”、“出卖劳动”这样的概念。1891年，恩格斯在为马克思的《雇佣劳动与资本》这本小册子所写的导言中指出：“用后来的著作中的观点来衡量”，这些概念“是不妥当的，甚至是不正确的”（见《马克思恩格斯选集》第3版第1卷第318页）。马克思和恩格斯在后来的著作中使用的是“劳动力价值”和“劳动力价格”、“出卖劳动力”等概念。——34、70、76。","language":"中文","translation":false},{"id":"manifesto-1-374","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":374,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[40] 英国工人阶级从18世纪末开始争取用立法手段限制工作日，从19世纪30年代起，广大无产阶级群众投入争取十小时工作日的斗争。十小时工作日法案是英国议会在1847年6月8日通过的，作为法律于1848年5月1日起生效。该法律将妇女和儿童的日劳动时间限制为10小时。但是，许多英国工厂主并不遵守这项法律，他们寻找种种借口把工作日从早晨5时半延续到晚上8时半。工厂视察员伦·霍纳的报告就是很好的证明（参看《马克思恩格斯文集》第5卷第335页）。","language":"中文","translation":false},{"id":"manifesto-1-375","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":375,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"恩格斯在《十小时工作日问题》和《英国的十小时工作日法》（见《马克思恩格斯全集》中文第2版第10卷）中对该法案作了详细的分析。关于英国工人阶级争取正常工作日的斗争，马克思在《资本论》第一卷第八章（见《马克思恩格斯文集》第5卷第267-350页）中作了详细考察。——37。","language":"中文","translation":false},{"id":"manifesto-1-376","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":376,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[41] 七月革命即1830年7月爆发的法国资产阶级革命。1814年拿破仑第一帝国垮台后，代表大土地贵族利益的波旁王朝复辟，竭力恢复封建专制统治，压制资本主义发展，限制言论自由和新闻出版自由，加剧了资产阶级同贵族地主的矛盾，激起了人民的反抗。1830年7月27-29日巴黎爆发革命，推翻了波旁王朝。金融资产阶级攫取了革命果实，建立了以奥尔良公爵路易-菲力浦为首的代表金融贵族和大资产阶级利益的“七月王朝”。——52。","language":"中文","translation":false},{"id":"manifesto-1-377","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":377,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[42] 改革运动指英国工业资产阶级发动的议会改革运动。英国资产阶级为了同土地贵族争夺政治权力，在19世纪20年代末提出了改革议会选举制度的要求，经过几年斗争，在人民群众的支持下，迫使英国议会于1832年6月通过了选举法改革法案。这次改革削弱了土地贵族和金融贵族的政治垄断，加强了工业资产阶级在议会中的地位。但是，由于财产资格的限制，为争取选举制度改革而斗争的主力军工人和手工业者仍未获得选举权。——52。","language":"中文","translation":false},{"id":"manifesto-1-378","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":378,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[43] 正统派是法国代表大土地贵族和高级僧侣利益的波旁王朝（1589-1792年和1814-1830年）长系的拥护者。1830年波旁王朝第二次被推翻以后，正统派结成政党。在反对以金融贵族和大资产阶级为支柱的当政的奥尔良王朝时，一部分正统派常常抓住社会问题进行蛊惑宣传，标榜自己维护劳动者的利益，使他们不受资产者的剥削。——53。","language":"中文","translation":false},{"id":"manifesto-1-379","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":379,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[44] “青年英国”是由英国托利党中的一些政治活动家和著作家组成的集团，成立于19世纪40年代初，主要代表人物是本·迪斯累里及托·卡莱尔等。他们维护土地贵族的利益，对资产阶级日益增长的经济势力和政治势力不满，企图用蛊惑手段把工人阶级置于自己的影响之下，并利用他们反对资产阶级。——53。","language":"中文","translation":false},{"id":"manifesto-1-380","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":380,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[45] 宪章派指宪章运动的参加者。宪章运动是19世纪30-50年代中期英国工人的政治运动，其口号是争取实施人民宪章。人民宪章要求实行普选权并为保障工人享有此项权利而创造种种条件。宪章派的领导机构是“宪章派全国协会”，机关报是《北极星报》，左翼代表人物是乔·哈尼、厄·琼斯等。恩格斯称宪章派是“近代第一个工人政党”（见《马克思恩格斯选集》第3版第3卷第768页）。按照列宁所下的定义，宪章运动是“世界上第一次广泛的、真正群众性的、政治上已经成型的无产阶级革命运动”（见《列宁选集》第3版修订版第3卷第792页）。宪章运动出现过三次高潮，其衰落的原因在于英国工商业垄断的加强，工人阶级政治上的不成熟，以及英国资产阶级用超额利润收买英国工人阶级上层（“工人贵族”），造成了英国工人阶级中机会主义倾向的增长，其表现就是工联领袖放弃了对宪章运动的支持。——63、92、99、101。","language":"中文","translation":false},{"id":"manifesto-1-381","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":381,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[46] 改革派又称《改革报》派，是聚集在法国《改革报》周围的一个政治集团，包括一些小资产阶级民主共和主义者和小资产阶级社会主义者。其首领是赖德律-洛兰和路易·勃朗等人。他们主张建立共和国并实行民主改革和社会改革。","language":"中文","translation":false},{"id":"manifesto-1-382","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":382,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"《改革报》（La Réforme）是法国的一家日报，小资产阶级民主派、小资产阶级共和党人和小资产阶级社会主义者的机关报，1843年7月-1850年l月在巴黎出版，创办人和主编是赖德律-洛兰和多·弗·阿拉戈，编辑有赖德律-洛兰和斐·弗洛孔等，1847年10月-1848年1月曾刊登恩格斯的许多文章。——63、64、102。","language":"中文","translation":false},{"id":"manifesto-1-383","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":383,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[47] 北美土地改革派即全国土地改革派，又称美国“全国改革协会”，成立于1845年，是一个以手工业者和工人为核心的政治团体，宗旨是无偿地分给每一个劳动者一块土地。19世纪40年代后半期，协会宣传土地改革，反对种植场奴隶主和土地投机分子，并提出实行十小时工作制、废除奴隶制、取消常备军等民主要求。许多德国手工业侨民参加了这一土地改革运动。——64、93。","language":"中文","translation":false},{"id":"manifesto-1-384","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":384,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"[48] 波兰人民为争取民族解放曾准备在1846年2月举行起义。起义的主要发起人是波兰的革命民主主义者埃·邓波夫斯基等人。但是，由于波兰小贵族的背叛以及起义的领袖遭普鲁士警察逮捕，总起义未能成功。仅在从1815年起由奥地利、普鲁士和俄国共管的克拉科夫举行了起义，起义者在2月22日获胜并建立了国民政府，发表了废除封建徭役的宣言。克拉科夫起义在1846年3月初被镇压。1846年11月，奥地利、普鲁士和俄国签订了关于把克拉科夫并入奥地利帝国的条约。——65。","language":"中文","translation":false},{"id":"manifesto-1-385","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":385,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"阿尔布雷希特，卡尔（Albrecht，Karl 1788-1844）——德国商人，曾因参加“蛊惑者”的反政府运动被判处六年徒刑；1841年移居瑞士，在那里以宗教神秘主义形式鼓吹类似魏特林的空想共产主义思想。——103。","language":"中文","translation":false},{"id":"manifesto-1-386","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":386,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"埃尔哈德，约翰·路德维希·阿尔伯特（Erhard，Johann Ludwig Albert生于1820年）——德国店员，共产主义者同盟盟员，科隆共产党人案件（1852）的被告之一，被陪审法庭宣告无罪。——114。","language":"中文","translation":false},{"id":"manifesto-1-387","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":387,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"埃卡留斯，约翰·格奥尔格（Eccarius，Johann Georg 1818-1889）——德国工人运动和国际工人运动的活动家，工人政论家，职业是裁缝；侨居伦敦，正义者同盟盟员，后为共产主义者同盟盟员，伦敦德意志工人共产主义教育协会的领导人之一，国际总委员会委员（1864-1872），总委员会总书记（1867-1871年5月），美国通讯书记（1870-1872），国际各次代表大会和代表会议的代表；1872年以前支持马克思，1872年海牙代表大会后成为英国工联的改良派领袖，后为工联主义运动的活动家。——104。","language":"中文","translation":false},{"id":"manifesto-1-388","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":388,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"埃斯特鲁普，雅科布·布伦农·斯卡文尼乌斯（Estrup，Jacob Brönnum Scavenius 1825-1913）——丹麦国务活动家，保守党人；曾任内务大臣（1865-1869），财政大臣和首相（1875-1894）。——131。","language":"中文","translation":false},{"id":"manifesto-1-389","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":389,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"艾韦贝克，奥古斯特·海尔曼（Ewerbeck，August Hermann 1816-1860）——德国医生和政论家，1841-1846年领导巴黎正义者同盟人民议事会，正义者同盟巴黎支部的领导人，后为共产主义者同盟盟员，1850年退出同盟；1848-1849年革命时期是在巴黎建立的德国人协会书记和《新莱茵报》驻巴黎通讯员；50年代是语言教师和图书管理员。——102、113。","language":"中文","translation":false},{"id":"manifesto-1-390","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":390,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"奥托，卡尔·武尼巴德（Otto，Karl Wunibald 1808-1862以后）——德国化学家，1848-1849年革命的参加者，科隆工人联合会会员，共产主义者同盟科隆支部成员，1850-1851年是同盟中央委员会委员，中央委员会派往莱比锡和德累斯顿的特使（1851），科隆共产党人案件（1852）的被告之一，被判五年徒刑，1856年9月获释。——113-114。","language":"中文","translation":false},{"id":"manifesto-1-391","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":391,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"巴贝夫，格拉古（Babeuf，Gracchus原名弗朗索瓦·诺埃尔François-Noёl 1760-1797）——法国革命家，空想平均共产主义的代表人物，1796年是平等派密谋的组织者；密谋失败后被处死。——60、95。","language":"中文","translation":false},{"id":"manifesto-1-392","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":392,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"巴尔贝斯，西吉斯蒙·奥古斯特·阿尔芒（Barbès，Sigismond Auguste Armand 1809-1870）——法国革命家，小资产阶级民主主义者，七月王朝时期秘密革命团体四季社的领导人之一；第二共和国时期是制宪议会议员（1848），因参加1848年五月十五日事件被判处无期徒刑，1854年遇赦；后流亡荷兰，不久即脱离政治活动。——95。","language":"中文","translation":false},{"id":"manifesto-1-393","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":393,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"巴枯宁，米哈伊尔·亚历山大罗维奇（Бакунин，Михаил Александрович 1814-1876）——俄国无政府主义和民粹主义创始人和理论家；1840年起侨居国外，曾参加德国1848-1849年革命；1849年因参与领导德累斯顿起义被判死刑，后改为终身监禁；1851年被引渡给沙皇政府，囚禁期间向沙皇写了《忏悔书》；1861年从西伯利亚流放地逃往伦敦；1868年参加第一国际活动后，在国际内部组织秘密团体——社会主义民主同盟，妄图夺取总委员会的领导权；由于进行分裂国际的阴谋活动，1872年在海牙代表大会上被开除出第一国际。——5、11、15、18。","language":"中文","translation":false},{"id":"manifesto-1-394","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":394,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"鲍威尔，安德烈亚斯·亨利希（Bauer，Andreas Heinrich约生于1813年）——德国工人运动活动家，职业是鞋匠；1838年在巴黎成为正义者同盟盟员，1842年被驱逐出法国；曾一度担任伦敦德意志工人共产主义教育协会主席，共产主义者同盟中央委员会委员（1847-1850），社会民主主义流亡者委员会的司库；1850年春是同盟派往德国的特使；1851年流亡澳大利亚。——95、96、107、111、113。","language":"中文","translation":false},{"id":"manifesto-1-395","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":395,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"贝克，亚历山大（Beck，Alexander）——德国裁缝，正义者同盟盟员，1846年底因同盟案件被捕；科隆共产党人案件（1852）的证人。——98。","language":"中文","translation":false},{"id":"manifesto-1-396","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":396,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"贝克尔，奥古斯特（Becker，August 1814-1871）——德国政论家，正义者同盟瑞士支部的盟员，魏特林的拥护者；德国1848-1849年革命的参加者；50年代初流亡美国，为民主派报纸撰稿。——97。","language":"中文","translation":false},{"id":"manifesto-1-397","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":397,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"贝克尔，海尔曼·亨利希（Becker，Hermann Heinrich“红色贝克尔”der “rote Becker” 1820-1885）——德国地方法院见习法官和政论家，科隆工人和业主联合会的领导人之一，民主主义者莱茵区域委员会委员（1848-1849），《西德意志报》发行人（1849年5月-1850年7月）；1850年底起为共产主义者同盟盟员，科隆共产党人案件（1852）的被告之一，被判五年徒刑；60年代是进步党人，后为民族自由党人；普鲁士第二议院议员（1862-1866），国会议员（1867-1874）；1875年起为科隆市长。——113、114。","language":"中文","translation":false},{"id":"manifesto-1-398","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":398,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"倍倍尔，奥古斯特（Bebel，August 1840-1913）——德国工人运动和国际工人运动的活动家，职业是旋工；德国工人协会联合会创始人之一，1867年起为主席；第一国际会员，1867年起为国会议员，1869年是德国社会民主工党创始人和领袖之一，《社会民主党人报》创办人之一；曾进行反对拉萨尔派的斗争，普法战争时期站在无产阶级国际主义立场，捍卫巴黎公社；1889、1891和1893年国际社会主义工人代表大会代表；第二国际的活动家，在19世纪90年代和20世纪初反对改良主义和修正主义；马克思和恩格斯的朋友和战友。——133。","language":"中文","translation":false},{"id":"manifesto-1-399","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":399,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"俾斯麦公爵，奥托（Bismarck[Bismark]，Otto Fürst von 1815-1898）——普鲁士和德国国务活动家和外交家，普鲁士容克的代表；曾任驻彼得堡大使（1859-1862）和驻巴黎大使（1862）；普鲁士首相（1862-1872和1873-1890），北德意志联邦首相（1867-1871）和德意志帝国首相（1871-1890）；1870年发动普法战争，1871年支持法国资产阶级镇压巴黎公社；主张在普鲁士领导下“自上而下”统一德国；曾采取一系列内政措施，捍卫容克和大资产阶级的联盟；1878年颁布反社会党人非常法。——22、114、121、131。","language":"中文","translation":false},{"id":"manifesto-1-400","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":400,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"比万（Bevan）——英国斯旺西市工联理事会主席，1887年为在该市举行的工联代表大会主席。——10、19。","language":"中文","translation":false},{"id":"manifesto-1-401","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":401,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"毕尔格尔斯，约翰·亨利希（Bürgers，Johann Heinrich 1820-1878）——德国政论家，《莱茵报》撰稿人（1842-1843），1846年参加共产主义通讯委员会的活动，1848-1849年是《新莱茵报》编辑；共产主义者同盟盟员，1850-1851年是共产主义者同盟中央委员会委员，科隆共产党人案件（1852）的被告之一，被判六年徒刑；后为民族自由党人；60年代为民族联盟盟员和杜塞尔多夫《莱菌报》的编辑。——113、114。","language":"中文","translation":false},{"id":"manifesto-1-402","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":402,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"毕希纳，格奥尔格（Büchner，Georg 1813-1837）——德国剧作家，革命民主主义者，1834年吉森秘密的革命组织人权协会的组织者之一，《告黑森农民书》的作者，曾提出“给茅屋和平，对宫廷宣战”的口号。——96。","language":"中文","translation":false},{"id":"manifesto-1-403","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":403,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"庇护九世（Pius IX[Pio Nono]世俗名乔万尼·马里亚·马斯塔伊-费雷蒂Giovanni Maria Mastai-Ferretti 1792-1878）——罗马教皇（1846-1878）。——26。","language":"中文","translation":false},{"id":"manifesto-1-404","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":404,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"波尔恩，斯蒂凡（Borm，Stephan真名西蒙·布特尔米尔希Simon Buttermilch 1824-1898）——德国排字工人，共产主义者同盟盟员；《新莱茵报》通讯员（1848年6-8月）；德国1848-1849年革命的参加者，工人兄弟会组织者和领袖；1850年被开除出共产主义者同盟；革命后脱离工人运动。——109、110。","language":"中文","translation":false},{"id":"manifesto-1-405","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":405,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"波拿巴，路易——见拿破仑第三。","language":"中文","translation":false},{"id":"manifesto-1-406","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":406,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"伯恩施太德，阿达尔贝特（Bornstedt，Adalbert 1808-1851）——德国政论家，小资产阶级民主主义者；《德意志-布鲁塞尔报》的创办人和编辑（1847-1848），1848年二月革命后是巴黎德意志民主协会领导人；曾为共产主义者同盟盟员，后被开除出同盟（1848年3月）；巴黎德国流亡者志愿军团组织者之一；曾与警察局有联系。——108。","language":"中文","translation":false},{"id":"manifesto-1-407","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":407,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"伯恩施太因，阿尔诺德·伯恩哈德·卡尔（Börnstein，Arnold Bernhard Karl 1808-1849）——德国小资产阶级民主主义者，巴黎德意志民主协会领导人，巴黎德国流亡者志愿军团军事领导人。——108。","language":"中文","translation":false},{"id":"manifesto-1-408","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":408,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"勃朗，路易（Blanc，Louis 1811-1882）——法国小资产阶级社会主义者，新闻工作者和历史学家；1848年临时政府成员和卢森堡宫委员会主席；采取同资产阶级妥协的立场；1848年8月流亡英国，后为伦敦的法国布朗基派流亡者协会的领导人；1871年国民议会议员，反对巴黎公社。——64、109、112、133。","language":"中文","translation":false},{"id":"manifesto-1-409","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":409,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"布朗基，路易·奥古斯特（Blanqui，Louis-Auguste 1805-1881）——法国革命家，空想共产主义者，主张通过密谋性组织用暴力夺取政权和建立革命专政；许多秘密社团和密谋活动的组织者，1830年七月革命和1848年二月革命的参加者，秘密的四季社的领导人，1839年五月十二日起义的组织者，同年被判处死刑，后改为无期徒刑；1848-1849年革命时期是法国无产阶级运动的领袖；巴黎1870年十月三十一日起义的领导人，巴黎公社时期被反动派囚禁在凡尔赛，曾缺席当选为公社委员；一生中有36年在狱中度过。——95。","language":"中文","translation":false},{"id":"manifesto-1-410","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":410,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"布伦奇里，约翰·卡斯帕尔（Bluntschli，Johann Caspar 1808-1881）——瑞士法学家和政治家；对革命运动参加者实行警察迫害的策划者之一；1843年为苏黎世州政府设立的瑞士境内德国共产主义流亡者活动调查委员会委员和委员会于1843年公布的工作报告的起草人。——119。","language":"中文","translation":false},{"id":"manifesto-1-411","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":411,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"查苏利奇，维拉·伊万诺夫娜（Засулич，Вера Ивановна 1851-1919）——俄国民粹运动、社会民主主义运动的活动家，劳动解放社（1883）的创始人之一；后来转到孟什维克立场。——11、15。","language":"中文","translation":false},{"id":"manifesto-1-412","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":412,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"达尔文，查理·罗伯特（Darwin，Charles Robert 1809-1882）——英国自然科学家，科学的生物进化论的奠基人。——7、13。","language":"中文","translation":false},{"id":"manifesto-1-413","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":413,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"丹尼尔斯，罗兰特（Daniels，Roland 1819-1855）——德国工人运动活动家，职业是医生，1846年参加共产主义通讯委员会的活动；共产主义者同盟盟员和领导人之一，1850年起为同盟科隆中央委员会委员；科隆共产党人案件（1852）的被告之一，被陪审法庭宣告无罪；第一批尝试把辩证唯物主义运用到自然科学领域的人之一；马克思和恩格斯的朋友。——113、114。","language":"中文","translation":false},{"id":"manifesto-1-414","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":414,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"但丁·阿利格埃里（Dante Alighieri 1265-1321）——意大利诗人。——24、134。","language":"中文","translation":false},{"id":"manifesto-1-415","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":415,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"杜林，欧根·卡尔（Dühring，Eugen Karl 1833-1921）——德国折中主义哲学家和庸俗经济学家，小资产阶级社会主义者，形而上学者；在哲学上把唯心主义、庸俗唯物主义和实证论结合在一起；在自然科学和文学方面也有所著述；1863-1877年为柏林大学非公聘讲师；70年代他的思想曾对德国社会民主党部分党员产生过较大影响。——128。","language":"中文","translation":false},{"id":"manifesto-1-416","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":416,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"斐迪南一世（Ferdinand I 1793-1875）——奥地利皇帝（1835-1848）。——23。","language":"中文","translation":false},{"id":"manifesto-1-417","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":417,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"费奈迭，雅科布（Venedey，Jakob 1805-1871）——德国作家、政论家和政治活动家，小资产阶级民主主义者；30年代是巴黎流亡者同盟领导人，1848-1849年是预备议会议员和法兰克福国民议会议员，属于左派；1848-1849年革命后成为自由派。——95。","language":"中文","translation":false},{"id":"manifesto-1-418","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":418,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"弗莱里格拉特，斐迪南（Freiligrath，Ferdinand 1810-1876）——德国诗人，1848-1849年为《新莱茵报》编辑，共产主义者同盟盟员；50年代脱离革命斗争，50-60年代为瑞士银行伦敦分行职员。——114。","language":"中文","translation":false},{"id":"manifesto-1-419","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":419,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"弗洛孔，斐迪南（Flocon，Ferdinand 1800-1866）——法国政治活动家和政论家，小资产阶级民主主义者，《改革报》编辑，1848年为临时政府成员；山岳党人；1851年十二月二日政变后被驱逐出法国。——108。","language":"中文","translation":false},{"id":"manifesto-1-420","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":420,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"傅立叶，沙尔（Fourier，Charles 1772-1837）——法国空想社会主义者。——11、19、60、63。","language":"中文","translation":false},{"id":"manifesto-1-421","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":421,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"戈克，阿曼德（Goegg，Amand 1820-1897）——德国海关官员、政论家和新闻工作者，小资产阶级民主主义者，1848-1849年革命的参加者，1849年是巴登临时政府财政部长，革命失败后流亡国外；1862年返回德国；日内瓦和平和自由同盟的创建人之一，国际会员；70年代加入德国社会民主党。——112。","language":"中文","translation":false},{"id":"manifesto-1-422","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":422,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"格律恩，卡尔（Grün，Karl笔名恩斯特·冯·德尔·海德Ernst von der Haide 1817-1887）——德国小资产阶级政论家，接近青年德意志和青年黑格尔派，40年代中是“真正的”社会主义的主要代表人物；普鲁士制宪议会议员（1848），属于左翼，普鲁士第二议院议员（1849）；1851年起流亡比利时，1861年回到德国，曾在美因河畔法兰克福高等商业工艺学校任艺术史、文学史和哲学史教授（1862-1865）；1870年到维也纳；1874年出版路·费尔巴哈的书信集和遗著。——58。","language":"中文","translation":false},{"id":"manifesto-1-423","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":423,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"哈克斯特豪森男爵，奥古斯特·弗兰茨（Haxthausen，August Franz Freiherr von 1792—1866）——普鲁士官员和作家，联合议会议员（1847-1848），后为普鲁土第一议院议员；写有描述普鲁士和俄国土地关系中当时还残存的土地公社所有制方面的著作。—27。","language":"中文","translation":false},{"id":"manifesto-1-424","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":424,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"哈林，哈罗·保尔（Harring，Harro Paul 1798-1870）——德国作家，小资产阶级激进派；1828年起曾数度侨居国外。——103。","language":"中文","translation":false},{"id":"manifesto-1-425","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":425,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"哈尼，乔治·朱利安（Harney，George Julian 1817-1897）——英国工人运动活动家，宪章派左翼领袖；正义者同盟盟员，后为共产主义者同盟盟员；民主派兄弟协会创建人之一，《北极星报》编辑，《民主评论》、《人民之友》、《红色共和党人》等宪章派刊物的出版者；1862-1888年曾数度住在美国；国际会员；曾同马克思和恩格斯保持友好联系；50年代初和小资产阶级民主派接近，一度同工人运动中的革命派疏远。——9、102。","language":"中文","translation":false},{"id":"manifesto-1-426","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":426,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"海德——见沃尔弗，弗里德里希·威廉。","language":"中文","translation":false},{"id":"manifesto-1-427","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":427,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"海尔维格，格奥尔格（Herwegh，Georg 1817-1875）——德国诗人，小资产阶级民主主义者；1842年起成为马克思的朋友，《莱茵报》等多家报刊的撰稿人；1848年二月革命后是巴黎德意志民主协会领导人，巴黎德国流亡者志愿军团组织者之一；1848-1849年革命的参加者，后长期流亡瑞士；1869年起为德国社会民主工党（爱森纳赫派）党员。——108。","language":"中文","translation":false},{"id":"manifesto-1-428","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":428,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"豪普特，海尔曼·威廉（Haupt，Hermann Wilhelm约生于1831年）——德国店员，维护帝国宪法运动的参加者（1849），运动失败后流亡瑞士，后流亡英国；伦敦德意志工人共产主义教育协会会员，1850年10月在汉堡成为共产主义者同盟盟员，科隆共产党人案件（1852）的被告之一，在审讯期间作了叛卖性的供述，审判前即被释放，1852年迁居巴西。——113。","language":"中文","translation":false},{"id":"manifesto-1-429","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":429,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"赫尔岑，亚历山大·伊万诺维奇（Герцен，Александр Иванович 1812-1870）——俄国唯物主义哲学家、政论家和作家，革命民主主义者，1847年流亡法国，1852年移居伦敦，在英国建立“自由俄国印刷所”，并出版《北极星》定期文集和《钟声》报。——11。","language":"中文","translation":false},{"id":"manifesto-1-430","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":430,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"黑格尔，乔治·威廉·弗里德里希（Hegel，Georg Willelm Friedrich 1770-1831）——德国古典哲学的主要代表。——104、132。","language":"中文","translation":false},{"id":"manifesto-1-431","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":431,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"基佐，弗朗索瓦·皮埃尔·吉约姆（Guizot，François-Pierre-Guillaume 1787-1874）——法国政治活动家和历史学家，奥尔良党人；1812年起任巴黎大学历史系教授，七月王朝时期是立宪君主派领袖，历任内务大臣（1832-1836）、教育大臣（1836-1837）、外交大臣（1840-1848）和首相（1847-1848）；代表大金融资产阶级的利益。——26、120。","language":"中文","translation":false},{"id":"manifesto-1-432","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":432,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"金克尔，哥特弗里德·约翰（Kinkel，Gottfried Johann 1815-1882）——德国诗人、作家和政论家，小资产阶级民主主义者，1849年巴登-普法尔茨起义的参加者，被普鲁士法庭判处无期徒刑，1850年在卡·叔尔茨帮助下越狱逃跑，流亡英国；在伦敦的德国小资产阶级流亡者的领袖，《海尔曼》周报编辑（1859）；反对马克思和恩格斯。—112。","language":"中文","translation":false},{"id":"manifesto-1-433","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":433,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卡贝，埃蒂耶纳（Cabet，Etienne人称卡贝老爹Père Cabet 1788-1856）——法国法学家和政论家，法国工人共产主义一个流派的创始人，和平空想共产主义的代表人物，《人民报》的出版者（1833-1834）；流亡英国（1834-1839）；《1841年人民报》的出版者（1841-1851）；曾尝试在美洲建立共产主义移民区（1848-1856），以实现其在1848年出版的小说《伊加利亚旅行记》中阐述的理论。——12、19、63。","language":"中文","translation":false},{"id":"manifesto-1-434","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":434,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卡佩，路易——见路易十六。","language":"中文","translation":false},{"id":"manifesto-1-435","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":435,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"凯利-威士涅威茨基，弗洛伦斯（Kelly-Wischnewetzky，Florence 1859-1932）——美国社会主义者，后为资产阶级改良主义者，曾将恩格斯的《英国工人阶级状况》一书译成英文；1892年以前为波兰流亡者拉·威士涅威茨基的妻子。——13。","language":"中文","translation":false},{"id":"manifesto-1-436","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":436,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"科苏特，拉约什（路易，路德维希）（Kossuth，Lajos[Louis，Ludwig] 1802-1894）——匈牙利政治活动家，匈牙利民族解放运动的领袖，1848-1849年革命时期领导资产阶级民主派，匈牙利革命政府首脑，革命失败后流亡国外；50年代曾向波拿巴集团求援。——112。","language":"中文","translation":false},{"id":"manifesto-1-437","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":437,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"克莱因，约翰·雅科布（Klein，Johann Jacob 1817-约1897）——德国医生，共产主义者同盟盟员，科隆共产党人案件（1852）的被告之一，被陪审法庭宣告无罪；60年代初曾参加德国工人运动。——114。","language":"中文","translation":false},{"id":"manifesto-1-438","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":438,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"克利盖，海尔曼（Kriege，Hermann 1820-1850）——德国新闻工作者，正义者同盟盟员；“真正的”社会主义的代表人物；1845年前往纽约，在那里出版《人民代言者报》，宣传“真正的”社会主义思想，受到马克思和恩格斯的批判；1848年返回德国，成为德意志民主协会中央委员会委员；1848-1849年革命失败后又一次流亡美国。——102-104。","language":"中文","translation":false},{"id":"manifesto-1-439","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":439,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"库尔曼，格奥尔格（Kuhlmann，Georg生于1812年）——奥地利江湖医生，自命是“预言家”；40年代利用宗教词句在瑞士的德国魏特林派手工业者中间宣传“真正的”社会主义的思想；后来证实他是奥地利政府的密探。——103。","language":"中文","translation":false},{"id":"manifesto-1-440","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":440,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"拉弗尔，约翰（Lovell，John）——美国出版商和书商，曾出版恩格斯的《英国工人阶级状况》一书。——13。","language":"中文","translation":false},{"id":"manifesto-1-441","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":441,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"拉马丁，阿尔丰斯（Lamartine，Alphonse 1790-1869）——法国诗人，历史学家和政治活动家，40年代为温和的资产阶级共和派领袖；第二共和国时期任外交部长（1848），临时政府的实际上的首脑。——108。","language":"中文","translation":false},{"id":"manifesto-1-442","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":442,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"拉萨尔，斐迪南（Lassalle，Ferdinand 1825-1864）——德国工人运动中的机会主义代表，1848-1849年革命的参加者；全德工人联合会创始人之一和主席（1863）；写有古典古代哲学史、法学史和文学方面的著作。——10、18、19、121、124、133。","language":"中文","translation":false},{"id":"manifesto-1-443","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":443,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"赖德律（赖德律-洛兰），亚历山大·奥古斯特（Ledru [Ledru-Rollin]，Alexandre-Auguste 1807-1874）——法国政论家和政治活动家，小资产阶级民主派领袖，《改革报》编辑；第二共和国时期任临时政府内务部长和执行委员会委员（1848），制宪议会和立法议会议员（1848-1849），在议会中领导山岳党；1849年六月十三日示威游行后流亡英国，1869年回到法国。——64、112。","language":"中文","translation":false},{"id":"manifesto-1-444","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":444,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"赖夫，威廉·约瑟夫（Reiff，Wilhelm Joseph约生于1824年）——德国代理商，共产主义者同盟盟员，1848年为科隆工人联合会会员，后为工人教育协会书记，1850年被开除出共产主义者同盟，科隆共产党人案件（1852）的被告之一，被判五年徒刑。——113、114。","language":"中文","translation":false},{"id":"manifesto-1-445","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":445,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"勒南，约瑟夫·厄内斯特（Renan，Joseph Ernest 1823-1892）——法国宗教史学家、哲学家和东方学家，写有基督教史方面的著作。——110。","language":"中文","translation":false},{"id":"manifesto-1-446","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":446,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"勒泽尔，彼得·格尔哈德（Röser，Peter Gerhard 1814-1865）——德国工人运动活动家，雪茄烟工人；1848-1849年为科隆工人联合会副主席，《自由、博爱、劳动》的发行人；1850年为共产主义者同盟盟员，同盟科隆中央委员会主席，科隆共产党人案件（1852）的被告之一，被判六年徒刑；后来成为拉萨尔派。——113、114。","language":"中文","translation":false},{"id":"manifesto-1-447","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":447,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"李卜克内西，威廉（Liebknecht，Wilhelm 1826-1900）——德国工人运动和国际工人运动活动家，语文学家和政论家；1848-1849年革命的参加者，革命失败后流亡瑞士，1850年5月前往英国，在那里成为共产主义者同盟盟员；1862年回到德国；国际会员，1867年起为国会议员；德国社会民主党创始人和领袖之一；《人民国家报》编辑（1869-1876）和《前进报》编辑（1876-1878和1890-1900）；1889、1891和1893年国际社会主义工人代表大会代表；马克思和恩格斯的朋友和战友。——133。","language":"中文","translation":false},{"id":"manifesto-1-448","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":448,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"里夫斯，威廉·多布森（Reeves，William Dobson 1827前后-1907）——英国出版商和书商；曾出版恩格斯的《英国工人阶级状况》一书。——13、18。","language":"中文","translation":false},{"id":"manifesto-1-449","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":449,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"列列韦尔，约阿希姆（Lelewel，Joachim 1786-1861）——波兰历史学家和革命活动家；1830-1831年波兰起义参加者，在法国和英国的波兰流亡者民主派领袖之一，1847-1848年为布鲁塞尔民主协会副主席。——125。","language":"中文","translation":false},{"id":"manifesto-1-450","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":450,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"列斯纳，弗里德里希（Leßner[Lessner]，Friedrich 1825-1910）——德国工人运动和国际工人运动的活动家，职业是裁缝；共产主义者同盟盟员，1848-1849年革命的参加者，1850年为威斯巴登工人教育协会会员；1850-1851年为美因茨工人教育协会主席和同盟美因茨支部领导人；在科隆共产党人案件（1852）中被判处三年徒刑，1856年起侨居伦敦，伦敦德意志工人共产主义教育协会会员，国际总委员会委员（1864-1872），国际伦敦代表会议（1865）、洛桑代表大会（1867）、布鲁塞尔代表大会（1868）、巴塞尔代表大会（1869）、伦敦代表会议（1871）和海牙代表大会（1872）的参加者，不列颠联合会委员会委员；在国际中为马克思的路线积极斗争，后为英国独立工党的创始人之一；马克思和恩格斯的朋友和战友。——104、114。","language":"中文","translation":false},{"id":"manifesto-1-451","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":451,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"卢格，阿尔诺德（Ruge，Arnold 1802—1880）——德国政论家，青年黑格尔分子，《哈雷年鉴》的出版者，《莱茵报》的撰稿人，1843-1844年同马克思一起筹办并出版《德法年鉴》；1844年中起反对马克思，1848年为法兰克福国民议会议员，属于左派，50年代是在英国的德国小资产阶级流亡者领袖之一；1866年后成为民族自由党人。——112。","language":"中文","translation":false},{"id":"manifesto-1-452","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":452,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"路易十六（Louis XVI 1754-1793）——法国国王（1774-1792），18世纪末法国资产阶级革命时期被处死。——135。","language":"中文","translation":false},{"id":"manifesto-1-453","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":453,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"路易-菲力浦一世（路易-菲力浦），奥尔良公爵（Louis-Philippe I[Louis-Philippe]，duc d’Orléans 1773-1850）——法国国王（1830-1848）。——95-96。","language":"中文","translation":false},{"id":"manifesto-1-454","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":454,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"吕宁，奥托（Lüning，Otto 1818-1868）——德国医生和政论家，40年代中是“真正的社会主义”的代表，共产主义者同盟盟员；《威悉河汽船》（1844）、《威斯特伐利亚汽船》（1845-1848）和《新德意志报》（1848-1850）编辑；1866年后为民族自由党人。——117。","language":"中文","translation":false},{"id":"manifesto-1-455","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":455,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"罗赫纳，格奥尔格（Lochner，Georg 1824-1910）——德国工人运动和国际工人运动的活动家，职业是细木工；共产主义者同盟盟员；1848-1849年革命的参加者，1851年底流亡伦敦；伦敦德意志工人共产主义教育协会会员；国际总委员会委员（1864-1867和1871-1872），国际伦敦代表会议（1865和1871）代表；马克思和恩格斯的朋友和战友。——104。","language":"中文","translation":false},{"id":"manifesto-1-456","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":456,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"马拉斯特，玛丽·弗朗索瓦·帕斯卡尔·阿尔芒（Marrast，Marie-François-Pascal-Armand 1801-1852）——法国政论家和政治活动家，人权社的领导人，后为温和的资产阶级共和派领袖，《国民报》总编辑；第二共和国时期是临时政府成员和巴黎市长（1848），制宪议会议长（1848-1849）。——133。","language":"中文","translation":false},{"id":"manifesto-1-457","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":457,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"马志尼，朱泽培（Mazzini，Giuseppe，1805-1872）——意大利革命家，民主主义者，意大利民族解放运动领袖，意大利1848-1849年革命的参加者，1849年为罗马共和国临时政府首脑；1850年是伦敦欧洲民主派中央委员会组织者之一；1853年是米兰起义的主要领导人，50年代后反对波拿巴法国干涉意大利人民的民族解放斗争；1864年成立第一国际时企图置国际于自己影响之下，1871年反对巴黎公社和国际，阻碍意大利独立工人运动的发展。——96、99、112。","language":"中文","translation":false},{"id":"manifesto-1-458","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":458,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"麦克法林，海伦（Macfarlane，Helen 笔名霍华德·莫滕 Howard Morten）——英国新闻工作者，革命宪章派领袖乔·哈尼出版的《民主评论》（1849-1850）和《红色共和党人》（1850）的撰稿人，马克思和恩格斯的《共产党宣言》的英文译者。——3、9。","language":"中文","translation":false},{"id":"manifesto-1-459","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":459,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"毛勒，格奥尔格·路德维希（Maurer，Georg Ludwig 1790-1872）——德国历史学家，古代和中世纪的日耳曼社会制度的研究者；写有中世纪马尔克公社的农业史和制度史方面的著作。——27。","language":"中文","translation":false},{"id":"manifesto-1-460","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":460,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"梅特涅——见梅特涅-温内堡公爵。","language":"中文","translation":false},{"id":"manifesto-1-461","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":461,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"梅特涅-温内堡公爵，克莱门斯·文策斯劳斯·奈波穆克·洛塔尔（Metternich-Winneburg，Clemens Wenzeslaus Nepomuk Lothar Fürst von 1773-1859）——奥地利国务活动家和外交家，曾任外交大臣（1809-1821）和首相（1821-1848），神圣同盟的组织者之一。——26。","language":"中文","translation":false},{"id":"manifesto-1-462","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":462,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"门特尔，克里斯蒂安·弗里德里希（Mentel，Christian Friedrich 生于1812年）——德国裁缝，正义者同盟盟员，1846-1847年因同盟案件被关在普鲁士监狱。——98。","language":"中文","translation":false},{"id":"manifesto-1-463","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":463,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"摩尔根，路易斯·亨利（Morgan，Lewis Henry 1818-1881）——美国法学家、民族学家、考古学家和原始社会史学家，进化论的代表，自发的唯物主义者。——27。","language":"中文","translation":false},{"id":"manifesto-1-464","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":464,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"莫尔，约瑟夫（Moll，Joseph 1813-1849）——德国工人运动和国际工人运动的活动家，职业是钟表匠；正义者同盟领导人之一，共产主义者同盟中央委员会委员，1848年7-9月是科隆工人联合会主席，民主主义者莱茵区域委员会委员；1848年科隆九月事件后流亡伦敦，不久改名回到德国，在各地进行宣传鼓动；1849年巴登-普法尔茨起义的参加者，在穆尔格河战斗中牺牲。——96、104、107、110、120。","language":"中文","translation":false},{"id":"manifesto-1-465","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":465,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"穆尔，赛米尔（Moore，Samuel 1838-1911）——英国法学家，国际会员，曾将《资本论》第一卷（与爱·艾威林一起）和《共产党宣言》译成英文；50年代为曼彻斯特的厂主；马克思和恩格斯的朋友。——14、17-18。","language":"中文","translation":false},{"id":"manifesto-1-466","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":466,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"拿破仑第三（路易-拿破仑·波拿巴）（Napoléon Ⅲ[Louis-Napoléon Bonaparte] 1808-1873）——法兰西第二共和国总统（1848-1851），法国皇帝（1852-1870），拿破仑第一的侄子。——22。","language":"中文","translation":false},{"id":"manifesto-1-467","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":467,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"尼古拉一世（Николай Ⅰ 1796-1855）——俄国皇帝（1825-1855）。——6、16、23、26。","language":"中文","translation":false},{"id":"manifesto-1-468","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":468,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"诺特荣克，彼得（Nothjung，Peter 1821—1866）——德国裁缝，科隆工人联合会会员（1848）和共产主义者同盟盟员，1849年5月埃尔伯费尔德起义的参加者，共产主义者同盟科隆中央委员会特使（1850年11月-1851年5月）；科隆共产党人案件（1852）的被告之一，被判六年徒刑；后为全德工人联合会派驻布雷斯劳的全权代表。——113、114。","language":"中文","translation":false},{"id":"manifesto-1-469","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":469,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"欧文，罗伯特（Owen，Robert 1771-1858）——英国空想社会主义者。——11、19、60-61、63。","language":"中文","translation":false},{"id":"manifesto-1-470","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":470,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"蒲鲁东，皮埃尔·约瑟夫（Proudhon，Pierre-Joseph 1809-1865）——法国政论家、经济学家和社会学家，小资产阶级思想家，无政府主义理论的创始人，第二共和国时期是制宪议会议员（1848）。——10、18、19、59、109、118、124、129。","language":"中文","translation":false},{"id":"manifesto-1-471","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":471,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"普芬德，卡尔（Pfänder，Carl 1819-1876）——德国微型画画家，德国工人运动和国际工人运动的活动家，1845年起侨居伦敦，正义者同盟盟员，伦敦德意志工人共产主义教育协会会员；1849年巴登-普法尔茨起义的参加者，起义失败后流亡英国；共产主义者同盟中央委员会委员，1850年共产主义者同盟分裂后支持马克思和恩格斯；国际总委员会委员（1864-1867和1870-1872）；马克思和恩格斯的朋友和战友。——104。","language":"中文","translation":false},{"id":"manifesto-1-472","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":472,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"茹柯夫斯基，尤利·加拉克季昂诺维奇（Жуковский, Юлий Галактионович 1822-1907）——俄国资产阶级庸俗经济学家和政论家；国家银行行长；曾撰写《卡尔·马克思和他的〈资本论〉一书》一文，攻击马克思主义。——134。","language":"中文","translation":false},{"id":"manifesto-1-473","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":473,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"沙佩尔，卡尔（Schapper，Karl 1812-1870）——德国工人运动和国际工人运动的活动家，正义者同盟的领导者之一，伦敦德意志工人共产主义教育协会创建人之一，共产主义者同盟中央委员会委员；1848-1849年革命的参加者；民主主义者莱茵区域委员会委员，该委员会案件（1849年2月8日）的被告之一；1849年2-5月为科隆工人联合会主席，《新莱茵报》撰稿人；1850年共产主义者同盟分裂时为冒险主义宗派集团的领袖之一；1856年起重新同马克思和恩格斯接近；国际总委员会委员（1865），1865年伦敦代表会议的参加者。——75、95、96、102、107、110、113、114、144。","language":"中文","translation":false},{"id":"manifesto-1-474","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":474,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"圣西门，昂利（Saint-Simon，Henri 1760-1825）——法国空想社会主义者。——60。","language":"中文","translation":false},{"id":"manifesto-1-475","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":475,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"施梯伯，威廉（Stieber，Wilhelm 1818-1882）——普鲁士警官，普鲁士政治警察局局长（1852-1860），科隆共产党人案件（1852）的策划者之一和主要原告证人；同卡·维尔穆特合编《19世纪共产主义者的阴谋》一书；普奥战争（1866）和普法战争（1870-1871）时期为军事警察局局长，在法国境内的德国情报机关的首脑。——94、105。","language":"中文","translation":false},{"id":"manifesto-1-476","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":476,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"叔尔茨，卡尔（Schurz，Carl 1829-1906）——德国政论家，小资产阶级民主主义者，1849年巴登-普法尔茨起义的参加者，起义失败后流亡瑞士，加入秘密组织“革命集中”；1852年迁居美国，站在北部方面参加美国内战，美国共和党领袖之一，曾任美国驻西班牙公使，后为参议员和内政部长（1877-1881）。——111。","language":"中文","translation":false},{"id":"manifesto-1-477","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":477,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"维尔穆特，卡尔·格奥尔格·路德维希（Wermuth，Carl Georg Ludwig 1803-1867）——德国警官，汉诺威警察局长，科隆共产党人案件（1852）的策划者之一和原告证人；同威·施梯伯合编《19世纪共产主义者的阴谋》一书。——94、105。","language":"中文","translation":false},{"id":"manifesto-1-478","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":478,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"维利希，奥古斯特（Willich，August 1810-1878）——普鲁士军官，1847年起为共产主义者同盟盟员，1849年巴登-普法尔茨起义中为志愿军团首领；1850年共产主义者同盟分裂时同卡·沙佩尔一起组成反对马克思的冒险主义宗派集团；1853年侨居美国，站在北部方面参加美国内战，任将军。——110、111、113、114。","language":"中文","translation":false},{"id":"manifesto-1-479","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":479,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"魏特林，克里斯蒂安·威廉（Weitling，Christian Wilhelm 1808-1871）——德国工人运动活动家，正义者同盟领导人，职业是裁缝；空想平均共产主义理论家和鼓动家；工人同盟的创始人，《工人共和国报》的出版者；1849年流亡美国，晚年接近国际工人协会。——12、19、97-100、103、111、113、119、132。","language":"中文","translation":false},{"id":"manifesto-1-480","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":480,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"沃尔弗，弗里德里希·威廉（Wolff，Friedrich Wilhelm 鲁普斯 Lupus 1809-1864）——德国无产阶级革命家和政论家，职业是教员，西里西亚农民的儿子；1834-1839年被关在普鲁士监狱；1846-1847年为布鲁塞尔共产主义通讯委员会委员，共产主义者同盟创始人之一和同盟中央委员会委员（1848年3月起），《新莱茵报》编辑（1848-1849），民主主义者莱茵区域委员会和科隆安全委员会委员；法兰克福国民议会议员，属于极左派；1849年流亡瑞士，1851年迁居英国，1853年起在曼彻斯特当教员；马克思和恩格斯的朋友和战友。——75、105、107、109、120。","language":"中文","translation":false},{"id":"manifesto-1-481","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":481,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"西斯蒙第，让·沙尔·莱奥纳尔·西蒙德·德（Sismondi，Jean-Charles-Léonard Simonde de 1773-1842）——瑞士经济学家和历史学家，政治经济学中浪漫学派的代表人物。——54。","language":"中文","translation":false},{"id":"manifesto-1-482","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":482,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"席尔，卡尔——见沙佩尔，卡尔。","language":"中文","translation":false},{"id":"manifesto-1-483","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":483,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"雅科比，阿伯拉罕（Jacobi，Abraham 1830-1919）——德国医生，波恩体操联合会创建人和会长（1850-1851），共产主义者同盟盟员和特使，科隆共产党人案件（1852）的被告之一，被陪审法庭宣告无罪，但因被控“侮辱国王陛下”而继续被监禁；1853年流亡英国，后迁居美国，在美国的刊物上宣传马克思主义思想；站在北部方面参加美国内战，后为纽约医学科学院院长（1885-1889），一些医学院的教授和院长，写有医学方面的著作。——114。","language":"中文","translation":false},{"id":"manifesto-1-484","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":484,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"亚历山大三世（Александр III 1845-1894）——俄国皇帝（1881-1894）。——6、16。","language":"中文","translation":false},{"id":"manifesto-1-485","author":"马克思、恩格斯","title":"共产党宣言","location":"马克思 恩格斯：共产党宣言（1848年）","page":1,"paragraph":485,"url":"https://www.marxists.org/chinese/marx/01.htm","text":"感谢 聂孟、卫玄鹤 校对","language":"中文","translation":false},{"id":"capital-1-1","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-1-2","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"· 第一版序言（卡尔·马克思，1867年7月25日）","language":"中文","translation":false},{"id":"capital-1-3","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"· 第二版跋 （卡尔·马克思，1873年1月24日）","language":"中文","translation":false},{"id":"capital-1-4","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"· 法文版序言（卡尔·马克思，1872年3月18日）","language":"中文","translation":false},{"id":"capital-1-5","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"· 法文版跋 （卡尔·马克思，1875年4月28日）","language":"中文","translation":false},{"id":"capital-1-6","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"· 第三版序言（弗里德思希·恩格斯，1883年11月7日）","language":"中文","translation":false},{"id":"capital-1-7","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"· 英文版序言（弗里德里希·恩格斯，1886年11月5日）","language":"中文","translation":false},{"id":"capital-1-8","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"· 第四版序言（弗里德里希·恩格斯，1890年6月25日）","language":"中文","translation":false},{"id":"capital-1-9","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"现在我把这部著作的第一卷交给读者。这部著作是我1859年发表的《政治经济学批判》的续篇。初篇和续篇相隔很久，是由于多年的疾病一再中断了我的工作。","language":"中文","translation":false},{"id":"capital-1-10","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"前书的内容已经概述在这一卷的第一章中[2]。这样做不仅是为了联贯和完整，叙述方式也改进了。在情况许可的范围内，前书只是略略提到的许多论点，这里都作了进一步的阐述；相反地，前书已经详细阐述的论点，这里只略略提到。关于价值理论和货币理论的历史的部分，现在自然完全删去了。但是前书的读者可以在本书第一章的注释中，找到有关这两种理论的历史的新材料。","language":"中文","translation":false},{"id":"capital-1-11","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"万事开头难，每门科学都是如此。所以本书第一章，特别是分析商品的部分，是最难理解的。其中对价值实体和价值量的分析，我已经尽可能地做到通俗易懂[3]。以货币形式为其完成形态的价值形式，是极无内容和极其简单的。然而，两千多年来人类智慧在这方面进行探讨的努力，并未得到什么结果，而对更有内容和更复杂的形式的分析，却至少已接近于成功。为什么会这样呢？因为已经发育的身体比身体的细胞容易研究些。并且，分析经济形式，既不能用显微镜，也不能用化学试剂。二者都必须用抽象力来代替。而对资产阶级社会说来，劳动产品的商品形式，或者商品的价值形式，就是经济的细胞形式。在浅薄的人看来，分析这种形式好象是斤斤于一些琐事。这的确是琐事，但这是显微镜下的解剖所要做的那种琐事。","language":"中文","translation":false},{"id":"capital-1-12","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"因此，除了价值形式那一部分外，不能说这本书难懂。当然，我指的是那些想学到一些新东西、因而愿意自己思考的读者。","language":"中文","translation":false},{"id":"capital-1-13","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"物理学家是在自然过程表现得最确实、最少受干扰的地方考察自然过程的，或者，如有可能，是在保证过程以其纯粹形态进行的条件下从事实验的。我要在本书研究的，是资本主义生产方式以及和它相适应的生产关系和交换关系。到现在为止，这种生产方式的典型地点是英国。因此，我在理论阐述上主要用英国作为例证。但是，如果德国读者看到英国工农业工人所处的境况而伪善地耸耸肩膀，或者以德国的情况远不是那样坏而乐观地自我安慰，那我就要大声地对他说：这正是说的阁下的事情！[5]","language":"中文","translation":false},{"id":"capital-1-14","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"问题本身并不在于资本主义生产的自然规律所引起的社会对抗的发展程度的高低。问题在于这些规律本身，在于这些以铁的必然性发生作用并且正在实现的趋势。工业较发达的国家向工业较不发达的国家所显示的，只是后者未来的景象。","language":"中文","translation":false},{"id":"capital-1-15","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"撇开这点不说。在资本主义生产已经在我们那里完全确立的地方，例如在真正的工厂里，由于没有起抗衡作用的工厂法，情况比英国要坏得多。在其他一切方面，我们也同西欧大陆所有其他国家一样，不仅苦于资本主义生产的发展，而且苦于资本主义生产的不发展。除了现代的灾难而外，压迫着我们的还有许多遗留下来的灾难，这些灾难的产生，是由于古老的陈旧的生产方式以及伴随着它们的过时的社会关系和政治关系还在苟延残喘。不仅活人使我们受苦，而且死人也使我们受苦。死人抓住活人！","language":"中文","translation":false},{"id":"capital-1-16","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"德国和西欧大陆其他国家的社会统计，与英国相比是很贫乏的。然而它还是把帷幕稍稍揭开，使我们刚刚能够窥见幕内美杜莎的头。如果我国各邦政府和议会象英国那样，定期指派委员会去调查经济状况，如果这些委员会象英国那样，有全权去揭发真相，如果为此能够找到象英国工厂视察员、编写《公共卫生》报告的英国医生、调查女工童工受剥削的情况以及居住和营养条件等等的英国调查委员那样内行、公正、坚决的人们，那末，我国的情况就会使我们大吃一惊。柏修斯需要一顶隐身帽来追捕妖怪。我们却用隐身帽紧紧遮住眼睛和耳朵，以便有可能否认妖怪的存在。","language":"中文","translation":false},{"id":"capital-1-17","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"决不要在这上面欺骗自己。正象十八世纪美国独立战争给欧洲中产阶级敲起了警钟一样，十九世纪美国南北战争又给欧洲工人阶级敲起了警钟。在英国，变革过程已经十分明显。它达到一定程度后，一定会波及大陆。在那里，它将采取较残酷的还是较人道的形式，那要看工人阶级自身的发展程度而定。所以，现在的统治阶级，不管有没有较高尚的动机，也不得不为了自己的切身利益，把一切可以由法律控制的、妨害工人阶级发展的障碍除去。因此，我在本卷中用了很大的篇幅来叙述英国工厂法的历史、内容和结果。一个国家应该而且可以向其他国家学习。一个社会即使探索到了本身运动的自然规律，——本书的最终目的就是揭示现代社会的经济运动规律，——它还是既不能跳过也不能用法令取消自然的发展阶段。但是它能缩短和减轻分娩的痛苦。","language":"中文","translation":false},{"id":"capital-1-18","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"为了避免可能产生的误解，要说明一下。我决不用玫瑰色描绘资本家和地主的面貌。不过这里涉及到的人，只是经济范畴的人格化，是一定的阶级关系和利益的承担者。我的观点是：社会经济形态的发展是一种自然历史过程。不管个人在主观上怎样超脱各种关系，他在社会意义上总是这些关系的产物。同其他任何观点比起来，我的观点是更不能要个人对这些关系负责的。","language":"中文","translation":false},{"id":"capital-1-19","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"在政治经济学领域内，自由的科学研究遇到的敌人，不只是它在一切其他领域内遇到的敌人。政治经济学所研究的材料的特殊性，把人们心中最激烈、最卑鄙、最恶劣的感情，把代表私人利益的复仇女神召唤到战场上来反对自由的科学研究。例如，英国高教会宁愿饶恕对它的三十九个信条中的三十八个信条展开的攻击，而不饶恕对它的现金收入的三十九分之一进行的攻击。在今天，同批评传统的财产关系相比，无神论本身是一种很轻的罪。但在这方面，进步仍然是无可怀疑的。以最近几星期内发表的蓝皮书[6]《关于工业和工联问题同女王陛下驻外公使馆的通讯》为例。英国女王驻外使节在那里坦率地说，在德国，在法国，一句话，在欧洲大陆的一切文明国家，现有的劳资关系的变革同英国一样明显，一样不可避免。同时，大西洋彼岸的美国副总统威德先生也在公众集会上说：在奴隶制废除后，资本关系和土地所有权关系的变革会提到日程上来！这是时代的标志，不是用紫衣黑袍遮掩得了的。这并不是说明天就会出现奇迹。但这表明，甚至在统治阶级中间也已经透露出一种模糊的感觉：现在的社会不是坚实的结晶体，而是一个能够变化并且经常处于变化过程中的机体。","language":"中文","translation":false},{"id":"capital-1-20","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这部著作的第二卷将探讨资本的流通过程（第二册）和总过程的各种形式（第三册），第三卷即最后一卷（第四册）将探讨理论史。","language":"中文","translation":false},{"id":"capital-1-21","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"任何的科学批评的意见我都是欢迎的。而对于我从来就不让步的所谓舆论的偏见，我仍然遵守伟大的佛罗伦萨诗人的格言：","language":"中文","translation":false},{"id":"capital-1-22","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"走你的路，让人们去说罢！[7]","language":"中文","translation":false},{"id":"capital-1-23","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1867年7月25日于伦敦","language":"中文","translation":false},{"id":"capital-1-24","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"我首先应当向第一版的读者指出第二版中所作的修改。很明显的是，篇目更加分明了。各处新加的注，都标明是第二版注。就正文说，最重要的有下列各点：","language":"中文","translation":false},{"id":"capital-1-25","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"第一章第一节更加科学而严密地从表现每个交换价值的等式的分析中引出了价值，而且明确地突出了在第一版中只是略略提到的价值实体和由社会必要劳动时间决定的价值量之间的联系。第一章第三节（价值形式）全部改写了，第一版的双重叙述就要求这样做。——顺便指出，这种双重叙述是我的朋友，汉诺威的路·库格曼医生建议的。1867年春，初校样由汉堡寄来时，我正好访问他。他劝我说，大多数读者需要有一个关于价值形式的更带讲义性的补充说明。——第一章最后一节《商品的拜物教性质及其秘密》大部分修改了。第三章第一节（价值尺度）作了详细的修改，因为在第一版中，考虑到《政治经济学批判》（1859年柏林版）已有的说明，这一节是写得不够细致的。第七章，特别是这一章的第二节，作了很大的修改。","language":"中文","translation":false},{"id":"capital-1-26","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"原文中局部的、往往只是修辞上的修改，用不着一一列举出来。这些修改全书各处都有。但是，现在我校阅要在巴黎出版的法译本时，发现德文原本某些部分需要更彻底地修改，某些部分需要更好地修辞或更仔细地消除一些偶然的疏忽。可是我没有时间这样做，因为只是在1871年秋，正当我忙于其他迫切的工作的时候，我才接到通知说，书已经卖完了，而第二版在1872年1月就要付印。","language":"中文","translation":false},{"id":"capital-1-27","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"《资本论》在德国工人阶级广大范围内迅速得到理解，是对我的劳动的最好的报酬。一个在经济方面站在资产阶级立场上的人，维也纳的工厂主迈尔先生，在普法战争期间发行的一本小册子中[8]说得很对：被认为是德国世袭财产的卓越的理论思维能力，已在德国的所谓有教养的阶级中完全消失了，但在德国工人阶级中复活了。[9]","language":"中文","translation":false},{"id":"capital-1-28","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"在德国，直到现在，政治经济学一直是外来的科学。古斯达夫·冯·居利希在他的《商业、工业和农业的历史叙述》中，特别是在1830年出版的该书的前两卷中，已经大体上谈到了妨碍我国资本主义生产方式发展、因而也妨碍我国现代资产阶级社会建立的历史条件。可见，政治经济学在我国缺乏生存的基础。它作为成品从英国和法国输入；德国的政治经济学教授一直是学生。别国的现实在理论上的表现，在他们手中变成了教条集成，被他们用包围着他们的小资产阶级世界的精神去解释，就是说，被曲解了。他们不能把在科学上无能为力的感觉完全压制下去，他们不安地意识到，他们必须在一个实际上不熟悉的领域内充当先生，于是就企图用博通文史的美装，或用无关材料的混合物来加以掩饰。这种材料是从所谓官房学——各种知识的杂拌，满怀希望的[10]德国官僚候补者必须通过的炼狱之火——抄袭来的。","language":"中文","translation":false},{"id":"capital-1-29","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"从1848年起，资本主义生产在德国迅速地发展起来，现在正是它的欺诈盛行的时期。但是我们的专家还是命运不好。当他们能够公正无私地研究政治经济学时，在德国的现实中没有现代的经济关系。而当这种关系出现时，他们所处的境况已经不再容许他们在资产阶级的视野之内进行公正无私的研究了。只要政治经济学是资产阶级的政治经济学，就是说，只要它把资本主义制度不是看作历史上过渡的发展阶段，而是看作社会生产的绝对的最后的形式，那就只有在阶级斗争处于潜伏状态或只是在个别的现象上表现出来的时候，它还能够是科学。","language":"中文","translation":false},{"id":"capital-1-30","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"拿英国来说。英国古典政治经济学是属于阶级斗争不发展的时期的。它的最后的伟大的代表李嘉图，终于有意识地把阶级利益的对立、工资和利润的对立、利润和地租的对立当作他的研究的出发点，因为他天真地把这种对立看作社会的自然规律。这样，资产阶级的经济科学也就达到了它的不可逾越的界限。还在李嘉图活着的时候，就有一个和他对立的人西斯蒙第批判资产阶级的经济科学了。[11]","language":"中文","translation":false},{"id":"capital-1-31","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"随后一个时期，从1820年到1830年，在英国，政治经济学方面的科学活动极为活跃。这是李嘉图的理论庸俗化和传播的时期，同时也是他的理论同旧的学派进行斗争的时期。这是一场出色的比赛。当时的情况，欧洲大陆知道得很少，因为论战大部分是分散在杂志论文、关于时事问题的著作和抨击性小册子上。这一论战的公正无私的性质——虽然李嘉图的理论也例外地被用作攻击资产阶级经济的武器——可由当时的情况来说明。一方面，大工业刚刚脱离幼年时期；大工业只是从1825年的危机才开始它的现代生活的周期循环，就证明了这一点。另一方面，资本和劳动之间的阶级斗争被推到后面：在政治方面是由于纠合在神圣同盟周围的政府和封建主同资产阶级所领导的人民大众之间发生了纠纷；在经济方面是由于工业资本和贵族土地所有权之间发生了纷争。这种纷争在法国是隐藏在小块土地所有制和大土地所有制的对立后面，在英国则在谷物法颁布后公开爆发出来。这个时期英国的政治经济学文献，使人想起魁奈医生逝世后法国经济学的狂飙时期，但这只是象晚秋晴日使人想起春天一样。1830年，最终决定一切的危机发生了。","language":"中文","translation":false},{"id":"capital-1-32","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"法国和英国的资产阶级夺得了政权。从那时起，阶级斗争在实践方面和理论方面采取了日益鲜明的和带有威胁性的形式。它敲响了科学的资产阶级经济学的丧钟。现在问题不再是这个或那个原理是否正确，而是它对资本有利还是有害，方便还是不方便，违背警章还是不违背警章。不偏不倚的研究让位于豢养的文丐的争斗，公正无私的科学探讨让位于辩护士的坏心恶意。甚至以工厂主科布顿和布莱特为首的反谷物法同盟[13]抛出的强迫人接受的小册子，由于对地主贵族展开了论战，即使没有科学的意义，毕竟也有历史的意义。但是从罗伯特·皮尔爵士执政以来，这最后一根刺也被自由贸易的立法从庸俗经济学那里拔掉了。","language":"中文","translation":false},{"id":"capital-1-33","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1848年大陆的革命也在英国产生了反应。那些还要求有科学地位、不愿单纯充当统治阶级的诡辩家和献媚者的人，力图使资本的政治经济学同这时已不容忽视的无产阶级的要求调和起来。于是，以约翰·斯图亚特·穆勒为最著名代表的毫无生气的混合主义产生了。这宣告了“资产阶级”经济学的破产，关于这一点，俄国的伟大学者和批评家尼·车尔尼雪夫斯基在他的《穆勒政治经济学概述》中已作了出色的说明。","language":"中文","translation":false},{"id":"capital-1-34","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"可见，在资本主义生产方式的对抗性质在法英两国通过历史斗争而明显地暴露出来以后，资本主义生产方式才在德国成熟起来，同时，德国无产阶级比德国资产阶级在理论上已经有了更明确的阶级意识。因此，当资产阶级政治经济学作为一门科学看来在德国有可能产生的时候，它又成为不可能了。","language":"中文","translation":false},{"id":"capital-1-35","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"在这种情况下，资产阶级政治经济学的代表人物分成了两派。一派是精明的、贪利的实践家，他们聚集在庸俗经济学辩护论的最浅薄的因而也是最成功的代表巴师夏的旗帜下。另一派是以经济学教授资望自负的人，他们追随约·斯·穆勒，企图调和不能调和的东西。德国人在资产阶级经济学衰落时期，也同在它的古典时期一样，始终只是学生、盲从者和模仿者，是外国大商行的小贩。","language":"中文","translation":false},{"id":"capital-1-36","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"所以，德国社会特殊的历史发展，排除了“资产阶级”经济学在德国取得任何独创的成就的可能性，但是没有排除对它进行批判的可能性。就这种批判代表一个阶级而论，它能代表的只是这样一个阶级，这个阶级的历史使命是推翻资本主义生产方式和最后消灭阶级。这个阶级就是无产阶级。","language":"中文","translation":false},{"id":"capital-1-37","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"德国资产阶级的博学的和不学无术的代言人，最初企图象他们在对付我以前的著作时曾经得逞那样，用沉默置《资本论》于死地。当这种策略已经不再适合时势的时候，他们就借口批评我的书，开了一些单方来“镇静资产阶级的意识”，但是他们在工人报刊上（例如约瑟夫·狄慈根在《人民国家报》上发表的文章[14]）遇到了强有力的对手，至今还没有对这些对手作出答复。[15]","language":"中文","translation":false},{"id":"capital-1-38","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1872年春，彼得堡出版了《资本论》的优秀的俄译本。初版三千册现在几乎已售卖一空。1871年，基辅大学政治经济学教授尼·季别尔先生在他的《李嘉图的价值和资本的理论》一书中就已经证明，我的价值、货币和资本的理论就其要点来说是斯密—李嘉图学说的必然的发展。使西欧读者在阅读他的这本出色的著作时感到惊异的，是纯理论观点的始终一贯。","language":"中文","translation":false},{"id":"capital-1-39","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"人们对《资本论》中应用的方法理解得很差，这已经由各种互相矛盾的评论所证明。","language":"中文","translation":false},{"id":"capital-1-40","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"例如，巴黎的《实证论者评论》[16]一方面责备我形而上学地研究经济学，另一方面责备我——你们猜猜看！——只限于批判地分析既成的事实，而没有为未来的食堂开出调味单（孔德主义的吗？）。关于形而上学的责备，季别尔教授指出：","language":"中文","translation":false},{"id":"capital-1-41","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"“就理论本身来说，马克思的方法是整个英国学派的演绎法，其优点和缺点是一切最优秀的理论经济学家所共有的。”[17]","language":"中文","translation":false},{"id":"capital-1-42","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"莫·布洛克先生在《德国的社会主义理论家》(摘自1872年7月和8月《经济学家杂志》)一文中，指出我的方法是分析的方法，他说：","language":"中文","translation":false},{"id":"capital-1-43","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"“马克思先生通过这部著作而成为一个最出色的具有分析能力的思想家”。","language":"中文","translation":false},{"id":"capital-1-44","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"德国的评论家当然大叫什么黑格尔的诡辩。彼得堡的《欧洲通报》在专谈《资本论》的方法一文（1872年5月号第427—436页[18]）中，认为我的研究方法是严格的现实主义的，而叙述方法不幸是德国辩证法的。作者写道：","language":"中文","translation":false},{"id":"capital-1-45","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"“如果从外表的叙述形式来判断，那末最初看来，马克思是最大的唯心主义哲学家，而且是德国的即坏的唯心主义哲学家。而实际上，在经济学的批判方面，他是他的所有前辈都无法比拟的现实主义者……决不能把他称为唯心主义者。”","language":"中文","translation":false},{"id":"capital-1-46","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"我回答这位作者先生的最好的办法，是从他自己的批评中摘出几段话来，这几段话也会使某些不懂俄文原文的读者感到兴趣。","language":"中文","translation":false},{"id":"capital-1-47","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这位作者先生从我的《政治经济学批判》序言（1859年柏林版第4—7页[19]，在那里我说明了我的方法的唯物主义基础）中摘引一段话后说：","language":"中文","translation":false},{"id":"capital-1-48","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"“在马克思看来，只有一件事情是重要的，那就是发现他所研究的那些现象的规律。而且他认为重要的，不仅是在这些现象具有完成形式和处于一定时期内可见到的联系中的时候支配着它们的那种规律。在他看来，除此而外，最重要的是这些现象变化的规律，这些现象发展的规律，即它们由一种形式过渡到另一种形式，由一种联系秩序过渡到另一种联系秩序的规律。他一发现了这个规律，就详细地来考察这个规律在社会生活中表现出来的各种后果……所以马克思竭力去做的只是一件事：通过准确的科学研究来证明一定的社会关系秩序的必然性，同时尽可能完善地指出那些作为他的出发点和根据的事实。为了这个目的，只要证明现有秩序的必然性，同时证明这种秩序不可避免地要过渡到另一种秩序的必然性就完全够了，而不管人们相信或不相信，意识到或没有意识到这种过渡。马克思把社会运动看作受一定规律支配的自然历史过程，这些规律不仅不以人的意志、意识和意图为转移，反而决定人的意志、意识和意图……既然意识要素在文化史上只起着这种从属作用，那末不言而喻，以文化本身为对象的批判，比任何事情更不能以意识的某种形式或某种结果为依据。这就是说，作为这种批判的出发点的不能是观念，而只能是外部的现象。批判将不是把事实和观念比较对照，而是把一种事实同另一种事实比较对照。对这种批判唯一重要的是，把两种事实尽量准确地研究清楚，使之真正形成相互不同的发展阶段，但尤其重要的是，同样准确地把各种秩序的序列、把这些发展阶段所表现出来的联贯性和联系研究清楚……但是有人会说，经济生活的一般规律，不管是应用于现在或过去，都是一样的。马克思否认的正是这一点。在他看来，这样的抽象规律是不存在的……根据他的意见，恰恰相反，每个历史时期都有它自己的规律。一旦生活经过了一定的发展时期，由一定阶段进入另一阶段时，它就开始受另外的规律支配。总之，经济生活呈现出的现象，和生物学的其他领域的发展史颇相类似……旧经济学家不懂得经济规律的性质，他们把经济规律同物理学定律和化学定律相比拟……对现象所作的更深刻的分析证明，各种社会机体象动植物机体一样，彼此根本不同……由于各种机体的整个结构不同，它们的各个器官有差别，以及器官借以发生作用的条件不一样等等，同一个现象却受完全不同的规律支配。例如，马克思否认人口规律在任何时候在任何地方都是一样的。相反地，他断言每个发展阶段有它自己的人口规律……生产力的发展水平不同，生产关系和支配生产关系的规律也就不同。马克思给自己提出的目的是，从这个观点出发去研究和说明资本主义经济制度，这样，他只不过是极其科学地表述了任何对经济生活进行准确的研究必须具有的目的……这种研究的科学价值在于阐明了支配着一定社会机体的产生、生存、发展和死亡以及为另一更高的机体所代替的特殊规律。马克思的这本书确实具有这种价值”。","language":"中文","translation":false},{"id":"capital-1-49","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这位作者先生把他称为我的实际方法的东西描述得这样恰当，并且在考察我个人对这种方法的运用时又抱着这样的好感，那他所描述的不正是辩证方法吗？","language":"中文","translation":false},{"id":"capital-1-50","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"当然，在形式上，叙述方法必须与研究方法不同。研究必须充分地占有材料，分析它的各种发展形式，探寻这些形式的内在联系。只有这项工作完成以后，现实的运动才能适当地叙述出来。这点一旦做到，材料的生命一旦观念地反映出来，呈现在我们面前的就好象是一个先验的结构了。","language":"中文","translation":false},{"id":"capital-1-51","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"我的辩证方法，从根本上来说，不仅和黑格尔的辩证方法不同，而且和它截然相反。在黑格尔看来，思维过程，即他称为观念而甚至把它变成独立主体的思维过程，是现实事物的创造主，而现实事物只是思维过程的外部表现。我的看法则相反，观念的东西不外是移入人的头脑并在人的头脑中改造过的物质的东西而已。","language":"中文","translation":false},{"id":"capital-1-52","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"将近三十年以前，当黑格尔辩证法还很流行的时候，我就批判过黑格尔辩证法的神秘方面。但是，正当我写《资本论》第一卷时，愤懑的、自负的、平庸的、今天在德国知识界发号施令的模仿者们[20]，却已高兴地象莱辛时代大胆的莫泽斯·门德尔森对待斯宾诺莎那样对待黑格尔，即把他当作一条“死狗”了。因此，我要公开承认我是这位大思想家的学生，并且在关于价值理论的一章中，有些地方我甚至卖弄起黑格尔特有的表达方式。辩证法在黑格尔手中神秘化了，但这决不妨碍他第一个全面地有意识地叙述了辩证法的一般运动形式。在他那里，辩证法是倒立着的。必须把它倒过来，以便发现神秘外壳中的合理内核。","language":"中文","translation":false},{"id":"capital-1-53","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"辩证法，在其神秘形式上，成了德国的时髦东西，因为它似乎使现存事物显得光彩。辩证法，在其合理形态上，引起资产阶级及其夸夸其谈的代言人的恼怒和恐怖，因为辩证法在对现存事物的肯定的理解中同时包含对现存事物的否定的理解，即对现存事物的必然灭亡的理解；辩证法对每一种既成的形式都是从不断的运动中，因而也是从它的暂时性方面去理解；辩证法不崇拜任何东西，按其本质来说，它是批判的和革命的。","language":"中文","translation":false},{"id":"capital-1-54","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"使实际的资产者最深切地感到资本主义社会充满矛盾的运动的，是现代工业所经历的周期循环的变动，而这种变动的顶点就是普遍危机。这个危机又要临头了，虽然它还处于预备阶段；由于它的舞台的广阔和它的作用的强烈，它甚至会把辩证法灌进新的神圣普鲁士德意志帝国的暴发户们的头脑里去。","language":"中文","translation":false},{"id":"capital-1-55","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1873年1月24日于伦敦","language":"中文","translation":false},{"id":"capital-1-56","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"您想定期分册出版《资本论》的译本，我很赞同。这本书这样出版，更容易到达工人阶级的手里，在我看来，这种考虑是最为重要的。","language":"中文","translation":false},{"id":"capital-1-57","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这是您的想法好的一面，但也有坏的一面：我所使用的分析方法至今还没有人在经济问题上运用过，这就使前几章读起来相当困难。法国人总是急于追求结论，渴望知道一般原则同他们直接关心的问题的联系，因此我很担心，他们会因为一开始就不能继续读下去而气馁。","language":"中文","translation":false},{"id":"capital-1-58","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这是一种不利，对此我没有别的办法，只有事先向追求真理的读者指出这一点，并提醒他们。在科学上没有平坦的大道，只有不畏劳苦沿着陡峭山路攀登的人，才有希望达到光辉的顶点。","language":"中文","translation":false},{"id":"capital-1-59","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"亲爱的公民，请接受我对您的忠诚。","language":"中文","translation":false},{"id":"capital-1-60","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1872年3月18日于伦敦","language":"中文","translation":false},{"id":"capital-1-61","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"约·鲁瓦先生保证尽可能准确地、甚至逐字逐句地进行翻译。他非常认真地完成了自己的任务。但正因为他那样认真，我不得不对表述方法作些修改，使读者更容易理解。由于本书分册出版，这些修改是逐日作的，所以不能处处一样仔细，文体不免有不一致的地方。","language":"中文","translation":false},{"id":"capital-1-62","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"在担负校正工作后，我就感到作为依据的原本（德文第二版）应当作一些修改，有些论述要简化，另一些要加以完善，一些补充的历史材料或统计材料要加进去，一些批判性评注要增加，等等。不管这个法文版本有怎样的文字上的缺点，它仍然在原本之外有独立的科学价值，甚至对懂德语的读者也有参考价值。","language":"中文","translation":false},{"id":"capital-1-63","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"下面是我从德文第二版跋中摘引的几段，是有关政治经济学在德国的发展和本书运用的方法的。","language":"中文","translation":false},{"id":"capital-1-64","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1875年4月28日于伦敦","language":"中文","translation":false},{"id":"capital-1-65","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"马克思不幸已不能亲自进行这个第三版的付印准备工作。这位大思想家——现在，连反对他的人也拜服他的伟大了——已于1883年3月14日逝世。","language":"中文","translation":false},{"id":"capital-1-66","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"我失去了一个相交四十年的最好的、最亲密的朋友，他给我的教益是无法用言语形容的。现在，不论出版这个第三版的任务，还是出版以手稿形式遗留下来的第二卷的任务，都落在我的身上了。在这里，我应该告诉读者，我是怎样履行前一项任务的。","language":"中文","translation":false},{"id":"capital-1-67","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"马克思原想把第一卷原文大部分改写一下，把某些论点表达得更明确一些，把新的论点增添进去，把直到最近时期的历史材料和统计材料补充进去。由于他的病情和急于完成第二卷的定稿，他放弃了这一想法。他只作了一些最必要的修改，只把当时出版的法文版[21]中已有的增补收了进去。","language":"中文","translation":false},{"id":"capital-1-68","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"在马克思的遗物中，我发现了一个德文本，其中有些地方他作了修改，标明何处应参看法文版；同时还发现了一个法文本，其中准确地标出了所要采用的地方。这些修改和增补，除少数外，都属于本书的最后一部分，即资本的积累过程那一篇。旧版的这一篇原文比其他各篇更接近于初稿，而前面各篇都作过比较彻底的修改。因此，这一篇的文体更加生动活泼，更加一气呵成，但也更不讲究，夹杂英文语气，有不明确的地方；叙述过程中间或有不足之处，因为个别重要论点只是提了一下。","language":"中文","translation":false},{"id":"capital-1-69","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"说到文体，马克思亲自彻底校订了许多章节，并且多次作过口头指示，这就给了我一个标准去取舍英文术语和英文语气。马克思一定还会修改那些增补的地方，并且用他那精练的德语代替流畅的法语；而我只要把它们移译过来，尽量和原文协调一致，也就满足了。","language":"中文","translation":false},{"id":"capital-1-70","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"因此，在这第三版中，凡是我不能确定作者自己是否会修改的地方，我一个字也没有改。我也没有想到把德国经济学家惯用的一些行话弄到《资本论》里面来。例如，这样一种费解的行话：把通过支付现金而让别人为自己劳动的人叫做劳动给予者，把为了工资而让别人取走自己的劳动的人叫做劳动受取者。法文travail〔劳动〕在日常生活中也有“职业”的意思。但是，如果有个经济学家把资本家叫做donneur de travail〔劳动给予者〕，把工人叫做receveur de travail〔劳动受取者〕，法国人当然会把他看作疯子。","language":"中文","translation":false},{"id":"capital-1-71","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"我也不能把原文中到处使用的英制货币和度量衡单位换算成新德制单位。在第一版出版时，德制度量衡种类之多，犹如一年的天数那样，马克有两种（帝国马克当时还只存在于泽特贝尔的头脑中，这是他在三十年代末发明的），古尔登有两种，塔勒至少有三种，其中一种以“新三分之二”[22]为单位。在自然科学上通用的是公制度量衡，在世界市场上通用的是英制度量衡。在这种情况下，对于一部几乎完全要从英国的工业状况中取得实际例证的著作来说，采用英制计量单位是很自然的。这后一种理由直到今天还有决定意义，尤其因为世界市场上的有关情况几乎没有什么变化，而且正是在那些有决定意义的工业部门——制铁业和棉纺织业，至今通用的还几乎完全是英制度量衡。","language":"中文","translation":false},{"id":"capital-1-72","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"最后，我说几句关于马克思的不大为人们了解的引证方法。在单纯叙述和描写事实的地方，引文（例如引用英国蓝皮书）自然是作为简单的例证。而在引证其他经济学家的理论观点的地方，情况就不同了。这种引证只是为了确定：一种在发展过程中产生的经济思想，是什么地方、什么时候、什么人第一次明确地提出的。这里考虑的只是，所提到的经济见解在科学史上是有意义的，能够多少恰当地从理论上表现当时的经济状况。至于这种见解从作者的观点来看是否还有绝对的或相对的意义，或者完全成为历史上的东西，那是毫无关系的。因此，这些引证只是从经济科学的历史中摘引下来作为正文的注解，从时间和首倡者两方面说明经济理论中各个比较重要的成就。这种工作在这样一种科学上是很必要的，这种科学的历史著作家们一直只是以怀有偏见、不学无术、追名逐利而著称。——现在我们也会明白，和第二版跋中所说的情况一样，为什么马克思只是在极例外的场合才引证德国经济学家的言论。","language":"中文","translation":false},{"id":"capital-1-73","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"第二卷可望在1884年出版。","language":"中文","translation":false},{"id":"capital-1-74","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1883年11月7日于伦敦","language":"中文","translation":false},{"id":"capital-1-75","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"关于《资本论》英译本的出版，不需要作任何解释了。但是鉴于本书阐述的理论几年前就已经为英美两国的定期刊物和现代著作经常提到，被攻击或辩护，被解释或歪曲，倒是需要说明一下为什么这个英译本延迟到今天才出版。","language":"中文","translation":false},{"id":"capital-1-76","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"作者于1883年逝世后不久，我们就明显地感到这部著作确实需要一个英文版本，当时赛米尔·穆尔先生（马克思和本文作者多年的朋友，他可能比任何人都更熟悉这部著作）同意担任马克思的遗著处理人迫切希望出版的英译本的翻译工作。我们商定，由我对照原文校订译稿，并且在我认为适当的地方提出修改意见。但是后来，我们看到，穆尔先生本身的业务使他不能如我们大家所期待的那样很快完成翻译工作，于是我们欣然接受了艾威林博士的建议，由他担任一部分翻译工作。同时，马克思的小女儿艾威林夫人建议，由她核对引文，把引自英国作者和蓝皮书并由马克思译成德文的许多文句恢复成原文。除了少数无法避免的例外，她全部完成了这项工作。","language":"中文","translation":false},{"id":"capital-1-77","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"本书下述各部分是艾威林博士翻译的：1.第十章（工作日）和第十一章（剩余价值率和剩余价值量）；2.第六篇（工资，包括第十九章至第二十二章）；3.第二十四章第四节（决定积累量的情况）至本书结尾，包括第二十四章最后一部分，第二十五章和第八篇全部（第二十六章至第三十三章）；4.作者的两篇序言[23]。其余部分全是穆尔先生翻译的。因此，译者只对各自的译文负责，而我对整个工作负全部责任。","language":"中文","translation":false},{"id":"capital-1-78","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"我们全部译文所依据的德文第三版，是我在1883年利用作者遗留的笔记整理的，笔记注明第二版的哪些地方应当改成1873年法文版标出的文句[24]。第二版原文中这样修改的地方，和马克思曾经为一个英译本（大约十年前在美国有人打算出版的一个英译本，但主要由于没有十分合适的译者而作罢）所写的许多书面指示中提出需要修改的地方大体相同。这份手稿是由我们的老朋友，新泽西州霍布根的弗·阿·左尔格提供给我们的。手稿指出，还有一些地方应该按照法文版进行补充；但是因为这份手稿是早在马克思对第三版作最后指示的前几年写的，所以我不敢随便利用它，除非在个别情况下，并且主要是在它有助于我们解决某些疑难问题的情况下才加以利用。而大多数有疑难问题的句子，我们也参考了法文本，因为它指出了，原文中某些有意义而在翻译中不得不舍弃的地方，作者自己也是打算舍弃的。","language":"中文","translation":false},{"id":"capital-1-79","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"可是，有一个困难是我们无法为读者解除的。这就是：某些术语的应用，不仅同它们在日常生活中的含义不同，而且和它们在普通政治经济学中的含义也不同。但这是不可避免的。一门科学提出的每一种新见解，都包含着这门科学的术语的革命。化学是最好的例证，它的全部术语大约每二十年就彻底变换一次，几乎很难找到一种有机化合物不是先后拥有一系列不同的名称的。政治经济学通常满足于照搬工商业生活上的术语并运用这些术语，完全看不到这样做会使自己局限于这些术语所表达的观念的狭小范围。例如，古典政治经济学虽然完全知道，利润和地租都不过是工人必须向自己雇主提供的产品中无酬部分（雇主是这部分产品的第一个占有者，但不是它的最后的唯一的所有者）的一部分、一份，但即使这样，它也从来没有超出通常关于利润和地租的概念，从来没有把产品中这个无酬部分（马克思称它为剩余产品），就其总和即当作一个整体来研究过，因此，也从来没有对它的起源和性质，对制约着它的价值的以后分配的那些规律有一个清楚的理解。同样，一切产业，除了农业和手工业以外，都一概被包括在制造业（manufacture）这个术语中，这样，经济史上两个重大的本质不同的时期即以手工分工为基础的真正工场手工业时期和以使用机器为基础的现代工业时期的区别，就被抹杀了。不言而喻，把现代资本主义生产只看作是人类经济史上一个暂时阶段的理论所使用的术语，和把这种生产形式看作是永恒的最终阶段的那些作者所惯用的术语，必然是不同的。","language":"中文","translation":false},{"id":"capital-1-80","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"关于作者的引证方法，不妨说几句。在大多数场合，也和往常一样，引文是用作证实文中论断的确凿证据。但在不少场合，引证经济学著作家的文句是为了证明：什么时候、什么地方、什么人第一次明确地提出某一观点。只要引用的论点具有重要意义，能够多少恰当地表现某一时期占统治地位的社会生产和交换条件，马克思就加以引证，至于马克思是否承认这种论点，或者说，这种论点是否具有普遍意义，那是完全没有关系的。因此，这些引证是从科学史上摘引下来并作为注解以充实正文的。","language":"中文","translation":false},{"id":"capital-1-81","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"我们这个译本只包括这部著作的第一卷。但这第一卷是一部相当完整的著作，并且二十年来一直被当作一部独立的著作。1885年我用德文出版的第二卷，由于没有第三卷，显然是不完全的，而第三卷在1887年年底以前不能出版。到第三卷德文原稿刊行时，再考虑准备第二、三两卷的英文版也为时不晚。","language":"中文","translation":false},{"id":"capital-1-82","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"《资本论》在大陆上常常被称为“工人阶级的圣经”。任何一个熟悉工人运动的人都不会否认：本书所作的结论日益成为伟大的工人阶级运动的基本原则，不仅在德国和瑞士是这样，而且在法国，在荷兰和比利时，在美国，甚至在意大利和西班牙也是这样；各地的工人阶级都越来越把这些结论看成是对自己的状况和自己的期望所作的最真切的表述。而在英国，马克思的理论正是在目前对社会主义运动产生着巨大的影响，这个运动在“有教养者”队伍中的传播，不亚于在工人阶级队伍中的传播。但这并不是一切。彻底研究英国的经济状况成为国民的迫切需要的时刻，很快就会到来。这个国家的工业体系的运动，——没有生产的从而没有市场的经常而迅速的扩大，这种运动就不可能进行，——已趋于停滞。自由贸易已经无计可施了；甚至曼彻斯特对自己这个昔日的经济福音也发生了怀疑[25]。迅速发展的外国工业，到处直接威胁着英国的生产，不仅在受关税保护的市场上，而且在中立市场上，甚至在英吉利海峡的此岸都是这样。生产力按几何级数增长，而市场最多也只是按算术级数扩大。1825年至1867年每十年反复一次的停滞、繁荣、生产过剩和危机的周期，看来确实已经结束，但这只是使我们陷入无止境的经常萧条的绝望泥潭。人们憧憬的繁荣时期将不再来临；每当我们似乎看到繁荣时期行将到来的种种预兆，这些预兆又消失了。而每一个冬天的来临都重新提出这一重大问题：“怎样对待失业者”；虽然失业人数年复一年地增加，却没有人解答这个问题；失业者再也忍受不下去，而要起来掌握自己命运的时刻，几乎指日可待了。毫无疑问，在这样的时刻，应当倾听这样一个人的声音，这个人的全部理论是他毕生研究英国的经济史和经济状况的结果，他从这种研究中得出这样的结论：至少在欧洲，英国是唯一可以完全通过和平的和合法的手段来实现不可避免的社会革命的国家。当然，他从来没有忘记附上一句话：他并不指望英国的统治阶级会不经过“维护奴隶制的叛乱”[26]而屈服在这种和平的和合法的革命面前。","language":"中文","translation":false},{"id":"capital-1-83","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"第四版要求我尽可能把正文和注解最后确定下来。我是怎样实现这一要求的，可以简单说明如下：","language":"中文","translation":false},{"id":"capital-1-84","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"根据再一次对照法文版和根据马克思亲手写的笔记，我又把法文版的一些地方补充到德文原文中去。这些补充是在第80页（第3版第88页）、第458—460页（第3版第509—510页）、第547—551页（第3版第600页）、第591—593页（第3版第644页）和第596页（第3版第648页）注79。此外，我还按照法文版和英文版把一个很长的关于矿工的注解（第3版第509—515页）移入正文（第4版第461—467页）。其他一些小改动都是纯技术性的。","language":"中文","translation":false},{"id":"capital-1-85","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"其次，我还补加了一些说明性的注释，特别是在那些由于历史情况的改变看来需要加注的地方。所有这些补加的注释都括在四角括号里，并且注有我的姓名的第一个字母或《D. H.》。[27]","language":"中文","translation":false},{"id":"capital-1-86","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"最近出版英文版时，曾对许多引文作了全面的校订，这是很必要的。马克思的小女儿爱琳娜不辞劳苦，对所有引文的原文都进行了核对，使占引文绝大多数的英文引文不再是德文的转译，而是它原来的英文原文。因此，在出第四版时，我必须参考这个恢复了原文的版本。在参考中发现了某些细小的不确切的地方：有的引文页码弄错了（这一部分是由于从笔记本上转抄时抄错了，一部分是由于前三版堆积下来的排印的错误）；有的引号和省略号放错了位置（从札记本上抄录这么多的引文，这种差错是不可避免的）；还有某些引文在翻译时用字不很恰当。有一些引文是根据马克思在1843—1845年在巴黎记的旧笔记本抄录的，当时马克思还不懂英语，他读英国经济学家的著作是读的法译本；那些经过两次转译的引文多少有些走了原意——如引自斯图亚特、尤尔等人著作的话就是如此。这些地方我都改以英文原文为根据。其他一些细小的不确切和疏忽的地方也都改正了。把第四版和以前各版对照一下，读者就会看出，所有这些细微的改正，并没有使本书的内容有丝毫值得一提的改变。只有一段引文没有找到出处，这就是理查·琼斯的一段话（第4版第562页注47）；多半是马克思把书名写错了[28]。所有其余的引文都仍然具有充分的说服力，甚至由于现在更加确切而更加具有说服力了。","language":"中文","translation":false},{"id":"capital-1-87","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"不过，在此我不得不回溯一段往事。","language":"中文","translation":false},{"id":"capital-1-88","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"据我所知，马克思的引文的正确性只有一次被人怀疑过。由于马克思逝世后这段引文的事又被重新提起，所以我不能不讲一讲。[29]","language":"中文","translation":false},{"id":"capital-1-89","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1872年3月7日，德国工厂主联盟的机关刊物柏林《协和》杂志刊登了一篇匿名作者的文章，标题是《卡尔·马克思是怎样引证的》。这篇文章的作者义愤填膺、粗暴无礼地指责马克思歪曲地引证了格莱斯顿1863年4月16日预算演说中的话(这句话引用在1864年国际工人协会成立宣言[30]中，并且在《资本论》第1卷第4版第617页即第3版第670—671页上再次引用)。这句话就是：“财富和实力这样令人陶醉的增长……完全限于有产阶级。”这篇文章的作者说，在《汉萨德》的（准官方的）速记记录中根本没有马克思引的这句话。“但是在格莱斯顿的演说中根本没有这句话。他在演说中说的和这句话正好相反。〈接着是黑体字〉[31]马克思在形式上和实质上增添了这句话！”","language":"中文","translation":false},{"id":"capital-1-90","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"马克思在5月接到了这一期《协和》杂志，他在6月1日的《人民国家报》上回答了这个匿名作者。由于当时他已记不起这一句话是引自哪一家报纸的报道，所以只得从两种英文出版物中举出意思完全相同的这句话，接着他引用了《泰晤士报》的报道。根据这一报道，格莱斯顿说：","language":"中文","translation":false},{"id":"capital-1-91","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"“从财富的观点来看，这个国家的状况就是这样。我应当承认，我几乎会怀着忧虑和悲痛的心情来看待财富和实力这样令人陶醉的增长，如果我相信，这种增长仅限于富裕阶级的话。这里完全没有注意到工人居民的状况。我刚刚描述的增长，亦即以我认为十分确切的材料为根据的增长，完全限于有产阶级”。","language":"中文","translation":false},{"id":"capital-1-92","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"可见，格莱斯顿在这里是说，如果事实如此，他将感到悲痛，而事实确实是：实力和财富这样令人陶醉的增长完全限于有产阶级；至于准官方的《汉萨德》，马克思接着说道：“格莱斯顿先生非常明智地从事后经过炮制的他的这篇演说中删掉了无疑会使他这位英国财政大臣声誉扫地的一句话；不过，这是英国常见的议会传统，而决不是小拉斯克尔反对倍倍尔的新发明。”[32]","language":"中文","translation":false},{"id":"capital-1-93","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这个匿名作者越来越恼怒了。他在自己的答复（7月4日《协和》杂志）中，抛开了所有第二手的材料，羞羞答答地暗示，按“惯例”只能根据速记记录引用议会演说；但接着他硬说，《泰晤士报》的报道（其中有这句“增添”的话）和《汉萨德》的报道（其中没有这句话）“在实质上完全一致”，还说什么《泰晤士报》的报道所包含的意思“同成立宣言中这个声名狼藉的地方正好相反”，然而这位先生却尽量避而不谈这样一个事实：除了这种所谓“正好相反”的意思外，还恰恰有那个“声名狼藉的地方”。不过，匿名作者自己也感到难于招架，只有玩弄新的花招才能自拔。他把自己那篇象上面所证明的通篇“无耻地撒谎”的文章，塞满了极其难听的骂人话，什么“恶意”，“不诚实”，“捏造的材料”，“那个捏造的引文”，“无耻地撒谎”，“完全是伪造的引文”，“这种伪造”，“简直无耻”，等等。同时他又设法暗地里使争论的问题转向新的方面，并预告要“在另一篇文章中说明，我们〈即这个“不会捏造的”匿名作者〉认为格莱斯顿的话包含什么意思”。好象他那无关紧要的见解还有点意义似的！这另一篇文章在7月11日的《协和》杂志上刊登出来了。","language":"中文","translation":false},{"id":"capital-1-94","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"马克思在8月7日的《人民国家报》上又作了一次答辩，这次还引用了1863年4月17日的《晨星报》和《晨报》的有关的地方。根据这两家报纸的报道，格莱斯顿说，他会怀着忧虑……的心情来看待财富和实力令人陶醉的增长，如果他相信，增长只限于富裕阶级的话，而这种增长确实只限于占有财产的阶级；可见，在这两种报道中，也都一字不差地重复着所谓马克思“增添”的那句话。马克思接着把《泰晤士报》的字句同《汉萨德》的字句加以对比后再一次断定，第二天早上出版的三种互不相干的报纸在这一点上完全相同的报道，显而易见地证实了这句话的真实性，而这句话在根据某种“惯例”审查过的《汉萨德》中却没有，用马克思的话说，这是格莱斯顿“事后隐瞒了”。马克思最后声明，他没有时间再同匿名作者争辩，而匿名作者好象也觉得够了，至少马克思以后再没有收到《协和》杂志。","language":"中文","translation":false},{"id":"capital-1-95","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这个事件看来就此终结而被人遗忘了。诚然后来有一两次从一些同剑桥大学有来往的人那里传来一些神秘的谣言，说什么马克思在《资本论》里犯了写作上的大错，但无论怎样仔细追究，都得不到任何确实的结果。可是，1883年11月29日，即马克思逝世后八个月，《泰晤士报》上登载了一封剑桥三一学院的来信，署名是塞德莱·泰勒。这个搞最温和的合作运动的小人物在来信中完全出乎意外地使我们终于不仅弄清了剑桥的谣言，而且也弄清了《协和》杂志上的那个匿名作者。","language":"中文","translation":false},{"id":"capital-1-96","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这个三一学院的小人物写道：","language":"中文","translation":false},{"id":"capital-1-97","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"“使人特别惊异的是，布伦坦诺教授（当时在布勒斯劳，现在斯特拉斯堡任教）终于……揭露了在国际〈成立〉宣言中引用格莱斯顿演说时所怀的恶意。卡尔·马克思先生……曾企图为此进行辩护，但很快就被布伦坦诺巧妙的攻击打垮了，而他在垂死的挣扎中还敢于断言，格莱斯顿先生在1863年4月17日《泰晤士报》刊登他的演说原文之后，加工炮制了一份供《汉萨德》登载的演说记录，删掉了一句无疑会使他这位英国财政大臣声誉扫地的话。当布伦坦诺通过仔细地对比不同的文本，证明《泰晤士报》和《汉萨德》的报道彼此一致，绝对没有通过狡猾的断章取义而给格莱斯顿的话硬加上的那个意思时，马克思就借口没有时间而拒绝继续进行论战！”","language":"中文","translation":false},{"id":"capital-1-98","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"这就是全部事情的真相！布伦坦诺先生在《协和》杂志上发动的匿名攻击，在剑桥生产合作社的幻想小说中是多么辉煌！你看，这个德国工厂主联盟的圣乔治这样摆着架式，这样挺着剑[33]，进行“巧妙的攻击”，而恶龙马克思“很快被打垮”，倒在他的脚下，“在垂死的挣扎中”断了气！","language":"中文","translation":false},{"id":"capital-1-99","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"但这种阿里欧斯托式的全部战斗描写，只是为了掩盖我们这位圣乔治的诡计。他在这里再也不提什么“增添”，什么“伪造”，而只是说“狡猾的断章取义”了。整个问题完全转向另一个方面了，至于为什么要这样做，圣乔治和他的剑桥的卫士当然非常清楚。","language":"中文","translation":false},{"id":"capital-1-100","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"爱琳娜·马克思在《今日》月刊（1884年2月）上对泰勒做了答辩——因为《泰晤士报》拒绝刊登她的文章。她首先把辩论归结到原来的这一点上：是不是马克思“增添”了这句话？塞德莱·泰勒先生回答说，在他看来，在马克思和布伦坦诺之间的争论中，","language":"中文","translation":false},{"id":"capital-1-101","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"“格莱斯顿先生的演说中是否有这句话完全是次要问题，更主要的是，引用这句话的目的是正确传达格莱斯顿的意思，还是歪曲他的意思”。","language":"中文","translation":false},{"id":"capital-1-102","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"接着，他承认说，《泰晤士报》的报道“的确包含有文字上的矛盾”，但是，如果正确地推断，也就是照自由主义的格莱斯顿的意思推断，据说整个上下文正好表明了格莱斯顿所想说的那个意思（1884年3月《今日》月刊）。这里最可笑的是，虽然照匿名的布伦坦诺所说，按“惯例”应当从《汉萨德》引证，《泰晤士报》的报道“必然很粗糙”，但我们这个剑桥的小人物却固执地不从《汉萨德》引证，而从《泰晤士报》引证。当然，《汉萨德》上根本没有这句倒霉的话！","language":"中文","translation":false},{"id":"capital-1-103","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"爱琳娜·马克思没有费很大力气就在同一期《今日》月刊上驳倒了这个论据。要么泰勒先生读过1872年的论战文章，如果是这样，那他现在就是在“撒谎”，他的撒谎表现在：他不但“增添”了原来没有的东西，而且“否定”了原来已有的东西。要么他根本没有读过这些论战文章，那他就根本无权开口。无论如何，他再也不敢支持他的朋友布伦坦诺控告马克思“增添”引文了。相反，现在他不是控告马克思“增添”，而是控告马克思删掉了一句重要的话。其实这句话被引用在成立宣言的第5页上，只在这句所谓“增添”的话上面几行。至于格莱斯顿演说中包含的“矛盾”，恰好正是马克思指出了（《资本论》第618页注105，即第3版第672页）“1863年和1864年格莱斯顿的预算演说中不断出现的显著的矛盾”！不过，他不象塞德莱·泰勒那样企图把这些矛盾溶化在自由主义的温情之中。爱·马克思在答辩的结尾说：“事实上完全相反。马克思既没有删掉任何值得一提的东西，也绝对没有‘增添’任何东西。他只是把格莱斯顿在演说中确实说过、而又用某种方法从《汉萨德》的报道中抹掉的一句话重新恢复，使它不致被人们遗忘。”","language":"中文","translation":false},{"id":"capital-1-104","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"从此以后，连塞德莱·泰勒先生也闭口不言了。大学教授们所发动的整个这场攻击，在两大国持续二十年之久，而其结果是任何人也不敢再怀疑马克思写作上的认真态度了。可以想象得到，正如布伦坦诺先生不会再相信《汉萨德》象教皇般永无谬误那样，塞德莱·泰勒先生今后也将不会再相信布伦坦诺先生的文坛战报了。","language":"中文","translation":false},{"id":"capital-1-105","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1890年6月25日于伦敦","language":"中文","translation":false},{"id":"capital-1-106","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[1] 《资本论》是马克思的主要著作。马克思写这部著作花费了四十年的时间，从四十年代初起直到他逝世。“马克思认为经济制度是政治上层建筑借以树立起来的基础，所以他特别注意研究这个经济制度。”（《列宁全集》中文版第19卷第5页）","language":"中文","translation":false},{"id":"capital-1-107","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1843年底，马克思在巴黎开始系统地研究政治经济学。他研究经济文献的目的，是要写一部批判现存制度和资产阶级政治经济学的巨著。他在这方面进行的最初的研究反映在以下这些著作里：《1844年的经济哲学手稿》、《德意志意识形态》，《哲学的贫困》、《雇佣劳动与资本》、《共产党宣言》等等。在这些著作中就已经揭示了资本主义剥削的原理、资本家的利益和雇佣工人的利益之间的不可调和的对立、资本主义一切经济关系的对抗性和暂时性。","language":"中文","translation":false},{"id":"capital-1-108","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1848-1849年急风暴雨般的革命事件使马克思暂时中断了经济学的研究。1849年8月马克思被迫侨居伦敦，在那里他才继续进行这―研究。他深刻而全面地研究了国民经济史和各国特别是英国当时的经济，因为英国当时是典型的资本主义国家。在这一时期，他感兴趣的有土地所有制的历史和地租理论、货币流通和价格的历史与理论、经济危机、技术史和工艺史以及农艺学和农业化学的问题。","language":"中文","translation":false},{"id":"capital-1-109","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"马克思是在非常困难的条件下进行工作的。他必须不断地同贫困作斗争，并且时常要为挣钱维持生活而搁下研究工作。由于马克思在物质条件极差的情况下长期过度劳累，产生了恶果——他身患重病。虽然如此，到1857年，他已经做好巨大的准备工作，这就使他能够开始进入研究工作的完成阶段——对收集的材料进行系统的整理和概括。","language":"中文","translation":false},{"id":"capital-1-110","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"1857年8月至1858年6月，马克思写了约五十印张的手稿，这看来是未来《资本论》的草稿。1857年11月，马克思拟定了他的著作的计划，后来又对该计划作了详细的和重要的修改。他把这部批判各种经济范畴的著作分为六册：","language":"中文","translation":false},{"id":"capital-1-111","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"（1)资本（包括一些导言性章节）；（2）地产；（3）雇佣劳动；（4）国家；（5）对外贸易；（6）世界市场。预定第一册（《资本》)又分成四篇：（a）资本；（b）资本的竞争；（c）信用；（d）股份资本。第一篇《资本一般》又分为三章：（1）资本的生产过程；（2）资本的流通过程；（3）两者的统一，或资本和利润、利息。这三章后来成了全部著作分为三卷《资本论》的基础。政治经济学史和社会主义史打算成为另一部著作的对象。同时马克思决定把他写的书分册出版，第一分册“应当是一部比较完整的著作”，它只包括第一册的第一篇，这一篇分为三章：（1）商品；（2）货币或简单流通；（3）资本。但是出于政治上的考虑，第一分册的最后定稿即《政治经济学批判》一书中没有把第三章放进去。马克思指出，正是从这一章开始了真正的战斗，他认为，在存在官方书报检查、对不合统治阶级心愿的作者进行警察迫害和各种陷害的情况下，在广大的公众尚未了解这部新的著作之前，一开始就出版这一章是不适宜的。马克思为第一分册专门写了商品一章，并且认真地改写了1857—1858年手稿中关于货币的一章。","language":"中文","translation":false},{"id":"capital-1-112","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"《政治经济学批判》于1859年出版。曾经计划在这之后很快出版第二分册，即上述构成1857—1858年手稿主要内容的资本一章。马克思在英国博物馆里重新系统地研究政治经济学。但是不久，由于必须在报刊上揭露路易·波拿巴雇用的密探卡·福格特的诬蔑性攻击和做其他急事，他不得不停止研究工作达整整一年半之久。只是到1861年8月，他又开始写篇幅巨大的手稿，到1863年年中才完成。手稿共二十三本，约二百印张，标题与1859年出版的《政治经济学批判》相同。这一手稿的绝大部分（第VI—XV本和第XVIII本)是阐述经济学说史的，构成《剩余价值理论》即《资本论》第四卷。在头五本以及部分地在第XIX—XXIII本中，叙述了《资本论》第一卷的问题。马克思在这里分析了货币向资本的转化，阐述了绝对剩余价值和相对剩余价值的学说，并涉及了一系列其他问题。第XIX本和第XX本，为第一卷第十三章《机器和大工业》奠定了坚实的基础，引用了极其丰富的技术史资料，对资本主义工业中机器的使用作了十分详细的经济分析。第XXI—XXIII本阐述同《资本论》各卷（包括第二卷）有关的各种问题。第XVI本和第XVII本专门阐述第三卷的问题。因此，1861—1863年手稿多少都触及了所有四卷《资本论》的问题。","language":"中文","translation":false},{"id":"capital-1-113","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"马克思在以后的写作过程中，决定依照他过去分为三部分写的《资本一般》这一篇所拟定的计划来安排全书的结构。手稿的历史批判部分应构成第四个，即最后一个环节。马克思在1866年10月13日给库格曼的信中写道:“全部著作分为以下几部分：第一册资本的生产过程；第二册资本的流通过程；第三册总过程的各种形式；第四册理论史。”马克思也放弃了过去分册出版这一著作的计划，他决定不妨先基本上完成这部著作，然后再出版。","language":"中文","translation":false},{"id":"capital-1-114","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"为此，马克思继续致力于自己的著作，特别是致力于1861—1863年手稿中还没有得到充分阐述的部分。他补充研究了大量的经济文献和技术文献，其中有关于农业、关于信用和货币流通问题的文献，他研究了统计材料、各种议会文件、关于工业中的儿童劳动和英国无产阶级居住状况的官方报告等等。接着马克思用两年半的时间（从1863年8月至1865年底)完成了新的、篇幅很大的手稿，这就是三卷《资本论》理论著作的第一个详加琢磨的稿本。只是在全部著作完成（1866年1月）之后，马克思才进行付印前的最后加工。根据恩格斯的建议，他决定不一下子付印全部著作，而是首先只付印第一卷。马克思极其细致地完成了这次最后的加工，这一工作实质上是整个第一卷的一次重新修订。为了叙述的完整、充分和明确，马克思认为，必须在《资本论》第一卷的开头部分扼要地复述1859年出版的《政治经济学批判》一书的内容中的主要问题。在目前的版本中，这些问题构成整个第一篇（《商品和货币》)，而在第一版中，是在第一章（《商品和货币》）中加以叙述的。","language":"中文","translation":false},{"id":"capital-1-115","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"在《资本论》第一卷出版（1867年9月）以后，马克思继续从事第一卷的工作，准备德文版的再版和出版外文译本。他在第二版（1872年）里作了大量的修改，就出版俄译本作了重要的指示。俄译本是1872年在彼得堡出版的，它是《资本论》的第一个外文译本。马克思对1872—1875年分册出版的法译本作了相当大的加工和校订。","language":"中文","translation":false},{"id":"capital-1-116","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"另一方面，在《资本论》第一卷出版以后，马克思继续从事其他各卷的工作，他打算迅速完成全部著作。但是他没有能做到这一点。国际工人协会总委员会中的多方面的活动占去他许多时间。由于健康状况不好，他不得不越来越频繁地中断他的工作。马克思的极度的科学的认真精神和一丝不苟的态度，严格的自我批评——正如恩格斯所说，马克思就是以这种自我批评的精神，“力求在公布他的经济学方面的伟大发现以前，使它们达到最完善的程度”——使他在研究这一或那一问题时不断地回头做补充的考察。而在这一创作工作的过程中，也出现许多新的问题。","language":"中文","translation":false},{"id":"capital-1-117","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"《资本论》的后两卷是在马克思逝世后，由恩格斯准备付印和出版的。第二卷于1885年出版，第三卷于1894年出版。这样，恩格斯就对科学共产主义的宝库作出了无法估量的贡献。","language":"中文","translation":false},{"id":"capital-1-118","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"马克思逝世后，恩格斯还校订了《资本论》第一卷英译本〈1887年出版、准备了《资本论》第一卷的德文第三版（1883年）和第四版（1890年〕。此外，在马克思已逝世而恩格斯尚在世的时候，曾先后出版了《资本论》第一卷的下列各种版本：三个伦敦版英文本（1888、1889和1891年）、三个纽约版英文本（1887、1889和1890年）、巴黎版法文本1：1885年〉，哥本哈根版丹麦文本01885年、马德里版西班牙文本01886年；1，都灵版意大利文本1：1886年〉，莱比锡版波兰文本（1884—1889年）、阿姆斯特丹版荷兰文本（1894年），以及许多其他的不完全的版本。","language":"中文","translation":false},{"id":"capital-1-119","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"在准备《资本论》第一卷第四版时（1890年），恩格斯根据马克思本人的指示，对正文和脚注作了最后的校订。现在全世界都根据德文第四版再版和翻译这部著作。——第7页。","language":"中文","translation":false},{"id":"capital-1-120","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[2] 指《资本论》1867年德文第一版第一卷第一章，标题是《商品和货币》，再版时，马克思修订了自己的著作，对它的结构也作了很大的改动。他把原先的第一章和附录改为独立的三章，这三章构成第一篇。——第7页。","language":"中文","translation":false},{"id":"capital-1-121","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[3] 这样做之所以更加必要，是因为甚至斐·拉萨尔著作中反对舒尔采-德里奇的部分，即他声称已经提出我对那些问题的阐述的“思想精髓”的部分[4]，也包含着严重的误解。顺便说一下，斐·拉萨尔经济著作中所有一般的理论原理，如关于资本的历史性质、关于生产关系和生产方式之间的联系等等，几乎是逐字地——甚至包括我创造的术语——从我的作品中抄去的，而且没有说明出处，这样做显然是出于宣传上的考虑。我当然不是说他在细节上的论述和实际上的应用，这同我没有关系。","language":"中文","translation":false},{"id":"capital-1-122","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[4] 指斐·拉萨尔《巴师夏-舒尔采-德里奇先生，经济的尤利安，或者：资本和劳动》1864年柏林版（《Herr Bastiat-Schulze von Delitzsch, der ökonomische Julian, oder: Capital und arbeit》. Berlin, 1864）一书的第三章。——第7页。","language":"中文","translation":false},{"id":"capital-1-123","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[5] 只要换一个名字，这正是说的阁下的亊情（Mutato nomine de te fabula narratur）——引自贺雷西《讽刺诗集》第一卷第一首。——第8，296页。","language":"中文","translation":false},{"id":"capital-1-124","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[6] 蓝皮书（Blue Books）是英国议会和外交部发表的资料和外交文件的总称。蓝皮书因蓝色的封皮而得名，英国从十七世纪开始发表蓝皮书，它是研究英国经济史和外交史的主要的官方资料。——第12、542页。","language":"中文","translation":false},{"id":"capital-1-125","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[7] 走你的路，让人们去说罢！（Segui il tuo corso, e lascia dir le genti!）——套用了但丁《神曲》炼狱篇第五首歌中的一句话。——第13页。","language":"中文","translation":false},{"id":"capital-1-126","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[8] 济·迈尔《维也纳的社会问题。一个“劳动给予者”著》1871年维也纳版（S. Mayer.《Die sociale Frage in Wien. Studie eines《Arbeitgebers》》. Wien, 1871）。——第15页。","language":"中文","translation":false},{"id":"capital-1-127","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[9] 在《资本论》第一卷第四版（1890年）中，这篇跋的头四段被删掉。本版把它全文刊印。——第15页。","language":"中文","translation":false},{"id":"capital-1-128","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[10] 第3版和第4版中是：毫无希望的。——编者注","language":"中文","translation":false},{"id":"capital-1-129","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[11] 见我的《政治经济学批判》第39页[12]。","language":"中文","translation":false},{"id":"capital-1-130","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[12] 见《马克思恩格斯全集》中文版第13卷第51页。——第16页。","language":"中文","translation":false},{"id":"capital-1-131","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[13] 反谷物法同盟是1838年由工厂主科布顿和布莱特创立的。为了维护工业资产阶级的利益，同盟争取废除了为迎合土地贵族而实行的旨在限制或禁止从国外输入谷物的所谓谷物法。1815年实行的谷物法规定，在英国本国的谷物价格低于每夸特80先令时禁止输入谷物。1822年对这个法律作了某些形式上的修改。1828年实行了调节制，按照这个制度，国内市场谷物价格下跌时谷物进口税就提高，相反，国内市场谷物价格上涨时谷物进口税就降低。同盟争取废除谷物法，确立自由贸易，其目的是为了降低国内谷物价格，从而降低雇佣工人的工资。贸易自由的口号被同盟广泛利用于蛊惑性的宣传，说工人和工业主的利益是一致的。谷物法于1846年被废除。——第17页。","language":"中文","translation":false},{"id":"capital-1-132","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[14] 指约·狄慈根的文章《卡尔“马克思〈资本论。政治经济学批判〉1867年汉堡版》，载于《民主周报》1868年第31、34、35和36号。1869—1876年该报以《人民国家报》的新名称出版。——第18页。","language":"中文","translation":false},{"id":"capital-1-133","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[15] 德国庸俗经济学的油嘴滑舌的空谈家，指责我的著作的文体和叙述方法。没有人会比我本人更严厉地评论《资本论》的文字上的缺点。然而，为了使这些先生及其读者受益和愉快，我要在这里援引一篇英国的和一篇俄国的评论。同我的观点完全敌对的《星期六评论》在其关于德文第一版的短评中说道：叙述方法“使最枯燥无味的经济问题具有一种独特的魅力”。1872年4月20日的《圣彼得堡消息报》也说：“除了少数太专门的部分以外，叙述的特点是通俗易懂，明确，尽管研究对象的科学水平很高却非常生动。在这方面，作者……和大多数德国学者大不相同，这些学者……用含糊不清、枯燥无味的语言写书，以致普通人看了脑袋都要裂开。”但是，对现代德国民族主义自由主义教授的著作的读者说来，要裂开的是和脑袋完全不同的东西。","language":"中文","translation":false},{"id":"capital-1-134","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[16] 这里指1867—1883年在巴黎出版的杂志《实证哲学。评论》。在1868年11—12月的第3期上发表了一篇对《资本论》第一卷的短评，作者是实证主义哲学家奥·孔德的信徒叶·瓦·德·罗别尔提。——第19页。","language":"中文","translation":false},{"id":"capital-1-135","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[17] 尼·季别尔《李嘉图的价值和资本的理论的最新补充和解释》1871年基辅版第170页。——第19页。","language":"中文","translation":false},{"id":"capital-1-136","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[18] 指伊·伊·考夫曼写的《卡尔·马克思的政治经济学批判的观点》一文。——第20页。","language":"中文","translation":false},{"id":"capital-1-137","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[19] 见《马克思恩格斯全集》中文版第13卷第8—10页。——第20页。","language":"中文","translation":false},{"id":"capital-1-138","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[20] 指德国资产阶级哲学家毕希纳、朗格、杜林、费希纳等人。——第24页。","language":"中文","translation":false},{"id":"capital-1-139","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[21] 《资本论》第一卷法文版是1872年至1875年在巴黎分册出版的。——第30页。","language":"中文","translation":false},{"id":"capital-1-140","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[22] “新三分之二”是十七世纪末至十九世纪中叶在一些德意志公国中流通的一种银币，值三分之二塔勒。——第31页。","language":"中文","translation":false},{"id":"capital-1-141","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[23] 《资本论》第一卷英文版各章的编号同德文版不一致。——第34页。","language":"中文","translation":false},{"id":"capital-1-142","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[24] 《资本论》，卡尔·马克思著，莫·约·鲁瓦译，全文由作者校阅，由拉沙特尔在巴黎出版。这个译本，特别是该书的最后一部分，对德文第2版作了相当多的修改和补充。","language":"中文","translation":false},{"id":"capital-1-143","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[25] 在今天下午举行的曼彻斯特商会季度会议上，对自由贸易问题进行了激烈的辩论。会上曾提出决议案：“鉴于我们徒然等了40年时间，尚未见到其他国家效法英国的自由贸易，本商会认为，现在已到了重新考虑自己立场的时候。”决议案仅以一票之差被否决，即21票赞成，22票反对。——1886年11月1日《旗帜晚报》。","language":"中文","translation":false},{"id":"capital-1-144","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[26] “维护奴隶制的叛乱”是美国南部的奴隶主发动的一次叛乱，这次叛乱导致了1861—1865年的南北战争。——第37、317、468页。","language":"中文","translation":false},{"id":"capital-1-145","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[27] 本卷括在花括号｛｝里，并注有弗·恩·。——编者注","language":"中文","translation":false},{"id":"capital-1-146","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[28] 马克思没有把书名写错，而是把页码写错了。——第39，656页。","language":"中文","translation":false},{"id":"capital-1-147","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[29] 资产阶级的代表一再诽谤马克思，攻击他故意捏造格莱斯顿1863年4月16日演说的引文。为了揭露这种攻击，恩格斯专门写了一部著作《布伦坦诺contra 马克思。关于所谓捏造引文问题。事情的经过和文件》，这部著作于1891年在汉堡出版（见《马克思恩格斯全集》中文版第22卷第107—213页；)。——第39页。","language":"中文","translation":false},{"id":"capital-1-148","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[30] 见《马克恩恩格斯全集》中文版第16卷第3—14页。——第40页，","language":"中文","translation":false},{"id":"capital-1-149","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[31] 本卷引文中凡是尖括号〈〉内的话或标点符号都是马克思或恩格斯加的。——译者注","language":"中文","translation":false},{"id":"capital-1-150","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[32] 马克思在谈到“小拉斯克尔反对倍倍尔的新发明”时是指下面这件事。在1871年11月8日帝国国会会议上，资产阶级议员、民族自由党人拉斯克尔在反对倍倍尔的辩论中声明说，如果德国社会民主党工人想要学巴黎公社社员的样子，那末“正派的和有财产的公民们就要用棍棒打死他们”。但是演讲人不敢把这句话照直公布出来，因此在速记记录中“用棍棒打死他们”已被改为“用自己的权力压服他们”。倍倍尔揭穿了这种伪造手法。拉斯克尔在工人群众中成了嘲笑的对象。拉斯克尔由于身材矮小，就得到了一个讽刺性的诨名“小拉斯克尔”。——第41页。","language":"中文","translation":false},{"id":"capital-1-151","author":"马克思","title":"资本论·第一卷","location":"序和跋","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/capital/00.htm","text":"[33] 恩格斯套用了吹牛家、胆小鬼福斯泰夫说的一句话。这个福斯泰夫曾讲述他一个人怎样用剑击败五十个人（莎士比亚《亨利四世》前篇第二幕第四场；)。——第43页。","language":"中文","translation":false},{"id":"capital-2-1","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-2-2","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"1、商品的两个因素：使用价值和价值(价值实体，价值量)","language":"中文","translation":false},{"id":"capital-2-3","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"2、体现在商品中的劳动的二重性","language":"中文","translation":false},{"id":"capital-2-4","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"A、简单的、个别的或偶然的价值形式","language":"中文","translation":false},{"id":"capital-2-5","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(1)价值表现的两极：相对价值形式和等价形式","language":"中文","translation":false},{"id":"capital-2-6","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(a)相对价值形式的内容","language":"中文","translation":false},{"id":"capital-2-7","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(b)相对价值形式的量的规定性","language":"中文","translation":false},{"id":"capital-2-8","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(4)简单价值形式的总体","language":"中文","translation":false},{"id":"capital-2-9","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"B、总和的或扩大的价值形式","language":"中文","translation":false},{"id":"capital-2-10","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(1)扩大的相对价值形式","language":"中文","translation":false},{"id":"capital-2-11","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(3)总和的或扩大的价值形式的缺点","language":"中文","translation":false},{"id":"capital-2-12","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(1)价值形式的变化了的性质","language":"中文","translation":false},{"id":"capital-2-13","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(2)相对价值形式和等价形式的发展关系","language":"中文","translation":false},{"id":"capital-2-14","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(3)从一般价值形式到货币形式的过渡","language":"中文","translation":false},{"id":"capital-2-15","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"4、商品的拜物教性质及其秘密","language":"中文","translation":false},{"id":"capital-2-16","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"1、商品的两个因素：使用价值","language":"中文","translation":false},{"id":"capital-2-17","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"和价值(价值实体，价值量)","language":"中文","translation":false},{"id":"capital-2-18","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"资本主义生产方式占统治地位的社会的财富，表现为“庞大的商品堆积”[1]，单个的商品表现为这种财富的元素形式。因此，我们的研究就从分析商品开始。","language":"中文","translation":false},{"id":"capital-2-19","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品首先是一个外界的对象，一个靠自己的属性来满足人的某种需要的物。这种需要的性质如何，例如是由胃产生还是由幻想产生，是与问题无关的[2]。这里的问题也不在于物怎样来满足人的需要，是作为生活资料即消费品来直接满足，还是作为生产资料来间接满足。","language":"中文","translation":false},{"id":"capital-2-20","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"每一种有用物，如铁、纸等等，都可以从质和量两个角度来考察。每一种这样的物都是许多属性的总和，因此可以在不同的方面有用。发现这些不同的方面，从而发现物的多种使用方式，是历史的事情。[3]为有用物的量找到社会尺度，也是这样。商品尺度之所以不同，部分是由于被计量的物的性质不同，部分是由于约定俗成。","language":"中文","translation":false},{"id":"capital-2-21","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"物的有用性使物成为使用价值。[4]但这种有用性不是悬在空中的。它决定于商品体的属性，离开了商品体就不存在。因此，商品体本身，例如铁、小麦、金钢石等等，就是使用价值，或财物。商品体的这种性质，同人取得它的使用属性所耗费的劳动的多少没有关系。在考察使用价值时，总是以它们有一定的量为前提，如几打表，几码布，几吨铁等等。商品的使用价值为商品学这门学科提供材料。[5]使用价值只是在使用或消费中得到实现。不论财富的社会形式如何，使用价值总是构成财富的物质内容。在我们所要考察的社会形式中，使用价值同时又是交换价值的物质承担者。","language":"中文","translation":false},{"id":"capital-2-22","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"交换价值首先表现为一种使用价值同另一种使用价值相交换的量的关系或比例[6]，这个比例随着时间和地点的不同而不断改变。因此，交换价值好象是一种偶然的、纯粹相对的东西，也就是说，商品固有的、内在的交换价值似乎是一个形容语的矛盾。①[7]现在我们进一步考察这个问题。","language":"中文","translation":false},{"id":"capital-2-23","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"① 形容语的矛盾的原文是“contradictio in adjecto”，指“圆形的方”，“木制的铁”一类的矛盾。——译者注","language":"中文","translation":false},{"id":"capital-2-24","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"某种一定量的商品，例如一夸特小麦，同x量鞋油或y量绸缎或z量金等等交换，总之，按各种极不相同的比例同别的商品交换。因此，小麦有许多种交换价值，而不是只有一种。既然x量鞋油、y量绸缎、z量金等等都是一夸特小麦的交换价值，那末，x量鞋油、y量绸缎、z量金等等就必定是能够互相代替的或同样大的交换价值。由此可见，第一，同一种商品的各种有效的交换价值表示一个等同的东西。第二，交换价值只能是可以与它相区别的某种内容的表现方式，“表现形式”。","language":"中文","translation":false},{"id":"capital-2-25","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们再拿两种商品例如小麦和铁来说。不管二者的交换比例怎样，总是可以用一个等式来表示：一定量的小麦等于若干量的铁，如1夸特小麦=a吨铁。这个等式说明什么呢？它说明在两种不同的物里面，即在1夸特小麦和a吨铁里面，有一种等量的共同的东西。因而这二者都等于第三种东西，后者本身既不是第一种物，也不是第二种物。这样，二者中的每一个只要是交换价值，就必定能化为这第三种东西。","language":"中文","translation":false},{"id":"capital-2-26","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"用一个简单的几何学例子就可以说明这一点。为了确定和比较各种直线形的面积，就把它们分成三角形，再把三角形化成与它的外形完全不同的表现——底乘高的一半。各种商品的交换价值也同样要化成一种共同东西，各自代表这种共同东西的多量或少量。","language":"中文","translation":false},{"id":"capital-2-27","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"这种共同东西不可能是商品的几何的、物理的、化学的或其他的天然属性。商品的物体属性只是就它们使商品有用，从而使商品成为使用价值来说，才加以考虑。另一方面，商品交换关系的明显特点，正在于抽去商品的使用价值。在商品交换关系中，只要比例适当，一种使用价值就和其他任何一种使用价值完全相等。或者象老巴尔本说的：","language":"中文","translation":false},{"id":"capital-2-28","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"“只要交换价值相等，一种商品就同另一种商品一样。交换价值相等的物是没有任何差别或区别的。”[8]","language":"中文","translation":false},{"id":"capital-2-29","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"作为使用价值，商品首先有质的差别；作为交换价值，商品只能有量的差别，因而不包含任何一个使用价值的原子。","language":"中文","translation":false},{"id":"capital-2-30","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"如果把商品体的使用价值撇开，商品体就只剩下一个属性，即劳动产品这个属性。可是劳动产品在我们手里也已经起了变化。如果我们把劳动产品的使用价值抽去，那末也就是把那些使劳动产品成为使用价值的物质组成部分和形式抽去。它们不再是桌子、房屋、纱或别的什么有用物。它们的一切可以感觉到的属性都消失了。它们也不再是木匠劳动、瓦匠劳动、纺纱劳动，或其他某种一定的生产劳动的产品了。随着劳动产品的有用性质的消失，体现在劳动产品中的各种劳动的有用性质也消失了，因而这些劳动的各种具体形式也消失了。各种劳动不再有什么差别，全都化为相同的人类劳动，抽象人类劳动。","language":"中文","translation":false},{"id":"capital-2-31","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"现在我们来考察劳动产品剩下来的东西。它们剩下的只是同一的幽灵般的对象性，只是无差别的人类劳动的单纯凝结，即不管以哪种形式进行的人类劳动力耗费的单纯凝结。这些物现在只是表示，在它们的生产上耗费了人类劳动力，积累了人类劳动。这些物，作为它们共有的这个社会实体的结晶，就是价值——商品价值。","language":"中文","translation":false},{"id":"capital-2-32","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"① 对象性的原文是“Gegenständlichkeit”，意思是：客观现实性，客观存在的东西。——译者注","language":"中文","translation":false},{"id":"capital-2-33","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们已经看到，在商品的交换关系本身中，商品的交换价值表现为同它们的使用价值完全无关的东西。如果真正把劳动产品的使用价值抽去，就得到刚才已经规定的它们的价值。因此，在商品的交换关系或交换价值中表现出来的共同东西，也就是商品的价值。研究的进程会使我们再把交换价值当作价值的必然的表现方式或表现形式来考察，但现在，我们应该首先不管这种形式来考察价值。","language":"中文","translation":false},{"id":"capital-2-34","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，使用价值或财物具有价值，只是因为有抽象人类劳动体现或物化在里面。那末，它的价值量是怎样计量的呢？是用它所包含的“形成价值的实体”即劳动的量来计量。劳动本身的量是用劳动的持续时间来计量，而劳动时间又是用一定的时间单位如小时、日等作尺度。","language":"中文","translation":false},{"id":"capital-2-35","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可能会有人这样认为，既然商品的价值由生产商品所耗费的劳动量来决定，那末一个人越懒，越不熟练，他的商品就越有价值，因为他制造商品需要花费的时间越多。但是，形成价值实体的劳动是相同的人类劳动，是同一的人类劳动力的耗费。体现在商品世界全部价值中的社会的全部劳动力，在这里是当作一个同一的人类劳动力，虽然它是由无数单个劳动力构成的。每一个这种单个劳动力，同别一个劳动力一样，都是同一的人类劳动力，只要它具有社会平均劳动力的性质，起着这种社会平均劳动力的作用，从而在商品的生产上只使用平均必要劳动时间或社会必要劳动时间。社会必要劳动时间是在现有的社会正常的生产条件下，在社会平均的劳动熟练程度和劳动强度下制造某种使用价值所需要的劳动时间。例如，在英国采用蒸汽织布机以后，把一定量的纱织成布所需要的劳动可能比过去少一半。实际上，英国的手工织布工人把纱织成布仍旧要用以前那样多的劳动时间，但这时他一小时的个人劳动的产品只代表半小时的社会劳动，因此价值也降到了它以前的一半。","language":"中文","translation":false},{"id":"capital-2-36","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，只是社会必要劳动量，或生产使用价值的社会必要劳动时间，决定该使用价值的价值量[9]。在这里，单个商品是当作该种商品的平均样品。[10]因此，含有等量劳动或能在同样劳动时间内生产出来的商品，具有同样的价值量。一种商品的价值同其他任何一种商品的价值的比例，就是生产前者的必要劳动时间同生产后者的必要劳动时间的比例。“作为价值，一切商品都只是一定量的凝固的劳动时间。”[11]","language":"中文","translation":false},{"id":"capital-2-37","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"因此，如果生产商品所需要的劳动时间不变，商品的价值量也就不变。但是，生产商品所需要的劳动时间随着劳动生产力的每一变动而变动。劳动生产力是由多种情况决定的，其中包括：工人的平均熟练程度，科学的发展水平和它在工艺上应用的程度，生产过程的社会结合，生产资料的规模和效能，以及自然条件。例如，同一劳动量在丰收年表现为8蒲式耳小麦，在歉收年只表现为4蒲式耳。同一劳动量用在富矿比用在贫矿能提供更多的金属等等。金刚石在地壳中是很稀少的，因而发现金刚石平均要花很多劳动时间。因此，很小一块金刚石就代表很多劳动。杰科布曾经怀疑金是否按其全部价值支付过【29】。至于金刚石，就更可以这样说了。厄什韦葛说过，到1823年，巴西金刚石矿八十年的总产量的价格还赶不上巴西甘蔗种植园或咖啡种植园一年半平均产量的价格，虽然前者代表的劳动多得多，从而价值也多得多。如果发现富矿，同一劳动量就会表现为更多的金刚石，而金刚石的价值就会降低。假如能用不多的劳动把煤变成金刚石，金刚石的价值就会低于砖的价值。总之，劳动生产力越高，生产一种物品所需要的劳动时间就越少，凝结在该物品中的劳动量就越小，该物品的价值就越小。相反地，劳动生产力越低，生产一种物品的必要劳动时间就越多，该物品的价值就越大。可见，商品的价值量与体现在商品中的劳动的量成正比，与这一劳动的生产力成反比。①","language":"中文","translation":false},{"id":"capital-2-38","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"① 在第一版中接着有这样一段话：我们现在知道了价值的实体。这就是劳动, 我们知道了价值的量的尺度。这就是劳动时间。价值的形式（正是它使价值成为交换价值），有待分析。现在先要较详细地阐明那些已经发现的规定。——-编者注","language":"中文","translation":false},{"id":"capital-2-39","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一个物可以是使用价值而不是价值。在这个物并不是由于劳动而对人有用的情况下就是这样。例如，空气、处女地、天然草地、野生林等等。一个物可以有用，而且是人类劳动产品，但不是商品。谁用自己的产品来满足自己的需要，他生产的就只是使用价值，而不是商品。要生产商品，他不仅要生产使用价值，而且要为别人生产使用价值，即生产社会的使用价值。｛而且不只是单纯为别人。中世纪农民为封建主生产交代役租的粮食，为神父生产纳什一税的粮食。但不管是交代役租的粮食，还是纳什一税的粮食，都并不因为是为别人生产的，就成为商品。要成为商品，产品必须通过交换，转到把它当作使用价值使用的人的手里。｝①最后，没有一个物可以是价值而不是使用物品。如果物没有用，那末其中包含的劳动也就没有用，不能算作劳动，因此不形成价值。","language":"中文","translation":false},{"id":"capital-2-40","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"① 我插进了括号里的这段话，因为省去这段话常常会引起误解，好象不是由生产者本人消费的产品，马克思都认为是商品。——弗·恩·】","language":"中文","translation":false},{"id":"capital-2-41","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"2、体现在商品中的劳动的二重性","language":"中文","translation":false},{"id":"capital-2-42","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"起初我们看到，商品是一种二重的东西，即使用价值和交换价值。后来表明，劳动就它表现为价值而论，也不再具有它作为使用价值的创造者所具有的那些特征。商品中包含的劳动的这种二重性，是首先由我批判地证明了的。[12]这一点是理解政治经济学的枢纽，因此，在这里要较详细地加以说明。","language":"中文","translation":false},{"id":"capital-2-43","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们就拿两种商品如1件上衣和10码麻布来说。假定前者的价值比后者的价值大一倍。假设10码麻布=W，则1件上衣=2W。","language":"中文","translation":false},{"id":"capital-2-44","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"上衣是满足一种特殊需要的使用价值。要生产上衣，就需要进行特定种类的生产活动。这种生产活动是由它的目的、操作方式、对象、手段和结果决定的。由自己产品的使用价值或者由自己产品是使用价值来表示自己的有用性的劳动，我们简称为有用劳动。从这个观点来看，劳动总是联系到它的有用效果来考察的。","language":"中文","translation":false},{"id":"capital-2-45","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"上衣和麻布是不同质的使用价值，同样，决定它们存在的劳动即缝和织，也是不同质的。如果这些物不是不同质的使用价值，从而不是不同质的有用劳动的产品，它们就根本不能作为商品来互相对立。上衣不会与上衣交换，一种使用价值不会与同种的使用价值交换。","language":"中文","translation":false},{"id":"capital-2-46","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"各种使用价值或商品体的总和，表现了同样多种的、按照属、种、科、亚种、变种分类的有用劳动的总和，即表现了社会分工。这种分工是商品生产存在的条件，虽然不能反过来说商品生产是社会分工存在的条件。在古代印度公社中就有社会分工，但产品并不成为商品。或者拿一个较近的例子来说，每个工厂内都有系统的分工，但是这种分工不是通过工人交换他们个人的产品来实现的。只有独立的互不依赖的私人劳动的产品，才作为商品互相对立。","language":"中文","translation":false},{"id":"capital-2-47","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，每个商品的使用价值都包含着一定的有目的的生产活动，或有用劳动。各种使用价值如果不包含不同质的有用劳动，就不能作为商品互相对立。在产品普遍采取商品形式的社会里，也就是在商品生产者的社会里，作为独立生产者的私事而各自独立进行的各种有用劳动的这种质的区别，发展成一个多支的体系，发展成社会分工。","language":"中文","translation":false},{"id":"capital-2-48","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"对上衣来说，无论是裁缝自己穿还是他的顾客穿，都是一样的。在这两种场合，它都是起使用价值的作用。同样，上衣和生产上衣的劳动之间的关系，也并不因为裁缝劳动成为专门职业，成为社会分工的一个独立的部分就有所改变。在有穿衣需要的地方，在有人当裁缝以前，人已经缝了几千年的衣服。但是，上衣、麻布以及任何一种不是天然存在的物质财富要素，总是必须通过某种专门的、使特殊的自然物质适合于特殊的人类需要的、有目的的生产活动创造出来。因此，劳动作为使用价值的创造者，作为有用劳动，是不以一切社会形式为转移的人类生存条件，是人和自然之间的物质变换即人类生活得以实现的永恒的自然必然性。","language":"中文","translation":false},{"id":"capital-2-49","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"上衣、麻布等等使用价值，简言之，种种商品体，是自然物质和劳动这两种要素的结合。如果把上衣、麻布等等包含的各种不同的有用劳动的总和除外，总还剩有一种不借人力而天然存在的物质基质。人在生产中只能象自然本身那样发挥作用，就是说，只能改变物质的形态。[13]不仅如此，他在这种改变形态的劳动中还要经常依靠自然力的帮助。因此，劳动并不是它所生产的使用价值即物质财富的唯一源泉。正象威廉·配第所说，劳动是财富之父，土地是财富之母。【31】","language":"中文","translation":false},{"id":"capital-2-50","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"现在，我们放下作为使用物品的商品，来考察商品价值。","language":"中文","translation":false},{"id":"capital-2-51","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们曾假定，上衣的价值比麻布大一倍。但这只是量的差别，我们先不去管它。我们要记住的是，假如1件上衣的价值比10码麻布的价值大一倍，那末，20码麻布就与1件上衣具有同样的价值量。作为价值，上衣和麻布是有相同实体的物，是同种劳动的客观表现。但缝和织是不同质的劳动。然而在有些社会状态下，同一个人时而缝时而织，因此，这两种不同的劳动方式只是同一个人的劳动的变化，还不是不同的人的专门固定职能，正如我们的裁缝今天缝上衣和明天缝裤子只是同一个人的劳动的变化一样。其次，一看就知道，在我们资本主义社会里，随着劳动需求方向的改变，总有一定部分的人类劳动时而采取缝的形式，时而采取织的形式。劳动形式发生这种变换时不可能没有摩擦，但这种变换是必定要发生的。如果把生产活动的特定性质撇开，从而把劳动的有用性质撇开，生产活动就只剩下一点：它是人类劳动力的耗费。尽管缝和织是不同质的生产活动，但二者都是人的脑、肌肉、神经、手等等的生产耗费，从这个意义上说，二者都是人类劳动。这只是耗费人类劳动力的两种不同的形式。当然，人类劳动力本身必须已有一定的发展，才能以这种或那种形式耗费。但是，商品价值体现的是人类劳动本身，是一般人类劳动的耗费。正如在资产阶级社会里，将军或银行家扮演着重要的角色，而人本身则扮演极卑微的角色一样[14]，人类劳动在这里也是这样。它是每个没有任何专长的普通人的机体平均具有的简单劳动力的耗费。简单平均劳动虽然在不同的国家和不同的文化时代具有不同的性质，但在一定的社会里是一定的。比较复杂的劳动只是自乘的或不如说多倍的简单劳动，因此，少量的复杂劳动等于多量的简单劳动。经验证明，这种简化是经常进行的。一个商品可能是最复杂的劳动的产品，但是它的价值使它与简单劳动的产品相等，因而本身只表示一定量的简单劳动。[15]各种劳动化为当作它们的计量单位的简单劳动的不同比例，是在生产者背后由社会过程决定的，因而在他们看来，似乎是由习惯确定的。为了简便起见，我们以后把各种劳动力直接当作简单劳动力，这样就省去了简化的麻烦。","language":"中文","translation":false},{"id":"capital-2-52","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"因此，正如在作为价值的上衣和麻布中，它们的使用价值的差别被抽去一样，在表现为这些价值的劳动中，劳动的有用形式即缝和织的区别也被抽去了。作为使用价值的上衣和麻布是有一定目的的生产活动同布和纱的结合，而作为价值的上衣和麻布，不过是同种劳动的凝结，同样，这些价值所包含的劳动之所以算作劳动，并不是因为它们同布和纱发生了生产的关系，而只是因为它们是人类劳动力的耗费。正是由于缝和织具有不同的质，它们才是形成作为使用价值的上衣和麻布的要素；而只是由于它们的特殊的质被抽去，由于它们具有相同的质，即人类劳动的质，它们才是上衣价值和麻布价值的实体。","language":"中文","translation":false},{"id":"capital-2-53","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可是，上衣和麻布不仅是价值，而且是一定量的价值。我们曾假定，1件上衣的价值比10码麻布的价值大一倍。它们价值量的这种差别是从哪里来的呢？这是由于麻布包含的劳动只有上衣的一半，因而生产后者所要耗费劳动力的时间必须比生产前者多一倍。","language":"中文","translation":false},{"id":"capital-2-54","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"因此，就使用价值说，有意义的只是商品中包含的劳动的质，就价值量说，有意义的只是商品中包含的劳动的量，不过这种劳动已经化为没有质的区别的人类劳动。在前一种情况下，是怎样劳动，什么劳动的问题，在后一种情况下，是劳动多少，劳动时间多长的问题。既然商品的价值量只是表示商品中包含的劳动量，那末，在一定的比例上，各种商品应该总是等量的价值。","language":"中文","translation":false},{"id":"capital-2-55","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"如果生产一件上衣所需要的一切有用劳动的生产力不变，上衣的价值量就同上衣的数量一起增加。如果一件上衣代表x个工作日，两件上衣就代表2x个工作日，依此类推。假定生产一件上衣的必要劳动增加一倍或减少一半。在前一种场合，一件上衣就具有以前两件上衣的价值，在后一种场合，两件上衣就只有以前一件上衣的价值，虽然在这两种场合，上衣的效用和从前一样，上衣包含的有用劳动的质也和从前一样。但生产上衣所耗费的劳动量有了变化。","language":"中文","translation":false},{"id":"capital-2-56","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"更多的使用价值本身就是更多的物质财富，两件上衣比一件上衣多。两件上衣可以两个人穿，一件上衣只能一个人穿，依此类推。然而随着物质财富的量的增长，它的价值量可能同时下降。这种对立的运动来源于劳动的二重性。生产力当然始终是有用的具体的劳动的生产力，它事实上只决定有目的的生产活动在一定时间内的效率。因此，有用劳动成为较富或较贫的产品源泉与有用劳动的生产力的提高或降低成正比。相反地，生产力的变化本身丝毫也不会影响表现为价值的劳动。既然生产力属于劳动的具体有用形式，它自然不再同抽去了具体有用形式的劳动有关。因此，不管生产力发生了什么变化，同一劳动在同样的时间内提供的价值量总是相同的。但它在同样的时间内提供的使用价值量会是不同的：生产力提高时就多些，生产力降低时就少些。因此，那种能提高劳动成效从而增加劳动所提供的使用价值量的生产力变化，如果会缩减生产这个使用价值量所必需的劳动时间的总和，就会减少这个增大的总量的价值量。反之亦然。","language":"中文","translation":false},{"id":"capital-2-57","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一切劳动，从一方面看，是人类劳动力在生理学意义上的耗费；作为相同的或抽象的人类劳动，它形成商品价值。一切劳动，从另一方面看，是人类劳动力在特殊的有一定目的的形式上的耗费；作为具体的有用劳动，它生产使用价值。[16]","language":"中文","translation":false},{"id":"capital-2-58","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品是以铁、麻布、小麦等等使用价值或商品体的形式出现的。这是它们的日常的自然形式。但它们所以是商品，只因为它们是二重物，既是使用物品又是价值承担者。因此，它们表现为商品或具有商品的形式，只是由于它们具有二重的形式，即自然形式和价值形式。","language":"中文","translation":false},{"id":"capital-2-59","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品的价值对象性不同于快嘴桂嫂，你不知道对它怎么办【32】。同商品体的可感觉的粗糙的对象性正好相反，在商品体的价值对象性中连一个自然物质原子也没有。因此，每一个商品不管你怎样颠来倒去，它作为价值物总是不可捉摸的。但是如果我们记住，商品只有作为同一的社会单位即人类劳动的表现才具有价值对象性，因而它们的价值对象性纯粹是社会的，那末不用说，价值对象性只能在商品同商品的社会关系中表现出来。我们实际上也是从商品的交换价值或交换关系出发，才探索到隐藏在其中的商品价值。现在我们必须回到价值的这种表现形式。","language":"中文","translation":false},{"id":"capital-2-60","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"谁都知道——即使他别的什么都不知道，——商品具有同它们使用价值的五光十色的自然形式成鲜明对照的、共同的价值形式，即货币形式。但是在这里，我们要做资产阶级经济学从来没有打算做的事情：指明这种货币形式的起源，就是说，探讨商品价值关系中包含的价值表现，怎样从最简单的最不显眼的样子一直发展到炫目的货币形式。这样，货币的谜就会随着消失。","language":"中文","translation":false},{"id":"capital-2-61","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"显然，最简单的价值关系就是一个商品同另一个不同种的商品(不管是哪一种商品都一样)的价值关系。因此，两个商品的价值关系为一个商品提供了最简单的价值表现。","language":"中文","translation":false},{"id":"capital-2-62","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"A、简单的、个别的或偶然的价值形式","language":"中文","translation":false},{"id":"capital-2-63","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"x量商品A＝y量商品B，或x量商品A值y量商品B。","language":"中文","translation":false},{"id":"capital-2-64","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(20码麻布＝1件上衣，或20码麻布值1件上衣。)","language":"中文","translation":false},{"id":"capital-2-65","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(1)价值表现的两极：相对价值形式和等价形式","language":"中文","translation":false},{"id":"capital-2-66","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一切价值形式的秘密都隐藏在这个简单的价值形式中。因此，分析这个形式确实困难。","language":"中文","translation":false},{"id":"capital-2-67","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"两个不同种的商品A和B，如我们例子中的麻布和上衣，在这里显然起着两种不同的作用。麻布通过上衣表现自己的价值，上衣则成为这种价值表现的材料。前一个商品起主动作用，后一个商品起被动作用。前一个商品的价值表现为相对价值，或者说，处于相对价值形式。后一个商品起等价物的作用，或者说，处于等价形式。","language":"中文","translation":false},{"id":"capital-2-68","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"相对价值形式和等价形式是同一价值表现的互相依赖、互为条件、不可分离的两个要素，同时又是同一价值表现的互相排斥、互相对立的两端即两极；这两种形式总是分配在通过价值表现互相发生关系的不同的商品上。例如我不能用麻布来表现麻布的价值。20码麻布=20码麻布，这不是价值表现。相反，这个等式只是说，20码麻布无非是20码麻布，是一定量的使用物品麻布。因此，麻布的价值只能相对地表现出来，即通过另一个商品表现出来。因此，麻布的相对价值形式要求有另一个与麻布相对立的商品处于等价形式。另一方面，这另一个充当等价物的商品不能同时处于相对价值形式。它不表现自己的价值。它只是为别一个商品的价值表现提供材料。","language":"中文","translation":false},{"id":"capital-2-69","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"诚然，20码麻布=1件上衣，或20码麻布值1件上衣，这种表现也包含着相反的关系：1件上衣=20码麻布，或1件上衣值20码麻布。但是，要相对地表现上衣的价值，我就必须把等式倒过来，而一旦我这样做，成为等价物的就是麻布，而不是上衣了。可见，同一个商品在同一个价值表现中，不能同时具有两种形式。不仅如此，这两种形式是作为两极互相排斥的。","language":"中文","translation":false},{"id":"capital-2-70","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一个商品究竟是处于相对价值形式，还是处于与之对立的等价形式，完全取决于它当时在价值表现中所处的地位，就是说，取决于它是价值被表现的商品，还是表现价值的商品。","language":"中文","translation":false},{"id":"capital-2-71","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(a)相对价值形式的内容","language":"中文","translation":false},{"id":"capital-2-72","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"要发现一个商品的简单价值表现怎样隐藏在两个商品的价值关系中，首先必须完全撇开这个价值关系的量的方面来考察这个关系。人们通常的做法正好相反，他们在价值关系中只看到两种商品的一定量彼此相等的比例。他们忽略了，不同物的量只有化为同一单位后，才能在量上互相比较。不同物的量只有作为同一单位的表现，才是同名称的，因而是可通约的。[17]","language":"中文","translation":false},{"id":"capital-2-73","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"不论20码麻布=1件上衣，或=20件上衣，或=x件上衣，也就是说，不论一定量的麻布值多少件上衣，每一个这样的比例总是包含这样的意思：麻布和上衣作为价值量是同一单位的表现，是同一性质的物。麻布=上衣是这一等式的基础。","language":"中文","translation":false},{"id":"capital-2-74","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"但是，这两个被看作质上等同的商品所起的作用是不同的。只有麻布的价值得到表现。是怎样表现的呢？是通过同上衣的关系，把上衣当作它的“等价物”，或与它“能交换的东西”。在这个关系中，上衣是价值的存在形式，是价值物，因为只有作为价值物，它才是与麻布相同的。另一方面，麻布自身的价值显示出来了，或得到了独立的表现，因为麻布只有作为价值才能把上衣当作等值的东西，或与它能交换的东西。比如，丁酸是同甲酸丙酯不同的物体。但二者是由同一些化学实体——碳(C)、氢(H)、氧(O)构成，而且是以相同的百分比构成，即C4H8O2。假如甲酸丙酯被看作与丁酸相等，那末，在这个关系中，第一，甲酸丙酯只是C4H8O2的存在形式，第二，就是说，丁酸也是由C4H8O2构成的。可见，通过使甲酸丙酯同丁酸相等，丁酸与自身的物体形态不同的化学实体被表现出来了。","language":"中文","translation":false},{"id":"capital-2-75","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"如果我们说，商品作为价值只是人类劳动的凝结，那末，我们的分析就是把商品化为价值抽象，但是并没有使它们具有与它们的自然形式不同的价值形式。在一个商品和另一个商品的价值关系中，情形就不是这样。在这里，一个商品的价值性质通过该商品与另一个商品的关系而显露出来。","language":"中文","translation":false},{"id":"capital-2-76","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"例如当上衣作为价值物被看作与麻布相等时，前者包含的劳动就被看作与后者包含的劳动相等。固然，缝上衣的劳动是一种与织麻布的劳动不同的具体劳动。但是，把缝看作与织相等，实际上就是把缝化为两种劳动中确实等同的东西，化为它们的人类劳动的共同性质。通过这种间接的办法还说明，织就它织出价值而论，也和缝毫无区别，所以是抽象人类劳动。只有不同种商品的等价表现才使形成价值的劳动的这种特殊性质显示出来，因为这种等价表现实际上是把不同种商品所包含的不同种劳动化为它们的共同东西，化为一般人类劳动。①","language":"中文","translation":false},{"id":"capital-2-77","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"① 第2版注：最早的经济学家之一、著名的富兰克林，继威廉·配第之后看出了价值的本质，他说：“既然贸易无非是一种劳动同另一种劳动的交换，所以一切物的价值用劳动来估计是最正确的”(斯巴克斯编《富兰克林全集》1836年波士顿版第2卷第267页)。富兰克林没有意识到，既然他“用劳动”来估计一切物的价值，也就抽掉了各种互相交换的劳动的差别，这样就把这些劳动化为相同的人类劳动。他虽然没有意识到这一点，却把它说了出来。他先说“一种劳动”，然后说“另一种劳动”，最后说的是没有任何限定的“劳动”，也就是作为一切物的价值实体的劳动。","language":"中文","translation":false},{"id":"capital-2-78","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"然而，只把构成麻布价值的劳动的特殊性质表现出来，是不够的。处于流动状态的人类劳动力或人类劳动形成价值，但本身不是价值。它在凝固的状态中，在物化的形式上才成为价值。要使麻布的价值表现为人类劳动的凝结，就必须使它表现为一种“对象性”，这种对象性与麻布本身的物体不同，同时又是麻布与其他商品所共有的。这个问题已经解决了。","language":"中文","translation":false},{"id":"capital-2-79","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在麻布的价值关系中，上衣是当作与麻布同质的东西，是当作同一性质的物，因为它是价值。在这里，它是当作表现价值的物，或者说，是以自己的可以捉摸的自然形式表示价值的物。当然，上衣，作为商品体的上衣，只是使用价值。一件上衣同任何一块麻布一样，不表现价值。这只是证明，上衣在同麻布的价值关系中，比在这种关系之外，多一层意义，正象许多人穿上镶金边的上衣，比不穿这种上衣，多一层意义一样。","language":"中文","translation":false},{"id":"capital-2-80","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在上衣的生产上，人类劳动力的确是以缝的形式被耗费的。因此，上衣中积累了人类劳动。从这方面看，上衣是“价值承担者”，虽然它的这种属性即使把它穿破了也是看不出来的。在麻布的价值关系中，上衣只是显示出这一方面，也就是当作物体化的价值，当作价值体。即使上衣扣上了纽扣，麻布在它身上还是认出与自己同宗族的美丽的价值灵魂。但是，如果对麻布来说，价值不同时采取上衣的形式，上衣在麻布面前就不能表示价值。例如，如果在A看来，陛下不具有B的仪表，因而不随着国王的每次更换而改变容貌、头发等等，A就不会把B当作陛下。","language":"中文","translation":false},{"id":"capital-2-81","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，在上衣成为麻布的等价物的价值关系中，上衣形式起着价值形式的作用。因此，商品麻布的价值是表现在商品上衣的物体上，一个商品的价值表现在另一个商品的使用价值上。作为使用价值，麻布是在感觉上与上衣不同的物；作为价值，它却是“与上衣等同的东西”，因而看起来就象上衣。麻布就这样取得了与它的自然形式不同的价值形式。它的价值性质通过它和上衣相等表现出来，正象基督徒的羊性通过他和上帝的羔羊相等表现出来一样。","language":"中文","translation":false},{"id":"capital-2-82","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们看到，一当麻布与别的商品即上衣交往时，商品价值的分析向我们说明的一切，现在就由麻布自己说出来了。不过它只能用它自己通晓的语言即商品语言来表达它的思想。为了说明劳动在人类劳动的抽象属性上形成它自己的价值，它就说，上衣只要与它相等，从而是价值，就和麻布一样是由同一劳动构成的。为了说明它的高尚的价值对象性不同于它的浆硬的物体，它就说，价值看起来象上衣，因此它自己作为价值物，就同上衣相象，正如两个鸡蛋相象一样。顺便指出，除希伯来语以外，商品语言中也还有其他许多确切程度不同的方言。例如，要表达商品B同商品A相等是商品A自己的价值表现，德文《Wertsein》〔价值，价值存在〕就不如罗曼语的动词valere，valer，valoir〔值〕表达得确切。巴黎确实值一次弥撒！【33】","language":"中文","translation":false},{"id":"capital-2-83","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，通过价值关系，商品B的自然形式成了商品A的价值形式，或者说，商品B的物体成了反映商品A的价值的镜子。[18]商品A同作为价值体，作为人类劳动的化身的商品B发生关系，就使B的使用价值成为表现A自己价值的材料。在商品B的使用价值上这样表现出来的商品A的价值，具有相对价值形式。","language":"中文","translation":false},{"id":"capital-2-84","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(b)相对价值形式的量的规定性","language":"中文","translation":false},{"id":"capital-2-85","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"凡是价值要被表现的商品，都是一定量的使用物品，如15舍费耳小麦、100磅咖啡等等。这一定量的商品包含着一定量的人类劳动。因而，价值形式不只是要表现价值，而且要表现一定量的价值，即价值量。因此，在商品A和商品B如麻布和上衣的价值关系中，上衣这种商品不仅作为一般价值体被看作在质上同麻布相等，而且是作为一定量的价值体或等价物如1件上衣被看作同一定量的麻布如20码麻布相等。","language":"中文","translation":false},{"id":"capital-2-86","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"“20码麻布=1件上衣，或20码麻布值1件上衣”这一等式的前提是：1件上衣和20码麻布正好包含有同样多的价值实体。就是说，这两个商品量耗费了同样多的劳动或等量的劳动时间。但是生产20码麻布或1件上衣的必要劳动时间，是随着织或缝的生产力的变化而变化的。现在我们要较详细地研究一下这种变化对价值量的相对表现的影响。","language":"中文","translation":false},{"id":"capital-2-87","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"I、麻布的价值起了变化[19]，上衣的价值不变。如果生产麻布的必要劳动时间由于种植亚麻的土地肥力下降而增加一倍，那末麻布的价值也就增大一倍。这时不是20码麻布=1件上衣，而是20码麻布=2件上衣，因为现在1件上衣包含的劳动时间只有20码麻布的一半。相反地，如果生产麻布的必要劳动时间由于织机改良而减少一半，那末，麻布的价值也就减低一半。这样，现在是20码麻布=1/2件上衣。可见，在商品B的价值不变时，商品A的相对价值即它表现在商品B上的价值的增减，与商品A的价值成正比。","language":"中文","translation":false},{"id":"capital-2-88","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"II、麻布的价值不变，上衣的价值起了变化。在这种情况下，如果生产上衣的必要劳动时间由于羊毛歉收而增加一倍，现在不是20码麻布=1件上衣，而是20码麻布=1/2件上衣。相反地，如果上衣的价值减少一半，那末，20码麻布=2件上衣。因此，在商品A的价值不变时，它的相对的、表现在商品B上的价值的增减，与商品B的价值变化成反比。","language":"中文","translation":false},{"id":"capital-2-89","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们把I、II类的各种情形对照一下就会发现，相对价值的同样的量的变化可以由完全相反的原因造成。所以，20码麻布=1件上衣变为：1、20码麻布=2件上衣，或者是由于麻布的价值增加一倍，或者是由于上衣的价值减低一半；2、20码麻布=1/2件上衣，或者是由于麻布的价值减低一半，或者是由于上衣的价值增加一倍。","language":"中文","translation":false},{"id":"capital-2-90","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"III、生产麻布和上衣的必要劳动量可以按照同一方向和同一比例同时发生变化。在这种情况下，不管这两种商品的价值发生什么变动，依旧是20码麻布=1件上衣。只有把它们同价值不变的第三种商品比较，才会发现它们的价值的变化。如果所有商品的价值都按同一比例同时增减，它们的相对价值就保持不变。它们的实际的价值变化可以由以下这个事实看出：在同样的劳动时间内，现在提供的商品量都比过去多些或少些。","language":"中文","translation":false},{"id":"capital-2-91","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"IV、生产麻布和上衣的各自的必要劳动时间，从而它们的价值，可以按照同一方向但以不同的程度同时发生变化，或者按照相反的方向发生变化，等等。这种种可能的组合对一种商品的相对价值的影响，根据I、II、III类的情况就可以推知。","language":"中文","translation":false},{"id":"capital-2-92","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，价值量的实际变化不能明确地，也不能完全地反映在价值量的相对表现即相对价值量上。即使商品的价值不变，它的相对价值也可能发生变化。即使商品的价值发生变化，它的相对价值也可能不变，最后，商品的价值量和这个价值量的相对表现同时发生的变化，完全不需要一致。[20]","language":"中文","translation":false},{"id":"capital-2-93","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们说过，当商品A(麻布)通过不同种商品B(上衣)的使用价值表现自己的价值时，它就使商品B取得一种特殊的价值形式，即等价形式。商品麻布显示出它自身的价值，是通过上衣没有取得与自己的物体形式不同的价值形式而与它相等。这样，麻布表现出它自身具有价值，实际上是通过上衣能与它直接交换。因此，一个商品的等价形式就是它能与另一个商品直接交换的形式。","language":"中文","translation":false},{"id":"capital-2-94","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"如果一种商品例如上衣成了另一种商品例如麻布的等价物，上衣因而获得了一种特殊的属性，即处于能够与麻布直接交换的形式，那末，这根本没有表明上衣与麻布交换的比例。既然麻布的价值量已定，这个比例就取决于上衣的价值量。不管是上衣表现为等价物，麻布表现为相对价值，还是相反，麻布表现为等价物，上衣表现为相对价值，上衣的价值量总是取决于生产它的必要劳动时间，因而和它的价值形式无关。但是一当上衣这种商品在价值表现中取得等价物的地位，它的价值量就不是作为价值量来表现了。在价值等式中，上衣的价值量不如说只是当作某物的一定的量。","language":"中文","translation":false},{"id":"capital-2-95","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"例如，40码麻布“值”什么呢？2件上衣。因为上衣这种商品在这里起着等价物的作用，作为使用价值的上衣与麻布相对立时是充当价值体，所以，一定量的上衣也就足以表现麻布的一定的价值量。因此，两件上衣能够表现40码麻布的价值量，但是两件上衣决不能表现它们自己的价值量，即上衣的价值量。在价值等式中，等价物始终只具有某物即某种使用价值的单纯的量的形式，对这一事实的肤浅了解，使贝利同他的许多先驱者和后继者都误认为价值表现只是一种量的关系。其实，商品的等价形式不包含价值的量的规定。","language":"中文","translation":false},{"id":"capital-2-96","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在考察等价形式时看见的第一个特点，就是使用价值成为它的对立面即价值的表现形式。","language":"中文","translation":false},{"id":"capital-2-97","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品的自然形式成为价值形式。但是请注意，对商品B(上衣、小麦或铁等等)来说，这种转换只有在任何别的商品A(麻布等等)与它发生价值关系时，只有在这种关系中才能实现。因为任何商品都不能把自己当作等价物来同自己发生关系，因而也不能用它自己的自然外形来表现它自己的价值，所以它必须把另一商品当作等价物来同它发生关系，或者使另一商品的自然外形成为它自己的价值形式。","language":"中文","translation":false},{"id":"capital-2-98","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"为了说明这一点，可以用衡量商品体本身即使用价值的尺度作例子。塔糖是物体，所以是重的，因而有重量，但是我们看不见也摸不着塔糖的重量。现在我们拿一些不同的铁块来，这些铁块的重量是预先确定了的。铁的物体形式，就其自身来说，同塔糖的物体形式一样，不是重的表现形式。要表现塔糖是重的，我们就要使它和铁发生重量关系。在这种关系中，铁充当一种只表示重而不表示别的东西的物体。因此，铁的量充当糖的重量尺度，对糖这个物体来说，它只是重的体现，重的表现形式。铁只是在糖或其他任何要测定重量的物体同它发生重量关系的时候，才起这种作用。如果两种物都没有重，它们就不能发生这种关系，因此一种物就不能成为另一种物的重的表现。如果把二者放在天平上，我们就会在实际上看到，当作有重的物，它们是相同的，因而在一定的比例上也具有同样的重量。铁这个物体作为重量尺度，对于塔糖来说，只代表重，同样，在我们的价值表现中，上衣这个物体对于麻布来说，也只代表价值。","language":"中文","translation":false},{"id":"capital-2-99","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"但是，类比只能到此为止。在塔糖的重量表现中，铁代表两个物体共有的自然属性，即它们的重，而在麻布的价值表现中，上衣代表这两种物的超自然属性，即它们的价值，某种纯粹社会的东西。","language":"中文","translation":false},{"id":"capital-2-100","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一种商品例如麻布的相对价值形式，把自己的价值表现为一种与自己的物体和物体属性完全不同的东西，例如表现为与上衣相同的东西，因此，这个表现本身就说明其中隐藏着某种社会关系。等价形式却相反。等价形式恰恰在于：商品体例如上衣这个物本身就表现价值，因而天然就具有价值形式。当然，只是在商品麻布把商品上衣当作等价物的价值关系中，才是这样。[21]但是，既然一物的属性不是由该物同他物的关系产生，而只是在这种关系中表现出来，因此上衣似乎天然具有等价形式，天然具有能与其他商品直接交换的属性，就象它天然具有重的属性或保暖的属性一样。从这里就产生了等价形式的谜的性质，这种性质只是在等价形式以货币这种完成的形态出现在政治经济学家的面前的时候，才为他的资产阶级的短浅的眼光所注意。这时他用不太耀眼的商品代替金银，并以一再满足的心情反复列举各种曾经充当过商品等价物的普通商品，企图以此来说明金银的神秘性质。他没有料到，最简单的价值表现，如20码麻布=1件上衣，就已经提出了等价形式的谜让人们去解决。","language":"中文","translation":false},{"id":"capital-2-101","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"充当等价物的商品的物体总是当作抽象人类劳动的化身，同时又总是某种有用的、具体的劳动的产品。因此，这种具体劳动就成为抽象人类劳动的表现。例如，如果上衣只当作抽象人类劳动的实现，那末，在上衣内实际地实现的缝劳动就只当作抽象人类劳动的实现形式。在麻布的价值表现中，缝劳动的有用性不在于造了衣服，从而造了人，①而在于造了一种物体，使人们能看出它是价值，因而是与物化在麻布价值内的劳动毫无区别的那种劳动的凝结。要造这样一面反映价值的镜子，缝劳动本身就必须只是反映它作为人类劳动的这种抽象属性。","language":"中文","translation":false},{"id":"capital-2-102","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"① 原文套用了德国谚语《Kleider machen Leute》，直译是：“衣服造人”，转义是：人靠衣装。——译者注","language":"中文","translation":false},{"id":"capital-2-103","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"缝的形式同织的形式一样，都是人类劳动力的耗费。因此，二者都具有人类劳动的一般属性，因而在一定的情况下，比如在价值的生产上，就可以只从这个角度来考察。这并不神秘。但是在商品的价值表现上事情却反过来了。例如，为了表明织不是在它作为织这个具体形式上，而是在它作为人类劳动这个一般属性上形成麻布的价值，我们就要把缝这种制造麻布的等价物的具体劳动，作为抽象人类劳动的可以捉摸的实现形式与织相对立。","language":"中文","translation":false},{"id":"capital-2-104","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，等价形式的第二个特点，就是具体劳动成为它的对立面即抽象人类劳动的表现形式。","language":"中文","translation":false},{"id":"capital-2-105","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"既然这种具体劳动，即缝，只是当作无差别的人类劳动的表现，它也就具有与别种劳动即麻布中包含的劳动等同的形式，因而，尽管它同其他一切生产商品的劳动一样是私人劳动，但终究是直接社会形式上的劳动。正因为这样，它才表现在一种能与别种商品直接交换的产品上。可见，等价形式的第三个特点，就是私人劳动成为它的对立面的形式，成为直接社会形式的劳动。","language":"中文","translation":false},{"id":"capital-2-106","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"如果我们回顾一下一位伟大的研究家，等价形式的后两个特点就会更容易了解。这位研究家最早分析了许多思维形式、社会形式和自然形式，也最早分析了价值形式。他就是亚里士多德。","language":"中文","translation":false},{"id":"capital-2-107","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"首先，亚里士多德清楚地指出，商品的货币形式不过是简单价值形式——一种商品的价值通过任何别一种商品来表现——的进一步发展的形态，因为他说：","language":"中文","translation":false},{"id":"capital-2-108","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"其次，他看到：包含着这个价值表现的价值关系本身，要求屋必须在质上与床等同，这两种感觉上不同的物，如果没有这种本质上的等同性，就不能作为可通约的量而互相发生关系。他说：“没有等同性，就不能交换，没有可通约性，就不能等同。”但是他到此就停下来了，没有对价值形式作进一步分析。“实际上，这样不同种的物是不能通约的”，就是说，它们不可能在质上等同。这种等同只能是某种和物的真实性质相异的东西，因而只能是“应付实际需要的手段”。【34】","language":"中文","translation":false},{"id":"capital-2-109","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，亚里士多德自己告诉了我们，是什么东西阻碍他作进一步的分析，这就是缺乏价值概念。这种等同的东西，也就是屋在床的价值表现中对床来说所代表的共同的实体是什么呢？亚里士多德说，这种东西“实际上是不可能存在的”。为什么呢？只要屋代表床和屋二者中真正等同的东西，对床来说屋就代表一种等同的东西。这就是人类劳动。","language":"中文","translation":false},{"id":"capital-2-110","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"但是，亚里士多德不能从价值形式本身看出，在商品价值形式中，一切劳动都表现为等同的人类劳动，因而是同等意义的劳动，这是因为希腊社会是建立在奴隶劳动的基础上的，因而是以人们之间以及他们的劳动力之间的不平等为自然基础的。价值表现的秘密，即一切劳动由于而且只是由于都是一般人类劳动而具有的等同性和同等意义，只有在人类平等概念已经成为国民的牢固的成见的时候，才能揭示出来。而这只有在这样的社会里才有可能，在那里，商品形式成为劳动产品的一般形式，从而人们彼此作为商品所有者的关系成为占统治地位的社会关系。亚里士多德在商品的价值表现中发现了等同关系，正是在这里闪耀出他的天才的光辉。只是他所处的社会的历史限制，使他不能发现这种等同关系“实际上”是什么。","language":"中文","translation":false},{"id":"capital-2-111","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(4)简单价值形式的总体","language":"中文","translation":false},{"id":"capital-2-112","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一个商品的简单价值形式包含在它与一个不同种商品的价值关系或交换关系中。商品A的价值，通过商品B能与商品A直接交换而在质上得到表现，通过一定量的商品B能与既定量的商品A交换而在量上得到表现。换句话说，一个商品的价值是通过它表现为“交换价值”而得到独立的表现。在本章的开头，我们曾经依照通常的说法，说商品是使用价值和交换价值，严格说来，这是不对的。商品是使用价值或使用物品和“价值”。一个商品，只要它的价值取得一个特别的、不同于它的自然形式的表现形式，即交换价值形式，它就表现为这样的二重物。孤立地考察，它绝没有这种形式，而只有同第二个不同种的商品发生价值关系或交换关系时，它才具有这种形式。只要我们知道了这一点，上述说法就没有害处，而只有简便的好处。","language":"中文","translation":false},{"id":"capital-2-113","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"我们的分析表明，商品的价值形式或价值表现由商品价值的本性产生，而不是相反，价值和价值量由它们的作为交换价值的表现方式产生。但是，这正是重商主义者和他们的现代复兴者费里埃、加尼耳之流[22]的错觉，也是他们的反对者现代自由贸易贩子巴师夏之流的错觉。重商主义者看重价值表现的质的方面，也就是看重在货币上取得完成形态的商品等价形式，相反地，必须以任何价格出售自己的商品的现代自由贸易贩子，则看重相对价值形式的量的方面。因此，在他们看来，商品的价值和价值量只存在于由交换关系引起的表现中，也就是只存在于每日行情表中。苏格兰人麦克劳德，由于他的职责是用尽可能博学的外衣来粉饰伦巴特街【35】的杂乱的观念，而成了迷信的重商主义者和开明的自由贸易贩子之间的一个成功的综合。","language":"中文","translation":false},{"id":"capital-2-114","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"更仔细地考察一下商品A同商品B的价值关系中所包含的商品A的价值表现，就会知道，在这一关系中商品A的自然形式只是充当使用价值的形态，而商品B的自然形式只是充当价值形式或价值形态。这样，潜藏在商品中的使用价值和价值的内部对立，就通过外部对立，即通过两个商品的关系表现出来了，在这个关系中，价值要被表现的商品只是直接当作使用价值，而另一个表现价值的商品只是直接当作交换价值。所以，一个商品的简单的价值形式，就是该商品中所包含的使用价值和价值的对立的简单表现形式。","language":"中文","translation":false},{"id":"capital-2-115","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在一切社会状态下，劳动产品都是使用物品，但只是历史上一定的发展时代，也就是使生产一个使用物所耗费的劳动表现为该物的“对象的”属性即它的价值的时代，才使劳动产品转化为商品。由此可见，商品的简单价值形式同时又是劳动产品的简单商品形式，因此，商品形式的发展是同价值形式的发展一致的。","language":"中文","translation":false},{"id":"capital-2-116","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一看就知道，简单价值形式是不充分的，是一种胚胎形式，它只有通过一系列的形态变化，才成熟为价格形式。","language":"中文","translation":false},{"id":"capital-2-117","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品A的价值表现在某种商品B上，只是使商品A的价值同它自己的使用价值区别开来，因此也只是使商品A同某一种与它自身不同的商品发生交换关系，而不是表现商品A同其他一切商品的质的等同和量的比例。与一个商品的简单相对价值形式相适应的，是另一个商品的个别等价形式。所以，在麻布的相对价值表现中，上衣只是对麻布这一种商品来说，具有等价形式或能直接交换的形式。","language":"中文","translation":false},{"id":"capital-2-118","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"然而个别的价值形式会自行过渡到更完全的形式。通过个别的价值形式，商品A的价值固然只是表现在一个别种商品上，但是这后一个商品不论是哪一种，是上衣、铁或小麦等等，都完全一样。随着同一商品和这种或那种不同的商品发生价值关系，也就产生它的种种不同的简单价值表现①。它可能有的价值表现的数目，只受与它不同的商品种类的数目的限制。这样，商品的个别的价值表现就转化为一个可以不断延长的、不同的简单价值表现的系列。","language":"中文","translation":false},{"id":"capital-2-119","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"① 第2版注：例如在荷马的著作中，一物的价值是通过一系列各种不同的物来表现的。","language":"中文","translation":false},{"id":"capital-2-120","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"B、总和的或扩大的价值形式","language":"中文","translation":false},{"id":"capital-2-121","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"z量商品A=u量商品B，或=v量商品C，或=w量商品D，或=x量商品E，或=其他","language":"中文","translation":false},{"id":"capital-2-122","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(20码麻布=1件上衣，或=10磅茶叶，或=40磅咖啡，或=1夸特小麦，或=2盎斯金，或=1/2吨铁，或=其他)","language":"中文","translation":false},{"id":"capital-2-123","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(1)扩大的相对价值形式","language":"中文","translation":false},{"id":"capital-2-124","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"现在，一种商品例如麻布的价值表现在商品世界的其他无数的元素上。每一种其他的商品体都成为反映麻布价值的镜子。[23]这样，这个价值本身才真正表现为无差别的人类劳动的凝结。因为形成这个价值的劳动现在十分清楚地表现为这样一种劳动，其他任何一种人类劳动都与之等同，而不管其他任何一种劳动具有怎样的自然形式，即不管它是物化在上衣、小麦、铁或金等等之中。因此，现在麻布通过自己的价值形式，不再是只同另一种商品发生社会关系，而是同整个商品世界发生社会关系。作为商品，它是这个世界的一个公民。同时，商品价值表现的无限的系列表明，商品价值是同它借以表现的使用价值的特殊形式没有关系的。","language":"中文","translation":false},{"id":"capital-2-125","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在第一种形式即20码麻布=1件上衣中，这两种商品能以一定的量的比例相交换，可能是偶然的事情。相反地，在第二种形式中，一个根本不同于偶然现象并且决定着这种偶然现象的背景马上就显露出来了。麻布的价值无论是表现在上衣、咖啡或铁等等无数千差万别的、属于各个不同所有者的商品上，总是一样大的。两个单个商品所有者之间的偶然关系消失了。显然，不是交换调节商品的价值量，恰好相反，是商品的价值量调节商品的交换比例。","language":"中文","translation":false},{"id":"capital-2-126","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"每一种商品，上衣、茶叶、小麦、铁等等，都在麻布的价值表现中充当等价物，因而充当价值体。每一种这样的商品的一定的自然形式，现在都成为一个特殊的等价形式，与其他许多特殊等价形式并列。同样，种种不同的商品体中所包含的多种多样的一定的、具体的、有用的劳动，现在只是一般人类劳动的同样多种的特殊的实现形式或表现形式。","language":"中文","translation":false},{"id":"capital-2-127","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(3)总和的或扩大的价值形式的缺点","language":"中文","translation":false},{"id":"capital-2-128","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"第一，商品的相对价值表现是未完成的，因为它的表现系列永无止境。每当新出现一种商品，从而提供一种新的价值表现的材料时，由一个个的价值等式连结成的锁链就会延长。第二，这条锁链形成一幅由互不关联的而且种类不同的价值表现拼成的五光十色的镶嵌画。最后，象必然会发生的情形一样，如果每一种商品的相对价值都表现在这个扩大的形式中，那末，每一种商品的相对价值形式都是一个不同于任何别的商品的相对价值形式的无穷无尽的价值表现系列。——扩大的相对价值形式的缺点反映在与它相适应的等价形式中。既然每一种商品的自然形式在这里都是一个特殊的等价形式，与无数别的特殊等价形式并列，所以只存在着有局限性的等价形式，其中每一个都排斥另一个。同样，每个特殊的商品等价物中包含的一定的、具体的、有用的劳动，都只是人类劳动的特殊的因而是不充分的表现形式。诚然，人类劳动在这些特殊表现形式的总和中，获得自己的完全的或者总和的表现形式。但是它还没有获得统一的表现形式。","language":"中文","translation":false},{"id":"capital-2-129","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"扩大的相对价值形式只是由简单的相对价值表现的总和，或第一种形式的等式的总和构成，例如：","language":"中文","translation":false},{"id":"capital-2-130","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"20码麻布=10磅茶叶，等等。","language":"中文","translation":false},{"id":"capital-2-131","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"但是每一个这样的等式倒转过来也包含着一个同一的等式：","language":"中文","translation":false},{"id":"capital-2-132","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"10磅茶叶=20码麻布，等等。","language":"中文","translation":false},{"id":"capital-2-133","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"事实上，如果一个人用他的麻布同其他许多商品交换，从而把麻布的价值表现在一系列其他的商品上，那末，其他许多商品所有者也就必然要用他们的商品同麻布交换，从而把他们的各种不同的商品的价值表现在同一个第三种商品麻布上。——因此，把20码麻布=1件上衣，或=10磅茶叶，或=其他等等这个系列倒转过来，也就是说，把事实上已经包含在这个系列中的相反关系表示出来，我们就得到：","language":"中文","translation":false},{"id":"capital-2-134","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(1)价值形式的变化了的性质","language":"中文","translation":false},{"id":"capital-2-135","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"现在，商品价值的表现：1、是简单的，因为都是表现在唯一的商品上；2、是统一的，因为都是表现在同一的商品上。它们的价值形式是简单的和共同的，因而是一般的。","language":"中文","translation":false},{"id":"capital-2-136","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"第一种形式和第二种形式二者都只是使一种商品的价值表现为一种与它自身的使用价值或商品体不同的东西。","language":"中文","translation":false},{"id":"capital-2-137","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"第一种形式提供的价值等式是：1件上衣=20码麻布，10磅茶叶=1/2吨铁，等等。上衣的价值表现为与麻布等同，茶叶的价值表现为与铁等同，等等，但是与麻布等同和与铁等同——上衣和茶叶各自的这种价值表现是不相同的，正如麻布和铁不相同一样。很明显，这种形式实际上只是在最初交换阶段，也就是在劳动产品通过偶然的、间或的交换而转化为商品的阶段才出现。","language":"中文","translation":false},{"id":"capital-2-138","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"第二种形式比第一种形式更完全地把一种商品的价值同它自身的使用价值区别开来，因为例如上衣的价值现在是在一切可能的形式上与它的自然形式相对立，上衣的价值现在与麻布等同，与铁等同，与茶叶等同，与其他一切东西等同，只是不与上衣等同。另一方面，在这里商品的任何共同的价值表现都直接被排除了，因为在每一种商品的价值表现中，其他一切商品现在都只是以等价物的形式出现。扩大的价值形式，事实上是在某种劳动产品例如牲畜不再是偶然地而已经是经常地同其他不同的商品交换的时候，才出现的。","language":"中文","translation":false},{"id":"capital-2-139","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"新获得的形式使商品世界的价值表现在从商品世界中分离出来的同一种商品上，例如表现在麻布上，因而使一切商品的价值都通过它们与麻布等同而表现出来。每个商品的价值作为与麻布等同的东西，现在不仅与它自身的使用价值相区别，而且与一切使用价值相区别，正因为这样才表现为它和一切商品共有的东西。因此，只有这种形式才真正使商品作为价值互相发生关系，或者使它们互相表现为交换价值。","language":"中文","translation":false},{"id":"capital-2-140","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"前两种形式表现一种商品的价值，或者是通过一个不同种的商品，或者是通过许多种与它不同的商品构成的系列。在这两种情况下，使自己取得一个价值形式可以说是个别商品的私事，它完成这件事情是不用其他商品帮助的。对它来说，其他商品只是起着被动的等价物的作用。相反地，一般价值形式的出现只是商品世界共同活动的结果。一种商品所以获得一般的价值表现，只是因为其他一切商品同时也用同一个等价物来表现自己的价值，而每一种新出现的商品都要这样做。这就表明，由于商品的价值对象性只是这些物的“社会存在”，所以这种对象性也就只能通过它们全面的社会关系来表现，因而它们的价值形式必须是社会公认的形式。","language":"中文","translation":false},{"id":"capital-2-141","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"现在，一切商品，在与麻布等同的形式上，不仅表现为在质上等同，表现为价值，而且同时也表现为在量上可以比较的价值量。由于它们都通过同一个材料，通过麻布来反映自己的价值量，这些价值量也就互相反映。例如，10磅茶叶=20码麻布，40磅咖啡=20码麻布。因此，10磅茶叶=40磅咖啡。或者说，一磅咖啡所包含的价值实体即劳动，只等于一磅茶叶所包含的1/4。","language":"中文","translation":false},{"id":"capital-2-142","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品世界的一般的相对价值形式，使被排挤出商品世界的等价物商品即麻布，获得了一般等价物的性质。麻布自身的自然形式是这个世界的共同的价值形态，因此，麻布能够与其他一切商品直接交换。它的物体形式是当作一切人类劳动的可以看得见的化身，一般的社会的蛹化。同时，织，这种生产麻布的私人劳动，也就处于一般社会形式，处于与其他一切劳动等同的形式。构成一般价值形式的无数等式，使实现在麻布中的劳动，依次等于包含在其他商品中的每一种劳动，从而使织成为一般人类劳动的一般表现形式。这样，物化在商品价值中的劳动，不仅消极地表现为被抽去了实在劳动的一切具体形式和有用属性的劳动。它本身的积极的性质也清楚地表现出来了。这就是把一切实在劳动化为它们共有的人类劳动的性质，化为人类劳动力的耗费。","language":"中文","translation":false},{"id":"capital-2-143","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"把劳动产品表现为只是无差别人类劳动的凝结物的一般价值形式，通过自身的结构表明，它是商品世界的社会表现。因此，它清楚地告诉我们，在这个世界中，劳动的一般的人类的性质形成劳动的特殊的社会的性质。","language":"中文","translation":false},{"id":"capital-2-144","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(2)相对价值形式和等价形式的发展关系","language":"中文","translation":false},{"id":"capital-2-145","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"等价形式的发展程度是同相对价值形式的发展程度相适应的。但是必须指出，等价形式的发展只是相对价值形式发展的表现和结果。","language":"中文","translation":false},{"id":"capital-2-146","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一种商品的简单的或个别的相对价值形式使另一种商品成为个别的等价物。扩大的相对价值形式，即一种商品的价值在其他一切商品上的表现，赋予其他一切商品以种种不同的特殊等价物的形式。最后，一种特殊的商品获得一般等价形式，是因为其他一切商品使它成为它们统一的、一般的价值形式的材料。","language":"中文","translation":false},{"id":"capital-2-147","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"价值形式发展到什么程度，它的两极即相对价值形式和等价形式之间的对立，也就发展到什么程度。","language":"中文","translation":false},{"id":"capital-2-148","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"第一种形式——20码麻布=1件上衣——就已经包含着这种对立，但没有使这种对立固定下来。我们从等式的左边读起，麻布是相对价值形式，上衣是等价形式，从等式的右边读起，上衣是相对价值形式，麻布是等价形式。在这里，要把握住两极的对立还相当困难。","language":"中文","translation":false},{"id":"capital-2-149","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在第二种形式中，每一次总是只有一种商品可以完全展开它的相对价值，或者说，它自身具有扩大的相对价值形式，是因为而且只是因为其他一切商品与它相对立，处于等价形式。在这里，不能再变换价值等式(例如20码麻布=1件上衣，或=10磅茶叶，或=1夸特小麦等等)的两边的位置，除非改变价值等式的全部性质，使它从总和的价值形式变成一般的价值形式。","language":"中文","translation":false},{"id":"capital-2-150","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"最后，后面一种形式，即第三种形式，给商品世界提供了一般的社会的相对价值形式，是因为而且只是因为除了一个唯一的例外，商品世界的一切商品都不能具有一般等价形式。因此，一种商品如麻布处于能与其他一切商品直接交换的形式，或者说，处于直接的社会的形式，是因为而且只是因为其他一切商品都不是处于这种形式。[24]","language":"中文","translation":false},{"id":"capital-2-151","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"相反地，充当一般等价物的商品则不能具有商品世界的统一的、从而是一般的相对价值形式。如果麻布，或任何一种处于一般等价形式的商品，要同时具有一般的相对价值形式，那末，它必须自己给自己充当等价物。于是我们得到的就是20码麻布=20码麻布，这是一个既不表现价值也不表现价值量的同义反复。要表现一般等价物的相对价值，我们就必须把第三种形式倒过来。一般等价物没有与其他商品共同的相对价值形式，它的价值相对地表现在其他一切商品体的无限的系列上。因此，扩大的相对价值形式，即第二种形式，现在表现为等价物商品特有的相对价值形式。","language":"中文","translation":false},{"id":"capital-2-152","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"(3)从一般价值形式到货币形式的过渡","language":"中文","translation":false},{"id":"capital-2-153","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一般等价形式是价值的一种形式。因此，它可以属于任何一种商品。另一方面，一种商品处于一般等价形式(第三种形式)，是因为而且只是因为它被其他一切商品当作等价物排挤出来。这种排挤最终限制在一种特殊的商品上，从这个时候起，商品世界的统一的相对价值形式才获得客观的固定性和一般的社会效力。","language":"中文","translation":false},{"id":"capital-2-154","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"等价形式同这种特殊商品的自然形式社会地结合在一起，这种特殊商品成了货币商品，或者执行货币的职能。在商品世界起一般等价物的作用就成了它特有的社会职能，从而成了它的社会独占权。在第二种形式中充当麻布的特殊等价物，而在第三种形式中把自己的相对价值共同用麻布来表现的各种商品中间，有一种商品在历史过程中夺得了这个特权地位，这就是金。因此，我们在第三种形式中用商品金代替商品麻布，就得到：","language":"中文","translation":false},{"id":"capital-2-155","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在第一种形式过渡到第二种形式，第二种形式过渡到第三种形式的时候，都发生了本质的变化。而第四种形式与第三种形式的唯一区别，只是金代替麻布取得了一般等价形式。金在第四种形式中同麻布在第三种形式中一样，都是一般等价物。唯一的进步是在于：能直接地一般地交换的形式，即一般等价形式，现在由于社会的习惯最终地同商品金的特殊的自然形式结合在一起了。","language":"中文","translation":false},{"id":"capital-2-156","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"金能够作为货币与其他商品相对立，只是因为它早就作为商品与它们相对立。与其他一切商品一样，它过去就起等价物的作用：或者是在个别的交换行为中起个别等价物的作用，或者是与其他商品等价物并列起特殊等价物的作用。渐渐地，它就在或大或小的范围内起一般等价物的作用。一当它在商品世界的价值表现中独占了这个地位，它就成为货币商品。只是从它已经成为货币商品的时候起，第四种形式才同第三种形式区别开来，或者说，一般价值形式才转化为货币形式。","language":"中文","translation":false},{"id":"capital-2-157","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"一种商品(如麻布)在已经执行货币商品职能的商品(如金)上的简单的相对的价值表现，就是价格形式。因此，麻布的“价格形式”是：","language":"中文","translation":false},{"id":"capital-2-158","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"如果2盎斯金的铸币名称是2镑，那就是：","language":"中文","translation":false},{"id":"capital-2-159","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"理解货币形式的困难，无非是理解一般等价形式，从而理解一般价值形式即第三种形式的困难。第三种形式倒转过来，就化为第二种形式，即扩大的价值形式，而第二种形式的构成要素是第一种形式：20码麻布=1件上衣，或者x量商品A=y量商品B。因此，简单的商品形式是货币形式的胚胎。","language":"中文","translation":false},{"id":"capital-2-160","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"4、商品的拜物教性质及其秘密","language":"中文","translation":false},{"id":"capital-2-161","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"最初一看，商品好象是一种很简单很平凡的东西。对商品的分析表明，它却是一种很古怪的东西，充满形而上学的微妙和神学的怪诞。商品就它是使用价值来说，不论从它靠自己的属性来满足人的需要这个角度来考察，或者从它作为人类劳动的产品才具有这些属性这个角度来考察，都没有什么神秘的地方。很明显，人通过自己的活动按照对自己有用的方式来改变自然物质的形态。例如，用木头做桌子，木头的形状就改变了。可是桌子还是木头，还是一个普通的可以感觉的物。但是桌子一旦作为商品出现，就变成一个可感觉而又超感觉的物了。它不仅用它的脚站在地上，而且在对其他一切商品的关系上用头倒立着，从它的木脑袋里生出比它自动跳舞还奇怪得多的狂想。[25]","language":"中文","translation":false},{"id":"capital-2-162","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，商品的神秘性质不是来源于商品的使用价值。同样，这种神秘性质也不是来源于价值规定的内容。因为，第一，不管有用劳动或生产活动怎样不同，它们都是人体的机能，而每一种这样的机能不管内容和形式如何，实质上都是人的脑、神经、肌肉、感官等等的耗费。这是一个生理学上的真理。第二，说到作为决定价值量的基础的东西，即这种耗费的持续时间或劳动量，那末，劳动的量可以十分明显地同劳动的质区别开来。在一切社会状态下，人们对生产生活资料所耗费的劳动时间必然是关心的，虽然在不同的发展阶段上关心的程度不同。[26]最后，一旦人们以某种方式彼此为对方劳动，他们的劳动也就取得社会的形式。","language":"中文","translation":false},{"id":"capital-2-163","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可是，劳动产品一采取商品形式就具有的谜一般的性质究竟是从哪里来的呢？显然是从这种形式本身来的。人类劳动的等同性，取得了劳动产品的等同的价值对象性这种物的形式；用劳动的持续时间来计量的人类劳动力的耗费，取得了劳动产品的价值量的形式；最后，劳动的那些社会规定借以实现的生产者的关系，取得了劳动产品的社会关系的形式。","language":"中文","translation":false},{"id":"capital-2-164","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，商品形式的奥秘不过在于：商品形式在人们面前把人们本身劳动的社会性质反映成劳动产品本身的物的性质，反映成这些物的天然的社会属性，从而把生产者同总劳动的社会关系反映成存在于生产者之外的物与物之间的社会关系。由于这种转换，劳动产品成了商品，成了可感觉而又超感觉的物或社会的物。正如一物在视神经中留下的光的印象，不是表现为视神经本身的主观兴奋，而是表现为眼睛外面的物的客观形式。但是在视觉活动中，光确实从一物射到另一物，即从外界对象射入眼睛。这是物理的物之间的物理关系。相反，商品形式和它借以得到表现的劳动产品的价值关系，是同劳动产品的物理性质以及由此产生的物的关系完全无关的。这只是人们自己的一定的社会关系，但它在人们面前采取了物与物的关系的虚幻形式。因此，要找一个比喻，我们就得逃到宗教世界的幻境中去。在那里，人脑的产物表现为赋有生命的、彼此发生关系并同人发生关系的独立存在的东西。在商品世界里，人手的产物也是这样。我把这叫做拜物教。劳动产品一旦作为商品来生产，就带上拜物教性质，因此拜物教是同商品生产分不开的。","language":"中文","translation":false},{"id":"capital-2-165","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":165,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品世界的这种拜物教性质，象以上分析已经表明的，是来源于生产商品的劳动所特有的社会性质。","language":"中文","translation":false},{"id":"capital-2-166","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":166,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"使用物品成为商品，只是因为它们是彼此独立进行的私人劳动的产品。这种私人劳动的总和形成社会总劳动。由于生产者只有通过交换他们的劳动产品才发生社会接触，因此，他们的私人劳动的特殊的社会性质也只有在这种交换中才表现出来。换句话说，私人劳动在事实上证实为社会总劳动的一部分，只是由于交换使劳动产品之间、从而使生产者之间发生了关系。因此，在生产者面前，他们的私人劳动的社会关系就表现为现在这个样子，就是说，不是表现为人们在自己劳动中的直接的社会关系，而是表现为人们之间的物的关系和物之间的社会关系。","language":"中文","translation":false},{"id":"capital-2-167","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":167,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"劳动产品只是在它们的交换中，才取得一种社会等同的价值对象性，这种对象性是与它们的感觉上各不相同的使用对象性相分离的。劳动产品分裂为有用物和价值物，实际上只是发生在交换已经十分广泛和十分重要的时候，那时有用物是为了交换而生产的，因而物的价值性质还在生产时就被注意到了。从那时起，生产者的私人劳动真正取得了二重的社会性质。一方面，生产者的私人劳动必须作为一定的有用劳动来满足一定的社会需要，从而证明它们是总劳动的一部分，是自然形成的社会分工体系的一部分。另一方面，只有在每一种特殊的有用的私人劳动可以同任何另一种有用的私人劳动相交换从而相等时，生产者的私人劳动才能满足生产者本人的多种需要。完全不同的劳动所以能够相等，只是因为它们的实际差别已被抽去，它们已被化成它们作为人类劳动力的耗费、作为抽象的人类劳动所具有的共同性质。私人生产者的头脑把他们的私人劳动的这种二重的社会性质，只是反映在从实际交易，产品交换中表现出来的那些形式中，也就是把他们的私人劳动的社会有用性，反映在劳动产品必须有用，而且是对别人有用的形式中；把不同种劳动的相等这种社会性质，反映在这些在物质上不同的物即劳动产品具有共同的价值性质的形式中。","language":"中文","translation":false},{"id":"capital-2-168","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":168,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"可见，人们使他们的劳动产品彼此当作价值发生关系，不是因为在他们看来这些物只是同种的人类劳动的物质外壳。恰恰相反，他们在交换中使他们的各种产品作为价值彼此相等，也就使他们的各种劳动作为人类劳动而彼此相等。他们没有意识到这一点，但是他们这样做了。[27]价值没有在额上写明它是什么。不仅如此，价值还把每个劳动产品变成社会的象形文字。后来，人们竭力要猜出这种象形文字的涵义，要了解他们自己的社会产品的秘密，因为使用物品当作价值，正象语言一样，是人们的社会产物。后来科学发现，劳动产品作为价值，只是生产它们时所耗费的人类劳动的物的表现，这一发现在人类发展史上划了一个时代，但它决没有消除劳动的社会性质的物的外观。彼此独立的私人劳动的特殊的社会性质表现为它们作为人类劳动而彼此相等，并且采取劳动产品的价值性质的形式——商品生产这种特殊生产形式所独具的这种特点，在受商品生产关系束缚的人们看来，无论在上述发现以前或以后，都是永远不变的，正象空气形态在科学把空气分解为各种元素之后，仍然作为一种物理的物态继续存在一样。","language":"中文","translation":false},{"id":"capital-2-169","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":169,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"产品交换者实际关心的问题，首先是他用自己的产品能换取多少别人的产品，就是说，产品按什么样的比例交换。当这些比例由于习惯而逐渐达到一定的稳固性时，它们就好象是由劳动产品的本性产生的。例如，1吨铁和2盎斯金的价值相等，就象1磅金和1磅铁虽然有不同的物理属性和化学属性，但是重量相等一样。实际上，劳动产品的价值性质，只是通过劳动产品作为价值量发生作用才确定下来。价值量不以交换者的意志、设想和活动为转移而不断地变动着。在交换者看来，他们本身的社会运动具有物的运动形式。不是他们控制这一运动，而是他们受这一运动控制。要有十分发达的商品生产，才能从经验本身得出科学的认识，理解到彼此独立进行的、但作为自然形成的社会分工部分而互相全面依赖的私人劳动，不断地被化为它们的社会的比例尺度，这是因为在私人劳动产品的偶然的不断变动的交换关系中，生产这些产品的社会必要劳动时间作为起调节作用的自然规律强制地为自己开辟道路，就象房屋倒在人的头上时重力定律强制地为自己开辟道路一样。[28]因此，价值量由劳动时间决定是一个隐藏在商品相对价值的表面运动后面的秘密。这个秘密的发现，消除了劳动产品的价值量纯粹是偶然决定的这种假象，但是决没有消除这种决定所采取的物的形式。","language":"中文","translation":false},{"id":"capital-2-170","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":170,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"对人类生活形式的思索，从而对它的科学分析，总是采取同实际发展相反的道路。这种思索是从事后开始的，就是说，是从发展过程的完成的结果开始的。给劳动产品打上商品烙印、因而成为商品流通的前提的那些形式，在人们试图了解它们的内容而不是了解它们的历史性质(人们已经把这些形式看成是不变的了)以前，就已经取得了社会生活的自然形式的固定性。因此，只有商品价格的分析才导致价值量的决定，只有商品共同的货币表现才导致商品的价值性质的确定。但是，正是商品世界的这个完成的形式——货币形式，用物的形式掩盖了私人劳动的社会性质以及私人劳动者的社会关系，而不是把它们揭示出来。如果我说，上衣、皮靴等等把麻布当作抽象的人类劳动的一般化身而同它发生关系，这种说法的荒谬是一目了然的。但是当上衣、皮靴等等的生产者使这些商品同作为一般等价物的麻布(或者金银，这丝毫不改变问题的性质)发生关系时，他们的私人劳动同社会总劳动的关系正是通过这种荒谬形式呈现在他们面前。","language":"中文","translation":false},{"id":"capital-2-171","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":171,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"这种种形式恰好形成资产阶级经济学的各种范畴。对于这个历史上一定的社会生产方式即商品生产的生产关系来说，这些范畴是有社会效力的、因而是客观的思维形式。因此，一旦我们逃到其他的生产形式中去，商品世界的全部神秘性，在商品生产的基础上笼罩着劳动产品的一切魔法妖术，就立刻消失了。","language":"中文","translation":false},{"id":"capital-2-172","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":172,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"既然政治经济学喜欢鲁滨逊的故事[29]，那末就先来看看孤岛上的鲁滨逊吧。不管他生来怎样简朴，他终究要满足各种需要，因而要从事各种有用劳动，如做工具，制家具，养羊驼，捕鱼，打猎等等。关于祈祷一类事情我们在这里就不谈了，因为我们的鲁滨逊从中得到快乐，他把这类活动当作休息。尽管他的生产职能是不同的，但是他知道，这只是同一个鲁滨逊的不同的活动形式，因而只是人类劳动的不同方式。需要本身迫使他精确地分配自己执行各种职能的时间。在他的全部活动中，这种或那种职能所占比重的大小，取决于他为取得预期效果所要克服的困难的大小。经验告诉他这些，而我们这位从破船上抢救出表、账簿、墨水和笔的鲁滨逊，马上就作为一个道地的英国人开始记起账来。他的账本记载着他所有的各种使用物品，生产这些物品所必需的各种活动，最后还记载着他制造这种种一定量的产品平均耗费的劳动时间。鲁滨逊和构成他自己创造的财富的物之间的全部关系在这里是如此简单明了，甚至连麦·维尔特先生用不着费什么脑筋也能了解。但是，价值的一切本质上的规定都包含在这里了。","language":"中文","translation":false},{"id":"capital-2-173","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":173,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"现在，让我们离开鲁滨逊的明朗的孤岛，转到欧洲昏暗的中世纪去吧。在这里，我们看到的，不再是一个独立的人了，人都是互相依赖的：农奴和领主，陪臣和诸侯，俗人和牧师。物质生产的社会关系以及建立在这种生产的基础上的生活领域，都是以人身依附为特征的。但是正因为人身依附关系构成该社会的基础，劳动和产品也就用不着采取与它们的实际存在不同的虚幻形式。它们作为劳役和实物贡赋而进入社会机构之中。在这里，劳动的自然形式，劳动的特殊性是劳动的直接社会形式，而不是象在商品生产基础上那样，劳动的共性是劳动的直接社会形式。徭役劳动同生产商品的劳动一样，是用时间来计量的，但是每一个农奴都知道，他为主人服役而耗费的，是他本人的一定量的劳动力。缴纳给牧师的什一税，是比牧师的祝福更加清楚的。所以，无论我们怎样判断中世纪人们在相互关系中所扮演的角色，人们在劳动中的社会关系始终表现为他们本身之间的个人的关系，而没有披上物之间即劳动产品之间的社会关系的外衣。","language":"中文","translation":false},{"id":"capital-2-174","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":174,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"要考察共同的劳动即直接社会化的劳动，我们没有必要回溯到一切文明民族的历史初期都有过的这种劳动的原始的形式。[30]这里有个更近的例子，就是农民家庭为了自身的需要而生产粮食、牲畜、纱、麻布、衣服等等的那种农村家长制生产。对于这个家庭来说，这种种不同的物都是它的家庭劳动的不同产品，但它们不是互相作为商品发生关系。生产这些产品的种种不同的劳动，如耕、牧、纺、织、缝等等，在其自然形式上就是社会职能，因为这是这样一个家庭的职能，这个家庭就象商品生产一样，有它本身的自然形成的分工。家庭内的分工和家庭各个成员的劳动时间，是由性别年龄上的差异以及随季节而改变的劳动的自然条件来调节的。但是，用时间来计量的个人劳动力的耗费，在这里本来就表现为劳动本身的社会规定，因为个人劳动力本来就只是作为家庭共同劳动力的器官而发挥作用的。","language":"中文","translation":false},{"id":"capital-2-175","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":175,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"最后，让我们换一个方面，设想有一个自由人联合体，他们用公共的生产资料进行劳动，并且自觉地把他们许多个人劳动力当作一个社会劳动力来使用。在那里，鲁滨逊的劳动的一切规定又重演了，不过不是在个人身上，而是在社会范围内重演。鲁滨逊的一切产品只是他个人的产品，因而直接是他的使用物品。这个联合体的总产品是社会的产品。这些产品的一部分重新用作生产资料。这一部分依旧是社会的。而另一部分则作为生活资料由联合体成员消费。因此，这一部分要在他们之间进行分配。这种分配的方式会随着社会生产机体本身的特殊方式和随着生产者的相应的历史发展程度而改变。仅仅为了同商品生产进行对比，我们假定，每个生产者在生活资料中得到的份额是由他的劳动时间决定的。这样，劳动时间就会起双重作用。劳动时间的社会的有计划的分配，调节着各种劳动职能同各种需要的适当的比例。另一方面，劳动时间又是计量生产者个人在共同劳动中所占份额的尺度，因而也是计量生产者个人在共同产品的个人消费部分中所占份额的尺度。在那里，人们同他们的劳动和劳动产品的社会关系，无论在生产上还是在分配上，都是简单明了的。","language":"中文","translation":false},{"id":"capital-2-176","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":176,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"在商品生产者的社会里，一般的社会生产关系是这样的：生产者把他们的产品当作商品，从而当作价值来对待，而且通过这种物的形式，把他们的私人劳动当作等同的人类劳动来互相发生关系。对于这种社会来说，崇拜抽象人的基督教，特别是资产阶级发展阶段的基督教，如新教、自然神教等等，是最适当的宗教形式。在古亚细亚的、古希腊罗马的等等生产方式下，产品变为商品、从而人作为商品生产者而存在的现象，处于从属地位，但是共同体越是走向没落阶段，这种现象就越是重要。真正的商业民族只存在于古代世界的空隙中，就象伊壁鸠鲁的神只存在于世界的空隙中【43】，或者犹太人只存在于波兰社会的缝隙中一样。这些古老的社会生产机体比资产阶级的社会生产机体简单明了得多，但它们或者以个人尚未成熟，尚未脱掉同其他人的自然血缘联系的脐带为基础，或者以直接的统治和服从的关系为基础。它们存在的条件是：劳动生产力处于低级发展阶段，与此相应，人们在物质生活生产过程内部的关系，即他们彼此之间以及他们同自然之间的关系是很狭隘的。这种实际的狭隘性，观念地反映在古代的自然宗教和民间宗教中。只有当实际日常生活的关系，在人们面前表现为人与人之间和人与自然之间极明白而合理的关系的时候，现实世界的宗教反映才会消失。只有当社会生活过程即物质生产过程的形态，作为自由结合的人的产物，处于人的有意识有计划的控制之下的时候，它才会把自己的神秘的纱幕揭掉。但是，这需要有一定的社会物质基础或一系列物质生存条件，而这些条件本身又是长期的、痛苦的历史发展的自然产物。","language":"中文","translation":false},{"id":"capital-2-177","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":177,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"诚然，政治经济学曾经分析了价值和价值量(虽然不充分)[31]，揭示了这些形式所掩盖的内容。但它甚至从来也没有提出过这样的问题：为什么这一内容要采取这种形式呢？为什么劳动表现为价值，用劳动时间计算的劳动量表现为劳动产品的价值量呢？[32]一些公式本来在额上写着，它们是属于生产过程支配人而人还没有支配生产过程的那种社会形态的，但在政治经济学的资产阶级意识中，它们竟象生产劳动本身一样，成了不言而喻的自然必然性。因此，政治经济学对待资产阶级以前的社会生产机体形式，就象教父对待基督教以前的宗教一样。[33]","language":"中文","translation":false},{"id":"capital-2-178","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":178,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"商品世界具有的拜物教性质或劳动的社会规定所具有的物的外观，怎样使一部分经济学家受到迷惑，也可以从关于自然在交换价值的形成中的作用所进行的枯燥无味的争论中得到证明。既然交换价值是表示消耗在物上的劳动的一定社会方式，它就象汇率一样并不包含自然物质。","language":"中文","translation":false},{"id":"capital-2-179","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":179,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"由于商品形式是资产阶级生产的最一般的和最不发达的形式(所以它早就出现了，虽然不象今天这样是统治的、从而是典型的形式)，因而，它的拜物教性质显得还比较容易看穿。但是在比较具体的形式中，连这种简单性的外观也消失了。货币主义的幻觉是从哪里来的呢？是由于货币主义没有看出：金银作为货币代表的一种社会生产关系，不过采取了一种具有奇特的社会属性的自然物的形式。而蔑视货币主义的现代经济学，一当它考察资本，它的拜物教不是也很明显吗？认为地租是由土地而不是由社会产生的重农主义幻觉，又破灭了多久呢？","language":"中文","translation":false},{"id":"capital-2-180","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":180,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"为了不致涉及以后的问题，这里仅仅再举一个关于商品形式本身的例子。假如商品能说话，它们会说：我们的使用价值也许使人们感到兴趣。作为物，我们没有使用价值。作为物，我们具有的是我们的价值。我们自己作为商品物进行的交易就证明了这一点。我们彼此只是作为交换价值发生关系。现在，让我们听听经济学家是怎样说出商品内心的话的：","language":"中文","translation":false},{"id":"capital-2-181","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":181,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"“价值〈交换价值〉是物的属性，财富〈使用价值〉是人的属性。从这个意义上说，价值必然包含交换，财富则不然。”[34]“财富〈使用价值〉是人的属性，价值是商品的属性。人或共同体是富的；珍珠或金刚石是有价值的……珍珠或金刚石作为珍珠或金刚石是有价值的。”[35]","language":"中文","translation":false},{"id":"capital-2-182","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":182,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"直到现在，还没有一个化学家在珍珠或金刚石中发现交换价值。可是那些自命有深刻的批判力、发现了这种化学物质的经济学家，却发现物的使用价值同它们的物质属性无关，而它们的价值倒是它们作为物所具有的。在这里为他们作证的是这样一种奇怪的情况：物的使用价值对于人来说没有交换就能实现，就是说，在物和人的直接关系中就能实现；相反，物的价值则只能在交换中实现，就是说，只能在一种社会的过程中实现。在这里，我们不禁想起善良的道勃雷，他教导巡丁西可尔说：【46】","language":"中文","translation":false},{"id":"capital-2-183","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":183,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"“一个人长得漂亮是环境造成的，会写字念书才是天生的本领”。[36]","language":"中文","translation":false},{"id":"capital-2-184","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":184,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[1] 卡尔·马克思《政治经济学批判》1859年柏林版第3页【26】。","language":"中文","translation":false},{"id":"capital-2-185","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":185,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【26】 见《马克思恩格斯全集》中文版第13卷第15页。——第47页。","language":"中文","translation":false},{"id":"capital-2-186","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":186,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[2] “欲望包含着需要；这是精神的食欲，就象肉体的饥饿那样自然……大部分〈物〉具有价值，是因为它们满足精神的需要。”（尼古拉·巴尔本《新币轻铸论。答洛克先生关于提髙货币价值的意见》1696年伦敦版第2，3页〉","language":"中文","translation":false},{"id":"capital-2-187","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":187,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[3] “物都有内在的长处〈这是巴尔本用来表示使用价值的专门用语〉，这种长处在任何地方都是一样的，如磁石吸铁的长处就是如此。”(尼古拉·巴尔本《新币轻铸论。答洛克先生关于提髙货币价值的意见》1696年伦敦版第6页）磁石吸铁的属性只是在通过它发现了磁极性以后才成为有用的。","language":"中文","translation":false},{"id":"capital-2-188","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":188,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[4] “任何物的自然界worth〔价值〕都在于它能满足必要的需要，或者给人类生活带来方便。”（约翰·洛克《论降低利息的后果》（1691年），载于《约翰·洛克著作集》1777年伦敦版第2卷第28页）在十七世纪，我们还常常看到英国著作家用“worth”表示使用价值，用你“value”表示交换价值；这完全符合英语的精神，英语喜欢用日耳盎语源的词表示直接的东西，用罗马语源的词表示被反射的东西。","language":"中文","translation":false},{"id":"capital-2-189","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":189,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[5] 在资产阶级社会中，流行着一种法律上的假定，认为每个人作为商品的买者都具有百科全书般的商品知识。","language":"中文","translation":false},{"id":"capital-2-190","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":190,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[6] 价值就是一物和另一物、一定量的这种产品和一定量的别种产品之间的交换关系。”(列特隆《论社会利益》,［载于］②德尔编《重农学派》1846年巴黎版第889页）","language":"中文","translation":false},{"id":"capital-2-191","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":191,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[7] “任何东西都不可能有内在的交换价值。”（尼·巴尔本《新币轻铸论。答洛克先生关于提髙货币价值的意见》第6页）或者象巴特勒所说：","language":"中文","translation":false},{"id":"capital-2-192","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":192,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"正好和它会换来的东西相等。”【27】","language":"中文","translation":false},{"id":"capital-2-193","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":193,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"② 本卷中凡是四角括号［］内的话都是德文版编者加的。——译者注","language":"中文","translation":false},{"id":"capital-2-194","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":194,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【27】 套用了赛·巴特勒的长诗《休迪布腊斯》第二部第一首中的一句话。——第49页。","language":"中文","translation":false},{"id":"capital-2-195","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":195,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[8] “只要交换价值相等，一种商品就同另一种商品一样。交换价值相等的物是没有任何差别或区别的……价值100镑的铅或铁与价值100镑的银和金具有相等的交换价值。”(尼·巴尔本《新币轻铸论。答洛克先生关于提高货币价值的意见》第53页和第7页）","language":"中文","translation":false},{"id":"capital-2-196","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":196,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[9] 第2版注：“当它们〈生活必需品〉互相交换的时候，它们的价值取决于生产它们所必需的和通常所用掉的劳动量。”（《对货币利息，特别是公债利息的一些看法》伦敦版第36、37页)上一世纪的这部值得注意的匿名著作没有注明出版日期。但从它的内容可以看出，该书是在乔治二世时代,大约1739年或1740年出版的。","language":"中文","translation":false},{"id":"capital-2-197","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":197,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[10] “全部同类产品其实只是一个量，这个量的价格是整个地决定的，而不以特殊情况为转移。”(列特隆《论社会利益》第893页）","language":"中文","translation":false},{"id":"capital-2-198","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":198,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[11] 卡尔·马克思《政治经济学批判》1859年柏林版第6页【28】。","language":"中文","translation":false},{"id":"capital-2-199","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":199,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【28】 见《马克思恩格斯全集》中文版第13卷第18页。——第53页。","language":"中文","translation":false},{"id":"capital-2-200","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":200,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【29】 见威·杰科布《贵金属生产和消费的历史研究》，两卷集，1831年伦敦版（W.Jacob.《An historical Inquiry into the Production and Consumption of the Precious Metals》. In two volumes. London, 1831）。——第53页。","language":"中文","translation":false},{"id":"capital-2-201","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":201,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[12] 卡尔·马克思《政治经济学批判》1859年柏林版第12、13等页【30】。","language":"中文","translation":false},{"id":"capital-2-202","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":202,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【30】 见《马克思恩格斯全集》中文版第13卷第23—25页及以下各页。——第55页。","language":"中文","translation":false},{"id":"capital-2-203","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":203,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[13]“宇宙的一切现象，不论是由人手创造的，还是由物理学的一般规律引起的，都不是真正的新创造，而只是物质的形态变化。结合和分离是人的智慧在分析再生产的观念时一再发现的唯一要素；价值〈指使用价值，尽管维里在这里同重农学派论战时自己也不清楚说的是哪一种价值〉和财富的再生产，如土地、空气和水在田地上变成谷物，或者昆虫的分泌物经过人的手变成丝绸，或者一些金属片被装配成钟表，也是这样。”(彼得罗·维里《政治经济学研究》1771年初版，载于库斯托第编《意大利政治经济学名家文集》现代部分，第15卷第21、22页)","language":"中文","translation":false},{"id":"capital-2-204","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":204,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【31】 ［威·配第］《赋税论》1667年伦敦版第47页（［W.Petty］《a Treatise of Taxes and Contributions》. London, 1667, p.47）。——第57页。","language":"中文","translation":false},{"id":"capital-2-205","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":205,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[14] 参看黑格尔《法哲学》1840年柏林版第250页190节。","language":"中文","translation":false},{"id":"capital-2-206","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":206,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[15] 读者应当注意，这里指的不是工人得到的一个工作日的工资或价值，而是指工人的一个工作日物化成的商品价值。在我们叙述的这个阶段，工资这个范畴根本还不存在。","language":"中文","translation":false},{"id":"capital-2-207","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":207,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[16] 第2版注：为了证明“只有劳动才是我们在任何时候都能够用来估计和比较各种商品价值的最后的和现实的唯一尺度”，亚·斯密写道：“等量的劳动在任何时侯和任何地方对工人本身都必定具有同样的价值。在工人的健康、精力和活动正常的情况下，在他所能具有的平均熟练程度的情况下，他总是要牺牲同样多的安宁、自由和幸福”(《国富论》第1卷第5章[第104—105页]）。一方面，亚·斯密在这里(不是在每一处）把价值决定于生产商品所耗费的劳动量，同商品价值决定于劳动的价值混为一谈，因而他力图证明，等量的劳动总是具有同样的价值。另一方面，他感觉到，劳动就它表现为商品的价值而论，只是劳动力的耗费，但他把这种耗费又仅仅理解为牺牲安宁、自由和幸福，而不是把它也看作正常的生命活动。诚然，他看到的是现代雇佣工人。——注[9]提到的亚·斯密的那位匿名的前辈的说法要恰当得多。他说：“某人制造这种必需品用了一个星期……而拿另一种物与他进行交换的人要确切地估计出什么是真正的等值物，最好计算出什么东西会花费自己同样多的labour［劳动］和时间。这实际上就是说，一个人在一定时间内在一物上用去的劳动，同另一个人在同样的时间内在另―物上用去的劳动相交换。”(《对货币利息，特别是公债利息的一些看法》第39页）——｛第4版注：英语有一个优点，它有两个不同的词来表达劳动的这两个不同的方面。创造使用价值的并具有一定质的劳动叫做work，以与labour相对；创造价值并且只在量上被计算的劳动叫做labour，以与work相对。见英译本第14页脚注。——弗·恩·｝","language":"中文","translation":false},{"id":"capital-2-208","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":208,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【32】 莎士比亚《亨利四世》前篇第三幕第三场。——第61页。","language":"中文","translation":false},{"id":"capital-2-209","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":209,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[17] 少数经济学家，例如赛·贝利，曾分析价值形式，但没有得到任何结果，这首先是因为他们把价值形式同价值混为一谈，其次，是因为在讲求实用的资产者的粗鄙的影响下，他们一开始就只注意量的规定性。“对量的支配……构成价值。”(《货币及其价值的变动》1837年伦敦版第11页)作者赛·贝利。】","language":"中文","translation":false},{"id":"capital-2-210","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":210,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【33】 “巴黎确实值一次弥撒”（《Paris vaut bien une messe》）是亨利四世的话，1593年巴黎人答应承认他为国王，条件是他应由新教改宗天主教，这时他便说了这句话。——第67页。","language":"中文","translation":false},{"id":"capital-2-211","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":211,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[18] 在某种意义上，人很象商品。因为人来到世间，既没有带着镜子，也不象费希特派的哲学家那样，说什么我就是我,所以人起初是以别人来反映自已的。名叫彼得的人把自己当作人,只是由于他把名叫保罗的人看作是和自己相同的。因此，对彼得说来，这整个保罗以他保罗的肉体成为人这个物种的表现形式。","language":"中文","translation":false},{"id":"capital-2-212","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":212,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[19] “价值”一词在这里是用来指一定量的价值即价值量，前面有的地方已经这样用过。","language":"中文","translation":false},{"id":"capital-2-213","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":213,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[20] 第2版注：庸俗经济学以惯有的机警利用了价值量和它的相对表现之间的这种不一致现象。例如：“如果承认，A由于同它相交换的B提高而降低，虽然这时在A上所耗费的劳动并不比以前少，这样，你们的一般价值原理就破产了……如果承认，由于与B相对而言，A的价值提高，所以与A相对而言，B的价值就降低，那末，李嘉图提出的关于商品的价值总是取决于商品所体现的劳动量这个大原理就站不住脚了；因为既然A的费用的变化不仅改变了本身的价值(与同它相交换的B相对而言)，而且也改变了B的价值(与A的价值相对而言)，虽然生产B所需要的劳动量并未发生任何变化，那末，不仅确认商品生产所耗费的劳动量调节商品价值的学说要破产，而且断言商品的生产费用调节商品价值的学说也要破产。”(约·布罗德赫斯特《政治经济学》1842年伦敦版第11、14页)","language":"中文","translation":false},{"id":"capital-2-214","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":214,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"布罗德赫斯特先生也可以说：看看10/20、10/50、10/100等等分数罢。即使10这个数字不变，但它的相对量，它与分母20、50、100相对而言的量却不断下降。可见，整数(例如10)的大小由它包含的单位数来“调节”这个大原理破产了。","language":"中文","translation":false},{"id":"capital-2-215","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":215,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[21] 这种反思的规定是十分奇特的。例如，这个人所以是国王，只因为其他人作为臣民同他发生关系。反过来，他们所以认为自己是臣民，是因为他是国王。","language":"中文","translation":false},{"id":"capital-2-216","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":216,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【34】 这里马克思引自亚里士多德的著作《尼科马赫伦理学》（《Ethica Nicomachea》，载于伊曼努尔·贝克尔编《亚里士多德全集》1837年牛津版第9卷第99、100页（《Aristotelis opera ex recensione Immanuelis Bekkeri》. Tomus IX. OXonii, 1837, p.99, 100）。——第74页。","language":"中文","translation":false},{"id":"capital-2-217","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":217,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[22] 第2版注：弗·路·奥·费里埃（海关副督查）《论政府和贸易的相互关系》1805年巴黎版。沙尔·加尼耳《论政治经济学的各种体系》1821年巴黎第2版。","language":"中文","translation":false},{"id":"capital-2-218","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":218,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【35】 伦巴特街——伦敦的金融中心西蒂区的一条街，一些大银行设在这里；伦敦金融市场的同义语。——第76页。","language":"中文","translation":false},{"id":"capital-2-219","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":219,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[23] 因此，如果麻布的价值用上衣来表现，我们就说麻布的上衣价值。如果麻布的价值用谷物来表现，我们就说麻布的谷物价值，依此类推。每一个这种表现都意味着，在上衣、谷物等等的使用价值上表现出来的是麻布的价值。“因为每种商品的价值都表示该商品在交换中的关系，所以根据它用来比较的商品，我们可以称它的价值为……谷物价值、呢绒价值；因此，有千万种价值，有多少种商品，就有多少种价值，它们都同样是现实的，又都同样是名义的。”(《对价值的本质、尺度和原因的批判研究，主要是论李嘉图先生及其信徒的著作》，《略论意见的形成和发表》一书的作者著，1825年伦敦版第39页)这部在英国曾经轰动一时的匿名著作的作者赛·贝利以为，只要这样指出同一商品价值具有种种不同的相对表现，就消除了规定价值概念的任何可能。虽然他十分浅薄，但却触及了李嘉图学说的弱点，李嘉图学派例如在《韦斯明斯特评论》上攻击贝利时流露的愤激情绪，就证明了这一点。","language":"中文","translation":false},{"id":"capital-2-220","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":220,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[24] 实际上从一般的能直接交换的形式决不可能看出，它是一种对立的商品形式，是同不能直接交换的形式分不开的，就象一块磁铁的阳极同阴极分不开一样。因此，设想能够同时在一切商品上打上能直接交换的印记，就象设想能够把一切天主教徒都变成教皇一样。对于把商品生产看作人类自由和个人独立的顶峰的小资产者来说，去掉与这种形式相联系的缺点，特别是去掉商品的不能直接交换的性质，那当然是再好不过的事。蒲鲁东的社会主义就是对这种庸俗空想的描绘；我在别的地方曾经指出【36】，这种社会主义连首创的功绩也没有，在它以前很久，就由格雷、布雷以及其他人更好地阐述过了。在今天，这并不妨碍这种智慧以“科学”的名义在一定范围内蔓延开来。没有一个学派比蒲鲁东学派更会滥用“科学”这个字眼了，因为","language":"中文","translation":false},{"id":"capital-2-221","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":221,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"“缺乏概念的地方， 字眼就及时出现”。【37】","language":"中文","translation":false},{"id":"capital-2-222","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":222,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【36】 卡·马克思《哲学的贫困。答蒲鲁东先生的〈贫困的哲学〉》第1章（见《马克思恩格斯全集》中文版第4卷第77—134页)。——第84页。","language":"中文","translation":false},{"id":"capital-2-223","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":223,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【37】 歌德《浮士德》第一部第四场（浮士德的书斋)。——第84页。","language":"中文","translation":false},{"id":"capital-2-224","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":224,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[25] 我们想起了，当世界其他一切地方好象静止的时候，中国和桌子开始跳起舞来,以激励别人【38】。","language":"中文","translation":false},{"id":"capital-2-225","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":225,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【38】 在欧洲，1848—1849年革命失败以后，出现了一个极黑暗的政治反动时期。当时欧洲国家的贵族热中于降神术，特别是桌子灵动术。而这时，在中国爆发了太平天国革命运动。——第88页。","language":"中文","translation":false},{"id":"capital-2-226","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":226,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[26] 第2版注：在古日耳曼人中，一摩尔根土地的面积是按一天的劳动来计算的。因此，摩尔根又叫做Tagwerk［一日的工作］（或Tagwanne）（jurnale或jurnalis，terra jurnalis或diurnalis)，Mannwerk［一人的工作］，Mannskraft［一人的力量］，Mannsmaad，Mannshauet［一人的收割量］等等。见格奥尔格·路德维希·冯·毛勒《马尔克制度、农户制度、乡村制度和城市制度以及公共政权的历史概论》1854年慕尼黑版第129页及以下各页。","language":"中文","translation":false},{"id":"capital-2-227","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":227,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[27] 第2版注：因此，当加利阿尼说价值是人和人之间的一种关系时，他还应当补充一句：这是被物的外壳掩盖着的关系。（加利阿尼《货币论》，载于库斯托第编《意大利政治经济学名家文集》现代部分，1803年米兰版第3卷第221页）","language":"中文","translation":false},{"id":"capital-2-228","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":228,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[28] “我们应该怎样理解这个只有通过周期性的革命才能为自己开辟道路的规律呢？这是一个以当事人的盲目活动为基础的自然规律。”（弗里德里希·恩格斯《政治经疥学批判大纲》，载于阿尔诺德·卢格和卡尔·马克思编的《德法年鉴》1844年巴黎版【39】）","language":"中文","translation":false},{"id":"capital-2-229","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":229,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【39】 见《马克思恩格斯全集》中文版第1卷第614页。——第92页。","language":"中文","translation":false},{"id":"capital-2-230","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":230,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[29] 第2版注：甚至李嘉图也离不开他的鲁滨逊故事。“他让原始的渔夫和原始的猎人一下子就以商品所有者的身分，按照物化在鱼和野味的交换价值中的劳动时间的比例交换鱼和野味。在这里他犯了时代错误，他竟让原始的渔夫和猎人在计算他们的劳动工具时去查看1817年伦敦交易所通用的年息表。看来，除了资产阶级社会形式外，‘欧文先生的平行四边形’【40】是他所知道的唯一的社会形式。”(卡尔·马克思《政治经济学批判》第38、39页【41】)","language":"中文","translation":false},{"id":"capital-2-231","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":231,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【40】 李嘉图在他的著作《论农业的保护关税》1822年伦敦第4版第21页（《On Protection to Agriculture》. Fourth edition. London, 1822, p.21）上提到欧文的平行四边形。欧文在阐述他的社会改革的空想计划时证明，从经济上以及从建立家庭生活的观点看来，最适当的是建筑平行四边形的或者正方形的住宅区。——第93页。","language":"中文","translation":false},{"id":"capital-2-232","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":232,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【41】 见《马克思恩格斯全集》中文版第13卷第50—51页。——第93页。","language":"中文","translation":false},{"id":"capital-2-233","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":233,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[30] 第2版注：“近来流传着一种可笑的偏见，认为原始的公社所有制是斯拉夫族特有的形式，甚至只是俄罗斯的形式。这种原始形式我们在罗马人、日耳曼人、克尔特人那里都可以见到，直到现在我们还能在印度人那里遇到这种形式的一整套图样，虽然其中一部分只留下残迹了。仔细研究一下亚细亚的、尤其是印度的公社所有制形式，就会得到证明，从原始的公社所有制的不同形式中，怎样产生出它的解体的各种形式。例如，罗马和日耳曼的私人所有制的各种原型，就可以从印度的公社所有制的各种形式中推出来。”(卡尔·马克思《政治经济学批判》第10页【42】）","language":"中文","translation":false},{"id":"capital-2-234","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":234,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【42】 见《马克思恩格斯全集》中文版第13卷第22页。——第95页。","language":"中文","translation":false},{"id":"capital-2-235","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":235,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【43】 古希腊哲学家伊壁鸠鲁认为有无数的世界。这些世界是按照它们本身的自然规律产生和存在的。神虽然存在，但存在于世界之外，存在于世界之间的空隙中，对宇宙的发展和人的生活没有任何影响。——第96页。","language":"中文","translation":false},{"id":"capital-2-236","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":236,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[31] 李嘉图对价值量的分析并不充分，——但已是最好的分析，——这一点人们将在本书第三卷和第四卷中看到。至于价值本身，古典政治经济学在任何地方也没有明确地和十分有意识地把体现为价值的劳动同体现为产品使用价值的劳动区分开。当然，古典政治经济学事实上是这样区分的，因为它有时从量的方面，有时从质的方面来考察劳动。但是，它从来没有意识到，劳动的纯粹量的差别是以它们的质的统一或等同为前提的，因而是以它们化为抽象人类劳动为前提的。例如，李嘉图就曾表示他同意德斯杜特·德·特拉西的说法。德斯杜特说：“很清楚，我们的体力和智力是我们唯一的原始的财富，因此，这些能力的运用，某种劳动，是我们的原始的财宝；凡是我们称为财富的东西，总是由这些能力的运用创造出来的……此外，这一切东西确实只代表创造它们的劳动，如果它们有价值，或者甚至有两种不同的价值，那也只能来源于创造它们的劳动的价值。”(李嘉图《政治经济学原理》1821年伦敦第3版第334页）我们只指出，李嘉图在德斯杜特的话中塞进了自己的更加深刻的思想。一方面，德斯杜特确实说过，凡是构成财富的东西都“代表创造它们的劳动”。伹是另一方面，他又说，这一切东西的“两种不同的价值”(使用价值和交换价值)来自“劳动的价值”。这样，他就陷入庸俗经济学的平庸浅薄之中。庸俗经济学先假设一种商品（在这里是指劳动）的价值，然后再用这种价值去决定其他商品的价值。而李嘉图却把德斯杜特的话读作：劳动（而不是劳动的价值）既表现为使用价值，也表现为交换价值。不过他自己也不善于区别具有二重表现的劳动的二重性质，以致在关于《价值和财富，它们的不同性质》这整整一章中，不得不同让·巴·萨伊这个人的庸俗见解苦苦纠缠。因此，最后他不禁楞住了：在劳动是价值的源泉这一点上，德斯杜特虽然同他是一致的，可是另一方面，在价值概念上，德斯杜特却同萨伊是一致的。","language":"中文","translation":false},{"id":"capital-2-237","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":237,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[32] 古典政治经济学的根本缺点之一，就是它始终不能从商品的分析，而特别是商品价值的分析中，发现那种正是使价值成为交换价值的价值形式。恰恰是古典政治经济学的最优秀的代表人物，象亚·斯密和李嘉图，把价值形式看成一种完全无关紧要的东西或在商品本性之外存在的东西。这不仅仅因为价值量的分析把他们的注意力完全吸引住了。还有更深刻的原因。劳动产品的价值形式是资产阶级生产方式的最抽象的、但也是最一般的形式，这就使资产阶级生产方式成为一种特殊的社会生产类型，因而同时具有历史的特征。因此，如果把资产阶级生产方式误认为是社会生产的永恒的自然形式，那就必然会忽略价值形式的特殊性，从而忽略商品形式及其进一步发展——货币形式、资本形式等等的特殊性。因此，我们发现，在那些完全同意用劳动时间来计算价值量的经济学家中间，对于货币即一般等价物的完成形态的看法是极为混乱和矛盾的。例如，在考察银行业时，这一点表现得特别明显，因为在这里关于货币的通常的定义已经不够用了。于是，与此相对立的，出现了复兴的重商主义体系(加尼耳等人)，这一体系在价值中只看到社会形式，或者更确切地说，只看到这种社会形式的没有实体的外观。——在这里，我断然指出，我所说的古典政治经济学，是指从威·配第以来的一切这样的经济学，这种经济学与庸俗经济学相反，研究了资产阶级生产关系的内部联系。而庸俗经济学却只是在表面的联系内兜圈子，它为了对可以说是最粗浅的现象作出似是而非的解释，为了适应资产阶级的日常需要，一再反复咀嚼科学的经济学早就提供的材料。在其他方面，庸俗经济学则只限于把资产阶级生产当事人关于他们自己的最美好世界的陈腐而自负的看法加以系统化，赋以学究气味，并且宣布为永恒的真理。","language":"中文","translation":false},{"id":"capital-2-238","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":238,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[33] 经济学家们在论断中采用的方式是非常奇怪的。他们认为只有两种制度：―种是人为的，一种是天然的。封建制度是人为的，资产阶级制度是天然的。在这方面，经济学家很象那些把宗教也分为两类的神学家。一切异教都是人们臆造的，而他们自已的教则是神的启示。——于是，以前是有历史的，现在再也没有历史了。”（卡尔·马克思《哲学的贫困。答蒲鲁东先生的〈贫困的哲学〉》1847年版第113页【44】）巴师夏先生认为古代希腊人和罗马人专靠掠夺为生，这真是滑稽可笑。如果人们几百年来都靠掠夺为生，那就得经常有可供掠夺的东西，或者说，被掠夺的对象应当不断地被再生产出来。可见，希腊人和罗马人看来也要有某种生产过裎，从而有某种经济，这种经济构成他们的世界的物质基础，就象资产阶级经济构成现今世界的物质基础一样。也许巴师夏的意思是说，建立在奴隶劳动上的生产方式是以某种掠夺制度为基础吧？如果是这样，他就处于危险的境地了。既然象亚里士多德那样的思想巨人在评价奴隶劳动时都难免发生错误，那末，象巴师夏这样的经济学侏儒在评价雇佣劳动时怎么会正确无误呢？——借这个机会，我要简短地回答一下美国一家德文报纸在我的《政治经济学批判》一书出版时（1859年）对我的指责。在那本书中我曾经说过，一定的生产方式以及与它相适应的生产关系，简言之，“社会的经济结构，是有法律的和政治的上层建筑竖立其上并有一定的社会意识形式与之相适应的现实基础”，“物质生活的生产方式制约着整个社会生活、政治生活和精神生活的过程”【45】。可是据上述报纸说，这一切提法固然适用于物质利益占统治地位的现今世界，但却不适用于天主教占统治地位的中世纪，也不适用于政治占统治地位的雅典和罗马。首先，居然有人以为这些关于中世纪和古代世界的人所共知的老生常谈还会有人不知道，这真是令人惊奇。很明白，中世纪不能靠天主教生活，古代世界不能靠政治生活。相反，这两个时代谋生的方式和方法表明，为什么在古代世界政治起着主要作用，而在中世纪天主教起着主要作用。此外，例如只要对罗马共和国的历史稍微有点了解，就会知道，地产的历史构成罗马共和国的秘史。而从另一方面说，唐·吉诃德误认为游侠生活可以同任何社会经济形式并存，结果遭到了惩罚。","language":"中文","translation":false},{"id":"capital-2-239","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":239,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【44】 见《马克思恩格斯全集》中文版第4卷第153—154页。——第98页。","language":"中文","translation":false},{"id":"capital-2-240","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":240,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【45】 见《马克思恩格斯全集》中文版第13卷第8页。——第99页。","language":"中文","translation":false},{"id":"capital-2-241","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":241,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[34] 《评政治经济学上的若干用语的争论，特别是有关价值、供求的争论》1821年伦敦版第16页。","language":"中文","translation":false},{"id":"capital-2-242","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":242,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[35] 赛·贝利《对价值的本质、尺度和原因的批判研究》第165页及以下各页。","language":"中文","translation":false},{"id":"capital-2-243","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":243,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"【46】 莎士比亚《无事烦恼》第三幕第三场。——第100页。","language":"中文","translation":false},{"id":"capital-2-244","author":"马克思","title":"资本论·第一卷","location":"第一章 商 品","page":2,"paragraph":244,"url":"https://www.marxists.org/chinese/marx/capital/01.htm","text":"[36] 《评政治经挤学上的若干用语的争论》一书的作者和赛·贝利责备李嘉图，说他把交换价值从一种只是相对的东西变成一种绝对的东西。恰恰相反，李嘉图是把金刚石、珍珠这种物在作为交换价值时所具有的表面的相对性，还原为这种外表所掩盖的真实关系，还原为它们作为人类劳动的单纯表现的相对性。如果说李嘉图派对贝利的答复既粗浅而又缺乏说服力，那只是因为他们在李嘉图本人那里找不到关于价值和价值形式即交换价值之间的内部联系的任何说明。","language":"中文","translation":false},{"id":"capital-3-1","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-3-2","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"商品不能自己到市场去，不能自己去交换。因此，我们必须找寻它的监护人，商品所有者。商品是物，所以不能反抗人。如果它不乐意，人可以使用强力，换句话说，把它拿走[37]。为了使这些物作为商品彼此发生关系，商品监护人必须作为有自己的意志体现在这些物中的人彼此发生关系，因此，一方只有符合另一方的意志，就是说每一方只有通过双方共同一致的意志行为，才能让渡自己的商品，占有别人的商品。可见，他们必须彼此承认对方是私有者。这种具有契约形式的（不管这种契约是不是用法律固定下来的）法权关系，是一种反映着经济关系的意志关系。这种法权关系或意志关系的内容是由这种经济关系本身决定的[38]。在这里，人们彼此只是作为商品的代表即商品所有者而存在。在研究进程中我们会看到，人们扮演的经济角色不过是经济关系的人格化，人们是作为这种关系的承担者而彼此对立着的。","language":"中文","translation":false},{"id":"capital-3-3","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"商品所有者与商品不同的地方，主要在于：对商品来说，每个别的商品体只是它本身的价值的表现形式。商品是天生的平等派和昔尼克派，它随时准备不仅用自己的灵魂而且用自己的肉体去同任何别的商品交换，哪怕这个商品生得比马立托奈斯还丑。商品所缺乏的这种感知其他商品体的具体属性的能力，由商品所有者用他自己的五种和五种以上的感官补足了。商品所有者的商品对他没有直接的使用价值。否则，他就不会把它拿到市场上去。他的商品对别人有使用价值。他的商品对他来说，直接有的只是这样的使用价值：它是交换价值的承担者，从而是交换手段[39]。所以，他愿意让渡他的商品来换取那些使用价值为他所需要的商品。一切商品对它们的所有者是非使用价值，对它们的非所有者是使用价值。因此，商品必须全面转手。这种转手就形成商品交换，而商品交换使商品彼此作为价值发生关系并作为价值来实现。可见，商品在能够作为使用价值实现以前，必须先作为价值来实现。","language":"中文","translation":false},{"id":"capital-3-4","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"另一方面，商品在能够作为价值实现以前，必须证明自己是使用价值，因为耗费在商品上的人类劳动，只有耗费在对别人有用的形式上，才能算数。但是，这种劳动对别人是否有用，它的产品是否能够满足别人的需要，只有在商品交换中才能得到证明。","language":"中文","translation":false},{"id":"capital-3-5","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"每一个商品所有者都只想让渡自己的商品，来换取别种具有能够满足他本人需要的使用价值的商品。就这一点说，交换对于他只是个人的过程。另一方面，他想把他的商品作为价值来实现，也就是通过他所中意的任何另一种具有同等价值的商品来实现，而不问他自己的商品对于这另一种商品的所有者是不是有使用价值。就这一点说，交换对于他是一般社会的过程。但是，同一过程不可能同时对于一切商品所有者只是个人的过程，同时又只是一般社会的过程。","language":"中文","translation":false},{"id":"capital-3-6","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"我们仔细看一下就会发现，对每一个商品所有者来说，每个别人的商品都是他的商品的特殊等价物，从而他的商品是其他一切商品的一般等价物。既然一切商品所有者都这样做，所以没有一种商品是一般等价物，商品也就不具有使它们作为价值彼此等同、作为价值量互相比较的一般的相对价值形式。因此，它们并不是作为商品，而只是作为产品或使用价值彼此对立着。","language":"中文","translation":false},{"id":"capital-3-7","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"我们的商品所有者在他们的困难处境中是象浮士德那样想的：起初是行动【48】。因此他们还没有想就已经做起来了。商品本性的规律通过商品所有者的天然本能表现出来。他们只有使他们的商品同任何别一种作为一般等价物的商品相对立，才能使他们的商品作为价值，从而作为商品彼此发生关系。商品分析已经表明了这一点。但是，只有社会的活动才能使一种特定的商品成为一般等价物。因此，其他一切商品的社会的行动使一种特定的商品分离出来，通过这种商品来全面表现它们的价值。于是这一商品的自然形式就成为社会公认的等价形式。由于这种社会过程，充当一般等价物就成为被分离出来的商品的特殊社会职能。这种商品就成为货币。","language":"中文","translation":false},{"id":"capital-3-8","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"“他们同心合意，把力量和权柄授予那只兽。凡没有这种印记即没有这个兽名或兽名的数字者，都不能买或卖。”（《启示录》【49】）","language":"中文","translation":false},{"id":"capital-3-9","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"货币结晶是交换过程的必然产物，在交换过程中，各种不同的劳动产品事实上彼此等同，从而事实上转化为商品。交换的扩大和加深的历史过程，使商品本性中潜伏着的使用价值和价值的对立发展起来。为了交易，需要这一对立在外部表现出来，这就要求商品价值有一个独立的形式，这个需要一直存在，直到由于商品分为商品和货币这种二重化而最终取得这个形式为止。可见，随着劳动产品转化为商品，商品就在同一程度上转化为货币。[40]","language":"中文","translation":false},{"id":"capital-3-10","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"直接的产品交换一方面具有简单价值表现形式，另一方面还不具有这种形式。这种形式就是x量商品A=y量商品B。直接的产品交换形式是x量使用物品A=y量使用物品B。[41]在这里，A物和B物在交换之前不是商品，它们通过交换才成为商品。使用物品可能成为交换价值的第一步，就是它作为非使用价值而存在，作为超过它的所有者的直接需要的使用价值量而存在。物本身存在于人之外，因而是可以让渡的。为使让渡成为相互的让渡，人们只须默默地彼此当作被让渡的物的私有者，从而彼此当作独立的人相对立就行了。然而这种彼此当作外人看待的关系在原始共同体的成员之间并不存在，不管这种共同体的形式是家长制家庭，古代印度公社，还是印加国【51】，等等。商品交换是在共同体的尽头，在它们与别的共同体或其成员接触的地方开始的。但是物一旦对外成为商品，由于反作用，它们在共同体内部也成为商品。它们交换的量的比例起初完全是偶然的。它们能够交换，是由于它们的所有者彼此愿意把它们让渡出去的意志行为。同时，对别人的使用物品的需要渐渐固定下来。交换的不断重复使交换成为有规则的社会过程。因此，随着时间的推移，至少有一部分劳动产品必定是有意为了交换而生产的。从那时起，一方面，物满足直接需要的效用和物用于交换的效用的分离固定下来了。它们的使用价值同它们的交换价值分离开来。另一方面，它们相交换的量的比例是由它们的生产本身决定的。习惯把它们作为价值量固定下来。","language":"中文","translation":false},{"id":"capital-3-11","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"在直接的产品交换中，每个商品对于它的所有者直接就是交换手段，对于它的非所有者直接就是等价物，不过它要对于后者是使用价值。因此，交换物还没有取得同它本身的使用价值或交换者的个人需要相独立的价值形式。随着进入交换过程的商品数量和种类的增多，就越来越需要这种形式。问题和解决问题的手段同时产生。如果不同商品所有者的不同商品在它们的交易中不和同一个第三种商品相交换并作为价值和它相比较，商品所有者拿自己的物品同其他种种物品相交换、相比较的交易就决不会发生。这第三种商品由于成为其他各种商品的等价物，就直接取得一般的或社会的等价形式，虽然是在狭小的范围内。这种一般等价形式同引起这个形式的瞬息间的社会接触一起产生和消失。这种形式交替地、暂时地由这种或那种商品承担。但是，随着商品交换的发展，这种形式就只是固定在某些特定种类的商品上，或者说结晶为货币形式。它究竟固定在哪一种商品上，最初是偶然的。但总的说来，有两种情况起着决定的作用。货币形式或者固定在最重要的外来交换物品上，这些物品事实上是本地产品的交换价值的自然形成的表现形式；或者固定在本地可让渡的财产的主要部分如牲畜这种使用物品上。游牧民族最先发展了货币形式，因为他们的一切财产都具有可以移动的因而可以直接让渡的形式，又因为他们的生活方式使他们经常和别的共同体接触，因而引起产品交换。人们过去常常把作为奴隶的人本身当作原始的货币材料，但是从来没有把土地当作这种材料。这种想法只有在发达的资产阶级社会里才会产生。它出现在十七世纪最后三十多年，而只是在一个世纪以后的法国资产阶级革命时期，有人才试图在全国范围内来实现它。","language":"中文","translation":false},{"id":"capital-3-12","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"随着商品交换日益突破地方的限制，从而商品价值日益发展成为一般人类劳动的化身，货币形式也就日益转到那些天然适于执行一般等价物这种社会职能的商品身上，即转到贵金属身上。","language":"中文","translation":false},{"id":"capital-3-13","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"“金银天然不是货币，但货币天然是金银”[42]，这句话已为金银的自然属性适于担任货币的职能而得到证明[43]。但至此我们只知道货币的一种职能：它是商品价值的表现形式，或者是商品价值量借以取得社会表现的材料。一种物质只有分成的每一份都是均质的，才能成为价值的适当的表现形式，或抽象的因而等同的人类劳动的化身。另一方面，因为价值量的差别纯粹是量的差别，所以货币商品必须只能有纯粹量的差别，就是说，必须能够随意分割，又能够随意把它的各部分合并起来。金和银就天然具有这种属性。","language":"中文","translation":false},{"id":"capital-3-14","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"货币商品的使用价值二重化了。它作为商品具有特殊的使用价值，如金可以镶牙，可以用作奢侈品的原料等等，此外，它又取得一种由它的特殊的社会职能产生的形式上的使用价值。","language":"中文","translation":false},{"id":"capital-3-15","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"既然其他一切商品只是货币的特殊等价物，而货币是它们的一般等价物，所以它们是作为特殊商品来同作为一般商品的货币[44]发生关系。","language":"中文","translation":false},{"id":"capital-3-16","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"我们已经知道，货币形式只是其他一切商品的关系固定在一种商品上面的反映。所以，只有在那些从货币的完成的形态出发而从后往前分析商品的人看来，“货币是商品”才是一种发现[45]。对于交换过程使之转化为货币的那个商品，交换过程给予它的，不是它的价值，而是它的特殊的价值形式。有人由于把这两种规定混淆起来，曾误认为金银的价值是想象的[46]。由于货币在某些职能上可以用它本身的单纯的符号来代替，又产生了另一种误解，以为货币是一种单纯符号。但另一方面，在这种误解里面包含了一种预感：物的货币形式是物本身以外的东西，它只是隐藏在物后面的人的关系的表现形式。从这个意义上说，每个商品都是一个符号，因为它作为价值只是耗费在它上面的人类劳动的物质外壳[47]。但是，当人们把物在一定的生产方式的基础上取得的社会性质，或者说，把劳动的社会规定在一定的生产方式的基础上取得的物质性质说成是单纯的符号时，他们就把这些性质说成是人随意思考的产物。这是十八世纪流行的启蒙方法，其目的是要在人们还不能解释人的关系的谜一般的形态的产生过程时，至少暂时把这种形态的奇异外观除掉。","language":"中文","translation":false},{"id":"capital-3-17","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"前面已经指出，一个商品的等价形式并不包含该商品的价值量的量的规定。即使我们知道金是货币，因而可以同其他一切商品直接交换，我们并不因此就知道例如10磅金的价值是多少。货币同任何商品一样，只能相对地通过别的商品来表现自己的价值量。它本身的价值是由生产它所需要的劳动时间决定的，并且是通过每个含有同样多劳动时间的别种商品的量表现出来的[48]。金的相对价值量是在金的产地通过直接的物物交换确定的。当它作为货币进入流通时，它的价值已经是既定的了。还在十七世纪最后几十年，人们已经知道货币是商品，这在货币分析上是跨出很大一步的开端，但终究只是开端而已。困难不在于了解货币是商品，而在于了解商品怎样、为什么、通过什么成为货币。[49]","language":"中文","translation":false},{"id":"capital-3-18","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"我们已经看到，在x量商品A＝y量商品B这个最简单的价值表现中，就已经存在一种假象，好象表现另一物的价值量的物不通过这种关系就具有自己的等价形式，好象这种形式是天然的社会属性。我们已经探讨了这种假象是怎样确立起来的。当一般等价形式同一种特殊商品的自然形式结合在一起，即结晶为货币形式的时候，这种假象就完全形成了。一种商品成为货币，似乎不是因为其他商品都通过它来表现自己的价值，相反，似乎因为这种商品是货币，其他商品才都通过它来表现自己的价值。中介运动在它本身的结果中消失了，而且没有留下任何痕迹。商品没有出什么力就发现一个在它们之外、与它们并存的商品体是它们的现成的价值形态。这些物，即金和银，一从地底下出来，就是一切人类劳动的直接化身。货币的魔术就是由此而来的。人们在自己的社会生产过程中的单纯原子般的关系，从而，人们自己的生产关系的不受他们控制和不以他们有意识的个人活动为转移的物的形式，首先就是通过他们的劳动产品普遍采取商品形式这一点而表现出来。因此，货币拜物教的谜就是商品拜物教的谜，只不过变得明显了，耀眼了。","language":"中文","translation":false},{"id":"capital-3-19","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[37] 在以虔诚著称的十二世纪，商品行列里常常出现一些极妙的物。当时一位法国诗人所列举的兰第市场【47】上的商品中，除衣料、鞋子、皮革、农具、毛皮等物以外，还有“淫荡的女人”。","language":"中文","translation":false},{"id":"capital-3-20","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"【47】 兰第市场——巴黎近郊的一个大集市，从十二世纪至十九世纪每年都举办。——第102页。","language":"中文","translation":false},{"id":"capital-3-21","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[38] 蒲鲁东先从与商品生产相适应的法权关系中提取他的公平的理想，永恒公平的理想。顺便说一下，这就给一切庸人提供了一个使他们感到宽慰的论据，说商品生产形式象公乎一样也是永恒的。然后，他反过来又想按照这种理想来改造现实的商品生产和与之相适应的现实的法权。如果一个化学家不去研究物质变换的现实规律，并根据这些规律解决一定的问题，却要按照“自然性”和“亲合性”这些“永恒观念”来改造物质变换，那末对于这样的化学家人们该怎样想呢？如果有人说，“高利贷”违背“永恒公平”、“永恒公道”、“永恒互助”以及其他种种“永恒真理”，那末这个人对髙利贷的了解比那些说髙利贷违背“永恒恩典”、“永恒信仰”和“永恒神意”的教父的了解又高明多少呢？","language":"中文","translation":false},{"id":"capital-3-22","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[39] “因为每种货物都有两种用途。——一种是物本身所固有的，另一种则不然，例如鞋，既用来穿，又可以用来交换。二者都是鞋的使用价值，因为谁用鞋来交换他所需要的东西，例如食物，谁就是利用了鞋。但不是利用鞋的自然用途，因为它不是为交换而存在的。”(亚里士多德《政治学》第1卷第9章）","language":"中文","translation":false},{"id":"capital-3-23","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"【48】 歌德《浮士德》第一部第三场（《浮士德的书斋》〉。——第104页。","language":"中文","translation":false},{"id":"capital-3-24","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"【49】《启示录》是收入《新约全书》的早期基督教著作之一（圣经《约翰启示录》〕。写于一世纪。《启示录》的作者表达了对罗马帝国的公愤，把它打上“兽”的印记，并把它看作魔鬼的化身。这里引用的是第十七章和第十三章。——第105页。","language":"中文","translation":false},{"id":"capital-3-25","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[40] 依此我们可以判断小资产阶级社会主义的滑头了。小资产阶级社会主义既想使商品生产永恒化，又想废除“货币和商品的对立”，就是说废除货币本身，因为货币只是存在于这种对立中。这么说，我们同样也可以废除教皇而保存天主教了。关于这个问题详见我的《政治经济学批判》第61页及以下各页。【50】","language":"中文","translation":false},{"id":"capital-3-26","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"【50】 见《马克思恩格斯全集》中文版第13卷第76页及以下各页。——第105页。","language":"中文","translation":false},{"id":"capital-3-27","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[41] 只要不是两种不同的使用物品相交换，而是象在野蛮人中间常见的那样，把一堆混杂的东西当作一种东西的等价物，那末，连直接的产品交换也还处于它的初期阶段。","language":"中文","translation":false},{"id":"capital-3-28","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"【51】 印加国是保存着很多原始社会残余的奴隶占有制国家。社会组织和经济组织的基础是共同占有土地和牲畜的氏族公社或村社（Aylla）。印加国的繁盛时期，是从十五世纪末一直到十六世纪三十年代被西班牙占领和完全消灭为止。当时它曾扩展到今日的秘鲁、厄瓜多尔、玻利维亚和智利北部。——第106页。","language":"中文","translation":false},{"id":"capital-3-29","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[42] 卡尔·马克思《政治经济学批判》第135页【52】。“贵金属……天然是货币。”(加利阿尼《货币论》，见库斯托第编《意大利政治经济学名家文集》现代部分,第3卷第137页）","language":"中文","translation":false},{"id":"capital-3-30","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"【52】 见《马克思恩格斯全集》中文版第13卷第145页。——第107页。","language":"中文","translation":false},{"id":"capital-3-31","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[43] 详见我的上述著作中《贵金属》一节。","language":"中文","translation":false},{"id":"capital-3-32","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[44] “货币是一般商品。”(维里《政治经济学研究》第16页）","language":"中文","translation":false},{"id":"capital-3-33","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[45] “我们可以统称为贵金属的金锒本身，是……价值……时涨时落的……商品……当重量较小的贵金属可以购买数量较大的本国农产品或工业品等等时，我们可以认为贵金属的价值较髙。”（［西·克雷门特］《论货币、贸易、汇兑的相互关系的一般概念》，一个商人著，1695年伦敦版第7页）“银和金，已铸币的或者未铸币的，虽然被用作计量其他一切物的尺度，但是它们和酒、油、烟，布或毛织物一样，也是商品。”(［约·柴尔德］《论贸易，特别是东印度的贸易》1689年伦敦版第2页）“王国的财产和财富严格地说不能只限于货币，金和银也不能被排除在商品之外。”(［托·帕皮隆］《东印度的贸易是对王国最有利的贸易》1677年伦敦版第4页）","language":"中文","translation":false},{"id":"capital-3-34","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[46] “金银在成为货币以前，作为金属就具有价值。”（加利阿尼《货币论》第72页)洛克说：“由于银具有适于作货币的质，人们就一致同意给银一种想象的价值。”［约翰·洛克《论降低利息和提髙货币价值的后果》（1691年），载于《约翰·洛克著作集》1777年版第2卷第15页]与此相反，罗说：“不同的国家怎能给某物以一种想象的价值……或者说，这种想象的价值怎能保持下去呢？”但是请看他本人对这个问题了解得多么差：“银按照它具有的使用价值即它的实际价值进行交换；由于它作为货币的使命，又取得一个追加价值。”(约翰·罗《论货币和贸易》，载于欧·德尔编《十八世纪的财政经济学家》第469、470页）","language":"中文","translation":false},{"id":"capital-3-35","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[47] “货币是它〈商品〉的符号。”（弗·德·福尔邦奈《商业学入门》1766年来顿新版第2卷第143页〉“货币作为符号被商品吸引。”（同上，笫155页)“货币是某种物的符号，并且代表这种物。”（孟德斯鸠《论法的精神》，《孟德斯鸠全集》1767年伦敦版第2卷第3页)“货币不是单纯的符号，因为它本身就是财富；它不代表价值，它是价值的等价物。”(列特隆《就价值、流通、工业、国内外贸易论社会利益》第910页）“当我们考察价值的概念时，物本身只是被看作一种符号，物不是被当作物本身，而是被当作它所值的东西。”〈黑格尔《法哲学》第100页）法学家早在经济学家以前，就提出货币是单纯符号、贵金属价值纯属想象的观念；这些法学家这样做是为了向王权献媚，他们在整个中世纪时期，一直以罗马帝国的传统和罗马法全书【53】中的货币概念，作为国王伪造铸币的权利的依据。这些法学家的好学生，华洛瓦王朝的菲力浦在1346年的一项法令中说：“无论何人不得亦不应怀疑，唯朕有权……处理铸币事宜，决定铸币之制造、形状与储存，颁布有关铸币之命令，并遵照符合朕意之办法及价格将铸币付诸流通。”货币价值由皇帝下令规定，是罗马法的定则。当时明文禁止把货币当作商品。“任何人均不得购买货币，货币为公共使用而设，不应成为商品。”对于这个问题，卓·弗·帕尼尼《试论物品的合理价格》（库斯托第编《意大利政治经济学名家文集》现代部分，1751年版第2卷）做了很好的说明。特别在这一著作的第二部分，帕尼尼同法学家先生们展开了论战。","language":"中文","translation":false},{"id":"capital-3-36","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"【53】 罗马法全书——拉丁文Digesta，即汇编。它是罗马民法法典的最重要的一部分，其中收集了罗马法学家著作的残篇。它是代表奴隶主利益的。罗马法全书是在533年査士丁尼帝执政时发表的。——第109页。","language":"中文","translation":false},{"id":"capital-3-37","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[48] “假定有人从秘鲁地下获得一盎斯银并带到伦敦来，他所用的时间和他生产一蒲式耳谷物所需要的时间相等，那末，前者就是后者的自然价格；假定现在由于开采更富的新矿，获得两盎斯银象以前获得一盎斯银花费一样多，那末在其他条件相同的情况下，现在一蒲式耳谷物值10先令的价格，就和它以前值5先令的价格一样便宜。“(威廉·配第《赋税论》1667年伦敦版第31页）","language":"中文","translation":false},{"id":"capital-3-38","author":"马克思","title":"资本论·第一卷","location":"第二章 交换过程","page":3,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/02.htm","text":"[49] 罗雪尔教授先生教训我们说：“错误的货币定义可以分为两大类：一类认为货币比商品多一些，一类认为货币比商品少一些。”接着他杂乱无章地开列了一份关于货币性质的著作的目录，从这个书目丝毫也不能了解真实的货币学说史。最后他训诫说:“此外，不能否认，大部分现代国民经济学家对于使货币不同于其他商品的那些特性〈莫非指比商品多一些或少一些吗？〉是注意得不够的……就这一点说，加尼耳之流的半重商主义的反动就不是完全没有根据的了。”（威廉·罗雪尔《国民经济学原理》1858年第3版第207—210页）多一些——少一些——不够——就这一点说——不是完全！这算什么定义！而罗雪尔先生还谦逊地把这类教授式的折衷主义空谈命名为政治经济学的“解剖生理学的方法”！不过有一个发现要归功于他，那就是：货币是“一种快意的商品”。","language":"中文","translation":false},{"id":"capital-4-1","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-4-2","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"为了简单起见，我在本书各处都假定金是货币商品。","language":"中文","translation":false},{"id":"capital-4-3","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"金的第一个职能是为商品世界提供表现价值的材料，或者说，是把商品价值表现为同名的量，使它们在质的方面相同，在量的方面可以比较。因此，金执行一般的价值尺度的职能，并且首先只是由于这个职能，金这个特殊的等价商品才成为货币。","language":"中文","translation":false},{"id":"capital-4-4","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品并不是由于有了货币才可以通约。恰恰相反。因为一切商品作为价值都是物化的人类劳动，它们本身就可以通约，所以它们能共同用一个特殊的商品来计量自己的价值，这样，这个特殊的商品就成为它们共同的价值尺度或货币。货币作为价值尺度，是商品内在的价值尺度即劳动时间的必然表现形式。[50]","language":"中文","translation":false},{"id":"capital-4-5","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品在金上的价值表现——x量商品A=y量货币商品——是商品的货币形式或它的价格。现在，要用社会公认的形式表现铁的价值，只要有1吨铁=2盎斯金这样一个等式就够了。这个等式不需要再同其他商品的价值等式排成一个行列，因为金这个等价商品已经具有货币的性质。因此，现在商品的一般相对价值形式又具有商品最初的即简单的或个别的相对价值形式的样子。另一方面，扩大的相对价值表现，或相对价值表现的无限的系列，成为货币商品所特有的相对价值形式。而这个系列现在已经在商品价格中社会地提供了。把一份行情表上的价目倒过来读，就可以看出货币的价值量表现在各式各样的商品上。然而货币并没有价格。货币要参加其他商品的这个统一的相对价值形式，就必须把自己当作自己的等价物。","language":"中文","translation":false},{"id":"capital-4-6","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品的价格或货币形式，同商品的所有价值形式一样，是一种与商品的可以捉摸的实在的物体形式不同的，因而只是观念的或想象的形式。铁、麻布、小麦等等的价值虽然看不见，但是存在于这些物的本身中；它们的价值通过它们同金相等，同金发生一种可以说只是在它们头脑中作祟的关系而表现出来。因此，商品监护人必须把自己的舌头塞进它们的脑袋里，或者给它们挂上一张纸条，以便向外界表明它们的价格[51]。既然商品在金上的价值表现是观念的，所以要表现商品的价值，也可以仅仅用想象的或观念的金。每一个商品监护人都知道：当他给予商品价值以价格形式或想象的金的形式时，他远没有把自己的商品转化为金，而为了用金估量数百万的商品价值，他不需要丝毫实在的金。因此，货币在执行价值尺度的职能时，只是想象的或观念的货币。这种情况引起了种种最荒谬的学说[52]。尽管只是想象的货币执行价值尺度的职能，但是价格完全取决于实在的货币材料。例如，一吨铁所包含的价值，即人类劳动量，是通过想象中包含等量劳动的货币商品量表现出来的。所以，一吨铁的价值，根据充当价值尺度的是金、银还是铜，就具有完全不同的价格表现，或者说，在金、银或铜的完全不同的数量中表现出来。","language":"中文","translation":false},{"id":"capital-4-7","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"因此，如果两种不同的商品，例如金和银，同时充当价值尺度，一切商品就会有两种不同的价格表现，即金价格和银价格；只要金和银的价值比例不变，例如总是1∶15，那末这两种价格就可以安然并存。但是，这种价值比例的任何变动，都会扰乱商品的金价格和银价格之间的比例，这就在事实上证明，价值尺度的二重化是同价值尺度的职能相矛盾的。[53]","language":"中文","translation":false},{"id":"capital-4-8","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"凡是价格已经确定的商品都表现为这样的形式：a量商品A=x量金；b量商品B=z量金；c量商品C=y量金，等等，在这里，a，b，c代表商品A，B，C的一定量，x，z，y代表金的一定量。这样，商品价值就转化为大小不同的想象的金量，就是说，尽管商品体五花八门，商品价值都变为同名的量，即金量。各种商品的价值作为不同的金量互相比较，互相计量，这样在技术上就有必要把某一固定的金量作为商品价值的计量单位。这个计量单位本身通过进一步分成等分而发展成为标准。金、银、铜在变成货币以前，在它们的金属重量中就有这种标准，例如，以磅为计量单位，磅一方面分成盎斯等等，另一方面又合成英吨等等[54]。因此，在一切金属的流通中，原有的重量标准的名称，也是最初的货币标准或价格标准的名称。","language":"中文","translation":false},{"id":"capital-4-9","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"作为价值尺度和作为价格标准，货币执行着两种完全不同的职能。作为人类劳动的社会化身，它是价值尺度；作为规定的金属重量，它是价格标准。作为价值尺度，它用来使形形色色的商品的价值变为价格，变为想象的金量；作为价格标准，它计量这些金量。价值尺度是用来计量作为价值的商品，相反，价格标准是用一个金量计量各种不同的金量，而不是用一个金量的重量计量另一个金量的价值。要使金充当价格标准，必须把一定重量的金固定为计量单位。在这里，正如在其他一切同名量的尺度规定中一样，尺度比例的固定性有决定的意义。因此，充当计量单位的那个金量越是不变，价格标准就越是能更好地执行自己的职能。金能够充当价值尺度，只是因为它本身是劳动产品，因而是潜在可变的价值。[55]","language":"中文","translation":false},{"id":"capital-4-10","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"首先很明显，金的价值变动丝毫不会妨碍金执行价格标准的职能。不论金的价值怎样变动，不同的金量之间的价值比例总是不变。哪怕金的价值跌落1000％，12盎斯金的价值仍然是1盎斯金的12倍，在价格上问题只在于不同金量彼此之间的比例。另一方面，1盎斯金决不会因为它的价值涨落而改变它的重量，也不会因而改变它的等分的重量，所以，不论金的价值怎样变动，金作为固定的价格标准总是起同样的作用。","language":"中文","translation":false},{"id":"capital-4-11","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"金的价值变动也不会妨碍金执行价值尺度的职能。这种变动会同时影响一切商品，因此，在其他条件相同的情况下，它们相互间的相对价值不会改变，尽管这些价值这时都是在比过去高或低的金价格中表现出来。","language":"中文","translation":false},{"id":"capital-4-12","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"同某一商品的价值由任何别一个商品的使用价值来表现一样，商品用金来估价也只是以下面一点为前提：在一定时间内生产一定量的金要耗费一定量的劳动。至于商品价格的变动，前面阐述的简单相对价值表现的规律也是适用的。","language":"中文","translation":false},{"id":"capital-4-13","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品价格，只有在货币价值不变、商品价值提高时，或在商品价值不变、货币价值降低时，才会普遍提高。反之，商品价格，只有在货币价值不变、商品价值降低时，或在商品价值不变、货币价值提高时，才会普遍降低。由此决不能得出结论说，货币价值提高，商品价格必定相应降低，货币价值降低，商品价格必定相应提高。这只适用于价值不变的商品。例如，某些商品的价值和货币的价值同时按同一比例提高，这些商品的价格就不会改变。如果这些商品的价值比货币价值增加得慢些或者增加得快些，那末，这些商品的价格的降低或提高，就由这些商品的价值变动和货币的价值变动之间的差额来决定。余此类推。","language":"中文","translation":false},{"id":"capital-4-14","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"现在我们回过来考察价格形式。","language":"中文","translation":false},{"id":"capital-4-15","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"由于各种原因，金属重量的货币名称同它原来的重量名称逐渐分离。其中在历史上有决定意义的是下列原因：1、外国货币流入较不发达的民族，例如在古罗马，银币和金币最初是作为外国商品流通的。这些外国货币的名称与本地的重量名称是不同的。2、随着财富的增长，不大贵重的金属逐渐为比较贵重的金属所排挤，失去价值尺度的职能。铜为银所排挤，银为金所排挤，尽管这个顺序是同诗人想象的年代顺序【58】相抵触的。[56]例如，镑原来是真正一磅重的银的货币名称。当金排挤作为价值尺度的银时，这个名称依照金和银的价值比例，可能用来称呼1/15磅的金等等。现在，作为货币名称的镑就和作为金的通常重量名称的磅分开了[57]。3、几百年来君主不断伪造货币，使铸币原来的重量实际上只剩下一个名称。[58]","language":"中文","translation":false},{"id":"capital-4-16","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"这些历史过程使金属重量的货币名称同它的通常重量名称的分离成为民族的习惯。货币标准一方面纯粹是约定俗成的，另一方面必须是普遍通用的。因此，最后就由法律来规定了。一定重量的贵金属，如一盎斯金，由官方分成若干等分，取得法定的教名，如镑、塔勒等等。这种等分成为真正的货币计量单位后，又分为新的等分，并具有法定的教名，如先令、便士等等。[59]一定的金属重量仍旧是金属货币的标准。改变的只是分法和名称。[60]","language":"中文","translation":false},{"id":"capital-4-17","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"因此，价格或商品价值在观念上转化成的金量，现在用金标准的货币名称或法定的计算名称来表现了。英国人不说1夸特小麦等于1盎斯金，而说等于3镑17先令10 1/2便士。这样，商品就用自己的货币名称说明自己值多少，每当需要把一物当作价值，从而用货币形式来确定时，货币就充当计算货币。","language":"中文","translation":false},{"id":"capital-4-18","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"物的名称对于物的本性来说完全是外在的。即使我知道一个人的名字叫雅各，我对他还是一点不了解。同样，在镑、塔勒、法郎、杜卡特等货币名称上，价值关系的任何痕迹都消失了。由于货币名称既表示商品价值，同时又表示某一金属重量即货币标准的等分，对这些神秘记号的秘密含意的了解就更加混乱了[61]。另一方面，价值和商品世界的形形色色的物体不同，必然发展为这种没有概念的物的而又纯粹是社会的形式。[62]","language":"中文","translation":false},{"id":"capital-4-19","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"价格是物化在商品内的劳动的货币名称。因此，商品同称为它的价格的那个货币量等价，不过是同义反复，因为一个商品的相对价值表现总是两个商品等价的表现[63]。虽然价格作为商品价值量的指数，是商品同货币的交换比例的指数，但不能由此反过来说，商品同货币的交换比例的指数必然是商品价值量的指数。假定等量的社会必要劳动表现为1夸特小麦和2镑(约1/2盎斯金)。2镑是1夸特小麦的价值量的货币表现或1夸特小麦的价格。如果情况许可把1夸特小麦标价为3镑，或者迫使把它标价为1镑，那末作为小麦的价值量的表现，1镑是太少了，3镑是太多了。但是1镑和3镑都是小麦的价格，因为第一，它们是小麦的价值形式，是货币；第二，它们是小麦同货币的交换比例的指数。在生产条件不变或者劳动生产力不变的情况下，再生产1夸特小麦仍需要耗费同样多的社会劳动时间。这一事实既不以小麦生产者的意志为转移，也不以其他商品所有者的意志为转移。因而，商品的价值量表现着一种必然的、商品形成过程内在的同社会劳动时间的关系。随着价值量转化为价格，这种必然的关系就表现为商品同在它之外存在的货币商品的交换比例。这种交换比例既可以表现商品的价值量，也可以表现比它大或小的量，在一定条件下，商品就是按这种较大或较小的量来让渡的。可见，价格和价值量之间的量的不一致的可能性，或者价格偏离价值量的可能性，已经包含在价格形式本身中。但这并不是这种形式的缺点，相反地，却使这种形式成为这样一种生产方式的适当形式，在这种生产方式下，规则只能作为没有规则性的盲目起作用的平均数规律来为自己开辟道路。","language":"中文","translation":false},{"id":"capital-4-20","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"价格形式不仅可能引起价值量和价格之间即价值量和它的货币表现之间的量的不一致，而且能够包藏一个质的矛盾，以致货币虽然只是商品的价值形式，但价格可以完全不是价值的表现。有些东西本身并不是商品，例如良心、名誉等等，但是也可以被它们的所有者出卖以换取金钱，并通过它们的价格，取得商品形式。因此，没有价值的东西在形式上可以具有价格。在这里，价格表现是虚幻的，就象数学中的某些数量一样。另一方面，虚幻的价格形式——如未开垦的土地的价格，这种土地没有价值，因为没有人类劳动物化在里面——又能掩盖实在的价值关系或由此派生的关系。","language":"中文","translation":false},{"id":"capital-4-21","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"同所有相对价值形式一样，价格通过下列方式来表现一种商品如一吨铁的价值：一定量的等价物，如一盎斯金，能直接与铁交换。但决不能反过来说，铁也能直接与金交换。因此，商品要实际上起交换价值的作用，就必须抛弃自己的自然形体，从只是想象的金变为实在的金，诚然，商品实现这种变体，同黑格尔的“概念”实现由必然到自由的过渡相比，同龙虾脱壳相比，同教父圣热罗尼莫[64]解脱原罪相比，是“更为困难的”。商品除了有例如铁这种实在的形态以外，还可以在价格上有观念的价值形态或想象的金的形态，但它不能同时既是实在的铁，又是实在的金。要规定商品的价格，只需要使想象的金同商品相等。但商品必须为金所代替，它才能对它的所有者起一般等价物的作用。例如，铁的所有者遇见某种享乐商品的所有者，他向后者说铁的价格已经是货币形式了，后者就会象圣彼得在天堂听了但丁讲述信仰要义之后那样回答说：","language":"中文","translation":false},{"id":"capital-4-22","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"但告诉我，你钱袋里有吗？”【63】","language":"中文","translation":false},{"id":"capital-4-23","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"价格形式包含着商品为取得货币而让渡的可能性和这种让渡的必要性。另一方面，金所以充当观念的价值尺度，只是因为它在交换过程中已作为货币商品流通。因此，在观念的价值尺度中隐藏着坚硬的货币。","language":"中文","translation":false},{"id":"capital-4-24","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"我们看到，商品的交换过程包含着矛盾的和互相排斥的关系。商品的发展并没有扬弃这些矛盾，而是创造这些矛盾能在其中运动的形式。一般说来，这就是解决实际矛盾的方法。例如，一个物体不断落向另一个物体而又不断离开这一物体，这是一个矛盾。椭圆便是这个矛盾借以实现和解决的运动形式之一。","language":"中文","translation":false},{"id":"capital-4-25","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"交换过程使商品从把它们当作非使用价值的人手里转到把它们当作使用价值的人手里，就这一点说，这个过程是一种社会的物质变换。一种有用劳动方式的产品代替另一种有用劳动方式的产品。商品一到它充当使用价值的地方，就从商品交换领域转入消费领域。在这里，我们感兴趣的只是商品交换领域。因此，我们只是从形式方面考察全部过程，就是说，只是考察为社会的物质变换作媒介的商品形式变换或商品形态变化。","language":"中文","translation":false},{"id":"capital-4-26","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"人们对这种形式变换之所以理解得很差，除了对价值概念本身不清楚以外，是因为商品的每次形式变换都是通过两种商品即普通商品和货币商品的交换实现的。如果我们只注意商品和金的交换这个物质因素，那就会恰恰看不到应该看到的东西，即形式发生了怎样的变化。我们就会看不到：金当作单纯的商品并不是货币，而其他的商品通过它们的价格才把金当作它们自己的货币形态。","language":"中文","translation":false},{"id":"capital-4-27","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品首先是没有镀金，没有蘸糖，以本来面目进入交换过程的。交换过程造成了商品分为商品和货币这种二重化，即造成了商品得以表现自己的使用价值和价值之间的内在对立的一种外部对立。在这种外部对立中，作为使用价值的商品同作为交换价值的货币对立着。另一方面，对立的双方都是商品，也就是说，都是使用价值和价值的统一。但这种差别的统一按相反的方向表现在两极中的每一极上，并且由此同时表现出它们的相互关系。商品实际上是使用价值，它的价值存在只是观念地表现在价格上，价格使商品同对立着的金发生关系，把金当作自己的实际的价值形态。反之，金这种物质只是充当价值化身，充当货币。因此金实际上是交换价值。金的使用价值只是观念地表现在相对价值表现的系列上，金通过这个相对价值表现的系列，同对立着的商品发生关系，把它们当作自己的实际使用形态的总和。商品的这种对立的形式就是它们的交换过程的实际的运动形式。","language":"中文","translation":false},{"id":"capital-4-28","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"现在，我们随同任何一个商品所有者，比如我们的老朋友织麻布者，到交换过程的舞台上去，到商品市场上去。他的商品即20码麻布的价格是规定了的。它的价格是2镑。他把麻布换成2镑，接着，这个守旧的人又用这2镑换一本价格相等的家庭用的圣经。麻布——对于他来说只是商品，只是价值承担者——被转让出去，换取了金，麻布的价值形态，然后又从这个价值形态被让渡出去，换取了另一种商品圣经，而圣经就作为使用物品来到织布者的家里，满足他受教化的需要。可见，商品交换过程是在两个互相对立、互为补充的形态变化中完成的：从商品转化为货币，又从货币转化为商品[65]。商品形态变化的两个因素同时就是商品所有者的两种行为，一种是卖，把商品换成货币，一种是买，把货币换成商品，这两种行为的统一就是：为买而卖。","language":"中文","translation":false},{"id":"capital-4-29","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"如果织麻布者看看交易的最终结果，那末现在他占有的不是麻布，而是圣经，不是他原来的商品，而是另外一种价值相等而用处不同的商品。他用同样的方法取得他的其他生活资料和生产资料。在他看来，全部过程不过是他的劳动产品同别人的劳动产品进行交换的媒介，是产品交换的媒介。","language":"中文","translation":false},{"id":"capital-4-30","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"因此，商品的交换过程是在下列的形式变换中完成的：","language":"中文","translation":false},{"id":"capital-4-31","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"从物质内容来说，这个运动是Ｗ—Ｗ，是商品换商品，是社会劳动的物质变换，这种物质变换的结果一经达到，过程本身也就结束。","language":"中文","translation":false},{"id":"capital-4-32","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"Ｗ—Ｇ。商品的第一形态变化或卖。商品价值从商品体跳到金体上，象我在别处说过的【64】，是商品的惊险的跳跃。这个跳跃如果不成功，摔坏的不是商品，但一定是商品所有者。社会分工使商品所有者的劳动成为单方面的，又使他的需要成为多方面的。正因为这样，他的产品对他来说仅仅是交换价值。这个产品只有通过货币，才取得一般的社会公认的等价形式，而货币又在别人的口袋里。为了把货币吸引出来，商品首先应当对于货币所有者是使用价值，就是说，用在商品上的劳动应当是以社会有用的形式耗费的，或者说，应当证明自己是社会分工的一部分。但分工是自然形成的生产机体，它的纤维在商品生产者的背后交织在一起，而且继续交织下去。商品可能是一种新的劳动方式的产品，它声称要去满足一种新产生的需要，或者想靠它自己去唤起一种需要。一种特殊的劳动操作，昨天还是同一个商品生产者许多职能中的一种职能，今天就可能脱离这种联系，独立起来，从而把它的局部产品当作独立商品送到市场上去。这个分离过程的条件可能已经成熟，或者可能尚未成熟。某种产品今天满足一种社会需要，明天就可能全部地或部分地被一种类似的产品排挤掉。即使某种劳动，例如我们这位织麻布者的劳动，是社会分工的特许的一部分，这也决不能保证他的20码麻布就有使用价值。社会对麻布的需要，象对其他各种东西的需要一样，是有限度的，如果他的竞争者已经满足了这种需要，我们这位朋友的产品就成为多余的、过剩的，因而是无用的了。接受赠马，不看岁口（德国成语，意思是；接受礼物，不会计较好坏。——译者注），但是我们这位织麻布者决不是到市场去送礼的。我们就假定他的产品证明自己有使用价值，因而商品会把货币吸引出来。但现在要问：它能吸引多少货币呢？当然，答案已经由商品的价格即商品价值量的指数预示了。我们把商品所有者可能发生的纯粹主观的计算错误撇开，因为这种错误在市场上马上可以得到客观的纠正。假定他耗费在他的产品上的只是平均社会必要劳动时间。因此，商品的价格只是物化在商品中的社会劳动量的货币名称。但是，织麻布业的以往可靠的生产条件，没有经过我们这位织麻布者的许可而在他的背后发生了变化。同样多的劳动时间，昨天还确实是生产一码麻布的社会必要劳动时间，今天就不是了。货币所有者会非常热心地用我们这位朋友的各个竞争者定出的价格来说明这一点。真是不幸，世上竟有很多织麻布者。最后，假定市场上的每一块麻布都只包含社会必要劳动时间。即使这样，这些麻布的总数仍然可能包含耗费过多的劳动时间。如果市场的胃口不能以每码2先令的正常价格吞下麻布的总量，这就证明，在全部社会劳动时间中，以织麻布的形式耗费的时间太多了。其结果就象每一个织布者花在他个人的产品上的时间都超过了社会必要劳动时间一样。这正象俗话所说：“一起捉住，一起绞死。”（德国谚语，意思是：有祸同当。——译者注）在市场上，全部麻布只是当作一个商品，每一块麻布只是当作这个商品的相应部分。事实上，每一码的价值也只是同种人类劳动的同一的社会规定的量的化身。①","language":"中文","translation":false},{"id":"capital-4-33","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"① 马克思在1878年11月28日给《资本论》俄译者尼·弗·丹尼尔逊的信中，提出把这句话改为：“事实上，每一码的价值也只是耗费在麻布总量上的社会劳动量的一部分的化身”。——编者注","language":"中文","translation":false},{"id":"capital-4-34","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"我们看到，商品爱货币，但是“真爱情的道路决不是平坦的”【65】。把自己的“分散的肢体”【66】表现为分工体系的社会生产机体，它的量的构成，也象它的质的构成一样，是自发地偶然地形成的。所以我们的商品所有者发现：分工使他们成为独立的私人生产者，同时又使社会生产过程以及他们在这个过程中的关系不受他们自己支配；人与人的互相独立为物与物的全面依赖的体系所补充。","language":"中文","translation":false},{"id":"capital-4-35","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"分工使劳动产品转化为商品，因而使它转化为货币成为必然的事情。同时，分工使这种转化能否成功成为偶然的事情。但是在这里应当纯粹地考察现象，因此假定这种现象是正常进行的。其实，只要这种现象发生，就是说，只要商品不是卖不出去，就总会发生商品的形式变换，尽管在这种形式变换中，实体——价值量——可能在不正常的场合亏损或增加。","language":"中文","translation":false},{"id":"capital-4-36","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"对一个商品所有者来说，金代替了他的商品，对另一个商品所有者来说，商品代替了他的金。可以感觉到的现象是商品和金，即20码麻布和2镑转手了，换位了，就是说，交换了。但是商品同什么交换呢？同它自己的一般价值形态交换。金又同什么交换呢？同它的使用价值的特殊形态交换。金为什么作为货币同麻布对立呢？因为麻布的价格2镑或它的货币名称，已经使麻布把金当作货币。原来的商品形式的转换是通过商品的让渡完成的，就是说，是在商品的使用价值确实把商品价格中只是想象的金吸引出来的时刻完成的。因此，商品价格的实现，或商品的仅仅是观念的价值形式的实现，同时就是货币的仅仅是观念的使用价值的实现。商品转化为货币，同时就是货币转化为商品。这一个过程是两方面的：从商品所有者这一极看，是卖；从货币所有者这另一极看，是买。或者说，卖就是买，Ｗ—Ｇ同时就是Ｇ—Ｗ。[66]","language":"中文","translation":false},{"id":"capital-4-37","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"到这里，我们还只知道人与人之间的一种经济关系，即商品所有者之间的关系，在这种关系中，商品所有者只是由于让出自己的劳动产品，才占有别人的劳动产品。因此，一个商品所有者所以能够作为货币所有者同另一个商品所有者对立，或者是因为他的劳动产品天然具有货币形式，是货币材料，是金等等；或者是因为他自己的商品已经蜕皮，已经蜕掉它原来的使用形式。金要执行货币的职能，自然就必须在某个地点进入商品市场。这个地点就在金的产地，在那里，金作为直接的劳动产品与另一种价值相同的劳动产品相交换。但是，从这个时候起，它就总是代表已经实现了的商品价格[67]。撇开金在产地同商品的交换不说，金在每个商品所有者手里都是他所让渡的商品的转换形态，都是卖的产物，或商品第一形态变化Ｗ—Ｇ的产物[68]。金能够成为观念的货币或价值尺度，是因为一切商品都用金来计量它们的价值，从而使金成为它们的使用形态的想象的对立面，成为它们的价值形态。金能够成为实在的货币，是因为商品通过它们的全面让渡使金成为它们的实际转换或转化的使用形态，从而使金成为它们的实际的价值形态。商品在它的价值形态上蜕掉了它自然形成的使用价值的一切痕迹，蜕掉了创造它的那种特殊有用劳动的一切痕迹，蛹化为无差别的人类劳动的同样的社会化身。因此，从货币上看不出它是由哪种商品转化来的。在货币形式上，一种商品和另一种商品完全一样。因此，货币可以是粪土，虽然粪土并不是货币。假定我们的织麻布者让渡他的商品而取得的两块金是一夸特小麦的转化形态。卖麻布Ｗ—Ｇ同时就是买麻布Ｇ—Ｗ。作为卖麻布，这个过程开始了一个运动，而这个运动是以卖的反面，以买圣经结束的；作为买麻布，这个过程结束了一个运动，而这个运动是以买的反面，以卖小麦开始的。Ｗ—Ｇ(麻布—货币)，即Ｗ—Ｇ—Ｗ(麻布—货币—圣经)这一运动的始段，同时就是Ｇ—Ｗ(货币—麻布)，即另一运动Ｗ—Ｇ—Ｗ(小麦—货币—麻布)的终段。一个商品的第一形态变化，即从商品形式变成货币，同时总是另一个商品的相反的第二形态变化，即从货币形式又变成商品。[69]","language":"中文","translation":false},{"id":"capital-4-38","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"Ｇ—Ｗ。商品的第二形态变化，或最终的形态变化：买。——货币是其他一切商品的转换形态，或者说，是它们普遍让渡的产物，因此是绝对可以让渡的商品。货币把一切价格倒过来读，从而把自己反映在一切商品体上，即为货币本身转化为商品而献身的材料上。同时，价格，即商品向货币送去的秋波，表明货币可以转化的限度，即指明货币本身的量。既然商品在变成货币后就消失了，所以，从货币上就看不出它究竟怎样落到货币所有者的手中，究竟是由什么东西转化来的。货币没有臭味【68】，无论它从哪里来。一方面，它代表已经卖掉的商品，另一方面，它代表可以买到的商品。[70]","language":"中文","translation":false},{"id":"capital-4-39","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"Ｇ—Ｗ，即买，同时就是卖，即Ｗ—Ｇ；因此，一个商品的后一形态变化，同时就是另一商品的前一形态变化。对我们的织麻布者来说，他的商品的生命旅程是以他把2镑又转化为圣经而结束的。卖圣经的人则把从织麻布者那里得到的2镑换成烧酒。Ｇ—Ｗ，即Ｗ—Ｇ—Ｗ(麻布—货币—圣经)的终段，同时就是Ｗ—Ｇ，即Ｗ—Ｇ—Ｗ(圣经—货币—烧酒)的始段。因为商品生产者只提供单方面的产品，所以他常常是大批地卖；而他的多方面的需要，又迫使他不断地把已经实现的价格，或得到的全部货币额，分散在许多次买上。卖一次就要买许多次各种各样的商品。这样，一种商品的最终的形态变化，就是许多其他商品的第一形态变化的总和。","language":"中文","translation":false},{"id":"capital-4-40","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"如果我们来考察一个商品例如麻布的总形态变化，那末我们首先就会看到，这个形态变化由两个互相对立、互为补充的运动Ｗ—Ｇ和Ｇ—Ｗ组成。商品的这两个对立的转化是通过商品所有者的两个对立的社会过程完成的，并反映在商品所有者充当的两种对立的经济角色上。作为卖的当事人，他是卖者，作为买的当事人，他是买者。但是，在商品的每一次转化中，商品的两种形式即商品形式和货币形式同时存在着，只不过是在对立的两极上，所以，对同一个商品所有者来说，当他是卖者时，有一个买者和他对立着，当他是买者时，有一个卖者和他对立着。正象同一个商品要依次经过两个相反的转化，由商品转化为货币，由货币转化为商品一样，同一个商品所有者也要由扮演卖者改为扮演买者。可见，这两种角色不是固定的，而是在商品流通中经常由人们交替扮演的。","language":"中文","translation":false},{"id":"capital-4-41","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"一个商品的总形态变化，在其最简单的形式上，包含四个极和三个登场人物。最先，与商品对立着的是作为它的价值形态的货币，而后者在彼岸，在别人的口袋里，具有物的坚硬的现实性。因此，与商品所有者对立着的是货币所有者。商品一变成货币，货币就成为商品的转瞬即逝的等价形式，这个等价形式的使用价值或内容在此岸，在其他的商品体中存在着。作为商品第一个转化的终点的货币，同时是第二个转化的起点。可见，在第一幕是卖者，在第二幕就成了买者，这里又有第三个商品所有者作为卖者同他对立着。[71]","language":"中文","translation":false},{"id":"capital-4-42","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品形态变化的两个相反的运动阶段组成一个循环：商品形式，商品形式的抛弃，商品形式的复归。当然，在这里，商品本身具有对立的规定。对它的所有者来说，它在起点是非使用价值，在终点是使用价值。同样，货币先表现为商品转化成的固定的价值结晶，然后又作为商品的单纯等价形式而消失。","language":"中文","translation":false},{"id":"capital-4-43","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"组成一个商品的循环的两个形态变化，同时是其他两个商品的相反的局部形态变化。同一个商品(麻布)开始它自己的形态变化的系列，又结束另一个商品(小麦)的总形态变化。商品在它的第一个转化中，即在出卖时，一身兼有这两种作用。而当它作为金蛹结束自己的生涯的时候，它同时又结束第三个商品的第一形态变化。可见，每个商品的形态变化系列所形成的循环，同其他商品的循环不可分割地交错在一起。这全部过程就表现为商品流通。","language":"中文","translation":false},{"id":"capital-4-44","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品流通不仅在形式上，而且在实质上不同于直接的产品交换。让我们回顾一下上面说过的过程。织麻布者确实拿麻布换了圣经，拿自己的商品换了别人的商品。但这种现象只有对于他才是真实的。宁愿要生暖的饮料而不要冰冷的圣物的圣经出卖者，不会想到麻布换他的圣经，正象织麻布者不会想到小麦换他的麻布一样，如此等等。B的商品替换了A的商品，但A和B并不是互相交换自己的商品。A同B彼此购买的事，实际上也可能发生，但这种特殊关系决不是由商品流通的一般条件决定的。在这里，一方面，我们看到，商品交换怎样打破了直接的产品交换的个人的和地方的限制，发展了人类劳动的物质变换。另一方面，又有整整一系列不受当事人控制的天然的社会联系发展起来。织布者能卖出麻布，只是因为农民已经卖了小麦；嗜酒者能卖出圣经，只是因为织布者已经卖了麻布；酿酒者能卖出酿造之水，只是因为另一个人已经卖了永生之水，如此等等。","language":"中文","translation":false},{"id":"capital-4-45","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"因此，与直接的产品交换不同，流通过程在使用价值换位和转手之后并没有结束。货币并不因为它最终从一个商品的形态变化系列中退出来而消失。它不断地沉淀在商品空出来的流通位置上。例如，在麻布的总形态变化即麻布—货币—圣经中，先是麻布退出流通，货币补上它的位置，然后是圣经退出流通，货币又补上圣经的位置。一个商品由另一个商品代替，而货币商品留在第三人手中。[72]流通不断地把货币象汗一样渗出来。","language":"中文","translation":false},{"id":"capital-4-46","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"有一种最愚蠢不过的教条：商品流通必然造成买和卖的平衡，因为每一次卖同时就是买，反过来也是一样。如果这是指实际完成的卖的次数等于买的次数，那是毫无意义的同义反复。但这种教条是要证明，卖者会把自己的买者带到市场上来。作为两极对立的两个人即商品所有者和货币所有者的相互关系来看，卖和买是同一个行为。但作为同一个人的活动来看，卖和买是两极对立的两个行为。因此，卖和买的同一性包含着这样的意思：如果商品被投入流通的炼金炉，没有炼出货币，没有被商品所有者卖掉，也就是没有被货币所有者买去，商品就会变成无用的东西。这种同一性还包含这样的意思：如果这个过程成功，它就会形成商品的一个休止点，形成商品生命中的一个时期，而这个时期可长可短。既然商品的第一形态变化是卖又是买，这个局部过程同时就是一个独立的过程。买者有商品，卖者有货币，也就是有一种不管早一些或晚一些再进入市场都保持着能够流通的形式的商品。没有人买，也就没有人能卖。但谁也不会因为自己已经卖，就得马上买。流通所以能够打破产品交换的时间、空间和个人的限制，正是因为它把这里存在的换出自己的劳动产品和换进别人的劳动产品这二者之间的直接的同一性，分裂成卖和买这二者之间的对立。说互相对立的独立过程形成内部的统一，那也就是说，它们的内部统一是运动于外部的对立中。当内部不独立(因为互相补充)的过程的外部独立化达到一定程度时，统一就要强制地通过危机显示出来。商品内在的使用价值和价值的对立，私人劳动同时必须表现为直接社会劳动的对立，特殊的具体的劳动同时只是当作抽象的一般的劳动的对立，物的人格化和人格的物化的对立，——这种内在的矛盾在商品形态变化的对立中取得了发展的运动形式。因此，这些形式包含着危机的可能性，但仅仅是可能性。这种可能性要发展为现实，必须有整整一系列的关系，从简单商品流通的观点来看，这些关系还根本不存在。[73]","language":"中文","translation":false},{"id":"capital-4-47","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"作为商品流通的媒介，货币取得了流通手段的职能。","language":"中文","translation":false},{"id":"capital-4-48","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"劳动产品的物质变换借以完成的形式变换Ｗ—Ｇ—Ｗ，要求同一个价值作为商品成为过程的起点，然后又作为商品回到这一点。因此，商品的这种运动就是循环。另一方面，这个形式又排斥货币的循环。其结果是货币不断地离开它的起点，不再回来。只要卖者还紧紧握着他的商品的转化形态即货币，这个商品就仍然处在第一形态变化的阶段，或者说，只通过了流通的前半段。如果为买而卖的过程已经完成，货币就会再从它原来的所有者手里离开。当然，如果织麻布者买了圣经之后再卖麻布，货币就会再回到他的手里。但货币返回来，并不是由于上次那20码麻布的流通，相反地，那次流通已经使货币从织麻布者的手里离开，而到了圣经出售者的手里。货币返回来，只是由于新的商品又更新了或重复了同样的流通过程，并且这次的结果和上次相同。因此，商品流通直接赋予货币的运动形式，就是货币不断地离开起点，就是货币从一个商品所有者手里转到另一个商品所有者手里，或者说，就是货币流通（currency, cours de la monnaie）。","language":"中文","translation":false},{"id":"capital-4-49","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"货币流通表示同一个过程的不断的、单调的重复。商品总是在卖者方面，货币是作为购买手段在买者方面。货币作为购买手段执行职能，是在它实现商品的价格的时候。而货币在实现商品的价格的时候，把商品从卖者手里转到买者手里，同时自己也从买者手里离开，到了卖者手里，以便再去同另一种商品重复同样的过程。货币运动的单方面形式来源于商品运动的两方面形式，这一点是被掩盖着的。商品流通的性质本身造成了相反的假象。商品的第一形态变化表现出来的不仅是货币的运动，而且是商品本身的运动；而商品的第二形态变化表现出来的只是货币的运动。商品在流通的前半段同货币换了位置。同时，商品的使用形态便离开流通，进入消费。[74]它的位置由它的价值形态或货币化装所占据。商品不再是包在它自己的天然外皮中，而是包在金外皮中来通过流通的后半段。因此，运动的连续性完全落在货币方面；这个运动对商品来说包含两个对立的过程，但作为货币本身的运动却总是包含同一个过程，就是货币同一个又一个的商品变换位置。因此，商品流通的结果，即一种商品被另一种商品所代替，似乎并不是由商品本身的形式变换引起的，而是由货币作为流通手段的职能引起的，似乎正是作为流通手段的货币使本身不能运动的商品流通起来，使商品从把它们当作非使用价值的人手里转到把它们当作使用价值的人手里，并且总是朝着同货币本身运动相反的方向运动。货币不断使商品离开流通领域，同时不断去占据商品在流通中的位置，从而不断离开自己的起点。因此，虽然货币运动只是商品流通的表现，但看起来商品流通反而只是货币运动的结果。[75]","language":"中文","translation":false},{"id":"capital-4-50","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"另一方面，货币所以具有流通手段的职能，只因为货币是商品的独立出来的价值。因此，货币作为流通手段的运动，实际上只是商品本身的形式的运动。因而这种运动也必然明显地反映在货币流通上。例如，麻布就是先把它的商品形式转化为它的货币形式。然后它的第一形态变化Ｗ—Ｇ的终极，即货币形式，成为它的第二形态变化Ｇ—Ｗ(即再转化为圣经)的始极。但这两个形式变换的每一个都是通过商品和货币的交换，通过二者互相变换位置而实现的。同一些货币作为商品的转换形态来到卖者手里，然后又作为商品的绝对可以让渡的形态从他的手里离开。这些货币变换位置两次。麻布的第一形态变化使这些货币进入织布者的口袋里，麻布的第二形态变化又使这些货币从那里出来。这样，同一个商品的两个互相对立的形式变换就反映在货币的两次方向相反的位置变换上。","language":"中文","translation":false},{"id":"capital-4-51","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"反之，如果只有单方面的商品形态变化，不论单是卖或单是买，这个货币就只变换位置一次。货币的第二次位置变换总是表明商品的第二次形态变化，表明又由货币转化为商品。同一些货币反复不断地变换位置，不仅反映一个商品的形态变化的系列，而且反映整个商品世界的无数形态变化的交错联系。不言而喻，这一切只适合于这里所考察的简单商品流通形式。","language":"中文","translation":false},{"id":"capital-4-52","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"每一个商品在流通中走第一步，即进行第一次形式变换，就退出流通，而总有新的商品进入流通。相反，货币作为流通手段却不断地留在流通领域，不断地在那里流动。于是产生了一个问题，究竟有多少货币不断地被流通领域吸收。","language":"中文","translation":false},{"id":"capital-4-53","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在一个国家里，每天都发生大量的、同时发生的、因而在空间上并行的单方面的商品形态变化，换句话说，一方面单是卖，另一方面单是买。商品在自己的价格上已经等于一定的想象的货币量。因为这里所考察的直接的流通形式总是使商品和货币作为物体彼此对立着，商品在卖的一极，货币在买的一极，所以，商品世界的流通过程所需要的流通手段量，已经由商品的价格总额决定了。事实上，货币不过是把已经在商品价格总额中观念地表现出来的金额实在地表现出来。因此，这两个数额相等是不言而喻的。但是我们知道，在商品价值不变的情况下，商品的价格会同金(货币材料)本身的价值一起变动，金的价值降低，商品的价格会相应地提高；金的价值提高，商品的价格会相应地降低。随着商品价格总额这样增加或减少，流通的货币量必须以同一程度增加或减少。诚然，在这里，流通手段量的变化都是由货币本身引起的，但不是由它作为流通手段的职能，而是由它作为价值尺度的职能引起的。先是商品价格同货币价值成反比例地变化，然后是流通手段量同商品价格成正比例地变化。比如说，如果不是金的价值降低，而是银代替金充当价值尺度，或者不是银的价值提高，而是金使银失去价值尺度的职能，那也会发生完全相同的现象。在前一种情况下，流通的银要比以前的金多，在后一种情况下，流通的金要比以前的银少。在这两种情况下，货币材料的价值，即执行价值尺度的职能的商品的价值都改变了，因此，商品价值的价格表现也会改变，实现这些价格的流通货币量也会改变。我们已经知道，商品流通领域有一个口，金(或银，总之，货币材料)是作为具有一定价值的商品，从这个口进入流通领域的。这个价值在货币执行价值尺度的职能时，即在决定价格时，是作为前提而存在的。比如说，如果价值尺度本身的价值降低了，那末，这首先会在贵金属产地直接同作为商品的贵金属交换的那些商品的价格变化中表现出来。而很大一部分其他商品会在一个较长的时期继续按照价值尺度的已变得虚幻的旧有的价值来估价，特别在资产阶级社会还不太发展的阶段是这样。可是，通过商品间的价值关系，一种商品会影响别一种商品，于是这些商品的金价格或银价格会逐渐同商品价值本身所决定的比例趋于一致，直到最后所有的商品价值都相应地根据货币金属的新价值来估价。随着这个趋于一致的过程，贵金属不断增加，它们是由于代替那些直接同它们交换的商品而流进来的。因此，商品改订价格普遍到什么程度，或者说，商品的价值根据金属已经跌落并继续跌落到一定点的新价值来估价达到什么程度，实现商品价值所需要的贵金属数量也已经增加到同样的程度了。由于对发现新的金银矿以后出现的事实做了片面的考察，在十七世纪，特别是在十八世纪，有人得出了错误的结论，以为商品价格上涨是因为有更多的金银充当了流通手段。下面假设金的价值是既定的，实际上在估量价格的一瞬间，金的价值确实也是既定的。","language":"中文","translation":false},{"id":"capital-4-54","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在这种前提下，流通手段量决定于待实现的商品价格总额。如果我们再假设每一种商品的价格都是既定的，显然，商品价格总额就决定于流通中的商品量。只要稍微动一下脑筋就可以知道，1夸特小麦要是值2镑，100夸特就值200镑，200夸特就值400镑，等等，因此，在小麦出售时与小麦换位的货币量必须同小麦量一起增加。","language":"中文","translation":false},{"id":"capital-4-55","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"假设商品量已定，流通货币量就随着商品价格的波动而增减。流通货币量之所以增减，是因为商品的价格总额随着商品价格的变动而增减。为此，完全不需要所有商品的价格同时上涨或跌落。只要若干主要商品的价格在一种情况下上涨，或在另一种情况下跌落，就足以提高或降低全部流通商品的待实现的价格总额，从而使进入流通的货币增加或减少。无论商品价格的变动是反映实际的价值变动，或只是反映市场价格的波动，流通手段量所受的影响都是相同的。","language":"中文","translation":false},{"id":"capital-4-56","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"假定有若干互不相干的、同时发生的、因而在空间上并行的卖，或者说局部形态变化，例如有1夸特小麦、20码麻布、1本圣经、4加仑烧酒同时出售。如果每种商品的价格都是2镑，待实现的价格总额就是8镑，那末进入流通的货币量必须是8镑。相反，如果这4种商品是我们上面所说过的形态变化系列的各个环节，即1夸特小麦—2镑—20码麻布—2镑—1本圣经—2镑—4加仑烧酒—2镑，那末，有2镑就可以使所有这些商品依次流通，因为它依次实现它们的价格，从而实现8镑的价格总额，最后停留在酿酒者手中。这2镑完成了4次流通。同一些货币的这种反复的位置变换既表示商品发生双重的形式变换，表示商品通过两个对立的流通阶段的运动，也表示各种商品的形态变化交错在一起[76]。这个过程经过的各个互相对立、互为补充的阶段，不可能在空间上并行，只能在时间上相继发生。因此，时间就成为计量这个过程久暂的尺度，或者说，同一些货币在一定时间内的流通次数可以用来计量货币流通的速度。例如，假定上述4种商品的流通过程持续1天。这样，待实现的价格总额为8镑，同一些货币1天的流通次数是4次，流通的货币量是2镑，或者就一定时间的流通过程来说是：商品价格总额/同名货币的流通次数=执行流通手段职能的货币量。这个规律是普遍适用的。在一定的时间内，一个国家的流通过程包括两方面：一方面是许多分散的、同时发生的和空间上并行的卖(或买)或局部形态变化，其中同一些货币只变换位置一次或只流通一次；另一方面是许多部分互相平行，部分互相交错的具有多少不等的环节的形态变化系列，其中同一些货币流通的次数多少不等。但是，流通中的全部同名货币的总流通次数提供了每个货币的平均流通次数或货币流通的平均速度。例如，在每天流通过程开始时进入流通的货币量，当然由同时地和空间上并行地流通着的商品的价格总额来决定。但在过程之内，可以说每一货币都对另一货币承担责任。如果一个货币加快流通速度，另一个货币就会放慢流通速度，甚至完全退出流通领域，因为流通领域只能吸收这样一个金量，这个金量乘以它的单个元素的平均流通次数，等于待实现的价格总额。因此，货币的流通次数增加，流通的货币量就会减少，货币的流通次数减少，货币量就会增加。因为在平均流通速度一定时，能够执行流通手段职能的货币量也是一定的，所以，例如只要把一定量1镑的钞票投入流通，就可以从流通中取回等量的索维林，——这是一切银行都很熟悉的手法。","language":"中文","translation":false},{"id":"capital-4-57","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"既然货币流通只是表现商品流通过程，即商品通过对立的形态变化而实现的循环，所以货币流通的速度也就表现商品形式变换的速度，表现形态变化系列的不断交错，表现物质变换的迅速，表现商品迅速退出流通领域并同样迅速地为新商品所代替。因此，货币流通的迅速表现互相对立、互为补充的阶段——由使用形态转化为价值形态，再由价值形态转化为使用形态——的流水般的统一，即卖和买两个过程的流水般的统一。相反，货币流通的缓慢则表现这两个过程分离成彼此对立的独立阶段，表现形式变换的停滞，从而表现物质变换的停滞。至于这种停滞由什么产生，从流通本身当然看不出来。流通只是表示出这种现象本身。一般人在货币流通迟缓时看到货币在流通领域各点上出没的次数减少，就很容易用流通手段量不足来解释这种现象。[77]","language":"中文","translation":false},{"id":"capital-4-58","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"可见，在每一段时期内执行流通手段职能的货币的总量，一方面取决于流通的商品世界的价格总额，另一方面取决于这个商品世界的互相对立的流通过程流动的快慢，这种流动决定着同一些货币能够实现价格总额的多大部分。但是，商品的价格总额又决定于每种商品的数量和价格。这三个因素，即价格的变动、流通的商品量、货币的流通速度，可能按不同的方向和不同的比例变动，因此，待实现的价格总额以及受价格总额制约的流通手段量，也可能有多种多样的组合。在这里，我们只举出商品价格史上最重要的几种组合。","language":"中文","translation":false},{"id":"capital-4-59","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在商品价格不变时，由于流通商品量增加，或者货币流通速度减低，或者这两种情况同时发生，流通手段量就会增加。反之，由于商品量减少，或者货币流通速度增加，流通手段量就会减少。","language":"中文","translation":false},{"id":"capital-4-60","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在商品价格普遍提高时，如果流通商品量的减少同商品价格的上涨保持相同的比例，或流通的商品量不变，而货币流通速度的增加同价格的上涨一样迅速，流通手段量就会不变。如果商品量的减少或货币流通速度的增加比价格的上涨更迅速，流通手段量就会减少。","language":"中文","translation":false},{"id":"capital-4-61","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在商品价格普遍下降时，如果商品量的增加同商品价格的跌落保持相同的比例，或货币流通速度的减低同价格的跌落保持相同的比例，流通手段量就会依然不变。如果商品量的增加或货币流通速度的减低比商品价格的跌落更迅速，流通手段量就会增加。","language":"中文","translation":false},{"id":"capital-4-62","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"各种因素的变动可以互相抵销，所以尽管这些因素不断变动，待实现的商品价格总额，从而流通的货币量可以依然不变。因此，特别是考察一个较长的时期，我们就会发现：在每一国家中流通的货币量的平均水平比我们根据表面现象所预料的要稳定得多；除了周期地由生产危机和商业危机引起的，以及偶尔由货币价值本身的变动引起的强烈震动时期以外，流通的货币量偏离这一平均水平的程度，比我们根据表面现象所预料的要小得多。","language":"中文","translation":false},{"id":"capital-4-63","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"流通手段量决定于流通商品的价格总额和货币流通的平均速度这一规律[78]，还可以表述如下：已知商品价值总额和商品形态变化的平均速度，流通的货币或货币材料的量决定于货币本身的价值。有一种错觉，认为情况恰恰相反，即商品价格决定于流通手段量，而流通手段量又决定于一个国家现有的货币材料量[79]，这种错觉在它的最初的代表者那里是建立在下面这个荒谬的假设上的：在进入流通过程时，商品没有价格，货币也没有价值，然后在这个过程内，商品堆的一定部分同金属堆的相应部分相交换。[80]","language":"中文","translation":false},{"id":"capital-4-64","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"从货币作为流通手段的职能中产生出货币的铸币形式。在商品的价格或货币名称中想象地表现出来的金重量，必须在流通中作为同名的金块或铸币同商品相对立。正象确立价格标准一样，铸造硬币也是国家的事。金银作为铸币穿着不同的国家制服，但它们在世界市场上又脱掉这些制服。这就表明，商品流通的国内领域或民族领域，同它们的普遍的世界市场领域是分开的。","language":"中文","translation":false},{"id":"capital-4-65","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"因此，金币和金块本来只有形状上的差别，金始终能从一种形式变为另一种形式。[81]它离开造币厂的道路，同时就是通向熔炉的道路。这是因为金币在流通中受到磨损，有的磨损得多，有的磨损得少。金的名称和金的实体，名义含量和实际含量，开始了它们的分离过程。同名的金币，具有了不同的价值，因为重量不同了。作为流通手段的金同作为价格标准的金偏离了，因此，金在实现商品的价格时不再是该商品的真正等价物。中世纪和直到十八世纪为止的近代的铸币史就是一部这样混乱的历史。流通过程的自然倾向是要把铸币的金存在变为金假象，或把铸币变为它的法定金属含量的象征。这种倾向甚至为现代的法律所承认，这些法律规定，金币磨损到一定程度，便不能通用，失去通货资格。","language":"中文","translation":false},{"id":"capital-4-66","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"既然货币流通本身使铸币的实际含量同名义含量分离，使铸币的金属存在同它的职能存在分离，所以在货币流通中就隐藏着一种可能性：可以用其他材料做的记号或用象征来代替金属货币执行铸币的职能。铸造重量极小的金币或银币在技术上有困难，而且起初是较贱的金属而不是较贵的金属(是银不是金，是铜不是银)充当价值尺度，因而在它们被较贵的金属赶下宝座之前曾一直作为货币流通，这些事实历史地说明了银记号和铜记号可以代替金币发挥作用。这些记号在铸币流通最快因而磨损最快的商品流通领域中，即在极小额的买卖不断重复进行的领域中代替了金。为了不让金的这些侍从永远篡夺金的位置，法律规定一个极小的比例，只有在这个比例内，它们代替金来支付才能强人接受。不同种铸币流通的各种特殊领域当然是互相交错的。辅币在支付最小金币的尾数时与金同时出现；金不断地进入零售流通，但是又因与辅币兑换而从那里不断地被抛出来。[82]","language":"中文","translation":false},{"id":"capital-4-67","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"银记号或铜记号的金属含量是由法律任意规定的。它们在流通中比金币磨损得还要快。因此，它们的铸币职能实际上与它们的重量完全无关，就是说，与任何价值完全无关。金的铸币存在同它的价值实体完全分离了。因此，相对地说没有价值的东西，例如纸票，就能代替金来执行铸币的职能。在金属货币记号上，这种纯粹的象征性质还在一定程度上隐藏着。但在纸币上，这种性质就暴露无遗了。我们看到，困难的只是第一步。","language":"中文","translation":false},{"id":"capital-4-68","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"这里讲的只是强制流通的国家纸币。这种纸币是直接从金属流通中产生出来的。而信用货币产生的条件，我们从简单商品流通的观点来看还是根本不知道的。但不妨顺便提一下，正如本来意义的纸币是从货币作为流通手段的职能中产生出来一样，信用货币的自然根源是货币作为支付手段的职能。[83]","language":"中文","translation":false},{"id":"capital-4-69","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"国家把印有1镑、5镑等等货币名称的纸票从外部投入流通过程。只要这些纸票确实是代替同名的金额来流通，它们的运动就只反映货币流通本身的规律。纸币流通的特殊规律只能从纸币是金的代表这种关系中产生。这一规律简单说来就是：纸币的发行限于它象征地代表的金(或银)的实际流通的数量。诚然，流通领域所能吸收的金量经常变动，时常高于或低于一定的平均水平。但是，一个国家的流通手段量决不会降到一定的由经验确定的最低限量以下。这个最低限量不断变动它的组成部分，就是说，不断由另外的金块组成，这种情况当然丝毫不会影响这个量的大小和它在流通领域内的不断流动。因此，这个最低限量可以由纸做的象征来代替。但是，如果今天一切流通渠道中的纸币已达到这些渠道所能吸收货币的饱和程度，明天纸币就会因商品流通发生变动而泛滥开来。一切限度都消失了。不过，如果纸币超过了自己的限度，即超过了能够流通的同名的金币量，那末，即使不谈有信用扫地的危险，它在商品世界毕竟只是代表由商品世界的内在规律所决定的那个金量，即它所能代表的那个金量。例如，如果一定的纸票量按其名称代表2盎斯金，而实际是代替1盎斯金，那末事实上1镑比如说就是1/8盎斯金的货币名称，而不是原来1/4盎斯金的货币名称了。其结果无异于金在它作为价格尺度的职能上发生了变化，同一价值，原来用1镑的价格来表现，现在要用2镑的价格来表现了。","language":"中文","translation":false},{"id":"capital-4-70","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"纸币是金的符号或货币符号。纸币同商品价值的关系只不过是：商品价值观念地表现在一个金量上，这个金量则由纸象征地可感觉地体现出来。纸币只有代表金量(金量同其他一切商品量一样，也是价值量)，才成为价值符号。[84]","language":"中文","translation":false},{"id":"capital-4-71","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"最后要问，为什么金可以用它本身的没有任何价值的符号来代替呢？而我们已经知道，只有当金执行铸币或流通手段的职能而被孤立起来或独立出来时，金才可以被代替。当然，就个别金币来说，这种职能并没有独立出来，虽然磨损了的金币的继续流通已表明这种职能已经独立出来。金块只有实际处在流通中的时候，才是单纯的铸币或流通手段。对于个别金币不适用的情况，对于能由纸币代替的最低限度的金量却是适用的。这个金量经常处在流通领域中，不断地执行流通手段的职能，从而只是作为这种职能的承担者而存在。因此，它的运动只表示商品形态变化Ｗ—Ｇ—Ｗ的对立过程的不断互相转化。在这种形态变化中，商品的价值形态与商品对立，只是为了马上又消失。在这里，商品的交换价值的独立表现只是转瞬即逝的要素。它马上又会被别的商品代替。因此，在货币不断转手的过程中，单有货币的象征存在就够了。货币的职能存在可以说吞掉了它的物质存在。货币作为商品价格的转瞬即逝的客观反映，只是当作它自己的符号来执行职能，因此也能够由符号来代替[85]。但是，货币符号本身需要得到客观的社会公认，而纸做的象征是靠强制流通得到这种公认的。国家的这种强制行动，只有在一国范围内或国内的流通领域内才有效，也只有在这个领域内，货币才完全执行它的流通手段或铸币的职能，因而才能在纸币形式上取得一种同它的金属实体在外部相脱离的并纯粹是职能的存在形式。","language":"中文","translation":false},{"id":"capital-4-72","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"作为价值尺度并因而以自身或通过代表作为流通手段来执行职能的商品，是货币。因此，金(或银)是货币。金作为货币执行职能，一方面是在这样的场合：它必须以其金体(或银体)出现，因而作为货币商品出现，就是说，它不象在充当价值尺度时那样纯粹是观念的，也不象在充当流通手段时那样可以用别的东西来代表；另一方面是在这样的场合：它的职能——不论由它亲自执行，还是由它的代表执行——使它固定成为唯一的价值形态，成为交换价值的唯一适当的存在，而与其他一切仅仅作为使用价值的商品相对立。","language":"中文","translation":false},{"id":"capital-4-73","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"两种对立的商品形态变化的不断循环，或卖与买的不息转换，表现在不停的货币流通上，或表现在货币作为流通的永动机的职能上。只要商品的形态变化系列一中断，卖之后没有继之以买，货币就会停止流动，或者如布阿吉尔贝尔所说的，由动的东西变为不动的东西【74】，由铸币变为货币。","language":"中文","translation":false},{"id":"capital-4-74","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"随着商品流通的最初发展，把第一形态变化的产物，商品的转化形式或它的金蛹保留在自己手中的必要性和欲望也发展起来了[86]。出售商品不是为了购买商品，而是为了用货币形式来代替商品形式。这一形式变换从物质变换的单纯媒介变成了目的本身。商品的转换形态受到阻碍，不能再作为商品的绝对可以让渡的形态或作为只是转瞬即逝的货币形式而起作用。于是货币硬化为贮藏货币，商品出售者成为货币贮藏者。","language":"中文","translation":false},{"id":"capital-4-75","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在商品流通的初期，只是使用价值的多余部分转化为货币。这样，金和银自然就成为这种多余部分或财富的社会表现。在有些民族中，与传统的自给自足的生产方式相适应，需要范围是固定有限的，在这些民族中，这种素朴的货币贮藏形式就永恒化了。在亚洲人那里，特别是在印度人那里，情况就是这样。范德林特以为商品价格决定于一个国家现有的金银量，他自问：为什么印度的商品这样便宜？他回答说：因为印度人埋藏货币。他指出，从1602年到1734年，他们埋藏的银值15000万镑，这些银最先是从美洲运到欧洲去的[87]。从1856年到1866年这10年间，英国输往印度和中国的银(输到中国的银大部分又流入印度)值12000万镑，这些银原先是用澳大利亚的金换来的。","language":"中文","translation":false},{"id":"capital-4-76","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"随着商品生产的进一步发展，每一个商品生产者都必须握有这个物的神经，这个“社会的抵押品”[88]。他的需要不断更新，因而促使他不断购买别人的商品，而他生产和出售自己的商品是要费时间的，并且带有偶然性。他要买而不卖，就必须在以前曾经卖而不买。这种做法要普遍实行，似乎是自相矛盾的。但是，贵金属在它的产地直接同其他商品交换。在那里就是卖(商品所有者方面)而不买(金银所有者方面)。[89]而以后的没有继之以买的卖，不过是使贵金属进一步分配给一切商品所有者的媒介。因此，在交易的各个点上，有不同数量的金银贮藏。自从有可能把商品当作交换价值来保持，或把交换价值当作商品来保持以来，求金欲就产生了。随着商品流通的扩展，货币——财富的随时可用的绝对社会形式——的权力也日益增大。","language":"中文","translation":false},{"id":"capital-4-77","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"“金真是一个奇妙的东西！谁有了它，谁就成为他想要的一切东西的主人。有了金，甚至可以使灵魂升入天堂。”(哥伦布1503年寄自牙买加的信)","language":"中文","translation":false},{"id":"capital-4-78","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"因为从货币身上看不出它是由什么东西变成的，那末，一切东西，不论是不是商品，都可以变成货币。一切东西都可以买卖。流通成了巨大的社会蒸馏器，一切东西抛到里面去，再出来时都成为货币的结晶。连圣徒的遗骨也不能抗拒这种炼金术，更不用说那些人间交易范围之外的不那么粗陋的圣物了[90]。正如商品的一切质的差别在货币上消灭了一样，货币作为激进的平均主义者把一切差别都消灭了[91]。但货币本身是商品，是可以成为任何人的私产的外界物。这样，社会权力就成为私人的私有权力。因此，古代社会咒骂货币是换走了自己的经济秩序和道德秩序的辅币[92]。还在幼年时期就抓着普路托的头发把他从地心里拖出来[93]的现代社会，则颂扬金的圣杯是自己最根本的生活原则的光辉体现。","language":"中文","translation":false},{"id":"capital-4-79","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"商品作为使用价值满足一种特殊的需要，构成物质财富的一种特殊的要素。而商品的价值则衡量商品对物质财富的一切要素的吸引力的大小，因而也衡量商品所有者的社会财富。在野蛮的简单的商品所有者看来，甚至在西欧的农民看来，价值是同价值形式分不开的，因而金银贮藏的增多就是价值的增多。当然，货币的价值在变化，这或者是由于它本身的价值变化，或者是由于商品的价值变化。但是一方面，这不会妨碍200盎斯金始终比100盎斯金包含的价值多，300盎斯金又比200盎斯金包含的价值多等等，另一方面，这也不会妨碍这种物的天然的金属形式仍旧是一切商品的一般等价形式，是一切人类劳动的直接的社会化身。贮藏货币的欲望按其本性是没有止境的。在质的方面，或按形式来说，货币是无限的，也就是说，是物质财富的一般代表，因为它能直接转化成任何商品。但是在量的方面，每一个现实的货币额又是有限的，因而只是作用有限的购买手段。货币的这种量的有限性和质的无限性之间的矛盾，迫使货币贮藏者不断地从事息息法斯式的积累劳动。他们同世界征服者一样，这种征服者把征服每一个新的国家只看作是取得了新的国界。","language":"中文","translation":false},{"id":"capital-4-80","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"要把金作为货币，从而作为贮藏货币的要素保存起来，就必须阻止它流通，不让它作为购买手段化为消费。因此，货币贮藏者为了金偶像而牺牲自己的肉体享受。他虔诚地信奉禁欲的福音书。另一方面，他能够从流通中以货币形式取出的，只是他以商品形式投入流通的。他生产的越多，他能卖的也就越多。因此，勤劳、节俭、吝啬就成了他的主要美德。多卖少买就是他的全部政治经济学。[94]","language":"中文","translation":false},{"id":"capital-4-81","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"除直接的贮藏形式以外，还有一种美的贮藏形式，即占有金银制的商品。它是与资产阶级社会的财富一同增长的。“让我们成为富人或外表象富人吧。”(狄德罗)【75】这样，一方面，形成了一个日益扩大的金银市场，这个市场不以金银的货币职能为转移，另一方面，也形成了一个潜在的货币供应源泉，这个源泉特别在社会大风暴时期涌现出来。","language":"中文","translation":false},{"id":"capital-4-82","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"货币贮藏在金属流通的经济中执行着种种不同的职能。它的第一个职能是从金银铸币的流通条件中产生的。我们已经知道，随着商品流通在范围、价格和速度方面的经常变动，流通的货币量也不断增减。因此，这个量必须能伸缩。有时货币必须当作铸币被吸收，有时铸币必须当作货币被排斥。为了使实际流通的货币量总是同流通领域的饱和程度相适应，一个国家的现有的金银量必须大于执行铸币职能的金银量。这个条件是靠货币的贮藏形式来实现的。货币贮藏的蓄水池，对于流通中的货币来说，既是排水渠，又是引水渠；因此，货币永远不会溢出它的流通的渠道。[95]","language":"中文","translation":false},{"id":"capital-4-83","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在上面我们所考察的商品流通的直接形式中，同一价值量总是双重地存在着，在一极上是商品，在另一极上是货币。所以，商品所有者只是作为现存的互相等价的物的代表来接触。但是，随着商品流通的发展，使商品的让渡同商品价格的实现在时间上分离开来的关系也发展起来。这里我们只举出其中一些最简单的关系。一些商品需要的生产时间较长，另一些商品需要的生产时间较短。不同的商品的生产与不同的季节有关。一些商品在市场所在地生产，另一些商品要旅行到远方的市场去。因此，一个商品所有者可以在另一个商品所有者作为买者出现之前，作为卖者出现。当同样一些交易总是在同一些人中间反复进行时，商品的出售条件就按照商品的生产条件来调节。另一方面，有一些商品例如房屋的使用权是出卖一定期限的。买者只是在期满时才真正取得商品的使用价值。因而他先购买商品，后对商品支付。一个商品所有者出售他现有的商品，而另一个商品所有者却只是作为货币的代表或作为未来货币的代表来购买这种商品。卖者成为债权人，买者成为债务人。由于商品的形态变化或商品的价值形式的发展在这里起了变化，货币也就取得了另一种职能。货币成了支付手段。[96]","language":"中文","translation":false},{"id":"capital-4-84","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"债权人或债务人的身分在这里是从简单商品流通中产生的。简单商品流通形式的改变，在卖者和买者身上打上了这两个新烙印。最初，同卖者和买者的角色一样，这也是暂时的和由同一些流通当事人交替扮演的角色。但是，现在这种对立一开始就不是那样愉快，并且能够更牢固地结晶起来[97]。而这两种角色还可以不依赖商品流通而出现。例如，古代世界的阶级斗争主要是以债权人和债务人之间的斗争的形式进行的；在罗马，这种斗争以负债平民的破产，沦为奴隶而告终。在中世纪，这种斗争以负债封建主的破产，他们的政治权力随着它的经济基础一起丧失而告终。但是在这里，货币形式——债权人和债务人的关系具有货币关系的形式——所反映的不过是更深刻的经济生活条件的对抗。","language":"中文","translation":false},{"id":"capital-4-85","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"现在我们回到商品流通领域来。等价的商品和货币不再同时出现在卖的过程的两极上。现在，第一，货币在决定所卖商品的价格上执行价值尺度的职能。由契约规定的所卖商品的价格，计量买者的债务，即买者到期必须支付的货币额。第二，货币执行观念的购买手段的职能。虽然货币只是存在于买者支付货币的承诺中，但它使商品的转手实现了。只是当支付日期到来时，支付手段才真正进入流通，就是说，从买者手里转到卖者手里。流通手段转化为贮藏货币，是因为流通过程在第一阶段中断，或商品的转化形态退出了流通。支付手段进入流通，但这是在商品已经退出流通之后。货币不再是过程的媒介。它作为交换价值的绝对存在，或作为一般商品，独立地结束这一过程。卖者把商品变为货币，是为了通过货币来满足某种需要，货币贮藏者把商品变为货币，是为了以货币形式保存商品，欠债的买者把商品变为货币，则是为了能够支付。如果他不支付，他的财产就会被强制拍卖。因此，现在由于流通过程本身的关系所产生的一种社会必要性，商品的价值形态即货币就成了卖的目的本身。","language":"中文","translation":false},{"id":"capital-4-86","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"买者在把商品变为货币之前，已经把货币再转化为商品，或者说，他先完成商品的第二形态变化，后完成商品的第一形态变化。卖者的商品在流通，但它只是靠私法的索债权实现它的价格。它在转化为货币之前，已经转化为使用价值。它的第一形态变化只是以后才完成的。[98]","language":"中文","translation":false},{"id":"capital-4-87","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在流通过程的每一个一定的时期内，到期的债务代表着产生这些债务的已售商品的价格总额。实现这一价格总额所必需的货币量，首先取决于支付手段的流通速度。它决定于两种情况：一是债权人和债务人的关系的锁链，即A从他的债务人B那里得到的货币，付给他的债权人C等等；一是各种不同的支付期限的间隔。一个接一个的支付的锁链或事后进行的第一形态变化的锁链，同我们前面考察的形态变化系列的交错，有着本质的区别。在流通手段的流通中，卖者和买者的联系不仅仅被表现出来，而且这种联系本身只是在货币流通中产生，并且是与货币流通一同产生。相反地，支付手段的运动则表现了一种在这种运动之前已经现成地存在的社会联系。","language":"中文","translation":false},{"id":"capital-4-88","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"若干卖的同时并行，使流通速度对铸币量的补偿作用受到了限制。反之，这种情况却为节省支付手段造成了新的杠杆。随着支付集中于同一地点，使这些支付互相抵销的专门机构和方法就自然地发展起来。例如中世纪里昂的转账处就是如此。只要把A对B、B对C、C对A等等所有的债权对照一下，就可以有一定的数额作为正数和负数互相抵销。这样需要偿付的只是债务差额。支付越集中，差额相对地就越小，因而流通的支付手段量也相对地越小。","language":"中文","translation":false},{"id":"capital-4-89","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"货币作为支付手段的职能包含着一个直接的矛盾。在各种支付互相抵销时，货币就只是在观念上执行计算货币或价值尺度的职能。而在必须进行实际支付时，货币又不是充当流通手段，不是充当物质变换的仅仅转瞬即逝的媒介形式，而是充当社会劳动的单个化身，充当交换价值的独立存在，充当绝对商品。这种矛盾在生产危机和商业危机中称为货币危机[99]的那一时刻暴露得特别明显。这种货币危机只有在一个接一个的支付的锁链和抵销支付的人为制度获得充分发展的地方，才会发生。当这一机构整个被打乱的时候，不问其原因如何，货币就会突然直接地从计算货币的纯粹观念形态变成坚硬的货币。这时，它是不能由平凡的商品来代替的。商品的使用价值变得毫无价值，而商品的价值在它自己的价值形式面前消失了。昨天，资产者还被繁荣所陶醉，怀着启蒙的骄傲，宣称货币是空虚的幻想。只有商品才是货币。今天，他们在世界市场上到处叫嚷，只有货币才是商品！象鹿渴求清水一样，他们的灵魂渴求货币这唯一的财富[100]。在危机时期，商品和它的价值形态(货币)之间的对立发展成绝对矛盾。因此，货币的表现形式在这里也是无关紧要的。不管是用金支付，还是用银行券这样的信用货币支付，货币荒都是一样的。[101]","language":"中文","translation":false},{"id":"capital-4-90","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"现在我们来考察一定时期内的流通货币的总额。假定流通手段和支付手段的流通速度是已知的，这个总额就等于待实现的商品价格总额加上到期的支付总额，减去彼此抵销的支付，最后减去同一货币交替地时而充当流通手段、时而充当支付手段的流通次数。例如，一个农民卖谷物得到2镑，在这里，这2镑起着流通手段的作用。他在支付日把这2镑用来支付织布者先前交给他的麻布。这时，这2镑起着支付手段的作用。接着织布者又拿现金去买圣经，于是这2镑又重新充当流通手段，如此等等。因此，即使价格、货币流通速度和支付的节省程度是既定的，一定时期内例如一天内流通的货币量和流通的商品量也不再相符。货币在流通，而它所代表的是早已退出流通的商品。商品在流通，而它的货币等价物只有在将来才出现。另一方面，每天订立的支付和同一天到期的支付完全不是可通约的量。[102]","language":"中文","translation":false},{"id":"capital-4-91","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"信用货币是直接从货币作为支付手段的职能中产生的，而由出售商品得到的债券本身又因债权的转移而流通。另一方面，随着信用事业的扩大，货币作为支付手段的职能也在扩大。作为支付手段的货币取得了它特有的各种存在形式，并以这些形式占据了大规模交易的领域，而金银铸币则主要被挤到小额贸易的领域之内。[103]","language":"中文","translation":false},{"id":"capital-4-92","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在商品生产达到一定水平和规模时，货币作为支付手段的职能就会越出商品流通领域。货币变成契约上的一般商品[104]。地租、赋税等等由实物交纳转化为货币支付。这种转化在多大程度上取决于生产过程的总的状态，可以由例如罗马帝国两次企图用货币征收一切赋税都告失败来证明。路易十四统治下的法国农民极端贫困，这种受到布阿吉尔贝尔、沃邦元帅等人如此有力地斥责的现象，不仅是由重税引起的，而且是由实物税改为货币税造成的[105]。另一方面，在亚洲，地租的实物形式(它同时又是国税的主要因素)是建立在象自然关系那样一成不变地再生产出来的生产关系的基础上的，这种支付形式反过来又维护着这种古老的生产形式。这种支付形式是土耳其帝国自身得以维持的秘密之一。如果欧洲强加于日本的对外贸易使日本把实物地租改为货币地租，日本的模范的农业就会崩溃。这种农业的狭隘的经济存在条件也就会消失。","language":"中文","translation":false},{"id":"capital-4-93","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在每个国家，都规定一定的总的支付期限。撇开再生产的其他周期不说，这些期限部分地是以同季节变化有关的生产的自然条件为基础的。这些期限还调节着那些不是直接由商品流通产生的支付，如赋税、地租等等。这些分散在社会上各个地方的支付在一年的某些天所需的货币量，会在节省支付手段方面引起周期性的但完全是表面的混乱。[106]从支付手段的流通速度的规律中可以看出，一切周期性的支付(不问其起因如何)所必需的支付手段量，与支付期限的长短成正比（在第1版至第4版中是：反比。——编者注）。[107]","language":"中文","translation":false},{"id":"capital-4-94","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"由于充当支付手段的货币的发展，就必须积累货币，以便到期偿还债务。随着资产阶级社会的发展，作为独立的致富形式的货币贮藏消失了，而作为支付手段准备金的形式的货币贮藏却增长了。","language":"中文","translation":false},{"id":"capital-4-95","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"货币一越出国内流通领域，便失去了在这一领域内获得的价格标准、铸币、辅币和价值符号等地方形式，又恢复原来的贵金属块的形式。在世界贸易中，商品普遍地展开自己的价值。因此，在这里，商品独立的价值形态，也是作为世界货币与商品相对立。只有在世界市场上，货币才充分地作为这样一种商品起作用，这种商品的自然形式同时就是抽象人类劳动的直接的社会实现形式。货币的存在方式与货币的概念相适合了。","language":"中文","translation":false},{"id":"capital-4-96","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"在国内流通领域内，只能有一种商品充当价值尺度，从而充当货币。在世界市场上，占统治地位的是双重价值尺度，即金和银。[108]","language":"中文","translation":false},{"id":"capital-4-97","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"世界货币执行一般支付手段的职能、一般购买手段的职能和一般财富的绝对社会化身的职能。它的最主要的职能，是作为支付手段平衡国际贸易差额。由此产生重商主义体系的口号——贸易差额！[109]金银充当国际购买手段，主要是在各国间通常的物质变换的平衡突然遭到破坏的时候。最后，它们充当财富的绝对社会化身是在这样的场合：不是要买或是要支付，而是要把财富从一个国家转移到另一个国家，同时，商品市场的行情或者要达到的目的本身，不容许这种转移以商品形式实现。[110]","language":"中文","translation":false},{"id":"capital-4-98","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"每个国家，为了国内流通，需要有准备金，为了世界市场的流通，也需要有准备金。因此，货币贮藏的职能，一部分来源于货币作为国内流通手段和国内支付手段的职能，一部分来源于货币作为世界货币的职能。[110a]在后一种职能上，始终需要实在的货币商品，真实的金和银。因此，詹姆斯·斯图亚特为了把金银和它们的仅仅是地方的代表区别开来，就明确地指出金银的特征是世界货币。","language":"中文","translation":false},{"id":"capital-4-99","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"金银的流动是二重的。一方面，金银从产地分散到整个世界市场，在那里，在不同程度上为不同国家的流通领域所吸收，以便进入国内流通渠道，补偿磨损了的金银铸币，供给奢侈品的材料，并且凝固为贮藏货币[111]。这第一种运动是以实现在商品上的一国劳动和实现在贵金属上的金银出产国的劳动之间的直接交换为媒介的。另一方面，金银又不断往返于不同国家的流通领域之间，这是一个随着汇率的不断变化而产生的运动。[112]","language":"中文","translation":false},{"id":"capital-4-100","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"资产阶级生产发达的国家把大量集中在银行准备库内的贮藏货币，限制在它执行各种特殊职能所必需的最低限度以内。[113]除了某些例外，如果准备库内的货币贮藏大大超过平均水平，那就表明商品流通停滞了，或者商品形态变化的流动中断了。[114]","language":"中文","translation":false},{"id":"capital-4-101","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[50] 为什么货币不直接代表劳动时间本身，例如，以一张纸币代表X个劳动小时，这个问题可简单归结为：在商品生产的基础上为什么劳动产品必须表现为商品，因为商品的表现就包含着商品分为商品和货币商品这种二重化。或者说，为什么私人劳动不能看成是直接的社会劳动，不能看成是它自身的对立面。我在别处曾详细地谈到在商品生产的基础上实行“劳动货币”这种平庸的空想。（《政治经济学批判》第61页及以下各页【54】）在这里我还想指出一点，例如欧文的“劳动货币”，同戏票一样，不是“货币”。欧文以直接社会化劳动为前提，就是说，以一种与商品生产截然相反的生产形式为前提。劳动券只是证明生产者个人参与共同劳动的份额，以及他个人在供消费的那部分共同产品中应得的份额。不过欧文没有想到以商品生产为前提，也没有想到要用货币把戏来回避商品生产的必要条件。","language":"中文","translation":false},{"id":"capital-4-102","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【54】 见《马克思恩格斯全集》中文版第13卷第73页及以下各页。——第112页。","language":"中文","translation":false},{"id":"capital-4-103","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[51] 野蛮人或半野蛮人以另外的方式使用舌头。例如帕里船长在谈到巴芬湾西岸居民的情况时说：“在这种场合〈在交换产品时〉……他们用舌头舔它〈要换给他们的物品〉两次，这才表示交易已经顺利完成。”【55】东部爱斯基摩人也总是用舌头舔他们换得的物品。既然在北方把舌头当作占有的器官，那末，在南方把肚子当作积累财富的器官就不足为奇了，卡弗尔人就是拿肚子的大小来衡量一个人的财富的。卡弗尔人真是聪明极了，因为1864年英国官方卫生报告说，工人阶级的很大一部分人缺乏脂肪物质，就在那一年，一个叫哈维的医生（不是发现血液循环的哈维），由亍吹嘘他有一种妙方能使资产阶级和贵族消除过剩的脂肪而发了财。","language":"中文","translation":false},{"id":"capital-4-104","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【55】 ［威·爱·帕里］《开辟大西洋太平洋西北航线航行日志；航行在威廉·爱德华·帕里命令下，1819—1820年由皇家“赫克拉”和“格赖珀”两轮进行》1821年伦敦版（[W. E. Parry.] 《Journal of a Voyage for the Discovery of a North-West Passage from the Atlantic to the pacific: performed in the Years 1819-20, in His Majesty's Ships Heela and Griper, under the Orders of William Edward parry》. London, 1821）。——第113页。","language":"中文","translation":false},{"id":"capital-4-105","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[52] 见卡尔·马克思《政治经济学批判》，《关于货币计量单位的学说》，第53页 及以下各页【56】。","language":"中文","translation":false},{"id":"capital-4-106","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【56】 见《马克思恩格斯全集》中文版第13卷第66页及以下各页。——第114页。","language":"中文","translation":false},{"id":"capital-4-107","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[53] 第2版注：“在金和银依法同时充当货币即充当价值尺度的地方，想把它们当作同一物质看待，总是徒劳无益的。如果假定同一劳动时间必须固定不变地物化在金银的同一比例中，这实际上就是假定金银是同一物质，而一定量价值较低的金属，即银，是一定量金的一个固定不变的分数。从爱德华三世起到乔治二世时期，英国币制史经历了一连串的混乱，其原因是法定的金银价值比例同金银价值的实际变动不断发生冲突。有时金的估价髙了，有时银的估价高了。估价过低的金属退出流通，被熔化和输出。于是两种金属的价值比例再由法律加以调整，但新的名义价值很快义象旧的那样同实际的价值比例发生冲突。——现代，由于印度和中国需要银，同银相比，金的价值暂时略微低落，结果在法国大规模地发生了上述现象：银被输出，被金逐出于流通之外。1855年、1856年和1857年，输入法国的金比从法国输出的金多了4 158万镑,而 从法国输出的银比输入法国的银多了34 704 000镑。在一些国家里，两种金属都是法定的价值尺度，因而两者在支付中都必须接受，每个人都可以随意用银或金来支付，在这里价值增大的金属实际上有贴水，它同其他任何商品一样用估价过髙的金属来计量自己的价格，而其实也只有估价过高的那种金属才起着价值尺度的作用。这方面的全部历史经验总结起来不过是这样：凡有两种商品依法充当价值尺度的地方，事实上总 是只有一种商品保持着这种地位。”（卡尔·马克思《政治经济学批判》第52、53页【57】）","language":"中文","translation":false},{"id":"capital-4-108","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【57】 见《马克思恩格斯全集》中文版第13卷第65、66页。——第115页。","language":"中文","translation":false},{"id":"capital-4-109","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[54] 第2版注：在英国，一盎斯金是货币标准的单位，但它不能分成等分。造成这种奇怪现象的原因是：“我国的铸币制度本来只适用于银，因此，一盎斯银分成的铸币总是一个整数。但后来在只适用于银的铸币制度中采用了金，因此一盎斯金铸成的金币就不能是一个整数了。”（麦克拉伦《通货简史》1858年伦敦版第16页）","language":"中文","translation":false},{"id":"capital-4-110","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[55] 第2版注：在英国的著作中，价值尺度(measure of value)和价格标准(standard of value)这两个概念极为混乱。它们的职能，从而它们的名称，经常被混淆起来。","language":"中文","translation":false},{"id":"capital-4-111","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【58】 在古代神话里，人类历史分成五个时代。黄金时代和白银时代是五个时代中最初两个时代。在最幸搞的黄金时代，人们无忧无虑，只是在后面几个时代，他们的生活才变成另外一个样子。第五个即最后一个时代——黑铁时代——充满了不平、暴行和屠杀。关于这五个时代的传说，在希腊的叙事诗人海西阿德以及罗马抒情诗人奥维狄乌斯的作品中都有记述。——第117页。","language":"中文","translation":false},{"id":"capital-4-112","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[56] 而且这种年代顺序也不是在历史上普遍适用的。","language":"中文","translation":false},{"id":"capital-4-113","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[57] 第2版注：例如,现在的英镑还不到原来重量的1/3，苏格兰镑在合并【59】以前只有原来重量的1/36，法国的利弗尔只有原来重量的1/74，西班牙的马拉维第不到原来重量的1/1000，葡萄牙的瑞斯所占的比例更是小得多。","language":"中文","translation":false},{"id":"capital-4-114","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【59】 指1707年英格兰和苏格兰的合并，这次合并的结果，使苏格兰最终归并于英格兰。由于这次合并解散了苏格兰的议会，两国间存在的一切经济上的障碍也消除了。——第118页。","language":"中文","translation":false},{"id":"capital-4-115","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[58] 第2版注：“那些现今只具有观念的名称的铸币在一切民族中都是最古老的铸币；曾经有一个时期，它们都是实在的，正因为它们是实在的，所以才用它们来计算。”（加利阿尼《货币论》第153页）","language":"中文","translation":false},{"id":"capital-4-116","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[59] 第2版注：戴维·乌尔卡尔特先生在《家常话》中说，现在英国货币标准的单位1镑约等于1/4盘斯金,是令人惊奇的（！）。他说：“这是伪造尺度，不是确立标准。”［第105页］他在金重量的“假名”上，象在其他事情上一样，看出了文明的伪造之手。","language":"中文","translation":false},{"id":"capital-4-117","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[60] 第2版注：“有人问阿那卡雪斯，为什么希腊人要用货币？他回答说，为了计算。”(阿泰纳奥斯《学者们的宴会》,施魏格霍塞编，1802年版第2卷第1部第4册第49节［第120页］）","language":"中文","translation":false},{"id":"capital-4-118","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[61] 第2版注：“作为价格标准的金和商品价格表现为同样的计算名称，例如，1盎斯金和1吨铁的价值同样都可表现为3镑17先令10 1/2便士，因此，金的这种计算名称被叫做金的造币局价格。于是产生了一种奇怪的想法，以为金（或银）用它自身的材料来估价，而且和一切其他商品不同，它从国家取得固定的价格。确定一定重量的金的计算名称被误认为确定这个重量的价值。”〈马克思《政治经济学批判》第52页【60】）","language":"中文","translation":false},{"id":"capital-4-119","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【60】 见《马克思恩格斯全集》中文版第13卷第64—65页。——第119页。","language":"中文","translation":false},{"id":"capital-4-120","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[62] 参看《政治经济学批判》中《关于货币计量单位的学说》一节（第53页及以下各页【61】)。关于提高或降低“造币局价格”的各种幻想，无非是要国家使法定的货币名称不代表法定的金量或银量，而代表较多或较少的金量或银量，由此，如1/4盎斯的金将来不是铸成20先令，而是铸成40先令。如果这种种幻想所抱的目的，不是为了采取一些拙劣的财政措施来对付公私债权人，而是为了寻求经济上的“奇迹疗法”，那末配第在《货币略论。致哈里法克斯侯爵》（1682年）中，就已经对这些幻想作了极为详尽的论述，而他的直接继承人达德利·诺思爵士和约翰·洛克只能把他的思想庸俗化，更不用说以后的人了。配第说：“如果一道法令就能使国家的财富增加十倍，这就很奇怪，为什么我们的政府不早颁布这样的法令呢！”(同上，第36页）","language":"中文","translation":false},{"id":"capital-4-121","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【61】 见《马克思恩格斯全集》中文版第13卷第66页及以下各页。——第119页。","language":"中文","translation":false},{"id":"capital-4-122","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[63] “否则必须承认，一百万货币的价值大于等值的商品的价值”（列特隆《就价值、流通、工业、国内外贸易论社会利益》第919页），因此也必须承认，“某一价值大于相等的另一价值”。","language":"中文","translation":false},{"id":"capital-4-123","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[64] 圣热罗尼莫在青年时代很费力地克制自己的物质欲念，他在沙漠中同美女的形象的斗争表明了这一点。在老年时代，他也很费力地克制自己的精神欲念。例如他说：“我自信在精神上处于世界审判者之前。”一个声音问道：“你是谁?”“我是一个基督徒。”世界审判者大发雷霆：“你撒谎，你只是一个西塞罗信徒！”【62】","language":"中文","translation":false},{"id":"capital-4-124","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【62】 马克思引自圣热罗尼莫《给叶夫斯托希亚的信——论童贞的保持》。——第121页。","language":"中文","translation":false},{"id":"capital-4-125","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【63】 但丁《神曲》天堂篇第二十四首歌。——第122页。","language":"中文","translation":false},{"id":"capital-4-126","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[65] “赫拉克利特说：……火变成万物，万物又变成火，就象金变成货物，货物变成金一样。”（斐·拉萨尔《爱非斯的晦涩哲人赫拉克利特的哲学》1858年柏林版第1卷第222页）拉萨尔在对这句话的注解中（箄224页注3〉，错误地把货币说成只是价值符号。","language":"中文","translation":false},{"id":"capital-4-127","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【64】 见《马克思恩格斯全集》中文版第13卷第79页。——第124页。","language":"中文","translation":false},{"id":"capital-4-128","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【65】 “真爱情的道路决不是平坦的”（《The course of true love never does run smooth》）——莎士比亚《仲夏夜之梦》第一幕第一场。——第126页。","language":"中文","translation":false},{"id":"capital-4-129","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【66】 “诗人的分散的肢体”（《Disjecta membra poetae》）——引自贺雷西《讽刺诗集》第一卷第四首。——第126、380、403、516页。","language":"中文","translation":false},{"id":"capital-4-130","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[66] “每次卖都是买”（魁奈医生《关于商业和手工业者劳动的问答》，［载于］德尔编《重农学派》1846年巴黎版第1部第170页)，或者象魁奈在他的《一般原理》中所说：“卖就是买。”【67】","language":"中文","translation":false},{"id":"capital-4-131","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【67】 马克思在这里引用的是杜邦·德·奈穆尔的著作《魁奈医生的学说，或他的社会经济学原理概述》（《Maximes du docteur Quesnay, ou Resume de ses principes d'economie sociale》)，载于《重农学派》，附欧·德尔的绪论和评注，1846年巴黎版第1部第392页（《Physiocrates》. Avec une introduction et des commentaires par E. Daire. Partie I, Paris, 1846, p. 392）。——第127页。","language":"中文","translation":false},{"id":"capital-4-132","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[67] “一个商品的价格只能用另一个商品的价格来支付。”（里维埃尔的迈尔西埃《政治社会天然固有的秩序》,［载于］德尔编《重农学派》第2部第554页）","language":"中文","translation":false},{"id":"capital-4-133","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[68] “要有货币，就得先卖。”（同上，第543页）","language":"中文","translation":false},{"id":"capital-4-134","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[69] 象前面说过的，金或银的生产者是例外，他们拿自己的产品去交换，用不着先卖。","language":"中文","translation":false},{"id":"capital-4-135","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【68】 货币没有臭味（non olet）——这句话是罗马皇帝韦斯帕西安(69—79年）对他的儿子说的，因为他的儿子不同意他征收专门的厕所税。——第129页。","language":"中文","translation":false},{"id":"capital-4-136","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[70] “货币在我们手中代表我们要买的东西，它也代表我们取得货币时卖出的东西。”（里维埃尔的迈尔西埃《政治社会天然固有的秩序》，［载于］德尔编《重农学派》 第2卷第586页）","language":"中文","translation":false},{"id":"capital-4-137","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[71] “这样，就有四个终点和三个契约当事人，其中有一个人出现两次。”（列特隆《就价值、流通、工业、国内外贸易论社会利益》第909页）","language":"中文","translation":false},{"id":"capital-4-138","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[72] 第2版注：这个现象虽然很明显，但是往往为政治经济学家所忽略，尤其是为庸俗的自由贸易论者所忽略。","language":"中文","translation":false},{"id":"capital-4-139","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[73] 参看我在《政治经济学批判》第74—76页【69】对詹姆斯·穆勒的评论。在这里，经济学辩护士的方法有两个特征。第一，简单地抽去商品流通和直接的产品交换之间的区别，把二者等同起来。第二，企图把资本主义生产当亊人之间的关系,归结为商品流通所产生的简单关系，从而否认资本主义生产过程的矛盾。但商品生产和商品流通是极不相同的生产为式都具有的现象，尽管它们在范围和作用方面各不相同。因此，只知道这些生产方式所共有的抽象的商品流通的范畴，还是根本不能了解这些生产方式的不同特征，也不能对这些生产方式作出判断。任何一门科学都不象政治经济学那样，流行着拿浅显的普通道理来大肆吹嘘的风气。例如，让·巴·萨伊由于知道商品是产品，就断然否定危机。","language":"中文","translation":false},{"id":"capital-4-140","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【69】 见《马克思恩格斯全集》中文版第13卷第86—88页。——第133页。","language":"中文","translation":false},{"id":"capital-4-141","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[74] 即使商品一再出卖（在这里，这种现象对我们来说还不存在)，它也会在最后一次出卖时，由流通领域落入消费领域，以便在那里充当生活资料或生产资料。】","language":"中文","translation":false},{"id":"capital-4-142","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[75] “它〈货币〉除了产品賦予它的运动之外，没有别的运动。”（列特隆《就价值、流通、工业、国内外贸易论社会利益》第885页）","language":"中文","translation":false},{"id":"capital-4-143","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[76] “正是产品使它〈货币〉运动，使它流通……它〈即货币〉运动的速度可以补充它的数量。必要时，它会一刻不停地从一个人的手中转到另一个人的手中。”（列特隆《就价值、流逋、工业、国内外贸易论社会利益》第915、916页）","language":"中文","translation":false},{"id":"capital-4-144","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[77] “因为货币……是买和卖的普遍的尺度，所以每一个要卖东西而找不到买者的人，总以为他的商品卖不出去是因为国内缺乏货币；因此到处都叫嚷缺乏货币。然而这是一个大错误……那些叫嚷缺乏货币的人究竟要什么呢？……租地农民抱怨……他以为，如果国内有较多的货币，他的货物就可以卖到好价钱。看来他要的不是货币，而是他想卖但又卖不出去的谷物和牲畜的好价钱……为什么他卖不到好价钱呢？……1.或者是因为国内谷物和牲畜太多，到市场上来的人大多数都象他那样要卖，但只有少数人要买；2.或者是因为通常的出口停滞……3.或者是因为消费缩减，例如，人们由于贫困，不能再花费过去那样多的生活费用。可见，有助于租地农民出售货物的，不是增加货币，而是消除这三个真正造成市场缩减的原因中的任何一个原因……批发商和零售商也同样要货币，就是说，因为市场停滞，他们要把他们经营的货物销售出去……没有比财富不断转手更能使国家繁荣的了。”(散见达德利·诺思爵士《贸易论》1691年伦敦版第11-15页)赫伦施万德的骗术总括起来就是：由商品性质引起并在商品流通中表现出来的矛盾，通过增加流通手段就可以消除。认为流通手段不足造成生产过程和流通过程的停滞，是一种流行的错觉，但决不能由此反过来说，例如，官方采取“通货管理”的拙劣手段所造成的流通手段的真正不足，也不会引起停滞。","language":"中文","translation":false},{"id":"capital-4-145","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[78] “推动一国商业，窬要一定数量和比例的货币，过多或过少都对商业有害。这正象在小零售业中要有一定量的法寻来把银币换开和结算用最小的锒币也无法处理的帐目……贸易所需要的法寻量的比例，取决于购买者的人数、他们购买的次数，首先是取决于最小的银币的价值，同样，我国商业所需要的货币（金币或银币）的比例，取决于交换的次数和支付额的大小。”(威廉·配第《赋税论》1667年伦敦版第17页）阿·杨格在他的《政治算术》（1774年伦敦版）中维护受到詹·斯图亚特等人攻击的休谟的理论，书中专列一章，题名是《价格取决于货币量》，见该书第112页及以下各页。我在《政治经济学批判》第149页上【70】曾经指出：“他（亚·斯密）把流通中的铸币量问题悄悄地抹掉了，因为他完全错误地把货币当作单纯的商品。”这句话只是对于亚·斯密专门论述货币的那些地方才是适用的。例如，在批评以前的政治经济学体系时，斯密偶尔说出了正确的看法：“每一个国家的铸币量取决于该国靠铸币而流通的商品的价值……每一个国家每年买卖的货物的价值，要求有一定量的货币来使货物流通，并把它们分配给它们的真正的消费者，但不能使用比这更多的货币。流通的渠道必然会吸收一个使自己达到饱和的数量，但决不会容纳更多的数量。”（《国富论》［第3卷］第4篇第1章［第87、89页］）与此相似，亚·斯密在这部著作的开头，曾专门颂扬分工，但后来，在最后一篇论述国家收入的源泉时，他又偶尔重复他的老师亚·弗格森的话，谴责了分工。","language":"中文","translation":false},{"id":"capital-4-146","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【70】 见《马克思恩格斯全集》中文版第13卷第158页。——第143页。","language":"中文","translation":false},{"id":"capital-4-147","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[79] “在每一个国家，随着民间的金银量的增加，货物的价格必定上涨，因此，如果任何一个国家的金银减少，那末一切货物的价格也必将随着货币的减少而相应地跌落。”(杰科布·范德林特《货币万能》1734年伦敦版第5页)把范德林特的著作同休谟的《论丛》仔细对照后，我丝毫不怀疑，休谟知道并且利用了范德林特这部在别的方面也很重要的著作。流通手段量决定价格的看法，巴尔本以及更早期的著作家就曾提出过。范德林特说：“无限制的贸易不会造成任何不便，而只会带来很大的好处，因为当一个国家的现金量由于这种贸易而减少时(这是禁令所要防止的)，流入现金的国家的一切货物价格必然会随着该国现金量的增加而上涨……我国的工业产品以及其他各种货物会很快地跌价，从而又造成对我们有利的贸易差额，这样，货币就会流回我国。”(同上，第43、44页)","language":"中文","translation":false},{"id":"capital-4-148","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[80] 不言而喻，每一种商品的价格构成全部流通商品的价格总额的一个要素。但完全不能理解的是，为什么彼此不可通约的使用价值总量应同一个国家现有的金或银的总量相交换。如果大胆地幻想一下，把商品世界当作一个唯一的总商品，每一个商品只是它的相应部分，那我们就会得到一个美妙的算式：总商品=x英吨金，商品A=总商品的一定部分=x英吨金的同一部分。孟德斯鸠当真这样说过：“如果我们把世界上现有的金银量同现有的商品总量相比较，那末每个单个产品或商品一定可以同一定量的货币相比较。我们假定世界上只有一种产品或一种商品，或者说，只有一种东西可以买，而且它象货币那样可以分割，这个商品的一定部分就会相当于货币量的一定部分；这个商品总量的一半相当于货币总量的一半，等等……商品价格的决定总是基本上取决于商品总量和货币符号总量之间的比例。”(孟德斯鸠《论法的精神》，《孟德斯鸠全集》第3卷第12、13页)关于李嘉图和他的学生詹姆斯·穆勒、奥维尔斯顿勋爵等人对这一理论的进一步发展，可参看《政治经济学批判》第140-146页、第150页及以下各页【71】。约·斯·穆勒先生凭他惯用的折衷逻辑，懂得既要赞成他父亲詹姆斯·穆勒的见解，又要赞成相反的见解。他在自己的教科书纲要《政治经济学原理》的序言(第1版)中，以当代的亚当·斯密自居，如果把该书的正文同这篇序言比较一下，真不知道究竟应当赞扬这个人的天真呢，还是赞扬那些诚心诚意地承认他是当代亚当·斯密的公众的天真。其实他同亚当·斯密相比，就象卡尔斯的威廉斯·卡尔斯将军同威灵顿公爵相比一样。约·斯·穆勒先生在政治经济学方面进行的既不广也不深的独创研究，在1844年他出版的小册子《略论政治经济学的某些有待解决的问题》里全部包括了。洛克直截了当地说明了金银没有价值和金银价值取决于金银量这二者之间的关系。他说：“人们一致同意赋予金银一个想象的价值……在这些金属中所看到的内在价值无非是它们的量。”(《论降低利息和提高货币价值的后果》1691年，［载于］《洛克著作集》1777年版第2卷第15页)","language":"中文","translation":false},{"id":"capital-4-149","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【71】 见《马克思恩格斯全集》中文版第13卷第149—156、159页及以下各页。——第144页。","language":"中文","translation":false},{"id":"capital-4-150","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[81] 当然，探讨造币税之类的细节，决不是我的目的。但是，为了驳斥浪漫主义的献媚者亚当·弥勒对“英国政府免费造币”的“慷慨精神”的赞扬【72】，可以引用达德利·诺思爵士的一段话：“金银象其他的商品一样，有它的来潮和退潮。只要从西班牙运到一批金银……就被送往伦敦塔去铸造。不久又会需要金条和银条，以便再输出。如果金条和银条都没有了，而是恰巧都用来造币了，那怎么办呢？那就把铸币再熔化；这不会有什么损失，因为所有者对造币不用花费分文。但国家受到损失，不得不为了喂驴子而支付捆草料的费用。如果商人〈诺思本人是査理二世时代的一个大商人〉必须支付造币费，他就不会轻易地把他的银送到伦敦塔去了，而且铸币总是会比未铸的银有更高的价值了”（诺思《贸易论》1691年伦教版第18页）","language":"中文","translation":false},{"id":"capital-4-151","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【72】 亚·亨·弥勒《治国艺术原理》1809年柏林版第2册第280页（A. H. Muller. 《Die Elemente der Staatskunst》. Theil II, Berlin,1809，280）。——第145页。","language":"中文","translation":false},{"id":"capital-4-152","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[82] 如果银币从来不超过小额支付所需的数量，它就不可能积累到足以进行巨额支付的数量……用金进行巨額支付，也必然包含用金进行零售贸易：金币的所有者，拿金币进行小额购买时，除得到所买的商品外，还可找回银币；这样，那些本来会成为零售商的负担的银币余额，就会离开零售商，回到总流通中去。但如果银的数量多到不用金就可以进行小额支付，那末，零售商人从小额购买中就只能得到银，而这些银就必然会在他的手中积累起来。”（大卫·布坎南《大不列颠赋税和商业政策的研究》1844年爱丁堡版第248、249页）","language":"中文","translation":false},{"id":"capital-4-153","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[83] 清朝户部右侍郎王茂荫向天子上了一个奏折，主张暗将官票宝钞改为可兑现的钞票。在1854年4月的大臣审议报告中，他受到严厉申斥。他是否因此受到笞刑，不得而知。审议报告最后说：“臣等详阅所奏……所论专利商而不使于国。”（《帝俄驻北京公使馆关于中国的著述》，卡·阿伯尔博士和弗·阿·梅克伦堡译自俄文，1858年柏林版第1卷第54页）关于金币在流通中不断磨损的问题，英格兰银行的一位“经理”曾在“上院委员会”（银行条例委员会）上作证说：“每年都有一批新的sovereigns〈不是政治上的君主，而是金镑的名称索维林【73】〉变得过轻。在一年中以十足重量流通的一批索维林，经过这一年的磨损，到下一年放在天平上就重量不足了。”（《1848年上院委员会》第429号）","language":"中文","translation":false},{"id":"capital-4-154","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【73】 文字游戏：英语《Sovereign》一词既有“君主、帝王”的意思，又是一英镑金币的名称。——第147页。","language":"中文","translation":false},{"id":"capital-4-155","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[84] 第2版注：甚至最优秀的货币问题著作家，对货币的各种职能的理解也是很模糊的，例如，富拉顿下面的一段话就是证明：“就我们的国内交换来说，通常由金币和银币执行的各种货币职能，同样可以有效地由不兑现的纸币的流通来执行，而这种纸币除依法获得的人为的约定的价值外，没有任何别的价值。我想，这个事实是任何人都不能否认的。只要纸币发行量保持在应有的限度内，这种价值就完全能适合于内在价值的目的，甚至使价值标准成为多余。”（富拉顿《论流通手段的调整》1845年伦敦第2版第21页）这就是说，由于货币商品在流通中可以被单纯的价值符号代替，作为价值尺度和价格标准的货币商品就成为多余的了！","language":"中文","translation":false},{"id":"capital-4-156","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[85] 由于金银作为铸币或只执行流通手段的职能时，变成了它们自己的符号，于是尼古拉·巴尔本就推论说，政府有权“提髙货币价值”，就是说，例如，可以替名叫格罗申的银量起一个较大银量的名称塔勒，这样，就可以用格罗申当塔勒来偿还债务。“货币因经常点数而磨损和减轻……在交易中，人们注意的只是货币的名称和通用与否，而不是银的量……国家的权威使金属成为货币。”（尼·巴尔本《新币轻铸论。答洛克先生关于提髙货币价值的意见》第29、30、25页）","language":"中文","translation":false},{"id":"capital-4-157","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【74】 比·布阿吉尔贝尔《法国详情》，载于《十八世纪的财政经济学家》，1843年巴黎版第213页（P. Boisguillebert.《Le detail de la France》. In: 《Economistes financiers du XVIII-e siecle》. Paris, 1843, p. 213）。——第150页。","language":"中文","translation":false},{"id":"capital-4-158","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[86] “货币财富无非是……已经转化为货币的产品财富。”（里维埃尔的迈尔西埃《政治社会天然固有的秩序》第573页〉“产品形式上的价值只是改变形式而已。”(同上，第486页）","language":"中文","translation":false},{"id":"capital-4-159","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[87] “他们就是用这种办法使他们所有的货物和产品保持如此低廉的价格。”（范德林特《货币万能》第95、96页）","language":"中文","translation":false},{"id":"capital-4-160","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[88] “货币是一种抵押品。”(约翰·贝勒斯《论贫民、工业、贸易、殖民地和道德堕落》1699年伦敦版第13页）","language":"中文","translation":false},{"id":"capital-4-161","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[89] 严格地说，买要以下面一点为前提：金或银已经是商品的转化形态，或者说，是卖的产物。","language":"中文","translation":false},{"id":"capital-4-162","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[90] 法国笃信基督教的国王亨利三世，抢劫了修道院等地的圣物，以便把它们变成银。大家知道，弗西斯人抢劫德尔斐神庙的财宝曾在希腊史上起了什么作用。众所周知，古代人把神庙看作商品之神的住所。神庙是“神圣的银行”。以经商为主的民族腓尼基人，认为货币是万物的转换形式。因此，那些在爱神节委身于外来人的少女把作为报酬得来的钱献给女神，是很自然的事。","language":"中文","translation":false},{"id":"capital-4-163","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[91] “金子！黄黄的，发光的，宝贵的金子！","language":"中文","translation":false},{"id":"capital-4-164","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"只这一点点儿，就可以使黑的变成白的，丑的变成美的，","language":"中文","translation":false},{"id":"capital-4-165","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":165,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"错的变成对的，卑贱变成尊贵，老人变成少年，懦夫变成勇士。","language":"中文","translation":false},{"id":"capital-4-166","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":166,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"吓！你们这些天神们啊，为什么要给我这东西呢？","language":"中文","translation":false},{"id":"capital-4-167","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":167,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"嘿，这东西会把你们的祭司和仆人从你们的身旁拉走；","language":"中文","translation":false},{"id":"capital-4-168","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":168,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"把健汉头颅底下的枕垫抽去；","language":"中文","translation":false},{"id":"capital-4-169","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":169,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"这黄色的奴隶可以使异教联盟，同宗分裂；","language":"中文","translation":false},{"id":"capital-4-170","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":170,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"它可似使受咒诅的人得福，使害着灰白色的癞病的人为众人所敬爱；","language":"中文","translation":false},{"id":"capital-4-171","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":171,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"它可以使窃賊得到髙爵显位，和元老们分庭抗礼；","language":"中文","translation":false},{"id":"capital-4-172","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":172,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"它可以使鸡皮黄脸的寡妇重做新娘……","language":"中文","translation":false},{"id":"capital-4-173","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":173,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"来，该死的土块，你这人尽可夫的娼妇……”（莎士比亚《雅典的泰门》）","language":"中文","translation":false},{"id":"capital-4-174","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":174,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[92] “人间再没有象金钱这样坏的东西到处流通，","language":"中文","translation":false},{"id":"capital-4-175","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":175,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"这东西可以使城邦毁灭，使人们被赶出家乡，","language":"中文","translation":false},{"id":"capital-4-176","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":176,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"把善良的人教坏，使他们走上邪路，作些可耻的事，","language":"中文","translation":false},{"id":"capital-4-177","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":177,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"甚至叫人为非作歹，干出种种罪行。”","language":"中文","translation":false},{"id":"capital-4-178","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":178,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"(索福克勒斯《安提戈涅》）","language":"中文","translation":false},{"id":"capital-4-179","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":179,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[93] “贪婪想把普路托从地心里拖出来。”（阿泰纳奥斯《学者们的宴会》〉","language":"中文","translation":false},{"id":"capital-4-180","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":180,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[94] “尽量增加每一种商品的卖者的人数，尽量减少买者的人数，这是政治经济学的一切措施的枢纽。”（维里《政治经济学研究》第52、53页）","language":"中文","translation":false},{"id":"capital-4-181","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":181,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【75】 德·狄德罗《一七六七年的沙龙》。——第154页。","language":"中文","translation":false},{"id":"capital-4-182","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":182,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[95] “一个国家要进行贸易，必须有一定数量的金属货币，这个数量随着情况的需要而变化，时而增多，时而减少…… 货币的这种涨落，无需政治家的任何协助，能够自行调节…… 两只吊桶交替工作：货币不足时，用金属块来铸造；金属块不足时，把货币熔化掉。”（达·诺思爵士《贸易论》［附言］第3页）长期在东印度公司【76】任职的约翰·斯图亚特·穆勒证实，在印度银饰品仍然直接起着贮藏货币的作用。“利率高时，银饰品送往造币厂，利率低时，它又恢复原状。”（约·斯·穆勒的证词，1857年《银行法报告》第2084，2101号）根据1864年关于印度金银输入和输出的议会文件【77】，1863年金银入超19 367 764镑。在1864年以前的8年间，贵金属入超109 652 917镑。在 本世纪中，印度铸造的货币远远超过200 000 000镑。","language":"中文","translation":false},{"id":"capital-4-183","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":183,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【76】 东印度公司是存在于1600年至1858年的英国贸易公司，它是英国在印度、中国及其他亚洲国家推行殖民主义掠夺政策的工具。从十八世纪中叶起，公司拥有军队和舰队，成为巨大的军事力量。在公司的名义下，英国殖民主义者完成了对印度的占领。公司长期垄断了对印度的贸易，并且操纵了这个国家最重要的管理职能。1857—1859年印度的民族解放起义迫使英国人改变了他们的殖民统治的形式：公司被撤销，印度被宣布为不列颠王国的领地。——第154、820页。","language":"中文","translation":false},{"id":"capital-4-184","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":184,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【77】 《东印度（金银条块）。答可尊敬的下院1864年2月8日的质问》（《East India （Bullion）. Return to an Address of the Honourable the House of Commons, dated 8 February 1864》）。——第154页。","language":"中文","translation":false},{"id":"capital-4-185","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":185,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[96] 路德把作为购买手段的货币和作为支付手段的货币区别开来。“你使我两头受损失：这里我不能支付，那里我不能购买。”(马丁·路德《给牧师们的谕示：讲道时要反对高利贷》1540年维登堡版）","language":"中文","translation":false},{"id":"capital-4-186","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":186,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[97] 下面一点可以说明十八世纪初期英国商人中的债务人和债权人的关系：“英国商人中间盛行的那种残酷精神，是在任何其他社会和世界上任何其他国家所看不到的。”（《论信贷和破产法》1707年伦敦版第2页）","language":"中文","translation":false},{"id":"capital-4-187","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":187,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[98] 第2版注：从引自我在1859年出版的著作的如下一段话中可以看出，为什么我在本文中没有谈到相反的形式：“相反，在G—W过程中，货币可以在其使用价值实现之前，或者说，在商品让渡之前，作为现实的购买手段转让出去，从而实现商品的价格。例如通常的预付货款的形式就是如此。英国政府向印度农民购买鸦片时就是采取这种形式……但是，这里货币不过是在我们已经知道的购买手段的形式上起作用……诚然，资本也是以货币形式预付的……可是这个观点不属于简单流通的范围。”(《政治经济学批判》1859年柏林版第119、120页【78】)","language":"中文","translation":false},{"id":"capital-4-188","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":188,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【78】 见《马克思恩格斯全集》中文版第13卷第130页。——第157页。","language":"中文","translation":false},{"id":"capital-4-189","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":189,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[99] 本文所谈的货币危机是任何普遍的生产危机和商业危机的一个特殊阶段，应同那种也称为货币危机的特种危机区分开来。后者可以单独产生，只是对工业和商业发生反作用。这种危机的运动中心是货币资本，因此它的直接范围是银行、交易所和财政。（马克思在第3版上加的注）","language":"中文","translation":false},{"id":"capital-4-190","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":190,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[100] “这种由信用主义突然转变到货币主义，使得实际恐慌又加上了理论恐惧，流通的当事人在他们自己的关系的深不可测的秘密面前瑟瑟发抖了。”（马克思《政治经济学批判》1859年柏林版第126页【79】〉“穷人没有工作，因为富人没有钱雇用他们，虽然他们和过去一样，拥有同样的土地和劳动力，可以用来生产食物和衣服；正是这些，而不是货币，构成一个国家的真正财富。”〖约翰·贝勒斯《关于创办一所劳动学院的建议》1696年伦敦版第3—4页）","language":"中文","translation":false},{"id":"capital-4-191","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":191,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【79】 见《马克思恩格斯全集》中文版第13卷第136—137页。——第159页。","language":"中文","translation":false},{"id":"capital-4-192","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":192,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[101] 下面这段话可以说明“商业之友”是如何利用这种时机的：“一次〈1839年）一位贪婪的老银行家〈西蒂区的〉在他的私人房间里，坐在写字桌前，掲开桌盖，取出成捆的钞票给他的一位朋友看，并洋洋得意地说，这是60万镑，收回这些钞票，是为了使银根吃紧，在当天3点钟以后，再把它们全部投放出去。”（[亨·罗伊]《兑换理论。1844年的银行法令》1864年伦敦版第81页）1864年4月24日，半官方报纸《观察家报》报道：“现在流传着一种很奇怪的谣言，说已经有一种使银根吃紧的手段……不论采用这类诡计看来是多么值得怀疑，但是这种谣言广为流传，确实值得一提。”","language":"中文","translation":false},{"id":"capital-4-193","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":193,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[102] “某日締结的购买总额或契约总额不会影响该日流通的货币量，但是在绝大多数场合，它会变为各种各样的票据，用来取得将来在或远或近的某日进入流通的货币量……今天开的票据或今天提供的信贷无论在数目、总额或期限上都不必同明天或后天开的票据或提供的信贷有什么相似之处。相反地，许多今天的票据和信贷到期时会同以前在许多完全不定的日期欠下的债务相抵，以12个月、6个月、3个月或1个月为期的票据往往凑在一起，以致使某日到期的债务总额特别膨胀起来……”(《通货论。给苏格兰人民的一封信》，英国一银行家著，1845年爱丁堡版，散见第29、30页）","language":"中文","translation":false},{"id":"capital-4-194","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":194,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[103] 为了举例说明在真正的商业活动中所用的现实的货币是多么少，我们在这里列出伦敦最大的贸易公司之一（莫里逊—狄龙公司〉的全年的货币收支表。1856年该公司的交易额达好几百万镑，现在折合成一百万镑计算。","language":"中文","translation":false},{"id":"capital-4-195","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":195,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"收入（单位：镑） 支出（单位：镑）","language":"中文","translation":false},{"id":"capital-4-196","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":196,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"定期支付的银行家和商人的票据 533 596 定期支付的票据 302 674","language":"中文","translation":false},{"id":"capital-4-197","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":197,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"见票即付的银行支票等 357 715 伦敦各银行支票 663 672","language":"中文","translation":false},{"id":"capital-4-198","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":198,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"地方银行券 9 627 英格兰银行券 22 743","language":"中文","translation":false},{"id":"capital-4-199","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":199,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"英格兰银行券 68 554 金 9 427","language":"中文","translation":false},{"id":"capital-4-200","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":200,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"金 28 089 银和铜 1 484","language":"中文","translation":false},{"id":"capital-4-201","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":201,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"总计 1 000 000镑 1 000 000镑","language":"中文","translation":false},{"id":"capital-4-202","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":202,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"(《银行法特别委员会的报告》1858年7月第71页）","language":"中文","translation":false},{"id":"capital-4-203","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":203,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[104] “交易的性质在这里改变了，现在不是以货换货，不是供货和进货，而是出售和支付，一切交易……都表现为纯粹的货币业务。”（[丹·笛福]《论公共信贷》1710年伦敦第3版第8页）","language":"中文","translation":false},{"id":"capital-4-204","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":204,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[105] “货币成了万物的刽子手。”理财术是“一个蒸馏器，它使多得惊人的货物和商品蒸发，以便取得这种致命的膏汁”。“货币向全人类宣战。”（布阿吉尔贝尔《论财富、货币和赋税的性质》，德尔编《财政经济学家》1843年巴黎版苐1卷第413、419、417，418页）","language":"中文","translation":false},{"id":"capital-4-205","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":205,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[106] 克雷格先生在1826年的议会调査委员会上说，“1824年圣灵降临节，在爱丁堡，需要如此大量的钞票，以致到11点钟，我们手里连一张钞票也没有了，我们到一家一家银行去商借，但是都没有借到，许多交易郁只好凭纸条付款。但是到了下午3点钟，所有的钞票都回到了那些发行钞票的银行。这些钞票只不过转转手而已。”在苏格兰，.虽然钞票的实际平均流通量还不到300万镑，但是到了一年的各个支付期限，银行家手里所有的钞票（共约700万镑）都要动用。在这种情况下，-钞票只是履行一种单一的特殊的职能，这个职能一经完成，它们立刻又各自回到那些发行钞票的银行。(约翰·富拉顿《论流通手段的调整》1845年伦敦第2版第86页注）为了便于了解，这里附带说一下，在富拉顿写这本书的时候，在苏格兰支付存款，不是用支票，而是用钞票。","language":"中文","translation":false},{"id":"capital-4-206","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":206,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[107] 有人问：“如果一年的贸易额必需有4000万，那末这600万〈金〉对于贸易所需的周转和流通是否够用呢？”配第以他惯用的巧妙方法回答说：“我回答说够用，如果周转期很短，只有一个星期，象贫苦的手工业者和工人每星期六收付货币那样，那末要花费4000万，有100万的40/52就够了；如果周转期是一季，按照我们交租纳税的习惯，那就要有1000万。因此，假定支付期限总起来说是从1个星期到13个星期之间的平均数，那末1000万加上100万的40/52，再求其半数，约等于550万，就是说，我们有550万就够了。”（威廉·配第《爱尔兰政治剖视。1672年》1691年伦敦版第13、14页【80】）","language":"中文","translation":false},{"id":"capital-4-207","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":207,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【80】 马克思在这里引用的是威·配第的著作《爱尔兰政治剖视。1672年》1691年伦敦版（《The Political Anatomy of Ireland. 1672》. London. 1691）的附录《献给英明人士》（《Verbum Sapienti》)。——第162、166、302页。","language":"中文","translation":false},{"id":"capital-4-208","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":208,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[108] 因此，法律规定国家银行只能贮藏那种在国内起货币作用的贵金屑，是荒唐的。例如，英格兰银行自己制造的那些“可爱的麻烦”，是众所周知的。关于金银相对价值发生变动的几个大的历史时代，可参看卡尔·马克思《政治经济学批判》第136页及以下各页。【81】——第2版补注：罗伯特·皮尔爵士在他的1844年的银行法中，力图摆脱这种困境，即允许英格兰银行发行以银块作准备金的银行券，但银储备不得超过金储备的四分之一。同时，银的价值按照它在伦敦市场上的市场价格（以金计算的〉来估价。｛第4版注：现在我们又处在金银的相对价值剧烈变动的时代。大约25年以前，金银的比价＝15.5：1，现在大约＝22:1，而且与金相比，银的价值还在继续跌落。其实，这主要是这两种金属的开采方法发生变革的结果。从前，金几乎完全是从淘洗含金的冲积层即含金岩石的风化物中获得的。现在，这种方法已经不够用了，让位于开采含金石英矿脉的方法，后一种方法虽然古人早已知道（狄奥多洛斯《史学丛书》第3卷第12—14章），但过去一直居于第二位。另一方面，不仅美国落基山脉的西部发现了新的大银矿，而且还铺设铁路来开发这个银矿和墨西哥银矿，这就有可能运去新式机器和燃料，使银的开采规模空前扩大，开采费用大大降低。但是，这两种金属在矿脉中的存在方式是大不相同的。金大都是夭然的，但是它混杂在石英中，数量极少，因此必须把整批矿石粉碎，而后淘金，或用水银提取金。从100万克石英中，往往只能采到1－3克金，难得采到30—60克金。银很少天然是纯的，但它存在于比较容易从矿脉中开采的特殊的矿石中，这些矿石通常含银40—90％；或者它也少量地混在某些本身值得开采的矿石如铜、铅等等中。从这里已经可以看出，采金所耗费的劳动增多了，而采银所耗费的劳动却大大减少了，所以银的价值降低是不言而喻的。假如现在不是用人为的办法把银的价格维持在一定的水平上，那末银的价值降低一定会表现为价格的更大的跌落。目前美洲银矿还只开采了很少一部分，因此完全可以预料，银的价值在长时期内还会继续降低。此外，用于制造日用品和奢侈品的银相对地减少，银制品为镀银品和铝制品等等所代替，这也必然会促使银的价值降低。因此可以断定，复本位主义想靠强制的国际行市来把银的价值比例提髙到从前的1：15.5是一种空想。银在世界市场上将越来越失去它的货币属性。——弗·恩·｝","language":"中文","translation":false},{"id":"capital-4-209","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":209,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【81】 见《马克思恩格斯全集》中文版第13卷第146—147页。——第163页。","language":"中文","translation":false},{"id":"capital-4-210","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":210,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[109] 重商主义体系把通过金银来结算贸易顺差当作世界贸易的目的，而重商主义体系的反对者也完全误解了世界货币的职能。我在评论李嘉图时曾详细说明，对贵金属的国际运动的错误理解，不过是反映了对调节流通手段量的规律的错误理解。（《政治经济学批判》1859年柏林版第150页及以下各页【82】）他的错误教条是：“贸易逆差只能是流通手段过剩的结果……铸币输出是因为它价值低廉，不是逆差的结果，而是逆差的原因。”【83】这个教条我们在巴尔本那里已经见过：“贸易差额，如果它存在的话，不是货币从一国输出的原因。相反地，货币输出是由各国的贵金属价值之间的差别引起的。”（尼·巴尔本《新币轻铸论。答洛克先生关于提高货币价值的意见》第59页）麦克库洛赫在《政治经济李文献。各科分类书目》〖1845年伦敦版）中，称赞巴尔本的这种先见之明，但十分机智地避而不谈“通货原理”【84】的荒谬前提在巴尔本那里所表现的素朴形式。这篇书目没有批判性，甚至是不正直的，这种情况在他叙述货币学说史的几章中达到了顶点，因为在这里，麦克库洛赫向奥维尔斯顿勋爵（前银行家劳埃德）大献殷勤，把他捧为“锒行界公认的领袖”。","language":"中文","translation":false},{"id":"capital-4-211","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":211,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【82】 见《马克思恩格斯全集》中文版第13卷第158页及以下各页。——第164页。","language":"中文","translation":false},{"id":"capital-4-212","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":212,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【83】 马克思在这里引用的是大·李嘉图的著作《金银条块价格高昂是银行券贬值的证明》1811年伦敦修订第4版（《The High Price of Bullion a Proof of the Depreciation of Bank Notes》. The Fourth Edition, Corrected. London, 1811）。——第164页。","language":"中文","translation":false},{"id":"capital-4-213","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":213,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"【84】 “通货原理”（《Currency principle》）或“通货学派”——是主张货币数量论学派的变种之一。它的代表们断言，商品的价值和价格决定于流通领域中的货币数量。他们的目的是要保持稳定的货币流通，并认为纸币的必需的黄金保证和根据贵金属进出口情况调整纸币的发行量是达到这一目的的唯一手段。从这些错误的理论前提出发，“通货学派”认为生产过剩的经济危机的决定性原因，是由于他们所宣布的货币流通规律遭到破坏。“通货学派”理论在十九世纪上半叶在英国十分流行。但是英国政府以这种理论作拫据的种种尝试〈1844年银行法）没有收到任何成效，而只是证明它在科学上是完全站不住脚的，在实践上是毫不中用的（参看《马克思恩格斯全集》中文版第13卷第172—176页）。——第164、680页。","language":"中文","translation":false},{"id":"capital-4-214","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":214,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[110] 例如，在发放补助金，为进行战争或恢复银行现金支付而实行借款等等情况下，价值正是要求具有货币形式。","language":"中文","translation":false},{"id":"capital-4-215","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":215,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[110a] 第2版注：“在金属本位的国家，有了货币贮藏的机构，即使没有普遍流通的明显支持，也能够执行清偿国际债务的每种必要的职能，事实上，要证明这点，我想再也没有比下面这个例子更有说服力了：法国在遭到外国侵略的毁灭性破坏后刚刚开始恢复，就能够轻易地在27个月内偿付了同盟国加在它身上的近2千万的战争赔款，而且其中很大一部分是用金属货币偿付的，但是却没有引起国内货币流通的显著缩减或混乱，也没有引起汇率的任何急剧的波动。”（富拉顿《论流通手段的调整》第141页）{第4版注：我们还可以举一个更明显的例子。同一个法国在1871—1873年中的30个月内，轻易地偿付了相当于上述数目10倍多的巨额战争赔款，而且相当大一部分也是用金属货币偿付的。——弗·恩·}","language":"中文","translation":false},{"id":"capital-4-216","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":216,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[111] “货币根据各国的需要在各国间分配……因为它总是被产品所吸引。”（列特隆《就价值、流通、工业、国内外贸易论社会利益》第916页）“不断提供金银的矿山足以向每个国家提供所需要的数量。”（杰·范德林特《货币万能》第40页）","language":"中文","translation":false},{"id":"capital-4-217","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":217,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[112] “汇率每周都会涨落，在一年的某些时间内达到的比率对一国不利，而在另一些时间内又对它有利。”（巴尔本《新币轻铸论。答洛克先生关于提髙货币价值的意见》第39页）","language":"中文","translation":false},{"id":"capital-4-218","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":218,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[113] 一旦加上兑换银行券的基金的职能，这些不同的职能彼此就会发生危险的冲突。","language":"中文","translation":false},{"id":"capital-4-219","author":"马克思","title":"资本论·第一卷","location":"第三章 货币或商品流通","page":4,"paragraph":219,"url":"https://www.marxists.org/chinese/marx/capital/03.htm","text":"[114] “超过国内贸易绝对需要的货币是死资本，不会给拥有这些货币的国家带来任何利润，除非把它们用于进出口贸易。”（约翰·贝勒斯《论贫民》第13页〉“如果我们铸币过多，那怎么办呢？我们可以把最重的铸币熔化，加工成上等餐具，金银器皿；或者把它们作为商品输往霈要或想要它们的地方；或者可以把它们拿到利率高的地方去生息。”（威廉·配第《货币略论》第39页）“货币不过是国家躯体的脂肪，过多会妨碍这一躯体和灵活性，太少会使它生病……脂肪使肌肉的动作滑润，在缺乏食物时供给营养，使肌肤丰满，身体美化，同样，货币使国家的活动敏捷，在国内歉收时用来从国外进口食物，清偿债务……使一切美化；当然〈作者最后讽刺说〉，特别是使那班富有货币的人美化。”(威廉·配第《爱尔兰政治剖视》第14、15页【80】〉","language":"中文","translation":false},{"id":"capital-5-1","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-5-2","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"商品流通是资本的起点。商品生产和发达的商品流通，即贸易，是资本产生的历史前提。世界贸易和世界市场在十六世纪揭开了资本的近代生活史。","language":"中文","translation":false},{"id":"capital-5-3","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"如果撇开商品流通的物质内容，撇开各种使用价值的交换，只考察这一过程所造成的经济形式，我们就会发现，货币是这一过程的最后产物。商品流通的这个最后产物是资本的最初的表现形式。","language":"中文","translation":false},{"id":"capital-5-4","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"资本在历史上起初到处是以货币形式，作为货币财产，作为商人资本和高利贷资本，与地产相对立[1]。然而，为了认识货币是资本的最初的表现形式，不必回顾资本产生的历史。这个历史每天都在我们眼前重演。现在每一个新资本最初仍然是作为货币出现在舞台上，也就是出现在市场上——商品市场、劳动市场或货币市场上，经过一定的过程，这个货币就转化为资本。","language":"中文","translation":false},{"id":"capital-5-5","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"作为货币的货币和作为资本的货币的区别，首先只是在于它们具有不同的流通形式。","language":"中文","translation":false},{"id":"capital-5-6","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"商品流通的直接形式是Ｗ—Ｇ—Ｗ，商品转化为货币，货币再转化为商品，为买而卖。但除这一形式外，我们还看到具有不同特点的另一形式Ｇ—Ｗ—Ｇ，货币转化为商品，商品再转化为货币，为卖而买。在运动中通过后一种流通的货币转化为资本，成为资本，而且按它的使命来说，已经是资本。","language":"中文","translation":false},{"id":"capital-5-7","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"现在我们较仔细地研究一下Ｇ—Ｗ—Ｇ这个流通。和简单商品流通一样，它也经过两个对立阶段。在第一阶段Ｇ—Ｗ（买）上，货币转化为商品。在第二阶段Ｗ—Ｇ（卖）上，商品再转化为货币。这两个阶段的统一是一个总运动：货币和商品交换，同一商品再和货币交换，即为卖商品而买商品；如果不管买和卖的形式上的区别，那就是用货币购买商品，又用商品购买货币[2]。整个过程的结果，是货币和货币交换，Ｇ—Ｇ。假如我用100镑买进2000磅棉花，然后又把这2000磅棉花按110镑卖出，结果我就是用100镑交换110镑，用货币交换货币。","language":"中文","translation":false},{"id":"capital-5-8","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"很清楚，假如Ｇ—Ｗ—Ｇ这个流通过程只是兜个圈子，是同样大的货币价值相交换，比如说，100镑和100镑交换，那末这个流通过程就是荒唐的、毫无内容的了。货币贮藏者的办法倒是无比地简单，无比地牢靠，他把100镑贮藏起来，不让它去冒流通中的风险。另一方面，不论商人把他用100镑买来的棉花卖110镑，还是100镑，甚至只是50镑，他的货币总是经过一种独特和新奇的运动，这种运动根本不同于货币在简单商品流通中的运动，例如在农民手中的运动——出售谷物，又用卖得的货币购买衣服。因此，首先我们应该说明Ｇ—Ｗ—Ｇ和Ｗ—Ｇ—Ｗ这两种循环的形式上的区别。这样，隐藏在这种形式上的区别后面的内容上的区别同时也就暴露出来。","language":"中文","translation":false},{"id":"capital-5-9","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"我们先来看一下这两种形式的共同点。","language":"中文","translation":false},{"id":"capital-5-10","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"这两种循环都分成同样两个对立阶段：Ｗ—Ｇ（卖）和Ｇ—Ｗ（买）。在其中每一个阶段上，都是同样的两个物的因素即商品和货币互相对立，都是扮演同样两种经济角色的两个人即买者和卖者互相对立。这两个循环的每一个都是同样两个对立阶段的统一，这种统一在这两种情形下都是通过三个当事人的登场而实现的：一个只是卖，一个只是买，一个既买又卖。","language":"中文","translation":false},{"id":"capital-5-11","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"但是，Ｗ—Ｇ—Ｗ和Ｇ—Ｗ—Ｇ这两个循环从一开始就不同，是由于同样两个对立的流通阶段具有相反的次序。简单商品流通以卖开始，以买结束；作为资本的货币的流通以买开始，以卖结束。作为运动的起点和终点的，在前一场合是商品，在后一场合是货币。在整个过程中起媒介作用的，在前一形式是货币，在后一形式是商品。","language":"中文","translation":false},{"id":"capital-5-12","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在Ｗ—Ｇ—Ｗ这个流通中，货币最后转化为充当使用价值的商品。于是，货币就最终花掉了。而在Ｇ—Ｗ—Ｇ这个相反的形式中，买者支出货币，却是为了作为卖者收入货币。他购买商品，把货币投入流通，是为了通过出卖这同一商品，从流通中再取回货币。他拿出货币时，就蓄意要重新得到它。因此，货币只是被预付出去。[3]","language":"中文","translation":false},{"id":"capital-5-13","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在Ｗ—Ｇ—Ｗ形式中，同一块货币两次变换位置。卖者从买者那里得到货币，又把它付给另一个卖者。整个过程以交出商品收入货币开始，以交出货币得到商品告终。在Ｇ—Ｗ—Ｇ形式中，情形则相反。在这里，两次变换位置的，不是同一块货币，而是同一件商品。买者从卖者手里得到商品，又把商品交到另一个买者手里。在简单商品流通中，同一块货币的两次变换位置，使货币从一个人手里最终转到另一个人手里；而在这里，同一件商品的两次变换位置，则使货币又流回到它最初的起点。","language":"中文","translation":false},{"id":"capital-5-14","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"货币流回到它的起点同商品是否贱买贵卖没有关系。后者只影响流回的货币额的大小。只要买进的商品再被卖掉，就是说，只要Ｇ—Ｗ—Ｇ的循环全部完成，就发生货币流回的现象。可见，作为资本的货币的流通和单纯作为货币的货币的流通之间，存在着可以感觉到的区别。","language":"中文","translation":false},{"id":"capital-5-15","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"一旦出卖一种商品所得到的货币又被用去购买另一种商品，Ｗ—Ｇ—Ｗ的循环就全部结束。如果货币又流回起点，那只是由于整个过程的更新或重复。假如我把一夸特谷物卖了3镑，然后用这3镑买了衣服，对我来说，这3镑就是最终花掉了。我和这3镑再没有任何关系。它是衣商的了。假如我又卖了一夸特谷物，货币就又流回到我的手里，但这不是第一次交易的结果，而只是这一交易重复的结果。一旦我结束了这第二次交易，又买了东西，货币就又离开我。因此，在Ｗ—Ｇ—Ｗ这个流通中，货币的支出和货币的流回没有任何关系。相反，在Ｇ—Ｗ—Ｇ中，货币的流回是由货币支出的性质本身决定的。没有这种流回，活动就失败了，或者过程就中断而没有完成，因为它的第二阶段，即作为买的补充和完成的卖没有实现。","language":"中文","translation":false},{"id":"capital-5-16","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在Ｗ—Ｇ—Ｗ循环中，始极是一种商品，终极是另一种商品，后者退出流通，转入消费。因此，这一循环的最终目的是消费，是满足需要，总之，是使用价值。相反，Ｇ—Ｗ—Ｇ循环是从货币一极出发，最后又返回同一极。因此，这一循环的动机和决定目的是交换价值本身。","language":"中文","translation":false},{"id":"capital-5-17","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在简单商品流通中，两极具有同样的经济形式。二者都是商品，而且是价值量相等的商品。但它们是不同质的使用价值，如谷物和衣服。在这里，产品交换，体现着社会劳动的不同物质的交换，是运动的内容。Ｇ—Ｗ—Ｇ这个流通则不同。乍一看来，它似乎是无内容的，因为是同义反复。两极具有同样的经济形式。二者都是货币，从而不是不同质的使用价值，因为货币正是商品的转化形式，在这个形式中，商品的一切特殊使用价值都已消失。先用100镑交换成棉花，然后又用这些棉花交换成100镑，就是说，货币兜了一个圈子又交换成货币，同样的东西又交换成同样的东西。这似乎是一种既无目的又很荒唐的活动[4]。一个货币额和另一个货币额只能有量的区别。因此，Ｇ—Ｗ—Ｇ过程所以有内容，不是因为两极有质的区别（二者都是货币)，而只是因为它们有量的不同。最后从流通中取出的货币，多于起初投入的货币。例如，用100镑买的棉花卖100镑+10镑，即110镑。因此，这个过程的完整形式是Ｇ—Ｗ—Ｇ'。其中的Ｇ'＝Ｇ＋△Ｇ，即等于原预付货币额加上一个增殖额。我把这个增殖额或超过原价值的余额叫做剩余价值。可见，原预付价值不仅在流通中保存下来，而且在流通中改变了自己的价值量，加上了一个剩余价值，或者说增殖了。正是这种运动使价值转化为资本。","language":"中文","translation":false},{"id":"capital-5-18","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"诚然，在Ｗ—Ｇ—Ｗ中，两极Ｗ和Ｗ，如谷物和衣服，也可能是大小不等的价值量。农民卖谷物的价钱可能高于谷物的价值，或者他买衣服的价钱可能低于衣服的价值。他也可能受衣商的骗。但是这种价值上的差异，对这种流通形式本身来说完全是偶然的。即使这种流通形式的两极（如谷物和衣服）是等价的，它也丝毫不会象Ｇ—Ｗ—Ｇ过程一样丧失自己的意义。在这里，两极的价值相等倒可以说是这种流通形式正常进行的条件。","language":"中文","translation":false},{"id":"capital-5-19","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"为买而卖的过程的重复或更新，与这一过程本身一样，以达到这一过程以外的最终目的，即消费或满足一定的需要为限。相反，在为卖而买的过程中，开端和终结是一样的，都是货币，都是交换价值，单是由于这一点，这种运动就已经是没有止境的了。诚然，Ｇ变成了Ｇ＋△Ｇ，100镑变成了100镑+10镑。但是单从质的方面来看，110镑和100镑一样，都是货币。而从量的方面来看，110镑和100镑一样，都是有限的价值额。如果把这110镑当作货币用掉，那它就不再起作用了。它不再成为资本。如果把它从流通中取出来，那它就凝固为贮藏货币，即使藏到世界末日，也不会增加分毫。因此，如果问题是要使价值增殖，那末110镑和100镑一样，也需要增殖，因为二者都是交换价值的有限的表现，从而具有相同的使命：通过量的增大以接近绝对的富。不错，原预付价值100镑和它在流通中所增殖的剩余价值10镑在一瞬间是有区别的，但这个区别马上又消失了。过程终了时，不是100镑原价值在一边，10镑剩余价值在另一边。得到的结果是一个110镑的价值。这个价值和原先的100镑一样，也完全适宜于开始价值增殖过程。货币在运动终结时又成为运动的开端。[5]因此，每一次为卖而买所完成的循环的终结，自然成为新循环的开始。简单商品流通——为买而卖——是达到流通以外的最终目的，占有使用价值，满足需要的手段。相反，作为资本的货币的流通本身就是目的，因为只是在这个不断更新的运动中才有价值的增殖。因此，资本的运动是没有限度的。【6】","language":"中文","translation":false},{"id":"capital-5-20","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"作为这一运动的有意识的承担者，货币所有者变成了资本家。他这个人，或不如说他的钱袋，是货币的出发点和复归点。这种流通的客观内容——价值增殖——是他的主观目的；只有在越来越多地占有抽象财富成为他的活动的唯一动机时，他才作为资本家或作为人格化的、有意志和意识的资本执行职能。因此，绝不能把使用价值看作资本家的直接目的[7]。他的目的也不是取得一次利润，而只是谋取利润的无休止的运动[8]。这种绝对的致富欲，这种价值追逐狂[9]，是资本家和货币贮藏者所共有的，不过货币贮藏者是发狂的资本家，资本家是理智的货币贮藏者。货币贮藏者竭力把货币从流通中拯救出来[10]，以谋求价值的无休止的增殖，而精明的资本家不断地把货币重新投入流通，却达到了这一目的。[10a]","language":"中文","translation":false},{"id":"capital-5-21","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"商品的价值在简单流通中所采取的独立形式，即货币形式，只是充当商品交换的媒介，运动一结束就消失。相反，在Ｇ—Ｗ—Ｇ流通中，商品和货币这二者仅仅是价值本身的不同存在方式：货币是它的一般存在方式，商品是它的特殊的也可以说只是化了装的存在方式[11]。价值不断地从一种形式转化为另一种形式，在这个运动中永不消失，从而变成一个自动的主体。如果把增殖中的价值在其生活的循环中交替采取的各种特殊表现形式固定下来，就得出这样的说明：资本是货币，资本是商品[12]。但是实际上，价值在这里已经成为一个过程的主体，在这个过程中，它不断地交替采取货币形式和商品形式，改变着自己的量，作为剩余价值同作为原价值的自身分出来，自行增殖着。既然它生出剩余价值的运动是它自身的运动，它的增殖也就是自行增殖。它所以获得创造价值的奇能，是因为它是价值。它会产仔，或者说，它至少会生金蛋。","language":"中文","translation":false},{"id":"capital-5-22","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"价值时而采取时而抛弃货币形式和商品形式，同时又在这种变换中一直保存自己和扩大自己；价值作为这一过程的扩张着的主体，首先需要一个独立的形式，把自身的同一性确定下来。它只有在货币上才具有这种形式。因此，货币是每个价值增殖过程的起点和终点。它以前是100镑，现在是110镑，等等。但货币本身在这里只是价值的一种形式，因为价值有两种形式。货币不采取商品形式，就不能成为资本。因此，货币在这里不象在货币贮藏的情况下那样，与商品势不两立。资本家知道，一切商品，不管它们多么难看，多么难闻，在信仰上和事实上都是货币，是行过内部割礼的犹太人，并且是把货币变成更多的货币的奇妙手段。","language":"中文","translation":false},{"id":"capital-5-23","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在简单流通中，商品的价值在与商品的使用价值的对立中，至多取得了独立的货币形式，而在这里，商品的价值突然表现为一个处在过程中的、自行运动的实体，商品和货币只是这一实体的两种形式。不仅如此。现在，它不是表示商品关系，而可以说同它自身发生私自关系。它作为原价值同作为剩余价值的自身区别开来，作为圣父同作为圣子的自身区别开来，而二者年龄相同，实际上只是一个人。这是因为预付的100镑只是由于有了10镑剩余价值才成为资本，而它一旦成为资本，一旦生了儿子，并由于有了儿子而生了父亲，二者的区别又马上消失，合为一体——110镑。","language":"中文","translation":false},{"id":"capital-5-24","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"因此，价值成了处于过程中的价值，成了处于过程中的货币，从而也就成了资本。它离开流通，又进入流通，在流通中保存自己，扩大自己，扩大以后又从流通中返回来，并且不断重新开始同样的循环[13]。Ｇ—Ｇ'，生出货币的货币，——资本的最初解释者重商主义者就是这样来描绘资本的。","language":"中文","translation":false},{"id":"capital-5-25","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"为卖而买，或者说得完整些，为了贵卖而买，即Ｇ—Ｗ—Ｇ'，似乎只是一种资本即商人资本所特有的形式。但产业资本也是这样一种货币，它转化为商品，然后通过商品的出售再转化为更多的货币。在买和卖的间歇，即在流通领域以外发生的行为，丝毫不会改变这种运动形式。最后，在生息资本的场合，Ｇ—Ｗ—Ｇ'的流通简化地表现为没有中介的结果，表现为一种简练的形式，Ｇ—Ｇ'，表现为等于更多货币的货币，比本身价值更大的价值。","language":"中文","translation":false},{"id":"capital-5-26","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"因此，Ｇ—Ｗ—Ｇ'事实上是直接在流通领域内表现出来的资本的总公式。","language":"中文","translation":false},{"id":"capital-5-27","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"货币羽化为资本的流通形式，是和前面阐明的所有关于商品、价值、货币和流通本身的性质的规律相矛盾的。它和简单商品流通不同的地方，在于同样两个对立过程（卖和买）的次序相反。但这种纯粹形式上的区别，是用什么魔法使这一过程的性质改变的呢？","language":"中文","translation":false},{"id":"capital-5-28","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"不仅如此。在互相进行交易的三个同行中间，只是对其中一个人来说，次序才是颠倒过来了。作为资本家，我从A手里购买商品，再把商品卖给B；作为简单的商品所有者，我把商品卖给B，然后从A手里购买商品。对A和B这两个同行来说，这个区别是不存在的。他们只是作为商品的买者或卖者出现。我自己也总是作为简单的货币所有者或商品所有者，作为买者或卖者与他们相对立。在这两个序列中，对于一个人我只是买者，对于另一个人我只是卖者；对于一个人我只是货币，对于另一个人我只是商品，不论对于这两个人中的哪一个，我都不是资本，不是资本家，不是比货币或商品更多的什么东西的代表，或者能起货币或商品以外的什么作用的东西的代表。对我来说，向A购买商品和把商品卖给B，构成一个序列。但是这两个行为之间的联系，只有对我来说才是存在的。A并不关心我同B的交易，B并不关心我同A的交易。假如我想向他们说明我把交易的序列颠倒过来而作出的特殊功绩，他们就会向我指出，是我把序列本身弄错了，整个交易不是由买开始和由卖结束，而是相反，由卖开始和由买结束。实际上，我的第一个行为买，在A看来是卖，我的第二个行为卖，在B看来是买。A和B并不满足于这一点，他们还会说，这整个序列是多余的，是耍把戏。A可以直接把商品卖给B，B可以直接向A购买商品。这样，整个交易就缩短为普通商品流通的一个单方面的行为：从A看来只是卖，从B看来只是买。可见，我们把序列颠倒过来，并没有越出简单商品流通领域，相反，我们倒应该看一看：这个领域按其性质来说，是否允许进入这一领域的价值发生增殖，从而允许剩余价值的形成。","language":"中文","translation":false},{"id":"capital-5-29","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"我们拿表现为单纯的商品交换的流通过程来说。在两个商品所有者彼此购买对方的商品，并到支付日结算债务差额时，流通过程总是表现为单纯的商品交换。在这里，货币充当计算货币，它把商品的价值表现为商品价格，但不是用它的物体同商品本身相对立。就使用价值来看，交换双方显然都能得到好处。双方都是让渡对自己没有使用价值的商品，而得到自己需要使用的商品。但好处可能不止是这一点。卖葡萄酒买谷物的A，在同样的劳动时间内，大概会比种植谷物的B酿出更多的葡萄酒，而种植谷物的B，在同样的劳动时间内，大概会比酿酒的A生产出更多的谷物。可见，与两人不进行交换而各自都不得不为自己生产葡萄酒和谷物相比，用同样的交换价值，A能得到更多的谷物，B能得到更多的葡萄酒。因此，就使用价值来看，可以说，“交换是双方都得到好处的交易”[14]。就交换价值来看，情况就不同了。","language":"中文","translation":false},{"id":"capital-5-30","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"“一个有许多葡萄酒而没有谷物的人，同一个有许多谷物而没有葡萄酒的人进行交易，在他们之间，价值50的小麦和价值50的葡萄酒相交换了。这种交换不论对哪一方来说都不是交换价值的增多，因为每一方通过这次行为得到的价值，是和他在交换以前握有的价值相等的。”[15]","language":"中文","translation":false},{"id":"capital-5-31","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"货币作为流通手段出现在商品之间，以及买和卖的行为明显地分离开来，这对事情毫无影响[16]。商品的价值在商品进入流通以前就表现为商品价格，因此它是流通的前提，不是流通的结果。[17]","language":"中文","translation":false},{"id":"capital-5-32","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"如果抽象地来考察，就是说，把不是从简单商品流通的内在规律中产生的情况撇开，那末，在这种流通中发生的，除了一种使用价值被另一种使用价值代替以外，只是商品的形态变化，即商品的单纯形式变换。同一价值，即同量的物化社会劳动，在同一个商品所有者手里，起初表现为他的商品的形式，然后是该商品转化成的货币的形式，最后是由这一货币再转化成的商品的形式。这种形式变换并不包含价值量的改变。商品价值本身在这一过程中所经历的变化，只限于它的货币形式的变化。起初，这个货币形式是待售商品的价格，然后是在价格中已经表现出来的货币额，最后是等价商品的价格。这种形式变换，象一张5镑的钞票换成若干索维林、若干半索维林和若干先令一样，本身并不包含价值量的改变。因此，商品流通就它只引起商品价值的形式变换来说，在现象纯粹地进行的情况下，就只引起等价物的交换。连根本不懂什么是价值的庸俗经济学，每当它想依照自己的方式来纯粹地观察现象的时候，也都假定供求是一致的，就是说，假定供求的影响是完全不存在的。因此，就使用价值来看，交换双方都能得到利益，但在交换价值上，双方都不能得到利益。不如说，在这里是：“在平等的地方，没有利益可言。”[18]诚然，商品可以按照和自己的价值相偏离的价格出售，但这种偏离是一种违反商品交换规律的现象[19]。商品交换就其纯粹形态来说是等价物的交换，因此，不是增大价值的手段。[20]","language":"中文","translation":false},{"id":"capital-5-33","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"因此，那些试图把商品流通说成是剩余价值的源泉的人，其实大多是弄混了，是把使用价值和交换价值混淆了。例如，孔狄亚克说：","language":"中文","translation":false},{"id":"capital-5-34","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"“认为在商品交换中是等量的价值相交换，那是错误的。恰恰相反，当事人双方总是用较小的价值去换取较大的价值……如果真的总是等量的价值交换，那任何一方都不会得到利益。但双方都得到利益，或都应该得到利益。为什么呢？物的价值只在于物和我们的需要的关系。某物对一个人来说是多了，对另一人来说则不够，或者相反……不能设想，我们会把自己消费所必需的物拿去卖……我们是要把自己用不着的东西拿去卖，以取得自己需要的东西；我们是要以少换多……人们自然会认为，只要每个被交换的物在价值上等于同一货币量，那就是等量的价值交换等量的价值……但还必须考虑到另一方面；试问：我们双方不是都用剩余物来交换需要物吗？”[21]","language":"中文","translation":false},{"id":"capital-5-35","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"我们看到，孔狄亚克不但把使用价值和交换价值混在一起，而且十分幼稚地把商品生产发达的社会硬说成是这样一种状态：生产者自己生产自己的生存资料，而只把满足自己需要以后的余额即剩余物投入流通[22]。然而，孔狄亚克的论据却经常为现代经济学家所重复，当他们要说明商品交换的发达形式即贸易会产生剩余价值的时候，更是如此。例如，有人说：","language":"中文","translation":false},{"id":"capital-5-36","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"“贸易使产品增添价值，因为同一产品在消费者手里比在生产者手里具有更大的价值，因此，严格说来，贸易应看作是一种生产活动。”[23]","language":"中文","translation":false},{"id":"capital-5-37","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"但是，人们购买商品不是付两次钱：一次是为了它的使用价值，一次是为了它的价值。如果说商品的使用价值对买者比对卖者更有用，那末商品的货币形式对卖者比对买者就更有用。不然他何必出卖商品呢？因此，我们同样也可以说，例如，买者把商人的袜子变成货币，严格说来，就是完成一种“生产活动”。","language":"中文","translation":false},{"id":"capital-5-38","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"假如互相交换的是交换价值相等的商品，或交换价值相等的商品和货币，就是说，是等价物，那末很明显，任何人从流通中取出的价值，都不会大于他投入流通的价值。在这种情形下，就不会有剩余价值形成。商品的流通过程就其纯粹的形式来说，要求等价物的交换。但是在实际上，事情并不是纯粹地进行的。因此，我们假定是非等价物的交换。","language":"中文","translation":false},{"id":"capital-5-39","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在任何情形下，在商品市场上，只是商品所有者与商品所有者相对立，他们彼此行使的权力只是他们商品的权力。商品的物质区别是交换的物质动机，它使商品所有者互相依赖，因为他们双方都没有他们自己需要的物品，而有别人需要的物品。除使用价值上的这种物质区别以外，商品之间就只有一种区别，即商品的自然形式和它的转化形式之间的区别，商品和货币之间的区别。因此，商品所有者之间的区别，只不过是卖者即商品所有者和买者即货币所有者之间的区别。","language":"中文","translation":false},{"id":"capital-5-40","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"假定卖者享有某种无法说明的特权，可以高于商品价值出卖商品，把价值100的商品卖110，即在名义上加价10％。这样，卖者就得到剩余价值10。但是，他当了卖者以后，又成为买者。现在第三个商品所有者作为卖者和他相遇，并且也享有把商品贵卖10％的特权。我们那位商品所有者作为卖者赚得了10，但是作为买者要失去10。[24]实际上，整个事情的结果是，全体商品所有者都高于商品价值10％互相出卖商品，这与他们把商品按其价值出售完全一样。商品的这种名义上的普遍加价，其结果就象例如用银代替金来计量商品价值一样。商品的货币名称即价格上涨了，但商品间的价值比例仍然不变。","language":"中文","translation":false},{"id":"capital-5-41","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"我们再反过来，假定买者享有某种特权，可以低于商品价值购买商品。在这里，不用说，买者还要成为卖者。他在成为买者以前，就曾经是卖者。他在作为买者赚得10％以前，就已经作为卖者失去了10％[25]。结果一切照旧。","language":"中文","translation":false},{"id":"capital-5-42","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"因此，剩余价值的形成，从而货币的转化为资本，既不能用卖者高于商品价值出卖商品来说明，也不能用买者低于商品价值购买商品来说明。[26]","language":"中文","translation":false},{"id":"capital-5-43","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"即使偷偷加进一些不相干的东西，如象托伦斯上校那样，问题也绝不会变简单些。这位上校说：","language":"中文","translation":false},{"id":"capital-5-44","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"“有效的需求在于，消费者通过直接的或间接的交换能够和愿意〈！〉付给商品的部分，大于生产它们时所耗费的资本的一切组成部分。”[27]","language":"中文","translation":false},{"id":"capital-5-45","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在流通中，生产者和消费者只是作为卖者和买者相对立。说生产者得到剩余价值是由于消费者付的钱超过了商品的价值，那不过是把商品所有者作为卖者享有贵卖的特权这个简单的命题加以伪装罢了。卖者自己生产了某种商品，或代表它的生产者，同样，买者也是自己生产了某种已体现为货币的商品，或代表它的生产者。因此，是生产者和生产者相对立。他们的区别在于，一个是买，一个是卖。商品所有者在生产者的名义下高于商品价值出卖商品，在消费者的名义下对商品付出高价，这并不能使我们前进一步。[28]","language":"中文","translation":false},{"id":"capital-5-46","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"因此，坚持剩余价值来源于名义上的加价或卖者享有贵卖商品的特权这一错觉的代表者，是假定有一个只买不卖，从而只消费不生产的阶级。从我们上面达到的观点来看，即从简单流通的观点来看，还不能说明存在着这样一个阶级。但是，我们先假定有这样一个阶级。这个阶级不断用来购买的货币，必然是不断地、不经过交换、白白地、依靠任何一种权利或暴力，从那些商品所有者手里流到这个阶级手里的。把商品高于价值卖给这个阶级，不过是骗回一部分白白交出去的货币罢了[29]。例如，小亚细亚的城市每年向古罗马缴纳贡款，就是如此。罗马则用这些货币购买小亚细亚城市的商品，而且按高价购买。小亚细亚人通过贸易从征服者手里骗回一部分贡款，从而欺骗了罗马人。但是，吃亏的还是小亚细亚人。他们的商品仍旧是用他们自己的货币支付的。这决不是发财致富或创造剩余价值的方法。","language":"中文","translation":false},{"id":"capital-5-47","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"所以，我们还是留在卖者也是买者、买者也是卖者的商品交换范围内吧。我们陷入困境，也许是因为我们只把人理解为人格化的范畴，而不是理解为个人。","language":"中文","translation":false},{"id":"capital-5-48","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"商品所有者A可能非常狡猾，总是使他的同行B或C受骗，而B和C无论如何也报复不了。A把价值40镑的葡萄酒卖给B，换回价值50镑的谷物。A把自己的40镑变成了50镑，把较少的货币变成了较多的货币，把自己的商品变成了资本。我们仔细地来看一下。在交换以前，A手中有价值40镑的葡萄酒，B手中有价值50镑的谷物，总价值是90镑。在交换以后，总价值还是90镑。流通中的价值没有增大一个原子，只是它在A和B之间的分配改变了。一方的剩余价值，是另一方的不足价值，一方的增加，是另一方的减少。如果A不用交换形式作掩饰，而直接从B那里偷去10镑，也会发生同样的变化。显然，流通中的价值总量不管其分配情况怎样变化都不会增大，正象一个犹太人把安女王时代的一法寻当作一基尼来卖，不会使本国的贵金属量增大一样。一个国家的整个资本家阶级不能靠欺骗自己来发财致富。[30]","language":"中文","translation":false},{"id":"capital-5-49","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"可见，无论怎样颠来倒去，结果都是一样。如果是等价物交换，不产生剩余价值；如果是非等价物交换，也不产生剩余价值[31]。流通或商品交换不创造价值。[32]","language":"中文","translation":false},{"id":"capital-5-50","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"由此可以了解，为什么我们在分析资本的基本形式，分析决定现代社会的经济组织的资本形式时，开始根本不提资本的常见的、所谓洪水期前的形态，即商业资本和高利贷资本。","language":"中文","translation":false},{"id":"capital-5-51","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"Ｇ—Ｗ—Ｇ'的形式，为贵卖而买，在真正的商业资本中表现得最纯粹。另一方面，它的整个运动是在流通领域内进行的。但是，既然不能从流通本身来说明货币转化为资本，说明剩余价值的形成，所以只要是等价物相交换，商业资本看来是不可能存在的。[33]因而，商业资本只能这样来解释：寄生在购买的商品生产者和售卖的商品生产者之间的商人对他们双方进行欺骗。富兰克林就是在这个意义上说：“战争是掠夺，商业是欺骗。”[34]如果不是单纯用对商品生产者的欺骗来说明商业资本的增殖，那就必须举出一长串的中间环节，但是在这里，商品流通及其简单要素是我们唯一的前提，因此这些环节还完全不存在。","language":"中文","translation":false},{"id":"capital-5-52","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"关于商业资本所说的一切，更加适用于高利贷资本。在商业资本中，两极，即投入市场的货币和从市场取出的增大的货币，至少还以买和卖，以流通运动为媒介。在高利贷资本中，Ｇ—Ｗ—Ｇ'形式简化成没有媒介的两极Ｇ—Ｇ'，即交换成更多货币的货币。这种形式是和货币的性质相矛盾的，因而从商品交换的角度是无法解释的。所以，亚里士多德说：","language":"中文","translation":false},{"id":"capital-5-53","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"“货殖有两种，一种属于商业方面，一种属于经济方面。后者是必要的，值得称赞的，前者以流通为基础，理应受到谴责（因为它不以自然为基础，而以互相欺骗为基础）。所以，高利贷受人憎恨完全理所当然，因为在这里，货币本身成为赢利的源泉，没有用于发明它的时候的用途。货币是为商品交换而产生的，但利息却使货币生出更多的货币。它的名称〈利息和利子〉就是由此而来的。利子和母财是相像的。但利息是货币生出的货币，因此在所有的赢利部门中，这个部门是最违反自然的。”[35]","language":"中文","translation":false},{"id":"capital-5-54","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"在我们研究的进程中，我们将会发现，生息资本和商业资本一样，也是派生的形式，同时会看到，为什么它们在历史上的出现早于资本的现代基本形式。","language":"中文","translation":false},{"id":"capital-5-55","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"上面已经说明，剩余价值不能从流通中产生；因此，在剩余价值的形成上，必然有某种在流通中看不到的情况发生在流通的背后。[36]但是，剩余价值能不能从流通以外的什么地方产生呢？流通是商品所有者的全部相互关系的总和。在流通以外，商品所有者只同他自己的商品发生关系。就商品的价值来说，这种关系只是：他的商品包含着他自己的、按一定社会规律计量的劳动量。这个劳动量表现为他的商品的价值量，而价值量是表现在计算货币上的，因此劳动量就表现为一个价格，例如10镑。但是，他的劳动不能表现为商品的价值和超过这个商品本身价值而形成的余额，不能表现为等于10镑又等于11镑的价格，不能表现为一个大于自身价值的价值。商品所有者能够用自己的劳动创造价值，但是不能创造进行增殖的价值。他能够通过新的劳动给原有价值添加新价值，从而使商品的价值增大，例如把皮子制成皮靴就是这样。这时，同一个材料由于包含了更大的劳动量，也就有了更大的价值。因此，皮靴的价值大于皮子的价值，但是皮子的价值仍然和从前一样。它没有增殖，没有在制作皮靴时添加剩余价值。可见，商品生产者在流通领域以外，也就是不同其他商品所有者接触，就不能使价值增殖，从而使货币或商品转化为资本。","language":"中文","translation":false},{"id":"capital-5-56","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"① “相互关系”在第3版和第4版中是“商品关系”。——编者注","language":"中文","translation":false},{"id":"capital-5-57","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"因此，资本不能从流通中产生，又不能不从流通中产生。它必须既在流通中又不在流通中产生。","language":"中文","translation":false},{"id":"capital-5-58","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"这样，就得到一个双重的结果。","language":"中文","translation":false},{"id":"capital-5-59","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"货币转化为资本，必须根据商品交换的内在规律来加以说明，因此等价物的交换应该是起点。[37]我们那位还只是资本家幼虫的货币所有者，必须按商品的价值购买商品，按商品的价值出卖商品，但他在过程终了时必须取出比他投入的价值更大的价值。他变为蝴蝶，必须在流通领域中，又必须不在流通领域中。这就是问题的条件。这里是罗陀斯，就在这里跳罢！【88】","language":"中文","translation":false},{"id":"capital-5-60","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"要转化为资本的货币的价值变化，不可能发生在这个货币本身上，因为货币作为购买手段和支付手段，只是实现它所购买或所支付的商品的价格，而它如果停滞在自己原来的形式上，它就凝固为价值量不变的化石了[38]。同样，在流通的第二个行为即商品的再度出卖上，也不可能发生这种变化，因为这一行为只是使商品从自然形式再转化为货币形式。因此，这种变化必定发生在第一个行为Ｇ—Ｗ中所购买的商品上，但不是发生在这种商品的价值上，因为互相交换的是等价物，商品是按它的价值支付的。因此，这种变化只能从这种商品的使用价值本身，即从这种商品的使用上产生。要从商品的使用上取得价值，我们的货币所有者就必须幸运地在流通领域内即在市场上发现这样一种商品，它的使用价值本身具有成为价值源泉的特殊属性，因此，它的实际使用本身就是劳动的物化，从而是价值的创造。货币所有者在市场上找到了这种特殊商品，这就是劳动能力或劳动力。","language":"中文","translation":false},{"id":"capital-5-61","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"我们把劳动力或劳动能力，理解为人的身体即活的人体中存在的、每当人生产某种使用价值时就运用的体力和智力的总和。","language":"中文","translation":false},{"id":"capital-5-62","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"但是，货币所有者要在市场上找到作为商品的劳动力，必须存在各种条件。商品交换本身除了包含由它自己的性质所产生的从属关系以外，不包含任何其他从属关系。在这种前提下，劳动力只有而且只是因为被它自己的所有者即有劳动力的人当作商品出售或出卖，才能作为商品出现在市场上。劳动力所有者要把劳动力当作商品出卖，他就必须能够支配它，从而必须是自己的劳动能力、自己人身的自由的所有者[39]。劳动力所有者和货币所有者在市场上相遇，彼此作为身分平等的商品所有者发生关系，所不同的只是一个是买者，一个是卖者，因此双方是在法律上平等的人。这种关系要保持下去，劳动力所有者就必须始终把劳动力只出卖一定时间，因为他要是把劳动力一下子全部卖光，他就出卖了自己，就从自由人变成奴隶，从商品所有者变成商品。他作为人，必须总是把自己的劳动力当作自己的财产，从而当作自己的商品。而要做到这一点，他必须始终让买者只是在一定期限内暂时支配他的劳动力，使用他的劳动力，就是说，他在让渡自己的劳动力时不放弃自己对它的所有权。[40]","language":"中文","translation":false},{"id":"capital-5-63","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"货币所有者要在市场上找到作为商品的劳动力，第二个基本条件就是：劳动力所有者没有可能出卖有自己的劳动物化在内的商品，而不得不把只存在于他的活的身体中的劳动力本身当作商品出卖。","language":"中文","translation":false},{"id":"capital-5-64","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"一个人要出卖与他的劳动力不同的商品，他自然必须占有生产资料，如原料、劳动工具等等。没有皮革，他就不能做皮靴。此外，他还需要有生活资料。任何人，即使是未来音乐的创作家，都不能靠未来的产品过活，也不能靠尚未生产好的使用价值过活。人从出现在地球舞台上的第一天起，每天都要消费，不管在他开始生产以前和在生产期间都是一样。如果产品是作为商品生产的，在它生产出来以后就必须卖掉，而且只有在卖掉以后，它才能满足生产者的需要。除生产时间外，还要加上出售所需要的时间。","language":"中文","translation":false},{"id":"capital-5-65","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"可见，货币所有者要把货币转化为资本，就必须在商品市场上找到自由的工人。这里所说的自由，具有双重意义：一方面，工人是自由人，能够把自己的劳动力当作自己的商品来支配，另一方面，他没有别的商品可以出卖，自由得一无所有，没有任何实现自己的劳动力所必需的东西。","language":"中文","translation":false},{"id":"capital-5-66","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"为什么这个自由工人在流通领域中同货币所有者相遇，对这个问题货币所有者不感兴趣。他把劳动市场看作是商品市场的一个特殊部门。我们目前对这个问题也不感兴趣。货币所有者是在实践上把握着这个事实，我们则是在理论上把握着这个事实。但是有一点是清楚的。自然界不是一方面造成货币所有者或商品所有者，而另一方面造成只是自己劳动力的所有者。这种关系既不是自然史上的关系，也不是一切历史时期所共有的社会关系。它本身显然是已往历史发展的结果，是许多次经济变革的产物，是一系列陈旧的社会生产形态灭亡的产物。","language":"中文","translation":false},{"id":"capital-5-67","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"我们前面所考察的经济范畴，也都带有自己的历史痕迹。产品成为商品，需要有一定的历史条件。要成为商品，产品就不应作为生产者自己直接的生存资料来生产。如果我们进一步研究，在什么样的状态下，全部产品或至少大部分产品采取商品的形式，我们就会发现，这种情况只有在一种十分特殊的生产方式即资本主义生产方式的基础上才会发生。但是这种研究不属于商品分析的范围。即使绝大多数产品直接用来满足生产者自己的需要，没有变成商品，从而社会生产过程按其广度和深度来说还远没有为交换价值所控制，商品生产和商品流通仍然能够产生。产品要表现为商品，需要社会内部的分工发展到这样的程度：在直接的物物交换中开始的使用价值和交换价值的分离已经完成。但是，这样的发展阶段是历史上完全不同的社会经济形态所共有的。","language":"中文","translation":false},{"id":"capital-5-68","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"如果考察一下货币，我们就会看到，货币是以商品交换发展到一定高度为前提的。货币的各种特殊形式，即单纯的商品等价物，或流通手段，或支付手段、贮藏货币和世界货币，按其中这种或那种职能的不同作用范围和相对占优势的情况，表示社会生产过程的极不相同的阶段。但是根据经验，不很发达的商品流通就足以促使所有这些形式的形成。资本则不然。有了商品流通和货币流通，决不是就具备了资本存在的历史条件。只有当生产资料和生活资料的所有者在市场上找到出卖自己劳动力的自由工人的时候，资本才产生；而单是这一历史条件就包含着一部世界史。因此，资本一出现，就标志着社会生产过程的一个新时代。[41]","language":"中文","translation":false},{"id":"capital-5-69","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"现在应该进一步考察这个特殊商品——劳动力。同一切其他商品一样，劳动力也具有价值[42]。这个价值是怎样决定的呢？","language":"中文","translation":false},{"id":"capital-5-70","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"同任何其他商品的价值一样，劳动力的价值也是由生产从而再生产这种特殊物品所必需的劳动时间决定的。就劳动力代表价值来说，它本身只代表在它身上物化的一定量的社会平均劳动。劳动力只是作为活的个体的能力而存在。因此，劳动力的生产要以活的个体的存在为前提。假设个体已经存在，劳动力的生产就是这个个体本身的再生产或维持。活的个体要维持自己，需要有一定量的生活资料。因此，生产劳动力所需要的劳动时间，可化为生产这些生活资料所需要的劳动时间，或者说，劳动力的价值，就是维持劳动力所有者所需要的生活资料的价值。但是，劳动力只有表现出来才能实现，只有在劳动中才能发挥出来。而劳动力的发挥即劳动，耗费人的一定量的肌肉、神经、脑等等，这些消耗必须重新得到补偿。支出增多，收入也得增多。[43]劳动力所有者今天进行了劳动，他应当明天也能够在同样的精力和健康条件下重复同样的过程。因此，生活资料的总和应当足以使劳动者个体能够在正常生活状况下维持自己。由于一个国家的气候和其他自然特点不同，食物、衣服、取暖、居住等等自然需要也就不同。另一方面，所谓必不可少的需要的范围，和满足这些需要的方式一样，本身是历史的产物，因此多半取决于一个国家的文化水平，其中主要取决于自由工人阶级是在什么条件下形成的，从而它有哪些习惯和生活要求[44]。因此，和其他商品不同，劳动力的价值规定包含着一个历史的和道德的因素。但是，在一定的国家，在一定的时期，必要生活资料的平均范围是一定的。","language":"中文","translation":false},{"id":"capital-5-71","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"劳动力所有者是会死的。因此，要使他不断出现在市场上（这是货币不断转化为资本的前提），劳动力的卖者就必须“象任何活的个体一样，依靠繁殖使自己永远延续下去”[45]。因损耗和死亡而退出市场的劳动力，至少要不断由同样数目的新劳动力来补充。因此，生产劳动力所必需的生活资料的总和，要包括工人的补充者即工人子女的生活资料，只有这样，这种特殊商品所有者的种族才能在商品市场上永远延续下去。[46]","language":"中文","translation":false},{"id":"capital-5-72","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"要改变一般的人的本性，使它获得一定劳动部门的技能和技巧，成为发达的和专门的劳动力，就要有一定的教育或训练，而这就得花费或多或少的商品等价物。劳动力的教育费随着劳动力性质的复杂程度而不同。因此，这种教育费——对于普通劳动力来说是微乎其微的——包括在生产劳动力所耗费的价值总和中。","language":"中文","translation":false},{"id":"capital-5-73","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"劳动力的价值可以归结为一定量生活资料的价值。因此，它也随着这些生活资料的价值即生产这些生活资料所需要的劳动时间量的改变而改变。","language":"中文","translation":false},{"id":"capital-5-74","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"一部分生活资料，如食品、燃料等等，每天都有新的消耗，因而每天都必须有新的补充。另一些生活资料，如衣服、家具等等，可以使用较长的时期，因而只是经过较长的时期才需要补充。有些商品要每天购买或支付，有些商品要每星期购买或支付，还有些商品要每季度购买或支付，如此等等。但不管这些支出的总和在例如一年当中怎样分配，都必须由每天的平均收入来担负。假如生产劳动力每天所需要的商品量=A，每星期所需要的商品量=B，每季度所需要的商品量=C，其他等等，那末这些商品每天的平均需要量=（365A+52B+4C+其他等等)/365。假定平均每天所需要的这个商品量包含6小时社会劳动，那末每天物化在劳动力中的就是半天的社会平均劳动，或者说，每天生产劳动力所需要的是半个工作日。生产劳动力每天所需要的这个劳动量，构成劳动力的日价值，或每天再生产出的劳动力的价值。假定半天的社会平均劳动又表现为3先令或1塔勒的金量，那末1塔勒就是相当于劳动力日价值的价格。如果劳动力所有者按每天1塔勒出卖劳动力，劳动力的出售价格就等于劳动力的价值，而且根据我们的假定，一心要把自己的塔勒转化为资本的货币所有者是支付这个价值的。","language":"中文","translation":false},{"id":"capital-5-75","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"劳动力价值的最低限度或最小限度，是劳动力的承担者即人每天得不到就不能更新他的生命过程的那个商品量的价值，也就是维持身体所必不可少的生活资料的价值。假如劳动力的价格降到这个最低限度，那就降到劳动力的价值以下，因为这样一来，劳动力就只能在萎缩的状态下维持和发挥。但是，每种商品的价值都是由提供标准质量的该种商品所需要的劳动时间决定的。","language":"中文","translation":false},{"id":"capital-5-76","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"认为这种由事物本性产生的劳动力的价值规定是粗暴的，并且象罗西那样为之叹息，那是一种极其廉价的感伤主义：","language":"中文","translation":false},{"id":"capital-5-77","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"“在考察劳动能力时，撇开生产过程中维持劳动的生存资料，那就是考察一种臆想的东西。谁谈劳动，谈劳动能力，同时也就是谈工人和生存资料，工人和工资”。[47]","language":"中文","translation":false},{"id":"capital-5-78","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"谁谈劳动能力并不就是谈劳动，正象谈消化能力并不就是谈消化一样。谁都知道，要有消化过程，光有健全的胃是不够的。谁谈劳动能力，谁就不会撇开维持劳动能力所必需的生活资料。生活资料的价值正是表现在劳动能力的价值上。劳动能力不卖出去，对工人就毫无用处，不仅如此，工人就会感到一种残酷的自然必然性：他的劳动能力的生产曾需要一定量的生存资料，它的再生产又不断地需要一定量的生存资料。于是，他就和西斯蒙第一样地发现：“劳动能力……不卖出去，就等于零。”[48]","language":"中文","translation":false},{"id":"capital-5-79","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"劳动力这种特殊商品的特性，使劳动力的使用价值在买者和卖者缔结契约时还没有在实际上转到买者手中。和其他任何商品的价值一样，它的价值在它进入流通以前就已确定，因为在劳动力的生产上已经耗费了一定量的社会劳动，但它的使用价值只是在以后的力的表现中才实现。因此，力的让渡和力的实际表现即力作为使用价值的存在，在时间上是互相分开的。但是，对于这类先通过出售而在形式上让渡使用价值、后在实际上向买者转让使用价值的商品来说，买者的货币通常执行支付手段的职能[49]。在资本主义生产方式占统治地位的一切国家里，给劳动力支付报酬，是在它按购买契约所规定的时间发挥作用以后，例如在每周的周末。因此，到处都是工人把劳动力的使用价值预付给资本家；工人在得到买者支付他的劳动力价格以前，就让买者消费他的劳动力，因此，到处都是工人给资本家以信贷。这种信贷不是什么臆想，这不仅为贷方碰到资本家破产时失掉工资[50]所证明，而且也为一系列远为经常的影响所证明。[51]但是，无论货币执行购买手段还是支付手段的职能，商品交换本身的性质并不因此发生变化。劳动力的价格已由契约确定下来，虽然它同房屋的出租价格一样，要在以后才实现。劳动力已经卖出，虽然报酬要在以后才得到。但是，为了在纯粹的形式上理解这种关系，我们暂且假定，劳动力所有者每次出卖劳动力时就立即得到了契约所规定的价格。","language":"中文","translation":false},{"id":"capital-5-80","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"现在我们知道了，货币所有者付给劳动力这种特殊商品的所有者的价值是怎样决定的。货币所有者在交换中得到的使用价值，在劳动力的实际使用即消费过程中才表现出来。这个过程所必需的一切物品，如原料等等，是由货币所有者在商品市场上买来并且按十足的价格支付的。劳动力的消费过程，同时就是商品和剩余价值的生产过程。劳动力的消费，象任何其他商品的消费一样，是在市场以外，或者说在流通领域以外进行的。因此，让我们同货币所有者和劳动力所有者一道，离开这个嘈杂的、表面的、有目共睹的领域，跟随他们两人进入门上挂着“非公莫入”牌子的隐蔽的生产场所吧！在那里，不仅可以看到资本是怎样进行生产的，还可以看到资本本身是怎样被生产出来的。赚钱的秘密最后一定会暴露出来。","language":"中文","translation":false},{"id":"capital-5-81","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"劳动力的买和卖是在流通领域或商品交换领域的界限以内进行的，这个领域确实是天赋人权的真正乐园。那里占统治地位的只是自由、平等、所有权和边沁。自由！因为商品例如劳动力的买者和卖者，只取决于自己的自由意志。他们是作为自由的、在法律上平等的人缔结契约的。契约是他们的意志借以得到共同的法律表现的最后结果。平等！因为他们彼此只是作为商品所有者发生关系，用等价物交换等价物。所有权！因为他们都只支配自己的东西。边沁！因为双方都只顾自己。使他们连在一起并发生关系的唯一力量，是他们的利己心，是他们的特殊利益，是他们的私人利益。正因为人人只顾自己，谁也不管别人，所以大家都是在事物的预定的和谐下，或者说，在全能的神的保佑下，完成着互惠互利、共同有益、全体有利的事业。","language":"中文","translation":false},{"id":"capital-5-82","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"一离开这个简单流通领域或商品交换领域，——庸俗的自由贸易论者用来判断资本和雇佣劳动的社会的那些观点、概念和标准就是从这个领域得出的，——就会看到，我们的剧中人的面貌已经起了某些变化。原来的货币所有者成了资本家，昂首前行；劳动力所有者成了他的工人，尾随于后。一个笑容满面，雄心勃勃；一个战战兢兢，畏缩不前，象在市场上出卖了自己的皮一样，只有一个前途——让人家来鞣。","language":"中文","translation":false},{"id":"capital-5-83","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[1] 以人身的奴役关系和统治关系为基础的地产权力和非人身的货币权力之间的对立，可以用两句法国谚语明白表示出来：“没有一块土地没有地主”，“货币没有主人”。","language":"中文","translation":false},{"id":"capital-5-84","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[2] “人们用货币购买商品，用商品购买货币。”（里维埃尔的迈尔西埃《政治社会天然固有的秩序》第543页）","language":"中文","translation":false},{"id":"capital-5-85","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[3] “如果购买一物是为了再卖出去，这样用掉的钱叫做预付货币；如果购买一物不是为了再卖出去，这样用掉的钱可以说是花掉了。”（《詹·斯图亚特著作集》，由其子詹姆斯·斯图亚特爵士将军汇编，1805年伦敦版第1卷第274页）","language":"中文","translation":false},{"id":"capital-5-86","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[4] 里维埃尔的迈尔西埃驳重商主义者说，“人们不会用货币去交换货币。”（《政治社会天然固有的秩序》第486页）有一本专门论述“贸易”和“投机”的著作写道：“一切贸易都是不同种物品的交换；而利益〈商人的？〉正是由于这种不同而产生的。用一磅面包交换一磅面包，这不会带来任何利益……因此，贸易同赌博相比形成有利的对照，因为赌博只是用货币交换货币。”（托·柯贝特《个人致富的原因和方法的研究；或贸易和投机原理的解释》1841年伦敦版第5页）虽然柯贝特不知道，G—G，货币交换货币， 不仅是商业资本，而且是一切资本的特有的流通形式，但他至少承认，这个形式是投机这种贸易与赌博共有的；但是后来出现了麦克库洛赫，他发现，为卖而买就是投机，这样，投机和贸易的区别就消失了。“任何交易，只要一个人购买产品是为了再卖出去，实际上就是投机。”（麦克库洛赫《商业及其航运的实践、理论和历史辞典》1847年伦敦版第1009页）品托，这个阿姆斯特丹交易所的品得，更是无比天真，他说：“贸易是一种赌博〈这句话是从洛克那里抄袭来的〉，不过从乞丐那儿是赢不到任何东西的。如果有人在长时间内赢了所有的人的所有的钱，那他只有心甘情愿地把赢得的绝大部分钱退回去，才能再赌”（品托《关于流通和信用的论文》1771年阿姆斯特丹版第231页）。","language":"中文","translation":false},{"id":"capital-5-87","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[5] “资本……分为原有资本和利润，即资本……所获得的增殖，虽然实践立刻又将这种利润加到资本上，并把它和资本一起投入周转中。”（弗·恩格斯《政治经济学批判大纲》，载于阿尔诺德·卢格和卡尔·马克思编的《德法年鉴》1844年巴黎版第99页【85】）","language":"中文","translation":false},{"id":"capital-5-88","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"【85】 见《马克思恩格斯全集》中文版第1卷第610页。——第173页。","language":"中文","translation":false},{"id":"capital-5-89","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[6] 亚里士多德拿经济同货殖作对比。他从经济出发。经济作为一种谋生术，只限于取得生活所必要的并且对家庭或国家有用的物品。“真正的财富就是由这样的使用价值构成的；因为满足优裕生活所必需的这类财产的量不是无限的。但是还有另一种谋生术，把它叫做货殖是很适当、很贴切的。由于货殖，财富和财产的界限看来就不存在了。商品交易按其性质来说不属于货殖范围，因为在这里，交换只限于他们自己<买者和卖者>需要的物品。”他又说，因此，商品交易的最初形式也是物物交换，但是随着它的扩大，必然产生货币。随着货币的发明，物物交换必然发展成为商品交易，而后者一反它的最初的宗旨，成了货殖，成了赚钱术。货殖与经济的区别是：“对货殖来说，流通是财富的源泉。货殖似乎是围绕着货币转，因为货币是这种交换的起点和终点。因此，货殖所追求的财富也是无限的。一种技术，只要它的目的不是充当手段，而是充当最终目的，它的要求就是无限的，因为它总想更加接近这个目的；而那种只是追求达到目的的手段的技术，就不是无限的，因为目的本身已给这种技术规定了界限。货殖则和前一种技术一样，它的目的也是没有止境的，它的目的就是绝对的致富。有界限的是经济而不是货殖……前者的目的是与货币本身不同的东西，后者的目的是增加货币……由于把这两种难以分清的形式混为一谈，有人就以为，无限地保存和增加货币是经济的最终目的。”（散见亚里士多德《政治学》，贝克尔编，第1篇第8、9章)","language":"中文","translation":false},{"id":"capital-5-90","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[7] “商品〈这里是指使用价值〉不是经商的资本家的最终目的……他的最终目的是货币。”（托·査默斯《论政治经济学和社会的道德状况、道德远景的关系》1832年格拉斯哥第2版第165、166页）","language":"中文","translation":false},{"id":"capital-5-91","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[8] “虽然商人并不轻视巳经获得的利润，但他的目光却总是盯着未来的利润。”(安·詹诺韦西《市民经济学讲义》（1765年版），载于库斯托第编《意大利政治经济学名家文集》现代部分，第8卷第139页）","language":"中文","translation":false},{"id":"capital-5-92","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[9] “这种不可遏止的追逐利润的狂热，这种可诅咒的求金欲，始终左右着资本家。”（麦克库洛赫《政治经济学原理》1830年伦敦版第179页）当然，这种见解并不妨碍麦克库洛赫之流，在理论上陷入困境的情况下，例如在考察生产过剩问题时，还是把资本家变成了善良的市民，好象他关心的只是使用价值，好象他真正象狼一般贪求的，只是皮靴、帽子、鸡蛋、印花布以及其他各种极为平常的使用价值。","language":"中文","translation":false},{"id":"capital-5-93","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[10] ［拯救］是希腊人用来表示贮藏财宝的一种特别用语。同样， 英语《to save》也是既有拯救，又有储蓄的意思。","language":"中文","translation":false},{"id":"capital-5-94","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[10a] “事物在直进中没有无限性，在循环中却有。”（加利阿尼[《货币论》第156页]）","language":"中文","translation":false},{"id":"capital-5-95","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[11] “构成资本的不是物质，而是这些物质的价值。”(让·巴·萨伊《论政治经济学》1817年巴黎第3版第2卷第429页）","language":"中文","translation":false},{"id":"capital-5-96","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[12] “用于生产目的的流通手段〈！〉就是资本。”（麦克劳德《银行业的理论与实践》1855年伦敦版第1卷第1章第55页）“资本就是商品。”（詹姆斯·穆勒《政治经济学原理》1821年伦敦版第74页）","language":"中文","translation":false},{"id":"capital-5-97","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[13] “资本……是不断增大的价值。”（西斯蒙第《政治经济学新原理》第1卷第89页）","language":"中文","translation":false},{"id":"capital-5-98","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[14] “交换是一种奇妙的交易，交换双方总是〈！〉得到好处。”(德斯杜特·德·特拉西《论意志及其作用》1826年巴黎版第68页）该书也以《政治经济学概论》的名称出版。","language":"中文","translation":false},{"id":"capital-5-99","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[15] 里维埃尔的迈尔西埃《政治社会天然固有的秩序》第544页。","language":"中文","translation":false},{"id":"capital-5-100","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[16] “这两个价值中有一个是货币，还是两个都是普通商品，这件事本身是毫无关系的。”（同上，第543页）","language":"中文","translation":false},{"id":"capital-5-101","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[17] “不是契约当事人决定价值；价值在成交以前就已经决定了。”（列特隆《论社会利益》第906页）","language":"中文","translation":false},{"id":"capital-5-102","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[18] 加利阿尼《货币论》，载于库斯托第编《意大利政治经济学名家文集》现代部分，第4卷第244页。","language":"中文","translation":false},{"id":"capital-5-103","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[19] “当某种外部情况使价格降低或提高时，交换就会对一方不利，于是平等被破坏了，但这种破坏是由于外部原因，而不是由于交换造成的。”（列特隆《论社会利益》 第904页）","language":"中文","translation":false},{"id":"capital-5-104","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[20] “交换按其性质来说是一种契约，这种契约以平等为基础，也就是说，是在两个相等的价值之间订立的。因此，它不是致富的手段，因为所付和所得是相等的。”〈列特隆《论社会利益》第903、904页）","language":"中文","translation":false},{"id":"capital-5-105","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[21] 孔狄亚克《商业和政府》（1776年），载于德尔和莫利纳里编《政治经济学文选》1847年巴黎版第267、291页。","language":"中文","translation":false},{"id":"capital-5-106","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[22] 因此，列特隆在回答他的朋友孔狄亚克时说得很对：“在发达的社会中，根本没有剩余的东西。”同时他还讽刺地解释说：“假如交换双方都以同样少的东西换得同样多的东西，那末他们得到的也就同样多。”由于孔狄亚克对交换价值的性质一无所知，所以，他是威廉·罗雪尔教授先生证实自己的幼稚概念的最好证明人。见罗雪尔的《国民经济学原理》1858年第3版。","language":"中文","translation":false},{"id":"capital-5-107","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[23] 塞·菲·纽曼《政治经济学原理》1835年安多怫和纽约版第175页。","language":"中文","translation":false},{"id":"capital-5-108","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[24] “靠提高产品的名义价值……卖者不会致富……因为他们作为卖者所得的利益，在他们作为买者时又如数付出。”（[约·格雷]《国民财富基本原理的说明》1797年伦敦版第66页）","language":"中文","translation":false},{"id":"capital-5-109","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[25] “假如有人不得不把价值24利弗尔的产品卖18利弗尔，那末，当他用这笔货币额再去购买时，这18利弗尔同样能买到24利弗尔的东西。”（列特隆《论社会利益》 第897页）","language":"中文","translation":false},{"id":"capital-5-110","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[26] “因此，任何一个卖者通常不能提高自己商品的价格，否则他购买其他卖者的商品时也必须付出高价。根据同样的理由，任何一个消费者通常不能以低价购买商品，否则他也必须降低他出售的商品的价格。（里维埃尔的迈尔西埃《政治社会天然固有的秩序》第555页）","language":"中文","translation":false},{"id":"capital-5-111","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[27] 罗·托伦斯《论财富的生产》1821年伦敦版第349页。","language":"中文","translation":false},{"id":"capital-5-112","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[28] “利润由消费者支付这种想法显然是十分荒谬的。消费者又是谁呢？”（乔·拉姆赛《论财富的分配》1836年爱丁堡版第183页）","language":"中文","translation":false},{"id":"capital-5-113","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[29] “假如有人感到商品滞销，那末马尔萨斯先生是否会劝他把钱付给别人，让别人用这笔钱购买他的商品呢?”一个很气愤的李嘉图的信徒这样质问马尔萨斯，因为后者及其门徒査默斯牧师从经济学的观点赞美了纯买者阶级，即消费者阶级。见《论马尔萨斯先生近来提倡的关于需求的性质和消费的必要性的原理》1821年伦敦版第55页。","language":"中文","translation":false},{"id":"capital-5-114","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[30] 德斯杜特·德·特拉西虽然是（或许正因为是）研究院院士【86】，却持有相反的观点。他说，产业资本家赚得利润，是因为“他们按高于生产成本的价格出卖商品。他们卖给谁呢？首先就是彼此互卖”（德斯杜特·德·特拉西《论意志及其作用》第239页）","language":"中文","translation":false},{"id":"capital-5-115","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"【86】 指法国研究院，它是法国的最高科学机构，由若干部分即若干学院组成。德斯杜特·德·特拉西是伦理学和政治学学院院士。——第186页。","language":"中文","translation":false},{"id":"capital-5-116","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[31] “两个相等的价值相交换，既不增大也不减少社会上现有价值的量。两个不相等的价值相交换……同样也改变不了社会上的价值总额，因为它给这一个人增添的财富，是它从另一个人手中取走的财富。”（让·巴·萨伊《论政治经济学》1817年巴黎第3版第2卷第443，444页）这个论点是萨伊几乎逐字逐句地从重农学派那里抄袭来的，当然他并不关心从这个论点会得出什么结论。下面的例子可以说明，他是怎样利用当时已被人遗忘的重农学派的著作，来增加自己的“价值”的。萨伊先生“最著名的”论点：“产品只能用产品来购买”（同上，第2卷第438页），用重农学派的原话来说就是：“产品只有用产品来支付”（列特隆《论社会利益》第899页）。","language":"中文","translation":false},{"id":"capital-5-117","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[32] “交换不会给产品以任何价值。”（弗·威兰德《政治经济学原理》1843年波士顿版第168页）","language":"中文","translation":false},{"id":"capital-5-118","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[33] “在不变的等价物支配下，贸易是不可能的。”（乔·奥普戴克《论政治经济学》1851年纽约版第66页到69页）“实际价值和交换价值间的差别就在于物品的价值不等于人们在买卖中给予它的那个所谓等价物，就是说，这个等价物并不是等价物。”（弗·恩格斯《政治经济学批判大纲》，载于阿尔诺德·卢格和卡尔·马克思编的《德法年鉴》1844年巴黎版第95、96页【87】）","language":"中文","translation":false},{"id":"capital-5-119","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"【87】见《马克思恩格斯全集》中文版第1卷第606页。——第186页。","language":"中文","translation":false},{"id":"capital-5-120","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[34] 《本杰明·富兰克林全集》，斯巴克斯编第2卷《关于国民财富的有待研究的几个问题》[第376页]。","language":"中文","translation":false},{"id":"capital-5-121","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[35] 亚里士多德《政治学》箄1篇第10章[第17页]。","language":"中文","translation":false},{"id":"capital-5-122","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[36] “在通常的市场条件下，利润不是由交换产生的。如果利润不是先前就已存在，那末，在这种交易以后也不会有。”（拉姆赛《论财富的分配》第184页）","language":"中文","translation":false},{"id":"capital-5-123","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[37] 根据以上说明，读者可以知道，这里的意思不过是：即使商品价格与商品价值相等，资本也一定可以形成。资本的形成不能用商品价格与商品价值的偏离来说明。假如价格确实与价值相偏离，那就必须首先把前者还原为后者，就是说，把这种情况当作偶然情况撇开，这样才能得到以商品交换为基础的资本形成的纯粹现象，才能在考察这个现象时，不致被那些起干扰作用的、与真正的过程不相干的从属情况所迷惑。而且我们知道，这种还原决不单纯是一种科学的手续。市场价格的不断波动，即它的涨落，会互相补偿，彼此抵销，并且还原为平均价格，而平均价格是市场价格的内在规则。这个规则是从事一切需要较长时间经营的企业的商人或工业家的指南。所以他们知道，就整个一段较长的时期来看，商品实际上既不是低于也不是高于平均价格，而是按照平均价格出售的。因此，如果撇开利害得失来考虑问题是符合他们的利益的话，他们就应该这样提出资本形成的问题：既然价格是由平均价格即归根到底是由商品的价值来调节的，那末资本怎么会产生呢？我说“归根到底”，是因为平均价格并不象亚·斯密、李嘉图等人所认为的那样，直接与商品的价值量相一致。","language":"中文","translation":false},{"id":"capital-5-124","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"【88】这里是罗陀斯，就在这里跳罢！（Hic Rhodus, hic salta!）这是对一个说大话的人讲的话，他硬说自己曾在罗陀斯岛跳得很远很远（引自伊索寓言《说大话的人》）。转义是：就在这里证明你有什么本领罢！——第189页。","language":"中文","translation":false},{"id":"capital-5-125","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[38] “在货币形式上……资本是不产生利润的。”（李嘉图《政治经济学原理》第267页）","language":"中文","translation":false},{"id":"capital-5-126","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[39] 在有关古希腊罗马的一些实用百科辞典中,可以看到一种谬论：在古代世界，资本就有了充分的发廏，“所缺少的只是自由工人和信用事业”。蒙森先生在他的《罗马史》中也一再陷入混乱。","language":"中文","translation":false},{"id":"capital-5-127","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[40] 因此，各种立法都规定了劳动契约的最长期限。在自由劳动的民族里，一切法典都规定了解除契约的条件。在有些国家，特别是墨西哥（美国南北战争前，从墨西哥夺去的领土也是这样，库扎政变【89】前多瑙河地区实际上也是这样），奴隶制采取债役这种隐蔽的形式。由于债务要以劳役偿还，而且要世代相传,所以不仅劳动者个人，而且连他的家族实际上都成为别人及其家族的财产。胡阿雷斯废除了债役。所谓的皇帝马克西米利安颁布一道敕令，又把它恢复了。华盛顿的众议院一针见血地谴责这个敕令是恢复墨西哥的奴隶制的敕令，“我可以把我的体力上和智力上的特殊技龍和活动能力……在限定的时期内让渡给别人使用，因为根据这种限制，它们同我的整体和全体取得一种外在的关系。如果我把我的由于劳动而具体化的全部时间和我的全部生产活动都让渡给别人，那末，我就把这种括动的实体、我的普遍的活动和现实性、我的人身，变成别人的财产了。”（黑格尔《法哲学》1840年柏林版苐104页第67节）","language":"中文","translation":false},{"id":"capital-5-128","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"【89】库扎政变——是罗马尼亚历史上的重要事件。1859年1月，著名的社会政治活动家亚历山大鲁·库扎先后被选为莫尔达维亚和瓦拉几亚公国的国君。由于这两个长期隶属于奥斯曼帝国的多瑙河公国的合并，为罗马尼亚国家的统一奠定了基础。库扎执政后，立意实行一系列的资产阶级民主改革。但是他的政策遇到了地主和一部分资产阶级的强烈反抗。在地主代表占优势的国民议会否决了政府提出的土地改革草案后，库扎于1864年实行政变，解散了反动的国民议会，颁布了新宪法，扩大了选民范围，加强了政府权力。在这种新的政治局势下实行的土地改革，规定废除农奴制和通过赎买把土地分给农民。——第191、265页。","language":"中文","translation":false},{"id":"capital-5-129","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[41] 因此，资本主义时代的特点是，对工人本身来说，劳动力是归他所有的一种商品的形式，他的劳动因而具有雇佣劳动的形式。另一方面，正是从这时起，劳动产品的商品形式才普遍化。","language":"中文","translation":false},{"id":"capital-5-130","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[42] “人的价值，和其他一切物的价值一样，等于他的价格，就是说，等于对他的能力的使用所付的报酬。”（托·霍布斯《利维坦》，载于摩耳斯沃思编《托马斯·霍布斯英文著作选》1839—1844年伦敦版第3卷第76页）","language":"中文","translation":false},{"id":"capital-5-131","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[43] 古罗马的斐力卡斯，作为管理人居于农业奴隶之首，但“由于劳动比奴隶轻，得到的报酬也比奴隶更微薄”（泰·蒙森《罗马史》1856年版第810页）。","language":"中文","translation":false},{"id":"capital-5-132","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[44] 参看威·托·桑顿《人口过剩及其补救办法》1846年伦教版。","language":"中文","translation":false},{"id":"capital-5-133","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[46] “它的〈劳动的〉自然价格……由一定量的生存资料和舒适品构成。这个量是拫据一个国家的气候和习惯，为维持工人并使他有可能抚养家庭，以保证市场上劳动供应不致减少所必需的。”（罗·托伦斯《论谷物外销》1815年伦敦版第62页）劳动一词在这里错误地当作劳动力一词来使用。","language":"中文","translation":false},{"id":"capital-5-134","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[47] 罗西《政治经济学教程》1843年布鲁塞尔版第370、371页。","language":"中文","translation":false},{"id":"capital-5-135","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[48] 西斯蒙第《政治经济学新原理》第1卷第113页。","language":"中文","translation":false},{"id":"capital-5-136","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[49] “一切劳动都是在它结束以后付给报酬的。”（《关于需求的性质的原理》第104页）“商业信用必定是从这样的时刻开始的，那时工人，生产的最初的创造者，有可能依靠自己的积蓄等待一两个星期、一个月、一季度等等，再领取自己劳动的工资。”（沙·加尼耳《论政治经济学的各种体系》1821年巴黎第2版第2卷第150页）","language":"中文","translation":false},{"id":"capital-5-137","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[50] 施托尔希说，“工人贷出自己的勤劳”，但是——他又狡猾地补充说——他们除了会“失掉自己的工资，不冒任何风险……工人没有付出任何物质的东西”。（施托尔希《政治经济学教程》1815年彼得堡版第2卷第36、37页）","language":"中文","translation":false},{"id":"capital-5-138","author":"马克思","title":"资本论·第一卷","location":"第四章 货币转化为资本","page":5,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/capital/04.htm","text":"[51] 举个例子。在伦敦有两种面包房：一种是按面包的全价出售的，一种是按低价出售的。后者占面包房总数的3/4以上。（政府调查委员休·西·特里门希尔关于《面包工人的申诉的报告》1862年伦敦版第32页)这些按低价出售的面包房所出售的面包，几乎无例外地都掺了明矾、肥皂、珍珠灰、白垩、得比郡石粉以及诸如此类的其他一些颇为可口的、富有营养的而又合乎卫生的成分。（见上述蓝皮书和《1855年食物掺假调查委员会的报告》，以及哈塞耳医生《揭穿了的掺假行为》1861年伦敦第2版）约翰·戈登爵士对1855年委员会说：“由于这种掺假，每天靠两磅面包度日的穷人，现在实际上连1/4的养料都得不到，且不说这种掺假对他们的健康的危害了。”特里门希尔（《面包工人的申诉的报告》第48页)认为，“工人阶级的很大一部分”明明知道掺假，可是还得去买明矾、石粉这一类东西，其原因就在于，对工人阶级来说，“面包房或杂货店爱给他们什么样的面包，他们就得买什么样的面包，这是必然的事情”。因为他们只是在劳动周的周末才得到报酬，所以，他们也只有“在周末才能支付全家—星期消费的面包钱”。特里门希尔还引用了一些证词：“众所周知，用这种混合物制成的面包是特意为这种主顾做的。”“在英格兰＜特别是苏格兰＞的许多农业区，工资是每两周、甚至每一个月发一次。支付期这样长，农业工人不得不赊购商品……他必须付出较高的价钱，他实际上已被赊卖东西给他的店铺束缚住了。例如，在威尔兹的浩宁汉，每月发一次工资，工人购买一英石面粉要付2先令4便士，而在别的地方则只要1先令10便士。”（《公共卫生。枢密院卫生视察员第6号报告》1864年版第264页)“1853年，佩斯里和基耳马尔诺克＜苏格兰西部＞的手工印染工人，通过一次罢工迫使支付期从一个月缩短为两周。”（《工厂视察员报告。1853年10月31日》第34页)英国许多煤矿主采取的方法可以说明，工人给资本家的信贷获得了进一步的、奇妙的发展。按照这种方法，工人到月底才领工资，在这期间从资本家那里得到预支，而预支往往就是一些工人不得不高于市场价格支付的商品（实物工资制)。“煤矿主惯用的一种办法就是，每月发一次工资，而在这一个月的每个周末给工人预支一次。预支是在店铺进行的<这个店铺就是老板自己开设的杂货店>。工人在店铺的这一边拿到钱，在另一边又把钱花掉。”（《童工调查委员会。第3号报告》1864年伦敦版第38页第192号）","language":"中文","translation":false},{"id":"capital-6-1","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-6-2","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"第五章 劳动过程和价值增殖过程","language":"中文","translation":false},{"id":"capital-6-3","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"劳动力的使用就是劳动本身。劳动力的买者消费劳动力，就是叫劳动力的卖者劳动。劳动力的卖者也就由此在实际上成为发挥作用的劳动力，成为工人，而在此以前，他只不过在可能性上是工人。为了把自己的劳动表现在商品中，他必须首先把它表现在使用价值中，表现在能满足某种需要的物中。因此，资本家要工人制造的是某种特殊的使用价值，是一定的物品。虽然使用价值或财物的生产是为了资本家，并且是在资本家的监督下进行的，但是这并不改变这种生产的一般性质。所以，劳动过程首先要撇开各种特定的社会形式来加以考察。","language":"中文","translation":false},{"id":"capital-6-4","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"劳动首先是人和自然之间的过程，是人以自身的活动来引起、调整和控制人和自然之间的物质变换的过程。人自身作为一种自然力与自然物质相对立。为了在对自身生活有用的形式上占有自然物质，人就使他身上的自然力——臂和腿、头和手运动起来。当他通过这种运动作用于他身外的自然并改变自然时，也就同时改变他自身的自然。他使自身的自然中沉睡着的潜力发挥出来，并且使这种力的活动受他自己控制。在这里，我们不谈最初的动物式的本能的劳动形式。现在，工人是作为他自己的劳动力的卖者出现在商品市场上。对于这种状态来说，人类劳动尚未摆脱最初的本能形式的状态已经是太古时代的事了。我们要考察的是专属于人的劳动。蜘蛛的活动与织工的活动相似，蜜蜂建筑蜂房的本领使人间的许多建筑师感到惭愧。但是，最蹩脚的建筑师从一开始就比最灵巧的蜜蜂高明的地方，是他在用蜂蜡建筑蜂房以前，已经在自己的头脑中把它建成了。劳动过程结束时得到的结果，在这个过程开始时就已经在劳动者的表象中存在着，即已经观念地存在着。他不仅使自然物发生形式变化，同时他还在自然物中实现自己的目的，这个目的是他所知道的，是作为规律决定着他的活动的方式和方法的，他必须使他的意志服从这个目的。但是这种服从不是孤立的行为。除了从事劳动的那些器官紧张之外，在整个劳动时间内还需要有作为注意力表现出来的有目的的意志，而且，劳动的内容及其方式和方法越是不能吸引劳动者，劳动者越是不能把劳动当作他自己体力和智力的活动来享受，就越需要这种意志。","language":"中文","translation":false},{"id":"capital-6-5","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"劳动过程的简单要素是：有目的的活动或劳动本身，劳动对象和劳动资料。","language":"中文","translation":false},{"id":"capital-6-6","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"土地（在经济学上也包括水）最初以食物，现成的生活资料供给人类[1]，它未经人的协助，就作为人类劳动的一般对象而存在。所有那些通过劳动只是同土地脱离直接联系的东西，都是天然存在的劳动对象。例如从鱼的生活要素即水中，分离出来的即捕获的鱼，在原始森林中砍伐的树木，从地下矿藏中开采的矿石。相反，已经被以前的劳动可以说滤过的劳动对象，我们称为原料。例如，已经开采出来正在洗的矿石。一切原料都是劳动对象，但并非任何劳动对象都是原料。劳动对象只有在它已经通过劳动而发生变化的情况下，才是原料。","language":"中文","translation":false},{"id":"capital-6-7","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"劳动资料是劳动者置于自己和劳动对象之间、用来把自己的活动传导到劳动对象上去的物或物的综合体。劳动者利用物的机械的、物理的和化学的属性，以便把这些物当作发挥力量的手段，依照自己的目的作用于其他的物[2]。劳动者直接掌握的东西，不是劳动对象，而是劳动资料（这里不谈采集果实之类的现成的生活资料，在这种场合，劳动者身上的器官是唯一的劳动资料）。这样，自然物本身就成为他的活动的器官，他把这种器官加到他身体的器官上，不顾圣经的训诫，延长了他的自然的肢体。土地是他的原始的食物仓，也是他的原始的劳动资料库。例如，他用来投、磨、压、切等等的石块就是土地供给的。土地本身是劳动资料，但是它在农业上要起劳动资料的作用，还要以一系列其他的劳动资料和劳动力的较高的发展为前提[3]。一般说来，劳动过程只要稍有一点发展，就已经需要经过加工的劳动资料。在太古人的洞穴中，我们发现了石制工具和石制武器。在人类历史的初期，除了经过加工的石块、木头、骨头和贝壳外，被驯服的，也就是被劳动改变的、被饲养的动物，也曾作为劳动资料起着主要的作用[4]。劳动资料的使用和创造，虽然就其萌芽状态来说已为某几种动物所固有，但是这毕竟是人类劳动过程独有的特征，所以富兰克林给人下的定义是，制造工具的动物。动物遗骸的结构对于认识已经绝迹的动物的机体有重要的意义，劳动资料的遗骸对于判断已经消亡的社会经济形态也有同样重要的意义。各种经济时代的区别，不在于生产什么，而在于怎样生产，用什么劳动资料生产[5]。劳动资料不仅是人类劳动力发展的测量器，而且是劳动借以进行的社会关系的指示器。在劳动资料中，机械性的劳动资料（其总和可称为生产的骨骼系统和肌肉系统）比只是充当劳动对象的容器的劳动资料（如管、桶、篮、罐等，其总和一般可称为生产的脉管系统）更能显示一个社会生产时代的具有决定意义的特征。后者只是在化学工业上才起着重要的作用。[5a]","language":"中文","translation":false},{"id":"capital-6-8","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"广义地说，除了那些把劳动的作用传达到劳动对象、因而以这种或那种方式充当活动的传导体的物以外，劳动过程的进行所需要的一切物质条件都算作劳动过程的资料。它们不直接加入劳动过程，但是没有它们，劳动过程就不能进行，或者只能不完全地进行。土地本身又是这类一般的劳动资料，因为它给劳动者提供立足之地，给他的过程提供活动场所。这类劳动资料中有的已经经过劳动的改造，例如厂房、运河、道路等等。","language":"中文","translation":false},{"id":"capital-6-9","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"可见，在劳动过程中，人的活动借助劳动资料使劳动对象发生预定的变化。过程消失在产品中。它的产品是使用价值，是经过形式变化而适合人的需要的自然物质。劳动与劳动对象结合在一起。劳动物化了，而对象被加工了。在劳动者方面曾以动的形式表现出来的东西，现在在产品方面作为静的属性，以存在的形式表现出来。劳动者纺纱，产品就是纺成品。","language":"中文","translation":false},{"id":"capital-6-10","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"如果整个过程从其结果的角度，从产品的角度加以考察，那末劳动资料和劳动对象表现为生产资料[6]，劳动本身则表现为生产劳动。[7]","language":"中文","translation":false},{"id":"capital-6-11","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"当一个使用价值作为产品退出劳动过程的时候，另一些使用价值，以前的劳动过程的产品，则作为生产资料进入劳动过程。同一个使用价值，既是这种劳动的产品，又是那种劳动的生产资料。所以，产品不仅是劳动过程的结果，同时还是劳动过程的条件。","language":"中文","translation":false},{"id":"capital-6-12","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"在采掘工业中，劳动对象是天然存在的，例如采矿业、狩猎业、捕鱼业等等中的情况就是这样（在农业中，只是在最初开垦处女地时才是这样）：除采掘工业以外，一切产业部门所处理的对象都是原料，即已被劳动滤过的劳动对象，本身已经是劳动产品。例如，农业中的种子就是这样。动物和植物通常被看作自然的产物，实际上它们不仅可能是上年度劳动的产品，而且它们现在的形式也是经过许多世代、在人的控制下、借助人的劳动不断发生变化的产物。尤其是说到劳动资料，那末就是最肤浅的眼光也会发现，它们的绝大多数都有过去劳动的痕迹。","language":"中文","translation":false},{"id":"capital-6-13","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"原料可以构成产品的主要实体，也可以只是作为辅助材料参加产品的形成。辅助材料或者被劳动资料消费，例如煤被蒸汽机消费，机油被轮子消费，干草被挽马消费；或者加在原料上，使原料发生物质变化，例如氯加在未经漂白的麻布上，煤加在铁上，颜料加在羊毛上；或者帮助劳动本身的进行，例如用于劳动场所的照明和取暖的材料。在真正的化学工业中，主要材料和辅助材料之间的区别就消失了，因为在所用的原料中没有一种会作为产品的实体重新出现。[8]","language":"中文","translation":false},{"id":"capital-6-14","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"因为每种物都具有多种属性，从而有各种不同的用途，所以同一产品能够成为很不相同的劳动过程的原料。例如，谷物是磨面者、制淀粉者、酿酒者和畜牧业者等等的原料。作为种子，它又是自身生产的原料。同样，煤作为产品退出采矿工业，又作为生产资料进入采矿工业。","language":"中文","translation":false},{"id":"capital-6-15","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"在同一劳动过程中，同一产品可以既充当劳动资料，又充当原料。例如，在牲畜饲养业中，牲畜既是被加工的原料，又是制造肥料的手段。","language":"中文","translation":false},{"id":"capital-6-16","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"一种已经完成可供消费的产品，能重新成为另一种产品的原料，例如葡萄能成为葡萄酒的原料。或者，劳动使自己的产品具有只能再作原料用的形式。这样的原料叫做半成品，也许叫做中间成品更合适些，例如棉花、线、纱等等。这种最初的原料虽然本身已经是产品，但还需要通过一系列不同的过程，在这些过程中，它不断改变形态，不断重新作为原料起作用，直到最后的劳动过程把它当作完成的生活资料或完成的劳动资料排出来。","language":"中文","translation":false},{"id":"capital-6-17","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"可见，一个使用价值究竟表现为原料、劳动资料还是产品，完全取决于它在劳动过程中所起的特定的作用，取决于它在劳动过程中所处的地位，随着地位的改变，这些规定也就改变。","language":"中文","translation":false},{"id":"capital-6-18","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"因此，产品作为生产资料进入新的劳动过程，也就丧失产品的性质。它们只是作为活劳动的物质因素起作用。在纺纱者看来，纱锭只是纺纱用的手段，亚麻只是纺纱的对象。当然，没有纺纱材料和纱锭是不能纺纱的。因此，在纺纱开始时，必须先有这两种产品。但是，亚麻和纱锭是过去劳动的产品这件事，对这个过程本身来说是没有关系的，正如面包是农民、磨面者、面包师等等过去劳动的产品这件事，对营养作用来说是没有关系的一样。相反，如果生产资料在劳动过程中显示出它是过去劳动的产品这种性质，那是由于它有缺点。不能切东西的刀，经常断头的纱等等，使人强烈地想起制刀匠Ａ和纺纱人Ｅ。就好的产品来说，它的使用属性由过去劳动创造这一点就看不出来了。","language":"中文","translation":false},{"id":"capital-6-19","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"机器不在劳动过程中服务就没有用。不仅如此，它还会由于自然界物质变换的破坏作用而解体。铁会生锈，木会腐朽。纱不用来织或编，会成为废棉。活劳动必须抓住这些东西，使它们由死复生，使它们从仅仅是可能的使用价值变为现实的和起作用的使用价值。它们被劳动的火焰笼罩着，被当作劳动自己的躯体，被赋予活力以在劳动过程中执行与它们的概念和职务相适合的职能，它们虽然被消费掉，然而是有目的地，作为形成新使用价值，新产品的要素被消费掉，而这些新使用价值，新产品或者可以作为生活资料进入个人消费领域，或者可以作为生产资料进入新的劳动过程。","language":"中文","translation":false},{"id":"capital-6-20","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"因此，如果说，现有的产品不仅是劳动过程的结果，而且是劳动过程的存在条件，那末另一方面，它们投入劳动过程，从而与活劳动相接触，则是使这些过去劳动的产品当作使用价值来保存和实现的唯一手段。","language":"中文","translation":false},{"id":"capital-6-21","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"劳动消费它自己的物质要素，即劳动对象和劳动资料，把它们吞食掉，因而是消费过程。这种生产消费与个人消费的区别在于：后者把产品当作活的个人的生活资料来消费，而前者把产品当作劳动即活的个人发挥作用的劳动力的生活资料来消费。因此，个人消费的产物是消费者本身，生产消费的结果是与消费者不同的产品。","language":"中文","translation":false},{"id":"capital-6-22","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"只要劳动资料和劳动对象本身已经是产品，劳动就是为创造产品而消耗产品，或者说，是把产品当作产品的生产资料来使用。但是，正如劳动过程最初只是发生在人和未经人的协助就已存在的土地之间一样，现在在劳动过程中也仍然有这样的生产资料，它们是天然存在的，不是自然物质和人类劳动的结合。","language":"中文","translation":false},{"id":"capital-6-23","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"劳动过程，就我们在上面把它描述为它的简单的抽象的要素来说，是制造使用价值的有目的的活动，是为了人类的需要而占有自然物，是人和自然之间的物质变换的一般条件，是人类生活的永恒的自然条件，因此，它不以人类生活的任何形式为转移，倒不如说，它是人类生活的一切社会形式所共有的。因此，我们不必来叙述一个劳动者与其他劳动者的关系。一边是人及其劳动，另一边是自然及其物质，这就够了。根据小麦的味道，我们尝不出它是谁种的，同样，根据劳动过程，我们看不出它是在什么条件下进行的：是在奴隶监工的残酷的鞭子下，还是在资本家的严酷的目光下；是在辛辛纳图斯耕种自己的几亩土地的情况下，还是在野蛮人用石头击杀野兽的情况下。[9]","language":"中文","translation":false},{"id":"capital-6-24","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"我们再回头来谈我们那位未来的资本家吧。我们离开他时，他已经在商品市场上购买了劳动过程所需要的一切因素：物的因素和人的因素，即生产资料和劳动力。他用内行的狡黠的眼光物色到了适合于他的特殊行业（如纺纱、制靴等等）的生产资料和劳动力。于是，我们的资本家就着手消费他购买的商品，劳动力；就是说，让劳动力的承担者，工人，通过自己的劳动来消费生产资料。当然，劳动过程的一般性质并不因为工人是为资本家劳动而不是为自己劳动就发生变化。制靴或纺纱的特定方式和方法起初也不会因资本家的插手就发生变化。起初，资本家在市场上找到什么样的劳动力就得使用什么样的劳动力，因而劳动在还没有资本家的时期是怎样的，资本家就得采用怎样的劳动。由劳动从属于资本而引起的生产方式本身的变化，以后才能发生，因而以后再来考察。","language":"中文","translation":false},{"id":"capital-6-25","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"劳动过程，就它是资本家消费劳动力的过程来说，显示出两个特殊现象。","language":"中文","translation":false},{"id":"capital-6-26","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"工人在资本家的监督下劳动，他的劳动属于资本家。资本家进行监视，使劳动正常进行，使生产资料用得合乎目的，即原料不浪费，劳动工具受到爱惜，也就是使劳动工具的损坏只限于劳动使用上必要的程度。","language":"中文","translation":false},{"id":"capital-6-27","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"其次，产品是资本家的所有物，而不是直接生产者工人的所有物。资本家例如支付劳动力一天的价值。于是，在这一天内，劳动力就象出租一天的任何其他商品（例如一匹马）一样，归资本家使用。商品由它的买者使用；劳动力的所有者提供他的劳动，实际上只是提供他已卖出的使用价值。从他进入资本家的工场时起，他的劳动力的使用价值，即劳动力的使用，劳动，就属于资本家了。资本家购买了劳动力，就把劳动本身当作活的酵母，并入同样属于他的各种形成产品的死的要素。从资本家的观点看来，劳动过程只是消费他所购买的劳动力商品，而他只有把生产资料加到劳动力上才能消费劳动力。劳动过程是资本家购买的各种物之间的过程，是归他所有的各种物之间的过程。因此，这个过程的产品归他所有，正象他的酒窖内处于发酵过程的产品归他所有一样。[10]","language":"中文","translation":false},{"id":"capital-6-28","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"产品——资本家的所有物——是一种使用价值，如棉纱、皮靴等等。虽然例如皮靴在某种意义上构成社会进步的基础，而我们的资本家也是一位坚决的进步派，但是他制造皮靴并不是为了皮靴本身。在商品生产中，使用价值绝不是本身受人喜爱的东西。在这里，所以要生产使用价值，是因为而且只是因为使用价值是交换价值的物质基质，是交换价值的承担者。我们的资本家所关心的是下述两点。第一，他要生产具有交换价值的使用价值，要生产用来出售的物品，商品。第二，他要使生产出来的商品的价值，大于生产该商品所需要的各种商品即生产资料和劳动力——为了购买它们，他已在商品市场上预付了真正的货币——的价值总和。他不仅要生产使用价值，而且要生产商品，不仅要生产使用价值，而且要生产价值，不仅要生产价值，而且要生产剩余价值。","language":"中文","translation":false},{"id":"capital-6-29","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"既然这里谈的是商品生产，所以事实上直到现在我们显然只考察了过程的一个方面。正如商品本身是使用价值和价值的统一一样，商品生产过程必定是劳动过程和价值形成过程的统一。","language":"中文","translation":false},{"id":"capital-6-30","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"现在我们就把生产过程作为价值形成过程来考察。","language":"中文","translation":false},{"id":"capital-6-31","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"我们知道，每个商品的价值都是由物化在它的使用价值中的劳动量决定的，是由生产该商品的社会必要劳动时间决定的。这一点也适用于作为劳动过程的结果而归我们的资本家所有的产品。因此，首先必须计算物化在这个产品中的劳动。","language":"中文","translation":false},{"id":"capital-6-32","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"生产棉纱，首先要有原料，例如10磅棉花，而棉花的价值是多少，在这里先用不着探究，因为资本家已经在市场上按照棉花的价值例如10先令把它购买了，在棉花的价格中，生产棉花所需要的劳动已经表现为一般社会劳动。我们再假定，棉花加工时消耗的纱锭量代表纺纱用掉的一切其他劳动资料，价值为2先令。如果12先令的金额是24个劳动小时或2个工作日的产物，那末首先可以得出，2个工作日物化在棉纱中。","language":"中文","translation":false},{"id":"capital-6-33","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"棉花改变了它的形状，被消耗的纱锭量完全消失了，但我们不应该受这种情况的迷惑。如果40磅棉纱的价值=40磅棉花的价值+1个纱锭的价值，也就是说，如果生产这个等式两边的产品需要同样的劳动时间，那末按照一般的价值规律，10磅棉纱就是10磅棉花和1/4个纱锭的等价物。在这种情况下，同一劳动时间一次体现在使用价值棉纱中，另一次体现在使用价值棉花和纱锭中。因此，价值无论表现在棉纱、纱锭或者棉花中，都是一样的。纱锭和棉花不再相安无事地并存着，而是在纺纱过程中结合在一起，这种结合改变了它们的使用形式，把它们变成了棉纱。但这种情况不会影响到它们的价值，就象它们通过简单的交换而换成等价物棉纱一样。","language":"中文","translation":false},{"id":"capital-6-34","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"生产棉花所需要的劳动时间，是生产以棉花为原料的棉纱所需要的劳动时间的一部分，因而包含在棉纱中。生产纱锭所需要的劳动时间也是如此，因为没有纱锭的磨损或消费，棉花就不能纺成纱。[11]","language":"中文","translation":false},{"id":"capital-6-35","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"因此，在考察棉纱的价值，即生产棉纱所需要的劳动时间时，可以把各种不同的在时间和空间上分开的特殊劳动过程，即生产棉花本身和生产所消耗的纱锭量所必须完成的劳动过程，以及最后用棉花和纱锭生产棉纱所必须完成的劳动过程，看成是同一个劳动过程的前后相继的不同阶段。棉纱中包含的全部劳动都是过去的劳动。至于生产棉纱的各形成要素所需要的劳动时间是早已过去的，是过去完成的，而在纺纱这一最后过程中直接耗费的劳动则是接近现在的，是现在完成的，这种情况是完全没有关系的。如果建筑一座房屋需要一定数量的劳动，例如30个工作日，那末体现在这座房屋中的劳动时间的总量，不会因为第30个工作日比第1个工作日晚29天而有所改变。因此，包含在劳动材料和劳动资料中的劳动时间，完全可以看成是在纺纱过程的早期阶段耗费的，是在最后以纺纱形式加进的劳动之前耗费的。","language":"中文","translation":false},{"id":"capital-6-36","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"因此，生产资料即棉花和纱锭的表现为12先令价格的价值，是棉纱价值或产品价值的组成部分。","language":"中文","translation":false},{"id":"capital-6-37","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"但是这里必须具备两个条件。第一，棉花和纱锭必须实际上用来生产使用价值。在我们所举的例子中，就是必须从棉花和纱锭生产出棉纱。对于价值说来，它由什么样的使用价值来承担都是一样的，但是它必须由一种使用价值来承担。第二，要假定所用的劳动时间只是一定社会生产条件下的必要劳动时间。如果纺1磅纱只需要1磅棉花，那末，纺1磅纱就只应当消耗1磅棉花，纱锭也是这样。如果资本家异想天开，要用金锭代替铁锭，那末在棉纱的价值中仍然只计算社会必要劳动，即生产铁锭所必要的劳动时间。","language":"中文","translation":false},{"id":"capital-6-38","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"现在，我们知道了，棉纱价值的哪一部分是由生产资料即棉花和纱锭构成的。这一部分价值等于12先令，等于2个工作日的化身。现在要考察纺纱工人本身的劳动加在棉花上的价值部分。","language":"中文","translation":false},{"id":"capital-6-39","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"现在，我们要从与考察劳动过程时完全不同的角度来考察这种劳动。在考察劳动过程时，谈的是使棉花变为棉纱的有目的的活动。在其他一切条件不变的情况下，劳动越合乎目的，棉纱就越好。纺纱工人的劳动是一种和其他生产劳动不同的特殊生产劳动。这种区别在主观方面和客观方面都表现出来，就是说，纺纱工人有特殊的目的，有特殊的操作方式，他的生产资料有特殊的性质，他的产品有特殊的使用价值。棉花和纱锭充当纺纱劳动的生活资料，但是不能用它们制造线膛炮。相反，就纺纱工人的劳动是形成价值的劳动，是价值源泉来说，它却和炮膛工人的劳动毫无区别，或者用一个更切近的例子来说，同植棉者和纱锭制造者体现在棉纱的生产资料中的劳动毫无区别。只是由于这种同一性，植棉、制锭和纺纱才能成为同一个总价值即棉纱价值的只有量的区别的各个部分。这里谈的不再是劳动的质，即劳动的性质和内容，而只是劳动的量。劳动的量是容易计算的。我们假定纺纱劳动是简单劳动，是社会平均劳动。以后我们会知道，相反的假定也不会对问题有丝毫影响。","language":"中文","translation":false},{"id":"capital-6-40","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"在劳动过程中，劳动不断由动的形式转为存在形式，由运动形式转为物质形式。一小时终了时，纺纱运动就表现为一定量的棉纱，于是一定量的劳动，即一个劳动小时，物化在棉花中。我们说劳动小时，就是纺纱工人的生命力在一小时内的耗费，因为在这里，纺纱劳动只有作为劳动力的耗费，而不是作为纺纱这种特殊劳动才具有意义。","language":"中文","translation":false},{"id":"capital-6-41","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"在这里具有决定意义的是，在过程的进行中，即在棉花变为棉纱时，消耗的只是社会必要劳动时间。如果在正常的即平均的社会的生产条件下，一个劳动小时内a磅棉花应该变为b磅棉纱，那末，只有把12×a磅棉花变成12×b磅棉纱的工作日，才能算是12小时工作日。因为只有社会必要劳动时间才算是形成价值的劳动时间。","language":"中文","translation":false},{"id":"capital-6-42","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"同劳动本身一样，在这里，原料和产品也都与我们从本来意义的劳动过程的角度考察时完全不同了。原料在这里只是当作一定量劳动的吸收器。通过这种吸收，原料事实上变成了棉纱，因为劳动力以纺纱形式耗费并加在原料中了。而产品棉纱现在只是棉花所吸收的劳动的测量器。如果1小时内有1 2/3磅棉花被纺掉，或者说，变成了1 2/3磅棉纱，那末10磅棉纱就表示6个被吸收的劳动小时。由经验确定的一定的产品量，现在只不过代表一定量的劳动，代表一定量凝固的劳动时间。它们只是一小时、两小时、一天的社会劳动的化身。","language":"中文","translation":false},{"id":"capital-6-43","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"在这里，劳动是纺纱劳动、它的原料是棉花、它的产品是棉纱这种情况，是没有关系的，正如劳动对象本身已经是产品、是原料这种情况没有关系一样。如果工人不是在纺纱厂做工，而是在煤矿做工，劳动对象煤就是天然存在的。但是，从矿床中开采出来的一定量的煤，例如一英担，依然代表一定量被吸收的劳动。","language":"中文","translation":false},{"id":"capital-6-44","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"在劳动力出卖时，曾假定它的日价值＝3先令，在3先令中体现了6个劳动小时，而这也就是生产出工人每天平均的生活资料量所需要的劳动量。现在，如果我们的纺纱工人在1个劳动小时内把1 2/3磅棉花变成1 2/3磅棉纱[12]，他在6小时内就会把10磅棉花变成10磅棉纱。因此，在纺纱过程中，棉花吸收了6个劳动小时。这个劳动时间表现为3先令金额。这样，由于纺纱本身，棉花就被加上了3先令的价值。","language":"中文","translation":false},{"id":"capital-6-45","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"现在我们来看看产品即10磅棉纱的总价值。在这10磅棉纱中物化着2 1/2个工作日：2日包含在棉花和纱锭量中，1/2日是在纺纱过程中被吸收的。这个劳动时间表现为15先令金额。因此，同10磅棉纱的价值相一致的价格是15先令，一磅棉纱的价格是1先令6便士。","language":"中文","translation":false},{"id":"capital-6-46","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"我们的资本家愣住了。产品的价值等于预付资本的价值。预付的价值没有增殖，没有产生剩余价值，因此，货币没有转化为资本。这10磅棉纱的价格是15先令，而在商品市场上为购买产品的各种形成要素或劳动过程的各种因素所花掉的也是15先令：10先令购买棉花，2先令购买所消耗的纱锭，3先令购买劳动力。棉纱的膨胀了的价值无济于事，因为棉纱的价值只是以前分配在棉花、纱锭和劳动力上的价值的总和，已有价值的这种单纯相加，永远也不能产生剩余价值[13]。这些价值现在集中在一个物上面，但是，在15先令分开来购买三种商品以前，这些价值就已经集中在一个15先令的货币额上了。","language":"中文","translation":false},{"id":"capital-6-47","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"这种结果本身是不足为奇的。一磅棉纱的价值是1先令6便士，因此，我们的资本家在商品市场上买10磅棉纱就得付出15先令。不管他是在市场上购买现成的房屋，还是自己建造一座房屋，无论哪一种做法都不会使置备房屋支出的货币增加。","language":"中文","translation":false},{"id":"capital-6-48","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"熟悉庸俗政治经济学的资本家也许会说：他预付自己货币的意图是要由此生出更多的货币。但是，通向地狱的道路是由良好的意图铺成的；他不进行生产，也同样可以有赚钱的意图[14]。他进行威胁。他说人们再也抓不住他的把柄了。以后他要在市场上购买现成的商品，不再自己制造。但是，如果他的所有资本家弟兄都这样做，他又怎能在市场上找到商品呢？而他又不能拿货币当饭吃。他进行说教。要人们想到他的节欲。他本来可以把他的15先令挥霍掉。他没有这样做，他生产地消费它们，把它们制成了棉纱。就算这样吧。可是他为此得到的是棉纱而不是后悔。他决不应该再去当货币贮藏者，后者已经向我们表明，禁欲会得到什么结果。而且，在一无所有的地方，皇帝也会丧失他的权力。不管他禁欲的功劳有多大，也没有东西可以用来付给禁欲以额外的报偿，因为退出生产过程的产品的价值只等于投入生产过程的商品价值的总和。他应该以“德有德报”来安慰自己。然而资本家不这样，他纠缠不休。说什么棉纱对他没有用处。他生产棉纱是为了出售。好，那就让他出售吧！或者更简单一些，让他以后只生产自己需要的东西吧，——这是他的家庭医生麦克库洛赫给他开的药方，作为防止生产过剩这种流行病的灵丹妙药。他强硬起来。难道工人光用一双手就能凭空创造产品，生产商品吗？难道不是他给工人材料，工人才能用这些材料并在这些材料之中来体现自己的劳动吗？社会上大多数人一贫如洗，他不是用自己的生产资料，棉花和纱锭，对社会和由他供给生活资料的工人本身进行了莫大的服务吗？难道他的服务不应该得到报酬吗？但是，工人把棉花和纱锭变为棉纱，不也就是为他服务了吗？而且这里的问题也不在于服务[15]。服务无非是某种使用价值发挥效用，而不管这种使用价值是商品还是劳动[16]。这里谈的是交换价值。他付给工人3先令价值。工人还给他一个完全相当的等价物，即加在棉花上的3先令价值，工人以价值偿还了价值。我们这位朋友刚才还以资本自傲，现在却突然变得和自己的工人一样谦逊了。难道他自己没有劳动吗？难道他没有从事监视和监督纺纱工人的劳动吗？他的这种劳动不也形成价值吗？但是，他的监工和经理耸肩膀了。而他得意地笑了笑，又恢复了他原来的面孔。他用一大套冗长无味的空话愚弄了我们。为此他不费一文钱。他把这一类虚伪的遁词和空话都交给他为此目的雇用的政治经济学教授们去讲。他自己是一个讲求实际的人，对于业务范围之外所说的话，虽然并不总是很好地考虑，但对于业务范围之内所做的事，他始终是知道的。","language":"中文","translation":false},{"id":"capital-6-49","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"让我们更仔细地来看一看。劳动力的日价值是3先令，因为在劳动力本身中物化着半个工作日，就是说，因为每天生产劳动力所必需的生活资料要费半个工作日。但是，包含在劳动力中的过去劳动和劳动力所能提供的活劳动，劳动力一天的维持费和劳动力一天的耗费，是两个完全不同的量。前者决定它的交换价值，后者构成它的使用价值。维持一个工人24小时的生活只需要半个工作日，这种情况并不妨碍工人劳动一整天。因此，劳动力的价值和劳动力在劳动过程中的价值增殖，是两个不同的量。资本家购买劳动力时，正是看中了这个价值差额。劳动力能制造棉纱或皮靴的有用属性，只是一个必要条件，因为劳动必须以有用的形式耗费，才能形成价值。但是，具有决定意义的，是这个商品独特的使用价值，即它是价值的源泉，并且是大于它自身的价值的源泉。这就是资本家希望劳动力提供的独特的服务。在这里，他是按照商品交换的各个永恒规律行事的。事实上，劳动力的卖者，和任何别的商品的卖者一样，实现劳动力的交换价值而让渡劳动力的使用价值。他不交出后者，就不能取得前者。劳动力的使用价值即劳动本身不归它的卖者所有，正如已经卖出的油的使用价值不归油商所有一样。货币所有者支付了劳动力的日价值，因此，劳动力一天的使用即一天的劳动就归他所有。劳动力维持一天只费半个工作日，而劳动力却能劳动一整天，因此，劳动力使用一天所创造的价值比劳动力自身一天的价值大一倍。这种情况对买者是一种特别的幸运，对卖者也绝不是不公平。","language":"中文","translation":false},{"id":"capital-6-50","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"我们的资本家早就预见到了这种情况，这正是他发笑的原因【93】。因此，工人在工场中遇到的，不仅是6小时而且是12小时劳动过程所必需的生产资料。如果10磅棉花吸收6个劳动小时，变为10磅棉纱，那末20磅棉花就会吸收12个劳动小时，变成20磅棉纱。我们来考察一下这个延长了的劳动过程的产品。现在，在这20磅棉纱中物化着5个工作日，其中4个工作日物化在已消耗的棉花和纱锭量中，1个工作日是在纺纱过程中被棉花吸收的。5个工作日用金来表现是30先令，或1镑10先令。因此这就是20磅棉纱的价格。1磅棉纱仍然和以前一样值1先令6便士。但是，投入劳动过程的商品的价值总和是27先令。棉纱的价值是30先令。产品的价值比为了生产产品而预付的价值增长了1/9。27先令变成了30先令，带来了3先令的剩余价值。戏法终于变成了。货币转化为资本了。","language":"中文","translation":false},{"id":"capital-6-51","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"问题的一切条件都履行了，商品交换的各个规律也丝毫没有违反。等价物换等价物。作为买者，资本家对每一种商品——棉花、纱锭和劳动力——都按其价值支付。然后他做了任何别的商品购买者所做的事情。他消费它们的使用价值。劳动力的消费过程（同时是商品的生产过程）提供的产品是20磅棉纱，价值30先令。资本家在购买商品以后，现在又回到市场上来出售商品。他卖棉纱是1先令6便士一磅，既不比它的价值贵，也不比它的价值贱。然而他从流通中取得的货币比原先投入流通的货币多3先令。他的货币转化为资本的这整个过程，既在流通领域中进行，又不在流通领域中进行。它是以流通为媒介，因为它以在商品市场上购买劳动力为条件。它不在流通中进行，因为流通只是为价值增殖过程作准备，而这个过程是在生产领域中进行的。所以，“在这个最美好的世界上，一切都十全十美”。【94】","language":"中文","translation":false},{"id":"capital-6-52","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"当资本家把货币变成商品，使商品充当新产品的物质形成要素或劳动过程的因素时，当他把活的劳动力同这些商品的死的物质合并在一起时，他就把价值，把过去的、物化的、死的劳动变为资本，变为自行增殖的价值，变为一个有灵性的怪物，它用“好象害了相思病”【95】的劲头开始去“劳动”。","language":"中文","translation":false},{"id":"capital-6-53","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"如果我们现在把价值形成过程和价值增殖过程比较一下，就会知道，价值增殖过程不外是超过一定点而延长了的价值形成过程。如果价值形成过程只持续到这样一点，即资本所支付的劳动力价值恰好为新的等价物所补偿，那就是单纯的价值形成过程。如果价值形成过程超过这一点，那就成为价值增殖过程。","language":"中文","translation":false},{"id":"capital-6-54","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"其次，如果我们把价值形成过程和劳动过程比较一下，就会知道，构成劳动过程的是生产使用价值的有用劳动。在这里，运动只是从质的方面来考察，从它的特殊的方式和方法，从目的和内容方面来考察。在价值形成过程中，同一劳动过程只是表现出它的量的方面。所涉及的只是劳动操作所需要的时间，或者说，只是劳动力被有用地消耗的时间长度。在这里，进入劳动过程的商品，已经不再作为在劳动力有目的地发挥作用时执行一定职能的物质因素了。它们只是作为一定量的物化劳动来计算。无论是包含在生产资料中的劳动，或者是由劳动力加进去的劳动，都只按时间尺度计算。它等于若干小时、若干日等等。","language":"中文","translation":false},{"id":"capital-6-55","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"但是，被计算的，只是生产使用价值所耗费的社会必要时间。这里包含下列各点。劳动力应该在正常的条件下发挥作用。如果纺纱机在纺纱业中是社会上通用的劳动资料，那就不能让工人使用手摇纺车。他所用的棉花也应该是正常质量的棉花，而不应该是经常断头的坏棉花。否则，在这两种情况下，他生产一磅棉纱所耗费的劳动时间就会超过社会必要劳动时间，而这些超过的时间并不形成价值或货币。不过，劳动的物质因素是否具有正常性质并不取决于工人，而是取决于资本家。再一个条件，就是劳动力本身的正常性质。劳动力在它被使用的专业中，必须具有在该专业占统治地位的平均的熟练程度、技巧和速度。而我们的资本家在劳动市场上也买到了正常质量的劳动力。这种劳动力必须以通常的平均的紧张程度，以社会上通常的强度来耗费。资本家小心翼翼地注视着这一点，正如他小心翼翼地注视着不让有一分钟不劳动而白白浪费掉一样。他购买的劳动力有一定的期限。他要从这上面得到属于他的东西。他不愿意被盗窃。最后，他不允许不合理地消费原料和劳动资料，——为此我们这位先生有他自己的刑法，——因为浪费了的原料或劳动资料是多耗费的物化劳动量，不能算数，不加入形成价值的产品中。[17]","language":"中文","translation":false},{"id":"capital-6-56","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"我们看到，以前我们分析商品时所发现的创造使用价值的劳动和创造价值的同一个劳动之间的区别，现在表现为生产过程的不同方面的区别了。","language":"中文","translation":false},{"id":"capital-6-57","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"作为劳动过程和价值形成过程的统一，生产过程是商品生产过程；作为劳动过程和价值增殖过程的统一，生产过程是资本主义生产过程，是商品生产的资本主义形式。","language":"中文","translation":false},{"id":"capital-6-58","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"我们在前面指出过，对于价值的增殖过程来说，资本家占有的劳动是简单的、社会平均劳动，还是较复杂的、比重较高的劳动，是毫无关系的。比社会平均劳动较高级较复杂的劳动，是这样一种劳动力的表现，这种劳动力比普通劳动力需要较高的教育费用，它的生产要花费较多的劳动时间，因此它具有较高的价值。既然这种劳动力的价值较高，它也就表现为较高级的劳动，也就在同样长的时间内物化为较多的价值。但是，无论纺纱工人的劳动和珠宝细工的劳动在程度上有多大差别，珠宝细工用来补偿自己的劳动力价值的那一部分劳动，与他用来创造剩余价值的那一部分追加劳动在质上完全没有区别。可见，在这两种场合，剩余价值都只是来源于劳动在量上的剩余，来源于同一个劳动过程——在一种场合是棉纱生产过程，在另一种场合是首饰生产过程——的延长。[18]","language":"中文","translation":false},{"id":"capital-6-59","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"另一方面，在每一个价值形成过程中，较高级的劳动总是要化为社会平均劳动，例如一日较高级的劳动化为x日简单的劳动[19]。因此，只要假定资本使用的工人是从事简单的社会平均劳动，我们就能省却多余的换算而使分析简化。","language":"中文","translation":false},{"id":"capital-6-60","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[1] “土地的自然产品，数量很小，并且完全不取决于人，自然提供这点产品，正象给一个青年一点钱，使他走上勤劳致富的道路一样。”（詹姆斯·斯图亚特《政治经济学原理》1770年都柏林版第1卷第116页）","language":"中文","translation":false},{"id":"capital-6-61","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[2] “理性何等强大，就何等狡猾。理性的狡猾总是在于它的间接活动，这种间接活动让对象按照它们本身的性质互相影响，互相作用，它自已并不直接参与这个过程，而只是实现自己的目的。”《黑格尔《哲学全书》，第1部《逻辑》,1840年柏林版第382页）","language":"中文","translation":false},{"id":"capital-6-62","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[3] 加尼耳的著作《政治经济学理论》〈1815年巴黎版）从其他方面来说是贫乏的，但针对重农学派，却恰当地列举了一系列构成真正的农业的前提的劳动过程。","language":"中文","translation":false},{"id":"capital-6-63","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[4] 杜尔哥在《关于财富的形成和分配的考察》（1766年）一书中，很好地说明了被饲养的动物对于文化初期的重要性。","language":"中文","translation":false},{"id":"capital-6-64","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[5] 在从工艺上比较各个不同的生产时代时，真正的奢侈品在一切商品中意义最小。","language":"中文","translation":false},{"id":"capital-6-65","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[5a] 第2版注：尽管直到现在，历史著作很少提到物质生产的发展，即整个社会生活以及整个现实历史的基础，但是，至少史前时期是在自然科学研究的基础上，而不是在所谓历史研究的基础上，按照制造工具和武器的材料，划分为石器时代、青铜时代和铁器时代的。","language":"中文","translation":false},{"id":"capital-6-66","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[6] 例如，把尚未捕获的鱼叫做渔业的生产资料，好象是奇谈怪论。但是至今还没有发明一种技术，能在没有鱼的水中捕鱼。","language":"中文","translation":false},{"id":"capital-6-67","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[7] 这个从简单劳动过程的观点得出的生产劳动的定义，对于资本主义生产过程是绝对不够的。","language":"中文","translation":false},{"id":"capital-6-68","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[8] 施托尔希把真正的原料和辅助材料区别开来，把前者叫做《matiere》，把后者叫做《materiaux》【90】；舍尔比利埃把辅助材料叫做《matieres instrumentales》【91】。","language":"中文","translation":false},{"id":"capital-6-69","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"【90】 亨·施托尔希《政治经济学教程，或论决定人民幸福的原理》1815年圣彼得堡版第1卷第288页（H. Storch.《Cours d'eeonomie politique, on Exposition des principes, qui determinent la prosperite des nations》. Tome I, St.-Petersbourg, 1815, p.288）。——第206页。","language":"中文","translation":false},{"id":"capital-6-70","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"【91】 安·舍尔比利埃《富或贫。社会财富当前分配的因果》1841年巴黎版第14页（A. Cherbuliez.《Richesse ou pauvrete. Exposition des causes et des effets de la distribution actuelle des richesses sociales》. Paris, 1841, p.14）。——第206页。","language":"中文","translation":false},{"id":"capital-6-71","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[9] 根据这种非常合乎逻辑的理由，托伦斯上校在野蛮人用的石头上发现了资本的起源。“在野蛮人用来投掷他所追遂的野兽的第一块石头上，在他用来打落他用手摘不到的果实的第一根棍子上，我们看到占有一物以取得另一物的情形，这样我们就发现了资本的起源。”(罗·托伦斯《论财富的生产》第70、71页）根据那第一根棍子［Stock］也许还可以说明，为什么在英语中Stock和资本是同义词。","language":"中文","translation":false},{"id":"capital-6-72","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[10] “产品在转化为资本以前就被占有了；这种转化并没有使它们摆脱那种占有。”（舍尔比利埃《富或贫》1841年巴黎版第54页）“无产者为换取一定量的生活资料出卖自己的劳动，也就完全放弃了对产品的任何分享。产品的占有还是和以前一样，并不因上述的契约而发生变化。产品完全归提供原料和生活资料的资本家所有。这是占有规律的严格结果，相反地，这个规律的基本原则却是每个劳动者对自已产品拥有专门的所有权。”（同上，第58页）詹姆斯·穆勒在《政治经济学原理》第70、71页上写道：“当工人是为工资而劳动时，资本家就不仅是资本的〈这里是指生产资料的〉所有者，而且是劳动的所有者。如果人们象通常那样，把用来支付工资的东西也包括在资本的概念中，那末撇开资本来谈劳动就是荒谬的。在这个意义上，资本一词包括资本和劳动二者。”","language":"中文","translation":false},{"id":"capital-6-73","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[11] “影响商品价值的，不仅是直接花费在商品上的劳动，而且还有花费在协助这种劳动的器具、工具和建筑物上的劳动。”（李嘉图《政治经济学原理》1821年伦敦第3版第1章第16页）","language":"中文","translation":false},{"id":"capital-6-74","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[12] 这里的数字完全是随意假设的。","language":"中文","translation":false},{"id":"capital-6-75","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[13] 这是重农学派关于一切非农业劳动都是非生产劳动的学说借以建立起来的根本命题，这个命题对于专业经济学家来说，是不容反驳的。“把许多其他东西的价值加在一个物上〈例如，把织工的生活费用加在麻布上〉，也就是说，把若干价值一层层地堆积在一个价值上，这种办法使价值有了相应的增加……‘加’这个词完美地表达了劳动产品价格形成的方式；这种价格不过是许多被消耗的、加在一起的价值的总和；‘加’并不意味着‘乘’。”（里维埃尔的迈尔西埃《政治社会天然固有的秩序》，载于《重农学派》1846年3黎版第2部第1章第599页）","language":"中文","translation":false},{"id":"capital-6-76","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[14] 例如，在1844—1847年，他从生产中抽出了一部分自己的资本，拿来在铁路股票上投机。又如，在美国南北战争时期，他关闭了工厂，把工人抛向街头，自己到利物浦棉花交易所去赌博。","language":"中文","translation":false},{"id":"capital-6-77","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[15] “你尽可以夸耀、粉饰和装扮……但是谁取得的<比他供给的>更多或更好，那就是高利贷。也就是说，象偷盗和抢劫一样，他不是为别人服务，而是损害别人。一切名为别人服务和行善的事情，并非都是服务和行善。奸夫和淫妇也是互相提供重大的服务和互相满足的。骑士帮助罪犯拦路行抢，打家劫舍，也是对罪犯的重大服务。罗马教徒没有把我们全部淹死、烧死、杀死、囚死，而是让一些人活着，把他们驱逐，或者夺去他们所有的东西，也是对我们的重大服务。魔鬼对于侍奉他的人也提供重大的不可估量的服务……总之，世上到处都是重大的、卓越的、日常的服务和行善。“（马丁·路德《给牧师们的谕示：讲道时要反对高利贷》1540年维登堡版）","language":"中文","translation":false},{"id":"capital-6-78","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[16] 关于这一点，我在《政治经济学批判》第14页上说过:“‘服务’这个范畴对于象让·巴·萨伊和弗·巴师夏那样的经济学家必然会提供怎样的‘服务’是不难了解的。”【92】","language":"中文","translation":false},{"id":"capital-6-79","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"【92】 见《马克思恩格斯全集》中文版第13卷第26页。——第218页。","language":"中文","translation":false},{"id":"capital-6-80","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"【93】 “这正是他发笑的原因”——套用了歌德《浮士德》第一部第三场（《浮士德的书斋》）中的一句话。——第220页。","language":"中文","translation":false},{"id":"capital-6-81","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"【94】 “在这个最美好的世界上，一切都十全十美”（《Tout pour le mieux dans le meilleur des mondes possibles》）伏尔泰小说《老实人》中的一句格言。——第221、841页。","language":"中文","translation":false},{"id":"capital-6-82","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"【95】 歌德《浮士德》第一部第五场（《莱比锡的欧北和酒寮》)。——第221页。","language":"中文","translation":false},{"id":"capital-6-83","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[17] 这是以奴隶制为基础的生产所以昂贵的原因之一。按照古人的恰当的说法，劳动者在这里只是会说话的工具，牲畜是会发声的工具，无生命的劳动工具是无声的工具，它们之间的区别只在于此。但劳动者本人却要让牲畜和劳动工具感觉到，他和它们不一样，他是人。他虐待它们，任性地毁坏它们，以表示自己与它们有所不同。 因此，这种生产方式的经济原则，就是只使用最粗糙、最笨重、因而很难损坏的劳动工具。正因如此，直到南北战争爆发之前，墨西哥湾沿岸各蓄奴州一直使用旧的中国式的犁。这种犁象猪和鼹鼠那样掘地，但不能把地犁出沟来，不能把土翻过来。参看约·埃·凯尔恩斯《奴隶劳力》1862年伦敦版第46页及以下各页。奥姆斯特德在他的《沿海各蓄奴州旅行记》［第46、47页］中也谈到：“我看到了这里使用的工具，在我们中间，任何一个有理性的人也不会把这样的工具交给他雇用的工人使用。这种工具异常笨重，在我看来，使用起来至少要比我们通常使用的工具多费百分之十的劲。然而人们却使我相信，由于奴隶使用工具不当心不仔细，就是给他们较轻便的或不太笨重的工具，也不可能有好结果；我们经常让工人使用的并为我们带来优厚利益的那些工具，在弗吉尼亚的麦田里用不上一天就会损坏，尽管那里的土地比我们的土地松软，而且没有那么多石块。当我问为什么各个农庄都普遍地用骡子代替马的时候，我听到的第一个最令人信服的理由，就是马受不住黑人的经常不断的虐待。马要是受到虐待，很快就会垮，变成残废，而骡子即使挨鞭子，饿一两次，也不会造成身体上的伤害。骡子在照料不周或劳累过度时，也不会受凉生病。我用不着走远，只要从我执笔写作的房间的窗户望出去，就几乎随时可以看到虐待牲畜的情形，而在北方，如果这样虐待牲畜，几乎每个农场主都会马上把工人解雇的。”","language":"中文","translation":false},{"id":"capital-6-84","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[18] 较高级劳动和简单劳动，熟练劳动和非熟练劳动之间的区别，一部分是根据单纯的幻想，或者至少是根据早就不现实的、只是作为传统惯例而存在的区别；一部分则是根据下面这样的事实：工人阶级的某些阶层处于更加贫困无靠的地位，比别人更难于取得自己劳动力的价值。在这方面，偶然的情况起着很大的作用，以致这两种劳动会互换位置。例如，在一切资本主义生产发达的国家中，工人阶级的体质已日趋孱弱和相当衰竭，因此，同很轻巧的细活相比，需要很多力气的粗活常常成为较高级劳动，而细活倒降为简单劳动。如瓦匠的劳动在英国要比锦缎工人的劳动高得多。另一方面，剪毛工人的劳动虽然体力消耗大，而且很不卫生，但仍被看作“简单”劳动。而且，不要以为所谓“熟练劳动”在国民劳动中占着相当大的数量。据兰格计算，英格兰（和威尔士)有1100多万人靠简单劳动为生。当时的人口总数是1800万，其中要减去100万贵族和150万需要救济的贫民、流浪汉、罪犯、娼妓等，还要减去465万中等阶级，其中包括小食利者、官吏、作家、艺术家、教员等等。为了凑足这465万的数目，除银行家等等之外他还把所有工资较高的“工厂工人”列为中等阶级中从事劳动的部分！甚至瓦匠也被列为“复杂劳动者”。这样剩下来的，便是上面说的1100万了。(赛·兰格《国家的贫因，贫困的原因及防止办法》1844年伦敦版[散见第49-52页])“除自己的普通劳动拿不出任何别的东西来换取食物的一个庞大阶级，占人口的大多数。”(詹姆斯·穆勒《殖民地》，载于《英国百科全书附册》1831年版）","language":"中文","translation":false},{"id":"capital-6-85","author":"马克思","title":"资本论·第一卷","location":"第五章 劳动过程和价值增殖过程","page":6,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/05.htm","text":"[19] “当人们说到作为价值尺度的劳动时，必定指一定种类的劳动……别种劳动对这种劳动的比例，是容易确定的。”（［约·卡泽诺夫］《政治经济学大纲》1832年伦敦版第22、23页）","language":"中文","translation":false},{"id":"capital-7-1","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-7-2","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"第六章 不变资本和可变资本","language":"中文","translation":false},{"id":"capital-7-3","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"劳动过程的不同因素在产品价值的形成上起着不同的作用。","language":"中文","translation":false},{"id":"capital-7-4","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"工人把一定量的劳动——撇开他的劳动所具有的特定的内容、目的和技术性质——加到劳动对象上，也就把新价值加到劳动对象上。另一方面我们发现，被消耗的生产资料的价值又成了产品价值的组成部分，例如，棉花和纱锭的价值包含在棉纱的价值中。可见，生产资料的价值由于转移到产品上而被保存下来。这种转移是在生产资料转化为产品时发生的，是在劳动过程中发生的。它是通过劳动实现的。然而是怎样实现的呢？","language":"中文","translation":false},{"id":"capital-7-5","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"工人并不是在同一时间内劳动两次：一次由自己的劳动把价值加到棉花上；另一次保存棉花的旧价值，或者说，把他所加工的棉花和使用的纱锭的价值转移到产品棉纱上。他只是由于加进新价值而保存了旧价值。但是，把新价值加到劳动对象上和把旧价值保存在产品中，是工人在同一时间内达到的两种完全不同的结果（虽然工人在同一时间内只劳动一次），因此很明显，这种结果的二重性只能用他的劳动本身的二重性来解释。在同一时间内，劳动就一种属性来说必然创造价值，就另一种属性来说必然保存或转移价值。","language":"中文","translation":false},{"id":"capital-7-6","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"每个工人怎样加进劳动时间，从而加进价值呢？始终只能通过他特有的生产劳动方式。纺纱工人只有通过纺纱，织布工人只有通过织布，铁匠只有通过打铁，才能加进劳动时间。而通过他们借以加进一般劳动、从而加进新价值的有目的的形式，通过纺纱、织布、打铁，生产资料棉花和纱锭，棉纱和织机，铁和铁砧也就成了产品即新的使用价值的形成要素[20]。生产资料的使用价值的旧形式消失了，但只是为了以新的使用价值形式出现。我们在考察价值形成过程时已经看到，只要使用价值是有目的地用来生产新的使用价值，制造被用掉的使用价值所必要的劳动时间，就成为制造新的使用价值所必要的劳动时间的一部分，也就是说，这部分劳动时间从被用掉的生产资料转移到新产品上去。可见，工人保存被用掉的生产资料的价值，或者说，把它们作为价值组成部分转移到产品上去，并不是由于他们加进一般劳动，而是由于这种追加劳动的特殊的有用性质，由于它的特殊的生产形式。劳动作为这种有目的的生产活动，纺纱、织布、打铁，只要同生产资料接触，就使它们复活，赋予它们活力，使它们成为劳动过程的因素，并且同它们结合为产品。","language":"中文","translation":false},{"id":"capital-7-7","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"如果工人的特殊的生产劳动不是纺纱，他就不能使棉花变成棉纱，因而也就不能把棉花和纱锭的价值转移到棉纱上。不过，如果这个工人改行当木匠，他仍然会用一个工作日把价值加到他的材料上。可见，他通过自己的劳动加进价值，并不是由于他的劳动是纺纱劳动或木匠劳动，而是由于他的劳动是一般的抽象的社会劳动；他加进一定的价值量，并不是因为他的劳动具有特殊的有用的内容，而是因为他的劳动持续了一定的时间。因此，纺纱工人的劳动，就它的抽象的一般的属性来说，作为人类劳动力的耗费，把新价值加到棉花和纱锭的价值上；而就它的具体的特殊的有用的属性来说，作为纺纱的过程，把这些生产资料的价值转移到产品上，从而把这些价值保存在产品中。由此就产生了劳动在同一时间内所得出的结果的二重性。","language":"中文","translation":false},{"id":"capital-7-8","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"新价值的加进，是由于劳动的单纯的量的追加；生产资料的旧价值在产品中的保存，是由于所追加的劳动的质。同一劳动由于它的二重性造成的这种二重作用，清楚地表现在种种不同的现象上。","language":"中文","translation":false},{"id":"capital-7-9","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"假定由于某种发明，纺纱工人6小时纺的棉花同过去36小时纺的棉花一样多。作为有目的的有用的生产活动，他的劳动的能力增加为6倍。他的劳动的产品也增加为6倍，从6磅棉纱增加到36磅棉纱。但是，现在36磅棉花吸收的劳动时间只和过去6磅棉花吸收的劳动时间一样多。加在每磅棉花上的新劳动比用旧方法时少5/6，因此，加进的价值也只是过去的1/6。另一方面，现在在产品36磅棉纱中包含6倍的棉花价值。纺纱6小时，保存并转移到产品上去的原料价值是过去的6倍，虽然加到同量原料上的新价值小5/6。这说明，在同一不可分割的过程中，劳动保存价值的属性和创造价值的属性在本质上是不同的。纺同量的棉花所必要的劳动时间越多，加到棉花上的新价值就越大；在同一劳动时间内纺的棉花磅数越多，保存在产品内的旧价值就越大。","language":"中文","translation":false},{"id":"capital-7-10","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"相反，假定纺纱劳动的生产率不变，就是说，纺纱工人把一磅棉花变成棉纱所需的时间同过去一样。但是假定棉花本身的交换价值变了，一磅棉花的价格提高到原来的6倍，或降低为原来的1/6。在这两种情况下，纺纱工人都是把同一劳动时间，因而也是把同一价值加到同量的棉花上；在这两种情况下，他都是在同样的时间内生产同样多的棉纱。然而，他从棉花转移到棉纱上即产品上的价值，在一种情况下是原来的1/6，在另一种情况下是原来的6倍。当劳动资料涨价或跌价，而它在劳动过程中始终发挥相同的效用时，情况也是如此。","language":"中文","translation":false},{"id":"capital-7-11","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"如果纺纱过程的技术条件不变，而且它的生产资料的价值也不变，那末纺纱工人在同样的劳动时间内就仍旧消耗同等数量的、价值不变的原料和机器。在这种情况下，纺纱工人保存在产品中的价值就同他加进的新价值成正比。他两星期加进的劳动比一星期多一倍，因而价值也多一倍；同时，他用掉的材料及其价值也多一倍，他损耗的机器及其价值也多一倍，因而，他在两星期的产品中保存的价值比在一星期的产品中多一倍。在已定的不变的生产条件下，工人加进的价值越多，他保存的价值就越多。但是，他能保存更多的价值，并不是因为他加进了更多的价值，而是因为他在不变的和不以他自己的劳动为转移的条件下加进这些价值。","language":"中文","translation":false},{"id":"capital-7-12","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"当然，从某种相对的意义上可以说，工人保存的旧价值同他加进的新价值总是保持同一比例。不管棉花从1先令涨到2先令或者跌到6便士，不管它的价值怎样变动，工人保存在一小时产品中的棉花价值总是只有保存在两小时产品中的一半。其次，如果他本身的劳动的生产率发生了变化，提高了或者降低了，那末，他例如一个劳动小时纺的棉花就会比过去增多或减少，与此相应，他保存在一个劳动小时产品中的棉花价值也会增多或减少。但是不管怎样，他两个劳动小时保存的价值总是一个劳动小时的两倍。","language":"中文","translation":false},{"id":"capital-7-13","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"把价值的纯粹象征性的表现——价值符号撇开，价值只是存在于某种使用价值中，存在于某种物中。（人本身单纯作为劳动力的存在来看，也是自然对象，是物，不过是活的有意识的物，而劳动本身则是这种力的物质表现。）因此，如果使用价值丧失，价值也就丧失。生产资料在丧失自己的使用价值的同时并不丧失价值，因为它们通过劳动过程失掉自己原来的使用价值形态，实际上只是为了在产品上获得另一种使用价值形态。虽然价值存在于某种使用价值中是很重要的，但是商品的形态变化表明，它存在于哪一种使用价值中是没有关系的。由此可见，在劳动过程中，只有生产资料失掉它的独立的使用价值同时也失掉它的交换价值，价值才从生产资料转移到产品上。生产资料转给产品的价值只是它作为生产资料而失掉的价值。但是在这方面，劳动过程的各种物质因素的情况是不同的。","language":"中文","translation":false},{"id":"capital-7-14","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"为发动机器而燃烧的煤消失得无影无踪，为润滑轮轴而上的油等等也是这样。染料和其他辅助材料消失了，但是又在产品的属性中表现出来。原料形成产品的实体，但是改变了自己的形式。可见，原料和辅助材料丧失了它们作为使用价值进入劳动过程时所具有的独立形态。真正的劳动资料却不是这样。工具、机器、厂房、容器等等，只有保持原来的形态，并且明天以同昨天一样的形式进入劳动过程，才能在劳动过程中发挥作用。它们在生前，在劳动过程中，与产品相对保持着独立的形态，它们在死后也是这样。机器、工具、厂房等等的尸骸同在它们帮助下形成的产品仍旧是分开的。如果我们考察某个这类的劳动资料从进入工作场所那天起到被扔进废品库那天止发挥作用的整个时期，就会看到，在这个时期中，它的使用价值已经完全被劳动消耗了，因此它的交换价值也完全转移到产品上去了。例如，一台纺纱机的寿命为10年，在10年的劳动过程中，它的全部价值就转移到10年的产品上去。因此，一种劳动资料的生存期，包括若干不断重新用它来反复进行的劳动过程。在这方面，劳动资料同人的情况一样。每人每天都死掉生命的24小时。但无论从谁身上都不能确切地看出，他已经死掉了生命的多少天。然而，这并不妨碍人寿保险公司从人的平均寿命中得出非常准确、非常有利（这重要得多）的结论。劳动资料也是这样。根据经验可以知道，一种劳动资料，例如某种机器，平均能用多少时间。假定这种劳动资料的使用价值在劳动过程中只能持续6天，那末它平均每个工作日丧失它的使用价值的1/6，因而把它的价值的1/6转给每天的产品。一切劳动资料的损耗，例如它们的使用价值每天的损失，以及它们的价值每天往产品上相应的转移，都是用这种方法来计算的。","language":"中文","translation":false},{"id":"capital-7-15","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"这十分清楚地表明，生产资料转给产品的价值决不会大于它在劳动过程中因本身的使用价值的消灭而丧失的价值。如果生产资料没有价值可以丧失，就是说，如果它本身不是人类劳动的产品，那末，它就不会把任何价值转给产品。它的作用只是形成使用价值，而不形成交换价值。一切未经人的协助就天然存在的生产资料，如土地、风、水、矿脉中的铁、原始森林中的树木等等，都是这样。","language":"中文","translation":false},{"id":"capital-7-16","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"在这里，我们遇到另一个有趣的现象。假定一台机器价值1000镑，并且在1000天内损耗掉。在这种情况下，机器的价值每天有1/1000从机器本身转移到它的日产品上。同时，尽管机器的生命力日益减弱，但整个机器仍然不断地在劳动过程中起作用。由此可见，劳动过程的一个因素，一种生产资料，是全部进入劳动过程，但只是部分地进入价值增殖过程。在这里，劳动过程和价值增殖过程的区别反映在它们的物质因素上：同一生产资料，作为劳动过程的要素，是全部加入同一生产过程；作为价值形成的要素，则只是部分加入同一生产过程。[21]","language":"中文","translation":false},{"id":"capital-7-17","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"另一方面正相反，一种生产资料能够全部进入价值增殖过程，而只是部分进入劳动过程。假定在把棉花纺成棉纱的时候，每天115磅棉花中有15磅没有变成棉纱，而是变成了飞花。如果损失这15磅棉花是正常的，在棉花的平均加工条件下是不可避免的，那末这15磅棉花虽然不是棉纱的要素，但它的价值同形成棉纱实体的100磅棉花的价值完全一样，也加入棉纱的价值中。为了生产100磅棉纱，15磅棉花的使用价值必须化为飞花。因此，这些棉花的损失是棉纱的一个生产条件。正因为如此，它们才把自己的价值转给棉纱。劳动过程中的一切排泄物都是这样，至少在这些排泄物不再形成新的生产资料，因而不再形成新的独立的使用价值的情况下是这样。例如我们在曼彻斯特的大机器制造厂内可以看到，被庞大的机器象刨花一样削下的铁屑堆积如山，傍晚用大车运到炼铁厂去，第二天变成铁锭再运回来。","language":"中文","translation":false},{"id":"capital-7-18","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"生产资料只有在劳动过程中丧失掉存在于旧的使用价值形态中的价值，才把价值转移到新形态的产品上。它们在劳动过程中所能丧失的最大限度的价值量，显然是以它们进入劳动过程时原有的价值量为限，或者说，是以生产它们自身所必要的劳动时间为限。因此，生产资料加到产品上的价值决不可能大于它们在自己参加的劳动过程之外所具有的价值。不管一种劳动材料，一种机器，一种生产资料怎样有用，如果它值150镑，值500个工作日，那末它加到用它制造的总产品上去的价值就决不会大于150镑。它的价值不是由它作为生产资料进入的劳动过程决定的，而是由它作为产品被生产出来的劳动过程决定的。它在劳动过程中只是作为使用价值，作为具有有用属性的物起作用，因此，如果它在进入劳动过程之前没有价值，它就不会把任何价值转给产品。[22]","language":"中文","translation":false},{"id":"capital-7-19","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"当生产劳动把生产资料变为新产品的形成要素时，生产资料的价值也就经过一次轮回。它从已消耗的躯体转到新形成的躯体。但是这种轮回似乎是在现实的劳动背后发生的。工人不保存旧价值，就不能加进新劳动，也就不能创造新价值，因为他总是必须在一定的有用的形式上加进劳动；而他不把产品变为新产品的生产资料，从而把它们的价值转移到新产品上去，他就不能在有用的形式上加进劳动。可见，由于加进价值而保存价值，这是发挥作用的劳动力即活劳动的自然恩惠，这种自然恩惠不费工人什么，但对资本家却大有好处，使他能够保存原有的资本价值[22a]。当生意兴隆的时候，资本家埋头赚钱，觉察不到劳动的这种无偿的恩惠。但当劳动过程被迫中断的时候，当危机到来的时候，资本家对此就有切肤之感了。[23]","language":"中文","translation":false},{"id":"capital-7-20","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"就生产资料来说，被消耗的是它们的使用价值，由于这种使用价值的消费，劳动制成产品。生产资料的价值实际上没有被消费[24]，因而也不可能再生产出来。这个价值被保存下来，但不是因为在劳动过程中对这个价值本身进行了操作，而是因为这个价值原先借以存在的那种使用价值虽然消失，但只是消失在另一种使用价值之中。因此，生产资料的价值是再现在产品的价值中，确切地说，不是再生产。所生产出来的是旧交换价值借以再现的新使用价值。[25]","language":"中文","translation":false},{"id":"capital-7-21","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"劳动过程的主观因素，即发挥作用的劳动力，却不是这样。当劳动通过它的有目的的形式把生产资料的价值转移到产品上并保存下来的时候，它的运动的每时每刻都形成追加的价值，形成新价值。假设生产过程在工人生产出他自己的劳动力价值的等价物以后就停下来，例如，他劳动6小时加进3先令价值。这个价值是产品价值超过其中由生产资料价值构成的部分而形成的余额。它是在这个过程中产生的唯一的新价值，是产品中由这个过程本身生产的唯一的价值部分。当然，它只是补偿资本家在购买劳动力时预付的，工人自身在生活资料上花费的货币。就已花费的3先令来说，这3先令的新价值只是表现为再生产。但它是真正的再生产，不象生产资料的价值只是表面上的再生产。在这里，一个价值用另一个价值来补偿是通过创造新价值来实现的。","language":"中文","translation":false},{"id":"capital-7-22","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"然而我们已经知道，劳动过程在只是再生产出劳动力价值的等价物并把它加到劳动对象上以后，还越过这一点继续下去。要再生产出这一等价物，6小时就够了，但是劳动过程不是持续6小时，而是比如说持续12小时。这样，劳动力发挥作用的结果，不仅再生产出劳动力自身的价值，而且生产出一个超额价值。这个剩余价值就是产品价值超过消耗掉的产品形成要素即生产资料和劳动力的价值而形成的余额。","language":"中文","translation":false},{"id":"capital-7-23","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"我们叙述了劳动过程的不同因素在产品价值的形成中所起的不同作用，事实上也就说明了资本的不同组成部分在资本本身的价值增殖过程中所执行的不同职能。产品的总价值超过产品的形成要素的价值总额而形成的余额，就是价值已经增殖的资本超过原预付资本价值而形成的余额。一方面是生产资料，另一方面是劳动力，它们不过是原有资本价值在抛弃货币形式而转化为劳动过程的因素时所采取的不同的存在形式。","language":"中文","translation":false},{"id":"capital-7-24","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"可见，变为生产资料即原料、辅助材料、劳动资料的那部分资本，在生产过程中并不改变自己的价值量。因此，我把它称为不变资本部分，或简称为不变资本。","language":"中文","translation":false},{"id":"capital-7-25","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"相反，变为劳动力的那部分资本，在生产过程中改变自己的价值。它再生产自身的等价物和一个超过这个等价物而形成的余额，剩余价值。这个剩余价值本身是可以变化的，是可大可小的。这部分资本从不变量不断变为可变量。因此，我把它称为可变资本部分，或简称为可变资本。资本的这两个组成部分，从劳动过程的角度看，是作为客观因素和主观因素，作为生产资料和劳动力相区别的；从价值增殖过程的角度看，则是作为不变资本和可变资本相区别的。","language":"中文","translation":false},{"id":"capital-7-26","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"不变资本这个概念决不排斥它的组成部分发生价值变动的可能性。假定1磅棉花今天值6便士，明天由于棉花歉收而涨到1先令。仍在加工中的原有的棉花，是按6便士的价值买进的，但现在加到产品上的价值部分却是1先令。已经纺完，也许已经变成棉纱在市场上流通的棉花，加到产品上的价值同样也比它原来的价值大一倍。然而我们知道，这种价值变动是同纺纱过程中棉花价值的增殖没有关系的，即使原有的棉花还根本没有进入劳动过程，它现在也能按1先令而不是按6便士再卖出去。不仅如此，棉花经历的劳动过程越少，这种结果就越可靠。因此，投机的规律是：在价值发生这种变动的情况下，要在加工最少的原料上进行投机，就是说，棉布不如棉纱，棉纱不如棉花。在这里，价值的变动是发生在生产棉花的过程中，而不是发生在棉花作为生产资料，从而作为不变资本执行职能的过程中。商品的价值固然是由商品所包含的劳动量决定的，但这个劳动量本身是社会地决定的。如果生产商品的社会必要劳动时间改变了，例如，同一数量的棉花在歉收时比在丰收时代表更多的劳动量，那就会反过来对原有的商品发生影响，因为原有的商品始终只是本类商品的一个样品[26]，它的价值总是由社会必要劳动计量的，因而也总是由现有的社会条件下的必要劳动计量的。","language":"中文","translation":false},{"id":"capital-7-27","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"同原料的价值一样，已经用在生产过程中的劳动资料即机器等等的价值，也可以发生变化，因此它们转移到产品上去的那部分价值也会发生变化。例如，由于一种新发明，同种机器可由较少的劳动再生产出来，那末旧机器就要或多或少地贬值，因而转移到产品上去的价值也要相应地减少。但就是在这种情况下，价值变动也是在机器作为生产资料执行职能的生产过程以外发生的。机器在这个过程中转移的价值决不会大于它在这个过程之外所具有的价值。","language":"中文","translation":false},{"id":"capital-7-28","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"生产资料的价值变动，虽然使已经进入生产过程的生产资料受到影响，但不会改变生产资料作为不变资本的性质。同样，不变资本和可变资本之间的比例的变化也不会影响它们在职能上的区别。例如，劳动过程的技术条件大大革新了，过去10个工人用10件价值很小的工具只能加工比较少量的原料，现在1个工人用1台昂贵的机器就能加工一百倍的原料。在这种情况下，不变资本即被使用的生产资料的价值量大大增加了，而资本的可变部分即预付劳动力的部分则大大减少了。但是，这种变动只改变不变资本和可变资本的量的关系，或者说，只改变总资本分为不变部分和可变部分的比例，而不影响不变资本和可变资本的区别。","language":"中文","translation":false},{"id":"capital-7-29","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[20] “劳动创造一种新物来代替被消灭的物。”（《论国民政治经济学》1821年伦敦版第13页）","language":"中文","translation":false},{"id":"capital-7-30","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[21] 这里不包括劳动资料即机器、建筑物等等的修理。正在修理中的机器不是充当劳动资料，而是充当劳动材料。不是用它来劳动，而是对它本身进行加工，以便修复它的使用价值。为了我们的目的，我们可以设想，这种修理劳动总是包括在生产劳动资料所必要的劳动中。正文中所说的那种损耗是任何医生都不能医治的，它逐渐导致死亡。“这种磨损有时是不可能补偿的，例如，它会使一把刀最后弄到这种地步，连磨刀匠也会说，这把刀子不值得再开刃了。”我们在正文中看到，例如机器是全部进入每一个劳动过程，但只是部分进入同时进行的价值增殖过程。拫据这一点，我们可以判断下述概念的混乱了：“李嘉图说，机器制造工人制造织袜机时耗费的劳动的一部分”，包含在例如一双袜子的价值内。“可是制造每一双袜子的全部劳动……包含机器制造工人的全部劳动，而不只是他的一部分劳动。因为，虽然一台机器织出许多双袜子，但是缺少机器的任何一部分，连一双袜子也制造不出来。”（《评政治经济学上若干用语的争论，特别是有关价值、供求的争论》1821年伦敦版第54页）这位作者，这位极端自负的“自作聪明的人”，他的混乱，从而他的论战，只有从下面这一点来说是对的：无论李嘉图，还是在他以前或以后的其他任何经济学家，都没有把劳动的两个方面准确地区分开来，自然更没有对这两方面在价值形成上所起的不同作用作出分析。","language":"中文","translation":false},{"id":"capital-7-31","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[22] 我们可以由此了解庸俗的让·巴·萨伊的荒诞无稽了：他想从生产资料(土地、工具、皮革等等)的使用价值在劳动过程中所提供的“生产服务”，引出剩余价值(利息、利润、地租)。决不轻易放过机会把精巧的辩护思想用黑字写在白纸上的威廉·罗雪尔先生则喊道：“让·巴·萨伊在《论政治经济学》第一卷第四章中非常正确地指出，‘榨油机所生产的价值扣除一切费用后，还留下一种同制造榨油机本身所费的劳动有本质区别的新东西’。”(《国民经济学原理》1858年第3版第82页注)非常正确！榨油机所生产的“油”同制造榨油机所费的劳动是很不相同的。罗雪尔先生所说的“价值”是指“油”这种东西，因为“油”有价值；但“自然界”有石油，尽管相对来说不“很多”，他大概针对这一点在另一个地方说道：“它<自然界!>几乎完全不生产交换价值。”[同上，第79页]罗雪尔的自然界同交换价值有关系，就象一个愚蠢的姑娘同一个只有“一点点大的”孩子有关系一样。这位“学者”还借这次引证的机会说道：“李嘉图学派通常把资本当作‘积蓄的劳动’包括在劳动概念内，这是不高明的，因为资本所有者不单纯是生产和保存它<什么东西?>，而且的确还做了更多的事情：就是节制了自己的享受，为此，比如说，他要求得到利息。”（同上，[第82页]）这种单纯从“要求”中得出“价值”的政治经济学的“解剖学和生理学方法”是多么“高明”啊！","language":"中文","translation":false},{"id":"capital-7-32","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[22a] “在农业的一切手段中，人类劳动……是农场主用来补偿自己资本的最可靠的东西。其他两类东西——役畜和……车、犁、铲等等——没有一定量的人类劳动， 就毫无用处。”（艾德蒙·伯克《关于贫困的意见和详情，原系1795年11月向最尊敬的威廉·皮特提出的报告》1800年伦敦版第10页）","language":"中文","translation":false},{"id":"capital-7-33","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[23] 有一个工厂主，他的纺纱厂共雇用800个工人，每周平均消耗150包东印度棉花或约130包美国棉花。他在1862年11月26日的《泰晤士报》上曾为了他的工厂每年停工的花费向公众诉苦。他估计这笔花费达6000镑。在这些非生产费用中，有许多项目同我们这里无关，如地租、税款、保险费以及按年雇用的人员——经理、会计、工程师的薪金等等。然后，依他计算，为了购买工厂有时取暖和偶而开动蒸汽机所用的煤共需150镑。此外还要支付临时雇来保养机器的工人的工资。最后，机器的折旧为1200镑，因为“天气和自然的腐蚀力并不因蒸汽机停止运转就不再发挥作用”。他明白地说，折旧所以只估计为1200镑这样一个很小的数目，是因为机器已经很破旧了。","language":"中文","translation":false},{"id":"capital-7-34","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[24] “生产消费：在生产消费中，商品的消费是生产过程的一部分……在这种情况下价值没有被消费。”（赛·菲·纽曼《政治经济学原理》1835年安多佛和纽约版第296页）","language":"中文","translation":false},{"id":"capital-7-35","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[25] 在一本也许已经出到20版的美国教本中，有这样的话：“资本以什么形式再现是无关紧要的。”该书在罗列了一切可能在产品中再现自己价值的生产成分之后，得出结论说：“人们生存和安乐所必需的各种食物、衣服和住房同样会发生变化。它们时时被消费掉，而它们的价值则作为它们给予人的肉体和精神的新力量再现出来，从而形成新的资本，再用于生产过程。”(弗·威兰德《政治经济学原理》1843年波士顿版第31、32页)我们撇开所有其他的奇怪说法不谈，只须指出，例如在新力量中再现的，并不是面包的价格，而是形成血液的面包的实体。相反，作为这个力量的价值再现的，也并不是生活资料，而是生活资料的价值。同样一些生活资料，如果它的费用减少一半，仍然产生同样多的肌肉、骨骼等等，总之，仍然产生同等的力量，但不是同等价值的力量。这种把“价值”换成“力量”，以及全部伪善的含糊其辞，掩盖着这样一种显然徒劳的企图：想从预付价值的单纯再现中得出剩余价值。】","language":"中文","translation":false},{"id":"capital-7-36","author":"马克思","title":"资本论·第一卷","location":"第六章 不变资本和可变资本","page":7,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/06.htm","text":"[26] “全部同类产品其实只是一个量，这个量的价格是整个地决定的，而不以特殊情况为转移。”（列特隆《论社会利益》第893页）","language":"中文","translation":false},{"id":"capital-8-1","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-8-2","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"2、产品价值在产品相应部分上的表现","language":"中文","translation":false},{"id":"capital-8-3","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"3、西尼耳的“最后一小时”","language":"中文","translation":false},{"id":"capital-8-4","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"预付资本C在生产过程中生出的剩余价值，或预付资本价值C的价值增殖额，首先表现为产品价值超过它的各种生产要素的价值总和而形成的余额。","language":"中文","translation":false},{"id":"capital-8-5","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"资本C分为两部分，一部分是为购买生产资料而支出的货币额c，另一部分是为购买劳动力而支出的货币额v；c代表转化为不变资本的价值部分，v代表转化为可变资本的价值部分。因此，最初是C=c+v，例如，预付资本500镑=410镑c+90镑v。在生产过程结束时得到商品，它的价值=c+v+m(m是剩余价值)，例如，410镑c+90镑v+90镑m。原来的资本C变为C'，由500镑变为590镑。二者的差额=m，即90镑剩余价值。因为各种生产要素的价值等于预付资本的价值，所以，说产品价值超过它的各种生产要素的价值而形成的余额，等于预付资本的价值增殖额，或等于生产出来的剩余价值，实际上是同义反复。","language":"中文","translation":false},{"id":"capital-8-6","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"然而，对这个同义反复需要作进一步的规定。这里同产品价值相比较的，是它形成过程中消耗的各种生产要素的价值。但是我们已经知道，由劳动资料构成的那部分被使用的不变资本只是把自己价值的一部分转给产品，而其余的部分仍然保留在原来的存在形式中。既然这后一部分在价值形成中不起任何作用，在这里就可以把它抽去。即使把它计算进去，也不会引起任何改变。假定c=410镑，由原料312镑、辅助材料44镑和在过程中磨损的机器54镑组成，而实际使用的机器的价值是1054镑。我们只把机器因执行职能而失掉的并因而转给产品的54镑价值，算作为生产产品价值而预付的价值。如果我们把仍然保留在原来形式(如蒸汽机等等)中的1000镑计算进去，就必须在预付价值和产品价值这两边都加上1000镑[26a]。这样，一边就是1500镑，另一边就是1590镑。差额或剩余价值仍然是90镑。因此，凡从上下文联系中得不出相反意思的地方，我们谈到为生产价值而预付的不变资本时，总只是指在生产中消耗的生产资料的价值。","language":"中文","translation":false},{"id":"capital-8-7","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"根据这样的假定，我们再回头来谈C=c+v这个公式，这个公式现在变成了C'=c+v+m，并且正因为这样，C变成了C'。我们知道，不变资本的价值只是再现在产品中。可见，在生产过程中实际新生产的价值产品，是和从这个过程中得到的产品价值不同的。因此，它不象乍一看来那样，仿佛是c+v+m，或410镑c+90镑v+90镑m，而是v+m，或90镑v+90镑m，不是590镑，而是180镑。如果不变资本c=0，换句话说，如果有这样一些产业部门，它们的资本家可以不使用经过生产的生产资料，不使用原料、辅助材料，也不使用劳动工具，而只是使用天然存在的材料和劳动力，那末，就不会有不变价值部分转移到产品上去。产品价值的这个要素，即我们例子中的410镑，就会消失，但是包含90镑剩余价值的180镑的价值产品仍然同c代表最大的价值额时一样大。现在，C=0+v=v，而已经增殖的资本C'=v+m，C'－C仍然=m。相反，如果m=0，换句话说，假定劳动力(其价值是在可变资本上预付的)只是生产了自己的等价物，那末C=c+v，C'(产品价值)=c+v+0，因此，C=C'。预付资本没有增殖。","language":"中文","translation":false},{"id":"capital-8-8","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"实际上我们已经知道，剩余价值只是v这个变为劳动力的资本部分发生价值变动的结果，因此，v+m=v+△v(v加v的增长额)，但是现实的价值变化和价值变化的比率却是被这样的事实掩盖了：由于资本可变部分的增加，全部预付资本也增加了。全部预付资本以前是500，现在变成了590。可见，要对这个过程进行纯粹的分析，必须把产品价值中只是不变资本价值的再现的那一部分完全抽去，就是说，必须使不变资本c=0。为此，这里要运用数学上的一条定律，就是数学上运算变量和常量的定律，即运算常量同变量相加减的定律。","language":"中文","translation":false},{"id":"capital-8-9","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"另一个困难是由可变资本的原有形式产生的。比如在上述例子中，C'=410镑不变资本+90镑可变资本+90镑剩余价值。90镑是已知量，因而是不变量，因此把它当作可变量似乎是不合理的。但90镑v或90镑可变资本，在这里实际上只是这个价值所经过的过程的符号。购买劳动力所预付的资本部分是一定量的物化劳动，因而同购买来的劳动力的价值一样，是一个不变的价值量。但是，在生产过程本身中，预付的90镑为发挥作用的劳动力所代替，死劳动为活劳动所代替，静止量为流动量所代替，不变量为可变量所代替。结果是v的再生产加v的增长额。从资本主义生产的观点来看，这全部进程是转化为劳动力的那个原来不变的价值的自行运动。过程及其结果都要归因于这个价值。因此，如果说90镑可变资本或自行增殖的价值这个说法看来是矛盾的，那末它只是表现了资本主义生产固有的矛盾。","language":"中文","translation":false},{"id":"capital-8-10","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"乍一看来，假定不变资本等于0是很奇怪的。但在日常生活中人们经常这样做。例如，有人要计算英国棉纺织业的利润，他首先就会扣除付给美国、印度、埃及等国的棉花价格，就是说，使在产品价值中只是再现出来的资本价值=0。","language":"中文","translation":false},{"id":"capital-8-11","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"当然，不仅剩余价值同直接产生它并由它来表示其价值变化的那部分资本的比率具有重大的经济意义，而且剩余价值同全部预付资本的比率也具有重大的经济意义。因此我们将在第三卷中详细讨论后一比率。要使资本的一部分变成劳动力而增殖，就必须使资本的另一部分变成生产资料。要使可变资本起作用，就必须根据劳动过程的一定的技术性质，按相应的比例来预付不变资本。一定的化学过程固然需要蒸馏器及其他容器，但这并不妨碍我们在分析时把蒸馏器抽去。如果仅仅就价值创造和价值变化本身进行考察，也就是说，进行纯粹的考察，那末生产资料，这些不变资本的物质形态，就只是提供一种物质，使流动的、形成价值的力得以固定在上面。因此，这种物质的性质如何是没有关系的，无论它是棉花还是铁都一样。这种物质的价值如何也是没有关系的。它只须有足够的量，以便能吸收生产过程中要消耗的劳动量。只要有了足够的量，不管它的价值提高或是降低，或者象土地和大海那样没有价值，都不会影响价值创造和价值变化的过程。[27]","language":"中文","translation":false},{"id":"capital-8-12","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"这样，我们先假定不变资本部分等于零。于是，预付资本就从c+v简化为v，产品价值c+v+m就简化为价值产品v+m。假定价值产品=180镑，代表整个生产过程期间流动的劳动，那我们从中扣除90镑可变资本的价值，就可得到90镑剩余价值。90镑(m)这个数字在这里表示所生产的剩余价值的绝对量。剩余价值的相对量，即可变资本价值增殖的比率，显然由剩余价值同可变资本的比率来决定，或者用m/v来表示。在上述例子中，它是90/90=100％。我把可变资本的这种相对的价值增殖或剩余价值的相对量，称为剩余价值率。[28]","language":"中文","translation":false},{"id":"capital-8-13","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"我们已经知道，工人在劳动过程的一段时间内，只是生产自己劳动力的价值，就是说，只是生产他必需的生活资料的价值。因为他是在以社会分工为基础的状态下进行生产，所以他不是直接生产自己的生活资料，而是在某种特殊的商品形式(如棉纱)上生产出同他的生活资料的价值相等的价值，或者说，同他用来购买生活资料的货币相等的价值。他为此需用的工作日部分是大小不同的，这取决于他每天平均的生活资料的价值，也就是取决于每天生产这些生活资料所需要的平均劳动时间。如果工人每天的生活资料的价值平均代表6个物化劳动小时，那末，工人要生产这个价值，就必须平均每天劳动6小时。如果他不是为资本家劳动，而是独立地为自己劳动，在其他条件相同的情况下，他平均一天同样要劳动这么多小时，才能生产出自己的劳动力的价值，从而获得维持或不断再生产自己所必需的生活资料。但是，既然工人在生产劳动力日价值(如3先令)的工作日部分内，只是生产资本家已经支付[28a]的劳动力价值的等价物，就是说，只是用新创造的价值来补偿预付的可变资本的价值，所以，这种价值的生产只是表现为再生产。因此，我把进行这种再生产的工作日部分称为必要劳动时间，把在这部分时间内耗费的劳动称为必要劳动。[29]这种劳动对工人来说所以必要，是因为它不以他的劳动的社会形式为转移。这种劳动对资本和资本世界来说所以必要，是因为工人的经常存在是它们的基础。","language":"中文","translation":false},{"id":"capital-8-14","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"劳动过程的第二段时间，工人超出必要劳动的界限做工的时间，虽然耗费工人的劳动，耗费劳动力，但并不为工人形成任何价值。这段时间形成剩余价值，剩余价值以从无生有的全部魅力引诱着资本家。我把工作日的这部分称为剩余劳动时间，把这段时间内耗费的劳动称为剩余劳动。把价值看作只是劳动时间的凝结，只是物化的劳动，这对于认识价值本身具有决定性的意义，同样，把剩余价值看作只是剩余劳动时间的凝结，只是物化的剩余劳动，这对于认识剩余价值也具有决定性的意义。使各种社会经济形态例如奴隶社会和雇佣劳动的社会区别开来的，只是从直接生产者身上，劳动者身上，榨取这种剩余劳动的形式。[30]","language":"中文","translation":false},{"id":"capital-8-15","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"因为可变资本的价值等于它所购买的劳动力的价值，因为这个劳动力的价值决定工作日的必要部分，而剩余价值又由工作日的剩余部分决定，所以从这里可以得出结论：剩余价值和可变资本之比等于剩余劳动和必要劳动之比，或者说，剩余价值率m/v=剩余劳动/必要劳动。这两个比率把同一种关系表示在不同的形式上：一种是物化劳动的形式，另一种是流动劳动的形式。","language":"中文","translation":false},{"id":"capital-8-16","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"因此，剩余价值率是劳动力受资本剥削的程度或工人受资本家剥削的程度的准确表现。[30a]","language":"中文","translation":false},{"id":"capital-8-17","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"按照我们的假定，产品的价值=410镑c+90镑v+90镑m，预付资本=500镑。因为剩余价值=90，预付资本=500，所以按照通常的计算方法，人们就说：剩余价值率(人们把它同利润率混为一谈)=18％。这样低的比率是会使凯里先生及其他调和论者感动的。但实际上剩余价值率不是=m/C或m/(c+v)，而是=m/v，也就是说，不是90/500，而是90/90=100％，比表面的剥削程度的5倍还要多。在这里，虽然我们不知道工作日的绝对量，不知道劳动过程的期间(日、周等等)，也不知道90镑可变资本同时推动的工人人数，但剩余价值率m/v由于可以转化为剩余劳动/必要劳动，从而精确地向我们表明工作日的两个组成部分的比率。这个比率为100％。因此，工人是半天为自己劳动，半天为资本家劳动。","language":"中文","translation":false},{"id":"capital-8-18","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"这样，计算剩余价值率的方法可以简述如下：我们把全部产品价值拿来，使其中只是再现的不变资本价值等于零。余下的价值额就是在商品形成过程中实际生产出来的唯一的价值产品。如果剩余价值已定，我们从这个价值产品中减去剩余价值，就可得出可变资本。如果可变资本已定，我们从这个价值产品中减去可变资本，就可得出剩余价值。如果这二者已定，那就只须进行最后的运算，计算剩余价值同可变资本的比率m/v。","language":"中文","translation":false},{"id":"capital-8-19","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"这种方法虽然很简单，但它所依据的看法对读者并不习惯。看来，举几个例子使读者熟悉一下是适当的。","language":"中文","translation":false},{"id":"capital-8-20","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"我们先举一家纺纱厂的例子，该厂拥有10000个走锭精纺纱锭，用美国棉花纺32支纱，每个纱锭一周生产1磅棉纱。飞花占6％。因此，每周有10600磅棉花被加工成10000磅棉纱和600磅飞花。1871年4月，这种棉花每磅花费7 3/4便士，因此10600磅棉花约为342镑。10000个纱锭(包括粗纺机和蒸汽机在内)，按每个花费1镑计算，共为10000镑。它们的损耗率是10％=1000镑，或每周20镑。厂房的租金是300镑，或每周6镑。煤每周11吨(1小时1马力用煤4磅，1周60小时100马力(按示功器)的用煤量，外加房屋取暖用煤)，每吨按8先令6便士计算，每周约花费4 1/2镑，煤气每周1镑，机油每周4 1/2镑，因此，以上所有的辅助材料每周共需10镑。总之，不变价值部分每周是378镑。工资每周是52镑。棉纱的价格是每磅12 1/4便士，或10000磅=510镑，因此剩余价值是510镑－430镑=80镑。我们使不变价值部分378镑=0，因为它在每周的价值形成中不起作用。这样，每周的价值产品132镑=52镑v+80镑m。因此，剩余价值率=80/52=153 11/13％。在10小时的平均工作日内，必要劳动=3 31/33小时，剩余劳动=6 2/33小时。[31]","language":"中文","translation":false},{"id":"capital-8-21","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"杰科布曾为1815年做过如下的计算[99]，他假定每夸特小麦的价格是80先令，每英亩平均收小麦22蒲式耳，所以从每英亩得到的是11镑。这个计算预先把不同的项目互相抵销了，因而很不完备，但对我们来说已经足够用了。","language":"中文","translation":false},{"id":"capital-8-22","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"种子(小麦)………1镑 9先令 什一税、地方税和国税……1镑1先令","language":"中文","translation":false},{"id":"capital-8-23","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"肥料 ………………2镑10先令 地租…………………………1镑8先令","language":"中文","translation":false},{"id":"capital-8-24","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"工资 ………………3镑10先令 租地农场主的利润和利息…1镑2先令","language":"中文","translation":false},{"id":"capital-8-25","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"总计 ………………7镑 9先令 总计…………………………3镑11先令","language":"中文","translation":false},{"id":"capital-8-26","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"在这里(我们始终假定产品的价格=它的价值)，剩余价值是分为利润、利息、什一税等等不同项目的。这些项目与我们无关。我们把它们加在一起，就得到剩余价值3镑11先令。我们把买种子和肥料的3镑19先令作为不变资本部分，使它等于零。预付的可变资本就是3镑10先令，代替它而被生产出来的新价值是3镑10先令+3镑11先令。这样，m/v=3镑11先令／3镑10先令，在100％以上。工人用他的工作日的一半以上生产剩余价值，这些剩余价值被各种人用各种借口瓜分掉。[31a]","language":"中文","translation":false},{"id":"capital-8-27","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"2、产品价值在产品相应部分上的表现","language":"中文","translation":false},{"id":"capital-8-28","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"现在我们再回头谈谈资本家是怎样把货币转化为资本的那个例子。他的纺纱工人的必要劳动是6小时，剩余劳动也是6小时，因此劳动力的剥削程度是100％。","language":"中文","translation":false},{"id":"capital-8-29","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"一个十二小时工作日的产品是20磅棉纱，价值30先令。这些棉纱价值至少有8/10(24先令)是由已消耗的生产资料的只是再现的价值(20磅棉花20先令，纱锭等等4先令)构成的，或者说，是由不变资本构成的。其余的2/10是在纺纱过程中产生的6先令新价值，其中一半补偿预付的劳动力的日价值或可变资本，另一半形成3先令剩余价值。可见，这20磅棉纱的总价值是依下列方式构成的：","language":"中文","translation":false},{"id":"capital-8-30","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"30先令棉纱价值=24先令c+3先令v+3先令m","language":"中文","translation":false},{"id":"capital-8-31","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"因为这个总价值表现在总产品20磅棉纱上，所以各个不同的价值要素也必定可以表现在产品的相应部分上。","language":"中文","translation":false},{"id":"capital-8-32","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"如果说30先令的棉纱价值存在于20磅棉纱中，那末，这个价值的8/10或其不变部分24先令，就存在于8/10的产品或16磅棉纱中。在这当中，13 1/3磅棉纱代表原料的价值，即纺掉的棉花的价值20先令，2 2/3磅棉纱代表已消耗的辅助材料和劳动资料纱锭等等的价值4先令。","language":"中文","translation":false},{"id":"capital-8-33","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"因此，13 1/3磅棉纱代表总产品20磅棉纱中纺掉的全部棉花，即总产品的原料，此外再也不代表别的东西。虽然13 1/3磅棉纱中只包含价值13 1/3先令的13 1/3磅棉花，但它们的追加价值6 2/3先令形成其余6 2/3磅棉纱中纺掉的棉花的等价物。结果好象其余的6 2/3磅棉纱被抽掉了棉花，而总产品中的全部棉花都塞到13 1/3磅棉纱中了。另一方面，在这13 1/3磅棉纱中，现在既不包含已消耗的辅助材料和劳动资料的价值的任何一个原子，也不包含纺纱过程中创造的新价值的任何一个原子。","language":"中文","translation":false},{"id":"capital-8-34","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"同样，剩下的包含不变资本余额(=4先令)的2 2/3磅棉纱，只是代表总产品20磅棉纱中所用掉的辅助材料和劳动资料的价值。","language":"中文","translation":false},{"id":"capital-8-35","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"因此，8/10的产品或16磅棉纱，虽然从物体来看，从作为使用价值棉纱来看，它们同产品的其余部分一样，也是纺纱劳动的创造物，但从我们在这里所讲的意义上来看，它们并不包含纺纱劳动，并不包含在纺纱过程本身中吸收的劳动。好象它们没有经过纺就变成了棉纱，好象它们的棉纱形态纯粹是骗人的。其实，当资本家按24先令把这些棉纱卖出，又用这24先令买回生产资料时就会表明，这16磅棉纱不过是化了装的棉花、纱锭、煤炭等等。","language":"中文","translation":false},{"id":"capital-8-36","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"反之，其余2/10的产品或4磅棉纱，现在只是代表12小时纺纱过程中生产的6先令新价值。其中包含的已用掉的原料和劳动资料的价值已经被剔除了，同前16磅棉纱合并在一起了。体现在20磅棉纱中的纺纱劳动都集中在2/10的产品上。好象这4磅棉纱是纺纱工人用空气纺成的，好象所用的棉花和纱锭是未经人类加工而天然存在的，因而不会把任何价值加到产品中去。","language":"中文","translation":false},{"id":"capital-8-37","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"这4磅棉纱包含一天纺纱过程所生产的全部价值产品，其中2磅棉纱只代表已用掉的劳动力的补偿价值，即3先令可变资本，其余2磅棉纱则只代表3先令剩余价值。","language":"中文","translation":false},{"id":"capital-8-38","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"因为纺纱工人的12个劳动小时物化在6先令中，所以在30先令的棉纱价值中就物化着60个劳动小时。它们存在于20磅棉纱内，其中8/10或16磅棉纱是纺纱过程以前的48个劳动小时的化身，也就是物化在棉纱的生产资料中的劳动的化身，而2/10或4磅棉纱则是纺纱过程本身中消耗的12个劳动小时的化身。","language":"中文","translation":false},{"id":"capital-8-39","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"前面我们已经看到，棉纱的价值等于棉纱生产中创造的新价值加棉纱的生产资料中原先已有的价值之和。现在我们又看到，产品价值在职能上或在概念上不同的组成部分，怎样能够表现在产品本身的相应部分上。","language":"中文","translation":false},{"id":"capital-8-40","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"我们把产品——生产过程的结果——分成几个量。一个量只代表生产资料中包含的劳动，或不变资本部分。另一个量只代表生产过程中加进的必要劳动，或可变资本部分。最后一个量的产品只代表同一过程中加进的剩余劳动，或剩余价值。这种划分很简单，但又很重要，这一点在以后把它应用到复杂的尚未解决的问题上时就可以看出。","language":"中文","translation":false},{"id":"capital-8-41","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"上面我们把总产品当作一个十二小时工作日的完成结果来考察。但是我们还可以伴随总产品的产生过程来看，仍然把各个部分产品当作职能上不同的各个产品部分。","language":"中文","translation":false},{"id":"capital-8-42","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"纺纱工人12小时生产20磅棉纱，因此1小时生产1 2/3磅，8小时生产13 1/3磅，也就是生产一个部分产品，其价值等于整个工作日纺掉的棉花的总价值。同样，往后的1小时36分生产的部分产品=2 2/3磅棉纱，因而代表12个劳动小时所用掉的劳动资料的价值。再往后的1小时12分，纺纱工人生产2磅棉纱=3先令，这部分产品价值等于他在6小时必要劳动中所创造的全部价值产品。最后的6/5小时，他又生产2磅棉纱，其价值等于他半天剩余劳动所生产的剩余价值。这是英国工厂主日常应用的计算方法，例如他会说，他在最初8小时或2/3的工作日中把棉花赚回来，如此等等。我们知道，这个公式是正确的，其实它就是上面的第一个公式，不过把现成产品的各部分同时并存的空间变成了它们依次出现的时间。但是，伴随这个公式也可能产生极野蛮的想法，特别是在那些实际上关心价值的增殖过程，但在理论上又有意曲解这一过程的头脑中会产生这种想法。例如这些人可能这样想：我们的纺纱工人在他的工作日的最初8小时是生产或补偿棉花的价值，往后的1小时36分是生产或补偿已消耗的劳动资料的价值，再往后的1小时12分是生产或补偿工资的价值，而只有那非常著名的“最后一小时”才是献给工厂主生产剩余价值的。这样一来，纺纱工人就得创造双重奇迹：一方面，他在用棉花、纱锭、蒸汽机、煤炭、机油等等纺纱的时候同时又生产这些东西；另一方面，他把一个有一定强度的工作日变成五个这样的工作日。就我们的例子来说，生产原料和劳动资料需要24/6=4个十二小时工作日，而把它们变成棉纱还需要1个十二小时工作日。掠夺的贪欲相信这种奇迹，并且总是找得到发空论的献媚者来证明这种奇迹，下面这个历史上著名的例子就说明了这一点。","language":"中文","translation":false},{"id":"capital-8-43","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"3、西尼耳的“最后一小时”","language":"中文","translation":false},{"id":"capital-8-44","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"1836年的一个早晨，以经济学识和文体优美著称的纳骚·威·西尼耳，这位在英国经济学家中相当于克劳伦的人，从牛津被召往曼彻斯特。他在牛津教授政治经济学，现在被召到这里来学习政治经济学。工厂主选中了他，要他充当斗士去反对新颁布的工厂法[100]和比工厂法更激进的争取十小时工作日运动。工厂主以通常具有的实际敏感看出，这位教授先生“还需要好好地最后雕琢一番”。因此他们写信叫他到曼彻斯特来。这位教授先生把他在曼彻斯特从工厂主那里学到的课业，加以润色，写成一本小册子：《关于工厂法对棉纺织业的影响的书信》(1837年伦敦版)。在这本小册子里，我们可以读到下面一段很有教益的话：","language":"中文","translation":false},{"id":"capital-8-45","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"“按照现行法律，凡雇用不满18岁的人的工厂，每天的劳动时间都不得超过11 1/2小时，就是说，一周的前5天每天劳动12小时，星期六劳动9小时。下面的分析〈！〉说明，这种工厂的全部纯利润是由最后一小时提供的。假定工厂主投资100000镑，其中用在厂房和机器上的是80000镑，用在原料和工资上的是20000镑。假定资本每年周转一次，总利润是15％，该厂全年的商品销售额应该是价值115000镑…… 一个工作日是23个1/2劳动小时，每个1/2劳动小时生产115000镑的5/115或1/23。在构成总额115000镑的23/23中，20/23即115000镑中的100000镑只是补偿资本，1/23即总利润〈！〉15000镑中的5000镑补偿工厂和机器的磨损。其余2/23即每天最后两个1/2小时才生产10％的纯利润。因此，在价格不变的情况下，如果工厂不是劳动11 1/2小时，而是可以劳动13小时，那末，只要增加大约2600镑流动资本，就能使纯利润增加一倍以上。反之，劳动时间每天缩短1小时，纯利润就会消失，缩短1 1/2小时，总利润也会消失。”[32] 这位教授先生竟把这种东西叫做“分析”！如果他真的相信工厂主的怨言，认为工人把一天的大部分时间用来生产从而再生产或补偿建筑物、机器、棉花、煤炭等等的价值，那末，任何分析都是多余的。他只须回答：诸位先生！如果你们把劳动时间从11 1/2小时减为10小时，在其他条件相同的情况下，每天棉花、机器等等的消耗也会减少1 1/2小时。因此，你们正好得失相当。以后你们的工人用来再生产或补偿预付资本价值的时间也将少1 1/2小时。如果西尼耳不相信工厂主所说的话，而是作为内行认为必须作一番分析，他首先就得请求工厂主先生们，在专门涉及纯利润同工作日长度的关系的问题上，不要把机器和厂房、原料和劳动混杂在一起，而把包含在厂房、机器、原料等等中的不变资本放在一边，把预付在工资上的资本放在另一边。在这之后，如果按照工厂主的计算，工人是用2/2个劳动小时或1小时再生产或补偿工资，那末这位分析家就应该接着说：","language":"中文","translation":false},{"id":"capital-8-46","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"根据你们的说法，工人是在倒数第二小时生产自己的工资，在最后一小时生产你们的剩余价值或纯利润。因为工人在同样的时间内生产同样的价值，所以倒数第二小时的产品和最后一小时的产品具有同样的价值。其次，工人只有耗费劳动，才生产价值，而他的劳动量是由他的劳动时间来计量的。按照你们的说法，工人的劳动时间是每天11 1/2小时。他用这11 1/2小时的一部分来生产或补偿自己的工资，用另一部分来生产你们的纯利润。在这个工作日内他再也没有做别的事情。既然按照你们的说法，工人的工资和他提供的剩余价值是同样大的价值，那末工人显然是在5 3/4小时内生产自己的工资，在其余5 3/4小时内生产你们的纯利润。其次，因为两小时棉纱产品的价值等于他的工资的价值额加上你们的纯利润，所以这一棉纱的价值必然等于11 1/2个劳动小时，也就是说，倒数第二小时的产品必然等于5 3/4个劳动小时，最后一小时的产品也必然等于5 3/4个劳动小时。现在我们到了棘手的地方了。请注意！倒数第二个劳动小时同最初一个劳动小时一样，都是一个通常的劳动小时。不多也不少。因此，纺纱工人怎么能在1个劳动小时内生产出代表5 3/4个劳动小时的棉纱价值呢？实际上，他并没有创造这个奇迹。他在1个劳动小时内生产的使用价值是一定量的棉纱。这些棉纱的价值等于5 3/4个劳动小时，其中4 3/4小时未经他的协助就已包含在1小时消耗的生产资料棉花、机器等等内，而4/4小时或1小时才是由他自己加进的。因为他的工资是在5 3/4小时内生产的，而1小时纺出的棉纱产品也包含5 3/4个劳动小时。所以，他5 3/4个劳动小时纺纱劳动的价值产品等于1小时纺纱劳动的产品价值，这并不是什么魔法妖术。如果你们以为他用了他的工作日的哪怕一个时间原子来再生产或“补偿”棉花、机器等等的价值，那你们就完全错了。正由于他的劳动把棉花和纱锭变成棉纱，正由于他纺纱，棉花和纱锭的价值才自行转移到棉纱上去。这种结果是靠他的劳动的质，而不是靠他的劳动的量造成的。当然，他1小时转移到棉纱上去的棉花等等的价值比1/2小时多，但这只是因为他1小时纺掉的棉花比1/2小时多。现在你们懂了吧，你们所谓工人在倒数第二小时生产他的工资的价值，在最后一小时生产纯利润，只不过是说，他的工作日的2小时(不管是最初2小时或是最后2小时)的棉纱产品，体现着11 1/2个劳动小时，正好等于他的整个工作日。所谓工人在前5 3/4小时生产他的工资，在后5 3/4小时生产你们的纯利润，又只不过是说，前5 3/4小时你们给了报酬，后5 3/4小时你们没有给报酬。这里我说劳动的报酬，而不说劳动力的报酬，是为了用你们的行话。诸位先生，现在请把你们付给报酬的劳动时间和你们没有付给报酬的劳动时间比较一下，你们就会发现，二者的比率是半天比半天，也就是100％。这当然是一个很高的百分比。毫无疑问，如果你们使你们的“人手”不是劳动11 1/2小时，而是劳动13小时，并且象你们会做的那样，把额外的1 1/2小时也归入纯粹的剩余劳动，那末剩余劳动就会从5 3/4小时增加到7 1/4小时，从而剩余价值率就会从100％增加到126 2/23％。如果你们期望，加上1 1/2小时就能使剩余价值率从100％增加到200％，甚至200％以上，即“增加一倍以上”，那未免太乐观了。另一方面——人的心是很奇怪的东西，特别是当人们把心放在钱袋里的时候——如果你们担心，工作日从11 1/2小时缩减为10 1/2小时会使你们的全部纯利润化为乌有，那又未免太悲观了。事情决不是这样的。假设其他一切条件相同，即使剩余劳动从5 3/4小时降为4 3/4小时，仍然会得出一个很好的剩余价值率，即82 14/23％。但是这个致命的“最后一小时”——你们为它编造的神话比锡利亚信徒[101]为世界末日编造的神话还要多——是“十足的胡说”。失掉这最后一小时，你们并不会丧失“纯利润”，而你们使用的童男童女也不会失去“灵魂的纯洁”。[32a]","language":"中文","translation":false},{"id":"capital-8-47","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"当你们的“最后一小时”真的敲响的时候，请你们想起牛津的这位教授吧。好了，但愿在一个更美好的世界里再同诸位相会。再见！[33]…… 西尼耳1836年发现的“最后一小时”这个信号，在1848年4月15日，又被经济学界的一位大官老爷詹姆斯·威尔逊在伦敦《经济学家》杂志上重新吹奏起来，以反对十小时工作日的法律。","language":"中文","translation":false},{"id":"capital-8-48","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"我们把代表剩余价值的那部分产品(在第2节举的例子中，是20磅棉纱的1/10或2磅棉纱)称为剩余产品。决定剩余价值率的，不是剩余价值同资本总额的比率，而是剩余价值同资本的可变部分的比率，同样，决定剩余产品的水平的，也不是剩余产品同总产品的其余部分的比率，而是剩余产品同代表必要劳动的那部分产品的比率。剩余价值的生产是资本主义生产的决定的目的，同样，富的程度不是由产品的绝对量来计量，而是由剩余产品的相对量来计量。[34]","language":"中文","translation":false},{"id":"capital-8-49","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"必要劳动和剩余劳动之和，工人生产他的劳动力的补偿价值和生产剩余价值的时间之和，构成他的劳动时间的绝对量——工作日。","language":"中文","translation":false},{"id":"capital-8-50","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[26a] “如果我们把所使用的固定资本的价值算作预付资本的一部分，我们就必须在年终时把这种资本的残余价值算作年收入的一部分。”（马尔萨斯《政治经济学原理》1836年伦敦第2版第269页）","language":"中文","translation":false},{"id":"capital-8-51","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[27] 第2版注：卢克莱修说，“无中不能生有”[96]，这是不言而喻的。“价值创造”是劳动力转化为劳动。而劳动力首先又是已转化为人的机体的自然物质。","language":"中文","translation":false},{"id":"capital-8-52","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[96]克莱修《物性论》第1卷第155—156行。——第242页。","language":"中文","translation":false},{"id":"capital-8-53","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[28] 这是仿照英国人的“利润率”、“利息率”等等说法。读者在第三卷中会着到，只要知道了剩余价值的各个规律，利润率是容易理解的。如果走相反的道路,则既不能了解前者，也不能了解后者。","language":"中文","translation":false},{"id":"capital-8-54","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[28a] ｛第3版注：在这里，作者沿用了流行的经济学用语。我们记得，在第137页（见本卷第197页。——编者注）已经说明，实际上不是资本家“预付”给工人，而是工人“预付”给资本家。——弗·恩·｝","language":"中文","translation":false},{"id":"capital-8-55","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[29] 我们在本书的前面一直是用“必要劳动时间”这个词泛指生产一般的商品的社会必要劳动时间。从现在起，我们也用这个词指生产特殊的商品即劳动力的必要劳动时间。用同一术语表示不同的意思是容易发生误会的，但这种现象在任何科学中都不能完全避免。例如，我们可以用高等数学和初等数学作一比较。","language":"中文","translation":false},{"id":"capital-8-56","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[30] 威廉·修昔的底斯·罗雪尔先生[97]以真正哥特谢德[98]（指傲慢与迟钝）的天才发现，在今天，剩余价值或剩余产品的形成，以及与此相联的积累，是由于资本家的“节俭”，为此，资本家“比如说，要求得到利息”，相反，“在极低的文化阶段……是强者迫使弱者节俭”。(《国民经济学原理》1858年第3版第82、78页)是节约劳动呢?还是节约尚不存在的剩余产品呢?罗雪尔之流除了确实无知之外，他们又是辩护士，不敢对价值和剩余价值作出诚实的分析，不敢得出可能是危险的违背警章的结论，就是这个原因，迫使罗雪尔之流把资本家用来辩护自己占有已存在的剩余价值时表面上多少能说得过去的理由，歪曲成剩余价值产生的原因。】","language":"中文","translation":false},{"id":"capital-8-57","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[97]昔的底斯是著名古希腊历史学家，马克思把威廉·罗雪尔讽剌地叫做威廉·修昔的底斯·罗雪尔，因为这个庸俗经济学家在他的著作《国民经济学原理》（《Die Grundlagen der Nationalokonomie》）第一版序言中，如马克思所说，“谦虚地宣称自己是政治经济学的修昔的底斯”。罗雪尔在引用修昔的底斯的著作时表示:“象古代历史学家一样，我也希望我的著作有益于……”等等。——第244页。","language":"中文","translation":false},{"id":"capital-8-58","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[98]德国作家和文学批评家哥特谢德。哥特谢德在文学上曾起一定的积极作用，但同时他又对新的文学潮流表现出异常的偏执。因此，他的名字成了文学上傲慢与迟钝的同义语。——第244页。","language":"中文","translation":false},{"id":"capital-8-59","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[30a] 第2版注：剩余价值率虽然是劳动力剥削程度的准确表现，但并不是剥削的绝对量的表现。例如，假定必要劳动=5小时，剩余劳动=5小时，则剥削程度=100％，这里剥削量是5小时。但是如果必要劳动=6小时，剩余劳动=6小时，剥削程度仍然是100％，剥削量却增加了20％，由5小时增加到6小时。","language":"中文","translation":false},{"id":"capital-8-60","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[31] 第2版注：第一版所举的1860年一家纺纱厂的例子，有些事实上的错误。本文列举的材料非常精确，它是曼彻斯特的一位工厂主向我提供的。这里要指出一点，英国的旧马力是根据汽缸的直径计算的，而新马力则是根据示功器指示的实际马力计算的。","language":"中文","translation":false},{"id":"capital-8-61","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[99] 威·杰科布《再论英国农业需要保护关税。给赛·惠特布雷德的一封信》1815年伦敦版第33页（W. Jacob. 《A Letter to S. Whitbread, being a Sequel to Considerations on the Protection Required by British Agriculture》. London, 1815, p.33）。——第246页。","language":"中文","translation":false},{"id":"capital-8-62","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[31a] 我们引用的这个计算材料只是作为例解。同时假定价格＝价值。我们在第三卷中会看到，即使拿平均价格来说，也不会这样简单地得出这个等式。","language":"中文","translation":false},{"id":"capital-8-63","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[100] 指1833年的工厂法。关于这个法律，见本卷第307—310页。——第251页。","language":"中文","translation":false},{"id":"capital-8-64","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[32] 西尼耳《关于工厂法对棉纺织业的影响的书信》1837年伦敦版第12、13页。我们且不谈那些和我们的目的无关的奇谈怪论，例如，说工厂主把补偿磨损的机器等等的金额，即补偿资本的一个组成部分的金额，算在总利润或纯利润里面。我们也不去谈这些数据是否正确。莱昂纳德·霍纳在《给西尼耳先生的一封信》(1837年伦敦版)中已指明，这些数据除了供所谓“分析”外没有什么别的价值。莱昂纳德·霍纳是1833年的工厂调查委员会的委员，在1859年前，一直是工厂视察员——其实是工厂检查官。他对英国工人阶级有不朽的贡献。他终生不仅同激怒的工厂主作斗争，而且同大臣作斗争，对于这些大臣来说，计算工厂主在下院的“票数”比计算“人手”在工厂内的劳动小时不知要重要多少倍。","language":"中文","translation":false},{"id":"capital-8-65","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"注〔32）的补充：且不谈西尼耳说的内容如何荒唐，他的叙述方法也是混乱的。其实，他想说的是，工广主使工人每天劳动11.5小时或23/2小时。正象一个工作日的情形—样，全年的劳动也是由11.5小时或23/2小时（乘以一年的工作日数）构成。按照这个假定，23/2个劳动小时生产的年产品为115 000镑；1/2个劳动小时生产的年产品为1/23×115 000镑；20/2个劳动小时生产20/23×115 000镑＝100 000镑，也就是说，它们只补偿预付资本。余下的3/2个劳动小时生产3/23×115 000镑＝15 000镑，即总利润。在这3/2个劳动小时中，1/2个劳动小时生产115 000镑＝5 000镑，即只补偿工厂和机器的损耗。最后的两个1/2劳动小时，即最后一个劳动小时，生产2/23×115 000镑＝10 000镑，即纯利润。在本文中，西尼耳把最后的2/23的产品转化为工作日本身的各个部分。","language":"中文","translation":false},{"id":"capital-8-66","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[101] 锡利亚信徒（来自希腊文“锡利亚斯”——一千）宣传关于耶稣再生和在地球上建立公正、普遍平等和幸福的“千年王国”的宗教神秘学说。锡利亚教义产生在奴隶制度解体时期，劳动人民由于遭受难以忍受的压迫和痛苦而从这种救世的狂想中寻找出路。这种信仰流传很广，后来经常重新出现在中世纪各种教派的学说中。——第255页。","language":"中文","translation":false},{"id":"capital-8-67","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[32a] 西尼耳证明，工厂主的纯利润、英国棉纺织业的存在和英国在世界市场上的地位都决定于“最后一个劳动小时”；而安德鲁·尤尔博士则又证明[102]，如果不是把童工和不满18岁的青工在工厂的温暖而纯洁的道德气氛里关上整整12小时，而是提早“一小时”把他们赶到冷酷无情、放荡不羁的外界去，他们就会因懒惰和邪恶而使灵魂不能得救。从1848年起，工厂视察员在半年一次的《报告》中一直拿“最后的”、“致命的一小时”来嘲弄工厂主。例如，豪威耳先生在1855年5月31日的工厂视察报告中说：“假如下面这种巧妙的计算＜他引证西尼耳＞是正确的，联合王国的所有棉纺织厂从1850年起就已经赔本了。”(《工厂视察员报告。截至1855年4月30日为止的半年》第19、20页)当1848年议会通过十小时工作日法案时，分散在多尔塞持和索美塞特两郡交界处的农村麻纺厂的工厂主们，强迫一些正规工人接受一份反对这项法案的请愿书，请愿书中有这样的话：“我们这些向你们请愿的人，作为父母，认为增加一小时闲荡的时间，结果只会使我们的孩子道德败坏，因为懒惰是万恶之源。”关于这一点，1848年10月31日的工厂视察员报告指出：“在这些敦厚善良的父母们的子女做工的麻纺厂里，空气中充满着原料的尘埃和碎屑，即使只在纺纱车间呆上10分钟，也会感到非常难受，因为眼睛、耳朵、鼻孔、嘴巴里会立刻塞满亚麻的碎屑，根本无法躲避，这不能不使你感到极度的痛苦。同时，由于机器飞速地转动，这种劳动本身需要全神贯注，需要一刻不停地运用技巧和动作，这些儿童在这样的空气里除了吃饭时间外整整劳动10小时，现在还要他们的父母说自己的子女‘懒惰’，这未免太残酷了……这些儿童的劳动时间比附近农村里雇工的劳动时间还要长……所谓‘懒惰和邪恶’这种无情的胡说必须斥之为十足的假仁假义和最无耻的伪善……大约在十二年以前，当有人在最高权威的批准下，十分自信地、郑重其事地公开宣布工厂主的全部‘纯利润’来源于‘最后一小时’劳动，从而工作日缩短一小时就会消灭纯利润的时候，一部分公众曾对这种自信程度感到惊讶；而现在，当这部分公众看到下面的事实时恐怕会不相信自己的眼睛了，这就是：关于充满善行的‘最后一小时’的原始发现，从那时以来已经大大完善，不仅包括‘利润’，而且还包括‘道德’；因此，如果儿童的劳动时间减为整整10小时，儿童的道德会和他们的雇主的纯利润一道化为乌有，因为二者都取决于这最后的致命的一小时。”(《工厂视察员报告。1848年10月31日》第101页)接着，这份工厂视察员报告举出了一些实例，说明这些工厂主先生的“道德”和“善行”，说明他们怎样施用阴谋、诡计、利诱、威胁、伪造等手段，迫使少数完全不会反抗的工人在这种请愿书上签名，然后把这种请愿书冒充整个产业部门和整个郡的请愿书提交议会。——无论是后来热心拥护工厂立法而值得赞扬的西尼耳本人，还是先后反对他的人，都不知道怎样说明这一“原始发现”的错误结论。这个事实最能说明所谓经济“科学”的现状。他们只是诉诸实际经验。而理由和原因仍然是秘密。","language":"中文","translation":false},{"id":"capital-8-68","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[102] 安·尤尔《工厂哲学：或论大不列颠工厂制度的科学、道德和商业的经济》1835年伦敦版第406页（A. Ure.《The Philosophy of Manufactures: or, An Exposition of the Scientific, Moral, and Commercial Economy of the Factory System of Great Britain》. London, 1835, p.406）。——第255页。","language":"中文","translation":false},{"id":"capital-8-69","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[33] 这位教授先生总算从这次曼彻斯特的旅行中得到了一些好处!在《关于工厂法的书信》中，全部纯利润，即“利润”、“利息”和甚至“更多的东西”取决于工人的一小时无酬劳动!而在一年前，西尼耳在他那本为牛律的大学生和有教养的庸人写的《政治经济学大纲》一书中，还反对李嘉图提出的价值由劳动时间决定的论点，“发现”利润来源于资本家的劳动，利息来源于资本家的禁欲主义。","language":"中文","translation":false},{"id":"capital-8-70","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"[34] “对于一个拥有20000镑资本，每年获得利润2000镑的人来说，只要他的利润不低于2000镑，不管他的资本是雇100个工人还是雇1000个工人，不管生产的商品是卖10000镑还是卖20000镑，都是一样的。一个国家的实际利益不也是这样吗?只要这个国家的实际纯收入，它的地租和利润不变，这个国家的人口有1000万还是有1200万，都是无关紧要的。”(李嘉图《政治经济学原理》1821年伦敦第3版第416页)早在李嘉图之前，有一位剩余产品的狂热的崇拜者阿瑟·杨格——他还是一个喜欢空谈而缺乏批判精神的作家，他的名声和他的功绩适成反比——就曾说过：“在一个现代王国里，如果象古罗马那样把整个省区的土地分给独立的小农耕种，即使他们耕种得很好，又有什么用呢?除了繁殖人口别无其他目的，而人口繁殖本身是最没有用处的”(阿瑟·杨格《政治算术》1774年伦敦版第47页)。","language":"中文","translation":false},{"id":"capital-8-71","author":"马克思","title":"资本论·第一卷","location":"第七章 剩余价值率","page":8,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/07.htm","text":"注（34）的补充：奇怪的是，“有一种强烈的倾向，把纯收入说成是对工人阶级有利的……但是很明显，它之所以有利，并不因为它是纯的”(托·霍普金斯《论地租》1828年伦敦版第126页)。","language":"中文","translation":false},{"id":"capital-9-1","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-9-2","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"2、对剩余劳动的贪欲。工厂主和领主","language":"中文","translation":false},{"id":"capital-9-3","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"3、在剥削上不受法律限制的英国工业部门","language":"中文","translation":false},{"id":"capital-9-4","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"4、日工和夜工。换班制度","language":"中文","translation":false},{"id":"capital-9-5","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"5、争取正常工作日的斗争。十四世纪中叶至十七世纪末叶关于延长工作日的强制性法律","language":"中文","translation":false},{"id":"capital-9-6","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"6、争取正常工作日的斗争。对劳动时间的强制的法律限制。1833—1864年英国的工厂立法","language":"中文","translation":false},{"id":"capital-9-7","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"7、争取正常工作日的斗争。英国工厂立法对其他国家的影响","language":"中文","translation":false},{"id":"capital-9-8","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"我们已经假定劳动力是按照它的价值买卖的。它的价值，和其他各种商品的价值一样，是由生产它所必需的劳动时间决定的。因此，如果工人平均一天生活资料的生产需要6小时，那末工人平均每天就要劳动6小时来逐日生产他的劳动力，或者说，再生产出他出卖劳动力得到的价值。这样，他的工作日的必要部分就是6小时，因而，在其他条件不变的情况下，是一个一定量。但是由此还不能确定工作日本身的量。","language":"中文","translation":false},{"id":"capital-9-9","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"我们用a——————b线表示必要劳动时间的持续或长度，假定是6小时。再假定劳动分别超过ab线1小时、3小时、6小时不等，我们就得到3条不同的线：","language":"中文","translation":false},{"id":"capital-9-10","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"a——————b—c a——————b———c","language":"中文","translation":false},{"id":"capital-9-11","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"a——————b——————c","language":"中文","translation":false},{"id":"capital-9-12","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"这3条线表示三种不同的工作日：七小时工作日、九小时工作日和十二小时工作日。延长线bc表示剩余劳动的长度。因为工作日等于ab+bc，即ac，所以它随着变量bc一同变化。因为ab是已定的，所以bc与ab之比总是可以计算出来的。它在工作日I中是1/6，在工作日II中是3/6，在工作日III中是6/6。又因为剩余劳动时间/必要劳动时间这个比率决定剩余价值率，所以已知这两段线之比，就可以知道剩余价值率。就上述三种不同的工作日来说，剩余价值率分别等于16 2/3％、50％和100％。相反，仅仅知道剩余价值率，却不能断定工作日的长度。例如，假定剩余价值率是100％，可是工作日可以是8小时、10小时、12小时等等。这个剩余价值率只表明工作日的两个组成部分即必要劳动和剩余劳动是同样大的，但并不表明每一部分各有多大。","language":"中文","translation":false},{"id":"capital-9-13","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"所以，工作日不是一个不变量，而是一个可变量。它的一部分固然是由不断再生产工人本身所必需的劳动时间决定的，但是它的总长度随着剩余劳动的长度或持续时间而变化。因此，工作日是可以确定的，但是它本身是不定的。[35]","language":"中文","translation":false},{"id":"capital-9-14","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"另一方面，工作日虽然不是固定的量，而是流动的量，但是它只能在一定的界限内变动。不过它的最低界限是无法确定的。当然，假定延长线bc或剩余劳动=0，我们就得出一个最低界限，即工人为维持自身而在一天当中必须从事必要劳动的那部分时间。但是在资本主义生产方式的基础上，必要劳动始终只能是工人的工作日的一部分，因此，工作日决不会缩短到这个最低限度。可是工作日有一个最高界限。它不能延长到超出某个一定的界限。这个最高界限取决于两点。第一是劳动力的身体界限。人在一个24小时的自然日内只能支出一定量的生命力。正象一匹马天天干活，每天也只能干8小时。这种力每天必须有一部分时间休息、睡觉，人还必须有一部分时间满足身体的其他需要，如吃饭、盥洗、穿衣等等。除了这种纯粹身体的界限之外，工作日的延长还碰到道德界限。工人必须有时间满足精神的和社会的需要，这种需要的范围和数量由一般的文化状况决定。因此，工作日是在身体界限和社会界限之内变动的。但是这两个界限都有极大的伸缩性，有极大的变动余地。例如我们看到有8小时、10小时、12小时、14小时、16小时、18小时的工作日，也就是有各种各样长度的工作日。","language":"中文","translation":false},{"id":"capital-9-15","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"资本家按照劳动力的日价值购买了劳动力。劳动力在一个工作日内的使用价值归资本家所有。因此，资本家有权要工人在一日之内为他做工。但什么是一个工作日呢？[36]当然比一个自然的生活日短。短多少呢？关于这个极限，即工作日的必要界限，资本家有他自己的看法。作为资本家，他只是人格化的资本。他的灵魂就是资本的灵魂。而资本只有一种生活本能，这就是增殖自身，获取剩余价值，用自己的不变部分即生产资料吮吸尽可能多的剩余劳动[37]。资本是死劳动，它象吸血鬼一样，只有吮吸活劳动才有生命，吮吸的活劳动越多，它的生命就越旺盛。工人劳动的时间就是资本家消费他所购买的劳动力的时间。[38]如果工人利用他的可供支配的时间来为自己做事，那他就是偷窃了资本家。[39]","language":"中文","translation":false},{"id":"capital-9-16","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"可见，资本家是以商品交换规律作根据的。他和任何别的买者一样，想从他的商品的使用价值中取得尽量多的利益。但是，突然传来了在疾风怒涛般的生产过程中一直沉默的工人的声音：","language":"中文","translation":false},{"id":"capital-9-17","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"我卖给你的商品和其他的普通商品不同，它的使用可以创造价值，而且创造的价值比它本身的价值大。正是因为这个缘故你才购买它。在你是资本价值的增殖，在我则是劳动力的过多的支出。你和我在市场上只知道一个规律，即商品交换的规律。商品不归卖出商品的卖者消费，而归买进商品的买者消费。因此，我一天的劳动力归你使用。但是我必须依靠每天出卖劳动力的价格来逐日再生产劳动力，以便能够重新出卖劳动力。如果撇开由于年老等等原因造成的自然损耗不说，我明天得象今天一样，在体力、健康和精神的正常状态下来劳动。你经常向我宣讲“节俭”和“节制”的福音。好！我愿意象个有理智的、节俭的主人一样，爱惜我唯一的财产——劳动力，不让它有任何荒唐的浪费。我每天只想在它的正常耐力和健康发展所容许的限度内使用它，使它运动，变为劳动。你无限制地延长工作日，就能在一天内使用掉我三天还恢复不过来的劳动力。你在劳动上这样赚得的，正是我在劳动实体上损失的。使用我的劳动力和劫掠我的劳动力完全是两回事。假定在劳动量适当的情况下一个中常工人平均能活30年，那你每天支付给我的劳动力的价值就应当是它的总价值的1/(365×30)或1/10950。但是如果你要在10年内就消费尽我的劳动力，可是每天支付给我的仍然是我的劳动力总价值的1/10950，而不是1/3650，那就只支付了我的劳动力日价值的1/3，因而每天就偷走了我的商品价值的2/3。你使用三天的劳动力，只付给我一天的代价。这是违反我们的契约和商品交换规律的。因此，我要求正常长度的工作日，我这样要求，并不是向你求情，因为在金钱问题上是没有情面可讲的。你可能是一个模范公民，也许还是禁止虐待动物协会的会员，甚至还负有德高望重的名声，但是在你我碰面时你所代表的那个东西的里面是没有心脏跳动的。如果那里面仿佛有什么东西在跳动的话，那不过是我自己的心。我要求正常的工作日，因为我和任何别的卖者一样，要求得到我的商品的价值。[40]","language":"中文","translation":false},{"id":"capital-9-18","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"我们看到，撇开伸缩性很大的界限不说，商品交换的性质本身没有给工作日规定任何界限，因而没有给剩余劳动规定任何界限。资本家要坚持他作为买者的权利，他尽量延长工作日，如果可能，就把一个工作日变成两个工作日。可是另一方面，这个已经卖出的商品的特殊性质给它的买者规定了一个消费的界限，并且工人也要坚持他作为卖者的权利，他要求把工作日限制在一定的正常量内。于是这里出现了二律背反，权利同权利相对抗，而这两种权利都同样是商品交换规律所承认的。在平等的权利之间，力量就起决定作用。所以，在资本主义生产的历史上，工作日的正常化过程表现为规定工作日界限的斗争，这是全体资本家即资本家阶级和全体工人即工人阶级之间的斗争。","language":"中文","translation":false},{"id":"capital-9-19","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"2、对剩余劳动的贪欲。工厂主和领主","language":"中文","translation":false},{"id":"capital-9-20","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"资本并没有发明剩余劳动。凡是社会上一部分人享有生产资料垄断权的地方，劳动者，无论是自由的或不自由的，都必须在维持自身生活所必需的劳动时间以外，追加超额的劳动时间来为生产资料的所有者生产生活资料[41]，不论这些所有者是雅典的贵族，伊特剌斯坎的僧侣，罗马的市民，诺曼的男爵，美国的奴隶主，瓦拉几亚的领主，现代的地主，还是资本家[42]。但是很明显，如果在一个社会经济形态中占优势的不是产品的交换价值，而是产品的使用价值，剩余劳动就受到或大或小的需求范围的限制，而生产本身的性质就不会造成对剩余劳动的无限制的需求。因此，在古代，只有在谋取具有独立的货币形式的交换价值的地方，即在金银的生产上，才有骇人听闻的过度劳动。在那里，累死人的强迫劳动是过度劳动的公开形式。这只要读一读西西里的狄奥多洛斯的记载就可以知道[43]。但是在古代，这只是一种例外。不过，那些还在奴隶劳动或徭役劳动等较低级形式上从事生产的民族，一旦卷入资本主义生产方式所统治的世界市场，而这个市场又使它们的产品的外销成为首要利益，那就会在奴隶制、农奴制等等野蛮灾祸之上，再加上一层过度劳动的文明灾祸。因此，在美国南部各州，当生产的目的主要是直接满足本地需要时，黑人劳动还带有一种温和的家长制的性质。但是随着棉花出口变成这些州的切身利益，黑人所从事的有时只要七年就把生命耗尽的过度劳动，就成为事事都要加以盘算的那个制度的一个因素。问题已经不再是从黑人身上榨取一定量的有用产品，现在的问题是要生产剩余价值本身了。徭役劳动，例如多瑙河各公国的徭役劳动，也有类似的情形。","language":"中文","translation":false},{"id":"capital-9-21","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"把多瑙河各公国对剩余劳动的贪欲和英国工厂对剩余劳动的贪欲比较一下是很有意义的，因为徭役制度下的剩余劳动具有独立的、可以感觉得到的形式。","language":"中文","translation":false},{"id":"capital-9-22","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"假定工作日由6小时必要劳动和6小时剩余劳动组成。在这种情况下，自由工人每周为资本家提供6×6小时即36小时的剩余劳动。这和他每周为自己劳动3天，又为资本家白白地劳动3天，完全一样。但是这种情形是觉察不出来的。剩余劳动和必要劳动融合在一起了。因此，我也可以用另外的说法来表示同样的关系，例如说工人在每分钟内为自己劳动30秒，为资本家劳动30秒，等等。而徭役劳动就不是这样。例如瓦拉几亚的农民为维持自身生活所完成的必要劳动和他为领主所完成的剩余劳动在空间上是分开的。他在自己的地里完成必要劳动，在主人的领地里完成剩余劳动。所以，这两部分劳动时间是各自独立的。在徭役劳动形式中，剩余劳动和必要劳动截然分开。这种表现形式上的差别，显然丝毫不会改变剩余劳动和必要劳动之间的量的比率。每周三天的剩余劳动，无论是叫做徭役劳动还是叫做雇佣劳动，都是劳动者自己的无代价的三天劳动。不过资本家对剩余劳动的贪欲表现为渴望无限度地延长工作日，而领主的贪欲则较简单地表现为直接追求徭役的天数。[44]","language":"中文","translation":false},{"id":"capital-9-23","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在多瑙河各公国，徭役劳动是同实物地租和其他农奴制义务结合在一起的，但徭役劳动是交纳给统治阶级的最主要的贡赋。凡是存在这种情形的地方，徭役劳动很少是由农奴制产生的，相反，农奴制倒多半是由徭役劳动产生的[44a]。罗马尼亚各州的情形就是这样。那里原来的生产方式是建立在公社所有制的基础上的，但这种公社所有制不同于斯拉夫的形式，也完全不同于印度的形式。一部分土地是自由的私田，由公社成员各自耕种，另一部分土地是公田，由公社成员共同耕种。这种共同劳动的产品，一部分作为储备金用于防灾备荒和应付其他意外情况，一部分作为国家储备用于战争和宗教方面的开支以及其他的公用开支。久而久之，军队的和宗教的头面人物侵占了公社的地产，从而也就侵占了花在公田上的劳动。自由农民在公田上的劳动变成了为公田掠夺者而进行的徭役劳动。于是农奴制关系随着发展起来，但这只是在事实上，还没有反映到法律上，直到后来，要解放全世界的俄罗斯才借口废除农奴制而把这种农奴制用法律固定下来。1831年俄国将军基谢廖夫颁布的徭役劳动法，当然是由领主们口授的。俄罗斯由此一举征服了多瑙河各公国的显贵，并博得了整个欧洲的自由派白痴们的喝采。","language":"中文","translation":false},{"id":"capital-9-24","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"按照这个称为“组织规程”【104】的徭役劳动法，瓦拉几亚的每个农民除交纳详细规定的大量实物贡赋之外，还必须为所谓地主完成：1、十二个一般工作日；2、一个田间工作日；3、一个搬运木材的工作日。一年共14日。不过，由于制定该法令的人谙熟政治经济学，所以规定的不是通常意义的工作日，而是生产某种平均日产品所必需的工作日，而这个平均日产品又规定得非常狡猾，连塞克洛普在24小时之内也完成不了。因此，“组织规程”本身以道地的俄罗斯式讽刺的露骨语言解释说，12个工作日应该理解为36日体力劳动的产品，一个田间工作日应理解为3日，一个搬运木材的工作日也应理解为3日。合计是42日徭役。此外还要加上所谓《Jobagie》，就是当地主在生产上有特殊需要时所服的劳役。每个村每年要按照人口的多寡出一定人力为领主服这种徭役。每个瓦拉几亚的农民估计要担负14日这种额外徭役劳动。这样，已经规定的徭役劳动每年就有56个工作日。在瓦拉几亚，由于气候不好，每年只有210日可以从事农活。其中有40日是星期天和节日，平均还有30日坏天气，加起来就去掉了70日。剩下的只有140个工作日。徭役劳动同必要劳动之比是56/48或66 2/3％，这表明剩余价值率比英国农业工人或工厂工人劳动的剩余价值率要小得多。但这只是法定的徭役劳动。“组织规程”比英国的工厂立法有更多的“自由主义”精神，它有意让人更容易去钻空子。它除了把12日变成56日之外，又把56日徭役中每日的名义上的劳动额规定得非拖到以后的日子去完成不可。例如一日的锄草定额，特别是玉米地的锄草定额，实际上要加倍的时间才能完成。某些农活的法定的一日劳动定额，甚至可以解释成所谓这一日是从五月开始一直到十月为止。对于莫尔达维亚，规定更加苛刻。有一个为胜利所陶醉的领主喊道：","language":"中文","translation":false},{"id":"capital-9-25","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“‘组织规程’规定的12日徭役，等于一年365日！”[45]","language":"中文","translation":false},{"id":"capital-9-26","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"如果说，通过一项项条文使对剩余劳动的贪欲合法化的多瑙河各公国“组织规程”是这种贪欲的积极表现，那末，英国的工厂法是这种贪欲的消极表现。英国的工厂法是通过国家，而且是通过资本家和地主统治的国家所实行的对工作日的强制的限制，来节制资本无限度地榨取劳动力的渴望。即使撇开一天比一天更带威胁性地高涨着的工人运动不说，也有必要把工厂劳动限制一下，这正象有必要用海鸟粪对英国田地施肥一样。同是盲目的掠夺欲，在后一种情况下使地力枯竭，而在前一种情况下使国家的生命力遭到根本的摧残。英国的周期复发的流行病和德法两国士兵身长的降低，都同样明白地说明了这个问题。[46]","language":"中文","translation":false},{"id":"capital-9-27","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1850年制定的现行（1867年）工厂法规定，一周平均每个工作日为10小时，即一周的前5天为12小时，从早晨6时至晚上6时，其中包括法定的半小时早饭时间和一小时午饭时间，做工时间净剩10 1/2小时；星期六为8小时，从早晨6时至午后2时，其中有半小时早饭时间。每周净剩60小时，前5天为10 1/2小时，星期六为7 1/2小时[47]。为了监督法律的执行，设置了专门的工厂视察员，直属内务部，他们的报告由议会每半年公布一次。这些报告不断地提供关于资本家对剩余劳动贪欲的官方统计材料。","language":"中文","translation":false},{"id":"capital-9-28","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"让我们听一听这些工厂视察员的报告吧。[48]","language":"中文","translation":false},{"id":"capital-9-29","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“狡猾的工厂主在早晨6点前1刻就开工，有时还要早些，有时稍晚些，晚上6点过1刻才收工，有时稍早些，有时还要晚些。他把名义上规定的半小时早饭时间前后各侵占5分钟，一小时午饭时间前后各侵占10分钟。星期六下午到2点过1刻才收工，有时稍早些，有时还要晚些。这样他就赚到：星期一至星期五：早6时前15分钟、晚6时后15分钟、早饭10分钟、午饭20分钟，即60分钟/日，5日共计：300分钟；星期六：早6时前15分钟、早饭10分钟、下午2时后15分钟；1周共计：340分钟。","language":"中文","translation":false},{"id":"capital-9-30","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"就是说，每周多出来5小时40分钟，每年以50个劳动周计算（除掉2周作为节日或因故停工），共为27个工作日。”[49]","language":"中文","translation":false},{"id":"capital-9-31","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“如果每个工作日比标准时间延长5分钟，一年就等于2 1/2个生产日。”[50]“这里捞一点时间，那里捞一点时间，一天多出一小时，一年12个月就变成13个月了。”[51] 在危机时期，生产中断，“开工不足”，每周只开工几天。这当然不影响延长工作日的欲望。营业越不振，就越要从已有的营业中取得更大的利润。开工的时间越少，就越要使剩余劳动时间延长。工厂视察员关于1857—1858年的危机时期报告说：","language":"中文","translation":false},{"id":"capital-9-32","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“在生意这样不景气的时候还有过度劳动现象，人们也许会认为是矛盾的；可是生意不景气却刺激那些无所顾忌的人去犯法。他们这样就保证自己能取得额外利润……”莱昂纳德·霍纳说：“我的管区有122家工厂倒闭，143家停工，所有其余的工厂也都开工不足，但是就在这个时期，超过法定时间的过度劳动仍然存在。”[52]豪威耳先生说：“虽然大多数工厂由于营业不振只开半工，但我和以前一样仍旧接到同样多的控告，说由于侵占法定的吃饭时间和休息时间，工人每天被夺去半小时或3刻钟。”[53]","language":"中文","translation":false},{"id":"capital-9-33","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在1861年至1865年的可怕的棉业危机时期，也发生了同样的现象，不过规模比较小。[54]","language":"中文","translation":false},{"id":"capital-9-34","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“如果我们在吃饭时间或者在其他违法时间查到有的工人在做工，有人有时就出来辩解，说工人怎样也不愿意离开工厂，要他们停止工作〈擦洗机器等等〉，非得使用强制办法不可，特别在星期六下午更是如此。其实，在机器停止转动以后仍然有‘人手’留在工厂里，那只是因为在早晨6时至晚上6时的法定劳动时间内没有拨出时间让他们干这类事情。”[55]","language":"中文","translation":false},{"id":"capital-9-35","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“看来，靠超过法定时间的过度劳动获得额外利润，对许多工厂主来说是一个难于抗拒的巨大诱惑。他们指望不被发觉，而且心中盘算，即使被发觉了，拿出一笔小小的罚款和诉讼费，也仍然有利可图。”[56]“如果额外时间是在一天之内零敲碎打地偷窃来的，那末，视察员要想找出违法的证据就很困难了。”[57]","language":"中文","translation":false},{"id":"capital-9-36","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"资本“零敲碎打地偷窃”工人吃饭时间和休息时间的这种行为，又被工厂视察员叫做“偷占几分钟时间”[58]，“夺走几分钟时间”[59]，工人中间流行的术语，叫做“啃吃饭时间”。[60]","language":"中文","translation":false},{"id":"capital-9-37","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"我们看到，在这种气氛中，剩余价值由剩余劳动形成已经不是什么秘密。","language":"中文","translation":false},{"id":"capital-9-38","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“有一位很可敬的工厂主对我说：如果你允许我每天只让工人多干10分钟的话，那你一年就把1000镑放进了我的口袋。”[61]“时间的原子就是利润的要素。”[62]","language":"中文","translation":false},{"id":"capital-9-39","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在这一点上，最能说明问题的是，人们把那些全天劳动的工人叫做“全日工”，把13岁以下的只准劳动6小时的童工叫做“半日工”[63]。在这里，工人不过是人格化的劳动时间。一切个人之间的区别都化成“全日工”和“半日工”的区别了。","language":"中文","translation":false},{"id":"capital-9-40","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"3、在剥削上不受法律限制的英国工业部门","language":"中文","translation":false},{"id":"capital-9-41","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"以上我们考察了一些部门中竭力延长工作日的情况，考察了对剩余劳动的狼一般的贪欲，在这些部门中，无限度的压榨，正如一个英国资产阶级经济学家所说的，比西班牙人对美洲红种人的暴虐有过之而无不及[64]，因此，资本终于受到法律的约束。现在我们来看看另外一些生产部门，在那里，直到今天，或者直到不久以前，还在毫无拘束地压榨劳动力。","language":"中文","translation":false},{"id":"capital-9-42","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“1860年1月14日，郡治安法官布罗顿先生在诺定昂市会议厅主持的一次集会上说，从事花边生产的那部分城市居民过着极其贫穷痛苦的生活，其困苦程度是文明世界的其他地方所没有见过的…… 9岁到10岁的孩子，在大清早2、3、4点钟就从肮脏的床上被拉起来，为了勉强糊口，不得不一直干到夜里10、11、12点钟。他们四肢瘦弱，身躯萎缩，神态呆痴，麻木得象石头人一样，使人看一眼都感到不寒而栗。马勒特先生和别的工厂主起来抗议讨论这类事情，是一点也不奇怪的…… 这种制度，正象蒙塔古·瓦尔皮牧师所描写的那样，是无拘无束的奴隶制，是社会的、肉体的、道德的和智力的奴隶制…… 如果一个城市竟举行公众集会，请求把男子每天的劳动时间限制为18小时，那我们将作何感想呢！…… 我们抨击弗吉尼亚和加罗林的种植园主。然而，他们买卖黑奴、鞭笞黑奴、贩卖人肉的行为，比起为资本家的利益而制造面纱和硬领的过程中发生的那种慢性杀人的暴行，难道更可恶吗？”[65]","language":"中文","translation":false},{"id":"capital-9-43","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"斯泰福郡的陶器业，在最近22年来，曾三度成为议会调查的对象。调查的结果，第一次见斯克里文先生1841年向童工调查委员会提出的报告，第二次见奉枢密院【106】医官命令公布的格林豪医生1860年的报告（《公共卫生。第3号报告》第1部分第102—103页），最后一次见朗格先生1863年的报告，载于1863年6月13日的《童工调查委员会。第1号报告》。在这里，我只要从1860年和1863年的报告中摘录一些受剥削的儿童本人的证词就够了。根据儿童的情况也就可以推知成年人的情况，特别是少女和妇女的情况。同这一工业部门比较起来，棉纺织业之类的部门还算是很愉快很卫生的职业呢。[66]","language":"中文","translation":false},{"id":"capital-9-44","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"威廉·伍德，9岁，“从7岁零10个月就开始做工”。一直是“运模子”（把已经入模的坯子搬到干燥房，再把空模搬回来）。他每周天天早晨6点上工，晚上9点左右下工。“我每周天天都干到晚上9点钟。例如最近七八个星期都是这样。”就是说，一个7岁的孩子竟劳动15小时！詹·默里，12岁，他说：","language":"中文","translation":false},{"id":"capital-9-45","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我干的是运模子和转辘轳。我早晨6点钟上工，有时4点钟上工。昨天，我干了一整夜，一直干到今天早晨6点钟。我从前天夜里起就没有上过床。除我以外，还有八九个孩子昨天都干了一整夜。除了一个没有来，其余的孩子今天早晨又都上工了。我一个星期挣3先令6便士。我整整干了一夜，也没多得到一个钱。上星期我就整整干了两夜。”","language":"中文","translation":false},{"id":"capital-9-46","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我不总是能够得到十足一小时的吃饭时间，而往往只有半小时，每星期四、星期五、星期六都是这样。”[67]","language":"中文","translation":false},{"id":"capital-9-47","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"格林豪医生指出，在特伦特河畔的斯托克和在沃尔斯坦登这两个陶业区，人的寿命特别短。20岁以上的男子从事陶业生产的，在斯托克区虽然只占36.6％，在沃尔斯坦登只占30.4％，但是在这类年龄的男子死亡人数中，死于胸腔病的陶工在斯托克区占一半以上，在沃尔斯坦登区约占2/5。在亨莱行医的布思罗伊德医生说：","language":"中文","translation":false},{"id":"capital-9-48","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“陶工一代比一代矮，一代比一代弱。”","language":"中文","translation":false},{"id":"capital-9-49","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"另一个医生麦克贝恩先生也说：","language":"中文","translation":false},{"id":"capital-9-50","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我在陶工中间行医25年了，我发觉这个阶级在身长和体重方面显著退化。”","language":"中文","translation":false},{"id":"capital-9-51","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"以上这些证词是从格林豪医生1860年的报告[68]中摘录的。","language":"中文","translation":false},{"id":"capital-9-52","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"下面我们从几个调查委员1863年的报告中摘录几段。北斯泰福郡医院主任医生约·特·阿尔莱兹说：","language":"中文","translation":false},{"id":"capital-9-53","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“陶工作为一个阶级，不分男女……代表着身体上和道德上退化的人口。他们一般都是身材矮小，发育不良，而且胸部往往是畸型的。他们未老先衰，寿命短促，迟钝而又贫血；他们常患消化不良症、肝脏病、肾脏病和风湿症，表明体质极为虚弱。但他们最常患的是胸腔病：肺炎、肺结核、支气管炎和哮喘病。有一种哮喘病是陶工特有的，通称陶工哮喘病或陶工肺结核。还有侵及腺、骨骼和身体其他部分的瘰疬病，患这种病的陶工占三分之二以上。只是由于有新的人口从邻近的乡村地区补充进来，由于同较为健康的人结婚，这个地区的人口才没有发生更严重的退化。”","language":"中文","translation":false},{"id":"capital-9-54","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"不久前还是该医院外科医生的查理·帕森斯先生在给调查委员朗格的信中写道：","language":"中文","translation":false},{"id":"capital-9-55","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我所能说的只是我个人的观察，并没有什么统计材料作根据。但是我可以毫不犹豫地说，每当我看到这些为满足父母和雇主的贪心而牺牲了健康的不幸孩子们的时候，激愤的心情怎样也平静不下来。”","language":"中文","translation":false},{"id":"capital-9-56","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"他列举陶工患病的种种原因，最后指出，最重要的原因是“劳动时间过长”。调查委员会的报告希望：","language":"中文","translation":false},{"id":"capital-9-57","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“一个在全世界人们的心目中占有如此卓越地位的行业，不能再容忍这种可耻的现象：它依靠工人的劳动和技巧，取得了光辉的成就，但伴随而来的是，工人身体退化，遭受种种折磨，早期死亡。”[69]","language":"中文","translation":false},{"id":"capital-9-58","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"这里所说的英格兰陶器业的情况，也适用于苏格兰的陶器业。[70]","language":"中文","translation":false},{"id":"capital-9-59","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"火柴制造业是从1833年发明用木梗涂磷的办法之后出现的。自1845年起，它在英国迅速地发展起来，并由伦敦人口稠密的地区传到曼彻斯特、北明翰、利物浦、布利斯托尔、诺里奇、新堡、格拉斯哥等地，它同时也使牙关锁闭症蔓延到各地。维也纳的一位医生早在1845年就发现这种病是火柴工人的职业病。工人中有一半是13岁以下的儿童和不满18岁的少年。谁都知道，这种制造业有害健康，令人生厌，所以只有工人阶级中那些最不幸的人，饿得半死的寡妇等等，才肯把“衣衫褴褛、饿得半死、无人照管、未受教育的孩子”[71]送去干这种活。在委员怀特1863年询问过的证人当中，有270人不满18岁，40人不满10岁，10人只有8岁，5人只有6岁。工作日从12到14或15小时不等，此外还有夜间劳动，吃饭没有固定时间，而且多半是在充满磷毒的工作室里吃饭。如果但丁还在，他一定会发现，他所想象的最残酷的地狱也赶不上这种制造业中的情景。","language":"中文","translation":false},{"id":"capital-9-60","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在壁纸工厂中，粗糙的壁纸用机器印刷，精致的壁纸用手工印刷。生产的旺季是从十月初到第二年四月底。在这段时期内，劳动往往从早晨6时一直持续到晚上10时，甚至到深夜，中间几乎没有休息。","language":"中文","translation":false},{"id":"capital-9-61","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“去年〈1862年〉冬天，19个女孩子中，有6个因为劳动过度，害了病，不能上工。为了不让她们打瞌睡，我必须对她们大声喊叫。”伍·达菲说：“孩子们往往疲倦得睁不开眼睛，其实，我们自己往往也是勉强地支撑着。”詹·莱特伯恩说：“我13岁…… 去年冬天我们干到晚上9点，前年冬天干到晚上10点。去年冬天我的脚有伤，差不多每天晚上都疼得哭起来。”格·阿蒲斯登说：“我这个孩子7岁的时候，我就常常背着他在雪地里上下工，他常常要做16个钟头的工！…… 当他在机器旁干活的时候，我往往得跪下来喂他饭，因为他不能离开机器，也不能把机器停下来。”曼彻斯特一家工厂的股东兼经理斯密说：“我们〈他是指那些为“我们”做工的“人手”〉一直做工，中间不停下来吃饭，所以一天10 1/2小时的劳动到下午4点半就干完了，以后的时间都是额外时间。[72]〈难道这位斯密先生在这10 1/2小时内也不吃一顿饭吗？〉我们〈又是克里斯平【108】〉很少在晚上6点以前停工〈他是指停止消费“我们的”劳动力这些机器〉，所以我们实际上整年都有额外时间…… 在过去18个月当中，无论孩子或成年人〈152个儿童和18岁以下的少年，140个成年人〉平均每周至少要干7天零5小时即78 1/2小时。在今年〈1863年〉5月2日以前的6周内，平均时间更长了，每周达8天即84小时！”","language":"中文","translation":false},{"id":"capital-9-62","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"还是这位如此爱用君主口吻以“我们”自称的斯密先生，微笑着补充说：“机器劳动是轻松的。”采用手工印刷的工厂主却说：“手工劳动比机器劳动要合乎卫生。”但是工厂主先生们全都愤愤不平地反对“至少在吃饭时间使机器停下来”的建议。巴勒区（伦敦）一家壁纸厂的经理奥特利先生说道：","language":"中文","translation":false},{"id":"capital-9-63","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“要是法律准许的劳动时间是从早晨6点到晚上9点，对我们〈！〉倒很合适，可是工厂法规定的时间是从早晨6点到晚上6点，这对我们〈！〉可不合适…… 在午饭时间我们的机器总是停下来〈何等宽宏大量！〉。这样做在纸张和颜料方面不会造成大不了的损失。”接着他满怀同情地补充说：“但是，我可以理解，因此而造成的损失是人们所不喜欢的。”","language":"中文","translation":false},{"id":"capital-9-64","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"委员会的报告坦率地认为，某些“大公司”担心丧失时间，即担心丧失占有别人劳动的时间，并从而“丧失利润”。这不能成为“充足的理由”，让13岁以下的儿童和不满18岁的少年在长达12—16小时的时间内“丧失”吃午饭的时间，或者象给蒸汽机添煤加水，给羊毛加肥皂水，给机轮上油等等那样，把午饭仅仅当作劳动资料的辅助材料在生产过程进行中加给他们。[73]","language":"中文","translation":false},{"id":"capital-9-65","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在英国，没有一个工业部门象面包业（刚刚兴起的机制面包业不算在内）那样，直到今天还保持着如此古老的、只有从罗马帝国时代的诗人作品里才可以看到的纪元前的生产方式。不过，前面已经说过，资本起初并不关心它所征服的劳动过程的技术性质。起初，它是遇到什么样的劳动过程就采用什么样的劳动过程。","language":"中文","translation":false},{"id":"capital-9-66","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"面包掺假的情况，令人难以置信，尤其在伦敦更为厉害。这种现象，最先是由下院“食物掺假”调查委员会（1855—1856年）和哈塞耳医生《揭穿了的掺假行为》一书揭发出来的[74]。揭发的结果是1860年8月6日颁布了“防止饮食品掺假”法，这是一项无效的法律，因为它对每个企图靠买卖假货“赚正当钱”的自由贸易者当然是极端宽容的[75]。委员会本身也相当坦率地承认，自由贸易实质上是假货贸易，或者用英国人的俏皮说法，是“诡辩品”贸易。事实上，这种“诡辩”比普罗塔哥拉更会颠倒黑白，比埃利亚派【109】更能当面证明一切真实都只不过是假象。[76]","language":"中文","translation":false},{"id":"capital-9-67","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"不管怎样，委员会把公众的目光引向了他们“每日的面包”，从而引向了面包业。与此同时，伦敦面包工人在群众大会上和在向议会的请愿中，发出了反对过度劳动等等的呼声。这种呼声如此急迫，以致当局把我们上面屡次提到的1863年委员会的委员休·西·特里门希尔先生，任命为皇家调查专员。他的报告[77]和列举的证词激动了公众，不过不是激动了公众的心，而是激动了公众的胃。熟读圣经的英国人虽然清楚地知道，一个人除非由于上帝的恩赐而成为资本家、大地主或领干薪者，否则必须汗流满面来换取面包，但是他不知道，他每天吃的面包中含有一定量的人汗，并且混杂着脓血、蜘蛛网、死蟑螂和发霉的德国酵母，更不用提明矾、砂粒以及其他可口的矿物质了。因此，不管“贸易自由”多么神圣，这个一向“自由”的面包业终于受到国家视察员的监督（1863年议会会议快结束时），同时，这次会议通过的法令还禁止18岁以下的面包工人在晚上9点至第二天早晨5点这段时间内做工。上面这项条款充分说明了这个带有古代遗风的工业部门中过度劳动的情形。","language":"中文","translation":false},{"id":"capital-9-68","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“伦敦的面包工人通常在夜里11点开始干活。他先发面，这是一种极费力气的活。根据烤制面包的数量和精粗程度，需要半小时到三刻钟。然后他躺在那块兼作发面盆盖子的面板上，拿一个面袋枕在头下，再拿一个面袋盖在身上，睡几个钟头。随后他一连紧张地忙上5个小时，把面揉好，分成一块一块，做成面包的样子，放到炉里去烤，再从炉里取出，等等。烤炉房的温度达75度到90度，小烤炉房的温度还要高些。各种各样的面包做成后，分送面包的工作又开始了。短工中的一大部分人，刚刚结束了上述繁重的夜间劳动，又要在白天提着篮子或推着车子挨户送面包，有时，他们还要再在烤炉房里干些别的活。根据季节和营业范围的不同，劳动在下午1点到6点之间结束，而另一部分工人则在烤炉房里一直忙到晚上。”[78]“在伦敦社交季节，伦敦西区烤制‘全价’面包的工人通常是在夜里11点开始干活，一直忙到第二天早晨8点，中间只稍微休息一两次。然后就叫他们运送面包，或有时在烤炉房烤面包干，一直干到下午4点、5点、6点甚至7点。活全干完了才睡6个小时，有时只睡5个或4个小时。到了星期五，总是提前上工，大约从晚上10点开始，不停地烤制面包或发送面包，一直忙到星期六晚上8点，而在大多数情况下，要一直干到星期日早晨4点或5点。就连出售‘全价’面包的第一流面包房，到了星期天，也要为第二天做4—5小时的准备工作…… 在‘卖低价面包的老板’那里（前面已经说过，这种人在伦敦面包业主中占3/4），面包工人的劳动时间更长，不过几乎全是在烤炉房里做工，因为他们的老板除把面包供应一些小铺子外，只在自己的店铺里出售。每当临近周末……就是说从星期四起，晚上10点就开始干活，一直干到星期六深夜，中间只有很少的休息。”[79]","language":"中文","translation":false},{"id":"capital-9-69","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"至于这些“卖低价面包的老板”，连资产阶级人士也懂得：“工人的无酬劳动是他们进行竞争的基础”[80]。而“卖全价面包的老板”则向调查委员会揭发说，他的“卖低价面包”的竞争者盗窃别人的劳动，并在面包中掺假。","language":"中文","translation":false},{"id":"capital-9-70","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“他们所以走运，全靠欺骗公众，压榨工人，要工人劳动18小时，而只给12小时的工资。”[81]","language":"中文","translation":false},{"id":"capital-9-71","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在英国，面包掺假和卖低价面包的面包业主阶层的形成，都是从十八世纪初发展起来的，那时，这一行业的行会性质刚刚消失，而资本家以面粉厂厂主或面粉代理商的面目，出现在名义上的面包房老板的背后[82]。这就为资本主义的生产，为无限度地延长工作日和为夜间劳动奠定了基础，虽然夜间劳动甚至在伦敦也只是在1824年才真正站稳脚跟。[83]","language":"中文","translation":false},{"id":"capital-9-72","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"根据以上所述，我们就可以了解，为什么委员会的报告把面包工人列为短命的工人；这些工人即使幸运地逃脱了工人阶级的各个部分通常都难免的夭折，他们也很少活到42岁。可是，等着去面包业做工的人总是非常之多。就伦敦来说，这种“劳动力”的来源是苏格兰、英格兰西部农业区以及德国。","language":"中文","translation":false},{"id":"capital-9-73","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1858—1860年，爱尔兰的面包工人自己筹款组织了多次群众大会，来反对做夜工和星期日劳动。公众怀着爱尔兰人的热情表示站在工人一边，例如在都柏林1860年的五月大会上就是这样。由于这一运动，只做日工的规定才在威克斯弗德、基尔肯尼、克郎梅尔、瓦特福德等地真正有效地得到执行。","language":"中文","translation":false},{"id":"capital-9-74","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“在雇佣工人苦不堪言的里美黎克，由于面包房老板，特别是面包房兼磨坊老板的反抗，运动遭到了失败。里美黎克的失败引起了恩尼斯和梯培雷里两郡的倒退。在公众的不满情绪表现得最强烈的科克郡，老板们利用他们解雇工人的权力，把运动压了下去。在都柏林，老板们进行了最坚决的反抗，他们用迫害领导运动的工人的办法，迫使其余的工人让步，同意做夜工和星期日劳动。”[84]","language":"中文","translation":false},{"id":"capital-9-75","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在爱尔兰武装到牙齿的英国政府所属的委员会，竟痛切地规劝都柏林、里美黎克、科克等地那些铁石心肠的面包房老板：","language":"中文","translation":false},{"id":"capital-9-76","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“委员会认为，劳动时间受自然规律的限制，若有违反，必受惩罚。老板们用解雇来威胁工人，迫使他们违背宗教信仰，违反国家法律，冒犯社会舆论〈这些全是指星期日劳动〉，这样老板们就播下劳资敌对的种子，做出了有害宗教、道德和社会秩序的先例…… 委员会认为，把工作日延长到12小时以上，是横暴地侵犯工人的家庭生活和私人生活，这会破坏一个男人的家庭，使他不能履行他作为一个儿子、兄弟、丈夫和父亲所应尽的家庭义务，以致造成道德上的非常不幸的后果。12小时以上的劳动会损害工人的健康，使他们早衰早死，因而造成工人家庭的不幸，恰好在最必要的时候，失去家长的照料和扶持。”[85]","language":"中文","translation":false},{"id":"capital-9-77","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"以上是爱尔兰的情形。在海峡彼岸的苏格兰，农业工人（即庄稼汉）揭露，他在最寒冷的天气里，每天要劳动13—14小时，星期日还要从事4小时的额外劳动（这还是在信守安息日的国家里呢！）[86]。就在这个时候，伦敦一个大陪审团面前站着三个铁路员工：一个列车长，一个司机，一个信号员。一次惨重的车祸把几百名旅客送到了另一个世界。这几个铁路员工的疏忽大意是造成这次不幸事件的原因。他们在陪审员面前异口同声地说，10—12年以前，他们每天只劳动8小时。但是在最近5—6年内，劳动时间延长到了14、18甚至20小时，而在旅客特别拥挤的时候，例如在旅行季节，他们往往要连续劳动40—50小时。可是他们都是些普通人，并不是塞克洛普。他们的劳动力使用到一定限度就不中用了。他们浑身麻木，头发昏，眼发花。但是最“可尊敬的不列颠陪审员”对他们的回答，是定为“杀人罪”，交付巡回审判庭审理，并只在一项温和的附录中表示良好的愿望，希望铁路大亨们将来在购买必要数量的“劳动力”时大方一些，在榨取所购买的劳动力时“节制”、“节欲”或“节俭”一些。[87]","language":"中文","translation":false},{"id":"capital-9-78","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"一大群不同职业、年龄、性别的各色各样的工人，争先恐后地向我们拥来，简直比被杀者的鬼魂向奥德赛拥去还要厉害。即使他们腋下没有夹着蓝皮书，我们也可以一眼看出他们从事过度劳动的情形。现在让我们从这一大群人当中再挑出两种人来，一种是女时装工，一种是铁匠。这两种人的鲜明的对照表明，在资本面前一切人都是平等的。","language":"中文","translation":false},{"id":"capital-9-79","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1863年6月下旬，伦敦所有的日报都用《一个人活活累死》这一“耸人听闻”的标题登载着一条消息，报道一个20岁的女时装工玛丽·安·沃克利是怎样死的。她在一家很有名的宫廷时装店里做工，受一位芳名爱丽丝的老板娘的剥削。这里又碰到我们常常讲的那一类老故事了[88]。店里的女工平均每天劳动16 1/2小时，在忙季，她们往往要一连劳动30小时，要不时靠喝雪莉酒、葡萄酒或咖啡来维持她们已经不听使唤的“劳动力”。当时正是忙季的最高潮。为了迎贺刚从国外进口的威尔士亲王夫人，女工们要为高贵的夫人小姐立即赶制参加舞会的华丽服装。玛丽·安·沃克利同其他60个女工一起连续干了26 1/2小时，一间屋挤30个人，空气少到还不及需要量的1/3，夜里睡在用木板隔成的一间间不透气的小屋里，每两人一张床。[89]这还是伦敦一家较好的时装店。玛丽·安·沃克利星期五得病，星期日就死了，而使老板娘爱丽丝大为吃惊的是，她竟没有来得及把最后一件礼服做好。医生基斯先生被请来的时候已经太迟了，他直率地向验尸陪审团作证说：","language":"中文","translation":false},{"id":"capital-9-80","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“玛丽·安·沃克利致死的原因，是在过分拥挤的工作室里劳动时间过长，以及寝室太小又不通风。”","language":"中文","translation":false},{"id":"capital-9-81","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"为了教医生讲话得体，验尸陪审团却说：","language":"中文","translation":false},{"id":"capital-9-82","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“死者是中风死的，但是也有理由担心，在过分拥挤的工作室里劳动过度等等，可能加速了她的死亡。”","language":"中文","translation":false},{"id":"capital-9-83","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"自由贸易论者科布顿和布莱特的机关报《晨星报》叫喊道：“我们的白色奴隶劳作到坟墓里去了，无声无臭地憔悴而死了。”[90]","language":"中文","translation":false},{"id":"capital-9-84","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“累死——这是目前普遍存在的现象，不仅在时装店是如此，在很多地方，在一切生意兴隆的地方都是如此…… 我们试以铁匠为例。如果可以相信诗人的话，那末世界上再没有象铁匠那样强健、那样快活的人了。他大清早就起来，太阳还没有出来，就丁当丁当地打起铁来。他比谁都吃得多，喝得足，睡得好。单就身体条件来说，如果劳动适度，铁匠的情况确实是属于最好的了。但是，我们到城里去，看看这些健壮的汉子所担负的劳动重担，看看他们在我国的死亡表上所占据的位置吧。在梅里勒榜区〈伦敦最大的市区之一〉，铁匠每年的死亡率为31/1000，比英国成年男子的平均死亡率高11/1000。打铁几乎是人的天生的技能，本来是无可非议的，只是由于过度劳动才成为毁灭人的职业。他每天能打这么多锤，迈这么多步，呼吸这么多次，干这么多活，平均能活比方说50年。现在强迫他每天多打这么多锤，多迈这么多步，多呼吸这么多次，而这一切加在一起就使他的生命力每天多耗费1/4。他尽力做了，结果在一个有限的时期内多干了1/4的活，但是他活不到50岁，他37岁就死了。”[91]","language":"中文","translation":false},{"id":"capital-9-85","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"4、日工和夜工。换班制度","language":"中文","translation":false},{"id":"capital-9-86","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"从价值增殖过程来看，不变资本即生产资料的存在，只是为了吮吸劳动，并且随着吮吸每一滴劳动吮吸一定比例的剩余劳动。如果它们不这样做，而只是闲置在那里，就给资本家造成消极的损失，因为生产资料闲置起来就成了无用的预付资本；如果恢复中断的生产必须追加开支，那末这种损失就变成积极的损失了。把工作日延长到自然日的界限以外，延长到夜间，只是一种缓和的办法，只能大致满足一下吸血鬼吮吸劳动鲜血的欲望。因此，在一昼夜24小时内都占有劳动，是资本主义生产的内在要求。但是日夜不停地榨取同一劳动力，从身体上说是不可能的，因此，要克服身体上的障碍，就得使白天被吸尽的劳动力和夜里被吸尽的劳动力换班工作。换班有各种办法，例如可以使一部分工人这个星期做日班，下个星期做夜班，等等。大家知道，这种换班制度，这种换班制的经营方法，在英国棉纺织业等部门方兴未艾的青春时期是很盛行的，今天，在莫斯科省的纺纱厂中也很流行。这种24小时连续不停的生产过程，作为一种制度，直到今天还存在于大不列颠的许多依然“自由”的工业部门中，其中如英格兰、威尔士和苏格兰的炼铁厂、锻冶厂、压延厂以及其他金属工厂。在这里，劳动过程除了6个工作日每天24小时，在大多数工厂还包括星期日24小时。工人中有男有女，有成年人有儿童。儿童和少年从8岁（有时是6岁）直到18岁年龄不等[92]。在某些部门中，少女和妇女也整夜和男工一道做工。[93]","language":"中文","translation":false},{"id":"capital-9-87","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"我们且不说夜工的一般害处[94]。昼夜24小时不断的生产过程，为打破名义上的工作日界限提供了极大的方便。例如在上述那些劳动繁重的工业部门中，每个工人公认的工作日大多为12小时，无论夜工或日工都是如此。但是在很多场合，那种超出这一界限的过度劳动，用英国官方报告的话来说，“实在可怕”[95]。报告说：","language":"中文","translation":false},{"id":"capital-9-88","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“任何有感情的人想到证词中提到的9—12岁儿童所担负的劳动量，都不能不得出结论说，再也不能容许父母和雇主这样滥用权力。”[96]","language":"中文","translation":false},{"id":"capital-9-89","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“儿童昼夜轮班做工的办法，无论在忙时或平时，都会使工作日极度延长。这种延长在许多场合不仅骇人听闻，而且简直令人难以置信。有时难免有的儿童因某种原因不能上工接班。这时，一个或几个该下工的儿童就得留下来填补空位。这个办法是人人皆知的，有一次，我问一个压延厂的经理，没有上工的儿童由谁代替，他竟回答说：‘我知道，你心里和我一样明白。’他毫不犹豫地承认了上述事实。”[97]","language":"中文","translation":false},{"id":"capital-9-90","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“有一个压延厂，名义上的工作日是从早晨6点到晚上5点半。有一个儿童，每星期有4个夜晚，至少要干到第二天晚上8点半……这样一直继续了6个月。”“另一个儿童，9岁时，有时一连做3班，每班12小时，10岁时，有时一连干两天两夜。”“第三个儿童，今年10岁，每星期有三天都是从早晨6点一直干到夜间12点，在其余几天干到晚上9点。”“第四个儿童，今年13岁，整个星期都是从下午6点干到第二天中午12点，有时接连做3班，例如从星期一早晨一直干到星期二夜晚。”“第五个儿童，今年12岁，在斯泰夫利铸铁厂做工，他一连14天都是从早晨6点干到夜间12点，他已经不能再这样干下去了。”9岁的乔治·阿林斯沃思说：“我是上星期五来的。我们应当在第二天清早3点上工。所以我就留在这里过夜。我家离这里有5哩路。我睡在地板上，铺一条皮围裙，盖一件短外衣。以后的两天我早晨6点来上工。唉！这个地方真热！来这儿以前，我有整整一年的时间也是在高炉上做工。那是在乡下的一家非常大的工厂，在那里，星期六也是清早3点上工，不过好歹还能回家睡觉，因为离家不远。在别的日子里，我早晨6点上工，到晚上6点或者7点下工。”如此等等。[98]","language":"中文","translation":false},{"id":"capital-9-91","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"现在我们来听听资本自己是怎样解释这种24小时制度的。当然，对于这种制度的极端形式，对于它滥用这种制度，以致把工作日延长到“骇人听闻和令人难以置信”的程度，它是避而不谈的。它所谈的只是这种制度的“正常”形式。","language":"中文","translation":false},{"id":"capital-9-92","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"内勒和维克斯公司炼钢厂老板，雇有600至700个工人，其中只有10％未满18岁，这些未满18岁的工人当中又只有20个男孩是做夜班的。这个公司说：","language":"中文","translation":false},{"id":"capital-9-93","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“这些男孩根本不感到酷热难熬。温度大约介于86°至90°之间…… 锻冶车间和压轧车间分昼夜两班劳动，其他各车间就只有日班，从早晨6点到晚上6点。锻冶车间的劳动是从12点到12点。有一些人只做夜工，不日夜换班…… 我们没有发现日工和夜工对健康〈内勒和维克斯公司老板的健康吗？〉有什么不同的影响。而且，休息时间固定不变比昼夜改变恐怕要睡得好些…… 约有20个未满18岁的少年做夜班…… 不叫18岁以下的少年做夜工，我们就应付不下去。我们所以反对，是因为这会增加生产费用。熟练工人和工头不容易找，而少年工要多少有多少…… 当然，我们使用的少年工的比例是比较小的，所以限制夜工同我们并没有多大的利害关系。”[99]","language":"中文","translation":false},{"id":"capital-9-94","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"约翰·布朗公司钢铁厂有3000名成年男工和少年工，一部分制钢制铁的重活是“昼夜换班”的。该公司的约·埃利斯先生说，在劳动繁重的制钢厂，每两个成年男工配一个或两个少年工。在他们公司里，18岁以下的少年工有500名，其中约1/3即170名不满13岁。关于拟议中的法律修正案，埃利斯先生说：","language":"中文","translation":false},{"id":"capital-9-95","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“禁止未满18岁的人在24小时内劳动12小时以上，我并不认为是特别值得谴责的。但是我不认为，人们可以划一条线来规定12岁以上的少年免做夜工。我们宁可接受完全禁止未满13岁甚至15岁的少年做工的法律，而不愿接受不让我们已有的少年做夜工的禁令。做日班的少年也必须轮换做夜班，因为成年男工不能老是做夜班；这会毁掉他们的健康。不过我们认为，做一星期夜工，又做一星期日工，不会有什么害处。〈而内勒和维克斯公司为了维护他们自己的工厂的利益，却相反地认为，连续做夜工并没有害处，定期轮换做夜工倒可能有害处。〉我们看到，轮换做夜工的人同专做日工的人同样健康…… 我们反对禁止18岁以下的少年做夜工，因为这会增加费用。这就是唯一的理由。〈多么无耻的坦率！〉我们认为，为此增加的费用，会超出企业正常的负担能力，如果适当地考虑到营业的成效的话。〈多么拐弯抹角！〉这里劳力很少，进行这种调整，就会使劳力不够用。〈这就是说，埃利斯—布朗公司就会陷入不得不如数支付劳动力价值的不幸境地。〉”[100]","language":"中文","translation":false},{"id":"capital-9-96","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"康麦尔公司的“塞克洛普”钢铁厂同上述约翰·布朗公司的规模不相上下。该厂的经理曾把他的一份书面证词亲手递交给政府委员怀特，但是后来把证词退给他修改时，他又觉得最好还是把这个手稿隐藏起来。但怀特先生的记忆力很强。他非常清楚地记得，在塞克洛普公司看来，禁止儿童和少年做夜工是“行不通的事情；这无异于关闭他们的工厂”，虽然在他们工厂中未满18岁的少年只占6％强，未满13岁的只占1％！[101]","language":"中文","translation":false},{"id":"capital-9-97","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"关于这个问题，亚特克利夫的炼钢、压延、锻铁工厂，桑德森兄弟钢铁公司的伊·弗·桑德森先生说：","language":"中文","translation":false},{"id":"capital-9-98","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“禁止未满18岁的少年做夜工会引起很大的困难；主要的困难是，用成年男工代替少年工必然使费用增加。增加多少，我说不上，但是看来不会增加到使工厂主能够提高钢的价格，因此，这种损失就落在工厂主身上，因为成年男工〈多么固执的人！〉当然会拒绝承担这种损失”。","language":"中文","translation":false},{"id":"capital-9-99","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"桑德森先生不知道他究竟付给儿童多少工资，不过，","language":"中文","translation":false},{"id":"capital-9-100","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“大概每人每周得到4—5先令…… 少年工干的活，一般地说来〈当然不总是“特殊地说来”〉，有少年工的力气就足够用了，用成年男工的较大力气是得不偿失，只有在很少的场合，如金属制件很重时，使用这种较大的力气才合算。成年男工也喜欢有个少年工当下手，因为成年男工不那么听话。此外，儿童也应当从小就开始学手艺。只许少年做日工，就达不到这个目的”。","language":"中文","translation":false},{"id":"capital-9-101","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"为什么呢？为什么少年不能在白天学手艺呢？你的理由是什么呢？","language":"中文","translation":false},{"id":"capital-9-102","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“因为这样一来，成年男工一周做日工，一周做夜工，就会有一半时间和同班的少年工分开，从而把他们从少年工那里得到的利益丧失一半。成年男工教少年工学手艺，就算作少年工劳动报酬的一部分，这就使成年男工能够得到廉价的少年劳动。所以，只准少年做日工，就会使每个成年男工的利益丧失一半。”","language":"中文","translation":false},{"id":"capital-9-103","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"换句话说，桑德森公司就得自己掏腰包，而不能再用少年工的夜间劳动来支付成年男工的这部分工资了。这样一来，桑德森公司的利润就会减少一些，而这就是桑德森公司所谓少年工不能在白天学手艺的好理由[102]。此外，现在同少年工换班的成年男工就得担负起全部的夜工，这是他们不能忍受的。总之，困难是太大了，也许会使夜工完全停下来。伊·弗·桑德森说：“至于说到钢的生产本身，那倒不会有什么差别。但是！”但是桑德森公司不单是生产钢而已。生产钢只是赚钱的借口。熔炉、轧钢设备等等，厂房、机器、铁、煤等等，除了变成钢，还有别的任务。它们的存在是为了吸取剩余劳动，而24小时吸取的剩余劳动当然比12小时多。事实上，按照上帝旨意和人间法律，桑德森公司有了它们也就有了一张证书，可以在一天全部24小时内支配一定数量人手的劳动时间；而它们吸取劳动的职能一旦中断，它们也就丧失了资本的性质，从而给桑德森公司造成纯粹的损失。","language":"中文","translation":false},{"id":"capital-9-104","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“这时，在这些有一半时间停着不用的非常贵重的机器上，必然会受到损失。并且，为了生产在目前这种制度下所能生产的同样数量的产品，就得把厂房和机器增加一倍，而这样就会使费用增加一倍。”","language":"中文","translation":false},{"id":"capital-9-105","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"其他资本家都只准在白天开工，他们的厂房、机器、原料到夜间就“停着不用”，可是为什么这个桑德森公司偏偏要求特权呢？伊·弗·桑德森代表全体桑德森回答说：","language":"中文","translation":false},{"id":"capital-9-106","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“是的，凡是只在白天开工的工厂，都会遭受到这种由于机器停着不用而造成的损失。但是我们使用熔炉，损失就更大。如果熔炉不停火，就会浪费燃料〈现在却是浪费工人的生命材料〉，如果熔炉停火，就要重新生火并等待烧到必要的热度，这就损失了时间〈而睡眠时间——甚至是8岁孩子的睡眠时间——的损失，正是桑德森家族捞到的劳动时间〉，而且一冷一热会使熔炉受到损害〈而昼夜换班劳动却不会使熔炉受到损害了〉”。[103]","language":"中文","translation":false},{"id":"capital-9-107","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"5、争取正常工作日的斗争。十四世纪中叶至十七世纪末叶关于延长工作日的强制性法律","language":"中文","translation":false},{"id":"capital-9-108","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“什么是一个工作日呢”资本支付劳动力的日价值，可以在多长的时间内消费劳动力呢？在劳动力本身的再生产所需要的劳动时间以外，可以把工作日再延长到什么程度呢？我们知道，资本对这些问题的回答是：工作日就是一昼夜24小时减去几小时休息时间。没有这种休息时间，劳动力就根本不能重新工作。首先，不言而喻，工人终生不外就是劳动力，因此他的全部可供支配的时间，按照自然和法律，都是劳动时间，也就是说，应当用于资本的自行增殖。至于个人受教育的时间，发展智力的时间，履行社会职能的时间，进行社交活动的时间，自由运用体力和智力的时间，以至于星期日的休息时间（即使是在信守安息日的国家里）[104]，——这全都是废话！但是，资本由于无限度地盲目追逐剩余劳动，象狼一般地贪求剩余劳动，不仅突破了工作日的道德极限，而且突破了工作日的纯粹身体的极限。它侵占人体成长、发育和维持健康所需要的时间。它掠夺工人呼吸新鲜空气和接触阳光所需要的时间。它克扣吃饭时间，尽量把吃饭时间并入生产过程，因此对待工人就象对待单纯的生产资料那样，给他饭吃，就如同给锅炉加煤、给机器上油一样。资本把积蓄、更新和恢复生命力所需要的正常睡眠，变成了恢复精疲力尽的机体所必不可少的几小时麻木状态。在这里，不是劳动力的正常状态的维持决定工作日的界限，相反地，是劳动力每天尽量的耗费（不论这是多么强制和多么痛苦）决定工人休息时间的界限。资本是不管劳动力的寿命长短的。它唯一关心的是在一个工作日内最大限度地使用劳动力。它靠缩短劳动力的寿命来达到这一目的，正象贪得无厌的农场主靠掠夺土地肥力来提高收获量一样。","language":"中文","translation":false},{"id":"capital-9-109","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"可见，资本主义生产——实质上就是剩余价值的生产，就是剩余劳动的吸取——通过延长工作日，不仅使人的劳动力由于被夺去了道德上和身体上的正常发展和活动的条件而处于萎缩状态，而且使劳动力本身未老先衰和死亡[105]。它靠缩短工人的寿命，在一定期限内延长工人的生产时间。","language":"中文","translation":false},{"id":"capital-9-110","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"但是，劳动力的价值包含再生产工人或延续工人阶级所必需的商品的价值。既然资本无限度地追逐自行增殖，必然使工作日延长到违反自然的程度，从而缩短工人的寿命，缩短他们的劳动力发挥作用的时间，因此，已经消费掉的劳动力就必须更加迅速地补偿，这样，在劳动力的再生产上就要花更多的费用，正象一台机器磨损得越快，每天要再生产的那一部分机器价值也就越大。因此，资本为了自身的利益，看来也需要规定一种正常工作日。","language":"中文","translation":false},{"id":"capital-9-111","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"奴隶主买一个劳动者就象买一匹马一样。他失去奴隶，就是失去一笔资本，必须再花一笔钱到奴隶市场上去买，才能得到补偿。但是，","language":"中文","translation":false},{"id":"capital-9-112","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“尽管乔治亚州的稻田和密西西比州的沼泽地对人体组织具有致命的危害，这种对人的生命的破坏，总不会大到连靠弗吉尼亚州和肯塔基州的黑人众多的‘自然保护区’也补充不了的程度。当经济上的考虑使奴隶主的利益同保存奴隶相一致时，这种考虑还可以成为奴隶受到人的待遇的某种保证，但在实行奴隶贸易以后，同样的经济上的考虑却成了把奴隶折磨致死的原因，因为奴隶一旦可以从外地的黑人‘自然保护区’得到补充，他们的寿命也就不如他们活着时的生产率那样重要了。因此，在奴隶输入国，管理奴隶的格言是：最有效的经济，就是在最短的时间内从当牛马的人身上榨出最多的劳动。在种植热带作物的地方，种植园的年利润往往与总资本相等，正是在这些地方，黑人的生命被视同草芥。正是这个几世纪来成为巨大富源的西印度农业，曾吞没了几百万非洲人。拿现在的古巴来说，那里每年的收入总是以百万计算，种植园主俨然就是王公，但是我们看到，那里的奴隶阶级饮食最坏，劳动最累最重，甚至每年都有一大批人直接由于劳动过度、睡眠和休息不足等慢性折磨而丧命”。[106]","language":"中文","translation":false},{"id":"capital-9-113","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"只要换一个名字，这正是说的阁下的事情！试把奴隶贸易换成劳动市场，把肯塔基和弗吉尼亚换成爱尔兰以及英格兰、苏格兰和威尔士的农业区，把非洲换成德国再看看罢！我们已经听到，过度劳动使伦敦的面包工人不断丧生，可是伦敦的劳动市场总是挤满来自德国和其他地方的人，等着去面包房送死。我们已经看到，陶器业是工人寿命最短的行业之一。但是陶工是不是因此就缺少呢？普通工人出身的、现代陶器业的创始人约瑟亚·威季伍德，1785年曾向下院说，陶器业共有15000到20000人[107]。到了1861年，单是大不列颠的陶器业市镇人口就有101302人。","language":"中文","translation":false},{"id":"capital-9-114","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“棉纺织业有90年的历史…… 在英国经历了三代人，却吞没了九代纺织工人。”[108]","language":"中文","translation":false},{"id":"capital-9-115","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"诚然，在个别的热病式的繁荣时期，劳动市场上曾严重缺乏劳动力。例如1834年就是这样。当时工厂主先生们向济贫法委员会建议，把农业区的“过剩人口”送往北方，并表示“工厂主们将吸收和消费这批人”[109]。这是他们的原话。","language":"中文","translation":false},{"id":"capital-9-116","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“在济贫法委员会的同意下，在曼彻斯特成立了代办所。农业工人的名单造好以后交给了代办所。工厂主们纷纷赶到代办所，挑选自己需要的人，然后就把这些家庭从英国南部运出来。这些人体包裹就象一包包货物一样，挂上签条，装上船或货车运走了；也有人步行，很多人迷了路，在工业区流浪，濒于饿死的境地。这已经发展成为一种真正的贸易部门。下院几乎不相信会有这样的事。但是这种经常的贸易，这种贩卖人肉的行当继续存在，曼彻斯特代办所不断把这些人买来，卖给曼彻斯特的工厂主，就象把黑人经常不断地卖给美国南部各州的植棉主一样…… 1860年，棉纺织业空前繁荣…… 人手又不够了。工厂主们又向贩卖人肉的代办所求援……于是代办所便到多尔塞特郡的沙丘地带、戴文郡的高地、威尔兹郡的平原去搜罗，但过剩的人口已经被吸收光了。”","language":"中文","translation":false},{"id":"capital-9-117","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"《贝里卫报》抱怨说，英法通商条约签订以后，本来还会吸收1万人，而且马上还需要3—4万人。但是从事人肉买卖的大小代办所1860年在农业区几乎没有搜罗到什么人，于是","language":"中文","translation":false},{"id":"capital-9-118","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“工厂主们派了代表去求见济贫法委员会主席维利尔斯先生，请求他再次准许贫民习艺所的穷孩子和孤儿进工厂去做工”。[110]","language":"中文","translation":false},{"id":"capital-9-119","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"一般说来，经验向资本家表明：过剩人口，即同当前资本增殖的需要相比较的过剩人口，是经常存在的，虽然这些人发育不良，寿命短促，更替迅速，可以说未成熟就被摘掉[111]。另一方面，经验向有理解力的观察者表明：虽然从历史的观点看，资本主义生产几乎是昨天才诞生的，但是它已经多么迅速多么深刻地摧残了人民的生命根源；工业人口的衰退只是由于不断从农村吸收自然生长的生命要素，才得以缓慢下来；甚至农业工人，尽管他们可以吸到新鲜空气，尽管在他们中间自然选择的规律（按照这个规律，只有最强壮的人才能生存）起着无限的作用，也已经开始衰退了[112]。有如此“好理由”来否认自己周围一代工人的苦难的资本，在自己的实际活动中不理会人类将退化并将不免终于灭种的前途，就象它不理会地球可能和太阳相撞一样。在每次证券投机中，每个人都知道暴风雨总有一天会到来，但是每个人都希望暴风雨在自己发了大财并把钱藏好以后，落到邻人的头上。我死后哪怕洪水滔天！【116】这就是每个资本家和每个资本家国家的口号。因此，资本是根本不关心工人的健康和寿命的，除非社会迫使它去关心[113]。人们为体力和智力的衰退、夭折、过度劳动的折磨而愤愤不平，资本却回答说：既然这种痛苦会增加我们的快乐（利润），我们又何必为此苦恼呢？【117】不过总的说来，这也并不取决于个别资本家的善意或恶意。自由竞争使资本主义生产的内在规律作为外在的强制规律对每个资本家起作用。[114]","language":"中文","translation":false},{"id":"capital-9-120","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"正常工作日的规定，是几个世纪以来资本家和工人之间斗争的结果。但在这个斗争的历史中，出现了两种对立的倾向。例如，我们对照一下英国现行的工厂立法和从十四世纪起一直到十八世纪中叶的劳工法[115]。现代的工厂法强制地缩短工作日，而当时的劳工法力图强制地延长工作日。资本在它的萌芽时期，由于刚刚出世，不能单纯依靠经济关系的力量，还要依靠国家政权的帮助才能确保自己榨取足够的剩余劳动的权利，它在那时提出的要求，同它在成年时期不得不忍痛做出的让步比较起来，诚然是很有限的。只是过了几个世纪以后，“自由”工人由于资本主义生产方式的发展，才自愿地，也就是说，才在社会条件的逼迫下，按照自己的日常生活资料的价格出卖自己一生的全部能动时间，出卖自己的劳动能力本身，为了一碗红豆汤出卖自己的长子继承权【118】。因此，从十四世纪中叶至十七世纪末，资本借国家政权的力量力图迫使成年工人接受的工作日的延长程度，同十九世纪下半叶国家在某些地方为了限制儿童血液变成资本而对劳动时间规定的界限大体相一致，这是很自然的了。例如，在马萨诸塞州，这个直到最近还是北美共和国最自由的州，今天国家规定的12岁以下儿童的劳动时间的界限，在十七世纪中叶还曾经是英国的健壮的手工业者、结实的雇农和大力士般的铁匠的正常工作日。[116]","language":"中文","translation":false},{"id":"capital-9-121","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"第一个劳工法（爱德华三世二十三年即1349年）的颁布，其直接借口（是借口，而不是原因，因为这种法律在这个借口不再存在的情况下继续存在了几百年）是鼠疫猖獗【119】，死了很多人，用一个托利党著作家的话来说，当时“要用合理的价格〈即能保证雇主得到合理的剩余劳动量的价格〉雇用工人，已经困难到了实在难以忍受的地步”[117]。因此，在法律上强制地规定了“合理”工资和工作日界限。后面这一点，即我们在这里唯一关心的一点，在1496年（亨利七世时期）的法令中又提到了。依照法令（虽然始终没有实现），所有手艺人和农业工人的工作日，从三月到九月，应该是从早晨5点到晚上7—8点，其中吃饭时间是早饭1小时，午饭1 1/2小时，午后小餐1/2小时，正好比现行工厂法规定的吃饭时间多一倍[118]。冬季，是从早晨5点劳动到天黑，中间的休息时间不变。1562年的伊丽莎白法令，没有触动“按日领工资或按周领工资”的所有工人的工作日长度，不过它设法把夏季的休息时间限制为2 1/2小时，冬季限制为2小时。午饭时间只有1小时，“1/2小时午睡制”只准在五月中至八月中这段时间内实行。旷工1小时扣工资1便士。但实际上，工人所受的待遇要比法令规定的好得多。政治经济学之父，在某种程度上也可以说是统计学的创始人威廉·配第，在十七世纪最后三十多年发表的一部著作中说：","language":"中文","translation":false},{"id":"capital-9-122","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“工人〈当时是指农业工人〉一天做工10小时，一星期吃饭20次，就是说，平日每天3次，星期天两次。可见，只要他们星期五晚上节食，午饭时间不象现在这样用两小时即从11时到1时，而用一个半小时，从而劳动增加1/20，消费减少1/20，那末，上述税收的1/10就可以筹集出来了”。[119]","language":"中文","translation":false},{"id":"capital-9-123","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"安得鲁·尤尔博士抨击1833年的十二小时工作日法案是倒退到黑暗时代，不是说得很公平吗？当然，劳工法中列举的并为配第所提到的各项规定对学徒也是适用的。至于直至十七世纪末儿童劳动的情况究竟怎样，我们从下面的怨言中可以看出：","language":"中文","translation":false},{"id":"capital-9-124","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我们英国少年在当学徒以前，什么都不干，因此，他们当然需要7年这样长的时间，才能成为熟练的手艺人”。","language":"中文","translation":false},{"id":"capital-9-125","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"相反地，德国值得夸耀的是，那里的儿童在摇篮里就至少“受到一点职业训练”。[120]","language":"中文","translation":false},{"id":"capital-9-126","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在十八世纪的大部分时间内，直到大工业时期以前，英国资本还不能靠支付劳动力一星期的价值而占有工人的整个星期，只有农业工人是例外。当时工人靠四天的工资可以生活一星期，在他们看来，这一事实并不能成为其余两天也要为资本家做工的充分理由。英国有一派经济学家为了替资本效劳，猛烈攻击工人顽固不化；另一派经济学家则为工人辩护。例如，我们就来听听波斯耳思威特（当时他编的商业辞典，就象现在麦克库洛赫和麦克格莱哥尔的同类著作一样受到好评）和前面引述过的《论手工业和商业》的作者之间的争论吧。[121]","language":"中文","translation":false},{"id":"capital-9-127","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我在结束这几点评述的时候，不能不提到从许多人那里听来的这样一种陈腐论调：如果工人（industrious poor）做5天工就足够维持生活，他就不想做满6天工。他们因此做出结论说，必须用税收或任何其他办法提高那些甚至是必要生活资料的价格，来迫使手工业者和工场手工业工人每星期不间断地劳动6天。请原谅，我的见解和这些要王国的劳动人口永远做奴隶的大政治家们不同。他们忘记了这样一句谚语：‘只管干活不玩耍，头脑迟钝人变傻’。难道英国人没有因为他们多才多艺的手工业者和工场手工业工人一向为不列颠的商品争得普遍声誉而感到自豪吗？这是怎样得来的呢？或许就是由于我们生性活泼的劳动大众善于休息娱乐吧。如果硬要他们终年劳碌，每星期干满6天，而且老是干同样的活，那他们的才能不会退化吗？他们不会由活泼的灵巧的人变为笨拙的迟钝的人吗？我们的工人由于这种长期的奴隶制，不是会丧失自己的声誉而不是保持自己的声誉吗？…… 还能指望受着这种残酷折磨的动物有什么熟练的技艺吗？…… 他们中间许多人4天干的活，抵得上法国人干5—6天。但是，如果英国人长期做苦力，恐怕他们就会退化，落在法国人后面。我国人民在战争中素以勇敢闻名，我们不是常说，这是因为一方面有美味的英国牛排和布丁来果腹，另一方面有立宪的自由精神吗？我国手工业者和工场手工业工人所以有高超的才能、精力和技巧，怎能说不是因为他们享有可以随意休息娱乐的自由呢？但愿他们永远不会丧失这种特权，不会失去成为他们劳动技巧和英勇精神的来源的优越生活！”[122]","language":"中文","translation":false},{"id":"capital-9-128","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"关于这个问题，《论手工业和商业》的作者却回答说：","language":"中文","translation":false},{"id":"capital-9-129","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“假如每周的第七天休息是上帝的安排，那就是说，其余6天属于劳动〈下面我们就会看到，他的意思是说属于资本〉，所以强制实行上帝的这一命令，决不能说是残忍的行为…… 人一般说来天生是好逸恶劳的，我们从我国工场手工业工人的行为就不幸地体验到这一点。除非生活资料涨价，不然他们每周平均顶多干4天活…… 假定1蒲式耳小麦代表一个工人的全部生活资料，价格为5先令，工人一天挣1先令。这样，他一周只需要劳动5天，如果1蒲式耳小麦为4先令，他就只需要劳动4天…… 但是王国的工资比生活资料的价格高得多，因此工场手工业工人劳动4天，就可以有余钱维持一周其余几天的闲适生活…… 我希望，我说的这些已足以表明，一周进行6天适度的劳动并不是什么奴隶制。我国农业工人就是一周干6天活的，看来他们是工人（labouring poor）中最幸福的人[123]；荷兰人在手工工场每周也是劳动这么多天，而且看来是一个很幸福的民族。法国人也是这样劳动，只要不是中间插了许多假日的话[124]…… 但是我们的民众却有一种成见，好象他们作为英国人生来就有一种特权，应该比欧洲任何一国的〈工人大众〉都享有更大的自由和独立。这种思想使我们的士兵勇敢起来，就这点说，它可能有些好处；但是工场手工业工人受这种思想的影响越小，他们本身和国家得到的好处就越大。工人无论什么时候都不应当认为自己可以不依靠自己的上司而独立…… 在我们这样一个大概占总人口7/8的人只有一点财产或没有财产的商业国家里，怂恿不良分子是非常危险的[125]……只有我们的工业贫民情愿做6天工而依旧领取现在做4天工所得的工资，情况才能根本好转。”[126]","language":"中文","translation":false},{"id":"capital-9-130","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"为了这种目的，也为了“根除懒惰、放荡和对自由的奢望”，同时也为了“减轻济贫税、鼓励勤勉精神和压低手工工场的劳动价格”，我们的忠于资本的埃卡尔特提出了一个行之有效的办法，就是把这些依赖社会慈善事业的工人，一句话，把需要救济的贫民关进“理想的习艺所”。“这种习艺所应当成为恐怖之所。”[127]在这种“恐怖之所”，这种“理想的习艺所”里，“每天”应当劳动“14小时，不过其中包括适当的吃饭时间，因此净剩的劳动时间是整整12小时”。[128]","language":"中文","translation":false},{"id":"capital-9-131","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在1770年的“理想的习艺所”，在这恐怖之所，工作日是12小时！而经过了六十三年，到了1833年，当英国议会把四种工业部门的13—18岁的儿童的工作日缩短为整整12小时的时候，似乎英国工业的末日就到来了！1852年，当路易·波拿巴为了巩固自己在资产阶级心目中的地位，打算修改法定的工作日时，法国工人大众异口同声地高呼：“把工作日缩短为12小时的法令，是共和国立法留给我们的唯一福利！”[129]在苏黎世，10岁以上的儿童的劳动限制为12小时，在阿尔高，13—16岁的儿童的劳动在1862年从12 1/2小时减为12小时；在奥地利，14—16岁的儿童的劳动在1860年也缩短为12小时。[130]如果马考莱还在的话，一定会以“惊喜若狂”的心情大叫“1770年以来的巨大进步”！","language":"中文","translation":false},{"id":"capital-9-132","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"需要救济的贫民的“恐怖之所”在1770年还只是资本灵魂的梦想，几年以后，它却作为工场手工业工人自身的庞大的“习艺所”矗立起来了。它叫做工厂。但是这一次，理想在现实面前大为逊色。","language":"中文","translation":false},{"id":"capital-9-133","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"6、争取正常工作日的斗争。对劳动时间的强制的法律限制。1833—1864年英国的工厂立法","language":"中文","translation":false},{"id":"capital-9-134","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"资本经历了几个世纪，才使工作日延长到正常的最大极限，然后越过这个极限，延长到12小时自然日的界限[131]。此后，自十八世纪最后三十多年大工业出现以来，就开始了一个象雪崩一样猛烈的、突破一切界限的冲击。道德和自然、年龄和性别、昼和夜的界限，统统被摧毁了。甚至在旧法规中说得十分简单明了的关于昼夜的概念，也变得如此模糊不清，以致1860年一位英国法官为了对昼和夜做出“有判决力的”解释，竟不得不使出真正学究式的聪明[132]。资本则狂欢痛饮来庆祝胜利。","language":"中文","translation":false},{"id":"capital-9-135","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"被生产的轰隆声震晕了的工人阶级一旦稍稍清醒过来，就开始进行反抗，首先是在大工业的诞生地英国。但是三十年来，工人所争得的让步完全是有名无实的。从1802年到1833年，议会颁布了5个劳动法，但是议会非常狡猾，它没有批准一文钱用于强制地实施这些法令，用于维持必要的官员等等[133]。这些法令只是一纸空文。","language":"中文","translation":false},{"id":"capital-9-136","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“事实是，在1833年的法令以前，儿童和少年被迫整夜、整日或整昼夜从事劳动。”[134]","language":"中文","translation":false},{"id":"capital-9-137","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"现代工业中的正常工作日，只是从1833年颁布了有关棉、毛、麻、丝等工厂的工厂法起才出现的。1833年到1864年的英国工厂立法史，比任何东西都更能说明资本精神的特征！","language":"中文","translation":false},{"id":"capital-9-138","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1833年的法令规定，工厂的普通工作日应从早晨5点半开始，到晚上8点半结束。在这15小时的界限内，在白天的任何时间使用少年（从13岁到18岁）做工都是合法的，但是有一个条件：除某些特别规定的情况外，每个少年每天不得做工12小时以上。法令的第6节规定：“在限制的劳动时间内，每人每天至少应有1 1/2小时的吃饭时间”。除开下面要谈到的例外情况，禁止雇用未满9岁的儿童；9岁至13岁的儿童的劳动每天限制为8小时。禁止9岁至18岁的少年做夜工，也就是在该法令所说的晚上8点半至早晨5点半之间做工。","language":"中文","translation":false},{"id":"capital-9-139","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"立法者根本不想触犯资本榨取成年劳动力的自由，即他们所说的“劳动自由”，于是想出一种别出心裁的制度来防止工厂法造成这种令人发指的后果。1833年6月25日委员会中央评议会的第1号报告说道：","language":"中文","translation":false},{"id":"capital-9-140","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“现时工厂制度的大弊病，在于它必然把儿童劳动延长到成年人工作日的极限。克服这种弊病的唯一的方法，看来就是实行儿童分两班做工的方案，而不是去限制成年人的劳动，因为那样造成的弊病比要消除的弊病更大。”【120】","language":"中文","translation":false},{"id":"capital-9-141","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"这个“方案”于是就以“换班制度”（《System of Relays》；在英语和法语中，Relay都指到驿站换马）的名义实施了。例如，9岁到13岁的儿童分成两班，一班从早晨5点半到午后1点半，另一班从午后1点半到晚上8点半，等等。","language":"中文","translation":false},{"id":"capital-9-142","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"工厂主先生们极端厚颜无耻地无视最近22年来所公布的一切有关儿童劳动的法律，为了奖赏他们，如今又给他们吞服的药丸涂上一层金色。议会决定，未满11岁的儿童从1834年3月1日起，未满12岁的儿童从1835年3月1日起，未满13岁的儿童从1836年3月1日起，不得在工厂从事8小时以上的劳动！这种对“资本”如此宽厚的“自由主义”，理应得到更多的赞赏，因为法尔医生、安·卡莱尔爵士、本·布罗迪爵士、查·贝尔爵士、加思里先生等等，一句话，当时伦敦最著名的内科和外科医生，在下院作证时都曾经说过，“危险在于迟缓！”【121】。关于这个问题，法尔医生说得更尖锐：","language":"中文","translation":false},{"id":"capital-9-143","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“为了防止由任何原因引起的早死，立法同样是必要的。这种方法〈工厂方法〉无疑应看作是引起早死的最残酷的方法之一。”[135]","language":"中文","translation":false},{"id":"capital-9-144","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"同一个“经过改革”的议会，一方面出于对工厂主先生们的温情，迫使未满13岁的儿童在几年内继续在工厂地狱里每周劳动72小时；另一方面却在那也是一点一滴地给予自由的解放法令中，一开始就禁止种植园主强迫黑奴每周劳动45小时以上！","language":"中文","translation":false},{"id":"capital-9-145","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"但是资本毫不体谅，掀起了一个叫嚷了好几年的鼓动运动。运动主要是围绕着儿童的年龄标准问题，因为法律规定，儿童每天做工不得超过8小时，并且要受到一定的义务教育。根据资本主义人类学的说法，儿童时代到10岁，或者至多到11岁就结束了。工厂法完全生效的日期——不祥的1836年——越接近，工厂主这帮恶棍就越猖狂。他们确实把政府吓住了，于是政府在1835年建议把儿童年龄的界限从13岁降为12岁。但这时外界的压力也越来越带有威胁性。下院没有勇气这样做了。它拒绝把13岁的儿童扔在资本的札格纳特车轮下【123】每天被压榨8小时以上。1833年的法令完全生效了。直到1844年6月一直没有变动。","language":"中文","translation":false},{"id":"capital-9-146","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在工厂劳动先是局部后是全部受到这项法令约束的十年间，工厂视察员的官方报告充满了关于这项法令无法实施的抱怨。1833年的法令规定，在早晨5点半到晚上8点半这十五小时内，每个“少年”和“儿童”究竟什么时候开始、中断和停止他的十二小时或八小时劳动，完全由资本家先生们去决定，并且他们还可以为不同的人规定不同的吃饭时间，这样一来，这班先生很快就找到一种新的“换班制度”，让驿马不是在一定的驿站换班，而是在不固定的驿站上一次又一次地被套上跑下去。我们不来进一步谈论这个制度的妙处，因为后面我们还要谈到。但是一眼就看得很清楚，这个制度不仅使整个工厂法的精神，而且使它的条文都落空了。既然每个儿童和少年的帐册如此复杂，工厂视察员有什么办法迫使工厂主遵守法定的劳动时间和吃饭时间呢？以前那种残酷的不法行为很快地又在许多工厂中畅行无阻。工厂视察员在同内务大臣的一次会见（1844年）时证明说，在新发明的换班制度下不可能实行任何监督[136]。但这时情况毕竟有了很大变化。特别是从1838年以来，工厂工人把十小时工作日法案当作自己经济上的竞选口号，正象他们把宪章【124】当作自己政治上的竞选口号一样。甚至一部分按照1833年法令来经营工厂的工厂主，也上书议会，控告某些“口是心非的弟兄”进行不道德的“竞争”，因为这些人由于更加厚颜无耻或拥有较有利的地方条件就违反法律。此外，尽管一个个的工厂主仍然可以为所欲为，工厂主阶级的代言人和政治领袖却要求对工人采取另一种态度和使用另一种语言。他们已经发动了废除谷物法的运动，为了取得胜利，需要工人的帮助！因此，他们不仅答应把大圆面包加大一倍【125】，而且答应在自由贸易的千年王国内实行十小时工作日法案[137]。所以，他们就更不能去反对那种只以实行1833年法令为目的的措施了。最后，托利党人由于自己的最神圣的利益即地租受到威胁，也用博爱家的口吻大骂他们的敌人的“可耻行为”。[138]","language":"中文","translation":false},{"id":"capital-9-147","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"于是就出现了1844年6月7日的补充工厂法案。它从1844年9月10日开始生效。它又把另一类工人，即18岁以上的妇女，置于法律保护之下。她们在各方面都受到与少年工相同的待遇，她们的劳动时间限制为12小时，禁止做夜工，等等。立法第一次被迫对成年人的劳动也进行直接的正式的监督。1844—1845年的工厂报告讽刺地说：","language":"中文","translation":false},{"id":"capital-9-148","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“就我们所知，成年妇女还从未抱怨过这种侵犯她们权利的行为。”[139]","language":"中文","translation":false},{"id":"capital-9-149","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"13岁以下的儿童的工作日缩短为每天6 1/2小时，在有些条件下是7小时。[140]","language":"中文","translation":false},{"id":"capital-9-150","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"为了防止滥用虚假的“换班制度”，法律又规定了下列重要的细则：","language":"中文","translation":false},{"id":"capital-9-151","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“儿童和少年的工作日，应该从有任何一个儿童或少年早晨在工厂里开始劳动的时候算起”。","language":"中文","translation":false},{"id":"capital-9-152","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"按照这个规定，如果A是从早晨8点开始劳动，B是从10点开始劳动，那末，B的工作日仍然要和A的工作日一样，应在同一时间结束。开工时间应以某个公共时钟为准，例如，以附近的铁路时钟为准，工厂的钟要和这个铁路时钟保持一致。工厂主必须在工厂张贴大字印刷的时间表，说明上工、下工、休息的时间。12点以前上工的儿童不得在下午1点钟以后又做工。这样，下午班就不能再有上午班的儿童。受法律保护的全体工人都要有1 1/2小时的吃饭时间，并应在同一时间吃饭，其中至少有1小时应在下午3点以前。儿童或少年至少应有半小时的吃饭时间，否则不得让他们在下午1点以前做工5小时以上。儿童、少年和妇女不得留在某种劳动过程正在进行的厂房中吃饭，等等。","language":"中文","translation":false},{"id":"capital-9-153","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"我们看到，这些按照军队方式一律用钟声来指挥劳动的期间、界限和休息的详尽的规定，决不是议会设想出来的。它们是作为现代生产方式的自然规律从现存的关系中逐渐发展起来的。它们的制定、被正式承认以及由国家予以公布，是长期阶级斗争的结果。它们的直接后果之一，就是这些规定的实施使工厂的成年男工的工作日也受到同样的限制，因为在大多数生产过程中，必须有儿童、少年和妇女的协作。所以总的说来，在1844—1847年期间，受工厂立法约束的一切工业部门，都普遍一致地实行了十二小时工作日。","language":"中文","translation":false},{"id":"capital-9-154","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"但是，工厂主如果没有得到某种“退步”作补偿，是不会容忍这种“进步”的。在他们的敦促下，下院把可以雇用的儿童的最低年龄从9岁减为8岁，以保证资本按照上帝旨意和人间法律得到“工厂儿童的追加供给”。[141]","language":"中文","translation":false},{"id":"capital-9-155","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1846—1847年在英国经济史上划了一个时代。谷物法废除了，棉花和其他原料的进口税取消了，自由贸易被宣布为立法的指路明灯！一句话，千年王国出现了。另一方面，宪章运动和争取十小时工作日运动在这期间达到了顶点。它们在渴望报仇的托利党人那里找到了同盟者。尽管以布莱特和科布顿为首的言而无信的自由贸易派疯狂反抗，争取了多年的十小时工作日法案终于由议会通过了。","language":"中文","translation":false},{"id":"capital-9-156","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1847年6月8日的新工厂法规定，从1847年7月1日起，“少年”（从13岁到18岁）和所有女工的工作日先缩短为11小时，从1848年5月1日起，再最终限制为10小时。在其他方面，这个法令只是1833年和1844年的法令的修正补充。","language":"中文","translation":false},{"id":"capital-9-157","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"资本先发制人，想使这个法令在1848年5月1日不能完全实行。而且，似乎由于取得经验教训而变得聪明的工人自己应当来帮助再一次破坏自己的事情。时机是选择得很巧妙的。","language":"中文","translation":false},{"id":"capital-9-158","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“必须记住，1846—1847年爆发了可怕的危机，工厂工人深受其害，因为很多工厂开工不足，有些工厂完全停工。大量工人的生活非常窘迫，很多工人负有债务。因此，可以有把握地断定，他们宁愿劳动时间更长一些，以便弥补过去的亏损，偿还债务，或者从当铺赎回自己的家具，或者把卖掉的东西再补充进来，或者为自己和家属添制新衣。”[142]","language":"中文","translation":false},{"id":"capital-9-159","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"工厂主先生们普遍把工资降低了10％，企图以此来助长这种状况的自然作用。而这就是所谓向自由贸易新纪元的献礼。后来，工作日缩短为11小时，工资又降低8 1/3％，最后工作日缩短为10小时，工资降低的百分比再增加一倍。因此，凡是在情况允许的地方，工资至少降低了25％[143]。在这样准备妥当的时机下，就在工人中间展开了废除1847年法令的鼓动。欺骗、诱惑、威胁的手段全都用了，但都是枉费心机。虽然在工人中间征集到了半打请愿书，诉说“他们深受这个法令的压迫”，但是在口头询问这些请愿者的时候，他们说是被迫签名的。“他们是受压迫，但不是受工厂法而是受某种人的压迫。”[144]工厂主们既然无法使工人说出他们工厂主想说的话，于是自己就以工人的名义在报刊上和议会里大叫大嚷。他们指责工厂视察员是一种国民公会委员【126】，说他们要靠残酷无情地牺牲不幸的工人，来实现他们改善世界的奇想。但是这一招也没有得逞。工厂视察员莱昂纳德·霍纳本人以及通过他的助手在郎卡郡的工厂中询问了很多证人。在被询问的工人中，赞成十小时工作日的将近70％，赞成十一小时的百分比要小得多，赞成原来的十二小时的只占极少数。[145]","language":"中文","translation":false},{"id":"capital-9-160","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"另一个“友好的”花招是使成年男工劳动12—15小时，然后宣布这是无产阶级内心愿望的最好的表达。但是“残酷无情的”工厂视察员莱昂纳德·霍纳马上又出现了。大多数“加班加点工人”声称：","language":"中文","translation":false},{"id":"capital-9-161","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“他们宁愿劳动10小时而少拿些工资，但是他们没有选择的余地；他们有很多人失业，有很多纺纱工人被迫去做零工，如果他们拒绝延长劳动时间，别人马上就会把他们挤走。所以，摆在他们面前的问题是：或者把劳动时间延长一些，或者流落街头。”[146]","language":"中文","translation":false},{"id":"capital-9-162","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"资本想先发制人，但是失败了。十小时工作日法令于1848年5月1日生效。但同时，宪章派也失败了。他们的领袖被关进监狱，他们的组织遭到破坏。宪章派的失败已经动摇了英国工人阶级的自信心。不久，巴黎的六月起义和对起义的血腥镇压，使欧洲大陆和英国的统治阶级的一切派别——土地所有者和资本家，交易所豺狼和小商人，保护关税论者和自由贸易论者，政府和反对派，教士和自由信仰者，年轻的娼妇和年老的修女——都在拯救财产、宗教、家庭和社会的共同口号下联合起来了！工人阶级到处被排除在法律保护之外，被革出教门，受到“嫌疑犯处治法”【127】的迫害。工厂主先生们可以为所欲为了。他们不仅公开起来反对十小时工作日法令，而且反对1833年以来企图对劳动力的“自由”榨取稍加限制的一切立法。这是一次缩小型的“维护奴隶制的叛乱”，这次叛乱蛮横无耻，疯狂已极，持续了两年多，而这样做是十分便宜的，因为叛乱的资本家只是用自己工人的生命进行冒险。","language":"中文","translation":false},{"id":"capital-9-163","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"为了便于了解以后的事情，应当记住：1833年、1844年和1847年的各个工厂法，凡是在后者没有对前者做修改的地方，都保留了法律效力；这三个法令都没有限制18岁以上的男工的工作日；从1833年以来，早晨5点半至晚上8点半这15小时的时间始终是法定“日”，在这个界限以内，少年和妇女可以在法律规定的条件下，起先劳动12小时，后来劳动10小时。","language":"中文","translation":false},{"id":"capital-9-164","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"某些地方的工厂主开始把他们雇用的少年工和女工解雇一部分，有时甚至解雇一半，同时却把几乎已经绝迹的夜工在成年男工当中恢复了。他们叫嚷说，十小时工作日法令使他们别无出路！[147]","language":"中文","translation":false},{"id":"capital-9-165","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":165,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"第二步是针对法定的吃饭时间，让我们听听工厂视察员是怎样说的：","language":"中文","translation":false},{"id":"capital-9-166","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":166,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“自从工作日限制为10小时以来，工厂主们就说（虽然实际上他们还没有完全实现他们所说的东西），如果劳动是从早晨9点到晚上7点，那末他们在早晨9点以前拿出1小时，在晚上7点以后拿出半小时，总共用1 1/2小时作为吃饭时间，这也就是充分地执行法令的规定了。现在，在某些场合，他们准许有半小时或1小时的午饭时间，但是他们坚持说，他们没有义务把这1 1/2小时的任何部分包括在十小时工作日之内”。[148]","language":"中文","translation":false},{"id":"capital-9-167","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":167,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"因此，工厂主先生们硬说，1844年法令关于吃饭时间的十分详细的规定，只是允许工人在进厂以前和离厂以后，即在自己家里吃饭喝水！工人为什么不应当在早晨9点以前吃午饭呢？但是皇家法官裁决说，法律规定的吃饭时间","language":"中文","translation":false},{"id":"capital-9-168","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":168,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“必须安排在实际工作日的休息时间内。让工人从早晨9点到晚上7点连续不停地劳动10小时是不合法的”。[149]","language":"中文","translation":false},{"id":"capital-9-169","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":169,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"经过这几场愉快的示威后，资本采取了与1844年法令条文相适应的即合法的步骤来进行反叛。","language":"中文","translation":false},{"id":"capital-9-170","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":170,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"诚然，1844年的法令规定，上午12点以前做工的8—13岁的儿童不准在下午1点以后继续做工。但是在中午12点或下午开始做工的儿童的6 1/2小时劳动，法令却未作任何规定！因此，可以使中午12点开始做工的8岁儿童在12点至1点之间干1小时，在下午2点至4点之间干2小时，在5点至晚上8点半之间干3 1/2小时，总共是法定的6 1/2小时！甚至还有更妙的办法。为了使儿童的劳动同干到晚上8点半的成年男工的劳动配合起来，工厂主只要在下午2点以前不给儿童活干，就可以使他们在工厂中连续不停地干到晚上8点半！","language":"中文","translation":false},{"id":"capital-9-171","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":171,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“现在人们公开承认，近来由于工厂主拚命使机器开动10小时以上，在所有的少年和妇女都离开工厂以后，8—13岁的男女儿童被留下来和成年男工一起干到晚上8点半，这种办法已在英国实行。”[150]","language":"中文","translation":false},{"id":"capital-9-172","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":172,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"工人和工厂视察员从卫生和道德的角度提出抗议。但资本回答说：","language":"中文","translation":false},{"id":"capital-9-173","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":173,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我的行为没有越轨，我要求我的权利！","language":"中文","translation":false},{"id":"capital-9-174","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":174,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"那就是我的契约上规定的罚金和抵押品！”","language":"中文","translation":false},{"id":"capital-9-175","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":175,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"事实上，1850年7月26日向下院提出的统计材料表明，尽管有各种抗议，到1850年7月15日为止，还有257家工厂的3742个儿童受着这种“办法”的折磨[151]。不仅如此！资本的山猫眼睛发现，1844年的法令规定，在上午连续劳动5小时至少要休息30分钟，但是关于下午的劳动却没有任何类似的规定。因此，资本要求而且确实也迫使8岁的童工不仅从下午2点一直拚命干到晚上8点半，而且还要挨饿！","language":"中文","translation":false},{"id":"capital-9-176","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":176,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"契约上是这么说的！”[152]【128】","language":"中文","translation":false},{"id":"capital-9-177","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":177,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"对于1844年法令限制儿童劳动的条款，资本家象夏洛克那样死抓住法令条文不放，但这只是为了对该法令限制“少年和妇女”的劳动的这同一项条款进行公开的反叛。我们记得，消灭“虚假的换班制度”是这个法令的主要目的和主要内容。工厂主开始反叛这个法令的时候，只是简单地声明说，1844年法令禁止在十五小时工厂日内任意分小段时间来使用少年和妇女的条款，","language":"中文","translation":false},{"id":"capital-9-178","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":178,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“在劳动时间限制为12小时的时候，还是比较没有妨害的。而在实行十小时工作日法令的情况下，它们就是难以忍受的不公平了”。[153]","language":"中文","translation":false},{"id":"capital-9-179","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":179,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"因此，他们用最冷静的态度向视察员宣称，他们将不理睬法律的条文，他们打算自行恢复旧的制度。[154]据说，这将符合于听了不良劝告的工人本身的利益，","language":"中文","translation":false},{"id":"capital-9-180","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":180,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“使他们能够得到较高的工资”。“这是在实行十小时工作日法令下保持大不列颠的工业优势的唯一可能的办法。”[155]“在换班制度下要发现违法情况也许有些困难，但这又有什么关系呢？难道为使工厂视察员及其助手省掉一些小小的麻烦，就可以把这个国家的巨大的工厂利益看成是次要的东西吗？”[156]","language":"中文","translation":false},{"id":"capital-9-181","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":181,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"当然，所有这些遁辞都无济于事。工厂视察员向法庭提出诉讼。但是工厂主的请愿书立即象雪片似地飞向内务大臣乔治·格雷爵士，以致他在1848年8月5日的通令中晓谕视察员：","language":"中文","translation":false},{"id":"capital-9-182","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":182,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“只要还没有证实换班制度被滥用来使少年和妇女劳动10小时以上，一般不要按违背法令条文来追究”。","language":"中文","translation":false},{"id":"capital-9-183","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":183,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在这以后，工厂视察员约·斯图亚特就准许苏格兰全境在十五小时工厂日内实行所谓换班制度，于是这种制度很快就象以前那样盛行起来。而英格兰的工厂视察员则声明，内务大臣没有权力自作主张中止法律的实施，并且继续向法庭控告那些维护奴隶制的叛乱者。","language":"中文","translation":false},{"id":"capital-9-184","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":184,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"但是，既然法庭，郡治安法官[157]宣判他们无罪，那传讯又有什么用呢？法庭上坐的是工厂主先生，他们是自己审问自己。举一个例子。克肖—莱塞公司的纺纱厂主，一个叫埃斯克里奇的人，曾把他的工厂准备实施换班制度的计划提交本区的工厂视察员。在他的计划被拒绝以后，他起初没有采取什么行动。几个月以后，一个叫鲁滨逊的人——也是纺纱厂主，他如果不是埃斯克里奇的星期五，至少也是他的亲戚——由于实行一种与埃斯克里奇想出的换班制度相同的制度而被控告到斯托克波尔特市治安法官。庭上坐着4位法官，其中3位是纺纱厂主，而以那位必不可少的埃斯克里奇为首。埃斯克里奇宣判鲁滨逊无罪，并且说，对鲁滨逊来说是合法的事，对埃斯克里奇也是合理的。于是，他根据他自己的具有法律效力的判决，马上就在自己的工厂里实行这种制度[158]。不用说，这种法庭的组成本身就是对法律的公然违反[159]。工厂视察员豪威耳叫道：","language":"中文","translation":false},{"id":"capital-9-185","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":185,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“这种审判把戏急须改革……或者是使法律适应这种宣判，或者是让一个犯错误较少、在一切这样的场合都能使判决适应法律的……法院去执行。多么需要领薪水的法官啊！”[160]","language":"中文","translation":false},{"id":"capital-9-186","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":186,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"皇家法官宣布工厂主对1848年法令的解释是荒谬的，但是社会的救主们坚持原来的想法。莱昂纳德·霍纳报告说：","language":"中文","translation":false},{"id":"capital-9-187","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":187,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“我在7个审判区中提出10件诉讼，试图强制人们执行法律，可是只有一件诉讼得到治安法官的支持……我认为再对违法行为提出诉讼是徒劳无益的。法令中规定劳动时间要整齐划一的那一部分条文……在郎卡郡已经不发生效力。我和我的助手没有任何办法能使自己确信，在实行所谓换班制度的工厂里，确实不让少年和妇女劳动10小时以上…… 1849年4月底，在我的管区里已经有114家工厂采用这种方法，近来这种工厂的数目还在急剧增加。一般说来，现在工厂的劳动是13 1/2小时，从早晨6点到晚上7点半；也有劳动15小时的，从早晨5点半到晚上8点半。”[161]","language":"中文","translation":false},{"id":"capital-9-188","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":188,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"还在1848年12月，莱昂纳德·霍纳就列举出65个工厂主和29个工厂监工，说他们一致认为，在这种换班制度下，任何监督制度都不能阻止过度劳动的广泛流行[162]。同一批儿童和少年时而由纺纱车间调到织布车间，时而在15小时之内由这个工厂调到那个工厂[163]。这样一种制度怎能加以监督呢，","language":"中文","translation":false},{"id":"capital-9-189","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":189,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“它滥用换班之名，把工人象纸牌一样按无限多样的方式混杂起来，并且天天变更各人的劳动和休息时间，以致同组的全体工人永远不能在同一时间同一地点做工！”[164]","language":"中文","translation":false},{"id":"capital-9-190","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":190,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"但是，完全撇开现实的过度劳动不说，这种所谓换班制度是资本幻想的产物，连傅立叶关于“短时工作”【132】的幽默描写都相形见绌，所不同的只是，劳动的吸引力变成了资本的吸引力。我们来看看工厂主所编造的那些计划吧，它们被有声望的报纸誉为“在相当精细和适当的安排下才能做出的事物”的典范。工人有时被分为12至15个类别，各类别本身的组成部分不断改变。在十五小时工厂日内，资本一会儿把工人拉来干30分钟，一会儿拉来干1小时，然后又把他推开，接着又把他拉来，然后再把他推开，就这样一小段一小段时间地把他赶来赶去，但是在他未做满10小时之前，决不把他放掉。就象在舞台上一样，同样一些人物要在各幕戏的各个场次轮流出场。但是也正象演员在整个戏的演出中是属于舞台一样，现在，工人在15小时之内是属于工厂，其中还不包括上下工走路的时间。于是，休息时间变成了强制闲逛的时间，它把少年男工赶进酒店，把少年女工赶进妓院。资本家力图不增加工人而使自己的机器开动12小时或15小时，为此他们每天都想出新的妙法，这就使工人不得不抓住零碎时间把饭吞下去。在争取十小时工作日运动期间，工厂主大喊大叫，说工人歹徒们请愿的目的是想用10小时的劳动取得12小时的工资。现在他们是反过来了。他们支配劳动力12小时或15小时，而只支付10小时的工资！[165]这就是问题的实质，这就是工厂主所解释的十小时工作日法令！正是这些假献殷勤、满嘴博爱的自由贸易论者，在宣传反对谷物法的整整十年中，一分一毫地算给工人听，说如果可以自由输入粮食，那末按照英国工业的能力，只要实行十小时的劳动就足以使资本家发财致富了。[166]","language":"中文","translation":false},{"id":"capital-9-191","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":191,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"资本进行了两年的叛乱终于取得了胜利：英国四个高等法院之一，高等控诉院，于1850年2月8日判决一件案子时宣布，虽然工厂主违反了1844年法令的精神，但是这个法令本身的某些词句已经使法令变得毫无意义。“这种判决废除了十小时工作日法令。”[167]很多以前不敢对少年和女工实行换班制度的工厂主，现在都双手抓住换班制度不放了。[168]","language":"中文","translation":false},{"id":"capital-9-192","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":192,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"但是，随着资本获得表面上的最后胜利，情况立即又发生了变化。在此以前，工人虽然日复一日地进行不屈不挠的反抗，但是这种反抗一直采取守势。现在他们在郎卡郡和约克郡召开声势浩大的集会表示抗议。他们提出，所谓十小时工作日法令只是一场骗局，只是议会的欺诈行为，根本就未存在过！工厂视察员严重地警告政府说，阶级对抗已经达到难以置信的紧张程度。甚至一部分工厂主也抱怨起来：","language":"中文","translation":false},{"id":"capital-9-193","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":193,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“治安法官的互相矛盾的判决，势必造成十分不正常的、无政府的状态。在约克郡是一种法律，在郎卡郡又是一种法律，在郎卡郡的某一教区是一种法律，在邻近的教区又是一种法律。大城市的工厂主可以逃避法律，小地方的工厂主找不到必要的人手来实行换班制度，更不必说把工人从一个工厂调到另一个工厂……”","language":"中文","translation":false},{"id":"capital-9-194","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":194,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"平等地剥削劳动力，是资本的首要的人权。","language":"中文","translation":false},{"id":"capital-9-195","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":195,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在这种情况下，工厂主和工人之间取得了某种妥协，这种妥协被议会在1850年8月5日新的补充工厂法中固定下来。“少年和妇女”的工作日，在一周的前5天从10小时延长为10 1/2小时，星期六限制为7 1/2小时。劳动时间应从早晨6点至晚上6点[169]，其中休息1 1/2小时作为吃饭时间，吃饭时间应当统一，并且要符合1844年的规定等等。这样，换班制度就永远结束了[170]。关于儿童劳动，1844年的法令仍然有效。","language":"中文","translation":false},{"id":"capital-9-196","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":196,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"有一类工厂主，这一次也和以往一样，保全了自己对无产阶级儿童的特殊的领主权。他们是丝厂厂主。1833年他们曾咄咄逼人地喊叫：“如果剥夺他们让各种年龄的儿童每天劳动10小时的自由，那就等于让他们的工厂停工。”他们说，他们无法买到足够数量的13岁以上的儿童。他们强行取得了想要取得的特权。后来的调查表明，他们的借口纯系捏造[171]，但是这并没有妨碍他们在整整10年内，每天用10小时从那些必须靠人放到凳子上才能干活的幼童的血中抽出丝来[172]。1844年的法令虽然“抢走了”他们让不满11岁的儿童每天劳动6 1/2小时以上的“自由”，但是保证了他们让11—13岁的儿童每天劳动10小时的特权，并且取消了儿童在其他工厂本来可以受到的义务教育。这一次的借口是：","language":"中文","translation":false},{"id":"capital-9-197","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":197,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“细巧的织物需要灵巧的手指，而这只有年幼时进工厂才能做到。”[173]","language":"中文","translation":false},{"id":"capital-9-198","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":198,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"儿童们由于手指细巧而被杀戮，正如俄国南部的牛羊由于身上的皮和油而被屠宰一样。最后，1844年准许的这种特权，到1850年又受到限制而只适用于捻丝和缫丝部门了；但是，为了补偿资本失掉这种“自由”而遭到的损失，11—13岁儿童的劳动时间从10小时延长到10 1/2小时。借口是：“丝厂的劳动比其他工厂轻，对健康损害较少。”[174]后来，官方医生的调查表明，情况正好相反，","language":"中文","translation":false},{"id":"capital-9-199","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":199,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“丝业区的平均死亡率异常高，人口中妇女部分的平均死亡率甚至比郎卡郡棉纺织业区还高”。[175]","language":"中文","translation":false},{"id":"capital-9-200","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":200,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"尽管工厂视察员每半年提出一次抗议，但是这种恶劣现象一直继续到现在。[176]","language":"中文","translation":false},{"id":"capital-9-201","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":201,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1850年的法令只是把“少年和妇女”的劳动时间从15小时改为12小时，即从早晨5点半至晚上8点半改为从早晨6点至晚上6点。就是说，这种改变不适用于儿童，他们照旧可以在开工前半小时和完工后2 1/2小时内被使用，尽管他们劳动的总时间不得超过6 1/2小时。在讨论法案的时候，工厂视察员曾向议会提出统计材料，说明这种反常现象造成了可耻的滥用。但是毫无效果。因为在这背后隐藏着一种企图，就是想借助于儿童在繁荣年代重新把成年男工的工作日延长到15小时。以后3年的经验表明，这种企图由于成年男工的反抗必定遭到失败[177]。因此，1850年法令终于在1853年作了补充：禁止“在少年和妇女早晨上工前和晚上下工后使用童工”。从那时起，除了少数例外情况，1850年的工厂法把受它约束的工业部门的全体工人的工作日都纳入法律限制之内了。[178]从第一个工厂法颁布以来，到这时已经过去半个世纪了。[179]","language":"中文","translation":false},{"id":"capital-9-202","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":202,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"1845年公布的“印染工厂法”，使立法第一次超出了它原有的范围。资本容许这种新的“狂暴行为”时的不悦心情，贯穿法令的每一行！这个法令把8—13岁的儿童和妇女的工作日限制为16小时，从早晨6点到晚上10点，并且没有规定任何法定的吃饭时间。它容许人们任意使13岁以上的男工日夜劳动[180]。这是议会的一次流产。[181]","language":"中文","translation":false},{"id":"capital-9-203","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":203,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"但是，原则战胜了，它在作为现代生产方式的特殊产物的大工业部门中胜利了。1853—1860年时期这些部门的惊人发展，以及同时出现的工厂工人体力和精神的复活，连瞎子也看得清清楚楚。连那些经过半个世纪的内战才被迫逐步同意在法律上限制和规定工作日的工厂主，也夸耀这些工业部门与那些仍旧是“自由的”剥削领域所形成的对照。[182]“政治经济学”上的伪善者现在也宣称，认识在法律上规定工作日的必要性，是他们这门“科学”的突出的新成就[183]。不难了解，在工厂大亨们被迫服从不可避免的东西并且同它和解之后，资本的抵抗力量就逐渐削弱了，而同时，工人阶级的进攻力量则随着他们在没有直接利害关系的社会阶层中的同盟者的增加而大为加强。这就是从1860年以来进步较快的原因。","language":"中文","translation":false},{"id":"capital-9-204","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":204,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"染厂和漂白厂[184]在1860年，花边厂和织袜厂在1861年分别受1850年工厂法的约束。由于有童工调查委员会第1号报告（1863年），一切瓦器业（不仅是陶器业）、火柴厂、雷管厂、弹药厂、壁纸厂、天鹅绒厂以及许多统称为“最后整饰”的作业，都遭受同样的命运。1863年，“露天漂白厂”[185]和面包房分别受专门法令的约束，在前一种工厂中禁止在夜间（从晚上8点至早晨6点）使用儿童、少年和妇女做工，在面包房中禁止在晚上9点至早晨5点使用18岁以下的面包工人。根据童工调查委员会以后的各次建议，英国一切重要工业部门，除农业、采矿业和运输业以外，都有被夺去“自由”的危险，关于这些建议我们以后还要谈到。[185a]","language":"中文","translation":false},{"id":"capital-9-205","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":205,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"7、争取正常工作日的斗争。英国工厂立法对其他国家的影响","language":"中文","translation":false},{"id":"capital-9-206","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":206,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"读者会记得，不管生产方式本身由于劳动隶属于资本而产生了怎样的变化，生产剩余价值或榨取剩余劳动，是资本主义生产的特定内容和目的。读者还会记得，从我们到目前为止所阐明的观点看来，只有独立的、因而在法律上是成年的工人，作为商品出卖者与资本家缔结契约。因此，如果说在我们的历史的概述中，起主要作用的一方面是现代工业，另一方面是身体上和法律上未成年的人的劳动，那末我们只是把前者看作榨取劳动的特殊领域，把后者看作这种榨取的最鲜明的例子。但是，即使暂不涉及以后的阐述，仅仅根据历史事实的联系，也可以得出如下的结论：","language":"中文","translation":false},{"id":"capital-9-207","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":207,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"第一，在最早依靠水力、蒸汽和机器而发生革命的工业部门中，即在现代生产方式的最初产物——棉、毛、麻、丝等纺织业中，资本无限度地、放肆地延长工作日的欲望首先得到了满足。物质生产方式的改变和生产者的社会关系的相应的改变[186]，先是造成了无限度的压榨，后来反而引起了社会的监督，由法律来限制、规定和划一工作日及休息时间。因此，这种监督在十九世纪上半叶只是作为例外情况由法律规定的[187]。但是，当这种监督刚刚征服了新生产方式的已有领域时，却发现，不仅许多别的生产部门采用了真正的工厂制度，而且那些采用或多或少陈旧的生产方式的手工工场（如陶器作坊、玻璃作坊等）以及老式的手工业（如面包房），甚至那些分散的所谓家庭劳动（如制钉业等）[188]，也都象工厂一样早已处于资本主义剥削之下了。因此，立法不得不逐渐去掉它的例外性，或者在象英国这样在立法上仿效罗马决疑法的地方，把有人在里面劳动的任何房屋都任意称为工厂。[189]","language":"中文","translation":false},{"id":"capital-9-208","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":208,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"第二，某些生产部门中规定工作日的历史以及另一些生产部门中还在继续争取这种规定的斗争，清楚地证明：孤立的工人，“自由”出卖劳动力的工人，在资本主义生产的一定成熟阶段上，是无抵抗地屈服的。因此，正常工作日的确立是资本家阶级和工人阶级之间长期的多少隐蔽的内战的产物。斗争是在现代工业范围内开始的，所以它最先发生在现代工业的发源地英国[190]。英国的工厂工人不仅是英国工人阶级的先进战士，而且是整个现代工人阶级的先进战士，最先向资本的理论挑战的也正是他们的理论家[191]。所以，工厂哲学家尤尔咒骂说，英国工人阶级洗不掉的耻辱就是，他们面对勇敢地为“劳动的完全自由”而奋斗的资本，竟把“工厂法的奴隶制”写在自己旗帜上。[192]","language":"中文","translation":false},{"id":"capital-9-209","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":209,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"法国在英国后面慢慢地跟了上来。在那里，十二小时工作日法律[193]曾不得不由二月革命来催生，但是这个法律同它的英国原版比起来更加不完备。虽然如此，法国的革命方法还是显示了它的独特的优点。它一下子就给所有的作坊和工厂毫无区别地规定了同样的工作日界限，而英国立法却时而在这一点上，时而在那一点上被迫向环境的压力屈服，并且极容易制造出一起又一起的诉讼纠纷[194]。另一方面，法国法律作为原则宣布的东西，在英国则只是以儿童、少年和妇女的名义争取的东西，并且这些东西直到最近才作为普遍的权利提了出来。[195]","language":"中文","translation":false},{"id":"capital-9-210","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":210,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"在北美合众国，只要奴隶制使共和国的一部分还处于残废状态，任何独立的工人运动都是瘫痪的。在黑人的劳动打上屈辱烙印的地方，白人的劳动也不能得到解放。但是，从奴隶制的死亡中，立刻萌发出一个重新变得年青的生命。南北战争的第一个果实，就是争取八小时工作日运动，这个运动以特别快车的速度，从大西洋跨到太平洋，从新英格兰跨到加利福尼亚。在巴尔的摩召开的全国工人代表大会【134】（1866年8月）宣布：","language":"中文","translation":false},{"id":"capital-9-211","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":211,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“为了把我国的劳动从资本主义的奴隶制下解放出来，当务之急是颁布一项法律，规定八小时工作日为美利坚联邦各州的正常工作日。我们誓以全力争取这一光荣的结果。”[196]","language":"中文","translation":false},{"id":"capital-9-212","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":212,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"与此同时（1866年9月初），在日内瓦召开的“国际工人代表大会”，根据伦敦总委员会的建议，通过决议：“限制工作日是一个先决条件，没有这个条件，一切进一步谋求工人解放的尝试都将遭到失败…… 我们建议通过立法手续把工作日限制为8小时。”【135】","language":"中文","translation":false},{"id":"capital-9-213","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":213,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"这样，大西洋两岸从生产关系本身中本能地成长起来的工人运动，就证实了英国工厂视察员罗·约·桑德斯的话：","language":"中文","translation":false},{"id":"capital-9-214","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":214,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"“如果不先限制工作日，不严格地强制贯彻工作日的法定界限，要想在社会改革方面采取进一步的措施，是决不可能有任何成功希望的”。[197]","language":"中文","translation":false},{"id":"capital-9-215","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":215,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"必须承认，我们的工人在走出生产过程时同他进入生产过程时是不一样的。在市场上，他作为“劳动力”这种商品的所有者与其他商品的所有者相遇，即作为商品所有者与商品所有者相遇。他把自己的劳动力卖给资本家时所缔结的契约，可以说象白纸黑字一样表明了他可以自由支配自己。在成交以后却发现：他不是“自由的当事人”，他自由出卖自己劳动力的时间，是他被迫出卖劳动力的时间[198]；实际上，他“只要还有一块肉、一根筋、一滴血可供榨取”[199]，吸血鬼就决不罢休。为了“抵御”折磨他们的毒蛇【137】，工人必须把他们的头聚在一起，作为一个阶级来强行争得一项国家法律，一个强有力的社会屏障，使自己不致再通过自愿与资本缔结的契约而把自己和后代卖出去送死和受奴役[200]。从法律上限制工作日的朴素的大宪章【138】，代替了“不可剥夺的人权”这种冠冕堂皇的条目，这个大宪章“终于明确地规定了，工人出卖的时间何时结束，属于工人自己的时间何时开始”。[201]多么大的变化啊！【139】","language":"中文","translation":false},{"id":"capital-9-216","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":216,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[35] “工作日是个不定量，可长可短。”（《论手工业和商业。兼评赋税》1770年伦敦版第73页）","language":"中文","translation":false},{"id":"capital-9-217","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":217,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[36] 这个问题比罗伯特·皮尔爵士向北明翰商会提出的有名的问题“什么是一镑?”不知要重要多少。皮尔提出这样的问题，是因为他和北明翰的“小先令派”【103】一样，不理解货币的本质。","language":"中文","translation":false},{"id":"capital-9-218","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":218,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【103】 小先令派（Little shilling men）或北明翰派，是十九世纪上半叶产生的一个经济学特殊学派。这一学派的追随者宣传关于观念的货币计量单位的理论，并且相应地把货币仅仅看作“计算名称”。北明翰派的代表托马斯·阿特伍德和马提阿斯·阿特伍德两兄弟、斯普纳及其他人提出了一个降低英国货币单位含金量的方案，这一方案被称为“小先令方案”。这一学派的名称就是由此而来。同时，“小先令派”反对政府旨在减少流通中的货币量的措施。他们认为，实施他们的方针就可以通过人为地提髙价格使工业兴旺并保证国家的普遍繁荣。但是，实际上他们提出的使货币贬值的办法，只是为以贬值的货币来清偿国家和私人的债务创造条件，也就是说，给各种贷款的主要获得者即国库和大企业主带来一定的利益。马克思在他的著作《政治经济学批判》中谈到了这一学派（见《马克思恩格斯全集》中文版第13卷第72—73页〉。——第260页。","language":"中文","translation":false},{"id":"capital-9-219","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":219,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[37] “资本家的任务是：靠所支出的资本来取得尽量多的劳动。”（让·古·库尔塞尔-塞纳伊《工商企业、农业企业的理论和实践概论》1857年巴黎第2版第63页）","language":"中文","translation":false},{"id":"capital-9-220","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":220,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[38] “每天损失一个劳动小时，会给一个商业国家造成莫大的损害。”“我国的劳动贫民大量地消费奢侈品；制造业中的平民尤其如此；他们同时还消费自己的时间——这是各种消费中最有害的一种消费。”（《论手工业和商业》1770年伦敦版第47页和第153页）","language":"中文","translation":false},{"id":"capital-9-221","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":221,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[39] “贪婪的吝啬鬼不放心地监视着自由短工，只要他休息一下，就硬说是偷窃了他。”（尼·兰盖《民法论》1767年伦敦版第2卷第466页）","language":"中文","translation":false},{"id":"capital-9-222","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":222,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[40] 1860-1861年，伦敦建筑工人举行大罢工，要求把工作日缩短到9小时，当时他们的委员会发表了一项声明，这项声明同我们这位工人的辩护词几乎完全一样。声明讽刺地指出，一位最贪婪的“建筑业老板”——某个摩·佩托爵士——负有“德高望重的名声”。（这位佩托在1867年以后得到了和施特鲁斯堡一样的结局！）","language":"中文","translation":false},{"id":"capital-9-223","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":223,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[41] “那些劳动的人……实际上既养活自己，也养活那些称为富人的领年金者。”（艾德蒙·伯克《关于贫困的意见和详情》1800年伦敦版第2、3页）","language":"中文","translation":false},{"id":"capital-9-224","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":224,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[42] 尼布尔在他的《罗马史》中非常天真地指出：“象伊特剌斯坎人的这种建筑，虽然仅存遗迹，但仍令人惊异；这样的建筑，毋庸讳言，在小〈！〉国是以奴隶主和奴隶的存在为前提的。”西斯蒙第说得深刻得多：“布鲁塞尔的花边”是以雇主和雇工的存在为前提的。","language":"中文","translation":false},{"id":"capital-9-225","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":225,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[43] “这些不幸者〈在埃及、埃塞俄比亚和阿拉伯之间的金矿中做工的人〉不仅总是肮脏不堪，而且不得不赤身露体，谁看到他们，都不能不同情他们的悲惨命运。在这种地方，对于老弱病残和妇女没有任何的照顾和怜悯。所有的人都在皮鞭的逼迫下不断地做工，直到死亡才结束他们的痛苦和贫困生活。”(狄奥多洛斯(西西里的）《史学丛书》第3卷第13章［第260页］）","language":"中文","translation":false},{"id":"capital-9-226","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":226,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[44] 以下所述，是指罗马尼亚各州在克里木战争后发生政变【89】以前的情形。","language":"中文","translation":false},{"id":"capital-9-227","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":227,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【89】库扎政变——是罗马尼亚历史上的重要事件。1859年1月，著名的社会政治活动家亚历山大鲁·库扎先后被选为莫尔达维亚和瓦拉几亚公国的国君。由于这两个长期隶属于奥斯曼帝国的多瑙河公国的合并，为罗马尼亚国家的统一奠定了基础。库扎执政后，立意实行一系列的资产阶级民主改革。但是他的政策遇到了地主和一部分资产阶级的强烈反抗。在地主代表占优势的国民议会否决了政府提出的土地改革草案后，库扎于1864年实行政变，解散了反动的国民议会，颁布了新宪法，扩大了选民范围，加强了政府权力。在这种新的政治局势下实行的土地改革，规定废除农奴制和通过赎买把土地分给农民。——第191、265页。","language":"中文","translation":false},{"id":"capital-9-228","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":228,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[44a] ｛第3版注：这种情形也适用于德国，特别是易北河以东的普鲁士。在十五世纪，德国的农民虽然几乎都要担负一定的实物贡赋和劳役，但是除此之外，他们至少在事实上是自由的人。勃兰登堡，波美拉尼亚、西里西亚和东普鲁士等地的德国移民，甚至在法律上被认为是自由人。贵族在农民战争中的胜利，结束了这种状况。不但战败的德国南部的农民又沦为农奴，而且从十六世纪中叶以后，东普鲁士、勃兰登堡，波美拉尼亚和西里西亚的自由农民，以及紧跟着还有什列斯维希—霍尔施坦的自由农民也都降到了农奴的地位。（毛勒《德国领主庄园、农户和农户制度史》第4卷。麦岑《一八六六年以前普鲁士国家边陲地带的土地和农业关系》。汉森《什列斯维希—霍尔施坦的农奴制》)——弗·恩·｝","language":"中文","translation":false},{"id":"capital-9-229","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":229,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【104】 “组织规程”（《Reglement organique》）是多瑙河各公国（莫尔达维亚和瓦拉几亚）的第一部宪法。1828—1829年俄土战争结束后，俄军占领了这些公国。这部宪法是由这些公国的俄国行政当局首脑巴·德·基谢廖夫于1831年实施的。根据组织规程，每个公国的立法权交给大土地占有者所选出的议会，而行政权交给土地占有者、僧侣和城市的代表所选出的终身国君。规程巩固了大贵族和上层僧侣的统治地位，保持了原有的封建制度，包括徭役制。农民曾举行许多次起义来回答这部“宪法”。同时，组织规程还规定了一系列资产阶级的改革：废除国内关税，实行贸易自由，司法和行政分立等。——第266页。","language":"中文","translation":false},{"id":"capital-9-230","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":230,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[45] 详见埃·雷尼奥《多瑙河各公国政治社会史》1855年巴黎版［第304页及以下各页］。","language":"中文","translation":false},{"id":"capital-9-231","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":231,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[46] “一般说来，一个生物体超过它的同类的平均长度，这在某种限度内表示这个生物体的强健。如果人的发育由于自然条件或社会条件而受到妨害，人体就会缩小。在欧洲所有实行征兵制的国家里，自从实行这种制度以来，成年男子的平均身长和整个应征条件都降低了。法国在革命(1789年)以前，步兵身长的最低标准是165厘米，1818年(根据3月10日的法令)是157厘米，根据1832年3月21日的法令是156厘米。在法国，应征者平均有一半以上因身长不够和体质孱弱而被淘汰；在萨克森，1780年军人的身长标准是178厘米，目前是155厘米。在普鲁士目前是157厘米。根据1862年5月9日《巴伐利亚报》刊载的迈耶尔博士的报告，普鲁士按9年平均计算，每1000个应征者当中有716人不合格：其中317人因身长不够，399人因体质孱弱……1858年，柏林就没有征足兵额，差156人。”(尤·冯·李比希《化学在农业和生理学中的应用》1862年第7版第1卷第117、118页）","language":"中文","translation":false},{"id":"capital-9-232","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":232,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[47] 关于1850年工厂法的历史，将在本章以后的段落叙述。","language":"中文","translation":false},{"id":"capital-9-233","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":233,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[48] 英国从大工业产生到1845年这段时期，我只在某些地方提到，详细情况，请阅读弗里德里希·恩格斯的《英国工人阶级状况》（1845年莱比锡版)。1845年以后发表的工厂视察员报告、矿山视察员报告等等，都说明了恩格斯对资本主义生产方式的精神了解得多么深刻！把他的著作和过了18—20年以后才发表的童工调査委员会（1863—1867年）的官方报告稍加比较就可以看出，他对工人阶级状况的详细入微的描写是多么令人惊叹。童工调査委员会的报告所谈的恰好是1862年以前尚未实施工厂法的那些工业部门的堉形，其中有些部门直到现在还没有实施工厂法。因此,恩格斯所描写的状况在这些部门内并没有受外因影响而发生多大变化。我所举的例子主要属于1848年以后的自由贸易时期，也就是不学无术而又象孚赫那样吹牛的自由贸易贩子们神话般地向德国人大吹特吹的那个极乐时期。——这里所以把英国摆在首要地位，是因为英国是资本主义生产的典型代表，而且对于我们所研究的问题来说，只有英国才有不断公布的官方统计材料。","language":"中文","translation":false},{"id":"capital-9-234","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":234,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[49] 《工厂视察员莱·霍纳先生的建议》，载于《工厂法》（根据下院决定于1859年8月9日刊印）第4、5页。","language":"中文","translation":false},{"id":"capital-9-235","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":235,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[50] 《工厂视察员报告。截至1856年10月为止的半年》第35页。","language":"中文","translation":false},{"id":"capital-9-236","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":236,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[51] 《工厂视察员报告。1858年4月30日》第9页。","language":"中文","translation":false},{"id":"capital-9-237","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":237,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[52] 同上，第10页。","language":"中文","translation":false},{"id":"capital-9-238","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":238,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[53] 《工厂视察员报告。1858年4月30日》第25页。","language":"中文","translation":false},{"id":"capital-9-239","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":239,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[54] 《工厂视察员报告。截至1861年4月30日为止的半年》。见附录2；《工厂视察员报告。1862年10月31日》第7、52、53页。1863年的下半年违法事件又増多,参看《工厂视察员报告。截至1863年10月31日为止的半年》笫7页。","language":"中文","translation":false},{"id":"capital-9-240","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":240,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[55] 《工厂视察员报告。1860年10月31日》第23页。根据工厂主在法庭上的供述，他们工厂的工人狂热地反对工厂劳动的任何中断，关于这一点，有下列奇闻为证。1836年6月初，杜斯伯里(约克郡)的治安法官接到控告，说巴特里附近有8个大工厂的厂主违反了工厂法。其中有几位先生雇用12—15岁的儿童5人，迫使他们从星期五早晨6点一直劳动到星期六下午4点，除了吃饭和半夜一小时睡眠外，不让有任何休息。这些孩子在那种叫做“再生毛料洞”的小屋里一连劳动30小时，他们在那里把破旧毛织物撕成碎片，洞里弥漫着灰尘和毛屑，连成年工人都要经常用手帕捂着嘴来保护自己的肺！这些被告先生虽然没有发誓(他们这些战栗教徒都是谨小慎微的信教者，是不发誓的)，但是硬说他们怀有怜悯之心，本来允许这些可怜的孩子睡4个小时，但是这些固执的孩子偏偏不肯睡！这几位战栗教徒先生被判处罚金20镑。德莱登对这些战栗教徒颇有先见之明，他写道：","language":"中文","translation":false},{"id":"capital-9-241","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":241,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"不先祈祷一番，不成！”【105】","language":"中文","translation":false},{"id":"capital-9-242","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":242,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【105】 德莱登《公鸡和狐狸》。——第270页。","language":"中文","translation":false},{"id":"capital-9-243","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":243,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[56] 《工厂视察员报告。1856年10月31日》第34页。","language":"中文","translation":false},{"id":"capital-9-244","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":244,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[57] 同上，第35页。","language":"中文","translation":false},{"id":"capital-9-245","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":245,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[58] 同上，第48页。","language":"中文","translation":false},{"id":"capital-9-246","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":246,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[62] 《工厂视察员报告。1860年4月30日》第56页。","language":"中文","translation":false},{"id":"capital-9-247","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":247,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[63] 这个术语无论在工厂或工厂报吿中，都取得了正式的公民权。","language":"中文","translation":false},{"id":"capital-9-248","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":248,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[64] “工厂主贪得无厌，他们追逐利润时的暴虐行为，同西班牙人征服美洲追逐黄金时犯下的暴行相比，有过之而无不及。”（约翰·威德《中等阶级和工人阶级的历史》1835年伦敦第3版第114页）这本书的理论部分，是政治经济学概论的一种,在当时有它独到之处，如对于商业危机的论述就是一例。至于历史部分，则是无耻地从摩·伊登爵士的《贫民的状况》（1797年伦敦版）中抄来的。","language":"中文","translation":false},{"id":"capital-9-249","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":249,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[65] 1860年1月17日的伦敦《每日电讯》。","language":"中文","translation":false},{"id":"capital-9-250","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":250,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【106】 枢密院是英国国王属下的专门机关，由内阁大臣和其他官员以及宗教界的髙级代表所组成。最初成立于十三世纪。在很长的时期内它拥有代表国王而不经过议会进行立法的权力。在十八世纪和十九世纪，枢密院的作用急剧下降。枢密院实际上根本不参与管理现今的英国。——笫273、438、509、718页。","language":"中文","translation":false},{"id":"capital-9-251","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":251,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[66] 参看恩格斯《英国工人阶级状况》第249-251页。【107】","language":"中文","translation":false},{"id":"capital-9-252","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":252,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【107】 见《马克思恩格斯全集》中文版第2卷第492—494页。——第273页。","language":"中文","translation":false},{"id":"capital-9-253","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":253,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[67] 《童工调查委员会。第1号报告。1863年》，证词第16、19、18页。","language":"中文","translation":false},{"id":"capital-9-254","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":254,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[68] 《公共卫生，笫3号报告》第103，105页。","language":"中文","translation":false},{"id":"capital-9-255","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":255,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[69] 《童工调查委员会。1863年》第24、22页和第XI页。","language":"中文","translation":false},{"id":"capital-9-256","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":256,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[70] 同上，第XLVII页。","language":"中文","translation":false},{"id":"capital-9-257","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":257,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[71] 同上，第LIV页。","language":"中文","translation":false},{"id":"capital-9-258","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":258,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[72] 不要把这种时间理解为我们所说的剩余劳动时间。这些先生把10 1/2小时的劳动看作正常工作日，因而其中包含正常的剩余劳动。在此之外是“额外时间”，它的报酬稍高一些。往后我们就会知道，在所谓正常日中使用劳动力，报酬是低于价值的，所以“额外时间”不外是资本家用来榨取更多的“剩余劳动”的诡计；而且，即使对“正常日”中使用的劳动力确实支付了足够的报酬，情况仍然是一样的。","language":"中文","translation":false},{"id":"capital-9-259","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":259,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【108】 又是克里斯平（Ecce iterum Crispinus）——尤维纳利斯的《讽刺诗集》第四篇就是这样开始的，这篇诗（在第一部分中）痛斥罗马皇帝多米齐安的一个宫臣克里斯平。这句话的转义是:“又是这个家伙”或“又是这个东西”。——第276页。","language":"中文","translation":false},{"id":"capital-9-260","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":260,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[73] 《童工调査委员会。1863年》，证词第123、124、125、140页和第LXIV页。","language":"中文","translation":false},{"id":"capital-9-261","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":261,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[74] 把明矾磨成细粉，或与盐混合，这是一种常见的商品，名为“面包素”。","language":"中文","translation":false},{"id":"capital-9-262","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":262,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[75] 大家知道，煤烟是碳的一种髙效形态，可作肥料，资本主义的烟囱扫除业者都是把煤烟卖给英格兰租地农民。1862年，一个英国陪审员审理了这样一件案子：卖者瞒着买者在煤烟中掺了90外的灰尘和沙，这样的煤烟究竟算是“商业上”的“真正的”煤烟呢，还是“法律上”的“掺假的”煤烟。“商业之友”判决说，这是商业上的“真正的”煤烟。于是原告租地农民的官司打输了，并且还要负担诉讼费用。","language":"中文","translation":false},{"id":"capital-9-263","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":263,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【109】 埃利亚派——公元前六世纪末—五世纪古希腊哲学中的唯心主义派别。这一派别的最重要的代表有色诺芬、巴门尼德和芝诺。埃利亚派企图证明，运动和现象的多样性在现实中并不存在，而只存在于想象中。——第278页。","language":"中文","translation":false},{"id":"capital-9-264","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":264,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[76] 法国化学家舍伐利挨在一篇论商品“掺假”的文章中说，他所检査过的600多种商品中，很多商品都有10、20甚至30种掺假的方法。他又说，很多掺假方法他还不知道，而且他知道的也并没有全部列举出来。他指出，糖有6种掺假方法，橄榄油有9种，奶油有10种，盐有12种，牛奶有19种，面包有20种，烧酒有23种，面粉有24种，巧克力有28种，葡萄酒有30种，咖啡有32种，等等。甚至仁慈的上帝也不能逃脱这种命运。见卢阿尔·德·卡尔《论伪造圣物》1856年巴黎版。","language":"中文","translation":false},{"id":"capital-9-265","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":265,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[77] 《就面包工人的申诉向女王陛下内务大臣的报告》1862年伦敦版，以及《第2号报告》1863年伦敦版。","language":"中文","translation":false},{"id":"capital-9-266","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":266,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[78] 《就面包工人的申诉向女王陛下内务大臣的报告》1862年伦敦版，以及《第1号报告》第VI—VII页。","language":"中文","translation":false},{"id":"capital-9-267","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":267,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[79] 《就面包工人的申诉向女王陛下内务大臣的报告》1862年伦敦版，以及《第1号报告》第LXXI页。","language":"中文","translation":false},{"id":"capital-9-268","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":268,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[80] 乔治·里德《面包业的历史》1848年伦敦版第16页。","language":"中文","translation":false},{"id":"capital-9-269","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":269,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[81] 《（第1号）拫告。证词部分》。“卖全价面包的老板”齐斯曼的证词，第108页。","language":"中文","translation":false},{"id":"capital-9-270","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":270,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[82] 乔治·里德《面包业的历史》。在十七世纪末和十八世纪初，打入各种行业的代理商还被官方认为是“社会之害”。例如在索美塞特郡，在治安法官季度法庭开庭期间，大陪审团【110】曾向下院递送一份“呈文”，其中说：“布莱克韦耳商馆中的这些代理商是社会之害，他们危害织布业，必须予以铲除。”（《我们英国羊毛业的诉讼案》1685年伦敦版第6、7页）","language":"中文","translation":false},{"id":"capital-9-271","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":271,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【110】 大陪审团是1933年之前存在于英国的一种陪审团，由郡长从郡中选拔十二到二十三个“善良的和诚实的人”组成。陪审团的职能是对案件进行预先审査，并对是否将被告提交刑事法庭审判的问题作出决定。——第280页。","language":"中文","translation":false},{"id":"capital-9-272","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":272,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[83] 《就面包工人的申诉向女王陛下内务大臣的报告。第1号报告》第VIII页。","language":"中文","translation":false},{"id":"capital-9-273","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":273,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[84] 《1861年爱尔兰面包业委员会的报告》。","language":"中文","translation":false},{"id":"capital-9-274","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":274,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[85] 《1861年爱尔兰面包业委员会的拫告》，","language":"中文","translation":false},{"id":"capital-9-275","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":275,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[86] 1866年1月5日，农业工人在格拉斯哥附近的拉斯威德举行群众大会。（见1866年1月13日《工人辩护士报》）1865年底，在苏格兰的农业工人中首先成立了一个工联，这是一次历史性的亊件。在英格兰最受压迫的一个农业区白金汉郡，雇佣工人于1867年3月举行一次大罢工，要求把周工资从9—10先令提髙到12先令。——（从这些事件可以看出，英国农业无产阶级的运动，自从1830年后他们的强大示威运动遭到镇压，特别是实行新的济贫法以来，虽然遭到了彻底破坏，可是到了六十年代，这个运动又重新抬头，并终于在1872年进入了新的时代。在第二卷我还要回过来谈谈这个问题，并且谈一谈1867年以后发表的关于英国农业工人状况的蓝皮书。第3版补注。）","language":"中文","translation":false},{"id":"capital-9-276","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":276,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[87] 见1866年1月［21日]《雷诺新闻》。这家周报每周都以“耸人听闻的标题”，如《可怕的横祸》，《惊人的慘剧》等等，报道一连串新发生的铁路惨祸。北斯泰福郡铁路线上的一个工人对此议论说：“谁都知道，司机和司炉稍一失神，就会造成严重的后果。天气这么冷，还要拚命延长劳动时间，不让有片刻休息，那又怎能不造成这样的后果呢？我们可以举一个每天都在发生的例子：上星期一，有一个司炉一清早就上工，干了14小时50分钟才下工。他还没有来得及喝口茶，就又被叫去做工了。就这样他一连做工29小时15分钟。这一周的其余几天，他的工作情形是这样：星期三15小时，星期四15小时35分，星期五14.5小时，星期六14小时10分，一周共工作88小时30分。不难设想，当他只得到6个工作日的工资时会感到多么惊异。这个人是个新手，他问什么叫一个工作日，得到的回答是：13个小时算一个工作日，也就是说，78小时算一周。而多做的10小时30分钟又怎么算呢？争吵了很久，最后才给他加了10个便士。”（1866年2月4日《雷诺新闻》）","language":"中文","translation":false},{"id":"capital-9-277","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":277,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[88] 参看弗·恩格斯《英国工人阶级状况》第253、254页。【111】","language":"中文","translation":false},{"id":"capital-9-278","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":278,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【111】 见《马克思恩格斯全集》中文版第2卷第496—498页。——第283页。","language":"中文","translation":false},{"id":"capital-9-279","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":279,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[89] 卫生局的里特比医生当时说：“成年人的寝室至少要有300立方英尺空气而住房至少要有500立方英尺。”伦敦一家医院的主任医生理查逊说：“各种女缝纫工——女时装工、女服装工、普通女裁缝，都有三种灾难，这就是劳动过度，空气不足，营养不够或消化不良。一般说来，这种劳动对于妇女无论如何要比男子更为适宜。这种行业的不幸，特别在首都，是在于它被26个资本家所垄断，这些资本家利用资本所产生的权势，硬要从劳动里实现节约＜他的意思是说：靠浪费劳动力来节约费用＞。在整个女缝纫工阶级中都感受到了资本家的这种权力。如果一个女服装工揽到了一些顾客，那末由于竞争，她必须在家里挤死命地干，才能把顾客维持住，而且她必然要让她的助手同样从事过度的劳动。如果她抢不到生意，或者不能再独立经营下去，她就到一家裁缝店去做工，在那里，活并不轻，但是收入有保障。处于这样的地位，她就变成了纯粹的奴隶，随着社会的动荡而飘泊不定；她时而呆在家里的小房间里挨饿或近乎挨饿；时而又要在一昼夜劳动15、16甚至18小时，而她们劳动的场所空气闷得几乎令人喘不过气来，同时她们吃下的东西，哪怕吃得还不坏，由于缺乏新鲜空气，也消化不了。纯粹由于空气不良而造成的肺病，就是靠这些牺牲者而存在的。”(理查逊医生《劳动与过度劳动》，载于1863年7月18日《社会科学评论》)","language":"中文","translation":false},{"id":"capital-9-280","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":280,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[90] 见1863年6月23日《晨星报》。《泰晤士报》曾利用这件事反对布莱特等人而为美国奴隶主辩护。该报写道：“我们中间很多人认为，只要我们自己是用饥饿的折磨代替皮鞭的抽打，使我们本国的年轻妇女累死，我们就很难有权利用火和剑攻击生来就是奴隶主的家族，他们至少是好好地养活他们的奴隶，并让奴隶进行适度的劳动。”(1863年7月2日《泰晤士报》)托利党的报纸《旗帜报》也同样地申斥纽曼·霍尔牧师说：“他把奴隶主开除教籍，可是却同那些用养一只狗的价钱驱使伦敦公共马车夫和售票员等等每天劳动16小时的正人君子在一起祈祷。”最后，预言家托马斯·卡莱尔先生发言了。关于这位先生，还在1850年我就写过：“天才已经消失，剩下的只是崇拜。”【112】这位卡莱尔先生在一篇简短的寓言中把现代史上的唯一重大事件，美国南北战争，说成是北方的彼得拼命要打破南方保罗的头，因为北方的彼得“逐日”雇用工人，而南方的保罗却“终生”雇用。(《萌芽中的美国伊利亚特》，载于1863年8月《麦克米伦杂志》)这样，托利党同情城市雇佣工人(决不是农村雇佣工人！)的肥皂泡终于破灭了。问题的核心还是奴隶制！","language":"中文","translation":false},{"id":"capital-9-281","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":281,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【112】 马克思指他对托马斯·卡莱尔的《当代评论。（一）当前的时代。（二）模范监狱》一书的书评（见《马克思恩格斯全集》中文版第7卷第300—312页)。——第285页。","language":"中文","translation":false},{"id":"capital-9-282","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":282,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[91] 理查逊医生《劳动与过度劳动》，载于1863年7月18日《社会科学评论》。","language":"中文","translation":false},{"id":"capital-9-283","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":283,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[92] 《童工调査委员会。第3号报告》1864年伦敦版第IV、V、VI页。","language":"中文","translation":false},{"id":"capital-9-284","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":284,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[93] “在斯泰福郡和南威尔士，少女和妇女不但白天而且夜里都在煤矿和焦炭堆上做工。送交议会的拫告经常指出，这种现象是造成尽人皆知的严重弊端的原因。这些妇女同男子一道做工，从衣服上很难区别出来；她们浑身是污泥和煤灰。这种不适于妇女的职业几乎必然使妇女丧失自尊心，因而使她们品行堕落。”（《童工调查委员会。第3号报告》第194号第XXVI页，参看《第4号报告》（1865年）第61号第XIII页）玻璃厂的情况也是如此。","language":"中文","translation":false},{"id":"capital-9-285","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":285,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[94] 有一个雇儿童做夜工的钢厂老扳说：“做夜工的少年在白天也不能睡觉，不能得到必要的体息，他们只好在第二天不停地到处乱跑，看来这是很自然的。”〔《童工调査委员会。第4号报告》第63号第XIII页）一位医生谈到日光对身体的维护和发育的重要性时说道：“日光还直接影响身体的各部组织，使其强健而富有弹性。动物的肌肉缺少适量的光照就会松软，失去弹力，神经也会因缺乏刺激而失去应有的紧张度，各个部分的发育就会受到阻碍……至于儿童，经常有充足的阳光，并且每天有一部分时间受到日光的直接照射，对于他们的健康是特别重要的。日光可以促使食物变成良好的成形血液，并使新形成的纤维组织强固起来。它还可以刺激视觉器官，从而加强大脑各部分的机能。”这一段话摘自伍斯特总医院主任医生威·斯特兰吉先生论述“健康”的著作（1864年）【113】。这位医生在给调査委员怀特先生的信中写道：“我从前在郎卡郡有机会观察过夜工对工厂儿童的影响。和某些雇主通常的说法相反，我肯定认为，这种劳动很快就使孩子的健康受到损害。”（《童工调查委员会。第4号报告》第284号第55页）这类亊物也成为认真争论的对象，这就再好不过地表明，资本主义生产是怎样影响着资本家及其仆从们的“大脑机能”。","language":"中文","translation":false},{"id":"capital-9-286","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":286,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【113】 威·斯特兰吉《健康的七要素》1864年伦敦版第84页（W. Strange.《The Seven Sources of Health》.London, 1864, p.84。——第287页。","language":"中文","translation":false},{"id":"capital-9-287","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":287,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[95] 同上，第57号第XII页。","language":"中文","translation":false},{"id":"capital-9-288","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":288,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[96] 同上，第58号第XII页。","language":"中文","translation":false},{"id":"capital-9-289","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":289,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[97] 《童工调査委员会。第4号报告》（1865年）第58号第XII页。","language":"中文","translation":false},{"id":"capital-9-290","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":290,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[98] 同上，第XIII页。当然，这些“劳动力”的文化程度，必然会象他们和一位调査委员进行下述谈话时表现出来的那样！耶利米·海恩斯，12岁，他说：“4的4倍是8，而4个4是16…… 国王是有一切金钱和黄金的人。我们有个国王，据说他是个女王，他们叫她亚历山得拉公主。据说她嫁给了女王的儿子。公主是男人。”威廉·特纳，12岁，他说：“我不是住在英国。我想，是有这么一个国家，但以前根本不知道。”约翰·莫利斯，14岁，他说：“听说上帝造了世界，又听说所有的人都淹死了，只有一个人活着；听说，这个人是一只小鸟。”威廉·斯密斯，15岁，他说：“上帝造了男人，男人造了女人。”爱德华·泰勒，15岁，他说：“我根本不知道伦敦。”亨利·马特曼，17岁，他说：“我有时到教堂去……他们讲道时提到一个名字，叫耶稣基督，其他的名字我都说不上来了，就连耶稣基督是怎么回事，我也说不上来。他不是被杀死的，而是象平常人那样死去的。他和别人有些不同，因为他有些信教，别人不信。”（《童工调査委员会。第4号报告》（1865年）第74号第XV页）“魔鬼是好人。我不知道他住在哪儿。基督是坏蛋。”“这个女孩（10岁）把God［上帝］念成Dog［狗］，而且不知道女王的名字。”(《童工调査委员会。第5号报告》1866年第55页第278号）在上述金属工厂中实行的制度，在玻璃厂和造纸厂也很盛行。在用机器生产的造纸厂中，除了挑选破布以外，所有其他工序照例都实行夜工。有的地方借助于换班制，通常从星期日晚上起直到下星期六午夜12点止，整个星期当中始终都有夜工。日班毎星期有5天做12小时，有1天做18小时。夜班毎星期有5夜做12小时，有1夜做6小时。有的地方是每班工人一连做24小时，隔一天一换班。其中一班在星期一做6小时，不过到星期六要做18小时以补足24小时。有的地方实行介于这二者之间的制度，例如所有在造纸机上工作的工人，一个星期中每天都做15—16小时。调查委员洛德说：这种制度看来兼有十二小时换班制和二十四小时换班制的一切害处。在这种夜班制度下做工的，有13岁以下的儿童，有18岁以下的少年，还有妇女。在实行十二小时换班制的情况下，有时接班的人没有来，他们就不得不连干两班，干24小时，证人的证词说明，男孩和女孩经常要加班加点，往往是连续干24小时，甚至36小时。从事“连续不断而又单调乏味的”抛光作业的，有12岁的小姑娘，她们整月都是每天工作14小时，“只有两次至多是三次半小时的吃饭时间，此外没有任何正规的休息时间”。有些工厂完全取消了正规的夜工，可是额外劳动却长得可怕，而且“往往是发生在那些最脏最热最单调的工序上”（《童工调査委员会。第4号拫告》1865年第XXXVIII和XXXIX页〉。","language":"中文","translation":false},{"id":"capital-9-291","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":291,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[99] 《童工调査委员会。第4号报告》1865年第79号第XVI页。","language":"中文","translation":false},{"id":"capital-9-292","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":292,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[100] 同上，第80号第XVI和XVII页。","language":"中文","translation":false},{"id":"capital-9-293","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":293,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[101] 《童工调査委员会。第4号报告》1865年第82号第XVII页。","language":"中文","translation":false},{"id":"capital-9-294","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":294,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[102] “在我们这个富于思考的和论辩的时代，假如一个人不能对于任何事物，即使是最坏的最无理的事物说出一些好理由，那他还不是一个高明的人。世界上一切腐败的事物之所以腐败，无不有其好理由。”（黑格尔《哲学全书》，第1部《逻辑》，1840年柏林版第249页）","language":"中文","translation":false},{"id":"capital-9-295","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":295,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[103] 《童工调查委员会。第4号报告》1865年第85号第XVII页。玻璃厂老板先生也有类似的忧虑，他认为规定童工的“正规吃饭时间”是不可能的，因为熔炉由此失散的一定热量是“纯粹的损失”或“浪费”。调查委员怀特对此作了答复。怀特完全不象尤尔、西尼耳等人以及他们的可怜的德国应声虫罗雪尔等人那样，为资本家花费他们的货币时的“节制”、“禁欲”和“节俭”以及他们对人的生命的帖木儿—塔梅尔兰式的“浪费”而大为感动，他回答说：“定出正规的吃饭时间会比现在多浪费一些热量，但是这种浪费同现在各玻璃厂中正在发育的儿童由于没有时间舒舒服服吃顿饭和没有时间进行消化而给王国造成的生命力的浪费相比较，即使折合成货币价值，也是算不了什么的”(同上，第XLV页)。这还是在“进步年”1865年！在制造玻璃瓶和燧石玻璃的工厂中做工的儿童，且不说他们搬运时要费多少气力，他们不停地做工，6小时就得走15—20(英)里路！而劳动往往长达14—15小时！在许多这种玻璃厂，象在莫斯科的纺纱厂那样，盛行六小时换班制。“在从事劳动的一周中，六小时已经是连续得最长的休息时间了。而其中还包括往返工厂、盥洗、穿衣、吃饭所需要的时间。这样一算，实际剩下的休息时间就极少了。如果不牺牲些睡眠时间，那就没有时间游戏和呼吸点新鲜空气，而对于在如此高温下担负如此繁重劳动的儿童来说，睡眠又是绝对不可少的……但是就连短短的睡眠也睡不稳，在夜间他们担心睡过时间，在白天又被外面的喧闹声吵醒。”怀特先生曾列举事实，说明有个少年连续做了36小时工，有些12岁的男孩一直干到夜里2点钟，然后在厂里睡到早晨5点钟(只睡3个小时！)，就又开始白天的工作！总报告起草人特里门希尔和塔夫耐尔说：“男女童工和女工在日班或夜班中所担负的劳动量是惊人的。”(同上，第XLIII页和第XLIV页)可是“异常禁欲”的玻璃业资本家，也许正喝醉了酒，在深夜里东倒西歪地从俱乐部走回家去，一边走一边象个傻瓜似地哼着：“不列颠人永远永远不会当奴隶！”【114】","language":"中文","translation":false},{"id":"capital-9-296","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":296,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【114】 “不列顧人永远永远不会当奴隶！”（《Britons never, never shall be staves!》——英国国歌《统治吧，不列颠》中的一句歌词。——第293页。","language":"中文","translation":false},{"id":"capital-9-297","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":297,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[104] 例如，在英格兰农村，有的地区直到目前为止，工人还常常因为在安息日在自己房前的园圃里干点活，亵渎了安息日，而受到拘禁的处分。但是同一个工人如果在星期日不去金属厂，造纸厂或玻璃厂干活，那末即使是出于宗教的癖性，也要按违反契约论处。如果对于安息日的亵渎是发生在资本的“价值增殖过程”内，正统教徒的议会就充耳不闻了。伦敦鱼店和家禽店的短工,在一份要求废除星期日劳动的呈文（1863年8月）中说，他们在一星期的前6天，每天平均劳动15小时,星期日劳动8—10小时。从这份呈文还可以看出，这种“星期日劳动”正是埃克塞特会堂【115】的饕餮而伪善的贵族所鼓励的。这些如此热心“追求肉体享受”的“圣徒”，是通过他们容忍第三者的过度劳动、贫困和饥饿来表明自己的基督徒精神的。美餐对他们（工人）是非常有害的。","language":"中文","translation":false},{"id":"capital-9-298","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":298,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【115】 埃克塞特会堂是伦敦的一座建筑物，各种宗教团体和慈善团体集会的地方。——第294页。","language":"中文","translation":false},{"id":"capital-9-299","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":299,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[105] “我们在以前的报告中曾提到，许多有经验的工厂主确认，过度的劳动……无疑具有过早地耗尽人的劳动力的危险。”（《童工调査委员会。第4号报告》1865年第64号第XIII页）","language":"中文","translation":false},{"id":"capital-9-300","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":300,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[106] 凯尔恩斯《奴隶劳力》1862年伦敦版第110，111页。","language":"中文","translation":false},{"id":"capital-9-301","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":301,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[107] 约翰·华德《特伦特河畔的斯托克城》1843年伦敦版第42页。","language":"中文","translation":false},{"id":"capital-9-302","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":302,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[108] 1863年4月27日费兰德在下院的演说。","language":"中文","translation":false},{"id":"capital-9-303","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":303,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[109] “工厂主们将吸收和消费这批人。这是棉纺织厂主们的原话。”（同上）","language":"中文","translation":false},{"id":"capital-9-304","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":304,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[110] 1863年4月27日费兰德在下院的演说。尽管维利尔斯有最良好的愿望，但“根据法律”他不得不拒绝工厂主们的要求。可是由于地方贫民管理局的甘愿效劳，这些先生们还是达到了自己的目的。工厂视察员亚·雷德格雷夫先生硬说，这一次，这种“拫据法律”把孤儿和贫民的孩子当作学徒看待的制度，“没有带来以前的弊病”（关于这些“弊病”，参看恩格斯《英国工人阶级状况》)，不过确实在一种情况下，也就是“在那些从苏格兰农业区被送到郎卡郡和柴郡的少女和年轻妇女的身上，这种制度是被滥用了”。工厂主根据这个“制度”同济贫院当局订立了有一定期限的契约。工厂主供给这些儿童衣食住，还给一点补貼。1860年是英国棉纺织业最繁荣的一年，而且工资也髙，因为对工人的需求量特别大，可是这时爱尔兰的人口却减少了，英格兰和苏格兰农业区的人口空前大量地迁往澳洲和美洲了，同时英格兰某些农业区的人口，由于生命力大受摧残以及可利用的人口早已被人肉販子搜罗走而大大减少了。如果注意到这些事实，再来听听雷德格雷夫先生的下面一段话，就会感到奇怪了。他说：“但是这种劳动〈济贫院儿童的劳动〉只有在找不到别的劳动时才有人去找，因为这是一种昂贵的劳动。一个13岁的少年每周的普通工资大约是4先令；但是要供给50个或100个这样的少年的衣食住，再加上医药补助费和一定的监管费，此外再加上少量的补贴，这样毎人每周4先令是不够的。”（《工厂视察员报告。1860年4月30日》第27页）雷德格雷夫先生忘记说明，既然工厂主以每人4先令的费用都无法把50个或100个孩子放在一起养活和监管，那末工人自己又怎能靠自3孩子的4先令工资来做到这一点呢。为了避免从正文中引出错误的结论，在这里我还应当指出，英国棉纺织业自从施行1850年工厂法，因而对劳动时间等进行调整以后，已应看作是英国的模范工业。英国棉纺织工人的处境，从各方面来说都比大陆上的命运相同的伙伴好些。“普鲁士的工厂工人每星期至少比他们的英国对手多劳动10小时，而如果他们是在自己家里用自己的织机工作，那末连这个逍加劳动时间的界限也要突破了。”（《工厂视察员报告。1855 年10月31日》第103页）上面提到的1工厂视察员雷德格雷夫，在1851年工业博览会以后，曾到大陆上，特别是到法国和普鲁士调查工厂状况。关于普鲁士的工厂工人，他说，“他们得到的工资仅够购买简单的食品和少量他们习惯用的生活舒适品……与他们的英国对手相比，他们生活更苦，劳动更重”（《工厂视察员报告。1853年10月31日》第85页）。","language":"中文","translation":false},{"id":"capital-9-305","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":305,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[111] “从事过度劳动的人死得惊人地快！但死者的空位，马上又有人补充上，人物频頻更换，但舞台上并不因而发生任何变化。”（《英国和美国》1833年伦敦版第1卷第55页；爱·吉·威克菲尔德著）","language":"中文","translation":false},{"id":"capital-9-306","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":306,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[112] 见《公共卫生。枢密院卫生视察员第6号报告。1863年》1864年伦敦版。这个报告特别谈到农业工人。“人们认为萨特伦德郡是一个有很大改进的郡，但最近的调查发现，在这个曾经以出美男子和勇敢士兵而闻名的地方，居民已退化成瘦弱的种族了，尽管这个地区背山临海，环境极其有益于健康，但儿童的面容异常消瘦苍白，竟同在伦敦小巷的污秽空气中才能遇到的那种面容一样。”（桑顿《人口过剩及其补救办法》1846年伦敦版第74、75页）他们实际上同那些和娼妓、小偷挤住在格拉斯哥的小街陋巷的3万个“英武的山地居民”相似。","language":"中文","translation":false},{"id":"capital-9-307","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":307,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【116】 我死后哪怕洪水滔天！（Apres moi le deluge！)——据说这句话是法国国王路易十五回答他的亲信们的谏告时说的，他们劝他不要经常大办酒宴和举行节庆，认为这会使国债剧增，危及国家。——第299页。","language":"中文","translation":false},{"id":"capital-9-308","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":308,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[113] “尽管居民的健康是国民资本的一个重要成分，但恐怕必须承认，资本家根本不想保持和珍惜这个财富……工厂主关心工人的健康状况是被迫的。”（《泰晤士报》1861年11月5日）“西莱丁的男人成了人类的织工……工人的健康被断送了，再过几代这个种族就会退化下去，但发生了反作用。儿童劳动的时间受到了限制……”（《中央注册局局长第22号年度报告》1861年）","language":"中文","translation":false},{"id":"capital-9-309","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":309,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【117】 歌德《给祖莱卡》。——第300页。","language":"中文","translation":false},{"id":"capital-9-310","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":310,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[114] 例如，我们看到，1863年初，在斯泰福郡拥有大规模陶器厂的26家公司，其中包括约·威季伍德父子公司，提出呈文，请求“国家进行强制干涉”。他们说，同“别的资本家的竞争”使他们不能“自愿地”限制儿童的劳动时间等等。“因此，虽然我们对上述弊病深恶痛绝，但依靠工厂主之间的某种协议是不可能制止这种弊病的……鉴于所有这些情况，我们确信，制定一种强制的法律是必要的。”(《童工调查委员会。第1号报告》1863年第322页)","language":"中文","translation":false},{"id":"capital-9-311","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":311,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"注[114]的补充：最近有一个更突出的例子。在热病式的繁荣时期，棉价很高，于是布莱克本的棉织业主们达成协议，在一定时期内缩短自己工厂的劳动时间。这个期限大约到十一月底(1871年)为止。然而兼营纺和织的富裕厂主利用这个协议所造成的生产缩减的机会，扩大自己的营业，从而靠牺牲小厂主获得了大量利润。这些小厂主迫于困难就向工厂工人呼吁，要他们大力鼓吹九小时工作日，并答应为此给以资助！","language":"中文","translation":false},{"id":"capital-9-312","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":312,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[115] 在英国，这些劳工法（在法国、尼德兰等国同时也有这种法令）是在1813年，在生产关系早已使它们失效以后，才正式废除的。","language":"中文","translation":false},{"id":"capital-9-313","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":313,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【118】 “为了一碗红豆汤出卖自己的长子继承权”——出自圣经的一个故事，现已成为日常惯用的借喻语。据传说，饥饿的以扫正是用这一代价把自己的长子继承权卖给了自己的弟弟雅各。——第301页。","language":"中文","translation":false},{"id":"capital-9-314","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":314,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[116] “12岁以下的儿童在工厂中每天不得劳动10小时以上。”(《马萨诸塞州普通法》第60章第3节。这些法令是1836—1858年颁布的。）“在所有棉纺织厂、毛织厂、丝织厂、造纸厂、玻璃厂、亚麻厂或铁工厂和其他金属加工厂实行的每天10小时劳动，应视为法定的日劳动量。又规定，对于不论在任何工厂做工的未成年人，今后皆不得鼓励或强迫他们每天劳动10小时以上，或每周劳动60小时以上；其次，本州任何工厂今后皆不得雇用10岁以下的未成年人当工人。”（《新泽西州。限制工作日的长度的法令》第1、2节。1851年3月18日法令）“12岁至15岁的未成年人，不论在任何工厂，每天不得劳动11小时以上，并且不得在早晨5点以前和晚上7点半以后做工。”(《罗得岛州修订条例》第139章第23节。1857年7月1日）","language":"中文","translation":false},{"id":"capital-9-315","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":315,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【119】 鼠疫猖獗——1347年至1350年西欧鼠疫流行。根据现有资料，当时死于鼠疫的约有二千五百万人，占西欧总人口的四分之一。——第301、770页。","language":"中文","translation":false},{"id":"capital-9-316","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":316,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[117] ［约·巴·拜耳斯］《自由贸易的诡辩》1850年伦敦第7版第205页。这位托利党人还承认：“议会通过的不利于工人而有利于雇主的调整工资的法令，维持了464年之久。人口增长了，这些法令现在已经成为多余，成为累赘了。”（同上，第206页）","language":"中文","translation":false},{"id":"capital-9-317","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":317,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[118] 关于这项法令，约·威德公正地指出：“从1496年的法令可以看出，当时的伙食费等于手工业者收入的1/3，等于农业工人收入的1/2。这说明，当时的工人比现在的工人有更大的独立性，因为现在农业工人和工场手工业工人的伙食费在他们工资中所占的比重大得多了。”（约·威德《中等阶级和工人阶级的历史》第24、25、577页)有人认为，这种差别是由于现在的食品和衣服的比价和那时的比价不同造成的，但只要略为看一下弗利特伍德主教的《行情表》（1707年伦敦第1版及1745年伦敦第2版），这种意见就不攻自破了。","language":"中文","translation":false},{"id":"capital-9-318","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":318,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[119] 威·配第《爱尔兰政治剖视，1672年》1691年版第10页80。","language":"中文","translation":false},{"id":"capital-9-319","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":319,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[120] 《论促进机械工业发展的必要性》1690年伦较版第13页。为了讨好辉格党和资产阶级，马考莱伪造了英国历史，他宣称：“让儿童过早地从事劳动的做法，在十七世纪十分盛行，这从当时的工业状况来看几乎令人难以置信。在毛织业的中心诺里奇，6岁的儿童就被看作是有劳动能力的。当时有许多著作家，其中包括有些被认为是心地非常正直的著作家，曾以‘惊喜若狂’的心情谈到，单是在这座城市，男女童工一年所创造的财富就比他们的生活费要多12 000镑。我们对过去的历史研究得越仔细，就越有理由驳斥那种认为我们时代充满了新的社会弊病的见解。新东西不过是发现这些弊病的智慧和医治这些弊病的人道精神”(《英国史》第1卷第417页〉。马考莱本来还可以告诉我们：十七世纪的“心地非常正直”的商业之友，曾以“惊喜若狂”的心情叙述荷兰的一所济贫院曾怎样雇用一个4岁的儿童做工，而且这种“应用于实际的道德”的例子，直到亚·斯密时代为止，在一切马考莱式人道主义者的著作中都有过。诚然，随着那种和手工业有区别的工场手工业的出现，剥削儿童的踪迹也就显现出来了。这种剥削在一定程度上从来就存在于农民中间，并且农民身上的枷锁越沉重，这种剥削就越厉害。资本的趋势是很明显的，但事实本身却象双头婴儿一样，是极为罕见的。因此，富于预感的“商业之发”就以“惊喜若狂”的心情把这些事实当作特别值得重视、值得惊异的事情记录下来，以垂教同时代的和后代的人们，并让他们去摹仿。这位喜欢献媚和爱说漂亮话的苏格兰人马考莱还说：“我们现在听到的只是退步，但看到的只是进步。”这是什么眼睛，尤其是，这是什么耳朵！","language":"中文","translation":false},{"id":"capital-9-320","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":320,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[121] 非难工人最凶的就是本文提到的《论手工业和商业》（1770年伦敦版)的匿名作者。他早在《论赋税》（1765年伦敦版）一书中就进行了这样的非难。站在这一方的， 还有妙不可言的饶舌统计家普隆涅斯-阿瑟·杨格。为工人辩护的，最出色的当推：杰科布·范德林特《货币万能》（1734年伦敦版）；神学博士纳萨涅尔·福斯特牧师《论当前粮价昂贵的原因》（1767年伦敦版）；普莱斯博士，特别是波斯耳思威特（对自己的《工商业大辞典》一书的增补以及他的《阐明并增进大不列颠商业利益》1759年伦敦第2版）。至于事实本身，当时的许多别的著作家都是确认的，例如约瑟亚·塔克尔就是如此。","language":"中文","translation":false},{"id":"capital-9-321","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":321,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[122] 波斯耳思威特《工商业大辞典》，《第一篇绪论》第14页。","language":"中文","translation":false},{"id":"capital-9-322","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":322,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[123] 《论手工业和商业》。他自己在第96页上就说明，还在1770年，英国农业工人的“幸福”已经成了什么样子。“他们的劳动力总是紧张到极点；他们的生活坏得不能再坏，他们的劳动重得不能再重。”","language":"中文","translation":false},{"id":"capital-9-323","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":323,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[124] 新教几乎把所有传统的假日都变成了工作日，光是这一点，它在资本的产生上就起了重要的作用。","language":"中文","translation":false},{"id":"capital-9-324","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":324,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[125] 《论手工业和商业》第41、15、96、97、55、56、57页。","language":"中文","translation":false},{"id":"capital-9-325","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":325,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[126] 同上，第69页。早在1734年，杰科布·范德林特就说过，资本家抱怨工人懒惰，其秘密不过在于，他们想用同样的工资使4个工作日变成6个工作日。","language":"中文","translation":false},{"id":"capital-9-326","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":326,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[127] 同上，第242、243页，“这种理想的习艺所应当成为‘恐怖之所’，而不应当成为贫民收容所，让他们在那里吃得炮，穿得好，而只做极少的工作。”","language":"中文","translation":false},{"id":"capital-9-327","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":327,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[128] 同上,［第260页］，他说：“法国人嘲笑我们的狂热的自由思想。”（同上，第78页）","language":"中文","translation":false},{"id":"capital-9-328","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":328,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[129] “他们所以特别反对每天工作12小时以上，是因为规定这种工时的法令是共和国立法留给他们的唯一福利。”（《工厂视察员报告。1855年10月31日》第80页）法国1850年9月5日的十二小时工作日法令是临时政府1848年3月2日法令的资产阶级化的翻版；这个法令适用于一切作坊。在这项法令颁布以前，法国的工作日是不受限制的。工厂的工作日长达14－15小时或者还要多些。见布朗基先生的《1848年法国的工人阶级》这位布郎基先生是经济学家，而不是那位革命家，他曾受政府的委托调査过工人的状况。","language":"中文","translation":false},{"id":"capital-9-329","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":329,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[130] 比利时在调整工作日方面也显示出是一个资产阶级的模范国家。英国驻布鲁塞尔的全权大使霍华德·德·华尔登勋爵，1862年5月12日向外交部报告说：“罗日埃大臣对我说，无论是普遍的法令还是地方性的调整，都没有使儿童劳动受到什么限制；近3年来，政府在每次会议上都想向两院提出关于这个问题的法案，但总是遇到无法克服的障碍，因为人们猜忌不安，唯恐出现一种同劳动完全自由的原则相抵触的法令！”","language":"中文","translation":false},{"id":"capital-9-330","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":330,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[131] “无论哪一阶级的人，如果每天必须劳作12小时，那确实是十分令人遗憾的事情。如果把吃饭和往返工厂的时间都计算在内，实际上这就在一夭24小时中占去14小时……我想，即使不谈健康问题，单从道德观点来看，谁也不会否认，从13岁这么小的年龄开始（而在“自由的”工业部门甚至是从更小的年龄开始〉，就不断地把劳动阶级的时间全部侵吞，这是非常有害的，是一种可怕的弊端……为了公共道德，为了培育出健壮的居民，为了使广大人民能有合理的生活享受，应当坚决要求在一切营业部门中把每个工作日的一部分留出来作为休息和余暇时间。”（莱昂纳德·霍纳《工厂视察员报告。1841年12月31日》）","language":"中文","translation":false},{"id":"capital-9-331","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":331,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[132] 见《1860年1月庭期安特里姆州拜尔法斯特法庭庭长约·亨·奥特韦先生的判决》。 ^","language":"中文","translation":false},{"id":"capital-9-332","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":332,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[133] 很能说明路易-菲力浦这个资产者国王的制度的特点的是，他在位时颁布的唯一的工厂法（1841年3月22日）从来就没有兑现过。而且这个法令也只是涉及到儿童劳动。它规定8—12岁的儿童劳动8小时，12—16岁的儿童劳动12小时，等等，并且还附有许多例外，以至竟准许8岁的儿童做夜工。在一个连每只老鼠都要受警察监视的国家里，却把对这项法令的监督和推行寄托在“商业之友”的善良愿望上。只是从1853年起，才仅仅在诺尔省设置了一个领薪水的政府视察员。同样能很好说明法国社会一般发展的特点的是，路易-菲力浦的法令在1848年革命前竟是拥有各种各样法律的法国立法工厂中独一无二的工厂法！","language":"中文","translation":false},{"id":"capital-9-333","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":333,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[134] 《工厂视察员报告。1860年4月30日》第50页。","language":"中文","translation":false},{"id":"capital-9-334","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":334,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【120】 《工厂调査委员会。皇家委员会中央评议会的第1号报告》，根据下院决定于1833年6月28日刊印，第53页（《Factories Inquiry Commission. First Report of the Central Board of His Majesty's Commissioners. Ordered, by the House of Commons, to be printed, 28 June 1833》, p.53）。——第309页。","language":"中文","translation":false},{"id":"capital-9-335","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":335,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【121】 “危险在于迟缓”（Periculum in mora）——引自罗马历史学家梯特·李维《罗马建城以来的历史》（《Ab urbe condita》）——第38卷第25章第13节。——第310页。","language":"中文","translation":false},{"id":"capital-9-336","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":336,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[135] 《Legislation is equally necessary for the prevention of death, in any form in which it can be prematurely inflicted, and certainly this must be viewed as a most cruel mode of inflicting it.》【122】","language":"中文","translation":false},{"id":"capital-9-337","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":337,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【122】 《联合王国儿童劳动调整法案委员会的报告。附证词》，根据下院决定于1832年8月8日刊印（《Report from the Committee on the 《Bill to regulate the labour of Children in the Mills and Factories of theUnited Kingdom》: with the Minutes of Evidence》. Ordered, by the House of Commons, to be printed, 8 August 1832）。——第310页。","language":"中文","translation":false},{"id":"capital-9-338","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":338,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【123】 札格纳特是印度的大神之一毗湿奴的化身。崇拜札格纳特的教派的特点是宗教仪式上的十分豪华和极端的宗教狂热，这种狂热表现为教徒的自我折磨和自我残害。在举行大祭的日子里，某些教徒投身于载着毗湿奴神像的车轮下让它轧死。——第311，708页。","language":"中文","translation":false},{"id":"capital-9-339","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":339,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[136] 《工厂视察员报告。1849年10月31日》第6页。","language":"中文","translation":false},{"id":"capital-9-340","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":340,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【124】 指包括了宪章派各项要求的人民宪章，它是1838年5月8日作为准备提交议会的一项法律草案公布的。宪章包括六点：普选权（年满二十一岁的男子)、议会每年改选一次、秘密投票、各选区一律平等、取消议会议员候选人的财产资格限制、发给议员薪金，——笫312页。","language":"中文","translation":false},{"id":"capital-9-341","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":341,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【125】 反谷物法同盟（见注10）拥护者通过蛊惑性的宣传要工人们相信，随着贸易自由的实行，他们的实际工资将要提髙，工人们将得到比从前大一倍的大圆面包（《big loaf》）。而且，他们还拿着两个写着有关字句的面包——一个大的和一个小的——在街上形象地进行鼓动。现实生活揭穿了这些诺言的全部欺骗性。由于谷物法的废除而得到巩固的英国工业资本加紧对工人阶级的切身利益的进攻。——第312、499页。","language":"中文","translation":false},{"id":"capital-9-342","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":342,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[137] 《工厂视察员报告。1848年10月31日》第98页。","language":"中文","translation":false},{"id":"capital-9-343","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":343,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[138] 莱昂纳德·霍纳还正式使用了 “可耻行为”一语（《工厂视察员报告。1859 年10月31日》第7页）。","language":"中文","translation":false},{"id":"capital-9-344","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":344,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[139] 《工厂视察员报告。1844年9月30日》第15页。","language":"中文","translation":false},{"id":"capital-9-345","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":345,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[140] 法令允许使用儿童劳动10小时，只要他们不是天天做工，而是隔一天做一天工。总的说来，后面这项附带条款始终没有发生过效力。","language":"中文","translation":false},{"id":"capital-9-346","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":346,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[141] “由于他们的劳动时间的缩短会引起雇用人数〈儿童数〉的增加，有人就认为，这种增长了的需求可由8—9岁的儿童的追加供给来满足。”（《工厂视察员报告。1844年9月30日》第13页）","language":"中文","translation":false},{"id":"capital-9-347","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":347,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[142] 《工厂视察员报告。1848年10月31日》第16页。","language":"中文","translation":false},{"id":"capital-9-348","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":348,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[143] “我发现，每周领取10先令的人因为工资普遍减少而少得1先令, 又因为工作时间缩短而少得1先令6便士，总共少得2先令6便士，尽管如此，大多数人还是坚决拥护十小时工作日法案。”（同上）","language":"中文","translation":false},{"id":"capital-9-349","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":349,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[144] “当我在请愿书上签名的时候，我就说我做了一件坏事。——那你为什么要签名呢？-一因为拒绝签名就会被开除。——请愿者觉得自己确实‘受压迫’，但不是受工厂法的压迫。”（同上，第102页）","language":"中文","translation":false},{"id":"capital-9-350","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":350,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【126】 国民公会委员——十八世纪末法国资产阶级革命时期，国民公会（1792—1795年法兰西共和国国民议会）在各省和军队中派驻拥有特许全权的代表。国民公会委员就是对这些代表的称呼。——第315页。","language":"中文","translation":false},{"id":"capital-9-351","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":351,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[145] 《工厂视察员报告。1848年10月31日》第17页。在霍纳先生的管区，曾询问了181个工厂的10 270个成年男工。他们的证词都载于截至1848年10月为止的半年工厂视察报告的附录中。这种询问在其他方面也提供了宝贵的材料。","language":"中文","translation":false},{"id":"capital-9-352","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":352,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[146] 同上。见《附录》中列举的莱昂纳德·霍纳本人收集的第69、70、71、72、92、93号证词，以及他的助手亚·收集的第51、52、58、59、62、70号证词。有一个工厂主自己讲出了全部真相。见该报告第265号以后的第14号。","language":"中文","translation":false},{"id":"capital-9-353","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":353,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【127】 嫌疑犯处治法（loi des suspects）是1858年2月19日在法国由立法团通过的一项法律。该法律授予法皇及其政府以无限的权力，可以把—切敌视第二帝国制度的嫌疑分子流放到法国和阿尔及利亚各地去，或者驱逐出一切法国领土。——第316页。","language":"中文","translation":false},{"id":"capital-9-354","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":354,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[147] 《工厂视察员报告。1848年10月31日》第133、134页。","language":"中文","translation":false},{"id":"capital-9-355","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":355,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[148] 《工厂视察员报告。1848年4月30日》第47页。","language":"中文","translation":false},{"id":"capital-9-356","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":356,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[149] 《工厂视察员报告。1848年10月31日》第130页。","language":"中文","translation":false},{"id":"capital-9-357","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":357,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[150] 同上，第142页。","language":"中文","translation":false},{"id":"capital-9-358","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":358,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[151] 《工厂视察员报告。1850年10月31日》第5、6页。","language":"中文","translation":false},{"id":"capital-9-359","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":359,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[152] 资本无论在其发达的形式上或不发达的形式上，性质都是一样的。在美国南北战争爆发前不久，由于奴隶主的影响，有一项法典被强加在新墨西哥的领土上了，其中写道：只要资本家购买了工人的劳动力，工人就“成为他的〈资本家的〉货币”。在罗马的贵族中也流行过这种看法。他们借给平民债务人的钱，先变成债务人的生活资料，然后变成债务人的血和肉。因此，这种“血和肉”是“他们的货币”。由此就产生了夏洛克式的十表法【129】！兰盖关于贵族债权人时常在台伯河彼岸用煮熟了的债务人的肉来大张筵席的臆说【130】，和道梅尔关于基督教圣餐的臆说【131】—样，始终是未解之谜。","language":"中文","translation":false},{"id":"capital-9-360","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":360,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【128】 莎士比亚《威尼斯商人》第四幕第一场。——第318、319页。","language":"中文","translation":false},{"id":"capital-9-361","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":361,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【129】 十表法是罗马奴隶制国家最古老的立法文献“十二铜表法”的最初的方案。这一法律维护私有制，它规定凡无法偿还债务者应被剥夺自由，降为奴隶或碎尸分身。——第319页。","language":"中文","translation":false},{"id":"capital-9-362","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":362,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【130】 这一臆说，见法国历史学家兰盖的著作《民法论，或社会的基本原理》1767年伦敦版第2卷第5册第20章（《Theorie des loix civiles, ou Principes fondamentaux de la societe》, Tome II, Londres, 1767, livre V, chapitre XX）。——第319页。","language":"中文","translation":false},{"id":"capital-9-363","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":363,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【131】 德国哲学家道梅尔在他的著作《基督教古代的秘密》（《Die Geheimnisse des christlichen Alterthums》）中证明，最初的基督徒在圣餐时吃人肉。——第319页。","language":"中文","translation":false},{"id":"capital-9-364","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":364,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[153] 《工厂视察员报告。1848年10月31日》第133页。","language":"中文","translation":false},{"id":"capital-9-365","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":365,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[154] 例如，慈善家艾释华特在写给莱昂纳德·霍纳的一封战栗教徒式的令人作呕的信中，就是这样说的。（《工厂视察员报告。1849年4月》第4页）","language":"中文","translation":false},{"id":"capital-9-366","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":366,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[155] 《工厂视察员报告。1848年10月31日》第138页。","language":"中文","translation":false},{"id":"capital-9-367","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":367,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[156] 同上，第140页。","language":"中文","translation":false},{"id":"capital-9-368","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":368,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[157] 这些“郡治安法官”，即被威·科贝特称为“伟大的不领薪水的人”，是由各郡绅士组成的不领薪水的治安法官。事实上，他们形成统治阶级的世袭法庭。","language":"中文","translation":false},{"id":"capital-9-369","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":369,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[158] 《工厂视察员报告。1849年4月30日》第21、22页。参看该报告第4、5 页上类似的例子。","language":"中文","translation":false},{"id":"capital-9-370","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":370,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[159] 根据威廉四世元年和二年法令，即叫做约翰·霍布豪斯爵士工厂法的第二十九章第十节，在与工厂法有关的问题上，棉纺织厂厂主及其父子兄弟一律不得担任抬安法官的职务。","language":"中文","translation":false},{"id":"capital-9-371","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":371,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[160] 《工厂视察员报告。1849年4月30日》［第22页］。","language":"中文","translation":false},{"id":"capital-9-372","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":372,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[161] 《工厂视察员报告，1849年4月30日》第5页。","language":"中文","translation":false},{"id":"capital-9-373","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":373,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[162] 《工厂视察员报告。1849年10月31日》第6页。","language":"中文","translation":false},{"id":"capital-9-374","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":374,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[163] 《工厂视察员报告。1849年4月30日》第21页。","language":"中文","translation":false},{"id":"capital-9-375","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":375,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[164] 《工厂视察员报告。1848年10月31日》第95页。","language":"中文","translation":false},{"id":"capital-9-376","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":376,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【132】 伟大的法国空想社会主义者傅立叶描绘了一幅未来社会的图景，在这个社会里，人在一个工作日里从事几种劳动，也就是说，工作日将由若干“短时工作”（《courtes seances》）组成，每一项工作不超过一个半至两个小时。根据傅立叶的意见，这样劳动生产率就会大大提高，连最贫穷的劳动者也能够比从前的任何资本家更充分地满足自己的一切需要。——第322页。","language":"中文","translation":false},{"id":"capital-9-377","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":377,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[165] 见《工厂视察员报告。1849年4月30日》第6页，以及工厂视察员豪威耳和桑德斯在《工厂视察员报告。1848年10月31日》中对“换班制度”的详细剖析。还可参看埃士顿市及其附近地区的牧师于1849年春为反对“换班制度”而向女王［维多利亚］呈交的请愿书。","language":"中文","translation":false},{"id":"capital-9-378","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":378,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[166] 例如可参看罗·海·格莱格《工厂问题和十小时工作日法案》1837年版。","language":"中文","translation":false},{"id":"capital-9-379","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":379,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[167] 弗·恩格斯《英国的十小时工作日法案》(载于我主编的《新莱茵报。政治经济评论》1850年4月号笫13页【133】）。在美国南北战争时期，这所“髙等”法院又发现，由于语义含糊，取缔海盗船只武装的法律竟成了正好相反的东西。","language":"中文","translation":false},{"id":"capital-9-380","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":380,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【133】 见《马克思恩格斯全集》中文版第7卷第284页。——第323页。","language":"中文","translation":false},{"id":"capital-9-381","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":381,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[168] 《工厂视察员报告。1850年4月30日》。","language":"中文","translation":false},{"id":"capital-9-382","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":382,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[169] 在冬季，这段时间可以改为早晨7点至晚上7点。","language":"中文","translation":false},{"id":"capital-9-383","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":383,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[170] “现行法律〈1850年〉是一种妥协，其结果是工人放弃了十小时工作日法令的利益，而得到的好处是，凡在劳动时间上受到限制的人都能同时上工和下工。”（《工厂视察员报告。1852年4月30日》第14页）","language":"中文","translation":false},{"id":"capital-9-384","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":384,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[171] 《工厂视察员报告。1844年9月30日》第13页。","language":"中文","translation":false},{"id":"capital-9-385","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":385,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[173] 《工厂视察员报告。1846年10月31日》第20页。","language":"中文","translation":false},{"id":"capital-9-386","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":386,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[174] 《工厂视察员报告。1861年10月31日》第26页。","language":"中文","translation":false},{"id":"capital-9-387","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":387,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[175] 《工厂视察员报告。1861年10月31日》第27页，一般说来，工厂法影响所及的劳动居民的体格都大大增强了。医生的所有证词在这一点上都是一致的，我根据自己在各个不同时期的亲身观察，也确信这一点。尽管如此，并且即使撇开初生婴儿的惊人的死亡率不说，袼林豪医生的正式报告还是表明，同“具有正常健康状况的农业区”相比，工厂区的健康状况是不良的，我引用他1861年报告中的下列统计表作为证明：","language":"中文","translation":false},{"id":"capital-9-388","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":388,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"肺病的人数地区名称每10万个","language":"中文","translation":false},{"id":"capital-9-389","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":389,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"业类别14.9598威根64418.0棉业42.6708布莱克本73434.9同上37.3547哈里法克斯56420.4毛业41.9611布莱得弗德60330.0同上31.0691麦克尔士菲尔德80426.0丝业14.9588利克70517.2同上36.6721特伦特河畔的斯托克66519.3瓦器业30.4726沃尔斯坦登72713.9同上―3058个健康的农业区340―","language":"中文","translation":false},{"id":"capital-9-390","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":390,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[176] 大家知道，英国的“自由贸易派”曾多么不愿意放弃丝织业的保护关税。现在限制法国进口的保护关税是取消了，取而代之的却是英国的工厂儿童也不加保护了。","language":"中文","translation":false},{"id":"capital-9-391","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":391,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[177] 《工厂视察员报告。1853年4月30日》第30页。","language":"中文","translation":false},{"id":"capital-9-392","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":392,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[178] 在1859年和1860年英国棉纺织业的鼎盛时期，有些工厂主企图以额外时间付高工资为诱饵，促使成年男纺工等延长工作日。使用手摇骡机和自动纺机的纺工向雇主提出意见书，这才打消了这种尝试。意见书中写道：“坦白地说，我们的生活对我们来说已成为一种负担。只要我们每周被关在工厂中的时间仍比别的工人几乎多两天<20小时>，我们就觉得自己好象是国内的奴隶，并且我们责备自己竟容忍一种对我们自己的和我们后代的身心有害的制度长期存在下去……所以，我们郑重通知，从新年起，我们每周劳动将决不多于60小时，从6点至6点，其中还包括法定的1 1/2小时的休息时间。”(《工厂视察员报告。1860年4月30日》第30页)","language":"中文","translation":false},{"id":"capital-9-393","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":393,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[179] 关于利用这个法律的词句来破坏法律的手法，参看议会报告《工厂法》（1859年8月9日），以及该报告所载莱昂纳德·霍纳《关于修改工厂法以使工厂视察员能够制止目前盛行的非法劳动的建议》。","language":"中文","translation":false},{"id":"capital-9-394","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":394,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[180] “最近半年〈1857年〉在我的管区内，8岁和8岁以上的儿童亊实上是从早晨6点一直被折磨到晚上9点。”（《工厂视察员报告。1857年10月31日》第39页）","language":"中文","translation":false},{"id":"capital-9-395","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":395,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[181] “印染工厂法关于教育以及劳动保护的规定被认为是一种失败。”（《工厂视察员报告。1862年10月31日》第52页）","language":"中文","translation":false},{"id":"capital-9-396","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":396,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[182] 例如，艾·波特尔1863年3月24日写给《泰晤士报》的一封信中就是这样说的。《泰晤士报》提醒他不要忘记反对十小时工作日法令的工厂主叛乱。","language":"中文","translation":false},{"id":"capital-9-397","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":397,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[183] 同图克一起编写并出版《价格史》的威·纽马奇先生就是这样认为的。难道怯懦地向舆论让步也是科学上的进步么？","language":"中文","translation":false},{"id":"capital-9-398","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":398,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[184] 1860年颁布的关于漂白厂和染厂的法令规定，从1861年8月1日起，工作日暂时缩短为12小时，从1862年8月1日起，最后缩短为10小时，也就是说，平日为10 1/2小时，星期六为7 1/2小时。但是不祥的1862年一到来，旧把戏又重演了。工厂主先生们向议会请愿，要求把准许少年和妇女劳动12小时的规定仅仅再延长一年…… “在现今的营业状况下〈棉荒时期〉，如果允许工人每天劳动12小时，赚得尽可能多的工资，那对他们将是十分有利的…… 一项根据这种精神拟定的法案也已经提交下院，由于苏格兰漂白厂工人的鼓动，这项法案被撤销了。”（《工厂视察员报告。1862年10月31日》第14、15页）盗用工人名义说话的资本遭到工人回击后，又借助法学家的眼镜发现，1860年的法令和议会的一切有关“劳动保护”的法令一样，措词含糊，从中能找到这样的借口：该法令的有效范围不包括“轧光工”和“整理工”。英国的审判权始终是资本的忠实奴仆，它通过“普通法法院”批准了这种强词夺理的解释。“这引起工人极大的不满，并且深为遗憾的是，立法的明确意图，竟由于字义不明而化为泡影。”（《工厂视察员报告。1862年10月31日》第18页）","language":"中文","translation":false},{"id":"capital-9-399","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":399,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[185] “露天漂白业者”撒谎说，他们没有使用妇女做夜工，以此逃避了1860年漂白工厂法。但谎言被工厂视察员揭穿了，同时，工人的请愿书使议会打消了“露天漂白厂”座落在芳香、凉爽的草地上的印象。在这些露天漂白厂里，千燥室的温度高达华氏90°－100°，其中做工的主要是少女。“冷却”这个词已经成了她们从干燥室偶尔跑到户外喘口气的专门用语。“在干燥室里有15个少女，烘烤麻布的温度是80°－90°，烘烤细麻布的温度是100°和100°以上。一间约有10平方呎的小屋，中间放着密闭火炉，12个少女在那里〈把细麻布等〉熨平和叠齐。少女们围着发出炽热的火炉，细麻布很快就被烘干，然后由她们熨平。这些人的劳动时间是没有限制的。在忙的时候，他们要接连许多天干到晚上9点或12点”。（同上，第56页）一个医生说：“没有规定专门的时间让人们凉快一下，不过当温度髙得实在受不了，或者女工的手被汗水弄脏了，便允许她们出去几分钟……我在这些女工中行医的经验使我断定，她们的健康状况比纺纱女工坏得多〈而资本在递交给议会的请愿书中，竟用卢本斯的笔法把她们描画成非常健康！〉。她们中间最常见的病是：肺病、支气管炎、子宫病、恶性歇斯底里和风湿症。我认为，造成所有这些病症的直接或间接的原因，就是她们的工作室温度太髙，并且她们缺少足够的舒适的农服，不能在冬季回家时抵御寒冷潮湿空气的袭击。”（同上，第56、57页）关于后来才从快活的“露天漂白业者”那里争得来的1863年法令，工厂视察员指出：“这个法令看起来是保护工人的，但它不仅没有达到保护工人的目的……按照法令的条文，只有当儿童和妇女在晚上8点以后被发现做工时才应受到保护，就是在这种时候，因法令所规定的证明方法有种种保留条件，以致很少有人会受到处罚。”（同上，第52页）“作为一个具有人道的和教育的目的的法令来说，该法令是彻底失败了。允许同样也可以说强迫妇女和儿童每天劳动14小时（包括或不包括吃饭时间，要看情况而定），或许还要劳动更长的时间，并且不管他们的年龄、性别如何，不管漂白厂邻近地区的家庭有怎样的社会习惯，这能说是人道的吗？”（《工厂视察员报告，1863年4月30日》笫40页）","language":"中文","translation":false},{"id":"capital-9-400","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":400,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[185a] 第2版注：自从1866年我写这些话以来，倒退的现象又发生了。","language":"中文","translation":false},{"id":"capital-9-401","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":401,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[186] “这两个阶级〈资本家和工人〉各自的行为，是它们当时所处地位的结果。”（《工厂视察员报告。1848年10月31日》第113页）","language":"中文","translation":false},{"id":"capital-9-402","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":402,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[187] “受限制的行业都与使用蒸汽力或水力生产纺织品有关。一种行业必须具备两个条件才受工厂视察制度的保护，这就是：使用蒸汽力或水力，并且加工某种特定的纤维。”（《工厂视察员拫吿。1864年10月31日》笫8页）","language":"中文","translation":false},{"id":"capital-9-403","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":403,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[188] 关于这种所谓家庭工业的情况，童工调査委员会最近的报告提供了非常丰富的材料。","language":"中文","translation":false},{"id":"capital-9-404","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":404,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[189] “最近这次会期〈1864年〉通过的法令……涉及到习惯异常不同的各种行业。使用机械力开动机器，已不象以前那样是一个企业在法律上被当作工厂的必要条件了。”（《工厂视察员报告。1864年10月31日》第8页）","language":"中文","translation":false},{"id":"capital-9-405","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":405,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[190] 在比利时这个大陆自由主义的乐园，连这种运动的影子都没有。甚至那里的煤矿和金属矿山，各种年龄的男女工人都被完全“自由地”消费着，而不论消费时间多长以及什么时候被消费。那里所雇用的每1000人中，有733个男人，88个妇女，135个16岁以下的男孩，44个16岁以下的女孩。在炼铁厂等处，每1000人中，有668个男人，149个妇女，98个16岁以下的男孩，85个16岁以下的女孩。此外，对成熟的或未成熟的劳动力虽然都剥削得很厉害，但工资很低，每日平均的工资，男人为2先令8便士，妇女为1先令8便士，少年为1先令2 1/2便士。不过，与1850年相比，1863年比利时输出的煤、铁等等的数量和价值几乎增加了一倍。","language":"中文","translation":false},{"id":"capital-9-406","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":406,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[191] 本世纪头十年刚刚结束，罗伯特·欧文就不仅在理论上鼓吹限制工作日的必要性，而且在实际上在新拉纳克他自己的工厂内实行了十小时工作日。这种主张正同他的“生产劳动与儿童教育相结合”一样，同他创办的工人合作企业一样,被讥笑为共产主义的空想。现在，第一个空想成了工厂法，第二个空想成了一切“工厂法”中的正式用语，第三个空想甚至成了进行反动欺骗的外衣。","language":"中文","translation":false},{"id":"capital-9-407","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":407,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[192] 尤尔《工厂哲学》（法译本）1836年巴黎版第2卷第39、40、67、77等页。","language":"中文","translation":false},{"id":"capital-9-408","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":408,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[193] “1855年巴黎国际统计会议”的报告说:“法国的法律把工厂和作坊每天的劳动时间限制为12小时。但它不是把这一劳动限制在固定的钟点内〈即一段时间内〉，而只是规定儿童在早晨5点至晚上9点这段时间内做工。因此一部分工厂主就利用这一不幸的沉默给予他们的权利，让工人每天（也许除开星期日）不停地劳动。他们为此使用两班工人，每班在作坊内的劳动时间都不超过12小时，但企业的生产却昼夜不停。法律得到了遵守，但是合乎人道吗？”除了“做夜工对人体有破坏性的影响”外，报告还着重指出，“夜晚男女工人挤在同一个灯光暗淡的车间内会产生严重的后果”。","language":"中文","translation":false},{"id":"capital-9-409","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":409,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[194] “例如，在我这个地区内，在同一家工厂建筑物内，同一个工厂主既是要受‘漂白厂和染厂法’约束的溧白业者和染色业者，又是要受‘印染工厂法’约束的印染业者，并且还是受‘工厂法’约束的上浆业者……”（贝克先生的报告，载于《工厂视察员报告。1861年10月31日》第20页）贝克先生在列举这些法令的不同规定以及由此引起的种种纠纷以后说：“可见，如果工厂主存心回避法律，那末要保证执行议会的这三个法令是多么困难。”［同上，第21页］不过这倒保证法学家先生有案子可办了。","language":"中文","translation":false},{"id":"capital-9-410","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":410,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[195] 因此，工厂视察员终于大胆地说出：“这种异议〈资本对在法律上限制劳动时间的异议〉必将在劳动权利的伟大原则面前屈服……到一定的时候，雇主使用工人劳动的权利就终止，工人就可以自行支配自己的时间，即使他还没有精疲力尽。”（《工厂视察员报告。1862年10月31日》第54页）","language":"中文","translation":false},{"id":"capital-9-411","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":411,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【134】 指1866年8月20日至25日在巴尔的摩召开的美国工人代表大会。参加大会的有六十名代表，他们代表六万多名联合在工联中的工人。大会讨论了在法律上规定八小时工作日、工人的政治活动、合作社、把所有工人联合到工联中等问题。另外，大会决定成立工人阶级的政治组织——全国劳工同盟。——第333页。","language":"中文","translation":false},{"id":"capital-9-412","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":412,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[196] “我们，丹克尔克的工人，特此声明：现行制度所规定的劳动时间太长，没有给工人休息和发展的时间，相反，倒是把工人貶低到比在奴隶制下好不了多少的受奴役地位。因此我们通过决议：一个工作日有8小时就够了，而且法律也应该承认这—点；我们呼吁报刊这个强有力的杠杆来支持我们……凡拒绝给予这种支持的人，将被看作是劳动改良和工人权利的敌人。”（纽约州丹克尔克工人的决议，1866年）","language":"中文","translation":false},{"id":"capital-9-413","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":413,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【135】 这里引用的国际工人协会日内瓦代表大会的决议，是拫据马克思所写的《临时中央委员会就若干问题给代表的指示》一文拟定的（见《马克思恩格斯全集》中文版第16卷第213—223页〉。——第334页。","language":"中文","translation":false},{"id":"capital-9-414","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":414,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[197] 《工厂视察员报告。1848年10月31日》第112页。","language":"中文","translation":false},{"id":"capital-9-415","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":415,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[198] “此外，这种诡计〈例如资本在1848—1850年采取的手法〉提供了一个无可辩驳的证据，证明一种经常有人提出的着法是多么错误，这种看法是：工人不需要任何保护，而应被看作是他们的唯一财产即他们双手的劳动和额头上的汗水的自由支配者。”（《工厂视察员报告。1850年4月30日》第45页）“自由劳动（如果还可以这样称呼的话、即使在自由的国家也需要法律的强有力的臂膀来保护。”（《工厂视察员报告。1864年10月31日》第34页）“允许每天劳动14小时，包括或不包括吃饭时间……就等于强迫这样做。”（《工厂视察员报告。1863年4月30日》第40页）","language":"中文","translation":false},{"id":"capital-9-416","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":416,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[199] 弗里德里希·恩格斯《英国的十小时工作日法案》，载于我主编的《新莱茵报。政治经济评论》1850年4月号第5页【136】。","language":"中文","translation":false},{"id":"capital-9-417","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":417,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【136】 见《马克思恩格斯全集》中文版第7卷第276页。——第335页。","language":"中文","translation":false},{"id":"capital-9-418","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":418,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【137】 “折磨他们的毒蛇”——套用了海涅的诗《亨利希》（诗集《时代的诗》）中的一句话。——第335页。","language":"中文","translation":false},{"id":"capital-9-419","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":419,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[200] 在受十小时工作日法令约束的工业部门，该法令“使工人免于完全退化下去，并使他们的健康状况有了保障”。（《工厂视察员报告。1859年10月31日》第47页）“资本〈在工厂中〉超过限定时间仍使机器转动，就必定损害它所雇用的工人的健康和道德；而工人是不能自己保护自己的。”（同上，第8页）","language":"中文","translation":false},{"id":"capital-9-420","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":420,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【138】 大宪章（Magna Charta)，即自由大宪章（Magna Charta Libertatum），是1215年由英王“无地约翰”签署的一个历史文件的名称。大宪章是骑士和市民所支持的起义的大封建主向国王提出的。它对国王的权力规定了某些限制，保存了一些封建特权，并对骑士阶层和城市做了一些让步。马克思在这里指英国工人阶级经过长期顽强的反资本斗争而争得的限制工作日的法律。——第335页。","language":"中文","translation":false},{"id":"capital-9-421","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":421,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"[201] “还有一个更大的好处，这就是把属于工人自己的时间和属于雇主的时间终于明显地区分开来。工人现在知道，他出卖的时间何时结束，他自己的时间何时开始，由于他预先准确地知道了这一点，他就能够依照自己的目的事先安排好自己的时间了。”（同上，第52页）“它〈工厂法〉使工人成了自己时间的主人，这就赋予工人一种道义力量，使他们也许有可能掌握政治权力。”（同上，笫47页）……工厂视察员以有节制的讥讽和经过斟酌的语言暗示，现在的十小时工作日法令，在某种程度上也使资本家摆脱了他作为单纯的资本化身而自然带有的那种野蛮性，并给了他受少许“教养”的时间。从前，“雇主除了搞钱以外再没有时间做别的事情，而工人除了劳动以外也再没有时间做别的事情”。（《工厂视察员报告。1859年10月31日》第48页）","language":"中文","translation":false},{"id":"capital-9-422","author":"马克思","title":"资本论·第一卷","location":"第八章 工作日","page":9,"paragraph":422,"url":"https://www.marxists.org/chinese/marx/capital/08.htm","text":"【139】 多么大的变化啊！（Quantum mutatus ab illo！）——味吉尔《亚尼雅士之歌》第2卷第274行。——第335页。","language":"中文","translation":false},{"id":"capital-10-1","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-10-2","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"第九章 剩余价值率和剩余价值量","language":"中文","translation":false},{"id":"capital-10-3","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"在这一章里，也同前面一样，假定劳动力的价值，从而再生产或维持劳动力所必要的工作日部分，是一个已知的不变的量。","language":"中文","translation":false},{"id":"capital-10-4","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"根据这个假设，知道剩余价值率，同时也就知道一个工人在一定的时间内为资本家提供的剩余价值量。例如，假设必要劳动每天是6小时，表现为金额3先令或1塔勒，那末，1塔勒就是一个劳动力的日价值，或者说，是购买一个劳动力所预付的资本价值。再假设剩余价值率是100％，那末，这1塔勒的可变资本就生产1塔勒的剩余价值量，或者说，工人每天提供6小时的剩余劳动量。","language":"中文","translation":false},{"id":"capital-10-5","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"但是，可变资本是资本家同时使用的全部劳动力的总价值的货币表现。因此，可变资本的价值，等于一个劳动力的平均价值乘以所使用的劳动力的数目。因此，在已知劳动力价值的情况下，可变资本的量与同时雇用的工人人数成正比。如果一个劳动力的日价值＝1塔勒，那末，每天要剥削100个劳动力，就必须预付100塔勒的资本，要剥削n个劳动力，就必须预付n塔勒的资本。","language":"中文","translation":false},{"id":"capital-10-6","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"同样，如果1塔勒的可变资本，即一个劳动力的日价值，每天生产1塔勒的剩余价值，那末，100塔勒的可变资本每天就生产100塔勒的剩余价值，n塔勒的可变资本每天就生产1塔勒×n的剩余价值。可见，所生产的剩余价值量，等于一个工人一个工作日所提供的剩余价值乘以所使用的工人人数。又因为在劳动力价值已定的情况下，一个工人所生产的剩余价值量是由剩余价值率决定的，由此就得出如下第一个规律：所生产的剩余价值量，等于预付的可变资本量乘以剩余价值率，或者说，是由同一个资本家同时剥削的劳动力的数目与单个劳动力受剥削的程度之间的复比例决定的。","language":"中文","translation":false},{"id":"capital-10-7","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"① 在作者亲自校订过的法文版中，这个原理的后一部分表述如下：“或者说，等于一个劳动力的价值乘以该劳动力受剥削的程度，再乘以同时受剥削的劳动力的数目。”——编者注","language":"中文","translation":false},{"id":"capital-10-8","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"因此，如果我们用M表示剩余价值量，用m表示一个工人每天平均提供的剩余价值，用v表示购买一个劳动力每天预付的可变资本，用V表示可变资本的总数，用k表示一个平均劳动力的价值，用a'/a（剩余劳动/必要劳动）表示一个平均劳动力受剥削的程度，用n表示所使用的工人人数，我们就得出：","language":"中文","translation":false},{"id":"capital-10-9","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"这里继续假定，不仅一个平均劳动力的价值不变，而且一个资本家所使用的工人已经化为平均的工人。也有例外的情况，就是所生产的剩余价值并不与受剥削的工人人数按比例增长，但这时劳动力的价值也就不是不变的了。","language":"中文","translation":false},{"id":"capital-10-10","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"因此，在一定量剩余价值的生产上，一种因素的减少可以由另一种因素的增加来补偿。如果可变资本减少，同时剩余价值率却按同一比例提高，那末所生产的剩余价值量仍然不变。按照以前的假定，如果一个资本家每天要剥削100个工人，必须预付100塔勒，而剩余价值率如果是50％，那末，这100塔勒的可变资本就提供50塔勒的剩余价值，或100×3个劳动小时的剩余价值。如果剩余价值率提高一倍，或者说，工作日不是从6小时延长到9小时，而是从6小时延长到12小时，那末减少了一半的可变资本50塔勒，也同样提供50塔勒的剩余价值，或50×6个劳动小时的剩余价值。可见，可变资本的减少，可以由劳动力受剥削的程度的按比例的提高来抵偿，或者说，所雇用的工人人数的减少，可以由工作日的按比例的延长来抵偿。因此在一定限度内，资本所能榨取的劳动的供给，并不取决于工人的供给。[202]反过来说，如果剩余价值率降低了，那末，只要可变资本量或雇用的工人人数按比例增加，所生产的剩余价值量就仍然不变。","language":"中文","translation":false},{"id":"capital-10-11","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"但是，靠提高剩余价值率或延长工作日来补偿工人人数或可变资本量的减少，是有不能超越的界限的。无论劳动力的价值如何，无论维持工人的必要劳动时间是2小时还是10小时，一个工人每天所能生产的总价值，总是小于24个劳动小时所物化的价值，如果这24个物化劳动小时的货币表现是12先令或4塔勒，那就总是小于12先令或4塔勒。我们前面假定，要再生产劳动力本身，或者说，要补偿购买劳动力所预付的资本价值，每天需要6个劳动小时。根据这个假定，500塔勒的可变资本，使用500个工人，在剩余价值率为100％，或工作日为12小时的时候，每天生产500塔勒的剩余价值，或6×500个劳动小时的剩余价值。100塔勒的资本，每天使用100个工人，在剩余价值率为200％，或工作日为18小时的时候，只生产200塔勒的剩余价值量，或12×100个劳动小时的剩余价值量。它的总价值产品，即预付的可变资本的等价物加剩余价值，在任何一天都决不能达到400塔勒或24×100个劳动小时的数额。平均工作日（它天然总是小于24小时）的绝对界限，就是可变资本的减少可以由剩余价值率的提高来补偿的绝对界限，或者说，就是受剥削的工人人数的减少可以由劳动力受剥削的程度的提高来补偿的绝对界限。这个非常明白的第二个规律，对于解释资本要尽量减少自己所雇用的工人人数即减少转化为劳动力的可变资本部分的趋势（以后将谈到这种趋势）所产生的许多现象，是十分重要的，而这种趋势是同资本要生产尽可能多的剩余价值量的另一趋势相矛盾的。反过来说，如果所使用的劳动力数量增加了，或可变资本量增加了，但是它的增加和剩余价值率的降低不成比例，那末所生产的剩余价值量就会减少。","language":"中文","translation":false},{"id":"capital-10-12","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"第三个规律是从所生产的剩余价值量取决于剩余价值率和预付的可变资本量这两个因素而得出来的。如果剩余价值率或劳动力受剥削的程度已定，劳动力价值或必要劳动时间量已定，那末不言而喻，可变资本越大，所生产的价值量和剩余价值量也就越大。如果工作日的界限及其必要部分的界限已定，那末，一个资本家所生产的价值量和剩余价值量，显然就只取决于他所推动的劳动量。但根据以上假设，他所推动的劳动量取决于他所剥削的劳动力的数量，或他所剥削的工人人数，而工人的人数又是由他所预付的可变资本量决定的。可见，在剩余价值率和劳动力价值已定的情况下，所生产的剩余价值量同预付的可变资本量成正比。但是我们知道，资本家把他的资本分成两部分。他把一部分投在生产资料上，这是他的资本的不变部分。他把另一部分转化为活的劳动力，这一部分形成他的可变资本。在同一生产方式的基础上，在不同生产部门中，资本划分为不变部分和可变部分的比例是不同的。在同一生产部门内，这一比例是随着生产过程的技术基础和社会结合的变化而变化的。但是，无论一定量的资本是怎样分为不变部分和可变部分，无论后者与前者之比是1:2或是1:10，还是1:x，刚才确定的规律都不会受到影响。因为根据前面的分析，不变资本的价值虽然再现在产品价值中，但是并不加入新形成的价值产品。使用1000个纺纱工人，当然比使用100个纺纱工人需要更多的原料、纱锭等等。但是不管这些待追加的生产资料的价值是提高，降低，还是不变，也不管是大是小，都不会对推动这些生产资料的劳动力的价值增殖过程有任何影响。因此，上面确认的规律就具有这样的形式：在劳动力的价值已定和劳动力受剥削的程度相同的情况下，不同的资本所生产的价值量和剩余价值量，同这些资本的可变部分即转化为活劳动力的部分的量成正比。","language":"中文","translation":false},{"id":"capital-10-13","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"这一规律同一切以表面现象为根据的经验显然是矛盾的。每个人都知道，就所使用的总资本两个部分各占的百分比来说，纺纱厂主使用的不变资本较多，可变资本较少，面包房老板使用的可变资本较多，不变资本较少，但前者获得的利润或剩余价值并不因此就比后者少。要解决这个表面上的矛盾，还需要许多中项，就象从初等代数的角度来看，要了解0/0可以代表一个真实的量需要很多中项一样。尽管古典经济学从来没有表述过这一规律，但是它却本能地坚持这一规律，因为这个规律是一般价值规律的必然结果。古典经济学企图用强制的抽象法把这个规律从现象的矛盾中拯救出来。以后[203]我们会看到，李嘉图学派是怎样被这块拦路石绊倒的。“确实什么也没有学到”【140】的庸俗经济学，在这里也象在其他各处一样，抓住了现象的外表来反对现象的规律。它与斯宾诺莎相反，认为“无知就是充足的理由”。【141】","language":"中文","translation":false},{"id":"capital-10-14","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"我们可以把社会总资本每天所使用的劳动看成一个唯一的工作日。例如，假设工人人数为100万，一个工人的平均工作日为10小时，那末社会工作日就是1000万小时。在这个工作日的长度已定时，不管它的界限是由生理条件还是由社会条件决定，只有工人人数即工人人口增加，剩余价值量才能增加。在这里，人口的增加形成社会总资本生产剩余价值的数学界限。反之，在人口数量已定时，这种界限就由工作日的可能的延长来决定[204]。在下一章我们会看到，这个规律只适用于以上所考察的剩余价值形式。","language":"中文","translation":false},{"id":"capital-10-15","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"从以上对剩余价值生产的考察中可以看出，不是任何一个货币额或价值额都可以转化为资本。相反地，这种转化的前提是单个货币所有者或商品所有者手中有一定的最低限额的货币或交换价值。可变资本的最低限额，就是为取得剩余价值全年逐日使用的一个劳动力的成本价格。假设这个工人自己占有生产资料，并且满足于工人的生活，那末只要有再生产他的生活资料的必要劳动时间，比如说每天8小时，对他来说就够了。因而他也只需要够8个劳动小时用的生产资料。但是，资本家除这8小时外还要工人再进行比如说4小时剩余劳动，这样，他就需要一个追加的货币额，来购置追加的生产资料。按照我们的假设，他必须使用两个工人，才能靠每天占有的剩余价值来过工人那样的生活，即满足他的必要的需求。在这种情况下，他的生产的目的就只是维持生活，不是增加财富；而在资本主义生产下，增加财富是前提。为了使他的生活只比一个普通工人好一倍，并且把所生产的剩余价值的一半再转化为资本，他就必须把预付资本的最低限额和工人人数都增加为原来的8倍。诚然，他自己也可以和他的工人一样，直接参加生产过程，但这时他就不过成了介于资本家和工人之间的中间人物，成了“小业主”。资本主义生产发展到一定高度，就要求资本家能够把他充当资本家即人格化的资本的全部时间，都用来占有从而控制别人的劳动，用来出售这种劳动的产品[205]。中世纪的行会力图用强制的办法防止手工业师傅变为资本家，限定每个师傅可以雇用的劳动者的人数不得超过一个极小的最高限额。货币或商品的所有者，只有当他在生产上预付的最低限额大大超过了中世纪的最高限额时，才真正变为资本家。在这里，也象在自然科学上一样，证明了黑格尔在他的《逻辑学》中所发现的下列规律的正确性，即单纯的量的变化到一定点时就转化为质的区别。[205a]","language":"中文","translation":false},{"id":"capital-10-16","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"单个的货币所有者或商品所有者要蛹化为资本家而必须握有的最低限度价值额，在资本主义生产的不同发展阶段上是不同的，而在一定的发展阶段上，在不同的生产部门内，也由于它们的特殊的技术条件而各不相同。还在资本主义生产初期，某些生产部门所需要的最低限额的资本就不是在单个人手中所能找到的。这种情况一方面引起国家对私人的补助，如柯尔培尔时代的法国和直到目前的德意志若干邦就是这样。另一方面，促使对某些工商业部门的经营享有合法垄断权的公司[206]的形成，这种公司就是现代股份公司的前驱。","language":"中文","translation":false},{"id":"capital-10-17","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"我们不详细谈资本家和雇佣工人的关系在生产过程的进行中的变化，也不谈资本本身的更进一步的规定。这里只着重指出少数要点。","language":"中文","translation":false},{"id":"capital-10-18","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"在生产过程中，资本发展成为对劳动，即对发挥作用的劳动力或工人本身的指挥权。人格化的资本即资本家，监督工人有规则地并以应有的强度工作。","language":"中文","translation":false},{"id":"capital-10-19","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"其次，资本发展成为一种强制关系，迫使工人阶级超出自身生活需要的狭隘范围而从事更多的劳动。作为别人辛勤劳动的制造者，作为剩余劳动的榨取者和劳动力的剥削者，资本在精力、贪婪和效率方面，远远超过了以往一切以直接强制劳动为基础的生产制度。","language":"中文","translation":false},{"id":"capital-10-20","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"资本起初是在历史上既有的技术条件下使劳动服从自己的。因此，它并没有直接改变生产方式。所以我们上面所考察的、单靠延长工作日这种形式的剩余价值的生产，看来是与生产方式本身的任何变化无关的。它在旧式面包业中和在现代棉纺业中同样有效。","language":"中文","translation":false},{"id":"capital-10-21","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"如果我们从劳动过程的观点来考察生产过程，那末工人并不是把生产资料当作资本，而只是把它当作自己有目的的生产活动的手段和材料。例如在制革厂，工人只是把皮革当作自己的劳动对象。他不是鞣资本家的皮。可是，只要我们从价值增殖过程的观点来考察生产过程，情形就不同了。生产资料立即转化为吮吸他人劳动的手段。不再是工人使用生产资料，而是生产资料使用工人了。不是工人把生产资料当作自己生产活动的物质要素来消费，而是生产资料把工人当作自己的生活过程的酵母来消费，并且资本的生活过程只是资本作为自行增殖的价值的运动。夜间停止不用、不吮吸活劳动的熔炉和厂房，对资本家说来是一种“纯粹的损失”。因此，熔炉和厂房就造成了要劳动力“做夜工的要求”。货币单纯地转化为生产过程的物质因素，转化为生产资料，就使生产资料变成了榨取他人劳动和剩余劳动的合法权和强制权。最后还可以举一个例子说明，资本主义生产所固有的并成为其特征的这种颠倒，死劳动和活劳动、价值和创造价值的力之间的关系的倒置，是如何反映在资本家头脑中的。在1848—1850年英国工厂主叛乱时期，“佩斯里的一家棉麻纺纱厂（卡莱尔父子公司，这是苏格兰西部资格最老、声誉最好的公司之一，它自1752年开办以来，世世代代由同一家族经营）的老板”，这位非常有学识的绅士，在1849年4月25日《格拉斯哥每日邮报》上发表了一封信[207]。标题是《换班制度》，其中有一段天真可笑的话：","language":"中文","translation":false},{"id":"capital-10-22","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"“现在让我们看看，把劳动时间由12小时缩减到10小时会产生怎样的祸害…… 这些祸害‘合计起来’给工厂主的前途和财产带来极其严重的损害。如果他〈即他的“人手”〉以前工作12小时，而现在限制为10小时，那就等于他的企业内每12台机器或12个纱锭缩减为10台机器或10个纱锭，如果工厂被卖掉，那它们就只能按10来计价。于是全国每家工厂的价值都会减少六分之一。”[208]","language":"中文","translation":false},{"id":"capital-10-23","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"在苏格兰西部这个世袭的资本的头脑中，生产资料即纱锭等的价值同它们的自行增殖或每天吸取他人一定量的无偿劳动的资本属性这样紧密地溶合在一起，以致卡莱尔公司的老板真的以为，在出卖工厂时，要支付给他的不仅是纱锭的价值，而且还有它们的价值增殖，不仅是包含在纱锭内的劳动或生产同种纱锭所必需的劳动，而且还有借助于纱锭每天从佩斯里的健壮的西苏格兰人身上榨取的剩余劳动。正因为如此，他才认为，如果工作日缩短两小时，每12台纺纱机的出售价格就会缩减为10台的出售价格！","language":"中文","translation":false},{"id":"capital-10-24","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[202] 这个基本规律看来是庸俗经济学的先生们所不知道的。他们与阿基米德相反，认为在需求和供给决定劳动的市场价格这一点上，发现了一个不是使世界运动而是使世界静止的支点。","language":"中文","translation":false},{"id":"capital-10-25","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[203] 详见第四卷。","language":"中文","translation":false},{"id":"capital-10-26","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"【140】 “确实什么也没有学到”这句流传很广的话出自法国海军上将德·帕纳的一封信。也有人认为是达来朗说的。这句话是针对那些没有从十八世纪末法国资产阶级革命中吸取任何教训的保皇党人而言。——第341页。","language":"中文","translation":false},{"id":"capital-10-27","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"【141】 斯宾诺莎在《伦理学》（第一部分，增补）中说，无知并不是充足的理由。这句话是针对那些对自然抱有僧侣主义目的论观点的代表人物说的，他们把“上帝意志”称作一切现象的原因的原因，而其唯一的论据就是对其他原因的无知。——第341页。","language":"中文","translation":false},{"id":"capital-10-28","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[204] “社会的劳动，即用在经济上的时间，表现为一个定量，比如说，100万人每人每天10小时，或1000万小时……资本的增长是有限度的。在任何一定的时期内，这个限度就是用在经济上的时间的实际数量。”（《论国民政治经济学》1821年伦敦版第47、49页）","language":"中文","translation":false},{"id":"capital-10-29","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[205] “租地农场主不能指靠自己的劳动，如果他这样做，我认为他会受到损失。他的事务应该是全面照料，他必须监督打谷人，否则粮食打不干净，工钱很快就浪费了；他还必须监督割草人、割麦人等等；他必须经常巡视自己的篱笆；他必须查看是否有疏忽的地方，如果他只局限在一处，那末别处就难免有疏忽。”（［约·阿伯思诺特］《当前粮食价格和农场面积相互关系的研究》，一个租地农场主著，1773年伦敦版第12页）这本书非常有趣，从中可以研究“资本主义租地农场主”或他明确地称之为“商人租地农场主”的起源，可以听到这种租地农场主在那些主要是为生存而挣扎的“小租地农民”面前是怎样自我吹嘘的。“资本家阶级最初部分地摆脱了体力劳动的必要性，最后完全摆脱了体力劳动的必要性。”（理查·琼斯牧师《国民政治经济学教程》1852年哈特福版第3讲第39页）","language":"中文","translation":false},{"id":"capital-10-30","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[205a] 现代化学上应用的，最早由罗朗和热拉尔科学地阐明的分子说，正是以这个规律作基础的。｛笫3版补注：这个注解对于不大懂化学的人来说是不十分明了的。所以我们对它作如下的解释：作者在这里所指的是最初由沙·热拉尔在1843年命名的碳氢化合物的“同系列”，其中每一个系列都有自己的代数组成式。例如：烷烃系列是CnH2n+2；正醇系列是CnH2n+2O；正脂肪酸系列是CnH2nO2以及其他等等。在上面的例子中，（CH2在分子式中单纯的量的增加，每次都形成一个不同质的物体。关于罗朗和热拉尔在确定这个重要事实上的贡献（马克思对他们的贡献估计过高），可参看柯普《化学的发展》1873年慕尼黑版第709、716页和肖莱马《有机化学的产生及其发展》1879年伦敦版笫54页。——弗·恩·｝","language":"中文","translation":false},{"id":"capital-10-31","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[206] 马丁·路德把这种机构称为“垄断公司”。","language":"中文","translation":false},{"id":"capital-10-32","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[207] 《工厂视察员报告。1849年4月30日》第59页。","language":"中文","translation":false},{"id":"capital-10-33","author":"马克思","title":"资本论·第一卷","location":"第九章 剩余价值率和剩余价值量","page":10,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/09.htm","text":"[208] 同上，第60页。工厂视察员斯图亚特本人是一个苏格兰人，他与英格兰的工厂视察员相反，已完全为资本主义思维方式所俘虏。他把这封信附在他的报告中，并明确地指出，这“是某一位采用换班制度的工厂主所写的最有用的一封信，它特别可以用来消除对这种制度的偏见和疑虑”。","language":"中文","translation":false},{"id":"capital-11-1","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-11-2","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"第十章 相对剩余价值的概念","language":"中文","translation":false},{"id":"capital-11-3","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"工作日的一部分只是生产出资本所支付的劳动力价值的等价物。到现在为止，工作日的这一部分被看作不变量，而在一定的生产条件下，在社会现有的经济发展阶段上，它实际上也是这样的。在这个必要劳动时间之外，工人还能劳动2小时、3小时、4小时、6小时等。剩余价值率和工作日的长度就取决于这个延长的量。如果说必要劳动时间是不变的，那末相反，整个工作日是可变的。现在假定有一个工作日，它的总长度以及它的必要劳动和剩余劳动的划分是已定的。例如ac线a——————————b——c代表一个十二小时工作日，ab段代表10小时必要劳动，bc段代表2小时剩余劳动。现在，如果没有ac的进一步延长，或者说不依靠ac的进一步延长，怎样才能增加剩余价值的生产呢？也就是说，怎样才能延长剩余劳动呢？ 尽管工作日的界限ac已定，看来bc仍然可以延长，不过不是越过它的终点c（同时也是工作日ac的终点）延长，而是由它的起点b以相反的方向向a端推移而延长。假定在a—————————b'—b——c中，b'—b等于bc的一半，或一个劳动小时。假定在一个十二小时工作日ac中，b移到b'，bc就延长到b'c，剩余劳动就增加了一半，从2小时增加到3小时，虽然工作日仍旧是12小时。但是很明显，如果必要劳动不同时从ab缩短到ab'，从10小时缩短到9小时，要使剩余劳动这样从bc延长到b'c，从2小时延长到3小时是不可能的。必要劳动的缩短要与剩余劳动的延长相适应，或者说，工人实际上一直为自己耗费的劳动时间的一部分，要变成为资本家耗费的劳动时间。这里，改变的不是工作日的长度，而是工作日中必要劳动和剩余劳动的划分。","language":"中文","translation":false},{"id":"capital-11-4","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"另一方面，知道工作日的量和劳动力的价值，显然也就知道剩余劳动量本身。劳动力的价值，即生产劳动力所需要的劳动时间，决定再生产劳动力价值所必要的劳动时间。如果一个劳动小时用金量来表示是半先令或6便士，劳动力的日价值是5先令，那末工人每天就必须劳动10小时，才能补偿资本支付给他的劳动力的日价值，或者说，才能生产出他每天必要生活资料的价值的等价物。知道这些生活资料的价值，也就知道工人劳动力的价值，知道工人劳动力的价值，也就知道他的必要劳动时间的量。从整个工作日中减去必要劳动时间，就得到剩余劳动的量。12小时减去10小时，还剩2小时，这里看不出，在这种条件下剩余劳动怎么能够延长到2小时以上。当然资本家可以不付给工人5先令，而只付给4先令6便士，或者更少。再生产这4先令6便士价值，有9个劳动小时就够了，这样，在一个十二小时工作日中，剩余劳动就不是2小时，而是3小时了，剩余价值本身也就从1先令提高到1先令6便士了。但是这个结果的获得，只是由于把工人的工资压低到劳动力价值以下。工人只得到他在9小时内生产的4先令6便士，他所支配的生活资料比以前少1/10，因此，他的劳动力只能有萎缩的再生产。在这里，剩余劳动的延长，只是由于打破剩余劳动的正常界限，剩余劳动的范围的扩大，只是由于侵占了必要劳动时间的范围。虽然这种方法在工资的实际运动中起着重要的作用，但是在这里它应该被排除，因为我们假定，一切商品，包括劳动力在内，都是按其十足的价值买卖的。既然作了这样的假定，那末劳动力的生产或劳动力价值的再生产所必要的劳动时间，就不能因为工人的工资低于他的劳动力的价值而减少，而只有当这个价值本身降低时才减少。在工作日长度已定的情况下，剩余劳动的延长必然是由于必要劳动时间的缩短，而不是相反，必要劳动时间的缩短是由于剩余劳动的延长。就我们的例子来说，劳动力的价值必需在实际上降低1/10，必要劳动时间才能减少1/10，从10小时减到9小时，从而使剩余劳动从2小时延长到3小时。","language":"中文","translation":false},{"id":"capital-11-5","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"但是，劳动力的价值要这样降低1/10，同量的生活资料，从前用10小时生产出来，现在要求用9小时生产出来。不过，要做到这一点，不提高劳动生产力是不可能的。例如，一个鞋匠使用一定的手段，在一个十二小时工作日内可以做一双皮靴。如果他要在同样的时间内做两双皮靴，他的劳动生产力就必须提高一倍。不改变他的劳动资料或他的劳动方法，或不同时改变这二者，就不能把劳动生产力提高一倍。因此，他的劳动生产条件，也就是他的生产方式，从而劳动过程本身，必须发生革命。劳动生产力的提高，在这里一般是指劳动过程中的这样一种变化，这种变化能缩短生产某种商品的社会必需的劳动时间，从而使较小量的劳动获得生产较大量使用价值的能力。在研究我们上面考察的那种形式的剩余价值的生产时，我们曾假定生产方式是既定的。而现在，对于由必要劳动变成剩余劳动而生产剩余价值来说，资本只是占有历史上遗留下来的或者说现存形态的劳动过程，并且只延长它的持续时间，就绝对不够了。必须变革劳动过程的技术条件和社会条件，从而变革生产方式本身，以提高劳动生产力，通过提高劳动生产力来降低劳动力的价值，从而缩短再生产劳动力价值所必要的工作日部分。","language":"中文","translation":false},{"id":"capital-11-6","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"我把通过延长工作日而生产的剩余价值，叫做绝对剩余价值；相反，我把通过缩短必要劳动时间、相应地改变工作日的两个组成部分的量的比例而生产的剩余价值，叫做相对剩余价值。","language":"中文","translation":false},{"id":"capital-11-7","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"要降低劳动力的价值，就必须提高这样一些产业部门的生产力，这些部门的产品决定劳动力的价值，就是说，它们或者属于日常生活资料的范围，或者能够代替这些生活资料。但是，商品的价值不仅取决于使商品取得最终形式的那种劳动的量，而且还取决于该商品的生产资料所包含的劳动量。例如皮靴的价值不仅取决于鞋匠的劳动，而且还取决于皮革、蜡、线等等的价值。因此，那些为生产必要生活资料提供不变资本物质要素（劳动资料和劳动材料）的产业部门中生产力的提高，以及它们的商品相应的便宜，也会降低劳动力的价值。相反，那些既不提供必要生活资料、也不为制造必要生活资料提供生产资料的生产部门中生产力的提高，并不会影响劳动力的价值。","language":"中文","translation":false},{"id":"capital-11-8","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"便宜的商品当然只是相应地，即只是按照该商品在劳动力的再生产中所占的比例，降低劳动力的价值。例如，衬衫是一种必要生活资料，但只是许多种必要生活资料中的一种。这种商品变得便宜只会减少工人购买衬衫的支出。但是必要生活资料的总和是由各种商品、各个特殊产业部门的产品构成的，其中每种商品的价值总是劳动力价值的相应部分。劳动力价值随着劳动力再生产所必要的劳动时间的减少而降低，这种劳动时间的全部减少等于所有这些特殊生产部门劳动时间减少的总和。在这里我们把这个总结果看成好象是每个个别场合的直接结果和直接目的。当一个资本家提高劳动生产力来使例如衬衫便宜的时候，他决不是必然抱有相应地降低劳动力的价值，从而减少必要劳动时间的目的；但是只要他最终促成这个结果，他也就促成一般剩余价值率的提高。必须把资本的一般的、必然的趋势同这种趋势的表现形式区别开来。","language":"中文","translation":false},{"id":"capital-11-9","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"这里不考察资本主义生产的内在规律怎样表现为资本的外部运动，怎样作为竞争的强制规律发生作用，从而怎样成为单个资本家意识中的动机。然而有一点一开始就很清楚：只有了解了资本的内在本性，才能对竞争进行科学的分析，正象只有认识了天体的实际的、但又直接感觉不到的运动的人，才能了解天体的表面运动一样。但是，为了理解相对剩余价值的生产，并且只根据已经得出的结果，要作如下的说明。","language":"中文","translation":false},{"id":"capital-11-10","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"如果一个劳动小时用金量来表示是6便士或1/2先令，一个十二小时工作日就会生产出6先令的价值。假定在一定的劳动生产力的条件下，在这12个劳动小时内制造12件商品；每件商品用掉的生产资料、原料等的价值是6便士。在这种情况下，每件商品花费1先令，即6便士是生产资料的价值，6便士是加工时新加进的价值。现在假定有一个资本家使劳动生产力提高一倍，在一个十二小时工作日中不是生产12件这种商品，而是生产24件。在生产资料的价值不变的情况下，每件商品的价值就会降低到9便士，即6便士是生产资料的价值，3便士是最后的劳动新加进的价值。生产力虽然提高一倍，一个工作日仍然同从前一样只创造6先令新价值，不过这6先令新价值现在分散在增加了一倍的产品上。因此分摊在每件产品上的不是这个总价值的1/12，而只是1/24，不是6便士，而是3便士，也就是说，在生产资料变成产品时，就每件产品来说，现在加到生产资料上的，不象从前那样是一个劳动小时，而是半个劳动小时。现在，这个商品的个别价值低于它的社会价值，就是说，这个商品所花费的劳动时间，少于在社会平均条件下生产的大宗同类商品所花费的劳动时间。每件商品平均花费1先令，或者说，代表2小时社会劳动；在生产方式发生变化以后，它只花费9便士，或者说，只包含1 1/2个劳动小时。但是商品的现实价值不是它的个别价值，而是它的社会价值，就是说，它的现实价值不是用生产者在个别场合生产它所实际花费的劳动时间来计量，而是用生产它所必需的社会劳动时间来计量。因此，如果采用新方法的资本家按1先令这个社会价值出售自己的商品，那末他的商品的售价就超出它的个别价值3便士，这样，他就实现了3便士的超额剩余价值。但是另一方面，对他来说，一个十二小时工作日现在表现为24件商品，而不是过去的12件商品。因此要卖掉一个工作日的产品，他就需要有加倍的销路或大一倍的市场。在其他条件相同的情况下，他的商品只有降低价格，才能获得较大的市场。因此资本家要高于商品的个别价值但又低于它的社会价值来出售商品，例如一件商品卖10便士，这样，他从每件商品上仍然赚得1便士的超额剩余价值。对于资本家来说，剩余价值总会这样提高，不管他的商品是不是属于必要生活资料的范围，是不是参加劳动力的一般价值的决定。因此，即使撇开后面这种情况，每个资本家都抱有提高劳动生产力来使商品便宜的动机。","language":"中文","translation":false},{"id":"capital-11-11","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"然而，甚至在这种场合，剩余价值生产的增加也是靠必要劳动时间的缩短和剩余劳动的相应延长。假定必要劳动时间是10 小时，或者说，劳动力的日价值是5先令，剩余劳动是2小时，因而每日生产的剩余价值是1先令。但我们的资本家现在是生产24件商品，每件卖10便士，或者说，一共卖20先令。因为生产资料的价值等于12先令，所以14 2/5件商品只是补偿预付的不变资本。十二小时工作日表现为其余的9 3/5件商品。因为劳动力的价格=5先令，所以6件产品表现必要劳动时间，3 3/5件产品表现剩余劳动。必要劳动和剩余劳动之比在社会平均条件下是5:1，而现在是5:3。用下列方法也可以得到同样结果。一个十二小时工作日的产品价值是20先令。其中12先令属于只是再现的生产资料的价值。因此，剩下的8先令是体现一个工作日的价值的货币表现。这个货币表现比同类社会平均劳动的货币表现要多，因为12小时的同类社会平均劳动只表现为6先令。生产力特别高的劳动起了自乘的劳动的作用，或者说，在同样的时间内，它所创造的价值比同种社会平均劳动要多。但是我们的资本家仍然和从前一样，只用5先令支付劳动力的日价值。因此工人现在要再生产这个价值，用不着象过去那样需要10小时，只要7 1/2小时就够了。这样，他的剩余劳动就增加了2 1/2小时，他生产的剩余价值就从1先令增加到3先令。可见，采用改良的生产方式的资本家比同行业的其余资本家，可以在一个工作日中占有更大的部分作为剩余劳动。他个别地所做的，就是资本全体在生产相对剩余价值时所做的。但是另一方面，当新的生产方式被普遍采用，因而比较便宜地生产出来的商品的个别价值和它的社会价值之间的差额消失的时候，这个超额剩余价值也就消失。价值由劳动时间决定的规律，既会使采用新方法的资本家感觉到，他必须低于商品的社会价值来出售自己的商品，又会作为竞争的强制规律，迫使他的竞争者也采用新的生产方式。因此，只有当劳动生产力的提高扩展到同生产必要生活资料有关的生产部门，以致使属于必要生活资料范围、从而构成劳动力价值要素的商品便宜时，一般剩余价值率才会最终受到这一整个过程的影响。","language":"中文","translation":false},{"id":"capital-11-12","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"商品的价值与劳动生产力成反比。劳动力的价值也是这样，因为它是由商品价值决定的。相反，相对剩余价值与劳动生产力成正比。它随着生产力提高而提高，随着生产力降低而降低。在货币价值不变的情况下，一个十二小时社会平均工作日总是生产6先令的价值产品，而不管这个价值额如何分割为劳动力价值的等价物和剩余价值。但是，如果由于生产力的提高，每天的生活资料的价值，从而劳动力的日价值，从5先令下降到3先令，那末剩余价值就从1先令增加到3先令。再生产劳动力的价值，从前需要10个劳动小时，现在只要6个劳动小时就够了。有4个劳动小时空了出来，可以并入剩余劳动的范围。因此，提高劳动生产力来使商品便宜，并通过商品便宜来使工人本身便宜，是资本的内在的冲动和经常的趋势。","language":"中文","translation":false},{"id":"capital-11-13","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"商品的绝对价值本身，是生产商品的资本家所不关心的。他关心的只是商品所包含的、在出售时实现的剩余价值。剩余价值的实现本身就包含着预付价值的补偿。因为相对剩余价值的增加和劳动生产力的发展成正比，而商品价值的降低和劳动生产力的发展成反比，也就是说，因为同一过程使商品便宜，并使商品中包含的剩余价值提高，所以就揭示了一个谜：为什么只是关心生产交换价值的资本家，总是力求降低商品的交换价值；这也就是政治经济学奠基人之一魁奈用来为难他的论敌、而后者至今还没有回答的那个矛盾。魁奈说：","language":"中文","translation":false},{"id":"capital-11-14","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"“你们认为，在工业产品的生产中，只要不损害生产，越能节省费用或昂贵的劳动，这种节省就越有利，因为这会降低产品的价格。尽管如此，你们又认为，由工人劳动创造的财富的生产，在于增大他们产品的交换价值。”","language":"中文","translation":false},{"id":"capital-11-15","author":"马克思","title":"资本论·第一卷","location":"第十章 相对剩余价值的概念","page":11,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/10.htm","text":"可见，在资本主义生产条件下，通过发展劳动生产力来节约劳动，目的绝不是为了缩短工作日。它的目的只是为了缩短生产一定量商品所必要的劳动时间。工人在他的劳动的生产力提高时，一小时内例如会生产出等于过去10倍的商品，从而每件商品需要的劳动时间只是过去的1/10，这绝不能阻止他仍旧劳动12小时，并且在12小时内生产1200件商品，而不是以前的120件商品。他的工作日甚至还可能延长，以致他现在要在14小时内生产1400件商品等等。因此，在麦克库洛赫、尤尔、西尼耳之流的经济学家的著作中，在这一页可以读到，工人应当感谢资本发展了生产力，因为这种发展缩短了必要劳动时间，在下一页接着就会读到，工人为了表示这种感谢，以后必须劳动15小时，以代替原来的10小时。在资本主义生产中，发展劳动生产力的目的，是为了缩短工人必须为自己劳动的工作日部分，以此来延长工人能够无偿地为资本家劳动的工作日的另一部分。在商品没有变便宜的情况下，究竟会在多大的程度上达到这个结果，我们在下面考察相对剩余价值的各种特殊的生产方法时，就可以看到。","language":"中文","translation":false},{"id":"capital-12-1","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-12-2","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"我们已经看到，资本主义生产实际上是在同一个资本同时雇用较多的工人，因而劳动过程扩大了自己的规模并提供了较大量的产品的时候才开始的。较多的工人在同一时间、同一空间（或者说同一劳动场所），为了生产同种商品，在同一资本家的指挥下工作，这在历史上和逻辑上都是资本主义生产的起点。就生产方式本身来说，例如初期的工场手工业，除了同一资本同时雇用的工人较多而外，和行会手工业几乎没有什么区别。行会师傅的作坊只是扩大了而已。","language":"中文","translation":false},{"id":"capital-12-3","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"因此，起初只是量上的区别。我们已经看到，一定的资本所生产的剩余价值量，等于一个工人所提供的剩余价值乘以同时雇用的工人人数。工人人数本身丝毫不会改变剩余价值率或劳动力的剥削程度，而且，就商品价值的生产来说，劳动过程的任何质的变化，看来是没有关系的。这是由价值的性质得出来的。如果一个十二小时工作日物化为6先令，那末1200个这样的工作日就物化为6先令×1200。在前一种情况下，产品体现了12个劳动小时，在后一种情况下，则体现了12×1200个劳动小时。在价值生产上，多数始终只是许多个数的总和。因此对于价值生产来说，1200个工人无论是单独进行生产，还是在同一资本指挥下联合起来进行生产，都不会引起任何差别。","language":"中文","translation":false},{"id":"capital-12-4","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"不过，在一定限度内还是会发生变化。物化为价值的劳动，是社会平均性质的劳动，也就是平均劳动力的表现。但是平均量始终只是同种的许多不同的个别量的平均数。在每个产业部门，个别工人，彼得或保罗，都同平均工人多少相偏离。这种在数学上叫做“误差”的个人偏离，只要把较多的工人聚集在一起，就会互相抵销，归于消失。著名的诡辩家和献媚者艾德蒙·伯克甚至根据他当租地农场主的实际经验也懂得，只要有五个雇农“这样小的队伍”，劳动的所有个人差别就会消失，因此任意五个成年英国雇农在一起，和其他任何五个英国雇农一样，可以在同样的时间内完成同样多的劳动。无论如何，明显的是，同时雇用的许多工人的总工作日除以工人人数，本身就是一天的社会平均劳动。例如，假定一个人的工作日是12小时。这样，12个同时雇用的工人的工作日就构成144小时的总工作日，虽然这12个工人中每个人的劳动都多少偏离社会平均劳动，因而每个工人做同一件工作所用的时间有多有少，但是每个工人的工作日作为144小时总工作日的1/12，都具有社会平均性质。但是，对于雇用12个工人的资本家来说，工作日是作为12个工人的总工作日而存在的。不管这12个工人是协同地劳动，还是他们劳动的全部联系只在于他们为同一个资本家做工，每个工人的工作日都总是总工作日的一个相应部分。反之，如果这12个工人每两人为一个小业主雇用，那末每个业主能否生产同样的价值量，从而能否实现一般剩余价值率，就是偶然的了。这里就会出现个人偏离。如果一个工人生产一种商品所花费的时间显著地超出社会必需的时间，他的个人必要劳动时间显著地偏离社会必要劳动时间或平均劳动时间，那末，他的劳动就不能当作平均劳动，他的劳动力就不能当作平均劳动力。这样的劳动力不是根本卖不出去，就是只能低于劳动力的平均价值出卖。因此要有一定的最低限度的劳动能力作为前提，以后我们会看到：资本主义生产找到了衡量这个最低限度的办法。不过这个最低限度是会偏离平均水平的，虽然从另一方面看，劳动力必须按平均价值支付。因此，在6个小业主中间，有人赚到的会高于一般剩余价值率，有人赚到的会低于一般剩余价值率。这些差别就整个社会来说会互相抵销，但是就单个业主来说却不是这样。因此对单个生产者来说，只有当他作为资本家进行生产，同时使用许多工人，从而一开始就推动社会平均劳动的时候，价值增殖规律才会完全实现。〔注：罗雪尔教授先生声称他发现了，教授夫人雇用的一个女裁缝两天内提供的劳动，比她雇用的两个女裁缝一天内提供的劳动要多。这位教授先生不应该在婴儿室和在没有主要人物——资本家的情况下观察资本主义的生产过程。Bondt, Werner F. M., and Richard Thaler, 1985. Does the Stock Market Overreact? Journal of Finance, 40 (3), 793-805.〕","language":"中文","translation":false},{"id":"capital-12-5","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"即使劳动方式不变，同时使用较多的工人，也会在劳动过程的物质条件上引起革命。容纳许多人做工的厂房、储藏原料等的仓库、供许多人同时使用或交替使用的容器、工具、器具等，总之，一部分生产资料，现在是在劳动过程中共同消费的。一方面，商品的交换价值，从而生产资料的交换价值，丝毫不会因为它们的使用价值得到某种更有效的利用而有所增加。另一方面，共同使用的生产资料的规模会增大。20个织布工人用20台织机劳动的房间，必然比一个独立织布者带两个帮工做工的房间大得多。但是，建造一座容纳20个人的作坊比建造10座各容纳两个人的作坊所耗费的劳动要少，因此大量积聚的并且共同使用的生产资料的价值，一般地说，不会和这些生产资料的规模及其效果成比例地增加。共同使用的生产资料转移到单个产品上去的价值组成部分所以较小，部分是因为这些生产资料转移的总价值要同时分配在较大量的产品上，部分是因为这些生产资料加入生产过程的价值同分散的生产资料相比，绝对地说虽然较大，但从它们作用范围来看，相对地说却较小。因此，不变资本的价值组成部分降低了，而随着这部分价值的量的减少，商品的总价值也降低了。其结果和商品的生产资料的生产变得便宜时所产生的结果一样。生产资料使用方面的这种节约，只是由于许多人在劳动过程中共同消费它们。即使许多工人只是在空间上集合在一起，并不协同劳动，这种生产资料也不同于单干的独立劳动者或小业主的分散的并且相对地说花费大的生产资料，而取得了社会劳动的条件或劳动的社会条件这种性质。一部分劳动资料甚至在劳动过程本身取得这种社会性质以前，就已经取得这种社会性质。","language":"中文","translation":false},{"id":"capital-12-6","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"生产资料的节约要从两方面去考察。一方面，它使商品便宜，从而使劳动力的价值下降。另一方面，它改变剩余价值同全部预付资本，也就是同资本的不变组成部分和可变组成部分的价值总额之间的比例。后一点要到本书第三卷第一篇才来探讨，为了叙述上的联系，和这里有关的许多问题也留到该篇再谈。分析的进程要求把研究的对象这样割裂开来，而这种割裂也是符合资本主义生产的精神的。因为在资本主义生产中，劳动条件作为某种独立的东西而与工人相对立，所以劳动条件的节约也表现为一种特殊操作，与工人无关，因而与提高工人的个人生产率的方法没有联系。","language":"中文","translation":false},{"id":"capital-12-7","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"许多人在同一生产过程中，或在不同的但互相联系的生产过程中，有计划地一起协同劳动，这种劳动形式叫做协作。","language":"中文","translation":false},{"id":"capital-12-8","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"一个骑兵连的进攻力量或一个步兵团的抵抗力量，与单个骑兵分散展开的进攻力量的总和或单个步兵分散展开的抵抗力量的总和有本质的差别，同样，单个劳动者的力量的机械总和，与许多人手同时共同完成同一不可分割的操作（例如举重、转绞车、清除道路上的障碍物等）所发挥的社会力量有本质的差别。在这里，结合劳动的效果要末是个人劳动根本不可能达到的，要末只能在长得多的时间内，或者只能在很小的规模上达到。这里的问题不仅是通过协作提高了个人生产力，而且是创造了一种生产力，这种生产力本身必然是集体力。","language":"中文","translation":false},{"id":"capital-12-9","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"且不说由于许多力量融合为一个总的力量而产生的新力量。在大多数生产劳动中，单是社会接触就会引起竞争心和特有的精力振奋，从而提高每个人的个人工作效率。因此，12个人在一个144小时的共同工作日中提供的总产品，比12个单干的劳动者每人劳动12小时或者一个劳动者连续劳动12天所提供的产品要多得多。这是因为人即使不象亚里士多德所说的那样，天生是政治动物，无论如何也天生是社会动物。","language":"中文","translation":false},{"id":"capital-12-10","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"尽管许多人同时协同完成同一或同种工作，但是每个人的个人劳动，作为总劳动的一部分，仍可以代表劳动过程本身的不同阶段。由于协作，劳动对象可以更快地通过这些阶段。例如瓦匠站成一排，把砖从脚手架的下面传到上面，虽然每个人都做同一件事情，但是这些单个操作构成一个总操作的连续部分，成为每块砖在劳动过程中必须通过的各个特殊阶段。因此，总体劳动者例如用24只手传砖，比单个劳动者每人都用两只手搬着砖上下脚手架要快。劳动对象在比较短的时间内通过同样的空间。另一方面，例如，如果一座建筑物同时从各个方面动工兴建，尽管协作的人做的是同一或同种工作，那也会发生劳动的结合。144小时的结合工作日可以在空间上从多方面对劳动对象进行加工，因为结合劳动者或总体劳动者前前后后都有眼睛和手，在一定程度上是全能的。这样，144小时结合工作日完成总产品，比只能比较单方面地对劳动对象进行加工的、多少是单干的劳动者的12个十二小时工作日要快。产品的不同的空间部分同时成长。","language":"中文","translation":false},{"id":"capital-12-11","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"我们所以着重指出，许多互相补充的劳动者做同一或同种工作，是因为这种最简单的共同劳动的形式即使在最发达的协作形态中也起着重大作用。如果劳动过程是复杂的，只要有大量的人共同劳动，就可以把不同的操作分给不同的人，因而可以同时进行这些操作，这样，就可以缩短制造总产品所必要的劳动时间。","language":"中文","translation":false},{"id":"capital-12-12","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"在许多生产部门都有紧急时期，即由劳动过程的性质本身所决定的一定时期，在这些时期内必须取得一定的劳动成果。例如剪一群羊的羊毛或收割若干摩尔根的谷物，在这种情况下，产品的数量和质量取决于这种操作是否在一定的时间开始并在一定的时间结束。在这里，劳动过程要占用的时间是事先决定了的，正象例如捕鲱鱼的情况一样。一个人只能从一天中分割出一个工作日，例如12小时，但是，例如100个人协作就能把一个十二小时工作日扩大成一个1200小时工作日。短促的劳动期限可以由在紧要关头投入生产场所的巨大的劳动量来补偿。在这里，能否不失时机地获得成果，取决于是否同时使用许多结合的工作日，成效的大小取决于劳动者人数的多少；但是这种人数总比在同样长的时间内为达到同样效果所需要的单干劳动者的人数要少。由于缺少这样的协作，美国西部每年都要损失大量粮食，而在英国的统治已经破坏了旧的公社的东印度地区，每年都要损失大量棉花。","language":"中文","translation":false},{"id":"capital-12-13","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"一方面，协作可以扩大劳动的空间范围，因此，某些劳动过程由于劳动对象空间上的联系就需要协作；例如排水、筑堤、灌溉、开凿运河、修筑道路、铺设铁路等等。另一方面，协作可以与生产规模相比相对地在空间上缩小生产领域。在劳动的作用范围扩大的同时劳动空间范围的这种缩小，会节约非生产费用，这种缩小是由劳动者的集结、不同劳动过程的靠拢和生产资料的积聚造成的。","language":"中文","translation":false},{"id":"capital-12-14","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"和同样数量的单干的个人工作日的总和比较起来，结合工作日可以生产更多的使用价值，因而可以减少生产一定效用所必要的劳动时间。不论在一定的情况下结合工作日怎样达到生产力的这种提高：是由于提高劳动的机械力，是由于扩大这种力量在空间上的作用范围，是由于与生产规模相比相对地在空间上缩小生产场所，是由于在紧急时期短时间内动用大量劳动，是由于激发个人的竞争心和集中他们的精力，是由于使许多人的同种作业具有连续性和多面性，是由于同时进行不同的操作，是由于共同使用生产资料而达到节约，是由于使个人劳动具有社会平均劳动的性质，在所有这些情形下，结合工作日的特殊生产力都是劳动的社会生产力或社会劳动的生产力。这种生产力是由协作本身产生的。劳动者在有计划地同别人共同工作中，摆脱了他的个人局限，并发挥出他的种属能力。","language":"中文","translation":false},{"id":"capital-12-15","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"既然劳动者不在一起就不能直接地共同工作，既然劳动者集结在一定的空间是他们进行协作的条件，那末，同一个资本，同一个资本家，如果不同时使用雇佣工人，也就是同时购买他们的劳动力，雇佣工人就不能进行协作。因此，在劳动力本身集合在生产过程中以前，这些劳动力的总价值或工人一天、一周等等的工资总额，必须已经集合在资本家的口袋里。一次支付300工人的报酬，即使支付的只是一天的报酬，也比全年一周一周地支付少量工人的报酬需要更多的资本支出。因此，协作工人的人数或协作的规模，首先取决于单个资本家能支付多大资本量来购买劳动力，也就是取决于每一个资本家在多大规模上拥有供许多工人用的生活资料。","language":"中文","translation":false},{"id":"capital-12-16","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"可变资本的情形是这样，不变资本的情形也是这样。例如拿原料的支出来说，一个雇用300个工人的资本家的支出，是30个各雇用10个工人的资本家中的每一个人的支出的30倍。诚然，共同使用的劳动资料在价值量和物质量方面都不会同雇用的工人人数按同一程度增加，但是它们的增加还是很显著的。因此，较大量的生产资料积聚在单个资本家手中，是雇佣工人进行协作的物质条件，而且协作的范围或生产的规模取决于这种积聚的程度。","language":"中文","translation":false},{"id":"capital-12-17","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"起初，为了有足够的同时被剥削的工人人数，从而有足够的生产出来的剩余价值数量，以便使雇主本身摆脱体力劳动，由小业主变成资本家，从而使资本关系在形式上建立起来，需要有一定的最低限额的单个资本。现在，这个最低限额又表现为使许多分散的和互不依赖的单个劳动过程转化为一个结合的社会劳动过程的物质条件。","language":"中文","translation":false},{"id":"capital-12-18","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"同样，起初资本指挥劳动只是表现为这样一个事实的形式上的结果：工人不是为自己劳动，而是为资本家，因而是在资本家的支配下劳动。随着许多雇佣工人的协作，资本的指挥发展成为劳动过程本身的进行所必要的条件，成为实际的生产条件。现在，在生产场所不能缺少资本家的命令，就象在战场上不能缺少将军的命令一样。","language":"中文","translation":false},{"id":"capital-12-19","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"一切规模较大的直接社会劳动或共同劳动，都或多或少地需要指挥，以协调个人的活动，并执行生产总体的运动——不同于这一总体的独立器官的运动——所产生的各种一般职能。一个单独的提琴手是自己指挥自己，一个乐队就需要一个乐队指挥。一旦从属于资本的劳动成为协作劳动，这种管理、监督和调节的职能就成为资本的职能。这种管理的职能作为资本的特殊职能取得了特殊的性质。","language":"中文","translation":false},{"id":"capital-12-20","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"首先，资本主义生产过程的动机和决定目的，是资本尽可能多地自行增殖，也就是尽可能多地生产剩余价值，因而也就是资本家尽可能多地剥削劳动力。随着同时雇用的工人人数的增加，他们的反抗也加剧了，因此资本为压制这种反抗所施加的压力也必然增加。资本家的管理不仅是一种由社会劳动过程的性质产生并属于社会劳动过程的特殊职能，它同时也是剥削社会劳动过程的职能，因而也是由剥削者和他所剥削的原料之间不可避免的对抗决定的。同样，随着作为别人的财产而同雇佣工人相对立的生产资料的规模的增大，对这些生产资料的合理使用进行监督的必要性也增加了。〔注：英国一家庸人报纸《旁观者》1866年5月26日报道，在曼彻斯特金属丝加工公司实行资本家和工人合伙经营以后，“第一个结果便是材料的浪费突然减少，因为工人理解到，他们没有理由比对待资本家的财产还更厉害地浪费自己的财产，而除了黄帐以外，材料的浪费大概是工厂亏损的最大原因了”。该报又发现罗契得尔合作实验的根本缺点是：“这些实验表明，工人组合可以有成效地管理商店、工厂以及几乎一切工业形式，这些实验大大改善了工人本身的状况，但是它们却没有给资本家留下明显的位置。”多么可怕啊！〕 其次，雇佣工人的协作只是资本同时使用他们的结果。他们的职能上的联系和他们作为生产总体所形成的统一，存在于他们之外，存在于把他们集合和联结在一起的资本中。因此，他们的劳动的联系，在观念上作为资本家的计划，在实践中作为资本家的权威，作为他人意志——他们的活动必须服从这个意志的目的——的权力，而和他们相对立。","language":"中文","translation":false},{"id":"capital-12-21","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"因此，如果说资本主义的管理就其内容来说是二重的，——因为它所管理的生产过程本身具有二重性：一方面是制造产品的社会劳动过程，另一方面是资本的价值增殖过程，——那末，资本主义的管理就其形式来说是专制的。随着大规模协作的发展，这种专制也发展了自己特有的形式。正如起初当资本家的资本一达到开始真正的资本主义生产所需要的最低限额时，他便摆脱体力劳动一样，现在他把直接和经常监督单个工人和工人小组的职能交给了特种的雇佣工人。正如军队需要军官和军士一样，在同一资本指挥下共同工作的大量工人也需要工业上的军官（经理）和军士（监工），在劳动过程中以资本的名义进行指挥。监督工作固定为他们的专职。政治经济学家在拿独立的农民或独立的手工业者的生产方式同以奴隶制为基础的种植园经济作比较时，把这种监督工作算作非生产费用。〔注：凯尔恩斯教授在指出“对劳动的监督”是北美南方各州奴隶制生产的主要特点以后，继续说道：“因为农民所有者<北方的>得到他的土地的全部产品，所以用不着其他的劳动刺激。在这里完全不需要监督”（凯尔恩斯《奴隶劳力》第48、49页）。〕 相反地，他在考察资本主义生产方式时，却把从共同的劳动过程的性质产生的管理职能，同从这一过程的资本主义性质因而从对抗性质产生的管理职能混为一谈。资本家所以是资本家，并不是因为他是工业的领导人，相反，他所以成为工业的司令官，因为他是资本家。工业上的最高权力成了资本的属性，正象在封建时代，战争中和法庭裁判中的最高权力是地产的属性一样。〔注：因此奥古斯特·孔德及其学派可以象证明资本家老爷的永恒必要性那样，去证明封建老爷的永恒必要性。〕 工人作为劳动力的出卖者和资本家进行交易时，是自己劳动力的所有者，他只能出卖他所占有的东西，出卖他个人的、单个的劳动力。这种关系，决不因为资本家购买的不是1个劳动力而是100个劳动力，或者说，他不是和1个工人而是和100个互不相干的工人签订合同，而有所变化。资本家无须让这100个工人协作就能使用他们。因此，他支付的是100个独立的劳动力的价值，而不是100个结合劳动力的价值。工人作为独立的人是单个的人，他们和同一资本发生关系，但是彼此不发生关系。他们的协作是在劳动过程中才开始的，但是在劳动过程中他们已经不再属于自己了。他们一进入劳动过程，便并入资本。作为协作的人，作为一个工作机体的肢体，他们本身只不过是资本的一种特殊存在方式。因此，工人作为社会工人所发挥的生产力，是资本的生产力。只要把工人置于一定的条件下，劳动的社会生产力就无须支付报酬而发挥出来，而资本正是把工人置于这样的条件之下的。因为劳动的社会生产力不费资本分文，另一方面，又因为工人在他的劳动本身属于资本以前不能发挥这种生产力，所以劳动的社会生产力好象是资本天然具有的生产力，是资本内在的生产力。","language":"中文","translation":false},{"id":"capital-12-22","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"古代亚洲人、埃及人、伊特刺斯坎人等等的庞大建筑，显示了简单协作的巨大作用。","language":"中文","translation":false},{"id":"capital-12-23","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"“在过去的时代，这些亚洲国家除了民用的和军事的开支以外，还有剩余的生活资料，可以用于华丽的或实用的建筑。这些国家可以指挥几乎全部非农业人口的手臂，而对这些剩余生活资料的唯一支配权又完全属于君主和祭司，所以它们有能力兴建那些遍布全国的宏伟纪念物…… 在移动巨大的雕像和庞大的重物方面，当时的搬运本领令人惊讶，在这方面恣意滥用的几乎全是人的劳动。光有劳动者的人数和他们的努力的集中就够了。我们看到巨大的珊瑚礁从海底升起形成岛屿和陆地，虽然每一个珊瑚虫是渺小的、微弱的、不足道的。亚洲任何一个君主国的非农业劳动者，除了自己个人的体力以外，很少能贡献什么，但是他们的数量就是他们的力量。由于存在着指挥这些群众的权力，就产生出这些巨大的建筑。正是由于劳动者赖以生活的那些收入都集中在一个人或少数人的手里，才使这一类事业成为可能。”","language":"中文","translation":false},{"id":"capital-12-24","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"亚洲和埃及的国王或伊特刺斯坎的祭司等等的这种权力，在现代社会已经转到资本家手里，不管他是单个资本家，还是象股份公司那样的结合资本家。","language":"中文","translation":false},{"id":"capital-12-25","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"在人类文化初期，在狩猎民族中，或者例如在印度公社的农业中，我们所看到的那种在劳动过程中占统治地位的协作，一方面以生产条件的公有制为基础，另一方面，正象单个蜜蜂离不开蜂房一样，以个人尚未脱离氏族或公社的脐带这一事实为基础。这两点使得这种协作不同于资本主义协作。在古代世界、中世纪和现代的殖民地偶尔采用的大规模协作，以直接的统治关系和从属关系为基础，大多数以奴隶制为基础。相反，资本主义的协作形式一开始就以出卖自己的劳动力给资本的自由雇佣工人为前提。不过，历史地说，资本主义的协作形式是同农民经济和独立的手工业生产（不管是否具有行会形式）相对立而发展起来的。对农民经济和独立的手工业生产来说，资本主义协作好象不是协作的一个特殊的历史形式，而协作本身倒好象是资本主义生产过程所固有的并表示其特征的历史形式。","language":"中文","translation":false},{"id":"capital-12-26","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"正如协作发挥的劳动的社会生产力表现为资本的生产力一样，协作本身表现为同单个的独立劳动者或小业主的生产过程相对立的资本主义生产过程的特有形式。这是实际的劳动过程由于隶属于资本而经受的第一个变化。这种变化是自然发生的。这一变化的前提，即在同一个劳动过程中同时雇用较大量的雇佣工人，构成资本主义生产的起点。这个起点是和资本本身的存在结合在一起的。因此，一方面，资本主义生产方式表现为劳动过程转化为社会过程的历史必然性，另一方面，劳动过程的这种社会形式表现为资本通过提高劳动过程的生产力来更有利地剥削劳动过程的一种方法。","language":"中文","translation":false},{"id":"capital-12-27","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"上面所考察的简单形态的协作，是同规模较大的生产结合在一起的，但是并不构成资本主义生产方式的一个特殊发展时代的固定的特殊形式。它至多不过在仍然保持手工业性质的初期工场手工业中，在那种和工场手工业时期相适应的、仅仅由于同时使用的工人数量和所积聚的生产资料的规模才和农民经济有本质区别的大农业中，近似地表现出来。简单协作在那些大规模运用资本而分工或机器还不起重大作用的生产部门，始终是占统治的形式。","language":"中文","translation":false},{"id":"capital-12-28","author":"马克思","title":"资本论·第一卷","location":"第十一章 协作","page":12,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/11.htm","text":"虽然协作的简单形态本身表现为同它的更发展的形式并存的一种特殊形式，协作仍然是资本主义生产方式的基本形式。","language":"中文","translation":false},{"id":"capital-13-1","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-13-2","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"第十二章 分工和工场手工业","language":"中文","translation":false},{"id":"capital-13-3","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"1、工场手工业的二重起源","language":"中文","translation":false},{"id":"capital-13-4","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"以分工为基础的协作，在工场手工业上取得了自己的典型形态。这种协作，作为资本主义生产过程的特殊形式，在真正的工场手工业时期占居统治地位。这个时期大约从十六世纪中叶到十八世纪末叶。","language":"中文","translation":false},{"id":"capital-13-5","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业是以两种方式产生的。","language":"中文","translation":false},{"id":"capital-13-6","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"一种方式是：不同种的独立手工业的工人在同一个资本家的指挥下联合在一个工场里，产品必须经过这些工人之手才能最后制成。例如，马车过去是很多独立手工业者，如马车匠、马具匠、裁缝、钳工、铜匠、旋工、饰绦匠、玻璃匠、彩画匠、油漆匠、描金匠等劳动的总产品。马车工场手工业把所有这些不同的手工业者联合在一个工场内，他们在那里协力地同时进行劳动。当然，一辆马车在制成以前是不能描金的。但是，如果同时制造许多辆马车，那末，当一部分马车还处在生产过程的较早阶段的时候，另一部分马车就可以不断地描金。到此为止，我们的立足点还是简单协作，它在人和物方面的材料都是现成的。但是很快就发生了本质的变化。专门从事马车制造的裁缝、钳工、铜匠等等，逐渐地失去了全面地从事原有手工业的习惯和能力。另一方面，他们的片面活动现在取得了一种最适合于狭隘活动范围的形式。起初，马车工场手工业是作为独立手工业的结合出现的。以后，马车生产逐渐地分成了各种特殊的操作，其中每一种操作都形成为一个工人的专门职能，全部操作由这些局部工人联合体来完成。同样，织物工场手工业以及一系列其他工场手工业，也是由不同的手工业在同一个资本的指挥下结合起来而产生的。","language":"中文","translation":false},{"id":"capital-13-7","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"但是，工场手工业也以相反的方式产生。许多从事同一个或同一类工作（例如造纸、铸字或制针）的手工业者，同时在同一个工场里为同一个资本所雇用。这是最简单形式的协作。每个这样的手工业者（可能带一两个帮工）都制造整个商品，因而顺序地完成制造这一商品所需要的各种操作。他仍然按照原有的手工业方式进行劳动。但是外部情况很快促使人们按照另一种方式来利用集中在同一个场所的工人和他们同时进行的劳动。例如，必须在一定期限内提供大量完成的商品这种情况，就是如此。于是劳动有了分工。各种操作不再由同一个手工业者按照时间的先后顺序完成，而是分离开来，孤立起来，在空间上并列在一起，每一种操作分配给一个手工业者，全部操作由协作工人同时进行。这种偶然的分工一再重复，显示出它特有的优越性，并渐渐地固定为系统的分工。商品从一个要完成许多种操作的独立手工业者的个人产品，变成了不断地只完成同一种局部操作的各个手工业者的联合体的社会产品。一个德国的行会造纸匠要依次完成的、互相连接的那些操作，在荷兰的造纸手工工场里独立化为许多协作工人同时进行的局部操作。纽伦堡的行会制针匠是英国制针手工工场的基本要素。但是纽伦堡的一个制针匠可能要依次完成20种操作，而在英国，将近20个制针匠同时进行工作，每一个人只从事一种操作，后来，这20种操作根据经验又进一步划分、孤立，并独立化为各个工人的专门职能。","language":"中文","translation":false},{"id":"capital-13-8","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"可见，工场手工业的产生方式，它由手工业形成的方式，是二重的。一方面，它以不同种的独立手工业的结合为出发点，这些手工业非独立化和片面化到了这种程度，以致它们在同一个商品的生产过程中成为只是互相补充的局部操作。另一方面，工场手工业以同种手工业者的协作为出发点，它把这种个人手工业分成各种不同的特殊操作，使之孤立，并且独立化到这种程度，以致每一种操作成为特殊工人的专门职能。因此，一方面工场手工业在生产过程中引进了分工，或者进一步发展了分工，另一方面它又把过去分开的手工业结合在一起。但是不管它的特殊的出发点如何，它的最终形态总是一样的：一个以人为器官的生产机构。","language":"中文","translation":false},{"id":"capital-13-9","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"为了正确地理解工场手工业的分工，把握住下列各点是很重要的。首先，在这里生产过程分解为各个特殊阶段是同手工业活动分成各种不同的局部操作完全一致的。不管操作是复杂还是简单，它仍然是手工业性质的，因而仍然取决于每个工人使用工具时的力量、熟练、速度和准确。手工业仍旧是基础。这种狭隘的技术基础使生产过程得不到真正科学的分解，因为产品所经过的每一个局部过程都必须作为局部的手工业劳动来完成。正因为手工业的熟练仍旧是生产过程的基础，所以每一个工人都只适合于从事一种局部职能，他的劳动力变成了终身从事这种局部职能的器官。最后，这种分工是一种特殊的协作，它的许多优越性都是由协作的一般性质产生的，而不是由协作的这种特殊形式产生的。","language":"中文","translation":false},{"id":"capital-13-10","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"如果我们进行更仔细的考察，那末首先就可以清楚地看到，终生从事同一种简单操作的工人，把自己的整个身体变成这种操作的自动的片面的器官，因而他花费在这一操作上的时间，比循序地进行整个系列的操作的手工业者要少。但是，构成工场手工业活机构的结合总体工人，完全是由这些片面的局部工人组成的。因此，与独立的手工业比较，在较短时间内能生产出较多的东西，或者说，劳动生产力提高了。在局部劳动独立化为一个人的专门职能之后，局部劳动的方法也就完善起来。经常重复做同一种有限的动作，并把注意力集中在这种有限的动作上，就能够从经验中学会消耗最少的力量达到预期的效果。又因为总是有好几代工人同时在一起生活，在同一些手工工场内共同劳动，因此，这样获得的技术上的诀窍就能巩固、积累并迅速地传下去。","language":"中文","translation":false},{"id":"capital-13-11","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业在工场内部把社会上现存的各种手工业的自然分立再生产出来，并系统地把它发展到极端，从而在实际上生产出局部工人的技艺。另一方面，工场手工业把局部劳动变为一个人的终生职业，符合以前社会的如下倾向：使手工业变成世袭职业，使它固定为种姓，或当一定历史条件产生与种姓制度相矛盾的个人变化时，使它硬化为行会。种姓和行会由以产生的自然规律，就是调节动植物分化为种和亚种的那个自然规律。不同的只是，种姓的世袭性和行会的排他性发展到一定程度会当作社会法令来颁布。","language":"中文","translation":false},{"id":"capital-13-12","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“达卡的凡而纱的精细，科罗曼德耳的花布及其他布匹的色彩的华丽和耐久，始终是无与伦比的。但是这些布匹的生产并没有依靠资本、机器和分工或者任何一种使欧洲制造业获得很多益处的手段。织工是单独的个人，他是根据顾客的订货织布的。他使用的织机的结构非常简单，有时候只是用木条草草搭成的。这种织机甚至没有整经装置，因此机身必须全部伸展开来，这样它就很笨重，很长，无法放在生产者的小屋中，因此生产者必须在露天劳动，一遇到坏天气，就只好停工。”","language":"中文","translation":false},{"id":"capital-13-13","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"正是父传子、子传孙一代一代积累下来的特殊熟练，才使印度人具有蜘蛛一样的技艺。但是同大多数工场手工业的工人相比，这样一个印度织工从事的是极复杂的劳动。","language":"中文","translation":false},{"id":"capital-13-14","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"一个在制品的生产中依次完成各个局部过程的手工业者，必须时而变更位置，时而调换工具。由一种操作转到另一种操作会打断他的劳动进程，造成他的工作日中某种空隙。一旦手工业者整天不断地从事同一种操作，这些空隙就会缩小，或者说会随着他的操作变化的减少而趋于消失。在这里，劳动生产率的提高，或者是由于增加了一定时间内劳动力的支出，也就是提高了劳动强度，或者是由于减少了劳动力的非生产耗费。就是说，每次由静止到运动所需要的力量的额外消耗，为已经达到的正常速度在较长时间的持续所补偿。另一方面，不断从事单调的劳动，会妨碍精力的集中和焕发，因为精力是在活动本身的变换中得到恢复和刺激的。","language":"中文","translation":false},{"id":"capital-13-15","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"劳动生产率不仅取决于劳动者的技艺，而且也取决于他的工具的完善程度。同类的工具，例如切削工具、钻具、凿具和锤具等，用于不同的劳动过程，而同一种工具在同一劳动过程中又用于不同的操作。但是，一旦劳动过程的不同操作彼此分离，并且每一种局部操作在局部工人手中获得最合适的因而是专门的形式，过去用于不同目的的工具就必然要发生变化。工具形式变化的方向，是根据从工具原来形式带来的特殊困难中得出的经验决定的。劳动工具的分化和劳动工具的专门化，是工场手工业的特征，前者使同类的工具获得了适合于每种特殊用途的特殊的固定形式，后者使每种这样的特殊的工具只有在专门的局部工人的手中才能充分发挥作用。单在北明翰就生产出约500种不同的锤，不但每一种锤只适用于一个特殊的生产过程，而且往往好多种锤只用于同一过程的不同操作。工场手工业时期通过劳动工具适合于局部工人的专门的特殊职能，使劳动工具简化、改进和多样化。这样，工场手工业时期也就同时创造了机器的物质条件之一，因为机器就是由许多简单工具结合而成的。","language":"中文","translation":false},{"id":"capital-13-16","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"局部工人及其工具构成工场手工业的简单要素。现在我们来考察工场手工业的全貌。","language":"中文","translation":false},{"id":"capital-13-17","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"3、工场手工业的两种基本形式——混成的工场手工业和有机的工场手工业","language":"中文","translation":false},{"id":"capital-13-18","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业的组织有两种基本形式。这两种形式虽然有时交错在一起，但仍然是两个本质上不同的类别，而且特别在工场手工业后来转化为使用机器的大工业时，起着完全不同的作用。这种二重性起源于制品本身的性质。制品或者是由各个独立的局部产品纯粹机械地组合而成，或者是依次经过一系列互相关联的过程和操作而取得完成的形态。","language":"中文","translation":false},{"id":"capital-13-19","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"例如，机车是由5000多个独立部件组成的。但是它不能算作第一类真正工场手工业的例子，因为它是大工业的产物。钟表才是最好的例子。威廉·配第就已经用它来说明工场手工业的分工。钟表从纽伦堡手工业者的个人制品，变成了无数局部工人的社会产品。这些局部工人是：毛坯工、发条工、字盘工、游丝工、钻石工、棘轮掣子工、指针工、表壳工、螺丝工、镀金工，此外还有许多小类，例如制轮工（又分黄铜轮工和钢轮工）、龆轮工、上弦拨针机构工、装轮工（把轮安到轴上，并把它抛光等等）、轴颈工、齿轮安装工（把各种齿轮和龆轮安装到机心中去）、切齿工（切轮齿，扩孔，把棘爪簧和棘爪淬火）、擒纵机构工、圆柱形擒纵机构又有圆筒工、擒纵轮片工、摆轮工、快慢装置工（调节钟表快慢的装置）、擒纵调速器安装工，还有条合和棘爪安装工、钢抛光工、齿轮抛光工、螺丝抛光工、描字工、制盘工（把搪瓷涂到铜上）、表壳环制造工、装销钉工（把黄铜销钉插入表壳的接头等）、表壳弹簧制造工（制造能使表壳弹起来的弹簧）、雕刻工、雕镂工、表壳抛光工以及其他工人，最后是装配全表并使其行走的装配工。只有钟表的少数几个零件要经过不同的人的手，所有这些分散的肢体只是在最终把它们结合成一个机械整体的人的手中才集合在一起。在这里，同在其他类似的制品上一样，成品和它的各种不同的要素的外在关系，使局部工人在同一个工场中的结合成为一种偶然的事情。局部劳动本身又可以作为彼此独立的手工业进行，如在瓦得州和纽沙特尔州就是这样；在日内瓦则有大钟表手工工场，也就是说，那里局部工人在一个资本指挥下进行直接的协作。但即使在日内瓦，指针盘、发条和表壳也很少是在本手工工场内制造的。在这里，结合的工场手工业生产，只有在例外的情形下才是有利的，因为在家里劳动的工人之间的竞争十分激烈，生产分为许多性质不同的过程，使人们不大可能使用共同的劳动资料；而且在分散生产的情况下，资本家可节省厂房等的费用。不过，这些在家里为一个资本家（工厂主）劳动的局部工人的地位，也是和仅仅为自己的顾客劳动的独立手工业者的地位完全不同的。","language":"中文","translation":false},{"id":"capital-13-20","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"第二类工场手工业，是工场手工业的完成形式，它生产的制品要经过相互联系的发展阶段，要顺序地经过一系列的阶段过程，例如，制针手工工场的针条要经过72个甚至92个专门的局部工人之手。","language":"中文","translation":false},{"id":"capital-13-21","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"由于这种工场手工业把原来分散的手工业结合在一起，因此就缩短了制品的各个特殊生产阶段之间的空间距离。制品从一个阶段转移到另一阶段所需要的时间减少了，同样，用在这种转移上的劳动也减少了。这样，同手工业相比，劳动生产力提高了，这种提高是由工场手工业的一般协作性质产生的。另一方面，工场手工业特有的分工原则，使不同的生产阶段孤立起来，这些阶段作为同数的手工业性质的局部劳动而互相独立。既然各个孤立的职能之间要建立和保持联系，制品就得不断地由一个人之手转到另一个人之手，由一个过程转到另一个过程。从大工业的角度来看，这种情形表现为一种特殊的、破费的、工场手工业原则所固有的局限性。","language":"中文","translation":false},{"id":"capital-13-22","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"如果我们考察一定量的原料（如造纸手工工场的破布或者制针手工工场的针条），就可以看到，这些原料在获得自己的最后形态之前，要在不同的局部工人手中经过时间上顺序进行的各个生产阶段。但如果把工场看作一个总机构，那末原料就同时处在它的所有的生产阶段上。由局部工人组成的总体工人，用他的许多握有工具的手的一部分拉针条，同时用另一些手和工具把针条拉直、切断、磨尖等等。不同的阶段过程由时间上的顺序进行变成了空间上的并存。因此在同一时间内可以提供更多的成品。虽然这种同时性是由总过程的一般协作形式产生的，但是工场手工业不只是找到了现成的协作条件，而且还通过分解手工业的活动部分地创造出协作条件。另一方面，工场手工业所以能够达到劳动过程的这种社会组织，只是因为同一个工人固定在同一局部工作上。","language":"中文","translation":false},{"id":"capital-13-23","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"因为每个局部工人的局部产品同时只是同一制品的特殊的发展阶段，所以，一个工人是给另一个工人，或一组工人是给另一组工人提供原料。一个工人的劳动结果，成了另一个工人劳动的起点。因此在这里，一个工人是直接给另一个工人提供工作。在每一局部过程中，取得预期效果所必要的劳动时间是根据经验确定的，工场手工业总机构是以一定的劳动时间内取得一定的结果为前提的。只有在这个前提下，互相补充的各个劳动过程才能不间断地、同时地、空间上并存地进行下去。很明显，各种劳动因而各个工人之间的这种直接的互相依赖，迫使每个工人在自己的职能上只使用必要的时间，因此在这里形成了和独立手工业中，甚至和简单协作中完全不同的连续性、划一性、规则性、秩序性，特别是劳动强度。在一种商品上只应耗费生产该商品的社会必要劳动时间，这在商品生产的条件下表现为竞争的外部强制，因为肤浅地说，每一个生产者都必须按商品的市场价格出售商品。而在工场手工业中，在一定劳动时间内提供一定量的产品，成了生产过程本身的技术规律。","language":"中文","translation":false},{"id":"capital-13-24","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"但是，不同的操作需要不等的时间，因此在相等的时间内会提供不等量的局部产品。因此，要使同一个工人每天总是只从事同一种操作，不同的操作就必须使用不同比例数的工人。例如在活字铸造业中，如果一个铸工每小时能铸2000个字，一个分切工能截开4000个字，一个磨字工能磨8000个字，雇用一个磨字工就需要雇用4个铸工和2个分切工。在这里，又回到了最简单形式的协作原则：同时雇用许多人从事同种工作。但现在这个原则表现为一种有机的关系。因此，工场手工业的分工不仅使社会总体工人的不同性质的器官简单化和多样化，而且也为这些器官的数量大小，即为从事每种专门职能的工人小组的相对人数或相对量，创立了数学上固定的比例。工场手工业的分工在发展社会劳动过程的质的划分的同时，也发展了它的量的规则和比例性。","language":"中文","translation":false},{"id":"capital-13-25","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"如果各个不同的局部工人小组之间最合适的比例数，已由经验为一定的生产规模确定下来，那末，只有使每个特殊工人小组按倍数增加，才能扩大这个生产规模。此外，某些工作，不管规模大些或小些，都可以由同一个人来做。例如，总监督的工作，把局部产品由一个生产阶段运送到另一个生产阶段的工作等等，就是如此。因此，使这些职能独立，或者把它们交给特殊工人，只有在增加雇佣工人人数的情况下，才是有利的，但是这种增加必须立刻在所有小组中按比例实行。","language":"中文","translation":false},{"id":"capital-13-26","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"一个小组，即执行同一局部职能的一定数目的工人，是由同质的要素组成的，并且构成总机构的一个特殊器官。但在某些手工工场，这种小组本身就是一个已经组织好了的劳动体，而总机构由这些基本的生产机体的重复或倍加形成。拿制瓶手工工场为例。这种工场分为三个本质不同的阶段，第一个阶段是预备阶段：调制玻璃的配料，把砂、石灰等等混合在一起，并把这种混合物熔化为玻璃液。最后阶段是把瓶从焙烧炉中取出，分类，包装等等。这两个阶段都使用了不同的局部工人。在这两个阶段之间是真正的玻璃生产即对玻璃液的加工。在玻璃炉的每一个口旁都有一个小组在工作。这种小组在英国叫做“炉口”，它由一个制瓶工或精制工、一个吹瓶工、一个收集工、一个堆积工或研磨工和一个搬入工组成。这五个局部工人形成一个单一的劳动体的五个特殊器官。这个劳动体只有作为一个整体，即只有通过五个人的直接协作才能起作用。如果这个由五个部分构成的躯体少了一个成员，它就瘫痪了。但一个玻璃炉有好几个炉口，例如在英国有4—6个炉口，每个炉口都有一个盛玻璃液的土制坩埚，并且有一个同样由五个成员组成的工人小组。在这里，每个组的组织都直接以分工为基础，而各个同类小组之间的联系则是一种简单的协作，在这种协作下，生产资料之一（这里是玻璃炉）由于共同使用而得到更经济的利用。这种有4—6个小组的玻璃炉，构成一个玻璃作坊；而一个玻璃手工工场有几个这样的作坊，同时还要有生产的最初阶段和最后阶段所需的各种设备和工人。","language":"中文","translation":false},{"id":"capital-13-27","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"最后，正如工场手工业部分地由不同手工业结合而成一样，工场手工业又能发展为不同的工场手工业的结合。例如，英国的大玻璃工场自己制造土制坩埚，因为产品的优劣主要取决于坩埚的质量。在这里，制造生产资料的工场手工业同制造产品的工场手工业联合起来了。反过来，制造产品的工场手工业，也可以同那些又把它的产品当作原料的工场手工业，或者同那些把它的产品与自己的产品结成一体的工场手工业联合起来。例如，我们看到制造燧石玻璃的工场手工业同磨玻璃业和铸铜业（为各种玻璃制品镶嵌金属）结合在一起。在这种场合，不同的结合的工场手工业成了一个总工场手工业在空间上多少分离的部门，同时又是各有分工的、互不依赖的生产过程。结合的工场手工业虽有某些优点，但它不能在自己的基础上达到真正的技术上的统一。这种统一只有在工场手工业转化为机器生产时才能产生。","language":"中文","translation":false},{"id":"capital-13-28","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业时期很快就宣布减少生产商品所必要的劳动时间是自觉的原则，因此也就间或使用机器，特别是在某些需要大量人力、费力很大的简单的最初的过程。例如，在造纸手工工场很快就采用了粉碎磨来磨碎破布，在冶金业很快就采用了所谓的捣碎磨来捣碎矿石。罗马帝国以水磨的形式把一切机器的原始形式留传下来。手工业时期留下了指南针、火药、印刷术和自鸣钟等伟大的发明。但总的来说，正如亚当·斯密指出的，机器在分工之旁起着次要的作用。机器在十七世纪的间或应用是极其重要的，因为它为当时的大数学家创立现代力学提供了实际的支点和刺激。","language":"中文","translation":false},{"id":"capital-13-29","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业时期所特有的机器始终是由许多局部工人结合成的总体工人本身。一种商品的生产者顺序完成的、在其全部劳动过程中交织在一起的各种操作，向商品生产者提出各种不同的要求。在一种操作中，他必须使出较大的体力；在另一种操作中，他必须比较灵巧；在第三种操作中，他必须更加集中注意力，等等；而同一个人不可能在相同的程度上具备所有这些素质。在各种操作分离、独立和孤立之后，工人就按照他们的特长分开、分类和分组。如果说工人的天赋特性是分工赖以生长的基础，那末工场手工业一经采用，就会使生来只适宜于从事片面的特殊职能的劳动力得到发展。现在总体工人具备了技艺程度相同的一切生产素质，同时能最经济地使用它们，因为他使自己的所有器官分离而成为特殊的工人或工人小组，各自担任一种专门的职能。局部工人作为总体工人的一个器官，他的片面性甚至缺陷就成了他的优点。从事片面职能的习惯，使他变成本能地准确地起作用的器官，而总机构的联系迫使他以机器部件的规则性发生作用。","language":"中文","translation":false},{"id":"capital-13-30","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"由于总体工人的各种职能有的比较简单，有的比较复杂，有的比较低级，有的比较高级，因此他的器官，即各个劳动力，需要极不相同的教育程度，从而具有极不相同的价值。因此，工场手工业发展了劳动力的等级制度，与此相适应的是工资的等级制度。一方面，单个工人适应于一种片面的职能，终生从事这种职能；另一方面，各种劳动操作，也要适应这种由先天的和后天的技能构成的等级制度。然而，每一个生产过程都需要有一些任何人都能胜任的简单操作。现在，这一类操作也断绝了同内容较充实的活动要素的流动的联系，硬化为专门职能。","language":"中文","translation":false},{"id":"capital-13-31","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"因此，工场手工业在它掌握的每种手工业中，造成了一类所谓的非熟练工人，这些工人是手工业生产极端排斥的。工场手工业靠牺牲整个劳动能力使非常片面的专长发展成技艺，同时它又使没有任何发展成为专长。在等级制度的阶梯的旁边，工人简单地分为熟练工人和非熟练工人。对后者说来完全不需要学习费用，而对前者说来，由于职能的简化，学习费用比手工业者要低。在这两种场合，劳动力的价值都降低了。但也有例外，当劳动过程的分解产生了一些在手工业生产中根本没有过的，或者不是在同样大的范围内有过的新的综合的职能时，就是如此。由学习费用的消失或减少所引起的劳动力的相对贬值，直接包含着资本的更大的增殖，因为凡是缩短劳动力再生产所必要的时间的事情，都会扩大剩余劳动的领域。","language":"中文","translation":false},{"id":"capital-13-32","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"4、工场手工业内部的分工和社会内部的分工","language":"中文","translation":false},{"id":"capital-13-33","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"我们首先考察了工场手工业的起源，接着考察了它的简单要素——局部工人及其工具，最后考察了它的总机构。现在我们简单地叙述一下工场手工业分工和构成一切商品生产的一般基础的社会分工之间的关系。","language":"中文","translation":false},{"id":"capital-13-34","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"单就劳动本身来说，可以把社会生产分为农业、工业等大类，叫做一般的分工；把这些生产大类分为种和亚种，叫做特殊的分工；把工场内部的分工，叫做个别的分工。","language":"中文","translation":false},{"id":"capital-13-35","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"社会内部的分工以及个人被相应地限制在特殊职业范围内的现象，同工场手工业内部的分工一样，是从相反的两个起点发展起来的。在家庭内部，〔注：后来对人类原始状况的透彻的研究，使作者得出结论：最初不是家庭发展为氏族，相反地，氏族是以血缘为基础的人类社会的自然形成的原始形式。由于氏族纽带的开始解体，各种各样家庭形式后来才发展起来。——弗·恩·〕 随后在氏族内部，由于性别和年龄的差别，也就是在纯生理的基础上产生了一种自然的分工。随着公社的扩大，人口的增长，特别是各氏族间的冲突，一个氏族之征服另一个氏族，这种分工的材料也扩大了。另一方面，我在前面已经谈到，产品交换是在不同的家庭、氏族、公社互相接触的地方产生的，因为在文化的初期，以独立资格互相接触的不是个人，而是家庭、氏族等等。不同的公社在各自的自然环境中，找到不同的生产资料和不同的生活资料。因此，它们的生产方式、生活方式和产品，也就各不相同。这种自然的差别，在公社互相接触时引起了产品的互相交换，从而使这些产品逐渐变成商品。交换没有造成生产领域之间的差别，而是使不同的生产领域发生关系，并把它们变成社会总生产的多少互相依赖的部门。在这里，社会分工是由原来不同而又互不依赖的生产领域之间的交换产生的。而在那里，在以生理分工为起点的地方，直接互相联系的整体的各个特殊器官互相分开和分离，——这个分离过程的主要推动力是同其他公社交换商品，——并且独立起来，以致不同的劳动只有通过把产品当作商品来交换才能建立联系。在一种场合，原来独立的东西丧失了独立，在另一种场合，原来非独立的东西获得了独立。","language":"中文","translation":false},{"id":"capital-13-36","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"一切发达的、以商品交换为媒介的分工的基础，都是城乡的分离。可以说，社会的全部经济史，都概括为这种对立的运动。但是关于这种对立，我们不在这里多谈。","language":"中文","translation":false},{"id":"capital-13-37","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"一定量同时使用的工人，是工场手工业内部分工的物质前提，同样，人口数量和人口密度是社会内部分工的物质前提。在这里，人口数量和人口密度代替了工人在同一个工场内的密集。但是人口密度是一种相对的东西。人口较少但交通工具发达的国家，比人口较多但交通工具不发达的国家有更加密集的人口；从这个意义上说，例如，美国北部各州的人口比印度的人口更加稠密。","language":"中文","translation":false},{"id":"capital-13-38","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"因为商品生产和商品流通是资本主义生产方式的一般前提，所以工场手工业的分工要求社会内部的分工已经达到一定的发展程度。相反地，工场手工业分工又会发生反作用，发展并增加社会分工。随着劳动工具的分化，生产这些工具的行业也日益分化。一旦工场手工业的生产扩展到这样一种行业，即以前作为主要行业或辅助行业和其他行业联系在一起、并由同一生产者经营的行业，分离和互相独立的现象就会立即发生。一旦工场手工业的生产扩展到某种商品的一个特殊的生产阶段，该商品的各个生产阶段就变成各种独立的行业。前面已经指出，在制品是一个由局部产品纯粹机械地组合成的整体的地方，局部劳动又可以独立化为特殊的手工业。为了使工场手工业内部的分工更完善，同一个生产部门，根据其原料的不同，根据同一种原料可能具有的不同形式，而分成不同的有时是崭新的工场手工业。例如，十八世纪上半叶，单在法国就织出了100多种不同的丝织品；例如，在阿维尼翁，法律曾规定“每个学徒始终只能从事一种产品的制造，不得同时学几种产品的制造方法”。把一定生产部门固定在国家一定地区的地域分工，由于利用各种特点的工场手工业生产的出现，获得了新的推动力。在工场手工业时期，世界市场的扩大和殖民制度（二者属于工场手工业时期的一般存在条件），为社会内部的分工提供了丰富的材料。在这里，我们不去进一步论证，分工除了扩展到经济领域以外，又怎样扩展到社会的其他一切领域，怎样到处为专业化、专门化的发展，为人的细分奠定基础，以致亚·斯密的老师亚·弗格森曾经叫喊说：“我们成了奴隶民族，我们中间没有自由人”。","language":"中文","translation":false},{"id":"capital-13-39","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"社会内部的分工和工场内部的分工，尽管有许多相似点和联系，但二者不仅有程度上的差别，而且有本质的区别。在一种内在联系把不同的生产部门连结起来的地方，这种相似点无可争辩地表现得最为明显。例如，牧人生产毛皮，皮匠把毛皮变成皮革，鞋匠把皮革变成皮靴。在这里，每个人所生产的只是一种中间制品，而最后的完成的形态是他们的特殊劳动的结合产品。此外，还有供给牧人、皮匠和鞋匠以生产资料的各种劳动部门。有人可能象亚·斯密那样，认为这种社会分工和工场手工业分工的区别只是主观的，也就是说，只是对观察者才存在的，因为观察者在工场手工业中一眼就可以在空间上看到各种各样局部劳动，而在社会生产中，各种局部劳动分散在广大的面上，每个特殊部门都雇用大量的人，因而使这种联系模糊不清。但是，使牧人、皮匠和鞋匠的独立劳动发生联系的是什么呢？那就是他们各自的产品都是作为商品而存在。反过来，工场手工业分工的特点是什么呢？那就是局部工人不生产商品。〔注：“但是再也没有什么东西可以叫做个人劳动的自然报酬。每个工人只生产整体的一个部分，由于每个部分单独就其本身来说没有任何价值或用处，因此没有东西工人可以拿来说：这是我的产品，我要留给我自己。”（《保护劳动反对资本的要求》1825年伦敦版第25页）这部出色著作的作者，就是前面引证过的托·霍吉斯金。〕 变成商品的只是局部工人的共同产品。社会内部的分工以不同劳动部门的产品的买卖为媒介；工场手工业内部各局部劳动之间的联系，以不同的劳动力出卖给同一个资本家，而这个资本家把它们作为一个结合劳动力来使用为媒介。工场手工业分工以生产资料积聚在一个资本家手中为前提；社会分工则以生产资料分散在许多互不依赖的商品生产者中间为前提。在工场手工业中，保持比例数或比例的铁的规律使一定数量的工人从事一定的职能；而在商品生产者及其生产资料在社会不同劳动部门中的分配上，偶然性和任意性发挥着自己的杂乱无章的作用。诚然，不同的生产领域经常力求保持平衡，一方面因为，每一个商品生产者都必须生产一种使用价值，即满足一种特殊的社会需要，而这种需要的范围在量上是不同的，一种内在联系把各种不同的需要量连结成一个自然的体系；另一方面因为，商品的价值规律决定社会在它所支配的全部劳动时间中能够用多少时间去生产每一种特殊商品。但是不同生产领域的这种保持平衡的经常趋势，只不过是对这种平衡经常遭到破坏的一种反作用。在工场内部的分工中预先地、有计划地起作用的规则，在社会内部的分工中只是在事后作为一种内在的、无声的自然必然性起着作用，这种自然必然性可以在市场价格的晴雨表的变动中觉察出来，并克服着商品生产者的无规则的任意行动。工场手工业分工以资本家对人的绝对权威为前提，人只是资本家所占有的总机构的部分；社会分工则使独立的商品生产者互相对立，他们不承认任何别的权威，只承认竞争的权威，只承认他们互相利益的压力加在他们身上的强制，正如在动物界中一切反对一切的战争多少是一切物种的生存条件一样。因此，资产阶级意识一方面把工场手工业分工，把工人终生固定从事某种局部操作，把局部工人绝对服从资本，歌颂为提高劳动生产力的劳动组织，同时又同样高声地责骂对社会生产过程的任何有意识的社会监督和调节，把这些说成是侵犯资本家个人的不可侵犯的财产权、自由和自决的“独创性”。工厂制度的热心的辩护士们在斥责社会劳动的任何一种普遍组织时，只会说这种组织将把整个社会变成一座工厂，这一点是很能说明问题的。","language":"中文","translation":false},{"id":"capital-13-40","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"在资本主义生产方式的社会中，社会分工的无政府状态和工场手工业分工的专制是互相制约的，相反地，在职业的分离是自然发展起来、随后固定下来、最后由法律加以巩固的早期社会形态中，一方面，呈现出一幅有计划和有权威地组织社会劳动的图画，另一方面，工场内部完全没有分工，或者分工只是在很狭小的范围内，或者只是间或和偶然地得到发展。","language":"中文","translation":false},{"id":"capital-13-41","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"例如，目前还部分地保存着的原始的规模小的印度公社，就是建立在土地公有、农业和手工业直接结合以及固定分工之上的，这种分工在组成新公社时成为现成的计划和略图。这种公社都是一个自给自足的生产整体，它们的生产面积从一百英亩至几千英亩不等。产品的主要部分是为了满足公社本身的直接需要，而不是当作商品来生产的，因此，生产本身与整个印度社会以商品交换为媒介的分工毫无关系。变成商品的只是剩余的产品，而且有一部分到了国家手中才变成商品，从远古以来就有一定量的产品作为实物地租流入国家手中。在印度的不同地区存在着不同的公社形式。形式最简单的公社共同耕种土地，把土地的产品分配给公社成员，而每个家庭则从事纺纱织布等等，作为家庭副业。除了这些从事同类劳动的群众以外，我们还可以看到一个“首领”，他兼任法官、警官和税吏；一个记帐员，登记农业帐目，登记和记录与此有关的一切事项；一个官吏，捕缉罪犯，保护外来旅客并把他们从一个村庄护送到另一村庄；一个边防人员，守卫公社边界防止邻近公社入侵；一个管水员，从公共蓄水池中分配灌溉用水；一个婆罗门，司理宗教仪式；一个教员，在沙土上教公社儿童写字读书；一个专管历法的婆罗门，以占星家的资格确定播种、收割的时间以及对各种农活有利和不利的时间；一个铁匠和一个木匠，制造和修理全部农具；一个陶工，为全村制造器皿；一个理发师，一个洗衣匠，一个银匠，有时还可以看到一个诗人，他在有些公社里代替银匠，在另外一些公社里代替教员。这十几个人的生活由全公社负担。如果人口增长了，就在未开垦的土地上按照旧公社的样子建立一个新的公社。公社的机构显示了有计划的分工，但是它不可能有工场手工业分工，因为对铁匠、木匠等等来说市场是不变的，至多根据村庄的大小，铁匠、陶工等等不是一个而是两个或三个。调节公社分工的规律在这里以自然规律的不可抗拒的权威起着作用，而每一个手工业者，例如铁匠等等，在他的工场内按照传统方式完成他职业范围内的一切操作，但是他是独立的，不承认任何权威。这些自给自足的公社不断地按照同一形式把自己再生产出来，当它们偶然遭到破坏时，会在同一地点以同一名称再建立起来，这种公社的简单的生产机体，为揭示下面这个秘密提供了一把钥匙：亚洲各国不断瓦解、不断重建和经常改朝换代，与此截然相反，亚洲的社会却没有变化。这种社会的基本经济要素的结构，不为政治领域中的风暴所触动。","language":"中文","translation":false},{"id":"capital-13-42","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"前面已经谈判，行会的规章严格限制一个行会师傅所能雇用的帮工的人数，有计划地阻止了行会师傅变成资本家。同样，行会师傅只能在他本人是师傅的那个手工业中雇用帮工。行会竭力抵制商人资本这种与它对立的、唯一自由的资本形式的任何侵入。商人可以购买任何商品，但是不能购买作为商品的劳动。他只许充当手工业产品的定购人。如果外部情况引起进一步的分工，现存的行会就分为几个亚种，或者在原有行会之外建立新的行会，但是各种手工业并不联合在一个工场内。因此，虽然行会组织造成的手工业的分离、孤立和发展是工场手工业时期的物质存在条件，但行会组织排斥了工场手工业的分工。总的说来，工人和他的生产资料还是互相结合的，就象蜗牛和它的甲壳互相结合一样，因而工场手工业的起码基础还不具备，也就是说，生产资料还没有独立化为资本而同工人相对立。","language":"中文","translation":false},{"id":"capital-13-43","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"整个社会内的分工，不论是否以商品交换为媒介，是各种社会经济形态所共有的，而工场手工业分工却完全是资本主义生产方式的独特创造。","language":"中文","translation":false},{"id":"capital-13-44","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"5、工场手工业的资本主义性质","language":"中文","translation":false},{"id":"capital-13-45","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"数量较多的工人受同一资本指挥，既是一般协作的自然起点，也是工场手工业的自然起点。反过来，工场手工业的分工又使所使用的工人人数的增加成为技术上的必要。现在，单个资本家所必需使用的最低限额的工人人数，要由现有的分工来规定。另一方面，要得到进一步分工的利益，就必须进一步增加工人人数，而且只能按倍数来增加。但是随着资本的可变部分的增加，资本的不变部分也必须增加，建筑物、炉子等共同生产条件的规模要扩大，原料尤其要增加，而且要比工人人数快得多地增加。由于分工，劳动生产力提高了，一定劳动量在一定时间内消耗的原料数量也就按比例增大。因此，单个资本家手中的资本最低限额越来越增大，或者说，社会的生活资料和生产资料越来越多地转化为资本，这是由工场手工业的技术性质产生的一个规律。","language":"中文","translation":false},{"id":"capital-13-46","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"在工场手工业中，也和在简单协作中一样，执行职能的劳动体是资本的存在形式。由许多单个的局部工人组成的社会生产机构是属于资本家的。因此，由各种劳动的结合所产生的生产力也就表现为资本的生产力。真正的工场手工业不仅使以前独立的工人服从资本的指挥和纪律，而且还在工人自己中间造成了等级的划分。简单协作大体上没有改变个人的劳动方式，而工场手工业却使它彻底地发生了革命，从根本上侵袭了个人的劳动力。工场手工业把工人变成畸形物，它压抑工人的多种多样的生产志趣和生产才能，人为地培植工人片面的技巧，这正象在拉普拉塔各州人们为了得到牲畜的皮或油而屠宰整只牲畜一样。不仅各种局部劳动分配给不同的个体，而且个体本身也被分割开来，成为某种局部劳动的自动的工具，这样，梅涅尼·阿格利巴把人说成只是人身体的一个片断这种荒谬的寓言就实现了。起初，工人因为没有生产商品的物质资料，把劳动力卖给资本，现在，他个人的劳动力不卖给资本，就得不到利用。它只有在一种联系中才发挥作用，这种联系只有在它出卖以后，在资本家的工场中才存在。工场手工业工人按其自然的性质没有能力做一件独立的工作，他只能作为资本家工场的附属物进行生产活动。正象耶和华的选民的额上写着他们是耶和华的财产一样，分工在工场手工业工人的身上打上了他们是资本的财产的烙印。","language":"中文","translation":false},{"id":"capital-13-47","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"独立的农民或手工业者所发挥（虽然是小规模地）的知识、判断力和意志，——他发挥这些东西，正如野蛮人把全部战争艺术当作他的个人机智来施展一样，——现在只是对整个工场说来才是必要的。生产上的智力在一个方面扩大了它的规模，正是因为它在许多方面消失了。局部工人所失去的东西，都集中在和他们对立的资本上面了。工场手工业分工的产物，就是物质生产过程的智力作为别人的财产和统治工人的力量同工人相对立。这个分离过程在简单协作中开始，在工场手工业中得到发展，在大工业中完成。在简单协作中，资本家在单个工人面前代表社会劳动体的统一和意志，工场手工业使工人畸形发展，变成局部工人，大工业则把科学作为一种独立的生产能力与劳动分离开来，并迫使它为资本服务。","language":"中文","translation":false},{"id":"capital-13-48","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"在工场手工业中，总体工人从而资本在社会生产力上的富有，是以工人在个人生产力上的贫乏为条件的。","language":"中文","translation":false},{"id":"capital-13-49","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“无知是迷信之母，也是工业之母。思索和想象会产生错误，但是手足活动的习惯既不靠思索，也不靠想象。因此，在最少用脑筋的地方，工场手工业也就最繁荣，所以，可以把工场看成一部机器，而人是机器的各个部分。”","language":"中文","translation":false},{"id":"capital-13-50","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"事实上，在十八世纪中叶，某些手工工场宁愿使用半白痴来从事某些简单的、然而构成工厂秘密的操作。亚·斯密说：","language":"中文","translation":false},{"id":"capital-13-51","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“大多数人的智力，必然由他们的日常活动发展起来。终生从事少数简单操作的人……没有机会运用自己的智力……他的迟钝和无知就达到无以复加的地步。”","language":"中文","translation":false},{"id":"capital-13-52","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"斯密在描述了局部工人的愚钝以后继续说：","language":"中文","translation":false},{"id":"capital-13-53","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“他的呆板的、单调的生活自然损害了他的进取精神…… 它甚至破坏了他的身体的活力，使他除了从事他所会的那种局部工作以外，不能精力充沛地持久地使用自己的力量。因此，他在自己的专门职业中的技能是靠牺牲他的智力的、社会的和军事的德性而取得的。但是，在每一个工业的文明的社会中，这是劳动贫民即广大人民群众必然陷入的境地。”","language":"中文","translation":false},{"id":"capital-13-54","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"为了防止由于分工而造成的人民群众的完全萎缩，亚·斯密建议由国家来实行国民教育，虽然是在极小的范围内进行。亚·斯密著作的法文译者和评注者热·加尔涅——他在法兰西第一帝国时自然地成了参议员——始终一贯地反对这一点。他认为，国民教育是同分工的基本规律相矛盾的；实行国民教育会“消灭我们的整个社会制度”。他说：","language":"中文","translation":false},{"id":"capital-13-55","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“象其他一切分工一样，体力劳动和脑力劳动之间的分离，随着社会〈他正确地使用了这个用语来表示资本、土地所有权和它们的国家〉的日益富裕而越来越明显、越来越确定。象其他任何分工一样，这种分工是过去进步的结果和未来进步的原因…… 政府应当反对这种分工并阻止它的自然进程吗？政府应当用一部分国家收入来试图使两类力求分开和分立的劳动混淆和混合起来吗？”","language":"中文","translation":false},{"id":"capital-13-56","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"某种智力上和身体上的畸形化，甚至同整个社会的分工也是分不开的。但是，因为工场手工业时期大大加深了劳动部门的这种社会分裂，另一方面，因为它以自己特有的分工才从生命的根源上侵袭着个人，所以工场手工业时期也首先给工业病理学提供了材料和刺激力。","language":"中文","translation":false},{"id":"capital-13-57","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“一个人如果应受死刑，对他的分割就叫做处死，如果他不应受死刑，对他的分割就叫做谋杀。对劳动的分割就是对民众的谋杀。”","language":"中文","translation":false},{"id":"capital-13-58","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"以分工为基础的协作，或者工场手工业，最初是自发地形成的。一旦它得到一定的巩固和扩展，它就成为资本主义生产方式的有意识的、有计划的和系统的形式。真正工场手工业的历史表明，工场手工业所特有的分工最初是如何根据经验，好象背着当事人获得适当的形式，但后来是如何象行会手工业那样，力图根据传统把一度找到的形式保持下来，在个别场合甚至把它保持了几百年。这种形式的变化，除了在次要事情上的变化以外，始终只是由于劳动工具的革命。现代工场手工业——在这里我不是指以机器为基础的大工业——或者如在大城市产生的服装工场手工业那样，找到了现成的“诗人的分散的肢体”，只需要把它们从分散状态集合起来；或者，分工的原则十分明显，只需要简单地把手工业生产（例如装订业）的各种操作分配给专门的工人。在这种情况下，用不着一个星期的经验，就能找到各种职能所必需的人手之间的比例数。〔注：有一种天真的信念，认为资本家个人在分工方面先验地运用了有发明能力的天才。这种信念还只保存在如罗雪尔先生那样的德国教授中间，在罗雪尔看来，分工是从资本家的丘必特式的脑袋中现成地跳出来的，因此他以“各种各样的工资”来酬谢资本家。实行分工的程度取决于钱袋的大小，而不取决于天才的大小。〕","language":"中文","translation":false},{"id":"capital-13-59","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业分工通过手工业活动的分解，劳动工具的专门化，局部工人的形成以及局部工人在一个总机构中的分组和结合，造成了社会生产过程的质的划分和量的比例，从而创立了社会劳动的一定组织，这样就同时发展了新的、社会的劳动生产力。工场手工业分工作为社会生产过程的特殊的资本主义形式，——它在当时的基础上只能在资本主义的形式中发展起来，——只是生产相对剩余价值即靠牺牲工人来加强资本（人们把它叫做社会财富，“国民财富”等等）自行增殖的一种特殊方法。工场手工业分工不仅只是为资本家而不是为工人发展社会劳动生产力，而且靠使各个工人畸形化来发展社会劳动生产力。它生产了资本统治劳动的新条件。因此，一方面，它表现为社会经济形成过程中的历史进步和必要的发展因素，另一方面，它又是文明的、精巧的剥削手段。","language":"中文","translation":false},{"id":"capital-13-60","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"政治经济学作为一门独立的科学，是在工场手工业时期才产生的，它只是从工场手工业分工的观点来考察社会分工，把社会分工看成是用同量劳动生产更多商品，从而使商品便宜和加速资本积累的手段。同这种着重量和交换价值的观点截然相反，古典古代的著作家只注重质和使用价值。由于社会生产部门的分离，商品就制造得更好，人的不同志趣和才能为自己选择到适宜的活动范围，如果没有限制，在任何地方都作不出重要的事情。因此，产品和生产者由于分工而得到改善。他们偶尔也提到产品数量的增加，但他们指的只是使用价值的更加丰富。他们根本没有想到交换价值，想到使商品便宜的问题。这种关于使用价值的观点既在柏拉图那里，也在色诺芬那里占统治地位。前者认为分工是社会分为等级的基础，后者则以他所特有的市民阶级的本能已经更加接近工场内部的分工。在柏拉图的理想国中，分工被说成是国家的构成原则，就这一点说，他的理想国只是埃及种姓制度在雅典的理想化；与柏拉图同时代的其他人，例如伊索克拉特斯，也把埃及看成是模范的工业国，甚至在罗马帝国时代的希腊人看来，它还保持着这种意义。","language":"中文","translation":false},{"id":"capital-13-61","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"在真正的工场手工业时期，即在工场手工业成为资本主义生产方式的统治形式的时期，充分实现工场手工业所特有的倾向遇到了多方面的障碍。虽然工场手工业，如我们已看到的，除了把工人分成等级以外，还把工人简单地分为熟练工人和非熟练工人，但是，由于熟练工人占压倒优势，非熟练工人人数仍然极其有限。虽然工场手工业使特殊操作适应于它的活的劳动器官的年龄、体力和发育的不同程度，从而迫切要求在生产上对妇女和儿童进行剥削，但总的说来，这种倾向由于习惯和男工的反抗而遭到破坏。虽然手工业活动的分解降低了工人的教育费用，从而降低了工人的价值，但较难的局部劳动仍然需要较长的学习时间，甚至在这种学习时间已成为多余的地方，工人还竭力要把它保留下来。例如，我们看到，英国的学习时间定为七年的学徒法，直到工场手工业时期的末期还完全有效，大工业才把它们废除。由于手工业的熟练仍然是工场手工业的基础，同时在工场手工业中执行职能的总机构没有任何不依赖工人本身的客观骨骼，所以资本不得不经常同工人的不服从行为作斗争。我们的朋友尤尔叫喊说：","language":"中文","translation":false},{"id":"capital-13-62","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“人类天性的弱点如此之大，以致工人越熟练，就越任性，越难驾驭，因此，工人不驯服的脾气给总机构造成巨大的损害。”","language":"中文","translation":false},{"id":"capital-13-63","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"因此，在整个工场手工业时期，都可听到关于工人缺乏纪律的怨言。即使我们没有当时的著作家的记载，但从十六世纪直到大工业时代，资本始终没有能够占有工场手工业工人全部可供支配的劳动时间，各种工场手工业生命短促，它们随着工人由国外迁入或迁往国外而由一国迁到另一国，这些最简单的事实就等于成千上万册的书。我们一再引用过的《论手工业和商业》的作者在1770年呼吁说：“必须用这种或那种方法把秩序建立起来。”六十六年以后，安得鲁·尤尔博士也说道，在以“经院式的分工教条”为基础的工场手工业中，还缺乏“秩序”，而“阿克莱建立了秩序”。","language":"中文","translation":false},{"id":"capital-13-64","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"同时，工场手工业既不能掌握全部社会生产，也不能根本改造它。工场手工业作为经济上的艺术品，耸立在城市手工业和农村家庭工业的广大基础之上。工场手工业本身的狭隘的技术基础发展到一定程度，就和它自身创造出来的生产需要发生矛盾。","language":"中文","translation":false},{"id":"capital-13-65","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业最完善的产物之一，是生产劳动工具本身特别是生产当时已经采用的复杂的机械装置的工场。尤尔说：","language":"中文","translation":false},{"id":"capital-13-66","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"“这种作坊展示了各种程度的分工。钻头、刀具、旋床各有各的工人，这些工人依照他们的熟练程度而分成等级。”","language":"中文","translation":false},{"id":"capital-13-67","author":"马克思","title":"资本论·第一卷","location":"第十二章 分工和工场手工业","page":13,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/12.htm","text":"工场手工业分工的这一产物，又生产出机器。机器使手工业的活动不再成为社会生产的支配原则。因此，一方面，工人终生固定从事某种局部职能的技术基础被消除了。另一方面，这个原则加于资本统治身上的限制也消失了。","language":"中文","translation":false},{"id":"capital-14-1","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-14-2","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"2、机器的价值向产品的转移","language":"中文","translation":false},{"id":"capital-14-3","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"3、机器生产对工人的直接影响","language":"中文","translation":false},{"id":"capital-14-4","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"5、工人和机器之间的斗争","language":"中文","translation":false},{"id":"capital-14-5","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"6、关于被机器排挤的工人会得到补偿的理论","language":"中文","translation":false},{"id":"capital-14-6","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"7、工人随机器生产的发展而被排斥和吸引。棉纺织业的危机","language":"中文","translation":false},{"id":"capital-14-7","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"8、大工业所引起的工场手工业、手工业和家庭劳动的革命","language":"中文","translation":false},{"id":"capital-14-8","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"9、工厂法(卫生条款和教育条款)。它在英国的普遍实行","language":"中文","translation":false},{"id":"capital-14-9","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"约翰·斯图亚特·穆勒在他的《政治经济学原理》一书中说道：","language":"中文","translation":false},{"id":"capital-14-10","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“值得怀疑的是，一切已有的机械发明，是否减轻了任何人每天的辛劳。”［注：穆勒应该说“任何不靠别人劳动过活的人”，因为机器无疑大大地增加了养尊处优的游惰者的人数。］","language":"中文","translation":false},{"id":"capital-14-11","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"但是，这也决不是资本主义使用机器的目的。象其他一切发展劳动生产力的方法一样，机器是要使商品便宜，是要缩短工人为自己花费的工作日部分，以便延长他无偿地给予资本家的工作日部分。机器是生产剩余价值的手段。","language":"中文","translation":false},{"id":"capital-14-12","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"生产方式的变革，在工场手工业中以劳动力为起点，在大工业中以劳动资料为起点。因此，首先应该研究，劳动资料如何从工具转变为机器，或者说，机器和手工业工具有什么区别。这里只能谈谈显著的一般的特征，因为社会史上的各个时代，正如地球史上的各个时代一样，是不能划出抽象的严格的界限的。","language":"中文","translation":false},{"id":"capital-14-13","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"数学家和力学家说，工具是简单的机器，机器是复杂的工具。某些英国经济学家也重复这种说法。他们看不到二者之间的本质区别，甚至把简单的机械力如杠杆、斜面、螺旋、楔等等也叫做机器。的确，任何机器都是由这些简单的力构成的，不管它怎样改装和组合。但是从经济学的观点来看，这种说明毫无用处，因为其中没有历史的要素。另一方面，还有人认为，工具和机器的区别在于：工具的动力是人，机器的动力是不同于人力的自然力，如牲畜、水、风等等。按照这种说法，在各个极不相同的生产时代存在的牛拉犁是机器，而一个工人用手推动的、每分钟可织96000个眼的克劳生式回转织机不过是工具了。而且，同一台织机，用手推动时是工具，用蒸汽推动时就成为机器了。既然畜力的使用是人类最古老的发明之一，那末，机器生产事实上就应该先于手工业生产了。当1735年约翰·淮亚特宣布他的纺纱机的发明，并由此开始十八世纪的工业革命时，他只字未提这种机器将不用人而用驴去推动，尽管它真是用驴推动的。淮亚特的说明书上说，这是一种“不用手指纺纱”的机器。","language":"中文","translation":false},{"id":"capital-14-14","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"所有发达的机器都由三个本质上不同的部分组成：发动机，传动机构，工具机或工作机。发动机是整个机构的动力。它或者产生自己的动力，如蒸汽机、卡路里机、电磁机等；或者接受外部某种现成的自然力的推动，如水车受落差水推动，风磨受风推动等。传动机构由飞轮、转轴、齿轮、蜗轮、杆、绳索、皮带、联结装置以及各种各样的附件组成。它调节运动，在必要时改变运动的形式(例如把垂直运动变为圆形运动)，把运动分配并传送到工具机上。机构的这两个部分的作用，仅仅是把运动传给工具机，由此工具机才抓住劳动对象，并按照一定的目的来改变它。机器的这一部分——工具机，是十八世纪工业革命的起点。在今天，每当手工业或工场手工业生产过渡到机器生产时，工具机也还是起点。","language":"中文","translation":false},{"id":"capital-14-15","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果我们仔细地看一下工具机或真正的工作机，那末再现在我们面前的，大体上还是手工业者和工场手工业工人所使用的那些器具和工具，尽管它们在形式上往往有很大改变。不过，现在它们已经不是人的工具，而是一个机构的工具或机械工具了。或者，整部机器只是旧手工业工具多少改变了的机械翻版，如机械织机；或者，装置在工作机机架上的工作器官原是老相识，如纺纱机上的锭子，织袜机上的针，锯木机上的锯条，切碎机上的刀等等。这些工具同工作机的真正机体的区别，甚至表现在它们的出生上：这些工具大部分仍然由手工业或工场手工业方式生产，然后才装到由机器生产的工作机的机体上。因此，工具机是这样一种机构，它在取得适当的运动后，用自己的工具来完成过去工人用类似的工具所完成的那些操作。至于动力是来自人还是来自另一台机器，这并不改变问题的实质。在真正的工具从人那里转移到机构上以后，机器就代替了单纯的工具。即使人本身仍然是原动力，机器和工具之间的区别也是一目了然的。人能够同时使用的工具的数量，受到人天生的生产工具的数量，即他自己身体的器官数量的限制。在德国，起初有人试图让一个纺纱工人踏两架纺车，也就是说，要他同时用双手双脚劳动。这太紧张了。后来有人发明了脚踏的双锭纺车，但是，能同时纺两根纱的纺纱能手几乎象双头人一样罕见。相反地，珍妮机一开始就能用12—18个纱锭，织袜机同时可用几千枚织针，等等。同一工作机同时使用的工具的数量，一开始就摆脱了工人的手工工具所受的器官的限制。","language":"中文","translation":false},{"id":"capital-14-16","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"作为单纯动力的人和作为真正操作工人的人之间的区别，在许多手工工具上表现得格外明显。例如，在纺车上，脚只起动力的作用，而在纱锭上工作即引纱和捻纱的手，则从事真正的纺纱操作。正是手工工具的这后一部分，首先受到了工业革命的侵袭。最初，工业革命除了使人从事用眼看管机器和用手纠正机器的差错这种新劳动外，还使人发挥纯机械的动力作用。相反地，原来只是用人当简单动力的那些工具，如推磨、抽水、拉风箱、捣臼等等，却最早采用了牲畜、水、风作为动力。这些工具部分地在工场手工业时期，个别地甚至在更早以前，就已经发展为机器，但并没有引起生产方式的革命。在大工业时期可以看出，这些工具甚至在它们的手工业形式上就已经是机器了。例如，1836—1837年荷兰人用来抽干哈勒姆湖水的水泵，就是按普通唧筒的原理设计的，不同的只是，它的活塞不是用人手来推动，而是用巨大的蒸汽机来推动。在英国，现在有时还把铁匠用的极不完善的普通风箱的把手同蒸汽机连接起来，而变成机械风箱。十七世纪末工场手工业时期发明的、一直存在到十八世纪八十年代初的那种蒸汽机，并没有引起工业革命。相反地，正是由于创造了工具机，才使蒸汽机的革命成为必要。一旦人不再用工具作用于劳动对象，而只是作为动力作用于工具机，人的肌肉充当动力的现象就成为偶然的了，人就可以被风、水、蒸汽等等代替了。当然，这种变更往往会使原来只以人为动力而设计的机构发生重大的技术变化。今天，所有还必须为自己开辟道路的机器，象缝纫机、制面包机等等，如果它们的性能一开始并不排斥小规模应用，那就会制造得既适合用人作动力，也适合用纯机械作动力。","language":"中文","translation":false},{"id":"capital-14-17","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"作为工业革命起点的机器，是用一个机构代替只使用一个工具的工人，这个机构用许多同样的或同种的工具一起作业，由一个单一的动力来推动，而不管这个动力具有什么形式。在这里我们就有了机器，但它还只是机器生产的简单要素。","language":"中文","translation":false},{"id":"capital-14-18","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工作机规模的扩大和工作机上同时作业的工具数量的增加，需要较大的发动机构。这个机构要克服它本身的阻力，就必需有比人力强大的动力，更不用说人是产生划一运动和连续运动的很不完善的工具了。假定人只是充当简单的动力，也就是说，工具机已经代替了人的工具，那末现在自然力也可以作为动力代替人。在工场手工业时期遗留下来的一切大动力中，马力是最坏的一种，这部分地是因为马有它自己的头脑，部分地是因为它十分昂贵，而且在工厂内使用的范围很有限。但在大工业的童年时期，马是常被使用的。除了当时的农业家的怨言外，一直到今天仍沿用马力来表示机械力这件事，就是证明。风太不稳定，而且无法控制；此外，在大工业的发源地英国，水力的应用在工场手工业时期就已经很普遍。早在十七世纪，就有人试用一架水车来推动两盘上磨，也就是两套磨。但是这时，传动机构规模的扩大同水力不足发生了冲突，这也是促使人们更精确地去研究摩擦规律的原因之一。同样，靠磨杆一推一拉来推动的磨，它的动力的作用是不均匀的，这又引出了飞轮的理论和应用。飞轮后来在大工业中起了非常重要的作用。大工业最初的科学要素和技术要素就是这样在工场手工业时期发展起来的。阿克莱的环锭精纺机最初是用水推动的。但使用水力作为主要动力有种种困难。水不能随意增高，在缺乏时不能补充，有时完全枯竭，而主要的是，它完全受地方的限制。直到瓦特发明第二种蒸汽机，即所谓双向蒸汽机后，才找到了一种原动机，它消耗煤和水而自行产生动力，它的能力完全受人控制，它可以移动，同时它本身又是推动的一种手段；这种原动机是在城市使用的，不象水车那样是在农村使用的，它可以使生产集中在城市，不象水车那样使生产分散在农村，它在工艺上的应用是普遍的，在地址选择上不太受地点条件的限制。瓦特的伟大天才表现在1784年4月他所取得的专利的说明书中，他没有把自己的蒸汽机说成是一种用于特殊目的的发明，而把它说成是大工业普遍应用的发动机。他在说明书中指出的用途，有一些(例如蒸汽锤)过了半个多世纪以后才被采用。但是他当时曾怀疑，蒸汽机能否应用到航海上。1851年，他的后继者，博耳顿－瓦特公司，在伦敦工业展览会上展出了远洋轮船用的最大的蒸汽机。","language":"中文","translation":false},{"id":"capital-14-19","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"只是在工具由人的机体的工具变为机械装置即工具机的工具以后，发动机才取得了独立的、完全摆脱人力限制的形式。于是，我们以上所考察的单个的工具机，就降为机器生产的一个简单要素了。现在，一台发动机可以同时推动许多工作机。随着同时被推动的工作机数量的增加，发动机也在增大，传动机构也跟着扩展成为一个庞大的装置。","language":"中文","translation":false},{"id":"capital-14-20","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"现在，必须把许多同种机器的协作和机器体系这两件事区别开来。","language":"中文","translation":false},{"id":"capital-14-21","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在前一场合，整个制品是由同一台工作机完成的。工作机完成各种不同的操作，这些操作原来是由一个手工业者用自己的工具(例如织布业者用自己的织布机)来完成的，或者是由若干手工业者独立地或作为一个手工工场的成员用各种工具顺次来完成的。例如，在现代的信封手工工场中，一个工人用折纸刀折纸，另一个工人涂胶水，第三个工人折边，预备印封面，第四个工人把封面印好，等等。每个信封，每经过一道局部操作，就要转一次手。一台信封制造机一下子完成所有这些操作，而且每小时制成3000多个信封。1862年伦敦工业展览会上展出的一台美国纸袋制造机，可以切纸、涂胶水、折纸，每分钟生产300个纸袋。在工场手工业中分成几种操作顺次进行的整个过程，现在由一台由各种工具结合而成的工作机来完成。不管这种工作机只是比较复杂的手工工具的机械复制品，还是由工场手工业专门化了的各种简单工具的结合，在工厂内，即在以机器生产为基础的工场内，总有简单协作重新出现，这种协作首先表现为同种并同时共同发生作用的工作机在空间上的集结(这里撇开工人不说)。例如，许多机械织机集结在同一厂房内便组成织布工厂，许多缝纫机集结在同一厂房内便组成缝纫厂。但这里存在着技术上的统一，因为这许多同种的工作机，都是同时并同等地从共同的原动机的心脏跳动中得到推动，这是通过传动机构传送来的，而传动机构对这些工作机来说也有一部分是共同的，因为它不过是分出一些特殊的分支同每个工具机相连结。正象许多工具只组成一个工作机的器官一样，许多工作机现在只组成同一个发动机构的同样的器官。","language":"中文","translation":false},{"id":"capital-14-22","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"但是，只有在劳动对象顺次通过一系列互相连结的不同的阶段过程，而这些过程是由一系列各不相同而又互为补充的工具机来完成的地方，真正的机器体系才代替了各个独立的机器。在这里，工场手工业所特有的以分工为基础的协作又出现了，但这种协作现在表现为各个局部工作机的结合。各种局部工人的专门工具，例如毛纺织手工工场中的弹毛工、梳毛工、起毛工、纺毛工等等所使用的工具，现在转化为各种专门化的工作机的工具，而每台工作机又在结合的工具机构的体系中成为一个特殊的器官，执行一种特殊的职能。在最先采用机器体系的部门中，工场手工业本身大体上为机器体系对生产过程的划分和组织提供了一个自然基础。但在工场手工业生产和机器生产之间一开始就存在着本质的区别。在工场手工业中，单个的或成组的工人，必须用自己的手工工具来完成每一个特殊的局部过程。如果说工人会适应这个过程，那末这个过程也就事先适应了工人。在机器生产中，这个主观的分工原则消失了。在这里，整个过程是客观地按其本身的性质分解为各个组成阶段，每个局部过程如何完成和各个局部过程如何结合的问题，由力学、化学等等在技术上的应用来解决，当然，在这里也象以前一样，理论的方案需要通过实际经验的大量积累才臻于完善。每一台局部机器依次把原料供给下一台，由于所有局部机器都同时动作，产品就不断地处于自己形成过程的各个阶段，不断地从一个生产阶段转到另一个生产阶段。在工场手工业中，局部工人的直接协作，在各个特殊工人小组之间造成一定的比例数，同样，在有组织的机器体系中，各局部机器之间不断地交接工作，也在各局部机器的数目、规模和速度之间造成一定的比例。结合工作机现在成了各种单个工作机和各组工作机的有组织的体系。结合工作机所完成的整个过程越是连续不断，即原料从整个过程的最初阶段转到最后阶段的中断越少，从而，原料越是不靠人的手而靠机构本身从一个生产阶段传送到另一个生产阶段，结合工作机就越完善。如果说，在工场手工业中，各特殊过程的分离是一个由分工本身得出的原则，那末相反，在发达的工厂中，起支配作用的是各特殊过程的连续性。","language":"中文","translation":false},{"id":"capital-14-23","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"一个机器体系，无论是象织布业那样，以同种工作机的单纯协作为基础，还是象纺纱业那样，以不同种工作机的结合为基础，只要它由一个自动的原动机来推动，它本身就形成一个大自动机。整个体系可以由例如蒸汽机来推动，虽然个别工具机在某些动作上还需要工人，例如在采用自动走锭精纺机以前，走锭精纺机口若悬河就需要工人发动，而精纺到现在都还是这样；或者，机器的某些部分必须象工具一样，要由工人操纵才能进行工作，例如在机器制造上，在转动刀架还未变成自动装置以前就是这样。当工作机不需要人的帮助就能完成加工原料所必需的一切运动，而只需要人从旁照料时，我们就有了自动的机器体系，不过，这个机器体系在细节方面还可以不断地改进。例如，断纱时使纺纱机自动停车的装置，梭中纬纱用完时使改良蒸汽织机立即停车的自动开关，都完全是现代的发明。现代造纸工厂可以说是生产的连续性和应用自动原理的范例。在纸张的生产上，我们可以详细而有益地研究以不同生产资料为基础的不同生产方式之间的区别，以及社会生产关系同这些生产方式之间的联系，因为德国旧造纸业为我们提供了这一部门的手工业生产的典型，十七世纪荷兰和十八世纪法国提供了真正工场手工业的典型，而现代英国提供了自动生产的典型，此外在中国和印度，直到现在还存在着这种工业的两种不同的古亚细亚的形式。","language":"中文","translation":false},{"id":"capital-14-24","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"通过传动机由一个中央自动机推动的工作机的有组织的体系，是机器生产的最发达的形态。在这里，代替单个机器的是一个庞大的机械怪物，它的躯体充满了整座整座的厂房，它的魔力先是由它的庞大肢体庄重而有节奏的运动掩盖着，然后在它的无数真正工作器官的疯狂的旋转中迸发出来。在专门制造蒸汽机、走锭精纺机等等的工人出现以前，走锭精纺机、蒸汽机等等就已经出现了，这正象在裁缝出现以前人就已经穿上了衣服一样。但是，沃康松、阿克莱、瓦特等人的发明之所以能够实现，只是因为这些发明家找到了相当数量的、在工场手工业时期就已准备好了的熟练的机械工人。这些工人中，一部分是各种职业的独立的手工业者，一部分是联合在象前面所说的分工非常严格的手工工场内的。随着发明的增多和对新发明的机器的需求的增加，一方面机器制造业日益分为多种多样的独立部门，另一方面制造机器的工场手工业内的分工也日益发展。这样，在这里，在工场手工业中，我们看到了大工业的直接的技术基础。工场手工业生产了机器，而大工业借助于机器，在它首先占领的那些生产领域排除了手工业生产和工场手工业生产。因此，机器生产是在与它不相适应的物质基础上自然兴起的。机器生产发展到一定程度，就必定推翻这个最初是现成地遇到的、后来又在其旧形式中进一步发展了的基础，建立起与它自身的生产方式相适应的新基础。正象在单个机器还要由人来推动时，它始终是一种小机器一样，正象在蒸汽机还没有代替现成的动力——牲畜、风以至水以前，机器体系不可能自由发展一样，当大工业特有的生产资料即机器本身，还要依靠个人的力量和个人的技巧才能存在时，也就是说，还取决于手工工场内的局部工人和手工工场外的手工业者用来操纵他们的小工具的那种发达的肌肉、敏锐的视力和灵巧的手时，大工业也就得不到充分的发展。所以，且不说这样生产出的机器很昂贵，——这种情况作为自觉的动机支配着资本，——已经使用机器的工业部门的扩大，以及机器向新的生产部门的渗入，完全取决于这样一类工人增加的情况，这类工人由于他们的职业带有半艺术性，只能逐渐地增加而不能飞跃地增加。但是，大工业发展到一定阶段，也在技术上同自己的手工业以及工场手工业基础发生冲突。发动机、传动机构和工具机的规模日益扩大；随着工具机摆脱掉最初曾支配它的构造的手工业型式而获得仅由其力学任务决定的自由形式，工具机的各个组成部分日益复杂、多样并具有日益严格的规则性；自动体系日益发展；难于加工的材料日益不可避免地被应用，例如以铁代替木材；——所有这些都是自然发生的问题，要解决这些问题到处都碰到人身的限制。这些限制甚至工场手工业中的结合工人也只能在一定程度上突破，而不能从根本上突破。例如，象现代印刷机、现代蒸汽织机和现代梳棉机这样的机器，就不是工场手工业所能制造的。","language":"中文","translation":false},{"id":"capital-14-25","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"一个工业部门生产方式的变革，必定引起其他部门生产方式的变革。这首先是指那些因社会分工而孤立起来以致各自生产独立的商品、但又作为总过程的阶段而紧密联系在一起的工业部门。因此，有了机器纺纱，就必须有机器织布，而这二者又使漂白业、印花业和染色业必须进行力学和化学革命。同样，另一方面，棉纺业的革命又引起分离棉花纤维和棉籽的轧棉机的发明，由于这一发明，棉花生产才有可能按目前所需要的巨大规模进行。但是，工农业生产方式的革命，尤其使社会生产过程的一般条件即交通运输工具的革命成为必要。正象以具有家庭副业的小农业和城市手工业为“枢纽”(我借用傅立叶的用语)的社会所拥有的交通运输工具，完全不能再满足拥有扩大的社会分工、集中的劳动资料和工人以及殖民地市场的工场手工业时期的生产需要，因而事实上已经发生了变革一样，工场手工业时期遗留下来的交通运输工具，很快又成为具有狂热的生产速度和巨大的生产规模、经常把大量资本和工人由一个生产领域投入另一个生产领域并具有新建立的世界市场联系的大工业所不能忍受的桎梏。因此，撇开已经完全发生变革的帆船制造业不说，交通运输业是逐渐地靠内河轮船、铁路、远洋轮船和电报的体系而适应了大工业的生产方式。但是，现在锻冶、锻接、切削、穿凿和铸造巨量的铁，又需要有庞大的机器，制造这样的机器是工场手工业的机器制造业所不能胜任的。","language":"中文","translation":false},{"id":"capital-14-26","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"因此，大工业必须掌握它特有的生产资料，即机器本身，必须用机器来生产机器。这样，大工业才建立起与自己相适应的技术基础，才得以自立。随着十九世纪最初几十年机器生产的发展，机器实际上逐渐掌握了工具机的制造。但只是到了最近几十年，由于大规模的铁路建设和远洋航运事业的发展，用来制造原动机的庞大机器才产生出来。","language":"中文","translation":false},{"id":"capital-14-27","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"用机器制造机器的最重要的生产条件，是要有能充分供给力量同时又完全受人控制的发动机。蒸汽机已经是这样的机器。但是，机器部件所必需的精确的几何形状，如直线、平面、圆、圆柱形、圆锥形和球形，也同时要用机器来生产。在十九世纪最初十年，亨利·莫兹利发明了转动刀架，解决了这个问题。这种刀架不久就改为自动式，经改装后从它最初被使用的旋床上移到其他制造机器的机器上。这种机械装置所代替的不是某种特殊工具，而是人的手本身。以往必须用手把切削工具等等的刃对准或加在劳动材料(如铁)上面，才能制造出一定的形状。现在有了这种装置，就能制造出机器部件的几何形状，而且","language":"中文","translation":false},{"id":"capital-14-28","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“轻易、精确和迅速的程度是任何最熟练工人的富有经验的手都无法做到的”。","language":"中文","translation":false},{"id":"capital-14-29","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果我们考察一下机器制造业所采用的机器中构成真正工具机的部分，那末，手工业工具就再现出来了，不过规模十分庞大。例如，钻床的工作机，是一个由蒸汽机推动的庞大钻头，没有这种钻头就不可能生产出大蒸汽机和水压机的圆筒。机械旋床是普通脚踏旋床的巨型翻版；刨床是一个铁木匠，它加工铁所用的工具就是木匠加工木材的那些工具；伦敦造船厂切割胶合板的工具是一把巨大的剃刀；剪裁机的工具是一把大得惊人的剪刀，它剪铁就象裁缝剪布一样；蒸汽锤靠普通的锤头工作，但这种锤头重得连托尔也举不起来。例如，奈斯密斯发明的这些蒸汽锤中，有一种重6吨多，从7呎的高度垂直落在36吨重的铁砧上。它能轻而易举地把一块花岗石打得粉碎，也能轻轻地一下一下地把钉子钉进柔软的木头里去。","language":"中文","translation":false},{"id":"capital-14-30","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"劳动资料取得机器这种物质存在方式，要求以自然力来代替人力，以自觉应用自然科学来代替从经验中得出的成规。在工场手工业中，社会劳动过程的组织纯粹是主观的，是局部工人的结合；在机器体系中，大工业具有完全客观的生产机体，这个机体作为现成的物质生产条件出现在工人面前。在简单协作中，甚至在因分工而专业化的协作中，社会化的工人排挤单个的工人还多少是偶然的现象。而机器，除了下面要谈的少数例外，则只有通过直接社会化的或共同的劳动才发生作用。因此，劳动过程的协作性质，现在成了由劳动资料本身的性质所决定的技术上的必要了。","language":"中文","translation":false},{"id":"capital-14-31","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"2、机器的价值向产品的转移","language":"中文","translation":false},{"id":"capital-14-32","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"我们已经知道，由协作和分工产生的生产力，不费资本分文。这是社会劳动的自然力。用于生产过程的自然力，如蒸汽、水等等，也不费分文。可是，正象人呼吸需要肺一样，人要在生产上消费自然力，就需要一种“人的手的创造物”。要利用水的动力，就要有水车，要利用蒸汽的压力，就要有蒸汽机。利用自然力是如此，利用科学也是如此。电流作用范围内的磁针偏离规律，或电流绕铁通过而使铁磁化的规律一经发现，就不费分文了。［注：科学不费资本家“分文”，但这丝毫不妨碍他们去利用科学。资本象吞并别人的劳动一样，吞并“别人的”科学。但是，对科学或物质财富的“资本主义的”占有和“个人的”占有，是截然不同的两件事。尤尔博士本人曾哀叹他的亲爱的、使用机器的工厂主对力学一窍不通。李比希也曾述说英国的化学工厂主对化学惊人地无知。］ 但是要在电报等方面利用这些规律，就需要有极昂贵的和复杂的设备。我们已经知道，工具并没有被机器排挤掉。它由人的机体的小工具，通过扩大规模，增加数量，发展成为由人创造的机构的工具。现在资本不要工人用手工工具去做工，而要工人用一个会自行操纵工具的机器去做工。因此，大工业把巨大的自然力和自然科学并入生产过程，必然大大提高劳动生产率，这一点是一目了然的。但是生产力的这种提高并不是靠在另一地方增加劳动消耗换来的，这一点却绝不是同样一目了然的。象不变资本的任何其他组成部分一样，机器不创造价值，但它把自身的价值转移到它所生产的产品上。就机器具有价值，从而把价值转给产品来说，它是产品价值的一个组成部分。机器不是使产品变便宜，而是使产品随着机器的价值相应地变贵。很明显，机器和发达的机器体系这种大工业特有的劳动资料，在价值上比手工业生产和工场手工业生产的劳动资料增大得无可比拟。","language":"中文","translation":false},{"id":"capital-14-33","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"首先应当指出，机器总是全部地进入劳动过程，始终只是部分地进入价值增殖过程。它加进的价值，决不会大于它由于磨损而平均丧失的价值。因此，机器的价值和机器定期转给产品的价值部分，有很大的差别。作为价值形成要素的机器和作为产品形成要素的机器，有很大的差别。同一机器在同一劳动过程中反复使用的时期越长，这种差别就越大。诚然，我们已经知道，每一种真正的劳动资料或生产工具，总是全部地进入劳动过程，始终只是根据它每天平均的损耗而部分地进入价值增殖过程。但是，使用和磨损之间的这种差别，在机器上比在工具上大得多，因为机器是由比较坚固的材料制成的，寿命较长；因为机器的使用要遵照严格的科学规律，能够更多地节约它的各个组成部分和它的消费资料的消耗；最后，因为机器的生产范围比工具的生产范围广阔无比。如果我们不算机器和工具二者每天的平均费用，即不算由于它们每天的平均损耗和机油、煤炭等辅助材料的消费而加到产品上的那个价值组成部分，那末，它们的作用是不需要代价的，同未经人类加工就已经存在的自然力完全一样。机器的生产作用范围越是比工具大，它的无偿服务的范围也就越是比工具大。只是在大工业中，人才学会让自己过去的、已经物化的劳动的产品大规模地、象自然力那样无偿地发生作用。","language":"中文","translation":false},{"id":"capital-14-34","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在考察协作和工场手工业时，我们知道，共同消费某些共同的生产条件(如建筑物等)，比单个工人消费分散的生产条件要节约，因而能使产品便宜一些。在机器生产中，不仅一个工作机的许多工具共同消费一个工作机的躯体，而且许多工作机共同消费同一个发动机和一部分传动机构。","language":"中文","translation":false},{"id":"capital-14-35","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果机器的价值和机器转给日产品的价值部分之间的差额已定，那末这个价值部分使产品变贵的程度，首先取决于产品的数量，就象是取决于产品的面积。布莱克本的培恩斯先生在1857年发表的一篇演讲中计算过：","language":"中文","translation":false},{"id":"capital-14-36","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“一实际的机械马力可以推动450个自动走锭精纺机纱锭及其附属设备，或者可以推动200个环锭精纺机纱锭，或者可以推动15台织宽40吋布的织布机以及整经、浆纱等装置。”","language":"中文","translation":false},{"id":"capital-14-37","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"一蒸汽马力每天的费用及其所推动的机器的损耗，在第一种情况下是分配在450个走锭精纺机纱锭的日产品上；在第二种情况下是分配在200个环锭精纺机纱锭的日产品上；在第三种情况下是分配在15台机械织机的日产品上。可见，转给一盎斯棉纱或一码布的只是极小的一部分价值。前面举的蒸汽锤的例子也是这样。因为蒸汽锤每天的磨损和煤炭的消耗等等是分配在它每天锤打的巨量的铁上，所以在每英担铁上只添加很小一部分价值；但如果用这个庞大的工具来钉小钉子，那末分配在每英担上的价值就会很大了。","language":"中文","translation":false},{"id":"capital-14-38","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果工作机的作用范围已定，也就是说，工作机的工具数量已定，或者在涉及到力的时候，工作机工具的规模已定，那末产品的数量就取决于工作机作业的速度，例如取决于纱锭的转速或蒸汽锤每分钟锤击的次数。某些大蒸汽锤每分钟可锤70次；赖德的专利锻造机，用小蒸汽锤锻造纱锭，每分钟可锤700次。","language":"中文","translation":false},{"id":"capital-14-39","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果机器转给产品的价值的比率已定，那末这个价值部分的大小就取决于机器本身价值的大小。机器本身包含的劳动越少，它加到产品上的价值也就越小。它转移的价值越小，它的生产效率就越高，它的服务就越接近自然力的服务。而用机器生产机器，会使机器的价值同机器的规模和作用相对而言降低下来。","language":"中文","translation":false},{"id":"capital-14-40","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"分析比较一下手工业或工场手工业生产的商品的价格和机器生产的同种商品的价格，一般可以得出这样的结论：在机器产品中，由劳动资料转来的价值组成部分相对地说是增大了，但绝对地说是减少了。这就是说，它的绝对量是减少了，但它同产品(如一磅棉纱)的总价值相比较的量是增大了。","language":"中文","translation":false},{"id":"capital-14-41","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"很明显，如果生产一台机器所费的劳动，与使用该机器所节省的劳动相等，那末这只不过是劳动的变换，就是说，生产一个商品所需要的劳动总量没有减少，或者说，劳动生产力没有提高。但是，机器所费的劳动和它所节省的劳动之间的差额，或机器生产率的高低，显然不是由机器本身的价值和它所代替的工具的价值之间的差额来决定的。只要机器所费的劳动，从而机器加到产品上的价值部分，小于工人用自己的工具加到劳动对象上的价值，这种差额就一直存在。因此，机器的生产率是由它代替人类劳动力的程度来衡量的。根据培恩斯先生的计算，由一蒸汽马力推动的450个走锭精纺机纱锭及其附属设备，需要两个半工人看管；每个自动走锭精纺机纱锭在一个十小时工作日里可纺出13盎斯棉纱(平均纱支)，因此两个半工人一星期可纺出365 5/8磅棉纱。可见，大约366磅棉花(为了简便起见，我们撇开棉屑不说)在变为棉纱时，只吸收了150个劳动小时，或15个十小时工作日，而用纺车，一个手工纺工60小时纺13盎斯棉纱，因此，同量的棉花就要吸收2700个十小时工作日，或27000个劳动小时。［注：据拜比吉的计算，在爪哇，几乎单是纺纱劳动就使棉花价值增加117%。而同一时期(1832年)，英国精纺业的机器和劳动加进棉花的总价值约为原料价值的33%。(《论机器和工厂的节约》第165、166页)］ 在木板印花或手工印花这种旧方法被机器印花代替的地方，一台机器由一个成年男工或少年工看管，一小时印制的四色花布的数量，等于过去200个成年工人印制的数量。在1793年伊莱·维特尼发明轧棉机以前，轧除一磅棉花的棉籽要花一个平均工作日。由于有了他的发明，一个黑人妇女每天可以轧100磅棉花，而且从那以后，轧棉机的效率又大有提高。原来要花50分钱生产的一磅棉纤维，后来卖10分钱，而且利润更高，也就是说，包含的无酬劳动更多了。在印度，使用一种半机器式的工具——手工轧棉机，来使棉纤维与棉籽脱离。使用这种工具，一个男工和一个女工每天能轧28磅棉花。但使用几年前福尔布斯博士发明的手工轧棉机，一个成年男工和一个少年工每天可轧250磅棉花；在用牛、蒸汽或水作动力的地方，只需要几个男女少年充当添料工。16台这样的机器，用牛来拉，每天能完成以前750个人一天平均的工作。","language":"中文","translation":false},{"id":"capital-14-42","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"前面已经说过，装在蒸汽犁上的蒸汽机在一小时内花费3便士或1/4先令所完成的工作，等于66个人在一小时内花费15先令所完成的工作。我又来引用这个例子，是为了反驳一种错误的见解。就是说，这15先令决不是这66个人一小时内加进的劳动的表现。如果剩余劳动和必要劳动之比为100％，那末，这66个工人一小时就生产30先令的价值，虽然其中只有33小时表现为他们自己的等价物，即表现为15先令的工资。因此，假定一台机器的所值等于它排挤的150个工人一年的工资，比方说3000镑，那末，这3000镑决不是这150个工人所提供的并加到劳动对象上的劳动的货币表现，而只是他们的年劳动中表现为他们工资的那部分劳动的货币表现。相反，机器的货币价值3000镑是生产机器时所耗费的全部劳动的表现，不管这一劳动按什么比例形成工人的工资和资本家的剩余价值。可见，即使机器的所值和它所代替的劳动力的所值相等，物化在机器本身中的劳动，总是比它所代替的活劳动少得多。","language":"中文","translation":false},{"id":"capital-14-43","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果只把机器看作使产品便宜的手段，那末使用机器的界限就在于：生产机器所费的劳动要少于使用机器所代替的劳动。可是对资本说来，这个界限表现得更为狭窄。由于资本支付的不是所使用的劳动，而是所使用的劳动力的价值，因此，对资本说来，只有在机器的价值和它所代替的劳动力的价值之间存在差额的情况下，才会使用机器。由于工作日中必要劳动和剩余劳动的比例，在不同的国家是不同的，而且在同一国家不同的时期，或者在同一时期不同的生产部门，也是不同的；其次，由于工人的实际工资有时降到他的劳动力价值以下，有时升到他的劳动力价值以上，因此，机器的价格和它所要代替的劳动力的价格之间的差额，可能有很大的变动，即使生产机器所必需的劳动量和机器所代替的劳动总量之间的差额保持不变。［注：因此，在共产主义社会，机器的作用范围将和在资产阶级社会完全不同。］ 但是，对资本家本身来说，只有前一种差额才决定商品的生产费用，并通过竞争的强制规律对他发生影响。因此，现在英国发明的机器只能在北美使用，正象十六世纪和十七世纪德国发明的机器只能在荷兰使用，十八世纪法国的某些发明只能在英国使用一样。在一些较老的发达国家，机器本身在某些产业部门的使用，会造成其他部门的劳动过剩，以致其他部门的工资降到劳动力价值以下，从而阻碍机器的应用，并且使机器的应用在资本看来是多余的，甚至往往是不可能的，因为资本的利润本来不是靠减少所使用的劳动得来的，而是靠减少有酬劳动得来的。近几年来，在英国毛纺织业的某些部门中，童工显著减少，有的地方几乎完全被排挤掉了。为什么呢？因为工厂法规定童工必须实行两班制，一班劳动6小时，另一班劳动4小时，或每班只劳动5小时。但是父母们不愿比以前出卖全日工更便宜地出卖半日工。因此半日工就被机器所代替。在矿井禁止使用女工和童工(10岁以下的)以前，资本认为，在煤矿和其他矿井使用裸体的妇女和少女，而且往往让她们同男子混在一起的做法，是完全符合它的道德规范的，尤其是符合它的总账的。直到禁止使用女工和童工以后，资本才采用机器。美国人发明了碎石机。英国人不采用这种机器，因为从事这种劳动的“不幸者”(《wretch》是英国政治经济学用来称呼农业工人的术语)的劳动只有很小一部分是有报酬的，所以对于资本家说来，机器反而会使生产变贵。在英国，直到现在还有时不用马而用妇女在运河上拉纤等等，因为生产马和机器所需要的劳动是一个数学上的已知量，而维持过剩人口中的妇女所需要的劳动，却是微不足道的。因此，恰恰是英国这个机器国家，比任何地方都更无耻地为了卑鄙的目的而浪费人力。","language":"中文","translation":false},{"id":"capital-14-44","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"3、机器生产对工人的直接影响","language":"中文","translation":false},{"id":"capital-14-45","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"前面已经指出，大工业的起点是劳动资料的革命，而经过变革的劳动资料，在工厂的有组织的机器体系中获得了最发达的形式。在研究人身材料怎样合并到这个客观机体之前，让我们先来考察一下这种革命对工人本身的某些一般影响。","language":"中文","translation":false},{"id":"capital-14-46","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"(a)资本对补充劳动力的占有。妇女劳动和儿童劳动","language":"中文","translation":false},{"id":"capital-14-47","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"就机器使肌肉力成为多余的东西来说，机器成了一种使用没有肌肉力或身体发育不成熟而四肢比较灵活的工人的手段。因此，资本主义使用机器的第一个口号是妇女劳动和儿童劳动！这样一来，这种代替劳动和工人的有力手段，就立即变成了这样一种手段，它使工人家庭全体成员不分男女老少都受资本的直接统治，从而使雇佣工人人数增加。为资本家进行的强制劳动，不仅夺去了儿童游戏的时间，而且夺去了家庭本身通常需要的、在家庭范围内从事的自由劳动的时间。","language":"中文","translation":false},{"id":"capital-14-48","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"劳动力的价值不只是决定于维持成年工人个人所必需的劳动时间，而且决定于维持工人家庭所必需的劳动时间。机器把工人家庭的全体成员都抛到劳动市场上，就把男劳动力的价值分到他全家人身上了。因此，机器使男劳动力贬值了。购买例如有四个劳动力的一家，也许比以前购买家长一个劳动力花费得多些，但现在四个工作日代替了原来的一个工作日，劳动力的价格按照四个工作日的剩余劳动超过一个工作日的剩余劳动的比例而下降了。现在，一家人要维持生活，四口人不仅要给资本提供劳动，而且要给资本提供剩余劳动。因此，机器从一开始，在增加人身剥削材料，即扩大资本固有的剥削领域的同时，也提高了剥削程度。","language":"中文","translation":false},{"id":"capital-14-49","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器还从根本上使资本关系的形式上的表现，即工人和资本家之间的契约发生了革命。在商品交换的基础上，第一个前提是资本家和工人作为自由人，作为独立的商品所有者而互相对立：一方是货币和生产资料的所有者，另一方是劳动力的所有者。但是现在，资本购买未成年人或半成年人。从前工人出卖他作为形式上自由的人所拥有的自身的劳动力。现在他出卖妻子儿女。他成了奴隶贩卖者。对儿童劳动的需求，在形式上也往往同美国报纸广告上常见的对黑奴的需求相似。例如，一个英国工厂视察员说：","language":"中文","translation":false},{"id":"capital-14-50","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“在我的管区的一个重要的工业城市里，地方报纸的一条广告引起了我的注意，广告写道：兹征求12至20名少年，外貌要13岁以上。工资每周4先令。报名处……”","language":"中文","translation":false},{"id":"capital-14-51","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这里之所以用“外貌要13岁”这句话，是因为按照工厂法规定，未满13岁的儿童只能劳动6小时。年龄必须经过合格医生的证明。因此，工厂主需要外表看来已满13岁的儿童。工厂主雇用的未满13岁的儿童人数屡次大幅度地减少，这在英国近20年来的统计材料中是令人惊讶的。根据工厂视察员本人的证词，这种情况大部分是由合格医生造成的，他们为迎合资本家的剥削欲望和父母的贩卖要求而虚报儿童的年龄。在声名狼藉的伦敦拜特纳－格林区，每逢星期一和星期二的早晨，都有公开的集市，9岁以上的男女儿童就在那里把自己出租给伦敦的丝织厂。“一般的条件是，每周1先令8便士(归父母)，2便士归我自己用作茶点费。”契约仅以一周为限。这种集市上的情景和语言确实令人愤慨。直到现在英国还有这样的事发生：妇女“把子女从贫民习艺所中领出来，以每周2先令6便士的价格出租给任何一个主顾”。在大不列颠，不顾法律的规定，至少还有2000名儿童被自己的父母卖出去充当活的烟囱清扫机(虽然已经有机器可以代替他们)。机器引起的劳动力买者和卖者之间的法权关系的革命，使全部交易本身失去了自由人之间的契约的外表，这就为后来英国议会提供了国家干涉工厂事务的法律上的根据。每当工厂法把以前不受约束的工业部门的儿童劳动限制为6小时的时候，工厂主总是一再抱怨说：有些父母会把儿童从受限制的工业部门中领出来，把他们卖给“劳动自由”还盛行的部门，即卖给那些不满13岁的儿童被迫象成年人一样地劳动，因而出价较高的工业部门。但由于资本是天生的平等派，就是说，它要求在一切生产领域内剥削劳动的条件都是平等的，把这当作自己的天赋人权，因此，儿童劳动在一个工业部门受到法律限制，就成为儿童劳动在另一个工业部门受到限制的原因。","language":"中文","translation":false},{"id":"capital-14-52","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"前面已经指出，机器起初使儿童、少年象工人妻子一样在以机器为基础而产生的工厂内直接受资本的剥削，后来使他们在所有其他工业部门内间接受资本的剥削，而使他们的身体受到摧残。因此在这里，我们只谈一点，就是工人子女出生后头几年的惊人的死亡率。在英格兰，有16个户籍区在100000个不满一周岁的儿童中每年平均的死亡人数只是9085人(其中有一个区只是7047人)；24个区是10000人至11000人；39个区是11000人至12000人；48个区是12000人至13000人；22个区超过20000人；25个区超过21000人；17个区超过22000人；11个区超过23000人；在赫乌、乌尔未汉普顿、埃士顿－安得－莱因和普雷斯顿等地超过24000人；在诺定昂、斯托克波尔特和布莱得弗德等地超过25000人；在威兹比奇是26001人；在曼彻斯特是26125人。1861年的一个官方医生调查报告指出：造成这样高的死亡率的原因，除了当地的情况外，主要是由于母亲外出就业，以及由此引起的对子女的照顾不周和虐待，例如饮食不适、缺乏营养、喂鸦片剂等等，另外，母亲还违反天性地疏远自己的子女，从而发生故意饿死和毒死的事件。相反地，在“妇女最少就业”的农业区，“死亡率则最低”。但是，1861年的调查委员会却得出了一个出人意料的结论：在北海沿岸的一些纯农业区，不满一周岁的儿童的死亡率几乎赶上了名声最坏的工厂区。因此，朱利安·汉特医生被派去就地研究这种现象。他的报告收在《公共卫生第6号报告》中。在此以前人们认为，疟疾和低洼的沼泽地区所特有的其他疾病是造成儿童大批死亡的原因。但调查却得出了完全相反的结论：","language":"中文","translation":false},{"id":"capital-14-53","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“把冬天是沼地夏天是贫瘠草地的土地变成肥沃的谷物耕地，这是消灭疟疾的原因，但也就是这个原因造成了非常高的婴儿死亡率。”","language":"中文","translation":false},{"id":"capital-14-54","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"汉特医生在这些地区询问过70个开业医生，他们对这一点的意见“惊人地一致”。事实上，随着土地耕作的革命，采用了工业制度。","language":"中文","translation":false},{"id":"capital-14-55","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“同少年男女在帮伙里一起劳动的已婚妇女，为了挣一些钱，被一个出租整个帮伙的叫做‘帮头’的人，交给租地农场主支配。这些帮伙往往到离本村许多哩以外的地方去；早晚都可以在路上看到他们，妇女们穿着短裙和短上衣、靴子，有时穿长裤，表面上很健壮有力，但由于放荡成性而变坏了，她们喜欢这种忙碌的独立的生活方式，而毫不考虑这会给她们家里瘦弱的子女带来多么不幸的后果。”","language":"中文","translation":false},{"id":"capital-14-56","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂区的各种现象在这里又重现了，而且暗地杀害儿童和让儿童服鸦片剂的现象比工厂区还要厉害。","language":"中文","translation":false},{"id":"capital-14-57","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"英国枢密院医官、《公共卫生》报告主编西蒙医生说：","language":"中文","translation":false},{"id":"capital-14-58","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我了解工业中大量使用成年妇女所造成的恶果，所以每当我看到这种现象都有理由感到深恶痛绝。”","language":"中文","translation":false},{"id":"capital-14-59","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂视察员罗·贝克在一份官方报告中疾呼：","language":"中文","translation":false},{"id":"capital-14-60","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“禁止任何有家的已婚妇女在任何工厂里干活，对于英国的工厂区来说，确实会是一件幸事。”","language":"中文","translation":false},{"id":"capital-14-61","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"关于对妇女劳动和儿童劳动进行资本主义剥削所造成的精神摧残，弗·恩格斯在他所著的《英国工人阶级状况》中以及其他的著作家已经作了详尽的阐述，因此我在这里只是提一下。把未成年人变成单纯制造剩余价值的机器，就人为地造成了智力的荒废，——这和自然的无知完全不同，后者把智力闲置起来，并没有损害它的发展能力、它的自然肥力，——这种智力的荒废甚至使英国议会最后不得不宣布，在一切受工厂法约束的工业中，受初等教育是“在生产上”使用14岁以下儿童的法定条件。工厂法关于所谓教育的条款措辞草率；由于缺少行政机构，这种义务教育大部分仍然徒有其名；工厂主反对这个教育法令，使用种种阴谋诡计回避这个法令；——这一切明显地暴露出资本主义生产的本性。","language":"中文","translation":false},{"id":"capital-14-62","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“只有立法机关应受谴责，因为它颁布了一个骗人的法令，这个法令表面上关心儿童的教育，但没有一条规定能够保证达到这个口头上的目的。它只是规定儿童每天必须有若干小时<3小时>被关在叫做学校的地方的四壁之内，规定儿童的雇主每周必须从一个以男教师或女教师身分签字的人那里得到证明书。”","language":"中文","translation":false},{"id":"capital-14-63","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在1844年的修正工厂法颁布以前，上学证明书由男教师或女教师在上面划一个十字来代替签字，并不是少见的现象，因为他们自己也不会写字。","language":"中文","translation":false},{"id":"capital-14-64","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我访问一所颁发这种证明书的学校，教师的无知使我非常惊奇，所以我问他：‘先生，请问您识字吗？’他的回答是：‘唉，认识一点点’，为了申辩，他又补充一句：‘不管怎样，我总比我的学生高明’。”","language":"中文","translation":false},{"id":"capital-14-65","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在拟定1844年的法令的时候，工厂视察员揭发了这种叫做学校的地方的丑事。但他们不得不承认这种学校发的证明书在法律上是完全有效的。他们努力的全部成果就是，从1844年起， “教师必须在上学证明书上亲笔填写数字，并且必须亲笔签上自己的姓名”。","language":"中文","translation":false},{"id":"capital-14-66","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"苏格兰工厂视察员约翰·金凯德爵士谈到了他工作中类似的经历。","language":"中文","translation":false},{"id":"capital-14-67","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我们访问的第一所学校是由一个叫安·基林的夫人主办的。当我请她把她的姓拼读出来时，她马上就出了错，她先说了一个C，但马上改正说，她的姓的第一个字母是K。然而，我查看她在上学证明书上的签字时，发现她的姓的写法不一，同时，她的笔迹证明，她根本没有教书的能力。她自己也承认，她不会填写名册…… 在另一所学校，我发现教室长15呎宽10呎，里面有75个儿童，不知在叽叽喳喳讲些什么。”“然而，儿童只得到上学证明书而受不到教育的现象，不仅存在于这些受罪的地方。在许多有合格师资的学校，由于各种年龄(从3岁起)的儿童乱哄哄地混杂在一起，教师也几乎是白费力气。教师的收入充其量只能勉强糊口，这些收入完全依靠儿童缴纳的便士，因此他尽可能把大量学生塞进一个教室里。此外，学校设备简陋，缺乏书籍和其他教具，沉闷难闻的空气对贫苦的儿童产生有害的影响。我到过很多这样的学校，看见一排一排的儿童无所事事，但这就被证明是上学了，在官方的统计中，这些儿童算是受过教育的。”","language":"中文","translation":false},{"id":"capital-14-68","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在苏格兰，工厂主竭力排斥那种必须上学的儿童。","language":"中文","translation":false},{"id":"capital-14-69","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“这足以证明，工厂主对教育条款是十分憎恶的。”","language":"中文","translation":false},{"id":"capital-14-70","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这种情况在受一种特别工厂法限制的棉布等印花厂中表现得荒诞离奇。按照这项法令的规定，","language":"中文","translation":false},{"id":"capital-14-71","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“每个儿童在到这种印花厂就业以前，必须在他就业第一天前的6个月内至少上学30天，并且不得少于150小时。他在印花厂就业期间，每过6个月仍须上学30天，而且是150小时…… 上学时间应在早晨8点至下午6点之间。每天上学的时数少于2 1/2小时或超过5小时，都不得算入150小时之内。在一般情况下，儿童在30天内上下午都上学，每天5小时，30天期满，就达到规定的总数150小时，用他们自己的话来说，读完了书，然后他们又回到印花厂，在那里再劳动6个月；到下一个上学期限，他们又去上学，直到又读完了书为止…… 许多按规定上过150小时学的儿童，在印花厂呆了6个月以后再回到学校时，情形和刚上学时一样…… 他们自然又把前一次上学所学到的东西忘得一干二净。还有一些印花厂，上学的事完全取决于工厂的营业需要。每6个月内所必须达到的时数是由每次3至5小时零碎凑成的，而且可能分散在这6个月内。例如，一天是从上午8点到11点上学，另一天是从下午1点到4点上学，在儿童有些天不上学之后，突然又从下午3点到6点上学；他可能连续上3、4天或一个星期，然后又停3个星期或整整一个月。而当他的雇主偶然不需要他的那些日子，他又回去混一些小时，因此，儿童可说是被推来推去，从学校推到工厂，再从工厂推到学校，直到凑满150小时为止”。","language":"中文","translation":false},{"id":"capital-14-72","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器使儿童和妇女以压倒的多数加入结合劳动人员中，终于打破了男工在工场手工业时期还进行的对资本专制的反抗。","language":"中文","translation":false},{"id":"capital-14-73","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果说机器是提高劳动生产率，即缩短生产商品的必要劳动时间的最有力的手段，那末，它作为资本的承担者，首先在它直接占领的工业中，成了把工作日延长到超过一切自然界限的最有力的手段。一方面，它创造了新条件，使资本能够任意发展自己这种一贯的倾向，另一方面，它创造了新动机，使资本增强了对别人劳动的贪欲。","language":"中文","translation":false},{"id":"capital-14-74","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"首先，在机器上，劳动资料的运动和活动离开工人而独立了。劳动资料本身成为一种工业上的永动机，如果它不是在自己的助手——人的身上遇到一定的自然界限，即人的身体的虚弱和人的意志，它就会不停顿地进行生产。因此，劳动资料作为资本——而且作为资本，自动机在资本家身上获得了意识和意志——就具有一种欲望，力图把有反抗性但又有伸缩性的人的自然界限的反抗压到最低限度。而且，由于在机器上劳动看来很容易，由于妇女和儿童比较温顺驯服，这种反抗无疑减小了。","language":"中文","translation":false},{"id":"capital-14-75","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"我们已经知道，机器的生产率同机器转移到成品上的价值组成部分的大小成反比。机器执行职能的期限越长，分担机器加进的价值的产品量就越大，机器加到单个商品上的价值部分就越小。而机器的有效寿命，显然取决于工作日的长度或每天劳动过程的长度乘以劳动过程反复进行的日数。","language":"中文","translation":false},{"id":"capital-14-76","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器的磨损绝不象在数学上那样精确地和它的使用时间相一致。即使二者相一致，一台在7 1/2年内每天工作16小时的机器所包含的生产时间和加到总产品上的价值，和同样一台在15年内每天只工作8小时的机器所包含的生产时间和加到总产品上的价值是相等的。但是在第一种情况下，机器价值的再生产要比第二种情况下快一倍，而且资本家用这台机器在7 1/2年内就可以吞下在第二种情况下15年内才能吞下的剩余劳动。","language":"中文","translation":false},{"id":"capital-14-77","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器的有形损耗有两种。一种是由于使用，就象铸币由于流通而磨损一样。另一种是由于不使用，就象剑入鞘不用而生锈一样。在后一种情况下，机器的磨损是由于自然作用。前一种磨损或多或少地同机器的使用成正比，后一种损耗在一定程度上同机器的使用成反比。","language":"中文","translation":false},{"id":"capital-14-78","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"但是，机器除了有形损耗以外，还有所谓无形损耗。只要同样结构的机器能够更便宜地再生产出来，或者出现更好的机器同原有的机器相竞争，原有机器的交换价值就会受到损失。在这两种情况下，即使原有的机器还十分年轻和富有生命力，它的价值也不再由实际物化在其中的劳动时间来决定，而由它本身的再生产或更好的机器的再生产的必要劳动时间来决定了。因此，它或多或少地贬值了。机器总价值的再生产时期越短，无形损耗的危险就越小，而工作日越长，这个再生产时期就越短。在某个生产部门最初采用机器时，那些使机器更便宜地再生产出来的新方法，那些不仅涉及机器的个别部分或装置，而且涉及机器的整个构造的改良，会接连不断地出现。因此，在机器的最初的生活期，这种延长工作日的特别动机也最强烈。","language":"中文","translation":false},{"id":"capital-14-79","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在其他条件不变和工作日已定的情况下，要剥削双倍的工人，就必须把投在机器和厂房上的不变资本部分和投在原料、辅助材料等等上的不变资本部分增加一倍。随着工作日的延长，生产的规模会扩大，而投在机器和厂房上的资本部分却保持不变。因此，不仅剩余价值增加了，而且榨取剩余价值所必需的开支减少了。当然，只要延长工作日，总会在一定程度上发生这种情况，但是在这里，它却更加具有决定性的意义，因为转化为劳动资料的资本部分具有更大的意义。机器生产的发展使资本中越来越大的组成部分固定在这样一种形式上，在这种形式上，一方面资本可以不断地增殖，另一方面，一旦资本同活劳动的接触被中断，它就会丧失使用价值和交换价值。英国棉纺织业巨头艾释华特先生曾教训纳骚·威·西尼耳教授说：","language":"中文","translation":false},{"id":"capital-14-80","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“一个农夫放下自己的铁锹，他就使一笔18便士的资本在这个时期内变成无用的东西。我们的人<即工厂工人>有一个离开工厂，他就使一笔值10万镑的资本变成无用的东西。”","language":"中文","translation":false},{"id":"capital-14-81","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"请想一想吧！把一笔值10万镑的资本变成了——即使在一瞬间——“无用的东西”！我们的人有一个竟然随便在什么时候离开工厂，这真是骇人听闻的事！在被艾释华特教训过的西尼耳看来，机器规模的扩大，使工作日的不断延长成为“合乎愿望的事情”。","language":"中文","translation":false},{"id":"capital-14-82","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器生产相对剩余价值，不仅由于它直接地使劳动力贬值，使劳动力再生产所必需的商品便宜，从而间接地使劳动力便宜，而且还由于它在最初偶而被采用时，会把机器所有主使用的劳动变为高效率的劳动，把机器产品的社会价值提高到它的个别价值以上，从而使资本家能够用日产品中较小的价值部分来补偿劳动力的日价值。因此，在机器生产还被垄断的这个过渡时期，利润特别高，而资本家也就企图尽量延长工作日来彻底利用这个“初恋时期”。高额的利润激起对更多利润的贪欲。","language":"中文","translation":false},{"id":"capital-14-83","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"随着机器在同一生产部门内普遍应用，机器产品的社会价值就降低到它的个别价值的水平，于是下面这个规律就会发生作用：剩余价值不是来源于资本家用机器所代替的劳动力，恰恰相反，是来源于资本家雇来使用机器的劳动力。剩余价值只是来源于资本的可变部分，同时我们已经知道，剩余价值量取决于两个因素，即剩余价值率和同时使用的工人人数。在工作日的长度已定时，剩余价值率取决于工作日分为必要劳动和剩余劳动的比例。同时使用的工人人数则取决于资本的可变部分和不变部分的比例。现在很明显，不管机器生产怎样提高劳动生产力，靠减少必要劳动来扩大剩余劳动，它只有减少一定资本所使用的工人人数，才能产生这样的结果。机器生产使以前的可变资本的一部分，也就是曾变为活劳动力的资本的一部分，转化为机器，即转化为不生产剩余价值的不变资本。但是，例如从两个工人身上榨不出从24个工人身上同样多的剩余价值。24个工人每人只要在12小时中提供一小时剩余劳动，总共就提供24小时剩余劳动，而两个工人的全部劳动只不过是24小时。可见，利用机器生产剩余价值包含着一个内在的矛盾：在一定量资本所提供的剩余价值的两个因素中，机器要提高一个因素，要提高剩余价值率，就只有减少另一个因素，减少工人人数。一旦机器生产的商品的价值随着机器在一个工业部门普遍应用而成为所有同类商品的起调节作用的社会价值，这种内在的矛盾就会表现出来；但正是这种资本没有意识到的矛盾又重新推动资本拚命延长工作日，以便不仅增加相对剩余劳动，而且增加绝对剩余劳动，来弥补被剥削的工人人数的相对减少。","language":"中文","translation":false},{"id":"capital-14-84","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"因此，机器的资本主义应用，一方面创造了无限度地延长工作日的新的强大动机，并且使劳动方式本身和社会劳动体的性质发生这样的变革，以致打破对这种趋势的抵抗，另一方面，部分地由于使资本过去无法染指的那些工人阶层受资本的支配，部分地由于使那些被机器排挤的工人失业，制造了过剩的劳动人口，这些人不得不听命于资本强加给他们的规律。由此产生了近代工业史上一种值得注意的现象，即机器消灭了工作日的一切道德界限和自然界限。由此产生了一种经济上的反常现象，即缩短劳动时间的最有力的手段，竟成为把工人及其家属的全部生活时间变成受资本支配的增殖资本价值的劳动时间的最可靠的手段。古代最伟大的思想家亚里士多德曾经幻想过：","language":"中文","translation":false},{"id":"capital-14-85","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"”如果每一件工具都能按照命令，或者，甚至按照自己的预想去完成它所担负的工作，就象代达罗斯的工艺品那样自己会动作，或者象赫斐斯塔司的鼎那样会自动执行祭神的工作，如果织布的梭会自己织布，那末师傅就不需要助手，主人就不需要奴隶了。”","language":"中文","translation":false},{"id":"capital-14-86","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"西塞罗时代的希腊诗人安谛巴特洛斯，曾歌颂碾谷的水磨这种一切生产机器的最初形式的发明，把它看作是女奴隶的解放者和黄金时代的复兴者！“异教徒！噢，这些异教徒！”他们对政治经济学和基督教一窍不通，就象机智的巴师夏和在他以前的更聪明的麦克库洛赫在这方面毫无发现一样。例如，他们就不了解机器是延长工作日的最可靠的手段。他们也许会辩护说，一个人受奴役是使另一个人获得充分发展的手段。但是，要鼓吹群众受奴役，以便使少数粗野的或者没有多少教养的暴发户成为“卓越的纺纱业主”、“了不起的香肠制造业主”和“有势力的鞋油商人”，那他们还缺少专门的基督教器官。","language":"中文","translation":false},{"id":"capital-14-87","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"资本手中的机器所造成的工作日的无限度的延长，使社会的生命根源受到威胁，结果象我们所看到的那样，引起了社会的反应，从而产生了受法律限制的正常工作日。在正常工作日的基础上，我们前面已经看到的劳动强化现象，就获得了决定性的重要意义。在分析绝对剩余价值时，首先涉及的是劳动的外延量，而劳动的强度则是假定不变的。现在我们要考察外延量怎样转化为内含量或强度。","language":"中文","translation":false},{"id":"capital-14-88","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"不言而喻，随着机器的进步和机器工人本身的经验积累，劳动的速度，从而劳动的强度，也会自然增加。例如，英国在半个世纪内，工作日的延长同工厂劳动强度的增加一直是同时并进的。但是很明显，如果一种劳动不是一时的发作，而是日复一日有规律地划一地反复进行，那末必定会出现这样一个时刻，这时工作日的延长和劳动的强化会互相排斥，以致要延长工作日就只有降低劳动强度，或者反过来，要提高劳动强度就只有缩短工作日。自从工人阶级不断增长的反抗迫使国家强制缩短劳动时间，并且首先为真正的工厂强行规定正常工作日以来，也就是说，自从剩余价值的生产永远不能通过延长工作日来增加以来，资本就竭尽全力一心一意加快发展机器体系来生产相对剩余价值。同时，相对剩余价值的性质也发生了变化。一般地说，生产相对剩余价值的方法是：提高劳动生产力，使工人能够在同样的时间内以同样的劳动消耗生产出更多的东西。同样的劳动时间加在总产品上的价值，仍然和以前同样多，虽然这个不变的交换价值现在表现为较多的使用价值，从而使单个商品的价值下降。但是，一旦强制缩短工作日，情况就不同了。强制缩短工作日，有力地推动了生产力的发展和生产条件的节约，同时迫使工人在同样的时间内增加劳动消耗，提高劳动力的紧张程度，更紧密地填满劳动时间的空隙，也就是说，使劳动凝缩到只有在缩短了的工作日中才能达到的程度。这种压缩在一定时间内的较大量的劳动，现在是算作较大的劳动量，而实际上也是如此。现在，计量劳动时间的，除了它的“外延量”以外，还有它的密度。现在，十小时工作日中一个较紧张的小时，同十二小时工作日中一个较松弛的1 1/5小时相比，会包含相同的或者更多的劳动，即已耗费的劳动力。因此，较紧张的一小时的产品同较松弛的1 1/5小时的产品相比，会具有相同的或者更多的价值。撇开相对剩余价值由于劳动生产力的提高而增加不说，现在，例如3 1/3小时剩余劳动和6 2/3小时必要劳动，也会和从前4小时剩余劳动和8小时必要劳动一样，给资本家提供同样大的价值量。","language":"中文","translation":false},{"id":"capital-14-89","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"现在要问，劳动是怎样强化的呢？","language":"中文","translation":false},{"id":"capital-14-90","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工作日缩短的第一个结果，是由一个显而易见的规律引起的，即劳动力的活动能力同它的活动时间成反比。因此，在一定的限度内，力的作用时间上所受的损失，可由力的作用程度来弥补。资本也会通过付酬的办法，设法使工人在实际上付出更多的劳动力。在工场手工业中，例如，在机器不起作用或只起很小作用的陶器业中，工厂法的实行令人信服地证明，单单缩短工作日，就惊人地增加了劳动的规则性、划一性、秩序性、连续性和效能。但是，在真正的工厂中是否也有这样的结果，看来是值得怀疑的，因为在这里，工人要服从机器的连续的、划一的运动，这早已造成了最严格的纪律。因此，当1844年讨论把工作日缩减到12小时以下的问题时，工厂主几乎异口同声地说：","language":"中文","translation":false},{"id":"capital-14-91","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“他们的监工在各个车间，都注意不让人手浪费时间”，“工人专心致志的程度可以说不能再提高了”。因此，在机器的速度等其他一切条件不变的情况下，“指望在管理良好的工厂里，通过提高工人的注意力等等来获得任何显著的成果，是荒谬的”。","language":"中文","translation":false},{"id":"capital-14-92","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这种论断被实验推翻了。罗·加德纳先生从1844年4月20日起，在普雷斯顿他的两个大工厂里，把劳动时间由每天12小时改为11小时。经过大约一年的时间，结果是：","language":"中文","translation":false},{"id":"capital-14-93","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“花费同样多的开支，得到同样多的产品，而全体工人11小时挣的工资，和以前12小时挣的同样多”。","language":"中文","translation":false},{"id":"capital-14-94","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在这里我且不谈纺纱间和梳棉间的实验，因为这种实验同机器速度的提高(提高2％)结合在一起。相反地，在织造各式各样细花时装布的织布间，客观生产条件没有发生任何变化。结果是：","language":"中文","translation":false},{"id":"capital-14-95","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“从1844年1月6日到4月20日，每天干12小时，每个工人每周的平均工资是10先令1 1/2便士，从1844年4月20日到6月29日，每天干11小时，每周的平均工资是10先令3 1/2便士。”","language":"中文","translation":false},{"id":"capital-14-96","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在这里，11小时比以前12小时生产出更多的东西，这完全是由于工人始终不懈地付出更多的劳力和节约时间造成的。工人拿到同样的工资，并得到一小时的空闲时间；而资本家得到同量的产品，并节约了一小时煤炭、煤气等的消耗。在霍罗克斯先生和杰克逊先生的工厂里也进行过类似的实验，并且得到了同样的结果。","language":"中文","translation":false},{"id":"capital-14-97","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"缩短工作日，这种起初创造了使劳动凝缩的主观条件，也就是使工人有可能在一定时间内付出更多力量的办法，一旦由法律强制实行，资本手中的机器就成为一种客观的和系统地利用的手段，用来在同一时间内榨取更多的劳动。这是通过两种方法达到的：一种是提高机器的速度，另一种是扩大同一个工人看管的机器数量，即扩大工人的劳动范围。改进机器结构，一方面是对工人施加更大的压力所必需的，另一方面，这本身又是和劳动的强化伴随在一起的，因为工作日的限制，迫使资本家在生产费用上面精打细算。蒸汽机的改进提高了活塞每分钟的冲击次数，同时由于力的更加节省，用同一个发动机就能推动更大的机构，而耗煤量照旧不变，甚至下降了。传动装置的改进减少了磨擦力，使各种大小轮轴的直径和重量减到越来越小的最低限度，——这正是现代机器显著超过旧式机器的地方。最后，工作机的改进，在加快速度和扩大效能的同时，缩小了机器的体积(如现代蒸汽织机)，或者在增大机体的同时，扩大了它所使用的工具的规模和数量(如纺纱机)，或者对零件稍加改进而增加了这些工具的活动性(如五十年代中期，自动走锭精纺机的纱锭转速就是这样提高了1/5)。","language":"中文","translation":false},{"id":"capital-14-98","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"英国在1832年开始把工作日缩短到12小时。在1836年，一个英国工厂主说道：","language":"中文","translation":false},{"id":"capital-14-99","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“同以前比较，现在工厂中的劳动大大加重了，因为机器速度的大大加快要求工人更加注意，更多地活动。”","language":"中文","translation":false},{"id":"capital-14-100","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1844年，艾释黎勋爵，即现在的舍夫茨别利伯爵，在下院根据文件作了如下的发言：","language":"中文","translation":false},{"id":"capital-14-101","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“现在，在制造过程中雇用的工人的劳动，是开始实行这些操作时的三倍。毫无疑问，机器完成的工作，代替了成百万人的肌肉，但是，机器也使受它可怕的运动支配的人的劳动惊人地增加了…… 1815年，工人在12小时内来回看管两台纺40支纱的走锭精纺机，等于步行8哩。1832年，在12小时内看管两台纺同样支纱的走锭精纺机所走的距离等于20哩，并且往往还要多。1825年，一个纺纱工人在12小时内，在每台走锭精纺机上牵伸820次，12小时的牵伸总数是1640次。1832年，一个纺纱工人在一个十二小时工作日内，在每台走锭精纺机上牵伸2200次，合计是4400次；1844年，在每台走锭精纺机上牵伸2400次，合计是4800次；有时，需要的劳动量还要大…… 现在，我手头另有一份1842年的文件，证明劳动累进地增加，不仅是因为步行的距离加大了，而且还因为生产的商品数量增加了，而人手的数量相应地减少了；其次，还因为现在纺的往往是较次的棉花，需要较多的劳动…… 在梳棉间，劳动也大大增加了。现在，一个人要干以前由两个人分担的活…… 织布间雇用的人很多，而且多半是妇女，在这里，近年来由于机器速度的提高，劳动增加了整整10％。1838年，每周纺纱18000束，1843年达到21000束。1819年，蒸汽织机每分钟打梭60次，1842年是140次，这说明劳动大大增加了”。","language":"中文","translation":false},{"id":"capital-14-102","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"鉴于十二小时工作日法令支配下的劳动在1844年就已达到这样惊人的强度，因此，当时英国工厂主说在这方面不能再前进一步，说再缩短劳动时间就等于缩减生产，这似乎是有道理的。他们这种理由表面上的正确性，在他们不倦的检查官、工厂视察员莱昂纳德·霍纳当时所说的下面这段话中得到了最好的证明：","language":"中文","translation":false},{"id":"capital-14-103","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“由于产量主要由机器的速度来调节，工厂主所关心的必定是设法使机器的速度快到极点，而又不违背下列条件：保护机器以免损坏得太快，保持产品的质量，使工人能够跟上机器的运转，而又不过分紧张，以致不能持久。往往有这样的情况：工厂主由于操之过急，过分地加快了运转。这样，损坏和次品使提高速度得不偿失，工厂主又不得不放慢机器的速度。因为精明能干的工厂主会找到可能达到的最高限度，所以我得出结论，11小时的产品不可能和12小时的产品相等。同时我认为，领取计件工资的工人已经紧张到了极点，超过这个极限，他就不可能经常保持同样的劳动强度了”。","language":"中文","translation":false},{"id":"capital-14-104","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"因此，尽管有加德纳等人的实验，霍纳还是得出结论说：把工作日进一步缩短到12小时以下，产品数量就一定会减少。但是10年以后，霍纳自己引用他1845年的疑虑，来证明他当时还是多么不了解机器和人的劳动力所具有的伸缩性。这二者同样会由于工作日的强制缩短而紧张到极点。","language":"中文","translation":false},{"id":"capital-14-105","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"现在，我们来考察一下1847年以后，英国棉、毛、丝、亚麻纺织厂实行十小时工作日法令以来的时期。","language":"中文","translation":false},{"id":"capital-14-106","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“纱锭的转速，在环锭精纺机上每分钟增加了500转，在走锭精纺机上每分钟增加了1000转，也就是说，环锭精纺机纱锭的转速在1839年是每分钟4500转，现在<1862年>是5000转，而走锭精纺机纱锭的转速原来是每分钟5000转，现在是6000转，前者的转速增加了1/10，后者的转速增加了1/6。”","language":"中文","translation":false},{"id":"capital-14-107","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1852年，曼彻斯特附近帕特里克罗弗特的著名土木工程师詹姆斯·奈斯密斯，在给莱昂纳德·霍纳的一封信中解释了1848—1852年蒸汽机的改良。他指出，在官方的工厂统计中，蒸汽马力仍然是按1828年的功率计算的，这种马力只是额定马力，只能当作实际马力的指数。接着他写道：","language":"中文","translation":false},{"id":"capital-14-108","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“毫无疑问，重量相同的蒸汽机(往往就是只经过现代改良的同一些机器)，比以前平均多做50％的功；在许多场合，同一些蒸汽机，在速度限制为每分钟220呎的时候，提供50马力，现在则提供100马力以上，而且耗煤量减少了…… 同一额定马力的现代蒸汽机，由于构造的改良，锅炉容积和结构的缩小等等，能比以前发出更大的推动力…… 因此，虽然同额定马力比较起来，使用的人手数量和过去一样，但是同工作机比较起来，使用的人手数量则减少了。”","language":"中文","translation":false},{"id":"capital-14-109","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1850年，联合王国的工厂共使用134217额定马力，推动25638716个纱锭和301445台织机。1856年，纱锭数是33503580个，织机数是369205台。如果所需要的马力仍旧和1850年相同，那末1856年就需要175000马力。但根据官方材料，只有161435马力，也就是说，按照1850年的算法现在减少了1万多马力。","language":"中文","translation":false},{"id":"capital-14-110","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“1856年的最近的报告<官方统计>确证了下述事实：工厂制度在急剧扩展；同机器比较起来，人手数量减少了；由于力的节省和通过其他方法，蒸汽机可以推动更重的机器；由于工作机的改良、制造方法的改变、机器速度的提高以及其他许多原因，制品量增加了。”“各种机器的巨大改进，大大提高了它们的生产力。毫无疑问，工作日的缩短……推动了这种改进。这种改进以及工人紧张程度的加强，使得在一个已经缩短了<两小时或1/6>的工作日内生产的制品，至少和以前在一个较长的工作日内生产的制品一样多。”","language":"中文","translation":false},{"id":"capital-14-111","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂主的财富如何随着劳动力剥削的加强而增加，单是下面这个事实就可以证明：英国棉纺织等等工厂的平均增长额，从1838年到1850年间是每年32个，而在1850年到1856年间是每年86个。","language":"中文","translation":false},{"id":"capital-14-112","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"从1848年到1856年8年间，在十小时工作日的支配下，英国工业有了这样大的进步，但这种进步在1856年到1862年这以后的6年间，又被远远地超过了。例如丝织厂，1856年有1093799个锭子，1862年有1388544个锭子；1856年有9260台织机，1862年有10709台织机。相反，工人人数1856年是56137人，1862年是52429人。这些数字表明，锭子数增加了26.9％，织机增加了15.6％，而工人人数却同时减少了7％。精梳毛纺织厂使用的锭子，1850年是875830个，1856年是1324549个(增加51.2％)，1862年是1289172个(减少2.7％)。但是，1856年的数字把线锭计算在内，而1862年的数字没有把线锭计算在内，如果把线锭减去，那末，1856年以来锭子数是相当稳定的。相反地，1850年以来，在许多地方，锭子和织机的速度增加了1倍。精梳毛纺织厂的蒸汽织机，在1850年是32617台，1856年是38956台，1862年是43048台。这种工厂的工人人数，在1850年是79737人，1856年是87794人，1862年是86063人；但是其中14岁以下的童工，1850年是9956人，1856年是11228人，1862年是13178人。可见，同1856年比较起来，1862年虽然织机数有很大的增加，但是雇用的工人总数减少了，而被剥削的童工总数却增加了。","language":"中文","translation":false},{"id":"capital-14-113","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1863年4月27日，议员弗兰德在下院说：","language":"中文","translation":false},{"id":"capital-14-114","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我受郎卡郡和柴郡16个区的工人代表的委托，在这里讲话。他们告诉我说，工厂中的劳动，由于机器的改进，不断加重。过去一个人带着助手，看管两台织机，现在没有助手，要看管三台织机；而且一个人看管四台织机等等，也完全不是什么稀罕的事。从上述事实中可以看出，12小时的劳动，现在压缩在不到10个劳动小时当中了。因此，不言而喻，近几年来工厂工人的辛劳有了多么惊人的增加。”","language":"中文","translation":false},{"id":"capital-14-115","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"因此，虽然工厂视察员不倦地、十分正当地颂扬1844年和1850年的工厂法的好处，但他们也承认，缩短工作日，已使劳动强化到损害工人健康，从而破坏劳动力本身的程度。","language":"中文","translation":false},{"id":"capital-14-116","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“近几年来，在大多数棉纺织厂、精梳毛纺织厂和丝织厂里，机器的运转大大加快，看管机器需要的劳动紧张到精疲力竭的地步，看来，这正是格林豪医生在他最近的出色的报告中所指出的肺病死亡率过高的原因之一。”","language":"中文","translation":false},{"id":"capital-14-117","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"毫无疑问，当法律使资本永远不能延长工作日时，资本就力图不断提高劳动强度来补偿，并且把机器的每一改进变成加紧吮吸劳动力的手段，资本的这种趋势很快又必定达到一个转折点，使劳动时间不可避免地再一次缩短。另一方面，英国工业的蓬勃发展，在1833—1847年时期，即实行十二小时工作日时期，超过了实行工厂制度以来的最初半个世纪，即工作日不受限制时期，而从1848年到现在实行十小时工作日时期又超过了1833—1847年时期，而且超过的幅度比前一幅度大得多。","language":"中文","translation":false},{"id":"capital-14-118","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"我们在本章的开头考察了工厂的躯体，即有组织的机器体系。后来我们看到，机器怎样通过占有妇女劳动和儿童劳动增加资本剥削的人身材料，机器怎样通过无限度地延长工作日侵吞工人的全部生活时间，最后，机器的发展虽然使人们能在越来越短的时间内提供惊人地增长的产品，但又怎样作为系统的手段，用来在每一时刻内榨取更多的劳动或不断地加强对劳动力的剥削。现在我们转过来考察工厂的整体，而且考察的是它的最发达的形式。","language":"中文","translation":false},{"id":"capital-14-119","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"尤尔博士，这位自动工厂的品得，一方面把工厂描写成","language":"中文","translation":false},{"id":"capital-14-120","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“各种工人即成年工人和未成年工人的协作，这些工人熟练地勤勉地看管着由一个中心动力(原动机)不断推动的、进行生产的机器体系”；","language":"中文","translation":false},{"id":"capital-14-121","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"另一方面，又把工厂描写成","language":"中文","translation":false},{"id":"capital-14-122","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“一个由无数机械的和有自我意识的器官组成的庞大的自动机，这些器官为了生产同一个物品而协调地不间断地活动，因此它们都受一个自行发动的动力的支配”。","language":"中文","translation":false},{"id":"capital-14-123","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这两种说法绝不是相同的。在前一种说法中，结合总体工人或社会劳动体是积极行动的主体，而机械自动机则是客体；在后一种说法中，自动机本身是主体，而工人只是作为有意识的器官与自动机的无意识的器官并列，而且和后者一同受中心动力的支配。第一种说法适用于机器的一切可能的大规模应用，第二种说法表明了机器的资本主义应用以及现代工厂制度的特征。因此，尤尔也喜欢把产生运动的中心机器不仅描写成自动机(Automat)，而且描写成专制君主(Autokrat)。","language":"中文","translation":false},{"id":"capital-14-124","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“在这些大工场里，仁慈的蒸汽力量把无数臣民聚集在自己的周围。”","language":"中文","translation":false},{"id":"capital-14-125","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"使用劳动工具的技巧，也同劳动工具一起，从工人身上转到了机器上面。工具的效率从人类劳动力的人身限制下解放出来。这样一来，工场手工业分工的技术基础就消失了。因此，在自动工厂里，代替工场手工业所特有的专业工人的等级制度的，是机器的助手所要完成的各种劳动的平等或均等的趋势，代替局部工人之间的人为差别的，主要是年龄和性别的自然差别。","language":"中文","translation":false},{"id":"capital-14-126","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在自动工厂里重新出现了分工，但这种分工首先就是把工人分配到各种专门机器上去，以及把大群没有形成有组织的小组的工人分配到工厂的各个部门，在那里，他们在并列着的同种工作机上劳动，因此，在他们之间只有简单的协作。工场手工业的有组织的小组被一个主要工人同少数助手的联系代替了。重大的差别是实际操作工作机的工人(包括某些看管发动机或给发动机添料的工人)和这些机器工人的单纯下手(几乎完全是儿童)之间的差别。所有《feeders》(单纯给机器添劳动材料的人)或多或少地都算在这种下手之内。除了这两类主要工人外，还有为数不多的负责检查和经常修理全部机器的人员，如工程师、机械师、细木工等等。这一类是高级的工人，其中一部分人有科学知识，一部分人有手艺，他们不属于工厂工人的范围，而只是同工厂工人聚集在一起。这种分工是纯技术性的。","language":"中文","translation":false},{"id":"capital-14-127","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器上面的一切劳动，都要求训练工人从小就学会使自己的动作适应自动机的划一的连续的运动。只要总机器本身是一个由各种各样的、同时动作并结合在一起的机器构成的体系，以它为基础的协作也就要求把各种不同的工人小组分配到各种不同的机器上去。但是，机器生产不需要象工场手工业那样，使同一些工人始终从事同一种职能，从而把这种分工固定下来。由于工厂的全部运动不是从工人出发，而是从机器出发，因此不断更换人员也不会使劳动过程中断。1848—1850年英国工厂主叛乱期间所实行的换班制度，提供了最有力的证明。最后，年轻人很快就可以学会使用机器，因此也就没有必要专门培养一种特殊的工人成为机器工人。在工厂里，单纯的下手干的活一方面可以用机器来代替，另一方面由于这种活十分简单，从事这种苦役的人员可以迅速地经常地更换。","language":"中文","translation":false},{"id":"capital-14-128","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"虽然机器从技术上推翻了旧的分工制度，但是最初这种旧制度由于习惯，仍然作为工场手工业的传统在工厂里延续着，后来被资本当作剥削劳动力的手段，在更令人厌恶的形式上得到了系统的恢复和巩固。过去是终身专门使用一种局部工具，现在是终身专门服侍一台局部机器。滥用机器的目的是要使工人自己从小就变成局部机器的一部分。这样，不仅工人自身再生产所必需的费用大大减少，而且工人终于毫无办法，只有依赖整个工厂，从而依赖资本家。在这里，象在其他各处一样，必须把社会生产过程的发展所造成的较大的生产率同这个过程的资本主义剥削所造成的较大的生产率区别开来。","language":"中文","translation":false},{"id":"capital-14-129","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在工场手工业和手工业中，是工人利用工具，在工厂中，是工人服侍机器。在前一种场合，劳动资料的运动从工人出发，在后一种场合，则是工人跟随劳动资料的运动。在工场手工业中，工人是一个活机构的肢体。在工厂中，死机构独立于工人而存在，工人被当作活的附属物并入死机构。","language":"中文","translation":false},{"id":"capital-14-130","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“在这种永无止境的苦役中，反复不断地完成同一个机械过程；这种苦役单调得令人丧气，就象息息法斯的苦刑一样；劳动的重压，象巨石般一次又一次地落在疲惫不堪的工人身上。”","language":"中文","translation":false},{"id":"capital-14-131","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器劳动极度地损害了神经系统，同时它又压抑肌肉的多方面运动，侵吞身体和精神上的一切自由活动。甚至减轻劳动也成了折磨人的手段，因为机器不是使工人摆脱劳动，而是使工人的劳动毫无内容。一切资本主义生产既然不仅是劳动过程，而且同时是资本的增殖过程，因此都有一个共同点，即不是工人使用劳动条件，相反地，而是劳动条件使用工人，不过这种颠倒只是随着机器的采用才取得了在技术上很明显的现实性。由于劳动资料变成了自动机，所以它在劳动过程本身中作为资本，作为支配和吮吸活劳动力的死劳动而同工人相对立。正如前面已经指出的那样，生产过程的智力同体力劳动相分离，智力变成资本支配劳动的权力，是在以机器为基础的大工业中完成的。变得空虚了的单个机器工人的局部技巧，在科学面前，在巨大的自然力面前，在社会的群众性劳动面前，作为微不足道的附属品而消失了；科学、巨大的自然力、社会的群众性劳动都体现在机器体系中，并同机器体系一道构成“主人”的权力。因此，当这位主人(在他的头脑中，机器和他对机器的垄断已经不可分割地结合在一起)同“人手”发生冲突时，他就轻蔑地对他们说：","language":"中文","translation":false},{"id":"capital-14-132","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“工厂工人们应当牢牢记住，他们的劳动实际上是一种极低级的熟练劳动；没有一种劳动比它更容易学会，按质量来说比它报酬更高；没有一种劳动能通过对最无经验的人进行短期训练而在这样短的时间这样大量地得到。在生产事务中，主人的机器所起的作用，实际上比工人的劳动和技巧所起的作用重要得多，因为工人的劳动和技巧6个月就可以教完，并且任何一个雇农都可以学会”。","language":"中文","translation":false},{"id":"capital-14-133","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工人在技术上服从劳动资料的划一运动以及由各种年龄的男女个体组成的劳动体的特殊构成，创造了一种兵营式的纪律。这种纪律发展成为完整的工厂制度，并且使前面已经提到的监督劳动得到充分发展，同时使那种把工人划分为劳工和监工，划分为普通工业士兵和工业军士的现象得到充分发展。 “自动工厂的主要困难在于建立必要的纪律，以便使人们抛弃无规则的劳动习惯，使他们和大自动机的始终如一的规则性协调一致。但是，发明一个适合自动体系的需要和速度的纪律法典，并有成效地加以实行，不愧是海格立斯式的事业，而这正是阿克莱的高尚成就！甚至在这个体系已完全建立起来的今天，也几乎不可能在成年工人中间为自动体系找到有用的助手。”","language":"中文","translation":false},{"id":"capital-14-134","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"资产阶级平时十分喜欢分权制，特别是喜欢代议制，但资本在工厂法典中却通过私人立法独断地确立了对工人的专制。这种法典只是对劳动过程实行社会调节的资本主义讽刺画，而这种调节是大规模协作和使用共同的劳动资料，特别是使用机器所必需的。奴隶监督者的鞭子被监工的罚金簿代替了。自然，一切处罚都简化成罚款和扣工资，而且工厂的莱喀古士们立法的英明，使犯法也许比守法对他们更有利。","language":"中文","translation":false},{"id":"capital-14-135","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在这里我们只提一下进行工厂劳动的物质条件。人为的高温，充满原料碎屑的空气，震耳欲聋的喧嚣等等，都同样地损害人的一切感官，更不用说在密集的机器中间所冒的生命危险了。这些机器象四季更迭那样规则地发布自己的工业伤亡公报。社会生产资料的节约只是在工厂制度的温和适宜的气候下才成熟起来的，这种节约在资本手中却同时变成了对工人在劳动时的生活条件系统的掠夺，也就是对空间、空气、阳光以及对保护工人在生产过程中人身安全和健康的设备系统的掠夺，至于工人的福利设施就根本谈不上了。傅立叶称工厂为“温和的监狱”难道不对吗？","language":"中文","translation":false},{"id":"capital-14-136","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"5、工人和机器之间的斗争","language":"中文","translation":false},{"id":"capital-14-137","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"资本家和雇佣工人之间的斗争是同资本关系本身一起开始的。在整个工场手工业时期，这场斗争一直如火如荼地进行着。但只是在采用机器以后，工人才开始反对劳动资料本身，即反对资本的物质存在形式。工人奋起反对作为资本主义生产方式的物质基础的这种一定形式的生产资料。","language":"中文","translation":false},{"id":"capital-14-138","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"十七世纪，反对所谓Bandmuhle(也叫做Schnurmuhle或Muhlenstuhl)即一种织带子和花边的机器的工人暴动几乎席卷了整个欧洲。十七世纪三十年代，一个荷兰人在伦敦附近开办的一家风力锯木场毁于贫民的暴行。十八世纪初在英国，水力锯木机好不容易才战胜了议会支持的民众反抗。1758年，埃弗雷特制成了第一台水力剪毛机，但是它被10万名失业者焚毁了。5万名一向以梳毛为生的工人向议会请愿，反对阿克莱的梳毛机和梳棉机。十九世纪最初十五年，英国工场手工业区发生的对机器的大规模破坏(特别是由于蒸汽织机的应用)，即所谓鲁德运动，为西德默思、卡斯尔里等反雅各宾派政府采取最反动的暴力行动提供了借口。工人要学会把机器和机器的资本主义应用区别开来，从而学会把自己的攻击从物质生产资料本身转向物质生产资料的社会使用形式，是需要时间和经验的。","language":"中文","translation":false},{"id":"capital-14-139","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工场手工业内部为工资而进行的斗争，是以工场手工业为前提的，根本不反对它的存在。至于说工场手工业的建立遭到反对，那末，这种反对是来自行会师傅和享有特权的城市，而不是来自雇佣工人。因此，工场手工业时期的著作家多半认为，分工是潜在地代替工人的手段，而不是现实地排挤工人的手段。这个区别是不言自明的。例如，我们说，现在英国50万人用机器纺掉的棉花，如果用旧式纺车来纺需要1亿人，这当然不是说机器占据了这从来没有存在过的1亿人的位置。这只是说，要代替纺纱机，需要上亿工人。反过来，我们说，在英国蒸汽织机把80万织工抛向街头，那末，这并不是说现有机器要由一定数量工人来代替，而是说现有的一定数量工人事实上已经被机器代替或排挤。在工场手工业时期，手工业生产虽然已经解体了，但仍旧是基础。中世纪遗留下来的城市工人相对来说是不多的，不能满足新的殖民地市场的需要；同时，真正的工场手工业为那些由于封建制度的解体而被赶出土地的农村居民开辟了新的生产领域。因此，当时工场内的分工和协作更多地显示了自己的积极方面，即提高在业工人的生产效率。［注：詹姆斯·斯图亚特爵士也完全从这个意义来理解机器的作用。“因此，我把机器看作(根据它的效率)增加不需要供养的劳动者人数的手段……机器的作用和那种新居民的作用有什么区别呢?”(《政治经济学原理研究》法译本第l卷第1分册第19章)配第天真得多，他说：机器代替了“一夫多妻制”。这个观点至多只适用于美国的某些地方。相反地，“使用机器来减少单个人的劳动是很少能成功的，因为制造机器用掉的时间，比使用机器所节省的时间要多。只有当机器大规模起作用时，当一台机器能帮助成千上万的人劳动时，机器才是真正有用的。因此，机器总是在人口最稠密，失业人数最多的地方使用最多……使用机器不是由于缺少工人，而是为了便于吸引大量工人参加劳动”(皮尔西·莱文斯顿《论公债制度及其影响》1824年伦敦版第45页)。］ 在许多国家中，早在大工业时期以前很久，协作和劳动资料在少数人手中的结合这种方法应用在农业上，确实使农村居民的生产方式，从而使他们的生活条件和就业手段发生了巨大的、突然的和强烈的革命。但是，这种斗争最初主要是在大土地所有者和小土地所有者之间发生的，而不是在资本和雇佣劳动之间发生的；另一方面，就劳动者被劳动资料(羊、马等等)排挤来说，那末在这里，直接的暴力行为首先形成工业革命的前提。先是劳动者被赶出土地，然后羊进去了。象在英国发生的那种大规模盗窃土地的现象，才为大农业开辟了活动场所。因此，农业的这个变革一开始就更具有政治革命的外观。","language":"中文","translation":false},{"id":"capital-14-140","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"劳动资料一作为机器出现，立刻就成了工人本身的竞争者。通过机器进行的资本的自行增殖，同生存条件被机器破坏的工人的人数成正比。资本主义生产的整个体系，是建立在工人把自己的劳动力当作商品出卖的基础上的。分工使这种劳动力片面化，使它只具有操纵局部工具的特定技能。一旦工具由机器来操纵，劳动力的交换价值就随同它的使用价值一起消失。工人就象停止流通的纸币一样卖不出去。工人阶级的一部分就这样被机器变成了过剩的人口，也就是不再为资本的自行增殖所直接需要的人口，这些人一部分在旧的手工业和工场手工业生产反对机器生产的力量悬殊的斗争中毁灭，另一部分则涌向所有比较容易进去的工业部门，充斥劳动市场，从而使劳动力的价格降低到它的价值以下。有人说，需要救济的工人会得到巨大的安慰：一方面，他们的痛苦只是“短暂的”(《a temporary inconvenience》[“短暂的不便”])；另一方面，机器只是逐渐地占据整整一个生产领域，因此它的破坏作用的范围和强度会缩减。一种安慰抵销另一种安慰。在机器逐渐地占据某一生产领域的地方，它给同它竞争的工人阶层造成慢性的贫困。在过渡迅速完成的地方，机器的影响则是广泛的和急性的。世界历史上再没有比英国手工织布工人缓慢的毁灭过程更为可怕的景象了，这个过程拖延了几十年之久，直到1838年才结束。在这些织布工人中，许多人饿死了，许多人长期地每天靠2 1/2便士维持一家人的生活。与此相反，英国的棉纺织机在东印度的影响却是急性的。1834—1835年东印度总督确认：","language":"中文","translation":false},{"id":"capital-14-141","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“这种灾难在商业史上几乎是绝无仅有的。织布工人的尸骨把印度的平原漂白了。”","language":"中文","translation":false},{"id":"capital-14-142","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"诚然，一旦这些织工结束自己短暂的一生，机器带给他们的就只是“短暂的不便”了。此外，由于机器不断占领新的生产领域，机器的“短暂的”影响也就成为长期的了。可见，资本主义生产方式使劳动条件和劳动产品具有的与工人相独立、相异化的形态，随着机器的发展而发展成为完全的对立。因此，随着机器的出现，才第一次发生工人对劳动资料的暴烈的反抗。","language":"中文","translation":false},{"id":"capital-14-143","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"劳动资料扼杀工人。当然，这种直接的对立，在新采用的机器同传统的手工业生产或工场手工业生产发生竞争时，表现得最明显。但在大工业本身内，机器的不断改良和自动体系的发展也发生类似的作用。","language":"中文","translation":false},{"id":"capital-14-144","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“改良机器的一贯目的，是减少体力劳动，或者说，是通过以铁的装置代替人的装置的方法使工厂的生产链条的某个环节完善起来。”“把蒸汽力和水力应用到以前用手推动的机器上，是每天都发生的事情……为了节省动力，改进产品，增加同样时间内的产量，或排挤掉一个童工、一个女工或一个男工等等，在机器上不断实行一些小的改良，这种改良虽然看起来没有多大意义，但会产生重要的结果。”“凡是某种操作需要高度熟练和准确的手的地方，人们总是尽快地把这种操作从过于灵巧和易于违犯各种规则的工人手中夺过来，把它交给一种动作非常规律、甚至儿童都能看管的特殊机械来进行。”“在自动体系下，工人的才能越来越受排挤。”“机器改良不仅可以减少为取得一定成果所雇用的成年工人的人数，而且用一种人代替另一种人：熟练程度低的代替熟练程度高的，儿童代替成年人，女工代替男工。所有这些变化都引起工资率的经常波动。”“机器不断地把成年人抛出工厂。”","language":"中文","translation":false},{"id":"capital-14-145","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器体系在缩短工作日的压力下的飞速发展向我们表明，由于实际经验的积累，由于机械手段的现有规模以及技术的不断进步，机器体系具有极大的弹力。但在1860年，英国棉纺织工业的这个全盛年，谁能料到此后三年在美国南北战争的刺激下竟会引起机器的急剧改良和手工劳动的相应被排挤呢？在这里，只要从英国工厂视察员关于这一问题的官方材料中引用几个例子就够了。曼彻斯特的一个工厂主说：","language":"中文","translation":false},{"id":"capital-14-146","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我们过去用75台梳棉机，现在只用12台，产量和过去一样，质量也和过去一样，甚至更好…… 每星期节省工资10镑，少出飞花10％。”","language":"中文","translation":false},{"id":"capital-14-147","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在曼彻斯特的一家精纺厂内，","language":"中文","translation":false},{"id":"capital-14-148","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“由于加速运转和采用各种自动过程，工人人数在一个车间削减了1/4，在另一个车间削减了1/2以上，而以精梳机代替二道粗梳机，又使从前梳棉间所雇用的人手大大减少了”。","language":"中文","translation":false},{"id":"capital-14-149","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"另一家纺纱厂估计该厂共节省10％的“人手”。曼彻斯特的吉尔摩公司纺纱厂主们说：","language":"中文","translation":false},{"id":"capital-14-150","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我们估计，由于采用新机器，在我们的清棉间整整节省了1/3的人手和工资……在粗纺间和并条间节省了将近1/3的费用和人手；在精纺间节省了将近1/3的费用。不仅如此，我们现在交给织布业主的纱的质量，由于采用新机器而大大改进了，因此织出的布比用旧机器纺的纱所织出的布又多又好。”","language":"中文","translation":false},{"id":"capital-14-151","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"关于这一点，工厂视察员亚·雷德格雷夫说道：","language":"中文","translation":false},{"id":"capital-14-152","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“在生产增加的同时，工人迅速减少；不久以前，毛纺织工厂又开始裁减人手，而且还在不断裁减；前几天，一位住在罗契得尔附近的教员对我说，女学校中人数大大减少，不仅是由于危机的压力，而且是由于毛纺织工厂机器的改良，改良后平均裁减了70个半日工。”","language":"中文","translation":false},{"id":"capital-14-153","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"美国南北战争引起的英国棉纺织工业的机械改良的总结果是，从1861年至1868年减少了338家棉纺织厂，这就是说，生产效率较高规模较大的机器集中在人数较少的资本家手中。蒸汽织机减少了20663台；但与此同时它们的产品增加了，可见，改良的织机现在提供的产品比旧式织机要多。最后，纱锭增加了1612547个，而在业工人却减少了50505人。因此，棉业危机压在工人身上的“暂时的”贫困，由于机器迅速不断的进步而加剧和持久了。","language":"中文","translation":false},{"id":"capital-14-154","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"但是，机器不仅是一个极强大的竞争者，随时可以使雇佣工人“过剩”。它还被资本公开地有意识地宣布为一种和工人敌对的力量并加以利用。机器成了镇压工人反抗资本专制的周期性暴动和罢工等等的最强有力的武器。用盖斯克尔的话来说，蒸汽机一开始就是“人力”的对头，它使资本家能够粉碎工人日益高涨的、可能使刚刚开始的工厂制度陷入危机的那些要求。可以写出整整一部历史，说明1830年以来的许多发明，都只是作为资本对付工人暴动的武器而出现的。我们首先想到的是走锭精纺机，因为它开辟了自动体系的新时代。","language":"中文","translation":false},{"id":"capital-14-155","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"蒸汽锤的发明者奈斯密斯，在他向工联调查委员会所作的证词中，谈到他由于1851年机器制造工人的长期大罢工而采用的机器改良时说：","language":"中文","translation":false},{"id":"capital-14-156","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我们现代机械改良的特征，是采用自动工具机。一个机械工人现在所要做的，并不是自己劳动，而是看管机器的出色劳动，这种活每一个男孩都能干。完全依仗自己技能的那类工人，现在全部被排除了。从前我用四个男孩配一个机械工人。由于这些新的机械联合，我把成年男工从1500人减到750人。结果，我的利润大大增加”。","language":"中文","translation":false},{"id":"capital-14-157","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"尤尔在谈到印花业中的一种印花机时说道：","language":"中文","translation":false},{"id":"capital-14-158","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“资本家终于求助于科学来摆脱这种难以忍受的奴役<也就是使他们感到负担的同工人签订的契约条件>，于是，他们很快地就恢复了自己的合法权利——头脑支配身体其他部分的权利。”","language":"中文","translation":false},{"id":"capital-14-159","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"他在谈到由于一次罢工而直接引起的浆纱方面的一项发明时说道：","language":"中文","translation":false},{"id":"capital-14-160","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“一帮不满分子自以为在旧的分工线上构筑了无法攻破的工事，却发现现代机械战术已把他们的侧翼包围，他们的防御手段已经毫无用处。他们只好无条件投降。”","language":"中文","translation":false},{"id":"capital-14-161","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"他在谈到走锭精纺机的发明时说道：","language":"中文","translation":false},{"id":"capital-14-162","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“它的使命是恢复工业阶级中间的秩序……这一发明证实了我们已经阐述的理论：资本迫使科学为自己服务，从而不断地迫使反叛的工人就范。”","language":"中文","translation":false},{"id":"capital-14-163","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"尤尔的著作虽然是在1835年，在工厂制度还不很发达的年代出版的，但这部著作仍不失为工厂精神的典型表现。这不仅是因为它包含的直率的昔尼克主义，而且还因为它天真地道出了资本头脑中的荒谬的矛盾。例如，他先阐述了这样一种“理论”：资本借助于受它供养的科学“不断地迫使反叛的工人就范”，然后他又怒气冲冲地说：","language":"中文","translation":false},{"id":"capital-14-164","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“有人竟从某一方面非难机械物理学，指责它助长富有的资本家的专制，充当压迫贫苦阶级的工具”。","language":"中文","translation":false},{"id":"capital-14-165","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":165,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"他到处宣扬机器的迅速发展对工人如何有利，然后又警告工人说，他们的反抗和罢工等等会加速机器的发展。他说：","language":"中文","translation":false},{"id":"capital-14-166","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":166,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“这种暴力的反叛表示了人们的目光短浅，因为他们具有非常可鄙的性格，竟使自己做了自己的刽子手。”","language":"中文","translation":false},{"id":"capital-14-167","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":167,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"与此相反，他在前几页曾说道：","language":"中文","translation":false},{"id":"capital-14-168","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":168,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“如果没有因为工人的错误见解而引起的激烈冲突和中断，工厂制度的发展还要迅速得多，给有关各方带来的利益还要大得多。”","language":"中文","translation":false},{"id":"capital-14-169","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":169,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“对大不列颠工厂区居民来说，值得庆幸的是，机械的改良只是逐渐实现的。”","language":"中文","translation":false},{"id":"capital-14-170","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":170,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“指责机器排挤了一部分成年工人，使成年工人的人数超过对劳动的需要，从而降低了他们的工资，这是不正确的。不过，机器扩大了对儿童劳动的需求，因而提高了儿童劳动的工资率。”","language":"中文","translation":false},{"id":"capital-14-171","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":171,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"另一方面，这位安慰家又为儿童的低工资辩护：“这阻止了父母们过早地把他们的孩子送进工厂”。尤尔的整个著作是一部维护无限制的工作日的辩护书。当立法规定13岁的儿童每天不得劳动12小时以上时，他这颗自由主义的心就回想起中世纪最黑暗的时代。但这并不妨碍他去诱劝工厂工人感谢上帝，因为上帝通过机器迫使他们“有了空闲时间去考虑自己的不朽利益”。","language":"中文","translation":false},{"id":"capital-14-172","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":172,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"6、关于被机器排挤的工人会得到补偿的理论","language":"中文","translation":false},{"id":"capital-14-173","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":173,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"詹姆斯·穆勒、麦克库洛赫、托伦斯、西尼耳、约翰·斯图亚特·穆勒等一系列资产阶级经济学家断言，所有排挤工人的机器，总是同时地而且必然地游离出相应的资本，去如数雇用这些被排挤的工人。","language":"中文","translation":false},{"id":"capital-14-174","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":174,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"假定有一家壁纸工场，资本家雇用100个工人，每人每年30镑。因此他每年支出的可变资本总共是3000镑。现在他解雇50个工人，雇用剩下的50个工人操纵他花费1500镑买来的机器。为了简单起见，我们把厂房、煤炭等等都撇开不说。再假定每年消耗的原料仍然是3000镑。经过这样的形态变化是否“游离”出任何资本呢？按旧的生产方式，在支出总额6000镑中，一半是不变资本，一半是可变资本。现在这个总额中，4500镑是不变资本(3000镑用于原料，1500镑用于机器)，1500镑是可变资本。可变的或转化为活劳动力的资本部分，不再是总资本的一半，而只是总资本的1/4。在这里，资本并没有被游离出来，倒是被束缚在一种不再同劳动力相交换的形式中，也就是说，可变资本转化为不变资本。现在，如果其他条件不变，这6000镑资本再也不能雇用50个以上的工人。机器每改良一次，这笔资本雇用的工人也就减少一次。如果新采用的机器的费用少于机器所排挤的劳动力和劳动工具的总额，比如说，不是1500镑而只是1000镑，那末，1000镑可变资本就被变成了不变资本，或者说，被束缚起来，而有500镑资本被游离出来。假定年工资是相同的，在解雇50个工人的情况下，这500镑资本就形成大约16个工人的就业基金，其实大大少于16个工人，因为要使500镑变成资本，就必须把其中的一部分再转化为不变资本，因而也只能把一部分转化为劳动力。","language":"中文","translation":false},{"id":"capital-14-175","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":175,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"再假定制造新机器会雇用较多的机械工人，这是不是应该算作对被解雇的壁纸工人的补偿呢？在最好的情况下，制造新机器所雇用的工人也比使用新机器所排挤的工人要少。这1500镑以前只代表被解雇的壁纸工人的工资，现在在机器的形式上则代表：1、制造机器所需要的生产资料的价值；2、制造机器的机械工人的工资；3、落到他们的“雇主”手里的剩余价值。此外，机器一经制成，在它报废以前就不需要再更新。因此，要连续雇用追加的机械工人，壁纸厂主就必须一个接一个地去用机器排挤工人。","language":"中文","translation":false},{"id":"capital-14-176","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":176,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"事实上，那些辩护士也并不是指用这种方式游离资本。他们指的是被游离出来的工人的生活资料。不可否认，例如在上述情况下，机器不仅游离出50个工人，从而使他们成为“可供支配的”，同时还割断了他们同价值1500镑的生活资料的联系，因而也就“游离”出这些生活资料。因此，机器把工人从生活资料中游离出来这一简单而又毫不新奇的事实，用经济学家的话一说，就成了机器替工人游离出生活资料，或机器把生活资料变成用来雇用工人的资本。可见，一切事情全看你怎么说。真是：好话能遮丑。","language":"中文","translation":false},{"id":"capital-14-177","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":177,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"按照这个理论，价值1500镑的生活资料，是一笔靠五十个被解雇的壁纸工人的劳动去增殖的资本。因此，一旦这五十个人被迫休假，这笔资本也就无事可做，但是在找到新的“投资场所”以前，它是不会安闲的，在那里，上述这五十个人可以重新在生产上消费它。可见，资本和工人迟早总要重新会合，而到那时补偿就实现了。可见，被机器排挤的工人所受的痛苦，正象这个世界上的财富一样，也是暂时的。","language":"中文","translation":false},{"id":"capital-14-178","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":178,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"价值1500镑的生活资料，从来没有作为资本同被解雇的工人对立过。作为资本同他们对立的，是现在转化成机器的1500镑。仔细地考察一下就会看出，这1500镑只是代表被解雇的50个工人一年所生产的壁纸的一部分，工人们从雇主那里以货币形式而不是以实物形式得到这一部分作为工资。他们用这些转化成1500镑的壁纸购买具有同样价值的生活资料。因此，这些生活资料对于他们来说，不是资本，而是商品，而他们本身对于这些商品来说，不是雇佣工人，而是买者。机器把他们从购买手段中“游离”出来，于是就把他们从买者变成非买者。因此对这些商品的需求减少了。如此而已。如果这种减少了的需求没有其他方面的增加了的需求来补偿，商品的市场价格就会下降。如果这种情况延续的时间较长而且范围较广，生产这些商品所雇用的工人就会被解雇。以前用来生产必要生活资料的一部分资本，就以其他的形式再生产出来。当市场价格下降和资本转移时，生产必要生活资料所雇用的工人也从一部分工资中被“游离”出来。可见，辩护士先生们并没有证明，机器由于把工人从生活资料中游离出来，同时就把这些生活资料变成雇用这些工人的资本；这些先生们反而用他们经过考验的供求规律证明了，机器不仅在采用它的生产部门，而且还在没有采用它的生产部门把工人抛向街头。","language":"中文","translation":false},{"id":"capital-14-179","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":179,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"被经济学上的乐观主义所歪曲的事实真相是：受机器排挤的工人从工场被抛到劳动市场，增加了那里已有的供资本随意剥削的劳动力的数量。我们在第七篇将会看到，机器的这种作用，在这里被说成是对工人阶级的补偿，其实正相反，是对工人的极端可怕的鞭笞。在这里只指出一点：从一个工业部门被抛出来的工人，当然可以在另外一个工业部门找职业。如果他们找到了职业，从而在他们和同他们一道被游离出来的生活资料之间重新建立了联系，那末，在这里起媒介作用的，是正在挤入投资场所的新追加的资本，而决不是过去已经执行职能的并且现在转化成机器的资本。并且，即使如此，他们的前途也是多么渺茫！这些因为分工而变得畸形的穷人，离开他们原来的劳动范围就不值钱了，只能在少数低级的、因而始终是人员充斥和工资微薄的劳动部门去找出路。其次，每个工业部门每年都吸收一批新人，供该部门用于人员的正常补充和扩充。一旦机器把一部分至今在一定工业部门就业的工人游离出来，这些补充人员也要重新分配，由其他劳动部门来吸收，不过，原来的那些牺牲者大部分在过渡期间堕落丧亡。","language":"中文","translation":false},{"id":"capital-14-180","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":180,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"一个毫无疑问的事实是：机器本身对于把工人从生活资料中“游离”出来是没有责任的。机器使它所占领的那个部门的产品便宜，产量增加，而且最初也没有使其他工业部门生产的生活资料的数量发生变化。因此，完全撇开年产品中被非劳动者挥霍掉的巨大部分不说，在应用机器以后，社会拥有的可供被排挤的工人用的生活资料同以前一样多，或者更多。而这正是经济学辩护论的主要点！同机器的资本主义应用不可分离的矛盾和对抗是不存在的，因为这些矛盾和对抗不是从机器本身产生的，而是从机器的资本主义应用产生的！因为机器就其本身来说缩短劳动时间，而它的资本主义应用延长工作日；因为机器本身减轻劳动，而它的资本主义应用提高劳动强度；因为机器本身是人对自然力的胜利，而它的资本主义应用使人受自然力奴役；因为机器本身增加生产者的财富，而它的资本主义应用使生产者变成需要救济的贫民，如此等等，所以资产阶级经济学家就简单地宣称，对机器本身的考察确切地证明，所有这些显而易见的矛盾都不过是平凡现实的假象，而就这些矛盾本身来说，因而从理论上来说，都是根本不存在的。于是，他们就用不着再动脑筋了，并且还指责他们的反对者愚蠢，说这些人不是反对机器的资本主义应用，而是反对机器本身。","language":"中文","translation":false},{"id":"capital-14-181","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":181,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"资产阶级经济学家绝不否认，在机器的资本主义应用中也出现短暂的不便；但是哪个徽章没有反面呢！对他们说来，机器除了资本主义的利用以外不可能有别的利用。因此，在他们看来，机器使用工人和工人使用机器是一回事。所以，谁要是揭露机器的资本主义应用的真相，谁就是根本不愿意有机器的应用，就是社会进步的敌人！这完全是著名的杀人犯比耳·赛克斯的道理：","language":"中文","translation":false},{"id":"capital-14-182","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":182,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“陪审官先生们，这些行商确实是被杀死了。但这不是我的罪过，这是刀的罪过。难道我们因为这种短暂的不便就该禁止用刀吗？请你们想一想！没有刀，哪里有农业和手工业？刀在外科手术上不是很能为人造福，在解剖方面不是给人带来知识吗？此外，在备办喜筵时，刀不是一位称心的助手吗？如果你们禁止用刀，那就等于把我们拖回到野蛮时代的深渊。”","language":"中文","translation":false},{"id":"capital-14-183","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":183,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"虽然机器在应用它的劳动部门必然排挤工人，但是它能引起其他劳动部门就业的增加。不过，这种作用同所谓的补偿理论毫无共同之处。既然任何一种机器产品，例如一码机织布，总是比被它排挤的同种手工产品便宜，所以就产生一条绝对的规律：如果机器生产的物品的总量同它所代替的手工业或工场手工业生产的物品的总量相等，那末，所使用的劳动总量就要减少。生产劳动资料本身如机器、煤炭等等所需要的劳动量的增加，同使用机器而引起的劳动量的减少相比，必然较小。不然的话，机器产品就会同手工产品一样贵，或者更贵。但是事实上，人数减少了的工人所生产的机器制品总量不是不变，而是远远超过被排挤的手工业制品的总量。假定生产40万码机织布所使用的工人，少于生产10万码手工织布所使用的工人。在四倍的产品中包含四倍的原料。因此原料的生产也必须增长为原来的四倍。至于所耗费的劳动资料，如厂房、煤炭、机器等，那末，生产这些东西所必须追加的劳动可能增长的界限，随着机器产品量和同数工人能够生产的手工产品量之间的差额而变化。","language":"中文","translation":false},{"id":"capital-14-184","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":184,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"可见，随着机器生产在一个工业部门的扩大，给这个工业部门提供生产资料的那些部门的生产首先会增加。就业工人数量会因此增加多少，在工作日长度和劳动强度已定的情况下，取决于所使用的资本的构成，也就是取决于资本不变部分和可变部分的比例。这个比例又随着机器在这些行业中已经占领或者正在占领的范围不同而有很大变化。随着英国机器体系的进展，注定要落到煤矿和金属矿中去的人数惊人地膨胀起来，尽管最近几十年，由于矿业中使用新机器，这种增加变得缓慢了。一种新工人随着机器出现了，这就是机器的生产者。我们已经知道，机器生产以越来越大的规模占领这个生产部门本身。再拿原料来说，毫无疑问，例如棉纺业的飞速发展极大地促进了美国的植棉业，从而不仅大大促进了非洲的奴隶贸易，而且还使饲养黑人成了所谓边疆蓄奴各州的主要事业。1790年，美国进行了第一次奴隶人口调查，当时共有奴隶697000人，而到1861年大约有400万人。另一方面，同样明确的是，机械毛纺织工厂的兴旺，以及耕地不断变成牧羊场，引起了农业劳动者的大量被驱逐和“过剩”。爱尔兰直到目前还在经历着这个过程，那里的人口从1845年以来几乎减少了一半，并且还在继续减少，以达到同爱尔兰大地主和英格兰毛纺织厂主先生们的需要恰好相适应的那个程度。","language":"中文","translation":false},{"id":"capital-14-185","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":185,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果机器占领了某一劳动对象在取得最终形式前所必须经过的初期阶段或中间阶段，那末，在这种机器制品还要进入的那些仍保持手工业或工场手工业生产方式的部门中，对劳动的需求就随着劳动材料的增加而增加。例如，机器纺纱业提供的棉纱又便宜又多，使得手工织布业者最初不用增加开支就可以利用充分的时间工作。这样一来，他们的收入增加了。于是人们纷纷拥向棉织业，直到这些被珍妮机、环锭精纺机和走锭精纺机比如说在英国招唤出来的80万织工最终又被蒸汽织机挤垮为止。同样，由于机器生产的衣料充足，男女裁缝和缝纫女工等等的人数也不断增加，直到缝纫机出现为止。","language":"中文","translation":false},{"id":"capital-14-186","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":186,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"机器生产用相对少量的工人所提供的原料、半成品、工具等等的数量日益增加了，与此相适应，对这些原料和半成品的加工就越分越细，因而社会生产部门也就越来越多样化。机器生产同工场手工业相比使社会分工获得无比广阔的发展，因为它使它所占领的行业的生产力得到无比巨大的增加。","language":"中文","translation":false},{"id":"capital-14-187","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":187,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"采用机器的直接结果是，增加了剩余价值，同时也增加了体现这些剩余价值的产品量，从而，在增加供资本家阶级及其仆从消费的物质时，也增加了这些社会阶层本身。这些社会阶层的财富的日益增加和生产必要生活资料所需要的工人人数的不断相对减少，一方面产生出新的奢侈要求，另一方面又产生出满足这些要求的新手段。社会产品中有较大的部分变成剩余产品，而剩余产品中又有较大的部分以精致和多样的形式再生产出来和消费掉。换句话说，奢侈品的生产在增长。大工业造成的新的世界市场关系也引起产品的精致和多样化。不仅有更多的外国消费品同本国的产品相交换，而且还有更多的外国原料、材料、半成品等作为生产资料进入本国工业。随着这种世界市场关系的发展，运输业对劳动的需求增加了，而且运输业又分成许多新的下属部门。","language":"中文","translation":false},{"id":"capital-14-188","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":188,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在工人人数相对减少的情况下生产资料和生活资料的增加，使那些生产在较远的将来才能收效的产品(如运河、船坞、隧道、桥梁等等)的工业部门中的劳动扩大了。一些全新的生产部门，从而一些新的劳动领域，或者直接在机器生产的基础上，或者在与机器生产相适应的一般工业变革的基础上形成起来。不过，它们在总生产中所占的比重，即使在最发达的国家，也不是很大的。它们所雇用的工人人数的增加，同它们对最粗笨的手工劳动的需求成正比。目前，这类工业主要有煤气厂、电报业、照像业、轮船业和铁路业。根据1861年的调查(在英格兰和威尔士)，煤气业(包括煤气厂、机械设备的生产、煤气公司的经理处等)有15211人，电报业有2399人，照像业有2366人，轮船业有3570人，铁路业有70599人(其中包括大约28000个比较固定的“非熟练的”掘土工人以及全部管理人员和商业人员)。所以，这五种新工业总共有94145人。","language":"中文","translation":false},{"id":"capital-14-189","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":189,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"最后，大工业领域内生产力的极度提高，以及随之而来的所有其他生产部门对劳动力的剥削在内含和外延两方面的加强，使工人阶级中越来越大的部分有可能被用于非生产劳动，特别是使旧式家庭奴隶在“仆役阶级”(如仆人、使女、侍从等等)的名称下越来越大规模地被再生产出来。根据1861年的人口调查，英格兰和威尔士的总人口为20066224人，其中男子9776259人，妇女10289965人。从中减掉不宜劳动的老幼，所有“非生产的”妇女、少年和儿童，再减掉官吏、牧师、律师、军人等“意识形态的”阶层以及所有专门以地租、利息等形式消费别人劳动的人，最后再减掉需要救济的贫民、流浪者、罪犯等，大致还剩下800万不同年龄的男女，其中包括所有以某种方式在生产、商业和金融等部门供职的资本家。在这800万人中，全部纺织厂的雇佣人员和煤矿、金属矿的人员加在一起是1208442人；全部纺织厂的雇佣人员和冶金厂、金属手工工场人员加在一起是1039605人；二者都少于现代家奴的人数1208648人。请看机器的资本主义应用获得了多么辉煌的结果！","language":"中文","translation":false},{"id":"capital-14-190","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":190,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"7、工人随机器生产的发展而被排斥和吸引。棉纺织业的危机","language":"中文","translation":false},{"id":"capital-14-191","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":191,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"政治经济学上一切头脑健全的代表人物都承认，新采用机器，对那些首先成为机器竞争对象的旧有手工业和工场手工业中的工人产生灾难性的影响。他们几乎全都为工厂工人的奴隶地位叹息。那末，他们打出的大王牌是什么呢？这就是：机器在其采用时期和发展时期的恐怖过去之后，最终是增加而不是减少劳动奴隶！是的，政治经济学正沉醉于一个令人厌恶的定理，一个连每个相信资本主义生产方式的永恒的自然必然性的“慈善家”都感到厌恶的定理：即使已经建立在机器生产的基础上的工厂，经过一定的发展时期，经过或长或短的“过渡时期”，也会让比它当初抛向街头的更多的工人进厂受苦！","language":"中文","translation":false},{"id":"capital-14-192","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":192,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"诚然，有些例子(例如英国精梳毛纺织厂和丝纺织厂)已经表明，到了一定的发展程度上，在工厂部门极度扩展的同时，所使用的工人人数不仅可能相对地减少，而且可能绝对地减少。1860年，根据议会的命令对联合王国所有的工厂进行过一次专门调查，在郎卡郡、柴郡和约克郡工厂区中属工厂视察员罗·贝克管辖的地区，共有652家工厂，其中570家拥有：蒸汽织机85622台，纱锭(不包括并纱锭)6819146个，蒸汽机27439马力，水车1390马力，雇用94119人。而到1865年，这些工厂拥有：织机95163台，纱锭7025031个，蒸汽机28925马力，水车1445马力，雇用88913人。可见，从1860年到1865年，这些工厂的蒸汽织机增加了11％，纱锭增加了3％，蒸汽马力增加了5％，而与此同时雇用的人数却减少了5.5％。在1852年到1862年期间，英国的毛纺织业获得了显著的发展，然而所使用的工人人数却几乎没有变化。","language":"中文","translation":false},{"id":"capital-14-193","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":193,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“这表明，新采用的机器以多么大的程度排挤了以前各时期的劳动。”","language":"中文","translation":false},{"id":"capital-14-194","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":194,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"根据某些经验过的事实，工厂工人就业人数的增加往往只是表面的，也就是说，这种增加并不是由于已经建立在机器生产基础上的工厂扩大了，而是由于附属部门逐渐和它合并。例如，1838—1858年期间，机械织机及其使用的工厂工人的增加，就(不列颠)棉纺织工厂来说，完全是由于这个生产部门的扩大，而在另外一些工厂中，则是由于过去用人的肌肉力推动的织毯机、织带机、织麻布机等等现在采用了蒸汽力。因此，这些工厂工人的增加只是表明就业工人总数的减少。最后，在这里还完全撇开了这种情况，就是除金属工厂外，到处都是少年工人(18岁以下的)、妇女和儿童在工厂人员中远居优势。","language":"中文","translation":false},{"id":"capital-14-195","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":195,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"然而我们知道，尽管机器生产实际地排挤和潜在地代替了大量工人，但随着机器生产本身的发展(这种发展表现为同种工厂数目的增多或现有工厂规模的扩大)，工厂工人的人数最终可以比被他们排挤的工场手工业工人或手工业工人的人数多。假定每周使用的500镑资本中，在旧的生产方式下不变部分占2/5，可变部分占3/5，也就是说，200镑用于生产资料，300镑用于劳动力，比如说1镑雇一个工人。由于采用机器生产，总资本的构成发生变化。假定现在这个资本分为4/5的不变部分和1/5的可变部分，或者说，用于劳动力的只有100镑。这样，过去雇用的工人就有2/3被解雇。如果工厂生产扩大，使用的总资本在其他生产条件不变的情况下由500镑增加到1500镑，那末现在就要雇用300个工人，和工业革命以前同样多。如果所使用的资本继续增加到2000镑，那末就要雇用400个工人，比采用旧的生产方式时多1/3。使用的工人人数绝对地增加了100人，相对地，即同预付总资本相比，却减少了800人，因为2000镑资本在旧的生产方式下能雇用1200个工人，而不是400个工人。可见，就业工人人数的相对减少和绝对增加是并行不悖的。上面假定，随着总资本的增加，资本的构成保持不变，因为生产条件保持不变。然而我们已经知道，随着机器体系的每一进步，由机器、原料等构成的不变资本部分不断增加，而用于劳动力的可变资本部分则不断减少，同时我们还知道，在任何其他的生产方式下，改良都不是这样经常进行，因而总资本的构成也不是这样经常变化。然而这种经常的变化也经常地被间歇时期和在既定技术基础上的单纯量的扩大所中断。因此就业工人的人数也就增加。例如，在1835年，联合王国的棉、毛、精梳毛、亚麻、丝等纺织厂的工人总数只有354684人，可是到1861年，仅蒸汽织机占用的织工(8岁以上的各种年龄的男女)就有230654人。当然，如果考虑到1838年不列颠的手工织布工人以及和他们一起工作的家属还有80万人，这种增加也就不算大了；而且这里还根本没有提到亚洲和欧洲大陆上被排挤掉的那些手工织布工人。","language":"中文","translation":false},{"id":"capital-14-196","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":196,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"关于这一点，还要作某些说明，其中我们将部分地谈到理论叙述本身还没有涉及到的一些纯粹事实方面的情况。","language":"中文","translation":false},{"id":"capital-14-197","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":197,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"只要机器生产在一个工业部门内靠牺牲旧有的手工业或工场手工业来扩展，它就一定取得成功，就象用针发枪装备的军队在对付弓箭手的军队时一定取得成功一样。机器刚刚为自己夺取活动范围的这个初创时期，由于借助机器生产出异常高的利润而具有决定性的重要意义。这些利润本身不仅形成加速积累的源泉，而且把不断新生的并正在寻找新的投资场所的很大一部分社会追加资本吸引到有利的生产领域。突飞猛进的初创时期的这种特殊利益，不断地在新采用机器的生产部门重现。但是，一旦工厂制度达到一定的广度和一定的成熟程度，特别是一旦它自己的技术基础即机器本身也用机器来生产，一旦煤和铁的采掘、金属加工以及交通运输业都发生革命，总之，一旦与大工业相适应的一般生产条件形成起来，这种生产方式就获得一种弹力，一种突然地跳跃式地扩展的能力，只有原料和销售市场才是它的限制。一方面，机器直接引起原料的增加，例如轧棉机使棉花生产增加。另一方面，机器产品的便宜和交通运输业的变革是夺取国外市场的武器。机器生产摧毁国外市场的手工业产品，迫使这些市场变成它的原料产地。例如东印度就被迫为大不列颠生产棉花、羊毛、大麻、黄麻、靛蓝等。大工业国工人的不断“过剩”，大大促进了国外移民和把外国变成殖民地，变成宗主国的原料产地，例如澳大利亚就变成了羊毛产地。一种和机器生产中心相适应的新的国际分工产生了，它使地球的一部分成为主要从事农业的生产地区，以服务于另一部分主要从事工业的生产地区。这种革命是同农业中的各种变革联系在一起的，关于这些变革，我们在这里还不需要作进一步的说明。","language":"中文","translation":false},{"id":"capital-14-198","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":198,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1867年2月18日，英国下院根据格莱斯顿先生的提议，编制了一份关于1831年到1866年期间联合王国各种谷物和面粉的总输入和输出的统计材料。我把总结果列举如下。面粉折合成以夸特为单位的谷物。(见下表)","language":"中文","translation":false},{"id":"capital-14-199","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":199,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂制度的巨大的跳跃式的扩展能力和它对世界市场的依赖，必然造成热病似的生产，并随之造成市场商品充斥，而当市场收缩时，就出现瘫痪状态。工业的生命按照中常活跃、繁荣、生产过剩、危机、停滞这几个时期的顺序而不断地转换。由于工业循环的这种周期变换，机器生产使工人在就业上并从而在生活上遭遇的无保障和不稳定状态，已成为正常的现象。除了繁荣时期以外，资本家之间总是进行十分激烈的斗争，以争夺各自在市场上的地位。这种地位同产品的便宜程度成正比。除了由此造成的资本家竞相采用代替劳动力的改良机器和新的生产方法以外，每次都出现这样的时刻：为了追求商品便宜，强制地把工资压低到劳动力价值以下。","language":"中文","translation":false},{"id":"capital-14-200","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":200,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"可见，工厂工人人数的增加以投入工厂的总资本在比例上更迅速得多的增加为条件。但是，这个过程只是在工业循环的涨潮退潮中间实现。而且它还经常被技术进步所打断，这种进步有时潜在地代替工人，有时实际地排挤工人。机器生产中这种质的变化，不断地把工人逐出工厂，或者把新的补充人员的队伍拒之门外，而工厂的单纯的量的扩大则不仅把被驱逐的工人吸收进来，而且还把新的人员吸收进来。工人就这样不断被排斥又被吸引，被赶来赶去，并且被招募来的人的性别、年龄和熟练程度也不断变化。","language":"中文","translation":false},{"id":"capital-14-201","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":201,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"只要粗略地看一下英国棉纺织业的命运，就可以再清楚不过地了解工厂工人的命运。","language":"中文","translation":false},{"id":"capital-14-202","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":202,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"从1770年到1815年，棉纺织业有5年处于不振或停滞状态。在这最初的45年，英国工厂主垄断了机器和世界市场。从1815年到1821年，不振。1822年和1823年，繁荣。1824年，废除禁止结社法，工厂普遍大扩展。1825年，危机。1826年，棉纺织业工人极端贫困，发生暴动。1827年，略有好转。1828年，蒸汽织机和输出量大增。1829年，输出(特别是向印度的输出)超过历年。1830年，市场商品充斥，境况艰难。1831年到1833年，连续不振；东印度公司对东亚(印度和中国)贸易的垄断权被取消。1834年，工厂和机器大增，工人不足。新济贫法促进农业工人向工厂区流动。农业各郡的儿童被劫掠一空。白奴贸易。1835年，大繁荣。同时，手工织布工人饥饿待毙。1836年，大繁荣。1837年和1838年，不振状态和危机。1839年，复苏。1840年，严重萧条，发生暴动，军队出动干涉。1841年和1842年，工厂工人遭到可怕的穷困。1842年，工厂主解雇工人以便迫使废除谷物法。成千上万的工人涌向约克郡，又被军队驱回，工人的领袖被提交郎卡斯特法庭。1843年，严重贫困。1844年，复苏。1845年，大繁荣。1846年，起初是继续高涨，以后有相反的征候。谷物法被废除。1847年，危机。为庆祝“大圆面包”，［注：反谷物法同盟拥护者通过蛊惑性的宣传要工人们相信，随着贸易自由的实行，他们的实际工资将要提高，工人们将提到比从前大一倍的大圆面包。而且，他们还拿着两个写着有关字句的面包——一个大的和一个小的——在街上形象地进行鼓动。现实生活揭穿了这些诺言的全部欺骗性。由于谷物法的废除而得到巩固的英国工业资本加紧对工人阶级的切身利益的进攻。］ 工资普遍降低10％或10％以上。1848年，继续不振。曼彻斯特处于军队保护之下。1849年，复苏。1850年，繁荣。1851年，商品降价，工资低微，罢工频繁。1852年，开始好转。罢工继续发生，工厂主以输入外国工人相威胁。1853年，输出增加。普雷斯顿罢工持续八个月，严重贫困。1854年，繁荣，市场商品充斥。1855年，破产消息从美国、加拿大和东亚市场纷纷传来。1856年，大繁荣。1857年，危机。1858年，好转。1859年，大繁荣，工厂增加。1860年，英国棉纺织业达到顶点。印度、澳大利亚以及其他市场上商品过剩，直到1863年几乎还没有销完全部存货。同法国缔结贸易协定。工厂和机器激增。1861年，高涨持续了一些时候，随后出现相反的趋势，美国南北战争，棉荒。1862年到1863年，完全崩溃。","language":"中文","translation":false},{"id":"capital-14-203","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":203,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"棉荒的历史太有代表性了，我们不能不略为叙述一下。从1860年到1861年的世界市场状况的简述中可以看出，对于工厂主来说，棉荒发生的正是时候，部分地说对于他们是有利的。这是个事实，它已被曼彻斯特商会的报告所承认，帕麦斯顿和得比在议会中也宣布过，而且也为实际情况证明了。当然，1861年联合王国的2887家棉纺织厂中，有许多是小工厂。在这2887家工厂中，有2109家是属于工厂视察员亚·雷德格雷夫的管辖范围。根据他的报告，在这2109家工厂中，使用还不到10蒸汽马力的有392家，占19％；使用10到20马力之间的有345家，占16％；使用20马力和20马力以上的有1372家。小工厂多半是在1858年以后的繁荣时期建立起来的织布厂，而且大部分是靠一些投机家分头出棉纱、出机器、出厂房建立起来的，交由以前的监工或其他没有资财的人经营。这些小工厂主大部分已经破产了。其实，棉荒避免了商业危机，不然他们也会遭到同样的命运。虽然他们占工厂主总数的1/3，但是他们工厂的资本只占投入棉纺织业的资本的很小很小一部分。至于瘫痪的规模，据可靠估计，1862年10月有60.3％的纱锭和58％的织机停工。这是整个工业部门的情况，各个区的情况当然是很不同的。只有极少数的工厂开全工(每周60小时)，其余工厂都有停工现象。即使那些做全工并且照例拿计件工资的少数工人，由于次棉代替好棉，埃及棉代替海岛棉(在精纺厂)、苏拉特棉(东印度)代替美棉和埃及棉，以及飞花掺苏拉特棉代替纯棉，所得到的周工资也不可避免地减少了。苏拉特棉纤维较短，质地不纯，棉纱易断，经纱上浆不用面粉而用各种重拼料，以及其他等等，这一切都减低了机器的速度，或者减少了一个织工所能看管的织机台数，增加了纠正机器差错所花的劳动，在减少产量的同时也减少了计件工资。使用苏拉特棉时，做全工的工人也要遭受20％、30％或更多的损失。而多数工厂主又把计件工资率降低了5％，7.5％和10％。因此，那些每周只劳动3天、3天半、4天或者每天只劳动6小时的工人的处境也就可想而知了。1863年时，情况已经比较好转，织布工人、纺纱工人等的周工资也只有3先令4便士、3先令10便士、4先令6便士、5先令1便士等。即使在这样悲惨的状况下，工厂主在克扣工资方面的创造精神也没有丝毫减退。工厂主的棉花不好和机器不合用等等使产品出了毛病，这也成了罚扣工资的部分原因。如果工厂主还是工人住的小屋的房主，那他还要从名义工资中扣除一部分算作房租。工厂视察员雷德格雷夫谈到走锭精纺机的看管工(他们每人看管两台走锭精纺机)时说道：他们","language":"中文","translation":false},{"id":"capital-14-204","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":204,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“做满14天全工，得到8先令11便士；从这个数中扣除房租，而工厂主又把房租的一半作为礼物送还工人，这样看管工拿回家去的总共是6先令11便士。1862年的最后时期，织布工人周工资最低是2先令6便士”。","language":"中文","translation":false},{"id":"capital-14-205","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":205,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"甚至工人只劳动很短的时间，也常常要从工资中扣除房租。难怪在郎卡郡的某些地方发生一种饥饿病！但比这一切更能表明特征的是：生产过程的革命是靠牺牲工人来进行的。这就象解剖学家拿青蛙作实验一样，完全是拿无价值的生物体作实验。工厂视察员雷德格雷夫说：","language":"中文","translation":false},{"id":"capital-14-206","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":206,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我虽然列举了许多工厂的工人的实际收入，但是不能认为，他们每星期都能得到这个数目。由于工厂主不断地进行实验，工人的状况极不稳定……他们的收入随着混合棉的质量而增减，有时和过去相差15％，而过一两个星期竟降低50％至60％。”","language":"中文","translation":false},{"id":"capital-14-207","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":207,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这些实验不仅靠牺牲工人的生活资料来进行，而且还以牺牲工人的全部五官为代价。","language":"中文","translation":false},{"id":"capital-14-208","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":208,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“拆棉花包的工人告诉我，难忍的臭味薰得人恶心…… 在混棉间、清棉间和梳棉间里，棉屑和尘埃飞扬，刺激人的七窍，弄得人咳嗽和呼吸困难…… 由于纤维短，浆纱时棉纱上附加大量的材料，而且是用各种代用品来代替原来使用的面粉。这就引起织布工人恶心呕吐和消化不良。因为灰尘多，支气管炎、咽喉炎十分流行；其次，由于苏拉特棉里的脏东西刺激皮肤，皮肤病也很流行。”","language":"中文","translation":false},{"id":"capital-14-209","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":209,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"另一方面，面粉的代用品由于增加棉纱的重量而成为工厂主先生们的福尔土纳特的钱袋。这些代用品使“15磅原料在纺成纱后重20磅”。工厂视察员1864年4月30日的报告说：","language":"中文","translation":false},{"id":"capital-14-210","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":210,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“现在，工业上使用这种办法简直达到卑鄙无耻的程度。我从可靠方面得知，8磅的布是由5 1/4磅棉花和2 3/4磅浆料制成的。另外一疋5 1/4磅的布里含有两磅浆料。这还是供出口的普通的衬衫布。别种布里有时竟加了50％的浆料，因此工厂主可以吹嘘，而且确实也在吹嘘，说他们之所以发财致富，是因为他们卖的布，比布在名义上包含的纱的价值还便宜。”","language":"中文","translation":false},{"id":"capital-14-211","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":211,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"可是，工人们不只是苦于工厂主在厂内的实验和市政当局在厂外的实验，不只是苦于工资降低和失业、贫困和救济以及上下两院的赞美词。","language":"中文","translation":false},{"id":"capital-14-212","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":212,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“因棉荒而失业的不幸的妇女们，成了社会的遗弃者，而且现在仍然如此…… 年轻妓女的数目比过去25年增多了。”","language":"中文","translation":false},{"id":"capital-14-213","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":213,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"可见，不列颠棉纺织工业在最初的45年中，即从1770年到1815年，只有5年是危机和停滞状态，但这45年是它独霸世界的时期。在第二个时期，即从1815年到1863年的48年间，只有20年是复苏和繁荣时期，却有28年是不振和停滞时期。从1815年到1830年，开始同欧洲大陆和美国竞争。从1833年起，靠“毁灭人种”的办法强行扩大亚洲市场。谷物法废除之后，从1846年到1863年，有8年是中常活跃和繁荣时期，却有9年是不振和停滞时期。棉纺织业中的成年男工的状况，即使是在繁荣时期，也可根据下面的附注作出判断。［注：1863年春，棉纺织工人在要求成立移民协会的一份呼吁书中说：“工厂工人的大量移民在目前是绝对必要的，这一点只有少数人才会否认。下列事实表明，经常不断地移民在任何时候都是需要的，否则我们就不能维持我们平时的地位。这些事实就是：1814年，输出的棉织品的官方价值（这只是数量的指数）是17665378镑，而其实际市场价值是20070824镑；1858年，输出的棉织品的官方价值是182221681镑，而其实际市场价值只是43001322镑；数量增加为十倍，而卖得的价格只增加一倍多一些。这种对于整个国家特别是对于工厂工人极其有害的结果，是由各种同时起作用的原因造成的。最突出的原因之一是劳动的经常过剩，而这种过剩对我们这个生产部门来说是必需的，因为它在被消灭的威胁下需要不断扩大市场。在现有制度下，商业的周期性停滞就象死亡一样不可避免，而这种停滞可能使我们棉纺织工厂停工。但是，人的创造精神并不因此就停歇下来。根据最低的估计，最近25年有600万人离开了这个国家，尽管如此，由于为了使产品便宜而不断排斥劳动，甚至在最繁荣的时期，仍然有很大一部分成年男工无法在工厂找到任何条件的任何工作。”（《工厂视察员报告。1863年4月30日》第51、52页）在以后的某章中，我们会看到，在棉纺织业的大灾难中，工厂主先生们是怎样用尽一切办法，甚至借助国家权力，来力图阻止工厂工人的外移。］","language":"中文","translation":false},{"id":"capital-14-214","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":214,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"8、大工业所引起的工场手工业、手工业和家庭劳动的革命","language":"中文","translation":false},{"id":"capital-14-215","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":215,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"(a)以手工业和分工为基础的协作的消灭","language":"中文","translation":false},{"id":"capital-14-216","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":216,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"我们已经看到，机器如何消灭了以手工业为基础的协作和以手工业分工为基础的工场手工业。收割机是前一种情况的例子，它代替了收割者的协作。制针机是后一种情况的明显例子。据亚当·斯密说，在他那时候，10个男人分工合作每天能制针48000多枚。但是现在，一台机器在一个十一小时工作日中就能制针145000枚。一个妇女或少女平均可以看管4台这样的机器，因此，她用机器每天可以生产针近60万枚，每星期就可以生产300多万枚。如果一台单个的工作机代替了协作或工场手工业，那末，工作机本身又可以成为手工业生产的基础。但是，手工业生产在机器基础上的再现只是向工厂生产的过渡，只要机械动力(蒸汽或水)代替人的肌肉来推动机器，工厂生产通常就会出现。小生产可以间或地，并且也只能是暂时地同机械动力结合起来，那或是靠租用蒸汽，如北明翰的某些工场手工业，或是靠采用小型卡路里机，如织布业等的某些部门。在考文垂的丝织业里，一种“小屋工厂”的实验曾自发地发展起来。由几排小屋围成的方形场地的中间，建起一座安装蒸汽机的所谓机器房，蒸汽机通过枢轴同各个小屋中的织机连接起来。蒸汽一律是租用的，例如每台织机交2 1/2先令。不管织机是否转动，蒸汽费都得按周支付。每个小屋有2—6台织机，这些机器有的是工人的，有的是赊购的，有的是租来的。小屋工厂和真正的工厂之间的斗争持续了12年以上。结果是300家小屋工厂完全破产。在过程的性质并不是一开始就要求大规模生产的场合，那些最近几十年间新兴的工业，例如信封制造业、钢笔尖制造业等等，通常都是先经过手工业生产，然后经过工场手工业生产这些短暂的过渡阶段才达到工厂生产。这种形态变化，在工场手工业性质的制品生产不是由顺序展开的过程组成，而是由许多各不相干的过程组成的地方，会特别困难。例如，这种情形对于钢笔尖工厂就是一大障碍。但是大约十五年前就已经发明了一种自动机，可以一下子完成6种各不相干的过程。1820年手工业提供的第一批12打钢笔尖价格7镑4先令，1830年工场手工业提供的为8先令，而现在工厂提供给批发商的价格是2到6便士。","language":"中文","translation":false},{"id":"capital-14-217","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":217,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"(b)工厂制度对于工场手工业和家庭劳动的反作用","language":"中文","translation":false},{"id":"capital-14-218","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":218,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"随着工厂制度的发展和随之而来的农业的变革，不仅所有其他工业部门的生产规模扩大了，而且它们的性质也发生了变化。机器生产的原则是把生产过程分解为各个组成阶段，并且应用力学、化学等等，总之就是应用自然科学来解决由此产生的问题。这个原则到处都起着决定性的作用。因此，机器时而挤进工场手工业的这个局部过程，时而又挤进那个局部过程。这样一来，从旧的分工中产生的工场手工业组织的坚固结晶就逐渐溶解，并不断发生变化。此外，总体工人即结合工人的构成也发生了根本的变革。同工场手工业时期相反，现在，只要可行，分工的计划总是把基点放在使用妇女劳动、各种年龄的儿童劳动和非熟练工人劳动上，总之，就是放在使用英国人所谓的“廉价劳动”上。这一情况不仅适用于使用机器或者不使用机器的一切大规模结合的生产，而且适用于在工人的私人住宅或者在小工场中进行生产的所谓家庭工业。这种所谓的现代家庭工业，与那种以独立的城市手工业、独立的农民经济，特别是以工人家庭的住宅为前提的旧式家庭工业，除了名称，毫无共同之处。现在它已经变成了工厂、手工工场或商店的分支机构。资本除了把工厂工人、手工工场工人和手工业工人大规模地集中在一起，并直接指挥他们，它还通过许多无形的线调动着另一支散居在大城市和农村的家庭工人大军。例如，梯利先生在爱尔兰的伦敦德里所开设的衬衫工厂，就雇用着1000个工厂工人和9000个散居在农村的家庭工人。","language":"中文","translation":false},{"id":"capital-14-219","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":219,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"现代工场手工业中对廉价劳动力和未成熟劳动力的剥削，比在真正的工厂中还要无耻，因为工厂所拥有的技术基础，即代替肌肉力的机器和轻便的劳动，在现代工场手工业中大多是不存在的；同时，在现代工场手工业中，女工或未成熟工人的身体还被丧尽天良地置于毒物等等的侵害之下。而这种剥削在所谓的家庭劳动中，又比在工场手工业中更加无耻，这是因为：工人的反抗力由于分散而减弱，在真正的雇主和工人之间挤进了一大批贪婪的寄生虫，家庭劳动到处和同一生产部门的机器生产或者至少是同工场手工业生产进行竞争，贫困剥夺了工人必不可少的劳动条件——空间、光线、通风设备等等，职业越来越不稳定，最后，在这些由大工业和大农业所造成的“过剩”人口的最后避难所里，工人之间的竞争必然达到顶点。由于采用机器生产才系统地实现的生产资料的节约，一开始就同时是对劳动力的最无情的浪费和对劳动的正常条件的剥夺，而现在，在一个工业部门中，社会劳动生产力和结合的劳动过程的技术基础越不发达，这种节约就越暴露出它的对抗性的和杀人的一面。","language":"中文","translation":false},{"id":"capital-14-220","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":220,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"现在，我举几个例子来说明上述原理。其实读者已经从工作日那一章看到大量例证。北明翰及其近郊的金属手工工场除雇用1万个妇女外，还雇用3万个儿童和少年，大多数都干着很重的活。他们在这里的有害健康的铸铜业、钮扣业、珐瑯业、电镀业和油漆业中劳动。伦敦的各家书报印刷厂由于让成年和未成年的工人从事过度劳动而博得了“屠宰场”的美名。在订书业中也存在着这种过度劳动，这里的牺牲品主要是妇女、少女和儿童。在制绳业中，未成年的工人担负着繁重的劳动，在制盐、制蜡烛以及其他化工工场中，他们还得做夜工，在尚未采用机械动力的丝织业中，织机是由少年来推动的，这种活简直能累死人。一种最丢脸、最肮脏、报酬最低、主要是雇用少女和妇女来干的活是清理破布。我们知道，大不列颠不仅自己拥有无数的破布，而且还是全世界破布贸易的中心。破布从日本、遥远的南美各国和卡内里群岛流进来。但是，它的主要供应来源是德国、法国、俄国、意大利、埃及、土耳其、比利时和荷兰。破布可以做肥料、床垫、再生呢绒，还可以当作造纸的原料。这些清理破布的女工是传播天花及其他传染病的媒介，而她们自己就是这些疾病的最先的牺牲者。除金属矿和煤矿之外，砖瓦工场可以作为典型的例子，来说明过度劳动、繁重的和不适当的劳动以及那些从幼年起就被使用的工人在这方面所受到的摧残。在英国，这种砖瓦工场只是间或采用新发明的机器(1866年)。从5月到9月，劳动是从早晨5点起到晚上8点止，如果是在户外晾干，则往往从早晨4点起到晚上9点止。早晨5点至晚上7点的工作日算是“缩短的”、“适度的”了。男女儿童从6岁起，甚至从4岁起就被使用。他们劳动的时间同成年人一样长，甚至往往比成年人还要长。活很吃力，夏天的酷热更容易使人精疲力竭。例如在莫斯莱的一个制砖工场，一个24岁的姑娘每天制砖2000块，只有两个未成年的女孩子作助手，帮她运土和垛砖。这两个女孩子每天要从30呎深的土坑里通过很滑的斜坡挖出10吨粘土，并把它运到210呎远的地方去。","language":"中文","translation":false},{"id":"capital-14-221","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":221,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“通过制砖工场这座炼狱，儿童在道德上没有不极端堕落的…… 他们从幼年起就听惯了各种下流话，他们在各种卑劣、猥亵、无耻的习惯中野蛮无知地长大，这就使他们日后变成无法无天、放荡成性的无赖汉…… 他们的居住方式是道德败坏的一个可怕根源。每个成型工<他是真正的熟练工人，又是一个工人小组的头>要在自己的小屋里安排他这一班7个人的吃和住。这些人不管是不是他的家里人，男女青少年都睡在他的小屋里。这种小屋通常只有2个房间，个别的才有3个房间，他们统统睡在地上，通风很差。他们劳累一天，混身汗水，已经精疲力竭，哪还能讲究卫生、清洁和礼貌。这样的小屋多数都是混乱和肮脏的真正标本…… 雇用少女干这种活的最大弊病就是，这种情况往往使她们从幼年起就终生沦为放荡成性的败类。在自然使她们懂得自己是个女人之前，她们已经变成粗鲁的、出言下流的男孩子。她们身上披着几块肮脏的布片，裸露大腿，蓬头垢面，根本不在乎什么端庄和羞耻。吃饭的时候，她们伸开四肢躺在田野上，或者偷看在附近河里洗澡的小伙子。她们干完了白天的重活，就换一身好一点的衣服，陪着男人上酒馆。”","language":"中文","translation":false},{"id":"capital-14-222","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":222,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"所有这种工人从幼年起都酗酒，这完全是很自然的事。","language":"中文","translation":false},{"id":"capital-14-223","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":223,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“最糟糕的是，制砖工人自暴自弃。一个比较好的工人曾对南奥菲尔德的牧师说，先生，您感化一个制砖工人，那简直比感化魔鬼还难！”","language":"中文","translation":false},{"id":"capital-14-224","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":224,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"关于现代工场手工业(这里指除真正的工厂之外的一切大规模的工场)中劳动条件的资本主义的节约，可以在《公共卫生报告》第4号(1861年)和第6号(1864年)中找到大量的官方材料。报告中关于工场，特别是关于伦敦印刷业和裁缝业工场的描绘，超过了我们的小说家的最可怕的幻想。对工人健康状况的影响，是不言而喻的。枢密院主任医官兼《公共卫生报告》主编西蒙医生说：","language":"中文","translation":false},{"id":"capital-14-225","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":225,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我在我的第4号报告<1861年>中曾指出，工人要坚持他们首要的健康权利，也就是说，要求雇主无论叫工人干什么活时，都要在责任所及的范围内，使劳动避免一切可以避免的有害健康的情况，这实际上是办不到的。我曾指出，当工人事实上没有能力自己实现这个健康权利的时候，他们也不可能从卫生警察官吏那里得到任何有效的帮助…… 现在，成千上万的男女工人的生命，只是由于他们的职业所造成的无止境的肉体折磨，便无谓地受到摧残而缩短了。”","language":"中文","translation":false},{"id":"capital-14-226","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":226,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"为了说明工场对工人健康状况的影响，西蒙医生还列出一张死亡统计表［注：《公共卫生。第6号报告》1864年伦敦版第30页。西蒙医生指出，伦敦25—35岁的裁缝和印刷工人的死亡率实际上还要高得多，因为他们的伦敦雇主从农村得到大量的30岁以下的青年“学徒”和“实习生”（即那些想提高自己手艺的人）。这些人在调查中算作伦敦人，他们使伦敦死亡率的计算基数增大了，但是并没有使伦敦死亡的人数相应增加，因为他们当中大部分人要返回农村去，特别是在患重病的时候。（同上）］ ：","language":"中文","translation":false},{"id":"capital-14-227","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":227,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"不同年龄的工人人数在健康方面互相比较的","language":"中文","translation":false},{"id":"capital-14-228","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":228,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"几个产业部门各有关产业部门按年龄划分","language":"中文","translation":false},{"id":"capital-14-229","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":229,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"每10万人中的死亡率 25—35岁35—45岁 45—55岁 958265英格兰和威尔士的农业743 8051145 男 22301","language":"中文","translation":false},{"id":"capital-14-230","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":230,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"女 12377伦敦的裁缝业 95812622093 13803伦敦的印刷业894 17472367","language":"中文","translation":false},{"id":"capital-14-231","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":231,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"我现在来谈谈所谓家庭劳动。为了对这个在大工业的背景下建立起来的资本的剥削领域和它的骇人听闻的状况有个简略的了解，不妨考察一下例如英格兰某些偏僻乡村经营的那些表面上充满田园风味的制钉业。不过在这里，只要从花边业和草辫业中完全没有采用机器，或者同机器生产和工场手工业生产完全没有发生竞争的部门中举出几个例子就够了。","language":"中文","translation":false},{"id":"capital-14-232","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":232,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在英国从事花边生产的共有15万人，其中受1861年工厂法约束的大约有1万人，其余的14万人绝大多数是妇女、男女少年和儿童，其中男性很少。这些“廉价的”剥削材料的健康状况，可以从诺定昂贫民诊所特鲁曼医生的下列统计材料中看出来。在686个患病的花边女工(大部分是17岁到24岁)中，患肺病的比率如下：","language":"中文","translation":false},{"id":"capital-14-233","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":233,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1852年每45人中有1人 1857年每13人中有1人","language":"中文","translation":false},{"id":"capital-14-234","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":234,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1853年每28人中有1人 1858年每15人中有1人","language":"中文","translation":false},{"id":"capital-14-235","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":235,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1854年每17人中有1人 1859年每9人中有1人","language":"中文","translation":false},{"id":"capital-14-236","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":236,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1855年每18人中有1人 1860年每8人中有1人","language":"中文","translation":false},{"id":"capital-14-237","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":237,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1856年每15人中有1人 1861年每8人中有1人","language":"中文","translation":false},{"id":"capital-14-238","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":238,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"肺病率的这种增长，一定会使最乐观的进步党人和最善于象孚赫那样撒谎的德国自由贸易论贩子感到满意的。","language":"中文","translation":false},{"id":"capital-14-239","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":239,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"受1861年工厂法约束的是采用机器生产的真正花边业，而在英国，这一行业通常都已经采用机器了。我们要在这里略加考察的部门(我们的考察仅限于所谓家庭工人，而不涉及集中在手工工场和商店等处的工人)，可分为两类：一类是花边整理(对机织花边进行最后加工，它又分成许多工种)，另一类是手织花边。","language":"中文","translation":false},{"id":"capital-14-240","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":240,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"花边整理当作一种家庭劳动，或者是在所谓“老板娘家”进行的，或者是在妇女家里由她自己或同她的子女一道进行的。那些开设“老板娘家”的妇女本身也是贫穷的。工场就是她们的私宅的一部分。她们从工厂主或商店老板等人那里承揽定货，使用妇女、少女和幼童的劳动，其人数要看她们房间的大小和营业需要的变动情况而定。雇用的女工的人数有些地方是20至40人，有些地方是10至20人。儿童开始劳动的平均最低年龄是6岁，但有些儿童不满5岁就开始劳动了。劳动时间通常是从早晨8点到晚上8点，中间有1 1/2小时的吃饭时间，吃饭时间很不规则，而且往往是在臭气熏天的小工房里吃饭。生意好的时候，往往从早晨8点(有时是6点)干到夜里10、11或12点。在英国兵营中，每个士兵规定占有500至600立方呎的空间，在军医院里规定占1200立方呎。而在这样的小工房里，每人只有67—100立方呎。同时煤气灯还消耗空气中的氧气。为了保持花边的清洁，即使在冬天，儿童们也往往必须把鞋脱掉，哪怕地面上砌的是石板或砖块。","language":"中文","translation":false},{"id":"capital-14-241","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":241,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“在诺定昂，常常可以看到15个至20个儿童挤在一间也许不超过12呎见方的小房间里，一天24小时内要干15小时，这种劳动本身由于单调乏味而令人厌倦，而且劳动条件对健康极为不利…… 甚至年龄最小的儿童干起活来也紧张得要命和迅速得惊人，手指几乎不能稍停一下或放慢一点。如果有人向他们问话，他们也眼不离活，唯恐耽误了一分一秒。”","language":"中文","translation":false},{"id":"capital-14-242","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":242,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"劳动时间越长，“老板娘”用“长棍”来催促儿童的次数就越多。","language":"中文","translation":false},{"id":"capital-14-243","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":243,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“儿童们逐渐贫乏了。他们的劳动单调乏味，极费眼力，由于姿势持久不变而格外累人，当这种长时间的劳动快要结束时，他们简直象小鸟一样不能安静下来。这是真正的奴隶劳动。”","language":"中文","translation":false},{"id":"capital-14-244","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":244,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果妇女是同自己的子女在家里(这个家，在现代意义上，就是租来的一间房子，往往是一间阁楼)一道劳动时，情况更坏到不能再坏了。这种劳动在诺定昂周围80哩的地区内都可见到。在商店干活的儿童，晚上9点或10点下工时，往往还要给他一捆活，让他带回家去干。资本主义的伪君子这样做时，当然会通过他的雇佣奴才的嘴巴说上一句漂亮话：“这是给你母亲的”，但是他非常清楚，可怜的孩子必然要坐下来帮着母亲干。","language":"中文","translation":false},{"id":"capital-14-245","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":245,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"手织花边业主要分布在英格兰的两个农业区域。一个是洪尼顿花边业区，包括戴文郡南海岸20哩至30哩宽的地带和北戴文的少数地方；另一区域包括白金汉、培德福德、北安普顿等郡的大部分，以及牛津郡和杭廷登郡的邻近地区。农业短工住的小屋通常就是工场。有些手工工场老板雇有3000多个这样的家庭工人，主要是儿童和少年，全部是女性。在花边整理那里见到的情况又重新出现了。只不过“老板娘家”被贫穷妇女用自己小屋开办的所谓“花边学校”代替了。这些学校里的儿童从5岁起(有时还要小)劳动到12岁或者15岁。年龄最小的儿童在第一年每天劳动4至8小时，稍大一些就从早晨6点劳动到晚上8点或10点。","language":"中文","translation":false},{"id":"capital-14-246","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":246,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“工房通常是小屋的普通卧室，为了挡风，烟囱也堵死了，住在里面的人甚至在冬天也往往只能靠自己的体温来暖和自己。有的地方，这些所谓教室象个小贮藏室，连安装火炉的地方都没有…… 这些破旧的小屋异常拥挤，空气坏极了。此外，臭水沟、厕所、腐烂物以及经常堆在小屋四周的垃圾也产生着有害的影响。”","language":"中文","translation":false},{"id":"capital-14-247","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":247,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“在一所花边学校里，有18个女孩和一个老板娘，每人占有33立方呎的空间；在另一所臭气熏天的学校里，有18个人，每人占有24 1/2立方呎。在这个行业中，竟雇用2岁到2岁半的儿童干活。”","language":"中文","translation":false},{"id":"capital-14-248","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":248,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在白金汉和培德福德这两个农业郡中不从事手织花边业的地方，草辫业就兴起了。这种行业扩展到哈特福郡的大部分地区和艾塞克斯郡的西部和北部。1861年，从事草辫业和草帽业的共有48043人，其中有各种年龄的男子3815人，其余都是妇女，20岁以下的有14913人，其中儿童近7000人。在这里，“草辫学校”代替了花边学校。孩子们通常从4岁起，有时在3岁到4岁之间，就开始在这里学编草辫。他们当然受不到任何教育。孩子们自己都把初级小学称为“自然的学校”，来和这种吸血的场所相区别。他们到这种地方来劳动，只是为了完成他们的挨饿的母亲指定他们完成的活，即每天大多要完成30码。下工后，母亲往往还要孩子在家里再劳动到夜里10、11以至12点。他们不断用唾液把麦秆润湿，因此常常割破手指和嘴唇。根据巴拉德医生所综合的伦敦卫生视察员们的共同意见，在卧室或工房中，每个人至少应占有300立方呎的空间。但是，草辫学校里的空间比花边学校还要小，每个人只有12 2/3立方呎、17立方呎、18 1/2立方呎，最多也不到22立方呎。调查委员怀特说：","language":"中文","translation":false},{"id":"capital-14-249","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":249,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“这些数字中的最小的数字，比一个装在每边各3呎的箱子里的儿童所占的空间还要小一半。”","language":"中文","translation":false},{"id":"capital-14-250","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":250,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这就是孩子们在12岁或14岁以前的生活享受。贫困堕落的双亲只想从孩子身上榨取尽可能多的东西。孩子们长大以后，自然也就对他们的双亲漠不关心并弃之不管了。","language":"中文","translation":false},{"id":"capital-14-251","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":251,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“难怪在这样教养起来的人口中流行着无知和放荡的现象…… 他们的道德极度败坏…… 许多妇女都有私生子，而且其中很多人还未到成熟年龄就有了，这种情况使那些熟悉刑事案件统计材料的人也不免大吃一惊。”","language":"中文","translation":false},{"id":"capital-14-252","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":252,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"但是，堪称基督教权威人士的蒙塔郎贝尔伯爵竟然声称，这些模范家庭的祖国是什么欧洲的基督教模范国家！","language":"中文","translation":false},{"id":"capital-14-253","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":253,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在上述两个工业部门中，工资一般都低得可怜(在草辫学校，儿童的最高工资在例外的情况下可以达到3先令)，而由于实行实物工资制(这种制度在花边业区特别盛行)，工资比它的名义数额就更低了。","language":"中文","translation":false},{"id":"capital-14-254","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":254,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"(e)现代工场手工业和家庭劳动向大工业的过渡。","language":"中文","translation":false},{"id":"capital-14-255","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":255,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这一革命由于工厂法在这两种生产方式中的实行而加速","language":"中文","translation":false},{"id":"capital-14-256","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":256,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"单靠滥用妇女劳动力和未成年劳动力，单靠掠夺一切正常的劳动条件和生活条件，单靠残酷的过度劳动和夜间劳动来实现的劳动力的便宜化，终究会遇到某些不可逾越的自然界限，而以此为基础的商品的便宜化和整个资本主义的剥削，随着也会发生这种情形。当这一点终于达到时(这需要很长的时间)，采用机器和把分散的家庭劳动(还有工场手工业)迅速转变为工厂生产的时刻就来到了。","language":"中文","translation":false},{"id":"capital-14-257","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":257,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“服饰”的生产为这一运动提供了最明显的例证。根据童工调查委员会的分类，这一工业部门包括草帽和女帽业，便帽业，裁缝业，妇女头饰业和女时装业，衬衫业和缝纫业，胸衣业，手套业和制鞋业，以及其他许多较小的行业，如领带和硬领业等等。1861年，在英格兰和威尔士的这些工业部门中雇用的女工总计有586298人，其中20岁以下的至少有115242人，15岁以下的有16560人。在联合王国(1861年)，这类女工共有750334人。同一时期，英格兰和威尔士的制帽业、制鞋业、手套业及裁缝业雇用的男工有437969人，其中15岁以下的有14964人，15岁至20岁的有89285人，20岁以上的有333117人。属于这一领域的许多比较小的部门还没有统计在内。但是我们就现有的数字来看，单在英格兰和威尔士，根据1861年的调查，从事这种生产的人就有1024267人，也就是说，几乎与农业和畜牧业吸收的人数相等。我们现在才开始明白，机器生产出来的这样惊人的大量产品和“游离”出来的这样惊人的大量工人究竟到哪里去了。","language":"中文","translation":false},{"id":"capital-14-258","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":258,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"从事“服饰”生产的有手工工场，它只是把具有现成的分散的肢体的分工在手工工场内部再生产出来；还有较小的手工业师傅，不过他们已不再象从前那样为个别消费者劳动，而是为手工工场和商店劳动，这样一来，往往整个城市和整个地区都专门从事某种行业，象制鞋业等等；最后，有所谓的家庭工人，他们生产大部分产品，成了手工工场、商店、甚至较小的手工业师傅的分支机构。大量的劳动材料、原料、半成品等由大工业供给，大量的廉价的任人摆布的人身材料则由大工业和大农业“游离”出来的人组成。这一领域中的手工工场所以会产生，主要是由于资本家需要在自己手里拥有一支能适应需求的每一变动的后备军。但这些手工工场又允许分散的手工业生产和家庭生产作为自己的广阔基础与自己一起并存下去。在这些劳动部门中，所以能大量地生产剩余价值，同时能使产品越来越便宜，这在过去和现在都主要是由于工资被降到仅够糊口的最低限度，而劳动时间却延长到人能忍受的最高限度。正是由于转化为商品的人的血和汗日益便宜，销售市场曾不断地扩大并且仍在一天天扩大，而对英国来说，盛行英国习俗和爱好的殖民地市场尤其是如此。最后，转折点来到了。旧方法的基础是单纯对工人材料进行残酷的剥削，同时多少采用一些系统发展起来的分工。这种基础已经不再能适应日益发展的市场和更加迅速地发展着的资本家之间的竞争了。采用机器的时刻来到了。同等地占领这一生产领域所有部门(如女时装业，裁缝业，制鞋业，缝纫业，制帽业等)的具有决定性革命意义的机器，是缝纫机。","language":"中文","translation":false},{"id":"capital-14-259","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":259,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"缝纫机对工人的直接影响，同所有在大工业时期征服新生产部门的机器的影响大体相似。年龄最小的儿童被排挤了。同家庭工人(其中很多人都是“穷人中的最穷者”)相比，机器工人的工资提高了。处境较好的手工业者的工资由于机器的竞争而降低了。新的机器工人完全是少女和年轻妇女。她们靠机械的力量消灭了男工在较重的劳动中的独霸地位，并且把大批老年妇女和未成熟儿童从较轻的劳动中赶走。这种强有力的竞争扼杀了最弱的手工劳动者。最近十年来伦敦因饥饿而死亡的人数的惊人增长，同机器缝纫业的扩大是齐头并进的。使用缝纫机的新的女工，按照机器的轻重、大小及其性能，坐着或者站着，用手和脚或者单用手推动机器，她们要支出大量的劳动力。她们的劳动由于拖得很长(虽然大多比在旧制度下要短些)危害着她们的健康。在制鞋业、胸衣业和制帽业等行业中，本来已经很小很挤的工场，现在再塞进缝纫机，对健康就更加有害了。调查委员洛德说：","language":"中文","translation":false},{"id":"capital-14-260","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":260,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“一走进有30到40个机器工人挤在一起干活的低矮的劳动场所，就感到受不了…… 温度(一部分是由烧熨斗的煤气炉发出的)高得可怕…… 在这些劳动场所尽管通行的是所谓适度的劳动时间，即从上午8点至下午6点，但每天照例还是有3个或者4个人晕倒。”","language":"中文","translation":false},{"id":"capital-14-261","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":261,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"社会生产方式的变革，生产资料改革的这一必然产物，是在各种错综复杂的过渡形式中完成的。这些过渡形式的变化，取决于缝纫机占领这一或那一工业部门的范围的大小和时间的长短，取决于工人当时的状况，取决于工场手工业生产、手工业生产或家庭生产三者谁占优势，取决于劳动场所的租金，等等。例如，在劳动(主要通过简单协作)多半已经组织起来的女时装业中，缝纫机最初只是工场手工业生产的一个新因素。在裁缝业、衬衫业和制鞋业等行业中，种种形式交织在一起了。有的地方是真正的工厂生产；有的地方是中间人从资本家头儿那里取得原料，在“小屋”或“阁楼”里把10—50或者更多的雇佣工人聚集在缝纫机周围；最后，有的地方则象机器尚未形成有组织的体系而只能小范围使用时会发生的情形那样，是手工业者或家庭工人同自己的家人或少数外面雇来的工人一起，使用属于他们自己的缝纫机。在英国，现在盛行的实际上是这样一种制度：资本家在自己的厂房里集中大量的机器，然后把机器产品分给家庭工人大军去进一步加工。但是，过渡形式的错综复杂并不能掩盖向真正的工厂生产转变的趋势。助长这种趋势的，首先是缝纫机本身的性能，它的多种多样的用途促使以前分散的生产部门在同一个厂房里和在同一个资本的指挥下联合起来；其次是，初步的缝纫工作以及其他一些操作最适合在机器所在的地方进行；最后是，那些用自己的机器进行生产的手工业者和家庭工人不可避免地遭到剥夺。现在，这种命运已经部分地落在他们身上了。投在缝纫机上的资本量的不断增加，刺激了生产，并造成了市场停滞，从而迫使家庭工人出卖自己的缝纫机。缝纫机本身的生产过剩又迫使急于打开销路的缝纫机生产者按周出租缝纫机，这就造成了把小的机器所有者置于死地的竞争局面。机器结构的不断变化和机器的日益便宜，使旧机器也不断地贬值，以致只有那些以极低的价格大批收买这种机器的大资本家，才能从使用机器中获利。最后，用蒸汽机代替人，在这里也象在一切类似的变革过程中一样，具有决定性的意义。蒸汽力的运用最初遇到了一些纯粹技术上的障碍，例如机器发生震动，控制机器速度有困难，轻型机器损坏很快等等，但经验很快就教会了人们克服这些障碍。如果说，一方面许多工作机在比较大的手工工场中的集中促进了蒸汽力的应用，那末另一方面，蒸汽同人的肌肉的竞争则加速了工人和工作机在大工厂的集中。例如，英国生产服饰的庞大领域，正如大部分其他行业一样，现在正经历着从工场手工业、手工业、家庭劳动过渡到工厂生产的变革。但在这以前，所有这些形式已经在大工业的影响下完全变样、解体，变得畸形了，它们没有显示出工厂制度的积极发展因素，却老早就再现了工厂制度的一切可怕的方面，甚至有过之无不及。","language":"中文","translation":false},{"id":"capital-14-262","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":262,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这种自发进行的工业革命，由于工厂法在所有使用妇女、少年和儿童的工业部门的推行而被人为地加速了。强制规定工作日的长度、休息时间、上下工时间，实行儿童的换班制度，禁止使用一切未满一定年龄的儿童等等，一方面要求采用更多的机器，并用蒸汽代替肌肉充当动力。另一方面，为了从空间上夺回在时间上失去的东西，就要扩充共同使用的生产资料如炉子、厂房等等，一句话，要使生产资料在更大程度上集中起来，并与此相适应，使工人在更大程度上结集起来。每一种受工厂法威胁的工场手工业所一再狂热鼓吹的主要反对论据，实际上不外是：必须支出更大量的资本，才能在原有规模上继续进行生产。至于说工场手工业和家庭劳动之间的中间形式以及家庭劳动本身，那末，随着工作日和儿童劳动受到限制，它们也就日益失去立足之地。对廉价劳动力的无限制的剥削是它们竞争能力的唯一基础。","language":"中文","translation":false},{"id":"capital-14-263","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":263,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂生产的重要条件，就是生产结果具有正常的保证，也就是说，在一定的时间里生产出一定量的商品，或取得预期的有用效果，特别在工作日被规定以后更是如此。其次，被规定的工作日的法定休息时间，要求劳动能够突然地和周期地停顿下来，而不损害正处在生产过程中的制品。当然，纯机械性质的行业同那些要经历某种化学和物理过程的行业(如陶器业、漂白业、染色业、面包业以及大部分金属加工业)相比，生产结果比较容易得到保证，劳动的中断也比较容易做到。只要不受限制的工作日、夜工以及对人力的肆意糟蹋照旧存在，每一种自然发生的障碍都会很快被看作生产上的永恒的“自然界限”。没有一种毒药消灭害虫能比工厂法消灭这类“自然界限”更有把握。没有任何人比陶器业的先生们叫喊“不可能”叫得更响亮的了。1864年，工厂法强制施行到他们身上，过了16个月以后，一切不可能都消失了。工厂法所引起的","language":"中文","translation":false},{"id":"capital-14-264","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":264,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“用压缩代替蒸发制造陶土的改良方法，烘土坯的炉子的新结构等等，都是制陶技术上极其重要的事件，它们标志着上一世纪无法比拟的制陶技术上的进步…… 炉温大大降低了，而煤的消耗大大减少了，土坯烧得更快了”。","language":"中文","translation":false},{"id":"capital-14-265","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":265,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"同各种预言相反，提高的并不是陶制品的成本价格，而是产量，结果从1864年12月到1865年12月的12个月中，陶制品出口的价值比前三年的平均出口价值超过了138628镑。在火柴业里，少年们甚至在吃中饭时也得用火柴棍去浸蘸发热的磷混合溶液，这种溶液的有毒的气体直扑到他们脸上，这种情况过去被认为是自然规律。工厂法(1864年)的实施使工厂不得不节省时间，结果促使一种浸蘸机问世，这种机器发出的气体不会扑到工人身上。目前还没有受到工厂法约束的那些花边工场手工业部门还坚持认为，由于各种花边材料烘干时间长短不同，从3分钟到1小时或1小时以上不等，所以吃饭时间不能固定。对于这种说法，童工调查委员会委员回答说： “这里的情况和壁纸业的情况一样。这个部门的某些主要工厂主曾激烈地争辩说，由于所使用的材料的性质和这些材料要经过的各道工序的差异，突然停下劳动去吃饭，就会造成重大的损失……按照《工厂法扩充条例》<1864>年第6节第6条的规定，自该法公布之日起给予他们18个月的期限，期满后，他们就必须遵行工厂法所规定的休息时间”。","language":"中文","translation":false},{"id":"capital-14-266","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":266,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"议会刚批准这个法律，工厂主先生们就已经发现：","language":"中文","translation":false},{"id":"capital-14-267","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":267,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“他们原来预料实行工厂法后会产生的种种弊端并没有出现。我们没有发现生产有任何瘫痪现象，实际上，我们在同一时间内生产得更多了”。","language":"中文","translation":false},{"id":"capital-14-268","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":268,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"我们看到，英国议会(肯定不会有人责备它的独创性)根据经验已经认识到，仅仅一项强制性的法律，就可以消除一切有碍于限制和规定工作日的所谓生产上的自然障碍。因此，当一个工业部门实行工厂法时，总要给予6到18个月的时间，在这段时期内，工厂主的事情就是扫除技术上的障碍。米拉波的格言“不可能？永远别对我说这种蠢话！”，特别适用于现代工艺学。但是，如果说工厂法就这样象在温室里那样使工场手工业生产转化为工厂生产所必要的物质要素成熟起来，那末，它又由于使扩大资本支出成为必要而加速了小师傅的破产和资本的积聚。","language":"中文","translation":false},{"id":"capital-14-269","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":269,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"撇开纯技术上的和技术上可以排除的障碍不说，对工作日的规定还遇到工人本身的不规则的生活习惯的障碍，这特别是发生在这样的地方，那里盛行计件工资，在一天或一星期中所旷费的时间可以由以后的过度劳动或做夜工来补偿，这种方法使成年工人变得野蛮，使他们的未成年的和女性的伙伴遭到毁灭。劳动力耗费方面的这种毫无规则的情形，虽然是对单调乏味的苦役的一种自发的粗暴反应，但在极大程度上是由生产本身的无政府状态引起的，而这种无政府状态又是以资本对劳动力的不受限制的剥削为前提的。除了工业周期的一般的周期变动和每个生产部门的特殊的市场波动外，还出现一种因航海季节的周期性或因赶时髦而形成的所谓旺季，此外，还会突然出现必须在最短期限内完成大批定货的情况。这种短期定货的习惯随着铁路和电报的发展越来越变得经常了。例如，伦敦的一个工厂主说：","language":"中文","translation":false},{"id":"capital-14-270","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":270,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“铁路系统扩展到全国各地，大大地助长了短期定货的习惯；买主现在从格拉斯哥、曼彻斯特和爱丁堡每隔14天来一次，或者是到我们供货的西蒂大商行成批购货。他们不再象往常那样从货栈里购买，而是发出必须立即交货的定单。前几年，我们总是可以在淡季预先准备好下一季的需要，而现在谁也不能预言将会需要什么。”","language":"中文","translation":false},{"id":"capital-14-271","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":271,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在那些尚未受工厂法约束的工厂和手工工场里，在所谓旺季，由于突如其来的定货，周期性地盛行着骇人听闻的过度劳动。在工厂、手工工场和商店的那些分支机构里，即在本来就极不规则的家庭劳动领域里，原料和定货完全取决于资本家的情绪，在这里，资本家根本不用去考虑厂房、机器等的利用问题，而只是拿工人的生命去冒险。在这个领域里，正系统地培育着一支随时可供支配的产业后备军，这支后备军在一年的一部分时间里由于被迫从事非人的劳动而遭到摧残，在另一部分时间里则由于没有工作而穷困堕落。童工调查委员会的报告说：","language":"中文","translation":false},{"id":"capital-14-272","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":272,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“雇主们利用家庭劳动习以为常的不规则性，在要完成紧急的活时，迫使家庭劳动延长到夜间11点、12点、2点，事实上，就象通常所说的，延长到随便什么时间”，而劳动场所又是“臭气熏天，简直会使你晕倒。你可能走到门口，把门打开，但不敢往里走”。","language":"中文","translation":false},{"id":"capital-14-273","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":273,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"有一个被询问的证人鞋匠说：","language":"中文","translation":false},{"id":"capital-14-274","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":274,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我们的雇主真古怪，他们相信，让一个少年在这半年累得要死，在另外半年又几乎被迫到处闲逛，这对少年似乎没有什么害处。”","language":"中文","translation":false},{"id":"capital-14-275","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":275,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这些所谓“商业习惯”，同技术上的障碍一样，过去和现在都被有利害关系的资本家硬说成是生产上的“自然界限”，这也是棉纺织业巨头们在最初受到工厂法威胁时最喜欢叫喊的口号。虽然他们的工业比任何其他工业更依赖于世界市场，从而也更依赖于航海业，但是经验已经揭露了他们的谎言。从此以后，任何一种所谓的“商业障碍”都被英国的工厂视察员看成是一种无聊的借口了。事实上，童工调查委员会的极其认真的调查证明：在某些工业中，规定工作日只不过是把已经使用的劳动量较均衡地分配在全年；这种规定，对于那种害死人的、毫无意义的、本身同大工业制度不相适应的赶时髦的风气，是第一个合理的约束；远洋航行和一般交通工具的发展已经打破了季节性劳动的固有的技术基础；一切其他所谓不能控制的条件，也由于厂房的扩大、机器的增加、同时使用的工人人数的增长以及所有这些变化对批发商业制度自然产生的反作用而被消除了。但是，正象资本通过自己代表的嘴屡次宣布的那样，要资本同意这种变革，“只有在议会的一项普遍法令的压力下”，即用法律强制规定工作日的情况下，才能办到。","language":"中文","translation":false},{"id":"capital-14-276","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":276,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"9、工厂法(卫生条款和教育条款)。它在英国的普遍实行","language":"中文","translation":false},{"id":"capital-14-277","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":277,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂法的制定，是社会对其生产过程自发形式的第一次有意识、有计划的反作用。正如我们讲过的，它象棉纱、走锭精纺机和电报一样，是大工业的必然产物。在谈到工厂法在英国普遍实行之前，我们还要简单地提一提英国工厂法中与工作日的小时数无关的某些条款。","language":"中文","translation":false},{"id":"capital-14-278","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":278,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"撇开卫生条款中使资本家容易规避的措辞不说，它的内容也是非常贫乏的，实际上只是就粉刷墙壁和其他几项清洁措施，通风和危险机器的防护等做出一些规定。我们在第三卷里还会谈到，工厂主曾怎样进行疯狂的斗争，反对这些要求他们拿出少量的钱来保护他们“人手”的四肢的条款。在这里，再一次光辉地证实了自由贸易论者的信条：在一个存在着对抗利益的社会里，人人追逐私利，就会促进公共福利。举一个例子就够了。大家知道，在过去二十年间，爱尔兰的亚麻工业以及随之兴起的打麻工厂，都得到了很大的发展。1864年那里的打麻工厂已有约1800个。每到秋冬两季，一些完全不熟悉机器的人，主要是少年和妇女，即附近小租地农民的妻子儿女，便定期地放下地里的活，到打麻工厂从事往辗压机里装填亚麻的劳动。这里的事故，按其数量和程度来说是机器史上根本没有先例的。只在基尔迪南(在科克附近)的一家打麻工厂里，从1852年至1856年就一共发生6起造成死亡和60起造成严重残废的事故，而所有这些事故本来只要花几先令，安上一些最简单的装置就可以防止。达翁帕特里克各工厂的合格医生冯·怀特，在1865年12月16日的官方报告中说道：","language":"中文","translation":false},{"id":"capital-14-279","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":279,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“打麻工厂里的事故可怕到了极点。大多都是身体被铡掉四分之一。受伤者的通常结局，不是死亡就是变成残废，痛苦终身。国内工厂数量的增多当然会扩大这种可怕的结果。我相信，通过国家对打麻工厂的适当监督，可以避免身体和生命的大量牺牲。”","language":"中文","translation":false},{"id":"capital-14-280","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":280,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"为了迫使资本主义生产方式建立最起码的卫生保健设施，也必须由国家颁布强制性的法律。还有什么比这一点更能清楚地说明资本主义生产方式的特点呢？","language":"中文","translation":false},{"id":"capital-14-281","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":281,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“1864年的工厂法使陶器业的200多个工场进行了粉刷和清扫，这些工场已经有二十年或者根本就节制了这一类的工作。<这就是资本的“节欲”！>这些作坊里雇有27878个工人，他们直到今天还在过度的日间劳动甚至往往在过度的夜间劳动中，呼吸着极端有害的空气。这种空气使得这种在其他方面危害较少的职业也成为疾病和死亡的温床。工厂法使通风设备大大增加了。”","language":"中文","translation":false},{"id":"capital-14-282","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":282,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"同时，工厂法的这个部分清楚地表明，资本主义生产方式按其本质来说，只要超过一定的限度就拒绝任何合理的改良。我们一再指出，英国的医生曾异口同声地宣布，每人起码要有500立方呎的空间才能持续地工作。好了！既然工厂法通过它的各种强制性规定间接地加速了较小的工场向工厂的转化，从而间接地侵害了较小的资本家的所有权，并确保了大资本家的垄断权，那末，法律关于工场中的每个工人应占有必要空间的强制规定，就会一下子直接剥夺成千上万的小资本家！就会动摇资本主义生产方式的根基，也就是说，会破坏大小资本通过劳动力的“自由”购买和消费而实现自行增殖。因此，工厂法在500立方呎的空间面前碰壁了。卫生机关、工业调查委员会、工厂视察员，都一再强调500立方呎的必要性，又一再述说不可能强迫资本接受这一点。这样，他们实际上就是宣布，工人的肺结核和其他肺部疾病是资本生存的条件。","language":"中文","translation":false},{"id":"capital-14-283","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":283,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"尽管工厂法的教育条款整个说来是不足道的，但还是把初等教育宣布为劳动的强制性条件。这一条款的成就第一次证明了智育和体育同体力劳动相结合的可能性，从而也证明了体力劳动同智育和体育相结合的可能性。工厂视察员从教师的证词中就发现：虽然工厂儿童上课的时间要比正规的日校学生少一半，但学到的东西一样多，而且往往更多。 “道理很简单。他们只是半天在学校里，所以总是精力充沛，几乎随时都适于并愿意学功课。半工半读的制度使得两种活动互为休息和调剂，因此，对儿童来说，这种制度比不间断地从事其中一种活动要合适得多。一个从清晨就坐在学校里的儿童，特别在暑天，不可能同一个从劳动中来的活泼愉快的儿童相比。”","language":"中文","translation":false},{"id":"capital-14-284","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":284,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"关于这一点，从西尼耳于1863年在爱丁堡举行的社会学家大会的演说中也可以找到进一步的例证。他在这篇演说中还指出，上层阶级和中层阶级的孩子们的片面的、不生产的和漫长的学习日，只是白白地增加教师的劳动，“同时，不仅无益地并且是绝对有害地浪费着儿童的时间、健康和精力”。正如我们在罗伯特·欧文那里可以详细看到的那样，从工厂制度中萌发出了未来教育的幼芽，未来教育对所有已满一定年龄的儿童来说，就是生产劳动同智育和体育相结合，它不仅是提高社会生产的一种方法，而且是造就全面发展的人的唯一方法。","language":"中文","translation":false},{"id":"capital-14-285","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":285,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"我们已经看到，大工业从技术上消灭了那种使整个人终生固定从事某种局部操作的工场手工业分工。但大工业的资本主义形式同时又更可怕地再生产了这种分工：在真正的工厂中，是由于把工人变成局部机器的有自我意识的附件；在其他各处，一部分是由于间或地使用机器和机器劳动，一部分是由于采用妇女劳动、儿童劳动和非熟练劳动作为分工的新基础。工场手工业分工和大工业性质之间的矛盾强烈地表现出来。例如它表现在这样一个可怕的事实上：现代工厂和手工工场雇用的大部分儿童从最年幼的时期起就被束缚在最简单的操作上，多年遭受着剥削，却没有学会任何一种哪怕以后只是在同一手工工场或工厂中能用得上的手艺。例如，过去在英国的印刷业中，同旧的工场手工业和手工业制度相适应，学徒工是从比较简单的活过渡到比较复杂的活。他们经过一段学习时期，最终会成为熟练的印刷工人。凡从事这门手工业的人，都必须能读会写。随着印刷机的出现，一切都变了。印刷机使用两种工人：一种是成年工人，他们看管机器；另一种是少年，大多从11岁到17岁，他们的工作只是把纸铺开送到机器上，或者从机器上把印好的纸取下来。他们(特别是在伦敦)在一星期中有好几天要连续不断地从事这种苦工达14、15、16小时，甚至往往一连劳动36小时，而中间只有两小时吃饭和睡觉的休息时间！他们当中大部分人不识字，他们通常都是非常粗野的、反常的人。","language":"中文","translation":false},{"id":"capital-14-286","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":286,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“要使他们能胜任自己的工作，不需要任何知识教育；他们很少有机会接触技艺，更少有机会运用判断力；他们的工资虽然在少年中略高一些，但是不会随着他们的成长按比例增加，而且大多数人都没有任何希望被提升到收入较高和责任较大的机器看管工人的职位，因为每一台机器只需要一个看管工人，却往往需要4个少年。”","language":"中文","translation":false},{"id":"capital-14-287","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":287,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"当他们长大到不适于从事儿童劳动时，也就是最迟到17岁时，就被印刷厂解雇。他们成为罪犯的补充队。企图在别的地方为他们找到职业的某些尝试，也都由于他们的无知、粗野、体力衰退和精神堕落而遭到了失败。","language":"中文","translation":false},{"id":"capital-14-288","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":288,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"关于工场内部的工场手工业分工所谈到的这一切，也适用于社会内部的分工。只要手工业和工场手工业构成社会生产的普遍基础，生产者对专一生产部门的依附，他的职业的原有多面性的破坏，就成为发展的必要因素。在这一基础上，每一个特殊的生产部门都通过经验找到适合于自己的技术形式，慢慢地使它完善，而一旦达到一定的成熟程度，就迅速地使它固定下来。除商业提供的新的劳动材料外，劳动工具的逐渐改变也会不时地引起变化。一旦从经验中取得适合的形式，工具就固定不变了；工具往往世代相传达千年之久的事实，就证明了这一点。很能说明问题的是，各种特殊的手艺直到十八世纪还称为：mysteries〔秘诀〕，只有经验丰富的内行才能洞悉其中的奥妙。这层帷幕在人们面前掩盖起他们自己的社会生产过程，使各种自然形成的分门别类的生产部门彼此成为哑谜，甚至对每个部门的内行都成为哑谜。大工业撕碎了这层帷幕。大工业的原则是，首先不管人的手怎样，把每一个生产过程本身分解成各个构成要素，从而创立了工艺学这门完全现代的科学。社会生产过程的五光十色的、似无联系的和已经固定化的形态，分解成为自然科学的自觉按计划的和为取得预期有用效果而系统分类的应用。工艺学揭示了为数不多的重大的基本运动形式，不管所使用的工具多么复杂，人体的一切生产活动必然在这些形式中进行，正象力学不会由于机器异常复杂，就看不出它们不过是简单机械力的不断重复一样。现代工业从来不把某一生产过程的现存形式看成和当作最后的形式。因此，现代工业的技术基础是革命的，而所有以往的生产方式的技术基础本质上是保守的。现代工业通过机器、化学过程和其他方法，使工人的职能和劳动过程的社会结合不断地随着生产的技术基础发生变革。这样，它也同样不断地使社会内部的分工发生革命，不断地把大量资本和大批工人从一个生产部门投到另一个生产部门。因此，大工业的本性决定了劳动的变换、职能的更动和工人的全面流动性。另一方面，大工业在它的资本主义形式上再生产出旧的分工及其固定化的专业。我们已经看到，这个绝对的矛盾怎样破坏着工人生活的一切安宁、稳定和保障，使工人面临这样的威胁：在劳动资料被夺走的同时，生活资料也不断被夺走，在他的局部职能变成过剩的同时，他本身也变成过剩的东西；我们已经看到，这个矛盾怎样通过工人阶级的不断牺牲、劳动力的无限度的浪费以及社会无政府状态的洗劫而放纵地表现出来。这是消极的方面。但是，如果说劳动的变换现在只是作为不可克服的自然规律，并且带着自然规律在任何地方遇到障碍时都有的那种盲目破坏作用而为自己开辟道路，那末，大工业又通过它的灾难本身使下面这一点成为生死攸关的问题：承认劳动的变换，从而承认工人尽可能多方面的发展是社会生产的普遍规律，并且使各种关系适应于这个规律的正常实现。大工业还使下面这一点成为生死攸关的问题：用适应于不断变动的劳动需求而可以随意支配的人员，来代替那些适应于资本的不断变动的剥削需要而处于后备状态的、可供支配的、大量的贫穷工人人口；用那种把不同社会职能当作互相交替的活动方式的全面发展的个人，来代替只是承担一种社会局部职能的局部个人。工艺学校和农业学校是这种变革过程在大工业基础上自然发展起来的一个要素；职业学校是另一个要素，在这种学校里，工人的子女受到一些有关工艺和各种生产工具的实际操作的教育。如果说，工厂法作为从资本那里争取来的最初的微小让步，只是把初等教育同工厂劳动结合起来，那末毫无疑问，工人阶级在不可避免地夺取政权之后，将使理论的和实践的工艺教育在工人学校中占据应有的位置。同样毫无疑问，生产的资本主义形式和与之相适应的工人的经济关系，是同这种变革酵母及其目的——消灭旧分工——直接矛盾的。但是，一种历史生产形式的矛盾的发展，是这种形式瓦解和改造的唯一的历史道路。“鞋匠，管你自己的事吧！”——手工业智慧的这一“顶峰”，在钟表匠瓦特发明蒸汽机，理发师阿克莱发明经线织机，宝石工人富尔顿发明轮船以来，已成为一种可怕的愚蠢了。","language":"中文","translation":false},{"id":"capital-14-289","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":289,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"当工厂法规定工厂、工场手工业等的劳动时，这最初仅仅表现为对资本的剥削权利的干涉。相反地，对所谓家庭劳动的任何规定都立即表现为对父权(用现代语言来说是父母权力)的直接侵犯。温和的英国议会对于采取这一步骤长期来一直装腔作势，畏缩不前。但是事实的力量终于迫使人们承认，大工业在瓦解旧家庭制度的经济基础以及与之相适应的家庭劳动的同时，也瓦解了旧的家庭关系本身。不得不为儿童的权利来呼吁了。1866年童工调查委员会的最后报告说：","language":"中文","translation":false},{"id":"capital-14-290","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":290,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“不幸的是，所有的证词都表明：男女儿童在自己的父母面前比在任何别人面前都更需要保护。”对一般儿童劳动，特别是对家庭劳动进行无限度的剥削的制度“之所以能够维持，是由于父母对自己的年幼顺从的儿女滥用权力，任意虐待，而不受任何约束或监督…… 父母不应当享有为每周取得一点工资而把自己的孩子变成单纯机器的绝对权力…… 儿童和少年有权为防止父母权力的滥用而取得立法方面的保护，这种滥用会过早地毁坏他们的体力，并且使他们道德堕落，智力衰退”。","language":"中文","translation":false},{"id":"capital-14-291","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":291,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"然而，不是父母权力的滥用造成了资本对未成熟劳动力的直接或间接的剥削，相反，正是资本主义的剥削方式通过消灭与父母权力相适应的经济基础，造成了父母权力的滥用。不论旧家庭制度在资本主义制度内部的解体表现得多么可怕和可厌，但是由于大工业使妇女、男女少年和儿童在家庭范围以外，在社会地组织起来的生产过程中起着决定性的作用，它也就为家庭和两性关系的更高级的形式创造了新的经济基础。当然，把基督教日耳曼家庭形式看成绝对的东西，就象把古罗马家庭形式、古希腊家庭形式和东方家庭形式看成绝对的东西一样，都是荒谬的。这些形式依次构成一个历史的发展序列。同样很明白，由各种年龄的男女组成的结合工人这一事实，尽管在其自发的、野蛮的、资本主义的形式中，也就是在工人为生产过程而存在，不是生产过程为工人而存在的那种形式中，是造成毁灭和奴役的祸根，但在适当的条件下，必然会反过来变成人类发展的源泉。","language":"中文","translation":false},{"id":"capital-14-292","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":292,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂法从一个只在机器生产的最初产物即纺纱业和织布业中实行的法律，发展成为一切社会生产中普遍实行的法律，这种必然性，正如我们已经看到的，是从大工业的历史发展进程中产生的。在大工业的背景下，工场手工业、手工业和家庭劳动的传统形式经历着彻底的变革：工场手工业不断地转化为工厂；手工业不断地转化为工场手工业；最后，手工业和家庭劳动领域在相对说来短得惊人的时间内变成了苦难窟，骇人听闻的最疯狂的资本主义剥削在那里为所欲为。在这里最后起了决定作用的，有两方面的情况：第一，经验不断反复证明，如果资本只是在社会范围的个别点上受到国家的监督，它就会在其他点上更加无限度地把损失捞回来；第二，资本家自己叫喊着要求平等的竞争条件，即要求对劳动的剥削实行平等的限制。我们且听一听关于这方面的两种由衷的呼声吧。伍·库克斯利先生们(布利斯托尔的生产钉子、链条等的工厂主)，自愿在自己的企业里实行工厂条例。","language":"中文","translation":false},{"id":"capital-14-293","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":293,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“因为邻近各厂继续存在着旧的未经规定的制度，所以他们不得不遭受损失，眼看着他们的少年工人在下午6点钟以后被引诱到别的地方去继续做工。他们当然会说：‘这对于我们是一种不公平，并且是一种损失，因为这样会消耗少年工人的部分体力，而从少年取得的全部利益照理应该是属于我们的。’”","language":"中文","translation":false},{"id":"capital-14-294","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":294,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"辛普森先生(伦敦纸袋纸盒厂的工厂主)对童工调查委员会委员说：","language":"中文","translation":false},{"id":"capital-14-295","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":295,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“他愿意在任何一个要求实行工厂法的请愿书上签名。无论如何，他在晚上总是感到不安，工场一关门他就想，别的工场干的时间更长些，正在把生意从他的鼻子底下抢走。”","language":"中文","translation":false},{"id":"capital-14-296","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":296,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“只使较大的雇主的工厂遵守规定，而他们同行业的小工场在劳动时间上却不受任何法律限制，这对较大的雇主是不公平的。在劳动时间的限制上，把较小的工场看作例外，就造成不平等的竞争条件，这是一种不公平。除此以外，对较大的工厂主来说还有一种不利：他们的少年工和女工的供给会被引到不受工厂法约束的工场。最后，这会促使较小的工场增加，而这些较小的工场对国民的健康、福利、教育以及普遍的改善，几乎毫无例外都是最为不利的。”","language":"中文","translation":false},{"id":"capital-14-297","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":297,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"童工调查委员会在它的最终报告中，建议把140多万儿童、少年和妇女(其中几乎有一半人受小生产和家庭劳动的剥削)置于工厂法的约束之下。委员会说：","language":"中文","translation":false},{"id":"capital-14-298","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":298,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“如果议会全部接受我们的建议，那末毫无疑问，这样的立法不仅对同它直接有关的年幼和体弱的工人产生非常有益的影响，而且对直接<妇女>和间接<男子>地受立法约束的更大量的成年工人也会产生非常有益的影响。这种立法会迫使他们接受规则的和适度的劳动时间；它会节约和积蓄体力储备，而这同他们的个人幸福和国家幸福是息息相关的；它会保护正在发育的一代，使他们免于在幼年从事毁坏体质和引起早衰的过度紧张的劳动；最后，它还会为至少13岁以下的儿童提供接受初等教育的机会，从而结束那种难以置信的愚昧无知状态，这种状态在委员会的报告里曾得到如实的描写，使人看了不能不十分痛心，深感民族受到了侮辱。”","language":"中文","translation":false},{"id":"capital-14-299","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":299,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"托利党内阁在1867年2月5日通过国王演辞宣布，它已经把工业调查委员会的提案定为“法案”。做到这一步，竟需要在无价值的生物体上进行一个长达二十年的新试验。议会童工调查委员会早在1840年就已经成立了。该委员会1842年的报告，用纳·威·西尼耳的话来说， “对资本家和父母的贪婪、自私和残酷，对儿童和少年的困苦、堕落和遭受摧残，展示出一幅从未见过的极为可怕的图景…… 也许有人会说，报告描写的是过去时代的惨状。但遗憾的是，我们面前的一些报告说明，这种惨状仍然存在，同过去一样严重。两年前哈德威克出版的一本小册子写道，1842年受到指责的弊端，在今天<1863年>仍然非常泛滥…… 这份报告<1842年>二十年来竟无人过问，在这期间，当年的儿童已长大成人，他们对我们称为道德的东西，对学校教育、宗教和自然的家庭之爱毫无所知，但我们竟然又让这些儿童成了现在这一代孩子的父母”。","language":"中文","translation":false},{"id":"capital-14-300","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":300,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"在这期间，社会状况发生了变化。议会再也不敢象当年拒绝童工调查委员会1842年的要求那样，拒绝该委员会1863年的要求了。因此在1864年，当该委员会只公布了它的一部分报告时，瓦器业(包括陶器业)、壁纸、火柴、弹药和雷管制造业以及剪绒业，便都受到已在纺织业中实行的那些法律的约束。当时的托利党内阁通过1867年2月5日的国王演辞，公布了以童工调查委员会(这个委员会在1866年完成了它的工作)的最后议案为基础的新法案。","language":"中文","translation":false},{"id":"capital-14-301","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":301,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1867年8月15日和21日，工厂法扩充条例和工场管理条例先后获得国王批准。前者约束大企业，后者约束小企业。","language":"中文","translation":false},{"id":"capital-14-302","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":302,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工厂法扩充条例约束炼铁厂、铜铁工厂、铸造厂、机器制造厂、金属加工厂、古塔波树胶厂、造纸厂、玻璃厂、烟草厂，还有印刷业和装订业，以及所有在一年中至少有100天同时雇有50名以上工人的同类工业的工场。","language":"中文","translation":false},{"id":"capital-14-303","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":303,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"为了对这个法律的适用范围的扩大有一个概括的了解，我们在这里引用该法律规定的几个定义：","language":"中文","translation":false},{"id":"capital-14-304","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":304,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“手工业是指<在这项法律中>任何一种作为职业或者为了谋利而从事或者附带从事的手工劳动，它用于制造、改装、装饰、修理或最后加工某种待售的物品或这种物品的一部分。”","language":"中文","translation":false},{"id":"capital-14-305","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":305,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“工场是指有任何一个儿童、少年工人或妇女在其中从事某种‘手工业’，并且雇用这个儿童、少年或妇女的人有权进入并实行监督的一切有顶的或露天的房间或场所。”","language":"中文","translation":false},{"id":"capital-14-306","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":306,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“受雇是指在一个师傅或在符合下述详细规定的尊亲之一的手下从事一种‘手工业’，不管领工资或不领工资。”","language":"中文","translation":false},{"id":"capital-14-307","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":307,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“尊亲是指父、母、监护人、或其他负责监护或监督某一……儿童或少年工人的人。”","language":"中文","translation":false},{"id":"capital-14-308","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":308,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"第7条规定，凡违反该法律的规定而雇用儿童、少年工人和妇女者，得处以罚款，这一条不仅适用于工场主(不管是不是尊亲之一)，而且也适用于","language":"中文","translation":false},{"id":"capital-14-309","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":309,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“尊亲以及其他对儿童、少年工人或妇女有监护权或从他们的劳动中得到直接好处的人”。","language":"中文","translation":false},{"id":"capital-14-310","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":310,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"适用于大企业的工厂法扩充条例作了大量可耻的例外规定和对资本家的卑怯妥协，因此同工厂法比较起来，是后退了。","language":"中文","translation":false},{"id":"capital-14-311","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":311,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"工场管理条例的各项细节十分贫乏，它在被授权执行该法律的市政及地方当局手中仍然是一纸空文。1871年议会从这些当局手里收回该法的执行权，把它交给了工厂视察员，从而使工厂视察员的视察范围一举扩大了10万多个工场，单是砖厂就增加了300个，但对于本来就很缺乏的视察人员，只十分谨慎地增派了8名助手。","language":"中文","translation":false},{"id":"capital-14-312","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":312,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"因此，在1867年的这次英国立法中引人注意的地方是：一方面，统治阶级的议会不得不被迫在原则上采取非常的和广泛的措施，来防止资本主义剥削的过火现象；另一方面，议会在真正实现这些措施时又很不彻底、很不自愿、很少诚意。1862年的调查委员会还建议对采矿业实行一种新的规定；采矿业和其他各种工业不同的地方在于，在这里土地所有者和工业资本家的利益是一致的。过去，这两种利益的对立曾有利于工厂法的制订；现在，正是由于不存在这种对立，才足以说明矿业立法为什么会如此拖延和施展诡计。","language":"中文","translation":false},{"id":"capital-14-313","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":313,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1840年调查委员会揭露了骇人听闻、令人愤慨的事实，这在整个欧洲引起了极大的震动，以致议会为了拯救自己的良心，不得不通过了1842年的矿业法，这项法律仅限于禁止使用妇女和不满10岁的儿童从事井下劳动。","language":"中文","translation":false},{"id":"capital-14-314","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":314,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"以后，1860年，制订了矿山视察法，规定矿山要受专门任命的国家官员的检查，不许雇用10岁至12岁的儿童，除非他们持有学校的证明或者按一定的时数上学。由于任命的视察员少得可笑，职权又很小，加上其他一些下面将要详细叙述的原因，这项法令不过是一纸空文。","language":"中文","translation":false},{"id":"capital-14-315","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":315,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"关于矿山的最近的蓝皮书之一，是《矿山特别委员会的报告。附证词。1866年7月23日》。这是由下院议员组成的一个有全权传讯证人的委员会的作品，是厚厚的一册对开本，其中报告本身一共只有五行，内容是：委员会无话可说，还必须传讯更多的证人！","language":"中文","translation":false},{"id":"capital-14-316","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":316,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"讯问证人的方法使人想起英国法庭的反问法，就是律师乱七八糟地提出各种无耻的模棱两可的问题，弄得证人胡里胡涂，然后对他的话加以歪曲。在这里，律师也就是议会调查委员会的委员，其中有矿主和矿山经营者；证人是矿工，大部分是煤矿工人。这套滑稽戏最能说明资本的精神了，因此在这里不能不引述几段。为了便于考察起见，我把调查的结果分类叙述。要记住，问题和回答在英国蓝皮书中都编有号码，而这里所引用的都是煤矿工人的证词。","language":"中文","translation":false},{"id":"capital-14-317","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":317,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1、矿山中10岁以上童工的劳动。劳动，连同到矿山往返的路程，一般持续14至15小时，有时还要长，从早晨3、4、5点钟到傍晚4—5点钟。(第6、452、83号)成年工人分两班劳动，或者说劳动8小时，但是为了节省开支，儿童不换班。(第80、203、204号)年幼的儿童主要是雇来开关矿内各巷道的通风门，大一些的儿童则做较重的活，如运煤等等。(第122、739、740号)这种长时间的井下劳动一直要做到18岁或者22岁，然后才转入真正的挖煤劳动。(第161号)现在儿童和少年所受的折磨，比以往任何时期都更残酷。(第1663—1667号)矿工几乎一致要求议会制订一项法令禁止使用不满14岁的童工从事矿山劳动。于是，哈西·维维安(他自己就是一个矿山经营者)问道：","language":"中文","translation":false},{"id":"capital-14-318","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":318,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“这种要求难道不取决于父母的贫穷程度吗？”勃鲁斯先生问道：“如果父亲死了或者变成残废等等，那末夺去家庭的这个收入来源，难道不残忍吗？那就必须施行一项普遍的规章。你愿意在任何情况下都禁止不满14岁的儿童从事井下劳动吗？”回答：“在任何情况下都愿意。”(第107—110号)维维安：“如果矿山禁止使用不满14岁的童工，父母不会把孩子送到工厂等处去吗？——一般说，不会。”(第174号)工人：“开关通风门看起来很容易，但这是很苦的活。他们不仅老是挨风吹，而且关在那里完全象关在阴暗的牢房里一样。”资产者维维安：“孩子如果有灯，他不能在看门的时候读读书吗？——首先，他得自己买腊烛，再说，也不会允许他这样做。他在那里要注意自己的工作，他必须尽他的责任。我从来没见过有孩子在矿里念书。”(第139、141—160号)","language":"中文","translation":false},{"id":"capital-14-319","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":319,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"2、教育。矿工要求象工厂中那样，制定一项有关儿童强制教育的法律。他们认为，1860年法令中关于使用10—12岁儿童要有学校证明的条款纯粹是一种空想。资本主义审讯官的“寻根究底的”盘问在这里实在可笑极了。","language":"中文","translation":false},{"id":"capital-14-320","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":320,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“法令应当更多地约束谁呢，雇主还是父母？——对双方都约束。”(第115号)“不更多地约束其中的一方吗？——让我怎么回答呢？”(第116号)“雇主有没有表示某种愿望想使劳动时间规定得适合于上学呢？——从来没有。”(第137号)“矿工以后能改进自己的教养吗？——一般说来，他们越来越坏；染上了各种恶习；酗酒、赌钱等等，完全堕落了。”(第211号)“为什么不送孩子们进夜校呢？——多数煤矿区根本没有夜校。但主要的是，孩子们都让长时间的过度劳动累得精疲力尽，连眼睛也睁不开。”资产者最后断定说：“这样看，你是反对教育罗？——决不是，不过……”(第454号)“1860年的法令不是规定矿主等等在雇用10岁至12岁的儿童时要索取学校的证明么？——法律是这样规定的，但是矿主不照办。”(第443号)“你认为，法律的这项条款没有普遍实行吗？——根本就没有实行。”(第444号)“矿工对教育问题很关心吗？——绝大多数人都很关心。”(第717号)“他们都盼望实行这项法律吗？——绝大多数人都盼望。”(第718号)“为什么他们不迫使实行这项法律呢？——有许多工人希望拒绝没有学校证明的儿童做工，但是他会成为被记名的人。”(第720号)“谁给他记名呢？——他的雇主。”(第721号)“那你岂不是相信雇主会追究一个服从法律的人吗？——我相信雇主会这样做。”(第722号)“为什么工人不拒绝使用这样的儿童呢？——这可不由工人作主。”(第723号)“你要求议会干涉吗？——要在矿工的孩子们的教育上多少做出点有成效的事情，议会必须制定一项法令来强制实行。”(第1634号)“这种办法应适用于大不列颠全部工人的孩子呢，还是只适用于矿工的孩子？——我到这里来是代表矿工说话。”(第1636号)“为什么要把矿工的孩子和别的孩子分开？——因为他们是通常情况下的一个例外。”(第1638号)“在哪一方面？——生理方面。”(第1639号)“为什么教育对他们比对其他阶级的孩子更有价值呢？——我不是说教育对于他们更有价值，但是，由于他们在矿上从事过度劳动，就更少有机会上日校和星期日学校。”(第1640号)“这类问题可不能绝对地看，难道不是这样吗？”(第1644号)“矿区的学校够么？——不够。”(第1646号)“如果国家要求每一个孩子都入学，那末，从哪里来这么多的学校容纳所有的儿童上学呢？——我想，如果情况需要这么办，学校自然会办起来的。”(第1647号)“不只是绝大部分孩子，而且绝大部分成年矿工也都不会写不会读。”(第705、726号)","language":"中文","translation":false},{"id":"capital-14-321","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":321,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"3、妇女劳动。虽然从1842年以来已经不再在井下使用女工，但是她们仍被用来在井上装卸煤炭等物，把煤桶拉到运河边和火车旁，选煤等等。最近3—4年来使用的女工大有增加。(第1727号)这些女工大多数是矿工的妻子、女儿和寡妇，年龄从12岁至50、60岁不等。(第647、1779、1781号)","language":"中文","translation":false},{"id":"capital-14-322","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":322,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“矿工对矿上雇用妇女有什么想法呢？——他们普遍反对这种做法。”(第648号)“为什么？——他们认为这会使女性堕落(第649号)…… 妇女穿着男人的衣服。在许多场合下丧失了任何的羞耻心。有些妇女抽烟。劳动同井下一样脏。其中许多已婚的妇女不能尽自己的家庭职责。”(第650—654号、第701号)“寡妇能在其他地方找到同样收入(每周8—10先令)的职业吗？——我不能回答这个问题。”(第709号)“那末你仍然<铁石心肠！>下决心截断她们的这条谋生之路么？——毫无疑问。”(第710号)“哪儿来的这种情绪呢？——我们矿工非常尊敬女性，不忍看到她们在煤矿里受罪…… 这种活大部分是很繁重的。有许多姑娘一天要卸煤10吨之多。”(第1715、1717号)“你是否认为矿上雇用的女工比工厂雇用的女工更没有道德？——变坏的人的百分比大于工厂姑娘。”(第1732号)“但你不是对工厂里的道德状况也不满意么？——不满意。”(第1733号)“那末你也希望禁止工厂里使用妇女劳动吗？——不，我不希望。”(第1734号)“为什么不希望？——工厂劳动对于女性比较体面和适合。”(第1735号)“你不是认为这种劳动对她们的道德仍然是有害的吗？——不，远不象矿上的劳动那样有害。不过，我的意见不仅是出于道德方面的考虑，而且也出于生理和社会方面的考虑。姑娘们的社会堕落是令人痛心的，是极端严重的。当这些姑娘成为矿工的妻子以后，她们的丈夫就深受这种堕落之苦，这种情况使他们离开家跑去酗酒。”(第1736号)“但是铁工厂雇用的妇女不也是这样吗？——关于其他生产部门我不能说什么。”(第1737号)“但是铁工厂雇用的妇女和矿上雇用的妇女有什么不同呢？——我没有研究过这个问题。”(第1740号)“你能找出这两类人之间的区别吗？——我没有把握回答这个问题，不过我挨家挨户访问过，知道我们矿区里的一些丑事。”(第1741号)“你是不是很希望在所有会使妇女堕落的地方消灭妇女劳动呢？——是的……儿童的最好的感情应由母亲来培养。”(第1750号)“但是从事农业的妇女也是这样吗？——农活只有两季，而我们这里的妇女一年四季都要劳动，有时白天黑夜接着干，汗流浃背，使她们的体质变弱，健康受到损害。”(第1751号)“你没有全盘地研究过这个问题<即妇女劳动的问题>吗？——我观察了周围的情况，我敢说，我在任何地方都找不到和煤矿上的妇女劳动相似的工作。(第1753号)这是男人干的活，而且是身强力壮的男人干的活。”“较好的矿工想振奋起来并认真做人，但在妻子那里得不到支持，反而受她们的连累。”［第1793、1794、1808号］","language":"中文","translation":false},{"id":"capital-14-323","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":323,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"资产者又乱七八糟盘问了一通之后，终于暴露了他们对寡妇、贫苦家庭等等的“同情心”的秘密。","language":"中文","translation":false},{"id":"capital-14-324","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":324,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“煤矿主们派一些绅士去当总监工，而这些总监工为了博得主人嘉许，就实行尽可能节约地办一切事情的政策；雇用的姑娘每天得到1先令—1先令6便士，而男人却得到2先令6便士。”(第1816号)","language":"中文","translation":false},{"id":"capital-14-325","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":325,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“谈到你们区里的验尸陪审员的调查，那末，在发生事故时，工人对法院的审理是否满意？——不，他们不满意。”(第360号)“为什么不满意？——特别是因为当陪审员的那些人对矿山毫无所知。工人除了当证人以外，根本不让干别的。通常总是邀请邻近的小店主当陪审员，这些人受矿主即他们的顾客的影响，对证人的技术用语一窍不通。我们要求由矿工担任一部分陪审员。判决和证人的证词一般是矛盾的。”(第361—375号)“陪审员不是应当公正吗？——是的。”(第378号)“工人会成为这样的陪审员吗？——我看不出有任何原因会使工人不公正。他们了解真实情况。”(第379号)“但是他们会不会由于偏袒工人而作出不公正的苛刻的判决呢？——不，我相信不会。”(第380号)","language":"中文","translation":false},{"id":"capital-14-326","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":326,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"5、虚假的度量衡等等。工人要求以每周发一次工资的办法代替两周发一次工资的办法，要求按重量计算，不要按桶的容量计算，保证不使用假秤等等。","language":"中文","translation":false},{"id":"capital-14-327","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":327,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“如果桶被暗地加大，工人不是在提出声明后14天就可以离开矿井吗？——但是如果他到另外一个地方去，也会遇到同样的情况。”(第1071号)“但他不是仍然可以离开这种不公平的地方吗？——到处都是不公平的。”(第1072号)“但是工人不是在提出声明后14天又可以离开他所在的地方吗？——是的。”(第1073号)","language":"中文","translation":false},{"id":"capital-14-328","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":328,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"6、矿山视察。工人不仅遭受瓦斯爆炸事故带来的痛苦。","language":"中文","translation":false},{"id":"capital-14-329","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":329,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“我们也要对煤矿内通风不良提出控诉，这种情况使工人在矿内几乎无法呼吸，因此什么活也干不了。例如，正好现在在我干活的那个工作面上，恶劣的空气使许多工人病倒了好几个星期。在主要巷道里，空气一般还够用，然而正好在我们干活的地方就不够用了。如果有谁向视察员控诉通风情况，那他就会被解雇，并且成为一个‘被记名的’人，到别的地方也找不到工作。1860年的矿山视察法纯粹是一张废纸。视察员的人数太少了，他们也许要7年才能进行一次形式上的视察。我们的视察员是一个不能做任何事情的70多岁的老头，他要管130多个煤矿。我们除了需要有更多的视察员外，还需要有副视察员。”(第234号及以下各号)“这样是不是政府应当维持一支视察员队伍，让他们在没有工人报告的情况下自己就能够解决你们的全部要求？——这是不可能的，不过他们应该自己到矿井里来听取报告。”(第280号)“你是否相信这样做的结果就会把通风等责任<！>从矿主身上推到政府官员身上呢？——绝不会这样，他们的职责是要迫使人们遵守现行的法律。”(第285号)“你说的副视察员是不是指那些比现任视察员薪水少资历浅的人呢？——如果你们能够派比较好的，我绝不希望要资历比较浅的。”(第294号)“你们是要更多的视察员呢，还是要比视察员低一级的人呢？——我们需要那些能亲自到矿上来跑跑并且不顾私利的人。”(第295号)“如果你们要求派次一级视察员的愿望得到满足，那末他们在熟练程度上的缺陷不会造成危险吗？…… ——不会；政府的责任是委派适当的人员。”(第297号)","language":"中文","translation":false},{"id":"capital-14-330","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":330,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这种讯问法最终连调查委员会的主席也感到太荒唐了。他插进来说：","language":"中文","translation":false},{"id":"capital-14-331","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":331,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“你们是希望有实际经验的人员，能亲自到矿井看看并把情况报告给视察员，而视察员就可以运用他的较高级的知识。”(第531号)“所有这些旧矿井都搞通风设备，不是会造成很大的花费吗？——是的，费用可能会增加，但人们的生命将得到保障。”","language":"中文","translation":false},{"id":"capital-14-332","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":332,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"一个煤矿工人对1860年法令第17条表示抗议：","language":"中文","translation":false},{"id":"capital-14-333","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":333,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“现在，如果矿山视察员发现矿井的某一部分不适于工作，他必须向矿主和内务大臣报告。然后矿主有20天的考虑时间；20天期满后，矿主可以拒绝任何改进。但是矿主要是这样做，他就必须给内务大臣打一个报告，并向他推荐5名矿山工程师，由内务大臣从中挑选仲裁人。我们认为，在这种情况下，矿主实际上是委派自己的仲裁人。”(第581号)","language":"中文","translation":false},{"id":"capital-14-334","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":334,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"资产者讯问人(他自己就是矿主)说：","language":"中文","translation":false},{"id":"capital-14-335","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":335,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“这纯粹是一种思辩的异议。”(第586号)“这样说来，你们对矿山工程师的正直评价很低了？——我是说，这种做法非常不合理、不公平。”(第588号)“难道矿山工程师不具备某种公正的品格，从而可以使他们的决定避免你们所担心的那种偏袒吗？——我拒绝回答有关这些人的个人品格的问题。我相信，在许多情况下，他们做事很不公正，在这种人命关天的地方，应当剥夺他们的这种权力。”(第589号)","language":"中文","translation":false},{"id":"capital-14-336","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":336,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"这个资产者又厚颜无耻地问：","language":"中文","translation":false},{"id":"capital-14-337","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":337,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“你不认为矿主也会因瓦斯爆炸而遭到损失吗？”","language":"中文","translation":false},{"id":"capital-14-338","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":338,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"“你们工人不请求政府的帮助不能自己维护你们自己的利益吗？——不能。 ”(第1042号)","language":"中文","translation":false},{"id":"capital-14-339","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":339,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1865年在大不列颠有3217个煤矿和12个视察员。约克郡的一个矿主(1867年1月26日《泰晤士报》报道)自己曾计算过，撇开视察员的纯事务性的工作(而这就占了他们的全部时间)不说，每个矿山每10年才能被视察一次。无怪近几年来(特别是1866年和1867年)惨祸发生的次数和规模越来越大(有时一次竟牺牲200—300名工人)。这就是“自由”资本主义生产的美妙之处！","language":"中文","translation":false},{"id":"capital-14-340","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":340,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1872年的法令尽管有很大缺陷，但它无论如何是对矿山雇用的儿童的劳动时间作出规定，并在一定程度上使矿山经营者和采矿业主要对所谓的事故负责的第一个法令。","language":"中文","translation":false},{"id":"capital-14-341","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":341,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"1867年调查农业中儿童、少年、妇女劳动情况的皇家委员会公布了几个很重要的报告。为了把工厂立法的原则在形式上加以改变而应用到农业方面去，曾有过各种尝试，但直到今天都完全失败了。可是我在这里必须提醒注意的一点是：普遍应用这些原则的不可抗拒的趋势已经存在。","language":"中文","translation":false},{"id":"capital-14-342","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":342,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"如果说，作为工人阶级的身体和精神的保护手段的工厂立法的普遍化已经不可避免，那末，另一方面，正如前面讲到的，这种普遍化使小规模的分散的劳动过程向大的社会规模的结合的劳动过程的过渡也普遍化和加速起来，从而使资本的积聚和工厂制度的独占统治也普遍化和加速起来。它破坏一切还部分地掩盖着资本统治的陈旧的过渡的形式，而代之以直接的无掩饰的资本统治。这样，它也就使反对这种统治的直接斗争普遍化。它迫使单个的工场实行划一性、规则性、秩序和节约，同时，它又通过对工作日的限制和规定，造成对技术的巨大刺激，从而加重整个资本主义生产的无政府状态和灾难，提高劳动强度并扩大机器与工人的竞争。它在消灭小生产和家庭劳动的领域的同时，也消灭了“过剩人口”的最后避难所，从而消灭了整个社会机构的迄今为止的安全阀。它在使生产过程的物质条件及其社会结合成熟的同时，也使生产过程的资本主义形式的矛盾和对抗成熟起来，因此也同时使新社会的形成要素和旧社会的变革要素成熟起来。","language":"中文","translation":false},{"id":"capital-14-343","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":343,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"大工业在农业以及农业生产当事人的社会关系上引起的革命，要留到以后才能说明。在这里，我们先简短地提一下某些结果就够了。如果说机器在农业中的使用大多避免了机器使工厂工人遭到的那种身体上的损害，那末机器在农业中的使用在造成工人“过剩”方面却发生了更为强烈的作用，而且没有遇到什么抵抗，这一点我们在以后将会详细谈到。例如，在剑桥郡和萨福克郡，最近二十年来耕地面积大大扩大了，但是在这一时期农村人口不但相对地减少了，而且绝对地减少了。在北美合众国，农业机器目前只是潜在地代替工人，也就是说，它使生产者有可能耕种更大的面积，但是并没有在实际上驱逐在业工人。1861年，英格兰和威尔士参加农业机器制造的人数总计有1034人，而在蒸汽机和工作机上干活的农业工人总共只有1205人。","language":"中文","translation":false},{"id":"capital-14-344","author":"马克思","title":"资本论·第一卷","location":"第十三章 机器和大工业","page":14,"paragraph":344,"url":"https://www.marxists.org/chinese/marx/capital/13.htm","text":"大工业在农业领域内所起的最革命的作用，是消灭旧社会的堡垒——“农民”，并代之以雇佣工人。因此，农村中社会变革的需要和社会对立，就和城市相同了。最陈旧和最不合理的经营，被科学在工艺上的自觉应用代替了。农业和工场手工业的原始的家庭纽带，也就是把二者的早期未发展的形式联结在一起的那种纽带，被资本主义生产方式撕断了。但资本主义生产方式同时为一种新的更高级的综合，即农业和工业在它们对立发展的形式的基础上的联合，创造了物质前提。资本主义生产使它汇集在各大中心的城市人口越来越占优势，这样一来，它一方面聚集着社会的历史动力，另一方面又破坏着人和土地之间的物质变换，也就是使人以衣食形式消费掉的土地的组成部分不能回到土地，从而破坏土地持久肥力的永恒的自然条件。这样，它同时就破坏城市工人的身体健康和农村工人的精神生活。但是资本主义生产在破坏这种物质变换的纯粹自发形成的状况的同时，又强制地把这种物质变换作为调节社会生产的规律，并在一种同人的充分发展相适合的形式上系统地建立起来。在农业中，象在工场手工业中一样，生产过程的资本主义转化同时表现为生产者的殉难历史，劳动资料同时表现为奴役工人、剥削工人和使工人贫困的手段，劳动过程的社会结合同时表现为对工人个人的活力、自由和独立的有组织的压制。农业工人在广大土地上的分散，同时破坏了他们的反抗力量，而城市工人的集中却增强了他们的反抗力量。在现代农业中，也和在城市工业中一样，劳动生产力的提高和劳动量的增大是以劳动力本身的破坏和衰退为代价的。此外，资本主义农业的任何进步，都不仅是掠夺劳动者的技巧的进步，而且是掠夺土地的技巧的进步，在一定时期内提高土地肥力的任何进步，同时也是破坏土地肥力持久源泉的进步。一个国家，例如北美合众国，越是以大工业作为自己发展的起点，这个破坏过程就越迅速。因此，资本主义生产发展了社会生产过程的技术和结合，只是由于它同时破坏了一切财富的源泉——土地和工人。","language":"中文","translation":false},{"id":"capital-15-1","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-15-2","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"第十四章 绝对剩余价值和相对剩余价值","language":"中文","translation":false},{"id":"capital-15-3","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"劳动过程最初是抽象地，撇开它的各种历史形式，作为人和自然之间的过程来考察的（见第五章）。在那里曾指出：“如果整个劳动过程从其结果的角度加以考察，那末劳动资料和劳动对象表现为生产资料，劳动本身则表现为生产劳动。”并补充说：“这个从简单劳动过程的观点得出的生产劳动的定义，对于资本主义生产过程是绝对不够的。”在这里要进一步研究这个问题。","language":"中文","translation":false},{"id":"capital-15-4","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"就劳动过程是纯粹个人的劳动过程来说，同一劳动者是把后来彼此分离开来的一切职能结合在一起的。当他为了自己的生活目的对自然物实行个人占有时，他是自己支配自己的。后来他成为被支配者。单个人如果不在自己的头脑的支配下使自己的肌肉活动起来，就不能对自然发生作用。正如在自然机体中头和手组成一体一样，劳动过程把脑力劳动和体力劳动结合在一起了。后来它们分离开来，直到处于敌对的对立状态。产品从个体生产者的直接产品转化为社会产品，转化为总体工人即结合劳动人员的共同产品。总体工人的各个成员较直接地或者较间接地作用于劳动对象。因此，随着劳动过程本身的协作性质的发展，生产劳动和它的承担者即生产工人的概念也就必然扩大。为了从事生产劳动，现在不一定要亲自动手；只要成为总体工人的一个器官，完成他所属的某一种职能就够了。上面从物质生产性质本身中得出的关于生产劳动的最初的定义，对于作为整体来看的总体工人始终是正确的。但是，对于总体工人中的每一单个成员来说，就不再适用了。","language":"中文","translation":false},{"id":"capital-15-5","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"但是，另一方面，生产劳动的概念缩小了。资本主义生产不仅是商品的生产，它实质上是剩余价值的生产。工人不是为自己生产，而是为资本生产。因此，工人单是进行生产已经不够了。他必须生产剩余价值。只有为资本家生产剩余价值或者为资本的自行增殖服务的工人，才是生产工人。如果可以在物质生产领域以外举一个例子，那末，一个教员只有当他不仅训练孩子的头脑，而且还为校董的发财致富劳碌时，他才是生产工人。校董不把他的资本投入香肠工厂，而投入教育工厂，这并不使事情有任何改变。因此，生产工人的概念决不只包含活动和效果之间的关系，工人和劳动产品之间的关系，而且还包含一种特殊社会的、历史地产生的生产关系。这种生产关系把工人变成资本增殖的直接手段。所以，成为生产工人不是一种幸福，而是一种不幸。在阐述理论史的本书第四卷将更详细地谈到，古典政治经济学一直把剩余价值的生产看作生产工人的决定性的特征。因此，由于古典政治经济学对剩余价值性质的看法的改变，它对生产工人所下的定义也就有所变化。例如，重农学派认为，只有农业劳动才是生产劳动，因为只有农业劳动才提供剩余价值。在重农学派看来，剩余价值只存在于地租形式中。","language":"中文","translation":false},{"id":"capital-15-6","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"把工作日延长，使之超出工人只生产自己劳动力价值的等价物的那个点，并由资本占有这部分剩余劳动，这就是绝对剩余价值的生产。绝对剩余价值的生产构成资本主义体系的一般基础，并且是相对剩余价值生产的起点。就相对剩余价值的生产来说，工作日一开始就分成必要劳动和剩余劳动这两个部分。为了延长剩余劳动，就要用各种方法缩短生产工资的等价物的时间，从而缩短必要劳动。绝对剩余价值的生产只同工作日的长度有关；相对剩余价值的生产使劳动的技术过程和社会组织发生根本的革命。","language":"中文","translation":false},{"id":"capital-15-7","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"因此，相对剩余价值的生产以特殊的资本主义的生产方式为前提；这种生产方式连同它的方法、手段和条件本身，最初是在劳动在形式上隶属于资本的基础上自发地产生和发展的。劳动对资本的这种形式上的隶属，又让位于劳动对资本的实际上的隶属。","language":"中文","translation":false},{"id":"capital-15-8","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"至于各种中间形式，在这里只要提一下就够了。在这些中间形式中，剩余劳动不是用直接强制的办法从生产者那里榨取的，生产者也没有在形式上隶属于资本。资本在这里还没有直接支配劳动过程。在那些用古老传统的生产方式从事手工业或农业的独立生产者的身旁，有高利贷者或商人，有高利贷资本或商业资本，他们象寄生虫似地吮吸着这些独立生产者。这种剥削形式在一个社会内占统治地位，就排斥资本主义的生产方式，不过另一方面，这种剥削形式又可以成为通向资本主义生产方式的过渡，例如中世纪末期的情况就是这样。最后，正如现代家庭劳动的例子所表明的，某些中间形式还会在大工业的基础上在某些地方再现出来，虽然它的样子完全改变了。","language":"中文","translation":false},{"id":"capital-15-9","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"对于绝对剩余价值的生产来说，只要劳动在形式上隶属于资本就够了，例如，只要从前为自己劳动或者作为行会师傅的帮工的手工业者变成受资本家直接支配的雇佣工人就够了；另一方面却可以看到，生产相对剩余价值的方法同时也是生产绝对剩余价值的方法。无限度地延长工作日正是表现为大工业的特有的产物。特殊的资本主义的生产方式一旦掌握整整一个生产部门，它就不再是单纯生产相对剩余价值的手段，而一旦掌握所有决定性的生产部门，那就更是如此。这时它成了生产过程的普遍的、在社会上占统治地位的形式。现在它作为生产相对剩余价值的特殊方法，只在下面两种情况下起作用：第一，以前只在形式上隶属于资本的那些产业部门为它所占领，也就是说，它扩大作用范围；第二，已经受它支配的产业部门由于生产方法的改变不断发生革命。","language":"中文","translation":false},{"id":"capital-15-10","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"从一定观点看来，绝对剩余价值和相对剩余价值之间的区别似乎完全是幻想的。相对剩余价值是绝对的，因为它以工作日的绝对延长超过工人本身生存所必需的劳动时间以上为前提。绝对剩余价值是相对的，因为它以劳动生产率发展到能够把必要劳动时间限制为工作日的一个部分为前提。但是，如果注意一下剩余价值的运动，这种表面上的同一性就消失了。在资本主义生产方式一旦确立并成为普遍的生产方式的情况下，只要涉及到剩余价值率的提高，绝对剩余价值和相对剩余价值之间的差别就可以感觉到了。假定劳动力按其价值支付，那末，我们就会碰到这样的抉择：如果劳动生产力和劳动的正常强度已定，剩余价值率就只有通过工作日的绝对延长才能提高；另一方面，如果工作日的界限已定，剩余价值率就只有通过工作日两个组成部分即必要劳动和剩余劳动的相对量的变化才能提高，而这种变化在工资不降低到劳动力价值以下的情况下，又以劳动生产率或劳动强度的变化为前提。","language":"中文","translation":false},{"id":"capital-15-11","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"如果工人需要用他的全部时间来生产维持他自己和他的家庭所必需的生活资料，那末他就没有时间来无偿地为第三者劳动。没有一定程度的劳动生产率，工人就没有这种可供支配的时间，而没有这种剩余时间，就不可能有剩余劳动，从而不可能有资本家，而且也不可能有奴隶主，不可能有封建贵族，一句话，不可能有大私有者阶级。","language":"中文","translation":false},{"id":"capital-15-12","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"因此，可以说剩余价值有一个自然基础，但这只是从最一般的意义来说，即没有绝对的自然障碍会妨碍一个人把维持自身生存所必要的劳动从自身上解脱下来并转嫁给别人，例如，同样没有绝对的自然障碍会妨碍一个人去把别人的肉当作食物。绝不应该象有时发生的情况那样，把神秘的观念同这种自然发生的劳动生产率联系起来。只有当人类通过劳动摆脱了最初的动物状态，从而他们的劳动本身已经在一定程度上社会化的时候，一个人的剩余劳动成为另一个人的生存条件的关系才能出现。在文化初期，已经取得的劳动生产力很低，但是需要也很低，需要是同满足需要的手段一同发展的，并且是依靠这些手段发展的。其次，在这个文化初期，社会上依靠别人劳动来生活的那部分人的数量，同直接生产者的数量相比，是微不足道的。随着社会劳动生产力的增进，这部分人也就绝对地和相对地增大起来。并且，资本关系就是在作为一个长期发展过程的产物的经济基础之上产生的。作为资本关系的基础和起点的已有的劳动生产率，不是自然的恩惠，而是几十万年历史的恩惠。","language":"中文","translation":false},{"id":"capital-15-13","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"撇开社会生产的不同发展程度不说，劳动生产率是同自然条件相联系的。这些自然条件都可以归结为人本身的自然（如人种等等）和人的周围的自然。外界自然条件在经济上可以分为两大类：生活资料的自然富源，例如土壤的肥力，鱼产丰富的水等等；劳动资料的自然富源，如奔腾的瀑布、可以航行的河流、森林、金属、煤炭等等。在文化初期，第一类自然富源具有决定性的意义；在较高的发展阶段，第二类自然富源具有决定性的意义。例如，可以用英国同印度比较，或者在古代，用雅典、科林斯同黑海沿岸的地方比较。","language":"中文","translation":false},{"id":"capital-15-14","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"绝对必需满足的自然需要的数量越少，土壤自然肥力越大，气候越好，维持和再生产生产者所必需的劳动时间就越少。因而，生产者在为自己从事的劳动之外来为别人提供的剩余劳动就可以越多。狄奥多洛斯谈到古代埃及人时就这样说过：","language":"中文","translation":false},{"id":"capital-15-15","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“他们抚养子女所花的力气和费用少得简直令人难以相信。他们给孩子随便煮一点最简单的食物；甚至纸草的下端，只要能用火烤一烤，也拿来给孩子们吃。此外也给孩子们吃沼泽植物的根和茎，有的生吃，有的煮一煮或烧一烧再吃。因为气候非常温暖，大多数孩子不穿鞋和衣服。因此父母养大一个子女的费用总共不超过20德拉马。埃及有那么多的人口并有可能兴建那么多宏伟的建筑，主要可由此得到说明。” 但是古代埃及能兴建这些宏伟建筑，与其说是由于埃及人口众多，还不如说是由于有很大一部分人口可供支配。个体工人的必要劳动时间越少，他能提供的剩余劳动就越多；同样，工人人口中从事生产必要生活资料的部分越小，可以用在其他事情方面的部分就越大。","language":"中文","translation":false},{"id":"capital-15-16","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"资本主义生产一旦成为前提，在其他条件不变并且工作日保持一定长度的情况下，剩余劳动量随劳动的自然条件，特别是随土壤的肥力而变化。但绝不能反过来说，最肥沃的土壤最适于资本主义生产方式的生长。资本主义生产方式以人对自然的支配为前提。过于富饶的自然“使人离不开自然的手，就象小孩子离不开引带一样”。它不能使人自身的发展成为一种自然必然性。资本的祖国不是草木繁茂的热带，而是温带。不是土壤的绝对肥力，而是它的差异性和它的自然产品的多样性，形成社会分工的自然基础，并且通过人所处的自然环境的变化，促使他们自己的需要、能力、劳动资料和劳动方式趋于多样化。社会地控制自然力以便经济地加以利用，用人力兴建大规模的工程以便占有或驯服自然力，——这种必要性在产业史上起着最有决定性的作用。如埃及、伦巴第、荷兰等地的治水工程就是例子。或者如印度、波斯等地，在那里人们利用人工渠道进行灌溉，不仅使土地获得必不可少的水，而且使矿物质肥料同淤泥一起从山上流下来。兴修水利是阿拉伯人统治下的西班牙和西西里岛产业繁荣的秘密。","language":"中文","translation":false},{"id":"capital-15-17","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"良好的自然条件始终只提供剩余劳动的可能性，从而只提供剩余价值或剩余产品的可能性，而绝不能提供它的现实性。劳动的不同的自然条件使同一劳动量在不同的国家可以满足不同的需要量，因而在其他条件相似的情况下，使得必要劳动时间各不相同。这些自然条件只作为自然界限对剩余劳动发生影响，就是说，它们只确定开始为别人劳动的起点。产业越进步，这一自然界限就越退缩。在西欧社会中，工人只有靠剩余劳动才能买到为维持自己生存而劳动的许可，因此容易产生一种错觉，似乎提供剩余产品是人类劳动的一种天生的性质。但是，我们可以举出亚洲群岛的东部一些岛屿上的居民的例子。那里的森林中长着野生的西米树。","language":"中文","translation":false},{"id":"capital-15-18","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“居民在西米树上钻个孔，确定树髓已经成熟时，就把树放倒，分成几段，取出树髓，再掺水和过滤，就得到完全可以食用的西米粉。从一棵西米树上通常可以采得西米粉300磅，有时可采得500磅至600磅。那里的居民到森林去采伐面包，就象我们到森林去砍柴一样。”","language":"中文","translation":false},{"id":"capital-15-19","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"假定东亚的这样的面包采伐者为了满足自己的全部需要，每周需要劳动12小时。良好的自然条件直接给予他的，是许多闲暇时间。要他把这些闲暇时间用于为自己生产，需要一系列的历史条件；要他把这些时间用于为别人从事剩余劳动，需要外部的强制。如果那里出现了资本主义生产，这个诚实的人为了占有一个工作日的产品，也许每周就得劳动6天。良好的自然条件并不说明，为什么他现在每周要劳动6天，或者为什么他要提供5天的剩余劳动。它只是说明，为什么他的必要劳动时间限于每周一天。但是，他的剩余产品无论如何不是来自人类劳动的某种天生的神秘性质。","language":"中文","translation":false},{"id":"capital-15-20","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"同历史地发展起来的社会劳动生产力一样，受自然制约的劳动生产力也表现为合并劳动的资本的生产力。——","language":"中文","translation":false},{"id":"capital-15-21","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"李嘉图从来没有考虑到剩余价值的起源。他把剩余价值看作资本主义生产方式固有的东西，而资本主义生产方式在他看来是社会生产的自然形式。他在谈到劳动生产率的时候，不是在其中寻找剩余价值存在的原因，而只是寻找决定剩余价值量的原因。相反，他的学派公开宣称，劳动生产力是利润（应读作剩余价值）产生的原因。这无论如何总比重商主义者前进了一步，因为重商主义者认为，产品的价格超过产品生产费用而形成的余额是从交换中，从产品高于其价值的出售中产生的。不过对这个问题，李嘉图学派也只是回避，而没有解决。这些资产阶级经济学家实际上具有正确的本能，懂得过于深入地研究剩余价值的起源这个爆炸性问题是非常危险的。可是在李嘉图以后半个世纪，约翰·斯图亚特·穆勒先生还在拙劣地重复那些最先把李嘉图学说庸俗化的人的陈腐遁辞，郑重其事地宣称他比重商主义者高明，对此我们该说些什么呢？","language":"中文","translation":false},{"id":"capital-15-22","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“利润的原因在于，劳动生产的东西比维持劳动所需要的东西多。”","language":"中文","translation":false},{"id":"capital-15-23","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"这不过是旧话重提；但是穆勒还想加上一些自己的东西。","language":"中文","translation":false},{"id":"capital-15-24","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“或者换句话说，资本提供利润的原因在于，食物、衣服、原料和劳动资料等存在的时间比生产它们所需要的时间长。”","language":"中文","translation":false},{"id":"capital-15-25","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"这里，穆勒把劳动时间的持续与劳动产品的持续混为一谈了。按照这种看法，面包业主永远不可能从他的雇佣工人那里取得同机器制造业主相同的利润，因为面包业主的产品只能持续一天，而机器制造业主的产品却能持续二十年或更长的时间。自然，如果鸟巢存在的时间不比造巢所需的时间长，鸟只好不要巢了。","language":"中文","translation":false},{"id":"capital-15-26","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"这一基本真理一旦确立，穆勒就来确立他比重商主义者高明之处了：","language":"中文","translation":false},{"id":"capital-15-27","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“因此，我们看到，利润不是来自交换这种偶然的事情，而是来自劳动生产力；不管交换是否发生，一个国家的总利润总是由劳动生产力决定的。如果没有职业的区分，那就既没有买，也没有卖，但是利润依然存在”。 在这里，交换、买和卖这些资本主义生产的一般条件被说成是纯粹偶然的事情；并且没有劳动力的买和卖，利润依然存在！","language":"中文","translation":false},{"id":"capital-15-28","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“如果一个国家的全体工人所生产的东西超过了他们的工资总额的20％，那末不论商品价格的水平如何，利润总是20％。”","language":"中文","translation":false},{"id":"capital-15-29","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"从一方面看，这是绝妙的同义反复，因为既然工人为自己的资本家生产了20％的剩余价值，利润和工人工资总额之比自然是20:100。但另一方面，说利润“总是20％”却是完全错误的。它必然总是小于20％，因为利润要按预付资本的总额来计算。例如，假设资本家预付了500镑，其中400镑预付在生产资料上，100镑预付在工资上。假定剩余价值率照上面所说是20％，那末利润率则是20:500，即4％，而不是20％。","language":"中文","translation":false},{"id":"capital-15-30","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"接下去又有一个光辉的例证，说明穆勒是怎样对待社会生产的各种历史形式的：","language":"中文","translation":false},{"id":"capital-15-31","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“我到处假定，除少数例外，事物的现状到处都占统治地位，这就是说，资本家预付全部费用，包括工人的报酬在内”。","language":"中文","translation":false},{"id":"capital-15-32","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"把地球上迄今只是作为例外而占统治地位的一种状态看作到处存在的状态，这真是奇怪的错觉！我们再往下看。穆勒很乐于承认，“资本家这样做也没有绝对的必要”。事情正好相反。","language":"中文","translation":false},{"id":"capital-15-33","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“如果工人在他完成全部工作以前已有维持这段时间生活所必需的资料，他就可以在完工后再去领他的工资，甚至他的全部工资。但在这种情况下，他在某种程度上成了资本家了，因为他把资本投入企业，提供了经营企业所需的一部分基金。”","language":"中文","translation":false},{"id":"capital-15-34","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"穆勒同样可以说，一个不仅为自己预付生活资料，而且为自己预付劳动资料的工人实际上是他自己的雇佣工人。或者说，只为自己服劳役而不为主人服劳役的美国农民是他自己的奴隶。","language":"中文","translation":false},{"id":"capital-15-35","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"穆勒在这样清楚地论证了资本主义生产甚至在它不存在的时候也总是存在的以后，又完全合乎逻辑地证明，资本主义生产在它存在的时候也是不存在的。他说：","language":"中文","translation":false},{"id":"capital-15-36","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"“甚至在前一场合<即资本家预付雇佣工人的全部生活资料>，我们也可以用同一观点来考察工人<即把他看作资本家>。”“因为他是在市场价格以下<！>提供他的劳动的，所以他好象是把其中的差额<？>预付给他的企业主……”","language":"中文","translation":false},{"id":"capital-15-37","author":"马克思","title":"资本论·第一卷","location":"第十四章 绝对剩余价值和相对剩余价值","page":15,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/14.htm","text":"实际上工人是在一周或其他一段时间内把自己的劳动无偿地预付给资本家，然后在一周之末或其他一段时间结束时才取得他的劳动的市场价格；在穆勒看来，这就使工人成了资本家！平地上的一堆土，看起来也象座小山；现代资产阶级的平庸，从它的“大思想家”的水平上就可以测量出来。","language":"中文","translation":false},{"id":"capital-16-1","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-16-2","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"第十五章 劳动力价格和剩余价值的量的变化","language":"中文","translation":false},{"id":"capital-16-3","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"劳动力价值是由平均工人通常必需的生活资料的价值决定的。这些生活资料在形式上虽然可能有变化，但是在一定社会的一定时代，它们的量是一定的，所以应该看作是一个不变量。变化的是这个量的价值。还有两个因素决定劳动力的价值。一个是劳动力的发展费用，这种费用是随生产方式的变化而变化的；另一个是劳动力的自然差别，男劳动力和女劳动力，成年劳动力和未成年劳动力的自然差别。这些不同劳动力的使用（这又是由生产方式决定的）在工人家庭的再生产费用上和在成年男工的价值上都造成很大的差别。但是在下面的研究中，是撇开这两个因素的。","language":"中文","translation":false},{"id":"capital-16-4","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"我们假定：1、商品是按照它的价值出售的；2、劳动力的价格有时可能比它的价值高，但从不比它的价值低。","language":"中文","translation":false},{"id":"capital-16-5","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"在这种假定下，我们看到，劳动力价格和剩余价值的相对量取决于三种情况：1、工作日的长度，或劳动的外延量；2、正常的劳动强度，或劳动的内含量，即一定时间内耗费一定量的劳动；3、最后，劳动生产力，即由于生产条件发展程度的不同，等量的劳动在同样时间内会提供较多或较少的产品量。显然，这三个因素可以有各种各样的组合：或者是其中一个因素不变，其他两个因素可变；或者两个因素不变，一个因素可变；最后，或者三个因素同时变化。这些因素同时变化时，又因为变化的大小和方向可以不同，组合也就更加多种多样了。下面只谈谈几种最主要的组合。","language":"中文","translation":false},{"id":"capital-16-6","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"I、工作日的长度和劳动强度不变(已定)，劳动生产力可变","language":"中文","translation":false},{"id":"capital-16-7","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"在这个假定下，劳动力的价值和剩余价值是由三个规律决定的：","language":"中文","translation":false},{"id":"capital-16-8","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"第一，不论劳动生产率如何变化，从而不论产品量和单个商品的价格如何变化，一定长度的工作日总表现为相同的价值产品。","language":"中文","translation":false},{"id":"capital-16-9","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"一个十二小时工作日的价值产品例如为6先令，虽然所生产的使用价值量随劳动生产力的变化而变化，以致6先令的价值会分配在较多或较少的商品上面。","language":"中文","translation":false},{"id":"capital-16-10","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"第二，劳动力的价值和剩余价值按照相反的方向变化。劳动生产力的变化，它的提高或降低，按照相反的方向影响劳动力的价值，按照相同的方向影响剩余价值。","language":"中文","translation":false},{"id":"capital-16-11","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"一个十二小时工作日的价值产品是一个不变量，例如6先令。这个不变量等于剩余价值加劳动力价值(这个价值由工人以等价来补偿)之和。不言而喻，在一个不变量的两个部分当中，一个部分不减少，另一个部分就不能增加。剩余价值不由3先令降低到2先令，劳动力的价值就不可能由3先令提高到4先令，反过来，劳动力的价值不由3先令降低到2先令，剩余价值就不可能由3先令提高到4先令。因而，在这种情况下，劳动力价值或剩余价值的绝对量，如果没有它们的相对量或比例量的同时变化，是不可能变化的。劳动力价值和剩余价值不可能同时提高或同时降低。","language":"中文","translation":false},{"id":"capital-16-12","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"其次，如果劳动生产力不提高，劳动力的价值就不能降低，从而剩余价值就不能提高。用前面的例子来说，如果不是劳动生产力的提高，使以前需要6小时生产的生活资料量用4小时就可以生产出来，劳动力的价值就不可能由3先令降低到2先令。反过来，如果不是劳动生产力的下降，使以前只用6小时就能生产的生活资料量要用8小时才能生产出来，劳动力的价值也就不可能由3先令提高到4先令。由此可以得出结论，劳动生产率的提高会降低劳动力的价值，从而提高剩余价值，相反地，劳动生产率的下降会提高劳动力的价值，降低剩余价值。","language":"中文","translation":false},{"id":"capital-16-13","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"李嘉图在表述这个规律时忽略了一点：虽然剩余价值量或剩余劳动量的变化是以劳动力的价值量或必要劳动量的相反的变化为前提的，但决不能由此推论说，这些量是按照同一比例变化的。它们会以相同的量增加或减少。但是价值产品或工作日的各部分增加或减少的比例，取决于劳动生产力变化以前的原来的划分。假定劳动力价值为4先令，或必要劳动时间为8小时，剩余价值为2先令，或剩余劳动为4小时；如果由于劳动生产力提高，劳动力价值降低到3先令，或必要劳动降低到6小时，那末剩余价值就提高到3先令，或剩余劳动提高到6小时。一方增加的量和另一方减少的量都是2小时或1先令。但是量的相对的变化在两方面是不一样的。劳动力的价值由4先令降低到3先令，即降低了1/4或25％，剩余价值则由2先令提高到3先令，即提高1/2或50％。由此可见，劳动生产力的一定变化所引起的剩余价值的增加或减少的比例，取决于工作日中原来表现为剩余价值的那一部分，如果那部分原来较小，比例就较大，原来较大，比例就较小。","language":"中文","translation":false},{"id":"capital-16-14","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"第三，剩余价值的增加或减少始终是劳动力价值相应的减少或增加的结果，而绝不是这种减少或增加的原因。","language":"中文","translation":false},{"id":"capital-16-15","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"因为工作日是一个不变量，并表现为不变的价值量，因为剩余价值量的每一变化都有劳动力价值量的相反的变化与之相适应，又因为劳动力的价值只能随劳动生产力的变化而变化，所以很清楚，在这些条件下，剩余价值量的任何变化都是由劳动力价值量的相反的变化而引起的。上面我们已经知道，劳动力价值和剩余价值的绝对量，如果没有它们的相对量的变化，是不可能变化的。现在，我们又得出，它们的相对量，如果没有劳动力价值的绝对量的变化，是不可能变化的。","language":"中文","translation":false},{"id":"capital-16-16","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"按照第三个规律，剩余价值量的变化是以劳动生产力的变化所引起的劳动力价值的变动为前提的。剩余价值量变化的界限是由劳动力价值的新的界限决定的。但是，即使在情况允许这个规律发生作用的条件下，也会发生各种中间的变动。例如，由于劳动生产力的提高，劳动力价值由4先令降低到3先令，或者必要劳动时间由8小时降低到6小时，而劳动力的价格还是可以只降低到3先令8便士，3先令6便士，3先令2便士等等，因而剩余价值只提高到3先令4便士，3先令6便士，3先令10便士等等。下降以3先令为最低界限，但下降程度要取决于资本的压力同工人的反抗这二者的力量对比。","language":"中文","translation":false},{"id":"capital-16-17","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"劳动力的价值是由一定量的生活资料的价值决定的。随着劳动生产力的变化而变化的，是这些生活资料的价值，而不是它们的量。在劳动生产力提高时，工人和资本家的生活资料量可以同时按照同样的比例增长，而劳动力价格和剩余价值之间不发生任何量的变化。如果劳动力原来的价值是3先令，必要劳动时间是6小时，而剩余价值也是3先令，剩余劳动也是6小时，那末，在工作日的划分不变的情况下，劳动生产力虽然提高一倍，而劳动力价格和剩余价值会保持不变。不过它们现在都表现为数量增加一倍、但按比例变得便宜了的使用价值。劳动力的价格虽然不变，但是它现在提高到劳动力的价值以上。如果劳动力的价格下降，但没有下降到由劳动力的新价值所决定的最低界限，即1 1/2先令，而是下降到2先令10便士，2先令6便士等等，那末这个下降了的价格也还是代表一个增加了的生活资料量。可见，在劳动生产力提高时，劳动力的价格能够不断下降，而工人的生活资料量同时不断增加。但是相对地说，即同剩余价值比较起来，劳动力的价值还是不断下降，从而工人和资本家的生活状况之间的鸿沟越来越深。","language":"中文","translation":false},{"id":"capital-16-18","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"李嘉图第一个严密地表述了上述三个规律。他的阐述中的缺点是：1、他把这些规律所适用的各种特殊条件看作是资本主义生产的理所当然的、普遍的和唯一的条件。他不认识工作日长度的变化，也不认识劳动强度的变化，因此在他看来，劳动生产率自然就成了唯一可变的因素。2、同其他一切经济学家一样，李嘉图从不研究剩余价值本身，就是说，他不是撇开它的特殊形式如利润、地租等去进行研究。这一点在更大的程度上损害了他的分析。因此，他把剩余价值率的各种规律同利润率的各种规律直接混为一谈。上面已经说过，利润率是剩余价值同预付总资本的比率，而剩余价值率则是剩余价值同这个资本的可变部分的比率。假定资本(C)为500镑，分在原料、劳动资料等(c)上共400镑，分在工资(v)上为100镑；再假定剩余价值(m)＝100镑。这样，剩余价值率为m/v＝100镑/100镑＝100％，而利润率m/C＝100镑/500镑＝20％。此外，很显然，利润率还取决于对剩余价值率不发生任何影响的一些情况。以后在本书第三卷中，我将说明，同一个剩余价值率可以表现为极不相同的利润率，而不同的剩余价值率在一定情况下也可以表现为同一利润率。","language":"中文","translation":false},{"id":"capital-16-19","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"II、工作日和劳动生产力不变，劳动强度可变","language":"中文","translation":false},{"id":"capital-16-20","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"劳动强度的提高是以在同一时间内劳动消耗的增加为前提的。因此，一个强度较大的工作日比一个时数相同但强度较小的工作日体现为更多的产品。诚然，在劳动生产力提高时，同一个工作日也会提供较多的产品。但在后一种情况下，由于产品所费劳动比以前少，单个产品的价值也就下降；而在前一种情况下，由于产品所费的劳动同以前一样，单个产品的价值也就保持不变。在这种情况下，产品的数量增加了，但它们的价格没有下降。随着产品数量的增加，它们的价格总额也就增大，但在生产力提高的情况下，同一价值总额不过表现在增大的产品总量上。可见，如果劳动时数不变，强度较大的工作日就体现为较多的价值产品，因而，在货币的价值不变的情况下，也就体现为较多的货币。强度较大的工作日的价值产品随着它的强度同社会的正常强度的偏离程度而变化。因此，同一个工作日不再象以前那样表现为一个不变的价值产品，而是表现为一个可变的价值产品。例如，强度较大的十二小时工作日，就不象普通强度的十二小时工作日那样，表现为6先令，而是表现为7先令、8先令等等。显然，如果一个工作日的价值产品发生变化，例如从6先令增加到8先令，那末这个价值产品的两个部分，即劳动力的价格和剩余价值可以同时按照相同的或不同的程度增加。如果价值产品由6先令提高到8先令，劳动力价格和剩余价值可以同时由3先令增加到4先令。在这种场合，劳动力价格虽然提高，但不一定要超过它的价值。相反地，在劳动力价格提高时，劳动力价格还可能降低到劳动力的价值以下。当劳动力价格的提高不能补偿劳动力的加速的损耗时总是发生这种情况。","language":"中文","translation":false},{"id":"capital-16-21","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"我们知道，撇开一时的例外情况不说，只有在有关的产业部门的产品加入工人的日常消费的情况下，劳动生产率的变化才能引起劳动力价值量的变化，从而引起剩余价值量的变化。这种限制在这里是不适用的。不论劳动量在外延上还是在内含上发生变化，劳动的价值产品量总要相应地随着变化，不管这个价值借以体现的物品有怎样的性质。","language":"中文","translation":false},{"id":"capital-16-22","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"如果一切产业部门的劳动强度都同时相等地提高，新的提高了的强度就成为普通的社会的正常强度，因而不再被算作外延量。但是甚至在这种情况下，平均的劳动强度在不同的国家仍然是不同的，因而，会使价值规律在不同国家的工作日的应用上有所变化。一个国家的强度较大的工作日，比另一个国家的强度较小的工作日，表现为更大的货币额。","language":"中文","translation":false},{"id":"capital-16-23","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"III、劳动生产力和劳动强度不变，工作日可变","language":"中文","translation":false},{"id":"capital-16-24","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"工作日可以向两个方向变化。它可以缩短或延长。","language":"中文","translation":false},{"id":"capital-16-25","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"1、在假定的条件下，即在劳动生产力和劳动强度不变时，工作日的缩短不会使劳动力价值，从而不会使必要劳动时间发生变化。但是它会缩小剩余劳动和剩余价值。随着剩余价值的绝对量的下降，它的相对量，即它同劳动力价值的不变量相比的量也就下降。资本家只有把劳动力价格压低到它的价值以下，才能避免损失。","language":"中文","translation":false},{"id":"capital-16-26","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"一切反对缩短工作日的陈词滥调，都认定这种现象是在这里所假设的这种条件下发生的。然而实际上正好相反：在工作日缩短以前或紧随着工作日缩短以后，劳动生产率和劳动强度会发生变化。","language":"中文","translation":false},{"id":"capital-16-27","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"2、工作日的延长：假定必要劳动时间是6小时，或劳动力价值是3先令，剩余劳动也是6小时，剩余价值是3先令。那末，整个工作日就是12小时，并表现为6先令的价值产品。如果工作日延长2小时，劳动力价格不变，那末剩余价值的相对量就随同它的绝对量一同增加。虽然劳动力价值按其绝对量来说没有变化，但就其相对量来说却降低了。在第I节所假设的条件下，劳动力价值的绝对量不发生变化，它的相对量就不可能变化。相反地，在这里，劳动力价值的相对量的变化，是剩余价值的绝对量的变化的结果。","language":"中文","translation":false},{"id":"capital-16-28","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"因为工作日借以表现的价值产品随着工作日的延长而增加，所以劳动力的价格和剩余价值可以同时等量地或不等量地增长。这种同时增长可以发生在下述两种场合：工作日绝对延长，或者工作日没有绝对延长，但是劳动强度增加了。","language":"中文","translation":false},{"id":"capital-16-29","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"随着工作日的延长，劳动力的价格尽管名义上不变，甚至有所提高，还是可能降到它的价值以下。我们记得，劳动力的日价值是根据劳动力的正常的平均持续时间或工人的正常的寿命来计算的，并且是根据从生命物质到运动的相应的、正常的、适合人体性质的转化来计算的。与工作日的延长密不可分的劳动力的更大损耗，在一定点内，可以用增多的报酬来补偿。超过这一点，损耗便以几何级数增加，同时劳动力再生产和发挥作用的一切正常条件就遭到破坏。劳动力的价格和劳动力的剥削程度就不再是可通约的量了。","language":"中文","translation":false},{"id":"capital-16-30","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"IV、劳动的持续时间、劳动生产力和劳动强度同时变化","language":"中文","translation":false},{"id":"capital-16-31","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"很明显，在这里可能有许多种组合。可能两个因素变化，一个因素不变，或者三个因素同时发生变化。它们可能在同一程度上或在不同程度上变化，可能向同一方向或向相反的方向变化，以致它们的变化可以部分地或全部地互相抵销。其实，根据I、II、III节所作的解释来分析一切可能的情况并不困难。只要顺次地把其中一个因素视为可变，把其他因素视为不变，就会得到任何一种可能的组合的结果。因此在下面我们只简单地谈谈两种重要的情况。","language":"中文","translation":false},{"id":"capital-16-32","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"1、劳动生产力降低，同时工作日延长：","language":"中文","translation":false},{"id":"capital-16-33","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"这里所谈的劳动生产力的降低，是指这样一些劳动部门，它们的产品决定劳动力的价值。由于土壤肥力下降以及农产品相应涨价所引起的劳动生产力的降低，就是一个例子。假定工作日是12小时，它的价值产品是6先令，其中一半补偿劳动力的价值，另一半形成剩余价值。因此，工作日划分为6小时必要劳动和6小时剩余劳动。假定由于农产品的涨价，劳动力的价值由3先令提高到4先令，因而必要劳动时间由6小时增加到8小时。如果工作日不变，剩余劳动就会从6小时减少到4小时，剩余价值就会从3先令降低到2先令。如果工作日延长2小时，即从12小时延长到14小时，那末剩余劳动仍然是6小时，剩余价值仍然是3先令，但是剩余价值量同由必要劳动计量的劳动力价值相比较却下降了。如果工作日延长4小时，即由12小时延长到16小时，那末剩余价值和劳动力价值的比例量，剩余劳动和必要劳动的比例量不会改变。但是剩余价值的绝对量由3先令增加到4先令，剩余劳动的绝对量也由6个劳动小时增加到8个劳动小时，即增加1/3或33 1/3％。可见，在劳动生产力降低和工作日同时延长的情况下，即使剩余价值的比例量降低，它的绝对量仍可保持不变；即使剩余价值的绝对量增加，它的比例量仍可保持不变；并且，工作日延长到一定的程度时，剩余价值的比例量和绝对量都可能增加。","language":"中文","translation":false},{"id":"capital-16-34","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"在1799年到1815年期间，英国生活资料价格的上涨引起了名义工资的提高，虽然用生活资料表示的实际工资降低了。威斯特和李嘉图由此得出农业劳动生产率的下降引起剩余价值率下降的结论，并且把这个仅仅存在于他们幻想之中的假定当作出发点，来对工资、利润和地租的相对的量的关系进行重要的分析。但是在当时，由于劳动强度的提高和劳动时间的强制延长，剩余价值也绝对地和相对地增加了。这正是工作日的无限度的延长获得了公认的时期，这个时期的特点是：一方面资本加速增长，另一方面需要救济的赤贫也加速增长。〔注：“战争期间资本增加的主要原因，在于每个社会中人数最多的劳动阶级的更加努力，也许还在于这个阶级的更加贫困。更多的妇女和儿童为环境所迫，不得不从事劳动；原来的工人，由于同样的原因不得不拿出更多的时间去增加生产。”（《政治经济学论文集。论当前国家贫困的主要原因》1830年伦敦版第248页）〕","language":"中文","translation":false},{"id":"capital-16-35","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"2、劳动强度和劳动生产力提高，同时工作日缩短：","language":"中文","translation":false},{"id":"capital-16-36","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"劳动生产力的提高和劳动强度的增加，从一方面来说，起着同样的作用。它们都会增加任何一段时间内所生产的产品总额。因此，它们都能缩短工人生产自己的生活资料或其等价物所必需的工作日部分。工作日的绝对最低界限，总是由工作日的这个必要的但能缩减的部分形成。如果整个工作日缩小到这个必要的部分，那末剩余劳动就消失了，这在资本的制度下是不可能发生的。只有消灭资本主义生产形式，才允许把工作日限制在必要劳动上。但是，在其他条件不变的情况下，必要劳动将会扩大自己的范围。一方面，是因为工人的生活条件日益丰富，他们的生活需求日益增长。另一方面，是因为现在的剩余劳动的一部分将会列入必要劳动，即形成社会准备基金和社会积累基金所必要的劳动。","language":"中文","translation":false},{"id":"capital-16-37","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"劳动生产力越是增长，工作日就越能缩短；而工作日越是缩短，劳动强度就越能增加。从社会的角度来看，劳动生产率还随同劳动的节约而增长。这种节约不仅包括生产资料的节约，而且还包括一切无用劳动的免除。资本主义生产方式迫使单个企业实行节约，但是它的无政府状态的竞争制度却造成社会生产资料和劳动力的最大的浪费，而且也产生了无数现在是必不可少的、但就其本身来说是多余的职能。","language":"中文","translation":false},{"id":"capital-16-38","author":"马克思","title":"资本论·第一卷","location":"第十五章 劳动力价格和剩余价值的量的变化","page":16,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/15.htm","text":"在劳动强度和劳动生产力已定的情况下，劳动在一切有劳动能力的社会成员之间分配得越平均，一个社会阶层把劳动的自然必然性从自身上解脱下来并转嫁给另一个社会阶层的可能性越小，社会工作日中必须用于物质生产的部分就越小，从而个人从事自由活动，脑力活动和社会活动的时间部分就越大。从这一方面来说，工作日的缩短的绝对界限就是劳动的普遍化。在资本主义社会里，一个阶级享有自由时间，是由于群众的全部生活时间都转化为劳动时间了。","language":"中文","translation":false},{"id":"capital-17-1","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-17-2","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"第十六章 剩余价值率的各种公式","language":"中文","translation":false},{"id":"capital-17-3","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"我们已经知道，剩余价值率是用下列公式来表示的：","language":"中文","translation":false},{"id":"capital-17-4","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"I、剩余价值m/可变资本v＝剩余价值/劳动力价值＝剩余劳动/必要劳动","language":"中文","translation":false},{"id":"capital-17-5","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"前两个公式是价值的比率，第三个公式是生产这些价值所需要的时间的比率，它们表示同一个东西。这些互相替代的公式在概念上是严格的。因此，我们看到，在古典政治经济学中，这些公式诚然在实质上已经制定出来，但是还不是有意识地制定的。在那里我们看到的是下列派生的公式：","language":"中文","translation":false},{"id":"capital-17-6","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"II、剩余劳动/工作日＝剩余价值/产品价值＝剩余产品/总产品","language":"中文","translation":false},{"id":"capital-17-7","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"这里，同一个比率交替地在劳动时间的形式上，在劳动时间借以体现的价值的形式上，在这些价值借以存在的产品的形式上表现出来。不言而喻，这里所说的产品价值只能理解为工作日的价值产品，产品价值的不变部分不包括在内。","language":"中文","translation":false},{"id":"capital-17-8","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"在所有这些公式中，实际的劳动剥削程度或剩余价值率是虚假地被表现出来的。假定工作日为12小时。根据我们前面例子 的其他各项假设，在这里，实际的劳动剥削程度就表现为如下的比率：","language":"中文","translation":false},{"id":"capital-17-9","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"6小时剩余劳动/6小时必要劳动＝3先令剩余价值/3先令可变资本＝100%","language":"中文","translation":false},{"id":"capital-17-10","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"但是，根据公式II，我们却得出：","language":"中文","translation":false},{"id":"capital-17-11","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"6小时剩余劳动/12小时工作日＝3先令剩余价值/6先令价值产品＝50%","language":"中文","translation":false},{"id":"capital-17-12","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"这两个派生的公式实际上表示工作日或其价值产品按怎样的比例在资本家和工人之间进行分配。因此，如果把这些公式看作资本自行增殖的直接表现，就会得出一个虚假的规律：剩余劳动或剩余价值绝不能达到100%。 〔注：例如，见《洛贝尔图斯给冯·基尔希曼的第三封信。驳李嘉图的地租学说，对新的地租理论的论证》1851年柏林版。关于这一著作，我以后还要谈到。该著作提出的地租理论虽然是错误的，但它看出了资本主义生产的本质。——{第3版补注：从这里可以看出，只要马克思在前人那里看到任何真正的进步和任何正确的新思想，他总是对他们作出善意的评价。 而洛贝尔图斯致鲁道夫·迈耶尔的书信的发表，使马克思的上述赞许不能不打一个相当的折扣。书信中说：“不仅要把资本从劳动中拯救，而且要把它从其自身中拯救出来，要真正做到这一点，最好是把企业主资本家的活动理解为资本所有权委托给他的国民经济职能或国家经济职能，把他的利润理解为一种薪俸的形式，因为我们还不知道有其他的社会组织。但薪俸是可以调节的，如果它过多地侵占了工资，还可以降低。马克思对社会的入侵——我要这样来称呼他的著作——也应该这样来击退…… 总之，马克思的著作与其说是对资本的研究，还不如说是对现代资本形式的攻击。他把现代资本形式和资本概念本身混为一谈了，这就是他的错误的根源。”（《洛贝尔图斯—亚格措夫博士书信和社会政治论文集》，鲁道夫·迈耶尔博士出版，1881年柏林版第1卷第111页，洛贝尔图斯第48封信)——洛贝尔图斯在《社会问题书简》里的真正大胆的进攻完全为这些陈旧平庸的思想所淹没了。 ——弗·恩·}〕 因为剩余劳动始终只能是工作日的一个部分，或剩余价值始终只能是价值产品的一个部分，所以剩余劳动必然始终小于工作日，或剩余价值必然始终小于价 值产品。二者必须相等，才能达到100/100的比率。剩余劳动要吞掉整个工作日(这里指一周劳动或一年劳动等等的平均日)，必要劳动就必须减到零。但是，如果必要劳动消失了，剩余劳动也就消失了，因为后者只是前者的函数。因此，剩余劳动/工作日＝剩余价值/价值产品这个比率永远不能达到100/100的界限，更不能提高到(100+x)/100。但剩余价值率或实际的劳动剥削程度完全能够达到这种程度。就拿路易·德·拉维涅先生的计算做例子。根据他的计算，英国农业工人只得到产品〔注：不言而喻，在这种计算中，产品中只补偿所投不变资本的那一部分是没有计算在内的。——路易·德·拉维涅先生是一位盲目崇拜英国的人，他只会把比例估计过低，决不会估计过高。〕 或其价值的1/4，而资本家(租地农场主)得到3/4，不管这个赃物以后还要在资本家和土地所有者等人之间怎样进行分配。依照这个例子，英国农业工人的剩余劳动和必要劳动之比是3:1，剥削率是300%。","language":"中文","translation":false},{"id":"capital-17-13","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"古典学派把工作日看作不变量的方法，由于公式II的应用而固定化了，因为人们在这里总是把剩余劳动同一定长度的工作日进行比较。如果只着眼于价值产品的分配，也会得到同样的结果。已经物化在价值产品中的工作日总是具有一定界限的工作日。","language":"中文","translation":false},{"id":"capital-17-14","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"把剩余价值和劳动力价值表现为价值产品的两部分——这种表现方式其实是从资本主义生产方式本身中产生的，它的意义将在以后加以说明——掩盖了资本关系的特殊性质，即掩盖了可变资本与活劳动力的交换，以及与此相适应的工人与产品的分离。代替的是一种协作关系的假象，仿佛工人和资本家在这种协作关系中是按照产品的不同的形成要素的比例来分配产品的。〔注：因为资本主义生产过程的一切发达的形式都是协作形式，所以，把这些形式所特有的对抗性质抽去，并把它们胡说成是自由的协作，自然是再容易不过的事情了。例如，亚·德·拉波尔德伯爵在《论有利于社会一切方面的协作精神》（1818年巴黎版）中就是这样做的。美国人亨·凯里有时甚至把这种戏法应用于奴隶制度的关系，也收到相同的效果。〕","language":"中文","translation":false},{"id":"capital-17-15","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"但是，公式II在任何时候都能再转化成公式I。例如，如果我们知道6小时剩余劳动/12小时工作日，则必要劳动时间＝12小时工作日减掉6小时剩余劳动，并得出：","language":"中文","translation":false},{"id":"capital-17-16","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"6小时剩余劳动/6小时必要劳动＝100/100","language":"中文","translation":false},{"id":"capital-17-17","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"我在前面已经顺便提到的第三个公式是：","language":"中文","translation":false},{"id":"capital-17-18","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"III、剩余价值/劳动力价值＝剩余劳动/必要劳动＝无酬劳动/有酬劳动","language":"中文","translation":false},{"id":"capital-17-19","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"无酬劳动/有酬劳动这个公式会引起一种误解，好象资本家是向劳动而不是向劳动力支付报酬，但是这种误解经过前面的说明已经消除了。无酬劳动/有酬劳动这个公式只是剩余劳动/必要劳动这个公式的通俗的表述。资本家支付劳动力价值或偏离这一价值的劳动力价格，在交换中取得对活劳动力本身的支配权。他对这种劳动力的利用分为两个时期。在一个时期，工人只生产一个等于他的劳动力价值的价值，因而只生产一个等价物。这样，资本家预付出劳动力的价格，得到一个价格相等的产品。事情就好象资本家是在市场上购买现成的产品。 而在剩余劳动期间，劳动力的利用为资本家创造出无须他付出代价的价值。他无偿地获得了劳动力的这种利用。在这个意义上，剩余劳动可以称为无酬劳动。","language":"中文","translation":false},{"id":"capital-17-20","author":"马克思","title":"资本论·第一卷","location":"第十六章 剩余价值率的各种公式","page":17,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/16.htm","text":"因此，资本不仅象亚·斯密所说的那样，是对劳动的支配权。按其本质来说，它是对无酬劳动的支配权。一切剩余价值，不论它后来在利润、利息、地租等等哪种特殊形式上结晶起来，实质上都是无酬劳动时间的物化。资本自行增殖的秘密归结为资本对别人的一定数量的无酬劳动的支配权。","language":"中文","translation":false},{"id":"capital-18-1","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-18-2","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"第十七章 劳动力的价值或价格转化为工资","language":"中文","translation":false},{"id":"capital-18-3","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"在资产阶级社会的表面上，工人的工资表现为劳动的价格，表现为对一定量劳动支付的一定量货币。在这里，人们说劳动的价值，并把它的货币表现叫做劳动的必要价格或自然价格。另一方面，人们说劳动的市场价格，也就是围绕着劳动的必要价格上下波动的价格。","language":"中文","translation":false},{"id":"capital-18-4","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"但什么是商品的价值呢？这就是耗费在商品生产上的社会劳动的物化形式。我们又用什么来计量商品的价值量呢？用它所包含的劳动量来计量。那末，比如说，一个十二小时工作日的价值是由什么决定的呢？是由十二小时工作日中包含的12个劳动小时决定的；这是无谓的同义反复。[1]","language":"中文","translation":false},{"id":"capital-18-5","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"劳动要作为商品在市场上出卖，无论如何必须在出卖以前就已存在。但是，工人如果能使他的劳动独立存在，他出卖的就是商品，而不是劳动。[2]","language":"中文","translation":false},{"id":"capital-18-6","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"撇开这些矛盾不说，货币即物化劳动同活劳动的直接交换，也会或者消灭那个正是在资本主义生产的基础上才自由展开的价值规律，或者消灭那种正是以雇佣劳动为基础的资本主义生产本身。举例来说，假定一个十二小时工作日表现为6先令的货币价值。或者是等价物相交换，这样，工人以12小时劳动获得6先令。他的劳动的价格就要等于他的产品的价格。在这种情形下，他没有为他的劳动的购买者生产剩余价值，这6先令不转化为资本，资本主义生产的基础就会消失，然而正是在这个基础上，工人才出卖他的劳动，而他的劳动也才成为雇佣劳动。或者工人在12小时劳动中获得的少于6先令，就是说，少于12小时劳动。12小时劳动同10小时劳动、6小时劳动等等相交换。不等量的这种相等，不仅消灭了价值规定。这种自我消灭的矛盾甚至根本不可能当作规律来阐明或表述。[3]","language":"中文","translation":false},{"id":"capital-18-7","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"从劳动分为物化劳动和活劳动这一形式上的区别而引出较多量劳动同较少量劳动相交换，这是徒劳无益的。[4]既然商品的价值不是由实际物化在商品中的劳动量来决定，而是由生产该商品所必需的活劳动的量来决定，所以这种做法就更加荒谬了。假定一个商品代表6个劳动小时。如果一些发明使这个商品用3小时就可以生产出来，那末，连已经生产出来的商品的价值也会降低一半。现在，这个商品所代表的只是3小时社会必要劳动，而不是原先6小时社会必要劳动了。可见，决定商品的价值量的，是生产商品所必需的劳动量，而不是劳动的物化形式。","language":"中文","translation":false},{"id":"capital-18-8","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"实际上，在商品市场上同货币所有者直接对立的不是劳动，而是工人。工人出卖的是他的劳动力。当工人的劳动实际上开始了的时候，它就不再属于工人了，因而也就不再能被工人出卖了。劳动是价值的实体和内在尺度，但是它本身没有价值。[5]","language":"中文","translation":false},{"id":"capital-18-9","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"在“劳动的价值”这个用语中，价值概念不但完全消失，而且转化为它的反面。这是一个虚幻的用语，就象说土地的价值一样。但是这类虚幻的用语是从生产关系本身中产生的。它们是本质关系的表现形式的范畴。事物在其现象上往往颠倒地表现出来，这是几乎所有的科学都承认的，只有政治经济学例外。[6]","language":"中文","translation":false},{"id":"capital-18-10","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"古典政治经济学毫无批判地从日常生活中借用了“劳动的价格”这个范畴，然后提出问题：这一价格是怎样决定的？它马上认识到，供求关系的变化，对于劳动的价格也象对于一切其他商品的价格一样，无非是说明价格的变化，也就是说明市场价格围绕着一定的量上下波动。假定供求相抵，而其他条件不变，价格的波动就会停止。这时，供求也不再说明任何东西了。在供求相抵时，劳动的价格就是它的不依赖供求关系来决定的价格，即它的自然价格，而这个价格才真正是应当分析的对象。或者我们拿市场价格在一个较长时期（比如说一年）内的波动来看，就会发现，这种上下的波动会互相抵销，而得出一个中等的平均量，一个不变量。这个平均量和围绕着这个平均量发生的互相抵销的偏离，自然是由不同的东西决定的。这个支配着和调节着劳动的偶然市场价格的价格，即劳动的“必要价格”（重农学派）或“自然价格”（亚当·斯密），也象其他商品的价格一样，只能是用货币来表现的劳动的价值。政治经济学以为用这种办法，就可以通过劳动的偶然价格进到劳动的价值。然后认为，这一价值也和其他商品的价值一样，是由生产费用来决定的。但是工人的生产费用，即用来生产或再生产工人本身的费用又是什么呢？这个问题在政治经济学上是不自觉地代替了原来的问题，因为政治经济学在谈到劳动本身的生产费用时，只是兜圈子，没有前进一步。可见，政治经济学称为劳动的价值的东西，实际上就是劳动力的价值；劳动力存在于工人身体内，它不同于它的职能即劳动，正如机器不同于机器的功能一样。人们研究了劳动的市场价格同它的所谓价值之间的区别，研究了这种价值同利润率、同劳动所生产的商品价值的关系等等，但从来没有发现，分析的进程不仅已从劳动的市场价格推移到它的假想的价值，而且又把这个劳动价值本身化为劳动力的价值。古典政治经济学没有意识到自己的分析所得出的这个结果，毫无批判地采用“劳动的价值”，“劳动的自然价格”等等范畴，把它们当作所考察的价值关系的最后的、适当的用语，结果就象我们在下面将要看到的那样，陷入了无法解决的混乱和矛盾中，同时替庸俗经济学的在原则上只忠于假象的浅薄理论提供了牢固的活动基础。","language":"中文","translation":false},{"id":"capital-18-11","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"现在，我们首先来考察一下，劳动力的价值和价格是怎样表现为它的转化形式，即表现为工资的。","language":"中文","translation":false},{"id":"capital-18-12","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"我们知道，劳动力的日价值是根据工人的一定的寿命来计算的，而同工人的一定的寿命相适应的是一定长度的工作日。假定，一个普通工作日是12小时，劳动力的日价值是3先令，而这3先令是体现了6个劳动小时的价值的货币表现。如果工人获得了3先令，他就获得了他的在12小时内执行职能的劳动力的价值。现在如果劳动力的这个日价值当作日劳动的价值来表现，那就会得出这样一个公式：12小时的劳动有3先令价值。这样一来，劳动力的价值就决定劳动的价值，或者用货币来表现，就决定劳动的必要价格。如果劳动力的价格同它的价值相偏离，那末劳动的价格也就会同它的所谓价值相偏离。","language":"中文","translation":false},{"id":"capital-18-13","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"既然劳动的价值只是劳动力的价值的不合理的用语，那末不言而喻，劳动的价值必定总是小于劳动的价值产品，因为资本家总是使劳动力执行职能的时间超过再生产劳动力本身的价值所需要的时间。在上述例子中，在12小时内执行职能的劳动力的价值是3先令，为了再生产这一价值，劳动力需要执行职能6小时。可是劳动力的价值产品是6先令，因为劳动力实际上执行职能12小时，而劳动力的价值产品不是由劳动力本身的价值来决定的，而是由劳动力执行职能的时间长短来决定的。这样，我们就会得到一个一看就是荒谬的结果：创造6先令价值的劳动有3先令价值。[7]","language":"中文","translation":false},{"id":"capital-18-14","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"其次，我们看到，体现工作日的有酬部分即6小时劳动的3先令价值，表现为包含6小时无酬劳动在内的整个十二小时工作日的价值或价格。于是，工资的形式消灭了工作日分为必要劳动和剩余劳动、分为有酬劳动和无酬劳动的一切痕迹。全部劳动都表现为有酬劳动。在徭役劳动下，服徭役者为自己的劳动和为地主的强制劳动在空间上和时间上都是明显地分开的。在奴隶劳动下，连奴隶只是用来补偿他本身的生活资料的价值的工作日部分，即他实际上为自己劳动的工作日部分，也表现为好象是为主人的劳动。他的全部劳动都表现为无酬劳动。[8]相反地，在雇佣劳动下，甚至剩余劳动或无酬劳动也表现为有酬劳动。在奴隶劳动下，所有权关系掩盖了奴隶为自己的劳动，而在雇佣劳动下，货币关系掩盖了雇佣工人的无偿劳动。","language":"中文","translation":false},{"id":"capital-18-15","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"因此可以懂得，为什么劳动力的价值和价格转化为工资形式，即转化为劳动本身的价值和价格，会具有决定性的重要意义。这种表现形式掩盖了现实关系，正好显示出它的反面。工人和资本家的一切法权观念，资本主义生产方式的一切神秘性，这一生产方式所产生的一切自由幻觉，庸俗经济学的一切辩护遁词，都是以这个表现形式为依据的。","language":"中文","translation":false},{"id":"capital-18-16","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"如果说世界历史需要经过很长时间才揭开了工资的秘密，那末相反地，要了解这种表现形式的必然性，存在的理由，却是再容易不过的了。","language":"中文","translation":false},{"id":"capital-18-17","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"资本和劳动的交换，在人们的感觉上，最初完全同其他一切商品的买卖一样。买者付出一定量的货币，卖者付出与货币不同的物品。在这里，法权意识至多只认识物质的区别，这种区别表现在法权上对等的公式中：“我给，为了你给；我给，为了你做；我做，为了你给；我做，为了你做”。","language":"中文","translation":false},{"id":"capital-18-18","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"其次，因为交换价值和使用价值本身是不可通约的量，所以“劳动的价值”、“劳动的价格”这种用语，似乎并不比“棉花的价值”、“棉花的价格”这种用语更不合理。况且，工人是在提供自己的劳动以后被支付报酬的。而货币充当支付手段，是在事后才实现所提供的物品的价值或价格的，在这里就是实现所提供的劳动的价值或价格。最后，工人提供给资本家的“使用价值”，实际上不是他的劳动力，而是劳动力的职能，即一定的有用劳动，裁缝劳动，鞋匠劳动，纺纱劳动等等。至于这种劳动另一方面又是形成价值的一般要素，具有一种使它同一切其他商品相区别的属性，这一点却是普通意识所不能领会的。","language":"中文","translation":false},{"id":"capital-18-19","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"让我们站在工人的立场上来看，他以12小时劳动获得6小时劳动的价值产品，比如说3先令，对他说来，他的12小时劳动实际上是3先令的购买手段。他的劳动力的价值可以随着他的日常生活资料的价值的变化而变化，从3先令提高到4先令或降低到2先令。或者他的劳动力的价值不变，它的价格可以因供求关系的变化，从3先令提高到4先令或降低到2先令。但是不管怎样，他付出的始终是12个劳动小时。因此，在他看来，他所获得的等价物的量的任何变化，都必然表现为他的12个劳动小时的价值或价格的变化。由于这种情况，把工作日看作不变量的亚·斯密[9]就反过来得出一个错误的论断：劳动的价值是不变的，虽然生活资料的价值会变化，因而对工人来说，同一个工作日会表现为较多或较少的货币。","language":"中文","translation":false},{"id":"capital-18-20","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"另一方面我们拿资本家来说。他无疑希望用尽量少的货币换取尽量多的劳动。因此，他实际上所关心的只是劳动力的价格和劳动力执行职能时所创造的价值之间的差额。但是，他力图尽可能便宜地购买一切商品，并且总是把低于价值购买和高于价值出售这一纯粹欺诈行为说成是他的利润的来源。因而，他理解不到，如果劳动的价值这种东西确实存在，而且他确实支付了这一价值，那末资本就不会存在，他的货币也就不会转化为资本。","language":"中文","translation":false},{"id":"capital-18-21","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"此外，工资的实际运动显示出一些现象，似乎证明被支付的不是劳动力的价值，而是它的职能即劳动本身的价值。这些现象可以归纳为两大类：第一，工资随着工作日长度的变化而变化。如果是这样，那我们同样可以说，因为租用机器一周的费用比租用一天要贵，所以被支付的不是机器的价值，而是机器功能的价值。第二，执行同一职能的不同工人的工资间存在着个人的差别。这种个人的差别在奴隶制度下也可以看到，但是在那里劳动力本身是赤裸裸地、不加任何掩饰地出卖的，这种差别没有引起任何幻觉。区别只是在于：劳动力因超过平均水平而获得的利益或因低于平均水平而遭到的损失，在奴隶制度下落到奴隶主身上，而在雇佣劳动制度下则落到工人自己身上，因为在后一种场合，劳动力是由工人自己出卖的，而在前一种场合，是由第三者出卖的。","language":"中文","translation":false},{"id":"capital-18-22","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"总之，“劳动的价值和价格”或“工资”这个表现形式不同于它所表现的本质关系，即劳动力的价值和价格，我们关于一切表现形式和隐藏在它们背后的基础所说的话，在这里也是适用的。前者是直接地自发地作为流行的思维形式再生产出来的，而后者只有通过科学才能揭示出来。古典政治经济学几乎接触到事物的真实状况，但是没有自觉地把它表述出来。只要古典政治经济学附着在资产阶级的皮上，它就不可能做到这一点。","language":"中文","translation":false},{"id":"capital-18-23","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[1] “李嘉图相当机智地避开了一个困难，这个困难乍看起来似乎会推翻他的关于价值取决于生产中所使用的劳动量的理论。如果严格地坚持这个原则，就会得出结论说，劳动的价值取决于劳动的生产中所使用的劳动量。这显然是荒谬的。因此，李嘉图用了一个巧妙的手法，使劳动的价值取决于生产工资所需要的劳动量；或者用他自己的话来说，劳动的价值应当由生产工资所必需的劳动量来估量；他这里指的是为生产付给工人的货币或商品所必需的劳动量。那我们同样也可以说，呢绒的价值不是由生产呢绒所花费的劳动量来估量，而是由生产用呢绒换得的银所花费的劳动量来估量。”（［赛· 贝利］《对价值的本质、尺度和原因的批判研究》第50、51页）","language":"中文","translation":false},{"id":"capital-18-24","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[2] “如果你们把劳动叫做商品，那末它也还是不同于一般商品。后者最初为交换的目的而生产，然后拿到市场上去，和同时在市场上出售的其他商品按照适当的比例相交换。劳动只有当它被带到市场上去的那一瞬间才被创造出来，或者不如说，劳动是在它被创造出来以前被带到市场上去的。”（《评政治经济学上若干用语的争论》第75、76页）","language":"中文","translation":false},{"id":"capital-18-25","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[3] “如果把劳动看成一种商品，而把资本，劳动的产品，看成另一种商品，并且假定这两种商品的价值是由相同的劳动量来决定的，那末……一定量的劳动就会和同量劳动所生产的资本量相交换；过去的劳动就会……和同量的现在的劳动相交换。但是，劳动的价值同其他商品相比……不是由同量劳动决定的。”（爱·吉·威克菲尔德对他出版的亚·斯密《国富论》所加的注。1835年伦敦版第1卷第230、231页）","language":"中文","translation":false},{"id":"capital-18-26","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[4] “必须同意〈“社会契约论”的又一翻版〉，每当已经完成的劳动同将要宪成的劳动相交换时，后者＜资本家＞获得的价值必须多于前者＜工人＞。”（西蒙（即西斯蒙第）《论商业财富》1803年日内瓦版第1卷第37页）","language":"中文","translation":false},{"id":"capital-18-27","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[5] “劳动，即价值的唯一尺度……一切财富的创造者，不是商品。”（托·霍吉斯金《通俗政治经济学》第186页）","language":"中文","translation":false},{"id":"capital-18-28","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[6] 相反地，把这些用语说成是单纯的诗人的破格权，这只能说明分析的无能。蒲鲁东说：“人们认为劳动有价值并不因为它本身是商品，而是指人们认定劳动中所隐含的价值。劳动的价值是一种……比喻说法。”因此，针对这种说法我指出：“他把劳动商品这个可怕的现实只看做是文法上的简略。这就是说，建立在劳动商品基础上的整个现代社会，今后仅仅是建立在某种破格的诗文和比喻性的用语上了。如果社会愿意‘排除’使它烦恼的‘一切麻烦’，那末只要去掉不好听的字句，改一改说法就可以了；要达到这个目的，只要请求科学院出版一部新辞典就够了。”(卡尔·马克思《哲学的贫困》第34、35页)把价值了解为什么也不是，当然方便多了。这样，就可以随便把任何东西都包括到这个范畴中去。例如，让·巴·萨伊就是这样做的。“价值”是什么？答：“物之所值。”“价格”是什么？答：“以货币表现的物的价值。”为什么“土地的劳动……具有价值？因为人们赋予它一个价格”。这就是说，价值是物之所值，而土地之所以有“价值”，是因为人们“用货币表现了”它的价值。总之，这是理解事物“因何”和“为何”问题的非常简便的方法。","language":"中文","translation":false},{"id":"capital-18-29","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[7] 参看《政治经济学批判》第40页。我曾在那里指出，在考察资本时应当解决这个间题：“为什么在纯粹由劳动时间决定的交换价值的基础上进行的生产，结果竟会使劳动的交换价值小于这劳动的产品的交换价值呢？”","language":"中文","translation":false},{"id":"capital-18-30","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[8] 伦敦一家天真到愚蠢程度的自由贸易派机关报《晨星报》，在美国南北战争时期，一再以人类所能有的义愤断言，“南部同盟”的黑人完全是白白地劳动的。最好请它把这种黑人的一天的费用同例如伦敦东头的自由工人的一天的费用比较一下。","language":"中文","translation":false},{"id":"capital-18-31","author":"马克思","title":"资本论·第一卷","location":"第十七章 劳动力的价值或价格转化为工资","page":18,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/17.htm","text":"[9] 亚·斯密只是在谈到计件工资时，才偶然地隐约提到工作日的变化。","language":"中文","translation":false},{"id":"capital-19-1","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-19-2","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"工资本身又采取各种各样的形式，这种情况从那些过分注重材料而忽视一切形式区别的经济学教程中是了解不到的。但是，阐述所有这些形式是属于专门研究雇佣劳动的学说的范围，因而不是本书的任务。不过，这里要简单地说明一下两种占统治地位的基本形式。","language":"中文","translation":false},{"id":"capital-19-3","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"我们记得，劳动力总是按一定时期来出卖的。因此，直接表现劳动力的日价值、周价值等等的转化形式，就是“计时工资”的形式，也就是日工资等等。","language":"中文","translation":false},{"id":"capital-19-4","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"首先应当指出，在第十五章叙述过的关于劳动力价格和剩余价值的量的变化的规律，只须改变一下形式，就转化为工资规律。同样，劳动力的交换价值和由这个价值转变成的生活资料的量之间的区别，现在则表现为名义工资和实际工资之间的区别。在本质形式上已经阐明的事情，再在表现形式上重复一遍，那是徒劳无益的。因此我们只限于说明计时工资的若干特点。","language":"中文","translation":false},{"id":"capital-19-5","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"工人靠日劳动、周劳动等等得到的货币额[1]，形成他的名义的即按价值计算的工资额。但是很明显，依照工作日的长短，即依照工人每天所提供的劳动量，同样的日工资、周工资等等可以代表极不相同的劳动价格，也就是说，可以代表对同量劳动所支付的极不相同的货币额[2]。因而，在考察计时工资时必须再把工资总额，即日工资、周工资等等的总额和劳动价格区别开来。但怎样得出这个价格，即一定量劳动的货币价值呢？劳动力的平均日价值除以平均工作日的小时数，就得出平均的劳动价格。假定劳动力的日价值是3先令，即6个劳动小时的价值产品，而工作日为12小时，那末1个劳动小时的价格＝3先令／12＝3便士。这样得出的劳动小时的价格就是劳动价格的单位尺度。","language":"中文","translation":false},{"id":"capital-19-6","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"由此可见，即使劳动价格不断下降，日工资、周工资等等仍然可以保持不变。例如，一个普通工作日是10小时，劳动力的日价值是3先令，那末1个劳动小时的价格是 3 3／5 便士；一旦工作日延长到12小时，1个劳动小时的价格就降低到3便士，一旦工作日延长到15小时，1个劳动小时的价格就降低到 2 2／5 便士。虽然如此，日工资或周工资仍旧不变。反之，即使劳动价格不变或甚至下降，日工资或周工资也可以增加。例如，一个工作日是10小时，劳动力的日价值是3先令，那末1个劳动小时的价格就是 3 3／5 便士。如果由于工作量增加，工人按照原来的劳动价格劳动12小时，那末他的日工资就增加到3先令 7 1／5 便士，而劳动价格没有变化。如果不是增加劳动的外延量而是增加劳动的内含量，那也会得到同样的结果[3]。因此，名义上的日工资或周工资提高的同时，劳动价格可以不变或下降。这也适用于工人家庭的收入，只要家长提供的劳动量是靠家庭成员的劳动而增加的。因此，存在着不减少名义上的日工资或周工资而降低劳动价格的各种方法。[4]","language":"中文","translation":false},{"id":"capital-19-7","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"一般的规律就是：如果日劳动、周劳动等等的量已定，那末日工资或周工资就决定于劳动价格，而劳动价格本身或者是随着劳动力的价值而变化，或者是随着劳动力的价格与其价值的偏离而变化。反之，如果劳动价格已定，那末日工资或周工资就决定于日劳动或周劳动的量。","language":"中文","translation":false},{"id":"capital-19-8","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"计时工资的计量单位，即1个劳动小时的价格，是劳动力的日价值除以普通工作日的小时数所得之商。假定一个普通工作日是12小时，而劳动力的日价值是3先令，即6个劳动小时的价值产品。在这种情况下，1个劳动小时的价格是3便士，它的价值产品是6便士。如果工人现在一天就业不足12小时（或者一周不足6天），比如说只有8小时或6小时，那末按这个劳动价格计算，他只能得到2先令或 1 1／2 先令的日工资[5]。因为根据假定，工人要生产出一个只是和他的劳动力价值相适应的日工资，一天必须平均劳动6小时，又因为根据同一假定，他在每小时内只有一半时间是为自己劳动，而另一半时间是为资本家劳动，所以很清楚，如果他就业不足12小时，他就不能挣得6小时的价值产品。前面我们已经看到过度劳动的破坏性后果，这里我们又发现了工人由于就业不足所遭受的苦难的源泉。","language":"中文","translation":false},{"id":"capital-19-9","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"如果小时工资是用下述办法来确定的，即资本家不承担支付日工资或周工资的义务，而只是愿意雇用工人多少劳动小时就支付多少小时的报酬，那末，资本家就能使工人就业的时间少于原先作为计算小时工资或劳动价格的计量单位的基础的那个时间。因为这种计量单位是由（劳动力的日价值／一定小时的工作日）这个比率确定的，所以，一旦工作日不再包含一定的小时数，这种计量单位自然就失去了任何意义。有酬劳动和无酬劳动之间的联系就被消除了。现在资本家不让工人做满维持自身生存所必需的劳动时间，也能从工人身上榨取一定量的剩余劳动。他可以破坏就业方面的任何规则性，完全按照自己的方便、意愿和眼前利益，使最惊人的过度劳动同相对的或完全的失业互相交替。他可以在支付“正常的劳动价格”的借口下，把工作日延长到超过正常的限度，而不给工人任何相应的补偿。因此，伦敦建筑工人为反对资本家强制实行这种小时工资的企图，发动了一次完全合理的暴动（1860年）。法律对工作日的限制结束了这种不正当的作法，不过，这种限制当然没有消灭由于机器的竞争、由于所使用的工人在质量上的改变以及局部的和普遍的危机而产生的就业不足的现象。","language":"中文","translation":false},{"id":"capital-19-10","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"在日工资或周工资增加的情形下，劳动价格可以在名义上保持不变，甚至降低到它的正常水平以下。只要劳动价格或劳动小时的价格不变，而工作日超出它的普通长度，这种情况就会发生。在（劳动力的日价值／工作日）这一分数中，如果分母增大，分子就会更快地增大。由于劳动力的损耗，劳动力的价值会同劳动力执行职能的时间一起增加，而且前者增加的比例比后者更快。因此，在计时工资占统治地位而劳动时间又不受法律限制的许多产业部门中，就自然地形成了一种习惯，把达到一定点（比如满10小时）的工作日当作是正常的（《normal working day》〔“正常的工作日”〕，《the day's work》〔“日劳动”〕，《the regular hours of work》〔“正规的劳动时间”〕）。超过这个界限的劳动时间形成额外时间，并且以小时为计量单位付以额外报酬，虽然额外报酬往往低得可怜[6]。正常工作日在这里是作为实际工作日的一部分而存在的，而且就全年来说，实际工作日往往比正常工作日要长[7]。在英国各种产业部门中，在工作日的延长超出一定正常界限时，劳动价格的增长造成了这样一种情况：所谓正常时间内的劳动价格很低，这就迫使那些想挣得足够工资的工人在额外时间去做报酬较高的工作[8]。法律对工作日的限制结束了这种快意的事情。[9]","language":"中文","translation":false},{"id":"capital-19-11","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"在一个产业部门内，工作日越长，工资就越低，这是人所共知的事实[10]。工厂视察员亚·雷德格雷夫通过1839年到1859年二十年间的比较观察说明了这一点。根据他的观察，在受十小时工作日法令约束的工厂中，工资提高了，而在每天工作14到15小时的工厂中，工资下降了。[11]","language":"中文","translation":false},{"id":"capital-19-12","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"从“在劳动价格已定时，日工资或周工资决定于所提供的劳动量”这一规律中首先可以得出这样的结论：劳动价格越低，工人为了保证得到哪怕是可怜的平均工资而付出的劳动量必然越大，或者说，工作日必然越长。劳动价格的低廉在这里起了刺激劳动时间延长的作用。[12]","language":"中文","translation":false},{"id":"capital-19-13","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"但是，劳动时间的延长反过来又会引起劳动价格的下降，从而引起日工资或周工资的下降。","language":"中文","translation":false},{"id":"capital-19-14","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"劳动价格由（劳动力的日价值／一定小时数的工作日）来决定这个事实表明：如果没有任何补偿，单是工作日的延长就会降低劳动价格。但是那些使资本家能够长期延长工作日的情况，最初使他能够，最后则迫使他也在名义上降低劳动价格，以致劳动时数增加了，但总价格即日工资或周工资反而下降了。这里只要指出两种情况就够了。如果一个人完成一个半人或两个人的工作，那末即使市场上劳动力的供给不变，劳动的供给还是增加了。由此造成的工人之间的竞争，使资本家能够压低劳动价格，而劳动价格的降低反过来又使他能够更加延长劳动时间。[13]但是这种对异常的即超过社会平均水平的无酬劳动量的支配权，很快就会成为资本家本身之间的竞争手段。商品价格的一部分是由劳动价格构成的。劳动价格的无酬部分不需要计算在商品价格内。它可以赠送给商品购买者。这是竞争促成的第一步。竞争迫使完成的第二步是，至少把延长工作日而产生的异常的剩余价值的一部分也不包括在商品的出售价格中。异常低廉的商品出售价格就是以这样的方式形成的，最初是偶然的，以后就逐渐固定下来，并且从此成为劳动时间过长而工资极低的不变基础，而原先它却是这些情况所造成的结果。我们只是指出这一运动，因为分析竞争不是这里要做的事情。不过我们还是可以听一下资本家本人的自白。","language":"中文","translation":false},{"id":"capital-19-15","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"“在北明翰，业主之间的竞争是这样激烈，以致我们中间的某些人，不得不以雇主的身分做我们平素感到可耻的事情；但是即使如此也不能多赚钱，而只是让公众从中得到好处。”[14] 我们记得伦敦有两种面包房老板，一种是按全价出售面包，另一种是低于正常价格出售面包。“全价出售者”向议会调查委员会指责他们的竞争者说：","language":"中文","translation":false},{"id":"capital-19-16","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"“他们能够存在，首先就是靠欺骗公众<商品掺假>，其次是靠从工人身上榨取18小时的劳动而支付12小时的工资…… 工人的无酬劳动是用来进行竞争的手段…… 面包业主之间的竞争是夜间劳动难以废除的原因。低价出售者低于成本价格（它随着面粉价格的变化而变化）出售面包，但他并没有受到损失，因为他从工人身上榨取了更多的劳动。如果我从工人那里只取得12小时劳动，而我的邻居却取得18或20小时劳动，那末，他必然会在出售价格上把我击败。如果工人能坚持要求支付额外时间的报酬，这种手法立刻就会完蛋…… 低价出售者雇用的工人中，有很大一部分是外国人、少年和其他人，他们被迫满足于几乎任何一种他们所能得到的工资。”[15] 这种诉苦之所以有意思，还因为它表明：反映在资本家头脑中的只是生产关系的假象。资本家不知道，劳动的正常价格也包含着一定量的无酬劳动，并且正是这种无酬劳动是他的利润的正常源泉。剩余劳动时间这个范畴对他说来是根本不存在的，因为剩余劳动时间包含在正常的工作日之内，而后者在他看来已经在日工资中支付了。但是，额外时间，即工作日超过与普通的劳动价格相适应的界限的延长部分，对他来说却是存在的。为了对付他的低价出售的竞争者，他甚至主张对这种额外时间支付额外报酬。但是他仍然不知道，这种额外报酬，和普通的劳动小时的价格一样，也包含着无酬劳动。例如，十二小时工作日的一个小时价格是3便士，即1/2个劳动小时的价值产品，而一个额外劳动小时的价格是4便士，即2/3个劳动小时的价值产品。在第一种场合，资本家无偿地占有了1/2个劳动小时，在第二种场合，无偿地占有了1/3个劳动小时。","language":"中文","translation":false},{"id":"capital-19-17","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[1] 这里总是假定货币本身的价值是不变的。","language":"中文","translation":false},{"id":"capital-19-18","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[2] “劳动价格是对一定量劳动所支付的货币额。”（爱德华·威斯特爵士《谷物价格和工资》1826年伦敦版第67页）威斯特是《论资本用于土地》（牛津大学大学学院一特待校友著，1815年伦敦版）这本在政治经济学史上有划时代意义的匿名著作的作者。","language":"中文","translation":false},{"id":"capital-19-19","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[3] “工资决定于劳动价格和完成的劳动量……工资的增加不一定包含着劳动价格的提高。在劳动时间较长和劳动较紧张的情况下，工资可以大大增加，而劳动价格却可以保持不变。”（爱德华·威斯特爵士《谷物价格和工资》1826年伦敦版第67、68 和112页）不过关于“劳动价格”是怎样决定的这样一个主要间题，威斯特却用陈词滥调搪塞过去了。","language":"中文","translation":false},{"id":"capital-19-20","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[4] 十八世纪工业资产阶级的最狂热的辩护士、我们多次引用过的《论手工业和商业》的作者正确地感觉到了这一点，虽然他把问题阐述得很混乱：“由食品和其他生活必需品的价格决定的是劳动的量，而不是劳动的价格＜他把劳动价格理解为名义上的日工资或周工资＞，如果大大降低生活必需品的价格，那你们自然就会相应地减少劳动的量……工厂主们知道，除了改变劳动价格的名义数额以外，还有各种提高或降低劳动价格的方法”（《论手工业和商业》第48 和61页）。纳·威·西尼耳在他的《关于工资率的三篇演讲》（1830年伦敦版）中不加引号地利用了威斯特的著作，比如他说；“工人主要关心的是工资的数量”（第15页）。这就是说，工人主要关心的是他所得到的东西，即工资的名义数额，而不是他所给予的东西，即劳动的量！","language":"中文","translation":false},{"id":"capital-19-21","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[5] 这种异常的就业不足的影响是和法律强制普遍缩短工作日的影响完全不同的。前者与工作日的绝对长度无关，它可以在15小时工作日上发生，同样也可以在6小时工作日上发生。正常的劳动价格，在第一种场合是按照工人平均每天劳动15小时来计算的，在第二种场合，是按照他平均每天劳动6小时来计算的。因此，如果他在第一种场合只就业7.5小时，在第二种场合只就业3小时，那末结果就会相同。","language":"中文","translation":false},{"id":"capital-19-22","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[6] “额外时间的报酬率＜在花边制造业中＞非常低，每小时1/2便士等等，以致同它对工人的健康和生命力所造成的巨大损害形成了尖锐的对照……不仅如此，这样挣得的一点点额外报酬往往又不得不耗费在额外的饮食上。”（《童工调查委员会。第2号报告》第XVI页第117号）","language":"中文","translation":false},{"id":"capital-19-23","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[7] 例如，在壁纸印刷业中，在工厂法最近实行以前，情况就是这样。“我们一直劳动，连吃饭的间歇时间也没有，结果10个半小时的日工到下午4点半就完了，此后就全是额外时间，这种时间很少在下午6点以前结束，因此，实际上我们终年都在做额外时间的工作。”（斯密先生的证词，载于《童工调查委员会。第1号报告》第125页）","language":"中文","translation":false},{"id":"capital-19-24","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[8] 例如，在苏格兰的漂白业中就是这样。“在苏格兰的某些地方，这种行业＜在1862年工厂法实行以前＞是按额外时间的制度经营的，即把10小时当作正常的工作日。在这段时间内每人得到1先令2便士。但是每天还有3 或4小时额外时间，每小时的报酬是3便士。实行这种制度的结果是：只在正常时间内劳动的人，只能挣得8先令的周工资。不在额外时间做工，工资是不够用的。”（《工厂视察员报告。1863年4月30日》第10页）这种“额外时间的额外报酬，是工人无力抗拒的一种诱惑”（《工厂视察员报告。1848年4月30日》第5页）。伦敦西蒂的书籍装订业雇用了许多14、15岁的少女，而且还订有学徒合同，规定了一定的劳动小时。尽管如此，在每月的最后一周，她们还是要同较年长的男工混杂在一起，一直劳动到夜间10、11、12点，甚至到1点。“业主以额外工资和一顿丰富的夜餐钱来引诱她们”，这顿夜餐，她们是在附近的酒馆中吃的。在这些“年青的永生者”中间因此产生了十分放荡的行为（《童工调查委员会。第5号报告》第44页第191号），不过这些行为，由于她们除了其他书籍外还装订了大量的圣经和宗教书籍而得到了补偿。","language":"中文","translation":false},{"id":"capital-19-25","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[9] 见《工厂视察员报告。1863年4月30日》第5页。在1860年大罢工和同盟歇业中，伦敦建筑工人对事态作了完全正确的判断，他们声明，只有在下述两个条件下才愿意接受小时工资：1．在规定劳动小时价格的同时，也要规定以9小时或10小时为正常工作日，而且10小时工作日的每小时价格要高于9小时工作日的每小时价格；2．超过正常工作日的每一小时都是额外时间，要相应地付给较高的报酬。","language":"中文","translation":false},{"id":"capital-19-26","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[10] “此外，这是一个十分值得注意的事实：通常劳动时间长的地方，工资就低。”（《工厂视察员报告。1863年10月31日》第9页）“只能挣得饥饿工资的劳动大多是过长的。”（《公共卫生。第6号报告。1863年》第15页）","language":"中文","translation":false},{"id":"capital-19-27","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[11] 《工厂视察员报告。1860年4月30日》第31、32页。","language":"中文","translation":false},{"id":"capital-19-28","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[12] 例如，英国手工制钉业工人，由于劳动价格低廉，每天要劳动15小时才能挣得极可怜的周工资。“他一天到晚累死累活地要干许许多多小时，才能挣得11便士或1先令，而且从中还要扣除2.5到3便士，以补偿工具的磨损、燃料的耗费和铁屑的耗损。”（《童工调查委员会。第3号报告》第136页第671号）在同样长的劳动时间内，女工只能挣得5先令的周工资（同上，第137页第674号）。","language":"中文","translation":false},{"id":"capital-19-29","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[13] 例如，一个工厂工人如果拒绝象通常那样干较多的时数，“他很快就会被任何一个不论干多长时间都愿意的工人所代替，这样他就会失业”（《工厂视察员报告。1848年10月31日》，证词第39页第58号）。“如果一个人做两个人的工作……利润率通常会提高……因为这种追加的劳动供给，压低了劳动的价格。”（西尼耳《关于工资率的三篇演讲》1830年伦敦版第15页）","language":"中文","translation":false},{"id":"capital-19-30","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[14] 《童工调查委员会。第3号报告》，证词第66页第22号。","language":"中文","translation":false},{"id":"capital-19-31","author":"马克思","title":"资本论·第一卷","location":"第十八章 计时工资","page":19,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/18.htm","text":"[15] 《就面包工人的申诉向女王陛下内务大臣的报告》1862年伦敦版第LII页和同一报告，证词第479、359、27号。不过，全价出售者，如我们在前面已经提到的，而且象他们的代言人贝奈特本人所承认的，也让他们的工人“在晚上11点钟或更早的时候开始干活，并且往往延长到第二天晚上7点钟”（同上，第22页）。","language":"中文","translation":false},{"id":"capital-20-1","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-20-2","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"计件工资无非是计时工资的转化形式，正如计时工资是劳动力的价值或价格的转化形式一样。","language":"中文","translation":false},{"id":"capital-20-3","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"在实行计件工资的情况下，乍一看来，似乎工人出卖的使用价值不是他的劳动力的职能即活的劳动，而是已经物化在产品中的劳动，似乎这种劳动的价格不是象计时工资那样，由（劳动力的日价值／一定小时数的工作日）这个分数来决定，而是由生产者的工作效率来决定的。[1]","language":"中文","translation":false},{"id":"capital-20-4","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"首先，两种工资形式在同一些行业中同时并存的事实，剧烈地动摇着对这种假象的信念。例如：","language":"中文","translation":false},{"id":"capital-20-5","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"“伦敦的排字工人通常是拿计件工资，计时工资在他们那里是例外。相反地，各地的排字工人，通常是拿计时工资，计件工资是例外。伦敦港口的造船工人拿计件工资，英国其他港口的造船工人则拿计时工资。”[2] 在伦敦，同一些马具工场中，就同一种劳动来说，往往对法国人支付计件工资，对英国人支付计时工资。在普遍实行计件工资的真正工厂中，个别劳动职能由于技术上的原因不能按件计算，因而按计时工资来支付[3]。不过很清楚，工资支付形式的区别丝毫没有改变工资的本质，虽然其中一种形式可以比另一种形式更有利于资本主义生产的发展。","language":"中文","translation":false},{"id":"capital-20-6","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"假定普通工作日为12小时，其中6小时是有酬的，6小时是无酬的。一个工作日的价值产品假定是6先令，从而一个劳动小时的价值产品是6便士。假定经验表明，一个具有平均劳动强度和技能，因而在生产一种物品时实际上只耗费社会必要劳动时间的工人，在12小时内提供24件产品，不管它们是一个个可分离的产品，还是一个具有连续性的制品的可以分别计量的部分。这样，这24件产品的价值，扣除其中包含的不变资本部分，为6先令，每件产品的价值为3便士。工人每件得 1 1／2 便士，所以12小时得3先令。在实行计时工资的情况下，不管是假定工人6小时为自己劳动，6小时为资本家劳动，还是假定他每小时一半为自己劳动，一半为资本家劳动，都是没有区别的；同样在这里，不管是说每一件产品一半是有酬的，一半是无酬的，还是说12件产品的价格只是补偿劳动力的价值，而另外12件产品体现为剩余价值，也是没有区别的。","language":"中文","translation":false},{"id":"capital-20-7","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"计件工资的形式同计时工资的形式一样是不合理的。例如，两件商品，扣除其中耗费掉的生产资料的价值，作为一个劳动小时的产品，值6便士，而工人由此得到3便士的价格。计件工资实际上不直接表现价值关系。在这里，不是一件商品的价值由体现在其中的劳动时间来计量，相反地，工人耗费的劳动是由他们生产的产品的件数来计量。在实行计时工资的情况下，劳动由劳动的直接的持续时间来计量；在实行计件工资的情况下，则由在一定时间内劳动所凝结成的产品的数量来计量[4]。劳动时间本身的价格最终决定于这个等式：日劳动价值＝劳动力的日价值。因此，计件工资只是计时工资的转化形式。","language":"中文","translation":false},{"id":"capital-20-8","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"现在我们比较详细地来考察一下计件工资的特点。","language":"中文","translation":false},{"id":"capital-20-9","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"在这里，劳动的质量是由产品本身来控制的，产品必须具有平均的质量，计件价格才能得到完全的支付。从这方面说，计件工资是克扣工资和进行资本主义欺诈的最丰富的源泉。","language":"中文","translation":false},{"id":"capital-20-10","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"计件工资给资本家提供了一个十分确定的计算劳动强度的尺度。只有体现在一个预先规定的并由经验确定的商品量中的劳动时间，才被看作是社会必要劳动时间，并当作这种劳动时间来支付报酬。因此，在伦敦较大的裁缝工场中，把某件产品，例如一件背心等等，叫作一小时或半小时等等，每小时付给6便士。从实践中知道，一小时的平均产品是多少。在做时装、改衣服等等时，雇主和工人之间常常会为某件产品是否等于一小时等等发生争执，最后还是要由经验来解决。在伦敦的家具制造厂等部门中也有同样的情况。如果工人没有平均的工作效率，因而不能提供最低限度的日劳动，他就会被解雇。[5]","language":"中文","translation":false},{"id":"capital-20-11","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"既然劳动的质量和强度在这里是由工资形式本身来控制的，那末对劳动的监督大部分就成为多余的了。因此，计件工资的形式既形成前面所说的现代家庭劳动的基础，也形成层层剥削和压迫的制度的基础。后一种制度有两种基本形式。一方面，计件工资使资本家和雇佣工人之间的寄生者的中间盘剥即包工制更容易实行。中间人的利润完全来自资本家支付的劳动价格和中间人实际付给工人的那部分劳动价格之间的差额[6]。在英国，这种制度有一个特别的称呼（血汗制度）。另一方面，计件工资使资本家能与工头（在手工工场是组长，在矿井是采煤工人等等，在工厂是真正的机器工人）签订按件计酬的合同，以便工头按照合同规定的价格自己负责招募帮手和支付给他们工资。在这里，资本对工人的剥削是通过工人对工人的剥削来实现的。[7]","language":"中文","translation":false},{"id":"capital-20-12","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"实行了计件工资，很自然，工人的个人利益就会使他尽可能紧张地发挥自己的劳动力，而这又使资本家容易提高劳动强度的正常程度。[8]同样，延长工作日也是工人的个人利益之所在，因为这样可以提高他的日工资或周工资[9]。这就会引起那种在研究计时工资时已经指出过的反作用，更不用说，即使在计件工资保持不变的情况下，工作日的延长本身就包含着劳动价格的下降。","language":"中文","translation":false},{"id":"capital-20-13","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"在实行计时工资的情况下，除少数例外，通常是对同样的职能支付同样多的工资；在实行计件工资的情况下，虽然劳动时间的价格是由一定量的产品来计量的，但日工资或周工资却因工人的个人差别而变化，因为某一工人在一定时间内只提供最低限额的产品，另一工人提供平均数额的产品，第三个工人则提供超过平均数额的产品。在这种情况下，各个工人的实际收入，就会因其技能、体力、精力、耐力等等的不同而有很大的差别[10]。当然，这绝不会改变资本和雇佣劳动之间的一般关系。第一，就整个工场来说，个人的差别会互相抵销，所以，整个工场在一定劳动时间内会提供一个平均的产品量，而支付的总工资也是本行业的平均工资。第二，工资和剩余价值间的比例仍旧不变，因为各个工人各自提供的剩余价值量是同他们各自的工资相适应的。但是计件工资给个性提供的较大的活动场所，一方面促进了工人个性的发展，从而促进了自由精神、独立性和自我监督能力的发展；但另一方面也促进了他们之间的互相竞争。因此，计件工资有一种趋势，就是在把个别工资提高到平均水平以上的同时，把这个水平本身降低。但是，在某种计件工资根据长期的传统已经固定下来，因而特别难以降低的地方，雇主就会破例地把计件工资强行改成计时工资。例如，1860年考文垂织带工人大罢工就是由此引起的[11]。最后，计件工资是上一章叙述的计时制的主要支柱。[12]","language":"中文","translation":false},{"id":"capital-20-14","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"从以上所述可以看出：计件工资是最适合资本主义生产方式的工资形式。虽然计件工资绝不是什么新东西，在十四世纪，它就已经与计时工资一起正式列入英法两国的劳工法中，但是只是在真正工场手工业时期，它才得到比较广阔的活动场所。在大工业的狂飈时期，特别是从1797年至1815年，计件工资成了延长劳动时间和降低工资的手段。我们从蓝皮书《谷物法请愿特别委员会的报告和证词》（1813年至1814年议会会期）和《上院委员会关于谷物的生长、贸易、消费状况以及有关法律的报告》（1814年至1815年会期）中，可以找到有关当时工资变动的十分重要的材料。在这里，我们可以找到自从反雅各宾战争开始以来劳动价格不断下降的证明文件。例如，在织布业中计件工资下降得很厉害，尽管工作日已经大大延长，但日工资仍旧低于以前的水平。","language":"中文","translation":false},{"id":"capital-20-15","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"“织布工人的实际收入比从前大为减少：同普通工人相比，他的优越性以前是很大的，而现在几乎完全消失了。事实上，熟练劳动和普通劳动的工资间的差别现在比过去任何时期都小得多。”[13] 随着计件工资的实行而增加的劳动强度和长度，对农业无产阶级毫无好处，这从一本维护大地主和租地农场主利益的书中摘录出来的下面这段话就可以看出：","language":"中文","translation":false},{"id":"capital-20-16","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"“绝大部分农活是由按日或按件雇用的人来完成的。他们的周工资约为12先令；虽然可以假定，一个人在采用计件工资的情况下，由于劳动有较大的刺激，比在采用周工资的情况下能够多挣1先令或许2先令，但是在计算他的总收入时就会发现，他在一年中由于失业所造成的损失抵销了这一增加部分…… 一般说来我们还会发现，这些人的工资同必要生活资料的价格保持着一定的比例，所以有两个孩子的人，可以不靠教区的救济而维持一家的生活。”[14] 当时马尔萨斯就议会公布的事实说过：","language":"中文","translation":false},{"id":"capital-20-17","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"“我承认，我看到计件工资的广泛采用，感到不愉快。在较长的时期内每天从事12或14小时实在繁重的劳动，对一个人来说是太多了。”[15] 在受工厂法约束的工场内，一般都采用计件工资，因为在这里，资本只能从强度方面扩大工作日。[16]","language":"中文","translation":false},{"id":"capital-20-18","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"随着劳动生产率的改变，同一产品量所代表的劳动时间也会改变。于是计件工资也会改变，因为计件工资是一定劳动时间的价格表现。就上面所举的例子来说，12小时内生产出24件产品，12小时的价值产品是6先令，劳动力的日价值是3先令，一个劳动小时的价格是3便士，每件产品的工资是 1 1／2 便士。每件产品吸收了 1／2 个劳动小时。假定劳动生产率提高一倍，同一个工作日现在提供的产品不是24件，而是48件，在其他一切情况不变的条件下，计件工资就会由1 1/2便士降低到3/4便士，因为现在每件产品所代表的已经不是 1／2 个劳动小时，而只是 1／4 个劳动小时。24×（1 1／2）便士＝3先令，同样48×（3／4 ）便士＝3先令。换句话说，计件工资的下降是与同一时间内所生产的产品件数的增加成比例的[17]，从而，是与耗费在同一件产品上的劳动时间的减少成比例的。计件工资的这种变动虽然纯粹是名义上的，但也会引起资本家和工人之间的经常不断的斗争：或者是因为资本家以此为借口来实际降低劳动的价格，或者是因为在劳动生产力提高的同时也提高了劳动强度；或者是因为工人当真看待计件工资的假象，认为被支付的是他的产品，而不是他的劳动力，因此反对在商品的出售价格没有相应地降低的情况下降低工资。","language":"中文","translation":false},{"id":"capital-20-19","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"“工人仔细地注视着原料的价格和制品的价格，这样就能够准确地估计他们的雇主的利润。”[18] 资本有权拒绝这种要求，认为这是对雇佣劳动的性质的粗暴歪曲[19]。它痛斥这种要对产业进步课税的狂妄企图，并且断然宣称劳动生产率与工人毫不相干。[20]","language":"中文","translation":false},{"id":"capital-20-20","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[1] “计件劳动制度标志着工人史上的一个时代，它是介于受资本家意志支配的普通短工的地位和不久的将来有希望一身兼任手工业者和资本家的合作手工业者之间的阶段。计件工人虽然靠企业主的资本从事劳动，实际上是自己的雇主。”（约翰·瓦茨《工会和罢工。机器和合作社》1865年曼彻斯特版第52、53页）我引用这本小册子，是因为它是一切早已陈腐的辩护滥调的真正臭水坑。就是这位瓦茨先生，以前曾热中于欧文主义，并在1842年发表过另外一本小册子《政治经济学家的事实和臆想》，在那里，他说财产就是掠夺。这已经是很久以前的事了。","language":"中文","translation":false},{"id":"capital-20-21","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[2] 托·约·登宁《工联和罢工》1860年伦敦版第22页。","language":"中文","translation":false},{"id":"capital-20-22","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[3] 下面这个例子说明，这两种工资形式的同时并存多么有利于工厂主进行欺诈：“一个工厂雇了400个人，其中一半是拿计件工资的，劳动时间长一些对他们有直接利益。另外200人是按日支付报酬的，他们劳动的时间与计件工人一样长，但是他们的额外劳动时间得不到任何报酬……这200个人每天在半小时内多干的活，就等于1个人在50小时内或一个人在一周劳动的5/6的时间内所干的活，这对于企业主有明显的好处。”（《工厂视察员报告。1860年10月31日》第9页）“额外劳动仍旧非常盛行。而且，在大多数场合下，法律本身就提供了保障，使这种现象不致被揭发出来而受到惩处。在以前许多报告中，我一再指出……所有那些不是领取计件工资而是领取周工资的工人受到怎样不公平的待遇。”（莱昂纳德·霍纳《工厂视察员报告。1859年4月30日》第8、9页）","language":"中文","translation":false},{"id":"capital-20-23","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[4] “工资有两种计算方法，或者是按劳动的持续时间来计算，或者是按劳动产品来计算。”（《政治经济学原理概论》1796年巴黎版第32页）这部匿名著作的作者是热·加尔涅。","language":"中文","translation":false},{"id":"capital-20-24","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[5] “交给他＜纺纱工人＞一定重量的棉花。经过一定时间，他必须交出一定重量的有一定精细程度的线或纱，并且根据这样提供的每一磅产品，得到一定的报酬。如果产品的质量不好，他就要受罚；如果产品数量少于一定时期应完成的最低限度，他就会被解雇，就会被更能干的工人所代替。”（尤尔《工厂哲学》1835年伦敦版第316、317页）","language":"中文","translation":false},{"id":"capital-20-25","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[6] “如果一件劳动产品要经过许多人的手，他们都要从中分取利润，而只有最后一双手才从事劳动，那末女工最后得到的报酬就微乎其微了。”（《童工调查委员会。第2号报告》第LXX页第424号）","language":"中文","translation":false},{"id":"capital-20-26","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[7] 甚至辩护士瓦茨也说：“如果在一项工作中所有被雇用的人都成为合同的参加者，每个人都量力而为，而不是一个人只顾自己的利益，而让他的同伴去从事过度劳动，那末这会是计件工资制的一个重大改进。”（约翰·瓦茨《工会和罢工，机器和合作社》1865年曼彻斯特版第53页）关于这个制度的害处，参看《童工调查委员会。第3号报告》第66页第22号；第n页第124号，第XI页第13、53、59号等等。","language":"中文","translation":false},{"id":"capital-20-27","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[8] 这种自然的结果往往人为地得到助长。例如，伦敦的机器制造业中惯用的诡计是：“资本家挑选一名特别强壮和灵巧的人做一定数量工人的头头。每到一个季度或其他期限就付给他以追加工资，条件是他拚命地干，以促使他的那些只领取普通工资的同伴也跟着拚命地干……这不用进一步解释就可以说明，为什么资本家要抱怨说，‘工联限制活动，限制卓越的技能和劳动力’。”（托·约·登宁《工联和罢工》1860年伦敦版第22、23页）因为作者本人就是工人和工联书记，人们也许会认为他的话过于夸张。但是请看一看，比如说，约·查·摩尔顿的“受人推崇的”农业百科全书吧，在“工人”一条里，这个方法是当作一种卓有成效的方法向租地农场主们推荐的。","language":"中文","translation":false},{"id":"capital-20-28","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[9] “所有拿计件工资的人……由于劳动超过法定界限而获得利益。这种从事额外时间的劳动的愿望，在织布女工和纺纱女工中间尤为常见。”（《工厂视察员报告。1858年4月30日》第9页）“这种计件工资制对资本家非常有利……它直接促使少年陶工在四、五年内从事过长的额外劳动，而得到的却是按低价支付的计件工资。这是引起陶工身体衰退的主要原因之一。”（《童工调查委员会。第1号报告》第XIII页）","language":"中文","translation":false},{"id":"capital-20-29","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[10] “如果在某个行业劳动是按单价计件支付报酬……那末各个工人的工资在数量上就会有很大差别……但就日工资来说，通常都有一个统一的数额……雇主和工人都把这个数额看作是该行业的中常工人的标准工资。”（托·约·登宁《工联和罢工》1860年伦敦版第17页）","language":"中文","translation":false},{"id":"capital-20-30","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[11] “手工业帮工的劳动，是按日或按件规定的……从事每种手艺的工人一天能完成多少工作，业主大体是心中有数的，所以，他们往往根据完成的工作量付给工人报酬；这样，即使没有监督，这些帮工为了切身利益也会尽量劳动。”（康替龙《试论一般商业的性质》1756年阿姆斯特丹版第185页和第202页。第1 版于1755年出版）可见，魁奈、詹姆斯·斯图亚特爵士和亚·斯密曾充分利用过的康替龙，在这里已经把计件工资看作只是计时工资的转化形式。在康替龙著作的法文版的扉页上注明系译自英文，但是该书的英文版《关于工商业、货币、金银、银行和外汇的分析》（菲力浦·康替龙著，选自一位已故的伦敦西蒂商人的手稿）不仅出版日期较晚（1759年），而且按其内容来说，也表明是后来的修订版。例如，在法文版中还没有提到休谟，而在英文版中，配第的名字几乎再也没有出现过。英文版在理论上的价值比较小，但是其中关于英国贸易、贵金属贸易等等的各种专门材料，却是法文版所没有的。因此，英文版扉页上注明的本书“主要选自一位已故的极有才能的绅士的手稿，加以改编”等字样，看来并不完全是当时所流行的虚构手法。","language":"中文","translation":false},{"id":"capital-20-31","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[12] “我们不是常常看到，有些工场雇用的工人远远超过工作上的实际需要吗？雇主雇用工人往往是为了期待某种无法预料的、有时甚至完全是想象的工作。既然雇主支付计件工资，所以他说他并不冒任何风险，因为一切时间上的损失完全由没有活干的人承担。”（昂·格里哥瓦尔《布鲁塞尔违警法庭上的印刷工人》1865年布鲁塞尔版第9页）","language":"中文","translation":false},{"id":"capital-20-32","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[13] 《评大不列颠的商业政策》1815年伦敦版第48页。","language":"中文","translation":false},{"id":"capital-20-33","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[14] 《大不列颠土地所有者和租地农场主的抗辩》1814年伦敦版第4、5页。","language":"中文","translation":false},{"id":"capital-20-34","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[15] 马尔萨斯《关于地租的本质和增长》1815年伦敦版〔第49页注〕 。","language":"中文","translation":false},{"id":"capital-20-35","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[16] “拿计件工资的工人，约占工厂工人总数的4/5。” （《工厂视察员报告。1858年4月30日》第9页）","language":"中文","translation":false},{"id":"capital-20-36","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[17] “他的纺纱机的生产力是准确计算好了的，靠这种机器完成的劳动的报酬，随着这种机器的生产力的提高而减少，虽然不是按照同一比例减少。”（尤尔《工厂哲学》第317页）可是尤尔自己又把后面那句辩护的话否定了。他承认，例如在走锭精纺机加长的时候，这种加长就会引起追加劳动。可见，劳动不是按照劳动生产率增长的程度程减少。其次，由于这种加长，机器的生产力提高了1／5。这样一来纺纱工完成的工作将不能按从前的工资率付给报酬，但是由于他的工资率不是减少1／5，于是这种改良也就提高了工人在每一定数量劳动小时中的货币工资”。但是，但是“上述情况需要有一个限制条件……纺纱工必须从自己的追加收入6便士中拿出一部分来付给追加的未成年的助手，此外，还有一部分成年工人被挤掉了”（同上，第320、321页），这一事实决不能说明工资有提高的趋势。","language":"中文","translation":false},{"id":"capital-20-37","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[18] 亨·福塞特《英国工人的经济状况》1865年剑桥和伦敦版第178页。","language":"中文","translation":false},{"id":"capital-20-38","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[19]在1861年10月26日伦敦的《旗帜报》上，载有一篇关于约翰，布莱特公司诉讼案的报告。该公司向罗契得尔治安法官“控告地毯业工联代表，说他们进行恐吓。布莱特公司的股东采用了一种新机器，用以前生产160码地毯所需的时间和劳动（！），现在可以生产240 码。工人对于企业主因投资于机器改良而获得的利润没有任何参与分配的权利。因此，公司老板提议把每码的工资从1.5便士降低到1便士，这样，工人以同量劳动所得的收入仍和以前完全一样。这只是名义上的降低。关于这件事，据说事先没有老实地告诉工人”。","language":"中文","translation":false},{"id":"capital-20-39","author":"马克思","title":"资本论·第一卷","location":"第十九章 计件工资","page":20,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/19.htm","text":"[20] “工联为了要保持工资，力图分享改良机器所带来的利润！（多么可怕啊！）他们因为劳动缩短而要求较高的工资……换句话说，他们企图对产业改良课税。” （《论工会》1834年伦敦新版第42页）","language":"中文","translation":false},{"id":"capital-21-1","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-21-2","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"第二十章 工资的国民差异","language":"中文","translation":false},{"id":"capital-21-3","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"在第十五章，我们考察了可以引起劳动力价值的绝对量或相对量（即同剩余价值相比较的量）发生变化的种种组合的情况，而另一方面，劳动力价格借以实现的生活资料量，又可以发生与这一价格的变动无关[1]或不同的运动。我们已经说过，只要把劳动力的价值或价格换成外在的工资形式，那里的一切规律就会转化为工资运动的规律。在这一运动中表现为各种变动着的组合的情况，对于不同的国家说来，会表现为国民工资的同时存在的差异。因此，在比较国民工资时，必须考虑到决定劳动力的价值量的变化的一切因素：自然的和历史地发展起来的首要的生活必需品的价格和范围，工人的教育费，妇女劳动和儿童劳动的作用，劳动生产率，劳动的外延量和内含量。即使作最肤浅的比较，首先也要求把不同国家同一行业的平均日工资化为长度相等的工作日。在对日工资作了这样换算以后，还必须把计时工资换算为计件工资，因为只有计件工资才是计算劳动生产率和劳动内含量的尺度。","language":"中文","translation":false},{"id":"capital-21-4","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"每一个国家都有一个中等的劳动强度，在这个强度以下的劳动，在生产一种商品时所耗费的时间要多于社会必要劳动时间，所以不能算作正常质量的劳动。在一个国家内，只有超过国民平均水平的强度，才会改变单纯以劳动的持续时间来计量的价值尺度。在以各个国家作为组成部分的世界市场上，情形就不同了。国家不同，劳动的中等强度也就不同；有的国家高些，有的国家低些。于是各国的平均数形成一个阶梯，它的计量单位是世界劳动的平均单位。因此，强度较大的国民劳动比强度较小的国民劳动，会在同一时间内生产出更多的价值，而这又表现为更多的货币。","language":"中文","translation":false},{"id":"capital-21-5","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"但是，价值规律在国际上的应用，还会由于下述情况而发生更大的变化：只要生产效率较高的国家没有因竞争而被迫把它们的商品的出售价格降低到和商品的价值相等的程度，生产效率较高的国民劳动在世界市场上也被算作强度较大的劳动。","language":"中文","translation":false},{"id":"capital-21-6","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"一个国家的资本主义生产越发达，那里的国民劳动的强度和生产率，就越超过国际水平[2]。因此，不同国家在同一劳动时间内所生产的同种商品的不同量，有不同的国际价值，从而表现为不同的价格，即表现为按各自的国际价值而不同的货币额。所以，货币的相对价值在资本主义生产方式较发达的国家里，比在资本主义生产方式不太发达的国家里要小。由此可以得出结论：名义工资，即表现为货币的劳动力的等价物，在前一种国家会比在后一种国家高；但这决不是说，实际工资即供工人支配的生活资料也是这样。","language":"中文","translation":false},{"id":"capital-21-7","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"但是即使撇开不同国家货币价值的这种相对的差异，也常常可以发现，日工资、周工资等等在前一种国家比在后一种国家高，而相对的劳动价格，即同剩余价值和产品价值相比较的劳动价格，在后一种国家却比在前一种国家高。[3]","language":"中文","translation":false},{"id":"capital-21-8","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"1833年工厂委员会委员约·伍·考威尔，曾对纺纱业作了仔细调查，并得出如下结论：","language":"中文","translation":false},{"id":"capital-21-9","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"“英国的工资虽然对于工人说来可能比大陆高，但是对于工厂主说来，实际上比大陆低。”（尤尔《工厂哲学》第314页） 英国工厂视察员亚历山大·雷德格雷夫在1866年10月31日的工厂报告中，根据同大陆各国比较的统计材料指出，大陆的劳动，尽管工资较低，劳动时间也长得多，但是同产品相比较，还是比英国贵。奥登堡一家棉纺织厂的一位英国经理说，那里的劳动时间是从早晨5点半到晚上8点，星期六也不例外，而当地工人即使在英国监工的监视下在这个时间内提供的产品，也比英国工人在10小时内提供的产品少，要是在德国监工的监视下，那还要少得多。工资比英国的低得多，在许多场合低50％，但是同机器相比的工人数却要比英国的多得多，在一些部门达5:3。雷德格雷夫先生提供了有关俄国棉纺织厂的非常详尽的材料。这些材料是一位不久前还在俄国工厂任职的英国经理提供给他的。在这块充满种种丑事的俄国土地上，英国工厂幼年时期的那些陈旧的骇人听闻的现象还非常盛行。管理人当然都是英国人，因为当地的俄国资本家不会管理工厂。尽管工人从事过度劳动，夜以继日地干活，而报酬却微乎其微，但是俄国的工业品仍然只有在禁止外国货的情况下才能勉强站住脚。最后，我还要举出雷德格雷夫先生的一张关于欧洲各国每个工厂和每个纺纱工人的平均纱锭数的比较表。雷德格雷夫先生本人指出，这些数字是他几年以前收集的，从那时以来，英国工厂的规模和每个工人的纱锭数都扩大了。但是他假定，所列举的大陆国家也有了同样程度的进步，因此这些数字材料仍然有比较的价值。","language":"中文","translation":false},{"id":"capital-21-10","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"英格兰………………………………………12600","language":"中文","translation":false},{"id":"capital-21-11","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"瑞 士……………………………………… 8000","language":"中文","translation":false},{"id":"capital-21-12","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"奥地利……………………………………… 7000","language":"中文","translation":false},{"id":"capital-21-13","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"萨克森……………………………………… 4500","language":"中文","translation":false},{"id":"capital-21-14","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"比利时……………………………………… 4000","language":"中文","translation":false},{"id":"capital-21-15","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"法 国……………………………………… 1500","language":"中文","translation":false},{"id":"capital-21-16","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"普鲁士……………………………………… 1500","language":"中文","translation":false},{"id":"capital-21-17","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"法 国……………………………………………14","language":"中文","translation":false},{"id":"capital-21-18","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"俄 国……………………………………………28","language":"中文","translation":false},{"id":"capital-21-19","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"普鲁士……………………………………………37","language":"中文","translation":false},{"id":"capital-21-20","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"巴伐利亚…………………………………………46","language":"中文","translation":false},{"id":"capital-21-21","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"奥地利……………………………………………49","language":"中文","translation":false},{"id":"capital-21-22","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"比利时……………………………………………50","language":"中文","translation":false},{"id":"capital-21-23","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"萨克森……………………………………………50","language":"中文","translation":false},{"id":"capital-21-24","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"德意志各小邦……………………………………55","language":"中文","translation":false},{"id":"capital-21-25","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"瑞 士……………………………………………55","language":"中文","translation":false},{"id":"capital-21-26","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"大不列颠…………………………………………74","language":"中文","translation":false},{"id":"capital-21-27","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"“这一比较对大不列颠是不利的，除了别的原因以外，特别是因为：在大不列颠，有许多工厂是兼营机器织布业和纺纱业的，而在计算时，连一个织工也没有除去。相反地，外国工厂大多只经营纺纱业。如果能够拿同样的情况进行精确比较，我就可以从我的管区中举出许多棉纺厂，在这些工厂里，只要一个男工和两个女助手就能看管几台共有2200个纱锭的走锭精纺机，每天生产出重220磅、长400的棉纱。”（散见《工厂视察员报告。1866年10月31日》第31—37页） 我们知道，英国的一些公司在东欧和亚洲承包过铁路建筑工程，它们除了使用当地工人外，还使用了一定数量的英国工人。它们迫于实际的需要，就不得不考虑劳动强度的国民差异，但是这并没有使它们受到任何损失。它们根据经验知道，即使工资水平多少同中等劳动强度是相符合的，但是劳动的相对价格（同产品相比较的价格）通常是按相反方向变动的。","language":"中文","translation":false},{"id":"capital-21-28","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"亨·凯里在他的最早的经济学著作之一《论工资率》[4]中企图证明，不同的国民工资同各国工作日的生产率水平成正比，以便从这种国际的对比中得出结论说，工资总是随着劳动生产率而升降。即使凯里没有象往常那样把毫无批判地、表面地拼凑起来的统计材料杂乱无章地罗列在一起，而是论证了自己的前提，我们关于剩余价值生产的全部分析还是证明，他的这个推论是荒谬的。最妙的是，他并不认为，事物实际上是同理论上所说的一样。正是国家的干涉歪曲了这种自然的经济关系。因此，在计算国民工资时，似乎必须把工资中以税收的形式归国家所有的那一部分看作是归工人自身所有的。凯里先生难道不应当进一步想一想：这种“国家费用”不也是资本主义发展的“自然果实”吗？这样的推论对这样的人说来是十分相称的：他起初把资本主义生产关系说成是永恒的自然规律和理性规律，并且说这些规律的自由的、和谐的作用只是由于国家干涉才遭到破坏，可是后来他发现，英国对世界市场的恶魔般的影响（似乎这种影响不是从资本主义生产的自然规律中产生的），使国家干涉即通过国家来保护那些“自然规律和理性规律”成为必要，换句话说，就是使实行保护关税制度成为必要。其次他发现，李嘉图等人用来表述现存社会的对立和矛盾的定理，并不是现实经济运动的观念的产物，相反地，英国和其他地方的资本主义生产中的现实对立倒是李嘉图等人的理论的结果！最后，他发现，破坏资本主义生产方式固有的优美与和谐的，归根到底是贸易。再前进一步，他也许会发现，资本主义生产的唯一祸害就是资本本身。只有一个如此惊人地缺乏批判能力和如此假装博学的人（尽管他相信保护关税的异端邪说），才配成为一位名叫巴师夏的人和现代自由贸易派其他一切乐观主义者的和谐智慧的秘密源泉。","language":"中文","translation":false},{"id":"capital-21-29","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"[1] “因为用工资能买到更多更便宜的物品，就说工资＜这里指工资的货币表现＞提高了，这是不正确的。”（大卫·布坎南对他出版的亚·斯密《国富论》所加的注。1814年版第1卷第417页）","language":"中文","translation":false},{"id":"capital-21-30","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"[2] 我们将在别处研究，哪些和生产率有关的情况能够在个别生产部门使这一规律发生变化。","language":"中文","translation":false},{"id":"capital-21-31","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"[3] 詹姆斯·安德森在同亚·斯密论战时说过：“同样应当指出，虽然在农产品特别是谷物便宜的贫国中，劳动价格表面上通常较低，其实在那里，劳动价格实际上大都比其他国家高。因为工人每日获得的工资，虽然是劳动的表面价格，但是并不代表劳动的实际价格。实际价格是已完成的一定量劳动使企业主实际上花去的费用。从这个观点看来，劳动在富国几乎总是比在贫国便宜，虽然谷物和其他生活资料的价格在贫国通常比在富国低得多……按日计酬的劳动在苏格兰比在英格兰贱得多……而按件计酬的劳动一般在英格兰较贱。”（詹姆斯·安德森《论激励民族创业精神的手段》1777年爱丁堡版第350、351页）——相反地，工资的低廉又引起劳动的昂贵。“劳动在爱尔兰比在英格兰贵……因为那里的工资低得多。”（《皇家铁道委员会记录》1867年版第2074号）","language":"中文","translation":false},{"id":"capital-21-32","author":"马克思","title":"资本论·第一卷","location":"第二十章 工资的国民差异","page":21,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/20.htm","text":"[4] 《论工资率：世界劳动人民状况差别的原因的探讨》1835年费拉得尔菲亚版。","language":"中文","translation":false},{"id":"capital-22-1","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-22-2","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"一个货币额转化为生产资料和劳动力，这是要执行资本职能的价值量所完成的第一个运动。这个运动是在市场上，在流通领域内进行的。运动的第二阶段，生产过程，在生产资料转化为商品时就告结束，这些商品的价值大于其组成部分的价值，也就是包含原预付资本加上剩余价值。接着，这些商品必须再投入流通领域。必须出售这些商品，把它们的价值实现在货币上，把这些货币又重新转化为资本，这样周而复始地不断进行。这种不断地通过同一些连续阶段的循环，就形成资本流通。","language":"中文","translation":false},{"id":"capital-22-3","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"积累的第一个条件，是资本家能够卖掉自己的商品，并把由此得到的绝大部分货币再转化为资本。下面假定资本是按正常的方式完成自己的流通过程的。对这一过程的详细分析要在第二卷里进行。","language":"中文","translation":false},{"id":"capital-22-4","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"生产剩余价值即直接从工人身上榨取无酬劳动并把它固定在商品上的资本家，是剩余价值的第一个占有者，但决不是剩余价值的最后所有者。以后他还必须同在整个社会生产中执行其他职能的资本家，同土地所有者等等，共同瓜分剩余价值。因此，剩余价值分为各个不同的部分。它的各部分归不同类的人所有，并具有不同的、互相独立的形式，如利润、利息、商业利润、地租等等。剩余价值的这些转化形式要在第三卷里才来研究。","language":"中文","translation":false},{"id":"capital-22-5","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"因此，我们在这里一方面假定，生产商品的资本家按照商品的价值出售商品，而不去进一步研究资本家如何回到商品市场：既不研究资本在流通领域里所采取的那些新形式，也不研究这些形式所包含的再生产的具体条件。另一方面，我们把资本主义的生产者当作全部剩余价值的所有者，或者，不妨把他当作所有参加分赃的人的代表。总之，我们首先抽象地来考察积累，也就是把积累只看作直接生产过程的一个要素。","language":"中文","translation":false},{"id":"capital-22-6","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"此外，只要积累在进行，资本家就是在出售所生产的商品，并把出售商品所取得的货币再转化为资本。其次，剩余价值分为各个不同的部分，丝毫也不会改变它的性质以及使它成为积累要素的那些必要条件。不管资本主义生产者自己握有的或分给别人的剩余价值的比例如何，他总是最先占有剩余价值。因此，我们在说明积累时假定的情况，也就是积累进行中实际发生的情况。另一方面，剩余价值的分割和流通的中介运动模糊了积累过程的简单的基本形式。因此，对积累过程的纯粹的分析，就要求我们暂时抛开掩盖它的机构的内部作用的一切现象。","language":"中文","translation":false},{"id":"capital-22-7","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"不管生产过程的社会形式怎样，它必须是连续不断的，或者说，必须周而复始地经过同样一些阶段。一个社会不能停止消费，同样，它也不能停止生产。因此，每一个社会生产过程，从经常的联系和它不断更新来看，同时也就是再生产过程。","language":"中文","translation":false},{"id":"capital-22-8","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"生产的条件同时也就是再生产的条件。任何一个社会，如果不是不断地把它的一部分产品再转化为生产资料或新生产的要素，就不能不断地生产，即再生产。在其他条件不变的情况下，社会在例如一年里所消费的生产资料，即劳动资料、原料和辅助材料，只有在实物形式上为数量相等的新物品所替换，社会才能在原有的规模上再生产或保持自己的财富，这些新物品要从年产品总量中分离出来，重新并入生产过程。因此，一定量的年产品是属于生产的。这部分本来供生产消费之用的产品，就采取的实物形式来说，大多数不适于个人消费。","language":"中文","translation":false},{"id":"capital-22-9","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"生产具有资本主义的形式，再生产也就具有同样的形式。在资本主义生产方式下，劳动过程只表现为价值增殖过程的手段，同样，再生产也只表现为把预付价值作为资本即作为自行增殖的价值来再生产的手段。某个人之所以扮演资本家的经济角色，只是由于他的货币不断地执行资本的职能。比如说，如果100镑预付货币额在今年转化为资本，生产了20镑剩余价值，那末，在明年及以后各年它必须重复同样的活动。剩余价值作为资本价值的周期增加额或处在过程中的资本的周期果实，取得了来源于资本的收入的形式。","language":"中文","translation":false},{"id":"capital-22-10","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"如果这种收入只是充当资本家的消费基金，或者说，它周期地获得，也周期地消费掉，那末，在其他条件不变的情况下，这就是简单再生产。虽然简单再生产只是生产过程在原来规模上的重复，但是这种重复或连续性，赋予这个过程以某些新的特征，或者不如说，消除它仅仅作为孤立过程所具有的虚假特征。","language":"中文","translation":false},{"id":"capital-22-11","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"生产过程是以购买一定时间的劳动力作为开端的，每当劳动的售卖期限届满，从而一定的生产期间（如一个星期，一个月等等）已经过去，这种开端就又更新。但是，工人只是在自己的劳动力发挥了作用，把它的价值和剩余价值实现在商品上以后，才得到报酬。因此，工人既生产了我们暂时只看作资本家的消费基金的剩余价值，也生产了付给他自己报酬的基金即可变资本，而后者是在它以工资形式流回到工人手里之前生产的，只有当他不断地再生产这种基金的时候，他才被雇用。由此就产生了在第十六章里提到的经济学家的公式II，这个公式把工资表现为产品本身的一部分。这就是工人自己不断再生产的产品中不断以工资形式流回到工人手里的那一部分。当然，资本家用货币把这个商品价值支付给工人。但这些货币不过是劳动产品的转化形式。当工人把一部分生产资料转化为产品的时候，他以前的一部分产品就再转化为货币。工人今天的劳动或下半年的劳动是用他上星期的劳动或上半年的劳动来支付的。只要我们不是考察单个资本家和单个工人，而是考察资本家阶级和工人阶级，货币形式所造成的错觉就会立即消失。资本家阶级不断地以货币形式发给工人阶级凭据，让他们用来领取由工人阶级生产而为资本家阶级所占有的产品中的一部分。工人也不断地把这些凭据还给资本家阶级，以便从资本家阶级那里取得他自己的产品中属于他自己的那一部分。产品的商品形式和商品的货币形式掩饰了这种交易。","language":"中文","translation":false},{"id":"capital-22-12","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"因此，可变资本不过是劳动者为维持和再生产自己所必需的生活资料基金或劳动基金的一种特殊的历史的表现形式；这种基金在一切社会生产制度下都始终必须由劳动者本身来生产和再生产。劳动基金所以不断以工人劳动的支付手段的形式流回到工人手里，只是因为工人自己的产品不断以资本的形式离开工人。但是劳动基金的这种表现形式丝毫没有改变这样一个事实：资本家把工人自己的物化劳动预付给工人。以徭役农民为例。比如说，他每周3天用自己的生产资料在自己的耕地上劳动，其余3天在主人的田庄服徭役。他不断再生产自己的劳动基金，而这一劳动基金对他来说，从来也没有采取第三者为换取他的劳动而预付的支付手段的形式。然而，他的无酬的强制的劳动也从来没有采取自愿的和有酬的劳动的形式。一旦地主把徭役农民的耕地、耕畜、种子，一句话，把他的生产资料都攫为己有，那末，徭役农民从此以后就不得不把自己的劳动力出卖给地主了。在其他条件不变的情况下，他现在也和过去一样，每周劳动6天，3天为自己，3天为现在变为雇主的过去的地主。他现在也和过去一样，要把这些生产资料作为生产资料来消费，把它们的价值转移到产品上。现在也和过去一样，一定部分的产品仍要进入再生产。但是，既然徭役劳动采取了雇佣劳动的形式，徭役农民和过去一样所生产和再生产的劳动基金也就采取了由地主预付给徭役农民的资本的形式。资产阶级经济学家由于头脑狭隘不能区别表现形式和它所表现的东西，他们无视这样一个事实：甚至今天，劳动基金在地球上也只是例外地表现为资本的形式。","language":"中文","translation":false},{"id":"capital-22-13","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"诚然，只有从生产过程的不断更新来考察资本主义生产过程，可变资本才会失去从资本家私人基金中预付的价值的性质。但是，这一过程总要从某地某时开始。因此，从我们上面所持的观点来看，下面的情况是可能的：资本家曾经一度依靠某种与别人的无酬劳动无关的原始积累而成为货币所有者，因而能够作为劳动力的购买者进入市场。然而，资本主义生产过程的单纯连续或者说简单再生产，还会引起其他一些特殊的变化，这些变化不仅影响资本的可变部分，而且影响整个资本。","language":"中文","translation":false},{"id":"capital-22-14","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"如果1000镑资本周期地（例如每年）创造剩余价值200镑，而这些剩余价值每年又都被消费掉，那就很清楚，同一过程重复五年以后，所消费的剩余价值量＝5×200，也就是等于原预付资本价值1000镑。如果年剩余价值只是部分地被消费掉，例如只消费掉一半，那末，在生产过程重复十年以后，也会产生同样的结果，因为10×100＝1000。总之，预付资本价值除以每年所消费的剩余价值，就可以求出，经过若干年或者说经过若干个再生产期间，原预付资本就会被资本家消费掉，因而消失了。资本家认为，他所消费的是别人无酬劳动的产品即剩余价值，而保存了原资本价值，但这种看法绝对不能改变事实。经过若干年以后，资本家占有的资本价值就等于他在这若干年不付等价物而占有的剩余价值额，而他所消费的价值额就等于原有资本价值。诚然，他手中握有一笔数量没有改变的资本，而且其中一部分如厂房、机器等等，在他开始经营的时候就已经存在。但是，这里问题在于资本的价值，而不在于资本的物质组成部分。如果某人借了等于自己全部财产的价值的债务而把全部财产耗尽，那末他的全部财产正好只代表他的全部债务。同样，如果资本家把自己预付资本的等价物消费掉，那末这些资本的价值不过只代表他无偿占有的剩余价值的总额。他的原有资本的任何一个价值原子都不复存在了。","language":"中文","translation":false},{"id":"capital-22-15","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"因此，撇开一切积累不说，生产过程的单纯连续或者说简单再生产，经过一个或长或短的时期以后，必然会使任何资本都转化为积累的资本或资本化的剩余价值。即使资本在进入生产过程的时候是资本使用者本人挣得的财产，它迟早也要成为不付等价物而被占有的价值，成为别人无酬劳动的货币形式或其他形式的化身。","language":"中文","translation":false},{"id":"capital-22-16","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"我们在第四章已经看到，要使货币转化为资本，只有商品生产和商品流通的存在还是不够的。为此首先必须有下列双方作为买者和卖者相对立：一方是价值或货币的所有者，另一方是创造价值的实体的所有者；一方是生产资料和生活资料的所有者，另一方是除了劳动力以外什么也没有的所有者。所以，劳动产品和劳动本身的分离，客观劳动条件和主观劳动力的分离，是资本主义生产过程事实上的基础或起点。","language":"中文","translation":false},{"id":"capital-22-17","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"但是，起初仅仅是起点的东西，后来通过过程的单纯连续，即通过简单再生产，就作为资本主义生产本身的结果而不断重新生产出来，并且永久化了。一方面，生产过程不断地把物质财富转化为资本，转化为资本家的价值增殖手段和消费品。另一方面，工人不断地象进入生产过程时那样又走出这个过程——是财富的人身源泉，但被剥夺了为自己实现这种财富的一切手段。因为在他进入过程以前，他自己的劳动就同他相异化而为资本家所占有，并入资本中了，所以在过程中这种劳动不断物化在别人产品中。因为生产过程同时就是资本家消费劳动力的过程，所以工人的产品不仅不断地转化为商品，而且也转化为资本，转化为吸收创造价值的力的价值，转化为购买人身的生活资料，转化为使用生产者的生产资料。可见，工人本身不断地把客观财富当作资本，当作同他相异化的、统治他和剥削他的权力来生产，而资本家同样不断地把劳动力当作主观的、同它本身物化的和实现的资料相分离的、抽象的、只存在于工人身体中的财富源泉来生产，一句话，就是把工人当作雇佣工人来生产。〔注：“租地农场主荒谬地断言他维持穷人生活。实际上，穷人被维持在贫困生活中。”（《最近济贫税增加的理由，或劳动价格和粮食价格的比较研究》1777年伦敦版31页）〕工人的这种不断再生产或永久化是资本主义生产的必不可少的条件。","language":"中文","translation":false},{"id":"capital-22-18","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"工人的消费有两种。在生产本身中他通过自己的劳动消费生产资料，并把生产资料转化为价值高于预付资本价值的产品。这就是他的生产消费。同时这也是购买他的劳动力的资本家对他的劳动力的消费。另一方面，工人把购买他的劳动力而支付给他的货币用于生活资料：这是他的个人消费。可见，工人的生产消费和个人消费是完全不同的。在前一种情况下，工人起资本动力的作用，属于资本家；在后一种情况下，他属于自己，在生产过程以外执行生活职能。前者的结果是资本家的生存，后者的结果是工人自己的生存。","language":"中文","translation":false},{"id":"capital-22-19","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"在考察“工作日”等等时，有些场合已经表明：工人往往被迫把自己的个人消费变成生产过程的纯粹附带的事情。在这种情况下，他给自己添加生活资料，是为了维持自己劳动力的运转，正象给蒸汽机添煤加水，给机轮上油一样。在这里，他的消费资料只是一种生产资料的消费资料，他的个人消费是直接生产的消费。但是，这表现为一种与资本主义生产过程的本质无关的无谓消耗。","language":"中文","translation":false},{"id":"capital-22-20","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"只要我们考察的不是单个资本家和单个工人，而是资本家阶级和工人阶级，不是孤立的商品生产过程，而是在社会范围内不断进行的资本主义生产过程，那情况就不同了。当资本家把自己一部分资本变成劳动力时，他就由此增殖了自己的总资本。他一举两得。他不仅从他由工人那里取得的东西中，而且从他给工人的东西中获取利益。用来交换劳动力的资本转化为生活资料，这种生活资料的消费是为了再生产现有工人的肌肉、神经、骨骼、脑髓和生出新的工人。因此，工人阶级的个人消费，在绝对必需的限度内，只是把资本用来交换劳动力的生活资料再转化为可供资本重新剥削的劳动力。这种消费是资本家最不可少的生产资料即工人本身的生产和再生产。可见，工人的个人消费，不论在工场、工厂等以内或以外，在劳动过程以内或以外进行，都是资本生产和再生产的一个要素，正象擦洗机器，不论在劳动过程中或劳动过程的一定间歇进行，总是生产和再生产的一个要素一样。虽然工人实现自己的个人消费是为自己而不是为资本家，但事情并不因此有任何变化。役畜的消费并不因为役畜自己享受食物而不成为生产过程的必要的要素。工人阶级的不断维持和再生产始终是资本再生产的条件。资本家可以放心地让工人维持自己和繁殖后代的本能去实现这个条件。他所操心的只是把工人的个人消费尽量限制在必要的范围之内，这种做法同南美洲那种强迫工人吃营养较多的食物，不吃营养较少的食物的粗暴行为，真有天壤之别。","language":"中文","translation":false},{"id":"capital-22-21","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"因此，资本家及其思想家即政治经济学家认为，只有使工人阶级永久化所必需的，也就是为了使资本能消费劳动力所实际必要的那部分工人个人消费，才是生产消费。除此以外，工人为了自己享受而消费的一切都是非生产消费。假使资本积累引起工资的提高，从而使工人的消费资料增加，但资本并没有消费更多的劳动力，那末追加资本就会非生产地消费掉。〔注：“如果劳动价格大大提高，以致增加资本也无法使用更多的劳动，那我就要说，这样增加的资本就会非生产地消费掉。”（李嘉图《政治经济学和赋税原理》1821年伦敦第3版第163页）〕实际上，工人的个人消费对他自己来说是非生产的，因为这种消费仅仅是再生产贫困的个人；而对资本家和国家来说是生产的，因为它生产了创造别人财富的力量。","language":"中文","translation":false},{"id":"capital-22-22","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"因此，从社会角度来看，工人阶级，即使在直接劳动过程以外，也同死的劳动工具一样是资本的附属物。甚至工人的个人消费，在一定限度内，也不过是资本再生产过程的一个要素。不过，这个过程关心的是，在它不断使工人的劳动产品从工人这一极移到资本那一极时，不让这种有自我意识的生产工具跑掉。工人的个人消费一方面保证他们维持自己和再生产自己，另一方面通过生活资料的耗费来保证他们不断重新出现在劳动市场上。罗马的奴隶是由锁链，雇佣工人则由看不见的线系在自己的所有者手里。他这种独立的假象是由雇主的经常更换以及契约的法律虚构来保持的。","language":"中文","translation":false},{"id":"capital-22-23","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"从前，资本在它认为必要的时候，就通过强制的法律来实现对自由工人的所有权。例如在1815年以前，英国曾以严厉的刑罚来禁止机器工人向国外迁移。","language":"中文","translation":false},{"id":"capital-22-24","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"工人阶级的再生产，同时也包括技能的世代传授和积累。资本家竭力把这种熟练的工人阶级的存在算作属于自己的生产条件，并且实际上把这种熟练的工人阶级看作自己的可变资本的实际存在，每当危机使这种工人阶级有丧失的危险时，这一点就会明显地表现出来。大家知道，美国的南北战争以及随之而来的棉荒，把郎卡郡等地的大部分棉纺织业工人抛向街头。于是从工人阶级自身以及其他社会阶层中发出呼声，要求通过国家援助或国民的自愿捐款把“多余的人”迁往英国的殖民地或美国。当时《泰晤士报》（1863年3月24日）发表了曼彻斯特前任商会会长艾德蒙·波特尔的一封信。这封信在下院被恰当地称为“工厂主宣言”。我们在这里举出几处有代表性的地方，这些地方毫无掩饰地表明了资本对劳动力的所有权。","language":"中文","translation":false},{"id":"capital-22-25","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"“可能有人对棉纺织业工人说，他们的劳动供给太多了……也许应当减少三分之一，这样才能保障对其余三分之二的正常需求…… 社会舆论坚决要求移民…… 雇主〈即棉纺织厂主〉不愿意看到他的劳动供给转移出去；他会想，这样做既不公正又不正确…… 如果靠公共基金实行移民，他就有权提出意见，也许有权提出抗议。” 这个波特尔接着谈到，棉纺织业是如何有用，如何“无疑地吸收了爱尔兰和英国农业区的多余人口”，它的规模是如何的大，如何在1860年占英国输出总额的5/13，它如何经过几年后，会由于市场特别是印度市场的扩大，并由于“按每磅6便士输入足够数量的棉花”而再行扩展。他继续说：","language":"中文","translation":false},{"id":"capital-22-26","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"“时间（一年两年或许是三年）会生产出必要的数量…… 于是我要提出一个问题：这种工业值得维持吗？这种机器〈指活的劳动机器〉值得费力去维护吗？想抛弃这种机器不是最大的愚蠢吗？我认为是这样。我承认，工人不是财产，不是郎卡郡和雇主们的财产，然而他们是二者的力量；他们是有智慧的和受过训练的力量，不是在一代之内就能替换的；相反地，其他机器即工人进行操作的机器，很大一部分可以在12个月内加以替换和改良而获得利益。〔注：人们会记得，通常在必须降低工资的情况下，同一资本就唱完全不同的调子。这时“主人”异口同声地说（见第13章）：“工厂工人们应当牢牢记住，他们的劳动实际上是一种极低级的熟练劳动；没有一种劳动比它更容易学会，按质量来说比它报酬更高；没有一种劳动能通过对最无经验的人进行短期训练而在这样短的时间这样大量地得到。在生产事务中，主人的机器<现在我们听到，这种机器可以在12个月内加以替换和改良而获得利益>所起的作用，实际上比工人的劳动和技巧<现在我们听到，这种劳动和技巧在30年中无法替换>所起的作用重要得多，因为工人的劳动和技巧6个月就可以教完，并且任何一个雇农都可以学会”。〕如果鼓励或允许〈！〉劳动力迁往国外，那资本家怎么办呢？”","language":"中文","translation":false},{"id":"capital-22-27","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"这种发自内心的叫喊使人想起了宫廷侍卫长卡尔勃。","language":"中文","translation":false},{"id":"capital-22-28","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"“…… 抛掉工人的精华，固定资本就会大大贬值，流动资本就会经不起同劣等劳动供应不足的斗争…… 有人对我们说，工人自己希望迁往国外。工人要这样做，那是很自然的…… 抛掉棉纺织业的劳动力，把支付给他们的工资比如降低1/3，或5百万，使棉纺织业生产缩减，这样一来，工人上面的一个阶级即小店主怎么办呢？地租及小屋租金怎么办呢？……小租地农场主、比较优裕的房主和土地所有者怎么办呢？输出国家最优秀的工厂工人，降低它的那部分生产效率最高的资本和财富的价值，以使这个国家贫弱，请问，对国内一切阶级说来，还有什么计划会比这种计划更具有自杀性呢？”“我建议两三年内分批发行5—6百万公债；这笔钱由棉纺织工业区济贫所所属的特别委员掌管，依照特别法律的规定来使用，并实行一定的强制劳动来保持受救济者的道德标准…… 放弃自己最优秀的工人，并且由于实行大规模的造成国内空虚的移民，以及把全区的资本和价值弄得一干二净，而使剩下的工人道德败坏，意志消沉，对土地所有者或雇主来说，还有什么比这更坏的事情吗？”","language":"中文","translation":false},{"id":"capital-22-29","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"波特尔这位棉纺织厂主选中的喉舌，把“机器”分为两类，这两类都属于资本家。一类在资本家的工厂里，另一类在夜间和星期日住在厂外的小屋中。一类是死机器，另一类是活机器。死机器不仅逐日损坏和贬值，而且由于技术不断进步，它的现有数量中的大部分也变得陈旧了，以致在几个月之内可以用新机器来替换而获得利益。活机器则相反，它延续的时间越久，历代的技能积累得越多，就越好。《泰晤士报》在回答这位大厂主时写道：","language":"中文","translation":false},{"id":"capital-22-30","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"“艾·波特尔先生深深感到棉纺织企业主的异乎寻常的绝对的重要性，以致为了维持这个阶级并且使他们的行业永世长存，他准备把50万工人强行关进庞大的有道德的贫民习艺所。波特尔先生问道，这种工业值得维持吗？我们回答说，当然值得，应当用一切正直的手段来维持。波特尔先生又问，这种机器值得费力去维护吗？这里我们就犹豫了。波特尔先生指的机器是人这种机器，因为他断言他并不打算把这种机器当作绝对的财产。我们必须承认，维护人这种机器，也就是把他们关起来并且给他们上油，直到需要他们的时候为止，我们认为这是‘不值得费力的’，甚至是不可能的。人这种机器有一种特性：尽管你上油擦洗，不使用就会生锈。此外，正如我们已经看见的，人这种机器能自己放出蒸汽，发生爆炸，在我们的大城市里疯狂地胡闹。正如波特尔先生所说，再生产工人可能需要更长的时间，但是只要我们手里有机械师和货币，我们总是能够找到克勤克俭、吃苦耐劳的人，从这些人中间可以造就出超过我们任何时候所能需要的工厂工长…… 波特尔先生谈到过一年、两年或三年工业又会活跃起来，要求我们不鼓励或不允许劳动力迁往国外！他说工人希望迁移国外是很自然的，但是他认为，国家必须不顾他们的要求，把这50万工人和他们的70万家属关闭在棉纺织工业区里，并且——这是必然会得出的——国家必须用暴力压制他们的不满，用救济维持他们的生存；所有这一切都是由于考虑到有朝一日棉纺织企业主可能再需要他们…… 现在已经是这个岛国强大的舆论行动起来，从那些想把劳动力同煤、铁、棉花一样看待的人的手里拯救出‘这种劳动力’的时候了。”","language":"中文","translation":false},{"id":"capital-22-31","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"《泰晤士报》的文章只不过是一种益智游戏。“强大的舆论”实际上同波特尔先生的意见一样，认为工厂工人是工厂的活动的附属物。工人被制止迁往国外。他们被关进棉纺织工业区的“有道德的贫民习艺所”，他们仍然是“郎卡郡棉纺织企业主的力量”。","language":"中文","translation":false},{"id":"capital-22-32","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"因此，资本主义生产过程在本身的进行中，再生产出劳动力和劳动条件的分离。这样，它就再生产出剥削工人的条件，并使之永久化。它不断迫使工人为了生活而出卖自己的劳动力，同时不断使资本家能够为了发财致富而购买劳动力。现在资本家和工人作为买者和卖者在商品市场上相对立，已经不再是偶然的事情了。过程本身必定把工人不断地当作自己劳动力的卖者投回商品市场，同时又把工人自己的产品不断地变成资本家的购买手段。实际上，工人在把自己出卖给资本家以前就已经属于资本了。工人经济上的隶属地位，是由他的卖身行为的周期更新、雇主的更换和劳动的市场价格的变动造成的，同时又被这些事实所掩盖。","language":"中文","translation":false},{"id":"capital-22-33","author":"马克思","title":"资本论·第一卷","location":"第二十一章 简单再生产","page":22,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/21.htm","text":"可见，把资本主义生产过程联系起来考察，或作为再生产过程来考察，它不仅生产商品，不仅生产剩余价值，而且还生产和再生产资本关系本身：一方面是资本家，另一方面是雇佣工人。","language":"中文","translation":false},{"id":"capital-23-1","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-23-2","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"第二十二章 剩余价值转化为资本","language":"中文","translation":false},{"id":"capital-23-3","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"1、规模扩大的资本主义生产过程。商品生产所有权规律转变为资本主义占有规律","language":"中文","translation":false},{"id":"capital-23-4","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"我们以前考察了剩余价值怎样从资本产生，现在我们考察资本怎样从剩余价值产生。把剩余价值当作资本使用，或者说，把剩余价值再转化为资本，叫做资本积累。","language":"中文","translation":false},{"id":"capital-23-5","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"首先，我们从单个资本家的角度来考察这个过程。例如，一个纱厂主预付了10000镑的资本，其中4/5用于棉花、机器等等，其余1/5用于工资。假定他每年生产棉纱240000磅，价值为12000镑。如果剩余价值率为100％，剩余价值就包含在40000磅棉纱的剩余产品或纯产品中，它占总产品的1/6，价值2000镑。这2000镑价值将由出售而实现。2000镑的价值额就是2000镑的价值额。从这笔货币上既嗅不出也看不出它是剩余价值。一个价值是剩余价值这一点，表明这一价值怎样来到它的所有者手里，但是丝毫也不能改变价值或货币的本性。","language":"中文","translation":false},{"id":"capital-23-6","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"因此，纱厂主要把他新增加的2000镑货币变成资本，在其他条件不变的情况下，就得预付其中的4/5去购买棉花等物，1/5去购买新的纺纱工人，这些纺纱工人会在市场上找到生活资料，而生活资料的价值已由纱厂主预付给他们了。于是，这2000镑新资本就在纺纱厂中执行职能，并又带来400镑的剩余价值。","language":"中文","translation":false},{"id":"capital-23-7","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"资本价值最初是以货币形式预付的；相反，剩余价值一开始就作为总产品的一定部分的价值而存在。如果总产品卖出去，变成货币，那末资本价值就又取得了自己最初的形式，而剩余价值则改变了自己最初的存在方式。但是从这时候起，资本价值和剩余价值二者都成了货币额，并且以完全相同的方式重新转化为资本。资本家把这二者都用来购买商品，以便能够重新开始制造自己的产品，而这次是在扩大规模上进行的。但是，他要买到这些商品，就必须在市场上找到这些商品。","language":"中文","translation":false},{"id":"capital-23-8","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"他自己的棉纱所以能流通，只是因为他把自己的年产品投入市场，正象其他所有的资本家也把自己的商品投入市场一样。但这些商品在进入市场以前，就已经存在于年生产基金中了，也就是说，已经存在于由各个单个资本的总额或社会总资本在一年中转化成的各种物品的总额中了，而每个资本家只占有其中的一个相应部分。市场上的过程只是实现年生产的各个组成部分的交换，使它们从一个人的手里转到另一人的手里，但它既不能增大年生产的总额，也不能改变产品的本性。可见，全部年产品能有什么用途，取决于它本身的构成，而绝不取决于流通。","language":"中文","translation":false},{"id":"capital-23-9","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"首先，年生产必须提供一切物品（使用价值）以补偿一年中所消费的资本的物质组成部分。扣除这一部分以后，剩下的就是包含剩余价值的纯产品或剩余产品。但这种剩余产品究竟是由什么 构成的呢？也许是那些供资本家阶级满足需要和欲望的物品，即加入他们的消费基金的物品吧？如果真是这样，剩余价值就会被挥霍尽，这样就只能进行简单再生产了。","language":"中文","translation":false},{"id":"capital-23-10","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"要积累，就必须把一部分剩余产品转化为资本。但是，如果不是出现了奇迹，能够转化为资本的，只是在劳动过程中可使用的物品，即生产资料，以及工人用以维持自身的物品，即生活资料。所以，一部分年剩余劳动必须用来制造追加的生产资料和生活资料，它们要超过补偿预付资本所需的数量。总之，剩余价值所以能转化为资本，只是因为剩余产品（它的价值就是剩余价值）已经包含了新资本的物质组成部分。〔注：这里我们把出口贸易撇开不说。一个国家借助出口贸易可以使奢侈品转化为生产资料或生活资料，或者相反。为了在纯粹的状态下对我们的研究对象进行考察，避免次要情况的干扰，我们在这里必须把整个贸易世界看作一个国家，并且假定资本主义生产已经到处确立并占据了一切产业部门。〕","language":"中文","translation":false},{"id":"capital-23-11","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"但要使这些组成部分真正执行资本的职能，资本家阶级还需要追加劳动。如果从外延方面或内含方面都不能增加对就业工人的剥削，那就必须雇用追加的劳动力。而资本主义生产的机构也已经考虑到了这一点，因为它把工人阶级当作靠工资过活的阶级再生产出来，让他们的通常的工资不仅够用来维持自己，而且还够用来进行繁殖。资本只要把工人阶级每年向它提供的各种年龄的追加劳动力同已经包含在年产品中的追加生产资料合并起来，剩余价值向资本的转化就完成了。具体说来，积累就是资本的规模不断扩大的再生产。简单再生产的循环改变了，按照西斯蒙第的说法，变成螺旋形了。","language":"中文","translation":false},{"id":"capital-23-12","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"现在我们再回过头来谈我们所举的例子。这是父亲生儿子，儿子生孙子等等的老故事。10000镑原有资本带来2000镑剩余价值，这些剩余价值资本化了；新的2000镑资本又带来400镑剩余价值；这个剩余价值又资本化了，于是变成了第二个追加资本，又带来80镑新的剩余价值，依此类推。","language":"中文","translation":false},{"id":"capital-23-13","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"我们在这里撇开资本家自己所消费的那部分剩余价值不说。追加资本是同原有资本合并，还是同它分开而独立增殖；是由积累它的同一资本家使用，还是转入别的资本家手中，这些我们暂时也不必过问。只是我们不应当忘记，在新形成的资本旁边，原有资本仍在继续再生产自己，并生产剩余价值，而且每一个积累起来的资本就它同自己所创造的追加资本的关系来说，也是这样。","language":"中文","translation":false},{"id":"capital-23-14","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"原有资本是由预付10000镑而形成的。它的所有者是从哪里得到它的呢？它是通过所有者本人的劳动和他的祖先的劳动得到的！——政治经济学的代表人物一致这样回答我们，而他们的这种假定好象真的是唯一符合商品生产的规律的。","language":"中文","translation":false},{"id":"capital-23-15","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"2000镑追加资本的情况就完全不同了。它的产生过程我们是一清二楚的。这是资本化了的剩余价值。它一开始就没有一个价值原子不是由别人的无酬劳动产生的。合并追加劳动力的生产资料，以及维持这种劳动力的生活资料，都不外是剩余产品的不可缺少的组成部分，即资本家阶级每年从工人阶级那里夺取的贡品的不可缺少的组成部分。如果资本家阶级用贡品的一部分来购买追加劳动力，甚至以十足的价格来购买，就是说，用等价物交换等价物，那还是征服者的老把戏，用从被征服者那里掠夺来的货币去购买被征服者的商品。","language":"中文","translation":false},{"id":"capital-23-16","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"如果追加资本所雇用的就是把它生产出来的人，那末后者首先必须继续使原有资本增殖，其次要对自己过去劳动的产品用比它所费劳动更多的劳动买回来。如果我们把这看作资本家阶级和工人阶级之间的交易，那末，即使用从前雇用的工人的无酬劳动来雇用追加的工人，问题的实质也不会有丝毫改变。资本家也许还把追加资本转化为机器，而机器又把这种追加资本的生产者抛向街头，用几个儿童来代替他们。不管怎样，工人阶级总是用他们这一年的剩余劳动创造了下一年雇用追加劳动的资本。这就是所谓“资本生资本”。","language":"中文","translation":false},{"id":"capital-23-17","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"第一个追加资本2000镑的积累的前提，是资本家所预付的、由于他的“最初劳动”而属于他的10000镑价值额。而第二个追加资本400镑的前提，只能是第一个追加资本2000镑的预先积累，400镑就是这2000镑的资本化的剩余价值。现在，对过去无酬劳动的所有权，成为现今以日益扩大的规模占有活的无酬劳动的唯一条件。资本家已经积累的越多，就越能更多地积累。","language":"中文","translation":false},{"id":"capital-23-18","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"既然构成第一个追加资本的剩余价值，是用一部分原资本购买劳动力的结果，而这种购买完全符合商品交换的规律，从法律上看来，这种购买的前提不外是工人自由地支配自己的能力，而货币或商品的所有者自由地支配属于他的价值；既然第二个追加资本等等不过是第一个追加资本的结果，因而是前一种关系的结果；既然每一次交易都始终符合商品交换的规律，资本家总是购买劳动力，工人总是出卖劳动力，甚至还可以假定这种交易是按劳动力的实际价值进行的；那末很明显，以商品生产和商品流通为基础的占有规律或私有权规律，通过它本身的内在的、不可避免的辩证法转变为自己的直接对立物。表现为最初行为的等价物交换，已经变得仅仅在表面上是交换，因为，第一，用来交换劳动力的那部分资本本身只是不付等价物而占有的别人劳动产品的一部分；第二，这部分资本不仅必须由它的生产者即工人来补偿，而且在补偿时还要加上新的剩余额。这样一来，资本家和工人之间的交换关系，仅仅成为属于流通过程的一种表面现象，成为一种与内容本身无关的并只能使它神秘化的形式。劳动力的不断买卖是形式。其内容则是，资本家用他总是不付等价物而占有的别人的已经物化的劳动的一部分，来不断再换取更大量的别人的活劳动。最初，在我们看来，所有权似乎是以自己的劳动为基础的。至少我们应当承认这样的假定，因为互相对立的仅仅是权利平等的商品所有者，占有别人商品的手段只能是让渡自己的商品，而自己的商品又只能是由劳动创造的。现在，所有权对于资本家来说，表现为占有别人无酬劳动或产品的权利，而对于工人来说，则表现为不能占有自己的产品。所有权和劳动的分离，成了似乎是一个以它们的同一性为出发点的规律的必然结果。","language":"中文","translation":false},{"id":"capital-23-19","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"因此，不论资本主义占有方式好象同最初的商品生产规律如何矛盾，但这种占有方式的产生决不是由于这些规律遭到违反，相反地，是由于这些规律得到应用。只要略微回顾一下以资本主义积累为终点的各个依次发生的运动阶段，就可以再次弄清楚这一点。","language":"中文","translation":false},{"id":"capital-23-20","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"首先我们看到，一个价值额最初转化为资本是完全按照交换规律进行的。契约的一方出卖自己的劳动力，他方购买劳动力。前者取得自己商品的价值，从而把这种商品的使用价值即劳动让渡给后者。后者就借助于现在也归他所有的劳动，把已经归他所有的生产资料转化为一种新产品，这个产品在法律上也归他所有。","language":"中文","translation":false},{"id":"capital-23-21","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"这个产品的价值首先包含了已被消费掉的生产资料的价值。有用劳动不把生产资料的价值转移到新产品上去，就不能消费这些生产资料；但劳动力要卖得出去，必须能够向使用它的工业部门提供有用劳动。","language":"中文","translation":false},{"id":"capital-23-22","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"新产品的价值还包含了劳动力价值的等价物和剩余价值。这是由于按一定时期（一日，一周等等）出卖的劳动力的价值，低于它在这期间被使用后所创造的价值。但是，工人得到付给他的劳动力的交换价值，因而让渡了他的劳动力的使用价值，这同任何买卖都一样。","language":"中文","translation":false},{"id":"capital-23-23","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"劳动力这种特殊商品具有独特的使用价值，它能提供劳动，从而能创造价值，但这并不触犯商品生产的一般规律。所以，如果说预付在工资上的价值额不仅仅在产品中简单地再现出来，而且还增加了一个剩余价值，那末，这也并不是由于卖者被欺诈，——他已获得了自己商品的价值，——而只是由于买者消费了这种商品。","language":"中文","translation":false},{"id":"capital-23-24","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"交换规律只要求彼此出让的商品的交换价值相等。这一规律甚至从来就要求商品的使用价值各不相同，并且同它们的消费毫无关系，因为消费只是在买卖结束和完成以后才开始的。","language":"中文","translation":false},{"id":"capital-23-25","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"可见，货币最初转化为资本，是完完全全符合商品生产的经济规律以及由此产生的所有权的。尽管这样，这种转化仍然有以下的结果：","language":"中文","translation":false},{"id":"capital-23-26","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"1、产品属于资本家，而不属于工人；","language":"中文","translation":false},{"id":"capital-23-27","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"2、这一产品的价值除包含预付资本的价值外，还包含剩余价值，后者要工人耗费劳动，而不要资本家耗费任何东西，但它却成为资本家的合法财产；","language":"中文","translation":false},{"id":"capital-23-28","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"3、工人保持了自己的劳动力，只要找到买者就可以重新出卖。","language":"中文","translation":false},{"id":"capital-23-29","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"简单再生产仅仅是这种最初的活动的周期反复。货币总是一次又一次地重新转化为资本。因此，规律并没有遭到违反，相反地，只是得到不断发生作用的机会。","language":"中文","translation":false},{"id":"capital-23-30","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“好多次连续发生的交换行为，不过使最后一次成为最初一次的代表。”（西斯蒙第《政治经济学新原理》第1卷第70页）","language":"中文","translation":false},{"id":"capital-23-31","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"然而，我们已经知道，简单再生产足以使这种最初的活动具有一种同把它当作孤立过程来考察时完全不同的性质。","language":"中文","translation":false},{"id":"capital-23-32","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“在参加国民收入分配的人中间，一部分人〈工人〉每年通过新的劳动获得新的分配权；另一部分人〈资本家〉则通过最初劳动已经预先取得了永久的分配权。”（同上，第110、111页）","language":"中文","translation":false},{"id":"capital-23-33","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"大家知道，劳动领域并不是长子继承权创造奇迹的唯一领域。","language":"中文","translation":false},{"id":"capital-23-34","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"如果简单再生产为规模扩大的再生产，为积累所代替，事情也还是一样。在前一种情况下，资本家花费了全部剩余价值，在后一种情况下，他只消费了剩余价值的一部分，而把其余部分转化为货币，以此表现了自己的公民美德。","language":"中文","translation":false},{"id":"capital-23-35","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"剩余价值是资本家的财产，它从来不属于别人。资本家把剩余价值预付在生产上，完全象他最初进入市场的那一天一样，是从自己的基金中预付的。至于这一次他的基金是由他的工人的无酬劳动产生的这一事实，和问题绝对无关。如果工人B是用工人A所生产的剩余价值来雇用的，那末，第一，A提供这种剩余价值时，资本家对他的商品支付了全部合理价格，分文也没有少给；第二，这一交易同工人B毫无关系。B所要求的而且有权要求的，是资本家把他的劳动力的价值付给他。","language":"中文","translation":false},{"id":"capital-23-36","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“双方都有利，因为对工人来说，他在劳动前〈应当说：在他自己的劳动带来成果前〉就预先得到他的劳动〈应当说：别的工人的无酬劳动〉的果实；对雇主来说，这个工人的劳动的价值大于他的工资的价值〈应当说：他生产的价值大于他的工资的价值〉。”（西斯蒙第《政治经济学新原理》第1卷第135页）","language":"中文","translation":false},{"id":"capital-23-37","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"诚然，如果我们把资本主义生产看作不断更新的过程，如果我们考察的不是单个资本家和单个工人，而是他们的整体，即资本家阶级和与它对立的工人阶级，那末，情况就会完全不同了。但这样一来，我们就得应用一个与商品生产完全不同的标准。","language":"中文","translation":false},{"id":"capital-23-38","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在商品生产中，互相对立的仅仅是彼此独立的卖者和买者。他们之间的相互关系，随着他们所签订的契约期满而告结束。要是交易重复进行，那是由于订了新的契约，这同以前的契约完全无关，在这里同一买者和同一卖者再次碰在一起只是偶然的事情。","language":"中文","translation":false},{"id":"capital-23-39","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"因此，如果要把商品生产或属于商品生产的过程按其本身的经济规律来加以判断，我们就必须把每个交换行为就其本身来加以考察，撇开它与以前和以后的交换行为的一切联系。由于买卖只是在个别人之间进行，所以不可能在这里找到整个社会阶级之间的关系。","language":"中文","translation":false},{"id":"capital-23-40","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"现在执行职能的资本，不管它经过的周期的再生产和先行积累的系列多么长，总是保持着它本来的处女性。尽管每一个单独考察的交换行为仍遵循交换规律，但占有方式却会发生根本的变革，而这丝毫不触犯与商品生产相适应的所有权。同一所有权，在产品归生产者所有，生产者用等价物交换等价物，只能靠自己劳动致富的初期，是有效的；在社会财富越来越多地成为那些能不断地重新占有别人无酬劳动的人的财产的资本主义时期，也是有效的。","language":"中文","translation":false},{"id":"capital-23-41","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"一旦劳动力由工人自己作为商品自由出卖，这种结果就是不可避免的。但只有从这时起，商品生产才普遍化，才成为典型的生产形式；只有从这时起，每一个产品才一开始就是为卖而生产，而生产出来的一切财富都要经过流通。只有当雇佣劳动成为商品生产的基础时，商品生产才强加于整个社会，但也只有这时，它才能发挥自己的全部潜力。说雇佣劳动的介入使商品生产变得不纯，那就等于说，商品生产要保持纯粹，它就不该发展。商品生产按自己本身内在的规律越是发展成为资本主义生产，商品生产的所有权规律也就越是转变为资本主义的占有规律。","language":"中文","translation":false},{"id":"capital-23-42","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"我们已经看到，甚至在简单再生产的情况下，全部预付资本，不管它的来源如何，都转化为积累资本或资本化的剩余价值。但在生产的巨流中，全部原预付资本，与直接积累的资本即重新转化为资本（不论它是在积累者手中，还是在别人手中执行职能）的剩余价值或剩余产品比较起来，总是一个近于消失的量（数学意义上的无限小的量）。所以，政治经济学一般都把资本说成是“用来重新生产剩余价值的积累起来的财富”（转化了的剩余价值或收入），或把资本家说成是“剩余产品的占有者”。这种看法不过是用另一种方式来说明全部现存的资本是积累起来的或资本化的利息，因为利息不过是剩余价值的一部分。","language":"中文","translation":false},{"id":"capital-23-43","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"2、政治经济学关于规模扩大的再生产的错误见解","language":"中文","translation":false},{"id":"capital-23-44","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在进一步探讨积累或剩余价值再转化为资本的某些规定以前，我们必须清除古典经济学提出的一种含糊观点。","language":"中文","translation":false},{"id":"capital-23-45","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"资本家为自己消费而用一部分剩余价值购买的商品，对他不能起生产资料和价值增殖手段的作用，同样，他为满足自己的自然需要和社会需要而购买的劳动，也不起生产劳动的作用。资本家没有通过购买这种商品和劳动，把剩余价值转化为资本，相反地，把它作为收入消费掉或花费掉了。旧贵族的思想，如黑格尔正确地指出的，主张“消费现存的东西”，特别是讲究个人侍奉的豪华，以示阔绰，与此相反，在资产阶级经济学看来，具有决定性重要意义的是，宣布积累资本是每个公民的首要义务，并谆谆告诫人们，如果把全部收入吃光用尽，而不把其中相当的一部分用来雇用追加的生产工人，让他们带来的东西超过他们耗费的东西，那就不能积累。另一方面，资产阶级经济学又不得不同一般人的偏见作斗争，这种偏见把资本主义生产和货币贮藏混为一谈，以为积累财富就是使财富现有的实物形式免遭破坏，也就是不被消费掉，或者说，把财富从流通中救出来。其实，把货币贮藏起来不加入流通，同把货币作为资本而增殖，恰恰是相反的两回事，从货币贮藏的意义上进行商品积累，是十足的愚蠢行为。大量商品的积累是流通停滞或生产过剩的结果。诚然，在一般人的观念中是把下面这两种现象混在一起了：一方面是富人消费基金中积累的供慢慢消费的财物，另一方面是一切生产方式所共有的储备。后一现象，我们在分析流通过程时还要略微谈到。","language":"中文","translation":false},{"id":"capital-23-46","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"因此，古典经济学强调指出，积累过程的特点是，剩余产品由生产工人消费，而不由非生产工人消费，这一点是对的。但它的错误也正是从这里开始。亚·斯密使人们形成一种流行的看法，把积累仅仅看成剩余产品由生产工人消费，或者说，把剩余价值的资本化仅仅看成剩余价值转变为劳动力。例如，我们可以听听李嘉图的说法：","language":"中文","translation":false},{"id":"capital-23-47","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“必须懂得，一个国家的全部产品都是要消费掉的，但究竟由再生产另一个价值的人消费，还是由不再生产另一个价值的人消费，这中间有难以想象的区别。我们说收入节约下来加入资本，我们的意思是，加入资本的那部分收入，是由生产工人消费，而不是由非生产工人消费。如果认为资本可以由于不消费而增加，那就大错特错了。”","language":"中文","translation":false},{"id":"capital-23-48","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"李嘉图和一切以后的经济学家追随亚·斯密一再重复地说：“加入资本的那部分收入，是由生产工人消费”，这就大错特错了。根据这种看法，所有转化为资本的剩余价值都要成为可变资本了。其实，剩余价值和原预付价值一样，分成不变资本和可变资本，分成生产资料和劳动力。劳动力是可变资本在生产过程中的存在形式。在这个过程中，它本身被资本家消费了。它通过自己的职能——劳动——去消费生产资料。同时，购买劳动力所付出的货币，转化为不是由“生产劳动”而是由“生产工人”消费的生活资料。亚·斯密根据自己根本错误的分析得出了以下的荒谬结论：虽然每一单个资本分成不变组成部分和可变组成部分，但社会资本只分解为可变资本，或者说，只用来支付工资。例如，一个呢绒厂主把2000镑转化为资本。他把这些货币的一部分用来雇织工，另一部分用来购买毛纱和织毛机等等。而把毛纱和织毛机卖给他的人，又把其中的一部分用来支付劳动，依此类推，直到2000镑完全用于支付工资，或者这2000镑所代表的全部产品都由生产工人消费掉。我们看到，这个论据的全部力量就在于把我们推来推去的“依此类推”这几个字。事实上，亚当·斯密正是在困难开始的地方中止了他的研究。","language":"中文","translation":false},{"id":"capital-23-49","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"要是我们只考察年总生产基金，每年的再生产过程是容易理解的。但年生产的各个组成部分都必须投入商品市场，而困难就在这里开始。各个资本的运动和个人收入的运动交错混合在一起，消失在普遍的换位中，即消失在社会财富的流通中，这就迷惑了人们的视线，给我们的研究提出了极其复杂的问题需要解决。在本书第二卷第三篇中，我将对实际的联系进行分析。重农学派最大的功劳，就在于他们在自己的《经济表》中，首次试图对通过流通表现出来的年生产的形式画出一幅图画。","language":"中文","translation":false},{"id":"capital-23-50","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"不言而喻，政治经济学不会不利用亚·斯密的所谓纯产品中转化为资本的部分完全由工人阶级消费这一论点，来为资本家阶级的利益服务。","language":"中文","translation":false},{"id":"capital-23-51","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"3、剩余价值分为资本和收入。节欲论","language":"中文","translation":false},{"id":"capital-23-52","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在前一章里，我们把剩余价值或剩余产品只是看作资本家的个人消费基金，在这一章里，我们到现在为止把它只是看作积累基金。但是，剩余价值不仅仅是前者，也不仅仅是后者，而是二者兼而有之。剩余价值一部分由资本家作为收入消费，另一部分用作资本或积累起来。","language":"中文","translation":false},{"id":"capital-23-53","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在一定量的剩余价值中，这两部分中的一部分越大，另一部分就越小。在其他一切条件不变的情况下，这种分割的比例决定着积累量。但这种分割是由剩余价值的所有者资本家来进行的。因此，这是他的意志行为。至于他所征收的贡物中由他积累的部分，据说是他节约下来的，因为他没有把它吃光用尽，也就是说，他执行了他作为资本家的职能，即执行使自己致富的职能。","language":"中文","translation":false},{"id":"capital-23-54","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"资本家只有作为人格化的资本，他才有历史的价值，才有象聪明的利希诺夫斯基所说的“没有任何日期”的历史存在权。也只有这样，他本身的暂时必然性才包含在资本主义生产方式的暂时必然性中。但既然这样，他的动机，也就不是使用价值和享受，而是交换价值和交换价值的增殖了。他狂热地追求价值的增殖，肆无忌惮地迫使人类去为生产而生产，从而去发展社会生产力，去创造生产的物质条件；而只有这样的条件，才能为一个更高级的、以每个人的全面而自由的发展为基本原则的社会形式创造现实基础。资本家只是作为资本的人格化才受到尊敬。作为这样一种人，他同货币贮藏者一样，具有绝对的致富欲。但是，在货币贮藏者那里，这表现为个人的狂热，在资本家那里，这却表现为社会机构的作用，而资本家不过是这个社会机构中的一个主动轮罢了。此外，资本主义生产的发展，使投入工业企业的资本有不断增长的必要，而竞争使资本主义生产方式的内在规律作为外在的强制规律支配着每一个资本家。竞争迫使资本家不断扩大自己的资本来维持自己的资本，而他扩大资本只能靠累进的积累。","language":"中文","translation":false},{"id":"capital-23-55","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"所以，就资本家的一切行动只是通过他才具有意志和意识的资本的职能而论，他的私人消费，对他来说也就成了对他的资本积累的掠夺，就象在意大利式簿记中把资本家的私人开支记在资本的借方一样。积累是对社会财富世界的征服。它在扩大被剥削的人身材料的数量的同时，也扩大了资本家直接和间接的统治。〔注：路德用高利贷者这种虽然在不断更新但是老式的资本家形式为例，很清楚地说明了统治欲是致富欲的一个要素。“异教徒根据理性得出了高利贷者是四倍盗贼和杀人犯的结论。而我们基督教徒却非常尊敬他们，几乎要为了他们的货币而崇拜他们…… 凡是吸尽、抢劫和盗窃别人营养的人，就是犯了使人饿死，使人灭亡的杀人大罪(杀多少，由他决定)。高利贷者就是犯了这样的大罪，他照理应当上绞架，如果他身上的肉多得足供许多乌鸦啄而分食，那末，他盗窃了多少古尔登，就应该被多少乌鸦去吃。但是他们却泰然坐在安乐椅上，而小偷却被绞死……小偷带上镣拷，大盗却腰缠万贯，身著丝绸…… 所以，在世界上人类再没有比守财奴和高利贷者更大的敌人了(恶魔除外)，因为他想成为支配一切人的上帝。土耳其人、武夫、暴君都是恶人，但他们仍不得不让人们生活，并自认是恶人和敌人。他们有时还会同情甚至不得不同情某些人。而高利贷者和贪财之徒却想竭尽全力使整个世界毁灭于饥渴贫苦之中，从而使他能独占一切，人人都把他奉为上帝，去领受他的恩赐，永远成为他的奴隶……披上长外套，带上金链指环，擦擦油嘴，让人看来俨如尊贵的虔诚者…… 高利贷者庞大可怕的怪物，象一只蹂躏一切的恶狼，比任何卡库斯、格里昂或安泰都厉害。但他却装出一付虔诚的样子，想使人无法知道被他倒着牵回洞穴去的公牛究竟到什么地方去了。然而海格立斯必然会听到公牛的吼声和俘虏的叫声，甚至到悬崖峭壁中去搜寻卡库斯，把公牛从恶汉手中拯救出来。所谓卡库斯就是指盗窃、抢劫和吞食一切的虔诚的高利贷者这个恶汉。他不承认自己做了恶事，并且认为谁也不会找到他，因为公牛是倒着牵回他的洞里去的，从足迹看来公牛似乎是被放走了。高利贷者正是想这样愚弄整个世界，似乎他带来了利益，他把公牛给了世界，其实他夺取了公牛并把它独吞了……既然对劫路人、杀人犯和强盗应处以磔车刑或斩首，那就更应该把一切高利贷者处以磔车刑和斩首…… 驱逐，革出教门，或斩首。”(马丁·路德《给牧师们的谕示：讲道时要反对高利贷》〕 但是，原罪到处发生作用。随着资本主义生产方式、积累和财富的发展，资本家不再仅仅是资本的化身。他对自己的亚当具有“人的同情感”，而且他所受的教养，使他把禁欲主义的热望嘲笑为旧式货币贮藏者的偏见。古典的资本家谴责个人消费是违背自己职能的罪恶，是“节制”积累，而现代化的资本家却能把积累看作是“放弃”自己的享受欲。“啊，他的胸中有两个灵魂，一个要想同另一个分离！”","language":"中文","translation":false},{"id":"capital-23-56","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在资本主义生产方式的历史初期，——而每个资本主义的暴发户都个别地经过这个历史阶段，——致富欲和贪欲作为绝对的欲望占统治地位。但资本主义生产的进步不仅创立了一个享乐世界；随着投机和信用事业的发展，它还开辟了千百个突然致富的源泉。在一定的发展阶段上，已经习以为常的挥霍，作为炫耀富有从而取得信贷的手段，甚至成了“不幸的”资本家营业上的一种必要。奢侈被列入资本的交际费用。此外，资本家财富的增长，不象货币贮藏者那样同自己的个人劳动和个人消费的节约成比例，而是同他榨取别人的劳动力的多少和强使工人放弃一切生活享受的程度成比例的。因此，虽然资本家的挥霍从来不象放荡的封建主的挥霍那样是直截了当的，相反地，在它的背后总是隐藏着最肮脏的贪欲和最小心的盘算；但是资本家的挥霍仍然和积累一同增加，一方决不会妨害另一方。因此，在资本家个人的崇高的心胸中同时展开了积累欲和享受欲之间的浮士德式的冲突。","language":"中文","translation":false},{"id":"capital-23-57","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"艾金医生在1795年发表的一部著作中说：","language":"中文","translation":false},{"id":"capital-23-58","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“曼彻斯特的工业可分为四个时期。在第一个时期，工厂主为了维持生活，不得不辛勤劳动。”","language":"中文","translation":false},{"id":"capital-23-59","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"他们特别是靠盘剥那些把子女送来当学徒的父母而大发横财，那些父母付给他们高额学费，而这些学徒却忍饥挨饿。另一方面，当时平均利润很低，要积累就得大大节俭。他们过着象货币贮藏者一样的生活，甚至连资本的利息也不肯消费。","language":"中文","translation":false},{"id":"capital-23-60","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“在第二个时期，他们开始赚到了少量的财产，但还象过去那样辛勤地劳动”，——因为象一切奴隶监督者都知道的那样，对劳动的直接剥削是要花费劳动的，——“并且过着和过去一样的俭朴生活…… 在第三个时期，奢侈开始了，各企业通过派骑马的人〈骑马的推销员〉到王国各商业城市去兜揽生意而扩大了经营。在1690年以前，在工业中能赚到3000—4000镑资本的人可能为数极少，甚至根本没有。但大约就在这个时候，或者在稍后的时期，工业家已经积累了货币，开始建造石头房子来代替木棚或土房…… 但在十八世纪最初几十年，如果一个曼彻斯特的工厂主以一品脱外国葡萄酒款待自己的客人，那就会遭到所有邻居的议论和非难。”","language":"中文","translation":false},{"id":"capital-23-61","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在机器生产出现以前，工厂主们晚上在酒店聚会时花的费用从来不会超过6便士一杯果汁酒和1便士一包烟。直到1758年，才出现了划时代的事情，人们第一次看到“一个实际从事营业的人坐上自己的马车！”“第四个时期”，即十八世纪最后三十多年，“是穷奢极欲，大肆挥霍的时期，这是靠扩大营业来维持的”。如果善良的艾金医生今天在曼彻斯特复活的话，他又将说些什么呢！","language":"中文","translation":false},{"id":"capital-23-62","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"积累啊，积累啊！这就是摩西和先知们！“勤劳提供物资，而节俭把它积累起来”。因此，节俭啊，节俭啊，也就是把尽可能多的剩余价值或剩余产品重新转化为资本！为积累而积累，为生产而生产——古典经济学用这个公式表达了资产阶级时期的历史使命。它对财富分娩的痛苦从来不迷惑，但对历史必然性悲叹又有什么用处呢？在古典经济学看来，无产者不过是生产剩余价值的机器，而资本家也不过是把这剩余价值转化为追加资本的机器。它非常严肃地对待资本家的历史职能。为了使资本家的内心摆脱享受欲和致富欲之间的不幸的冲突，马尔萨斯在本世纪二十年代初期曾维护这样一种分工：让实际从事生产的资本家承担积累的任务，而让另一些参加剩余价值分配的人，如土地贵族、领受国家和教会俸禄的人等等承担挥霍的任务。他说，最重要的就是“把支出欲和积累欲分开”。那些早就变得享乐成性和善于交际的资本家先生们不由得大叫起来。他们的代言人之一，一个李嘉图派叫道：马尔萨斯先生鼓吹高额地租、高额税收等等，难道是为了让非生产消费者来不断地刺激工业家！诚然，口号所标榜的是生产，规模不断扩大的生产，但是，","language":"中文","translation":false},{"id":"capital-23-63","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“这个过程与其说会促进生产，不如说会阻碍生产。而且让一部分人过着游手好闲的生活，只是为了去鞭策另一些人，这也不是十分公正的。尽管从后者的性格来说，如果强其他们去做，他们是能把事情办好的”。","language":"中文","translation":false},{"id":"capital-23-64","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"尽管他认为靠吸掉工业资本家汤里的油水这种办法来刺激工业资本家去积累是不公正的，但是他觉得，“要使工人勤勉地劳动”，必须尽可能地把工人的工资减到最低限度。他从来也不隐瞒生财之道就在于占有无酬劳动。","language":"中文","translation":false},{"id":"capital-23-65","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“工人需求的增加不过是表明他们甘愿拿走自己产品中的一小部分，而把其中大部分留给他们的雇主：要是有人说，消费〈工人的消费〉减少会产生‘过剩现象’〈市场商品充斥，生产过剩〉，那我只能回答说：过剩现象是高额利润的同义语。”","language":"中文","translation":false},{"id":"capital-23-66","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"关于从工人那里掠夺来的赃物应该怎样在工业资本家和游手好闲的土地所有者等人之间进行分配才最有利于积累这种学究气的争论，遇到七月革命就平息下去了。此后不久，城市无产阶级在里昂敲起了警钟，而农村无产阶级在英国又燃起了熊熊烈火。海峡此岸在传播欧文主义，海峡彼岸在传播圣西门主义和傅立叶主义。庸俗经济学的丧钟已经响了。在纳骚·威·西尼耳于曼彻斯特发现资本的利润（包括利息）是无酬的“最后第十二个劳动小时”的产物恰恰一年以前，他曾向世界宣布了自己的另一个发现。他庄严地声称：“我用节欲一词来代替被看作生产工具的资本一词。”这真是庸俗经济学的“发现”的不可超越的标本！它用阿谀的词句来替换经济学的范畴。如此而已。西尼耳教训说：“野蛮人造弓就是从事工业，但他没有实行节欲。”这就向我们说明，在早期的社会状态下，劳动资料如何和为何没有资本家的“节欲”也被制造出来了。“社会越进步，就越要求节欲”，也就是越要求那些以占有别人劳动及其产品为业的人实行节欲。从此劳动过程的一切条件就如数转化成资本家的节欲行为了。 谷物不只是吃掉，而且还用来播种，这是资本家的节欲！葡萄酒保留一个时期用以发酵，这是资本家的节欲！资本家“把生产工具贷给〈！〉工人”，也就是说，把生产工具同劳动力合并在一起作为资本来增殖，而不把蒸汽机、棉花、铁路、肥料、挽马等等吃光，或者按照庸俗经济学家的幼稚说法，不把“它们的价值”变成奢侈品和其他消费资料挥霍掉，这就是资本家在掠夺自己的欲望。资本家阶级究竟怎样能做到这一点，至今仍然是庸俗经济学严加保守的秘密。 够了，世界之所以能生存，无非全靠这个在毗湿奴神前的现代赎罪者资本家的自我修行。不仅是积累，就是单纯的“保存资本也要求不断地努力克服把资本吃光用尽的诱惑”。所以很明显，单是人道就要求把资本家从殉道和诱惑中解救出来，其办法同不久前乔治亚州的奴隶主所采取的一样，后者通过废除奴隶制而摆脱了这样一种 左右为难的境地：是把鞭打黑奴所得的全部剩余产品消耗在香槟酒上，还是把其中一部分再转化为更多的黑人和土地。","language":"中文","translation":false},{"id":"capital-23-67","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在各种不同的社会经济形态中，不仅都有简单再生产，而且都有规模扩大的再生产，虽然程度不同。生产和消费会累进地增加，因此，转化为生产资料的产品也会累进地增加。但是，只要工人的生产资料，从而他的产品和生活资料，还没有以资本形式同他相对立，这个过程就不会表现为资本积累，因而也不会表现为资本家的职能。几年前去世的、继马尔萨斯之后在海利贝里东印度学院讲授政治经济学的理查·琼斯，曾用两大事实很好地阐明了这一点。因为印度人民大部分是自耕农，所以他们的产品、劳动资料和生活资料从来不具有“从别人的收入中节约下来从而要经过一个预先的积累过程的基金的形式”〔注：第4版注：这一定是错了，这句话没有找到出处。——弗·恩·〕 。另一方面，在旧制度被英国统治破坏最小的省份，非农业工人由豪门直接雇用，一部分剩余农产品以贡物或地租形式流到这些豪门手中。这种剩余产品的一部分在实物形式上为豪门所消费，另一部分由工人替他们转化为奢侈品及其他消费，而剩下的一部分则形成自己占有劳动工具的工人的工资。在这里，虽然没有那种奇异的圣徒、神色黯然的骑士、“禁欲的”资本家介于其间，生产和规模扩大的再生产也仍在照常进行。","language":"中文","translation":false},{"id":"capital-23-68","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"4、几种同剩余价值分为资本和收入的比例无关但决定积累量的情况：","language":"中文","translation":false},{"id":"capital-23-69","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"劳动力的剥削程度；劳动生产力；所使用的资本和所消费的资本之间差额的扩大；预付资本的量 假设剩余价值分为资本和收入的比例已定，积累的资本量显然取决于剩余价值的绝对量。假定80％资本化，20％被消费掉，那末，积累的资本是2400镑还是1200镑，就要看剩余价值的总额是3000镑还是1500镑。可见，决定剩余价值量的一切情况也影响着积累的量。在这里我们对这些情况再作一次总括的说明，但是只限于它们在积累方面会提供新观点的范围。","language":"中文","translation":false},{"id":"capital-23-70","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"我们记得，剩余价值率首先取决于劳动力的剥削程度。政治经济学非常重视剥削程度的这种作用，以致有时把由于提高劳动生产力而造成的积累的加速和由于加强对工人的剥削而造成的积累的加速等同起来。在论述剩余价值的生产的那几篇里，我们总是假定工资至少和劳动力的价值相等。但是，把工资强行压低 到这一价值以下，在实际运动中起着极为重要的作用，因此我们不能不对这一点略加考察。在一定限度内，这实际上是把工人的必要消费基金转化为资本的积累基金。","language":"中文","translation":false},{"id":"capital-23-71","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“工资没有生产力；它是一个生产力的价格；工资不会同劳动本身一起贡献于商品的生产，正如机器的价格也不会同机器本身一起贡献于商品的生产一样。如果劳动无须购买就能得到，工资就成为多余的了。”","language":"中文","translation":false},{"id":"capital-23-72","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"但是，假如工人能靠空气过活，那用任何价格也不能购买他们了。因此，工人不费分文是一个数学意义上的极限：虽然可以逐渐接近，但永远无法达到。资本的不断趋势是使工人降到这种不费分文的地步。我常引用的一个十八世纪著作家、《论手工业和商业》的作者声称，英国的重大历史任务是把英国的工资降低到法国和荷兰的水平，他不过是泄露了英国资本灵魂深处的秘密。〔注：《论手工业和商业》1770年伦敦版第44页。1866年12月和1867年1月的《泰晤士报》也类似地表达了英国矿山所有者的心情，文中描绘了比利时矿工的幸福生活，他们只是要求和得到为他们的“主人”而生存所绝对必需的东西。比利时工人备受熬煎，但是《泰晤士报》却把他们描写成模范工人！1867年2月初，比利时的矿工（在马尔希延）用罢工作了回答，这次罢工是用火药和枪弹镇压下去的。〕 例如，他天真地说：","language":"中文","translation":false},{"id":"capital-23-73","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“如果我们的穷人〈称呼工人的术语〉想过奢侈的生活……他们的劳动就必然昂贵…… 我们只要想想那些工场手工业工人消费多得惊人的奢侈品就够了，例如白兰地酒、杜松子酒、茶叶、砂糖、外国水果、烈性啤酒、印花亚麻布、鼻烟和香烟等等。” 他还引用了北安普顿郡的一个工厂主的文章，这位工厂主仰天悲鸣：","language":"中文","translation":false},{"id":"capital-23-74","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“劳动在法国要比在英国整整便宜三分之一，因为法国的穷人劳动繁重，但衣食简单，他们的主要食物是面包、水果、青菜、根菜和干鱼；他们很少吃肉，小麦昂贵时，面包也吃得很少”。 〔注：北安普顿郡的这位工厂主犯了一个虔诚的欺骗罪，这是出于内心的冲动，因而是可以原谅的。他表面上是在比较英国的和法国的工场手工业工人的生活，但是，正如他后来所承认的，在本文的引文中，他描写的却是法国的农业工人!〕这篇文章的作者接着说道：“而且他们喝的只是白水或清淡饮料。因此他们实际上花的钱极少…… 这种状况当然很难达到，但并不是不能达到的，法国和荷兰已经存在这种状况，就令人信服地证明了这一点。”〔注：《论手工业和商业》1770年伦敦版第70、71页。第3版注：由于此后出现了世界市场上的竞争，我们现在大大地迈进了一步。议员斯特普耳顿向他的选举人说：“如果中国成了一个大工业国，那末欧洲的劳动人口除非把生活水平降低到他们的竞争者的水平，否则，我就不知道他们怎样才能坚持竞争。”(1873年9月3日《泰晤士报》)———现在英国资本渴望达到的目标已经不再是大陆的工资，而是中国的工资了。〕","language":"中文","translation":false},{"id":"capital-23-75","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"二十年后，一位名列贵族的美国骗子本杰明·汤普逊（又称朗福德伯爵）遵循着同一博爱主义的路线，使上帝和人都大为满意。他的《论文集》可以说是一本食谱，其中全是制作各种各样的代用品的方法，用以代替工人日常的昂贵食品。请看这位令人惊异的“哲学家”的一张特别成功的菜单：","language":"中文","translation":false},{"id":"capital-23-76","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“大麦5磅，玉米5磅，青鱼3便士，盐1便士，醋1便士，胡椒和白菜2便士，总计20 3/4便士，可以做成供64个人喝的汤，如果粮食的价格中常，汤的费用还可以降低到每人合1/4便士。”","language":"中文","translation":false},{"id":"capital-23-77","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"随着资本主义生产的发展，商品掺假使汤普逊的理想也成为多余的了。","language":"中文","translation":false},{"id":"capital-23-78","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"十八世纪末和十九世纪的最初几十年间，英国的租地农场主和地主把工资强行降低到绝对的最低限度，他们以工资形式付给农业短工的钱比最低限度还要低，而以教区救济金的形式付给不足的部分。下面这个例子可以说明英国的道勃雷们在利用“法律”来规定工资率时的丑态：","language":"中文","translation":false},{"id":"capital-23-79","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“1795年，当地主们在规定斯宾诺姆兰德地方的工资的时候，他们已用过午餐，但是他们显然认为工人是无须用午餐的…… 他们决定：当一个8磅11盎斯重的面包卖1先令的时候，每人每周的工资应为3先令，在这种面包价格上涨，而没有达到1先令5便士之前，工资可以适当增加。一旦超过了这一价格，工资则应按比例地减少，直到这种面包的价格达到2先令为止，这时每人的食量应比以前减少1/5。” 1814年，有一位大租地农场主，治安推事，贫民院主管，工资调整人阿·贝奈特在上院调查委员会上被质问：","language":"中文","translation":false},{"id":"capital-23-80","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“一天劳动的价值和教区给工人的救济金之间是否有某种比例？”他回答说：“有的，每个家庭每周的收入要超过名义工资，补足到每人一加仑面包（8磅11盎斯）和每人3便士…… 我们认为一个家庭中每人每周有一加仑面包就足以维持生活了；3便士则用来买衣服；如果教区愿意发给衣服，这3便士就可以不发了。这种办法不仅在威尔特郡西部一带普遍采用，我想全国也在普遍采用。”","language":"中文","translation":false},{"id":"capital-23-81","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"当时有一位资产阶级著作家喊道：","language":"中文","translation":false},{"id":"capital-23-82","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“这样，租地农场主们在若干年内就把自己同胞中的这个可敬的阶级贬低了，竟然迫使他们以贫民习艺所作为栖身之所…… 租地农场主甚至阻碍工人最必要的消费基金的积累，以便增加自己的收入。”","language":"中文","translation":false},{"id":"capital-23-83","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"目前，直接掠夺工人必要的消费基金对于剩余价值的形成，从而对于资本的积累基金的形成究竟起怎样的作用，已经由所谓家庭劳动（参看第十三章第八节d）的例子说明了。在本篇中我们还要举出更多的事实。","language":"中文","translation":false},{"id":"capital-23-84","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"虽然在一切工业部门里，由劳动资料构成的不变资本部分，必须足够供一定数量（这由企业规模决定）的工人使用，但是它完全不必总是同所使用的劳动量按同一比例增加。假定某一工厂有100个工人，每人劳动8小时，共800个劳动小时。如果资本家想使这个劳动小时数增加一半，他可以再雇用50个工人，但这样一来，他不仅要在工资上预付新的资本，而且要在劳动资料上预付新的资本。不过他也可以使原有的100个工人不是劳动8小时而是劳动12小时，这样，现有的劳动资料就足够使用了，只是损耗得快一些罢了。可见，由提高劳动力的紧张程度而获得的追加劳动，没有不变资本部分的相应增加，也可以增加剩余产品和剩余价值，即积累的实体。","language":"中文","translation":false},{"id":"capital-23-85","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在采掘工业中，例如在采矿业中，原料不是预付资本的组成部分。这里的劳动对象不是过去劳动的产品，而是由自然无偿赠予的。如金属矿石、矿物、煤炭，石头等等。这里的不变资本几乎完全由劳动资料组成，它们能很容易地容纳增加了的劳动量（如工人日夜换班）。而在其他条件相同的情况下，产品的数量和价值同所使用的劳动成正比地增加。在这里，正象生产的第一天一样，形成产品的原始要素，从而也就是形成资本物质成分的要素，即人和自然，是同时起作用的。由于劳动力具有伸缩性，即使不预先增加不变资本，积累的领域也能扩大。","language":"中文","translation":false},{"id":"capital-23-86","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在农业中，不预付追加的种子和肥料，就不可能扩大耕地。但是，一旦预付了追加的种子和肥料，那末，即使对土地进行纯粹机械性的耕作，也会对产量的提高发生奇迹般的作用。只要原有数量的工人付出更多的劳动量，不必预付新的劳动资料，也可以提高肥力。这又是人对自然的直接作用，这种作用无需新资本的介入，也会成为扩大积累的直接源泉。","language":"中文","translation":false},{"id":"capital-23-87","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"最后，在本来意义的工业中，任何追加的劳动消耗都要求相应地追加原料的消耗，但是不一定要追加劳动资料的消耗。因为采掘工业和农业给加工工业提供了它本身需要的原料和它的劳动资料的原料，所以采掘工业和农业无需追加资本就能生产的追加产品，对于加工工业也是有利的。","language":"中文","translation":false},{"id":"capital-23-88","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"总的结论是：资本一旦合并了形成财富的两个原始要素——劳动力和土地，它便获得了一种扩张的能力，这种能力使资本能把它的积累的要素扩展到超出似乎是由它本身的大小所确定的范围，即超出由体现资本存在的、已经生产的生产资料的价值和数量所确定的范围。","language":"中文","translation":false},{"id":"capital-23-89","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"资本积累的另一个重要的因素是社会劳动生产率的水平。","language":"中文","translation":false},{"id":"capital-23-90","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"随着劳动生产力的提高，体现一定量价值从而一定量剩余价值的产品量也会提高。在剩余价值率不变甚至下降，但其下降比劳动生产力的提高缓慢的情况下，剩余产品量也会增加。因此，在剩余产品分为收入和追加资本的比例保持不变的情况下，资本家的消费可以增加，而积累基金并不减少。积累基金的相对量甚至可以靠牺牲消费基金而增加，而同时由于商品变得便宜，资本家享用的消费仍和过去相等甚至比过去还多。但是我们已经知道，工人之变得便宜，从而剩余价值率的增加，是同劳动生产率的提高携手并进的，即使在实际工资提高的情况下也是如此。实际工资从来不会和劳动生产率按同一比例增加。这样，同一可变资本价值可以推动更多的劳动力，从而可以推动更多的劳动。同一不变资本价值可以体现在更多的生产资料上，即体现在更多的劳动资料、劳动材料和辅助材料上，从而会提供更多的形成产品和价值的要素，或者说，提供更多的吸收劳动的要素。因此，在追加资本的价值不变甚至降低的情况下，积累仍然可以加快。不仅再生产的规模在物质上扩大了，而且剩余价值的生产也比追加资本的价值增长得更快。","language":"中文","translation":false},{"id":"capital-23-91","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"劳动生产力的发展也会对原资本或已经处于生产过程中的资本发生反作用。执行职能的不变资本的一部分是由劳动资料如机器等等构成的，这些劳动资料只有经过一个较长的时期，才会被消费掉，因而被再生产出来或被同一种新的物品所替换。但是，这些劳动资料每年都有一部分死亡，或者说，达到了它的生产职能的终点。因此，每年都有一部分是处在周期的再生产或被同一种新的物品所替换的阶段。如果生产这些劳动资料的部门的劳动生产力发展了（劳动生产力是随着科学和技术的不断进步而不断发展的），旧的机器、工具、器具等等就为效率更高的、从功效来说更便宜的机器、工具和器具等等所代替。撇开现有的劳动资料在细节上的不断改进不说，旧的资本也会以生产效率更高的形式再生产出来。不变资本的另一部分，即原料和辅助材料在一年当中不断地再生产出来，而其中由农业生产的大多是一年再生产一次。因此改良方法等等的每次采用，在这里对追加资本和已在执行职能的资本几乎同时发生影响。化学的每一个进步不仅增加有用物质的数量和已知物质的用途，从而随着资本的增长扩大投资领域。同时，它还教人们把生产过程和消费过程中的废料投回到再生产过程的循环中去，从而无需预先支出资本，就能创造新的资本材料。正象只要提高劳动力的紧张程度就能加强对自然财富的利用一样，科学和技术使执行职能的资本具有一种不以它的一定量为转移的扩张能力。同时，这种扩张能力对原资本中已进入更新阶段的那一部分也发生反作用。资本以新的形式无代价地合并了在它的旧形式背后所实现的社会进步。当然，生产力的这种发展同时会使正在执行职能的资本部分地贬值。只要这种贬值通过竞争被人们痛切地感觉到，主要负担就会落到工人身上，资本家力图用加强对工人剥削的办法来弥补自己的损失。","language":"中文","translation":false},{"id":"capital-23-92","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"劳动把它所消费的生产资料的价值转移到产品上去。另一方面，一定量的劳动所推动的生产资料的价值和数量是同劳动的生产效率的提高成比例地增加的。因此，虽然同量的劳动始终只是给自己的产品增加同量的新价值，但是，随着劳动生产率的提高，同时由劳动转移到产品上的旧资本的价值仍会增加。","language":"中文","translation":false},{"id":"capital-23-93","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"例如，一个英国的纺纱工人和一个中国的纺纱工人以同样的强度劳动同样多的小时，那末在一周当中他们会创造出相等的价值。但是，尽管有这种相等，使用一架强有力的自动机劳动的英国人一周的产品的价值和只使用一架手摇纺车的中国人一周的产品的价值，仍有大得惊人的差别。在同一个时间内，中国人纺一磅棉花，英国人可以纺好几百磅。一个几百倍大的旧价值总额使英国人的产品的价值膨胀了，这些旧价值以新的有用形式保存在产品中，因而又可以重新执行资本的职能。弗·恩格斯告诉我们：“在1782年，〈英国〉前三年剪下的全部羊毛都因为缺少工人而没有加工，假若不是新发明的机器帮助把所有的羊毛都纺出来的话，这些羊毛还得这样搁下去。”在机器形式中物化的劳动自然没有直接创造出任何一个人，但是它使为数不多的工人通过追加相对少的活劳动，就能不仅把羊毛生产地消费掉，加进新的价值，而且还以毛纱等等的形式保存它的旧价值。同时，它又提供了羊毛扩大再生产的手段和刺激。在创造新价值时又保存旧价值，这是活劳动的自然恩惠。因此，随着劳动的生产资料的效能、规模和价值的增长，从而随着劳动生产力的发展而造成的积累的增长，劳动在不断更新的形式中把不断膨胀的资本的价值保存下来并使其永久化。〔注：古典经济学由于对劳动过程和价值增殖过程作了不完全的分析，所以从来也没有真正了解再生产的这一重要因素。例如，我们在李嘉图那里就可以看到这种情形。例如他说：不管生产力发生怎样的变化，“一百万人在工厂里总是生产出相同的价值”。在他们的劳动的外延量和内含量己定时，这样说是对的。但是这一点不会妨碍下面的事实，即在劳动生产力不同的情况下，一百万人会把极不相同的生产资料量转化为产品，因而会把极不相同的价值量保存在他们的产品中，也会提供极不相同的产品价值。而李嘉图在作某些结论时把这一情况忽视了。顺便提一下，李嘉图妄图用上述例子向让·巴·萨伊阐明使用价值(在这里他把它叫做wealth，即物质财富）和交换价值的区别。萨伊回答说：“李嘉图说，应用较好的方法，一百万人可以生产出多一两倍的财富，而并不生产更多的价值。李嘉图提出的这一难题，只要我们把生产看作（也必须看作）一种交换，即人们为了取得产品而在其中提供自己的劳动、土地和资本的生产服务的那种交换，就能迎刃而解了。我们正是通过这些生产服务才获得世界上的一切产品…… 因此……在名为生产的那种交换中，我们的生产服务所产生的有用物的量越多，我们就越富，我们的生产服务的价值就越大。”(让·巴·萨伊《给马尔萨斯先生的信》1820年巴黎版第168、169页)萨伊想要说明的“难题”（这种“难题”对他来说是存在的，对李亮图来说并不存在）如下：为什么在使用价值的量由于劳动生产力的提高而增加时，使用价值的价值不会增加？回答是：只要我们把使用价值叫作交换价值，这个难题就解决了。交换价值是一种以某种方式与交换相联系的东西。因此，我们把生产称为劳动和生产资料同产品的“交换”，同时十分清楚，生产提供的使用价值越多，所得到的交换价值也就越多。换句话说，一个工作日给织袜厂主生产的使用价值例如袜子越多，工厂主也就越富有袜子。但是萨伊先生突然想起，随着袜子“量的增加”，袜子的“价格”(它当然与交换价值毫无关系)就会下降，“因为竞争迫使他们<生产者>按照他们在产品上花去的费用出售产品”。但如果资本家按照他在商品上所花的成本价格出售这些商品，那末利润又从什么地方来呢？这不要紧。萨伊解释说，由于生产率的提高，每一个人用从前换一双袜子的同一等价物，现在可以换两双。他所得出的结论正是他想反驳的李嘉图的论点。经过了这样一番苦思之后，他洋洋得意地对马尔萨斯说道：“先生，这是个有充分根据的学说，我敢说，如果没有这个学说，便无从解决政治经济学上一些非常困难的问题，特别是解决这样的问题：财富代表价值，但在产品价值下降时，一个国家怎么会变得更为富有。”（《给马尔萨斯先生的信》第170页）一位英国经济学家对于萨伊在信中所玩弄的类似手法说道：“这些装腔作势的说法大体上就是萨伊先生喜欢称之为自己的学说的东西，他还力劝马尔萨斯在哈特福讲授这种学说，就象人们‘在欧洲许多地方’已经做过的那样。他说：‘如果你发现这一切论断中有什么似乎矛盾的地方，就请你考察一下它们所表现的那些事物吧，我敢相信，你会觉得这些论断是十分简单，十分合理的。’毫无疑问，通过这种手法，这些论断决不会表现为独创的或重要的。”(《论马尔萨斯先生近来提倡的关于需求的性质和消费的必要性的原理》第110页)〕劳动的这种自然能力表现为合并劳动的资本所固有的自我保存的能力，正象劳动的社会生产力表现为资本的属性，资本家对剩余劳动的不断占有表现为资本的不断自行增殖一样。劳动的一切力量都显现为资本的力量，正象商品价值的一切形式都显现为货币的形式一样。","language":"中文","translation":false},{"id":"capital-23-94","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"随着资本的增长，所使用的资本和所消费的资本之间的差额也在增大。换句话说，劳动资料如建筑物、机器、排水管、役畜以及各种器具的价值量和物质量都会增加，这些劳动资料在或长或短的一个时期里，在不断反复进行的生产过程中，用自己的整体执行职能，或者说，为达到某种有用的效果服务，而它们本身却是逐渐损耗的，因而是一部分一部分地丧失自己的价值，也就是一部分一部分地把自己的价值转移到产品中去。这些劳动资料越是作为产品形成要素发生作用而不把价值加到产品中去，也就是说，它们越是整个地被使用而只是部分地被消费，那末，它们就越是象我们在上面说过的自然力如水、蒸汽、空气、电力等等那样，提供无偿的服务。被活劳动抓住并赋予生命的过去劳动的这种无偿服务，会随着积累规模的扩大而积累起来。","language":"中文","translation":false},{"id":"capital-23-95","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"因为过去劳动总是装扮成资本，也就是说，A、B、C等人的劳动的被人所有总是装扮成非劳动者X的自己所有，所以资产者和政治经济学家们对过去劳动的功绩赞扬备至；苏格兰的天才麦克库洛赫甚至认为，过去劳动应当得到特殊的报酬（利息、利润等等）。〔注：在西尼耳取得“节欲的报酬”的专利权以前，麦克库洛赫早就取得了“过去劳动的报酬”的专利权。〕 于是，那种以生产资料的形式参与活劳动过程的过去劳动所取得的不断增长的重要性，就被归功于这种劳动的同工人本身相异化的形态，即它的资本的形态，虽然这种劳动是工人的过去的和无酬的劳动。就象奴隶主不能把劳动者本身和他的奴隶身分分开来考虑一样，资本主义生产的实际当事人及其胡说八道的思想家不能把生产资料和它们今天所具有的对抗性的社会化装分开来考虑。","language":"中文","translation":false},{"id":"capital-23-96","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"在劳动力的剥削程度已定的情况下，剩余价值量就取决于同时被剥削的工人人数，而工人人数和资本的量是相适应的，虽然它们的比例是变动着的。所以，资本由于连续的积累而增加得越多，分为消费基金和积累基金的价值额也就增加得越多。因此，资本家既能过更优裕的生活，又能更加“禁欲”。最后，生产的规模越是随着预付资本量一同扩大，生产的全部发条也就越是开动得有力。","language":"中文","translation":false},{"id":"capital-23-97","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"我们在这一研究的进程中已经知道，资本不是一个固定的量，而是社会财富中一个可伸缩的、随着剩余价值分为收入和追加资本的比例而不断变化的部分。其次我们知道，即使执行职能的资本的量已定，资本所合并的劳动力、科学和土地（经济学上所说的土地是指未经人的协助而自然存在的一切劳动对象），也会成为资本的有伸缩性的能力，这种能力在一定的限度内使资本具有 一个不依赖于它本身的量的作用范围。在这里，我们把流通过程中一切会使同量资本发生程度极不相同的作用的条件完全撇开不说。因为我们只是以资本主义生产的界限为前提，是以社会生产过程的纯粹自然发生的形式为前提，所以我们把一切用现有的生产资料和劳动力可以直接而有计划地实现的更合理的结合也撇开不说。古典经济学从来就喜欢把社会资本看成一个有固定作用程度的固定量。不过这种偏见只是在庸人的鼻祖耶利米·边沁手里，即在十九世纪资产阶级平庸理智的这个枯燥乏味的、迂腐不堪的、夸夸其谈的圣哲手里，才确立为教条。边沁在哲学家中的地位，就象马丁·塔波尔在诗人中的地位一样。他们两人只有在英国才能制造出来。〔注：耶利米·边沁纯粹是一种英国的现象。在任何时代，任何国家里，都不曾有一个哲学家，就连我们的哲学家克利斯提安·沃尔弗也算在内，曾如此洋洋得意地谈论这些庸俗不堪的东西。效用原则并不是边沁的发明。他不过把爱尔维修和十八世纪其他法国人的才气横溢的言论枯燥无味地重复一下而已。假如我们想知道什么东西对狗有用，我们就必须探究狗的本性。这种本性本身是不能从“效用原则”中虚构出来的。如果我们想把这一原则运用到人身上来，想根据效用原则来评价人的一切行为、运动和关系等等，就首先要研究人的一般本性，然后要研究在每个时代历史地发生了变化的人的本性。但是边沁不管这些。他幼稚而乏味地把现代的市侩，特别是英国的市侩说成是标准的人。 凡是对这种标准的人和他的世界有用的东西，本身就是有用的。他还用这种尺度来评价过去、现在和将来。 例如基督教是“有用的”，因为它对刑法从法律方面所宣判的罪行，从宗教方面严加禁止。艺术批评是“有害的”，因为它妨碍贵人们去欣赏马丁·塔波尔的作品，如此等等。这位勇敢的人的座右铭是“没有一天不动笔”，他就用这些废话写出了堆积如山的书。如果我有我的朋友亨·海涅那样的勇气，我就要把耶利米先生称为资产阶级蠢才中的一个天才。〕 按照他的教条，生产过程的最普通的现象，如生产过程的突然扩张和收缩，甚至积累本身，都是完全不可理解的。〔注：“政治经济学家们喜欢把一定量的资本和一定数目的工人看作具有一种划一力量的和以划一的强度发生作用的生产工具…… 那些主张商品是生产的唯一要素的人证明生产根本不能扩大，因为要扩大生产就必须预先增多生活资料、原料和工具，实际上就等于说，没有生产的预先增加，就不可能有生产的增加，或者换句话说，任何增加都是不可能的。”(赛·贝利《货币及其价值的变动》第58、70页)贝利主要是从流通过程的观点来批判这个教条。〕 边沁本人和马尔萨斯、詹姆斯·穆勒、麦克库洛赫等人都利用这一教条以达到辩护的目的，特别是为了把资本的一部分，即可变资本或可转化为劳动力的资本，说成是一个固定的量。可变资本的物质存在，即它所代表的工人生活资料的量或所谓劳动基金，被虚构为社会财富中受自然锁链束缚的而且不能突破的特殊部分。为了推动作为固定资本，或从物质方面说，作为生产资料执行职能的那一部分社会财富，必需有一定量的活劳动。这个量是由工艺学所确定的。但是，推动这一劳动量所需要的工人人数是没有一定的，因为这个数目随着单个劳动力的剥削程度而变化，这个劳动力的价格也是没有一定的，所知道的只是它的具有很大伸缩性的最低界限。这一教条根据的事实是：一方面，工人对社会财富分为非劳动者的消费和生产资料这一点无权过问。另一方面，工人只有在幸运的例外情况下才有可能靠牺牲富人的“收入”来扩大所谓“劳动基金”。〔注：约·斯·穆勒在其《政治经济学原理》一书[第2篇第1章第3节]中说：“现在劳动产品的分配是同劳动成反比的：产品的最大部分属于从来不劳动的人，次大部分属于几乎只是名义上劳动的人，而且劳动越艰苦和越不愉快，报酬就越少，最后，从事最劳累、最费力的体力劳动的人甚至连得到生活必需品都没有保证”。为了避免误解，我说明一下，约·斯·穆勒之流由于他们的陈旧的经济学教条和他们的现代倾向发生矛盾，固然应当受到谴责，但是，如果把他们和庸俗经济学的一帮辩护士混为一谈，也是很不公平的。〕","language":"中文","translation":false},{"id":"capital-23-98","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"把劳动基金的资本主义界限改写成劳动基金的社会的自然界限，造成了多么荒唐的同义反复，这可以用福塞特教授的例子来说明。他说：","language":"中文","translation":false},{"id":"capital-23-99","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“一个国家的流动资本〔注：这里我要提醒读者，可变资本和不变资本这两个范畴是我最先使用的。亚·斯密以来的政治经济学都把这两个范畴中包含的规定性，同那种由流通过程产生的形式区别，即固定资本和流动资本的区别混淆起来了。关于这个问题本书第二卷第二篇还要更详细地谈到。〕就是它的劳动基金。因此，要想计算出每个工人所得到的平均货币工资，只要简单地用工人人口的数目去除这个资本就行了。”","language":"中文","translation":false},{"id":"capital-23-100","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"这就是说，我们先算出实际付给的个人工资的总额，然后我们就可以断言，这样加起来的结果就是上帝和自然强行规定的“劳动基金”的价值总额。最后，我们把用这种办法得出的总额除以工人人数，就可以又发现平均每个工人能得到多少。这是一个非常狡猾的手法。它并不妨碍福塞特先生一口气说出：","language":"中文","translation":false},{"id":"capital-23-101","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"“英国每年所积累的总财富分为两个部分。一部分用来维持英国本身的工业。另一部分则输往国外…… 用在本国工业上的那一部分占这个国家每年积累的财富的不大的一部分。”","language":"中文","translation":false},{"id":"capital-23-102","author":"马克思","title":"资本论·第一卷","location":"第二十二章 剩余价值转化为资本","page":23,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/22.htm","text":"由此可见，从英国工人那里不付等价物而窃取的、逐年都在增长的剩余产品的一大部分，不是在英国而是在其他国家资本化的。但是同追加资本一起输出的，还有上帝和边沁所发明的“劳动基金”的一部分。〔注：可以说，每年从英国输出的不仅是资本，而且还有以移民形式输出的工人。不过本文所指的并不是移民的特有财产，这些移民大部分不是工人。其中租地农民的儿子占很大部分。每年为了获得利息而输往国外的英国追加资本同每年的积累的比率，要比每年的移民同每年人口的增长的比率大得多。〕","language":"中文","translation":false},{"id":"capital-24-1","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-24-2","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"第二十三章 资本主义积累的一般规律","language":"中文","translation":false},{"id":"capital-24-3","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1、资本构成不变，对劳动力的需求随积累的增长而增长","language":"中文","translation":false},{"id":"capital-24-4","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"我们在这一章要研究资本的增长对工人阶级的命运产生的影响。在这种研究中，最重要的因素就是资本的构成和它在积累过程进行中所起的变化。","language":"中文","translation":false},{"id":"capital-24-5","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"资本的构成要从双重的意义上来理解。从价值方面来看，资本的构成是由资本分为不变资本和可变资本的比率，或者说，分为生产资料的价值和劳动力的价值即工资总额的比率来决定的。从在生产过程中发挥作用的物质方面来看，每一个资本都分为生产资料和活的劳动力；这种构成是由所使用的生产资料量和为使用这些生产资料而必需的劳动量之间的比率来决定的。我把前一种构成叫做资本的价值构成，把后一种构成叫做资本的技术构成。二者之间有密切的相互关系。为了表达这种关系，我把由资本技术构成决定并且反映技术构成变化的资本价值构成，叫做资本的有机构成。凡是简单地说资本构成的地方，始终应当理解为资本的有机构成。","language":"中文","translation":false},{"id":"capital-24-6","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"投入一定生产部门的许许多多单个资本，彼此间具有多少不同的构成。把这些资本的一个个构成加以平均，就得出这个生产部门的总资本的构成。最后，把一切生产部门的平均构成加以总平均，就得出一个国家的社会资本的构成，我们以下要谈的归根到底只是这种构成。","language":"中文","translation":false},{"id":"capital-24-7","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"资本的增长包含它的可变部分，即转化为劳动力的部分的增长。转化为追加资本的剩余价值总要有一部分再转化为可变资本，或追加的劳动基金。假定资本的构成不变，也就是说，为了推动一定量的生产资料或不变资本始终需要同量劳动力，同时其他情况也不变，那末，对劳动的需求和工人的生存基金，显然按照资本增长的比例而增长，而且资本增长得越快，它们也增长得越快。因为资本每年都生产出剩余价值，其中的一部分每年都并入原资本，因为这种增殖额本身随着已经执行职能的资本的规模的扩大每年都在增长，最后，因为在特殊的致富欲的刺激下，例如，在由于新发展起来的社会需求而开辟了新的市场、新的投资领域等等的情况下，只要改变剩余价值或剩余产品分为资本和收入的比例，积累的规模就能突然扩大，所以，资本的积累需要，能够超过劳动力或工人人数的增加，对工人的需求，能够超过工人的供给，这样一来，工资就会提高。只要上述假定一直不变，这种情况最终一定会发生。因为雇用的工人一年比一年多，所以迟早必定会出现这样的时候：积累的需要开始超过通常的劳动供给，于是工资提高。在整个十五世纪和十八世纪上半叶，在英国就可以听到这方面的怨言。但是这些多少有利于雇佣工人的维持和繁殖的情况，丝毫不会改变资本主义生产的基本性质。简单再生产不断地再生产出资本关系本身：一方面是资本家，另一方面是雇佣工人；同样，规模扩大的再生产或积累再生产出规模扩大的资本关系：一极是更多的或更大的资本家，另一极是更多的雇佣工人。劳动力必须不断地作为价值增殖的手段并入资本，不能脱离资本，它对资本的从属关系只是由于它时而卖给这个资本家，时而卖给那个资本家才被掩盖起来，所以，劳动力的再生产实际上是资本本身再生产的一个因素。因此，资本的积累就是无产阶级的增加。","language":"中文","translation":false},{"id":"capital-24-8","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"古典经济学十分懂得这个原理，以致象前面已经说过的，亚·斯密、李嘉图等人甚至错误地把积累同剩余产品中整个资本化的部分由生产工人消费或转化成追加的雇佣工人混为一谈。还在1696年，约翰·贝勒斯就说过：","language":"中文","translation":false},{"id":"capital-24-9","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“假设某人有10万英亩土地，有10万镑货币和10万头牲畜，而没有一个工人，那末这个富人自己还不就是工人？既然工人使人变富，所以工人越多，富人也就越多…… 穷人的劳动就是富人的财源。”","language":"中文","translation":false},{"id":"capital-24-10","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"同样，贝尔纳德·德孟德维尔在十八世纪初也曾说过：","language":"中文","translation":false},{"id":"capital-24-11","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“在财产有充分保障的地方，没有货币还比较容易生活，没有穷人就不行，不然谁去劳动呢？…… 应当使工人免于挨饿，但不应当使他们拥有任何可供储蓄的东西。如果某处有一个属于最低阶级的人，想靠异常的勤劳和忍饥挨饿来摆脱自己生长起来的那种环境，那谁也不应当妨碍他，因为对社会上每一个人，每一个家庭来说，节俭无可否认是最聪明的办法；但是对一切富裕民族有利的是：绝大部分穷人永远不要无事可做，但要经常花光他们所收入的一切……靠每天劳动为生的人，只有贫困才能激励他们去工作，缓和这种贫困是明智的，想加以治疗则未免愚蠢。能使工人勤勉的唯一手段是适度的工资。工资过低会使工人依各自的气质或者变得垂头丧气，或者变得悲观绝望，工资过高则会使他们变得傲慢不逊，好逸恶劳…… 以上的说明就可以知道，在不允许奴隶存在的自由民族中，最可靠的财富就是众多的勤劳贫民。没有他们，就不能有任何享乐，任何一个国家的产品都不可能被用来谋利，此外，他们还是补充海陆军的永不枯竭的源泉。要使社会〈当然是非劳动者的社会〉幸福，使人民满足于可怜的处境，就必须使大多数人既无知又贫困。知识会使我们产生更大和更多的愿望，而人的愿望越少，他的需要也就越容易满足。”〔注：贝·德·孟德维尔(《蜜蜂的寓言》1728年伦敦第5版附注第212、213、328页)——“有节制的生活和不断的劳动，对于穷人来说，是通向物质幸福<他是指尽可能长的工作日和尽可能少的生活资料>的道路，而对于国家<即地主、资本家和他们的政界显贵与代理人>来说，是通向富裕的道路。”(《论手工业和商业》1770年伦敦版第54页)〕","language":"中文","translation":false},{"id":"capital-24-12","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"孟德维尔这个诚实的和头脑清晰的人还没有了解：积累过程的机构本身，会在增大资本的同时，增加“勤劳贫民”即雇佣工人的数量，这些雇佣工人不得不把自己的劳动力转化为日益增长的资本的日益增大的增殖力，并且由此把他们对自己所生产的、但已人格化为资本家的产品的从属关系永久化。弗·摩·伊登爵士在他所著《贫民的状况，或英国劳动者阶级的历史》一书中曾谈到这种从属关系，他说：","language":"中文","translation":false},{"id":"capital-24-13","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“在我们这个地带，为了满足需求，就需要有劳动，因此，社会上至少有一部分人必须不倦地劳动…… 但是一些不劳动的人却支配着勤劳的产品。这些所有主所以能够如此，仅仅归因于文明和秩序；他们纯粹是市民制度的创造物〔注：伊登应当问一下：“市民制度”又是谁的创造物?他从法律幻想的观点出发，不是把法律看作物质生产关系的产物，而是相反，把生产关系看作法律的产物。兰盖只用“法的精神就是所有权”这样一句话，就把孟德斯鸠幻想的“法的精神”推翻了。〕。因为这种制度承认，除了劳动之外，还可以用别种方法占有劳动的果实。拥有独立财产的人所以能够拥有财产，几乎完全是靠别人的劳动，而不是靠他们自己的能力，他们的能力绝不比别人强；富人不同于穷人的地方，不在于占有土地和货币，而在于拥有对劳动的支配权…… 对穷人适宜的，不是使他们处于卑贱的或奴隶般的地位，而是使他们处于安适和宽松的从属关系，对拥有财产的人来说，他们则应当对于为他们劳动的人拥有充分的影响和权威…… 每一个懂得人类天性的人都知道，这样一种从属关系是工人自身安乐所必需的”。","language":"中文","translation":false},{"id":"capital-24-14","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"顺便提一下，在亚当·斯密的学生中，只有弗·摩·伊登爵士在十八世纪有过某些重要的成就。〔注：假如读者想提醒我们不要忘了1798年发表《人口原理》的马尔萨斯，那我也要提醒你们：他这本书最初的版本不过是对笛福、詹姆斯·斯图亚特爵士、唐森、富兰克林、华莱士等人的小学生般肤浅的和牧师般拿腔做调的剽窃，其中没有一个他独自思考出来的命题。这本小册子所以轰动一时，完全是由党派利益引起的。法国革命在不列颠王国找到了热情的维护者；“人口原理”是在十八世纪逐渐编造出来的，接着在一次巨大的社会危机中被大吹大擂地宣扬为对付孔多塞等人学说的万无一失的解毒剂，英国的寡头政府认为它可以最有效地扑灭一切追求人类进步的热望，因而报以热情的喝采。马尔萨斯对自己的成功大为惊奇，于是着手把一些表面地拼凑起来的材料塞进原来的模型中去，又添加了点新东西，不过这些东西不是马尔萨斯发现的，而只是被他据为已有的。——顺便提一下，马尔萨斯虽然是英国国教高教会派的牧师，但他曾立过修道士终身不婚的誓言。这正是取得新教派的剑桥大学的特待校友资格的条件之一。“本会会员不得结婚。一旦娶妻，即不再为会员。”(《剑桥大学委员会报告》第172页)这种情况使马尔萨斯区别于其他新教牧师而处于有利的地位，因为其他新教牧师抛弃了天主教关于教士终身不婚的圣诫，并且力言“滋生繁殖”是他们特殊的圣经使命，以致到处为人口的增殖作出极不体面的贡献，而同时却又向工人宣讲“人口原理”。能说明问题的是：经济学上拙劣地仿造出来的原罪，亚当的苹果，“迫不及待的情欲”，唐森牧师风趣地称之为“要把邱比特的箭弄钝的各种障碍”——这个微妙的问题过去和现在都是由新教神学或不如说新教教会的老爷们所垄断。除了威尼斯的僧侣奥特斯这位有创见有才智的著作家外，大多数人口论者都是新教牧师。例如：布吕克纳，他1767年在来顿出版的《动物界论》一书详尽无遗地论述了现代人口理论，而该书的思想是由魁奈同自己的学生老米拉波对这一题目的一次短暂争论所提供的，后来就是华莱士牧师、唐森牧师、马尔萨斯牧师及其学生托·查默斯大牧师，至于这一派的一些次要的牧师文人，那就根本不用谈了。最初研究政治经济学的，是象霍布斯、洛克、休谟一类的哲学家，以及象托马斯·莫尔、坦普尔、萨利、德·维特、诺思、罗、范德林特、康替龙、富兰克林一类的实业家和政治家，而特别在理论方面进行过研究并获得巨大成就的，是象配第、巴尔本、孟德维尔、魁奈一类的医生。甚至在十八世纪中叶，一位当时著名的经济学家，牧师塔克尔先生，还曾为他自己研究钱财而进行过辩解。后来，正是随着“人口原理”的出现，新教牧师的丧钟敲响了。把人口看作财富的基础，并且和亚当·斯密一样是牧师们不可调和的敌人的配第，似乎预料到了这些拙劣的干涉，因此说道：“教士最守苦行时，宗教最繁荣，正如在律师饿死的地方，法律最昌明一样”。配第劝告新教的牧师们：如果你们不愿再追随使徒保罗，不愿终身不婚来“禁欲”，“至少不要生出多于现有牧师俸禄所能吸收的牧师，也就是说，在英格兰和威尔士只有12000份牧师俸禄的时候，要是生出24000个牧师，那是不明智的，因为12000个无以为生的人总要设法自谋生计。为此他们走向民间，向人们游说：那12000个受俸牧师在毒害人们的灵魂，使这些灵魂饿死，把他们引入歧途，使他们无法升入天国。除了这样做而外，难道还能有什么别的更容易谋生的方法吗?”(配第《赋税论》1667年伦敦版第57页)亚当·斯密对当时新教牧师的态度可以从下面这件事看出来。在《给法学博士亚·斯密的一封信，论他的朋友大卫·休谟的生平和哲学》(一位称作基督徒的人著，1784年牛津第4版)这一著作中，诺里奇的高教会派主教霍恩博士责难亚·斯密，因为斯密在一封致斯特兰先生的公开信中要使自己的“朋友大卫<即休谟>不朽”，因为斯密向公众讲述，“休谟在他临终的床上以读琉善的作品和玩惠斯特牌而自娱”，甚至胆敢写道：“无论在休谟生前或死后，我始终认为，他在人类天性的弱点所允许的范围内，接近了一个理想的全智全德的人”。这位主教愤怒地叫喊道：“先生，您把一个不可救药地反对一切叫作宗教的东西，并且竭尽全力甚至要使宗教这个名称也从人们的记忆中消失的人的性格和品行，向我们描绘成全智全德的，您这样做合适吗?”(同上，第8页)“但是，热爱真理的朋友们，不要气馁，无神论是长久不了的。”(第17页)亚当·斯密“抱着残忍的恶意，要在全国宣扬无神论<就是通过他的《道德情操论》>…… 博士先生，我们了解您的诡计！您想得倒好，但是这一次却失算了。您想用大卫·休谟先生的例子来使我们相信，无神论对于意志沮丧的人来说是唯一的兴奋剂，是对付死亡恐怖的唯一的解毒剂…… 您去笑那废墟中的巴比伦吧？去祝贺那无情的恶魔法老吧？”(同上，第21、22页)在亚·斯密的学生中，一个正统派在亚·斯密死后写道：“斯密对休谟的友谊妨碍他成为一个基督徒…… 他相信休谟的每一句话。即使休谟对他说，月亮是一块绿色的干酪，他也会相信。所以，休谟说没有上帝，没有奇迹，他也同样相信…… 斯密在政治原则上接近于共和主义。”(詹姆斯·安德森《蜜蜂》1791—1793年爱丁堡版，共十八卷，第3卷第166、165页)托·查默斯牧师曾怀疑，亚·斯密捏造出“非生产工人”这个范畴纯粹是出于恶意，是专门用来影射新教牧师的，虽然牧师们在上帝的葡萄园中也进行了幸福的劳动。〕","language":"中文","translation":false},{"id":"capital-24-15","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在以上所假定的对工人最有利的积累条件下，工人对资本的从属关系是采取可以忍受的，或者如伊登所说的“安适和宽松的”形式。随着资本的增长，这种关系不是更为加强，而只是更为扩大，也就是说，资本的剥削和统治的范围只是随着它本身的规模和它的臣民人数的增大而扩大。在工人自己所生产的日益增加的并且越来越多地转化为追加资本的剩余产品中，会有较大的份额以支付手段的形式流回到工人手中，使他们能够扩大自己的享受范围，有较多的衣服、家具等消费基金，并且积蓄一小笔货币准备金。但是，吃穿好一些，待遇高一些，持有财产多一些，不会消除奴隶的从属关系和对他们的剥削，同样，也不会消除雇佣工人的从属关系和对他们的剥削。由于资本积累而提高的劳动价格，实际上不过表明，雇佣工人为自己铸造的金锁链已经够长够重，容许把它略微放松一点。在关于这一问题的争论中，大都把主要的东西，即资本主义生产的具有代表性的特征忽略了。在这里，购买劳动力，不是为了用它的服务或它的产品来满足买者的个人需要。买者的目的是增殖他的资本，是生产商品，使其中包含的劳动比他支付了报酬的劳动多，也就是包含一个不花费他什么、但会通过商品的出售得到实现的价值部分。生产剩余价值或赚钱，是这个生产方式的绝对规律。劳动力只有在它会把生产资料当作资本来保存，把自身的价值当作资本再生产出来，并且以无酬劳动提供追加资本的源泉的情况下，才能够卖出去。〔注：第2版注：“但是，不论工业工人还是农业工人，他们就业的界限是一致的，那就是雇主能够从他们的劳动产品中榨取利润。如果工资率过高，使雇主的利润降低到平均利润以下，那末，雇主就会不再雇用他们，或者只有在他们答应降低工资的条件下，才会继续雇用他们。”（约翰·威德《中等阶级和工人阶级的历史》1835年伦敦第3版第240页）〕 所以，劳动力的出卖条件不管对工人怎样有利，总要使劳动力不断地再出卖，使财富作为资本不断地扩大再生产。我们已经知道，工资按其本性来说，要求工人不断地提供一定数量的无酬劳动。即使完全撇开工资提高而劳动价格同时下降等情况不说，工资的增大至多也不过说明工人必须提供的无酬劳动量的减少。这种减少永远也不会达到威胁制度本身的程度。撇开关于工资率的暴力冲突不说，——亚当·斯密也早就指出过，在这种冲突中，一般说来雇主始终是雇主，——由资本积累而引起的劳动价格的提高不外是下列两种情况之一：","language":"中文","translation":false},{"id":"capital-24-16","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"一种情况是，劳动价格继续提高，因为它的提高不会妨碍积累的进展；这没有什么值得奇怪的地方，因为，亚·斯密说过，","language":"中文","translation":false},{"id":"capital-24-17","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“即使利润下降，资本还是能增长，甚至增长得比以前还要快…… 利润小的大资本，一般也比利润大的小资本增长得快”（《国富论》第1卷第189）。","language":"中文","translation":false},{"id":"capital-24-18","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在这种情况下，很显然，无酬劳动的减少决不会妨碍资本统治的扩大。另一种情况是，积累由于劳动价格的提高而削弱，因为利润的刺激变得迟钝了。积累减少了。但是随着积累的减少，使积累减少的原因，即资本和可供剥削的劳动力之间的不平衡，也就消失了。所以，资本主义生产过程的机构会自行排除它暂时造成的障碍。劳动价格重新降到适合资本增殖需要的水平，而不管这个水平现在是低于、高于还是等于工资提高前的正常水平。可见，在第一种情况下，并不是劳动力或工人人口绝对增加或相对增加的减缓引起资本的过剩，相反地，是资本的增长引起可供剥削的劳动力的不足。在第二种情况下，并不是劳动力或工人人口绝对增加或相对增加的加速引起资本的不足，相反地，是资本的减少使可供剥削的劳动力过剩，或者不如说使劳动力价格过高。正是资本积累的这些绝对运动反映成为可供剥削的劳动力数量的相对运动，因而看起来好象是由后者自身的运动引起的。用数学上的术语来说：积累量是自变量，工资量是因变量，而不是相反。 同样，在工业周期的危机阶段，商品价格的普遍降低表现为货币相对价值的提高，而在繁荣阶段，商品价格的普遍提高表现为货币相对价值的降低。所谓通货学派就从这里得出结论说，物价高时，流通的货币太多；物价低时，流通的货币太少。他们的无知和对事实的完全误解，有这样一些经济学家现在可以与之媲美，这些经济学家把积累的上述现象说成是：在一种情况下是雇佣工人太少，在另一种情况下是雇佣工人太多。","language":"中文","translation":false},{"id":"capital-24-19","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"作为所谓“自然人口规律”的基础的资本主义生产规律，可以简单地归结如下：资本、积累同工资率之间的关系，不外是转化为资本的无酬劳动和为推动追加资本所必需的追加劳动之间的关系。因此，这决不是两个彼此独立的量，即资本量和工人人口数量之间的关系；相反地，归根到底这只是同一工人人口所提供的无酬劳动和有酬劳动之间的关系。如果工人阶级提供的并由资本家阶级所积累的无酬劳动量增长得十分迅速，以致只有大大追加有酬劳动才能转化为资本，那末，工资就会提高，而在其他一切情况不变时，无酬劳动就会相应地减少。但是，一旦这种减少达到一定点，滋养资本的剩余劳动不再有正常数量的供应时，反作用就会发生：收入中资本化的部分减少，积累削弱，工资的上升运动受到反击。可见，劳动价格的提高被限制在这样的界限内，这个界限不仅使资本主义制度的基础不受侵犯，而且还保证资本主义制度的规模扩大的再生产。可见，被神秘化为一种自然规律的资本主义积累规律，实际上不过表示：资本主义积累的本性，绝不允许劳动剥削程度的任何降低或劳动价格的任何提高有可能严重地危及资本关系的不断再生产和它的规模不断扩大的再生产。 在一种不是物质财富为工人的发展需要而存在，相反是工人为现有价值的增殖需要而存在的生产方式下，事情也不可能是别的样子。正象人在宗教中受他自己头脑的产物的支配一样，人在资本主义生产中受他自己双手的产物的支配。","language":"中文","translation":false},{"id":"capital-24-20","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"2、在积累和伴随积累的积聚的进程中资本可变部分相对减少","language":"中文","translation":false},{"id":"capital-24-21","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"按照经济学家们自己的见解，引起工资提高的，既不是社会财富的现有量，也不是已经取得的资本量，而仅仅是积累的不断增长和它的增长速度。（亚·斯密《国富论》第1篇第8章）以上我们只考察了这个过程的一个特殊阶段，即在资本技术构成不变的情况下资本增长的阶段。但是过程会越出这一阶段。","language":"中文","translation":false},{"id":"capital-24-22","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"一旦资本主义制度的一般基础奠定下来，在积累过程中就一定会出现一个时刻，那时社会劳动生产率的发展成为积累的最强有力的杠杆。亚·斯密说：","language":"中文","translation":false},{"id":"capital-24-23","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“引起工资提高的原因，即资本的增长，也促使劳动生产能力提高，使较小量的劳动能够生产出较大量的产品。”","language":"中文","translation":false},{"id":"capital-24-24","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"如果撇开土壤肥力等等自然条件，撇开分散劳动的独立生产者的技能（这种技能更多地表现在质量即制品的优劣上，而不是表现在数量即制品的多寡上），那末，社会劳动生产率的水平就表现为一个工人在一定时间内，以同样的劳动力强度使之转化为产品的生产资料的相对量。工人用来进行劳动的生产资料的量，随着工人的劳动生产率的增长而增长。在这里，这些生产资料起着双重作用。一些生产资料的增长是劳动生产率增长的结果，另一些生产资料的增长是劳动生产率增长的条件。例如，由于有了工场手工业分工和采用了机器，同一时间内加工的原料增多了，因而，进入劳动过程的原料和辅助材料的量增大了。这是劳动生产率增长的结果。另一方面，使用的机器、役畜、矿物质肥料、排水管等等的量，则是劳动生产率增长的条件。以建筑物、炼铁炉、运输工具等等形式积聚起来的生产资料的量，也是这样。但是，不管是条件还是结果，只要生产资料的量比并入生产资料的劳动力相对增长，这就表示劳动生产率的增长。因而，劳动生产率的增长，表现为劳动的量比它所推动的生产资料的量相对减少，或者说，表现为劳动过程的主观因素的量比它的客观因素的量相对减少。资本技术构成的这一变化，即生产资料的量比推动它的劳动力的量相对增长，又反映在资本的价值构成上，即资本价值的不变组成部分靠减少它的可变组成部分而增加。例如，有一笔资本，按百分比计算，起初50％投在生产资料上，50％投在劳动力上。后来，随着劳动生产率的发展，80％投在生产资料上，20％投在劳动力上，等等。资本的不变部分比可变部分日益相对增长的这一规律，在每一步上都由商品价格的比较分析所证实（象前面已经说明的），不管我们比较的是同一国家的不同经济时代，还是同一时代的不同国家。只代表所耗费的生产资料价值或资本不变部分的那个价格要素的相对量，同积累的增进成正比；用来支付劳动或代表资本可变部分的另一价格要素的相对量，一般同积累的增进成反比。","language":"中文","translation":false},{"id":"capital-24-25","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"不过，资本可变部分比不变部分的相对减少，或资本价值构成的变化，只是近似地表示出资本的物质组成部分构成上的变化。例如，目前投入纺纱业的资本价值中，不变资本占7/8，可变资本占1/8，而在十八世纪初不变资本占1/2，可变资本占1/2，但是，目前一定量纺纱劳动在生产中所消费的原料、劳动资料等等的量却比十八世纪初要多几百倍。原因很简单：随着劳动生产率的增长，不仅劳动所消费的生产资料的量增大了，而且生产资料的价值比生产资料的量也相对地减小了。这样一来，生产资料的价值绝对地增长了，但不是同它的量按比例增长。因此，不变资本和可变资本之间的差额的增大，同不变资本转化成的生产资料的量和可变资本转化成的劳动力的量之间的差额的增大相比，要慢得多。随着后一个差额的增长，前一个差额也增长，但是增长的程度较小。","language":"中文","translation":false},{"id":"capital-24-26","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"然而，积累的增进虽然使资本可变部分的相对量减少，但是决不因此排斥它的绝对量的增加。假定资本价值起初分为50％的不变资本和50％的可变资本，后来分为80％的不变资本和20％的可变资本。如果原有资本在此期间从例如6000镑增加到18000镑，那末，它的可变组成部分也要增加1/5。这个可变部分原来是3000镑，现在是3600镑。但是，要使劳动的需求提高20％，以前只需资本增加20％就够了，现在则要求原有资本增加为三倍。","language":"中文","translation":false},{"id":"capital-24-27","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在第四篇中已经指出，社会劳动生产力的发展怎样以大规模的协作为前提，怎样只有在这个前提下，才能组织劳动的分工和结合，才能使生产资料由于大规模积聚而得到节约，才能产生那些按其物质属性来说只适于共同使用的劳动资料，如机器体系等等，才能使巨大的自然力为生产服务，才能使生产过程变为科学在工艺上的应用。在商品生产中，生产资料归私人所有，因而劳动者或者分散地、独立地生产商品，或者由于缺乏自己经营的资料而把自己的劳动力当作商品来出卖；在这种生产的基础上，上述的前提只有通过单个资本的增长来实现，或者说，随着社会生产资料和生活资料转化为资本家的私有财产来实现。商品生产的地基只有在资本主义的形式上才能担负起大规模的生产。所以，单个商品生产者手中一定程度的资本积累，是特殊的资本主义的生产方式的前提。因此，在从手工业到资本主义生产的过渡中，我们必须假定已经有这种积累。这种积累可以叫作原始积累，因为它不是特殊的资本主义的生产的历史结果，而是这种生产的历史基础。这种积累本身是怎样发生的，我们还用不着在这里研究。只要知道它是起点就行了。但是，一切在这个基础上生长起来的提高社会劳动生产力的方法，同时也就是提高剩余价值或剩余产品的生产的方法，而剩余价值或剩余产品又是积累的形成要素。因此，这些方法同时也就是资本生产资本或加速资本积累的方法。剩余价值不断再转化为资本，表现为进入生产过程的资本量的不断增长。这种增长又成为不断扩大生产规模的基础，成为随之出现的提高劳动生产力和加速剩余价值生产的方法的基础。可见，一定程度的资本积累表现为特殊的资本主义的生产方式的条件，而特殊的资本主义的生产方式又反过来引起资本的加速积累。因此，特殊的资本主义的生产方式随着资本积累而发展，资本积累又随着特殊的资本主义的生产方式而发展。这两种经济因素由于这种互相推动的复合关系，引起资本技术构成的变化，从而使资本的可变组成部分同不变组成部分相比越来越小。","language":"中文","translation":false},{"id":"capital-24-28","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"每一个资本，都是生产资料的或大或小的积聚，并且相应地指挥着一支或大或小的劳动军。每一个积累都成为新的积累的手段。这种积累随着执行资本职能的财富数量的增多而扩大这种财富在单个资本家手中的积聚，从而扩大大规模生产和特殊的资本主义的生产方法的基础。社会资本的增长是通过许多单个资本的增长来实现的。假定其他一切条件不变，各单个资本，从而生产资料的积聚，会按照它们各自在社会总资本中所占份额的比例而增长。同时，从原资本上会分出枝杈来，作为新的独立资本执行职能。在这方面，资本家家庭内部的分产起着重大作用。因此，随着资本的积累，资本家的人数也多少有所增加。这种直接以积累为基础的或不如说和积累等同的积聚，有两个特征。第一，在其他条件不变的情况下，社会生产资料在单个资本家手中积聚的增进，受社会财富增长程度的限制。第二，社会资本中固定在每个特殊生产部门的部分，分在许多资本家身上，他们作为独立的和互相竞争的商品生产者彼此对立着。所以，积累和伴随积累的积聚不仅分散在许多点上，而且执行职能的资本的增长还受到新资本的形成和旧资本的分裂的阻碍。因此，积累一方面表现为生产资料和对劳动的支配权的不断增长的积聚，另一方面，表现为许多单个资本的互相排斥。","language":"中文","translation":false},{"id":"capital-24-29","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"社会总资本这样分散为许多单个资本，或它的各部分间的互相排斥，又遇到各部分间的互相吸引的反作用。这已不再是生产资料和对劳动的支配权的简单的、和积累等同的积聚。这是已经形成的各资本的积聚，是它们的个体独立性的消灭，是资本家剥夺资本家，是许多小资本变成少数大资本。这一过程和前一过程不同的地方就在于，它仅仅以已经存在的并且执行职能的资本在分配上的变化为前提，因而，它的作用范围不受社会财富的绝对增长或积累的绝对界限的限制。资本所以能在这里，在一个人手中大量增长，是因为它在那里，在许多人手中丧失了。这是不同于积累和积聚的本来意义的集中。","language":"中文","translation":false},{"id":"capital-24-30","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"资本的这种集中或资本吸引资本的规律，不可能在这里加以阐述。简单地提一些事实就够了。竞争斗争是通过使商品便宜来进行的。在其他条件不变时，商品的便宜取决于劳动生产率，而劳动生产率又取决于生产规模。因此，较大的资本战胜较小的资本。其次，我们记得，随着资本主义生产方式的发展，在正常条件下经营某种行业所需要的单个资本的最低限量提高了。因此，较小的资本挤到那些大工业还只是零散地或不完全地占领的生产领域中去。在那里，竞争的激烈程度同互相竞争的资本的多少成正比，同互相竞争的资本的大小成反比。竞争的结果总是许多较小的资本家垮台，他们的资本一部分转入胜利者手中，一部分归于消灭。除此而外，一种崭新的力量——信用事业，随同资本主义的生产而形成起来。起初，它作为积累的小小的助手不声不响地挤了进来，通过一根根无形的线把那些分散在社会表面上的大大小小的货币资金吸引到单个的或联合的资本家手中；但是很快它就成了竞争斗争中的一个新的可怕的武器；最后，它变成一个实现资本集中的庞大的社会机构。","language":"中文","translation":false},{"id":"capital-24-31","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"随着资本主义生产和积累的发展，竞争和信用——集中的两个最强有力的杠杆，也以同样的程度发展起来。同时，积累的增进又使可以集中的材料即单个资本增加，而资本主义生产的扩大，又替那些要有资本的预先集中才能建立起来的强大工业企业，一方面创造了社会需要，另一方面创造了技术手段。因此，现在单个资本的互相吸引力和集中的趋势比以往任何时候都更加强烈。虽然集中运动的相对广度和强度在一定程度上由资本主义财富已经达到的数量和经济机构的优越性来决定，但是集中的进展决不取决于社会资本的实际增长量。这正是集中和积聚特别不同的地方，因为积聚不过是规模扩大的再生产的另一种表现而已。集中可以通过单纯改变既有资本的分配，通过单纯改变社会资本各组成部分的量的组合来实现。资本所以能在这里，在一个人手中大量增长，是因为它在那里，在许多单个人的手中被夺走了。在一个生产部门中，如果投入的全部资本已溶合为一个单个资本时，集中便达到了极限。在一个社会里，只有当社会总资本或者合并在唯一的资本家手中，或者合并在唯一的资本家公司手中的时候，集中才算达到极限。","language":"中文","translation":false},{"id":"capital-24-32","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"集中补充了积累的作用，使工业资本家能够扩大自己的经营规模。不论经营规模的扩大是积累的结果，还是集中的结果；不论集中是通过强制的道路进行吞并，——在这种场合，某些资本成为对其他资本的占压倒优势的引力中心，打破其他资本的个体内聚力，然后把各个零散的碎片吸引到自己方面来，——还是通过建立股份公司这一比较平滑的办法把许多已经形成或正在形成的资本溶合起来，经济作用总是一样的。工业企业规模的扩大，对于更广泛地组织许多人的总体劳动，对于更广泛地发展这种劳动的物质动力，也就是说，对于使分散的、按习惯进行的生产过程不断地变成社会结合的、用科学处理的生产过程来说，到处都成为起点。","language":"中文","translation":false},{"id":"capital-24-33","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"不过很明显，积累，即由圆形运动变为螺旋形运动的再生产所引起的资本的逐渐增大，同仅仅要求改变社会资本各组成部分的量的组合的集中比较起来，是一个极缓慢的过程。假如必须等待积累去使某些单个资本增长到能够修建铁路的程度，那末恐怕直到今天世界上还没有铁路。但是，集中通过股份公司转瞬之间就把这件事完成了。集中在这样加强和加速积累作用的同时，又扩大和加速资本技术构成的变革，即减少资本的可变部分来增加它的不变部分，从而减少对劳动的相对需求。","language":"中文","translation":false},{"id":"capital-24-34","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"通过集中而在一夜之间集合起来的资本量，同其他资本量一样，不断再生产和增大，只是速度更快，从而成为社会积累的新的强有力的杠杆。因此，当人们谈到社会积累的增进时，今天已经把集中的作用包括在内。","language":"中文","translation":false},{"id":"capital-24-35","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在正常的积累进程中形成的追加资本（见第22章第1节），主要是充当利用新发明和新发现的手段，总之，是充当利用工业改良的手段。但是，随着时间的推移，旧资本总有一天也要从头到尾地更新，要脱皮，并且同样会以技术上更加完善的形式再生出来，在这种形式下，用较少量的劳动就足以推动较多量的机器和原料。由此必然引起对劳动需求的绝对减少，不言而喻，经历这种更新过程的资本越是由于集中运动而大量聚集，对劳动需求的绝对减少也就越厉害。","language":"中文","translation":false},{"id":"capital-24-36","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"可见，一方面，在积累进程中形成的追加资本，同它自己的量比较起来，会越来越少地吸引工人。另一方面，周期地按新的构成再生产出来的旧资本，会越来越多地排斥它以前所雇用的工人。","language":"中文","translation":false},{"id":"capital-24-37","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"3、相对过剩人口或产业后备军的累进生产","language":"中文","translation":false},{"id":"capital-24-38","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"资本积累最初只是表现为资本的量的扩大，但是以上我们看到，它是通过资本构成不断发生质的变化，通过减少资本的可变部分来不断增加资本的不变部分而实现的。","language":"中文","translation":false},{"id":"capital-24-39","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"特殊的资本主义的生产方式，与之相适应的劳动生产力的发展以及由此引起的资本有机构成的变化，不只是同积累的增进或社会财富的增长保持一致的步伐。它们的进展要快得多，因为简单的积累即总资本的绝对扩大，伴随有总资本的各个分子的集中，追加资本的技术变革，也伴随有原资本的技术变革。因此，随着积累的进程，资本的不变部分和可变部分的比例会发生变化；假定原来是1:1，后来会变成2:1、3:1、4:1、5:1、7:1等等，因而随着资本的增长，资本总价值转化为劳动力的部分不是1/2，而是递减为1/3、1/4、1/5、1/6、1/8等等，转化为生产资料的部分则递增为2/3、3/4、4/5、5/6、7/8等等。因为对劳动的需求，不是由总资本的大小决定的，而是由总资本可变组成部分的大小决定的，所以它随着总资本的增长而递减，而不象以前假定的那样，随着总资本的增长而按比例增加。对劳动的需求，同总资本量相比相对地减少，并且随着总资本量的增长以递增的速度减少。诚然，随着总资本的增长，总资本的可变组成部分即并入总资本的劳动力也会增加，但是增加的比例越来越小。积累表现为生产在一定技术基础上的单纯扩大的那种间歇时间缩短了。为了吸收一定数目的追加工人，甚至为了在旧资本不断发生形态变化的情况下继续雇用已经在职的工人，就不仅要求总资本以不断递增的速度加快积累。而且，这种不断增长的积累和集中本身，又成为使资本构成发生新的变化的源泉，也就是成为使资本的可变组成部分和不变组成部分相比再次迅速减少的源泉。总资本的可变组成部分的相对减少随着总资本的增长而加快，而且比总资本本身的增长还要快这一事实，在另一方面却相反地表现为，好象工人人口的绝对增长总是比可变资本即工人人口的就业手段增长得快。事实是，资本主义积累不断地并且同它的能力和规模成比例地生产出相对的，即超过资本增殖的平均需要的，因而是过剩的或追加的工人人口。","language":"中文","translation":false},{"id":"capital-24-40","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"就社会总资本来考察，时而它的积累运动引起周期的变化，时而这个运动的各个因素同时分布在各个不同的生产部门。在某些部门，由于单纯的积聚，资本的构成发生变化而资本的绝对量没有增长；在有些部门，资本的绝对增长同它的可变组成部分或它所吸收的劳动力的绝对减少结合在一起；在另一些部门，资本时而在一定的技术基础上持续增长，并按照它增长的比例吸引追加的劳动力，时而有机构成发生变化，资本的可变组成部分缩小；在一切部门中，资本可变部分的增长，从而就业工人人数的增长，总是同过剩人口的激烈波动，同过剩人口的暂时产生结合在一起，而不管这种产生采取排斥就业工人这个较明显的形式，还是采取使追加的工人人口难于被吸入它的通常水道这个不大明显但作用相同的形式。随着已经执行职能的社会资本量的增长及其 增长程度的提高，随着生产规模和所使用的工人人数的扩大，随着他们劳动的生产力的发展，随着财富的一切源流的更加广阔和更加充足，资本对工人的更大的吸引力和更大的排斥力互相结合的规模不断扩大，资本有机构成和资本技术形式的变化速度不断加快，那些时而同时地时而交替地被卷入这些变化的生产部门的范围不断增大。因此，工人人口本身在生产出资本积累的同时，也以日益扩大的规模生产出使他们自身成为相对过剩人口的手段。这就是资本主义生产方式所特有的人口规律，事实上，每一种特殊的、历史的生产方式都有其特殊的、历史地起作用的人口规律。抽象的人口规律只存在于历史上还没有受过人干涉的动植物界。","language":"中文","translation":false},{"id":"capital-24-41","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"过剩的工人人口是积累或资本主义基础上的财富发展的必然产物，但是这种过剩人口反过来又成为资本主义积累的杠杆，甚至成为资本主义生产方式存在的一个条件。过剩的工人人口形成一支可供支配的产业后备军，它绝对地隶属于资本，就好象它是由资本出钱养大的一样。 过剩的工人人口不受人口实际增长的限制，为不断变化的资本增殖需要创造出随时可供剥削的人身材料。随着积累和伴随积累而来的劳动生产力的发展，资本的突然扩张力也增长了，这不仅是因为执行职能的资本的伸缩性和绝对财富——资本不过是其中一个可伸缩的部分——增长了，也不仅是因为信用每当遇到特殊刺激会在转眼之间把这种财富的非常大的部分作为追加资本交给生产支配。这还因为生产过程本身的技术条件，机器、运输工具等等，有可能以最大的规模最迅速地把剩余产品转化为追加的生产资料。随着积累的增进而膨胀起来的并且可以转化为追加资本的大量社会财富，疯狂地涌入那些市场突然扩大的旧生产部门，或涌入那些由旧生产部门的发展而引起的新兴生产部门，如铁路等等。在所有这些场合，都必须有大批的人可以突然地被投到决定性的地方去，而又不致影响其他部门的生产规模。这些人就由过剩人口来提供。现代工业特有的生活过程，由中等活跃、生产高度繁忙、危机和停滞这几个时期构成的、穿插着较小波动的十年一次的周期形式，就是建立在产业后备军或过剩人口的不断形成、或多或少地被吸收、然后再形成这样的基础之上的。而工业周期的阶段变换又补充新的过剩人口，并且成为过剩人口再生产的最有力的因素之一。","language":"中文","translation":false},{"id":"capital-24-42","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"现代工业这种独特的生活过程，我们在人类过去的任何时代都是看不到的，即使在资本主义生产的幼年时期也不可能出现。那时资本构成的变化还极其缓慢。因此，对劳动的需求的增长，总的说来是同资本的积累相适应的。不管那时资本积累的增进同现代相比是多么缓慢，它还是碰到了可供剥削的工人人口的自然限制，这些限制只有通过以后将要谈到的暴力手段才能清除。生产规模突然的跳跃式的膨胀是它突然收缩的前提；而后者又引起前者，但是没有可供支配的人身材料，没有不取决于人口绝对增长的工人的增加，前者是不可能的。 工人的这种增加，是通过使一部分工人不断地被“游离”出来的简单过程，通过使就业工人人数比扩大的生产相对减少的方法造成的。因此，现代工业的整个运动形式来源于一部分工人人口不断地转化为失业的或半失业的人手。政治经济学的肤浅性也表现在，它把信用的膨胀和收缩，把工业周期各个时期更替这种单纯的征兆，看作是造成这种更替的原因。正如天体一经投入一定的运动就会不断地重复这种运动一样，社会生产一经进入交替发生膨胀和收缩的运动，也会不断地重复这种运动。而结果又会成为原因，于是不断地再生产出自身条件的整个过程的阶段变换就采取周期性的形式。这种周期性一经固定下来，那末，就连政治经济学也会把相对的，即超过资本增殖的平均需要的过剩人口的生产，看作是现代工业的生活条件。","language":"中文","translation":false},{"id":"capital-24-43","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"曾任牛津大学政治经济学教授、后来又任英国殖民部官员的赫·梅里威耳说：","language":"中文","translation":false},{"id":"capital-24-44","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“假定在危机时期国家竭力通过向国外移民的办法来摆脱几十万过剩的贫民，那结果会怎样呢？结果是，当对劳动的需求刚一恢复时，就会感到劳动不足。人的再生产不管多么快，要把成年工人补充起来，总需要有一代人的时间。可是我们的工厂主的利润主要取决于是否有能力利用畅销的有利时机，并以此来弥补滞销时期的损失。而他们只有拥有对机器和体力劳动的指挥权，才能保证有这种能力。他们必须找到可供支配的人手；他们必须能够依据市场情况在必要时加强或收缩他们的营业活动，否则他们就决不能在竞争的角逐中保持优势，而这种优势是国家财富的基础。”","language":"中文","translation":false},{"id":"capital-24-45","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"甚至马尔萨斯也承认，过剩人口对于现代工业来说是必要的，虽然他按照自己的偏狭之见，把它解释成工人人口的绝对过剩，而不是工人人口的相对过剩。他说：","language":"中文","translation":false},{"id":"capital-24-46","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“在一个主要依靠工商业的国家里，如果在工人阶级中间盛行慎重地对待结婚的习惯，那对国家是有害的…… 按人口的性质来说，即使遇到特殊需求，不经过16年或18年的时间，也不可能向市场供应追加工人。然而，收入通过节约转化为资本却可以快得多；一个国家的劳动基金比人口增长得快的情况，是经常有的。”","language":"中文","translation":false},{"id":"capital-24-47","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"政治经济学这样把工人的相对过剩人口的不断生产宣布为资本主义积累的必要条件之后，就恰如其分地以一个老处女的姿态，通过自己“最理想的人”资本家的嘴，对那些因自己创造了追加资本而被抛向街头的“过剩的人”说了如下的话：","language":"中文","translation":false},{"id":"capital-24-48","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“我们工厂主增大你们借以生存的资本，为你们做了我们所能做的事情；而你们必须去做其余的事情，去使你们的人数同生存资料相适应”。","language":"中文","translation":false},{"id":"capital-24-49","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"对资本主义生产来说，人口自然增长所提供的可供支配的劳动力数量是绝对不够的。为了能够自由地活动，它需要有一支不以这种自然限制为转移的产业后备军。","language":"中文","translation":false},{"id":"capital-24-50","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"以上我们假定，就业工人人数的增减正好同可变资本的增减相一致。","language":"中文","translation":false},{"id":"capital-24-51","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"然而，可变资本在它所指挥的工人人数不变或甚至减少的情况下也会增长。如果单个工人提供更多的劳动，因而得到更多的工资，——即使劳动价格不变，或者甚至下降，但只要下降得比劳动量的增加慢，——情况就是如此。在这种场合，可变资本的增长是劳动增加的指数，而不是就业工人增加的指数。 每一个资本家的绝对利益在于，从较少的工人身上而不是用同样低廉或甚至更为低廉的花费从较多的工人身上榨取一定量的劳动。在后一种情况下，不变资本的支出会随着所推动的劳动量成比例地增长，在前一种情况下，不变资本的增长则要慢得多。 生产规模越大，这种动机就越具有决定意义。它的力量随资本积累一同增长。","language":"中文","translation":false},{"id":"capital-24-52","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"我们已经知道，资本主义生产方式和劳动生产力的发展——既是积累的原因，又是积累的结果——使资本家能够通过从外延方面或内含方面加强对单个劳动力的剥削，在支出同样多的可变资本的情况下推动更多的劳动。其次，我们还知道，资本家越来越用不大熟练的工人排挤较熟练的工人，用未成熟的劳动力排挤成熟的劳动力，用女劳动力排挤男劳动力，用少年或儿童劳动力排挤成年劳动力，这样，他就用同样多的资本价值买到更多的劳动力。","language":"中文","translation":false},{"id":"capital-24-53","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"所以，在积累的进程中，一方面，较大的可变资本无须招收更多的工人就可以推动更多的劳动；另一方面，同样数量的可变资本用同样数量的劳动力就可以推动更多的劳动；最后，通过排挤较高级的劳动力可以推动更多低级的劳动力。","language":"中文","translation":false},{"id":"capital-24-54","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"因此，相对过剩人口的生产或工人的游离，比生产过程随着积累的增进本身而加速的技术变革，比与此相适应的资本可变部分比不变部分的相对减少，更为迅速。如果说生产资料在扩大自己的规模和作用的同时，在越来越小的程度上成为工人的就业手段，那末，这种情况本身又会由于下述事实而有所变化：劳动生产力越是增长，资本造成的劳动供给比资本对工人的需求越是增加得快。工人阶级中就业部分的过度劳动，扩大了它的后备军的队伍，而后者通过竞争加在就业工人身上的增大的压力，又反过来迫使就业工人不得不从事过度劳动和听从资本的摆布。工人阶级的一部分从事过度劳动迫使它的另一部分无事可做，反过来，它的一部分无事可做迫使它的另一部分从事过度劳动，这成了各个资本家致富的手段，〔注：甚至在1863年棉荒时期，布莱克本的纺纱工人在其散发的一本小册子中，对过度劳动也提出了强烈的指责。由于工厂法的约束，从事这种过度劳动的当然只有成年男工。“这个工厂要求成年工人每天劳动十二至十三小时，虽然有成百的人被迫无事可做，而他们又愿意劳动一部分时间，以便养家活口和防止自己的工人弟兄因过度劳动而早死。”小册子接着说，“我们要问，进行额外时间的劳动这种作法，能使主人和‘仆役’之间建立某种可以容忍的关系吗?过度劳动的牺牲者和因此而被宣告为被迫无事可做的人，同样地感到不公平。如果把劳动加以公平的分配，那末，这个地区所需完成的工作足以使所有的人都能部分地就业。我们只要求一个权利：我们请求业主们，至少在目前状况维持不变的期间，普遍缩短劳动时间，而不是使一部分人从事过度劳动，使另一部分人由于没有活干被迫靠救济来维持生活。”(《工厂视察员报告，1863年10月31日》第8页)——《论手工业和商业》的作者，以其惯有的不会弄错的资产阶级本能，来理解相对过剩人口对就业工人的影响。“在这个王国中，引起怠惰的另一个原因，就是缺少足够数量的劳动人手。只要出现对产品的某种特殊需求，而使劳动量变得不足时，工人就会感觉到自己的重要性，并且想使业主也感觉到这一点；这是令人惊奇的；但是这帮家伙的心思坏透了，每遇到这种场合，成群的工人就联合起来，终日游惰，使他们的业主陷于困境。”(《论手工业和商业》第27、28页)他是说，这帮家伙要求提高工资。〕 同时又按照与社会积累的增进相适应的规模加速了产业后备军的生产。这个因素在相对过剩人口的形成上是多么重要，可以拿英国的例子来证明。英国“节约”劳动的技术手段是十分强大的。但是，如果明天把劳动普遍限制在合理的程度，并且把工人阶级的各个阶层再按年龄和性别进行适当安排，那末，要依照现有的规模继续进行国民生产，目前的工人人口是绝对不够的。目前“非生产”工人的大多数都不得不转化为“生产”工人。","language":"中文","translation":false},{"id":"capital-24-55","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"大体说来，工资的一般变动仅仅由同工业周期各个时期的更替相适应的产业后备军的膨胀和收缩来调节。因此，决定工资的一般变动的，不是工人人口绝对数量的变动，而是工人阶级分为现役军和后备军的比例的变动，是过剩人口相对量的增减，是过剩人口时而被吸收、时而又被游离的程度。 现代工业具有十年一次的周期，每次周期又有各个周期性的阶段，而且这些阶段在积累进程中被越来越频繁地相继发生的不规则的波动所打断。对于这个现代工业来说，如果有下面这样的规律，那确实是太好了：劳动的供求不是通过资本的膨胀和收缩，因而不是按照资本当时的增殖需要来调节，以致劳动市场忽而由于资本膨胀而显得相对不足，忽而由于资本收缩而显得过剩，而是相反，资本的运动依存于人口量的绝对运动。然而，这正是经济学的教条。按照这个教条，工资因资本的积累而提高。工资的提高刺激工人人口更快地增加，这种增加一直持续到劳动市场充斥，因而资本同工人的供给比较相对不足时为止。工资下降，于是事情走向反面。由于工资的下降，工人人口逐渐减少，以致资本同工人人口比较又相对过剩了，或者象另一些人所说的那样，工资的降低和对工人剥削的相应提高，会重新加速积累，而与此同时，低工资又会抑制工人阶级的增长。这样一来，就又出现劳动供不应求、工资提高等等情况。这对于发达的资本主义生产是一个多么美好的运动方法啊！ 可是，在真正有劳动能力的人口因工资提高而可能出现某种实际增长以前，已经一再经过了这样一个时期，在这个时期必然发生工业战，展开厮杀，并且决出胜负。","language":"中文","translation":false},{"id":"capital-24-56","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1849年至1859年间，在谷物价格下降的同时，英国农业地区出现了实际考察起来只是名义上的工资提高。例如，周工资在威尔特郡由7先令提高到8先令，在多尔塞特郡由7先令或8先令提高到9先令，等等。这是农业过剩人口空前外流的结果，而人口外流是由战争的需要和铁路工程、工厂、矿山等部门的大规模扩展引起的。工资越低，它的任何提高，即使是微不足道的提高，在百分比上也表现得越高。例如，周工资是20先令，提高到22先令，就是提高10％；但如果周工资只有7先令，提高到9先令，那就是提高284/7％，这就耸人听闻了。不管怎样，租地农场主大喊大叫起来，甚至伦敦《经济学家》在谈到这些饥饿工资时，也郑重其事地胡诌什么有了“普遍的和重大的提高”。租地农场主该怎么办呢？难道他们会象教条的经济学的头脑所设想的那样，等待这种优厚的报酬促使农业工人繁殖，直到他们的工资不得不重新下降吗？不，租地农场主采用了更多的机器，工人转瞬间又“过剩”了，过剩的比例连租地农场主也感到满意了。同以前相比，现在投入农业的“资本更多了”，并且采取了生产效率更高的形式。这样一来，对劳动的需求不仅相对地下降，而且绝对地下降了。","language":"中文","translation":false},{"id":"capital-24-57","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"经济学的上述虚构，把调节工资的一般变动或调节工人阶级即总劳动力和社会总资本之间的关系的规律，同在各个特殊生产部门之间分配工人人口的规律混为一谈了。例如，由于市场情况良好，某一生产部门的积累特别活跃，利润高于平均利润，追加资本纷纷涌来，这样，对劳动的需求和工资自然就会提高。较高的工资把较大一部分工人人口吸引到这个有利的部门，直到这里劳动力达到饱和，工资终于又下降到以前的平均水平，如果工人流入过多，甚至会降到这个水平以下。那时工人流入该生产部门的现象不仅停止，甚至还会发生流出现象。在这里，政治经济学家就以为看到了，随着工资的提高，工人人数“在何处以及如何”绝对增长，而随着工人人数的绝对增长，工资“在何处以及如何”下降；但是事实上，他所看到的，只是某一特殊生产部门的劳动市场的局部波动，他所看到的，只是工人人口按照资本变化不定的需要而在各投资部门之间分配的现象。","language":"中文","translation":false},{"id":"capital-24-58","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"产业后备军在停滞和中等繁荣时期加压力于现役劳动军，在生产过剩和亢进时期又抑制现役劳动军的要求。所以，相对过剩人口是劳动供求规律借以运动的背景。它把这个规律的作用范围限制在绝对符合资本的剥削欲和统治欲的界限之内。这里正好应该回过来谈一下经济学辩护论者的一大业绩。我们记得，由于采用新机器或扩大旧机器，一部分可变资本转化为不变资本，这是“束缚”资本并从而“游离”工人的活动，而经济学辩护士却相反地把这种活动说成是为工人游离资本。只有到现在我们才能充分地评价辩护士的厚颜无耻。其实，被游离出来的，不仅有直接被机器排挤的工人，而且还有他们的代替者和企业在原有基础上实行一般扩大时通常会吸收的追加人员。现在他们全被“游离”出来，并且每一笔希望执行职能的新资本都能支配他们。不管这种资本吸引的是这些工人，还是另一些工人，只要这笔资本刚好足以从市场上雇走被机器抛到市场上的那么多工人，那末对劳动的总需求的影响就等于零。如果它雇用的人数较少，过剩的人数就会增加；如果它雇用的人数较多，劳动总需求增加的幅度也只不过等于就业的人超过“被游离的人”的那个差额。可见，寻求投资场所的追加资本本来会激起的劳动总需求的增加，在以上每一种场合都会按照工人被机器抛向街头的程度而受到抵销。因此，这也就是说，资本主义生产的机构已安排好，不让资本的绝对增长伴有劳动总需求的相应增加。而辩护士们就把这叫作对于被排挤的工人在被抛入产业后备军的过渡时期中遭受贫困、痛苦和可能死亡的一种补偿！劳动的需求同资本的增长并不是一回事，劳动的供给同工人阶级的增长也不是一回事，所以，这里不是两种彼此独立的力量互相影响。骰子是假造的。资本在两方面同时起作用。它的积累一方面扩大对劳动的需求，另一方面又通过“游离”工人来扩大工人的供给，与此同时，失业工人的压力又迫使就业工人付出更多的劳动，从而在一定程度上使劳动的供给不依赖于工人的供给。劳动供求规律在这个基础上的运动成全了资本的专制。因此，一旦工人识破秘密，知道了他们为什么劳动越多，为别人生产的财富越多，他们的劳动生产力越是提高，他们连充当资本增殖手段的职能也就越是没有保障；一旦工人发现，他们本身之间竞争的激烈程度完全取决于相对过剩人口的压力；一旦工人因此试图通过工联等等在就业工人和失业工人之间组织有计划的合作，来消除或削弱资本主义生产的那种自然规律对他们这个阶级所造成的毁灭性的后果，这时，资本和它的献媚者政治经济学家就大吵大叫起来，说这是违反了“永恒的”和所谓“神圣的”供求规律。也就是说，就业工人和失业工人之间的任何联合都会破坏这个规律的“纯粹的”作用。另一方面，例如在殖民地，只要有不利的情况妨碍建立产业后备军，从而妨碍工人阶级绝对地隶属于资本家阶级，资本就会同它的庸俗的桑科·判札一道起来反叛“神圣的”供求规律，并企图用强制手段来阻碍它发挥作用。","language":"中文","translation":false},{"id":"capital-24-59","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"4、相对过剩人口的各种存在形式。资本主义积累的一般规律","language":"中文","translation":false},{"id":"capital-24-60","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"相对过剩人口是形形色色的。每个工人在半失业或全失业的时期，都属于相对过剩人口。工业周期阶段的更替使相对过剩人口具有显著的、周期反复的形式，因此相对过剩人口时而在危机时期急剧地表现出来，时而在营业呆滞时期缓慢地表现出来。如果撇开这些形式不说，那末，过剩人口经常具有三种形式：流动的形式、潜在的形式和停滞的形式。","language":"中文","translation":false},{"id":"capital-24-61","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在现代工业的中心——工厂、制造厂、冶金厂、矿山等等，工人时而被排斥，时而在更大的规模上再被吸引，因此总的说来，就业人数是增加的，虽然增加的比率同生产规模相比不断缩小。在这里，过剩人口处于流动的形式。","language":"中文","translation":false},{"id":"capital-24-62","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"无论在真正的工厂中，还是在一切使用机器或者甚至仅仅实行现代分工的大工场中，都需要大量的还没有脱离少年期的男工。少年期一过，便只剩下极少数的人能够被原生产部门继续雇用，而大多数的人通常要被解雇。他们成了流动过剩人口的一个要素，这个要素随着工业规模的扩大而增大。其中一部分人移居国外，其实不过是跟着外流的资本流出去。由此造成的后果之一，是女性人口比男性人口增长得快，英格兰就是一个例子。工人数量的自然增长不能满足资本积累的需要，但同时又超过这种需要，这是资本运动本身的一个矛盾。资本需要的少年工人数量较大，成年工人数量较小。比这个矛盾更引人注目的是另一个矛盾：在成千上万的人手流落街头的同时，却有人抱怨人手不足，因为分工把人手束缚在一定的生产部门了。此外，资本消费劳动力是如此迅速，以致工人到了中年通常就已经多少衰老了。他落入过剩者的队伍，或者从较高的等级被排挤到较低的等级。我们看到，正是大工业中的工人寿命最短。","language":"中文","translation":false},{"id":"capital-24-63","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“曼彻斯特保健医官李医生证实，该市富裕阶级的平均寿命是38岁，而工人阶级的平均寿命只有17岁。在利物浦，前者是35岁，后者是15岁。可见，特权阶级的寿命比他们的不那么幸运的同胞的寿命要长一倍以上。”","language":"中文","translation":false},{"id":"capital-24-64","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在这种情况下，这部分无产阶级的绝对增长就需要采取这样一种形式：它的成员迅速耗损，但是它的人数不断增大。这样就需要工人一代一代地迅速更替。（这个规律对人口中的其他阶级是不适用的。）这种社会需要，是通过早婚这一大工业工人生活条件的必然后果，并通过榨取工人子女以奖励工人生育子女的办法来得到满足的。","language":"中文","translation":false},{"id":"capital-24-65","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"资本主义生产一旦占领农业，或者依照它占领农业的程度，对农业工人人口的需求就随着在农业中执行职能的资本的积累而绝对地减少，而且对人口的这种排斥不象在非农业的产业中那样，会由于更大规模的吸引而得到补偿。因此，一部分农村人口经常准备着转入城市无产阶级或制造业无产阶级的队伍，经常等待着有利于这种转化的条件。（这里所说的制造业是指一切非农业的产业。）因此，相对过剩人口的这一源泉是长流不息的。但是，它不断地流向城市是以农村本身有经常潜在的过剩人口为前提的，这种过剩人口的数量只有在排水渠开放得特别大的时候才能看得到。因此，农业工人的工资被压到最低限度，他总是有一只脚陷在需要救济的泥潭里。","language":"中文","translation":false},{"id":"capital-24-66","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"第三类相对过剩人口，停滞的过剩人口，形成现役劳动军的一部分，但是就业极不规则。因此，它为资本提供了一个贮存着可供支配的劳动力的取之不竭的蓄水池。这种劳动力的生活状况降到了工人阶级的平均正常水平以下，正是这种情况使它成为资本的特殊剥削部门的广泛基础。它的特点是劳动时间最长而工资最低。它的主要形式，我们在家庭劳动一节中已经看到了。它不断地从大工业和农业的过剩者那里得到补充，特别是从那些由于手工业生产被工场手工业生产打垮，或者工场手工业生产被机器生产打垮而没落的工业部门那里得到补充。它的数量随着由积累的规模和能力的增大造成的“过剩”工人的增长而增加。但是，它同时又是工人阶级中会自行再生产和繁衍不息的要素，它在工人阶级的增长总额中所占的比重大于其他要素。实际上，不仅出生和死亡的数量，而且家庭人口的绝对量都同工资的水平，即各类工人所支配的生活资料量成反比。资本主义社会的这个规律，在野蛮人中间，或者甚至在文明的移民中间，听起来会是荒谬的。它使人想起各种个体软弱的、经常受到追捕的动物的大量再生产。〔注：“贫困似乎会促进繁殖。”(亚·斯密)在风流才子加利阿尼神甫看来，这甚至是上市特别英明的安排：“上帝安排好了，让从事最有益的职业的人生得绰绰有余”(加利阿尼《货币论》第4卷第78页)。“贫困在达到引起饥馑和瘟疫的极限以前，与其说会妨碍人口的增长，不如说会促进人口的增长。”(赛·兰格《国家的贫困》1844年版第69页)兰格用统计材料说明了这个论点之后，又继续说道：“如果世界上所有的人都生活在舒适安乐的环境中，那末世界上很快就会荒无人烟。”〕","language":"中文","translation":false},{"id":"capital-24-67","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"最后，相对过剩人口的最底层陷于需要救济的赤贫的境地。撇开流浪者、罪犯和妓女，一句话，撇开真正的流氓无产阶级不说，这个社会阶层由三类人组成。第一类是有劳动能力的人。只要粗略地浏览一下英格兰需要救济的贫民的统计数字，就会发现，他们的人数每当危机发生时就增大，每当营业复苏时就减少。第二类是孤儿和需要救济的贫民的子女。他们是产业后备军的候补者，在高度繁荣时期，如在1860年，他们迅速地大量地被卷入现役劳动军的队伍。第三类是衰败的、流落街头的、没有劳动能力的人。属于这一类的，主要是因分工而失去灵活性以致被淘汰的人，还有超过工人正常年令的人，最后还有随着带有危险性的机器、采矿业、化学工厂等等的发展而人数日益增多的工业牺牲者，如残废者、病人、寡妇等等。需要救济的赤贫形成现役劳动军的残废院，形成产业后备军的死荷重。〔注：“死荷重”是运输业的用语，指运输工具自身的重量。〕 它的生产包含在相对过剩人口的生产中，它的必然性包含在相对过剩人口的必然性中，它和相对过剩人口一起，形成财富的资本主义生产和发展的一个存在条件。它是资本主义生产的一项非生产费用，但是，资本知道怎样把这项费用的大部分从自己的肩上转嫁到工人阶级和下层中产阶级的肩上。","language":"中文","translation":false},{"id":"capital-24-68","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"社会的财富即执行职能的资本越大，它的增长的规模和能力越大，从而无产阶级的绝对数量和他们的劳动生产力越大，产业后备军也就越大。可供支配的劳动力同资本的膨胀力一样，是由同一些原因发展起来的。因此，产业后备军的相对量和财富的力量一同增长。但是同现役劳动军相比，这种后备军越大，常备的过剩人口也就越多，他们的贫困同他们所受的劳动折磨成正比。最后，工人阶级中贫苦阶层和产业后备军越大，官方认为需要救济的贫民也就越多。这就是资本主义积累的绝对的、一般的规律。象其他一切规律一样，这个规律在实现中也会由于各种各样的情况而有所变化，不过对这些情况的分析不属于这里的范围。","language":"中文","translation":false},{"id":"capital-24-69","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"我们可以明白，当经济学的智者们向工人说教，要工人使自己的人数去适应资本增殖的需要时，他们是多么愚蠢。资本主义生产和积累的机构在不断地使这个人数适应资本增殖的需要。这种适应的开头是创造出相对过剩人口或产业后备军，结尾是现役劳动军中不断增大的各阶层的贫困和需要救济的赤贫的死荷重。","language":"中文","translation":false},{"id":"capital-24-70","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"由于社会劳动生产率的增进，花费越来越少的人力可以推动越来越多的生产资料，这个规律在不是工人使用劳动资料，而是劳动资料使用工人的资本主义的基础上表现为：劳动生产力越高，工人对他们自己就业手段的压力就越大，因而他们的生存条件，即为增加别人财富或为资本自行增殖而出卖自己的力气，也就越没有保障。因此，生产资料和劳动生产率比生产人口增长得快的事实，在资本主义下却相反地表现为：工人人口总是比资本的增殖需要增长得快。","language":"中文","translation":false},{"id":"capital-24-71","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"我们在第四篇分析相对剩余价值的生产时已经知道，在资本主义体系内部，一切提高社会劳动生产力的方法都是靠牺牲工人个人来实现的；一切发展生产的手段都变成统治和剥削生产者的手段，都使工人畸形发展，成为局部的人，把工人贬低为机器的附属品，使工人受劳动的折磨，从而使劳动失去内容，并且随着科学作为独立的力量被并入劳动过程而使劳动过程的智力与工人相异化；这些手段使工人的劳动条件变得恶劣，使工人在劳动过程中屈服于最卑鄙的可恶的专制，把工人的生活时间变成劳动时间，并且把工人的妻子儿女都抛到资本的札格纳特车轮下。但是，一切生产剩余价值的方法同时就是积累的方法，而积累的每一次扩大又反过来成为发展这些方法的手段。由此可见，不管工人的报酬高低如何，工人的状况必然随着资本的积累而日趋恶化。最后，使相对过剩人口或产业后备军同积累的规模和能力始终保持平衡的规律把工人钉在资本上，比赫斐斯塔司的楔子把普罗米修斯钉在岩石上钉得还要牢。这一规律制约着同资本积累相适应的贫困积累。因此，在一极是财富的积累，同时在另一极，即在把自己的产品作为资本来生产的阶级方面，是贫困、劳动折磨、受奴役、无知、粗野和道德堕落的积累。","language":"中文","translation":false},{"id":"capital-24-72","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"政治经济学家们以各种不同的形式说出了资本主义积累的这种对抗性质，虽然他们把它同资本主义前的生产方式的那些尽管部分地相类似但本质上不同的现象混同起来。","language":"中文","translation":false},{"id":"capital-24-73","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"十八世纪的一位大经济学著作家、威尼斯的修道士奥特斯，把资本主义生产的对抗性理解为社会财富的普遍的自然规律。","language":"中文","translation":false},{"id":"capital-24-74","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“在一个国家里，经济上的善和经济上的恶总是保持平衡，一些人财富的充裕总是与另一些人财富的贫乏相抵。一些人享有巨大财富，同时总伴有更多得多的其他人被完全剥夺必需品。一个国家的财富同它的人口相适应，而它的贫困则同它的财富相适应。一些人勤劳迫使另一些人懒惰。穷人和懒惰者，是富人和勤劳者所造成的一个必然结果”等等。","language":"中文","translation":false},{"id":"capital-24-75","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在奥特斯之后大约过了10年，高教会新教牧师唐森，曾十分露骨地颂扬贫困是财富的必要条件。","language":"中文","translation":false},{"id":"capital-24-76","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“用法律来强制劳动，会引起过多的麻烦、暴力和叫嚣，而饥饿不仅是和平的、无声的和持续不断的压力，而且是刺激勤勉和劳动的最自然的动力，会唤起最大的干劲。”","language":"中文","translation":false},{"id":"capital-24-77","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"所以，一切问题都归结为怎样使工人阶级的饥饿永久化，而照唐森的看法，那个特别在穷人中起作用的人口原理已经把这件事安排好了。","language":"中文","translation":false},{"id":"capital-24-78","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“这似乎是一个自然规律：穷人在一定程度上是轻率的〈也就是说，他们是如此轻率，嘴里没有衔着金羹匙就降生到世界上来〉，所以，总是有一些人去担任社会上最卑微、最肮脏和最下贱的职务。于是，人类的幸福基金大大增加，比较高雅的人们解除了烦劳，可以不受干扰地从事比较高尚的职业等等…… 济贫法有一种趋势，就是要破坏上帝和自然在世界上所创立的这个制度的和谐与优美、均称与秩序。”","language":"中文","translation":false},{"id":"capital-24-79","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"威尼斯的修道士从使贫困永久化的命运中，找到基督教的善行、终身不婚、修道院和慈善机关存在的理由，而这位新教的牧师却从其中找到借口，来诅咒使穷人有权享受少得可怜的社会救济的法律。施托尔希说：","language":"中文","translation":false},{"id":"capital-24-80","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“社会财富的增长产生出那个有用的社会阶级……它从事最单调、最下贱和最令人厌恶的职业，一句话，它把生活中一切不愉快的、受奴役的事情担在自己的肩上，从而使其他阶级有闲暇，有开阔的心境和传统的〈妙！〉高贵品性……”","language":"中文","translation":false},{"id":"capital-24-81","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"施托尔希问自己：这种伴随有群众贫困和堕落的资本主义文明，同野蛮相比究竟有什么优越性呢？他只找到一个答案：安全！西斯蒙第说：","language":"中文","translation":false},{"id":"capital-24-82","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“由于工业和科学的进步，每一个工人每天所能生产的东西比他自己消费所需要的东西多得多。但是，在他的劳动生产财富的同时，如果叫他自己去消费这个财富，那末这个财富就会使他不适宜于劳动了。”他认为，“如果人们〈即非工人〉必须象工人那样不倦地劳动才能获得技艺的一切改良和工业给我们带来的一切享受，那末他们大概会放弃这些东西…… 在今天，努力同它的报酬分开了；不是同一个人先劳动而后休息，相反地，正是因为一个人劳动，另一个人才休息…… 因此，劳动生产力的无限增长的结果，只能增加那些游手好闲的富人的奢侈和享受。”","language":"中文","translation":false},{"id":"capital-24-83","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"最后，冷血的资产阶级空论家德斯杜特·德·特拉西冷酷地 声称：","language":"中文","translation":false},{"id":"capital-24-84","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“在贫国，人民是安乐的；在富国，人民通常是贫苦的。”","language":"中文","translation":false},{"id":"capital-24-85","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"5、资本主义积累一般规律的例证","language":"中文","translation":false},{"id":"capital-24-86","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"(a) 1846—1866年的英格兰","language":"中文","translation":false},{"id":"capital-24-87","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"现代社会的任何一个时期，都不如最近二十年这样适合于研究资本主义的积累。在这个时期，真好象是福尔土纳特的钱袋被发现了。不过，在所有国家中，英格兰又是一个典型的例子，因为它在世界市场上占据首位，因为资本主义生产方式只有在这里才得到了充分的发展，最后还因为，从1846年以来自由贸易千年王国的实现，又切断了庸俗政治经济学最后的退路。我们已经在第四篇里充分谈到了生产的巨大进步，由于这种进步，这二十年中的后十年又远远超过了前十年。","language":"中文","translation":false},{"id":"capital-24-88","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"最近半世纪以来，英格兰人口的绝对增长虽然很大，但是它的相对增长或增长率却不断下降。引自官方人口调查的下列表格就可以证明。","language":"中文","translation":false},{"id":"capital-24-89","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"英格兰和威尔士每十年中人口每年增长的百分率：","language":"中文","translation":false},{"id":"capital-24-90","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1811—1821 1.533％","language":"中文","translation":false},{"id":"capital-24-91","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1821—1831 1.446％","language":"中文","translation":false},{"id":"capital-24-92","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1831—1841 1.326％","language":"中文","translation":false},{"id":"capital-24-93","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1841—1851 1.216％","language":"中文","translation":false},{"id":"capital-24-94","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1851—1861 1.141％","language":"中文","translation":false},{"id":"capital-24-95","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"另一方面，现在我们再来看看财富的增长。在这里，应纳所得税的利润、地租等等的变动情况是最可靠的依据。1853—1864年，大不列颠应纳税的利润（不包括租地农场主的和若干其他项目的利润）增长50.47％（平均每年增长4.58％），而同时期人口约增长12％。1853—1864年，应纳税的地租（包括房屋、铁路、矿山、渔场等等的地租）增加38％，每年增加3 5/12％，其中增加最快的是下列项目：","language":"中文","translation":false},{"id":"capital-24-96","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1853年到1864年收入增加 每年增加","language":"中文","translation":false},{"id":"capital-24-97","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"房屋………………………38.60％ 3.50％","language":"中文","translation":false},{"id":"capital-24-98","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"采石场……………………84.76％ 7.70％","language":"中文","translation":false},{"id":"capital-24-99","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"矿山………………………68.85％ 6.26％","language":"中文","translation":false},{"id":"capital-24-100","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"铸铁厂……………………39.92％ 3.63％","language":"中文","translation":false},{"id":"capital-24-101","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"渔场………………………57.37％ 5.21％","language":"中文","translation":false},{"id":"capital-24-102","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"煤气厂………………… 126.02％ 11.45％","language":"中文","translation":false},{"id":"capital-24-103","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"铁路………………………83.29％ 7.57％","language":"中文","translation":false},{"id":"capital-24-104","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"如果把1853—1864年这段时间以每四年为一期作一比较，就会看出，收入的增长程度是不断提高的。例如，利润的收入，1853—1857年期间每年增加1.73％，1857—1861年期间每年增加2.74％，1861—1864年期间每年增加9.30％。联合王国应纳所得税的收入总额，1856年为307,068,898镑，1859年为328,127,416镑，1862年为351,745,241镑，1863年为359,142,897镑，1864年为362,462,279镑，1865年为385,530,020镑。 资本积累的同时伴随有资本的积聚和集中。虽然英格兰没有官方的农业统计材料（爱尔兰倒有），但是有10个郡自动提供了统计材料。根据这些统计材料可以看出：1851年到1861年，100英亩以下的租地农场从31583个减少到26567个，也就是说，有5016个合并于较大的租地农场了。1815年到1825年，在应纳遗产税的动产中还没有一份超过100万镑的，但是从1825年到1855年，就有了8份，从1855年到1859年6月，也就是4年半的时间里，又有了4份。简单地分析一下1864年和1865年的D项所得税（把租地农场主等等除外的利润），可以极为明显地看出这种集中。首先应该指出，这种来源的收入达到60镑就要交纳所得税。在英格兰、威尔士和苏格兰，这种应纳税的收入1864年为95,844,222镑，1865年为105,435,787镑，纳税的人数1864年在居民总数23,891,009人中是308,416人，1865年在居民总数24,127,003人中是332,431人。","language":"中文","translation":false},{"id":"capital-24-105","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"联合王国的煤产量，1855年为61,453,079吨，价值16,113,267镑，1864年为92,787,873吨，价值23,197,968镑；生铁产量，1855年为3,218,154吨，价值8,045,385镑，1864年为4,767,951吨，价值11,919,877镑。联合王国的营业铁路里程，1854年为8054哩，投入资本286,068,794镑，1864年为12789哩，投入资本425,719,613镑。联合王国的进出口总额，1854年为268,210,145镑，1865年为489,923,285镑。出口的变动情况如下表：","language":"中文","translation":false},{"id":"capital-24-106","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1847年 58,842,377镑","language":"中文","translation":false},{"id":"capital-24-107","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1849年 63,596,052镑","language":"中文","translation":false},{"id":"capital-24-108","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1856年 115,826,948镑","language":"中文","translation":false},{"id":"capital-24-109","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1860年 135,842,817镑","language":"中文","translation":false},{"id":"capital-24-110","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1865年 165,862,402镑","language":"中文","translation":false},{"id":"capital-24-111","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1866年 188,917,563镑","language":"中文","translation":false},{"id":"capital-24-112","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"根据这些为数不多的材料，我们已经可以理解为什么英国国民中央注册局局长发出这样一种胜利的欢呼了：","language":"中文","translation":false},{"id":"capital-24-113","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“人口的增加固然迅速，但它赶不上工业和财富的增长”。","language":"中文","translation":false},{"id":"capital-24-114","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"现在让我们再来看看这种工业的直接代表，或这种财富的生产者，即工人阶级。格莱斯顿说：","language":"中文","translation":false},{"id":"capital-24-115","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“我国社会状况最令人感到忧虑的特点之一就是，国民的消费力在下降，工人阶级的困苦和贫穷在加剧，而与此同时，上层阶级的财富不断积累，资本不断增长。”","language":"中文","translation":false},{"id":"capital-24-116","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这位假献殷勤的大臣1843年2月13日在下院是这样说的。过了二十年，在1863年4月16日，他在预算演说中又说：","language":"中文","translation":false},{"id":"capital-24-117","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“从1842年到1852年，国内应该课税的收入增加了6％…… 在从1853年到1861年的8年内，如以1853年的收入为基础，则增加了20％。事实令人惊奇得几乎到了难以置信的程度…… 财富和实力这样令人陶醉的增长……完全限于有产阶级，但是……但是这种增长对工人居民也一定有间接的好处，因为它会降低日用消费的价格，——富人虽然更富了，穷人至少也不那么穷了。不过我不敢断定穷的极端程度已经缩小”。","language":"中文","translation":false},{"id":"capital-24-118","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"多么拙劣的诡辩！如果说工人阶级仍然“穷”，只是随着他们给有产阶级创造的“财富和实力的令人陶醉的增长”而变得“不那么穷”了，那也就是说，工人阶级相对地还是象原来一样穷。如果说穷的极端程度没有缩小，那末，穷的极端程度就增大了，因为富的极端程度已经增大。至于说到生活资料价格的降低，那末官方的统计材料，例如伦敦孤儿院的材料却表明，1860—1862年3年间的生活资料价格平均比1851—1853年3年间上涨了20％。在随后的3年中，即1863—1865年，肉类、油类、奶类、糖、盐、煤以及 其他许多必要的生活资料的价格又继续上涨了。 格莱斯顿在1864年4月7日所做的下一个预算演说，是一首对赚钱事业的进步和因“贫穷”而减色的国民幸福的品得式的赞歌。他谈到“处于需要救济的赤贫边缘”的群众，谈到“工资没有提高的”行业，最后，他用下面这样的话概括了工人阶级的幸福：","language":"中文","translation":false},{"id":"capital-24-119","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“人的生活十有八九都纯粹是为生存而挣扎”。","language":"中文","translation":false},{"id":"capital-24-120","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"不象格莱斯顿那样受官方考虑的约束的福塞特教授则直截了当地说：","language":"中文","translation":false},{"id":"capital-24-121","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“自然我并不否认，货币工资随着资本的这种增加〈最近几十年〉而有所提高，但是，由于许多生活必需品日益昂贵〈他认为这是由于贵金属贬值造成的〉，这种表面上的利益在很大程度上都丧失了…… 富人迅速地变得更富了，而工人阶级的生活却没有什么可以觉察得出来的改善…… 工人几乎成了小店主的奴隶，他们都是小店主的债务人。”〔注：工人越来越依赖于小店主，这是工人就业方面越来越多的变动和中断的结果。〕 在论述工作日和机器的那几篇里，我们揭示了不列颠工人阶级是在怎样的条件下为有产阶级创造了“财富和实力的令人陶醉的增长”。不过我们那时考察的，主要是执行社会职能时的工人。为了全面说明积累的规律，还必须考察工人在厂外的状况，考察他们营养和居住的状况。由于本书篇幅所限，我们在这里主要考察工业无产阶级和农业工人中报酬最微薄的部分，也就是考察工人阶级的大多数。","language":"中文","translation":false},{"id":"capital-24-122","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在这以前，我还要简单谈一谈官方认为需要救济的贫民，也就是工人阶级中丧失了出卖劳动力这个生存条件而靠社会施舍度日的那部分人。在英格兰，官方认为需要救济的贫民的人数1855年是851,369人，1856年是877,767人，1865年是971,433人。由于棉荒，1863年和1864年这种贫民的人数分别增加到1,079,382人和1,014,978人。1866年的危机使伦敦遭到了最沉重的打击，在这个居民比苏格兰王国还要多的世界市场中心，这种贫民的人数1866年比1865年增加了19.5％，比1864年增加了24.4％，而在1867年的头几个月比1866年增加得还多。在分析需要救济的贫民的统计数字时必须指出两点。一方面，这种贫民人数的增减运动反映着工业周期各阶段的变换。另一方面，随着资本的积累，阶级斗争日益发展，工人的觉悟日益提高，关于需要救济的贫民实际人数的官方统计也就越来越带有欺骗性。例如，最近两年来英国报刊（《泰晤士报》、《派尔－麦尔新闻》等）大声叫嚷的虐待需要救济的贫民的现象，是早就存在的。弗·恩格斯在1844年就叙述过完全相同的惨状和完全相同的“应时文学”喧闹一时的 伪善呼叫。不过，最近十年伦敦饿死的人数惊人地增加了，这无疑证明工人是更加憎恶贫民习艺所这种贫民监狱的奴役了。","language":"中文","translation":false},{"id":"capital-24-123","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"(b)不列颠工业工人阶级中报酬微薄的阶层","language":"中文","translation":false},{"id":"capital-24-124","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"现在我们来考察工业工人阶级中报酬微薄的阶层。1862年棉荒时期，枢密院委派斯密斯医生调查了郎卡郡和柴郡的衰弱的棉纺织工人的营养状况。根据过去多年的观察，斯密斯曾得出过这样的结论：“为了避免饥饿病”，每个中常妇女一天的营养，最低限度必须包含3900克冷碳素，180克冷氮素，每个中常男子一天的营养，最低限度必须包含4300克冷碳素，200克冷氮素，这就是说，一个妇女需要的养料大致等于2磅上等小麦面包所含的养料，男子需要的还要多1/9。成年男女平均每周最低限度需要28600克冷碳素和1330克冷氮素。他的计算在实际生活中惊人地得到了证实：他的计算同棉纺织工人消费的营养量因贫困而被压低到的可怜水平是相一致的。1862年12月，棉纺织工人每周得到的碳素是29211克冷，氮素是1295克冷。","language":"中文","translation":false},{"id":"capital-24-125","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1863年，枢密院下令调查英国工人阶级中营养最差的那部分人的贫困状况。枢密院医官西蒙医生选派了上述那位斯密斯医生担任这项工作。他的调查范围一方面包括农业工人，另一方面包 括丝织工人、女缝工、皮手套工人、织袜工人、织手套工人和制鞋工人。后一方面的各类工人，除织袜工人外，全是城市工人。按照调查的惯例，选择的对象是每一类工人中最健康的和境况比较好的家庭。","language":"中文","translation":false},{"id":"capital-24-126","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“调查过的各类城市工人中，只有一类工人消费的氮素略微超过那个免于患饥饿病的绝对最低量；有两类工人氮素和碳素营养都感不足，而其中一类相差很多；调查过的农业家庭中，有1/5以上得到的碳素营养少于必要量，有1/3以上得到的氮素营养少于必要量；有三个郡（伯克郡、牛津郡、索美塞特郡）普遍缺乏最低限度的氮素营养。”","language":"中文","translation":false},{"id":"capital-24-127","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在农业工人中，联合王国最富庶的地区英格兰的农业工人营养最差。农业工人中缺乏营养的主要又是妇女和儿童，因为“男人要去干活，总得吃饭”。在调查过的各类城市工人中，营养缺乏的程度更为严重。“他们的饮食非常坏，以致必然发生许多严重的有害健康的不足现象。”（这一切都是资本家的“禁欲”！也就是连勉强糊口所必不可少的生活资料都节省下来不付给他的工人！）","language":"中文","translation":false},{"id":"capital-24-128","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"下表表明，上述各类纯粹城市工人的营养状况同斯密斯医生假定的最低营养量，以及同棉纺织工人最贫困时期的营养状况的对比。","language":"中文","translation":false},{"id":"capital-24-129","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"调查过的各类工业工人中，有半数即60/125完全得不到啤酒，28％得不到牛奶。平均每周消费的流质食物量，最低的是女缝工的家庭，只有7盎斯，最高的是织袜工人的家庭，有24 3/4盎斯。完全得不到牛奶的人当中，大部分是伦敦的女缝工。每周消费的面包量，最低的是女缝工，只有7 3/4磅，最高的是制鞋工人，有11 1/4磅，每个成年人每周消费的平均总量是9.9磅。糖（糖浆等等）每周的消费量，最低的是皮手套工人，只有4盎斯，最高的是织袜工人，有11盎斯；所有各类中每个成年人平均每周消费的总量是8盎斯。每个成年人平均每周的奶油（脂肪等等）消费总量是5盎斯。每个成年人平均每周的肉类（腊肉等等）消费量，最低是丝织工人，只有7 1/4盎斯，最高是皮手套工人，有18 1/4盎斯；各类工人每人消费的平均总量是13.6盎斯。每个成年人每周的饮食费大致平均如下：丝织工人2先令2 1/2便士，女缝工2先令7便士，皮手套工人2先令9 1/2便士，制鞋工人2先令7 3/4便士，织袜工人2先令6 1/4便士。麦克尔士菲尔德丝织工人的饮食费平均每周只有1先令8 1/2便士。营养最差的是女缝工、丝织工人和皮手套工人。","language":"中文","translation":false},{"id":"capital-24-130","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"关于这种营养状况，西蒙医生在他的总的卫生报告中说：","language":"中文","translation":false},{"id":"capital-24-131","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“由于缺乏营养而引起疾病或者加重疾病的事例是举不胜举的，任何一个熟悉贫民医疗情况，或者熟悉医院的住院或门诊病人的人都可以证实这一点…… 但是，从卫生的观点看，这里还要加上另一个非常重要的情况……应该记住，缺乏饮食是极难忍受的，而饮食的严重缺乏通常总是跟随在其他方面的不足发生之后。远在缺乏营养成为卫生问题以前，远在生理学家想到计算决定生死的氮素和碳素的克冷数以前，家庭生活中早已谈不上任何物质享受了。衣服和燃料比食物还缺。","language":"中文","translation":false},{"id":"capital-24-132","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"没有足够的抗寒能力；居住面积狭小到了引起疾病或者加重疾病的程度；家具器皿几乎一无所有；甚至保持整洁也成了破费和难于办到的事。如果出于自尊心 想保持整洁，那末任何这样的尝试都会加重饥饿的痛苦。住的地方是在房屋最便宜的地区；是在卫生警察的工作收效最少，排水沟最坏，交通最差，环境最脏，水的供给最不充分最不清洁的地区，如果是在城市的话，阳光和空气也最缺乏。当穷到连饮食都感到缺乏时，也就必然要遭到这些威胁健康的灾祸。这些灾祸加在一起对生命固然是可怕的威胁，但仅仅缺乏饮食本身就已经够骇人的了…… 这真令人痛苦，特别是，如果想到这里所说的贫困完全不是由于游手好闲而应得的贫困。这是工人的贫困。是的，说到城市工人，他们为了换取少量的食物，竟多半要使劳动延长到超出一切界限。然而，只有作极大的保留，才能说这种劳动可以使工人维持生活…… 在大多数场合，这种名义上的维持生活不过是一条或长或短的通向需要救济的赤贫的迂回道路而已。”","language":"中文","translation":false},{"id":"capital-24-133","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"最勤劳的工人阶层的饥饿痛苦和富人建立在资本主义积累基础上的粗野的或高雅的奢侈浪费之间的内在联系，只有当人们认识了经济规律时才能揭露出来。居住状况却不是这样。在这方面，任何一个公正的观察者都能看到，生产资料越是大量集中，工人也就越要相应地聚集在同一个空间，因此，资本主义的积累越迅速，工人的居住状况就越悲惨。随着财富的增长而实行的城市“改 良”是通过下列方法进行的：拆除建筑低劣地区的房屋，建造供银行和百货商店等等用的高楼大厦，为交易往来和豪华马车而加宽街道，修建铁轨马车路等等；这种改良明目张胆地把贫民赶到越来越坏、越来越挤的角落里去。 另一方面，每个人都知道，房屋的昂贵和房屋的质量成反比，房屋投机分子开采贫民这个矿山比当年开采波托西矿山花的钱还要少，赚的钱还要多。在这里，资本主义积累的对抗性质，从而整个资本主义财产关系的对抗性质〔注：“任何情况下都不象工人阶级的居住条件这样露骨这样无耻地使人权成为产权的牺牲品。每个大城市都是使人成为牺牲品的场所，都是一个祭坛，每年要屠杀成千上万的人来祭祀贪婪的摩洛赫。”（赛·兰格《国家的贫困》1844年版第150页）〕 ，表现得如此明显，就连英国官方关于这个问题的报告也都充满了对“财产和财产权”的异端攻击。随着工业的发展、资本的积累、城市的扩展和“美化”，灾祸越来越严重，以致在1847年到1864年间，仅仅由于害怕那些对“上流人士”也决不留情的传染病，议会就制定了不下十项卫生警察法令，在某些城市，如利物浦、格拉斯哥等地，吓破了胆的资产阶级还通过他们的市政当局来进行干涉。不过，西蒙医生在他的1865年的报告中仍然大声疾呼：“一般说来，这些灾祸在英国还没有控制住。”根据枢密院的命令，1864年对农业工人的居住条件进行了调查，1865年又对城市中较贫穷的阶级的居住条件进行了调查。 人们在《公共卫生》第7号和第8号报告中，可以看到朱利安·汉特医生完成的这一出色工作。关于农业工人我在后面再谈。我先引用西蒙医生总的评语来说明城市的居住状况。他说：","language":"中文","translation":false},{"id":"capital-24-134","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“虽然我的职务上的观点仅限于医学方面，然而最普通的人道不容许我忽视这种灾祸的另外一面。在灾祸达到较严重的程度时，几乎必然会使人们 不顾任何体面，造成肉体和肉体机能如此龌龊的混杂，如此毫无掩饰的性的裸露，以致使人象野兽而不象人。受这种影响会使人堕落，时间越久，堕落越深。对于在这样可诅咒的环境下出生的儿童来说，这种环境本身就是一种寡廉鲜耻的洗礼。如果想让处在这种境况下的人们在其他方面努力向上，追求以身心纯洁为本质的文明气氛，那是绝对无望的。”","language":"中文","translation":false},{"id":"capital-24-135","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"就住宅过分拥挤和绝对不适于人居住而言，伦敦首屈一指。汉特医生说：","language":"中文","translation":false},{"id":"capital-24-136","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“有两点是肯定无疑的：第一，在伦敦，大约有20个大的贫民区，每个区住1万人左右，这些人的悲惨处境超过了在英国其他任何地方所能见到的一切惨象，而这种处境几乎完全是由住宅设备恶劣造成的；第二，在这些贫民区，住房过于拥挤和破烂的情形，比20年前糟糕得多。”“即使把伦敦和新堡的许多地区的生活说成是地狱生活，也不算过分。”","language":"中文","translation":false},{"id":"capital-24-137","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在伦敦，随着城市的不断“改良”，旧街道和房屋的拆除，随着这个京城中工厂的不断增多和人口的不断流入，随着房租同城市地租一道不断地上涨，就连工人阶级中处境较好的那部分人以及小店主和其他下层中产阶级分子，也越来越陷入这种可诅咒的恶劣的居住环境中了。","language":"中文","translation":false},{"id":"capital-24-138","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“房租过高，只有少数工人才付得起一间房子以上的租金。”","language":"中文","translation":false},{"id":"capital-24-139","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在伦敦，几乎没有一所房产不寄生着无数的“中间人”。伦敦的地价总是大大高于土地的年收入，因为每个买地的人都抱着投机的目的，指望迟早会按审定价格（即征用时由陪审员确定的价格）再把地抛售出去，或者会由于靠近某个大企业而能诈取异常高的价钱。结果是，买卖快到期的租约成了一项经常的交易。","language":"中文","translation":false},{"id":"capital-24-140","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“对于从事这种营业的绅士们所能期待的，就是他们会象他们所干的那样去干——尽量从房客身上榨取一切可能榨取的东西，而把糟到不能再糟的房子留给他们的后继者。”","language":"中文","translation":false},{"id":"capital-24-141","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"房租是按周支付的，所以这些先生们不会冒任何风险。由于市内修建铁路的关系，","language":"中文","translation":false},{"id":"capital-24-142","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“不久前，我们看到伦敦东头有许多家庭从自己的旧住所里被赶出来，在一个星期六的晚上背着少得可怜的家当到处徘徊，可是除了投奔贫民习艺所，找不到任何栖身之处”。","language":"中文","translation":false},{"id":"capital-24-143","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"贫民习艺所已经人满之患，而议会批准的“改良”措施不过刚刚开始执行。如果工人因拆毁旧房而被赶了出来，那他们并不离开自己的教区，或者，最远也只是搬到紧靠原来教区的地方。","language":"中文","translation":false},{"id":"capital-24-144","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“他们自然想要尽量住在自己劳动场所的附近。结果原来住两间房的人家，现在也不得不住一间。即使出的房租比原来的高，住的房子却比他们被从中赶出来的那些糟糕的房子还要糟糕。住在滨河路的工人，有半数要走两哩路才能到达劳动场所。”","language":"中文","translation":false},{"id":"capital-24-145","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"滨河路的主要街道虽然使异乡人为伦敦的富庶而惊叹，但是这条路本身可以作为伦敦人口拥挤的例子。据保健医官计算，在滨河路的一个教区里，每英亩面积就住有581人，而且还把太晤士河的一半水面算了进去。很明显，每一项卫生警察措施，都由于拆 毁不适用的房子而把工人从某个街区赶出去，其唯一的结果就是使他们更加密集地拥挤在另一个街区，在伦敦历来就是这样。汉特医生说：","language":"中文","translation":false},{"id":"capital-24-146","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“或者是必须把这一整套办法看作荒谬的而予以停止；或者是必须唤起公众的同情〈！〉，让公众关心现在可以毫不夸大地称为国民义务的事情，这就是为那些不能出资自建房屋，但能定期交纳房租以报偿出租者的人提供住房。”","language":"中文","translation":false},{"id":"capital-24-147","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"让我们来赞美资本主义的公正吧！土地所有者、房主、实业家，在他们的财产由于进行“改良”，如修铁路、修新街道等等而被征用时，不仅可以得到充分的赔偿，而且按照上帝的意旨和人间的法律，他们还要得到一大笔利润，作为对他们迫不得已实行“禁欲”的安慰。而工人及其妻子儿女连同全部家当却被抛到大街上来，如果他们过于大量地拥到那些市政当局要维持市容的市区，他们还要遭到卫生警察的起诉！","language":"中文","translation":false},{"id":"capital-24-148","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"十九世纪初，在英国除伦敦外再没有一个10万人口的城市。只有5个城市超过5万人。而现在，超过5万人的城市已有28个。","language":"中文","translation":false},{"id":"capital-24-149","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“这种变化的结果，不仅是城市人口大量增加，而且原先人口稠密的小城市现在也变成了中心，四周建筑起许多房屋，挤得简直没有地方让空气自由流通。这里已不再合富人的心意了，于是他们搬到爽心悦目的郊外去。继这些富人之后而来的住户，住进这些较大的房子里，每家一间，往往还要再收房客。这样一来，居民就都被塞到不是专为他们盖的、完全不适合他们住的房子里，周围的环境的确会使成年人堕落，使儿童毁灭。”","language":"中文","translation":false},{"id":"capital-24-150","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"一个工业城市或商业城市的资本积累得越快，可供剥削的人身材料的流入也就越快，为工人安排的临时住所也就越坏。因此，产量不断增加的煤铁矿区的中心太恩河畔新堡，是一座仅次于伦敦而居第二位的住宅地狱。那里住小单间房屋的不下34000人。在新堡和格茨黑德，不久前大量的房屋由于绝对有害公益，根据警察的命令拆毁了。可是新房子盖得很慢，而营业却发展得很快。因此，1865年，城市比过去任何时候都更加拥挤不堪。简直难得有一间招租的小单间。新堡热病医院的恩布尔顿医生说：","language":"中文","translation":false},{"id":"capital-24-151","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“毫无疑问，伤寒病持续和蔓延的原因，是人们住得过于拥挤和住房肮脏不堪。工人常住的房子都在偏街陋巷和大院里。从光线、空气、空间、清洁各方面来说，简直是不完善和不卫生的真正典型，是任何一个文明国家的耻辱。男人、妇女、儿童夜晚混睡在一起。男人们上日班和上夜班的你来我往，川流不息，以致床铺难得有变冷的时候。这些住房供水不良，厕所更坏，肮脏，不通风，成了传染病的发源地。”","language":"中文","translation":false},{"id":"capital-24-152","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这样的洞窟，每周房租也从8便士涨到了3先令。汉特医生说：","language":"中文","translation":false},{"id":"capital-24-153","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“太恩河畔新堡是一个例子，说明我们同胞中最优秀的一部分，由于房屋和街道这些外部环境，往往沉沦到接近野蛮的退化状态。”","language":"中文","translation":false},{"id":"capital-24-154","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"由于资本和劳动的大量流动，一个工业城市的居住状况今天还勉强过得去，明天就可能变得恶劣不堪。或者，有时市政官员终于能振作起来去消除最恶劣的弊端，然而明天，衣衫褴褛的爱尔兰人或者破落的英格兰农业工人就会象蝗虫一样成群地拥来。人们把他们塞到地下室和仓库里，或者把过去还象样的工人住房变成一种寓所，在这里住客变动得非常迅速，就象三十年战争时期的营房一样。布莱得弗德就是一个例子。那里的市政当局的凡夫俗子们正在从事城市改革。1861年那里还有1751栋没有住人 的房子。但是现在营业兴旺起来了，关于这种情况，黑人之友、温和的自由主义者福斯特先生最近曾经文雅地谈到过。自然，随着营业的兴旺，那里也就被不断起伏的“后备军”或“相对过剩人口”的浪潮所淹没。汉特医生从一家保险公司代办所得到一张表格〔注：布莱得弗德某工人保险公司的代办所的一张表格：","language":"中文","translation":false},{"id":"capital-24-155","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"火神街122号………………………………1间房 16人","language":"中文","translation":false},{"id":"capital-24-156","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"拉姆利街13号………………………………1间房 11人","language":"中文","translation":false},{"id":"capital-24-157","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"鲍威尔街41号………………………………1间房 11人","language":"中文","translation":false},{"id":"capital-24-158","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"波特兰街112号………………………………1间房 10人","language":"中文","translation":false},{"id":"capital-24-159","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"哈尔迪街17号………………………………1间房 10人","language":"中文","translation":false},{"id":"capital-24-160","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"北街18号……………………………………1间房 16人","language":"中文","translation":false},{"id":"capital-24-161","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"北街17号……………………………………1间房 13人","language":"中文","translation":false},{"id":"capital-24-162","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"魏曼街19号…………………………………1间房 8个成年人","language":"中文","translation":false},{"id":"capital-24-163","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"乔威特街56号………………………………1间房 12人","language":"中文","translation":false},{"id":"capital-24-164","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"乔治街150号………………………………1间房 3家","language":"中文","translation":false},{"id":"capital-24-165","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":165,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"莱福场马丽门11号…………………………1间房 11人","language":"中文","translation":false},{"id":"capital-24-166","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":166,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"马歇尔街28号………………………………1间房 10人","language":"中文","translation":false},{"id":"capital-24-167","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":167,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"马歇尔街49号………………………………3间房 3家","language":"中文","translation":false},{"id":"capital-24-168","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":168,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"乔治街128号…………………………………1间房 18人","language":"中文","translation":false},{"id":"capital-24-169","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":169,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"乔治街130号…………………………………1间房 16人","language":"中文","translation":false},{"id":"capital-24-170","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":170,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"爱德华街4号…………………………………1间房 17人","language":"中文","translation":false},{"id":"capital-24-171","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":171,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"[乔治街49号………………………………1间房 2家]","language":"中文","translation":false},{"id":"capital-24-172","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":172,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"约克街34号……………………………………1间房 2家","language":"中文","translation":false},{"id":"capital-24-173","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":173,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"咸饼街…………………………………………2间房 26人","language":"中文","translation":false},{"id":"capital-24-174","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":174,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"瑞琴特广场………………………………1个地下室 8人","language":"中文","translation":false},{"id":"capital-24-175","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":175,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"爱克街……………………………………1个地下室 7人","language":"中文","translation":false},{"id":"capital-24-176","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":176,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"罗伯茨街33号……………………………1个地下室 7人","language":"中文","translation":false},{"id":"capital-24-177","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":177,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"普腊特后街（炼铜场）…………………1个地下室 7人","language":"中文","translation":false},{"id":"capital-24-178","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":178,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"埃本尼泽街27号…………………………1个地下室 6人〕 ，","language":"中文","translation":false},{"id":"capital-24-179","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":179,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"表上记载的这些令人厌恶的地下室和小房间，住的大多还都是收入较好的工人。这些人都说，如果有较好的房子他们是愿意租赁的。正当温和的自由主义者福斯特议员为自由贸易的恩赐，为布莱得弗德的经营精梳毛纺业的巨头们的利润流着激动的眼泪的时候，工人们一家大小却在颠沛流离，疾病缠身。布莱得弗德的贫民诊所医生贝尔在他1865年9月5日的报告中说，在他的管区内，热病患者的惊人的死亡率是由他们的居住条件造成的。他说：","language":"中文","translation":false},{"id":"capital-24-180","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":180,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“在一个1500立方呎的地下室里住着10个人…… 在文辛街、格林—艾尔广场和利斯，有223栋房子住着1450人，可是只有435个床铺和36个厕所…… 我所指的床铺是连一卷肮脏的破布或一小堆刨花也都算在内的，每个床铺平均睡3.3人，有些甚至睡4—6个人。很多人没有床，穿着衣服睡在光秃秃的地上，青年男女，已婚的和未婚的，都混睡在一起。这些房子大都是些阴暗、潮湿、污秽、发臭的洞穴，根本不适合人住，这还用得着说吗？这里是散布疾病和死亡的中心。连那些听任这种毒疮在我们中间溃烂的境况良好的人也身受其害。”","language":"中文","translation":false},{"id":"capital-24-181","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":181,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"居住状况的恶劣次于伦敦而居第三位的，是布利斯托尔。","language":"中文","translation":false},{"id":"capital-24-182","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":182,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“这里，在这个欧洲最富的城市之一，赤贫现象和住房惨状也极为严重。”","language":"中文","translation":false},{"id":"capital-24-183","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":183,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"现在我们谈谈一个来自农村而大部分在工业中就业的居民阶 层。他们是资本的轻步兵，资本按自己的需要把他们时而调到这里，时而调到那里。当不行军的时候，他们就“露营”。这种流动的劳动被用在各种建筑工程和排水工程、制砖、烧石灰、修铁路等方面。这是一支流动的传染病纵队，他们把天花、伤寒、霍乱、猩红热等疾病带到他们扎营的附近地区。在象铁路建设等需要大量投资的企业中，通常由企业主本人为自己的军队提供一些木棚之类的住所，这种临时性的村落，没有任何卫生设备，不受地方当局监督，对承包人先生非常有利可图，他把工人既当作产业士兵又当作房客进行着双重剥削。 木棚里各有1个、2个或3个洞穴，住户即掘土工人等等按照洞穴数每周分别付房租2先令、3先令或4先令。举一个例子就够了。据西蒙医生报告，1864年9月，内务大臣乔治·格雷爵士收到塞文诺克斯教区卫生警察委员会主席如下一份揭发报告：","language":"中文","translation":false},{"id":"capital-24-184","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":184,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“大约12个月以前，这个教区根本没听说有天花病。在那以前不久，从留伊斯海姆到汤布里季的铁路工程开始了。主要工程就在这个城市附近进行，工程总部也设在这里。因此有大量的人在这里就业。由于小屋住不下所有的人，承包人杰伊先生就吩咐在铁路沿线各点建造一些供工人居住的小棚。这些小棚既没有通风设备，也没有排水沟，而且必然拥挤不堪，因为每个房客不管自己家里有多少人，而且尽管每个小棚只有两个房间，也必须接纳别的房客。根据我们所收到的医生的报告说，结果是这些可怜的人夜里为了躲避从窗前的臭水里和厕所里发出的恶臭，不得不忍受窒息的痛苦。最后，一位有机会参观过这些小棚的医生向我们委员会提出了控诉。这位医生用极其沉痛的语调叙述了这些所谓住宅的状况，他担心倘若不采取一些卫生预防措施，就会产生极其严重的后果。大约一年前，上面提到过的那位杰伊曾答应安排一所房子，以便他雇用的人在患传染病时可以立即被隔离。今年7月底，他再 次许下了这个诺言，但是此后尽管发生了几起天花，并且有两人因此死亡，他仍然没有采取任何步骤履行自己的诺言。9月9日凯尔桑医生向我报告说，在这些小棚里又发生了几起天花，他把那里的情况描绘得非常可怕。我还应当向阁下〈大臣〉补充报告一点。我们教区已有了一座隔离所，也就是所说的传染病房，用来收容本教区传染病患者。几个月来，这个病房的病人总是挤得满满的。有一家5个孩子死于天花和热病。今年4月1日至9月1日，死于天花的已不下10人，其中有4个人就是死在成为传染病发源地的上述小棚中。由于遭难的家属竭力保守秘密，患者的数目无法确定”。","language":"中文","translation":false},{"id":"capital-24-185","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":185,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"煤矿以及其他矿山的工人是属于不列颠无产阶级中报酬最优厚的一类工人。他们花了怎样的代价才挣得自己的工资，这一点在前面已经说过了。在这里我再略微谈谈他们的居住情况。矿山开采者，不管他是矿山的所有主还是承租人，通常要为自己的工人建造一定数量的小屋。工人“无代价地”得到小屋和燃料用煤，也就是说，这些小屋和煤构成工资中用实物支付的部分。靠这种办法安置不了的人，每年可以领到4镑作为补偿。矿区很快就吸引来大批的居民，其中有矿业人口本身以及聚集在他们周围的手工业者和小店主等等。这里也象其他一切人口稠密的地方一样，地租很高。因此，采矿业主力图在井口附近的尽量狭小的建筑地 段上，盖起正好能塞下他的工人和工人家属的必要数量的小屋。一旦附近又开凿新矿井或者重新开采旧矿井，拥挤的程度就要增加。在建造小屋方面，唯一起作用的着眼点就是：凡是绝非必需的现金开支，资本家一概实行“禁欲”。朱利安·汉特医生说：","language":"中文","translation":false},{"id":"capital-24-186","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":186,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“除了蒙默思郡的一些类似的地区外，诺森伯兰和德勒穆矿山的矿工以及其他工人的住宅，平均说来，大概是英国能够大量见到的最坏的和最贵的住宅了。最糟糕的是：许多人拥挤在一间房里；建筑地段很狭小，却胡乱盖了许多房子；缺乏水并且没有厕所；经常采取屋上架屋或者把屋子分成几层的办法〈以致各种小屋都层层相叠〉…… 企业主把整个移民团看成似乎只是露营，而不是驻扎。”","language":"中文","translation":false},{"id":"capital-24-187","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":187,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“我奉命视察了德勒穆联合教区大部分的大矿山村落…… 除了极少数例外，可以说，所有的村落都没有采取过任何措施来保障居民的健康……所有矿工都被束缚〈《bound》这个词和bondage[依附]一样，都来源于农奴制时代〉在与矿山承租人或矿山所有主签订的12个月的契约上。只要工人流露出不满，或者在哪一方面得罪了监工，监工就在监督簿上他们的姓名下面作个记号或加个注，等到签订新的一年的契约时就把他们解雇…… 在我看来，再没有别的实物工资制比这个人口稠密地区所流行的实物工资制更坏了。工人不得不接受处于传染病影响下的住房，作为他的工资的一部分。他自己一点也无能为力。无论从哪方面看，他都是一个农奴。除了他的所有主以外，恐怕很难有别的什么人能帮助他。但是所有主首先要考虑的是自己的收支表，其结果是可想而知的。工人还从所有主那里得到水的供应。不管供应好坏，不管有无，工人都要付水费，或者不如说，都要从工资中扣除。”","language":"中文","translation":false},{"id":"capital-24-188","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":188,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在同“社会舆论”或甚至同卫生警察发生冲突时，资本总是恬不知耻地对工人不得不在其中劳动和居住的、既危险又使人堕落的条件进行“辩护”，说这是为了更有利地剥削工人所必需的。当 资本拒绝在工厂的危险机器上安装防护设备，拒绝在矿山中安装通风设备和采取安全措施，对此一概实行禁欲时，就是这样说的。现在，在矿工的住宅方面，它也是这样说的。枢密院的医官西蒙医生在他的正式报告中说：","language":"中文","translation":false},{"id":"capital-24-189","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":189,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“人们替恶劣的房屋设备辩解，说矿山通常是以租赁方式开采的；租赁合同期限太短（煤矿大多是21年），所以矿山承租人认为不值得为企业所招来的工人、手工业者等等提供良好的房屋设备；即使承租人自己想在这方面慷慨一点，地主也会打消他的这种念头。地主有一种倾向，就是当地面上一旦造起象样而舒适的村庄供给那些开采地下财产的矿工们居住时，地主就会马上利用这种特权来索取异常高的追加地租。这种禁令似的价格，即使不是一道直接的禁令，也会把另一些本想把房屋建造得好一些的人吓回去…… 我不想进一步研究这种辩解的价值，也不想研究用来建造象样的住宅的追加费用归根到底应当由谁负担，由地主、矿山承租人、工人还是由公众负担……但是，面对后面所附报告〈汉特、斯蒂文斯等医生的报告〉中揭露出来的可耻事实，必须采取一个补救的办法…… 土地所有权竟被利用来造成社会的极大不公平。地主以矿山所有主的身分把一个工业移民团召到自己的领地上来从事劳动，然后又以地面所有主的身分使他所招来的工人无法找到生活上必不可少的合适住宅。矿山承租人〈资本主义的矿山开采者〉没有任何金钱上的利益要来反对交易上的这种划分，因为他知道得很清楚，即使地主的条件很苛刻，后果也不由他承担，而承担这种后果的工人又没有受过什么教育，连自己的卫生权利也不认识，不论极端恶劣的住宅，还是污浊不堪的饮水，从来都没有引起过罢工。”","language":"中文","translation":false},{"id":"capital-24-190","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":190,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"(d)危机对工人阶级中报酬最优厚的部分的影响","language":"中文","translation":false},{"id":"capital-24-191","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":191,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在谈到真正的农业工人之前，我还要举一个例子，说明危机甚 至对工人阶级中报酬最优厚的部分即工人阶级的贵族产生了怎样的影响。我们记得，1857年发生了一次大危机——工业周期每一次都是以这种危机而告终。下一个周期是在1866年到期的。由于棉荒把许多资本从通常的投资领域赶到了货币市场的大中心，这次危机在真正的工厂区域已经打了折扣，因而主要带有金融的性质。这次危机在1866年5月爆发，这是以伦敦一家大银行的破产为信号的，继这家银行之后，无数在金融上进行欺诈的公司也接着倒闭了。遭殃的伦敦大生产部门之一是铁船制造业。这一行业的巨头们在繁荣时期不仅无限度地使生产过剩了，而且由于他们误认为信用来源会照样源源不绝，所以还接受了大宗的供货合同。今天，一种可怕的反作用发生了，而且直到现在，1867年3月底，这种反作用还在伦敦其他工业部门继续发生。为了说明工人的状况，现在从1867年初采访过主要受难地区的《晨星报》记者的详细报道中摘引一段如下。","language":"中文","translation":false},{"id":"capital-24-192","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":192,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“在伦敦东头，在波普拉尔、米尔瓦尔、格林威治、德普弗德、莱姆豪斯、坎宁镇等区，至少有15000名工人及其家属处于极端贫困的状态，其中有3000多人是熟练的机械工人。他们已经一连失业6个月至8个月了，积蓄已全部用光…… 我费了好大劲才挤到贫民习艺所（在波普拉尔）的大门口，因为它已被饿坏了的人群团团围住。他们在等着发面包票，但是发票的时间还没有到。院子很大，是方形的，沿着院墙盖有一圈棚子。几大堆雪覆盖着堆在院子当中的铺路石块。院子里有一些用柳条篱笆隔成的小块地方，活象羊栏一样；天气好的时候男人们就在里面干活。我去采访那天，栏子里面全是雪，没法坐人。男人们就在棚子底下砸铺路的石块。每个人都坐在一块大石头上，挥动着大锤砸碎结着冰的花岗石，直到砸满5蒲式耳为止。这样他们一天的活才算干完，每人获得3便士和一张面包票。院子的一边有一座歪歪斜斜的小木房。我们把门推开，看见里面塞满了人，肩并肩地挤在一起互相取暖。他们一边撕麻絮一边争论，看谁能吃得最少而干的时间最长，因为有耐力已经成了受称赞的事情。单是这个贫民习艺所就收容着7000个接受救济的人，其中有好几百人在6个月或8个月以前还拿着我国熟练劳动的最高工资。许多人即使积蓄已经用光，但只要还有一点东西可以典当，也绝不乞求教区救济；如果没有这种情况，接受救济的人数还要增加一倍 C. T. and T. R. Saving, 1964. The Demand for General Assistance Payments. American Economic Review vol. LIX, pp. 1002-1018.)中，就没有考虑到这一点。而且这篇文献明明表明低工资是引起申请救济的原因，但却不敢明确表达这一结论。 ……离开贫民习艺所，我又到街上走了走，街道两旁大多是两层楼的房子，这种房子在波普拉尔比比皆是。我的向导是失业委员会的委员。我们访问的第一家是一个已经失业27周的铁匠。我看见他和他的全家坐在一间后屋里。屋子里还剩下一点家具，而且生着火。为了使小孩子们光着的脚不致冻坏，不生火是不行的，因为那天非常冷。在火对面的盆子里放着一堆粗麻，妻子和孩子们正在撕麻絮，这是从贫民习艺所领取面包的代价。丈夫在某个上面谈到过的那种院子里干活，每天得一张面包票和3便士。这时他正好回家吃午饭。他苦笑着对我们说，他饿极了；他的午饭只有几片薄薄的涂着油的面包和一杯没有牛奶的清茶…… 我们又敲第二家的门，开门的是一个中年妇女，她一句话也没有说就把我们领进一间狭小的后屋，一家大小都在那里一声不响地坐着，呆望着快要熄灭的火。他们脸上和他们的小屋里笼罩着的那种凄凉绝望的情景，使我再也不愿看到类似的景象。妇人指着她的孩子们说：‘先生，他们已经26个星期没有活干了。我们所有的钱都花光了，那是我和孩子们的父亲在光景好时积蓄下来准备困难时用的。请你们看吧！’她几乎是发狂似地喊着，一边拿出一本存取款项写得清清楚楚的银行存折；我们从上面可以看出，这笔小小的财产最初怎样从5先令开始存起，怎样一点一点地增加到20镑，然后又怎样逐渐消失，从若干镑减到若干先令，直到最后一次提款使存折变得象一张白纸一样一文不值。这家人每天从贫民习艺所领到一顿救济饭…… 接着我们访问了一个曾在造船厂工作的爱尔兰人 的妻子。我们发现她已经饿病了，穿着衣服躺在一张垫子上，勉强算盖着一条毯子，因为所有的被褥都已进了当铺。两个可怜的孩子照料着她，但是看来孩子们自己正需要母亲的照顾。已经19周被迫无事可干，致使她陷入这样的境地。她在讲述她的痛苦经历的时候唉声叹气，仿佛失去了对美好未来的一切希望…… 我们走出房子的时候，有一个年轻人跑来要我们到他家去，看看是不是能帮他一点忙。一个年轻的妻子，两个可爱的小孩，一卷当票，一间空房——这就是他指给我们看的一切。”","language":"中文","translation":false},{"id":"capital-24-193","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":193,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"下面我们再从托利党的报纸上摘引一段描述1866年危机的余痛的报道。不要忘记，这里谈到的伦敦东头，不仅是本章所谈到的铁船制造业工人的中心，而且还是工资一向低于最低额的所谓“家庭劳动”的中心。","language":"中文","translation":false},{"id":"capital-24-194","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":194,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“昨天在这个大都会的一角出现了一幅可怕的情景。东头的好几千失业工人虽然没有打着黑色丧旗成群结队地游行，但是这股人潮已经够吓人的了。让我们想想这些人受着怎样的苦难吧。他们快要饿死了。这是一个简单而可怕的事实。他们共有4万人…… 在我们面前，在这个不可思议的大都会的一个区，一边是旷古未有的最大量财富的积累，而紧挨着它的旁边的是4万个走投无路的行将饿死的人！现在这成千上万的人正在侵入其他市区；这些一直处于半饥饿状态的人向我们大声诉苦，向天哀号，向我们诉说他们的破烂不堪的住所，他们无法找到工作，求乞也没有用。而地方上交纳济贫税的人，由于教区的勒索，也濒于需要救济的赤贫的边缘了。” （1867年4月5日《旗帜报》）","language":"中文","translation":false},{"id":"capital-24-195","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":195,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"英国的资本家中间流行着一种说法，认为比利时是工人的乐园，因为据说“劳动的自由”，其实也就是“资本的自由”，在那里既不受工联专制的侵犯，也不受工厂法的侵犯。因此，我在这里应谈一谈比利时工人的“幸福”。关于这种幸福的秘密，肯定再也没有人比已故的杜克佩西奥先生更为熟悉的了。杜克佩西奥先生是比利时监狱和慈善机关的总监，也是比利时中央统计委员会的委员。现在让我们来翻看一下他的《比利时劳动阶级的经济预算》（1855 年布鲁塞尔版）。在这本书中，我们可以看到一个比利时的标准工人家庭，该书根据非常精确的材料算出了这个家庭每年的收支，然后又把它的营养状况同士兵、水兵和囚犯的营养状况作了比较。这个家庭有“父亲、母亲和4个孩子”。这6个人中“有4个人可以全年就业而有所收益”；假定“他们中间没有生病的和不能劳动的人”，他们“除了交纳为数极少的教堂坐位费以外，在宗教、道德和精神需要方面没有什么开支”，他们不“在储蓄银行存款或交纳养老准备金”，没有“奢侈品的开支或其他的多余的开支”。只有父亲和大儿子抽点烟，星期天上个酒馆，这些总共每周花86生丁。","language":"中文","translation":false},{"id":"capital-24-196","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":196,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“根据不同行业同意付给工人的工资的综合材料可以看出……一日工资的最高平均额，男人是1法郎56生丁，妇女是89生丁，男孩是56生丁，女孩是55生丁。按照这个标准计算，这家的收入一年最多不过1068法郎……我们把这个当作典型的家庭的一切可能的收入都计算进去了。但是，既然我们也给母亲算上一笔工资，这样，我们就使她无法料理家务了；谁来看家和照顾小孩呢？谁来做饭、洗衣服和缝缝补补呢？这是工人每天都要碰到的难题。”","language":"中文","translation":false},{"id":"capital-24-197","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":197,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"根据这个算法，这个家庭的预算是：","language":"中文","translation":false},{"id":"capital-24-198","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":198,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1日的工资额 300个工作日的工资总额","language":"中文","translation":false},{"id":"capital-24-199","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":199,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"父亲 1.56法郎 468法郎","language":"中文","translation":false},{"id":"capital-24-200","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":200,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"母亲 0.89法郎 267法郎","language":"中文","translation":false},{"id":"capital-24-201","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":201,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"儿子 0.56法郎 168法郎","language":"中文","translation":false},{"id":"capital-24-202","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":202,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"女儿 0.55法郎 165法郎","language":"中文","translation":false},{"id":"capital-24-203","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":203,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"——————————————————————","language":"中文","translation":false},{"id":"capital-24-204","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":204,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"工人如果要达到下述各种人的营养水平，全家每年的支出额和不足额如下：","language":"中文","translation":false},{"id":"capital-24-205","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":205,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"水兵的营养………………… 1828法郎 760法郎","language":"中文","translation":false},{"id":"capital-24-206","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":206,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"士兵的营养………………… 1473法郎 405法郎","language":"中文","translation":false},{"id":"capital-24-207","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":207,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"囚犯的营养………………… 1112法郎 44法郎","language":"中文","translation":false},{"id":"capital-24-208","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":208,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“我们看到，只有少数工人家庭才能达到同囚犯差不多的营养，更不用说达到水兵或士兵的营养了。1847—1849年，比利时每个囚犯每天平均花费63生丁，同工人每天的生活费用相比还有一个13生丁的差额。管理费和监视费可由囚犯不付房租来抵销…… 但是多数工人，甚至可以说大多数工人的生活过得还要俭朴，这是怎么回事呢？这只是由于工人采取了只有他们自己才了解其中秘密的应急措施；他们减少了每天的口粮；吃黑面包而不吃白面包；少吃或者根本不吃肉；少用或者根本不用奶油和调味品；一家大小挤在一两间小屋里，男孩和女孩睡在一起，往往就睡在同一张草垫子上；他们节减服装、洗濯和清洁用品的开支；放弃星期天的消遣；总之，他们决心过最痛苦的贫困生活。工人已经到了山穷水尽的地步，只要生活资料的价格稍稍上涨一点，或者一旦无工可做，或者生病，都会加深工人的贫困，使他完全毁灭。债台高筑，借贷无门，衣服和绝对必需的家具也送进当铺，最后是全家申请列入贫民名册。”","language":"中文","translation":false},{"id":"capital-24-209","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":209,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"其实，在这个“资本家的乐园”里，只要最必要的生活资料的价格发生最微小的变动，就会引起死亡和犯罪数字的变动！ （见《协会呼吁书：佛来米人，前进！》1860年布鲁塞尔版第12页）全比利时共有93万个家庭。据官方统计，其中富有的家庭（选民）9万户，共45万人；城乡下层中产阶级家庭39万户，共195万人，其中有相当大一部分正在不断地下降为无产阶级。最后，工人家庭45万户，共225万人，其中的一些模范家庭正在享受着杜克佩西奥所描写的那种幸福。在这45万户工人家庭中，列入贫民名册的竟达 20万户以上！","language":"中文","translation":false},{"id":"capital-24-210","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":210,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"(e)不列颠的农业无产阶级","language":"中文","translation":false},{"id":"capital-24-211","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":211,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"资本主义生产和积累的对抗性质，在任何地方再也没有比在英格兰农业（包括畜牧业）的进步和农业工人的退步上表现得更为残酷的了。在考察农业工人的现状之前，我们先略微回顾一下过去。在英格兰，现代农业是在十八世纪中叶出现的，虽然生产方式由以发生变化的基础，即土地所有权关系的变革还要早得多。","language":"中文","translation":false},{"id":"capital-24-212","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":212,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"阿瑟·杨格虽是一个肤浅的思想家，但不失为一个精确的观察家，我们从他关于1771年农业工人的描述中可以看到，这些农业工人同他们十四世纪末“生活得很富裕并且能积累财富”的先人比较起来，扮演着非常可怜的角色，更不用说同“英格兰城乡劳动者的黄金时代”十五世纪相比了。但是我们用不着追溯这么远。在1777年的一部内容十分丰富的著作中写道：","language":"中文","translation":false},{"id":"capital-24-213","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":213,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“大租地农场主几乎上升到绅士的地位，而贫困的农业工人几乎被踩到地下去了。把今天农业工人的状况和40年前的状况比较一下，他们的不幸处境是一目了然的…… 土地所有者和租地农场主狼狈为奸，压榨工人。” 接着作者又详细地证明，农村中的实际工资从1737年到1777年几乎降低了1/4即25％。当时理查·普莱斯博士也说：","language":"中文","translation":false},{"id":"capital-24-214","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":214,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“现代政治袒护国民中的上层阶级；其结果是，整个王国迟早终将只由绅士和乞丐，贵族和奴隶组成。”","language":"中文","translation":false},{"id":"capital-24-215","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":215,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"但是英格兰农业工人在1770年至1780年期间的状况，无论就他们的营养和居住状况来说，或者就他们的自尊感和娱乐情况等等来说，都成了以后再也没有达到过的理想。他们的平均工资如果用小麦来表示，1770年至1771年是90品脱，到伊登时代（1797年）已经只有65品脱，而到1808年时则只剩下60品脱了。","language":"中文","translation":false},{"id":"capital-24-216","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":216,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"前面我们已经提到反雅各宾战争末期农业工人的状况，在这次战争中，土地贵族、租地农场主、工厂主、商人、银行家、交易所骑士、军火商等等大发横财。同时，一方面由于银行券贬值，另一方面由于同银行券贬值无关的生活必需品价格的上涨，名义工资也提高了。但是工资的实际变动情况，用不着在这里详细论述，用很简单的方法就可以说明。济贫法及其行政机关在1795年和1814年并没有什么变化。我们还记得这项法令在农村中是怎样实施的，那就是由教区以救济形式把名义工资补足到只够工人勉强糊口的 名义数额。租地农场主支付的工资和教区贴补的工资不足额之间的比率说明两件事：第一，工资已经降到它的最低限额以下；第二，农业工人在何种程度上成了既是雇佣工人又是需要救济的贫民，或者说，在何种程度上被变成了他所在的教区的农奴。我们选一个能代表其他各郡平均情况的郡来说吧。在北安普顿郡，1795年平均周工资是7先令6便士，一个6口之家的年支出总额是36镑12先令5便士，收入总额是29镑18先令，由教区贴补的不足额是6镑14先令5便士。1814年，该郡周工资是12先令2便士，一个5口之家的年支出总额是54镑18先令4便士，收入总额是36镑2先令，由教区贴补的不足额是18镑6先令4便士。可见，在1795年，不足额占工资的1/4弱，而到1814年竟占一半以上。不言而喻，在这种情况下，伊登曾经在农业工人小屋中看到过的那种略感舒适的情景，到1814年早已无影无踪了。从此以后，在租地农场主饲养的各种牲畜中，工人这种会说话的工具一直是受苦最深、喂得最坏和虐待得最残酷的了。","language":"中文","translation":false},{"id":"capital-24-217","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":217,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这种状况一直平静无事地继续下去，直到","language":"中文","translation":false},{"id":"capital-24-218","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":218,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“1830年斯温暴动使我们〈即统治阶级〉在燃烧着的麦垛的熊熊火光中看到，在农业英格兰的表面下也象在工业英格兰的表面下一样，充满着贫困和燃烧着阴森的反叛的怒火”。","language":"中文","translation":false},{"id":"capital-24-219","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":219,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"当时萨德勒曾在下院中给农业工人起了一个绰号，把他们叫做“白奴”，一个主教在上院也袭用了这个绰号。当时最著名的政 治经济学家爱·吉·威克菲尔德说：","language":"中文","translation":false},{"id":"capital-24-220","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":220,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“英格兰南部的农业工人不是奴隶，也不是自由人，而是需要救济的贫民。”","language":"中文","translation":false},{"id":"capital-24-221","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":221,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"谷物法临废除前的一段时期，进一步透露了农业工人的状况。一方面，资产阶级鼓动家的利益是要证明这个保护法对谷物的真正生产者很少起什么保护作用。另一方面，工业资产阶级又非常恼恨土地贵族对工厂状况的非难，恼恨这些腐败透顶、丧尽天良、矜持高傲的游惰者对工厂工人的痛楚所表示的假慈悲，恼恨他们对工厂立法所表现的那种“外交热忱”。英格兰有句古老的谚语说得好：两贼相争，好人得利。事实上，统治阶级的两个派别在关于它们当中谁最无耻地剥削工人的问题上展开的喧闹的狂热的争吵，从两方面暴露了真相。舍夫茨别利伯爵，又称艾释黎勋爵，是贵族慈善家反工厂运动的先锋。因此，他成了1844年至1845年《纪事晨报》上揭露农业工人状况的文章中引人注目的人物。这家报纸是当时最重要的自由党机关报，它在各个农业地区都有特派记者。这些记者不以一般的记述和统计为满足，而且还把调查过的工人家庭和他们的地主的姓名公布出来。下表 列举了布兰弗德、维姆博恩和普耳附近三个村庄工资的支付情况。这些村庄是乔治·班克斯先生和舍夫茨别利伯爵的财产。我们将会看到，这位低教会派的教皇，英格兰虔诚派的头目，同他的伙伴班克斯一样，还以房租名义从工人的微薄工资中克扣掉相当大一部分。","language":"中文","translation":false},{"id":"capital-24-222","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":222,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"谷物法的废除大大推动了英格兰的农业。修建巨大规模的排水工程，采用圈养牲畜和人工种植饲料的新方法，应用施肥机，采用处理粘土的新方法，更多地使用矿物质肥料，采用蒸汽机以及其他各种新式工作机等等，总之，耕作更加集约化就是这一时期的特点。皇家农业学会主席皮由兹先生断言，由于采用新机器，（相对的）经营费用几乎减少了一半。另一方面，从土地上得到的实际收益也迅速增加了。每英亩土地投资的增加，因而租地农场 的加速积聚，这是采用新方法的基本条件。同时，从1846年到1865年耕地面积约扩大了464119英亩，东部各郡原为养兔场和贫瘠牧场而现在变成了富饶的庄稼地的大片土地尚不计算在内。我们已经知道，从事农业的总人数与此同时却减少了。就拿男女两性各种年龄的真正农业工人来说，他们的人数从1851年的1241269人减少到1861年的1163217人。因此，英国中央注册局局长有理由说：“1801年以来租地农场主和农业工人数目的增加，同农产品的增长是极不相称的”。但是最近一个时期，这种不相称的情况更加严重了：一方面，耕地面积不断扩大，耕作更加集约化，投在土地及其耕作上的资本有了空前的积累，农产品获得了英格兰农业史上空前未有的增长，土地所有者的地租大大增加，资本主义租地农场主的财富日益膨胀；另一方面，农业工人人口却在绝对地减少。如果再加上城市销售市场的不断迅速扩大，自由贸易的占统治地位，那末，农业工人在经过种种不幸之后终于被安排在理应令人陶醉的幸福环境中了。","language":"中文","translation":false},{"id":"capital-24-223","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":223,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"但是罗杰斯教授却得出这样的结论：今天的英格兰农业工人，不要说同他们十四世纪下半叶和十五世纪的先人相比，就是同他们1770年到1780年时期的先人相比，他们的状况也是极端恶化了，“他们又成了农奴”，而且是食宿都很坏的农奴。朱利安·汉特医生在他关于农业工人的居住状况的划时代的报告中说：","language":"中文","translation":false},{"id":"capital-24-224","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":224,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“农仆〈这是农奴制时期对农业劳动者的称呼〉的生活费用固定在只够他活命的最低的数额上……他的工资和住房同从他身上榨取的利润相比，几乎不值一提。他在租地农场主的算盘上是个零…… 他的生存资料永远被看成是一个固定的量”。“至于谈到他的收入的任何进一步的减少，他会说：我什么也没有，我什么也不操心。他不担心将来，因为他除了生存所绝对必需的东西之外，一无所有。","language":"中文","translation":false},{"id":"capital-24-225","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":225,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"他降到了零点， 也就是租地农场主打算盘的起点。由它去吧，幸福与不幸反正同他无关。”","language":"中文","translation":false},{"id":"capital-24-226","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":226,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1863年，对被判处流放和强制劳动的犯人的饮食状况和劳动状况曾进行过正式调查。调查的结果记载在两大本厚厚的蓝皮书中。其中写道：","language":"中文","translation":false},{"id":"capital-24-227","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":227,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“英格兰监狱中犯人的饮食同这个国家贫民习艺所中需要救济的贫民以及自由农业工人的饮食的详细对比，无可辩驳地表明，前者的饮食比后二者都要好得多。”而“被判处强制劳动的犯人的劳动量，大约只有普通农业工人的一半”。","language":"中文","translation":false},{"id":"capital-24-228","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":228,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"下面略引几段颇为典型的证词。爱丁堡典狱官约翰·斯密斯 在作证时说：","language":"中文","translation":false},{"id":"capital-24-229","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":229,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“英格兰监狱中的饮食比普通农业工人要好得多。”（第5056号）“苏格兰的普通农业工人很少吃到什么肉类，这是事实。”（第5057号）“你知道有什么理由能说明犯人的饮食必须比普通农业工人好得多吗？——确实不知道。”（第3047号）“你是否认为应当作进一步试验，使被判处强制劳动的犯人的饮食和自由农业工人的饮食大致差不多呢？”（第3048号）其中还写道：“农业工人会说：我干的活很重但是吃不饱。我在蹲监狱的时候，活没有这样重但是吃得很饱，因此我觉得释放出来还不如关在监狱里好。”","language":"中文","translation":false},{"id":"capital-24-230","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":230,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"综合该报告第一卷中所附的各种表格，可以得出如下比较表。","language":"中文","translation":false},{"id":"capital-24-231","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":231,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1863年医务调查委员会对国民中吃得较坏的各阶级的营养状况进行过一次调查，这次调查的一般结果读者都已经知道了。它表明，大部分农业工人家庭的饮食都低于“防止饥饿病”所必需的最低限度。特别在康瓦尔、戴文、索美塞特、威尔兹、斯泰福、牛津、伯克斯和赫尔茨等地的所有纯农业区更是这样。斯密斯医生说：","language":"中文","translation":false},{"id":"capital-24-232","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":232,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“农业工人得到的营养比平均量大，因为他吃的食物比家庭其他成员多得多，这对他的劳动来说是必不可少的。在比较贫困的地区，几乎全部肉类或油脂都归他一个人吃了。他的妻子和正处在发育期的孩子们得到的营养量多半不够，主要是缺乏氮素，几乎所有的郡都是如此。”","language":"中文","translation":false},{"id":"capital-24-233","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":233,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"同租地农场主住在一起的男仆和婢女的营养倒很充足。 他们的总数由1851年的288277人减少到1861年的204962人。斯密斯医生说：","language":"中文","translation":false},{"id":"capital-24-234","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":234,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“妇女参加田间劳动尽管会有一些坏处，但在目前情况下对一个家庭来说还是大有好处，因为这样可以挣几个钱补贴买鞋子、衣服和支付房租，从而使一家人可以吃得好些。”","language":"中文","translation":false},{"id":"capital-24-235","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":235,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这次调查的最值得注意的结果之一，就是弄清了英格兰农业工人的营养比联合王国其他地区农业工人的营养要差得多。下表就是证明： 西蒙医生在官方的卫生报告中说：","language":"中文","translation":false},{"id":"capital-24-236","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":236,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“汉特医生报告的每一页都证明，我国农业工人的住宅数量不足而且质量很坏。并且多年来，他们在这方面的情况一直在不断恶化。现在农业工人更难找到栖身之所了，即使能够找到，也远不能适应他们的需要，这种情况也许比几世纪以来的任何时候都更糟。特别是最近二三十年来，这种祸害更迅速滋长了，目前村民的居住条件简直糟糕透了。村民在这方面毫无办法可想，除非那些靠他们的劳动发财致富的人认为值得对他们发点善心。农业工人能不能在他耕种的土地上找到住处，那个地方适合于人住还是适合于猪住，同时是否附有一小块能够大大减轻贫困压力的园圃——这一切都不取决于他是否愿意或者有能力支付适当的房租，而是取决于别人怎样行使‘任意支配自己财产’的权利。不管租地面积有多大，也没有一项法律规定必须在上面建有一定数量的工人住宅，更不用说象样的住宅了；法律同样也没有给工人保留拥有土地的丝毫权利，虽然工人的劳动对土地来说就象雨露和阳光一样必不可少 …… 还有一种大家都知道的情况更加深了工人的灾难…… 这就是济贫法关于居住和负担济贫税的规定所产生的影响。在这项法律的影响下，各教区为了金钱上的利益都要把本教区居住的农业工人的人数限制在最低限度之内；因为不幸的是，农业劳动并不能保证劳苦的工人和他的一家维持永久可靠的独立地位，而多半不过是一条通向需要救济的赤贫的或长或短的迂回道路，在整个途程中工人离需要救济的赤贫境地是这样近，他只要一生病或者暂时失业，就不得不立刻求助于教区救济；因此，只要有农业人口在教区内定居下来，显然就会加重教区的济贫税负担…… 大地主们〔注：为了便于理解下文，这里要说明：非开放村庄是指一个或几个大地主所有的村庄；开放村庄是指土地分属于许多小地主的村庄。建筑投机家只有在开放村庄才能建造小屋和旅店。〕只要决定不准在他们的领地上建筑工人住宅，他们对穷人的负担马上就可以减轻一半。那些可以‘任意支配自己财产’的地主，凭借绝对的土地所有权，竟能够象对待异邦人那样对待土地的耕种者并把他们从自己的庄园上赶出去。对于这样一种绝对的土地所有权，英国宪法和法律究竟准备在多大程度上予以承认，这个问题不属于本报告所讨论的范围…… 这种驱逐权不单是一种理论问题，它在实际上被广泛地行使着。这是对农业工人的居住条件有决定性影响的情况之一…… 这种灾祸殃及的范围，从最近一次人口调查中就可以看出。根据调查，在最近10年间，尽管地方上对房屋的需求增加了，但是英格兰的821个地区拆除的房屋却越来越多，以致撇开那些无法定居的人〈即无法在自己劳动的教区内定居的人〉不说，1861年居民人数虽然比1851 年增加了5 1/3％，但是他们居住的房屋却减少了4 1/2％…… 汉特医生说，减少人口的过程一旦达到目的，就出现一种游赏村庄，那里小屋所剩无几，除了牧羊人、园丁和看守狩猎场的人这些固定的仆役以外，谁也不准居住，只有他们才能从慈善的主人那里得到对他们这个阶级来说通常已算不坏的待遇。但是土地需要耕种，于是我们看到，雇来种地的工人并不是地主的房客，而是也许从3哩外的开放村庄来的；这种开放村庄有大量小房主，他们在非开放村庄的工人的小屋被拆除以后就把这些人收容下来。在那些正走向这种结局的地方，小屋大多破烂不堪，显示出它们注定要遭到的命运。这些小屋正处在自然倒塌的各个阶段。只要房顶还没有塌下来，就允许工人租用，而工人往往也非常乐意承租，即使他必须付出上等住宅的租金。可是房子从来不加修缮，除非身无分文的住户自己动手收拾一下。当房屋终于完全不能住人时，只不过表示又多了一座拆毁的小屋和未来的济贫税将相应减少而已。当大地主这样把居民从他们控制的土地上赶走以摆脱济贫税时，附近的小乡镇或开放村庄就把这些被赶出来的工人收容下来。我说的是附近，但是这个‘附近’也可能离工人每天做苦工的租地农场有3—4哩远。这样，工人为了挣得每天的面包，除了整天干活外，每天还必须走6—8哩路，而这好象不算一回事似的。现在，他的妻子和孩子们所从事的一切农活也要在同样困难的条件下进行了。然而住得远所引起的灾难还不止此。在开放村庄里，建筑投机家购买小块地皮，尽量密集地建造一些最简陋的小屋。英格兰农业工人就硬塞在这些可怜的小屋里。这些小屋即使面临空旷的田野，也具有最坏的城市住宅的种种最可怖的特点…… 另一方面，绝不要以为，那些即使居住在他们耕种的土地上的工人能够找到一所同他们的辛勤劳动的生活相称的住宅。甚至在最阔绰的田庄，工人的小屋也往往是非常简陋的。有些地主认为，能让工人和他的家庭住上一间牲口棚已经很不错了，可是他们在出租这类房子时竟然恬不知耻地榨取尽可能多的房租。这也许是一座破落的茅屋，只有一间卧室，没有火炉，没有厕所，没有可以开关的窗户，除了水沟而外没有任何供水设备，没有园圃，但工人对这种虐待也无可奈何。而我们的卫生警察法仍然是一纸空文。这些法律竟然恰恰要靠出租这类破屋的地主们来实行…… 我们绝不能让那些偶尔见到的灿烂夺目的景象迷住眼睛而看不见那些有辱英国文明的大量事实。尽管现在的居住情况已经糟到了骇人听闻的地步，但是权威的观察家们却一致得出结论说，住宅固然普遍恶劣不堪，但同住宅数量不足比较起来，那还是一个微不足道的灾难。 这种状况真是太可怕了。多年来，农业工人居住过挤的状况不仅使关心健康的人深感不安，而且也使一切维护庄重和有道德的生活的人深感不安。因为那些提出关于农村地区流行病蔓延情况报告的人总是用几乎一成不变的词句再三指出，由于居住过挤，为制止已发生的流行病进一步蔓延而作的一切努力都白费了。报告同样再三证明，农村生活本来对健康有许多好处，但是由于居民过于密集，不仅传染病蔓延得很快，就是非传染性疾病也很容易发生。揭露这类情况的人对别的祸害也没有保持沉默。虽然他们原来的任务只限于保健工作，但是他们几乎总是不得不注意到问题的其他方面。他们在报告中指出，已婚的和未婚的成年男女常常挤住在一间狭小的屋子里，这定会使人相信，在这种情况下羞耻心和庄重感被最粗暴地伤害了，道德的败坏几乎是必然的…… 例如，在我最近一次报告的附录里，载有奥德医生关于白金汉郡温格地区突然发生热病的报告。他谈到一个从温格雷弗来的年轻人怎样把热病带到了温格。他在得病的最初几天和另外9个人同住在一个房间里。两个星期的工夫，房间里就有几个人被传染了。在几星期内，9人中有5人得了热病，并有一人死亡！同时，圣乔治医院的医生哈维曾因私人出诊的关系在传染病流行期间到过温格，他也向我提供了类似的情况：‘一个患热病的年轻女人晚上同父亲、母亲、她的私生子、两个小伙子即她的兄弟以及各有一个私生子的两个姊妹睡在一个房间里，一共是10个人。几星期以前这个房间曾住过13个儿童’。”","language":"中文","translation":false},{"id":"capital-24-237","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":237,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"汉特医生调查过5375座农业工人小屋，其中不仅有纯农业区的，而且有英格兰所有各郡的。在5375座小屋中，2195座小屋只有一间卧室（往往兼作餐室），2930座小屋有2间卧室，250座小屋有2间卧室以上。现在我就12个郡的情况简单摘录如下。","language":"中文","translation":false},{"id":"capital-24-238","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":238,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"勒斯特林沃思：卧室大约长12呎、宽10呎，还有许多比这更小。矮小的平房通常都用木板隔成两间卧室，在高5呎6吋的厨房里往往还放上一张床。房租3镑。住户要自己盖厕所，房东只提供一个土坑。谁家一盖了厕所，邻居们便都来使用。理查逊家租的一栋房屋真是漂亮非凡。它的石灰墙鼓得象行屈膝礼的女人的长裙一样。山墙一边突出来，一边凹进去，而在凹进去的一边不幸还竖着一根烟囱，即一根用泥土和木头做的歪歪扭扭的管子，活象一个象鼻子。烟囱用一根长棍支着，防备它倒下来。门和窗都是菱形的。在调查过的17座房屋中，只4座有卧室一间以上，不过也是挤得满满的。在一座只有一间卧室的小屋里，住着3个大人和3个孩子，另一座这样的小屋住着一对夫妇和6个孩子，如此等等。","language":"中文","translation":false},{"id":"capital-24-239","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":239,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"登顿：房租昂贵，4镑至5镑，男子每周工资10先令。他们都想靠家里人编草辫来挣钱付房租。房租越高，需要一起干活的人便越多，这样才能付得起房租。一间住着6个大人和4个孩子的卧室，房租是3镑10先令。登顿最便宜的房屋外沿长15呎，宽10呎，租金3镑。在调查过的14座房屋中，只有一座有两间卧室。村前不远有一座房屋，住户就在墙脚下大小便，房门下端烂掉了9吋。晚上关门的时候，人们巧妙地从里面塞上几块砖头，再挡上块破席子。半个窗户连玻璃带窗框全掉下来了。房子里没有任何家具，3个大人和5个小孩挤做一团。登顿比起比格耳斯沃德联合教区的其他地方来，还不算是最坏的。 2、伯克郡","language":"中文","translation":false},{"id":"capital-24-240","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":240,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"宾汉姆：1864年6月，一间小屋住着丈夫、妻子和4个孩子。一个女儿在干活的地方得了猩红热，回到家里后病死了。一个孩子得病死去。汉特医生被请来的时候，母亲和一个孩子正患着伤寒病。父亲和另一个孩子睡在屋外边。但是，这里是很难实行隔离的，因为在这个不幸的村庄的拥挤的市场上就堆放着传染病人家待洗的衣物。有一家的房租每周1先令，一间卧室里住着一对夫妇和6个孩子。另一座房子租金8便士（每周）；长14呎6吋，宽7呎，厨房高6呎；卧室没有窗户，没有火炉，没有门，除了一条过道外，没有任何其他出入口，也没有园圃。不久前，有一个男人同他的两个成年女儿和一个行将成年的儿子住在里边；父亲和儿子睡在一张床上，两个女儿睡在过道里。他家住在这里的时候，两个女儿各生过一个小孩，其中一个女儿是到贫民习艺所生了孩子以后才回家来的。","language":"中文","translation":false},{"id":"capital-24-241","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":241,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在1000英亩土地上有30座小屋，大约住着130—140人。布莱敦哈姆教区占地1000英亩，1851年有36座房屋，住着84个男人和54个女人。男女人数的不平衡到1861年有所改变，这时男子有98人，女子87人，10年间男子增加14人，女子增加33人。然而房屋却减少了一座。","language":"中文","translation":false},{"id":"capital-24-242","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":242,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"温兹洛：大部分房屋是按好式样新建的；房屋的需要量看来很大，因为极不象样的小屋每周也要付1先令或1先令3便士的租金。","language":"中文","translation":false},{"id":"capital-24-243","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":243,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"沃特－伊顿：这里的地主眼看居民增加了，却拆除了大约20％的房屋。有一个贫穷的工人上工时大约要走4哩路，有人问他能不能找到一座比较近的小屋，他回答说：“不能，他们生怕招到象我这样有一大家人口的房客。”","language":"中文","translation":false},{"id":"capital-24-244","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":244,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"温兹洛附近的廷克尔斯－恩特：一间卧室长11呎，宽9呎，最高处6呎5吋，住着4个大人和5个孩子。另一间卧室长11呎7吋，宽9呎，高5呎10吋，住着6个人。这两个家庭每个成员所占的空间比一个苦役犯人所应占的空间还要小。每座房屋只有一间卧室，没有后门，水非常缺乏。房租每周从1先令4便士到2先令。在调查过的16家住户中，只有一个人每周有10先令的收入。在这样的居住条件下，每个人得到的空气量相当于他整夜被关在4呎立方的箱子里所得到的空气量。不过，那些旧房子倒有许多自然的通风口。","language":"中文","translation":false},{"id":"capital-24-245","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":245,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"甘布林盖属于几个地主所有。这里到处都可以看到破烂不堪的小屋。许多人以编草辫为业。甘布林盖到处都是致命的疲惫，到处都绝望地屈服于肮脏生活。中心地区年久失修已经成为南北两端灾难加深的根源，在这两端房子正一座接一座地倒塌下去。另有住处的地主们对这些穷窝敲骨吸髓。房租贵极了；8—9个人硬挤在一间卧室里，有两处是6个大人各带着1—2个孩子挤在一间小小的卧室里。","language":"中文","translation":false},{"id":"capital-24-246","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":246,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在本郡的许多教区，小屋和居民同时减少。但是至少有22个教区，房屋的拆除并没有阻止住居民的增加，或者说，没有引起那种到处发生的以“向城市移居”为名而进行的驱逐居民的现象。在面积为3443英亩的芬格林格霍教区，1851年有房屋145座，到1861年只剩了110座，但是居民不愿意搬走，并且甚至在这样的条件下，人口还增加了。在腊姆斯登－克莱斯教区，1851年252人住在61座房屋里，而到1861年，262人却挤在49座房屋里。在面积为1827英亩的巴西耳登教区，1851年157人住35座房屋，10年以后，180人却只住27座房屋。在总面积为8449英亩的芬格林格霍、南芬桥、威德福德、巴西耳登和腊姆斯登－克莱斯等教区，1851年1392人住316座房屋，到1861年，在同样大的面积上1473人却只住249座房屋。","language":"中文","translation":false},{"id":"capital-24-247","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":247,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这个小郡受“驱逐风气”之苦比英格兰任何其他郡都更厉害。在马德利，小屋挤得满满的，这些小屋通常有两间卧室，多半为租地农场主所有。他们很容易按每年3镑或4镑的租金出租这些小屋，而他们每周支付的工资才9先令！","language":"中文","translation":false},{"id":"capital-24-248","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":248,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"哈特福德教区，1851年有房屋87座，此后不久，这个面积为1720英亩的小教区拆除了19座小屋。居民1831年452人，1851年382人，1861年341人。调查过的14座小屋，都只有一间卧室。其中一座小屋住着一对夫妇，3个成年儿子、1个成年姑娘、4个小孩，共计10人。另一座住着3个大人、6个小孩。有一个房间长12呎10吋，宽12呎2吋，高6呎9呎，住着8个人；连房内突出部分计算在内，平均每人占有的空间才将近130立方呎。在这14间卧室内，共住着34个大人和33个小孩。这些小屋四周很少有小园圃，不过许多住户可以按每路得（1/4英亩）10或12先令的租金租到一小块土地。这些地块离住宅很远。住宅没有厕所。全家人都不得不到自己的地里去大便，或者，这简直很难说出口，干脆就拉在一个橱柜的抽屉里，满了以后，便抬到需要粪便的 地方倒掉。在日本，生活条件的循环也要比这清洁些。","language":"中文","translation":false},{"id":"capital-24-249","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":249,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"兰格托弗特：在莱特的房屋中住着1个男人、他的妻子、岳母和5个孩子。这座房屋一进门有个厨房，还有个洗濯间，厨房顶上是卧室。厨房和卧室长12呎2吋，宽9呎5吋。房屋总面积长21呎3吋，宽9呎5吋。卧室是个小阁楼，四壁象宝塔糖一样越往上越收拢，正面开着一个天窗。他为什么要住在这里？因为有园圃吗？园圃小极了。因为房租吗？房租很贵，每周1先令3便士。因为离工作地点近吗？不，离工作地点有6哩远，他每天来回要走12哩路。他住在这里，只是因为这座小屋可以租到，并且他想找一座独门独户的小屋，而不管房子在什么地方，租价多高，好坏如何。下面是兰格托弗特教区12座房屋的统计资料 ，这些房屋都只有一间卧室，共住着38个大人和36个小孩。","language":"中文","translation":false},{"id":"capital-24-250","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":250,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"肯宁顿，1859年居民拥挤到了极点，当时发生了白喉，教区医生对居民中较贫困阶级的状况进行了一次卫生调查。他发现，在这个需要大量劳动的地方，好多小屋被拆除了，却没有建造新的。在一个地区有4座被称为鸟笼的小房子，每座有4个房间，其大小如下：","language":"中文","translation":false},{"id":"capital-24-251","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":251,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"布里克斯沃思、皮茨福德、弗路尔：这3个村庄中，一到冬天就有20—30个人因为找不到工作流落街头。租地农民栽种的谷物和块根作物往往种得不够好，因此地主认为最好还是把他所有的租地合并成2—3片大地块。这样一来就造成了失业现象。一边是土地需要耕种，另一边是受欺诈的工人眼巴巴地望着土地。工人们夏天拚死拚活地劳动，而冬天却要忍饥挨饿，难怪工人们用他们自己的方言说：“牧师和贵族好象勾结起来要逼死他们”。","language":"中文","translation":false},{"id":"capital-24-252","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":252,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"弗路尔村有好几家这样的例子：一间极其狭窄的卧室住着一对夫妇和4、5或6个孩子，或者是住着3个大人和5个孩子，或者是住着一对夫妇、祖父和6个患猩红热的孩子，如此等等。有两座各有两间卧室的房子，住着两户人家，分别有8个大人和9个大人。","language":"中文","translation":false},{"id":"capital-24-253","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":253,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"斯特腊顿：调查过31座房屋，其中8座都只有一间卧室。在这个教区的彭希耳地方，有一座小屋，每周租金1先令3便士，住着4个大人和4个孩子，除了还算象样的墙壁之外，从粗糙的碎石铺成的地面到腐烂的茅草屋顶，没有一处好地方。","language":"中文","translation":false},{"id":"capital-24-254","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":254,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这里拆除房屋的现象并不那么严重，但是从1851年到1861年，每座房屋容纳的人数平均由4.2人增加到4.6人。","language":"中文","translation":false},{"id":"capital-24-255","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":255,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"巴德西：这里有许多小屋和小园圃。有些租地农场主说，小屋“是个大祸害，因为它招引穷人”。一个绅士说：","language":"中文","translation":false},{"id":"capital-24-256","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":256,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“穷人不会因此得到什么好处；即使再修建500座小屋，也会象面包一样被一抢而光；事实上，修建得越多，需要量也就越大”——","language":"中文","translation":false},{"id":"capital-24-257","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":257,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"照他看来，房屋产生住户，而住户又按照自然规律对“住房”产生压力。汉特医生在回答这种说法时指出：","language":"中文","translation":false},{"id":"capital-24-258","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":258,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“但是这些穷人必然是来自某个地方。既然巴德西没有任何慈善事业之类能特别吸引人的东西，那必然是在另一个更不合适的地方存在着某种把他们赶到这儿来的排斥力。如果每个人都能在自己的劳动地点附近找到一座小屋和一小块土地，那他当然宁愿住在这种地方而不会搬到巴德西来了。在巴德西，他租一小块土地的租金比租地农场主所付的租金贵一倍。”","language":"中文","translation":false},{"id":"capital-24-259","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":259,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"人口不断地流往城市，农村人口由于租地集中、耕地变成牧场、采用机器等原因而不断地“变得过剩”，农村人口因小屋拆除而不断地被驱逐，这种种现象是同时发生的。一个地区的人口越稀少，那里的“相对过剩人口”就越多，他们对就业手段的压力就越大，农村人口多于住房的绝对过剩也就越大，从而农村中地方性的人口过剩以及最容易传染疾病的人口拥挤现象也就越严重。人群密集在分散的小村庄和小市镇的现象，同人们被强行从地面上赶走是相适应的。尽管农业工人的人数不断减少，他们的产品的数量不断增加，但他们还是不断地“变得过剩”，这是使他们成为需要救济的贫民的温床。他们可能成为需要救济的贫民，是他们被驱逐的一个原因，也是居住条件恶劣的主要根源，而居住条件恶劣又打破了他们最后的反抗能力，使他们完全变成地主和租地农场主的奴隶，以致获得最低的工资对他们来说已成了天经地义。另一方面，农村中尽管经常出现“相对过剩人口”，但同时也感到人手不足。这种现象不仅局部地发生在人口过快地流往城市、矿山、铁路工地等处的地区，而且在收割季节以及在春夏两季，当英国的精耕细作的、集约化的农业需要额外劳力的许多时候，到处都可以看到。农业工人按耕作的平均需要来说总是过多，而按特殊的或者临时的需要来说又总是过少。因此，在官方的文件中可以看到同一地区同时发出的自相矛盾的抱怨，既抱怨劳力不足，又抱怨劳力过剩。临时性的或局部的劳力不足并不会引起工资的提高，只会迫使妇女和儿童也参加田间劳动，使工人的平均年龄不断下降。一旦妇女和儿童被大规模地使用，这又会反过来成为一种新的手段，造成农业中男工过剩，并使他们的工资下降。这种恶性循环的美好结果之一是所谓的帮伙制度，这种制度在英格兰东部地区正在兴盛起来。下面我简单地谈谈这种制度。","language":"中文","translation":false},{"id":"capital-24-260","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":260,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"帮伙制度几乎是林肯、杭廷登、剑桥、诺福克、萨福克和诺定昂等郡所独有的，在邻近的北安普顿、培德福德和拉特兰德各郡的个别地方也可以见到。我们且举林肯郡为例。这个郡的很大一部分是新地，原来是些沼泽，或者象上述东部其他各郡的一些地方一样，是刚从海水下夺来的土地。蒸汽机在排水方面创造了奇迹。过去的沼泽地和沙地现在已成了一片富饶的米粮川，可以得到最高的地租。阿克斯霍姆岛及特伦特河沿岸其他教区人工开拓的冲积地也是如此。新的租地农场出现了，然而不但没有相应地修建新的小屋，连旧的小屋也拆毁了，劳力供给来自几哩以外的、分布在蜿蜒于丘陵之间的大道两旁的开放村庄。从前居民只是为了躲避漫长的冬季水患才到那里居住。在400—1000英亩的租地农场上长期住着一些工人（他们在当地被称为定居工人），他们专门干经常性的使用马匹的繁重农活。每100英亩（1英亩＝40.49公亩或1.584普鲁士亩）土地平均还摊不到一座小屋。例如，一个租种沼泽地的租地农场主对童工调查委员会说：","language":"中文","translation":false},{"id":"capital-24-261","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":261,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“我的租地占地320多英亩，全是耕地。没有小屋。有一个工人现在住在我这里。我有四个养马工，住在农场附近。需要大量人手的轻活都找帮伙去做。”","language":"中文","translation":false},{"id":"capital-24-262","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":262,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"田间有许多轻活，如除草、松土、施肥、拣石子等等。所有这些活都由住在开放村庄的帮伙，即一群有组织的人来干。","language":"中文","translation":false},{"id":"capital-24-263","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":263,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"每个帮伙由10人至40或50人组成，有妇女、男女青少年（13—18岁，不过少年们大多一到13岁就离开帮伙）和男女儿童（6—13岁）。为首的是帮头，他通常是一个普通农业工人，多半是所谓的坏蛋，无赖汉，漂泊不定，好酗酒，但是有一定的胆识和才干。他招募帮伙，帮伙在他指挥下干活，而不是在租地农场主指挥下干活。他多半从租地农场主那里按活茬包揽农活，他的收入平均起来不会比一个普通农业工人的收入高出许多〔注：但是有的帮头已变成了拥有500英亩土地的租地农场主，有的则变成了成片房屋的所有主〕 ，这种收入几乎完全要看他有多大本领能在最短时间内使他的那伙人付出最大量的劳动。租地农场主们发现，妇女只有在男子的专制下才能好好地干活，而妇女和儿童一干起活来，正象傅立叶已经知道的那样，就会拚命地使出自己的全身力气，可是成年男工却很滑头，总是尽量节省力气。帮头带着人从一个庄园到另一个庄园，一年中能使他的帮伙干6—8个月的活。因此对工人家庭来说，同他打交道要比同个别租地农场主打交道有利和可靠得多，因为租地农场主只是偶而才雇用孩子。这种情形大大地巩固了他在开放村庄中的权势，以致孩子们多半只有经过他的介绍才能找到工作。从帮伙中抽出个别儿童向外出租，成了他的副业。","language":"中文","translation":false},{"id":"capital-24-264","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":264,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这种制度的“阴暗面”，就是儿童和青少年要从事过度劳动，他们每天要到5、6哩有时甚至7哩以外的庄园去劳动，往返时要长途跋涉，最后，“帮伙”内道德败坏。虽然帮头（在某些地区被称为“赶牲口的人”备有一根长棍子，但是他很少用它打人，极少听到有谁抱怨他虐待人。他是一个民主的皇帝，或者有些象哈默伦的捕鼠者。他需要在自己的臣民中树立威望，他用那种在他的庇护下风行一时的茨冈式的生活把他的臣民笼络住。粗野的放纵，漫无节制的寻欢作乐和极端伤风败俗的猥亵行为，使帮伙具有巨大的魔力。帮头常常在下流酒馆里畅饮到囊空如洗，然后酣醉而归，左右各由一个慓悍的女人搀扶着，走在行列的前头，儿童和青少年跟在后面乱嚷乱叫，唱着嘲讽轻浮的歌曲。在回家的路上，傅立叶所说的“男女公开”已经成了习以为常的事。十三四岁的女孩因她们的年龄相仿的男伙伴而怀孕的现象屡见不鲜。帮伙所在的开放村庄变成了淫乱罪恶之地，这些地方的非婚生子比王国的其他地方要多一倍。受这种环境薰陶的姑娘出嫁以后，在道德上会落到怎样的结果，我们在前面已经指出。她们的子女即使不被鸦片毁掉，也是帮伙的天生的新兵。","language":"中文","translation":false},{"id":"capital-24-265","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":265,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"上面所说的是帮伙的典型形式，这种帮伙称为公开的，公共的或流动的帮伙。此外，还有私人帮伙。私人帮伙的组成同普通帮伙一样，但人数较少，并且不是在帮头手下干活，而是在一个租地农场主不知如何使用才好的老雇农手下干活。这里没有茨冈式的放荡不羁的生活，但是各种证词表明，儿童的报酬和待遇变坏了。","language":"中文","translation":false},{"id":"capital-24-266","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":266,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"最近几年来不断扩大的帮伙制度当然不是为了帮头的需要而存在的。它是为了大租地农场主或地主的发财致富的需要而存在的。在租地农场主看来，再没有更巧妙的办法能把他的工人人数大大压低到正常水平以下，又能经常拥有一批额外劳力来应付额外工作，花尽量少的钱榨取尽量多的劳动，并使成年男工“过剩”。根据以上所述，我们可以了解，为什么人们一方面承认农民处于不同程度的失业中，而另一方面又认为，由于男劳力缺乏并流往城市，帮伙制度是“必要的”。林肯郡等地的已清除杂草的田地和人类的杂草，就是资本主义生产的对立的两极。","language":"中文","translation":false},{"id":"capital-24-267","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":267,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"在结束本节时，我们还应该到爱尔兰去看一看。首先说一说与此有关的事实。","language":"中文","translation":false},{"id":"capital-24-268","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":268,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"爱尔兰的人口，1841年曾达到8222664人，1851年减少到6623985人，1861年减少到5850309人，1866年减少到5500000人，即几乎减少到1801年的水平。人口减少是从饥荒的1846年开始的，此后不到20年的工夫，爱尔兰就失去了它的总人口的5/16以上。1851年5月到1865年7月，从爱尔兰移居国外的总人数为1591487人，而在1861年到1865年最近5年间移居国外的人口达500000人以上。住宅从1851年到1861年减少了52990座。从1851年到1861年，15—30英亩的租地农场增加61000个，30英亩以上的租地农场增加109000个，但是全部租地农场的总数减少了120000个。可见，减少的原因完全是由于15英亩以下的租地农场不断消灭了，也就是说，它们不断集中了。","language":"中文","translation":false},{"id":"capital-24-269","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":269,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"随着人口的减少，自然，产品量总的来说也减少了。从我们的目的来说，只要考察一下1861年到1865年这5年就够了。这5年间，有500000以上的人口移居国外，绝对人口数减少了330000以上。","language":"中文","translation":false},{"id":"capital-24-270","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":270,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"现在我们再来看看为牲畜和人提供生活资料的农业。下表中的各年度的数字是比上一年度减少或增加的数字。谷物包括小麦、燕麦、大麦、黑麦、菜豆和豌豆；蔬菜包括马铃薯、芜菁、厚皮菜、甜菜、白菜、胡萝卜、美洲防风、小豌豆等等。 1865年，“草地”增加了127470英亩，这主要是由于“未开垦的荒地和泥沼地”减少了101543英亩。我们把1865年同1864年比较一下，则可以看到谷物减少了246667夸特，其中小麦减少48999夸特，燕麦减少166605夸特，大麦减少29892夸特，等等；马铃薯种植面积在1865年虽然有所增加，但是收获量却减少446398吨，等等（见C表）。","language":"中文","translation":false},{"id":"capital-24-271","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":271,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"我们以上考察了爱尔兰的人口和农业生产的变动，现在再说一说爱尔兰地主、大租地农场主和工业资本家的财产的变动。这种变动反映在所得税的增减上。为了便于理解下面的D表，应当指出，D项（把租地农场主的利润除外的利润）也包括所谓“自由职业”的利润，即律师、医生等的收入，表内没有单独列出的C和E项则包括官吏、军官，领干薪的挂名官员、国债债权人等的收入。","language":"中文","translation":false},{"id":"capital-24-272","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":272,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"1853年到1864年，D项收入每年平均只增长0.93％，而同一时期在大不列颠该项收入每年平均却增长4.58％。下表表明1864年和1865年利润（租地农场主的利润除外）的分配情况。","language":"中文","translation":false},{"id":"capital-24-273","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":273,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"英格兰是一个资本主义生产发达和工业占优势的国家，如果它的人口也象爱尔兰那样放血般地外流，它也许已失血而死。但是今天的爱尔兰仅仅是英格兰的一个被大海峡隔开的农业区，它为英格兰提供着谷物，羊毛，牲畜，工业新兵和军事新兵。","language":"中文","translation":false},{"id":"capital-24-274","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":274,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"人口的减少使许多土地废止耕种，使农产品大大减少，并且，尽管牧场面积扩大了，但是某些畜牧部门的生产绝对减少了，而在另外一些部门中，即使有一点微不足道的进步，也经常为退步所中断。然而，在人口减少的同时，地租和租地农场主的利润却继续增加，虽然后者的增加不象前者那样经常不断。原因是容易理解的。一方面，随着租地农场集中和耕地变为牧场，总产品中越来越大的部分转化为剩余产品。虽然总产品减少了，但是构成其中一部分的剩余产品增加了。另一方面，这些剩余产品的货币价值比它们的数量增长得更快，因为最近20年来，特别是最近10年来，肉类、羊毛等等的英格兰市场价格不断地上涨了。","language":"中文","translation":false},{"id":"capital-24-275","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":275,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"正如生产者所消费的他自己的产品不是商品一样，充当生产者本身的就业手段和生存资料而不合并别人劳动以自行增殖的分散的生产资料，也不是资本。随着人口的减少，用在农业上的生产资料量也减少了，但是用在农业上的资本量却增加了，因为从前分散的生产资料中的一部分转化成了资本。","language":"中文","translation":false},{"id":"capital-24-276","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":276,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"爱尔兰用在农业以外即投入工商业的总资本，在最近二十年间积累得很缓慢，而且处在经常不断的大波动之中。但是，这个总资本的各个组成部分的积聚却发展得更快了。最后，尽管它的绝对增长量很小，但是相对地说，即同已经减少的人口比较起来，它还是增大了。","language":"中文","translation":false},{"id":"capital-24-277","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":277,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"因此，这里在我们眼前大规模地展开了一个过程。正统的经济学不能指望有比这更美好的东西可用来证实他们的教条了。按照他们的教条，贫困是由绝对的人口过剩产生的，减少人口才能够恢复平衡。这是同马尔萨斯信徒所极力赞美的十四世纪中叶的鼠疫完全不同的另一重要实验。顺便指出，把十四世纪的尺度应用到十九世纪的生产关系和相应的人口关系上来，这本身就是一种学究式的天真，况且这种天真的做法还忽略了一个事实：随那次鼠疫以及由此发生的人口大量减少之后，在海峡此岸的英格兰接踵而来的固然是农村人口的解放和致富，但在海峡彼岸的法兰西却是更加残酷的奴役和更大的贫困。","language":"中文","translation":false},{"id":"capital-24-278","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":278,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"爱尔兰1846年的饥荒毁灭了一百万人以上，但是毁灭的全是穷人。饥荒没有使该国的财富遭受丝毫损失。此后二十年不断扩大的人口外流，也不象三十年战争那样，在人口大量减少的同时使他们的生产资料也大量减少。爱尔兰的天才发明一种崭新的方法，象行妖术一样把穷人从他们的贫困之境送到数千里之外。迁往北美合众国的移民，逐年寄回家一笔钱，给留下来的人做旅费用。今年迁出去的一批人会在明年带走另外一批人。这样一来，向国外移民不仅不需要爱尔兰花费什么，相反地成了它的出口业中最能获利的部门之一。最后，这种向国外移民又是一个系统的过程，它不只是暂时地为人口钻开一个出口，它每年从人口中吸走的人数要比新生的人数多，结果是绝对人口水平年复一年地下降。","language":"中文","translation":false},{"id":"capital-24-279","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":279,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"那些得以避免成为过剩人口而留下来的爱尔兰工人的结局又是怎样的呢？目前的相对过剩人口同1846年以前一样庞大；工资同样很低，劳动的折磨更重；农村的贫困再一次逼近新的危机。原因很简单。农业革命和向国外移民保持同一步伐。相对过剩人口的生产比人口的绝对减少更快。看一下C表就可以知道，在爱尔兰，耕地变成牧场必然比在英格兰发生更加强烈的作用。在英格兰，随着畜牧业的发展，菜类的生产也发展了，而在爱尔兰却减少了。从前的大片耕地变成了休耕地或永久的草地，而同时一大部分从前未开垦的荒地和泥沼地被用来扩大畜牧业。中小租地农场主——我把耕地不超过100英亩的租地农场主全都计算在内——仍然约占总数的8/10。他们越来越受到资本主义农业生产的竞争的空前压迫而被挤垮，因此不断地为雇佣工人阶级提供新兵。爱尔兰唯一的大工业，亚麻加工业，需要的成年男工比较少，虽然自从1861年到1866年棉花涨价以来这种工业扩大了，但总的来说，它只能雇用居民中较小的一部分人。象所有其他大工业一样，它由于不断发生波动而在本部门内不断地生产出相对过剩人口，即使在它吸收的人数绝对增加的情况下也是如此。农村居民的贫困成为巨大的衬衫厂等等的基础，这类工厂的劳动大军大部分散布在农村中。在这里，我们又一次碰到前面曾经叙述过的家庭劳动制度。低工资和过度劳动是这种制度“生产过剩人口”的系统的手段。最后，人口的减少虽然没有带来象它在资本主义生产发达的国家所带来的那样破坏性后果，但是也不能不对国内市场产生经常的反作用。国外移民现象在这里所造成的空隙，不仅使地方性的劳动需求缩小了，而且也使小店主、手工业者，总之，一切小企业主的收入减少了。E表内60—100镑收入的减少，就是由于这种原因。","language":"中文","translation":false},{"id":"capital-24-280","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":280,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"关于爱尔兰农业短工的状况，在爱尔兰济贫法视察员的报告（1870年）中叙述得很清楚。这些视察员既然供职于一个只有靠刺刀，靠时而公开时而隐蔽的戒严状态才得以维持的政府，所以在措辞上不得不十分审慎，而这是他们的英格兰的同僚们所不齿的。尽管如此，他们也没有让他们的政府沉湎于幻想。据他们说，农村中工资率至今仍然很低，可是最近20年来已经提高了50—60％，现在每周平均是6—9先令。但是在这种表面提高的背后，隐藏着工资的实际降低，因为工资的提高并没有和同一时期必要生活资料的涨价保持平衡；从爱尔兰某个贫民习艺所的官方报告中摘引的如下数字就可作为例证。","language":"中文","translation":false},{"id":"capital-24-281","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":281,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"可见，同二十年前比较，必要生活资料的价格几乎上涨了一倍，而衣类的价格恰好上涨一倍。","language":"中文","translation":false},{"id":"capital-24-282","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":282,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"即使撇开这种不平衡不说，只是比较用货币表示的工资率，也远不能得出正确的结论。在饥荒以前，农村的工资大部分是用实物支付的，用货币支付的只是极小一部分；而今天，用货币支付已经是通例了。由此就可以得出结论：不管实际工资如何变动，货币工资率必然提高。","language":"中文","translation":false},{"id":"capital-24-283","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":283,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“饥荒以前，农业短工还有一小块土地，用来种植马铃薯，饲养猪和家禽。现在，他不仅要购买一切生活资料，而且连出卖猪、家禽和蛋类所得的收入也丧失了。” 在早些时候，农业工人实际上又是小租地农民，他们大多只是中等农场和大农场的后卫部队，在这些农场里找些活干。只是在1846年的灾荒以后，他们才开始构成纯粹雇佣工人阶级的一部分，构成一个同他们的雇主只发生货币关系的特殊阶层。","language":"中文","translation":false},{"id":"capital-24-284","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":284,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"我们已经知道1846年以前农业工人的居住状况是怎样的。从那以后，他们的居住状况更糟了。一部分农业短工尽管人数日益减少，仍然居住在租地农场主土地上的拥挤不堪的小屋里，这种住处的可怕情景远远超过了英格兰各农业地区最坏的居住情况。除了乌尔斯脱的某些地区以外，到处都是如此：南部有科克、里美黎克、基尔肯尼等郡，东部有威克洛、威克斯弗特等郡，中部有国王郡、女王郡、都柏林郡等，北部有达翁、安特林、提朗等郡，西部有斯来果、罗斯考门、梅沃、高尔威等郡。一个视察员感慨地说：“这简直是对宗教和我国文明的污辱。”为了使短工们的洞窟生活更舒服些，那些自古以来就附属于住宅的小块土地也被系统地没收了。","language":"中文","translation":false},{"id":"capital-24-285","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":285,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“由于意识到是地主及其管家使他们受到这种非人待遇，农业短工对那些把他们当作无权人种看待的人，产生了一种相应的对抗情绪和憎恨心理。”","language":"中文","translation":false},{"id":"capital-24-286","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":286,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"农业革命的第一个行动，就是以极大的规模，象奉天之命一样，拆除耕地上的那些小屋。因此，许多工人不得不到村镇和城市里去寻找栖身之所。在那里，他们就象废物一样被抛进阁楼，洞窟，地下室和最糟糕的街区的屋角里。爱尔兰人素来以罕有的眷恋乡土之情、开朗的性格和纯正的家风而著称，这是连抱有民族偏见的英格兰人也承认的，可是现在，成千上万个这样的爱尔兰家庭突然被移植到罪恶的温室中来了。男人们现在必须到邻近的租地农场主那里找寻工作，并且只能按日受雇用，因而工资收入极不稳定，同时，","language":"中文","translation":false},{"id":"capital-24-287","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":287,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“他们现在不得不在往返农场的路上长途跋涉，途中经常被雨淋透，还要吃到别的苦头，结果往往引起身体虚弱、疾病以致贫困”。","language":"中文","translation":false},{"id":"capital-24-288","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":288,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“城市不得不年年收容农业地区中被认为是过剩的工人”，可是令人奇怪的是，“城镇中工人过剩，而农村中则到处工人不足！”实际情形是，只有“在春秋农忙季节”才感到工人不足，“而在其余季节，很多人都闲着没事干”；“秋收以后，从10月到翌年开春，他们几乎找不到什么工作”；甚至在干活的季节，“他们也经常一连几天没事干，并且他们的工作还经常发生各种各样的中断”。","language":"中文","translation":false},{"id":"capital-24-289","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":289,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"农业革命——耕地变成牧场，采用机器，最严格的节约劳动等等——所引起的这些后果，被那些不在国外挥霍地租而甘愿住在爱尔兰本人领地内的典型地主们弄得更加严重了。为了使供求规律完全不受损害，这班老爷们","language":"中文","translation":false},{"id":"capital-24-290","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":290,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“现在几乎完全是从他们的小租地农民那里取得他们所需要的全部劳动，小租地农民这样就不得不为他们的地主做苦工，而工资通常比普通短工还要低。至于在播种或收割的紧急时刻，他们被迫搁下自己的田地而招致许多不便和损失，那就更不用说了”。","language":"中文","translation":false},{"id":"capital-24-291","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":291,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"可见，就业的没有保障和不稳定，频繁和长期的失业，所有这一切相对人口过剩的征候，都在济贫所视察员的报告中作为爱尔兰农业无产阶级的苦难列举出来了。我们记得，在英格兰农业无产阶级中我们已经看到过类似的现象。不过，不同的是，在工业国的英格兰，工业后备军是从农村得到补充，而在农业国的爱尔兰，农业后备军则是从城市，从被驱逐的农业工人的避难所得到补充。在英格兰，过剩的农业工人变成工厂工人，而在爱尔兰，被驱逐到城市里去的农业工人，虽然对城市的工资形成压力，但仍然是农业工人，并不断地被送回农村去找活干。","language":"中文","translation":false},{"id":"capital-24-292","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":292,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"官方报告的起草人对农业短工的物质状况作了如下的概述：","language":"中文","translation":false},{"id":"capital-24-293","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":293,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“虽然他们的生活极端俭朴，但是他们的工资只能勉勉强强应付他们自己及其家属吃住之用。要做衣服，他们得有另外的收入…… 他们的居住环境，加上其他方面的困苦，使得这个阶级特别容易感染伤寒和肺结核。”","language":"中文","translation":false},{"id":"capital-24-294","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":294,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这就无怪报告起草人都异口同声地证明，阴郁的不满情绪笼罩着这个阶级的行列，他们留恋过去，厌恶现在，绝望于将来，“受到煽动者的有害影响”，并且只有一个固执的想法：移居美洲。请看，伟大的马尔萨斯的万应灵药——减少人口，已经把绿色艾林变成了多么幸福的乐土！","language":"中文","translation":false},{"id":"capital-24-295","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":295,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"爱尔兰的工业工人又是过着怎样幸福的生活呢？举一个例子就可以说明。","language":"中文","translation":false},{"id":"capital-24-296","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":296,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"英格兰工厂视察员罗伯特·贝克说：","language":"中文","translation":false},{"id":"capital-24-297","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":297,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"“我最近视察爱尔兰北部的时候，看到一个熟练的爱尔兰工人靠自己少得可怜的收入尽力使自己的孩子受教育，这件事使我深为惊讶。我把他亲口所说的情形逐字逐句地写在下面。只要我说出他是被雇用来为曼彻斯特市场制造商品的，人们就会知道他是一个熟练的工厂工人。约翰逊说：我是一个清棉工，从星期一到星期五，都是从早晨6点钟干到夜里11点；星期六干到下午6点，有3个钟头的吃饭和休息时间。我有5个孩子。我每周劳动的收入是10先令6便士；我的妻子也做工，每周挣5先令。大女儿12岁，料理家务。她是我们的厨师和唯一的帮手。她照料弟妹上学。我的妻子和我同时起床上工。有一个小姑娘每天经过我家门口，她在早晨5点半钟把我叫醒。我们什么也不吃就去上工。白天，由12岁的女儿照顾弟妹。我们在8点钟回家吃早饭。我们每周只喝一次茶；我们平时喝粥，有时是燕麦片粥，有时是玉米面粥，这要看我们能弄到什么了。冬天，我们往玉米面里加一点糖和水。夏天，我们收点马铃薯，那是我们在一小块地上自己种的；马铃薯吃完了，还得喝粥。不管星期日也好，平日也好，一年到头就是这样过日子。晚上下工以后，我总是感到非常疲乏。我们偶而也能见到一小块肉，但那是太难得了。我们有3个孩子上学，每人每周要花费1便士。我们的房租每周9便士，泥炭和燃料每两周至少也要1先令6便士。”","language":"中文","translation":false},{"id":"capital-24-298","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":298,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这就是爱尔兰的工资，这就是爱尔兰的生活！","language":"中文","translation":false},{"id":"capital-24-299","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":299,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"事实上，爱尔兰的贫困又成了英格兰当前的话题了。1866年底和1867年初，有一个叫达费林侯爵的爱尔兰大地主，曾经在《泰晤士报》上着手讨论解决这个问题。“这位伟大的至尊多么仁慈啊！”","language":"中文","translation":false},{"id":"capital-24-300","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":300,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"我们从E表可以看出，1864年，3个谋利者从总利润4368610镑中只捞去262819镑，而1865年，同是这3位大“禁欲家”就从总利润4669979镑中捞去274528镑；1864年，26个谋利者得到646377镑，1865年，28个谋利者得到736448镑；1864年，121个谋利者得到1076912镑，1865年，150个谋利者得到1320906镑；1864年，1131个谋利者得到2150818镑，几乎占全年总利润的一半，1865年，1194个谋利者得到2418833镑，超过全年总利润的一半。可是，英格兰、苏格兰和爱尔兰的一小撮大地主从每年国民地租总额中吞掉的庞大数额是太惊人了，以致英国的治国明哲认为，关于地租的分配不宜于提出象利润分配这样的统计资料。达费林侯爵就是这些大地主中的一个。说地租和利润会在某个时候“过多”，或者说地租和利润的过多同人民的过于贫困有某种联系，这当然是既“不体面”又“不健全的”概念。侯爵依据的是事实。事实是，爱尔兰人口减少了，而爱尔兰的地租却增长了；人口减少对土地所有者“有利”，从而对土地以及仅仅是土地附属品的人民也“有利”。于是，侯爵宣告，爱尔兰的人口仍然过剩，人口外流仍然太慢。要想享有十足的幸福，爱尔兰至少还应该排出30多万工人。桑格拉都学派的医生见病人没有起色，就让放血，然后再放血，直到病人的血放完了，病也就没了。我们不要以为这位还很富有诗意的侯爵是个桑格拉都学派的医生。他只是要求再放30多万人的血而不是大约200万。但是事实上要想在爱尔兰建立起千年王国，非得放出大约200万人的血不可。证据是不难提出的。 1851年到1861年间的集中所消灭的主要是1英亩以下至15英亩的租地农场。这些农场必然首先被消灭。结果就产生了307058户“过剩”的租地农民，作一个低的估计，每家平均4口人，总人数就是1228232人。即使作一夸大的假定，假定农业革命完成后，其中的1/4将再度被吸收，结果仍须有921174人移居国外。16至100英亩的租地农场，用来经营资本主义的谷物生产也嫌太小，至于用来牧羊，就简直等于零，这是我们在英格兰早就知道的了。因此，在上述同样的假定下，又得有788761人移居国外，结果总人数就是1709532人。既然胃口越吃越大，所以地主们的眼睛立刻会发现，具有350万人口的爱尔兰仍然是个穷国，而贫穷的原因是人口过剩，因此，必须更进一步大力减少人口，才能完成它作为英格兰的一个牧羊场和放牧场的真正使命。〔注：在本书第三卷论述土地所有权的那一篇，我将更详细地谈到，单个的土地所有者以及英国的立法如何有计划地利用饥荒和由饥荒引起的情况来强力推行农业革命，并使爱尔兰的人口稀少到符合地主希望的程度。在那里我还要重新谈到小租地农民和农业工人的状况。这里只引证一段话。纳骚·威·西尼耳在他的遗著《关于爱尔兰的日志、谈话和短评》(两卷集，1868年伦敦版第2卷第282页)中提到：“G博士中肯地指出：我们有了一个济贫法，这是使地主取胜的强大工具；另一个工具就是往国外移民。没有一个爱尔兰朋友会希望战争<地主和克尔特族小租地农民之间的战争>拖延下去，更不希望这场战争以小租地农民获胜而告终……它<这场战争>越是迅速地结束，爱尔兰越是迅速地变成牧场国，同时人口相应地减少到一个牧场国所需要的程度，对一切阶级就越是有利。”1815年的英国谷物法保证了爱尔兰向大不列颠自由输入谷物的独占权。这样一来，谷物法就人为地促进了谷物生产。1846年，随着谷物法的废除，这种独占权突然消失了。即使撇开其他各种情况不说，单是这一事实就足以大大促使爱尔兰的耕地变成牧场、租地农场积聚和小农被驱逐。1815—1846年间，人们称赞爱尔兰土地的肥沃，大肆宣扬爱尔兰的土地天然适合种植小麦，可是后来，英国的农学家、经济学家和政治家们又突然发现，这些土地除适于种植青饲料外别无用处！莱昂斯·德·拉维涅先生也急急忙忙在海峡彼岸重复起这种论调。只有象拉维涅那样“认真”的人才会相信这种幼稚话。〕","language":"中文","translation":false},{"id":"capital-24-301","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":301,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"这个有利可图的方法，正象这个世界上一切美好的事物一样，也有它的缺陷。地租在爱尔兰不断积累着，而爱尔兰人则在美洲以同一步伐不断积累着。被羊和牛挤走的爱尔兰人作为芬尼亚社社员崛起于大洋彼岸了。年青的大共和国面对海上的老女皇越来越带威胁性地昂起头来。","language":"中文","translation":false},{"id":"capital-24-302","author":"马克思","title":"资本论·第一卷","location":"第二十三章 资本主义积累的一般规律","page":24,"paragraph":302,"url":"https://www.marxists.org/chinese/marx/capital/23.htm","text":"严酷的命运，兄弟互相残杀的罪孽，","language":"中文","translation":false},{"id":"capital-25-1","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-25-2","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"第二十四章 所谓原始积累","language":"中文","translation":false},{"id":"capital-25-3","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"我们已经知道，货币怎样转化为资本，资本怎样产生剩余价值，剩余价值又怎样产生更多的资本。但是，资本积累以剩余价值为前提，剩余价值以资本主义生产为前提，而资本主义生产又以商品生产者握有较大量的资本和劳动力为前提。因此，这整个运动好象是在一个恶性循环中兜圈子，要脱出这个循环，就只有假定在资本主义积累之前有一种“原始”积累（亚当·斯密称为“预先积累”），这种积累不是资本主义生产方式的结果，而是它的起点。","language":"中文","translation":false},{"id":"capital-25-4","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"这种原始积累在政治经济学中所起的作用，同原罪在神学中所起的作用几乎是一样的。亚当吃了苹果，人类就有罪了。人们在解释这种原始积累的起源的时候，就象在谈过去的奇闻逸事。在很久很久以前有两种人，一种是勤劳的，聪明的，而且首先是节俭的中坚人物，另一种是懒惰的，耗尽了自己的一切，甚至耗费过了头的无赖汉。诚然，神学中关于原罪的传说告诉我们，人怎样被注定必须汗流满面才得糊口；而经济学中关于原罪的历史则向我们揭示，怎么会有人根本不需要这样做。但是，这无关紧要。于是出现了这样的局面：第一种人积累财富，而第二种人最后除了自己的皮以外没有可出卖的东西。大多数人的贫穷和少数人的富有就是从这种原罪开始的；前者无论怎样劳动，除了自己本身以外仍然没有可出卖的东西，而后者虽然早就不再劳动，但他们的财富却不断增加。例如梯也尔先生为了替所有权辩护，甚至带着政治家的严肃神情，向一度如此富有才华的法国人反复叨念这种乏味的儿童故事。但是，一旦涉及所有权问题，那末坚持把儿童读物的观点当作对于任何年龄和任何发育阶段都是唯一正确的观点，就成了神圣的义务。 大家知道，在真正的历史上，征服、奴役、劫掠、杀戮，总之，暴力起着巨大的作用。但是在温和的政治经济学中，从来就是田园诗占统治地位。正义和“劳动”自古以来就是唯一的致富手段，自然，“当前这一年”总是例外。事实上，原始积累的方法决不是田园诗式的东西。","language":"中文","translation":false},{"id":"capital-25-5","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"货币和商品，正如生产资料和生活资料一样，开始并不是资本。它们需要转化为资本。但是这种转化本身只有在一定的情况下才能发生，这些情况归结起来就是：两种极不相同的商品所有者必须互相对立和发生接触；一方面是货币、生产资料和生活资料的所有者，他们要购买别人的劳动力来增殖自己所占有的价值总额；另一方面是自由劳动者，自己劳动力的出卖者，也就是劳动的出卖者。自由劳动者有双重意义：他们本身既不象奴隶、农奴等等那样，直接属于生产资料之列，也不象自耕农等等那样，有生产资料属于他们，相反地，他们脱离生产资料而自由了，同生产资料分离了，失去了生产资料。商品市场的这种两极分化，造成了资本主义生产的基本条件。资本关系以劳动者和劳动实现条件的所有权之间的分离为前提。资本主义生产一旦站稳脚跟，它就不仅保持这种分离，而且以不断扩大的规模再生产这种分离。因此，创造资本关系的过程，只能是劳动者和他的劳动条件的所有权分离的过程，这个过程一方面使社会的生活资料和生产资料转化为资本，另一方面使直接生产者转化为雇佣工人。因此，所谓原始积累只不过是生产者和生产资料分离的历史过程。这个过程所以表现为“原始的”，因为它形成资本及与之相适应的生产方式的前史。","language":"中文","translation":false},{"id":"capital-25-6","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"资本主义社会的经济结构是从封建社会的经济结构中产生的。后者的解体使前者的要素得到解放。","language":"中文","translation":false},{"id":"capital-25-7","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"直接生产者，劳动者，只有当他不再束缚于土地，不再隶属或从属于他人的时候，才能支配自身。其次，他要成为劳动力的自由出卖者，能把他的商品带到任何可以找到市场的地方去，他就必须摆脱行会的控制，摆脱行会关于学徒和帮工的制度以及关于劳动的约束性规定。 因此，使生产者转化为雇佣工人的历史运动，一方面表现为生产者从隶属地位和行会束缚下解放出来；对于我们的资产阶级历史学家来说，只有这一方面是存在的。但是另一方面，新被解放的人只有在他们被剥夺了一切生产资料和旧封建制度给予他们的一切生存保障之后，才能成为他们自身的出卖者。而对他们的这种剥夺的历史是用血和火的文字载入人类编年史的。","language":"中文","translation":false},{"id":"capital-25-8","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"工业资本家这些新权贵，不仅要排挤行会的手工业师傅，而且要排挤占有财富源泉的封建主。从这方面来说，他们的兴起是战胜了封建势力及其令人愤恨的特权的结果，也是战胜了行会及其对生产的自由发展和人对人的自由剥削所加的束缚的结果。但是，工业骑士之所以能够排挤掉佩剑骑士，只是因为他们利用了与自己毫不相干的事件。他们借以兴起的手段，同罗马的被释奴隶成为自己保护人的主人所使用的手段同样卑鄙。","language":"中文","translation":false},{"id":"capital-25-9","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"劳动者的奴役状态是产生雇佣工人和资本家的发展过程的起点。这一发展过程就是这种奴役状态的形式变换，就是封建剥削变成资本主义剥削。要了解这一过程的经过，不必追溯太远。虽然在十四和十五世纪，在地中海沿岸的某些城市已经稀疏地出现了资本主义生产的最初萌芽，但是资本主义时代是从十六世纪才开始的。在这个时代来到的地方，农奴制早已废除，中世纪的顶点——主权城市也早已衰落。","language":"中文","translation":false},{"id":"capital-25-10","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在原始积累的历史中，对正在形成的资本家阶级起过推动作用的一切变革，都是历史上划时代的事情；但是首要的因素是：大量的人突然被强制地同自己的生存资料分离，被当作不受法律保护的无产者抛向劳动市场。对农业生产者即农民的土地的剥夺，形成全部过程的基础。 这种剥夺的历史在不同的国家带有不同的色彩，按不同的顺序、在不同的历史时代通过不同的阶段。只有在英国，它才具有典型的形式，因此我们拿英国作例子。","language":"中文","translation":false},{"id":"capital-25-11","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"2、对农村居民土地的剥夺","language":"中文","translation":false},{"id":"capital-25-12","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在英国，农奴制实际上在十四世纪末期已经不存在了。当时，尤其是十五世纪，绝大多数人口是自由的自耕农，尽管他们的所有权还隐藏在封建的招牌后面。在较大的封建领地上，过去本身也是农奴的管事，被自由的租地农场主排挤了。农业中的雇佣工人包括两种人，一种是利用空闲时间为大土地所有者做工的农民，一种是独立的、相对说来和绝对说来人数都不多的真正的雇佣工人阶级。甚至后者实际上也是自耕农，因为除了工资，他们还分得四英亩或更多一些的耕地和小屋。此外，他们又和真正的农民共同利用公有地，在公有地上放牧自己的牲畜和取得木材、泥炭等燃料。在欧洲一切国家中，封建生产的特点是土地分给尽可能多的臣属。同一切君主的权力一样，封建主的权力不是由他的地租的多少，而是由他的臣民的人数决定的，后者又取决于自耕农的人数。因此，虽然英国的土地在诺曼人入侵后分为巨大的男爵领地，往往一个男爵领地就包括九百个盎格鲁撒克逊旧领地，但是小农户仍然遍布全国，只是在有些地方穿插有较大的封建领地。 这些情况，加上代表十五世纪特点的城市繁荣，就使大法官福特斯居在其《谈谈英国法律的优越性》一书中十分雄辩地描述过的人民财富能够产生出来，但是这些情况是排斥资本财富的。","language":"中文","translation":false},{"id":"capital-25-13","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"为资本主义生产方式奠定基础的变革的序幕，是在十五世纪最后三十多年和十六世纪最初几十年演出的。由于封建家臣（这些封建家臣，正如詹姆斯·斯图亚特爵士正确指出的，“到处都无用地塞满了房屋和城堡”）的解散，大量不受法律保护的无产者被抛向劳动市场。虽然王权这个资产阶级发展的产物在追求绝对权力时，用暴力加速了这些家臣的解散，但王权绝不是这件事情的唯一原因。不如说，同王室和议会顽强对抗的大封建主，通过把农民从土地（农民对土地享有和封建主一样的封建权利）上赶走，夺去他们的公有地的办法，造成了人数更多得无比的无产阶级。 在英国，特别是弗兰德毛纺织工场手工业的繁荣，以及由此引起的羊毛价格的上涨，对这件事起了直接的推动作用。大规模的封建战争已经消灭了旧的封建贵族，而新的封建贵族则是他们自己的时代的儿子，对这一时代说来，货币是一切权力的权力。因而，把耕地变为牧羊场就成了他们的口号。哈里逊在其著作《英国概述》（载于霍林舍德的编年史的卷首）中，描述了对小农的剥夺给国家造成了多么大的破坏。他写道：“我们的大掠夺者什么也不在乎！”农民的住房和工人的小屋被强行拆除，或者任其坍毁。哈里逊说：","language":"中文","translation":false},{"id":"capital-25-14","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“我们对照一下每一个骑士领地的旧财产清单，就会发现，无数的房屋和小农户消失了；现在土地供养的人口少得多了；虽然有一些新的城市繁荣起来，但是很多城市衰落了…… 城市和乡村为了作牧羊场而被毁坏，只有领主的房屋保留下来，这类情况我也能谈一些。”","language":"中文","translation":false},{"id":"capital-25-15","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"这些老的编年史的作者的抱怨总是夸大的，但是他们准确地描绘了生产关系的革命给当时的人们造成的印象。把大法官福特斯居的著作与大法官托马斯·莫尔的著作比较一下，我们就会清楚地看见十五世纪和十六世纪之间的鸿沟。桑顿说得对，英国工人阶级没有经过任何过渡阶段就从自己的黄金时代陷入了黑铁时代。","language":"中文","translation":false},{"id":"capital-25-16","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"立法被这一变革吓住了。它还没有达到这样的文明程度：把“国民财富”，也就是把资本的形成、对人民群众的残酷剥削和他们的贫困化当作全部国策的极限。培根在他的亨利七世执政史中说道：","language":"中文","translation":false},{"id":"capital-25-17","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“这时〈1489年〉人们越来越多地抱怨把耕地变成少数牧人就可照管的牧场〈牧羊场等〉；定期租地、终身租地和年度租地（很多自耕农靠年度租地生活）变成了领地。这使人民衰落，因而使城市、教会、什一税也衰落…… 国王和当时的议会为医治这一弊端表现出的智慧是值得赞叹的…… 他们采取措施来制止对公有地的灭绝人口的掠夺，来制止随之而来的灭绝人口的牧场的形成。”","language":"中文","translation":false},{"id":"capital-25-18","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"1489年亨利七世颁布的第19号法令，禁止拆毁附有20英亩以上土地的农民房屋。亨利八世二十五年颁布的法令，又重新规定这条法律。其中谈到：","language":"中文","translation":false},{"id":"capital-25-19","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“很多租地和大畜群，特别是大羊群，集中在少数人手中，因此地租飞涨，耕地荒芜，教堂和房屋被毁，无力养家糊口的人多得惊人。”","language":"中文","translation":false},{"id":"capital-25-20","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"因此法律规定重建那些荒废了的农场，制定耕地和牧场的比例等等。1533年的一项法令抱怨不少所有者拥有24000只羊，于是限定不得超过2000只。但是，人民的抱怨和从亨利七世以来150年内相继颁布的禁止剥夺小租地农民和农民的法律，都同样毫无效果。它们毫无效果的秘密，培根已经不自觉地透露给我们了。他在《文明与道德论文集》第29节中写道：","language":"中文","translation":false},{"id":"capital-25-21","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“亨利七世的法令是深思熟虑的和值得赞赏的，因为它建立了一定标准的农场和农舍，也就是说，为农场和农舍保持一定数量的土地，这样，它们就能提供相当富裕的、不是处于奴隶地位的臣民，并能使耕犁掌握在所有者手中，而不是掌握在雇工手中。”","language":"中文","translation":false},{"id":"capital-25-22","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"但是，资本主义制度却正是要求人民群众处于奴隶地位，使他们本身转化为雇工，使他们的劳动资料转化为资本。在这一过渡时期中，立法也曾力图使农业雇佣工人的小屋保有4英亩土地，并且禁止他们以自己的小屋招揽房客。1627年，在查理一世的时候，丰特米尔的罗吉尔·克罗克在丰特米尔的领地上修建一座小屋时，还因没有拨出4英亩土地作为小屋的永久附属物而被判罪；1638年，在查理一世的时候，还任命了一个皇家委员会来监督旧法律的实施，特别是关于4英亩土地的法律的实施；克伦威尔还禁止在伦敦周围4哩的地区内修建未附有4英亩土地的房屋。在十八世纪上半叶，如果农业工人的小屋未附有1—2英亩土地，他还会到法院去控告。但是现在，如果小屋附有一个小园子，或者在远离小屋的地方可以租到一点点土地，就是很幸运的了。汉特医生说：","language":"中文","translation":false},{"id":"capital-25-23","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“地主和租地农场主在这方面是行动一致的。他们认为，小屋附有几英亩土地就会使工人过于独立。”","language":"中文","translation":false},{"id":"capital-25-24","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在十六世纪，宗教改革和随之而来的对教会地产的大规模的盗窃，使暴力剥夺人民群众的过程得到新的惊人的推动。在宗教改革的时候，天主教会是英国相当大一部分土地的封建所有者。对修道院等的压迫，把住在里面的人抛进了无产阶级行列。很大一部分教会地产送给了贪得无厌的国王宠臣，或者非常便宜地卖给了投机的租地农场主和市民，这些人把旧的世袭佃户大批地赶走，把他们耕种的土地合并过来。法律保证贫苦农民对一部分教会什一税的所有权，也被暗中取消了。伊丽莎白女王一次巡视英国之后叫喊说：“穷人到处受苦难。”在她执政的第四十三年，终于不得不通过征收济贫税而正式承认有需要救济的贫民。","language":"中文","translation":false},{"id":"capital-25-25","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“这一法律的起草人不好意思说明起草该法律的理由，因此一反惯例，未附有任何说明性的序言就把该法律公布了。”","language":"中文","translation":false},{"id":"capital-25-26","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"查理一世十六年颁布的第4号法令宣布这项法律是永久性的，事实上只是在1834年，这项法律才获得新的更严格的形式。〔注：从下述事实也可以看出新教的“精神”。在英格兰南部，若干土地所有者和富有的租地农场主聚首集议，拟就了关于正确解释伊丽莎白济贫法的十个问题。他们请当时著名的法学家皇家律师斯尼格(后来在詹姆斯一世时曾任法官)对这十个问题发表意见。“第九个问题是：本教区某些富有的租地农场主想出了一个能排除法令执行中遇到的任何困难的巧妙计划。他们建议在本教区设立一座监狱。每个贫民如不愿被投入上述监狱，就不予救济。其次，应当通知邻近居民，如果有人打算租赁这个教区的贫民，他可以在一定的日子，以密封函件提出他愿出的最低价格。这个计划的起草人认为，邻郡有这样的人，他们不愿劳动，但又没有财产或信用，以便获得租地或船舶来过不劳而获的生活。这种人经过开导，可以对教区作一些很有益的事情。如果贫民在雇主的保护下死亡，那就罪在雇主，因为教区对这些贫民已经尽了自己的义务。但是，我们耽心，现行法令不会允许实施这类英明措施，但你们要知道，本郡及邻郡的所有其他的自由农都赞同我们的意见，来敦促他们的下院议员提出这样的法案：允许监禁贫民和强迫贫民劳动，从而使任何拒绝受监禁的人都无权要求救济。我们希望，这样能使贫民不致要求救济。”(罗·布莱基《古今政治文献史》1855年伦敦版第2卷第84、85页)——苏格兰农奴制的废除要比英格兰迟几百年。1698年索耳通的弗列特切尔还在苏格兰议会中说：“在苏格兰，乞丐的人数估计不下20万。我，一个原则上的共和主义者，能提出的消除这种现象的唯一办法是恢复农权制的旧状态，把一切没有能力独立谋生的人变为奴隶。”伊登在《贫民的状况》第1卷第1章第60、61页上说：“农民的自由是需要救济的赤贫的开始…… 工场手工业和商业是我国贫民的真正父母。”伊登和苏格兰的那位“原则上的共和主义者”的错误只在于：不是农奴制的废除，而是农民的土地所有权的废除，才使农民成为无产者，成为需要救济的贫民。——在法兰西，剥夺是以另外的方式完成的，但1566年的穆兰敕令和1656年的敕令相当于英格兰的济贫法。〕 宗教改革的这些直接的影响并不是它的最持久的影响。教会所有权是古老的土地所有权关系的宗教堡垒。随着这一堡垒的倾覆，这些关系也就不能维持了。〔注：罗杰斯先生当时虽然是新教正统派的故乡牛津大学的政治经济学教授，却在他所著的《英国的农业史和价格史》一书的序言中强调宗教改革使人民群众贫困化。〕","language":"中文","translation":false},{"id":"capital-25-27","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在十七世纪最后几十年，自耕农即独立农民还比租地农民阶级的人数多。他们曾经是克伦威尔的主要力量，甚至马考莱也承认，他们同酗酒的劣绅及其奴仆，即不得不娶主人的弃妾的乡村牧师相比，处于有利的地位。甚至农业雇佣工人也仍然是公有地的共有者。大约在1750年，自耕农消灭了，而在十八世纪最后几十年，农民公有地的最后痕迹也消灭了。我们在这里不谈农业革命的纯经济原因。我们只来研究一下它的暴力手段。","language":"中文","translation":false},{"id":"capital-25-28","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在斯图亚特王朝复辟时期，土地所有者通过立法实行掠夺，而这种掠夺在大陆各处都是不经过立法手续就直接完成了的。他们取消了封建的土地制度，也就是使土地摆脱了对国家的贡赋，以对农民和其他人民群众的课税来“补偿”国家，他们要求对地产的现代私有权（他们对地产只有封建权利），最后，他们强令实行定居法。只要把情况相应地改变一下，它们对英国农民的影响，就同鞑靼人波利斯·戈东诺夫的命令对俄国农民的影响一样。","language":"中文","translation":false},{"id":"capital-25-29","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“光荣革命”把地主、资本家这些谋利者同奥伦治的威廉三世一起推上了统治地位。他们开辟了一个新时代，使以前只是有节度地进行的对国有土地的盗窃达到了巨大的规模。这些土地被赠送出去了，被非常便宜地卖掉了，或者被用直接掠夺的办法合并到私人地产中去了。所有这一切都是在丝毫不遵守法律成规的情况下完成的。 用这种欺骗的方法攫取的国有土地和从教会夺来的土地，既然在共和革命中没有再度失去，就构成现今英国寡头政治的贵族领地的基础。市民资本家鼓励这种做法，为的是把土地变成纯粹的商品，扩大农业大规模生产的范围，增加来自农村的不受法律保护的无产者的供给等等。并且，新土地贵族又是新银行巨头这一刚刚孵化出来的金融显贵和当时靠保护关税支持的大手工工场主的自然盟友。英国资产阶级为了自身利益做得同瑞典的市民一样正确，虽然后者的做法相反：他们同自己的经济堡垒即农民协同一致，支持国王用暴力从寡头政府手中夺回王室土地（从1604年开始，后来在查理十世和查理十一世时继续进行）。","language":"中文","translation":false},{"id":"capital-25-30","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"公有地——同刚才谈的国有土地完全不同——是一种在封建制度掩护下保存下来的古代日耳曼制度。我们已经知道，对公有地的暴力掠夺大都伴有变耕地为牧场的现象，它开始于十五世纪末，在十六世纪还在继续下去。但是，当时这一过程是作为个人的暴力行为进行的，立法曾同这种暴力行为斗争了150年而毫无效果。十八世纪的进步表现为：法律本身现在成了掠夺人民土地的工具，虽然大租地农场主同时也使用自己独立的私人小办法。这种掠夺的议会形式就是“公有地圈围法”，换句话说，是地主借以把人民的土地当作私有财产赠送给自己的法令，是剥夺人民的法令。弗·摩·伊登爵士企图把公有地说成是代替封建主的大土地所有者的私有地，但是他自己把这种狡黠的辩护词否定了，因为他要求“为公有地的圈围制定一般性的议会法令”，即承认要把公有地变成私有地必须由议会采取非常措施，另一方面，他又要求立法对被剥夺的贫苦者给予“赔偿”。","language":"中文","translation":false},{"id":"capital-25-31","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"当任意租户，即按一年期限租佃土地的小租地农民，一群奴隶般地完全听大地主摆布的人，代替独立的自耕农时，对国有土地的掠夺，特别是对公有地的不断的盗窃，促使在十八世纪叫做资本租地农场或商人租地农场的大租地农场增长，并且促使农村居民变成无产阶级，把他们“游离”出来投向工业。","language":"中文","translation":false},{"id":"capital-25-32","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"但是，十八世纪的人还不象十九世纪的人那样清楚地了解到，国民财富和人民贫困是一回事。因此，当时经济著作中就有关于“公有地的圈围”的十分激烈的论战。我从手边的大量材料中只摘录几段话，因为这几段话就能生动地说明当时的情况。","language":"中文","translation":false},{"id":"capital-25-33","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“在哈特福郡的很多教区中，有24个平均占50—150英亩土地的租地农场被合并为3个租地农场了。”“在北安普顿郡和林肯郡，圈围公有地的做法十分流行，由于圈地而形成的新领地大部分都变成牧场；结果在很多领地中，现在耕地还不到50英亩，而过去曾经耕种过1500英亩…… 过去的住宅、谷仓、马厩等等变成的废墟”是以往居民留下的唯一痕迹。“在某些地方，100所房屋和家庭已经减少到……8所或10所…… 在大多数不过15年或20年前才开始圈地的教区，土地所有者的数目同以前耕种开放地的土地所有者的人数相比是很少的。往往还有这样的事情，4—5个富有的畜牧业主侵吞了不久前圈围的大片领地，这些土地以前是在20—30个租地农民和同样数目的较小的所有者以及其他居民的手里。所有这些人和他们的家属，从自己占有的土地上被赶走，同他们一起被赶走的，还有替他们做工以维持生活的许多其他户人家。”","language":"中文","translation":false},{"id":"capital-25-34","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"邻近的地主在圈地的借口下，不仅侵占了荒地，而且往往也侵占了个人以一定的租金向公社租来耕种的土地或共同耕种的土地。","language":"中文","translation":false},{"id":"capital-25-35","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“我这里是说开放地和已耕地的圈围。甚至为圈地辩护的作者也承认，圈地加强了大租地农场的垄断地位，提高了生活资料的价格，造成了人口的减少……甚至象现在这样进行的荒地的圈围，也使贫民失去他们的一部分生存资料，而把本来已经过大的租地农场更加扩大。”","language":"中文","translation":false},{"id":"capital-25-36","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“如果土地落到少数大租地农场主手中，那末小租地农民〈以前他是指“许多小土地所有者和小租地农民，他们靠自己耕种的土地上的产品和在公有地上放养的羊、家禽、猪等来维持自己和家庭的生活，因此几乎不必购买生存资料”〉就要变成这样一种人，他们必须为别人劳动才能维持生活，而且不得不到市场上去购买自己所需要的一切…… 劳动也许加多了，因为对劳动的强制更大了…… 城市和手工工场将会扩大，因为将有更多寻找职业的人被赶到那里去。这就是租地农场的扩大必然发生作用的道路，也是它多年以来在这个王国中实际发生作用的道路。”","language":"中文","translation":false},{"id":"capital-25-37","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"他把圈地的总的结果概括如下：","language":"中文","translation":false},{"id":"capital-25-38","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“总的说来，下层人民的状况几乎在各方面都恶化了，小土地所有者和小租地农民降到短工和雇工的地位；同时，在这种情况下谋生变得更加困难了。”","language":"中文","translation":false},{"id":"capital-25-39","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"确实，对公有地的掠夺和随之而来的农业革命，对农业工人产生十分强烈的影响，伊登自己就说，农业工人的工资在1765—1780年之间开始降到最低限度以下，因此必须由官方的济贫费来补助。他说，他们的工资“只够满足绝对必要的生活需要”。","language":"中文","translation":false},{"id":"capital-25-40","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"现在我们再听一下一位圈地卫护者，普莱斯博士的反对者的意见。","language":"中文","translation":false},{"id":"capital-25-41","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“因为不再看见人们在开放地上浪费自己的劳动，就得出人口减少的结论，这是不对的…… 如果小农转变成不得不替别人劳动的人之后，可以把更多的劳动动用起来，那末，这是国民〈那些已经经历转变的农民当然不在此列〉应当期待的一种利益…… 如果他们的结合的劳动在一个租地农场上使用，产品就会更多：这样就可以为工场手工业创造出剩余产品，从而工场手工业，这个国家的金矿之一，就会随着生产出的谷物量的增加而相应增加。”〔注：[约·阿伯思诺特]《当前粮食价格和农场面积相互关系的研究》第124、129页。下面这句话与此相类似，但倾向相反：“劳动者被赶出了自己的小屋，被迫去城市寻找职业；但这样便生产出了更多的剩余产品，于是资本也增大了”（[罗·本·西利]《国家的危险》1843年伦敦第2版第XIV页）。〕","language":"中文","translation":false},{"id":"capital-25-42","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"对“神圣的所有权”进行最无耻的凌辱，对人身施加最粗暴的暴力，只要这是为建立资本主义生产方式的基础所需要的，政治经济学家就会以斯多噶派的平静的心情来加以观察。带有托利党色彩的“博爱的”弗·摩·伊登爵士就是一个例子。从十五世纪最后三十多年到十八世纪末，伴随着对人民的暴力剥夺的是一连串的掠夺、残暴行为和人民的苦难，这些只不过使他得出下面这个“称心如意的”结论：","language":"中文","translation":false},{"id":"capital-25-43","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“必须确定耕地和牧场之间的适当的比例。在整个十四世纪和十五世纪的大部分时期，还要有2、3英亩甚至4英亩耕地才有1英亩牧场。在十六世纪中叶，这个比例变为2英亩牧场对2英亩耕地，后来是2英亩牧场对1英亩耕地，直到最后达到3英亩牧场对1英亩耕地这个适当的比例。”","language":"中文","translation":false},{"id":"capital-25-44","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"到十九世纪，人们自然甚至把农民和公有地之间的联系都忘却了。更不必谈最近的时期：1801年到1831年农村居民被夺去3511770英亩公有地，并由地主通过议会赠送给地主，难道农村居民为此得到过一文钱的补偿吗？","language":"中文","translation":false},{"id":"capital-25-45","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"最后，对农民土地的最后一次大规模剥夺过程，是所谓的Clearing of Estates（清扫领地，实际上是把人从领地上清扫出去）。“清扫”是前面谈过的英国的一切剥夺方法的顶点。我们在上面谈到现代状况时知道，在已经没有独立农民可以清扫的地方，现在是要把小屋“清扫”掉，结果农业工人在他们耕种的土地上甚至再也找不到必要的栖身之所了。至于“清扫领地”的真正含意，我们只有看看苏格兰高地这个现代小说中的天国，才可以领会。在那里，这个过程的特点是：它有系统性，有一举完成的巨大规模（在爱尔兰，地主同时把好几个村庄清扫掉；在苏格兰高地，一下子被清扫的土地面积相当于德意志几个公国），最后，还有被侵吞的土地所有权的特殊形式。","language":"中文","translation":false},{"id":"capital-25-46","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"苏格兰高地的克尔特人由氏族组成，每一氏族是该氏族所居住的土地的所有者。氏族的代表，即氏族的首领或“大人”，只是这块土地名义上的所有者，就象英国女王是全国土地名义上的所有者完全一样。英国政府虽然成功地镇压了这些“大人”之间的内部战争，制止了他们对苏格兰低地的不断侵袭，但是氏族首领们丝毫没有放弃自己原来的劫掠行径；他们只不过改变了形式而已。他们依靠自己的权威，把他们名义上的所有权变成私有财产权，由于遭到氏族成员的反抗，他们就决定公开使用暴力把氏族成员驱逐出去。纽曼教授说：","language":"中文","translation":false},{"id":"capital-25-47","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“英国国王可以有同样的权利把自己的臣民赶下大海。”","language":"中文","translation":false},{"id":"capital-25-48","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在苏格兰，这种革命是在王位觊觎者的拥护者进行了最后一次武装暴动后开始的，我们可以从詹姆斯·斯图亚特爵士和詹姆斯·安德森的著作中看到这一革命的最初阶段。在十八世纪，还禁止从土地上被赶走的盖尔人移居外国，以便用暴力把他们赶到格拉斯哥和其他工业城市去。至于十九世纪盛行的方法，在这里以萨特伦德公爵夫人进行的“清扫”作例子就够了。这位懂得经济学的女人一当权，就决定对经济进行彻底的治疗，并且把全郡——郡内的人口通过以前的类似过程已经减少到15000人——变为牧羊场。从1814年到1820年，这15000个居民，大约3000户，陆续地被驱逐和消灭了。他们的村庄全都被破坏和烧毁，他们的田地全都变成了牧场。不列颠的士兵奉命执行任务，同当地居民发生了冲突。一个老太婆因拒绝离开小屋而被烧死在里面。这位夫人用这种方法把自古以来就属于氏族的794000英亩土地据为己有了。她把沿海地区大约6000英亩的土地分配给这些被驱逐的居民，每户2英亩。这6000英亩土地以前一直是荒地，没有给所有者带来过收入。这位公爵夫人是如此的宽宏大量，她以平均每英亩2先令6便士的租金把这些荒地租给那些几百年来为她的家族流洒鲜血的氏族成员。她把从氏族那里夺来的全部土地划分为29个大牧羊租地农场，每一个租地农场住一户人家，他们大都是英格兰租地农场主的雇农。到1825年，15000个盖尔人已经被131000只羊所代替。被赶到海边的那部分土著居民企图靠捕鱼为生。他们成了两栖动物，用一位英国作家的话来说，他们一半生活在陆上，一半生活在水上，但是二者合在一起也只能使他们过半饱的生活。","language":"中文","translation":false},{"id":"capital-25-49","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"但是，诚实的盖尔人由于他们对氏族“大人”的山岳般浪漫的崇拜，必须更加含辛茹苦。 鱼的气味传到“大人”的鼻子里去了。他们嗅到其中有某种有利可图的东西，于是把沿海地区租给伦敦的大鱼商。盖尔人又一次被驱逐了。","language":"中文","translation":false},{"id":"capital-25-50","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"最后，一部分牧羊场又变成了狩猎场。大家知道，英格兰没有真正的森林。贵族们的鹿苑中的鹿长得象家畜，肥得象伦敦的市议员一样。所以，苏格兰是这种“高贵情欲”的最后的寄托所。1848年萨默斯写道：","language":"中文","translation":false},{"id":"capital-25-51","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“在苏格兰高地，森林面积大大扩大了。在盖克的一边，可以看见格伦菲希新森林，在另一边，是阿德佛里基新森林。在同一条线上，布拉克山这一大片荒地不久前植树造林了。从东到西，从阿贝丁附近到欧班峭壁，现在都是一条连绵不断的林带，而在高地的其他地方，又有洛赫－阿尔恰格、格连加里、格伦莫里斯顿等新森林出现…… 盖尔人由于他们的土地变为牧羊场……而被赶到更贫瘠的地方。现在鹿开始代替羊，使盖尔人更加贫困…… 鹿林〔注：在苏格兰的“鹿林”中没有一棵树木。人们把羊群从秃山赶走，把鹿群赶上秃山，并称此为“鹿林”。因此，连造林也谈不上！〕和人民不能并存。总有一方要让位。如果在未来的二十五年当中，狩猎场的数目和规模象过去二十五年那样增长，那末盖尔人就会在他们家乡的土地上绝迹了。苏格兰高地土地所有者中间进行的这个运动，一方面是出于时髦，贵族的欲望，打猎的爱好等等；另一方面，他们做鹿的交易只是为了牟取利润。因为事实是，把一块山地辟为狩猎场，在很多情况下都比把它变为牧羊场有利得多…… 对于爱好打猎而寻找狩猎场的人说来，出价高低只受自己钱袋大小的限制…… 苏格兰高地所受的痛苦，不下于诺曼人国王的政策给英格兰带来的痛苦。鹿有了更自由的活动场所，而人却被赶到越来越窄的圈子里去了…… 人民的自由接二连三地被夺去…… 压迫日甚一日。清扫和驱逐人民，象在美洲和澳洲的荒野上砍除树木和灌木丛一样，被当作固定的原则，当作农业上的必要，由地主们来实行；这一过程静静地、有条不紊地进行着。”","language":"中文","translation":false},{"id":"capital-25-52","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"掠夺教会地产，欺骗性地出让国有土地，盗窃公有地，用剥夺方法、用残暴的恐怖手段把封建财产和氏族财产变为现代私有财产——这就是原始积累的各种田园诗式的方法。 这些方法为资本主义农业夺得了地盘，使土地与资本合并，为城市工业造成了不受法律保护的无产阶级的必要供给。","language":"中文","translation":false},{"id":"capital-25-53","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"3、十五世纪末以来惩治被剥夺者的血腥立法。压低工资的法律","language":"中文","translation":false},{"id":"capital-25-54","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"由于封建家臣的解散和土地断断续续遭到暴力剥夺而被驱逐的人，这个不受法律保护的无产阶级，不可能象它诞生那样快地被新兴的工场手工业所吸收。另一方面，这些突然被抛出惯常生活轨道的人，也不可能一下子就适应新状态的纪律。他们大批地变成了乞丐、盗贼、流浪者，其中一部分人是由于习性，但大多数是为环境所迫。因此，十五世纪末和整个十六世纪，整个西欧都颁布了惩治流浪者的血腥法律。现在的工人阶级的祖先，当初曾因被迫变成了流浪者和贫民而受到惩罚。法律把他们看作“自愿的”罪犯，其依据是：只要他们愿意，是可以继续在已经不存在的旧的条件下劳动的。","language":"中文","translation":false},{"id":"capital-25-55","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在英国，这种立法是在亨利七世时期开始的。","language":"中文","translation":false},{"id":"capital-25-56","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"亨利八世时期，1530年，允许年老和无劳动能力的乞丐行乞。但对身强力壮的流浪者则加以鞭打和监禁。他们要被绑在马车后面，被鞭打到遍体流血为止，然后要发誓回到原籍或最近三年所居住的地方去“从事劳动”。多么残酷的讽刺！亨利八世二十七年，又重申了以前的法令，但由于加上了新的条款而更严厉了。如果在流浪时第二次被捕，就要再受鞭打并被割去半只耳朵；如果第三次被捕，就要被当作重罪犯和社会的敌人处死。","language":"中文","translation":false},{"id":"capital-25-57","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"爱德华六世在他即位的第一年（1547年）颁布的法令规定，拒绝劳动的人，如被告发为游惰者，就要判为告发者的奴隶。主人应当用面包和水，用稀汤和他认为适当的肉屑给自己的奴隶吃。他有权用鞭打和镣铐强迫奴隶从事一切令人厌恶的劳动。如果奴隶逃亡达14天，就要判为终身奴隶，并在额头或脸颊打上S字样的烙印，如果第三次逃亡，就要当作叛国犯处死。主人可以把他出卖，遗赠，作为奴隶出租，完全象对待其他动产和牲畜一样。如果奴隶图谋反抗主人，也要被处死。治安法官必须根据报告搜捕逃亡的奴隶。如果发现流浪者3天无所事事，就要把他送回原籍，用烧红的铁片在他胸前打上V字样的烙印，套上锁链在街道上服役或服其他劳役。如果流浪者谎报籍贯，就要被罚充当该地、该地居民或社团的终身奴隶，并打上S字样的烙印。任何人都有权把流浪者的子女领去当学徒，男的当到24岁为止，女的当到20岁为止。如果他们逃亡，就要成为他们师傅的奴隶，直到这个年龄为止。师傅可以给他们戴上镣铐，鞭打他们等等。为了便于识别和更加保险起见，每个主人可以在自己奴隶的脖子、手或脚上套一个铁环。这个法令的最后一部分规定，贫民必须在愿意给他们饮食和劳动的地区或个人那里干活。在英国，这种教区的奴隶，在游荡者的名义下一直保留到十九世纪。","language":"中文","translation":false},{"id":"capital-25-58","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"伊丽莎白执政时期的1572年的法令规定，没有得到行乞许可的14岁以上的乞丐，如果没有人愿意使用他两年，就要受猛烈的鞭打，并在左耳打上烙印；如果有人再度行乞而且年过18，又没有人愿意使用两年，就要被处死；第三次重犯，就要毫不容情地当作叛国犯处死。类似的法令还有伊丽莎白十八年所颁布的第13号法令和1597年的法令。 詹姆斯一世时期，游荡和行乞的人被宣布为流浪者。即决法庭的治安法官有权当众鞭打他们，把第一次被捕者监禁6个月，第二次被捕者监禁2年。在监禁期间，治安法官认为适当就可以随时鞭打他们，要打多少就打多少…… 不可救药的危险的流浪者，要在左肩打上R字样的烙印，并要从事强制劳动；如果他再度在行乞时被捕，那就要毫不容情地处死。这些条例直到十八世纪初还有效，到安女王十二年颁布第23号法令时才被废除。","language":"中文","translation":false},{"id":"capital-25-59","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"法国也有同样的法律，十七世纪中叶在巴黎建立了一个流浪者王国。在路易十六初期（1777年7月13日的敕令）还规定，16岁至60岁的身体强壮而没有生存资料或职业的人，都要罚做苦工。1537年10月查理五世对尼德兰颁布的法令，1614年3月19日荷兰各州和各城市的第1号告示，1649年6月25日联合省的公告等，都有类似的规定。","language":"中文","translation":false},{"id":"capital-25-60","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"这样，被暴力剥夺了土地、被驱逐出来而变成了流浪者的农村居民，由于这些古怪的恐怖的法律，通过鞭打、烙印、酷刑，被迫习惯于雇佣劳动制度所必需的纪律。","language":"中文","translation":false},{"id":"capital-25-61","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"单是在一极有劳动条件作为资本出现，在另一极有除了劳动力以外没有东西可出卖的人，还是不够的。这还不足以迫使他们自愿地出卖自己。在资本主义生产的进展中，工人阶级日益发展，他们由于教育、传统、习惯而承认这种生产方式的要求是理所当然的自然规律。发达的资本主义生产过程的组织粉碎一切反抗；相对过剩人口的不断产生把劳动的供求规律，从而把工资限制在与资本增殖需要相适应的轨道以内；经济关系的无声的强制保证资本家对工人的统治。超经济的直接的暴力固然还在使用，但只是例外地使用。在通常的情况下，可以让工人由“生产的自然规律”去支配，即由他对资本的从属性去支配，这种从属性由生产条件本身产生，得到这些条件的保证并由它们永久维持下去。在资本主义生产在历史上刚刚产生的时期，情况则不同。新兴的资产阶级为了“规定”工资，即把工资强制地限制在有利于赚钱的界限内，为了延长工作日并使工人本身处于正常程度的从属状态，就需要并运用了国家权力。这是所谓原始积累的一个重要因素。","language":"中文","translation":false},{"id":"capital-25-62","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"雇佣工人阶级是在十四世纪下半叶产生的，它在当时和后一世纪内只占居民中很小的一部分；它的地位受到农村的独立农民经济和城市的行会组织的有力的保护。在农村和城市，雇主和工人在社会上是接近的。劳动对资本的从属只是形式上的，就是说，生产方式本身还不具有特殊的资本主义的性质。资本的可变要素大大超过它的不变要素。因此，对雇佣劳动的需求随着资本的积累而迅速增加，而雇佣劳动的供给只是缓慢地跟在后面。后来变成资本积累基金的一大部分国民产品，在当时还是工人的消费基金。","language":"中文","translation":false},{"id":"capital-25-63","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"自始就是为了剥削工人，而在其发展中一直与工人为敌的关于雇佣劳动的立法，在英国开始于1349年爱德华三世的劳工法。在法国，与此相当的，是1350年以国王约翰名义颁布的敕令。英法两国的立法齐头并进，内容也相同。关于劳工法企图强制延长工作日这一点，我就不再谈了，因为前面（第8章第5节）已经讲过了。","language":"中文","translation":false},{"id":"capital-25-64","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"劳工法是由于下院的迫切要求而颁布的。一个托利党人天真地说：","language":"中文","translation":false},{"id":"capital-25-65","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“以前贫民要求的工资太高，使工业和财富受到威胁。现在他们的工资太低，也使工业和财富受到威胁，不过这种威胁和以前的不同，而且可能更危险。”","language":"中文","translation":false},{"id":"capital-25-66","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"法律规定了城市和农村、计件劳动和日劳动的工资率。农村工人受雇期限应为一年，城市工人则应在“自由市场”上受雇。支付高于法定工资的人要被监禁，但接受高工资的人要比支付高工资的人受到更严厉的处罚。例如，伊丽莎白的学徒法第18条和第19条规定，支付高工资的人，监禁十天，而接受的人，则监禁二十一天。1360年的法令加重了处罚，甚至授权雇主按法定的工资率通过体罚去榨取劳动。把瓦匠和木匠相互联系在一起的一切结合、契约、誓约等都被宣告无效。从十四世纪起到1825年废除禁止结社法止，工人结社一直被认为是严重的犯罪行为。1349年的劳工法和以后的一切类似法令的精神清楚地表现在这一事实上：国家虽然规定了工资的最高限度，但从来没有规定工资的最低限度。","language":"中文","translation":false},{"id":"capital-25-67","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"大家知道，在十六世纪，工人的状况十分恶化。货币工资提高了，但其提高的程度不及货币贬值和物价相应上涨的程度。因此，工资实际上是下降了。但是，旨在压低工资的法律仍然有效，同时，“没有人愿意使用”的人还要被割耳朵和打烙印。伊丽莎白五年颁布的第3号法令学徒法，授权治安法官规定一定的工资，并按季节和物价加以调整。詹姆斯一世把这种有关劳动的规定推行到纺织工人和其他各种工人身上。乔治二世把禁止工人结社的法律推行到一切工场手工业。","language":"中文","translation":false},{"id":"capital-25-68","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在真正的工场手工业时期，资本主义生产方式已经相当强大，因而用法律来规定工资已经行不通而且没有必要，但是人们为了防备万一，还不想抛弃旧武库中的这件武器。在乔治二世八年，除国丧期外，伦敦及其近郊的裁缝帮工的日工资还禁止超过2先令7 1/2便士；乔治三世十三年颁布的第68号法令还授权治安法官规定丝织工人的工资；在1796年，治安法官关于工资的命令是否也适用于非农业工人，还需要经过高等法院的两次判决来确定；在1799年，一项议会法令还规定，苏格兰矿工的工资要根据伊丽莎白的一项法令和1661年及1671年的两项苏格兰法令来规定。在此期间情况有了多大的变化，这可由英国下院的一件前所未闻的事情来说明。在这里，四百多年来人们都是制定法律来规定工资绝不能超过的最高限度，而在1796年，惠特布雷德建议用法律规定农业短工工资的最低限度。皮特表示反对，但承认“贫民的状况是悲惨的”。最后，在1813年，规定工资的法律被废除了。自从资本家以其私人立法来管理工厂，并依靠济贫税把农业工人的工资补充到必要的最低限度以来，这些法律就变成了可笑的反常的东西。但是劳工法中有关雇主和雇佣工人之间的契约以及解约期限等条款，直到现在还完全有效，这些条款规定，对违约的雇主只提出民事诉讼，而对违约的工人则提出刑事诉讼。","language":"中文","translation":false},{"id":"capital-25-69","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"残酷的禁止结社法于1825年在无产阶级的威胁性行动面前取消了。虽然如此，但取消的只是其中一部分。旧法令某些美丽的残片直到1859年才消失。最后，1871年6月29日的议会法令，在法律上承认工联时就认为消除了这项阶级立法的最后痕迹。但是，同一天颁布的一项议会法令，即关于惩治暴行、胁迫和侵害行为的刑法修正法令，实际上是以新的形式恢复了旧的状态。这种议会把戏，使工人在罢工或同盟歇业（结成同盟的工厂主同时把工厂关闭）时可能利用的手段都不按普通法来处理，而按特别刑法来处理，而这个刑法的解释权又操在担任治安法官的工厂主本人手中。两年前，同一个下院和同一个格莱斯顿先生，以人所共知的正直态度提出了一项取消一切反对工人阶级的特别刑法的法案。但是这个法案只二读了事，这样，问题就被搁置下来，直到后来，“伟大的自由党”同托利党结成联盟，竟然坚决反对扶它上台的无产阶级。“伟大的自由党”并不以这种背叛为满足，它还让一贯奴颜婢膝地为统治阶级效劳的英国法官把已经失效的禁止“秘密活动”法重新挖掘出来，用来对付工人的结社。我们看到，五百年来， 英国议会一直卑鄙无耻地自私自利地保持旨在反对工人的永久的资本家“工联”的地位，后来只是在群众的压力下才迫不得已地放弃了反对罢工和工联的法律。","language":"中文","translation":false},{"id":"capital-25-70","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"法国资产阶级在革命风暴一开始，就胆敢再把工人刚刚争得的结社权剥夺掉。它在1791年6月14日颁布法令，宣布工人的一切结社都是“对自由和人权宣言的侵犯”，要课以500利弗尔的罚金并剥夺公民权一年。这个法律用国家警察手段把资本和劳动之间的斗争限制在对资本有利的范围内，它经历了几次革命和几次改朝换代。甚至恐怖政府也没有触动它。直到最近它才被从刑法典中取消。采取这一资产阶级非常措施的借口是最典型不过的了。报告人列沙白里哀说：“工资比现在提高一些，使领工资的人摆脱由于缺乏必要的生活资料而陷入的绝对的、几乎是奴隶般的依赖状态，这虽然是应当的”，但是工人不应当彼此商定自己的利益，不应当采取共同行动来缓和自己的“绝对的、几乎是奴隶般的依赖状态”，因为他们这样做就会损害“他们从前的老板现在的企业主的自由”（使工人保持奴隶状态的自由！），因为进行结社来反对从前公会老板的专制，就是——猜猜看！——恢复法国宪法所取消的公会！","language":"中文","translation":false},{"id":"capital-25-71","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"4、资本主义租地农场主的产生","language":"中文","translation":false},{"id":"capital-25-72","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"我们考察了不受法律保护的无产者怎样通过暴力产生，考察了使他们转化为雇佣工人的血腥纪律，考察了君主和国家用警察手段加强对劳动的剥削程度来提高资本积累的无耻行为。现在要问：资本家最初是从哪里来的呢？因为对农村居民的剥夺只是直接地产生了大土地所有者。至于说到租地农场主的产生，我们是能够弄清楚的，因为这是一个延续了许多世纪的漫长过程。农奴本身，此外还有自由小土地所有者，处于极不相同的财产状况下，因而是在极不相同的经济条件下解放出来的。","language":"中文","translation":false},{"id":"capital-25-73","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在英国，最初形式的租地农场主是本身也是农奴的管事。他的地位和古罗马的斐力卡斯相似，不过活动范围狭小一些。在十四世纪下半叶，管事被由地主供给种籽、牲畜和农具的租地农民所代替。这种租地农民的地位同农民没有多大的区别，不过他剥削更多雇佣劳动。他不久就成为分成农，半租地农场主。他筹集农业资本的一部分，而其余部分则由地主提供。双方按合同规定的比例分配总产品。这种形式在英国很快就消失了，代之而起的是真正的租地农场主，他靠使用雇佣工人来增殖自己的资本，并把剩余产品的一部分以货币或实物的形式作为地租交给地主。","language":"中文","translation":false},{"id":"capital-25-74","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在十五世纪，当独立农民和那些既当雇工同时又独自耕作的雇农靠自己的劳动而富裕起来的时候，租地农场主的境况和生产范围都同样是中等的。十五世纪最后三十多年开始的、几乎在整个十六世纪（但最后几十年除外）继续进行的农业革命，以同一速度使农村居民破产，使租地农场主致富。对公有牧场等的掠夺，使租地农场主几乎不费代价就大大增加了自己的牲畜数量，这些牲畜又为他的土地的耕作提供了更丰富的肥料。","language":"中文","translation":false},{"id":"capital-25-75","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在十六世纪，又加进了一个有决定意义的重要因素。当时，租约的期限很长，往往达99年。贵金属价值从而货币价值的不断下降，给租地农场主带来了黄金果。把前面已经指出的其他一切情况撇开不说，这种下降也降低了工资。工资的一部分变成了租地农场主的利润。谷物、羊毛、肉类，总之，一切农产品的价格不断上涨，不费租地农场主一点力气，就增大了他的货币资本，而他必须支付的地租，却是按照以前的货币价值签订在契约上的。所以，他是同时靠牺牲自己的雇佣工人和地主的利益而致富的。因此，在十六世纪末，英国有了一个就当时情况来说已很富有的“资本主义租地农场主”阶级，是不足为奇的。","language":"中文","translation":false},{"id":"capital-25-76","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"5、农业革命对工业的反作用。工业资本的国内市场的形成","language":"中文","translation":false},{"id":"capital-25-77","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"我们已经知道，对农村居民断断续续的、一再重复的剥夺和驱逐，不断地为城市工业提供大批完全处于行会关系之外的无产者。这一奇妙的现象，使老亚·安德森（不要和詹姆斯·安德森相混）在他的商业史中也相信神的直接干预。我们还必须谈一谈原始积累的这个要素。若弗卢瓦·圣伊雷尔用世界物质在那里的稀薄化来解释它在这里的稠密化，但是，与独立的、自耕的农村居民稀薄化相适应的，不仅仅是工业无产阶级的稠密化。虽然种地的人数减少了，但土地提供的产品和过去一样多，或者比过去更多，因为伴随土地所有权关系革命而来的，是耕作方法的改进，协作的扩大，生产资料的积聚等等，因为农业雇佣工人不仅被迫加强了劳动强度，而且他们为自己进行劳动的生产范围也日益缩小了。因此，随着一部分农村居民的游离，他们以前的生活资料也被游离出来。这些生活资料现在变成可变资本的物质要素。被驱逐出来的农民必须从自己的新主人工业资本家那里，以工资的形式挣得这些生活资料的价值。国内农业提供的工业原料也同生活资料的情况一样。它变成了不变资本的一个要素。","language":"中文","translation":false},{"id":"capital-25-78","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"例如，可以设想，在弗里德里希二世时代全都纺亚麻的威斯特伐里亚农民，一部分遭到暴力剥夺，被逐出土地，另一部分留下来的则变成了大租地农场主的短工。与此同时，出现了大亚麻纺织厂，“被游离出来的人”受雇在那里做工。亚麻外表上和过去完全一样。它的纤维一根也没有发生变化，但是一个新的社会灵魂已经进入它的身体。它现在是手工工场主的不变资本的一部分。以前，亚麻分散在许多小生产者之间，他们自己种植亚麻，并和家人一道小量地进行纺织；现在，它积聚在一个资本家手中，他叫别人为自己纺织。消耗在纺亚麻上的额外劳动以前体现为无数农民家庭的额外收入，在弗里德里希二世时代，还体现为交给普鲁士国王的赋税。现在，它体现为少数资本家的利润。纱锭和织机以前分散在农村，现在和工人以及原料一样都集中在少数大劳动营里了。现在，纱锭、织机和原料由纺织工人独立生存的手段都变成了指挥他们和榨取他们的无酬劳动的手段。大手工工场同大租地农场一样，看不出是由许多小生产单位联合而成的，还是通过剥夺许多独立小生产者而成的。但是，不带偏见的考察是不会受迷惑的。在革命狮子米拉波的时代，人们还把大手工工场叫做联合手工工场，正如我们现在说联合耕地一样。米拉波说：","language":"中文","translation":false},{"id":"capital-25-79","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“人们只注意有几百人在一个厂长指挥下进行劳动的、通常叫做联合手工工场的大手工工场；而对人数众多的工人分散地独自经营的手工工场，几乎不屑一顾，把这些手工工场完全摆到次要的地位。这是一个很大的错误，因为只有它们才是国民财富的真正重要的组成部分…… 联合工场使一两个企业主大发其财，但工人不过是得到或多或少的报酬的短工，他们丝毫分享不到企业主得到的好处。相反地，在分散的工场中没有人发财致富，但许多工人过着优裕的生活…… 勤劳节俭的工人人数将会增加，因为他们将会认识到，正当的生活和劳动，是根本改善自己状况而不是稍许提高工资的手段；稍许提高工资对于将来决不可能是重要的事情，充其量只能使工人勉强糊口的生活稍微好一点。通常同小农经济结合在一起的单个分散的手工工场，才是自由的手工工场。”","language":"中文","translation":false},{"id":"capital-25-80","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"一部分农村居民的被剥夺和被驱逐，不仅为工业资本游离出工人及其生活资料和劳动材料，同时也建立了国内市场。","language":"中文","translation":false},{"id":"capital-25-81","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"事实上，使小农转化为雇佣工人，使他们的生活资料和劳动资料转化为资本的物质要素的那些事件，同时也为资本建立了自己的国内市场。以前，农民家庭生产并加工绝大部分供自己以后消费的生活资料和原料。现在，这些原料和生活资料都变成了商品；大租地农场主出售它们，手工工场则成了他的市场。纱、麻布、粗毛织品（过去每个农民家庭都有这些东西的原料，它把这些东西纺织出来供自己消费），现在变成了工场手工业的产品，农业地区正是这些东西的销售市场。以前由于大量小生产者独自经营而造成的分散各地的许多买主，现在集中为一个由工业资本供应的巨大市场。于是，随着以前的自耕农的被剥夺以及他们与自己的生产资料的分离，农村副业被消灭了，工场手工业与农业分离的过程发生了。只有消灭农村家庭手工业，才能使一个国家的国内市场获得资本主义生产方式所需要的范围和稳固性。","language":"中文","translation":false},{"id":"capital-25-82","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"但是，真正的工场手工业时期并没有引起根本的改变。我们记住，工场手工业只涉及国民生产的很小一部分，它一直以城市手工业和农村家庭副业作为广阔的背景。它在某种形式下，在某些工业部门，在某些地方消灭城市手工业和农村家庭副业，同时又在其他地方使它们重新出现，因为它需要它们把原料加工到一定的程度。因此，它产生了一个新的小农阶级，这些小农以种地为副业，而以工业劳动为主业，把产品直接或通过商人卖给手工工场。这就是首先使研究英国历史的人困惑不解的现象所以会产生的一个原因，虽然不是主要的原因。研究英国历史的人看到，从十五世纪最后三十多年起怨声不断（只是有时中止），抱怨资本主义经济在农村日益发展，农民日益被消灭，另一方面又看到，这些农民不断重新出现，虽然他们人数在减少，处境日益恶化。主要原因在于，英国在不同的时代，有时以谷物业为主，有时以畜牧业为主，因而农民的生产范围也跟着变化。只有大工业才用机器为资本主义农业提供了牢固的基础，彻底地剥夺了极大多数农村居民，使农业和农村家庭手工业完全分离，铲除了农村家庭手工业的根基——纺纱和织布。这样，它才为工业资本征服了整个国内市场。","language":"中文","translation":false},{"id":"capital-25-83","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"工业资本家不是象租地农场主那样逐渐地产生的。毫无疑问，有些小行会师傅和更多的独立小手工业者，甚至雇佣工人，变成了小资本家，并且由于逐渐扩大对雇佣劳动的剥削和相应的积累，成为不折不扣的资本家。在中世纪城市的幼年时期，逃跑的农奴中谁成为主人，谁成为仆人的问题，多半取决于他们逃出来的日期的先后，在资本主义生产的幼年时期，情形往往也是这样。但是这种方法的蜗牛爬行的进度，无论如何也不能适应十五世纪末各种大发现所造成的新的世界市场的贸易需求。而中世纪已经留下两种不同形式的资本，它们是在极不相同的社会经济形态中成熟的，而且在资本主义生产方式时期到来以前，就被当作资本了，这就是高利贷资本和商人资本。","language":"中文","translation":false},{"id":"capital-25-84","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“现在，社会的一切财富首先落入资本家手中……他对土地所有者支付地租，对工人支付工资，对赋税和什一税的征收者支付他们要求的东西，而留给自己的是年劳动产品的很大一部分，其实是最大的而且日益增长的一部分。现在，资本家可以看作是全部社会财富的最先所有者，虽然没有任何一项法律给予他这种所有权…… 所有权方面的这种变化是由于资本的取息而产生的……同样值得注意的是，整个欧洲的立法者都想用取缔高利贷的法律来阻止这件事…… 资本家支配国家的全部财富的权力是所有权上的一种彻底的革命；然而这个革命是靠哪一项法律或者哪一套法律来实行的呢？” 作者应该知道，革命不是靠法律来实行的。","language":"中文","translation":false},{"id":"capital-25-85","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"高利贷和商业所形成的货币资本在转化为工业资本时，曾受到农村封建制度和城市行会制度的阻碍。这些限制随着封建家臣的解散，农村居民的被剥夺和一部分被驱逐而消失。新的工场手工业建立在通海港口或不受旧城市及其行会制度控制的内陆地区。因此，在英国，享有公会特权的城市对这些新的工业培养所进行了激烈的斗争。","language":"中文","translation":false},{"id":"capital-25-86","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"美洲金银产地的发现，土著居民的被剿灭、被奴役和被埋葬于矿井，对东印度开始进行的征服和掠夺，非洲变成商业性地猎获黑人的场所：这一切标志着资本主义生产时代的曙光。这些田园诗式的过程是原始积累的主要因素。跟踵而来的是欧洲各国以地球为战场而进行的商业战争。这场战争以尼德兰脱离西班牙开始，在英国的反雅各宾战争中具有巨大的规模，并且在对中国的鸦片战争中继续进行下去，等等。","language":"中文","translation":false},{"id":"capital-25-87","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"原始积累的不同因素，多少是按时间顺序特别分配在西班牙、葡萄牙、荷兰、法国和英国。在英国，这些因素在十七世纪末系统地综合为殖民制度、国债制度、现代税收制度和保护关税制度。这些方法一部分是以最残酷的暴力为基础，例如殖民制度就是这样。但所有这些方法都利用国家权力，也就是利用集中的有组织的社会暴力，来大力促进从封建生产方式向资本主义生产方式的转变过程，缩短过渡时间。暴力是每一个孕育着新社会的旧社会的助产品。暴力本身就是一种经济力。","language":"中文","translation":false},{"id":"capital-25-88","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"关于基督教殖民制度，有一位把基督教当作专业来研究的人，威·豪伊特曾这样说过：","language":"中文","translation":false},{"id":"capital-25-89","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“所谓的基督教人种在世界各地对他们所能奴役的一切民族所采取的野蛮和残酷的暴行，是世界历史上任何时期，任何野蛮愚昧和残暴无耻的人种都无法比拟的。”","language":"中文","translation":false},{"id":"capital-25-90","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"荷兰——它是十七世纪标准的资本主义国家——经营殖民地的历史，“展示出一幅背信弃义、贿赂、残杀和卑鄙行为的绝妙图画”。最有代表性的是，荷兰人为了使爪哇岛得到奴隶而在苏拉威西岛实行盗人制度。为此目的训练了一批盗人的贼。盗贼、译员、贩卖人就是这种交易的主要代理人，土著王子是主要的贩卖人。盗来的青年在长大成人可以装上奴隶船以前，被关在苏拉威西的秘密监狱中。一份官方报告说：","language":"中文","translation":false},{"id":"capital-25-91","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“例如，孟加锡这个城市到处都是秘密监狱，一座比一座恐怖，里面挤满了不幸的人，贪欲和暴政的牺牲者，他们戴着镣铐，被迫和家人分离。”","language":"中文","translation":false},{"id":"capital-25-92","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"荷兰人为了霸占马六甲，曾向葡萄牙的总督行贿。1641年总督允许他们进城。他们为了“节省”支付21875镑贿款，立即到总督住宅把他杀了。他们走到哪里，那里就变得一片荒芜，人烟稀少。爪哇的班纽万吉省在1750年有8万多居民，而到1811年只有8000人了。这就是温和的商业！","language":"中文","translation":false},{"id":"capital-25-93","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"大家知道，英国东印度公司除了在东印度拥有政治统治权外，还拥有茶叶贸易、同中国的贸易和对欧洲往来的货运的垄断权。而印度的沿海航运和各岛屿之间的航运以及印度内地的贸易，却为公司的高级职员所垄断。对盐、鸦片、槟榔和其他商品的垄断权成了财富的取之不尽的矿藏。这些职员自定价格，任意勒索不幸的印度人。总督也参与这种私人买卖。他的宠信们是在使他们这些比炼金术士聪明的人们能从无中生出金来的条件下接受契约的。巨额财产象雨后春笋般地增长起来，原始积累在不预付一个先令的情况下进行。华伦·哈斯廷斯的审判记录中有很多这样的实例。举一个例子来说。有一个名叫沙利文的人，当他因公出差到印度一个离鸦片产地很远的地区时，接受了一项鸦片契约。沙利文以4万镑把契约卖给一个名叫宾恩的人，宾恩又在当天以6万镑转卖给别人，而这张契约的最后购买者和履行者声称，他从中还赚了一大笔钱。根据一个呈报议会的表报，从1757年到1766年，东印度公司和它的职员让印度人赠送了600万镑！在1769年到1770年间，英国人用囤积全部大米，不出骇人听闻的高价就拒不出售的办法制造了一次饥荒。","language":"中文","translation":false},{"id":"capital-25-94","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"在象西印度那样专营出口贸易的种植殖民地，以及在象墨西哥和东印度那样任人宰割的资源丰富人口稠密的国家里，土著居民所受的待遇当然是最可怕的。但是，即使在真正的殖民地，原始积累的基督教性质也是无可否认的。那些谨严的新教大师，新英格兰的清教徒，1703年在他们的立法会议上决定，每剥一张印第安人的头盖皮和每俘获一个红种人都给赏金40镑；1720年，每张头盖皮的赏金提高到100镑；1744年马萨诸塞湾的一个部落被宣布为叛匪以后，规定了这样的赏格：每剥一个12岁以上男子的头盖皮得新币100镑，每俘获一个男子得105镑，每俘获一个妇女或儿童得50镑，每剥一个妇女或儿童的头盖皮得50镑！数十年后，殖民制度对这些虔诚的新教徒们的背叛祖国的子孙进行了报复。在英国人的唆使和收买下，他们被人用短战斧砍死了。英国议会曾宣布，杀戮和剥头盖皮是“上帝和自然赋予它的手段”。","language":"中文","translation":false},{"id":"capital-25-95","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"殖民制度大大地促进了贸易和航运的发展。“垄断公司”（路德语）是资本积聚的强有力的手段。殖民地为迅速产生的工场手工业保证了销售市场，保证了通过对市场的垄断而加速的积累。在欧洲以外直接靠掠夺、奴役和杀人越货而夺得的财宝，源源流入宗主国，在这里转化为资本。第一个充分发展了殖民制度的荷兰，在1648年就已达到了它的商业繁荣的顶点。它","language":"中文","translation":false},{"id":"capital-25-96","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“几乎独占了东印度的贸易及欧洲西南部和东北部之间的商业往来。它的渔业、海运业和工场手工业，都胜过任何别的国家。这个共和国的资本也许比欧洲所有其他国家的资本总和还要多”。","language":"中文","translation":false},{"id":"capital-25-97","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"居利希忘记加上一句：荷兰的人民群众在1648年就已经比欧洲所有其他国家的人民群众更加劳动过度，更加贫困，更加遭受残酷的压迫。","language":"中文","translation":false},{"id":"capital-25-98","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"现在，工业上的霸权带来商业上的霸权。在真正的工场手工业时期，却是商业上的霸权造成了工业上的优势。所以殖民制度在当时起着决定性的作用。和欧洲各个旧神并列于祭坛上的“一位陌生的神”，有一天一下子把所有的旧神都打倒了。殖民制度宣布，赚钱是人类最终的和唯一的目的。","language":"中文","translation":false},{"id":"capital-25-99","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"公共信用制度，即国债制度，在中世纪的热那亚和威尼斯就已产生，到工场手工业时期流行于整个欧洲。殖民制度以及它的海外贸易和商业战争是公共信用制度的温室。所以它首先在荷兰确立起来。国债，即国家的让渡，不论是在专制国家，立宪国家，还是共和国家，总是给资本主义时代打下自己的烙印。在所谓国民财富中，真正为现代人民所共有的唯一部分，就是他们的国债。因此，一个国家的人民负债越多就越富这一现代理论是完全合乎逻辑的。 公共信用成了资本的信条。随着国债的产生，不可饶恕的罪恶，已不再是亵渎圣灵，而是破坏国债的信用了。","language":"中文","translation":false},{"id":"capital-25-100","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"公债成了原始积累的最强有力的手段之一。它象挥动魔杖一样，使不生产的货币具有了生殖力，这样就使它转化为资本，而又用不着承担投资于工业，甚至投资于高利贷时所不可避免的劳苦和风险。国家债权人实际上并没有付出什么，因为他们贷出的金额变成了容易转让的公债券，这些公债券在他们手里所起的作用和同量现金完全一样。于是就出现了这样产生的有闲的食利者阶级，充当政府和国民之间中介人的金融家就大发横财，每次国债的一大部分就成为从天而降的资本落入包税者、商人和私营工厂主的手中，——撇开这些不说，国债还使股份公司、各种有价证券的交易、证券投机，总之，使交易所投机和现代的银行统治兴盛起来。","language":"中文","translation":false},{"id":"capital-25-101","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"用国家的名义装饰起来的大银行，从一产生起就只不过是私人投机家的公司，它们支持政府，依靠取得的特权能够把货币贷给政府。因此，国债积累的最准确的尺度就是这些银行的股票的不断涨价，这些银行的充分发展是从英格兰银行的创立（1694年）开始的。英格兰银行开始营业的第一笔生意，就是以8％的利率贷款给政府；同时它由议会授权用同一资本铸造货币，这同一资本又以银行券的形式贷给公众。它可以用这些银行券来办理期票贴现、抵押货物、购买贵金属。这样，过了不久，这些由银行自己制造的信用货币又变成了铸币，英格兰银行用这些铸币贷款给国家并代国家支付公债利息。它一只手拿出去，另一只手拿更多的进来，这还不够；当它拿进来时，它仍然是国民的永远债权人，直到最后一个铜板付清为止。它逐渐成了国家的贵金属必然贮藏所和全部商业信用的重心。在英国，当人们禁止焚杀女巫的时候，却开始绞死伪造银行券者。至于银行巨头、金融家、食利者、经纪人、证券投机家和交易所的豺狼这一伙人的突然兴起，对同时代人曾产生怎样的影响，当时的著作如博林布罗克的著作可以证明。","language":"中文","translation":false},{"id":"capital-25-102","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"随着国债同时产生的，有国际信用制度。国际信用制度常常隐藏着这个或那个国家原始积累的源泉之一。例如，由于没落的威尼斯以巨额货币贷给荷兰，威尼斯的劫掠制度的卑鄙行径就成为荷兰资本财富的这种隐蔽的基础。荷兰和英国的关系也是这样。在十八世纪初，荷兰的工场手工业已经远远落后了，荷兰已不再是一个占统治地位的工商业国家。因此，荷兰在1701—1776年时期的主要营业之一就是贷放巨额资本，特别是贷给它的强大竞争者英国。现在英国和美国之间也发生了类似的情形。今天出现在美国的许多身世不明的资本，仅仅在昨天还是英国的资本化了的儿童血液。","language":"中文","translation":false},{"id":"capital-25-103","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"由于国债是依靠国家收入来支付年利息等等开支，所以现代税收制度就成为国债制度的必要补充。借债使政府可以抵补额外的开支，而纳税人又不会立即感到负担，但借债最终还是要求提高税收。另一方面，由于债务的不断增加而引起的增税，又使政府在遇到新的额外开支时，总是要借新债。因此，以对最必要的生活资料的课税（因而也是以它们的昂贵）为轴心的现代财政制度，本身就包含着税收自行增加的萌芽。过重的课税并不是一件偶然的事情，倒不如说是一个原则。因此，在首先建立这种制度的荷兰，大爱国者德·维特在他的箴言中对这种制度备加赞扬，把它说成是促使雇佣工人服从、俭朴、勤勉和……从事过度劳动的最好制度。但这里，我们所关心的，与其说是这种制度对雇佣工人状况的破坏性影响，不如说是它所引起的对农民、手工业者，一句话，对一切下层中产阶级分子的暴力剥夺。关于这一点，甚至在资产阶级经济学家中间也没有异议。现代财政制度的剥夺作用，被这一制度的一个组成部分即保护关税制度加强了。","language":"中文","translation":false},{"id":"capital-25-104","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"公债和与之相适应的财政制度在财富的资本化和对群众的剥夺中所起的重大作用，使科贝特、达布耳德等许多著作家错误地要在公债和财政制度中寻找现代人民贫困的根本原因。","language":"中文","translation":false},{"id":"capital-25-105","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"保护关税制度是制造工厂主、剥夺独立劳动者、使国民的生产资料和生活资料变成资本、强行缩短从旧生产方式向现代生产方式的过渡的一种人为手段。欧洲各国为了获得这种发明的专利权而勾心斗角，它们一旦成为谋利者的奴仆，就不仅要为此目的而间接通过保护关税和直接通过出口补助金等来掠夺本国人民，而且还要强制地摧毁其附属邻国的一切工业，例如英格兰摧毁了爱尔兰的毛纺织工场手工业。在欧洲大陆上，柯尔培尔开了先例以后，这个过程更是大大地简化了。在那里，工业家的原始资本有一部分直接来自国库。米拉波喊道：","language":"中文","translation":false},{"id":"capital-25-106","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“为什么要追溯到那么远去寻找七年战争以前萨克森工场手工业繁荣的原因呢？只要看看18000万国债就够了！”","language":"中文","translation":false},{"id":"capital-25-107","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"殖民制度、国债、重税、保护关税制度、商业战争等等——所有这些真正工场手工业时期的嫩芽，在大工业的幼年时期都大大地成长起来了。大工业是以希罗德王式的大规模掠夺儿童来庆贺自己的诞生的。象皇家海军强征水兵一样，工厂也是用强力招收工人的。尽管弗·摩·伊登爵士对于从十五世纪最后三十多年到他所处时代即十八世纪末这一段时间里，由于剥夺农村居民的土地而造成的惨象，处之泰然，尽管他对于为建立资本主义农业以及“确定耕地和牧场的合理比例”所“必需的”这一过程，满意地表示庆幸，然而他对于为了使工场手工业生产转变为工厂生产以及确定资本和劳动力的合理比例而必需掠夺和奴役儿童这一点，却没有表现出同样的经济学上的洞察力。他说：","language":"中文","translation":false},{"id":"capital-25-108","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“公众也许有必要考虑一下这个问题：如果一种工场手工业只有掠夺小屋和贫民习艺所中的贫苦儿童，并让他们成群结队地轮班劳动大半夜而得不到休息，才能顺利地经营下去，如果这种工场手工业把不同年龄和不同爱好的男女混杂在一起，以致通过实例的传染必然造成道德败坏，荒淫放荡，——这样一种工场手工业难道能够增加国家和个人的幸福的总和吗？”","language":"中文","translation":false},{"id":"capital-25-109","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"“在得比郡、诺定昂郡，尤其在郎卡郡，沿着能够推动水车的河流修建的大工厂，采用了最新发明的机器。这些远离城市的地方，突然需要成千上万的人手；其中以当时人口较少、土地贫瘠的郎卡郡最需要人。特别需要手指细小而灵巧的儿童。于是，从伦敦、北明翰等地的教区贫民习艺所招收学徒<！>之风盛行一时。成千上万这种从7岁到13、14岁的无依无靠的儿童，就这样被运到北方去。通常，主人<即掠夺儿童的人>要供给自己的学徒衣食，让他们住在工厂附近的徒工房里。派来监工监督他们的劳动。这些监工的工资和从儿童身上榨取的产品量成正比，因此他们的兴趣是让儿童尽量多干活。结果必然是残酷虐待…… 在许多工厂区，尤其是在郎卡郡，这些任凭工厂主支配的无依无靠的无辜儿童，遭到了最悲惨的折磨。他们被过度的劳动折磨至死……他们被鞭打，戴上镣铐，受尽挖空心思的残酷虐待；他们大多饿得骨瘦如柴，但还得在皮鞭下干活…… 他们有时甚至被逼得自杀！…… 得比郡、诺定昂郡和郎卡郡的那些与世隔绝的美丽而浪漫的山谷，竟成为折磨人，甚至常常虐杀人的恐怖地方！…… 工厂主的利润是巨大的。但这只能燃起他们狼一般的贪欲。他们开始实行夜间劳动，就是说，在做日工的一批人精疲力尽之后，他们已经准备好另一批人去做夜工；夜班工人刚下床，日班工人就躺上去，然后再反过来。郎卡郡流行一句俗语：床永不凉。”","language":"中文","translation":false},{"id":"capital-25-110","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"随着资本主义生产在工场手工业时期的发展，欧洲的舆论丢掉了最后一点羞耻心和良心。各国恬不知耻地夸耀一切当作资本积累手段的卑鄙行径。 例如，读一读老实人亚·安德森的天真的商业编年史。这本编年史把下面的事实当作英国国策的巨大胜利而备加赞扬：英国在乌得勒支和谈时通过阿西恩托条约，从西班牙人手里夺走了经营非洲和西属美洲之间贩卖黑人的特权，而在此以前，英国只经营非洲和英属西印度之间的这种买卖。英国 获得了到1743年为止每年供给西属美洲4800个黑人的权利。这同时又为英国的走私提供了公开的掩护。利物浦是靠奴隶贸易发展起来的。奴隶贸易是它进行原始积累的方法。直到目前为止，利物浦“受尊敬的人”仍然是赞扬奴隶贸易的品得；奴隶贸易——参看前面所引1795年出版的艾金医生的著作——“使商业冒险精神达到了狂热，产生了出色的海员，带来了巨额的金钱”。利物浦用于奴隶贸易的船只，1730年15艘，1751年53艘，1760年74艘，1770年96艘，1792年132艘。","language":"中文","translation":false},{"id":"capital-25-111","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"当棉纺织工业在英国引起儿童奴隶制的时候，它同时在美国促使过去多少带有家长制性质的奴隶经济转变为商业性的剥削制度。总之，欧洲的隐蔽的雇佣工人奴隶制，需要以新大陆的赤裸裸的奴隶制作为基础。","language":"中文","translation":false},{"id":"capital-25-112","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"要使资本主义生产方式的“永恒的自然规律”充分表现出来，要完成劳动者同劳动条件的分离过程，要在一极使社会的生产资料和生活资料转化为资本，在另一极使人民群众转化为雇佣工人，转化为自由的“劳动贫民”这一现代历史的杰作，就需要经受 这种苦难。如果按照奥日埃的说法，货币“来到世间，在一边脸上带着天生的血斑”，那末，资本来到世间，从头到脚，每个毛孔都滴着血和肮脏的东西。","language":"中文","translation":false},{"id":"capital-25-113","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"7、资本主义积累的历史趋势","language":"中文","translation":false},{"id":"capital-25-114","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"资本的原始积累，即资本的历史起源，究竟是指什么呢？既然它不是奴隶和农奴直接转化为雇佣工人，因而不是单纯的形式变换，那末它就只是意味着直接生产者的被剥夺，即以自己劳动为基础的私有制的解体。","language":"中文","translation":false},{"id":"capital-25-115","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"私有制作为公共的、集体的所有制的对立物，只是在劳动资料和劳动的外部条件属于私人的地方才存在。但是私有制的性质，却依这些私人是劳动者还是非劳动者而有所不同。私有制在最初看来所表现出的无数色层，只不过反映了这两极间的各种中间状态。","language":"中文","translation":false},{"id":"capital-25-116","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"劳动者对他的生产资料的私有权是小生产的基础，而小生产又是发展社会生产和劳动者本人的自由个性的必要条件。诚然，这种生产方式在奴隶制度、农奴制度以及其他从属关系中也是存在的。但是，只有在劳动者是自己使用的劳动条件的自由私有者，农民是自己耕种的土地的自由私有者，手工业者是自己运用自如的工具的自由私有者的地方，它才得到充分发展，才显示出它的全部力量，才获得适当的典型的形式。","language":"中文","translation":false},{"id":"capital-25-117","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"这种生产方式是以土地及其他生产资料的分散为前提的。它既排斥生产资料的积聚，也排斥协作，排斥同一生产过程内部的分工，排斥社会对自然的统治和支配，排斥社会生产力的自由发展。它只同生产和社会的狭隘的自然产生的界限相容。要使它永远存在下去，那就象贝魁尔公正地指出的那样，等于“下令实行普遍的中庸”。 它发展到一定的程度，就造成了消灭它自身的物质手段。从这时起，社会内部感到受它束缚的力量和激情，就活动起来。这种生产方式必然要被消灭，而且已经在消灭。它的消灭，个人的分散的生产资料转化为社会的积聚的生产资料，从而多数人的小财产转化为少数人的大财产，广大人民群众被剥夺土地、生活资料、劳动工具，——人民群众遭受的这种可怕的残酷的剥夺，形成资本的前史。这种剥夺包含一系列的暴力方法，其中我们只考察了那些具有划时代意义的资本原始积累的方法。对直接生产者的剥夺，是用最残酷无情的野蛮手段，在最下流、最龌龊、最卑鄙和最可恶的贪欲的驱使下完成的。靠自己劳动挣得的私有制，即以 各个独立劳动者与其劳动条件相结合为基础的私有制，被资本主义私有制，即以剥削他人的但形式上是自由的劳动为基础的私有制所排挤。","language":"中文","translation":false},{"id":"capital-25-118","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"一旦这一转化过程使旧社会在深度和广度上充分瓦解，一旦劳动者转化为无产者，他们的劳动条件转化为资本，一旦资本主义生产方式站稳脚跟，劳动的进一步社会化，土地和其他生产资料的进一步转化为社会使用的即公共的生产资料，从而对私有者的进一步剥夺，就会采取新的形式。现在要剥夺的已经不再是独立经营的劳动者，而是剥削许多工人的资本家了。","language":"中文","translation":false},{"id":"capital-25-119","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"这种剥夺是通过资本主义生产本身的内在规律的作用，即通过资本的集中进行的。一个资本家打倒许多资本家。随着这种集中或少数资本家对多数资本家的剥夺，规模不断扩大的劳动过程的协作形式日益发展，科学日益被自觉地应用于技术方面，土地日益被有计划地利用，劳动资料日益转化为只能共同使用的劳动资料，一切生产资料因作为结合的社会劳动的生产资料使用而日益节省，各国人民日益被卷入世界市场网，从而资本主义制度日益具有国际的性质。随着那些掠夺和垄断这一转化过程的全部利益的资本巨头不断减少，贫困、压迫、奴役、退化和剥削的程度不断加深，而日益壮大的、由资本主义生产过程本身的机构所训练、联合和组织起来的工人阶级的反抗也不断增长。资本的垄断成了与这种垄断一起并在这种垄断之下繁盛起来的生产方式的桎梏。生产资料的集中和劳动的社会化，达到了同它们的资本主义外壳不能相容的地步。这个外壳就要炸毁了。资本主义私有制的丧钟就要 响了。 剥夺者就要被剥夺了。","language":"中文","translation":false},{"id":"capital-25-120","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"从资本主义生产方式产生的资本主义占有方式，从而资本主义的私有制，是对个人的、以自己劳动为基础的私有制的第一个否定。但资本主义生产由于自然过程的必然性，造成了对自身的否定。这是否定的否定。这种否定不是重新建立私有制，而是在资本主义时代的成就的基础上，也就是说，在协作和对土地及靠劳动本身生产的生产资料的共同占有的基础上，重新建立个人所有制。","language":"中文","translation":false},{"id":"capital-25-121","author":"马克思","title":"资本论·第一卷","location":"第二十四章 所谓原始积累","page":25,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/capital/24.htm","text":"以个人自己劳动为基础的分散的私有制转化为资本主义私有制，同事实上已经以社会生产为基础的资本主义所有制转化为公有制比较起来，自然是一个长久得多、艰苦得多、困难得多的过程。前者是少数掠夺者剥夺人民群众，后者是人民群众剥夺少数掠夺者。","language":"中文","translation":false},{"id":"capital-26-1","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"中文马克思主义文库 -> 马克思 -> 《资本论》第一卷：资本的生产过程(1867)","language":"中文","translation":false},{"id":"capital-26-2","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"第二十五章 现代殖民理论","language":"中文","translation":false},{"id":"capital-26-3","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"〔注：这里说的是真正的殖民地，即自由移民所开拓的处女地。从经济上来说，美国仍然是欧洲的殖民地。此外，这里还包括那些由于消灭了奴隶制而完全改变了关系的旧种植殖民地在内。〕","language":"中文","translation":false},{"id":"capital-26-4","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"政治经济学在原则上把两种极不相同的私有制混同起来了。其中一种是以生产者自己的劳动为基础，另一种是以剥削别人的劳动为基础。它忘记了，后者不仅与前者直接对立，而且只是在前者的坟墓上成长起来的。","language":"中文","translation":false},{"id":"capital-26-5","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"在西欧，政治经济学的故乡，原始积累的过程多少已经完成。在这里，资本主义制度或者已经直接征服整个国民生产，或者在这种关系还不很发达的地方，它也至少间接地控制着那些与它并存的、属于旧生产方式的、腐朽的社会阶层。事实越是明显地反对政治经济学家的意识形态，政治经济学家就越是热心地起劲地把资本主义以前世界的法权观念和所有权观念应用到这个已经完成的资本世界。","language":"中文","translation":false},{"id":"capital-26-6","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"殖民地的情况却不是这样。在那里，资本主义制度到处都碰到这样一种生产者的阻碍，这种生产者是自己劳动条件的所有者，靠自己的劳动使自己变富，而不是使资本家变富。在那里，这两种完全对立的经济制度之间的矛盾，在它们的斗争中实际地得到证 实。在资本家有宗主国的力量作后盾的地方，资本家就企图用暴力清除以自己的劳动为基础的生产方式和占有方式。同样的利益，在宗主国使资本的献媚者政治经济学家从理论上把资本主义生产方式和它本身的对立面说成是同一的，在殖民地却使他“公开揭露事实”，大声宣布这两种生产方式是对立的。为了这个目的，他证明，不剥夺劳动者，不相应地把他们的生产资料转化为资本，劳动的社会生产力的发展，协作、分工以及机器的大规模使用等等，都是不可能的。为了所谓国民财富的利益，他要寻找那些制造人民贫困的人为的手段。在这里，他的辩护的甲胄就象松软的火绒一样裂成一片一片的了。","language":"中文","translation":false},{"id":"capital-26-7","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"爱·吉·威克菲尔德的巨大功绩，并不是他关于殖民地有什么新发现，而是他在殖民地发现了关于宗主国的资本主义关系的真理。正如保护关税制度起初力图在宗主国制造出资本家一样，英国一度试图用立法手段来推行的威克菲尔德的殖民理论，力图在殖民地制造出雇佣工人。威克菲尔德把这称为《系统的殖民》。","language":"中文","translation":false},{"id":"capital-26-8","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"首先，威克菲尔德在殖民地发现，拥有货币、生活资料、机器以及其他生产资料，而没有雇佣工人这个补充物，没有被迫自愿出卖自己的人，还不能使一个人成为资本家。 他发现，资本不是一种物，而是一种以物为媒介的人和人之间的社会关系。他向我们 感慨地说，皮尔先生把共值5万镑的生活资料和生产资料从英国带到澳洲的斯旺河去。皮尔先生非常有远见，他除此以外还带去了工人阶级的3000名男工、女工和童工。可是，一到达目的地，“皮尔先生竟连一个替他铺床或到河边打水的仆人也没有了”。不幸的皮尔先生，他什么都预见到了，就是忘了把英国的生产关系输出到斯旺河去！","language":"中文","translation":false},{"id":"capital-26-9","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"为了理解威克菲尔德下述的发现，要作两点说明。我们知道，生产资料和生活资料，作为直接生产者的财产，不是资本。它们只有在同时还充当剥削和统治工人的手段的条件下，才成为资本。但是，在政治经济学家的头脑中，它们的这个资本主义灵魂和它们的物质实体非常紧密地结合在一起，以致在任何情况下，甚至当它们正好是资本的对立面的时候，他也把它们称为资本。威克菲尔德就是这样。 其次，他把生产资料为许多互不依赖而独立经营的劳动者个人所有这种分散的现象，称为资本的均分。政治经济学家的做法和封建法学家一样，后者在纯粹的货币关系上，也贴上自己封建法律的标签。","language":"中文","translation":false},{"id":"capital-26-10","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“如果把资本以相等的份额分给社会的所有成员，那就没有人想要积累多于他能亲手使用的资本了。美洲新殖民地的情况，在某种程度上就是这样。在那里，对土地所有权的热望妨碍了雇佣工人阶级的存在。”","language":"中文","translation":false},{"id":"capital-26-11","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"因此，只要劳动者是自己的生产资料的所有者，他就能为自己积累；只要他能为自己积累，资本主义积累和资本主义生产方式就是不可能的。为此所必需的雇佣工人阶级还没有。 那末，旧欧洲劳动者的劳动条件是怎样被剥夺，从而资本和雇佣劳动是怎样产生的呢？靠一种原始的社会契约。","language":"中文","translation":false},{"id":"capital-26-12","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“人类……采用了一种促进资本积累的简单方法”，自然，这种积累从亚当时代起就被人类当作自己生存的最终的和唯一的目的；“人类把自己分为资本所有者和劳动所有者……这种分法是自愿协商和结合的结果”。","language":"中文","translation":false},{"id":"capital-26-13","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"一句话，人类的大多数为了“积累资本”而自己剥夺了自己。这样，我们就应当相信，这种克己的狂热本能必定会特别在殖民地最充分地表现出去，因为只有在那里才存在着能够把一种社会契约从梦想变为现实的人和条件。但是，为什么又要提倡与自然的殖民相对立的“系统的殖民”呢？但是，但是：","language":"中文","translation":false},{"id":"capital-26-14","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“在美国北部各州，是否有十分之一的人口属于雇佣工人的范畴，是值得怀疑的…… 在英国……大部分人民群众是雇佣工人。”","language":"中文","translation":false},{"id":"capital-26-15","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"的确，劳动人口很少有为资本而自我剥夺的欲望，连威克菲尔德也认为，奴隶制是殖民地财富唯一的自然基础。他的系统的殖民只是一种应急手段，因为他要对付的是自由民，而不是奴隶。","language":"中文","translation":false},{"id":"capital-26-16","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“到圣多明哥的第一批西班牙移民，没有从西班牙得到一个工人。但是没有工人〈即没有奴隶制〉，资本就会死亡，至少也会缩小到每个人都可以亲手使用的微小数额。实际上，上述那个由英国人建立的殖民地的情况就是这 样。在那里，大量资本即种子、牲畜和工具，由于缺乏雇佣工人而毁掉了，同时每个移民所拥有的资本并不比他能亲手使用的资本多多少。”","language":"中文","translation":false},{"id":"capital-26-17","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"我们已经知道，剥夺人民群众的土地是资本主义生产方式的基础。与此相反，自由殖民地的本质在于，大量土地仍然是人民的财产，因此每个移民都能够把一部分土地变为自己的私有财产和个人的生产资料，而又不妨碍后来的移民这样做。这就是殖民地繁荣的秘密，同时也是殖民地的痼疾——反抗资本迁入——的秘密。","language":"中文","translation":false},{"id":"capital-26-18","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“在土地十分便宜，所有的人都自由，每个人能随意得到一块土地的地方，不仅劳动十分昂贵，劳动者会在自己的产品中占去很大的份额，而且不论出什么价格都很难得到结合劳动。”","language":"中文","translation":false},{"id":"capital-26-19","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"因为殖民地的劳动者还没有和劳动条件以及他们的根基即土地分离，或者这种分离只是间或地或在极有限的范围内存在，所以，农业还没有和工业分离，农村家庭工业也还没有消灭。在那里，资本的国内市场又从何而来呢？","language":"中文","translation":false},{"id":"capital-26-20","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“在美洲，除了奴隶和他们的主人，即那些把资本和劳动结合起来经营大企业的人，没有一部分专门从事农业的人口。自由的美洲人自己耕种土地，同时还从事其他许多职业。他们使用的一部分家具和工具，通常是他们自己制造的。他们往往自己建造房屋，并把自己的工业制品送到遥远的市场去。他们是纺纱者和织布者，他们制造自己消费的肥皂、蜡烛、鞋和衣服。在美洲，种地往往是铁匠、磨面匠或小商人的副业。” 在这些古怪的人当中，哪里还有资本家“禁欲的场所”呢？","language":"中文","translation":false},{"id":"capital-26-21","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"资本主义生产最美妙的地方，就在于它不仅不断地再生产出雇佣工人本身，而且总是与资本积累相适应地生产出雇佣工人的相对过剩人口。这样，劳动的供求规律就保持在正常的轨道上，工资的变动就限制在资本主义剥削所容许的范围内，最后，工人对资本家必不可少的社会从属性即绝对的从属关系得到了保证。政治经济学家在本国，即在宗主国，可以花言巧语地把这种绝对的从属关系描绘成买者和卖者之间的自由契约关系，描绘成同样独立的商品所有者即资本商品所有者和劳动商品所有者之间的自由契约关系。但是在殖民地，这个美丽的幻想破灭了。到这里来的许多工人都是成年人，因此这里绝对人口增长得比宗主国快得多，但是劳动市场却总是供给不足。劳动的供求规律遭到了破坏。一方面，旧大陆不断地把渴望剥削和要求禁欲的资本投进来，另一方面，雇佣工人本身有规则的再生产，遇到了非常顽强的、部分是不可克服的障碍。哪里还能与资本积累相适应地生产出过剩的雇佣工人来呢！今天的雇佣工人，明天就会成为独立经营的农民或手工业者。他从劳动市场上消失，但并不是到贫民习艺所去了。雇佣工人不断地转化为独立生产者，他们不是为资本劳动，而是为自己劳动，不是使资本家老爷变富，而是使自己变富； 这种转化又反过来对劳动市场的状况产生极有害的影响。不仅雇佣工人受剥削的程度低得不象样子；而且，雇佣工人在丧失对禁欲资本家的从属关系时，也丧失了对他的从属感情。我们的爱·吉·威克菲尔德那样勇敢，那样雄辩，那样感人地描述的种种弊病，就是由此而来的。","language":"中文","translation":false},{"id":"capital-26-22","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"他埋怨说，雇佣劳动的供给不经常，不规则，不充足，“不仅总是过少，而且没有保证”。","language":"中文","translation":false},{"id":"capital-26-23","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“虽然在工人和资本家之间分配的产品很多，但是工人取得的部分非常大，以致他很快就成了资本家…… 即使寿命很长的人，也只有少数人能够积累大量的财富。”","language":"中文","translation":false},{"id":"capital-26-24","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"工人绝不允许资本家实行禁欲而不支付工人最大部分的劳动。即使资本家十分狡猾，把自己的雇佣工人连同自己的资本一起从欧洲输入，那也无济于事。","language":"中文","translation":false},{"id":"capital-26-25","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“他们很快就不再是雇佣工人，他们很快就变成独立的农民，甚至在雇佣劳动市场上变成自己原来主人的竞争者。”","language":"中文","translation":false},{"id":"capital-26-26","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"这是多么可怕的事情！精明能干的资本家竟用自己宝贵的金钱从欧洲输入了自己的竞争者！一切都完蛋了！无怪乎威克菲尔德埋怨殖民地的雇佣工人缺乏从属关系和从属感情。他的门徒梅里威耳说，由于殖民地的工资高昂，所以在那里渴望有一种较便宜较驯服的劳动，有一个接受资本家的条件，而不是向资本家提出条件的阶级…… 在旧的文明国家，工人虽然自由，但按照自然规律，他是从属于资本家的；在殖民地，这种从属关系必须用人为的手段建立起来。","language":"中文","translation":false},{"id":"capital-26-27","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"照威克菲尔德看来，殖民地的这种弊病的后果是什么呢？就是使生产者和国民财产“分散的野蛮制度”。生产资料分散在无数独立经营的所有者之间，这就既破坏了资本集中，也破坏了结合劳动的一切基础。一切要历经多年并需要投入固定资本的长期性的企业，在经营中都会遇到障碍。在欧洲，资本不会有片刻迟疑，因为工人阶级是它的活的附属物，总是过剩的，总是处于供它使用的状态。可是在殖民地国家呢！威克菲尔德讲了一个非常令人痛心的奇闻逸事。他曾经同加拿大和纽约州的某些资本家谈过话，应当指出的是，这些地方移民浪潮经常停滞下来并且沉淀下“过剩”工人。传奇剧中的一个人物叹惜说：","language":"中文","translation":false},{"id":"capital-26-28","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“我们的资本打算从事许多需要很长时期才能完成的工作，可是我们能用我们明知很快就会离开我们的工人来开始这些工作吗？只要我们能确实掌握这些移民的劳动，我们乐意立即用高价雇用他们。确实，只要我们有保证能根据我们的需要得到新的供给，即使他们肯定要离开，我们还是要雇用他们。”","language":"中文","translation":false},{"id":"capital-26-29","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"在威克菲尔德把英国的资本主义农业及其“结合”劳动，同美洲分散的农民经济作了绝妙的对比之后，事情的反面就露出来了。 他把美洲的人民群众描绘成富裕、独立、有事业心和比较有教养的人，而","language":"中文","translation":false},{"id":"capital-26-30","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“英国的农业工人是悲惨的穷人，需要救济的贫民…… 除了北美和某些新殖民地以外，还有什么地方，农业上使用的自由劳动的工资是大大超过工人最必需的生存资料的呢？…… 毫无疑问，英国的耕马由于是一种贵重财产，所以吃得比英国的农民好得多”。","language":"中文","translation":false},{"id":"capital-26-31","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"不过没有关系，国民财富和人民贫困本来就是一回事。","language":"中文","translation":false},{"id":"capital-26-32","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"究竟应该怎样治疗殖民地的反资本主义的痼疾呢？如果一下子把全部土地由人民财产变为私有财产，这固然会消除祸根，但同时也会消除殖民地。必须有一举两得的妙计。政府应当对处女地规定出一种不以供求规律为转移的价格，即人为的价格，迫使移民在赚到足够的钱购买土地，成为独立农民以前，必须从事较长时期的雇佣劳动。另一方面，政府应当用那个因土地按雇佣工人较难支付的价格出售得来的基金，即靠违背神圣的供求规律而从工资中榨取来的货币基金，并依据这个基金增长的程度，从欧洲把穷人输入到殖民地来，为资本家老爷充实雇佣劳动市场。在这种情况下，就会“在这个最美好的世界上，一切都十全十美”。这就是“系统的殖民”的最大秘密。威克菲尔德洋洋得意地喊道：","language":"中文","translation":false},{"id":"capital-26-33","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"“按照这个计划，劳动的供给必然是不断的和有规则的；因为，第一，任何一个工人在没有靠劳动挣到钱以前，都不能获得土地，因此，所有移入的工人都得为了挣工资而结合起来进行劳动，这就将为他们的主人生产出可以使用更多劳动的资本来；第二，每个放弃雇佣劳动并成为土地所有者的人，正好由于购买土地而提供一个能把新劳动输入到殖民地来的基金。”","language":"中文","translation":false},{"id":"capital-26-34","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"国家强行规定的土地价格，当然必须是“充分的价格”，也就是说，必须高到“使工人在雇佣劳动市场上被另一个人取代以前不可能变成独立的农民”。这种“充分的土地价格”，无非是工人为了能从雇佣劳动市场回到土地上而付给资本家的赎金的一种婉转的说法。他先是必须为资本家老爷创造“资本”，使资本家老爷能够剥削更多的工人，然后又必须牺牲自己，使政府能为他原来的资本家老爷从海外把他的“替身”送到劳动市场上来。","language":"中文","translation":false},{"id":"capital-26-35","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"最能说明问题的是，威克菲尔德先生制定的这个专门用于殖民地的“原始积累”方法，英国政府采用了好些年。当然，它遭到了和皮尔银行法同样可耻的失败。结果只是使移民潮流从英国殖民地转向美国。同时，欧洲资本主义生产的进步，以及随之而来的政府压迫的加重，使威克菲尔德的方案成为多余。一方面，逐年涌向美洲的巨大的不断的人流，在美国东部停滞并沉淀下来，因为从欧洲来的移民浪潮迅速地把人们抛到东部的劳动市场上，而向西部去的移民浪潮来不及把人们冲走。另一方面，美国南北战争的结果造成了巨额的国债以及随之而来的沉重的赋税，产生了最卑鄙的金融贵族，使极大一部分公有土地被滥送给经营铁路、矿山等的投机家公司，——一句话，造成了最迅速的资本集中。因此，这个大共和国已经不再是迁移来的工人的天堂了。在那里，资本主义生产正在飞速向前发展，虽然工资的下降和雇佣工人的从属关系还远没有降到欧洲的标准水平。被威克菲尔德本人大声责难的、由英国政府无耻地把殖民地未开垦的土地滥送给贵族和资本家的做法，加上金矿吸引来的人流，以及英国商品的输入所引起的对最小的手工业者的竞争，——这一切，特别在澳洲，产生了一个充分的“相对过剩的工人人口”，以致几乎每班邮船都带来澳洲劳动市场过剩的凶讯。在那里，有些地方的卖淫现象和在伦敦草市一样盛行。","language":"中文","translation":false},{"id":"capital-26-36","author":"马克思","title":"资本论·第一卷","location":"第二十五章 现代殖民理论","page":26,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/capital/25.htm","text":"但是，我们在这里并不是要研究殖民地的状况。我们感兴趣的只是旧大陆的政治经济学在新大陆发现并大声宣布的秘密：资本主义的生产方式和积累方式，从而资本主义的私有制，是以那种以自己的劳动为基础的私有制的消灭为前提的，也就是说，是以劳动者的被剥夺为前提的。","language":"中文","translation":false},{"id":"wage-labour-1-1","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"中文马克思主义文库 -> 马克思","language":"中文","translation":false},{"id":"wage-labour-1-2","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"雇佣劳动与资本[298]","language":"中文","translation":false},{"id":"wage-labour-1-3","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"科伦4月4日［注：“雇佣劳动与资本”的某些版本中（包括1891年版在内）去掉了每篇文章开首的日期。——编者注］。我们听到了各方面的责难，说我们没有详述构成现代阶级斗争和民族斗争的物质基础的经济关系。我们只是当这些关系在政治冲突中直接表现出来的时候，才有意地讲到过这些关系。","language":"中文","translation":false},{"id":"wage-labour-1-4","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"过去首先必须从日常历史进程中去考察阶级斗争，并根据已有的和每天新出现的历史材料来从经验上证明：当实现了二月革命和三月革命的工人阶级遭到失败的时候，它的敌人（在法国是资产阶级共和派，在整个欧洲大陆则是反对过封建专制制度的资产阶级和农民阶级）也同时被战胜了；法国“正直的共和国”的胜利，同时也就是以争取独立的英勇战争响应了二月革命的那些民族的失败；最后，随着革命工人的失败，欧洲又落到了过去那种受双重奴役即受英俄两国奴役的地位。巴黎的六月斗争，维也纳的陷落，柏林十一月［注：在1891年的版本中，“柏林十一月”前面加有“1848年”等字。——编者注］的悲喜剧，波兰、意大利和匈牙利的拚命努力，爱尔兰的严重饥荒——这些就是那些集中表现了欧洲资产阶级和工人阶级之间的阶级斗争的主要事件。我们曾经根据这些实例证明过：任何一次革命起义，不论它的目的仿佛距离阶级斗争多么远，在革命的工人阶级没有获得胜利以前，都是不免要失败的；任何一种社会改革，在无产阶级革命和封建反革命没有在世界战争中较量一下以前，都是要成为空想的。在我们的阐述中，也如在现实中一样，比利时和瑞士都是大历史画中的两幅悲喜剧式的、漫画式的世俗画：前者是资产阶级君主制的典型国家，后者是资产阶级共和制的典型国家，两者都自以为既跟阶级斗争无关，又跟欧洲革命无关。","language":"中文","translation":false},{"id":"wage-labour-1-5","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"现在，在我们的读者看到了1848年以波澜壮阔的政治形式展开的阶级斗争以后，我们想更切近地考察一下资产阶级的生存及其阶级统治和工人的奴役地位所依为基础的经济关系本身，也就适当其时了。","language":"中文","translation":false},{"id":"wage-labour-1-6","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们分三大部分来加以说明：（1）雇佣劳动对资本的关系，工人的奴役地位，资本家的统治；（2）中等资产阶级和农民等级［注：在1891年的版本中，“农民等级”改为“所谓的市民等级”。——编者注］在现存制度下必然发生的灭亡过程；（3）欧洲各国资产者阶级在商业上受世界市场霸主英国的奴役和剥削的情形。","language":"中文","translation":false},{"id":"wage-labour-1-7","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们力求说得尽量简单和通俗，我们就当读者连最起码的政治经济学概念也没有。我们希望工人能明白我们的解说。加之，在德国到处对一些最简单的经济关系的了解都极端无知和十分混乱，从特许的现存制度的辩护者到冒牌的社会主义者和未被承认的政治天才都莫不如此，这种人在四分五裂的德国比“诸侯王爷”还多。","language":"中文","translation":false},{"id":"wage-labour-1-8","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们首先来讲第一个问题：什么是工资？它是怎样决定的？","language":"中文","translation":false},{"id":"wage-labour-1-9","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"假如问工人们：“你们的工资是多少？”，那末一个工人回答说：“我做一天工从资产者那里得到一法郎［注：一法郎等于八普鲁士银格罗申。［在1891年的版本中，“法郎”完全改为“马克”。——编者注］］。”；另一个工人回答说：“我得到两法郎”，等等。由于他们工作的劳动部门不同，他们每一个人因劳动了一定的时间或［注：在1891年的版本中，“劳动了一定的时间或”删去了。——编者注］做了一定的工作（譬如，织成一尺麻布或排好一个印张的字）而从各自的资产者那里得到的货币数量也不同。尽管他们得到的货币数量不同，但是有一点是一致的：就是工资是资产者为了偿付劳动一定的时间或完成一定的工作而支出的一笔货币。","language":"中文","translation":false},{"id":"wage-labour-1-10","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可见［注：在1891年的版本中，“可见”后面加有“看起来仿佛”。——编者注］，资产者是用货币购买工人的劳动。工人是为了货币而向资产者出卖自己的劳动［注：在1891年的版本中，“劳动”后面加有：“但这只是表面情形。实际上，他们是为了货币向资本家出卖自己的劳动力的。资本家以一日、一周、一月等等为期购买这个劳动力。而当他把劳动力买到手以后，他就使用它，迫使工人在约定的期间内劳动。”——编者注］。资产者用以购买工人劳动［注：在1891年的版本中，“资产者用以购买工人劳动”改为“资本家用以购买工人劳动力”。——编者注］的那个货币量，譬如说两法郎，也可以买到两磅糖或一定数量的其他某种商品。他用以购买两磅糖的两法郎，就是两磅糖的价格。他用以购买十二小时劳动［注：在1891年的版本中，“劳动”改为“劳动力使用”。——编者注］的两法郎，就是十二小时劳动的价格。可见，劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］是一种商品，是和沙糖一模一样的商品。前者是用钟点来计量的，后者是用重量来计量的。","language":"中文","translation":false},{"id":"wage-labour-1-11","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"工人拿自己的商品即劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］去换得资本家的商品，即换得货币，并且这种交换是按一定的比率进行的。一定量的货币交换一定量的劳动［注：在1891年的版本中，“劳动”改为“劳动力使用”。——编者注］时间。织布工人的十二小时劳动交换两法郎。但是，难道这两法郎不是代表其他一切可以用两法郎买到的商品吗？可见，实质上工人是拿他自己的商品即劳动交换各种各样的其他商品［注：在1891年的版本中，“劳动交换各种各样的其他商品”改为“劳动力交换各种各样的商品”。——编者注］，并且是按一定的比率变换的。资本家付给他两法郎，就是为交换他的劳动日而付给了他一定量的肉，一定量的衣服，一定量的劈柴，一定量的灯光，等等。可见，这两法郎是表现劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］跟其他商品相交换的比例，即表现他的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的交换价值。商品通过货币表现出来的交换价值，也就称为商品的价格。所以，工资只是劳动价格［注：在1891年的版本中，“劳动价格”改为“通常被称为劳动价格的劳动力价格”。——编者注］的特种名称，是只能存在于人的血肉中的这种特殊商品价格的特种名称。","language":"中文","translation":false},{"id":"wage-labour-1-12","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"拿任何一个工人来说，比如拿一个织布工人来说吧。资产者［注：在1891年的版本中，“资产者”改为“资本家”。——编者注］供给他一架织布机和一些纱。织布工人动手工作，纱变成了布。资产者［注：在1891年的版本中，“资产者”改为“资本家”。——编者注］把布拿去，卖了——比方说——二十法郎。织布工人的工资是不是这块布中的一份，二十法郎中的一份，他的劳动产品中的一份呢？绝对不是。因为这个织布工人是在布还没有卖出很久以前，甚至可能是在布还没有织成很久以前就得到了自己的工资的。可见，资本家支付的这笔工资并不是来自他卖布所赚的那些货币，而是来自他原来储备的货币。织布工人从资产者那里领来使用的织布机和纱不是他的产品，同样，他用自己的商品即劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］交换所得的那些商品也不是他的产品。可能有这样的情形：资产者给自己的布找不到一个买主。他出卖布所赚的钱，也许甚至不能捞回他用于开销工资的款项。也有可能他出卖布所得的钱，比他付给织布工人的工资数目大得多。这一切都与织布工人毫不相干。资本家拿自己的一部分现有财产即一部分资本去购买织布工人的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］，这就同他拿他的另一部分资本去购买原料（纱）和劳动工具（织布机）完全一样。购买了这些东西（其中包括生产布所必需的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］）以后，资本家就用只是属于他的原料和劳动工具进行生产。当然，我们这位善良的织布工人现在也属于劳动工具之列，他也做织布机一样在产品中或在产品价格中是没有份的。","language":"中文","translation":false},{"id":"wage-labour-1-13","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"所以，工资不是工人在他所生产的商品中占有的一份。工资是原有商品中由资本家用以购买一定量的生产劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的那一部分。","language":"中文","translation":false},{"id":"wage-labour-1-14","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"总之，劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］是一种商品，是由其所有者即雇佣工人出卖给资本的一种商品。他为什么出卖它呢？为了生活。","language":"中文","translation":false},{"id":"wage-labour-1-15","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可是［注：在1891年的版本中，“可是”后面加有“劳动力在动作中的表现”。——编者注］，劳动是工人本身的生命活动，是工人本身的生命的表现。工人正是把这种生命活动出卖给别人，以获得自己所必需的生活资料。可见，工人的生命活动对于他不过是使他能以生存的一种手段而已。他是为生活而工作的。他甚至不认为劳动是自己生活的一部分；相反地，对于他来说，劳动就是牺牲自己的生活。劳动是已由他出卖给别人的一种商品。因此，他的活动的产物也就不是他的活动的目的。工人为自己生产的不是他织成的绸缎，不是他从金矿里开采出的黄金，也不是他盖起的高楼大厦。他为自己生产的是工资，而绸缎、黄金、高楼大厦对于他都变成一定数量的生活资料，也许是变成棉布上衣，变成铜币，变成某处地窖的住所了。一个工人在一昼夜中有十二小时在织布、纺纱、钻孔、研磨、建筑、挖掘、打石子、搬运重物等等，他能不能认为这十二小时的织布、纺纱、钻孔、研磨、建筑、挖掘、打石子是他的生活的表现，是他的生活呢？恰恰相反，对于他来说，在这种活动停止以后，当他坐在饭桌旁，站在酒店柜台前，睡在床上的时候，生活才算开始。在他看来，十二小时劳动的意义并不在于织布、纺纱、钻孔等等，而在于这是挣钱的方法，挣钱使他能吃饭、喝酒、睡觉。假如说蚕儿吐丝作茧是为了维持自己的生存，那末它就可算是一个真正的雇佣工人了。","language":"中文","translation":false},{"id":"wage-labour-1-16","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］并不向来就是商品。劳动并不向来就是雇佣劳动、即自由劳动。奴隶就不是把他自己的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］出卖给奴隶主，正如耕牛不是向农民卖工一样。奴隶连同自己的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］一次而永远地卖给自己的主人了。奴隶是商品，可以从一个所有者手里转到另一个所有者手里。奴隶本身是商品，但劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］却不是他的商品。农奴只出卖自己的一部分劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］。不是他从土地所有者方面领得报酬；相反地，土地所有者从他那里收取贡赋。农奴是土地的附属品，替土地所有者生产果实。相反地，自由工人自己出卖自己，并且是零碎地出卖。他每天把自己生命中的八小时、十小时、十二小时、十五小时拍卖给出钱最多的人，拍卖给原料、劳动工具和生活资料的所有者，即拍卖给资本家。工人既不属于私有者，也不属于土地，但是他每日生命的八小时、十小时、十二小时、十五小时却属于它的购买者。工人只要愿意，就可以离开雇用他的资本家，而资本家也可以随意辞退工人，只要工人使他不能再获得利益或者不能使他获得预期的利益，他就可以辞退。但是，工人是以出卖劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］为其工资的唯一来源的，如果他不愿饿死，就不能离开整个购买者阶级即资本家阶级。工人不是属于某一个资产者，而是属于整个资产阶级［注：在1891年的版本中，“不是属于某一个资产者，而是属于整个资产阶级”改为“不是属于某一个资本家，而是属于整个资本家阶级”。——编者注］；至于工人给自己寻找一个雇主，即在资产阶级［注：在1891年的版本中，“资产阶级”改为“资本家阶级”。——编者注］中间寻找一个买主，那是工人自己的事情了。","language":"中文","translation":false},{"id":"wage-labour-1-17","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"现在，在更详细地谈论资本和雇佣劳动之间的关系以前，我们先简短地叙述一下在决定工资时起作用的一些最一般的条件。","language":"中文","translation":false},{"id":"wage-labour-1-18","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们已经说过，工资是一定商品——劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的价格。所以，工资是由那些决定其他一切商品价格的规律决定的。","language":"中文","translation":false},{"id":"wage-labour-1-19","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"那末，试问：商品的价格是怎样决定的呢？","language":"中文","translation":false},{"id":"wage-labour-1-20","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"科伦4月5日。商品的价格是由什么决定的？","language":"中文","translation":false},{"id":"wage-labour-1-21","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"它是由买主和卖主之间的竞争即供求关系决定的。决定商品价格的竞争是三方面的。","language":"中文","translation":false},{"id":"wage-labour-1-22","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"同一种商品，有许多不同的卖主供应。谁以最便宜的价格出卖同一质量的商品，谁就一定会战胜其他卖主，从而保证自己有最大的销路。于是，各个卖主彼此间就进行争夺销路、争夺市场的斗争。他们每一个人都想出卖商品，都想尽量多卖，如果可能，都想由他一个人独卖，而把其余的卖主排挤掉。因此，一个人就要比另一个人卖得便宜些。于是卖主之间就发生了竞争，这种竞争降低他们所供应的商品的价格。","language":"中文","translation":false},{"id":"wage-labour-1-23","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"但是买主之间也有竞争，这种竞争反过来提高所供应的商品的价格。","language":"中文","translation":false},{"id":"wage-labour-1-24","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"最后，买主和卖主之间也有竞争。前者想买得尽量便宜些，后者却想卖得尽量贵些。买主和卖主之间的这种竞争的结果怎样，要依上述竞争双方的对比关系怎样来决定，就是说要看是买主阵营里的竞争激烈些呢还是卖主阵营里的竞争激烈些。产业把两支军队抛到战场上对峙，其中每一支军队内部又发生内讧。战胜敌人的是内部冲突较少的那支军队。","language":"中文","translation":false},{"id":"wage-labour-1-25","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"假定说，市场上有一百包棉花，而买主们却需要一千包。在这种情形下，需求比供应大十倍，因而买主之间的竞争就会很激烈；他们中间的每一个人都竭力设法至少也要搞到一包，如果可能，就把一百包全都搞到手里。这个例子并不是随意虚构的。在商业史上有过这样一些棉花歉收的时期，那时几个资本家彼此结成联盟，不只想把一百包棉花都收买下来，而且想把世界上的全部存棉都收买下来。这样，在我们前述的情形下，每一个买主都力图排挤掉另一个买主，出较高的价格收买每包棉花。棉花的卖主们看见敌军队伍里发生极剧烈的内讧、并完全相信他们的一百包棉花都能卖掉，因此他们就严防自己内部打起架来，以免在敌人竞相抬高价格的时候降低自己商品的价格。于是卖主阵营里忽然奠定了和平。他们冷静地叉着双手，像一个人似地对抗买主；只要那些最热衷的买主出价又没有一定的限度，那卖主的贪图也就会没有止境了。","language":"中文","translation":false},{"id":"wage-labour-1-26","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可见，某种商品的供应低于需求，那末这种商品的卖主中间的竞争就会很弱，甚至于完全没有竞争。卖主中间的竞争在某种程度上减弱，买主中间的竞争就会在某种程度上加剧。结果便是商品价格或多或少显著地上涨。","language":"中文","translation":false},{"id":"wage-labour-1-27","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"大家知道，较为常见的是产生相反后果的相反情形：供应大大超过需求，卖主中间拚命竞争，买主少，商品贱价拍卖。","language":"中文","translation":false},{"id":"wage-labour-1-28","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"但是，价格上涨和下跌是什么意思呢？高价和低价是什么意思呢？沙粒在显微镜下就显得高，宝塔比起山岳来就显得低了。既然价格是由供求关系决定的，那末供求关系又是由什么决定的呢？","language":"中文","translation":false},{"id":"wage-labour-1-29","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"让我们随便问一个资产者吧。他会像新即位的亚历山大大帝一样，马上毫不犹豫地利用乘法表来解开这个形而上学的纽结。他会对我们说，假如我生产我出卖的这个商品的费用是一百法郎，而我把它卖了一百一十法郎（自然是在一年期满后），那末这是一种普通的、老实的、正当的利润。假如我在进行交换时得到了一百二十或一百三十法郎，那就是高额利润了。假如我得到了整整二百法郎，那就会是特高的巨额利润了。对于这个资产者来说，究竟什么是衡量利润的尺度呢？这就是他的商品的生产费用。假如他拿自己的商品换来的一定数量的别种商品，其生产费用少于他的商品的生产费用，那他就算亏本了。可是假如他拿自己的商品换来的一定数量的别种商品，其生产费用大于他的商品的生产费用，那他就算赢利了。他是以生产费用作为零度，根据他的商品的交换价值在零度上下的度数来测定他的利润的升降的。","language":"中文","translation":false},{"id":"wage-labour-1-30","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"由此可见，供求关系的改变，引起价格的上涨或下跌，引起高价或低价。","language":"中文","translation":false},{"id":"wage-labour-1-31","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"假如某一种商品的价格，由于供应不足或需求剧增而大大上涨，那末另一种商品的价格就不免要相应地下跌，因为商品的价格不过是以货币来表示的别种商品和它交换的比率。举例说，假如一尺绸缎的价格从五法郎上涨到六法郎，那末白银的价格对于绸缎来讲就下跌了，其他一切商品也都是这样，它们的价格虽然没有改变，但比起绸缎来却是跌价了。这时若要交换得原来那么多的绸缎，就必须拿出更多的商品。","language":"中文","translation":false},{"id":"wage-labour-1-32","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"商品价格上涨会产生什么后果呢？大量资本将涌向繁荣的产业部门中去，而这种资本流入较为有利的产业部门中去的现象，要继续到该部门的利润跌落到普通水平时为止，或者更确切些说，要继续到该部门产品的价格由于生产过剩而跌落到生产费用以下时为止。","language":"中文","translation":false},{"id":"wage-labour-1-33","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"反之，假如某一种商品的价格跌落到它的生产费用以下，那末资本就要从该种商品生产部门中流出去了。除了该工业部门已经不合时代要求，因而必然衰亡以外，该商品的生产，即该商品的供应，就要因为资本的这种外流而缩减，直到该商品的供应和需求相适应为止，就是说，直到该商品的价格重新上涨到它的生产费用水平，或者更确切些说，直到供应低于需求，即直到商品价格又上涨到它的生产费用以上为止，因为商品的现时价格总是高于或低于它的生产费用。","language":"中文","translation":false},{"id":"wage-labour-1-34","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"由此可见，资本是不断地从一个生产部门向另一个生产部门流出或流入的。价格高就引起资本的过分猛烈的流入，价格低就引起资本的过分猛烈的流出。","language":"中文","translation":false},{"id":"wage-labour-1-35","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们从另一个角度来研究问题时能够证明：不仅供应，连需求也是由生产费用决定的。可是，这样一来，我们就未免离题太远了。","language":"中文","translation":false},{"id":"wage-labour-1-36","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们刚才说过，需求和供应的波动，每次都把商品的价格引导到生产费用的水平。固然，商品的实际价格始终不是高于生产费用，就是低于生产费用；但是，上涨和下降是相互抵销的，因此，在一定时间内，如果把工业中的资本流入和流出总合起来看，就可看出各种商品是依其生产费用而互相交换的，所以它们的价格是由生产费用决定的。","language":"中文","translation":false},{"id":"wage-labour-1-37","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"价格由生产费用决定这一点，不应当了解成像经济学家们所了解的那种意思。经济学家们说，商品的平均价格等于生产费用；在他们看来，这是一个规律。他们把价格的上涨被价格的下降所抵销，而下降则被上涨所抵销这种无政府状态的变动看作偶然现象。那末，同样也可以（另一些经济学家就正是这样做的）把价格的波动看作规律，而把价格由生产费用决定这一点看作偶然现象。可是实际上，只有在这种波动的进程中，价格才是由生产费用决定的；我们细加分析时就可以看出，这种波动起着极可怕的破坏作用，并像地震一样震撼资产阶级社会的基础。这种无秩序状态的总运动就是它的秩序。在这种产业无政府状态的进程中，在这种循环运转中，竞争可以说是拿一个极端去抵销另一个极端。","language":"中文","translation":false},{"id":"wage-labour-1-38","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"由此可见，商品价格是由生产费用这样来决定的：某些时期，某种商品的价格超过它的生产费用，另一些时期，该商品的价格却下跌到它的生产费用以下，而抵销以前超过的时期，反之亦然。当然，这不是就个别产业的产品来说的，而只是就整个产业部门来说的。所以，这同样也不是就个别产业家来说的，而只是就整个产业家阶级来说的。","language":"中文","translation":false},{"id":"wage-labour-1-39","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"价格由生产费用决定，就等于说价格由生产商品所必需的劳动时间决定，因为构成生产费用的是：（1）原料和劳动工具［注：在1891年的版本中，“劳动工具”改为“劳动工具损耗部分”。——编者注］，即产业产品，它们的生产耗费了一定数量的工作日，因而也就是代表一定数量的劳动时间；（2）直接劳动，它也是以时间计量的。","language":"中文","translation":false},{"id":"wage-labour-1-40","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"一般调节商品价格的那些最一般的规律，当然也调节工资，即调节劳动价格。","language":"中文","translation":false},{"id":"wage-labour-1-41","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"劳动报酬忽而提高，忽而降低，是依供求关系为转移的，依购买劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的资本家和出卖劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的工人之间的竞争情形为转移的。工资的波动一般是和商品价格的波动相适应的。可是，在这种波动的范围内，劳动的价格是由生产费用即为创造劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］这一商品所需要的劳动时间来决定的。","language":"中文","translation":false},{"id":"wage-labour-1-42","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"那末，劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］本身的生产费用究竟是什么呢？","language":"中文","translation":false},{"id":"wage-labour-1-43","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"这就是为了使工人保持其为工人并把他训练成为工人所需要的费用。","language":"中文","translation":false},{"id":"wage-labour-1-44","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"因此，某一种劳动所需要的训练时间愈少，工人的生产费用也就愈少，他的劳动的价格即他的工资也就愈低。在那些几乎不需要任何训练时间，只要有工人的肉体存在就行的产业部门里，为造成工人所需要的生产费用，几乎只归结为维持工人生存［注：在1891年的版本中，“生存”后面加有“及其劳动能力”。——编者注］所需要的商品。因此，工人的劳动的价格是由必需生活资料的价格决定的。","language":"中文","translation":false},{"id":"wage-labour-1-45","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可是，这里还应该注意到一种情况。","language":"中文","translation":false},{"id":"wage-labour-1-46","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"工厂主在计算自己的生产费用，并根据生产费用计算产品的价格的时候，是把劳动工具的损耗也计算在内的。譬如说，假如一架机器值一千法郎，使用期限为十年，那末他每年就要往商品价格中加进一百法郎，以便在十年期满时有可能用新机器来更换用坏的机器。同样，简单劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的生产费用中也应加入延缓工人后代的费用，即使工人阶级能够繁殖后代并用新工人来代替失去劳动能力的工人的费用。所以，工人的损耗也和机器的损耗一样，是要计算进去的。","language":"中文","translation":false},{"id":"wage-labour-1-47","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"总之，简单劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的生产费用就是维持工人生存和延续工人后代的费用。这种维持生存和延续后代的费用的价格就是工资。这样决定的工资就叫做最低工资。这种最低工资，也和商品价格一般由生产费用决定一样，不是就单个人来说的，而是就整个种属来说的。单个工人所得，千百万工人所得，不足以维持生存和延续后代，但整个工人阶级的工资在其波动范围内则是和这个最低额相等的。","language":"中文","translation":false},{"id":"wage-labour-1-48","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"现在，我们既已讲明了调节工资以及其他任何商品的价格的最一般规律，我们就能更切近地研究我们的本题了。","language":"中文","translation":false},{"id":"wage-labour-1-49","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"科伦4月6日。资本包括原料、劳动工具和各种生活资料，这些东西是用以生产新的原料、新的劳动工具和新的生活资料的。资本的所有这些组成部分都是劳动的创造物，劳动的产品，积累起来的劳动。作为进行新生产的手段的积累起来的劳动就是资本。","language":"中文","translation":false},{"id":"wage-labour-1-50","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"经济学家们就是这样说的。","language":"中文","translation":false},{"id":"wage-labour-1-51","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"什么是黑奴呢？黑奴就是黑种人。上面的说明和这个说明是一样的。","language":"中文","translation":false},{"id":"wage-labour-1-52","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"黑人就是黑人。只有在一定的关系下，他才成为奴隶。纺纱机是纺棉花的机器。只有在一定的关系下，它才成为资本。脱离了这种关系，它也就不是资本了，就像黄金本身并不是货币，沙糖并不是沙糖的价格一样。","language":"中文","translation":false},{"id":"wage-labour-1-53","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"人们在生产中不仅仅同自然界发生关系［注：在1891年的版本中，“不仅仅与自然界发生关系”改为“不仅仅影响自然界，而且也互相影响”。——编者注］。他们如果不以一定方式结合起来共同活动和互相交换其活动，便不能进行生产。为了进行生产，人们便发生一定的联系和关系；只有在这些社会联系和社会关系的范围内，才会有他们对自然界的关系［注：在1891年的版本中，“对自然界的关系”改为“对自然界的影响”。——编者注］，才会有生产。","language":"中文","translation":false},{"id":"wage-labour-1-54","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"生产者相互发生的这些社会关系，他们借以互相交换其活动和参于共同生产的条件，当然依照生产资料的性质而有所不同。随着新作战工具即射击火器的发明，军队的整个内部组织就必然改变了，各个人借以组成军队并能作为军队行动的那些关系就改变了，各个军队相互间的关系也发生了变化。","language":"中文","translation":false},{"id":"wage-labour-1-55","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"总之，各个人借以进行生产的社会关系，即社会生产关系，是随着物质生产资料、生产力的变化和发展而变化和改变的。生产关系总合起来就构成为所谓社会关系，构成为所谓社会，并且是构成为一个处于一定历史发展阶段上的社会，具有独特的特征的社会。古代社会、封建社会和资产阶级社会都是这样的生产关系的总和，而其中每一个生产关系的总和同时又标志着人类历史发展中的一个特殊阶段。","language":"中文","translation":false},{"id":"wage-labour-1-56","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"资本也是一种社会生产关系。这是资产阶级的生产关系，是资产阶级社会的生产关系。构成资本的生活资料、劳动工具和原料，难道不是在一定的社会条件下，不是在一定的社会关系下生产出来和积累起来的吗？难道这一切不是在一定的社会条件下，在一定的社会关系内被用来进行新生产的吗？并且，难道不正是这种一定的社会性质把那些用来进行新生产的产品变为资本的吗？","language":"中文","translation":false},{"id":"wage-labour-1-57","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"资本不仅包括生活资料、劳动工具和原料，不仅包括物质产品。并且还包括交换价值。资本所包括的一切产品都是商品。所以，资本不仅是若干物质产品的总和，并且也是若干商品或若干交换价值或若干社会定量的总和。","language":"中文","translation":false},{"id":"wage-labour-1-58","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"不论我们是以棉花代替羊毛也好，是以米代替小麦也好，是以轮船代替铁路也好，只要这些体现资本的棉花、米和轮船同原先体现资本的羊毛、小麦和铁路具有同样的交换价值即同样的价格，那末资本依然还是资本。资本的肉体可以经常改变，但不会使资本性质有丝毫改变。","language":"中文","translation":false},{"id":"wage-labour-1-59","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"虽然任何资本都是一些商品即交换价值的总和，然而远不是任何一些商品即交换价值的总和都是资本。","language":"中文","translation":false},{"id":"wage-labour-1-60","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"任何一些交换价值的总和都是一个交换价值。任何单个交换价值都是一些交换价值的总和。例如，值一千法郎的一座房子是一千法郎的交换价值。值一生丁［注：在1891年的版本中，“生丁”改为“分尼”。——编者注］的一印张纸是100/100生丁的交换价值的总和。能同别的产品交换的产品就是商品。这些产品由以交换的一定比率就是它们的交换价值，如果这种比率是用货币来表示的，就是它们的价格。这些产品的数量多少丝毫不能改变它们成为商品，或者表现交换价值，或者具有一定价格的这种性能。一株树不论其大小如何，终究是一株树。我们拿铁同别的产品交换时不是以两为单位，而是以公担为单位，难道铁作为商品，作为交换价值的性能竟会因此而改变吗？铁作为一种商品，只是依其数量多少而具有大小不同的价值，高低不同的价格。","language":"中文","translation":false},{"id":"wage-labour-1-61","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"一些商品即一些交换价值的总和究竟是怎样成为资本的呢？","language":"中文","translation":false},{"id":"wage-labour-1-62","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"它成为资本，是由于它作为一种独立的社会力量，即作为一种属于社会一部分的力量，借交换直接的、活的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］而保存下来并增殖起来。除劳动能力以外一无所有的阶级的存在是资本的必要前提。","language":"中文","translation":false},{"id":"wage-labour-1-63","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"只是由于积累起来的、过去的、物化的劳动支配直接的、活的劳动，积累起来的劳动才变为资本。","language":"中文","translation":false},{"id":"wage-labour-1-64","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"资本的实质并不在于积累起来的劳动是替活劳动充当进行新生产的手段。它的实质在于活劳动是替积累起来的劳动充当保存自己并增加其交换价值的手段。","language":"中文","translation":false},{"id":"wage-labour-1-65","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"资本和雇佣劳动［注：在1891年的版本中，“资本和雇佣劳动”改为“资本家和雇佣工人”。——编者注］是怎样进行交换的呢？","language":"中文","translation":false},{"id":"wage-labour-1-66","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"工人拿自己的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］换到生活资料，而资本家拿归他所有的生活资料换到劳动，即工人的生产活动，亦即创造力量。这种力量不仅能补偿工人所消费的东西，并且还使积累起来的劳动具有比以前更大的价值。工人从资本家那里得到一部分现有的生活资料。这些生活资料对工人有什么用处呢？用于直接消费。可是，如果我不把靠这些生活资料维持我的生活的一段时间用来生产新的生活资料，即在消费的同时用我的劳动创造新价值来补偿那些因消费而消失了的价值，那末我一把这些生活资料消费完，它们对于我就算是完全白耗费了。但是，工人为了换到生活资料，正是把这种贵重的再生产力量让给了资本家。因此，对于工人本身来说，这种力量是白耗费了。","language":"中文","translation":false},{"id":"wage-labour-1-67","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"举一个例子来说吧。有个农场主每天付给他的一个短工五银格罗申。这个短工为得到这五银格罗申，就整天在农场主的田地上干活，保证农场主能得到十银格罗申的收入。农场主不但收回了他付给短工的价值，并且还把它增加了一倍。可见，他有成效地、生产性地使用和消费了他付给短工的五银格罗申。他拿这五银格罗申买到的正是一个短工的能生产出双倍价值的农产品并把五银格罗申变成十银格罗申的劳动和力量。短工则拿他的生产力（他正是把这个生产力让给了农场主）换到五银格罗申，并用它们换得迟早要消费掉的生活资料。所以，这五银格罗申的消费有两种方法：对资本家来说，是有生产性的，因为他用这五银格罗申换来的劳动力使他得到了十银格罗申；对工人来说，是非生产性的，因为他用这五银格罗申换来的生活资料永远消失了，他只有再和农场主进行同样的交换才能重新取得这些生活资料的价值。这样，资本以雇佣劳动为前提，而雇佣劳动又以资本为前提。两者相互制约；两者相互产生。","language":"中文","translation":false},{"id":"wage-labour-1-68","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"一个棉纺织厂的工人是不是只生产棉织品呢？不是，他生产资本。他生产重新供人利用去支配他的劳动并借他的劳动创造新价值的价值。","language":"中文","translation":false},{"id":"wage-labour-1-69","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"资本只有同劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］交换，只有引起雇佣劳动的产生，才能增加起来。雇佣劳动［注：在1891年的版本中，“雇佣劳动”改为“雇佣工人的劳动力”。——编者注］只有在它增加资本，使奴役它的那种权力加强时，才能和资本交换。因此，资本的增加就是无产阶级即工人阶级的增加。","language":"中文","translation":false},{"id":"wage-labour-1-70","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"所以，资产者及其经济学家们断言，资本家和工人的利益是一致的。千真万确呵！工人若不受雇于资本家就会灭亡。资本若不剥削劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］就会灭亡，而要剥削劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］，资本就得购买劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］。投入生产的资本即生产资本增殖愈快，也就是说，产业愈繁荣，资产阶级愈发财，生意愈兴隆，资本家需要的工人也就愈多，工人出卖自己的价格也就愈高。","language":"中文","translation":false},{"id":"wage-labour-1-71","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"原来，生产资本的尽快增加竟是工人能勉强过活的必要条件。","language":"中文","translation":false},{"id":"wage-labour-1-72","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"但是，生产资本的增加又是什么意思呢？就是积累起来的劳动对活劳动的支配权力的增加，就是资产阶级对工人阶级的统治力量的增加。雇佣劳动生产着对它起支配作用的他人财富，也就是说生产着同它敌对的力量——资本，而它从资本那里取得就业手段，即取得生活资料，是以雇佣劳动又会变成资本的一部分，又会变成使资本加速增殖的杠杆为条件的。","language":"中文","translation":false},{"id":"wage-labour-1-73","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"断言资本的利益和劳动的利益［注：在1891年的版本中，“劳动的利益”改为“工人的利益”。——编者注］是一致的，事实上不过是说资本和雇佣劳动是同一种关系的两个方面罢了。一个方面制约着另一个方面，就如同高利贷者和挥霍者相互依存一样。","language":"中文","translation":false},{"id":"wage-labour-1-74","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"当雇佣工人仍然是雇佣工人的时候，他的命运是取决于资本的。所谓工人和资本家的利益一致就是这么一回事。","language":"中文","translation":false},{"id":"wage-labour-1-75","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"科伦4月7日。资本愈增长，雇佣劳动量就愈增长，雇佣工人人数就愈增加，一句话，受资本支配的人数就愈增多。我们且假定有这样一种最适意的情形：随着生产资本的增加，对劳动的需求也增加了，因而劳动价格即工资也提高了。","language":"中文","translation":false},{"id":"wage-labour-1-76","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"一座小房子不管怎样小，在周围的房屋都是这样小的时候，它是能满足社会对住房的一切要求的。但是，一旦在这座小房子近旁耸立起一座宫殿，这座小房子就缩成可怜的茅舍模样了。这时，狭小的房子证明它的居住者毫不讲究或者要求很低；并且，不管小房子的规模怎样随着文明的进步而扩大起来，但是，只要近旁的宫殿以同样的或更大的程度扩大起来，那末较小房子的居住者就会在那四壁之内越发觉得不舒适，越发不满意，越发被人轻视。","language":"中文","translation":false},{"id":"wage-labour-1-77","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"工资的任何显著的增加是以生产资本的迅速增加为前提的。生产资本的迅速增加，就要引起财富、奢侈，社会需要和社会享受等同样迅速的增长。所以，工人可以得到的享受纵然增长了，但是，比起资本家的那些为工人所得不到的大为增加的享受来，比起一般社会发展水平来，工人所得到的社会满足的程度反而降低了。我们的需要和享受是由社会产生的，因此，我们对于需要和享受是以社会的尺度，而不是以满足它们的物品去衡量的。因为我们的需要和享受具有社会性质，所以它们是相对的。","language":"中文","translation":false},{"id":"wage-labour-1-78","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"工资一般不仅是由我能够用它交换到的商品数量来决定的。工资包含着各种对比关系。","language":"中文","translation":false},{"id":"wage-labour-1-79","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"首先，工人靠出卖自己的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］取得一定数量的货币。工资是不是单由这个货币价格来决定的呢？","language":"中文","translation":false},{"id":"wage-labour-1-80","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"在十六世纪，由于美洲的发现［注：在1891年的版本中，“美洲的发现”改为“在美洲发现了更丰富和更易于开采的金矿”。——编者注］，欧洲流通的黄金和白银的数量增加了。因此，黄金和白银的价值和其他各种商品比较起来就降低了。但是，工人们出卖自己的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］所得到的银币数仍和从前一样。他们的劳动的货币价格仍然如旧，然而他们的工资毕竟是降低了，因为他们拿同样数量的银币所交换到的别种商品比以前少了。这是促成十六世纪资本增殖和资产阶级兴盛的原因之一。","language":"中文","translation":false},{"id":"wage-labour-1-81","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们再举一个别的例子。1847年冬，由于歉收，最必需的生活资料（面包、肉类、黄油、干酪等等）大大涨价了。假定工人靠出卖自己的劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］所得的货币量仍和以前一样。难道他们的工资没有降低吗？当然是降低了。他们拿同样多的货币所能换到的面包、肉类等等东西比从前少了。他们的工资降低并不是因为白银的价值减低了，而是因为生活资料的价值增高了。","language":"中文","translation":false},{"id":"wage-labour-1-82","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"我们最后再假定，劳动的货币价格仍然未变，可是一切农产品和工业品由于使用新机器、年成好等等原因而降低了价格。这时，工人拿同样多的货币可以买到更多的各种商品。所以，他们的工资正因为工资的货币价值仍然未变而提高了。","language":"中文","translation":false},{"id":"wage-labour-1-83","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"总之，劳动的货币价格即名义工资，是和实际工资即用工资实际交换所得的商品量并不一致的。因此，我们谈到工资的增加或降低时，不应当仅仅注意到劳动的货币价格，仅仅注意到名义工资。","language":"中文","translation":false},{"id":"wage-labour-1-84","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"但是，无论名义工资，即工人把自己卖给资本家所得到的货币量，无论实际工资，即工人用这些货币所能买到的商品量，都不能把工资所包含的各种对比关系完全表示出来。","language":"中文","translation":false},{"id":"wage-labour-1-85","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"此外，工资首先是由它和资本家的赢利即利润的对比关系来决定的。这就是比较工资、相对工资。","language":"中文","translation":false},{"id":"wage-labour-1-86","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"实际工资所表示的是同其他商品的价格相比的劳动价格，反之，相对工资所表示的则是同积累起来的劳动的价格相比的直接劳动价格，是雇佣劳动和资本的相对价值，是资本家和工人的相互价值［注：在1891年的版本中，恩格斯把自“反之，相对工资”以下的一段话改为：“而相对工资所表示的，则是直接劳动从劳动新创造出的价值中所获得的那个同积累起来的劳动即资本从这种价值中所取得的份额相比的份额。","language":"中文","translation":false},{"id":"wage-labour-1-87","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"上面，在第14页［见本卷第477页。——编者注］上，我们说过：‘工资不是工人在他所生产的商品中占有的一份。工资是原有商品中由资本家用以购买一定量的生产劳动力的那一部分。’但是，资本家要从卖出由工人创造的产品所得的进款中再补偿这笔工资。资本家在补偿这笔工资时，照例要在扣除生产费用后，还有若干剩余，即还有利润。工人所生产的商品的销售价格，对资本家来说可分为三部分：第一，补偿他所垫支的原料价格和他所垫支的工具、机器及其他劳动资料的损耗；第二，补偿资本家所垫支的工资；第三，这些费用以外的余额，即资本家的利润。第一部分只是补偿原已存在的价值；很清楚，补偿工资的那一部分和构成资本家利润的余额完全是从工人劳动所创造出来的并附加到原料价值上去的新价值中得来的。而在这个意义上说，为了把工资和利润加以比较，我们可以把两者都看成是工人生产的产品中的份额。”——编者注］。","language":"中文","translation":false},{"id":"wage-labour-1-88","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"实际工资可能仍然未变，甚至可能增加了，但是相对工资却可能降低了。假定说，一切生活资料跌价三分之二，而日工资只降低了三分之一，比方由三法郎降低到两法郎。这时，虽然工人拿这两法郎可以买到比从前拿三法郎买到的更多的商品，但是和资本家的利润比较起来，工人的工资终究是降低了。资本家（比如，一个工厂主）的利润增加了一法郎，换句话说，资本家拿比以前少的交换价值付给工人，而工人却得替资本家生产出比以前多的交换价值。资本的价值比劳动的价值提高了［注：在1891年的版本中，“资本的价值比劳动的价值提高了”改为“资本所得的份额比劳动所得的份额提高了”。——编者注］。社会财富在资本和劳动之间的分配更不平衡了。资本家用同样多的资本支配着更多的劳动。资本家阶级支配工人阶级的权力增加了，工人的社会地位更坏了，比起资本家的地位来又降低了一级。","language":"中文","translation":false},{"id":"wage-labour-1-89","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"决定工资和利润在其相互关系上的降低和增加的一般规律究竟是怎样的呢？","language":"中文","translation":false},{"id":"wage-labour-1-90","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"工资和利润是互成反比的。资本的交换价值［注：在1891年的版本中，“资本的交换价值”，改为“资本的所得份额”。——编者注］即利润愈增加，则劳动的交换价值［注：在1891年的版本中，“劳动的交换价值”改为“劳动的所得份额”。——编者注］即按日工资就愈降低；反之亦然。利润增加多少，工资就降低多少；而利润降低多少，则工资就增加多少。","language":"中文","translation":false},{"id":"wage-labour-1-91","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"也许有人会驳斥说：资本家赢利可能是由于他拿自己的产品同其他资本家进行了有利的交换，可能是由于开辟了新的市场或者原有市场上的需要骤然增加等等，从而对他的商品的需求量大为增加；所以，一个资本家所得利润的增加可能是由于损害了其他资本家的利益，而与工资即劳动［注：在1891年的版本中，“劳动”改为“劳动力”。——编者注］的交换价值的涨落无关；或者，资本家所得利润的增加也可能是由于改进了劳动工具，采用了利用自然力的新方法等等。","language":"中文","translation":false},{"id":"wage-labour-1-92","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"首先必须承认，所得出的结果依然是一样的，只不过这是经过相反的途径得出的。固然，利润的增加不是由于工资的降低，但是工资的降低却是由于利润的增加。资本家用同一数量的劳动［注：在1891年的版本中，“劳动”改为“别人的劳动”。——编者注］，购得了更多的交换价值，而对这个劳动却没有多付一文。这就是说，劳动所得的报酬同它使资本家得到的纯收入相比却减少了。","language":"中文","translation":false},{"id":"wage-labour-1-93","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"此外，我们还应提醒，无论商品价格如何波动，每一种商品的平均价格，即它同别种商品相交换的比率，总是由它的生产费用决定的。因此，资本家相互间的盈亏得失必定在整个资本家阶级范围内互相抵销。改进机器，在生产中采取利用自然力的新方法，使得在一定的劳动时间内，用同样数量的劳动和资本可以创造出更多的产品，但绝不是创造出更多的交换价值。如果我用纺纱机能够在一小时内生产出比未发明这种机器以前的产量多一倍的纱，比方从前为五十磅，现在为一百磅，那末我用这一百磅纱交换所得［注：在1891年的版本中，在“所得”之后还有“平均起来在一个相当长的时间内”一句话。——编者注］的商品，并不比以前用五十磅交换到的多些，因为纱的生产费用减低了一半，或者说，因为现在我用同样多的生产费用能够生产出比以前多一倍的产品。","language":"中文","translation":false},{"id":"wage-labour-1-94","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"最后，不管资本家阶级即资产阶级（一个国家的也好，整个世界市场的也好）相互之间分配生产所得的纯收入的比率如何，这个纯收入的总额归根到底只是活劳动［注：在1891年的版本中，“活劳动”改为“直接劳动”。——编者注］加到全部积累起来的劳动上去的那个数额。所以，这个总额是按劳动增殖资本的比率，即按利润比工资增加的比率增长的。","language":"中文","translation":false},{"id":"wage-labour-1-95","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可见，即使我们单只在资本和雇佣劳动的关系这个范围内观察问题，也可以知道资本的利益和雇佣劳动的利益是截然对立的。","language":"中文","translation":false},{"id":"wage-labour-1-96","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"资本的迅速增加就等于利润的迅速增加。而利润的迅速增加只有在劳动的交换价值［注：在1891年的版本中，“劳动的交换价值”改为“劳动价格”。——编者注］同样迅速下降，相对工资同样迅速下降的条件下才是可能的。即使在实际工资同名义工资即劳动的货币价值同时增加的情况下，只要实际工资不是和利润同等地增加，相对工资还是可能下降的。比如说，在经济兴旺的时期，工资提高5％，而利润却提高30％，那末比较工资即相对工资不是增加，而是减少了。","language":"中文","translation":false},{"id":"wage-labour-1-97","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"所以，一方面工人的收入在资本迅速增加的情况下也有所增加，可是另一方面横在资本家和工人之间的社会鸿沟也同时扩大，而资本支配劳动的权力，劳动对资本的依赖程度也随着增大。","language":"中文","translation":false},{"id":"wage-labour-1-98","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"所谓资本迅速增加对工人有好处的论点，实际上不过是说：工人把他人的财富增殖得愈迅速，落到工人口里的残羹剩饭就愈多，能够获得工作和生活下去的工人就愈多，依附资本的奴隶人数就增加得愈多。","language":"中文","translation":false},{"id":"wage-labour-1-99","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"即使最有利于工人阶级的情势，即使资本的尽快增加如何改善了工人的物质生活状况，也不能消灭工人的利益和资产者即资本家的利益之间的对立状态。利润和工资仍然是互成反比的。","language":"中文","translation":false},{"id":"wage-labour-1-100","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"假如资本增加得迅速，工资是可能提高的；可是资本家的利润增加得更迅速无比。工人的物质生活改善了，然而这是以他们的社会地位的降低为代价换来的。横在他们和资本家之间的社会鸿沟扩大了。","language":"中文","translation":false},{"id":"wage-labour-1-101","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"所谓生产资本的尽快增加是对雇佣劳动最有利的条件这种论点，实际上不过是说：工人阶级愈迅速地扩大和增加敌对它的力量，即愈迅速地扩大和增加支配它的他人财富，它就能在愈加有利的条件下重新为资产阶级增殖财富、重新为资本加强权力而工作——这样的工作无非是它本身在铸造金锁链，让资产阶级用来牵着它走罢了。","language":"中文","translation":false},{"id":"wage-labour-1-102","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"科伦4月10日。然而，是不是像资产阶级的经济学家们所说的那样，生产资本的增加真的和工资的提高密不可分呢？我们不应当听信他们的话。我们甚至于不能相信他们的这种说法：似乎资本长得越肥，它的奴隶也吃得越好。资产阶级太开明了，太会打算了，它没有封建主的那种以奴仆的衣着华丽夸耀于人的偏见。资产阶级的生存条件迫使它锱铢必较。","language":"中文","translation":false},{"id":"wage-labour-1-103","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"因此我们就应当更仔细地研究一个问题：","language":"中文","translation":false},{"id":"wage-labour-1-104","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"生产资本的增长是怎样影响工资的？","language":"中文","translation":false},{"id":"wage-labour-1-105","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"如果资产阶级社会的生产资本整个说来是在不断增长，那末劳动的积累就是更多方面的了。资本的数目和资本的数额［注：在1891年的版本中，“资本的数目和资本的数额”改为“资本家的数目和他们的资本的数额”。——编者注］日益增加。资本的增殖加剧资本家之间的竞争。资本数额的增加，就使得有可能把装备着火力更猛烈的斗争武器的更强大的工人大军抛入产业战场。","language":"中文","translation":false},{"id":"wage-labour-1-106","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"一个资本家只有在自己更便宜地出卖商品的情况下，才能把另一个资本家逐出战场，并占有他的资本。可是，要能够贱卖而又不破产，他就必须廉价生产，就是说，必须尽量增加劳动的生产力。而增加劳动的生产力的首要办法是更细地分工，更全面地运用和经常地改进机器。内部实行分工的工人大军愈庞大，应用机器的规模愈广大，生产费用相对地就愈迅速缩减，劳动就更有效率。因此，资本家之间就发生了各方面的竞争：他们竭力设法扩大分工和增加机器，并尽可能大规模地使用机器。","language":"中文","translation":false},{"id":"wage-labour-1-107","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可是，假如某一个资本家由于更细地分工、更多地采用新机器并改进新机器，由于更有利和更广泛地利用自然力，因而有可能用同样多的劳动或积累起来的劳动生产出比他的竞争者更多的产品（即商品），比如说，在同一劳动时间内，他的竞争者只能织出半尺麻布，他却能织出一尺麻布，那末他会怎样办呢？","language":"中文","translation":false},{"id":"wage-labour-1-108","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"他可以继续按照原来的市场价格出卖每半尺麻布，但是这样他就不能把自己的敌人逐出战场，就不能扩大自己的销路。可是随着他的生产的扩大，他对销路的需要也增加了。固然，他所采用的这些更有力更贵重的生产资料使他能够廉价出卖商品，但是这种生产资料又使他不得不出卖更多的商品，为自己的商品争夺更大得多的市场。因此，这个资本家出卖半尺麻布的价格就要比他的竞争者便宜些。","language":"中文","translation":false},{"id":"wage-labour-1-109","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"虽然这个资本家生产一尺麻布的费用并不比他的竞争者生产半尺麻布的费用多，但是他不会以他的竞争者出卖半尺麻布的价格来出卖一尺麻布。不然他就占不到任何便宜，而只是通过交换把自己的生产费用收回罢了。如果他的收入终究还是增加了，那只是因为他动用了更多的资本，而不是因为他的资本比别人的资本更多地增加了自己的价值。而且只要他把他的商品价格定得比他的竞争者低百分之几，他追求的目的也就达到了。他压低价格就能把他的竞争者挤出市场，或者至少也能夺取他的竞争者的一部分销路。最后，我们再提一下，现时价格总是高于或低于生产费用，这取决于该种商品是在产业的旺季出卖的还是在淡季出卖的。一个采用了生产效能更高的新生产资料的资本家所能得到的超出他的实际生产费用的百分率，是依每尺麻布的市场价格高于或低于迄今的一般生产费用为转移的。","language":"中文","translation":false},{"id":"wage-labour-1-110","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可是这个资本家的特权不会长久，因为同他竞争的资本家也会采用同样的机器，实行同样的分工，并以同样的或更大的规模采用这些机器的分工。这些新措施将得到广泛的推广，直到麻布价格不仅跌到原先的生产费用以下，而且跌到新的生产费用以下为止。","language":"中文","translation":false},{"id":"wage-labour-1-111","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"这样，资本家的相互关系又会像采用新生产资料以前那样了；如果说他们由于采用这种生产资料曾经能够用以前的价格供给加倍的产品，那末现在他们已不得不按低于以前的价格出卖加倍的产品了。在这种新生产费用的水平上，同样一场钩心斗角的斗争又重新开始。又有人实行更细的分工，又有人增加机器数量，利用这种分工的范围和采用这些机器的规模日益扩大。而竞争又对这个结果发生反作用。","language":"中文","translation":false},{"id":"wage-labour-1-112","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"由此可见，生产方式和生产资料总在不断变更，不断革命化；分工必然要引起更进一步的分工；机器的采用必然要引起机器的更广泛的采用；大规模的生产必然要引起更大规模的生产。","language":"中文","translation":false},{"id":"wage-labour-1-113","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"这是一个规律，这个规律一次又一次地把资产阶级的生产甩出原先的轨道，并迫使资本加强劳动的生产力，因为它以前就加强过劳动的生产力；这个规律不让资本有片刻的停息，老是在它耳边催促说：前进！前进！","language":"中文","translation":false},{"id":"wage-labour-1-114","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"这个规律正就是那个在商业的周期性波动中必然使商品价格和商品生产费用趋于一致的规律。","language":"中文","translation":false},{"id":"wage-labour-1-115","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"不管一个资本家运用了效率多么高的生产资料，竞争总使这种生产资料的采用成为普遍的现象，而当这种生产资料的采用一旦成为普遍的现象时，他的资本具有更大效率的唯一后果就只能是：要取得原有的价格，他就必须供给比以前多十倍、二十倍、一百倍的商品。可是，因为现在他必须售出也许比以前多一千倍的商品，才能靠增加所售产品数量的办法来弥补由于售价降低所受的损失；因为他现在必须卖出更多的商品不仅是为了得到利润［注：在1891年的版本中，“得到利润”改为“得到更多的利润”。——编者注］，并且也是为了抵补生产费用（我们已经说过，生产工具本身也日益昂贵）；因为此时这种大量出卖不仅对于他而且对于他的竞争对方都成了生死问题，所以先前的斗争就因已经发明的生产资料的生产效率愈大而愈残酷无情地激烈起来。所以，分工和机器的采用又将以更大得无比的规模发展起来。","language":"中文","translation":false},{"id":"wage-labour-1-116","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"不管已被采用的生产资料的力量多么强大，竞争总是要把资本从这种强大力量中得到的黄金果实夺去，使商品的价格降低到生产费用的水平；也就是说，只要有可能更廉价的生产，即有可能用同一数量的劳动生产更多的产品，竞争就使廉价生产即按原先价格供给日益增多的产品数量成为确定不移的规律。可见，资本家努力的结果，除了必须在同一劳动时间内生产出更多的商品以外，换句话说，除了使他的资本的价值增殖的条件恶化以外，并没有得到任何好处。因此，虽然竞争经常以其生产费用的规律迫使资本家坐卧不宁，把他制造出来对付竞争者的一切武器倒转来针对着他自己，但资本家总是想方设法在竞争中取胜，孜孜不倦地采用价钱较贵但能进行廉价生产的新机器，实行新分工，以代替旧机器和旧分工，并且不等到竞争使这些新措施过时，就这样做了。","language":"中文","translation":false},{"id":"wage-labour-1-117","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"现在我们若是想像一下这种狂热的激发状态同时笼罩了整个世界市场，那我们就会明白，资本增殖、积累和集聚的结果，如何导向了不断地、日新月异地、更大规模地实行分工，采用新机器，改进旧机器。","language":"中文","translation":false},{"id":"wage-labour-1-118","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"这些同生产资本的增殖分不开的情况又怎样影响工资的确定呢？","language":"中文","translation":false},{"id":"wage-labour-1-119","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"更进一步的分工使一个工人能做五个、十个乃至二十个人的工作，因而就使工人之间的竞争加剧五倍、十倍乃至二十倍。工人中间的竞争不只表现于一个工人把自己出卖得比另一个工人贱些，而且还表现于一个工人做五个、十个乃至二十个人的工作。而资本所实行的和经常扩展的分工就迫使工人进行这种竞争。","language":"中文","translation":false},{"id":"wage-labour-1-120","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"其次，分工愈细，劳动就愈简单化。工人的特殊技巧失去任何价值。工人变成了一种简单的、单调的生产力，就不需要体力上或智力上的特别本事和技能了。他的劳动成为人人都能从事的劳动了。因此，工人受到四面八方的排挤；我们还要提醒一下，一种工作愈简单，就愈容易学会，为学会这种工作所需要的生产费用愈少，工资也就愈降低，因为工资像一切商品的价格一样，是由生产费用决定的。","language":"中文","translation":false},{"id":"wage-labour-1-121","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"总之，劳动愈是不能给人以乐趣，愈是令人生厌，竞争也就愈激烈，工资也就愈减少。工人想维持自己的工资总额，就得多劳动：多工作几小时或者在一小时内造出更多的产品。这样一来，工人为贫困所迫，就愈加重分工的极危险的后果。结果就是：他工作得愈多，他所得的工资就愈少。这里的原因很简单：他工作得愈多，他给自己的工友们造成的竞争就愈激烈，因而就使自己的工友们变成他自己的竞争者，这些竞争者也像他一样按同样恶劣的条件出卖自己。所以，原因同样很简单：他归根到底是自己给自己，即自己给作为工人阶级一员的自己造成竞争。","language":"中文","translation":false},{"id":"wage-labour-1-122","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"机器也发生同样的影响，而且影响的规模更大得多，因为机器用不熟练的工人代替熟练工人，用女工代替男工，用童工代替成年工；因为在最先使用机器的地方，机器就把大批手工工人抛到街头上去，而在机器日益完善、改进或为生产效率更高的机器所替换的地方，机器又把一批一批的工人排挤出去。我们在前面大略地描述了资本家相互间的产业战争。这种战争有一个特点，就是致胜的办法与其说是增加劳动大军，不如说是减少劳动大军。统帅们即资本家们相互竞赛，看谁能解雇更多的产业士兵。","language":"中文","translation":false},{"id":"wage-labour-1-123","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"不错，经济学家们告诉我们说，似乎因采用机器而成为多余的工人可以在新的工业部门里找到工作。","language":"中文","translation":false},{"id":"wage-labour-1-124","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"他们不敢干脆地肯定说，在新的劳动部门中找到栖身之所的就是那些被解雇的工人。事实最无情地粉碎了这种谎言。其实，他们不过是肯定说，在工人阶级的其他组成部分面前，譬如说，在一部分已准备进入那种衰亡的产业部门的青年工人面前，出现了新的就业门路。这对于不幸的工人当然是一个很大的安慰。资本家老爷们是不会缺少可供剥削的新鲜血肉的，于是他们就让死人们去埋葬自己的尸体。这种安慰，与其说是对工人的安慰，不如说是对资本家本身的安慰。要知道，假若机器消灭了整个雇佣工人阶级，那末资本的最可怕的时刻就会到来，因为资本没有雇佣劳动就不再成为资本了！","language":"中文","translation":false},{"id":"wage-labour-1-125","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"就假定那些直接被机器从一个产业部门排挤出去的工人以及原已指望受雇于该产业部门的那一部分青年工人都能找到新工作。是否可以相信新工作的报酬会和已失去的工作的报酬同样高呢？要是这样，那就是违反了一切经济规律。我们说过，现代产业经常是用简单的和低级的工作来代替较复杂和较高级的工作的。","language":"中文","translation":false},{"id":"wage-labour-1-126","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"既是这样，被机器从一个产业部门排挤出去的一大批工人若不甘愿领取更低更坏的报酬，又怎能在别的部门找到栖身之所呢？","language":"中文","translation":false},{"id":"wage-labour-1-127","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"有人说制造机器本身的工人是一种例外。他们说，既然产业需要并使用更多的机器，机器的数量就必然增加，因而机器的生产也必然增加，而在这个生产部门中工作的工人人数也必然随之增加；况且这个产业部门的工人是熟练工人，而且还是受过教育的工人。","language":"中文","translation":false},{"id":"wage-labour-1-128","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"从1840年起，这种原先也只有一半正确的论点已经毫无正确的影子了，因为机器生产部门也完全和棉纱生产部门一样，日益多方面地采用机器，而机器生产部门的工人，比起极完善的机器来，只能起着极不完善的机器的作用。","language":"中文","translation":false},{"id":"wage-labour-1-129","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"可是，在一个男工被机器排挤出去以后，工厂方面也许会雇佣三个童工和一个女工！难道先前一个男工的工资不是应该足够养活三个孩子和一个妻子吗？难道先前最低工资不是应该足够维持工人生活和繁殖工人后代吗？资产阶级爱说的这些话在这里究竟证明了什么呢？只证明了一点：现在要得到维持一个工人家庭生活的工资，就得消耗比以前多三倍的工人生命。","language":"中文","translation":false},{"id":"wage-labour-1-130","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"总括起来说：生产资本愈增加，分工和采用机器的范围就愈扩大。分工和采用机器的范围愈扩大，工人之间的竞争就愈剧烈，他们的工资就愈减少。","language":"中文","translation":false},{"id":"wage-labour-1-131","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"加之，工人阶级还从较高的社会阶层中得到补充；降落到无产阶级队伍里来的有大批小产业家和小食利者，他们除了赶快跟工人一起伸手乞求工作，毫无别的办法。这样，伸出来乞求工作的手像森林似地愈来愈稠密，而这些手本身则愈来愈消瘦。","language":"中文","translation":false},{"id":"wage-labour-1-132","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"不言而喻，小产业家是支持不住这种战争［注：在1891年的版本中，“战争”改为“斗争”。——编者注］的：这种战争的首要条件之一就是生产的规模经常扩大，也就是说必须要做大产业家而绝不能做一个小产业家。","language":"中文","translation":false},{"id":"wage-labour-1-133","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"当然，还有一点也是用不着进一步说明的：资本愈增殖，资本的总量和数目愈增加，资本的利息也就愈减少；因此，小食利者就不可能再依靠利息来维持生活，必须投到产业方面去，即补充小产业家的队伍，从而增加无产者的候补人数。","language":"中文","translation":false},{"id":"wage-labour-1-134","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"最后，上述发展进程愈迫使资本家以日益扩大的规模使用既有的巨大的生产资料，并为此而动用一切信贷机构，而“地震”［注：在1891年的版本中，“地震”改为“产业方面的地震”。——编者注］也来得愈来愈频繁，在每次地震中，商业界只是由于埋葬一部分财富、产品以至生产力才维持下去，——也就是说，危机来得愈益剧烈了。这种危机之所以来得愈频繁和愈剧烈，就是因为随着产品总量的增加，亦即随着对扩大市场的需要的增长，世界市场变得愈加狭窄了，剩下可供榨取的市场［注：在1891年的版本中，“市场”改为“新市场”。——编者注］愈益减少了，因为先前发生的每一次危机都把一些新市场或以前只被微微榨取过的市场卷入了世界贸易。但是，资本不光靠剥削劳动来生活。像显贵的野蛮的奴隶主一样，资本也要他的奴隶们陪葬，即在危机时期要使大批的工人死亡。由此可见：如果说资本增长得迅速，那末工人之间的竞争就增长得更迅速无比，就是说，资本增长得愈迅速，工人阶级的就业手段即生活资料就相对地缩减得愈厉害；虽然如此，资本的迅速增长对雇佣劳动却是最有利的条件。","language":"中文","translation":false},{"id":"wage-labour-1-135","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"卡·马克思根据他在1847年12月下半月所做的讲演写成","language":"中文","translation":false},{"id":"wage-labour-1-136","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"载于1849年4月5—8日和11日“新莱茵报”第264—267号和第269号","language":"中文","translation":false},{"id":"wage-labour-1-137","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"来源：《马克思恩格斯全集》第六卷","language":"中文","translation":false},{"id":"wage-labour-1-138","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"[298] “雇佣劳动与资本”是马克思根据他于1847年12月下半月在布鲁塞尔德国工人协会所作的讲演而写的。约·魏德迈抄写的标题为“工资”的手稿被保存了下来，这部手稿跟“新莱茵报”上发表的本文几乎完全一致。1848年初，马克思试图在布鲁塞尔发表这部著作。可是，由于马克思被逐出比利时而未能出版。","language":"中文","translation":false},{"id":"wage-labour-1-139","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"这部著作以“新莱茵报”社论的形式于1849年4月5—8日和11日首次发表，标题为“雇佣劳动与资本”。由于马克思暂时离开科伦，后来又由于德国政局更加紧张以及“新莱茵报”的停刊，这些文章的刊载遂告中断。","language":"中文","translation":false},{"id":"wage-labour-1-140","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"“雇佣劳动与资本”的首次发表，就已经促进了科学社会主义思想在德国工人中的传播。例如，根据科伦工人联合会委员会的决定，马克思的这些文章曾被推荐给科伦和其他城市的工人联合会讨论。","language":"中文","translation":false},{"id":"wage-labour-1-141","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"“新莱茵报”停刊后，马克思曾想出版“雇佣劳动与资本”的单行本，但是他未能亲自实现这个想法。这部著作的单行本于1880年在布勒斯劳首次出版，马克思未能参与其事。1881年又在同一地方再版。在恩格斯的参加下，这部著作于1884年又在霍廷根—苏黎世出版，并附有恩格斯写的一篇关于该书发表经过的简短序言。“雇佣劳动与资本”的第一种外文译本是俄译本（根据1880年德文版译出）；该译本于1883年在日内瓦出版。","language":"中文","translation":false},{"id":"wage-labour-1-142","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"1891年，为了在工人中进行宣传，这本小册子又出了一种新版，由恩格斯校订并作序。在这一版本中，恩格斯作了某些修改和补充，以使文章的叙述符合于马克思经济学说的进一步发展。关于正文的重新校订，恩格斯在序言中这样写道：“我所作的一切更改，归纳起来只有一点。凡在原稿上是说工人为取得工资而向资本家出卖自己的劳动的地方，在现在的本子上都改为出卖自己的劳动力”。接着，恩格斯论证了作这种更改的必要性。","language":"中文","translation":false},{"id":"wage-labour-1-143","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"所发表的“雇佣劳动与资本”仍然是不完全的。马克思于1847年12月写的手稿“工资”（见本卷第635—660页）可以作为正文的部分补充。","language":"中文","translation":false},{"id":"wage-labour-1-144","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"在本卷中，马克思的这部著作的俄译文译自“新莱茵报”。凡恩格斯在1891年的单行本中所作的重要更改，均在脚注中注明。这部著作的章节是按“新莱茵报”发表时的样子划分的。——第473页。","language":"中文","translation":false},{"id":"wage-labour-1-145","author":"马克思","title":"雇佣劳动与资本","location":"雇佣劳动与资本（卡·马克思，1847年著，1849年发表）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/mia-chinese-marx-1847-1849.htm","text":"[299] 正如恩格斯在其为1891年版写的序言中所指出的，“这部著作在报纸上尚未载完；在第269号的文章末尾曾刊有‘待续’的字样，但这个诺言未能履行，因为当时爆发的事变——俄国人侵入匈牙利，德勒斯顿、伊塞隆、爱北斐特、普法尔茨和巴登等地举行了起义——使该报本身停止出版”。——第506页。","language":"中文","translation":false},{"id":"wages-price-1-1","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"中文马克思主义文库 -> 马克思","language":"中文","translation":false},{"id":"wages-price-1-2","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"2．﹝生产、工资、利润﹞","language":"中文","translation":false},{"id":"wages-price-1-3","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"10．利润是按照商品的价值出卖商品获得的","language":"中文","translation":false},{"id":"wages-price-1-4","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"11．剩余价值分解成的各个部分","language":"中文","translation":false},{"id":"wages-price-1-5","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"12．利润、工资和价格的一般关系","language":"中文","translation":false},{"id":"wages-price-1-6","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"13．争取提高工资或反对降低工资的一些最重要场合","language":"中文","translation":false},{"id":"wages-price-1-7","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"14．资本和劳动的斗争及其结果","language":"中文","translation":false},{"id":"wages-price-1-8","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"公民们！在讨论这个问题以前，允许我先说几句开场白。","language":"中文","translation":false},{"id":"wages-price-1-9","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"目前大陆上有一种真正的罢工流行病，闹着要求增加工资。这个问题将在我们的大会上讨论。你们是国际协会的领导，对这个极重要的问题应当有确定的见解。因此，我认为有责任把这个问题彻底分析一下，甚至不怕引起你们的不耐烦。","language":"中文","translation":false},{"id":"wages-price-1-10","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我要预先说明的另一点，是关于公民韦斯顿。他不仅向你们提出一些他明知不受工人阶级欢迎的观点，而且公开为之辩护，还自以为是在维护工人阶级的利益。这种表现为道义上的勇气，我们每个人都应该深表尊敬。尽管我这篇报告措辞直率，我希望，在报告结束后，公民韦斯顿将会发现，我同意的是在我看来正是构成他的论点基础的那种思想，不过我不得不认为，这些论点就其现有的形式来讲，在理论上是错误的，在实践中是危险的。","language":"中文","translation":false},{"id":"wages-price-1-11","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"公民韦斯顿的论证，实际上是根据两个前提：","language":"中文","translation":false},{"id":"wages-price-1-12","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"首先，国民产品量是固定不变的，或者像数学家所说的，是一个常量或常数；","language":"中文","translation":false},{"id":"wages-price-1-13","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"其次，实际工资总额，也就是说，按照能够用以购买的商品的数量来测定的工资总额，是一个不变额，一个常数。","language":"中文","translation":false},{"id":"wages-price-1-14","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"他的前一个论断显然是错误的。你们可以看到，产品的价值和数量在逐年增加，国民劳动的生产力在逐年扩大，而用来流通这种日益增加的产品所必需的货币数量也在不断变化。对全年或对相互比较的各个不同年度来说是如此，对一年中平均的每一天来说也是如此。国民产品的数或量总是在不断变化。它不是一个常数，而是一个变量，姑且不论人口的变化，它也必然如此，因为资本积累和劳动生产力总是在不断地变化。的确，一旦工资水平普遍提高了，这种提高本身，无论其后果如何，决不会立即改变产品量。这种提高最初可能是由于当时的实际情况。但是，如果在工资提高之前，国民产品是一个变量而不是一个常数，那么，在工资提高之后，它仍然是一个变量而不是一个常数。","language":"中文","translation":false},{"id":"wages-price-1-15","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是，假定说，国民产品量不是变量，而是常数。即使如此，我们的朋友韦斯顿当做逻辑结论的东西，也只是一种武断。如果我们有一个已知数，比如说是8，那么这个数的绝对界限并不妨碍它的各部分改变其相对界限。如果利润为6，工资为2，那么工资可能增加至6，利润减少至2，而总数仍然是8。因此，产品量的固定不变，无论如何也不能证明工资总额也是固定不变的。那么，我们的朋友韦斯顿究竟怎样证明工资总额是固定不变的呢？不过是武断而已。","language":"中文","translation":false},{"id":"wages-price-1-16","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是，即使同意他的论断，那么它也应当在两方面都说得通，然而公民韦斯顿却使它只能说明一个方面。如果工资总额是一个常数，它就既不能增加，也不能减少。因此，如果说工人争取暂时增加工资，是很愚蠢，那么资本家争取暂时降低工资，也很愚蠢。我们的朋友韦斯顿并不否认，在一定的情况下，工人能够迫使资本家增加工资，但是，他觉得工资总额是天然固定不变的，工资增加后必然会有一个反作用。另一方面，他也知道资本家能够压低工资，而且确实经常想压低它。依照工资不变的原则，在这种场合，也应当像在前一种场合一样，随后有一个反作用。所以，工人对降低工资的企图，或者，对工资已经降低的现象进行反抗，是正确的。所以，他们力求增加工资，也是正确的，因为任何一种反抗降低工资的行动都是一种争取增加工资的行动。依照公民韦斯顿的工资不变原则，工人也应当在一定情况下联合起来，为增加工资而斗争。","language":"中文","translation":false},{"id":"wages-price-1-17","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果他否认这个结论，他就必须放弃那个所以得出这个结论的前提。他就不该说工资总额是一个常数，而应该说工资总额尽管不能而且不该提高，但是它随时可能而且应该降低，只要是资本家想把它降低。如果资本家想给你们吃的是马铃薯而不是肉，是燕麦而不是小麦，你们也必须接受他的愿望，当作政治经济学的一条规律而唯命是从。如果一个国家的工资水平比另一个国家的高，例如美国的比英国的高，你们就应当以美国资本家的愿望和英国资本家的愿望的不同来解释这种工资水平的不同，这个方法看来不仅会简化对经济现象的研究工作，而且也会简化对其他一切现象的研究工作。","language":"中文","translation":false},{"id":"wages-price-1-18","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"不过，即使如此，我们也可以问：为什么美国资本家的愿望不同于英国资本家的愿望？为了回答这个问题，就得超出愿望的范围。一个牧师会说：上帝愿意法国是一个样，愿意英国是另一个样。如果我要求他解释这种愿望的两重性，他会厚颜无耻地回答，上帝愿意在法国抱一种愿望，在英国抱另一种愿望。但是，我们的朋友韦斯顿当然决不会去作这种完全否定一切推理的论证。","language":"中文","translation":false},{"id":"wages-price-1-19","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"诚然，资本家的愿望是获取尽量多的东西。但是，我们的任务不是要谈论他的愿望，而是要研究他的力量。研究那股力量的界限以及那些界限的性质。","language":"中文","translation":false},{"id":"wages-price-1-20","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"2．﹝生产、工资、利润﹞","language":"中文","translation":false},{"id":"wages-price-1-21","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"公民韦斯顿向我们作的演说，三言两语就可以说清楚了。","language":"中文","translation":false},{"id":"wages-price-1-22","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"他的全部推论归结如下：如果工人阶级强迫资本家阶级以货币工资形式付5先令，而不是4先令，那么，资本家以商品形式归还的，将会是值4先令的东西，而不是值5先令的东西。工人阶级就不得不用5先令去买在工资增加之前用4先令就能买到的东西。为什么会这样呢？为什么资本家把只值4先令的东西要卖5先令呢？因为工资额是固定不变的。但是为什么工资被固定在值4先令的商品上？为什么不是值3或2先令，或其它数目的商品上呢？如果工资额的界限是由一条既不依资本家的愿望又不依工人的愿望为转移的经济规律决定的，公民韦斯顿就应当首先阐述这条规律，并加以证明。其次，他还应当证明，在每一定的时期内，实际上所支付的工资额，总是完全符合必要的工资额而决不能违背它。另一方面，如果工资额的一定界限只是取决于资本家的愿望或取决于他的贪欲的界限，这种界限就是随意的，没有什么必然性，可以依照资本家的愿望而改变，因此也可以违反他的愿望而改变。","language":"中文","translation":false},{"id":"wages-price-1-23","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"公民韦斯顿对他的理论是这样解释的：有一个盆盛着一定量的汤，供一定数量的人分食，这一定量的汤决不会因为汤匙子的增大而增多。真让人觉得这个例子未免有点笨拙。这使我想起梅涅尼·阿格利巴用过的一个比喻。当罗马平民反抗罗马贵族时，贵族阿格利巴对他们说，贵族的胃养活着国家躯体上的平民的四肢。阿格利巴却没能证明，填满一个人的胃就可以养活另一个人的四肢。公民韦斯顿想必忘记了，在工人们喝汤的那个汤盆里盛着国民劳动的全部产品，他们不能舀出更多的汤，既不是因为汤盆的容量小，也不是因为汤盆里盛的东西少，只因为他们的汤匙太小了。","language":"中文","translation":false},{"id":"wages-price-1-24","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"资本家用什么诡计能把只值4先令的东西卖5先令呢？就是靠抬高他出卖的商品的价格。那么，商品价格的提高，或者，更广泛些说，商品价格的变动，以及商品价格本身，是否仅仅取决于资本家的愿望呢？或者相反，是否需要一定的条件才能实现这个愿望呢？如果不需要，那么市场价格的涨落及其不断的变动，就成为一个不可解答的谜了。","language":"中文","translation":false},{"id":"wages-price-1-25","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"既然我们假定，在劳动生产力中，在所使用的资本和劳动的数量中，在估量产品价值的货币价值中，都没有变化，而变化的只是工资水平，那么这种工资的提高怎样能够影响商品的价格呢？只要能影响这些商品的实际供求关系，就能影响商品的价格。","language":"中文","translation":false},{"id":"wages-price-1-26","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"的确，整个来说，工人阶级总是把自己的收入耗费在并且不得不耗费在生活必需品上。所以工资水平的普遍提高总要引起对生活必需品的需求的提高，从而引起生活必需品市场价格的提高。生产这些必需品的资本家支付的工资提高了，就靠提高他们的商品的市场价格来求得补偿。但是那些不生产生活必需品的资本家又怎样呢？决不要以为他们人数很少。你们仔细想一下，国民产品的三分之二被五分之一的人口消费掉了，──最近一位下院议员说只被七分之一的人口消费掉了，──那你们就会知道，该有多么大的一批国民产品要作为奢侈品来生产或用来交换奢侈品，该有多么大量的生活必需品要浪费在豢养仆役、马匹、猫等等上面；我们凭经验知道，这种浪费，随着生活必需品价格的提高，总是要大受限制的。","language":"中文","translation":false},{"id":"wages-price-1-27","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"那么，那些不生产生活必需品的资本家的处境究竟会怎样呢？工资的普遍提高必然引起利润率的下降，他们不可能靠提高自己商品的价格来求得补偿，因为对这些商品的需求是不会增加的。他们的收入会减少，从这种已经减少的收入中，他们不得不支付更多的钱才能买到同样数量的高价的生活必需品。不仅如此。他们的收入减少了，就不得不缩减用于奢侈品的支出，因此他们彼此对于各自商品的需求也要缩减。需求额缩减了，他们的商品的价格就会降低。所以在这些工业部门中，利润率就会下降，不仅与工资水平的普遍提高成比例，而且与工资的普遍提高、必需品价格的上升和奢侈品价格的下降都成比例。","language":"中文","translation":false},{"id":"wages-price-1-28","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"对于投在各个不同工业部门中的那些资本来说，这种利润率的差别会有什么样的后果呢？当然，其后果也同各个生产部门中的平均利润率因某种原因而产生差别时一样。资本和劳动就会从获利较少的部门转移到获利较多的部门，这种转移过程，一直要延续下去，直到一些工业部门的供给量上升到符合于增长了的需求量，而其它工业部门的供给量下降到符合于缩减了的需求量时才会停止。经过这种变化，一般利润率才会在各个工业部门中重新平均化。整个这种转变，最初只是起因于各种商品供求关系的变动，这个原因一旦消失，它的作用就会停止，价格就会回到原来的水平和平衡状态。因工资提高而引起的利润率的下降，不会局限于某些工业部门，一定会成为普遍的现象。按照我们的假定，劳动生产力没有变化，产品总量也没有变化，只是这一定量的产品会改变自己的形式。大部分产品将以生活必需品的形式存在，小部分产品将以奢侈品的形式存在，或者，结果一样，小部分产品将用来交换外国奢侈品并以其原来的形式消费掉；或者，结果也一样，大部分本国产品将用来交换外国的生活必需品，而不是奢侈品，因此工资水平的普遍提高，在市场价格暂时混乱之后，只会引起利润率的普遍下降，不会引起商品价格稍许长期的变动。","language":"中文","translation":false},{"id":"wages-price-1-29","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果有人说，在上述论证中，我假定全部工资增加数都花费在生活必需品上，我就回答，我作的这个假定是最有利于公民韦斯顿的观点的。如果工资增加数花费在从前不是工人们消费的物品上，那么，他们的购买力的实际提高就无需证明了。可是，他们购买力的提高只是由于工资的增加，这种提高就应该恰巧相当于资本家购买力的降低。因此，对商品的总需求量不会增加，但是这种需求的各个构成部分可能会改变。一方增加的需求会被另一方减少的需求抵销。总的需求量因此仍旧不变，商品的市场价格无论如何也不会变动。","language":"中文","translation":false},{"id":"wages-price-1-30","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"因此必须二者择一：或者是工资增加数均等地耗费于一切消费品，于是工人阶级方面的需求的扩大就该由资本家阶级方面的需求的缩减来抵偿；或者是工资增加数只耗费于某几种市场价格将暂时上涨的物品。这样，一些工业部门的利润率的必然上升，以及另一些工业部门的利润率的必然下降，就会引起资本和劳动分配上的变化，这种变化必将继续下去，直到供给量在一些工业部门中增加到符合于增长的需求量，在另一些工业部门中降低到符合于减少的需求量时为止。在前一种假定下，商品的价格不会发生变动。在后一种假定下，商品的交换价值经过市场价格的某些波动之后，又会降到原先的水平。在这两种假定下，工资水平的普遍提高，终究不会引起任何别的后果，只会引起利润率的普遍下降。","language":"中文","translation":false},{"id":"wages-price-1-31","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"为了唤起你们的想象力，公民韦斯顿要求你们想一想，英国农业工人的工资普遍从9先令增加到18先令，会引起哪些困难。他大声疾呼，请想一想生活必需品需求的大量增加和接踵而来的价格的惊人上涨吧。当然你们都知道，美国农业工人的平均工资比英国农业工人的平均工资多一倍以上，虽然美国农产品的价格比英国低，虽然美国的资本与劳动的整个关系同英国一样，虽然美国产品的年产量比英国少得多。我们的朋友为什么要敲警钟呢？只不过是为了回避我们面临的实际问题罢了。工资忽然从9先令增加到18先令，就是说工资忽然增加了100％。不过，我们现在决不是要讨论英国普遍的工资水平能不能突然提高100％的问题。我们完全不必讨论提高的数量，它在每一个具体场合下，都应该取决于并适应于一定的情况。我们只想弄清楚，工资水平的普遍提高，即使超不过1100，将会产生什么样的后果。","language":"中文","translation":false},{"id":"wages-price-1-32","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"姑且不谈我们的朋友韦斯顿关于工资提高100％的幻想，我想请你们注意英国在1849年至1859年时期确实提高过工资。你们都知道1848年实行的十小时工作日法案，更确切地说，十小时半工作日法案。这是我们亲眼见过的重大的经济改革之一。这是一次突然和强制性的提高工资，并不是发生在某些地方行业中，而是发生在英国赖以统治世界市场的那些主要工业部门中。这是在特别不利情况下的提高工资。尤尔博士、西尼耳教授以及资产阶级经济学的其它所有的官方发言人都曾证明──我应该指出，他们的论据比我们的朋友韦斯顿的更有力──这是为英国工业敲丧钟。他们证明说，问题不在于简单的工资增加，而在于这种工资的增加起因于并依据于所使用的劳动量的减少。他们断言，人们想从资本家手里夺去的第十二小时，正好是资本家赖以获得利润的唯一的一个小时。他们危言耸听，说这会使积累减少，价格提高，市场丧失，生产缩小，从而引起工资降低，弄得彻底破产。他们甚至声称，马克西米利安·罗伯斯比尔的最大限度法令与这个法案相比就微不足道了；在某种意义上他们说得有理。但是，结果怎样呢？结果是：尽管工作日缩短，工厂工人的货币工资却提高了；工厂的在业工人数目大大增加了；工厂产品的价格不断降低了；工厂工人的劳动生产力惊人地发展了；工厂产品的销售市场空前地扩大了。1861年在曼彻斯特科学促进协会的会议上，我亲自听到纽曼先生承认，他本人、尤尔博士、西尼耳以及经济科学的其它所有的官方人士都错了，而人民的直觉是正确的。我说的不是弗兰西斯·纽曼教授，而是威廉·纽曼先生，因为他在经济科学中占有重要的地位，是托马斯·图克先生的《价格史》一书的合著者和出版者，这是一部追溯了1793年至1856年的价格史的佳作。如果我们的朋友韦斯顿的固定不变的观念，即关于不变的工资总额，不变的产品量，不变的劳动生产力水平，不变的资本家的愿望，以及他的其它各种固定不变论和最终完成论都是正确的，那么西尼耳教授的悲观的预言也将是正确的，而早在1815年就宣布普遍限制工作日是解放工人阶级的第一个准备步骤、不惜违反一般人的成见独自在新拉纳克的棉织工厂里真正予以实行的罗伯特·欧文却是错了。","language":"中文","translation":false},{"id":"wages-price-1-33","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"在十小时法案颁布实行并从而引起工资提高的时候，在大不列颠，由于某些不必在此列举的原因，曾有过一次农业工人工资的普遍提高。","language":"中文","translation":false},{"id":"wages-price-1-34","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"虽然这不是我的直接目的所要求的，为了不使你们误会，我要在这里预先说明几句。","language":"中文","translation":false},{"id":"wages-price-1-35","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果一个人每星期的工资是2先令，后来他的工资提高到4先令，那么工资水平就提高了100％。若从工资水平的提高来看，这可以说是很了不起的，尽管实际的工资数额，每星期4先令，仍然少得可怜，难以温饱。所以不应当陶醉于动听的工资水平提高的百分比。必须经常问：原来的工资数是多少？","language":"中文","translation":false},{"id":"wages-price-1-36","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"其次，不难理解，如果10个人每星期各得2先令，5个人每星期各得5先令，还有5个人每星期各得11先令，这20个人每星期总共收入100先令或5英镑。如果后来他们每星期的工资总数有了增加，假定为20％，那就是从5英镑增加到了6英镑。就平均数来看，可以说工资的总的水平增加了20％，尽管实际上其中10个人的工资并没有变，5个人的工资每人从5先令增加到6先令，另外5个人的工资总额则从55先令增加到70先令。其中半数人的状况丝毫没有改善，14的人稍有改善，只有剩下的14的人，才真正有所改善。然而，再以平均数来计算，这20个人的工资总数是增加了20％，就雇用他们的全部资本而论，就他们所生产的商品的价格而论，就仍然好像他们真的均等地分享了工资的平均增长额。在关于那些农业工人的例子中，英格兰和苏格兰各个郡的工资水平极不相同，所以工资的提高对他们的影响也很不平衡。","language":"中文","translation":false},{"id":"wages-price-1-37","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"最后，在这次工资提高的时期，有些事起了抵销作用，例如对俄战争引起的新的税赋，农业工人住宅的大批毁坏，等等。我就先说这么多，现在就来谈大不列颠农业工人工资的平均水平在1849年至1859年时期大约提高了40％这件事。我可以举出大量的详细材料来证明我的论述，但是，就当前的目的来说，我认为只要请你们去看一看已故约翰·查·摩尔顿先生1859年在伦敦艺术和手工业协会宣读的《用在农业中的力量》那篇诚实的批判性的报告，也就够了。摩尔顿先生引用的材料，是从苏格兰12个郡和英格兰35个郡内大约100个农场主的账簿和其它真实文据中搜集的。","language":"中文","translation":false},{"id":"wages-price-1-38","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"按照我们的朋友韦斯顿的意见，再加上工厂工人工资的同时提高，农产品的价格在1849─1859年间应该有惊人的上涨。但实际情况怎样呢？虽然发生了对俄战争，1854─1856年又连续歉收，英国主要农产品小麦的平均价却从1838─1848年的每一夸特约3英镑，降到1849─1859年的每一夸特约2英镑10先令。这就是说，在农业工人的平均工资提高40％的同时，小麦的价格降低了16％以上。在同一时期，如果把末期同初期，即1859年同1849年比较一下，正式登记的贫民已从934419人减到860470人，即减少了73949人。我承认，减少的数目确实很小，而在以后几年又未见减少，但毕竟是减少了。","language":"中文","translation":false},{"id":"wages-price-1-39","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"有人会说，由于废除了谷物法，1849─1859年外国谷物的进口比1838─1848年增加一倍以上。结果怎样呢？根据公民韦斯顿的观点，国外市场上发生这样突然的、巨大的和不断增长的需求，一定会使农产品的价格猛涨，这种增长的需求无论是发生在国外或者是国内，影响都是相同的。实际情形又是怎样呢？除了几个歉收的年份，法国在这段时期，粮价惨跌已成为人们的经常话题，美国人不得不屡次焚毁他们多余的产品，而俄国，如果相信乌尔卡尔特先生的话，则鼓励了美国的内战，因为美国佬在欧洲市场上的竞争破坏了俄国农产品的输出。","language":"中文","translation":false},{"id":"wages-price-1-40","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果把公民韦斯顿的论证化为抽象的形式，就是：需求的任何提高，总是在一定的产品量的基础上发生的。因此，需求的提高决不能增加所需的各种商品的供给，只能抬高这些商品的货币价格。可是，最普通的观察也可以表明，需求的提高有时会使商品的市场价格完全不变，有时也会引起市场价格的暂时提高，接着就是供给的增加，接着就是价格再降到原先的水平，多半低于原先的水平。至于需求的提高是由于工资的增加还是由于其它什么原因，这丝毫不能改变这个问题的条件。从公民韦斯顿的观点来看，解释一般的现象，和解释在工资提高这个特别情况下所发生的现象，同样是困难的。所以，他的论证对于我们所讨论的问题是毫无特殊意义的，只不过表明他不知道怎样解释这个规律：需求的提高引起供给的增加，而不一定会引起市场价格的上涨。","language":"中文","translation":false},{"id":"wages-price-1-41","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"在讨论的第二天，我们的朋友韦斯顿把他的旧主张披上了新形式。他说：由于货币工资的普遍提高，将需要更多的通货来支付这些工资。通货的数量既然固定不变，那又怎么能用这种固定不变的通货来支付增加了的货币工资呢？以前的困难是：工人的货币工资尽管增加而工人所得到的商品数量仍然固定不变；现在的困难是：商品的数量尽管固定不变而货币工资却增加了。当然，如果你们不承认他的原先的教条，他那相应产生的难题也就消灭了。","language":"中文","translation":false},{"id":"wages-price-1-42","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"可是我要说明，这个通货问题和我们面临的问题毫无关系。","language":"中文","translation":false},{"id":"wages-price-1-43","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"在你们的国家，支付机制比在欧洲任何国家完善得多。由于有了广泛的、集中的银行系统，只需要少量的通货，就能周转同等数目的价值，就能办理同等的或数量更大的交易。例如，在工资方面，英国工厂工人每星期把自己的工资付给商店老板，商店老板每星期把这些钱送交银行家，银行家每星期把这些钱交还工厂主，工厂主再把这些钱付给自己的工人，如此循环不已。由于有这套机制，一个工人的年工资假定为52英镑，只要用一个索维林，就这样每星期周转一次，便可支付了。但是，这种机制即使在英格兰，也不如在苏格兰那样完善；并且并不是到处都一样完善的，所以我们看到，例如有些农业区域，与纯工业区域相比，却需要更多的通货才能周转少得多的价值额。","language":"中文","translation":false},{"id":"wages-price-1-44","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"你们如果渡过海峡，就可以看到，那里的货币工资比英国的低得多，然而在德国、意大利、瑞士和法国，这些工资是用大量的通货额来周转的。每一个索维林不能那样快地被银行家取得，或者回到工业资本家的手中，所以，在英国，一个索维林就能周转一年的52英镑，在大陆上，你也许需要3个索维林才能周转25英镑的年工资。因此，把大陆各国和英国相比较，可以立刻看出，低额的货币工资可能比高额的货币工资需要更多的通货来周转，这实际上纯粹是一个技术问题，与我们的问题毫不相干。","language":"中文","translation":false},{"id":"wages-price-1-45","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"据我知道的最确切的计算，英国工人阶级的年收入估计为25000万英镑。这个庞大的数目大约是用300万英镑来周转的。假定工资增加50％，需要的通货就不是300万英镑，而是450万英镑了。工人的每日开支，有很大一部分用的是银币和铜币，即普通的铸币，这些铸币对于金子的相对价值，和不能兑换的纸币一样，是由法律任意规定的；那么，货币工资提高50％，至多只需要补充100万索维林进入流通。以金条或铸币形式躺在英格兰银行或私人银行家金库里的100万英镑就会进入流通。然而补充的通货势必会有一些磨损，这100万的补充铸币或补充磨损所引起的少量费用甚至可以节省下来，也确实会节省下来。你们都知道，英国的通货分为两大类：一类是各种银行券，用于商人之间的交易和消费者与商人之间的大宗支付。另一类是金属铸币，在零售贸易中流通。这两种通货，虽然种类不同，却是交错使用的。例如，甚至在大宗支付中，5英镑以下的零数大半是用金币流通的。如果明天发行4英镑、3英镑、或2英镑的银行券，这些流通渠道中的金币就会立刻被挤出，流到那些因货币工资增加而需要它们的地方。这样一来，因货币工资增加50％所需要补充的100万，不增加一个索维林也可以填补了。增加票据流通而不另发银行券也可以产生同样的效果，例如在兰开夏郡，这个方法就实行了很久。","language":"中文","translation":false},{"id":"wages-price-1-46","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果工资水平的普遍提高，像公民韦斯顿对农业工人工资所假设的那样增加100％，会引起生活必需品价格的大幅度上涨，并且，依照他的见解，需要补充一批得不到的通货，那么，工资的普遍下降，就会在同样的程度上，不过是在相反的方向，引起同样的后果。好啦！你们都知道，1858─1860年是棉纺织工业最繁荣的时期，特别是1860年在这方面是商业史上空前未有的一年，其它一切工业部门这时也很兴旺。1860年，棉纺工人以及与他们这一行业有关的其它工人的工资，比过去任何时候都高。美国危机发生后，那些工人的工资忽然降到大约相当于过去数目的1∕4。反过来，那就是增加了300％。如果工资从5提高到20，我们便说工资增加了300％；如果工资从20降到5，我们便说工资减少了75％。但是在一方面增加的数目和在另一方面减少的数目是相同的，即15先令。所以，这是工资水平的一种突然的、从未有过的变动，如果我们不仅计算那些直接在棉纺织工业中做工的工人，而且还计算那些间接依靠于棉纺织工业的工人，那么这种变动所涉及的工人数目，就要比农业工人的数目多1∕2。小麦的价格降低了吗？没有，它已由1858─1860年这三年中每一夸特年平均价格47先令8便士提高到1861─1863年这三年中每一夸特年平均价格55先令10便士。至于通货，1861年造币厂铸造了8673232英镑，而1860年只有3378102英镑。换句话说，1861年比1860年多铸造了5295130英镑。当然，1861年流通的银行券比1860年少了1319000英镑。现在减去这个数目，1861年的通货与1860年这个繁荣年度相比，仍然多出3976130英镑，大约多了400万英镑；但是英格兰银行的黄金储备已经减少了，虽然不是以完全相同的比例却是以近似的比例减少了。","language":"中文","translation":false},{"id":"wages-price-1-47","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"现在把1862年和1842年比较一下。1862年，流通中的商品的价值和数量有极大的增加，除此以外，单是对英格兰和威尔士的铁路定期支付的股票、债券等等的资本就达32000万英镑，这个数目如在1842年当然会令人难以置信。然而，1862和1842年的通货的总额仍然是几乎相等的，你们还可以看出，不仅商品的价值，而且一般货币交易的价值在大量增加时，通货反而趋于递减。从我们的朋友韦斯顿的观点看来，这就是一个不可解答的谜了。","language":"中文","translation":false},{"id":"wages-price-1-48","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"他要是对这个问题比较深入地考察一下，就会发现：姑且不谈工资并假定它固定不变，流通中的商品的价值和数量以及通常要结算的货币交易的数额是每天变化的；银行券的发行量是每天变化的；不以货币为中介而借助汇票、支票、转账信贷和票据交换所而实现的支付数额是每天变化的；由于需要实在的金属通货，市面上流通的铸币与储存或躺在银行金库中的铸币和金条的比例是每天变化的；国内流通所吸收的金条数量和送出国外供国际流通的金条数量是每天变化的；那他就会知道：他的通货总额固定不变的教条，是一个与日常生活相矛盾的极大的错误。他就会去研究使货币流通能适应不断变化的条件的那些规律，而不致把他对货币流通规律的无知变成反对提高工资的论据了。","language":"中文","translation":false},{"id":"wages-price-1-49","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们的朋友韦斯顿确信一句拉丁谚语：repetitio est materstudiorum，即复习是学业之母，所以他再次用新的方式来重述他原来的教条：因工资提高而引起的通货紧缩一定会使资本减少，等等。我已经讲过他的关于通货的奇谈怪论，我认为，完全不必再来讨论他的那些根据他想象的通货灾难所幻想出来的想象的后果了。我现在就把他用多种不同形式反复陈述的同一个教条，归结为它的最简单的理论形式。","language":"中文","translation":false},{"id":"wages-price-1-50","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"他论述他的命题的方法是非批判的，只要指出一点就可以看得很清楚。他反对提高工资，或者，反对因工资的提高而产生的高工资。现在我要问他：究竟什么是高工资，什么是低工资？例如，为什么每星期5先令就是低工资，每星期20先令就是高工资？如果说5与20相比算是低工资，那么20与200相比就更低了。如果某人作关于寒暑表的讲演，一开始就谈高温度和低温度，那决不能给人传授任何知识。他首先应该谈冰点和沸点是怎样确定的，应该谈这两个标准点是由自然规律决定的，并不是由出售或制造寒暑表的人随便规定的。然而公民韦斯顿在谈到工资和利润的时候，不仅没有从经济规律中推演出这样的标准点，甚至不觉得有注意它们的必要。显然，工资只有和一种测量其数量的标准相比较才能够谈高或低，但他却满足于承认高低这种流行的庸词俗语，以为这是有一定意义的。","language":"中文","translation":false},{"id":"wages-price-1-51","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"他不能向我说明，为什么对一定量的劳动要付以一定量的货币。如果他回答说，这是由供求规律决定的，我首先就要问他，供给和需求本身又是由什么规律调节的呢？于是，他那样回答就会立刻使人不屑一顾。劳动的供求关系总是在不断变化，随着这种变化，劳动的市场价格也在不断变化。需求超过供给，工资就上涨；供给超过需求，工资就下降，尽管在这种情形下，可能仍有必要采用例如罢工或别的方法来探测需求和供给的实际情况。但是，如果你们承认供给和需求是调节工资的规律，那么毅然反对提高工资，就未免幼稚无益了，因为按照你们所凭借的至高无上的规律，工资的周期性的上涨，也和工资的周期性的下降一样，是必然的和正常的。你们要是不承认供给和需求是调节工资的规律，我就再提出这个问题：为什么对一定量的劳动要付以一定量的货币呢？","language":"中文","translation":false},{"id":"wages-price-1-52","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"还是把这个问题考虑得更广一些：你们如果以为劳动和任何一种商品的价值归根到底是由供给和需求决定的，那就完全错了。供给和需求只调节市场价格一时的变动。供给和需求可以说明为什么一种商品的市场价格会涨到它的价值以上或降到它的价值以下，但决不能说明这个价值本身。假定说，供给和需求是相互平衡的，或如经济学者所说，是相互一致的。当这两个相反的力量相等时，它们就相互牵制，彼此都不向对方发生作用。当供给和需求相互平衡因而停止发生作用时，商品的市场价格就符合它的实际价值，就符合市场价格随之变动的那个标准价格。所以在研究这个价值的本质时，我们完全不必讨论供给和需求对市场价格的一时的影响。这对于工资或其它一切商品的价格来说，都是一样的。","language":"中文","translation":false},{"id":"wages-price-1-53","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们的朋友的一切论据，如果化为最简单的理论形式，就是这样一个教条：“商品的价格是由工资决定或调节的。”","language":"中文","translation":false},{"id":"wages-price-1-54","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我可以用实际的经验来驳斥这种已被驳倒的陈腐谬论。我可以告诉你们，英国工厂工人、矿工、造船工人等等的劳动的价格比较高，但他们的产品比其它国家的同类产品卖得便宜；可是，英国农业工人的劳动价格就比较低，但他们的产品几乎比其它任何一个国家的同类产品都卖得贵。比较一下同一个国家的不同产品或不同国家的各种商品，我可以指出，除了一些与其说是本质上的不如说是表面上的例外，平均说来，高价的劳动生产低价的商品，而低价的劳动生产高价的商品。当然，这种现象不能证明一种场合下的高价劳动和另一种场合下的低价劳动都是造成那些正好相反结果的各自原因，但总能证明商品的价格不是由劳动的价格决定的。不过我们完全不必采用这种经验主义的方法。","language":"中文","translation":false},{"id":"wages-price-1-55","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"也许有人会否认公民韦斯顿曾提出过“商品的价格是由工资决定或调节的”这个教条。的确，他从来没有使它公式化。相反地，他曾说，利润和地租也是商品价格的构成部分，因为不仅工人的工资，而且资本家的利润和土地所有者的地租，也非从商品的价格中支付不可。但是，照他的意见，价格是怎样构成的呢？首先是由工资构成的。然后再为资本家加上百分之几，为土地所有者加上百分之几。现在假定，生产一种商品时所费的劳动的工资为10；如果利润率与支出的工资相比是100％，资本家就要加上10；如果地租率与工资相比也是100％，就要再加上10；于是商品的全部价格就是30。但是，这样决定价格不过意味着价格是由工资决定罢了。如果在上述场合，工资涨到20，那么商品的价格就要涨到60，其余类推。因此，提出价值由工资来调节的这一教条的所有老朽的政治经济学作家们，都是说利润和地租不过是加在工资上的百分之几，借以证明这个教条是正确的。当然，他们中间没有一个人能把这些百分之几的限度归结为一种经济规律。相反地，他们似乎以为利润是由传统、习惯和资本家的愿望决定的，或者是由别种同样武断的和莫名其妙的方式决定的。如果他们说利润决定于资本家之间的竞争，这等于什么也没有说。这种竞争的确会拉平不同行业的不同利润率，把这些利润率引到一个平均的水平，但决不能决定这个水平本身或一般利润率。","language":"中文","translation":false},{"id":"wages-price-1-56","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们说商品的价格是由工资决定的，这是什么意思呢？既然工资是劳动价格的一种称呼，就是说，商品的价格是由劳动的价格来调节的。既然“价格”是交换价值，──我说的价值都是指交换价值，──即用货币来表现的交换价值，于是这一原理就归结为“商品的价值是由劳动的价值决定的”，或“劳动的价值是价值的一般尺度”。","language":"中文","translation":false},{"id":"wages-price-1-57","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是，“劳动的价值”本身又是怎样决定的呢？这就使我们为难了，当然要为难，因为我们总是想依照逻辑来推论。可是，这个教条的维护者是很少从逻辑上考虑的。就以我们的朋友韦斯顿来说吧。起初他告诉我们，工资规定商品的价格，所以，工资增加了，价格也要提高。随后他又反过来向我们证明，增加工资没有什么好处，因为商品的价格也要随之提高，因为工资实际上是由工资所能买来的那些商品的价格来测量的。总之，我们在开始时说商品的价值由劳动的价值来决定，在结尾时却又说劳动的价值由商品的价值来决定了。我们真是在瞎兜圈子，始终得不出结论。","language":"中文","translation":false},{"id":"wages-price-1-58","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"总之，我们把一种商品的价值，例如劳动、谷物或其它商品的价值作为价值的一般尺度和调节器，显然，我们只是躲避了困难，因为我们决定一种价值，用的是其本身又需要被决定的另一种价值。","language":"中文","translation":false},{"id":"wages-price-1-59","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"“工资决定商品的价格”这一教条，用它的最抽象的说法来表示，就是“价值是由价值决定的”，这种同义反复只表明我们实际上对价值一窍不通。要是接受这个前提，有关政治经济学一般规律的全部推论就都变成空洞的呓语了。所以，李嘉图的伟大功绩就在于他在1817年出版的《政治经济学原理》中，彻底粉碎了“工资决定价格”这个流行已久的陈腐不堪的谬论，这个谬论已被亚当·斯密和他的法国前辈们在自己著作的真正科学的部分中驳斥了，但是又被他们在其著作的比较肤浅和庸俗的章节里再现出来。","language":"中文","translation":false},{"id":"wages-price-1-60","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"公民们，讲到这里，现在我必须进一步实际地阐明这个问题了。我不能保证一定能令人很满意，因为这样做，我就不能不涉及政治经济学的全部领域。我只能像法国人所说的“effleurer la question”，即只涉及一些基本问题。","language":"中文","translation":false},{"id":"wages-price-1-61","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们要提的第一个问题是：什么是商品的价值？它是怎样决定的？","language":"中文","translation":false},{"id":"wages-price-1-62","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"乍一看，似乎商品的价值是一种完全相对的东西，如果不研究某一个商品和其它一切商品的关系，就不能确定它的价值。其实，讲到价值，讲到某一个商品的交换价值，我们指的是这一个商品与其它一切商品交换时的比例量。但是这时又发生一个问题：商品相互交换的比例是怎样决定的呢？","language":"中文","translation":false},{"id":"wages-price-1-63","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们根据经验知道，这些比例有无限的差别。就以一种商品例如小麦来说，我们将会发现，一夸特小麦同其它各种商品交换，几乎有无数不同的比例。但是，小麦的价值无论是用丝绸、黄金还是用其它某种商品表现出来，都依然是一样的，它必定是一种与各种商品交换的各种交换率显然不同而且毫不相干的东西。一定能用一种极不同的形式来表现不同商品间的这些不同的等式。","language":"中文","translation":false},{"id":"wages-price-1-64","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"假如我说一夸特小麦按一定的比例与铁交换，或者说一夸特小麦的价值表现为一定数量的铁，那就是说，小麦的价值和它那个表现为铁的等价物等于某个第三种东西，既不是小麦又不是铁，因为我假定小麦和铁是以两种不同的形态来表现这同一数量的。所以，这两种商品中的每一种，不论是小麦或铁，都一定能不依赖于另一种而化成这个第三种东西，即化成作为它们的共同尺度的东西。","language":"中文","translation":false},{"id":"wages-price-1-65","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"为了说明这一点，我举一个十分简单的几何学的例子。在比较形状不同和大小不同的三角形面积，或者比较三角形与矩形或其它某种多边形时，我们将怎样着手呢？我们把任何一个三角形的面积还原为一种与它的外形完全不同的形式。既然根据三角形的特性知道它的面积等于它的底边和高相乘的一半，我们就能比较各种三角形的大小以及一切多边形的大小，因为每一种多边形都可以分解为一定数量的三角形。","language":"中文","translation":false},{"id":"wages-price-1-66","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"计算商品价值，也应当用这种方法。我们一定能把一切商品化为一种它们所共有的表现形式，只按照它们所含有的同一尺度的比例去区别它们。","language":"中文","translation":false},{"id":"wages-price-1-67","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"既然商品的交换价值不过是这些东西的社会职能，与它们的自然属性毫不相关，那么我们首先要问，所有商品共同的社会实体是什么呢？这就是劳动。要生产一个商品，必须在这个商品上投入或耗费一定量的劳动。我说的不仅是劳动，而是社会劳动。一个人生产一个物品要是为自己直接使用，供自己消费的，他创造的就是产品而不是商品。作为一个自给自足的生产者，他与社会没有关系。但是，一个人要生产一个商品，就不仅要生产能满足某种社会需要的物品，而且他的劳动本身也应该是社会所耗费的劳动总额的一部分。他的劳动应该从属于社会内部的分工。没有别的分工，这种劳动就算不了什么，它所以必需，是为了补充别的分工。","language":"中文","translation":false},{"id":"wages-price-1-68","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们如果把商品看作是价值，我们是只把它们看作体现了的、凝固了的或所谓结晶了的社会劳动。从这个观点来看，它们所以能够互相区别，只是由于它们代表着较多或较少的劳动量，例如，生产一条丝手巾也许比生产一块砖要耗费更多的劳动量。但是怎样测量劳动量呢？用劳动所经历的时间，也就是说，用小时、日等等来测量。当然，采用这种测量法，就必须把各种劳动化为平均劳动或简单劳动，作为它们的单位。","language":"中文","translation":false},{"id":"wages-price-1-69","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"所以我们便得出结论：商品具有价值，因为它是社会劳动的结晶。商品的价值的大小或它的相对价值，取决于它所含的社会实体量的大小，也就是说，取决于生产它所必需的相对劳动量。所以各个商品的相对价值，是由耗费于、体现于、凝固于该商品中的相应的劳动数量或劳动量决定的。在同样劳动时间内生产出来的各种商品的各相对应的数量，是相等的。或者说：一个商品的价值对另一个商品的价值的关系，相当于一个商品中凝固的劳动量对另一个商品中凝固的劳动量的关系。","language":"中文","translation":false},{"id":"wages-price-1-70","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我想，你们有许多人一定要问：商品价值由工资来决定与商品价值由生产该商品所必需的相对劳动量来决定，其间果真有什么区别或多大的差异吗？你们应当知道，劳动报酬和劳动数量是完全不相同的东西。例如，假定说一夸特小麦和一盎斯金子包含了同等数量的劳动。我举这个例子，是因为本杰明·富兰克林在他的1729年发表的题为《试论纸币的性质和必要性》这个第一篇论文里曾经用过，他也是一个最先发现价值的真正实质的人。是的，我们已假定，一夸特小麦和一盎斯金子是等价的或等价物，因为它们都是凝结于它们本身的若干天或若干周的同等数量的平均劳动的结晶。我们这样决定金子和谷物的相对价值，是否多少要参考一下农业工人和矿工的工资呢？一点也不。他们每天或每周的劳动究竟怎样支付，甚至是否采用了雇佣劳动，我们都不管，让它作为完全没有确定的问题。要是采用了雇佣劳动，这两个工人的工资就很可能极不相等。一个把劳动体现在一夸特小麦上的工人可能只获得两蒲式耳小麦的工资，而那个开矿的工人却可能获得半盎斯金子的报酬。或者，假定他们的工资是相等的，这种工资也可能在极不相同的比例上脱离他们所生产的商品的价值。这种工资可能等于一夸特谷物或一盎斯金子的1╱2、1╱3、1╱4、1╱5或其它某种份量。他们的工资当然不能超过或多于他们所生产的商品的价值，但是可能在极不相同的程度上少于这个价值。他们的工资要受产品的价值的限制，但是他们的产品的价值却不受工资的限制。最主要的是，例如谷物和金子的价值、相对价值，完全不依所用劳动的价值来规定，即不依工资来规定。因此，按商品中凝固的相对劳动量决定商品价值，与按劳动的价值或工资决定商品价值这种同义反复的方法全然不同。不过，这一点我们在以后的探讨过程中还要进一步阐明。","language":"中文","translation":false},{"id":"wages-price-1-71","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"在计算一个商品的交换价值时，必须把以前用于这个商品原料的劳动量以及消耗在协助这种劳动的那些装备、工具、机器和房屋的劳动，加到最后所费的劳动量上。例如，一定量棉纱的价值，是若干劳动量的结晶，即纺织过程中附加于棉花的劳动量，以前体现于棉花本身的劳动量，体现于煤炭、油料和其它各种生产辅助材料的劳动量以及用于蒸汽机、纱锭、厂房等等的劳动量的结晶。本来意义上的生产工具，如工具、机器和厂房，在反复的生产过程中可以再三使用一个或长或短的时期。如果它们像原料那样一下子就消耗完了，它们的全部价值也就会一下子转移到它们协助生产的那些商品上。但是，例如纱锭只是逐渐消耗的，所以就要根据它的平均寿命和它在一定时间内，例如在一天内的平均消耗程度来平均地计算。这样，我们就计算出纱锭价值中有多少转移到每天纺出的棉纱上，因而也就计算出，例如一磅棉纱所费的全部劳动量中，有多少是以前体现于纱锭的劳动。就我们现在的目的而论，对这个问题实在没有详述的必要了。","language":"中文","translation":false},{"id":"wages-price-1-72","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"也许会有人认为，既然商品的价值是由生产它所耗费的劳动量决定的，那么一个人越懒或越笨，他生产的商品就越有价值，因为完成这个商品所需要的劳动时间越多。然而，这样推论将是一个可悲的错误。你们记得我曾经用过“社会劳动”这个用语，“社会”这个词有许多含意。我们说，一个商品的价值是由耗费于或结晶于这个商品中的劳动量决定的，就是指，在一定的社会状态中，在一定的社会平均生产条件下，在所用劳动的一定的社会平均强度和平均熟练程度下，生产这个商品所必需的劳动量。在英国，当蒸汽织机和手织机开始竞争时，只需要从前的一半劳动时间就能把一定量的纱转化为一码布或呢子，可怜的手织机织工，从前每天劳动9小时或10小时，这时每天要劳动17至18个小时了。但是，他20个小时的劳动产品这时只代表10个小时的社会劳动，或代表10个小时内把一定量的纱转化成布时的社会必要劳动。因此，他用20个小时生产的产品，并不比他从前用10个小时生产的产品有更多的价值。","language":"中文","translation":false},{"id":"wages-price-1-73","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果说，体现在商品中的社会必要劳动量决定商品的交换价值，那么，生产一个商品所需要的劳动量增加了，这个商品的价值就必定增加，同样，生产它所需要的劳动量减少了，它的价值就必定减少。","language":"中文","translation":false},{"id":"wages-price-1-74","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果生产各种商品所必需的各种劳动量是固定不变的，这些商品的相对价值也会是固定不变的。但是，其实不然。生产一个商品所必需的劳动量，是随着所用劳动的生产力的变化而不断变化的。劳动的生产力越高，在一定的劳动时间内所完成的产品也越多；劳动的生产力越低，在同一时间内所完成的产品也越少。举例说，如因人口增加而必须耕种不太肥沃的土地，要获得同样多的产品，就必须耗费更大的劳动量，农产品的价值也就会因而提高。另一方面，如果一个纺纱工人用现代生产资料，在一个工作日内比他从前用手纺车在同一时间内能把多几千倍的棉花纺成纱，那么，每一磅棉花所吸收的纺纱工人的劳动，就显然只有以前的几千分之一，因而在纺纱过程中加在每一磅棉花上的价值也显然只有从前的几千分之一。于是棉纱的价值也要相应地减少。","language":"中文","translation":false},{"id":"wages-price-1-75","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"除了各个人的先天的能力和后天获得的生产技能的区别，劳动生产力主要应当取决于：","language":"中文","translation":false},{"id":"wages-price-1-76","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"首先，劳动的自然条件，如土地的肥沃程度、矿山的丰富程度等等；","language":"中文","translation":false},{"id":"wages-price-1-77","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"其次，劳动的社会力的日益改进，引起这种改进的是：大规模的生产，资本的积聚，劳动的联合，分工，机器，改良的方法，化学力和其它自然力的应用，利用交通和运输工具而达到时间和空间的缩短，以及其它各种发明，科学就是靠这些发明来驱使自然力为劳动服务，劳动的社会性质或协作性质也由于这些发明而得以发展。劳动生产力越高，消耗在一定量产品上的劳动就越少，因而产品的价值也越小。劳动生产力越低，消耗在同量产品上的劳动就越多，因而产品的价值也越高。因此，作为一般的规律，我们可以这样说：","language":"中文","translation":false},{"id":"wages-price-1-78","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"商品的价值与生产这些商品所耗费的劳动时间成正比，而与所耗费的劳动的生产力成反比。","language":"中文","translation":false},{"id":"wages-price-1-79","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"以上只说了价值，现在我再讲几句关于价格这个价值所表现的特殊形式。","language":"中文","translation":false},{"id":"wages-price-1-80","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"价格本身不过是价值的货币表现。例如，在英国，一切商品的价值是用金的价格表现的，而在欧洲大陆，主要是用银的价格表现的。金或银的价值，和其它一切商品的价值一样，都是由开采它们所必需的劳动量决定的。你们用本国的若干产品，即凝结了你们国内若干劳动量的产品，去交换那些出产金银的国家的产品，即凝结了它们的若干劳动量的产品。人们就是用这种方法，实际上是用以货换货的方法才学会用金银来表现一切商品的价值，即为它们所消耗的各个劳动量。只要仔细看看价值的货币表现，换句话说，仔细看看价值向价格的转化，你们就会发现，这是一个过程，一个使一切商品的价值能具有一种既独立又同质的形式，或者，一个使一切商品的价值能表现为等同的社会劳动量的过程。只要价格是价值的货币表现，亚当·斯密就称之为自然价格，法国的重农学派则称之为“必要价格”。","language":"中文","translation":false},{"id":"wages-price-1-81","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"那么，价值和市场价格的关系或自然价格和市场价格的关系是怎样的呢？你们都知道，一切同类商品的市场价格总是一样的，尽管生产条件因各个生产者而会有所不同。市场价格只表现在平均的生产条件下供给市场以某种数量的某种物品所必需的平均社会劳动量。市场价格是依据某种商品的总额计算的。在这个范围内，商品的市场价格与它的价值是相符的。另一方面，市场价格有时高于价值或自然价格，有时低于价值或自然价格，这种波动取决于供给和需求的变动。市场价格背离价值的情形是常见的，但是正如亚当·斯密所说：","language":"中文","translation":false},{"id":"wages-price-1-82","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"“自然价格……是中心价格，一切商品的价格都不断地趋向于这一中心价格。各种偶然情况可能有时使商品的价格过高于自然价格，有时又使商品的价格略低于它。但是不管什么样的障碍使价格背离这个稳定而恒久的中心，商品的价格总是经常趋向于这个中心。”","language":"中文","translation":false},{"id":"wages-price-1-83","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我现在不能细谈这个问题。只需要指出：如果供给和需求互相平衡，则商品的市场价格相当于它们的自然价格，也就是说，相当于它们的价值，这个价值是由生产它们所必需的劳动量决定的。但是供给和需求必定经常趋向于相互平衡，虽然它们实现这种平衡只是靠一个变动补偿另一个变动，靠下落补偿上涨，或者反过来的情况。如果你们不只是观察每天的波动，而是分析较长一段时期的市场价格的运动，例如像图克先生在他的《价格史》中所做的那样，你们就会发现，市场价格的波动，它们的背离价值，它们的上涨和下落，都是互相抵销和互相补偿的；所以，除了垄断组织的影响和其它某些限制，这些我暂且不谈，一切种类的商品，平均说来总是按它们各自的价值或自然价格出售的。市场价格波动互相补偿的平均时期，因商品的种类不同而各不相同，因为，某些商品比另一些商品更容易使供给适合于需求。","language":"中文","translation":false},{"id":"wages-price-1-84","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"说得更广些，就算在较长的时期一切种类的商品都是按各自的价值出售的，要是假定利润──不是指个别场合的，而是指各个行业经常的和普通的利润──来源于商品价格的额外提高，或者来源于商品按超过其价值的价格出卖，那岂不荒唐。要是把这个观点加以概括，它的荒谬就显然可见了。一个人作为卖者经常赢得的东西，总不免要作为买者经常丧失掉。如果说有些人是买者未必又是卖者，是消费者未必又是生产者，这也没用。这些人付给生产者的东西，首先应该是他们从生产者那里无偿得到的。如果一个人先拿了你的钱，然后用你的钱购买你的商品，即使你按高价把你的商品卖给这个人，你也决不会发财。这种交易可能减少亏损，但是决不能赚到利润。","language":"中文","translation":false},{"id":"wages-price-1-85","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"所以，要想说明利润的一般本质，就应该根据这样一个原理：平均说来，商品是按自己的实际价值出卖的，利润是按商品的价值，也就是说，按商品所体现的劳动量的比例出卖商品得来的。如果你们不能根据这种假定来解释利润，你们就根本不能解释它。这好像是奇谈怪论，有悖于日常经验。但是，地球围绕太阳运行以及水由两种易燃气体所构成，也是奇谈怪论了。日常经验只能抓住事物诱人的外观，如果根据这种经验来判断，科学的真理就总会是奇谈怪论了。","language":"中文","translation":false},{"id":"wages-price-1-86","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们尽量简略地分析了价值的本质，分析了一切商品的价值的本质，现在就应当集中注意力来研究特别的劳动的价值。这里我又要用一种好像是奇谈怪论的话来使你们大吃一惊了。你们都确实以为你们每天所出卖的是自己的劳动，所以劳动是有价格的，既然商品的价格只是它的价值的货币表现，那就一定有一种作为劳动的价值的东西。但是，作为劳动的价值的东西，就这个词的通常意义来说，实际上是不存在的。我们已经知道，凝结在商品里的必要劳动量构成商品的价值。现在我们用这个价值的概念，怎能确定比如说十小时工作日的价值呢？在这个工作日里有多少劳动呢？10小时劳动。如果说十小时工作日的价值就等于10小时的劳动，或者，就等于这个工作日所包含的劳动量，那无非是同义反复，甚至是毫无意义了。显然，我们一旦发现“劳动的价值”这个词的真实而隐藏的意义，就能说明对于价值的这种不合理的、似乎不可能的应用了，好像我们一旦认识了天体的实际运动，就能解释它们表面上奇异的运动一样。","language":"中文","translation":false},{"id":"wages-price-1-87","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"工人卖的并不直接是他的劳动，而是他的暂时让资本家支配的劳动力。的确，我不知道英国的法律究竟怎样，我确实知道一些大陆国家的法律都规定一个人能出卖自己劳动力的最长时间。如果允许无限期地出卖劳动力，奴隶制就会立刻恢复原状。如果这种出卖包括一个人的一生，那就会立刻把他变成他的雇主的终身奴隶了。","language":"中文","translation":false},{"id":"wages-price-1-88","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"英国的一位最老的经济学家和最有创见的哲学家托马斯·霍布斯已经在他的著作《利维坦》中本能地发觉了这一点，而他的继承者全都忽略了。他说：","language":"中文","translation":false},{"id":"wages-price-1-89","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"“一个人的价值或所值，像其它一切东西一样，就是他的价格，即使用他的力时应付给的报酬。”","language":"中文","translation":false},{"id":"wages-price-1-90","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"从这一原理出发，那我们就能确定劳动的价值，就像确定其它一切商品的价值那样。","language":"中文","translation":false},{"id":"wages-price-1-91","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是在这以前，我们应当问，有这样一种奇怪的现象：我们发现市场上有一批人是买者，他们占有土地、机器、原料和生活数据，这些东西，除了原始状态的土地以外，都是劳动的产品，另一方面，有一批人是卖者，他们除了自己的劳动力，除了劳动的双手和头脑，没有别的东西可卖；前一批人经常买进是为了赚取利润和发财，后一批人经常卖出则是为了谋生，这种奇怪的现象是怎样产生的呢？研究这个问题，就是研究经济学家所谓的预先积累或原始积累，实际上应该称作原始剥夺。我们一定会发现，这种所谓的原始积累不过是一连串使劳动者与其劳动数据之间的原始统一被破坏的历史过程。可是，这样的研究，就超出了目前这个题目的范围。劳动的人脱离劳动工具的现象一旦成为事实，就会继续保持下去，还会以不断扩大的规模再生产出来，直到一种新的、根本的生产方式的革命把它消灭，并以新的历史形式再恢复这种原始的统一为止。","language":"中文","translation":false},{"id":"wages-price-1-92","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"那么，劳动力的价值是什么呢？","language":"中文","translation":false},{"id":"wages-price-1-93","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"劳动力的价值，也像其它一切商品的价值一样，是由生产它所必需的劳动量决定的。一个人的劳动力只有在他本人活着的时候才存在。一个人要成长并维持生活，就必须消费一定量的生活必需品。但是，人和机器一样，也是要损坏的，所以必须有另一个人来代替他。他除了维持他自己生活所必需的若干生活必需品以外，还需要有一定数量的生活必需品来养育儿女，因为他们将在劳动市场上代替他，并且延续劳动者的种族。此外，为了发展他的劳动力，使他获得一种技能，还需要另外花费一定数量的价值。就我们的目的而论，只要考察一下中等的劳动就够了，这种劳动的教育费和训练费是微不足道的。但是，我要趁此机会指出，各种不同质量的劳动力的生产费用既然各不相同，所以不同行业所用的劳动力的价值也就一定各不相同。因此，要求工资平等是根本错误的，这是一种决不能实现的妄想。这种要求是一种虚妄和肤浅的激进主义的产物，只承认前提而企图避开结论。在雇佣劳动制度的基础上，确定劳动力的价值，也像确定其它一切商品的价值那样；不同种类的劳动力有不同的价值，要生产它们，需要有不同的劳动量，所以它们在劳动市场上就应当获得不同的价格。在雇佣劳动制度的基础上要求平等的或仅仅是公平的报酬，就犹如在奴隶制的基础上要求自由一样。你们认为公道和公平的东西，与问题毫无关系。问题就在于：一定的生产制度所必需的和不可避免的东西是什么？","language":"中文","translation":false},{"id":"wages-price-1-94","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"根据以上所说的，就可以看出，劳动力的价值，是由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定的。","language":"中文","translation":false},{"id":"wages-price-1-95","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"现在假定，一个工人每天的生活必需品的平均量需要6小时的平均劳动才能生产出来。又假定，这6小时的平均劳动也用金的数量表现出来，等于3先令。于是3先令就是这个人的劳动力的价格或他的劳动力的每天价值的货币表现。如果他每天工作6小时，那他每天所生产的价值就足以购买他每天平均必需的生活必需品，足以维持他这个工人的生存。","language":"中文","translation":false},{"id":"wages-price-1-96","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是，这个人是一个雇佣工人。因此，他必须把他的劳动力卖给资本家。如果他把他的劳动力每天卖3先令或每周卖18先令，他就是按劳动力的价值出卖的。假定他是一个纺纱工人。如果他每天工作6小时，他每天就使棉花增加了3先令的价值。他每天所加的这个价值，与他每天所得的工资或他的劳动力的价格，是完全等价的。可是，这样一来，资本家就得不到任何的剩余价值或剩余产品。于是我们在这里就遇到难题了。","language":"中文","translation":false},{"id":"wages-price-1-97","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"资本家购买工人的劳动力，付了它的价值以后，像所有其它买主一样，就有权消费或使用他所买的商品。强迫一个人去工作以消费或使用他的劳动力，就像开动一架机器去消费或使用它一样。资本家支付了工人劳动力的一天或一周的价值，就有权整天或整周地使用这个劳动力或迫使它去工作。工作日或工作周当然有一定的限度，可是这一点我们留待以后再详细谈。","language":"中文","translation":false},{"id":"wages-price-1-98","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"现在我希望你们注意一个关键问题。","language":"中文","translation":false},{"id":"wages-price-1-99","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"劳动力的价值是由维持或再生产这个劳动力所必需的劳动量决定的，对这种劳动力的使用却只受劳动者的工作能力和体力的限制。劳动力每天或每周的价值同劳动力每天或每周的消耗全然不同，就像一匹马所需要的饲料和它能供人乘骑的时间全然不同一样。限制工人劳动力价值的劳动量，决不能限制他的劳动力所能完成的劳动量。以我们的纺纱工人为例。我们已经知道，他为了每天再生产他的劳动力，必须每天再生产3先令的价值，这是他每天工作6小时就可以做到的。但是这并不妨碍他能每天工作10小时，12小时或更多的小时。然而资本家支付了这个纺纱工人劳动力的一天或一周的价值，就有权整天或整周地使用这个劳动力。这样，资本家就迫使他每天工作例如12小时。纺纱工人除了必须工作6小时以补偿他的工资或他的劳动力价值以外，还必须额外工作6小时，这6小时我称之为剩余劳动时间，这个剩余劳动将体现在剩余价值和剩余产品上面。假如我们这个纺纱工人，例如，每天工作6小时使棉花增加3先令的价值，这个价值与他的工资完全等价，那么，他在12小时内就要使棉花增加6先令的价值，并生产出相应的剩余棉纱。既然他已经把他的劳动力卖给资本家，他所创造的全部价值或产品，便都属于资本家，即他的劳动力的暂时所有者。资本家预付3先令，结果却实得6先令的价值，因为，他预付的价值是6小时劳动的结晶，而他收回的价值却是12小时劳动的结晶。资本家每天重复这一过程，他每天预付3先令，每天收入6先令，这6先令中有一半将再付工资，另一半则构成剩余价值，资本家对此并不付出任何等价物，资本主义的生产或雇佣劳动制度，正是在资本和劳动之间的这种交换的基础上建立的，这种交换必然不断地造成这样的结果：工人作为工人再生产出来，资本家作为资本家再生产出来。","language":"中文","translation":false},{"id":"wages-price-1-100","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果其它一切条件都相同，剩余价值率取决于再生产劳动力价值所必需的那部分工作日和为资本家效力的剩余时间或剩余劳动之间的比。所以，剩余价值率取决于工作日的延长在多大程度上超过工人只再生产他的劳动力价值，只抵偿他的工资所花费的劳动时间。","language":"中文","translation":false},{"id":"wages-price-1-101","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"现在我们应当回过来谈谈“劳动的价值或价格”这个用语。","language":"中文","translation":false},{"id":"wages-price-1-102","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我们已经知道，实际上，劳动的价值无非是劳动力的价值，是由维持劳动力所必需的那些商品的价值来测量的。但是，因为工人是在他劳动完毕以后领取工资的，并且知道他实际上给予资本家的正是他的劳动，所以他以为他的劳动力的价值或价格必然就是他的劳动本身的价格或价值。假定他的劳动力的价格是3先令，这是工作6小时所得的，如果他工作12小时，他必然以为这3先令就是12小时劳动的价值或价格，虽然这12小时的劳动体现了6先令的价值。由此就得出两个结论：","language":"中文","translation":false},{"id":"wages-price-1-103","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"第一，严格说来，劳动的价值或价格是无意义的名词，但是劳动力的价值或价格表面上却很像劳动本身的价格或价值。","language":"中文","translation":false},{"id":"wages-price-1-104","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"第二，虽然工人每天的劳动只有一部分是有偿的，另一部分是无偿的，这无偿的或剩余的劳动正是产生剩余价值或利润的基础，但是看起来就好像全部劳动都是有偿的劳动。","language":"中文","translation":false},{"id":"wages-price-1-105","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"这种假象，就是雇佣劳动和历史上其它形态的劳动的不同之处。在雇佣劳动制度的基础上，甚至无偿的劳动也好像是有偿的劳动；反之，奴隶的那部分有偿的劳动，却好像是无偿的劳动。奴隶因为要工作，自然必须生活，他的工作日的一部分就用于抵偿他自己维持生活的价值。但是，由于他和他的主人没有订立合同，双方又没有什么买卖行为，所以他的全部劳动似乎都是白干的。","language":"中文","translation":false},{"id":"wages-price-1-106","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"另一方面，再以农奴为例。可以说，农奴在整个东欧直到最近还存在着。农奴在自己的或分给他的田地上为自己劳动3天，其余3天就要在主人的领地上从事强迫的、无偿的劳动。所以，这里劳动中的有偿部分和无偿部分都显然分开了，在时间上和空间上都分开了，于是我们的自由主义者就义愤填膺，认为强迫人白干活的这种意见非常荒谬。","language":"中文","translation":false},{"id":"wages-price-1-107","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"其实，一个人无论是一周中在自己的田地上为自己劳动3天，再在主人的领地上无报酬地劳动3天，或者是每天在工厂或作坊中为自己劳动6小时，再为他的雇主劳动6小时，结果都一样，不过在后一例中，劳动的有偿部分和无偿部分是不可分割地混在一起的，整个交易的实质完全被合同的存在和周末付酬所掩饰了。这种无偿的劳动，在后一例中似乎是自愿的，在前一例中似乎是强迫的。全部区别就在于此。","language":"中文","translation":false},{"id":"wages-price-1-108","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"以下使用的“劳动的价值”这一用语，我不过是把它作为表示“劳动力价值”的通常流行的名词罢了。","language":"中文","translation":false},{"id":"wages-price-1-109","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"10．利润是按照商品的价值出卖商品获得的","language":"中文","translation":false},{"id":"wages-price-1-110","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"假定1小时的平均劳动所体现的价值等于6便士，或12小时的平均劳动体现为6先令。又假定劳动的价值等于3先令或6小时劳动的产品。如果生产一种商品所耗费的原料、机器等等体现了24小时的平均劳动，这些东西的价值就会等于12先令。此外，如果资本家所雇的工人再把自己12小时的劳动加到这些生产资料上，这12小时就会体现为6先令的追加价值。所以这种产品的全部价值共为36小时的已体现的劳动，即等于18先令。但是，劳动的价值或付给工人的工资只有3先令，那么，资本家对于工人所耗费并体现在商品价值里的6小时剩余劳动，就没有支付任何等价物。所以，资本家把这个商品按其价值卖了18先令，他就实现了3先令的价值，他对此并未付出任何等价物。这3先令就是他装进自己口袋里的剩余价值或利润。可见，资本家实现这3先令的利润，并不是因为他按照超过商品价值的价格出卖商品，而是因为他按照商品的实际价值出卖这个商品。","language":"中文","translation":false},{"id":"wages-price-1-111","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"商品的价值是由该商品所包含的全部劳动量决定的。但是，这劳动量有一部分体现为用工资形式付过等价的价值，另一部分则体现为没有付过任何等价的价值。商品中所含的劳动，一部分是有偿劳动，另一部分是无偿劳动。所以，资本家按照商品的价值出卖商品，即出卖耗费于该商品的全部劳动量的结晶，是必定获得利润的。资本家出卖的不仅有他支付过等价的东西，而且还有他分文未付的东西，虽然这东西曾费去了他的工人的劳动。资本家花在商品上的费用，和商品的实在费用，是不同的两码事。所以，我再说一遍，正常的、平均的利润，不是由于超过而是由于按照商品的实际价值出卖商品获得的。”","language":"中文","translation":false},{"id":"wages-price-1-112","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"11．剩余价值分解成的各个部分","language":"中文","translation":false},{"id":"wages-price-1-113","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"剩余价值，或商品全部价值中体现工人的剩余劳动或无偿劳动的那一部分，我称之为利润。这种利润并不是全都落入经营资本家的腰包。垄断土地，使土地占有者能以地租名义──不管这土地是用于农业、建筑、铁路还是用于其它生产目的──取得这剩余价值的一部分。另一方面，拥有劳动资料，使经营资本家能生产剩余价值，即窃取一定量的无偿劳动，这就使拥有劳动资料并把它们全部或部分地贷给经营资本家的人，简言之，即放债的资本家，能以利息的名义，要求取得这剩余价值的另一部分，所以，留归经营资本家本身的，就只是所谓产业利润或商业利润的那一部分了。","language":"中文","translation":false},{"id":"wages-price-1-114","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"至于上述三种人这样瓜分全部剩余价值究竟由什么规律来调节的问题，与本题毫无关系。但是根据以上所述，可以得出这样的结论：","language":"中文","translation":false},{"id":"wages-price-1-115","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"地租、利息和产业利润不过是商品的剩余价值或商品中所包含的无偿劳动各个部分的不同名称，它们都是同样从这个泉源并且只是从这个泉源产生的。它们不是从土地本身也不是从资本本身产生的，但是土地和资本使拥有土地和资本的人能从经营资本家压榨工人所得来的剩余价值中各分得一份。对于工人来说，究竟经营资本家是把这剩余价值──工人剩余劳动或无偿劳动的产物──全部占为己有，或是不得不将其中某些部分以地租和利息的名义分给第三者，这是一个次要的问题。假定经营资本家只使用自己的资本，而且本人又是他使用的那块土地的所有者，那么，剩余价值就会全部落入他的腰包了。","language":"中文","translation":false},{"id":"wages-price-1-116","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"直接向工人榨取这剩余价值的正是经营资本家，不论他最终能把这剩余价值中的哪一部分留归自己。所以，整个雇佣劳动制度，整个现代生产制度，正是建立在经营资本家和雇佣工人的这种关系上的。因此，有几位参加我们这次讨论的公民要想模糊事情的真相，把经营资本家和工人的这种根本关系看作一个次要的问题，那就错了，虽然他们断定，在一定情况下，价格的上涨对经营资本家、土地所有者、货币资本家以至征税者影响的程度极不相同，这是正确的。","language":"中文","translation":false},{"id":"wages-price-1-117","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"根据以上所述，还可以得出另一个结论。","language":"中文","translation":false},{"id":"wages-price-1-118","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"商品价值中只代表原料和机器的价值的那一部分，即只代表消耗了的生产资料的价值的那一部分，决不会构成收入，只是补偿资本而已。但是，除此以外，如果说商品价值中的另一部分，即构成收入或可能以工资、利润、地租、利息的形式花费掉的那一部分，是由工资的价值、地租的价值和利润的价值等等构成的，那就错了。我们先不谈工资，只来研究产业利润、利息和地租。我们刚才说过，商品中所包含的剩余价值或商品价值中体现无偿劳动的这一部分价值，其本身分解成不同的部分，有三个不同的名称。可是，如果说商品中的这一部分价值是由这三个组成部分的独立价值之和而构成或形成的，那就完全违反真理了。","language":"中文","translation":false},{"id":"wages-price-1-119","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果1小时的劳动体现为6便士的价值，如果工人的工作日为12小时，如果这段时间有一半是无偿劳动，那么这种剩余劳动就在商品上加3先令的剩余价值，即没有付过等价的价值。这3先令的剩余价值，就是经营资本家可以按任何比例去同土地所有者及放债人瓜分的全部基金。这3先令的价值，构成他们彼此瓜分的那个价值的限度。并不是经营资本家在商品的价值上任意加上一份价值作为自己的利润，再加上另一份价值给土地所有者等等，然后，这些任意规定的价值就构成了全部价值。所以，你们知道，流行的观点分不清一定量的价值分解为三个部分，和三种独立价值相加而形成这个价值这二者的不同，于是就把地租、利润和利息所由产生的总和价值变成一种随意规定的数量，这种观点该是如何荒谬。","language":"中文","translation":false},{"id":"wages-price-1-120","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"假定一个资本家所实现的全部利润等于100英镑，我们把这个数量看作一个绝对量而称之为利润量。如果我们计算这100英镑对于预付资本的比，我们就把这个相对量称为利润率。这个利润率显然可以用两种方式来表示。","language":"中文","translation":false},{"id":"wages-price-1-121","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"假定预付在工资上的资本为100英镑。如果所创造的剩余价值也是100英镑，那就表明这工人的工作日一半是无偿劳动；如果我们用预付在工资上的资本价值去测量这个利润，我们就可以说，利润率等于100％，因为预付的价值为100，而实得的价值则为200。","language":"中文","translation":false},{"id":"wages-price-1-122","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"另一方面，如果我们不是只看到预付在工资上的资本，而是看到预付的全部资本，例如500英镑，其中，400英镑代表原料、机器等等的价值，我们就应该说，利润率只等于20％，因为这100英镑的利润只是预付的全部资本的1╱5。","language":"中文","translation":false},{"id":"wages-price-1-123","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"前一种表示利润率的方式，是表明有偿劳动和无偿劳动的真正比率，即对劳动进行exploitation（请允许我用这个法文字）的真实程度的唯一方式；后一种表示方式是通常所用的，并且也确实适用于某几种目的，至少是非常便于掩饰资本家榨取工人无偿劳动的程度。","language":"中文","translation":false},{"id":"wages-price-1-124","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"在我以后的说明中，我将使用利润一词来标明资本家所榨取的剩余价值总量，不管这剩余价值究竟如何分配给不同的人群；我在使用利润率一词时，则总是用预付在工资上的资本价值来测量利润。","language":"中文","translation":false},{"id":"wages-price-1-125","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"12．利润、工资和价格的一般关系","language":"中文","translation":false},{"id":"wages-price-1-126","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"从商品的价值中除去补偿原料和耗费在商品上的其它生产资料的价值的价值，即除去商品中所含的代表过去劳动的价值，这商品价值的余留部分就是最后雇用的工人所加的劳动量。如果这个工人每天工作12小时，如果12小时的平均劳动结晶为6先令的金量，那么这6先令的附加价值就是他的劳动所创造的唯一价值。这种由他的劳动时间所决定的一定的价值，就是他和资本家双方都从中各自分得一份的唯一基金，即分为工资和利润的唯一价值。显然，双方可以按各种不同比例来分配这一价值，但是这一价值本身是不会变化的。假如不是以一个工人而是以全体工人人数计算，或者不是以一个工作日而是例如以1200万个工作日计算，也同样不会有什么变化。","language":"中文","translation":false},{"id":"wages-price-1-127","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"资本家和工人所能分配的仅仅是这个有限的价值，即根据工人的全部劳动所测量的价值，所以一方分得的越多，他方分得的就越少，反之亦然。一个一定的数，其中一部分在增加时，另一部分相反地总要减少。工资有了变动，利润就要朝相反的方向变动。工资下降了，利润就要上涨；工资上涨了，利润就要下降。按照前面的假设，如果工人得3先令，即等于他所创造的价值的一半，换句话说，如果他的整个工作日一半是有偿劳动，一半是无偿劳动，利润率就是100％，因为资本家所得的也是3先令。假如工人只得到2先令，或者，在一整天中只有1∕3的时间为自己工作，资本家得到的就是4先令，利润率就是200％。如果工人得到4先令，资本家只得到2先令，利润率就降至50％。但是，这一切变动都不会影响商品的价值。所以，工资的普遍提高只会引起一般利润率的降低，而不会影响商品的价值。","language":"中文","translation":false},{"id":"wages-price-1-128","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是，商品的价值──这种价值最终一定要调节商品的市场价格──虽然完全由商品中所凝结的劳动总量来决定，并不取决于这种劳动量分为有偿劳动和无偿劳动，但是决不能说，例如在12小时内所生产的个别商品或成批商品的价值会永远不变。在一定的劳动时间内或由一定的劳动量所生产的商品的数或量，取决于所用的劳动的生产力，而不取决于劳动的延伸或长度。纺纱劳动的生产力，在一般水平下，例如，在一个12小时的工作日内能生产12磅棉纱，在较低的生产力水平下，只能生产2磅棉纱。这就是说，如果在前一场合，12小时的平均劳动实现为6先令的价值，12磅棉纱就要值6先令，而在后一场合，2磅棉纱也要值6先令。所以，在前一场合，1磅棉纱只值6便士，在后一场合，1磅棉纱竟要值3先令。这种价格上的差异，就是所用劳动的生产力有差异的结果。生产力较高时，1小时劳动体现为1磅棉纱；生产力较低时，6小时劳动才能体现为1磅棉纱。在前一场合，1磅棉纱的价格只等于6便士，尽管工资较高而利润率较低，在后一场合，它的价格却等于3先令，尽管工资较低而利润率较高。这是必然的，因为1磅棉纱的价格是由耗费于这磅棉纱的全部劳动量决定的，而不是由这个劳动量分为有偿劳动和无偿劳动的比例决定的。所以，我前面所说的高价劳动可能生产低廉的商品，而低价劳动可能生产昂贵的商品这一事实，也就不再像是什么奇谈怪论了。这只是说明了一般的规律，即商品的价值是由消耗于商品的劳动量决定的，所消耗的劳动量完全取决于所用劳动的生产力，因而也随劳动生产率的每一变化而变化。","language":"中文","translation":false},{"id":"wages-price-1-129","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"13．争取提高工资或反对降低工资的一些最重要场合","language":"中文","translation":false},{"id":"wages-price-1-130","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"现在让我们认真研究一下争取提高工资或反对降低工资的几个主要场合。","language":"中文","translation":false},{"id":"wages-price-1-131","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（1）我们已经知道，劳动力的价值，或用流行的说法，即劳动的价值，是由生活必需品的价值或生产这些生活必需品所需要的劳动量决定的。例如，在某一国，劳动者每天平均的生活必需品的价值为6小时的劳动，表现为3先令，这个劳动者为了生产维持他一天生活费用的等价物，就必须每天工作6小时。如果整个工作日为12小时，资本家付给他3先令，便偿付了他的劳动的价值。工作日的一半就会是无偿劳动，利润率就等于100％。但是现在假定，例如，因生产率的降低，要用更多的劳动来生产同量的农产品，于是，每天平均的生活必需品的价格就从3先令涨到4先令。在这种场合，劳动的价值就增加1∕3，或增加331∕3％。劳动者要依照他原来的生活水平生产维持他一天生活费用的等价物，便需在一个工作日中劳动8小时；所以，剩余劳动就要由6小时减到4小时，利润率就要由100％降到50％。但是，劳动者要求提高工资，不过是要求获得他的劳动所增加的价值，就好像其它所有出卖商品的人在商品成本费增加时，力求使其商品所增加的价值获得报酬一样。如果工资没有提高或提高得不够补偿生活必需品所增长的价值，劳动的价格也就会降到劳动的价值以下，劳动者的生活水平就会下降。","language":"中文","translation":false},{"id":"wages-price-1-132","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是，变化也可能朝相反的方向发生。由于劳动生产率的提高，同等数量的每天平均的生活必需品，可能从3先令减到2先令，换句话说，在一个工作日中不必劳动6小时，只要劳动4小时，就能再生产与每天生活必需品等价的价值。这时工人用2先令就可以买到从前用3先令买到的生活必需品了。劳动的价值确实会降低，但是，这样减少的价值，仍能获得和从前一样多的商品。于是，利润就会从3先令提高到4先令，利润率也会从100％提高到200％。虽然工人生活的绝对水平依然照旧，但他的相对工资以及他的相对社会地位，也就是与资本家相比较的地位，却会下降。工人反对这种相对工资的降低，不过是想要在他的增长的劳动生产力所生产的总额中获得应有的一份，不过是想要维持他以前在社会阶梯上的相对地位。例如，英国的一些工厂主在榖物法废除后，就卑鄙地背弃他们在鼓动反对谷物法时所作的庄严诺言，把工资普遍降低了10％。工人的反抗，起初没有奏效，但是，由于我现在不能详谈的某些情况，后来又恢复所失去的10％了。","language":"中文","translation":false},{"id":"wages-price-1-133","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（2）生活必需品的价值，从而劳动的价值，可能保持原状，但是货币的价值已经发生变化，所以生活必需品的货币价格也可能发生变化。","language":"中文","translation":false},{"id":"wages-price-1-134","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"由于更丰富的矿山的发现，等等，生产例如2盎斯金，可能并不比从前生产1盎斯金所费的劳动多。于是，金的价值就会降低一半或50％。劳动的价值，也像其它一切商品的价值一样，就要表现在比以前大一倍的货币价格上。从前表现为6先令的12小时劳动，这时就会表现为12先令了。如果工人的工资仍是3先令而没有提高到6先令，他的劳动的货币价格这时就只等于他的劳动的价值的一半，他的生活水平也就要大大降低。如果他的工资提高了，但与金的价值的下降不成比例，这种情况也会在或大或小的程度上发生。在这个实例中，无论是劳动生产力，供给和需求，还是价值，都没有丝毫变化。除了这些价值的货币名称，什么也没有变。如果说，在这样的场合工人不应该争取工资的相应提高，那就等于说，他必须满足于名称的报酬，而不是实物的报酬。过去的整个历史证明，在发生这样的货币贬值时，资本家总是急忙趁此良机来欺骗工人。但是，许多派别的政治经济学家断定，由于新发现一些产金地、改进银矿开采和水银供给较廉，贵重金属的价值又降低了。这也许可以说明为什么大陆上普遍地同时产生了提高工资的要求。","language":"中文","translation":false},{"id":"wages-price-1-135","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（3）我们以前都假定工作日有一定的界限。但是工作日本身并没有固定界限。资本的经常趋势就是把工作日延长到体力可能达到的极限，因为随着工作日长度的增加，剩余劳动，从而这劳动所创造的利润也将同样增长。资本把工作日越延长，它占有他人的劳动量也越多。在17世纪，甚至在18世纪的前三分之二这段期间，10小时的工作日是全英国的正常工作日。在反雅各布宾战争，其实是不列颠贵族反对不列颠劳动群众的战争时期，资本庆祝自己的胜利，把工作日从10小时延长到12小时，14小时，18小时。马尔萨斯这位决非多愁善感的人，在1815年左右出版的一本小册子中宣称，这种情形如果再继续下去，必将摧毁民族的生命之本。在普遍应用新发明的机器的前几年即1765年左右，英国出现了一本小册子，书名为《论手工业》。匿名的作者是工人阶级的死敌，他竭力主张必须扩大工作日的界限。为了达到这一目的，他提议，除了采取其它手段，还要建立习艺所，用他的话来说，应该是“恐怖所”。他给这种“恐怖所”规定的工作日是多长呢？12小时，──这恰好是资本家、政治经济学家和内阁大臣们在1832年宣布的对12岁以下儿童不仅是已在实行，而且是必要的工作时间。","language":"中文","translation":false},{"id":"wages-price-1-136","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"工人出卖他的劳动力──在现代制度下他不得不这样做──就是把这个力让给资本家来消费，不过是在一定的合理的界限内消费。他出卖他的劳动力，是为了保持它，──且不谈它的自然损耗，──而不是为了毁灭它。工人按照劳动力每天或每周的价值出卖他的劳动力，不用说，决不会允许这个劳动力在一天或一周内受到两天或两周的损耗或损失。现在举一架价值1000英镑的机器为例。如果这架机器能用10年，它在它所参与生产的商品的价值上每年就要增添100英镑。如果它能用5年，它每年在这些商品的价值上就要增添200英镑。换句话说，它每年损耗的价值和它被磨损的速度成反比。但这正是工人和机器的不同之处。机器恰恰不是和它的使用期限按同样的比率磨损。相反地，人的衰老程度，和他工作的单纯数值的增加，在比例上显然大得多。","language":"中文","translation":false},{"id":"wages-price-1-137","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"当工人们争取工作日减到原先的合理范围时，或者，当他们不能强迫法律规定正常的工作日，而用提高工资的办法，使工资提高得不仅和被勒索的剩余时间成比例而且还要超过这一比例，来防止过度劳动时，他们只是在对他们自己和他们的种族履行义务。他们不过是对资本的横暴掠夺设置一些限制而已。时间是人类发展的空间。一个人如果没有自己处置的自由时间，一生中除睡眠饮食等纯生理上必需的间断以外，都是替资本家服务，那么，他就还不如一头载重的牲畜。他不过是一架为别人生产财富的机器，身体垮了，心智也犷野了。现代工业的全部历史还表明，如果不对资本加以限制，它就会不顾一切和毫不留情地把整个工人阶级投入这种极端退化的境地。","language":"中文","translation":false},{"id":"wages-price-1-138","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"资本家延长工作日，可能付出较高的工资，其实仍低于劳动的价值，如果工资的提高不符合被榨取的更大的劳动量，不符合劳动力的更快的衰竭，这种情形就会发生。这种事，用别的方法也可以做到。你们的资产阶级统计学家们会告诉你们，例如，兰开夏郡的职工家庭的平均工资增加了。他们却忘记补充说，除了家长那个成年男子的劳动，还有他的妻子，也许还有三四个小孩，现在都被投在资本的札格纳特车轮下了，而工资总额的增加并不符合从这个家庭榨取的全部剩余劳动。","language":"中文","translation":false},{"id":"wages-price-1-139","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"即使工作日有一定的界限，例如，现在一切服从工厂法的工业部门中有这种限制，要想保持劳动价值的原有水平，提高工资也是必要的。劳动强度的提高，可能使一个人在一小时内耗费他从前在两小时内耗费的生命力。在一些服从工厂法的行业中，由于机器运转速度的加快和一个人要管理的工作机器的加多，这种情形已经在某种程度上出现了。如果劳动强度的提高或一小时内所费劳动量的增大与工作日的缩短保持应有的比例，劳动者还能占到便宜。如果超过这个限度，他在一种形式下所得到的就会在另一种形式下丧失掉，于是10小时劳动就可能与以前12小时劳动同样有害。工人争取把工资提高到相当于劳动强度提高的程度来制止资本的这种倾向，这不过是抑制他的劳动的跌价，防止他的种族的退化罢了。","language":"中文","translation":false},{"id":"wages-price-1-140","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（4）你们都知道，由于我现在没有必要说明的某些原因，资本主义的生产总是要经过一定的周期性循环。它要经过消沉、逐渐活跃、繁荣、生产过剩、危机和停滞等阶段。商品的市场价格和市场利润率，都随着这些阶段而变化，有时低于自己的平均水平，有时高于自己的平均水平。你们考察一下这整个周期，就会发现，市场价格的一种偏差是由别种偏差来补正的，在整个周期内，平均说来，商品的市场价格是由商品的价值调节的。再说，在市场价格下跌的阶段，以及在危机和停滞的阶段，工人即使不致完全失业，他的工资也一定会降低。为了不受骗，他甚至在市场价格这样下降时，也应当同资本家争论工资究竟该降到什么程度。在产生额外利润的繁荣阶段，他如果不争取提高工资，按整个工业周期平均计算，他就会甚至得不到他的平均工资或他的劳动的价值。他的工资，在这个周期的不顺利阶段，必然要受影响，如果在这个周期的繁荣阶段，还要求他不去争取补偿，那就太愚蠢了。一般说来，一切商品的价值，只是由不断波动的市场价格的相互补偿才能实现，而这种相互补偿又是供给和需求不断变动的结果。在现代制度的基础上，劳动不过是一种商品，和其它商品一样。所以，劳动也必须经历同样的变动，才能够获得与它的价值相符的平均价格。如果一方面把劳动看做一种商品，另一方面又让它免受调节商品价格的那些规律的约束，那就很荒谬了。奴隶能得到经常的和定量的生活数据，雇佣工人却不能。雇佣工人要想补偿一个时期的工资的降低，必须在另一个时期努力争取工资的提高，如果他甘心接受资本家的愿望，接受资本家的命令，把它当作永久的经济规律，他就一定要受到奴隶所受的一切苦痛，而得不到奴隶所享有的生存保障。","language":"中文","translation":false},{"id":"wages-price-1-141","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（5）从我以上讨论的各场合──它们几乎是百分之九十九──你们已经看见，提高工资的斗争只不过是在先前的各种变化之后发生的，是生产的规模、劳动的生产力、劳动的价值、货币的价值、被榨取的劳动长度或强度、市场价格的波动──它的波动取决于供给和需求的变动，与工业周期的各个阶段相适应──这些先前的变化的必然结果，总而言之，是劳动对资本的先前行动的反行动。你们讨论争取提高工资的斗争，如果不顾这些情况，如果只看到工资的变动而忽视引起这些变动的其它一切变动，你们就是从错误的前提出发，想要得出一个错误的结论了。","language":"中文","translation":false},{"id":"wages-price-1-142","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"14．资本和劳动的斗争及其结果","language":"中文","translation":false},{"id":"wages-price-1-143","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（1）我已经指出，工人周期地反抗降低工资，周期地力图提高工资，这是同雇佣劳动制度密不可分的，因为劳动既然等同于商品，就要服从那些调节一般价格变动的规律；我还指出，工资的普通提高会引起一般利润率的降低，但不会影响商品的平均价格或商品的价值。现在就有一个问题：在资本和劳动的这场不断的斗争中，后者能取得多大的成功？","language":"中文","translation":false},{"id":"wages-price-1-144","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"我可以概括地回答，劳动和其它一切商品一样，它的市场价格在长时期内会与它的价值相适应；因此，不论怎样涨跌，也不论工人如何行动，他所得到的，平均计算起来，只是他的劳动的价值，他的劳动的价值无非是他的劳动力的价值，后者是由维持和再生产劳动力所需要的生活必需品的价值决定的，而这些生活必需品的价值最后又是由生产它们所需要的劳动量决定的。","language":"中文","translation":false},{"id":"wages-price-1-145","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"但是，劳动力的价值或劳动的价值由于有某些特点而不同于其它一切商品的价值。劳动力的价值由两种要素构成：一种是纯生理的要素，另一种是历史的或社会的要素。劳动力价值的最低界限是由生理的要素决定的。这就是说，工人阶级为了维持和再生产自己，为了延续自己肉体的生存，就必须获得生存和繁殖所绝对需要的生活必需品。所以这些绝对需要的生活必需品的价值，就构成劳动的价值的最低界限。另一方面，工作日的长度也有极限，虽然是很有伸缩性的极限。它的最高界限决定于工人的体力。如果他的生命力每天的消耗超过一定限度，就不能日复一日地重复使用了。可是，我已经说过，这种限度有很大的伸缩性。孱弱和短命的后代如果繁殖很快，也可以与健壮和长命的后代一样，使劳动市场维持下去。","language":"中文","translation":false},{"id":"wages-price-1-146","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"除了这种纯粹生理的要素，劳动的价值还取决于每个国家的传统生活水平。这种生活水平不仅要满足生理上的需要，而且要满足人们赖以生息教养的那些社会条件所产生的某些需要。英国人的生活水平可能降到爱尔兰人的生活水平；德国农民的生活水平可能降到利夫兰农民的生活水平。关于历史传统和社会风俗在这方面起的巨大作用，你们可以看一看桑顿先生的《人口过剩论》，他在书中指出，英国各农业区的平均工资，至今还由于这些区域在脱离农奴状态时所处条件的好坏程度不同而有高低之分。","language":"中文","translation":false},{"id":"wages-price-1-147","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"包含于劳动价值中的这一历史的或社会的要素可能扩大，也可能缩小，甚至可能完全消失，只剩下生理上的限界。在反雅各布宾战争时期──正如那位不可救药的吞食赋税、尸位素餐的老乔治·罗斯经常说的那样，发动这场战争是为了挽救我们神圣宗教的福利免遭渎神的法国人的侵犯──我们在前次会议上曾谨慎地谈到的那些仁慈的英国农场主，竟把农业工人的工资降到这种纯粹生理上的最低界限以下，而维持生命和延续种族所需要的不足之数却由济贫法来填补。这是把雇佣工人变成奴隶，把莎士比亚笔下的骄傲的自耕农变成贫民的一种高明手法。","language":"中文","translation":false},{"id":"wages-price-1-148","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果你们把各个不同国家中或同一国家各个不同历史时代的工资水平或劳动的价值水平比较一下，你们就会发现，劳动的价值本身不是一个固定的量，而是一个变化的量，即使假定其它一切商品的价值不变，它也是变化的。","language":"中文","translation":false},{"id":"wages-price-1-149","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"这种比较也可以证明：不仅市场利润率是变动的，而且平均利润率也是变动的。","language":"中文","translation":false},{"id":"wages-price-1-150","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"然而对于利润来说，并没有一条规律能决定其最低限度。我们不能说，利润降低的极限是怎样的。为什么我们不能够确定这个限度呢？因为我们虽能确定工资的最低限度，却不能确定工资的最高限度。我们只能说，工作日既然有界限，利润的最高限度就与生理上所容许的工资的最低限度相适应；工资既然是一定的，利润的最高限度就与工人体力所容许的工作日延长程度相适应。所以利润的最高限度受生理上所容许的工资的最低限度和生理上所容许的工作日的最高限度的限制。显然，在最高利润率的这两个界限之间可能有许多变化。利润率的实际水平只是由资本与劳动的不断斗争确定的，资本家总想把工资降低到生理上所容许的最低限度，把工作日延长到生理上所容许的最高限度，而工人则在相反的方面不断地对抗。","language":"中文","translation":false},{"id":"wages-price-1-151","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"归根到底，这是斗争双方力量对比的问题。","language":"中文","translation":false},{"id":"wages-price-1-152","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（2）至于谈到英国的工作日的限制，像其它各国一样，它向来只靠立法的干涉。如果没有工人方面的经常压力，这种干涉永远也不会实现。无论如何，这种结果决不是工人和资本家的私人经商所能获得的。这种采取普遍政治行动的必要性就证明，资本在其纯粹经济的行动上是比较强有力的一方。","language":"中文","translation":false},{"id":"wages-price-1-153","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"至于谈到劳动价值的界限，它实际上总是取决于供给和需求。我指的是资本方面对劳动的需求和工人方面对劳动的供给。在一些殖民地国家，供求规律有利于工人。所以，美国的工资水平比较高。资本在这里可以施展全力，却不能制止因雇佣工人经常转化为独立自耕农而造成的劳动市场的经常空虚。对于大部分美国人民说来，雇佣工人的地位不过是一种学徒见习的状态，他们迟早总会脱离这种状态。为了纠正殖民地的这种情况，作为母邦的不列颠政府曾一度采纳所谓现代殖民学说，其内容是将殖民地的土地人为地规定一种高价，以阻止雇佣工人过分迅速地转化为独立农民。","language":"中文","translation":false},{"id":"wages-price-1-154","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"现在我们来谈谈资本支配全部生产过程的那些文明古国。例如，以英国农业工人的工资在1849年至1859年时期的提高为例。其结果如何呢？农场主们没能──我们的朋友韦斯顿也许劝告过他们──提高小麦的价值，甚至没能提高小麦的市场价格，反而不得不听任其市场价格的下降。但是在这11年中，他们采用各种机器，应用更科学的方法，把一部分耕地变成牧场，增大农场的面积，同时也扩大了生产的规模，由于采取了这些方法和其它各种提高劳动生产力的措施而减少对劳动的需求，使农村人口又相对过剩了。这就是资本在各个早已住满居民的古老国家迟早对付增加工资的一般方法。李嘉图正确地说过，机器是经常和劳动竞争的，并且往往是在劳动价格已达到某种高度时才可能被采用；然而采用机器不过是提高劳动生产力的许多方法之一。正是这个发展过程使简单劳动相对过剩，另一方面使熟练劳动简单化，于是也就使它贬值了。","language":"中文","translation":false},{"id":"wages-price-1-155","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"这同一规律还有另一种形式。随着劳动生产力的发展，即使工资的水平相当高，资本的积累也会越来越快。因此，可以推论，像亚·斯密──在他的那个时代，近代工业还很幼稚──那样推论，资本的这种加速积累，能保证对劳动需求的增长，所以必然会对工人有利。现代许多著作家同意这种观点，他们对最近20年英国资本的增加比人口的增加更迅速，而工资却没有很大的提高，感到诧异。但是随着积累的进展，资本的构成也发生递增的变化。资本中包含固定资本即机器、原料和各种生产资料的这一部分，比用于支付工资或购买劳动的那一部分，总是逐渐递增的。这一规律已经由巴顿、李嘉图、西斯蒙第、理查德·琼斯教授、拉姆赛教授、舍尔比利埃等人多少确切地阐明了。","language":"中文","translation":false},{"id":"wages-price-1-156","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"如果资本中这两个部分的比例原来是一比一，这个比例就会因工业的发展而变成五比一，等等。如果总资本为600，其中300用于工具和原料等，其余300用于支付工资，那么总资本只增加一倍，就能造成对600工人而不是对300工人的需求。但是，如果总资本600中，500用于机器和原料等，只有100用于支付工资，为了造成对600工人而不是对300工人的需求，这同一资本就要从600增至3600。因此，在工业发展的进程中，对劳动的需求总是赶不上资本的积累。这一需求是在增加，但是与资本的增加相比，不过是在递减的比例上增加的。","language":"中文","translation":false},{"id":"wages-price-1-157","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"以上所说的这几点足以表明，现代工业的发展一定会越来越有利于资本家而有害于工人，所以资本主义生产的总趋势不是提高而是降低工资的平均水平，在或大或小的程度上使劳动的价值降到它的最低限度。这种制度下的实际情况的趋势既然如此，那么，这是不是说，工人阶级应当放弃对资本的掠夺行为的反抗，停止利用偶然的时机使生活暂时改善的尝试呢？如果他们这样做，他们就会沦为一群听天由命的、不可挽救的可怜虫。我想我已经说过：他们争取工资水平的斗争，同整个雇佣劳动制度有密切的联系；他们为提高工资的努力，在一百回中有九十九回都只是为了维持现有的劳动价值；他们必须与资本家争论劳动价格，因为他们已经把自己当作商品出卖了。他们在和资本的日常冲突中如果畏缩让步，他们就没有资格发动更大的运动。","language":"中文","translation":false},{"id":"wages-price-1-158","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"同时，即使不谈雇佣劳动制度中所包含的一般奴隶状态，工人阶级也不应夸大这一日常斗争的最终效果。他们不应当忘记：在日常斗争中他们反对的只是结果，而不是产生这种结果的原因；他们延缓下降的趋势，而不改变它的方向；他们服用止痛剂，而不袪除病根。所以他们不应当只局限于这些不可避免的、因资本永不停止的进攻或市场的各种变动而不断引起的游击式的搏斗。他们应当懂得：现代制度给他们带来一切贫困，同时又造成对社会进行经济改造所必需的种种物质条件和社会形式。他们应当屏弃“做一天公平的工作，得一天公平的工资！”这种保守的格言，要在自己的旗帜上写上革命的口号：“消灭雇佣劳动制度！”","language":"中文","translation":false},{"id":"wages-price-1-159","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"为了阐明基本问题，我不得不作这样一个冗长的，恐怕是令人厌倦的说明。现在我提出下面的决议案来结束我的报告：","language":"中文","translation":false},{"id":"wages-price-1-160","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（1）工资水平的普遍提高，会引起一般利润率的降低。但整个说来并不影响商品的价格。","language":"中文","translation":false},{"id":"wages-price-1-161","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（2）资本主义生产的总趋势不是提高工资的平均水平，而是降低这个水平。","language":"中文","translation":false},{"id":"wages-price-1-162","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"（3）工联作为抵制资本进攻的中心，工作颇有成效。它们遭到失败，部分是由于不正确地使用自己的力量。总的说来，它们遭到失败是因为它们只限于进行游击式的斗争以反对现存制度所产生的结果，而不同时努力改变这个制度，不运用自己有组织的力量作为杠杆来最终解放工人阶级，也就是最终消灭雇佣劳动制度。","language":"中文","translation":false},{"id":"wages-price-1-163","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"写于1865年5月底─6月27日","language":"中文","translation":false},{"id":"wages-price-1-164","author":"马克思","title":"工资、价格和利润","location":"马克思：工资、价格和利润（1865年）","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1865-5.htm","text":"1898年第一次以单行本形式在伦敦出版","language":"中文","translation":false},{"id":"gotha-1-1","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"中文马克思主义文库 -> 马克思 相关链接：恩格斯","language":"中文","translation":false},{"id":"gotha-1-2","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"卡·马克思写于1875年4月—5月初","language":"中文","translation":false},{"id":"gotha-1-3","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"载于1891年“新时代”杂志第1卷第18期，并作了某些删节","language":"中文","translation":false},{"id":"gotha-1-4","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"中文根据“马克思恩格斯文选”两卷集","language":"中文","translation":false},{"id":"gotha-1-5","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"1953年柏林狄茨出版社德文版第2卷译出","language":"中文","translation":false},{"id":"gotha-1-6","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"· 卡·马克思“哥达纲领批判”序言（恩格斯，1891年1月6日）","language":"中文","translation":false},{"id":"gotha-1-7","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"· 给威·白拉克的信（马克思，1875年5月5日）","language":"中文","translation":false},{"id":"gotha-1-8","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"· 对德国工人党纲领的几点意见","language":"中文","translation":false},{"id":"gotha-1-9","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"Ø 一 Ø 二 Ø 三 Ø 四","language":"中文","translation":false},{"id":"gotha-1-10","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"卡·马克思“哥达纲领批判”序言[131]","language":"中文","translation":false},{"id":"gotha-1-11","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这里刊印的手稿——对纲领草案的批判以及给白拉克的附信——曾于1875年哥达合并代表大会[132]召开以前不久送给白拉克，请他转给盖布、奥艾尔、倍倍尔和李卜克内西过目，然后退还马克思。既然哈雷党代表大会[133]已把关于哥达纲领的讨论提上了党的议程，所以我认为，如果我还延迟发表这个有关这次讨论的重要的——也许是最重要的——文件，那我就要犯隐匿罪了。","language":"中文","translation":false},{"id":"gotha-1-12","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是，这个手稿还有另外的和更广泛的意义。其中第一次明确而坚定地表明了马克思对拉萨尔从他开始从事鼓动工作起就采取的方针的态度，并且同样地表明了对拉萨尔的经济学原则和策略的态度。","language":"中文","translation":false},{"id":"gotha-1-13","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这里用以剖析纲领草案的那种无情的尖锐性，用来表述得出的结论和揭露草案缺点的那种严厉性，——这一切在十五年以后的今天已不会使人见怪了。道地的拉萨尔主义者只是在国外还作为一些孤独的残余存在着，而哥达纲领甚至也被它的那些创造者们在哈雷当做完全不能令人满意的东西抛弃了。","language":"中文","translation":false},{"id":"gotha-1-14","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"虽然如此，凡是在对内容没有影响的地方，我还是把一些针对个别人的尖锐的词句和评语删掉了，而用省略号来代替。如果马克思今天发表这个手稿，他自己也会这样作的。手稿中有些地方口气很激烈，这是由下述两种情况引起的：第一，马克思和我对德国运动的关系，比对其他任何一国运动的关系都更为亲切；因此这个纲领草案中所表现的断然的退步，就不能不使我们感到特别愤慨。第二，我们那时正在同巴枯宁及其无政府主义者进行最激烈的斗争，——那时离国际海牙代表大会[134]闭幕才两年，——他们把德国工人运动中发生的一切都归咎于我们；因而我们不得不预料，他们也会诬指我们是这个纲领的秘密创作者。这些顾虑现在已经消失，因而一些有关的地方也就随之失去必要性了。","language":"中文","translation":false},{"id":"gotha-1-15","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"由于出版法的缘故，有些语句只用省略号暗示出来。凡是我不得不选用比较缓和的说法的地方，都加上了方括弧。其他地方都按手稿付印。","language":"中文","translation":false},{"id":"gotha-1-16","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"1891年1月6日于伦敦","language":"中文","translation":false},{"id":"gotha-1-17","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"载于1890—1891年“新时代”杂志第1卷第18期","language":"中文","translation":false},{"id":"gotha-1-18","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"1875年5月5日于伦敦","language":"中文","translation":false},{"id":"gotha-1-19","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"对合并纲领的下列批评意见，请您阅后转交盖布和奥艾尔、倍倍尔和李卜克内西过目。我工作太忙，已经不得不远远超过医生给我规定的工作时间。所以，写这么多张纸，对我来说决不是一种“享受”。但是，为了使党内的朋友们——而这些意见就是为他们写的——以后不致误解我这方面不得不采取的步骤，这是必要的。这里指的是，在合并大会以后，恩格斯和我将要发表的一个简短的声明，声明的内容是：我们和上述原则性纲领毫不相干，我们和它毫无共同之点。","language":"中文","translation":false},{"id":"gotha-1-20","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这样做是必要的，因为在国外有一种为党的敌人所热心支持的见解——一种完全荒谬的见解，仿佛我们在这里秘密地领导所谓爱森纳赫党的运动。例如巴枯宁还在他新近出版的一本俄文著作里要我不仅为这个党的所有纲领等等负责，甚至要为李卜克内西自从和人民党合作以来所采取的每一个步骤负责。","language":"中文","translation":false},{"id":"gotha-1-21","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"撇开这一点不谈，我的义务也不容许我即使只用外交式的沉默方法来承认一个我认为应当根本抛弃并且会使党瓦解的纲领。","language":"中文","translation":false},{"id":"gotha-1-22","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"一步实际运动要比一打纲领更为重要。所以，既然不可能——而局势也不容许这样做——超过爱森纳赫纲领，那就干脆缔结一个反对共同敌人的行动协定好了。但是，制定一个原则性纲领（应该是把这件事情推迟到由较长时间的共同工作准备好了的时候再做），这就是在全世界面前树立起一些可供人们用以判定党的运动水平的界碑。","language":"中文","translation":false},{"id":"gotha-1-23","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"拉萨尔派的领袖们之所以跑来靠拢我们，是因为他们为形势所迫。如果一开始就向他们声明决不会拿原则来做买卖，那末他们就只好满足于一个行动纲领或共同行动的组织计划了。可是并没有这样做，反而允许他们拿着全权委托书来出席，并且自己承认他们的这种全权委托书有效，就是说，向那些本身需要援助的人们无条件投降。不仅如此，他们甚至在召开妥协的代表大会以前就召开了代表大会，而自己的党却只是在事后才召开自己的代表大会。人们显然是想杜绝一切批评，不让自己的党有一个深思的机会。大家知道，合并这一事实本身是使工人感到满意的；但是，如果有人以为这种一时的成功不是用过高的代价换来的，那他就错了。","language":"中文","translation":false},{"id":"gotha-1-24","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"此外，即使这个纲领没有把拉萨尔的信条奉为神圣，也是完全不适宜的。","language":"中文","translation":false},{"id":"gotha-1-25","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"我将在最近把“资本论”法文版的最后几册寄给您。排印工作因法国政府禁止而耽搁了很久。在本星期内或下星期初本书可以印完。前六册您已经收到没有？请把伯恩哈特·贝克尔的地址也告诉我，我也要给他寄最后几册[14]去。","language":"中文","translation":false},{"id":"gotha-1-26","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“人民国家报”出版社有一种特别的习气。例如到现在为止连一本新版的“科伦共产党人案件”[15]也没有给我寄来。","language":"中文","translation":false},{"id":"gotha-1-27","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"对德国工人党纲领的几点意见","language":"中文","translation":false},{"id":"gotha-1-28","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"1．“劳动是一切财富和一切文化的源泉，而因为有益的劳动只有在社会里和通过社会才是可能的，所以劳动所得应当不折不扣和按照平等的权利属于社会一切成员。”","language":"中文","translation":false},{"id":"gotha-1-29","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"本段第一部分：“劳动是一切财富和一切文化的源泉。”","language":"中文","translation":false},{"id":"gotha-1-30","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"劳动不是一切财富的源泉。自然界和劳动一样也是使用价值（而物质财富本来就是由使用价值构成的！）的源泉，劳动本身不过是一种自然力的表现，即人的劳动力的表现。上面那句话在一切儿童识字课本里都可以找到，但是这句话只是在它包含着劳动具备了相应的对象和资料这层意思的时候才是正确的。然而，一个社会主义的纲领不应当容许这种资产阶级的说法，对那些唯一使这种说法具有意义的条件避而不谈。只有一个人事先就以所有者的身分来对待自然界这个一切劳动资料和劳动对象的第一源泉，把自然界当做隶属于他的东西来处置，他的劳动才成为使用价值的源泉，因而也成为财富的源泉，资产者有很充分的理由给劳动加上一种超自然的创造力，因为正是从劳动所受的自然制约性中才产生出如下的情况：一个除自己的劳动力外没有任何其他财产的人，在任何社会的和文化的状态中，都不得不为占有劳动的物质条件的他人做奴隶。他只有得到他人的允许才能劳动，因而只有得到他人的允许才能生存。","language":"中文","translation":false},{"id":"gotha-1-31","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是不管这句话缺点如何，我们且把它放在一旁，不去管它。那么结论应当怎样呢？显然应当是：","language":"中文","translation":false},{"id":"gotha-1-32","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“既然劳动是一切财富的源泉，社会中的任何一个人要不占有劳动的产品就不能占有财富。因此，如果他自己不劳动，他就是靠别人的劳动生活，而且他自己的文化也是靠别人的劳动获得的。”","language":"中文","translation":false},{"id":"gotha-1-33","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"可是并没有这样做，反而借助于“而因为”这种暧昧的字眼添上第二句话，以便从第二句中，而不是从第一句中作出结论来。","language":"中文","translation":false},{"id":"gotha-1-34","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"本段第二部分：“有益的劳动只有在社会里和通过社会才是可能的。”","language":"中文","translation":false},{"id":"gotha-1-35","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"根据第一句话，劳动是一切财富和一切文化的源泉，就是说，任何一个社会都不能离开劳动。相反地，我们现在却看到，任何一种“有益的”劳动都不能离开社会。","language":"中文","translation":false},{"id":"gotha-1-36","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"那么同样也可以说，只有在社会里，无益的、甚至有损公益的劳动才能成为一个职业部门，只有在社会里才可以游手好闲，如此等等，——一句话，可以抄袭卢梭的全部著作了。","language":"中文","translation":false},{"id":"gotha-1-37","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"而什么是“有益的”劳动呢？只不过是能产生预期效果的劳动。一个蒙昧人（而人在他已不再是猿类以后就是蒙昧人）用石头击毙野兽，采集果实等等，就是进行“有益的”劳动。","language":"中文","translation":false},{"id":"gotha-1-38","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第三，结论：“而因为有益的劳动只有在社会里和通过社会才是可能的，所以劳动所得应当不折不扣和按照平等的权利属于社会一切成员。”","language":"中文","translation":false},{"id":"gotha-1-39","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"多妙的结论！既然有益的劳动只有在社会里和通过社会才是可能的，劳动所得就应当属于社会，而单个的工人从中获得的仅仅是不必用来维持劳动“条件”即维持社会的那一部分。","language":"中文","translation":false},{"id":"gotha-1-40","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"事实上，这个论点在一切时代都被当时的社会制度的捍卫者所承认。首先要满足政府方面以及依附于它的各个方面的要求，因为政府是维持社会秩序的社会机关；其次要满足各种私有财产［注：在“马克思恩格斯全集”德文版第19卷中这里是：私有者。——译者注］方面的要求，因为各种私有财产是社会的基础，如此等等。你们看，这些空洞的辞句是随便怎么摆弄都可以的。","language":"中文","translation":false},{"id":"gotha-1-41","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"本段第一和第二两部分只有像下面这样说才能有些合乎情理的联系：","language":"中文","translation":false},{"id":"gotha-1-42","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“劳动只有作为社会的劳动”，或者换个说法，“只有在社会里和通过社会”，“才能成为财富和文化的源泉”。","language":"中文","translation":false},{"id":"gotha-1-43","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这个论点无可争辩地是正确的，因为孤立的劳动（假定它的物质条件是具备的）虽能创造使用价值，但它既不能创造财富，也不能创造文化。","language":"中文","translation":false},{"id":"gotha-1-44","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是另一个论点也是同样无可争辩的：","language":"中文","translation":false},{"id":"gotha-1-45","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“随着劳动的社会性的发展，以及由此而来的劳动之成为财富和文化的源泉，劳动者方面的贫穷和愚昧、非劳动者方面的财富和文化也发展起来。”","language":"中文","translation":false},{"id":"gotha-1-46","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这是到现时为止的全部历史的规律。因此，不应当泛泛地谈论“劳动”和“社会”，而应当在这里清楚地证明，在现今的资本主义社会中最终创造了物质的和其他的条件，使工人能够并且不得不铲除这个社会祸害［注：在“马克思恩格斯全集”德文版第19卷中这里是：历史祸害。——译者注］。","language":"中文","translation":false},{"id":"gotha-1-47","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"实际上，把这整个行文和内容都不妥当的条文放在这里，只不过是为了要把拉萨尔的“不折不扣的劳动所得”作为第一个口号写在党的旗帜上。以后我还要回过来谈“劳动所得”、“平等的权利”等等，因为同样的东西在下面又以稍微不同的形式重复出现。","language":"中文","translation":false},{"id":"gotha-1-48","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"2．“在现代社会中，劳动资料为资本家阶级所垄断。由此造成的工人阶级的依附性是一切形式的贫困和奴役的原因。”","language":"中文","translation":false},{"id":"gotha-1-49","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这段从国际章程中抄来的话，经过这番“修订”就变成荒谬的了。","language":"中文","translation":false},{"id":"gotha-1-50","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在现代社会中，劳动资料为土地所有者和资本家所垄断（地产的垄断甚至是资本垄断的基础）。无论是前一个或者后一个垄断者阶级，国际章程在有关条文中都没有提到。它谈到的是“劳动资料即生活源泉的垄断”。“生活源泉”这一补充语充分表明，劳动资料也包括土地。","language":"中文","translation":false},{"id":"gotha-1-51","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"其所以作这种修订，是因为拉萨尔由于现在大家都知道的理由仅仅攻击了资本家阶级，而没有攻击土地所有者。在英国，资本家多半不是他的工厂所在的那块土地的所有者。","language":"中文","translation":false},{"id":"gotha-1-52","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"3．“劳动的解放要求把劳动资料提高为社会的公共财产，要求集体调节总劳动并公平分配劳动所得。”","language":"中文","translation":false},{"id":"gotha-1-53","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“把劳动资料提高为社会的公共财产”（！），应当是说把它们“变为社会的公共财产”。这不过是顺便提一句罢了。","language":"中文","translation":false},{"id":"gotha-1-54","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"什么是“劳动所得”呢？是劳动的产品呢，还是产品的价值？如果是后者，那末，是产品的总价值呢，或者只是劳动新添加在消费掉的生产资料的价值上的那部分价值？","language":"中文","translation":false},{"id":"gotha-1-55","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“劳动所得”是拉萨尔为了代替明确的经济概念而提出的一个模糊观念。","language":"中文","translation":false},{"id":"gotha-1-56","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"什么是“公平的”分配呢？","language":"中文","translation":false},{"id":"gotha-1-57","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"难道资产者不是断定今天的分配是“公平的”吗？难道它事实上不是在现今的生产方式基础上唯一“公平的”分配吗？难道经济关系是由法权概念来调节，而不是相反地由经济关系产生出法权关系吗？难道各种社会主义宗派分子关于“公平的”分配不是有各种极为不同的观念吗？","language":"中文","translation":false},{"id":"gotha-1-58","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"为了弄清楚“公平的”分配一语在这里指什么东西，我们必须把第一段和本段对照一下。本段设想的是这样一个社会，在那里“劳动资料是公共财产，总劳动是由集体调节的”，而在第一段里我们则看到，“劳动所得应当不折不扣和按照平等的权利属于社会一切成员”。","language":"中文","translation":false},{"id":"gotha-1-59","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“属于社会一切成员”？也属于不劳动的成员吗？那么“不折不扣的劳动所得”又在哪里呢？只属于社会中劳动的成员吗？那么社会一切成员的“平等的权利”又在哪里呢？","language":"中文","translation":false},{"id":"gotha-1-60","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“社会一切成员”和“平等的权利”显然只是些空话。问题的实质在于：在这个共产主义社会里，每个劳动者都应当得到“不折不扣的”拉萨尔的“劳动所得”。","language":"中文","translation":false},{"id":"gotha-1-61","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"如果我们把“劳动所得”这个用语首先理解为劳动的产品，那末集体的劳动所得就是社会总产品。","language":"中文","translation":false},{"id":"gotha-1-62","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第一，用来补偿消费掉的生产资料的部分。","language":"中文","translation":false},{"id":"gotha-1-63","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第二，用来扩大生产的追加部分。","language":"中文","translation":false},{"id":"gotha-1-64","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第三，用来应付不幸事故、自然灾害等的后备基金或保险基金。","language":"中文","translation":false},{"id":"gotha-1-65","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"从“不折不扣的劳动所得”里扣除这些部分，在经济上是必要的，至于扣除多少，应当根据现有的资料和力量来确定，部分地应当根据概率论来确定，但是这些扣除根据公平原则无论如何是不能计算的。","language":"中文","translation":false},{"id":"gotha-1-66","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"剩下的总产品中的其他部分是用来作为消费资料的。","language":"中文","translation":false},{"id":"gotha-1-67","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在把这部分进行个人分配之前，还得从里面扣除：","language":"中文","translation":false},{"id":"gotha-1-68","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第一，和生产没有关系［注：在“马克思恩格斯全集”德文版第19卷中这里是：没有直接关系。——译者注］的一般管理费用。","language":"中文","translation":false},{"id":"gotha-1-69","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"和现代社会比起来，这一部分将会立即极为显著地缩减，并将随着新社会的发展而日益减少。","language":"中文","translation":false},{"id":"gotha-1-70","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第二，用来满足共同需要的部分，如学校、保健设施等。","language":"中文","translation":false},{"id":"gotha-1-71","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"和现代社会比起来，这一部分将会立即显著增加，并将随着新社会的发展而日益增加。","language":"中文","translation":false},{"id":"gotha-1-72","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第三，为丧失劳动能力的人等等设立的基金，总之，就是现在属于所谓官办济贫事业的部分。","language":"中文","translation":false},{"id":"gotha-1-73","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"只有现在才谈得上纲领在拉萨尔的影响下偏狭地专门注意的那种“分配”，就是说，才谈得上在集体中的个别生产者之间进行分配的那部分消费资料。","language":"中文","translation":false},{"id":"gotha-1-74","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“不折不扣的劳动所得”已经不知不觉地变成“有折有扣的”了，虽然从一个处于私人地位的生产者身上扣除的一切，又会直接或间接地用来为处于社会成员地位的这个生产者谋福利。","language":"中文","translation":false},{"id":"gotha-1-75","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"正如“不折不扣的劳动所得”一语消失了一样，“劳动所得”一语现在也在整个地消失。","language":"中文","translation":false},{"id":"gotha-1-76","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在一个集体的、以共同占有生产资料为基础的社会里，生产者并不交换自己的产品；耗费在产品生产上的劳动，在这里也不表现为这些产品的价值，不表现为它们所具有的某种物的属性，因为这时和资本主义社会相反，个人的劳动不再经过迂回曲折的道路，而是直接地作为总劳动的构成部分存在着。于是，“劳动所得”这个由于含意模糊就是现在也不能接受的用语，便失去了任何意义。","language":"中文","translation":false},{"id":"gotha-1-77","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"我们这里所说的是这样的共产主义社会，它不是在它自身基础上已经发展了的，恰好相反，是刚刚从资本主义社会中产生出来的，因此它在各方面，在经济、道德和精神方面都还带着它脱胎出来的那个旧社会的痕迹。所以，每一个生产者，在作了各项扣除之后，从社会方面正好领回他所给予社会的一切。他所给予社会的，就是他个人的劳动量。例如，社会劳动日是由所有的个人劳动小时构成的；每一个生产者的个人劳动时间就是社会劳动日中他所提供的部分，就是他在社会劳动日里的一分。他从社会方面领得一张证书，证明他提供了多少劳动（扣除他为社会基金而进行的劳动），而他凭这张证书从社会储存中领得和他所提供的劳动量相当的一分消费资料。他以一种形式给予社会的劳动量，又以另一种形式全部领回来。","language":"中文","translation":false},{"id":"gotha-1-78","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"显然，这里通行的就是调节商品交换（就它是等价的交换而言）的同一原则。内容和形式都改变了，因为在改变了的环境下，除了自己的劳动，谁都不能提供其他任何东西，另一方面，除了个人的消费资料，没有任何东西可以成为个人的财产。至于消费资料在各个生产者中间的分配，那末这里通行的是商品等价物的交换中也通行的同一原则，即一种形式的一定量的劳动可以和另一种形式的同量劳动相交换。","language":"中文","translation":false},{"id":"gotha-1-79","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"所以，在这里平等的权利按照原则仍然是资产阶级的法权，虽然原则和实践在这里已不再互相矛盾，而在商品交换中，等价物的交换只存在于平均数中，并不是存在于每个个别场合。","language":"中文","translation":false},{"id":"gotha-1-80","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"虽然有这种进步，但这个平等的权利还仍然被限制在一个资产阶级的框框里。生产者的权利是和他们提供的劳动成比例的；平等就在于以同一的尺度——劳动——来计量。","language":"中文","translation":false},{"id":"gotha-1-81","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是，一个人在体力或智力上胜过另一个人，因此在同一时间内提供较多的劳动，或者能够劳动较长的时间；而劳动，为了要使它能够成为一种尺度，就必须按照它的时间或强度来确定，不然它就不成其为尺度了。这种平等的权利，对不同等的劳动来说是不平等的权利。它不承认任何阶级差别，因为每个人都像其他人一样只是劳动者；但是它默认［注：在“马克思恩格斯全集”德文版第19卷中这里还有：劳动者的。——译者注］不同等的个人天赋，因而也就默认［注：在“马克思恩格斯全集”德文版第19卷中这里还有：劳动者的。——译者注］不同等的工作能力是天然特权。所以就它的内容来讲，它像一切权利一样是一种不平等的权利。权利，就它的本性来讲，只在于使用同一的尺度；但是不同等的个人（而如果他们不是不同等的，他们就不成其为不同的个人）要用同一的尺度去计量，就只有从同一个角度去看待他们，从一个特定的方面去对待他们，例如在现在所讲的这个场合，把他们只当做劳动者；再不把他们看做别的什么，把其他一切都撇开了。其次，一个劳动者已经结婚，另一个则没有；一个劳动者的子女较多，另一个的子女较少，如此等等。在劳动成果相同、从而由社会消费品中分得的份额相同的条件下，某一个人事实上所得到的比另一个人多些，也就比另一个人富些，如此等等。要避免所有这些弊病，权利就不应当是平等的，而应当是不平等的。","language":"中文","translation":false},{"id":"gotha-1-82","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是这些弊病，在共产主义社会第一阶段，在它经过长久的阵痛刚刚从资本主义社会里产生出来的形态中，是不可避免的。权利永远不能超出社会的经济结构以及由经济结构所制约的社会的文化发展。","language":"中文","translation":false},{"id":"gotha-1-83","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在共产主义社会高级阶段上，在迫使人们奴隶般地服从分工的情形已经消失，从而脑力劳动和体力劳动的对立也随之消失之后；在劳动已经不仅仅是谋生的手段，而且本身成了生活的第一需要之后；在随着个人的全面发展生产力也增长起来，而集体财富的一切源泉都充分涌流之后，——只有在那个时候，才能完全超出资产阶级法权的狭隘眼界，社会才能在自己的旗帜上写上：各尽所能，按需分配！","language":"中文","translation":false},{"id":"gotha-1-84","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"我较为详细地一方面谈到“不折不扣的劳动所得”，另一方面谈到“平等的权利”和“公平的分配”，这是为了要指出：这些人犯了多么大的罪，他们一方面企图把那些在某个时期曾经有一些意思，而现在已变成陈词滥调的见解作为教条重新强加于我们党，另一方面又打算用民主主义者和法国社会主义者所惯用的关于权利等等的空洞的废话，来歪曲那些花费了很大力量才灌输给党而现在已在党内扎了根的现实主义观点。","language":"中文","translation":false},{"id":"gotha-1-85","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"除了上述的一切之外，把所谓分配看做事物的本质并把重点放在它上面，那也是根本错误的。","language":"中文","translation":false},{"id":"gotha-1-86","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"消费资料的任何一种分配，都不过是生产条件本身分配的结果。而生产条件的分配，则表现生产方式本身的性质。例如，资本主义生产方式的基础就在于：物质的生产条件以资本和地产的形式掌握在非劳动者的手中，而人民大众则只有人身的生产条件，即劳动力。既然生产的要素是这样分配的，那末自然而然地就要产生消费资料的现在这样的分配。如果物质的生产条件是劳动者自己的集体财产，那末同样要产生一种和现在不同的消费资料的分配。庸俗的社会主义仿效资产阶级经济学家（一部分民主派又仿效庸俗社会主义）把分配看成并解释成一种不依赖于生产方式的东西，从而把社会主义描写为主要是在分配问题上兜圈子。既然真实的关系早已弄清楚了，为什么又要开倒车呢？","language":"中文","translation":false},{"id":"gotha-1-87","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"4．“劳动的解放应当是工人阶级的事情，对它说来，其他一切阶级只是反动的一帮。”","language":"中文","translation":false},{"id":"gotha-1-88","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"前一句是从国际章程的导言中抄来的，但是经过了“修订”。那里写道：“工人阶级的解放应当是工人自己的事情”，这里却说“工人阶级”应当解放——解放什么？——“劳动”。谁能了解，就让他去了解吧。","language":"中文","translation":false},{"id":"gotha-1-89","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"另一方面，作为一种补偿，后一句却纯粹引用了拉萨尔的话：“对它（工人阶级）说来，其他一切阶级只组成反动的一帮。”","language":"中文","translation":false},{"id":"gotha-1-90","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在“共产党宣言”里写道：“在当前同资产阶级对立的一切阶级中，只有无产阶级是真正革命的阶级。其余的阶级都随着大工业的发展而日趋衰落和灭亡，无产阶级却是大工业本身的产物。”[16]","language":"中文","translation":false},{"id":"gotha-1-91","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在这里，资产阶级作为大工业的体现者，对那些力求保持过时的生产方式所创造的一切社会阵地的封建主和中层等级说来，是被当做革命阶级看待的。所以他们并不是同资产阶级一起只组成反动的一帮。","language":"中文","translation":false},{"id":"gotha-1-92","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"另一方面，无产阶级对资产阶级说来是革命的，因为它本身是在大工业基地上成长起来的，它力求使生产摆脱资产阶级企图永远保存的资本主义性质。但是，“宣言”又补充说：“中间等级……是革命的，那是鉴于他们行将转入无产阶级的队伍。”","language":"中文","translation":false},{"id":"gotha-1-93","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"所以，从这个观点看来，说什么对工人阶级说来，中间等级“同资产阶级一起”并且加上封建主“只组成反动的一帮”，这也是荒谬的。","language":"中文","translation":false},{"id":"gotha-1-94","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"难道在最近这次选举中有人向手工业者、小工业家等等以及农民宣布说：“对我们说来，你们同资产者和封建主一起只组成反动的一帮”吗？","language":"中文","translation":false},{"id":"gotha-1-95","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"拉萨尔熟知“共产党宣言”，就像他的信徒熟知他写的福音书一样。他这样粗暴地歪曲“宣言”，不过是为了粉饰他同专制主义者和封建主义者这些敌人结成的反资产阶级联盟。","language":"中文","translation":false},{"id":"gotha-1-96","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"此外，在上面这一段里他的格言是勉强被塞进去的，它同那句从国际章程中摘来但被歪曲了的引语毫不相干。这纯粹是一种狂妄无耻的做法，这种做法当然绝对不是俾斯麦先生所不喜欢的，这是柏林的马拉[17]所干出来的廉价的无耻行径之一。","language":"中文","translation":false},{"id":"gotha-1-97","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"5．“工人阶级为了本身的解放，首先是在现代民族国家的范围内进行活动，同时意识到，它的为一切文明国家的工人所共有的那种意图必然导致的结果，将是各民族的国际的兄弟联合。”","language":"中文","translation":false},{"id":"gotha-1-98","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"同“共产党宣言”和先前的一切社会主义相反，拉萨尔以最狭隘的民族观点来对待工人运动。有人竟在这方面追随他，而且这是在国际的活动以后！","language":"中文","translation":false},{"id":"gotha-1-99","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"为了能够进行斗争，工人阶级必须在国内组成为一个阶级，而且它的直接的斗争舞台就是本国，这是不言而喻的。所以，它的阶级斗争不是就内容来说，而是像“共产党宣言”所指出“就形式来说”是本国范围内的斗争。但是，“现代民族国家的范围”，例如德意志帝国，本身在经济上又处在“世界市场的范围内”，而在政治上则处在“国家体系的范围内”。任何一个商人都知道，德国的贸易同时就是对外贸易，而俾斯麦先生的伟大恰好在于他实行一种国际的政策。","language":"中文","translation":false},{"id":"gotha-1-100","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"而德国工人党把自己的国际主义归结为什么呢？就是意识到它的意图所导致的结果将是“各民族的国际的兄弟联合”。这句话是从资产阶级的和平和自由同盟那里抄来的，它应当被当做各国工人阶级在反对各国统治阶级及其政府的共同斗争中的国际兄弟联合的等价物。这样，关于德国工人阶级的国际职责连一个字也没有提到！德国工人阶级就应当这样对付本国的、为反对工人阶级而已经同其他一切国家的资产者紧密联合起来的资产阶级和俾斯麦先生的国际阴谋政策！","language":"中文","translation":false},{"id":"gotha-1-101","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"实际上，这个纲领的国际主义，比那个自由贸易派的国际主义还差得难以估量。自由贸易派也说，它的意图所导致的结果是“各民族的国际的兄弟联合”。但是它还做一些事使贸易成为国际性的，而决不满足于一切民族各自在本国内从事贸易的意识。","language":"中文","translation":false},{"id":"gotha-1-102","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"各国工人阶级的国际活动绝对不依赖于“国际工人协会”的存在。“国际工人协会”只是要为这种活动创立一个中央机关的第一个尝试；这种尝试由于它所产生的推动力已留下了不可磨灭的成绩，但是在巴黎公社失败之后，已经不能再以它的第一个历史形态继续下去了。","language":"中文","translation":false},{"id":"gotha-1-103","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"俾斯麦的“北德报”为了取悦于自己的主人，宣称德国工人党在新纲领中放弃了国际主义，它的这种说法是完全正确的[18]。","language":"中文","translation":false},{"id":"gotha-1-104","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“德国工人党从这些原则出发，力求用一切合法手段来争取自由国家——和——社会主义社会，废除工资制度连同铁的工资现律——和——任何形式的剥削，消除一切社会的和政治的不平等。”","language":"中文","translation":false},{"id":"gotha-1-105","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"关于“自由”国家，我以后再讲。","language":"中文","translation":false},{"id":"gotha-1-106","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这样，德国工人党将来就不得不相信拉萨尔的“铁的工资规律”了！为了不让它埋没掉，竟胡说什么“废除工资制度（应当说：雇佣劳动制度）连同铁的工资规律”。如果我废除了雇佣劳动，那末我当然也废除了它的规律，不管这些规律是“铁的”还是海绵的。但是拉萨尔反对雇佣劳动的斗争几乎只是绕着这个所谓规律兜圈子。所以，为了证明拉萨尔派已经获得胜利，“工资制度连同铁的工资规律”都应当被废除掉，而不是不连同后者。","language":"中文","translation":false},{"id":"gotha-1-107","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"大家知道，在“铁的工资规律”中，除了从歌德的“永恒的、铁的、伟大的规律”［注：引自歌德的诗“神妙的”。——编者注］中抄来的“铁的”这个词以外，没有一样东西是拉萨尔的。“铁的”这个词是虔诚的信徒们借以互相识别的一个标记。但是，如果我接受带有拉萨尔印记因而是拉萨尔意义下的规律，那末我就不得不连同他的论据一块接受下来。这个论据是什么呢？正如朗格在拉萨尔死后不久的言行所表明的，这就是（朗格自己宣扬的）马尔萨斯的人口论[19]。但是，如果这个理论是正确的，那末，我即使把雇佣劳动废除了一百次，也还废除不了这个规律，因为在这种情况下，这个规律不仅支配着雇佣劳动制度，而且支配着一切社会制度。经济学家们五十多年以来正是以此为根据证明社会主义不能消除自然本身造成的贫困，而只能使它普遍化，使它同时分布在社会的整个表面上！","language":"中文","translation":false},{"id":"gotha-1-108","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是，这一切都不是主要的。完全撇开拉萨尔对这个规律的错误了解不谈，真正令人气愤的退步是在于：","language":"中文","translation":false},{"id":"gotha-1-109","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"自从拉萨尔死后，在我们党内，这样一种科学见解已经给自己开辟了道路，这就是工资不是它表面上呈现的那种东西，不是劳动的价值或价格，而只是劳动力的价值或价格的掩蔽形式。这样，过去关于工资的全部资产阶级见解以及对这种见解的全部批评都被彻底推翻了，并且弄清了：雇佣工人只有为资本家（因而也为他们的剩余价值的分享者）白白地劳动一定的时间，才被允许为维持自己的生活而劳动，就是说，才被允许生存；整个资本主义生产体系的中心问题就在于：用延长劳动日的办法，或者用提高生产率、从而使劳动力更加紧张的办法等等，来增加这个无偿劳动；因此，雇佣劳动制度是奴隶制度，而且社会劳动生产力愈发展，这种奴隶制度就愈残酷，不管工人得到的报酬较好或是较坏。而现在，当这个见解已经在我们党内愈来愈给自己开辟出道路的时候，竟有人倒退到拉萨尔的教条那里去，虽然他们应当知道，拉萨尔并不懂得什么是工资，而是跟着资产阶级经济学家把外表当做事物的本质。","language":"中文","translation":false},{"id":"gotha-1-110","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"这正像奴隶们最终发现了自己处于奴隶地位的秘密而举行起义时，其中有一个为陈旧观点所束缚的奴隶竟要在起义的纲领上写道：奴隶制度必须废除，因为在奴隶制度下，奴隶的给养最大限度不能超过一定的、非常低的标准！","language":"中文","translation":false},{"id":"gotha-1-111","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"我们党的代表们对这个在党员群众中广泛传播的见解竟能进行这样惊人的侵犯，仅仅这一件事实岂不就证明了他们在草拟妥协的纲领时轻率得多么令人不能容忍，多么缺乏责任感！","language":"中文","translation":false},{"id":"gotha-1-112","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"本段末尾“消除一切社会的和政治的不平等”这一不明确的语句，应当改成：随着阶级差别的消灭，一切由此差别产生的社会的和政治的不平等也就自行消失。","language":"中文","translation":false},{"id":"gotha-1-113","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“为了替社会问题的解决开辟道路，德国工人党要求在劳动人民的民主监督下依靠国家帮助建立生产合作社。无论在工业中，或是在农业中，生产合作社都必须普遍建立起来，以便从它们里面产生出调节总劳动的社会主义组织。”","language":"中文","translation":false},{"id":"gotha-1-114","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在拉萨尔的“铁的工资规律”之后，就是这个先知提出的救世良方。这里“道路开辟”得确实不错。现存的阶级斗争被换上了拙劣的报刊作家的空话：需要“开辟道路”来“解决”的“社会问题”。“调节总劳动的社会主义组织”不是从社会的革命转变过程中，而是从国家给予生产合作社的“国家帮助”中“产生出来”，并且这些生产合作社是由国家而不是由工人“建立起来”的。这真不愧为拉萨尔的幻想：靠国家贷款能够建设一个新社会，就像能够建设一条新铁路一样！","language":"中文","translation":false},{"id":"gotha-1-115","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"由于还知道点羞耻，于是就把“国家帮助”置于……“劳动人民”的民主监督之下。","language":"中文","translation":false},{"id":"gotha-1-116","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第一，德国的“劳动人民”大多数是农民而不是无产者。","language":"中文","translation":false},{"id":"gotha-1-117","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"第二，“民主的”这个词在德文里意思是“人民当权的”。什么是“劳动人民的人民当权的监督呢”？何况所说的是这样的劳动人民，他们通过向国家提出的这些要求表明他们充分意识到自己既没有当权，也没有成熟到当权的程度！","language":"中文","translation":false},{"id":"gotha-1-118","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在这里详细批评毕舍在路易－菲力浦时代为了对付法国社会主义者而开列并由“工场”[20]派的反动工人所采用的药方，那是多余的。主要的过失不在于把这个特殊的万灵药方写入了纲领，而在于从阶级运动的立场完全退到宗派运动的立场。","language":"中文","translation":false},{"id":"gotha-1-119","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"如果工人们力求在社会的范围内，首先是在本民族的范围内建立集体生产的条件，这只是表明，他们在争取变革现在的生产条件，而这同靠国家帮助建立合作社毫无共同之处。至于现存的合作社，那末它们之所以可贵，仅仅是因为它们是工人自己独立创设的，既不受政府的保护，也不受资产者的保护。","language":"中文","translation":false},{"id":"gotha-1-120","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"现在我们来谈民主的一节。","language":"中文","translation":false},{"id":"gotha-1-121","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"Ａ．“国家的自由基础”。","language":"中文","translation":false},{"id":"gotha-1-122","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"首先，照第二节的说法，德国工人党力求争取“自由国家”。","language":"中文","translation":false},{"id":"gotha-1-123","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"自由国家是个什么东西呢？","language":"中文","translation":false},{"id":"gotha-1-124","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"使国家变成“自由的”，这决不是已经摆脱了狭隘的奴才思想的工人的目的。在德意志帝国，“国家”差不多是和在俄国一样地“自由”。自由就在于把国家由一个站在社会之上的机关变成完全服从这个社会的机关；而且就在今天，各种国家形式比较自由或比较不自由，也取决于这些国家形式把“国家的自由”限制到什么程度。","language":"中文","translation":false},{"id":"gotha-1-125","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"德国工人党——至少是当它接受了这个纲领的时候——表明：它对社会主义思想领会得多么肤浅；它不把现存社会（对任何未来的社会也是一样）当做现存国家的基础（或者不把未来社会当做未来国家的基础），反而把国家当做一种具有自己的“精神的、道德的、自由的基础”的独立本质。","language":"中文","translation":false},{"id":"gotha-1-126","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"而且在纲领中还荒谬地滥用了“现代国家”、“现代社会”等字眼，甚至更荒谬地误解了向之提出自己要求的那个国家！","language":"中文","translation":false},{"id":"gotha-1-127","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“现代社会”就是存在于一切文明国度中的资本主义社会，它或多或少地摆脱了中世纪的杂质，或多或少地由于每个国度的特殊的历史发展而改变了形态，或多或少地发展了。“现代国家”却各不相同。它在普鲁士德意志帝国同在瑞士不一样，在英国同在美国不一样。所以，“现代国家”是一种虚构。","language":"中文","translation":false},{"id":"gotha-1-128","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是，不同的文明国度中的不同的国家，不管它们的形式如何纷繁，却有一个共同点：它们都建筑在资本主义多少已经发展了的现代资产阶级社会的基础上。所以，它们具有某些极重要的共同特征。在这个意义上可以谈“现代国家制度”，而未来就不同了，到那时“现代国家制度”现在的根基即资产阶级社会已经消亡了。","language":"中文","translation":false},{"id":"gotha-1-129","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"于是就产生了一个问题：在共产主义社会里国家制度会发生怎样的变化呢？换句话说，那时有哪些同现代国家职能相类似的社会职能保留下来呢？这个问题只能科学地回答；否则，即使你把“人民”和“国家”这两个名词联接一千次，也丝毫不会对这个问题的解决有所帮助。","language":"中文","translation":false},{"id":"gotha-1-130","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在资本主义社会和共产主义社会之间，有一个从前者变为后者的革命转变时期。同这个时期相适应的也有一个政治上的过渡时期，这个时期的国家只能是无产阶级的革命专政。","language":"中文","translation":false},{"id":"gotha-1-131","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是，这个纲领既没谈到无产阶级的革命专政，也没谈到未来共产主义社会的国家制度。","language":"中文","translation":false},{"id":"gotha-1-132","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"纲领的政治要求除了陈旧的［注：在“马克思恩格斯全集”德文版第19卷中这里没有：陈旧的。——译者注］、人所共知的民主主义的废话，如普选权、直接立法权、人民权利、人民军队等等之外，没有任何其他内容。这纯粹是资产阶级的人民党、和平和自由同盟的回声。所有这些要求凡不属于空想的，都已经实现了。不过实现了这些要求的国家不是在德意志帝国境内，而是在瑞士、美国等等。这类“未来的国家”就是现代的国家，虽然它是存在于德意志帝国的“范围”以外。","language":"中文","translation":false},{"id":"gotha-1-133","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是他们忘记了一点。既然德国工人党明确地声明，它是在“现代民族国家”内，就是说，是在自己的国家即普鲁士德意志帝国内进行活动，——否则，它的大部分要求就没有意义了，因为人们只要求他们所没有的东西——那末，它就不应该忘记主要的一点，这就是这一切美丽的东西都建立在承认所谓人民主权的基础上，所以它们只有在民主共和国内才是适宜的。","language":"中文","translation":false},{"id":"gotha-1-134","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"既然他们没有勇气［注：在“马克思恩格斯全集”德文版第19卷中这里有一个脚注：“1891年版是：既然他们不能。”——译者注］——而这是明智的，因为形势要求小心谨慎——像法国工人纲领在路易-菲力浦和路易-拿破仑时代那样要求民主共和国，那就不应当采取这个既不“诚实”也不体面的手法：居然向一个以议会形式粉饰门面、混杂着封建残余、已经受到资产阶级影响、按官僚制度组织起来、并以警察来保卫的、军事专制制度的国家，要求只有在民主共和国里才有意义的东西，并且还庄严地向这个国家保证：他们认为能够用“合法手段”争得这类东西！","language":"中文","translation":false},{"id":"gotha-1-135","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"庸俗的民主派把民主共和国看做千年王国，他们完全没有想到，正是在资产阶级社会的这个最后的国家形式里阶级斗争要进行最后的决战，——就连这样的庸俗的民主派也比这种局限于为警察所容许而为逻辑所不容许的范围内的民主主义高明得多。","language":"中文","translation":false},{"id":"gotha-1-136","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"事实上，他们是把“国家”了解为政府机器，或者了解为构成一个由于分工而和社会分离的独特机体的国家，这可以从下面的话得到证明：“德国工人党提出下列要求作为国家的经济基础：实行统一的累进所得税……”。赋税是政府机器的经济基础，而不是其他任何东西。在存在于瑞士的“未来国家”里，这种要求差不多已经实现了。所得税是以不同社会阶级的不同收入来源为前提，就是说，以资本主义社会为前提。所以，利物浦的财政改革派——以格莱斯顿的弟弟为首的资产者们——提出和这个纲领相同的要求，这是不足为奇的。","language":"中文","translation":false},{"id":"gotha-1-137","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"Ｂ．德国工人党提出下列要求作为国家的精神的和道德的基础：","language":"中文","translation":false},{"id":"gotha-1-138","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"1．通过国家去实施普遍的和平等的国民教育。实施普遍的义务教育。实施免费教育。”","language":"中文","translation":false},{"id":"gotha-1-139","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"平等的国民教育？他们怎样理解这句话呢？是不是以为在现代社会里（而所谈到的只能是现代社会）教育对一切阶级都可能是平等的呢？或者是要求上层阶级也被迫降到很低的教育水平——国民小学，即降到不仅唯一适合于雇佣工人的经济状况、而且唯一适合于农民的经济状况的教育水平呢？","language":"中文","translation":false},{"id":"gotha-1-140","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“实施普遍的义务教育。实施免费教育”。前者甚至存在于德国，后者就国民小学来说存在于瑞士和美国。如果说，在美国的几个州里，高等学校也是“免费的”，那末，事实上这不过是从总税收中替上层阶级支付了教育费用而已。顺便指出，Ａ．项第5条所要求的“免费诉讼”也是如此。刑事诉讼到处都是免费的；而民事诉讼几乎只涉及财产纠纷，因而几乎只和有产阶级有关。难道它们应当用人民的金钱来打官司吗？","language":"中文","translation":false},{"id":"gotha-1-141","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在关于学校的一段里，和国民小学一起至少还应当提出技术学校（理论的和实践的）。","language":"中文","translation":false},{"id":"gotha-1-142","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“通过国家来实施国民教育”是完全要不得的。用一般的法律来确定国民小学的经费、教员的资格、学习的科目等等，并且像美国那样通过国家视察员来监督这些法律规定的实施，这和指定国家为人民的教育者完全是两回事！相反地，应该使政府和教会一样地对学校不起任何影响。在普鲁士德意志帝国内（他们会说，他们谈的是“未来的国家”，但是这种空洞的遁辞在这里也无济于事，——我们已经看到，在这方面是怎样一回事了），倒是国家需要从人民方面受到严格的教育。","language":"中文","translation":false},{"id":"gotha-1-143","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"但是整个纲领，尽管满是民主的喧嚣，却彻头彻尾地感染了拉萨尔派的对国家的忠顺信仰，或者说感染了并不比前者好一些的对民主奇迹的信仰，或者说得更正确些，它是这两种同样背离社会主义的对奇迹的信仰的妥协。","language":"中文","translation":false},{"id":"gotha-1-144","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“科学自由”——普鲁士宪法中有一条就是这样写的。为什么把它写在这里呢？","language":"中文","translation":false},{"id":"gotha-1-145","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“信仰自由”！如果现在，在进行“文化斗争”[21]的时候，要想提醒自由主义者记住他们的旧口号，那末只有采用下面这样的形式才能做到这一点：每一个人都应当有可能实现自己的宗教需要，就像实现自己的肉体需要一样［注：在“马克思恩格斯全集”德文版第19卷中这里有一个脚注：“1891年版是：实现自己的宗教……需要一样。”——译者注］，不受警察干涉。但是工人党本来应当乘此机会说出自己的看法：资产阶级的“信仰自由”不过是容忍各种各样的宗教信仰自由而已，而工人党却力求把信仰从宗教的妖术中解放出来。但是他们不愿越过“资产阶级的”水平。","language":"中文","translation":false},{"id":"gotha-1-146","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"现在我就要讲完了，因为纲领中接下去的部分在里面并不是主要的。所以我在这里只简单地谈一谈。","language":"中文","translation":false},{"id":"gotha-1-147","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"其他任何国家的工人党都没有局限于这种含糊的要求，而总是明确地指出，在当前条件下多长的劳动日是正常的。","language":"中文","translation":false},{"id":"gotha-1-148","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"3．“限制妇女劳动和禁止童工。”","language":"中文","translation":false},{"id":"gotha-1-149","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"如果限制妇女劳动指的是劳动日的长短和工间休息等等，那末劳动日的正常化就应当已经包括了这个问题；否则，限制妇女劳动只能意味着在那些对妇女身体特别有害或者对女性不道德的劳动部门中禁止妇女劳动。如果指的就是这点，那就应当加以说明。","language":"中文","translation":false},{"id":"gotha-1-150","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“禁止童工”！这里绝对必须指出年龄界限。","language":"中文","translation":false},{"id":"gotha-1-151","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"普遍禁止童工是和大工业的存在不相容的，所以这是空洞的虔诚的愿望。","language":"中文","translation":false},{"id":"gotha-1-152","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"实行这一措施——如果可能的话——是反动的，因为在按照各种年龄严格调节劳动时间并采取其他保护儿童的预防措施的条件下，生产劳动和教育的早期结合是改造现代社会的最强有力的手段之一。","language":"中文","translation":false},{"id":"gotha-1-153","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"4．“对工厂工业、作坊工业和家庭工业实行国家监督。”","language":"中文","translation":false},{"id":"gotha-1-154","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在普鲁士德意志这样一个国家里，应该明确地要求，工厂视察员只有经过法庭才能撤换；每个工人都可以向法庭告发视察员的失职行为；视察员必须是医生出身。","language":"中文","translation":false},{"id":"gotha-1-155","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"在一个一般的工人纲领里面，这是一种微不足道的要求。无论如何应该明白说出，工人们完全不愿意由于担心竞争而让一般犯人受到牲畜一样的待遇，特别是不愿意使他们失掉改过自新的唯一手段即生产劳动。这是应当期望于社会主义者的最低限度的东西。","language":"中文","translation":false},{"id":"gotha-1-156","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"应该说明，“有效的”责任法是指什么东西。","language":"中文","translation":false},{"id":"gotha-1-157","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"顺便指出，在关于正常劳动日的一条中，忽略了工厂立法中关于卫生设施和安全措施等等那一部分。只有当这些规定遭到破坏时，责任法才发生效力。","language":"中文","translation":false},{"id":"gotha-1-158","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"总之，这一部分也是写得很草率的。","language":"中文","translation":false},{"id":"gotha-1-159","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"Dixi et salvavi animam meam〔我已经说了，我已经拯救了自己的灵魂〕。","language":"中文","translation":false},{"id":"gotha-1-160","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[131] 恩格斯为发表卡·马克思的著作“哥达纲领批判”（见“马克思恩格斯全集”中文版第19卷第11—35页）写了这篇序言。“哥达纲领批判”是科学共产主义最重要的纲领性文献，同时是对机会主义进行不调和斗争的典范，恩格斯发表它，是为了给德国社会民主党里活跃起来的机会主义分子以打击，这在党即将在爱尔福特代表大会上讨论并通过新的纲领来代替哥达纲领的时候是特别重要的。恩格斯在发表“哥达纲领批判”时，不得不克服来自德国社会民主党的领导人方面的某种反对。他在发表时所做的一些小删节以及将某些尖锐的词句改成别的说法，在很大的程度上是“新时代”杂志的出版者狄茨和编辑卡·考茨基的立场所引起的。这一著作发表后，德国社会民主党国会党团和“前进报”编辑部对它不表欢迎。但是，正如恩格斯所预见的，无论是在德国党内，还是在其他国家的社会主义者当中，马克思的这一著作都受到了欢迎，其他国家的社会主义者把这一著作看做整个国际社会主义运动的纲领性文献。","language":"中文","translation":false},{"id":"gotha-1-161","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“哥达纲领批判”和恩格斯的序言，在恩格斯生前没有再版。根据路易莎·考茨基的手抄副本译出的“哥达纲领批判”的全文，于1932年在苏联第一次发表。第19卷所载这篇著作，是第一次根据马克思列宁主义研究院搜集到的马克思亲笔手稿译出发表的。——第105页。","language":"中文","translation":false},{"id":"gotha-1-162","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[132] 在1875年5月22—27日哥达代表大会上，德国工人运动中的两个派别——由奥·倍倍尔和威·李卜克内西领导的社会民主工党（爱森纳赫派）在拉萨尔派全德工人联合会——实行了合并。合并后的党叫做德国社会主义工人党。这样，德国工人阶级队伍中的分裂是克服了。但是，向哥达代表大会提出的合并起来的党的纲领草案（主要起草人是威·李卜克内西，他在这个问题上采取了妥协的立场）有严重的错误，在原则上对拉萨尔派作了让步。马克思和恩格斯虽然对建立德国统一的社会主义政党这件事表示赞许，但是反对在思想上同拉萨尔派妥协，他们尖锐地批评了纲领草案的错误论点，可是该草案只是略加修改就被代表大会通过了。——第105页。","language":"中文","translation":false},{"id":"gotha-1-163","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[133] 1890年10月12—18日的德国社会民主党哈雷代表大会，是在反社会党人非常法废除后举行的第一次代表大会。根据威·李卜克内西的提议，代表大会决定起草一个新纲领草案，提交将在爱尔福特举行的下届党代表大会，并在下届代表大会召开前三个月内把新纲领草案公布，以便在各地方党组织里和在报刊上讨论。——第105页。","language":"中文","translation":false},{"id":"gotha-1-164","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[134] 国际工人协会海牙代表大会是在1872年9月2—7日召开的。和过去历次代表大会相比，海牙代表大会按其组成来说是最有代表性的大会。出席这次代表大会的有代表15个全国性组织的65名代表。马克思和恩格斯亲自领导了这次代表大会。在代表大会上，马克思、恩格斯和他们的战友们多年来为反对工人运动中的各种小资产阶级宗派主义而进行的斗争胜利结束了。无政府主义者的分裂活动受到谴责，他们的领导者被开除出国际。海牙代表大会的决议为将来建立各国独立的工人阶级政党奠定了基础。——第106页。","language":"中文","translation":false},{"id":"gotha-1-165","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[13] 卡·马克思的著作“哥达纲领批判”，是对科学共产主义理论的根本问题的发展的重大贡献，是对机会主义进行不调和的斗争的典范，于1875年4—5月初写成，并于1875年5月5日寄给了爱森纳赫派的领导（给威·白拉克）。这一著作包含了对将要合并的社会民主党的纲领草案的批评意见，这些意见是为在哥达举行的合并大会而准备的。","language":"中文","translation":false},{"id":"gotha-1-166","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“哥达纲领批判”是恩格斯于1891年不顾德国社会民主党的机会主义领导的反对而首先发表的。它当时刊登在德国社会民主党的理论性机关刊物“新时代”杂志1891年第1卷第18期上，并附有恩格斯的说明。","language":"中文","translation":false},{"id":"gotha-1-167","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"恩格斯在发表“哥达纲领批判”的同时，也一起发表了直接同它有关的马克思在1875年5月5日给威·白拉克的信。","language":"中文","translation":false},{"id":"gotha-1-168","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"正如大家从恩格斯1891年2月23日给卡·考茨基的信中所知道的，在发表“哥达纲领批判”时，恩格斯不得不同意缓和某些最尖锐的地方。收集在本版中的这一文件是同马克思的手稿完全一致的。——第11页。","language":"中文","translation":false},{"id":"gotha-1-169","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[14] 指作者亲自校订的“资本论”第一卷的法文译本，这一译本于1872—1875年在巴黎分册出版。——第14页。","language":"中文","translation":false},{"id":"gotha-1-170","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[15] 指马克思的著作“揭露科伦共产党人案件”的第二版（见“马克思恩格斯全集”中文版第8卷第457—536页），它是由社会民主工党中央机关报“人民国家报”编辑部所属的该党的出版社于1875年在莱比锡出版的。——第14页。","language":"中文","translation":false},{"id":"gotha-1-171","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[16] 见“马克思恩格斯全集”中文版第4卷第476页。——第24页。","language":"中文","translation":false},{"id":"gotha-1-172","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[17] 马克思在这里大概是把“新社会民主党人报”的主编哈赛尔曼讽刺地称为马拉。","language":"中文","translation":false},{"id":"gotha-1-173","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“新社会民主党人报”（《Neuer Social-Demokrat》）是从1871年至1876年在柏林每周出版三次的德文报纸，拉萨尔派的全德工人联合会的机关报。该报的方针完全反映了拉萨尔派所执行的迎合俾斯麦制度和巴结德国统治阶级的政策，反映了拉萨尔派领袖的机会主义和民族主义。该报站在宗派主义的立场上，一贯反对国际的马克思主义的领导，反对德国社会民主工党，支持巴枯宁分子和其他反无产阶级流派的人们所进行的仇视总委员会的活动。——第25页。","language":"中文","translation":false},{"id":"gotha-1-174","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[18] 马克思指的是1875年3月20日“北德总汇报”就德国社会民主党的纲领草案发表的一篇社论；文章同时指出，“社会民主党的鼓动在某些方面变得比较谨慎了：它在背弃国际”。","language":"中文","translation":false},{"id":"gotha-1-175","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"“北德总汇报”（《Norddeutsche Allgemeine Zeitung》）是反动的日报，在六十至八十年代是俾斯麦政府的机关报；1861年至1918年在柏林出版。——第26页。","language":"中文","translation":false},{"id":"gotha-1-176","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[19] 指弗·阿·朗格在其著作“工人问题对现在和将来的意义”1865年杜斯堡版第144—161、180页（《Die Arbeiterfrage in ihrer Be-deutung für Gegenwart und Zukunft》．Duisburg，1865，S．144-161，180）上所发表的言论。——第27页。","language":"中文","translation":false},{"id":"gotha-1-177","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":177,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[20] “工场”（《L’Atelier》）是一种法文月刊，受基督教社会主义思想影响的手工业者和工人的刊物，1840年至1850年在巴黎出版，编辑部由工人代表组成，每三月改选一次。——第29页。","language":"中文","translation":false},{"id":"gotha-1-178","author":"马克思","title":"哥达纲领批判","location":"马克思：哥达纲领批判（写于1875年4－5月）","page":1,"paragraph":178,"url":"https://www.marxists.org/chinese/marx/marxist.org-chinese-marx-1875-4.htm","text":"[21] “文化斗争”是资产阶级自由派给俾斯麦政府在十九世纪七十年代采取的一套法律措施所起的名称。这套措施是在为世俗文化而斗争的幌子下实行的，其目的是反对天主教，反对支持德国西南部中小各邦的官吏、地主和资产阶级的分裂主义和反普鲁士倾向的“中央”党。在八十年代，俾斯麦为了纠集反动力量把这些措施中的大部分取消了。——第34页。","language":"中文","translation":false},{"id":"principles-1-1","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"中文马克思主义文库 -> 恩格斯","language":"中文","translation":false},{"id":"principles-1-2","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第一个问题：什么是共产主义？","language":"中文","translation":false},{"id":"principles-1-3","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：共产主义是关于无产阶级解放的条件的学说。","language":"中文","translation":false},{"id":"principles-1-4","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二个问题：什么是无产阶级？","language":"中文","translation":false},{"id":"principles-1-5","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：无产阶级是完全靠出卖自己的劳动而不是靠某一种资本的利润来获得生活资料的社会阶级。这一阶级的祸福、存亡和整个生存，都取决于对劳动的需求，即取决于生意的好坏，取决于不受限制的竞争的波动。一句话，无产阶级或无产者阶级是19世纪的劳动阶级。","language":"中文","translation":false},{"id":"principles-1-6","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第三个问题：是不是说，无产者不是一向就有的？","language":"中文","translation":false},{"id":"principles-1-7","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：是的，不是一向就有的。穷人和劳动阶级一向就有；并且劳动阶级通常都是贫穷的。但是，生活在上述条件下的这种穷人、这种工人，即无产者，并不是一向就有的，正如竞争并不一向是自由和不受限制的一样。","language":"中文","translation":false},{"id":"principles-1-8","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第四个问题：无产阶级是怎样产生的？","language":"中文","translation":false},{"id":"principles-1-9","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：无产阶级是由于工业革命而产生的，这一革命在上个世纪下半叶发生于英国，后来，相继发生于世界各文明国家。工业革命是由蒸汽机、各种纺纱机、机械织布机和一系列其他机械装备的发明而引起的。这些价钱很贵、因而只有大资本家才买得起的机器，改变了以前的整个生产方式，挤掉了原来的工人。这是因为机器生产的商品要比工人用不完善的纺车和织布机生产的又便宜又好。这样一来，这些机器就使工业全部落到大资本家手里，并且使工人仅有的一点薄产(工具、织布机等)变得一钱不值，于是资本家很快就占有了一切，而工人却一无所有了。从此，在衣料生产方面就实行了工厂制度。机器和工厂制度一经采用，这一制度很快就推行到所有其他工业部门，特别是印花业、印书业、制陶业和金属品制造业等部门。工人之间的分工越来越细，于是，从前完成整件工作的工人，现在只做这件工作的一部分。这种分工可以使产品生产得更快，因而也更便宜。分工把每个工人的活动变成一种非常简单的、老一套的机械操作，这种操作利用机器不但能够做得同样出色，甚至还要好得多。因此，所有这些工业部门都像纺纱和织布业一样，一个跟著一个全都受到了蒸汽动力、机器和工厂制度的支配。这样一来，这些工业部门同时也就全都落到了大资本家的手里，工人也就失掉了最后的一点独立性。除了原来意义上的工场手工业，手工业也渐渐受到工厂制度的支配，因为这里的大资本家也在通过建立可以大量节省开支和实行细致分工的大作坊，不断挤掉小师傅。结果，我们现在可以看到，在文明国家里，几乎所有劳动部门都照工厂方式进行经营了，在所有劳动部门，手工业和工场手工业几乎都被工业挤掉了。于是从前的中间等级，特别是小手工业师傅日益破产，工人原来的状况发生了根本的变化，产生了两个逐渐并吞所有其他阶级的新阶级。这两个阶级就是：","language":"中文","translation":false},{"id":"principles-1-10","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"一、大资本家阶级，他们在所有文明国家里现在已经几乎独占了一切生活资料和生产这些生活资料所必须的原料和工具(机器、工厂)。这就是资产者阶级或资产阶级。","language":"中文","translation":false},{"id":"principles-1-11","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"二、完全没有财产的阶级，他们为了换得维持生存所必须的生活资料，不得不把自己的劳动出卖给资产者。这个阶级叫作无产者阶级或无产阶级。","language":"中文","translation":false},{"id":"principles-1-12","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第五个问题：无产者是在怎样的条件下把劳动出卖给资产者的？","language":"中文","translation":false},{"id":"principles-1-13","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：劳动和其他任何商品一样，也是一种商品，因此，它的价格和其他任何商品的价格一样，也是由同样的规律决定的。正像我们下面将看到的，在大工业或自由竞争的统治下，情形都一样，商品的价格平均总是和这种商品的生产费用相等的。因此，劳动的价格也是和劳动的生产费用相等的。而劳动的生产费用正好是使工人能够维持他们的劳动能力并使工人阶级不致灭绝所必需的生活资料的数量。工人的劳动所得不会比为了这一目的所必需的更多。因此，劳动的价格或工资将是维持生存所必需的最低额。但是，因为买卖有时清淡有时兴旺，工人的所得也就有多有少，正像厂主出卖商品所得有多有少一样。如果把旺季和淡季平均起来，厂主出卖商品所得既不多于他的生产费用，也不少于他的生产费用，同样，工人平均所得也是既不会多于这个最低额，也不会少于这个最低额。大工业越是在所有劳动部门占统治地位，工资的这一经济规律体现得就越充分。","language":"中文","translation":false},{"id":"principles-1-14","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第六个问题：在工业革命前，有过什么样的劳动阶级？","language":"中文","translation":false},{"id":"principles-1-15","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：在不同的社会发展阶段上，劳动阶级的生活条件各不相同，劳动阶级在同有产阶级和统治阶级的关系中所处的地位也各不相同。在古代，劳动者是主人的奴隶。直到今天在许多落后国家甚至美国南部他们还是这种奴隶。在中世纪，劳动者是土地占有者贵族的农奴，直到今天在匈牙利、波兰和俄国他们还是这种农奴。此外，在中世纪，直到工业革命前，城市里还有在小资产阶级师傅那里做工的手工业帮工，随著工场手工业的发展，也渐渐出现了受较大的资本家雇用的工场手工业工人。","language":"中文","translation":false},{"id":"principles-1-16","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第七个问题：无产者和奴隶有什么区别？","language":"中文","translation":false},{"id":"principles-1-17","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：奴隶一次就被完全卖掉了。无产者必须一天一天、一小时一小时地出卖自己。单个的奴隶是某一个主人的财产，由于他与主人利害攸关，他的生活不管怎样坏，总还是有保障的。单个的无产者可以说是整个资产者阶级的财产，他的劳动只有在有人需要的时候才能卖掉，因而他的生活是没有保障的。只有对整个无产者阶级来说，这种生活才是有保障的。奴隶处在竞争之外，无产者处在竞争之中，并且亲身感受到竞争的一切波动。奴隶被看作物，不被看作市民社会的成员。无产者被承认是人，是市民社会的成员。因此奴隶能够比无产者生活得好些，但无产者属于更高的社会发展阶段，他们本身处于比奴隶更高的阶段。在所有的私有制关系中，只要废除奴隶制关系，奴隶就能解放自己，并由此而成为无产者；无产者只有废除一切私有制才能解放自己。","language":"中文","translation":false},{"id":"principles-1-18","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第八个问题：无产者和农奴有什么区别？","language":"中文","translation":false},{"id":"principles-1-19","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：农奴占有并使用一种生产工具，即一块土地，为此他要交出自己的一部份收益或者服一定的劳役。无产者用别人的生产工具为这个别人做工，从而得到一部份收益。农奴是交出，无产者是得到。农奴生活有保障，无产者生活无保障。农奴处在竞争之外，无产者处在竞争之中。农奴可以通过各种道路获得解放：或者是逃到城市里去做手工业者；或者是交钱给地主代替劳役和产品，从而成为自由的佃农；或者是把他们的封建主赶走，自己变成财产所有者。总之，农奴可以通过不同的办法加入有产阶级的队伍并进入竞争领域而获得解放。无产者只有通过消灭竞争、私有制和一切阶级差别才能获得解放。","language":"中文","translation":false},{"id":"principles-1-20","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第九个问题：无产者和手工业者有什么区别？","language":"中文","translation":false},{"id":"principles-1-21","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十个问题：无产者和工场手工业工人有什么区别？","language":"中文","translation":false},{"id":"principles-1-22","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：16至18世纪，几乎任何地方的工场手工业工人都占有生产工具，如织布机、家庭用的纺车和一小块在工余时间耕种的土地。这一切，无产者都没有。工场手工业工人几乎总是生活在农村，和地主或雇主维持著或多或少的宗法关系。无产者通常生活在大城市，和雇主只有金钱关系。大工业使工场手工业工人脱离了宗法关系，他们失去了仅有的一点财产，因此而变成无产者。","language":"中文","translation":false},{"id":"principles-1-23","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十一个问题：工业革命和社会划分为资产者与无产者首先产生了什么结果？","language":"中文","translation":false},{"id":"principles-1-24","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：第一，由于在世界各国机器劳动不断降低工业品的价格，旧的工场手工业制度或以手工劳动为基础的工业制度完全被摧毁。所有那些迄今或多或少置身于历史发展之外、工业迄今建立在工场手工业基础上的半野蛮国家，随之也就被迫脱离了它们的闭关自守状态。这些国家购买比较便宜的英国商品，把本国的工场手工业工人置于死地。因此，那些几千年来没有进步的国家，例如印度，都已经进行了完全的革命，甚至中国现在也正走向革命。事情已经发展到这样的地步：今天英国发明的新机器，一年之内就会夺去中国千百万工人的饭碗。这样，大工业便把世界各国人民互相联系起来，把所有地方性的小市场联合成为一个世界市场，到处为文明和进步作好了准备，使各文明国家里发生的一切必然影响到其余各国。因此，如果现在英国或法国的工人获得解放，这必然会引起其他一切国家的革命，这种革命迟早会使这些国家的工人也获得解放。","language":"中文","translation":false},{"id":"principles-1-25","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二，凡是大工业代替了工场手工业的地方，工业革命都使资产阶级及其财富和势力最大限度地发展起来，使它成为国内的第一阶级。结果，凡是完成了这种过程的地方，资产阶级都取得了政治权力，并挤掉了以前的统治阶级——贵族、行会师傅和代表他们的专制王朝。资产阶级废除了长子继承权或出卖领地的禁令，取消了贵族的一切特权，这样便消灭了特权贵族、土地贵族的势力。资产阶级取消了所有行会，废除了手工业者的一切特权，这样便摧毁了行会师傅的势力。资产阶级用自由竞争来代替它们；在自由竞争这种社会状况下，每一个人都有权经营任何一个工业部门，而且，除非缺乏必要的资本，什么也不能妨碍他的经营。这样，实行自由竞争就是公开宣布：从今以后，只是由于社会各成员的资本多寡不等，所以他们之间才不平等，资本成为决定性的力量，从而资本家，资产者成为社会上的第一阶级。但是，自由竞争在大工业发展初期之所以必要是因为只有在这种社会状况下大工业才能成长起来。资产阶级这样消灭了贵族和行会师傅的社会势力以后，也就消灭了他们的政治权力。资产阶级在社会上上升为第一阶级以后，它也就在政治上宣布自己是第一阶级。它是通过实行代议制而做到这一点的。代议制是以资产阶级的在法律面前平等和法律承认自由竞争为基础的。这种制度在欧洲各国采取立宪君主制的形式。在这种立宪君主制的国家里，只有拥有一定资本的人即资产者，才有选举权。这些资产者选民选出议员，而这些资产者议员可以运用拒绝纳税的权利，选出资产者政府。","language":"中文","translation":false},{"id":"principles-1-26","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第三，工业革命到处都使无产阶级和资产阶级以同样的速度发展起来。资产者越发财，无产者的人数也就越多。因为只有资本才能使无产者找到工作，而资本只有在使用劳动的时候才能增加，所以无产阶级的增加和资本的增加是完全同步的。同时，工业革命使资产者和无产者都集中在最有利于发展工业的大城市里，广大群众聚集在一个地方，使无产者意识到自己的力量。其次，随著工业革命的发展，随著挤掉手工劳动的新机器的不断发明，大工业把工资压得越来越低，把它压到上面说过的最低额，因而无产阶级的处境也就越来越不堪忍受了。这样，一方面由于无产阶级不满情绪的增长，另一方面由于他们力量的壮大，工业革命便孕育著一个由无产阶级进行的社会革命。","language":"中文","translation":false},{"id":"principles-1-27","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十二个问题：工业革命进一步产生了什么结果？","language":"中文","translation":false},{"id":"principles-1-28","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：大工业创造了像蒸汽机和其他机器那样的手段，使工业生产在短时间内用不多的费用便能无限地增加起来。由于生产变得这样容易，这种大工业必然产生的自由竞争很快就达到十分剧烈的程度。大批资本家投身于工业，生产很快就超过了消费。结果，生产出来的商品卖不出去，所谓商业危机就到来了。工厂只好关门，厂主破产，工人挨饿。到处出现了极度贫困的现象。过了一段时间，过剩的产品卖光了，工厂重新开工，工资提高，生意也渐渐地比以往更好起来。但这是不会长久的，因为很快又会生产出过多的商品，新的危机又会到来，这种新危机的过程和前次危机完全相同。因此，从本世纪初以来，工业经常在繁荣时期和危机时期之间波动。这样的危机几乎定期地每五年到七年发生一次，每一次它都给工人带来极度的贫困，激起普遍的革命热情，给整个现存制度造成极大的危险。","language":"中文","translation":false},{"id":"principles-1-29","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十三个问题：这种定期重复的商业危机会产生什么后果？","language":"中文","translation":false},{"id":"principles-1-30","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：第一，虽然大工业在它的发展初期自己创造了自由竞争，但是现在它的发展已经超越了自由竞争的范围。竞争和个人经营工业生产已经变成大工业的枷锁，大工业必须粉碎它，而且一定会粉碎它。大工业只要还在现今的基础上进行经营，就只能通过每七年出现一次的普遍混乱来维持，每次混乱对全部文明都是一种威胁，它不但把无产者抛入贫困的深渊，而且也使许多资产者破产。因此，或者必须完全放弃大工业本身(这是绝对不可能的)，或者大工业使建立一个全新的社会组织成为绝对必要的，在这个新的社会组织里，工业生产将不是由相互竞争的单个的厂主来领导，而是由整个社会按照确定的计划和所有人的需要来领导。","language":"中文","translation":false},{"id":"principles-1-31","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二，大工业及其所引起的生产无限扩大的可能性，使人们能够建立这样一种社会制度，在这种社会制度下，一切生活必需品都将生产得很多，使每一个社会成员都能够完全自由地发展和发挥他的全部力量和才能。由此可见，在现今社会中造成一切贫困和商业危机的大工业的那种特性，在另一种社会组织中正是消灭这种贫困和这些灾难性的波动的因素。","language":"中文","translation":false},{"id":"principles-1-32","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"这就完全令人信服地证明：","language":"中文","translation":false},{"id":"principles-1-33","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(1)从现在起，可以把所有这些弊病完全归咎于已经不适应当前情况的社会制度；","language":"中文","translation":false},{"id":"principles-1-34","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(2)通过建立新的社会制度来彻底铲除这些弊病的手段已经具备。","language":"中文","translation":false},{"id":"principles-1-35","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十四个问题：这种新的社会制度应当是怎样的？","language":"中文","translation":false},{"id":"principles-1-36","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：这种新的社会制度首先必须剥夺相互竞争的个人对工业和一切生产部门的经营权，而代之以所有这些生产部门由整个社会来经营，就是说，为了共同的利益、按照共同的计划、在社会全体成员的参加下来经营。这样，这种新的社会制度将消灭竞争，而代之以联合。因为个人经营工业的必然结果是私有制，竞争不过是单个私有者经营工业的一种方式，所以私有制同工业的个体经营和竞争是分不开的。因此私有制也必须废除，而代之以共同使用全部生产工具和按照共同的协议来分配全部产品，即所谓财产共有。废除私有制甚至是工业发展必然引起的改造整个社会制度的最简明扼要的概括。所以共产主义者完全正确地强调废除私有制是自己的主要要求。","language":"中文","translation":false},{"id":"principles-1-37","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十五个问题：这么说，过去废除私有制是不可能的？","language":"中文","translation":false},{"id":"principles-1-38","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：不可能。社会制度中的任何变化，所有制关系中的每一次变革，都是产生了同旧的所有制关系不再相适应的新的生产力的必然结果。私有制本身就是这样产生的。私有制不是一向就有的；在中世纪末期，产生了一种工场手工业那样的新的生产方式，这种新的生产方式超越了当时封建和行会所有制的范围，于是这种已经超越旧的所有制关系的工场手工业便产生了新的所有制形式——私有制。对于工场手工业和大工业发展的最初阶段来说，除了私有制，不可能有其他任何所有制形式，除了以私有制为基础的社会制度，不可能有其他任何社会制度。只要生产的规模还没有达到不仅可以满足所有人的需要，而且还有剩余产品去增加社会资本和进一步发展生产力，就总会有支配社会生产力的统治阶级和贫穷的被压迫阶级。至于这些阶级是什么样子，那要看生产的发展阶段。在依赖农业的中世纪，是领主和农奴；在中世纪后期的城市里，是行会师傅、帮工和短工；在17世纪是工场手工业主和工场手工业工人；在19世纪是大工厂主和无产者。非常明显，在这以前，生产力还没有发展到私有制成为这些生产力发展的桎梏和障碍。但是现在，由于大工业的发展，第一，产生了空前大规模的资本和生产力，并且具备了能在短时期内无限提高这些生产力的手段；第二，生产力集中在少数资产者手里，而广大人民群众越来越变成无产者，资产者的财富越增加，无产者的境遇就越悲惨和难以忍受；第三，这种强大的、容易增长的生产力，已经发展到私有制和资产者远远不能驾驭的程度，以致经常引起社会制度极其剧烈的震荡。只有这时废除私有制才不仅可能，甚至完全必要。","language":"中文","translation":false},{"id":"principles-1-39","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十六个问题：能不能用和平的办法废除私有制？","language":"中文","translation":false},{"id":"principles-1-40","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：但愿如此，共产主义者当然是最不反对这种办法的人。共产主义者很清楚，任何密谋都不但无益，甚至有害。他们很清楚，革命不能故意地、随心所欲地制造，革命在任何地方和任何时候都是完全不以单个政党和整个阶级的意志和领导为转移的各种情况的必然结果。但他们也看到，几乎所有文明国家的无产阶级的发展都受到暴力压制，因而是共产主义者的敌人用尽一切力量引起革命。如果被压迫的无产阶级因此最终被推向革命，那时，我们共产主义者将用行动来捍卫无产者的事业，正像现在用语言来捍卫它一样。","language":"中文","translation":false},{"id":"principles-1-41","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十七个问题：能不能一下子就把私有制废除？","language":"中文","translation":false},{"id":"principles-1-42","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：不，不能，正像不能一下子就把现有的生产力扩大到为实行财产公有所必要的程度一样。因此，很可能就要来临的无产阶级革命，只能逐步改造现社会，只有创造了所必需的大量生产资料之后，才能废除私有制。","language":"中文","translation":false},{"id":"principles-1-43","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十八个问题：这个革命的发展过程将是怎样的？","language":"中文","translation":false},{"id":"principles-1-44","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：首先无产阶级革命将建立民主的国家制度，从而直接或间接地建立无产阶级的政治统治。在英国可以直接建立，因为那里的无产者现在已占人民的大多数。在法国和德国可以间接建立，因为这两个国家的大多数人民不仅是无产者，而且还有小农和小资产者，小农和小资产者正处在转变为无产阶级的过渡阶段，他们的一切政治利益的实现都越来越依赖无产阶级，因而他们很快就会同意无产阶级的要求。这也许还需要第二次斗争，但是，这次斗争只能以无产阶级的胜利而告终。","language":"中文","translation":false},{"id":"principles-1-45","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"如果不立即利用民主作为手段实行进一步、直接侵犯私有制和保障无产阶级生存的各种措施，那么，这种民主对于无产阶级就毫无用处。这些作为现存关系的必然结果现在已经产生出来的最主要的措施如下：","language":"中文","translation":false},{"id":"principles-1-46","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(1)用累进税、高额遗产税、取消旁系亲属(兄弟、侄甥等)继承权、强制公债等来限制私有制。","language":"中文","translation":false},{"id":"principles-1-47","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(2)一部分用国家工业竞争的办法，一部分直接用纸币赎买的办法，逐步剥夺土地所有者、工厂主、铁路所有者和船主的财产。","language":"中文","translation":false},{"id":"principles-1-48","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(3)没收一切反对大多数人民的流亡分子和叛乱分子的财产。","language":"中文","translation":false},{"id":"principles-1-49","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(4)在国家农场、工厂和作坊中组织劳动或者让无产者就业，这样就会消除工人之间的竞争，并迫使还存在的厂主支付同国家一样高的工资。","language":"中文","translation":false},{"id":"principles-1-50","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(5)对社会全体成员实行同样的劳动义务制，直到完全废除私有制为止。成立产业军，特别是在农业方面。","language":"中文","translation":false},{"id":"principles-1-51","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(6)通过拥有国家资本的国家银行，把信贷系统和金融业集中在国家手里。取消一切私人银行和银行家。","language":"中文","translation":false},{"id":"principles-1-52","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(7)随著国家拥有的资本和工人的增加，增加国家工厂、作坊、铁路和船舶，开垦一切荒地，改良已垦土地的土壤。","language":"中文","translation":false},{"id":"principles-1-53","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(8)所有的儿童，从能够离开母亲照顾的时候起，都由国家出钱在国家设施中受教育。把教育和生产结合起来。","language":"中文","translation":false},{"id":"principles-1-54","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(9)在国有土地上建筑大厦，作为公民公社的公共住宅。公民公社将从事工业生产和农业生产，将把城市和农村生活方式的优点结合起来，避免二者的片面性和缺点。","language":"中文","translation":false},{"id":"principles-1-55","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(10)拆毁一切不合卫生条件的、建筑得很坏的住宅和市区。","language":"中文","translation":false},{"id":"principles-1-56","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(11)婚生子女和非婚生子女享有同等的继承权。","language":"中文","translation":false},{"id":"principles-1-57","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(12)把全部运输业集中在国家手里。","language":"中文","translation":false},{"id":"principles-1-58","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"自然，所有这一切措施不能一下子都实行起来，但是它们将一个跟著一个实行，只要向私有制一发起猛烈的进攻，无产阶级就要被迫继续向前迈进，把全部资本、全部农业、全部工业、全部运输业和全部交换都越来越多地集中在国家手里。上述一切措施都是为了这个目的。无产阶级的劳动将使国家的生产力大大增长，随著这种增长，这些措施实现的可能性和由此而来的集中化程度也将相应地增长。最后，当全部资本、全部生产和全部交换都集中在国家手里的时候，私有制将自行灭亡，金钱将变成无用之物，生产将大大增加，人将大大改变，以致连旧社会最后的各种交往形式也能够消失。","language":"中文","translation":false},{"id":"principles-1-59","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第十九个问题：这种革命能不能单独在一个国家发生？","language":"中文","translation":false},{"id":"principles-1-60","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：不能。单是大工业建立了世界市场这一点，就把全球各国人民，尤其是各文明国家的人民，彼此紧紧地联系起来，以致每一国家的人民都受到另一国家发生的事情的影响。此外，大工业使所有文明国家的社会发展大致相同，以致在所有这些国家，资产阶级和无产阶级都成了社会上两个起决定作用的阶级，它们之间的斗争成了当前的主要斗争。因此，共产主义革命将不是仅仅一个国家的革命，而是将在一切文明国家里，至少在英国、美国、法国、德国同时发生的革命，在这些国家的每一个国家中，共产主义革命发展得较快或较慢，要看这个国家是否有较发达的工业，较多的财富和比较大量的生产力。因此，在德国实现共产主义革命最慢最困难，在英国最快最容易。共产主义革命也会大大影响世界上其他国家，会完全改变并大大加速它们原来的发展进程。它是世界性的革命，所以将有世界性的活动场所。","language":"中文","translation":false},{"id":"principles-1-61","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二十个问题：最终废除私有制将产生什么结果？","language":"中文","translation":false},{"id":"principles-1-62","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：由于社会将剥夺私人资本家对一切生产力和交换手段的支配权以及他们对产品的交换和分配权，由于社会将按照根据实有资源和整个社会需要而制定的计划来管理这一切，所以同现在的大工业管理制度相联系的一切有害的后果，将首先被消除。危机将终止。扩大的生产在现今的社会制度下引起生产过剩，并且是产生贫困的极重要的原因，到那个时候，这种生产就会显得十分不够，还必须大大扩大。超出社会当前需要的生产过剩不但不会引起贫困，而且将保证满足所有人的需要，将引起新的需要，同时将创造出满足这种新需要的手段。这种生产过剩将是新的进步的条件和刺激，它将实现这种进步，而不会像过去那样总是因此造成社会秩序的混乱。摆脱了私有制压迫的大工业的发展规模将十分宏伟，相形之下，目前的大工业状况将显得非常渺小，正像工场手工业和我们今天的大工业相比一样。工业的这种发展将给社会提供足够的产品以满足所有人的需要。现在由于私有制的压迫和土地的分散而难以利用现有改良成果和科学成就的农业，将来同样也会进入崭新的繁荣时期，并将给社会提供足够的产品。这样一来，社会将生产出足够的产品，可以组织分配以满足全体成员的需要。因此，社会划分为各个不同的相互敌对的阶级就是多余的了。这种划分不仅是多余的，甚至是和新的社会制度互不相容的。阶级的存在是由分工引起的，现在这种分工将完全消失，因为要把工业和农业生产提高到上面说过的水平，单靠机械和化学的辅助手段是不够的，还必须相应地发展使用这些手段的人的能力。当上个世纪的农民和工场手工业工人被卷入大工业的时候，他们改变了自己的整个生活方式而成为完全不同的人，同样，由整个社会共同经营生产和由此而引起的生产的新发展，也需要完全不同的人，并将创造出这种人来，共同经营生产不能由现在这种人来进行，因为他们每一个人都只隶属于某一个生产部门，受它束缚，听它剥削，在这里，每一个人都只能发展自己才能的一方面而偏废了其他各方面，只熟悉整个生产的某一个部门或某一个部门的一部分。就是现在的工业也越来越不能使用这样的人了。由整个社会共同地和有计划地来经营的工业，更加需要才能得到全面发展、能够通晓整个生产系统的人。因此，现在已被机器破坏了的分工，即把一个人变成农民、把另一个人变成鞋匠、把第三个人变成工厂工人、把第四个人变成交易所投机者，将完全消失。教育将使年轻人能够很快熟悉整个生产系统，将使他们能够根据社会需要或者他们自己的爱好，轮流从一个生产部门转到另一个生产部门。因此，教育将使他们摆脱现在这种分工给每个人造成的片面性。这样一来，根据共产主义原则组织起来的社会，将使自己的成员能够全面发挥他们的得到全面发展的才能。于是各个不同的阶级也必然消灭。因此，根据共产主义原则组织起来的社会一方面不容许阶级继续存在，另一方面这个社会的建立本身为消灭阶级差别提供了手段。","language":"中文","translation":false},{"id":"principles-1-63","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"由此可见，城市和乡村之间的对立也将消失。从事农业和工业的将是同一些人，而不再是两个不同的阶级，单从纯粹物质方面的原因来看，这也是共产主义联合体的必要条件。乡村农业人口的分散和大城市工业人口的集中，仅仅适应于工农业发展水平还不够高的阶段，这种状态是一切进一步发展的障碍，这一点现在人们就已经深深地感觉到了。","language":"中文","translation":false},{"id":"principles-1-64","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"由社会全体成员组成的共同联合体来共同地和有计划地利用生产力；把生产发展到能够满足所有人的需要的规模；结束牺牲一些人的利益来满足另一些人的需要的状况；彻底消灭阶级和阶级对立；通过消除旧的阶级，通过产业教育、变换工种、所有人共同享受大家创造出来的福利，通过城乡的融合，使社会全体成员的才能得到全面发展；——这就是废除私有制的主要结果。","language":"中文","translation":false},{"id":"principles-1-65","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二十一个问题：共产主义社会制度对家庭将产生什么影响？","language":"中文","translation":false},{"id":"principles-1-66","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：共产主义社会制度将使两性关系成为仅仅和当事人有关而社会无须干预的纯粹私人关系。共产主义社会制度之所以能实现这一点，是由于这种社会制度将废除私有制并将由社会教育儿童，从而将消灭现代婚姻的两种基础，即私有制所产生的妻子依赖丈夫、孩子依赖父母。这也是对道貌岸然的市侩关于共产主义公妻制的号叫的回答。公妻制完全是资产阶级社会的现象，现在的卖淫就是公妻制的充分表现。卖淫是以私有制为基础的，它将随著私有制的消失而消失。因此，共产主义组织并不实行公妻制，正好相反，它要消灭公妻制。","language":"中文","translation":false},{"id":"principles-1-67","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二十二个问题：共产主义组织将怎样对待现有的民族？","language":"中文","translation":false},{"id":"principles-1-68","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二十三个问题：共产主义组织将怎样对待现有的宗教","language":"中文","translation":false},{"id":"principles-1-69","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二十四个问题：共产主义者和社会主义者有什么区别？","language":"中文","translation":false},{"id":"principles-1-70","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：所谓社会主义者分为三类：","language":"中文","translation":false},{"id":"principles-1-71","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第一类是封建和宗法社会的拥护者，这种社会已被大工业、世界贸易和由它们造成的资产阶级社会所消灭，并且每天还在消灭。这一类社会主义者从现今社会的弊病中得出了这样的结论：应该恢复封建和宗法社会，因为它没有这种种弊病。他们的所有建议都是直接或间接地为了这一目的。共产主义者随时都要坚决同这类反动的社会主义者作斗争，尽管他们假惺惺地表示同情无产阶级的苦难并为此而洒出热泪。因为：","language":"中文","translation":false},{"id":"principles-1-72","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(1)他们追求一种根本不可能的事情；","language":"中文","translation":false},{"id":"principles-1-73","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(2)他们企图恢复贵族、行会师傅、工场手工业主以及和他们相联系的专制君主或封建君主、官吏、士兵和僧侣的统治，他们想恢复的这种社会固然没有现今社会的各种弊病，但至少会带来同样多的其他弊病，而且它根本不可能展现通过共产主义组织来解放被压迫工人的任何前景；","language":"中文","translation":false},{"id":"principles-1-74","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(3)当无产阶级成为革命的和共产主义的阶级的时候，这些社会主义者总要暴露出他们的真实意图。那时他们马上和资产阶级联合起来反对无产者。","language":"中文","translation":false},{"id":"principles-1-75","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二类是现今社会的拥护者，现今社会必然产生的弊病，使他们为这个社会的存在担心。因此，他们力图保持现今社会，不过要消除和它联系在一起的弊病。为此，一些人提出了种种简单的慈善办法，另一些人则提出了规模庞大的改革计划，这些计划在改组社会的借口下企图保存现今社会的基础，从而保存现今社会本身。共产主义者也必须同这些资产阶级社会主义者作不懈的斗争，因为他们的活动有利于共产主义者的敌人，他们所维护的社会正是共产主义者所要推翻的社会。","language":"中文","translation":false},{"id":"principles-1-76","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"最后，第三类是民主主义的社会主义者，他们和共产主义者同道，他们希望实现问题中所提出的部分措施，但他们不是把这些措施当作走向共产主义的过渡办法，而是当作足以消除贫困和现今社会的弊病的措施。这些民主主义的社会主义者，或者是还不够了解本阶级解放条件的无产者，或者是小资产阶级的代表，这个阶级直到争得民主和实行由此产生的社会主义措施为止，在许多方面都和无产者有共同的利益。因此，共产主义者在行动的时候，只要民主主义的社会主义者不为占统治地位的资产阶级效劳和不攻击共产主义者，就应当和这些社会主义者达成协议，这时尽可能和他们采取共同的政策。当然，共同行动并不排除讨论存在于他们和共产主义者间的分歧意见。","language":"中文","translation":false},{"id":"principles-1-77","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第二十五个问题：共产主义者怎样对待现有的其他政党？","language":"中文","translation":false},{"id":"principles-1-78","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"答：在不同的国家采取不同的态度。在资产阶级占统治地位的英国、法国和比利时，共产主义者和各民主主义政党暂时还有共同的利益，并且民主主义者在他们现在到处坚持的社会主义措施中越接近共产主义者的目的，就是说，他们越明确地坚持无产阶级的利益和越依靠无产阶级，这种共同的利益就越多。例如在英国，由工人组成的宪章派就要比民主主义小资产者或所谓激进派在极大程度上更接近共产主义者。","language":"中文","translation":false},{"id":"principles-1-79","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"在实行民主宪法的美国，共产主义者必须支持愿意用这个宪法去反对资产阶级、并利用它来为无产阶级谋利益的政党，即全国土地改革派。","language":"中文","translation":false},{"id":"principles-1-80","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"在瑞士是激进派，虽然他们本身是个成分极其复杂的政党，但他们是共产主义者能够打交道的唯一政党，其中瓦特州和日内瓦州的激进派又是最进步的。","language":"中文","translation":false},{"id":"principles-1-81","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"最后，在德国，资产阶级和专制君主制之间的决战还在后面。但是，共产主义者不能指望在资产阶级取得统治以前就和资产阶级进行决战，所以共产主义者为了本身的利益必须帮助资产阶级尽快地取得统治，以便尽快地再把它推翻。因此，在自由派资产阶级同政府的斗争中，共产主义者始终应当支持自由派资产阶级，只是应当注意，不要跟著资产者自我欺骗，不要听信他们关于资产阶级的胜利给无产阶级带来良好结果的花言巧语。共产主义者从资产阶级的胜利中得到的好处只能是：(1)得到各种让步，使共产主义者易于捍卫、讨论和传播自己的原则，从而使无产阶级易于联合成一个紧密团结的、准备战斗的和有组织的阶级；(2)使他们确信，从专制政府垮台的那一天起，就轮到资产者和无产者进行斗争了。从这一天起，共产主义者在这里所采取的党的政策，将和在资产阶级现在已占统治地位的那些国家里所采取的政策一样。","language":"中文","translation":false},{"id":"principles-1-82","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"弗·恩格斯写于 1847年10月底—11月","language":"中文","translation":false},{"id":"principles-1-83","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"1914年第一次以单行本发行","language":"中文","translation":false},{"id":"principles-1-84","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"(根据 人民出版社 1995年版《马克思恩格斯选集》","language":"中文","translation":false},{"id":"principles-1-85","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"第一卷 230-247页 输入)","language":"中文","translation":false},{"id":"principles-1-86","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"[1] 弗·恩格斯的著作“共产主义原理”是共产主义者同盟的纲领草案。关于以问答方式拟定纲领的问题，早在正义者同盟进行改组和改名为共产主义者同盟（1847年6月）的第一次代表大会以前就进行过讨论。1847年9月，共产主义者同盟伦敦中央委员会（沙佩尔、鲍威尔、莫尔）把“共产主义问答”分发给同盟的各个区部和支部。这个带有空想社会主义影响痕迹的文件不能使马克思和恩格斯满意，同样，“真正的社会主义者”莫·赫斯在巴黎拟走的“修正”草案也不能使他们满意。10月22日，在巴黎共产主义者同盟区部委员会的会议上，恩格斯尖锐地批评了赫斯的草案，使它遭到否决。恩格斯受委托起草新的草案。这个草案就是很快写成的“共产主义原理”。","language":"中文","translation":false},{"id":"principles-1-87","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"恩格斯把“共产主义原理”仅仅看成是纲领的初稿，他在1847年11月23—24日给马克思的信中曾谈到应当以“共产主义宣言”的形式来起草纲领的想法，而抛弃那陈旧的问答方式。马克思和恩格斯在共产主义者同盟第二次代表大会（1847年11月29日—12月8日）上捍卫了无产阶级政党的纲领的科学基础，大会委托他们以宣言的形式拟定纲领。在写作“共产党宣言”的过程中，马克思主义的创始人曾运用了“共产主义原理”中提出的一系列的原理。——第357页。","language":"中文","translation":false},{"id":"principles-1-88","author":"恩格斯","title":"共产主义原理","location":"恩格斯：共产主义原理（1847年10月）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1847a.htm","text":"[2] 在手稿中，在回答第二十二个问题以及下面一个即第二十三个问题的地方，写着“保留原案”等字样。显然，这是说答案应当仍维持原案，即仍照已失传的共产主义者同盟纲领的初步草案之一中业已拟定的答案。——第372页。","language":"中文","translation":false},{"id":"socialism-1-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"中文马克思主义文库 -> 恩格斯 【CHM电子书下载】","language":"中文","translation":false},{"id":"socialism-1-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"来源：《马克思恩格斯全集》第19卷","language":"中文","translation":false},{"id":"socialism-1-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"附录来自《全集》第20、22卷","language":"中文","translation":false},{"id":"socialism-1-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"社会主义从空想到科学的发展","language":"中文","translation":false},{"id":"socialism-1-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"·1880年法文版导言（马克思）","language":"中文","translation":false},{"id":"socialism-1-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"·1882年德文本初版序言（恩格斯）","language":"中文","translation":false},{"id":"socialism-1-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"·1891年德文第四版序言（恩格斯）","language":"中文","translation":false},{"id":"socialism-1-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"·1892年英文版导言（恩格斯）","language":"中文","translation":false},{"id":"socialism-1-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"·对《反杜林论》正文的补充和修改（恩格斯）","language":"中文","translation":false},{"id":"socialism-1-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"弗·恩格斯写于1880年1—3月上半月","language":"中文","translation":false},{"id":"socialism-1-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"载于1880年3月20日、4月20日和5月5日“社会主义评论”杂志第3、4和5期，并于1880年在巴黎出版法文单行本：弗·恩格斯“空想社会主义和科学社会主义”","language":"中文","translation":false},{"id":"socialism-1-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯《社会主义从空想到科学的发展》","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/index.htm","text":"中文根据“马克思恩格斯文选”两卷集1953年柏林狄茨出版社德文版译出","language":"中文","translation":false},{"id":"socialism-2-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-2-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"社会主义从空想到科学的发展[114]","language":"中文","translation":false},{"id":"socialism-2-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"现代社会主义，就其内容来说，首先是对统治于现代社会中的有产者和无产者之间、资本家和雇佣工人之间的阶级对立和统治于生产中的无政府状态这两个方面进行考察的结果。但是，就其理论形式来说，它起初表现为十八世纪法国伟大启蒙学者所提出的各种原则的进一步的、似乎更彻底的发展。和任何新的学说一样，它必须首先从已有的思想材料出发，虽然它的根源深藏在物质的经济的事实中。","language":"中文","translation":false},{"id":"socialism-2-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"在法国为行将到来的革命启发过人们头脑的那些伟大人物，本身都是非常革命的。他们不承认任何外界的权威，不管这种权威是什么样的。宗教、自然观、社会、国家制度，一切都受到了最无情的批判；一切都必须在理性的法庭面前为自己的存在作辩护或者放弃存在的权利。思维着的悟性成了衡量一切的唯一尺度。那时，如黑格尔所说的，是世界用头立地的时代［注：关于法国革命黑格尔这样写道：“正义思想、正义概念立刻得到了公认，非正义的旧支柱不能对它作任何抵抗。因此，正义思想现在就成了宪法的基础，今后一切都必须以它为根据。自从太阳照耀在天空而行星围绕着太阳旋转的时候起，还从来没有看到人用头立地，即用思想立地并按照思想去构造现实。阿那克萨哥拉第一个说，Nûs即理性支配着世界；可是直到现在人们才认识到思想应当支配精神的现实。这是一次壮丽的日出。一切能思维的生物都欢庆这个时代的来临。这时笼罩着一种高尚的热情，全世界都浸透了一种精神的热忱，仿佛第一次达到了神意和人世的和谐。”（黑格尔“历史哲学”1840年版第535页[115]）难道现在不应当用反社会党人法去反对已故的黑格尔教授的这种危险的颠复学说吗？］，最初，这句话的意思是：人的头脑以及通过它的思维发现的原理要求成为一切人类活动和社会结合的基础；后来这句话又有了更广泛的含义：和这些原理矛盾的现实，实际上被上下颠倒了。以往的一切社会形式和国家形式、一切传统观念，都被当做不合理的东西扔到垃圾堆里去了；到现在为止，世界所遵循的只是一些成见；过去的一切只值得怜悯和鄙视。只是现在阳光才照射出来，理性的王国才开始出现。从今以后，迷信、偏私、特权和压迫，必将为永恒的真理，为永恒的正义，为基于自然的平等和不可剥夺的人权所排挤。","language":"中文","translation":false},{"id":"socialism-2-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"现在我们知道，这个理性的王国不过是资产阶级的理想化的王国；永恒的正义在资产阶级的司法中得到实现；平等归结为法律面前的资产阶级的平等；被宣布为最主要的人权之一的是资产阶级的所有权；而理性的国家、卢梭的社会契约[116]在实践中表现为而且也只能表现为资产阶级的民主共和国。十八世纪的伟大思想家们，也和他们的一切先驱者一样，没有能够超出他们自己的时代所给予他们的限制。","language":"中文","translation":false},{"id":"socialism-2-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"但是，除了封建贵族和作为社会所有其余部分的代表出现的资产阶级之间的对立，还存在着剥削者和被剥削者、游手好闲的富人和从事劳动的穷人之间的一般的对立。正是由于这种情形，资产阶级的代表才能标榜自己不是某一特殊的阶级的代表，而是整个受苦人类的代表。不仅如此，资产阶级从它产生的时候起就背负着自己的对立物：资本家没有雇佣工人就不能生存，而且，随着中世纪的行会师傅发展成为现代的资产者，行会帮工和行会外的短工便相应地发展成为无产者。虽然总的说来，资产阶级在和贵族斗争时有权认为自己同时代表当时的各个劳动阶级的利益，但是在每一个大的资产阶级运动中都爆发过作为现代无产阶级的多少发展了的先驱者的那个阶级的独立运动。例如，德国宗教改革和农民战争时期的再洗礼派和托马斯·闵采尔，英国大革命时期的平均派[117]，法国大革命时期的巴贝夫。伴随着一个还没有成熟的阶级的这些革命武装起义，产生了相应的理论表现；在十六和十七世纪有理想社会制度的空想的描写[118]，而在十八世纪已经有直接共产主义的理论（摩莱里和马布利）。平等的要求已经不再限于政治权利方面，它也扩大到个人的社会地位方面了；必须加以消灭的不仅是阶级特权，而且是阶级差别本身。苦修苦炼的、禁绝一切生活享受的、斯巴达式的共产主义，是这个新学说的第一个表现形式。后来出现了三个伟大的空想主义者：圣西门、傅立叶和欧文。在圣西门那里，除无产阶级的倾向外，资产阶级的倾向还有一定的影响。欧文在资本主义生产最发达的国家里，在这种生产所造成的种种对立的影响下，直接从法国唯物主义出发，系统地制定了他的消除阶级差别的方案。","language":"中文","translation":false},{"id":"socialism-2-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"所有这三个人有一个共同点：他们都不是作为当时已经历史地产生的无产阶级的利益的代表出现的。他们和启蒙学者一样，并不是想首先解放某一个阶级，而是想立即解放全人类。他们和启蒙学者一样，想建立理性和永恒正义的王国；但是他们的王国和启蒙学者的王国是有天壤之别的。按照这些启蒙学者的原则建立起来的资产阶级世界也是不合乎理性的和不正义的，所以也应该像封建制度和以往的一切社会制度一样被抛到垃圾堆里去。真正的理性和正义至今还没有统治世界，这只是因为它们没有被人们正确地认识。所缺少的只是个别的天才人物，现在这种人物已经出现而且已经认识了真理；至于天才人物是在现在出现，真理正是在现在被认识到，这并不是历史发展的进程所必然产生的、不可避免的事情，而只是一种侥幸的偶然现象。这种天才人物在五百年前也同样可能诞生，这样他就能使人类免去五百年的迷误、斗争和痛苦。","language":"中文","translation":false},{"id":"socialism-2-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"我们已经看到为革命作了准备的十八世纪的法国哲学家们如何求助于理性，把理性当做一切现存事物的唯一的裁判者。他们要求建立理性的国家、理性的社会，要求无情地铲除一切和永恒理性相矛盾的东西。我们也已经看到，这个永恒的理性实际上不过是正好在那时发展成为资产者的中等市民的理想化的悟性而已。现在，当法国革命把这个理性的社会和这个理性的国家实现了的时候，就发现新制度不论较之旧制度如何合理，却决不是绝对合乎理性的。理性的国家完全破产了。卢梭的社会契约在恐怖时代获得了实现，对自己的政治能力丧失了信心的资产阶级为了摆脱这种恐怖，起初求助于腐败的督政府[119]，最后则托庇于拿破仑的专制统治。早先许下的永久和平变成了一场无休止的掠夺战争。理性的社会的遭遇也并不更好一些。富有和贫穷的对立并没有在普遍的幸福中得到解决，反而由于缓和这种对立的行会特权和其他特权的废除，由于减弱这种对立的教会慈善设施的取消而更加尖锐化了；现在已经实现的脱离封建桎梏的“财产自由”，对小资产者和小农说来，就是把他们的被大资本和大地产的强大竞争所压垮的小财产出卖给这些大财主的自由，于是这种“自由”对小资产者和小农说来就变成了失去财产的自由；工业在资本主义基础上的迅速发展，使劳动群众的贫穷和困苦成了社会的生存条件。现金交易，如卡莱尔所说的，日益成为社会的唯一纽带。犯罪的次数一年比一年增加。如果说，以前在光天化日之下肆无忌惮地干出来的封建罪恶虽然没有消灭，但终究已经暂时被迫收敛了，那末，以前只是暗中偷着干的资产阶级罪恶却更加猖獗了。商业日益变成欺诈。革命的箴言“博爱”[120]在竞争的诡计和嫉妒中获得了实现。贿赂代替了暴力压迫，金钱代替了刀剑，成为社会权力的第一杠杆。初夜权从封建领主手中转到了资产阶级工厂主的手中。卖淫增加到了前所未闻的程度。婚姻本身和以前一样仍然是法律承认的卖淫的形式，是卖淫的官方的外衣，并且还以不胜枚举的通奸作为补充。总之，和启蒙学者的华美约言比起来，由“理性的胜利”建立起来的社会制度和政治制度竟是一幅令人极度失望的讽刺画。那时只是还缺少指明这种失望的人，而这种人随着世纪的转换出现了。1802年出版了圣西门的日内瓦书信；1808年出版了傅立叶的第一部著作，虽然他的理论基础在1799年就已经奠定了；1800年1月1日，欧文担负了新拉纳克的管理工作[121]。","language":"中文","translation":false},{"id":"socialism-2-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"但是，在这个时候，资本主义生产方式以及资产阶级和无产阶级间的对立还很不发展。在英国刚刚产生的大工业，在法国还完全没有。但是，一方面，只有大工业才能发展那些使生产方式的变革和生产方式的资本主义性质的消灭成为绝对必要的冲突——不仅是大工业所产生的各个阶级之间的冲突，而且是它所产生的生产力和交换形式本身之间的冲突；另一方面，大工业又正是通过这些巨大的生产力来发展解决这些冲突所必需的手段。因此，如果说，在1800年左右，新的社会制度所产生的冲突还只是在开始形成，那末，解决这些冲突的手段就更是这样了。虽然巴黎的无财产的群众在恐怖时期曾有一瞬间夺得了统治权，从而能够引导资产阶级革命（甚至是反对资产阶级的）达到胜利，但是他们只是以此证明了他们的统治在当时的条件下是不可能持久的。在当时才刚刚作为新阶级的胚胎从这些无财产的群众中分离出来的无产阶级，还完全无力采取独立的政治行动，表现为一个被压迫的受苦的等级，无力帮助自己，最多只能从外面、从上面取得帮助。","language":"中文","translation":false},{"id":"socialism-2-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"这种历史情况也决定了社会主义创始人的观点。不成熟的理论，是和不成熟的资本主义生产状况、不成熟的阶级状况相适应的。解决社会问题的办法还隐藏在不发达的经济关系中，所以只有从头脑中产生出来。社会所表现出来的只是缺点；消除这些缺点是思维着的理性的任务。于是就需要发明一套新的更完善的社会制度，并且通过宣传，可能时通过典型示范把它从外面强加于社会。这种新的社会制度是一开始就注定要成为空想的，它愈是制定得详尽周密，就愈是要陷入纯粹的幻想。","language":"中文","translation":false},{"id":"socialism-2-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"既然这一点已经确定，我们就不再谈论现在已经完全属于过去的这一方面了。让著作界的小贩们去一本正经地挑剔这些现在只能使人发笑的幻想吧，让他们以自己的严谨的思维方式优越于这种“疯狂的念头”而自我陶醉吧。使我们感到高兴的，倒是处处突破幻想的外壳而显露出来的天才的思想萌芽和天才思想，而这些却是那班庸人所看不见的。","language":"中文","translation":false},{"id":"socialism-2-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"圣西门是法国大革命的产儿，他在革命爆发时还不到30岁。这次革命，是第三等级即从事生产和贸易的多数国民对以前享有特权的游手好闲的等级即贵族和僧侣的胜利。但是，很快就暴露出，第三等级的胜利只是这个等级中的一小部分人的胜利，是第三等级中享有社会特权的阶层即资产阶级夺得政治权力。而且这个资产阶级还在革命过程中就迅速地发展起来了，这是因为它通过没收后加以拍卖的贵族和教会的地产进行了投机，同时又以承办军用品欺骗了国家。正是这些骗子的统治在督政府时代使法国和革命濒于复灭，从而使拿破仑得到举行政变的借口。因此，在圣西门的头脑中，第三等级和特权等级之间的对立就采取了“劳动者”和“游手好闲者”之间的对立的形式。游手好闲者不仅是指旧时的特权分子，而且也包括一切不参加生产和贸易而靠租息为生的人。而“劳动者”不仅是指雇佣工人，而且也包括厂主、商人和银行家。游手好闲者失去了精神领导和政治统治的能力，这已经是确定无疑的，而且由革命最终证实了。至于无财产者没有这种能力，在圣西门看来，这已由恐怖时期的经验所证明。那末，应当是谁来领导和统治呢？按照圣西门的意见，应当是科学和工业，它们两者由一种新的宗教纽带，即必然是神秘的和等级森严的“新基督教”结合起来，而这种纽带的使命就是恢复从宗教改革时起被破坏了的宗教观点的统一。可是，科学就是学者，而工业首先就是积极的资产者，厂主、商人、银行家。这些资产者固然应当成为一种公众的官吏、社会所信托的人，但是对工人还应当保持发号施令的和享有经济特权的地位。至于银行家，那末正是他们应当担负起通过调节信用来调节整个社会生产的使命。——这样的见解是完全适应于大工业以及资产阶级和无产阶级的对立在法国还只是刚刚产生的那个时代的。但是，圣西门特别强调的是：他随时随地都首先关心“人数最多和最贫穷的阶级”（《la classe la plus nombreuse et la plus pauvre》）的命运。","language":"中文","translation":false},{"id":"socialism-2-13","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"圣西门在日内瓦书信中已经提出这样一个论点：","language":"中文","translation":false},{"id":"socialism-2-14","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"在同一部著作中他已经指出，恐怖统治是无财产的群众的统治。","language":"中文","translation":false},{"id":"socialism-2-15","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"他向他们高声说道：“看吧，当你们的伙伴在统治法国的时候，那里发生了什么事情：他们造成了饥荒！”[122]","language":"中文","translation":false},{"id":"socialism-2-16","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"但是，了解到法国革命是阶级斗争，并且不仅是贵族和资产阶级之间的、而且是贵族、资产阶级和无财产者之间的阶级斗争，这在1802年是极为天才的发现。在1816年，圣西门宣布说政治是关于生产的科学，并且预言说政治将完全为经济所包容[123]。虽然经济状况是政治制度的基础这样的认识在这里仅仅以萌芽状态表现出来，但是对人的政治统治应当变成对物的管理和对生产过程的领导这种思想，即最近纷纷议论的“废除国家”的思想，已经明白地表达出来了。同样比他的同时代人优越的是：在1814年联军刚刚开进巴黎以后，接着又在1815年百日战争时，他声明，法国和英国的同盟以及这两个国家和德国的同盟是欧洲的繁荣和和平的唯一保障[124]。在1815年向法国人宣传要和滑铁卢战役[125]的胜利者建立同盟，这确实既要有勇气又要有历史远见。","language":"中文","translation":false},{"id":"socialism-2-17","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"如果说，我们在圣西门那里看到了天才的远大眼光，由于他有这种眼光，后来的社会主义者的几乎一切并非严格地是经济的思想都以萌芽状态包含在他的思想中，那末，我们在傅立叶那里就看到了他对现存社会制度所作的具有真正法国人的风趣、但并不因此显得不深刻的批判。傅立叶就资产阶级所说的话，就他们在革命前的狂热的预言者和革命后的被收买的奉承者所说的话，抓住了他们。他无情地揭露资产阶级世界在物质上和道德上的贫困，他不仅拿这种贫困和以往的启蒙学者关于只为理性所统治的社会、关于能给一切人以幸福的文明、关于人类无限完善化的能力的诱人的约言作对比，而且也拿这种贫困和当时的资产阶级思想家的华丽的辞句作对比；他指出，和最响亮的词句相适应的到处都是最可怜的现实，他辛辣地嘲讽这种词句的无可挽救的破产。傅立叶不仅是批评家，他的永远开朗的性格还使他成为一个讽刺家，而且是自古以来最伟大的讽刺家之一。他以巧妙而诙谐的笔调描述了随着革命的低落而盛行起来的投机取巧和当时法国商业中普遍的小商贩气息。他更巧妙地批判了两性关系的资产阶级形式和妇女在资产阶级社会中的地位。他第一个表明了这样的思想：在任何社会中，妇女解放的程度是衡量普遍解放的天然尺度[126]。但是傅立叶最伟大的地方是表现在他对社会历史的看法上。他把社会历史迄今为止的全部历程分为四个发展阶段：蒙昧、野蛮、宗法和文明。最后一个阶段就相当于现在所谓的资产阶级社会，即从十六世纪发展起来的社会制度。他指出：","language":"中文","translation":false},{"id":"socialism-2-18","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"“这个文明制度使野蛮时期任何一种以简单的方式干出来的罪恶都采取了复杂的、暧昧的、两面的、虚伪的存在形式”；","language":"中文","translation":false},{"id":"socialism-2-19","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"文明是在一个“恶性循环”中运动，是在它不断地重新制造出来而又无法克服的矛盾中运动，因此，它所达到的结果总是和它希望达到或者佯言希望达到的相反[127]。所以，譬如说，","language":"中文","translation":false},{"id":"socialism-2-20","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":20,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"“在文明阶段，贫困是由富裕本身所产生的”[128]。","language":"中文","translation":false},{"id":"socialism-2-21","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":21,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"我们看到，傅立叶是和他的同时代人黑格尔一样巧妙地掌握了辩证法的。他反对关于人类无限完善化的能力的空谈，而同样辩证地断言，每个历史阶段都有它的上升时期，但是也有它的下降时期[129]，而且他还把这个看法用于整个人类的未来。正如康德在自然科学中提出了地球将来要归于灭亡的思想一样，傅立叶在历史研究中提出了人类将来要归于灭亡的思想。","language":"中文","translation":false},{"id":"socialism-2-22","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":22,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"当革命的风暴横扫整个法国的时候，英国正在进行一种比较平静的但是威力并不因此减弱的变革。蒸汽和新的工具机把工场手工业变成了现代的大工业，从而把资产阶级社会的整个基础革命化了。工场手工业时代的迟缓的发展进程变成了生产中的真正的狂飚时期。社会愈来愈迅速地分化为大资本家和无产者，处于他们二者之间的已经不是以前的稳定的中间等级，而是不稳定的手工业者和小商人群众，他们过着不安定的生活，他们是人口中最流动的部分。当时新的生产方式还处在上升时期的最初阶段；它还是正常的、适当的、在当时条件下唯一可能的生产方式。但是它在那时已经产生了惊人的社会恶果：无家可归的人聚居在大城市的贫民窟里；一切传统习惯的约束、宗法制从属关系、家庭都解体了；劳动时间，特别是女工和童工的劳动时间延长到可怕的程度；突然被抛到一个全新的环境中（从乡村到城市，从农业到工业，从稳定的生活条件转到天天都在变化的、毫无保障的生活条件）的劳动阶级大批地堕落了。这时有一个29岁的厂主以改革家的身分出现了，这个人具有像孩子一样单纯的高尚的性格，同时又是一个少有的天生的领导者。罗伯特·欧文接受了唯物主义启蒙学者的学说，认为人的性格是先天组织和人在自己的一生中、特别是在发育时期所处的环境这两个方面的产物。社会地位和欧文相同的大多数人，都认为工业革命只是便于浑水摸鱼和大发横财的一片混乱。欧文则认为工业革命是运用其心爱的理论并把混乱化为秩序的好机会。当他在曼彻斯特领导一个有500多工人的工厂的时候，就试行了这个理论，并且获得了成效。从1800到1829年间，他以股东兼经理的身分领导了苏格兰的新拉纳克大棉纺厂，他在这里按照同样的精神办事，但是在行动上有更大的自由，而且获得了使他名闻全欧的成效。新拉纳克的人口逐渐增加到2500人，这些人的成分原来是极其复杂的，而且多半是极其堕落的分子，可是欧文把这个地方变成了一个完善的模范移民区，在这里，酗酒、警察、刑事法庭、诉讼、贫困救济和慈善事业都绝迹了。而他之所以做到这点，只是由于他使人生活在比较合乎人的尊严的环境中，特别是关心成长中的一代的教育。他发明了并且第一次在这里创办了幼儿园。孩子们从两岁起就进幼儿园；他们在那里生活得非常愉快，父母简直很难把他们领回去。欧文的竞争者迫使工人每天劳动13—14小时，而在新拉纳克只劳动10小时半。当棉纺织业危机使工厂不得不停工4个月的时候，歇工的工人还继续领取全部工资。虽然如此，这个企业的价值还是增加了一倍多，而且直到最后都给企业主们带来大量的利润。","language":"中文","translation":false},{"id":"socialism-2-23","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":23,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"但是欧文并不对这一切感到满足。他给他的工人创造的生活条件，在他看来还远不是合乎人的尊严的；他说，","language":"中文","translation":false},{"id":"socialism-2-24","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":24,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"“这些人都是我的奴隶”；","language":"中文","translation":false},{"id":"socialism-2-25","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":25,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"他给他们安排的比较良好的环境，还远不足以使人的性格和智慧得到全面的合理的发展，更不用说自由发挥其才能了。","language":"中文","translation":false},{"id":"socialism-2-26","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":26,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"“可是，这2500人中从事劳动的那一部分人给社会生产的实际财富，仅仅半世纪前还需要60万人才能生产出来。我问自己：这2500人所消费的财富和以前60万人所应当消费的财富之间的差额到哪里去了呢？”","language":"中文","translation":false},{"id":"socialism-2-27","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":27,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"答案是明白的。这个差额是落到企业所有者的手里去了，他们除了领取5％的股息以外，还得到30万英镑（600万马克）以上的利润，新拉纳克尚且如此，英国其他一切工厂就更不用说了。","language":"中文","translation":false},{"id":"socialism-2-28","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":28,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"“没有这些由机器创造的新财富，就不能进行推翻拿破仑和保持贵族的社会原则的战争。而这个新的力量是劳动阶级创造的。”［注：摘自“头脑中和实践中的革命”——给一切“欧洲红色共和党人、共产主义者和社会主义者”、1848年的法国临时政府，以及“维多利亚女王和她的负责顾问”[130]。］","language":"中文","translation":false},{"id":"socialism-2-29","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":29,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"因此，果实也应当属于劳动阶级。在欧文看来，以前仅仅使少数人发财而使群众受奴役的新的强大的生产力，提供了改造社会的基础，它只应当作为大家的共同财产来为大家的共同福利服务。","language":"中文","translation":false},{"id":"socialism-2-30","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":30,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"欧文的共产主义就是通过这种纯粹营业的方式，作为所谓商业计算的果实产生出来的。它始终都保持着这种实践的性质。例如，在1823年，欧文提出了通过共产主义移民区消除爱尔兰贫困的办法，并附上了关于筹建费用、每年开支和预计收入的详细计算[131]。而在他的关于未来的最终计划中，他从技术上规定了各种细节，附上了平面图、正面图和鸟瞰图，而这一切都做得非常内行，以致他的改造社会的方法一旦被采纳，则各种细节的安排甚至从专家的眼光看来也很少有什么可以反对的。","language":"中文","translation":false},{"id":"socialism-2-31","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":31,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"转向共产主义是欧文一生中的转折点。当他还只是一个慈善家的时候，他所获得的只是财富、赞扬、名望和荣誉。他是欧洲最有名望的人物。不仅社会地位和他相同的人，而且连达官显贵、王公大人们都点头倾听他的讲话。可是当他提出他的共产主义理论时，情况就完全变了。在他看来，阻碍社会改造的首先有三大障碍：私有制、宗教和现在的婚姻形式。他知道，当他向这些障碍进攻的时候，他所面临的是什么：官场社会的普遍排斥，他的整个社会地位的丧失。但是，他并没有却步，他不顾一切地向这些障碍进攻，而他所预料的事情果然发生了。他被逐出了官场社会，受到了报刊的封锁，他由于以全部财产在美洲进行的共产主义试验的失败而变得一贫如洗，于是他就直接转向工人阶级，在工人阶级中又进行了三十年的活动。当时英国的有利于工人的一切社会运动、一切实际成就，都是和欧文的名字联在一起的。例如，由于他的五年的努力，在1819年通过了限制工厂中女工和童工劳动的第一个法律[132]。他主持了英国工会的第一次代表大会，在这次大会上全国各工会联合成一个巨大的工会联合会[133]。同时，作为向完全共产主义的社会制度过渡的措施，一方面他组织了合作社（消费合作社和生产合作社），这些合作社从这时起至少已经在实践上证明，无论商人或厂主都决不是不可缺少的人物；另一方面他组织了劳动市场，在这里，劳动产品借助于以劳动小时为单位的劳动券进行交换[134]；这种市场必然要遭到失败，但是充分预示了晚得多的蒲鲁东的交换银行[135]，而它和后者不同的就是它并没有被描写为医治一切社会病害的万应药方，而只是激进得多的社会改造的第一步。","language":"中文","translation":false},{"id":"socialism-2-32","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":32,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"空想主义者的见解曾经长期地支配着十九世纪的社会主义观点，而且现在还部分地支配着这种观点。法国和英国的一切社会主义者不久前都还信奉这种见解，包括魏特林在内的先前的德国共产主义也是这样。对所有这些人来说，社会主义是绝对真理、理性和正义的表现，只要把它发现出来，它就能用自己的力量征服世界；因为绝对真理是不依赖于时间，空间和人类的历史发展的，所以，它在什么时候和什么地方被发现，那纯粹是偶然的事情。同时，绝对真理、理性和正义在每个学派的创始人那里又是各不相同的；而因为在每个学派的创始人那里，绝对真理、理性和正义的独特形式又是由他的主观理解、生活条件、知识水平和思维发展程度所决定的，所以，解决各种绝对真理的这种冲突的办法就只能是它们互相磨损。由此只能得出一种折衷的不伦不类的社会主义，这种社会主义实际上直到今天还统治着法国和英国大多数社会主义工人的头脑，它是由比较温和的批评意见、经济理论和各学派创始人关于未来社会的观念组成的色调极为复杂的混合物，这种混合物的各个组成部分在辩论的激流中愈是像石子在溪流中一样地磨光其锋利的棱角，这种混合物就愈加容易构成。为了使社会主义变为科学，就必须首先把它置于现实的基础之上。","language":"中文","translation":false},{"id":"socialism-2-33","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":33,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[114] “社会主义从空想到科学的发展”是由弗·恩格斯于1877—1878年写成的著作“反杜林论”中的三章编成的。","language":"中文","translation":false},{"id":"socialism-2-34","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":34,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"1880年恩格斯应保·拉法格的请求把“反杜林论”中的三章（“引论”的第一章、第三编的第一章和第二章）改写成为一篇独立的通俗的著作，这一著作首先以“空想社会主义和科学社会主义”为题发表在法国社会主义杂志“社会主义评论”上，后来又以单行本的形式在同年出版。这一法文版本成了波兰文和意大利文译本基础。1883年，这本小册子出版了德文本，书名为“社会主义从空想到科学的发展”（扉页上标的是1882年）。这本小册子在恩格斯生前就已经从德文译成了欧洲各种文字，并且在工人中得到了广泛的传播，对马克思主义思想的宣传起了巨大的作用。这一著作在恩格斯生前的最后一次德文版（第4版）是1891年在柏林出版的。这一小册子在材料安排上与“反杜林论”的有关章节有所不同，并且对“反杜林论”的本文作了一些补充和改动。——第201页。","language":"中文","translation":false},{"id":"socialism-2-35","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":35,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[115] 乔·威·弗·黑格尔“历史哲学”；“全集”1840年柏林第2版第9卷（G．W．F．Hegel．《Philosophie der Geschichte》，Werke，2．Aufl．，Bd．Ⅸ，Berlin，1840）。——第206页。","language":"中文","translation":false},{"id":"socialism-2-36","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":36,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[116] 按照卢梭的理论，人们最初生活在自然状态的条件下，在这种条件下人人都是平等的。私有制的产生和财产不平等的发展决定了人们从自然状态向市民状态的过渡，并导致以社会契约为基础的国家的形成。但是，后来由于政治不平等的发展，社会契约遭到破坏，产生了新的自然状态。消灭这种自然状态，是以新的社会契约为基础的理性国家的使命。","language":"中文","translation":false},{"id":"socialism-2-37","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":37,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"这个理论在卢梭的1755年阿姆斯特丹出版的“论人间不平等的起源和原因”（《Discours sur l'origine et les fondemens de l'inégalité parmi les hommes》．Amsterdam，1755）和1762年阿姆斯特丹出版的“社会契约论，或政治权利的原则”（《Du contract social；ou，Principes du droit politique》．Amsterdam，1762）这两部著作中得到了发挥。——第206页。","language":"中文","translation":false},{"id":"socialism-2-38","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":38,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[117] 恩格斯指“真正平均派”或“掘地派”，他们是十七世纪英国资产阶级革命时期极左派的代表。“掘地派”代表城乡贫民阶层的利益，他们要求消灭土地私有制，宣传原始的平均共产主义思想，并企图用集体开垦公有土地的办法来实现这种思想。——第207页。","language":"中文","translation":false},{"id":"socialism-2-39","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":39,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[118] 恩格斯首先指空想共产主义者的著作——托·莫尔“乌托邦”（1516年出版）和托·康帕内拉“太阳城”（1623年出版）。——第207页。","language":"中文","translation":false},{"id":"socialism-2-40","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":40,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[119] 恐怖时代是雅各宾派的革命民主专政时期（1793年6月—1794年7月），当时雅各宾派为了对付吉伦特派和保皇派的反革命恐怖采用了革命的恐怖。","language":"中文","translation":false},{"id":"socialism-2-41","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":41,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"督政府（由五个督政官组成，每年改选一人）是法国执行权的领导机关，它是根据雅各宾派革命专政于1794年失败后所通过的1795年宪法建立的；它存在到1799年波拿巴政变；它支持反对民主力量的恐怖制度，并维护大资产阶级的利益。——第208页。","language":"中文","translation":false},{"id":"socialism-2-42","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":42,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[120] 指十八世纪末法国资产阶级革命的口号：“自由、平等、博爱”。——第209页。","language":"中文","translation":false},{"id":"socialism-2-43","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":43,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[121] “一个日内瓦居民给当代人的信”（《Lettres d'un habitant de Ge-nève à ses contemporains》）是圣西门的第一部著作；1802年写于日内瓦，1803年匿名发表于巴黎，没有标明出版的地点和时间。恩格斯用的版本是：Ｇ．雨巴“圣西门。他的生平和著述。附有圣西门名著的摘录”1857年巴黎版（G．Hubbard．《Saint-Simon．Sa vie et ses travaux．Suivi de fragments des plus célèbres écrits de Saint-Simon》．Paris，1857）。在这个版本中圣西门的个别著作的日期有不确切的地方。","language":"中文","translation":false},{"id":"socialism-2-44","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":44,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"傅立叶的第一部大作是“关于四种运动和普遍命运的理论”（《Théorie des quatre mouvements et des destinées généra-les》），写于十九世纪头几年，1808年在里昂匿名出版（可能考虑到书报检查，在扉页上注明的出版地点是莱比锡）。","language":"中文","translation":false},{"id":"socialism-2-45","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":45,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"新拉纳克（New Lanark）是苏格兰拉纳克城附近的一个棉纺厂，创办于1784年，在工厂周围形成一个小镇。——第209页。","language":"中文","translation":false},{"id":"socialism-2-46","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":46,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[122] 恩格斯引证的是圣西门的“一个日内瓦居民给当代人的信”这部著作中的第二封信。这些话在雨巴版本的第143页和第135页上。——第212页。","language":"中文","translation":false},{"id":"socialism-2-47","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":47,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[123] 恩格斯指“昂·圣西门给一个美国人的信”（第八封信）中的一段话。这些信载于昂·圣西门的论文集“实业，或为贡献出有用和独立的劳动的一切人的利益所作的政治、道德和哲学的议论”1817年巴黎版第2卷（H．Saint-Simon．《L'industrie，ou Discussions politiques，morales et philosophiques，dans L'intérêt de tous les hommes livrés à des travaux utiles et indépendans》．T．Ⅱ，Paris，1817）。这些话在雨巴版本的第155—157页上。——第212页。","language":"中文","translation":false},{"id":"socialism-2-48","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":48,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[124] 恩格斯指的是圣西门同他的学生奥·梯叶里合著的两本书：“论欧洲社会的改组，或论欧洲各民族在保持各自的民族独立性的条件下联合为一个政治统一体的必要性和手段”（《De la réorganisation de la société européenne，ou de la nécessité et des moyens de rassembler les peuples de l'éurope en un seul corps politi-que，en conservant à chacun son indépendance nationale》）和“关于应当用来对付1815年同盟的措施的意见”（《Opinion sur les mesures à prendre contre la coalition de 1815》）；这两本小册子都在巴黎出版，第一本在1814年10月，第二本在1815年。在雨巴的版本中，从第一本小册子作的摘录在第149—154页，而这两本小册子的内容则刊在第68—76页。","language":"中文","translation":false},{"id":"socialism-2-49","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":49,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"第六次反法同盟的参加国（俄国、奥地利、英国、普鲁士等国）的同盟国军于1814年3月31日进入巴黎。拿破仑帝国垮台了，而拿破仑本人在宣布退位以后被流放到埃尔巴岛。在法国发生了波旁王朝的第一次复辟。","language":"中文","translation":false},{"id":"socialism-2-50","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":50,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"百日是指拿破仑恢复帝制的短暂时期，从1815年3月20日他从埃尔巴岛回到巴黎时起，到同年6月22日他在滑铁卢失败后第二次退位时为止。——第212页。","language":"中文","translation":false},{"id":"socialism-2-51","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":51,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[125] 1815年6月18日，拿破仑的军队在滑铁卢（比利时）被威灵顿指挥的英荷联军和布吕歇尔指挥的普鲁士军击败。这次战役在1815年的战局中起了决定性的作用，它预先决定了第七次反法同盟（英国、俄国、奥地利、普鲁士、瑞典等国）的彻底胜利和拿破仑帝国的崩溃。——第212页。","language":"中文","translation":false},{"id":"socialism-2-52","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":52,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[126] 这个思想在傅立叶的第一本书“关于四种运动的理论”中已经得到了发挥，书中包含着这样一个总的论点：“某一时代的社会进步和变迁是同妇女走向自由的程度相适应的，而社会秩序的衰落是同妇女自由减少的程度相适应的。”傅立叶在下述公式中概括了这个论点：“妇女权利的扩大是一切社会进步的基本原则”（ Ch．Fourier．Oeuvres comp-lètes，t．Ⅰ，Paris，1841，p．195—196）。——第213页。","language":"中文","translation":false},{"id":"socialism-2-53","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":53,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[127] 参看沙·傅立叶“关于普遍统一的理论”第1卷和第4卷；“全集”1843年巴黎版第2卷第78—79页和1841年巴黎版第5卷第213—214页（Ch．Fourier．《Théorie de l'unité universelle》，vol．Ⅰ et Ⅳ；Oeuvres complètes，t．Ⅱ，Paris，1843，p．78-79 et t．Ⅴ，Paris，1841，p．213—214）。","language":"中文","translation":false},{"id":"socialism-2-54","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":54,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"关于文明制度在其中运动的“恶性循环”，见沙·傅立叶“经济的和协会的新世界，或按情欲分类的引人入胜的和合乎自然的劳动方式的发现”；“全集”1845年巴黎版第6卷第27—46、390页（Ch．Fourier．《Le Nouveau Monde industriel et sociétaire，ou Invention du procédé d'industrie attrayante et naturelle distribuée en séries passionnées》；Oeuvres complètes，t．Ⅵ，Paris，1845，p．27—46，390）。该书的第一版于1829年在巴黎出版。并参看Ch．Fourier．Oeuvres complètes，t．Ⅰ，Paris，1841，p．202。——第213页。","language":"中文","translation":false},{"id":"socialism-2-55","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":55,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[128] Ch．Fourier．Oeuvres complètes，t．Ⅵ，Paris，1845，p．35．——第213页。","language":"中文","translation":false},{"id":"socialism-2-56","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":56,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[129] Ch．Fourier．Oeuvres complètes，t．Ⅰ，Paris，1841，p．50 et suiv．——第213页。","language":"中文","translation":false},{"id":"socialism-2-57","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":57,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[130] 罗·欧文“人类头脑和实践中的革命，或将来由非理性到理性的过渡”1849年伦敦版（Ｒ．Ｏｗｅｎ．《The Revolution in the Mind and Practice of the Human Race；or，the Coming Change from Irrationality to Rationality》．London，1849）。——第216页。","language":"中文","translation":false},{"id":"socialism-2-58","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":58,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[131] 罗·欧文“关于在都柏林举行的几次公众集会的报告……3月18日、4月12日和19日、5月3日”1823年都柏林版（R．Owen．《Report of the proceedings at the several public meetings，held in Dublin…on the 18th March，12th April，19th April and 3rd May》．Dublin，1823）。——第216页。","language":"中文","translation":false},{"id":"socialism-2-59","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":59,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[132] 1815年1月，欧文在格拉斯哥的一次群众集会上提出了一系列改善工厂的童工和成年工人的状况的措施。根据1815年6月欧文的倡议提出的法案到1819年7月才被议会通过，成为法律，而且还大大地打了折扣。调整棉纺厂劳动的法律禁止9岁以下的儿童作工，限定18岁以下的工人的工作日为12小时，规定所有工人有两次工间休息作为早饭和午饭的时间，共一个半小时。——第217页。","language":"中文","translation":false},{"id":"socialism-2-60","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":60,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[133] 1833年10月，在欧文的主持下在伦敦举行了合作社和职工的代表大会，会上正式成立了大不列颠和爱尔兰全国产业部门大联盟；联盟的章程于1834年2月被通过。按照欧文的想法，这个联盟应当把生产管理的权力掌握在自己手里，并且通过和平的途径实现对社会的彻底改造。但是这个空想的计划遭到了失败。由于受到资产阶级社会和国家的强烈反对，该联盟于1834年8月宣告解散。——第217页。","language":"中文","translation":false},{"id":"socialism-2-61","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":61,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[134] 指由英国各城市的工人合作社创立的劳动产品公平交换市场（Equ-itable Labour Exchange Bazaars）；第一个这样的市场是罗伯特·欧文于1832年9月在伦敦创办的，存在到1834年年中。——第217页。","language":"中文","translation":false},{"id":"socialism-2-62","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（一）","page":2,"paragraph":62,"url":"https://www.marxists.org/chinese/engels/1880/01.htm","text":"[135] 蒲鲁东在1848—1849年革命时期做了组织交换银行的尝试。他的人民银行（Banque du peuple）于1849年1月31日在巴黎成立。银行存在了两个月左右，而且只是在纸面上：它在开始正常业务活动以前就破产了，并于4月初宣告关闭。——第217页。","language":"中文","translation":false},{"id":"socialism-3-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-3-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"社会主义从空想到科学的发展","language":"中文","translation":false},{"id":"socialism-3-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"这时，和十八世纪的法国哲学一起并继它之后，现代德国哲学产生了，而且在黑格尔身上达到了顶峰。它的最大的功绩，就是恢复了辩证法这一最高的思维形式。古希腊的哲学家都是天生的自发的辩证论者，他们中最博学的人物亚里士多德就已经研究了辩证思维的最主要的形式。而近代哲学虽然也有辩证法的卓越代表（例如笛卡儿和斯宾诺莎），却日益陷入（特别是由于英国的影响）所谓形而上学的思维方式；十八世纪的法国人也几乎全都为这种思维方式所支配，至少在他们的专门哲学的著作中是如此。可是，在本来意义的哲学之外，他们也能够写出辩证法的杰作；我们只要提一下狄德罗的“拉摩的侄子”[136]和卢梭的“论人间不平等的起源”就够了。——在这里，我们来简略地谈谈这两种思维方法的实质。","language":"中文","translation":false},{"id":"socialism-3-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"当我们深思熟虑地考察自然界、人类历史或我们的精神活动的时候，首先呈现在我们眼前的是一幅由种种联系和相互作用无穷无尽地交织起来的画面，其中没有任何东西是不动的和不变的，而是一切都在运动、变化、产生和消失。所以我们首先看到的是总的画面，其中各个细节还或多或少地隐在背景中，我们注意得更多的是运动、转变和联系，而不是什么在运动、转变和联系。这个原始的、素朴的但实质上正确的世界观是古希腊哲学的世界观，而且是由赫拉克利特第一次明白地表述出来的：一切都存在，同时又不存在，因为一切都在流动，都在不断地变化，不断地产生和消失。但是，这种观点虽然正确地把握了现象的总画面的一般性质，却不足以说明构成这幅总画面的各个细节；而我们要是不知道这些细节，就看不清总的画面。为了认识这些细节，我们不得不把它们从自然的或历史的联系中抽出来，从它们的特性、它们的特殊的原因和结果等等方面来逐个地加以研究。这首先是自然科学和历史研究的任务；而这些科学部门，由于十分明显的原因，在古典时代的希腊人那里只占有从属的地位，因为他们首先必须为这种研究搜集材料。只有当自然和历史的材料搜集到一定程度以后，才能进行批判的分析和比较，并相应地进行纲、目和种的划分。因此，精确的自然研究只是在亚历山大里亚时期[137]的希腊人那里才开始，而后来在中世纪由阿拉伯人继续发展下去；可是真正的自然科学只是从十五世纪后半期才开始，从这时起它就获得了日益迅速的进展。把自然界分解为各个部分，把自然界的各种过程和事物分成一定的门类，对有机体的内部按其多种多样的解剖形态进行研究，这是最近四百年来在认识自然界方面获得巨大进展的基本条件。但是，这种做法也给我们留下了一种习惯：把自然界的事物和过程孤立起来，撇开广泛的总的联系去进行考察，因此就不是把它们看做运动的东西，而是看做静止的东西；不是看做本质上变化着的东西，而是看做永恒不变的东西；不是看做活的东西，而是看做死的东西。这种考察事物的方法被培根和洛克从自然科学中移到哲学中以后，就造成了最近几个世纪所特有的局限性，即形而上学的思维方式。","language":"中文","translation":false},{"id":"socialism-3-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"在形而上学者看来，事物及其在思想上的反映，即概念，是孤立的、应当逐个地和分别地加以考察的、固定的、僵硬的、一成不变的研究对象。他们在绝对不相容的对立中思维；他们的说法是：“是就是，不是就不是；除此以外，都是鬼话”[138]。在他们看来，一个事物要么存在，要么就不存在；同样，一个事物不能同时是自己又是别的东西。正和负是绝对互相排斥的；原因和结果也同样是处于固定的相互对立中。初看起来，这种思维方式对我们来说似乎是不言而喻的，因为它是合乎所谓常识的。然而，常识在它自己的日常活动范围内虽然是极可尊敬的伴侣，但它一跨入广阔的研究领域，就会有最惊人的遭遇。形而上学的思维方式，虽然在相当广泛的、各依对象的性质而大小不同的领域中是正当的，甚至必要的，可是它每一次都迟早要达到一个界限，一超过这个界限，它就要变成片面的、狭隘的、抽象的，并且陷入不可解决的矛盾，因为它看到一个一个的事物，忘了它们互相间的联系；看到它们的存在，忘了它们的产生和消失；看到它们的静止，忘了它们的运动；因为它只见树木，不见森林。例如，在日常生活中，我们知道，并且可以肯定地说某种动物存在还是不存在；但是在进行较精确的研究时，我们就发现这有时是极其复杂的事情。这一点法学家们知道得很清楚，他们绞尽脑汁去发现一条判定在子宫内杀死胎儿是否算是谋杀的合理界限，结果总是徒劳。同样，要确定死的时刻也是不可能的，因为生理学证明，死并不是突然的、一瞬间的现象，而是一个很长的过程。同样，任何一个有机体，在每一瞬间都是它本身，又不是它本身；在每一瞬间，它同化着自外界供给的物质，并排泄出另一种物质；在每一瞬间，它的机体中都有细胞在死亡，也有新的细胞在形成；经过或长或短的一段时间，这个机体的物质便完全更新了，由其他物质的原子代替了，所以，每个有机体永远是它本身，同时又是别的东西。在进行较精确的考察时，我们也发现，某种对立的两极，例如正和负，是彼此不可分离的，正如它们是彼此对立的一样，而且不管它们如何对立，它们总是互相渗透的；同样，原因和结果这两个观念，只有在应用于个别场合时才有其本来的意义；可是只要我们把这种个别场合放在它和世界整体的总联系中来考察，这两个观念就汇合在一起，融化在普遍相互作用的观念中，在这种相互作用中，原因和结果经常交换位置；在此时或此地是结果的，在彼时或彼地就成了原因，反之亦然。","language":"中文","translation":false},{"id":"socialism-3-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"所有这些过程和思维方法都是形而上学思维的框子所容纳不下的。相反地，对辩证法来说，上述过程正好证明了它自己的方法是正确的，因为辩证法在考察事物及其在头脑中的反映时，本质上是从它们的联系、它们的连结、它们的运动、它们的产生和消失方面去考察。自然界是检验辩证法的试金石，而且我们必须说，现代自然科学为这种检验提供了极其丰富的、与日俱增的材料，并从而证明了，自然界的一切归根到底是辩证地而不是形而上学地发生；自然界不是循着一个永远一样的不断重复的圆圈运动，而是经历着实在的历史。这里首先就应当指出达尔文，他极其有力地打击了形而上学的自然观，因为他证明了今天的整个有机界，植物和动物，因而也包括人类在内，都是延续了几百万年的发展过程的产物。可是，因为学会辩证地思维的自然科学家到现在还屈指可数，所以，现在统治于理论自然科学中并使教师和学生、作者和读者都同样感到绝望的那种无限混乱的状态，完全可以从已经达到的成果和传统的形而上学思维方式之间的这个冲突中得到说明。","language":"中文","translation":false},{"id":"socialism-3-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"因此，要精确地描绘宇宙、宇宙的发展和人类的发展，以及这种发展在人们头脑中的反映，就只有用辩证的方法，只有经常注意产生和消失之间，前进的变化和后退的变化之间的普遍相互作用才能做到。现代德国哲学一开始就是以这种精神进行活动的。康德一开始他的科学生涯，就把牛顿的稳定的和自从有名的第一次推动作出以后就永远如此的太阳系变成了历史的过程，即太阳和一切行星由旋转的星云团产生的过程。同时，他已经作出了这样的结论：太阳系的产生也预示着它将来的不可避免的灭亡。过了半个世纪，他的观点由拉普拉斯从数学上作出了证明；又过了半个世纪，分光镜证明了，在宇宙的空间存在着凝聚程度不同的炽热的气团[139]。","language":"中文","translation":false},{"id":"socialism-3-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"这种现代德国哲学在黑格尔的体系中达到了顶峰，在这个体系中，黑格尔第一次——这是他的巨大功绩——把整个自然的、历史的和精神的世界想像为一个过程，即想像它是处在不断的运动、变化、改造和发展中，并企图揭示这种运动和发展的内在联系。从这个观点看来，人类的历史已经不再是乱七八糟的一堆统统应当被这时已经成熟了的哲学理性的法庭所唾弃并尽快被人遗忘的毫无意义的暴力行为，而是人类本身的发展过程，而思维的任务现在就在于通过一切迂回曲折的道路去探索这一过程的依次发展的阶段，并且透过一切表面的偶然性揭示这一过程的内在规律性。","language":"中文","translation":false},{"id":"socialism-3-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"至于黑格尔的体系没有解决它给自己提出的这个任务，在这里是无关紧要的；它的划时代的功绩是在于它提出了这个任务。这不是任何个别的人所能解决的任务。虽然黑格尔和圣西门一样是当时最博学的人，但是他毕竟受到了限制，首先是他自己的必然有限的知识的限制，其次是他那个时代的在广度在深度方面都同样有限的知识和见解的限制。但是除此以外还有第三种限制。黑格尔是唯心主义者，就是说，在他看来，他头脑中的思想不是现实的事物和过程的多少抽象的反映，相反地，在他看来，事物及其发展只是在世界出现以前已经以某种方式存在着的“观念”的现实化的反映。这样，一切都被弄得头足倒置了，世界的现实联系完全被颠倒了。所以，不论黑格尔如何正确地和天才地把握了一些个别的联系，但由于上述原因，就是在细节上也有许多东西不能不是牵强的、造作的、虚构的，一句话，被歪曲的。黑格尔的体系作为体系来说，是一次巨大的流产，但也是这类流产中的最后一次。它还包含着不可救药的内在矛盾：一方面，它以历史的观点作为基本前提，即把人类的历史看做一个发展过程，这个过程按其本性来说是不能通过发现所谓绝对真理来达到其智慧的顶峰的；但是另一方面，它又硬说自己是这个绝对真理的全部内容。包罗万象的、最终完成的关于自然和历史的认识的体系是和辩证思维的基本规律相矛盾的；但是这决不排斥，反而肯定，对于整个外部世界的有系统的认识是可以一代一代地得到巨大进展的。","language":"中文","translation":false},{"id":"socialism-3-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"了解了以往的德国唯心主义的完全荒谬，这就必然导致唯物主义，但是要注意，并不是导致十八世纪的纯形而上学的、完全机械的唯物主义。和那种以天真的革命精神笼统地抛弃以往的全部历史的做法相反，现代唯物主义把历史看做人类的发展过程，而它的任务就在于发现这个过程的运动规律。无论在十八世纪的法国人那里，还是在黑格尔那里，占统治地位的自然观都是：自然界是一个在狭小的循环中运动的、永远不变的整体，其中有牛顿所说的永恒的天体和林耐所说的不变的有机物种。和这个自然观相反，现代唯物主义概括了自然科学的最新成就，从这些成就看来，自然界也有自己的时间上的历史，天体和在适宜条件下存在于天体上的有机物种一样是有生有灭的；至于循环，即使它能够存在，也具有无限加大的规模。在这两种情况下，现代唯物主义都是本质上辩证的，而且不再需要任何凌驾于其他科学之上的哲学了。一旦对每一门科学都提出了要求，要它弄清它在事物以及关于事物的知识的总联系中的地位，关于总联系的任何特殊科学就是多余的了。于是，在以往的全部哲学中还仍旧独立存在的，就只有关于思维及其规律的学说——形式逻辑和辩证法。其他一切都归到关于自然和历史的实证科学中去了。","language":"中文","translation":false},{"id":"socialism-3-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"但是，当自然观的这种变革只能随着研究工作提供相应的实证的认识材料而实现的时候，一些在历史观上引起决定性转变的历史事实已经老早就发生了。1831年在里昂发生了第一次工人起义；在1838—1842年，第一次全国性的工人运动，即英国的宪章派运动，达到了自己的最高点。无产阶级和资产阶级间的阶级斗争一方面随着大工业的发展，另一方面随着资产阶级新近取得的政治统治的发展，在欧洲最发达的国家的历史中升到了首要地位。事实日益令人信服地证明，资产阶级经济学关于资本和劳动的利益一致、关于自由竞争必将带来普通协调和全民幸福的学说完全是撒谎。所有这些事实都再不能不加考虑了，正如作为这些事实的理论表现（虽然是极不完备的表现）的法国和英国的社会主义不能不加考虑一样。但是，旧的、还没有被排除掉的唯心主义历史观不知道任何基于物质利益的阶级斗争，而且根本不知道任何物质利益；生产和一切经济关系，在它那里只是被当做“文化史”的从属因素顺便提到过。","language":"中文","translation":false},{"id":"socialism-3-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"新的事实迫使人们对以往的全部历史作一番新的研究，结果发现：以往的全部历史，除原始状态外，都是阶级斗争的历史；这些互相斗争的社会阶级在任何时候都是生产关系和交换关系的产物，一句话，都是自己时代的经济关系的产物；因而每一时代的社会经济结构形成现实基础，每一个历史时期由法律设施和政治设施以及宗教的、哲学的和其他的观点所构成的全部上层建筑，归根到底都是应由这个基础来说明的。黑格尔把历史观从形而上学中解放了出来，使它成为辩证的，可是他的历史观本质上是唯心主义的。现在，唯心主义从它的最后的避难所中，从历史观中被驱逐出来了，唯物主义历史观被提出来了，用人们的存在说明他们的意识而不是像以往那样用人们的意识说明他们的存在这样一条道路已经找到了。","language":"中文","translation":false},{"id":"socialism-3-13","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"因此，社会主义现在已经不再被看做某个天才头脑的偶然发现，而被看做两个历史地产生的阶级无产阶级和资产阶级间斗争的必然产物。它的任务不再是想出一个尽可能完善的社会制度，而是研究必然产生这两个阶级及其相互斗争的那种历史的经济的过程；并在由此造成的经济状况中找出解决冲突的手段。可是以往的社会主义同这种唯物主义观点是不相容的，正如法国唯物主义的自然观同辩证法和现代自然科学不相容一样。以往的社会主义固然批判过现存的资本主义生产方式及其后果，但是它不能说明这个生产方式，因而也就不能对付这个生产方式；它只能简单地把它当做坏东西抛弃掉。它愈是义愤填膺地反对这种生产方式必然产生的对工人阶级的剥削，就愈是不能明白指出这种剥削在哪里和怎样发生。但是，问题是在于：一方面说明资本主义生产方式的历史联系和它对一定历史时期的必然性，从而说明它灭亡的必然性，另一方面揭露这种生产方式内部的一直还隐蔽着的性质。这已经由于剩余价值的发现而完成了。已经证明，无偿劳动的占有是资本主义生产方式和通过这种生产方式对工人进行的剥削的基本形式；即使资本家按照劳动力作为商品在市场上所具有的全部价值来购买他的工人的劳动力，他从这劳动力榨取的价值仍然比他为这劳动力付出的多；这种剩余价值归根到底构成了有产阶级手中日益增加的资本量所由积累而成的价值总量。这样就说明了资本主义生产和资本生产的过程。","language":"中文","translation":false},{"id":"socialism-3-14","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"这两个伟大的发现——唯物主义历史观和通过剩余价值揭破资本主义生产的秘密，都应当归功于马克思。由于这些发现，社会主义已经变成了科学，现在的问题首先是对这门科学的一切细节和联系作进一步的探讨。","language":"中文","translation":false},{"id":"socialism-3-15","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"[136] 德·狄德罗的对话“拉摩的侄子”（《Le neveu de Rameau》）是1762年前后写成的，后来又经作者修改了两次。最初它是由歌德译成德文于1805年在莱比锡出版的。真正的法文版发表在1821年（实际上是1823年）巴黎出版的“狄德罗轶文集”（《Oeuvres inédites de Dide-rot》）一书中。——第219页。","language":"中文","translation":false},{"id":"socialism-3-16","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"[137] 科学发展的亚历山大里亚时期是指纪元前三世纪到公元七世纪的时期，这个名称是由埃及的一个城市、当时国际经济关系最大中心之一亚历山大里亚（位于地中海沿岸）得到的。在亚历山大里亚时期，许多科学，如数学和力学（欧几里得和阿基米德）、地理学、天文学、解剖学、生理学等等获得了很大的发展。——第220页。","language":"中文","translation":false},{"id":"socialism-3-17","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"[138] “圣经”，“马太福音”第5章第37节。——第221页。","language":"中文","translation":false},{"id":"socialism-3-18","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"[139] 根据康德的星云假说，太阳系是从原始星云（拉丁文：nebula——雾）发展而来的，他在1755年科尼斯堡和莱比锡出版的著作“自然通史和天体论，或根据牛顿原理论述宇宙的结构和机械起源的尝试”（《All-gemeine Naturgeschichte und Theorie des Himmels，oder Versuch von der Verfassung und dem mechanischen Ursprunge des ganzen Weltgebäudes nach Newtonischen Grundsätzen abgehandelt》．Königsberg und Leipzig，1755）中阐述了这一假说。这本书是匿名出版的。","language":"中文","translation":false},{"id":"socialism-3-19","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（二）","page":3,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/1880/02.htm","text":"拉普拉斯关于太阳系的构成的假说最初是在他于法兰西共和国四年［1796］在巴黎出版的“宇宙体系解说”第1—2卷（《Exposition du systême du monde》．T．Ⅰ-Ⅱ，Paris，l'an Ⅳ de la République Française［1796］）中得到了阐述。在作者拉普拉斯生前编好而在死后出版的该书的最后一版即第六版中，这个假说是在该书的最后一个，即第七个注释中加以阐述的。——第223页。","language":"中文","translation":false},{"id":"socialism-4-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-4-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"社会主义从空想到科学的发展","language":"中文","translation":false},{"id":"socialism-4-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"唯物主义历史观从下述原理出发：生产以及随生产而来的产品交换是一切社会制度的基础；在每个历史地出现的社会中，产品分配以及和它相伴随的社会之划分为阶级或等级，是由生产什么、怎样生产以及怎样交换产品来决定的。所以，一切社会变迁和政治变革的终极原因，不应当在人们的头脑中，在人们对永恒的真理和正义的日益增进的认识中去寻找，而应当在生产方式和交换方式的变更中去寻找；不应当在有关的时代的哲学中去寻找，而应当在有关的时代的经济学中去寻找。对现存社会制度的不合理和不公平、对“理性化为无稽，幸福变成苦痛”［注：歌德“浮士德”第一部第四场（“浮士德的书斋”）。——编者注］的日益清醒的认识，只是一种征象，表示在生产方法和交换形式中已经静悄悄地发生了变化，适合于早先的经济条件的社会制度已经不再和这些变化相适应了。同时这还说明，用来消除已经发现的弊病的手段，也必然以多少发展了的形式存在于已经发生变化的生产关系本身中。这些手段不应当从头脑中发明出来，而应当通过头脑从生产的现成物质事实中发现出来。","language":"中文","translation":false},{"id":"socialism-4-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"那末，现代社会主义的情况究竟怎样呢？","language":"中文","translation":false},{"id":"socialism-4-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"现在大家几乎都承认，现存的社会制度是由现在的统治阶级即资产阶级创立的。资产阶级所固有的生产方式（从马克思以来称为资本主义生产方式），是同封建制度的地方特权、等级特权以及相互的人身束缚不相容的；资产阶级摧毁了封建制度，并且在它的废墟上建立了资产阶级的社会制度，建立了自由竞争、自由迁徙、商品所有者平等的王国，以及资产阶级的一切美妙东西。资本主义生产方式现在可以自由发展了。自从蒸汽和新的工具机把旧的工场手工业变成大工业以后，在资产阶级领导下造成的生产力［注：在“马克思恩格斯全集”德文版第19卷中这里是：生产关系，并加了一个脚注：“在‘反杜林论’中是：生产力。”——译者注］，就以前所未闻的速度和前所未闻的规模发展起来了。但是，正如从前工场手工业以及在它影响下进一步发展了的手工业同封建的行会桎梏发生冲突一样，大工业得到比较充分的发展时就同资本主义生产方式用来限制它的框框发生冲突了。新的生产力已经超过了这种生产力的资产阶级利用形式；生产力和生产方式之间的这种冲突，并不是像人的原罪和神的正义的冲突那样产生于人的头脑中，而是实际地、客观地、在我们之外、甚至不依赖于引起这种冲突的那些人的意志或行动而存在着。现代社会主义不过是这种实际冲突在思想上的反映，是它在头脑中、首先是在那个直接吃到它的苦头的阶级即工人阶级的头脑中的观念的反映。","language":"中文","translation":false},{"id":"socialism-4-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"那末这种冲突表现在哪里呢？","language":"中文","translation":false},{"id":"socialism-4-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"在资本主义生产出现以前，即在中世纪，普遍地存在着以劳动者对他的生产资料的私有为基础的小生产：小农即自由农或依附农的农业和城市的手工业。劳动资料——土地、农具、作坊、手工业工具——都是个人的劳动资料，只供个人使用，因而必然是小的、简陋的、有限的。但是，正因为如此，它们也照例是属于生产者自己的。把这些分散的小的生产资料加以集中和扩大，把它们变成现代的强有力的生产杠杆，这正是资本主义生产方式及其体现者即资产阶级的历史作用。关于资产阶级怎样从十五世纪起经过简单协作、工场手工业和大工业这三个阶段历史地实现了这种作用，马克思在“资本论”第四编中已经作了详尽的阐述[140]。但是，正如马克思在那里所证明的，资产阶级要是不把这些有限的生产资料从个人的生产资料变为社会化的，即只能由大批人共同使用的生产资料，就不能把它们变成强大的生产力。纺纱机、机动织布机和蒸汽锤代替了纺车、手工织布机和手工锻锤；需要成百上千的人进行协作的工厂代替了小作坊。和生产资料一样，生产本身也从一系列的个人行动变成了一系列的社会行动，而产品也从个人的产品变成了社会的产品。现在工厂所出产的纱、布、金属制品，都是许多工人的共同产品，都必须顺次经过他们的手，然后才变为成品。他们当中没有一个人能够说：“这是我做的，这是我的产品”。","language":"中文","translation":false},{"id":"socialism-4-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"但是，在以自发的、无计划地逐渐产生的社会内部分工作为生产的基本形式的地方，这种分工就使产品带有商品的形式，商品的相互交换，即买和卖，就使个体生产者有可能满足自己的各式各样的需要。中世纪的情况就是这样。例如，农民把农产品卖给手工业者，而从他们那里买得手工业品。在这个个体生产者即商品生产者的社会中，渗入了一种新的生产方式。在支配全社会的自发的无计划的分工中间，它确立了在个别工厂里组织起来的有计划的分工；在个体生产旁边出现了社会化的生产。两者的产品在同一市场上出卖，因而价格至少大体相等。但是，有计划的组织要比自发的分工有力；实行社会化劳动的工厂里所制造的产品，要比分散的小生产者所制造的便宜。个体生产在一个又一个的部门中遭到失败，社会化的生产使全部旧的生产方式革命化了。但是它的这种革命性质并没有为人所认识，结果它反而被用来当做提高和促进商品生产的手段。它的产生，是同商品生产和商品交换的一定的已经存在的杠杆即商业资本、手工业、雇佣劳动直接联系着的。由于它本身是作为商品生产的一种新形式出现的，所以商品生产的占有形式对它也保持着全部效力。","language":"中文","translation":false},{"id":"socialism-4-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"在中世纪得到发展的那种商品生产中，劳动产品应当属于谁的问题根本不可能发生。当时个体生产者通常都用自己所有的、往往是自己生产的原料，用自己的劳动资料，用自己成家属的手工劳动来制造产品。这样的产品根本用不着他去占有，它自然是属于他的。因此，产品的所有权是以自己的劳动为基础的。即使利用过别人的帮助，这种帮助通常也是次要的，而且往往除工资以外还得到别的报酬：行会的学徒和帮工与其说是为了吃饭和挣钱而劳动，不如说是为了自己学成手艺当师傅而劳动。后来生产资料开始集中于大的作坊和手工工场，开始变为真正社会化的生产资料。但是这些社会化的生产资料和产品还像从前一样被当做个人的生产资料和产品来处理。从前，劳动资料的占有者占有产品，因为这些产品通常是他自己的产品，别人的辅助劳动是一种例外，而现在，劳动资料的占有者还继续占有产品，虽然这些产品已经不是他的产品，而完全是别人劳动的产品了。这样，现在由社会化劳动所生产的产品已经不是为那些真正使用生产资料和真正生产这些产品的人所占有，而是为资本家所占有。生产资料和生产实质上已经变成社会化的了。但是，它们仍然服从于这样一种占有形式，这种占有形式是以个体的私人生产为前提，因而在这种形式下每个人都占有自己的产品并把这个产品拿到市场上去出卖。生产方式虽然已经消灭了这一占有形式的前提，但是它仍然服从于这一占有形式［注：这里无需解释，虽然占有形式还是原来那样，可是占有的性质由于上述过程而经历的革命，并不亚于生产所经历的革命。我占有我自己的产品或者占有别人的产品，这自然是两种很不相同的占有。顺便提一下：包含着整个资本主义生产方式的萌芽的雇佣劳动是很古老的；它个别地和分散地同奴隶制度并存了几百年。但是只有在历史前提已经具备时，当一萌芽才能发展成资本主义生产方式。］。这个使新的生产方式具有资本主义性质的矛盾已经包含着现代的一切冲突的萌芽。新的生产方式愈是在一切有决定意义的生产部门和一切在经济上起决定作用的国家里占统治地位，并从而把个体生产排挤到无足轻重的残余地位，社会化生产和资本主义占有的不相容性，也必然愈加鲜明地表现出来。","language":"中文","translation":false},{"id":"socialism-4-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"如上所述，最初的资本家就已经遇到了现成的雇佣劳动形式。但是，那时雇佣劳动是一种例外，一种副业，一种救急办法，一种暂时措施。不时出去打短工的农业劳动者都有自己的只能借以糊口的几亩土地。行会制度规定今天的帮工明天可以成为师傅。但是，生产资料一旦变为社会化的生产资料并集中于资本家手中，情形就改变了。个体小生产者的生产资料和产品变得愈来愈没有价值；他们除了受雇于资本家就没有别的出路。雇佣劳动以前是一种例外和救急办法，现在成了整个生产的通例和基本形式；以前是一种副业，现在成了工人的唯一职业。暂时的雇佣劳动者变成了终身的雇佣劳动者。此外，由于同时发生的封建制度的崩溃，由于封建主扈从人员被解散，农民被逐出自己的家园等等，终身的雇佣劳动者大量增加了。集中于资本家手中的生产资料和除了自己的劳动力以外一无所有的生产者彻底分裂了。社会化生产和资本主义占有之间的矛盾表现为无产阶级和资产阶级的对立。","language":"中文","translation":false},{"id":"socialism-4-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"我们已经看到，资本主义生产方式渗入了商品生产者即通过自己产品的交换来实现社会联系的个体生产者的社会。但是，每个以商品生产为基础的社会都有一个特点：这里的生产者丧失了对他们自己的社会关系的支配权。每个人都用自己偶然拥有的生产资料并为自己的特殊的交换需要而各自进行生产。谁也不知道，他的那种商品出现在市场上的会有多少，究竟需要多少；谁也不知道，他的个人产品是否真正为人所需要，是否能收回它的生产费用，或者是否能卖出去。社会生产的无政府状态占统治地位。但是，商品生产同任何其他生产形式一样，有其特殊的、固有的、和它分不开的规律；这些规律不顾无政府状态、在无政府状态中、通过无政府状态来为自己开辟道路。这些规律在唯一保留下来的社会联系形式即交换中表现出来，并且作为强制性的竞争规律作用于各个生产者。所以，这些规律起初连这些生产者也不知道，只是由于长期的经验才逐渐被他们揭示出来。所以，这些规律是在不经过生产者并且和生产者对立的情况下，作为他们的生产形式的盲目起作用的自然规律为自己开辟道路的。产品支配着生产者。","language":"中文","translation":false},{"id":"socialism-4-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"在中世纪的社会里，特别是在最初几世纪，生产基本上是为了供自己消费。它主要只是满足生产者及其家属的需要。在那些有人身依附关系的地方，例如在农村中，生产还满足封建主的需要。因此，在这里没有交换，产品也不具有商品的性质。农民家庭差不多生产了自己所需要的一切：食物、用具和衣服。只有当他们在满足自己的需要并向封建主缴纳实物租税以后还能生产更多的东西时，他们才开始生产商品；这种投入社会交换即拿去出卖的多余产品就成了商品。诚然，城市手工业者一开始就必然为交换而生产。但是他们也自己生产自己所需要的大部分东西；他们有园圃和小块土地；他们在公共森林中放牧牲畜，并且从这些森林中取得木材和燃料；妇女纺麻，纺羊毛等等。以交换为目的的生产，即商品生产，还只是在形成中。因此，交换是有限的，市场是狭小的，生产方式是稳定的，地方和外界是隔绝的，地方内部是团结的；农村中有马尔克［注：见书末的附录。［这里恩格斯指的是他的著作“马尔克”。见本卷第351—369页。——编者注］］，城市中有行会。","language":"中文","translation":false},{"id":"socialism-4-13","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"但是，随着商品生产的扩展，特别是随着资本主义生产方式的出现，以前潜伏着的商品生产规律也就愈来愈公开、愈来愈有力地发挥作用了。旧日的束缚已经松弛，旧日的壁障已经突破，生产者日益变为独立的、分散的商品生产者了。社会生产的无政府状态已经表现出来，并且愈来愈走向极端。但是，资本主义生产方式用来加剧社会生产中的这种无政府状态的主要工具正是无政府状态的直接对立物：每一个别生产企业中的社会化生产所具有的日益加强的组织性。资本主义生产方式利用这一杠杆结束了旧日的和平的稳定状态。它在哪一个工业部门被采用，就不容许任何旧的生产方法在那里和它并存。它控制了手工业，就把旧的手工业消灭掉。劳动场地变成了战场。伟大的地理发现以及随之而来的殖民地的开拓使销售市场扩大了许多倍，并且加速了手工业向工场手工业的转化。斗争不仅爆发于地方的各个生产者之间；地方性的斗争已经发展为全国性的，发展为十七和十八世纪的商业战争[141]。最后，大工业和世界市场的形成使这个斗争成为普遍的，同时使它具有了空前的剧烈性。在资本家和资本家之间，在产业和产业之间以及国家和国家之间，生存问题都决定于天然的或人为的生产条件的优劣。失败者被无情地清除掉。这是从自然界加倍疯狂地搬到社会中的达尔文的生存斗争。动物的自然状态竟表现为人类发展的顶点。社会化生产和资本主义占有之间的矛盾表现为个别工厂中的生产的组织性和整个社会的生产的无政府状态之间的对立。","language":"中文","translation":false},{"id":"socialism-4-14","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"资本主义生产方式在它由于自己的起源而固有的矛盾的这两种表现形式中运动着，它毫无出路地进行着早已为傅立叶所发现的“恶性循环”。诚然，傅立叶在他那个时代还不能看到：这种循环在逐渐缩小；运动宁可说是在按螺旋形进行，并且必然像行星的运动一样，由于和中心相碰撞而告终。社会的生产无政府状态的推动力使大多数人日益变为无产者，而无产者群众又将最终结束生产的无政府状态。社会的生产无政府状态的推动力，使大工业中的机器无限改进的可能性变成一种迫使每个工业资本家在遭受毁灭的威胁下不断改进自己的机器的强制性法令。但是，机器的改进就造成人的劳动的过剩。如果说，机器的采用和推广意味着成百万的手工劳动者为少数机器劳动者所排挤，那末，机器的改进就意味着愈来愈多的机器劳动者本身受到排挤，而归根到底就意味着形成一批超过资本在经营上的平均需要的、待雇的雇佣劳动者，一支真正的产业后备军（我早在1845年就这样称呼他们［注：“英国工人阶级状况”第109页。［见“马克思恩格斯全集”中文版第2卷第369页。——编者注］］），这支后备军在工业开足马力工作的时期可以随意使用，而由于必然随着这个时期到来的崩溃又被抛到街头，这支后备军任何时候都是工人阶级在自己对资本进行生存斗争中的绊脚石，是把工资抑制在合乎资本家需要的低水平上的调节器。这样一来，机器，用马克思的话来说，就成了资本用来对付工人阶级的最有力的武器，劳动资料不断地夺走工人手中的生活资料，工人自己的产品变成了奴役工人的工具[142]。于是，劳动资料的节省一开始就同时成为劳动力的最严重的浪费和对劳动机能的正常前提的掠夺[143]；机器这一缩短劳动时间的最有力的手段，变成了使工人及其家属一生的时间转化为可以随意用来增殖资本的劳动时间的最可靠的手段；于是，一部分人的过度劳动造成了另一部分人的失业，而在全世界追逐新消费者的大工业，却在国内把群众的消费限制到需要忍饥挨饿这样一个最低水平，从而破坏了自己的国内市场。“使相对的过剩人口或产业后备军同资本积累的规模和能力始终保持平衡的规律把工人钉在资本上，比赫斐斯塔司的楔子把普罗米修斯钉在岩石上钉得更牢。这一规律制约着同资本积累相适应的贫困积累。因此，在一极是财富的积累，同时在另一极，即在把自己的产品作为资本来生产的阶级方面，是贫困、劳动折磨、受奴役、无知、粗野和道德堕落的积累。”（马克思“资本论”第671页）[144]。而从资本主义生产方式中期待产品的另一种分配，那就等于希望电池的电极和电池相联时不使水分解，不在阳极放出氧和阴极放出氢。","language":"中文","translation":false},{"id":"socialism-4-15","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"我们已经看到，现代机器的已经达到最高程度的改进的可能性，怎样由于社会中的生产无政府状态而变成一种迫使各个工业资本家不断改进自己的机器、不断提高机器的生产能力的强制性法令。对资本家来说，扩大自己的生产规模的单纯的实际可能性也变成了同样的强制性法令。大工业的巨大的扩张力——气体的膨胀力和它相比简直是儿戏——现在在我们面前表现为不顾任何阻力的、在质量上和数量上进行扩张的需要。这种阻力是由大工业产品的消费、销路和市场形成的。但是，市场向广和深方面扩张的能力首先是受完全不同的、力量弱得多的规律支配的。市场的扩张赶不上生产的扩张。冲突成为不可避免的了，而且，因为它在把资本主义生产方式本身炸毁以前不能使矛盾得到解决，所以它也成为周期性的了。资本主义生产产生了新的“恶性循环”。","language":"中文","translation":false},{"id":"socialism-4-16","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"事实也是这样，自从1825年第一次普遍危机爆发以来，整个工商业世界，一切文明民族及其多少尚未开化的附属地中的生产和交换，差不多每隔十年就要出轨一次。商业停顿，市场盈溢，产品滞销，银根奇紧，信用停止，工厂关门，工人群众因为他们生产的生活资料过多而缺乏生活资料，破产相继发生，拍卖纷至沓来。停滞状态持续了几年，生产力和产品被大量浪费和破坏，直到最后，大批积压的商品以或多或少压低了的价格卖出去，生产和交换的运动逐渐恢复起来。运动逐渐加快，慢步转成快步，工业快步转成跑步，跑步又转成工业、商业、信用和投机事业的真正障碍赛马中的狂奔，最后，经过几次拚命的跳跃重新陷入崩溃的深渊。如此反复不已。从1825年以来，这种情况我们已经历了整整五次，目前（1877年）正经历着第六次。这些危机的性质表现得这样明显，以致傅立叶把第一次危机称为crise pléthorique即由过剩引起的危机时，就中肯地说明了一切危机的实质[145]。","language":"中文","translation":false},{"id":"socialism-4-17","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"在危机中，社会化生产和资本主义占有之间的矛盾达到剧烈爆发的地步。商品流通暂时停顿下来；流通手段即货币成为流通的障碍；商品生产和商品流通的一切规律都颠倒过来了。经济的冲突达到了顶点：生产方式起来反对交换方式。","language":"中文","translation":false},{"id":"socialism-4-18","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"工厂内部的生产的社会化组织已经发展到同存在于自己之旁并凌驾于自己之上的社会中的生产无政府状态不能相容的地步。甚至资本家也由于资本的猛烈集中而感觉到这一事实，因为在危机期间这种集中是通过许多大资本家和更多的小资本家的破产实现的。资本主义生产方式的全部机构在它自己创造的生产力的压力下失灵了。它已经不能把这大批生产资料全部变成资本；生产资料闲置起来，因此产业后备军也不得不闲置起来。生产资料、生活资料、待雇的工人，生产和一般财富的一切因素都显得过剩。但是，这种“过剩成了贫困和匮乏的源泉”（傅立叶），因为正是这种过剩阻碍生产资料和生活资料变为资本。因为在资本主义社会里，生产资料要不先变为资本，变为剥削人的劳动力的工具，就不能发挥作用。生产资料和生活资料具有资本属性的必然性，像幽灵一样站在这些资料和工人之间。唯独这个必然性阻碍着生产的物的杠杆和人的杠杆的结合；唯独它妨碍生产资料发挥作用，妨碍工人劳动和生活。因此，一方面，资本主义生产方式暴露出自己无能继续驾御这种生产力。另一方面，这种生产力本身以日益增长的威力要求消除这种矛盾，要求摆脱它作为资本的那种属性，要求在事实上承认它作为社会生产力的那种性质。","language":"中文","translation":false},{"id":"socialism-4-19","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"猛烈增长着的生产力对它的资本属性的这种反抗，要求承认它的社会本性的这种日益增长的必要性，迫使资本家阶级本身在资本关系内部可能的限度内愈来愈把生产力当做社会生产力看待。无论信用无限膨胀的工业高涨时期，还是由大资本主义企业的破产造成的崩溃本身，都把大量生产资料推向如像我们在各种股份公司中所遇见的那种社会化形式。某些生产资料和交通手段，例如铁路，一开始规模就很大，它们排斥任何其他的资本主义经营形式。在一定的发展阶段上，这种形式也嫌不够了；国内同一工业部门的大生产者联合为一个“托拉斯”，即一个以调节生产为目的的联盟；他们规定应该生产的总产量，在他们中间加以分配，并且强制实行预先规定的出售价格。但是，这种托拉斯一遇到不景气的时候大部分就陷于瓦解，正因为如此，它们就趋向于更加集中的社会化：整个工业部门变为一个唯一的庞大的股份公司，国内的竞争让位于这个公司在国内的垄断；例如还在1890年，英国的制硷业就发生了这种情形，现在，这一行业在所有48个大工厂合并以后就转到了一个唯一的、统一领导的、拥有12000万马克资本的公司手中了。","language":"中文","translation":false},{"id":"socialism-4-20","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":20,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"在托拉斯中，自由竞争转为垄断，而资本主义社会的无计划生产向行将到来的社会主义社会的计划生产投降。当然，这首先还是对资本家有利的。但是，在这里剥削变得这样明显，以致它必然要被消灭。任何一个民族都不会容忍由托拉斯领导的生产，不会容忍由一小撮专靠剪息票为生的人对全社会进行的如此露骨的剥削。","language":"中文","translation":false},{"id":"socialism-4-21","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":21,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"无论在任何情况下，无论有或者没有托拉斯，资本主义社会的正式代表——国家终究不得不［注：我说“不得不”，因为只有在生产资料或交通手段真正发展到不适于由股份公司来管理，因而国有化在经济上已成为不可避免的情况下，国有化——即使是由现代国家实行的——才意味着经济上的进步，才意味着在由社会本身占有一切生产力方面达到了一个新的准备阶段。但是最近，自从俾斯麦致力于国有化以来，出现了一种冒牌的社会主义，它有时甚至堕落为一种十足的奴才习气，直截了当地把任何一种国有化，甚至俾斯麦的国有化，都说成社会主义的。显然，如果烟草国营是社会主义的，那末拿破仑和梅特涅就应该算是社会主义的创始人了。如果说，比利时政府出于纯粹日常的政治和财政方面的考虑而自己修建自己的主要铁路，如果说，俾斯麦没有任何经济上的必要，只是为了使铁路能够在战时更好地适应和利用，为了把铁路职员训练成政府的投票家畜，主要是为了取得一种不依赖于议会决定的新的收入来源而把普鲁士的主要铁路收归国有，那末，这无论如何不是社会主义的步骤，既不是直接的，也不是间接的，既不是自觉的，也不是不自觉的。否则，皇家海外贸易公司[146]、皇家陶磁厂，甚至陆军被服厂，以致在三十年代弗里德里希－威廉三世时期由一个聪明人十分严肃地建议过的……妓院国营，也都是社会主义的设施了。］承担起对生产的领导。这种转化为国家财产的必然性首先表现在大规模的交通机构，即邮政、电报和铁路方面。","language":"中文","translation":false},{"id":"socialism-4-22","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":22,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"如果说，危机暴露出资产阶级无能继续驾御现代生产力，那末，大的生产机构和交通机构向股份公司、托拉斯和国家财产的转变就表明资产阶级在这方面不是不可缺少的。资本家的全部社会职能现在由雇佣的职员来执行了。资本家拿红利、剪息票、在各种资本家相互争夺彼此的资本的交易所中进行投机，除此以外，再没有任何其他的社会活动了。资本主义生产方式起初排挤工人，现在却在排挤资本家了，完全像对待工人那样把他们赶到过剩人口中去，虽然暂时还没有把他们赶到产业后备军中去。","language":"中文","translation":false},{"id":"socialism-4-23","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":23,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"但是，无论转化为股份公司和托拉斯，还是转化为国家财产，都没有消除生产力的资本属性。在股份公司和托拉斯那里，这一点是十分明显的。而现代国家却只是资产阶级社会为了维护资本主义生产方式的共同的外部条件使之不受工人和个别资本家的侵犯而建立的组织。现代国家，不管它的形式如何，本质上都是资本主义的机器，资本家的国家，理想的总资本家。它愈是把更多的生产力据为己有，就愈是成为真正的总资本家，愈是剥削更多的公民。工人仍然是雇佣劳动者，无产者。资本关系并没有被消灭，反而被推到了顶点。但是在顶点上是要发生变革的。生产力的国家所有不是冲突的解决，但是它包含着解决冲突的形式上的手段，解决冲突的线索。","language":"中文","translation":false},{"id":"socialism-4-24","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":24,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"这种解决只能是在事实上承认现代生产力的社会本性，因而也就是使生产、占有和交换的方式同生产资料的社会性相适应。而要实现这一点，只有由社会公开地和直接地占有已经发展到除了社会管理不适于任何其他管理的生产力。现在，生产资料和产品的社会性反过来反对生产者本身，周期性地突破生产方式和交换方式，并且只是作为盲目起作用的自然规律强制性地和破坏性地为自己开辟道路，而随着社会对生产力的占有，这种社会性就将为生产者完全自觉地运用，并且从造成混乱和周期性崩溃的原因变为生产本身的最有力的杠杆。","language":"中文","translation":false},{"id":"socialism-4-25","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":25,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"社会力量完全像自然力一样，在我们还没有认识和考虑到它们的时候，起着盲目的、强制的和破坏的作用。但是，一旦我们认识了它们，理解了它们的活动、方向和影响，那末，要使它们愈来愈服从我们的意志并利用它们来达到我们的目的，这就完全取决于我们了。这一点特别适用于今天的强大的生产力。只要我们固执地拒绝理解这种生产力的本性和性质——而资本主义生产方式及其辩护士正是抗拒这种理解的，——它就总是像上面所详细叙述的那样起违反我们、反对我们的作用，把我们置于它的统治之下。但是它的本性一旦被理解，它就会在联合起来的生产者手中从魔鬼似的统治者变成顺从的奴仆。这里的区别正像暴风雨时雷鸣闪电中的电的破坏力同电报机和弧光灯的被驯服的电之间的区别一样，正像火灾同为人服务的火之间的区别一样。当人们按照今天的生产力终于被认识了的本性来对待这种生产力的时候，社会的生产无政府状态就让位于按照全社会和每个成员的需要对生产进行的社会的有计划的调节。那时，资本主义的占有方式，即产品起初奴役生产者而后又奴役占有者的占有方式，就让位于那种以现代生产资料的本性为基础的产品占有方式：一方面由社会直接占有，作为维持和扩大生产的资料，另一方面由个人直接占有，作为生活和享乐的资料。","language":"中文","translation":false},{"id":"socialism-4-26","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":26,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"资本主义生产方式日益把大多数居民变为无产者，同时就造成一种在死亡的威胁下不得不去完成这个变革的力量。这种生产方式迫使人们日益把巨大的社会化的生产资料变为国家财产，同时它本身就指明完成这个变革的道路。无产阶级将取得国家政权，并且首先把生产资料变为国家财产。但是，这样一来它就消灭了作为无产阶级的自身，消灭了一切阶级差别和阶级对立，也消灭了作为国家的国家。迄今在阶级对立中运动着的社会需要有国家，即需要一个剥削阶级的组织，以便维持它的外部的生产条件，特别是用强力把被剥削阶级控制在当时的生产方式所决定的那些压迫条件下（奴隶制、农奴制或依附农制、雇佣劳动制）。国家是整个社会的正式代表，是社会在一个有形的组织中的集中表现，但是，说国家是这样的，这仅仅是说，它是当时独自代表整个社会的那个阶级的国家：在古代是占有奴隶的公民的国家，在中世纪是封建贵族的国家，在我们的时代是资产阶级的国家。当国家终于真正成为整个社会的代表时，它就使自己成为多余的了。当不再有需要加以镇压的社会阶级的时候，当阶级统治和根源于现代生产无政府状态的生存斗争以及由此产生的冲突和极端行动都被消除了的时候，就不再有什么需要镇压了，也就不再需要国家这种特殊的镇压力量了。国家真正作为整个社会的代表所采取的第一个行动，即以社会的名义占有生产资料，同时也是它作为国家所采取的最后一个独立行动。那时，国家政权对社会关系的干预将先后在各个领域中成为多余的事情而自行停止下来。那时，对人的统治将由对物的管理和对生产过程的领导所代替。国家不是“被废除”的，它是自行消亡的。应当以此来衡量“自由的人民国家”[147]这个用语，这个用语在鼓动的意义上暂时有存在的理由，但归根到底是没有科学根据的；同时也应当以此来衡量所谓无政府主义者提出的在一天之内废除国家的要求。","language":"中文","translation":false},{"id":"socialism-4-27","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":27,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"自从资本主义生产方式在历史上出现以来，由社会占有全部生产资料，常常作为未来的理想隐隐约约地浮现在个别人物和整个整个的派别的脑海中。但是，这种占有只有在实现它的实际条件已经具备的时候才能成为可能，才能成为历史的必然性。正如其他一切社会进步一样，这种占有之所以能够实现，并不是由于人们认识到阶级的存在同平等、正义等等相矛盾，也不是仅仅由于人们希望废除阶级，而是由于具备了一定的新的经济条件。社会分裂为剥削阶级和被剥削阶级、统治阶级和被压迫阶级，是以前生产不大发展的必然结果。当社会总劳动所提供的产品除了满足社会全体成员最起码的生活需要以外只有少量剩余，因而劳动还占去社会大多数成员的全部或几乎全部时间的时候，这个社会就必然划分为阶级。在这个完全委身于劳动的大多数人之旁，形成了一个摆脱直接生产劳动的阶级，它从事于社会的共同事务：劳动管理、政务、司法、科学、艺术等等。因此，分工的规律就是阶级划分的基础。但是这并不妨碍阶级的这种划分曾经通过暴力和掠夺、狡诈和欺骗来实现，这也不妨碍统治阶级一旦掌握政权就牺牲劳动阶级来巩固自己的统治，并把对社会的领导变成对群众的加紧剥削。","language":"中文","translation":false},{"id":"socialism-4-28","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":28,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"但是，即使阶级的划分根据上面所说具有某种历史的理由，那也只是对一定的时期、一定的社会条件才是这样。这种划分是以生产的不足为基础的，它将被现代生产力的充分发展所消灭。的确，社会阶级的消灭是以这样一个历史发展阶段为前提，在这个阶段上，不仅某个特定的统治阶级而且任何统治阶级的存在，从而阶级差别本身的存在，都将成为时代的错误，成为过时的现象。所以，阶级的消灭是以生产的高度发展阶段为前提，在这个阶段上，某一特殊的社会阶级对生产资料和产品的占有，从而对政治统治、教育垄断和精神领导的占有，不仅成为多余的，而且成为经济、政治和精神发展的障碍。这个阶段现在已经达到了。资产阶级的政治和精神的破产甚至对他们自己也未必是一种秘密了，而他们的经济破产则有规律地每十年重复一次。在每次危机中，社会在属于它自己而又不能为它自己所利用的生产力和产品的重压下奄奄一息，面对着生产者没有什么可以消费是因为缺乏消费者这种荒谬的矛盾而束手无策。生产资料的扩张力撑破了资本主义生产方式所加给它的桎梏。生产资料从这种桎梏下解放出来，是生产力不断地加速发展的唯一先决条件，因而也是生产本身实际上无限增长的唯一先决条件。但是还不止于此。生产资料的社会占有，不仅会消除生产的现存的人为障碍，而且还会消除生产力和产品的明显的浪费和破坏，这种浪费和破坏在目前是生产的不可分离的伴侣，并且在危机时期达到顶点。此外，这种占有还由于消除了现在的统治阶级及其政治代表的穷奢极欲的浪费而为全社会节省出大量的生产资料和产品。通过社会生产，不仅可能保证一切社会成员有富足的和一天比一天充裕的物质生活，而且还可能保证他们的体力和智力获得充分的自由的发展和运用，这种可能性现在是第一次出现了，但是它确实是出现了［注：有几个数字可以大体表明现代生产资料即使在资本主义压制下也有巨大的扩张力。根据吉芬的计算[148]，大不列颠和爱尔兰的全部财富约计如下： 1814年……22亿英镑＝440亿马克","language":"中文","translation":false},{"id":"socialism-4-29","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":29,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"1865年……61亿英镑＝1220亿马克","language":"中文","translation":false},{"id":"socialism-4-30","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":30,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"1875年……85亿英镑＝1700亿马克 至于在危机中生产资料和产品被破坏的情况，根据1878年2月21日在柏林举行的德国工业家第二次代表大会[149]所作的计算，在最近一次崩溃中，单是德国铁工业所遭受的全部损失就达45500万马克。］。","language":"中文","translation":false},{"id":"socialism-4-31","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":31,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"一旦社会占有了生产资料，商品生产就将被消除，而产品对生产者的统治也将随之消除。社会生产内部的无政府状态将为有计划的自觉的组织所代替。生存斗争停止了。于是，人才在一定意义上最终地脱离了动物界，从动物的生存条件进入真正人的生存条件。人们周围的、至今统治着人们的生活条件，现在却受到人们的支配和控制，人们第一次成为自然界的自觉的和真正的主人，因为他们已经成为自己的社会结合的主人了。人们自己的社会行动的规律，这些直到现在都如同异己的、统治着人们的自然规律一样而与人们相对立的规律，那时就将被人们熟练地运用起来，因而将服从他们的统治。人们自己的社会结合一直是作为自然界和历史强加于他们的东西而同他们相对立的，现在则变成他们自己的自由行动了。一直统治着历史的客观的异已的力量，现在处于人们自己的控制之下了。只是从这时起，人们才完全自觉地自己创造自己的历史；只是从这时起，由人们使之起作用的社会原因才在主要的方面和日益增长的程度上达到他们所预期的结果。这是人类从必然王国进入自由王国的飞跃。","language":"中文","translation":false},{"id":"socialism-4-32","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":32,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"最后，我们把上述的发展进程简单地概述如下：","language":"中文","translation":false},{"id":"socialism-4-33","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":33,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"一、中世纪社会：个体的小生产。生产资料是供个人使用的，因而是原始的、笨拙的、小的、效能很低的。生产或者是为了生产者本身的直接消费，或者是为了他的封建领主的直接消费。只有在生产的东西除了满足这些消费以外还有剩余的时候，这种剩余才拿去出卖和进行交换：所以商品生产刚刚处于形成过程中；但是这时它本身已经包含着社会生产的无政府状态的萌芽。","language":"中文","translation":false},{"id":"socialism-4-34","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":34,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"二、资本主义革命：起初是工业通过简单协作和工场手工业实现的变革。先前分散的生产资料集中到大作坊中，因而它们就由个人的生产资料转变为社会化的生产资料，这种转变总的说来是没有触及交换形式的。旧的占有形式仍然起作用。资本家出现了：他是生产资料的所有者，当然就占有产品并把它们变为商品。生产已经成为社会的活动，而交换和占有仍旧是个体的活动，单个人的活动：社会产品被个别资本家所占有。这就是产生现代社会借以运动并在大工业中表现得特别明显的一切矛盾的基本矛盾。","language":"中文","translation":false},{"id":"socialism-4-35","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":35,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"（a）生产者和生产资料分离。工人注定要终身从事雇佣劳动。无产阶级和资产阶级相对立。","language":"中文","translation":false},{"id":"socialism-4-36","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":36,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"（b）支配商品生产的规律日益显露出来，它们的作用日益加强。竞争不可遏止。个别工厂中的社会化组织和整个生产中的社会无政府状态相矛盾。","language":"中文","translation":false},{"id":"socialism-4-37","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":37,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"（c）一方面是机器的改进，这种改进由于竞争而变成每个厂主必须遵守的强制性法令，同时就使工人遭到不断的解雇：产生了产业后备军。另一方面是生产的无限扩张，这也成了每个厂主必须遵守的强制性的竞争规律。这两方面造成了生产力的空前发展、供过于求、生产过剩、市场盈溢、十年一次的危机、恶性循环：这里是生产资料和产品过剩，那里是没有工作和没有生活资料的工人过剩；但是，生产和社会福利的这两个杠杆不能结合起来，因为生产力和产品要不先转变为资本，资本主义的生产形式就不允许生产力发挥作用和产品进行流通，而阻碍这种转变的正是生产力和产品的过剩。这种矛盾发展到荒谬的程度：生产方式起来反对交换形式。资产阶级已经暴露出自己无能继续管理自己的社会生产力。","language":"中文","translation":false},{"id":"socialism-4-38","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":38,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"（d）资本家本身不得不部分地承认生产力的社会性。大规模的生产机构和交通机构起初由股份公司占有，后来由托拉斯占有，然后又由国家占有。资产阶级表明，自己已成为多余的阶级；它的全部社会职能现在由雇佣的职员来执行了。","language":"中文","translation":false},{"id":"socialism-4-39","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":39,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"三、无产阶级革命，矛盾的解决：无产阶级将取得社会权力，并且利用这个权力把脱离资产阶级掌握的社会化生产资料变为公共财产。通过这个行动，无产阶级使生产资料摆脱了它们迄今具有的资本属性，给它们的社会性以充分发展的自由。从此按照预定计划进行的社会生产就成为可能的了。生产的发展使不同社会阶级的继续存在成为时代的错误。随着社会生产的无政府状态的消失，国家的政治权威也将消失。人终于成为自己的社会结合的主人，从而也就成为自然界的主人，成为自己本身的主人——自由的人。","language":"中文","translation":false},{"id":"socialism-4-40","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":40,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"完成这一解放世界的事业，是现代无产阶级的历史使命。考察这一事业的历史条件以及这一事业的性质本身，从而使负有使命完成这一事业的今天受压迫的阶级认识到自己行动的条件和性质，这就是无产阶级运动的理论表现即科学社会主义的任务。","language":"中文","translation":false},{"id":"socialism-4-41","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":41,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"弗·恩格斯写于1880年1—3月上半月","language":"中文","translation":false},{"id":"socialism-4-42","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":42,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"载于1880年3月20日、4月20日和5月5日“社会主义评论”杂志第3、4和5期，并于1880年在巴黎出版法文单行本：弗·恩格斯“空想社会主义和科学社会主义”","language":"中文","translation":false},{"id":"socialism-4-43","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":43,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"中文根据“马克思恩格斯文选”两卷集1953年柏林狄茨出版社德文版译出","language":"中文","translation":false},{"id":"socialism-4-44","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":44,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[140] 见“马克思恩格斯全集”俄文第2版第23卷第322—515页〔参看“资本论”1953年人民出版社版第1卷第371—620页〕。——第230页。","language":"中文","translation":false},{"id":"socialism-4-45","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":45,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[141] 指欧洲各大国之间为争夺同印度和美洲通商的霸权以及殖民地市场而在十七和十八世纪进行的一系列战争。最初主要的竞争国家是英国和荷兰（1652—1654、1664—1667和1672—1674年的英荷战争是典型的商业战争），后来决定性的斗争是在英国和法国之间展开的。所有这些战争的胜利者是英国，到十八世纪末，在它手中已经集中了几乎全部的世界贸易。——第234页。","language":"中文","translation":false},{"id":"socialism-4-46","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":46,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[142] 恩格斯在这里引证的是“资本论”第一卷（见“马克思恩格斯全集”俄文第2版第23卷第445页和第498页〔参看“资本论”1953年人民出版社版第1卷第529—530页和第595—596页〕）。——第236页。","language":"中文","translation":false},{"id":"socialism-4-47","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":47,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[143] 见“马克思恩格斯全集”俄文第2版第23卷第473页〔参看“资本论”1953年人民出版社版第1卷第563—564页〕。——第236页。","language":"中文","translation":false},{"id":"socialism-4-48","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":48,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[144] 见“马克思恩格斯全集”俄文第2版第23卷第660页〔参看“资本论”1953年人民出版社版第1卷第813页〕。——第236页。","language":"中文","translation":false},{"id":"socialism-4-49","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":49,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[145] “傅立叶全集”1845年巴黎版第6卷第393—394页（Ch．Fourier．Oeuvres complètes，t．Ⅵ，Paris，1845，p．393—394）。——第237页。","language":"中文","translation":false},{"id":"socialism-4-50","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":50,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[146] Seehandlung（海外贸易公司）是1772年在普鲁士成立的贸易信用公司。该公司享有许多重要的国家特权，它给予政府巨额贷款，实际上起了政府的银行老板和财政方面的经纪人的作用。1904年正式成为普鲁士国家银行。——第239页。","language":"中文","translation":false},{"id":"socialism-4-51","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":51,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[147] “自由的人民国家”是七十年代德国社会民主党人提出的纲领性要求和流行口号。对这个口号的马克思主义的批评，见马克思的著作“哥达纲领批判”第四节和1875年3月18—28日恩格斯给倍倍尔的信（本卷第30—35页和第3—10页）。另见列宁的著作“国家与革命”第一章第4节和第四章第3节（“列宁全集”中文版第25卷第382—388页和第426—429页）。——第242页。","language":"中文","translation":false},{"id":"socialism-4-52","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":52,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[148] 这里关于大不列颠和爱尔兰的全部财富的材料引自罗·吉芬的报告“近来联合王国的资本积累”。这个报告是1878年1月15日在统计学会宣读的，发表在1878年3月号伦敦“统计学会杂志”（《Journal of the Statistical Society》）上。——第244页。","language":"中文","translation":false},{"id":"socialism-4-53","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"社会主义从空想到科学的发展（三）","page":4,"paragraph":53,"url":"https://www.marxists.org/chinese/engels/1880/03.htm","text":"[149] 德国工业家中央联合会第二次代表大会于1878年2月21—22日在柏林举行。——第245页。","language":"中文","translation":false},{"id":"socialism-5-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-5-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"*弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言[155]","language":"中文","translation":false},{"id":"socialism-5-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"这本小册子中所包含的几页早先曾作为三篇论文发表在“社会主义评论”[156]上，它们是从恩格斯最近的著作“科学中的变革”[157]中抽出来译成法文的［注：在保·拉法格出版的“社会主义从空想到科学的发展”一书导言的正文中还做了如下的补充：“它们经作者校阅过，而且作者为了使资本主义生产的经济力量的辩证运动更容易为法国读者所理解，还在第三部分做了一些补充。”——编者注］。","language":"中文","translation":false},{"id":"socialism-5-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"弗里德里希·恩格斯是现代社会主义最杰出的代表人物之一，他在1844年就以他首先发表在马克思和卢格在巴黎出版的“德法年鉴”上的“政治经济学批判大纲”引起了注意。“大纲”中已经表述了科学社会主义的某些一般原则。在曼彻斯特（当时恩格斯住在那里），他用德文写了“英国工人阶级状况”（1845），这是一部重要的著作，其意义由马克思在“资本论”中作了充分的估价。在他第一次旅居英国以及后来旅居布鲁塞尔的时候，他是社会主义运动的正式机关报“北极星报”和罗伯特·欧文的“新道德世界”报的撰稿人[158]。","language":"中文","translation":false},{"id":"socialism-5-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"在他旅居布鲁塞尔时，他和马克思建立了德国工人共产主义俱乐部，这个俱乐部同佛来米和瓦隆的俱乐部保持了联系。他们两人和伯恩施太德一起创办了“德意志—布鲁塞尔报”。应正义者同盟设在伦敦的德国委员会的邀请，他们参加了这个由卡尔·沙佩尔在1839年因参加布朗基的密谋而不得不从法国逃出以后所创立的组织。从那时起，同盟就放弃了秘密组织的普通形式，变成国际性的共产主义者同盟了。但是在当时的情况下，同盟还必需对各国政府保持秘密。1847年，在同盟在伦敦召开的国际代表大会上，马克思和恩格斯被委托起草“共产党宣言”，“宣言”在二月革命前不久出版，并且几乎立即被翻译成欧洲的一切文字［注：在保·拉法格出版的小册子原文中还做了如下的补充：“‘共产党宣言’是现代社会主义最有价值的文件之一；它现在仍然是描述资产阶级社会的发展和必将结束资本主义社会的无产阶级的形成的最有力和最鲜明的著作之一；在这一著作中，正像在早一年出版的马克思的‘哲学的贫困’中一样，第一次清楚地表述了阶级斗争的理论。”——编者注］。","language":"中文","translation":false},{"id":"socialism-5-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"同年，马克思和恩格斯致力于建立布鲁塞尔民主协会的工作，这是一个公开的和国际性的组织，参加这个组织的有资产阶级激进派和社会主义工人的代表人物。","language":"中文","translation":false},{"id":"socialism-5-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"二月革命后，恩格斯成了“新莱茵报”的编辑之一，这家报纸是由马克思在科伦创办的，于1849年5月被普鲁士政府禁止。恩格斯参加爱北斐特起义以后，作为志愿部队指挥官维利希的副官完成了反对普鲁士人的巴登进军[159]（1849年6—7月）。","language":"中文","translation":false},{"id":"socialism-5-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"1850年，他在伦敦做“新莱茵报。政治经济评论”的撰稿人，这个刊物是由马克思出版并在汉堡刊印的。恩格斯在上面发表了“德国农民战争”，19年后在莱比锡印成小册子出版并连续出了三版。","language":"中文","translation":false},{"id":"socialism-5-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"在德国的社会主义运动重新活跃起来以后，恩格斯做了“人民国家报”和“前进报”的撰稿人；这两家报纸所发表的最重要的论文都是他写的，其中大部分都印成了小册子：“论俄国社会问题”、“德意志帝国国会中的普鲁士烧酒”、“论住宅问题”、“行动中的巴枯宁主义者”等等。","language":"中文","translation":false},{"id":"socialism-5-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"1870年恩格斯从曼彻斯特迁居伦敦以后，参加了国际总委员会；他被委托负责同西班牙、葡萄牙和意大利联系。","language":"中文","translation":false},{"id":"socialism-5-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"他寄给“前进报”并讽刺地题为“欧根·杜林先生在科学中实行的变革”的最近的一组论文，是对杜林先生关于科学、特别是关于社会主义的所谓新理论的驳斥。这些论文已经集印成书并且在德国社会党人中获得了巨大的成功。在这本小册子中我们摘录了这本书的理论部分中最重要的部分；这一部分可以说是科学社会主义的入门。","language":"中文","translation":false},{"id":"socialism-5-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"卡·马克思写于1880年5月4—5日左右","language":"中文","translation":false},{"id":"socialism-5-13","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"载于弗·恩格斯的小册子“社会主义从空想到科学的发展”（1880年巴黎版）","language":"中文","translation":false},{"id":"socialism-5-14","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"俄文是按手稿译的，并根据1880年版本校对过","language":"中文","translation":false},{"id":"socialism-5-15","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"[155] 弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言是马克思在1880年5月4—5日左右写的。在小册子中导言是由恩格斯这一著作的法文本译者拉法格署名的。在新近发现的手稿中发现有马克思给拉法格的附言，其中说，导言是在他和恩格斯商量以后写的，请拉法格“在词句上加以修饰，但是不要修改内容”。","language":"中文","translation":false},{"id":"socialism-5-16","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"在“马克思恩格斯全集”第一版中导言是作为附录刊印的。——第259页。","language":"中文","translation":false},{"id":"socialism-5-17","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"[156] “社会主义评论”（《La Revue socialiste》）是法国小资产阶级社会主义者、后来成为可能派的倍·马隆创办的月刊。先是共和社会主义的刊物，后来是激进派和合作派的刊物；1880年在里昂和巴黎两地出版，从1885年至1914年在巴黎出版。在八十年代马克思和恩格斯曾为该杂志撰稿。——第259页。","language":"中文","translation":false},{"id":"socialism-5-18","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"[157] 弗·恩格斯“反杜林论。欧根·杜林先生在科学中实行的变革”（见“马克思恩格斯全集”俄文第2版第20卷）。——第259页。","language":"中文","translation":false},{"id":"socialism-5-19","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"[158] “北极星报”（《The Northern Star》）是英国的一种周报，宪章派的机关报；1837年创刊；1852年停刊；最初在里子出版，从1844年11月起在伦敦出版。该报的创办人和主编是菲·奥康瑙尔，在四十年代乔·哈尼也做过该报的主编。从1843年至1850年该报登载过恩格斯的一些论文和短评。","language":"中文","translation":false},{"id":"socialism-5-20","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":20,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"“新道德世界和理性的报纸”（《The New Moral World：and Gazette of the Rational Society》）是空想社会主义者的周报，1834年由罗·欧文创办，1846年停刊，最初在里子出版，从1841年10月起在伦敦出版；1843年11月至1845年5月恩格斯曾为该报撰稿。——第260页。","language":"中文","translation":false},{"id":"socialism-5-21","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"弗·恩格斯的小册子“社会主义从空想到科学的发展”法文版导言","page":5,"paragraph":21,"url":"https://www.marxists.org/chinese/engels/1880/04.htm","text":"[159] 这一时期的事件详见恩格斯的著作“德国维护帝国宪法的运动”（见“马克思恩格斯全集”中文版第7卷第127—235页）。——第260页。","language":"中文","translation":false},{"id":"socialism-6-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-6-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"“社会主义从空想到科学的发展”德文本初版序言","language":"中文","translation":false},{"id":"socialism-6-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"这本小册子来自1878年在莱比锡出版的我的著作“欧根·杜林先生在科学中实行的变革”一书中的三章。我为我的朋友保尔·拉法格把这三章汇集在一起交给他译成法文，并增加了若干比较详细的说明。经我校阅过的法译文最初发表在“社会主义评论”上，后来于1880年在巴黎印成单行本出版，书名为“空想社会主义和科学社会主义”[206]。根据法译文翻译的波兰文本于1882年在日内瓦“黎明”印刷所出版，书名为“空想的和科学的社会主义”[207]。","language":"中文","translation":false},{"id":"socialism-6-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"拉法格的译本在说法语的国家，特别是在法国，获得了意外的成功，这给我提出了一个问题：这三章如果按德文印成单行本出版，是否同样有好处呢。这时，苏黎世的“社会民主党人报”[208]编辑部告诉我，在德国社会民主党内普遍感到迫切需要出版新的宣传小册子，问我是否愿意把这三章用于这一目的。我当然同意这样做，并把我的著作交给他们处理。","language":"中文","translation":false},{"id":"socialism-6-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"可是，这一著作原来根本不是为了直接在群众中进行宣传而写的。这样一种首先是纯粹科学的著作怎样才能适用于直接的宣传呢？在形式和内容上需要作些什么修改呢？","language":"中文","translation":false},{"id":"socialism-6-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"说到形式，只有常常使用外国字这一点可以引起怀疑。但是拉萨尔已经根本不在他的演说和宣传小册子中避免使用外国字，而且据我所知，大家并没有因此诉苦。从那时以来，我们的工人已经更多地和更经常地阅读报纸，因此也更多地熟悉外国字。我只限于删去一切不必要的外国字。对于必要的外国字，我没有附上所谓解释性的译文。这些必要的外国字大部分是科学技术上通用的术语，它们如果可以翻译，那就不是必要的了。这就是说，翻译只能歪曲这些术语的意义；它不能说明，反而会造成混乱。在这里，口头的解释会有更大的帮助。","language":"中文","translation":false},{"id":"socialism-6-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"内容却刚刚相反，我可以肯定地说：对德国工人来说困难是不多的。总的说来，只有第三部分是困难的，但是对于工人，较之“有教养的”资产者，困难要少得多，因为这一部分正是概括了工人的一般生活条件。至于说到我在这里加上的许多说明，那末我实际上与其说是考虑到工人，不如说是考虑到“有教养的”读者，如议员先生冯·艾内恩、枢密顾问先生亨利希·冯·济贝耳以及特赖奇克之流的人物，他们为不可抑制的欲望所驱使，总是一再地表明他们的惊人的无知和由此产生的对社会主义的巨大的误解。如果唐·吉诃德挺着长矛同风车搏斗，那末这是合乎他的身分和所扮演的角色的；但是我们不能容许桑科·判扎做这类事情。","language":"中文","translation":false},{"id":"socialism-6-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"这样的读者也会觉得奇怪：为什么在社会主义发展的简述中提到康德—拉普拉斯的天体演化学说，提到现代自然科学和达尔文，提到德国的古典哲学和黑格尔。但是，科学社会主义本质上是德国的产物，而且也只能产生于古典哲学还生气勃勃地保存着自觉的辩证法传统的国家，即产生于德国［注：“于德国”是笔误，应当说“于德国人中间”，因为科学社会主义的产生，一方面必需有德国的辩证法，但是同时也必需有英国和法国的发展了的经济关系和政治关系。德国的落后的经济和政治条件——四十年代初比现在还落后得多——最多只能产生社会主义的讽刺画（参看“共产党宣言”第三章（丙）“德国的或‘真正的’社会主义”[209]）。只有在英国和法国所造成的经济和政治的情况受到德国辩证法的批判以后，才能产生真正的结果。因而，从这方面看来，科学社会主义并不是专属德国的产物，而同样是国际的产物。——恩格斯在1883年德文版上加的注］。唯物主义历史观及其在现代的无产阶级和资产阶级之间的阶级斗争上的特别应用，只有借助于辩证法才有可能。如果说，德国资产阶级的教师们已经把关于德国大哲学家和他们所创立的辩证法的记忆淹没在一种无聊的折衷主义的泥沼里，而且已经做到这样一种程度，以致我们不得不引用现代自然科学来证明辩证法是存在于现实之中的，那末，我们德国社会主义者却以我们不仅继承了圣西门、傅立叶和欧文，而且继承了康德、费希特和黑格尔而感到骄傲。","language":"中文","translation":false},{"id":"socialism-6-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"1882年9月21日于伦敦","language":"中文","translation":false},{"id":"socialism-6-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"载于弗·恩格斯“社会主义从空想到科学的发展”一书（1882年哥丁根—苏黎世版）","language":"中文","translation":false},{"id":"socialism-6-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"中文根据“马克思恩格斯全集”1962年柏林狄茨出版社德文版第19卷译出","language":"中文","translation":false},{"id":"socialism-6-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"[206] F．Engels．《Socialisme utopique et socialisme scientifique》．Paris，1880．——第345页。","language":"中文","translation":false},{"id":"socialism-6-13","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"[207] Fr．Engels．《Socyjalizm utopijny a naukowy》．Genève，1882．——第345页。","language":"中文","translation":false},{"id":"socialism-6-14","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"[208] “社会民主党人报”（《Der Sozialdemokrat》）是德国社会民主党的中央机关报；反社会党人非常法生效时期出版的一种周报，从1879年9月至1888年9月在苏黎世出版，从1888年10月至1890年9月27日在伦敦出版。马克思和为该报撰稿的恩格斯都反对过该报的错误，帮助该报在自己的篇幅中贯彻党的无产阶级的路线。——第345页。","language":"中文","translation":false},{"id":"socialism-6-15","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文本初版序言","page":6,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/1880/05.htm","text":"[209] 见“马克思恩格斯全集”中文版第4卷第495—498页。——第347页。","language":"中文","translation":false},{"id":"socialism-7-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-7-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"“社会主义从空想到科学的发展”德文第四版序言[210]","language":"中文","translation":false},{"id":"socialism-7-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"我曾经预料，这一著作对我们的德国工人来说困难是不多的，现在这个预料已被证实。至少从1883年3月第一版问世以来已经印行了三版，总数达一万册，而且这是在已经升天的反社会党人法的统治下的事情，——同时，这也是一个新的例证，证明警察的禁令在像现代无产阶级的运动这样的运动面前是多么软弱无力。","language":"中文","translation":false},{"id":"socialism-7-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"从第一版印行以来，又出版了几种外文译本。帕斯夸勒·马尔提涅蒂翻译的意大利文本：“空想社会主义和科学社会主义”1883年贝内万托版；俄文本：“科学社会主义的发展”［注：在原文中这一书名是用拉丁字母拼写的俄文。——编者注］1884年日内瓦版；丹麦文本：“社会主义从空想到科学的发展”，载于“社会主义丛书”第一卷，1885年哥本哈根版，西班牙文本：“空想社会主义和科学社会主义”1886年马德里版；以及荷兰文本：“社会主义从空想到科学的发展”1886年海牙版。[211]","language":"中文","translation":false},{"id":"socialism-7-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"本版作了一些小的修改；比较重要的补充只有两处：在第一章中关于圣西门的补充，同傅立叶和欧文相比，关于圣西门过去谈得的确太少；其次是在第三章接近末尾的地方关于当时已经变得很重要的新的生产形式“托拉斯”的补充[212]。","language":"中文","translation":false},{"id":"socialism-7-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"1891年5月12日于伦敦","language":"中文","translation":false},{"id":"socialism-7-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"载于1891年在柏林出版的弗·恩格斯“社会主义从空想到科学的发展”一书","language":"中文","translation":false},{"id":"socialism-7-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"俄文译自“社会主义从空想到科学的发展”","language":"中文","translation":false},{"id":"socialism-7-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"[210]这篇序言是恩格斯为他的著作“社会主义从空想到科学的发展”（见“马克思恩格斯全集”中文版第19卷第201—247页）德文第四版写的，该版于1891年在柏林由“前进报”社出版。这部著作在1880年首先用法文发表在“社会主义评论”（《Revue socialiste》）杂志上，德文第一版是由“社会民主党人报”社于1883年3月在霍廷根—苏黎世出版的（扉页上标的日期是：1882年）。恩格斯在德文第一版序言中表示相信这部著作的内容对德国工人读者来说困难是不多的（见“马克思恩格斯全集”中文版第19卷第346页）。恩格斯这部著作的德文第二版和第三版仍由该报社于1883年出版。第四版是在恩格斯生前以德文印刷的最后一版。所有这四个德文版本，都以附录形式刊载了恩格斯的“马尔克”一文（见“马克思恩格斯全集”中文版第19卷第351—369页）。——第244页。","language":"中文","translation":false},{"id":"socialism-7-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"[211]所列举的各种版本为：《Ⅰl socialismo utopico e il socialismo scientifico》，Benevento，1883；《Развитие научного социализма》，Женева，1884；《Socialismens Udvikling fra Utopi til Videnskab》，Ｋфbenhavm，1885；《Socialismo utópico y socialismo científico》，Madrid，1886；《De ontwikkeling van het socialisme van utopie tot wetenschap》，Gravenhage，1886。——第244页。","language":"中文","translation":false},{"id":"socialism-7-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”德文第四版序言","page":7,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/06.htm","text":"[212]恩格斯提到的对“社会主义从空想到科学的发展”最初文本（它以“反杜林论”中相应各章的文字为基础）的补充，另行刊载在“马克思恩格斯全集”俄文第2版第20卷“‘反杜林论’的资料”部分。关于圣西门的补充见第20卷第669—670页；关于托拉斯的补充见第20卷第672—673页。——第245页。","language":"中文","translation":false},{"id":"socialism-8-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-8-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"“社会主义从空想到科学的发展”英文版导言[286]","language":"中文","translation":false},{"id":"socialism-8-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"这本小册子本来是一个更大的整体的一部分。大约在1875年，柏林大学副教授欧·杜林博士突然大叫大嚷地宣布他改信社会主义，他不仅向德国公众提出了一套详尽的社会主义理论，而且还提出了一个改造社会的完备的实践计划。自然，他与他的前辈发生了冲突；首先，他将满腹怒气发泄在马克思身上。","language":"中文","translation":false},{"id":"socialism-8-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"这件事发生在这样一种时候：德国社会党的两派——爱森纳赫派和拉萨尔派——刚刚实现了合并[287]，因而不仅大大地加强了力量，而且更重要的是已经有能力运用这全部力量去反对共同的敌人。德国社会党正在迅速地成为一种力量。但是，要使它成为一种力量，第一个条件是不让这个刚刚赢得的统一受到危害。而杜林博士却公开地着手在自己周围建立一个宗派，一个未来的单独的政党的核心。因此，不管我们是否愿意，我们必须应战，把斗争进行到底。","language":"中文","translation":false},{"id":"socialism-8-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"可是，这虽然不是一件太困难的事情，显然也是够麻烦的。大家知道，我们德国人具有一种极其笨拙的Gründlichkeit，即彻底的深思精神或深思的彻底精神，不管你叫它什么都行。我们中的任何一个人在阐述他认为是新学说的那种东西的时候，便首先一定要设法把它弄成一个包罗万象的体系。他一定要证明，逻辑的主要原则和宇宙的基本规律之所以存在，从来都只是为了最后导致这个新发现的卓绝的理论。在这方面，杜林博士已经完全达到这种民族标准了。整整的全套“哲学体系”，精神的、道德的、自然的和历史的一应俱全；全套“政治经济学的和社会主义的体系”；最后还有“政治经济学批判史”[288]——三部八开本的巨著，在外观上和内容上都很有份量的、被动员起来向一切前辈哲学家和经济学家进攻、特别是向马克思进攻的三路论证大军——事实上，这是企图“在科学中”实行一次完全的“变革”——这些就是我所要对付的。我不得不涉及所有的和各种各样的问题：从时间和空间的概念到复本位制[289]，从物质和运动的永恒性到道德观念的易逝性，从达尔文的自然选择到未来社会中的青年教育。无论如何，我的对手的包罗万象的体系，使我有机会在同他的争论中阐明（而且是用比以前更连贯的形式）马克思和我对这许多形形色色的问题的见解。这就是使我把这个从其他方面来说是吃力不讨好的任务担负起来的主要原因。","language":"中文","translation":false},{"id":"socialism-8-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"我的答复，最初是作为一系列论文发表在社会党的中央机关报莱比锡的“前进报”上，后来汇集成书，题为《Herrn Eugen Dühring's Umwälzung der Wissenschaft》（“欧根·杜林先生在科学中实行的变革”）[290]，这本书的第二版于1886年在苏黎世出版。","language":"中文","translation":false},{"id":"socialism-8-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"根据我的朋友，现在法国众议院中利尔市的议员保尔·拉法格的请求，我把这本书中的三章编成了小册子，由他译成法文并于1880年出版，书名为“空想社会主义和科学社会主义”[291]。波兰文版和西班牙文版[292]就是根据这个法文本译出的。1883年，我们的德国朋友用原文出版了这本小册子。此后，根据这个德文本又出版了意大利文、俄文、丹麦文、荷兰文和罗马尼亚文的译本[293]。这样，连同现在这个英文版在内，这本小册子已经用十种文字流传开了。据我所知，任何其他社会主义著作，甚至我们的1848年出版的“共产主义宣言”和马克思的“资本论”，也没有这么多的译本。在德国，这本小册子已经印了四版，共约两万册。","language":"中文","translation":false},{"id":"socialism-8-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"附录“马尔克”是为了在德国社会党内传播若干关于德国土地所有制的历史和发展的基本知识而写的。当这个党团结城市工人的工作已经有完成的希望而农业工人和农民的工作需要着手进行的时候，这就显得尤其必要了。这个附录之所以收入英译本中，是因为考虑到一切日耳曼部落所共有的原始的土地占有形式及其衰亡的历史，在英国比在德国更不为人所知。这篇附录仍旧保持了原状，我没有涉及马克西姆·柯瓦列夫斯基最近提出的假说，按照这个假说，在马尔克的成员分割耕地和草地之前，曾经有包括几代人的庞大的宗法制家庭公社（现在还存在的南方斯拉夫人的扎德鲁加可以作为例证）共同耕种这些土地；后来，当公社范围扩大，太不便于共同经营的时候，便出现了分割公社土地的现象。[294]柯瓦列夫斯基也许是完全对的，不过问题还sub judice〔在讨论中〕。","language":"中文","translation":false},{"id":"socialism-8-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"本书中所用的经济学名词，凡是新的，都同马克思的“资本论”英文版[295]中所用的一致。我们所说的“商品生产”，是指经济发展中的这样一个阶段，在这个阶段上，物品生产出来不仅是为了供生产者使用，而且也是为了交换的目的；就是说，是作为商品，而不是作为使用价值来生产的。这个阶段从开始为交换而生产的时候起，一直延续到现在；这个阶段只是在资本主义生产下，即在占有生产资料的资本家出资雇用那些除自己的劳动力以外没有任何生产资料的工作者并把产品的卖价超出其支出的赢余部分纳入腰包的条件下，才获得充分的发展。我们把中世纪以来的工业生产的历史分为三个时期：（1）手工业，小手工业师傅带着少数帮工和学徒，每个工作者都生产整件物品；（2）工场手工业，较大数量的工人聚集在一个大企业中，按照分工的原则生产整件物品，每个工人只完成一部分工序，所以产品只有依次经过所有工人的手以后才能制成；（3）现代工业，产品是用动力发动的机器来生产的，工人的工作只限于监督和调整机器的动作［注：在发表于“新时代”杂志上的德译文中，这篇导言从开头到“调整机器的动作”为止的几段被删去。——编者注］。","language":"中文","translation":false},{"id":"socialism-8-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"我很清楚，本书的内容将遭到相当大的一部分英国公众的反对。但是，如果我们大陆上的人稍微顾到英国“体面人物”［注：德译文中，在“体面人物”的后面补充有：“即英国庸人”。——编者注］的偏见，那末事情将会比现在更坏。本书所捍卫的是我们称为“历史唯物主义”的东西，而唯物主义这个名词是使大多数英国读者感到刺耳的。“不可知论”还可以容忍，但是唯物主义就完全不能容许了。","language":"中文","translation":false},{"id":"socialism-8-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"然而，从十七世纪以来，全部现代唯物主义的发祥地正是英国。","language":"中文","translation":false},{"id":"socialism-8-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"“唯物主义是大不列颠的天生的产儿，英国经院哲学家邓斯·司各脱就曾经问过自己：‘物质是否不能思维？’","language":"中文","translation":false},{"id":"socialism-8-13","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"为了使这种奇迹能够实现，他求助于上帝的万能，即迫使神学来宣扬唯物主义。此外，他还是一个唯名论者[296]。唯名论，唯物主义的最初形式，主要是存在于英国经院哲学家中间。","language":"中文","translation":false},{"id":"socialism-8-14","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"英国唯物主义的真正始祖是培根。在他看来，自然哲学是唯一真正的哲学；而以感性经验为基础的物理学则是自然哲学的最主要的部分。阿那克萨哥拉和他的同素体[297]，德谟克利特和他的原子，都常常被他当做权威来引证。在他看来，感觉是可靠的，是全部知识的泉源。全部科学都是以经验为基础的，是在于用理性的研究方法去整理感官所提供的材料。归纳、分析、比较、观察和实验，是这种理性方法的主要形式。在物质的固有的特性中，运动是第一个特性而且是最重要的特性，这里所说的运动不仅是机械的和数学的运动，而且主要是物质的动力、生命力、张力，或者用雅科布·伯麦的术语来说，物质的《Qual》［注：《Qual》是哲学上的双关语。《Qual》按字面的意思是苦闷，是一种促使采取某种行动的痛苦；同时，神秘主义者伯麦把拉丁语qualitas［质］的某些意义加进这个德国字；他的《Qual》和外来的痛苦相反，是能动的本原，这种本原从受《Qual》支配的事物、关系或个人的自发发展中产生出来，而反过来又推进这种发展。［恩格斯在英文版上加的注，在德文版上未加。——编者注］］〔“痛苦”〕［注：在德译文中，在〔“痛苦”〕一词后面，又从“神圣家族”中援引了英文版中删去的一句话：“物质的原始形式是物质内部所固有的、活生生的、本质的力量，这些力量使物质获得个性，并造成各种特殊的差异。”——编者注］。","language":"中文","translation":false},{"id":"socialism-8-15","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"唯物主义在它的第一个创始人培根那里，本身还包含着多方面发展的萌芽。一方面，被赏心悦目的、诗意的魅力环绕着的物质似乎以迷人的微笑吸引着人的整个身心。另一方面，以格言形式表述出来的学说却充满了神学的不彻底性。","language":"中文","translation":false},{"id":"socialism-8-16","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"唯物主义在以后的发展中变得片面了。霍布斯把培根的唯物主义系统化了。以感觉为基础的知识，失去了它的诗的绚丽色彩，它变成了数学家的抽象的经验［注：在德译文中又援引了英文版中删去的一句话：“物理运动成为机械运动或数学运动的牺牲品。”——编者注］；几何学被宣布为科学的女王。唯物主义开始憎恨起人类来了。既然唯物主义要克服自己的对手，即憎恨人类的、不要肉体的唯灵论，并且是在后者自己的范围内予以克服，它就只好禁锢自己的肉体而变成禁欲主义者。这样，它就从感性的东西变成理性的东西；可是，它因此也就发展着理智所特有的不顾后果的全部彻底性。","language":"中文","translation":false},{"id":"socialism-8-17","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"霍布斯，作为培根的继承者，这样推论道：如果人类的全部知识都是由感官提供的，那末我们的概念和观念就不过是现实世界的丧失了感性形式的幻影。哲学只能给这些幻影冠以名称。一个名称可以用于许多幻影。甚至还可以有名称的名称。但是，如果一方面认为一切观念都起源于感性世界，另一方面又说一个词的意义不止是一个词，除了通过我们的感官而为我们所知道的存在物，即全都是个别的存在物之外，还有某种普遍的，非个别的存在物，那就矛盾了。无形体的实体和无形体的形体一样，都是荒唐的。形体、存在、实体只是同一种实在的不同名称。不可能把思维同思维着的物质分开。物质是世界上所发生的一切变化的基础。假如无限的这个词不表示我们的精神能够完成无限的相加过程，那末这个词就毫无意义。既然只有物质的东西对我们来说是可以觉察到的，那末关于上帝的存在，我们就丝毫不能有所知了。只有我自己的存在才是确实可信的。人的一切情欲都是既有开始也有结束的机械运动。欲求的对象就是我们称为善的东西。人和自然都受同样的规律支配。强力和自由是同一的。","language":"中文","translation":false},{"id":"socialism-8-18","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"霍布斯把培根的学说系统化了，但是他没有论证培根关于人类的全部知识起源于感性世界的基本原则。洛克在他的‘人类悟性论’[298]中提供了这种论证。","language":"中文","translation":false},{"id":"socialism-8-19","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"霍布斯打破了培根唯物主义中的有神论的偏见；柯林斯、多德威尔、考尔德、哈特莱、普利斯特列同样地打破了还包围着洛克的感觉论的最后的神学藩篱。无论如何，对实际的唯物主义者来说，自然神论[299]不过是摆脱宗教的一种简便易行的方法罢了。”［注：马克思和恩格斯“神圣家族”1845年美因河畔法兰克福版第201—204页。[300]］","language":"中文","translation":false},{"id":"socialism-8-20","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":20,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"关于现代唯物主义在英国的起源，卡尔·马克思就是这样写的。如果英国人现在对马克思给予他们祖先的赞扬并不感到十分高兴，那真是遗憾得很。可是不容否认，培根、霍布斯和洛克是法国唯物主义者这个光辉的学派的前辈。尽管十八世纪时法国人在陆上和海上的一切战争中都被德国人和英国人所战胜，法国唯物主义者还是使十八世纪成为主要是法国人的世纪，这甚至发生在卓绝的法国革命之前；而这次革命的成果，我们在英国和德国的局外人都还在试图移植于我们自己的环境。","language":"中文","translation":false},{"id":"socialism-8-21","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":21,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"无可否认，大约在本世纪中叶，每个移居英国的有教养的外国人都感到惊奇的，是那种他在当时必然认为是英国体面的中等阶级的宗教执迷和愚蠢的现象。在那时，我们都是唯物主义者，或者至少是很激进的自由思想者，我们不能理解，为什么英国几乎所有有教养的人都相信各种各样不可思议的奇迹，甚至像巴克兰德和曼特耳那样的地质学家也歪曲自己科学中的事实，以避免同创世纪的神话有太多的冲突；而为了要找到在宗教问题上敢于运用自己的智力的人，就必须到没有受过教育的人中去，到当时所谓的“肮脏人群”中去，到工人中去，特别是到欧文派的社会主义者中去。","language":"中文","translation":false},{"id":"socialism-8-22","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":22,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"但是从那时以来，英国已经“开化”了。1851年的博览会[301]给英国岛国的闭塞性敲起了丧钟。英国在饮食、风俗和观念方面已经逐渐国际化了；它在这方面取得了很大的成就，使我不禁希望英国的某些风俗和习惯在大陆上也像大陆上的其他习惯在英国那样得到传播。总之，随着橄榄油（1851年以前只有贵族才知道）的传入和传播，大陆在宗教问题上的怀疑论也致命地传播开了，而且事情达到这样的地步：不可知论虽然还没有像英国国教教会那样被当做“头等货色”，但是在体面这一点上，却几乎和浸礼会是同等的，而且肯定要比“救世军”[302]的地位高。我不禁想道：在这种情况下，许多对不信教思想的进展感到十分痛心并加以诅咒的人，如果知道这些“新奇的思想”并不是舶来品，不像其他许多日用品那样带有made in Germany〔德国造〕的商标，而肯定无疑是老牌的英国质，如果知道他们的不列颠祖先在两百年前所走的比今天后代子孙所敢于走的要远得多，那他们将会感到安慰吧。","language":"中文","translation":false},{"id":"socialism-8-23","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":23,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"真的，不可知论如果不是（用郎卡郡的一个富于表现力的字眼来说）［注：在德译文中“（用郎卡郡的一个富于表现力的字眼来说）”一语被删掉。——编者注］“羞羞答答的”唯物主义，又是什么呢？不可知论者的自然观，完全是唯物主义的。整个自然界是受规律支配的，它绝对排除任何外来的干涉。可是，不可知论者补充道，我们无法肯定或否定已知世界之外的某个最高存在物的存在。这种说法也许在拿破仑那个时代有点价值，那时拉普拉斯对拿破仑的问题——为什么在这位伟大的天文学家的“天体力学”[303]一书中对造物主连提也没有提到，——曾经骄傲地这样回答：《Je n’avais pas besoin de cette hypothèse》〔“我不需要这个假说”〕。可是在今天，在我们关于宇宙发展的概念中绝对没有造物主或主宰者立足的余地；如果人们说，有一个被排斥于整个现存世界之外的最高存在物，那末这样说本身就有矛盾，而且在我看来，这对信教者的情感也是一种不应有的侮辱。","language":"中文","translation":false},{"id":"socialism-8-24","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":24,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"我们的不可知论者也承认，我们的全部知识是以我们的感官所给予我们的报告为基础的。可是，他补充道：我们怎么知道我们的感官所给予我们的，是我们通过感官去感知的事物的正确反映呢？接着他又告诉我们：当他讲到事物或事物的特性时，他实际上所指的并不是这些事物和特性（关于这些，他是一点也不能确实知道的），而只是这些事物和特性对他的感官所产生的印象。看起来，这种论点确实是很难只凭论证去驳倒的。但是在有论证之前，已经先有了行动。《In Anfang war die Tat》〔“起初是行动”〕。［注：歌德“浮士德”第一部第三场（“浮士德的书斋”）。——编者注］在人类的才智发明这个困难以前很久，人类的行动已经解决了这个困难。对布丁的检验在于吃。当我们按照我们所感知的事物特性来利用这些事物的时候，我们就让我们的感性知觉的正确性受到确实可靠的检验。如果这些知觉是错误的，那末我们关于这种事物可能有什么用途的判断，必然也是错误的，而我们的尝试就必然要失败。可是，如果我们达到了我们的目的，如果我们发现事物符合我们关于它的观念，并且产生我们所预期的目的，那末这就肯定地证明，在这一范围内我们关于事物及其特性的知觉是同存在于我们之外的现实相符合的。当我们发现自己遭到了失败的时候，我们一般地总是不要很久就能找出使我们失败的原因；我们总是发现，我们的行动所依据的知觉，不是不完全的和肤浅的，就是不正确地和其他知觉的结果结合在一起——我们把这叫做有缺陷的推理［注：在德译文中“我们把这叫做有缺陷的推理”一语被删掉。——编者注］。只要我们注意正确地训练和运用我们的感官，并把我们的行动限制在正确地形成和正确地运用的知觉所限定的范围之内，我们就会发现，我们的行动的结果证明我们的知觉是和知觉到的事物的客观本性相符合的。到目前为止，没有一个例子迫使我们得出这样的结论：我们的经过科学检验的感性知觉，会在我们的头脑中造成一种在本性上同现实不符合的关于外部世界的观念；或者在外部世界和我们关于外部世界的感性知觉之间，存在着天生的不一致。","language":"中文","translation":false},{"id":"socialism-8-25","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":25,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"但是，这时新康德主义的不可知论者出来说道：我们可能正确地知觉到事物的特性，但是我们不能通过任何感觉的或思维的过程来掌握自在之物。这个“自在之物”是在我们的认识范围之外的。对于这一点，黑格尔很早以前就已回答了：如果你知道了某一事物的一切性质，那末你也就知道了这一事物本身；这时剩下来的只是上述事物存在于我们之外这样一个事实；而当你的感官使你知道了这一事实的时候，你就完全掌握了这一事物，即康德的著名的不可认识的《Ding an sich》〔“自在之物”〕。对此，可以补充的是：在康德所处的时代，我们对自然界事物的知识确实是十分零碎的，所以他很可以猜想在我们关于每一件事物的少许知识背后存在着一种神秘的“自在之物”。但是这些不可理解的事物，已经被科学的巨大进步逐一地理解，分析，甚至重新制造出来了；而我们能够制造的东西，我们当然不能认为是不可认识的。对于本世纪上半叶的化学来说，有机物正是这样的神秘的东西；现在我们学会了不依靠有机过程的帮助，按照有机物的化学成分逐一地把有机物构造出来。近代化学家声称：无论什么物体，只要知道它的化学结构，就可以按它的成分把它构造出来。我们现在还远远地不知道最高有机物即蛋白体的结构；但是没有理由说，我们在几个世纪以后还不能达到这种认识，并以这种认识制造出人造蛋白。如果我们达到了这点，我们同时就制造出了有机生命，因为生命，从它的最低形式直到最高形式，都只是蛋白体的正常的生存方式。","language":"中文","translation":false},{"id":"socialism-8-26","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":26,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"然而，我们的不可知论者在做了这些形式上的思想保留之后，就立刻像十足的唯物主义者那样说话和行动，实际上他也是唯物主义者。他或许会说：就我们所知，物质和运动，或者用现在的说法，能，是既不能被创造也不能被消灭的，但是我们没有证据来证明它们不是在某一个时候被创造出来的。可是，如果你试图在某个特定的场合利用这种承认去反驳他，那末他立刻就会要你闭口。如果说他in abstracto〔抽象地〕承认唯灵论的可能性，那末他in concreto〔具体地〕一点也不愿意知道这种可能性。他会对你说：就我们所知道或所能知道的来说，宇宙的造物主和主宰者是不存在的；对我们来说，物质和能是既不能被创造也不能被消灭的；在我们看来，思维是能的一种形式，是脑的一种职能；我们所知道的一切就是：物质世界是受不变的规律支配的，如此等等。所以，就他是一个讲科学的人来说，就他知道一些事情来说，他是唯物主义者；可是在他的科学以外，在他一无所知的领域中，他就把自己的无知翻译成为希腊文，称之为不可知论。","language":"中文","translation":false},{"id":"socialism-8-27","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":27,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"无论如何，有一点似乎是清楚的：即使我是一个不可知论者，显然我也不能把这本小册子中所概述的历史观称为“历史不可知论”。信教的人将会取笑我，不可知论者将会气愤地质问我是否在嘲弄他们？因此，如果我在英文中也像在其他许多文字中一样，用“历史唯物主义”这个名词来表达一种关于历史过程的观点，这种观点认为一切重要历史事件的终极原因和伟大动力是社会的经济发展、生产方式和交换方式的改变、由此产生的社会之划分为不同的阶级，以及这些阶级彼此之间的斗争，那末，即使英国的体面人物［注：在德译文中在“体面人物”的后面补充有：“用德文来说叫做庸人”。——编者注］也不致于感到太震惊吧。","language":"中文","translation":false},{"id":"socialism-8-28","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":28,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"如果我表明历史唯物主义甚至对英国的体面人物［注：在德译文中不是“英国的体面人物”，而是“英国庸人的体面”。——编者注］也是有利的，那末人们对我或许还会更谅解一些。我提到过这样的事实：约在四五十年前，住在英国的任何一个有教养的外国人都为他当时必然认为是英国体面的中等阶级的宗教执迷和愚蠢的现象而感到惊奇。现在我要证明，那时候的体面的英国中等阶级，并不像有知识的外国人所认为的那样愚蠢。这个阶级的宗教倾向是有其缘由的。","language":"中文","translation":false},{"id":"socialism-8-29","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":29,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"当欧洲脱离中世纪的时候，新兴的城市中等阶级［注：在德译文中，从这里开始，直至以“新的出发点是……的妥协”一句起首的那一段（本卷第350页），恩格斯的用语《middle class》〔“中等阶级”〕、《bourgeoisie》〔“资产阶级”〕，都译为“市民阶级”（《Bürgerthum》；以后，这些用语又被恩格斯译为“资产阶级”（《Bourgeoisie》）。——编者注］是欧洲的革命因素。它在中世纪的封建组织内已经赢得了公认的地位，但是这个地位对它的扩张能力来说，也已经变得太狭小了。中等阶级，即资产阶级的发展，同封建制度的继续存在已经不相容了，因此，封建制度必定要覆灭。","language":"中文","translation":false},{"id":"socialism-8-30","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":30,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"但是封建制度的巨大的国际中心是罗马天主教会。它把整个封建的西欧（尽管有各种内部战争）联合为一个大的政治体系，同闹分裂的希腊正教徒和伊斯兰教的国家相对抗。它给封建制度绕上一圈神圣的灵光。它按照封建的方式建立了它自己的教阶制，最后，它自己还是最有势力的封建领主，拥有天主教世界的地产的整整三分之一。要在每个国家内从各个方面成功地进攻世俗的封建制度，就必须先摧毁它的这个神圣的中心组织。","language":"中文","translation":false},{"id":"socialism-8-31","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":31,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"此外，随着中等阶级的兴起，科学也大大地复兴了；天文学、机械学、物理学、解剖学和生理学的研究又重新进行起来。资产阶级为了发展它的工业生产，需要有探察自然物体的物理特性和自然力的活动方式的科学。而在此以前，科学只是教会的恭顺的婢女，它不得超越宗教信仰所规定的界限，因此根本不是科学。现在科学起来反叛教会了；资产阶级没有科学是不行的，所以也不得不参加这一反叛。","language":"中文","translation":false},{"id":"socialism-8-32","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":32,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"上面所说的，虽然只就新兴的中等阶级必然要同现存的教会发生冲突这方面提到了两点，但已经足以证明：第一，在反对罗马教会权利的斗争中，最有直接利害关系的阶级是资产阶级；第二，当时反对封建制度的每一种斗争，都必然要披上宗教的外衣，必然首先把矛头指向教会。可是，如果说大学和城市商人领先发出了呼声，那末一定会在而且确实已经在农村人民群众即农民中得到强有力的响应，农民为了自己的生存不得不到处同他们的精神的和尘世的封建主进行斗争。","language":"中文","translation":false},{"id":"socialism-8-33","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":33,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"资产阶级反对封建制度的长期［注：在德译文中不是“长期”，而是“伟大”。——编者注］斗争，在三次大决战中，达到了顶点。","language":"中文","translation":false},{"id":"socialism-8-34","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":34,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"第一次是德国的所谓宗教改革。路德发出的反对教会的战斗号召，唤起了两次政治性的起义：首先是弗兰茨·冯·济金根领导下的下层贵族的起义（1523），然后是1525年的伟大的农民战争。[304]两次起义都失败了，主要是由于最有利害关系的集团即城市市民的不坚决，——至于不坚决的原因，我们在这里不能阐述了。从那时起，斗争就蜕化为地方诸侯和中央政权［注：在德译文中不是“中央政权”，而是“皇室中央政权”。——编者注］之间的战斗，结果，德国有两百年不见于政治上积极的欧洲国家之列。路德的宗教改革确实建立了新的信条，即适合君主专制的宗教。德国东北部的农民一改信路德教，就从自由人变成了农奴。","language":"中文","translation":false},{"id":"socialism-8-35","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":35,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"但是，在路德遭到失败的地方，加尔文却获得了胜利。加尔文的信条适合当时资产阶级中最勇敢的人的要求。他的先定学说，就是下面这一事实在宗教上的反映：在商业竞争的世界中，成功或失败不取决于个人的活动或才智，而取决于不受他支配的情况。起决定作用的不是一个人的意志或行动，而是未知的至高的经济力量的摆布；在经济革命时期，当一切旧的商业路线和商业中心被新的所代替的时候，当印度和美洲已经向世界开放的时候，当最神圣的经济信条——金银的价值——也已经开始动摇和崩溃的时候，这种情形就特别真实了。加尔文的教会的组织是完全民主的和共和的；而在上帝的王国已经共和化了的地方，人间的王国还能够仍然从属于君王、主教和领主吗？当德国的路德教变成诸侯［注：在德译文中不是“诸侯”，而是“德国小诸侯”。——编者注］手中的驯服工具的时候，加尔文教在荷兰创立了共和国，并且在英国，特别是在苏格兰，创立了有力的共和主义的政党。","language":"中文","translation":false},{"id":"socialism-8-36","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":36,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"资产阶级的第二次大起义在加尔文教中给自己找到了现成的理论。这次起义是在英国发生的。发动者是城市中等阶级，而完成者是农村地区的自耕农［注：在德译文中不是“自耕农”，而是“中农（yeomanry）”。——编者注］。很有意思的是：在所有三次资产阶级大起义［注：在德译文中不是“起义”，而是“革命”。——编者注］中，都是农民提供了战斗部队，而在胜利后必然由于这一胜利的经济结果而破产的阶级又恰恰是农民。克伦威尔之后一百年，英国的自耕农差不多完全绝迹了。无论如何，如果没有这种自耕农和城市平民，单单资产阶级决不会把斗争进行到底，也决不会把查理一世送上断头台。［注：在德译文中，这句话是这样的：“然而，正是由于这种yeomanry和城市平民的参与，斗争才进行到底，而查理一世才被推上断头台”。——译者注］为了取得即便是那些在当时已经成熟而只待采集的资产阶级的胜利果实，也必须使革命远远地超出这一目的，正如1793年在法国和1848年在德国那样。这看来事实上就是资产阶级社会发展的规律之一。","language":"中文","translation":false},{"id":"socialism-8-37","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":37,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"在这种过分的革命活动之后，必然接着到来一个不可避免的反动，这个反动又超出了它能继续下去的那个限度［注：在德译文中不是“它能继续下去的那个限度”，而是“自己的目的”。——编者注］。经过多次动荡以后，新的重心终于确立了，并且成了新的出发点。英国历史上被体面人物［注：在德译文中不是“体面人物”，而是“庸人”。——编者注］称为“大叛乱”的辉煌时期，以及随之而来的斗争，是以自由党历史家称为“光荣革命”[305]的一件比较不足道的事件而告结束的。","language":"中文","translation":false},{"id":"socialism-8-38","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":38,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"新的出发点是新兴的中等阶级［注：在德译文中这里以及后面几个地方，《middle class》〔“中等阶级”〕这个用语，也同《bourgeoisie》一样，译为“资产阶级”。——编者注］和以前的封建地主之间的妥协。后者虽然被称为贵族（就像现在这样），其实早已向法国的路易-菲力浦在很久之后才变成的“王国第一流资产者”的方向发展了。对英国幸运的是，旧的封建诸侯已经在蔷薇战争[306]中自相残杀殆尽。他们的继承人，虽然大部分是这些旧家族的后裔，但是离开嫡系已经很远，甚至形成了一个崭新的集团，他们的习惯和倾向，与其说是封建的，倒不如说是资产阶级的。他们完全懂得金钱的价值，而且立即着手增加地租，办法是把成百的小佃户赶走，而代之以绵羊。亨利八世慷慨地胡乱处理教会土地，造成了大批新的资产阶级地主；在整个十七世纪继续不断地发生的大量没收大采邑分赠暴发户或半暴发户的情形，也造成了同样的结果。因此，从亨利七世以来，英国的“贵族”不但不反对工业生产的发展，反而力图间接地从中取得利益；而且经常有这样一部分大地主，由于经济的或政治的原因，愿意同金融资产阶级和工业资产阶级的首脑人物合作。这样，1689年的妥协很容易就达成了。“俸禄和官职”［注：在德译文中不是“俸禄和官职”，而是：“官职、闲差、厚禄”。——编者注］这些政治上的战利品留给了大地主家庭，其条件是充分照顾金融的、工业的和商业的中等阶级的经济利益。而这些经济利益，在当时已经强大到足以决定国家的一般政策了。在细节问题上或许发生过争执，但是总的说来，贵族寡头非常清楚，他们本身的经济繁荣同工商业中等阶级的经济繁荣是有不可分割的联系的。","language":"中文","translation":false},{"id":"socialism-8-39","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":39,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"从这个时候起，资产阶级就成了英国统治阶级的微末的但却是得到承认的一部分了。在压迫国内广大劳动群众方面，它同统治阶级的其他部分是有共同利益的。商人或工厂主本人，对自己的伙计、工人和仆役来说，是站在主人的地位，或者像直到不久以前还说的那样，站在“天然首长”的地位。他的利益是要从他们身上尽可能取得尽量多和尽量好的劳动；为此目的，就必须把他们训练得驯服顺从。他自己是信教的，他的宗教曾经是他用来战胜国王和贵族的旗帜；不久他就发现这同一个宗教可以用来操纵他的天然下属的灵魂，使他们服从那些由上帝安置在他们头上的主人的命令。简言之，英国资产阶级这时已经参加镇压“下层等级”、从事生产的广大人民群众，而用来达到这一目的的手段之一，就是宗教的影响。","language":"中文","translation":false},{"id":"socialism-8-40","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":40,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"另外还有一件事情也助长了资产阶级的宗教倾向。这就是唯物主义在英国的兴起。这个新的［注：在德译文中在“新的”的后面补充有：“无神论的”。——编者注］学说，不仅震动了中等阶级的宗教情感，而且还宣布自己是仅仅适合于世界上的学者和有教养的人们的哲学，而跟适合于包括资产阶级在内的没有受过教育的群众的宗教大大不同。它同霍布斯一起，作为至高无上的王权的保卫者登上了舞台，并且号召君主专制制度镇压这个puer robustus sed malitiosus〔强壮而心怀恶意的小伙子〕，即人民[307]。同样地，在霍布斯的后继者博林布罗克、舍夫茨别利等人那里，唯物主义的新的自然神论形式，仍然是一种贵族的、秘传的学说，可见，唯物主义之所以被中等阶级仇视，既由于它是宗教的异端，也由于它具有反资产阶级的政治联系。于是，同贵族的唯物主义和自然神论相反，过去曾经为反对斯图亚特王朝的斗争提供旗帜和战士的新教教派，继续提供了进步的中等阶级的主要战斗力量，并且直到今天还是“伟大的自由党”的主要骨干。","language":"中文","translation":false},{"id":"socialism-8-41","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":41,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"这时候，唯物主义从英国传到了法国，它在那里遇到了另一个唯物主义哲学学派，即笛卡儿学派[308]的一个支脉，并且和这个学派汇合了。在法国，唯物主义最初也完全是贵族的学说。但是不久，它的革命性就呈现出来了。法国的唯物主义者没有把他们的批评局限于宗教信仰问题；他们把批评扩大到他们所遇到的每一个科学传统或政治设施；而为了证明他们的学说可以普遍应用，他们选择了最简便的道路：在他们因以得名的巨著“百科全书”中，他们大胆地把这一学说应用于所有的知识对象。这样，唯物主义就以其两种形式中的这种或那种形式——公开的唯物主义或自然神论，成了法国一切有教养的青年的信条。它的影响是如此巨大，以致在大革命爆发时，这个由英国保皇党孕育出来的学说，竟给了法国共和党人和恐怖主义者一面理论旗帜，并且为“人权宣言”[309]提供了底本。","language":"中文","translation":false},{"id":"socialism-8-42","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":42,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"法国大革命是资产阶级的第三次起义，然而这是第一次完全抛开了宗教外衣，并在毫不掩饰的政治战线上作战；这也是第一次真正把斗争进行到底，直到交战的一方即贵族被消灭而另一方即资产阶级获得完全胜利。在英国，革命以前和革命以后的制度之间的继承关系、地主和资本家之间的妥协，表现在诉讼程序被继续应用和封建法律形式被虔诚地保存下来这方面。在法国，革命同过去的传统完全决裂；它扫清了封建制度的最后遗迹，并且在Code civil [310]中把古代罗马法——它差不多完满地表现了马克思称为商品生产的那个经济发展阶段的法律关系——巧妙地运用于现代的资本主义条件；它运用得如此巧妙，以致这部法国的革命的法典，直到现在还是包括英国在内的所有其他国家在财产法方面实行改革时所依据的范本。可是我们不要忘记，虽然英国的法律仍然用野蛮的封建的语言来表达资本主义社会的经济关系，——这种语言之符合于它所表达的事物，正像英文的拼法符合于英文的读音一样（一个法国人说过：vous écrivez Londres et vous prononcez Constantionopole〔你们写下伦敦，而读出来却是君士坦丁堡〕）——但是也只有这个英国法律把大陆上那些在君主专制时期已经丧失而到现在还没有在任何地方完全恢复起来的个人自由、地方自治以及除法庭干涉以外不受任何干涉的独立性，即古代日耳曼自由中的精华部分，保存了几个世纪，并且把它们移植到美洲和各殖民地。","language":"中文","translation":false},{"id":"socialism-8-43","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":43,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"还是回过来谈我们的英国资产者吧。法国革命给了他一个极好的机会，使他能够借助大陆上的君主国家来破坏法国的海上贸易，兼并法国的殖民地，并且完全摧毁法国争霸海上的野心。这是他向法国革命进行斗争的原因之一。另一个原因是，这次革命的方法很不合他的胃口。这不仅仅是由于这次革命的“可恶的”恐怖政策，而且还由于这次革命企图使资产阶级的统治走向极端。英国资产者如果没有本国的贵族教他像贵族一样待人接物，替他开创新风气，给他提供陆军军官去维持国内秩序，提供海军军官去夺取殖民地和新的海外市场，那他怎么能行呢？诚然，资产阶级中也有少数进步的人，他们并没有从妥协中得到多大利益；这一部分人主要是不太富裕的中等阶级，他们同情这次革命[311]，但是在议会中没有势力。","language":"中文","translation":false},{"id":"socialism-8-44","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":44,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"这样，如果说唯物主义成了法国革命的信条，那末敬畏上帝的英国资产者就更加紧紧地抓住自己的宗教。难道巴黎的恐怖时代没有证明，群众的宗教本能一旦失去，会有什么样的结局？唯物主义愈是从法国传播到邻近的国家，愈是得到各种类似的理论思潮、特别是德国哲学的支持，唯物主义和自由思想愈是在大陆上普遍地真正成为一个有教养的人所必需具备的条件，英国的中等阶级就愈是固执地坚守它的各种各样的宗教信条。这些信条，尽可以彼此不同，但是它们全都是明显的宗教信条，基督教信条。","language":"中文","translation":false},{"id":"socialism-8-45","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":45,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"当革命在法国保证了资产阶级的政治胜利的时候，在英国，瓦特、阿克莱、卡特赖特以及其他等人，开始了产业革命，这一革命把经济力量的重心完全转移了。资产阶级的财富，比土地贵族的财富增长得快得多。在资产阶级内部，金融贵族、银行家等等，愈来愈被工厂主推到后台去了。1689年的妥协，甚至在经过一些逐步的对资产阶级有利的修改以后，也不再适合这个妥协的参与者的力量对比了。这些参与者的性质也改变了；1830年的资产阶级，同前一世纪的资产阶级是大不相同的。仍然留在贵族手中并且被贵族用来抵制新工业资产阶级的野心的政治权力，已经同新的经济利益不能相容了。于是必须同贵族进行一次新的斗争；这一斗争的结局只能是新的经济力量的胜利。首先，在1830年的法国革命的刺激下，不顾一切抵抗，通过了改革法案[312]。这使资产阶级在议会里获得了公认的和强大的地位。随后是谷物法的废除，这永远确定了资产阶级、特别是资产阶级中最活跃的部分即工厂主对土地贵族的优势。这是资产阶级的最大的胜利；然而这也是它专门为自己的利益获得的最后一次胜利。它后来取得的任何一次胜利，都不得不同一个新的社会力量分享，这个新的社会力量起初是它的同盟者，但是不久就成了它的对手。","language":"中文","translation":false},{"id":"socialism-8-46","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":46,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"产业革命创造了一个大工业资本家的阶级，但是也创造了一个人数远远超过前者的产业工人的阶级。这个阶级，随着产业革命对一个又一个的工业部门的占领，在人数上不断地增加；而随着人数的增加，它在力量上也增加了。这一力量早在1824年就表现了出来，当时它迫使议会勉强地废除了禁止工人结社的法律[313]。在改革运动中，工人是改革派的激进的一翼；当1832年的法案剥夺了他们的选举权的时候，他们就把自己的要求写进人民宪章，并且为了同强大的资产阶级反谷物法同盟[314]相对抗，组成了一个独立的政党，即宪章派。这是近代第一个工人政党。","language":"中文","translation":false},{"id":"socialism-8-47","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":47,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"后来，大陆上发生了1848年2月和3月的革命，在这些革命中，工人起了很重要的作用，而且，至少在巴黎，提出了从资本主义社会的观点看来决不能允许的要求。接着而来的是普遍的反动。最初是1848年4月10日宪章派的失败；其次是同年6月巴黎工人起义的被镇压；再其次是1849年意大利、匈牙利和德国南部的不幸事件；最后是1851年12月2日路易·波拿巴战胜巴黎。这样，工人阶级的要求的吓人声势，至少在短时期内被压制下去了，可是用了多少代价啊！如果说，英国资产者先前已经确信有必要使普通人民保持宗教情绪，那末，在经历了这一切之后，他一定会如何更加强烈地感觉到这种必要性呢？他不理会大陆上的伙伴们的讥笑，年复一年地继续把成千上万的金钱花在向下层等级宣传福音方面；他不满足于他本国的宗教机关，还求助于当时宗教买卖的最大组织者“琼生大哥”，从美国输入了基督复活派[315]，穆迪和桑基之流；最后他还接受了“救世军”的危险的帮助，“救世军”恢复了早期基督教的宣传，把穷人当做上帝的选民看待，用宗教方式反对资本主义，从而使早期基督教的阶级对抗的因素得到滋长，这对于目前在这上面花现钱的富翁来说，总有一天会带来麻烦的。","language":"中文","translation":false},{"id":"socialism-8-48","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":48,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"看来这似乎是历史发展的规律：资产阶级在欧洲任何一个国家都不能——至少是不能长时期地——像中世纪的封建贵族那样独自掌握政权。即使在封建制度已经完全消灭了的法国，资产阶级作为一个整体，也只是在很短的时期内完全掌握了政权。在路易-菲力浦统治时期，即1830—1848年，是极小一部分资产阶级统治着王国，而大得多的一部分，则被高标准的选举资格限制剥夺了选举权。在第二共和国时代，即1848—1851年，整个资产阶级统治了国家，但只有三年之久；资产阶级的无能，带来了第二帝国。只是在现在，在第三共和国时代，资产阶级作为一个整体，掌握了政权达二十年以上；而它已经显露出衰落的鲜明征兆了。资产阶级的长期统治，只有在美国那样一个从来没有过封建制度而且社会一开始就建立在资产阶级基础之上的国家中，才是可能的。但是即使在法国和美国，资产阶级的继承者——工人，也已经在敲门了。","language":"中文","translation":false},{"id":"socialism-8-49","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":49,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"在英国，资产阶级从来没有掌握过全权。甚至1832年的胜利，也还是让土地贵族几乎独占了政府所有的高级职位。富裕的中等阶级对此表示的温顺态度，在自由党的大工厂主威·爱·福斯特先生发表那次公开演说以前，我是一直不能理解的。福斯特先生在那次演说中劝告布莱得弗德的青年学习法语，以此作为出人头地的手段，并且援引自己的经验说，当他作为一个内阁大臣而必须出入于那种说法语至少和说英语同样必要的社交场合时，他是感到多么难堪！的确，当时的英国中等阶级通常都是完全没有受过教育的暴发户，他们没有办法不把政府的那些高级职位让给贵族，因为那里所需要的，是其他一些条件，而不是加上了商业干练气味的岛国狭隘性和岛国自大心。［注：即使在商业上，采取民族沙文主义的自大态度也是足以坏事的。直到最近，普通的英国工厂主还以为，英国人不说本国话而说外国话，是有失体面的，而且当他看到外国的“可怜虫”迁居到英国，使他免去向国外推销产品的麻烦时，便颇为自傲了。他根本没有觉察到，这些外国人（大部分是德国人）这样一来就控制了英国对外贸易（不论是进口还是出口）的很大一部分，而英国人的直接对外贸易则变得几乎只局限于殖民地、中国、美国和南美洲了。他也没有觉察到，这些德国人同在外国的其他德国人进行贸易，后者逐渐组织了一个遍及世界各地的完整的商业殖民地网。大约四十年前，当德国认真地开始生产出口商品的时候，这个商业殖民地网，就给德国帮了很大的忙，使它在很短的时期内从一个输出粮食的国家变成一个头等的工业国。后来，大约十年前，英国的工厂主才大吃一惊，去问英国的大使们和领事们：为什么他再也保持不住自己的顾客。一致的答复是：（1）你们不学你们的顾客的语言，却要求他们说你们的语言；（2）你们不但不设法去适应你们的顾客的需要、习惯与爱好，反而要他们迁就你们的英国式的需要、习惯和爱好。］甚至目前报纸上关于中等阶级教育的无休止的争论，也表明英国中等阶级仍然认为自己不配受最好的教育，而为自己寻找某种比较谦卑的东西。所以，似乎很自然，甚至在谷物法废除以后，那些取得了胜利的人物，科布顿们、布莱特们、福斯特们等等，还不能正式参与统治国家，直到二十年之后，新的改革法案[316]才为他们敞开了内阁的大门。直到今天，英国的资产阶级还深深感到自己的社会地位很低，甚至用自己的和人民的金钱去豢养一个供装饰用的有闲等级，要它在一切庄严的场合体面地代表民族；而且当他们自己中间有人被认为有资格进入这个归根到底是他们自己造就的高等特权集团里去的时候，他们便认为是无上的光荣。","language":"中文","translation":false},{"id":"socialism-8-50","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":50,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"这样，工商业中等阶级还没有来得及把土地贵族从政权中完全赶走，另一个竞争者，工人阶级，便已经登上舞台了。宪章运动和大陆革命以后的反动，以及1848—1866年英国贸易的空前繁荣（通常以为这只是由于自由贸易，其实在更大得多的程度上是由于铁路、远洋轮船以及一般交通工具的巨大发展），重新迫使工人阶级处于依附自由党的地位，他们在这个党内，也像在宪章运动以前一样，组成了激进的一翼。可是，工人们对选举权的要求逐渐成为不可遏制的了；在辉格党人即自由党的首领们“畏缩不前”的时候，迪斯累里却显示了自己的高明，他促使托利党人抓紧有利的时机，在城市选区中实施了户主的选举权［注：在德国文中在“户主的选举权”的后面补充有：“（它适用于每一个租有单独住房的人）”。——编者注］，并且重新划分了选区。随着实行了秘密投票；1884年又把户主的选举权推广到各郡，并且又重新划分了选区，使各选区在某种程度上趋于平衡。[317]这一切措施大大增加了工人阶级在选举中的力量，使工人阶级至少在150个到200个选区中现在已经占选民的大多数。但是议会制度是训练人们尊重传统的最好的学校；如果说，中等阶级曾经怀着敬畏的心情仰望约翰·曼纳斯勋爵所戏称的“我们的老贵族”，那末，工人群众则以尊重和恭敬的态度去看待当时所谓的“优越者”即中等阶级。的确，大约在十五年前，英国的工人是模范工人，他们对雇主的恭敬，以及他们在为自己要求权利时所表现的克己的谦逊，大可排解我们德国的讲坛社会主义学派[318]的经济学家们由于他们本国工人的不可救药的共产主义倾向和革命倾向而产生的烦恼。","language":"中文","translation":false},{"id":"socialism-8-51","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":51,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"但是英国的中等阶级——毕竟是很好的生意人——比德国的教授们看得远。他们只是迫不得已才同工人阶级分享了政权。他们在宪章运动的年代里领教过人民这个puer robustus sed malitiosus〔强壮而心怀恶意的小伙子〕的作为。从那时以来，他们被迫把人民宪章的大部分要求纳入了联合王国的法律之中。现在比以往任何时候都更需要用精神手段去控制人民，而一切能影响群众的精神手段中第一个和最重要的手段依然是宗教。于是，学校董事会中就让牧师占据优势；于是，资产阶级日益增加自我捐税，以维持各种基督复活派［注：在德译文中不是“以维持各种基督复活派”，而是“以利用各种各样的宗教蛊惑方式”。——编者注］，从崇礼派[319]直到“救世军”。","language":"中文","translation":false},{"id":"socialism-8-52","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":52,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"现在，英国的体面人物［注：在德译文中不是“英国的体面人物”，而是“英国的体面庸人”。——编者注］战胜了大陆资产者的自由思想和对待宗教的冷淡态度。法国和德国的工人已经变成了叛乱者。他们全都感染了社会主义，而且根据相当充分的理由，他们在选择取得统治的手段时，丝毫不在乎这种手段是否合法。这个puer robustus〔强壮的小伙子〕一天比一天更malitiosus〔心怀恶意〕。法国和德国的资产阶级，只好采取最后的办法，不声不响地丢掉了他们的自由思想，就像一个年轻人感到晕船晕得厉害的时候把他在船上装模作样抽着玩的雪茄烟悄悄地丢掉一样；嘲笑宗教的人，一个一个地在外表上变成了笃信宗教的人，他们毕恭毕敬地谈论教会、它的教条和仪式，甚至在实在不得已的时候，自己也行起这些仪式来了。法国资产者每逢星期五进maigre〔素食〕，德国资产者每逢星期日就坐在教堂的椅子上耐心地听完新教的冗长的布道。他们已经吃了唯物主义的苦头。《Die Religion muss dem Volk erhalten werden》——“必须为人民保存宗教”，这是拯救社会于完全毁灭的唯一的和最后的手段。对他们自己不幸的是：等到他们发现这一点的时候，他们已经用尽一切力量把宗教永远破坏了。现在轮到英国资产者来嘲笑他们了：“蠢才！这个我早在两百年前就可以告诉你们了！”","language":"中文","translation":false},{"id":"socialism-8-53","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":53,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"然而，无论英国资产者的宗教愚钝，或是大陆资产者的post festum〔事后〕皈依宗教，恐怕都不能阻止日益高涨的无产阶级的潮流。传统是一种巨大的阻力，是历史的vis inertiae〔惰性力〕，但是由于它只是消极的，所以一定要被摧毁；因此，宗教也不能长期成为资本主义社会的保护物。如果说，我们的法律的、哲学的和宗教的观念，都是在一定社会内占统治地位的经济关系的或近或远的枝叶，那末，这些观念终究抵抗不住因这种经济关系完全改变而产生的影响。除非我们相信超自然的奇迹，否则，我们就必须承认，任何宗教教义都不足以支持一个摇摇欲坠的社会。","language":"中文","translation":false},{"id":"socialism-8-54","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":54,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"事实上，在英国，工人也开始重新动起来了。毫无疑义，他们还被各种传统束缚着。有资产阶级的传统，例如一种很普遍的看法，以为只能有两个政党——保守党和自由党，而工人阶级必须依靠和通过伟大的自由党来谋取自身的解放。还有工人的传统，从工人们最初摸索着从事独立行动的努力中继承下来的传统，例如，把一切没有经过正规学徒训练的工人排斥于许多旧工联之外；这就等于每一个采取这种做法的工会在为自己培养工贼。但是尽管如此，英国的工人阶级还是在前进，甚至布伦坦诺教授也不能不惋惜地把这一点告诉他的讲坛社会主义者同仁[320]。如同英国的一切事情一样，工人阶级用缓慢而适度的步伐前进着，前进中有时踌躇不定，有时做一些没有效果的尝试；它在前进中有时对“社会主义”这个名称表示过分的不信任，同时却逐渐地吸收着社会主义的实质；运动在扩展着，并且一批接着一批地把工人吸引进来。现在它已经把伦敦东头的没有技术的工人从沉睡中唤醒了，我们全都看到这些新的力量反过来又给了工人阶级以多么有力的推动。如果运动的步伐赶不上某些人的急躁要求，那末就请他们不要忘记：正是英国工人阶级保存着英国民族性格的最优秀的品质，在英国，一个进步一经取得，照例以后永不会失去。如果说老宪章派的儿子们，由于上述原因，还做得不够，那末，孙子们则可望不辱没他们的祖父。","language":"中文","translation":false},{"id":"socialism-8-55","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":55,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"但是，欧洲工人阶级的胜利，不是只依靠英国一个国家。它至少需要英法德三国的共同努力，才能得到保证。在法国和德国，工人运动大大超过了英国。在德国，工人运动的胜利甚至指日可待了。那里的工人运动在最近二十五年所获得的进展是空前的。它正以日益增加的速度前进着。如果说，德国的中等阶级已经表明自己非常缺乏政治才能、纪律、勇气、坚韧和毅力，那末，德国工人阶级则充分证明了自己具备这些品质。四百年前，德国是欧洲中等阶级第一次起义的出发点；依目前的形势来判断，德国难道不可能同样成为欧洲无产阶级第一次伟大胜利的舞台吗？","language":"中文","translation":false},{"id":"socialism-8-56","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":56,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"载于1892年在伦敦出版的弗里德里希·恩格斯“社会主义从空想到科学的发展”，并由作者译成德文摘要发表于1892—1893年“新时代”杂志第1卷第1期和第2期","language":"中文","translation":false},{"id":"socialism-8-57","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":57,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"中文根据“马克思恩格斯文选（两卷集）”英文本1958年版译出，并参考了德译文和俄译文","language":"中文","translation":false},{"id":"socialism-8-58","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":58,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[286] 这篇导言是恩格斯为他的著作“社会主义从空想到科学的发展”（见“马克思恩格斯全集”中文版第19卷第201—247页）的英文版写的。英文版于1892年在伦敦出版，译者是爱·艾威林，书名是：“空想社会主义和科学社会主义”。恩格斯把他在1882年写的“马尔克”（见“马克思恩格斯全集”中文版第19卷第351—369页）一文作为附录收在这一版中。","language":"中文","translation":false},{"id":"socialism-8-59","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":59,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"恩格斯在1892年6月把这篇导言译成德文，在7月间寄给“新时代”杂志，发表于1892年第1期和第2期，标题是：“论历史唯物主义”。杂志编辑部在发表这篇导言时，删去了前面的七段，并在脚注中说，这几段文字的内容在德国是尽人皆知的，不会引起德国读者的兴趣。","language":"中文","translation":false},{"id":"socialism-8-60","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":60,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"导言的个别部分曾以“资产阶级对封建主义的三次会战”、“工人政党”为标题，用法文发表于1892年12月4、11和25日，1893年1月1和9日“社会主义者报”第115、116、118、119和120号。导言还曾用保加利亚文发表于1892年“社会民主党人”杂志第3期（删去前面八段）。","language":"中文","translation":false},{"id":"socialism-8-61","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":61,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"这篇导言的俄译文第一次于1926年由马克思列宁主义研究院发表于恩格斯“社会主义从空想到科学的发展”一书。——第334页。","language":"中文","translation":false},{"id":"socialism-8-62","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":62,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[287] 关于爱森纳赫派和拉萨尔派的合并，见注132。——第334页。","language":"中文","translation":false},{"id":"socialism-8-63","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":63,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[288] 指以下这几部著作：欧·杜林“哲学教程——严格科学的世界观和生命形成”1875年莱比锡版（E．Dühring．《Cursus der Philosophie als streng wissenschaftlicher Weltanschauung und Lebensgestaltung》．Leipzig，1875），欧·杜林“国门—社会经济学教程，兼论财政政策的基本问题”1876年莱比锡第2版（E．Dühring．《Cursus der Nationalund Socialökonomie einschliesslich der Hauptpunkte der Finanzpolitik》．2．Aufl．，Leipzig，1876），欧·杜林“国民经济学和社会主义批判史”1875年柏林第2版（E．Dühring．《Kritische Geschichte der Nationalökonomie und des Socialismus》．2．Aufl．，Berlin，1875）。——第337页。","language":"中文","translation":false},{"id":"socialism-8-64","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":64,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[289] 复本位制是金银两种金属同时起货币作用的币制。——第337页。","language":"中文","translation":false},{"id":"socialism-8-65","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":65,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[290] 恩格斯的著作“反杜林论”（见“马克思恩格斯全集”俄文第2版第20卷第1—338页）以一系列论文的形式陆续发表于1877年1—5月的“前进报”，以及1877年7—12月和1878年5—7月的该报附刊。第一版单行本于1878年在莱比锡出版。","language":"中文","translation":false},{"id":"socialism-8-66","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":66,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"“前进报”（《Vorwärts》）是德国社会主义工人党的中央机关报。根据1876年党的哥达代表大会的决定，该报从1876年10月1日起在莱比锡出版，用以代替爱森纳赫派的机关报“人民国家报”和拉萨尔派的机关报“新社会民主党人报”（《Neuer Sozialdemokrat》）；反社会党人非常法颁布后，该报于1878年10月27日停刊。——第337页。","language":"中文","translation":false},{"id":"socialism-8-67","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":67,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[291] F．Engels．《Socialisme utopique et socialisme scientifique》．Paris，1880．这本小册子是恩格斯根据“反杜林论”中“导言”的第一章和第三篇的第一、二两章，并对它们做了一系列增补和一些修改而编成的。“社会主义从空想到科学的发展”是1883年德文第一版所用的书名。——第337页。","language":"中文","translation":false},{"id":"socialism-8-68","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":68,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[292] F．Engels．《Socyjalizm utopijny a naukowy》．Genève，Redakcyi《Przedswitu》，1882．关于西班牙文版，见注211。——第337页。","language":"中文","translation":false},{"id":"socialism-8-69","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":69,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[293] F．Engels．《Socialism utopic si socialism stiintific》．Bucuresti，1891．关于恩格斯这一著作的德文版、意大利文版、俄文版、丹麦文版和荷兰文版，见注210和注211。——第337页。","language":"中文","translation":false},{"id":"socialism-8-70","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":70,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[294] 恩格斯指的是马·马·柯瓦列夫斯基的著作：“家庭及所有制的起源和发展概论”1890年斯德哥尔摩版（《Tableau des origines et de l’évolution de la famille et de la proprieté》．Stockholm，1890）和“原始法权，第一分册：氏族”1886年莫斯科版（《Первобытное право，выпуск Ⅰ，Род》．Ｍ．，1886）。——第338页。","language":"中文","translation":false},{"id":"socialism-8-71","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":71,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[295] 关于“资本论”英文版，见注272。——第338页。","language":"中文","translation":false},{"id":"socialism-8-72","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":72,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[296] 唯名论者代表中世纪哲学的一个派别，认为一般的类概念只是名字，即人的思维和语言的产物，它们只能用来表明现存的单个事物。同中世纪的实在论者相反，唯名论者认为概念不是产生事物的原型，不是创造事物的源泉。因此，他们承认事物的第一性和概念的第二性。在这个意义上，唯名论是中世纪唯物主义的最初表现。——第339页。","language":"中文","translation":false},{"id":"socialism-8-73","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":73,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[297] 按照古希腊哲学家阿那克萨哥拉的学说，同素体是可以无限分割的、具有质的规定性的极小的物质粒子。阿那克萨哥拉认为，同素体是万物的本源，它们的结合构成各种不同的物体。——第339页。","language":"中文","translation":false},{"id":"socialism-8-74","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":74,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[298] 约·洛克“人类悟性论”（J．Locke．《An Essay concerning Human Understanding》）第一版于1690年在伦敦出版。——第341页。","language":"中文","translation":false},{"id":"socialism-8-75","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":75,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[299] 自然神论是一种宗教哲学学说，认为神是非人格的、有理性的世界始因，但是神不干预自然现象和社会生活。在封建教会世界观统治的条件下，自然神论往往站在唯理论的立场上批评中世纪的神学世界观，揭露僧侣们的寄生生活和招摇撞骗的行为。——第341页。","language":"中文","translation":false},{"id":"socialism-8-76","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":76,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[300] 卡·马克思和弗·恩格斯“神圣家族，或对批判的批判所做的批判。驳布鲁诺·鲍威尔及其伙伴”（引文参看“马克思恩格斯全集”中文版第2卷第163—165页）。——第341页。","language":"中文","translation":false},{"id":"socialism-8-77","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":77,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[301] 指1851年5—10月在伦敦举行的第一届世界工商业博览会。——第342页。","language":"中文","translation":false},{"id":"socialism-8-78","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":78,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[302] “救世军”是反动的宗教慈善组织，1865年由传教士威·布斯在英国创立，后来它的活动又扩展到其他国家（1880年按军队编制改组后才采用这个名称）。该组织利用资产阶级的大力支持，进行广泛的宗教宣传，建立了一整套慈善机构，其目的是使劳动群众离开反对剥削者的斗争。救世军的某些传教士进行社会性的蛊惑宣传，表面上谴责富人的利己主义。——第343页。","language":"中文","translation":false},{"id":"socialism-8-79","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":79,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[303] 指比·西·拉普拉斯的著作“论天体力学”（《Traité de mécanique céleste》），第一版于1799—1825年在巴黎出版，共五卷。——第343页。","language":"中文","translation":false},{"id":"socialism-8-80","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":80,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[304] 1522—1523年的德国贵族起义和1524—1525年的德国农民战争，恩格斯在“德国农民战争”中作了阐述（见“马克思恩格斯全集”中文版第7卷第383—483页）。——第348页。","language":"中文","translation":false},{"id":"socialism-8-81","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":81,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[305] 英国资产阶级历史著作都把1688年的政变称为“光荣革命”，由于这次政变，在英国推翻了斯图亚特王朝，确立了建立在土地贵族和大资产阶级妥协基础上的、以奥伦治的威廉（从1689年起）为首的君主立宪制。——第350页。","language":"中文","translation":false},{"id":"socialism-8-82","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":82,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[306] 红白蔷薇战争（1455—1485年）是两个争夺王位的英国封建家族的代表之间即约克族和郎卡斯特族之间的战争。约克族的纹章上饰有白色蔷薇，郎卡斯特族的纹章上饰有鲜红色蔷薇。站在约克族方面的有经济比较发达的南部的一部分大封建主，有骑士和市民；支持郎卡斯特族的是北部诸郡的封建贵族。这次战争几乎完全消灭了古老的封建家族，结果在英国建立了新的都铎王朝的统治，实行了专制政体。——第350页。","language":"中文","translation":false},{"id":"socialism-8-83","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":83,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[307] 语出霍布斯“论公民”（《De Cive》）一书序言，该书于1642年在巴黎写成，最初流传的是手抄本，1647年才在阿姆斯特丹刊印。——第352页。","language":"中文","translation":false},{"id":"socialism-8-84","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":84,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[308] 笛卡儿学派的哲学是十七世纪法国哲学家笛卡儿（拉丁文为Cartesius）的继承者的学说，他们从他的哲学中做出了唯物主义的结论。——第352页。","language":"中文","translation":false},{"id":"socialism-8-85","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":85,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[309] 恩格斯指的是1789年制宪议会通过的“人权和公民权宣言”，其中阐明了新的资产阶级制度的政治原则。1791年的法国宪法中包括了这篇宣言；根据它起草的1793年雅各宾派的“人权和公民权宣言”被置于1793年国民公会通过的法国的第一个共和宪法的前面。——第352页。","language":"中文","translation":false},{"id":"socialism-8-86","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":86,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[310] Code civil（民法典）是1804—1810年法国在拿破仑第一时代制订的（因此民法典又通称为拿破仑法典）、系统地阐明资产阶级法权的五部法典之一。恩格斯把1804年通过的民法典称为典型的资产阶级社会的法典（见“马克思恩格斯全集”俄文第2版第21卷第311页）。——第353页。","language":"中文","translation":false},{"id":"socialism-8-87","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":87,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[311] 恩格斯指的是英国小资产阶级激进阶层和资产阶级知识分子对十八世纪末法国资产阶级革命所采取的同情态度。联合在伦敦革命协会中的、主要是联合在伦敦通讯协会和英国其他各大城市通讯协会中的法国革命拥护者（在协会的组织者和参加者中有工人阶级的代表）宣传革命思想，提出实现普选权和其他民主改革的要求。各通讯协会都受到英国寡头政治的执政者的迫害。——第354页。","language":"中文","translation":false},{"id":"socialism-8-88","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":88,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[312] 见注276。——第355页。","language":"中文","translation":false},{"id":"socialism-8-89","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":89,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[313] 1824年英国议会在工人的群众运动的压力下被迫通过了一项废除禁止工人结社（工联）的法令。1825年，议会通过了结社法亦称工人联合法，这项法律重申废除禁止工联的决定，但是严格限制工联的活动。例如仅仅宣传工人结社和参加罢工就被看做“强制”和“暴力”，而受到刑事处分。——第355页。","language":"中文","translation":false},{"id":"socialism-8-90","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":90,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[314] 人民宪章——见注274。","language":"中文","translation":false},{"id":"socialism-8-91","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":91,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"反谷物法同盟是英国工业资产阶级的组织，于1838年由曼彻斯特的工厂主科布顿和布莱特所创立。同盟要求贸易完全自由，废除谷物法（见注266），其目的是为了降低工人的工资，削弱土地贵族的经济和政治地位。同盟在反对土地占有者的斗争中曾经企图利用工人群众，可是就在这个时候，英国的先进工人展开了独立的、有自己的政治主张的工人运动（宪章运动）。谷物法废除以后，同盟即不存在。——第355页。","language":"中文","translation":false},{"id":"socialism-8-92","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":92,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[315] 琼生大哥（Brother Jonathan）是在英属北美殖民地独立战争时（1775—1783年）英国人给北美人起的绰号。","language":"中文","translation":false},{"id":"socialism-8-93","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":93,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"基督复活派是新教教会中的一个流派，十八世纪上半叶产生于英国，流行于北美。它的信徒力图通过宗教说教和组织新的信仰者的团体来巩固和扩大基督教的影响。——第356页。","language":"中文","translation":false},{"id":"socialism-8-94","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":94,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[316] 指1867年得比—迪斯累里的保守党政府实行的议会改革（见注277）。——第357页。","language":"中文","translation":false},{"id":"socialism-8-95","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":95,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[317] 关于英国实行秘密投票和1884年议会改革，见法277。——第358页。","language":"中文","translation":false},{"id":"socialism-8-96","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":96,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[318] 见注135。——第359页。","language":"中文","translation":false},{"id":"socialism-8-97","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":97,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[319] 崇礼派（更流行的名称是皮由茲教派）是产生于十九世纪三十年代的、英国国教会中的一个流派。它的信徒号召在英国国教中恢复天主教的仪式（崇礼派即因此而得名）和天主教的某些教义。——第359页。","language":"中文","translation":false},{"id":"socialism-8-98","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"“社会主义从空想到科学的发展”英文版导言","page":8,"paragraph":98,"url":"https://www.marxists.org/chinese/engels/1880/07.htm","text":"[320] 恩格斯指的是路·布伦坦诺论述英国工联的著作和言论（见注184）。在这些著作和言论中，布伦坦诺竭力称赞英国的工联主义，说它是工人阶级组织的典范，可以在资本主义条件下使工人阶级状况得到根本的改善，并摆脱资本主义剥削。按照布伦坦诺和其他讲坛社会主义者的说法，组织得很好的工会可以使工人阶级的政治斗争和政党成为多余的。恩格斯在“布伦坦诺contra马克思”这部著作（本卷第107—213页）中揭露了这种说法的虚伪性质和阶级内容。——第360页。","language":"中文","translation":false},{"id":"socialism-9-1","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"中文马克思主义文库 -> 恩格斯 -> 《社会主义从空想到科学的发展》","language":"中文","translation":false},{"id":"socialism-9-2","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"恩格斯在《社会主义从空想到科学的发展》这本小册子中","language":"中文","translation":false},{"id":"socialism-9-3","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"对《反杜林论》正文所作的补充和修改[538]","language":"中文","translation":false},{"id":"socialism-9-4","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［注：这里标明的《反杜林论》的章次、本卷页码以及方括弧里的说明，都是编者加的。——译者注］","language":"中文","translation":false},{"id":"socialism-9-5","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“和任何新的学说一样，它必须首先从已有的思想材料出发，虽然它的根源深藏在经济的事实中。”——在《社会主义从空想到科学的发展》中，对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-6","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"和任何新的学说一样，它必须首先从已有的思想材料出发，虽然它的根源深藏在物质的经济的事实中。〔见《马克思恩格斯全集》中文版第19卷第205页〕","language":"中文","translation":false},{"id":"socialism-9-7","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“那时，如黑格尔所说的，是世界用头立地的时代。”——在这句话后面加了如下的附注：］","language":"中文","translation":false},{"id":"socialism-9-8","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"关于法国革命黑格尔这样写道：“正义思想、正义概念立刻得到了公认，非正义的旧支柱不能对它作任何抵抗。因此，正义思想现在就成了宪法的基础，今后一切都必须以它为根据。自从太阳照耀在天空而行星围绕着太阳旋转的时候起，还从来没有看到人用头立地，即用思想立地并按照思想去构造现实。阿那克萨哥拉第一个说，Ｎûｓ即理性支配着世界；可是直到现在人们才认识到思想应当支配精神的现实。这是一次壮丽的日出。一切能思维的生物都欢庆这个时代的来临。这时笼罩着一种高尚的热情，全世界都浸透了一种精神的热忱，仿佛第一次达到了神意和人世的和谐。”（黑格尔《历史哲学》1840年版第535页）难道现在不应当用反社会党人法去反对已故的黑格尔教授的这种危险的颠复学说吗？〔见《马克思恩格斯全集》中文版第19卷第205—206页〕","language":"中文","translation":false},{"id":"socialism-9-9","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“只是现在阳光才照射出来。从今以后，迷信、偏私、特权和压迫，必将为永恒的真理，为永恒的正义，为基于自然的平等和不可剥夺的人权所排挤。”——对这段话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-10","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"只是现在阳光才照射出来，理性的王国才开始出现。从今以后，迷信、偏私、特权和压迫，必将为永恒的真理，为永恒的正义，为基于自然的平等和不可剥夺的人权所排挤。〔见《马克思恩格斯全集》中文版第19卷第206页〕","language":"中文","translation":false},{"id":"socialism-9-11","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“但是，除了封建贵族和市民等级之间的对立，还存在着剥削者和被剥削者、游手好闲的富人和从事劳动的穷人之间的一般的对立。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-12","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"但是，除了封建贵族和作为社会所有其余部分的代表出现的市民等级之间的对立，还存在着剥削者和被剥削者、游手好闲的富人和从事劳动的穷人之间的一般的对立。〔见《马克思恩格斯全集》中文版第19卷第206页〕","language":"中文","translation":false},{"id":"socialism-9-13","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“例如，德国宗教改革和农民战争时期的托马斯·闵采尔派，英国大革命时期的平等派，法国大革命时期的巴贝夫。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-14","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"例如，德国宗教改革和农民战争时期的再洗礼派和托马斯·闵采尔，英国大革命时期的平等派，法国大革命时期的巴贝夫。〔见《马克思恩格斯全集》中文版第19卷第207页〕","language":"中文","translation":false},{"id":"socialism-9-15","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“苦修苦炼的、斯巴达式的共产主义，是这个新学说的第一个表现形式。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-16","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"苦修苦炼的、禁绝一切生活享受的、斯巴达式的共产主义，是这个新学说的第一个表现形式。〔见《马克思恩格斯全集》中文版第19卷第207页〕","language":"中文","translation":false},{"id":"socialism-9-17","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“他们和启蒙学者一样，并不是想解放某一个阶级，而是想解放全人类。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-18","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"他们和启蒙学者一样，并不是想首先解放某一个阶级，而是想立即解放全人类。〔见《马克思恩格斯全集》中文版第19卷第207页〕","language":"中文","translation":false},{"id":"socialism-9-19","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“这种见解本质上是英国和法国的一切社会主义者以及包括魏特林在内的第一批德国社会主义者的见解。”——对这句话作了如下的修改：］","language":"中文","translation":false},{"id":"socialism-9-20","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":20,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"空想主义者的见解曾经长期地支配着十九世纪的社会主义观点，而且现在还部分地支配着这种观点。法国和英国的一切社会主义者不久前都还信奉这种见解，包括魏特林在内的先前的德国共产主义也是这样。〔见《马克思恩格斯全集》中文版第19卷第217页〕","language":"中文","translation":false},{"id":"socialism-9-21","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":21,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“当我们深思熟虑地考察自然界或人类历史或我们自己的精神活动的时候，首先呈现在我们眼前的，是一幅由种种联系和相互作用无穷无尽地交织起来的画面，其中没有任何东西是不动的和不变的，而是一切都在运动、变化、产生和消失。”——在这段话之后作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-22","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":22,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"所以我们首先看到的是总画面，其中各个细节还或多或少地隐在背景中，我们注意得更多的是运动、转变和联系，而不是什么在运动、转变和联系。〔见《马克思恩格斯全集》中文版第19卷第219页〕","language":"中文","translation":false},{"id":"socialism-9-23","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":23,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“这首先是自然科学和历史研究的任务；而这些科学部门，由于十分明显的原因，在古典时代的希腊人那里只占有从属的地位，因为他们首先必须搜集材料。”——在这一句之后作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-24","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":24,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"只有当自然和历史的材料搜集到一定程度以后，才能进行批判的分析和比较，并相应地进行纲、目和种的划分。〔见《马克思恩格斯全集》中文版第19卷第220页〕","language":"中文","translation":false},{"id":"socialism-9-25","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":25,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“自然界是检验辩证法的试金石，而且我们必须说，现代自然科学为这种检验提供了极其丰富的、与日俱增的材料，并从而证明了，自然界的一切归根到底是辩证地而不是形而上学地发生的。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-26","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":26,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"自然界是检验辩证法的试金石，而且我们必须说，现代自然科学为这种检验提供了极其丰富的、与日俱增的材料，并从而证明了，自然界的一切归根到底是辩证地而不是形而上学地发生的；自然界不是循着一个永远一样的不断重复的园圈运动，而是经历着实在的历史。这里首先就应当指出达尔文，他极其有力地打击了形而上学的自然观，因为他证明了今天的整个有机界，植物和动物，因而也包括人类在内，都是延续了几百万年的发展过程的产物。〔见《马克思恩格斯全集》中文版第19卷第222页〕","language":"中文","translation":false},{"id":"socialism-9-27","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":27,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“至于黑格尔没有解决这个任务，在这里是无关紧要的。他的划时代的功绩是在于提出了这个任务。”——对这句话作了如下的修改：］","language":"中文","translation":false},{"id":"socialism-9-28","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":28,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"至于黑格尔的体系没有解决它给自己提出的这个任务，在这里是无关紧要的；它的划时代的功绩是在于它提出了这个任务。〔见《马克思恩格斯全集》中文版第19卷第223页〕","language":"中文","translation":false},{"id":"socialism-9-29","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":29,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“新的事实迫使人们对以往的全部历史作一番新的研究，结果发现：以往的全部历史，都是阶级斗争的历史；这些互相斗争的社会阶级在任何时候都是生产关系和交换关系的产物，一句话，都是自己时代的经济关系的产物；因而每一时代的社会经济结构形成现实基础，每一个历史时期由法律设施和政治设施以及宗教的、哲学的和其他的观点所构成的全部上层建筑，归根到底都是应由这个基础来说明的。这样一来，唯心主义从它的最后的避难所中，从历史观中被驱逐出来了，唯物主义历史观被提出来了，用人们的存在说明他们的意识而不是象以往那样用人们的意识说明他们的存在这样一条道路已经找到了。","language":"中文","translation":false},{"id":"socialism-9-30","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":30,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"可是以往的社会主义同这种唯物主义历史观是不相容的，正如法国唯物主义的自然观同辩证法和近代自然科学不相容一样。以往的社会主义固然批判过现存的资本主义生产方式及其后果，但是不能说明这个生产方式，因而也就不能对付这个生产方式：它只能简单地把它当做坏东西抛弃掉。”——对这两段话作了如下的补充和修改：］","language":"中文","translation":false},{"id":"socialism-9-31","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":31,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"新的事实迫使人们对以往的全部历史作一番新的研究，结果发现：以往的全部历史，除原始状态外，都是阶级斗争的历史；这些互相斗争的社会阶级在任何时候都是生产关系和交换关系的产物，一句话，都是自己时代的经济关系的产物；因而每一时代的社会经济结构形成现实基础，每一个历史时期由法律设施和政治设施以及宗教的、哲学的和其他的观点所构成的全部上层建筑，归根到底都是应由这个基础来说明的。黑格尔把历史观从形而上学中解放了出来，使它成为辩证的，可是他的历史观本质上是唯心主义的。现在，唯心主义从它的最后的避难所中，从历史观中被驱逐出来了，唯物主义历史观被提出来了，用人们的存在说明他们的意识而不是象以往那样用人们的意识说明他们的存在这样一条道路已经找到了。","language":"中文","translation":false},{"id":"socialism-9-32","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":32,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"因此，社会主义现在已经不再被看做某个天才头脑的偶然发现，而被看做两个历史地产生的阶级无产阶级和资产阶级间斗争的必然产物。它的任务不再是想出一个尽可能完善的社会制度，而是研究必然产生这两个阶级及其相互斗争的那种历史的经济的过程；并在由此造成的经济状况中找出解决冲突的手段。可是以往的社会主义同这种唯物主义历史观是不相容的，正如法国唯物主义的自然观同辩证法和近代自然科学不相容一样。以往的社会主义固然批判过现存的资本主义生产方式及其后果，但是它不能说明这个生产方式，因而也就不能对付这个生产方式；它只能简单地把它当做坏东西抛弃掉。它愈是义愤填膺地反对这种生产方式必然产生的对工人阶级的剥削，就愈是不能明白指出这种剥削在哪里和怎样发生。〔见《马克思恩格斯全集》中文版第19卷第225—226页〕","language":"中文","translation":false},{"id":"socialism-9-33","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":33,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“富有和贫穷的对立并没有在普遍的幸福中得到解决，反而由于沟通这种对立的行会特权和其他特权的废除，由于缓和这种对立的教会慈善设施的取消而更加尖锐化了；工业在资本主义基础上的迅速发展，使劳动群众的贫穷和困苦成了社会的生存条件。”——对这段话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-34","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":34,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"富有和贫穷的对立并没有在普遍的幸福中得到解决，反而由于沟通这种对立的行会特权和其他特权的废除，由于缓和这种对立的教会慈善设施的取消而更加尖锐化了；现在已经实现的脱离封建桎梏的“财产自由”，对小资产者和小农说来，就是把他们的被大资本和大地产的强大竞争所压垮的小财产出卖给这些大财主的自由，于是这种“自由”对小资产者和小农说来就变成了失去财产的自由；工业在资本主义基础上的迅速发展，使劳动群众的贫穷和困苦成了社会的生存条件。现金交易，如卡莱尔所说的，日益成为社会的唯一纽带。[539]〔见《马克思恩格斯全集》中文版第19卷第208页〕","language":"中文","translation":false},{"id":"socialism-9-35","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":35,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“但是，一方面，只有大工业才能发展那些使生产方式的变革成为绝对必要的冲突——不仅是大工业所产生的各个阶级之间的冲突，而且是它所产生的生产力和交换形式本身之间的冲突；另一方面，大工业又正是通过这些巨大的生产力来发展解决这些冲突所必需的手段。”——对这段话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-36","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":36,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"但是，一方面，只有大工业才能发展那些使生产方式的变革和生产方式的资本主义性质的消灭成为绝对必要的冲突——不仅是大工业所产生的各个阶级之间的冲突，而且是它所产生的生产力和交换形式本身之间的冲突；另一方面，大工业又正是通过这些巨大的生产力来发展解决这些冲突所必需的手段。〔见《马克思恩格斯全集》中文版第19卷第209页〕","language":"中文","translation":false},{"id":"socialism-9-37","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":37,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“虽然巴黎的无财产的群众在恐怖时代曾有一瞬间夺得了统治权，但是他们只是以此证明了，他们的统治在当时的条件下是不可能的。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-38","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":38,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"虽然巴黎的无财产的群众在恐怖时代曾有一瞬间夺得了统治权，从而能够引导资产阶级革命（甚至是反对资产阶级的）达到胜利，但是他们只是以此证明了，他们的统治在当时的条件下是不可能持久的。〔见《马克思恩格斯全集》中文版第19卷第209页〕","language":"中文","translation":false},{"id":"socialism-9-39","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":39,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“圣西门在《日内瓦书信》中已经提出这样一个论点：‘一切人都应当劳动’。”——在这段话之前加了一段话：］","language":"中文","translation":false},{"id":"socialism-9-40","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":40,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"圣西门是法国大革命的产儿，他在革命爆发时还不到三十岁。这次革命，是第三等级即从事生产和贸易的多数国民对以前享有特权的游手好闲的等级即贵族和僧侣的胜利。但是，很快就暴露出，第三等级的胜利只是这个等级中的一小部分人的胜利，是第三等级中享有社会特权的阶层即资产阶级夺得政治权力。而且这部分资产阶级还在革命过程中就迅速地发展起来了，这是因为它通过没收后加以拍卖的贵族和教会的地产进行了投机，同时又以承办军用品欺骗了国家。正是这些骗子的统治在督政府时代使法国和革命濒于复灭，从而使拿破仑得到举行政变的借口。因此，在圣西门的头脑中，第三等级和特权等级之间的对立就采取了“劳动者”和“游手好闲者”之间的对立的形式。游手好闲者不仅是指旧时的特权分子，而且也包括一切不参加生产和贸易而靠租息为生的人。而“劳动者”不仅是指雇佣工人，而且也包括厂主、商人和银行家。游手好闲者失去了精神领导和政治统治的能力，这已经是确定无疑的，而且由革命最终证实了。至于无财产者没有这种能力，在圣西门看来，这已由恐怖时代的经验所证明。那末，应当是谁来领导和统治呢？按照圣西门的意见，应当是科学和工业，它们两者由一种新的宗教纽带，即必然是神秘的和等级森严的“新基督教”结合起来，而这种纽带的使命就是恢复从宗教改革时起被破坏了的宗教观点的统一。可是，科学就是学者，而工业首先就是积极的资产者，厂主、商人、银行家。这些资产者固然应当成为一种公众的官吏、社会所信托的人，但是对工人还应当保持发号施令的和享有经济特权的地位。至于银行家，那末正是他们应当担负起通过调节信用来调节整个社会生产的使命。——这样的见解是完全适应于大工业以及资产阶级和无产阶级的对立在法国还只是刚刚产生的那个时代的。但是，圣西门特别强调的是：他随时随地都首先关心“人数最多和最贫穷的阶级”（《la classe la plus nombreuse et la plus pauvre》）的命运。[540]〔见《马克思恩格斯全集》中文版第19卷第210—211页〕","language":"中文","translation":false},{"id":"socialism-9-41","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":41,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“但是，了解到法国革命是贵族、市民等级和无财产者之间的阶级斗争，这在1802年是极为天才的发现。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-42","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":42,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"但是，了解到法国革命是阶级斗争，并且不仅是贵族和市民等级之间的、而且是贵族、市民等级和无财产者之间的阶级斗争，这在1802年是极为天才的发现。〔见《马克思恩格斯全集》中文版第19卷第212页〕","language":"中文","translation":false},{"id":"socialism-9-43","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":43,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“他把社会历史到目前为止的全部历程分为四个发展阶段：蒙昧、宗法、野蛮和文明。最后一个阶段就相当于现在所谓的资产阶级社会”。——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-44","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":44,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"他把社会历史到目前为止的全部历程分为四个发展阶段：蒙昧、宗法、野蛮和文明。最后一个阶段就相当于现在所谓的资产阶级社会，即从十六世纪发展起来的社会制度。〔见《马克思恩格斯全集》中文版第19卷第213页〕","language":"中文","translation":false},{"id":"socialism-9-45","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":45,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“但是就在那时它已经产生了惊人的社会恶果：无家可归的人挤在大城市的贫民窟里；一切传统习惯的约束、宗法制从属关系、家庭都解体了；劳动时间、特别是女工和童工的劳动时间延长到可怕的程度；突然被抛到一个全新的环境中的劳动阶级大批地堕落了。”——对这段话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-46","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":46,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"但是就在那时它已经产生了惊人的社会恶果：无家可归的人挤在大城市的贫民窟里；一切传统习惯的约束、宗法制从属关系、家庭都解体了；劳动时间、特别是女工和童工的劳动时间延长到可怕的程度；突然被抛到一个全新的环境中（从乡村到城市，从农业到工业，从稳定的生活条件转到天天都在变化的、毫无保障的生活条件）的劳动阶级大批地堕落了。〔见《马克思恩格斯全集》中文版第19卷第214页〕","language":"中文","translation":false},{"id":"socialism-9-47","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":47,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［在引自欧文著作的第三段引文的结尾加了如下的附注：］","language":"中文","translation":false},{"id":"socialism-9-48","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":48,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"摘自《头脑和实践中的革命》——给一切“欧洲红色共和党人、共产主义者和社会主义者”、1848年的法国临时政府，以及“维多利亚女王和她的负责顾问”。〔见《马克思恩格斯全集》中文版第19卷第216页〕","language":"中文","translation":false},{"id":"socialism-9-49","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":49,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“但是，在以自发的社会内部分工作为生产的基本形式的地方，这种分工就使产品带有商品的形式，商品的相互交换，即买和卖，就使个体生产者有可能满足自己的各式各样的需要。”——对这段话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-50","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":50,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"但是，在以自发的、无计划地逐渐产生的社会内部分工作为生产的基本形式的地方，这种分工就使产品带有商品的形式，商品的相互交换，即买和卖，就使个体生产者有可能满足自己的各式各样的需要。〔见《马克思恩格斯全集》中文版第19卷第230页〕","language":"中文","translation":false},{"id":"socialism-9-51","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":51,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“因此，交换是有限的，市场是狭小的，生产方式是稳定的，地方和外界是隔绝的，地方内部是团结的；农村中有马尔克，城市中有行会。”——对其中的“马尔克”一词加了如下的附注：］","language":"中文","translation":false},{"id":"socialism-9-52","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":52,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"见书末的附录［注：附录是指恩格斯的著作《马尔克》，见《马克思恩格斯全集》中文版第19卷第351—369页。——译者注］。〔见《马克思恩格斯全集》中文版第19卷第234页〕","language":"中文","translation":false},{"id":"socialism-9-53","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":53,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“在一定的发展阶段上，这种形式也嫌不够了：资本主义社会的正式代表——国家不得不承担起对生产的领导。”——对这段话作了如下的修改和补充：］","language":"中文","translation":false},{"id":"socialism-9-54","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":54,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"在一定的发展阶段上，这种形式也嫌不够了；国内同一工业部门的大生产者联合为一个“托拉斯”，即一个以调节生产为目的的联盟；他们规定应该生产的总产量，在他们中间加以分配，并且强制实行预先规定的出售价格。但是，这种托拉斯一遇到不景气的时候大部分就陷于瓦解，正因为如此，它们就趋向于更加集中的社会化：整个工业部门变为一个唯一的庞大的股份公司，国内的竞争让位于这一个公司在国内的垄断；例如还在1890年，英国的制碱业就发生了这种情形，现在，这一行业在所有四十八个大工厂合并以后就转到了一个唯一的、统一领导的、拥有一亿两千万马克资本的公司手中了。","language":"中文","translation":false},{"id":"socialism-9-55","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":55,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"在托拉斯中，自由竞争转为垄断，而资本主义社会的无计划生产向行将到来的社会主义社会的计划生产投降。当然，这首先还是对资本家有利的。但是，在这里剥削变得这样明显，以致它必然要被消灭。任何一个民族都不会容忍由托拉斯领导的生产，不会容忍由一小撮专靠剪息票为生的人对全社会进行的如此露骨的剥削。","language":"中文","translation":false},{"id":"socialism-9-56","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":56,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"无论在任何情况下，无论有或者没有托拉斯，资本主义社会的正式代表——国家终究不得不承担起对生产的领导。〔见《马克思恩格斯全集》中文版第19卷第238—239页〕","language":"中文","translation":false},{"id":"socialism-9-57","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":57,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“否则，皇家海外贸易公司、皇家陶磁厂，甚至陆军被服厂，也都是社会主义的设施了。”——对这句话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-58","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":58,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"否则，皇家海外贸易公司、皇家陶磁厂，甚至陆军被服厂，以致在三十年代弗里德里希－威廉三世时期由一个聪明人十分严肃地建议过的妓院国营，也都是社会主义的设施了。〔见《马克思恩格斯全集》中文版第19卷第239页〕","language":"中文","translation":false},{"id":"socialism-9-59","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":59,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［在提到“股份公司”的三个地方，加上了“托拉斯”或“和托拉斯”。］〔见《马克思恩格斯全集》中文版第19卷第240页〕。","language":"中文","translation":false},{"id":"socialism-9-60","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":60,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［“但是这并不妨碍阶级的这种划分曾经通过暴力和掠夺、狡诈和欺骗来实现，这也不妨碍统治阶级一旦掌握政权就牺牲劳动阶级来巩固自己的统治，并把对社会的领导变成对群众的剥削。”——对这段话作了如下的补充：］","language":"中文","translation":false},{"id":"socialism-9-61","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":61,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"但是这并不妨碍阶级的这种划分曾经通过暴力和掠夺、狡诈和欺骗来实现，这也不妨碍统治阶级一旦掌握政权就牺牲劳动阶级来巩固自己的统治，并把对社会的领导变成对群众的加紧剥削。〔见《马克思恩格斯全集》中文版第19卷第243页〕","language":"中文","translation":false},{"id":"socialism-9-62","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":62,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"［在本章最后一段的前面，补充了如下的概述：］ 最后，我们把上述的发展进程简单地概述如下：","language":"中文","translation":false},{"id":"socialism-9-63","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":63,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"一、中世纪社会：个体的小生产。生产资料是供个人使用的，因而是原始的、笨拙的、小的、效能很低的。生产或者是为了生产者本身的直接消费，或者是为了他的封建领主的直接消费。只有在生产的东西除了满足这些消费以外还有剩余的时候，这种剩余才拿去出卖和进行交换：所以商品生产刚刚处于形成过程中；但是这时它本身已经包含着社会生产的无政府状态的萌芽。","language":"中文","translation":false},{"id":"socialism-9-64","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":64,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"二、资本主义革命：起初是工业通过简单协作和工场手工业实现的变革。先前分散的生产资料集中到大作坊中，因而它们就由个人的生产资料转变为社会化的生产资料，这种转变总的说来是没有触及交换形式的。旧的占有形式仍然起作用。资本家出现了：他是生产资料的所有者，当然就占有产品并把它们变为商品。生产已经成为社会的活动；而交换以及和它相伴随的占有，仍旧是个体的活动，单个人的活动：社会产品被个别资本家所占有。这就是产生现代社会借以运动并在大工业中表现得特别明显的一切矛盾的基本矛盾。","language":"中文","translation":false},{"id":"socialism-9-65","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":65,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"（ａ）生产者和生产资料分离。工人注定要终身从事雇佣劳动。无产阶级和资产阶级相对立。","language":"中文","translation":false},{"id":"socialism-9-66","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":66,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"（ｂ）支配商品生产的规律日益显露出来，它们的作用日益加强。竞争不可遏止。个别工厂中的社会化组织和整个生产中的社会无政府状态相矛盾。","language":"中文","translation":false},{"id":"socialism-9-67","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":67,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"（ｃ）一方面是机器的改进，这种改进由于竞争而变成每个厂主必须遵守的强制性法令，同时就使工人遭到不断的解雇：产生了产业后备军。另一方面是生产的无限扩张，这也成了每个厂主必须遵守的强制性的竞争规律。这两方面造成了生产力的空前发展、供过于求、生产过剩、市场盈溢、十年一次的危机、恶性循环：这里是生产资料和产品过剩，那里是没有工作和没有生活资料的工人过剩；但是，生产和社会福利的这两个杠杆不能结合起来，因为生产力和产品要不先转变为资本，资本主义的生产形式就不允许生产力发挥作用和产品进行流通，而阻碍这种转变的正是生产力和产品的过剩。这种矛盾发展到荒谬的程度：生产方式起来反对交换形式。资产阶级已经暴露出自己无能继续管理自己的社会生产力。","language":"中文","translation":false},{"id":"socialism-9-68","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":68,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"（ｄ）资本家本身不得不部分地承认生产力的社会性。大规模的生产机构和交通机构起初由股份公司占有，后来由托拉斯占有，然后又由国家占有。资产阶级表明自己已成为多余的阶级；它的全部社会职能现在由雇佣的职员来执行了。","language":"中文","translation":false},{"id":"socialism-9-69","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":69,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"三、无产阶级革命，矛盾的解决：无产阶级将取得社会权力，并且利用这个权力把脱离资产阶级掌握的社会化生产资料变为公共财产。通过这个行动，无产阶级使生产资料摆脱了它们迄今具有的资本属性，给它们的社会性以充分发展的自由。从此按照预定计划进行的社会生产就成为可能的了。生产的发展使不同社会阶级的继续存在成为时代的错误。随着社会生产的无政府状态的消失，国家的政治权威也将消失。人终于成为自己的社会结合的主人，从而也就成为自然界的主人，成为自己本身的主人——自由的人。〔见《马克思恩格斯全集》中文版第19卷第245—247页〕","language":"中文","translation":false},{"id":"socialism-9-70","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":70,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"[538] 恩格斯在把《反杜林论》的三章改写为《社会主义从空想到科学的发展》这本小册子时，对原文作了一系列补充和修改。恩格斯认为这些补充中有一部分必须在《反杜林论》再版时列入该书（见本卷第12页）。下面所引的这些补充，是恩格斯在准备小册子的德文第1版（1882年）和德文增订第4版（1891年）时所作，但恩格斯本人并没有把这些补充列入他生前所出的《反杜林论》各版。——第696页。","language":"中文","translation":false},{"id":"socialism-9-71","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":71,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"[539] 托·卡莱尔《过去和现在》1843年伦敦版第198页（Th．Carlyle．《Past and Present》．London，1843，p．198）。文中所提到的卡莱尔的言论，恩格斯在他的《英国状况。评托马斯·卡莱尔的〈过去和现在〉》一文中引用过（见《马克思恩格斯全集》中文版第1卷第635页）。——第703页。","language":"中文","translation":false},{"id":"socialism-9-72","author":"恩格斯","title":"社会主义从空想到科学的发展","location":"恩格斯在《社会主义从空想到科学的发展》这本小册子中对《反杜林论》正文所作的补充和修改","page":9,"paragraph":72,"url":"https://www.marxists.org/chinese/engels/1880/08.htm","text":"[540] 圣西门关于社会的目的应该是改善人数最多和最贫穷的阶级的命运的思想，在他的最后一部著作《新基督教》（《Nouveau Christianisme》）中表现得最明显。该书第一版于1825年在巴黎匿名出版。——第705页。","language":"中文","translation":false},{"id":"family-1-1","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"中文马克思主义文库 -> 恩格斯","language":"中文","translation":false},{"id":"family-1-2","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"家庭、私有制和国家的起源","language":"中文","translation":false},{"id":"family-1-3","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"就路易斯·亨·摩尔根的研究成果而作","language":"中文","translation":false},{"id":"family-1-4","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"以下各章，在某种程度上是实现遗愿。不是别人，正是卡尔·马克思曾打算联系他的——在某种限度内我可以说是我们两人的——唯物主义的历史研究所得出的结论来阐述摩尔根的研究成果，并且只是这样来阐明这些成果的全部意义。原来，摩尔根在美国，以他自己的方式，重新发现了40年前马克思所发现的唯物主义历史观，并且以此为指导，在把野蛮时代和文明时代加以对比的时候，在主要点上得出了与马克思相同的结果。正如德国的职业经济学家多年来热心地抄袭《资本论》同时又顽强地抹煞它一样，英国“史前史”科学的代表对摩尔根的《古代社会》[1]，也用了同样的办法。我这本书，只能稍稍补偿我的亡友未能完成的工作。不过，我手中有他写在摩尔根一书的详细摘要[2]中的批语，这些批语我在本书中有关的地方就加以引用。","language":"中文","translation":false},{"id":"family-1-5","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"根据唯物主义观点，历史中的决定性因素，归根结蒂是直接生活的生产和再生产。但是，生产本身又有两种。一方面是生活资料即食物、衣服、住房以及为此所必需的工具的生产；另一方面是人自身的生产，即种的蕃衍。一定历史时代和一定地区内的人们生活于其下的社会制度，受着两种生产的制约：一方面受劳动的发展阶段的制约，另一方面受家庭的发展阶段的制约。劳动越不发展，劳动产品的数量、从而社会的财富越受限制，社会制度就越在较大程度上受血族关系的支配。然而，在以血族关系为基础的这种社会结构中，劳动生产率日益发展起来；与此同时，私有制和交换、财产差别、使用他人劳动力的可能性，从而阶级对立的基础等等新的社会成分，也日益发展起来；这些新的社会成分在几个世代中竭力使旧的社会制度适应新的条件，直到两者的不相容性最后导致一个彻底的变革为止。以血族团体为基础的旧社会，由于新形成的各社会阶级的冲突而被炸毁；代之而起的是组成为国家的新社会，而国家的基层单位已经不是血族团体，而是地区团体了。在这种社会中，家庭制度完全受所有制的支配，阶级对立和阶级斗争从此自由开展起来，这种阶级对立和阶级斗争构成了直到今日的全部成文史的内容。","language":"中文","translation":false},{"id":"family-1-6","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根的伟大功绩，就在于他在主要特点上发现和恢复了我们成文史的这种史前的基础，并且在北美印第安人的血族团体中找到了一把解开希腊、罗马和德意志上古史上那些极为重要而至今尚未解决的哑谜的钥匙。而他的著作也并非一日之功。他研究自己所得的材料，到完全掌握为止，前后大约有40年。然而也正因为如此，他这本书才成为今日划时代的少数著作之一。","language":"中文","translation":false},{"id":"family-1-7","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在后面的叙述中，读者大体上很容易辨别出来，哪些是属于摩尔根的，哪些是我补充的。在关于希腊和罗马历史的章节中，我没有局限于摩尔根的例证，而是补充了我所掌握的材料。关于克尔特人和德意志人的章节，基本上是属于我的；在这里，摩尔根所掌握的差不多只是第二手的材料，而关于德意志人的章节——除了塔西佗以外——还只是弗里曼先生的不高明的自由主义的赝品[3]。经济方面的论证，对摩尔根的目的来说已经很充分了，对我的目的来说就完全不够，所以我把它全部重新改写过了。最后，凡是没有明确引证摩尔根而作出的结论，当然都由我来负责。","language":"中文","translation":false},{"id":"family-1-8","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"写于1884年3月底－5月26日 原文是德文","language":"中文","translation":false},{"id":"family-1-9","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"载于1884年在苏黎世出版的 选自《马克思恩格斯全集》《家庭、私有制和国家的起源》 第21卷第29－31页一书","language":"中文","translation":false},{"id":"family-1-10","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"本书以前各版，印数虽多，但在差不多半年以前就脱销了，出版者[4]早就请我准备新版。更紧迫的工作一直拖住我，使我不能做这件事。自本书初版问世以来，已经有七年了；在这几年间，对于原始家庭形式的认识，已经获得了很大的进展。因此，在这里必须用心地加以修订和补充；加之这次文本的排印预定要铸成铅版，这将使我在相当时期内无法作进一步的修改。[5]","language":"中文","translation":false},{"id":"family-1-11","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"因此，我仔细地校阅了全文，并作了许多补充，我希望在这些补充中恰如其分地照顾到了今天的科学状况。其次，在这篇序言里，我将把自巴霍芬至摩尔根对于家庭史的观点的发展，作一简短的评述；我之所以要这样做，主要是因为带有沙文主义情绪的英国史前史学派，仍然尽一切可能闭口不提摩尔根的发现在原始历史观中所引起的革命，同时却丝毫不客气地把摩尔根所得的成果，掠为己有。而在其他国家，也间或有人非常热中于效尤英国。","language":"中文","translation":false},{"id":"family-1-12","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我的这本书已被译成了各种外文。最先译成意大利文：《家庭、私有制和国家的起源》，帕斯夸勒·马尔提涅蒂译，并经作者审阅，1885年贝内文托版。后来译成罗马尼亚文：《家庭、私有制和国家的起源》，若安·纳杰日杰译，载于1885年9月至1886年5月在雅西出版的《现代人》杂志。以后又译成丹麦文：《家庭、私有制和国家的起源》，由格尔松·特里尔1888年在哥本哈根出版；昂利·腊韦从德文本版译成的法文本，正在印刷中。","language":"中文","translation":false},{"id":"family-1-13","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在60年代开始以前，根本谈不到家庭史。历史科学在这一方面还是完全处在摩西五经的影响之下。人们不仅毫无保留地认为那里比任何地方都描写得更为详尽的家长制的家庭形式是最古的形式，而且把它——除一夫多妻制外——跟现代资产阶级的家庭等同起来，这样一来，家庭实际上就根本没有经历过任何历史的发展；至多认为在原始时代可能有过杂乱的性关系的时期。——诚然，除个体婚制之外，一般所知道的还有东方的一夫多妻制及印度——西藏的一妻多夫制；可是，这三种形式并不能按历史的顺序排列起来，它们彼此并立而没有任何相互的联系。至于说在古代历史的个别民族中间，以及至今尚存的若干蒙昧人中间，世系不是依照父亲而是依照母亲计算，因此，女系被认为是唯一有效的；在今天的许多民族中间，某些相当大的集团(那时还没有被详细研究过)内部禁止通婚，而且这种习俗，在各大洲都可见到，——这种种事实诚然已经是众所周知，而且这样的例子搜集得一天比一天多。但是没有人知道应当怎样去处理它们，甚至在爱·伯·泰勒所著的《人类原始历史的研究》(1865年版)一书[6]中，也还是把这些事实简单地看作“奇怪习俗”，而与某些蒙昧人不许用铁器接触燃烧的木头以及类似的宗教上的滑稽怪事相提并论。","language":"中文","translation":false},{"id":"family-1-14","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"家庭史的研究是从1861年，即从巴霍芬的《母权论》[7]的出版开始的。作者在这本书中提出了以下的论点：(1)最初人们实行着毫无限制的性关系，他把这种性关系用了一个不恰当的名词“淫游婚［Haterismus］”来表示；(2)这种关系排除了任何可以确切认知的父亲，因此，世系只能依照女系——依照母权制——计算，古代的一切民族，起初都是如此；(3)因此，妇女作为母亲，作为年轻一代的唯一确切知道的亲长，享有高度的尊敬和威望，据巴霍芬的意见，高度的尊敬和威望上升到了完全的妇女统治(Gynaikokratie)；(4)向一个女子专属于一个男子的个体婚制的过渡，含有对远古宗教戒律的侵犯(就是说，实际上侵犯了其余男子自古享有的可以占有这位女子的权利)，这种侵犯要求由女子暂时有限地献身于外人来赎罪或赎买对这种行为的容忍。","language":"中文","translation":false},{"id":"family-1-15","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"巴霍芬从他极其勤奋地搜集来的无数段古代经典著作中，为这些论点找出了证据。由“淫游婚”到专偶婚的发展，以及由母权制到父权制的发展，据他的意见，——特别是在希腊人中间——是由于宗教观念的进一步发展，由于代表新观念的新神挤入体现旧观念的传统神内部；因此，旧神就越来越被新神排挤到后边去了。所以，照巴霍芬看来，并不是人们的现实生活条件的发展，而是这些条件在这些人们头脑中的宗教反映，引起了男女两性相互的社会地位的历史性的变化。根据这一点，巴霍芬指出，埃斯库罗斯的《奥列斯特》三部曲是用戏剧的形式来描写没落的母权制跟发生于英雄时代并日益获得胜利的父权制之间的斗争。克丽达妮斯特拉为了她的情大亚格斯都士，杀死了她的刚从特洛伊战争归来的丈夫亚加米农；而她和亚加米农所生的儿子奥列斯特又杀死自己的母亲，以报杀父之仇。为此，他受到母权制的凶恶维护者依理逆司神的追究，因为按照母权制，杀母是不可赎的大罪。但是，曾通过自己的传谕者鼓励奥列斯特去做这件事情的阿波罗和被请来当裁判官的雅典娜这两位在这里代表父权制新秩序的神，则庇护奥列斯特：雅典娜听取了双方的申诉。整个争论点集中地表现在奥列斯特与依理逆司神的辩论中。奥列斯特的理由是：克丽达妮斯特拉既杀了自己的丈夫，同时又杀了他的父亲，犯了两重罪。为什么依理逆司神要追究他，而不追究罪行严重得多的她呢？回答是明确的：","language":"中文","translation":false},{"id":"family-1-16","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“她跟她所杀死的男人没有血缘亲属关系。”[8]","language":"中文","translation":false},{"id":"family-1-17","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"杀死一个没有血缘亲属关系的男人，即使他是那个女凶手的丈夫，也是可以赎罪的，是跟依理逆司神毫不相干的；她们的职务只是追究血缘亲属中间的谋杀案件，在这里，按照母权制，杀母是最不可赎的大罪。这时，阿波罗出来作奥列斯特的辩护人；于是雅典娜就把问题提交阿雷奥帕格的法官们——雅典娜的陪审员们——投票表决；主张宣告无罪与主张有罪判刑的票数相等；这时，雅典娜以审判长的资格，给奥列斯特投了一票，宣告他无罪。父权制战胜了母权制；“幼辈的神”(依理逆司神自己这样称呼他们)战胜了依理逆司神，后者终于也同意担任新的职务，转而为新的秩序服务了。","language":"中文","translation":false},{"id":"family-1-18","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"对《奥列斯特》三部曲的这个新的但完全正确的解释，是巴霍芬全书中最美好精彩的地方之一，但它同时证明，巴霍芬至少是像当年的埃斯库罗斯一样地相信依理逆司神、阿波罗神及雅典娜神；也就是说，他相信这些神在希腊的英雄时代创造了用父权制推翻母权制的奇迹。显然，这种认为宗教是世界历史的决定性杠杆的观点，归根结蒂必然导致纯粹的神秘主义。所以，仔细研究巴霍芬的这部四开本的大部头著作，乃是一件吃力而绝非始终值得的事情。不过，所有这一切并不降低他开辟道路的功绩；他头一个抛弃了关于性关系杂乱的毫无所知的原始状态的空谈，而证明古代经典著作向我们提出了大量的证据，这些证据表明，在希腊人及亚洲人那里，在个体婚制之前，确实存在过这样的状态，即不但一个男子与几个女子发生性的关系，而且一个女子也与几个男子发生性的关系，都不违反习俗；他证明，这种习俗在消失的时候留下了一种痕迹，即妇女必须在一定限度内献身于外人，以赎买实行个体婚的权利；因此，世系最初只能依女系即从母亲到母亲来计算；女系的这种唯一有效性，在父亲的身分已经确定或至少已被承认的个体婚制时代，还保存了很久；最后，母亲作为自己子女的唯一确实可靠的亲长的这种最初的地位，便为她们、从而也为所有妇女保证了一种自此以后她们再也没有占据过的崇高的社会地位。诚然，巴霍芬并没有这样明确地表述这些论点，——他的神秘主义的观点妨碍他这样做。但是他证明了这些论点，而这在1861年是一个完全的革命。","language":"中文","translation":false},{"id":"family-1-19","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"巴霍芬的这部四开本的大部头著作，是用德文写的，即用那时对现代家庭的史前史最不感兴趣的民族的语言写的。因此，他的这本书一直湮没无闻。1865年在同一领域里出现的巴霍芬的直接后继人，甚至没有听说过他。","language":"中文","translation":false},{"id":"family-1-20","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这个后继人，就是约·弗·麦克伦南，他和他的先驱者正好相反。在这里我们所看到的，不是天才的神秘主义者，而是一个枯燥无味的法学家；不是诗人的才气横溢的幻想，而是出庭的辩护士的貌似有理的推论。麦克伦南在古代及近代的许多蒙昧民族、野蛮民族、以至文明民族中间，发现了这样一种结婚形式，即新郎必须一个人或者与他的朋友们一起假装用暴力把新娘从她的亲属手里抢过来。这个习俗，应当是较早的一种习俗的遗迹，那时一个部落的男子确实是用暴力到外边从别的部落为自己抢劫妻子。那么这种“抢劫婚姻”是怎样发生的呢？当男子在本部落内可以找到足够的妻子时，是没有任何理由这样做的。不过，我们也常常发现，在不发达的民族中间，有一些集团(在1865年时，还常常把这种集团与部落本身等同起来)禁止内部通婚，因此，男子不得不在本集团以外去娶妻，女子也不得不在本集团以外去找丈夫；而另外有些民族，却又有这样一种习俗，即某一集团的男子只能在自己本集团以内娶妻。麦克伦南把第一种集团叫作外婚制集团，把第二种集团叫作内婚制集团，并且直截了当地虚构出外婚制“部落”与内婚制“部落”的僵硬的对立。虽然他自己对外婚制的研究使他迎面就碰到这样一件事实，即这种对立如果不是在大多数场合，以至一切场合，那么在许多场合都只是存在于他的想象中，可是他仍然把这种对立作为他的整个理论的基础。根据这一说法，外婚制的部落只能从别的部落娶妻，而这在与蒙昧时代相适应的各部落之间战争不断的状态下，只有用抢劫的办法才能做到。","language":"中文","translation":false},{"id":"family-1-21","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"麦克伦南接着问道：这种外婚制的习俗是从哪里来的呢？他认为血缘亲属关系的观念和血亲婚配的观念与这毫不相干，因为这只是在很久以后才发展起来的。但在蒙昧人中间广泛流行的女孩出生后立即杀死的习俗，则可能有关系。他说，这种习俗使各个部落内发生男子过剩，其直接后果便必然是几个男子共有一个妻子，即一妻多夫制；由此又造成：人们只知道谁是孩子的母亲而不知道谁是孩子的父亲，于是，亲属关系只能依照女系，而不能依照男系计算，这就是母权制。部落内部妇女缺少——这缺少虽然由一妻多夫制所缓和，但并未消除——的第二个后果，便是一贯地用暴力抢劫别的部落里的妇女。","language":"中文","translation":false},{"id":"family-1-22","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“外婚制与一妻多夫制既是起于同一原因——两性数目的不等，那么我们就应当认为，一切外婚制的种族起初都是一妻多夫制的……因此，我们应当认为不容争辩的是，在外婚制的种族中间，最初的亲属制度乃是仅由母亲方面来认知血缘关系的制度。”(麦克伦南《古代史研究》1886年版。《原始婚姻》第124页)4","language":"中文","translation":false},{"id":"family-1-23","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"麦克伦南的功绩就在于他指出了他所谓的外婚制的到处流行及其重大意义。他根本没有发现外婚制集团存在的事实，也完全没有理解这个事实。且不说许多观察者的更早的个别记载——这些正是麦克伦南的材料来源，莱瑟姆就精确而可靠地叙述过印度马加尔人5的外婚制度(《记述民族学》1859年版)，并且说，这种制度曾普遍流行，在各大洲都可见到，——这个地方麦克伦南自己就引用过。而且，我们的摩尔根还在1847年他的关于易洛魁人的通信(发表于《美国评论》杂志上)中，以及1851年在《易洛魁联盟》一书6中也证明了在这个民族集团里存在着这种制度，并正确地记述了它，可是麦克伦南的辩护士般的头脑，如我们将要看到的，在这个问题上，造成了比巴霍芬的神秘主义幻想在母权制方面所造成的更大得多的混乱。麦克伦南的又一个功绩，就在于他认定母权制的世系制度是最初的制度，虽然在这一点上，像他本人后来所承认的那样，巴霍芬已比他先说过了。但即使是在这里，他也没有把问题弄清楚；他经常说到“只依照女系计算的亲属关系”(kinship through females Only)，并且一直把这个对较早发展阶段说来是正确的用语也应用于较后的一些发展阶段，在这些发展阶段上，世系和继承权虽然还是只依照女系计算，但亲属关系也依照男子方面来承认和表示了。这是法学家的局限性，法学家创造了一个固定的法律用语，就继续一成不变地把它应用于早已不再适用的情况。","language":"中文","translation":false},{"id":"family-1-24","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"麦克伦南的理论，虽然好像讲得头头是道，然而即使在作者本人看来，似乎也缺乏牢固的根据。至少他本人注意到“值得注意的是，<假装的>抢劫妇女的形式，正是在男子亲属关系<应该说依照男系计算的世系>占统治地位的民族中间表现得最突出，最明显”(第140页)。","language":"中文","translation":false},{"id":"family-1-25","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“这是一个奇怪的事实，据我们所知，在外婚制与最古的亲属关系形式并存的任何地方，都没有杀婴的习俗。”(第146页)","language":"中文","translation":false},{"id":"family-1-26","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这两点都是事实，是和他的说明方法显然矛盾的，他只能用新的更加混乱的假说来解释。","language":"中文","translation":false},{"id":"family-1-27","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"可是，他的理论在英国仍然得到了很多的支持和响应：在英国，麦克伦南被普遍认为是家庭史的创始者和这个领域的第一个权威。他那外婚制“部落”与内婚制“部落”的对立，虽然人们也认为有个别的例外并加以修改，但依然是占统治地位的观点的公认基础，而且变成了眼罩，使得任何不抱成见的通观这一研究领域、从而取得任何决定性的进步都成为不可能。鉴于在英国，而且别国也仿效英国普遍对麦克伦南的功绩估价过高，我们应当着重指出一个事实，即他那纯粹理解错了的外婚制“部落”与内婚制“部落”的对立所造成的害处，要多于他的研究所带来的益处。","language":"中文","translation":false},{"id":"family-1-28","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"而不久便开始出现越来越多的，无法装进他的理论的小巧框框中去的事实。麦克伦南只知道三种婚姻形式：一夫多妻制，一妻多夫制和个体婚制。但是一当注意力集中到这一点的时候，就发现了越来越多的证据，证明在不发达的各民族中间，存在过一批男子共同占有一批女子的婚姻形式；而拉伯克(《文明的起源》1870年版[9])则认定这种群婚(Communal marriage)是历史的事实。","language":"中文","translation":false},{"id":"family-1-29","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"紧接着，在1871年，摩尔根又提出了新的、在许多方面都是决定性的材料。他确信，易洛魁人所通行的那种特殊的亲属制度，乃是美国的一切土著居民所共有的制度，因此，它流行于整个大陆，虽然它同那里通行的婚姻制度所实际产生的亲属等级是直接矛盾的。他促使美国联邦政府，根据他自己所拟定的问题和表格，了解有关其他各民族的亲属制度的情况，他从答案中发现：(1)美洲印第安人的亲属制度，也流行于亚洲的许多部落，并且以略有改变的形式，流行于非洲及澳洲的许多部落。(2)这种制度，在夏威夷及其他澳洲岛屿上正处于消亡阶段的群婚形式中，找到了完全的说明。(3)但是，在这些岛屿上，与这种婚姻形式并存而流行的亲属制度，则是一种只有用更为原始而如今业已消失的群婚形式才能说明的亲属制度。他把所搜集的材料与他从中得出的结论，一同发表在他的《血亲制度和姻亲制度》(1871年版)[10]一书中，因而把争论转移到更无比广大的领域里来了。他从亲属制度出发，恢复了与之相应的家庭形式，这就开辟了一条新的研究途径及进一步追溯人类史前史的可能。如果这个方法能够通用，麦克伦南的精巧设计就要烟消云散了。","language":"中文","translation":false},{"id":"family-1-30","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"麦克伦南在《原始婚姻》的新版(《古代史研究》1876年版)中起而为自己的理论辩护。他自己只根据假说完全人为地编造出一套家庭史，却要求拉伯克和摩尔根不仅要对他们的每一个论点提出证据，而且要提出只有在苏格兰法庭上才会要求的那种不可争辩的确凿证据。而提出这种要求的同一个人，却根据德意志人中的舅甥之间的密切关系(塔西佗《日耳曼尼亚志》第20章)，根据凯撒关于布列吞人每10个或12个男子有共同的妻子的记述，根据古代著作家关于野蛮人共妻的其他一切记述，毫不犹豫地作出结论说，所有这些民族都盛行过一妻多夫制!这就好像在听这样一位检察官讲话，他在起诉时可以信口开河，然而却要求辩护人每句话都要有最明确的、有法律效力的证据。","language":"中文","translation":false},{"id":"family-1-31","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"他断言群婚是纯粹的想象，这样，他便比巴霍芬落后了许多。他认为，摩尔根所说的亲属制度，乃是纯粹的社交礼仪的规则，并拿印第安人把异族人、白种人也称呼为父亲或兄弟这一事实作为证明。这正如某人因为人们把天主教的教士和修道院女院长也称为父亲和母亲，而修士和修女，甚至共济会会员和英国同业公会会员在庄严的集会上，彼此也用兄弟和姊妹相称，就硬说父母、兄弟、姊妹等称呼是根本毫无意义的称呼一样。总之，麦克伦南的辩护是极端软弱无力的。","language":"中文","translation":false},{"id":"family-1-32","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不过他还有一点没有被攻破。他的全部体系所依据的外婚制“部落”与内婚制“部落”的对立，不仅没有被动摇，而且甚至被公认为全部家庭史的基石。人们承认，麦克伦南试图给这个对立所作的解释是不够有力的，而且跟他自己所举出的一些事实相矛盾。不过这一对立本身，即存在着两种相互排斥的独立自主的部落，其中一种是在本部落以内娶妻，而另一种则绝对禁止这样做，却被认为是不可辩驳的真理。请参看例如日罗－特隆的《家庭的起源》(1874年版)，甚至拉伯克的《文明的起源》(1882年第4版)[11]。","language":"中文","translation":false},{"id":"family-1-33","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根的主要著作《古代社会》(1877年版)[12](本书即以这部著作为基础)，就是针对这一点的。摩尔根在1871年仅仅模糊地推测到的，在这里已经十分明确地发挥出来了。内婚制和外婚制根本不构成对立；外婚制“部落”的存在，直到现在也没有在任何地方找到证明。不过，在群婚还盛行的时代，——群婚完全可能一度到处盛行，——一个部落分为好几个母系血缘亲属集团，即氏族，在氏族内部，严格禁止通婚，因此，某一氏族的男子，虽能在部落以内娶妻，并且照例都是如此，却必须是在氏族以外娶妻。这样，要是氏族是严格外婚制的，那么包括了所有这些氏族的部落，便成了同样严格内婚制的了。这就彻底推翻了麦克伦南人为地编造的理论的最后残余。","language":"中文","translation":false},{"id":"family-1-34","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是摩尔根并不满足于此。美洲印第安人的氏族还帮助他在他所研究的领域内迈出了有决定意义的第二步。他发现，这种按母权制建立的氏族，就是后来按父权制建立的氏族——即我们在古希腊罗马时代文明民族中可以看到的氏族——所由以发展起来的原始形式。希腊的和罗马的氏族，对于迄今所有的历史编纂学家来说都是一个谜，如今可以用印第安人的氏族来说明了，因而也就为全部原始历史找到了一个新的基础。","language":"中文","translation":false},{"id":"family-1-35","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"确定原始的母权制氏族是文明民族的父权制氏族以前的阶段的这个重新发现，对于原始历史所具有的意义，正如达尔文的进化理论对于生物学和马克思的剩余价值理论对于政治经济学的意义一样。它使摩尔根得以首次绘出家庭史的略图；这一略图，在目前已知的资料所容许的限度内，至少把典型的发展阶段大体上初步确定下来了。非常清楚，这样就在原始历史的研究方面开始了一个新时代。母权制氏族成了整个这门科学所围着旋转的轴心；自从它被发现以后，人们才知道，应该朝着什么方向研究和研究什么，以及应该如何去整理所得的结果。因此，现在在这一领域内正取得比摩尔根的著作出版以前更加迅速得多的进步。","language":"中文","translation":false},{"id":"family-1-36","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根的发现，如今也为英国所有的史前史学家所承认，或者更确切些说，所窃取了。但是，他们几乎没有一个人肯公开承认，这一观点上的革命恰恰应该归功于摩尔根。在英国，人们对他的书尽可能保持沉默，而对他本人则只是以宽大地称赞他以前的成绩来敷衍一下；对他的叙述中的细节尽力吹毛求疵，而对他的真正伟大的发现却顽强地闭口不提。《古代社会》的第一版已经脱销；在美国，这类书没有应有的销路；在英国，这本书看来是一贯受到压制；这本划时代的著作的唯一还在出售的版本，就是德文译本。","language":"中文","translation":false},{"id":"family-1-37","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种冷漠态度很难不令人想到是一种共同蓄意采取的沉默抵制行为，尤其是如果考虑到我们那些公认的史前史学家的著作中充满了仅仅是出于客气而作的许多引证，以及其他对同行表示尊敬的证据，就更会使人这样想，——这种冷漠态度的原因何在呢？是不是因为摩尔根是个美国人，而对于英国的史前史学家极其难堪的是，他们尽管在热心地搜集材料方面值得高度赞扬，但是在整理与分析这种材料所必要的一般观点方面，一句话，在他们的思想方面，却求助于两个天才的外国人——巴霍芬和摩尔根呢？要是德国人的话，他们还可以容忍，但是对一个美国人怎能容忍呢？在美国人面前，每个英国人都成了爱国主义者，关于这一点，我在美国看到了许多可笑的例子。7何况麦克伦南可以说是官方任命的英国史前史学派的创始人和领袖；史前史学界在某种程度上有一种规矩，只能以莫大的敬意谈论他那从杀婴经过一妻多夫制、抢劫婚姻到母权制家庭的人工编造的历史理论；对于绝对相互排斥的外婚制“部落”和内婚制“部落”的存在稍有怀疑，便被视为放肆的邪说；这样，把所有这些神圣教条打得粉碎的摩尔根，就是犯了某种渎圣罪。加之，摩尔根在打破这些教条时，又是用一经说出便立即人人明白的方式；因此，一直茫然彷徨于外婚制与内婚制之间的麦克伦南的崇拜者，现在简直要用拳头敲着自己的脑门大叫起来：我们怎么会这样愚蠢，自己没有老早把它发现出来呢!","language":"中文","translation":false},{"id":"family-1-38","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如果说这些罪过还不足以使官方学派非把摩尔根冷漠地撇在一边不可，那么他还有一个实在太过分的地方，就是他不仅用类似傅立叶使用的方式对文明，对商品生产社会，对我们现代社会的基本形式进行了批评，而且还用了卡尔·马克思才能说的话来谈论这一社会的未来的改造。所以，摩尔根就罪有应得，麦克伦南忿然地责难“他根本厌恶历史方法”[13]，而且日内瓦的教授日罗－特隆先生在1884年也重申了这一点。可是要知道，这位日罗－特隆先生在1874年(《家庭的起源》)还是束手无策地徘徊于麦克伦南的外婚制的迷宫中，全仗摩尔根才被解救出来!","language":"中文","translation":false},{"id":"family-1-39","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根在原始历史学上的其他成就，在这里没有考察的必要；在这一方面需要提到的，在本书有关的地方都可以找到。自从摩尔根的主要著作出版以来已经14年了，这14年间，关于人类原始社会史的材料，已经大大丰富起来；除了人类学家、旅行家及职业的史前史学家以外，比较法律学家也参加进来了，他们有的提供了新的材料，有的提出了新的观点。结果，摩尔根有一些假说便被动摇，甚至站不住脚了。不过，新搜集的资料，不论在什么地方，都没有导致必须用其他的观点来代替他的卓越的基本观点。他给原始历史建立的系统，在基本的要点上，今天仍然有效。甚至可以说，越是有人力图隐瞒摩尔根是这一伟大进步的奠基者，他所建立的这个系统就将越来越获得大家的公认。[14]","language":"中文","translation":false},{"id":"family-1-40","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1891年6月16日于伦敦","language":"中文","translation":false},{"id":"family-1-41","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"载于1890－1891年《新时代》 原文是德文","language":"中文","translation":false},{"id":"family-1-42","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"杂志第2卷第41期和1891年 选自《马克思恩格斯全集》在斯图加特出版的《家庭、私有 第22卷第246－259页制和国家的起源》一书","language":"中文","translation":false},{"id":"family-1-43","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"家庭、私有制和国家的起源","language":"中文","translation":false},{"id":"family-1-44","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根是第一个具有专门知识而尝试给人类的史前史建立一个确定的系统的人；他所提出的分期法，在没有大量增加的资料认为需要改变以前，无疑依旧是有效的。","language":"中文","translation":false},{"id":"family-1-45","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在三个主要时代——蒙昧时代、野蛮时代和文明时代中，不消说，他所研究的只是前两个时代以及向第三个时代的过渡。他根据生活资料生产的进步，又把这两个时代中的每一时代分为低级阶段、中级阶段和高级阶段，因为，他说：","language":"中文","translation":false},{"id":"family-1-46","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“这一生产上的技能，对于人类的优越程度和支配自然的程度具有决定的意义；一切生物之中，只有人类达到了几乎绝对控制食物生产的地步。人类进步的一切大的时代，是跟生活来源扩充的各时代多少直接相符合的”8。","language":"中文","translation":false},{"id":"family-1-47","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"家庭的发展与此并行，不过，这一发展对于时期的划分没有提供这样显著的标志罢了。","language":"中文","translation":false},{"id":"family-1-48","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.低级阶段。这是人类的童年。人还住在自己最初居住的地方，即住在热带的或亚热带的森林中。他们至少是部分地住在树上，只有这样才可以说明，为什么他们在大猛兽中间还能生存。他们以果实、坚果、根作为食物；音节清晰的语言的产生是这一时期的主要成就。在有史时期所知道的一切民族中，已经没有一个是处在这种原始状态的了。虽然这一状态大概延续了好几千年之久，但我们却不能根据直接的证据去证明它；不过，我们既然承认人是起源于动物界的，那么，我们就不能不承认这种过渡状态了。","language":"中文","translation":false},{"id":"family-1-49","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.中级阶段。从采用鱼类(我们把虾类、贝壳类及其他水栖动物都算在内)作为食物和使用火开始。这两者是互相联系着的，因为鱼类食物，只有用火才能做成完全可吃的东西。而自从有了这种新的食物以后，人们便不受气候和地域的限制了；他们沿着河流和海岸，甚至在蒙昧状态中也可以散布在大部分地面上。石器时代早期的粗制的、未加磨制的石器，即所谓旧石器时代的石器(这些石器完全属于或大部分都属于这一阶段)遍布于各大洲，就是这种迁徙的证据。新移居的地带，以及不断的活跃的探索欲，加上掌握了摩擦取火的本领，就提供了新的食物，这就是在热灰或烧穴(地灶)中煨烤的淀粉质的根和块茎，以及随着最初武器即棍棒和标枪的发明而间或取得的附加食物——猎物。像书籍中所描写的纯粹的打猎民族，即专靠打猎为生的民族，从未有过；靠猎物来维持生活，是极其靠不住的。由于食物来源经常没有保证，在这个阶段上大概发生了食人之风，这种风气，此后保持颇久。即在今日，澳大利亚人和许多波利尼西亚人还是处在蒙昧时代的这个中级阶段上。","language":"中文","translation":false},{"id":"family-1-50","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"3.高级阶段。从弓箭的发明开始。由于有了弓箭，猎物便成了通常的食物，而打猎也成了常规的劳动部门之一。弓、弦、箭已经是很复杂的工具，发明这些工具需要有长期积累的经验和较发达的智力，因而也要同时熟悉其他许多发明。如果把已经知道弓箭，但还不知道制陶术(摩尔根认为向野蛮时代过渡就是从制陶术开始)的各民族，彼此对照一下，我们的确就可以看到，已经有定居而成村落的某些萌芽，以及对生活资料生产的某种程度的掌握，如：木制的容器和用具，用韧皮纤维做成的手工织物(没有织机)，用韧皮或芦苇编成的篮子，以及磨制的(新石器时代的)石器。火和石斧通常已经使人能够制造独木舟，有的地方已经使人能够用方木和木板来建筑房屋了。例如，在美洲西北部的印第安人中间，我们就可以看到这一切进步，这些印第安人虽然已经使用弓和箭，但还不知道制陶术。弓箭对于蒙昧时代，正如铁剑对于野蛮时代和火器对于文明时代一样，乃是决定性的武器。","language":"中文","translation":false},{"id":"family-1-51","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.低级阶段。从学会制陶术开始。可以证明，在许多地方，也许是在一切地方，陶器的制造都是由于在编制的或木制的容器上涂上粘土使之能够耐火而产生的。在这样做时，人们不久便发现，成型的粘土不要内部的容器，同样可以使用。","language":"中文","translation":false},{"id":"family-1-52","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在此以前，我们可以很一般地把发展过程看作适用于一定时期的一切民族，不管他们所生活的地域如何。但是，随着野蛮时代的到来，我们达到了这样一个阶段，这时两大陆的自然条件上的差异，就有了意义。野蛮时代的特有的标志，是动物的驯养、繁殖和植物的种植。东大陆，即所谓旧大陆，差不多有着一切适于驯养的动物和除一种以外一切适于种植的谷物；而西大陆，即美洲，在一切适于驯养的哺乳动物中，只有羊驼一种，并且只是在南部某些地方才有；而在一切可种植的谷物中，也只有一种，但是最好的一种，即玉蜀黍。由于自然条件的这种差异，两个半球上的居民，从此以后，便各自循着自己独特的道路发展，而表示各个阶段的界标在两个半球也就各不相同了。","language":"中文","translation":false},{"id":"family-1-53","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.中级阶段。在东大陆，是从驯养家畜开始；在西大陆，是从靠灌溉之助栽培食用植物以及在建筑上使用土坯(即用阳光晒干的砖)和石头开始。","language":"中文","translation":false},{"id":"family-1-54","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们先从西大陆说起，因为在这里，在被欧洲人征服以前，不论什么地方，都还没有越过这个阶段。","language":"中文","translation":false},{"id":"family-1-55","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"处于野蛮时代低级阶段的印第安人(凡是在密西西比河以东看到的都属于这种印第安人)，到他们被发现的时候，已经知道在园圃里种植玉蜀黍、可能还有南瓜、甜瓜及其他园圃植物的某种方法，这些东西构成他们食物的极为重要的部分；他们住在木造的房子里，村落用木栅围起来。西北各部落，特别是住在哥伦比亚河流域的各部落，尚处于蒙昧时代高级阶段，他们既不知道制陶术，也不知道任何植物的种植。反之，新墨西哥的所谓普韦布洛印第安人9，以及墨西哥人、中美洲人和秘鲁人，当他们被征服时，已经处于野蛮时代中级阶段：他们住的房屋是用土坯或石头造成的，类似城堡，并且在人工灌溉的园圃内种植玉蜀黍和其他各种依所住地区和气候而不同的食用植物，这些东西是他们食物的主要来源，他们甚至已经驯养了某几种动物：黑西哥人饲养火鸡及其他禽类，秘鲁人饲养羊驼。而且，他们还知道了金属的加工——唯有铁除外，因此他们还仍然不得不使用石制的武器和工具。西班牙人的征服打断了他们的任何进一步的独立发展。","language":"中文","translation":false},{"id":"family-1-56","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在东大陆，野蛮时代的中级阶段是从驯养供给乳和肉的动物开始的，而植物的种植，在这里似乎直到这一时期的晚期还不为人所知。牲畜的驯养和繁殖以及较大规模的畜群的形成，看来是使雅利安人和闪米特人从其余的野蛮人群中分离出来的原因。在欧亚两洲的雅利安人中间，家畜的名称还是共通的；而栽培植物的名称却几乎完全不同。","language":"中文","translation":false},{"id":"family-1-57","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"畜群的形成，在适于畜牧的地方导致了游牧生活：闪米特人在幼发拉底河和底格里斯河的草原上，雅利安人在印度、以及奥克苏斯河及药杀水、顿河和第聂伯河的草原上。动物的驯养，最初大概是在这种牧区的边缘上实行的。因此，后人便以为游牧民族是起源于这样一些地方，这种地方根本不会是人类的摇篮，相反，对于人类的祖先蒙昧人，甚至对于野蛮时代低级阶段的人，都几乎是不适于居住的。反之，一旦这些处于中级阶段的野蛮人习惯了游牧生活以后，就永远不会想到从水草丰美的沿河平原自愿回到他们的祖先居住过的林区去了。甚至当闪米特人和雅利安人继续被挤向北部和西部的时候，要不是他们已经能够通过谷物的种植在亚洲西部的和欧洲的森林地带这种不大适宜的土壤上养活他们的牲畜，特别是在这里过冬，那他们也是不会移居这里的。十分可能，谷物的种植在这里起初是由牲畜饲料的需要所引起的，只是到了后来，才成为人类食物的重要来源。","language":"中文","translation":false},{"id":"family-1-58","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"雅利安人和闪米特人这两个种族的卓越的发展，或许应归功于他们的丰富的肉乳食物，特别是这种食物对于儿童发育的有利影响。的确，不得不几乎专以植物为食的新墨西哥的普韦布洛印第安人，他们的脑子比那些处于野蛮时代低级阶段而吃肉类和鱼类较多的印第安人的脑子要小些。不管怎样，在这个阶段上，食人之风正在逐渐消失，仅仅当作一种宗教活动或巫术(在这里差不多是一回事)而保存着。","language":"中文","translation":false},{"id":"family-1-59","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"3.高级阶段。从铁矿石的冶炼开始，并由于拼音文字的发明及其应用于文献记录而过渡到文明时代。这一阶段，前面已经说过，只是在东半球才独立经历过，其生产的进步，要比过去一切阶段的总和还要来得丰富。英雄时代的希腊人、罗马建立前不久的各意大利部落、塔西佗时代的德意志人、海盗10时代的诺曼人[15]，都属于这个阶段。","language":"中文","translation":false},{"id":"family-1-60","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"首先，我们在这里初次看到了带有铁铧的用牲畜拉的犁；有犁以后，大规模耕种土地，即田野农业，从而生活资料在当时条件下实际上无限制地增加，便都有可能了；从而也能够清除森林使之变为耕地和牧场了，这一点，如果没有铁斧和铁锹，也不可能大规模进行。但这样一来，人口也开始迅速增长起来，稠密地聚居在不大的地域内。而在田野农业产生以前，除非有极其特殊的条件才能把50万人联合在一个统一的中央领导之下；这样的事大概从来都没有过。","language":"中文","translation":false},{"id":"family-1-61","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"野蛮时代高级阶段的全盛时期，我们在荷马的诗中，特别是在《伊利亚特》中可以看到。发达的铁制工具、风箱、手磨、陶工的辘轳、榨油和酿酒、成为手工艺的发达的金属加工、货车和战车、用方木和木板造船、作为艺术的建筑术的萌芽、由设塔楼和雉堞的城墙围绕起来的城市、荷马的史诗以及全部神话——这就是希腊人由野蛮时代带入文明时代的主要遗产。如果我们把凯撒，甚至塔西佗对日耳曼人的记述11跟这些成就作一比较，便可看出，野蛮时代高级阶段在生产的发展上已取得如何丰富的成就，那时日耳曼人尚处在这个文化阶段的初期，而荷马时代的希腊人，已经准备由这个文化阶段过渡到更高的阶段了。","language":"中文","translation":false},{"id":"family-1-62","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我在这里根据摩尔根的著作描绘的这幅人类经过蒙昧时代和野蛮时代达到文明时代的开端的发展图景，已经包含足够多的新特征了，而尤其重要的是，这些特征都是不可争辩的，因为它们是直接从生产中得来的。不过，这幅图景跟我们此次遨游终了时将展现在我们面前的那幅图景比较起来，就会显得暗淡和可怜；只有在那个时候，才能充分看到从野蛮时代到文明时代的过渡以及两者之间的显著对立。现在我们可以把摩尔根的分期概括如下：蒙昧时代是以获取现成的天然产物为主的时期；人工产品主要是用作获取天然产物的辅助工具。野蛮时代是学会畜牧和农耕的时期，是学会靠人的活动来增加天然产物生产的方法的时期。文明时代是学会对天然产物进一步加工的时期，是真正的工业和艺术的时期。","language":"中文","translation":false},{"id":"family-1-63","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根一生的大部分，是在易洛魁人中间度过的，这种易洛魁人现在还居住在纽约州；他并且被一个易洛魁人部落(塞讷卡人部落)接纳入族。他发现，易洛魁人奉行着一种同他们的实际的家庭关系相矛盾的亲属制度。在易洛魁人中间盛行的，是一种双方可以轻易解除的个体婚姻，摩尔根把它称为“对偶制家庭”。因此，这种夫妻的子女，是众所周知和大家公认的；对谁应该用父亲、母亲、儿子、女儿、兄弟、姊妹等称呼，是不会有疑问的。但是，这些称呼的实际使用，却与此矛盾。易洛魁人的男子，不仅把自己亲生的子女称为自己的儿子和女儿，而且把他兄弟的子女也称为自己的儿子和女儿，而他们都称他为父亲。他把自己姊妹的子女则称为自己的外甥和外甥女，他们称他为舅父。反之，易洛魁人的女子，把自己姊妹的子女和她自己亲生的子女一概都称为自己的儿子和女儿，而他们都称她为母亲。她把自己兄弟的子女则称为自己的内侄和内侄女，她自己被称为他们的姑母。同样，兄弟的子女们互称兄弟姊妹，姊妹的子女们也互称兄弟姊妹。而一个女人的子女和她兄弟的子女，则互称为表兄弟和表姊妹。这并不是一些空洞的名称，而是实际上流行的对血缘亲属关系的亲疏和辈份的观点的表达；这种观点是一种完备地制定了的亲属制度的基础，这种亲属制度可以表达单个人的数百种不同的亲属关系。不仅如此，这种亲属制度不仅在所有美洲印第安人中(直到现在还没有发现过例外)完全有效，而且在印度最古的居民中，在德干的达罗毗荼人部落和印度斯坦的戈拉人部落中，也差不多毫无变更地实行着。南印度的泰米尔人和纽约州的塞讷卡部落的易洛魁人用来表达亲属关系的名称，即使现在，也还有200种以上不同的亲属关系是相同的。所以在印度的这些部落中间，正和在所有美洲印第安人中间一样，从现行家庭形式中产生的亲属关系，也是同亲属制度相矛盾的。","language":"中文","translation":false},{"id":"family-1-64","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"怎样来说明这一点呢？由于亲属关系在一切蒙昧民族和野蛮民族的社会制度中起着决定作用，因此，我们不能只用说空话来抹煞这一如此广泛流行的制度的意义。在美洲普遍流行的制度，在种族全然不同的亚洲各民族中间也存在着，在非洲和澳洲各地也经常可以发现它的多少改变了的形式，——像这样的一种制度，是需要从历史上来说明的，决不能像例如麦克伦南所企图做的那样含糊过去。父亲、子女、兄弟、姊妹等称呼，并不是单纯的荣誉称号，而是代表着完全确定的、异常郑重的相互义务，这些义务的总和构成这些民族的社会制度的实质部分。说明终于找到了。在桑威奇(夏威夷)群岛上，本世纪上半叶还存在着一种家庭形式，这种家庭所产生的父亲和母亲、兄弟和姊妹、儿子和女儿、舅父和姑母、外甥和外甥女、内侄和内侄女，正好同美洲及古印度人的亲属制度所要求的一样。然而，好奇怪!夏威夷群岛上流行的亲属制度，又是同当地事实上存在的家庭形式不相符合的。因为，那里凡是兄弟姊妹的子女，都毫无例外地是兄弟姊妹；他们不仅被看作自己母亲及其姊妹或自己父亲及其兄弟的共同的子女，而且毫无区别地被看作自己双亲的一切兄弟姊妹的共同的子女。由此可见，如果说美洲的亲属制度，是以在美洲已经不存在，而我们在夏威夷确实还找到的比较原始的家庭形式为前提，那么，另一方面，夏威夷的亲属制度却向我们指出了一种更加原始的家庭形式，诚然，这一家庭形式的存在，现在我们在任何地方都不能加以证明，但是它一定是存在过的，否则，就不会产生相应的亲属制度。摩尔根说：","language":"中文","translation":false},{"id":"family-1-65","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“家庭是一个能动的要素；它从来不是静止不动的，而是随着社会从较低阶段向较高阶段的发展，从较低的形式进到较高的形式。反之，亲属制度却是被动的；它只是把家庭经过一个长久时期所发生的进步记录下来，并且只是在家庭已经根本变化了的时候，它才发生根本的变化。”","language":"中文","translation":false},{"id":"family-1-66","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“同样，——马克思补充说，——政治的、法律的、宗教的、哲学的体系，一般都是如此。”12当家庭继续发展的时候，亲属制度却僵化起来；当后者以习惯的方式继续存在的时候，家庭却已经超过它了。不过，正像居维叶可以根据巴黎附近所发现的有袋动物骨胳的骨片，来确实地断定这种骨胳属于有袋动物，并断定那里曾经生存过这种已经绝迹的有袋动物一样，我们也可以根据历史上所留传下来的亲属制度，同样确实地断定，曾经存在过一种与这个制度相适应的业已绝迹的家庭形式。","language":"中文","translation":false},{"id":"family-1-67","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"刚刚讲过的那些亲属制度和家庭形式，同现在所盛行的亲属制度和家庭形式不同的地方，就在于每个孩子有几个父亲和母亲。按照美洲的亲属制度(夏威夷的家庭是与它相适应的)，兄弟和姊妹不能成为同一个孩子的父亲和母亲；反之，夏威夷的亲属制度，却以通常都是这种情形的家庭为前提。在这里，我们可以看见一系列家庭形式，这些家庭形式，同那些迄今习惯上认为唯一通行的形式正相矛盾。传统的观念只知道有个体婚制，以及和它并存的一夫多妻制，至多还有一妻多夫制，同时，正如满口道德的庸人所应当做的那样，还把实践偷偷地但毫不知耻地逾越官方社会所定的界限这一事实隐瞒起来。反之，原始历史的研究却向我们展示了这样一种状态，在这种状态下，男子过着多妻制的生活，而他们的妻子同时也过着多夫制的生活，所以，他们两者的子女都被看作大家共有的子女；这种状态本身，在最终分解为个体婚姻以前，又经历了一系列的变化。这些变化是这样的：被共同的婚姻纽带所联结的范围，起初是很广泛的，后来越来越缩小，直到最后只留下现在占主要地位的成对配偶为止。","language":"中文","translation":false},{"id":"family-1-68","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根在这样考证过去的家庭的历史时，同他的多数同行一致，也认为曾经存在过一种原始的状态，那时部落内部盛行毫无限制的性关系，因此，每个女子属于每个男子，同样，每个男子也属于每个女子[16]。这种原始状态，早在上一个世纪就有人谈过，不过只是一般谈谈而已；只有巴霍芬才第一个认真对待这个问题，并且到历史的和宗教的传说中寻找这种原始状态的痕迹[17]，——这是他的伟大功绩之一。现在我们知道，他所找出的这些痕迹，决没有追溯到杂乱性关系的社会阶段，而只是追溯到晚得多的一个形式，即群婚制。那个原始社会阶段，如果确实存在过的话，也是属于非常遥远的时代，以致在社会的化石，即在落后的蒙昧人中间，我们未必可以找到它在过去存在的直接证据了。巴霍芬的功绩，就在于他把这个问题提了出来作为考察的中心。[18]近年来，否认人类性生活的这个初期阶段，已成时髦了。人们想使人类免去这一“耻辱”。在这里，人们不仅以缺乏任何直接的证据为口实，而且还特别引用其他动物界的例子；从其他动物界里，勒土尔诺(《婚姻和家庭之进化》1888年版)搜集了许多事实，表明完全杂乱的性关系即使在这里也应该属于低级发展阶段。但是，我从这一切事实中只能得出这样一个结论，即它们对于人类及其原始生活条件绝对证明不了任何东西。脊椎动物长期的成对同居，用生理的原因足以说明，例如在鸟类中，是由于雌鸟在孵卵期间需要扶助；在鸟类中存在的忠实的专偶制的例子，对于人类丝毫不能有所证明，因为人类并非起源于鸟类。如果严格的专偶制是各种美德的最高峰，那么优胜的棕叶就应当属于绦虫了，因为绦虫在其50－200个关节或体节的每一节中都有完备的雌雄性器官，终生都在每个体节中自行交合。而如果我们只限于谈哺乳动物，那么我们在这里就可以找出性生活的一切形式——杂交、类似群婚的形式、多妻制、个体婚制；所缺乏的只是多夫制，这一点只有人类才能做得出来。甚至我们的近亲——猿猴类，在雌雄的配合上也显露了种种可能的差别；如果再缩小范围，仅仅考察一下四种类人猿，那么在这里勒土尔诺只能说，它们有时是专偶制，有时是多偶制，而从日罗－特隆的著作来看，索绪尔则断言它们是专偶制。13最近韦斯特马克(《人类婚姻史》1891年伦敦版)关于类人猿是专偶制的断语，也远不能作为证据。总之，现有的材料都是这样一种性质，以致诚实的勒土尔诺承认：","language":"中文","translation":false},{"id":"family-1-69","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“不过，在哺乳动物中，智力发展的程度和性关系的形式之间，根本没有严格的关系。”[19]而埃斯皮纳斯(《论动物的社会》1877年版)则率直地说：","language":"中文","translation":false},{"id":"family-1-70","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“群是我们在动物中所能看到的最高的社会集团。它大概是由家庭构成的，但是家庭和群一开始就处在对抗之中，它们是以反比例发展的。”","language":"中文","translation":false},{"id":"family-1-71","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"从上述情况已经可以看出，我们关于类人猿的家庭集团及其他共居生活集团还几乎没有丝毫确定的知识；现有的材料都是直接互相矛盾的。这也没有什么稀奇。甚至我们所掌握的关于蒙昧人类族系的一切材料，也是十分矛盾，十分需要严格考证和精选的；而观察猿猴社会，比观察人类社会，还要困难得多。因此，凡根据这样绝对不可靠的报告而作的任何结论，我们都必须加以屏弃。","language":"中文","translation":false},{"id":"family-1-72","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"反之，上面所引的埃斯皮纳斯的命题却给了我们一个较好的论据。高等动物的群和家庭并不是互相补充，而是互相对立的。埃斯皮纳斯非常清楚地说明了，雄性在交尾期内的忌妒是怎样削弱或者暂时瓦解任何共居生活的群。","language":"中文","translation":false},{"id":"family-1-73","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“在家庭紧密结合的地方，群只是一种稀有的例外。反之，在自由的性关系或多偶制盛行的地方，群差不多是自动地形成的……为了使群能够组成，家庭的纽结必然要放松，个体必然要重新自由。因此，我们在鸟类中才极少见到有组织的群……反之，我们在哺乳动物中之所以能发现在某种程度上有组织的社会，正因为个体在这里没有被家庭所吞没……所以，群的集体感在其发生时的大敌，莫过于家庭的集体感。我们可以毫不迟疑地说：如果说一种比家庭更高级的社会形式已经发展起来，那么这只是由于它把遭受了彻底变化的家庭容纳于自身之中才能发生；这并不排除，这些家庭正是由于这一点以后才有可能在无限优越的环境中重新组成。”(埃斯皮纳斯《论动物的社会》；转引自日罗－特隆《婚姻与家庭的起源》1884年版第518－520页)","language":"中文","translation":false},{"id":"family-1-74","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由此可见，动物社会对于推断人类社会确有某种价值，——但只是反面的价值而已。在较高等的脊椎动物中，据我们所知，只有两种家庭形式：多妻制和成对配偶制；在这两种家庭形式中，都只许有一个成年的雄者，只许有一个丈夫。雄者的忌妒，既联结又限制着动物的家庭，使动物的家庭跟群对立起来；由于这种忌妒，作为共居生活较高形式的群，在一些场合成为不可能，而在另一些场合则被削弱，或在交尾期间趋于瓦解，最多不过是，其进一步的发展受到阻碍。单是这一点就足以证明，动物的家庭和人类的原始社会是两不相容的东西；正在努力脱离动物状态的原始人类，或者根本没有家庭，或者至多只有动物中所没有的那种家庭。像正在形成中的人这样一种没有武器的动物，即使互相隔绝，以成对配偶为共居生活的最高形式，就像韦斯特马克根据猎人的口述所断定的大猩猩和黑猩猩的情况那样，也是能够以不多的数量生存下去的。为了在发展过程中脱离动物状态，实现自然界中的最伟大的进步，还需要一种因素：以群的联合力量和集体行动来弥补个体自卫能力的不足。用现今类人猿那样的生活条件根本无法解释向人类的状态过渡；这种类人猿给我们的印象，勿宁说是一种正在逐渐灭绝的、至少也是处于衰落状态的脱离正轨的旁系。只此一点，就足以驳倒由它们的家庭形式类推原始人类的家庭形式的任何论调了。而成年雄者的相互宽容，没有忌妒，则是形成较大的持久的集团的首要条件，只有在这种集团中才能实现由动物向人的转变。的确，我们发现历史上可以确切证明并且现在某些地方还可以加以研究的最古老、最原始的家庭形式是什么呢？那就是群婚，即整群的男子与整群的女子互为所有，很少有忌妒余地的婚姻形式。其次，在较晚的一个发展阶段上，我们又发现了多夫制这种例外形式，这一形式更是直接同一切忌妒的感情相矛盾，因而是动物所没有的。不过，我们所知道的群婚形式都伴有特殊复杂的条件，以致必然使我们追溯到各种更早、更简单的性关系的形式，从而归根结蒂使我们追溯到一个同从动物状态向人类状态的过渡相适应的杂乱的性关系的时期，这样，动物婚姻形式的引证，就使我们恰好回到这些引证本来要使我们永远离开的那一点上去了。","language":"中文","translation":false},{"id":"family-1-75","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"那么，杂乱的性关系究竟是什么意思呢？这就是说，现在或较早时期通行的禁规在那时是没有效力的。我们已经看到，忌妒所造成的限制是怎样崩溃的。如果说有什么可以确定的话，那就是：忌妒是一种较后发展起来的感情。血亲婚配的观念，也是如此。不仅兄弟和姊妹起初曾经是夫妇，而且父母和子女之间的性关系今日在许多民族中也还是允许的。班克罗夫特(《北美太平洋沿岸各州的土著民族》1875年版第1卷)证明，白令海峡沿岸的加惟基人、阿拉斯加附近的科迪亚克岛上的人、英属北美内地的提纳人，都有这种关系；勒土尔诺也提出了关于印第安赤北韦人、智利的库库人、加勒比人、印度支那半岛的克伦人的同样事实的报告；至于古希腊人和古罗马人关于帕提亚人、波斯人、西叙亚人、匈奴人等的故事，在这里就不必说了。在血亲婚配尚未发明之前(这的确是一种发明，而且是一种极其宝贵的发明)，父母和子女之间的性关系所引起的憎恶，并不大于其他不同辈的人们之间的性关系；而后者即使今日在最市侩气的国家里也还在发生，而且并不引起多大的惊骇；甚至年逾60的老“姑娘”，如果她们十分富有的话，有时也可以嫁给一个30来岁的青年男子。不过，如果我们从我们所知道的最原始的家庭形式上抛弃那种与它们连在一起的血亲婚配的观念，——这种观念跟我们的观念完全不同，而且往往是跟它们直接冲突的，——那么我们就得出一种只能叫作杂乱的性关系的形式了。所谓杂乱，是说后来由习俗所规定的那些限制那时还不存在。但是由此决不能说，在日常实践中也必然是一片混乱。短时期的成对配偶决不是不可能的，正如在群婚制中，当时的多数情况也是成对配偶那样。所以，如果说韦斯特马克(他是最近的一个否认这种原始状态的人)把两性在生孩子以前一切成对同居状态，都叫作婚姻，那么就应该说，这种婚姻完全可以在杂乱的性关系状态下发生，而它跟杂交状态，即不存在习俗规定的对性关系的限制的那种状态不相矛盾。当然，韦斯特马尔克是从如下的观点出发的，他认为：","language":"中文","translation":false},{"id":"family-1-76","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“杂交状态包含着对个人爱好的压抑”，因而“卖淫是这种状态的最真实的形式”[20]。","language":"中文","translation":false},{"id":"family-1-77","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"而我却以为，只要还戴着妓院眼镜去观察原始状态，便永远不可能对它有任何理解。我们在研究群婚时，再来谈这个问题吧。","language":"中文","translation":false},{"id":"family-1-78","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"按照摩尔根的意见，从这种杂乱的性关系的原始状态中，大概很早就发展出了以下几种家庭形式：","language":"中文","translation":false},{"id":"family-1-79","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.血缘家庭——这是家庭的第一个阶段。在这里，婚姻集团是按照辈份来划分的：在家庭范围以内的所有祖父和祖母，都互为夫妻；他们的子女，即父亲和母亲，也是如此；同样，后者的子女，构成第三个共同夫妻圈子。而他们的子女，即第一个集团的曾孙子女们，又构成第四个圈子。这样，这一家庭形式中，仅仅排斥了祖先和子孙之间、双亲和子女之间互为夫妻的权利和义务(用现代的说法)。同胞兄弟姊妹、从(表)兄弟姊妹、再从(表)兄弟姊妹和血统更远一些的从(表)兄弟姊妹，都互为兄弟姊妹，正因为如此，也一概互为夫妻。兄弟姊妹的关系，在家庭的这一阶段上，也自然而然地包括相互的性关系。[21]这种家庭的典型形式，应该是一对配偶的子孙中每一代都互为兄弟姊妹，正因为如此，也互为夫妻。","language":"中文","translation":false},{"id":"family-1-80","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"血缘家庭已经绝迹了。甚至在历史所记载的最粗野的民族中间，也找不出一个可以证实的例子来。不过，这种家庭一定是存在过的，如今还在整个波利尼西亚通行的，夏威夷的亲属制度使我们不能不承认这一点，因为它所表现的血缘亲属等级只有在这种家庭形式之下才能产生；家庭后来的全部发展，使我们不能不承认这一点，因为这一家庭形式作为必然的最初阶段决定着家庭后来的全部发展。","language":"中文","translation":false},{"id":"family-1-81","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.普那路亚家庭。如果说家庭组织上的第一个进步在于排除了父母和子女之间相互的性关系，那么，第二个进步就在于对于姊妹和兄弟也排除了这种关系。这一进步，由于当事者的年龄比较接近，所以比第一个进步重要得多，但也困难得多。这一进步是逐渐实现的，大概[22]先从排除同胞的(即母方的)兄弟姊妹之间的性关系开始，起初是在个别场合，以后逐渐成为惯例(在夏威夷群岛上，在本世纪尚有例外)，最后甚至禁止旁系兄弟姊妹之间的结婚，用现代的称谓来说，就是禁止同胞兄弟姊妹的子女、孙子女以及曾孙子女之间结婚；按照摩尔根的看法，这一进步可以作为","language":"中文","translation":false},{"id":"family-1-82","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“自然选择原则在发生作用的最好说明”[23]。","language":"中文","translation":false},{"id":"family-1-83","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不容置疑，凡近亲繁殖因这一进步而受到限制的部落，其发展一定要比那些依然把兄弟姊妹婚姻当作惯例和规定的部落更加迅速，更加完全。这一进步的影响有多么大，可以由氏族的建立来作证明，氏族就是由这一进步直接引起的，而且远远超出了最初的目的，它构成地球上即使不是所有的也是大多数野蛮民族的社会制度的基础，并且在希腊和罗马我们还由氏族直接进入了文明时代。","language":"中文","translation":false},{"id":"family-1-84","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"每个原始家庭，至迟经过几代以后是一定要分裂的。原始共产制的共同的家户经济(它毫无例外地一直盛行到野蛮时代中级阶段的后期)，决定着家庭公社的最大限度的规模，这种规模虽然依条件而变化，但是在每个地方都是相当确定的。不过，认为同母所生的子女之间的性关系不妥的观念一旦发生，这种观念就一定要影响到旧家庭公社的分裂和新家庭公社的建立(这种新的家庭公社这时并不必然同家庭群体相一致)。一列或者数列姊妹成为一个公社的核心，而她们的同胞兄弟则成为另一个公社的核心。摩尔根称之为普那路亚家庭的形式，便经过这样或类似的途径而由血缘家庭产生出来了。按照夏威夷的习俗，若干数目的姊妹——同胞的或血统较远的即从(表)姊妹，再从(表)姊妹或更远一些的姊妹——是她们共同丈夫们的共同的妻子，但是在这些共同丈夫之中，排除了她们的兄弟；这些丈夫彼此已不再互称兄弟，他们也不再必须是兄弟了，而是互称普那路亚，即亲密的同伴，即所谓associé。同样，一列兄弟——同胞的或血统较远的——则跟若干数目的女子(只要不是自己的姊妹)共同结婚，这些女子也互称普那路亚。这是古典形式的一种家庭结构；这种形式后来又有一系列变种，它的主要特征是一定的家庭范围内相互的共夫和共妻，不过，妻子的兄弟(起初是同胞的，以后更及于血统较远的)被排除在这个家庭范围以外，另一方面也把丈夫的姊妹除外。","language":"中文","translation":false},{"id":"family-1-85","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种家庭形式十分精确地向我们提供了美洲的制度所表现的亲属等级。我母亲的姊妹的子女，依然是我母亲的子女，同样，我父亲的兄弟的子女，也依然是我父亲的子女，他们全都是我的兄弟姊妹；但是我母亲的兄弟的子女，现在都是我母亲的内侄和内侄女，我父亲的姊妹的子女，现在都是我父亲的外甥和外甥女，而他们全都是我的表兄弟和表姊妹了。因为，固然我母亲的姊妹的丈夫们依然是我母亲的丈夫们，同样，我父亲的兄弟的妻子们也依然是我父亲的妻子们——即使事实上不总是如此，在道理上却是如此——，但由于社会禁止兄弟姊妹之间的性关系，结果就使迄今不加区别地被作为兄弟姊妹来对待的兄弟姊妹的子女划分为两类：有一些人像过去一样，相互之间依然是(血统较远的)兄弟姊妹，另一些人即一方面兄弟的子女和另一方面姊妹的子女，再也不能是兄弟姊妹，再也不能有共同的双亲了——无论是共同的父亲，共同的母亲，或是共同的父母；因此，在这里，第一次发生了分为外甥和外甥女、内侄和内侄女、表兄弟和表姊妹这一类别的必要，而这一类别在从前的家庭制度之下恐怕是没有任何意义的。美洲的亲属制度，在以某种个体婚为基础的任何家庭形式下，看来都是极其荒诞的事情，现在它在普那路亚家庭中，连最细微的地方，都获得了合理的解释和自然的根据。只要美洲的亲属制度流行过，普那路亚家庭或某种与它类似的形式[24]至少也应该同样存在过。","language":"中文","translation":false},{"id":"family-1-86","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如果虔诚的传教士，像美洲早先的西班牙修道士一样，在这种反基督教的关系中，除去简单的“丑事”[25]外能够看一看更多的东西，那么，大概在整个波利尼西亚都可以找到这种已被证明确实存在于夏威夷群岛上的家庭形式。如果说，凯撒在谈到当时处于野蛮时代中级阶段的布列吞人时曾告诉我们说，他们“每10个或12个男子共妻，而且多半是兄弟和兄弟，父母和子女”19，那么，这最好解释为群婚[26]。野蛮时代的母亲不会有10个至12个这样年龄的儿子，以致可以有共同的妻子们；而跟普那路亚家庭相适应的美洲的亲属制度，却能提供好多兄弟，因为每个男子的一切血统近的和远的从(表)兄弟都是他的兄弟。所谓“父母和子女”，大概是凯撒弄错了；在这个制度下，固然还没有绝对排除父亲和儿子或母亲和女儿属于同一婚姻集团的可能性，但是却不许父亲和女儿或母亲和儿子处在同一婚姻集团内。同样，这种群婚形式或与它类似的群婚形式[27]，最容易说明希罗多德及其他古代著作家关于蒙昧民族和野蛮民族中共妻情况的报告。这也可以说明沃森和凯(《印度的居民》20)所叙述的关于奥德(在恒河以北)的蒂库尔人的情况，即：","language":"中文","translation":false},{"id":"family-1-87","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“他们共同地<即在性关系上>生活在大公社中，差不多毫无区别，要是他们之间有二人被视为夫妻，那么，这种关系只不过是名义上的。”","language":"中文","translation":false},{"id":"family-1-88","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"看来，氏族制度，在绝大多数情况下，都是从普那路亚家庭中直接发生的。诚然，澳大利亚的级别制度也可以成为产生氏族的出发点21；澳大利亚人有氏族，但他们还没有普那路亚家庭，而只有比较粗陋的群婚形式[28]。","language":"中文","translation":false},{"id":"family-1-89","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在一切形式的群婚家庭中，谁是某一个孩子的父亲是不确定的，但谁是孩子的母亲则是确定的。即使母亲把共同家庭的一切子女都叫作自己的子女，对于他们都担负母亲的义务，但她仍然能够把她自己亲生的子女同其余一切子女区别开来。由此可知，只要存在着群婚，那么世系就只能从母亲方面来确定，因此，也只承认女系。一切蒙昧民族和处在野蛮时代低级阶段的民族，实际上都是这样；所以巴霍芬的第二个伟大功绩，就在于他第一个发现了这一点。他把这种只从母亲方面确认世系的情况和由此逐渐发展起来的继承关系叫作母权制；为了简便起见，我保留了这一名称；不过它是不大恰当的，因为在社会发展的这一阶段上，还谈不到法律意义上的权利。","language":"中文","translation":false},{"id":"family-1-90","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如果我们现在从普那路亚家庭中取它的两个典型集团之一，即由一列同胞姊妹和血统较远的姊妹(亦即同胞姊妹所派生的第一等级、第二等级或更远等级的姊妹)连同她们的子女以及她们母方的同胞兄弟和血统较远的兄弟(按照我们的前提，他们不是她们的丈夫)所组成的典型集团来看，那么，摆在我们面前的这一群人，正是后来构成原始形式的氏族的成员。她们全体有一个共同的女始祖；由于世系出自同一个女始祖，后代的所有女性每一代都是姊妹。但是，这些姊妹的丈夫们，再也不能是她们的兄弟，从而不能是出自这个女始祖的，因而也不包括在血缘亲属集团即后来的氏族以内了；然而，他们的子女却属于这个集团，因为只有唯一确知的母方世系才具有决定的作用。一切兄弟和姊妹间，甚至母方最远的旁系亲属间的性关系的禁规一经确立，上述的集团便转化为氏族了，换言之，即组成一个确定的、彼此不能结婚的女系血缘亲属集团；从这时起，这种集团就由于其他共同的社会的和宗教的设施而日益巩固起来，并且与同一部落内的其他氏族区别开来了。关于这一点，以后还要详细谈到。不过，我们既然看到氏族不仅是必然地，而且简直是自然而然地从普那路亚家庭发展起来的，那么我们就有理由认定，在氏族制度可得到证实的一切民族中，即差不多在一切野蛮人和一切文明民族中，几乎毫无疑问地都曾经存在过这种家庭形式。[29]当摩尔根写他的著作的时候，我们关于群婚的知识还是非常有限的。我们仅略略知道一点那种组织为级别的澳大利亚人的群婚，此外摩尔根早在1871年发表了他所得到的关于夏威夷普那路亚家庭的材料[30]。普那路亚家庭，一方面，给美洲印第安人中盛行的亲属制度提供了完备的说明，而这一制度曾经是摩尔根的全部研究的出发点；另一方面，它又是一个引出母权制氏族的现成的出发点；最后，它乃是远比澳大利亚的级别制度更高的一个发展阶段。因此，摩尔根把这个形式看作必然先于对偶婚存在的一个发展阶段，并且认定它在较早的时期普遍流行，这是可以理解的。自从那时以来，我们了解了群婚的一系列其他形式，现在我们知道，摩尔根在这里走得太远了。不过，他仍然很幸运，在他的普那路亚家庭中碰到了最高的、典型的群婚形式，从这种群婚形式向更高形式的过渡，最容易得到说明。","language":"中文","translation":false},{"id":"family-1-91","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"使我们的关于群婚的知识大大丰富起来的，是英国传教士洛里默·法伊森，他在这种家庭形式的典型地区——澳大利亚，对群婚作了多年的研究。22他在南澳大利亚的芒特甘比尔地区的澳大利亚黑人中发现了最低的发展阶段。在这里，整个部落分为两个级别：克洛基和库米德。每个级别内部都严格禁止性关系；反之，一级别的每个男子生来就是另一级别的每个女子的丈夫，而后者生来也是前者的妻子。不是单个人，而是整个集团相互结婚，即级别和级别结婚。而且应当指出，这里除了两个外婚制级别的划分所造成的限制以外，也没有因年龄差别或某种特殊血缘亲属关系设下什么条件。对克洛基的任何男子说来，库米德的每个女子都是他的当然的妻子；但是，他自己的女儿，既是库米德女性所生，根据母权制也是库米德，所以，她生来就是每个克洛基男人的妻子，从而也是自己父亲的妻子。至少，我们所知道的这种级别组织对于这一点是没有悬为禁规的。所以，或者是在这种组织发生的那个时期，虽然已有限制近亲婚配的朦胧意向，但是人们还不把父母和子女间的性关系看作怎样特别可怕的事情，——在这种情况下，级别制度就是从杂乱的性关系的状态中直接产生的；或者是在级别发生的时候，父母和子女间的性关系业已为习俗所禁止，——在这种情况下，当前的状态就表明在它以前曾经存在过血缘家庭，而它是走出血缘家庭的第一步。后面这一种情况，比较可信。据我所知，在澳大利亚，父母和子女间的婚姻关系的例子，还没有人提到过；而比较晚一些的外婚形式，即母权制氏族，通常也默然以禁止这种关系为前提，把这种禁规看作一种在氏族产生时就已存在的事情。","language":"中文","translation":false},{"id":"family-1-92","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"两个级别的制度，除了南澳大利亚的芒特甘比尔地区以外，在更靠东部的达令河流域和东北部的昆士兰也有，所以，这个制度流行颇广。它只排除母方兄弟姊妹间、母方兄弟的子女间、母方姊妹的子女间的结婚，因为他们都是属于同一级别的；反之，姊妹的子女和兄弟的子女却能相互结婚。进一步阻止近亲婚配的办法，可以在新南威尔士达令河流域的卡米拉罗依人中间看到，在那里，两个最初的级别分裂成四个，而这四个级别之中每一级别又都跟其他一定的级别整体结婚。最初的两个级别生来就互为夫妻；根据母亲属于第一或第二级别，她的子女就属于第三或第四级别；这后两个同样互相结婚的级别，其子女又加入第一和第二级别。这样，一代总是属于第一和第二级别，下一代则属于第三和第四级别，第三代又重新属于第一和第二级别。根据这一制度，兄弟姊妹的子女(母方的)不得为夫妻，但是兄弟姊妹的孙子孙女却可以为夫妻。这一特别而复杂的制度，由于母权制氏族嫁接上来——肯定是在较后的时期——而更加复杂。不过，在这里我们不能研讨这个了。这样，我们看到，阻止近亲婚配的意向，一而再再而三地表现出来，然而这是自发地摸索着进行的，并没有明确的目的意识。","language":"中文","translation":false},{"id":"family-1-93","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"群婚在澳大利亚还是一种级别婚，它是往往分布于全大陆的整个一级别的男子和同样广布的一级别的女子的群众性夫妻关系，——这种群婚，如果加以详细的观察，并不完全像习惯于娼妓制度的庸人幻想所想象的那样可怕。相反地，过了许多年以后，人们仅仅猜测到有这种群婚存在，而不久以前又对它争论起来。在皮相的观察者看来，它是一种不牢固的个体婚制，而在某些地方则是与偶尔的通奸并行的多妻制。只有像法伊森和豪伊特那样，花费许多年工夫，才能在这些使普通的欧洲人对于其实践反倒更感到亲切的婚姻关系中发现一种调节规则，根据这种规则，一个外地的澳大利亚黑人在离开本乡数千公里的地方，在说着他所不懂的语言的人们中间，往往依然可以在一个个住宿地，在一个个部落里，找到毫无反抗和怨恨地委身于他的女子，而根据这种规则有着几个妻子的男人，也要让出一个妻子给自己的客人去过夜。在欧洲人视为不道德和无规则的地方，事实上都盛行着一种严格的规则。这些女子属于客人的通婚级别，因而她们生来就是他的妻子；把双方结合起来的那个道德规则，同时又用剥夺权利的惩罚方法，禁止相互所属的通婚级别以外的任何性关系。甚至在抢劫妇女(这是经常的，某些地方还是通例)的地方，也很慎重地遵守级别的规则。","language":"中文","translation":false},{"id":"family-1-94","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"顺便提一下，抢劫妇女的现象，已经表现出向个体婚制过渡的迹象，至少是以对偶婚的形式表现出这种迹象：当一个青年男子，在朋友们的帮助下劫得或拐得一个姑娘的时候，他们便轮流同她发生性关系；但是在此以后，这个姑娘便被认为是那个发动抢劫的青年男子的妻子。反之，要是被劫来的女子背夫潜逃，而被另一个男子捕获，那么她就成为后者的妻子，前者就丧失了他的特权。这样，与普遍继续存在的群婚并行，并且在它的范围以内，就形成了一种排斥他人的关系，即或长或短时期内的成对配偶制以及与此并行的多妻制，于是在这里群婚也开始消亡，问题只在于：在欧洲人的影响下，首先消失的是什么——是群婚制还是奉行群婚制的澳大利亚黑人。","language":"中文","translation":false},{"id":"family-1-95","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"像澳大利亚所盛行的那种整个级别的结婚，无论如何，乃是群婚的一种十分低级的、原始的形式；而普那路亚家庭，就我们所知道的而论，则是群婚的最高发展阶段。前者大概是同漂泊不定的蒙昧人的社会状况相适应的，后者则已经是以有了比较牢固的共产制公社的居民点为前提，并且直接导向下一个更高的发展阶段。在这两种婚姻形式之间，我们无疑还会发现某些中间阶段；在这里，目下摆在我们面前的还是一个刚刚敞开而尚未有人进入的研究领域。","language":"中文","translation":false},{"id":"family-1-96","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"3.对偶制家庭。某种或长或短时期内的成对配偶制，在群婚[31]制度下，或者更早的时候，就已经发生了；一个男子在许多妻子中有一个主妻(还不能称为爱妻)，而他对于这个女子来说是她的许多丈夫中的最主要的丈夫。这种情况，在不小的程度上助长了传教士中间的混乱，这些传教士们有时把群婚[32]看作一种杂乱的共妻，有时又把它看作一种任意的通奸。但是，这种习惯上的成对配偶制，随着氏族日趋发达，随着不许互相通婚的“兄弟”和“姊妹”级别的日益增多，必然要日益巩固起来。氏族在禁止血缘亲属结婚方面所起的推动作用，使事情更加向前发展了。例如我们看到，在易洛魁人和其他处于野蛮时代低级阶段的大多数印第安人那里，在他们的亲属制度所点到的一切亲属之间都禁止结婚，其数多至几百种。由于婚姻禁规日益错综复杂，群婚就越来越不可能；群婚就被对偶制家庭排挤了。在这一阶段上，一个男子和一个女子共同生活；不过，多妻和偶尔的通奸，则仍然是男子的权利，虽然由于经济的原因，很少有实行多妻制的；同时，在同居期间，多半都要求妇女严守贞操，要是有了通奸的情事，便残酷地加以处罚。然而，婚姻关系是很容易由任何一方解除的，而子女像以前一样仍然只属于母亲。","language":"中文","translation":false},{"id":"family-1-97","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在这种越来越排除血缘亲属结婚的事情上，自然选择的效果也继续表现出来。用摩尔根的话来说就是：","language":"中文","translation":false},{"id":"family-1-98","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“没有血缘亲属关系的氏族之间的婚姻，生育出在体质上和智力上都更强健的人种；两个正在进步的部落混合在一起了，新生代的颅骨和脑髓便自然地扩大到综合了两个部落的才能的程度。”23这样，实行氏族制度的部落便必然会对落后的部落取得上风，或者带动它们来仿效自己。","language":"中文","translation":false},{"id":"family-1-99","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由此可见，原始历史上家庭的发展，就在于不断缩小最初包括整个部落、其内部盛行两性共同婚姻的那个范围。由于次第排斥亲属通婚(起初是血统较近的，后来是血统越来越远的亲属，最后甚至是仅有姻亲关系的)，任何群婚形式终于在实际上成为不可能的了，结果，只剩下一对暂时松散地结合的配偶，即一旦解体整个婚姻就终止的分子。从这一点就已经可以看出，个体婚制的发生同字面的现代意义上的个人的性爱是多么没有关系了。所有正处于这一发展阶段的各民族的实践，更加证明了这一点。在以前的各种家庭形式下，男子是从来不缺乏女子的，相反，女子倒是多了一点；而现在女子却稀少起来，不得不去寻找了。因此，随着对偶婚的发生，便开始出现抢劫和购买妇女的现象，这是发生了一个深刻得多的变化的普遍迹象，不过只是迹象而已；但是苏格兰的学究麦克伦南，却把这些迹象，这些单纯的求妻方法，说成是“抢劫婚姻”和“买卖婚姻”，虚构为两种特殊的家庭。此外，在美洲印第安人和其他处于同一发展阶段的民族中间，缔结婚姻并不是当事人本人的事情(甚至往往不同他们商量)，而是他们的母亲的事情。这样，订婚的往往是两个彼此全不相识的人，只是到婚期临近时，才告诉他们业已订婚。在婚礼之前，新郎赠送礼物给新娘的同氏族亲属(即新娘的母方亲属，而不是她的父亲和父亲的亲属)；这种礼物算是被出让的女儿的代价。婚姻可以根据夫妇任何一方的意原而角除，但是在许多部落中，例如在易洛魁人中，逐渐形成了对这种离婚采取否定态度的社会舆论；在夫妇不和时，双方的氏族亲属便出面调解，只有在调解无效时，才实行离婚，此时子女仍归妻方，以后双方都有重新结婚的自由。","language":"中文","translation":false},{"id":"family-1-100","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种对偶制家庭，本身还很脆弱，还很不稳定，不能使人需要有或者只是希望有自己的家户经济，因此它根本没有使早期传下来的共产制家户经济解体。但是共产制家户经济意味着妇女在家内的统治，正如在不能确认生身父亲的条件下只承认生身母亲意味着对妇女即母亲的高度尊敬一样。那种认为妇女在最初的社会里曾经是男子的奴隶的意见，是18世纪启蒙时代所流伟下来的最荒谬的观念之一。在一切蒙昧人中，在一切处于野蛮时代低级阶段、中级阶段、部分地还有处于高级阶段的野蛮人中，妇女不仅居于自由的地位，而且居于受到高度尊敬的地位。这种地位到了对偶婚时期是怎样的情形，可以由在塞讷卡部落的易洛魁人中做过多年伟教士的阿瑟·莱特作证明。他说：","language":"中文","translation":false},{"id":"family-1-101","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“讲到他们的家庭，当他们还住在老式长屋(包含几个家庭的共产制家户经济)中的时候……那里总是由某一个克兰(氏族) 占统治地位，因此妇女是从别的克兰(氏族)中招来丈夫的……通常是女方在家是支配一切，贮藏品是公有的；但是，倒霉的是那种过于怠惰或过于笨拙因而不能给公共贮藏品增加一分的不幸的丈夫或情人。不管他在家里有多少子女或占有多少财产，仍然要随时听候命令，收拾行李，准备滚蛋。对于这个命令，他不可有反抗的企图；他无法在这栋房子里住下去，他非回到自己的克兰(氏族)去不可；或者像他们通常所做的那样，到别的克兰内重新结婚。妇女在克兰(氏族)里，乃至一般在任何地方，都有很大的势力。有时，她们可以毫不犹豫地撤换酋长，把 他贬为普通的战士。”24在共产制家户经济中，大多数或全体妇女都属于同一氏族，而男子则来自不同的氏族，这种共产制家户经济是原始时代普遍流行的妇女占统治地位的客观基础，发现妇女占统治地位，乃是巴霍芬的第三个功绩。——为补充起见，我还要指出：旅行家和传教士关于蒙昧人和野蛮人的妇女都担负过重工作的报告，同上面所说的并不矛盾。决定两性间的分工的原因，是同决定妇女社会地位的原因完全不同的。有些民族的妇女所做的工作比我们所设想的要多得多，这些民族比我们欧洲人常常对妇女怀着更多的真正尊敬。外表上受尊敬的、脱离一切实际劳动的文明时代的贵妇人，比起野蛮时代辛苦劳动的妇女来，其社会地位是无比低下的；后者在本民族中被看作真正的贵妇人(lady，frowa，Frau＝女主人)，而就其地位的性质说来，她们也确是如此。","language":"中文","translation":false},{"id":"family-1-102","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"要弄清现在美洲的群婚[33]是否已完全被对偶婚所排除的问题，必须更加仔细地研究一下还处于蒙昧时代高级阶段的西北部民族、特别是南美的各民族。关于后者，流传着各种各样的性关系不受限制的事例，使人很难设想在这里旧时的群婚已经完全克服。[34]无论如何，群婚的遗迹还没有完全消失。在北美的至少40个部落中，同长姊结婚的男子有权把她的一俟达到婚龄的一切妹妹也娶为妻子——这是一整群姊妹共夫的遗风。而加利福尼亚半岛的居民(蒙昧时代高级阶段)，据班克罗夫特说，则有一些节日，在节日里几个“部落”聚集在一起，不加区别地发生性关系。25这显然是指一些氏族，它们在这些节日里，对于从前一个氏族的妇女以另一氏族的所有男子为她们的共同丈夫，而男子则以另一氏族的所有妇女为他们的共同妻子的时代，还保存着一点朦胧的记忆。[35]这种习俗在澳大利亚仍然盛行着。有些民族中，还有这种情形，即男性长者、酋长和巫师，利用共妻制来为自己服务，自己独占大多数妇女；但是，他们在一定节日和民众大集会时，必须重新实行以前的共妻制，让自己的妻子去和年轻的男子们寻乐。韦斯特马克在他的《人类婚姻史》一书第28－29页，举了许多例子，表明在印度的霍人、桑塔尔人、潘札人和科塔尔人部落中，在某些非洲民族和其他民族中，都有这种定期的沙特恩节26，即在一个短时期内恢复旧时的自由的性关系。奇怪的是，韦斯特马尔克由此得出一个结论，说这并不是他所否认的群婚的残余，而是原始人和其他动物所共有的交尾期的残余。","language":"中文","translation":false},{"id":"family-1-103","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在这里，我们便接触到了巴霍芬的第四个伟大的发现：广泛流行的从群婚到对偶婚的过渡形式。被巴霍芬说成是对违反古代神戒的赎罪，即妇女用以赎买贞操权利的赎罪，事实上不过是对一种赎身办法的神秘化的说法，妇女用这种办法，把自己从旧时的共夫制之下赎出来，而获得只委身于一个男子的权利。这种赎身，是一种有限制的献身：巴比伦的女子每年须有一次在米莉塔庙里献身；其他前亚细亚各民族把自己的姑娘送到阿娜伊蒂斯庙去住好几年，让她们在那里同自己的意中人进行自由恋爱，然后才允许她们结婚；穿上宗教外衣的类似的风俗，差不多在地中海和恒河之间的所有亚洲民族中间都是共同的。为赎身而作出的赎罪牺牲，随着时间的进展而越来越轻，正如巴霍芬已经指出的：","language":"中文","translation":false},{"id":"family-1-104","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“年年提供的这种牺牲，让位于一次的供奉；从前是妇人的淫游婚，现在是姑娘的淫游婚；从前是在结婚后进行，现在是在结婚前进行；从前是不加选择地献身于任何人，现在是只献身于某些人了。”(《母权论》第XIX页)","language":"中文","translation":false},{"id":"family-1-105","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在其他民族中，没有这种宗教的外衣：在有些民族中——在古代有色雷斯人、克尔特人等，在现代则有印度的许多土著居民、马来亚各民族、太平洋岛屿的居民，和许多美洲印第安人——姑娘在出嫁以前，都享有极大的性的自由。特别是在南美洲，差不多到处都是如此，只要稍稍深入到该大陆内地的人，都可以证明这一点。例如，阿加西斯(《巴西旅行记》1868年波士顿－纽约版第266页)曾经谈到一个印第安人世系的富有家庭。当他被介绍同这一家的女儿认识时，他问到她的父亲，意思是指她母亲的丈夫，一个正在参加对巴拉圭战争的军官，但是母亲含笑回答道： tem pai，éfilha da fortuna——她没有父亲，她是一个偶然生的孩子。","language":"中文","translation":false},{"id":"family-1-106","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“印第安妇女或混血种妇女，总是这样毫不害羞或者说毫无自责之意地谈到她们的非婚生子女；这远不是什么不寻常的事，似乎倒是相反的情形才是例外。孩子们……往往只知道母亲，因为一切的照顾和责任都落在她的身上；他们对于父亲却毫无所知；看来妇女也从来没有想到她或她的子女对他应当有什么要求。”","language":"中文","translation":false},{"id":"family-1-107","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在这里使文明人感到奇怪的事情，按照母权制和在群婚制中却是一种通例。","language":"中文","translation":false},{"id":"family-1-108","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在另一些民族中，新郎的朋友和亲属或请来参加婚礼的客人，在举行婚礼时，都可以提出古代遗传下来的对新娘的权利，新郎按次序是最后的一个；在巴利阿里群岛和在非洲的奥及娄人中，在古时都是如此；而在阿比西尼亚的巴里人中，现在也还是如此。在另一些民族中，则由一个有公职的人，——部落或氏族的头目、酋长、萨满、祭司、诸侯或其他不管是什么头衔的人，代表公社行使对新娘的初夜权。尽管新浪漫主义者竭力掩饰这一事实，但这种初夜权至今还作为群婚的残余，存在于阿拉斯加地区的大多数居民(班克罗夫特《土著民族》第1卷第81页)、墨西哥北部的塔胡人(同上，第584页)及其他民族中；在整个中世纪，它至少存在于原为克尔特人的各个国家中，例如在阿拉贡；在这些地方，它是直接由群婚传下来的。在卡斯蒂利亚，农民虽然从来没有成为农奴，但在阿拉贡却盛行过极丑恶的农奴制，直到1486年天主教徒斐迪南作出裁决为止27。在这个文件中说：","language":"中文","translation":false},{"id":"family-1-109","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“兹决定并宣告，上述领主……亦不得在农民娶妻时与其妻同睡第一夜，或在婚礼之夜，新娘躺在床上以后，跨越该床及该女子，作为自己统治的标志；上述领主亦不得违反农民的女儿或儿子的意志去差使他们，无论偿付报酬与否。”(转引自祖根海姆《农奴制度》1861年彼得堡版第355页上的加泰罗尼亚语原文。)","language":"中文","translation":false},{"id":"family-1-110","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"其次，巴霍芬坚决地断定，从他所说的“淫游婚”或“污泥生殖”向个体婚制的过渡，主要是由妇女所完成，这是绝对正确的。古代遗传下来的两性间的关系，越是随着经济生活条件的发展，从而随着古代共产制的解体和人口密度的增大，而失去森林原始生活的素朴性质，就必然越使妇女感到屈辱和压抑；妇女也就必然越迫切地要求取得保持贞操的权利，取得暂时地或长久地只同一个男子结婚的权利作为解救的办法。这个进步决不可能由男子首创，这至少是因为男子从来不会想到甚至直到今天也不会想到要放弃事实上的群婚的便利。只有在由妇女实现了向对偶婚的过渡以后，男子才能实行严格的专偶制——自然，这种专偶制只是对妇女而言的。","language":"中文","translation":false},{"id":"family-1-111","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"对偶制家庭产生于蒙昧时代和野蛮时代交替的时期，大部分是在蒙昧时代高级阶段，有些地方刚刚到达野蛮时代低级阶段。这是野蛮时代所特有的家庭形式，正如群婚之于蒙昧时代，专偶制之于文明时代一样。要使对偶制家庭进一步发展为牢固的专偶制，需要有别的原因，这种原因与我们已经看到的一直起着作用的那些原因不同。在成对配偶制中，群已经减缩到它的最后单位，仅由两个原子组成的分子，即一男和一女。自然选择已经通过日益缩小婚姻共同体的范围而完成了自己的使命；在这一方面，它再也没有事可做了。因此，如果没有新的、社会的动力发生作用，那么，从成对配偶制中就没有任何根据产生新的家庭形式了。但是，这种动力开始发生作用了。 我们现在撇开美洲这个对偶制家庭的典型地区不谈吧。没有任何迹象可以使我们作出结论说，在美洲曾经发展起更高级的家庭形式，或者在美洲被发现和被征服以前，在这里的什么地方曾经存在过牢固的专偶制。而旧大陆的情况却不是这样。 在旧大陆，家畜的驯养和畜群的繁殖，开发出前所未有的财富的来源，并创造了全新的社会关系。直到野蛮时代低级阶段，固定的财富差不多只限于住房、衣服、粗糙的装饰品以及获得食物和制作食物的工具：小船、武器、最简单的家庭用具。天天都要重新获得食物。现在，日益前进的游牧民族——住在印度五河地区和恒河地区，以及当时水草更丰茂的奥克苏斯河和药杀水草原的雅利安人，住在幼发拉底河和底格里斯河流域的闪米特人——已经有了马、骆驼、驴、牛、绵羊、山羊和猪等畜群，这些财产，只须加以看管和最简单的照顾，就可以越来越多地繁殖起来，供给非常充裕的乳肉食物。以前一切获取食物的方法，现在都退居次要地位了；打猎在从前曾经是必需的，如今也成了一种奢侈。","language":"中文","translation":false},{"id":"family-1-112","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，这种新的财富归谁所有呢？最初无疑是归氏族所有。然而，对畜群的私有制，一定是很早就已经发展起来了。很难说，亚伯拉罕族长被所谓摩西一经的作者看作畜群的占有者，究竟是由于他作为家庭公社首领所拥有的权利，还是由于他作为实际上世袭的氏族酋长的身分。只有一点没有疑问，那就是我们不应该把他设想为现代意义上的财产所有者。其次，没有疑问的是，在成文史的最初期，我们就已经到处都可以看到畜群乃是家庭首领的特殊财产[36]，完全同野蛮时代的工艺品一样，同金属器具、奢侈品以及人畜——奴隶一样。","language":"中文","translation":false},{"id":"family-1-113","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"因为这时奴隶制度也已经发明了。对于低级阶段的野蛮人来说，奴隶是没有价值的。所以，美洲印第安人处置战败敌人的办法，与较高发展阶段上的人们的处置办法，完全不同。男子被杀死或者被当作兄弟编入胜利者的部落；妇女则作为妻子，或者把她们同她们的尚存的子女一起收养入族。在这个阶段上，人的劳动力还不能提供超出维持它的费用的显著的盈余。由于采用牲畜繁殖、金属加工、纺织以及最后田野耕作，情况就改变了。正如以前容易得到的妻子现在具有了交换价值[37]而可以购买一样，劳动力也发生了同样的变化，特别是在畜群完全转归家庭所有[38]以后。家庭并不像牲畜那样迅速繁殖。现在需要有更多的人来看管牲畜；为此正可以利用被俘虏的敌人，何况这些敌人像牲畜一样，也是可以继续繁殖的。","language":"中文","translation":false},{"id":"family-1-114","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这些财富，一旦转归家庭[39]私有并且迅速增加起来，就给了以对偶婚和母权制氏族为基础的社会一个强有力的打击。对偶婚给家庭添加了一个新的因素。除了生身的母亲以外，它又确立了确实的生身的父亲，而且这个生身的父亲，大概比今天的许多“父亲”还要确实一些。按照当时家庭内的分工，丈夫的责任是获得食物和为此所必需的劳动工具，从而，他也取得了劳动工具的所有权；在离婚时，他就随身带走这些劳动工具，而妻子则保留有她的家庭用具。所以，根据当时社会的习惯，丈夫也是食物的新来源即家畜的所有者，而后来又是新的劳动工具即奴隶的所有者。但是根据同一社会的习惯，他的子女却不能继承他的财产，因为关于继承问题有如下的情形。","language":"中文","translation":false},{"id":"family-1-115","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"根据母权制，就是说，当世系还是只按女系计算的时候，并根据氏族内最初的继承习惯，氏族成员死亡以后早先是由他的同氏族亲属继承的。财产必须留在氏族以内。最初，由于财物不多，在实践上大概总是转归最亲近的同氏族亲属所有，就是说，转归母方的血缘亲属所有。但是，男性死者的子女并不属于死者的氏族，而是属于他们的母亲的氏族；最初他们是同母亲的其他血缘亲属共同继承母亲的，后来，可能就首先由他们来继承了；不过，他们不能继承自己的父亲，因为他们不属于父亲的氏族，而父亲的财产应该留在父亲自己的氏族内。所以，畜群的所有者死亡以后，他的畜群首先应当转归他的兄弟姊妹和他的姊妹的子女所有，或者转归他母亲的姊妹的后代所有。他自己的子女则被剥夺了继承权。","language":"中文","translation":false},{"id":"family-1-116","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"因此，随着财富的增加，财富便一方面使丈夫在家庭中占据比妻子更重要的地位；另一方面，又产生了利用这个增强了的地位来废除传统的继承制度使之有利于子女的原动力。但是，当世系还是按母权制来确定的时候，这是不可能的。因此，必须废除母权制，而它也就被废除了。这并不像我们现在所想象的那样困难，因为这一革命——人类所经历过的最深刻的革命之一，——并不需要侵害到任何一个活着的氏族成员。氏族的全体成员都仍然能够和以前一样。只要有一个简单的决定，规定以后氏族男性成员的子女应该留在本氏族内，而女性成员的子女应该离开本氏族，转到他们父亲的氏族中去就行了。这样就废除了按女系计算世系的办法和母系的继承权，确立了按男系计算世系的办法和父系的继承权。这一革命在文化民族中是怎样和在何时发生的，我们毫无所知。它是完全属于史前时代的事。不过这一革命确实发生过，关于这一点，特别是巴霍芬所搜集的关于母权制的许多遗迹的材料可以充分证明；至于这一革命是怎样容易地完成的，可以从许许多多印第安部落的例子上看出来；在那里，部分地由于日益增长的财富和改变了的生活方式(从森林移居大草原)的影响，部分地由于文明和传教士的道德上的影响，这一革命不久以前方才发生，现在还在进行。在密苏里河流域的八个部落中，有六个是实行男系世系和男系继承制的，只有两个还按女系。在肖尼人、迈阿密人和德拉韦人各部落中，已经形成一种习俗，即用属于父亲氏族的一个氏族人名来给子女取名字，用这种方法把他们列入父亲的氏族，以便他们能继承自己的父亲。“借更改名称以改变事物，乃是人类天赋的决疑法!于是就寻找一个缝隙，当实际利益提供足够的推动力时在传统的范围以内打破传统!”(马克思语)28因此，就发生了一个不可救药的混乱，这种混乱只有通过向父权制的过渡才能消除，而且确实这样部分地被消除了。“这看来是一个十分自然的过渡。”(马克思语)29至于研究比较法的法学家们对这一过渡在旧大陆的各文化民族中是如何完成的说法，——当然几乎全部只是一些假说而已，——见马·柯瓦列夫斯基《家庭及所有制的起源和发展概论》1890年斯德哥尔摩版[40]。","language":"中文","translation":false},{"id":"family-1-117","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"母权制的被推翻，乃是女性的具有世界历史意义的失败。丈夫在家中也掌握了权柄，而妻子则被贬低，被奴役，变成丈夫淫欲的奴隶，变成单纯的生孩子的工具了。妇女的这种被贬低了的地位，在英雄时代，尤其是古典时代的希腊人中间，表现得特别露骨，虽然它逐渐被粉饰伪装起来，有些地方还披上了较温和的外衣，但是丝毫也没有消除。","language":"中文","translation":false},{"id":"family-1-118","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样确立的男子独裁的第一个结果，表现在这时发生的家长制家庭这一中间形式上。这一形式的主要特点不是多妻制(关于这一点后边再讲)，而是","language":"中文","translation":false},{"id":"family-1-119","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“若干数目的自由人和非自由人在家长的父权之下组成一个家庭。在闪米特类型的家庭中，这个家长过着多妻的生活，非自由人也有妻子和子女，而整个组织的目的在于在一定的地域范围以内照管畜群”30。","language":"中文","translation":false},{"id":"family-1-120","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种家庭的根本之处在于，一是把非自由人包括在内，一是父权；所以，这种家庭形式的完善的典型是罗马人的家庭。Familia这个词，起初并不表示现代庸人的那种由脉脉温情同家庭龃龉组合的理想；在罗马人那里，它起初甚至不是指夫妻及其子女，而只是指奴隶。Famulus的意思是一个家庭奴隶，而familia则是指属于一个人的全体奴隶。还在盖尤斯时代，familia，id est patrimonium(即遗产)，就是通过遗嘱遗留的。这一用语是罗马人所发明，用以表示一种新的社会机体，这种机体的首长，以罗马的父权支配着妻子、子女和一定数量的奴隶，并且对他们握有生杀之权。","language":"中文","translation":false},{"id":"family-1-121","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“因此，这一用语不会比拉丁部落的严酷的家庭制度更早，这种家庭制度是在采用田野耕作和奴隶制合法化以后，也是在雅利安意大利人同希腊人分离以后发生的。”31","language":"中文","translation":false},{"id":"family-1-122","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"对这一点，马克思补充说：“现代家庭在萌芽时，不仅包含着奴隶制(servitus)，而且也包含着农奴制，因为它从一开始就是同田野耕作的劳役有关的。它以缩影的形式包含了一切后来在社会及其国家中广泛发展起来的对立。”","language":"中文","translation":false},{"id":"family-1-123","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种家庭形式表示着从对偶婚向专偶婚的过渡。为了保证妻子的贞操，从而保证子女出生自一定的父亲，妻子便落在丈夫的绝对权力之下了；即使打死了她，那也不过是行使他的权利罢了。[41]","language":"中文","translation":false},{"id":"family-1-124","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"随着家长制家庭的出现，我们便进入成文史的领域，从而也进入比较法学能给我们以很大帮助的领域了。而比较法学在这里也确实给我们带来了重大的进步。我们感谢马克西姆·柯瓦列夫斯基(《家庭及所有制的起源和发展概论》1890年斯德哥尔摩版第60－100页)，他向我们证明了，今天我们在塞尔维亚人和保加利亚人中还可以见到的那种称为扎德鲁加32(大意为大家庭)和Bratstvo(兄弟社)的家长制家庭公社，以及在东方各民族中所见到的那种形式有所改变的家长制家庭公社，乃是一个由群婚中产生的母权制家庭和现代世界的个体家庭之间的过渡阶段。至少对于旧大陆各文化民族说来，对于雅利安人和闪米特人说来，这一点看来已经得到证明了。","language":"中文","translation":false},{"id":"family-1-125","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"南方斯拉夫的扎德鲁加是这种家庭公社现存的最好的例子。它包括一个父亲所生的数代子孙和他们的妻子，他们住在一起，共同耕种自己的田地，衣食都出自共同的储存，共同占有剩余产品。公社处于一个家长的最高管理之下，家长对外代表公社，有权出让小物品，掌管财务，并对财务和对整个家务的正常经营负责。他是选举产生的，完全不一定是最年长者。妇女和她们的工作受主妇领导，主妇通常是家长的妻子。在为姑娘择婿时，主妇也起着重要的，而且往往是决定性的作用。但是，最高权力集中在家庭会议，即全体成年男女社员的会议。家长向这个会议作报告；会议通过各项重大决议，对公社成员进行审判，对比较重要的买卖特别是地产的买卖等作出决定。","language":"中文","translation":false},{"id":"family-1-126","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"只是在大约十年以前，才证明了在俄国也还继续存在着这种大家庭公社33；现在大家都承认，这种家庭公社，像农村公社一样在俄国的民间习俗中深深地扎下了根子。它们出现在俄罗斯最古的法典——即雅罗斯拉夫的《真理》34中，其名称(vervj)和达尔马提亚法典35中所用的相同；它们在波兰和捷克的史料中，也可以得到证明。","language":"中文","translation":false},{"id":"family-1-127","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"根据霍伊斯勒(《德意志私法制度》)的意见，德意志人的经济单位起初也不是现代意义上的个体家庭，而是由几代人或者说几个个体家庭所构成的、并且往往还包括许多非自由人的“家庭公社”。罗马的家庭也被归在这种类型以内，因此，家长的绝对权力，其他家庭成员对家长的无权地位，近来是受到很大怀疑的。在爱尔兰的克尔特人中，据说也存在过类似的家庭公社；在法国的尼韦奈，直到法国革命时期，这种家庭公社还以parc Onneries为名称保存着；而在弗朗什孔泰，它直到现在也还没有完全消失。在鲁昂地区(在索恩－卢瓦尔省)，还可以见到巨大的农民住房，中间是公用的很高的、直达屋顶的大厅，四周是卧室，由六级至八级的梯子登入，在这里住着同一家庭的好几代人。","language":"中文","translation":false},{"id":"family-1-128","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在印度，实行共同耕作的家庭公社，在亚历山大大帝时代奈阿尔科斯就已经提到过36，它今天也还存在于原来那些地方，即旁遮普和该国的整个西北部。在高加索，柯瓦列夫斯基本人就可以证明这种家庭公社的存在。在阿尔及利亚，它还存在于卡比尔人中间。甚至在美洲，据说它也曾经存在过；苏里塔所记述的古墨西哥的“calpullis”37，人们就想把它看作是家庭公社；而库诺(1890年《外国》杂志第42－44期)38十分清楚地证明，在秘鲁被征服时，存在过一种马尔克制度(而且很奇怪，这种马尔克［Mark］叫作marca)，实行定期的重新分配耕地，从而实行个体耕作。","language":"中文","translation":false},{"id":"family-1-129","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"无论如何，实行土地的共同占有和共同耕作的家长制家庭公社，现在就具有了和以前完全不同的意义。我们对于它在旧大陆各文化民族和其他若干民族中，在母权制家庭和个体家庭之间所起的重要的过渡作用，已不能有所怀疑了。在以后的阐述中，我们还要说到柯瓦列夫斯基所作的进一步的结论，即这种家长制家庭公社也是实行个体耕作以及起初是定期的而后来是永远的分配耕地和草地的农村公社或马尔克公社从中发展起来的过渡阶段。","language":"中文","translation":false},{"id":"family-1-130","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"谈到这种家庭公社内部的家庭生活，应当指出，至少在俄国，大家都知道，家长对于公社的年轻妇女，特别是对他的儿媳常常滥用他的地位，而且往往把她们作为后房；俄罗斯民歌对于这点的描述很有说服力。","language":"中文","translation":false},{"id":"family-1-131","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在说到随着母权制的覆灭而迅速发展起来的专偶制以前，我们再就多妻制和多夫制说几句话。这两种婚姻形式，只能算是例外，可以说是历史的奢侈品，除非它们在某一个国家内同时并存，但是大家知道这是没有的事。因此，由于被排除在多妻制以外的男子并不能从因多夫制而成为多余的妇女那里求得安慰，而且男女的数目，不管社会制度如何，迄今又差不多是相等的，所以，不论多妻制或多夫制的婚姻形式都不能上升为普遍通行的形式。事实上，一夫多妻制显然是奴隶制度的产物，并且限于个别占据特殊地位的人物。在闪米特人的家长制家庭中，只有家长本人，至多还有他的几个儿子，过着多妻制的生活，其余的人都以一人一妻为满足。现在整个东方还是如此；多妻制是富人和显贵人物的特权，多妻主要是用购买女奴隶的方法取得的；人民大众都是过着专偶制的生活。印度－西藏的多夫制，也同样是个例外；关于它起源于群婚[42]这个肯定并非无关紧要的问题，还需要作进一步的研究。而在实践上，多夫制的容让性看来要比伊斯兰教徒的富于忌妒的后房制度大得多。例如至少在印度的纳伊尔人中间，虽然每三四个或更多的男子共有一个妻子，但是他们每人同时还可以和别的三个或更多的男子共有第二个，甚至第三个、第四个……妻子。奇怪的是，麦克伦南在叙述这种婚姻俱乐部时(其成员可以同时加入几个俱乐部)，竟没有发现俱乐部婚姻这个新类别。不过，这种婚姻俱乐部的制度，决不是真正的多夫制；恰好相反，正如日罗－特隆已经指出的，这只是群婚的一种特殊化了的形式；男子过着多妻制的生活，而妇女则过着多夫制的生活。[43]","language":"中文","translation":false},{"id":"family-1-132","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"4.专偶制家庭。如上所述，它是在野蛮时代的中级阶段和高级阶段交替的时期从对偶制家庭中产生的；它的最后胜利乃是文明时代开始的标志之一。它是建立在丈夫的统治之上的，其明显的目的就是生育有确凿无疑的生父的子女；而确定这种生父之所以必要，是因为子女将来要以亲生的继承人的资格继承他们父亲的财产。专偶制家庭和对偶制不同的地方，就在于婚姻关系要牢固得多，这种关系现在已不能由双方任意解除了。这时通例只有丈夫可以解除婚姻关系，赶走他的妻子。对婚姻不忠的权利，这时至少仍然有习俗保证丈夫享有(拿破仑法典明确规定丈夫享有这种权利，只要他不把姘妇带到家里来[44])；而且随着社会的进一步发展，这种权利也行使得越来越广泛；如果妻子回想起昔日的性的实践而想加以恢复时，她就要受到比过去任何时候都更严厉的惩罚。","language":"中文","translation":false},{"id":"family-1-133","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种新的家庭形式的全部严酷性，我们在希腊人那里可以看到。正如马克思所指出的，神话中的女神的地位给我们展示了一个更早的时期，那时妇女还享有比较自由和比较受尊敬的地位，39但是到了英雄时代，我们就看到妇女已经由于男子的统治和女奴隶的竞争而被贬低了。[45]只要读一下《奥德赛》，就可以看到特里曼珠是怎样打断他母亲的话并要求她缄默。[46]在荷马的史诗中，被俘虏的年轻妇女都成了胜利者的肉欲的牺牲品；军事首领们按照他们的军阶依次选择其中的最美丽者；大家也知道全部《伊利亚特》都是以阿基里斯和亚加米农二人争夺这样一个女奴隶的纠纷为中心的。荷马的史诗每提到一个重要的英雄，都要讲到同他共享帐篷和枕席的被俘的姑娘。这些姑娘也被带回胜利者的故乡和家里去同居，例如在埃斯库罗斯的作品中，亚加米农对珈桑德拉就是这样做的[47]；同这些女奴隶所生的儿子可以得到父亲遗产的一小部分，并被认为是自由民；特夫克尔就是铁拉孟的这样一个非婚生的儿子，他可以按父名给自己取名字。对于正式的妻子，则要她容忍这一切，同时还要她自己严格保持贞操和对丈夫的忠诚。虽然英雄时代的希腊妇女比文明时代的妇女较受尊敬，但是归根结蒂，她对于男子说来仍不过是他的婚生的嗣子的母亲、他的最高的管家婆和女奴隶的总管而已，他可以随意纳这些女奴隶为妾，而且事实上也是这样做的。正是奴隶制与专偶制的并存，正是完全受男子支配的年轻美貌的女奴隶的存在，使专偶制从一开始就具有了它的特殊的性质，使它成了只是对妇女而不是对男子的专偶制。这种性质它到现在还保存着。","language":"中文","translation":false},{"id":"family-1-134","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"谈到较后时期的希腊人，应该把多立斯人同伊奥尼亚人区别开来。前者以斯巴达为典范，他们的婚姻关系在许多方面甚至比荷马本人所描写的婚姻关系还要古老。在斯巴达，是一种由国家根据当地的观点而改变了的对偶婚制，这种对偶婚制在有些方面还像群婚。不育子女的婚姻可以解除；国王阿拿克散德里德(约公元前650年)在一个不育的妻子以外又娶了一个，有着两个家；大约在同一时期，国王阿里斯东除了有两个不育的妻子以外还娶了第三个，而把前两妻中的一个退了。另一方面，几个兄弟可以有一个共同的妻子；一个人如果喜欢自己朋友的妻子，就可以和那个朋友共同享有她；并且认为，把自己的妻子交给一个按照俾斯麦的口吻所说的壮健的“种马”去支配，即使这个家伙本人并不属于公民之列，也是合乎体统的事情。在普卢塔克的作品中，有一个地方谈到一个斯巴达妇女，叫一个向她求爱的情人去找她的丈夫商量；因此，按照舍曼的看法，可以认为在习俗上甚至存在着更大的自由。40所以，真正的通奸，妻背夫不贞，是从来没有听说过的。另一方面，斯巴达至少在其全盛时代，还不知有家务奴隶，而处于农奴地位的黑劳士则另外居住在庄园里，因此，斯巴达人41占有他们妻子的机会比较少。在这些条件下，斯巴达的妇女自然要比其他希腊妇女占着受人尊敬得多的地位。斯巴达的妇女和少数优秀的雅典淫游女，是受古人尊崇并认为她们的言行是值得记载的举世无双的希腊妇女。","language":"中文","translation":false},{"id":"family-1-135","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们看到，在以雅典人为代表的伊奥尼亚人中间，情况就完全不同了。姑娘们只学习纺织缝纫，至多也不过学一点读写而已。她们差不多是被幽禁起来，只能同别的妇女有所交往。妇女所住的房间是在家中的单独一部分，在楼上或者在后屋中，男子，特别是陌生人不容易入内，如果有男子来到家里，妇女就躲到那里去。妇女没有女奴隶作伴就不能离家外出；她们在家里实际上受着监视；阿里斯托芬曾经提到摩罗西狗，说人们饲养它们是为了吓走奸夫[48]，而且，至少在亚洲各城市，还用阉人来监视妇女，早在希罗多德时代，在希俄斯岛上就制造这种阉人出售，据瓦克斯穆特说，并不是只卖给野蛮人42。在欧里庇得斯的作品中，妻子被称为oikure－ma[49]，即用来照管家务的一种物件(这个词是一个中性名词)；在雅典人看来，妻子除生育子女以外，不过是一个婢女的头领而已。丈夫从事竞技运动和公共事业，而妻子不许参加；此外，丈夫还常常有女奴隶供他支配，而在雅典的全盛时期，则广泛盛行至少是受国家保护的卖淫。希腊妇女那超群出众的品性，正是在这种卖淫的基础上发展起来的，她们由于才智和艺术上的审美教养而高出于古代妇女的一般水平之上，正如斯巴达妇女由于性格刚烈而高出一般水平之上一样。但是，要成为妇人，必须先成为淫游女，这是对雅典家庭的最严厉的判决。","language":"中文","translation":false},{"id":"family-1-136","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种雅典家庭随着时间的进展，成了一种范例，不仅其余的伊奥尼亚人，而且本土和殖民地的所有希腊人都逐渐按照这种范例来建立他们的家庭关系。但是，尽管有这些幽禁和监视，希腊妇女仍然常常可以找到欺瞒自己丈夫的机会。那些似乎耻于表示任何对自己妻子的爱情的丈夫，就同淫游女纵情取乐；但对妇女的侮辱，却在男子身上得到了报复并侮辱了男子本身，直到他们堕落到玩弄男童的丑恶地步，并且用加尼米德的神话使他们的神同他们自己一样都受到侮辱为止。","language":"中文","translation":false},{"id":"family-1-137","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"根据我们对古代最文明、最发达的民族所能作的考察，专偶制的起源就是如此。它决不是个人性爱的结果，它同个人性爱绝对没有关系，因为婚姻和以前一样仍然是权衡利害的婚姻。专偶制是不以自然条件为基础，而以经济条件为基础，即以私有制对原始的自然产生的公有制的胜利为基础的第一个家庭形式。[50]丈夫在家庭中居于统治地位，以及生育只可能是他自己的并且应当能继承他的财产的子女，——这就是希腊人坦率宣布的个体婚制的唯一目的。其实，个体婚制对希腊人说来就是一种负担，是一种必须履行的对神、对国家和对自己祖先的义务。在雅典，法律不仅规定必须结婚，而且规定丈夫必须履行一定的最低限度的所谓婚姻义务。[51]","language":"中文","translation":false},{"id":"family-1-138","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"可见，个体婚制在历史上决不是作为男女之间的和好而出现的，更不是作为这种和好的最高形式而出现的。恰好相反。它是作为女性被男性奴役，作为整个史前时代所未有的两性冲突的宣告而出现的。在马克思和我于1846年合写的一个旧的、未发表的手稿中，我发现了如下一句话：“最初的分工是男女之间为了生育子女而发生的分工。”43现在我可以补充几句：在历史上出现的最初的阶级对立，是同个体婚制下的夫妻间的对抗的发展同时发生的，而最初的阶级压迫是同男性对女性的压迫同时发生的。个体婚制是一个伟大的历史的进步，但同时它同奴隶制和私有制一起，却开辟了一个一直继续到今天的时代，在这个时代中，任何进步同时也是相对的退步，因为在这种进步中一些人的幸福和发展是通过另一些人的痛苦和受压抑而实现的。个体婚制是文明社会的细胞形态，根据这种形态，我们就可以研究文明社会内部充分发展着的对立和矛盾的本质。","language":"中文","translation":false},{"id":"family-1-139","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"旧时性关系的相对自由，决没有随着对偶婚或者甚至个体婚的胜利而消失。","language":"中文","translation":false},{"id":"family-1-140","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“旧的婚姻制度，虽然由于普那路亚集团的逐渐消亡而缩小到更加狭小的范围内，但仍然围绕着正在向前发展的家庭，并且伴随着它直到文明时代的最初期……这种旧制度最后终于消失在新型的淫游制中，这种新型的淫游制伴随着人类直到进入文明时代，就像一个阴影笼罩在家庭上面。”[52]","language":"中文","translation":false},{"id":"family-1-141","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根所说的淫游制，是指与个体婚制并存的男子和未婚妇女在婚姻之外发生的性关系，这种性关系，大家知道，以各种不同的形式盛行于整个文明时代，而且日益变为公开的卖淫了。[53]这种淫游制直接起源于群婚制，起源于妇女为赎买贞操权利而作的献身牺牲。为金钱而献身，最初是一种宗教行为，它是在爱神庙举行的，所得的钱最初都归于神庙的财库。亚美尼亚的阿娜伊蒂斯庙、科林斯的阿芙罗狄蒂庙的庙奴44，以及印度神庙中的宗教舞女，即所谓Bajaderen(葡萄牙语bailadeira——舞女一词的讹误)，都是最初的娼妓。这种献身起初是每个妇女的义务，后来便只由这些女尼代替其他所有妇女来实行了。在其他一些民族中，这种淫游制起源于允许姑娘们在结婚前有性的自由，因此也是群婚制的残余，只不过这种残余是通过另外一种途径传到今天的。随着财产差别的产生，亦即早在野蛮时代高级阶段，与奴隶劳动并存就零散地出现了雇佣劳动，同时，作为它的必然补充，也出现了与女奴隶的强制献身并存的自由妇女的职业卖淫。由此可见，群婚制传给文明时代的遗产是两重的，正如文明时代所产生的一切都是两重的、口不应心的、分裂为二的、对立的一样：一方面是专偶制，另方面则是淫游制以及它的最极端的形式——卖淫。淫游制和社会的任何其他制度一样，也是一种社会的制度；它使旧时的性的自由继续存在，以利于男子。在实际上不仅被容忍而且特别为统治阶级所乐于实行的淫游制，在口头上是受到诅咒的。但是实际上，这种诅咒决不是针对着参与此事的男子，而只是针对着妇女：她们被剥夺权利，被排斥在外，以便用这种方法再一次宣布男子对妇女的无条件统治乃是社会的根本法则。","language":"中文","translation":false},{"id":"family-1-142","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，在专偶制内部第二种对立也因此而发展起来了。同靠淫游制来使自己的生活更美好的丈夫并存的还有一个被冷落的妻子。[54]正如吃了半个苹果以后就再不能有一个整苹果一样，没有对立的另一面，就不可能有对立的这一面。尽管如此，男子的想法似乎仍然不是这样，直到他们的妻子教训了他们，使他们醒悟为止。随着个体婚制，出现了两种经常性的、以前所不知道的特有的社会人物：妻子的经常的情人和戴绿帽子的丈夫。男子获得了对妇女的胜利，但是桂冠是由失败者宽宏大量地给胜利者加上的。虽然加以禁止、严惩但终不能根除的通奸，已成为与个体婚制和淫游制并行的不可避免的社会的制度了。子女是否确凿无疑地出自父亲，像从前一样，至多只能依据道德的信念；所以，为了解决这个无法解决的矛盾，《拿破仑法典》第312条规定：","language":"中文","translation":false},{"id":"family-1-143","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“L′enfant concu pendant le mariage a pour pèrele mari”——凡在结婚以后怀胎的婴儿，以丈夫为父。","language":"中文","translation":false},{"id":"family-1-144","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这便是个体婚制3000年的最后结果。","language":"中文","translation":false},{"id":"family-1-145","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，在个体家庭中，在仍然忠实于它的历史起源和使得由于丈夫的独占统治而出现的男女之间的冲突明白显露出来的场合，我们就看到了自文明时代开始分裂为阶级的社会在其中运动着、但是既不能解决又不能克服的那些对立和矛盾的一幅缩图。自然，我在这里所说的，只是个体婚制的如下一些场合，即夫妻生活确实是按照这整个制度的最初性质的规则来进行而妻子反抗丈夫统治的场合。至于说并不是一切婚姻都是这样进行的，这一点没有人比德国庸人知道得更清楚了，他不知道怎样维护他在家中的统治，正如他不知道怎样维护他在国家的统治一样，所以，他的妻子有充分权利操起不配由他掌握的权柄。但是他却自以为，他比他的同样不幸的、比他本人更常遇到恶劣得多的境遇的法国难友要优越得多。","language":"中文","translation":false},{"id":"family-1-146","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不过，个体家庭决不是在任何地方和任何时候都具有像希腊人中间所有的那种古典的粗野形式。罗马人作为世界的未来征服者，具有虽不如希腊人细致但比他们远大的见识，在罗马人中间，妇女是比较自由和受尊敬的。罗马的男子认为，妻子的贞操已经由于他对妻子有生杀之权而得到了充分的保证。此外，这里妇女同男子一样，可以自愿解除婚姻关系。但是，在个体婚制发展方面的最大进步，无疑是随着德意志人登上历史舞台而发生的，因为在德意志人中间，大概由于他们贫穷的缘故，专偶制看来在那个时候还没有从对偶制中完全发展起来。我们是根据塔西佗所提到的如下三种情况而得出这个结论的。第一，尽管十分尊重婚姻，——“他们以一个妻子为满足，妇女生活在被贞操防卫起来的环境中”[55]，——但是在他们的显要人物和部落首长中间却实行多妻制，同我们在实行对偶婚的美洲人中间看到的情况类似。第二，从母权制向父权制的过渡，在他们那里可能只是在前此不久的时候才完成的，因为母亲的兄弟——按照母权制是最近的男性的同氏族亲属——在他们那里仍然被认为是比自己的父亲更亲近的亲属，这一点也是与美洲印第安人的观点相一致的；正如马克思所常常说的，他在美洲印第安人中间找到了一把了解我们自己的原始时代的钥匙。第三，在德意志人中间，妇女很受尊敬并且对公共事务也有很大的影响，这同专偶制所特有的男子统治是直接对立的。差不多在这一切方面，德意志人都与斯巴达人相一致；正如我们已经看到的，在斯巴达人中间，对偶婚也还没有完全被放弃。[56]因此，在这方面，一个崭新的要素也随着德意志人的出现而获得了世界的统治。在各民族混合的过程中，在罗马世界的废墟上发展起来的新的专偶制，使男子的统治具有了比较温和的形式，而使妇女至少从外表上看来有了古典古代所从未有过的更受尊敬和更加自由的地位。从而就第一次造成了一种可能性，在这种可能性的基础上，从专偶制之中——因情况的不同，或在它的内部，或与它并行，或与它相反——发展起来了我们应归功于专偶制的最伟大的道德进步：整个过去的世界所不知道的现代的个人性爱。","language":"中文","translation":false},{"id":"family-1-147","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，这个进步无疑是由这样的情况引起的，即德意志人还生活在对偶制家庭中，他们在可能的范围内把适应于对偶制家庭的妇女地位嫁接到专偶制上来；这一进步决不是由于德意志人的什么传奇性的、道德上纯洁得神奇的天性所引起的，这种天性只不过是：对偶制实际上并不像专偶制那样在明显的道德对立中前进的。恰好相反，德意志人在其迁徒时期，特别是在向东南方，即黑海沿岸草原游牧民族区迁徙时期，在道德上堕落得很厉害，除骑马术以外，他们还从这些游牧民族那里染上了丑恶的反常情的恶习，阿米亚努斯关于泰发耳人，普罗科皮阿斯关于海鲁莱人的叙述就是明显的证明。45","language":"中文","translation":false},{"id":"family-1-148","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不过，如果说在我们所知道的一切家庭形式中，专偶制是现代的性爱能在其中发展起来的唯一形式，那么这并不是说，现代的性爱作为夫妇相互的爱完全或主要是在这一形式中发展起来的。在男子统治下的牢固的个体婚制的整个本质，是排斥这一点的。在一切历史上主动的阶级中间，即在一切统治阶级中间，婚姻的缔结和对偶婚以来的做法相同，仍然是一种由父母安排的、权衡利害的事情。所以，第一个出现在历史上的性爱形式，亦即作为热恋，作为每个人(至少是统治阶级中的每个人)都能享受到的热恋，作为性的冲动的最高形式(这正是性爱的特性)，而第一个出现的性爱形式，那种中世纪的骑士之爱，就根本不是夫妇之爱。恰好相反，古典方式的、普罗旺斯人的骑士之爱，正是极力要破坏夫妻的忠实，而他们的诗人们所歌颂的也正是这个。Albas，用德文来说就是破晓歌，是普罗旺斯爱情诗46的精华。它用热烈的笔调描写骑士怎样睡在他的情人——别人的妻子——的床上，门外站着侍卫，一见晨曦(alba)初上，便通知骑士，使他能悄悄地溜走，而不被人发觉；接着是叙述离别的情景，这是歌词的最高潮。北部法兰西人和老实的德意志人，也学到了这种诗体和与它相适应的骑士爱的方式，而我们的老沃尔弗拉姆·冯·埃申巴赫也以这种挑逗性的主题留下了三首美妙的破晓歌，我觉得这些诗歌比他的三篇很长的英雄诗更好。","language":"中文","translation":false},{"id":"family-1-149","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在今日的资产阶级中间，缔结婚姻有两种方式。在天主教国家中，父母照旧为年轻的资产阶级儿子选择适当的妻子，其结果自然是专偶制所固有的矛盾得到了最充分的发展：丈夫方面是大肆实行淫游婚，妻子方面是大肆通奸。天主教会禁止离婚，恐怕也只是因为它确信对付通奸就像对付死亡一样，是没有任何药物可治的。相反，在新教国家中，通例是允许资产阶级的儿子有或多或少的自由去从本阶级选择妻子；因此，一定程度的爱可能成为结婚的基础，而且，为了体面，也始终以此为前提，这一点符合新教伪善的精神。在这里，丈夫实行淫游婚并不那么厉害，而妻子的通奸也比较不那么常见。不过，在任何婚姻形式下，人们结婚后和结婚前仍然是同样的人，而新教国家的资产者又大多是些庸人，所以，这种新教的专偶制，即使拿一般最好的场合来看，也只不过是导致被叫作家庭幸福的极端枯燥无聊的婚姻共同体罢了。小说就是这两种缔结婚姻的方法的最好的镜子：法国的小说是天主教婚姻的镜子；德国的[57]小说是新教婚姻的镜子。在两种场合，“他都有所得”；在德国小说中是青年得到了少女；在法国小说中是丈夫得到了绿帽子。两者之中究竟谁的处境更坏，不是常常都可以弄清楚的。因此，德国小说的枯燥之于法国资产者，正如法国小说的“不道德”之于德国的庸人一样是令人不寒而栗的。可是，最近，自从“柏林成为世界都市”以来，德国小说也开始不那么胆怯地描写当地早就为人所知的淫游和通奸了。","language":"中文","translation":false},{"id":"family-1-150","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，在这两种场合，婚姻都是由当事人的阶级地位来决定的，因此总是权衡利害的婚姻。[58]这种权衡利害的婚姻，在两种场合都往往变为最粗鄙的卖淫——有时是双方的，而以妻子为最通常。妻子和普通的娼妓不同之处，只在于她不是像雇佣女工做计件工作那样出租自己的身体，而是把身体一次永远出卖为奴隶。所以，傅立叶的一句话，可适用于一切权衡利害的婚姻，他说：","language":"中文","translation":false},{"id":"family-1-151","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“正如在文法上两个否定构成一个肯定一样，在婚姻道德上两个卖淫则算作一个美德。”47","language":"中文","translation":false},{"id":"family-1-152","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"只有在被压迫阶级中间，而在今天就是在无产阶级中间，性爱才成为而且也才可能成为对妇女的关系的常规，不管这种关系是否为官方所认可。不过，在这里，古典的专偶制的全部基础也就除去了。在这里没有任何财产，而专偶制和男子的统治原是为了保存和继承财产而建立的；因此，在这里也就没有建立男子统治的任何推动力了。况且，在这里也没有达到这个目的的手段：维护男子统治的资产阶级法律，只是为了有产者和为了他们同无产者的相互关系而存在的；它是要钱的，而因为工人贫穷的缘故，它对于工人同他的妻子的关系就没有效力了。在这里，起决定作用的完全是另一种个人的和社会的关系。此外，自从大工业迫使妇女从家庭进入劳动市场和工厂，而且往往把她们变为家庭的供养者以后，在无产者家庭中，除了自专偶制出现以来就蔓延开来的对妻子的野蛮粗暴也许还遗留一些以外，男子统治的最后残余也已失去了任何基础。这样一来，无产者的家庭，甚至在双方都保持最热烈的爱情和最牢固的忠实的情况下，也不管有可能得到什么宗教的和世俗的祝福，也不再是严格意义上的专偶制的家庭了。所以，专偶制的经常伴侣——淫游和通奸，在这里只有极其微小的作用；妻子事实上重新取得了离婚的权利，当双方不能和睦相处时，他们就宁愿分离。一句话，无产者的婚姻之为专偶制，是在这个名词的词源学意义上说的，决不是在这个名词的历史意义上说的。[59]诚然，我们的法学家认为，立法的进步使妇女越来越失去申诉不平的任何根据。现代各文明国家的法律体系越来越承认，第一，为了使婚姻有效，它必须是一种双方自愿缔结的契约；第二，在结婚同居期间，双方在相互关系上必须具有平等的权利和义务。如果这两种要求都能彻底实现，那么妇女就有了她们所能希望的一切了。","language":"中文","translation":false},{"id":"family-1-153","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这种纯法律的论据，同激进的共和派资产者用来击退和安抚无产者的论据完全一样。劳动契约据说是由双方自愿缔结的。而只要法律在字面上规定双方平等，这个契约就算是自愿缔结。至于不同的阶级地位给予一方的权力，以及这一权力加于另一方的压迫，即双方实际的经济地位，——这是与法律毫不相干的。在劳动契约有效期间，只要此方或彼方没有明白表示放弃，双方仍然被认为是权利平等的。至于经济地位迫使工人甚至把最后一点表面上的平等权利也放弃掉，这又是与法律无关。","language":"中文","translation":false},{"id":"family-1-154","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在婚姻问题上，即使是最进步的法律，只要当事人让人把他们出于自愿一事正式记录在案，也就十分满足了。至于法律幕后的现实生活发生了什么事，这种自愿是怎样造成的，关于这些，法律和法学家都可以置之不问。但是，最简单的法制比较，在这里也会向法学家们表明，这种自愿究竟是怎么一回事。在法律保证子女继承父母财产的应得部分，因而不能剥夺他们继承权的各国，——在德国，在采用法国法制的各国以及其他一些国家中——子女的婚事必须得到父母的同意。在采用英国法制的各国，法律并不要求结婚要得到父母的同意，在这些国家，父母对自己的财产也有完全的遗赠自由，他们可以任意剥夺子女的继承权。很明显，尽管如此，甚至正因为如此，在英国和美国，在有财产可继承的阶级中间，结婚的自由在事实上丝毫也不比在法国和德国更多些。","language":"中文","translation":false},{"id":"family-1-155","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"男女婚后在法律上的平等权利，情况也不见得更好些。我们从过去的社会关系中继承下来的两性的法律上的不平等，并不是妇女在经济上受压迫的原因，而是它的结果。在包括许多夫妇和他们的子女的古代共产制家户经济中，委托妇女料理的家务，正如由男子获得食物一样，都是一种公共的、为社会所必需的事业。随着家长制家庭，尤其是随着专偶制个体家庭的产生，情况就改变了。家务的料理失去了它的公共的性质。它与社会不再相干了。它变成了一种私人的服务；妻子成为主要的家庭女仆，被排斥在社会生产之外。只有现代的大工业，才又给妇女——只是给无产阶级的妇女——开辟了参加社会生产的途径。但在这种情况下，如果她们仍然履行自己对家庭中的私人的服务的义务，那么她们就仍然被排除于公共的生产之外，而不能有什么收入了；如果她们愿意参加公共的事业而有独立的收入，那么就不能履行家庭中的义务。不论在工厂里，或是在一切行业直到医务和律师界，妇女的地位都是这样的。现代的个体家庭建立在公开的或隐蔽的妇女的家务奴隶制之上，而现代社会则是纯粹以个体家庭为分子而构成的一个总体。现在在大多数情形之下，丈夫都必须是挣钱的人，赡养家庭的人，至少在有产阶级中间是如此，这就使丈夫占据一种无需有任何特别的法律特权的统治地位。在家庭中，丈夫是资产者，妻子则相当于无产阶级。不过，在工业领域内，只有在资本家阶级的一切法定的特权被废除，而两个阶级在法律上的完全平等的权利确立以后，无产阶级所受的经济压迫的独特性质，才会最明白地显露出来；民主共和国并不消除两个阶级的对立，相反，正是它才提供了一个为解决这一对立而斗争的地盘。同样，在现代家庭中丈夫对妻子的统治的独特性质，以及确立双方的真正社会平等的必要性和方法，只有当双方在法律上完全平等的时候，才会充分表现出来。那时就可以看出，妇女解放的第一个先决条件就是一切女性重新回到公共的事业中去；而要达到这一点，又要求消除个体家庭作为社会的经济单位的属性。","language":"中文","translation":false},{"id":"family-1-156","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，我们便有了三种主要的婚姻形式，这三种婚姻形式大体上与人类发展的三个主要阶段相适应。群婚制是与蒙昧时代相适应的，对偶婚制是与野蛮时代相适应的，以通奸和卖淫为补充的专偶制是与文明时代相适应的。在野蛮时代高级阶段，在对偶婚制和专偶制之间，插入了男子对女奴隶的统治和多妻制。","language":"中文","translation":false},{"id":"family-1-157","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"以上全部论述证明，在这种顺序中所表现的进步，其特征就在于，妇女越来越被剥夺了群婚的性的自由，而男性却没有被剥夺。的确，群婚对于男子到今天事实上仍然存在着。凡在妇女方面被认为是犯罪并且要引起严重的法律后果和社会后果的一切，对于男子却被认为是一种光荣，至多也不过被当作可以欣然接受的道德上的小污点。但是，自古就有的淫游制现在在资本主义商品生产的影响下变化越大，越适应于资本主义商品生产，越变为露骨的卖淫，它在道德上的腐蚀作用也就越大。而且它在道德上对男子的腐蚀，比对妇女的腐蚀要厉害得多。卖淫只是使妇女中间不幸成为受害者的人堕落，而且她们也远没有堕落到普通所想象的那种程度。与此相反，它败坏着全体男子的品格。所以，举例来说，长期的未婚夫状态，十中有九都是婚后不忠实的真正的预备学校。","language":"中文","translation":false},{"id":"family-1-158","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，我们现在正在走向一种社会变革，那时，专偶制的迄今存在的经济基础，正像它的补充物即卖淫的经济基础一样，不可避免地都要消失。专偶制的产生是由于，大量财富集中于一人之手，也就是男子之手，而且这种财富必须传给这一男子的子女，而不是传给其他人的子女。为此，就需要妻子方面的专偶制，而不是丈夫方面的专偶制，所以这种妻子方面的专偶制根本不妨碍丈夫的公开的或秘密的多偶制。但是，行将到来的社会变革至少将把绝大部分耐久的、可继承的财富——生产资料——变为社会所有，从而把这一切传授遗产的关切减少到最低限度。可是，既然专偶制是由于经济的原因而产生的，那么当这种原因消失的时候，它是不是也要消失呢？","language":"中文","translation":false},{"id":"family-1-159","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"可以不无理由地回答：它不仅不会消失，而且相反地，只有那时它才能完全地实现。因为随着生产资料转归社会所有，雇佣劳动、无产阶级、从而一定数量的——用统计方法可以计算出来的——妇女为金钱而献身的必要性，也要消失了。卖淫将要消失，而专偶制不仅不会灭亡，而且最后对于男子也将成为现实。","language":"中文","translation":false},{"id":"family-1-160","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样一来，男子的地位无论如何要发生很大的变化。而妇女的地位，一切妇女的地位也要发生很大的转变。随着生产资料转归公有，个体家庭就不再是社会的经济单位了。私人的家务变为社会的事业。孩子的抚养和教育成为公共的事情；社会同等地关怀一切儿童，无论是婚生的还是非婚生的。因此，对于“后果”的担心也就消除了，这种担心在今天成了妨碍少女毫无顾虑地委身于所爱的男子的最重要的社会因素——既是道德的也是经济的因素。那么，会不会由于这个原因，就足以逐渐产生更随便的性关系，从而也逐渐产生对处女的荣誉和女性的羞耻都更加马虎的社会舆论呢？最后，难道我们没有看见，在现代世界上专偶制和卖淫虽然是对立物，却是不可分离的对立物，是同一社会秩序的两极吗？能叫卖淫消失而不叫专偶制与它同归于尽吗？","language":"中文","translation":false},{"id":"family-1-161","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在这里，一个在专偶制发展的时候最多只处于萌芽状态的新的因素——个人的性爱，开始发生作用了。","language":"中文","translation":false},{"id":"family-1-162","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在中世纪以前，是谈不到个人的性爱的。不言而喻，形态的美丽、亲密的交往、融洽的情性等等，都曾引起异性对于发生性关系的热望；同谁发生这种最亲密的关系，无论对男子还是对女子都不是完全无所谓的。但是这距离现代的性爱还很远很远。在整个古代，婚姻都是由父母为当事人缔结的，当事人则安心顺从。古代所仅有的那一点夫妇之爱，并不是主观的爱好，而是客观的义务；不是婚姻的基础，而是婚姻的附加物。现代意义上的爱情关系，在古代只是在官方社会以外才有。忒俄克里托斯和莫斯库斯曾歌颂其爱情的喜悦和痛苦的那些牧人，朗格的达夫尼斯和赫洛娅，全都是不参与国家事务，不参与自由民活动的奴隶。而除去奴隶以外，我们所遇到的爱情纠纷只是灭亡中的古代世界解体的产物，而且是与同样也处在官方社会以外的妇女，与淫游女，即异地妇女或被释女奴隶发生的纠纷：在雅典是从它灭亡的前夜开始，在罗马是在帝政时代。如果说在自由民男女之间确实发生过爱情纠纷，那只是就婚后通奸而言的。所以，对于那位古代的古典爱情诗人老阿那克里翁来说，现代意义上的性爱竟是如此无关紧要，以致被爱者的性别对于他来说也成了无关紧要的事情。","language":"中文","translation":false},{"id":"family-1-163","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"现代的性爱，同古代人的单纯的性要求，同厄洛斯［情欲］，是根本不同的。第一，性爱是以所爱者的对应的爱为前提的；从这方面说，妇女处于同男子平等的地位，而在古代的厄洛斯时代，决不是一向都征求妇女同意的。第二，性爱常常达到这样强烈和持久的程度，如果不能结合和彼此分离，对双方来说即使不是一个最大的不幸，也是一个大不幸；为了能彼此结合，双方甘冒很大的危险，直至拿生命孤注一掷，而这种事情在古代充其量只是在通奸的场合才会发生。最后，对于性关系的评价，产生了一种新的道德标准，人们不仅要问：它是婚姻的还是私通的，而且要问：是不是由于爱和对应的爱而发生的？自然，在封建的或资产阶级的实践中，这个新的标准，并不比其他一切道德标准的境遇更好——人们对它视若无睹。不过，它的境遇也并非更坏；它和其他道德标准一样——在理论上，在字面上，也是被承认的。而更高的要求目前它就不能提了。","language":"中文","translation":false},{"id":"family-1-164","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"中世纪是从具有性爱的萌芽的古代世界停止前进的地方接着向前走的，它以通奸的方式接着前进。我们已经叙述过那创造了破晓歌的骑士爱。从这种力图破坏婚姻的爱情，到那应该成为婚姻的基础的爱情，还有一段漫长的路程，这段路程骑士们将永远走不到尽头。甚至我们由轻浮的罗曼语族各民族进而考察有德行的德意志人时，在《尼贝龙根之歌》中也可以发现，克里姆希耳德虽然暗中钟情于齐格弗里特，并不亚于齐格弗里特对她的钟情，但是当贡特尔宣布已把她许配给一个骑士(他没有说出他的名字)时，她却简单地回答道：","language":"中文","translation":false},{"id":"family-1-165","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“您不必问我；您要我怎样，我总是照办；老爷，您要我嫁给谁，我就乐意和他订婚。”[60]她甚至连想也没有想，她的爱情在这里是可以加以考虑的。贡特尔向布龙希耳德求婚，埃策耳向克里姆希耳德求婚，他们一次也不曾见过她们；同样，在《古德龙》48中，爱尔兰的齐格班特向挪威的乌黛求婚，黑盖林格的黑特耳向爱尔兰的希尔达求婚，以及莫尔兰的齐格弗里特、诺曼的哈尔特木特和西兰的黑尔维希向古德龙求婚，都是如此；而这里第一次出现古德龙自愿嫁给黑尔维希。按照通例，年轻王公的未婚妻都是由父母选择的，要是后者还活着的话；否则他就同大诸侯们商议，自行选择，大诸侯们的意见在一切场合总是起着很大的作用。而且也不能不如此。对于骑士或男爵，像对于王公一样，结婚是一种政治的行为，是一种借新的联姻来扩大自己势力的机会；起决定作用的是家世的利益，而决不是个人的意愿。在这种条件下，爱情怎能对婚姻问题有最后决定权呢？","language":"中文","translation":false},{"id":"family-1-166","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"中世纪城市的行会市民，也是如此。单是保护着他的那些特权，带有各种限制的行会规约，在法律上把他或者同别的行会、或者同本行会的同事、或者同他的帮工和学徒分开的种种人为的界限，就大大缩小了他寻求适当的妻子的范围。至于这些女子当中谁是最适当的，在这种错综复杂的体系下，决定这个问题的绝对不是他个人的意愿，而是家庭的利益。","language":"中文","translation":false},{"id":"family-1-167","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"因此，直到中世纪末期，在绝大多数场合，婚姻的缔结仍然和最初一样，不是由当事人决定的事情。起初，人们一出世就已经结了婚——同整个一群异性结了婚。在较后的各种群婚形式中，大概仍然存在着类似的状态，只是群的范围逐渐缩小罢了。在对偶婚之下，通例是由母亲给自己的子女说定婚事；在这里关于新的亲戚关系的考虑也起着决定的作用，这种新的亲戚关系应该使年轻夫妇在氏族和部落中占有更牢固的地位。当父权制和专偶制随着私有财产的份量超过共同财产以及随着对继承权的关切而占了统治地位的时候，结婚便更加依经济上的考虑为转移了。买卖婚姻的形式正在消失，但它的实质却在越来越大的范围内实现，以致不仅对妇女，而且对男子都规定了价格，而且不是根据他们的个人品质，而是根据他们的财产来规定价格。当事人双方的相互爱慕应当高于其他一切而成为婚姻基础的事情，在统治阶级的实践中是自古以来都没有的。至多只是在浪漫故事中，或者在不受重视的被压迫阶级中，才有这样的事情。","language":"中文","translation":false},{"id":"family-1-168","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这就是从地理发现的时代起，资本主义生产通过世界贸易和工场手工业而准备取得世界统治的时候它所遇到的状况。人们应该认为，这种结婚方式对于资本主义生产是非常合适的，而事实上也确实如此。但是——世界历史的讽刺神秘莫测——正是资本主义生产注定要把这种结婚方式打开一个决定性的缺口。它把一切变成了商品，从而消灭了过去留传下来的一切古老的关系，它用买卖、“自由”契约代替了世代相因的习俗，历史的法。英国的法学家亨·萨·梅恩说，同以前的各个时代相比，我们的全部进步就在于从身分到契约，从过去留传下来的状态进到自由契约所规定的状态49，他自以为他的这种说法是一个伟大的发现，其实，这一点，就其正确之处而言，在《共产党宣言》中早已说过了[61]。","language":"中文","translation":false},{"id":"family-1-169","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"然而，只有能够自由地支配自己的人身、行动和财产并且彼此权利平等的人们才能缔结契约。创造这种“自由”而“平等”的人们，正是资本主义生产的主要工作之一。虽然这在最初不过是半自觉地发生的，并且穿上了宗教的外衣，但是自路德和加尔文的宗教改革以来，就牢固地确立了一个原则，即一个人只有在他握有意志的完全自由去行动时，他才能对他的这些行动负完全的责任，而对于任何强迫人从事不道德行为的做法进行反抗，乃是道德上的义务。但是这同迄今为止的订立婚约的实践怎么能协调起来呢？按照资产阶级的理解，婚姻是一种契约，是一种法律行为，而且是一种最重要的法律行为，因为它就两个人终身的肉体和精神的问题作出规定。虽然这种契约那时在形式上是自愿缔结的；没有当事人双方的同意就不能解决问题。不过人人都非常明白，这一同意是如何取得的，实际上是谁在订立婚约。然而，在缔结别的契约时要求真正自由的决定，那么在订立婚约时为什么不要求这种自由呢？难道两个将要被撮合的青年人没有权利自由地支配他们自己、他们的身体以及身体的器官吗？难道性爱不是由于骑士而成为时髦，对比骑士的通奸之爱，难道夫妇之爱不是性爱的正确的资产阶级形式吗？既然彼此相爱是夫妇的义务，难道相爱者彼此结婚而不是同任何别人结婚不同样也是他们的义务吗？难道相爱者的这种权利不是高于父母、亲属以及其他传统的婚姻中介人和媒妁的权利吗？既然自由的、个人审定的权利已经无礼地侵入教会和宗教的领域，它怎么能在老一代支配下一代的身体、精神、财产、幸福和不幸这种无法容忍的要求面前停步呢？","language":"中文","translation":false},{"id":"family-1-170","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这些问题，在社会的一切旧有的联系正在松弛，而一切因袭的观念正在动摇的时候，是必然要提出来的。世界一下子大了差不多十倍；现在展现在西欧人眼前的，已不是一个半球的四分之一，而是整个地球了，他们赶紧去占据其余的七个四分之一。传统的中世纪思想方式的千年藩篱，同旧日的狭隘的故乡藩篱一样崩溃了。在人的外在的眼睛和内心的眼睛前面，都展开了无比广大的视野。在为印度的财富、墨西哥和波托西的金矿银矿所引诱的青年男子看来，尊长们的赞许以及世代相传的荣耀的行会特权能有什么意义呢？这是资产阶级的漫游骑士的时代；这个时代也有自己的浪漫故事和爱情幻想，但都是按照资产阶级的方式，而且归根到底是抱着资产阶级的目的。","language":"中文","translation":false},{"id":"family-1-171","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"于是就发生了这样的情况：正在兴起的资产阶级，特别是在现存制度最受动摇的新教国家里，都越来越承认在婚姻方面也有缔结契约的自由，并用上述方式来实现这一自由。婚姻仍然是阶级的婚姻，但在阶级内部则承认当事者享有某种程度的选择的自由。在字面上，在道德理论上以及在诗歌描写上，再也没有比认为不以夫妻相互性爱和真正自由的协议为基础的任何婚姻都是不道德的那种观念更加牢固而不可动摇的了。总之，恋爱婚姻被宣布为人权，并且不仅是droit de l′homme[62]，而且在例外的情况下也是妇女的权利。","language":"中文","translation":false},{"id":"family-1-172","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，这种人权有一点是与其他一切所谓人权不同的。当后者实际上只限于统治阶级即资产阶级，而对于被压迫阶级即无产阶级则直接或间接地被削减了的时候，历史的讽刺又经受了考验。统治阶级仍然为众所周知的经济影响所支配，因此在他们中间，真正自由缔结的婚姻只是例外，而在被统治阶级中间，像我们所已看到的，这种婚姻却是通例。","language":"中文","translation":false},{"id":"family-1-173","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"因此，结婚的充分自由，只有在消灭了资本主义生产和它所造成的财产关系，从而把今日对选择配偶还有巨大影响的一切附加的经济考虑消除以后，才能普遍实现。到那时，除了相互的爱慕以外，就再也不会有别的动机了。","language":"中文","translation":false},{"id":"family-1-174","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"既然性爱按其本性来说就是排他的，——虽然这种排他性今日只是在妇女身上无例外地得到实现，——那么，以性爱为基础的婚姻，按其本性来说就是个体婚姻。我们已经看到，巴霍芬认为由群婚向个体婚的过渡这一进步主要应归功于妇女，是多么的正确；只有由对偶婚制向专偶制的进步才是男子的功劳；在历史上，后一进步实质上是使妇女地位恶化，而便利了男子的不忠实。因此，只要那种迫使妇女容忍男子的这些通常的不忠实行为的经济考虑——例如对自己的生活，特别是对自己子女的未来的担心——一旦消失，那么由此而达到的妇女的平等地位，根据以往的全部经验来判断，与其说会促进妇女的多夫制，倒不如说会在无比大的程度上促进男子的真正的专偶制。","language":"中文","translation":false},{"id":"family-1-175","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，专偶制完全肯定地将要失掉的东西就是，它因起源于财产关系而被烙上的全部特征，这些特征就是：第一，男子的统治，第二，婚姻的不可解除性。男子在婚姻上的统治是他的经济统治的简单的后果，它将自然地随着后者的消失而消失。婚姻的不可解除性，部分地是专偶制所赖以产生的经济状况的结果，部分地是这种经济状况和专偶制之间的联系还没有被正确地理解并且被宗教加以夸大的那个时代留下的传统。这种不可解除性现在就已经遭到千万次的破坏了。如果说只有以爱情为基础的婚姻才是合乎道德的，那么也只有继续保持爱情的婚姻才合乎道德。不过，个人性爱的持久性在各个不同的个人中间，尤其在男子中间，是很不相同的，如果感情确实已经消失或者已经被新的热烈的爱情所排挤，那就会使离婚无论对于双方或对于社会都成为幸事。只是要使人们免于陷入离婚诉讼的无益的泥潭才好。","language":"中文","translation":false},{"id":"family-1-176","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，我们现在关于资本主义生产行将消灭以后的两性关系的秩序所能推想的，主要是否定性质的，大都限于将要消失的东西。但是，取而代之的将是什么呢？这要在新的一代成长起来的时候才能确定：这一代男子一生中将永远不会用金钱或其他社会权力手段去买得妇女的献身；而这一代妇女除了真正的爱情以外，也永远不会再出于其他某种考虑而委身于男子，或者由于担心经济后果而拒绝委身于她所爱的男子。这样的人们一经出现，对于今日人们认为他们应该做的一切，他们都将不去理会，他们自己将做出他们自己的实践，并且造成他们的据此来衡量的关于各人实践的社会舆论——如此而已。","language":"中文","translation":false},{"id":"family-1-177","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":177,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"现在让我们再回过来谈摩尔根吧，我们已经把他丢开很远了。对于在文明时期发展起来的社会制度进行历史的考察，是超出了他的著作的范围的。所以，他只是非常简单地论述了一下专偶制在这一时期的命运。他也认为专偶制家庭的进一步发展是一种进步，是一种向两性权利完全平等的接近，而这一目标他并不认为已经达到了。不过，他说：","language":"中文","translation":false},{"id":"family-1-178","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":178,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“如果承认家庭已经依次经过四种形式而现在正处在第五种形式中这一事实，那就要产生一个问题：这一形式在将来会不会永久存在？可能的答案只有一个：它正如迄今的情形一样，一定要随着社会的发展而发展，随着社会的变化而变化。它是社会制度的产物，它将反映社会制度的发展状况。既然专偶制家庭从文明时代开始以来，已经改进了，而在现代特别显著，那么我们至少可以推测，它能够进一步完善，直至达到两性的平等为止。如果专偶制家庭在遥远的将来不能满足社会的需要，那也无法预言，它的后继者将具有什么性质了。”50","language":"中文","translation":false},{"id":"family-1-179","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":179,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们现在来谈一谈摩尔根的另一发现，这一发现至少与他根据亲属制度恢复原始家庭形式有着同等重要的意义。摩尔根证明：美洲印第安人部落内部用动物名称命名的血族团体，实质上是与希腊人的genea［氏族］、罗马人的gentes［氏族］相同的；美洲的形式是原始的形式，而希腊－罗马的形式是晚出的、派生的形式；原始时代希腊人和罗马人的氏族、胞族和部落的全部社会组织，跟美洲印第安人的组织极其相似；氏族，直到野蛮人进入文明时代为止，甚至再往后一点，是一切野蛮人所共有的制度(就现有资料而言)。摩尔根证明了这一切以后，便一下子说明了希腊、罗马上古史中最困难的地方，同时，出乎意料地给我们阐明了原始时代——国家产生以前社会制度的基本特征。虽然这个发现在人们一旦知道它之后显得十分简单，但是，摩尔根只是最近才做到这一点的；在他于1871年出版的前一部著作中，他还没有看透这个秘密，而这个秘密一揭开之后，就使一向那样自信的英国原始史学家们一时[63]沉默了下去。","language":"中文","translation":false},{"id":"family-1-180","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":180,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根普遍用以表示这种血族团体的拉丁语gens［氏族］一词，像同意义的希腊语genos一词一样，来源于共同雅利安语的字根gan(德语为kan，因为在德语中，通例是用k代替雅利安语的g)，gan的意思是“生育”。Gens，genos，梵语的dschanas，哥特语(依照上面所说的通例)的kuni，古代斯堪的纳维亚语和盎格鲁撒克逊语的kyn，英语的kin，中古高地德意志语的，都同样表示血族、世系。不过拉丁语的gens和希腊语的genos，都是专用以表示这样的一种血族团体，这种团体自夸有共同的世系(这里指的是出自一个共同的男始祖)，并且借某种社会的和宗教的制度而组成一个特殊的公社。但是这种血族团体的起源与本性，我们的一切历史编纂学家迄今为止却一直弄不清楚。","language":"中文","translation":false},{"id":"family-1-181","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":181,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们在前面，在研究普那路亚家庭时，已经看到原始形式的氏族是怎样构成的。凡由于普那路亚婚姻，并且依照这种婚姻中必然占统治地位的观念而构成一个确定的女始祖即氏族创立者的公认后代的人，都是这种氏族的成员，这样就组成了氏族。由于在这种家庭形式下父系血统不能确定，所以只承认女系。又由于兄弟不得娶自己的姊妹为妻，只能同其他世系的妇女结婚，所以，根据母权制，同这些异族妇女所生的子女，便列在氏族以外。这样，留在血族团体内部的只有各代女儿的子孙；儿子的子孙则归入其母亲的氏族。一候这种血缘亲属集团构成一个与同一部落内其他类似集团相对来说的特殊集团，它又是什么样子呢？","language":"中文","translation":false},{"id":"family-1-182","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":182,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"摩尔根举出易洛魁人的氏族，特别是塞讷卡部落的氏族，作为这种原始氏族的古典形式。这个部落内有八个氏族，都以动物的名称命名：(1)狼，(2)熊，(3)龟，(4)海狸，(5)鹿，(6)鹬，(7)苍鹭，(8)鹰。每个氏族内都盛行以下的习俗：","language":"中文","translation":false},{"id":"family-1-183","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":183,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.氏族选举一个酋长(平时的首脑)和一个酋帅(军事领袖)。酋长必须从本氏族成员中选出，他的职位在氏族内世袭，一旦出缺，必须立刻重新补上；军事领袖，也可以从氏族以外的人中选出并且有时可以暂缺。由于易洛魁人奉行母权制，因而酋长的儿子属于别一氏族，所以从不选举前一酋长的儿子做酋长，而是往往选举他的兄弟做酋长，或者选举他的姊妹的儿子做酋长。所有的人，无论男女，都参加选举。不过选举须经其余七个氏族确认，只有在这以后，当选为酋长的人才被隆重地，就是说由全易洛魁联盟的联合议事会委任。这样做的意义，在后面就可以看出来。酋长在氏族内部的权力，是父亲般的、纯粹道义性质的；他手里没有强制的手段。此外，由于他的职位，他也是塞讷卡部落议事会以及全体易洛魁人联盟的议事会的成员。酋帅仅仅在出征时才能发号施令。","language":"中文","translation":false},{"id":"family-1-184","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":184,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.氏族可以任意罢免酋长和酋帅。这仍是由男女共同决定的。被罢免的人，此后便像其他人一样成为普通战士，成为私人。此外，部落议事会也可以甚至违反氏族的意志而罢免酋长。","language":"中文","translation":false},{"id":"family-1-185","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":185,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"3.氏族的任何成员都不得在氏族内部通婚。这是氏族的根本规则，维系氏族的纽带；这是极其肯定的血缘亲属关系的否定表现，赖有这种血缘亲属关系，它所包括的个人才成为一个氏族。摩尔根由于发现了这个简单的事实，就第一次揭示了氏族的本质。从前关于蒙昧人和野蛮人的报告，把构成氏族制度的各种集团，糊里糊涂地、不加分别地混为一谈，统称为部落、克兰51、萨姆52等等，而且往往说，在这种集团内部禁止通婚，这证明以前人们对于氏族是多么不了解。这便造成了一种不可救药的混乱，麦克伦南先生就在这个混乱中得以充当拿破仑，用最后的判决建立了这样的秩序：一切部落分为部落内部禁止通婚的(外婚制的)和许可通婚的(内婚制的)两种。他这样把问题更加彻底混淆以后，便埋头于最深沉的研究中，去探讨在他的两个无聊乏味的类别中，究竟哪一种较古：是外婚还是内婚。自从发现了那以血缘亲属关系为基础的，因此其成员间不能通婚的氏族之后，这种荒谬的说法就不攻自破了。不言而喻，在我们见到易洛魁人时他们所处的那种发展阶段，氏族内部禁止通婚是被严格遵守着的。","language":"中文","translation":false},{"id":"family-1-186","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":186,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"4.死者的财产转归其余的同氏族人所有，它必须留在氏族中。因为易洛魁人所能遗留的东西为数很少，所以他的遗产就由他最近的同氏族亲属分享；男子死时，由他的同胞兄弟、姊妹以及母亲的兄弟分享；妇女死时，由她的子女和同胞姊妹而不是由她的兄弟分享。根据同一理由，夫妇不能彼此继承，子女也不得继承父亲。","language":"中文","translation":false},{"id":"family-1-187","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":187,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"5.同氏族人必须互相援助、保护，特别是在受到外族人伤害时，要帮助报仇。个人依靠氏族来保护自己的安全，而且也能做到这一点；凡伤害个人的，便是伤害了整个氏族。因而，从氏族的血族关系中便产生了那为易洛魁人所绝对承认的血族复仇的义务。假使一个氏族成员被外族人杀害了，那么被害者的全氏族就有义务实行血族复仇。起初是试行调解；行凶者的氏族议事会开会，大抵用道歉与赠送厚礼的方式，向被害者的氏族的议事会提议和平了结事件。如果提议被接受，事情就算解决了。否则，受害的氏族就指定一个或几个复仇者，他们的义务就是去追寻行凶者，把他杀死。如果这样做了，行凶者的氏族也没有诉怨的权利，事情就算了结了。","language":"中文","translation":false},{"id":"family-1-188","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":188,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"6.氏族有固定的人名或几套人名，在全部落内只有该氏族才能使用这些人名，因此，氏族个别成员的名字，也就表明了他属于哪一氏族。氏族的人名一开始就自行带来氏族的权利。","language":"中文","translation":false},{"id":"family-1-189","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":189,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"7.氏族可以接纳外人入族，并用这个办法吸收他们为整个部落的成员。这样，未杀死的俘虏，由于被一个氏族接纳入族，就成为塞讷卡部落的成员，从而获得了氏族和部落的一切权利。接纳外人入族的事情，是根据氏族的个别成员的提议而实行的：男子可以提议接纳外人为兄弟或姊妹；女子可以提议接纳外人为自己的孩子；为了确认这种接纳，必须举行入族仪式。个别因特殊情形而人丁不旺的氏族，常常由于大批接纳别一氏族(得到它的同意)的人入族而重新兴旺起来。在易洛魁人中间，入族仪式在部落议事会的公共集会上举行，实际上已经变为一种宗教仪式。","language":"中文","translation":false},{"id":"family-1-190","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":190,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"8.印第安人的氏族有无专有的宗教祭祀，很难确定；不过印第安人的宗教仪式多少都是和氏族联系在一起的。在易洛魁人的六个一年一度的宗教节日期间，各个氏族的酋长和酋帅，由于他们的职位，都被列在“信仰守护人”以内，而执行祭司的职能。","language":"中文","translation":false},{"id":"family-1-191","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":191,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"9.氏族有着共同的墓地。纽约州境内四周都为白种人包围的易洛魁人，他们的墓地现在已经绝迹了，但从前是存在过的。在其他印第安人那里，这种墓地还保存着；例如，和易洛魁人有近亲关系的吐斯卡罗腊人，他们虽然是基督徒，但在墓地上，每一氏族都独成一排，所以，总是把母亲而不是把父亲和孩子埋在一排。而在易洛魁人中间，死者的全氏族都要参加葬仪，营造坟墓，致悼词等等。","language":"中文","translation":false},{"id":"family-1-192","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":192,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"10.氏族有议事会，它是氏族的一切成年男女享有平等表决权的民主集会。这种议事会选举、罢免酋长和酋帅，以及其余的“信仰守护人”；它作出为被杀害的氏族成员接受赎罪献礼(杀人赔偿金)或实行血族复仇的决定；它收养外人加入氏族。总之，它是氏族的最高权力机关。","language":"中文","translation":false},{"id":"family-1-193","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":193,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"典型的印第安人氏族的职能就是这样。","language":"中文","translation":false},{"id":"family-1-194","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":194,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“它的全体成员都是自由人，都有相互保卫自由的义务；在个人权利方面平等，不论酋长或酋帅都不能要求任何优越权；他们是由血亲纽带结合起来的同胞。自由、平等、博爱，虽然从来没有明确表达出来，却是氏族的根本原则，而氏族又是整个社会制度的单位，是有组织的印第安人社会的基础。这就可以说明，为什么印第安人具有那种受到普遍承认的强烈的独立感和自尊心。”53到发现美洲的时候，全北美洲的印第安人都是按照母权制组成为氏族。仅在某几个部落如达科塔人的部落，氏族已然衰落；在另外几个部落中间，如在奥季布瓦，奥马哈等部落中间，氏族已经是按照父权制组成了。","language":"中文","translation":false},{"id":"family-1-195","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":195,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在许多有五六个以上氏族的印第安人部落中间，我们遇到，每三四个或更多的氏族联合成一个特殊的集团，摩尔根按照它的极相似的希腊式样忠实地把印第安语的名称译过来，把这种集团叫作Phratrie(胞族)。例如，塞讷卡部落有两个胞族；第一个胞族包括1－4四个氏族，第二个胞族包括5－8四个氏族。更详细的研究表明，这种胞族大抵是当初由部落分裂成的最初的氏族；因为在氏族内部禁止通婚的情况下，每个部落必须至少包括两个氏族才能独立存在。随着部落的增殖，每个氏族又分裂成两个或两个以上的氏族，这些氏族如今也作为单个的氏族而存在；而包括一切女儿氏族的最初的氏族，则作为胞族继续存在。在塞讷卡人和大多数其他印第安人中间，一个胞族内的各氏族被认为是兄弟氏族，而别个胞族的各氏族则被认为是它们的从兄弟氏族，——这种称呼，在美洲亲属制度中，像我们在前边所看到的，都具有极其真实而明确的意义。塞讷卡人起初在胞族内也不能通婚，但是这种习俗久已废除了，如今只限于氏族。塞讷卡部落有一种传说，“熊”和“鹿”两个氏族是最初的氏族，其他氏族都是从这两个氏族分化出来的。这个新组织扎下根以后，便根据需要而改变；要是某一胞族的一些氏族灭亡了，那么为均衡起见，有时就从别的胞族中拨几个氏族去补充它。因此，我们在不同的部落中间，可以看到名称相同的氏族以不同的方式集结在各胞族中。","language":"中文","translation":false},{"id":"family-1-196","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":196,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"易洛魁人的胞族的职能，部分地是社会性质的，部分地是宗教性质的。(1)胞族间互相赛球竞技；每一胞族派出自己的优秀球员，其余的人按胞族旁立观看，并以本胞族球员的获胜打赌。(2)在部落议事会上，每个胞族的酋长和军事领袖坐在一起，两个胞族彼此相对，每个发言者都面对各胞族的代表讲话，把他们当作特别的团体。(3)如果部落内发生杀人事件，而行凶者与被害者不属于同一个胞族时，被害者的氏族往往诉诸自己的兄弟氏族；于是这些氏族就举行胞族议事会，把对方胞族作为一个整体进行交涉，使对方胞族也召集自己的议事会，以谋求事件的解决。因此，在这里，胞族又以最初的氏族的资格出现，并且比它派生的较微弱的单个氏族更有获胜的希望。(4)在重要人物死亡时，对方胞族办理安葬和丧礼，而死者胞族的成员则以死者的近亲服丧人资格参与葬仪。酋长死时，对方胞族将出缺一事通知易洛魁人的联盟议事会。(5)在选举酋长时，胞族议事会也出面参预。兄弟氏族对选举的确认，被认为是一种当然的事情；但另一个胞族的氏族则可能提出异议。在这种情况下，这个胞族的议事会即召开会议；如果议事会认为异议是正当的，选举就算无效。(6)从前，易洛魁人有一些特殊的宗教神秘仪式，白种人把它称为巫术集会。这种神秘仪式在塞讷卡人那里，是由两个宗教团体举行的；新会员入会时还举行正式的入会的仪式；两个胞族中各有一个这样的团体。(7)在征服时期[64]，住在特拉斯卡拉四个区的四个lineages(血族)，如果是——而这差不多是肯定的——四个胞族的话，那么这证明，像希腊人的胞族以及德意志人的类似的血族团体一样，这种胞族也都有军事单位的意义；这四个血族在作战时各成一队，各穿自己的制服，有自己的旗帜和自己的首领。","language":"中文","translation":false},{"id":"family-1-197","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":197,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"正如几个氏族组成一个胞族一样，几个胞族就古典形式来说则组成一个部落；而那些大大衰微的部落则往往没有胞族这种中间环节。那么，美洲印第安人部落有什么特征呢？","language":"中文","translation":false},{"id":"family-1-198","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":198,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.有自己的地区和自己的名称。每一部落除自己实际居住的地方以外，还占有相当大的地区供打猎和捕鱼之用。在这个地区之外，还有一块广阔的中立地带，一直延伸到邻近部落的地区边上；在语言接近的各部落中间，这种中立地带比较狭小，在语言不接近的各部落中间，中立地带比较宽大。这种地带跟德意志人的边境森林、凯撒的苏维汇人在他们地区四周所设的荒地相同；这也跟丹麦人和德意志人之间的(丹麦语为jarnved，limes Dani－cus)、德意志人和斯拉夫人之间的萨克森森林和branibor(斯拉夫语，意即“防卫林”，勃兰登堡这一名称即由此而来)相同。由这种不确定的疆界隔开的地区，乃是部落的公有土地，而为相邻部落所承认，并由部落自己来防卫，以免他人侵占。疆界的不确定，多半仅在人口大量增加的时候，才会在实际上感到不方便。部落的名称，看来多半是偶然发生，而不是有意选择的。随着时间的进展，往往一个部落被邻近各部落取了另外的名称，与该部落自己使用的名称不同，像德意志人的最初的历史上的总称“日耳曼人”是由克尔特人给他们取的一样。","language":"中文","translation":false},{"id":"family-1-199","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":199,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.有独特的、仅为这个部落所用的方言。事实上，部落和方言在实质上范围是一致的；因分裂而形成新部落与新方言的事情，不久以前还在美洲发生，即至今日，也未必完全停止。在两个衰落的部落合而为一的地方，有时例外地在同一个部落内说着两种极为相近的方言。美洲各部落的平均人数在2000人以下；但是彻罗基部落却有26000人，这是在合众国说同一方言的数目最多的印第安人。","language":"中文","translation":false},{"id":"family-1-200","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":200,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"3.有隆重委任氏族所选出的酋长和军事领袖的权利。","language":"中文","translation":false},{"id":"family-1-201","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":201,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"4.有罢免他们的权利，甚至可以违反他们氏族的愿望而罢免他们。由于这些酋长和军事领袖都是部落议事会的成员，部落对待他们有这种权利是当然的。凡已经组成部落联盟而且一切部落都有代表参加联盟议事会的地方，上述权利便转归联盟议事会了。","language":"中文","translation":false},{"id":"family-1-202","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":202,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"5.有共同的宗教观念(神话)和崇拜仪式。","language":"中文","translation":false},{"id":"family-1-203","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":203,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“印第安人，是按照野蛮人方式信仰宗教的人民。”54他们的神话迄今还远没有得到考证性的研究；他们已经给自己的宗教观念——各种精灵——赋予人的形象，但是他们还处在野蛮时代低级阶段，所以还不知道具体的造像，即所谓偶像。这是一种正向多神教发展的自然崇拜与自然力崇拜。各部落各有其定期的节日和一定的崇拜形式，特别是舞蹈和竞技；舞蹈尤其是一切宗教祭祀的主要组成部分；每一部落各自庆祝自己的节日。","language":"中文","translation":false},{"id":"family-1-204","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":204,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"6.有管理公共事务的部落议事会。它是由各个氏族的酋长和军事领袖组成的——这些人是氏族的真正代表，因为他们是随时都可以罢免的；议事会公开开会，四周围着其余的部落成员，这些成员有权加入讨论和发表自己的意见；决议则由议事会作出。按照通例，每个出席的人都可以随意发表意见，妇女也可以通过她们所选出的演说人陈述自己的意见。在易洛魁人中间，最后的决定需要一致通过，跟德意志人的马尔克公社在作出某些决定时一样。部落议事会特别负有调整同其他部落的关系的责任；它接待和派遣使者，宣战及媾和。要是发生战争，大多由志愿者去作战。在原则上，每一个部落只要没有同其他部落订立明确的和平条约，它同这些部落便都算是处在战争状态。反对这种敌人的军事行动，大多由一些优秀的战士来组织；这些战士发起一个战争舞蹈，凡参加舞蹈的人，就等于宣告加入了出征队，队伍便立刻组织起来，即刻出动。部落的领土若被侵犯，其防卫也大多由志愿者来担任。这种队伍的出发和归来，总要举行公共的典礼。这种出征并不需要得到部落议事会的同意，没有人去征求这种同意，也没有人给予这种同意。这正和塔西佗所记述的德意志人扈从队的私人出征一样[65]，不过德意志人的扈从队伍，已具有比较常备的性质，而成为一种在平时也有组织，在战时团结其他志愿兵的强固核心了。这种武装队伍的人数一般不多；印第安人的最重要的出征，即使到距离很远的地方去，也是由不大的战斗力量来进行的。假如有几支这样的扈从队为了一次大规模战事而联合起来时，其中每支队伍只服从它自己的首领；作战计划的统一，好歹由这些首领的议事会来保证。据阿米亚努斯·马尔采利努斯的记载，4世纪阿勒曼尼人在上莱茵的作战方法，就是如此。","language":"中文","translation":false},{"id":"family-1-205","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":205,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"7.在有些部落中间，有一个最高的首领，但他的权力很小。他是酋长之一，当需要紧急行动时，他应当在议事会召集会议作出最后决定之前采取临时的措施。这是一种具有执行权力的官员的微弱萌芽，不过它在进一步发展方面多半都没有结果；这种官员，如我们在后面将要看到的，虽不是到处，但在大多数场合，都是由最高军事首长发展来的。","language":"中文","translation":false},{"id":"family-1-206","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":206,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"大多数的美洲印第安人，都没有超过联合为部落的阶段。他们的人数不多的部落，彼此由广大的边境地带隔离开来，而且为不绝的战争所削弱，这样他们就以少数的人口占有辽阔的地区。亲属部落间的联盟，常因暂时的紧急需要而结成，随着这一需要的消失即告解散。但在个别地方，最初本是亲属部落的一些部落从分散状态中又重新团结为永久的联盟，这样就朝民族［Nation］的形成跨出了第一步。在合众国，我们在易洛魁人中间，便可以见到这种联盟的最发达的形式。他们从密西西比河以西的地方(在这里，他们大概是很大的达科塔族系的一个分支)迁移出来，经过长期漂泊才定居在今日的纽约州，并分成了五个部落：塞讷卡，卡尤加，奥嫩多加，欧奈达及摩霍克。他们以捕鱼、打猎及原始园艺为生；住在大多用栅栏防卫起来的村落中。他们的人数从未超过两万；五个部落中有几个氏族是共同的；他们说着同一种语言的非常近似的方言，占有互相接壤的、为五个部落所瓜分的地区。因为这个地区是他们不久以前才征服来的，所以这些部落惯于团结起来对付被他们驱逐的部落，是自然而然的事。这样至迟到15世纪初，就发展成为一种正式的“永世联盟”，这种联盟，一经意识到它的新的实力，便立刻具有了进攻的性质，在1675年前后，当它达到了极盛的时候，便征服了它四周的广大土地，把这些地方上的居民一部分驱逐出境，一部分使之纳贡。易洛魁人联盟是尚未越过野蛮时代低级阶段的印第安人(因而，墨西哥人、新墨西哥人9和秘鲁人除外)所曾达到的最进步的社会组织。联盟的基本特点如下：","language":"中文","translation":false},{"id":"family-1-207","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":207,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.五个血缘亲属部落以完全平等和在部落的一切内部事务上的独立为基础，结成永世联盟。这种血缘亲属关系是联盟的真实基础。五个部落中有三个称为父亲部落，互为兄弟部落；其余两个称为儿子部落，也互为兄弟部落。有三个氏族——最老的——在五个部落中都还存在着，另外有三个氏族在三个部落中都还存在着；这些氏族中的每一个氏族，其成员在所有五个部落中都被认为是兄弟。仅在方言上有差异的共同语言，便是共同世系的表现和证明。","language":"中文","translation":false},{"id":"family-1-208","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":208,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.联盟的机关是联盟议事会，由50个地位和威信平等的酋长组成；这个议事会对联盟的一切事务作最后的决定。","language":"中文","translation":false},{"id":"family-1-209","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":209,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"3.这50个酋长，在联盟成立时，被分配在各部落和氏族中，担任专为联盟目的而设立的新的公职。当出缺时，有关的氏族便重新进行选举，同时有关的氏族也可以随时罢免他们；不过委任权则属于联盟议事会。","language":"中文","translation":false},{"id":"family-1-210","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":210,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"4.联盟的这些酋长们，在他们各自的部落中也是酋长，享有参加部落议事会和表决的权利。","language":"中文","translation":false},{"id":"family-1-211","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":211,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"5.联盟议事会的一切决议，须经全体一致通过。","language":"中文","translation":false},{"id":"family-1-212","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":212,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"6.表决是按部落举行的，这样，每个部落以及每个部落内的议事会全体成员，都必须一致赞成，决议才算有效。","language":"中文","translation":false},{"id":"family-1-213","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":213,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"7.五个部落议事会中每一个都可以召集联盟议事会，但联盟议事会本身不得自行召集。","language":"中文","translation":false},{"id":"family-1-214","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":214,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"8.会议在聚集起来的民众面前公开举行，每个易洛魁人都可以发言；但只有议事会才能作决定。","language":"中文","translation":false},{"id":"family-1-215","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":215,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"9.联盟没有一长制首长，即没有主掌执行权的首脑。","language":"中文","translation":false},{"id":"family-1-216","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":216,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"10.但联盟有两个具有平等职能和平等权力的最高军事首长(类似斯巴达人的两“王”，罗马的两执政官)。","language":"中文","translation":false},{"id":"family-1-217","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":217,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"易洛魁人在其中生活了四百余年、而且直至今日还生活于其中的整个社会制度，就是如此。我依据摩尔根，比较详细地叙述了这种制度，因为我们在这里有可能研究还不知有国家的一个社会的组织情况。国家是以一种与全体固定成员相脱离的特殊的公共权力为前提的，所以毛勒凭其正确的直觉，确认德意志的马尔克制度是一种纯粹社会的制度，虽然它以后大部分成了国家的基础，但在本质上它是和国家不同的。因此，毛勒在他的一切著作中所研究的，是公共权力逐渐从马尔克、乡村、农户、城市等最初的组织中产生，和与之并行产生的情形。55我们从北美印第安人那里可以看出，一个原来统一的氏族集团怎样逐渐散布于辽阔的大陆；各部落怎样通过分裂而转化为各民族，转化为整个的部落集团；语言怎样改变，以致不仅成了互相不懂的东西，而且差不多失去了原来统一性的任何痕迹；与此同时，在部落内部，单个的氏族怎样分裂为好几个氏族，老的母亲氏族作为胞族保存下来，但是这些最老的氏族的名称，在彼此相距极远的、老早就分离了的部落中间仍是一样的——“狼”和“熊”在大多数印第安部落中仍然是氏族的名称。一般说来，上述的社会制度适用于印第安人的一切部落，只是有许多部落没有达到亲属部落联盟的程度罢了。","language":"中文","translation":false},{"id":"family-1-218","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":218,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，我们也看到，氏族作为社会单位出现以后，氏族、胞族和部落这整个社会组织就怎样以几乎不可抗拒的必然性(因为是天然性)从这种单位中发展出来。这三种集团代表着不同层次的血缘亲属关系，每个都是闭关自守，自己的事情自己管理，但是又互相补充。归它们管辖的事情，包括低级阶段上的野蛮人的全部公共事务。所以，我们凡遇见某一民族是把氏族作为社会单位时，我们也就可以去寻找类似前面所讲的那种部落组织；凡有充足资料的地方，如在希腊人和罗马人那里，我们不仅能找出这种组织，而且也会确信，即使在没有资料作为依据的地方，只要与美洲社会制度作一比较，也有助于我们解决最困难的疑难和哑谜。","language":"中文","translation":false},{"id":"family-1-219","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":219,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"而这种十分单纯质朴的氏族制度是一种多么美妙的制度呵!没有大兵、宪兵和警察，没有贵族、国王、总督、地方官和法官，没有监狱，没有诉讼，而一切都是有条有理的。一切争端和纠纷，都由当事人的全体即氏族或部落来解决，或者由各个氏族相互解决；血族复仇仅仅当作一种极端的、很少应用的威胁手段；我们今日的死刑，只是这种复仇的文明形式，而带有文明的一切好处与弊害。虽然当时的公共事务比今日多得多，——家户经济是由一组家庭按照共产制共同经营的，土地是全部落的财产，仅有小小的园圃归家户经济暂时使用，——可是，丝毫没有今日这样臃肿复杂的管理机关。一切问题，都由当事人自己解决，在大多数情况下，历来的习俗就把一切调整好了。不会有贫穷困苦的人，因为共产制的家户经济和氏族都知道它们对于老年人、病人和战争残废者所负的义务。大家都是平等、自由的，包括妇女在内。他们还不曾有奴隶；奴役异族部落的事情，照例也是没有的。当易洛魁人在1651年左右征服伊利部落和“中立民族”56的时候，他们曾建议这两个部落作为完全的平等的成员加入他们的联盟；只是在被征服者拒绝了这个建议之后，才被驱逐出自己所居住的地区。凡与未被腐蚀的印第安人接触过的白种人，都称赞这种野蛮人的自尊心、公正、刚强和勇敢，这些称赞证明了，这样的社会能够产生怎样的男子，怎样的妇女。","language":"中文","translation":false},{"id":"family-1-220","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":220,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不久以前，我们在非洲看到了这种勇敢的例证。祖鲁卡菲尔人在数年前，也像努比亚人在数月前一样，——两者都是至今还保存着氏族制度的部落——曾做出了任何欧洲军队都不能做到的事情。57他们没有枪炮，仅仅用长矛和投枪武装起来，在英国步兵——在密集队形战斗上被公认为世界第一——的后装枪的弹雨之下，竟然一直向前冲到刺刀跟前，不止一次打散英军队伍，甚至使英军溃退，尽管在武器上非常悬殊，尽管他们根本没有什么服兵役，也不知道什么是操练。英国人诉苦说，卡菲尔人比马走得还快，一昼夜比马走得还远，这就可以证明这种野蛮人的能力和毅力。“他们的最小的一条筋都暴栗起来，坚硬如钢，像鞭条一样。”——一位英国的画家这样说。","language":"中文","translation":false},{"id":"family-1-221","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":221,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在没有分化为不同的阶级以前，人类和人类社会就是如此。要是我们把他们的状况和现代绝大多数文明人的状况作一比较，那么就可以看出，在今日的无产者和小农同古代自由的氏族成员之间，差距是巨大的。","language":"中文","translation":false},{"id":"family-1-222","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":222,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这是一个方面。但我们不要忘记，这种组织是注定要灭亡的。它没有超出部落的范围；部落联盟的建立就已经标志着这种组织开始崩溃，这一点我们在后面将会看到，易洛魁人征服其他部落的企图也表明了这一点。凡是部落以外的，便是不受法律保护的。在没有明确的和平条约的地方，部落与部落之间便存在着战争，而且这种战争进行得很残酷，使别的动物无法和人类相比，只是到后来，才因物质利益的影响而缓和一些。全盛时期的氏族制度，如我们在美洲所见的，其前提是生产极不发展，因而广大地区内人口极度稀少；因此，人类差不多完全受着同他异己地对立着的、不可理解的外部大自然的支配，这也就反映在幼稚的宗教观念中。部落始终是人们的界限，无论对别一部落的人来说或者对他们自己来说都是如此：部落、氏族及其制度，都是神圣而不可侵犯的，都是自然所赋予的最高权力，个人在感情、思想和行动上始终是无条件服从的。这个时代的人们，虽然使人感到值得赞叹，他们彼此并没有差别，他们都仍依存于——用马克思的话说——自然形成的共同体的脐带[66]。这种自然形成的共同体的权力必然要被打破，而且也确实被打破了。不过它是被那种使人感到从一开始就是一种退化，一种离开古代氏族社会的纯朴道德高峰的堕落的势力所打破的。最卑下的利益——无耻的贪欲、狂暴的享受、卑劣的名利欲、对公共财产的自私自利的掠夺——揭开了新的、文明的阶级社会；最卑鄙的手段——偷盗、强制、欺诈、背信——毁坏了古老的没有阶级的氏族社会，把它引向崩溃。而这一新社会自身，在其整整两千五百余年的存在期间，只不过是一幅区区少数人靠牺牲被剥削和被压迫的大多数人而求得发展的图画罢了，而这种情形，现在比从前更加厉害了。","language":"中文","translation":false},{"id":"family-1-223","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":223,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"希腊人，像皮拉斯基人以及其他起源于同一部落的民族一样，在史前时代，就已经按照美洲人的那种有机的序列——氏族、胞族、部落、部落联盟组织起来了。胞族可能是没有的，在多立斯人中间就是这样；部落联盟也不是到处都有成立的必要，但无论如何氏族是基本的单位。希腊人，在他们出现在历史舞台上的时候，已经站在文明时代的门槛上了；他们与上述美洲部落之间，横着差不多整整两个很大的发展时期，亦即英雄时代的希腊人超过易洛魁人两个时期。所以，希腊人的氏族也绝不再是易洛魁人的那种古老的氏族了，群婚[67]的痕迹正开始显著地消失。母权制已让位给父权制；正在产生的私有制就这样在氏族制度上打开了第一个缺口。第二个缺口是第一个缺口的自然结果：由于在实行父权制以后，富有的女继承人的财产在她出嫁时应当归她的丈夫所有，从而归别的氏族所有，所以，这便摧毁了整个氏族权利的基础，在这种情况下，为了把少女的财产保存在氏族以内，不仅容许少女在氏族内出嫁，而且也规定要这样做。","language":"中文","translation":false},{"id":"family-1-224","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":224,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"根据格罗特的《希腊史》58，其中雅典的氏族是建立在以下的基础上的：","language":"中文","translation":false},{"id":"family-1-225","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":225,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.共同的宗教祭把和祭司为把奉一定的神所拥有的特权。这种神被假想为氏族的男始祖，并用独特的名称作这种地位的标志。","language":"中文","translation":false},{"id":"family-1-226","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":226,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.共同的墓地(参看狄摩西尼《反驳欧布利得》59)。","language":"中文","translation":false},{"id":"family-1-227","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":227,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"4.在受到侵害时提供帮助、保护和支援的相互义务。","language":"中文","translation":false},{"id":"family-1-228","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":228,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"5.在一定情况下，特别是在事关孤女或女继承人的时候，在氏族内部通婚的相互权利和义务。","language":"中文","translation":false},{"id":"family-1-229","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":229,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"6.至少在某些情况下拥有共同财产，有自己的一位Archon (酋长)和一位司库。","language":"中文","translation":false},{"id":"family-1-230","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":230,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"此后，几个氏族结合为一个比较不那么密切的胞族；但是在这里我们也可以看到类似的相互权利与义务，特别是共同举行一定的宗教仪式以及在胞族成员被杀害时进行追究的权利。一个部落的所有胞族，又有共同的定期举行的祭祀，由一个从贵族(Eupa－triden)中间选出的Phylobasileus(部落酋长)主持。","language":"中文","translation":false},{"id":"family-1-231","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":231,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"格罗特所说的，就是这样。马克思补充说：“但是，透过希腊氏族，也可以清楚地看到蒙昧人(例如易洛魁人)。”60要是我们作进一步的研究，那就看得更加清楚。","language":"中文","translation":false},{"id":"family-1-232","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":232,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"希腊的氏族还具有以下这几个特征：","language":"中文","translation":false},{"id":"family-1-233","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":233,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"7.按照父权制计算世系。","language":"中文","translation":false},{"id":"family-1-234","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":234,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"8.禁止氏族内部通婚，但女继承人例外。这一例外及其确立成为规定，就证明旧时的规则仍然有效。这也是从下述普遍通行的原则中产生的，即妇女出嫁后，就不再参加本氏族的宗教仪式，而改行她丈夫的氏族的宗教仪式，注籍于她丈夫的胞族。根据这一点以及狄凯阿尔科斯的著名的一段话看来61，可知外婚乃是规则，而贝克尔在《哈里克尔》一书中径直认为，无论什么人都不得在本氏族内部通婚。62","language":"中文","translation":false},{"id":"family-1-235","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":235,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"9.接纳外人入族的权利；这是用家庭接纳的办法来实现的，不过要有公开的仪式，而且只限于例外情形。","language":"中文","translation":false},{"id":"family-1-236","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":236,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"10.选举和罢免酋长的权利。我们知道，每一氏族都有自己的酋长；但是，任何地方都没有说过这一职务是在一定的家庭里世袭的。在野蛮时代结束以前，不大可能有严格的[68]世袭制，因为这种世袭制是同富人和穷人在氏族内部享有完全平等权利的秩序不相容的。","language":"中文","translation":false},{"id":"family-1-237","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":237,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不仅格罗特，而且尼布尔、蒙森以及迄今为止的其他一切古典古代历史编纂学家，都没有解决氏族问题。不论他们多么正确地叙述了氏族的许多特征，但是他们总是把氏族看作家庭集团，因此便不能理解氏族的本性和起源。在氏族制度之下，家庭从来不是，也不可能是一个组织单位，因为夫与妻必然属于两个不同的氏族。氏族整个包括在胞族内，胞族整个包括在部落内；而家庭却是一半包括在丈夫的氏族内，一半包括在妻子的氏族内。国家在公法上也不承认家庭，到今日为止，家庭不过存在于私法上而已。然而我们的全部历史编纂学直至现在都是从以下一个荒诞的，尤其在18世纪已成为不可侵犯的假定出发的：未必早于文明时代的专偶制个体家庭，曾是社会和国家围绕它而逐渐萌发起来的核心。","language":"中文","translation":false},{"id":"family-1-238","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":238,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"马克思补充说：“格罗特先生应当进一步注意到，虽然希腊人是从神话中引伸出他们的氏族的，但是这些氏族比他们自己所创造的神话及其诸神和半神要古老些。”63摩尔根爱引用格罗特的话，因为后者是一个很有名望的和十分受人信任的证人。格罗特又说到，每个雅典氏族都有一个从它的假想的男始祖传给他们的名称；在梭伦时代以前，死者的财产一律由同氏族人继承，在梭伦时代以后，死者如无遗言，其财产亦由同氏族人继承；遇有杀害事件，首先是被害者的亲属有权利和义务向法庭控告犯罪者，其次是同氏族人，最后是同胞族人：","language":"中文","translation":false},{"id":"family-1-239","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":239,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“我们所知道的关于最古的雅典法律的一切，都是以划分成氏族和胞族为基础的。”64氏族起源于共同祖先，成了“庸人学者”(马克思语)65绞尽脑汁而不能解决的难题。既然他们很自然地认为这种祖先纯粹是神话人物，他们便根本没有可能解释氏族是怎样从许多彼此相邻的、起初完全没有亲属关系的家庭中产生出来的，然而单是为了解释氏族的存在，他们还是非这样做不可。这样他们便陷入了说空话的圈子，不能超出这样一个论题：族系的确是一种虚构，但氏族是一个现实，因之，格罗特终于说(括弧内的话是马克思加的)：","language":"中文","translation":false},{"id":"family-1-240","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":240,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“我们只是偶而听到这种族系，因为仅仅在一定的、特别隆重的场合才公开把它提出来。可是，比较卑微的氏族也有其共同的宗教仪式(这真奇怪，格罗特先生!)，有一个共同的超人的男始祖和族系，像比较有名的氏族那样(格罗特先生，这在比较卑微的氏族那里真十分奇怪呵!)；根本的结构和观念的基础(亲爱的先生!不是观念的而是物质的，直白地说是肉欲的!)在一切氏族中都是相同的。”66","language":"中文","translation":false},{"id":"family-1-241","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":241,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"马克思把摩尔根对这个问题的答案概括如下：“与原始形态的氏族——希腊人像其他凡人一样也曾有过这种形态的氏族——相适应的血缘亲属制度，保存了全体氏族成员彼此之间的亲属关系的知识。他们从童年时代起，就在实践上熟悉了这种对他们极其重要的事物。随着专偶制家庭的产生，这种事物就湮没无闻了。氏族名称创造了一个族系，相形之下，个体家庭的族系便显得没有意义。氏族名称的作用就在于使具有这种名称的人不忘他们有共同世系的事实；但是氏族的族系已经十分久远，以致氏族的成员，除了有较近的共同祖先的少数场合以外，已经不能证明他们相互之间有事实上的亲属关系了。氏族名称本身就是共同世系的证据，而且除了接纳外人入族的情形以外，也是不可更改的证据。反之，像格罗特[69]和尼布尔所作的那样，把氏族变为纯粹虚构和幻想的产物，从而事实上否定氏族成员之间的任何亲属关系，这是只有‘观念的’、亦即蛰居式的书斋学者才能干出来的事情。由于血族联系(尤其是专偶制发生后)已经湮远，而过去的现实看来是反映在神话的幻想中，于是老实的庸人们便作出了而且还在继续作着一种结论，即幻想的族系创造了现实的氏族!”67","language":"中文","translation":false},{"id":"family-1-242","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":242,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"胞族，像在美洲人那里一样，是一种分裂成几个女儿氏族同时又把它们联合起来的母亲氏族，这种母亲氏族常常还能表明所有这些女儿氏族出自一个共同的男始祖。比如，据格罗特说：","language":"中文","translation":false},{"id":"family-1-243","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":243,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“赫卡泰胞族的所有同时代的成员，都承认在第十六亲属等级内有一个共同的神为其男始祖。”68","language":"中文","translation":false},{"id":"family-1-244","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":244,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"所以，这一胞族的一切氏族都是真正的兄弟氏族。在荷马的诗篇中，还把胞族看作军事单位，在那著名的一段中，奈斯托尔劝告亚加米农说：要按照部落和胞族来编制军队，以便胞族帮助胞族，部落帮助部落。69此外，胞族在其成员被害时有追究的权利和义务；可见在较早的时代，胞族也有血族复仇的义务。其次，胞族有共同的神殿和节日，而且，从古代雅利安人的传统的自然崇拜而来的全部希腊神话，其发展本身，实质上也是由氏族及胞族所制约并在它们内部进行的。再次，胞族有一个胞族长(phratriarchos)，据德·库朗日说，它还有全体大会，通过必须执行的决定，拥有法庭和行政机关。70甚至以后的轻视氏族的国家，也给胞族保留下了若干公共的行政性的职能。","language":"中文","translation":false},{"id":"family-1-245","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":245,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"几个亲属胞族构成一个部落。在阿提卡，共有四个部落，每个部落有三个胞族，每个胞族有三十个氏族。这样细密的集团划分，是以有意识的和有计划的干涉自然形成的秩序为前提的。至于这是怎样发生的，什么时候发生的，发生的原因何在，希腊历史都没有提到，希腊人自己关于他们的历史所保存下来的记忆仅仅追溯到英雄时代为止。","language":"中文","translation":false},{"id":"family-1-246","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":246,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"拥挤在一个比较小的地区上的希腊人，其方言上的差异不像在广大的美洲森林中那样显著；但是就是在这里我们也看到，只有主要方言相同的部落才联合成为一个大的整体；甚至小小的阿提卡也有独特的方言，这一方言后来获得了统治地位而成为共同的散文语言。","language":"中文","translation":false},{"id":"family-1-247","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":247,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在荷马的诗中，我们可以看到希腊的各部落大多数已联合成为一些小民族；在这种小民族内部，氏族、胞族和部落仍然完全保持着它们的独立性。它们已经住在有城墙保护的城市里；人口的数目，随着畜群的增加、农业的扩展以及手工业的萌芽而日益增长；与此同时，就产生了财产上的差别，随之也就在古代自然形成的民主制内部产生了贵族分子。各个小民族，为了占有最好的土地，也为了掠夺战利品，进行着不断的战争；以俘虏充作奴隶，已成为公认的制度。","language":"中文","translation":false},{"id":"family-1-248","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":248,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这些部落和小民族的组织如下：","language":"中文","translation":false},{"id":"family-1-249","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":249,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.常设的权力机关为议事会，这种议事会最初大概是由各氏族的酋长组成的，后来，由于其人数增加得太多，便由其中选出的一部分人组成，这就造成了发展和加强贵族分子的机会；狄奥尼修斯所描述的英雄时代的议事会正是这样由贵族(kratistoi)组成的71。议事会对于一切重要问题作出最后决定；例如，在埃斯库罗斯的作品中就谈到过忒拜议事会曾作了一个对当时局势有决定意义的决议，即为伊托克利斯举行荣誉葬礼，而波吕涅克斯的尸体则扔出去让狗吃掉。72随着国家的设立，这种议事会就变为元老院了。","language":"中文","translation":false},{"id":"family-1-250","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":250,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.人民大会(agora［阿哥腊］)。我们在易洛魁人中间已经看到，当议事会开会时，人民——男男女女都站在周围，有秩序地参加讨论，这样来影响它的决定。在荷马所描写的希腊人中间，这种“围立”［Umstand］(这是古代德意志人的法庭用语)已经发展成为一种真正的人民大会，这种情形在古代德意志人那里也有。人民大会由议事会召集，以解决各项重要事务；每个男子都可以发言。决定是用举手(埃斯库罗斯的《求援女》)或欢呼通过的。人民大会是最高级的权力，因为，正如舍曼所说(《希腊的古代》)，","language":"中文","translation":false},{"id":"family-1-251","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":251,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“当谈到一件须要人民协助来办的事情的时候，荷马并未向我们指出任何可以违反人民意志而强迫他们来这样做的手段”73。","language":"中文","translation":false},{"id":"family-1-252","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":252,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"原来，当部落中每个成年男子都是战士的时候，那脱离了人民的、有可能和人民对抗的公共权力还不存在。自然形成的民主制还处于全盛时期，所以无论在判断议事会的或者巴赛勒斯的权力与地位时，都应当以此为出发点。","language":"中文","translation":false},{"id":"family-1-253","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":253,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"3.军事首长(Basileus［巴赛勒斯］)。关于这一点马克思说道：“欧洲的学者们大都是天生的宫廷奴才，他们把巴赛勒斯变为现代意义上的君主。共和党人美国佬摩尔根是反对这一点的。他极其辛辣地、但很公正地说到油滑的格莱斯顿先生和他的《世界的少年时代》一书74：","language":"中文","translation":false},{"id":"family-1-254","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":254,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"‘格莱斯顿先生向我们把英雄时代的希腊酋长描写成国王和公侯，而且还给他们加上绅士的资格，但是他本人不得不承认：总的说来，我们发现在他们那里似乎有长子继承的习惯或法律，而且规定得很充分但是并不是明确到了极点’75。”","language":"中文","translation":false},{"id":"family-1-255","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":255,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"看来，格莱斯顿先生本人也会觉得，带有这种保留条件的长子继承制，也已经充分地等于没有，尽管并不是明确到了极点地等于没有。","language":"中文","translation":false},{"id":"family-1-256","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":256,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们已经看到，易洛魁人和其他印第安人的酋长职位是怎样继承的。一切职位多半都是在氏族内部选举的，因而是在氏族范围内继承的。出缺时，最亲近的同氏族男亲属——兄弟，或姊妹的儿子，逐渐享有了优先权，除非有理由屏弃他。因此，如果说在希腊人中间，在父权制统治之下，巴赛勒斯的职位通常是传给儿子或儿子中的一个，那么这仅仅证明，儿子们在这里很有可能通过人民选举而获得继承权，但决不证明不经过人民选举就实行合法继承。这里所说的情况，在易洛魁人和希腊人那里，就是氏族内部特殊的贵族家庭的最初萌芽，而在希腊人那里，除此之外还是未来的世袭元首或君主制的最初萌芽。因此，这种推想说明，希腊人的巴赛勒斯，正像罗马的“王”(勒克斯)一样，必定是或者由人民选举的，或者为人民的公认的机关——议事会或人民大会——所认可的。","language":"中文","translation":false},{"id":"family-1-257","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":257,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在《伊利亚特》里，勇士的统领亚加米农，并不是作为希腊人的最高国王，而是作为围城盟军的最高统帅而出现的。当希腊人中间发生内讧时，奥德赛在一段著名的话中指明了他的这一地位：多头指挥是不好的，应该由一个人做统帅等等(此外还有一节人人爱诵的关于权杖的诗，但这是后人加的)。69“奥德赛在这里并不是讲述统治的形式，而是要求服从战争中的最高统帅。对于在特洛伊城下仅仅作为军队出现的希腊人说来，人民大会是进行得十分民主的。阿基里斯在说到赠品，即说到分配战利品时，他总是既不让亚加米农也不让其他某个巴赛勒斯来分配，而是让‘亚该亚人的儿子们’即人民来分配。‘宙斯所生的’，‘宙斯所养的’这一类称号，不能证明任何东西，因为每个氏族都起源于一个神，而部落首长的氏族则起源于一个‘更显赫’的神，在这里就是起源于宙斯。甚至人身不自由的人，例如牧猪人优玛士等人，也都是‘神的’(dioi和theioi)，这是在《奥德赛》中所描述的情形，即在比《伊利亚特》晚得多的时期中发生的情形；在这本《奥德赛》中，‘英雄’的称号还给予传令官木利奥斯和盲人歌手德莫多克。[70]简言之，希腊著作家用来表示荷马所说的王权的basileia［巴赛勒亚］一词(因为这一权力的主要特征是军事的统率)，在同时存在议事会和人民大会的情况下，其意不过是军事民主制而已。”(马克思语)76巴赛勒斯除军事的权限以外，还有祭把的和审判的权限；审判的权限没有详细规定，但祭祀的权限是他作为部落或部落联盟的最高代表而被赋予的。关于民政、行政的权限从来没有提到过；但是巴赛勒斯由于职位的关系大概也是议事会的成员。可见，用来翻译Basileus一词，在语源上是完全正确的，因为(Kuning)是由而来的，即氏族酋长的意思。不过，古希腊文的basileus跟现代意义的一词是完全不相符合的。修昔的底斯把古代的basileia很确定地叫作，即由氏族产生的意思，并说basileia有明确规定的、因而是有限的权限。77亚里士多德也说，英雄时代的basileia是对自由人的统率，巴赛勒斯是军事首长、法官和最高祭司78；可见，巴赛勒斯并未握有后来的意义上的统治权力。[71]这样，我们看到，在英雄时代的希腊社会制度中，古代的氏族组织还是很有活力的，不过我们也已经看到，它的瓦解已经开始：由子女继承财产的父权制，促进了财产积累于家庭中，并且使家庭变成一种与氏族对立的力量；财产的差别，通过世袭贵族和王权的最初萌芽的形成，对社会制度发生反作用；奴隶制起初虽然仅限于俘虏，但已经开辟了奴役同部落人甚至同氏族人的前景；古代部落对部落的战争，已经逐渐蜕变为在陆上和海上为攫夺牲畜、奴隶和财宝而不断进行的抢劫，变为一种正常的营生，一句话，财富被当作最高的价值而受到赞美和崇敬，古代氏族制度被滥用来替暴力掠夺财富的行为辩护。所缺少的只是一件东西，即这样一个机关，它不仅保障单个人新获得的财富不受氏族制度的共产制传统的侵犯，不仅使以前被轻视的私有财产神圣化，并宣布这种神圣化是整个人类社会的最高目的，而且还给相继发展起来的获得财产从而不断加速财富积累的新的形式，盖上社会普遍承认的印章；所缺少的只是这样一个机关，它不仅使正在开始的社会分裂为阶级的现象永久化，而且使有产者阶级剥削无产者阶级的权利以及前者对后者的统治永久化。而这样的机关也就出现了。国家被发明出来了。","language":"中文","translation":false},{"id":"family-1-258","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":258,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"国家怎样靠部分地改造氏族制度的机关，部分地用设置新机关来排挤掉它们，并且最后全部以真正的国家机关来取代它们而发展起来；同时受这些国家机关支配的，因而也可以被用来反对人民的，武装的“公共权力”，又怎样代替了氏族、胞族和部落中自己保卫自己的真正的“武装的人民”——关于这一切，至少是它的初始阶段，再好莫过于从古雅典来加以研究。各种形式的更替，基本上已由摩尔根描绘出来了；我所要补充的，多半是引起这种形式更替的经济内容。","language":"中文","translation":false},{"id":"family-1-259","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":259,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在英雄时代，雅典人的四个部落，还分居在阿提卡的各个地区；甚至组成这四个部落的十二个胞族，看来也还有自己单独的居住地，即凯克罗普斯的十二个城市。制度也是英雄时代的制度：人民大会，人民议事会和巴赛勒斯。从有成文历史的时候起，土地已被分割而成了私有财产，这种情形正是和野蛮时代高级阶段末期已经比较发达的商品生产以及与之相适应的商品交易相符合的。除了谷物以外，还生产葡萄酒和植物油；爱琴海的海上贸易，逐渐脱离腓尼基人的控制而大半落于阿提卡居民之手。由于地产的买卖，由于农业和手工业、商业和航海业之间的分工的进一步发展，氏族、胞族和部落的成员，很快就都杂居起来；在胞族和部落的地区内，移来了这样的居民，他们虽然也是本民族的同胞，但并不属于这些团体，因而他们在自己的居住地上被看作外人。在和平时期，每一个胞族和每一个部落都是自己管理自己的事务，也不向雅典的人民议事会或巴赛勒斯请示。但是那些住在胞族或部落的地区内而不属于这个胞族或部落的人，自然是不能参与这种管理的。","language":"中文","translation":false},{"id":"family-1-260","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":260,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这就扰乱了氏族制度机关的正常活动，以致在英雄时代就需要设法补救。于是实行了据说是提修斯所规定的制度。这一改变首先在于，在雅典设立了一个中央管理机关，就是说，以前由各部落独立处理的一部分事务，被宣布为共同的事务，而移交给设在雅典的共同的议事会管辖了。由于这一点，雅典人比美洲任何土著民族都前进了一步：相邻的各部落的单纯的联盟，已经由这些部落融合为单一的民族［Volk］所代替了。于是就产生了凌驾于各个部落和氏族的法的习惯之上的雅典普遍适用的民族法［Volksrecht］；只要是雅典的公民，即使在非自己部落的地区，也取得了确定的权利和新的法律保护。但这样一来就跨出了摧毁氏族制度的第一步，因为这是后来容许不属于全阿提卡任何部落并且始终都完全处于雅典氏族制度以外的人也成为公民的第一步。据说是提修斯所规定的第二个制度，就是把全体人民，不问氏族、胞族或部落，一概分为Eupatriden即贵族、Geomoren即农民和Demiurgen即手工业者三个阶级，并赋予贵族以担任公职的独占权。不过这一划分，除了由贵族担任公职以外，并没有起什么作用，因为除此以外，它并没有规定各个阶级之间的任何权利上的差别。[72]但它有着重大的意义，因为它向我们展示了新的、悄悄发展起来的社会要素。它表明，由一定家庭的成员担任氏族公职的习惯，已经变为这些家庭担任公职的无可争辩的权利；这些因拥有财富而本来就有势力的家庭，开始在自己的氏族之外联合成一种独特的特权阶级；而刚刚萌芽的国家，也就使这种霸占行为神圣化。其次，它表明，农民和手工业者之间的分工已经如此牢固，以致以前氏族和部落的划分在社会意义方面已不是最重要的。最后，它宣告了氏族社会和国家之间的不可调和的对立；建立国家的最初企图，就在于破坏氏族的联系，其办法就是把每一氏族的成员分为特权者和非特权者，把非特权者又按照他们的职业分为两个阶级，从而使之互相对立起来。","language":"中文","translation":false},{"id":"family-1-261","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":261,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"以后的雅典政治史，直到梭伦时代，知道得很不完全。巴赛勒斯一职已经废除；国家首脑人物已由贵族中所选出的执政官来充任。贵族的统治日益加强，到了公元前600年左右，已经变得令人不能忍受了。这时，货币和高利贷已成为压制人民自由的主要手段。贵族们的主要居住地是雅典及其近郊，在那里，海上贸易以及附带的有时仍然进行的海上掠夺，使贵族们发财致富，并使货币财富集中在他们手中。由此而日益发达的货币经济，就像腐蚀性的酸类一样，渗入了农村公社的以自然经济为基础的传统的生活方式。氏族制度同货币经济绝对不能相容；阿提卡小农的破产是与保护他们的旧的氏族联系的松弛同时发生的。债务契约和土地抵押(雅典人已经发明了抵押办法)既不理会氏族，也不理会胞族。而旧的氏族制度既不知有货币，也不知有贷款，更不知有货币债务。因此，贵族的日益扩展的货币统治，为了保护债权人对付债务人，为了使货币所有者对小农的剥削神圣化，也造成了一种新的习惯法。在阿提卡的田地上到处都竖立着抵押柱，上面写着这块地已经以多少钱抵押给某某人了。没有竖这种柱子的田地，大半都因未按期付还押款或利息而出售，归贵族高利贷者所有了；农民只要被允许作佃户租种原地，能得自己劳动生产品的六分之一以维持生活，把其余六分之五作为地租交给新主人，那他就谢天谢地了。不仅如此，如果出卖土地所得的钱不够还债，或者债务没有抵押保证，那么债务人便不得不把自己的子女出卖到国外去做奴隶，以偿还债务。父亲出卖子女——这就是父权制和专偶制的第一个果实!要是吸血鬼还不满足，那么他可以把债务人本身卖为奴隶。雅典人民的文明时代的欢乐的曙光，就是如此。","language":"中文","translation":false},{"id":"family-1-262","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":262,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"以前，当人民的生活条件和氏族制度还相适应时，这样的变革是不可能的；但是现在这一变革发生了，人们不知道它是怎样发生的。我们暂且回转来看一下易洛魁人吧。这时强加在雅典人身上而他们可以说并未参与策划并且又确乎违反他们意志的状况，在易洛魁人中间是不能想象的。在易洛魁人那里，年年不变的生产生活资料的方式，决不会产生这种仿佛从外面强加的冲突，这种富人与穷人、剥削者与被剥削者之间的对立。易洛魁人离支配自然的地步还远得很，但是在他们能起作用的自然界限以内，他们是支配着自己的生产的。除开他们的小小园圃的歉收，他们的河流湖泊内的鱼类的罄竭以及森林中猎物的绝迹以外，他们知道他们获取生活资料的方式会产生什么结果。所必然产生的结果是生活资料，尽管有时少，有时多；但是决不会产生那种无意中产生的社会变革，氏族联系的破裂，或同氏族人和同部落人分裂为互相斗争的对立阶级。生产是在极狭隘的范围内进行的，但生产品完全由生产者支配。这是野蛮时代的生产的巨大优越性，这一优越性随着文明时代的到来便丧失了。夺回这一优越性，但是以今日人类所获得的对自然的有力支配以及今日已有可能的自由联合为基础，这将是下几代人的任务。","language":"中文","translation":false},{"id":"family-1-263","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":263,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"希腊人的情形就不同了。业已出现的对畜群和奢侈品的私人占有，引起了单个人之间的交换，使产品变成了商品。这就包含着随之而来的全部变革的萌芽。当生产者不再直接消费自己的产品，而是通过交换把它转让出去的时候，他们就失去了对自己的产品的支配权力。他们已不再知道产品的结局如何，于是产品有那么一天被用来反对生产者、剥削和压迫生产者的可能性便产生了。因此，不论哪一个社会，只要它不消灭单个人之间的交换，它便不能长久保持对它自己的生产的支配，不能长久保持对自己生产过程的社会效果的控制。","language":"中文","translation":false},{"id":"family-1-264","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":264,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"然而，产品是怎样在单个人之间的交换发生以后以及随着产品变成商品而迅速地支配了它的生产者的——这一点雅典人不得不亲自来体验了。随着商品生产，出现了个人单独经营的土地耕作，以后不久又出现了个人的土地所有制。随后就出现了货币，即其余一切商品都可以和它交换的普遍商品。但是当人们发明货币的时候，他们并没有想到，这样一来他们就创造了一种新的社会力量，一种整个社会都要向它屈膝的普遍力量。这种未经它自身创造者的预知并违反其意志而突然崛起的新力量，就以其全部青春时代的粗暴性使雅典人感受到它的支配了。","language":"中文","translation":false},{"id":"family-1-265","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":265,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"怎么办呢？古老的氏族制度，不仅无力反对货币的胜利进军，而且它也绝对没有办法能在自己的结构内部给货币、债权人、债务人以及逼债等找到立足之地。但是新的社会力量已经存在；挽回旧的美好时光的虔诚愿望和渴望，都没有能再把货币和高利贷从世界上消除。而且，在氏族制度中已经打开了一系列其他的次要缺口。在全部阿提卡境内，特别是在雅典城本身，各氏族和胞族的成员相互杂居，已经一代比一代厉害了，尽管这时雅典人仍然只能把土地而不能把自己的住宅卖给本氏族以外的人。随着工业和交换的进一步发展，各种生产部门——农业、手工业(在手工业内又有无数行业)、商业、航海业等——之间的分工日益充分地发展起来；居民现在依其职业分成了相当稳定的集团；其中每个集团都有好多新的共同的利益，这种利益在氏族或胞族内是没有存在的余地的，因而就需要创设新的公职来处理这种利益。奴隶的数量已经大大增加，那个时候肯定就已经远远超过自由的雅典人的数量；氏族制度最初并没有奴隶制，因而也就没有控制这大批非自由人的手段。最后，贸易把许多外地人吸引到雅典来，这些外地人是为了易于赚钱而定居这里的；按照旧制度，他们既没有权利，也不受法律保护，所以尽管有传统的容忍精神，他们仍然是人民中间令人不安的异己分子。","language":"中文","translation":false},{"id":"family-1-266","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":266,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"一句话，氏族制度已经走到了尽头。社会一天天成长，越来越超出氏族制度的范围；即使是最严重的坏事在它眼前发生，它也既不能阻止，又不能铲除了。但在这时，国家已经不知不觉地发展起来。最初在城市和乡村间，然后在各种城市劳动部门间实行的分工所造成的新集团，创立了新的机关以保护自己的利益；各种公职都设置起来了。这时，年轻的国家首先就需要一支自己的军事力量，而在操航海业的雅典人中间，起初只能是一支海上的军事力量，用以进行个别的小规模战争和保护商船。在梭伦以前的一个不能确知的时期，设置了诺克拉里，即小规模的区，每个部落设十二个；每一诺克拉里必须提供一只战船，配备上武器和船员，此外，还要提供两个骑士。这个设施对氏族制度起了双重的破坏作用；第一，它造成了一种已不再直接等同于武装起来的全体人民的公共权力；第二，它第一次不依亲属集团而依共同居住地区为了公共目的来划分人民。这有什么意义，可以从下面看出来。","language":"中文","translation":false},{"id":"family-1-267","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":267,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"既然氏族制度对于被剥削的人民不能有任何帮助，于是就只有期望正在产生的国家。而国家也确实以梭伦制度的形式给予了这种帮助，同时它又靠牺牲旧制度来增强自己。梭伦揭开了一系列所谓政治革命，而且是以侵犯所有制来揭开的，至于他在公元前594年实现改革的方式，我们在这里可以不谈。迄今的一切革命，都是为了保护一种所有制以反对另一种所有制的革命。它们如果不侵犯另一种所有制，便不能保护这一种所有制。在法国大革命时期，是牺牲封建的所有制以拯救资产阶级的所有制；在梭伦所进行的革命中，应当是损害债权人的财产以保护债务人的财产。债务简单地被宣布无效了。详情我们虽然不太清楚，但是梭伦在他的诗中自夸说，他清除了负债土地上的抵押柱，使那些因债务而被出卖和逃亡到海外的人都重返家园。这只有通过公开侵犯财产所有权才能做到。的确，一切所谓政治革命，从头一个起到末一个止，都是为了保护一种财产而实行的，都是通过没收(或者也叫作盗窃)另一种财产而进行的。所以毫无疑问，2500年来私有财产之所以能保存下来，只是由于侵犯了财产所有权的缘故。","language":"中文","translation":false},{"id":"family-1-268","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":268,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但现在必须防止这种使自由的雅典人变为奴隶的情形重演。这一点，首先是通过普遍实行的措施而做到的，例如禁止缔结以债务人的人身作抵押的债务契约。此外，又规定了个人所能占有的地产的最大数额，以便至少把贵族对于农民土地的无限贪欲限制一下。然后又对制度本身作了修改；对我们说来，最重要的有以下几点：","language":"中文","translation":false},{"id":"family-1-269","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":269,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"议事会规定由400人组成，每一部落为100人；因此在这里，部落依然是基础。不过这是新的国家组织从旧制度中接受下来的唯一方面。至于其他方面，梭伦把公民按照他们的地产和收入分为四个阶级；500、300及150袋谷物(1袋约等于41公升)，为前三个阶级的最低限度的收入额；地产少于此数或完全没有地产的人，则属于第四阶级。一切公职只有三个上等阶级的人才能担任；最高的公职只有第一阶级的人才能担任；第四阶级只有在人民大会上发言和投票的权利，但是，一切官吏都是在这里选出的，一切官吏都要在这里报告自己的工作；一切法律都是在这里制定的；而第四阶级在这里占多数。贵族的特权，部分地以财富特权的形式得到更新；但人民却保留有决定的权力。此外，四个阶级都是新的军队组织的基础。前两个阶级提供骑兵，第三阶级提供重装步兵，第四阶级提供不穿甲胄的轻装步兵或在海军中服务，大概还领薪饷。","language":"中文","translation":false},{"id":"family-1-270","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":270,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，在制度中便加入了一个全新的因素——私有财产。公民的权利和义务，是按照他们的地产的多寡来规定的，于是，随着有产阶级日益获得势力，旧的血缘亲属团体也就日益遭到排斥；氏族制度遭到了新的失败。","language":"中文","translation":false},{"id":"family-1-271","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":271,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"然而，按照财产来规定政治权利，并不是国家不可缺少的办法。虽然这种办法在国家制度史上起过很大的作用，但是许多国家，而且恰好是最发达的国家，都是不需要它的。即使在雅典，它也只起了暂时的作用；从亚里斯泰迪兹的时候起，一切公职对每个公民都是开放的。79","language":"中文","translation":false},{"id":"family-1-272","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":272,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"其后80年间，雅典社会就逐渐采取了一个它在以后数百年中都遵循着的发展方向。在梭伦以前的时代盛行的农村高利贷，以及地产的无限制的集中，都受到了节制。商业以及靠奴隶劳动日益大规模发展起来的手工业和工艺，都成了流行的职业。人们也比较开通了。旧时残酷剥削自己同胞的方法，已经弃而不用，如今主要是剥削奴隶和雅典以外的买主了。动产，即由货币、奴隶以及商船构成的财富，日益增加，但是，这时它已经不是单单用作购置地产的手段，像在眼光狭小的最初时期那样，——它已经变成目的本身了。结果，一方面形成了新阶级即从事工商业的富人对旧的贵族权力的胜利竞争，而另一方面，也使旧的氏族制度的残余失去了它的最后地盘。现在氏族、胞族和部落的成员遍布于全阿提卡并完全杂居在一起，因此，氏族、胞族和部落已不适宜于作为政治集团了；大量的雅典公民不属于任何氏族；他们是移民，他们虽然取得了公民权，但是并没有被接纳入任何旧的血族团体；此外，还有不断增加的仅仅被保护的外来的移民。80","language":"中文","translation":false},{"id":"family-1-273","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":273,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这时，帮派斗争在进行着；贵族想夺回他们以前的特权，并在短时期内占了上风，直到克利斯提尼革命(公元前509年)最终把他们推翻，但与之同时也推翻了氏族制度的最后残余。81","language":"中文","translation":false},{"id":"family-1-274","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":274,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"克利斯提尼的新制度撇开了以氏族和胞族为基础的四个旧部落。代替它们的是一种全新的组织，这种组织是以曾经用诺克拉里试验过的只依居住地区来划分公民的办法为基础的。有决定意义的已不是血族团体的族籍，而只是常住地区了；现在要加以划分的，不是人民，而是地区了；居民在政治上已变为地区的简单的附属物了。","language":"中文","translation":false},{"id":"family-1-275","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":275,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"全阿提卡被划分成一百个区域，即所谓德莫，分别实行自治。居住在每个德莫内的公民(德莫特)，选举出自己的区长(德马赫)和司库、以及审理轻微案件的30个法官。各个德莫同样也有自己的神庙及守护神或英雄，并选出侍奉他们的祭司。德莫的最高权力，属于德莫特大会。摩尔根说得对，这是实行自治的美洲市镇区的一种原型。当时在雅典正在产生的国家借以开始的单位，正好和现代国家在其最高发展阶段上借以完结的单位相同。","language":"中文","translation":false},{"id":"family-1-276","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":276,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"十个这样的单位，即德莫，构成一个部落，但是这种部落和过去的血族部落不同，现在它被叫作地区部落。地区部落不仅是一种自治的政治组织，而且也是一种军事组织；它选出一个菲拉尔赫[73]即部落长，指挥骑兵；一个塔克色阿赫，指挥步兵；一个将军，统率在部落境内征召的全体军人。其次，它提供5艘配有船员和船长的战船；并且有阿提卡的一位英雄作为自己的守护神，英雄的名字也就是部落的名称。最后，它选举50名代表参加雅典议事会。","language":"中文","translation":false},{"id":"family-1-277","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":277,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"结果组成了雅典国家，它是由10个部落所选出的500名代表组成的议事会来管理的，最后一级的管理权属于人民大会，每个雅典公民都可以参加这个大会并享有投票权；此外，有执政官和其他官员掌管各行政部门和司法事务。在雅典没有总揽执行权力的最高官员。","language":"中文","translation":false},{"id":"family-1-278","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":278,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由于实施这个新制度和容纳大量被保护民——一部分是移民，一部分是被释奴隶，——血族制度的各种机关便受到排挤而不再过问公事；它们下降为私人性质的团体和宗教社团。不过，旧氏族时代的道德影响、传统的观点和思想方式，还保存很久，只是逐渐才消亡下去。这一点从下面的一个国家设施中可以看出来。","language":"中文","translation":false},{"id":"family-1-279","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":279,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们已经看到，国家的本质特征，是和人民大众分离的公共权力。雅典在当时只有一支国民军和一支直接由人民提供的舰队，它们被用来抵御外敌和压制当时已占人口绝大多数的奴隶。对于公民，这种公共权力起初只不过作为警察而存在，警察和国家一样古老，所以18世纪的质朴的法国人就不讲文明民族而讲警察民族(nations policées)[74]。这样，雅典人在创立他们国家的同时，也创立了警察，即由步行的和骑马的弓箭手组成的真正的宪兵队，或者如德国南部和瑞士所说的。[75]不过，这种宪兵队却是由奴隶组成的。这种警察职务，在自由的雅典人看来是非常卑贱的，以致他们宁愿让武装的奴隶逮捕自己，而自己却不肯去干这种丢脸的工作。这仍是旧的氏族观念。国家是不能没有警察的，不过国家还很年轻，还未享有充分的道义上的威望，足以使那种必然要被旧氏族成员视为卑贱的行业受到尊敬。","language":"中文","translation":false},{"id":"family-1-280","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":280,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"现在已经大体上形成的国家是多么适合雅典人的新的社会状况，这可以从财富、商业和工业的迅速繁荣中得到证明。现在社会制度和政治制度所赖以建立的阶级对立，已经不再是贵族和平民之间的对立，而是奴隶和自由民之间的对立，被保护民和公民之间的对立了。到了雅典全盛时期，自由公民的总数，连妇女和儿童在内，约为9万人，而男女奴隶为365000人，被保护民——外地人和被释奴隶为45000人。这样，每个成年的男性公民至少有18个奴隶和2个以上的被保护民。大量奴隶的存在，是由于许多奴隶在监工的监督下在手工工场，在大房间内一起工作。但是，随着商业和工业的发展，发生了财富积累和集中于少数人手中以及大批自由公民贫困化的现象；摆在自由公民面前的只有两条道路：或者从事手工业去跟奴隶劳动竞争，而这被认为是可耻的、卑贱的职业，而且也不会有什么成效；或者就变成穷光蛋。他们在当时条件下必不可免地走上了后一条道路；由于他们数量很大，于是就把整个雅典国家引向了灭亡。所以，使雅典灭亡的并不是民主制，像欧洲那些讨好君主的学究们所断言的那样，而是排斥自由公民劳动的奴隶制。","language":"中文","translation":false},{"id":"family-1-281","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":281,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"雅典人国家的产生乃是一般国家形成的一种非常典型的例子，一方面，因为它的形成过程非常纯粹，没有受到任何外来的或内部的暴力干涉，——庇西特拉图的篡位为时很短，并未留下任何痕迹82，——另一方面，因为它使一个具有很高发展形态的国家，民主共和国，直接从氏族社会中产生；最后，因为我们是充分知道这个国家形成的一切重要详情的。","language":"中文","translation":false},{"id":"family-1-282","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":282,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"从罗马建城的传说中可以看出，最早在这里定居的是由许多拉丁氏族(传说有100个)联合而成的一个部落；不久又加入了一个萨伯力安部落，据说也有100个氏族；最后加入的是一个由各种不同的分子构成的第三个部落，传说它也有100个氏族。初看起来，这全部故事表明，在这里除了氏族以外，很少再有自然形成的东西，连氏族本身在许多情况下，也只不过是在故土上继续存在的母亲氏族的分支。各个部落都带有人为构成的痕迹，但它们大部分都是由有亲属关系的分子构成的，并且不是按照人为的部落而是按照古代的已经长成的部落的样子构成的；同时仍不排除三个部落中每一个部落的核心都是一个真正的老部落。中间环节——胞族，是由10个氏族组成的，叫作库里亚；因此，共有30个库里亚。","language":"中文","translation":false},{"id":"family-1-283","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":283,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"人们公认，罗马氏族的制度和希腊氏族的制度是相同的；如果说，希腊氏族是我们在美洲红种人中间发现其原始形态的那种社会单位的进一步发展，那么，这对于罗马氏族也完全适用。因此，我们在这里可以谈得简单些。","language":"中文","translation":false},{"id":"family-1-284","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":284,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"罗马的氏族，至少在该城存在的早期，有以下的制度：","language":"中文","translation":false},{"id":"family-1-285","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":285,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1.氏族成员的相互继承权；财产仍保留在氏族以内。在罗马氏族里，也像在希腊氏族里一样，因为父权制已经盛行，所以女系后裔已经没有继承权。根据我们所知道的最古的罗马成文法即十二铜表法83，首先是子女作为直系继承人继承财产；要是没有子女，则由父方宗亲(男系亲属)继承；倘若连父方宗亲也没有，则由同氏族人继承。无论在哪种情况下，财产都是留在氏族以内的。在这里我们看到，由财富的增加和专偶制所产生的新的法律规范已逐渐渗入氏族的习俗：同氏族人的原先是平等的继承权，起初——如前面所说的在很早的时期——在实践上只限于父方宗亲，最后只限于亲生子女及其男系后裔；不言而喻，这和十二铜表法上的顺序是相反的。","language":"中文","translation":false},{"id":"family-1-286","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":286,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"2.拥有共同的墓地。克劳狄名门氏族，在由雷吉尔城迁到罗马时，得到了一块土地，此外还在城内得到了一块共同墓地。还在奥古斯都时代，死在条顿堡林山的瓦鲁斯的首级运到罗马后84，即埋在氏族坟地；可见他的氏族(昆提利)还有专用的坟地。[76]3.共同的宗教节日。这些氏族祭典是众所周知的。","language":"中文","translation":false},{"id":"family-1-287","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":287,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"4.氏族内部不得通婚。这在罗马似乎从来没有成为一种成文法，但一直是一种习俗。在名字一直保存到今天的大量罗马人夫妇中，没有一对夫妇的氏族名称是相同的。继承权也证实了这一规则。妇女出嫁后就丧失了她的父方宗亲的权利，而退出自己的氏族；不论她或她的子女都不能继承她的父亲或父亲的兄弟，因为不然的话，父亲的氏族就会失掉一部分财产。这一惯例只有在女子不能和同氏族人结婚的前提下才有意义。","language":"中文","translation":false},{"id":"family-1-288","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":288,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"5.共同的地产。这在原始时代，从部落土地开始实行分配的时候起，始终是存在的。在各拉丁部落中间，我们看到，土地一部分为部落占有，一部分为氏族占有，一部分为家户占有，那时这种家户未必是[77]个体家庭。相传罗慕洛第一次把土地分配给了个人，每人大约一公顷(两罗马亩)。但是后来我们也还看到氏族掌握的地产，至于那为共和国全部内政史所围绕的国有土地，就更不必说了。","language":"中文","translation":false},{"id":"family-1-289","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":289,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"6.同氏族人有互相保护和援助的义务。关于这一点，成文史仅有片断的记载；罗马国家，一开始就表现为这样一种超乎一切的力量，以致防御侵害的权利就转到了它的手里。当亚庇乌斯·克劳狄乌斯被捕时，他的氏族的全体成员，包括他的私敌在内，都穿上丧服。85在第二次布匿战争86时，各氏族都联合起来，赎回他们的被俘的同氏族人；元老院则禁止它们这样做。","language":"中文","translation":false},{"id":"family-1-290","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":290,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"7.使用氏族名称的权利。这种权利一直保持到帝政时代；被释奴隶可以采用他们从前的主人的氏族名称，但不能获得氏族的权利。","language":"中文","translation":false},{"id":"family-1-291","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":291,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"8.接纳外人入族的权利。其办法是接纳到某一家庭中(像印第安人所做的那样)，这同时也就是接纳入族。","language":"中文","translation":false},{"id":"family-1-292","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":292,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"9.关于选举和罢免酋长的权利，任何地方都没有提到过。但是，由于在罗马存在的最初时期，从选举产生的王起，自上而下一切官职都是选举或任命的，同时，库里亚的祭司也是由库里亚选举的，因此我们可以推断，氏族酋长(principes)也定然如此，虽然氏族酋长从氏族内同一家庭选出的办法可能已成为规则。","language":"中文","translation":false},{"id":"family-1-293","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":293,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这就是罗马氏族的职能。除了已经完成向父权制的过渡这一点以外，都完全是易洛魁氏族的权利与义务的再版；在这里也“可以清楚地看到易洛魁人”87。","language":"中文","translation":false},{"id":"family-1-294","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":294,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"今天[78]就连最著名的历史编纂学家们在内，关于罗马氏族制度的概念还是怎样的一片混乱，仅举一例就可以看出。在蒙森关于共和时代和奥古斯都时代罗马氏族名称的论文(《罗马研究》1864 年柏林版第1卷)中，有这样一段话：","language":"中文","translation":false},{"id":"family-1-295","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":295,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“除了血族的一切男性成员以外，——被接纳入族和受保护的人包括在内，但奴隶当然除外，——血族的名称也给予妇女……部落<蒙森在这里如此翻译gens一词>是……一个从共同的——真实的或推测的或甚至虚构的——世系中产生的，由共同的节日、墓地和继承权联合起来的共同体，一切有人身自由的个人，因而也包括妇女，都可以而且必须算在该共同体内。但是，确定已婚妇女的血族名称却成了一种困难。当妇女只能同自己血族的成员结婚时，这一困难自然是不存在的；而可以证明的是，在长时期内，妇女和血族以外的人结婚比同血族以内的人结婚要困难得多，因为这种在血族以外结婚的权利(gentis enuptio)到6世纪时，还被当作赏给个人的特权……但是，凡是实行这种外婚制的地方，妇女在上古时代是转入夫方部落的。毫无疑问，依照古代的宗教婚姻，妇女完全加入夫方的法的和宗教的公社，而脱离她自己的公社。谁不知道出嫁的妇女就丧失了在本氏族内继承遗产或将自己的遗产传给本氏族成员的权利，而加入自己的丈夫、子女以及他们的所有同氏族人的继承团体呢？假使她被她的丈夫接纳而加入他的家庭，那么她怎能和他的血族不相干呢？”(第9－11页)","language":"中文","translation":false},{"id":"family-1-296","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":296,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"可见，蒙森断言，属于某一氏族的罗马女子，最初只能在她的氏族内部结婚，因而，罗马的氏族是内婚制，不是外婚制。这种跟其他民族的全部经历相矛盾的观点，主要是(即使不完全是)以李维著作中引起很多争论的唯一的一段话(第39卷第19章)[79]为依据的，这段话说，元老院于罗马城建立568年即公元前186年，曾作出如下的决议：","language":"中文","translation":false},{"id":"family-1-297","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":297,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"uti Feceniae Hispalae datio，deminutio，gentis enuptio，tutoris optio item esset quasi ei vir testamento dedisset；utique ei ingenuo nubere liceret，neu quid ei qui eam duxisset，ob id fraudi ignominiaeve esset，——费策妮娅·希斯帕拉应有处理她的财产、减少她的财产、在氏族以外结婚、给自己选定保护人的权利，如同她的<已故的>丈夫曾用遗嘱把这个权利授予她一样；她可以和一个完全自由的人结婚，不能认为娶她为妻的人是做了不好的或可耻的事情。","language":"中文","translation":false},{"id":"family-1-298","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":298,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"毫无疑问，在这里，一个被释女奴隶费策妮娅获得了在氏族以外结婚的权利。同样无疑的是，丈夫也有权用遗嘱的方式允许妻子在他死后有权在氏族以外结婚。但是在哪一个氏族以外呢？","language":"中文","translation":false},{"id":"family-1-299","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":299,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如果像蒙森所推测的那样，妇女必须在她的氏族内部结婚，那么她在结婚以后也仍然留在该氏族以内。不过，第一，正是这个关于氏族内婚的断言，尚待证明。第二，如果妇女必须在她的氏族内部结婚，那么，男子自然也应当如此，否则他就会找不到妻子。这样一来，就成了丈夫可以用遗嘱把一项他自己也没有并且自己也享受不到的权利传给他的妻子了；这从法律的观点来看是荒谬的。蒙森也感觉到了这一点，因此，他又推测道：","language":"中文","translation":false},{"id":"family-1-300","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":300,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“为了在血族以外结婚，在法律上，大概不仅需要得到掌权者的同意，而且需要得到全体氏族成员的同意。”(第10页注)","language":"中文","translation":false},{"id":"family-1-301","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":301,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这首先是一个非常大胆的推测；其次，它跟那个决议的明确语意相矛盾；元老院是代替她的丈夫把这个权利给予她的；元老院给予她的显然不多不少恰恰和她的丈夫可能给予她的一样多；但是元老院给予她的乃是没有任何其他限制的绝对权利，以便她如果使用这个权利，她的新丈夫也不应因此受到损害；元老院甚至责成现在的和将来的执政官和大法官注意不要使她因此遭到任何烦恼。这样，蒙森的推测便全然不能成立了。","language":"中文","translation":false},{"id":"family-1-302","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":302,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"或者，再假定，一个妇女和别的氏族的男子结婚，而她本人仍留在她原来的氏族内。这样一来，依照上面所引的那个决议，她的丈夫就有权允许他的妻子在她自己的氏族以外结婚。这就是说，他有权处理他所不属于的那个氏族的事务了。这是十分荒谬的事，用不着多说的。","language":"中文","translation":false},{"id":"family-1-303","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":303,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"因此，剩下的只有这样一个推测，即妇女第一次结婚是嫁给别的氏族的男子，结婚后她便立即转入夫方的氏族，如蒙森事实上对于这类场合所容许的那样。这样一来，一切相互关系立刻就不言自明了。妇女由于结婚而脱离她的老氏族，加入新的、夫方的氏族团体，这样她便在那里占着一个完全特殊的地位。虽然她也是氏族的一员，但她并不是血缘亲属；她加入氏族的方式，从一开始就使她不受因结婚而加入的那个氏族禁止内部通婚的一切规定的束缚；其次，她已经被接受到氏族的继承团体中来，可以在她的丈夫死亡时继承他的财产，即一个氏族成员的财产。为了把财产保存在氏族以内，她必须同她的第一个丈夫的同氏族人结婚而不得同别的任何人结婚，这岂不是再自然不过的事吗？如果一定要造成例外，那么除了把这份财产遗留给她的第一个丈夫之外，试问谁还有资格授权她这样做呢？在他把一部分财产遗留给她，而同时允许她通过结婚或当作结婚的结果而把这一部分财产转移到别的氏族的瞬间，这份财产还是属于他的；因而，他实际上只是处置他自己的财产。至于这个妇女本身以及她和她的丈夫的氏族的关系，那么，正是他通过自由意志的行为——结婚，使她加入了这个氏族；因此，同样自然的是，也正是他可以授权她通过第二次结婚而退出这个氏族。总之，只要我们抛弃罗马氏族实行内婚制的奇怪观念，而同摩尔根一起承认它最初是实行外婚制的氏族，那么问题就很简单而不言自明了。","language":"中文","translation":false},{"id":"family-1-304","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":304,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"还有最后一种推测，这种推测也有它的拥护者，而且它的拥护者似乎最多。根据这个推测，那个决议只是说：","language":"中文","translation":false},{"id":"family-1-305","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":305,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“被释奴婢(libertae)没有特别的许可，不得e gente enubere<在氏族以外结婚>，也不得作出任何由于丧失家庭权利而使被释奴婢脱离氏族团体的行为。”(朗格《罗马的古代》1856年柏林版第1卷第195页，那里谈到我们从李维著作中引用的那段话时，引用了胡施克的话88)","language":"中文","translation":false},{"id":"family-1-306","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":306,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如果这一推测是正确的，那么那个决议对于完全自由的罗马妇女的地位根本就什么也没有证明；更谈不上她们应在氏族内部结婚的义务了。","language":"中文","translation":false},{"id":"family-1-307","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":307,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"Enuptio gentis［在氏族以外结婚］一语，只出现在上面那个决议中，在全部罗马文献中再没有遇见过；enubere——与外人结婚——一语只遇见三次，也是在李维的著作中，而且和氏族无关。那种虚幻的、认为罗马妇女只能在本氏族内部结婚的看法，其来源仅仅是那个决议。但是这种看法是绝对站不住脚的。因为，那个决议或者只是与被释女奴隶所受的特殊限制有关，那么它对于完全自由的妇女(ingenuae)就什么都没有证明；或者它也适用于完全自由的妇女，那么它倒证明妇女按照通例是在本氏族以外结婚，而结婚以后便转入夫方的氏族，从而证明蒙森说得不对，而摩尔根是正确的。","language":"中文","translation":false},{"id":"family-1-308","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":308,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在罗马建城差不多300年后，氏族联系还这样牢固，以致一个名门氏族，即法比氏族，经元老院许可，竟以自己的力量征伐了邻近的维爱城。据说有306个法比人出征，尽为伏兵所杀；唯一剩下的一个男孩，延续了这个氏族。","language":"中文","translation":false},{"id":"family-1-309","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":309,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们已经说过，10个氏族构成一个胞族，胞族在这里叫作库里亚，它有着比希腊胞族更重要的社会职能。每一个库里亚都有自己的宗教仪式、圣物和祭司；全体祭司构成罗马祭司团之一。10个库里亚构成一个部落，这种部落，像其余的拉丁部落一样，最初大概有一个选举产生的酋长——军事首长兼最高祭司。所有三个部落合在一起，构成罗马人民，即populus romanus。","language":"中文","translation":false},{"id":"family-1-310","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":310,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，只有身为氏族成员，并且通过自己的氏族而为库里亚成员和部落成员的人，才能属于罗马人民。罗马人民最初的制度是这样的：公共事务首先由元老院处理，而元老院，正像尼布尔最先正确地看到的那样，是由300个氏族的酋长组成的89；正因为如此，他们作为氏族的长老被称为patres，即父老，而他们全体则构成元老院(长老议事会，由senex——老者一词而来)。氏族酋长总是从每个氏族的同一家庭中选出的习俗，在这里也造成了最初的部落显贵；这些家庭自称为贵族，并且企求进入元老院和担任其他一切官职的独占权。随着时间的进展，人民容忍了这种企求，这种企求就变成实际的权利，这一点在关于罗慕洛赐给第一批元老及其子孙以贵族身分和特权的传说中得到了反映。元老院像雅典议事会一样，在许多事情上有决定权，在比较重要的事情，尤其是新法律方面有权预先讨论。这些新法律，最后由叫作comitia curiata(库里亚大会)的人民大会通过。来参加大会的人民按库里亚分组，而在每个库里亚内大概又按氏族分组；在通过决议时30个库里亚各有一票表决权。库里亚大会通过或否决一切法律，选举一切高级公职人员，包括勒克斯(所谓王)在内，宣战(但由元老院媾和)，并以最高法院资格，在一切事关判处罗马公民死刑的场合，根据当事人的上诉作最后的决定。最后，与元老院和人民大会并列的，还有勒克斯，他完全相当于希腊的巴赛勒斯，但决不像蒙森所描述的那样90几乎是专制的王。[80]他同样也是军事首长、最高祭司和某些法庭的审判长。他决没有民政方面的权力，换句话说，决没有处理公民的生命、自由和财产的权力，除非这些权力来自军事首长的惩戒权或法庭审判长的判决执行权。勒克斯的职位不是世袭的；相反地，他大概是由其前任推荐，先由库里亚大会选出，然后在第二次大会上被隆重委任。他也是可以罢免的，高傲的塔克文的命运，便是证明。","language":"中文","translation":false},{"id":"family-1-311","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":311,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"像英雄时代的希腊人一样，罗马人在所谓王政时代也生活在一种以氏族、胞族和部落为基础，并从它们当中发展起来的军事民主制之下。尽管库里亚和部落可能一部分是人为的组织，但它们都是按照它们所由发生并且从四面包围着它们的那种真正的、自然产生的社会的模型造成的。尽管自然成长的罗马贵族已经获得了牢固的基础，尽管担任勒克斯的人力图逐渐扩大自己的权力，但是所有这一切并没有改变制度的最初的根本性质，而全部问题就在于这个最初的根本性质。","language":"中文","translation":false},{"id":"family-1-312","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":312,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这时，罗马城以及靠征服而扩大了的罗马地区上的人口日益增加；增加的人口中一部分是外来移民，一部分是被征服地区，主要是拉丁地区的居民。所有这些新的国民(关于被保护民的问题，这里暂且不谈)，都处在旧的氏族、库里亚和部落之外，因而，不是populus romanus即本来的罗马人民的组成部分。他们是人身自由的人，可以占有地产，必须纳税和服兵役。可是他们不能担任任何官职；既不能参加库里亚大会，也不能参与征服得来的国有土地的分配。他们构成被剥夺了一切公权的平民。由于他们的人数不断增加，由于他们受过军事训练并有武装，于是就成了一种同这时根本禁止增加外人的旧的populus相对抗的可怕力量了。加以土地看来几乎是平均分配于populus和平民之间的，而商业和工业的财富，虽然还不十分发达，可能也主要是在平民手中。","language":"中文","translation":false},{"id":"family-1-313","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":313,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由于全部传说的罗马原始史都被浓厚的黑暗所笼罩，这种黑暗又因后世受过法学教育的史料典籍著作家们的唯理主义－实用主义的解释的尝试和报告而更加浓厚，因而，关于使古代氏族制度终结的革命发生的时间、进程和动因，都不可能说出什么确定的意见。只有一点是肯定的，这就是革命的原因在于平民和populus之间的斗争。","language":"中文","translation":false},{"id":"family-1-314","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":314,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"据说是由塞尔维乌斯·土利乌斯这位勒克斯依照希腊的榜样特别是梭伦的榜样制定的新制度，设立了新的人民大会；能参加或不得参加这个大会的，不分populus和平民，都依是否服兵役而定。凡是应服兵役的男子，都按其财产分为六个阶级。前五个阶级中每个阶级的最低财产额为：一、10万阿司；二、75000阿司；三、5万阿司；四、25000阿司；五、11000阿司；据杜罗·德·拉·马尔计算，这些数目大约相当于14000、10500、7000、3600和1540 马克91。第六阶级为无产者，是由那些没有什么财产、不服兵役和不纳税的人构成的。在新的百人团人民大会(comitia centuriata)上，公民以军队方式按连队来编组，每队100人，称百人团，每个百人团有1票表决权。但是，第一阶级出80个百人团，第二阶级出22个，第三阶级出20个，第四阶级出22个，第五阶级出30个，而第六阶级，为了体面起见，也准出1个。此外，还有从最富裕的公民中征集的骑士所组成的18个百人团；一共有193个百人团；多数票为97票。但骑士和第一阶级合在一起就有98票，即占多数；只要他们意见一致，就可以不征询其余阶级的意见，决议也就有效了。","language":"中文","translation":false},{"id":"family-1-315","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":315,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"以前库里亚大会的一切政治权利(除了若干名义上的权利以外)，现在都归这个新的百人团大会了；这样一来，库里亚和构成它们的各氏族，像在雅典一样，就降为纯粹私人的和宗教的团体，并且作为这样的团体还苟延残喘了很久，而库里亚大会不久就完全消失了。为了把三个旧的血族部落也从国家中排除出去，便设立了四个地区部落，每个地区部落居住罗马城的四分之一，并享有一系列的政治权利。","language":"中文","translation":false},{"id":"family-1-316","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":316,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，在罗马也是在所谓王政被废除之前，以个人血缘关系为基础的古代社会制度就已经被炸毁了，代之而起的是一个新的、以地区划分和财产差别为基础的真正的国家制度。公共权力在这里体现在服兵役的公民身上，它不仅被用来反对奴隶，而且被用来反对不许服兵役和不许有武装的所谓无产者。","language":"中文","translation":false},{"id":"family-1-317","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":317,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"只是在那僭取了真正王权的最后一个勒克斯，即高傲的塔克文被驱逐以后，在两个拥有同等职权(像在易洛魁人那里那样)的军事首长(执政官)代替了一个勒克斯以后，这个新制度才得到了进一步的发展，而罗马共和国的全部历史也就在这个制度的范围内演变，这里包括，共和国的贵族与平民为了担任官职以及分享国有土地而进行种种斗争，最后贵族溶化在大土地所有者和大货币所有者的新阶级中，这种大土地所有者和大货币所有者逐渐吞并了因兵役而破产的农民的一切地产，并使用奴隶来耕种由此产生的广大庄园，把意大利弄到十室九空的地步，从而不仅给帝政而且也给帝政的后继者德意志野蛮人打开了门户。","language":"中文","translation":false},{"id":"family-1-318","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":318,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"七 克尔特人和德意志人92的氏族93","language":"中文","translation":false},{"id":"family-1-319","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":319,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由于篇幅的原因，我们不能详细研究今天仍然在各种不同的蒙昧民族和野蛮民族中间以比较纯粹或比较模糊的形式存在着的氏族制度，或者亚洲的文化民族的古代历史上的氏族制度的痕迹了。[81]这两者是到处都可以见到的。只举几个例子：在人们还不知道什么是氏族的时候，那一位曾经费了莫大气力去误解氏族问题的麦克伦南，就已经证实了氏族的存在，并且大体上正确地描述了卡尔梅克人、切尔克斯人、萨莫耶特人[82]的氏族，以及三个印度民族——华拉耳人、马加尔人、曼尼普尔人的氏族。[83]不久以前，马·柯瓦列夫斯基也发现并描述了北萧胡人、显胡苏人、斯万人和其他高加索部落的氏族。在这里，我们只对克尔特人和日耳曼人的氏族的存在，作若干简短的记述。","language":"中文","translation":false},{"id":"family-1-320","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":320,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"克尔特人的保存到今天的最古的法律，使我们看到了仍然充满着活力的氏族；在爱尔兰，甚至到今天，在英国人用暴力炸毁了氏族以后，它至少还本能地存在于人民的意识中；在苏格兰，在上世纪中叶，它还处于全盛时期，在这里它也只是由于英国人的武器、立法和法庭才被消灭的。","language":"中文","translation":false},{"id":"family-1-321","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":321,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在威尔士被英国人征服以前数世纪94，即至迟于11世纪所制定的古代威尔士的法律，还表明有整个村落共同耕作的事情，虽然这只是一种普遍流行的早期习俗的稀有残余；每个家庭有供自己耕作的五英亩土地；此外，另有一块土地共同耕种，收获物实行分配。从它跟爱尔兰和苏格兰类似这一点来看，毫无疑问这种农村公社乃是一种氏族或氏族分支，即使对威尔士法律的重新考查——我没有时间去这样做(我的摘要是在1869年作的95)——未必能直接证实这一点。然而，威尔士以及爱尔兰的材料却直接证明，在11世纪时，克尔特人的对偶婚还根本没有被专偶制所代替。在威尔士，婚姻只有满了七年之后才不能解除，或者更确切些说，才不能终止。甚至只差三夜就满七年，夫妻还是可以分离的。那时便要分家：由妻子来分，丈夫取他的一份。家具是按一定的非常有趣的规则来分的。如果是丈夫提出离婚的，那他必须把妻子的嫁妆和其他某些东西还给她；如果是妻子提出离婚的，那她便少得一点。如有三个子女，丈夫分两个，妻子分一个，即中间那一个。如果妻子在离婚后重新结婚，而她的前夫想重新要她时，即使她的一只脚已经踏上新夫的婚床，也要顺从前夫的要求。而如果已经同居七年，即使以前并未正式结婚，他们也是夫和妻。在结婚以前，少女的贞操完全不严格遵守，也不要求遵守；与此有关的规定，具有非常轻佻的性质，同资产阶级的道德完全不符。如果妻子与人通奸，丈夫可以殴打她(这是允许他这样做的三种情况之一，在其余场合殴打妻子是要受罚的)，但是这样一来，他就无权要求别的补偿了；因为","language":"中文","translation":false},{"id":"family-1-322","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":322,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“对于同一过错，或者要求赎罪，或者要求报复，但两者不可得兼”。[84]妻子可据以要求离婚而且在分财产时自己的权利又不受损失的理由，范围非常广：只要丈夫口有臭气就够了。为赎回初夜权而付给部落首领或国王的赎金(gobr merch，中世纪的marcheta 这个名称、法语的marquette就是由此而来的)在法典上起着很大的作用。妇女在人民大会上享有表决权。如果我们补充下面几点：在爱尔兰已经证明有类似情况存在；在那里，暂时性的婚姻也非常流行，在离婚时，妻子享有很大的明确规定的照顾，甚至对她的家务操持也要给以赔偿；在那里，还有“长妻”与其他诸妻并存的事，而在分配遗产时，婚生子女和非婚生子女没有任何差别，这样，我们便看到了一幅对偶婚的图景，与这种对偶婚比较起来，北美观行的婚姻形式就显得严格了，不过，对于一个在凯撒时代还过着群婚生活的民族来说，在11世纪有这种情形，是不足为奇的。","language":"中文","translation":false},{"id":"family-1-323","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":323,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"爱尔兰氏族(即sept［塞普特］；部落称为clainne，即克兰51)不仅由古代法典，而且还由17世纪被派到那里去把克兰领地变成英王王室领地的英国法学家们所证实并作过记述。直到那时，土地只要未被首领变为自己的私有领地，就仍是克兰或氏族的公共财产。如果某一氏族成员死亡，因而一户经济不再存在，首领(英国法学家称之为caput cognationis［宗族长］)便把全部土地在其他各户中间进行一次重新分配。这种分配，大体上应该是依照在德国通行的规则来进行的。即在今日，还可以见到一些属于所谓rundale［朗得尔］制度的村田，在四五十年前，这种村田是很多的。农民们，即租种被英国征服者所掠夺的先前属于氏族公有的土地的个体佃农们，每人为自己承租的地段交纳租金，但是却把全部耕地和草地合并起来，按照方位和土质分成许多“Gewanne”［“大块”］，如摩泽尔河沿岸所称呼的那样；每个人在每一大块中都有一份；沼地和牧场共同使用。就在50年前，有时还重新分配土地，有些时候每年都重新分配。这种实行朗得尔制度的村落的地界图，看去极似摩泽尔河沿岸或霍赫瓦尔德地区的一个德意志人农家公社的地界图。氏族此外还继续存在于“factions”［“帮”］中。爱尔兰农民常常分成各种帮派，它们是建立在看起来毫无意思和十分荒诞的、为英国人所完全不理解的差别的基础之上的，并且它们除了彼此之间进行心爱的盛大殴斗而外，似乎别无任何目的。这是被消灭了的氏族的人为的复活，是氏族灭亡后产生的代替物，这种代替物以特殊的方式证明了流传下来的氏族本能的继续存在。此外，有些地方，同氏族人还一道住在他们旧有的地区内；比如在30年代，莫纳亨郡的大多数居民只有四个姓，换言之，即起源于四个氏族或克兰。[85]","language":"中文","translation":false},{"id":"family-1-324","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":324,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在苏格兰，氏族制度是随着1745年起义被镇压而灭亡的。97至于苏格兰的克兰是这个制度的哪一个环节，尚待研究；但它是这样一个环节，则是没有疑问的。在瓦尔特·司各脱的小说中，我们可以看到关于苏格兰高地的这种克兰的生动描写。摩尔根说，这种克兰，","language":"中文","translation":false},{"id":"family-1-325","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":325,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“就组织和精神而言，乃是氏族的最好典型，也是氏族生活支配氏族成员的突出例证……从他们的结世仇和血族复仇上，从按克兰划分地区上，从他们的共同使用土地上，从克兰成员对于酋长的忠诚以及彼此间的忠诚上，我们都看到了氏族社会的那种通常的、持久的特征……世系是按照父权制计算的，因此男子的子女仍留在克兰内，而妇女的子女则转到他们父亲的克兰里去”[86]。","language":"中文","translation":false},{"id":"family-1-326","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":326,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"至于从前在苏格兰盛行过母权制，有下述事实为证：据贝达说，皮克特人的王室是按照女系继承的。[87]甚至普那路亚家庭的残余，在威尔士人以及苏格兰人中间还以初夜权的形式一直保存到中世纪，那时，只要是初夜权没有赎回，克兰的首领或国王，便可以作为以前的共同丈夫的最后代表者，对每个新娘行使这个权利。[88]","language":"中文","translation":false},{"id":"family-1-327","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":327,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"德意志人在民族大迁徒以前，曾组织成为氏族，这是没有疑问的。他们只是在公元前数世纪，才有可能占据了多瑙河、莱茵河、维斯瓦河和北方诸海之间的地区；基姆布利人和条顿人正处在大迁徙中，而苏维汇人只是到凯撒时代才稳定地定居下来。凯撒谈到苏维汇人时明确地说过：他们是按氏族和亲属关系(gentibus cogna－tionibusque)分开居住的98；而在gensJulia［尤利氏族］的一个罗马人的口中，gentibus这个名词有着不容误解的确定的意义。这适用于全体德意志人；甚至在被征服的罗马各行省，他们似乎还按氏族[89]定居。从《阿勒曼尼亚法典》99中可以得到证实，在多瑙河以南的被征服的土地上人们是按血族(genealogiae)分开居住的。这里使用的genealogia一词，与后来的马尔克公社或农村公社的意义完全相同。不久以前，柯瓦列夫斯基提出了一种见解，说这些ge－nealogiae都是大家庭公社，土地在它们之间进行分配，农村公社只是后来才从它们当中发展起来的。100所以关于fara也可以这样说，这个词在勃艮第人和伦巴德人那里——自然也在哥特部落和赫米奥南部落或高地德意志部落那里——的含义和《阿勒曼尼法典》上的genealogia一词的含义虽不完全相同，却也大体一致。这里摆在我们面前的究竟是氏族还是家庭公社，还需要作进一步研究。","language":"中文","translation":false},{"id":"family-1-328","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":328,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在一切德意志人中是否有一个表示氏族的共同名词，这个名词又是什么，关于这个问题，古代语言研究文献没有给我们提供答案。在语源上，哥特语的kuni，中古高地德意志语的是和希腊语的genos，拉丁语的gens相当的，而且是在相同的意义上来使用的。妇女的名称来自同一个词根，如希腊语的gyne、斯拉夫语的、哥特语的qvino，古斯堪的纳维亚语的kona，kuna等，这表明曾存在过母权制时代。——在伦巴德人和勃艮第人那里，像刚才说过的，我们看到fǎra一词，这个词被格林假定来源于词根fisan，意即生育。我则倾向于认为它来源于更显而易见的词根faran，意即乘车[90]、迁徙，用来表示当然只由亲属构成的迁徒队伍的一个固定的分队。这个词，在起初是向东方，后来又向西方迁徙的许多世纪中，渐渐地被用来指血族共同体本身了。——其次，哥特语的sibja，盎格鲁撒克逊语的sib，古代高地德意志语的sippia，sippa，都是亲属[91]的意思。在古代斯堪的纳维亚语中，仅有复数的sifjar 即亲属一词；单数只用作女神西芙［Sif］的名字。——最后，在《希尔德布兰德之歌》101中还见到另外一种用语，它出现在希尔德布兰德问哈杜布兰德的话中：","language":"中文","translation":false},{"id":"family-1-329","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":329,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“这群人中的男子，谁是你的父亲……或你是哪一血族的？”","language":"中文","translation":false},{"id":"family-1-330","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":330,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"要是德意志语有表示氏族的共同名称，那么这恐怕就是哥特语的kuni了；这不仅因为它和亲属语中相应的说法一致，而且因为最初表示氏族酋长或部落酋长的kuning(［王］)一词就是从kuni这个字演变来的。sibja(亲属)这个词似乎无须加以考虑；至少，sifjar在古代斯堪的纳维亚语中，不仅表示血缘亲属，而且也表示姻亲亲属，即包括至少两个氏族的成员；因此，sif这个词本身不可能是表示氏族的用语。","language":"中文","translation":false},{"id":"family-1-331","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":331,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"像在墨西哥人和希腊人那里一样，在德意志人那里，骑兵队和楔形步兵纵队的战斗队形，也是按氏族的组织来编的；如果塔西佗说的是按家庭和亲属关系[92]，那么这种不明确的用语的来由是，在塔西佗时代氏族在罗马早已不再是一个有生命力的团体了。","language":"中文","translation":false},{"id":"family-1-332","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":332,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"有决定意义的是塔西佗的这一段话，那里说：母亲的兄弟把他的外甥看作自己的儿子；有些人甚至认为舅父和外甥之间的血缘关系，比父子之间的血缘关系还要神圣和密切，所以当要求人质的时候，那个将受到约束的人的姊妹的儿子被认为是比他自己的儿子还要大的保证。在这里，我们看到了按照母权制组织起来的、因而是最初的氏族的活生生的残余，而且这种残余还被当作德意志人特有的一种东西。[93]某一个这样的氏族，其成员假如把自己的儿子当作某一庄严义务的担保物，而这个儿子却成了父亲违约的牺牲品，那么这位父亲就责任自负。但是假如成为牺牲品的是姊妹的儿子，那么这就违反了最神圣的氏族法规；男孩子或少年的最近的同氏族亲属，即首先负有保护他的义务的人，便对他的死负有罪责；这个同氏族亲属或者是不应当把他作为人质，或者是必须履行契约。即使我们在德意志人那里没有发现氏族制度的其他任何痕迹，那么有上面这一段话也就够了。[94]","language":"中文","translation":false},{"id":"family-1-333","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":333,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在古代斯堪的纳维亚的关于诸神的晚景和世界的毁灭的(《女预言者的预言》)103中，有一个地方更具有决定的意义，因为那是此后又过了大约800年。在这个《女预言者的预言》中，——如现在班格和布格所证明的104，这首歌中也包含有基督教的因素，——在描述大灾难前的普遍堕落和道德败坏的时代时说道：","language":"中文","translation":false},{"id":"family-1-334","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":334,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“兄弟们将互相仇视，互相杀戮，","language":"中文","translation":false},{"id":"family-1-335","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":335,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"姊妹的儿女们就要毁坏亲属关系了。”","language":"中文","translation":false},{"id":"family-1-336","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":336,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"Systrungr一字是母亲的姊妹的儿子的意思，在诗人看来，姊妹的子女否认相互之间的血缘亲属关系比兄弟互相残杀的罪还要大。起加强作用的是表示母方亲属关系的systrungar一词；要是不用这个词，而用(兄弟姊妹的子女)或syskinasynir (兄弟姊妹的儿子们)，那么第二行对于第一行就不是加强，而是减弱了。由此可见，甚至在产生《女预言者的预言》的海盗时代，在斯堪的纳维亚对于母权制的回忆还没有消失。","language":"中文","translation":false},{"id":"family-1-337","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":337,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"此外，在塔西佗时代，至少在他较为熟悉的[95]德意志人中间，母权制已经让位给父权制了：父亲的遗产由子女继承；如果没有子女，就由兄弟及叔伯和舅父继承。容许母亲的兄弟参加继承这一事实，是和刚刚所说的习俗的保存有关系的，同时也证明德意志人的父权制在当时还是多么新近。直到进入中世纪很久之后，也仍然可以见到母权制的遗迹。那时，在人们中间，特别是在农奴中间，似乎仍然不大信赖父系血统；所以，当封建领主向某个城市要求追回逃亡的农奴的时候，例如在奥格斯堡、巴塞尔和凯泽斯劳滕，就要求有六个最近的血缘亲属，而且是只限于母方的亲属来宣誓证实被告的农奴身分(毛勒《城市制度》第1卷第381页[96])。","language":"中文","translation":false},{"id":"family-1-338","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":338,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"当时刚刚灭亡的母权制，还有一个残余，这就是在罗马人看来几乎是不可理解的、德意志人对于女性的尊敬。在同德意志人缔结条约时，贵族家庭的少女被认为是最可靠的人质；想到自己的妻女可能被俘而沦为奴隶，这对于德意志人说来是很可怕的，并且最能激励他们的战斗士气；他们认为妇女体现着某种神圣的和先知的东西，他们甚至在最重要的事情上也听取妇女的意见，例如，利珀河畔布鲁克泰人的女祭司魏勒妲，就曾经是推动巴达维人起义的灵魂，在这次起义中，齐维利斯领导德意志人和比利时人动摇了罗马人在高卢的全部统治。105在家里妻子的统治看来是无可争辩的；自然，一切家务也都由妻子、老人和子女关照；丈夫则打猎，饮酒或游手好闲。塔西佗就是这样说的；但是由于他没有说谁耕田种地，并且确定地说，奴隶只纳贡，不服任何劳役，因此，耕种土地所需要的少量劳动，看来仍须由众成年男子来承担。","language":"中文","translation":false},{"id":"family-1-339","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":339,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如前所述，婚姻的形式是逐渐接近专偶制的对偶制。这还不是严格的专偶制，因为还允许显要人物实行多妻制。少女的贞操，一般说来，是严格遵守的(这和克尔特人相反)，同样，塔西佗也特别热情地说到德意志人的婚姻关系的不可破坏。他举出只有妻子通奸，才是离婚的理由。不过，他的话在这里留下了一些漏洞，而且过分明显地用来给放荡的罗马人作美德的镜子了。有一点是可以肯定的：如果说德意志人在自己的森林中曾经是这种世上少有的美德骑士，那么，只要和外界稍一接触，便足以使他们堕落到其余一般欧洲人的水平；在罗马世界中，恪守道德准则的最后痕迹消失得比德语还要快得多。只消读一读图尔的格雷戈里的作品，就可以相信这点了。不言而喻，在德意志人的原始森林中，不可能像在罗马那样，盛行骄奢淫逸的享乐生活，因此，在这方面，即使我们没有硬给德意志人加上在任何时候和任何地方的整个民族中都没有盛行过的节欲行为，他们也比罗马世界优越得多。","language":"中文","translation":false},{"id":"family-1-340","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":340,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"从氏族制度中产生了把父亲或亲属的仇敌关系像友谊关系一样继承下来的义务；同样，也继承用以代替血族复仇的、为杀人或伤人赎罪的赔偿金。这种赔偿金在上一代还被认为是德意志人特有的制度，但现在已经证明，在成百个民族中都是这样，这是起源于氏族制度的血族复仇的一种普遍的较缓和的形式。这种赔偿金，就像款待客人的义务一样，我们在美洲印第安人中间也可以看到；塔西佗关于款待客人的情形的描述(《日耳曼尼亚志》第21章)，与摩尔根关于印第安人款待客人的情形的描述，几乎在细节上都是一致的。","language":"中文","translation":false},{"id":"family-1-341","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":341,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"塔西佗时代的德意志人是否已经最终分配了耕地以及与此有关的那几段文字应如何解释，像这种热烈而无休止的争论，如今已经是过去的事了。自从证明差不多一切民族都实行过土地由氏族后来又由共产制家庭公社共同耕作，——据凯撒证明[97]，在苏维汇人当中就是如此，——继而差不多一切民族都实行过把土地分配给单个家庭并定期实行重新分配以来；自从确定耕地的这种定期重新分配的办法在德意志本土有些地方还保存到今日以来，关于这个问题就不必再费一词了。如果从凯撒到塔西佗的150年间，德意志人从凯撒所明确指出的苏维汇人的共同耕作(他说，他们完全没有被分割的或私有的土地)过渡到了土地每年重新分配的个体耕作，那么这确实是个很大的进步；在这样短的时间内，而且没有任何外来干涉，要从那个阶段过渡到土地完全私有，是根本不可能的。因此，我在塔西佗的著作中只读到他说得很简洁的话：他们每年更换(或重新分配)耕地一次，同时还留下充分的公有土地。[98]这是和德意志人当时的氏族制度完全相适应的一个耕作和土地占有阶段。[99]上面这一段，我仍照以前各版的样子保留下来，未作更改。在此期间，问题已转到另外一个方面了。柯瓦列夫斯基已经证明(见前引书，第44页[100])，家长制家庭公社乃是母权制共产制家庭和现代的孤立的家庭之间的中间阶段，它虽不是到处流行，但是流行很广。在这以后，问题已经不再像毛勒和瓦茨争论的那样——土地是公有还是私有，而是公有的形式是什么了。毫无疑问，在凯撒时代，苏维汇人不仅有过土地公有，而且也有过共同核算的共同耕作。至于他们的经济单位是氏族，还是家庭公社，或者是介于两者之间的某种共产制亲属集团，或者所有三种集团依土地条件的不同都存在过，关于这些问题将来还会长久争论。但柯瓦列夫斯基认定，塔西佗所描述的状况，不是以马尔克公社或农村公社为前提，而是以家庭公社为前提的；只是过了很久，由于人口增加，农村公社才从这种家庭公社中发展出来。","language":"中文","translation":false},{"id":"family-1-342","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":342,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"按照这个观点，德意志人在罗马时代在他们所占据的土地上的居住区，以及后来在他们从罗马人那里夺取的土地上的居住区，不是由村组成，而是由大家庭公社组成的，这种大家庭公社包括好几代人，耕种着相当的地带，并和邻居一起，作为共同的马尔克来使用四周的荒地。在这种情况下，塔西佗著作中谈到更换耕地的那个地方，实际上就应当从农学意义上去理解：公社每年耕种另一个地带，而将上年的耕地休耕，或令其全然抛荒。由于人口稀少，荒地总是很多的，因之，任何争夺地产的纠纷，就没有必要了。只是经过数世纪之后，当家庭成员的人数过多，以致在当时的生产条件下共同经营已经成为不可能的时候，这种家庭公社才解体；以前公有的耕地和草地，就按人所共知的方式，在此后正在形成的单个农户之间实行分配，这种分配起初是暂时的，后来便成为永久的，至于森林、牧场和水域则依然是公共的。","language":"中文","translation":false},{"id":"family-1-343","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":343,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这一发展过程，对于俄国，看来已经是历史上完全证实了的。至于德意志，乃至其余的日耳曼诸国，不可否认，这个推测，在许多方面，较之迄今流行的把农村公社的存在追溯到塔西佗时代的推测，能更好地诠释典籍，更容易解决困难。最古的文件，例如Codex Laureshamensis106，一般说来，用家庭公社来解释，就比用农村马尔克公社来解释要好得多。另一方面，这种家庭公社又造成了新的困难和引起了新的需要解决的问题。在这里只有新的研究才能作出结论；但是，我不能否认，作为中间阶段的家庭公社，在德国、斯堪的纳维亚以及英国很可能也都有过。","language":"中文","translation":false},{"id":"family-1-344","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":344,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在凯撒时代，一部分德意志人刚刚定居下来，一部分人尚在找寻定居的地方，但在塔西佗时代，他们已有整整百年之久的定居生活了；与此相适应，在生活资料的生产方面也有了无可怀疑的进步。他们居住在木屋中，穿的还是很原始的森林居民的衣服：粗糙的羊毛外套，兽皮；妇女和显要人物则穿麻布内衣。食物为乳、肉、野生果实，以及像普林尼所补充的燕麦粥[101](直到今日，这还是爱尔兰和苏格兰的克尔特人的民族食物)。他们的财富是家畜，但是品种很差；牛矮小难看，没有角；马是小马，不善奔驰。钱币很少使用，数量有限，而且只是罗马钱币。他们不制造金银饰品，也不重视这些。铁是很少见的，看来至少在莱茵河和多瑙河诸部落中间差不多全靠输入，而不是自行冶炼。鲁恩文字(模仿希腊和拉丁字母造成文字)仅仅用作暗语文字，并且专供宗教巫术之用。把人当作祭品的做法还在流行。一句话，我们在这里所看到的，是一个刚从野蛮时代中级阶段进到高级阶段的民族。不过，虽然与罗马人直接接壤的各部落由于输入罗马的工业品方便，因而其独立的金属业和纺织业的发展受到了阻碍，但是在东北部，在波罗的海沿岸诸部落中，则无疑发展起了这样的工业。在石勒苏益格沼地所发现的武器——长的铁剑、环甲、银盔等等，和2世纪末的罗马铸币一起——以及由于民族大迁徙而流传各地的德意志金属制品，这些东西即使起初是模仿罗马式样的，但都相当讲究和独具风格。向文明的罗马帝国迁徙，使这种土生土长的工业，除了在英国以外，到处都绝迹了。至于这种工业是怎样一致地发生和发展起来的，可以拿青铜手镯为例来说明。在勃艮第、罗马尼亚、亚速海沿岸发现的青铜手镯，看来可能跟英国和瑞典的青铜手镯同出于一个作坊，因而同样无疑地是由日耳曼人生产的。","language":"中文","translation":false},{"id":"family-1-345","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":345,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"他们的制度也是跟野蛮时代高级阶段相适应的。据塔西佗说，到处都有氏族酋长(principes)议事会，它处理比较小的事情，而比较重大的事情则由它提交人民大会去解决；这种人民大会，在野蛮时代低级阶段上，至少在我们知道有人民大会的地方，例如在美洲人那里，仅仅氏族才有，而部落或部落联盟是没有的。氏族酋长(principes)和军事头领(duces)还有显著的区别，正像在易洛魁人那里一样。氏族酋长已经部分地靠部落成员的献礼如家畜、谷物等来生活；他们——如在美洲一样——大半是从同一家庭中选举出来的；向父权制的过渡，例如在希腊和罗马，促进了选举制逐渐变为世袭制，从而促进了每个氏族形成一个贵族家庭。这种古代的所谓部落贵族，大多数在民族大迁徙中或在它以后不久便衰落了。军事首长完全是按才能来选举的，不问世系如何。他们的权力很小，必须以自己的榜样来发挥作用；至于军队的实际惩戒权，塔西佗确定地说，是握在祭司们手里的。真正的权力集中在人民大会上。大会由王或部落酋长主持；决定由人民来做：怨声表示反对，喝采、敲打武器表示赞成。人民大会同时也是审判法庭；各种控诉都向它提出，并由它作出判决，死刑也在这里宣判，但只有对卑怯、背叛民族和反自然的淫行才判处死刑。在氏族和其他分支中，也是由以氏族酋长为主席的全体大会进行审判；像在德意志人的一切最早的法庭上一样，氏族酋长可能只是诉讼的领导者和审问者；德意志人的判决，不拘何时何地，都是由全体作出的。","language":"中文","translation":false},{"id":"family-1-346","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":346,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"部落联盟从凯撒时代起就组成了；其中有几个联盟已经有了王；最高军事首长，像在希腊人和罗马人中间一样，已经图谋夺取专制权，而且有时也达到了目的。这种侥幸的篡夺者决不是绝对的统治者；不过他们已经开始粉碎氏族制度的枷锁了。被释奴隶一般处于低微地位，因为他们不能属于任何氏族，而在新王的手下，这样一些宠儿却往往获得高官、财富和荣誉。罗马帝国被征服以后，现在成了大国国王的军事首长那里也发生了同样的事。在法兰克人中间，国王的奴隶和被释奴隶，起初在宫廷里，后来在国家中，都起了重要的作用；新的贵族有很大一部分是从他们当中产生的。","language":"中文","translation":false},{"id":"family-1-347","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":347,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"有一种设施促进了王权的产生，这就是扈从队。我们在美洲红种人中间就已经看到，与氏族制度并行，还形成了一种独立自主地从事战争的私人团体。这种私人团体，在德意志人中间，已经成为经常性的团体了。博得了声誉的军事领袖，在自己周围集合一队掠夺成性的青年人，他们对他个人必须忠诚，而他对他们亦然。首领供给吃喝并奖赏他们，把他们编成等级；对于小规模的征战，他们充当卫队和随时可以战斗的队伍；对于大规模的征战，他们是现成的军官团。不管这种扈从队必然是多么弱小，像后来例如在意大利奥多亚克麾下所表现的那样，但是他们仍然成为古代的人民自由走向衰落的开端；在民族大迁徙时期和迁徙以后，他们也表明自己的作用正是这样。因为，第一，他们促进了王权的产生；第二，如塔西佗已经指出的，只有通过不断的战争和抢劫，才能把他们纠合在一起。掠夺成了目的。如果扈从队首领在附近地区无事可做，他就把自己的人马带到发生了战争、可以指望获得战利品的别的民族那里去；由德意志人组成的辅助军，在罗马的旗帜下，甚至大举对德意志人作战，这种辅助军有一部分就是由这种扈从队编成的。德意志人的耻辱和诅咒——雇佣兵制度，在这里已经初具雏形。在罗马帝国被征服以后，国王们的这种扈从兵，就同非自由人和罗马人出身的宫廷奴仆一起，成了后来的贵族的第二个主要组成部分。","language":"中文","translation":false},{"id":"family-1-348","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":348,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由此可见，一般说来，在联合为民族［Volk］的德意志各部落中，也曾发展出像英雄时代的希腊人和所谓王政时代的罗马人那样的制度，即人民大会、氏族酋长议事会和已在图谋获得真正王权的军事首长。这是氏族制度下一般所能达到的最发达的制度；这是野蛮时代高级阶段的典型制度。只要社会一越出这一制度所适用的界限，氏族制度的末日就来到了；它就被炸毁，由国家来代替了。","language":"中文","translation":false},{"id":"family-1-349","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":349,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"据塔西佗说，德意志人是人口众多的民族。我们从凯撒的著作中可以得出一个关于各德意志民族人数的大致概念；他认为住在莱茵河左岸的乌济佩特人和邓克泰人的人口，包括妇女和儿童在内，共为18万人。因而，每个民族大约有10万人[102]，这已经大大超过例如易洛魁人在其全盛时代的总数，那时易洛魁人不到2万人，但已成为自大湖至俄亥俄河和波托马克河整个地区的可怕力量。如果我们根据现有材料，把莱茵河附近定居的大家知道得比较确切的民族试着划分一下，那么每一个这样的民族在地图上所占的面积平均约等于普鲁士的一个行政区，即约为1万平方公里，或182平方地理里。但是，罗马人的Germania Magna［大日耳曼尼亚］，直到维斯瓦河为止，占有依整数计共50万平方公里的面积。如果一个民族的平均人口为10万人，那么整个大日耳曼尼亚的人口总数，应达500万；对于野蛮时代的民族集团来说，这是一个很大的数目，而就今日的情况来说——1平方公里10人，或1平方地理里550人——这是极其微小的数目。但是这并不包括生活在那个时候的全部德意志人。我们知道，沿喀尔巴阡山脉直至多瑙河口，都居住着哥特系统的德意志民族——巴斯塔尔人、佩夫金人等等，——它们的人数非常之多，因而，普林尼认为他们是德意志人的第五个大系统[103]，而这些在公元前180年已经替马其顿王柏修斯做过雇佣兵的德意志人，还在奥古斯都在位的初年就已突进到阿德里安堡附近了。假定他们的人数只有100万人，那么到公元初，德意志人的大概数目，就至少有600万了。","language":"中文","translation":false},{"id":"family-1-350","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":350,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在他们定居日耳曼尼亚以后，人口一定是日益迅速地增长的；单是上面提到的工业方面的进步，就足以证明这一点。在石勒苏益格沼地所发现的古物，就其中的罗马铸币来判断，是属于3世纪的。由此可见，到这个时候，在波罗的海沿岸金属业和纺织业已经很发达了，跟罗马帝国已有频繁的往来，比较有钱的人已享有某些奢侈品，——这一切都是人口更为稠密的迹象。而在这个时期，德意志人在莱茵河、罗马边墙和多瑙河全线，从北海起到黑海止，也开始了总进攻，——这也是人口日益增多，竭力向外扩张的直接证明。斗争持续了300年，在斗争期间，哥特民族的整个大系统(斯堪的纳维亚的哥特人和勃艮第人除外)向东南推进，形成了漫长的进攻线的左翼；进攻线的中央是高地德意志人(赫米奥南人)，沿多瑙河上游突进；右翼是易斯卡伏南人即现今所谓法兰克人，沿莱茵河突进；征服不列颠，则是印格伏南人的事情。到5世纪末，罗马帝国已是那么衰弱，毫无生气和束手无策，因而为德意志人的入侵敞开了大门。","language":"中文","translation":false},{"id":"family-1-351","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":351,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"上面我们是站在古希腊罗马文明的摇篮旁边。这里我们却站在这一文明的棺木旁边了。罗马的世界霸权的刨子，刨削地中海盆地的所有地区已经有数百年之久。凡在希腊语没有进行抵抗的地方，一切民族语言都不得不让位于被败坏的拉丁语；一切民族差别都消失了，高卢人、伊比利亚人、利古里亚人、诺里克人都不复存在，他们都变成罗马人了。罗马的行政和罗马的法到处都摧毁了古代的血族团体，这样也就摧毁了地方的和民族的自主性的最后残余。新出炉的罗马公民身分并没有提供任何补偿；它并不表现任何民族性，它只是民族性欠缺的表现。新民族［neue Nationen］的要素是到处都具备的；各行省的拉丁方言差别越来越大；一度使意大利、高卢、西班牙、阿非利加成为独立区域的自然疆界依然存在，依然使人感觉得到。但是，任何地方都不具备能够把这些要素结成新民族［neue Nation］的力量，任何地方都还没有显示出发展能力或抵抗力的痕迹，更不用说创造力了。广大领土上的广大人群，只有一条把他们自己联结起来的纽带，这就是罗马国家，而这个国家随着时间的推移却成了他们最凶恶的敌人和压迫者。各行省消灭了罗马，罗马本身变成了行省的城市，像其他城市一样；它虽然有特权，但已经不再居于统治地位，已经不再是世界帝国的中心了，甚至也不再是皇帝和副皇帝的所在地了，他们现在住在君士坦丁堡、特里尔、米兰。罗马国家变成了一架庞大的复杂机器，专门用来榨取臣民的膏血。捐税、国家徭役和各种代役租使人民大众日益陷于穷困的深渊；地方官、收税官以及兵士的勒索，更使压迫加重到使人不能忍受的地步。罗马国家及其世界霸权引起了这样的结果：它把自己的生存权建立在对内维持秩序对外防御野蛮人的基础上；然而它的秩序却比最坏的无秩序还要坏，它说是保护公民防御野蛮人的，而公民却把野蛮人奉为救星来祈望。","language":"中文","translation":false},{"id":"family-1-352","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":352,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"社会状况同样也是绝望的。从共和制的末期起，罗马统治的目的已经放在残酷剥削被征服的各行省上了；帝制不但没有消除这种剥削，反而把它变成了常规。帝国越是走向没落，捐税和赋役就越是增加，官吏就越是无耻地进行掠夺和勒索。商业和工业向来不是统治着各民族的罗马人的事业；只有在高利贷方面，他们做到了空前绝后。商业所得到所保持的东西，都在官吏的勒索下毁灭了；而残存下来的东西，仅在帝国东部的希腊部分才有，不过，这一部分不在我们研究范围之内。普遍的贫困化，商业、手工业和艺术的衰落，人口的减少，都市的衰败，农业退回到更低的水平——这就是罗马人的世界霸权的最终结果。","language":"中文","translation":false},{"id":"family-1-353","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":353,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"农业是整个古代世界的决定性的生产部门，现在它更是这样了。在意大利，从共和制衰亡的时候起就几乎遍布全境的面积巨大的大庄园(Latifundien)，是用两种方法加以利用的：或者当作牧场，那里居民就被牛羊所代替，因为看管牛羊只用少数奴隶就行了；或者当作田庄，那里使用大批奴隶经营大规模的园艺业，——一部分为了满足主人的奢侈生活，一部分为了在城市市场上出售。大牧场保存了下来，甚至还扩大了；但田庄田产及其园艺业却随着主人的贫穷和城市的衰落而衰败了。以奴隶劳动为基础的大庄园经济，已经不再有利可图；而在当时它却是大规模农业的唯一可能的形式。现在小规模经营又成了唯一有利的形式。田庄一个一个地分成了小块土地，分别租给缴纳一定款项的世袭佃农，或者租给分成制农民，这种分成制农民只能获得他们一年劳动生产品的1/6，或者仅仅1/9，他们与其说是佃农，勿宁说是田产看管人。但是这种小块土地主要是交给隶农，他们每年缴纳一定的款项，被束缚在土地上，并且可以跟那块土地一起出售；这种隶农虽不是奴隶，但也不是自由的，他们不能和自由民通婚，他们相互间的婚姻也不被看作完全有效的，而是像奴隶的婚姻一样，只被看作简单的同居(contubernium)。他们是中世纪农奴的前辈。","language":"中文","translation":false},{"id":"family-1-354","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":354,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"古典古代的奴隶制，已经过时了。无论在乡村的大规模农业方面，还是在城市的工场手工业方面，它都已经不能提供值得费力去取得的收益，因为它的产品市场已经消失了。帝国繁荣时代的庞大的生产已经收缩为小农业和小手工业，这种小农业和小手工业都不能容纳大量奴隶了。只有富人的家庭奴隶和供他们显示豪华的奴隶，在社会上还有存在余地。但是，日趋灭亡的奴隶制仍然能够使人认为，一切生产劳动都是奴隶的事，让自由的罗马人来做有失他们的身分，而现在人人都是这种自由的罗马人了。结果，一方面，多余而成了累赘的被释奴隶的人数日益增加；另一方面，隶农的人数，破产的自由民(类似美国从前各蓄奴州的白种贫民)的人数，也日益增多。基督教对于古典古代奴隶制的逐渐灭亡是完全没有罪过的。它在罗马帝国和奴隶制同流合污达数世纪之久，以后也从来没有阻止过基督徒买卖奴隶，——既没有阻止过德意志人在北方或威尼斯人在地中海买卖奴隶，也没有阻止过后世买卖黑奴。[104]奴隶制已不再有利，因此也就灭亡了。但是垂死的奴隶制却留下了它那有毒的刺，即鄙视自由民的生产劳动。在这里罗马世界就陷入了绝境：奴隶制在经济上已经不可能了，而自由民的劳动却在道德上受鄙视。前者是已经不能再作为社会生产的基本形式，后者是还不能成为这种形式。只有一次彻底革命才能摆脱这种绝境。","language":"中文","translation":false},{"id":"family-1-355","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":355,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"各行省的情况，也不见得好些。我们所有的材料，以关于高卢的为最多。在这里，与隶农并存的，还有自由的小农。他们为了不受官吏、法官和高利贷者的侵害，往往托庇于有权势者以求保护；不仅农民个人这样做，而且整个公社也这样做，以致4世纪的皇帝们屡次发布命令，禁止这种行为。但是寻求保护的人这样做有什么好处呢？保护者向他们提出了这样的条件：他们把自己那块土地的所有权转让给他，而他则保证他们终身使用这块土地，——这也就是神圣的教会所心领神会的，并且在9和10世纪竭力仿效以扩张神的国家即教会地产的诡计。诚然，在那个时候，即公元475年左右，马赛的主教萨尔维安还对这种掠夺表示愤慨，并且说，罗马官吏和大地主的压迫已经如此严重，以致许多“罗马人”纷纷逃往野蛮人所占领的地方，而移居那里的罗马公民最怕的是重新落入罗马统治之下。[105]关于那时父母常常因贫穷而把自己的子女卖为奴隶的事情，为禁止这种行为而颁布的法律就证明了这一点。","language":"中文","translation":false},{"id":"family-1-356","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":356,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"德意志野蛮人把罗马人从他们自己的国家里解放了出来，为此他们便强夺了罗马人全部土地的2/3在自己人当中分配。这一分配是按照氏族制度进行的；由于征服者的人数相对来说较少，仍有广大的土地未被分配，一部分归全体人民占有，一部分归各个部落和氏族占有。在每个氏族内，则用抽签方法把耕地和草地平均分给各户；后来是否进行过重新分配，我们不得而知，但无论如何，这样的做法在罗马各行省不久就取消了，单块的份地变成了可以转让的私有财产即自主地。森林和牧场始终没有分配而留作共同使用；这种使用，以及被分配下去的耕地的耕种方式，都是按照古代的习俗和全体的决定来调整的。氏族在自己的村落里定居越久，德意志人和罗马人越是逐渐融合，亲属性质的联系就越是让位于地区性质的联系；氏族消失在马尔克公社中了，但在马尔克公社内，它起源于各成员的亲属关系的痕迹往往还是很显著的。可见，至少在保存着马尔克公社的各个国家——在法国北部，在英国，在德国，在斯堪的纳维亚，——氏族制度不知不觉地变成了地区制度，因而才能够和国家相适应。但是，它仍保存了它那种自然形成而为整个氏族制度所特有的民主性质；甚至在它后来被迫蜕变的时候，也还留下了氏族制度的片断，从而在被压迫者手中留下了一种武器，直到现代还有其生命力。","language":"中文","translation":false},{"id":"family-1-357","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":357,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，如果说氏族中的血缘纽带很快就丧失了自己的意义，那么，这是血缘纽带的各种机关在部落和整个民族内由于征服而同样发生蜕变的结果。我们知道，对被征服者的统治，是和氏族制度不相容的。在这里我们可以很普遍地看到这一点。各德意志民族做了罗马各行省的主人，就必须把所征服的地区组织管理起来。但是，它们既不能把大量的罗马人吸收到氏族团体里来，又不能通过氏族团体去统治他们。必须设置一种代替物来代替罗马国家，以领导起初大都还继续存在的罗马地方行政机关，而这种代替物只能是另一种国家。因此，氏族制度的机关必须转化为国家机关，并且为时势所迫，这种转化还非常迅速。但是，征服者民族的最近的代表人是军事首长。被征服地区对内对外的安全，要求增大他的权力。于是军事首长的权力转变为王权的时机来到了，这一转变发生了。","language":"中文","translation":false},{"id":"family-1-358","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":358,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"就拿法兰克王国来说，在这里，胜利了的撒利法兰克人不仅完全占有了广大的罗马国有领地，而且完全占有了一切不曾分配给大大小小的区域公社和马尔克公社的大片土地，特别是全部较大的林区。从一个普通的最高军事首长变成了真正君主的法兰克国王做的第一件事，便是把这种人民的财产变为王室的财产，从人民方面把它盗窃过来而赠送或赏赐给他的扈从队。这种起初由他的私人军事扈从以及其余的下级军事首长组成的扈从队，不久就膨胀了起来，这不仅由于补入了罗马人即罗马化的高卢人，这些人因为能书写、有教养，懂得罗曼口语、拉丁文言和当地法律很快就变成他所离不开的人，而且还由于也补入了奴隶、农奴和被释奴隶，这些人构成了他的宫廷，他就从他们中间挑选自己的宠儿。所有这些人都得到了大片的人民的田地，这些田地起初多半是赠送给他们，后来就以采邑108的形式赏赐给他们——起初多半是享用到国王去世时为止。这样，就靠牺牲人民而造成了新贵族的基础。","language":"中文","translation":false},{"id":"family-1-359","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":359,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不仅如此，由于王国幅员广阔，就不能利用旧的氏族制度的手段来管理了；氏族酋长议事会即使没有老早消失，也已经不能召集了，它很快就被国王的固定亲信所代替；旧的人民大会还继续存在着做做样子，但是也越来越变成纯粹是下级军事首长和新贵的会议。占有土地的自由农民，即法兰克人的主体，正如以前共和制末期的罗马农民一样，也由于连年内战和征服战争、特别是查理大帝时期的征服战争而弄得疲惫不堪和贫困衰败了。这种起初构成全部军队，而在征服法兰西地区以后，又构成该地的核心的农民，到9世纪之初，已穷困到五个人之中难得抽出一个人出去作战了。以前由国王直接召募的自由农民的卫国军，现在已经由新贵的仆从所组成的军队代替。在这些仆从中，还有一些依附农民，他们是那些先前只知有国王而不知有主人，而更早一点根本不知有任何主人，甚至也不知有国王的农民的后裔。在查理大帝的后代统治时，由于国内战争、王权的削弱和相应的贵人跋扈(在这种贵人之中还加上了查理大帝所任命的那些力图把自己的职位变成世袭的郡守109)，最后，还由于诺曼人的侵犯，法兰克的农民等级就完全破产了。查理大帝死后50年，法兰克王国便毫无反抗地匍匐在诺曼人的脚下，正和400年前罗马帝国匍匐在法兰克人的脚下一样。","language":"中文","translation":false},{"id":"family-1-360","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":360,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不仅对外软弱无能，而且内部的社会秩序(不如说是社会无秩序)，差不多也是一样。自由的法兰克农民陷入了与他们的前辈即罗马的隶农一样的处境。他们被战争和掠夺弄得破产，不得不去乞求新贵或教会的保护，因为国王的权力太弱了，已经不能保护他们；不过这种保护使他们不得不付出很高的代价。像以前高卢农民那样，他们必须将自己那块土地的所有权交给保护人，再以各种不同的和变化的形式——不过总不外是力役和代役租——从他那里把这块土地作为租地而租回来。一经陷入这种依附形式，他们也就逐渐地丧失了自己的人身自由；过不了几代，他们大多数已经都是农奴了。自由的农民等级灭亡得多么迅速，这从伊尔米农所编的圣日尔曼－德－普雷修道院(当时在巴黎附近，现在巴黎市内)的地产登记册110中可以得到证明。这个修道院的地产散布四周，面积极为广大，还在查理大帝在世的时候，就住有2788户人家，差不多全是取德意志名字的法兰克人。其中2080户是隶农，35户是黎特，220户是奴隶，只有8户是自由的佃农!保护人让农民把自己那块土地交归他所有，然后仅仅是再将这块土地交回农民终身使用，这个曾被萨尔维安宣布为背神行为的习俗，如今到处被教会施加在农民身上了。现在日益盛行的徭役，其原型既是罗马的安加利111，即为国家所服的强制劳役，又是德意志马尔克公社成员为修桥、筑路，以及其他共同目的而出的工役。这样一来，居民的主体在过了400年以后好像完全又回到起初的状况去了。","language":"中文","translation":false},{"id":"family-1-361","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":361,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"然而，这不过证明两点：第一，没落时期罗马帝国的社会分化和财产分配，是跟当时的农业和工业的生产水平完全相适应的，因而是不可避免的；第二，这一生产水平在以后400年间，并没有根本性的下降和上升，因此，才以同样的必然性重新产生了同样的财产分配和同样的居民阶级。在罗马帝国的最后数百年间，城市丧失了它从前对乡村的统治，而在德意志人统治的最初数百年间，也没有把它恢复起来。这是由农业与工业的发展程度很低决定的。这样一个总的状况，必然产生居于统治地位的大地主和依附的小农。要把使用奴隶劳动的罗马大庄园经济或使用徭役的新的大规模经营嫁接在这种社会上面是多么不可能，这可以从查理大帝用著名皇室田庄所作的几乎没有留下痕迹的庞大实验中得到证明。只有修道院才又继续了这种实验，也只是对修道院说来才获益甚丰；但是修道院是以独身生活为基础的非正常的社会团体；它们可能会有例外的成绩，然而正因为如此，才不能不永远是一个例外。","language":"中文","translation":false},{"id":"family-1-362","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":362,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但在这400年间，毕竟是继续前进了。即使我们在这一时期末所看到的主要阶级差不多跟初期一样，但构成这些阶级的人却已经不同了。古典古代的奴隶制已经消失；破产的、贫穷的、轻视劳动为奴隶贱事的自由民也已经消失。介于罗马隶农和新的农奴之间的是自由的法兰克农民。奄奄一息的罗马世界的“无益的回忆与徒然的斗争”已经死亡并且被埋葬了。9世纪的社会阶级，不是在垂死文明的沉沦中，而是在新文明诞生的阵痛中形成的。新的世代，无论是主人还是仆从，跟他们的罗马前辈比较起来，已经是成年人的世代了。有权势的地主和服劳役的农民之间的关系，对罗马前辈来说曾经是古典古代世界毫无出路的没落形式，现在对新的世代来说则是新发展的起点。其次，不论这400年看起来多么没有成果，可是却留下了一个重大的成果：这就是一些现代的民族［mod－，亦即西欧人类为了未来的历史而实行的分化和改组。德意志人确实重新使欧洲有了生气，因此，日耳曼时期的国家解体过程才不是以诺曼－萨拉秦人的征服而告终，而是以采邑制度和保护关系(依附制度112)的进一步发展为封建制度而告终，[106]而人口也有了这样巨大的增长，以致能够完好无恙地经受了不到200年后的十字军远征的大流血。","language":"中文","translation":false},{"id":"family-1-363","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":363,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"然而，德意志人究竟是用了什么神秘的魔法，给垂死的欧洲注入了新的生命力呢？是不是像我们的沙文主义的历史编纂学所虚构的那样，德意志种族天生有一种特别的魔力呢？决不是。德意志人，尤其在当时，是一个天资高的雅利安族系，并且正处在生机勃勃的发展中。但是使欧洲返老还童的，并不是他们的特殊的民族特点，而只是他们的野蛮状态，他们的氏族制度而已。","language":"中文","translation":false},{"id":"family-1-364","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":364,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"他们的个人才能和勇敢，他们的自由意识，以及把一切公共的事情看作是自己的事情的民主本能，总之，是罗马人所丧失的一切品质，而仅仅这些品质就能从罗马世界的污泥中造成新的国家，培养出新的民族——所有这一切，如果不是高级阶段野蛮人的特征——他们的氏族制度的果实，又是什么呢？","language":"中文","translation":false},{"id":"family-1-365","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":365,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如果说，德意志人改革了专偶制的古代形式，缓和了男子在家庭中的统治，给了妇女以比古典世界任何时期都更高的地位，那么，使他们能够做到这一点的，如果不是他们的野蛮状态、他们的氏族习惯，如果不是他们仍有母权制时代的遗风，又是什么呢？","language":"中文","translation":false},{"id":"family-1-366","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":366,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"如果说，他们至少在三个最重要的国度——德国、法国北部和英国——以马尔克公社的形式保存下来一部分真正的氏族制度，并把它带到封建国家里去，从而使被压迫阶级即农民甚至在中世纪农奴制的最严酷条件下，也能有地方性的团结即一个抵抗的手段，而这一手段无论在古典古代的奴隶那里或者在近代的无产阶级那里都没有这样现成，那么，造成这种情况的，如果不是他们的野蛮状态、如果不是他们的纯粹野蛮人的按血族定居的方式，又是什么呢?","language":"中文","translation":false},{"id":"family-1-367","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":367,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"最后，如果说，他们能把那种在他们的故乡已经实行的比较温和的隶属形式——在罗马帝国，奴隶制也日益转化为这种形式——发展起来，并使之成为唯一的形式，而这种隶属形式，正如傅立叶最早强调指出的11：，给被奴役者提供了一个使自己作为阶级而逐渐获得解放的手段(fournit aux cultivateurs des moyens d’affranchissement collectif et Progressif[107])，因此之故，这种形式大大胜过奴隶制——在奴隶制下，只能有单个人不经过过渡状态而立即获得释放(古代是没有用胜利的起义来消灭奴隶制的事情的)，而中世纪的农奴实际上却作为阶级而逐渐实现了自己的解放，——如果是这样的话，那么，这一切如果不是归功于他们的野蛮状态(由于这种野蛮状态，他们还没有达到形成了的奴隶制：既没有达到古典古代的劳动奴隶制，也没有达到东方的家庭奴隶制)，又归功于什么呢?","language":"中文","translation":false},{"id":"family-1-368","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":368,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"凡德意志人给罗马世界注入的一切有生命力的和带来生命的东西，都是野蛮时代的东西。的确，只有野蛮人才能使一个在垂死的文明中挣扎的世界年轻起来。而德意志人在民族大迁徒之前已经达到并努力开拓的野蛮时代高级阶段，对于这一过程恰好最为适宜。这就说明了一切。","language":"中文","translation":false},{"id":"family-1-369","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":369,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"我们已经根据希腊人、罗马人和德意志人这三大实例，探讨了氏族制度的解体。最后，我们来研究一下那些在野蛮时代高级阶段已经破坏了氏族社会组织，而随着文明时代的到来又把它完全消灭的一般经济条件。在这里，马克思的《资本论》对我们来说是和摩尔根的著作同样必要的。","language":"中文","translation":false},{"id":"family-1-370","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":370,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"氏族在蒙昧时代中级阶段发生，在高级阶段继续发展起来，就我们现有的资料来判断，到了野蛮时代低级阶段，它便达到了全盛时代。所以现在我们就从这一阶段开始。","language":"中文","translation":false},{"id":"family-1-371","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":371,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这一阶段应当以美洲红种人为例；在这一阶段上，我们发现氏族制度已经完全形成。一个部落分为几个氏族，通常是分为两个[108]；随着人口的增加，这些最初的氏族每一个又分裂为几个女儿氏族，对这些女儿氏族来说，母亲氏族便是胞族；部落本身分裂成几个部落，在其中的每一个部落中，我们多半又可以遇到那些老氏族；部落联盟至少是在个别情况下把亲属部落联合在一起。这种简单的组织，是同它所由产生的社会状态完全适应的。它无非是这种社会状态所特有的、自然长成的结构；它能够处理在这样组织起来的社会内部一切可能发生的冲突。对外的冲突，则由战争来解决；这种战争可能以部落的消灭而告终，但从没能以它的被奴役而告终。氏族制度的伟大，但同时也是它的局限，就在于这里没有统治和奴役存在的余地。在氏族制度内部，还没有权利和义务的分别；参与公共事务，实行血族复仇或为此接受赎罪，究竟是权利还是义务这种问题，对印第安人来说是不存在的；在印第安人看来，这种问题正如吃饭、睡觉、打猎究竟是权利还是义务的问题一样荒谬。同样，部落和氏族分为不同的阶级也是不可能的。这就使我们不能不对这种状态的经济基础加以研究了。","language":"中文","translation":false},{"id":"family-1-372","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":372,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"人口是极其稀少的；只有在部落的居住地才比较稠密，在这种居住地的周围，首先是一片广大的狩猎地带，其次是把这个部落同其他部落隔离开来的中立的防护森林。分工是纯粹自然产生的；它只存在于两性之间。男子作战、打猎、捕鱼，获取食物的原料，并制作为此所必需的工具。妇女管家，制备衣食——做饭、纺织、缝纫。男女分别是自己活动领域的主人：男子是森林中的主人，妇女是家里的主人。男女分别是自己所制造的和所使用的工具的所有者：男子是武器、渔猎用具的所有者，妇女是家内用具的所有者。家户经济是共产制的，包括几个、往往是许多个家庭。[109]凡是共同制作和使用的东西，都是共同财产：如房屋、园圃、小船。所以，在这里，而且也只有在这里，才真正存在着文明社会的法学家和经济学家所捏造的“自己劳动所得的财产”——现代资本主义所有制还依恃着的最后一个虚伪的法律借口。","language":"中文","translation":false},{"id":"family-1-373","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":373,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，人并不是到处都停留在这个阶段。在亚洲，他们发现了可以驯服和在驯服后可以繁殖的动物。野生的雌水牛，需要去猎取；但已经驯服的雌水牛，每年可生一头小牛，此外还可以挤奶。有些最先进的部落——雅利安人、闪米特人，也许还有图兰人，——其主要的劳动部门起初就是驯养牲畜，只是到后来才又有繁殖和看管牲畜。游牧部落从其余的野蛮人群中分离出来——这是第一次社会大分工。游牧部落生产的生活资料，不仅比其余的野蛮人多，而且也不相同。同其余的野蛮人比较，他们不仅有数量多得多的乳、乳制品和肉类，而且有兽皮、绵羊毛、山羊毛和随着原料增多而日益增加的纺织物。这就第一次使经常的交换成为可能。在更早的阶段上，只能有偶然的交换；制造武器和工具的特殊技能，可能导致暂时的分工。例如，在许多地方，都发现石器时代晚期的石器作坊的无可置疑的遗迹；在这种作坊中发展了自己技能的匠人，大概是靠全体和为全体工作，正如印度的氏族公社的终身手艺人至今仍然如此一样。在这个阶段上，除了部落内部发生的交换以外，决不可能有其他的交换，而且，即使是部落内部的交换，也仍然是一种例外的事件。相反地，自从游牧部落分离出来以后，我们就看到，各不同部落的成员之间进行交换以及它作为一种经常制度来发展和巩固的一切条件都具备了。起初是部落和部落之间通过各自的氏族酋长来进行交换；但是当畜群开始变为特殊财产[110]的时候，个人交换便越来越占优势，终于成为交换的唯一形式。不过，游牧部落用来同他们的邻人交换的主要物品是牲畜；牲畜变成了一切商品都用它来估价并且到处乐于同它交换的商品——一句话，牲畜获得了货币的职能，在这个阶段上就已经起货币作用了。在商品交换刚刚产生的时候，对货币商品的需求，就以这样的必然性和速度发展起来了。","language":"中文","translation":false},{"id":"family-1-374","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":374,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"园圃种植业大概是亚洲的低级阶段野蛮人所不知道的，但它在那里作为田野耕作的先驱而出现不迟于中级阶段。在图兰平原的气候条件下，在漫长而严寒的冬季，没有饲料储备，游牧生活是不可能的；因此，牧草栽培和谷物种植，在这里就成了必要条件。黑海以北的草原，也是如此。但谷物一旦作为家畜饲料而种植，它很快也成了人类的食物。耕地仍然是部落的财产，最初是交给氏族使用，后来由氏族交给家庭公社使用，最后[111]交给个人使用；他们对耕地或许有一定的占有权，但是没有更多的权利。","language":"中文","translation":false},{"id":"family-1-375","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":375,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"在这一阶段工业的成就中，特别重要的有两件。第一是织布机；第二是矿石冶炼和金属加工。铜、锡以及二者的合金——青铜是顶顶重要的金属；青铜可以制造有用的工具和武器，但是并不能排挤掉石器；这一点只有铁才能做到，而当时还不知道冶铁。金和银已开始用于首饰和装饰，其价值肯定已比铜和青铜高。","language":"中文","translation":false},{"id":"family-1-376","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":376,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"一切部门——畜牧业、农业、家庭手工业——中生产的增加，使人的劳动力能够生产出超过维持劳动力所必需的产品。同时，这也增加了氏族、家庭公社或个体家庭的每个成员所担负的每日的劳动量。吸收新的劳动力成为人们向往的事情了。战争提供了新的劳动力：俘虏变成了奴隶。第一次社会大分工，在使劳动生产率提高，从而使财富增加并且使生产领域扩大的同时，在既定的总的历史条件下，必然地带来了奴隶制。从第一次社会大分工中，也就产生了第一次社会大分裂，分裂为两个阶级：主人和奴隶、剥削者和被剥削者。","language":"中文","translation":false},{"id":"family-1-377","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":377,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"至于畜群怎样并且在什么时候从部落或氏族的共同占有变为各个家庭首长的财产，我们至今还不得而知。不过，基本上，这一过渡一定是在这个阶段上发生的。随着畜群和其他新的财富的出现，便发生了对家庭的革命。谋取生活资料总是男子的事情，谋取生活资料的工具是由男子制造的，并且是他们的财产。畜群是新的谋取生活资料的工具，最初对它们的驯养和以后对它们的照管都是男子的事情。因此，牲畜是属于他们的；用牲畜交换来的商品和奴隶，也是属于他们的。这时谋生所得的全部剩余都归了男子；妇女参加它的享用，但在财产中没有她们的份儿。“粗野的”战士和猎人，以在家中次于妇女而占第二位为满足，但“比较温和的”牧人，却依恃自己的财富挤上了首位，把妇女挤到了第二位。而妇女是不能抱怨的。家庭内的分工决定了男女之间的财产分配；这一分工仍然和以前一样，可是它现在却把迄今所存在的家庭关系完全颠倒了过来，这纯粹是因为家庭以外的分工已经不同了。从前保证妇女在家中占统治地位的同一原因——妇女只限于从事家务劳动，——现在却保证男子在家中占统治地位：妇女的家务劳动现在同男子谋取生活资料的劳动比较起来已经相形见绌；男子的劳动就是一切，妇女的劳动是无足轻重的附属品。在这里就已经表明，只要妇女仍然被排除于社会的生产劳动之外而只限于从事家庭的私人劳动，那么妇女的解放，妇女同男子的平等，现在和将来都是不可能的。妇女的解放，只有在妇女可以大量地、社会规模地参加生产，而家务劳动只占她们极少的工夫的时候，才有可能。而这只有依靠现代大工业才能办到，现代大工业不仅容许大量的妇女劳动，而且是真正要求这样的劳动，并且它还力求把私人的家务劳动逐渐融化在公共的事业中。","language":"中文","translation":false},{"id":"family-1-378","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":378,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"随着男子在家中的实际统治的确立，实行男子独裁的最后障碍便崩毁了。这种独裁，由于母权制的倾覆、父权制的实行、对偶婚制向专偶制的逐步过渡而被确认，并且永久化了。但是这样一来，在古代的氏族制度中就出现了一个裂口：个体家庭已经成为一种力量，并且以威胁的姿态起来与氏族对抗了。","language":"中文","translation":false},{"id":"family-1-379","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":379,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"下一步把我们引向野蛮时代高级阶段，一切文化民族都在这个时期经历了自己的英雄时代：铁剑时代，但同时也是铁犁和铁斧的时代。铁已在为人类服务，它是在历史上起过革命作用的各种原料中最后的和最重要的一种原料。所谓最后的，是指直到马铃薯的出现为止。铁使更大面积的田野耕作，广阔的森林地区的开垦，成为可能；它给手工业工人提供了一种其坚硬和锐利非石头或当时所知道的其他金属所能抵挡的工具。所有这些，都是逐渐实现的；最初的铁往往比青铜还软。所以，石制武器只是慢慢地消失的；不仅在《希尔德布兰德之歌》101中，而且在1066年的黑斯廷斯会战中114都还使用石斧。但是，进步现在是不可遏止地、更少间断地、更加迅速地进行着。用石墙、城楼、雉堞围绕着石造或砖造房屋的城市，已经成为部落或部落联盟的中心；这是建筑艺术上的巨大进步，同时也是危险增加和防卫需要增加的标志。财富在迅速增加，但这是个人的财富；织布业、金属加工业以及其他一切彼此日益分离的手工业，显示出生产的日益多样化和生产技术的日益改进；农业现在除了提供谷物、豆科植物和水果以外，也提供植物油和葡萄酒，这些东西人们已经学会了制造。如此多样的活动，已经不能由同一个人来进行了；于是发生了第二次大分工：手工业和农业分离了。生产的不断增长以及随之而来的劳动生产率的不断增长，提高了人的劳动力的价值；在前一阶段上刚刚产生并且是零散现象的奴隶制，现在成为社会制度的一个根本的组成部分；奴隶们不再是简单的助手了；他们被成批地赶到田野和工场去劳动。随着生产分为农业和手工业这两大主要部门，便出现了直接以交换为目的的生产，即商品生产；随之而来的是贸易，不仅有部落内部和部落边境的贸易，而且海外贸易也有了。然而，所有这一切都还很不发达；贵金属开始成为占优势的和普遍性的货币商品，但是还不是铸造的货币，只是不作加工按重量交换罢了。","language":"中文","translation":false},{"id":"family-1-380","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":380,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"除了自由民和奴隶的差别以外，又出现了富人和穷人的差别，——随着新的分工，社会又有了新的阶级划分。各个家庭首长之间的财产差别，炸毁了各地迄今一直保存着的旧的共产制家庭公社；同时也炸毁了为这种公社而实行的土地的共同耕作。耕地起初是暂时地、后来便永久地分配给各个家庭使用，它向完全的私有财产的过渡，是逐渐进行的，是与对偶婚制向专偶制的过渡平行地发生的。个体家庭开始成为社会的经济单位了。","language":"中文","translation":false},{"id":"family-1-381","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":381,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"住得日益稠密的居民，对内和对外都不得不更紧密地团结起来。亲属部落的联盟，到处都成为必要的了；不久，各亲属部落的融合，从而分开的各个部落领土融合为一个民族［Volk］的整个领土，也成为必要的了。民族的军事首长——勒克斯，巴赛勒斯，狄乌丹斯，——成了不可缺少的常设的公职人员。还不存在人民大会的地方，也出现了人民大会。军事首长、议事会和人民大会构成了继续发展为军事民主制的氏族社会的各机关。其所以称为“军事”，是因为战争以及进行战争的组织现在已经成为民族生活的正常功能。邻人的财富刺激了各民族的贪欲，在这些民族那里，获取财富已成为最重要的生活目的之一。他们是野蛮人：掠夺在他们看来比劳动获得更容易甚至更光荣。以前打仗只是为了对侵犯进行报复，或者是为了扩大已经感到不够的领土；现在打仗，则纯粹是为了掠夺，战争成了经常性的行当。在新的设防城市的周围屹立着高峻的墙壁并非无故：它们的深壕宽堑成了氏族制度的墓穴，而它们的城楼已经高耸入文明时代了。内部也发生了同样的情形。掠夺战争加强了最高军事首长以及下级军事首长的权力；习惯地由同一家庭选出他们的后继者的办法，特别是从父权制实行以来，就逐渐转变为世袭制，他们最初是耐心等待，后来是要求，最后便僭取这种世袭制了；世袭王权和世袭贵族的基础奠定下来了。于是，氏族制度的机关就逐渐挣脱了自己在民族中，在氏族、胞族和部落中的根子，而整个氏族制度就转化为自己的对立物：它从一个自由处理自己事务的部落组织转变为掠夺和压迫邻近部落的组织，而它的各机关也相应地从人民意志的工具转变为独立的、压迫和统治自己人民的机关了。但是，如果不是对财富的贪欲把氏族成员分裂成富人和穷人，如果不是“同一氏族内部的财产差别把利益的一致变为氏族成员之间的对抗”(马克思语)115，如果不是奴隶制的盛行已经开始使人认为用劳动获取生活资料是只有奴隶才配做的、比掠夺更可耻的活动，那么这种情况是决不会发生的。","language":"中文","translation":false},{"id":"family-1-382","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":382,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"这样，我们就走到文明时代的门槛了。它是由分工方面的一个新的进步开始的。在野蛮时代低级阶段，人们只是直接为了自身的消费而生产；间或发生的交换行为也是个别的，只限于偶然的剩余物。在野蛮时代中级阶段，我们看到游牧民族已经有牲畜作为财产，这种财产，到了畜群具有相当规模的时候，就可以经常提供超出自身消费的若干余剩；同时，我们也看到了游牧民族和没有畜群的落后部落之间的分工，从而看到了两个并存的不同的生产阶段，也就是看到了进行经常交换的条件。在野蛮时代高级阶段，进一步又发生了农业和手工业之间的分工，于是劳动产品中日益增加的一部分是直接为了交换而生产的，这就把单个生产者之间的交换提升为社会的生活必需。文明时代巩固并加强了所有这些已经发生的各次分工，特别是通过加剧城市和乡村的对立(或者是像古代那样，城市在经济上统治乡村，或者是像中世纪那样，乡村在经济上统治城市)而使之巩固和加强，此外它又加上了一个第三次的、它所特有的、有决定意义的重要分工：它创造了一个不再从事生产而只从事产品交换的阶级——商人。在此以前，阶级的形成的一切萌芽，还都只是与生产相联系的；它们把从事生产的人分成了领导者和执行者，或者分成了规模较大和较小的生产者。这里首次出现一个阶级，它根本不参与生产，但完全夺取了生产的领导权，并在经济上使生产者服从自己；它成了每两个生产者之间的不可缺少的中间人，并对他们双方都进行剥削。在可以使生产者免除交换的辛劳和风险，可以使他们的产品的销路扩展到遥远的市场，而自己因此就成为一个居民的最有用的阶级的借口下，一个寄生阶级，真正的社会寄生虫阶级形成了，它从国内和国外的生产上榨取油水，作为对自己的非常有限的实际贡献的报酬，它很快就获得了大量的财富和相应的社会影响；正因为如此，它在文明时期便取得了越来越荣誉的地位和对生产的越来越大的统治权，直到最后它自己也生产出自己的产品——周期性的商业危机为止。","language":"中文","translation":false},{"id":"family-1-383","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":383,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"不过，在我们正在考察的这个发展阶段上，年轻的商人阶级还丝毫没有预感到它未来的伟大事业。但是这个阶级正在形成并且使自己成为必不可少的，而这就够了。随着它，出现了金属货币即铸币，随着金属货币就出现了非生产者统治生产者及其生产的新手段。商品的商品被发现了，这种商品以隐蔽的方式包含着其他一切商品，它是可以任意变为任何值得向往和被向往的东西的魔法手段。谁有了它，谁就统治了生产世界。但是谁首先有了它呢？商人。对货币的崇拜掌握在他手中是万无一失的。他尽心竭力地叫人们知道，一切商品，从而一切商品生产者，都应该毕恭毕敬地匍匐在货币面前。他在实践上证明，在这种财富本身的化身面前，其他一切财富形式都不过是一个影子而已。以后货币的权力再也没有像在它的这个青年时代那样，以如此原始的粗野和横暴的形式表现出来。在使用货币购买商品之后，出现了货币借贷，随着货币借贷出现了利息和高利贷。后世的立法，没有一个像古雅典和古罗马的立法那样残酷无情地、无可挽救地把债务人投在高利贷债权人的脚下，——这两种立法都是作为习惯法而自发地产生的，都只有经济上的强制。","language":"中文","translation":false},{"id":"family-1-384","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":384,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"除了表现为商品和奴隶的财富以外，除了货币财富以外，这时还出现了表现为地产的财富。各个人对于原来由氏族或部落给予他们的小块土地的占有权，现在变得如此牢固，以致这些小块土地作为世袭财产而属于他们了。他们最近首先力求实现的，正是要摆脱氏族公社索取这些小块土地的权利，这种权利对他们已成为桎梏了。这种桎梏他们是摆脱了，但是不久他们也失去了新的土地所有权。完全的、自由的土地所有权，不仅意味着不折不扣和毫无限制地占有土地的可能性，而且也意味着把它出让的可能性。只要土地是氏族的财产，这种可能性就不存在。但是，当新的土地占有者彻底摆脱了氏族和部落的最高所有权这一桎梏的时候，他也就挣断了迄今把他同土地密不可分地连在一起的纽带。这意味着什么，和土地私有权同时被发明出来的货币，向他作了说明。土地现在可以成为出卖和抵押的商品了。土地所有权刚一确立，抵押就被发明出来了(见关于雅典的一章)。像淫游和卖淫紧紧跟着专偶制而来一样，如今抵押也紧紧跟着土地所有权而来了。你们曾希望有完全的、自由的、可以出售的土地所有权，那么好了，现在你们得到它了——这就是你所希望的，乔治·唐丹![112]这样，随着贸易的扩大，随着货币和货币高利贷、土地所有权和抵押的产生，财富便迅速地积聚和集中到一个人数很少的阶级手中，与此同时，大众日益贫困化，贫民的人数也日益增长。新的财富贵族，只要从一开始就恰巧不是旧的部落显贵，便把部落显贵完全排挤到后面去了(在雅典，在罗马，以及在德意志人中间)。随着这种按照财富把自由民分成各个阶级的划分，奴隶的人数特别是在希腊便大大增加起来[113]，奴隶的强制性劳动构成了整个社会的上层建筑所赖以建立的基础。","language":"中文","translation":false},{"id":"family-1-385","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":385,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"现在我们来看看，在这种社会变革中，氏族制度怎么样了。面对着没有它的参与而兴起的新因素，它显得软弱无力。氏族制度的前提，是一个氏族或部落的成员共同生活在纯粹由他们居住的同一地区中。这种情况早已不存在了。氏族和部落到处都杂居在一起，到处都有奴隶、被保护民和外地人在公民中间居住着。直到野蛮时代中级阶段末期才达到的定居状态，由于居住地受商业活动、职业变换和土地所有权转让的影响而变动不定，所以时常遭到破坏。氏族团体的成员再也不能集会来处理自己的共同事务了；只有不重要的事情，例如宗教节日，还勉强能够安排。除了氏族团体有责任并且能够予以保证的需要和利益以外，由于谋生条件的变革及其所引起的社会结构的变化，又产生了新的需要和利益，这些新的需要和利益不仅同旧的氏族制度格格不入，而且还千方百计在破坏它。由于分工而产生的手工业集团的利益，城市的对立于乡村的特殊需要，都要求有新的机构；但是，每一个这种集团都是由属于极不相同的氏族、胞族和部落的人们组成的，甚至还包括外地人在内；因此，这种机构必须在氏族制度以外，与它并列地形成，从而又是与它对立的。——同时，在每个氏族团体中，也表现出利益的冲突，这种冲突由于富人和穷人、高利贷者和债务人结合于同一氏族和同一部落中而达到最尖锐的地步。——此外，又加上了大批新的、外氏族公社的居民，他们在国内已经能够成为一种力量，像罗马的情况那样，同时他们人数太多，不可能被逐渐接纳到血缘亲属的血族和部落中来。氏族公社作为一种封闭的享有特权的团体对抗着这一批居民；原始的自然形成的民主制变成了可憎的贵族制。——最后，氏族制度是从那种没有任何内部对立的社会中生长出来的，而且只适合于这种社会。除了舆论以外，它没有任何强制手段。但是现在产生了这样一个社会，它由于自己的全部经济生活条件而必然分裂为自由民和奴隶，进行剥削的富人和被剥削的穷人，而这个社会不仅再也不能调和这种对立，反而必然使这些对立日益尖锐化。一个这样的社会，只能或者存在于这些阶级相互间连续不断的公开斗争中，或者存在于第三种力量的统治下，这第三种力量似乎站在相互斗争着的各阶级之上，压制它们的公开的冲突，顶多容许阶级斗争在经济领域内以所谓合法形式决出结果来。氏族制度已经过时了。它被分工及其后果即社会之分裂为阶级所炸毁。它被国家代替了。","language":"中文","translation":false},{"id":"family-1-386","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":386,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"前面我们已经分别考察了国家在氏族制度的废墟上兴起的三种主要形式。雅典是最纯粹、最典型的形式：在这里，国家是直接地和主要地从氏族社会本身内部发展起来的阶级对立中产生的。在罗马，氏族社会变成了封闭的贵族制，它的四周则是人数众多的、站在这一贵族制之外的、没有权利只有义务的平民；平民的胜利炸毁了旧的血族制度，并在它的废墟上面建立了国家，而氏族贵族和平民不久便完全融化在国家中了。最后，在战胜了罗马帝国的德意志人中间，国家是直接从征服广大外国领土中产生的，氏族制度不能提供任何手段来统治这样广阔的领土。但是，由于同这种征服相联系的，既不是跟旧有居民的严重斗争，也不是更加进步的分工；由于被征服者和征服者差不多处于同一经济发展阶段，从而社会的经济基础依然如故，所以，氏族制度能够以改变了的、地区的形式，即以马尔克制度的形式，继续存在几个世纪，甚至在以后的贵族血族和城市望族的血族中，甚至在农民的血族中，例如在迪特马申[114]，还以削弱了的形式复兴了一个时期。","language":"中文","translation":false},{"id":"family-1-387","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":387,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"可见，国家决不是从外部强加于社会的一种力量。国家也不像黑格尔所断言的是“伦理观念的现实”，“理性的形象和现实”。117确切说，国家是社会在一定发展阶段上的产物；国家是承认：这个社会陷入了不可解决的自我矛盾，分裂为不可调和的对立面而又无力摆脱这些对立面。而为了使这些对立面，这些经济利益互相冲突的阶级，不致在无谓的斗争中把自己和社会消灭，就需要有一种表面上凌驾于社会之上的力量，这种力量应当缓和冲突，把冲突保持在“秩序”的范围以内；这种从社会中产生但又自居于社会之上并且日益同社会相异化的力量，就是国家。","language":"中文","translation":false},{"id":"family-1-388","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":388,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"国家和旧的氏族组织不同的地方，第一点就是它按地区来划分它的国民。正如我们所看到的，由血缘关系形成和联结起来的旧的氏族公社已经很不够了，这多半是因为它们是以氏族成员被束缚在一定地区为前提的，而这种束缚早已不复存在。地区依然，但人们已经是流动的了。因此，按地区来划分就被作为出发点，并允许公民在他们居住的地方实现他们的公共权利和义务，不管他们属于哪一氏族或哪一部落。这种按照居住地组织国民的办法是一切国家共同的。因此，我们才觉得这种办法很自然；但是我们已经看到，当它在雅典和罗马能够代替按血族来组织的旧办法以前，曾经需要进行多么顽强而长久的斗争。","language":"中文","translation":false},{"id":"family-1-389","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":389,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"第二个不同点，是公共权力的设立，这种公共权力已经不再直接就是自己组织为武装力量的居民了。这个特殊的公共权力之所以需要，是因为自从社会分裂为阶级以后，居民的自动的武装组织已经成为不可能了。奴隶也包括在居民以内；9万雅典公民，对于365000奴隶来说，只是一个特权阶级。雅典民主制的国民军，是一种贵族的、用来对付奴隶的公共权力，它控制奴隶使之服从；但是如前所述，为了也控制公民使之服从，宪兵队也成为必要了。这种公共权力在每一个国家里都存在。构成这种权力的，不仅有武装的人，而且还有物质的附属物，如监狱和各种强制设施，这些东西都是以前的氏族社会所没有的。在阶级对立还没有发展起来的社会和偏远的地区，这种公共权力可能极其微小，几乎是若有若无的，像有时在美利坚合众国的某些地方所看到的那样。但是，随着国内阶级对立的尖锐化，随着彼此相邻的各国的扩大和它们人口的增加，公共权力就日益加强。就拿我们今天的欧洲来看吧，在这里，阶级斗争和争相霸占已经把公共权力提升到大有吞食整个社会甚至吞食国家之势的高度。","language":"中文","translation":false},{"id":"family-1-390","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":390,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"为了维持这种公共权力，就需要公民缴纳费用——捐税。捐税是以前的氏族社会完全没有的。但是现在我们却十分熟悉它了。随着文明时代的向前进展，甚至捐税也不够了；国家就发行期票，借债，即发行公债。关于这点，老欧洲也已经屡见不鲜了。","language":"中文","translation":false},{"id":"family-1-391","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":391,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"官吏既然掌握着公共权力和征税权，他们就作为社会机关而凌驾于社会之上。从前人们对于氏族制度的机关的那种自由的、自愿的尊敬，即使他们能够获得，也不能使他们满足了；他们作为同社会相异化的力量的代表，必须用特别的法律来取得尊敬，凭借这种法律，他们享有了特殊神圣和不可侵犯的地位。文明国家的一个最微不足道的警察，都拥有比氏族社会的全部机构加在一起还要大的“权威”；但是文明时代最有势力的王公和最伟大的国家要人或统帅，也可能要羡慕最平凡的氏族酋长所享有的，不是用强迫手段获得的，无可争辩的尊敬。后者是站在社会之中，而前者却不得不企图成为一种处于社会之外和社会之上的东西。","language":"中文","translation":false},{"id":"family-1-392","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":392,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由于国家是从控制阶级对立的需要中产生的，由于它同时又是在这些阶级的冲突中产生的，所以，它照例是最强大的、在经济上占统治地位的阶级的国家，这个阶级借助于国家而在政治上也成为占统治地位的阶级，因而获得了镇压和剥削被压迫阶级的新手段。因此，古希腊罗马时代的国家首先是奴隶主用来镇压奴隶的国家，封建国家是贵族用来镇压农奴和依附农的机关，现代的代议制的国家是资本剥削雇佣劳动的工具。但也例外地有这样的时期，那时互相斗争的各阶级达到了这样势均力敌的地步，以致国家权力作为表面上的调停人而暂时得到了对于两个阶级的某种独立性。17世纪和18世纪的专制君主制，就是这样，它使贵族和市民等级彼此保持平衡；法兰西第一帝国特别是第二帝国的波拿巴主义，也是这样，它唆使无产阶级去反对资产阶级，又唆使资产阶级来反对无产阶级。使统治者和被统治者都显得同样滑稽可笑的这方面的最新成就，就是俾斯麦国家的新的德意志帝国：在这里，资本家和工人彼此保持平衡，并为了破落的普鲁士土容克的利益而遭受同等的欺骗。","language":"中文","translation":false},{"id":"family-1-393","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":393,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"此外，在历史上的大多数国家中，公民的权利是按照财产状况分级规定的，这直接地宣告国家是有产阶级用来防御无产阶级的组织。在按照财产状况划分阶级的雅典和罗马，就已经是这样。在中世纪的封建国家中，也是这样，在那里，政治的权力地位是按照地产来排列的。现代的代议制的国家的选举资格，也是这样。但是，对财产差别的这种政治上的承认，决不是本质的东西。相反地，它标志着国家发展的低级阶段。国家的最高形式，民主共和国，在我们现代的社会条件下正日益成为一种不可避免的必然性，它是无产阶级和资产阶级之间的最后决定性斗争只能在其中进行到底的国家形式，——这种民主共和国已经不再正式讲什么财产差别了。在这种国家中，财富是间接地但也是更可靠地运用它的权力的。其形式一方面是直接收买官吏(美国是这方面的典型例子)，另一方面是政府和交易所结成联盟，而公债越增长，股份公司越是不仅把运输业而且把生产本身集中在自己手中，越是把交易所变成自己的中心，这一联盟就越容易实现。除了美国以外，最新的法兰西共和国，也是这方面的一个显著例证，甚至一本正经的瑞士，在这方面也作出了自己的成绩。不过，为了使政府和交易所结成这种兄弟般的联盟，并不一定要有民主共和国，除英国以外，新的德意志帝国也证明了这一点，在德国，很难说普选制究竟是把谁抬得更高，是把俾斯麦还是把布莱希勒德。最后，有产阶级是直接通过普选制来统治的。只要被压迫阶级——在我们这里就是无产阶级——还没有成熟到能够自己解放自己，这个阶级的大多数人就仍将承认现存的社会秩序是唯一可行的秩序，而在政治上成为资本家阶级的尾巴，构成它的极左翼。但是，随着被压迫阶级成熟到能够自己解放自己，它就作为独立的党派结合起来，选举自己的代表，而不是选举资本家的代表了。因此，普选制是测量工人阶级成熟性的标尺。在现今的国家里，普选制不能而且永远不会提供更多的东西；不过，这也就足够了。在普选制的温度计标示出工人的沸点的那一天，他们以及资本家同样都知道该怎么办了。","language":"中文","translation":false},{"id":"family-1-394","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":394,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"所以，国家并不是从来就有的。曾经有过不需要国家、而且根本不知国家和国家权力为何物的社会。在经济发展到一定阶段而必然使社会分裂为阶级时，国家就由于这种分裂而成为必要了。现在我们正在以迅速的步伐走向这样的生产发展阶段，在这个阶段上，这些阶级的存在不仅不再必要，而且成了生产的真正障碍。阶级不可避免地要消失，正如它们从前不可避免地产生一样。随着阶级的消失，国家也不可避免地要消失。在生产者自由平等的联合体的基础上按新方式来组织生产的社会，将把全部国家机器放到它应该去的地方，即放到古物陈列馆去，同纺车和青铜斧陈列在一起。","language":"中文","translation":false},{"id":"family-1-395","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":395,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"所以，根据以上所述，文明时代是社会发展的这样一个阶段，在这个阶段上，分工，由分工而产生的个人之间的交换，以及把这两者结合起来的商品生产，得到了充分的发展，完全改变了先前的整个社会。","language":"中文","translation":false},{"id":"family-1-396","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":396,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"先前的一切社会发展阶段上的生产在本质上是共同的生产，同样，消费也是在较大或较小的共产制共同体内部直接分配产品。生产的这种共同性是在极狭小的范围内实现的，但是它随身带来的是生产者对自己的生产过程和产品的支配。他们知道，产品的结局将是怎样：他们把产品消费掉，产品不离开他们的手；只要生产在这个基础上进行，它就不可能越出生产者的支配范围，也不会产生鬼怪般的、对他们来说是异己的力量，像在文明时代经常地和不可避免地发生的那样。","language":"中文","translation":false},{"id":"family-1-397","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":397,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，分工慢慢地侵入了这种生产过程。它破坏生产和占有的共同性，它使个人占有成为占优势的规则，从而产生了个人之间的交换，——这是如何发生的，我们前面已经探讨过了。商品生产逐渐地成了统治的形式。","language":"中文","translation":false},{"id":"family-1-398","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":398,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"随着商品生产，即不再是为了自己消费而是为了交换的生产的出现，产品必然易手。生产者在交换的时候交出自己的产品；他不再知道产品的结局将会怎样。当货币以及随货币而来的商人作为中间人插进生产者之间的时候，交换过程就变得更加错综复杂，产品的最终命运就变得更加不确定了。商人是很多的，他们谁都不知道谁在做什么。商品现在已经不仅是从一手转到另一手，而且是从一个市场转到另一个市场；生产者丧失了对自己生活领域内全部生产的支配权，这种支配权商人也没有得到。产品和生产都任凭偶然性来摆布了。","language":"中文","translation":false},{"id":"family-1-399","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":399,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，偶然性只是相互依存性的一极，它的另一极叫作必然性。在似乎也是受偶然性支配的自然界中，我们早就证实，在每一个领域内，都有在这种偶然性中去实现自己的内在的必然性和规律性。然而适用于自然界的，也适用于社会。一种社会活动，一系列社会过程，越是超出人们的自觉的控制，越是超出他们支配的范围，越是显得受纯粹的偶然性的摆布，它所固有的内在规律就越是以自然的必然性在这种偶然性中去实现自己。这种规律也支配着商品生产和商品交换的偶然性：它们作为异己的、起初甚至是未被认识的、其本性尚待努力研究和探索的力量，同各个生产者和交换的参加者相对立。商品生产的这些经济规律，随这个生产形式的发展阶段的不同而有所变化，但是总的说来，整个文明期都处在这些规律的支配之下。直到今天，产品仍然支配着生产者；直到今天，社会的全部生产仍然不是由共同制定的计划，而是由盲目的规律来调节，这些盲目的规律，以自发的威力，最后在周期性商业危机的风暴中显示着自己的作用。","language":"中文","translation":false},{"id":"family-1-400","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":400,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"上面我们已经看到，在相当早的生产发展阶段上，人的劳动力就能够提供大大超过维持生产者生存所需要的产品了，这个发展阶段，基本上就是产生分工和个人之间的交换的那个阶段。这时，用不了多久就又发现一个伟大的“真理”：人也可以成为商品；如果把人变为奴隶，人力[115]也是可以交换和消费的。人们刚刚开始交换，他们本身也就被交换起来了。主动态变成了被动态，不管人们愿意不愿意。","language":"中文","translation":false},{"id":"family-1-401","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":401,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"随着在文明时代获得最充分发展的奴隶制的出现，就发生了社会分成剥削阶级和被剥削阶级的第一次大分裂。这种分裂继续存在于整个文明期。奴隶制是古希腊罗马时代世界所固有的第一个剥削形式；继之而来的是中世纪的农奴制和近代的雇佣劳动制。这就是文明时代的三大时期所特有的三大奴役形式；公开的而近来是隐蔽的奴隶制始终伴随着文明时代。","language":"中文","translation":false},{"id":"family-1-402","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":402,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"文明时代所由以开始的商品生产阶段，在经济上有下列特征：(1)出现了金属货币，从而出现了货币资本、利息和高利贷；(2)出现了作为生产者之间的中间阶级的商人；(3)出现了土地私有制和抵押；(4)出现了作为占统治地位的生产形式的奴隶劳动。与文明时代相适应并随着它而彻底确立了自己的统治地位的家庭形式是专偶制、男子对妇女的统治，以及作为社会经济单位的个体家庭。国家是文明社会的概括，它在一切典型的时期毫无例外地都是统治阶级的国家，并且在一切场合在本质上都是镇压被压迫被剥削阶级的机器。此外，文明时代还有如下的特征：一方面，是把城市和乡村的对立作为整个社会分工的基础固定下来；另一方面，是实行所有者甚至在死后也能够据以处理自己财产的遗嘱制度。这种同古代氏族制度直接冲突的制度，在雅典直到梭伦时代之前还没有过；在罗马，它很早就已经实行了，究竟在什么时候我们不知道[116]；在德意志人中间，这种制度是由教士引入的，为的是使诚实的德意志人能够毫无阻碍地将自己的遗产遗赠给教会。","language":"中文","translation":false},{"id":"family-1-403","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":403,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"文明时代以这种基本制度完成了古代氏族社会完全做不到的事情。但是，它是用激起人们的最卑劣的冲动和情欲，并且以损害人们的其他一切秉赋为代价而使之变本加厉的办法来完成这些事情的。鄙俗的贪欲是文明时代从它存在的第一日起直至今日的起推动作用的灵魂；财富，财富，第三还是财富，——不是社会的财富，而是这个微不足道的单个的个人的财富，这就是文明时代唯一的、具有决定意义的目的。如果说在文明时代的怀抱中科学曾经日益发展，艺术高度繁荣的时期一再出现，那也不过是因为在积累财富方面的现代的一切积聚财富的成就不这样就不可能获得罢了。","language":"中文","translation":false},{"id":"family-1-404","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":404,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"由于文明时代的基础是一个阶级对另一个阶级的剥削，所以它的全部发展都是在经常的矛盾中进行的。生产的每一进步，同时也就是被压迫阶级即大多数人的生活状况的一个退步。对一些人是好事的，对另一些人必然是坏事，一个阶级的任何新的解放，必然是对另一个阶级的新的压迫。这一情况的最明显的例证就是机器的采用，其后果现在已是众所周知的了。如果说在野蛮人中间，像我们已经看到的那样，不大能够区别权利和义务，那么文明时代却使这两者之间的区别和对立连最愚蠢的人都能看得出来，因为它几乎把一切权利赋予一个阶级，另方面却几乎把一切义务推给另一个阶级。","language":"中文","translation":false},{"id":"family-1-405","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":405,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"但是，这并不是应该如此的。凡对统治阶级是好的，对整个社会也应该是好的，因为统治阶级把自己与整个社会等同起来了。所以文明时代越是向前进展，它就越是不得不给它所必然产生的坏事披上爱的外衣，不得不粉饰它们，或者否认它们，——一句话，是实行习惯性的伪善，这种伪善，无论在较早的那些社会形式下还是在文明时代初期阶段都是没有的，并且最后在下述说法中达到了极点：剥削阶级对被压迫阶级进行剥削，完全是为了被剥削阶级本身的利益；如果被剥削阶级不懂得这一点，甚至想要造反，那就是对行善的人即对剥削者的一种最卑劣的忘恩负义行为。[117]","language":"中文","translation":false},{"id":"family-1-406","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":406,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"现在把摩尔根对文明时代的评断引在下面作一个结束：","language":"中文","translation":false},{"id":"family-1-407","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":407,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"“自从进入文明时代以来，财富的增长是如此巨大，它的形式是如此繁多，它的用途是如此广泛，为了所有者的利益而对它进行的管理又是如此巧妙，以致这种财富对人民说来已经变成了一种无法控制的力量。人类的智慧在自己的创造物面前感到迷惘而不知所措了。然而，总有一天，人类的理智一定会强健到能够支配财富，一定会规定国家对它所保护的财产的关系，以及所有者的权利的范围。社会的利益绝对地高于个人的利益，必须使这两者处于一种公正而和谐的关系之中。只要进步仍将是未来的规律，像它对于过去那样，那么单纯追求财富就不是人类的最终的命运了。自从文明时代开始以来所经过的时间，只是人类已经经历过的生存时间的一小部分，只是人类将要经历的生存时间的一小部分。社会的瓦解，即将成为以财富为唯一的最终目的的那个历程的终结，因为这一历程包含着自我消灭的因素。管理上的民主，社会中的博爱，权利的平等，普及的教育，将揭开社会的下一个更高的阶段，经验、理智和科学正在不断向这个阶段努力。这将是古代氏族的自由、平等和博爱的复活，但却是在更高级形式上的复活。”(摩尔根《古代社会》第552页)","language":"中文","translation":false},{"id":"family-1-408","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":408,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"写于1884年3月底－5月26日","language":"中文","translation":false},{"id":"family-1-409","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":409,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"1884年以单行本形式在苏黎世出版","language":"中文","translation":false},{"id":"family-1-410","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":410,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"选自《马克思恩格斯全集》","language":"中文","translation":false},{"id":"family-1-411","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":411,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"第21卷第32—203页","language":"中文","translation":false},{"id":"family-1-412","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":412,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[1] 路易斯·亨利·摩尔根《古代社会，或人类从蒙昧时代经过野蛮时代到文明时代的发展过程的研究》伦敦麦克米伦公司1877年版。该书在美国刊印，在伦敦极难买到。作者已于数年前去世。","language":"中文","translation":false},{"id":"family-1-413","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":413,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[2] 马克思《摩尔根<古代社会>一书摘要》，见《马克思恩格斯全集》第45卷第328－571页。——编者注","language":"中文","translation":false},{"id":"family-1-414","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":414,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[3] 爱·奥·弗里曼《比较政治》1873年伦敦版。——编者注","language":"中文","translation":false},{"id":"family-1-415","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":415,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[4] 约·狄茨。——编者注","language":"中文","translation":false},{"id":"family-1-416","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":416,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[5] 在《新时代》3刊载的文本里，在“加之”后面是：“新版将大量印行，这在德国社会主义文献中现在已经是常见的事，不过对于德国出版界来说仍然是非常罕见的”。——编者注","language":"中文","translation":false},{"id":"family-1-417","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":417,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[6] 爱·伯·泰勒《人类原始历史和文明的产生的研究》1865年伦敦版。——编者注","language":"中文","translation":false},{"id":"family-1-418","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":418,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[7] 约·雅·巴霍芬《母权论。根据古代世界的宗教的和法的本质对古代世界的妇女统治的研究》1861年斯图加特版。——编者注","language":"中文","translation":false},{"id":"family-1-419","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":419,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[8] 埃斯库罗斯《奥列斯特》三部曲中的《厄默尼德》。——编者注","language":"中文","translation":false},{"id":"family-1-420","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":420,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[9] 约·拉伯克《文明的起源和人的原始状态。蒙昧民族的精神状态和社会状态》1870年伦敦版。——编者注","language":"中文","translation":false},{"id":"family-1-421","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":421,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[10] 路·亨·摩尔根《人类家庭的血亲制度和姻亲制度》1871年华盛顿版。——编者注","language":"中文","translation":false},{"id":"family-1-422","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":422,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[11] 约·拉伯克《文明的起源和人的原始状态。蒙昧民族的精神状态和社会状态》1882年伦敦版。——编者注","language":"中文","translation":false},{"id":"family-1-423","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":423,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[12] 路·亨·摩尔根《古代社会，或人类从蒙昧时代经过野蛮时代到文明时代的发展过程的研究》1877年伦敦版。——编者注","language":"中文","translation":false},{"id":"family-1-424","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":424,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[13] 约·弗·麦克伦南《古代史研究》1876年伦敦版第333页。——编者注","language":"中文","translation":false},{"id":"family-1-425","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":425,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[14] 我于1888年9月从纽约返欧途中，遇到一位罗切斯特选区的前国会议员，他认识摩尔根，可惜，关于摩尔根的事他能给我述说的并不多。摩尔根以个人的身分住在罗切斯特，仅仅从事自己的学术研究工作。他的兄弟是个上校，曾在华盛顿国防部供职；靠这位兄弟的介绍，摩尔根得以使政府对他的研究加以关注，用公款出版了他的几种著作；据我的交谈者自己说，他在任国会议员期间，也曾多次帮过摩尔根的忙。","language":"中文","translation":false},{"id":"family-1-426","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":426,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[15] 在1884年版中不是“塔西佗时代的德意志人，海盗时代的诺曼人”，而是“凯撒时代的德意志人(或者是我们更爱说的，塔西佗时代的德意志人)”。——编者注","language":"中文","translation":false},{"id":"family-1-427","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":427,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[16] 以下直到“血缘家庭……”(本卷第33页)那一段以前的文字，都是恩格斯在1891年版中增补的。1884年版中是：“这种原始状态的发现，是巴霍芬的第一个伟大功绩。从这种原始状态中，大概很早就发展出以下几种家庭形式。”——编者注","language":"中文","translation":false},{"id":"family-1-428","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":428,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[17] 约·雅·巴霍芬《母权论。根据古代世界的宗教的和法的本质对古代世界的妇女统治的研究》1861年斯图加特版。——编者注","language":"中文","translation":false},{"id":"family-1-429","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":429,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[18] 巴霍芬把这种原始状态叫作淫游婚，从而表明，他是多么不了解他所发现的，或者正确些说，他所猜到的东西。希腊人使用淫游婚这个名词，是表示未婚男子或过个体婚生活的男子跟未婚的女子的性关系；这种淫游婚，总是以一定的婚姻形式的存在为前提，在这个婚姻形式之外发生这种性关系；并且包含着至少是一种可能性的卖淫。这个名词，从来没有在别的意义上使用过，我和摩尔根就是在这个意义上使用它的。巴霍芬的极端重要的发现，到处都被他的幻想——即认为历史上发生的男女之间的关系，总是起源于当时人们的宗教观念，而不是起源于人们的现实生活条件——弄得神秘化了，令人难以置信。","language":"中文","translation":false},{"id":"family-1-430","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":430,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[19] 沙·勒土尔诺《婚姻和家庭之进化》1888年巴黎版第41页。——编者注","language":"中文","translation":false},{"id":"family-1-431","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":431,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[20] 爱·韦斯特马克《人类婚姻史》1891年伦敦－纽约版第70－71 页。——编者注","language":"中文","translation":false},{"id":"family-1-432","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":432,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[21] 恩格斯在1884年版上加了一个注：“马克思在1882年春季所写的一封信14中，以最强烈的措辞，批评瓦格纳的《尼贝龙根》歌词中比比皆是的对原始时代的完全曲解。歌词中说：‘谁曾听说哥哥抱着妹妹做新娘？’15瓦格纳的这些‘色情之神’，完全以现代方式，用一些血亲婚配的事情使自己的风流勾当更加耸人听闻；马克思对此回答道：‘在原始时代，姊妹曾经是妻子，而这是合乎道德的’。”恩格斯在1891年版上补加的注文：“瓦格纳的一位法国友人和崇拜者，不同意这个注，说在瓦格纳所根据的《老艾达》中，在《厄革斯德列克》中，洛基就曾指责弗莱雅说：‘在诸神面前，你拥抱自己的哥哥。’可见，兄弟姊妹婚姻在那时候已经被唾弃。不过，《厄革斯德列克》乃是对古代神话的信仰已经完全丧失的那一时代的表现；这是纯粹琉善式的对神的讽刺。要是作为靡菲斯特斐勒司的洛基在这里对弗莱雅作了这样的指责，那么这倒是反驳了瓦格纳。而且，在后边数行诗中，洛基对尼奥德尔说：‘你同你的妹妹生了一个(这样的)儿子’16。尼奥德尔本不是亚萨神，而是瓦那神，所以他在《英格林加传说》中说，兄弟姊妹婚姻，在瓦那国是很普通的，但在亚萨神中间并不如此。17这大概是表明，瓦那神是比亚萨神更古的神。无论如何，尼奥德尔是作为同亚萨神一样的神生活在亚萨神中间的，因此，《厄革斯德列克》勿宁说是证明，在挪威的关于诸神的传说产生的时代，至少诸神之间的兄弟姊妹婚姻尚未引起任何憎恶。要是想为瓦格纳辩护，引用《艾达》倒不如引用歌德，歌德在关于神和舞妓的叙事诗中，说到妇女在寺院献身的宗教义务时也犯了同样的错误，他过于把这种风俗习惯比作现代的卖淫了”。——编者注","language":"中文","translation":false},{"id":"family-1-433","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":433,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[22] “大概”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-434","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":434,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[23] 路·亨·摩尔根《古代社会》1877年伦敦版第425页。——编者注","language":"中文","translation":false},{"id":"family-1-435","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":435,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[24] “或某种与它类似的形式”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-436","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":436,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[25] 巴霍芬认为是他发现的不加区别的性关系，即他所谓的“污泥生殖”(Sumpfzeugung)的遗迹，这些遗迹是来自群婚制，现在关于这一点再不容怀疑了。“如果巴霍芬认为这种普那路亚婚姻是‘非法的’，那么，那一时代的人也许要认为今日从兄弟姊妹或表兄弟姊妹之间结婚，近的和远的，大多数都是血亲婚配，正如亲兄弟和亲姊妹之间结婚一样。”(马克思语)18","language":"中文","translation":false},{"id":"family-1-437","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":437,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[26] 在1884年版中不是“群婚”，而是“普那路亚家庭”。——编者注","language":"中文","translation":false},{"id":"family-1-438","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":438,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[27] 在1884年版中不是“这种群婚形式或与它类似的群婚形式”，而是“这种家庭形式”。——编者注","language":"中文","translation":false},{"id":"family-1-439","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":439,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[28] 在1884年版中不是“而只有比较粗陋的群婚形式”，而是“他们的组织具有十分个别的性质，我们就不要管它了”。——编者注","language":"中文","translation":false},{"id":"family-1-440","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":440,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[29] 以下直到“对偶制家庭”(本卷第43页)那一段以前的文字，都是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-441","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":441,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[30] 路·亨·摩尔根《人类家庭的血亲制度和姻亲制度》1871年华盛顿版。——编者注","language":"中文","translation":false},{"id":"family-1-442","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":442,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[31] 在1884年版中不是“群婚”，而是“普那路亚家庭”。——编者注","language":"中文","translation":false},{"id":"family-1-443","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":443,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[32] 在1884年版中不是“群婚”，而是“普那路亚家庭”。——编者注","language":"中文","translation":false},{"id":"family-1-444","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":444,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[33] 在1884年版中不是“群婚”，而是“普那路亚家庭”。——编者注","language":"中文","translation":false},{"id":"family-1-445","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":445,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[34] “使人很难设想……”这句话是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-446","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":446,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[35] 以下直到“对偶制家庭产生于蒙昧时代和野蛮时代交替的时期”(本卷第50页)以前，在1884年版中是如下一句话：“旧大陆的这一类遗迹是众所周知的，例如，腓尼基姑娘在阿斯塔尔塔节在寺庙中献身的风俗；甚至中世纪的初夜权，也是大概由克尔特氏族(克兰)传下来的普那路亚家庭的残余，尽管德国的新浪漫派竭力掩饰这个事实，初夜权却极其确凿地存在过。”——编者注","language":"中文","translation":false},{"id":"family-1-447","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":447,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[36] 在1884年版中不是“特殊财产”，而是“私有财产”。——编者注","language":"中文","translation":false},{"id":"family-1-448","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":448,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[37] 在1884年版中不是“以前容易得到的妻子现在具有了交换价值”，而是“以前众多的妻子现在具有了价值”。——编者注","language":"中文","translation":false},{"id":"family-1-449","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":449,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[38] 在1884年版中不是“家庭所有”，而是“私人所有”。——编者注","language":"中文","translation":false},{"id":"family-1-450","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":450,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[39] “家庭”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-451","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":451,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[40] 在“(马克思语)”以后直到本段结束是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-452","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":452,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[41] 以下直到“在说到随着母权制的覆灭……”(本卷第57页)以前是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-453","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":453,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[42] 在1884年版中不是“群婚”，而是“普那路亚家庭”。——编者注","language":"中文","translation":false},{"id":"family-1-454","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":454,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[43] 最后一句话是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-455","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":455,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[44] 1804年拿破仑统治时期通过的民法典第230条。——编者注","language":"中文","translation":false},{"id":"family-1-456","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":456,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[45] 在1884年版中，这句话的末尾是这样的：“但是到了英雄时代，我们就看到，妇女处于半囚禁的隔绝状态，以便保证子女确实出自父亲”。自此以下直到“但是，尽管有这些幽禁和监视”(本卷第62页)以前的几大段文字，都是恩格斯在1891年版上增补的，以代替1884 年版中的如下一段话：“相反，男人却以被俘的女奴隶、他的战时共享帐篷的女伴来寻欢作乐。古典时期的情况未必更好。从贝克尔《查里克利斯》一书我们可以较为详细地查阅到希腊人如何对待妇女的情形。她们虽说不是被幽禁，但也是与世隔绝的，她们成了自己丈夫最高等的婢女，只能同主要是其他的婢女来往。姑娘们则干脆被幽禁起来；妇女们只有由女奴作伴才能离家外出。如有男子来访，妇女就躲进自己的房间里去”。——编者注","language":"中文","translation":false},{"id":"family-1-457","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":457,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[46] 荷马《奥德赛》第1首歌。——编者注","language":"中文","translation":false},{"id":"family-1-458","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":458,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[47] 埃斯库罗斯《奥列斯特》三部曲中的《亚加米农》。——编者注","language":"中文","translation":false},{"id":"family-1-459","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":459,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[48] 阿里斯托芬《费斯莫佛里节日中的妇女》。——编者注","language":"中文","translation":false},{"id":"family-1-460","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":460,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[49] 欧里庇得斯《奥列斯特》。——编者注","language":"中文","translation":false},{"id":"family-1-461","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":461,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[50] 在1884年版中这句话是：“专偶制是不以自然条件为基础，而以社会条件为基础的第一个家庭形式。”——编者注","language":"中文","translation":false},{"id":"family-1-462","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":462,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[51] 最后一句话是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-463","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":463,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[52] 路·亨·摩尔根《古代社会》1877年伦敦版第504页。——编者注","language":"中文","translation":false},{"id":"family-1-464","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":464,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[53] 以下直到“淫游制和社会的任何其他制度一样……”以前是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-465","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":465,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[54] 这句话和前一句话是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-466","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":466,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[55] 塔西佗《日耳曼尼亚志》第18－19章。——编者注","language":"中文","translation":false},{"id":"family-1-467","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":467,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[56] 后半句话是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-468","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":468,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[57] 在1884年版中是：“德国的和瑞典的”。——编者注","language":"中文","translation":false},{"id":"family-1-469","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":469,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[58] 以下直到“只有在被压迫阶级中间……”以前是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-470","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":470,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[59] 以下直到“现在让我们再回过来谈摩尔根吧”(本卷第81页)以前的文字，是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-471","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":471,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[60] 《尼贝龙根之歌》第10首歌。——编者注","language":"中文","translation":false},{"id":"family-1-472","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":472,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[61] 见本选集第1卷第272－277页。——编者注","language":"中文","translation":false},{"id":"family-1-473","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":473,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[62] “droit de l′homme”既有“人的权利”的意思，也有“男子的权利”的意思。——编者注","language":"中文","translation":false},{"id":"family-1-474","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":474,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[63] “一时”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-475","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":475,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[64] 指1519－1521年西班牙侵略者征服墨西哥的时期。——编者注","language":"中文","translation":false},{"id":"family-1-476","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":476,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[65] 塔西佗《日耳曼尼亚志》。——编者注","language":"中文","translation":false},{"id":"family-1-477","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":477,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[66] 参看《马克思恩格斯全集》第23卷第96页。——编者注","language":"中文","translation":false},{"id":"family-1-478","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":478,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[67] 在1884年版中不是“群婚”，而是“普那路亚家庭”。——编者注","language":"中文","translation":false},{"id":"family-1-479","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":479,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[68] “严格的”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-480","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":480,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[69] 在马克思的手稿中不是格罗特，而是格罗特经常引用其著作的公元2世纪的古希腊学者坡吕克斯。——编者注","language":"中文","translation":false},{"id":"family-1-481","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":481,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[70] 在马克思的手稿中接着还有一句为恩格斯所省略的话：“奥德赛用来称呼亚加米农的‘科伊腊诺斯’这个词和‘巴赛勒斯’这个词一样，也仅仅意味着‘战争中军队的统帅’”。——编者注","language":"中文","translation":false},{"id":"family-1-482","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":482,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[71] 就像希腊的巴赛勒斯一样，阿兹特克人的军事首长也被误解为近代的王公。摩尔根最先对于西班牙人的起初是出于误会和夸张，后来简直是说谎的报告作了历史的考证，并证明，墨西哥人处于野蛮时代中级阶段，但他们的发展程度超过了新墨西哥的普韦布洛印第安人，他们的社会制度在根据被曲解了的报告来推论的范围内说，相当于以下的情形：这是一个包括三个部落的联盟，它征服了其他几个部落并使之纳贡；它由联盟议事会和联盟军事首长来管理，西班牙人就是把这个联盟军事首长变成了“皇帝”。","language":"中文","translation":false},{"id":"family-1-483","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":483,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[72] 在1884年版中这句话的结尾是这样写的：“因为其余两个阶级并未获得任何特殊的权利”。——编者注","language":"中文","translation":false},{"id":"family-1-484","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":484,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[73] 来源于古希腊文的“菲拉”(部落)一词。——编者注","language":"中文","translation":false},{"id":"family-1-485","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":485,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[74] 法文“police”(警察)的形容词“policé”意为“文明的”。——编者注","language":"中文","translation":false},{"id":"family-1-486","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":486,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[75] 方言，意即宪兵。——编者注","language":"中文","translation":false},{"id":"family-1-487","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":487,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[76] “可见他的氏族(昆提利)还有专用的坟地”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-488","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":488,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[77] 在1884年版中不是“未必是”，而是“并不必定是”。——编者注","language":"中文","translation":false},{"id":"family-1-489","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":489,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[78] 从本段开始到“在罗马建城差不多300年后”(本卷第125页)以前是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-490","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":490,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[79] 梯·李维《罗马建城以来的历史》。——编者注","language":"中文","translation":false},{"id":"family-1-491","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":491,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[80] 拉丁语的rex［勒克斯］，相当于克尔特一爱尔兰语的righ(部落长)和哥特语的reiks［勒克斯］。哥特语的这个词，像德语的本义(与英语的first，丹麦语的相同，意即“第一”)一样，也是氏族酋长或部落酋长的意思，这从哥特人在4世纪时对于后世的王即全体人民的军事首长已有特别名称即thiudans［狄乌丹斯］一事中已可以看出来。在乌尔菲拉所翻译的圣经中，阿尔塔薛西斯和希律从来不叫作reiks［勒克斯］，而是叫作thiudans［狄乌丹斯］，提比利乌斯皇帝的国家从来不叫做reiki，而叫作thiudinassus。在哥特的thi－udans(这个词我们不大确切地译为“王”)的名字Thiudareiks即德语的Theodorich［狄奥多里希］亦称Dietrich［迪特里希］中，两个名称合而为一了。","language":"中文","translation":false},{"id":"family-1-492","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":492,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[81] 以下直到本段结束是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-493","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":493,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[82] 涅涅茨人的旧称。——编者注","language":"中文","translation":false},{"id":"family-1-494","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":494,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[83] 约·弗·麦克伦南《原始婚姻》1865年爱丁堡版。——编者注","language":"中文","translation":false},{"id":"family-1-495","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":495,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[84] 《威尔士的古代法律和规章》1841年版第1卷第93页。——编者注","language":"中文","translation":false},{"id":"family-1-496","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":496,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[85] 恩格斯在1891年版上加了一个注：“在爱尔兰度过的那几天中96，我重新鲜明地意识到那里的乡村居民还是多么厉害地生活在氏族时代的观念中。土地所有者在他的佃户农民的眼中还俨然是一种为了全体的利益而管理土地的克兰首领；农民以租金的形式向他纳贡，但认为在困难时也应得到他的帮助。同样，一切比较富裕的人，也被认为当自己的比较贫苦的邻居有急需时，有责任接济他们，这种帮助并不是施舍，而是比较富有的克兰成员或克兰首领理所当然地应给予比较贫苦的克兰成员的。政治经济学家和法学家们抱怨无法使爱尔兰农民接受现代资产阶级的财产概念，这是可以理解的；只有权利而无义务的财产概念，绝不能灌输到爱尔兰人头脑中去。当具有这种素朴氏族观念的爱尔兰人突然流落到英国或美国的大城市，置身于道德观念和法律观念全然不同的居民中时，他们在道德和法律问题上会多么容易迷惑惶乱，失去一切依托并且往往大批地道德沦丧——这也是可以理解的”。——编者注","language":"中文","translation":false},{"id":"family-1-497","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":497,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[86] 路·亨·摩尔根《古代社会》1877年伦敦版第357－358页。编者注","language":"中文","translation":false},{"id":"family-1-498","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":498,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[87] 贝达《盎格鲁教会史》第1册第1章。——编者注","language":"中文","translation":false},{"id":"family-1-499","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":499,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[88] 在1884年版中在这句话后面接着还有两段话，第一段话是：“这种权利——在北美洲的最西北部地区经常可以见到——在俄国人当中也流行过；到10世纪时被奥丽珈女大公废除。”这一段话在1891 年版中被恩格斯略去。第二段话是：“在法国，特别是在尼韦奈和弗朗什孔泰，直到法国革命时期还存在着与塞尔维亚－克罗地亚地区的斯拉夫人的家庭公社相似的由农奴家庭组成的共产制家户，这也是从前氏族组织的残余。这种共产制家户还没有完全消亡，例如在鲁昂地区(在索恩－卢瓦尔省)还可以看到一些巨大的、造型别致的农民住房，中间是公用的大厅，四周是卧室，住着同一家庭的好几代人。”这一段话在1891年版中被恩格斯修改后补入第二章(见本卷第56－57页)。——编者注","language":"中文","translation":false},{"id":"family-1-500","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":500,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[89] 以下直到“像在墨西哥人和希腊人那里一样，在德意志人那里”(本卷第136页)以前的段落，是恩格斯在1891年版中增补的；在1884 年版中原是如下一段话：“……还按氏族居住。在公元8世纪的《阿勒曼尼法典》中genealogia一词完全与马尔克公社一词同义。这样我们就看到，德意志民族之一，并且恰恰又是苏维汇人，在这里是按血族即gentes分居的，每个氏族都分有确定的地区。勃艮第人和伦巴德人的氏族称为fara，而《勃艮第法典》中所使用的氏族成员(faramanni)一词，同时也指勃艮第人，这是针对着罗马居民说的，后者自然不包括在勃艮第氏族内。因而在勃艮第人那里，土地的分配也是按照氏族进行的。日耳曼法学家们一百年来为之绞尽脑汁的faramanni问题，这样就可解决。在德意志人中并不是到处都把氏族称为fara，尽管我们在一个哥特系的民族和另一个赫米奥南(高地德意志)系的民族那里可以发现这个名称。在德语中用来表示亲属关系的字根是很多的，这些字根同样使用在我们可以推断是和氏族有关的词语中。”——编者注","language":"中文","translation":false},{"id":"family-1-501","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":501,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[90] 德语是fahren。——编者注","language":"中文","translation":false},{"id":"family-1-502","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":502,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[91] 德语是Sippe。——编者注","language":"中文","translation":false},{"id":"family-1-503","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":503,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[92] 塔西佗《日耳曼尼亚志》第7章。——编者注","language":"中文","translation":false},{"id":"family-1-504","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":504,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[93] 起源于母权制时代并在许多民族中间都可以看到的舅父和外甥之间的特别密切的关系，只是在英雄时代的神话中希腊人才具有。据狄奥多鲁斯(第4卷第34章)说，梅里格尔杀死了铁斯特士的儿子们，也就是自己母亲阿耳泰娅的兄弟们。阿耳泰娅认为这种行为是一种无可饶恕的罪行，她诅咒凶手——她自己的儿子，并祈求他死。“据说，诸神听从了她的愿望，结束了梅里格尔的生命。”又据狄奥多鲁斯(第4卷第44章)说，海格立斯率领下的亚尔古船英雄在色雷斯登陆，他们在那里发现，菲尼士受他新妻子的教唆，残酷虐待被他遗弃的前妻——博雷阿德族的克利奥帕特腊所生的两个儿子。但在亚尔古船英雄中间，也有博雷阿德族的人，即克利奥帕特腊的兄弟们，也就是被虐待者的母亲的兄弟们。他们立刻保护他们的两个外甥，释放他们并杀死看守者。102","language":"中文","translation":false},{"id":"family-1-505","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":505,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[94] 以下直到本页“此外，在塔西佗时代”以前是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-506","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":506,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[95] “至少在他较为熟悉的”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-507","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":507,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[96] 毛勒《德国城市制度史》1869年埃朗根版。——编者注","language":"中文","translation":false},{"id":"family-1-508","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":508,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[97] 凯撒《高卢战记》第4卷第1章。——编者注","language":"中文","translation":false},{"id":"family-1-509","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":509,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[98] 塔西佗《日耳曼尼亚志》第26章。——编者注","language":"中文","translation":false},{"id":"family-1-510","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":510,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[99] 以下直到“在凯撒时代，一部分德意志人……”(本卷第142页)以前是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-511","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":511,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[100] 见本卷第55－57页。——编者注","language":"中文","translation":false},{"id":"family-1-512","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":512,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[101] 普林尼《博物志》(三十七卷集)第18卷第17章。——编者注","language":"中文","translation":false},{"id":"family-1-513","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":513,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[102] 这里所推测的数字，在狄奥多鲁斯关于高卢的克尔特人的一段文字中可以得到证实。他说：“在高卢住着人口不等的许多民族，其中最大者，人口约为20万人，最小者约为5万人。”(Diodorus Siculus，V，25.)因而，平均起来是125000人；由于各个高卢民族发展程度较高，应该把他们的人口设想得比德意志人多一些。","language":"中文","translation":false},{"id":"family-1-514","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":514,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[103] 普林尼《博物志》第4卷第14章。——编者注","language":"中文","translation":false},{"id":"family-1-515","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":515,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[104] 据克雷莫纳的主教利乌特普朗德说，10世纪在凡尔登，也就是说，在神圣德意志帝国，制造阉人成了一个主要的行业，因为把这些阉人输入西班牙，供摩尔人的后宫使用，可获厚利。107","language":"中文","translation":false},{"id":"family-1-516","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":516,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[105] 萨尔维安《论神的统治》第5册第8章。——编者注","language":"中文","translation":false},{"id":"family-1-517","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":517,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[106] 以下直到本段结束是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-518","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":518,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[107] 给土地耕种者提供了一个获得集体和逐渐解放的手段。——编者注","language":"中文","translation":false},{"id":"family-1-519","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":519,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[108] “通常是分为两个”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-520","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":520,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[109] 特别是在美洲的西北沿岸，见班克罗夫特的著作。在夏洛特皇后群岛上的海达人部落中，还有700人聚居在一所房屋中的家户经济。在努特卡人那里，整个部落都聚居在一所房屋中生活。","language":"中文","translation":false},{"id":"family-1-521","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":521,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[110] 在1884年版中不是“特殊财产”，而是“私有财产”。——编者注","language":"中文","translation":false},{"id":"family-1-522","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":522,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[111] “交给家庭公社使用，最后”是恩格斯在1891年版上增补的。——编者注","language":"中文","translation":false},{"id":"family-1-523","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":523,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[112] 莫里哀《乔治·唐丹》第1幕第9场。——编者注","language":"中文","translation":false},{"id":"family-1-524","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":524,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[113] 雅典奴隶的人数见前第117页。在科林斯城全盛时代，奴隶的人数达46万人，在埃吉纳达47万人；在这两个地方奴隶的人数都等于自由民的十倍。","language":"中文","translation":false},{"id":"family-1-525","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":525,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[114] 对于氏族的本质至少已有大致概念的第一个历史编纂学家是尼布尔，这应归功于他熟悉迪特马申116的血族。但是他的错误也是直接由此而来的。","language":"中文","translation":false},{"id":"family-1-526","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":526,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[115] 在1884年版中不是“人力”，而是“人的劳动力”。——编者注","language":"中文","translation":false},{"id":"family-1-527","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":527,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[116] 拉萨尔的《既得权利体系》118一书第二部的中心，主要是这样一个命题：罗马的遗嘱制同罗马本身一样古老，以致在罗马历史上，从来“没有过无遗嘱制的时代”，遗嘱制确切些说是在罗马以前的时代从对死者的崇拜中产生的。拉萨尔作为一个虔诚的老年黑格尔派，不是从罗马人的社会关系中，而是从意志的“思辨概念”中引伸出罗马的法的规定，从而得出了上述的完全非历史的论断。这在该书中是不足为奇的，因为该书根据同一个思辨概念得出结论，认为在罗马的继承制中财产的转移纯粹是次要的事情。拉萨尔不仅相信罗马法学家，特别是较早时期的罗马法学家的幻想，而且还比他们走得更远。","language":"中文","translation":false},{"id":"family-1-528","author":"恩格斯","title":"家庭、私有制和国家的起源","location":"恩格斯：家庭、私有制和国家的起源就路易斯·亨·摩尔根的研究成果而作","page":1,"paragraph":528,"url":"https://www.marxists.org/chinese/engels/marxist.org-chinese-engels-1884-3.htm","text":"[117] 我最初打算引用散见于沙尔·傅立叶著作中的对文明时代的卓越的批判，同摩尔根和我自己对文明时代的批判并列。可惜我没有时间来做这个工作了。现在我只想说明，傅立叶已经把专偶制和土地所有制作为文明时代的主要特征，他把文明时代叫作富人对穷人的战争。同样，我们也发现他有一个深刻的观点，即认为在一切不完善的、分裂为对立面的社会中，个体家庭(les familles incohérentes)是一种经济单位。","language":"中文","translation":false},{"id":"state-1-1","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-1-2","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"马克思主义关于国家的学说与无产阶级在革命中的任务[1]","language":"中文","translation":false},{"id":"state-1-3","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"来源：《列宁全集》第三十一卷（第二版）","language":"中文","translation":false},{"id":"state-1-4","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"国家问题，现在无论在理论方面或在政治实践方面，都具有特别重大的意义。帝国主义战争大大加速和加剧了垄断资本主义变为国家垄断资本主义的过程。国家同势力极大的资本家同盟日益密切地溶合在一起，它对劳动群众的骇人听闻的压迫愈来愈骇人听闻了。各先进国家（我们指的是它们的“后方”）变成了工人的军事苦役监狱。","language":"中文","translation":false},{"id":"state-1-5","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"旷日持久的战争造成的空前惨祸和灾难，使群众生活痛苦不堪，使他们更加愤慨。国际无产阶级革命正在显著地发展。这个革命对国家的态度问题，已经具有实践的意义了。","language":"中文","translation":false},{"id":"state-1-6","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"在几十年较为和平的发展中积聚起来的机会主义成分，造成了在世界各个正式的社会党内占统治地位的社会沙文主义流派。这个流派（在俄国有普列汉诺夫、波特列索夫、布列什柯夫斯卡娅、鲁巴诺维奇以及以稍加掩饰的形式出现的策列铁里先生、切尔诺夫先生之流，在德国有谢德曼、列金、大卫等；在法国和比利时有列诺得尔、盖得、王德威尔得；在英国有海德门和费边派[2]，等等）是口头上的社会主义、实际上的沙文主义，其特点就在于这些“社会主义领袖”不仅对于“自己”民族的资产阶级的利益，而且正是对于“自己”国家的利益，采取卑躬屈膝的迎合态度，因为大多数所谓大国早就在剥削和奴役很多弱小民族。而帝国主义战争正是为了瓜分和重新瓜分这种赃物而进行的战争。如果不同“国家”问题上的机会主义偏见作斗争，使劳动群众摆脱资产阶级影响、特别是摆脱帝国主义资产阶级影响的斗争就无法进行。","language":"中文","translation":false},{"id":"state-1-7","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"首先，我们要考察一下马克思和恩格斯的国家学说，特别详细地谈谈这个学说被人忘记或遭到机会主义歪曲的那些方面。其次，我们要专门分析一下歪曲这个学说的主要代表人物，即在这次战争中如此可悲地遭到破产的第二国际（1889—1914年）的最著名领袖卡尔·考茨基。最后，我们要给俄国1905年革命、特别是1917年革命的经验，作一个基本的总结。后面这次革命的第一个阶段看来现在（1917年8月初）正在结束，但整个这次革命只能认为是帝国主义战争引起的无产阶级社会主义革命的链条中的一个环节。因此，无产阶级社会主义革命对国家的态度问题不仅具有政治实践的意义，而且具有最迫切的意义，这个问题是要向群众说明，为了使自己从资本的枷锁下解放出来，他们在最近的将来应当做些什么。","language":"中文","translation":false},{"id":"state-1-8","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"本版，即第2版，几乎没有变动，仅在第2章中增加了第3节。","language":"中文","translation":false},{"id":"state-1-9","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"1918年12月17日于莫斯科","language":"中文","translation":false},{"id":"state-1-10","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"[1] 《国家与革命（马克思主义关于国家的学说与无产阶级在革命中的任务）》一书写于1917年8—9月，1918年5月在彼得格勒出版。在此以前，1917年12月17日（30日），《真理报》发表了它的序言和第1章的头两节。","language":"中文","translation":false},{"id":"state-1-11","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"为了撰写关于马克思主义对国家态度问题的著作，列宁于1916年秋和1917年初在苏黎世精心研究了马克思和恩格斯的国家学说，并把收集到的材料汇集成了一本笔记，取名为《马克思主义论国家》（见本卷第130—222页）。因笔记本封面为蓝色，通称“蓝皮笔记”。1917年4月列宁从瑞士回到俄国后，由于忙于革命实际活动，不能立即进行国家问题的著述，但也没有把这一计划完全搁置一边。1917年6月，他曾拟了一张研究马克思主义对国家态度问题的书单，并了解过彼得格勒公共图书馆的工作制度。1917年七月事变后，列宁匿居在拉兹利夫，才得以着手写作《国家与革命》一书。为此他请人把“蓝皮笔记”送到拉兹利夫，后又请人送来了马克思和恩格斯的著作《反杜林论》、《哲学的贫困》和《共产党宣言》（德文版和俄文版）等。8月上旬到芬兰的赫尔辛福斯后，他继续专心写作。按原定计划，本书共7章。列宁写完了前6章，拟了第7章《1905年和1917年俄国革命的经验》的详细提纲和《结束语》的提纲（见本卷第230—231页和第241—242页）。列宁曾写信告诉出版者，如果第7章完稿太晚，或者分量过大，那就有必要把前6章单独出版，作为第1分册。本书最初就是作为第1分册出版的。","language":"中文","translation":false},{"id":"state-1-12","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"在本书手稿的第1页上，为了应付临时政府的检查，作者署了一个从未用过的笔名：弗·弗·伊万诺夫斯基。但是这本书到1918年才出版，因此也就没有使用这个笔名而用了大家都知道的笔名：弗·伊林（尼·列宁）。1919年本书再版时，列宁在第2章中加了《1852年马克思对问题的提法》一节。——1。","language":"中文","translation":false},{"id":"state-1-13","author":"列宁","title":"国家与革命","location":"第一版序言·第二版序言","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/01.htm","text":"[2] 费边派是1884年成立的英国改良主义组织费边社的成员，多为资产阶级知识分子，代表人物有悉·维伯、比·维伯、拉·麦克唐纳、肖伯纳、赫·威尔斯等。费边·马克西姆是古罗马统帅，以在第二次布匿战争（公元前218—201年）中采取回避决战的缓进待机策略著称，费边社即以此人名字为名。费边派虽认为社会主义是经济发展的必然结果，但只承认演进的发展道路。他们反对马克思主义的阶级斗争和无产阶级革命学说，鼓吹通过细微改良来逐渐改造社会，宣扬所谓“地方公有社会主义”。1900年费边社加入工党（当时称工人代表委员会），仍保留自己的组织。在工党中，它一直起制定纲领原则和策略原则的思想中心的作用。第一次世界大战期间，费边派采取了社会沙文主义立场。关于费边派，参看列宁《社会民主党在1905—1907年俄国第一次革命中的土地纲领》第4章第7节和《英国的和平主义和英国的不爱理论》（见《列宁全集》第2版第16卷和第26卷）。——2。","language":"中文","translation":false},{"id":"state-2-1","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-2-2","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"1．国家是阶级矛盾不可调和的产物","language":"中文","translation":false},{"id":"state-2-3","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"2．特殊的武装队伍，监狱等等","language":"中文","translation":false},{"id":"state-2-4","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"3．国家是剥削被压迫阶级的工具","language":"中文","translation":false},{"id":"state-2-5","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"4．国家“自行消亡”和暴力革命","language":"中文","translation":false},{"id":"state-2-6","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"1．国家是阶级矛盾不可调和的产物","language":"中文","translation":false},{"id":"state-2-7","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"马克思的学说在今天的遭遇，正如历史上被压迫阶级在解放斗争中的革命思想家和领袖的学说常有的遭遇一样。当伟大的革命家在世时，压迫阶级总是不断迫害他们，以最恶毒的敌意、最疯狂的仇恨、最放肆的造谣和诽谤对待他们的学说。在他们逝世以后，便试图把他们变为无害的神像，可以说是把他们偶像化，赋予他们的名字某种荣誉，以便“安慰”和愚弄被压迫阶级，同时却阉割革命学说的内容，磨去它的革命锋芒，把它庸俗化。现在资产阶级和工人运动中的机会主义者在对马克思主义作这种“加工”的事情上正一致起来。他们忘记、抹杀和歪曲这个学说的革命方面，革命灵魂。他们把资产阶级可以接受或者觉得资产阶级可以接受的东西放在第一位来加以颂扬。现在，一切社会沙文主义者都成了“马克思主义者”，这可不是说着玩的！那些德国的资产阶级学者，昨天还是剿灭马克思主义的专家，现在却愈来愈频繁地谈论起“德意志民族的”马克思来了，似乎马克思培育出了为进行掠夺战争而组织得非常出色的工人联合会！","language":"中文","translation":false},{"id":"state-2-8","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"在这种情况下，在对马克思主义的种种歪曲空前流行的时候，我们的任务首先就是要恢复真正的马克思的国家学说。为此，必须大段大段地引证马克思和恩格斯本人的著作。当然，大段的引证会使文章冗长，并且丝毫无助于通俗化。但是没有这样的引证是绝对不行的。马克思和恩格斯著作中所有谈到国家问题的地方，至少一切有决定意义的地方，一定要尽可能完整地加以引证，使读者能够独立地了解科学社会主义创始人的全部观点以及这些观点的发展，同时也是为了确凿地证明并清楚地揭示现在占统治地位的“考茨基主义”对这些观点的歪曲。","language":"中文","translation":false},{"id":"state-2-9","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"我们先从传播最广的弗·恩格斯的《家庭、私有制和国家的起源》一书讲起，这本书已于1894年在斯图加特出了第6版。我们必须根据德文原著来译出引文，因为俄文译本虽然很多，但多半不是译得不全，就是译得很糟。","language":"中文","translation":false},{"id":"state-2-10","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯在总结他所作的历史的分析时说：“国家决不是从外部强加于社会的一种力量。国家也不象黑格尔所断言的是‘伦理观念的现实’，‘理性的形象和现实’。勿宁说，国家是社会在一定发展阶段上的产物；国家是表示：这个社会陷入了不可解决的自我矛盾，分裂为不可调和的对立面而又无力摆脱这些对立面。而为了使这些对立面，这些经济利益互相冲突的阶级，不致在无谓的斗争中把自己和社会消灭，就需要有一种表面上站在社会之上的力量来抑制冲突，把冲突保持在‘秩序’的范围以内；这种从社会中产生但又居于社会之上并且日益同社会相异化的力量，就是国家。”（德文第6版第177—178页）［注：《马克思恩格斯全集》第21卷第194页。——编者注］","language":"中文","translation":false},{"id":"state-2-11","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"这一段话十分清楚地表达了马克思主义关于国家的历史作用见和意义这一问题的基本思想。国家是阶级矛盾不可调和的产物和表现。在阶级矛盾客观上不能调和的地方、时候和条件下，便产生国家。反过来说，国家的存在证明阶级矛盾不可调和。","language":"中文","translation":false},{"id":"state-2-12","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"对马克思主义的歪曲正是从这最重要的和根本的一点上开始的，这种歪曲来自两个主要方面。","language":"中文","translation":false},{"id":"state-2-13","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"一方面，资产阶级的思想家，特别是小资产阶级的思想家——他们迫于无可辩驳的历史事实不得不承认，只有存在阶级矛盾和阶级斗争的地方才有国家——这样来“稍稍纠正”马克思，把国家说成是阶级调和的机关。在马克思看来，如果阶级调和是可能的话，国家既不会产生，也不会保持下去。而照市侩和庸人般的教授和政论家们说来（往往还善意地引用马克思的话作根据！），国家正是调和阶级的。在马克思看来，国家是阶级统治的机关，是一个阶级压迫另一个阶级的机关，是建立一种“秩序”来抑制阶级冲突，使这种压迫合法化、固定化。在小资产阶级政治家看来，秩序正是阶级调和，而不是一个阶级对另一个阶级的压迫；抑制冲突就是调和，而不是剥夺被压迫阶级用来推翻压迫者的一定的斗争手段和斗争方式。","language":"中文","translation":false},{"id":"state-2-14","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"例如，在1917年革命中，当国家的意义和作用问题正好显得极为重要，即作为立刻行动而且是大规模行动的问题在实践上提出来的时候，全体社会革命党人[3]和孟什维克一下子就完全滚到“国家”“调和”阶级这种小资产阶级理论方面去了。这两个政党的政治家写的无数决议和文章，都浸透了这种市侩的庸俗的“调和”论。至于国家是一定阶级的统治机关，这个阶级不可能与同它对立的一方（同它对抗的阶级）调和，这是小资产阶级民主派始终不能了解的。我国社会革命党人和孟什维克根本不是社会主义者（我们布尔什维克一直都在这样证明），而是唱着准社会主义的高调的小资产阶级民主派，他们对国家的态度就是最明显的表现之一。","language":"中文","translation":false},{"id":"state-2-15","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"另一方面，“考茨基主义”对马克思主义的歪曲要巧妙得多。“在理论上”，它既不否认国家是阶级统治的机关，也不否认阶级矛盾不可调和。但是，它忽视或抹杀了以下一点：既然国家是阶级矛盾不可调和的产物，既然它是站在社会之上并且“日益同社会相异化”的力量，那么很明显，被压迫阶级要求得解放，不仅非进行暴力革命不可，而且非消灭统治阶级所建立的、体现这种“异化”的国家政权机构不可。这个在理论上不言而喻的结论，下面我们会看到，是马克思对革命的任务作了具体的历史的分析后十分明确地得出来的。正是这个结论被考茨基……“忘记”和歪曲了，这一点我们在下面的叙述中还要详细地证明。","language":"中文","translation":false},{"id":"state-2-16","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"2．特殊的武装队伍，监狱等等","language":"中文","translation":false},{"id":"state-2-17","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯继续说：“……国家和旧的氏族〈或克兰[4]〉组织不同的地方，第一点就是它按地区来划分它的国民。……”","language":"中文","translation":false},{"id":"state-2-18","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"我们现在觉得这种划分“很自然”，但这是同血族或氏族的旧组织进行了长期的斗争才获得的。","language":"中文","translation":false},{"id":"state-2-19","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“……第二个不同点，是公共权力的设立，这种公共权力已不再同自己组织为武装力量的居民直接符合了。这种特殊的公共权力之所以需要，是因为自从社会分裂为阶级以后，居民的自动的武装组织已经成为不可能了。……这种公共权力在每一个国家里都存在。构成这种权力的，不仅有武装的人，而且还有物质的附属物，如监狱和各种强制机关，这些东西都是以前的氏族〈克兰〉社会所没有的。……”［注：见《马克思恩格斯全集》第21卷第194—195页。——编者注］","language":"中文","translation":false},{"id":"state-2-20","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯在这里阐明了被称为国家的那种“力量”的概念，即从社会中产生但又居于社会之上并且日益同社会相异化的力量的概念。这种力量主要是什么呢？主要是拥有监狱等等的特殊的武装队伍。","language":"中文","translation":false},{"id":"state-2-21","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"应该说这是特殊的武装队伍，因为任何国家所具有的公共权力已经“不再”同武装的居民，即同居民的“自动的武装组织”“直接符合”了。","language":"中文","translation":false},{"id":"state-2-22","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"同一切伟大的革命思想家一样，恩格斯也竭力促使有觉悟的工人去注意被流行的庸俗观念认为最不值得注意、最习以为常的东西，被根深蒂固的甚至可说是顽固不化的偏见奉为神圣的东西。常备军和警察是国家政权的主要强力工具，但是，难道能够不是这样吗？","language":"中文","translation":false},{"id":"state-2-23","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"19世纪末，大多数欧洲人认为只能是这样。恩格斯的话正是对这些人说的。他们没有经历过，也没有亲眼看到过一次大的革命。他们完全不了解什么是“居民的自动的武装组织”。对于为什么要有特殊的、居于社会之上并且同社会相异化的武装队伍（警察、常备军）这个问题，西欧和俄国的庸人总是喜欢借用斯宾塞或米海洛夫斯基的几句话来答复，说这是因为社会生活复杂化、职能分化等等。","language":"中文","translation":false},{"id":"state-2-24","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"这种说法似乎是“科学的”，而且很能迷惑一般人；它掩盖了社会分裂为不可调和地敌对的阶级这个主要的基本的事实。","language":"中文","translation":false},{"id":"state-2-25","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"如果没有这种分裂，“居民的自动的武装组织”，就其复杂程度、技术水平等等来说，固然会不同于拿着树棍的猿猴群或原始人或组成克兰社会的人们的原始组织，但这样的组织是可能有的。","language":"中文","translation":false},{"id":"state-2-26","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"这样的组织所以不可能有，是因为文明社会已分裂为敌对的而且是不可调和地敌对的阶级。如果这些阶级都有“自动的”武装，就会导致它们之间的武装斗争。于是国家形成了，特殊的力量即特殊的武装队伍建立起来了。每次大革命在破坏国家机构的时候，我们都看到赤裸裸的阶级斗争，我们都清楚地看到，统治阶级是如何力图恢复替它服务的特殊武装队伍，被压迫阶级又是如何力图建立一种不替剥削者服务，而替被剥削者服务的新型的同类组织。","language":"中文","translation":false},{"id":"state-2-27","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯在上面的论述中从理论上提出的问题，正是每次大革命实际地、明显地而且是以大规模的行动提到我们面前的问题，即“特殊的”武装队伍同“居民的自动的武装组织”之间的相互关系问题。我们在下面会看到，欧洲和俄国历次革命的经验是怎样具体地说明这个问题的。","language":"中文","translation":false},{"id":"state-2-28","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"现在我们再来看恩格斯的论述。","language":"中文","translation":false},{"id":"state-2-29","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":29,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"他指出，有时，如在北美某些地方，这种公共权力极其微小（这里指的是资本主义社会中罕见的例外，指的是帝国主义以前时期北美那些自由移民占多数的地方），但一般说来，它是在加强：","language":"中文","translation":false},{"id":"state-2-30","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":30,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“……随着国内阶级对立的尖锐化，随着彼此相邻的各国的扩大和它们人口的增加，公共权力就日益加强。就拿我们今天的欧洲来看吧，在这里，阶级斗争和侵略竞争已经使公共权力猛增到势将吞食整个社会甚至吞食国家的高度。……”［注：见《马克思恩格斯全集》第21卷第195页。——编者注］","language":"中文","translation":false},{"id":"state-2-31","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":31,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"这段话至迟是在上一世纪90年代初期写的。恩格斯最后的序言［注：指恩格斯的《家庭、私有制和国家的起源》一书德文第4版序言（见《马克思恩格斯全集》第22卷第246—259页）。——编者注］注明的日期是1891年6月16日。当时向帝国主义的转变，无论就托拉斯的完全统治或大银行的无限权力或大规模的殖民政策等等来说，在法国还是刚刚开始，在北美和德国更要差一些。此后，“侵略竞争”进了一大步，尤其是到了20世纪第二个10年的初期，世界已被这些“竞争的侵略者”，即进行掠夺的大国瓜分完了。从此陆海军备无限增长，1914—1917年由于英德两国争夺世界霸权即由于瓜分赃物而进行的掠夺战争，使贪婪的国家政权对社会一切力量的“吞食”快要酿成大灾大难了。","language":"中文","translation":false},{"id":"state-2-32","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":32,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯在1891年就已指出，“侵略竞争”是各个大国对外政策最重要的特征之一，但是在1914—1917年，即正是这个竞争加剧了许多倍而引起了帝国主义战争的时候，社会沙文主义的恶棍们却用“保卫祖国”、“保卫共和国和革命”等等词句来掩盖他们维护“自己”资产阶级强盗利益的行为！","language":"中文","translation":false},{"id":"state-2-33","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":33,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"3．国家是剥削被压迫阶级的工具","language":"中文","translation":false},{"id":"state-2-34","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":34,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"为了维持特殊的、站在社会之上的公共权力，就需要捐税和国债。","language":"中文","translation":false},{"id":"state-2-35","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":35,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯说：“……官吏既然掌握着公共权力和征税权，他们就作为社会机关而站在社会之上。从前人们对于氏族〈克兰〉社会的机关的那种自由的、自愿的尊敬，即使他们能够获得，也不能使他们满足了……”于是制定了官吏神圣不可侵犯的特别法律。“一个最微不足道的警察”却有比克兰代表更大的“权威”，然而，即使是文明国家掌握军权的首脑，也会对“不是用强迫手段获得”社会“尊敬”的克兰首领表示羡慕。［注：见《马克思恩格斯全集》第21卷第195页。——编者注］","language":"中文","translation":false},{"id":"state-2-36","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":36,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"这里提出了作为国家政权机关的官吏的特权地位问题。指出了这样一个基本问题：究竟什么东西使他们居于社会之上？我们在下面就会看到，这个理论问题在1871年如何被巴黎公社实际地解决了，而在1912年又如何被考茨基反动地抹杀了。","language":"中文","translation":false},{"id":"state-2-37","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":37,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“……由于国家是从控制阶级对立的需要中产生的，同时又是在这些阶级的冲突中产生的，所以，它照例是最强大的、在经济上占统治地位的阶级的国家，这个阶级借助于国家而在政治上也成为占统治地位的阶级，因而获得了镇压和剥削被压迫阶级的新手段。……”不仅古代国家和封建国家是剥削奴隶和农奴的机关，“现代的代议制的国家”也“是资本剥削雇佣劳动的工具。但也例外地有这样的时期，那时互相斗争的各阶级达到了这样势均力敌的地步，以致国家权力作为表面上的调停人而暂时得到了对于两个阶级的某种独立性。……”［注：同上，第196页。——编者注］17世纪和18世纪的专制君主制，法兰西第一帝国和第二帝国的波拿巴主义，德国的俾斯麦，都是如此。","language":"中文","translation":false},{"id":"state-2-38","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":38,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"我们还可以补充说，在开始迫害革命无产阶级以后，在苏维埃由于小资产阶级民主派的领导而已经软弱无力，资产阶级又还没有足够的力量来直接解散它的时候，共和制俄国的克伦斯基政府也是如此。","language":"中文","translation":false},{"id":"state-2-39","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":39,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯继续说，在民主共和国内，“财富是间接地但也是更可靠地运用它的权力的”，它所采用的第一个方法是“直接收买官吏”（美国），第二个方法是“政府和交易所结成联盟”（法国和美国）。［注：见《马克思恩格斯全集》第21卷第197页。——编者注］","language":"中文","translation":false},{"id":"state-2-40","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":40,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"目前，在任何民主共和国中，帝国主义和银行统治都把这两种维护和实现财富的无限权力的方法“发展”到了非常巧妙的地步。例如，在俄国实行民主共和制的头几个月里，也可以说是在社会革命党人和孟什维克这些“社会党人”同资产阶级在联合政府中联姻的蜜月期间，帕尔钦斯基先生暗中破坏，不愿意实施遏止资本家、制止他们进行掠夺和借军事订货盗窃国库的种种措施，而在帕尔钦斯基先生退出内阁以后（接替他的自然是同他一模一样的人），资本家“奖赏”给他年薪12万卢布的肥缺，这究竟是怎么一回事呢？是直接的收买，还是间接的收买？是政府同辛迪加结成联盟，还是“仅仅”是一种友谊关系？切尔诺夫、策列铁里、阿夫克森齐耶夫、斯柯别列夫之流究竟起着什么作用？他们是盗窃国库的百万富翁的“直接”同盟者，还是仅仅是间接的同盟者？","language":"中文","translation":false},{"id":"state-2-41","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":41,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“财富”的无限权力在民主共和制下更可靠，是因为它不依赖政治机构的某些缺陷，不依赖资本主义的不好的政治外壳。民主共和制是资本主义所能采用的最好的政治外壳，所以资本一掌握（通过帕尔钦斯基、切尔诺夫、策列铁里之流）这个最好的外壳，就能十分巩固十分可靠地确立自己的权力，以致在资产阶级民主共和国中，无论人员、无论机构、无论政党的任何更换，都不会使这个权力动摇。","language":"中文","translation":false},{"id":"state-2-42","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":42,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"还应该指出，恩格斯十分肯定地认为，普选制是资产阶级统治的工具。他显然是考虑到了德国社会民主党的长期经验，说普选制是","language":"中文","translation":false},{"id":"state-2-43","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":43,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“测量工人阶级成熟性的标尺。在现今的国家里，普选制不能而且永远不会提供更多的东西”［注：见《马克思恩格斯全集》第21卷第197页。——编者注］。","language":"中文","translation":false},{"id":"state-2-44","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":44,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"小资产阶级民主派，如我国的社会革命党人和孟什维克，以及他们的同胞兄弟西欧一切社会沙文主义者和机会主义者，却正是期待从普选制中得到“更多的东西”。他们自己相信而且要人民也相信这种荒谬的想法：普选制“在现今的国家里”能够真正体现大多数劳动者的意志，并保证实现这种意志。","language":"中文","translation":false},{"id":"state-2-45","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":45,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"我们在这里只能指出这种荒谬的想法，只能指出，恩格斯这个十分明白、准确而具体的说明，经常在“正式的”（即机会主义的）社会党的宣传鼓动中遭到歪曲。至于恩格斯在这里所唾弃的这种想法的全部荒谬性，我们在下面谈到马克思和恩格斯对“现今的”国家的看法时还会详细地加以阐明。","language":"中文","translation":false},{"id":"state-2-46","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":46,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯在他那部流传最广的著作中，把自己的看法总结如下：","language":"中文","translation":false},{"id":"state-2-47","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":47,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“所以，国家并不是从来就有的。曾经有过不需要国家、而且根本不知国家和国家权力为何物的社会。在经济发展到一定阶段而必然使社会分裂为阶级时，国家就由于这种分裂而成为必要了。现在我们正在以迅速的步伐接近这样的生产发展阶段，在这个阶段上，这些阶级的存在不仅不再必要，而且成了生产的直接障碍。阶级不可避免地要消失，正如它们从前不可避免地产生一样。随着阶级的消失，国家也不可避免地要消失。在自由平等的生产者联合体的基础上按新方式组织生产的社会，将把全部国家机器放到那时它应该去的地方，即放到古物陈列馆去，同纺车和青铜斧陈列在一起。”［注：见《马克思恩格斯全集》第21卷第197—198页。——编者注］","language":"中文","translation":false},{"id":"state-2-48","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":48,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"这一段引文在现代社会民主党的宣传鼓动书刊中很少遇到，即使遇到，这种引用也多半好象是对神像鞠一下躬，也就是为了例行公事式地对恩格斯表示一下尊敬，而丝毫不去考虑，先要经过多么广泛而深刻的革命，才能“把全部国家机器放到古物陈列馆去”。他们甚至往往不懂恩格斯说的国家机器究竟是什么。","language":"中文","translation":false},{"id":"state-2-49","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":49,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"4．国家“自行消亡”和暴力革命","language":"中文","translation":false},{"id":"state-2-50","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":50,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"恩格斯所说的国家“自行消亡”这句话是这样著名，这样经常地被人引证，又这样清楚地表明了通常那种把马克思主义篡改为机会主义的手法的实质，以致对它必须详细地考察一下。现在我们把谈到这句话的整段论述援引如下：","language":"中文","translation":false},{"id":"state-2-51","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":51,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“无产阶级将取得国家政权，并且首先把生产资料变为国家财产。但是，这样一来它就消灭了作为无产阶级的自身，消灭了一切阶级差别和阶级对立，也消灭了作为国家的国家。到目前为止还在阶级对立中运动着的社会，都需要有国家，即需要一个剥削阶级的组织，以便维持它的外部的生产条件，特别是用暴力把被剥削阶级控制在当时的生产方式所决定的那些压迫条件下（奴隶制、农奴制或依附农制、雇佣劳动制）。国家是整个社会的正式代表，是社会在一个有形的组织中的集中表现，但是，说国家是这样的，这仅仅是说，它是当时独自代表整个社会的那个阶级的国家：在古代是占有奴隶的公民的国家，在中世纪是封建贵族的国家，在我们的时代是资产阶级的国家。当国家终于真正成为整个社会的代表时，它就使自己成为多余的了。当不再有需要加以镇压的社会阶级的时候，当阶级统治和根源于至今的生产无政府状态的生存斗争已被消除，而由此产生的冲突和极端行动也随着被消除了的时候，就不再有什么需要镇压了，也就不再需要国家这种实行镇压的特殊力量了。国家真正作为整个社会的代表所采取的第一个行动，即以社会的名义占有生产资料，同时也是它作为国家所采取的最后一个独立行动。那时，国家政权对社会关系的干预将先后在各个领域中成为多余的事情而自行停止下来。那时，对人的统治将由对物的管理和对生产过程的领导所代替。国家不是‘被废除’的，它是自行消亡的。应当以此来衡量‘自由的人民国家’这个用语，这个用语在鼓动的意义上暂时有存在的理由，但归根到底是没有科学根据的；同时也应当以此来衡量所谓无政府主义者提出的在一天之内废除国家的要求。”（《反杜林论（欧根·杜林先生在科学中实行的变革）》德文第3版第301—303页）［注：见《马克思恩格斯全集》第20卷第305—306页。——编者注］","language":"中文","translation":false},{"id":"state-2-52","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":52,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"我们可以确有把握地说，在恩格斯这一段思想极其丰富的论述中，被现代社会党的社会主义思想实际接受的只有这样一点：和无政府主义的国家“废除”说不同，按马克思的观点，国家是“自行消亡”的。这样来削剪马克思主义，无异是把马克思主义变成机会主义，因为这样来“解释”，就只会留下一个模糊的观念，似乎变化就是缓慢的、平稳的、逐渐的，似乎没有飞跃和风暴，没有革命。对国家“自行消亡”的普遍的、流行的、大众化的（如果能这样说的话）理解，无疑意味着回避革命，甚至是否定革命。","language":"中文","translation":false},{"id":"state-2-53","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":53,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"实际上，这样的“解释”是对马克思主义最粗暴的、仅仅有利于资产阶级的歪曲，所以产生这种歪曲，从理论上说，是由于忘记了我们上面完整地摘引的恩格斯的“总结性”论述中就已指出的那些极重要的情况和想法。","language":"中文","translation":false},{"id":"state-2-54","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":54,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"第一，恩格斯在这段论述中一开始就说，无产阶级将取得国家政权，“这样一来也消灭了作为国家的国家”。这是什么意思，人们是“照例不”思索的。通常不是完全忽略这一点，就是认为这是恩格斯的一种“黑格尔主义的毛病”。其实这句话扼要地表明了最伟大的一次无产阶级革命的经验，即1871年巴黎公社的经验，关于这一点，我们在下面还要详细地加以论述。实际上恩格斯在这里所讲的是以无产阶级革命来“消灭”资产阶级的国家，而他讲的自行消亡是指社会主义革命以后无产阶级国家制度残余。按恩格斯的看法，资产阶级国家不是“自行消亡”的，而是由无产阶级在革命中来“消灭”的。在这个革命以后，自行消亡的是无产阶级的国家或半国家。","language":"中文","translation":false},{"id":"state-2-55","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":55,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"第二，国家是“实行镇压的特殊力量”。恩格斯这个出色的极其深刻的定义在这里说得十分清楚。从这个定义可以得出这样的结论：资产阶级对无产阶级，即一小撮富人对千百万劳动者“实行镇压的特殊力量”，应该由无产阶级对资产阶级“实行镇压的特殊力量”（无产阶级专政）来代替。这就是“消灭作为国家的国家”。这就是以社会的名义占有生产资料的“行动”。显然，以一种（无产阶级的）“特殊力量”来代替另一种（资产阶级的）“特殊力量”，这样一种更替是决不能通过“自行消亡”来实现的。","language":"中文","translation":false},{"id":"state-2-56","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":56,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"第三，恩格斯所说的“自行消亡”，甚至更突出更鲜明地说的“自行停止”，是十分明确而肯定地指“国家以整个社会的名义占有生产资料”以后即社会主义革命以后的时期。我们大家都知道，这时“国家”的政治形式是最完全的民主。但是那些无耻地歪曲马克思主义的机会主义者，却没有一个人想到恩格斯在这里所说的就是民主的“自行停止”和“自行消亡”。乍看起来，这似乎是很奇怪的。但是，只有那些没有想到民主也是国家、因而在国家消失时民主也会消失的人，才会觉得这是“不可理解”的。资产阶级的国家只有革命才能“消灭”。国家本身，就是说最完全的民主，只能“自行消亡”。","language":"中文","translation":false},{"id":"state-2-57","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":57,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"第四，恩格斯在提出“国家自行消亡”这个著名的原理以后，立刻就具体地说明这个原理是既反对机会主义者又反对无政府主义者的。而且恩格斯放在首位的，是从“国家自行消亡”这个原理中得出的反对机会主义者的结论。","language":"中文","translation":false},{"id":"state-2-58","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":58,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"可以担保，在1万个读过或听过国家“自行消亡”论的人中，有9990人完全不知道或不记得恩格斯从这个原理中得出的结论不仅是反对无政府主义者的。其余的10个人中可能有9个人不知道什么是“自由的人民国家”，不知道为什么反对这个口号就是反对机会主义者。历史竟然被写成这样！伟大的革命学说竟然这样被人不知不觉地篡改成了流行的庸俗观念。反对无政府主义者的结论被千百次地重复，庸俗化，极其简单地灌到头脑中去，变成固执的偏见。而反对机会主义者的结论，却被抹杀和“忘记了”！","language":"中文","translation":false},{"id":"state-2-59","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":59,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“自由的人民国家”是70年代德国社会民主党人的纲领性要求和流行口号。这个口号除了对于民主概念的市侩的、夸张的描写，没有任何政治内容。由于当时是在合法地用这个口号暗示民主共和国，恩格斯也就从鼓动的观点上同意“暂时”替这个口号“辩护”。但这个口号是机会主义的，因为它不仅起了粉饰资产阶级民主的作用，而且表现出不懂得社会主义对任何国家的批评。我们赞成民主共和国，因为这是在资本主义制度下对无产阶级最有利的国家形式。但是，我们决不应该忘记，即使在最民主的资产阶级共和国里，人民仍然摆脱不了当雇佣奴隶的命运。其次，任何国家都是对被压迫阶级“实行镇压的特殊力量”。因此任何国家都不是自由的，都不是人民的。在70年代，马克思和恩格斯一再向他们党内的同志解释这一点。[5]","language":"中文","translation":false},{"id":"state-2-60","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":60,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"第五，在恩格斯这同一本著作中，除了大家记得的关于国家自行消亡的论述，还有关于暴力革命意义的论述。恩格斯从历史上对于暴力革命的作用所作的评述变成了对暴力革命的真正的颂扬。但是，“谁都不记得”这一点，这个思想的意义在现代社会党内是照例不谈、甚至照例不想的，这些思想在对群众进行的日常宣传鼓动中也不占任何地位。其实，这些思想同国家“自行消亡”论是紧紧联在一起的，是联成一个严密的整体的。","language":"中文","translation":false},{"id":"state-2-61","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":61,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"“……暴力在历史中还起着另一种作用〈除作恶以外〉，革命的作用；暴力，用马克思的话说，是每一个孕育着新社会的旧社会的助产婆［注：参看《马克思恩格斯全集》第23卷第819页。——编者注］；它是社会运动借以为自己开辟道路并摧毁僵化的垂死的政治形式的工具——关于这些，杜林先生一个字也没有提到。他只是带着叹息和呻吟的口吻承认这样一种可能性：为了推翻进行剥削的经济，也许需要暴力，这很遗憾！因为暴力的任何应用都会使应用暴力的人道德堕落。尽管每一次革命的胜利都引起了道德上和精神上的巨大高涨，他还要这么说！而且这话是在德国说的，在那里，人民可能被迫进行的暴力冲突至少有一个好处，即扫除三十年战争[6]的屈辱在民族意识中造成的奴才气。而这种枯燥的、干瘪的、软弱无力的传教士的思维方式，竟要强迫历史上最革命的政党来接受！”（德文第3版第193页；第2编第4章末）［注：见《马克思恩格斯全集》第20卷第200页。——编者注］","language":"中文","translation":false},{"id":"state-2-62","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":62,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"怎样才能把恩格斯从1878年起至1894年即快到他逝世的时候为止，一再向德国社会民主党人提出的这一颂扬暴力革命的论点，同国家“自行消亡”的理论结合在一个学说里呢？","language":"中文","translation":false},{"id":"state-2-63","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":63,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"人们通常是借助折衷主义把这两者结合起来，他们随心所欲（或者为了讨好当权者），无原则地或诡辩式地时而抽出这个论述时而抽出那个论述，而且在100次中有99次（如果不是更多的话）正是把“自行消亡”论摆在首位。用折衷主义代替辩证法，这就是目前正式的社会民主党书刊中在对待马克思主义的态度上最常见最普遍的现象。这种做法，自然并不新鲜，甚至在希腊古典哲学史上也是可以见到的。把马克思主义篡改为机会主义的时候，用折衷主义冒充辩证法最容易欺骗群众，能使人感到一种似是而非的满足，似乎考虑到了过程的一切方面、发展的一切趋势、一切相互矛盾的影响等等，但实际上并没有对社会发展过程作出任何完整的革命的解释。","language":"中文","translation":false},{"id":"state-2-64","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":64,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"我们在前面已经说过，在下面还要更详尽地说明，马克思和恩格斯关于暴力革命不可避免的学说是针对资产阶级国家说的。资产阶级国家由无产阶级国家（无产阶级专政）代替，不能通过“自行消亡”，根据一般规律，只能通过暴力革命。恩格斯对暴力革命的颂扬同马克思的屡次声明完全符合（我们可以回忆一下，《哲学的贫困》和《共产党宣言》这两部著作的结尾部分［注：见《马克思恩格斯全集》第4卷第197—198页和第503—504页。——编者注］，曾自豪地公开声明暴力革命不可避免；我们还可以回忆一下，约在30年以后，马克思在1875年批判哥达纲领[7]的时候，曾无情地抨击了这个纲领的机会主义），这种颂扬决不是“过头话”，决不是夸张，也决不是论战伎俩。必须系统地教育群众这样来认识而且正是这样来认识暴力革命，这就是马克思和恩格斯全部学说的基础。现在占统治地位的社会沙文主义流派和考茨基主义流派对马克思和恩格斯学说的背叛，最突出地表现在这两个流派都把这方面的宣传和鼓动忘记了。","language":"中文","translation":false},{"id":"state-2-65","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":65,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"无产阶级国家代替资产阶级国家，非通过暴力革命不可。无产阶级国家的消灭，即任何国家的消灭，只能通过“自行消亡”。","language":"中文","translation":false},{"id":"state-2-66","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":66,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"马克思和恩格斯在研究每一个革命形势，分析每一次革命的经验教训时，都详细而具体地发展了他们的这些观点。我们现在就来谈谈他们学说中这个无疑是最重要的部分。","language":"中文","translation":false},{"id":"state-2-67","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":67,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"[3] 社会革命党人是俄国最大的小资产阶级政党社会革命党的成员。该党是1901年底—1902年初由一些民粹派团体联合而成的。社会革命党人否认无产阶级和农民之间的阶级差别，抹杀农民内部的矛盾，否认无产阶级在资产阶级民主革命中的领导作用。在策略方面，社会革命党人采用了社会民主党人进行群众性鼓动的方法，但主要斗争方法还是搞个人恐怖。在第一次世界大战期间，社会革命党的大多数领导人采取了社会沙文主义的立场。","language":"中文","translation":false},{"id":"state-2-68","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":68,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"1917年二月革命后，随着广大的小资产阶级群众参加政治生活，社会革命党的影响扩大，党员人数激增（1917年5月已达50万）。社会革命党人和孟什维克在苏维埃中，在土地委员会中都占多数。社会革命党中央实行妥协主义和阶级调和的政策，积极支持资产阶级临时政府，党的首领亚·费·克伦斯基、尼·德·阿夫克森齐耶夫、维·米·切尔诺夫、谢·列·马斯洛夫参加了临时政府。社会革命党拖延土地问题的解决，社会革命党人部长曾派讨伐队镇压夺取地主土地的农民。1917年七月事变时期，社会革命党公开转向资产阶级方面。社会革命党中央的妥协政策造成党的分裂，左翼于1917年12月组成了一个独立政党——左派社会革命党。","language":"中文","translation":false},{"id":"state-2-69","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":69,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"1917年十月革命后，社会革命党人（右派和中派）公开进行反苏维埃的活动，建立地下组织，1918年6月被开除出全俄中央执行委员会。1918—1920年国内战争时期，他们进行反对苏维埃政权的武装斗争，对共产党和苏维埃国家的领导人实行个人恐怖。社会革命党人推行所谓“第三种力量”的蛊惑政策，在1918年充当了小资产阶级反革命活动的主要组织者。内战结束后，社会革命党人重新成了俄国国内反革命势力的领导。他们提出“不要共产党人参加的苏维埃”的口号，组织了一系列的叛乱。这些叛乱被平定后，1922年社会革命党彻底瓦解。——6。","language":"中文","translation":false},{"id":"state-2-70","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":70,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"[4] 克兰是克尔特民族（主要是爱尔兰人、苏格兰人和威尔士人）对氏族的称呼。——7。","language":"中文","translation":false},{"id":"state-2-71","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":71,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"[5] 指马克思的《哥达纲领批判》（第4节）、恩格斯的《反杜林论》以及恩格斯1875年3月18—28日给奥·倍倍尔的信（参看《马克思恩格斯全集》第19卷第29—35页、第20卷第305页和第19卷第3—10页）。——18。","language":"中文","translation":false},{"id":"state-2-72","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":72,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"[6] 三十年战争指1618—1648年以德意志为主要战场的欧洲国际性战争。这场战争起因于天主教与新教之间的矛盾以及欧洲各国的政治冲突和领土争夺。参加战争的一方是哈布斯堡同盟，包括奥地利和西班牙的哈布斯堡王朝、德意志天主教诸侯，它们得到教皇和波兰的支持。另一方是反哈布斯堡联盟，包括德意志新教诸侯、法国、瑞典、丹麦，它们得到荷兰、英国、俄国的支持。战争从捷克起义反对哈布斯堡王朝的统治开始，几经反复，以哈布斯堡同盟失败告终。根据1648年签订的威斯特伐利亚和约，瑞典、法国等得到了德意志大片土地和巨额赔款。经过这场战争，德意志遭到严重破坏，在政治上更加处于四分五裂的状态。——19。","language":"中文","translation":false},{"id":"state-2-73","author":"列宁","title":"国家与革命","location":"第一章 阶级社会和国家","page":2,"paragraph":73,"url":"https://www.marxists.org/chinese/lenin/191708-09/02.htm","text":"[7] 哥达纲领即德国社会主义工人党纲领。这个纲领是在德国两个社会党——爱森纳赫派（1869年成立的社会民主工党）和拉萨尔派（1863年成立的全德工人联合会）——于1875年5月在哥达举行的合并代表大会上通过的。哥达纲领比爱森纳赫派的纲领倒退了一步，它是爱森纳赫派不惜一切代价追求合并、向拉萨尔派作了无原则的妥协和让步的产物。纲领宣布党的目的是解放工人阶级和建立社会主义社会，但是回避了社会主义革命和无产阶级夺取政权的问题，并写进了一系列拉萨尔主义的论点，如所谓“铁的工资规律”，所谓对无产阶级说来其他一切阶级都是反动的一帮，工人阶级只有通过普选权和由国家帮助建立生产合作社才能达到自己的目的，应当用一切合法手段建立所谓”自由国家”等。马克思和恩格斯对哥达纲领的草案作了彻底的批判（见《马克思恩格斯全集》第19卷第3—35页），但是他们的意见没有被认真考虑。哥达纲领于1891年被爱尔福特纲领代替。——20。","language":"中文","translation":false},{"id":"state-3-1","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-3-2","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"第二章 国家与革命。1848—1851年的经验","language":"中文","translation":false},{"id":"state-3-3","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"3．1852年马克思对问题的提法","language":"中文","translation":false},{"id":"state-3-4","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"成熟的马克思主义的头两部著作《哲学的贫困》和《共产党宣言》，恰巧是在1848年革命前夜写成的。由于这种情况，这两部著作除了叙述马克思主义的一般原理，还在一定程度上反映了当时具体的革命形势。因此，我们来研究一下这两部著作的作者从1848—1851年革命的经验作出结论以前不久关于国家问题的言论，也许更为恰当。","language":"中文","translation":false},{"id":"state-3-5","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"马克思在《哲学的贫困》中写道：“……工人阶级在发展进程中将创造一个消除了阶级和阶级对立的联合体来代替旧的资产阶级社会；从此再不会有任何原来意义的政权了，因为政权正是资产阶级社会内部阶级对立的正式表现。”（1885年德文版第182页）［注：见《马克思恩格斯选集》第1卷人民出版社1972年版第160页。——编者注］","language":"中文","translation":false},{"id":"state-3-6","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"拿马克思和恩格斯在几个月以后（1847年11月）写的《共产党宣言》中的下面的论述，同这一段关于国家在阶级消灭之后消失的思想的一般论述对照一下，是颇有教益的：","language":"中文","translation":false},{"id":"state-3-7","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"“……在叙述无产阶级发展的最一般的阶段的时候，我们循序探讨了现存社会内部或多或少隐蔽着的国内战争，直到这个战争爆发为公开的革命，无产阶级用暴力推翻资产阶级而建立自己的统治……","language":"中文","translation":false},{"id":"state-3-8","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"……前面我们已经看到，工人革命的第一步就是使无产阶级转化成〈直译是上升为〉统治阶级，争得民主。","language":"中文","translation":false},{"id":"state-3-9","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"无产阶级将利用自己的政治统治，一步一步地夺取资产阶级的全部资本，把一切生产工具集中在国家即组织成为统治阶级的无产阶级手里，并且尽可能快地增加生产力的总量。”（1906年德文第7版第31页和第37页）［注：见《马克思恩格斯选集》第1卷人民出版社1972年版第263页和第272页。——编者注］","language":"中文","translation":false},{"id":"state-3-10","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"在这里我们看到马克思主义在国家问题上一个最卓越最重要的思想即“无产阶级专政”（马克思和恩格斯在巴黎公社以后开始这样说）[8]这个思想的表述，其次我们还看到给国家下的一个非常引人注意的定义，这个定义也属于马克思主义中“被忘记的言论”：“国家即组织成为统治阶级的无产阶级。”","language":"中文","translation":false},{"id":"state-3-11","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"国家的这个定义，在正式社会民主党的占支配地位的宣传鼓动书刊中不仅从来没有解释过，而且恰巧被人忘记了，因为它同改良主义是根本不相容的，它直接打击了“民主的和平发展”这种常见的机会主义偏见和市侩的幻想。","language":"中文","translation":false},{"id":"state-3-12","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"无产阶级需要国家，——一切机会主义者，社会沙文主义者和考茨基主义者，都这样重复，硬说马克思的学说就是如此，但是“忘记”补充：马克思认为，第一，无产阶级所需要的只是逐渐消亡的国家，即组织得能立刻开始消亡而且不能不消亡的国家；第二，劳动者所需要的“国家”，“即组织成为统治阶级的无产阶级”。","language":"中文","translation":false},{"id":"state-3-13","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"国家是特殊的强力组织，是镇压某一个阶级的暴力组织。无产阶级要镇压的究竟是哪一个阶级呢？当然只是剥削阶级，即资产阶级。劳动者需要国家只是为了镇压剥削者的反抗，而能够领导和实行这种镇压的只有无产阶级，因为无产阶级是唯一彻底革命的阶级，是唯一能够团结一切被剥削劳动者对资产阶级进行斗争、把资产阶级完全铲除的阶级。","language":"中文","translation":false},{"id":"state-3-14","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"剥削阶级需要政治统治是为了维持剥削，也就是为了极少数人的私利，去反对绝大多数人。被剥削阶级需要政治统治是为了彻底消灭一切剥削，也就是为了绝大多数人的利益，去反对极少数的现代奴隶主——地主和资本家。","language":"中文","translation":false},{"id":"state-3-15","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"小资产阶级民主派，这些用阶级妥协的幻想来代替阶级斗争的假社会主义者，对社会主义改造也想入非非，他们不是把改造想象为推翻剥削阶级的统治，而是想象为少数和平地服从那已经理解到本身任务的多数。这种小资产阶级空想同认为国家是超阶级的观点有密切的联系，它在实践中导致出卖劳动阶级的利益，法国1848年革命和1871年革命的历史就表明了这一点，19世纪末和20世纪初英、法、意和其他国家的“社会党人”参加资产阶级内阁的经验也表明了这一点。","language":"中文","translation":false},{"id":"state-3-16","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"马克思一生都在反对这种小资产阶级社会主义，即目前在俄国由社会革命党和孟什维克党复活起来的这种小资产阶级社会主义。马克思把阶级斗争学说一直贯彻到政权学说、国家学说之中。","language":"中文","translation":false},{"id":"state-3-17","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"只有无产阶级才能推翻资产阶级的统治，因为无产阶级是一个特殊阶级，它的生存的经济条件为它推翻资产阶级的统治作了准备，使它有可能、有力量达到这个目的。资产阶级在分离和分散农民及一切小资产阶级阶层的同时，却使无产阶级团结、联合和组织起来。只有无产阶级，由于它在大生产中的经济作用，才能成为一切被剥削劳动群众的领袖，这些被剥削劳动群众受资产阶级的剥削、压迫和摧残比起无产阶级来往往有过之而无不及，可是他们不能为自己的解放独立地进行斗争。","language":"中文","translation":false},{"id":"state-3-18","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"阶级斗争学说经马克思运用到国家和社会主义革命问题上，必然导致承认无产阶级的政治统治，无产阶级的专政，即不与任何人分掌而直接依靠群众武装力量的政权。只有使无产阶级转化成统治阶级，从而能把资产阶级必然要进行的拼死反抗镇压下去，并组织一切被剥削劳动群众去建立新的经济结构，才能推翻资产阶级。","language":"中文","translation":false},{"id":"state-3-19","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"无产阶级需要国家政权，中央集权的强力组织，暴力组织，既是为了镇压剥削者的反抗，也是为了领导广大民众即农民、小资产阶级和半无产者来“调整”社会主义经济。","language":"中文","translation":false},{"id":"state-3-20","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"马克思主义教育工人的党，也就是教育无产阶级的先锋队，使它能够夺取政权并引导全体人民走向社会主义，指导并组织新制度，成为所有被剥削劳动者在不要资产阶级并反对资产阶级而建设自己社会生活的事业中的导师、领导者和领袖。反之，现在占统治地位的机会主义却把工人的党教育成为一群脱离群众而代表工资优厚的工人的人物，只图在资本主义制度下“苟且偷安”，为了一碗红豆汤而出卖自己的长子权[9]，也就是放弃那领导人民反对资产阶级的革命领袖作用。","language":"中文","translation":false},{"id":"state-3-21","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"“国家即组织成为统治阶级的无产阶级”，——马克思的这个理论同他关于无产阶级在历史上的革命作用的全部学说，有不可分割的联系。这种作用的最高表现就是无产阶级实行专政，无产阶级实行政治统治。","language":"中文","translation":false},{"id":"state-3-22","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"既然无产阶级需要国家这样一个反对资产阶级的特殊暴力组织，那么自然就会得出一个结论：不预先消灭和破坏资产阶级为自己建立的国家机器，根本就不可能建立这样一个组织！在《共产党宣言》中已接近于得出这个结论，马克思在总结1848—1851年革命的经验时也就谈到了这个结论。","language":"中文","translation":false},{"id":"state-3-23","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"关于我们感到兴趣的国家问题，马克思在《路易·波拿巴的雾月十八日》一书中总结1848—1851年的革命时写道：","language":"中文","translation":false},{"id":"state-3-24","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"“……然而革命是彻底的。它还处在通过涤罪所[10]的历程中。它在有条不紊地完成自己的事业。1851年12月2日〈路易·波拿巴政变的日子〉以前，它已经完成了它的前一半预备工作，现在它在完成另一半。它先使议会权力臻于完备，为的是能够推翻这个权力。现在，当它已达到这一步时，它就来使行政权力臻于完备，使它表现为最纯粹的形式，使它孤立，使它成为和自己对立的唯一的对象，以便集中自己的一切破坏力量来反对这个权力〈黑体是我们用的〉。而当革命完成自己这后一半准备工作的时候，欧洲就会站起来欢呼说：掘得好，老田鼠！[11]","language":"中文","translation":false},{"id":"state-3-25","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"这个行政权力有庞大的官僚和军事组织，有复杂而巧妙的国家机器，有50万人的官吏队伍和50万人的军队，——这个俨如密网一般缠住法国社会全身并堵塞其一切毛孔的可怕的寄生机体，是在专制君主制时代，在封建制度崩溃时期产生的，同时这个寄生机体又加速了封建制度的崩溃。”第一次法国革命发展了中央集权，“但是它同时也就扩大了政府权力的容量、职能和帮手的数目。拿破仑完成了这个国家机器”。正统王朝和七月王朝“并没有增添什么新的东西，不过是扩大了分工……","language":"中文","translation":false},{"id":"state-3-26","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"……最后，议会制共和国在它反对革命的斗争中，除采用高压手段而外，还不得不加强政府权力的工具和集中化。一切变革都是使这个机器更加完备，而不是把它摧毁〈黑体和着重号是我们用的〉。那些争夺统治权而相继更替的政党，都把这个庞大国家建筑物的夺得视为自己胜利的主要战利品。”（《路易·波拿巴的雾月十八日》1907年汉堡第4版第98—99页）［注：见《马克思恩格斯选集》第1卷人民出版社1972年版第691—692页。——编者注］","language":"中文","translation":false},{"id":"state-3-27","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"马克思主义在这一段精彩的论述里，与《共产党宣言》相比，向前迈进了一大步。在那里，国家问题还提得非常抽象，只用了最一般的概念和说法。在这里，问题提得具体了，并且作出了非常准确、明确、实际而具体的结论：过去一切革命都是使国家机器更加完备，而这个机器是必须打碎，必须摧毁的。","language":"中文","translation":false},{"id":"state-3-28","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"这个结论是马克思主义国家学说中主要的基本的东西。正是这个基本的东西，不仅被占统治地位的正式社会民主党完全忘记了，而且被第二国际最著名的理论家卡·考茨基公然歪曲了（这点我们在下面就会看到）。","language":"中文","translation":false},{"id":"state-3-29","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":29,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"在《共产党宣言》中对历史作了一般的总结，使人们认识到国家是阶级统治的机关，还使人们得出这样一个必然的结论：无产阶级如果不先夺取政权，不取得政治统治，不把国家变为“组织成为统治阶级的无产阶级”，就不能推翻资产阶级；这个无产阶级国家在它取得胜利以后就会立刻开始消亡，因为在没有阶级矛盾的社会里，国家是不需要的，也是不可能存在的。在这里还没有提出究竟应当怎样（从历史发展的观点来看）以无产阶级国家来代替资产阶级国家的问题。","language":"中文","translation":false},{"id":"state-3-30","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":30,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"马克思在1852年提出并加以解决的正是这个问题。马克思忠于自己的辩证唯物主义哲学，他以1848—1851伟大革命年代的历史经验作为依据。马克思的学说在这里也像其他任何时候一样，是用深刻的哲学世界观和丰富的历史知识阐明的经验总结。","language":"中文","translation":false},{"id":"state-3-31","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":31,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"国家问题现在提得很具体：资产阶级的国家，资产阶级统治所需要的国家机器在历史上是怎样产生的？在历次资产阶级革命进程中和面对着各被压迫阶级的独立行动，国家机器如何改变，如何演变？无产阶级在对待这个国家机器方面的任务是什么？","language":"中文","translation":false},{"id":"state-3-32","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":32,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"资产阶级社会所特有的中央集权的国家政权，产生于专制制度崩溃的时代。最能表明这个国家机器特征的有两种机构，即官吏和常备军。马克思和恩格斯的著作中屡次谈到，这两种机构恰巧同资产阶级有千丝万缕的联系。每个工人的经验都非常清楚非常有力地说明了这种联系。工人阶级是根据亲身的体验来学习领会这种联系的，正因为这样，工人阶级很容易懂得并且很深刻地理解这种联系不可避免的道理，而小资产阶级民主派不是无知地、轻率地否认这个道理，便是更轻率地加以“一般地”承认而忘记作出相应的实际结论。","language":"中文","translation":false},{"id":"state-3-33","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":33,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"官吏和常备军是资产阶级社会身上的“寄生物”，是使这个社会分裂的内部矛盾所产生的寄生物，而且正是“堵塞”生命的毛孔的寄生物。目前在正式的社会民主党内占统治地位的考茨基机会主义，认为把国家看做寄生机体是无政府主义独具的特性。当然，这样来歪曲马克思主义，对于那些空前地玷污社会主义、竟把“保卫祖国”的概念应用于帝国主义战争来替这个战争辩护和粉饰的市侩，是大有好处的，然而这毕竟是无可置疑的歪曲。","language":"中文","translation":false},{"id":"state-3-34","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":34,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"经过从封建制度崩溃以来欧洲所发生的为数很多的各次资产阶级革命，这个官吏和军事机构逐渐发展、完备和巩固起来。还必须指出，小资产阶级被吸引到大资产阶级方面去并受它支配，在很大程度上就是通过这个机构，这个机构给农民、小手工业者、商人等等的上层分子以比较舒适、安闲和荣耀的职位，使这些职位的占有者居于人民之上。看一看俄国在 1917年2月27日以后这半年中发生的情况吧：以前优先给予黑帮分子[12]的官吏位置，现已成为立宪民主党人[13]、孟什维克和社会革命党人猎取的对象。实际上他们根本不想进行任何认真的改革，力图把这些改革推迟“到立宪会议召集的时候”，而且又把立宪会议慢吞吞地推迟到战争结束再举行！至于瓜分战利品，攫取部长、副部长、总督等等职位，却没有延期，没有等待任何立宪会议！玩弄联合组阁的把戏，其实不过是全国上下一切中央和地方管理机关中瓜分和重新瓜分“战利品”的一种表现。各种改革都延期了，官吏职位已经瓜分了，瓜分方面的“错误”也由几次重新瓜分纠正了，——这无疑就是1917年2月27日—8月27日这半年的总结，客观的总结。","language":"中文","translation":false},{"id":"state-3-35","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":35,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"但是在各资产阶级政党和小资产阶级政党之间（拿俄国的例子来讲，就是在立宪民主党、社会革命党和孟什维克之间）“重新瓜分”官吏机构的次数愈多，各被压迫阶级，以无产阶级为首，就会愈清楚地认识到自己同整个资产阶级社会不可调和的敌对性。因此，一切资产阶级政党，甚至包括最民主的和“革命民主的”政党，都必须加强高压手段来对付革命的无产阶级，巩固高压机构，也就是巩固原有的国家机器。这样的事变进程迫使革命“集中自己的一切破坏力量”去反对国家政权，迫使革命提出这样的任务：不是去改善国家机器，而是破坏它、消灭它。","language":"中文","translation":false},{"id":"state-3-36","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":36,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"这样提出任务，不是根据逻辑的推论，而是根据事变的实际发展，根据1848—1851年的生动经验。马克思在1852年还没有具体提出用什么东西来代替这个必须消灭的国家机器的问题，从这里可以看出，马克思是多么严格地以实际的历史经验为依据。那时在这个问题上，经验还没有提供材料，后来在1871年，历史才把这个问题提到日程上来。在1852年，要以观察自然历史那样的精确性下断语，还只能说，无产阶级革命已面临“集中自己的一切破坏力量”来反对国家政权的任务，即“摧毁”国家机器的任务。","language":"中文","translation":false},{"id":"state-3-37","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":37,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"这里可能会发生这样的问题：把马克思的经验、观察和结论加以推广，用到比1848—1851年这三年法国历史更广阔的范围上去是否正确呢？为了分析这个问题，我们先重温一下恩格斯的一段话，然后再来研究实际材料。","language":"中文","translation":false},{"id":"state-3-38","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":38,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"恩格斯在《雾月十八日》第3版序言里写道：“……法国是这样一个国家，在那里历史上的阶级斗争，比起其他各国来每一次都达到更加彻底的结局；因而阶级斗争借以进行、阶级斗争的结果借以表现出来的变换不已的政治形式，在那里也表现得最为鲜明。法国在中世纪是封建制度的中心，从文艺复兴时代起是统一等级君主制的典型国家，它在大革命时期粉碎了封建制度，建立了纯粹的资产阶级统治，这种统治所具有的典型性是欧洲任何其他国家所没有的。而奋起向上的无产阶级反对占统治地位的资产阶级的斗争在这里也以其他各国所没有的尖锐形式表现出来。”（1907年版第4页）［注：见《马克思恩格斯选集》第1卷人民出版社1972年版第601—602页。 ——编者注］","language":"中文","translation":false},{"id":"state-3-39","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":39,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"最后一句评语已经过时了，因为从1871年起，法国无产阶级的革命斗争就停顿了，虽然这种停顿（无论它会持续多久）丝毫不排除法国在将来的无产阶级革命中有可能成为使阶级斗争达到彻底的结局的典型国家。","language":"中文","translation":false},{"id":"state-3-40","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":40,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"现在我们来概括地看一看19世纪末20世纪初各先进国家的历史。我们可以看到，这里更缓慢地、更多样地、范围更广阔得多地进行着那同一个过程：一方面，无论在共和制的国家（法国、美国、瑞士），还是在君主制的国家（英国、一定程度上的德国、意大利、斯堪的纳维亚国家等），都逐渐形成“议会权力”；另一方面，在不改变资产阶级制度基础的情况下，各资产阶级政党和小资产阶级政党瓜分着和重新瓜分着官吏职位这种“战利品”，为争夺政权进行着斗争；最后，“行政权力”，它的官吏和军事机构，日益完备和巩固起来。","language":"中文","translation":false},{"id":"state-3-41","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":41,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"毫无疑问，这是一般资本主义国家现代整个演变过程的共同特征。法国在1848—1851年这3年内迅速地、鲜明地、集中地显示出来的，就是整个资本主义世界所特有的那种发展过程。","language":"中文","translation":false},{"id":"state-3-42","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":42,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"特别是帝国主义，即银行资本时代，资本主义大垄断组织的时代，垄断资本主义转变为国家垄断资本主义的时代表明，无论在君主制的国家，还是在最自由的共和制的国家，由于要加强高压手段来对付无产阶级，“国家机器”就大大强化了，它的官吏和军事机构就空前膨胀起来了。","language":"中文","translation":false},{"id":"state-3-43","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":43,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"现在，全世界的历史无疑正在较之1852年广阔得无比的范围内，把无产阶级革命引向“集中自己的一切力量”去“破坏”国家机器。","language":"中文","translation":false},{"id":"state-3-44","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":44,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"至于无产阶级将用什么东西来代替这个国家机器，关于这一点，巴黎公社提供了极有教益的材料。","language":"中文","translation":false},{"id":"state-3-45","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":45,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"3．1852年马克思对问题的提法","language":"中文","translation":false},{"id":"state-3-46","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":46,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"［注：第2版增加的一节。］","language":"中文","translation":false},{"id":"state-3-47","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":47,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"1907年，梅林把1852年3月5日马克思给魏德迈的信摘要登在《新时代》杂志[14]上（第25年卷第2册第164页）。在这封信里有这样一段精彩的论述：","language":"中文","translation":false},{"id":"state-3-48","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":48,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"“至于讲到我，无论是发现现代社会中阶级的存在还是发现这些阶级间的斗争，都不是我的功劳。在我以前很久，资产阶级的历史学家就叙述过这种阶级斗争的历史发展，资产阶级的经济学家也对这些阶级作过经济的剖析。我新做的工作就是证明了：（1）阶级的存在仅仅同生产的一定的历史发展阶段相联系；（2）阶级斗争必然导致无产阶级专政；（3）这个专政本身不过是达到消灭一切阶级和达到无阶级社会的过渡。……”［注：见《马克思恩格斯选集》第4卷人民出版社1972年版第332—333页。——编者注］","language":"中文","translation":false},{"id":"state-3-49","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":49,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"在这一段话里，马克思极其鲜明地表达了两点：第一，他的学说同先进的和最渊博的资产阶级思想家的学说之间的主要的和根本的区别；第二，他的国家学说的实质。","language":"中文","translation":false},{"id":"state-3-50","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":50,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"马克思学说中的主要之点是阶级斗争。人们时常这样说，这样写。但这是不正确的。根据这个不正确的看法，往往会对马克思主义进行机会主义的歪曲，把马克思主义篡改为资产阶级可以接受的东西。因为阶级斗争学说不是由马克思而是由资产阶级在马克思以前创立的，一般说来是资产阶级可以接受的。谁要是仅仅承认阶级斗争，那他还不是马克思主义者，他还可以不超出资产阶级思想和资产阶级政治的范围。把马克思主义局限于阶级斗争学说，就是阉割马克思主义，歪曲马克思主义，把马克思主义变为资产阶级可以接受的东西。只有承认阶级斗争、同时也承认无产阶级专政的人，才是马克思主义者。马克思主义者同平庸的小资产者（以及大资产者）之间的最深刻的区别就在这里。必须用这块试金石来检验是否真正理解和承认马克思主义。无怪乎当欧洲的历史在实践上向工人阶级提出这个问题时，不仅一切机会主义者和改良主义者，而且所有“考茨基主义者”（动摇于改良主义和马克思主义之间的人），都成了否认无产阶级专政的可怜的庸人和小资产阶级民主派。1918年8月即本书第1版刊行以后很久出版的考茨基的小册子《无产阶级专政》，就是口头上假意承认马克思主义而实际上市侩式地歪曲马克思主义和卑鄙地背弃马克思主义的典型（见我的小册子《无产阶级革命和叛徒考茨基》1918年彼得格勒和莫斯科版［注：见《列宁全集》第2版第35卷第229—327页。——编者注］）。","language":"中文","translation":false},{"id":"state-3-51","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":51,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"以过去的马克思主义者卡·考茨基为主要代表的现代机会主义，完全符合马克思对资产阶级立场所作的上述评语，因为这种机会主义把承认阶级斗争的领域局限于资产阶级关系的领域。（而在这个领域内，在这个领域的范围内，任何一个有知识的自由主义者都不会拒绝“在原则上”承认阶级斗争！）机会主义恰巧不把承认阶级斗争贯彻到最主要之点，贯彻到从资本主义向共产主义过渡的时期，贯彻到推翻资产阶级并完全消灭资产阶级的时期。实际上，这个时期必然是阶级斗争空前残酷、阶级斗争的形式空前尖锐的时期，因而这个时期的国家就不可避免地应当是新型民主的（对无产者和一般穷人是民主的）和新型专政的（对资产阶级是专政的）国家。","language":"中文","translation":false},{"id":"state-3-52","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":52,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"其次，只有懂得一个阶级的专政不仅对一般阶级社会是必要的，不仅对推翻了资产阶级的无产阶级是必要的，而且对介于资本主义和“无阶级社会”即共产主义之间的整整一个历史时期都是必要的，——只有懂得这一点的人，才算掌握了马克思国家学说的实质。资产阶级国家的形式虽然多种多样，但本质是一样的：所有这些国家，不管怎样，归根到底一定都是资产阶级专政。从资本主义向共产主义过渡，当然不能不产生非常丰富和多样的政治形式，但本质必然是一样的：都是无产阶级专政。[15]","language":"中文","translation":false},{"id":"state-3-53","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":53,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[8] 列宁在写《国家与革命》时还不知道马克思在1871年以前已经有了“无产阶级专政”的提法。他在《马克思主义论国家》这本笔记中曾写道，“查对一下，马克思和恩格斯在1871年以前是否说过‘无产阶级专政’？似乎没有！”（见本卷第149页）在《国家与革命》出版以后，列宁才看到了马克思1852年3月5日给约·魏德迈的信。他在自己的一本《国家与革命》（第1版）的最后一页上，用德文作了一段笔记：“《新时代》（第25年卷第2册第164页），1906—1907年第31期（1907年5月2日）：弗·梅林：《卡·马克思和弗·恩格斯传记的新材料》，引自马克思1852年3月5日给魏德迈的信。”接下去便是从信中摘录的谈无产阶级专政的那一段话。《国家与革命》再版时，列宁作了相应的补充。——22。","language":"中文","translation":false},{"id":"state-3-54","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":54,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[9] 出典于圣经《旧约全书·创世记》第25章。故事说，一天，雅各熬红豆汤，其兄以扫打猎回来，累得昏了，求雅各给他汤喝。雅各说，须把你的长子名分让给我。以扫就起了誓，出卖了自己的长子权。这个典故常被用来比喻因小失大。——24。","language":"中文","translation":false},{"id":"state-3-55","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":55,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[10] 涤罪所亦译炼狱，按天主教教义，是生前有一般罪愆的灵魂在升入天堂以前接受惩戒、洗刷罪过的地方。通过涤罪所是经历艰苦磨难的譬喻。——25。","language":"中文","translation":false},{"id":"state-3-56","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":56,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[11] “掘得好，老田鼠！”出自英国作家威·莎士比亚的悲剧《哈姆莱特》第1幕第5场。马克思曾不止一次地使用善于掘土的老田鼠这一形象来比喻为新社会开路的革命。——25。","language":"中文","translation":false},{"id":"state-3-57","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":57,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[12] 黑帮分子指俄国反动组织俄罗斯人民同盟、君主派、法制党、十月十七日同盟、工商党以及和平革新党的成员。他们力图保持旧的专制制度。——28。","language":"中文","translation":false},{"id":"state-3-58","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":58,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[13] 立宪民主党人是俄国自由主义君主派资产阶级的主要政党立宪民主党的成员。立宪民主党（正式名称为人民自由党）于1905年10月成立。中央委员中多数是资产阶级知识分子、地方自治局人士和自由派地主。主要活动家有帕·尼·米留可夫、谢·安·穆罗姆采夫、瓦·阿·马克拉柯夫、安·伊·盛加略夫、彼·伯·司徒卢威、约·弗·盖森等。立宪民主党提出一条与革命道路相对抗的和平的宪政发展道路。在第一次世界大战期间，它支持沙皇政府的掠夺政策，曾同十月党等反动政党组成“进步同盟”，要求成立责任内阁，即为资产阶级和地主所信任的政府，力图阻止革命并把战争进行到最后胜利。二月革命后，立宪民主党在资产阶级临时政府中居于领导地位，竭力阻挠土地问题、民族问题等基本问题的解决，并奉行继续帝国主义战争的政策。七月事变后，它支持科尔尼洛夫叛乱，阴谋建立军事独裁。十月革命胜利后，苏维埃政府于1917年11月28日（12月11日）宣布立宪民主党为“人民公敌的党”，该党随之转入地下，继续进行反革命活动，并参与白卫将军的武装叛乱。国内战争结束后，该党上层分子大多数逃亡国外。1921年5月，该党在巴黎召开代表大会时分裂，作为统一的党不复存在。——28。","language":"中文","translation":false},{"id":"state-3-59","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":59,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[14] 《新时代》杂志（《Die Neue Zeit》）是德国社会民主党的理论刊物，1883—1923年在斯图加特出版。1890年10月前为月刊，后改为周刊。1917年10月以前编辑为卡·考茨基，以后为亨·库诺。1885—1895年间，杂志发表过马克思和恩格斯的一些文章。恩格斯经常关心编辑部的工作，并不时帮助它纠正背离马克思主义的倾向。为杂志撰过稿的有威·李卜克内西、保·拉法格、格·瓦·普列汉诺夫、罗·卢森堡、弗·梅林等国际工人运动活动家。《新时代》杂志在介绍马克思主义基本理论、宣传俄国1905—1907年革命等方面做了有益的工作。随着考茨基转到机会主义立场，1910年以后，《新时代》杂志成了中派分子的刊物。——31。","language":"中文","translation":false},{"id":"state-3-60","author":"列宁","title":"国家与革命","location":"第二章 国家与革命。1848—1851年的经验","page":3,"paragraph":60,"url":"https://www.marxists.org/chinese/lenin/191708-09/03.htm","text":"[15] 关于无产阶级专政有多种多样形式的论点，列宁最早是在1916年写的《论面目全非的马克思主义和“帝国主义经济主义”》（见《列宁全集》第2版第28卷）一文中提出来的。但这篇文章直到1924年才在杂志上公开发表。列宁在1919年写的《无产阶级专政时代的经济和政治》和1923年写的《论我国革命》（见《列宁全集》第2版第37卷和第43卷）中也都涉及了这一问题。——33。","language":"中文","translation":false},{"id":"state-4-1","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-4-2","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","language":"中文","translation":false},{"id":"state-4-3","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"1．公社战士这次尝试的英雄主义何在？","language":"中文","translation":false},{"id":"state-4-4","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"2．用什么东西来代替被打碎的国家机器呢？","language":"中文","translation":false},{"id":"state-4-5","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"1．公社战士这次尝试的英雄主义何在？","language":"中文","translation":false},{"id":"state-4-6","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"大家知道，在巴黎公社出现以前几个月，即1870年秋，马克思曾经告诫巴黎工人说，推翻政府的尝试会是一种绝望的愚蠢举动。［注：参看《马克思恩格斯全集》第17卷第292页。——编者注］但是，当1871年3月工人被迫进行决战的时候，当起义已经成为事实的时候，尽管当时有种种恶兆，马克思还是以极其欢欣鼓舞的心情来迎接无产阶级革命。马克思并没有固执己见，学究式地非难运动“不合时宜”，象臭名昭彰的俄国马克思主义叛徒普列汉诺夫那样：普列汉诺夫在1905年11月曾写文章鼓励工人农民进行斗争，而在1905年12月以后却自由派式地大叫什么“本来就用不着拿起武器”[16]。","language":"中文","translation":false},{"id":"state-4-7","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"然而，马克思不仅是为“冲天的”（他的用语）公社战士的英雄主义感到欢欣鼓舞，他还从这次群众性的革命运动（虽然它没有达到目的）中看到了有极重大意义的历史经验，看到了全世界无产阶级革命的一定进步，看到了比几百种纲领和议论更为重要的实际步骤。分析这个经验，从这个经验中得到策略教训，根据这个经验来重新审查自己的理论，这就是马克思为自己提出的任务。","language":"中文","translation":false},{"id":"state-4-8","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思认为对《共产党宣言》必须作的唯一“修改”，就是他根据巴黎公社战士的革命经验作出的。","language":"中文","translation":false},{"id":"state-4-9","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"在《共产党宣言》德文新版上由两位作者署名的最后一篇序言，注明的日期是1872年6月24日。在这篇序言中，作者卡尔·马克思和弗里德里希·恩格斯说，《共产党宣言》这个纲领“现在有些地方已经过时了”。","language":"中文","translation":false},{"id":"state-4-10","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"接着他们说：“……特别是公社已经证明：‘工人阶级不能简单地掌握现成的国家机器，并运用它来达到自己的目的。’……” ［注：同上，第18卷第105页。——编者注］","language":"中文","translation":false},{"id":"state-4-11","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"这段引文中单引号内的话，是两位作者从马克思的《法兰西内战》一书中借用来的。［注：见《马克思恩格斯全集》第17卷第355页。——编者注］","language":"中文","translation":false},{"id":"state-4-12","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"总之，马克思和恩格斯认为巴黎公社的这个基本的主要的教训具有非常重大的意义，所以他们把这个教训加进《共产党宣言》，作为一个极其重要的修改。","language":"中文","translation":false},{"id":"state-4-13","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"非常值得注意的是，正是这个极其重要的修改被机会主义者歪曲了，而《共产党宣言》的读者有十分之九，甚至有百分之九十九，大概都不知道这个修改所包含的意思。我们在下面专论歪曲的那一章里，还要对这种歪曲加以详细说明。现在只须指出，对于我们所引证的马克思的这句名言，流行的庸俗的“理解”就是认为马克思在这里是强调缓慢发展的思想，不主张夺取政权等等。","language":"中文","translation":false},{"id":"state-4-14","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"实际上恰巧相反。马克思的意思是说工人阶级应当打碎、摧毁“现成的国家机器”，而不只是简单地夺取这个机器。","language":"中文","translation":false},{"id":"state-4-15","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"1871年4月12日，即正当巴黎公社存在的时候，马克思在给库格曼的信中写道：","language":"中文","translation":false},{"id":"state-4-16","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“……如果你读一下我的《雾月十八日》的最后一章，你就会看到，我认为法国革命的下一次尝试再不应该象以前那样把官僚军事机器从一些人的手里转到另一些人的手里，而应该把它打碎〈黑体和着重号是马克思用的；原文是zerbre-chen〉，这正是大陆上任何一次真正的人民革命的先决条件。我们英勇的巴黎同志们的尝试正是这样。”（《新时代》第20年卷（1901—1902）第1册第709页）［注：同上，第33卷第206页。——编者注］（马克思给库格曼的书信至少有两种俄文版本，其中有一种是由我编辑和作序［注：见《列宁全集》第2版第14卷《卡·马克思致路·库格曼书信集俄译本序言》。——编者注］的。）","language":"中文","translation":false},{"id":"state-4-17","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“把官僚军事国家机器打碎”这几个字，已经简要地表明了马克思主义关于无产阶级在革命中在对待国家方面的任务问题的主要教训。而正是这个教训，不仅被人完全忘记了，而且被现时对马克思主义所作的流行的即考茨基主义的“解释”公然歪曲了！","language":"中文","translation":false},{"id":"state-4-18","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"至于马克思提到的《雾月十八日》中的有关地方，我们在前面已经全部引用了。","language":"中文","translation":false},{"id":"state-4-19","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"在以上引证的马克思的这段论述中，有两个地方是值得特别指出的。第一，他把他的结论只限于大陆。这在1871年是可以理解的，那时英国还是一个纯粹资本主义的、但是没有军阀并在很大程度上没有官僚的国家的典型。所以马克思把英国除外，当时在英国，革命，甚至是人民革命，被设想有可能而且确实有可能不以破坏“现成的国家机器”为先决条件。","language":"中文","translation":false},{"id":"state-4-20","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"现在，在1917年，在第一次帝国主义大战时期，马克思的这个限制已经不能成立了。英国和美国这两个全世界最大的和最后的盎格鲁撒克逊“自由制”（从没有军阀和官僚这个意义来说）的代表，已经完全滚到官僚和军阀支配一切、压制一切这样一种一般欧洲式的污浊血腥的泥潭中去了。现在，无论在英国或美国，都要以打碎、破坏“现成的”（是1914—1917年间在这两个国家已制造出来而达到了“欧洲式的”、一般帝国主义的完备程度的）“国家机器”，作为“任何一次真正的人民革命的先决条件”。","language":"中文","translation":false},{"id":"state-4-21","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"第二，马克思说破坏官僚军事国家机器是“任何一次真正的人民革命的先决条件”，这个非常深刻的见解是值得特别注的意。“人民”革命这一概念出自马克思的口中似乎是很奇怪的，俄国的普列权诺夫分子和孟什维克，这些愿意以马克思主义者自命的司徒卢威信徒，也许会说马克思是“失言”。他们把马克思主义歪曲成了非常贫乏的自由主义：在他们看来，除了资产阶级革命和无产阶级革命的对立，再没有任何东西，而且他们对这种对立的理解也是非常死板的。","language":"中文","translation":false},{"id":"state-4-22","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"如果以20世纪的革命为例，那么无论葡萄牙革命[17]或土耳其革命[18]，当然都应该算是资产阶级革命。但是无论前者或后者，都不是“人民”革命，因为人民群众，人民的大多数，在这两次革命中都没有很积极地、独立地起来斗争，都没有明显地提出自己的经济要求和政治要求。反之，1905—1907年的俄国资产阶级革命，虽然没有取得象葡萄牙革命和土耳其革命某些时候得到的那些“辉煌”成绩，但无疑是一次“真正的人民”革命，因为人民群众，人民的大多数，惨遭压迫和剥削的社会最“底层”，曾经独立奋起，给整个革命进程打上了自己的烙印：提出了自己的要求，自己尝试着按照自己的方式建立新社会来代替正被破坏的旧社会。","language":"中文","translation":false},{"id":"state-4-23","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"1871年，欧洲大陆上任何一个国家的无产阶级都没有占人民的大多数。当时只有把无产阶级和农民都包括进来的革命，才能成为真正把大多数吸引到运动中来的“人民”革命。当时的“人民”就是由这两个阶级构成的。这两个阶级因为都受“官僚军事国家机器”的压迫、摧残和剥削而联合起来。打碎这个机器，摧毁这个机器，——这就是“人民”，人民的大多数，即工人和大多数农民的真正利益，这就是贫苦农民同无产者自由联盟的“先决条件”，而没有这个联盟，民主就不稳固，社会主义改造就没有可能。","language":"中文","translation":false},{"id":"state-4-24","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"大家知道，巴黎公社着力求为自己开辟实现这个联盟的道路，但是，由于许多内部和外部的原因，没有达到目的。","language":"中文","translation":false},{"id":"state-4-25","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"所以马克思在谈到“真正的人民革命”时，极严格地估计到了1871年欧洲大陆上多数国家中实际的阶级对比关系，但他丝毫没有忘记小资产阶级的特点（关于这些特点，他说得很多而且常常说）。另一方面，他又确认，“打碎”国家机器是工人和农民双方的利益所要求的，这个要求使他们联合起来，在他们面前提出了铲除“寄生物”、用一种新东西来代替的共同任务。","language":"中文","translation":false},{"id":"state-4-26","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"究竟用什么东西来代替呢？","language":"中文","translation":false},{"id":"state-4-27","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"2．用什么东西来代替被打碎的国家机器呢？","language":"中文","translation":false},{"id":"state-4-28","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"1847年，马克思在《共产党宣言》中对这个问题的回答还十分抽象，确切些说，只是指出了任务，而没有指出解决任务的方法。以“无产阶级组织成为统治阶级”来代替，以“争得民主”来代替，这就是《共产党宣言》的回答。","language":"中文","translation":false},{"id":"state-4-29","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":29,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"无产阶级组织成为统治阶级会采取什么样的具体形式，究竟怎样才能组织得同最完全最彻底地“争得民主”这点相适应，对于这个问题，马克思并没有陷于空想，而是期待群众运动的经验来解答。","language":"中文","translation":false},{"id":"state-4-30","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":30,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思在《法兰西内战》一书中对公社的经验（尽管经验很少）作了极仔细的分析。现在我们把该书中最重要的地方摘录下来：","language":"中文","translation":false},{"id":"state-4-31","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":31,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"起源于中世纪的“中央集权的国家政权及其遍布各地的机关——常备军、警察、官僚、僧侣和法官”，在19世纪发展起来了。随着资本和劳动之间阶级对抗的发展，“国家政权也就愈益具有压迫劳动的公共权力的性质，具有阶级统治机器的性质。在每次标志着阶级斗争的一定进步的革命以后，国家政权的纯粹压迫性质就愈益公开地显露出来”。在1848—1849年革命以后，国家政权就成为“资本对劳动作战的全国性武器”。第二帝国把这种情况固定下来了。","language":"中文","translation":false},{"id":"state-4-32","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":32,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“公社就是帝国的直接对立物。”“公社正是”“一种不仅应该消灭阶级统治的君主制形式，而且应该消灭阶级统治本身的共和国的”“一定的形式”。……","language":"中文","translation":false},{"id":"state-4-33","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":33,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"无产阶级社会主义共和国的这种“一定的”形式究竟是怎样的呢？它已开始建立的国家是怎样的呢？","language":"中文","translation":false},{"id":"state-4-34","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":34,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“……公社的第一个法令就是废除常备军而用武装的人民来代替它。……”","language":"中文","translation":false},{"id":"state-4-35","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":35,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"现在一切愿意以社会党自命的政党的纲领中都载有这个要求。但是它们的纲领究竟有什么价值，这从我国社会革命党人和孟什维克的行径中看得最清楚，因为他们恰巧是在2月27日革命以后就已在实际上拒绝实现这个要求！","language":"中文","translation":false},{"id":"state-4-36","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":36,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“公社是由巴黎各区普选选出的城市代表组成的。这些代表对选民负责，随时可以撤换。其中大多数自然都是工人，或者是公认的工人阶级的代表。……","language":"中文","translation":false},{"id":"state-4-37","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":37,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“……一向作为中央政府的工具的警察，立刻失去了一切政治职能，而变为公社的随时可以撤换的负责机关。其他各行政部门的官吏也是一样。从公社委员起，自上至下一切公职人员，都只应领取相当于工人工资的薪金。国家高级官吏所享有的一切特权以及支付给他们的办公费，都随着这些官吏的消失而消失了。……公社在废除了常备军和警察这两种旧政府物质权力的工具以后，立刻着手摧毁精神压迫的工具，即僧侣势力……法官已失去其表面的独立性……他们今后应该由选举产生，对选民负责，并且可以撤换。……”［注：见《马克思恩格斯全集》第17卷第355—359页。——编者注］","language":"中文","translation":false},{"id":"state-4-38","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":38,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"由此可见，公社用来代替被打碎的国家机器的，似乎“仅仅”是更完全的民主：废除常备军，一切公职人员完全由选举产生并完全可以撤换。但是这个“仅仅”，事实上意味着两类根本不同的机构的大更替。在这里恰巧看到了一个“量转化为质”的例子：民主实行到一般所能想象的最完全最彻底的程度，就由资产阶级民主转化成无产阶级民主，即由国家（＝对一定阶级实行镇压的特殊力量）转化成一种已经不是原来意义上的国家的东西。","language":"中文","translation":false},{"id":"state-4-39","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":39,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"镇压资产阶级及其反抗，仍然是必要的。这对公社尤其必要，公社失败的原因之一就是在这方面做得不够坚决。但是实行镇压的机关在这里已经是居民的多数，而不象过去奴隶制、农奴制、雇佣奴隶制时代那样总是居民的少数。既然是人民这个大多数自己镇压他们的压迫者，实行镇压的“特殊力量”也就不需要了！国家就在这个意义上开始消亡。大多数人可以代替享有特权的少数人（享有特权的官吏、常备军长官）的特殊机构，自己来直接行使这些职能，而国家政权职能的行使愈是全民化，这个国家政权就愈不需要了。","language":"中文","translation":false},{"id":"state-4-40","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":40,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"在这方面特别值得注意的是马克思着重指出的公社所采取的一项措施：取消支付给官吏的一切办公费和一切金钱上的特权，把国家所有公职人员的薪金减到“工人工资”的水平。这里恰巧最明显地表现出一种转变：从资产阶级的民主转变为无产阶级的民主，从压迫者的民主转变为被压迫阶级的民主，从国家这个对一定阶级实行镇压的“特殊力量”转变为由大多数人——工人和农民用共同的力量来镇压压迫者。正是在这特别明显的一点上，也许是国家问题的最重要的一点上，人们把马克思的教训忘得最干净！通俗的解释（这种解释多不胜数）是不提这一点的。人们把这一点看作已经过时的“幼稚的东西”，“照例”不讲它，正如基督教徒在获得国教地位以后，把带有民主精神和革命精神的早期基督教的种种“幼稚的东西”“忘记了”一样。","language":"中文","translation":false},{"id":"state-4-41","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":41,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"降低国家高级官吏的薪金，看来“不过”是幼稚的原始的民主制度的要求。现代机会主义的“创始人”之一，以前的社会民主主义者爱·伯恩施坦曾不止一次地重复资产阶级那种嘲笑“原始的”民主制度的庸俗做法。他同一切机会主义者一样，同现在的考茨基主义者一样，完全不懂得：第一，如果不在某种程度上“返回”到“原始的”民主制度，从资本主义过渡到社会主义是不可能的（因为，不这样做，怎么能够过渡到由大多数居民以至全体居民行使国家职能呢？）；第二，以资本主义和资本主义文化为基础的“原始民主制度”同原始时代或资本主义以前时代的原始民主制度是不一样的。资本主义文化创立了大生产——工厂、铁路、邮政、电话等等，在这个基础上，旧的“国家政权”的大多数职能已经变得极其简单，已经可以简化为登记、记录、检查这样一些极其简单的手续，以致每一个识字的人都完全能够胜任这些职能，行使这些职能只须付给普通的“工人工资”，并且可以（也应当）把这些职能中任何特权制、“长官制”的痕迹铲除干净。","language":"中文","translation":false},{"id":"state-4-42","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":42,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"一切公职人员毫无例外地完全由选举产生并可以随时撤换，把他们的薪金减到普通的“工人工资”的水平，这些简单的和“不言而喻”的民主措施使工人和大多数农民的利益完全一致起来，同时成为从资本主义通向社会主义的桥梁。这些措施关系到对社会进行的国家的即纯政治的改造，但是这些措施自然只有同正在实行或正在准备实行的“剥夺剥夺者”联系起来，也就是同变生产资料资本主义私有制为公有制联系起来，才会显示出全部意义和作用。","language":"中文","translation":false},{"id":"state-4-43","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":43,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思写道：“公社实现了所有资产阶级革命都提出的廉价政府的口号，因为它取消了两项最大的开支，即军队和官吏。”［注：见《马克思恩格斯全集》第17卷第361页。——编者注］","language":"中文","translation":false},{"id":"state-4-44","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":44,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"农民同小资产阶级其他阶层一样，他们当中只有极少数人能够“上升”，能够“出人头地”（从资产阶级的意义来说），即变成富人，变成资产者，或者变成生活富裕和享有特权的官吏。在任何一个有农民的资本主义国家（这样的资本主义国家占大多数），大多数农民是受政府压迫而渴望推翻这个政府、渴望有一个“廉价”政府的。能够实现这一要求的只有无产阶级，而无产阶级实现了这一要求，也就是向国家的社会主义改造迈进了一步。","language":"中文","translation":false},{"id":"state-4-45","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":45,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思写道：“公社不应当是议会式的，而应当是工作的机关，兼管行政和立法的机关。……","language":"中文","translation":false},{"id":"state-4-46","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":46,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"……普选制不是为了每三年或六年决定一次，究竟由统治阶级中的什么人在议会里代表和镇压（ver-und zertreten）人民，而是应当为组织在公社里的人民服务，正如个人选择的权利为任何一个工厂主服务，使他们能为自己的企业找到工人、监工和会计一样。”［注：同上，第358页和第360页。——编者注］","language":"中文","translation":false},{"id":"state-4-47","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":47,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"由于社会沙文主义和机会主义占了统治地位，这个在1871年对议会制提出的精彩的批评，现在也属于马克思主义中“被忘记的言论”之列。部长和职业议员们，现今的无产阶级叛徒和“专讲实利的”社会党人，把批评议会制完全让给无政府主义者去做，又根据这个非常正当的理由宣布，对议会制的任何批评都是“无政府主义”！！难怪“先进的”议会制国家的无产阶级一看到谢德曼、大卫、列金、桑巴、列诺得尔、韩德逊、王德威尔得、斯陶宁格、布兰亭、比索拉蒂之流的“社会党人”就产生恶感，而日益同情无政府工团主义，尽管无政府工团主义是机会主义的同胞兄弟。","language":"中文","translation":false},{"id":"state-4-48","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":48,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"但是，马克思从来没有象普列汉诺夫和考茨基等人那样，把革命的辩证法看作是一种时髦的空谈或动听的词藻。马克思善于无情地屏弃无政府主义，鄙视它甚至不会利用资产阶级议会这个“畜圈”，特别是在显然不具备革命形势的时候，但同时马克思又善于给议会制一种真正革命无产阶级的批评。","language":"中文","translation":false},{"id":"state-4-49","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":49,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"每隔几年决定一次究竟由统治阶级中的什么人在议会里镇压人民、压迫人民，——这就是资产阶级议会制的真正本质，不仅在议会制的立宪君主国内是这样，而且在最民主的共和国内也是这样。","language":"中文","translation":false},{"id":"state-4-50","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":50,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"但是，如果提出国家问题，如果把议会看作国家的一种机构，从无产阶级在这方面的任务的角度加以考察，那么摆脱议会制的出路何在呢？怎样才可以不要议会制呢？","language":"中文","translation":false},{"id":"state-4-51","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":51,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"我们不得不一再指出，马克思从研究公社得出的教训竟被忘得这样干净，以致对议会制的批评，除了无政府主义的或反动的批评，任何其他的批评都简直为现代的“社会民主党人”（应读作：现代的社会主义叛徒）所不知道了。","language":"中文","translation":false},{"id":"state-4-52","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":52,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"摆脱议会制的出路，当然不在于取消代表机构和选举制，而在于把代表机构由清谈馆变为“工作”机构。“公社不应当是议会式的，而应当是工作的机构，兼管行政和立法的机构。”","language":"中文","translation":false},{"id":"state-4-53","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":53,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“不应当是议会式的，而应当是工作的”机构，这正好击中了现代的议员和社会民主党的议会“哈巴狗”的要害！请看一看任何一个议会制的国家，从美国到瑞士，从法国到英国和挪威等等，那里真正的“国家”工作是在幕后做的，是由各部、官厅和司令部进行的。议会专门为了愚弄“老百姓”而从事空谈。这是千真万确的事实，甚至在俄罗斯共和国这个资产阶级民主共和国里，在还没有来得及建立真正的议会以前，议会制的所有这些弊病就已经显露出来了。带有腐朽的市侩习气的英雄们，如斯柯别列夫和策列铁里之流，切尔诺夫和阿夫克森齐耶夫之流，竟把苏维埃糟蹋成最卑鄙的资产阶级的议会，把它变成了清谈馆。在苏维埃里，“社会党人”部长先生们用空谈和决议来愚弄轻信的农民。在政府里，不断地更换角色，一方面为的是依次让更多的社会革命党人和孟什维克尝尝高官厚禄的“甜头”，另一方面为的是“转移”人民的“视线”。而在官厅里，在司令部里，却在“干着”“国家”工作！","language":"中文","translation":false},{"id":"state-4-54","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":54,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"执政的“社会革命党”的机关报《人民事业报》[19]不久以前在一篇社论中，用“大家”都以政治卖淫为业的“上流社会”中的人物的无比坦率的口吻自供说，甚至在“社会党人”（请原谅我用这个名词！）主管的各部中，整个官吏机构实际上还是旧的，还在按旧的方式行使职权，十分“自由地”暗中破坏革命的创举！即使没有这个自供，社会革命党人和孟什维克参加政府的实际情况不也证明了这一点吗？这里值得注意的只是，同立宪民主党人一起呆在官场里的切尔诺夫、鲁萨诺夫、晋季诺夫之流以及《人民事业报》的其他编辑先生，是这样的不知羞耻，竟满不在乎地在公众面前象谈小事情一样厚着脸皮说，在“他们的”各部中一切照旧！！革命民主的词句是用来愚弄乡下佬的，官吏的官厅的拖拉作风则是为了博得资本家的“欢心”，这就是“真诚”联合的实质。","language":"中文","translation":false},{"id":"state-4-55","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":55,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"在公社用来代替资产阶级社会贪污腐败的议会的那些机构中，发表意见和讨论的自由不会流为骗局，因为议员必须亲自工作，亲自执行自己通过的法律，亲自检查实际执行的结果，亲自对自己的选民直接负责。代表机构仍然存在，然而议会制这种特殊的制度，这种立法和行政的分工，这种议员们享有的特权地位，在这里是不存在的。没有代表机构，我们不可能想象什么民主，即使是无产阶级民主；而没有议会制，我们却能够想象和应该想象，除非我们对资产阶级社会的批评是空谈，除非推翻资产阶级统治的愿望不是我们真正的和真诚的愿望，而是象孟什维克和社会革命党人，象谢德曼、列金、桑巴、王德威尔得之流的那种骗取工人选票的“竞选”词句。","language":"中文","translation":false},{"id":"state-4-56","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":56,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"非常有教益的是：马克思在谈到既为公社需要、又为无产阶级民主需要的那种官吏的职能时，拿“任何一个工厂主”雇用的人员来作比喻，即拿雇用“工人、监工和会计”的普通资本主义企业来作比喻。","language":"中文","translation":false},{"id":"state-4-57","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":57,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思没有丝毫的空想主义，就是说，他没有虚构和幻想“新”社会。相反，他把从旧社会诞生新社会的过程、从前者进到后者的过渡形式，作为一个自然历史过程来研究。他以无产阶级群众运动的实际经验为依据，竭力从这个经验中取得实际教训。他向公社“学习”，就象一切伟大的革命思想家不怕向被压迫阶级的伟大运动的经验学习而从来不对这些运动作学究式的“训诫”（象普列汉诺夫说“本来就用不着拿起武器”，或者象策列铁里说“阶级应当自己约束自己”）一样。","language":"中文","translation":false},{"id":"state-4-58","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":58,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"要一下子、普遍地、彻底地取消官吏，是谈不到的。这是空想。但是一下子打碎旧的官吏机器，立刻开始建立一个新的机器来逐步取消任何官吏，这并不是空想，这是公社的经验，这是革命无产阶级当前的直接任务。","language":"中文","translation":false},{"id":"state-4-59","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":59,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"资本主义使“国家”管理的职能简化了，使我们有可能抛弃“长官职能”，把全部问题归结为无产者组织起来（成为统治阶级）以全社会名义雇用“工人、监工和会计”。","language":"中文","translation":false},{"id":"state-4-60","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":60,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"我们不是空想主义者。我们并不“幻想”一下子就可以不要任何管理，不要任何服从；这种由于不懂得无产阶级专政的任务而产生的无政府主义幻想，与马克思主义根本不相容，实际上只会把社会主义革命拖延到人们变成另一种人的时候。我们不是这样，我们希望由现在的人来实行社会主义革命，而现在的人没有服从、没有监督、没有“监工和会计”是不行的。","language":"中文","translation":false},{"id":"state-4-61","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":61,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"但是所需要的服从，是对一切被剥削劳动者的武装先锋队——无产阶级的服从。国家官吏的特殊“长官职能”可以并且应该立即开始、在一天之内就开始用“监工和会计”的简单职能来代替，这些职能现在只要有一般市民的水平就完全能够胜任，行使这些职能只须付给“工人工资”就完全可以了。","language":"中文","translation":false},{"id":"state-4-62","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":62,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"我们工人自己将以资本主义创造的成果为基础，依靠自己的工人的经验，建立由武装工人的国家政权维护的最严格的铁的纪律，来组织大生产，把国家官吏变成我们的委托的简单执行者，变成对选民负责的、可以撤换的、领取微薄薪金的“监工和会计”（当然还要用各式各样的和各种等级的技术人员），——这就是我们无产阶级的任务，无产阶级革命实现时就可以而且应该从这里开始做起。在大生产的基础上，这个开端自然会导致任何官吏逐渐“消亡”，使一种不带引号的、与雇佣奴隶制不同的秩序逐渐建立起来，在这种秩序下，日益简化的监督职能和填制表报的职能将由所有的人轮流行使，然后将成为一种习惯，最后就不再成其为特殊阶层的特殊职能了。","language":"中文","translation":false},{"id":"state-4-63","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":63,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"19世纪70年代，有一位聪明的德国社会民主党人认为邮政是社会主义经济的模型。这是非常正确的。目前邮政是按国家资本主义垄断组织的样式组成的一种经济。帝国主义逐渐把所有托拉斯都变为这种样式的组织。这里压在那些工作繁重、忍饥挨饿的“粗笨的”劳动者头上的仍然是那个资产阶级的官僚机构。但是管理社会事务的机构在这里已经准备好了。只要推翻资本家，用武装工人的铁拳粉碎这些剥削者的反抗，摧毁现代国家的官僚机器，我们就会有一个除掉了“寄生物”而技术装备程度很高的机构，这个机构完全可以由已经联合起来的工人自己使用，雇用一些技术人员、监工和会计，对所有这些人的工作如同对所有“国家”官吏的工作一样，付给工人的工资。这就是在对待一切托拉斯方面具体、实际而且立即可行的任务，它使劳动者免除剥削，并考虑到了实际上已经由公社开始了的尝试（特别是在国家建设方面）。","language":"中文","translation":false},{"id":"state-4-64","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":64,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"把整个国民经济组织得象邮政一样，做到在武装的无产阶级的监督和领导下使技术人员、监工和会计，如同所有公职人员一样，都领取不超过“工人工资”的薪金，这就是我们最近的目标。这样的国家，在这样的经济基础上的国家，才是我们所需要的。这样才能取消议会制而保留代表机构，这样才能使劳动阶级的这些机构免除资产阶级的糟蹋。","language":"中文","translation":false},{"id":"state-4-65","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":65,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“……在公社没有来得及进一步加以发挥的全国组织纲要上说得十分清楚，公社应该成为甚至最小村落的政治形式……”巴黎的“全国代表会议”也应当由各个公社选举出来。","language":"中文","translation":false},{"id":"state-4-66","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":66,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“……那时还会留给中央政府的为数不多然而非常重要的职能，则不应该象有人故意捏造的那样予以废除，而应该交给公社的官吏，即交给那些严格负责的官吏。","language":"中文","translation":false},{"id":"state-4-67","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":67,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"民族的统一不是应该破坏，相反地应该借助于公社制度组织起来，应该通过这样的办法来实现，即消灭以民族统一的体现者自居同时却脱离民族、凌驾于民族之上的国家政权，这个国家政权只不过是民族躯体上的寄生赘瘤。旧政府权力的纯粹压迫机关应该铲除，而旧政府权力的合理职能应该从妄图站在社会之上的权力那里夺取过来，交给社会的负责的公仆。”［注：见《马克思恩格斯全集》第17卷第359—360页。——编者注］","language":"中文","translation":false},{"id":"state-4-68","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":68,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"叛徒伯恩施坦所著的有赫罗斯特拉特[20]名声的《社会主义的前提和社会民主党的任务》一书，再清楚不过地表明现代社会民主党内的机会主义者是多么不理解，或者更确切些说，是多么不愿意理解马克思的这些论述。伯恩施坦正是在谈到马克思的上述这些话时写道：这个纲领“就其政治内容来说，在一切要点上都十分类似蒲鲁东主张的联邦制……尽管马克思和‘小资产者’蒲鲁东〈伯恩施坦把“小资产者”这几个字放在引号内，想必他是表示讽刺〉之间有其他种种分歧，可是在这几点上，他们的思路是再接近不过的”。伯恩施坦接着又说：自然，地方自治机关的意义在增长，但是“民主的第一个任务是不是就象马克思和蒲鲁东所想象的那样是废除〈Auflösung——直译是解散、融解〉现代国家和完全改变〈Umwandlung——变革〉其组织（由各省或各州的会议选出代表组织全国会议，而各省或各州的会议则由各公社选出代表组成），从而使全国代表机关的整个旧形式完全消失，对此我是有怀疑的”。（伯恩施坦《前提》1899年德文版第134页和第136页）","language":"中文","translation":false},{"id":"state-4-69","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":69,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"把马克思关于“消灭国家政权——寄生物”的观点同蒲鲁东的联邦制混为一谈，这简直是骇人听闻的事！但这不是偶然的，因为机会主义者从来没有想到，马克思在这里谈的根本不是同集中制对立的联邦制，而是要打碎在一切资产阶级国家里都存在的旧的资产阶级的国家机器。","language":"中文","translation":false},{"id":"state-4-70","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":70,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"机会主义者所想到的，只是在自己周围、在充满市侩的庸俗习气和“改良主义的”停滞现象的环境中他所看到的东西，即只是“地方自治机关”！至于无产阶级革命，机会主义者连想都不会去想了。","language":"中文","translation":false},{"id":"state-4-71","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":71,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"这是很可笑的。但值得注意的是，在这一点上竟没有人同伯恩施坦进行过争论。许多人都曾驳斥过伯恩施坦，特别是俄国著作界的普列汉诺夫和欧洲著作界的考茨基，但是，无论前者或后者都没有谈到伯恩施坦对马克思的这一歪曲。","language":"中文","translation":false},{"id":"state-4-72","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":72,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"机会主义者根本不会革命地思考，根本不会思考革命，他们竟把“联邦制”强加在马克思头上，把他同无政府主义的始祖蒲鲁东混为一谈。而想成为正统派马克思主义者、想捍卫革命的马克思主义学说的考茨基和普列汉诺夫却对此默不作声！这就是考茨基主义者和机会主义者极端庸俗地认识马克思主义同无政府主义的区别的根源之一。关于这种庸俗的观点，我们以后还要讲到。","language":"中文","translation":false},{"id":"state-4-73","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":73,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"在上述的马克思关于公社经验的论述中根本没有一点联邦制的痕迹。马克思和蒲鲁东相同的地方，恰巧是机会主义者伯恩施坦看不到的。而马克思和蒲鲁东不同的地方，恰巧是伯恩施坦认为相同的。","language":"中文","translation":false},{"id":"state-4-74","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":74,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思和蒲鲁东相同的地方，就在于他们两人都主张“打碎”现代国家机器。马克思主义同无政府主义（不管是蒲鲁东或巴枯宁）这一相同的地方，无论机会主义者或考茨基主义者都不愿意看见，因为他们在这一点上离开了马克思主义。","language":"中文","translation":false},{"id":"state-4-75","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":75,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思同蒲鲁东和巴枯宁不同的地方，恰巧就在联邦制问题上（更不用说无产阶级专政的问题了）。联邦制在原则上是从无政府主义的小资产阶级观点产生出来的。马克思是主张集中制的。在他上述的论述中，丝毫也没有离开集中制。只有对国家充满市侩“迷信”的人们，才会把消灭资产阶级国家机器看成是消灭集中制！","language":"中文","translation":false},{"id":"state-4-76","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":76,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"无产阶级和贫苦农民把国家政权掌握在自己手中，十分自由地按公社体制组织起来，把所有公社的行动统一起来去打击资本，粉碎资本家的反抗，把铁路、工厂、土地以及其他私有财产交给整个民族、整个社会，难道这不是集中制吗？难道这不是最彻底的民主集中制、而且是无产阶级的集中制吗？","language":"中文","translation":false},{"id":"state-4-77","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":77,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"伯恩施坦根本不会想到可能有自愿的集中制，可能使各公社自愿统一为一个民族，可能使无产阶级的公社在破坏资产阶级统治和资产阶级国家机器的事业中自愿溶合在一起。伯恩施坦同其他所有的庸人一样，以为集中制是只能从上面，只能由官吏和军阀强迫实行和维持的东西。","language":"中文","translation":false},{"id":"state-4-78","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":78,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思似乎预料到会有人歪曲他的这些观点，所以特意着重指出，如果非难公社要破坏民族的统一、废除中央政权，那就是故意捏造。马克思特意使用“组织起民族的统一”这样的说法，以便提出自觉的、民主的、无产阶级的集中制来同资产阶级的、军阀的、官吏的集中制相对立。","language":"中文","translation":false},{"id":"state-4-79","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":79,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"但是……充耳不闻比聋子还糟。现代社会民主党内的机会主义者正是充耳不闻消灭国家政权、铲除寄生物这样的话。","language":"中文","translation":false},{"id":"state-4-80","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":80,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"我们已经引用了马克思有关的言论，现在还应当补充几段。","language":"中文","translation":false},{"id":"state-4-81","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":81,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思写道：“……新的历史创举通常遭到的命运就是被误认为是对旧的、甚至已经过时的社会生活形式的抄袭，只要它们稍微与这些形式有点相似。于是这个摧毁〈bricht——打碎〉现代国家政权的新公社，也就被误认为是……中世纪公社的复活。……是……许多小邦的联盟〈孟德斯鸠，吉伦特派[21]〉……是反对过分的中央集权的古老斗争的扩大形式。……","language":"中文","translation":false},{"id":"state-4-82","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":82,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"……公社制度将把靠社会供养而又阻碍社会自由发展的寄生赘瘤——‘国家’迄今所吞食的一切力量归还给社会机体。仅仅这一点就会把法国的复兴向前推进了。……","language":"中文","translation":false},{"id":"state-4-83","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":83,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"……公社制度会使农村生产者在精神上受各省主要城市的领导，保证他们能够得到城市工人做他们利益的天然代表者。公社的存在自然而然会带来地方自治，但这种地方自治已经不是用来对抗现在已被废弃的国家政权的东西了。”［注：见《马克思恩格斯全集》第17卷第360—361页。——编者注］","language":"中文","translation":false},{"id":"state-4-84","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":84,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“消灭国家政权”这个“寄生赘瘤”，“铲除”它，“破坏”它；“国家政权现在已被废弃”，——这就是马克思评价和分析公社的经验时在国家问题上使用的说法。","language":"中文","translation":false},{"id":"state-4-85","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":85,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"所有这些都是在将近半世纪以前写的，现在必须把这些话发掘出来，使广大群众能够认识马克思主义的本来面目。马克思观察了他经历的最后一次大革命之后作出的结论，恰巧在新的无产阶级大革命时代到来的时候被人忘记了。","language":"中文","translation":false},{"id":"state-4-86","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":86,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"“……人们对公社有各种不同的解释以及公社代表各种不同的利益，证明公社是一个高度灵活的政治形式，而一切旧有的政府形式在本质上都是压迫性的。公社的真正秘密就在于：它实质上是工人阶级的政府，是生产者阶级同占有者阶级斗争的结果，是终于发现的、可以使劳动在经济上获得解放的政治形式。","language":"中文","translation":false},{"id":"state-4-87","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":87,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"如果没有最后这个条件，公社制度就没有实现的可能，就是骗人的东西。……”［注：同上，第361页。——编者注］","language":"中文","translation":false},{"id":"state-4-88","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":88,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"空想主义者致力于“发现”可以对社会进行社会主义改造的各种政治形式。无政府主义者根本不考虑政治形式问题。现代社会民主党内的机会主义者则把议会制民主国家的资产阶级政治形式当作不可逾越的极限，对这个“典范”崇拜得五体投地，宣布摧毁这些形式的任何意图都是无政府主义。","language":"中文","translation":false},{"id":"state-4-89","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":89,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"马克思从社会主义和政治斗争的全部历史中得出结论：国家一定会消失；国家消失的过渡形式（从国家到非国家的过渡），将是“组织成为统治阶级的无产阶级”。但是，马克思并没有去发现这个未来的政治形式。他只是对法国历史作了精确的观察，对它进行了分析，得出了1851年所导致的结论：事情已到了破坏资产阶级的国家机器的地步。","language":"中文","translation":false},{"id":"state-4-90","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":90,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"当无产阶级的群众革命运动已经爆发的时候，马克思就来研究这个运动究竟发现了什么样的形式，虽然这个运动遭到了挫折，虽然这个运动为期很短而且有显著的弱点。","language":"中文","translation":false},{"id":"state-4-91","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":91,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"公社就是无产阶级革命“终于发现的”、可以使劳动在经济上获得解放的形式。","language":"中文","translation":false},{"id":"state-4-92","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":92,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"公社就是无产阶级革命打碎资产阶级国家机器的第一次尝试和“终于发现的”、可以而且应该用来代替已被打碎的国家机器的政治形式。","language":"中文","translation":false},{"id":"state-4-93","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":93,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"我们往下就会看到，俄国1905年革命和1917年革命在另一个环境和另一种条件下继续着公社的事业，证实着马克思这种天才的历史的分析。","language":"中文","translation":false},{"id":"state-4-94","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":94,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"[16] 指格·瓦·普列汉诺夫在《我们的处境》和《再论我们的处境（致X同志的信）》两篇文章（载于1905年11、12月《社会民主党人日志》第3、4期）中发表的意见。——34。","language":"中文","translation":false},{"id":"state-4-95","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":95,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"[17] 指1910年的葡萄牙资产阶级革命。1910年10月4日，葡萄牙共和派在陆海军部队支持下举行起义，迫使国王逃亡英国。5日，宣布成立共和国，组成了资产阶级临时政府。临时政府实行了某些民主改革，但农民的土地问题没有解决，赋税和高利贷盘剥没有减轻。这次革命是一次极不彻底的资产阶级革命。——37。","language":"中文","translation":false},{"id":"state-4-96","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":96,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"[18] 指1908—1909年的土耳其资产阶级革命，史称青年土耳其革命。1908年7月，驻马其顿的军队在青年土耳其党人的领导下发动了革命。他们提出恢复1876年宪法的口号，希望把封建神权的奥斯曼帝国变成资产阶级的立宪君主国。土耳其苏丹阿卜杜尔-哈米德二世被迫签署了召开议会的诏书。1909年4月，忠于苏丹的军队发动了叛乱。叛乱被击败后，议会废黜了阿卜杜尔-哈米德二世，选举马赫穆德五世为苏丹，青年土耳其党人组织了新政府。新政府同封建势力、买办阶级和帝国主义相勾结，成为他们利益的代表者。这次革命没有发动也不敢发动广大群众，是一次极不彻底的资产阶级上层的革命。——37。","language":"中文","translation":false},{"id":"state-4-97","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":97,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"[19] 《人民事业报》（《Дело Народа》）是俄国社会革命党的报纸（日报），1917年3月15日（28日）起在彼得格勒出版，1917年6月起成为该党中央机关报。先后担任编辑的有B．B．苏霍姆林、维·米·切尔诺夫、弗·米·晋季诺夫等，撰稿人有尼·德·阿夫克森齐耶夫、阿·拉·郭茨、亚·费·克伦斯基等。该报反对布尔什维克党，号召工农群众同资本家和地主妥协、继续帝国主义战争、支持资产阶级临时政府。该报对十月革命持敌对态度，鼓动用武力反抗革命力量。1918年1月14日（27日）被苏维埃政府封闭。此后曾用其他名称及原名（1918年3—6月）出版。1918年10月在捷克斯洛伐克军和白卫社会革命党叛乱分子占领的萨马拉出了4号。1919年3月20—30日在莫斯科出了10号后被查封。——44。","language":"中文","translation":false},{"id":"state-4-98","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":98,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"[20] 赫罗斯特拉特是公元前4世纪希腊人。据传说，他为了扬名于世，在公元前356年纵火焚毁了被称为世界七大奇观之一的以弗所城阿尔蒂米斯神殿。后来，赫罗斯特拉特的名字成了不择手段追求名声的人的通称。——48。","language":"中文","translation":false},{"id":"state-4-99","author":"列宁","title":"国家与革命","location":"第三章 国家与革命。1871年巴黎公社的经验。马克思的分析","page":4,"paragraph":99,"url":"https://www.marxists.org/chinese/lenin/191708-09/04.htm","text":"[21] 吉伦特派是18世纪末法国资产阶级革命时期的一个政治集团，代表共和派工商业资产阶级和农业资产阶级的利益，主要是外省的资产阶级的利益。它的许多领导人是立法议会和国民公会中的吉伦特省代表，所以后世历史学家给它取了这个名称。吉伦特派主张各省自治，成立联邦。——51。","language":"中文","translation":false},{"id":"state-5-1","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-5-2","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"第四章 续前。恩格斯的补充说明","language":"中文","translation":false},{"id":"state-5-3","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"2．同无政府主义者的论战","language":"中文","translation":false},{"id":"state-5-4","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"4．对爱尔福特纲领草案的批判","language":"中文","translation":false},{"id":"state-5-5","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"5．1891年为马克思的《内战》所写的导言","language":"中文","translation":false},{"id":"state-5-6","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"马克思对公社经验的意义问题指出了基本的要点。恩格斯不止一次地谈到这个问题，说明马克思的分析和结论，并且有时非常有力非常突出地阐明这个问题的其他方面，因此我们必须特别来谈谈这些说明。","language":"中文","translation":false},{"id":"state-5-7","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在他论住宅问题的著作（1872年）［注：见《马克思恩格斯全集》第18卷第233—321页。——编者注］中，已经考虑到了公社的经验，几次谈到了革命在对待国家方面的任务。很有意思的是，他在谈到这个具体问题时，一方面明显地说明了无产阶级国家同现今的国家相似的地方，根据这些相似的地方我们可以把两者都称为国家；另一方面又明显地说明了两者不同的地方，或者说，说明了向消灭国家的过渡。","language":"中文","translation":false},{"id":"state-5-8","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“怎样解决住宅问题呢？在现代社会里，解决这个问题同解决其他一切社会问题完全一样，即靠供求关系在经济上的逐渐均衡来解决，但是这样解决之后，这个问题还会不断产生，就是说，一点也没有解决。社会革命将怎样解决这个问题呢？这不仅要以时间地点为转移，而且也同一些意义深远的问题有关，其中最重要的问题之一就是消灭城乡对立的问题。既然我们不必为未来社会的组织臆造种种空想方案，也就用不着在这上面浪费时间。但有一点是肯定的，现在各大城市中有足够的住宅，只要合理使用，就可以立即帮助解决真正的住宅缺乏问题。当然，要实现这一点，就必须剥夺现在的房主，让没有房子住或现在住得很挤的工人搬到这些住宅里去。只要无产阶级取得了政权，这种为社会福利所要求的措施就会象现代国家剥夺其他东西和占据住宅那样容易实现了。”（1887年德文版第22页）［注：见《马克思恩格斯全集》第18卷第252页。——编者注］","language":"中文","translation":false},{"id":"state-5-9","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"这里没有考察国家政权形式的改变，只谈到国家政权活动的内容。剥夺和占据住宅是根据现今国家的命令进行的。无产阶级的国家，从形式上来讲，也会“下令”占据住宅和剥夺房屋。但是很明显，旧的执行机构，即同资产阶级相联系的官吏机构，是根本不能用来执行无产阶级国家的命令的。","language":"中文","translation":false},{"id":"state-5-10","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……必须指出，由劳动人民实际占有一切劳动工具和全部工业，是同蒲鲁东主义[22]的‘赎买’办法完全相反的。如果采用后一种办法，单个劳动者将成为某一所住宅、某一块农民土地、某些劳动工具的所有者；如果采用前一种办法，则‘劳动人民’将成为全部住宅、工厂和劳动工具的集体所有者。这些住宅、工厂等等，至少是在过渡时期未必会毫无代价地交给个人或协作社使用。同样，消灭土地私有制并不要求消灭地租，而是要求把地租——虽然是用改变过的形式——转交给社会。所以，由劳动人民实际占有一切劳动工具，无论如何都不排除承租和出租的保存。”（第68页）［注：同上，第315页。——编者注］","language":"中文","translation":false},{"id":"state-5-11","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"我们在下一章将要考察在这段论述中触及的问题，即关于国家消亡的经济基础的问题。恩格斯非常谨慎，他说无产阶级国家“至少是在过渡时期未必”会毫无代价地分配住宅。把属于全民的住宅租给单个家庭就既要征收租金，又要实行一定的监督，还要规定分配住宅的某种标准。这一切都需要有一定的国家形式，但决不需要那种公职人员享有特权地位的特殊的军事和官僚机构。至于过渡到免费分配住宅，那是与国家的完全“消亡”联系着的。","language":"中文","translation":false},{"id":"state-5-12","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯谈到布朗基主义者[23]在公社以后因受到公社经验的影响而转到马克思主义的原则立场上的时候，曾顺便把这个立场表述如下：","language":"中文","translation":false},{"id":"state-5-13","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……无产阶级必须采取政治行动，必须实行专政，作为向废除阶级并和阶级一起废除国家的过渡……”（第55页）［注：见《马克思恩格斯全集》第18卷第297页。——编者注］","language":"中文","translation":false},{"id":"state-5-14","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"一些喜欢咬文嚼字的批评家或者“从事剿灭马克思主义”的资产阶级分子大概以为，在这里承认“废除国家”，在上述《反杜林论》的一段论述中又把这个公式当作无政府主义的公式加以否定，是矛盾的。如果机会主义者把恩格斯也算作“无政府主义者”，那并没有什么奇怪，因为社会沙文主义者给国际主义者加上无政府主义的罪名现在是愈来愈时行了。","language":"中文","translation":false},{"id":"state-5-15","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"国家会随着阶级的废除而废除，马克思主义向来就是这样教导我们的。《反杜林论》的那段人所共知的关于“国家消亡”的论述，并不是简单地斥责无政府主义者主张废除国家，而是斥责他们鼓吹可以“在一天之内”废除国家。","language":"中文","translation":false},{"id":"state-5-16","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"现在占统治地位的“社会民主主义”学说把马克思主义在消灭国家问题上对无政府主义的态度完全歪曲了，因此我们来回忆一下马克思和恩格斯同无政府主义者的一次论战，是特别有益的。","language":"中文","translation":false},{"id":"state-5-17","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"2．同无政府主义者的论战","language":"中文","translation":false},{"id":"state-5-18","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"这次论战发生在1873年。马克思和恩格斯曾经把驳斥蒲鲁东主义者即“自治论者”或“反权威主义者”的文章[24]寄给意大利的一个社会主义文集。这些文章在1913年才译成德文发表在《新时代》上。","language":"中文","translation":false},{"id":"state-5-19","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"马克思讥笑无政府主义者否认政治时写道：“……如果工人阶级的政治斗争采取革命的形式，如果工人建立起自己的革命专政来代替资产阶级专政，那他们就犯了侮辱原则的莫大罪行，因为工人为了满足自己低微的起码的日常需要，为了粉碎资产阶级的反抗，竟不放下武器，不废除国家，而赋予国家以一种革命的暂时的形式。……”（《新时代》第32年卷（1913—1914）第1册第40页）［注：见《马克思恩格斯全集》第18卷第335页。——编者注］","language":"中文","translation":false},{"id":"state-5-20","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"请看，马克思在驳斥无政府主义者时，仅仅是反对这样地“废除”国家！马克思完全不是反对国家将随阶级的消失而消失，或国家将随阶级的废除而废除，而是反对要工人拒绝使用武器，拒绝使用有组织的暴力，即拒绝使用应为“粉碎资产阶级的反抗”这一目的服务的国家。","language":"中文","translation":false},{"id":"state-5-21","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"马克思故意着重指出无产阶级所必需的国家具有“革命的暂时的形式”，以免人们歪曲他同无政府主义斗争的真正意思。无产阶级需要国家只是暂时的。在废除国家是目的这个问题上，我们和无政府主义者完全没有分歧。我们所断言的是，为了达到这个目的，就必须暂时利用国家权力的工具、手段、方法去反对剥削者，正如为了消灭阶级，就必须实行被压迫阶级的暂时专政一样。马克思在驳斥无政府主义者时，把问题提得非常尖锐，非常明确：工人在推翻资本家的压迫时，应当“放下武器”呢，还是应当利用它来反对资本家以粉碎他们的反抗？一个阶级有系统地利用武器反对另一个阶级，这不是国家的“暂时的形式”又是什么呢？","language":"中文","translation":false},{"id":"state-5-22","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"每一个社会民主党人都应该问问自己：他在同无政府主义者论战时是这样提出国家问题的吗？第二国际大多数正式的社会党是这样提出国家问题的吗？","language":"中文","translation":false},{"id":"state-5-23","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯更加详尽更加通俗地阐明了这同一个思想。他首先讥笑了蒲鲁东主义者的糊涂观念，讥笑他们把自己称为“反权威主义者”，也就是否认任何权威、任何服从、任何权力。恩格斯说，试拿工厂、铁路、在汪洋大海上航行的轮船来说吧，这是一些使用机器的、很多人有计划地共同工作的复杂技术设施，如果没有一定的服从，因而没有一定的权威或权力，那就没有一样能够开动起来，这难道还不明显吗？","language":"中文","translation":false},{"id":"state-5-24","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯写道：“……如果我拿这种论据来反对最顽固的反权威主义者，那他们就只能给我如下的回答：‘是的！这是对的，但是这里所说的并不是我们赋予我们的代表的那种权威，而是某种委托。’这些人以为，只要改变一下某一事物的名称，就可以改变这一事物本身。……”［注：见《马克思恩格斯全集》第18卷第343页。——编者注］","language":"中文","translation":false},{"id":"state-5-25","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯指出，权威和自治都是相对的概念，它们的应用范围是随着社会发展阶段的不同而改变的，把它们看作绝对的东西是荒谬的；并且补充说，使用机器和大规模生产的范围在日益扩大。然后恩格斯从权威问题的一般论述转到国家问题。","language":"中文","translation":false},{"id":"state-5-26","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"他写道：“……如果自治论者仅仅是想说，未来的社会组织只会在生产条件所必然要求的限度内允许权威存在，那也许还可以同他们说得通。但是，他们闭眼不看一切使权威成为必要的事实，只是拚命反对字眼。","language":"中文","translation":false},{"id":"state-5-27","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"为什么反权威主义者不只是限于高喊反对政治权威，反对国家呢？所有的社会主义者都认为，国家以及政治权威将由于未来的社会革命而消失，这就是说，社会职能将失去其政治性质，而变为维护社会利益的简单的管理职能。但是，反权威主义者却要求在那些产生政治国家的社会关系废除以前，一举把政治国家废除。他们要求把废除权威作为社会革命的第一个行动。","language":"中文","translation":false},{"id":"state-5-28","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"这些先生见过革命没有？革命无疑是天下最权威的东西。革命就是一部分人用枪杆、刺刀、大炮，即用非常权威的手段强迫另一部分人接受自己的意志。获得胜利的政党迫于必要，不得不凭借它的武器对反动派造成的恐惧，来维持自己的统治。要是巴黎公社不依靠对付资产阶级的武装人民这个权威，它能支持一天以上吗？反过来说，难道我们没有理由责备公社把这个权威用得太少了吗？总之，二者必居其一。或者是反权威主义者自己不知所云，如果是这样，那他们只是在散布糊涂观念；或者他们是知道的，如果是这样，那他们就是在背叛无产阶级的事业。在这两种情况下，他们都只是为反动派效劳。”（第39页）［注：见《马克思恩格斯全集》第18卷第343—344页。——编者注］","language":"中文","translation":false},{"id":"state-5-29","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":29,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"在这些论述中涉及了在考察国家消亡时期的政治与经济的相互关系（下一章要专门论述这个问题）时应该考察的问题。那就是关于社会职能由政治职能变为简单管理职能的问题和关于“政治国家”的问题。后面这个说法（它特别容易引起误会）指出了国家消亡有一个过程：正在消亡的国家在它消亡的一定阶段，可以叫作非政治国家。","language":"中文","translation":false},{"id":"state-5-30","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":30,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯这些论述中最精彩的地方，仍然是他用来反驳无政府主义者的问题提法。愿意做恩格斯的学生的社会民主党人，从1873年以来同无政府主义者争论过无数次，但他们在争论时所采取的态度，恰巧不是马克思主义者可以而且应该采取的。无政府主义者关于废除国家的观念是糊涂的，而且是不革命的，恩格斯就是这样提问题的。无政府主义者不愿看见的，正是革命的产生和发展，正是革命在对待暴力、权威、政权、国家方面的特殊任务。","language":"中文","translation":false},{"id":"state-5-31","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":31,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"现代社会民主党人通常对无政府主义的批评，可以归结为一种十足的市侩式的庸俗论调：“我们承认国家，而无政府主义者不承认！”这样的庸俗论调自然不能不使那些稍有头脑的革命的工人感到厌恶。恩格斯就不是这样谈问题的。他着重指出，所有的社会主义者都承认国家的消失是社会主义革命的结果。然后他具体地提出革命的问题，这个问题恰巧是机会主义的社会民主党人通常避而不谈而可以说是把它留给无政府主义者去专门“研究”的。恩格斯一提出这个问题就抓住了关键：公社难道不应该更多地运用国家即武装起来并组织成为统治阶级的无产阶级这个革命政权吗？","language":"中文","translation":false},{"id":"state-5-32","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":32,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"现在占统治地位的正式的社会民主党，对于无产阶级在革命中的具体任务问题，通常是简单地用庸人的讥笑来敷衍，至多也不过是含糊地用诡辩来搪塞，说什么“将来再看吧”。因此无政府主义者有权责备这样的社会民主党，责备他们背弃了对工人进行革命教育的任务。恩格斯运用最近这次无产阶级革命的经验，正是为了十分具体地研究一下无产阶级无论在对待银行方面还是在对待国家方面应该做什么和怎样做。","language":"中文","translation":false},{"id":"state-5-33","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":33,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在1875年3月18—28日给倍倍尔的信中有下面这样一段话，这段话在马克思和恩格斯关于国家问题的著作中，如果不算是最精彩的论述，也得算是最精彩的论述之一。附带说一下，据我们所知，倍倍尔第一次发表这封信是在他1911年出版的回忆录（《我的一生》）第2卷里，也就是在恩格斯写好并发出这封信的36年之后。","language":"中文","translation":false},{"id":"state-5-34","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":34,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在给倍倍尔的信里批判了也被马克思在给白拉克的有名的信里批判过的哥达纲领草案，并且特别谈到了国家问题，他写道：","language":"中文","translation":false},{"id":"state-5-35","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":35,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……自由的人民国家变成了自由国家。从字面上看，自由国家就是可以自由对待本国公民的国家，即具有专制政府的国家。应当抛弃这一切关于国家的废话，特别是在出现了已经不是原来意义上的国家的巴黎公社以后。无政府主义者用‘人民国家’这一个名词把我们挖苦得很够了，虽然马克思驳斥蒲鲁东的著作以及后来的《共产党宣言》都已经直接指出，随着社会主义社会制度的建立，国家就会自行解体和消失。既然国家只是在斗争中、在革命中用来对敌人实行暴力镇压的一种暂时的机关，那么，说自由的人民国家，就纯粹是无稽之谈了：当无产阶级还需要国家的时候，它需要国家不是为了自由，而是为了镇压自己的敌人，一到有可能谈自由的时候，国家本身就不再存在了。因此，我们建议把国家一词全部改成‘公团’（Gemeinwesen），这是一个很好的德文古词，相当于法文的‘公社’。”（德文原版第321—322页）［注：见《马克思恩格斯全集》第19卷第7—8页。——编者注］","language":"中文","translation":false},{"id":"state-5-36","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":36,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"应当指出：这封信是谈党纲的，这个党纲马克思在离这封信仅仅几星期以后的一封信（马克思的信写于1875年5月5日）里曾作过批判；当时恩格斯和马克思一起住在伦敦。因此，恩格斯在最后一句话里用“我们”二字，无疑是以他自己和马克思的名义向德国工人党的领袖建议，把“国家”一词从党纲中去掉，用“公团”来代替。","language":"中文","translation":false},{"id":"state-5-37","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":37,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"如果向为了迁就机会主义者而伪造出来的现代“马克思主义”的首领们建议这样来修改党纲，那他们该会怎样狂吠，骂这是“无政府主义”啊！","language":"中文","translation":false},{"id":"state-5-38","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":38,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"让他们狂吠吧。资产阶级会因此称赞他们的。","language":"中文","translation":false},{"id":"state-5-39","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":39,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"我们还是要做我们自己的事情。在修改我们的党纲时，绝对必须考虑恩格斯和马克思的意见，以便更接近真理，以便清除对马克思主义的歪曲而恢复马克思主义，以便更正确地指导工人阶级争取自身解放的斗争。在布尔什维克当中大概不会有人反对恩格斯和马克思的建议。困难也许只是在用词上。德文中有两个词都作“公团”解释，恩格斯用的那个词不是指单个的公团，而是指公团的总和即公团体系。俄文中没有这样一个词，也许只好采用法文中的“公社”一词，虽然这也有它的不足之处。","language":"中文","translation":false},{"id":"state-5-40","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":40,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“巴黎公社已经不是原来意义上的国家”，——这是恩格斯在理论上最重要的论断。看了上文以后，这个论断是完全可以理解的。公社已经不再是国家了，因为公社所要镇压的不是大多数居民，而是少数居民（剥削者）；它已经打碎了资产阶级的国家机器；居民已经自己上台来代替实行镇压的特殊力量。所有这一切都已经不是原来意义上的国家了。如果公社得到巩固，那么公社的国家痕迹就会自行“消亡”，它就用不着“废除”国家机构，因为国家机构将无事可做而逐渐失去其作用。","language":"中文","translation":false},{"id":"state-5-41","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":41,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“无政府主义者用‘人民国家’这一个名词挖苦我们”，——恩格斯的这句话首先是指巴枯宁和他对德国社会民主党人的攻击说的。恩格斯认为这种攻击有正确之处，因为“人民国家”象“自由的人民国家”一样，都是无稽之谈，都是背离社会主义的。恩格斯竭力纠正德国社会民主党人反对无政府主义者的斗争，使这个斗争在原则上正确，使它摆脱在“国家”问题上的种种机会主义偏见。真可惜！恩格斯的这封信竟被搁置了36年。我们在下面可以看到，即使在这封信发表以后，考茨基实际上还是顽固地重犯恩格斯告诫过的那些错误。","language":"中文","translation":false},{"id":"state-5-42","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":42,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"倍倍尔在1875年9月21日写回信给恩格斯，信中也谈到他“完全同意”恩格斯对纲领草案的意见，并说他责备了李卜克内西的让步态度（倍倍尔的回忆录德文版第2卷第334页）。但是把倍倍尔的《我们的目的》这本小册子拿来，我们却可以看到国家问题上一种完全错误的论调：","language":"中文","translation":false},{"id":"state-5-43","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":43,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“国家应当由基于阶级统治的国家变成人民国家。”（《我们的目的》1886年德文版第14页）","language":"中文","translation":false},{"id":"state-5-44","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":44,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"这就是倍倍尔那本小册子第9版（第9版！）中的话！难怪德国社会民主党竟听任一些人如此顽固地重复关于国家问题的机会主义论调，特别是在恩格斯所作的革命解释被搁置起来而整个生活环境又长期使人“忘记”革命的时候。","language":"中文","translation":false},{"id":"state-5-45","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":45,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"4．对爱尔福特纲领草案的批判","language":"中文","translation":false},{"id":"state-5-46","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":46,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"在分析马克思主义的国家学说时，不能不提到恩格斯在1891年6月29日寄给考茨基而过了10年以后才在《新时代》上发表的对爱尔福特纲领[25]草案的批判，因为这篇文章主要就是批判社会民主党在国家结构问题上的机会主义观点的。","language":"中文","translation":false},{"id":"state-5-47","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":47,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"顺便指出，恩格斯还对经济问题作了一个非常宝贵的指示，这说明恩格斯是如何细心、如何深刻地考察了现代资本主义的形态的变化，因而他才能在一定程度上预先想到当前帝国主义时代的任务。这个指示是恩格斯由于该纲领草案用“无计划性”这个词来说明资本主义的特征而作的，他写道：","language":"中文","translation":false},{"id":"state-5-48","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":48,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……如果我们从股份公司进而来看那支配着和垄断着整个工业部门的托拉斯，那么，那里不仅私人生产停止了，而且无计划性也没有了。”（《新时代》第20年卷（1901—1902）第1册第8页）［注：见《马克思恩格斯全集》第22卷第270页。——编者注］","language":"中文","translation":false},{"id":"state-5-49","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":49,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"这里抓住了对现代资本主义即帝国主义的理论评价中最主要的东西，即资本主义转化为垄断资本主义。后面这四个字必须用黑体加以强调，因为目前最普遍的一种错误就是资产阶级改良主义者所断言的什么垄断资本主义或国家垄断资本主义已经不是资本主义，已经可以称为“国家社会主义”，如此等等。完全的计划性当然是托拉斯所从来没有而且也不可能有的。但是尽管托拉斯有计划性，尽管资本大王们能预先考虑到一国范围内甚至国际范围内的生产规模，尽管他们有计划地调节生产，我们还是处在资本主义下，虽然是在它的新阶段，但无疑还是处在资本主义下。在无产阶级的真正代表看来，这种资本主义之“接近”社会主义，只是证明社会主义革命已经接近，已经不难实现，已经可以实现，已经刻不容缓，而决不是证明可以容忍一切改良主义者否认社会主义革命和粉饰资本主义。","language":"中文","translation":false},{"id":"state-5-50","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":50,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"现在我们回过来讲国家问题。恩格斯在这里作了三方面的特别宝贵的指示：第一是关于共和国问题；第二是关于民族问题同国家结构的联系；第三是关于地方自治。","language":"中文","translation":false},{"id":"state-5-51","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":51,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"关于共和国，恩格斯把这点作为批判爱尔福特纲领草案的重点。如果我们还记得当时爱尔福特纲领在整个国际社会民主党中具有怎样的意义，它怎样成了整个第二国际的典范，那么可以毫不夸大地说，恩格斯在这里是批判了整个第二国际的机会主义。","language":"中文","translation":false},{"id":"state-5-52","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":52,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯写道：“草案的政治要求有一个很大的缺点。这里没有说〈黑体是恩格斯用的〉本来应当说的东西。”［注：见《马克思恩格斯全集》第22卷第272页。——编者注］","language":"中文","translation":false},{"id":"state-5-53","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":53,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"接着，恩格斯解释道：德国的宪法实质上是1850年最反动的宪法的抄本；帝国国会，正如威廉·李卜克内西所说的，只是“专制制度的遮羞布”；想在把各小邦的存在合法化、把德意志各小邦的联盟合法化的宪法的基础上实现“将一切劳动资料转变成公有财产”，“显然是荒谬的”。","language":"中文","translation":false},{"id":"state-5-54","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":54,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“谈论这个问题是危险的”，——恩格斯补充说，因为他深知在德国不能在纲领中公开提出建立共和国的要求。但是，恩格斯并不因为这个理由很明显，“大家”都满意，就这样算了。他接着说：“但是，无论如何，事情总是要去解决的。这样做是多么必要，正好现在由在很大一部分社会民主党报刊中散布的机会主义证明了。现在有人因害怕反社会党人法[26]重新恢复，或者回想起在这项法律统治下发表的几篇过早的声明，就忽然想要党承认在德国的现行法律秩序下，可以通过和平方式实现党的一切要求。……”［注：见《马克思恩格斯全集》第22卷第273页。——编者注］","language":"中文","translation":false},{"id":"state-5-55","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":55,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"德国社会民主党人那样行事是害怕非常法重新恢复，——恩格斯把这个主要事实提到首位，毫不犹豫地称之为机会主义，而且指出，正是因为在德国没有共和制和自由，所以幻想走“和平”道路是十分荒谬的。恩格斯非常谨慎，没有束缚自己的手脚。他承认，在有共和制或有充分自由的国家里，和平地向社会主义发展是“可以设想”（仅仅是“设想”！）的，但是在德国，他重复说：","language":"中文","translation":false},{"id":"state-5-56","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":56,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……在德国，政府几乎有无上的权力，帝国国会及其他一切代议机关毫无实权，因此，在德国宣布某种类似的做法，而且在没有任何必要的情况下宣布这种做法，就是揭去专制制度的遮羞布，自己去遮盖那赤裸裸的东西。……”［注：同上。——编者注］","language":"中文","translation":false},{"id":"state-5-57","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":57,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"德国社会民主党把这些指示“束之高阁”，党的大多数正式领袖果然就成了专制制度的遮羞者。","language":"中文","translation":false},{"id":"state-5-58","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":58,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……这样的政策归根到底只能把党引入迷途。人们把一般的抽象的政治问题提到首要地位，从而把那些在重大事件一旦发生，政治危机一旦来临就会自行提到日程上来的迫切的具体问题掩盖起来。这除了使党突然在决定性的时刻束手无策，使党在具有决定意义的问题上由于从未进行过讨论而认识模糊和意见不一而外，还能有什么结果呢？……","language":"中文","translation":false},{"id":"state-5-59","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":59,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"为了眼前暂时的利益而忘记根本大计，只图一时的成就而不顾后果，为了运动的现在而牺牲运动的未来，这种做法可能也是出于‘真诚的’动机。但这是机会主义，始终是机会主义，而且‘真诚的’机会主义也许比其他一切机会主义更危险。……","language":"中文","translation":false},{"id":"state-5-60","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":60,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"如果说有什么是勿庸置疑的，那就是，我们的党和工人阶级只有在民主共和国这种政治形式下，才能取得统治。民主共和国甚至是无产阶级专政的特殊形式，法国大革命已经证明了这一点。……”［注：见《马克思恩格斯全集》第22卷第273—274页。——编者注］","language":"中文","translation":false},{"id":"state-5-61","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":61,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在这里特别明确地重申了贯穿在马克思的一切著作中的基本思想，这就是：民主共和国是走向无产阶级专政的捷径。因为这样的共和国虽然丝毫没有消除资本的统治，因而也丝毫没有消除对群众的压迫和阶级斗争，但是，它必然会使这个斗争扩大、展开、明朗化和尖锐化，以致一旦出现满足被压迫群众的根本利益的可能性，这种可能性就必然通过而且只有通过无产阶级专政即无产阶级对这些群众的领导得到实现。对于整个第二国际来说，这也是马克思主义中“被忘记的言论”，而孟什维克党在俄国1917年革命头半年的历史则把这种忘却揭示得再清楚不过了。","language":"中文","translation":false},{"id":"state-5-62","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":62,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在谈到同居民的民族成分有关的联邦制共和国问题时写道：","language":"中文","translation":false},{"id":"state-5-63","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":63,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“应当用什么东西来代替现在的德国呢？〈它拥有反动的君主制宪法和同样反动的小邦分立制，这种分立制把“普鲁士主义”的种种特点固定下来，而不是使它们在德国的整体中被融解掉〉在我看来，无产阶级只能采取单一而不可分的共和国的形式。联邦制共和国一般说来现在还是美国广大地区所必需的，虽然在它的东部已经成为障碍。在英国，联邦制共和国将是前进一步，因为在这里，两个岛上居住着四个民族，议会虽然是统一的，但是却有三种立法体系同时并存。联邦制共和国在小小的瑞士早已成为障碍，它之所以还能被容忍，只是因为瑞士甘愿充当欧洲国家体系中纯粹消极的一员。对德国说来，实行瑞士式的联邦制，那就是倒退一大步。联邦制国家和单一制国家有两点区别，这就是：每个加盟的邦，即每个州都有它特别的民事立法、刑事立法和法院组织；其次，与国民议院并存的还有联邦议院，在联邦议院中，每一个州无分大小，都以一州的资格参加表决。”在德国，联邦制国家是向单一制国家的过渡，所以不是要使1866年和1870年的“来自上面的革命”又倒退回去，而是要用“来自下面的运动”来加以补充。［注：见《马克思恩格斯全集》第22卷第275页。——编者注］","language":"中文","translation":false},{"id":"state-5-64","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":64,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯对国家形式问题不但不抱冷淡态度，相反，他非常细致地努力去分析的正是过渡形式，以便根据每一个别场合的具体历史特点来弄清各该场合的过渡形式是从什么到什么的过渡。","language":"中文","translation":false},{"id":"state-5-65","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":65,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯同马克思一样，从无产阶级和无产阶级革命的观点出发坚持民主集中制，坚持单一而不可分的共和国。他认为联邦制共和国或者是一种例外，是发展的障碍，或者是由君主国向集中制共和国的过渡，是在一定的特殊条件下的“前进一步”。而在这些特殊条件中，民族问题占有突出的地位。","language":"中文","translation":false},{"id":"state-5-66","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":66,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯同马克思一样，虽然无情地批判了小邦制的反动性和在一定的具体情况下用民族问题来掩盖这种反动性的行为，但是他们在任何地方都丝毫没有忽视民族问题的倾向，而荷兰和波兰两国的马克思主义者在反对“自己”小国的狭隘市侩民族主义的极正当的斗争中，却常常表现出这种倾向。","language":"中文","translation":false},{"id":"state-5-67","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":67,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"在英国，无论从地理条件、从共同的语言或从数百年的历史来看，似乎已经把各个小地区的民族问题都“解决了”。可是，甚至在这个国家里，恩格斯也注意到一个明显的事实，即民族问题还没有完全消除，因此他承认建立联邦制共和国是“前进一步”。自然，这里他丝毫没有放弃批评联邦制共和国的缺点，丝毫没有放弃为实现单一制的、民主集中制的共和国而最坚决地进行宣传和斗争。","language":"中文","translation":false},{"id":"state-5-68","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":68,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"但是，恩格斯绝对不象资产阶级思想家和包括无政府主义者在内的小资产阶级思想家那样，从官僚制度的意义上去了解民主集中制。在恩格斯看来，集中制丝毫不排斥这样一种广泛的地方自治，这种自治在各个市镇和省自愿坚持国家统一的同时，绝对能够消除任何官僚制度和任何来自上面的“发号施令”。","language":"中文","translation":false},{"id":"state-5-69","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":69,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在发挥马克思主义对于国家问题的纲领性观点时写道：“……因此，需要单一制的共和国，但并不是象现在法兰西共和国那样的共和国，现在的法兰西共和国同1798年建立的没有皇帝的帝国没有什么不同。从1792年到1798年，法国的每个省、每个市镇，都有美国式的完全的自治权，这是我们也应该有的。至于应当怎样组织自治和怎样才可以不要官僚制，这已经由美国和法兰西第一共和国给我们证明了，而现在又有澳大利亚、加拿大以及英国的其他殖民地给我们证明了。这种省〈州〉的和市镇的自治是比例如瑞士的联邦制更自由得多的制度，在瑞士的联邦制中，州对Bund〈即对整个联邦国家〉而言固然有很大的独立性，但它对专区和市镇也具有独立性。州政府任命专区区长和市镇长官，这在讲英语的国家里是绝对没有的，而我们将来也坚决不要这样的官吏，就象不要普鲁士的Landrat和Regierungsrat〈专员、县长、省长以及所有由上面任命的官吏〉一样。”根据这一点，恩格斯建议把党纲关于自治问题的条文表述如下：“省〈省或州〉、专区和市镇通过由普选选出的官吏实行完全的自治。取消由国家任命的一切地方的和省的政权机关。”［注：见《马克思恩格斯全集》第22卷第276—277页。——编者注］","language":"中文","translation":false},{"id":"state-5-70","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":70,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"在被克伦斯基和其他“社会党人”部长的政府封闭的《真理报》[27]（1917年5月28日第68号）上我已经指出过，在这一点上（自然远不止这一点），我国所谓革命民主派的所谓社会党人代表们是如何令人气愤地背弃民主主义。［注：参看《列宁全集》第2版第30卷《一个原则问题（关于民主制的一段“被忘记的言论”）》。——编者注］自然，这些通过“联合”而把自己同帝国主义资产阶级拴在一起的人，对我指出的这些是充耳不闻的。","language":"中文","translation":false},{"id":"state-5-71","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":71,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"必须特别指出的是，恩格斯用事实和最确切的例子推翻了一种非常流行的、特别是在小资产阶级民主派中间非常流行的偏见，即认为联邦制共和国一定要比集中制共和国自由。这种看法是不正确的。恩格斯所举的1792—1798年法兰西集中制共和国和瑞士联邦制共和国的事实推翻了这种偏见。真正民主的集中制共和国赋予的自由比联邦制共和国要多。换句话说，在历史上，地方、州等等能够享有最多自由的是集中制共和国，而不是联邦制共和国。","language":"中文","translation":false},{"id":"state-5-72","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":72,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"对于这个事实，以及关于联邦制共和国与集中制共和国和关于地方自治这整个问题，无论过去和现在，我们党的宣传鼓动工作都没有充分注意。","language":"中文","translation":false},{"id":"state-5-73","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":73,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"5．1891年为马克思的《内战》所写的导言","language":"中文","translation":false},{"id":"state-5-74","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":74,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在为《法兰西内战》第3版写的导言中（导言注明的日期是1891年3月18日，最初刊载在《新时代》杂志上），除了顺便就有关对国家的态度的问题提出一些值得注意的意见，还对公社的教训作了极其鲜明的概括。这个概括，由于考虑到了公社以后20年的全部经验而作得非常深刻，并且是专门用来反对流行于德国的“对国家的迷信”的，完全可以称为马克思主义在国家问题上的最高成就。","language":"中文","translation":false},{"id":"state-5-75","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":75,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯指出：法国每次革命以后工人总是武装起来了；“因此，掌握国家大权的资产者的第一个信条就是解除工人的武装。于是，在每次工人赢得革命以后就产生新的斗争，其结果总是工人失败……”［注：见《马克思恩格斯全集》第22卷第218页。——编者注］","language":"中文","translation":false},{"id":"state-5-76","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":76,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"对各次资产阶级革命的经验作出的这个总结，真是又简短，又明了。这里正好抓住了问题的实质，也是国家问题的实质（被压迫阶级有没有武装？）。正是这个实质却是那些受资产阶级思想影响的教授以及小资产阶级民主派常常避而不谈的。在1917年的俄国革命中，泄露资产阶级革命的这个秘密的荣幸（卡芬雅克式的荣幸[28]）落到了“孟什维克”、“也是马克思主义者”的策列铁里身上。他在6月11日的“具有历史意义的”演说[29]中，脱口说出了资产阶级要解除彼得格勒工人武装的决定，当然，他把这个决定既说成是他自己的决定，又说成这就是“国家的”需要！","language":"中文","translation":false},{"id":"state-5-77","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":77,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"策列铁里在6月11日发表的具有历史意义的演说，当然会成为每一个研究1917年革命的历史学家都要援引的一个最明显的例证，证明策列铁里先生所率领的社会革命党人同孟什维克的联盟如何转到资产阶级方面来反对革命的无产阶级。","language":"中文","translation":false},{"id":"state-5-78","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":78,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯顺便提出的另外一个也是有关国家问题的意见是谈宗教的。大家知道，德国社会民主党随着它的日益腐化而愈来愈机会主义化，愈来愈对“宣布宗教为私人的事情”这个有名的公式进行庸俗的歪曲。就是说，把这个公式歪曲成似乎宗教问题对于革命无产阶级政党也是私人的事情！！恩格斯起来反对的就是这种对无产阶级革命纲领的完全背叛，但恩格斯在1891年还只看到自己党内机会主义的最小的萌芽，因此他说得很谨慎：","language":"中文","translation":false},{"id":"state-5-79","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":79,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“因为参加公社的差不多都是工人或公认的工人代表，所以它所通过的决议也就完全是无产阶级性质的。有些决议把共和派资产阶级只是由于怯懦才不肯实行的、然而是工人阶级自由活动的必要基础的那些改革以法令形式确定下来，例如实行宗教对国家来说仅仅是私人事情的原则。有些决议则直接有利于工人阶级，并且在某种程度上深深刺入了旧社会制度的内脏。……”［注：见《马克思恩格斯全集》第22卷第223页。——编者注］","language":"中文","translation":false},{"id":"state-5-80","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":80,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯故意强调“对国家来说”这几个字，目的是要击中德国机会主义的要害，因为德国机会主义宣布宗教对党来说是私人的事情，这样也就把革命无产阶级政党降低到最庸俗的“自由思想派”那班市侩的水平，这种市侩可以容许不信宗教，但是拒绝执行对麻醉人民的宗教鸦片进行党的斗争的任务。","language":"中文","translation":false},{"id":"state-5-81","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":81,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"将来研究德国社会民主党的历史学家在探讨该党1914年遭到可耻的破产的根源时，会找到许多关于这个问题的有趣的材料：从该党思想领袖考茨基的论文中为机会主义打开大门的暧昧言论起，直到党对1913年的与教会分离的运动[30]的态度止。","language":"中文","translation":false},{"id":"state-5-82","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":82,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"现在我们来看一看恩格斯在公社以后20年是怎样为斗争的无产阶级总结公社教训的。","language":"中文","translation":false},{"id":"state-5-83","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":83,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"下面就是恩格斯认为最重要的教训：","language":"中文","translation":false},{"id":"state-5-84","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":84,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……正是军队、政治警察、官僚这种旧的中央集权政府的压迫权力，即由拿破仑在1798年建立，以后一直被每届新政府当作合意的工具接收并利用来反对自己的敌人的权力，——正是这种权力应该在全国各地覆没，正如它已在巴黎覆没一样。","language":"中文","translation":false},{"id":"state-5-85","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":85,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"公社一开始就得承认，工人阶级在获得统治时，不能继续运用旧的国家机器来进行管理；工人阶级为了不致失去刚刚争得的统治，一方面应当铲除全部旧的、一直被利用来反对它的压迫机器，另一方面应当以宣布它自己所有的代表和官吏毫无例外地可以随时撤换，来保证自己有可能防范他们。……”［注：见《马克思恩格斯全集》第22卷第226—227页。——编者注］","language":"中文","translation":false},{"id":"state-5-86","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":86,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯一再着重指出，不仅在君主国，而且在民主共和国，国家依然是国家，也就是说仍然保留着它的基本特征：把公职人员，“社会公仆”，社会机关，变为社会的主人。","language":"中文","translation":false},{"id":"state-5-87","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":87,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……为了防止国家和国家机关由社会公仆变为社会主人——这种现象在至今所有的国家中都是不可避免的——公社采取了两个正确的办法。第一，它把行政、司法和国民教育方面的一切职位交给由普选选出的人担任，而且规定选举者可以随时撤换被选举者。第二，它对所有公职人员，不论职位高低，都只付给跟其他工人同样的工资。公社所曾付过的最高薪金是6000法郎［注：名义上约等于2400卢布，但按现在的汇率计算，约等于6000卢布。有些布尔什维克提议，例如在市杜马内，给9000卢布的薪金，而不提议全国以6000卢布（这个数目是足够的）为最高薪金，这是完全不可饶恕的。[31]］。这样，即使公社没有另外给各代表机构的代表以限权委托书，也能可靠地防止人们去追求升官发财了。……”［注：见《马克思恩格斯全集》第22卷第228页。——编者注］","language":"中文","translation":false},{"id":"state-5-88","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":88,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在这里接触到了一个有趣的界限，在这个界限上，彻底的民主变成了社会主义，同时也要求实行社会主义。因为，要消灭国家就必须把国家机关的职能变为非常简单的监督和计算的手续，使大多数居民，而后再使全体居民，都能够办理，都能够胜任。而要完全消除升官发财的思想，就必须使国家机关中那些无利可图但是“荣耀的”职位不能成为在银行和股份公司内找到肥缺的桥梁，象在一切最自由的资本主义国家内所经常看到的那样。","language":"中文","translation":false},{"id":"state-5-89","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":89,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"但是，恩格斯并没有犯有些马克思主义者在民族自决权问题上所犯的那种错误：他们说民族自决权在资本主义下是不可能实现的，而在社会主义下则是多余的。这种似乎很巧妙但实际上并不正确的论断，对于任何一种民主制度，包括给官吏发微薄薪金的办法在内，都可以套得上，因为在资本主义下彻底的民主制度是不可能的，而在社会主义下则任何民主都是会消亡的。","language":"中文","translation":false},{"id":"state-5-90","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":90,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"这是一种诡辩，正象一句古老的笑话所说的：一个人掉了一根头发，他是否就成了秃子呢？","language":"中文","translation":false},{"id":"state-5-91","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":91,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"彻底发展民主，找出彻底发展的种种形式，用实践来检验这些形式等等，这一切都是为社会革命进行斗争的基本任务之一。任何单独存在的民主制度都不会产生社会主义，但在实际生活中民主制度永远不会是“单独存在”，而总是“共同存在”的，它也会影响经济，推动经济的改造，受经济发展的影响等等。这就是活生生的历史辩证法。","language":"中文","translation":false},{"id":"state-5-92","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":92,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"“……这种炸毁旧的国家政权并以新的真正民主的国家政权来代替的情形，已经在《内战》第3章中作了详细的描述。但是这里再一次简单地谈到这种代替的几个特点，这是必要的，因为恰巧在德国，对国家的迷信，已经从哲学方面转到资产阶级甚至很多工人的一般意识中去了。按照哲学家的学说，国家是‘观念的实现’，或是译成了哲学语言的尘世的上帝王国，也就是永恒的真理和正义所借以实现或应当借以实现的场所。由此就产生了对国家以及一切有关国家的事物的盲目崇拜，由于人们从小就习惯于认为全社会的公共事业和公共利益只能用旧的方法来处理和保护，即通过国家及其收入极多的官吏来处理和保护，这种崇拜就更容易生根。人们以为，如果他们不再迷信世袭君主制而拥护民主共和制，那就已经是非常大胆地向前迈进了一步。实际上，国家无非是一个阶级镇压另一个阶级的机器，这一点即使在民主共和制下也丝毫不比在君主制下差。国家再好也不过是无产阶级在争取阶级统治的斗争胜利以后所继承下来的一个祸害；胜利了的无产阶级也将同公社一样，不得不立即尽量除去这个祸害的最坏方面，直到在新的自由的社会条件下成长起来的一代能够把这全部国家废物完全抛掉为止。”［注：见《马克思恩格斯全集》第22卷第228—229页。——编者注］","language":"中文","translation":false},{"id":"state-5-93","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":93,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯告诫德国人，叫他们在以共和制代替君主制的时候不要忘记社会主义关于一般国家问题的原理。他的告诫现在看起来好象是直接对策列铁里和切尔诺夫之流先生们的教训，因为他们在“联合的”实践中正好表现出对国家的迷信和盲目崇拜！","language":"中文","translation":false},{"id":"state-5-94","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":94,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"还应当指出两点：（1）恩格斯说，在民主共和制下，国家之为“一个阶级压迫另一个阶级的机器”，“丝毫不”比在君主制下“差”，但这决不等于说，压迫的形式对于无产阶级是无所谓的，象某些无政府主义者所“教导”的那样。阶级斗争和阶级压迫采取更广泛、更自由、更公开的形式，能够大大便于无产阶级为消灭一切阶级而进行的斗争。","language":"中文","translation":false},{"id":"state-5-95","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":95,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"（2）为什么只有新的一代才能够把这全部国家废物完全抛掉呢？这个问题是同民主的消除问题联系着的，现在我们就来谈这个问题。","language":"中文","translation":false},{"id":"state-5-96","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":96,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在谈到“社会民主党人”这个名称在科学上不正确的时候，曾连带说到这一点。","language":"中文","translation":false},{"id":"state-5-97","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":97,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯在给自己那本19世纪70年代主要是论述“国际”问题的文集（《〈人民国家报〉国际问题论文集》）作序（1894年1月3日，即恩格斯逝世前一年半）的时候写道，在所有的文章里，他都用“共产党人”这个名词，而不用“社会民主党人”，因为当时法国的蒲鲁东派和德国的拉萨尔派[32]都自称为社会民主党人。","language":"中文","translation":false},{"id":"state-5-98","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":98,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"恩格斯接着写道：“……因此对马克思和我来说，用如此有伸缩性的名称来表示我们特有的观点是绝对不行的。现在情况不同了，这个词〈“社会民主党人”〉也许可以过得去（mag passieren），虽然对于经济纲领不单纯是一般社会主义的而直接是共产主义的党来说，对于政治上的最终目的是消除整个国家因而也消除民主的党来说，这个词还是不确切的〈unpas-send，不恰当的〉。然而，对真正的〈黑体是恩格斯用的〉政党说来，名称总是不完全符合的；党在发展，名称却不变。”［注：见《马克思恩格斯全集》第22卷第490页。——编者注］","language":"中文","translation":false},{"id":"state-5-99","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":99,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"辩证法家恩格斯到临终时仍然忠于辩证法。他说：马克思和我有过一个很好的科学上很确切的党的名称，可是当时没有一个真正的即群众性的无产阶级政党。现在（19世纪末）真正的政党是有了，可是它的名称在科学上是不正确的。但这不要紧，“可以过得去”，只要党在发展，只要党意识到它的名称在科学上不确切，不让这一点妨碍它朝着正确的方向发展就行！","language":"中文","translation":false},{"id":"state-5-100","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":100,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"也许哪一位爱开玩笑的人会用恩格斯的话来安慰我们布尔什维克说：我们有真正的政党，它在很好地发展；就连“布尔什维克”这样一个毫无意义的奇怪的名词，这个除了表示我们在1903年布鲁塞尔—伦敦代表大会[33]上占多数这一完全偶然的情况外并没有什么其他意思的名词，也还“可以过得去”……现在，由于共和党人和“革命”市侩民主派在7、8月间对我党实行迫害，“布尔什维克”这个名词获得了全民的荣誉，除此而外，这种迫害还表明我党在真正的发展过程中迈进了多么巨大的具有历史意义的一步，在这个时候，也许连我自己也对我在4月间提出的改变我党名称的建议［注：参看《列宁全集》第2版第29卷《四月提纲初稿》、《在出席全俄工兵代表苏维埃会议的布尔什维克代表的会议上的报告》和《论无产阶级在这次革命中的任务》。——编者注］表示怀疑了。也许我要向同志们提出一个“妥协办法”：把我们党称为共产党，而把布尔什维克这个名词放在括号内……","language":"中文","translation":false},{"id":"state-5-101","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":101,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"但是党的名称问题远不及革命无产阶级对国家的态度问题重要。","language":"中文","translation":false},{"id":"state-5-102","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":102,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"人们通常在谈论国家问题的时候，老是犯恩格斯在这里所告诫的而我们在前面也顺便提到的那个错误。这就是：老是忘记国家的消灭也就是民主的消灭，国家的消亡也就是民主的消亡。","language":"中文","translation":false},{"id":"state-5-103","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":103,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"乍看起来，这样的论断似乎是极端古怪而难于理解的；甚至也许有人会耽心，是不是我们在期待一个不遵守少数服从多数的原则的社会制度，因为民主也就是承认这个原则。","language":"中文","translation":false},{"id":"state-5-104","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":104,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"不是的。民主和少数服从多数的原则不是一个东西。民主就是承认少数服从多数的国家，即一个阶级对另一个阶级、一部分居民对另一部分居民使用有系统的暴力的组织。","language":"中文","translation":false},{"id":"state-5-105","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":105,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"我们的最终目的是消灭国家，也就是消灭任何有组织有系统的暴力，消灭任何加在人们头上的暴力。我们并不期待一个不遵守少数服从多数的原则的社会制度。但是，我们在向往社会主义的同时深信：社会主义将发展为共产主义，而对人们使用暴力，使一个人服从另一个人、使一部分居民服从另一部分居民的任何必要也将随之消失，因为人们将习惯于遵守公共生活的起码规则，而不需要暴力和服从。","language":"中文","translation":false},{"id":"state-5-106","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":106,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"为了强调这个习惯的因素，恩格斯就说到了新的一代，他们是“在新的自由的社会条件下成长起来的一代，能够把这全部国家废物完全抛掉”，——这里所谓国家是指任何一种国家，其中也包括民主共和制的国家。","language":"中文","translation":false},{"id":"state-5-107","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":107,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"为了说明这一点，就必须分析国家消亡的经济基础问题。","language":"中文","translation":false},{"id":"state-5-108","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":108,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[22] 蒲鲁东主义是以法国无政府主义者皮·约·蒲鲁东为代表的小资产阶级社会主义流派，产生于19世纪40年代。蒲鲁东主义从小资产阶级立场出发批判资本主义所有制，把小商品生产和交换理想化，幻想使小资产阶级私有制永世长存。它主张建立“人民银行”和“交换银行”，认为它们能帮助工人购置生产资料，使之成为手工业者，并能保证他们“公平地”销售自己的产品。蒲鲁东主义反对任何国家和政府，否定任何权威和法律，宣扬阶级调和，反对政治斗争和暴力革命。马克思在《哲学的贫困》这部著作中，对蒲鲁东主义作了彻底的批判。列宁称蒲鲁东主义为不能领会工人阶级观点的市侩和庸人的痴想。蒲鲁东主义思想被资产阶级的理论家们广泛地利用来鼓吹阶级调和。——55。","language":"中文","translation":false},{"id":"state-5-109","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":109,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[23] 布朗基主义者是19世纪法国工人运动中由杰出的革命家路·奥·布朗基领导的一个派别。布朗基主义者不了解无产阶级的历史使命，忽视同群众的联系，而主张用密谋手段推翻资产阶级政府，建立革命政权，实行少数人的专政。列宁指出，布朗基主义者期待不通过无产阶级的阶级斗争，而通过少数知识分子的密谋使人类摆脱雇佣奴隶制。","language":"中文","translation":false},{"id":"state-5-110","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":110,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"巴黎公社失败以后，1872年秋天，在伦敦的布朗基派公社流亡者发表了题为《国际和革命》的小册子，宣布拥护《共产党宣言》这个科学共产主义的纲领。对此，恩格斯曾不止一次地予以肯定（参看《马克思恩格斯全集》第18卷第579—587页）。——56。","language":"中文","translation":false},{"id":"state-5-111","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":111,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[24] 指马克思的《政治冷淡主义》和恩格斯的《论权威》这两篇文章（见《马克思恩格斯全集》第18卷第334—340、341一344页）。——56。","language":"中文","translation":false},{"id":"state-5-112","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":112,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[25] 爱尔福特纲领指1891年10月举行的德国社会民主党爱尔福特代表大会通过的党纲。它取代了1875年的哥达纲领。爱尔福特纲领以马克思主义关于资本主义生产方式必然灭亡和被社会主义生产方式所代替的学说为基础，强调工人阶级必须进行政治斗争，指出了党作为这一斗争的领导者的作用。它是德国社会民主党历史上第一个也是唯一的马克思主义的纲领。它的通过标志着马克思主义对拉萨尔主义等小资产阶级思潮的胜利。但是爱尔福特纲领也有一些重大缺点，主要是没有提出为民主共和国而斗争的任务，避而不谈无产阶级专政的问题。恩格斯曾对爱尔损特纲领的草案提出过批评，可是他的一些重要意见在纲领定稿时没有被采纳。——64。","language":"中文","translation":false},{"id":"state-5-113","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":113,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[26] 反社会党人法即《反对社会民主党企图危害治安的法令》，是德国俾斯麦政府从1878年10月起实行的镇压工人运动的反动法令。这个法令规定取缔德国社会民主党和一切进步工人组织，封闭工人刊物，没收社会主义书报，并可不经法律手续把革命者逮捕和驱逐出境。在反社会党人法实施期间，有1000多种书刊被查禁，300多个工人组织被解散，2000多人被监禁和驱逐。在工人运动压力下，反社会党人法于1890年10月被废除。——66。","language":"中文","translation":false},{"id":"state-5-114","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":114,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[27] 《真理报》（《Правда》）是俄国布尔什维克的合法报纸（日报），根据俄国社会民主工党第六次（布拉格）全国代表会议的决定创办，1912年4月22日（5月5日）起在彼得堡出版。《真理报》经常受到沙皇政府的迫害，曾多次被查封。1914年7月8日，即在第一次世界大战前夕，沙皇政府下令禁止《真理报》出版。1917年二月革命后，《真理报》于3月5日（18日）复刊，成为俄国社会民主工党中央委员会和彼得堡委员会的机关报。1917年七月事变中，《真理报》编辑部于7月5日（18日）被士官生捣毁。7月15日（28日），资产阶级临时政府正式下令封闭《真理报》。7—10月，该报曾先后改称《〈真理报〉小报》、《无产者报》、《工人日报》、《工人之路报》。1917年10月27日（11月9日），《真理报》恢复原名，继续作为俄国社会民主工党中央委员会的机关报出版。1918年3月16日起，《真理报》改在莫斯科出版。——70。","language":"中文","translation":false},{"id":"state-5-115","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":115,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[28] 列宁谈到伊·格·策列铁里在1917年6月11日的演说中声言要解除工人武装的问题时，曾不止一次地拿法国将军路·欧·卡芬雅克的行为来对比。关于这个问题，可参看《现在和“将来出现”卡芬雅克分子的阶级根源是什么？》一文（见《列宁全集》第2版第30卷第314—317页）。——72。","language":"中文","translation":false},{"id":"state-5-116","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":116,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[29] 指俄国临时政府部长、孟什维克伊·格·策列铁里1917年6月11日（24日）在全俄苏维埃第一次代表大会主席团、彼得格勒工兵代表苏维埃执行委员会、农民代表苏维埃执行委员会和代表大会各党团委员会联席会议上发表的演说。社会革命党和孟什维克首领召开这次会议，把布尔什维克党原定于6月10日（23日）举行游行示威的问题列入议程，是要利用自己的多数地位来打击布尔什维克党。策列铁里在他的演说中诬蔑布尔什维克准备举行的游行示威是“企图推翻政府和夺取政权的阴谋”，说什么“布尔什维克现在从事的不是思想宣传，而是阴谋。批判的武器正在被武器的批判所代替。……对于那些不善于恰当掌握手中武器的革命者，要从他们手中把武器夺走。必须解除布尔什维克的武装。不能让他们迄今拥有的过多的技术兵器留在他们手里。不能让机关枪和武器留在他们手里”。列宁指出，策列铁里的演说表明他是露骨的反革命分子。——72。","language":"中文","translation":false},{"id":"state-5-117","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":117,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[30] 与教会分离的运动，又称退出教会的运动，是第一次世界大战前在德国发生的群众性的反教会运动。1914年1月，德国社会民主党的理论刊物《新时代》杂志发表了修正主义者保尔·格雷的《与教会分离运动和社会民主党》一文，开始就党对待反教会运动的态度问题展开讨论。格雷断言党应当对这一运动取中立态度，应当禁止党员以党的名义进行反宗教和反教会的宣传。而德国社会民主党的著名活动家们在讨论过程中始终没有批判格雷的错误。——73。","language":"中文","translation":false},{"id":"state-5-118","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":118,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[31] 这里说的是1917年下半年的纸币。俄国的纸卢布在第一次世界大战期间贬值得很厉害。——74。","language":"中文","translation":false},{"id":"state-5-119","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":119,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[32] 拉萨尔派是全德工人联合会的成员，德国小资产阶级社会主义者斐·拉萨尔的拥护者。全德工人联合会在1863年于莱比锡召开的全德工人代表大会上成立，拉萨尔是它的第一任主席。他为联合会制订了纲领和策略基础，规定争取普选权和建立由国家帮助的工人生产合作社为联合会的政治纲领和经济纲领。在实践活动中，拉萨尔派支持奥·俾斯麦的在普鲁士领导下通过王朝战争自上而下统一德国的政策。马克思和恩格斯曾多次尖锐地批判拉萨尔主义的理论、策略和组织原则，指出它是德国工人运动中的机会主义派别。1875年，拉萨尔派同爱森纳赫派合并成了德国社会主义工人党。——77。","language":"中文","translation":false},{"id":"state-5-120","author":"列宁","title":"国家与革命","location":"第四章 续前。恩格斯的补充说明","page":5,"paragraph":120,"url":"https://www.marxists.org/chinese/lenin/191708-09/05.htm","text":"[33] 指1903年7月17日（30日）—8月10日（23日）举行的俄国社会民主工党第二次代表大会。大会先在布鲁塞尔开了13次会议，后因受警察迫寄迁移到伦敦继续进行。这次代表大会是《火星报》筹备的。大会一致批准了《火星报》编辑部拟定的党纲（一票弃权），并基本批准了列宁拟定的党章，但是在党章第一条这个有关党员资格的重要问题上，却以微弱多数通过了尔·马尔托夫的机会主义条文。以列宁为首的坚定的火星派和以马尔托夫为首的“温和的”火星派发生了分裂。在选举中央领导机关时，由于崩得和经济派分子退出了大会，列宁派获得了多数票，从此被称为布尔什维克（多数派），机会主义分子获得了少数票，从此被称为孟什维克（少数派）。这次代表大会对俄国工人运动的发展具有重大意义。列宁曾经指出，布尔什维主义是从1903年起作为一种政治思想派别和一个政党而存在的。——77。","language":"中文","translation":false},{"id":"state-6-1","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-6-2","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"第五章 国家消亡的经济基础","language":"中文","translation":false},{"id":"state-6-3","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"2．从资本主义到共产主义的过渡","language":"中文","translation":false},{"id":"state-6-4","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"3．共产主义社会的第一阶段","language":"中文","translation":false},{"id":"state-6-5","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"4．共产主义社会的高级阶段","language":"中文","translation":false},{"id":"state-6-6","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思在他的《哥达纲领批判》（即1875年5月5日给白拉克的信，这封信直到1891年才在《新时代》第9年卷第1册上发表，有俄文单行本）［注：见《马克思恩格斯全集》第19卷第11—35页。——编者注］中对这个问题作了最详尽的说明。在这篇出色的著作中，批判拉萨尔主义的论战部分可以说是遮盖了正面论述的部分，即遮盖了对共产主义发展和国家消亡之间的联系的分析。","language":"中文","translation":false},{"id":"state-6-7","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"如果把马克思在1875年5月5日给白拉克的信同我们在前面研究过的恩格斯在1875年3月28日给倍倍尔的信粗略地对照一下，也许会觉得马克思比恩格斯带有浓厚得多的“国家派”色彩，也许会觉得这两位著作家对国家的看法有很大差别。","language":"中文","translation":false},{"id":"state-6-8","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"恩格斯建议倍倍尔根本抛弃关于国家的废话，把国家一词从纲领中完全去掉而用“公团”一词来代替；恩格斯甚至宣布公社已经不是原来意义上的国家。而马克思却谈到“未来共产主义社会的国家制度”［注：见《马克思恩格斯全集》第19卷第31页。——编者注］，这就是说，似乎他认为就是在共产主义下也还需要国家。","language":"中文","translation":false},{"id":"state-6-9","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但这种看法是根本不对的。如果仔细研究一下就可以知道，马克思和恩格斯对国家和国家消亡问题的看法是完全一致的，上面所引的马克思的话指的正是正在消亡的国家制度。","language":"中文","translation":false},{"id":"state-6-10","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"很清楚，确定未来的“消亡”的日期，这是无从谈起的，何况它显然还是一个很长的过程。马克思和恩格斯之间仿佛存在差别，是因为他们研究的题目不同，要解决的任务不同。恩格斯的任务是要清楚地、尖锐地、概括地向倍倍尔指明，当时流行的（也是拉萨尔颇为赞同的）关于国家问题的偏见是十分荒谬的。而马克思只是在论述另一个题目即共产主义社会的发展时，顺便提到了这个问题。","language":"中文","translation":false},{"id":"state-6-11","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思的全部理论，就是运用最彻底、最完整、最周密、内容最丰富的发展论去考察现代资本主义。自然，他也就要运用这个理论去考察资本主义的即将到来的崩溃和未来共产主义的未来的发展。","language":"中文","translation":false},{"id":"state-6-12","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"究竟根据什么材料可以提出未来共产主义的未来发展问题呢？","language":"中文","translation":false},{"id":"state-6-13","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"这里所根据的是，共产主义是从资本主义中产生出来的，它是历史地从资本主义中发展出来的，它是资本主义所产生的那种社会力量发生作用的结果。马克思丝毫不想制造乌托邦，不想凭空猜测无法知道的事情。马克思提出共产主义的问题，正象一个自然科学家已经知道某一新的生物变种是怎样产生以及朝着哪个方向演变才提出该生物变种的发展问题一样。","language":"中文","translation":false},{"id":"state-6-14","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思首先扫除了哥达纲领在国家同社会的相互关系问题上造成的糊涂观念。","language":"中文","translation":false},{"id":"state-6-15","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"他写道：“……现代社会就是存在于一切文明国度中的资本主义社会，它或多或少地摆脱了中世纪的杂质，或多或少地由于每个国度的特殊的历史发展而改变了形态，或多或少地有了发展。‘现代国家’却随国境而异。它在普鲁士德意志帝国同在瑞士不一样，在英国同在美国不一样。所以，‘现代国家’是一种虚构。","language":"中文","translation":false},{"id":"state-6-16","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但是，不同的文明国度中的不同的国家，不管它们的形式如何纷繁，却有一个共同点：它们都建立在资本主义多少已经发展了的现代资产阶级社会的基础上。所以，它们具有某些根本的共同特征。在这个意义上可以谈‘现代国家制度’，而未来就不同了，到那时‘现代国家制度’现在的根基即资产阶级社会已经消亡了。","language":"中文","translation":false},{"id":"state-6-17","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"于是就产生了一个问题：在共产主义社会中国家制度会发生怎样的变化呢？换句话说，那时有哪些同现在的国家职能相类似的社会职能保留下来呢？这个问题只能科学地回答；否则，即使你把‘人民’和‘国家’这两个词联接一千次，也丝毫不会对这个问题的解决有所帮助。……”［注：见《马克思恩格斯全集》第19卷第30—31页。——编者注］","language":"中文","translation":false},{"id":"state-6-18","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思这样讥笑了关于“人民国家”的一切空话以后，就来提出问题，并且好象是告诫说：要对这个问题作出科学的解答，只有依靠确实肯定了的科学材料。","language":"中文","translation":false},{"id":"state-6-19","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"由整个发展论和全部科学十分正确地肯定了的首要的一点，也是从前被空想主义者所忘记、现在又被害怕社会主义革命的现代机会主义者所忘记的那一点，就是在历史上必然会有一个从资本主义向共产主义过渡的特殊时期或特殊阶段。","language":"中文","translation":false},{"id":"state-6-20","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"2．从资本主义到共产主义的过渡","language":"中文","translation":false},{"id":"state-6-21","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思继续写道：“……在资本主义社会和共产主义社会之间，有一个从前者变为后者的革命转变时期。同这个时期相适应的也有一个政治上的过渡时期，这个时期的国家只能是无产阶级的革命专政。……”［注：同上，第31页。——编者注］","language":"中文","translation":false},{"id":"state-6-22","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"这个结论是马克思根据他对无产阶级在现代资本主义社会中的作用的分析，根据关于这个社会发展情况的材料以及关于无产阶级与资产阶级对立的利益不可调和的材料所得出的。","language":"中文","translation":false},{"id":"state-6-23","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"从前，问题的提法是这样的：无产阶级为了求得自身的解放，应当推翻资产阶级，夺取政权，建立自己的革命专政。","language":"中文","translation":false},{"id":"state-6-24","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"现在，问题的提法已有些不同了：从向着共产主义发展的资本主义社会过渡到共产主义社会，非经过一个“政治上的过渡时期”不可，而这个时期的国家只能是无产阶级的革命专政。","language":"中文","translation":false},{"id":"state-6-25","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"这个专政和民主的关系又是怎样的呢？","language":"中文","translation":false},{"id":"state-6-26","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"我们看到，《共产党宣言》是干脆把“无产阶级转化成统治阶级”和“争得民主”［注：见《马克思恩格斯全集》第4卷第489页。——编者注］这两个概念并列在一起的。根据上述一切，可以更准确地断定民主在从资本主义向共产主义过渡时是怎样变化的。","language":"中文","translation":false},{"id":"state-6-27","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"在资本主义社会里，在它最顺利的发展条件下，比较完全的民主制度就是民主共和制。但是这种民主制度始终受到资本主义剥削制度狭窄框子的限制，因此它实质上始终是少数人的即只是有产阶级的、只是富人的民主制度。资本主义社会的自由始终与古希腊共和国的自由即奴隶主的自由大致相同。由于资本主义剥削制度的条件，现代的雇佣奴隶被贫困压得喘不过气，结果都“无暇过问民主”，“无暇过问政治”，大多数居民在通常的平静的局势下都被排斥在社会政治生活之外。","language":"中文","translation":false},{"id":"state-6-28","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"德国可以说是证实这一论断的最明显的例子，因为在这个国家里，宪法规定的合法性保持得惊人地长久和稳定，几乎有半世纪之久（1871—1914年），而在这个时期内，同其他国家的社会民主党相比，德国社会民主党又做了多得多的工作来“利用合法性”，来使工人参加党的比例达到举世未有的高度。","language":"中文","translation":false},{"id":"state-6-29","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":29,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"这种在资本主义社会里能看到的有政治觉悟的积极的雇佣奴隶所占的最大的百分比究竟是多少呢？1500万雇佣工人中有100万是社会民主党党员！1500万雇佣工人中有300万是工会会员！","language":"中文","translation":false},{"id":"state-6-30","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":30,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"极少数人享受民主，富人享受民主，——这就是资本主义社会的民主制度。如果仔细地考察一下资本主义民主的结构，那么无论在选举权的一些“微小的”（似乎是微小的）细节上（居住年限、妇女被排斥等等），或是在代表机构的办事手续上，或是在行使集会权的实际障碍上（公共建筑物不准“叫化子”使用！），或是在纯粹资本主义的办报原则上，等等，到处都可以看到对民主制度的重重限制。用来对付穷人的这些限制、例外、排斥、阻碍，看起来似乎是很微小的，特别是在那些从来没有亲身体验过贫困、从来没有接近过被压迫阶级群众的生活的人（这种人在资产阶级的政论家和政治家中，如果不占百分之九十九，也得占十分之九）看起来是很微小的，但是这些限制加在一起，就把穷人排斥和推出政治生活之外，使他们不能积极参加民主生活。","language":"中文","translation":false},{"id":"state-6-31","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":31,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思正好抓住了资本主义民主的这一实质，他在分析公社的经验时说：这就是容许被压迫者每隔几年决定一次究竟由压迫阶级中的什么人在议会里代表和镇压他们！［注：参看《马克思恩格斯全集》第17卷第360页。——编者注］","language":"中文","translation":false},{"id":"state-6-32","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":32,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但是从这种必然是狭隘的、暗中排斥穷人的、因而也是彻头彻尾虚伪骗人的资本主义民主向前发展，并不象自由派教授和小资产阶级机会主义者所想象的那样，是简单地、直线地、平稳地走向“日益彻底的民主”。不是的。向前发展，即向共产主义发展，必须经过无产阶级专政，不可能走别的道路，因为再没有其他人也没有其他道路能够粉碎剥削者资本家的反抗。","language":"中文","translation":false},{"id":"state-6-33","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":33,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"而无产阶级专政，即被压迫者先锋队组织成为统治阶级来镇压压迫者，不能仅仅只是扩大民主。除了把民主制度大规模地扩大，使它第一次成为穷人的、人民的而不是富人的民主制度之外，无产阶级专政还要对压迫者、剥削者、资本家采取一系列剥夺自由的措施。为了使人类从雇佣奴隶制下面解放出来，我们必须镇压这些人，必须用强力粉碎他们的反抗，——显然，凡是实行镇压和使用暴力的地方，也就没有自由，没有民主。","language":"中文","translation":false},{"id":"state-6-34","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":34,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"读者总还记得，恩格斯在给倍倍尔的信中很好地阐明了这一点，他说：“无产阶级需要国家不是为了自由，而是为了镇压自己的敌人，一到有可能谈自由的时候，国家本身就不再存在了。”［注：见《马克思恩格斯全集》第19卷第7页。——编者注］","language":"中文","translation":false},{"id":"state-6-35","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":35,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"人民这个大多数享有民主，对人民的剥削者、压迫者实行强力镇压，即把他们排斥于民主之外，——这就是民主在从资本主义向共产主义过渡时改变了的形态。","language":"中文","translation":false},{"id":"state-6-36","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":36,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"只有在共产主义社会中，当资本家的反抗已经彻底粉碎，当资本家已经消失，当阶级已经不存在（即社会各个成员在同社会生产资料的关系上已经没有差别）的时候，——只有在那个时候，“国家才会消失，才有可能谈自由”。只有在那个时候，真正完全的、真正没有任何例外的民主才有可能，才会实现。也只有在那个时候，民主才开始消亡，道理很简单：人们既然摆脱了资本主义奴隶制，摆脱了资本主义剥削制所造成的无数残暴、野蛮、荒谬和丑恶的现象，也就会逐渐习惯于遵守多少世纪以来人们就知道的、千百年来在一切行为守则上反复谈到的、起码的公共生活规则，而不需要暴力，不需要强制，不需要服从，不需要所谓国家这种实行强制的特殊机构。","language":"中文","translation":false},{"id":"state-6-37","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":37,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"“国家消亡”这个说法选得非常恰当，因为它既表明了过程的渐进性，又表明了过程的自发性。只有习惯才能够发生而且一定会发生这样的作用，因为我们在自己的周围千百万次地看到，如果没有剥削，如果根本没有令人气愤、引起抗议和起义而使镇压成为必要的现象，那么人们是多么容易习惯于遵守他们所必需的公共生活规则。","language":"中文","translation":false},{"id":"state-6-38","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":38,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"总之，资本主义社会里的民主是一种残缺不全的、贫乏的和虚伪的民主，是只供富人、只供少数人享受的民主。无产阶级专政，向共产主义过渡的时期，将第一次提供人民享受的、大多数人享受的民主，同时对少数人即剥削者实行必要的镇压。只有共产主义才能提供真正完全的民主，而民主愈完全，它也就愈迅速地成为不需要的东西，愈迅速地自行消亡。","language":"中文","translation":false},{"id":"state-6-39","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":39,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"换句话说，在资本主义下存在的是原来意义上的国家，即一个阶级对另一个阶级、而且是少数人对多数人实行镇压的特殊机器。很明显，剥削者少数要能有系统地镇压被剥削者多数，就必须实行极凶狠极残酷的镇压，就必须造成大量的流血，而人类在奴隶制、农奴制和雇佣劳动制下就是这样走过来的。","language":"中文","translation":false},{"id":"state-6-40","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":40,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"其次，在从资本主义向共产主义过渡的时候镇压还是必要的，但这已经是被剥削者多数对剥削者少数的镇压。实行镇压的特殊机构，特殊机器，即“国家”，还是必要的，但这已经是过渡性质的国家，已经不是原来意义上的国家，因为由昨天还是雇佣奴隶的多数人去镇压剥削者少数人，相对来说，还是一件很容易、很简单和很自然的事情，所流的血会比镇压奴隶、农奴和雇佣工人起义流的少得多，人类为此而付出的代价要小得多。而且在实行镇压的同时，还把民主扩展到绝大多数居民身上，以致对实行镇压的特殊机器的需要就开始消失。自然，剥削者没有极复杂的实行镇压的机器就镇压不住人民，但是人民镇压剥削者却只需要有很简单的“机器”，即几乎可以不要“机器”，不要特殊的机构，而只需要有简单的武装群众的组织（如工兵代表苏维埃，——我们先在这里提一下）。","language":"中文","translation":false},{"id":"state-6-41","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":41,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"最后，只有共产主义才能够完全不需要国家，因为没有人需要加以镇压了，——这里所谓“没有人”是指阶级而言，是指对某一部分居民进行有系统的斗争而言。我们不是空想主义者，我们丝毫也不否认个别人采取极端行动的可能性和必然性，同样也不否认有镇压这种行动的必要性。但是，第一，做这件事情用不着什么实行镇压的特殊机器，特殊机构，武装的人民自己会来做这项工作，而且做起来非常简单容易，就象现代社会中任何一群文明人强行拉开打架的人或制止虐待妇女一样。第二，我们知道，产生违反公共生活规则的极端行动的根本社会原因是群众受剥削和群众贫困。这个主要原因一消除，极端行动就必然开始“消亡”。虽然我们不知道消亡的速度和过程怎样，但是，我们知道这种行动一定会消亡。而这种行动一消亡，国家也就随之消亡。","language":"中文","translation":false},{"id":"state-6-42","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":42,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"关于这个未来，马克思并没有陷入空想，他只是较详细地确定了现在所能确定的东西，即共产主义社会低级阶段和高级阶段之间的差别。","language":"中文","translation":false},{"id":"state-6-43","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":43,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"3．共产主义社会的第一阶段","language":"中文","translation":false},{"id":"state-6-44","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":44,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思在《哥达纲领批判》中，详细地驳斥了拉萨尔关于劳动者在社会主义下将领取“不折不扣的”或“全部的劳动产品”的思想。马克思指出，从整个社会的全部社会劳动中，必须扣除后备基金、扩大生产的基金和机器“磨损”的补偿等等，然后从消费品中还要扣除用作管理费用以及用于学校、医院、养老院等等的基金。","language":"中文","translation":false},{"id":"state-6-45","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":45,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思不象拉萨尔那样说些含糊不清的笼统的话（“全部劳动产品归劳动者”），而是对社会主义社会必须怎样管理的问题作了冷静的估计。马克思具体地分析了这种没有资本主义存在的社会的生活条件，他说：","language":"中文","translation":false},{"id":"state-6-46","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":46,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"“我们这里所说的〈在分析工人党的纲领时〉是这样的共产主义社会，它不是在它自身基础上已经发展了的，恰好相反，是刚刚从资本主义社会中产生出来的，因此它在各方面，在经济、道德和精神方面都还带着它脱胎出来的那个旧社会的痕迹。”［注：见《马克思恩格斯全集》第19卷第21页。——编者注］","language":"中文","translation":false},{"id":"state-6-47","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":47,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"就是这个刚刚从资本主义脱胎出来的在各方面还带着旧社会痕迹的共产主义社会，马克思称之为共产主义社会的“第一”阶段或低级阶段。","language":"中文","translation":false},{"id":"state-6-48","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":48,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"生产资料已经不是个人的私有财产。它们已归全社会所有。社会的每个成员完成一定份额的社会必要劳动，就从社会领得一张凭证，证明他完成了多少劳动量。他根据这张凭证从消费品的社会储存中领取相应数量的产品。这样，扣除了用作社会基金的那部分劳动量，每个劳动者从社会领回的正好是他给予社会的。","language":"中文","translation":false},{"id":"state-6-49","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":49,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但是，当拉萨尔把这样的社会制度（通常叫做社会主义，而马克思称之为共产主义的第一阶段）说成是“公平的分配”，说成是“每人有获得同等劳动产品的平等的权利”的时候，他是错误的，于是马克思对他的错误进行了分析。","language":"中文","translation":false},{"id":"state-6-50","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":50,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思说：这里确实有“平等的权利”，但这仍然是“资产阶级权利”，这个“资产阶级权利”同任何权利一样，是以不平等为前提的。任何权利都是把同一标准应用在不同的人身上，即应用在事实上各不相同、各不同等的人身上，因而“平等的权利”就是破坏平等，就是不公平。的确，每个人付出与别人同等份额的社会劳动，就能领取同等份额的社会产品（作了上述各项扣除之后）。","language":"中文","translation":false},{"id":"state-6-51","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":51,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"然而各个人是不同等的：有的强些，有的弱些；有的结了婚，有的没有结婚，有的子女多些，有的子女少些，如此等等。","language":"中文","translation":false},{"id":"state-6-52","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":52,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思总结说：“……因此，在提供的劳动相同、从而由社会消费基金中分得的份额相同的条件下，某一个人事实上所得到的比另一个人多些，也就比另一个人富些，如此等等。要避免所有这些弊病，权利就不应当是平等的，而应当是不平等的。……”［注：见《马克思恩格斯全集》第19卷第22页。——编者注］","language":"中文","translation":false},{"id":"state-6-53","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":53,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"可见，在共产主义第一阶段还不能做到公平和平等，因为富裕的程度还会不同，而不同就是不公平。但是人剥削人已经不可能了，因为已经不能把工厂、机器、土地等生产资料攫为私有了。马克思通过驳斥拉萨尔泛谈一般“平等”和“公平”的含糊不清的小资产阶级言论，指出了共产主义社会的发展进程，说明这个社会最初只能消灭私人占有生产资料这一“不公平”现象，却不能立即消灭另一不公平现象：“按劳动”（而不是按需要）分配消费品。","language":"中文","translation":false},{"id":"state-6-54","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":54,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"庸俗的经济学家，包括资产阶级教授，包括“我们的”杜冈在内，经常谴责社会主义者，说他们忘记了人与人的不平等，说他们“幻想”消灭这种不平等。我们看到，这种谴责只能证明资产阶级思想家先生们的极端无知。［注：对杜冈的批判，还可参看列宁《自由派教授论平等》一文（《列宁全集》第2版第24卷）。——编者注］","language":"中文","translation":false},{"id":"state-6-55","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":55,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思不仅极其准确地估计到了人们不可避免的不平等，而且还估计到：仅仅把生产资料转归全社会公有（通常所说的“社会主义”）还不能消除分配方面的缺点和“资产阶级权利”的不平等，只要产品“按劳动”分配，“资产阶级权利”就会继续通行。","language":"中文","translation":false},{"id":"state-6-56","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":56,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思继续说道：“……但是这些弊病，在经过长久阵痛刚刚从资本主义社会产生出来的共产主义社会第一阶段，是不可避免的。权利决不能超出社会的经济结构以及由经济结构制约的社会的文化发展。……”［注：见《马克思恩格斯全集》第19卷第22页。——编者注］","language":"中文","translation":false},{"id":"state-6-57","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":57,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"因此，在共产主义社会的第一阶段（通常称为社会主义），“资产阶级权利”没有完全取消，而只是部分地取消，只是在已经实现的经济变革的限度内取消，即只是在同生产资料的关系上取消。“资产阶级权利”承认生产资料是个人的私有财产。而社会主义则把生产资料变为公有财产。在这个范围内，也只是在这个范围内，“资产阶级权利”才不存在了。","language":"中文","translation":false},{"id":"state-6-58","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":58,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但是它在它的另一部分却依然存在，依然是社会各个成员间分配产品和分配劳动的调节者（决定者）。“不劳动者不得食”这个社会主义原则已经实现了；“对等量劳动给予等量产品”这个社会主义原则也已经实现了。但是，这还不是共产主义，还没有消除对不同等的人的不等量（事实上是不等量的）劳动给予等量产品的“资产阶级权利”。","language":"中文","translation":false},{"id":"state-6-59","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":59,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"马克思说，这是一个“弊病”，但在共产主义第一阶段是不可避免的，因为，如果不愿陷入空想主义，那就不能认为，在推翻资本主义之后，人们立即就能学会不要任何权利准则而为社会劳动，况且资本主义的废除不能立即为这种变更创造经济前提。","language":"中文","translation":false},{"id":"state-6-60","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":60,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"可是，除了“资产阶级权利”以外，没有其他准则。所以就这一点说，还需要有国家在保卫生产资料公有制的同时来保卫劳动的平等和产品分配的平等。","language":"中文","translation":false},{"id":"state-6-61","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":61,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"国家正在消亡，因为资本家已经没有了，阶级已经没有了，因而也就没有什么阶级可以镇压了。","language":"中文","translation":false},{"id":"state-6-62","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":62,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但是，国家还没有完全消亡，因为还要保卫那个确认事实上的不平等的“资产阶级权利”。要使国家完全消亡，必须有完全的共产主义。","language":"中文","translation":false},{"id":"state-6-63","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":63,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"4．共产主义社会的高级阶段","language":"中文","translation":false},{"id":"state-6-64","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":64,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"“……在共产主义社会高级阶段，在迫使个人奴隶般地服从分工的情形已经消失之后；在脑力劳动和体力劳动的对立也随之消失之后；在劳动已经不仅仅是谋生的手段，而且本身成了生活的第一需要之后；在随着个人的全面发展生产力也增长起来，而集体财富的一切源泉都充分涌流之后，——只有在那个时候，才能完全超出资产阶级权利的狭隘眼界，社会才能在自己的旗帜上写上：‘各尽所能，按需分配’。”［注：见《马克思恩格斯全集》第19卷第22—23页。——编者注］","language":"中文","translation":false},{"id":"state-6-65","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":65,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"只是现在我们才可以充分地认识到，恩格斯无情地讥笑那种把“自由”和“国家”这两个名词连在一起的荒谬见解，是多么正确。还有国家的时候就没有自由。到有自由的时候就不会有国家了。","language":"中文","translation":false},{"id":"state-6-66","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":66,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"国家完全消亡的经济基础就是共产主义的高度发展，那时脑力劳动和体力劳动的对立已经消失，因而现代社会不平等的最重要的根源之一也就消失，而这个根源光靠把生产资料转为公有财产，光靠剥夺资本家，是决不能立刻消除的。","language":"中文","translation":false},{"id":"state-6-67","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":67,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"这种剥夺会使生产力有蓬勃发展的可能。我们看到，资本主义目前已经在令人难以置信地阻碍这种发展，而在现代已经达到的技术水平的基础上本来是可以大有作为的，因此我们可以绝对有把握地说，剥夺资本家一定会使人类社会的生产力蓬勃发展。但是，生产力将以什么样的速度向前发展，将以什么样的速度发展到打破分工、消灭脑力劳动和体力劳动的对立、把劳动变为“生活的第一需要”，这都是我们所不知道而且也不可能知道的。","language":"中文","translation":false},{"id":"state-6-68","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":68,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"因此，我们只能谈国家消亡的必然性，同时着重指出这个过程是长期的，指出它的长短将取决于共产主义高级阶段的发展速度，而把消亡的日期或消亡的具体形式问题作为悬案，因为现在还没有可供解决这些问题的材料。","language":"中文","translation":false},{"id":"state-6-69","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":69,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"当社会实现“各尽所能，按需分配”的原则时，也就是说，当人们已经十分习惯于遵守公共生活的基本规则，他们的劳动生产率已经极大地提高，以致他们能够自愿地尽其所能来劳动的时候，国家才会完全消亡。那时，就会超出“资产阶级权利的狭隘眼界”，超出这种使人象夏洛克[34]那样冷酷地斤斤计较，不愿比别人多做半小时工作，不愿比别人少得一点报酬的狭隘眼界。那时，分配产品就无需社会规定每人应当领取的产品数量；每人将“按需”自由地取用。","language":"中文","translation":false},{"id":"state-6-70","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":70,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"从资产阶级的观点看来，很容易把这样的社会制度说成是“纯粹的乌托邦”，并冷嘲热讽地说社会主义者许诺每个人都有权利向社会领取任何数量的巧克力糖、汽车、钢琴等等，而对每个公民的劳动不加任何监督。就是今天，大多数资产阶级“学者”也还在用这样的嘲讽来搪塞，他们这样做只是暴露他们愚昧无知和替资本主义进行自私的辩护。","language":"中文","translation":false},{"id":"state-6-71","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":71,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"说他们愚昧无知，是因为没有一个社会主义者想到过要“许诺”共产主义高级发展阶段的到来，而伟大的社会主义者在预见这个阶段将会到来时所设想的前提，既不是现在的劳动生产率，也不是现在的庸人，这种庸人正如波米亚洛夫斯基作品中的神学校学生一样，很会“无缘无故地”糟蹋社会财富的储存和提出不能实现的要求。","language":"中文","translation":false},{"id":"state-6-72","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":72,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"在共产主义的“高级”阶段到来以前，社会主义者要求社会和国家对劳动量和消费量实行极严格的监督，不过这种监督应当从剥夺资本家和由工人监督资本家开始，并且不是由官吏的国家而是由武装工人的国家来实行。","language":"中文","translation":false},{"id":"state-6-73","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":73,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"说资产阶级思想家（和他们的走卒，如策列铁里先生、切尔诺夫先生之流）替资本主义进行自私的辩护，正是因为他们一味争论和空谈遥远的未来，而不谈目前政治上的迫切问题：剥夺资本家，把全体公民变为一个大“辛迪加”即整个国家的工作者和职员，并使这整个辛迪加的全部工作完全服从真正民主的国家，即工兵代表苏维埃国家。","language":"中文","translation":false},{"id":"state-6-74","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":74,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"其实，当博学的教授，以及附和教授的庸人和策列铁里先生、切尔诺夫先生之流谈到荒诞的乌托邦，谈到布尔什维克的蛊惑人心的许诺，谈到“实施”社会主义不可能做到的时候，他们指的正是共产主义的高级阶段，但是无论是谁都不仅没有许诺过，而且连想也没有想到过“实施”共产主义的高级阶段，因为这根本无法“实施”。","language":"中文","translation":false},{"id":"state-6-75","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":75,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"这里我们也就接触到了社会主义和共产主义在科学上的差别问题，这个问题在上面引用的恩格斯说“社会民主党人”这个名称不正确的一段话里已经谈到。共产主义第一阶段或低级阶段同共产主义高级阶段之间的差别在政治上说将来也许很大，但现在在资本主义下来着重谈论它就很可笑了，把这个差别提到首要地位的也许只有个别无政府主义者（在克鲁泡特金之流、格拉弗、科尔纳利森和其他无政府主义“大师”们已经“象普列汉诺夫那样”变成了社会沙文主义者，或者如少数没有丧失廉耻和良心的无政府主义者之一格耶所说，变成了无政府主义卫国战士以后，如果无政府主义者当中还有人丝毫没有学到什么东西的话）。","language":"中文","translation":false},{"id":"state-6-76","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":76,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但是社会主义同共产主义在科学上的差别是很明显的。通常所说的社会主义，马克思把它称作共产主义社会的“第一”阶段或低级阶段。既然生产资料已成为公有财产，那么“共产主义”这个名词在这里也是可以用的，只要不忘记这还不是完全的共产主义。马克思的这些解释的伟大意义，就在于他在这里也彻底地运用了唯物主义辩证法，即发展学说，把共产主义看成是从资本主义中发展出来的。马克思没有经院式地臆造和“虚构”种种定义，没有从事毫无意义的字面上的争论（什么是社会主义，什么是共产主义），而是分析了可以称为共产主义在经济上成熟程度的两个阶段的东西。","language":"中文","translation":false},{"id":"state-6-77","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":77,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"在第一阶段，共产主义在经济上还不可能完全成熟，完全摆脱资本主义的传统或痕迹。由此就产生一个有趣的现象，这就是在共产主义第一阶段还保留着“资产阶级权利的狭隘眼界”。既然在消费品的分配方面存在着资产阶级权利，那当然一定要有资产阶级国家，因为如果没有一个能够强制人们遵守权利准则的机构，权利也就等于零。","language":"中文","translation":false},{"id":"state-6-78","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":78,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"可见，在共产主义下，在一定的时期内，不仅会保留资产阶级权利，甚至还会保留资产阶级国家，——但没有资产阶级！","language":"中文","translation":false},{"id":"state-6-79","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":79,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"这好象是奇谈怪论，或只是一种玩弄聪明的辩证把戏，那些没有花过一点功夫去研究马克思主义的极其深刻的内容的人，就常常这样来谴责马克思主义。","language":"中文","translation":false},{"id":"state-6-80","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":80,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"其实，无论在自然界或在社会中，实际生活随时随地都使我们看到新事物中有旧的残余。马克思并不是随便把一小块“资产阶级”权利塞到共产主义中去，而是抓住了从资本主义脱胎出来的社会里那种在经济上和政治上不可避免的东西。","language":"中文","translation":false},{"id":"state-6-81","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":81,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"在工人阶级反对资本家以争取自身解放的斗争中，民主具有巨大的意义。但是民主决不是不可逾越的极限，它只是从封建主义到资本主义和从资本主义到共产主义的道路上的阶段之一。","language":"中文","translation":false},{"id":"state-6-82","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":82,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"民主意味着平等。很明显，如果把平等正确地理解为消灭阶级，那么无产阶级争取平等的斗争以及平等的口号就具有极伟大的意义。但是，民主仅仅意味着形式上的平等。一旦社会全体成员在占有生产资料方面的平等即劳动平等、工资平等实现以后，在人类面前不可避免地立即就会产生一个问题：要更进一步，从形式上的平等进到事实上的平等，即实现“各尽所能，按需分配”的原则。至于人类会经过哪些阶段，通过哪些实际措施达到这个最高目的，那我们不知道，也不可能知道。可是，必须认识到：通常的资产阶级观念，即把社会主义看成一种僵死的、凝固的、一成不变的东西的这种观念，是非常荒谬的；实际上，只是从社会主义实现时起，社会生活和个人生活的各个领域才会开始出现迅速的、真正的、确实是群众性的即有大多数居民参加然后有全体居民参加的前进运动。","language":"中文","translation":false},{"id":"state-6-83","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":83,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"民主是国家形式，是国家形态的一种。因此，它同任何国家一样，也是有组织有系统地对人们使用暴力，这是一方面。但另一方面，民主意味着在形式上承认公民一律平等，承认大家都有决定国家制度和管理国家的平等权利。而这一点又会产生如下的结果：民主在其发展的某个阶段首先把对资本主义进行革命的阶级——无产阶级团结起来，使他们有可能去打碎、彻底摧毁、彻底铲除资产阶级的（哪怕是共和派资产阶级的）国家机器即常备军、警察和官吏，代之以武装的工人群众（然后是人民普遍参加民兵）这样一种更民主的机器，但这仍然是国家机器。","language":"中文","translation":false},{"id":"state-6-84","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":84,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"在这里，“量转化为质”，因为这样高度的民主制度，是同越出资产阶级社会的框子、开始对社会进行社会主义的改造相联系的。如果真是所有的人都参加国家管理，那么资本主义就不能支持下去。而资本主义的发展又为真是“所有的人”能够参加国家管理创造了前提。这种前提就是：在一些最先进的资本主义国家中已经做到的人人都识字，其次是千百万工人已经在邮局、铁路、大工厂、大商业企业、银行业等等巨大的、复杂的、社会化的机构里“受了训练并养成了遵守纪律的习惯”。","language":"中文","translation":false},{"id":"state-6-85","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":85,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"在这种经济前提下，完全有可能在推翻了资本家和官吏之后，在一天之内立刻着手由武装的工人、普遍武装的人民代替他们去监督生产和分配，计算劳动和产品。（不要把监督和计算的问题同具有科学知识的工程师和农艺师等等的问题混为一谈，这些先生今天在资本家的支配下工作，明天在武装工人的支配下会更好地工作。）","language":"中文","translation":false},{"id":"state-6-86","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":86,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"计算和监督，——这就是把共产主义社会第一阶段“调整好”，使它能正常地运转所必需的主要条件。在这里，全体公民都成了国家（武装工人）雇用的职员。全体公民都成了一个全民的、国家的“辛迪加”的职员和工人。全部问题在于要他们在正确遵守劳动标准的条件下同等地劳动，同等地领取报酬。对这些事情的计算和监督已被资本主义简化到了极点，而成为非常简单、任何一个识字的 人都能胜任的手续——进行监察和登记，算算加减乘除和发发有关的字据。［注：当国家的最主要职能简化为由工人自己来进行的这样一种计算和监督的时候，国家就不再是“政治国家”，“社会职能就由政治职能变为简单的管理职能”（参看上面第4章第2节恩格斯同无政府主义者的论战）。］","language":"中文","translation":false},{"id":"state-6-87","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":87,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"当大多数人对资本家（这时已成为职员）和保留着资本主义恶习的知识分子先生们开始独立进行和到处进行这种计算即这种监督的时候，这种监督就会成为真正包罗万象的、普遍的和全民的监督，对它就绝对无法逃避、“无处躲藏”了。","language":"中文","translation":false},{"id":"state-6-88","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":88,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"整个社会将成为一个管理处，成为一个劳动平等和报酬平等的工厂。","language":"中文","translation":false},{"id":"state-6-89","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":89,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"但是，无产阶级在战胜资本家和推翻剥削者以后在全社会推行的这种“工厂”纪律，决不是我们的理想，也决不是我们的最终目的，而只是为了彻底肃清社会上资本主义剥削制造成的卑鄙丑恶现象和为了继续前进所必需的一个阶段。","language":"中文","translation":false},{"id":"state-6-90","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":90,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"当社会全体成员或者哪怕是大多数成员自己学会了管理国家，自己掌握了这个事业，对极少数资本家、想保留资本主义恶习的先生们和深深受到资本主义腐蚀的工人们“调整好”监督的时候，对任何管理的需要就开始消失。民主愈完全，它成为多余的东西的时候就愈接近。由武装工人组成的、“已经不是原来意义上的国家”的“国家”愈民主，则任何国家就会愈迅速地开始消亡。","language":"中文","translation":false},{"id":"state-6-91","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":91,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"因为当所有的人都学会了管理，都来实际地独立地管理社会生产，对寄生虫、老爷、骗子等等“资本主义传统的保持者”独立地进行计算和监督的时候，逃避这种全民的计算和监督就必然会成为极难得逞的、极罕见的例外，可能还会受到极迅速极严厉的惩罚（因为武装工人是重实际的人，而不是重感情的知识分子；他们未必会让人跟自己开玩笑），以致人们对于人类一切公共生活的简单的基本规则就会很快从必须遵守变成习惯于遵守了。","language":"中文","translation":false},{"id":"state-6-92","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":92,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"到那时候，从共产主义社会的第一阶段过渡到它的高级阶段的大门就会敞开，国家也就随之完全消亡。","language":"中文","translation":false},{"id":"state-6-93","author":"列宁","title":"国家与革命","location":"第五章 国家消亡的经济基础","page":6,"paragraph":93,"url":"https://www.marxists.org/chinese/lenin/191708-09/06.htm","text":"[34] 夏洛克是英国作家威·莎士比亚的喜剧《威尼斯商人》中的人物，一个残忍冷酷的高利贷者。他曾根据借约提供的权利，要求从没有如期还债的商人安东尼奥身上割下一磅肉。——92。","language":"中文","translation":false},{"id":"state-7-1","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-7-2","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"第六章 马克思主义被机会主义者庸俗化","language":"中文","translation":false},{"id":"state-7-3","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"1．普列汉诺夫与无政府主义者的论战","language":"中文","translation":false},{"id":"state-7-4","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"2．考茨基与机会主义者的论战","language":"中文","translation":false},{"id":"state-7-5","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"3．考茨基与潘涅库克的论战","language":"中文","translation":false},{"id":"state-7-6","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"国家对社会革命的态度和社会革命对国家的态度问题，象整个革命问题一样，是第二国际（1889—1914年）最著名的理论家和政论家们很少注意的。但是，在机会主义逐渐滋长而使第二国际在1914年破产的过程中，最突出的一点就是：甚至当他们直接遇到这个问题的时候，他们还是竭力回避或者不加理会。","language":"中文","translation":false},{"id":"state-7-7","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"总的看来可以说，由于在无产阶级革命对国家的态度问题上采取了有利于机会主义和助长机会主义的躲躲闪闪的态度，结果就产生了对马克思主义的歪曲和对马克思主义的完全庸俗化。","language":"中文","translation":false},{"id":"state-7-8","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"为了说明（哪怕是简要地说明）这个可悲的过程，我们就拿最著名的马克思主义理论家普列汉诺夫和考茨基来说吧。","language":"中文","translation":false},{"id":"state-7-9","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"1．普列汉诺夫与无政府主义者的论战","language":"中文","translation":false},{"id":"state-7-10","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"普列汉诺夫写了一本专门论述无政府主义对社会主义的态度问题的小册子，书名叫《无政府主义和社会主义》，于1894年用德文出版。","language":"中文","translation":false},{"id":"state-7-11","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"普列汉诺夫竟有这样的本事，能够论述这个主题而完全回避反对无政府主义的斗争中最现实、最迫切、政治上最重要的问题，即革命对国家的态度和整个国家问题！他的这本小册子有两部分特别突出：一部分是历史文献，其中有关于施蒂纳和蒲鲁东等人思想演变的宝贵材料；另一部分是庸俗的，其中有关于无政府主义者与强盗没有区别这样拙劣的议论。","language":"中文","translation":false},{"id":"state-7-12","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这两个主题拼在一起十分可笑，很足以说明普列汉诺夫在俄国革命前夜以及革命时期的全部活动，因为在1905—1917年，普列汉诺夫正是这样表明自己是在政治上充当资产阶级尾巴的半学理主义者[35]，半庸人。","language":"中文","translation":false},{"id":"state-7-13","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"我们已经看到，马克思和恩格斯在同无政府主义者论战时，怎样极其详尽地说明了自己在革命对国家的态度问题上的观点。恩格斯在1891年出版马克思的《哥达纲领批判》时写道：“我们〈即恩格斯和马克思〉那时正在同巴枯宁及其无政府主义者进行最激烈的斗争，——那时离〈第一〉国际海牙代表大会[36]闭幕才两年。”［注：见《马克思恩格斯全集》第22卷第106页。——编者注］","language":"中文","translation":false},{"id":"state-7-14","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"无政府主义者正是企图把巴黎公社宣布为所谓“自己的”，说它证实了他们的学说，然而他们根本不懂得公社的教训和马克思对这些教训的分析。对于是否需要打碎旧的国家机器以及用什么东西来代替这两个具体政治问题，无政府主义者连一个比较接近真理的答案都没有提出过。","language":"中文","translation":false},{"id":"state-7-15","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"但是在谈“无政府主义和社会主义”时回避整个国家问题，不理会马克思主义在公社以前和以后的全部发展，那就必然会滚到机会主义那边去。因为机会主义求之不得的，正是完全不提我们刚才所指出的那两个问题。光是这一点，已经是机会主义的胜利了。","language":"中文","translation":false},{"id":"state-7-16","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"2．考茨基与机会主义者的论战","language":"中文","translation":false},{"id":"state-7-17","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基的著作译成俄文的无疑比译成其他各国文字的要多得多。难怪有些德国社会民主党人开玩笑说，在俄国读考茨基著作的人比在德国还多（附带说一说，在这个玩笑里含有比开这个玩笑的人所料到的更深刻得多的历史内容：俄国工人在1905年对世界最优秀的社会民主主义文献中的最优秀的著作表现了空前强烈的、前所未见的需求，他们得到的这些著作的译本和版本也远比其他各国多，这样就把一个比较先进的邻国的丰富经验加速地移植到我国无产阶级运动这块所谓新垦的土地上来了）。","language":"中文","translation":false},{"id":"state-7-18","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基在俄国特别出名，是因为他除了对马克思主义作了通俗的解释，还同机会主义者及其首领伯恩施坦进行了论战。但是有一个事实几乎是没有人知道的，而如果想要考察一下考茨基在1914—1915年危机最尖锐时期怎样堕落到最可耻地表现出张皇失措和替社会沙文主义辩护的地步，那又不能放过这个事实。这个事实就是：考茨基在起来反对法国最著名的机会主义代表（米勒兰和饶勒斯）和德国最著名的机会主义代表（伯恩施坦）之前，表现过很大的动摇。1901—1902年在斯图加特出版的、捍卫革命无产阶级观点的、马克思主义的《曙光》[37]，曾不得不同考茨基进行论战，把他在1900年巴黎国际社会党代表大会[38]上提出的决议叫作“橡皮性”决议，因为这个决议对机会主义者的态度是暧昧的，躲躲闪闪的，调和的。在德国的书刊中还刊载过一些考茨基的信件，这些信件也表明他在攻击伯恩施坦之前有过很大的动摇。","language":"中文","translation":false},{"id":"state-7-19","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"但是另一件事情的意义更重大得多，这就是：现在，当我们来研究考茨基最近背叛马克思主义的经过的时候，就从他同机会主义者的论战本身来看，从他提问题和解释问题的方法来看，我们也看到，他恰恰是在国家问题上一贯倾向于机会主义。","language":"中文","translation":false},{"id":"state-7-20","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"我们拿考茨基反对机会主义的第一部大作《伯恩施坦与社会民主党的纲领》来说。考茨基详细地驳斥了伯恩施坦。但是下面的情况值得注意。","language":"中文","translation":false},{"id":"state-7-21","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"伯恩施坦在他著的有赫罗斯特拉特名声的《社会主义的前提》一书中，指责马克思主义为“布朗基主义”（此后，俄国机会主义者和自由派资产者千百次地重复这种指责，用以攻击革命马克思主义的代表布尔什维克）。而且伯恩施坦还特别谈到马克思的《法兰西内战》，企图（我们已经看到，这是枉费心机）把马克思对公社的教训的观点同蒲鲁东的观点混为一谈。伯恩施坦特别注意马克思在《共产党宣言》的1872年序言中着重指出的结论，这个结论说：“工人阶级不能简单地掌握现成的国家机器，并运用它来达到自己的目的。”［注：见《马克思恩格斯全集》第18卷第105页。——编者注］","language":"中文","translation":false},{"id":"state-7-22","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"伯恩施坦非常“喜爱”这句名言，所以他在自己那本书里至少重复了三遍，并且把它完全歪曲成机会主义的见解。","language":"中文","translation":false},{"id":"state-7-23","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"我们已经看到，马克思是想说工人阶级应当打碎、摧毁、炸毁（Sprengung——炸毁，是恩格斯用的字眼）全部国家机器。但在伯恩施坦看来，似乎马克思说这句话是告诫工人阶级不要在夺取政权时采取过激的革命手段。","language":"中文","translation":false},{"id":"state-7-24","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"不能想象对马克思思想的歪曲还有比这更严重更不象样的了。","language":"中文","translation":false},{"id":"state-7-25","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"而考茨基在详尽驳斥伯恩施坦主义[39]的时候是怎样做的呢？","language":"中文","translation":false},{"id":"state-7-26","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"他不去分析机会主义在这一点上对马克思主义的彻头彻尾的歪曲。他引证了我们在前面引证过的恩格斯为马克思的《内战》所写的导言中的一段话，然后就说：根据马克思的意见，工人阶级不能简单地掌握现成的国家机器，但一般说来它是能够掌握这个机器的。仅此而已。至于伯恩施坦把同马克思的真正思想完全相反的东西硬加在马克思的身上，以及马克思从1852年起就提出无产阶级革命负有“打碎”国家机器的任务，考茨基却只字不提。","language":"中文","translation":false},{"id":"state-7-27","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"结果是：马克思主义同机会主义在无产阶级革命的任务问题上的最本质的差别被考茨基抹杀了！","language":"中文","translation":false},{"id":"state-7-28","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基在“反驳”伯恩施坦时写道：“关于无产阶级专政问题，我们可以十分放心地留待将来去解决。”（德文版第172页）","language":"中文","translation":false},{"id":"state-7-29","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":29,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这不是反驳伯恩施坦，同他进行论战，实际上是向他让步，是把阵地让给机会主义，因为机会主义者现在所需要的，恰恰是把关于无产阶级革命的任务的一切根本问题都“十分放心地留待将来去解决”。","language":"中文","translation":false},{"id":"state-7-30","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":30,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"马克思和恩格斯在1852年到1891年这40年当中，教导无产阶级应当打碎国家机器。而考茨基在1899年，当机会主义者在这一点上完全背叛马克思主义的时候，却用打碎国家机器的具体形式问题来偷换要不要打碎这个机器的问题，把我们无法预先知道具体形式这种“无可争辩的”（也是争不出结果的）庸俗道理当作护身符！！","language":"中文","translation":false},{"id":"state-7-31","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":31,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"在马克思和考茨基之间，在他们对无产阶级政党组织工人阶级进行革命准备这一任务所持的态度上，存在着一条不可逾越的鸿沟。","language":"中文","translation":false},{"id":"state-7-32","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":32,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"我们再拿考茨基后来一部更成熟的、在很大程度上也是为了驳斥机会主义的错误而写的著作来说。这就是他那本论“社会革命”的小册子。作者在这里把“无产阶级革命”和“无产阶级制度”的问题作为自己专门的研究课题。作者发表了许多极宝贵的见解，但是恰恰回避了国家问题。在这本小册子里，到处都在谈夺取国家政权，并且只限于此，也就是说，考茨基选择的说法是向机会主义者让步的，因为他认为不破坏国家机器也能夺得政权。恰巧马克思在1872年认为《共产党宣言》这个纲领中已经“过时的”东西，考茨基却在1902年把它恢复了。","language":"中文","translation":false},{"id":"state-7-33","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":33,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"在这本小册子里，专门有这样一节：“社会革命的形式与武器”。其中既讲到群众性的政治罢工，又讲到国内战争，又讲到“现代大国的强力工具即官僚和军队”，但是一个字也没有提到公社已经给了工人什么教训。可见，恩格斯告诫人们特别是告诫德国社会党人不要“盲目崇拜”国家，不是没有原因的。","language":"中文","translation":false},{"id":"state-7-34","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":34,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基把问题说成这样：胜利了的无产阶级“将实现民主纲领”。接着他叙述了纲领的各条。至于1871年在以无产阶级民主代替资产阶级民主的问题上所提出的一些新东西，他却一个字也没有提到。考茨基用下面这种听起来好象“冠冕堂皇”的陈词滥调来搪塞：","language":"中文","translation":false},{"id":"state-7-35","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":35,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"“不言而喻，在现行制度下我们是不能取得统治的。革命本身要求先要进行持久的和深入的斗争来改变我们目前的政治结构和社会结构。”","language":"中文","translation":false},{"id":"state-7-36","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":36,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"毫无疑义，这是“不言而喻”的，正如马吃燕麦和伏尔加河流入里海的真理一样。所可惜的是他通过“深入的”斗争这种空洞而浮夸的言词回避了革命无产阶级的迫切问题：无产阶级革命对国家、对民主的态度与以往非无产阶级革命不同的“深入的地方”究竟在哪里。","language":"中文","translation":false},{"id":"state-7-37","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":37,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基回避这个问题，实际上就是在这个最重要的问题上向机会主义让步，但他在口头上却气势汹汹地向它宣战，强调“革命这个思想”的意义（如果怕向工人宣传革命的具体教训，那么试问这种“思想”还有多大价值呢？），或者说“革命的理想主义高于一切”，或者宣称英国工人现在“几乎与小资产者不相上下”。","language":"中文","translation":false},{"id":"state-7-38","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":38,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基写道：“在社会主义社会里同时并存的可以有……各种形式上极不相同的企业：官僚的〈？？〉、工会的、合作社的、个人的”……“例如，有些企业非有官僚〈？？〉组织不可，铁路就是这样。在这里，民主组织可以采取这样的形式：工人选出代表来组成某种类似议会的东西，由这个议会制定工作条例并监督官僚机构的管理工作。有些企业可以交给工会管理，另外一些企业则可以按合作原则来组织。”（1903年日内瓦版俄译本第148页和第115页）","language":"中文","translation":false},{"id":"state-7-39","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":39,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这种论断是错误的，它比马克思和恩格斯在70年代用公社的教训作例子来说明的倒退了一步。","language":"中文","translation":false},{"id":"state-7-40","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":40,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"从必须有所谓“官僚”组织这一点看来，铁路同大机器工业的一切企业，同任何一个工厂、大商店和大型资本主义农业企业根本没有区别。在所有这些企业中，技术条件都绝对要求严格地遵守纪律，要求每个人十分准确地执行给他指定的那一份工作，不然就会有完全停产或损坏机器和产品的危险。在所有这些企业中，工人当然要“选出代表来组成某种类似议会的东西”。","language":"中文","translation":false},{"id":"state-7-41","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":41,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"但是关键就在于这个“某种类似议会的东西”不会是资产阶级议会机构式的议会。关键就在于，这个“某种类似议会的东西”不会仅仅“制定条例和监督官僚机构的管理工作”，象思想没有超出资产阶级议会制框子的考茨基所想象的那样。在社会主义社会里，由工人代表组成的“某种类似议会的东西”当然会“制定条例和监督”“机构的”“管理工作”，可是这个机构却不会是“官僚的”机构。工人在夺得政权之后，就会把旧的官僚机构打碎，把它彻底摧毁，彻底粉碎，而用仍然由这些工人和职员组成的新机构来代替它；为了防止这些人变成官僚，就会立即采取马克思和恩格斯详细分析过的措施：（1）不但选举产生，而且随时可以撤换；（2）薪金不得高于工人的工资；（3）立刻转到使所有的人都来执行监督和监察的职能，使所有的人暂时都变成“官僚”，因而使任何人都不能成为“官僚”。","language":"中文","translation":false},{"id":"state-7-42","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":42,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基完全没有弄清楚马克思的话：“公社不应当是议会式的，而应当是工作的机关，兼管行政和立法的机关。”［注：见《马克思恩格斯全集》第17卷第358页。——编者注］","language":"中文","translation":false},{"id":"state-7-43","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":43,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基完全不理解资产阶级议会制与无产阶级民主制度的区别，资产阶级议会制是把民主（不是人民享受的）同官僚制（反人民的）结合在一起，而无产阶级民主制度则立即采取措施来根除官僚制，它能够把这些措施实行到底，直到官僚制完全消灭，人民的民主完全实现。","language":"中文","translation":false},{"id":"state-7-44","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":44,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基在这里暴露出来的仍然是那个对国家的“盲目崇拜”，对官僚制的“迷信”。","language":"中文","translation":false},{"id":"state-7-45","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":45,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"现在来研究考茨基最后的也是最好的一部反对机会主义者的著作，即他的《取得政权的道路》的小册子（好象没有俄文版本，因为它是在1909年我们国内最反动的时期出版的[40]）。这本小册子是一个很大的进步，因为它不象1899年所写的反对伯恩施坦的小册子那样泛谈革命纲领，也不象1902年写的小册子《社会革命》那样不涉及社会革命到来的时间问题而泛谈社会革命的任务，它谈的是那些使我们不得不承认“革命纪元”已经到来的具体情况。","language":"中文","translation":false},{"id":"state-7-46","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":46,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"作者明确地指出了阶级矛盾一般都在尖锐化和帝国主义在这方面起着特别巨大的作用。在西欧“1789—1871年的革命时期”之后，东方从1905年起也开始了同样的时期。世界大战已经迫在眉睫。“无产阶级已经不能再说革命为时过早了。”“我们已经进入革命时期。”“革命纪元开始了。”","language":"中文","translation":false},{"id":"state-7-47","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":47,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这些话是说得非常清楚的。应当把考茨基的这本小册子当作一个尺度来衡量一下，看看德国社会民主党在帝国主义战争以前答应要做什么，在战争爆时它（包括考茨基本人）又堕落到多么卑鄙的地步。考茨基在这本小册子里写道：“目前的形势会引起这样一种危险：人们很容易把我们〈即德国社会民主党〉看得比实际上温和。”事实表明，德国社会民主党实际上比它表面看来要温和得多，要机会主义得多！","language":"中文","translation":false},{"id":"state-7-48","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":48,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"更值得注意的是，考茨基虽然如此明确地说革命纪元已经开始，但是就在他这本自称为专门分析“政治革命”问题的小册子里，却又完全回避了国家问题。","language":"中文","translation":false},{"id":"state-7-49","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":49,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"所有这些回避问题、保持缄默、躲躲闪闪的做法加在一起，就必然使他完全滚到机会主义那边去，这一点我们马上就要谈到。","language":"中文","translation":false},{"id":"state-7-50","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":50,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"德国社会民主党，以考茨基为代表，好象是在声明说：我仍然坚持革命观点（1899年）；我特别承认无产阶级的社会革命是不可避免的（1902年）；我承认革命的新纪元已经到来（1909年）；但是，一涉及无产阶级革命在对待国家方面的任务问题，我还是要从马克思在1852年所说的话向后倒退（1912年）。","language":"中文","translation":false},{"id":"state-7-51","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":51,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"在考茨基与潘涅库克的论战中，问题就是这样明摆着的。","language":"中文","translation":false},{"id":"state-7-52","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":52,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"3．考茨基与潘涅库克的论战","language":"中文","translation":false},{"id":"state-7-53","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":53,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"潘涅库克以“左翼激进”派的一个代表的资格出来反对考茨基，在这个派别内有罗莎·卢森堡、卡尔·拉狄克等人，这个派别坚持革命策略，一致确信考茨基已经转到“中派”立场而无原则地摇摆于马克思主义和机会主义之间。这个看法已经由战争充分证明是正确的，在战时，“中派”（有人称它为马克思主义的派别是错误的），即“考茨基派”，充分暴露了它的丑态。","language":"中文","translation":false},{"id":"state-7-54","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":54,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"潘涅库克在一篇谈到了国家问题的文章《群众行动与革命》（《新时代》第30年卷（1912）第2册）里，说考茨基的立场是“消极的激进主义”立场，是“毫无作为的等待论”。“考茨基不愿看到革命的过程。”（第616页）潘涅库克这样提出问题，就接触到了我们所关心的关于无产阶级革命在对待国家方面的任务问题。","language":"中文","translation":false},{"id":"state-7-55","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":55,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"他写道：“无产阶级的斗争不单纯是为了国家政权而反对资产阶级的斗争，而且是反对国家政权的斗争……无产阶级革命的内容，就是用无产阶级的强力工具去消灭和取消〈Auflösung——直译是解散〉国家的强力工具……只有当斗争的最后结果是国家组织的完全破坏时，斗争才告终止。多数人的组织的优越性的证明，就是它能消灭占统治地位的少数人的组织。”（第548页）","language":"中文","translation":false},{"id":"state-7-56","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":56,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"潘涅库克表达自己思想的时候在措词上有很大的缺点，但是意思还是清楚的，现在来看一看考茨基怎样反驳这种思想倒是很有意思的。","language":"中文","translation":false},{"id":"state-7-57","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":57,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基写道：“到现在为止，社会民主党人与无政府主义者之间的对立，就在于前者想夺取国家政权，后者却想破坏国家政权。潘涅库克则既想这样又想那样。”（第724页）","language":"中文","translation":false},{"id":"state-7-58","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":58,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"如果说潘涅库克的说法犯了不明确和不具体的毛病（他的文章中其他一些与本题无关的缺点，这里暂且不谈），那么考茨基倒恰恰是把潘涅库克指出的具有原则意义的实质抓住了，而就在这个根本的具有原则意义的问题上，他完全离开了马克思主义立场，完全转到机会主义那边去了。他对社会民主党人与无政府主义者的区别所作的说明是完全不对的，马克思主义完全被他歪曲和庸俗化了。","language":"中文","translation":false},{"id":"state-7-59","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":59,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"马克思主义者与无政府主义者之间的区别是在于：（1）马克思主义者的目的是完全消灭国家，但他们认为，只有在社会主义革命把阶级消灭之后，即导向国家消亡的社会主义建立起来之后，这个目的才能实现；无政府主义者则希望在一天之内完全消灭国家，他们不懂得实现这个消灭的条件。（2）马克思主义者认为无产阶级在夺得政权之后，必须彻底破坏旧的国家机器，用武装工人的组织组成的、公社那种类型的新的国家机器来代替它；无政府主义者主张破坏国家机器，但是，他们完全没有弄清楚无产阶级将用什么来代替它以及无产阶级将怎样利用革命政权；无政府主义者甚至否定革命无产阶级应利用国家政权，否定无产阶级的革命专政。（3）马克思主义者主张通过利用现代国家来使无产阶级进行革命的准备；无政府主义者则否定这一点。","language":"中文","translation":false},{"id":"state-7-60","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":60,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"在这场争论中，代表马克思主义的恰恰是潘涅库克而不是考茨基，因为正是马克思教导我们说，无产阶级不能简单地夺取国家政权，也就是说，不能只是把旧的国家机构转到新的人手中，而应当打碎、摧毁这个机构，用新的机构来代替它。","language":"中文","translation":false},{"id":"state-7-61","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":61,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基离开马克思主义而转到机会主义者那边去了，因为正是机会主义者所完全不能接受的破坏国家机器的思想在他那里完全不见了，而他把“夺取”解释成简单地获得多数，这也给机会主义者留下了后路。","language":"中文","translation":false},{"id":"state-7-62","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":62,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基为了掩饰自己对马克思主义的歪曲，就采用了书呆子的办法：“引证”马克思本人的话。马克思在1850年曾说必须“坚决使权力集中于国家政权掌握之下”[41]。考茨基就得意洋洋地问道：潘涅库克是不是想破坏“集中制”呢？","language":"中文","translation":false},{"id":"state-7-63","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":63,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这不过是一种把戏，正象伯恩施坦说马克思主义和蒲鲁东主义都主张用联邦制代替集中制一样。","language":"中文","translation":false},{"id":"state-7-64","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":64,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基的“引证”是牛头不对马嘴。集中制无论在旧的国家机器或新的国家机器的条件下，都是可能实现的。工人们自愿地把自己的武装力量统一起来，这就是集中制，但这要以“完全破坏”常备军、警察和官僚这种集中制的国家机构为基础。考茨基采取了十足的欺骗手段，回避了大家都知道的马克思和恩格斯关于公社的言论，却搬出一些文不对题的引证来。","language":"中文","translation":false},{"id":"state-7-65","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":65,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基继续写道：“……也许是潘涅库克想要取消官吏的国家职能吧？但是，我们无论在党组织或在工会组织内都非有官吏不可，更不必说在国家管理机关内了。我们的纲领不是要求取消国家官吏，而是要求由人民选举官吏……现在我们谈的并不是‘未来的国家’的管理机构将采取什么样的形式，而是在我们夺取国家政权以前〈黑体是考茨基用的〉我们的政治斗争要不要消灭〈auflöst——直译是解散〉国家政权。哪一个部和它的官吏可以取消呢？”他列举了教育部、司法部、财政部、陆军部。“不，现有各部中没有一个部是我们反政府的政治斗争要取消的……为了避免误会，我再说一遍：现在谈的不是获得胜利的社会民主党将赋予‘未来的国家’以什么样的形式，而是我们作为反对党应该怎样去改变现今的国家。”（第725页）","language":"中文","translation":false},{"id":"state-7-66","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":66,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这显然是故意歪曲。潘涅库克提出的正是革命问题。这无论在他那篇文章的标题上或在上面所引的那段话中都讲得很清楚。考茨基跳到“反对党”问题上去，正是以机会主义观点偷换革命观点。照他的意思：现在我们是反对党，到夺取政权以后我们再专门来谈。革命不见了！这正是机会主义者所需要的。","language":"中文","translation":false},{"id":"state-7-67","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":67,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这里所说的不是反对党，也不是一般的政治斗争，而正是革命。革命就是无产阶级破坏“管理机构”和整个国家机构，用武装工人组成的新机构来代替它。考茨基暴露了自己对“各部”的“盲目崇拜”，试问，为什么不可以由——譬如说——拥有全权的工兵代表苏维埃设立的各种专家委员会去代替“各部”呢？","language":"中文","translation":false},{"id":"state-7-68","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":68,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"问题的本质完全不在于将来是否保留“各部”，是否设立“各种专家委员会”或其他什么机构，这根本不重要。问题的本质在于：是保存旧的国家机器（它与资产阶级有千丝万缕的联系，并且浸透了因循守旧的恶习）呢，还是破坏它并用新的来代替它。革命不应当是新的阶级利用旧的国家机器来指挥、管理，而应当是新的阶级打碎这个机器，利用新的机器来指挥、管理，——这就是考茨基所抹杀或者完全不理解的马克思主义的基本思想。","language":"中文","translation":false},{"id":"state-7-69","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":69,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"他提出的官吏问题，清楚地表明他不理解公社的教训和马克思的学说。他说：“我们无论在党组织或在工会组织内都非有官吏不可……”","language":"中文","translation":false},{"id":"state-7-70","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":70,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"我们在资本主义下，在资产阶级统治下是非有官吏不可的。无产阶级受资本主义的压迫，劳动群众受资本主义的奴役。在资本主义下，由于雇佣奴隶制和群众贫困的整个环境，民主制度受到束缚、限制、阉割和弄得残缺不全。因为这个缘故，而且仅仅因为这个缘故，我们政治组织和工会组织内的公职人员是受到了资本主义环境的腐蚀（确切些说，有被腐蚀的趋势），是有变为官僚的趋势，也就是说，是有变为脱离群众、站在群众之上、享有特权的人物的趋势。","language":"中文","translation":false},{"id":"state-7-71","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":71,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这就是官僚制的实质，在资本家被剥夺以前，在资产阶级被推翻以前，甚至无产阶级的公职人员也免不了在一定程度上“官僚化”。","language":"中文","translation":false},{"id":"state-7-72","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":72,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"在考茨基看来，既然选举产生的公职人员还会存在，那也就是说，官吏在社会主义下也还会存在，官僚还会存在！这一点恰恰是不对的。马克思正是以公社为例指出，在社会主义下，公职人员将不再是“官僚”或“官吏”，其所以能如此，那是因为除了选举产生，还可以随时撤换，并且还把薪金减到工人平均工资的水平，并且还以“工作的即兼管行政和立法的”机构去代替议会式的机构。［注：见《马克思恩格斯全集》第17卷第358页。——编者注］","language":"中文","translation":false},{"id":"state-7-73","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":73,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"实质上，考茨基用来反驳潘涅库克的全部论据，特别是考茨基说我们无论在工会组织或在党组织内都非有官吏不可这个绝妙的理由，证明考茨基是在重复过去伯恩施坦用来反对马克思主义的那一套“理由”。伯恩施坦在他那本背叛变节的作品《社会主义的前提》中，激烈反对“原始”民主的思想，反对他所称为“学理主义的民主制度”的东西，即实行限权委托书制度，公职人员不领报酬，中央代表机关软弱无力等等。为了证明这种“原始”民主制度的不中用，伯恩施坦就援引了维伯夫妇所阐述的英国工联的经验。据说，工联根据自己70年来在“完全自由”（德文版第137页）的条件下发展的情形，确信原始的民主制度已不中用，因而用普通的民主制度，即与官僚制相结合的议会制代替了它。","language":"中文","translation":false},{"id":"state-7-74","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":74,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"其实，工联并不是在“完全自由”的条件下，而是在完全的资本主义奴役下发展的，在这种奴役下，对普遍存在的邪恶现象、暴虐、欺骗以及把穷人排斥在“最高”管理机关之外的现象，自然非作种种让步“不可”。在社会主义下，“原始”民主的许多东西都必然会复活起来，因为人民群众在文明社会史上破天荒第一次站起来了，不仅独立地参加投票和选举，而且独立地参加日常管理。在社会主义下，所有的人将轮流来管理，因此很快就会习惯于不要任何人来管理。","language":"中文","translation":false},{"id":"state-7-75","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":75,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"马克思以其天才的批判分析才能，从公社所采取的实际措施中看到了一个转变。机会主义者因为胆怯，因为不愿意与资产阶级断然决裂而害怕这个转变，不愿意承认这个转变；无政府主义者则由于急躁或由于根本不懂得大规模社会变动的条件而不愿意看到这个转变。“根本用不着考虑破坏旧的国家机器，我们没有各部和官吏可不行啊！”——机会主义者就是这样议论的，他们满身庸人气，实际上不但不相信革命和革命的创造力，而且还对革命害怕得要死（象我国孟什维克和社会革命党人害怕革命一样）。","language":"中文","translation":false},{"id":"state-7-76","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":76,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"“只需要考虑破坏旧的国家机器，用不着探究以往无产阶级革命的具体教训，用不着分析应当用什么来代替和怎样代替要破坏的东西。”——无政府主义者（当然是无政府主义者当中的优秀分子，而不是那些追随克鲁泡特金之流的先生去做资产阶级尾巴的无政府主义者）就是这样议论的；所以他们就采取拚命的策略，而不是为完成具体的任务以大无畏的精神同时考虑到群众运动的实际条件来进行革命的工作。","language":"中文","translation":false},{"id":"state-7-77","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":77,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"马克思教导我们要避免这两种错误，教导我们要以敢于舍身的勇气去破坏全部旧的国家机器，同时又教导我们要具体地提问题：看，公社就是通过实行上述种种措施来扩大民主制度和根绝官僚制，得以在数星期内开始建立新的无产阶级的国家机器。我们要学习公社战士的革命勇气，要把他们的实际措施看作是具有实际迫切意义并立即可行的那些措施的一个轮廓，如果沿着这样的道路前进，我们就一定能彻底破坏官僚制。","language":"中文","translation":false},{"id":"state-7-78","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":78,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"彻底破坏官僚制的可能性是有保证的，因为社会主义将缩短工作日，使群众能过新的生活，使大多数居民无一例外地人人都来执行“国家职能”，这也就会使任何国家完全消亡。","language":"中文","translation":false},{"id":"state-7-79","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":79,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基继续写道：“……群众罢工的任务在任何时候都不能是破坏国家政权，而只能是促使政府在某个问题上让步，或用一个同情无产阶级的政府去代替敌视无产阶级的政府……可是，在任何时候，在任何条件下，这〈即无产阶级对敌对政府的胜利〉都不能导致国家政权的破坏，而只能引起国家政权内部力量对比的某种变动……因此，我们政治斗争的目的，和从前一样，仍然是以取得议会多数的办法来夺取国家政权，并且使议会变成政府的主宰。”（第726、727、732页）","language":"中文","translation":false},{"id":"state-7-80","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":80,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这真是最纯粹最庸俗的机会主义，是口头上承认革命而实际上背弃革命。考茨基的思想仅限于要一个“同情无产阶级的政府”，这与1847年《共产党宣言》宣告“无产阶级组织成为统治阶级”［注：见《马克思恩格斯全集》第4卷第489页。——编者注］比较起来，是倒退到了庸人思想的地步。","language":"中文","translation":false},{"id":"state-7-81","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":81,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基只得去同谢德曼、普列汉诺夫和王德威尔得之流实行他所爱好的“统一”了，因为他们都赞成为争取一个“同情无产阶级的”政府而斗争。","language":"中文","translation":false},{"id":"state-7-82","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":82,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"我们却要同这些社会主义的叛徒决裂，要为破坏全部旧的国家机器而斗争，使武装的无产阶级自己成为政府。这二者有莫大的区别。","language":"中文","translation":false},{"id":"state-7-83","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":83,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"考茨基只得成为列金和大卫之流，普列汉诺夫、波特列索夫、策列铁里和切尔诺夫之流的亲密伙伴了，因为他们完全赞同为争取“国家政权内部力量对比的变动”而斗争，为“取得议会多数和争取一个主宰政府的全权议会”而斗争，——这是一个极为崇高的目的，在这个目的下，一切都可以为机会主义者接受，一切都没有超出资产阶级议会制共和国的框子。","language":"中文","translation":false},{"id":"state-7-84","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":84,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"我们却要同机会主义者决裂；整个觉悟的无产阶级将同我们一起进行斗争，不是去争取“力量对比的变动”，而是去推翻资产阶级，破坏资产阶级的议会制，建立公社类型的民主共和国或工兵代表苏维埃共和国，建立无产阶级的革命专政。","language":"中文","translation":false},{"id":"state-7-85","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":85,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"在国际社会主义运动中比考茨基更右的派别，在德国有《社会主义月刊》[42]派（列金、大卫、科尔布以及其他许多人，其中还包括斯堪的纳维亚人斯陶宁格和布兰亭），在法国和比利时有饶勒斯派[43]和王德威尔得，在意大利党[44]内有屠拉梯、特雷维斯以及其他右翼代表，在英国有费边派和“独立党人”（即“独立工党”[45]，实际上始终依附于自由派的党），如此等等。所有这些无论在议会工作中或在党的政论方面都起着很大作用而且往往是主要作用的先生，都公开否认无产阶级专政，实行露骨的机会主义。在这些先生看来，无产阶级“专政”是与民主“矛盾”的！！他们在实质上跟小资产阶级民主派并没有重大的区别。","language":"中文","translation":false},{"id":"state-7-86","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":86,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"鉴于这种情况，我们有理由得出结论：第二国际的绝大多数正式代表已经完全滚到机会主义那边去了。公社的经验不仅被忘记了，而且被歪曲了。他们不仅没有教导工人群众说，工人们应当起来的时候快到了，应当打碎旧的国家机器、代之以新的国家机器从而把自己的政治统治变为对社会进行社会主义改造的基础的时候快到了，——他们不仅没有这样做，反而教导工人群众相反的东西，而他们对“夺取政权”的理解，则给机会主义留下无数的后路。","language":"中文","translation":false},{"id":"state-7-87","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":87,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"当着国家，当着军事机构由于帝国主义竞赛而强化的国家已经变成军事怪物，为着解决究竟由英国还是德国、由这个金融资本还是那个金融资本来统治世界的争执而去屠杀千百万人的时候，在这样的时候歪曲和避而不谈无产阶级革命对国家的态度问题，就不能不产生极大的影响。","language":"中文","translation":false},{"id":"state-7-88","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":88,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"［注：手稿上还有下面这一段：","language":"中文","translation":false},{"id":"state-7-89","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":89,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"1905年和1917年俄国革命的经验","language":"中文","translation":false},{"id":"state-7-90","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":90,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"这一章的题目非常大，可以而且应当写几卷书来论述它。这本小册子自然就只能涉及与无产阶级在革命中在对待国家政权方面的任务直接有关的最主要的经验教训了。”（手稿到此中断。）——俄文版编者注］","language":"中文","translation":false},{"id":"state-7-91","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":91,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[35] 学理主义者指盲目地拘守某种学理，崇尚空谈，脱离实际的人，意思同“教条主义者”相近。——99。","language":"中文","translation":false},{"id":"state-7-92","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":92,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[36] 第一国际海牙代表大会（即国际工人协会第五次代表大会）于1872年9月2—7日举行。出席大会的有15个全国性组织的65名代表。马克思和恩格斯亲自参加了这次代表大会。这次代表大会是在马克思主义者同无政府主义者进行激烈斗争的形势下召开的。代表大会的主要议程是关于总委员会的权力和关于无产阶级的政治活动这两个问题。大会通过了关于扩大总委员会的权力、关于总委员会会址迁往纽约、关于巴枯宁派秘密组织社会主义民主同盟的活动等问题的决议。这些决议大部分是马克思和恩格斯起草的。代表大会就无产阶级的政治活动这个问题通过的决议指出，无产阶级的伟大任务就是夺取政权，无产阶级应当组织政党，以保证社会革命的胜利和达到消灭阶级的最终目的。大会从理论上、组织上揭露和清算了巴枯宁派反对无产阶级革命、破坏国际工人运动的种种活动，并把该派首领米·亚·巴枯宁和詹·吉约姆开除出国际。海牙代表大会的决议标志着马克思主义对无政府主义者的小资产阶级世界观的胜利，为后来建立各国工人阶级独立的政党奠定了基础。——99。","language":"中文","translation":false},{"id":"state-7-93","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":93,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[37] 《曙光》杂志（《Заря》）是俄国马克思主义的科学政治刊物，由《火星报》编辑部编辑，1901—1902年在斯图加特出版，共出了4期（第2、3期为合刊）。杂志宣传马克思主义，批判民粹主义和合法马克思主义、经济主义、伯恩施坦主义等机会主义错误思潮。杂志第1期曾刊登格·瓦·普列汉诺夫的《略论最近一次巴黎国际社会党代表大会》一文，批评了卡·考茨基在第二国际第五次代表大会上提出的决议案。——101。","language":"中文","translation":false},{"id":"state-7-94","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":94,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[38] 指第二国际第五次代表大会。","language":"中文","translation":false},{"id":"state-7-95","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":95,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"第二国际第五次代表大会于1900年9月23—27日在巴黎举行。出席大会的有参加第二国际的各国社会党的代表791名。俄国代表团由24名代表组成，在大会上分裂为以波·尼·克里切夫斯基为首的多数派和以格·瓦·普列汉诺夫为首的少数派。代表大会注意的中心问题，是与1899年法国社会党人亚·艾·米勒兰加入资产阶级的瓦尔德克-卢梭政府这一事件有关的“夺取公共权力和同资产阶级政党联盟”的问题。大会就这一问题通过了卡·考茨基提出的决议案，其中说：“个别社会党人参加资产阶级政府，不能认为是夺取政权的正常的开端，而只能认为是迫不得已采取的暂时性的特殊手段。”俄国代表团多数派投票赞成考茨基的这个含糊其词的“橡皮性”决议案，少数派支持茹·盖得提出的谴责米勒兰主义的决议案。代表大会还通过了建立由各国社会党代表组成的社会党国际局和在布鲁塞尔设立国际局书记处的决议。——101。","language":"中文","translation":false},{"id":"state-7-96","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":96,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[39] 伯恩施坦主义是德国社会民主党人爱·伯恩施坦的修正主义思想体系，产生于19世纪末20世纪初。伯恩施坦的《社会主义的前提和社会民主党的任务》（1899年）一书是伯恩施坦主义的全面阐述。伯恩施坦主义在哲学上否定辩证唯物主义和历史唯物主义，用庸俗进化论和诡辩论代替革命的辩证法；在政治经济学上修改马克思主义的剩余价值学说，竭力掩盖帝国主义的矛盾，否认资本主义制度的经济危机和政治危机；在政治上鼓吹阶级合作和资本主义和平长入社会主义，传播改良主义和机会主义思想，反对马克思主义的阶级斗争学说，特别是无产阶级革命和无产阶级专政的学说。伯恩施坦主义得到了德国社会民主党右翼和第二国际其他一些政党的支持。在俄国，追随伯恩施坦主义的有合法马克思主义者、经济派等。——102。","language":"中文","translation":false},{"id":"state-7-97","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":97,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[40] 卡·考茨基的小册子《取得政权的道路（关于长入革命的政论）》的俄译本是1918年出版的。——106。","language":"中文","translation":false},{"id":"state-7-98","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":98,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[41] 这句话出自《中央委员会告共产主义者同盟书》（见《马克思恩格斯全集》第7卷第297页）。《告同盟书》是马克思和恩格斯于1850年3月底写的，1885年恩格斯把它作为附录发表在马克思的《揭露科隆共产党人案件》一书中。——109。","language":"中文","translation":false},{"id":"state-7-99","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":99,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[42] 《社会主义月刊》派是围绕《社会主义月刊》杂志而形成的集团。","language":"中文","translation":false},{"id":"state-7-100","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":100,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"《社会主义月刊》（《Sozialistische Monatshefte》）是德国机会主义者的主要刊物，也是国际修正主义者的刊物之一，1897—1933年在柏林出版。编辑和出版者为右翼社会民主党人约·布洛赫。第一次世界大战期间持社会沙文主义立场。——114。","language":"中文","translation":false},{"id":"state-7-101","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":101,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[43] 饶勒斯派指19世纪末20世纪初法国社会主义运动中以让·饶勒斯为首的右翼改良派。饶勒斯派对马克思主义基本原理持修正态度，认为社会主义的胜利不会通过无产阶级同资产阶级的阶级斗争而取得，这一胜利将是民主主义思想繁荣的结果。他们还赞同蒲鲁东主义关于合作社的主张，认为在资本主义条件下合作社的发展有助于逐渐向社会主义过渡。在米勒兰事件上，饶勒斯派竭力为亚·艾·米勒兰参加资产阶级内阁的背叛行为辩护。1902年，饶勒斯派成立了改良主义的法国社会党。1905年该党和盖得派的法兰西社会党合并成统一的法国社会党（工人国际法国支部）。第一次世界大战期间，在法国社会党领导中占优势的饶勒斯派采取了社会沙文主义立场，公开支持帝国主义战争。——114。","language":"中文","translation":false},{"id":"state-7-102","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":102,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[44] 指意大利社会党。","language":"中文","translation":false},{"id":"state-7-103","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":103,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"意大利社会党于1892年8月在热那亚代表大会上成立，最初叫意大利劳动党，1893年改称意大利劳动社会党，1895年开始称意大利社会党。从该党成立起，党内的革命派就同机会主义派进行着尖锐的思想斗争。1912年在艾米利亚雷焦代表大会上，改良主义分子伊·博诺米、莱·比索拉蒂等被开除出党。从第一次世界大战爆发到1915年5月意大利参战，意大利社会党一直反对战争，提出了“反对战争，赞成中立！”的口号。1914年12月，拥护资产阶级帝国主义政策、主张战争的叛徒集团（贝·墨索里尼等）被开除出党。意大利社会党人曾于1914年同瑞士社会党人一起在卢加诺召开了联合代表会议，并积极参加了齐美尔瓦尔德（1915年）和昆塔尔（1916年）国际社会党代表会议。1916年底意大利社会党在党内改良派的影响下走上了社会和平主义的道路。俄国十月社会主义革命胜利后，意大利社会党积极支持保卫苏维埃俄国的运动，1919年宣布参加共产国际。1921年，革命的一翼退出该党，建立了意大利共产党。——114。","language":"中文","translation":false},{"id":"state-7-104","author":"列宁","title":"国家与革命","location":"第六章 马克思主义被机会主义者庸俗化","page":7,"paragraph":104,"url":"https://www.marxists.org/chinese/lenin/191708-09/07.htm","text":"[45] 独立工党是英国改良主义政党，1893年1月成立。领导人有凯·哈第、拉·麦克唐纳、菲·斯诺登等。党员主要是“新工联”和一些老工会的成员以及受费边派影响的知识分子和小资产阶级分子。独立工党从建党时起就采取资产阶级改良主义立场，把主要注意力放在议会斗争和同自由主义政党进行议会交易上。1900年，该党作为集体党员加入工党。在第一次世界大战期间，该党领袖采取资产阶级和平主义立场。——114。","language":"中文","translation":false},{"id":"state-8-1","author":"列宁","title":"国家与革命","location":"第一版跋","page":8,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/08.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-8-2","author":"列宁","title":"国家与革命","location":"第一版跋","page":8,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/08.htm","text":"这本小册子是在1917年8、9月间写成的。我当时已经拟定了下一章即第7章《1905年和1917年俄国革命的经验》的提纲。但这一章除了题目以外，我连一行字也没有来得及写，因为1917年十月革命前夜的政治危机“妨碍”了我。对于这种“妨碍”，只有高兴。但是本书第2册（《1905年和1917年俄国革命的经验》）看来只好长时间拖下去了；做出“革命的经验”是会比论述“革命的经验”更愉快、更有益的。","language":"中文","translation":false},{"id":"state-8-3","author":"列宁","title":"国家与革命","location":"第一版跋","page":8,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/08.htm","text":"1917年11月30日于彼得格勒","language":"中文","translation":false},{"id":"state-8-4","author":"列宁","title":"国家与革命","location":"第一版跋","page":8,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/08.htm","text":"1918年在彼得格勒印成单行本","language":"中文","translation":false},{"id":"state-8-5","author":"列宁","title":"国家与革命","location":"第一版跋","page":8,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/08.htm","text":"译自《列宁全集》俄文第5版第33卷第1—120页","language":"中文","translation":false},{"id":"state-9-1","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-9-2","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"《列宁全集》第三十一卷（第二版）","language":"中文","translation":false},{"id":"state-9-3","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"本卷刊载的是列宁在1917年8—9月间所写的系统阐述马克思主义国家学说的名著《国家与革命》，在《附录》中还收载了被称作“蓝皮笔记”的《马克思主义论国家》以及1916年夏至1917年9月的有关材料。","language":"中文","translation":false},{"id":"state-9-4","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"19世纪末20世纪初，资本主义在世界范围内进入了帝国主义阶段，资本主义所固有的各种矛盾进一步加深和激化，这些矛盾只有通过无产阶级革命才能得到根本解决；帝国主义时代迅速发展的社会生产力和高度集中的垄断经济形式，则为社会主义创造了物质前提。正如列宁所说，帝国主义已是无产阶级社会主义革命的前夜。1914年爆发的第一次世界大战造成了各国经济的严重破坏，给人民带来了深重的灾难。战时空前加重的压迫和剥削迫使无产阶级和劳动群众奋起斗争。欧洲许多国家在客观上出现了革命的形势，无产阶级革命的条件日趋成熟。","language":"中文","translation":false},{"id":"state-9-5","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"革命的根本问题是国家政权问题。在当时的形势下，无产阶级革命对国家的态度问题不仅在理论上而且在政治实践上都具有特别重大的意义。但是，国家问题恰恰是被资产阶级和小资产阶级思想家、形形色色的社会主义者和无政府主义者搅得最乱的问题。特别是第二国际的机会主义领袖伯恩施坦、考茨基等人严重地歪曲和篡改了马克思主义的国家学说，在社会主义运动中造成了恶劣的影响。为了捍卫和恢复马克思主义的国家学说，批判机会主义者和无政府主义者的歪曲，列宁从1916年秋天起就精心研究国家问题，阅读了马克思和恩格斯有关国家问题的大量文献，翻阅了考茨基、伯恩施坦等人的著作，在1917年1—2月间作了《马克思主义论国家》的笔记，准备写一篇关于马克思主义对国家态度问题的论文。","language":"中文","translation":false},{"id":"state-9-6","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"1917年3月，俄国无产阶级和劳动群众推翻了沙皇政府，建立了工人、士兵和农民代表苏维埃，国内形成了两个政权并存的局面。列宁领导的布尔什维克党提出“全部政权归苏维埃”的口号，积极争取群众，为和平地实现向社会主义革命的转变而斗争。但是，在当时的苏维埃中占统治地位的社会革命党和孟什维克却对资产阶级临时政府奉行妥协投降的政策，致使政权完全落入反革命资产阶级手中。七月事变标志着形势的急剧变化，两个政权并存的局面已告结束，反革命势力开始向以布尔什维克为代表的革命力量猖狂反扑，革命和平发展的可能性已不复存在，武装夺取政权的问题提上了日程。这时，革命对国家的态度问题不仅具有一般现实意义，而且具有了最迫切的意义。为了从思想上武装无产阶级和劳动群众，向他们说明在即将到来的革命中应当做些什么，列宁在拉兹里夫湖畔的草棚中开始撰写《国家与革命》这部光辉的著作。","language":"中文","translation":false},{"id":"state-9-7","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"本书分为六章，列宁原来打算写的第七章《1905年和1917年俄国革命的经验》只开了一个头，因忙于直接领导十月革命而没有写成。","language":"中文","translation":false},{"id":"state-9-8","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"在第一章中，列宁根据恩格斯的著作阐述了马克思主义关于国家问题的最基本的观点，说明了国家的起源和本质、国家的基本特征和职能、国家消亡与暴力革命的关系等问题。他指出：国家是阶级矛盾不可调和的产物，是一个阶级压迫另一个阶级的机关，是压迫阶级剥削被压迫阶级的工具；无产阶级国家代替资产阶级国家，非通过暴力革命不可，而无产阶级国家只能“自行消亡”。在阐述马克思主义国家观的同时，列宁批判了资产阶级和俄国小资产阶级民主派——社会革命党人和孟什维克把国家看作阶级调和机关，以为有了普选权，资产阶级国家就能体现大多数劳动者的意志等错误观点，着重揭露了考茨基“忽视或抹杀”暴力革命的行径。","language":"中文","translation":false},{"id":"state-9-9","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"在第二章至第四章中，列宁按照历史顺序叙述了1847年至1894年马克思和恩格斯的国家观点的发展。","language":"中文","translation":false},{"id":"state-9-10","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"列宁指出，马克思和恩格斯在欧洲1848年革命的前夜已经提出了无产阶级专政的思想。他们在《共产党宣言》中写道：无产阶级用暴力推翻资产阶级而建立自己的政治统治，利用这种政治统治剥夺资产阶级，把生产工具集中在国家手里，尽快增加生产力的总量，而国家就是“组织成为统治阶级的无产阶级”。列宁认为，这是马克思主义在国家问题上的一个最卓越最重要的思想。","language":"中文","translation":false},{"id":"state-9-11","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"列宁引用了马克思在《路易·波拿巴的雾月十八日》一书中总结1848—1851年革命的论述，认为马克思总结1848年革命经验得出的无产阶级革命必须打碎资产阶级国家机器的结论与《共产党宣言》相比，是向前迈进了一大步，认为这个结论是马克思主义国家学说中主要的基本的原理。但当时还没有提出应当怎样以无产阶级国家代替资产阶级国家的问题。","language":"中文","translation":false},{"id":"state-9-12","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"1871年巴黎公社为解决这个问题提供了实践经验。列宁摘录了马克思在《法兰西内战》一书中对巴黎公社经验的分析，着重阐释了马克思根据公社经验得出的而且在马克思恩格斯看来必须加进《共产党宣言》的一个基本教训，即“工人阶级不能简单地掌握现成的国家机器，并运用它来达到自己的目的”。接着，列宁详细论述并高度评价了马克思所总结的公社为代替被破坏的国家机器而采取的实际步骤、公社的国家制度和政治形式。列宁最后总结说：公社是无产阶级革命终于发现的、可以使劳动在经济上获得解放的形式，是可以而且应该用来代替已被打碎的国家机器的政治形式。","language":"中文","translation":false},{"id":"state-9-13","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"在叙述马克思主义国家学说的发展时，列宁反复强调马克思的严格的科学态度。他指出，马克思始终忠于自己的辩证唯物主义哲学，在每一历史阶段都不是根据逻辑的推论，而是根据事变的实际发展作出自己的结论，并且根据群众运动的经验重新审查自己的理论，修改过时的结论，提出新的论断。列宁也正是以这种马克思主义的态度、运用唯物辩证的方法研究世界形势的新发展，总结国际社会主义运动正反两方面的经验和俄国1905年、1917年两次革命的经验，对无产阶级专政的思想以及马克思主义国家学说的许多方面作了进一步的发挥和新的理论概括。","language":"中文","translation":false},{"id":"state-9-14","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"列宁揭示了一切资产阶级国家的阶级本质，指出资产阶级国家的政治形式虽然多种多样，但本质是一样的，都是资产阶级专政。列宁根据垄断资本主义时代资产阶级国家的主要统治工具——官吏和军队普遍得到加强的事实，进一步论证了打碎旧国家机器的必要性，认为这是一切真正的人民革命的先决条件。","language":"中文","translation":false},{"id":"state-9-15","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"无产阶级专政学说是马克思主义国家学说的核心。针对机会主义者的歪曲，列宁详尽地阐发了马克思和恩格斯关于无产阶级专政的思想。列宁指出：无产阶级专政是无产阶级在历史上的革命作用的最高表现；只有使无产阶级转化成统治阶级，使它能够镇压资产阶级必然要进行的拚死反抗，并组织一切被剥削劳动群众去建立新的经济制度，才能推翻资产阶级；无产阶级需要专政的国家，既是为了镇压剥削者的反抗，也是为了领导广大人民群众“调整”社会主义经济，以便最终消灭阶级，过渡到无阶级的社会。因此，“一个阶级的专政不仅对一般阶级社会是必要的，不仅对推翻了资产阶级的无产阶级是必要的，而且对介于资本主义和‘无阶级社会’即共产主义之间的整整一个历史时期都是必要的，——只有懂得这一点的人，才算掌握了马克思国家学说的实质”（见本卷第33页）。","language":"中文","translation":false},{"id":"state-9-16","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"列宁总结了俄国两次革命中群众创造的苏维埃的经验，认为苏维埃是继巴黎公社之后的又一种无产阶级专政的形式。他还科学地预言：“从资本主义向共产主义过渡，当然不能不产生非常丰富和多样的政治形式，但本质必然是一样的：都是无产阶级专政。”（见本卷第33页）我国出现的人民民主专政和其他社会主义国家的实践充分证实了列宁的这一预见。","language":"中文","translation":false},{"id":"state-9-17","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"另外，列宁还揭示了无产阶级民主和资产阶级民主的根本区别，阐明了民主与社会主义、作为上层建筑的民主与经济基础的辩证关系。他指出，资产阶级民主是只供少数富人享受的、残缺不全的民主，而无产阶级民主却是大多数人的民主，它能保证大多数人真正当家作主，参加国家的管理。列宁在引述了恩格斯总结的巴黎公社为防止国家和国家机关由社会公仆变为社会主人所采取的措施后指出，民主扩展到一定的界限，彻底的民主就变成社会主义，同时也要求实行社会主义。彻底发展民主，找出彻底发展的种种形式，用实践来检验这些形式，是对社会进行社会主义改造的基本任务之一。任何单独存在的民主制度都不会产生社会主义，但在实际生活中总是“共同存在”的民主制度，既受经济发展的影响，又会影响经济，推动经济的改造。","language":"中文","translation":false},{"id":"state-9-18","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"在探讨国家消亡的经济基础的第五章中，列宁阐明了专政和民主的关系、无产阶级国家的消亡和经济基础的关系。根据马克思在《哥达纲领批判》中的论述，列宁进一步发挥了关于共产主义社会两个阶段的学说。列宁指出了两个阶段的共同特征，又说明了两者之间的差别。在共产主义社会初级阶段即社会主义阶段，实现了生产资料的公有，从而消除了人剥削人的可能性，在这一点上和高级阶段有共同之处，但由于受社会经济文化发展水平和人们觉悟水平的限制，社会主义阶段实行的是按劳分配的原则。这就要求国家和社会对劳动量和消费量进行极严格的计算和监督。列宁认为，计算和监督“是把共产主义社会第一阶段‘调整好’，使它能正常地运转所必需的主要条件”（见本卷第97页），只有到了各方面完全成熟的共产主义高级阶段，才能实行“各尽所能，按需分配”的原则。","language":"中文","translation":false},{"id":"state-9-19","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"和马克思恩格斯一样，列宁是运用最彻底、最完整、最周密、内容最丰富的发展论，即运用唯物辩证法来考察社会主义和共产主义的发展的。他批驳了那种把社会主义看成“僵死的、凝固的、一成不变的”形而上学观念，他指出：“实际上，只是从社会主义实现时起，社会生活和个人生活的各个领域才会开始出现迅速的、真正的、确实是群众性的即有大多数居民参加然后有全体居民参加的前进运动。”（见本卷第95—96页）","language":"中文","translation":false},{"id":"state-9-20","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"列宁在阐述马克思主义国家学说的各章中对考茨基等机会主义者的歪曲作了有力的批判，最后又专辟一章（第六章）揭露机会主义者把马克思主义庸俗化的行径。在这一章中，列宁集中批判了考茨基“盲目崇拜”国家、“迷信”官僚制度、取消打碎旧国家机器的任务、把无产阶级政治斗争的目的局限于“取得议会多数”、“使议会变成政府的主宰”等错误观点。列宁指出，这是最纯粹最庸俗的机会主义，是从马克思主义倒退到了庸人思想的地步。此外，列宁还揭露了普列汉诺夫在1894年与无政府主义者论战时完全回避革命对国家的态度和整个国家问题的错误。","language":"中文","translation":false},{"id":"state-9-21","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"本卷《附录》收载了《马克思主义论国家》这一读书笔记，笔记中摘录了马克思和恩格斯关于国家问题的重要论述以及考茨基、伯恩施坦、潘涅库克的著作。列宁读书时所作的大量批注包含着许多深刻的思想，其中大部分在《国家与革命》中得到了进一步发挥，但是还有一部分材料以及列宁在批语中所阐述的思想并没有反映在他的著作中，因此笔记具有独立的科学价值。列宁本人曾十分关切这本笔记的出版。","language":"中文","translation":false},{"id":"state-9-22","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"《附录》所载的《未写成的〈关于国家的作用问题〉一文的材料》是在1916年夏天至冬天形成的。从这组材料中可以看出，当时针对布哈林在《关于帝国主义国家理论》和《帝国主义强盗国家》这两篇文章中的某些错误观点，列宁准备写文章阐述国家的作用问题。在广泛收集材料、深入研究马克思主义对国家的态度问题之后，列宁的想法有改变。他在1917年2月给柯伦泰和印涅萨·阿尔曼德的信中说，他得出的结论与其说和布哈林的见解不同，不如说和考茨基的见解针锋相对。后来写成的《国家与革命》一书反映了列宁的这一想法。","language":"中文","translation":false},{"id":"state-9-23","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"本卷《附录》中的文献未收入《列宁全集》第1版。","language":"中文","translation":false},{"id":"state-9-24","author":"列宁","title":"国家与革命","location":"前言","page":9,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/09.htm","text":"《国家与革命》是列宁对马克思主义国家学说的发展作出的重大贡献。列宁在书中阐述的关于无产阶级革命和无产阶级专政的基本原理，不仅教育了俄国布尔什维克党和广大劳动群众，为他们创建第一个社会主义国家提供了强大的思想武器，而且也对各国无产阶级政党结合本国具体实际解决本国的革命问题具有指导意义。十月革命后，列宁总结俄国无产阶级专政和社会主义建设的实践经验，作出新的理论概括，进一步发展了《国家与革命》一书中的思想。列宁始终坚持马克思主义，同来自各方面的歪曲作不调和的斗争，同时又总结群众革命实践的经验，不断地丰富和发展马克思主义理论，为我们树立了光辉的榜样。","language":"中文","translation":false},{"id":"state-10-1","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"中文马克思主义文库 -> 列宁 -> 国家与革命——马克思主义关于国家的学说与无产阶级在革命中的任务（1917年8—9月）","language":"中文","translation":false},{"id":"state-10-2","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"[意大利]科莱蒂Lucio Colletti","language":"中文","translation":false},{"id":"state-10-3","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"《国家与革命》的基本主题就是破坏性的暴力行动的革命的主题，它牢牢地铭刻于人们的记忆之中，人们只要一想到这部著作，这个主题立刻就会在心灵中呈现出来。革命不能只限于夺取政权，还必须破坏旧的国家。列宁说：“问题的本质在于：是保存旧的国家机器……呢，还是把它破坏”。（《国家与革命》中文版单行本第103页）炸毁、打碎、破坏、粉碎：这些词汇是该文的基本语调。列宁并不是在驳斥那些不希望夺取政权的人。他攻击的对象不是改良主义。恰恰相反，列宁驳斥的是那些要求夺取政权、但又不希望破坏旧的国家的人。他所针对的作者是考茨基。但要说明的是，列宁所针对的考茨基并不是1917年后出场的考茨基（例如，以《恐怖政治和共产主义》一书出场的考茨基），而是致力于对机会主义进行笔伐的考茨基。当时的考茨基要求革命，但并不希望破坏旧的国家机器。","language":"中文","translation":false},{"id":"state-10-4","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"《国家与革命》给人的最初印象似乎是一种不可调和的但思想偏狭的评论，主要沉湎于“亚洲人的愤怒”之中——一首“为了暴力而暴力”的赞美歌。看上去它所表现出的是将革命简化为它的最基本的和外部的特征：占领冬宫、焚烧内务部、逮捕和处决旧政府的政治官员。正是由于对《国家与革命》的这种理解，才保证了它在从1928年到1953年四分之一世纪强的整个斯大林时代的成功，不仅在苏联是这样，而且在世界各国共产党都是这样。革命就是暴力。考茨基不希望暴力，因而是一个社会民主党人。一个人的目的如果不是暴力夺取政权，他就不可能是一个共产主义者。直到1953年，在一个共产党中（包括意大利共产党），任何胆敢怀疑暴力的必要性的战士都会发现自己处于如同今天那些表示怀疑“和平、议会道路”的人一样的窘境。","language":"中文","translation":false},{"id":"state-10-5","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"我并不那么愚蠢，以致会提出列宁是反对暴力的。正如在1917年6月列宁支持革命的和平发展一样，他也支持武装起义。根据情况，列宁或者支持这一面，或者支持另一面。但在一点上他的思想是不变的：即在每一种或所有情况下，都必须破坏国家机器。","language":"中文","translation":false},{"id":"state-10-6","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"进行革命的方法在某种程度上是偶然的：这些方法以一些事先无法讨论的事件为依据。而且流血的数量本身也并不说明革命过程的彻底性。革命的关键是破坏，这是不容放弃的（而且对于破坏来说暴力本身并不是一种充分保证），而破坏只是破坏脱离和反对人民群众的资产阶级国家这样一种政权，并以新型的政权取而代之。这是革命的关键。","language":"中文","translation":false},{"id":"state-10-7","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"按照列宁的观点，由于资产阶级国家依赖着人民群众相脱离和异化的权力，因而必须破坏旧的国家机器。在资本主义社会，民主充其量也要“始终受到资本主义剥削制度狭窄框子的限制”。“大多数居民在通常的和平局面下被排斥在社会政治生活之外。”（同上书第77页）所有资产阶级的国家机构都是“把穷人排斥和推出政治生活之外，使他们不能积极参加民主生活”的机构。（同上书，第78页）一种社会主义革命如果保留资产阶级国家，就会仍然使人民群众和权力相脱离，使人民群众依赖和隶属于政治权力。","language":"中文","translation":false},{"id":"state-10-8","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"如果生产资料的社会化指的是，生产资料从资本的统治下解放出来，社会成为自己的主人，使生产力受社会自觉的、有计划的控制，那么，达到这种经济解放的政治形式只能是一种以生产者的主动性和自我管理为基础的政治形式。","language":"中文","translation":false},{"id":"state-10-9","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"这样我们就掌握了《国家与革命》的真正的基本主题。破坏资产阶级国家机器不是焚烧内务部，内务部并不是障碍。这类事情是可能发生的，但不是革命的关键。革命的关键是消除使工人阶级与政权相分离的隔膜，工人阶级获得解放，自己决定自己，政权直接转到人民手中。马克思说：公社证明“工人阶级不能简单地掌握现成的国家机器，并运用它来达到自己的目的”。（同上书第33页）之所以是这样，是因为社会主义革命的目的不是“把官僚军事机器从一些人的手里转到另一些人的手里，”（同上书第34页）而只能是直接转到人民的手里——如果不首先打碎资产阶级的国家机器，这是不可能的。","language":"中文","translation":false},{"id":"state-10-10","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"这几条路线需要进行最严肃的思索：社会主义革命并不在于把官僚军事机器“从一些人手里转到另一些人手里”；破坏官僚军事国家机器在马克思看来是“任何一次真正的人民革命的先决条件”（同上书第34页）。列宁解释说，人民革命是一种这样的革命，在革命中，“人民群众，大多数人民，遭受压迫和剥削的社会最‘底层’，都自己站起来了，给整个革命的进程打上了自己的烙印，提出了自己的要求，自己尝试着按照自己的方式建设新社会来代替正在破坏的旧社会。”（同上书第36页）","language":"中文","translation":false},{"id":"state-10-11","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"这一段的意思是清楚的，破坏旧的国家机器是消除资产阶级国家对民主的限制。这是由一种“狭窄的、被限制的”民主走向完全民主的道路。列宁又说，“完全民主与不完全民主在性质上是不同的”。在那种看起来是形式上的量的差别背后，实际上至关紧要的是“一次大更替，即用一些根本不同的机构来代替另一些机构。”（同上书第38页）","language":"中文","translation":false},{"id":"state-10-12","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"在这里同考茨基辩论的意义也表现出来了。列宁同考茨基的辩论是重要的，因为这一辩论暴露了一个难题，它在列宁以后成为整个工人运动经验的难题。考茨基希望夺取政权，但不希望破坏国家。他说，本质的东西在于完全地占有现成的国家机器，并运用它来实现自己的目的。任何人只要思考这两种说法的差异就会发现，在单纯的词句不同的背后包含的是更本质的，更深刻的分歧。在列宁看来，革命不仅仅是把政权从一个阶级转到另一个阶级，而且是从一种类型的政权走向另一种类型的政权的道路。列宁认为，这两种事情是结合在一起的，因而夺取政权的工人阶级就是管理自己的工人阶级。然而，在考茨基看来，夺取政权并不意味着建立新型的政权，而只是促使运用那些本身不是工人阶级而又代表工人阶级的政治人员组成的旧政权。对于前者，社会主义是人民群众的自我管理。列宁说，在社会主义社会，“人民群众……站起来了，不仅自己来参加投票和选举，而且自己来参加日常管理。在社会主义下，所有的人将轮流来管理。因此很快就会习惯于不要任何人来管理。”（同上书第104—105页）","language":"中文","translation":false},{"id":"state-10-13","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"对于后者，社会主义是以群众的名义管理政权。列宁认为，社会主义革命必须破坏旧的国家，这是因为社会主义必须清除统治者和被统治者之间的差别。考茨基认为，不应该破坏国家以及国家的官僚政治设施，这是因为官僚政治，即统治者和被统治者之间的差别不能消除，将始终存在。列宁认为，革命是所有统治者的末日，考茨基认为，革命只是新统治者的来临。","language":"中文","translation":false},{"id":"state-10-14","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"我再说一遍，列宁的辩论所针对的考茨基仍然是一个马克思主义者，因为他坚定地坚持国家的阶级观念。确实，考茨基的政治见解具有一种难以改变的工运中心主义的倾向。正如所有第二国际的马克思主义者一样，事实上，考茨基的阶级观是那样地严肃，以至于经常变成一种狭窄的工团主义。为了反对普列汉诺夫等人，列宁所写的论马克思的人民革命概念的话也能很容易地扩大到考茨基身上。","language":"中文","translation":false},{"id":"state-10-15","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"然而，尽管考茨基有这种严格的阶级观，但他的政治观已经包含了所有后来他的思想发展的胚胎。那种没有必要破坏，只能接收并使之转向自己的目的的国家，那种不应该拆除，而只应该“从一些人手里转到另一些人手里”的官僚军事机器，已经是一种萌芽状态的具有阶级中立性质的国家：是一种技术的或“中性的”工具。一种仅仅是根据掌握和运用它的人的需要而行善或作恶的手段。","language":"中文","translation":false},{"id":"state-10-16","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"因此，仅仅夺取政权，而不同时破坏改造政权的理论，包含了一种关于国家介于阶级之间的理论的胚胎。或者说它是一种两极间的永久摇摆：一种把革命和社会主义的本质看成是促成那些特殊的政治人员组成政权的轻率的主观主义——正如我们知道的，这些政治人员是党的官僚——一种关于国家介于阶级之间的看法。一极产生所谓拉科西型政体：法定的“无产阶级专政”，而后在适当的时候可以发展为“全民国家”的概念。另一极产生社会民主官僚政治的官吏：谢德曼、莱昂·布兰姆、莫里特、威尔逊，当他们在为资产阶级国家服务时，并且正是由于他们在为资产阶级国家服务，他们因此认为他们正在为整个社会的利益服务，正在为“普遍的”和“共同的”利益服务。","language":"中文","translation":false},{"id":"state-10-17","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"考茨基写道，我们政治斗争的目的，是“以取得议会中多数的办法来夺取国家政权，并且使议会成为驾于政府之上的主宰”。（同上书第106页）显然，至今存在的议会，在以后将继续存在，的确必须永远存在。议会不仅独立于各阶级，而且独立于各历史时代。这是阶级合作主义（inter-classism）的极点。考茨基的理论（以及考茨基的现代摹仿者的理论）甚至没有提出这样的假设，即议会政体可能以某种方式同资产阶级的社会结构相联系。这个理论使得整个马克思对于现代代议制国家的批判荡然无存。而且就它准备承认议会政体具有任何阶级的所有特性而言，它看到了这一点，并不在议会政体本身中，而是从议会政体的滥用中，选举的舞弊、trasformismo,（是使对抗力量以及他们领袖都为占统治地位的杰出人物所吸引的过程。）“政治分肥”。sotto-governo（是流行于意大利的作法。按照这种作法，执政党通过建立直接依赖自身的同样的官僚政治机构而对国家行政部门置之不理）等等。这个理论之所以更愿意强调这些弊端，是由于这些“异常”现象使得它求助于所谓“真正的议会”、“国家的真正的镜子”这种陶里亚蒂也预言过的乌托邦主义：只有“老狐狸”才想象的乌托邦主义。","language":"中文","translation":false},{"id":"state-10-18","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"要获得议会的多数，变议会为政府的主宰，在考茨基看来实质的问题是谁控制议会。这种变化即使是一个根本的变化，也仅仅是政府政治成员的变更。再进一步是可能的，也是必然的，即关键确实在于消除统治者和被统治者之间的差别——考茨基甚至不能设想这样的事情。考茨基的公式是议会是“政府的主宰”，列宁的公式是人民是“议会的主宰”——即对议会本身的控制。","language":"中文","translation":false},{"id":"state-10-19","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"我们确信我们正确地理解了这一列宁主义对于议会制的批判。它并不是幼稚的和思想偏狭的批判，不是波尔迪加式的苍白无力的批判，斥责议会是“舞弊”，痛骂政治民主是“欺骗”，如此等等。后者曾是共产主义传统中历史地流行的批判。这只是一种初步的批判，既不能对自由民主予以阶级分析，也不能抓住同资本主义社会经济发展过程相联系的自由民主发展的有机的道路，而是根据主观主义把议会和代议制国家指责为好象是统治阶级为了愚弄人民而故意地“发明的”一种制度（更象伏尔泰所说的宗教是教父的发明）。只要我们不忘记由这种批判流传下来的对一个社会主义的民主和政权结构问题的虚无主义的轻蔑态度弥漫到今天的整个斯大林主义和后斯大林主义政治界的全部经历，那么我们就会清楚地看出这种批判的肤浅和无力。相反，在《国家与革命》中，列宁对议会的批判第一次成功地恢复了马克思对现代代议制国家批判的一些基本线索——要记住，在列宁自己的思想中这是第一次（因此这部著作具有决定意义的重要性，无疑地是列宁政治理论的最大的贡献）。结果是，正象在政治实践上《国家与革命》同列宁首次真正领悟和发现苏维埃的意义相一致（苏维埃很早就出现了，是在1905年革命期间，但列宁在很长时间里未能理解它），在政治理论上《国家与革命》同列宁发现“无产阶级专政”不是党的专政，而是巴黎公社式的专政相一致，甚至到1917年初，列宁还仍然认为巴黎公社虽然是“资产阶级民主主义”的一种极端形式，但也只是一种形式。","language":"中文","translation":false},{"id":"state-10-20","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"两种观点之间的差别是如此地带有根本性质以致于：在前者对于议会的批判成了对于民主的批判，相反，在列宁那里，对议会的批判，即对自由的和资产阶级民主的批判，就是对议会的反民主本性的批判——一种为了无限地更“完全”的民主（因而质上是不同的）为了苏维埃的民主而进行的批判，只有苏维埃的民主才应享有社会主义的名称。","language":"中文","translation":false},{"id":"state-10-21","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"从马克思以来的马克思主义的文献中，甚至没有什么东西可以和《国家与革命》中所包含的对议会批判的严肃认真相比拟；同时，也没有任何东西象列宁的这部著作一样充满着一种深远的民主精神，从始至终生气勃勃。“强制的命令”，议员可被他们所代表的人经常地不断地撤换；需要一种这样的立法权，这种立法权将不是议会式的机构。“而应当是同时兼管立法和行政的工作机构”；（同上书第42页）因此，在这种机构中，议员“必须亲自工作，亲自执行自己通过的法律，亲自检查在实际生活中执行的结果，亲自对选民负责”。（同上书第43页）所有这些都不是对“议会”的改造（象一些小宗派的过激分子的传言所想象的一样，这些小宗派是政党官僚政治的牺牲品，然而他们对列宁所设想的议会制度的斥责是“毫不留情的”！）；而是对议会的压制，是由一种“委员会”或者“苏维埃”式的代议机构代替议会：照列宁自己的话说，是“一次大更替，即用一些根本不同的机构来代替另一些机构”。（同上书第38页）","language":"中文","translation":false},{"id":"state-10-22","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"因此，破坏旧的国家，用“无产阶级民主”机构来代替，即用劳动群众的自我管理来代替。列宁的思路是如此地严密，以致他毫不犹豫地由此得出了最极端的结论：就社会主义（即共产主义社会的第一阶段）仍然需要国家而言，社会主义国家本身是资产阶级国家的残余。","language":"中文","translation":false},{"id":"state-10-23","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"国家正在消亡，因为资本家已经没有了，阶级已经没有了，因而也没有什么阶级可以镇压了。但是，国家还没有完全消亡，因为还要保卫容许在事实上存在不平等的资产阶级权利。（即“按劳分配”的原则而不是“按需分配”的原则）（同上书第84页）","language":"中文","translation":false},{"id":"state-10-24","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"因此，“在第一阶段，共产主义在经济上还不可能是完全成熟的，还不可能完全摆脱资本主义的传统和痕迹。由此就产生一个有趣的现象，这就是共产主义第一阶段还保留着‘资产阶级权利的狭隘眼界’。”既然“在消费品的分配方面存在着资产阶级的权利，那当然一定要有资产阶级的国家，因为如果没有一个能够迫使人们遵守权利规范的机构，权利也就等于零。”列宁总结说：“可见，在共产主义下，在一定的时期内，不仅会保留资产阶级权利，甚至还会保留没有资产阶级的资产阶级国家！”（同上书第38页）","language":"中文","translation":false},{"id":"state-10-25","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"正如我们所知，在这里社会主义的发展水平是由民主的发展水平来衡量的。国家消亡的进程越快，人民群众自我管理的范围越大，从社会主义向共产主义转化发展也就越快。共产主义不是伏尔加—顿河运河加国家。不是“防风林带”加警察、集中营和官僚的无限权力。列宁具有一个与此不同的观念。然而，正因为这种观念直到今天也仍然仅仅是一种观念，我们应该抛弃所有的禁忌，坦白地陈述自己的观点。","language":"中文","translation":false},{"id":"state-10-26","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"《国家与革命》写于1917年8月至9月革命高潮时期。列宁的任何著作都没有“沉思”的特征。《国家与革命》的情形更是如此。为了决定在那行将到来的革命中做些什么，列宁写作了这部著作。他是一个现实主义者，他不相信“灵感”，不相信政治的逢场作戏，而是热望着以对他所从事的事业的充分认识来行动。这就是《国家与革命》产生的时刻和背景。然而，我们今天只有观察一番，才能认识到这种社会主义的观念和社会主义现实之间的关系同摩西在山上的说教与梵蒂冈之间的关系并没多大差别。","language":"中文","translation":false},{"id":"state-10-27","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"我们必须承认的答案是大家都知道的答案，我们应该深思熟虑地、冷静地、不带戏剧色彩地得出这个答案：我们所称之为社会主义的国家都只是在隐喻上是社会主义的。它们是那些不再是资本主义的国家，它们是将所有的基本的生产资料国有化和为国家所有的国家，但不是生产资料社会化的国家，国有化和社会化是非常不同的。它们是世界资本主义链条的断裂的“环节”（到目前为止，这个链条断裂的只是它的最薄弱的环节），中国就是这样，“人民民主”就是这样，更不用说苏联了。这些国家都不是，也不可能是真正的社会主义。社会主义不是一个民族的过程，而是整个世界的过程。这个巨大的过程——在今天首先是资本主义体系的解体——是我们正在生活于其中的确实的过程，仅仅就它的史无前例的规模而言，显然不可能在一天里达到目的地。每个人都可以看到这个过程。社会民主党认为这个过程在任何时候都可以实现，只有社会民主党的这种半盲目的“具体性”才会给自己找大量的口实来无视这个过程。这一社会民主党的幻想就是所有认为《国家与革命》过了时的人的命运。几乎没有什么著作比这部著作更及时和更中肯了。列宁没有过时的。国家社会主义、“在一国建成社会主义”这些是过时的。马克思说，共产主义不能作为一种“地域性的事件”而存在，“无产阶级只有在世界历史意义上才能存在，就象它的事业——共产主义一般只有作为‘世界历史性的’存在才有可能实现一样。”（马克思、恩格斯：《德意志意识形态》，见《马克思恩格斯全集》中文版第3卷第40页）","language":"中文","translation":false},{"id":"state-10-28","author":"列宁","title":"国家与革命","location":"列宁的《国家与革命》（作者：[意大利] 科莱蒂 Lucio Colletti）","page":10,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/191708-09/10.htm","text":"译自科莱蒂《从卢梭到列宁》（From Rousseau to Lenin）纽约、伦敦每月评论出版社1972年版，第219—227页","language":"中文","translation":false},{"id":"imperialism-1-1","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"中文马克思主义文库 -> 列宁","language":"中文","translation":false},{"id":"imperialism-1-2","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"帝国主义是资本主义的最高阶段","language":"中文","translation":false},{"id":"imperialism-1-3","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"· 二 银行和银行的新作用","language":"中文","translation":false},{"id":"imperialism-1-4","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"· 三 金融资本和金融寡头","language":"中文","translation":false},{"id":"imperialism-1-5","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"· 七 帝国主义是资本主义的特殊阶段","language":"中文","translation":false},{"id":"imperialism-1-6","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"· 八 资本主义的寄生性和腐朽性","language":"中文","translation":false},{"id":"imperialism-1-7","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"· 九 对帝国主义的批评","language":"中文","translation":false},{"id":"imperialism-1-8","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"· 十 帝国主义的历史地位","language":"中文","translation":false},{"id":"imperialism-1-9","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在献给读者的这本小册子，是1916年春天我在苏黎世写成的。在那里的工作条件，我自然感到法文和英文的参考书有些不足，俄文参考书尤其缺乏。但是，论述帝国主义的一本主要英文著作，即约·阿·霍布森的书，我还是利用了的，而且我认为是给了它应得的重视。我写这本小册子的时候，是考虑到沙皇政府的书报检查的。因此，我不但要极严格地限制自己只作理论上的、特别是经济上的分析，而且在表述关于政治方面的几点必要的意见时，不得不极其谨慎，不得不用暗示的方法，用沙皇政府迫使一切革命者提笔写作“合法”著作时不得不采用的那种伊索式的——可恶的伊索式的——语言。","language":"中文","translation":false},{"id":"imperialism-1-10","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在目前这种自由的日子里，重读小册子里这些因顾虑沙皇政府的书报检查而说得走了样的、吞吞吐吐的、好象被铁钳子钳住了似的地方，真是感到十分难受。在谈到帝国主义是社会主义革命的前夜，谈到社会沙文主义（口头上的社会主义，实际上的沙文主义）完全背叛了社会主义、完全转到资产阶级方面，谈到工人运动的这种分裂是同帝国主义的客观条件相联系的等等问题时，我不得不用一种“奴隶的”语言，现在，只好请关心这类问题的读者去看我那些即将重新刊印的1914-1917年间在国外写的论文。这里要特别指出的是第119-120页上的一段文字。当时为了用书报检查通得过的形式向读者说明，资本家以及转到资本家方面的社会沙文主义者（考茨基同他们进行的斗争是很不彻底的）怎样无耻地在兼并问题上撒谎，怎样无耻地掩饰自己的资本家的兼并政策，我不得不拿……日本做例子！细心的读者不难把日本换成俄国，把朝鲜换成芬兰、波兰、库尔兰、乌克兰、希瓦、布哈拉、爱斯兰和其它非大俄罗斯人居住的地区。","language":"中文","translation":false},{"id":"imperialism-1-11","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我希望我这本小册子能有助于理解帝国主义的经济实质这个基本经济问题，不研究这个问题，就根本不会懂得如何去认识现在的战争和现在的政治。","language":"中文","translation":false},{"id":"imperialism-1-12","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1917年4月26日于彼得格勒","language":"中文","translation":false},{"id":"imperialism-1-13","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我在俄文版序言里说过，1916年写这本小册子的时候，是考虑到沙皇政府的书报检查的。现在我不可能把全文改写一遍，而且改写也未必适当，因为本书的主要任务，无论过去或现在，都是根据无可争辩的资产阶级统治的综合材料和各国资产阶级学者的自白，来说明20世纪初期，即第一次世界帝国主义大战前夜，全世界资本主义经济在其国际相互关系上的总的情况。","language":"中文","translation":false},{"id":"imperialism-1-14","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"不改写对于先进资本主义国家的许多共产党人来说，在某种程度上甚至不无益处，因为他们根据这本被沙皇书报检查机关认为合法的书的例子可以看到，甚至象在目前的美国或在法国，在不久以前几乎所有的共产党人都被逮捕之后，还是有可能和有必要利用共产党人还保有的一点点合法机会，来揭露社会和平主义观点和“世界民主”幻想的极端虚伪性。而在这篇序言中，我只想对这本经过检查的书作一些最必要的补充。","language":"中文","translation":false},{"id":"imperialism-1-15","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"本书证明，1914-1918年的战争，从双方来说，都是帝国主义的（即侵略的、掠夺的、强盗的）战争，都是为了瓜分世界，为了瓜分和重新瓜分殖民地、金融资本的“势力范围”等等而进行的战争。","language":"中文","translation":false},{"id":"imperialism-1-16","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"要知道，能够证明战争的真实社会性质，确切些说，证明战争的真实阶级性质的，自然不是战争的外交史，而是对所有交战大国统治阶级的客观情况的分析。为了说明这种客观情况，应当利用的，不是一些例子和个别的材料（社会生活现象极其复杂，随时都可以找到任何数量的例子或个别的材料来证实任何一个论点），而必须是关于所有交战大国和全世界的经济生活基础的材料的总和。","language":"中文","translation":false},{"id":"imperialism-1-17","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我在说明1876年和1914年瓜分世界的情况（第6章）以及说明1890年和1913年瓜分世界铁路的情况（第7章）时所引用的，正是这样一些驳不倒的综合材料。铁路是资本主义工业最主要的部门即煤炭工业和钢铁工业的结果，是世界贸易和资产阶级民主文明发展的结果和最显着的标志。本书前几章说明了铁路是怎样同大生产，同垄断组织，同辛迪加、卡特尔、托拉斯、银行，同金融寡头联系在一起的。铁路网的分布，这种分布的不平衡，铁路网发展的不平衡，是全世界现代资本主义即垄断资本主义造成的结果。这种结果表明，只要生产资料私有制还存在，在上述这样的经济基础上，帝国主义战争是绝对不可避免的。","language":"中文","translation":false},{"id":"imperialism-1-18","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"建筑铁路似乎是一种普通的、自然的、民主的、文化的、传播文明的事业。在那些由于粉饰资本主义奴隶制而得到报酬的资产阶级教授看来，在小资产阶级庸人看来，建筑铁路就是这么一回事。实际上，资本主义的线索象千丝万缕的密网，把这种事业同整个生产资料私有制连结在一起，把这种建筑事业变成对10亿人（殖民地加半殖民地），即占世界人口半数以上的附属国人民，以及对“文明”国家资本的雇佣奴隶进行压迫的工具。","language":"中文","translation":false},{"id":"imperialism-1-19","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"以小业主的劳动为基础的私有制，自由竞争，民主，——所有这些被资本家及其报刊用来欺骗工农的口号，都早已成为过去的东西。资本主义已成为极少数“先进”国对世界上绝大多数居民实行殖民压迫和金融扼杀的世界体系。瓜分这种“赃物”的是两三个世界上最强大的全身武装的强盗（美、英、日），他们把全世界卷入他们为瓜分自己的赃物而进行的战争。","language":"中文","translation":false},{"id":"imperialism-1-20","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"君主制的德国强迫签订的布雷斯特-里托夫斯克和约，以及后来美、法这些“民主的”共和国和“自由的”英国强迫签订的更残暴得多、卑鄙得多的凡尔赛和约，给人类做了一件天大的好事，它们把帝国主义雇用的文丐，把那些虽然自称为和平主义者和社会主义者，但是却歌颂“威尔逊主义”，硬说在帝国主义条件下可能得到和平和改良的反动小市民，全都揭穿了。","language":"中文","translation":false},{"id":"imperialism-1-21","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"英德两个金融强盗集团争夺赃物的战争留下的几千万尸体和残废者，以及上述这两个“和约”，空前迅速地唤醒了千百万受资产阶级压迫、蹂躏、欺骗、愚弄的民众。于是，在战争造成的全世界的经济破坏的基础上，世界革命危机日益发展，这个危机不管会经过多么长久而艰苦的周折，最后必将以无产阶级革命和这一革命的胜利而告终。","language":"中文","translation":false},{"id":"imperialism-1-22","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"第二国际的巴塞尔宣言在1912年所估计的正是1914年爆发的这样的战争，而不是一般战争（有各种各样的战争，也有革命的战争），——这个宣言现在仍是一个历史见证，它彻底揭露了第二国际英雄们的可耻破产和叛变行为。","language":"中文","translation":false},{"id":"imperialism-1-23","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"因此，我现在把这篇宣言转载在本版的附录里，并且再次请读者注意：这个宣言中确切、明白、直接地谈到这场即将到来的战争和无产阶级革命之间的联系的那些地方，第二国际的英雄们总是想方设法避开，就象小偷躲避他偷过东西的地方一样。","language":"中文","translation":false},{"id":"imperialism-1-24","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"本书特别注意批判“考茨基主义”这一国际思潮，在世界各国代表这一思潮的是第二国际的“最有名的理论家”和领袖（在奥地利是奥托·鲍威尔及其一伙，在英国是拉姆赛·麦克唐纳等人，在法国是阿尔伯·托马等等，等等），以及一大批社会党人、改良主义者、和平主义者、资产阶级民主派和神父。","language":"中文","translation":false},{"id":"imperialism-1-25","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这个思潮，一方面是第二国际瓦解、腐烂的结果，另一方面是由于整个生活环境而被资产阶级偏见和民主偏见所俘虏的小资产者的意识形态的必然产物。","language":"中文","translation":false},{"id":"imperialism-1-26","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基及其同伙的这类观点，正好完全背弃了这位著作家在几十年里，特别是在同社会主义运动中的机会主义（伯恩施坦、米勒兰、海德门、龚帕斯等人的机会主义）作斗争时所捍卫的那些马克思主义的革命原理。因此，现在 “考茨基派”在全世界都同极端机会主义者（通过第二国际即黄色国际）和资产阶级政府（通过有社会党人参加的资产阶级联合政府）在政治实践上联合起来，这并不是偶然的。","language":"中文","translation":false},{"id":"imperialism-1-27","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在全世界日益发展的一般无产阶级革命运动，特别是共产主义运动，不能不分析和揭露“考茨基主义”的理论错误。所以要这样做，尤其是因为和平主义和一般“民主主义”在全世界还十分流行，这些思潮虽然丝毫不想冒充马克思主义，但是完全同考茨基及其一伙一样，也在掩饰帝国主义矛盾的深刻性和帝国主义产生革命危机的必然性。所以，无产阶级的政党必须同这些思潮作斗争，把受资产阶级愚弄的小业主和程度不同地处在小资产阶级生活条件下的千百万劳动者从资产阶级那里争取过来。","language":"中文","translation":false},{"id":"imperialism-1-28","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"关于第八章——《资本主义的寄生性和腐朽》，有必要说几句话。在本书正文中已经指出：过去是“马克思主义者”、现在是考茨基的战友和“德国独立社会民主党”的资产阶级改良主义政策主要代表人之一的希法亭，在这个问题上，比露骨的和平主义者和改良主义者英国人霍布森还后退了一步。现在，整个工人运动的国际性的分裂已经完全暴露出来了（第二国际和第三国际）。这两派之间的武装斗争和国内战争的事实也同样暴露出来了：在俄国，孟什维克和“社会革命党人”支持高尔察克和邓尼金，反对布尔什维克；在德国，谢德曼分子和诺斯克及其一伙同资产阶级一起反对斯巴达克派；在芬兰、波兰以及匈牙利等国也是如此。这个有世界历史意义的现象的经济基础是什么呢？","language":"中文","translation":false},{"id":"imperialism-1-29","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"就是资本主义的寄生性和腐朽，而这是资本主义的最高历史阶段即帝国主义所特有的。正如本书所证明的，资本主义现在已经划分出极少数特别富强的国家（其人口不到世界人口的1/10，即使按最“慷慨”和最夸大的计算，也不到1/5)，它们专靠“剪息票”来掠夺全世界。根据战前的价格和战前资产阶级的统计，资本输出的收入每年有80-100亿法郎。现在当然更多得多了。","language":"中文","translation":false},{"id":"imperialism-1-30","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"很明显，这种大量的超额利润（因为它是在资本家从“自己”国家工人身上榨取的利润之外得来的）可以用来收买工人领袖和工人贵族这个上层。那些“先进”国家的资本家也确实在收买他们，用直接的和间接的、公开的和隐蔽的办法千方百计地收买他们。","language":"中文","translation":false},{"id":"imperialism-1-31","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这个资产阶级化了的工人阶层即“工人贵族”阶层，这个按生活方式、工资数额和整个世界观说来已经完全小市民化的工人阶层，是第二国际的主要支柱，现在则是资产阶级的主要社会支柱（不是军事支柱）。因为这是资产阶级在工人运动中的真正代理人，是资本家阶级的工人帮办，是改良主义和沙文主义的真正传播者。在无产阶级同资产阶级的国内战争中，他们有不少人必然会站在资产阶级方面，站在“凡尔赛派”方面来反对“公社战士”。","language":"中文","translation":false},{"id":"imperialism-1-32","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"如果不懂得这个现象的经济根源，如果不充分认识这个现象的政治意义和社会意义，那么，在解决共产主义运动和即将到来的社会革命的实践任务方面，就会一步也不能前进。","language":"中文","translation":false},{"id":"imperialism-1-33","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"帝国主义是无产阶级社会革命的前夜。从1917年起，这已经在全世界范围内得到了证实。","language":"中文","translation":false},{"id":"imperialism-1-34","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在最近15─20年中，特别是在美西战争(1898年）和英布战争(1899-1902年）之后，新旧两大陆出版的经济学著作以及政治学著作，愈来愈多地用“帝国主义”这个概念来说明我们所处时代的特征了。1902年，在伦敦和纽约出版了英国经济学家约·阿·霍布森的《帝国主义》一书。作者所持的是资产阶级社会改良主义与和平主义的观点，这同过去的马克思主义者卡·考茨基今天的立场实质上是一样的，但是，他对帝国主义的基本经济特点和政治特点作了一个很好很详尽的说明。1910年，在维也纳出版了奥地利马克思主义者鲁道夫·希法亭的《金融资本》一书（俄译本1912年在莫斯科出版）。虽然作者在货币理论问题上有错误，并且书中有某种把马克思主义同机会主义调和起来的倾向，但是这本书对“资本主义发展的最新阶段”（希法亭这本书的副标题）作了一个极有价值的理论分析。实质上，近年来关于帝国主义问题的论述，特别是报刊上有关这个问题的大量文章中所谈的，以及各种决议，如1912年秋的开姆尼茨和巴塞尔两次代表大会的决议中所谈的，恐怕都没有超出这两位作者所阐述的，确切些说，所总结的那些思想的范围……","language":"中文","translation":false},{"id":"imperialism-1-35","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"下面，我们准备对帝国主义的基本经济特点的联系和相互关系，作一个简要的、尽量通俗的阐述。至于非经济方面的问题，我们就不谈了，尽管这还是值得一谈的。所引资料的出处及其它注释并不是所有的读者都感兴趣的，所以放在本书的最后。","language":"中文","translation":false},{"id":"imperialism-1-36","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本主义最典型的特点之一，就是工业蓬勃发展，生产集中于愈来愈大的企业的过程进行得非常迅速。现代工业调查提供了说明这一过程的最完备最确切的材料。","language":"中文","translation":false},{"id":"imperialism-1-37","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"例如在德国，每1000个工业企业中，雇用工人50人以上的大企业，1882年有3个，1895年有6个，1907年有9个。每100个工人中，这些企业的工人分别占22人、30人、37人。但是生产集中的程度要比工人集中的程度大得多，因为在大企业中劳动的生产率要高得多。蒸汽机和电动机的材料可以说明这一点。拿德国所谓广义的工业（包括商业和交通运输业等在内）来说，情况如下：在3265623个企业中，大企业有30588个，只占0.9%。在1440万工人中，它们的工人占570万，即占39.4%；在880万蒸汽马力中，它们占有660万马力，即占75.3%；在150万千瓦电力中，它们占有120万千瓦，即占77.2%。","language":"中文","translation":false},{"id":"imperialism-1-38","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"不到1%的企业，竟占有总数3/4以上的蒸汽力和电力！而297万个小企业（雇佣工人不超过5人的），即占总数91%的企业，却只占有7%的蒸汽力和电力！几万个最大的企业就是一切，数百万个小企业算不了什么。","language":"中文","translation":false},{"id":"imperialism-1-39","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国在1907年雇用工人1000人和1000人以上的企业，有586个。它们的工人几乎占总数的1/10(138万），它们的蒸汽力和电力几乎占总数的1/3(32%)。下面我们可以看到，货币资本和银行使极少数最大企业的这种优势变成更强大的而且是名副其实的压倒优势，就是说，几百万中小“业主”，甚至一部分大“业主”，实际上完全受几百个金融富豪的奴役。","language":"中文","translation":false},{"id":"imperialism-1-40","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在另一个现代资本主义先进国家北美合众国，生产集中发展得更加迅猛。美国统计把狭义的工业单独列出，并且按全年产值的多少把这种企业分成几类。1904年，产值在100万美元和100万美元以上的最大的企业有1900个（占企业总数216180个的0.9%)，它们有140万工人（占工人总数550万的25.6%)，产值为56亿美元（占总产值148亿美元的38%)。5年之后，即1909年，相应的数字如下：3060个企业（占企业总数268491个的1.1%)，有200万工人（占工人总数660万的30.5%)，产值为90亿美元（占总产值207亿美元的43.8%)。","language":"中文","translation":false},{"id":"imperialism-1-41","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国所有企业的全部产值，差不多有一半掌握在仅占企业总数百分之一的企业手里！而这3000个大型企业包括258个工业部门。由此可见，集中发展到一定阶段，可以说就自然而然地走到垄断。因为几十个大型企业彼此之间容易达成协议；另一方面，正是企业的规模巨大造成了竞争的困难，产生了垄断的趋势。这种从竞争到垄断的转变，不说是最新资本主义经济中最重要的现象，也是最重要的现象之一，所以我们必须比较详细地谈一下。但是，我们首先应当消除一个可能产生的误会。","language":"中文","translation":false},{"id":"imperialism-1-42","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国的统计资料说：在250个工业部门中有3000个大型企业。似乎每个部门只有12个规模最大的企业。","language":"中文","translation":false},{"id":"imperialism-1-43","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"但事实上并非如此。并不是每个工业部门都有大企业；另一方面，资本主义发展到了最高阶段，有一个极重要的特点，就是所谓联合制，即把不同的工业部门联合在一个企业中，这些部门或者是依次对原料进行加工（如把矿石炼成生铁，把生铁炼成钢，可能还用钢制造各种成品），或者是一个部门对另一个部门起辅助作用（如加工下脚料或副产品，生产包装用品，等等）。","language":"中文","translation":false},{"id":"imperialism-1-44","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"希法亭写道：“联合制把各种行情拉平，从而保证联合企业有更稳定的利润率。第二，联合制导致贸易的消除。第三，联合制使技术改进有可能实现，因而与‘单纯’企业,<即没有联合的企业>相比，能够获得更多的利润。第四，联合制使联合企业的地位比‘单纯’企业巩固，使它在原料跌价赶不上成品跌价的严重萧条<营业呆滞，危机>时期的竞争中得到加强。”","language":"中文","translation":false},{"id":"imperialism-1-45","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国资产阶级经济学家海曼写了一部描述德国钢铁工业中“混合”（即联合）企业的专着，他说：“单纯企业由于原料价格高、成品价格低而纷纷倒闭”。结果是：","language":"中文","translation":false},{"id":"imperialism-1-46","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“一方面剩下几个采煤量达几百万吨的大煤业公司，它们紧密地组成一个煤业辛迪加；其次，是同它们有密切联系的、组成钢铁辛迪加的一些大铸钢厂。这些大型企业每年生产40万吨钢，采掘大量的矿石和煤炭，生产钢制品，有1万个住在工厂区集体宿舍中的工人，有的还有自己专用的铁路和港口。这种大型企业是德国钢铁工业的典型代表。而且集中还在不断地发展。某些企业愈来愈大；同一工业部门或不同工业部门的企业结合为大型企业的愈来愈多，而且有柏林的6家大银行作它们的靠山和指挥者。德国采矿工业确切地证实了卡尔·马克思关于集中的学说是正确的，诚然，这里指的是用保护性的关税和运费率来保护采矿工业的国家。德国采矿工业已经成熟到可以被剥夺的地步了。”","language":"中文","translation":false},{"id":"imperialism-1-47","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这就是一个诚实的（这是一个例外）资产阶级经济学家势必得出的结论。必须指出，他把德国似乎看得很特殊，因为德国工业受到高额保护关税的保护。但是这种情况只能加速集中，加速企业家垄断同盟卡特尔、辛迪加等等的形成。特别重要的是，在自由贸易的国家英国，集中同样导致垄断，尽管时间较晚，形式也许有所不同。请看赫尔曼·莱维教授根据大不列颠经济发展材料写的专着《垄断组织——卡特尔和托拉斯》中的一段话：","language":"中文","translation":false},{"id":"imperialism-1-48","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“在大不列颠，正是企业的巨大规模和高度技术水平包含着垄断的趋势。一方面，由于集中的结果，对每一企业必须投入大量资本，因此，新企业在必要资本方面面临着愈来愈高的要求，这就使新企业难以出现。另一方面，（我们认为这一点更重要），每个新企业要想同时集中所造成的那些大型企业并驾齐驱，就必须生产大量的过剩产品，而这些产品只有在需求异常增加的时候才能有利的销售出去，否则这种产品过剩就会使价格跌到无论对新工厂或各垄断同盟都不利的程度。”英国和那些有保护关税促进卡特尔化的国家不同，在这里，企业家垄断同盟卡特尔和托拉斯，多半是在互相竞争的主要企业的数目缩减到“一两打”的时候才产生的。“集中对产生大工业垄断组织的影响，在这里表现得非常明显。”","language":"中文","translation":false},{"id":"imperialism-1-49","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在半个世纪以前马克思现写《资本论》的时候，绝大多数经济学家都认为自由竞争是一种“自然规律”。官方学者曾经力图用缄默这种阴谋手段来扼杀马克思的著作，因为马克思对资本主义所作的理论和历史的分析，证明了自由竞争产生生产集中，而生产集中发展到一定阶段就导致垄断。现在，垄断已经成了事实。经济学家们正在写大堆大堆的著作，叙述垄断的某些表现，同时却齐声宣告：“马克思主义被驳倒了。”但是，英国有句谚语说得好：事实是顽强的东西，不管你愿意不愿意，你都得重视事实。事实证明：某些资本主义国家之间的差别，例如实行保护主义还是实行自由贸易，只能在垄断组织的形式上或产生的时间上引起一些非本质的差别，而生产集中产生垄断，则是现阶段资本主义发展的一般的和基本的规律。","language":"中文","translation":false},{"id":"imperialism-1-50","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"对于欧洲，可以相当精确地确定新资本主义最终代替旧资本主义的时间是20世纪初。在最近出版的一本关于“垄断组织的形成”的历史的综合性著作中，我们看到有下面几段话：","language":"中文","translation":false},{"id":"imperialism-1-51","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“我们可以从1860年以前的时代里举出资本主义垄断组织的个别例子；从这些例子可以看出现在极常见的那些形式的萌芽；但是这一切无疑还是卡特尔的史前时期。现代垄断组织的真正开始，最早也不过是19世纪60年代的事。垄断组织的第一个大发展时期，是从19世纪70年代国际性的工业萧条开始，一直延续到19世纪90年代初期。”“如果从欧洲范围来看，60年代和70年代是自由竞争发展的顶点。当时，英国建成了它的那种旧式资本主义组织。在德国，这种组织同手工业和家庭工业展开了坚决的斗争，开始建立自己的存在形式。”","language":"中文","translation":false},{"id":"imperialism-1-52","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“大转变是从1873年的崩溃时期，确切些说，是从崩溃后的萧条时期开始的；这次萧条在欧洲经济史上持续了22年，只是在80年代初稍有间断，并在1889年左右出现过异常猛烈然而为时甚短的高涨。”“在1889-1890年短促的高涨期间，人们大力组织卡特尔来利用行情。轻率的政策使价格比没有卡特尔时提高得更快更厉害，结果所有这些卡特尔差不多全都不光彩地埋葬在‘崩溃这座坟墓’里了。后来又经过了5年不景气和价格低落的时期，但是这时笼罩在工业界的已经不是从前那种情绪了。人们已经不把萧条看成什么当然的事情，而认为它不过是有利的新行情到来之前的一种间歇。","language":"中文","translation":false},{"id":"imperialism-1-53","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"于是卡特尔运动进入了第二个时期。卡特尔已经不是暂时的现象，而成了全部经济生活的基础之一。它占领一个又一个的工业部门，而首先是占领原料加工部门。早在19世纪90年代初，在组织焦炭辛迪加（后来的煤业辛迪加就是仿照它建立的）时，卡特尔就创造了后来基本上再没有发展的组织卡特尔的技术。19世纪末的巨大高涨和1900-1903年的危机，至少在采矿和钢铁工业方面，都是第一次完全在卡特尔的标志下发生的。当时人们还觉得这是一种新现象，而现在社会上则普遍认为，经济生活的重大方面通常不受自由竞争的支配，是一种不言而喻的事情了。”","language":"中文","translation":false},{"id":"imperialism-1-54","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"综上所述，对垄断组织的历史可以作如下的概括：(1)19世纪60年代和70年代是自由竞争发展的顶点即最高阶段。这时垄断组织还只是一种不明显的萌芽。(2)1873年危机之后，卡特尔有一段很长的发展时期，但卡特尔在当时还是一种例外，还不稳固，还是一种暂时现象。(3)19世纪末的高涨和1900-1903年的危机。这时卡特尔成了全部经济生活的基础之一。资本主义转化为帝国主义。","language":"中文","translation":false},{"id":"imperialism-1-55","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"卡特尔彼此商定销售条件和支付期限等等。它们彼此划分销售地区。它们规定所生产的产品的数量。它们确定价格。它们在各个企业之间分配利润，等等。","language":"中文","translation":false},{"id":"imperialism-1-56","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国的卡特尔在1896年约有250个，在1905年有385个，参加卡特尔的企业约有12000个。但是，大家都承认，这是缩小了的数字。从上面引用的1907年的德国工业统计材料可以看出，单是这12000个最大的企业，就集中了大约占总数一半以上的蒸汽力和电力。北美合众国的托拉斯在1900年是185个，在1907年是250个。美国的统计把所有的工业企业分为属于个人的和属于合伙商行、公司的。后者在1904年占企业总数的23.6%，在1909年占25.9%，即1/4以上。这些企业的工人，在1904年占工人总数的70.6%，在1909年占75.6%，即3/4；产值分别是109亿美元和163亿美元，即占总产值的73.7%和79%。","language":"中文","translation":false},{"id":"imperialism-1-57","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"一个工业部门的生产总量，往往有十分之七八集中在卡特尔和托拉斯手中。莱茵-威斯特伐利亚煤业辛迪加在1893年成立时，集中了该地区总采煤量的86.7%,到1910年则已经达到95.4%。这样造成的垄断，保证获得巨额的收入，并导致组成规模极大的技术生产单位。 美国著名的煤油托拉斯（美孚油公司），是1900年成立的。“它的资本是15000万美元。当时发行了1亿美元的普通股票和10600万美元的优先股票。1900-1907年，每年支付的优先股票的股息分别为：48%、48%、45%、44%、36%、40%、40%、40%，共计36700万美元。1882-1907年的纯利为88900万美元，其中60600万付股息，其余的作为后备资本。”“钢铁托拉斯（美国钢铁公司）所有企业的职工，在1907年达210180人。德国采矿工业中最大的企业盖尔森基兴矿业公司在1908年有46048名职工。”钢铁托拉斯在1902年就生产了900万吨钢。它的钢产量在1901年占美国全部钢产量的66.3%，在1908年占56.1%。它的矿石开采量，在1901年占43.9%，在1908年占46.3%。","language":"中文","translation":false},{"id":"imperialism-1-58","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国政府专门委员会关于托拉斯的报告中说：“它比竞争者优越，是因为它的企业规模大，技术装备优良。烟草托拉斯从创办的时候起，就竭力在各方面大规模地采用机器来代替手工劳动。为此目的，它收买了与烟草加工多少有关的一切发明专利权，在这方面花费了巨额款项。有许多发明起初是不适用的，必须经过在托拉斯供职的工程师的改进。在1906年年底设立了两个分公司，专门收买发明专利权。为了同一目的，托拉斯又设立了自己的铸造厂、机器厂和修理厂。设在布鲁克莱恩的一个这样的工厂有大约300名工人；这个厂对有关生产纸烟、小雪茄、鼻烟、包装用的锡纸和烟盒等等的发明进行试验，在这里还对各种发明进行改进。”“其它托拉斯也雇有所谓技术开发工程师，他们的任务就是发明新的生产方法，进行技术改良的试验。钢铁托拉斯给那些在提高技术或减少费用方面有发明创造的工程师和工人以高额奖金。”","language":"中文","translation":false},{"id":"imperialism-1-59","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国的大工业，例如近几十年来获得巨大发展的化学工业，也是这样组织技术改良工作的。到1908年，生产集中的过程已经在这个工业中造成了两大“集团”，它们也都按自己的方式逐步走向垄断。起初，这两个集团都是由两对大工厂组成的“双边联盟”，各有资本2000-2100万马克：一对是美因河畔赫希斯特的前行东……颜料厂和美因河畔法兰克福的卡塞拉公司；另一对是路德维希港苯胺苏打厂和爱北斐特的前拜尔公司。后来，一个集团在1905年，另一个集团在1908年，又各同另一个大工厂达成了协议。结果构成了两个“三边联盟”，各有资本4000-5000万马克，而且这两个“联盟”已经开始“接近”，“商定”价格等等。","language":"中文","translation":false},{"id":"imperialism-1-60","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"竞争转化为垄断。生产的社会化有了巨大的进展。就连技术发明和技术改进的过程也社会化了。","language":"中文","translation":false},{"id":"imperialism-1-61","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"从前是各个业主自由竞争，他们是分散的，彼此毫不了解，他们进行生产都是为了在情况不明的市场上去销售，现在则完全不同了。集中已经达到了这样的程度，可以对本国的，甚至像下面所说的，对许多国家以至全世界所有的原料来源（例如蕴藏铁矿的土地）作出大致的估计。现在不但进行这样的估计，而且这些来源完全操纵在一些大垄断同盟的手里。这些同盟对市场的容量也进行大致的估计，并且根据协议“瓜分”这些市场。他们垄断熟练的劳动力，雇用最好的工程师，霸占交通路线和交通工具，如美国的铁路、欧美的轮船公司。帝国主义阶段的资本主义紧紧接近最全面的生产社会化，它不顾资本家的愿望与意识，可以说是把他们拖进一种从完全的竞争自由向完全的社会化过渡的新的社会秩序。","language":"中文","translation":false},{"id":"imperialism-1-62","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"生产社会化了，但是占有仍然是私人的。社会化的生产资料仍旧是少数人的私有财产。在形式上被承认的自由竞争的一般架子依然存在，而少数垄断者对其余居民的压迫却更加百倍地沉重、显着和令人难以忍受了。","language":"中文","translation":false},{"id":"imperialism-1-63","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国经济学家克斯特纳写了一本专论“卡特尔与局外人斗争情况”的著作，所谓“局外人”就是未加入卡特尔的企业家。他给这本着作取名为《强迫加入组织》，其实，如果不粉饰资本主义，就应该说是强迫服从垄断者同盟。单是看看垄断者同盟为了这种“组织”而采取的种种现代的、最新的、文明的斗争手段，也是大有教益的。这些手段有：(1)剥夺原料（“...强迫加入卡特尔的主要手段之一”）；(2)用同盟方法剥夺劳动力（即资本家和工会订立合同，使工会只接受卡特尔化企业的工作）；(3)剥夺运输；(4)剥夺销路；(5)同买主订立合同，使他们只同卡特尔发生买卖关系；(6)有计划地压低价格（为了使“局外人”即不服从垄断者的企业破产，不惜耗费巨资，在一段时间内按低于成本的价格出售商品。）；(7)剥夺信贷；(8)宣布抵制。","language":"中文","translation":false},{"id":"imperialism-1-64","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在已经不是小企业同大企业、技术落后的企业同技术先进的企业进行竞争。现在已经是垄断者在扼杀那些不屈服于垄断、不屈服于垄断的压迫和摆布的企业了。下面就是这一过程在一位资产阶级经济学家意识中的反映。","language":"中文","translation":false},{"id":"imperialism-1-65","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"克斯特纳写道：“甚至在纯粹经济的活动方面，也在发生某种转变，原先意义上的商业活动转变为投机组织者的活动。获得最大成就的，不是最善于根据自己的技术和商业经验来判断购买者需要，找到并且可以说是‘开发’潜在需求的商人，而是那些善于预先估计到，或者哪怕只是嗅到组织上的发展，嗅到某些企业与银行可能发生某种联系的投机天才<?!>...”","language":"中文","translation":false},{"id":"imperialism-1-66","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"译成普通人的语言，这就是说：资本主义已经发展到这样的程度，商品生产虽然依旧“占统治地位”，依旧被看作全部经济的基础，但实际上已经被破坏了，大部分利润被那些干金融勾当的“天才”拿去了。这种金融勾当和欺骗行为的基础是生产的社会化，人类历尽艰辛所达到的生产社会化这一巨大进步，却造福于……投机者。下面我们会看到，那些对资本帝国主义作小市民式的反动批评的人，怎样“根据这一点”而梦想开倒车，恢复“自由的”、“和平的”、“诚实的”竞争。","language":"中文","translation":false},{"id":"imperialism-1-67","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"克斯特纳说：“由卡特尔的组成引起的价格长期上涨，至今还只有出现在最重要的生产资料方面，特别是煤、铁和钾碱等方面，而在成品方面则从来没有过。随之而来的收益的增加，同样也只限于生产生产资料的工业。对此还要作一点补充：原料（而不是半成品）加工工业不仅因组成卡特尔而获得高额利润，使那些进一步加工半成品的工业受到损失，而且它还取得了对这一工业的一定的统治关系，这是自由竞争时代所没有的。”","language":"中文","translation":false},{"id":"imperialism-1-68","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们作了着重标记的几个字，说明了问题的实质，这个实质是资产阶级经济学家很不愿意并且很少承认的，也是以卡 ·考茨基为首的当代的机会主义辩护士所竭力支吾搪塞、避而不谈的。统治关系和由此产生的强制，正是“资本主义发展的最新阶段”的典型现象，正是势力极大的经济垄断组织的形成所必然引起而且已经引起的结果。","language":"中文","translation":false},{"id":"imperialism-1-69","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们再举一个说明卡特尔如何经营的例子。凡是可以把全部或主要的原料产地抓在手里的地方，卡特尔的产生和垄断组织的形成就特别容易。但是，如果以为在无法霸占原料产地的其它工业部门中不会产生垄断组织，那就错了。水泥工业的原料是到处都有的。但是在德国，就连这个工业也高度卡特尔化了。水泥厂联合成了区域性的辛迪加，如南德辛迪加、莱茵-威斯特伐利亚辛迪加等等。规定了垄断价格：成本为180马克的一车皮水泥，售价竟达230-280马克！企业支付12-16%的股息，而且不要忘记，现代的投机“天才”除分得股息外，还能使大量的利润滚进自己的腰包。为了从如此盈利的工业部门中排除竞争，垄断者甚至使用各种诡计：散布谣言，说水泥工业情况很坏；在报上登匿名广告说，“资本家们！当心，别在水泥业投资！”；最后是收买没有参加辛迪加的“局外人”的企业，付给他们6万、8万、至15万马克的“出让费”。垄断组织在一切地方用一切办法为自己开辟道路，从偿付“微薄的”出让费起，直到像美国那样“使用”炸药对付竞争者为止。","language":"中文","translation":false},{"id":"imperialism-1-70","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"用卡特尔消除危机是拼命为资本主义涂脂抹粉的资产阶级经济学家的无稽之谈。相反，在几个工业部门中形成的垄断，使整个资本主义生产所特有的混乱现象更加厉害，更加严重。作为一般资本主义生特点的农业和工业发展不相适应的现象，变得更加严重了。卡特尔化程度最高的所谓重工业，尤其是煤铁工业的特权地位，使其余工业部门“更加严重地缺乏计划性”，正如论述“德国大银行与工业的关系”的最佳著作之一的作者耶德尔所承认的那样。","language":"中文","translation":false},{"id":"imperialism-1-71","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本主义最无耻的辩护士利夫曼说：“国民经济愈发展，就愈是转向更带冒险性的企业或国外的企业，转向需要长时间才能发展的企业，或者转向那些只有地方意义的企业。”冒险性的增大，归根到底是同资本的大量增加有关，资本可以说是漫溢出来而流向国外，如此等等。同时，技术的加速发展，又使国民经济各部门不相适应的因素、混乱和危机的因素日益增加。同一个利夫曼不得不承认说：“大概在不久的将来，人类又会碰到技术方面的一些也会影响到国民经济组织的大变革”...如电力、航空...“在发生这种根本性的经济变动的时候，通常而且照例会有很厉害的投机事业发展起来...”","language":"中文","translation":false},{"id":"imperialism-1-72","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"危机（各种各样的危机，最常见的是经济危机，但不是只有经济危机）又大大加强了集中和垄断的趋势。我们知道，1900年的危机，是现代垄断组织史上的转折点。关于这次危机的意义，耶德尔斯有一段非常值得注意的论断：","language":"中文","translation":false},{"id":"imperialism-1-73","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“遭到1900年危机的，除了各主要工业部门的大型企业以外，还有许多在今天说来结构上已经过时了的‘单纯’企业（即没有联合起来的企业），它们是乘着工业高涨的浪头浮上来的。价格的跌落，需求的减少，使这些‘单纯’企业陷于灾难的境地，这种情况，大型的联合企业或者根本没有遇到过，或者仅仅在极短的时期内碰到过。因此，1900年的危机引起的工业集中，其程度远远超过了1873年的危机。1873年的危机虽然也起了一种淘汰作用，使一些较好的企业保存下来，但是在当时的技术水平下，这种淘汰并没有能够使那些顺利地度过危机的企业获得垄断地位。长期地占据这种垄断地位的，是现在的钢铁工业和电力工业中的大型企业（因为它们的技术复杂，组织分布很广，资本雄厚），而且垄断程度很高；其次是机器制造业以及冶金工业、交通运输业等某些部门的企业，不过垄断程度较低。”","language":"中文","translation":false},{"id":"imperialism-1-74","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"垄断正是“资本主义发展的最新阶段”的最新成就。但是，如果我们不注意到银行的作用，那我们对于现代垄断组织的实际力量和意义的认识，就会是极不充分、极不完全和极其不足的。","language":"中文","translation":false},{"id":"imperialism-1-75","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"银行基本的和原来的业务是在支付中起中介作用。这样，银行就把不活动的货币资本变为活动的即生利的资本，把各种各样的货币收入汇集起来交给资本家阶级支配。","language":"中文","translation":false},{"id":"imperialism-1-76","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"随着银行业的发展及其集中于少数机构，银行就由中介人的普通角色发展成为势力极大的垄断者，它们支配着所有资本家和小业主几乎全部的货币资本，以及本国和许多国家的大部分生产资料和原料产地。为数众多的普通中介人成为极少数垄断者的这种转变，是资本主义发展成为资本帝国主义的基本过程之一，因此，我们应当首先来谈一谈银行业的集中。","language":"中文","translation":false},{"id":"imperialism-1-77","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在1907-1908年度，德国所有资本在100万马克以上的股份银行，共有存款70亿马克；到1912-1913年度，已达98亿马克。5年中增加了40%，而且这新增加的28亿马克中，有275000万马克属于57家资本在1000万马克以上的银行。存款在大小银行中的分配情形如下：","language":"中文","translation":false},{"id":"imperialism-1-78","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在存款总额中所占的百分比","language":"中文","translation":false},{"id":"imperialism-1-79","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"柏林9家大银行 其余48家资本在1000万马克以上的银行 115家资本在100─1000万马克的银行 资本不到100万马克的小银行 1907─8年度 47 32.5 16.5 4 1912─3年度 49 36 12 3","language":"中文","translation":false},{"id":"imperialism-1-80","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"小银行被大银行排挤，大银行当中仅仅9家银行就差不多集中了所有存款的一半。但是，这里还有许多情况没有考虑进去，例如有许多小银行实际上成了大银行的分行，等等。关于这些下面就要讲到。","language":"中文","translation":false},{"id":"imperialism-1-81","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"据舒尔采-格弗尼茨计算，1913年底，存款总额约为100亿马克，而柏林9家大银行就占了51亿马克。这位作者不仅注意到存款，而且注意到全部银行资本，他写道：“1909年年底，柏林9家大银行及其附属银行，支配着113亿马克，即约占德国银行资本总额的83%。德意志银行及其附属银行支配着约30亿马克，与普鲁士国有铁路管理局同为旧大陆上资本聚集最多、而且分权程度很高的企业。”","language":"中文","translation":false},{"id":"imperialism-1-82","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们在提到“附属”银行的地方用了着重标记，因为这是最新资本主义集中的最重要的特点之一。大企业，尤其是大银行，不仅直接吞并小企业，而且通过“参与”它们的资本、购买或交换股票，通过债务关系体系等等来“联合”它们，征服它们，吸收它们加入“自己的”集团，用术语说，就是加入自己的康采恩。 利夫曼教授写了一本500页的大“著作”，描述现代的参与和投资公司，可惜，这本书里给那些往往未经消化的原始材料加上了十分低劣的“理论”推断。关于这种“参与”制在集中方面造成的结果怎样，说得最清楚的是银行“活动家”里塞尔那本论德国大银行的著作。但是，在引用他的材料之前，我们先举一个“参与”的具体例子。","language":"中文","translation":false},{"id":"imperialism-1-83","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德意志银行集团，在所有大银行集团当中，不说是最大的集团，也是最大的集团之一。要弄清楚把这一集团所有的银行联系在一起的主要线索，应当区分第一级、第二级和第三级的“参与”，或者说是第一级、第二级和第三级的依附（比较小的银行对德意志银行的依附）。具体情况如下：","language":"中文","translation":false},{"id":"imperialism-1-84","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"第一级依附： 第二级依附： 第三级依附：","language":"中文","translation":false},{"id":"imperialism-1-85","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德意志银行 始终参与 17家银行； 其中有9家又参与34家银行； 其中有4家又参与7家银行","language":"中文","translation":false},{"id":"imperialism-1-86","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"间或参与 8家银行； 其中有5家又参与14家银行； 其中有2家又参与2家银行","language":"中文","translation":false},{"id":"imperialism-1-87","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"共 计 30家银行； 其中有14家又参与48家银行； 其中有6家又参与9家银行","language":"中文","translation":false},{"id":"imperialism-1-88","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在“间或”隶属于德意志银行的8家“第一级依附”的银行中，有3家国外银行：一家是奥地利的（维也纳的联营银行），两家是俄国的（西伯利亚商业银行和俄国对外贸易银行）。直接和间接地、全部和局部地加入德意志银行集团的，共有87家银行，这个集团所支配的资本，包括自己的和他人的，共有20-30亿马克。","language":"中文","translation":false},{"id":"imperialism-1-89","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"一家银行既然领导着这样一个集团，并且同其它6家稍小一点的银行达成协议，来办理公债之类的特别巨大、特别有利的金融业务，那么很明显，这家银行已经不仅仅扮演“中介人”的角色，而成了极少数垄断者的同盟。","language":"中文","translation":false},{"id":"imperialism-1-90","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"从下面我们简略地摘引的里塞尔的统计材料可以看出，正是在19世纪末和20世纪初，德国银行业的集中发展得多么迅速：","language":"中文","translation":false},{"id":"imperialism-1-91","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"柏林6家大银行拥有的机构","language":"中文","translation":false},{"id":"imperialism-1-92","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"年份 在德国的分行 存款部和兑换所 始终参与的德国股份银行 机构总数 1895 16 14 1 42 1900 21 40 8 80 1911 104 276 63 450","language":"中文","translation":false},{"id":"imperialism-1-93","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们看到，银行渠道的密网扩展得多么迅速，它布满全国，集中所有的资本和货币收入，把成千上万分散的经济变成一个统一的全国性的资本主义经济，并进而变成世界性的资本主义经济。舒尔采-格弗尼茨在上面那段引文中代表现代资产阶级政治经济学所说的那个“分权”，实际上却是愈来愈多的从前比较“独立的”、确切些说是地方性的同外界隔绝的经济单位，隶属于一个统一的中心。其实，这是集权，是垄断巨头的作用、意义和实力的加强。","language":"中文","translation":false},{"id":"imperialism-1-94","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在比较老的资本主义国家中，这种“银行网”更密。英国，包括爱尔兰，1910年所有银行的分行共有7151个。其中4家大银行各有400个以上的分行(447个至689个），另外还有4家大银行各有200多个分行，11家银行各有100多个分行。","language":"中文","translation":false},{"id":"imperialism-1-95","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"法国三家最大的银行里昂信贷银行、国民贴现银行和总公司的业务和分行网发展的情形如下：","language":"中文","translation":false},{"id":"imperialism-1-96","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"分行和部所数目 资本额（单位百万法郎)","language":"中文","translation":false},{"id":"imperialism-1-97","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在地方上 在巴黎 共计 自有的 他人的 1870年 47 17 64 200 427 1890年 192 66 258 265 1245 1909年 1033 196 1229 887 4363","language":"中文","translation":false},{"id":"imperialism-1-98","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"为了说明现代大银行“联系”的特点，里塞尔引用了德国和全世界最大的银行之一贴现公司（它的资本在1914年已经达到3亿马克）收发信件的统计数字：","language":"中文","translation":false},{"id":"imperialism-1-99","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1852年 6135 6292","language":"中文","translation":false},{"id":"imperialism-1-100","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1870年 85800 87513","language":"中文","translation":false},{"id":"imperialism-1-101","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1900年 533102 626043","language":"中文","translation":false},{"id":"imperialism-1-102","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"巴黎大银行里昂信贷银行的帐户数目：在1875年是28535个，而在1912年就增加到633539个。","language":"中文","translation":false},{"id":"imperialism-1-103","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这些简单的数字，也许比长篇大论更能清楚的表明：随着资本的集中和银行周转额的增加，银行的作用根本改变了。分散的资本家合成了一个集体的资本家。银行为某些资本家办理往来帐，似乎是在从事一种纯粹技术性的、完全辅助性的业务。而当这种业务的范围扩展到很大的时候，极少数垄断者就控制整个资本主义社会的工商业业务，就能通过银行的联系，通过往来帐及其它金融业务，首先确切地了解各资本家的业务状况，然后加以监督，用扩大或减少、便利或阻难信贷的办法来影响他们，以至最后完全决定他们的命运，决定他们的收入，夺去他们的资本，或者使他们有可能迅速而大量的增加资本等等。","language":"中文","translation":false},{"id":"imperialism-1-104","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们刚才谈到柏林的贴现公司有3亿马克的资本。贴现公司资本增加的经过，是柏林两家最大的银行德意志银行和贴现公司争夺霸权斗争中的一幕。在1870年，德意志银行还是一家新银行，资本只有1500万马克，贴现公司有3000万马克。在1908年，前者有资本2亿，后者有资本17000万。到1914年，前者的资本增加到25000万，后者因为同另一家第一流的大银行沙夫豪森联合银行合并，资本就增加到了3亿。当然，在进行这种争夺霸权的斗争的同时，这两家银行也订立愈来愈频繁、愈来愈巩固的“协议”。这种发展的进程，使得那些在观察经济问题时决不越出最温和、最谨慎的资产阶级改良主义范围的银行专家，也不得不作出如下的结论。","language":"中文","translation":false},{"id":"imperialism-1-105","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国的《银行》杂志就贴现公司资本增加到3亿马克这一点写道：“其它银行也会跟着走上这条道路的，现在在经济上统治着德国的300人，将会逐渐减到50人、25人甚至更少一些。不要以为最新的集中运动将仅限于银行业。各个银行间的紧密联系，自然会使这些银行所保护的工业家的辛迪加也接近起来……会有一天，我们一觉醒来，将惊奇地发现我们面前尽是托拉斯，到那时我们必须以国家垄断来代替私人垄断。然而，除了听凭事情自由发展、让股票稍稍加速这种发展以外，我们实在是没有什么别的可以责备自己的。”","language":"中文","translation":false},{"id":"imperialism-1-106","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这段话是资产阶级政论界束手无策的典型表现，而资产阶级学术界不同的地方，就在于后者不那么坦率，力图掩饰事情的本质，让人只见树木，不见森林。看见集中的后果而感觉“惊奇”，“责备”资本主义德国的政府或资本主义的“社会”（“我们”），害怕采用股票会“加速”集中，例如德国的一个“卡特尔问题”专家契尔施基就害怕美国托拉斯，“宁愿”要德国的卡特尔，因为德国的卡特尔似乎“不会象托拉斯那样过分地加速技术和经济的进步”，——这难道不是束手无策的表现吗？","language":"中文","translation":false},{"id":"imperialism-1-107","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"但是，事实终归是事实。德国没有托拉斯，“只”有卡特尔，但统治德国的，不超过300个资本巨头。而且这些巨头的人数还在不断地减少。在任何情况下，在一切资本主义国家，不管有什么样不同的银行法，银行总是大大地加强并加速资本集中和垄断组织形成的过程。","language":"中文","translation":false},{"id":"imperialism-1-108","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"半个世纪以前马克思就在《资本论》里写过：“银行制度造成了社会范围的公共簿记和生产资料的公共的分配的形式，但只是形式而已。”我们所引用的关于银行资本的增长、关于最大银行的分支机构数目及其帐户数目的增加等材料，都具体地让我们看到了整个资本家阶级的这种“公共簿记”，而且不仅是资本家阶级的“公共簿记”，因为银行所收集的（即使是暂时收集的），是各种各样的货币收入，其中也有小业主的，也有职员的，也有极少数上层工人的。“生产资料的公共的分配”，从形式上看来，是从现代银行中生长出来的；这种最大的银行在法国不过3家到6家，在德国有6家到8家，它们支配着几十亿几十亿的款额。但是，生产资料的这种分配，就其内容来说，决不是“公共的”，而是私人的，也就是说，是符合大资本（首先是最大的、垄断的资本）的利益的，因为大资本正是在民众挨饿，农业的整个发展无可救药地落后于工业的发展，工业中“重工业”向其它一切工业部门收取贡赋的条件下活动的。","language":"中文","translation":false},{"id":"imperialism-1-109","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在资本主义经济社会化方面，储金局和邮政机构开始同银行竞争，它们是更加“分权”的，也就是说，它们把更多的地区、更多的偏僻地方和更广大的居民群众纳入自己的势力范围。下面是美国的一个委员会收集的对比银行和储金局存款增加情况的统计材料：","language":"中文","translation":false},{"id":"imperialism-1-110","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"银行存款 储金局存款 银行存款 储金局存款 银行存款 信贷协会存款 储金局存款","language":"中文","translation":false},{"id":"imperialism-1-111","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1880年 8.4 1.6 ？ 0.9 0.5 0.4 2.6","language":"中文","translation":false},{"id":"imperialism-1-112","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1888年 12.4 2.0 1.5 2.1 1.1 0.4 4.5","language":"中文","translation":false},{"id":"imperialism-1-113","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1908年 23.2 4.2 3.7 4.2 7.1 2.2 13.9","language":"中文","translation":false},{"id":"imperialism-1-114","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"储金局为了支付4%和4.25%的存款利息，就必须给自己的资本找到“有利的”投资场所，如从事票据、抵押等业务。银行和储金局之间的界限“日益消失”。例如波鸿和爱尔福特的商会，就要求“禁止”储金局经营票据贴现之类的“纯”银行业务，要求限制邮政机构经营“银行”业务。银行大王好象是在担心国家垄断会不会从意料不到的地方悄悄地钻到他们身旁。不过，这种担心当然没有超出可以说是一个办事处的两个科长之间的竞争。因为储金局的几十亿资本，实际上归根到底是由同一些银行资本巨头们支配的，这是一方面；另一方面，在资本主义社会里，国家的垄断不过是提高和保证某个工业部门快要破产的百万富翁的收入的一种手段罢了。","language":"中文","translation":false},{"id":"imperialism-1-115","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"自由竞争占统治地位的旧资本主义，被垄断占统治地位的新资本主义所替代，还表现在交易所作用的降低上面。《银行》杂志写道：“交易所早已不再是必要的流通中介人了，它过去曾经是，因为过去银行还不能把发行的大部分有价证券推销到自己的顾客中间去。”","language":"中文","translation":false},{"id":"imperialism-1-116","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“‘任何银行都是交易所’，——这是一句现代的名言。银行愈大，银行业的集中愈有进展，这句名言所包含的真理也愈多。”“从前，在70年代，象年轻人那样放荡的交易所〈这是对1873年交易所的崩溃，对滥设投机公司的丑事等等所作的一种“微妙的”暗示〉，开辟了德国的工业化时代，而现在银行和工业已经能‘独立应付’了。我国大银行对交易所的统治……正表明德国是一个十分有组织的工业国。如果说这样就缩小了自动起作用的经济规律的作用范围，而大大扩大了通过银行进行有意识的调节的范围，那么少数领导人在国民经济方面所负的责任也就因此而大大加重了。”——德国教授舒尔采-格弗尼茨就是这样写的，这位教授是德国帝国主义的辩护士，是各国帝国主义者眼中的权威，他力图抹杀一件“小事情”，即这种通过银行进行的“有意识的调节”，就是由极少数“十分有组织的”垄断者对大众的掠夺。资产阶级教授的任务不是暴露全部内幕，不是揭穿银行垄断者的种种勾当，而是加以粉饰。","language":"中文","translation":false},{"id":"imperialism-1-117","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"一位更有威望的经济学家和银行“活动家”里塞尔也完全一样，他用一些言之无物的空话来回避无可否认的事实：“交易所正在愈来愈失去为整个经济和有价证券流通所绝对必需的性能，即不仅作为汇集到它那里的各种经济运动的最准确的测量器，而且作为对这些经济运动几乎自动起作用的调节器。”","language":"中文","translation":false},{"id":"imperialism-1-118","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"换句话说，旧的资本主义，即绝对需要交易所作为自己的调节器的自由竞争的资本主义，正在成为过去。代替它的是新的资本主义，这种新的资本主义带有某种过渡性事物、某种自由竞争和垄断混合物的鲜明特征。人们自然要问，这种最新的资本主义是在向哪里“过渡”呢？但这个问题资产阶级学者是不敢提出的。","language":"中文","translation":false},{"id":"imperialism-1-119","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“在30年前，不属于‘工人’体力劳动范围以内的经济工作，9/10都是由自由竞争的企业家来做的。现在，这种经济上的脑力工作9/10都是由职员们来担任了。在这一发展中处于领先地位的是银行业。”舒尔采-格弗尼茨的这种供认，使人们又再次触及这样一个问题：最新的资本主义，即帝国主义阶段的资本主义，究竟是向哪里去的过渡呢？------","language":"中文","translation":false},{"id":"imperialism-1-120","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在少数几个经过集中过程而仍然在整个资本主义经济中处于领先地位的银行中间，达成垄断协议、组织银行托拉斯的倾向自然愈来愈明显，愈来愈强烈。美国现在已经不是9家，而是2家最大的银行，即亿万富翁洛克菲勒和摩根的银行，控制着110亿马克的资本。在德国，我们上面指出的贴现公司吞并沙夫豪森联合银行的事实，引起了代表交易所利益的《法兰克福报》如下的一段评论：","language":"中文","translation":false},{"id":"imperialism-1-121","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“随着银行的日益集中，只能向愈来愈少的机构请求贷款了，这就使大工业更加依赖于少数几个银行集团。在工业同金融界联系密切的情况下，需要银行资本的那些工业公司活动的自由受到了限制。因此，大工业带着错综复杂的感情看待银行的日益托拉斯化〈联合成或转变为托拉斯〉；的确，我们已经多次看到各大银行康采恩之间开始达成某种限制竞争的协议。”","language":"中文","translation":false},{"id":"imperialism-1-122","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"银行业发展的最新成就还是垄断。","language":"中文","translation":false},{"id":"imperialism-1-123","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"说到银行和工业的密切联系，那么，正是在这一方面，银行的新作用恐怕表现得最明显。银行给某个企业主贴现票据，给他开立往来帐户等等，这些业务单独地来看，一点也没有减少这个企业主的独立性，银行也没有越出普通的中介人作用的范围。可是，如果这些业务愈来愈频繁、愈来愈加强，如果银行把大量资本“收集”在自己手里，如果办理某个企业的往来帐使银行能够愈来愈详细和充分地了解它的顾客的经济状况（事实上也确实如此），那么，结果就是工业资本家愈来愈完全依赖于银行。","language":"中文","translation":false},{"id":"imperialism-1-124","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"同时，银行同最大的工商业企业之间的所谓人事结合也发展起来，双方通过占有股票，通过银行和工商业企业的经理互任对方的监事（或董事），而日益融合起来。德国经济学家耶德尔斯搜集了关于这种形式的资本集中和企业集中的极为详细的材料。柏林6家最大的银行由经理做代表，参加了344个工业公司，又由董事做代表，参加了407个公司，一共参加了751个公司。它们在289个公司中各有两个监事，或者占据了监事长的位置。在这些工商业公司中，有各种各样的行业，如保险业、交通运输业、饭馆、戏院、工艺美术业等等。另一方面，在这6家银行的监事会中（在1910年）有51个最大的工业家，其中有克虏伯公司的经理、大轮船公司沃堡-美洲包裹投递股份公司的经理等等。在1895─1910年间，这6家银行中的每一家银行都参加了替数百个(281个至419个）工业公司发行股票和债券的工作。","language":"中文","translation":false},{"id":"imperialism-1-125","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"除银行同工业的“人事结合”以外，还有这些或那些公司同政府的“人事结合”。耶德尔斯写道：“它们自愿把监事职位让给有声望的人物和过去的政府官吏，这些人可以使公司在同当局打交道的时候得到不少方便〈！！〉……”“在大银行的监事会里，常有国会议员或柏林市议会的议员。”","language":"中文","translation":false},{"id":"imperialism-1-126","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"可见，所谓大资本主义垄断组织正在通过一切“自然的”和“超自然的”途径十分迅速地创立和发展起来。现代资本主义社会中几百个金融大王之间的某种分工正在有步骤地形成：","language":"中文","translation":false},{"id":"imperialism-1-127","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“除了某些大工业家活动范围的这种扩大〈如加入银行董事会等等〉以及地方银行经理分别专管某一工业区以外，大银行领导人的专业化也有所加强。这样的专业化，只有在整个银行企业的规模很大，尤其是在银行同工业的联系很广的时候，才能设想。这种分工是在两个方面进行的：一方面，把联系整个工业界的事情交给一个经理去做，作为他的专职；另一方面，每个经理都负责监督几个企业或几组在行业上、利益上彼此相近的企业〈资本主义已经发展到可以有组织地监督各个企业的程度了〉。某个经理专门管德国工业，甚至专门管德国西部的工业〈德国西部是德国工业最发达的区域〉，另一些经理则专门负责同外国和外国工业联系，了解工业家等等的个人的情况，掌管交易所业务等等。此外，银行的每个经理又往往专管某个地方或某个工业部门：有的主要是在电力公司监事会里工作，有的是在化学工厂、啤酒厂或制糖厂里工作，有的是在少数几个孤立的企业中工作，同时又参加保险公司监事会…… 总而言之，在大银行里，随着银行业务的扩大和业务种类的增多，领导人的分工无疑也就更加细密，其目的（和结果）是使他们稍微超出纯银行业务的范围，使他们对工业的一般问题以及各个工业部门的特殊问题更有判断力，更加懂行，培养他们在银行势力所及的工业部门中进行活动的能力。除了这一套办法以外，银行还竭力挑选熟悉工业的人物，挑选企业家、过去的官吏、特别是在铁路和采矿部门中工作过的官吏，来参加本银行的监事会”等等。","language":"中文","translation":false},{"id":"imperialism-1-128","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在法国银行业里，也有这一类的机构，不过形式稍微有点不同。例如，法国三家最大的银行之一里昂信贷银行，设立了一个专门的金融情报收集所。在那里工作的经常有50多个工程师、统计学家、经济学家和法学家等等。这个机构每年耗资60─70万法郎。它下面又分8个科：有的科专门收集工业企业情报，有的研究一般统计，有的研究铁路和轮船公司，有的研究证券，有的研究财务报告等等。","language":"中文","translation":false},{"id":"imperialism-1-129","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这样，一方面是银行资本和工业资本日益融合，或者用尼·伊·布哈林的很恰当的说法，日益长合在一起，另一方面是银行发展成为具有真正“包罗一切的性质”的机构。我们认为有必要引用在这方面最有研究的作家耶德尔斯对这个问题的准确的说法：","language":"中文","translation":false},{"id":"imperialism-1-130","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“我们考察了全部工业联系，结果发现那些为工业工作的金融机构具有包罗一切的性质。大银行同其它形式的银行相反，同某些著作中提出的银行应当专门从事某一方面业务或某一工业部门工作，以免丧失立脚点这样的要求相反，力求在尽可能不同的地区和行业同工业企业发生联系，力求消除各个地方或各个工业部门因各个企业历史情况不同而形成的资本分配不均现象。”“一种趋势是使银行同工业的联系成为普遍的现象，另一种趋势是使这种联系更加巩固和加强；这两种趋势在六大银行中虽然没有完全实现，但是已经在同样程度上大规模地实现了。”","language":"中文","translation":false},{"id":"imperialism-1-131","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在工商界经常听到有人抱怨银行的“恐怖主义”。既然大银行象下面的例子所表明的那样“发号施令”，那么听到这样的抱怨也就不奇怪了。1901年11月19日，柏林所谓Ｄ字银行(4家最大银行的名称都是以字母Ｄ开头的）之一，给西北德一中德水泥辛迪加管理处写了这样一封信：“兹阅贵处本月18日在某报上登载的通知，我们不得不考虑到贵辛迪加定于本月30日召开的全体大会，可能通过一些改革贵企业而为敝行所不能接受的决议。因此我们深感遗憾，不得不停发贵辛迪加所享有的贷款……但如此次大会不通过敝行不能接受的决议，并向敝行提出将来也不通过这种决议的相应保证，敝行仍愿就给予贵辛迪加以新的贷款问题举行谈判。”其实，这也是小资本对大资本的压迫发出的抱怨，不过这里列入“小”资本的是整整一个辛迪加罢了！大小资本之间过去的那种斗争，又在一个新的、高得多的发展阶段上重演了。当然，拥有亿万巨资的大银行企业，也能用从前远不能相比的办法来推动技术的进步。例如，银行设立了各种专门的技术研究会，研究成果当然只能由“友好的”工业企业来享用。这一类机构有电气铁路问题研究会、中央科学技术研究所等等。","language":"中文","translation":false},{"id":"imperialism-1-132","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"大银行的领导人自己不会看不到，国民经济中正在出现一些新的情况，但是他们在这些情况面前束手无策。","language":"中文","translation":false},{"id":"imperialism-1-133","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"耶德尔斯写道：“凡是近几年来注意大银行经理和监事人选变更情形的人，都不会不觉察到，权力逐渐转到了一些认为积极干预工业的总的发展是大银行必要的、愈来愈迫切的任务的人物手中，于是这些人和老的银行经理在业务方面，往往也在个人方面意见愈来愈分歧。实质的问题是：银行这种信贷机构会不会因为干预工业生产过程而受到损失，会不会因为从事这种同信贷中介作用毫不相干的业务，从事这种会使它比从前更受工业行情的盲目支配的业务，而牺牲掉自己的稳固的原则和可靠的利润。许多老的银行领导人都说会这样。但是，大部分年轻的领导人却认为积极干预工业问题是必然的，正象随着现代大工业的出现必然会产生大银行和最新的工业银行业一样。双方的意见只有一点相同，就是大家都认为大银行的新业务还没有什么固定的原则和具体的目的。”","language":"中文","translation":false},{"id":"imperialism-1-134","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"旧资本主义已经过时了。新资本主义是向某方面的过渡。想找到什么“固定的原则和具体的目的”来“调和”垄断和自由竞争，当然是办不到的事情。实践家的自白，听起来和舒尔采-格弗尼茨、利夫曼之流的“理论家”的颂扬完全不同，这些资本主义的辩护士是在用官场口吻颂扬“有组织的”资本主义的美妙。","language":"中文","translation":false},{"id":"imperialism-1-135","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"大银行的“新业务”究竟是什么时候完全确立起来的，——对于这个重要问题，我们可以从耶德尔斯那里找到相当确切的答案：","language":"中文","translation":false},{"id":"imperialism-1-136","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“工业企业间的联系及其新的内容、新的形式、新的机构即既集权又分权的大银行，成为国民经济的有代表性的现象，大概不会早于19世纪90年代；在某种意义上，甚至可以把这个起点推到1897年，当时许多企业实行了大‘合并’，从而根据银行的工业政策第一次采用了分权组织的新形式。也许还可以把这个起点推到更晚一些的时候，因为只有1900年的危机才大大加速了工业和银行业的集中过程，巩固了这个过程，第一次把同工业的关系变成大银行的真正垄断，并大大地密切了和加强了这种关系。”","language":"中文","translation":false},{"id":"imperialism-1-137","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"总之，20世纪是从旧资本主义到新资本主义，从一般资本统治到金融资本统治的转折点。","language":"中文","translation":false},{"id":"imperialism-1-138","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"希法亭写道：“愈来愈多的工业资本不属于使用这种资本的工业家了。工业家只有通过银行才能取得对资本的支配权，对于工业家来说，银行代表这种资本的所有者。另一方面，银行也必须把自己愈来愈多的资本固定在工业上。因此，银行愈来愈变成工业资本家。通过这种方式实际上变成了工业资本的银行资本，即货币形式的资本，我把它叫作金融资本。”“金融资本就是由银行支配而由工业家运用的资本。”","language":"中文","translation":false},{"id":"imperialism-1-139","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这个定义不完全的地方，就在于它没有指出最重要的因素之一，即生产和资本的集中发展到了会导致而且已经导致垄断的高度。但是，在希法亭的整个叙述中，尤其是在我摘引这个定义的这一章的前两章里，着重指出了资本主义垄断组织的作用。","language":"中文","translation":false},{"id":"imperialism-1-140","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"生产的集中；从集中生长起来的垄断；银行和工业日益融合或者说长合在一起，——这就是金融资本产生的历史和这一概念的内容。","language":"中文","translation":false},{"id":"imperialism-1-141","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在我们应当来叙述一下，在商品生产和私有制的一般环境里，资本主义垄断组织的“经营”怎样必然变为金融寡头的统治。应当指出，德国（而且不只是德国）资产阶级学术界的代表人物，如里塞尔、舒尔采-格弗尼茨、利夫曼等人，完全是帝国主义和金融资本的辩护士。对于寡头形成的“内幕”，寡头所采用的手段，寡头所获得的“正当和不正当”收入的数量，寡头和议会的联系等等，他们不是去揭露，而是加以掩盖和粉饰。他们避开这些“棘手的问题”，只讲一些堂皇而含糊的词句，号召银行经理们拿出“责任心”，赞扬普鲁士官员们的“尽职精神”，煞有介事地分析那些根本无关紧要的“监督”法案、“管理”法案的细枝末节，玩弄无谓的理论游戏，例如利夫曼教授居然写出了这样一个“科学的”定义：“……商业是收集财富、保管财富、把财富供人支配的一种经营活动”（着重号和黑体是该教授著作中原有的)...... 这样说来，商业在不知交换为何物的原始人那里就已经有了，而且在社会主义社会也将存在下去！","language":"中文","translation":false},{"id":"imperialism-1-142","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"但是，有关金融寡头骇人听闻的统治的骇人听闻的事实是太触目惊心了，所以在一切资本主义国家，无论是美国、法国或德国，都出现了这样一些著作，这些著作虽然抱着资产阶级的观点，但毕竟还是对金融寡头作了近乎真实的描述和批评，当然是小市民式的批评。","language":"中文","translation":false},{"id":"imperialism-1-143","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"应当作为主要之点提出来的是前面已经简略谈到的“参与制”。德国经济学家海曼大概是第一个注意到了这一点，请看他是怎样描述问题的实质的：","language":"中文","translation":false},{"id":"imperialism-1-144","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“领导人控制着总公司〈直译是“母亲公司”〉，总公司统治着依赖于它的公司〈“女儿公司”〉，后者又统治着‘孙女公司’，如此等等。这样，拥有不太多的资本，就可以统治巨大的生产部门。事实上，拥有50%的资本，往往就能控制整个股份公司，所以，一个领导人只要拥有100万资本，就能控制各孙女公司的800万资本。如果这样‘交织’下去，那么拥有100万资本就能控制1600万、3200万以至更多的资本。”","language":"中文","translation":false},{"id":"imperialism-1-145","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"其实经验证明，只要占有40%的股票就能操纵一个股份公司的业务，因为总有一部分分散的小股东实际上根本没有可能参加股东大会等等。虽然资产阶级的诡辩家和机会主义的“也是社会民主党人”都期望（或者要别人相信他们期望）股票占有的“民主化”会造成“资本的民主化”，会加强小生产的作用和意义等等，可是实际上它不过是加强金融寡头实力的一种手段而已。因此，在比较先进的或比较老、比较“有经验的”资本主义国家里，法律准许发行票额较小的股票。德国法律不准许发行1000马克以下的股票，所以德国金融巨头看见英国法律准许发行一英镑（等于20马克，约合10卢布）的股票，就很羡慕。1900年6月7日，德国最大的工业家和“金融大王”之一西门子，在帝国国会中声称：“一英镑的股票是不列颠帝国主义的基础。”这个商人对于什么是帝国主义这一问题的理解，同那位被认为是俄国马克思主义创始人的不光彩的作家比起来，显然要深刻得多，“马克思主义”得多，那位作家竟把帝国主义看成是某个民族的劣根性……","language":"中文","translation":false},{"id":"imperialism-1-146","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"但是，“参与制”不仅使垄断者的权力大大增加，而且还使他们可以不受惩罚地、为所欲为地干一些见不得人的龌龊勾当，可以盘剥公众，因为母亲公司的领导人在形式上，在法律上对女儿公司是不担负责任的，女儿公司算是“独立的”，但是一切事情都可以通过女儿公司去“实施”。下面是我们从1914年德国《银行》杂志5月号抄下来的一个例子：","language":"中文","translation":false},{"id":"imperialism-1-147","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“卡塞尔的弹簧钢股份公司在几年以前算是德国最赚钱的企业之一。后来因为管理得很糟糕，股息从15%跌到0%。原来，董事会没有通知股东就出借了600万马克给自己的一个女儿公司哈西亚，而哈西亚的名义资本只有几十万马克。这笔几乎比母亲公司的股份资本大两倍的借款，根本没有记入母亲公司的资产负债表；在法律上，这样的隐瞒是完全合法的，而且可以隐瞒整整两年，因为这样做并不违反任何一条商业法。以负责人的资格在这种虚假的资产负债表上签字的监事长，至今仍旧是卡塞尔商会的会长。这笔借款被发现是个错误〈错误这两个字，作者应当加上引号〉，知道底细的人开始把‘弹簧钢’的股票脱手而使股票价格几乎下跌了100%，在这以后很久，股东们才知道有借款给哈西亚公司这回事……","language":"中文","translation":false},{"id":"imperialism-1-148","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这个在股份公司里极常见的、在资产负债表上玩弄平衡把戏的典型例子，向我们说明为什么股份公司董事会干起冒险勾当来，心里要比私人企业家轻松得多。编制资产负债表的最新技术，不但使董事会能够把所干的冒险勾当瞒过普通的股东，而且使主要的当事人在冒险失败的时候，能够用及时出卖股票的办法来推卸责任，而私人企业家却要用自己的性命来为自己所做的一切事情负责……","language":"中文","translation":false},{"id":"imperialism-1-149","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"许多股份公司的资产负债表，就跟中世纪一种有名的隐迹稿本一样，要先把上面写的字迹擦掉，才能发现下面的字迹，看出原稿的真实内容。”（隐迹稿本是涂掉原来的字迹、写上别的内容的一种羊皮稿本。)","language":"中文","translation":false},{"id":"imperialism-1-150","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“最简单、因而也是最常用的一种把资产负债表弄得令人捉摸不透的办法，是成立女儿公司或合并女儿公司，把一个统一的企业分成几部分。从各种合法的或非法的目的看来，这种办法的好处是十分明显的，所以现在不采用这种办法的大公司简直是一种例外。”","language":"中文","translation":false},{"id":"imperialism-1-151","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"作者举出了著名的电气总公司（即A.E.G，这个公司我们以后还要讲到），作为极广泛地采用这种办法的最大垄断公司的例子。据1912年的计算，这个公司参与了175-200个公司，自然也就统治了这些公司，总共掌握了大约15亿马克的资本。","language":"中文","translation":false},{"id":"imperialism-1-152","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"好心的——即怀有维护和粉饰资本主义的好心的——教授和官员们用来吸引公众注意的种种有关监督、公布资产负债表、规定一定的资产负债表格式、设立监察机构等等的条例，在这里根本不能起什么作用。因为私有财产是神圣的，谁也不能禁止股票的买卖、交换和典押等等。","language":"中文","translation":false},{"id":"imperialism-1-153","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“参与制”在俄国大银行里发展到怎样的程度，可以根据欧·阿加德提供的材料作出判断。阿加德曾在俄华银行任职15年，他在1914年5月出版了一本书，书名不十分贴切，叫作《大银行与世界市场》。作者把俄国大银行分为两大类：（ａ）“参与制”下的银行，（ｂ）“独立的”银行，然而他把“独立”任意地解释为不依附于国外银行。作者又把第一类分为三小类：(1)德国参与的，(2)英国参与的，(3)法国参与的，即指分别属于这三个国家的最大的国外银行的“参与”和统治。作者把银行资本分为“生产性”的投资（投入工商业的）和“投机性”的投资（投入交易所业务和金融业务的），他抱着他那种小资产阶级改良主义的观点，认为在保存资本主义的条件下，似乎可以把第一种投资和第二种投资分开，并且消除第二种投资。","language":"中文","translation":false},{"id":"imperialism-1-154","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"各银行的资产(根据1913年10─11月的表报) (单位百万卢布)","language":"中文","translation":false},{"id":"imperialism-1-155","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"俄国银行种类 所投的资本","language":"中文","translation":false},{"id":"imperialism-1-156","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"生产性的 投机性的 共 计","language":"中文","translation":false},{"id":"imperialism-1-157","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(ａ1)4家银行：西伯利亚商业银行、俄罗斯银行、国际银行、贴现银行 413.7 859.1 1272.8","language":"中文","translation":false},{"id":"imperialism-1-158","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(ａ2)2家银行：工商银行、俄英银行 239.3 169.1 408.4","language":"中文","translation":false},{"id":"imperialism-1-159","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(ａ3)5家银行：俄亚银行、圣彼得堡私人银行、亚速海-顿河银行、莫斯","language":"中文","translation":false},{"id":"imperialism-1-160","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"科联合银行、俄法商业银行 711.8 661.2 1373.0","language":"中文","translation":false},{"id":"imperialism-1-161","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(11家银行)总 □计 (ａ)＝1364.8 1689.4 3054.2","language":"中文","translation":false},{"id":"imperialism-1-162","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(ｂ)8家银行：莫斯□E商人银行、伏尔加-卡马银行、容克股份银行、圣","language":"中文","translation":false},{"id":"imperialism-1-163","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"彼得堡商业银行(前瓦韦尔贝尔格银行)、莫斯科银行(前里亚布申","language":"中文","translation":false},{"id":"imperialism-1-164","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"斯基银行)、莫斯科贴现银行、莫斯科商业银行、莫斯科私人银行 504.2 391.1 895.3","language":"中文","translation":false},{"id":"imperialism-1-165","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(19家银行)共 □计 1869.0 2080.5 3949.5","language":"中文","translation":false},{"id":"imperialism-1-166","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"从这些材料看来，在近40亿卢布的大银行“活动”资本当中，有3/4以上，即30多亿卢布属于实际上是作为国外银行的女儿公司的那些银行；它们主要是巴黎的银行（著名的三大银行：巴黎联合银行、巴黎荷兰银行、总公司）和柏林的银行（特别是德意志银行和贴现公司）。俄国两家最大的银行俄罗斯银行（俄国对外贸易银行）和国际银行（圣彼得堡国际商业银行），在1906-1912年间，把资本由4400万卢布增加到9800万卢布，把准备金由1500万卢布增加到3900万卢布，“其中有3/4是德国的资本”；前一家银行属于柏林德意志银行的康采恩，后一家银行属于柏林贴现公司的康采恩。善良的阿加德对于柏林的银行握有大部分股票而使俄国股东软弱无力，感到十分愤慨。自然，输出资本的国家总是捞到油水，例如柏林的德意志银行，在柏林发行西伯利亚商业银行的股票，把这些股票压存了一年，然后以193%的行情，即几乎高一倍的行情售出，“赚了”约600万卢布的利润，这就是希法亭所说的“创业利润”。","language":"中文","translation":false},{"id":"imperialism-1-167","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"据该书作者计算，彼得堡各最大银行的全部“实力”为823500万卢布，即将近82.5亿；同时作者又把各个国外银行的“参与”，确切些说，各个国外银行的统治，划分如下：法国银行占55%，英国银行占10%，德国银行占35%。据作者计算，在这823500万职能资本当中，有368700万，即40%以上用于各辛迪加，即煤业公司、五金公司、石油工业辛迪加、冶金工业辛迪加、水泥工业辛迪加。可见，由于资本主义垄断组织的形成而造成的银行资本和工业资本的融合，在俄国也有了长足的进展。","language":"中文","translation":false},{"id":"imperialism-1-168","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"集中在少数人手里并且享有实际垄断权的金融资本，由于创办企业、发行有价证券、办理公债等等而获得大量的、愈来愈多的利润，巩固了金融寡头的统治，替垄断者向整个社会征收贡赋。下面是希法亭从美国托拉斯“经营”的无数实例中举出的一个例子：1887年哈夫迈耶把15个小公司合并起来，成立了一个糖业托拉斯。这些小公司的资本总额为650万美元，而这个托拉斯的资本，按美国的说法，是“掺了水”的，竟估定为5000万美元。这种“过度资本化”是预计到了将来的垄断利润的，正象美国的钢铁托拉斯预计到将来的垄断利润，就购买愈来愈多的蕴藏铁矿的土地一样。果然，这个糖业托拉斯规定了垄断价格，获得了巨额的收入，竟能为“掺水”7倍的资本支付10%的股息，也就是为创办托拉斯时实际投入的资本支付将近70%的股息！到1909年，这个托拉斯的资本为9000万美元。在22年内，资本增加了十倍以上。","language":"中文","translation":false},{"id":"imperialism-1-169","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"法国的“金融寡头”的统治（《反对法国金融寡头》——利西斯一本名著的标题，1908年出了第5版），只是在形式上稍有不同。4家最大的银行在发行有价证券方面享有不是相对的垄断权，而是“绝对的垄断权”。事实上这是“大银行托拉斯”。垄断保证它们从发行证券获得垄断利润。在借债时，债务国所得到的通常不超过总额的90%；10%被银行和其它中介人拿去了。银行从4亿法郎的中俄债券中得到8%的利润，从8亿法郎的俄国债券(1904年）中得到10%的利润，从6250万法郎的摩洛哥债券(1904年）中得到18.75%的利润。资本主义的发展是从小规模的高利贷资本开始，而以大规模的高利贷资本结束。利西斯说：“法国人是欧洲的高利贷者。”全部经济生活条件都由于资本主义的这种蜕化而发生深刻的变化。在人口、工商业和海运都发生停滞的情况下，“国家”却可以靠放高利贷发财。“代表800万法郎资本的50个人，能够支配4家银行的20亿法郎。”我们谈过的“参与”制度，也造成同样的结果：最大银行之一的总公司为女儿公司埃及精糖厂发行了64000张债券。发行的行情是150%，就是说，银行在每一个卢布上赚了50个戈比。后来发现这个女儿公司的股息是虚拟的，这样就使“公众”损失了9000万至1亿法郎；“总公司有一个经理是精糖厂的董事”。难怪这位作者不得不作出结论说：“法兰西共和国是金融君主国”；“金融寡头统治一切，既控制着报刊，又控制着政府”。","language":"中文","translation":false},{"id":"imperialism-1-170","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"作为金融资本主要业务之一的有价证券发行业，赢利极大，对于金融寡头的发展和巩固起着重大的作用。德国的《银行》杂志写道：“在发行外国债券的时候担任中介人，能够获得很高的利润，国内没有任何一种生意能够获得哪怕是同它相近的利润。”","language":"中文","translation":false},{"id":"imperialism-1-171","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“没有任何一种银行业务能够获得象发行业务那么高的利润。”根据《德国经济学家》杂志的材料，发行工业企业证券的利润每年平均如下：","language":"中文","translation":false},{"id":"imperialism-1-172","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1895年----38.6% 1898年----67.7%","language":"中文","translation":false},{"id":"imperialism-1-173","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1896年----36.1% 1899年----66.9%","language":"中文","translation":false},{"id":"imperialism-1-174","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1897年----66.7% 1900年----55.2%","language":"中文","translation":false},{"id":"imperialism-1-175","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“在1891-1900年的10年间，仅靠发行德国工业证券‘赚到’的钱就有10亿以上。”","language":"中文","translation":false},{"id":"imperialism-1-176","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在工业高涨时期，金融资本获得巨额利润，而在衰落时期，小企业和不稳固的企业纷纷倒闭，大银行就“参与”贱价收买这些企业，或者“参与”有利可图的“整理”和“改组”。在“整理”亏本的企业时，“把股份资本降低，也就是按照比较小的资本额来分配收入，以后就按照这个资本额来计算收入。如果收入降低到零，就吸收新的资本，这种新资本同收入比较少的旧资本结合来，就能获得相当多的收入。”希法亭又补充道：“而且，所有这些整理和改组，对于银行有双重的意义：第一，这是有利可图的业务；第二，这是使经济拮据的公司依附于自己的好机会。”","language":"中文","translation":false},{"id":"imperialism-1-177","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":177,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"请看下面的例子。多特蒙德的联合矿业股份公司，是在1872年创办的。发行的股份资本将近4000万马克，而在第一个年度获得12%的股息时，股行情就涨到170%。金融资本捞到了油水，稍稍地赚了那么2800万马克。在创办这个公司的时候，起主要作用的就是那个把资本很顺利地增加到3亿马克的德国最大的银行贴现公司。后来联合公司的股息降到了零。股东们只好同意“冲销”资本，也就是损失一部分资本，以免全部资本损失。经过多次“整理”，在30年中，联合公司的帐簿上消失了7300多万马克。“现在，这个公司原先的股东们手里的股票价值，只有票面价值的5%了”，而银行在每一次“整理”中却总是“赚钱”。","language":"中文","translation":false},{"id":"imperialism-1-178","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":178,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"拿发展得很快的大城市近郊的土地来做投机生意，也是金融资本的一种特别盈利的业务。在这方面，银行的垄断同地租的垄断、也同交通运输业的垄断结合起来了，因为地价的上涨，以及土地能不能有利地分块出售等等，首先取决于同市中心的交通是否方便，而掌握交通运输业的，是通过参与制和分配经理职务同这些银行联系起来的大公司。结果就形成了《银行》杂志的撰稿人、专门研究土地买卖和抵押等业务的德国作家路·埃施韦格称作“泥潭”的局面：买卖城郊土地的狂热投机，建筑公司的倒闭（如柏林的波斯瓦-克诺尔公司的倒闭，这个公司靠了“最大最可靠的”德意志银行的帮助，弄到了1亿马克的巨款，而这家银行当然是通过“参与”制暗地里在背后进行了活动，结果银行“总共”损失了1200万马克就脱身了），以及从空头的建筑公司那里一无所得的小业主和工人们的破产，同“廉洁的”柏林警察局和行政当局勾结起来把持颁发土地证和市议会建筑许可证的勾当，等等。","language":"中文","translation":false},{"id":"imperialism-1-179","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":179,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"欧洲的教授和善良的资产者一向装腔作势地对之表示痛心疾首的“美国风气”，在金融资本时代简直成了各国各大城市流行的风气。","language":"中文","translation":false},{"id":"imperialism-1-180","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":180,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1914年初，在柏林传说要组织一个“运输业托拉斯”，即由柏林的城市电气铁路公司、有轨电车公司和公共汽车公司这三个运输企业组成一个“利益共同体”。《银行》杂志写道：“当公共汽车公司的大部分股票转到其它两个运输公司手里的消息传出时，我们就知道有这种打算了。……完全可以相信，抱着这种目的的人希望通过统一调整运输业来节省一些费用，最终能使公众从中得到些好处。但是这个问题复杂化了，因为站在这个正在创建的运输业托拉斯背后的是这样一些银行，它们可以任意使自己所垄断的交通运输业服从自己的土地买卖的利益。只要回想一下下面这件事情，就会相信这种推测是十分自然的：在创办城市电气铁路公司的时候，鼓励创办该公司的那家大银行的利益就已经渗透进来了。就是说，这个运输企业的利益和土地买卖的利益交织在一起了。因为这条铁路的东线要经过银行的土地，当该路的建设已经有保证时，银行就把这些土地卖出去，使自己和几个合伙人获得了巨额的利润……”","language":"中文","translation":false},{"id":"imperialism-1-181","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":181,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"垄断既然已经形成，而且操纵着几十亿资本，它就绝对不可避免地要渗透到社会生活的各个方面去，而不管政治制度或其它任何“细节”如何。在德国经济著作中，通常是阿谀地赞美普鲁士官员的廉洁，而影射法国的巴拿马案件或美国政界的贿赂风气。但是事实是，甚至专论德国银行业务的资产阶级书刊，也不得不经常谈到远远越出纯银行业务范围的事情，例如，针对官员们愈来愈多地转到银行去服务这件事，谈到了“钻进银行的欲望”：“暗地里想在贝伦街〈柏林街名，德意志银行的所在地〉钻营一个肥缺的官员，他们的廉洁情况究竟怎样呢？”《银行》杂志出版版人阿尔弗勒德·兰斯堡在1909年写了《曲意逢迎的经济影响》一文，其中谈到威廉二世的巴勒斯坦之行，以及“此行的直接结果，即巴格达铁路的建筑，这一不幸的‘德意志进取精神的大事件’，对于德国受‘包围’一事应负的责任，比我们所犯的一切政治错误应负的责任还要大”（所谓“包围”是指爱德华七世力图孤立德国、用帝国主义的反德同盟圈来包围德国的政策）。我们已经提过的这个杂志的撰稿人埃施韦格，在1911年写了一篇《财阀和官吏》的文章，揭露了一位德国官员弗尔克尔的事情。弗尔克尔当过卡特尔问题委员会的委员，并且很卖力气，不久以后他却在最大的卡特尔——钢铁辛迪加中得到了一个肥缺。这类决非偶然的事情，迫使这位资产阶级作家不得不承认说，“德国宪法所保证的经济自由，在经济生活的许多方面，已经成了失去内容的空话”，在现有的财阀统治下，“即使有最广泛的政治自由，也不能使我们免于变成非自由民的民族”。","language":"中文","translation":false},{"id":"imperialism-1-182","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":182,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"说到俄国，我们只举一个例子：几年以前，所有的报纸都登载过一个消息，说信用局局长达维多夫辞去了政府的职务，到一家大银行任职去了，按照合同，他在几年里所得的薪俸将超过100万卢布。信用局是个“统一全国所有信用机关业务”的机关，它给了首都各银行总数达8-10亿卢布的津贴。------","language":"中文","translation":false},{"id":"imperialism-1-183","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":183,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本主义的一般特性，就是资本的占有同资本在生产中的运用相分离，货币资本同工业资本或者说生产资本相分离，全靠货币资本的收入为生的食利者同企业家及一切直接参与运用资本的人相分离。帝国主义，或者说金融资本的统治，是资本主义的最高阶段，这时候，这种分离达到了极大的程度。金融资本对其它一切形式的资本的优势，意味着食利者和金融寡头占统治地位，意味着少数拥有金融“实力”的国家处于和其余一切国家不同的特殊地位。至于这一过程进行到了怎样的程度，可以根据发行各种有价证券的统计材料来判断。","language":"中文","translation":false},{"id":"imperialism-1-184","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":184,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"阿·奈马尔克在《国际统计研究所公报》上发表了关于全世界发行证券的最详尽最完备的对照材料，后来这些材料曾屡次被经济学著作分别引用过。现将4个10年中的总计分列如下：","language":"中文","translation":false},{"id":"imperialism-1-185","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":185,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"10年证券发行额(单位十亿法朗)","language":"中文","translation":false},{"id":"imperialism-1-186","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":186,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1871-1880年 76.1","language":"中文","translation":false},{"id":"imperialism-1-187","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":187,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1881-1890年 64.5","language":"中文","translation":false},{"id":"imperialism-1-188","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":188,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1891-1900年 100.4","language":"中文","translation":false},{"id":"imperialism-1-189","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":189,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1901-1910年 197.8","language":"中文","translation":false},{"id":"imperialism-1-190","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":190,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在19世纪70年代，全世界证券发行总额增加了，特别是由于普法战争以及德国战后滥设投机公司时期发行债券而增加了。大体说来，在19世纪最后3个10年里，增加的速度比较起来还不算太快，直到20世纪的头10年才大为增加，10年之内差不多增加了一倍。可见，20世纪初，不仅在我们已经说过的垄断组织（卡特尔、辛迪加、托拉斯）的发展方面，而且在金融资本的增长方面，都是一个转折时期。","language":"中文","translation":false},{"id":"imperialism-1-191","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":191,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"据奈马尔克计算，1910年全世界有价证券的总额大约是8150亿法郎。他大致地减去了重复的数字，使这个数额缩小到5750亿至6000亿法郎。下面是这个数额在各国分布的情形（这里取的总额是6000亿）：","language":"中文","translation":false},{"id":"imperialism-1-192","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":192,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1910年有价证券数额(单位十亿法郎)","language":"中文","translation":false},{"id":"imperialism-1-193","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":193,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"瑞典、挪威、罗马尼亚等国2.5","language":"中文","translation":false},{"id":"imperialism-1-194","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":194,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"从这些数字一下子就可以看出，4个最富的资本主义国家是多么突出，它们各有约1000亿至1500亿法郎的有价证券。在这4个国家中有两个是最老的、殖民地最多的（这一点我们以下就要说到）资本主义国家——英国和法国，其余两个是在发展速度上和资本主义垄断组织在生产中的普及程度上领先的资本主义国家——美国和德国。这4个国家一共有4790亿法郎，约占全世界金融资本的80%。世界上其它各国，差不多都是这样或那样地成为这4个国家、这4个国际银行家、这4个世界金融资本的“台柱”的债务人和进贡者了。","language":"中文","translation":false},{"id":"imperialism-1-195","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":195,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在，我们应当特别谈一下，资本输出在形成金融资本的依附和联系的国际网方面所起的作用。","language":"中文","translation":false},{"id":"imperialism-1-196","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":196,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"对自由竞争占完全统治地位的旧资本主义来说，典型的是商品输出。对垄断占统治地位的最新资本主义来说，典型的则是资本输出。","language":"中文","translation":false},{"id":"imperialism-1-197","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":197,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本主义是发展到最高阶段的商品生产，这时劳动力也成了商品。国内交换尤其是国际交换的发展，是资本主义的具有代表性的特征。在资本主义制度下，各个企业、各个工业部门和各个国家的发展必然是不平衡的，跳跃式的。起先，英国早于别国成为资本主义国家，到19世纪中叶，英国实行自由贸易，力图成为“世界工厂”，由它供给各国成品，这些国家则供给它原料作为交换。但是英国的这种垄断，在19世纪最后的25年已经被打破了，因为当时有许多国家用“保护”关税来自卫，发展成为独立的资本主义国家。临近20世纪时，我们看到已经形成了另一种垄断：第一，所有发达的资本主义国家都有了资本家的垄断同盟；第二，少数积累了巨额资本的最富的国家处于垄断地位。在先进的国家里出现了大量的“过剩资本”。","language":"中文","translation":false},{"id":"imperialism-1-198","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":198,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"假如资本主义能发展现在到处都远远落后于工业的农业，假如资本主义能提高在技术获得惊人进步的情况下仍然到处是半饥半饱、乞丐一般的人民大众的生活水平，那当然就不会有什么过剩资本了。用小资产阶级观点批评资本主义的人就常常提出这种“论据”。但是这样一来，资本主义就不成其为资本主义了，因为发展的不平衡和民众半饥半饱的生活水平，是这种生产方式的根本的、必然的条件和前提。只要资本主义还是资本主义，过剩的资本就不会用来提高本国民众的生活水平（因为这样会降低资本家的利润），而会输出国外，输出到落后的国家去，以提高利润。在这些落后国家里，利润通常都是很高的，因为那里资本少，地价比较贱，工资低，原料也便宜。其所以有输出资本的可能，是因为许多落后的国家已经卷入世界资本主义的流转，主要的铁路线已经建成或已经开始兴建，发展工业的起码条件已有保证等等。其所以有输出资本的必要，是因为在少数国家中资本主义“已经过度成熟”，“有利可图的”投资场所已经不够了（在农业不发达和群众贫困的条件下）。","language":"中文","translation":false},{"id":"imperialism-1-199","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":199,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"下面是三个主要国家国外投资的大概数目：","language":"中文","translation":false},{"id":"imperialism-1-200","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":200,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"国外投资(单位十亿法郎)","language":"中文","translation":false},{"id":"imperialism-1-201","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":201,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1862 3.6 - -","language":"中文","translation":false},{"id":"imperialism-1-202","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":202,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1872 15 10(1869年) -","language":"中文","translation":false},{"id":"imperialism-1-203","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":203,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1882 22 15(1880年) ？","language":"中文","translation":false},{"id":"imperialism-1-204","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":204,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1893 42 20(1890年) ？","language":"中文","translation":false},{"id":"imperialism-1-205","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":205,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1902 62 27-37 12.5","language":"中文","translation":false},{"id":"imperialism-1-206","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":206,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1914 75-100 60 44","language":"中文","translation":false},{"id":"imperialism-1-207","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":207,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"由此可见，资本输出是在20世纪初期才大大发展起来的。在大战前夜，3个主要国家的国外投资已经达到1750-2000亿法郎。按5%的低利率计算，这笔款额的收入一年可达80-100亿法郎。这就是帝国主义压迫和剥削世界上大多数民族和国家的坚实基础，这就是极少数最富国家的资本主义寄生性的坚实基础！","language":"中文","translation":false},{"id":"imperialism-1-208","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":208,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这种国外投资在各国之间怎样分配，投在什么地方，对于这个问题只能作一个大概的回答，不过这个大概的回答也能说明现代帝国主义的某些一般的相互关系和联系：","language":"中文","translation":false},{"id":"imperialism-1-209","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":209,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"国外投资在世界各洲分布的大概情况(1910年前后)(单位十亿马克)","language":"中文","translation":false},{"id":"imperialism-1-210","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":210,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"欧洲 4 23 18 45","language":"中文","translation":false},{"id":"imperialism-1-211","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":211,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美洲 37 4 10 51","language":"中文","translation":false},{"id":"imperialism-1-212","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":212,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"亚洲、非洲、澳洲 29 8 7 44","language":"中文","translation":false},{"id":"imperialism-1-213","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":213,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"总计 70 35 35 140","language":"中文","translation":false},{"id":"imperialism-1-214","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":214,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在英国，占第一位的是它的殖民地，它在美洲也有广大的殖民地(例如加拿大），在亚洲等地就更不必说了。英国资本的大量输出，同大量的殖民地有最密切的联系。关于殖民地对帝国主义的意义，我们以后还要讲到。法国的情况不同。它的国外投资主要是在欧洲，首先是在俄国（不下100亿法郎），并且多半是借贷资本即公债，而不是对工业企业的投资。法国帝国主义与英国殖民帝国主义不同，可以叫作高利贷帝国主义。德国又是另一种情况，它的殖民地不多，它的国外投资在欧美两洲之间分布得最平均。","language":"中文","translation":false},{"id":"imperialism-1-215","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":215,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本输出在那些输入资本的国家中对资本主义的发展发生影响，大大加速这种发展。因此，如果说资本输出会在某种程度上引起输出国发展上的一些停滞，那也一定会有扩大和加深资本主义在全世界的进一步发展作为补偿的。","language":"中文","translation":false},{"id":"imperialism-1-216","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":216,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"输出资本的国家几乎总有可能获得一定的“利益”，这种利益的性质也就说明了金融资本和垄断组织的时代的特性。例如柏林的《银行》杂志在1913年10月写道：","language":"中文","translation":false},{"id":"imperialism-1-217","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":217,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“在国际的资本市场上，近来正在上演一出可以和阿里斯托芬的作品相媲美的喜剧。国外的很多国家，从西班牙到巴尔干，从俄国到阿根廷、巴西和中国，都在公开或秘密地向巨大的货币市场要求贷款，有时还要求得十分急迫。现在货币市场上的情况并不怎么美妙，政治前景也未可乐观。但是没有一个货币市场敢于拒绝贷款，唯恐邻居抢先同意贷款而换得某种报酬。在缔结这种国际契约时，债权人几乎总要占点便宜：获得贸易条约上的让步，开设煤站，建设港口，得到利益丰厚的租让，接受大炮定货。”","language":"中文","translation":false},{"id":"imperialism-1-218","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":218,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"金融资本造成了垄断组织的时代。而垄断组织则到处实行垄断的原则：利用 “联系”来订立有利的契约，以代替开放的市场上的竞争。最常见的是，规定拿一部分贷款来购买债权国的产品，尤其是军用品、轮船等等，作为贷款的条件。法国在最近20年中(1890-1910年）常常采用这种手段。资本输出成了鼓励商品输出的手段。在这种情况下，特别大的企业之间订立的契约，按照施尔德尔“婉转的”说法，往往“接近于收买”。德国的克虏伯、法国的施奈德、英国的阿姆斯特朗，就是同大银行和政府关系密切、在缔结债约时不容易“撇开”的公司的典型。","language":"中文","translation":false},{"id":"imperialism-1-219","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":219,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"法国贷款给俄国的时候，在1905年9月16日缔结的贸易条约上“压了”一下俄国，使俄国直到1917年为止作出相当的让步；在1911年8月19日同日本缔结贸易条约时，也是如此。奥地利同塞尔维亚的关税战争从1906年开始，一直继续到1911年，中间只有7个月的休战，这次关税战争部分是由奥地利和法国在供应塞尔维亚军用物资方面的竞争引起的。1912年1月，保尔 ·德沙内尔在议会里说，法国公司在1908-1911年间供给塞尔维亚的军用物资，价值达4500万法郎。","language":"中文","translation":false},{"id":"imperialism-1-220","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":220,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"奥匈帝国驻圣保罗（巴西）领事在报告中说：“巴西修筑铁路，大部分用的是法、比、英、德的资本；这些国家在办理有关修筑铁路的金融业务时已规定由它们供应铁路建筑材料。”","language":"中文","translation":false},{"id":"imperialism-1-221","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":221,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这样，金融资本的密网可以说确实是布满了全世界。在这方面起了很大作用的，是设在殖民地的银行及其分行。德国帝国主义者看到“老的”殖民国家在这方面特别“成功”，真是羡慕之至。在1904年，英国有50家殖民地银行和2279个分行(1910年有72家银行和5449个分行），法国有20家殖民地银行和136个分行，荷兰有16家殖民地银行和68个分行，而德国“总共只有”13家殖民地银行和70个分行。美国资本家则羡慕英德两国的资本家，他们在1915年诉苦说：“在南美，5家德国银行有40个分行，5家英国银行有70个分行…… 最近25年来，英德两国在阿根廷、巴西和乌拉圭投资约40亿美元，从而支配了这3个国家全部贸易的46%。”","language":"中文","translation":false},{"id":"imperialism-1-222","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":222,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"输出资本的国家已经把世界瓜分了，那是就瓜分一词的转义而言的。但是，金融资本还导致对世界的直接的瓜分。","language":"中文","translation":false},{"id":"imperialism-1-223","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":223,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本家的垄断同盟卡特尔、辛迪加、托拉斯，首先瓜分国内市场，把本国的生产差不多完全掌握在自己手里。但是在资本主义制度下，国内市场必然是同国外市场相联系的。资本主义早已造成了世界市场。所以随着资本输出的增加，随着最大垄断同盟的国外联系、殖民地联系和“势力范围”的极力扩大，这些垄断同盟就“自然地”走向达成世界性的协议，形成国际卡特尔。","language":"中文","translation":false},{"id":"imperialism-1-224","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":224,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这是全世界资本和生产集中的一个新的、比过去高得多的阶段。我们来看看这种超级垄断是怎样生长起来的。","language":"中文","translation":false},{"id":"imperialism-1-225","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":225,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"电力工业是最能代表最新技术成就，代表19世纪末、20世纪初的资本主义的一个工业部门。它在美国和德国这两个最先进的新兴资本主义国家里最发达。在德国，1900年的危机对这个部门集中程度的提高发生了特别巨大的影响。在此之前已经同工业相当紧密地长合在一起的银行，在这个危机时期极大地加速和加深了较小企业的毁灭和它们被大企业吞并的过程。耶德尔斯写道：“银行停止援助的正是那些最需要援助的企业，这样就使那些同银行联系不够密切的公司，起初虽有蓬勃的发展，后来却遭到了无法挽救的破产。”","language":"中文","translation":false},{"id":"imperialism-1-226","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":226,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"结果，在1900年以后，集中有了长足的进展。1900年以前，电力工业中有七八个“集团”，每个集团都由几个公司组成（总共有8个公司），这些集团背后各有2至11家银行。到1908-1912年时，所有这些集团已合并成两个甚至一个集团了。这个过程如下：","language":"中文","translation":false},{"id":"imperialism-1-227","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":227,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在1900年以前 费尔登与吉约姆 拉迈尔 联合电气总公司 西门子与哈尔斯克 舒克尔特公司 贝尔格曼 库梅尔","language":"中文","translation":false},{"id":"imperialism-1-228","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":228,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"费尔登与拉迈尔 电气总公司(A.E.G.) 西门子与哈尔斯克舒克尔特 贝尔格曼 1900年破产","language":"中文","translation":false},{"id":"imperialism-1-229","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":229,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"到1912年时： 电气总公司(A.E.G.) 西门子与哈尔斯克-舒克尔特","language":"中文","translation":false},{"id":"imperialism-1-230","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":230,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(从1908年开始密切“合作 ”)","language":"中文","translation":false},{"id":"imperialism-1-231","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":231,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这样生长起来的著名的电气总公司(A.E.G.)统治着175-200个公司（通过“参与”制度），总共支配着约15亿马克的资本。单是它在国外的直接代表机构就有34个，其中有12个是股份公司，分设在10多个国家中。早在1904年，德国电力工业在国外的投资就有23300万马克，其中有6200万投在俄国。不言而喻，这个电气总公司是一个大型的“联合”企业，单是它的制造公司就有16个，制造各种各样的产品，从电缆和绝缘体，直到汽车和飞行器为止。","language":"中文","translation":false},{"id":"imperialism-1-232","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":232,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"但是，欧洲的集中也就是美国集中过程的一个组成部分。当时的情况如下：","language":"中文","translation":false},{"id":"imperialism-1-233","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":233,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"汤普逊-霍斯乐公司在欧洲创设了一个公司 爱迪生公司在欧洲创设了法国爱迪生公司，后者又把发明专利权转让给德国公司","language":"中文","translation":false},{"id":"imperialism-1-234","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":234,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国 联合电气公司 电气总公司","language":"中文","translation":false},{"id":"imperialism-1-235","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":235,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"于是形成了两个电力“大国”。海尼希在他的《电力托拉斯之路》一文中写道：“世界上没有一个完全不依赖它们的电力公司。”关于这两个“托拉斯”的周转额和企业规模，下列数字可以使我们得到某种（远非完整的）概念：","language":"中文","translation":false},{"id":"imperialism-1-236","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":236,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"商品周转额(单位百万马克) 职员人数 纯 利(单位百万马克)","language":"中文","translation":false},{"id":"imperialism-1-237","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":237,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国的通用电气公司 1907年：252 28000 35.4","language":"中文","translation":false},{"id":"imperialism-1-238","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":238,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1910年：298 32000 45.6","language":"中文","translation":false},{"id":"imperialism-1-239","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":239,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国的电气总公司 1907年：216 30700 14.5","language":"中文","translation":false},{"id":"imperialism-1-240","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":240,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1911年：362 60800 21.7","language":"中文","translation":false},{"id":"imperialism-1-241","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":241,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1907年，美德两国的托拉斯订立了瓜分世界的协议。竞争消除了。通用电气公司“获得了”美国和加拿大，电气总公司“分得了”德国、奥地利、俄国、荷兰、丹麦、瑞士、土耳其和巴尔干。还就女儿公司渗入新的工业部门和“新的”即尚未正式被瓜分的国家问题，订立了单独的（当然是秘密的）协议。此外还规要互相交换发明和试验结果。","language":"中文","translation":false},{"id":"imperialism-1-242","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":242,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这种实际上是统一的世界性托拉斯，支配着几十亿资本，在世界各地有“分支机构”、代表机构、代办处以及种种联系等等，要同这种托拉斯竞争，自然是十分困难的。但是，这两个强大的托拉斯瓜分世界的事实，当然并不排除对世界的重新瓜分，如果实力对比由于发展不平衡、战争、崩溃等等而发生变化的话。","language":"中文","translation":false},{"id":"imperialism-1-243","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":243,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"煤油工业提供了企图实行这种重新瓜分，为重新瓜分而斗争的一个大有教益的例子。","language":"中文","translation":false},{"id":"imperialism-1-244","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":244,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"耶德尔斯在1905年写道：“世界的煤油市场直到现在还被两大金融集团分占着：一个是洛克菲勒的美国煤油托拉斯（美孚油公司），一个是俄国巴库油田的老板路特希尔德和诺贝尔。这两个集团彼此有密切的联系，但是几年以来，它们的垄断地位一直受到五大敌人的威胁”：(1)美国石油资源的枯竭；(2)巴库的曼塔舍夫公司的竞争；(3)奥地利的石油资源；(4)罗马尼亚的石油资源；(5)海外的石油资源，特别是荷兰殖民地的石油资源（极富足的塞缪尔公司和壳牌公司，它们同英国资本也有联系）。后面三个地区的企业是同最大的德意志银行为首的那些德国大银行有联系的。这些银行为了拥有“自己的”据点而有计划地独自发展煤油工业，例如在罗马尼亚。在罗马尼亚的煤油工业中，1907年有外国资本18500万法郎，其中德国资本占7400万。","language":"中文","translation":false},{"id":"imperialism-1-245","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":245,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"斗争开始了，这个斗争在经济著作中就叫作“瓜分世界”的斗争。一方面，洛克菲勒的煤油托拉斯想夺取一切，就在荷兰本土办了一个女儿公司，收买荷属印度的石油资源，想以此来打击自己的主要敌人——英荷壳牌托拉斯。另一方面，德意志银行和其它柏林银行力求把罗马尼亚“保持”在“自己手里”，使罗马尼亚同俄国联合起来反对洛克菲勒。洛克菲勒拥有大得多的资本，又拥有运输煤油和供应煤油给消费者的出色的组织。斗争的结果势必是德意志银行完全失败，它果然在1907年完全失败了，这时德意志银行只有两条出路：或者是放弃自己的“煤油利益”，损失数百万；或者是屈服。结果德意志银行选择了后者，同煤油托拉斯订立了一项对自己很不利的合同。按照这项合同，德意志银行保证“不做任何损害美国利益的事情”，但同时又规定，如果德国通过国家煤油垄断法，这项合同即告失效。","language":"中文","translation":false},{"id":"imperialism-1-246","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":246,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"于是一出“煤油喜剧”开演了。德国金融大王之一、德意志银行的经理冯 ·格温纳，通过自己的私人秘书施陶斯发动了一场主张煤油垄断的宣传。这家最大的柏林银行的整个庞大机构、一切广泛的“联系”都开动起来了，报刊上一片声嘶力竭的反对美国托拉斯“压迫”的“爱国主义”叫喊声。1911年3月15日，帝国国会几乎是一致地通过了请政府制定煤油垄断法案的决议。政府欣然接受了这个“受众人欢迎的”主张。于是，德意志银行旨在欺骗它的美国对手并用国家垄断来振兴自己业务的这场赌博，好象是已经赢了。德国煤油大王已经做着一种获得不亚于俄国糖厂主的大量利润的美梦…… 但是，第一，德国各大银行在分赃上彼此发生了争吵，贴现公司揭露了德意志银行的自私自利；第二，政府害怕同洛克菲勒斗争，因为德国是否能不通过洛克菲勒而获得煤油，还很成问题（罗马尼亚的生产率不高）；第三，1913年，正赶上德国要拨款10亿来准备战争。垄断法案搁下来了。斗争的结果是，洛克菲勒的煤油托拉斯暂时获得了胜利。","language":"中文","translation":false},{"id":"imperialism-1-247","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":247,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"柏林的《银行》杂志关于这点写道，德国只有实行电力垄断，用水力发出廉价的电力，才能同煤油托拉斯斗争。这个杂志又说：但是，“电力垄断只有在生产者需要的时候才会实现，也就是说，只有在下一次电力工业大崩溃逼近、各私营电力工业康采恩现在在各处修建的已经从市政府和国家等等方面获得了某些垄断权的那些成本高的大电站不能获利的时候，才会实现。到那时候就只好使用水力；但是用水力发出廉价的电力也不能靠国家出钱来办，还是要交给‘受国家监督的私人垄断组织’去经营，因为私营工业已经订立了许多契约……争得了巨额的补偿…… 以前钾碱的垄断是如此，现在煤油的垄断是如此，将来电力的垄断也是如此。我们那些被美妙的原则迷住了的国家社会主义者，现在总该明白：德国的垄断组织从来没有抱定过这样的目的，也没有达到过这样的结果，即为消费者带来好处或者哪怕是交给国家一部分企业利润，它们仅仅是为了用国家的钱来振兴快要破产的私营工业罢了。”","language":"中文","translation":false},{"id":"imperialism-1-248","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":248,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国资产阶级经济学家不得不作出这种宝贵的供认。这里我们清楚地看到，在金融资本时代，私人垄断组织和国家垄断组织是交织在一起的，实际上这两种垄断组织都不过是最大的垄断者之间为瓜分世界而进行的帝国主义斗争中的一些环节而已。","language":"中文","translation":false},{"id":"imperialism-1-249","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":249,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在商轮航运业中，集中的巨大发展也引起了对世界的瓜分。德国形成了两个最大的公司，即汉堡-美洲包裹投递股份公司和北德劳埃德公司，它们各有资本2亿马克（股票和债券），各有价值18500-18900万马克的轮船。另一方面，美国在1903年1月1日成立了所谓摩根托拉斯，即国际商轮公司，由美英两国的9个轮船公司合并而成，拥有资本12000万美元(48000万马克）。就在1903年，两家德国大公司和这个美英托拉斯签订了一项为瓜分利润而瓜分世界的合同。德国的公司在英美之间的航线上退出了竞争。合同明确地规定了哪些港口“归”谁“使用”，并且设立了一个共同的监察委员会等等。合同期定为20年，同时规定了一个附带条款：一旦发生战争，该合同即告废止。","language":"中文","translation":false},{"id":"imperialism-1-250","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":250,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"国际钢轨卡特尔形成的历史，也是大有教益的。早在1884年工业极为衰落的时候，英国、比利时、德国三国的钢轨制造厂就作过组织这种卡特尔的第一次尝试。它们议定不在缔约各国的国内市场上竞争，国外市场则按下列比例瓜分：英国占66%，德国占27%，比利时占7%。印度完全归英国。对于一个没有参加缔结协议的英国公司，它们就合力进攻，其耗费由出售总额中拿出一部分来补偿。但是到了1886年，有两个英国公司退出了同盟，这个同盟也就瓦解了。值得注意的是，在后来几次工业高涨时期，始终没有达成过协议。","language":"中文","translation":false},{"id":"imperialism-1-251","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":251,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1904年初，德国成立了钢铁辛迪加。1904年11月，国际钢轨卡特尔又按下列比例恢复起来了：英国占53.5%；德国占28.83%；比利时占17.67%。后来法国也加入了，它在第一、第二、第二年中所占份额分别为4.8%、5.8%、6.4%，这是在100%以外，即以104.8%等等为基数的。1905年，又有美国的钢铁托拉斯（钢铁公司）加入，其后奥地利和西班牙也加入了。福格尔施泰因在1910年写道：“现在，地面已经分完了，于是那些大用户，首先是国营铁路——既然世界已经被瓜分完毕而没有照顾它们的利益——，就可以象诗人一样生活在丘必特的天宫里了。”","language":"中文","translation":false},{"id":"imperialism-1-252","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":252,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"还要提一提1909年成立的国际锌业辛迪加，它把生产量在德、比、法、西、英五国的工厂集团之间作了明确的分配；还有国际火药托拉斯，用利夫曼的话来说，它是“德国所有炸药厂的最新式的紧密同盟，后来这些炸药厂与法美两国用同样的方法组织起来的代那买特炸药工厂一起，可以说是共同瓜分了整个世界”。据利夫曼统计，德国所参加的国际卡特尔，在1897年共有将近40个，到1910年就已经接近100个了。","language":"中文","translation":false},{"id":"imperialism-1-253","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":253,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"有些资产阶级作家（现在卡·考茨基也加入了他们的行列，他完全背叛了象他在1909年所采取的那种马克思主义的立场）认为，国际卡特尔作为资本国际化的最突出的表现之一，给人们带来了在资本主义制度下各民族间实现和平的希望。这种意见在理论上是十分荒谬的，在实践上则是一种诡辩，是用欺骗的手段为最恶劣的机会主义辩护。国际卡特尔表明了现在资本主义垄断组织已经发展到怎样的程度，资本家同盟是为了什么而互相斗争。后面这一点是最重要的，只有它才能向我们说明当前发生的事情的历史经济意义，因为斗争的形式由于各种比较局部的和暂时的原因，可能发生变化，而且经常在发生变化，但是，只要阶级存在，斗争的实质，斗争的阶级内容，是始终不会改变的。很明显，掩饰现代经济斗争的内容（瓜分世界），而强调这个斗争的这种或那种形式，这是符合比如说德国资产阶级的利益的（考茨基在理论见解方面实质上已经转到德国资产阶级那边去了，这点我们以后还要说到）。考茨基也犯了同样的错误。这里所说的当然不是德国资产阶级，而是全世界的资产阶级。资本家瓜分世界，并不是因为他们的心肠特别狠毒，而是因为集中已经达到这样的阶段，使他们不得不走上这条获取利润的道路；而且他们是“按资本”、“按实力”来瓜分世界的，在商品生产和资本主义制度下也不可能有其它的瓜分方法。实力则是随经济和政治的发展而变化的；要了解当前发生的事情，就必须知道哪些问题要由实力的变化来解决，至于这些变化是 “纯粹”经济的变化，还是非经济的（例如军事的）变化，却是次要的问题，丝毫不能改变对于资本主义最新时代的基本观点。拿资本家同盟互相进行斗争和订立契约的形式（今天是和平的，明天是非和平的，后天又是非和平的）问题来偷换斗争和协议的内容问题，就等于堕落成诡辩家。","language":"中文","translation":false},{"id":"imperialism-1-254","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":254,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"最新资本主义时代向我们表明，资本家同盟之间在从经济上瓜分世界的基础上形成了一定的关系，而与此同时，与此相联系，各个政治同盟、各个国家之间在从领土上瓜分世界、争夺殖民地、“争夺经济领土”的基础上也形成了一定的关系。","language":"中文","translation":false},{"id":"imperialism-1-255","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":255,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"地理学家亚·苏潘在他的一本论述“欧洲殖民地的扩展”的书中，对19世纪末的这种扩展情况，作了如下简短的总结：","language":"中文","translation":false},{"id":"imperialism-1-256","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":256,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"属于欧洲殖民大国(包括美国在内)的土地面积所占的百分比","language":"中文","translation":false},{"id":"imperialism-1-257","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":257,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1876年 1900年 增减数","language":"中文","translation":false},{"id":"imperialism-1-258","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":258,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在非洲 10.8% 90.4% +79.6%","language":"中文","translation":false},{"id":"imperialism-1-259","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":259,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在波利尼西亚 56.8% 98.9% +42.1%","language":"中文","translation":false},{"id":"imperialism-1-260","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":260,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在亚洲 51.5% 56.6% +5.1%","language":"中文","translation":false},{"id":"imperialism-1-261","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":261,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在澳洲 100.0% 100.0% -","language":"中文","translation":false},{"id":"imperialism-1-262","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":262,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在美洲 27.5% 27.2% -0.3%","language":"中文","translation":false},{"id":"imperialism-1-263","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":263,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"苏潘得出结论说：“可见，这个时期的特点是瓜分非洲和波利尼西亚。”因为在亚洲和美洲，无主的土地，即不属于任何国家的土地已经没有了，所以应当扩大苏潘的结论，应当说，我们所考察的这个时期的特点是世界瓜分完毕。所谓完毕，并不是说不可能重新瓜分了?----相反，重新瓜分是可能的，并且是不可避免的——，而是说在资本主义各国的殖民政策之下，我们这个行星上无主的土地都被霸占完了。世界已第一次被瓜分完毕，所以以后只能是重新瓜分，也就是从一个“主人”转归另一个“主人”，而不是从无主的变为“有主的”。","language":"中文","translation":false},{"id":"imperialism-1-264","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":264,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"可见，我们是处在一个同“资本主义发展的最新阶段”即金融资本密切联系的世界殖民政策的特殊时代。因此，首先必须较详细地研究一下实际材料，以便尽量确切地弄清楚这个时代和先前各个时代有什么不同，现在的情况究竟怎样。这里，首先就产生了两个事实问题：殖民政策的加强，争夺殖民地斗争的尖锐化，是不是恰好在金融资本时代出现的，在这方面，现在世界瓜分的情况究竟怎样。","language":"中文","translation":false},{"id":"imperialism-1-265","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":265,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国作家莫里斯在他写的一本关于殖民史的著作中，对英、法、德三国在19世纪各个时期的殖民地面积的材料作了归纳。现在把他所得出的结果简单列表如下：","language":"中文","translation":false},{"id":"imperialism-1-266","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":266,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"殖 民 地 面 积(面积单位百万平方英里)(人口单位百万)","language":"中文","translation":false},{"id":"imperialism-1-267","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":267,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"面积 人口 面积 人口 □面积 人口","language":"中文","translation":false},{"id":"imperialism-1-268","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":268,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1815-1830年 ？ 126.4 0.02 0.5 - -","language":"中文","translation":false},{"id":"imperialism-1-269","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":269,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1860年 2.5 145.1 0.2 3.4 - -","language":"中文","translation":false},{"id":"imperialism-1-270","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":270,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1880年 7.7 267.9 0.7 7.5 - -","language":"中文","translation":false},{"id":"imperialism-1-271","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":271,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1899年 9.3 309.0 3.7 56.4 1.0 14.7","language":"中文","translation":false},{"id":"imperialism-1-272","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":272,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"英国特别加紧夺取殖民地是在1860-1880年这个时期，而且在19世纪最后20年还在大量地夺取。法德两国加紧夺取殖民地也正是在这20年间。我们在上面已经看到，垄断前的资本主义，即自由竞争占统治的资本主义，发展到顶点的时期是19世纪60年代和70年代。现在我们又看到，正是在这个时期以后，开始了夺取殖民地的大“高潮”，瓜分世界领土的斗争达到了极其尖锐的程度。所以，毫无疑问，资本主义向垄断资本主义阶段的过渡，即向金融资本的过渡，是同瓜分世界的斗争的尖锐化联系着的。","language":"中文","translation":false},{"id":"imperialism-1-273","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":273,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"霍布森在论述帝国主义的著作中，把1884-1900年这个时期划为欧洲主要国家加紧“扩张”（扩大领土）的时期。据他计算，在这个时期，英国夺得了370万平方英里的土地和5700万人口，法国360万平方英里的土地和3650万人口，德国100万平方英里的土地和1470万人口，比利时90万平方英里的土地和3000万人口，葡萄牙80万平方英里的土地和900万人口。在19世纪末，特别是自19世纪80年代以来，各资本主义国家拼命争夺殖民地，已是外交史和对外政策史上众所周知的事实。","language":"中文","translation":false},{"id":"imperialism-1-274","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":274,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在1840-1860年英国自由竞争最兴盛的时期，英国居于领导地位的资产阶级政治家是反对殖民政策的，他们认为殖民地的解放和完全脱离英国，是一件不可避免而且有益的事情。麦·贝尔在1898年发表的一篇论述“现代英国帝国主义”的文章中指出，在1852年的时候，象迪斯累里这样一个一般说来是倾向于帝国主义的英国政治家，尚且说过：“殖民地是吊在我们脖子上的磨盘。”到19世纪末，成为英国风云人物的，已经是公开鼓吹帝国主义、肆无忌惮地实行帝国主义政策的塞西尔·罗得斯和约瑟夫·张伯伦了！","language":"中文","translation":false},{"id":"imperialism-1-275","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":275,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"值得注意的是，这些居于领导地位的英国资产阶级政治家当时就清楚地看到现代帝国主义的所谓纯粹经济根源和社会政治根源之间的联系。张伯伦鼓吹帝国主义是“正确、明智和经济的政策”，他特别举出目前英国在世界市场上遇到的来自德国、美国、比利时的竞争。资本家说，挽救的办法是实行垄断，于是就创办卡特尔、辛迪加、托拉斯。资产阶级的政治领袖随声附和说，挽救的办法是实行垄断，于是就急急忙忙地去夺取世界上尚未瓜分的土地。 据塞西尔·罗得斯的密友新闻记者斯特德说，1895年罗得斯曾经同他谈到自己的帝国主义的主张，罗得斯说：“我昨天在伦敦东头〈工人区〉参加了一个失业工人的集会。我在那里听到了一片狂叫‘□面包，面包！’的喊声。在回家的路上，我反复思考着看到的情景，结果我比以前更相信帝国主义的重要了…… 我的一个宿愿就是解决社会问题，就是说，为了使联合王国4000万居民免遭流血的内战，我们这些殖民主义政治家应当占领新的土地，来安置过剩的人口，为工厂和矿山生产的商品找到新的销售地区。我常常说，帝国就是吃饭问题。要是你不希望发生内战，你就应当成为帝国主义者。”","language":"中文","translation":false},{"id":"imperialism-1-276","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":276,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"百万富翁、金融大王、英布战争的罪魁塞西尔·罗得斯在1895年就是这样讲的。他对帝国主义的辩护只是比较粗俗，比较肆无忌惮，而实质上和马斯洛夫、休特古姆、波特列索夫、大卫诸先生以及那位俄国马克思主义创始人196等等的“理论”并没有什么不同。塞西尔·罗得斯是个比较诚实一点的社会沙文主义者……","language":"中文","translation":false},{"id":"imperialism-1-277","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":277,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"为了对世界领土的瓜分情况和近几十年来这方面的变化作一个尽可能确切的描述，我们要利用苏潘在上述那部关于世界各大国殖民地问题的著作中提供的综合材料。苏潘选的是1876年和1900年，我们则选用1876年（这一年选得很恰当，因为正是到这个时候，垄断前阶段的西欧资本主义的发展，整个说来可以算是完成了）和1914年（用许布纳尔的《地理统计表》上的比较新的数字来代替苏潘的数字）。苏潘只列出了殖民地；我们认为，把关于非殖民国家和半殖民地的简略数字补充进去，对描绘瓜分世界的全貌是有益的。我们把波斯、中国和土耳其列入殖民地，其中第一个国家差不多已经完全变成了殖民地，第二个和第三个国家正在变成殖民地。","language":"中文","translation":false},{"id":"imperialism-1-278","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":278,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"大国的殖民地(面积单位百万平方公里，人口单位百万)","language":"中文","translation":false},{"id":"imperialism-1-279","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":279,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1876年 1914年 1914年 1914年","language":"中文","translation":false},{"id":"imperialism-1-280","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":280,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"面积 人口□面积 人口□面积 人口 面积 人口","language":"中文","translation":false},{"id":"imperialism-1-281","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":281,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"英国 22.5 251.9 33.5 393.5 0.3 46.5 33.8 440.0","language":"中文","translation":false},{"id":"imperialism-1-282","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":282,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"俄国 17.0 15.9 17.4 33.2 5.4 136.2 22.8 169.4","language":"中文","translation":false},{"id":"imperialism-1-283","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":283,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"法国 0.9 6.0 10.6 55.5 0.5 39.6 11.1 95.1","language":"中文","translation":false},{"id":"imperialism-1-284","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":284,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国 - - 2.9 12.3 0.5 64.9 3.4 77.2","language":"中文","translation":false},{"id":"imperialism-1-285","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":285,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国 - - 0.3 9.7 9.4 97.0 9.7 106.7","language":"中文","translation":false},{"id":"imperialism-1-286","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":286,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"日本 - - 0.3 19.2 0.4 53.0 0.7 72.2","language":"中文","translation":false},{"id":"imperialism-1-287","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":287,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"6国总计40 273.8 65.0 523.4 16.5 437.2 81.5 960.6","language":"中文","translation":false},{"id":"imperialism-1-288","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":288,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"其余大国(比利时、荷兰等)的殖民地 9.9 45.3","language":"中文","translation":false},{"id":"imperialism-1-289","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":289,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"半殖民地(波斯、中国、土耳其) 14.5 361.2","language":"中文","translation":false},{"id":"imperialism-1-290","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":290,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"其余国家 28.0 289.9","language":"中文","translation":false},{"id":"imperialism-1-291","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":291,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"全球 133.9 1657.0","language":"中文","translation":false},{"id":"imperialism-1-292","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":292,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们从这里清楚看到在19世纪和20世纪之交世界被瓜分“完毕”的情况。1876年以后，殖民地有极大的扩张：6个最大的大国的殖民地增加了一半以上，由4000万平方公里增加到6500万平方公里，增加了2500万平方公里，比各宗主国的面积(1650万）多一半。有3个大国在1876年根本没有殖民地，另一个大国法国，当时也差不多没有。到1914年，这4个大国获得的殖民地面积为1410万平方公里，即大致比欧洲面积还大一半，这些殖民地的人口差不多有1亿。殖民地的扩张是非常不平衡的。例如拿面积和人口都相差不远的法、德、日三国来比较，就可以看出，法国的殖民地（按面积来说）几乎比德日两国殖民地的总和多两倍。不过在我们所谈的这个时代的初期，法国金融资本的数量大概也比德日两国的总和多几倍。除纯粹的经济条件而外，地理和其它条件也在这些经济条件的基础上影响到殖民地的大小。近几十年来，在大工业、交换和金融资本的压力下，世界的均等化，即各国经济条件与生活条件的平均化，虽然进展得很快，但差别还是不小的。在上述6个国家中，我们看到，一方面有年轻的进步非常快的资本主义国家（美、德、日），另一方面有近来进步比前面几国慢得多的老的资本主义国家（法、英），另外还有一个经济上最落后的国家（俄国），这个国家的现代资本帝国主义可以说是被前资本主义关系的密网紧紧缠绕着。","language":"中文","translation":false},{"id":"imperialism-1-293","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":293,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"除大国的殖民地以外，我们还列进了小国的小块殖民地。这些殖民地可以说是可能发生而且极可能发生的对殖民地的“重新瓜分”的最近目标。这些小国能够保持自己的殖民地，主要是因为大国之间存在着利益上的对立，存在着摩擦等等，妨碍了它们达成分赃的协议。至于“半殖民地”国家，它们是自然界和社会一切领域常见的过渡形式的例子。金融资本是一种存在于一切经济关系和一切国际关系中的巨大力量，可以说是起决定作用的力量，它甚至能够支配而且实际上已经支配着一些政治上完全独立的国家；这种例子我们马上就要讲到。不过，对金融资本最“方便”最有利的当然是使从属的国家和民族丧失政治独立这样的支配。半殖民地国家是这方面的“中间”形式的典型。显然，在金融资本时代，当世界上其它地方已经瓜分完毕的时候，争夺这些半附属国的斗争也就必然特别尖锐起来。","language":"中文","translation":false},{"id":"imperialism-1-294","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":294,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"殖民政策和帝国主义在资本主义最新阶段以前，甚至在资本主义以前就已经有了。以奴隶制为基础的罗马就推行过殖民政策，实行过帝国主义。但是，“泛泛地”谈论帝国主义而忘记或忽视社会经济形态的根本区别，必然会变成最空洞的废话或吹嘘，就象把“大罗马和大不列颠”相提并论那样。就是资本主义过去各阶段的资本主义殖民政策，同金融资本的殖民政策也是有重大差别的。","language":"中文","translation":false},{"id":"imperialism-1-295","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":295,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"最新资本主义的基本特点是最大企业家的垄断同盟的统治。当这种垄断组织独自霸占了所有原料产地的时候，它们就巩固无比了。我们已经看到，资本家国际同盟怎样拼命地致力于剥夺对方进行竞争的一切可能，收买譬如蕴藏铁矿的土地或石油资源等等。只有占领殖民地，才能充分保证垄断组织自如地应付同竞争者的斗争中的各种意外事件，包括对方打算用国家垄断法来实行自卫这样的意外事件。资本主义愈发达，原料愈感缺乏，竞争和追逐全世界原料产地的斗争愈尖锐，抢占殖民地的斗争也就愈激烈。","language":"中文","translation":false},{"id":"imperialism-1-296","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":296,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"施尔德尔写道：“可以作出一个在某些人看来也许是怪诞不经的论断，就是说，城市人口和工业人口的增长，在较近的将来与其说会遇到食品缺乏的障碍，远不如说会遇到工业原料缺乏的障碍。”例如木材（它变得日益昂贵）、皮革和纺织工业原料，都愈来愈缺乏。“工业家同盟企图在整个世界经济的范围内造成农业和工业的平衡；1904年几个主要工业国家的棉纺业工厂主同盟成立的国际同盟就是一个例子；后来在1910年，欧洲麻纺业厂主同盟也仿照它成立了一个同盟。”","language":"中文","translation":false},{"id":"imperialism-1-297","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":297,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"当然，资产阶级改良主义者，其中尤其是现在的考茨基主义者，总是企图贬低这种事实的意义，说不用“代价很大而且很危险的”殖民政策就“可以”在自由市场上取得原料，说“简单地”改善一下一般农业的条件就“可以”大大增加原料的供应。但是，这样说就成了替帝国主义辩护，替帝国主义涂脂抹粉，因为这样说就是忘记了最新资本主义的主要特点——垄断。自由市场愈来愈成为过去的事情，垄断性的辛迪加和托拉斯一天天地缩小自由市场，而“简单地”改善一下农业条件，就得改善民众的处境，提高工资，减少利润。可是，除了在甜蜜的改良主义者的幻想里，哪里会有能够关心民众的处境而不关心夺取殖民地的托拉斯呢？","language":"中文","translation":false},{"id":"imperialism-1-298","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":298,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"对于金融资本来说，不仅已经发现的原料产地，而且可能有原料的地方，都是有意义的，因为当代技术发展异常迅速，今天无用的土地，要是明天找到新的方法（为了这个目的，大银行可以配备工程师和农艺师等等去进行专门的考察），要是投入大量资本，就会变成有用的土地。矿藏的勘探，加工和利用各种原料的新方法等等，也是如此。因此，金融资本必然力图扩大经济领土，甚至一般领土。托拉斯估计到将来“可能获得的”（而不是现有的）利润，估计到将来垄断的结果，把自己的财产按高一两倍的估价资本化；同样，金融资本也估计到可能获得的原料产地，唯恐在争夺世界上尚未瓜分的最后几块土地或重新瓜分已经瓜分了的一些土地的疯狂斗争中落后于他人，总想尽量夺取更多的土地，不管这是一些什么样的土地，不管这些土地在什么地方，也不管采取什么手段。","language":"中文","translation":false},{"id":"imperialism-1-299","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":299,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"英国资本家用尽一切办法竭力在自己的殖民地埃及发展棉花生产(1904年埃及的230万公顷耕地中，就有60万公顷，即1/4以上用来种植棉花），俄国资本家在自己的殖民地土耳其斯坦也这样做，因为这样他们就能较容易地打败外国的竞争者，较容易地垄断原料产地，成立一个实行“联合”生产、包揽棉花种植和加工的各个阶段的、更经济更盈利的纺织业托拉斯。","language":"中文","translation":false},{"id":"imperialism-1-300","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":300,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本输出的利益也同样地在推动人们去夺取殖民地，因为在殖民地市场上，更容易（有时甚至只有在那里才可能）用垄断的手段排除竞争者，保证由自己来供应，巩固相应的“联系”等等。","language":"中文","translation":false},{"id":"imperialism-1-301","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":301,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在金融资本的基础上生长起来的非经济的上层建筑，即金融资本的政策和意识形态，加强了夺取殖民地的趋向。希法亭说得很对：“金融资本要的不是自由，而是统治。”有一个法国资产阶级作家好象是在发挥和补充上述塞西尔·罗得斯的思想，他写道，现代殖民政策除经济原因外，还应当加上社会原因：“愈来愈艰难的生活不仅压迫着工人群众，而且压迫着中间阶级，因此在一切老的文明国家中都积下了‘一种危及社会安定的急躁、愤怒和憎恨的情绪；应当为脱离一定阶级常轨的力量找到应用的场所，应当给它在国外找到出路，以免在国内发生爆炸’。”","language":"中文","translation":false},{"id":"imperialism-1-302","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":302,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"既然谈到资本帝国主义时代的殖民政策，那就必须指出，金融资本和同它相适应的国际政策，即归根到底是大国为了在经济上和政治上瓜分世界而斗争的国际政策，造成了许多过渡的国家依附形式。这个时代的典型的国家形式不仅有两大类国家，即殖民地占有国和殖民地，而且有各种形式的附属国，它们在政治上、形式上是独立的，实际上却被金融和外交方面的依附关系的罗网缠绕着。上面我们已经说过一种形式——半殖民地。而阿根廷这样的国家则是另一种形式的典型。","language":"中文","translation":false},{"id":"imperialism-1-303","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":303,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"舒尔采-格弗尼茨在一本论不列颠帝国主义的著作中写道：“南美，特别是阿根廷，在金融上如此依附于伦敦，应当说是几乎成了英国的商业殖民地。”施尔德尔根据奥匈帝国驻布宜诺斯艾利斯的领事1909年的报□告，确定英国在阿根廷的投资有875000万法郎。不难设想，由于这笔投资，英国金融资本及其忠实“友人”英国外交，同阿根廷资产阶级，同阿根廷整个经济政治生活的领导人物有着多么巩固的联系。","language":"中文","translation":false},{"id":"imperialism-1-304","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":304,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"葡萄牙的例子向我们表明了政治上独立而金融上和外交上不独立的另一种稍微不同的形式。葡萄牙是个独立的主权国家，但是实际上从西班牙王位继承战争(1701-1714年）起，这200多年来它始终处在英国的保护之下，英国为了加强它在反对自己的敌人西班牙和法国的斗争中的地位，保护了葡萄牙及其殖民地。英国以此换得了商业上的利益，换得了向葡萄牙及其殖民地输出商品、尤其是输出资本的优惠条件，换得了使用葡萄牙的港口、岛屿、电缆等等的便利。某些大国和小国之间的这种关系过去一向就有，但是在资本帝国主义时代，这种关系成了普遍的制度，成了“瓜分世界”的全部关系中的一部分，成了世界金融资本活动中的环节。","language":"中文","translation":false},{"id":"imperialism-1-305","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":305,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"为了结束关于瓜分世界问题的讨论，我们还要指出下面一点。不但美西战争以后的美国著作和英布战争以后的英国著作，在19世纪末和20世纪初十分公开而明确地提出了这个问题，不但最“忌妒地”注视着“不列颠帝国主义”的德国著作经常在估计这个事实，而且在法国资产阶级著作中，就资产阶级可以达到的程度来说，问题也提得相当明确而广泛。让我们来引证历史学家德里奥的一段话，他在《19世纪末的政治问题和社会问题》一书中论述“大国与瓜分世界”的一章里写道：“近年来世界上所有未被占据的地方，除了中国以外，都被欧洲和北美的大国占据了。在这个基础上已经发生了某些冲突和势力变动，这一切预示着最近的将来会有更可怕的爆发。因为大家都得急急忙忙地干：凡是没有及时得到一份的国家，就可能永远得不到它的一份，永远不能参加对世界的大规模开拓，而这将是下一世纪即20世纪最重要的事实之一。所以近来全欧洲和美国都充满了殖民扩张和‘帝国主义’的狂热，‘帝国主义’成了19世纪末最突出的特点。”作者又补充说：“在这种瓜分世界的情况下，在这种疯狂追逐地球上的宝藏和巨大市场的角斗中，这个世纪即19世纪建立起来的各个帝国之间的力量对比，是与建立这些帝国的民族在欧洲所占的地位完全不相称的。在欧洲占优势的大国，即欧洲命运的主宰者，并非在全世界也占有同样的优势。因为强大的殖民实力和占有尚未查明的财富的希望，显然会反过来影响欧洲大国的力量对比，所以殖民地问题（也可以说是“帝国主义”）这个已经改变了欧洲本身政治局面的问题，一定还会日甚一日地改变这个局面。”","language":"中文","translation":false},{"id":"imperialism-1-306","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":306,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"七 帝国主义是资本主义的特殊阶段","language":"中文","translation":false},{"id":"imperialism-1-307","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":307,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在我们应当试作一个总结，把以上关于帝国主义的论述归纳一下。帝国主义是作为一般资本主义基本特性的发展和直接继续而生长起来的。但是，只有在资本主义发展到一定的、很高的阶段，资本主义的某些基本特性开始转化成自己的对立面，从资本主义到更高级的社会经济结构的过渡时代的特点已经全角成和暴露出来的时候，资本主义才变成了资本帝国主义。在这一过程中，经济上的基本事实，就是资本主义的自由竞争为资本主义的垄断所代替。自由竞争是资本主义和一般商品生产的基本特性；垄断是自由竞争的直接对立面，但是我们眼看着自由竞争开始转化为垄断：自由竞争造成大生产，排挤小生产，又用更大的生产来代替大生产，使生产和资本的集中达到这样的程度，以致从中产生了并且还在产生着垄断，即卡特尔、辛迪加、托拉斯以及同它们相融合的十来家支配着几十亿资金的银行的资本。同时，从自由竞争中生长起来的垄断并不消除自由竞争，而是凌驾于这种竞争之上，与之并存，因而产生许多特别尖锐特别剧烈的矛盾、摩擦和冲突。垄断是从资本主义到更高级的制度的过渡。","language":"中文","translation":false},{"id":"imperialism-1-308","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":308,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"如果必须给帝国主义下一个尽量简短的定义，那就应当说，帝国主义是资本主义的垄断阶段。这样的定义能包括最主要之点，因为一方面，金融资本就是和工业家垄断同盟的资本融合起来的少数垄断性的最大银行的银行资本；另一方面，瓜分世界，就是由无阻碍地向未被任何一个资本主义大国占据的地区推行的殖民政策，过渡到垄断地占有已经瓜分完了的世界领土的殖民政策。","language":"中文","translation":false},{"id":"imperialism-1-309","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":309,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"过于简短的定义虽然方便（因为它概括了主要之点），但是要从中分别推导出应当下定义的现象的那些最重要的特点，这样的定义毕竟是不够的。因此，如果不忘记所有定义都只有有条件的、相对的意义，永远也不能包括充分发展的现象一切方面的联系，就应当给帝国主义下这样一个定义，其中要包括帝国主义的如下五个基本特征：(1)生产和资本的集中发展到这样高的程度，以致造成了在经济生活中起决定作用的垄断组织；(2)银行资本和工业资本已经融合起来，在这个“金融资本的”基础上形成了金融寡头；(3)和商品输出不同的资本输出具有特别重要的意义；(4)瓜分世界的资本家国际垄断同盟已经形成；(5)最大资本主义大国已把世界上的领土瓜分完毕。帝国主义是发展到垄断组织和金融资本的统治已经确立、资本输出具有突出意义、国际托拉斯开始瓜分世界、一些最大的资本主义国家已把世界全部领土瓜分完毕这一阶段的资本主义。","language":"中文","translation":false},{"id":"imperialism-1-310","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":310,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"下面我们还会看到，如果不仅注意到基本的、纯粹经济的概念（上述定义就只限于这些概念），而且注意到现阶段的资本主义同一般资本主义相比所占的历史地位，或者注意到帝国主义同工人运动中两个主要派别的关系，那就可以而且应当给帝国主义另外下一个定义。现在先必须指出，帝国主义，按上述意义来了解，无疑是资本主义发展的一个特殊阶段。为了使读者对于帝国主义有一个有充分根据的了解，我们故意尽量多引用了一些不得不承认最新资本主义经济中十分确凿的事实的资产阶级经济学家所发表的意见。为了同一目的，我们又引用了一些详细的统计材料，从中可以看出银行资本等究竟发展到了怎样的程度，看出量转化为质，发达的资本主义转化为帝国主义，究竟表现在什么地方。不用说，自然界和社会里的一切界限当然都是有条件的、变动的，如果去争论帝国主义究竟在哪一年或哪一个10年“最终”确立，那是荒唐的。","language":"中文","translation":false},{"id":"imperialism-1-311","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":311,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"但是，我们不得不在帝国主义的定义问题上，首先同所谓第二国际时代(1889-1914年这25年间）主要的马克思主义理论家卡·考茨基进行争论。在1915年，甚至早在1914年11月，考茨基就十分坚决地反对我们给帝国主义下的定义所表述的基本思想，他说不应当把帝国主义了解为一个经济上的“时期”或阶段，而应当了解为一种政策，即金融资本“比较爱好的”政策；不应当把帝国主义和“现代资本主义”“等同起来”；如果把帝国主义了解为“现代资本主义的一切现象”（卡特尔、保护主义、金融家的统治、殖民政策），那么帝国主义是资本主义所必需的这个问题就成了“最乏味的同义反复”，因为那样的话，“帝国主义就自然是资本主义生存所必需的了”，等等。为了最确切地表述考茨基的思想，我们引用他给帝国主义所下的定义，这个定义是直接反对我们所阐述的那些思想的实质的（因为，考茨基早已知道，多年来贯彻类似思想的德国马克思主义者阵营中所提出的反驳，正是马克思主义的一个派别所提出的反驳）。","language":"中文","translation":false},{"id":"imperialism-1-312","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":312,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“帝国主义是高度发达的工业资本主义的产物。帝国主义就是每个工业资本主义民族力图吞并或征服愈来愈多的农业〈黑体是考茨基用的〉区域，而不管那里居住的是什么民族。”","language":"中文","translation":false},{"id":"imperialism-1-313","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":313,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这个定义是根本要不得的，因为它片面地，也就是任意地单单强调了一个民族问题（虽然这个问题无论就其本身还是就其对帝国主义的关系来说，都是极其重要的），任意地和错误地把这个问题单单同兼并其它民族的那些国家的工业资本联系起来，又同样任意地和错误地突出了对农业区域的兼并。","language":"中文","translation":false},{"id":"imperialism-1-314","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":314,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"帝国主义就是力图兼并，——考茨基的定义的政治方面归结起来就是这样。这是对的，但是极不完全，因为在政治方面，帝国主义是力图使用暴力和实行反动。不过在这里我们要研究的是考茨基本人纳入他的定义中的经济方面。考茨基定义的错误是十分明显的。帝国主义的特点，恰好不是工业资本而是金融资本。在法国，恰好是在工业资本削弱的情况下金融资本特别迅速的发展，从上一世纪80年代开始使兼并政策（殖民政策）极度加强起来，这并不是偶然的。帝国主义的特点恰好不只是力图兼并农业区域，甚至还力图兼并工业极发达的区域（德国对比利时的野心，法国对洛林的野心），因为第一，世界已经瓜分完了，在重新瓜分的时候，就不得不把手伸向任何一块土地；第二，帝国主义的重要特点，是几个大国争夺霸权，即争夺领土，其目的与其说是直接为了自己，不如说是为了削弱对方，破坏对方的霸权（比利时作为反英据点对德国来说特别重要，巴格达作为反德据点对英国来说也一样重要，如此等等）。","language":"中文","translation":false},{"id":"imperialism-1-315","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":315,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基特地搬出、并且屡次搬出英国人来，似乎英国人确定的帝国主义一词的纯粹政治含义，是和他考茨基的意思相符的。现在就来看看英国人霍布森在他1902年出版的《帝国主义》一书中是怎样写的：","language":"中文","translation":false},{"id":"imperialism-1-316","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":316,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“新帝国主义和老帝国主义不同的地方在于：第一，一个日益强盛的帝国的野心，被几个互相竞争的帝国的理论和实践所代替，其中每个帝国都同样渴望政治扩张和贪图商业利益；第二，金融利益或投资利益统治着商业利益。”","language":"中文","translation":false},{"id":"imperialism-1-317","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":317,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们看到，考茨基笼统地搬出英国人来，是绝对没有事实根据的（他要搬的话，也只能是搬出那些庸俗的英国帝国主义者或帝国主义的公开辩护士）。我们看到，考茨基标榜自己在继续维护马克思主义，实际上比社会自由主义者霍布森还后退了一步，因为霍布森还比较正确地估计到现代帝国主义的两个“历史的具体的”（考茨基的定义恰好是对历史的具体性的嘲弄！）特点：(1)几个帝国主义互相竞争；(2)金融家比商人占优势。如果主要是工业国兼并农业国的问题，那就把商人抬上首要地位了。","language":"中文","translation":false},{"id":"imperialism-1-318","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":318,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基的定义不仅是错误的和非马克思主义的，而且还成了全面背离马克思主义理论和马克思主义实践的那一整套观点的基础，这一点以后还要讲到。考茨基挑起的那种字面上的争论，即资本主义的最新阶段应当叫作帝国主义还是叫作金融资本阶段，是毫无意义的争论。随便你怎样叫都是一样。关键在于考茨基把帝国主义的政治同它的经济割裂开了，把兼并解释为金融资本“比较爱好的”政策，并且拿同一金融资本基础上的另一种似乎可能有的资产阶级政策和它对立。照这样说来，经济上的垄断是可以同政治上的非垄断、非暴力、非掠夺的行动方式兼容的。照这样说来，瓜分世界领土（这种瓜分恰巧是在金融资本时代完成的并成了最大的资本主义国家现在互相竞争的特殊形式的基础）也是可以同非帝国主义的政策兼容的。这样一来，就不是暴露资本主义最新阶段最根本的矛盾的深刻性，而是掩饰、缓和这些矛盾；这样一来，就不是马克思主义，而是资产阶级改良主义。","language":"中文","translation":false},{"id":"imperialism-1-319","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":319,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基同德国的一个帝国主义和兼并政策的辩护士库诺争论过。库诺笨拙而又无耻地推论说：帝国主义是现代资本主义；资本主义的发展是不可避免的和进步的，所以帝国主义也是进步的，所以必须跪在帝国主义面前歌功颂德！这种话就象民粹派在1894-1895年讽刺俄国马克思主义者的时候所说的那些话，说什么如果马克思主义者认为资本主义在俄国是不可避免的和进步的，那么他们就应当开起酒馆来培植资本主义。考茨基反驳库诺说：不对，帝国主义并不是现代资本主义，而只是现代资本主义政策的形式之一，我们可以而且应当同这种政策作斗争，同帝国主义，同兼并等等作斗争。","language":"中文","translation":false},{"id":"imperialism-1-320","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":320,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这种反驳好象很有道理，实际上却等于更巧妙更隐蔽地（因此是更危险地）宣传同帝国主义调和，因为同托拉斯和银行的政策“作斗争”而不触动托拉斯和银行的经济基础，那就不过是资产阶级的改良主义与和平主义，不过是一种善良而天真的愿望而已。不是充分暴露矛盾的深刻性，而是回避存在的矛盾，忘掉其中最重要的矛盾，——这就是考茨基的理论，它同马克思主义毫无共同之点。显然，这种“理论”只能用来维护同库诺之流保持统一的思想！","language":"中文","translation":false},{"id":"imperialism-1-321","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":321,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基写道：“从纯粹经济的观点看来，资本主义不是不可能再经历一个新的阶段，即把卡特尔政策应用到对外政策上的超帝国主义的阶段”，也就是全世界各帝国主义彼此联合而不是互相斗争的阶段，在资本主义制度下停止战争的阶段，“实行国际联合的金融资本共同剥削世界”的阶段。","language":"中文","translation":false},{"id":"imperialism-1-322","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":322,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"关于这个“超帝国主义论”，我们以后还要谈到，以便详细地说明这个理论背弃马克思主义到了何等彻底而无可挽回的地步。现在，按照本书的总的规划，我们要看一看有关这个问题的确切的经济材料。“从纯粹经济的观点看来”，这个“超帝国主义”究竟是可能实现的呢，还是超等废话？","language":"中文","translation":false},{"id":"imperialism-1-323","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":323,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"如果纯粹经济的观点指的是一种“纯粹的”抽象概念，那么，说到底只能归结为这样一个论点：发展的趋势是走向垄断组织，因而也就是走向一个全世界的垄断组织，走向一个全世界的托拉斯。这是不容争辩的，不过也是毫无内容的，就好象说：“发展的趋势”是走向在实验室里生产食物。在这个意义上，超帝国主义“论”就如同什么“超农业论”一样是荒唐的。","language":"中文","translation":false},{"id":"imperialism-1-324","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":324,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"如果谈金融资本时代的“纯粹经济”条件，是指20世纪初这个历史的具体时代，那么对于“超帝国主义”这种僵死的抽象概念（它完全是为了一个最反动的目的，就是使人不去注意现有矛盾的深刻性）的最好回答，就是拿现代世界经济的具体经济现实同它加以对比。考茨基关于超帝国主义的毫无内容的议论还鼓舞了那种十分错误的、为帝国主义辩护士助长声势的思想，似乎金融资本的统治是在削弱世界经济内部的不平衡和矛盾，其实金融资本的统治是在加剧这种不平衡和矛盾。","language":"中文","translation":false},{"id":"imperialism-1-325","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":325,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"理·卡尔韦尔在他写的《世界经济导论》这本小册子里，对可以具体说明19世纪和20世纪之交世界经济内部相互关系的最重要的纯粹经济材料，作了归纳的尝试。他把整个世界分为5个“主要经济区域”：(1)中欧区（除俄国和英国以外的整个欧洲）；(2)不列颠区；(3)俄国区；(4)东亚区；(5)美洲区。同时他把殖民地列入所属国的“区域”内，而“撇开了”少数没有按上述区域划分的国家，例如亚洲的波斯、阿富汗和阿拉伯，非洲的摩洛哥和阿比西尼亚等等。","language":"中文","translation":false},{"id":"imperialism-1-326","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":326,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在把他所列出的这些区域的经济材料摘录如下：","language":"中文","translation":false},{"id":"imperialism-1-327","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":327,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"世界主要经济区域□面积 人口 交通运输业铁路 商船 (进出口共计) 煤炭产量 生铁产量 棉纺织业纱锭数目","language":"中文","translation":false},{"id":"imperialism-1-328","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":328,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(单位百万平方公里)(单位百万)(单位千公里)(单位百万吨)(单位十亿马克)(单位百万吨)(单位百万)","language":"中文","translation":false},{"id":"imperialism-1-329","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":329,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(1)中欧区27.6 (23.6) 388 (146)204 8 41 251 15 26","language":"中文","translation":false},{"id":"imperialism-1-330","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":330,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(2)不列颠区28.9 (28.6) 398 (355) 140 11 25 249 9 51","language":"中文","translation":false},{"id":"imperialism-1-331","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":331,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(3)俄国区 22 131 63 1 3 16 3 7","language":"中文","translation":false},{"id":"imperialism-1-332","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":332,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(4)东亚区 12 389 8 1 2 8 0.02 2","language":"中文","translation":false},{"id":"imperialism-1-333","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":333,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"(5)美洲区 30 148 379 6 14 245 14 19","language":"中文","translation":false},{"id":"imperialism-1-334","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":334,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们看到，有三个区域是资本主义高度发达（交通运输业、贸易和工业都十分发达）的区域，即中欧区、不列颠区和美洲区。其中德、英、美三国是统治着世界的国家。它们相互间的帝国主义竞争和斗争是非常尖锐的，因为德国的地区很小，殖民地又少，而“中欧区”的形成还有待于将来，现时它正在殊死的斗争中逐渐产生。目前整个欧洲的特征是政治上分散。相反，在不列颠区和美洲区，政治上却高度集中，但是它们之间又有极大的差别：前者有广大的殖民地，后者的殖民地却十分少。在殖民地，资本主义刚刚开始发展。争夺南美的斗争愈来愈尖锐。","language":"中文","translation":false},{"id":"imperialism-1-335","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":335,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"有两个区域是资本主义不发达的区域，即俄国区和东亚区。前者人口密度极小，后者极大；前者政治上很集中，后者不集中。瓜分中国才刚刚开始，日美等国争夺中国的斗争愈来愈激烈。","language":"中文","translation":false},{"id":"imperialism-1-336","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":336,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"请把考茨基关于“和平的”超帝国主义那种愚蠢可笑的胡说，拿来同经济政治条件极不相同、各国发展速度等等极不一致、各帝国主义国家间存在着疯狂斗争的实际情形比较一下吧。难道这不是吓坏了的小市民想逃避可怕的现实的反动企图吗？难道被考茨基当作“超帝国主义”的胚胎的国际卡特尔（正象“可以”把在实验室里生产片剂说成是超农业的胚胎一样），不就是向我们表明瓜分世界和重新瓜分世界、由和平瓜分转为非和平瓜分、再由非和平瓜分转为和平瓜分的一个例子吗？难道从前同德国一起（例如在国际钢轨辛迪加或国际商轮航运业托拉斯里）和平地瓜分过整个世界的美国和其它国家的金融资本，现在不是在按照以完全非和平的方式改变着的新的实力对比重新瓜分世界吗？","language":"中文","translation":false},{"id":"imperialism-1-337","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":337,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"金融资本和托拉斯不是削弱而是加强了世界经济各个部分在发展速度上的差异。既然实力对比发生了变化，那么在资本主义制度下，除了用实力来解决矛盾，还有什么别的办法呢？在铁路的统计中，我们可以看到说明整个世界经济中资本主义和金融资本发展速度不同的非常准确的材料。在帝国主义发展的最近几十年中，铁路长度变更的情形如下：","language":"中文","translation":false},{"id":"imperialism-1-338","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":338,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1890年 1913年 增加数","language":"中文","translation":false},{"id":"imperialism-1-339","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":339,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"欧洲 224 346 ＋122","language":"中文","translation":false},{"id":"imperialism-1-340","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":340,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国 268 411 ＋143","language":"中文","translation":false},{"id":"imperialism-1-341","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":341,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"独立国和半独立国43 125 137 347 ＋128＋222","language":"中文","translation":false},{"id":"imperialism-1-342","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":342,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"可见，铁路发展得最快的是殖民地和亚美两洲的独立国（以及半独立国）。大家知道，这里是由四五个最大的资本主义国家的金融资本统治着一切，支配着一切。在殖民地及亚美两洲其它国家建筑20万公里的新铁路，这意味着在特别有利的条件下，在收入有特别的保证、铸钢厂可以获得厚利定货等等的条件下，新投入400多亿马克的资本。","language":"中文","translation":false},{"id":"imperialism-1-343","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":343,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资本主义在殖民地和海外国家发展得最快。在这些国家中出现了新的帝国主义大国（如日本）。全世界帝国主义之间的斗争尖锐起来了。金融资本从特别盈利的殖民地企业和海外企业得到的贡款日益增加。在瓜分这种“赃物”的时候，有极大一部分落到了那些在生产力发展的速度上并不是常常占第一位的国家手里。各最大的强国及其殖民地的铁路总长度如下：","language":"中文","translation":false},{"id":"imperialism-1-344","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":344,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国 268 413 ＋145","language":"中文","translation":false},{"id":"imperialism-1-345","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":345,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"不列颠帝国 107 208 ＋101","language":"中文","translation":false},{"id":"imperialism-1-346","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":346,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"俄国 32 78 ＋46","language":"中文","translation":false},{"id":"imperialism-1-347","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":347,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国 43 68 ＋25","language":"中文","translation":false},{"id":"imperialism-1-348","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":348,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"法国 41 63 ＋22","language":"中文","translation":false},{"id":"imperialism-1-349","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":349,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"5个大国共计 491 830 ＋339","language":"中文","translation":false},{"id":"imperialism-1-350","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":350,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"可见，将近80%的铁路集中在5个最大的强国手中，但是这些铁路的所有权的集中程度，金融资本的集中程度，还要高得多，例如美、俄及其它国家铁路的大量股票和债券都属于英法两国的百万富翁。","language":"中文","translation":false},{"id":"imperialism-1-351","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":351,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"英国靠自己的殖民地，把“自己的”铁路网增加了10万公里，比德国增加的多3倍。但是，谁都知道，这一时期德国生产力的发展，特别是煤炭和钢铁生产的发展，其速度之快是英国无法比拟的，更不必说法国和俄国了。1892年，德国的生铁产量为490万吨，英国为680万吨；但是到1912年，已经是1760万吨比900万吨，也就是说，德国永远地超过英国了！试问，在资本主义基础上，要消除生产力发展和资本积累同金融资本对殖民地和“势力范围”的瓜分这两者之间不相适应的状况，除了用战争以外，还能有什么其它办法呢？","language":"中文","translation":false},{"id":"imperialism-1-352","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":352,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"八 资本主义的寄生性和腐朽性","language":"中文","translation":false},{"id":"imperialism-1-353","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":353,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在我们还要来研究一下帝国主义的另一个非常重要的方面，大多数关于帝国主义的论述，对这个方面往往认识不足。马克思主义者希法亭的缺点之一，就是他在这一点上比非马克思主义者霍布森还后退了一步。我们说的就是帝国主义所特有的寄生性。","language":"中文","translation":false},{"id":"imperialism-1-354","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":354,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们已经看到，帝国主义最深厚的经济基础就是垄断。这是资本主义的垄断，也就是说，这种垄断是从资本主义生长起来并且处在资本主义、商品生产和竞争的一般环境里，同这种一般环境始终有无法解决的矛盾。尽管如此，这种垄断还是同任何垄断一样，必然产生停滞和腐朽的趋向。在规定了（即使是暂时地）垄断价格的范围内，技术进步因而也是其它一切进步的动因，前进的动因，就在一定程度上消失了；其次在经济上也就有可能人为地阻碍技术进步。例如，美国有个姓欧文斯的发明了一种能引起制瓶业革命的制瓶机。德国制瓶工厂主的卡特尔收买了欧文斯的发明专利权，可是却把这个发明束之高阁，阻碍它的应用。当然，在资本主义制度下，垄断决不能完全地、长久地排除世界市场上的竞争（这也是超帝国主义论荒谬的原因之一）。用改良技术的办法可能降低生产费用和提高利润，这种可能性当然是促进着各种变化的。但是垄断所固有的停滞和腐朽的趋势仍旧在发生作用，而且在某些工业部门，在某些国家，在一定的时期，这种趋势还占上风。","language":"中文","translation":false},{"id":"imperialism-1-355","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":355,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"垄断地占有特别广大、富饶或地理位置方便的殖民地，也起着同样的作用。","language":"中文","translation":false},{"id":"imperialism-1-356","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":356,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"其次，帝国主义就是货币资本大量聚集于少数国家，其数额，如我们看到的，分别达到1000-1500亿法郎（有价证券）。于是，以“剪息票”为生，根本不参与任何企业经营、终日游手好闲的食利者阶级，确切些说，食利者阶层，就大大地增长起来。帝国主义最重要的经济基础之一——资本输出，更加使食利者阶层完完全全脱离了生产，给那种靠剥削几个海外国家和殖民地的劳动为生的整个国家打上了寄生性的烙印。","language":"中文","translation":false},{"id":"imperialism-1-357","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":357,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"霍布森写道：“在1893年，不列颠在国外的投资，约占联合王国财富总额的15%。”我们要指出，到1915年，这种资本又增加了大约一倍半。霍布森又说：“侵略性的帝国主义，要纳税人付出很高代价，对于工商业者来说殊少价值，……然而对于寻找投资场所的资本家〈在英语里，这个概念是用“investor”一词来表示的，意即“投资者”，食利者〉，却是大量利润的来源。”“据统计学家吉芬计算，1899年大不列颠从全部对外贸易和殖民地贸易（输入和输出）得到的全部年收入是1800万英镑，这是按贸易总额8亿英镑的2.5%计算出来的。”尽管这个数目不小，它却不能说明大不列颠侵略性的帝国主义。能够说明它的是9000-10000万英镑从“投资”得到的收入，也就是食利者阶层的收入。","language":"中文","translation":false},{"id":"imperialism-1-358","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":358,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在世界上“贸易”最发达的国家，食利者的收入竟比对外贸易的收入高4倍！这就是帝国主义和帝国主义寄生性的实质。因此，“食利国”(Rentnerstaat)或高利贷国这一概念，就成了论述帝国主义的经济著作中通用的概念。世界分为极少数高利贷国和极大多数债务国。舒尔采－格弗尼茨写道：“在国外投资中占第一位的，是对政治上附属的或结盟的国家的投资：英国贷款给埃及、日本、中国和南美。在必要时，英国的海军就充当法警。英国的政治力量保护着英国，防止债务人造反。”萨尔托里乌斯·冯·瓦尔特斯豪森在他所着的《国外投资的国民经济制度》一书中，把荷兰当作“食利国”的典型，并且说现在英国和法国也正在成为这样的国家。施尔德尔认为英国、法国、德国、比利时和瑞士这5个工业国家，是“明显的债权国”。他没有把荷兰算进去，只是因为荷兰“工业不大发达”。而美国仅仅是美洲的债权人。","language":"中文","translation":false},{"id":"imperialism-1-359","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":359,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"舒尔采－格弗尼茨写道：“英国逐渐由工业国变成债权国。虽然工业生产和工业品出口有了绝对的增加，但是，利息、股息和发行证券、担任中介、进行投机等方面的收入，在整个国民经济中的相对意义愈来愈大了。依我看来，这个事实正是帝国主义繁荣的经济基础。债权人和债务人之间的关系，要比卖主和买主之间的关系更巩固些。”关于德国的情形，柏林的《银行》杂志出版人阿·兰斯堡1911年在他的《德国是食利国》一文中写了如下一段话：“德国人喜欢讥笑法国人显露出来的那种渴望变为食利者的倾向。但是他们忘记了，就资产阶级来说，德国的情况同法国是愈来愈相象了。”","language":"中文","translation":false},{"id":"imperialism-1-360","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":360,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"食利国是寄生腐朽的资本主义的国家，这不能不影响到这种国家的一切社会政治条件，尤其是影响到工人运动的两个主要派别。为了尽量把这一点说清楚，我们还是引用霍布森的话。他是一个最“可靠的”证人，因为谁也不会疑心他偏袒“马克思主义的正统思想”；另一方面他又是英国人，很了解这个殖民地最广大、金融资本最雄厚、帝国主义经验最丰富的国家的情况。","language":"中文","translation":false},{"id":"imperialism-1-361","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":361,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"霍布森在对英布战争的印象很鲜明的情况下，描述了帝国主义同“金融家”利益的联系，以及“金融家”从承包、供应等业务获得的利润增加的情形，他说：“资本家是这一明显的寄生性政策的指挥者；但是同一动机对工人中间的特殊阶层也起作用。在很多城市中，最重要的工业部门都要依靠政府的定货；冶金工业和造船工业中心的帝国主义，也在不小的程度上可以归因于这个事实。”这位作者认为，有两种情况削弱了旧帝国的力量：(1)“经济寄生性”；(2)用附属国的人民编成军队。“第一种情况是经济寄生习气，这种习气使得统治国利用占领地、殖民地和附属国来达到本国统治阶级发财致富的目的，来收买本国下层阶级，使他们安分守己。”我们要补充一句：为了在经济上有可能进行这样的收买，不管收买的形式如何，都必须有垄断高额利润。","language":"中文","translation":false},{"id":"imperialism-1-362","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":362,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"关于第二种情况，霍布森写道：“帝国主义盲目征的最奇怪的征候之一，就是大不列颠、法国等帝国主义国家走上这条道路时所抱的那种漫不经心的态度。在这方面走得最远的是大不列颠。我们征服印度帝国的大部分战斗都是我们用土著人编成的军队进行的；在印度和近来在埃及，庞大的常备军是由英国人担任指挥的；我们征服非洲的各次战争，除了征服南部非洲的以外，几乎都是由土著人替我们进行的。”","language":"中文","translation":false},{"id":"imperialism-1-363","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":363,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"瓜分中国的前景，使霍布森作出了这样一种经济上的估计：“到那时，西欧大部分地区的面貌和性质，都将同现在有些国家的部分地区，如英格兰南部、里夫耶拉以及意大利和瑞士那些游人最盛、富人最多的地方一样，也会有极少数从远东取得股息和年金的富豪贵族，连同一批人数稍多的家臣和商人，为数更多的家仆以及从事运输和易腐坏产品最后加工的工人。主要的骨干工业部门就会消失，而大批的食品和半成品会作为贡品由亚非两洲源源而来。”“西方国家更广泛的同盟，即欧洲大国联邦向我们展示的前途就是，这个联邦不仅不会推进全世界的文明事业，反而有造成西方寄生性的巨大危险：产生出这样一批先进的工业国家，这些国家的上层阶级从亚非两洲获得巨额的贡款，并且利用这种贡款来豢养大批驯服的家臣，他们不再从事大宗的农产品和工业品的生产，而是替个人服务，或者在新的金融贵族监督下从事次要的工业劳动。让那些漠视这种理论〈应当说：前途〉、认为这个理论不值得研究的人，去思考一下已经处于这种状态的目前英格兰南部各区的经济条件和社会条件吧。让他们想一想，一旦中国受这种金融家、‘投资者’及其政治方面和工商业方面的职员的经济控制，使他们能从这个世界上所知道的最大的潜在富源汲取利润，以便在欧洲消费，这套方式将会扩展到怎样巨大的程度。当然，情况是极为复杂的，世界上各种力量的变化也难以逆料，所以不能很有把握地对未来作出某种唯一的预测。但是，现在支配着西欧帝国主义的那些势力，是在向着这个方向发展的。如果这些势力不遇到什么抵抗，不被引上另一个方面，它们就确实会朝着完成这一过程的方向努力。”","language":"中文","translation":false},{"id":"imperialism-1-364","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":364,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"作者说得完全对：如果帝国主义的力量不遇到抵抗，它就确实会走向这种结局。这里对于目前帝国主义情况下的“欧洲联邦”的意义，作了正确的估计。要补充的只有一点，就是在工人运动内部，目前在大多数国家暂时获得胜利的机会主义者，也是经常地一贯地朝着这个方向“努力”的。帝国主义意味着瓜分世界而不只是剥削中国一个国家，意味着极少数最富的国家享有垄断高额利润，所以，它们在经济上就有可能去收买无产阶级的上层，从而培植、形成和巩固机会主义。不过不要把反对帝国主义、特别是反对机会主义的那些力量忘掉，这些力量，社会自由主义者霍布森自然是看不到的。","language":"中文","translation":false},{"id":"imperialism-1-365","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":365,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国机会主义者格尔哈德·希尔德布兰德过去因为替帝国主义辩护而被开除出党，现在满可以充当德国所谓“社会民主”党的领袖，他给霍布森作了一个很好的补充，鼓吹“西欧联邦”（俄国除外），以便“共同”行动……反对非洲黑人、反对“大伊斯兰教运动”，以便维持“强大的陆海军”，对付“中日联盟”，等等。","language":"中文","translation":false},{"id":"imperialism-1-366","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":366,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"舒尔采－格弗尼茨对“不列颠帝国主义”的描绘，向我们揭示了同样的寄生性特征。从1865年到1898年，英国的国民收入增加了大约1倍，而这一时期“来自国外”的收入却增加了8倍。如果说帝国主义的“功劳”是“教育黑人去劳动”（不用强制手段是不行的……)，那么帝国主义的“危险”就在于，“欧洲将把体力劳动，起初把农业劳动和矿业劳动，然后把比较笨重的工业劳动，推给有色人种去干，自己则安然地当食利者，也许这样就为有色人种的经济解放以及后来的政治解放作好了准备”。","language":"中文","translation":false},{"id":"imperialism-1-367","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":367,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"在英国，愈来愈多的土地不再用于农业生产，而成了专供富人运动作乐的场所。人们谈到苏格兰这个最贵族化的、用作打猎和其它运动的地方时，都说“它是靠自己的过去和卡内基先生〈美国亿万富翁〉生活的”。英国每年单是花在赛马和猎狐上面的费用，就有1400万英镑（约合13000万卢布）。英国食利者的人数约有100万。从事生产的人口的百分比日益下降：","language":"中文","translation":false},{"id":"imperialism-1-368","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":368,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"英国人口 主要工业部门的工人人数 工人在人口总数中所占的百分比","language":"中文","translation":false},{"id":"imperialism-1-369","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":369,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1851年 17.9 4.1 23%","language":"中文","translation":false},{"id":"imperialism-1-370","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":370,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1901年 32.5 4.9 15%","language":"中文","translation":false},{"id":"imperialism-1-371","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":371,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这位研究“20世纪初的不列颠帝国主义”的资产阶级学者谈到英国工人阶级的时候，不得不经常把工人“上层”和“真正的无产阶级下层”加以区别。上层中间有大批人参加合作社、工会、体育团体和许多教派。选举权是同这个阶层的地位相适应的，这种选举权在英国“还有相当多的限制，以排除真正的无产阶级下层”！！为了粉饰英国工人阶级的状况，人们通常只谈论在无产阶级中占少数的这个上层，例如，“失业问题主要是涉及伦敦和无产阶级下层，这个下层是政治家们很少重视的……”应当说资产阶级政客和“社会党人”机会主义者们很少重视。","language":"中文","translation":false},{"id":"imperialism-1-372","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":372,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"从帝国主义国家移往国外的人数逐渐减少，从比较落后的、工资比较低的国家移入帝国主义国家的人数（流入的工人和移民）却逐渐增加，这也是与上面描述的一系列现象有关的帝国主义特点之一。据霍布森说，英国移往国外的人数从1884年起开始减少：1884年有242000人，而1900年只有169000人。德国移往国外的人数，在1881-1890年的10年中达到了最高峰，有1453000人，但是在后来的两个10年里，又减少到544000人和341000人。同时，从奥、意、俄及其它国家移入德国的工人却增加了。根据1907年的人口调查，德国有1342294个外国人，其中产业工人有440800人，农业工人有257329人。法国的采矿工业工人“很大一部分”是外国人——波兰人、意大利人和西班牙人。在美国，从东欧和南欧移移入的侨民做工资最低的工作，在升为监工和做工资最高的工作的工人中，美国工人所占的百分比最大。帝国主义有一种趋势，就是在工人中间也分化出一些特权阶层，并且使他们脱离广大的无产阶级群众。","language":"中文","translation":false},{"id":"imperialism-1-373","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":373,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"必须指出：在英国，帝国主义分裂工人、加强工人中间的机会主义、造成工人运动在一段时间内腐化的这种趋势，在19世纪末和20世纪初以前很久，就已经表现出来了。因为英国从19世纪中叶起，就具备了帝国主义的两大特点：拥有广大的殖民地；在世界市场上占垄断地位。马克思和恩格斯在几十年中一直密切注视着工人运动中的机会主义和英国资本主义的帝国主义特点之间的这种联系。例如，恩格斯在1858年10月7日给马克思的信中说：“英国无产阶级实际上日益资产阶级化了，因而这一所有民族中最资产阶级化的民族，看来想把事情最终导致这样的地步，即除了资产阶级，还要有资产阶级化的贵族和资产阶级化的无产阶级。自然，对一个剥削全世界的民族来说，这在某种程度上是有道理的。”过了将近1/4世纪，恩格斯又在1881年8月11日写的信里说到了“被中产阶级收买了的，或至少是领取中产阶级报酬的人所领导的最坏的英国工联”。恩格斯在1882年9月12日给考茨基的信中又说：“您问我：英国工人对殖民政策的想法如何？这和他们对一般政策的想法一样。这里没有工人政党，有的只是保守党和自由激进党，而工人十分安然地同他们共享英国的殖民地垄断权和英国在世界市场上的垄断权。”（恩格斯在1892年为《英国工人阶级状况》第2版所写的序言中，也叙述了同样的看法。)","language":"中文","translation":false},{"id":"imperialism-1-374","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":374,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这里已经把原因和后果明白地指出来了。原因是：(1)这个国家剥削全世界；(2)它在世界市场上占有垄断地位；(3)它拥有殖民地垄断权。后果是：(1)英国一部分无产阶级已经资产阶级化了；(2)英国一部分无产阶级受那些被资产阶级收买或至少是领取资产阶级报酬的人领导。在20世纪初，帝国主义完成了极少数国家对世界的瓜分，其中每个国家现在都剥削着（指榨取超额利润）“全世界”的一部分，只是比英国在1858年剥削的地方稍小一点；每一个国家都由于托拉斯、卡特尔、金融资本以及债权人对债务人的关系等等而在世界市场上占有垄断地位；每个国家都在一定程度上拥有殖民地垄断权（我们已经看到，世界上7500万平方公里的全部殖民地中，有6500万平方公里，即86%集中在6个大国手里；有6100万平方公里，即81%集中在3个大国手里）。","language":"中文","translation":false},{"id":"imperialism-1-375","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":375,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"现在局势的特点在于形成了以下这些经济政治条件：帝国主义已经从萌芽状态生长为统治的体系，资本主义垄断组织在国民经济和政治中居于首要地位，世界已经瓜分完毕；另一方面我们看到，作为整个20世纪初期特征的已经不是英国独占垄断权，而是少数帝国主义大国为分占垄断权而斗争。这些经济政治条件，不能不使机会主义同工人运动总的根本的利益更加不可调和。现在，机会主义已经不能象在19世纪后半期的英国那样，在一个国家的工人运动里取得完全胜利达几十年之久，但是它在许多国家里已经成熟，已经过度成熟，已经腐烂，并且作为社会沙文主义而同资产阶级的政策完全融合起来了。","language":"中文","translation":false},{"id":"imperialism-1-376","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":376,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这里所说的对帝国主义的批评是指广义的批评，是指社会各阶级根据自己的一般意识形态对帝国主义政策所采取的态度。","language":"中文","translation":false},{"id":"imperialism-1-377","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":377,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"集中在少数人手里的大量金融资本，建立了非常广泛而细密的关系和联系网，从而不仅控制了大批中小资本家，而且控制了大批最小的资本家和小业主，这是一方面；另一方面，同另一些国家的金融家集团为瓜分世界和统治其它国家而进行着尖锐的斗争，——这一切使所有的有产阶级全都转到帝国主义方面去了。“普遍”迷恋于帝国主义的前途，疯狂地捍卫帝国主义，千方百计地美化帝国主义，——这就是当代的标志。帝国主义的意识形态也渗透到工人阶级里面去了。工人阶级和其它阶级之间并没有隔着一道万里长城。德国现在的所谓“社会民主”党的领袖，被人们公正地称为“社会帝国主义者”，即口头上的社会主义者，实际上的帝国主义者，而霍布森早在1902年，就已经指出英国存在着属于机会主义“费边社”的“费边帝国主义者”了。","language":"中文","translation":false},{"id":"imperialism-1-378","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":378,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资产阶级的学者和政论家替帝国主义辩护，通常都是采用比较隐蔽的方式，掩盖帝国主义的完全统治和帝国主义的深刻根源，竭力把局部的东西和次要的细节放在主要的地位，拼命用一些根本无关紧要的“改良”计划，诸如由警察监督托拉斯或银行等等，来转移人们对实质问题的注意。至于那些肆无忌惮的露骨的帝国主义者的言论却比较少见，这些人倒敢于承认改良帝国主义的基本特性的想法是荒谬的。","language":"中文","translation":false},{"id":"imperialism-1-379","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":379,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"举个例子来说吧。一些德国帝国主义者在《世界经济文汇》这一刊物中，力图考察殖民地的民族解放运动，当然特别是那些非德属殖民地的民族解放运动。他们提到了印度的风潮和抗议运动，纳塔尔（南部非洲）的运动，荷属印度的运动等等。其中有人在评论一家英国刊物有关亚、非、欧三洲受外国统治的各民族代表于1910年6月28-30日举行的从属民族和种族代表会议的报道时，对会议上的演说作了这样的评价，他说：“据称，必须同帝国主义作斗争；统治国应当承认从属民族的独立权；国际法庭应当监督大国同弱小民族订立的条约的履行。除了表示这些天真的愿望以外，代表会议并没有继续前进。我们看不出他们对下面这个真理有丝毫的了解：帝国主义同目前形式的资本主义有不可分割的联系，所以〈！！〉同帝国主义作直接的斗争是没有希望的，除非仅限于反对某些特别可恶的过火现象。”因为用改良主义的方法修改帝国主义的基础不过是一种欺骗，是一种“天真的愿望”，因为被压迫民族的资产阶级代表没有“继续”前进，所以压迫民族的资产阶级代表就“继续”后退了，后退到在标榜“科学性”的幌子下向帝国主义卑躬屈膝的地步。这也是一种“逻辑”！","language":"中文","translation":false},{"id":"imperialism-1-380","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":380,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"能不能用改良主义的方法改变帝国主义的基础？是前进，去进一步加剧和加深帝国主义所产生的种种矛盾呢，还是后退，去缓和这些矛盾？这些问题是对帝国主义批评的根本问题。帝国主义在政治上的特点，是由金融寡头的压迫和自由竞争的消除引起的全面的反动和民族压迫的加强，所以在20世纪初期，几乎在所有帝国主义国家中都出现了反对帝国主义的小资产阶级民主派反对派。考茨基以及考茨基主义这一广泛的国际思潮背离马克思主义的地方，就在于考茨基不仅没有设法、没有能够使自己同这个经济上根本反动的小资产阶级改良主义反对派对立起来，反而在实践上和它同流合污。","language":"中文","translation":false},{"id":"imperialism-1-381","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":381,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1898年对西班牙的帝国主义战争，在美国引起了“反帝国主义者”，即资产阶级民主派的最后的莫希干人的反对。他们把这次战争叫作“罪恶的”战争，认为兼并别国土地是违背宪法的，认为对菲律宾土著人领袖阿奎纳多的行为是“沙文主义者的欺骗”（先答应阿奎纳多给菲律宾以自由，后来又派美国军队登陆，兼并了菲律宾），并且引用了林肯的话：“白人自己治理自己是自治；白人自己治理自己同时又治理别人，就不是自治而是专制。”但是，既然这全部批评都不敢承认帝国主义同托拉斯、也就是同资本主义的基础有不可分割的联系，不敢同大资本主义及其发展所造成的力量站在一起，那么这种批评就始终是一种“天真的愿望”。","language":"中文","translation":false},{"id":"imperialism-1-382","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":382,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"霍布森批评帝国主义的时候所采取的基本立场也是如此。霍布森否认“帝国主义的不可避免性”，呼吁必须“提高”居民的“消费能力”（在资本主义制度下！），比考茨基还早。用小资产阶级的观点批评帝国主义，批评银行支配一切，批评金融寡头等等的，还有我们屡次引用过的阿加德、阿·兰斯堡、路·埃施韦格，在法国作家中有《英国与帝国主义》这本肤浅的书(1900年出版〉的作者维克多·贝拉尔。所有这些人丝毫不想冒充马克思主义者，他们用自由竞争和民主来反对帝国主义，谴责势必引起冲突和战争的建筑巴格达铁路的计划，表示了维护和平的“天真的愿望”等等。最后还有从事国际证券发行统计的阿·奈马尔克，他在1912年计算出“国际”有价证券数达几千亿法郎的时候，不禁叫了起来：“难道可以设想和平会受到破坏吗？……有了这样大的数字，还会去冒险挑起战争吗？”","language":"中文","translation":false},{"id":"imperialism-1-383","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":383,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"资产阶级经济学家这样天真，倒没有什么奇怪，而且他们显得这样天真，“郑重其事地”谈论帝国主义制度下的和平，对他们反而是有利的。可是考茨基在1914年、1915年、1916年也采取了这种资产阶级改良主义的观点，硬说在和平问题上，“大家〈帝国主义者、所谓社会党人和社会和平主义者〉意见都是一致的”，试问他还有一点马克思主义的气味吗？这不是分析和揭露帝国主义矛盾的深刻性，而不过是抱着一种改良主义的“天真的愿望”，想撇开这些矛盾，回避这些矛盾。","language":"中文","translation":false},{"id":"imperialism-1-384","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":384,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"下面是考茨基从经济上对帝国主义进行批评的典型例子。他举出1872年和1912年英国对埃及进出口的统计材料，看到这方面的进出口额比英国总的进出口额增长得慢。于是考茨基得出结论说：“我们没有任何根据认为，不用武力占领埃及而依靠单纯的经济因素的作用，英国同埃及的贸易就会增长得慢些。”“资本扩张的意图”“不通过帝国主义的暴力方法，而通过和平的民主能够实现得最好 ”。","language":"中文","translation":false},{"id":"imperialism-1-385","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":385,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基的这个论断，被他的俄国随从（也是俄国的一个为社会沙文主义者打掩护的人）斯佩克塔托尔先生用各种各样的调子重弹过的论断，是考茨基主义对帝国主义的批评的基础，所以我们必须较详细地谈一谈。我们从引证希法亭的言论开始，因为考茨基曾经多次（包括1915年4月那次在内）声称，希法亭的结论是 “所有社会党人理论家一致同意的;”。","language":"中文","translation":false},{"id":"imperialism-1-386","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":386,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"希法亭写道：“无产阶级不应当用自由贸易时代的和敌视国家的那种已经落后的政策去反对向前发展了的资本主义政策。无产阶级对金融资本的经济政策的回答，对帝国主义的回答，不可能是贸易自由，而只能是社会主义。现在无产阶级政策的目的不可能是恢复自由竞争这样的理想（这种理想现在已经变成反动的理想了），而只能是通过消除资本主义来彻底消灭竞争。”","language":"中文","translation":false},{"id":"imperialism-1-387","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":387,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基维护对金融资本时代来说是“反动的理想”，维护“和平的民主”和“单纯的经济因素的作用”，从而背离了马克思主义，因为这个理想在客观上是开倒车，是从垄断资本主义倒退到非垄断资本主义，是一种改良主义的骗局。","language":"中文","translation":false},{"id":"imperialism-1-388","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":388,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"如果不用武力占领，如果没有帝国主义，没有金融资本，那么英国同埃及（或者同其它殖民地或半殖民地）的贸易“就会增长得”快些。这是什么意思？这是不是说，如果自由竞争没有受到任何垄断的限制，没有受到金融资本的 “联系”或压迫（这也是垄断）的限制，没有受到某些国家垄断地占有殖民地的限制，那么资本主义就会发展得快些呢？","language":"中文","translation":false},{"id":"imperialism-1-389","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":389,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基的论断不可能有别的意思，而这个“意思”却是毫无意思的。就假定会这样，如果没有任何垄断，自由竞争会使资本主义和贸易发展得更快些。但是，要知道贸易和资本主义发展得愈快，产生垄断的生产和资本的集中就愈是加强。况且垄断已经产生了，恰好是从自由竞争中产生出来的！即使现在垄断开始延缓发展，这也不能成为主张自由竞争的论据，因为在产生垄断以后自由竞争就不可能了。","language":"中文","translation":false},{"id":"imperialism-1-390","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":390,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"不管你怎样把考茨基的论断翻来复去地看，这里面除了反动性和资产阶级改良主义以外，没有任何别的东西。","language":"中文","translation":false},{"id":"imperialism-1-391","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":391,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"即使把这种论断修改一下，象斯佩克塔托尔说的那样，现在英属殖民地同英国的贸易，比英属殖民地同其它国家的贸易发展得慢些，——这也挽救不了考茨基。因为打击英国的也是垄断，也是帝国主义，不过是其它国家的（美国的、德国的）垄断和帝国主义。大家知道，卡特尔导致了一种新型的、独特的保护关税，它所保护的（这一点恩格斯在《资本论》第3卷上就已经指出来了）恰好是那些可供出口的物品。其次，大家知道，卡特尔和金融资本有一套 “按倾销价格输出”的做法，也就是英国人所说的 “抛售”的做法：卡特尔在国内按垄断的高价出卖产品，而在国外却按极低廉的价格销售，以便打倒自己的竞争者，把自己的生产扩大到最大限度等等。即使同英属殖民地的贸易，德国比英国发展得快些，那也只能证明德国帝国主义比英国帝国主义更新、更强大、更有组织、水平更高，而决不能证明自由贸易的 “优越”，因为这里并不是自由贸易同保护主义或殖民地附属关系作斗争，而是一个帝国主义同另一个帝国主义、一个垄断组织同另一个垄断组织、一个金融资本同另一个金融资本作斗争。德国帝国主义对英国帝国主义的优势，比殖民地疆界的屏障或保护关税的壁垒更厉害。如果由此得出主张自由贸易与 “和平的民主”的 “论据”，那是庸俗的，是忘掉帝国主义的基本特点和特性，是用小市民的改良主义来代替马克思主义。","language":"中文","translation":false},{"id":"imperialism-1-392","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":392,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"有趣的是，甚至资产阶级经济学家阿·兰斯堡，虽然也同考茨基一样对帝国主义作了小市民式的批评，但是他对贸易统计材料毕竟作了比较科学的整理。他并不是随便拿一个国家，也不是单拿一个殖民地来同其余国家比较，而是拿一个帝国主义国家的两种输出作比较：第一种是对在金融上依附于它、向它借钱的国家的输出，第二种是对在金融上独立的国家的输出。结果如下：","language":"中文","translation":false},{"id":"imperialism-1-393","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":393,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国的输出(单位百万马克)","language":"中文","translation":false},{"id":"imperialism-1-394","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":394,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"1889年 1908年 增加的百分数","language":"中文","translation":false},{"id":"imperialism-1-395","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":395,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"对在金融上依附于德国的国家的输出","language":"中文","translation":false},{"id":"imperialism-1-396","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":396,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"罗马尼亚 48.2 70.8 ＋47%","language":"中文","translation":false},{"id":"imperialism-1-397","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":397,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"葡萄牙 19.0 32.8 ＋73%","language":"中文","translation":false},{"id":"imperialism-1-398","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":398,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"阿根廷 60.7 147.0 ＋143%","language":"中文","translation":false},{"id":"imperialism-1-399","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":399,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"巴 西 48.7 84.5 ＋73%","language":"中文","translation":false},{"id":"imperialism-1-400","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":400,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"智 利 28.3 52.4 ＋85%","language":"中文","translation":false},{"id":"imperialism-1-401","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":401,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"土耳其 29.9 64.0 ＋114%","language":"中文","translation":false},{"id":"imperialism-1-402","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":402,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"·总 ·计 234.8 451.5 ＋92%","language":"中文","translation":false},{"id":"imperialism-1-403","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":403,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"对在金融上不依附于德国的国家的输出","language":"中文","translation":false},{"id":"imperialism-1-404","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":404,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"大不列颠 651.8 997.4 ＋53%","language":"中文","translation":false},{"id":"imperialism-1-405","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":405,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"法 国 210.2 437.9 ＋108%","language":"中文","translation":false},{"id":"imperialism-1-406","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":406,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"比利时 137.2 322.8 ＋135%","language":"中文","translation":false},{"id":"imperialism-1-407","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":407,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"瑞 士 177.4 401.1 ＋127%","language":"中文","translation":false},{"id":"imperialism-1-408","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":408,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"澳大利亚 21.2 64.5 ＋205%","language":"中文","translation":false},{"id":"imperialism-1-409","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":409,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"荷属印度 8.8 40.7 ＋363%","language":"中文","translation":false},{"id":"imperialism-1-410","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":410,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"·总 ·计 1206.6 2264.4 ＋87%","language":"中文","translation":false},{"id":"imperialism-1-411","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":411,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"兰斯堡没有作总结，所以他令人奇怪地没有察觉：如果这些数字能够证明什么的话，那只能证明他自己不对，因为对在金融上不独立的国家的输出，毕竟要比对在金融上独立的国家的输出增加得快些，虽然快得并不多(我们把“如果”两字加上着重标记，是因为兰斯堡的统计还是很不完全的）。","language":"中文","translation":false},{"id":"imperialism-1-412","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":412,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"兰斯堡在考察输出和贷款的关系时写道：","language":"中文","translation":false},{"id":"imperialism-1-413","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":413,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“在1890-91年度，罗马尼亚通过几家德国银行签订了一项债约。其实在前几年，这些德国银行就已经在提供这笔贷款了。这笔贷款主要是用来向德国购买铁路材料的。1891年德国对罗马尼亚的输出是5500万马克。下一年就降到3940万马克；以后断断续续地下降，到1900年一直降到2540万马克。直到最近几年，因为有了两笔新的贷款，才又达到了1891年的水平。德国对葡萄牙的输出，由于1888-89年度的贷款而增加到2110万马克(1890年），在以后两年内，又降到1620万马克和740万马克，直到1903年才达到原先的水平。","language":"中文","translation":false},{"id":"imperialism-1-414","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":414,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国同阿根廷贸易的材料更为明显。由于1888年和1890年的两次贷款，德国对阿根廷的输出在1889年达到了6070万马克。两年后，输出只有1860万马克，还不到过去的1/3。直到1901年，才达到并超过1889年的水平，这是同发行新的国家债券和市政债券，同出资兴建电力厂以及其它信贷业务有关的。","language":"中文","translation":false},{"id":"imperialism-1-415","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":415,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国对智利的输出，由于1889年的贷款，增加到4520万马克(1892年），一年后降到了2250万马克。1906年通过德国几家银行签订了一项新的债约以后，输出又增加到8470万马克(1907年），而到1908年又降到了5240万马克。”","language":"中文","translation":false},{"id":"imperialism-1-416","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":416,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"兰斯堡从这些事实中得出了一种可笑的小市民说教：同贷款相联系的输出是多么不稳定、不均衡；把资本输出国外而不用来 “自然地”、 “和谐地”发展本国工业，是多么不好；办理外国债券时，克虏伯要付出几百万的酬金，代价是多么 “巨大”，等等。","language":"中文","translation":false},{"id":"imperialism-1-417","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":417,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"但是事实清楚地说明：输出的增加，恰好是同金融资本的骗人勾当相联系的，金融资本并不关心什么资产阶级的说教，它要从一头牛身上剥下两张皮来：第一张皮是从贷款取得的利润，第二张皮是在同一笔贷款被用来购买克虏伯的产品或钢铁辛迪加的铁路材料等等时取得的利润。","language":"中文","translation":false},{"id":"imperialism-1-418","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":418,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"再说一遍，我们决不认为兰斯堡的统计是完备的，但是必须加以引用，因为它比考茨基和斯佩克塔托尔的统计科学一些，因为兰斯堡提供了对待问题的正确方法。要议论金融资本在输出等等方面的作用，就要善于着重地、专门地说明输出同金融家骗人勾当的联系，同卡特尔产品的销售等等的联系。简单地拿殖民地同非殖民地比较，拿一个帝国主义同另一个帝国主义比较，拿一个半殖民地或殖民地（如埃及）同其余一切国家比较，那就正是回避和掩饰问题的实质。","language":"中文","translation":false},{"id":"imperialism-1-419","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":419,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基在理论上对帝国主义进行的批评，其所以同马克思主义毫无共同之点，其所以只能用来鼓吹同机会主义者和社会沙文主义者保持和平和统一，就是因为这种批评恰恰回避和掩饰了帝国主义最深刻、最根本的矛盾：垄断同与之并存的自由竞争的矛盾，金融资本的庞大 “业务”（以及巨额利润）同自由市场上 “诚实的”买卖的矛盾，卡特尔、托拉斯同没有卡特尔化的工业的矛盾等等。","language":"中文","translation":false},{"id":"imperialism-1-420","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":420,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基胡诌出来的那个臭名昭著的“超帝国主义”论，也具有完全相同的反动性质。请把考茨基在1915年关于这个问题的论断同霍布森在1902年的论断比较一下。","language":"中文","translation":false},{"id":"imperialism-1-421","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":421,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基说：“……现在的帝国主义的政策会不会被一种新的超帝国主义的政策所取代，这种新的超帝国主义的政策，将以实行国际联合的金融资本共同剥削世界来代替各国金融资本的相互斗争。不管怎样，资本主义的这样一个新阶段是可以设想的。至于它能否实现，现在还没有足够的前提对此作出判断。”","language":"中文","translation":false},{"id":"imperialism-1-422","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":422,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"霍布森说：“基督教在各自占有若干未开化的属地的少数大联邦帝国里已经根深蒂固了，很多人觉得基督教正是现代趋势的最合理的发展，并且是这样一种发展，它最有希望在国际帝国主义的巩固的基础上达到永久的和平。”","language":"中文","translation":false},{"id":"imperialism-1-423","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":423,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"被考茨基叫作超帝国主义的东西，也就是霍布森比他早13年叫作国际帝国主义的那个东西。除了用一个拉丁语词头代替另一个词头，编造出一个深奥的新词以外，考茨基的“科学”见解的唯一的进步，就是企图把霍布森所描写的东西，实质上是英国牧师的伪善言词，冒充为马克思主义。在英布战争以后，英国牧师这一高贵等级把主要力量用来安慰那些在南部非洲作战丧失了不少生命，并且为保证英国金融家有更高的利润而交纳了更高捐税的英国小市民和工人，这本来是很自然的。除了说帝国主义并不那么坏，说它很快就要成为能够保障永久和平的国际（或超）帝国主义，还能有什么更好的安慰呢？不管英国的牧师或甜蜜的考茨基抱着什么样的善良意图，考茨基的 “理论”的客观即真正的社会意义只有一个，就是拿资本主义制度下可能达到永久和平的希望，对群众进行最反动的安慰，其方法就是使人们不去注意现代的尖锐矛盾和尖锐问题，而去注意某种所谓新的将来的 “超帝国主义”的虚假前途。在考茨基的 “马克思主义”理论里，除了对群众的欺骗以外，没有任何别的东西。","language":"中文","translation":false},{"id":"imperialism-1-424","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":424,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"其实只要同那些人人皆知的不容争辩的事实好好对比一下，就会清楚地知道，考茨基硬要德国工人（和各国工人）相信的那种前途是多么虚假。拿印度、印度支那和中国来说吧。谁都知道，这三个共有6-7亿人口的殖民地和半殖民地的国家，是受英、法、日、美等几个帝国主义大国的金融资本剥削的。假定这些帝国主义国家组成了几个彼此敌对的联盟，以保持或扩大它们在上述亚洲国家中的领地、利益和“势力范围”，这将是一些“国际帝国主义的”或“超帝国主义的”联盟。假定所有帝国主义大国组成一个联盟来“和平”瓜分上述亚洲国家，这将是一种 “实行国际联合的金融资本”。在20世纪的历史上就有这种联盟的实际例子，如列强共同对付中国就是这样。试问，在保存着资本主义的条件下（考茨基正是以这样的条件为前提的），“可以设想”这些联盟不是暂时的联盟吗？“可以设想”这些联盟会消除各种各样的摩擦、冲突和斗争吗？","language":"中文","translation":false},{"id":"imperialism-1-425","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":425,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"只要明确地提出问题，就不能不给以否定的回答。因为在资本主义制度下，瓜分势力范围、利益和殖民地等等，除了以瓜分者的实力，也就是以整个经济、金融、军事等等的实力为根据外，不可能设想有其它的根据。而这些瓜分者的实力的变化又各不相同，因为在资本主义制度下，各个企业、各个托拉斯、各个工业部门、各个国家的发展不可能是平衡的。如果拿半个世纪以前德国的资本主义实力同当时英国的实力相比，那时德国还小得可怜；日本同俄国相比，也是如此。是否“可以设想”一二十年之后，帝国主义大国的实力对比依然没有变化呢？绝对不可以。","language":"中文","translation":false},{"id":"imperialism-1-426","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":426,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"所以，资本主义现实中的（而不是英国牧师或德国“马克思主义者”考茨基的庸俗的小市民幻想中的）“国际帝国主义的”或“超帝国主义的”联盟，不管形式如何，不管是一个帝国主义联盟去反对另一个帝国主义联盟，还是所有帝国主义大国结成一个总联盟，都不可避免地只会是两次战争之间的“喘息”。和平的联盟准备着战争，同时它又是从战争中生长出来的，两者互相制约，在世界经济和世界政治的帝国主义联系和相互关系这个同一基础上，形成和平斗争形式与非和平斗争形式的彼此交替。聪明绝顶的考茨基为了安定工人，使他们同投到资产阶级方面去的社会沙文主义者调和，就把一条链子上的这一环节同另一环节割开，把今天所有大国为了“安定”中国（请回忆一下对义和团起义的镇压）而结成的和平的（而且是超帝国主义的，甚至是超而又超的帝国主义的）联盟，同明天的、非和平的冲突割开，而这种非和平的冲突，又准备着后天“和平的”总联盟来瓜分譬如说土耳其，如此等等。考茨基不提帝国主义和平时期同帝国主义战争时期之间的活生生的联系，而把僵死的抽象概念献给工人，是为了使工人同他们那些僵死的领袖调和。","language":"中文","translation":false},{"id":"imperialism-1-427","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":427,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"美国人希尔在他的《欧洲国际关系发展中的外交史》一书序言中，把现代外交史分为以下几个时期：(1)革命时代；(2)立宪运动；(3)当今的“商业帝国主义”时代。另一个作家则把1870年以来的大不列颠“世界政策”史分为四个时期：(1)第一个亚洲时期（反对俄国在中亚朝印度方向扩张）；(2)非洲时期（大约在1885-1902年），为了瓜分非洲而同法国斗争(1898年的“法索达”事件，——差一点同法国作战）；(3)第二个亚洲时期（与日本缔约反对俄国）；(4)“欧洲”时期，主要是反对德国。早在1905年，银行“活动家”里塞尔就说过：“政治前哨战是在金融的基础上开展起来的。”他指出，法国金融资本在意大利进行活动，为法意两国的政治联盟作了准备；德英两国为了争夺波斯以及所有欧洲国家的资本为了贷款给中国而展开了斗争，等等。这就是“超帝国主义的”和平联盟同普通帝国主义的冲突有不可分割的联系的活生生的现实。","language":"中文","translation":false},{"id":"imperialism-1-428","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":428,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基掩盖帝国主义的最深刻的矛盾，就必然会美化帝国主义，这在他对帝国主义政治特性的批评中也表现出来了。帝国主义是金融资本和垄断组织的时代，金融资本和垄断组织到处都带有统治的趋向而不是自由的趋向。这种趋势的结果，就是在一切政治制度下都发生全面的反动，这方面的矛盾也极端尖锐化。民族压迫、兼并的趋向即破坏民族独立的趋向（因为兼并正是破坏民族自决）也变本加厉了。希法亭很正确地指出了帝国主义和民族压迫加剧之间的联系，他写道：“在新开辟的地区，输入的资本加深了各种矛盾，引起那些有了民族自觉的人民对外来者的愈来愈强烈的反抗；这种反抗很容易发展成为反对外国资本的危险行动。旧的社会关系发生了根本的变革，各‘史外民族’千年来的农村闭塞状态日益被破坏，他们正被卷到资本主义的漩涡中去。资本主义本身在逐渐地为被征服者提供解放的手段和方法。于是他们也就提出了欧洲民族曾经认为是至高无上的目标：建立统一的民族国家，作为争取经济自由和文化自由的手段。这种独立运动，使欧洲资本在它那些最有价值的、最有光辉前途的经营地区受到威胁；因此，欧洲资本只有不断地增加自己的兵力，才能维持自己的统治。”","language":"中文","translation":false},{"id":"imperialism-1-429","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":429,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"对此还要补充的是，帝国主义不仅在新开辟的地区，而且在原有地区也实行兼并，加紧民族压迫，因而也使反抗加剧起来。考茨基表示反对帝国主义加强政治上的反动，然而他不去说明在帝国主义时代决不能同机会主义者统一这个变得十分迫切的问题。他表示反对兼并，然而采取的却是毫不触犯机会主义者、最容易为机会主义者接受的方式。他是直接对德国听众说话的，然而他恰恰把最重要、最有现实意义的事实，例如德国兼并阿尔萨斯-洛林的事实掩盖起来。为了评价考茨基的这种“思想倾向”，我们来举一个例子。假定日本人指责美国人兼并菲律宾，试问会不会有很多人相信这是因为他根本反对兼并，而不是因为他自己想要兼并菲律宾呢？是不是应当承认，只有日本人起来反对日本兼并朝鲜，要求朝鲜有从日本分离的自由，才能认为这种反对兼并的“斗争”是真挚的，政治上是诚实的呢？","language":"中文","translation":false},{"id":"imperialism-1-430","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":430,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"考茨基对帝国主义的理论分析，以及他在经济上和政治上对帝国主义的批评，都始终贯穿着一种同马克思主义绝不兼容的、掩饰和缓和最根本矛盾的精神，一种尽力把欧洲工人运动中同机会主义的正在破裂的统一保持下去的意图。","language":"中文","translation":false},{"id":"imperialism-1-431","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":431,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"我们已经看到，帝国主义就其经济实质来说，是垄断资本主义。这就决定了帝国主义的历史地位，因为在自由竞争的基础上、而且正是从自由竞争中生长起来的垄断，是从资本主义社会经济结构向更高级的结构的过渡。必须特别指出能够说明我们研究的这个时代的垄断的四种主要形式，或垄断资本主义的四种主要表现。","language":"中文","translation":false},{"id":"imperialism-1-432","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":432,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"第一，垄断是从发展到很高阶段的生产集中生长起来的。这指的是资本家的垄断同盟卡特尔、辛迪加、托拉斯。我们看到，这些垄断同盟在现代经济生活中起着多么大的作用。到20世纪初，它们已经在各先进国家取得了完全的优势。如果说，最先走上卡特尔化道路的，是那些实行高额保护关税制的国家（德国和美国），那么实行自由贸易制的英国也同样表明了垄断由生产集中产生这个基本事实，不过稍微迟一点罢了。","language":"中文","translation":false},{"id":"imperialism-1-433","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":433,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"第二，垄断导致加紧抢占最重要的原料产地，尤其是资本主义社会的基础工业部门，即卡特尔化程度最高的工业部门，如煤炭工业和钢铁工业所需要的原料产地。垄断地占有最重要的原料产地，大大加强了大资本的权力，加剧了卡特尔化的工业和没有卡特尔化的工业之间的矛盾。","language":"中文","translation":false},{"id":"imperialism-1-434","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":434,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"第三，垄断是从银行生长起来的。银行已经由普通的中介企业变成了金融资本的垄断者。在任何一个最先进的资本主义国家中，为数不过三五家的最大银行实行工业资本同银行资本的“人事结合”，集中支配着占全国资本和货币收入很大部分的几十亿几十亿资金。金融寡头给现代资产阶级社会中所有一切经济机构和政治机构罩上了一层依附关系的密网，——这就是这种垄断的最突出的表现。","language":"中文","translation":false},{"id":"imperialism-1-435","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":435,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"第四，垄断是从殖民政策生长起来的。在殖民政策的无数“旧的”动机以外，金融资本又增加了争夺原料产地、争夺资本输出、争夺“势力范围”（即进行有利的交易、取得租让、取得垄断利润等等的范围）直到争夺一般经济领土的动机。例如，当欧洲大国在非洲的殖民地占非洲面积十分之一的时候（那还是1876年的情况），殖民政策可以用非垄断的方式，用所谓“自由占领”土地的方式发展。但是，当非洲十分之九的面积已经被占领（到1900年时）、全世界已经瓜分完毕的时候，一个垄断地占有殖民地、因而使瓜分世界和重新瓜分世界的斗争特别尖锐起来的时代就不可避免地到来了。","language":"中文","translation":false},{"id":"imperialism-1-436","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":436,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"垄断资本主义使资本主义的一切矛盾尖锐到什么程度，这是大家都知道的。只要指出物价高涨和卡特尔的压迫就够了。这种矛盾的尖锐化，是从全世界金融资本取得最终胜利时开始的过渡历史时期的最强大的动力。","language":"中文","translation":false},{"id":"imperialism-1-437","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":437,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"垄断，寡头统治，统治趋向代替了自由趋向，极少数最富强的国家剥削愈来愈多的弱小国家，——这一切产生了帝国主义的这样一些特点，这些特点使人必须说帝国主义是寄生的或腐朽的资本主义。帝国主义的趋势之一，即形成为“食利国”、高利贷国的趋势愈来愈显着，这种国家的资产阶级愈来愈依靠输出资本和“剪息票”为生。如果以为这一腐朽趋势排除了资本主义的迅速发展，那就错了。不，在帝国主义时代，某些工业部门，某些资产阶级阶层，某些国家，不同程度地时而表现出这种趋势，时而又表现出那种趋势。整个说来，资本主义的发展比从前要快得多，但是这种发展不仅一般地更不平衡了，而且这种不平衡还特别表现在某些资本最雄厚的国家（英国）的腐朽上面。","language":"中文","translation":false},{"id":"imperialism-1-438","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":438,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"论述德国大银行的那本着作的作者里塞尔谈到德国经济发展的速度时说：“德国前一个时代(1848-1870年）的进步并不太慢，但是同德国现时代(1870-1905年）整个经济特别是银行业发展的速度比起来，就好象拿旧时邮车的速度同现代汽车的速度相比一样；现代汽车行驶之快，对于不小心的行人和坐汽车的人都是很危险的。”这个已经异常迅速地生长起来的金融资本，正因为生长得这样迅速，所以它不反对转向比较“安稳地”占有殖民地，而这些殖民地是要用不单是和平的手段从更富有的国家手里夺取的。美国近几十年来经济的发展比德国还要快，正因为如此，最新的美国资本主义的寄生性特征就表现得特别鲜明。另一方面，就拿共和派的美国资产阶级同君主派的日本或德国的资产阶级作比较，也可以看出：在帝国主义时代，它们之间极大的政治差别大大减弱了，这倒不是因为这种差别根本不重要，而是因为在所有这些场合谈的都是具有明显寄生性特征的资产阶级。","language":"中文","translation":false},{"id":"imperialism-1-439","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":439,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"许多任务业部门中的某一部门、许多国家中的某一国家的资本家获得了垄断高额利润，在经济上就有可能把工人中的某些部分，一时甚至是工人中数量相当可观的少数收买过去，把他们拉到该部门或该国家的资产阶级方面去反对其它一切部门或国家。帝国主义国家因瓜分世界而加剧的对抗，更加强了这种趋向。于是形成了帝国主义同机会主义的联系，这种联系在英国表现得最早而且最鲜明，因为某些帝国主义发展特点的出现，在英国比在其它国家早得多。有些作家，例如尔 ·马尔托夫，爱用一种“官场的乐观主义的”（同考茨基、胡斯曼一样）论断，来回避帝国主义同工人运动中的机会主义相联系这个现在特别引人注目的事实，说什么假如正是先进的资本主义会加强机会主义，或者，假如正是待遇最好的工人倾向于机会主义，那么反对资本主义的人们的事业就会没有希望了，等等。不要看错了这种“乐观主义”的意义：这是对机会主义的乐观主义，这是用来掩护机会主义的乐观主义。其实，机会主义特别迅速和特别可恶的发展，决不能保证机会主义取得巩固的胜利，正象健康的身体上的恶性脓疮的迅速发展，只能加速脓疮破口而使身体恢复健康一样。在这方面最危险的是这样一些人，他们不愿意了解：反对帝国主义的斗争，如果不同反对机会主义的斗争密切联系起来，就是空话和谎言。","language":"中文","translation":false},{"id":"imperialism-1-440","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":440,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"根据以上对帝国主义的经济实质的全部论述可以得出一个结论，即应当说帝国主义是过渡的资本主义，或者更确切些说，是垂死的资本主义。在这一方面特别耐人寻味的是，资产阶级经济学家在描述最新资本主义时也常用“交织”、“不存在孤立状态”等等这样一些说法；他们也说什么银行“就其任务和发展而言，不是带有单纯私有经济性质的企业，而是日益超出单纯私有经济调节范围的企业”。而就是讲这话的里塞尔，却又非常郑重地宣称，马克思主义者关于“社会化”的“预言”“并没有实现”！","language":"中文","translation":false},{"id":"imperialism-1-441","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":441,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"“交织”这个说法说明了什么呢？它只抓住了我们眼前发生的这个过程的最引人注目的一点。它表明观察者只看到一棵棵的树木而看不到森林。它盲目地复写表面的、偶然的、紊乱的现象。它暴露出观察者被原始材料压倒了，完全没有认识这些材料的含义和意义。股票的占有，私有者的关系，都是“偶然交织在一起的”。但是隐藏在这种交织现象底下的，构成这种交织现象的基础的，是正在变化的社会生产关系。既然大企业变得十分庞大，并且根据对大量材料的精确估计，有计划地组织原料的供应，其数量达几千万居民所必需的全部原料的2/3甚至3/4，既然运送这些原料到最便利的生产地点（有时彼此相距数百里数千里）是有步骤地进行的，既然原料的依次加工直到制成许多种成品的所有工序是由一个中心指挥的，既然这些产品分配给数千万数万万的消费者是按照一个计划进行的（在美、德两国，煤油都是由美国煤油托拉斯销售的），那就看得很清楚，摆在我们面前的就是生产的社会化，而决不是单纯的“交织”；私有经济关系和私有制关系已经变成与内容不相适应的外壳了，如果人为地拖延消灭这个外壳的日子，那它就必然要腐烂，——它可能在腐烂状态中保持一个比较长的时期（在机会主义的脓疮迟迟不能治好的最坏情况下），但终究不可避免地要被消灭。","language":"中文","translation":false},{"id":"imperialism-1-442","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":442,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"德国帝国主义的狂热崇拜者舒尔采-格弗尼茨惊叹道：“如果领导德国银行的责任归根到底是落在十来个人身上，那么现在他们的活动对于人民福利说来，就比大多数国务大臣的活动还要重要〈在这里，把银行家、大臣、工业家和食利者“交织”的情形忘掉，是更有利的……〉…… 如果把我们所看到的那些趋势的发展情况彻底想一番，那么结果就会是：一国的货币资本汇集在银行手里；银行又互相联合为卡特尔；一国寻找投资场所的资本都化为有价证券。到那时就会实现圣西门的天才预言：‘现在生产的无政府状态是同经济关系的发展缺乏统一的调节这个事实相适应的，这种状态应当被有组织的生产所代替。指挥生产的将不是那些彼此隔离、互不依赖、不知道人们经济要求的企业家；这种事情将由某种社会机构来办理。有可能从更高的角度去观察广阔的社会经济领域的中央管理委员会，将把这种社会经济调节得有利于全社会，把生产资料交给适当的人运用，尤其是将设法使生产和消费经常处于协调的状态。现在有一种机构已经把某种组织经济工作的活动包括在自己的任务以内了，这种机构就是银行。’我们现在还远远没有实现圣西门的这些预言，但是我们已经走在实现这一预言的道路上：这是和马克思本人所设想的马克思主义不同的马克思主义，不过只是形式上不同。”","language":"中文","translation":false},{"id":"imperialism-1-443","author":"列宁","title":"帝国主义是资本主义的最高阶段","location":"列宁：帝国主义是资本主义的最高阶段（1916年1-6月）","page":1,"paragraph":443,"url":"https://www.marxists.org/chinese/lenin/15.htm","text":"这真是对马克思的一个绝妙的“反驳”，这样就从马克思的精确科学分析倒退到圣西门的猜测上去了，那虽然是天才的猜测，但终究只是猜测而已。","language":"中文","translation":false},{"id":"foundations-1-1","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"中文马克思主义文库 -> 斯大林","language":"中文","translation":false},{"id":"foundations-1-2","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"——在斯维尔德洛夫大学的讲演","language":"中文","translation":false},{"id":"foundations-1-3","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"为纪念列宁而吸收入党的同志们","language":"中文","translation":false},{"id":"foundations-1-4","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义的基础是个很大的题目。要详尽地论述这个题目就得写一整本书，甚至要写好几本书。因此，我的讲演自然就不能详尽地说明列宁主义，至多也只能简要地叙述列宁主义的基础。虽然如此，我认为做这样一个叙述来指出几个为顺利研究列宁主义所必需的基本出发点，还是有益处的。","language":"中文","translation":false},{"id":"foundations-1-5","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"叙述列宁主义的基础并不是叙述列宁的世界观的基础。列宁的世界观和列宁主义的基础按范围来说并不是一回事。列宁是马克思主义者，他的世界观的基础当然也就是马克思主义。但是由此决不能得出结论说，叙述列宁主义应当从叙述马克思主义的基础开始。叙述列宁主义就是叙述列宁在他的著作中所加进马克思主义总宝库的、因而自然和列宁的名字分不开的那些特别的和新的贡献。我在我的讲演中只想从这个意义上来叙述列宁主义的基础。","language":"中文","translation":false},{"id":"foundations-1-6","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"那么，列宁主义是什么呢？","language":"中文","translation":false},{"id":"foundations-1-7","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"有些人说，列宁主义就是马克思主义在俄国环境的特殊条件下的应用。这个定义含有一部分真理，可是它远没有概括全部真理。列宁确实把马克思主义应用到俄国实际情况中，而且应用得十分巧妙。但是，如果列宁主义仅仅是马克思主义在俄国特殊环境中的应用，那么列宁主义就纯粹是一国的而且仅仅是一国的现象，纯粹是俄国的而且仅仅是俄国的现象了。可是我们知道，列宁主义是根源于整个国际发展过程的国际现象，而不仅仅是俄国的现象。正因为如此，我认为这个定义带有片面性。","language":"中文","translation":false},{"id":"foundations-1-8","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"另一些人说，列宁主义是十九世纪四十年代的马克思主义的革命因素的复活，而和四十年代以后的马克思主义不同，据说四十年代以后的马克思主义已经变成温和而不革命的了。如果撇开这种把马克思的学说分为革命部分和温和部分的愚蠢庸俗的见解不说，那就必须承认，即使这个完全不充分、完全不能令人满意的定义也含有一部分真理。这一部分真理就在于列宁确实复活了第二国际机会主义者所埋没的马克思主义的革命内容。但这只是一部分真理。关于列宁主义的全部真理是：列宁主义不仅复活了马克思主义，而且更进一步，在资本主义和无产阶级阶级斗争的新条件下向前发展了马克思主义。","language":"中文","translation":false},{"id":"foundations-1-9","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义是帝国主义和无产阶级革命时代的马克思主义。确切些说，列宁主义是无产阶级革命的理论和策略，特别是无产阶级专政的理论和策略。马克思和恩格斯是处在革命（我们指的是无产阶级革命）以前的时期，那时还没有发达的帝国主义，是训练无产者去进行革命的时期，那时无产阶级革命还不是必不可免的直接实践问题。而马克思和恩格斯的学生列宁却处在发达的帝国主义时期，无产阶级革命开展起来的时期，无产阶级革命已经在一个国家内获得了胜利、打破了资产阶级民主制、开辟了无产阶级民主制纪元即苏维埃纪元的时期。","language":"中文","translation":false},{"id":"foundations-1-10","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，列宁主义是马克思主义的进一步的发展。","language":"中文","translation":false},{"id":"foundations-1-11","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"人们通常都指出列宁主义具有非常战斗、非常革命的性质。这是完全正确的。可是，列宁主义所以具有这个特性，是由于以下两个原因：第一，列宁主义是从无产阶级革命中产生出来的，它不能不具有无产阶级革命的特色；第二，列宁主义是在和第二国际机会主义搏斗中成长和巩固起来的，而和这个机会主义作斗争，向来就是对资本主义进行胜利斗争所必需的先决条件。不要忘记，在马克思恩格斯两人和列宁之间隔着第二国际机会主义独占统治的整个时代，和这个机会主义作无情的斗争不能不是列宁主义的极重要的任务之一。","language":"中文","translation":false},{"id":"foundations-1-12","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义是在帝国主义条件下，即在资本主义的矛盾已经达到极点、无产阶级革命已经成为直接实践的问题、训练工人阶级去进行革命的旧时期已经达到尽头而转变为直接冲击资本主义的新时期的条件下成长和形成的。","language":"中文","translation":false},{"id":"foundations-1-13","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁把帝国主义叫做“垂死的资本主义”。为什么呢？因为帝国主义使资本主义的矛盾达到极端，达到顶点，接着就是革命的开始。在这些矛盾中，最重要的有下列三个。","language":"中文","translation":false},{"id":"foundations-1-14","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一个矛盾是劳动和资本之间的矛盾。帝国主义就是工业国里垄断性的托拉斯和辛迪加、银行和金融寡头拥有极大的势力。和这种极大的势力作斗争，工人阶级通常采用的手段，如工会和合作社、议会政党和议会斗争等等已经完全不够了。或者向资本屈服，依旧过着每况愈下的非人生活；或者拿起新的武器，——这就是帝国主义在千百万无产阶级群众面前提出的问题。帝国主义把工人阶级引向革命。","language":"中文","translation":false},{"id":"foundations-1-15","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二个矛盾是各金融集团之间以及帝国主义列强之间为争夺原料产地、争夺别国领土而发生的矛盾。帝国主义就是向原料产地输出资本，就是为独占这些原料产地而进行疯狂的斗争，就是为重新瓜分已经被瓜分完的世界而进行斗争，就是寻找“阳光下的地盘”（注：“阳光下的地盘”一语引自德意志帝国外交大臣伯·毕洛夫的演说。1897年他在国会中说：“让别的民族去分割大陆和海洋而我们德国人只满足于蓝色天空的时代已经过去了。我们也要为自己要求阳光下的地盘。”）的新起金融集团和列强对死抓住既得赃物不放的老旧金融集团和列强进行特别猛烈的斗争。各资本家集团之间的这种疯狂斗争的特点就在于它包含有帝国主义战争，为夺取别国领土而进行的战争这一不可避免的因素。而这个情况的特点又在于它使帝国主义者彼此削弱，使整个资本主义阵地削弱，使无产阶级革命的时机逼近，使无产阶级革命必然实现。","language":"中文","translation":false},{"id":"foundations-1-16","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第三个矛盾是为数极少的占统治地位的“文明”民族和世界上十多亿殖民地和附属国人民之间的矛盾。帝国主义就是对极广大的殖民地和附属国内十多亿居民施行最无耻的剥削和最残忍的压迫。榨取超额利润就是这种剥削和压迫的目的。可是，帝国主义在剥削这些国家时不得不在那里敷设铁路，设立工厂，建立工商业中心。无产者阶级的出现，本地知识分子的产生，民族意识的觉醒，解放运动的加强，就是这个“政策”的不可避免的结果。所有一切殖民地和附属国内革命运动的加强都明显地证明了这一点。这个情况对于无产阶级所以重要，就因为它根本破坏资本主义的阵地，把殖民地和附属国由帝国主义的后备军变为无产阶级革命的后备军。","language":"中文","translation":false},{"id":"foundations-1-17","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"帝国主义的主要矛盾，使旧的“繁荣的”资本主义变成了垂死的资本主义的那些矛盾，大体上就是这样。","language":"中文","translation":false},{"id":"foundations-1-18","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"十年前爆发的帝国主义战争的意义，也就在于它把所有这些矛盾集合在一起投入天平盘里，因而加速和便利了无产阶级的革命战斗。","language":"中文","translation":false},{"id":"foundations-1-19","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"换句话说，帝国主义不仅使革命成了必不可免的实践问题，而且造成了直接冲击资本主义堡垒的有利条件。","language":"中文","translation":false},{"id":"foundations-1-20","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这就是产生列宁主义的国际环境。","language":"中文","translation":false},{"id":"foundations-1-21","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"有人会向我们说：这一切都不错，但是这和当时并不是而且不可能是典型的帝国主义国家的俄国究竟有什么关系呢？这和首先是在俄国而且为俄国工作的列宁究竟有什么关系呢？为什么正好是俄国成了列宁主义的策源地，成了无产阶级革命的理论和策略的诞生地呢？","language":"中文","translation":false},{"id":"foundations-1-22","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因为俄国当时是帝国主义所有这一切矛盾的集合点。","language":"中文","translation":false},{"id":"foundations-1-23","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因为俄国当时孕育着革命的程度比其他任何国家都大，所以只有俄国才能用革命方法来解决这些矛盾。","language":"中文","translation":false},{"id":"foundations-1-24","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"首先，沙皇俄国是以最残忍最野蛮的形式表现出来的各种压迫——资本主义压迫、殖民地压迫和军事压迫的策源地。谁不知道，在俄国，资本的极大势力和沙皇制度的暴虐、俄罗斯民族主义的侵略性和沙皇制度对非俄罗斯民族的屠杀政策是融合起来了呢？谁不知道，对土耳其、波斯、中国广大地区的剥削和沙皇制度对这些地区的侵占，和侵占领土的战争是融合起来了呢？列宁说得对：沙皇制度是“军事封建帝国主义”。沙皇制度把帝国主义各种最坏的因素集中起来，并使之变本加厉了。","language":"中文","translation":false},{"id":"foundations-1-25","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"其次，沙皇俄国是西方帝国主义最大的后备军，这不仅是说它任凭外国资本自由进入，让外国资本操纵俄国国民经济中象燃料和冶金业这样一些有决定意义的部门，而且是说它能拿出千百万士兵去供西方帝国主义者使用。请回想一下一千四百万俄国军队为了保证英法资本家极高的利润而在帝国主义战线上流血牺牲的事实吧。","language":"中文","translation":false},{"id":"foundations-1-26","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"再其次，沙皇制度不仅是帝国主义在东欧的看门狗，而且是西方帝国主义的代理人，它从巴黎和伦敦、柏林和布鲁塞尔得到借款，而从人民身上榨取几亿卢布来缴付利息。","language":"中文","translation":false},{"id":"foundations-1-27","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"最后，沙皇制度是西方帝国主义在瓜分土耳其、波斯和中国等等勾当中的最忠实的同盟者。谁不知道，帝国主义战争是沙皇政府和协约国帝国主义者联合进行的呢？谁不知道，俄国是这次战争的重要角色呢？","language":"中文","translation":false},{"id":"foundations-1-28","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，沙皇制度的利益就和西方帝国主义的利益交织在一起，终于融合为统一的帝国主义的利益。","language":"中文","translation":false},{"id":"foundations-1-29","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"西方帝国主义在为维持和保存沙皇制度而倾注全力同俄国的革命决一死战之前，它能甘心失掉象旧时沙皇资产阶级俄国这样一个东方强大的支柱，这样一个人力物力的丰富宝库吗？当然不能！","language":"中文","translation":false},{"id":"foundations-1-30","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此应该得出结论：谁想打击沙皇制度，谁也就必然要动手打击帝国主义；谁起义反对沙皇制度，谁也就必须起义反对帝国主义。因为谁要是真想不仅摧毁沙皇制度，而且彻底铲除沙皇制度，那么他推翻沙皇制度也就必须推翻帝国主义。这样，反对沙皇制度的革命就和反对帝国主义的革命，和无产阶级革命接近起来，并且一定要转变为反对帝国主义的革命，转变为无产阶级革命。","language":"中文","translation":false},{"id":"foundations-1-31","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"而且，当时在俄国又掀起了最伟大的人民革命，领导这个革命的是世界上最革命的无产阶级，这个无产阶级又拥有俄国的革命农民这样一个重要的同盟者。这样的革命决不会半途而废，它一胜利就一定要举起反帝国主义的起义旗帜，继续前进，这难道还要证明吗？","language":"中文","translation":false},{"id":"foundations-1-32","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，俄国当时一定要成为帝国主义的各种矛盾的集合点，这不仅因为这些矛盾正是在俄国带有特别丑恶和特别不堪的性质而最容易暴露出来，也不仅因为俄国当时是西方帝国主义的把西方金融资本和东方殖民地联结起来的最重要的支柱，而且因为当时仅仅在俄国才有能够用革命方法来解决帝国主义矛盾的现实力量。","language":"中文","translation":false},{"id":"foundations-1-33","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此应该得出结论：俄国革命不能不成为无产阶级革命，它不能不在一开始发展时就具有国际性质，因而也就不能不震撼世界帝国主义的基础。","language":"中文","translation":false},{"id":"foundations-1-34","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在这样的实际情况下，俄国共产党人能不能把自己的工作局限于俄国革命的狭隘民族范围内呢？当然不能！恰恰相反，当时整个环境，无论是国内环境（深刻的革命危机）或国外环境（战争），都推动他们把自己的工作超出这个范围，把斗争搬到国际舞台上去，割开帝国主义的脓疮，证明资本主义必然崩溃，粉碎社会沙文主义和社会和平主义，最后，推翻本国资本主义并为无产阶级锻炼出新的斗争武器，即无产阶级革命的理论和策略，以促进世界各国无产者推翻资本主义的事业。俄国共产党人不能不这样行动，因为只有在这条道路上才可以指望国际环境发生某种变化，使俄国能够避免资产阶级制度的复辟。","language":"中文","translation":false},{"id":"foundations-1-35","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，俄国成了列宁主义的策源地，俄国共产党人的领袖列宁成了列宁主义的创造者。","language":"中文","translation":false},{"id":"foundations-1-36","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"俄国和列宁的“遭遇”差不多同十九世纪四十年代德国和马克思恩格斯的“遭遇”一样。德国当时孕育着资产阶级革命，正象俄国在二十世纪初期一样。当时马克思在《共产党宣言》上写道：","language":"中文","translation":false},{"id":"foundations-1-37","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“共产党人把自己的主要注意力集中在德国，因为德国正处在资产阶级革命的前夜，因为同十七世纪的英国和十八世纪的法国相比，德国将在整个欧洲文明更进步的条件下，拥有发展得多的无产阶级去实现这个变革，因而德国的资产阶级革命只能是无产阶级革命的直接序幕。”[2]","language":"中文","translation":false},{"id":"foundations-1-38","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"换句话说，当时革命运动的中心移到德国了。","language":"中文","translation":false},{"id":"foundations-1-39","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"几乎用不着怀疑，马克思在上述这段话中所指出的情况，大概正是德国成了科学社会主义的诞生地、德国无产阶级的领袖马克思和恩格斯成了科学社会主义的创造者的原因。","language":"中文","translation":false},{"id":"foundations-1-40","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于二十世纪初期的俄国也必须这样说，而且更必须这样说。这个时期的俄国正处在资产阶级革命的前夜，它应当在欧洲更进步的条件下，具有比十九世纪四十年代的德国（英法更不用说）更发展的无产阶级去实现这个革命；并且一切事实都表明这个革命一定会成为无产阶级革命的酵母和序幕。","language":"中文","translation":false},{"id":"foundations-1-41","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不能认为下面这个事实是偶然的，就是早在1902年，当俄国革命刚刚萌芽的时候，列宁就在他的《怎么办？》一书中写了以下的预言：","language":"中文","translation":false},{"id":"foundations-1-42","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“历史现在向我们〈即俄国马克思主义者。——约·斯大林注〉提出的当前任务，是比其他任何一个国家的无产阶级的一切当前任务都更革命的任务。”","language":"中文","translation":false},{"id":"foundations-1-43","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"……“实现这个任务，即摧毁这个不仅是欧洲的同时也是（我们现在可以这样说）亚洲的反动势力的最强大的堡垒，就会使俄国无产阶级成为国际革命无产阶级的先锋队。”（见“列宁全集”第四版第五卷第三四五页）","language":"中文","translation":false},{"id":"foundations-1-44","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"换句话说，革命运动的中心一定要移到俄国来。","language":"中文","translation":false},{"id":"foundations-1-45","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"大家知道，俄国革命的进程足以证实列宁的这个预言而绰绰有余。","language":"中文","translation":false},{"id":"foundations-1-46","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"既然如此，那么进行过这样的革命和具有这样的无产阶级的国家成了无产阶级革命的理论和策略的诞生地，这又有什么奇怪呢？","language":"中文","translation":false},{"id":"foundations-1-47","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"俄国无产阶级的领袖列宁同时也成了这个理论和策略的创造者以及国际无产阶级的领袖，这又有什么奇怪呢？","language":"中文","translation":false},{"id":"foundations-1-48","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"我在上面已经说过，在马克思恩格斯两人和列宁之间隔着第二国际机会主义占统治的整个时代。为了说得确切起见，我应当补充一下：这里所指的不是机会主义在形式上的统治，而只是机会主义在事实上的统治。在形式上，当时领导第二国际的是“正统的”马克思主义者，是“正统派”，即考茨基等人。可是在事实上，第二国际的基本工作是按照机会主义的路线进行的。机会主义者由于他们那种惯于迁就的小资产阶级天性而迁就了资产阶级，而“正统派”又为了和机会主义者“保持统一”、为了维持“党内和平”而迁就了机会主义者。结果就造成了机会主义占统治的局面，因为资产阶级的政策和“正统派”的政策已经完全结合起来了。","language":"中文","translation":false},{"id":"foundations-1-49","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这是资本主义比较和平发展的时期，即所谓战前的时期。当时帝国主义的那些毁灭性的矛盾还没有十分明显地暴露出来；当时工人的经济罢工和工会还比较“正常地”发展着；当时用选举斗争和议会党团还能收到“令人头晕目眩的”成效；当时人们把合法斗争形式捧到天上，并想用合法手段来“消灭”资本主义，——总而言之，当时第二国际各党养得肥肥胖胖，不愿意认真地想到革命，想到无产阶级专政，想到群众的革命教育。","language":"中文","translation":false},{"id":"foundations-1-50","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"脱离了生动的群众革命斗争并变成陈腐教条的一些自相矛盾的原理和理论片断，代替了完整的革命理论。为了装饰门面，他们当然也记起马克思的理论，但目的是要阉割这个理论中活的革命的灵魂。","language":"中文","translation":false},{"id":"foundations-1-51","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"萎靡的庸俗见解和小气的政客手腕，议会的外交手腕和议会的拉拢行为，代替了革命政策。为了装饰门面，他们当然也通过一些“革命的”决议和口号，但目的是要把这些决议和口号束之高阁。","language":"中文","translation":false},{"id":"foundations-1-52","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不是使党根据本身的错误来接受教育和学习正确的革命策略，而是小心躲避迫切的问题，掩饰和抹杀这些问题。为了装饰门面，他们当然也不反对谈谈迫切而困难的问题，但目的是要用一种“橡皮性的”决议来敷衍了事。","language":"中文","translation":false},{"id":"foundations-1-53","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二国际的面目，它的工作方法，它的武库，就是这样。","language":"中文","translation":false},{"id":"foundations-1-54","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"然而帝国主义战争和无产阶级革命搏斗的新时代已经来临。在金融资本的极大势力面前，旧的斗争方法显然已经不够而无能为力了。","language":"中文","translation":false},{"id":"foundations-1-55","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"当时必须重新审查第二国际的全部工作及其整个工作方法，必须驱除庸俗见解、狭隘观点、政客手腕、叛徒行为、社会沙文主义和社会和平主义。必须检查第二国际的整个武库，抛弃一切生锈的陈腐的东西，锻炼出新式的武器。不做这种预备工作，就根本不能去和资本主义作战。不做这种预备工作，无产阶级在新的革命搏斗面前就会陷于武装不足甚或完全没有武装的危险境地。","language":"中文","translation":false},{"id":"foundations-1-56","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"对第二国际的奥吉亚斯的牛圈（注：据希腊神话传说，奥吉亚斯王有个大牛圈，养牛三千头，三十年未打扫。后来人们用“奥吉亚斯的牛圈”来比喻极其肮脏的地方。）做一番总检查和总清洗这一光荣任务就落到了列宁主义的肩上。","language":"中文","translation":false},{"id":"foundations-1-57","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义的方法就是在这样的环境中产生和锻炼出来的。","language":"中文","translation":false},{"id":"foundations-1-58","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这个方法的要求是什么呢？","language":"中文","translation":false},{"id":"foundations-1-59","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一，要在群众的革命斗争的烈火中，在生动的实践的烈火中检验第二国际的各种理论教条，就是说，要恢复那个被破坏了的理论和实践的统一，消灭理论和实践分离的状态，因为只有这样，才能创立具有革命理论武装的真正无产阶级政党。","language":"中文","translation":false},{"id":"foundations-1-60","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二，要根据第二国际各党的实际行为，根据它们的行动，而不根据它们的口号和决议（它们的口号和决议是不可相信的），来检查第二国际各党的政策，因为只有这样才能获得无产阶级群众的信任并当之无愧。","language":"中文","translation":false},{"id":"foundations-1-61","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第三，要按新的革命的方式，用教育群众和训练群众去进行革命斗争的精神去改造全部党的工作，因为只有这样才能训练群众去进行无产阶级革命。","language":"中文","translation":false},{"id":"foundations-1-62","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第四，要无产阶级政党进行自我批评，要无产阶级政党根据本身的错误来学习和接受教育，因为只有这样，才能培养出党的真正干部和真正领导者。","language":"中文","translation":false},{"id":"foundations-1-63","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义的方法的基础和实质就是这样。","language":"中文","translation":false},{"id":"foundations-1-64","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这个方法是如何实际应用的呢？","language":"中文","translation":false},{"id":"foundations-1-65","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二国际机会主义者有许多理论教条，他们总是反复地搬弄这些教条。现在就拿其中的几个教条来看吧。","language":"中文","translation":false},{"id":"foundations-1-66","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一个教条：关于无产阶级夺取政权的条件。机会主义者硬说：无产阶级本身如果在全国人口中不占多数，就不能而且不应当夺取政权。一点证据也没有，因为无论在理论上或实践上都不可能为这个荒谬的论点辩护。列宁回答第二国际的先生们说：就算是这样吧；可是，如果形成了这样的历史环境（战争、农业危机等等），使虽占人口少数的无产阶级有可能把极大多数劳动群众团结在自己周围，那么，为什么它不应当夺取政权呢？为什么无产阶级不应当利用顺利的国际环境和国内环境来突破资本战线，加速总爆发呢？难道马克思不是在十九世纪五十年代就已经说过，如果当时在德国可以用“再版的农民战争”[3]来支持无产阶级革命，那么德国无产阶级革命的情况就会“很好”了吗？难道不是每个人都知道，当时德国无产者，比如说，和1917年俄国无产者比较起来是更少吗？难道俄国无产阶级革命的实践没有表明，第二国际的英雄们所喜爱的这个教条对于无产阶级是毫无实际意义的吗？群众革命斗争的实践打击和打破了这个陈腐的教条，这难道还不明显吗？","language":"中文","translation":false},{"id":"foundations-1-67","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二个教条：无产阶级如果还没有足够的、成熟的、能够组织国家管理的文化干部和行政干部，就不能保持政权，因此首先必须在资本主义条件下造就这种干部，然后才夺取政权。列宁回答说：就算是这样吧；可是，为什么不能把事情颠倒过来，先夺取政权，为无产阶级的发展造成有利条件，然后一日千里地前进，来提高劳动群众的文化水平，来造就很多工人出身的领导干部和行政干部呢？难道俄国的实践没有表明，在无产阶级政权下，工人出身的领导干部的增长要比在资本政权下迅速百倍和牢靠百倍吗？群众革命斗争的实践也在无情地打碎机会主义者的这个理论教条，这难道还不明显吗？","language":"中文","translation":false},{"id":"foundations-1-68","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第三个教条：政治总罢工的方法是无产阶级不能采用的，因为这种方法既然在理论上没有根据（见恩格斯的批评），在实践上有危险（会破坏国家经济生活的常态，会耗尽工会的基金），它就不能代替无产阶级阶级斗争的主要形式，即议会斗争形式。列宁主义者回答说：好吧；可是，第一，恩格斯当时所批评的并不是任何总罢工，而只是某种总罢工，即无政府主义者为代替无产阶级的政治斗争而提出的无政府主义者的经济总罢工[4]，——这和政治总罢工的方法有何相干呢？第二，什么人和在什么地方证明了议会斗争形式是无产阶级斗争的主要形式呢？革命运动的历史难道不是证明议会斗争仅仅是组织无产阶级的议会外斗争的学校和助力吗？难道不是证明在资本主义制度下，工人运动的基本问题是要用暴力，用无产阶级群众的直接斗争，用他们的总罢工，用他们的起义来解决的吗？第三，关于用政治总罢工的方法来代替议会斗争这个问题是从哪里来的呢？主张政治总罢工的人在什么时候和在什么地方曾经打算用议会外斗争形式来代替议会斗争形式呢？第四，难道俄国革命没有表明，政治总罢工是无产阶级革命的最大的学校，是在冲击资本主义堡垒的前夜动员和组织最广大的无产阶级群众的必不可少的手段吗？——这和那些因为怕破坏经济生活的常态、怕耗尽工会的基金而发出的庸俗怨言有何相干呢？革命斗争的实践也在粉碎机会主义者的这个教条，这难道还不明显吗？","language":"中文","translation":false},{"id":"foundations-1-69","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，列宁说，“革命理论并不是教条”，它“只有同真正群众性的和真正革命的运动的实践密切地联系起来，才能最终形成”〔《幼稚病》[5]〕，因为理论应当服务于实践，因为“理论应当回答实践所提出的问题”（《人民之友》[6]，因为理论应当由实践材料来检验。","language":"中文","translation":false},{"id":"foundations-1-70","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"至于第二国际各党的政治口号和政治决议，只要回忆一下“以战争对付战争”这一口号的历史，就足以了解这些以堂皇的革命口号和决议来掩饰自己的反革命勾当的党的政治实践是如何虚伪和腐败。大家都还记得第二国际在巴塞尔代表大会[7]上举行的堂皇的示威，当时第二国际恐吓帝国主义者说，如果帝国主义者敢于发动战争，那就要遇到可怕的起义；他们提出了“以战争对付战争”的吓人口号。可是过了不久，在战争就要爆发的时候，巴塞尔决议就被束之高阁，而向工人提出了新的口号——为了资本主义祖国的光荣而自相残杀。这一点有谁不记得呢？革命的口号和决议如果不加以实现，是一个钱都不值的，这难道还不明显吗？只要把列宁的变帝国主义战争为国内战争的政策和第二国际在战争时期的叛卖政策比较一下，就可以了解机会主义的政客是如何卑鄙，而列宁主义的方法是如何伟大。","language":"中文","translation":false},{"id":"foundations-1-71","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这里我不能不引证列宁的《无产阶级革命和叛徒考茨基》一书中的一段话，他在这本书中无情地痛斥了第二国际首领卡·考茨基企图不按实际行动去判断党，而按纸上口号和文件去判断党的机会主义态度：","language":"中文","translation":false},{"id":"foundations-1-72","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“考茨基实行典型的市侩庸人政策，以为提出口号就能改变事情……全部资产阶级民主史打破了这种幻想，因为资产阶级民主派为了欺骗人民，过去和现在总是什么‘口号’都提得出来的。问题是要考察他们的诚意，把他们的言论和他们的行动加以比较，不要满足于唯心主义的或骗人的空话，而要彻底找到阶级的现实。”（见“列宁全集”第四版第二十八卷第二六○页）","language":"中文","translation":false},{"id":"foundations-1-73","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"至于第二国际各党害怕自我批评的态度，它们那种竭力掩饰自己的错误、抹杀迫切而困难的问题、用一些只能把生动的思想消磨净尽而使党难于根据本身的错误去接受革命教育的粉饰太平的虚伪词句来掩盖自己的缺点的态度，那就更不用说了。这种态度受到列宁的讥笑和痛斥。列宁在他的《幼稚病》一书中谈到无产阶级政党的自我批评问题时写道：","language":"中文","translation":false},{"id":"foundations-1-74","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“一个政党对自己的错误所抱的态度，就是衡量这个党是否郑重，是否真正履行它对本阶级和劳动群众所负义务的最重要最可靠的尺度之一。公开承认错误，揭露错误的原因，分析产生错误的环境，仔细讨论改正错误的方法，——这才是一个郑重的党的标志，这才是党履行自己的义务，这才是教育和训练阶级，以至于群众。”（见“列宁全集”第四版第三十一卷第三十九页）","language":"中文","translation":false},{"id":"foundations-1-75","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"有些人说：揭露本身的错误和进行自我批评，这对于党是有危险的，因为这会被敌人利用来反对无产阶级政党。列宁认为这种反驳是不郑重的，是完全不正确的。关于这一点，列宁还在1904年，当我们党还幼弱的时候，就在他的《进一步，退两步》一书中说过：","language":"中文","translation":false},{"id":"foundations-1-76","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“他们〈即马克思主义者的敌人。——约·斯大林注〉一看见我们发生争论，就幸灾乐祸，洋洋得意；他们为了自己的目的，当然会竭力断章取义，摘引我这本专门谈论我们党内种种缺点的小册子中的个别词句。可是，俄国社会民主党人已经是久经战斗的了，决不会为这小小的针刺所惊扰，却能够不管这些针刺，继续进行自我批评并无情地揭露自己的缺点，这些缺点是一定会而且必然会随着工人运动的发展而被克服的。”（见“列宁全集”第四版第七卷第一九○页）","language":"中文","translation":false},{"id":"foundations-1-77","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义方法的特征大体上就是这样。","language":"中文","translation":false},{"id":"foundations-1-78","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁的方法的原理，在马克思的学说中基本上已经有了。这个学说，照马克思的话说来，“在本质上是批判的和革命的”[8]。列宁的方法正是从头到尾都贯串了这种批判的和革命的精神的。可是，如果以为列宁的方法仅仅是马克思的方法的恢复，那是不正确的。事实上列宁的方法不仅是马克思的批判的和革命的方法的恢复，不仅是马克思的唯物主义辩证法的恢复，而且是这个方法的具体化和进一步发展。","language":"中文","translation":false},{"id":"foundations-1-79","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于这个题目我来讲三个问题：","language":"中文","translation":false},{"id":"foundations-1-80","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）理论对于无产阶级运动的意义；","language":"中文","translation":false},{"id":"foundations-1-81","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）对自发“论”的批判；","language":"中文","translation":false},{"id":"foundations-1-82","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(1)理论的意义。有些人认为列宁主义是实践重于理论，就是说，列宁主义的主要点是把马克思主义的原理变为事实，是“执行”这些原理，至于理论，列宁主义似乎是很不关心的。大家知道，普列汉诺夫曾经屡次嘲笑列宁对于理论，特别是对于哲学的“不关心”。大家也知道，现在许多列宁主义的实际工作者不很喜欢理论，特别是因为他们由于环境关系而不得不忙于浩繁的实际工作。我必须指出：对列宁和列宁主义所持的这种非常奇怪的见解是完全不正确的，而且是丝毫不符合实际情况的；实际工作者忽视理论的趋向是和列宁主义的全部精神相矛盾的，而且对工作是有很大的危险的。","language":"中文","translation":false},{"id":"foundations-1-83","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"理论是概括起来的各国工人运动的经验。当然，离开革命实践的理论是空洞的理论，而不以革命理论为指南的实践是盲目的实践。可是，理论如果是在和革命实践密切联系中形成的，那么它就能成为工人运动的极伟大的力量；因为理论，而且只有理论，才能使运动具有信心，使它有确定方针的能力，使它能了解周围事变的内部联系；因为理论，而且只有理论，才能使实践不仅了解各阶级在目前如何进行和向哪里行进，而且了解这些阶级在最近的将来会如何行进和向哪里行进。不是别人而正是列宁说过和重复过几十次下面这个著名的原理：","language":"中文","translation":false},{"id":"foundations-1-84","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“没有革命的理论，就不会有革命的运动。”（见“列宁全集”第四版第五卷第三四一页；注：黑体是我用的。——约·斯大林注）","language":"中文","translation":false},{"id":"foundations-1-85","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁比谁都更了解理论的重要意义，特别是对于我们党这样一个党的重要意义，因为我们党负有国际无产阶级的先进战士的作用，因为我们党处于复杂的国内环境和国际环境中。列宁还在1902年预察到我们党的这种特殊作用时，就认为必须指出：","language":"中文","translation":false},{"id":"foundations-1-86","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“只有以先进理论为指南的党，才能实现先进战士的作用。”（同上，第三四二页）","language":"中文","translation":false},{"id":"foundations-1-87","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"几乎用不着证明，现在当列宁的关于我们党的作用的预言已经成为事实的时候，列宁的这个原理具有特别巨大的力量和特别重大的意义。","language":"中文","translation":false},{"id":"foundations-1-88","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"依据唯物主义的哲学，把从恩格斯到列宁这个时期最重要的科学成就概括起来，并从各方面去批判马克思主义者队伍里的反唯物主义的派别，这是一个极重大的任务，而负责完成这个任务的不是别人，正是列宁，——这个事实可以说是列宁高度重视理论的最明显的表现。恩格斯说：“随着自然科学领域中每一个划时代的发现，唯物主义也必然要改变自己的形式。”[9]大家知道，不是别人，正是列宁在他的《唯物主义和经验批判主义》[10]这部杰作中为自己的时代完成了这个任务。大家知道，喜欢嘲笑列宁“不关心”哲学的普列汉诺夫竟不敢认真着手执行这个任务。","language":"中文","translation":false},{"id":"foundations-1-89","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(2)对自发“论”的批判，或关于先锋队在运动中的作用。自发“论”是机会主义的理论，是崇拜工人运动自发性的理论，是实际上否认工人阶级的先锋队即工人阶级政党的领导作用的理论。","language":"中文","translation":false},{"id":"foundations-1-90","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"崇拜自发性的理论坚决反对工人运动的革命性质，反对使工人运动循着反对资本主义基础的路线行进，而主张使工人运动仅仅循着资本主义“可以履行的”“可以接受的”要求的路线行进，完全主张采取“阻力最小的路线”。自发论是工联主义的思想体系。","language":"中文","translation":false},{"id":"foundations-1-91","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"崇拜自发性的理论坚决反对使自发运动带有自觉的和有计划的性质，反对党走在工人阶级的前面，反对党把群众提高到自觉的水平，反对党领导运动，而主张使运动中的自觉因素不致妨碍运动循着自己的道路行进，使党只依从自发运动，做运动的尾巴。自发论是降低自觉因素在运动中的作用的理论，是“尾巴主义”的思想体系，是一切机会主义的逻辑基础。","language":"中文","translation":false},{"id":"foundations-1-92","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"还在俄国第一次革命以前，这个理论就已经登台，而在实际上使它的那些信徒即所谓“经济派”否认俄国有建立独立的工人政党的必要，反对工人阶级进行推翻沙皇制度的革命斗争，鼓吹运动中的工联主义政策，把工人运动完全交给自由资产阶级去领导。","language":"中文","translation":false},{"id":"foundations-1-93","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"旧《火星报》的斗争和列宁在《怎么办？》一书中对“尾巴主义”理论的精彩批判不仅粉碎了所谓“经济主义”，而且还建立了俄国工人阶级真正革命运动的理论基础。","language":"中文","translation":false},{"id":"foundations-1-94","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"当时如果没有这个斗争，就休想在俄国建立独立的工人政党，就休想使这个党在革命中起领导作用。","language":"中文","translation":false},{"id":"foundations-1-95","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，崇拜自发性的理论不仅是俄国的现象。它在第二国际所有的党内都是流行得最广泛的，虽然形式稍有不同。我指的是被第二国际的首领们庸俗化了的所谓“生产力”论，这个理论为一切事物辩护，使所有的人都调和起来，当某些事实已经被大家听厌以后，才指出这些事实并加以解释，而指出以后，就万事大吉。马克思说：唯物主义的理论不能只限于解释世界，它还应当改变世界。[11]可是，考茨基及其同伙却不管这一点，他们宁愿停留在马克思的公式的前半段上。","language":"中文","translation":false},{"id":"foundations-1-96","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"请看应用这个“理论”的许多例子中的一个吧。有人说，在帝国主义战争以前，第二国际各党曾经发表恐吓言论，说如果帝国主义者发动战争，它们就宣布“以战争对付战争”。有人说，在战争就要爆发的时候，这些党却把“以战争对付战争”这个口号束之高阁，而实行了一个相反的口号——“为帝国主义祖国而战”。有人说，这样变更口号的结果，几百万工人牺牲了生命。可是，如果以为这里应该归咎于什么人，这里有什么人叛变了或出卖了工人阶级，那就错了。绝对没有这样的事情！所有这些已经发生的事情都是一定要这样发生的。第一，因为国际是“和平的工具”，而不是战争的工具。第二，因为在当时的那种“生产力水平”下，再没有别的办法可想。“应该归咎于”“生产力”。考茨基先生的“生产力论”正是这样向“我们”解释的。而谁要是不相信这个“理论”，谁就不是马克思主义者。党的作用呢？党在运动中的意义呢？可是，党对于象“生产力水平”这样的决定因素又有什么办法呢？……","language":"中文","translation":false},{"id":"foundations-1-97","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这种假冒马克思主义的例子还可以举出一大堆来。","language":"中文","translation":false},{"id":"foundations-1-98","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"几乎用不着证明，这个以掩盖机会主义的真面目为使命的冒牌“马克思主义”，不过是还在俄国第一次革命前就受到列宁攻击的那个“尾巴主义”理论在欧洲的翻版罢了。","language":"中文","translation":false},{"id":"foundations-1-99","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"几乎用不着证明，打破这种理论上的假冒，是在西方建立真正的革命政党的先决条件。","language":"中文","translation":false},{"id":"foundations-1-100","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(3)无产阶级革命论。列宁主义的无产阶级革命论是从三个基本原理出发的。","language":"中文","translation":false},{"id":"foundations-1-101","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一个原理：金融资本在资本主义先进国内占统治地位；发行有价证券是金融资本的一种主要业务；向原料产地输出资本是帝国主义的基础之一；金融寡头的极大势力是金融资本统治的结果，——所有这些都揭露出垄断资本主义的明显的寄生性，使资本主义的托拉斯和辛迪加的压迫百倍沉重起来，使工人阶级对资本主义基础的愤怒更加增长，把群众引上无产阶级革命这条唯一的生路。（见列宁《帝国主义论》[12]）","language":"中文","translation":false},{"id":"foundations-1-102","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此得出第一个结论：资本主义国家内部的革命危机日益尖锐化，“宗主国”内部的无产阶级战线上的爆发因素日益增长。","language":"中文","translation":false},{"id":"foundations-1-103","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二个原理：加紧向殖民地和附属国输出资本；扩大“势力范围”和殖民地领土，直到占领整个地球；资本主义已经成为极少数“先进”国对地球上大多数居民进行金融奴役和殖民压迫的世界体系，——所有这些，一方面使各个民族的经济和领土变成所谓世界经济的整个链条的各个环节，另一方面又把地球上的居民分裂成两个阵营：一方面是剥削和压迫广大殖民地和附属国的极少数资本主义“先进”国，另一方面是不得不为摆脱帝国主义的压迫而斗争的占极大多数的殖民地和附属国。（见《帝国主义》）","language":"中文","translation":false},{"id":"foundations-1-104","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此得出第二个结论：殖民地国家内的革命危机日益尖锐化，外部的殖民地战线上的反对帝国主义的愤怒因素日益增长。","language":"中文","translation":false},{"id":"foundations-1-105","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第三个原理：独占“势力范围”和殖民地；各资本主义国家发展的不平衡使那些已经抢得领土的国家和那些希望得到自己的“份额”的国家为重新瓜分世界而进行疯狂的斗争；帝国主义的战争是恢复已经被破坏的“均势”的唯一手段，——所有这些都使第三条战线即资本主义国家间的战线紧张起来，因而使帝国主义削弱，并使头两条反帝国主义战线即革命的无产阶级战线和殖民地的解放运动战线易于联合起来。（见《帝国主义》）","language":"中文","translation":false},{"id":"foundations-1-106","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此得出第三个结论：在帝国主义条件下，战争是不可避免的；欧洲的无产阶级革命和东方的殖民地革命必然联合为一条世界革命战线，来反对世界帝国主义战线。","language":"中文","translation":false},{"id":"foundations-1-107","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁把上面一切结论综合为一个总的结论说：“帝国主义是社会主义革命的前夜。”（见“列宁全集”第四版第二十二卷第一七五页；注：黑体是我用的。——约·斯大林注）","language":"中文","translation":false},{"id":"foundations-1-108","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因此，对于无产阶级革命及其性质、范围和深度问题的看法本身也要改变，整个革命的方案，也就随着改变了。","language":"中文","translation":false},{"id":"foundations-1-109","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，通常都是根据某一个国家的经济状况去分析无产阶级革命的前提。现在，这种看法已经不够了。现在必须根据一切国家或多数国家的经济状况，根据世界经济状况来观察这个问题，因为个别国家和个别民族的经济已经不是独立自在的单位，已经变成所谓世界经济的整个链条的各个环节，因为旧的“文明的”资本主义已经转变为帝国主义，而帝国主义是极少数“先进”国对地球上大多数居民进行金融奴役和殖民压迫的世界体系。","language":"中文","translation":false},{"id":"foundations-1-110","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，通常都是说，在个别国家内，或者确切些说，在某一个发达的国家内，是否已经具备无产阶级革命的客观条件。现在，这种观点已经不够了。现在必须说，在世界帝国主义经济这一整体的整个体系中已经具备革命的客观条件；而且，如果整个体系，或者确切些说，因为整个体系已经成熟到发生革命的程度，这个体系中存在着工业不够发达的国家并不能成为革命的不可克服的障碍。","language":"中文","translation":false},{"id":"foundations-1-111","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，通常都是说某一个发达的国家内的无产阶级革命，认为这是个别的独立自在的现象，而以个别的民族的资本战线为敌方。现在，这种观点已经不够了。现在必须说世界无产阶级革命，因为个别的民族的资本战线已经变成所谓世界帝国主义战线的整个链条的各个环节，必须拿世界各国革命运动的总战线来对抗这个世界帝国主义战线。","language":"中文","translation":false},{"id":"foundations-1-112","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，总是把无产阶级革命看做纯粹是某一个国家内部发展的结果。现在，这种观点已经不够了。现在首先应当把无产阶级革命看做帝国主义世界体系中各种矛盾发展的结果，看做世界帝国主义战线的链条在某个国家内破裂的结果。","language":"中文","translation":false},{"id":"foundations-1-113","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"革命将在哪里开始呢？资本战线首先会在哪里，会在哪个国家内被突破呢？","language":"中文","translation":false},{"id":"foundations-1-114","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，通常都这样回答：在工业比较发达的地方，在无产阶级占多数的地方，在文化水平较高的地方，在民主成分较多的地方。","language":"中文","translation":false},{"id":"foundations-1-115","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义的革命论反驳说：不，不一定在工业比较发达等等的地方。资本战线将在帝国主义链条最薄弱的地方被突破，因为无产阶级革命是世界帝国主义战线的链条在其最薄弱的地方破裂的结果；而且开始革命的国家，突破资本战线的国家，也许是资本主义不大发达的国家，而其他资本主义比较发达的国家却仍然留在资本主义范围内。","language":"中文","translation":false},{"id":"foundations-1-116","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在1917年，世界帝国主义战线的链条在俄国比在其他国家薄弱些。这个链条就在这里被突破，而使无产阶级革命得以爆发。为什么呢？因为当时在俄国展开了最伟大的人民革命，领导这个革命的是革命的无产阶级，这个无产阶级又拥有千百万被地主压迫和剥削的农民这样一个重要的同盟者。因为当时在俄国和革命对立的是沙皇制度这样一个极丑恶的帝国主义代表，它没有丝毫威信，并为全体人民所痛恨。虽然当时俄国资本主义不如法国或德国、英国或美国发达，但是帝国主义的链条在俄国却比较薄弱。","language":"中文","translation":false},{"id":"foundations-1-117","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在最近的将来，这个链条将在什么地方被突破呢？还是在它最薄弱的地方。比如说，这个链条可能在印度被突破。为什么呢？因为印度有年轻的战斗的革命无产阶级，而这个无产阶级又拥有民族解放运动这样一个无疑是伟大的和重要的同盟者。因为在印度和革命对立的是外国帝国主义这样一个尽人皆知的敌人，它没有丝毫威信，并为印度全体被压迫被剥削群众所痛恨。","language":"中文","translation":false},{"id":"foundations-1-118","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这个链条也很可能在德国被突破。为什么呢？因为，比如说，在印度发生作用的那些因素，在德国也开始发生作用；同时，印度和德国在发展水平上的巨大差别，当然不能不影响到德国革命的进程和结局。","language":"中文","translation":false},{"id":"foundations-1-119","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“西欧资本主义国家发展到社会主义……不会是经过社会主义在这些国家里平衡‘成熟’，而会是经过一些国家对另一些国家进行剥削，经过对帝国主义战争中第一个战败国家进行剥削，再加上对整个东方进行剥削的道路来完成的。另一方面，正是由于第一次帝国主义战争的影响，东方已经最终加入了革命运动，最终卷入了全世界革命运动的总漩涡。”（见“列宁全集”第四版第三十三卷第四五七页）","language":"中文","translation":false},{"id":"foundations-1-120","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"简单地说：帝国主义战线的链条通常一定要在它最薄弱的环节被突破，但是无论如何不一定要在资本主义比较发达、无产者占百分之多少、农民占百分之多少等等的地方被突破。","language":"中文","translation":false},{"id":"foundations-1-121","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，计算个别国家内无产阶级在人口总数中所占百分数，在解决无产阶级革命问题时已经失去了第二国际的那些不了解帝国主义的、象害怕瘟疫那样害怕革命的书呆子们所喜欢赋予它的特殊意义。","language":"中文","translation":false},{"id":"foundations-1-122","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"其次，第二国际的英雄们曾经断定说（现在仍然断定说）：在资产阶级民主革命和无产阶级革命之间隔着一道鸿沟，或者至少是一座万里长城，使这两个革命之间隔着一个相当长的间断时期，在这个间断时期中，已经获得政权的资产阶级发展资本主义，而无产阶级则积聚力量，准备对资本主义进行“决战”。这个间断时期通常是以好几十年来计算的，甚至更长些。几乎用不着证明，这种万里长城“论”在帝国主义环境中是毫无科学根据的，它只是而且只能是资产阶级反革命欲望的掩蔽物和粉饰品。几乎用不着证明，在孕育着冲突和战争的帝国主义环境中，在“社会主义革命的前夜”的环境中，当“繁荣的”资本主义已经变为“垂死的”资本主义（列宁），而革命运动正在世界各国发展的时候，当帝国主义同包括沙皇制度和农奴制度在内的所有一切反动势力联合起来，因而使一切革命势力，从西方的无产阶级运动到东方的民族解放运动，都必须联合起来的时候，当不和帝国主义作革命斗争就不能推翻封建农奴制残余的时候，——几乎用不着证明，在这种条件下，在一个较为发达的国家内，资产阶级民主革命一定会和无产阶级革命接近，资产阶级民主革命一定会转变为无产阶级革命。俄国革命的历史显然证明了这个原理是正确的和不容争辩的。无怪乎列宁还在1905年，俄国第一次革命的前夜，就在他的《两种策略》一书中把资产阶级民主革命和社会主义革命看做一个链条的两个环节，看做俄国革命规模的一幅完整的图画：","language":"中文","translation":false},{"id":"foundations-1-123","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“无产阶级应当把民主革命进行到底，这就要把农民群众联合到自己方面来，以便用强力打破专制制度的反抗，并麻痹资产阶级的不稳定性。无产阶级应当实现社会主义革命，这就要把居民中的半无产者群众联合到自己方面来，以便用强力打破资产阶级的反抗，并麻痹农民和小资产阶级的不稳定性。这就是无产阶级的任务，而新火星派在他们关于革命规模的一切议论和决议中，却把这些任务看得非常狭隘。”（见“列宁全集”第四版第九卷第八十一页）","language":"中文","translation":false},{"id":"foundations-1-124","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"我且不说列宁的其他较晚的著作，在这些著作中，资产阶级革命转变为无产阶级革命的思想是列宁主义的革命论的基石之一这一点比在《两种策略》中表现得更为明显。有些同志却以为列宁在1916年才产生这种思想，以为列宁在1916年以前还认为俄国革命将停滞在资产阶级的范围内，于是政权也将从无产阶级和农民专政的机关手里转到资产阶级手里，而不是转到无产阶级手里。据说这种论断竟流传到我们共产党的报刊上来了。我必须指出，这种论断是完全不正确的，是完全不合乎实际情况的。","language":"中文","translation":false},{"id":"foundations-1-125","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"我可以引证列宁在党的第三次代表大会（1905年）上的著名演说，他在这篇演说中不是把无产阶级和农民的专政即民主革命的胜利称为“‘秩序’的组织”，而是称为“战争的组织”。（见“列宁全集”第四版第八卷第三五三页）","language":"中文","translation":false},{"id":"foundations-1-126","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"其次，我还可以引证列宁论临时政府（1905年）[13]的几篇著名论文，他在这几篇论文里描述俄国革命的发展前途时向党提出的任务是“力求使俄国革命成为多年的运动，而不是几个月的运动，使这个革命不仅得到执政当局的微小让步，而且要完全推翻这个执政当局”；他在这几篇论文里进一步阐明这个前途并把这个前途和欧洲的革命联系起来时继续写道：","language":"中文","translation":false},{"id":"foundations-1-127","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“如果能做到这一点，那时候……那时候革命的火焰将延烧欧洲；在资产阶级反动势力下备受折磨的欧洲工人也将发动起来，并向我们表明‘该怎么办’；那时候欧洲的革命高潮就会反过来影响俄国，使几年的革命时代变成几十年的革命时代……”。（见“列宁全集”第四版第八卷第二五九页）","language":"中文","translation":false},{"id":"foundations-1-128","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"其次，我还可以引证列宁在1915年11月发表的著名论文，他在这篇论文中写道：","language":"中文","translation":false},{"id":"foundations-1-129","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“无产阶级现在为夺取政权、为建立共和国、为没收土地……为吸收‘非无产阶级的人民群众’参加使资产阶级俄国摆脱军事封建‘帝国主义’（即沙皇制度）的解放运动而斗争，将来还要为此英勇忘我地进行斗争。对于这种使资产阶级俄国从沙皇制度下、从地主的土地权力下获得解放的运动，无产阶级将立即（注：黑体是我用的。——约·斯大林注）加以利用，无产阶级不是用来帮助富裕的农民去反对农业工人，而是用来联合欧洲各国的无产者，完成社会主义革命。”（见“列宁全集”第四版第二十一卷第三八二页至第三八三页）","language":"中文","translation":false},{"id":"foundations-1-130","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"最后，我还可以引证列宁的《无产阶级革命和叛徒考茨基》一书中的一段著名言论，他在这里援引了我们刚才从《两种策略》中引证过的那段关于俄国革命规模的话，而得出如下的结论：","language":"中文","translation":false},{"id":"foundations-1-131","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“结果正同我们所说的一样。革命进程证实了我们的论断是正确的。起初同‘全体’农民一起，反对君主制，反对地主，反对中世纪制度（因此，革命还是资产阶级革命，是资产阶级民主革命）。然后同贫苦农民一起，同半无产阶级一起，同一切被剥削者一起，反对资本主义，包括反对农村的富人、富农和投机者，因此革命变成了社会主义革命。除了无产阶级的准备程度、无产阶级同贫农联合的程度以外，企图在这两个革命中间筑起一道人为的万里长城，就是极端地歪曲马克思主义，把马克思主义庸俗化，用自由主义代替马克思主义。”（见“列宁全集”第四版第二十八卷第二七六页至第二七七页）","language":"中文","translation":false},{"id":"foundations-1-132","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"有人会向我们说，既然如此，为什么列宁和“不断（不间断）革命”的思想作斗争呢？","language":"中文","translation":false},{"id":"foundations-1-133","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因为列宁主张“用尽”农民的革命能力，彻底利用农民的革命毅力，以便彻底消灭沙皇制度，以便过渡到无产阶级革命，而“不断革命”论者却不懂得农民在俄国革命中的重大作用，过低估计农民的革命毅力，过低估计俄国无产阶级领导农民的力量和本领，因而妨碍了把农民从资产阶级影响下解放出来的事业，妨碍了把农民团结在无产阶级周围的事业。","language":"中文","translation":false},{"id":"foundations-1-134","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因为列宁主张以政权转归无产阶级来完成革命事业，而“不断”革命论者却想直接从建立无产阶级政权开始，他们不知道这样做就是闭眼不看象农奴制残余这样的“小事情”，就是不考虑到俄国农民这样的重大力量；他们不知道这样政策只能阻挠把农民争取到无产阶级方面来的事业。","language":"中文","translation":false},{"id":"foundations-1-135","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可见列宁和那些“不断”革命论者作斗争并不是由于不断性问题，因为列宁自己就是主张不断革命的，而是由于他们过低估计了农民这一无产阶级最大后备军的作用，由于他们不懂得无产阶级领导权的思想。","language":"中文","translation":false},{"id":"foundations-1-136","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“不断”革命的思想不能看做是一种新的思想。这种思想最初是马克思于十九世纪四十年代末在他的著名的《告共产主义者同盟书》（1850年）中提出的。我们的“不断论者”正是从这个文件中取得不断革命的思想的。必须注意到，我们的“不断论者”从马克思那里把这个思想拿来以后，就多少改变了这个思想，而一改变了它，就把它“弄坏了”，使它不合实用了。当时需要列宁用老练的手法来纠正这个错误，取得马克思的真正的不断革命的思想，而使它成为自己的革命论的基石之一。","language":"中文","translation":false},{"id":"foundations-1-137","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"请看马克思在他的《告共产主义者同盟书》中列举了他号召共产主义者应当争取的许多革命民主要求以后，关于不断革命的问题是怎样说的：","language":"中文","translation":false},{"id":"foundations-1-138","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“民主主义的小资产者至多也不过是希望实行了上述要求便赶快结束革命，而我们的利益和我们的任务却是要不断地进行革命，直到把一切大大小小的有产阶级的统治都消灭掉，直到无产阶级夺得国家政权，直到无产者的联合不仅在一个国家内而且在世界一切占统治地位的国家内都发展到使这些国家的无产者间的竞争停止，至少是直到那些有决定意义的生产力集中到了无产者手里的时候为止。”[14]","language":"中文","translation":false},{"id":"foundations-1-139","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）马克思根本没有主张直接从建立无产阶级政权来开始十九世纪五十年代的德国革命事业，这和我们俄国的“不断论者”的计划是相反的；","language":"中文","translation":false},{"id":"foundations-1-140","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）马克思只是主张以建立无产阶级国家政权来完成革命事业，一步一步地把资产阶级派别从政权的高峰上逐个推下去，以便在争得无产阶级政权后再把革命火焰燃遍世界各国，这和列宁根据他在帝国主义环境中的无产阶级革命论所教导我们的一切以及他在我们的革命过程中所实行的一切是完全符合的。","language":"中文","translation":false},{"id":"foundations-1-141","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此可见，我们俄国的“不断论者”不仅过低估计了农民在俄国革命中的作用和无产阶级领导权思想的意义，而且改变了（改坏了）马克思的“不断”革命的思想，使它不合实用了。","language":"中文","translation":false},{"id":"foundations-1-142","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，列宁嘲笑了我国“不断论者”的理论，称之为“独创的”“卓越的”理论，责备他们不肯“想一想，究竟由于哪些原因整整十年的实际生活都没有理睬他那个卓越的理论”。（列宁的这篇论文是在一九一五年，即在俄国“不断论者”的理论出现后过了十年写 的。——见“列宁全集”第四版第二十一卷第三八一页）","language":"中文","translation":false},{"id":"foundations-1-143","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，列宁认为这个理论是半孟什维主义的理论，说这个理论“从布尔什维克方面摄取了号召无产阶级进行坚决革命斗争和夺取政权的口号，而从孟什维克方面摄取了‘否定’农民作用的思想”。（见列宁“论革命中的两条路线”一文，“列宁全集”第四版第二十一卷第三八一页至第三八二页）。","language":"中文","translation":false},{"id":"foundations-1-144","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁关于资产阶级民主革命转变为无产阶级革命的思想，关于利用资产阶级革命来“立刻”过渡到无产阶级革命的思想就是这样。","language":"中文","translation":false},{"id":"foundations-1-145","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"其次，从前认为革命在一个国家内胜利是不可能的，以为要战胜资产阶级就必须要有一切先进国家内或至少要有多数先进国家内无产者的共同发动。现在，这个观点已经不合乎实际情形了。现在必须从这种胜利是可能的出发，因为各种不同的资本主义国家在帝国主义环境内发展的不平衡性和跳跃性，帝国主义内部那些必然引起战争的灾难性矛盾的发展，世界各国革命运动的增长，——所有这一切都使无产阶级在个别国家内的胜利不仅是可能的，而且是必然的。俄国革命的历史已经直接证明了这一点。不过这里必须记住：只有具备了某些完全必要的条件，才能顺利地推翻资产阶级；没有这些条件，就根本谈不到无产阶级夺取政权。","language":"中文","translation":false},{"id":"foundations-1-146","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"请看列宁在他的《幼稚病》一书中关于这些条件是怎样说的：","language":"中文","translation":false},{"id":"foundations-1-147","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“一切革命，尤其是二十世纪俄国三次革命所证实了的革命基本规律就是：要举行革命，单是被剥削被压迫群众感到不能照旧生活下去而要求变革，还是不够的；要举行革命，还必须要剥削者也不能照旧生活和统治下去。只有当‘下层’不愿照旧生活而‘上层’也不能照旧生活和统治下去的时候，革命才能获得胜利。这个真理的另一个说法是：如果没有全国性的（既触动被剥削者又触动剥削者的）危机，那么革命是不可能的（注：黑体是我用的。——约·斯大林注）。这就是说，要举行革命，第一，必须要多数工人（至少是多数有觉悟、能思考、政治上积极的工人）充分认识到革命的必要性，并且抱有为革命牺牲的决心；第二，必须要统治阶级遭到政府危机，这种危机甚至把最落后的群众卷入政治运动……削弱政府的力量，使革命者有可能很快地推翻它。”（见“列宁全集”第四版第三十一卷第六十五页至第六十六页）","language":"中文","translation":false},{"id":"foundations-1-148","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，在一个国家内推翻资产阶级政权，建立无产阶级政权，还不等于保证社会主义的完全胜利。社会主义的主要任务即组织社会主义生产的任务尚待解决。没有几个先进团家中无产者的共同努力，能不能解决这个任务，能不能在一个国家内获得社会主义的最终胜利呢?不，不能。为了推翻资产阶级，一个国家的努力就够了，这是我国革命的历史给我们说明了的。为了获得社会主义的最终胜利，为了组织社会主义生产，单靠一个国家的努力，特别是象俄国这样一个农民国家的努力就不够了，一为了达到这个目的，就必须有几个先进国家中无产者的共同努力。因此，发展和援助其他国家内的革命是获得胜利的革命的重大任务，因此，在一个国家内获得胜利的革命不应当把自己看做独立自在的东西，而应当看做用以加速其他国家无产阶级胜利的助力和工具。*","language":"中文","translation":false},{"id":"foundations-1-149","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁用一句话说明了这个意思，他说，获得胜利的革命的任务就在于“最大限度地实现一个国家内所能实现的一切，以便发展、援助 和激起世界各国的革命”。（见“列宁全集”第四版第二十八卷第二六九页）。","language":"中文","translation":false},{"id":"foundations-1-150","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义的无产阶级革命论的特征大体上就是这样。","language":"中文","translation":false},{"id":"foundations-1-151","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"*整理者注：当前流传的版本中，这段话被修改为：","language":"中文","translation":false},{"id":"foundations-1-152","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，在一个国家内推翻资产阶级政权，建立无产阶级政权，还不等于保证社会主义的完全胜利。革命获得胜利的国家的无产阶级既然已经巩固自己的政权并领导着农民，就能够而且应当建成社会主义社会。但是，这是不是说，它这样就能获得社会主义的完全胜利即最终胜利呢？换言之，这是不是说，它单靠一个国家的力量就能够最终巩固社会主义并完全保障国家免除外国武装干涉，也就是免除复辟呢？不，不是这个意思。为了达到这个目的，至少必须有几个国家内革命的胜利。因此，发展和援助其他国家内的革命是获得胜利的革命的重大任务。因此，在一个国家内获得胜利的革命不应当把自己看做独立自在的东西，而应当看做用以加速其他国家无产阶级胜利的助力和工具。","language":"中文","translation":false},{"id":"foundations-1-153","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于这个题目我来讲三个基本问题：","language":"中文","translation":false},{"id":"foundations-1-154","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）无产阶级专政是无产阶级革命的工具；","language":"中文","translation":false},{"id":"foundations-1-155","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）无产阶级专政是无产阶级对资产阶级的统治；","language":"中文","translation":false},{"id":"foundations-1-156","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丙）苏维埃政权是无产阶级专政的国家形式。","language":"中文","translation":false},{"id":"foundations-1-157","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(1)无产阶级专政是无产阶级革命的工具。无产阶级专政问题首先就是无产阶级革命的基本内容问题。无产阶级革命，无产阶级革命的进展、规模和成绩，只有通过无产阶级专政才能具体实现。无产阶级专政是无产阶级革命的工具，是这个革命的机关，是这个革命的最重要的据点，它的使命是：第一，镇压已被推翻的剥削者的反抗，巩固自己的成绩；第二，把无产阶级革命进行到底，使革命达到社会主义的完全胜利。没有无产阶级专政，革命也能战胜资产阶级，推翻资产阶级政权。可是，如果革命不在自己发展的一定阶段上建立无产阶级专政这个专门机关作为自己的基本支柱，那么它就不能镇压资产阶级的反抗，不能保持胜利并向前进展到社会主义的最终胜利。","language":"中文","translation":false},{"id":"foundations-1-158","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“政权问题是一切革命的根本问题。”（列宁）这是不是说，事情只限于夺取政权，取得政权呢？不，不是这个意思。取得政权——这仅仅是事情的开始。在一个国家内被推翻的资产阶级，由于许多原因，在长时间内还比推翻了它的无产阶级有力量。因此，全部问题在于保持政权，巩固政权，使它成为不可战胜的。为了达到这个目的，必须做些什么呢？为了达到这个目的，至少必须完成在革命胜利的“第二天”就摆在无产阶级专政面前的三个主要任务：","language":"中文","translation":false},{"id":"foundations-1-159","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）粉碎已被革命推翻和剥夺的地主和资本家的反抗，消灭他们的一切恢复资本政权的行动；","language":"中文","translation":false},{"id":"foundations-1-160","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）用把一切劳动者团结在无产阶级周围的精神来组织建设工作，并按照准备取消阶级，消灭阶级的方向来进行这一工作；","language":"中文","translation":false},{"id":"foundations-1-161","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丙）把革命武装起来，组织革命军队，以便和外部敌人作斗争，和帝国主义作斗争。","language":"中文","translation":false},{"id":"foundations-1-162","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"所以需要无产阶级专政，就是为了执行这些任务，完成这些任务。","language":"中文","translation":false},{"id":"foundations-1-163","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“从资本主义过渡到共产主义是一整个历史时代。只要这个时代没有结束，剥削者就必然存在着复辟希望，并把这种希望变为复辟行动。被推翻的剥削者不曾料到自己会被推翻，他们不相信这一点，不愿想到这一点，所以他们在遭到第一次严重失败以后，就以十倍的努力、疯狂的热情、百倍的仇恨投入战斗，为恢复他们被夺去的‘天堂’、为他们的家庭而斗争，他们的家庭从前过着那么甜蜜的生活，现在却被‘平凡的贱民’弄得破产和贫困（或者弄得只好从事“平凡的”劳动……）。而跟着剥削者资本家走的，还有广大的小资产阶级群众。世界各国几十年来的历史经验证明，小资产阶级总是犹豫不决，动摇不定，今天跟着无产阶级走，明天又因革命遭到困难而害怕起来，因工人遭受初次失败或挫折而张皇失措，他们心慌意乱，东奔西跑，到处诉苦，从这个营垒跑到那个营垒。”（见“列宁全集”第四版第二十八卷第二三三页）","language":"中文","translation":false},{"id":"foundations-1-164","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"而资产阶级是有根据来进行复辟行动的，因为资产阶级被推翻以后在长时间内还比推翻了它的无产阶级有力量。","language":"中文","translation":false},{"id":"foundations-1-165","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“如果剥削者只在一国内被打倒（这当然是典型的情况，因为几国同时发生革命是罕有的例外），他们就依然比被剥削者强大。”（同上，第二三二页）","language":"中文","translation":false},{"id":"foundations-1-166","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"被推翻的资产阶级的力量在哪里呢？","language":"中文","translation":false},{"id":"foundations-1-167","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一，“在于国际资本的力量，在于资产阶级的各种国际联系牢固有力”。（见“列宁全集”第四版第三十一卷第七页）","language":"中文","translation":false},{"id":"foundations-1-168","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二，在于“在革命以后的长时期内，剥削者必然在许多方面保持巨大的事实上的优势：他们还有货币（货币是不能一下子消灭的），有某些动产（往往是很多的）；有种种联系，有组织和管理的技能，知道一切管理‘秘诀’（习惯、方法、手段和窍门）；有较高的教育程度，同高级技术人员（他们的生活和思想是资产阶级的）接近；有无比丰富的军事技能（这是很重要的），以及其他等等”。（见“列宁全集”第四版第二十八卷第二三二页）","language":"中文","translation":false},{"id":"foundations-1-169","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第三，“在于习惯的力量，在于小生产的力量。因为小生产在世界上可惜还保留着很多很多，而小生产是经常地、每日每时地、自发地和大批地产生着资本主义和资产阶级的。……”因为“消灭阶级不仅意味着要驱逐地主和资本家，——这个我们已经比较容易地做到了——而且意味着要消灭小商品生产者，可是对于这种人不能驱逐，不能镇压，必须同他们和睦相处，可以（而且必须）改造他们，重新教育他们，这只有通过很长期、很缓慢、很谨慎的组织工作才能做到”。（见“列宁全集”第四版第三十一卷第七页至第八页和第二十六页至第二十七页）","language":"中文","translation":false},{"id":"foundations-1-170","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“无产阶级专政是新阶级对较强大的敌人，对资产阶级进行的最奋勇和最无情的战争，而资产阶级因为它被推翻而十倍加强它的反抗。”","language":"中文","translation":false},{"id":"foundations-1-171","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“无产阶级专政是对旧社会的势力和传统进行的顽强斗争，流血的和不流血的，暴力的和和平的，军事的和经济的，教育的和行政的斗争。”（同上，第七页和第二十七页）","language":"中文","translation":false},{"id":"foundations-1-172","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"几乎用不着证明，要在短时期内完成这些任务，要在几年内实现这一切，是绝对不可能的。因此，不应该把无产阶级专政，把从资本主义到共产主义的过渡看做瞬息即逝的时期，看做一批“最革命的”法律和法令，而应该把它看做充满国内战争和国外冲突、顽强的组织工作和经济建设、进攻和退却、胜利和失败的整整一个历史时代。这个历史时代所以必要，不仅是为了创造社会主义完全胜利的经济上和文化上的前提，而且是为了使无产阶级有可能：第一，把自己教育并锻炼成为能够管理国家的力量；第二，按照保证组织社会主义生产的方针来重新教育并改造小资产阶级阶层。","language":"中文","translation":false},{"id":"foundations-1-173","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"马克思向工人说过：“不仅为了改变现存条件，而且为了改变自己本身，使自己具有进行政治统治的能力，你们或许不得不再经历十五年、二十年、五十年的内战和国际冲突。”（见“马克思恩格斯全集”俄文第一版第八卷第五○六页）","language":"中文","translation":false},{"id":"foundations-1-174","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁继承并发展马克思这个思想时写道：","language":"中文","translation":false},{"id":"foundations-1-175","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“在无产阶级专政下，必须重新教育千百万农民和小业主，数十万职员、官吏和资产阶级知识分子，使他们大家都服从无产阶级的国家和无产阶级的领导，战胜他们中间的资产阶级的习惯和传统”，同样，必须“……在长期斗争中，在无产阶级专政的基础上重新教育无产者自己……因为无产者不能用神术，不能遵照圣母的意旨，不能遵照口号、决议、法令的意旨，一下子摆脱自己的小资产阶级偏见，而只有对广泛的小资产阶级影响，展开长期的艰苦的广泛的斗争，才能摆脱这种偏见。”（见“列宁全集”第四版第三十一卷第九十五页至第九十六页和第九十四页）。","language":"中文","translation":false},{"id":"foundations-1-176","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(2)无产阶级专政是无产阶级对资产阶级的统治。从上面所说的可以看出，无产阶级专政并不是在不侵犯旧的经济制度和政治制度的条件下进行的政府人员的普通的更换、“内阁”的更换等等。各国孟什维克和机会主义者害怕专政象害怕火一样，竟用所谓“夺取政权”的概念来顶替专政的概念。他们通常都把“夺取政权”归结为更换“内阁”，归结为由谢德曼和诺斯克、麦克唐纳和韩德逊这一类人组成新内阁执政。几乎用不着解释，诸如此类的内阁更换是和无产阶级专政，和真正的无产阶级夺取真正的政权毫无共同之点的。麦克唐纳之流和谢德曼之流在保留资产阶级旧制度的条件下掌握政权，他们的所谓政府，只能是资产阶级御用的服务机关，只能是帝国主义脓疮的掩蔽物，只能是资产阶级用来反对被压迫被剥削群众的革命运动的工具。当资本没有屏风就不便于、不利于、难于剥削和压迫群众的时候，它需要这些政府来做屏风。当然，这种政府的出现是“在他们那里”（就是说，在资本家那里），“在希普卡”（注：在1877—1878年俄土战争中，俄军曾冒严寒扼守巴尔干的希普卡山隘，大批士兵冻死冻伤，俄军司令部战报却多次说：“在希普卡平安无事。”）并非平安无事的征兆；虽然如此，这种政府仍然不免是稍加粉饰的资本政府。麦克唐纳政府或谢德曼政府是和无产阶级夺取政权相隔天壤的。无产阶级专政不是政府的更换，而是拥有新的中央政权机关和地方政权机关的新国家，是在旧国家即资产阶级国家的废墟上产生的无产阶级国家。","language":"中文","translation":false},{"id":"foundations-1-177","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":177,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"无产阶级专政不是在资产阶级制度的基础上产生的，而是在破坏资产阶级制度的过程中，在推翻资产阶级以后，在剥夺地主和资本家的过程中，在把基本的生产工具和生产资料社会化的过程中，在无产阶级的暴力革命的过程中产生的。无产阶级专政是以对资产阶级使用暴力为凭借的革命政权。","language":"中文","translation":false},{"id":"foundations-1-178","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":178,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"国家是统治阶级用来镇压其阶级敌人的反抗的机器。就这一点来说，无产阶级专政实质上和其他任何阶级的专政毫无区别，因为无产阶级国家是用来镇压资产阶级的机器。但是这里有一个本质上的差别。这个差别就在于以前所有的阶级国家是少数剥削者对多数被剥削者的专政，而无产阶级专政则是多数被剥削者对少数剥削者的专政。","language":"中文","translation":false},{"id":"foundations-1-179","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":179,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"简单地说：无产阶级专政就是无产阶级对资产阶级的统治，它不受法律限制，凭借暴力，得到被剥削的劳动群众的同情和拥护。（列宁《国家与革命》）","language":"中文","translation":false},{"id":"foundations-1-180","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":180,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此应当得出两个基本结论：","language":"中文","translation":false},{"id":"foundations-1-181","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":181,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一个结论：无产阶级专政不能是“完全的”民主，不能是对所有的人的民主，即既对富人又对穷人的民主；无产阶级专政“应当是新型民主的（对〔注：黑体是我用的。——约·斯大林〕无产者和一切穷人是民主的）国家和新型专政的（对〔注：黑体是我用的。——约·斯大林〕）资产阶级是专政的）国家”。考茨基及其同伙所谓普遍的平等、“纯粹的”民主和“完善的”民主等等的空话，是资产阶级用来掩饰被剥削者和剥削者不可能有平等这一无可置疑的事实的。“纯粹”民主论是帝国主义强盗所驯育和豢养的工人阶级上层分子的理论。这个理论的使命就是要掩盖资本主义的脓疮，粉饰帝国主义，赋予它一种精神力量来反对被剥削群众。在资本主义制度下，被剥削者没有而且不可能有真正的“自由”，这至少是因为房屋、印刷所、纸张仓库等等这些为享有“自由”所必需的东西都是剥削者的特权。在资本主义制度下，被剥削群众是没有而且不可能真正参加国家的管理的，这至少是因为即使在资本主义条件下最民主的制度中，政府也不是由人民所指定，而是由路特希尔德家族和斯汀尼斯家族、洛克菲勒家族和摩根家族所指定的。资本主义制度下的民主是资本主义的民主，是少数剥削者的民主，是以限制多数被剥削者的权利为基础并以反对这个多数为目标的。只有在无产阶级专政下，被剥削者才可能有真正的自由，无产者和农民才可能真正参加国家的管理。无产阶级专政下的民主是无产阶级的民主，是多数被剥削者的民主，是以限制少数剥削者的权利为基础并以反对这个少数为目标的。","language":"中文","translation":false},{"id":"foundations-1-182","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":182,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二个结论：无产阶级专政的产生不能是资产阶级社会和资产阶级民主制和平发展的结果，而只能是摧毁资产阶级的国家机器、资产阶级的军队、资产阶级的官吏机构、资产阶级的警察的结果。","language":"中文","translation":false},{"id":"foundations-1-183","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":183,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"马克思和恩格斯在《共产党宣言》序言中说：“工人阶级不能简单地掌握现成的国家机器，并运用它来达到自己的目的。”马克思在1871年给库格曼的信中说：无产阶级革命“……不应该象以前那样把官僚军事机器从一些人的手里转到另一些人的手里，而应该把它摧毁，这正是大陆上任何一次真正的人民革命的先决条件”[15]。","language":"中文","translation":false},{"id":"foundations-1-184","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":184,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"马克思的这句以大陆为限的话竟被各国机会主义者和孟什维克作为借口来叫喊：可见马克思曾经假定资产阶级民主有和平发展到无产阶级民主的可能，至少欧洲大陆以外的几个国家（英国和美国）是有这种可能的。马克思的确曾经假定有这种可能，并且有根据来给十九世纪七十年代的英美两国做这种假定，因为当时还没有垄断的资本主义，还没有帝国主义，当时在这些国家中由于特殊的发展条件，还没有发达的军阀机构和官僚机构。在发达的帝国主义出现以前的情形就是这样的。可是经过三四十年以后，当这些国家中的情形已经根本改变，当帝国主义已经发展并普及于所有一切资本主义国家，当军阀机构和官僚机构也已经在英美出现，当英美和平发展的特殊条件已经消失的时候，关于这些国家不在此限的说法自然就应当失去时效了。","language":"中文","translation":false},{"id":"foundations-1-185","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":185,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“现在，在1917年，在第一次帝国主义大战时期，马克思的这个限制已经不能成立了。英国和美国这两个全世界最大的和最后的盎格鲁撒克逊‘自由制’（从没有军阀机构和官僚机构这个意义来说）的代表，已经完全滚到官僚机构和军阀机构支配一切、镇压一切这样一种一般欧洲式的污浊血腥泥潭中去了。现在，无论在英国或美国，都要以摧毁、破坏‘现成的’（是1914—1917年间在这两个国家已制造完毕而达到了“欧洲式的”、一般帝国主义的完备程度的）‘国家机器’，作为‘任何一次真正的人民革命的先决条件’。”（见“列宁全集”第四版第二十五卷第三八七页）","language":"中文","translation":false},{"id":"foundations-1-186","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":186,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"换句话说，无产阶级暴力革命的规律，摧毁资产阶级的国家机器是这种革命的先决条件的规律，是全世界帝国主义国家革命运动的必然规律。","language":"中文","translation":false},{"id":"foundations-1-187","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":187,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"当然，在遥远的将来，如果无产阶级在那些最重要的资本主义国家内获得胜利，如果现在的资本主义包围被社会主义包围所代替，那么某些资本主义国家走上“和平”发展的道路是完全可能的，这些国家的资本家由于国际环境的“不利”，会认为最好是“自愿地”向无产阶级做重大的让步。可是，这个假定所涉及的只是遥远的和可能的将来。对于最近的将来，这个假定是没有任何根据的，是完全没有任何根据的。","language":"中文","translation":false},{"id":"foundations-1-188","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":188,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“不用暴力破坏资产阶级的国家机器，不用新的国家机器代替它，无产阶级革命是不可能的。”（见“列宁全集”第四版第二十八卷第二一七页）","language":"中文","translation":false},{"id":"foundations-1-189","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":189,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(3)苏维埃政权是无产阶级专政的国家形式。无产阶级专政的胜利就是镇压资产阶级，摧毁资产阶级的国家机器，以无产阶级的民主来代替资产阶级的民主。这是很明显的。但是要依靠什么组织才能完成这个巨大的工作呢？无产阶级的在资产阶级议会制基础上成长起来的旧的组织形式不足以完成这个工作，这是不容置疑的。那么，无产阶级的什么新的组织形式能够起资产阶级国家机器的掘墓人的作用，不仅能够摧毁这个机器，不仅能够以无产阶级的民主来代替资产阶级的民主，而且能够成为无产阶级国家政权的基础呢？","language":"中文","translation":false},{"id":"foundations-1-190","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":190,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"无产阶级的这个新的组织形式就是苏维埃。","language":"中文","translation":false},{"id":"foundations-1-191","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":191,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"苏维埃优越于旧的组织形式的地方在哪里呢？","language":"中文","translation":false},{"id":"foundations-1-192","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":192,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃是无产阶级的最能包括一切的群众组织，因为苏维埃，而且只有苏维埃，才能包括所有一切工人。","language":"中文","translation":false},{"id":"foundations-1-193","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":193,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃是能够团结所有的被压迫者和被剥削者、工人和农民、士兵和水兵的唯一的群众组织，因此在这个组织中，群众先锋队即无产阶级对群众斗争的政治领导就能够最容易和最充分地实现。","language":"中文","translation":false},{"id":"foundations-1-194","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":194,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃是群众革命斗争、群众政治发动和群众武装起义的最强有力的机关，是能够摧毁金融资本及其政治附属物的极大势力的机关。","language":"中文","translation":false},{"id":"foundations-1-195","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":195,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃是群众本身的直接的组织，是最民主的因而也是群众的最有威信的组织，这种组织能尽量便利群众参加新国家的建设和管理，能尽量发挥群众在毁坏旧制度的斗争中，在建设无产阶级新制度的斗争中的革命毅力、首倡精神和创造能力。","language":"中文","translation":false},{"id":"foundations-1-196","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":196,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"苏维埃政权就是把各地方苏维埃统一成为一个总的国家组织，统一成为无产阶级这个被压迫被剥削群众的先锋队、这个统治阶级的国家组织，即统一成为苏维埃共和国。","language":"中文","translation":false},{"id":"foundations-1-197","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":197,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"苏维埃政权的实质就在于：正是从前受资本家和地主压迫的那些阶级的最群众化和最革命的组织现在成了“全部国家政权和全部国家机构的固定的和唯一的基础”，“正是那些”在法律上有平等权利、“实际上却受到各种排挤不能参加政治生活和享有民主权利和自由（甚至在最民主的资产阶级共和国也是这样）的群众，现在被吸引来经常参加对国家的民主管理并在其中起决定作用”（黑体都是我用的。——约·斯大林注；见“列宁全集”第四版第二十八卷第四四三页）。","language":"中文","translation":false},{"id":"foundations-1-198","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":198,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，苏维埃政权是新的国家组织形式，与旧的资产阶级民主制的和议会制的国家组织形式有原则上的差别；它是新的国家类型，不适合于剥削和压迫劳动群众的任务，而适合于使他们完全摆脱任何压迫和任何剥削的任务，适合于无产阶级专政的任务。","language":"中文","translation":false},{"id":"foundations-1-199","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":199,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说得对：自从出现了苏维埃政权，“资产阶级民主的议会制度的时代已经终结。世界历史的新的一章，即无产阶级专政的时代已经开始”。","language":"中文","translation":false},{"id":"foundations-1-200","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":200,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"苏维埃政权的特征在哪里呢？","language":"中文","translation":false},{"id":"foundations-1-201","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":201,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃政权是存在着阶级的条件下可能有的一切国家组织中最群众化和最民主的国家组织，因为它既然是工人和被剥削农民在反对剥削者的斗争中结合和合作的场所，并在自己的工作中依靠这个结合和合作，它就是多数居民统治少数居民的政权，是这个多数的国家，是这个多数专政的表现。","language":"中文","translation":false},{"id":"foundations-1-202","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":202,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃政权是阶级社会一切国家组织中最富于国际主义的组织，因为它既然摧毁任何民族压迫而依靠各族劳动群众的合作，它就使这些群众易于在统一的国家联盟内联合起来。","language":"中文","translation":false},{"id":"foundations-1-203","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":203,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃政权按本身结构来说，使被压迫被剥削群众的先锋队，即无产阶级这个在苏维埃中最团结和最觉悟的核心易于领导这些被压迫被剥削群众。","language":"中文","translation":false},{"id":"foundations-1-204","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":204,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“被压迫阶级的一切革命和一切运动的经验、全世界社会主义运动的经验教导我们，只有无产阶级才能够团结和领导被剥削的劳动人民中的涣散落后的阶层。”（见“列宁全集”第四版第二十八卷第四四四页）而苏维埃政权的结构有助于实现这个经验给我们的启示。","language":"中文","translation":false},{"id":"foundations-1-205","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":205,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于苏维埃政权既然在统一的国家组织内把立法权和行政权结合起来，并用生产单位，用工厂来代替地域选区，就把工人和一般劳动群众同国家管理机关直接联系起来，教他们学习管理国家。","language":"中文","translation":false},{"id":"foundations-1-206","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":206,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于只有苏维埃政权才能使军队不受资产阶级长官的支配，把军队由资产阶级制度下压迫人民的工具变为使人民从本国的和外国的资产阶级压迫下解放出来的工具。","language":"中文","translation":false},{"id":"foundations-1-207","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":207,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于“只有苏维埃国家组织才能真正一下子粉碎和彻底摧毁旧式的即资产阶级的、官僚的、法官的机关”（见“列宁全集”第四版第二十八卷第四四四页）。","language":"中文","translation":false},{"id":"foundations-1-208","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":208,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就在于只有苏维埃的国家形式才能吸收劳动者和被剥削者的群众组织无条件地经常参加国家的管理，只有它才能准备国家的消亡，这种消亡是将来的无国家社会即共产主义社会的基本因素之一。","language":"中文","translation":false},{"id":"foundations-1-209","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":209,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这样，苏维埃共和国就是那个找了很久而终于找到了的政治形式，在这个形式的范围内必将完成无产阶级的经济解放，社会主义的完全胜利。","language":"中文","translation":false},{"id":"foundations-1-210","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":210,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"巴黎公社是这种形式的萌芽。苏维埃政权是这种形式的发展和完成。","language":"中文","translation":false},{"id":"foundations-1-211","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":211,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“工兵农代表苏维埃共和国不仅是更高类型的民主机构的形式……而且是能够保证最无痛苦地过渡到社会主义的唯一（注：黑体是我用的。——约·斯大林）形式。”（见“列宁全集”第四版第二十六卷第三四○页）","language":"中文","translation":false},{"id":"foundations-1-212","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":212,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于这个题目我来讲四个问题：","language":"中文","translation":false},{"id":"foundations-1-213","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":213,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）资产阶级民主革命时期的农民；","language":"中文","translation":false},{"id":"foundations-1-214","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":214,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丙）无产阶级革命时期的农民；","language":"中文","translation":false},{"id":"foundations-1-215","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":215,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丁）苏维埃政权巩固后的农民。","language":"中文","translation":false},{"id":"foundations-1-216","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":216,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(1)问题的提法。有人以为列宁主义中的基本问题是农民问题，以为列宁主义的出发点是关于农民及其作用和比重的问题。这是完全不对的。列宁主义中的基本问题，列宁主义的出发点，并不是农民问题，而是无产阶级专政、争取无产阶级专政的条件、巩固无产阶级专政的条件等问题。农民问题，即无产阶级在为政权而斗争中的同盟者问题，是一个派生的问题。","language":"中文","translation":false},{"id":"foundations-1-217","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":217,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，这个情况丝毫不会使农民问题失去它对无产阶级革命无疑具有的重大而迫切的意义。大家知道，在俄国马克思主义者的队伍里，认真研究农民问题正是在第一次革命（1905年）前夜开始的，当时推翻沙皇制度和实现无产阶级领导权的问题已经全盘摆在党的面前，无产阶级在当前资产阶级革命中的同盟者问题已经具有迫切的性质。大家也知道，俄国农民问题在无产阶级革命时期具有更迫切的性质，当时无产阶级专政的问题，争取和保持无产阶级专政的问题引起了无产阶级在当前无产阶级革命中的同盟者问题。不言而喻，谁想夺取政权，谁准备夺取政权，谁就不能不关心自己的真正同盟者的问题。","language":"中文","translation":false},{"id":"foundations-1-218","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":218,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从这个意义上说，农民问题是无产阶级专政这个总问题的一部分，因而也就是列宁主义的最迫切的问题之一。","language":"中文","translation":false},{"id":"foundations-1-219","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":219,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二国际各党所以漠视农民问题，有时简直否认农民问题，不仅是因为西方有特殊的发展条件，而首先是因为它们不相信无产阶级专政，害怕革命，不想引导无产阶级去夺取政权。而谁要是害怕革命，谁要是不想引导无产者去夺取政权，谁也就不会关心无产阶级在革命中的同盟者问题，因为在他看来，同盟者问题是无所谓的，不迫切的。第二国际的英雄们把自己讥笑农民问题的态度看作文雅风度的表现，“真正”马克思主义的表现。其实，这里一点马克思主义的气味也没有，因为在无产阶级革命前夜漠视农民问题这样一个重要的问题，就是否认无产阶级专政，就是直接背叛马克思主义的明显标志。","language":"中文","translation":false},{"id":"foundations-1-220","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":220,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"问题是这样：由于农民的某些生活条件而潜藏在农民内部的革命的可能性是否已经用完？如果还没有用完，是否有希望、有根据把这种可能性用于无产阶级革命，把农民，把农民中的多数被剥削者由资产阶级的后备军（从前在西方资产阶级革命时期是这样，现在还是这样）变为无产阶级的后备军，变为无产阶级的同盟者？","language":"中文","translation":false},{"id":"foundations-1-221","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":221,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义对这个问题的答复是肯定的，即认为多数农民具有革命能力，认为可以把这种革命能力用于无产阶级专政。","language":"中文","translation":false},{"id":"foundations-1-222","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":222,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"俄国三次革命的历史完全证实了列宁主义关于这一点的结论。","language":"中文","translation":false},{"id":"foundations-1-223","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":223,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此得出一个实际结论，就是要援助劳动农民群众的反对奴役和剥削的斗争，摆脱压迫和贫困的斗争。这当然不是说，无产阶级应当援助任何一种农民运动。这里所说的是要援助直接或间接地便利无产阶级解放运动、这样或那样地帮助无产阶级革命、促使农民变为工人阶级的后备军和同盟者的那种农民运动和农民斗争。","language":"中文","translation":false},{"id":"foundations-1-224","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":224,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(2)资产阶级民主革命时期的农民。这个时期包括俄国第一次革命（1905年）和第二次革命（1917年2月）。这个时期的特征是农民摆脱自由资产阶级的影响，离开立宪民主党人〔注：立宪民主党（或称人民自由党）是俄国自由君主派资产阶级的主要政党，成立于1905年10月，领袖是巴·尼·米留可夫。立宪民主党企图用立宪君主制的形式保存沙皇君主制。第一次世界大战期间，该党支持沙皇政府的对外侵略政策。1917年二月革命后，立宪民主党人在资产阶级临时政府中占据领导地位。十月革命胜利后，立宪民主党人多次策划反革命阴谋和暴乱。在武装干涉和白卫分子被击溃后，立宪民主党上层的大部分人逃亡国外，继续进行反对苏维埃俄国的活动。〕，而转到无产阶级方面来，转到布尔什维克党方面来。这个时期的历史是立宪民主党人（自由资产阶级）和布尔什维克（无产阶级）争夺农民的历史。杜马时期决定了这个斗争的命运，因为前后四届杜马时期给了农民一个实际教训，这个教训明明白白地向农民指出：他们从立宪民主党人手中既得不到土地，也得不到自由；沙皇完全拥护地主，而立宪民主党人则拥护沙皇；农民所能指望得到帮助的唯一的力量就是城市工人，即无产阶级。帝国主义战争只是证实了杜马时期的教训，使农民最终离开资产阶级，使自由资产阶级最终陷于孤立，因为战争年份表明：希望从沙皇及其资产阶级同盟者那里得到和平完全是画饼充饥，自欺欺人。如果没有杜马时期的实际教训，就不可能有无产阶级的领导权。","language":"中文","translation":false},{"id":"foundations-1-225","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":225,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"资产阶级民主革命中的工农联盟就是这样形成的。在推翻沙皇制度的共同斗争中的无产阶级领导权就是这样形成的，而这个领导权就引导到1917年的二月革命。","language":"中文","translation":false},{"id":"foundations-1-226","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":226,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"大家知道，西方（英、法、德、奥）资产阶级革命是循着另一条道路进行的。西方革命的领导权不是属于当时由于本身幼弱而没有成为并且不可能成为独立的政治力量的无产阶级，而是属于自由资产阶级。西方农民摆脱农奴制而获得的解放不是从人数很少和没有组织的无产阶级手里得到的，而是从资产阶级手里得到的。西方农民是和自由资产阶级一道反对旧制度的。西方农民是资产阶级的后备军。因此，西方革命的结果使资产阶级的政治比重大大增加了。","language":"中文","translation":false},{"id":"foundations-1-227","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":227,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"而俄国资产阶级革命所产生的结果却完全相反。俄国革命的结果不是使资产阶级这个政治力量加强，而是使它削弱；不是使它的政治后备军增加，而是使它失去了基本的后备军，即失去了农民。俄国资产阶级革命不是把自由资产阶级提到了首位，而是把革命无产阶级提到了首位，把千百万农民团结在革命无产阶级的周围。","language":"中文","translation":false},{"id":"foundations-1-228","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":228,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这也就说明为什么俄国资产阶级革命在比较短的时间内就转变成了无产阶级革命。无产阶级领导权是无产阶级专政的萌芽，是向无产阶级专政的过渡阶段。","language":"中文","translation":false},{"id":"foundations-1-229","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":229,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"俄国革命为什么有这个在西方资产阶级革命历史上没有先例的独特现象呢？这个独特现象是从哪里来的呢？","language":"中文","translation":false},{"id":"foundations-1-230","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":230,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这是因为俄国资产阶级革命是在比西方更发展的阶级斗争条件下展开的，因为俄国无产阶级在这个时候已经成为独立的政治力量，而被无产阶级的革命性所吓倒的自由资产阶级已经丧失任何革命性（尤其在1905年的教训以后），转而同沙皇和地主结成联盟来反对革命，反对工农。","language":"中文","translation":false},{"id":"foundations-1-231","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":231,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"必须注意下面几个决定俄国资产阶级革命的独特性的情况：","language":"中文","translation":false},{"id":"foundations-1-232","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":232,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）俄国工业在革命前夜的空前的集中程度。例如大家知道，当时俄国在有五百工人以上的企业中工作的工人占全体工人的百分之五十四，而象美国这样发达的国家在同样的企业中工作的工人只占全体工人的百分之三十三。几乎用不着证明，单是这一个情况，在具备布尔什维克党这样一个革命政党的条件下，就已经使俄国工人阶级成为全国政治生活中最大的力量了。","language":"中文","translation":false},{"id":"foundations-1-233","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":233,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）企业中丑恶的剥削形式，加上沙皇走狗残酷的警察压制，——这个情况使工人的每一次重大的罢工都变成巨大的政治行动，把工人阶级锻炼成为彻底革命的力量。","language":"中文","translation":false},{"id":"foundations-1-234","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":234,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丙）俄国资产阶级的政治上的萎靡不振，在1905年革命以后已经变成对于沙皇制度的效忠和公开的反革命，这不仅因为俄国无产阶级的革命性使俄国资产阶级投入沙皇制度的怀抱，而且因为俄国资产阶级直接依赖政府的订货。","language":"中文","translation":false},{"id":"foundations-1-235","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":235,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（四）农村中最丑恶最难堪的农奴制残余，加上地主的专权，——这个情况使农民投入了革命的怀抱。","language":"中文","translation":false},{"id":"foundations-1-236","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":236,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（戊）沙皇制度压制一切有生机的东西，并以自己的专横来加重资本家和地主的压迫，——这个情况使工人和农民的斗争汇合成一条革命洪流。","language":"中文","translation":false},{"id":"foundations-1-237","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":237,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（己）帝国主义战争把俄国政治生活中的这一切矛盾融合为深刻的革命危机，并使革命具有莫大的冲击力量。","language":"中文","translation":false},{"id":"foundations-1-238","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":238,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在这样的条件下，农民应当向哪里走呢？农民应当向谁寻求援助来反对地主专权、反对沙皇专横、反对使农民经济破产的毁灭性战争呢？向自由资产阶级吗？然而它是敌人，——这是前后四届杜马的多年的经验已经证明了的。向社会革命党人〔注：社会革命党是俄国的小资产阶级政党，1901年底—1902年初由一些民粹派团体和小组合并而成。社会革命党人的观点是民粹主义和修正主义的大杂烩，他们“竭力用机会主义对马克思主义的时髦‘批评’的补钉来修补民粹主义的破洞”（《列宁全集》第9卷第295页）。社会革命党人否认农民内部的阶级矛盾，反对无产阶级在资产阶级民主革命中的领导作用和无产阶级专政的思想。第一次世界大战期间，社会革命党人多数支持沙皇俄国的战争政策，少数反对战争，形成了后来的左派社会革命党的核心。1917年二月革命后，社会革命党人同孟什维克、立宪民主党人一起充当了资产阶级临时政府的主要支柱，党的领袖亚·费·克伦斯基、尼·德·阿夫克森齐也夫、维·米·切尔诺夫等在临时政府内担任要职。1917年11月，社会革命党的左翼组成了独立的左派社会革命党。左派社会革命党人在一段时间内承认苏维埃政权，同布尔什维克合作，但很快又开始反对苏维埃政权。右派社会革命党人则始终敌视十月革命。1918—1920年外国武装干涉和内战时期，社会革命党人曾多次策划反革命的破坏活动，策动富农叛乱，暗害共产党和苏维埃国家的领导人。内战结束后，它继续进行反革命活动，被苏维埃政权粉碎。〕吗？社会革命党人当然比立宪民主党人“好些”，他们的纲领也是“合适的”、几乎是农民的纲领。可是，既然社会革命党人想单单依靠农民，既然他们在成为敌人力量的主要泉源的城市中软弱无力，那么，他们能够干出什么事情呢？什么地方有一个新的力量，它无论在农村或城市中都能一往直前，勇敢地走到前列去同沙皇和地主作斗争，帮助农民摆脱奴役，摆脱没有土地的情况，摆脱压迫，摆脱战争呢？当时在俄国究竟有没有这样的力量呢？是的，是有的。这就是俄国无产阶级，它还在1905年就已经显示出自己的力量、自己的斗争到底的本领、自己的勇气、自己的革命性。","language":"中文","translation":false},{"id":"foundations-1-239","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":239,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"无论如何，除了这个力量以外，别的力量是没有的，而且是无从得到的。","language":"中文","translation":false},{"id":"foundations-1-240","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":240,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，农民在离开立宪民主党人而接近社会革命党人以后，就觉悟到必须服从俄国无产阶级这个勇敢的革命领袖的领导。","language":"中文","translation":false},{"id":"foundations-1-241","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":241,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"决定俄国资产阶级革命的独特性的情况就是这样。","language":"中文","translation":false},{"id":"foundations-1-242","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":242,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(3)无产阶级革命时期的农民。这个时期从二月革命（1917年）到十月革命（1917年）为止。这个时期比较短，总共只有八个月；但是从群众所受到的政治教育和革命训练来看，可以大胆地说，这八个月等于平常宪制发展时期的好几十年，因为这八个月是革命的八个月。这个时期的特点就是农民更加革命化，他们对社会革命党人感到失望，他们离开社会革命党人，他们重新转向直接团结在无产阶级的周围，认定无产阶级是能把国家导向和平的唯一彻底革命的力量。这个时期的历史是社会革命党人（小资产阶级民主派）和布尔什维克（无产阶级民主派）争夺农民、争取掌握多数农民的历史。决定这个斗争的命运的，是联合政府时期，克伦斯基统治时期，社会革命党人和孟什维克拒绝没收地主土地，社会革命党人和孟什维克争取继续作战，前线六月进攻，士兵死刑，科尔尼洛夫叛乱〔注：科尔尼洛夫叛乱指1917年8月间俄国资产阶级和地主策划的一次反革命叛乱。指挥这次叛乱的是资产阶级临时政府任命的俄国军队最高总司令、沙皇将军拉·格·科尔尼洛夫，准备叛乱的中心是设在莫吉廖夫的大本营。资产阶级临时政府是准备这次叛乱的同谋者。科尔尼洛夫于8月25日调集军队，企图占领彼得格勒，消灭苏维埃，建立反革命军事独裁政府。布尔什维克党组织工人和革命士兵奋起保卫革命，于8月底粉碎了这次叛乱。〕。","language":"中文","translation":false},{"id":"foundations-1-243","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":243,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"如果说从前，在前一时期，革命的基本问题是推翻沙皇和地主政权，那么现在，在二月革命以后的时期，当沙皇已经被推翻，而旷日持久的战争已经使国家经济完全破坏，使农民完全破产的时候，消灭战争的问题就成为革命的基本问题了。重心显然已经从纯粹国内性质的问题移到基本问题，即战争问题上了。“结束战争”，“摆脱战争”，——这就是疲惫不堪的全国人民首先是农民的共同呼声。","language":"中文","translation":false},{"id":"foundations-1-244","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":244,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是当时要摆脱战争，就必须推翻临时政府，必须推翻资产阶级的政权，必须推翻社会革命党人和孟什维克的政权，因为他们，而且只有他们，要把战争拖延到“胜利为止”。当时除了推翻资产阶级，实际上没有别的出路可以摆脱战争。","language":"中文","translation":false},{"id":"foundations-1-245","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":245,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这是新的革命，无产阶级的革命，因为它把帝国主义资产阶级的最后一个派别，帝国主义资产阶级的极左派，即社会革命党和孟什维克党抛出政权以外，以便创立新的无产阶级的政权，即苏维埃政权，以便使革命无产阶级的党，主张进行革命斗争以反对帝国主义战争而争取民主和平的党，即布尔什维克党掌握政权。大多数农民支持了工人为争取和平、为苏维埃政权而进行的斗争。","language":"中文","translation":false},{"id":"foundations-1-246","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":246,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"当时在农民面前没有别的出路，而且不可能有别的出路。","language":"中文","translation":false},{"id":"foundations-1-247","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":247,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这样，克伦斯基统治时期给了劳动农民群众一个最大的实际教训，因为它明明白白地指出：在社会革命党人和孟什维克的政权下，国家是不能摆脱战争的，农民是既得不到土地，也得不到自由的；孟什维克和社会革命党人与立宪民主党人不同的地方只在于他们有甜蜜的演说和虚伪的诺言，而事实上他们所执行的还是那个帝国主义的立宪民主党的政策；只有苏维埃政权才是唯一能够引导国家走上大道的政权。战争的继续拖延只是证实了这个教训的正确，督促革命前进，推动千百万农民和士兵群众直接团结在无产阶级革命的周围。社会革命党人和孟什维克的孤立已成为确定不移的事实。如果没有联合政府时期的实际教训，就不可能有无产阶级专政。","language":"中文","translation":false},{"id":"foundations-1-248","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":248,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"促使资产阶级革命转变为无产阶级革命的情况就是这样。","language":"中文","translation":false},{"id":"foundations-1-249","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":249,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"俄国无产阶级专政就是这样形成的。","language":"中文","translation":false},{"id":"foundations-1-250","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":250,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(4)苏维埃政权巩固后的农民。如果说从前，在革命的第一个时期，主要问题是推翻沙皇制度，而后来，在二月革命以后，首要问题是推翻资产阶级以摆脱帝国主义战争；那么现在，在国内战争结束以后，在苏维埃政权巩固以后，经济建设问题就成为首要问题了。加强和发展国有化工业；为了达到这个目的而通过国家所调节的商业把工业和农民经济联系起来；用粮食税代替余粮收集制，以便后来逐渐减少粮食税额，做到用工业品去交换农产品；振兴商业并发展合作社，吸引千百万农民参加合作社，——这就是列宁为建立社会主义经济的基础而制定的经济建设方面的当前任务。","language":"中文","translation":false},{"id":"foundations-1-251","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":251,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"有人说，这个任务也许是俄国这样一个农民国家所不能胜任的。有些爱怀疑的人甚至说，这个任务简直是空想，是无法实现的，因为农民总是农民，——农民是由小生产者组成的，因此不能利用他们来建立社会主义生产的基础。","language":"中文","translation":false},{"id":"foundations-1-252","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":252,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"但是，爱怀疑的人错了，因为他们没有估计到在这里有决定意义的一些情况。我们现在就来看看其中主要的情况。","language":"中文","translation":false},{"id":"foundations-1-253","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":253,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一，决不可把苏联农民和西方农民混为一谈。苏联农民不能不和西方农民有所区别，因为苏联农民经过了三次革命的训练，跟无产阶级一起并在无产阶级领导下进行了反对沙皇和资产阶级政权的斗争，从无产阶级革命手里获得了土地与和平，并因此成为无产阶级的后备军；西方农民却是在资产阶级革命时代在自由资产阶级领导下进行了斗争，从这个资产阶级手里获得了土地，并因此成为资产阶级的后备军。未必用得着证明：向来珍视他们同无产阶级的政治友谊和政治合作并把他们获得自由归功于这种友谊和这种合作的苏联农民，不会不是无产阶级实行经济合作的最好对象。","language":"中文","translation":false},{"id":"foundations-1-254","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":254,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"恩格斯曾经说：“社会党夺取政权已成为最近将来的事情”，“为了夺取政权，这个政党应当首先从城市跑到农村，应当成为农村中的力量”。（见恩格斯《农民问题》1922年版[16]）他的这一段话是十九世纪九十年代写的，他当时所指的是西方农民。俄国共产党人在三次革命中在这方面做了巨大的工作，已经在农村中给自己造成了我们的西方同志所不敢梦想的影响和支柱，这一点还需要证明吗？这个情况不能不根本促进俄国工人阶级和农民实行经济合作的事业，这一点怎么能否认呢？","language":"中文","translation":false},{"id":"foundations-1-255","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":255,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"爱怀疑的人硬说小农是和社会主义建设不能相容的因素。可是，请听一听恩格斯关于西方小农所说的话吧：","language":"中文","translation":false},{"id":"foundations-1-256","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":256,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“而我们则坚决站在小农方面；我们将竭力设法使他们的命运较为过得去一些，如果他们下决心的话，就使他们易于过渡到协作社，如果他们还不能下决心，那就甚至给他们一些时间，让他们在自己的小块土地上考虑考虑这个问题。我们所以要这样做，不仅是因为我们认为自食其力的小农可能来补充我们的队伍，而且也是为了党的直接利益。被我们挽救而没有真正转变为无产者，还在农民地位时就被我们吸收到自己方面来的农民人数愈多，社会改造的实现也就会愈迅速和愈容易。我们无须等到资本主义生产发展的后果到处都以极端形式表现出来的时候，等到最后一个小手工业者和最后一个小农都变成资本主义大生产的牺牲品的时候，才来实现这个改造。我们在这方面为了农民的利益而必须牺牲一些社会资金，这从资本主义经济的观点看来好象是白费金钱，然而这却是善于投资，因为这种物质牺牲可能使花在整个社会改造上的费用节省十分之九。因此，在这个意义上说来，我们可以很慷慨地对待农民。”","language":"中文","translation":false},{"id":"foundations-1-257","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":257,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"恩格斯说这些话时所指的是西方农民。可是，恩格斯所说的这些话在任何地方都不能象在无产阶级专政的国家那样容易和那样充分地实现，这难道还不明显吗？只有在苏维埃俄国，才能立刻实行并完全实行使“自食其力的小农来补充我们的队伍”，实行为此所必需的“物质牺牲”，实行为此所必需的“慷慨地对待农民”，而且有利于农民的诸如此类的措施已经在俄国实行，这难道还不明显吗？这个情况也一定会便利并推进苏维埃国家的经济建设事业，这一点怎么能否认呢？","language":"中文","translation":false},{"id":"foundations-1-258","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":258,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二，决不可把俄国农业和西方农业混为一谈。西方农业是按照通常的资本主义道路发展的，是在农民深刻分化的情况下发展的，一极是大田庄和私人资本主义大地产，另一极却是大众的贫穷困苦和雇佣奴隶地位。因此，在西方，解体和分化是十分自然的。在俄国却不是这样。我国农业是不能循着这样的道路去发展的，因为单是苏维埃政权的存在和基本生产工具与生产资料国有化的事实就不容许循着这条道路去发展。俄国农业应当循着另一条道路，即循着使千百万小农和中农合作化的道路，循着在农村中发展那种由国家以优惠贷款的办法来扶持的群众性的合作社的道路去发展。列宁在论合作制的论文中正确地指出我国农业应当循着新道路去发展，即循着通过合作社吸引多数农民来参加社会主义建设的道路，循着把集体制原则逐步应用于农业，起初应用于农产品销售方面，然后应用于农产品生产方面这一道路去发展。","language":"中文","translation":false},{"id":"foundations-1-259","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":259,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在这方面，由于农业合作社工作而在农村中发生的一些新现象是非常值得注意的。大家知道，在农业合作总社[17]内产生了各个农业部门（亚麻、马铃薯、油类等部门）的新的巨大组织，这些组织是有广大前途的。例如其中的亚麻合作总社包括许多麻农生产协作社。亚麻合作总社以种子和生产工具供给农民，然后向这些农民购买全部亚麻产品，在市场上大批销售；保证农民也得到利润，从而通过农业合作总社把农民经济和国家工业联系起来。怎样称呼这种生产组织形式呢？在我看来，这是国家社会主义大生产在农业方面的家庭手工制。这里所说的国家社会主义生产在农业方面的家庭手工制，是和资本主义的家庭手工制，例如纺织业的家庭手工制相比拟而说的；在资本主义的家庭手工制中，手工业者从资本家那里领得原料和工具，而把自己的全部生产品交给资本家，所以他们事实上是在家里做工的半雇佣工人。这不过是指明我国农业应当循着哪一条道路发展的许多标志之一。其他农业部门中的其他类似的标志，我就不谈了。","language":"中文","translation":false},{"id":"foundations-1-260","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":260,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"未必用得着证明：绝大多数农民乐意走这条新的发展道路，而抛开私人资本主义大地产和雇佣奴隶地位的道路，贫困和破产的道路。","language":"中文","translation":false},{"id":"foundations-1-261","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":261,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"请看列宁关于我国农业的发展道路所说的话吧：","language":"中文","translation":false},{"id":"foundations-1-262","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":262,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“国家支配着一切大生产资料，无产阶级掌握着国家政权，无产阶级和千百万小农及最小农结成联盟，无产阶级对农民的领导已有保证等等，难道这不是我们所需要的一切，难道这不是我们通过合作社，而且仅仅通过合作社，通过我们从前鄙视为买卖机关，并且现时在新经济政策下我们从某一方面也有理由加以鄙视的合作社来建成完全的社会主义社会所必需的一切吗？这还不是建成社会主义社会，但这已是建成社会主义社会所必需而且足够的一切。”（见“列宁全集”第四版第三十三卷第四二八页）","language":"中文","translation":false},{"id":"foundations-1-263","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":263,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁往下讲到必须给予合作社这个无产阶级专政条件下的“组织居民的新原则”和新的“社会制度”以财政支持和其他支持时继续说：","language":"中文","translation":false},{"id":"foundations-1-264","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":264,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“任何社会制度，只有在一定阶级的财政支持下才会产生。不待说，‘自由’资本主义的诞生曾花了许多万万卢布。目前我们应该特别加以支持的社会制度就是合作制度，这一点我们现在应该认识到并使它实现。但是支持合作社就应该是名副其实的支持，就是说，把这种支持仅仅了解为支持任何一种合作社的流转是不够的，而应该了解为支持确实有真正的居民群众参加的合作社的流转。”（见“列宁全集”第四版第三十三卷第四二九页）","language":"中文","translation":false},{"id":"foundations-1-265","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":265,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"所有这些情况说明什么呢？","language":"中文","translation":false},{"id":"foundations-1-266","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":266,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"说明爱怀疑的人是不对的。","language":"中文","translation":false},{"id":"foundations-1-267","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":267,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"说明列宁主义是对的，因为列宁主义把劳动农民群众看作无产阶级的后备军。","language":"中文","translation":false},{"id":"foundations-1-268","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":268,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"说明执掌政权的无产阶级能够运用而且应当运用这个后备军，以便把工业和农业结合起来，发展社会主义建设，为无产阶级专政建立过渡到社会主义经济所绝对必需的基础。","language":"中文","translation":false},{"id":"foundations-1-269","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":269,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于这个题目我来讲两个主要问题：","language":"中文","translation":false},{"id":"foundations-1-270","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":270,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）被压迫民族解放运动和无产阶级革命。","language":"中文","translation":false},{"id":"foundations-1-271","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":271,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(1)问题的提法。最近二十年来，民族问题发生了许多极重大的变化。第二国际时期的民族问题和列宁主义时期的民族问题远不是一回事。不仅按范围来说，而且按内在性质来说，它们都是大不相同的。","language":"中文","translation":false},{"id":"foundations-1-272","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":272,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，通常都把民族问题限制在主要和“文明”民族有关的问题的狭隘范围内。爱尔兰人、匈牙利人、波兰人、芬兰人、塞尔维亚人以及欧洲其他一些民族，——第二国际的活动家所关心的就是这些没有充分权利的民族的命运。而那些遭受最粗暴最残酷的民族压迫的千百万亚洲人民和非洲人民，通常都不放在他们的眼里。他们不敢把白种人和黑种人，“文明人”和“不文明人”相提并论。两三个空空洞洞、不痛不痒、竭力回避殖民地解放问题的决议，——这就是第二国际的活动家所能借以自夸的一切。现在，民族问题方面的这种两重性和不彻底性可以说已经被消灭了。列宁主义揭露了这种极不相称的现象，拆毁了横在白种人和黑种人，欧洲人和亚洲人，帝国主义的“文明”奴隶和“不文明”奴隶之间的墙壁，因而把民族问题和殖民地问题联结起来了。于是民族问题就由局部的和国内的问题变成了一般的和国际的问题，变成了附属国和殖民地被压迫民族摆脱帝国主义桎梏的世界问题。","language":"中文","translation":false},{"id":"foundations-1-273","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":273,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，民族自决原则通常都被曲解，往往把它缩小为民族自治权。第二国际的某些首领甚至把自决权变成文化自治权，就是说，被压迫民族有设立自己的文化机关的权利，而让全部政权仍旧掌握在统治民族手中。结果就使民族自决的思想有从反对兼并政策的工具变成替兼并政策辩护的工具的危险。现在，这种糊涂观念可以说已经被克服了。列宁主义扩大了民族自决的概念，把它解释为附属国和殖民地被压迫民族有完全分离的权利，各民族有成立独立国家的权利。于是就排除了把自决权解释为自治权来替兼并政策辩护的可能。于是民族自决原则就由欺骗群众的工具（在帝国主义战争时期，它无疑是被社会沙文主义者用来做这种工具的）变成了揭露一切帝国主义野心和沙文主义阴谋的工具，变成了用国际主义精神对群众进行政治教育的工具。","language":"中文","translation":false},{"id":"foundations-1-274","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":274,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，通常都把被压迫民族问题看做纯粹法的问题。冠冕堂皇地宣布“民族的平等权利”，发表无数关于“民族平等”的宣言，——这就是第二国际各党所心满意足的事情。它们抹杀了这样一个事实，就是在帝国主义时代，当某一些民族（少数）靠剥削另一些民族生存的时候，所谓“民族平等”不过是对于被压迫民族的嘲弄。现在，民族问题方面的这种资产阶级的法的观点可以说已经被揭穿了。列宁主义把民族问题从大吹大擂的宣言的天空拉到地上来，指出如果无产阶级政党不直接援助被压迫民族的解放斗争，“民族平等”的宣言就是空洞的虚伪的宣言。于是被压迫民族问题就成了支援，帮助，真正地经常地帮助被压迫民族反对帝国主义，争取真正的民族平等，争取成立独立国家的问题。","language":"中文","translation":false},{"id":"foundations-1-275","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":275,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"从前，通常都用改良主义的观点来看民族问题，把它看作一个单独的孤立的问题，看作和资本政权、推翻帝国主义、实现无产阶级革命这一总问题无关的问题。人们当时都默默地认为：欧洲无产阶级不和殖民地解放运动直接结成联盟也能取得胜利；民族殖民地问题可以离开无产阶级革命的大道，可以不进行反帝的革命斗争，而悄悄地“自流地”得到解决。现在，这种反革命的观点可以说已经被揭穿了。列宁主义已经证明，帝国主义战争和俄国革命也已经证实：民族问题只有和无产阶级革命相联系并在无产阶级革命的基础上才能得到解决，西方革命必须同殖民地和附属国反帝解放运动结成革命的联盟才能取得胜利。民族问题是无产阶级革命总问题的一部分，是无产阶级专政问题的一部分。","language":"中文","translation":false},{"id":"foundations-1-276","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":276,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"问题是这样：被压迫国家革命解放运动所含有的革命的可能性是否已经用完？如果还没有用完，是否有希望、有根据把这种可能性用于无产阶级革命，把附属国和殖民地国家由帝国主义资产阶级的后备军变为革命无产阶级的后备军，变为革命无产阶级的同盟者？","language":"中文","translation":false},{"id":"foundations-1-277","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":277,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义对这个问题的答复是肯定的，即认为被压迫国家民族解放运动含有革命能力，认为可以把这种革命能力用于推翻共同的敌人，用于推翻帝国主义。帝国主义发展的内幕、帝国主义战争和俄国革命完全证实了列宁主义关于这一点的结论。","language":"中文","translation":false},{"id":"foundations-1-278","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":278,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此可见，“统治”民族的无产阶级必须援助，必须坚决地积极地援助各被压迫民族和附属国人民的民族解放运动。","language":"中文","translation":false},{"id":"foundations-1-279","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":279,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这当然不是说，无产阶级在任何地方和任何时候，在每个具体情况下，都应当援助任何一种民族运动。这里所说的是要援助目的在于削弱帝国主义、推翻帝国主义，而不在于巩固和保持帝国主义的那种民族运动。有时候，个别被压迫国家的民族运动会和无产阶级运动发展的利益相冲突。不言而喻，在这种情况下是谈不到什么援助的。民族权利问题并不是一个独立自在的问题，而是无产阶级革命总问题的一部分，它服从整体，要求从整体的观点来观察。马克思在十九世纪四十年代拥护波兰人和匈牙利人的民族运动，而反对捷克人和南方斯拉夫人的民族运动。为什么呢？因为当时捷克人和南方斯拉夫人是“反动民族”，是欧洲的“俄国前哨”，是专制制度的前哨，而当时波兰人和匈牙利人却是反对专制制度的“革命民族”。因为当时援助捷克人和南方斯拉夫人的民族运动就是间接援助欧洲革命运动的最危险的敌人沙皇制度。","language":"中文","translation":false},{"id":"foundations-1-280","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":280,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“民主运动的个别要求，包括自决在内，并不是什么绝对的东西，而是世界一般民主主义（现在是整个社会主义）运动中的一部分。在个别的具体情况下，部分可能和总体相矛盾，那时就必须抛弃这一部分。”（见“列宁全集”第四版第二十二卷第三二六页）","language":"中文","translation":false},{"id":"foundations-1-281","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":281,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于个别的民族运动问题，关于这些运动可能具有的反动性问题（当然，如果不是从形式上，不是从抽象的法的观点，而是从革命运动的利益的观点来具体地估量这些运动）就是这样。","language":"中文","translation":false},{"id":"foundations-1-282","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":282,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于一般民族运动的革命性也应该这样说。极大多数民族运动所无疑具有的革命性，也和某些个别的民族运动所可能具有的反动性一样，是相对的和独特的。在帝国主义压迫的情况下，民族运动的革命性完全不一定要以这个运动有无产阶级分子参加、有革命的或共和的纲领、有民主的基础为前提。阿富汗的艾米尔为阿富汗独立而进行的斗争在客观上是革命的斗争，因为这个斗争能够削弱、瓦解和毁坏帝国主义，虽然阿富汗的艾米尔及其战友抱有君主制的观点；可是象克伦斯基和策烈铁里、列诺得尔和谢德曼、切尔诺夫和唐恩、韩德逊和克莱因斯这些“激烈的”民主主义者和“社会主义者”、“革命家”和共和主义者在帝国主义战争时期所进行的斗争却是反动的斗争，因为这个斗争的结果是粉饰并巩固帝国主义，使帝国主义取得胜利。埃及的商人和资产阶级知识分子为埃及独立而进行的斗争，由于同样的原因，在客观上也是革命的斗争，虽然埃及民族运动的首领是资产阶级出身，具有资产阶级身分，并反对社会主义；然而英国“工人”政府为保持埃及的附属地位而进行的斗争，由于同样的原因，却是反动的斗争，虽然这个政府的阁员是无产阶级出身，具有无产阶级身分，并“拥护”社会主义。更不必说其他较大的殖民地和附属国，如印度和中国的民族运动了。这些国家在争取解放的道路上的每一步骤，即使违反形式上的民主的要求，也是对帝国主义的一个非常沉重的打击，就是说，毫无疑问是革命的步骤。","language":"中文","translation":false},{"id":"foundations-1-283","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":283,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说得对，在估量被压迫国家的民族运动时不要以形式上的民主为标准，而要以反帝国主义斗争总结算中的实际结果为标准，就是说：“从世界范围来看，而不应当孤立地来看。”（见“列宁全集”第四版第二十二卷第三二六页）","language":"中文","translation":false},{"id":"foundations-1-284","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":284,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(2)被压迫民族解放运动和无产阶级革命。列宁主义在解决民族问题时是从下列原理出发的：","language":"中文","translation":false},{"id":"foundations-1-285","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":285,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）世界已经分成两个阵营：一个是拥有金融资本并剥削地球上绝大多数居民的为数极少的文明民族的阵营，另一个是组成这个绝大多数的殖民地和附属国被压迫被剥削民族的阵营；","language":"中文","translation":false},{"id":"foundations-1-286","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":286,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）被金融资本压迫和剥削的殖民地和附属国是帝国主义最巨大的后备力量和最重要的实力来源；","language":"中文","translation":false},{"id":"foundations-1-287","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":287,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丙）附属国和殖民地国家被压迫民族所进行的反帝革命斗争是他们摆脱压迫和剥削的唯一道路；","language":"中文","translation":false},{"id":"foundations-1-288","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":288,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丁）最重要的殖民地和附属国已经走上民族解放运动的道路，这个运动不能不引起全世界资本主义的危机；","language":"中文","translation":false},{"id":"foundations-1-289","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":289,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（戊）发达的国家的无产阶级运动和殖民地民族解放运动的利益，要求把这两种革命运动结合成一条反对共同的敌人、反对帝国主义的共同的战线；","language":"中文","translation":false},{"id":"foundations-1-290","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":290,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（已）如果不建立并巩固共同的革命战线，那么发达的国家中的工人阶级就不能胜利，被压迫民族就不能从帝国主义的桎梏下解放出来；","language":"中文","translation":false},{"id":"foundations-1-291","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":291,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（庚）如果压迫民族的无产阶级不直接而坚决地支援被压迫民族的解放运动来反对“本国的”帝国主义，那么就不可能建立共同的革命战线，因为“压迫其他民族的民族是不能获得解放的”（恩格斯）；","language":"中文","translation":false},{"id":"foundations-1-292","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":292,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（辛）这种援助就是坚持、维护和实行下列口号：民族有分离权，有成立独立国家的权利；","language":"中文","translation":false},{"id":"foundations-1-293","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":293,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（壬）不实行这个口号，就不能保证各民族在统一的世界经济中的联合和合作，而这种统一的世界经济是世界社会主义胜利的物质基础；","language":"中文","translation":false},{"id":"foundations-1-294","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":294,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（癸）这种联合只能是自愿的，是在各民族相互信任和友爱的基础上产生的。","language":"中文","translation":false},{"id":"foundations-1-295","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":295,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此就产生了民族问题上的两个方面，即两个趋向：一个趋向是在帝国主义压迫和殖民地剥削的基础上产生的，它力求在政治上摆脱帝国主义束缚而成立独立的民族国家；另一个趋向是因世界市场和世界经济的形成而产生的，它力求使各民族在经济上彼此接近。","language":"中文","translation":false},{"id":"foundations-1-296","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":296,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“在资本主义的发展过程中，可以看出在民族问题上有两个历史趋向。第一个趋向是民族生活和民族运动的觉醒，反对一切民族压迫的斗争，民族国家的建立。第二个趋向是民族之间各种联系的发展和日益频繁，民族壁垒的破坏，资本、整个经济生活、政治、科学等等的国际统一的形成。","language":"中文","translation":false},{"id":"foundations-1-297","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":297,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这两个趋向都是资本主义的世界规律。第一个趋向在资本主义发展初期占优势，第二个趋向标志着资本主义已经成熟，正在向社会主义社会转变。”（见“列宁全集”第四版第二十卷第十一页）","language":"中文","translation":false},{"id":"foundations-1-298","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":298,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"对于帝国主义，这两个趋向是一个不可调和的矛盾，因为帝国主义如果不剥削殖民地，如果不用暴力把殖民地束缚在“统一的整体”范围内，就不能生存；因为帝国主义只有靠兼并和夺取殖民地才能使各民族互相接近，否则它根本就不成其为帝国主义了。","language":"中文","translation":false},{"id":"foundations-1-299","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":299,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"对于共产主义，恰恰相反，这两个趋向不过是一个问题即被压迫民族摆脱帝国主义压迫这一问题的两个方面，因为共产主义知道：各民族在统一的世界经济中的联合，只有根据相互信任和自愿协定的原则才能实现；各民族的自愿联合，只有经过使殖民地从“统一的”帝国主义“整体”分离出来的道路，经过使殖民地变为独立国家的道路才能达到。","language":"中文","translation":false},{"id":"foundations-1-300","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":300,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因此，必须顽强地、不断地、坚决地反对各统治民族（英、法、美、意、日等）的“社会主义者”的大国沙文主义，这些“社会主义者”不愿意反对本国帝国主义政府，不愿意援助“他们的”殖民地被压迫民族的摆脱压迫、争取国家独立的斗争。","language":"中文","translation":false},{"id":"foundations-1-301","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":301,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不进行这样的斗争，就不能以真正的国际主义精神、以接近附属国和殖民地劳动群众的精神、以真正准备无产阶级革命的精神来教育统治民族的工人阶级。如果俄国无产阶级没有得到前俄罗斯帝国内各被压迫民族的同情和援助，那么俄国革命就不会胜利，而高尔察克和邓尼金也就不会被击溃。但是要取得这些民族的同情和援助，俄国无产阶级当时首先必须打断俄国帝国主义的锁链，使这些民族摆脱民族压迫。","language":"中文","translation":false},{"id":"foundations-1-302","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":302,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不这样做，就不能巩固苏维埃政权，就不能树立真正的国际主义，就不能建立各民族合作的卓越组织，这个组织叫做苏维埃社会主义共和国联盟，它是各民族将来在统一的世界经济中联合的实际榜样。","language":"中文","translation":false},{"id":"foundations-1-303","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":303,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因此，必须反对各被压迫国家社会党人的民族闭关自守、狭隘观点和隔离状态，这些社会党人不愿意超出自己的民族狭隘眼界，不了解本国解放运动和统治国无产阶级运动之间的联系。","language":"中文","translation":false},{"id":"foundations-1-304","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":304,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不进行这样的斗争，就不能保持被压迫民族无产阶级的独立政策，就不能保持它和统治国无产阶级在推翻共同的敌人、推翻帝国主义的斗争中的阶级团结。","language":"中文","translation":false},{"id":"foundations-1-305","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":305,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不进行这样的斗争，就不能实现国际主义。","language":"中文","translation":false},{"id":"foundations-1-306","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":306,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这就是以革命的国际主义精神来教育统治民族和被压迫民族的劳动群众的道路。","language":"中文","translation":false},{"id":"foundations-1-307","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":307,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"请看列宁对于共产主义运动以国际主义精神教育工人的这个两方面的工作是怎样说的：","language":"中文","translation":false},{"id":"foundations-1-308","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":308,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“这种教育工作……在压迫的大民族中和被压迫的小民族中，在兼并的民族中和被兼并的民族中，能够具体地相同吗？","language":"中文","translation":false},{"id":"foundations-1-309","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":309,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"显然不能。要达到使一切民族完全平等、密切接近和进而融合为一的共同目的，显然要走各不相同的具体道路，就拿达到一张纸的中心点的方法来说吧，可以从纸的一端向左走，也可以从纸的相对的一端向右走，反正都会达到。如果压迫的、兼并的大民族中的社会民主党人仅仅一般地鼓吹民族融合，而忘记了，哪怕是一分钟忘记了‘他的’尼古拉二世、‘他的’威廉、乔治、彭加勒等等也主张和小民族融合（用兼并手段），忘记了尼古拉二世主张和加里西亚‘融合’、威廉二世主张和比利时‘融合’等等，那么，这样的社会民主党人在理论上是可笑的学理主义者，在实践上是帝国主义的帮凶。","language":"中文","translation":false},{"id":"foundations-1-310","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":310,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在压迫国家里，工人的国际主义教育的重心必须是宣传并且要工人坚持被压迫国家有分离的自由。不这样，就没有国际主义。如果压迫民族的任何一个社会民主党人不进行这种宣传，那么我们就可以而且应该鄙视他，把他看作帝国主义者，看作坏分子。这是绝对的要求，哪怕在社会主义未实现以前，分离的机会只有千分之一是可能的和‘可以实现的’。……","language":"中文","translation":false},{"id":"foundations-1-311","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":311,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"相反地，小民族的社会民主党人应当以我们这个总公式——各民族‘自愿联合’的末尾两个字为其鼓动工作的重心。他既可以赞成本民族的政治独立，又可以赞成本民族加入邻近某个国家，同时又不违反他的作为国际主义者的义务。可是，他在任何场合都应当反对小民族的狭隘观点、闭关自守和隔离状态，而主张顾全整体和总体、部分利益服从全体利益。","language":"中文","translation":false},{"id":"foundations-1-312","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":312,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不仔细考虑问题的人，会以为压迫民族的社会民主党人坚持‘分离自由’而被压迫民族的社会民主党人坚持‘联合自由’是‘矛盾的’。可是，只要稍微思索一下，就可以知道要达到国际主义和民族融合这一目的，，除了实行这个原理以外，是没有而且不可能有其他道路的。”（见“列宁全集”第四版第二十二卷第三三○页至第三三二页）","language":"中文","translation":false},{"id":"foundations-1-313","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":313,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于这个题目我来讲六个问题：","language":"中文","translation":false},{"id":"foundations-1-314","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":314,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）战略和策略是指导无产阶级阶级斗争的科学；","language":"中文","translation":false},{"id":"foundations-1-315","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":315,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）革命的阶段和战略；","language":"中文","translation":false},{"id":"foundations-1-316","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":316,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（丙）运动的来潮退潮和策略；","language":"中文","translation":false},{"id":"foundations-1-317","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":317,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（已）改良主义和革命主义。","language":"中文","translation":false},{"id":"foundations-1-318","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":318,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(1)战略和策略是指导无产阶级阶级斗争的科学。第二国际统治时期主要是在比较和平发展的环境中编制和训练无产阶级政治军队的时期。这是把议会制度当作阶级斗争的主要形式的时期。当时关于大规模的阶级冲突的问题、关于训练无产阶级去进行革命搏斗的问题、关于争取无产阶级专政的道路问题似乎都不是迫切的问题。当时的任务只是要利用一切合法的发展道路来编制和训练无产阶级军队，以适应无产阶级处于在野党地位并且似乎应当处于在野党地位的条件来利用议会制度。几乎用不着证明，在这样的时期和这样了解无产阶级任务的情况下，既不可能有完整的战略，也不可能有周密的策略。当时只有关于策略和战略的一些片断的零碎的观念，但是没有策略和战略。","language":"中文","translation":false},{"id":"foundations-1-319","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":319,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二国际的滔天罪行并不在于它当时实行了利用议会斗争形式的策略，而在于它夸大了这种斗争形式的意义，几乎把这种斗争形式看作唯一的斗争形式。而当公开的革命搏斗时期到来的时候，当议会外斗争形式问题已经成为首要的迫切问题的时候，第二国际各党竟避开了新的任务，不去接受这些任务。","language":"中文","translation":false},{"id":"foundations-1-320","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":320,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"只有在下一个时期，无产阶级公开发动的时期，无产阶级革命的时期，当推翻资产阶级的问题已经成为直接的实践问题的时候，当无产阶级的后备军问题（战略）已经成为一个最迫切的问题的时候，当一切斗争形式和组织形式——议会形式和议会外形式（策略）已经十分明显地表现出来的时候，——只有在这个时期，才能制定无产阶级斗争的完整的战略和周密的策略。马克思和恩格斯的被第二国际机会主义者埋没了的那些关于策略和战略的英明思想，正是在这个时期被列宁发掘出来重见天日的。但是列宁并不限于恢复马克思和恩格斯的个别策略原理。他还向前发展了这些原理，补充了一些新的思想和原理，把这一切结合为指导无产阶级阶级斗争的规则和指导原则的体系。列宁的《怎么办？》、《两种策略》、《帝国主义》、《国家与革命》、《无产阶级革命和叛徒考茨基》以及《幼稚病》等书无疑是加进马克思主义的总宝库，马克思主义的革命武库的最宝贵的贡献。列宁主义的战略和策略是指导无产阶级革命斗争的科学。","language":"中文","translation":false},{"id":"foundations-1-321","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":321,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(2)革命的阶段和战略。战略就是规定无产阶级在革命某一阶段上的主要的打击方向，制定革命力量（主要的和次要的后备军）的相应的布置计划，在革命这一阶段的整个过程中为实现这个计划而斗争。","language":"中文","translation":false},{"id":"foundations-1-322","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":322,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"我们的革命已经过两个阶段，十月革命后已进入第三个阶段。与此相适应，战略也有过变更。","language":"中文","translation":false},{"id":"foundations-1-323","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":323,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一个阶段。1903—1917年2月。目的是推翻沙皇制度，彻底消灭中世纪制度的残余。革命的基本力量是无产阶级。最亲近的后备军是农民。主要的打击方向是孤立自由君主派资产阶级，这个资产阶级力图抓住农民并用和沙皇制度妥协的方法来消灭革命。力量的布置计划是工人阶级和农民联盟。“无产阶级应当把民主革命进行到底，这就要把农民群众联合到自己方面来，以便用强力打破专制制度的反抗，并麻痹资产阶级的不稳定性。”（见“列宁全集”第四版第九卷第八十一页）","language":"中文","translation":false},{"id":"foundations-1-324","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":324,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二个阶段。1917年3月—1917年10月。目的是推翻俄国的帝国主义，摆脱帝国主义战争。革命的基本力量是无产阶级。最亲近的后备军是贫苦农民。邻国无产阶级是可能的后备军。旷日持久的战争和帝国主义的危机是有利的时机。主要的打击方向是孤立小资产阶级民主派（孟什维克、社会革命党人），这个民主派力图抓住劳动农民群众并用和帝国主义妥协的方法来结束革命。力量的布置计划是无产阶级和贫苦农民联盟。“无产阶级应当实现社会主义革命，这就要把居民中的半无产者群众联合到自己方面来，以便用强力打破资产阶级的反抗，并麻痹农民和小资产阶级的不稳定性。”（见“列宁全集”第四版第九卷第八十一页）","language":"中文","translation":false},{"id":"foundations-1-325","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":325,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第三个阶段。这个阶段是在十月革命后开始的。目的是在一国内巩固无产阶级专政，运用这个专政作为据点，以便在世界各国推翻帝国主义。革命已经超出一国范围，世界革命的时代已经开始。革命的基本力量是一国的无产阶级专政，世界各国无产阶级的革命运动。主要的后备军是发达的国家的半无产阶级群众和小农群众，殖民地和附属国的解放运动。主要的打击方向是孤立小资产阶级民主派，孤立第二国际各党，这些党是和帝国主义妥协这一政策的基本支柱。力量的布置计划是无产阶级革命和殖民地、附属国的解放运动联盟。","language":"中文","translation":false},{"id":"foundations-1-326","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":326,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"战略是和革命的基本力量及其后备军有关的。战略因革命由一个阶段转入另一阶段而变更，而在某一阶段的整个时期基本上是不变的。","language":"中文","translation":false},{"id":"foundations-1-327","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":327,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(3)运动的来潮退潮和策略。策略就是规定无产阶级在运动的来潮或退潮、革命的高涨或低落这个较短时期内的行动路线，就是通过以新的斗争形式和组织形式代替旧的斗争形式和组织形式，以新的口号代替旧的口号，通过把这些形式配合起来等等来为实现这条路线而斗争。战略的目的，比如说，是要取得反对沙皇制度的战争或反对资产阶级的战争的胜利，把反对沙皇制度的斗争或反对资产阶级的斗争进行到底，而策略的目的却没有这样重大，因为策略并不是要取得整个战争的胜利，而是要取得某些战役、某些战斗的胜利，有成效地实行某些适合于革命某一高涨或低落时期的具体情况的运动和发动。策略是战略的一部分，是服从于战略的，是服务于战略的。策略是随着来潮退潮而变更的。在革命第一阶段的时期内（1903—1917年2月），战略计划始终没有变更，策略却变更过几次。在1903—1905年的时期，党的策略是进攻的，因为当时革命处于来潮，运动是上升的，策略应当以这个事实为出发点。与此相适应，斗争形式也是革命的，是适合于革命来潮的要求的。地方的政治罢工、政治示威、政治总罢工、抵制杜马、起义和革命战斗口号就是这个时期内互相代替的斗争形式。当时的组织形式也因斗争形式的变更而变更了。工厂委员会、农民革命委员会、罢工委员会、工人代表苏维埃和比较公开的工人政党就是这个时期内的组织形式。","language":"中文","translation":false},{"id":"foundations-1-328","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":328,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在1907—1912年的时期，党不得不转而采取退却的策略，因为当时革命运动低落，革命处于退潮，策略不能不估计到这个事实。与此相适应，斗争形式和组织形式也变更了。不是抵制杜马，而是参加杜马；不是杜马外的公开的革命发动，而是杜马内的发动和杜马内的工作；不是政治总罢工，而是局部经济罢工，或者简直无声无息。当然，党在这个时期内应该转入地下活动，而群众的革命组织也就由文化教育组织、合作社组织、保险会组织以及其他合法组织代替了。","language":"中文","translation":false},{"id":"foundations-1-329","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":329,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于革命的第二个阶段和第三个阶段也应该这样说，在这两个阶段中，策略变更过几十次，战略计划却始终没有变更。","language":"中文","translation":false},{"id":"foundations-1-330","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":330,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"策略是同无产阶级的斗争形式和组织形式有关的，是同这些形式的交替和配合有关的。策略在革命的某一阶段上可以随着革命的来潮或退潮、革命的高涨或低落而变更好几次。","language":"中文","translation":false},{"id":"foundations-1-331","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":331,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(4)战略指导。革命的后备军有两种：","language":"中文","translation":false},{"id":"foundations-1-332","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":332,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"直接的：（一）本国的农民以至所有过渡阶层，（二）邻国的无产阶级，（三）殖民地和附属国的革命运动，（四）无产阶级专政的胜利品和成果，而无产阶级为了收买强大的敌人并取得喘息时机，可以在保持自己的实力优势的条件下暂时放弃一部分胜利品和成果；","language":"中文","translation":false},{"id":"foundations-1-333","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":333,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"间接的：（一）本国各个非无产阶级之间的矛盾和冲突，这些矛盾和冲突是无产阶级可以利用来削弱敌人并加强自己的后备军的，（二）和无产阶级国家敌对的各个资产阶级国家之间的矛盾、冲突和战争（例如帝国主义战争），这些矛盾、冲突和战争是无产阶级在进攻时或者在被迫退却相机行事时可以利用的。","language":"中文","translation":false},{"id":"foundations-1-334","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":334,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于第一种后备军用不着多说，因为它们的意义是大家都知道的。至于第二种后备军，因为它们的意义并不是任何时候都很明显的，所以必须指出，它们有时候对于革命进程具有头等的意义。例如第一次革命时期和第一次革命后小资产阶级民主派（社会革命党人）和自由君主派资产阶级（立宪民主党人）之间的冲突的巨大意义是未必可以否认的，因为这种冲突在使农民摆脱资产阶级影响这件事情上无疑起了相当的作用。十月革命时期各主要帝国主义者集团之间进行决死的战争这一事实的巨大意义更是不可否认的，当时帝国主义者忙于相互之间的战争，没有可能集中力量来反对年轻的苏维埃政权，正因为如此，无产阶级就有可能来切实地组织自己的力量，巩固自己的政权，并准备扑灭高尔察克和邓尼金。现在，当帝国主义集团之间的矛盾日益加深，当它们彼此之间的新战争不可避免的时候，这种后备军对于无产阶级一定会有愈益重大的意义。","language":"中文","translation":false},{"id":"foundations-1-335","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":335,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"战略指导的任务就是要正确运用这一切后备军来达到革命在某一发展阶段上的基本目的。","language":"中文","translation":false},{"id":"foundations-1-336","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":336,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"怎样才是正确运用后备军呢？","language":"中文","translation":false},{"id":"foundations-1-337","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":337,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就是要执行一些必要的条件，其中主要的是：","language":"中文","translation":false},{"id":"foundations-1-338","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":338,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一，当革命时机已经成熟，当进攻在以全力进行，当起义已经迫在眉睫，当使后备军跟上先锋队已经成为决定胜负的条件的时候，在这个决定关头，要把革命的主要力量集中在敌人最易致命的地方。党在1917年4—10月这一时期的战略可以说是这样运用后备军的实例。毫无疑问，这个时期敌人最易致命的地方是战争。毫无疑问，党正是在这个基本问题上把广大群众集合到无产阶级先锋队的周围。党在这个时期的战略就是通过游行示威来训练先锋队去进行街头的发动，同时通过后方的苏维埃和前线的士兵委员会使后备军跟上先锋队。革命的结局表明，当时后备军是运用得正确的。","language":"中文","translation":false},{"id":"foundations-1-339","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":339,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁在谈到革命力量的战略运用这个条件时，把马克思和恩格斯关于武装起义的著名原理变动了一下说：","language":"中文","translation":false},{"id":"foundations-1-340","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":340,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“（1）无论何时不要把起义当做儿戏，在开始起义时就要切实懂得，必须把它进行到底。","language":"中文","translation":false},{"id":"foundations-1-341","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":341,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（2）必须在决定的地点，在决定的关头，集中很大的优势力量，否则，更有准备、更有组织的敌人就会把起义者消灭。","language":"中文","translation":false},{"id":"foundations-1-342","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":342,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（3）既然起义已经开始，就必须以最大的决心行动起来并坚决转入进攻。‘防御是武装起义的死路’。","language":"中文","translation":false},{"id":"foundations-1-343","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":343,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（4）必须抓住时机，趁敌军还分散的时候，出其不意地袭击他们。","language":"中文","translation":false},{"id":"foundations-1-344","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":344,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（5）每天（如果以一个城市来说，可以说每一小时）都必须力求获得胜利，即使是小小的胜利也好，无论如何要保持‘精神上的优势’。”（见“列宁全集”第四版第二十六卷第一五二页）","language":"中文","translation":false},{"id":"foundations-1-345","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":345,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二，要选择危机已经达到顶点、先锋队已经具有战斗到底的决心、后备军已经具有援助先锋队的决心、敌人内部已经极端慌乱的时机作为实行致命打击的时机，开始起义的时机。","language":"中文","translation":false},{"id":"foundations-1-346","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":346,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：决战时机可以说完全成熟了，如果“(1)一切敌视我们的阶级力量已经十分混乱，彼此之间的厮杀已经十分厉害，由于进行力不胜任的斗争已经十分疲惫”；如果“(2)一切犹豫的、动摇的、不坚定的中间分子，即和资产阶级不同的小资产阶级，小资产阶级民主派，已经在人民面前充分暴露自己，由于实际破产而大丢其丑”；如果“(3)在无产阶级中，群众支持采取最坚决、最奋勇的革命行动来反对资产阶级的情绪，已经开始产生并且大大地高涨起来。那时候，革命就成熟了；那时候，如果我们正确地估计到上面所指出的……一切条件，并且正确地选定时机，我们的胜利就有保证了”。（见“列宁全集”第四版第三十一卷第七十四页）","language":"中文","translation":false},{"id":"foundations-1-347","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":347,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"举行十月起义可以说是这种战略的模范。","language":"中文","translation":false},{"id":"foundations-1-348","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":348,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"违背这个条件，就会造成危险的错误，即所谓“失其速度”，就是说，党就会落在运动进程的后面，或者向前跑得太远，因而造成失败的危险。有一部分同志在1917年9月企图从逮捕民主会议〔注：民主会议，于1917年9月14—22日（公历9月27日—10月5日）在彼得格勒举行。会议是由工兵代表苏维埃全俄中央执行委员会和农民代表苏维埃执行委员会中的孟什维克和社会革命党领袖们召集的。参加会议的有各社会主义政党、苏维埃、工会、地方自治局、工商业界和军队中的妥协派代表。会上产生了临时政府的谘议机关——预备议会（共和国临时议会）。孟什维克和社会革命党人想利用它来制止日益高涨的革命运动，使俄国从苏维埃革命的道路转到资产阶级议会制度的道路上去。〕代表来开始起义，可以说是这种“失其速度”的例子，不善于选择起义时机的例子，因为当时在苏维埃内部还有动摇情绪，前线还犹豫不决，后备军还没有跟上先锋队。","language":"中文","translation":false},{"id":"foundations-1-349","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":349,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第三，要越过前进道路上的种种阻难和障碍，一往直前地实行既定的方针，只有这样，才能使先锋队不致失去斗争的基本目的，使群众不致迷失道路，而能向着这个目的前进并努力团结在先锋队的周围。违背这个条件，就会造成莫大的错误，即海员们所熟悉的所谓“失其方向”。我们党在紧接民主会议以后所采取的决定参加预备议会这一错误的步骤，可以说是这种“失其方向”的例子。当时党似乎忘记了预备议会是资产阶级企图把国家从苏维埃道路转到资产阶级议会制度道路上去的手腕，党参加这种机关就会打乱全部计划，就会使那些在“全部政权归苏维埃！”的口号下进行革命斗争的工农迷失道路。这个错误因为布尔什维克退出预备议会而被纠正了。","language":"中文","translation":false},{"id":"foundations-1-350","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":350,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第四，当敌人力量强大，当退却不可避免，当接受敌人的挑战显然对自己不利，当在一定的力量对比下退却是使先锋队免受打击并保存其后备军的唯一手段的时候，要机动调度后备军来实行正确的退却。","language":"中文","translation":false},{"id":"foundations-1-351","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":351,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“革命政党应当补课。它们学习过进攻。现在应当了解，除了学会进攻以外，还必须学会正确地退却。必须了解，——而且革命阶级已经从本身的沉痛经验中领会到，——不学会正确的进攻和正确的退却，要取得胜利是不可能的。”（见“列宁全集”第四版第三十一卷第十一页至第十二页）","language":"中文","translation":false},{"id":"foundations-1-352","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":352,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这种战略的目的就是要赢得时间，瓦解敌人，养精蓄锐，以便后来转为进攻。","language":"中文","translation":false},{"id":"foundations-1-353","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":353,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"缔结布列斯特和约〔注：布列斯特和约，指1918年3月3日苏维埃俄国在布列斯特－里托夫斯克同德国、奥匈帝国、保加利亚、土耳其四国签订的条约。签订这个条约，是当时新建立的苏维埃政权为了退出帝国主义战争、集中力量巩固十月革命取得的胜利而采取的一种革命的妥协。按照这个和约，苏维埃俄国丧失约一百万平方公里的领土，并要付出巨额赔款。由于签订了和约，年轻的苏维埃政权赢得了时间，从而能巩固无产阶级专政，整顿国家经济并建立红军，为后来战胜白卫军和帝国主义武装干涉创造了条件。1918年11月13日，即协约国对德停战协定签字后两天，全俄中央执行委员会宣布废除了布列斯特和约。〕可以说是这种战略的模范。这个和约使党有可能赢得时间，利用帝国主义阵营中的冲突，瓦解敌人的力量，为自己保留农民，养精蓄锐准备向高尔察克和邓尼金进攻。","language":"中文","translation":false},{"id":"foundations-1-354","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":354,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"当时列宁说：“我们缔结单独和约，就能在目前可能的最大程度上摆脱两个彼此敌对的帝国主义集团，利用它们相互之间的敌视和战争，——这种敌视和战争阻碍它们勾结起来反对我们，——取得一定时期的行动自由，来继续进行和巩固社会主义革命。”（见“列宁全集”第四版第二十六卷第四○七页）","language":"中文","translation":false},{"id":"foundations-1-355","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":355,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"布列斯特和约签订后过了三年，列宁说：“现在就连头号傻瓜也看得见，‘布列斯特和约’这个让步加强了我们的实力，分散了国际帝国主义的力量。”(见“列宁全集”第四版第三十三卷第四页)","language":"中文","translation":false},{"id":"foundations-1-356","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":356,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"保证有正确的战略指导的主要条件就是这样。","language":"中文","translation":false},{"id":"foundations-1-357","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":357,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(5)策略指导。策略指导是战略指导的一部分，是服从战略指导的任务和要求的。策略指导的任务就是要掌握无产阶级的一切斗争形式和组织形式，保证这些形式的正确运用，以便在一定的力量对比下取得为准备战略胜利所必需的最大成果。","language":"中文","translation":false},{"id":"foundations-1-358","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":358,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"怎样才是正确运用无产阶级的斗争形式和组织形式呢？","language":"中文","translation":false},{"id":"foundations-1-359","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":359,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"就是要执行一些必要的条件，其中主要的是：","language":"中文","translation":false},{"id":"foundations-1-360","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":360,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第一，要把这样一种斗争形式和组织形式提到第一位，这种形式最适合于当时运动的来潮或退潮的条件，能够促进和保证把群众引到革命阵地上，把千百万群众引到革命战线上，把群众配置在革命战线上。","language":"中文","translation":false},{"id":"foundations-1-361","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":361,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"问题并不是要使先锋队觉悟到保存旧制度的不可能和推翻旧制度的必不可免。问题是要使群众，使千百万群众了解这是必不可免的，使他们表示援助先锋的决心。可是，群众只有从亲身的经验中才能了解这一点。任务就是要使千百万群众有可能根据亲身的经验认识到推翻旧政权的必不可免，要提出适当的斗争方法和组织形式使群众易于根据经验来认清革命口号的正确性。","language":"中文","translation":false},{"id":"foundations-1-362","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":362,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"如果党在当时没有决定参加杜马，如果它没有决定集中力量去进行杜马内的工作，并在这一工作的基础上去开展斗争，使群众易于根据亲身的经验认清杜马的无用、立宪民主党人的诺言的虚伪、和沙皇制度妥协的不可能、农民和工人阶级联盟的必不可免，那么先锋队就会脱离工人阶级，而工人阶级就会失去它和群众的联系。如果没有群众在杜马时期的经验，就不可能揭露立宪民主党人，就不可能有无产阶级的领导权。","language":"中文","translation":false},{"id":"foundations-1-363","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":363,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"召回主义〔注：召回主义,是俄国1905—1907年革命失败后在布尔什维克队伍中产生的“左”倾机会主义派别，代表人物是亚·亚·波格丹诺夫、阿·瓦·卢那察尔斯基、格·阿·阿列克辛斯基、米·尼·波克罗夫斯基等。召回派要求从第三届国家杜马中召回社会民主党的代表，拒绝参加工会、合作社以及其他合法和半合法的组织，放弃一切合法斗争。召回派以“革命”词句作幌子，执行了取消派的路线。列宁把召回派叫作“改头换面的孟什维克”。1909年6月，布尔什维克机关报《无产者报》扩大编辑部会议（实际上是布尔什维克中央全体会议）斥责了召回派，把波格丹诺夫开除出布尔什维克组织。〕策略的危险性就在于它会使先锋队脱离自己的千百万人的后备军。","language":"中文","translation":false},{"id":"foundations-1-364","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":364,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"如果无产阶级当时跟着在1917年4月号召举行起义的“左派”共产主义者〔注：这里是指俄国社会民主工党（布）彼得堡委员会中以谢·亚·帕格达季耶夫为首的少数委员。他们在1917年四月游行示威时提出了立刻推翻临时政府的口号。布尔什维克党中央委员会在游行示威的次日（4月22日）通过列宁提出的决议，严厉地谴责了帕格达季耶夫等人的冒险主义行为，认为他们提出的口号不合适、不正确，妨碍党把苏维埃的多数争取到自己方面来，同当时党的方针相抵触。〕走，那么党就会脱离工人阶级，而工人阶级就会失去它在广大的农民和士兵群众中的影响，因为当时孟什维克和社会革命党人还没有暴露自己是战争和帝国主义的拥护者，因为当时群众还没有根据亲身的经验认清孟什维克和社会革命党人关于和平、土地和自由的言论的虚伪。如果没有群众在克伦斯基统治时期的经验，就不会使孟什维克和社会革命党人陷于孤立，就不可能有无产阶级专政。因此，“耐心说明”各小资产阶级政党的错误并在苏维埃内部进行公开斗争的策略是当时唯一正确的策略。","language":"中文","translation":false},{"id":"foundations-1-365","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":365,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“左派”共产主义者策略的危险性就在于它会使党由无产阶级革命的领袖变成一小撮徒托空言而没有基础的密谋家。","language":"中文","translation":false},{"id":"foundations-1-366","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":366,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“单靠先锋队是不能胜利的。当整个阶级，当广大群众还没有采取直接支持先锋队的立场，或者还没有对先锋队采取至少是善意的中立态度……时，单叫先锋队去进行决战，那就不仅是愚蠢，而且是犯罪。但是要使真正整个阶级，使被资本压迫的真正广大的劳动群众都站到这种立场上来，仅靠宣传和鼓动是不够的。要做到这一点，还需要这些群众本身的政治经验。这是一切大革命的基本规律，现在这个规律不仅在俄国，而且在德国也得到了十分有力而鲜明的证实。不仅对没有文化、大都不识字的俄国群众，而且对文化程度高、个个识字的德国群众，都需要亲身体验到第二国际骑士们的政府懦弱无能、毫无气节、一筹莫展、对资产阶级奴颜婢膝、卑鄙无耻，亲身体验到，不是无产阶级专政，就必然是极端反动分子（俄国的科尔尼洛夫、德国的卡普〔注：卡普（1868——1922）是德国1920年反革命政变——“卡普盲动’的主要领导者，政变后成为政府首领，他的政府仅存在数日即被德国工人的总罢工推翻。〕之流）的专政，然后才坚决转到共产主义方面来的。”","language":"中文","translation":false},{"id":"foundations-1-367","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":367,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第二，要在每个一定的时机找出事变过程链条上的特殊环节，抓住了这个环节，就能掌握整个链条，为取得战略胜利准备条件。","language":"中文","translation":false},{"id":"foundations-1-368","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":368,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"问题是要从摆在党面前的许多任务中挑出这样一个当前任务，解决这个任务是中心，实现这个任务就能保证顺利地解决其他一切当前任务。","language":"中文","translation":false},{"id":"foundations-1-369","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":369,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"我们可以用两个例子来说明这个原理的意义，一个例子可以引自很久以前的时期（党形成时期），另一个例子可以引自我们最接近的目前时期（新经济政策时期）。","language":"中文","translation":false},{"id":"foundations-1-370","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":370,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在党形成的时期，无数的小组和组织还没有彼此联系起来，手工业方式和小组习气从上到下腐蚀着党，思想上的混乱是党内生活的特征，——在这个时期，整个链条中的基本环节和摆在党面前的各项任务中的基本任务就是创办全俄的秘密报纸（《火星报》）。为什么呢？因为在当时的条件下，只有通过全俄的秘密报纸才能形成党内意见一致的核心，才能把无数的小组和组织联结成一个整体，准备思想统一和策略统一的条件，从而为真正的党的形成奠定基础。","language":"中文","translation":false},{"id":"foundations-1-371","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":371,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在由战争过渡到经济建设的时期，工业遭到破坏而奄奄一息，农业苦于城市产品的不足，国营工业和农民经济的结合已经成为顺利进行社会主义建设的基本条件，——在这个时期，事变过程链条中的基本环节，许多任务中的基本任务，就是发展商业。为什么呢？因为在新经济政策的条件下，工业和农民经济只有通过商业才能结合；因为在新经济政策的条件下，有生产而没有销路就是置工业于死地；因为只有通过发展商业去扩大销路，才能扩展工业；因为只有在商业方面巩固了，只有掌握了商业，只有掌握了这个环节，才能指望把工业和农民市场结合起来并顺利地解决其他的当前任务，以便为建立社会主义的经济基础创造条件。","language":"中文","translation":false},{"id":"foundations-1-372","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":372,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“仅仅做一个革命者和社会主义拥护者甚至共产主义者是不够的。必须善于在每个特定时机找出链条上的那个特殊环节，必须全力抓住这个环节，以便抓住整个链条并坚定地准备过渡到下一个环节……”","language":"中文","translation":false},{"id":"foundations-1-373","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":373,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“当前……这样的环节就是在国家的正确调节（指导）下活跃国内商业。在历史事件的链条中，即在1921—1922年我国社会主义建设的各个过渡形式中，商业正是……‘必须全力抓住的环节’。”（见“列宁全集”第四版第三十三卷第八十八页、第八十九页）","language":"中文","translation":false},{"id":"foundations-1-374","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":374,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"保证有正确的策略指导的主要条件就是这样。","language":"中文","translation":false},{"id":"foundations-1-375","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":375,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(6)改良主义和革命主义。革命的策略和改良主义的策略有什么区别呢？","language":"中文","translation":false},{"id":"foundations-1-376","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":376,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"有些人以为列宁主义反对一切改良，反对一切通融和妥协。这是完全不对的。布尔什维克和其他任何人一样清楚地知道：在某种意义上说来，真是“凡施皆善”；在某种条件下，改良，其中包括通融和妥协，是必要的和有益的。","language":"中文","translation":false},{"id":"foundations-1-377","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":377,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“为了推翻国际资产阶级而进行的战争，要比国家之间通常进行的最顽强的战争还要困难百倍，费时百倍，复杂百倍；进行这样的战争而事先拒绝采用机动办法，拒绝利用敌人之间的利益矛盾（哪怕是暂时的矛盾），拒绝同各种可能的同盟者（哪怕是暂时的、不稳定的、动摇的、有条件的同盟者）通融和妥协，这岂不是可笑到了极点吗？这岂不是正象我们想攀登一座崎岖险阻、未经勘察、人迹未到的高山，却预先拒绝有时要迂回前进，有时要向后折转，放弃已经选定的方向而试着向各种不同的方向走吗？”（见“列宁全集”第四版第三十一卷第五十一页）","language":"中文","translation":false},{"id":"foundations-1-378","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":378,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"问题显然不在于改良或通融和妥协，而在于怎样运用改良和妥协。","language":"中文","translation":false},{"id":"foundations-1-379","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":379,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在改良主义者看来，改良就是一切，而革命工作不过是拿来做谈话资料、借以转移视线的小事情。所以，改良主义策略下的改良，在资产阶级政权存在的条件下，必然要变为巩固资产阶级政权的工具，变为瓦解革命的工具。","language":"中文","translation":false},{"id":"foundations-1-380","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":380,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"相反地，在革命者看来，主要的是革命工作，而不是改良，——在革命者看来，改良是革命的副产品。所以，革命策略下的改良，在资产阶级政权存在的条件下，自然会变为瓦解资产阶级政权的工具，变为巩固革命的工具，变为向前发展革命运动的据点。","language":"中文","translation":false},{"id":"foundations-1-381","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":381,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"革命者采用改良，是为了利用它作为挂钩来把合法工作和秘密工作联结起来，是为了利用它作为掩蔽物来加强秘密工作，以便用革命精神训练群众去推翻资产阶级。","language":"中文","translation":false},{"id":"foundations-1-382","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":382,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在帝国主义条件下按革命精神利用改良和妥协的实质就在这里。","language":"中文","translation":false},{"id":"foundations-1-383","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":383,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"相反地，改良主义者采用改良，是为了拒绝任何秘密工作，破坏训练群众去进行革命的事业，在“恩赐的”改良的福荫下高枕而卧。","language":"中文","translation":false},{"id":"foundations-1-384","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":384,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"改良主义策略的实质就在这里。","language":"中文","translation":false},{"id":"foundations-1-385","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":385,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于帝国主义条件下的改良和妥协的问题就是这样。","language":"中文","translation":false},{"id":"foundations-1-386","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":386,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是在帝国主义被推翻后，在无产阶级专政下，情形就有些改变了。在某种条件下，在某种环境中，无产阶级政权也许不得不暂时离开用革命手段改造现存制度的道路，而走上逐渐改造现存制度的道路，“走上”列宁在《论黄金的作用》[18]这篇著名论文中所说的那条“改良主义的道路”，走上迂回行进的道路，走上改良和向非无产者阶级让步的道路，以便瓦解这些阶级，给革命以喘息时机，养精蓄锐，准备举行新进攻的条件。不能否认，这条道路在某种意义上说来是“改良主义的”道路。只是应当记住，这里有一个根本特点，就是在这种情况下的改良是来自无产阶级政权方面的改良，它巩固无产阶级政权，它给无产阶级政权以必要的喘息时机，它的使命不是要瓦解革命，而是要瓦解非无产者阶级。","language":"中文","translation":false},{"id":"foundations-1-387","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":387,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"于是，在这种情况下，改良就变成了自己的对立物。","language":"中文","translation":false},{"id":"foundations-1-388","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":388,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"无产阶级政权所以能够实行这种政策，是因为而且只是因为前一时期的革命规模已十分广大，因而开辟了十分广阔的场所，因而可以实行退却，用暂时退却的策略，用迂回行进的策略来代替进攻的策略。","language":"中文","translation":false},{"id":"foundations-1-389","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":389,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这样看来，从前，在资产阶级政权下，改良是革命的副产品，而现在，在无产阶级专政下，改良的来源却是无产阶级的革命胜利品，即由这些胜利品构成的、积累在无产阶级手中的后备力量。","language":"中文","translation":false},{"id":"foundations-1-390","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":390,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“只有马克思主义才精确地正确地规定了改良同革命的关系，然而马克思只能从一方面，即只能从无产阶级还没有在一个国家取得稍微巩固、稍微持久的初次胜利的情况下看到这种关系。在这种情况下，正确关系的基础就是把改良看作无产阶级的革命阶级斗争的副产品。……无产阶级即使在一个国家取得胜利以后，改良同革命的关系也还会产生一种新的内容。在原则上虽然和从前一样，但在形式上却已发生变化。这种变化马克思本人当时是预见不到的，这种变化只有根据马克思主义的哲学和政治学说才能认识到。……取得胜利以后，如果取得胜利的国家经过极度紧张的斗争，其实力显然不够用革命手段来实行某种过渡，那么改良（在国际范围内仍然是“副产品”）还是一种必要的合理的喘息时机。胜利提供了很多‘后备力量’，使我们即使在被迫退却时也能坚持下去，无论在物质方面或精神方面都能坚持下去。” （见“列宁全集”第四版第三十三卷第九十一页至第九十二页）","language":"中文","translation":false},{"id":"foundations-1-391","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":391,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在革命前的时期，在比较和平发展的时期，第二国际各党是工人运动中的统治力量，议会斗争形式是基本的斗争形式，——在这种条件下，党没有而且不可能有它后来在公开的革命搏斗的条件下所具有的那种重大的和决定的意义。考茨基在第二国际遭受攻击时替它辩护说：第二国际各党是和平的工具，不是战争的工具，正因为如此，它们在战争时期，在无产阶级的革命发动时期，就没有力量采取什么重大措施。这是完全对的。但是这说明什么呢？说明第二国际各党对于无产阶级的革命斗争是不适用的，它们不是引导工人去夺取政权的无产阶级的战斗的党，而是迁就议会选举和议会斗争的选举机关。正因为如此，在第二国际机会主义者统治的时期，无产阶级的基本政治组织并不是党，而是议会党团。大家知道，事实上党在这个时期只是议会党团的附属品和服役者。几乎用不着证明，在这样的条件下，在这样的党的领导下，是谈不到训练无产阶级去进行革命的。","language":"中文","translation":false},{"id":"foundations-1-392","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":392,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，新时期一到来，情形就根本改变了。新时期是公开的阶级冲突的时期，是无产阶级的革命发动的时期，是无产阶级革命的时期，是直接准备力量去推翻帝国主义而由无产阶级夺取政权的时期。这个时期在无产阶级面前提出种种新的任务：要按新的革命的方式去改造党的全部工作，要用夺取政权的革命斗争精神去教育工人，要训练后备军并使他们跟上来，要和邻国的无产者结成联盟，要同殖民地和附属国的解放运动建立巩固的联系，如此等等。如果以为这些新任务可以用那些在议会制度的和平条件下教育出来的旧社会民主主义政党的力量来解决，那就是使自己陷于绝望的境地，遭到必不可免的失败。肩负着这样的任务而仍然以旧的政党为领导，那就是完全解除武装。几乎用不着证明，无产阶级是不能容忍这种情形的。","language":"中文","translation":false},{"id":"foundations-1-393","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":393,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因此，必须有新的党，战斗的党，革命的党。这个党要有充分的勇气，能够引导无产者去夺取政权；这个党要有充分的经验，能够认清革命环境的复杂条件；这个党要有充分的随机应变的本领，能够绕过横在前进道路上的一切暗礁。","language":"中文","translation":false},{"id":"foundations-1-394","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":394,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"没有这样的党，就休想推翻帝国主义，就休想争得无产阶级专政。","language":"中文","translation":false},{"id":"foundations-1-395","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":395,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这个新的党就是列宁主义的党。","language":"中文","translation":false},{"id":"foundations-1-396","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":396,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这个新的党有什么特点呢？","language":"中文","translation":false},{"id":"foundations-1-397","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":397,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(1)党是工人阶级的先进部队。党首先应当是工人阶级的先进部队。党应当把工人阶级的一切优秀分子，把他们的经验、他们的革命性、他们对无产阶级事业无限忠诚的精神都吸收进来。但是要成为真正的先进部队，党应当用革命理论，用运动规律的知识，用革命规律的知识把自己武装起来。否则它就不能领导无产阶级的斗争，就不能引导无产阶级。如果党只限于记录工人阶级群众的感觉和思想，如果它做了自发运动的尾巴，如果它不善于克服自发运动的因循习惯和政治上的漠不关心，如果它不善于超出无产阶级的一时的利益，如果它不善于把群众的水平提高到认识无产阶级的阶级利益，那么它就不能成为真正的党。党应当站在工人阶级的前面，应当比工人阶级看得远些，应当引导无产阶级，而不应当做自发运动的尾巴。鼓吹“尾巴主义”的第二国际各党是资产阶级政策的传播者，而这个政策是要把无产阶级变成资产阶级手中的工具。只有采取无产阶级先进部队的观点、能够把群众的水平提高到认识无产阶级的阶级利益的党才能使工人阶级离开工联主义的道路，使它变成独立的政治力量。","language":"中文","translation":false},{"id":"foundations-1-398","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":398,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党是工人阶级的政治领袖。","language":"中文","translation":false},{"id":"foundations-1-399","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":399,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"我在上面已经说到工人阶级斗争的困难，说到斗争环境的复杂，说到战略和策略，说到后备军和机动性，说到进攻和退却。这些条件的复杂程度，和战争条件比较起来，是有过之而无不及的。谁能认清这些条件呢？谁能给千百万无产者群众以正确的方针呢？无论哪一个作战部队如果不愿意遭到失败，就非有经验丰富的司令部不可。无产阶级如果不愿意让自己受死敌的宰割，就更加非有这样的司令部不可，这难道还不明显吗？可是这个司令部在什么地方呢？只有无产阶级的革命的党才能成为这样的司令部。工人阶级没有革命的党，就等于军队没有司令部。","language":"中文","translation":false},{"id":"foundations-1-400","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":400,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党是无产阶级的战斗司令部。","language":"中文","translation":false},{"id":"foundations-1-401","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":401,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，党不能仅仅是先进部队。党同时还应当是本阶级的部队，即本阶级的一部分，党应当和本阶级有根深蒂固的联系。只要阶级还没有消灭，只要无产阶级还由其他阶级出身的人来补充，只要工人阶级还不可能全部提高到先进部队的水平，工人阶级的先进部队和其余群众之间的区别，党员和非党员之间的区别是不会消灭的。可是，如果这个区别变成了隔离，如果党把自己关在小圈子里而和非党群众脱离，那么党就不成其为党了。如果党不和非党群众联系，如果党不和非党群众结合，如果非党群众不接受党的领导，如果党在群众中没有道义上和政治上的信用，那么党就不能领导阶级。","language":"中文","translation":false},{"id":"foundations-1-402","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":402,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"不久以前，我们党从工人中接收了二十万新党员。这里最值得注意的情况，就是这些人与其说是自己走进党内来的，不如说是被其余的一切非党群众送进党内来的，这些非党群众积极参加了接收新党员的工作，而且接收新党员都是经过他们赞同的。这件事实说明：广大的非党工人群众把我们党看做他们自己的党，看做亲近的亲切的党，他们深切关心党的发展和巩固，他们自愿把自己的命运托付给党的领导。几乎用不着证明，如果没有这种看不见摸不到的精神上的线索把党和非党群众联系起来，党是不能成为本阶级的决定力量的。","language":"中文","translation":false},{"id":"foundations-1-403","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":403,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党是工人阶级的不可分离的部分。","language":"中文","translation":false},{"id":"foundations-1-404","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":404,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“我们是阶级的党，因此，几乎整个阶级（而在战争时期，在国内战争年代，甚至完全是整个阶级）都应当在我们党的领导下行动，都应当尽量紧密地靠近我们党；但是，如果以为在资本主义制度下，不论在什么时候，几乎整个阶级或者整个阶级都能把自己的觉悟程度和积极程度提高到自己的先进部队即自己的社会民主党的水平，那就是马尼洛夫精神〔注：马尼洛夫是果戈理的小说《死魂灵》中的一个游手好闲、痴心妄想、阿谀逢迎和虚假伪善的地主。马尼洛夫精神是想入非非的意思。——第100、263页。〕和‘尾巴主义’。还没有一个明白事理的社会民主党人怀疑过，在资本主义制度下，连工会组织（比较原始的、比较容易为落后阶层的觉悟程度接受的组织）也不能包括几乎整个工人阶级或者整个工人阶级。忘记先进部队和倾向于它的所有群众之间的区别，忘记先进部队的经常责任是把愈益广大的阶层提高到这个先进的水平，那只是欺骗自己，无视我们的巨大任务，缩小这些任务。”（见“列宁全集”第四版第七卷第二四○页）","language":"中文","translation":false},{"id":"foundations-1-405","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":405,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(2)党是工人阶级的有组织的部队。党不仅是工人阶级的先进部队。如果党想真正领导本阶级的斗争，那么它同时还应当是本阶级的有组织的部队。在资本主义的条件下，党的任务是非常巨大而繁杂的。党应当在国内外发展非常困难的条件下领导无产阶级的斗争；党应当在环境要求进攻时引导无产阶级去进攻；党应当在环境要求退却时带领无产阶级避开强大的敌人的打击；党应当向千百万无组织的非党工人群众灌注斗争的纪律性和计划性、组织性和坚定性。可是，党只有当它自己是纪律性和组织性的体现者的时候，只有当它自己是无产阶级的有组织的部队的时候，才能完成这些任务。没有这些条件，就谈不到党对千百万无产阶级群众的真正领导。","language":"中文","translation":false},{"id":"foundations-1-406","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":406,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党是工人阶级的有组织的部队。","language":"中文","translation":false},{"id":"foundations-1-407","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":407,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于党是有组织的整体这个思想，是在列宁所提出的我们党章第一条的著名条文中固定下来的，这个条文把党看做组织的总和，把党员看做党内某一组织的成员。孟什维克还在1903年就反对这个条文，而提出了自行列名入党的“制度”，要求把党员的“称号”扩大到每个“教授”和“中学生”，每个“同情者”和“罢工者”，即扩大到每个给党以某种援助、但是并不加入而且不愿加入党的任何一个组织的人。几乎用不着证明，如果这个奇特的“制度”在我们党内巩固起来，那就必然会使党内充满教授和中学生，使党变成一个界限模糊、没有定形、组织涣散而沉没在“同情者”大海中的“机构”，抹杀党和阶级间的界限，抛弃党把无组织群众提高到先进部队水平的任务。不用说，在这种机会主义的“制度”下，我们党是不能够在我们的革命进程中实现工人阶级的组织核心的作用的。","language":"中文","translation":false},{"id":"foundations-1-408","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":408,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“在马尔托夫同志看来，党的界限是极不明确的，因为‘每一个罢工者’都可以‘宣布自己是党员’。试问，这种界限模糊有什么好处呢？不过是使‘称号’广泛散布而已。它的害处就是会产生一种把党和阶级混淆起来的涣散组织的思想。”（见“列宁全集”第四版第七卷第二四六页）","language":"中文","translation":false},{"id":"foundations-1-409","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":409,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，党不仅是党的各个组织的总和。党同时还是这些组织的统一的体系，是这些组织正式结成的统一的整体，有上级的和下级的领导机关，有少数服从多数的原则，有全体党员所必须执行的实际决议。没有这些条件，党就不能成为能够有计划有组织地领导工人阶级斗争的统一的有组织的整体。","language":"中文","translation":false},{"id":"foundations-1-410","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":410,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“从前，我们党还不是正式的有组织的整体，而只是各个集团的总和，所以在这些集团间除了思想影响以外，别的关系是不可能有的。现在，我们已经成为有组织的政党，这也就是说造成了一种权力，思想威信变成了权力威信，党的下级机关应该服从党的上级机关。”（同上，第三三八页至第三三九页）","language":"中文","translation":false},{"id":"foundations-1-411","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":411,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"少数服从多数的原则，党的工作由中央来领导的原则，往往引起那些不坚定的分子的攻击，他们斥责这种原则是“官僚主义”、“形式主义”等等。几乎用不着证明，如果不实行这些原则，那么作为一个整体的党的有计划的工作和对工人阶级斗争的领导就会是不可能的。列宁主义在组织问题上是始终一贯地实行这些原则的。列宁把反对这些原则的行为叫做“俄国的虚无主义”和“老爷式的无政府主义”，认为这种行为应该受到讥笑和痛斥。","language":"中文","translation":false},{"id":"foundations-1-412","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":412,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁在他的《进一步,退两步》一书中对于这些不坚定的分子是这样说的：","language":"中文","translation":false},{"id":"foundations-1-413","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":413,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“这种老爷式的无政府主义是俄国虚无主义者所特有的。党的组织在他们看来是可怕的‘工厂’；部分服从整体和少数服从多数在他们看来是‘农奴制’……他们一听见在中央领导下实行分工，就发出可怜又可笑的号叫，反对把人们变成‘小轮子和小螺丝钉’……他们一听见有人提起党的组织章程，就作出瞧不起人的样子，发表鄙视的……意见，说完全不要章程也可以。”","language":"中文","translation":false},{"id":"foundations-1-414","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":414,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“看来很明显，高喊所谓官僚主义，不过是要掩盖他们对于中央机关人选的不满，不过是要掩盖……丑恶行为。你是官僚主义者，因为你是代表大会不按照我的意志而违反我的意志委派的；你是形式主义者，因为你是根据代表大会的形式上的决议，而没有得到我的同意；你做事极端机械，因为你凭借党代表大会的‘机械的’多数，而不考虑到我想得到补选席位的愿望；你是专制君主，因为你不愿意把权柄交给旧时的亲热伙伴〔这里所说的“伙伴”指阿克雪里罗得、马尔托夫、波特列索夫等人，他们不服从第二次代表大会的决议，而责备列宁犯了“官僚主义”的毛病。——约·斯大林注〕。”","language":"中文","translation":false},{"id":"foundations-1-415","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":415,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(3)党是无产阶级阶级组织的最高形式。党是工人阶级的有组织的部队。可是，党并不是工人阶级的唯一组织。无产阶级还有其他许多为顺利地进行反对资本的斗争所绝对必需的组织，如工会、合作社、工厂组织、议会党团、非党妇女团体、出版机关、文化教育组织、青年团、革命战斗组织（在公开的革命发动时期）以及作为国家组织形式的代表苏维埃（当无产阶级执掌政权时）等等。这些组织极大多数都是非党的，其中只有某一部分直接接近党或者是党的支脉。所有这些组织，在某种条件下都是工人阶级所绝对必需的，因为如果没有这些组织，就不能巩固无产阶级在各种斗争中的阶级阵地；因为如果没有这些组织，就不能锻炼无产阶级这个负有以社会主义制度代替资产阶级制度的使命的力量。可是，既然有这样多的组织，怎样实现统一的领导呢？怎样才能保证在领导工作中不致因为有很多组织而发生各自为政的现象呢？有人会说，这些组织各在自己的特别范围内进行工作，因此不会互相妨碍。这当然是对的。可是还有一点也是对的，即所有这些组织都应当按照一个方向进行工作，因为它们都是为一个阶级，即为无产者阶级服务的。试问：谁来决定这一切组织在进行工作时所必须遵循的路线，即总方向呢？哪里有这样一个中央组织，它不仅因为有必要的经验而能制定这条总路线，并且因为有充分的威信而能推动这一切组织去实现这条路线，以达到领导上的统一，排除发生不协调现象的可能呢？","language":"中文","translation":false},{"id":"foundations-1-416","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":416,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这样的组织就是无产阶级的党。","language":"中文","translation":false},{"id":"foundations-1-417","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":417,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党具备为此所必需的一切条件，第一，因为党是工人阶级优秀分子的集合点，这些分子和无产阶级的非党组织有直接联系，并经常领导它们；第二，因为党既是工人阶级优秀分子的集合点，所以它是培养能够领导本阶级各种组织的工人阶级领导者的最好的学校；第三，因为党既是培养工人阶级领导者的最好的学校，所以按其经验和威信来说，它是能把无产阶级斗争的领导集中起来的唯一组织，因而也就是能把工人阶级所有一切非党组织都变成使党同本阶级联结起来的服务机关和引带的唯一组织。","language":"中文","translation":false},{"id":"foundations-1-418","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":418,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党是无产阶级阶级组织的最高形式。","language":"中文","translation":false},{"id":"foundations-1-419","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":419,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这当然不是说，非党组织，如工会、合作社等等，应该正式服从党的领导。这只是说，参加这些组织的党员，这些无疑是有威信的人，应该采取一切说服办法，使这些非党组织在自己的工作中跟无产阶级政党接近，并自愿接受这个党的政治领导。","language":"中文","translation":false},{"id":"foundations-1-420","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":420,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，列宁说：党是“无产者的阶级联合的最高形式”，它的政治领导应当普及到无产阶级的其他各种组织中去。（见“列宁全集”第四版第三十一卷第三十二页）","language":"中文","translation":false},{"id":"foundations-1-421","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":421,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"正因为如此，主张非党组织“独立”和“中立”的机会主义理论，繁殖出独立的议员和脱离党的出版家、狭隘的工会活动家和市侩化的合作社运动者的机会主义理论，是和列宁主义的理论与实践完全不能相容的。","language":"中文","translation":false},{"id":"foundations-1-422","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":422,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(4)党是无产阶级专政的工具。党是无产阶级组织的最高形式。党是无产者阶级内部和无产者阶级各个组织中的主要的领导基础。可是由此决不能得出结论说，可以把党看做目的本身，看做独立自在的力量。党不仅是无产者的阶级联合的最高形式，而且又是无产阶级手中用来争得专政（当无产阶级还没有争得专政时）、用来巩固并扩大专政（当无产阶级已经争得专政时）的工具。如果政权问题没有摆在无产阶级的面前，如果帝国主义的条件、战争的不可避免以及危机的存在没有要求把无产阶级的一切力量集中到一点，把革命运动的一切线索集中在一个地方，以便推翻资产阶级而争得无产阶级专政，那么党的作用就不能提得这样高，党就不能超过无产阶级的其他一切组织。无产阶级所以需要党，首先因为党是无产阶级顺利夺取政权所必需的战斗司令部。几乎用不着证明，如果没有一个能够把无产阶级的群众组织集合在自己的周围、在斗争进程中把整个运动的领导都集中起来的党，那么俄国无产阶级就不能实现自己的革命专政。","language":"中文","translation":false},{"id":"foundations-1-423","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":423,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，无产阶级所以需要党，不仅是为了争得专政，而且更是为了保持专政，为了巩固专政并扩大专政，以求取得社会主义的完全胜利。","language":"中文","translation":false},{"id":"foundations-1-424","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":424,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“现在差不多每个人都已看到，如果我们党没有极严格的真正铁的纪律，如果我们党没有得到整个工人阶级全心全意的拥护，就是说，没有得到工人阶级中所有一切善于思考、诚实、有自我牺牲精神、有威信并且能带领或吸引落后阶层的人的全心全意的拥护，那么布尔什维克别说把政权保持两年半，就是两个半月也保持不住。”（见“列宁全集”第四版第三十一卷第七页）","language":"中文","translation":false},{"id":"foundations-1-425","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":425,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，“保持”和“扩大”专政是什么意思呢？这就是说，要向千百万无产者群众灌注纪律性和组织性；这就是说，要在无产者群众中间造成能够防御小资产阶级自发势力和小资产阶级习惯势力的腐蚀影响的屏障和堡垒；这就是说，要加强无产者在重新教育和改造小资产阶层方面的组织工作；这就是说，要帮助无产者群众把自己教育成为能够消灭阶级并准备条件来组织社会主义生产的力量。可是，如果没有一个因为本身具有团结性和纪律性而强有力的党，要做到这一切是不可能的。","language":"中文","translation":false},{"id":"foundations-1-426","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":426,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“无产阶级专政是对旧社会的势力和传统进行的顽强斗争，流血的和不流血的，暴力的和和平的，军事的和经济的，教育的和行政的斗争。千百万人的习惯势力是最可怕的势力。没有铁一般的和在斗争中锻炼出来的党，没有为本阶级全体忠实的人所信赖的党，没有善于考察群众情绪和影响群众情绪的党，要顺利地进行这种斗争是不可能的。”（见“列宁全集”第四版第三十一卷第二十七页）","language":"中文","translation":false},{"id":"foundations-1-427","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":427,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"无产阶级所以需要党，就是为了争得和保持专政。党是无产阶级专政的工具。","language":"中文","translation":false},{"id":"foundations-1-428","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":428,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此应该得出结论：随着阶级的消灭，随着无产阶级专政的消亡，党也一定会消亡。","language":"中文","translation":false},{"id":"foundations-1-429","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":429,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(5)党是意志的统一，是和派别组织的存在不相容的。如果没有一个因为本身具有团结性和铁的纪律而强有力的党，要争得和保持无产阶级专政是不可能的。可是，如果没有意志的统一，如果没有全体党员行动上的完全的和绝对的统一，党内铁的纪律是不可思议的。这当然不是说，因此就排斥了党内争论的可能。恰恰相反，铁的纪律不是排斥党内的批评和争论，而是以此为前提的。这更不是说，纪律应当是“盲目的”。恰恰相反，铁的纪律不是排斥自觉自愿的服从，而是以此为前提的，因为只有自觉的纪律才能成为真正铁的纪律。可是，在争论已经结束，批评已经完结，决议已经通过以后，全体党员意志的统一和行动的统一就是一个必要条件，没有这个条件，无论是统一的党还是党内铁的纪律，都是不可设想的。","language":"中文","translation":false},{"id":"foundations-1-430","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":430,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“在目前激烈的国内战争时代，共产党必须按照高度集中的方式组织起来，在党内实行象军事纪律那样的铁的纪律，党的中央必须拥有广泛的权力，得到全体党员的普遍信任，成为一个有权威的机构。只有这样，党才能履行自己的义务。”（见“列宁全集”第四版第三十一卷第一八五页）","language":"中文","translation":false},{"id":"foundations-1-431","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":431,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"在争得专政以前的斗争条件下党内纪律的问题就是这样。","language":"中文","translation":false},{"id":"foundations-1-432","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":432,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"关于争得专政以后的党内纪律也应该这样说，而且更应该这样说。","language":"中文","translation":false},{"id":"foundations-1-433","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":433,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“谁要是把无产阶级政党的铁的纪律哪怕是稍微削弱一点（特别是在无产阶级专政时期），那他事实上就是帮助资产阶级来反对无产阶级。”（同上，第二十七页）","language":"中文","translation":false},{"id":"foundations-1-434","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":434,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"由此应该得出结论：派别组织的存在，无论和党内统一或党内铁的纪律都不能相容。几乎用不着证明，有派别组织就会产生几个中央；有几个中央就是表明党内没有共同的中央，就是分散统一的意志，就是削弱和破坏纪律，就是削弱和破坏专政。第二国际各党既然反对无产阶级专政和不愿意引导无产者去夺取政权，当然可以容许自己有派别组织自由这种自由主义，因为它们根本就不需要铁的纪律。可是，共产国际各党既然把争得和巩固无产阶级专政的任务作为自己工作的基础，就不能容许“自由主义”，也不能容许派别组织自由。","language":"中文","translation":false},{"id":"foundations-1-435","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":435,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党是意志的统一，是排斥任何派别活动和党内权力分散现象的。","language":"中文","translation":false},{"id":"foundations-1-436","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":436,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因此，列宁“从保持党的统一和实现无产阶级先锋队的意志的统一是保证无产阶级专政胜利的基本条件这一观点出发”来说明“派别活动的……危险性”，这个说明已经载入我们党的第十次代表大会〔注：俄国共产党（布）第十次代表大会于1921年3月8—16日在莫斯科举行。列入大会议程的问题有：中央的总结报告、民族问题、工会问题、用粮食税代替余粮收集制问题、党的建设问题、党的统一和无政府工团主义倾向问题等。列宁在大会上作了中央的政治报告、关于用粮食税代替余粮收集制的报告、关于党的统一和无政府工团主义倾向的报告。大会根据列宁的报告通过了关于用粮食税代替余粮收集制即关于从战时共产主义政策转入新经济政策的具有历史意义的决议。大会作了关于工会问题争论的总结，严厉谴责了托洛茨基派、工人反对派、民主集中派等机会主义派别的观点，并以压倒多数通过了列宁的工会问题纲领。大会通过了列宁起草的《关于党的统一》的决议，要求立即解散一切派别集团，保持党的队伍的统一和团结。斯大林在大会上作了《关于党在民族问题方面的当前任务的报告》，并代表民族问题委员会提出了相应的决议草案，为大会一致通过。〕《关于党的统一》的专门决议[19]中。","language":"中文","translation":false},{"id":"foundations-1-437","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":437,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"因此，列宁要求“彻底消灭一切派别活动”并“立即毫无例外地解散一切按某种纲领组成的派别”，否则就给以“立即无条件地开除出党”的处分。（见《关于党的统一》的决议）","language":"中文","translation":false},{"id":"foundations-1-438","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":438,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"(6)党是靠清洗自己队伍中的机会主义分子而巩固起来的。党内的机会主义分子是党内派别活动的来源。无产阶级并不是一个和外界隔绝的阶级。农民、小市民、知识分子出身的那些因资本主义的发展而无产阶级化的人不断地流入无产阶级的队伍。同时，无产阶级上层分子又正在腐化，他们多半是资产阶级利用从殖民地得来的超额利润所豢养的工会活动家和议员。列宁说：“这个资产阶级化了的工人阶层即‘工人贵族’阶层，这个按生活方式、工资数额和整个世界观说来已经完全市侩化了的工人阶层，是第二国际的主要支柱，现在则是资产阶级的主要社会支柱（不是军事支柱）。因为这是资产阶级在工人运动中的真正走狗，是资本家阶级的工人代理人……是改良主义和沙文主义的真正传播者。”（见“列宁全集”第四版第二十二卷第一八二页）","language":"中文","translation":false},{"id":"foundations-1-439","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":439,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"所有这些小资产阶级集团用种种方法钻进党内，把动摇和机会主义的情绪，把腐化和犹疑的情绪带到党内来。他们是派别活动和瓦解现象的主要来源，是涣散党和从内部破坏党的现象的主要来源。后方有这样的“同盟者”而去和帝国主义作战，就会受到两面夹攻，陷于腹背受敌的境地。因此，对这种分子进行无情的斗争，把他们驱逐出党，是顺利进行反帝国主义斗争的先决条件。","language":"中文","translation":false},{"id":"foundations-1-440","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":440,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"主张用党内思想斗争的方法来“战胜”机会主义分子的理论，主张在一个党的范围内来“消除”机会主义分子的理论，是一种腐朽而危险的理论，它有使党麻痹和害慢性病的危险，有使党被机会主义宰割的危险，有使无产阶级丧失革命政党的危险，有使无产阶级在反对帝国主义的斗争中丧失主要武器的危险。如果我们党在自己的队伍里有马尔托夫之流和唐恩之流、波特列索夫之流和阿克雪里罗得之流，那么我们党就不能走上大道，就不能取得政权和组织无产阶级专政，就不能在国内战争中获得胜利。如果说我们党已经建立了自己内部的统一和自己队伍的空前的团结，那么这首先是因为它及时清洗了机会主义的肮脏东西，从党内驱逐了取消派和孟什维克。无产阶级政党发展和巩固的道路就是把机会主义者和改良主义者、社会帝国主义者和社会沙文主义者、社会爱国主义者和社会和平主义者从党内清洗出去的道路。","language":"中文","translation":false},{"id":"foundations-1-441","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":441,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"党是靠清洗自己队伍中的机会主义分子而巩固起来的。","language":"中文","translation":false},{"id":"foundations-1-442","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":442,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“在自己的队伍里有改良主义者，有孟什维克，就不能在无产阶级革命中取得胜利，就不能捍卫住无产阶级革命。这在原则上是很明显的。这是已经由俄国和匈牙利的经验具体证实了的。……在俄国……曾经有很多次处于困难的境地，当时如果让孟什维克、改良主义者、小资产阶级民主派留在我们党内……那么苏维埃制度就一定会被推翻的。大家都承认，意大利的无产阶级和资产阶级为了争夺国家政权，就要进行决战……在这样的时候，不仅把孟什维克、改良主义者、屠拉梯分子驱逐出党是绝对必要的，甚至把那些会动摇和正在动摇的、要去同改良主义者‘统一’的优秀的共产党员从各个重要岗位上撤下来，也可以说是有益的。……在革命的前夜和为争取革命的胜利而进行最激烈的斗争的时候，党内的最小的动摇都能葬送一切，都能破坏革命，都能使无产阶级丧失政权，因为这个政权还没有巩固，因为对这个政权的攻击还非常猛烈。如果动摇的领袖在这样的时候离开，那么这不会削弱而会加强党，加强工人运动，加强革命。”（见“列宁全集”第四版第三十一卷第三五七页、第三五八页、第三五九页）","language":"中文","translation":false},{"id":"foundations-1-443","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":443,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这里所指的不是文风。我指的是工作作风，是列宁主义实践中能够造就特种类型的列宁主义工作者的那种特殊和独特的要素。列宁主义是理论的和实践的学校，它能培养特种类型的党的工作者和国家工作者，造成特殊的列宁主义的工作作风。","language":"中文","translation":false},{"id":"foundations-1-444","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":444,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"这种作风的特征是什么呢？它的特点是怎样的呢？","language":"中文","translation":false},{"id":"foundations-1-445","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":445,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（甲）俄国人的革命胆略；","language":"中文","translation":false},{"id":"foundations-1-446","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":446,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"（乙）美国人的求实精神。","language":"中文","translation":false},{"id":"foundations-1-447","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":447,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁主义的作风就是党的工作和国家工作中的这两个特点的结合。","language":"中文","translation":false},{"id":"foundations-1-448","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":448,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"俄国人的革命胆略是消除因循习惯、守旧思想、保守主义、思想停滞以及对古老传统的盲从态度的药剂。俄国人的革命胆略是一种振奋人心的力量，它能激发思想，推动前进，破坏旧事物，开辟前途。没有这种革命胆略，就一步也不能前进。","language":"中文","translation":false},{"id":"foundations-1-449","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":449,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，如果不把俄国人的革命胆略和美国人在工作中的求实精神结合起来，那么它在实践中就很可能堕落为空洞的“革命的”马尼洛夫精神。这种堕落的例子是不胜枚举的。谁不知道“革命的”臆造和“革命的”设计这种病症的根源就是相信法令能安排一切和改造一切呢？有一位俄国作家伊·爱伦堡在他的《共产主义的完人》这篇小说中描写过一个患有这种病症的“布尔什维克”的典型，说他立意拟定一个理想的完人的模式……结果竟在这个“工作”中“淹死了”。这篇小说虽然有过于夸大的地方，它正确地抓住了这种病症却是毫无疑义的。可是，谁都没有象列宁那样苛刻无情地讥笑过患有这种病症的人。他把这种迷信臆造和发号施令的病症鄙视为“共产党员的骄傲自大”。","language":"中文","translation":false},{"id":"foundations-1-450","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":450,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“所谓共产党员的骄傲自大，就是说，一个置身于共产党内而还没有被清洗出去的人，以为用共产党员的名义发号施令，就能完成他的一切任务。”（见“列宁全集”第四版第三十三卷第五十四页）","language":"中文","translation":false},{"id":"foundations-1-451","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":451,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁通常总是用日常平凡的事情来和这种“革命的”高调相对立，以此着重指出：“革命的”臆造是和真正列宁主义的精神与字句绝对相反的。","language":"中文","translation":false},{"id":"foundations-1-452","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":452,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"列宁说：“少说些漂亮话，多做些日常平凡的事情……”","language":"中文","translation":false},{"id":"foundations-1-453","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":453,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"“少唱些政治高调，多注意些极平凡的但是生动的……共产主义建设事实……”（见“列宁全集”第四版第二十九卷第三九五页和第三八六页）","language":"中文","translation":false},{"id":"foundations-1-454","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":454,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"相反地，美国人的求实精神却是消除“革命的”马尼洛夫精神和虚幻的臆造的药剂。美国人的求实精神是一种不可遏止的力量，它不知道而且不承认有什么阻碍，它以自己的求实的坚忍精神排除所有一切障碍，它一定要把已经开始的事情进行到底，哪怕这是一件不大的事情；没有这种力量，就不可能有认真的建设工作。","language":"中文","translation":false},{"id":"foundations-1-455","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":455,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"可是，如果不把美国人的求实精神和俄国人的革命胆略结合起来，那么它就很可能堕落为狭隘的无原则的事务主义。谁不知道狭隘的实际主义和无原则的事务主义的病症往往使某些“布尔什维克”蜕化而脱离革命事业呢？波·皮尔尼亚克的《荒凉年份》这篇小说反映过这种特殊的病症，描写过某些俄国“布尔什维克”的典型，说他们充满了意志和实践的决心，“干得”很“起劲”，可是看不见前途，不知道“干工作是为了什么”，因而离开了革命工作的道路。谁都没有象列宁那样辛辣地讥笑过这种事务主义的病症。列宁把这种病症鄙视为“狭隘的实际主义”，“无头脑的事务主义”。他通常总是用生动的革命事业和我们全部日常工作中所必须具有的革命前途来和这种病症相对立，从而着重指出：无原则的事务主义，也同“革命的”臆造一样，是和真正的列宁主义绝对相反的。","language":"中文","translation":false},{"id":"foundations-1-456","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":456,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"俄国人的革命胆略和美国人的求实精神结合起来，就是党的工作和国家工作中的列宁主义的实质。","language":"中文","translation":false},{"id":"foundations-1-457","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":457,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"只有把这两者结合起来，我们才能有完整的列宁主义工作者的典型，列宁主义的工作作风。","language":"中文","translation":false},{"id":"foundations-1-458","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":458,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"载于1924年4月26、30日和5月9、11、14、15、18日 《真理报》","language":"中文","translation":false},{"id":"foundations-1-459","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":459,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"第96、97、103、105、107、108、111号","language":"中文","translation":false},{"id":"foundations-1-460","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":460,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[1] 约·维·斯大林的讲演“论列宁主义基础”发表在一九二四年四月和五月的“真理报”上。一九二四年五月出版了约·维·斯大林的小册子“论列宁和列宁主义”，其中编入了回忆录“论列宁”和讲演“论列宁主义基础”。 约·维·斯大林的著作“论列宁主义基础”编入了约·维·斯大林的“列宁主义问题”一书的各次版本中。","language":"中文","translation":false},{"id":"foundations-1-461","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":461,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[2] “马克思恩格斯文选”（两卷集）一九五四年莫斯科中文版第一卷第四十一页。","language":"中文","translation":false},{"id":"foundations-1-462","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":462,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[3] 指卡·马克思于一八五六年四月十六日给弗·恩格斯的信中所说的话（见“马克思恩格斯书信选集”一九四七年俄文版第八十六页）。","language":"中文","translation":false},{"id":"foundations-1-463","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":463,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[4] 指弗·恩格斯“行动中的巴枯宁主义者”一文（见“马克思恩格斯全集”一九三三年俄文版第十五卷第一○五页至第一二四页）。","language":"中文","translation":false},{"id":"foundations-1-464","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":464,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[5] 弗·伊·列宁“共产主义运动中的‘左派’幼稚病”（见“列宁全集”第四版第三十一卷第九页，“列宁文选”两卷集一九五四年人民出版社版第二卷第六九三页）。","language":"中文","translation":false},{"id":"foundations-1-465","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":465,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[6] 弗·伊·列宁“什么是‘人民之友’以及他们如何攻击社会民主主义者？”（见“列宁全集”一九五五年人民出版社版第一卷第二七四页至第二七五页）。","language":"中文","translation":false},{"id":"foundations-1-466","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":466,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[7] 第二国际巴塞尔代表大会于一九一二年十一月二十四日至二十五日举行。这次代表大会是由于巴尔干战争和世界大战危险的迫近而召开的。代表大会讨论了国际形势和共同反对战争这一个问题。代表大会在通过的宣言中号召工人运用无产阶级的组织和力量进行反对战争危险的革命斗争，宣布“以战争对付战争”。","language":"中文","translation":false},{"id":"foundations-1-467","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":467,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[8] 见卡尔·马克思“资本论”一九三五年俄文版第一卷序言第二十三页。","language":"中文","translation":false},{"id":"foundations-1-468","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":468,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[9] 见“马克思恩格斯文选”（两卷集）一九五五年莫斯科中文版第二卷第三七○页。","language":"中文","translation":false},{"id":"foundations-1-469","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":469,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[10] 见“列宁全集”第四版第十四卷。","language":"中文","translation":false},{"id":"foundations-1-470","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":470,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[11] 卡·马克思“费尔巴哈论提纲”（见“马克思恩格斯文选”（两卷集）一九五五年莫斯科中文版第二卷第四○一页至第四○四页）。","language":"中文","translation":false},{"id":"foundations-1-471","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":471,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[12] 弗·伊·列宁“帝国主义是资本主义的最高阶段”（见“列宁全集”第四版第二十二卷第一七三页至第二九○页，“列宁文选”两卷集一九五三年人民出版社版第一卷第九一八页至第一○三二页）。","language":"中文","translation":false},{"id":"foundations-1-472","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":472,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[13] 约·维·斯大林援引的是弗伊列宁在一九○五年所写的文章：“社会民主党和临时革命政府”（从这篇文章中引了一段话），“无产阶级和农民的革命民主专政”和“论临时革命政府”（见“列宁全集”第四版第八卷第二四七页至第二六三页、第二六四页至第二七四页、第四二七页至第四四七页）。","language":"中文","translation":false},{"id":"foundations-1-473","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":473,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[14] 卡·马克思和弗·恩格斯“中央委员会第一次告共产主义者同盟书”（见“马克思恩格斯全集”一九三一年俄文版第八卷第四八三页，“马克思恩格斯文选”(两卷集)一九五四年莫斯科中文版第一卷第八十八页）。","language":"中文","translation":false},{"id":"foundations-1-474","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":474,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[15] 见“马克思恩格斯文选“（两卷集）一九五四年莫斯科中文版第一卷第二页和“书信选集”一九四七年俄文版第二六三页）。","language":"中文","translation":false},{"id":"foundations-1-475","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":475,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[16] 见“马克思恩格斯文选”（两卷集）一九五五年莫斯科中文版第二卷第四二二页和第四三六页。","language":"中文","translation":false},{"id":"foundations-1-476","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":476,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[17] 农业合作总社即全俄农业合作总社，于一九二一年八月成立，一九二九年六月撤销。","language":"中文","translation":false},{"id":"foundations-1-477","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":477,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[18] 见弗·伊·列宁的著作“论金子在现时以及在社会主义完全胜利后的作用”（“列宁全集”第四版第三十三卷第八十五页至第九十二页，“列宁文选”两卷集一九五四年人民出版社版第二卷第九一一页至第九一九页）。","language":"中文","translation":false},{"id":"foundations-1-478","author":"斯大林","title":"论列宁主义基础","location":"论列宁主义基础——在斯维尔德洛夫大学的讲演（1924年4月）","page":1,"paragraph":478,"url":"https://www.marxists.org/chinese/stalin/mia-chinese-stalin-192404.htm","text":"[19] “关于党的统一”的决议由弗·伊·列宁起草，经一九二一年三月 八日至十六日举行的俄共（布）第十次代表大会通过。（见“列宁全集”第四版第三十二卷第二一七页至第二二○页，“列宁文选”两卷集一九五四年人民出版社版第二卷第八二一页至第八二四页，并见“苏共代表大会、代表会议和中央全会决议汇编”一九五四年版第一卷第五二七页至第五三○页）","language":"中文","translation":false},{"id":"classes-1-1","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"中文马克思主义文库 -> 毛泽东 相关链接：中国社会各阶级的分析（《毛泽东集》版）","language":"中文","translation":false},{"id":"classes-1-2","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"（一九二五年十二月一日）","language":"中文","translation":false},{"id":"classes-1-3","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"毛泽东此文是为反对当时党内存在着的两种倾向而写的。当时党内的第一种倾向，以陈独秀为代表，只注意同国民党合作，忘记了农民，这是右倾机会主义。第二种倾向，以张国焘为代表，只注意工人运动，同样忘记了农民，这是“左”倾机会主义。这两种机会主义都感觉自己力量不足，而不知道到何处去寻找力量，到何处去取得广大的同盟军。毛泽东指出中国无产阶级的最广大和最忠实的同盟军是农民，这样就解决了中国革命中的最主要的同盟军问题。毛泽东并且预见到当时的民族资产阶级是一个动摇的阶级，他们在革命高涨时将要分化，其右翼将要跑到帝国主义方面去。一九二七年所发生的事变，证明了这一点。","language":"中文","translation":false},{"id":"classes-1-4","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"谁是我们的敌人？谁是我们的朋友？这个问题是革命的首要问题。中国过去一切革命斗争成效甚少，其基本原因就是因为不能团结真正的朋友，以攻击真正的敌人。革命党是群众的向导，在革命中未有革命党领错了路而革命不失败的。我们的革命要有不领错路和一定成功的把握，不可不注意团结我们的真正的朋友，以攻击我们的真正的敌人。我们要分辨真正的敌友，不可不将中国社会各阶级的经济地位及其对于革命的态度，作一个大概的分析。","language":"中文","translation":false},{"id":"classes-1-5","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"中国社会各阶级的情况是怎样的呢？","language":"中文","translation":false},{"id":"classes-1-6","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"地主阶级和买办阶级。在经济落后的半殖民地的中国，地主阶级和买办阶级完全是国际资产阶级的附庸，其生存和发展，是附属于帝国主义的。这些阶级代表中国最落后的和最反动的生产关系，阻碍中国生产力的发展。他们和中国革命的目的完全不兼容。特别是大地主阶级和大买办阶级，他们始终站在帝国主义一边，是极端的反革命派。其政治代表是国家主义派[1]和国民党右派。","language":"中文","translation":false},{"id":"classes-1-7","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"中产阶级。这个阶级代表中国城乡资本主义的生产关系。中产阶级主要是指民族资产阶级，他们对于中国革命具有矛盾的态度：他们在受外资打击、军阀压迫感觉痛苦时，需要革命，赞成反帝国主义反军阀的革命运动；但是当着革命在国内有本国无产阶级的勇猛参加，在国外有国际无产阶级的积极援助，对于其欲达到大资产阶级地位的阶级的发展感觉到威胁时，他们又怀疑革命。其政治主张为实现民族资产阶级一阶级统治的国家。有一个自称为戴季陶[2]“真实信徒”的，在北京《晨报》[3]上发表议论说：“举起你的左手打倒帝国主义，举起你的右手打倒共产党。”这两句话，画出了这个阶级的矛盾惶遽状态。他们反对以阶级斗争学说解释国民党的民生主义，他们反对国民党联俄和容纳共产党[4]及左派分子。但是这个阶级的企图——实现民族资产阶级统治的国家，是完全行不通的，因为现在世界上的局面，是革命和反革命两大势力作最后斗争的局面。这两大势力竖起了两面大旗：一面是红色的革命的大旗，第三国际[5]高举着，号召全世界一切被压迫阶级集合于其旗帜之下；一面是白色的反革命的大旗，国际联盟[6]高举着，号召全世界一切反革命分子集合于其旗帜之下。那些中间阶级，必定很快地分化，或者向左跑入革命派，或者向右跑入反革命派，没有他们“独立”的余地。所以，中国的中产阶级，以其本阶级为主体的“独立”革命思想，仅仅是一个幻想。","language":"中文","translation":false},{"id":"classes-1-8","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"小资产阶级。如自耕农[7]，手工业主，小知识阶层——学生界、中小学教员、小员司、小事务员、小律师，小商人等都属于这一类。这一个阶级，在人数上，在阶级性上，都值得大大注意。自耕农和手工业主所经营的，都是小生产的经济。这个小资产阶级内的各阶层虽然同处在小资产阶级经济地位，但有三个不同的部分。第一部分是有余钱剩米的，即用其体力或脑力劳动所得，除自给外，每年有余剩。这种人发财观念极重，对赵公元帅礼拜最勤，虽不妄想发大财，却总想爬上中产阶级地位。他们看见那些受人尊敬的小财东，往往垂着一尺长的涎水。这种人胆子小，他们怕官，也有点怕革命。因为他们的经济地位和中产阶级颇接近，故对于中产阶级的宣传颇相信，对于革命取怀疑的态度。这一部分人在小资产阶级中占少数，是小资产阶级的右翼。第二部分是在经济上大体上可以自给的。这一部分人比较第一部分人大不相同，他们也想发财，但是赵公元帅[8]总不让他们发财，而且因为近年以来帝国主义、军阀、封建地主、买办大资产阶级的压迫和剥削，他们感觉现在的世界已经不是从前的世界。他们觉得现在如果只使用和从前相等的劳动，就会不能维持生活。必须增加劳动时间，每天起早散晚，对于职业加倍注意，方能维持生活。他们有点骂人了，骂洋人叫“洋鬼子”，骂军阀叫“抢钱司令”，骂土豪劣绅叫“为富不仁”。对于反帝国主义反军阀的运动，仅怀疑其未必成功（理由是：洋人和军阀的来头那么大），不肯贸然参加，取了中立的态度，但是绝不反对革命。这一部分人数甚多，大概占小资产阶级的一半。第三部分是生活下降的。这一部分人好些大概原先是所谓殷实人家，渐渐变得仅仅可以保住，渐渐变得生活下降了。他们每逢年终结账一次，就吃惊一次，说：“咳，又亏了！”这种人因为他们过去过着好日子，后来逐年下降，负债渐多，渐次过着凄凉的日子，“瞻念前途，不寒而栗”。这种人在精神上感觉的痛苦很大，因为他们有一个从前和现在相反的比较。这种人在革命运动中颇要紧，是一个数量不小的群众，是小资产阶级的左翼。以上所说小资产阶级的三部分，对于革命的态度，在平时各不相同；但到战时，即到革命潮流高涨、可以看得见胜利的曙光时，不但小资产阶级的左派参加革命，中派亦可参加革命，即右派分子受了无产阶级和小资产阶级左派的革命大潮所裹挟，也只得附和着革命。我们从一九二五年的五卅运动[9]和各地农民运动的经验看来，这个断定是不错的。","language":"中文","translation":false},{"id":"classes-1-9","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"半无产阶级。此处所谓半无产阶级，包含：（一）绝大部分半自耕农[10]，（二）贫农，（三）小手工业者，（四）店员[11]，（五）小贩等五种。绝大部分半自耕农和贫农是农村中一个数量极大的群众。所谓农民问题，主要就是他们的问题。半自耕农、贫农和小手工业者所经营的，都是更细小的小生产的经济。绝大部分半自耕农和贫农虽同属半无产阶级，但其经济状况仍有上、中、下三个细别。半自耕农，其生活苦于自耕农，因其食粮每年大约有一半不够，须租别人田地，或者出卖一部分劳动力，或经营小商，以资弥补。春夏之间，青黄不接，高利向别人借债，重价向别人籴粮，较之自耕农的无求于人，自然景遇要苦，但是优于贫农。因为贫农无土地，每年耕种只得收获之一半或不足一半；半自耕农则租于别人的部分虽只收获一半或不足一半，然自有的部分却可全得。故半自耕农的革命性优于自耕农而不及贫农。贫农是农村中的佃农，受地主的剥削。其经济地位又分两部分。一部分贫农有比较充足的农具和相当数量的资金。此种农民，每年劳动结果，自己可得一半。不足部分，可以种杂粮、捞鱼虾、饲鸡豕，或出卖一部分劳动力，勉强维持生活，于艰难竭蹶之中，存聊以卒岁之想。故其生活苦于半自耕农，然较另一部分贫农为优。其革命性，则优于半自耕农而不及另一部分贫农。所谓另一部分贫农，则既无充足的农具，又无资金，肥料不足，土地歉收，送租之外，所得无几，更需要出卖一部分劳动力。荒时暴月，向亲友乞哀告怜，借得几斗几升，敷衍三日五日，债务丛集，如牛负重。他们是农民中极艰苦者，极易接受革命的宣传。小手工业者所以称为半无产阶级，是因为他们虽然自有简单的生产手段，且系一种自由职业，但他们也常常被迫出卖一部分劳动力，其经济地位略与农村中的贫农相当。因其家庭负担之重，工资和生活费用之不相称，时有贫困的压迫和失业的恐慌，和贫农亦大致相同。店员是商店的雇员，以微薄的薪资，供家庭的费用，物价年年增长，薪给往往须数年一增，偶与此辈倾谈，便见叫苦不迭。其地位和贫农及小手工业者不相上下，对于革命宣传极易接受。小贩不论肩挑叫卖，或街畔摊售，总之本小利微，吃着不够。其地位和贫农不相上下，其需要一个变更现状的革命，也和贫农相同。","language":"中文","translation":false},{"id":"classes-1-10","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"无产阶级。现代工业无产阶级约二百万人。中国因经济落后，故现代工业无产阶级人数不多。二百万左右的产业工人中，主要为铁路、矿山、海运、纺织、造船五种产业的工人，而其中很大一个数量是在外资产业的奴役下。工业无产阶级人数虽不多，却是中国新的生产力的代表者，是近代中国最进步的阶级，做了革命运动的领导力量。我们看四年以来的罢工运动，如海员罢工[12]、铁路罢工[13]、开滦和焦作煤矿罢工[14]、沙面罢工[15]以及“五卅”后上海香港两处的大罢工[16]所表现的力量，就可知工业无产阶级在中国革命中所处地位的重要。他们所以能如此，第一个原因是集中。无论哪种人都不如他们的集中。第二个原因是经济地位低下。他们失了生产手段，剩下两手，绝了发财的望，又受着帝国主义、军阀、资产阶级的极残酷的待遇，所以他们特别能战斗。都市苦力工人的力量也很可注意。以码头搬运夫和人力车夫占多数，粪夫清道夫等亦属于这一类。他们除双手外，别无长物，其经济地位和产业工人相似，惟不及产业工人的集中和在生产上的重要。中国尚少新式的资本主义的农业。所谓农村无产阶级，是指长工、月工、零工等雇农而言。此等雇农不仅无土地，无农具，又无丝毫资金，只得营工度日。其劳动时间之长，工资之少，待遇之薄，职业之不安定，超过其它工人。此种人在乡村中是最感困难者，在农民运动中和贫农处于同一紧要的地位。","language":"中文","translation":false},{"id":"classes-1-11","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"此外，还有数量不小的游民无产者，为失了土地的农民和失了工作机会的手工业工人。他们是人类生活中最不安定者。他们在各地都有秘密组织，如闽粤的“三合会”，湘鄂黔蜀的“哥老会”，皖豫鲁等省的“大刀会”，直隶及东三省的“在理会”，上海等处的“青帮”[17]，都曾经是他们的政治和经济斗争的互助团体。处置这一批人，是中国的困难的问题之一。这一批人很能勇敢奋斗，但有破坏性，如引导得法，可以变成一种革命力量。","language":"中文","translation":false},{"id":"classes-1-12","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"综上所述，可知一切勾结帝国主义的军阀、官僚、买办阶级、大地主阶级以及附属于他们的一部分反动知识界，是我们的敌人。工业无产阶级是我们革命的领导力量。一切半无产阶级、小资产阶级，是我们最接近的朋友。那动摇不定的中产阶级，其右翼可能是我们的敌人，其左翼可能是我们的朋友——但我们要时常提防他们，不要让他们扰乱了我们的阵线。","language":"中文","translation":false},{"id":"classes-1-13","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[1] 国家主义派指中国青年党，当时以其外围组织“中国国家主义青年团”的名义公开进行活动。组织这个政团的是一些反动政客，他们投靠帝国主义和当权的反动派，把反对中国共产党和苏联当作职业。","language":"中文","translation":false},{"id":"classes-1-14","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[2] 戴季陶（一八九一——一九四九），又名传贤，原籍浙江湖州，生于四川广汉。早年参加中国同盟会，从事过反对清政府和袁世凯的活动。后曾和蒋介石在上海共同经营交易所的投机事业。一九二五年随着孙中山的逝世和革命高潮的到来，他歪曲孙中山学说的革命内容，散布反对国共合作、反对工农革命运动的谬论，为后来蒋介石的反共活动作了准备。一九二七年南京国民政府成立后，历任国民政府委员、考试院院长等职。一九四九年二月，蒋介石的统治即将崩溃，戴季陶感到绝望而自杀。","language":"中文","translation":false},{"id":"classes-1-15","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[3] 北京《晨报》，初名《晨钟报》，一九一六年八月创刊于北京，一九一八年十二月改名为《晨报》，一九二八年六月停刊。","language":"中文","translation":false},{"id":"classes-1-16","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[4] 一九二二年和一九二三年间，孙中山在共产党人的帮助下，决定改组国民党，实行国共合作，容纳共产党人参加国民党，并于一九二四年一月在广州召开国民党第一次全国代表大会，实行联俄、联共、扶助农工的三大政策。李大钊、谭平山、毛泽东、林伯渠、瞿秋白等共产党人参加了这次大会。他们曾经被选为国民党中央执行委员会的委员或候补委员，担任过国民党的许多领导工作，对于帮助国民党走上革命的道路，起了重大的作用。","language":"中文","translation":false},{"id":"classes-1-17","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[5] 第三国际即共产国际，一九一九年三月在列宁领导下成立。一九二二年中国共产党参加共产国际，成为它的一个支部。一九四三年五月，共产国际执行委员会主席团通过决定，提议解散共产国际，同年六月共产国际正式宣布解散。","language":"中文","translation":false},{"id":"classes-1-18","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[6] 国际联盟简称国联，一九二○年一月正式成立。先后参加的有六十多个国家。国际联盟标榜以“促进国际合作，维持国际和平与安全”为目的，实际上日益成为帝国主义国家推行侵略政策的工具。第二次世界大战爆发后无形瓦解，一九四六年四月正式宣布解散。","language":"中文","translation":false},{"id":"classes-1-19","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[8] 赵公元帅是中国民间传说的财神，叫赵公明。","language":"中文","translation":false},{"id":"classes-1-20","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[9] 指一九二五年五月三十日爆发的反帝爱国运动。一九二五年五月间，上海、青岛的日本纱厂先后发生工人罢工的斗争，遭到日本帝国主义和北洋军阀的镇压。上海内外棉第七厂日本资本家在五月十五日枪杀了工人顾正红，并伤工人十余人。二十九日青岛工人被反动政府屠杀八人。五月三十日，上海二千余学生分头在公共租界各马路进行宣传讲演，一百余名遭巡捕（租界内的警察）逮捕，被拘押在南京路老闸巡捕房内，引起了学生和市民的极大愤慨，有近万人聚集在巡捕房门口，要求释放被捕学生。英帝国主义的巡捕向群众开枪，打死打伤许多人。这就是震惊中外的五卅惨案。六月，英日等帝国主义在上海和其它地方继续进行屠杀。这些屠杀事件激起了全国人民的公愤。广大的工人、学生和部分工商业者，在许多城市和县镇举行游行示威和罢工、罢课、罢市，形成了全国规模的反帝爱国运动高潮。","language":"中文","translation":false},{"id":"classes-1-21","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[10] 这里是指自己有一部分土地，同时租种一部分土地，或出卖一部分劳动力，或兼营小商的贫农。","language":"中文","translation":false},{"id":"classes-1-22","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[11] 店员有不同的阶层，他们一般不占有生产资料，生活来源的全部或者主要部分是依靠向店主出卖劳动力所取得的工资。毛泽东在这里所指的是店员中的一部分，还有一部分下层店员过着无产阶级的生活。","language":"中文","translation":false},{"id":"classes-1-23","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[12] 指一九二二年香港和上海的海员罢工。香港海员罢工爆发于一月十二日，坚持了八个星期。最后，香港英帝国主义当局被迫答应增加工资，恢复原工会，释放被捕工人，抚恤在罢工中死难烈士的家属。上海海员罢工于八月五日开始，坚持了三个星期，也得到胜利。","language":"中文","translation":false},{"id":"classes-1-24","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[13] 指一九二二年和一九二三年中国共产党领导的各主要铁路线的工人罢工。在罢工过程中，工人群众的觉悟迅速提高，要求改善生活的经济斗争迅速发展为反对军阀的政治斗争。一九二三年二月四日，京汉铁路工人为争取组织总工会的自由，举行总罢工。其它许多铁路的工人也纷纷响应。二月七日，英帝国主义支持的北洋军阀吴佩孚、萧耀南等，残酷地屠杀京汉铁路的工人，造成了二七惨案。","language":"中文","translation":false},{"id":"classes-1-25","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[14] 开滦煤矿是直隶省（今河北省）开平、滦县一带煤矿的总称，当时为英帝国主义者所控制。开滦罢工指一九二二年十月、十一月间矿工三万余人举行的大罢工。英帝国主义者和北洋军阀对这次罢工进行残酷的镇压，工人死伤很多，但是仍然坚持斗争。最后，英帝国主义者不得不答应给工人增加一部分工资。焦作煤矿，在河南省北部，当时也为英帝国主义者所控制。焦作罢工指一九二五年七月爆发的罢工。这次罢工是为响应五卅运动而发动的，前后坚持七个多月。最后，英帝国主义者不得不承认工会有代表工人的权利，并且被迫接受增加工资、不无故开除工人和补偿工人因罢工所受的损失等项条件。","language":"中文","translation":false},{"id":"classes-1-26","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[15] 沙面当时是英法帝国主义在广州的租界。一九二四年七月，统治沙面的帝国主义者颁布新警律，规定沙面的中国人出入租界必须携带贴有本人相片的执照，在租界内行动必须受各种苛刻的限制，但是外国人却可以自由出入活动。沙面工人于七月十五日宣告罢工，抗议这些无理措施。这次沙面罢工迫使英法帝国主义者取消了新警律。","language":"中文","translation":false},{"id":"classes-1-27","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[16] 指一九二五年六月一日开始的上海大罢工和六月十九日开始的香港大罢工。这两处罢工是当时全国反帝爱国运动的支柱。前者有二十多万工人参加，坚持了三四个月；后者有二十五万工人参加，坚持了一年零四个月，是截至当时为止的世界工人运动史中时间最长的一次罢工。","language":"中文","translation":false},{"id":"classes-1-28","author":"毛泽东","title":"中国社会各阶级的分析","location":"中国社会各阶级的分析（一九二五年十二月一日）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19251201.htm","text":"[17] 三合会、哥老会、大刀会、在理会、青帮是旧中国的一些民间秘密团体，参加者主要的是破产农民、失业手工业工人和流氓无产者。这类团体大都用宗教迷信为团聚成员的工具，采取家长制的组织形式，有的还拥有武装。参加这类团体的人，在社会生活中有互相援助的义务，有时还共同反抗压迫他们的地主、官僚和外国侵略者。但是，农民和手工业工人不可能依靠这类团体得到出路。同时，由于这类团体带有严重的封建性和盲目的破坏性，它们又往往容易被反动统治阶级和帝国主义势力所操纵和利用。随着工人阶级力量的壮大和中国共产党的成立，农民和手工业工人在共产党的领导之下逐步地建立了完全新式的群众组织，这类落后的团体就失掉了它们的存在价值。","language":"中文","translation":false},{"id":"practice-1-1","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"中文马克思主义文库 -> 毛泽东","language":"中文","translation":false},{"id":"practice-1-2","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"论认识和实践的关系——知和行的关系","language":"中文","translation":false},{"id":"practice-1-3","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"* 在中国共产党内，曾经有一部分教条主义的同志长期拒绝中国革命的经验，否认“马克思主义不是教条而是行动的指南”这个真理，而只生吞活剥马克思主义书籍中的只言片语，去吓唬人们。还有另一部分经验主义的同志长期拘守于自身的片断经验，不了解理论对于革命实践的重要性，看不见革命的全局，虽然也是辛苦地——但却是盲目地在工作。这两类同志的错误思想，特别是教条主义思想，曾经在一九三一年至一九三四年使得中国革命受了极大的损失，而教条主义者却是披着马克思主义的外衣迷惑了广大的同志。毛泽东的《实践论》，是为着用马克思主义的认识论观点去揭露党内的教条主义和经验主义——特别是教条主义这些主观主义的错误而写的。因为重点是揭露看轻实践的教条主义这种主观主义，故题为《实践论》。毛泽东曾以这篇论文的观点在延安的抗日军事政治大学作过讲演。","language":"中文","translation":false},{"id":"practice-1-4","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"马克思以前的唯物论，离开人的社会性，离开人的历史发展，去观察认识问题，因此不能了解认识对社会实践的依赖关系，即认识对生产和阶级斗争的依赖关系。","language":"中文","translation":false},{"id":"practice-1-5","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"首先，马克思主义者认为人类的生产活动是最基本的实践活动，是决定其它一切活动的东西。人的认识，主要地依赖于物质的生产活动，逐渐地了解自然的现象、自然的性质、自然的规律性、人和自然的关系；而且经过生产活动，也在各种不同程度上逐渐地认识了人和人的一定的相互关系。一切这些知识，离开生产活动是不能得到的。在没有阶级的社会中，每个人以社会一员的资格，同其它社会成员协力，结成一定的生产关系，从事生产活动，以解决人类物质生活问题。在各种阶级的社会中，各阶级的社会成员，则又以各种不同的方式，结成一定的生产关系，从事生产活动，以解决人类物质生活问题。这是人的认识发展的基本来源。","language":"中文","translation":false},{"id":"practice-1-6","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"人的社会实践，不限于生产活动一种形式，还有多种其它的形式，阶级斗争，政治生活，科学和艺术的活动，总之社会实际生活的一切领域都是社会的人所参加的。因此，人的认识，在物质生活以外，还从政治生活文化生活中（与物质生活密切联系），在各种不同程度上，知道人和人的各种关系。其中，尤以各种形式的阶级斗争，给予人的认识发展以深刻的影响。在阶级社会中，每一个人都在一定的阶级地位中生活，各种思想无不打上阶级的烙印。","language":"中文","translation":false},{"id":"practice-1-7","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"马克思主义者认为人类社会的生产活动，是一步又一步地由低级向高级发展，因此，人们的认识，不论对于自然界方面，对于社会方面，也都是一步又一步地由低级向高级发展，即由浅入深，由片面到更多的方面。在很长的历史时期内，大家对于社会的历史只能限于片面的了解，这一方面是由于剥削阶级的偏见经常歪曲社会的历史，另方面，则由于生产规模的狭小，限制了人们的眼界。人们能够对于社会历史的发展作全面的历史的了解，把对于社会的认识变成了科学，这只是到了伴随巨大生产力——大工业而出现近代无产阶级的时候，这就是马克思主义的科学。","language":"中文","translation":false},{"id":"practice-1-8","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"马克思主义者认为，只有人们的社会实践，才是人们对于外界认识的真理性的标准。实际的情形是这样的，只有在社会实践过程中（物质生产过程中，阶级斗争过程中，科学实验过程中），人们达到了思想中所预想的结果时，人们的认识才被证实了。人们要想得到工作的胜利即得到预想的结果，一定要使自己的思想合于客观外界的规律性，如果不合，就会在实践中失败。人们经过失败之后，也就从失败取得教训，改正自己的思想使之适合于外界的规律性，人们就能变失败为胜利，所谓“失败者成功之母”，“吃一堑长一智”，就是这个道理。辩证唯物论的认识论把实践提到第一的地位，认为人的认识一点也不能离开实践，排斥一切否认实践重要性、使认识离开实践的错误理论。列宁这样说过：“实践高于（理论的）认识，因为它不但有普遍性的品格，而且还有直接现实性的品格。”[1]马克思主义的哲学辩证唯物论有两个最显着的特点：一个是它的阶级性，公然申明辩证唯物论是为无产阶级服务的；再一个是它的实践性，强调理论对于实践的依赖关系，理论的基础是实践，又转过来为实践服务。判定认识或理论之是否真理，不是依主观上觉得如何而定，而是依客观上社会实践的结果如何而定。真理的标准只能是社会的实践。实践的观点是辩证唯物论的认识论之第一的和基本的观点[2]。","language":"中文","translation":false},{"id":"practice-1-9","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"然而人的认识究竟怎样从实践发生，而又服务于实践呢？这只要看一看认识的发展过程就会明了的。","language":"中文","translation":false},{"id":"practice-1-10","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"原来人在实践过程中，开始只是看到过程中各个事物的现象方面，看到各个事物的片面，看到各个事物之间的外部联系。例如有些外面的人们到延安来考察，头一二天，他们看到了延安的地形、街道、屋宇，接触了许多的人，参加了宴会、晚会和群众大会，听到了各种说话，看到了各种文件，这些就是事物的现象，事物的各个片面以及这些事物的外部联系。这叫做认识的感性阶段，就是感觉和印象的阶段。也就是延安这些各别的事物作用于考察团先生们的感官，引起了他们的感觉，在他们的脑子中生起了许多的印象，以及这些印象间的大概的外部的联系，这是认识的第一个阶段。在这个阶段中，人们还不能造成深刻的概念，作出合乎论理（即合乎逻辑）的结论。","language":"中文","translation":false},{"id":"practice-1-11","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"社会实践的继续，使人们在实践中引起感觉和印象的东西反复了多次，于是在人们的脑子里生起了一个认识过程中的突变（即飞跃），产生了概念。概念这种东西已经不是事物的现象，不是事物的各个片面，不是它们的外部联系，而是抓着了事物的本质，事物的全体，事物的内部联系了。概念同感觉，不但是数量上的差别，而且有了性质上的差别。循此继进，使用判断和推理的方法，就可产生出合乎论理的结论来。《三国演义》上所谓“眉头一皱计上心来”，我们普通说话所谓“让我想一想”，就是人在脑子中运用概念以作判断和推理的工夫。这是认识的第二个阶段。外来的考察团先生们在他们集合了各种材料，加上他们“想了一想”之后，他们就能够作出“共产党的抗日民族统一战线的政策是彻底的、诚恳的和真实的”这样一个判断了。在他们作出这个判断之后，如果他们对于团结救国也是真实的的话，那末他们就能够进一步作出这样的结论：“抗日民族统一战线是能够成功的。”这个概念、判断和推理的阶段，在人们对于一个事物的整个认识过程中是更重要的阶段，也就是理性认识的阶段。认识的真正任务在于经过感觉而到达于思维，到达于逐步了解客观事物的内部矛盾，了解它的规律性，了解这一过程和那一过程间的内部联系，即到达于论理的认识。重复地说，论理的认识所以和感性的认识不同，是因为感性的认识是属于事物之片面的、现象的、外部联系的东西，论理的认识则推进了一大步，到达了事物的全体的、本质的、内部联系的东西，到达了暴露周围世界的内在的矛盾，因而能在周围世界的总体上，在周围世界一切方面的内部联系上去把握周围世界的发展。","language":"中文","translation":false},{"id":"practice-1-12","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"这种基于实践的由浅入深的辩证唯物论的关于认识发展过程的理论，在马克思主义以前，是没有一个人这样解决过的。马克思主义的唯物论，第一次正确地解决了这个问题，唯物地而且辩证地指出了认识的深化的运动，指出了社会的人在他们的生产和阶级斗争的复杂的、经常反复的实践中，由感性认识到论理认识的推移的运动。列宁说过：“物质的抽象，自然规律的抽象，价值的抽象以及其它等等，一句话，一切科学的（正确的、郑重的、非瞎说的）抽象，都更深刻、更正确、更完全地反映着自然。”[3]马克思列宁主义认为：认识过程中两个阶段的特性，在低级阶段，认识表现为感性的，在高级阶段，认识表现为论理的，但任何阶段，都是统一的认识过程中的阶段。感性和理性二者的性质不同，但又不是互相分离的，它们在实践的基础上统一起来了。我们的实践证明：感觉到了的东西，我们不能立刻理解它，只有理解了的东西才更深刻地感觉它。感觉只解决现象问题，理论才解决本质问题。这些问题的解决，一点也不能离开实践。无论何人要认识什么事物，除了同那个事物接触，即生活于（实践于）那个事物的环境中，是没有法子解决的。不能在封建社会就预先认识资本主义社会的规律，因为资本主义还未出现，还无这种实践。马克思主义只能是资本主义社会的产物。马克思不能在自由资本主义时代就预先具体地认识帝国主义时代的某些特异的规律，因为帝国主义这个资本主义最后阶段还未到来，还无这种实践，只有列宁和斯大林才能担当此项任务。马克思、恩格斯、列宁、斯大林之所以能够作出他们的理论，除了他们的天才条件之外，主要地是他们亲自参加了当时的阶级斗争和科学实验的实践，没有这后一个条件，任何天才也是不能成功的。“秀才不出门，全知天下事”，在技术不发达的古代只是一句空话，在技术发达的现代虽然可以实现这句话，然而真正亲知的是天下实践着的人，那些人在他们的实践中间取得了“知”，经过文字和技术的传达而到达于“秀才”之手，秀才乃能间接地“知天下事”。如果要直接地认识某种或某些事物，便只有亲身参加于变革现实、变革某种或某些事物的实践的斗争中，才能触到那种或那些事物的现象，也只有在亲身参加变革现实的实践的斗争中，才能暴露那种或那些事物的本质而理解它们。这是任何人实际上走着的认识路程，不过有些人故意歪曲地说些反对的话罢了。世上最可笑的是那些“知识里手”[4]，有了道听途说的一知半解，便自封为“天下第一”，适足见其不自量而已。知识的问题是一个科学问题，来不得半点的虚伪和骄傲，决定地需要的倒是其反面——诚实和谦逊的态度。你要有知识，你就得参加变革现实的实践。你要知道梨子的滋味，你就得变革梨子，亲口吃一吃。你要知道原子的组织同性质，你就得实行物理学和化学的实验，变革原子的情况。你要知道革命的理论和方法，你就得参加革命。一切真知都是从直接经验发源的。但人不能事事直接经验，事实上多数的知识都是间接经验的东西，这就是一切古代的和外域的知识。这些知识在古人在外人是直接经验的东西，如果在古人外人直接经验时是符合于列宁所说的条件“科学的抽象”，是科学地反映了客观的事物，那末这些知识是可靠的，否则就是不可靠的。所以，一个人的知识，不外直接经验的和间接经验的两部分。而且在我为间接经验者，在人则仍为直接经验。因此，就知识的总体说来，无论何种知识都是不能离开直接经验的。任何知识的来源，在于人的肉体感官对客观外界的感觉，否认了这个感觉，否认了直接经验，否认亲自参加变革现实的实践，他就不是唯物论者。“知识里手”之所以可笑，原因就是在这个地方。中国人有一句老话：“不入虎穴，焉得虎子。”这句话对于人们的实践是真理，对于认识论也是真理。离开实践的认识是不可能的。","language":"中文","translation":false},{"id":"practice-1-13","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"为了明了基于变革现实的实践而产生的辩证唯物论的认识运动——认识的逐渐深化的运动，下面再举出几个具体的例子。","language":"中文","translation":false},{"id":"practice-1-14","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"无产阶级对于资本主义社会的认识，在其实践的初期——破坏机器和自发斗争时期，他们还只在感性认识的阶段，只认识资本主义各个现象的片面及其外部的联系。这时，他们还是一个所谓“自在的阶级”。但是到了他们实践的第二个时期——有意识有组织的经济斗争和政治斗争的时期，由于实践，由于长期斗争的经验，经过马克思、恩格斯用科学的方法把这种种经验总结起来，产生了马克思主义的理论，用以教育无产阶级，这样就使无产阶级理解了资本主义社会的本质，理解了社会阶级的剥削关系，理解了无产阶级的历史任务，这时他们就变成了一个“自为的阶级”。","language":"中文","translation":false},{"id":"practice-1-15","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"中国人民对于帝国主义的认识也是这样。第一阶段是表面的感性的认识阶段，表现在太平天国运动和义和团运动等笼统的排外主义的斗争上[5]。第二阶段才进到理性的认识阶段，看出了帝国主义内部和外部的各种矛盾，并看出了帝国主义联合中国买办阶级和封建阶级以压榨中国人民大众的实质，这种认识是从一九一九年五四运动[6]前后才开始的。","language":"中文","translation":false},{"id":"practice-1-16","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"我们再来看战争。战争的领导者，如果他们是一些没有战争经验的人，对于一个具体的战争（例如我们过去十年的土地革命战争）的深刻的指导规律，在开始阶段是不了解的。他们在开始阶段只是身历了许多作战的经验，而且败仗是打得很多的。然而由于这些经验（胜仗，特别是败仗的经验），使他们能够理解贯串整个战争的内部的东西，即那个具体战争的规律性，懂得了战略和战术，因而能够有把握地去指导战争。此时，如果改换一个无经验的人去指导，又会要在吃了一些败仗之后（有了经验之后）才能理会战争的正确的规律。","language":"中文","translation":false},{"id":"practice-1-17","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"常常听到一些同志在不能勇敢接受工作任务时说出来的一句话：没有把握。为什么没有把握呢？因为他对于这项工作的内容和环境没有规律性的了解，或者他从来就没有接触过这类工作，或者接触得不多，因而无从谈到这类工作的规律性。及至把工作的情况和环境给以详细分析之后，他就觉得比较地有了把握，愿意去做这项工作。如果这个人在这项工作中经过了一个时期，他有了这项工作的经验了，而他又是一个肯虚心体察情况的人，不是一个主观地、片面地、表面地看问题的人，他就能够自己做出应该怎样进行工作的结论，他的工作勇气也就可以大大地提高了。只有那些主观地、片面地和表面地看问题的人，跑到一个地方，不问环境的情况，不看事情的全体（事情的历史和全部现状），也不触到事情的本质（事情的性质及此一事情和其它事情的内部联系），就自以为是地发号施令起来，这样的人是没有不跌交子的。","language":"中文","translation":false},{"id":"practice-1-18","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"由此看来，认识的过程，第一步，是开始接触外界事情，属于感觉的阶段。第二步，是综合感觉的材料加以整理和改造，属于概念、判断和推理的阶段。只有感觉的材料十分丰富（不是零碎不全）和合于实际（不是错觉），才能根据这样的材料造出正确的概念和论理来。","language":"中文","translation":false},{"id":"practice-1-19","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"这里有两个要点必须着重指明。第一个，在前面已经说过的，这里再重复说一说，就是理性认识依赖于感性认识的问题。如果以为理性认识可以不从感性认识得来，他就是一个唯心论者。哲学史上有所谓“唯理论”一派，就是只承认理性的实在性，不承认经验的实在性，以为只有理性靠得住，而感觉的经验是靠不住的，这一派的错误在于颠倒了事实。理性的东西所以靠得住，正是由于它来源于感性，否则理性的东西就成了无源之水，无本之木，而只是主观自生的靠不住的东西了。从认识过程的秩序说来，感觉经验是第一的东西，我们强调社会实践在认识过程中的意义，就在于只有社会实践才能使人的认识开始发生，开始从客观外界得到感觉经验。一个闭目塞听、同客观外界根本绝缘的人，是无所谓认识的。认识开始于经验——这就是认识论的唯物论。","language":"中文","translation":false},{"id":"practice-1-20","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"第二是认识有待于深化，认识的感性阶段有待于发展到理性阶段——这就是认识论的辩证法[7]。如果以为认识可以停顿在低级的感性阶段，以为只有感性认识可靠，而理性认识是靠不住的，这便是重复了历史上的“经验论”的错误。这种理论的错误，在于不知道感觉材料固然是客观外界某些真实性的反映（我这里不来说经验只是所谓内省体验的那种唯心的经验论），但它们仅是片面的和表面的东西，这种反映是不完全的，是没有反映事物本质的。要完全地反映整个的事物，反映事物的本质，反映事物的内部规律性，就必须经过思考作用，将丰富的感觉材料加以去粗取精、去伪存真、由此及彼、由表及里的改造制作工夫，造成概念和理论的系统，就必须从感性认识跃进到理性认识。这种改造过的认识，不是更空虚了更不可靠了的认识，相反，只要是在认识过程中根据于实践基础而科学地改造过的东西，正如列宁所说乃是更深刻、更正确、更完全地反映客观事物的东西。庸俗的事务主义家不是这样，他们尊重经验而看轻理论，因而不能通观客观过程的全体，缺乏明确的方针，没有远大的前途，沾沾自喜于一得之功和一孔之见。这种人如果指导革命，就会引导革命走上碰壁的地步。","language":"中文","translation":false},{"id":"practice-1-21","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"理性认识依赖于感性认识，感性认识有待于发展到理性认识，这就是辩证唯物论的认识论。哲学上的“唯理论”和“经验论”都不懂得认识的历史性或辩证性，虽然各有片面的真理（对于唯物的唯理论和经验论而言，非指唯心的唯理论和经验论），但在认识论的全体上则都是错误的。由感性到理性之辩证唯物论的认识运动，对于一个小的认识过程（例如对于一个事物或一件工作的认识）是如此，对于一个大的认识过程（例如对于一个社会或一个革命的认识）也是如此。","language":"中文","translation":false},{"id":"practice-1-22","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"然而认识运动至此还没有完结。辩证唯物论的认识运动，如果只到理性认识为止，那末还只说到问题的一半。而且对于马克思主义的哲学说来，还只说到非十分重要的那一半。马克思主义的哲学认为十分重要的问题，不在于懂得了客观世界的规律性，因而能够解释世界，而在于拿了这种对于客观规律性的认识去能动地改造世界。在马克思主义看来，理论是重要的，它的重要性充分地表现在列宁说过的一句话：“没有革命的理论，就不会有革命的运动。”[8]然而马克思主义看重理论，正是，也仅仅是，因为它能够指导行动。如果有了正确的理论，只是把它空谈一阵，束之高阁，并不实行，那末，这种理论再好也是没有意义的。认识从实践始，经过实践得到了理论的认识，还须再回到实践去。认识的能动作用，不但表现于从感性的认识到理性的认识之能动的飞跃，更重要的还须表现于从理性的认识到革命的实践这一个飞跃。抓着了世界的规律性的认识，必须把它再回到改造世界的实践中去，再用到生产的实践、革命的阶级斗争和民族斗争的实践以及科学实验的实践中去。这就是检验理论和发展理论的过程，是整个认识过程的继续。理论的东西之是否符合于客观真理性这个问题，在前面说的由感性到理性之认识运动中是没有完全解决的，也不能完全解决的。要完全地解决这个问题，只有把理性的认识再回到社会实践中去，应用理论于实践，看它是否能够达到预想的目的。许多自然科学理论之所以被称为真理，不但在于自然科学家们创立这些学说的时候，而且在于为尔后的科学实践所证实的时候。马克思列宁主义之所以被称为真理，也不但在于马克思、恩格斯、列宁、斯大林等人科学地构成这些学说的时候，而且在于为尔后革命的阶级斗争和民族斗争的实践所证实的时候。辩证唯物论之所以为普遍真理，在于经过无论什么人的实践都不能逃出它的范围。人类认识的历史告诉我们，许多理论的真理性是不完全的，经过实践的检验而纠正了它们的不完全性。许多理论是错误的，经过实践的检验而纠正其错误。所谓实践是真理的标准，所谓“生活、实践底观点，应该是认识论底首先的和基本的观点”[9]，理由就在这个地方。斯大林说得好：“理论若不和革命实践联系起来，就会变成无对象的理论，同样，实践若不以革命理论为指南，就会变成盲目的实践。”[10]","language":"中文","translation":false},{"id":"practice-1-23","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"说到这里，认识运动就算完成了吗？我们的答复是完成了，又没有完成。社会的人们投身于变革在某一发展阶段内的某一客观过程的实践中（不论是关于变革某一自然过程的实践，或变革某一社会过程的实践），由于客观过程的反映和主观能动性的作用，使得人们的认识由感性的推移到了理性的，造成了大体上相应于该客观过程的法则性的思想、理论、计划或方案，然后再应用这种思想、理论、计划或方案于该同一客观过程的实践，如果能够实现预想的目的，即将预定的思想、理论、计划、方案在该同一过程的实践中变为事实，或者大体上变为事实，那末，对于这一具体过程的认识运动算是完成了。例如，在变革自然的过程中，某一工程计划的实现，某一科学假想的证实，某一器物的制成，某一农产的收获，在变革社会过程中某一罢工的胜利，某一战争的胜利，某一教育计划的实现，都算实现了预想的目的。然而一般地说来，不论在变革自然或变革社会的实践中，人们原定的思想、理论、计划、方案，毫无改变地实现出来的事，是很少的。这是因为从事变革现实的人们，常常受着许多的限制，不但常常受着科学条件和技术条件的限制，而且也受着客观过程的发展及其表现程度的限制（客观过程的方面及本质尚未充分暴露）。在这种情形之下，由于实践中发现前所未料的情况，因而部分地改变思想、理论、计划、方案的事是常有的，全部地改变的事也是有的。即是说，原定的思想、理论、计划、方案，部分地或全部地不合于实际，部分错了或全部错了的事，都是有的。许多时候须反复失败过多次，才能纠正错误的认识，才能到达于和客观过程的规律性相符合，因而才能够变主观的东西为客观的东西，即在实践中得到预想的结果。但是不管怎样，到了这种时候，人们对于在某一发展阶段内的某一客观过程的认识运动，算是完成了。","language":"中文","translation":false},{"id":"practice-1-24","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"然而对于过程的推移而言，人们的认识运动是没有完成的。任何过程，不论是属于自然界的和属于社会的，由于内部的矛盾和斗争，都是向前推移向前发展的，人们的认识运动也应跟着推移和发展。依社会运动来说，真正的革命的指导者，不但在于当自己的思想、理论、计划、方案有错误时须得善于改正，如同上面已经说到的，而且在于当某一客观过程已经从某一发展阶段向另一发展阶段推移转变的时候，须得善于使自己和参加革命的一切人员在主观认识上也跟着推移转变，即是要使新的革命任务和新的工作方案的提出，适合于新的情况的变化。革命时期情况的变化是很急速的，如果革命党人的认识不能随之而急速变化，就不能引导革命走向胜利。","language":"中文","translation":false},{"id":"practice-1-25","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"然而思想落后于实际的事是常有的，这是因为人的认识受了许多社会条件的限制的缘故。我们反对革命队伍中的顽固派，他们的思想不能随变化了的客观情况而前进，在历史上表现为右倾机会主义。这些人看不出矛盾的斗争已将客观过程推向前进了，而他们的认识仍然停止在旧阶段。一切顽固党的思想都有这样的特征。他们的思想离开了社会的实践，他们不能站在社会车轮的前头充任向导的工作，他们只知跟在车子后面怨恨车子走得太快了，企图把它向后拉，开倒车。","language":"中文","translation":false},{"id":"practice-1-26","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"我们也反对“左”翼空谈主义。他们的思想超过客观过程的一定发展阶段，有些把幻想看作真理，有些则把仅在将来有现实可能性的理想，勉强地放在现时来做，离开了当前大多数人的实践，离开了当前的现实性，在行动上表现为冒险主义。","language":"中文","translation":false},{"id":"practice-1-27","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"唯心论和机械唯物论，机会主义和冒险主义，都是以主观和客观相分裂，以认识和实践相脱离为特征的。以科学的社会实践为特征的马克思列宁主义的认识论，不能不坚决反对这些错误思想。马克思主义者承认，在绝对的总的宇宙发展过程中，各个具体过程的发展都是相对的，因而在绝对真理的长河中，人们对于在各个一定发展阶段上的具体过程的认识只具有相对的真理性。无数相对的真理之总和，就是绝对的真理[11]。客观过程的发展是充满着矛盾和斗争的发展，人的认识运动的发展也是充满着矛盾和斗争的发展。一切客观世界的辩证法的运动，都或先或后地能够反映到人的认识中来。社会实践中的发生、发展和消灭的过程是无穷的，人的认识的发生、发展和消灭的过程也是无穷的。根据于一定的思想、理论、计划、方案以从事于变革客观现实的实践，一次又一次地向前，人们对于客观现实的认识也就一次又一次地深化。客观现实世界的变化运动永远没有完结，人们在实践中对于真理的认识也就永远没有完结。马克思列宁主义并没有结束真理，而是在实践中不断地开辟认识真理的道路。我们的结论是主观和客观、理论和实践、知和行的具体的历史的统一，反对一切离开具体历史的“左”的或右的错误思想。","language":"中文","translation":false},{"id":"practice-1-28","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"社会的发展到了今天的时代，正确地认识世界和改造世界的责任，已经历史地落在无产阶级及其政党的肩上。这种根据科学认识而定下来的改造世界的实践过程，在世界、在中国均已到达了一个历史的时节——自有历史以来未曾有过的重大时节，这就是整个儿地推翻世界和中国的黑暗面，把它们转变过来成为前所未有的光明世界。无产阶级和革命人民改造世界的斗争，包括实现下述的任务：改造客观世界，也改造自己的主观世界——改造自己的认识能力，改造主观世界同客观世界的关系。地球上已经有一部分实行了这种改造，这就是苏联。他们还正在促进这种改造过程。中国人民和世界人民也都正在或将要通过这样的改造过程。所谓被改造的客观世界，其中包括了一切反对改造的人们，他们的被改造，须要通过强迫的阶段，然后才能进入自觉的阶段。世界到了全人类都自觉地改造自己和改造世界的时候，那就是世界的共产主义时代。","language":"中文","translation":false},{"id":"practice-1-29","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"通过实践而发现真理，又通过实践而证实真理和发展真理。从感性认识而能动地发展到理性认识，又从理性认识而能动地指导革命实践，改造主观世界和客观世界。实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度。这就是辩证唯物论的全部认识论，这就是辩证唯物论的知行统一观。","language":"中文","translation":false},{"id":"practice-1-30","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[1] 见列宁《黑格尔〈逻辑学〉一书摘要》。新的译文是：“实践高于（理论的）认识，因为它不仅具有普遍性的品格，而且还具有直接现实性的品格。”（《列宁全集》第55卷，人民出版社1990年版，第183页）","language":"中文","translation":false},{"id":"practice-1-31","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[2] 参见马克思《关于费尔巴哈的提纲》（《马克思恩格斯选集》第1卷，人民出版社1972年版，第16—19页）和列宁《唯物主义和经验批判主义》第二章第六节（《列宁全集》第18卷，人民出版社1988年版，第144页）。","language":"中文","translation":false},{"id":"practice-1-32","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[3] 见列宁《黑格尔〈逻辑学〉一书摘要》（《列宁全集》第55卷，人民出版社1990年版，第142页）。","language":"中文","translation":false},{"id":"practice-1-33","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[4] 里手，湖南方言，内行的意思。","language":"中文","translation":false},{"id":"practice-1-34","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[5] 一九五一年三月二十七日，毛泽东在致李达的信中说：“《实践论》中将太平天国放在排外主义一起说不妥，出选集时拟加修改，此处暂仍照原。”","language":"中文","translation":false},{"id":"practice-1-35","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[6] 五四运动是一九一九年五月四日发生的反帝反封建的爱国运动。当时，第一次世界大战刚刚结束，英、美、法、日、意等战胜国在巴黎召开对德和会，决定由日本继承德国在中国山东的特权。中国是参加对德宣战的战胜国之一，但北洋军阀政府却准备接受这个决定。五月四日，北京学生游行示威，反对帝国主义的这一无理决定和北洋军阀政府的妥协。这次运动迅速地获得了全国人民的响应，到六月三日以后，发展成为有工人阶级、城市小资产阶级和民族资产阶级参加的广大群众性的反帝反封建的爱国运动。五四运动也是反对封建文化的新文化运动。以一九一五年《青年杂志》（后改名《新青年》）创刊为起点的新文化运动，竖起“民主”和“科学”的旗帜，反对旧道德，提倡新道德，反对旧文学，提倡新文学。五四运动中的先进分子接受了马克思主义，使新文化运动发展成为马克思主义思想运动，他们致力于马克思主义同中国工人运动相结合，在思想上和干部上准备了中国共产党的成立。","language":"中文","translation":false},{"id":"practice-1-36","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[7] 参见列宁《黑格尔〈逻辑学〉一书摘要》：“要理解，就必须从经验开始理解、研究，从经验上升到一般。”（《列宁全集》第55卷，人民出版社1990年版，第175页）","language":"中文","translation":false},{"id":"practice-1-37","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[8] 见列宁《俄国社会民主党人的任务》（《列宁全集》第2卷，人民出版社1984年版，第443页）；并见列宁《怎么办？》第一章第四节（《列宁全集》第6卷，人民出版社1986年版，第23页）。","language":"中文","translation":false},{"id":"practice-1-38","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[9] 见列宁《唯物主义和经验批判主义》第二章第六节（《列宁全集》第18卷，人民出版社1988年版，第144页）。","language":"中文","translation":false},{"id":"practice-1-39","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[10] 见斯大林《论列宁主义基础》第三部分《理论》。新的译文是：“离开革命实践的理论是空洞的理论，而不以革命理论为指南的实践是盲目的实践。”（《斯大林选集》上卷，人民出版社1979年版，第199—200页）","language":"中文","translation":false},{"id":"practice-1-40","author":"毛泽东","title":"实践论","location":"实践论：论认识和实践的关系——知和行的关系（一九三七年七月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193707.htm","text":"[11] 参见列宁《唯物主义和经验批判主义》第二章第五节。原文是：“人类思维按其本性是能够给我们提供并且正在提供由相对真理的总和所构成的绝对真理的。”（《列宁全集》第18卷，人民出版社1988年版，第135页）","language":"中文","translation":false},{"id":"contradiction-1-1","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"中文马克思主义文库 -> 毛泽东","language":"中文","translation":false},{"id":"contradiction-1-2","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"* 这篇哲学论文，是毛泽东继《实践论》之后，为了同一的目的，即为了克服存在于中国共产党内的严重的教条主义思想而写的，曾在延安的抗日军事政治大学作过讲演。在收入本书第一版的时候，作者作了部分的补充、删节和修改。","language":"中文","translation":false},{"id":"contradiction-1-3","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"事物的矛盾法则，即对立统一的法则，是唯物辩证法的最根本的法则。列宁说：“就本来的意义讲，辩证法是研究对象的本质自身中的矛盾。”[1]列宁常称这个法则为辩证法的本质，又称之为辩证法的核心[2]。因此，我们在研究这个法则时，不得不涉及广泛的方面，不得不涉及许多的哲学问题。如果我们将这些问题都弄清楚了，我们就在根本上懂得了唯物辩证法。这些问题是：两种宇宙观；矛盾的普遍性；矛盾的特殊性；主要的矛盾和主要的矛盾方面；矛盾诸方面的同一性和斗争性；对抗在矛盾中的地位。","language":"中文","translation":false},{"id":"contradiction-1-4","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"苏联哲学界在最近数年中批判了德波林学派[3]的唯心论，这件事引起了我们的极大的兴趣。德波林的唯心论在中国共产党内发生了极坏的影响，我们党内的教条主义思想不能说和这个学派的作风没有关系。因此，我们现在的哲学研究工作，应当以扫除教条主义思想为主要的目标。","language":"中文","translation":false},{"id":"contradiction-1-5","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在人类的认识史中，从来就有关于宇宙发展法则的两种见解，一种是形而上学的见解，一种是辩证法的见解，形成了互相对立的两种宇宙观。列宁说：“对于发展（进化）所持的两种基本的（或两种可能的？或两种在历史上常见的？）观点是：（一）认为发展是减少和增加，是重复；（二）认为发展是对立的统一（统一物分成为两个互相排斥的对立，而两个对立又互相关联着）。”[4]列宁说的就是这两种不同的宇宙观。","language":"中文","translation":false},{"id":"contradiction-1-6","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"形而上学，亦称玄学。这种思想，无论在中国，在欧洲，在一个很长的历史时间内，是属于唯心论的宇宙观，并在人们的思想中占了统治的地位。在欧洲，资产阶级初期的唯物论，也是形而上学的。由于欧洲许多国家的社会经济情况进到了资本主义高度发展的阶段，生产力、阶级斗争和科学均发展到了历史上未有过的水平，工业无产阶级成为历史发展的最伟大的动力，因而产生了马克思主义的唯物辩证法的宇宙观。于是，在资产阶级那里，除了公开的极端露骨的反动的唯心论之外，还出现了庸俗的进化论，出来对抗唯物辩证法。","language":"中文","translation":false},{"id":"contradiction-1-7","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"所谓形而上学的或庸俗进化论的宇宙观，就是用孤立的、静止的和片面的观点去看世界。这种宇宙观把世界一切事物，一切事物的形态和种类，都看成是永远彼此孤立和永远不变化的。如果说有变化，也只是数量的增减和场所的变更。而这种增减和变更的原因，不在事物的内部而在事物的外部，即是由于外力的推动。形而上学家认为，世界上各种不同事物和事物的特性，从它们一开始存在的时候就是如此。后来的变化，不过是数量上的扩大或缩小。他们认为一种事物永远只能反复地产生为同样的事物，而不能变化为另一种不同的事物。在形而上学家看来，资本主义的剥削，资本主义的竞争，资本主义社会的个人主义思想等，就是在古代的奴隶社会里，甚至在原始社会里，都可以找得出来，而且会要永远不变地存在下去。说到社会发展的原因，他们就用社会外部的地理、气候等条件去说明。他们简单地从事物外部去找发展的原因，否认唯物辩证法所主张的事物因内部矛盾引起发展的学说。因此，他们不能解释事物的质的多样性，不能解释一种质变为他种质的现象。这种思想，在欧洲，在十七世纪和十八世纪是机械唯物论，在十九世纪末和二十世纪初则有庸俗进化论。在中国，则有所谓“天不变，道亦不变”[5]的形而上学的思想，曾经长期地为腐朽了的封建统治阶级所拥护。近百年来输入了欧洲的机械唯物论和庸俗进化论，则为资产阶级所拥护。","language":"中文","translation":false},{"id":"contradiction-1-8","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"和形而上学的宇宙观相反，唯物辩证法的宇宙观主张从事物的内部、从一事物对他事物的关系去研究事物的发展，即把事物的发展看做是事物内部的必然的自己的运动，而每一事物的运动都和它的周围其它事物互相联系着和互相影响着。事物发展的根本原因，不是在事物的外部而是在事物的内部，在于事物内部的矛盾性。任何事物内部都有这种矛盾性，因此引起了事物的运动和发展。事物内部的这种矛盾性是事物发展的根本原因，一事物和他事物的互相联系和互相影响则是事物发展的第二位的原因。这样，唯物辩证法就有力地反对了形而上学的机械唯物论和庸俗进化论的外因论或被动论。这是清楚的，单纯的外部原因只能引起事物的机械的运动，即范围的大小，数量的增减，不能说明事物何以有性质上的千差万别及其互相变化。事实上，即使是外力推动的机械运动，也要通过事物内部的矛盾性。植物和动物的单纯的增长，数量的发展，主要地也是由于内部矛盾所引起的。同样，社会的发展，主要地不是由于外因而是由于内因。许多国家在差不多一样的地理和气候的条件下，它们发展的差异性和不平衡性，非常之大。同一个国家吧，在地理和气候并没有变化的情形下，社会的变化却是很大的。帝国主义的俄国变为社会主义的苏联，封建的闭关锁国的日本变为帝国主义的日本，这些国家的地理和气候并没有变化。长期地被封建制度统治的中国，近百年来发生了很大的变化，现在正在变化到一个自由解放的新中国的方向去，中国的地理和气候并没有变化。整个地球及地球各部分的地理和气候也是变化着的，但以它们的变化和社会的变化相比较，则显得很微小，前者是以若干万年为单位而显现其变化的，后者则在几千年、几百年、几十年、甚至几年或几个月（在革命时期）内就显现其变化了。按照唯物辩证法的观点，自然界的变化，主要地是由于自然界内部矛盾的发展。社会的变化，主要地是由于社会内部矛盾的发展，即生产力和生产关系的矛盾，阶级之间的矛盾，新旧之间的矛盾，由于这些矛盾的发展，推动了社会的前进，推动了新旧社会的代谢。唯物辩证法是否排除外部的原因呢？并不排除。唯物辩证法认为外因是变化的条件，内因是变化的根据，外因通过内因而起作用。鸡蛋因得适当的温度而变化为鸡子，但温度不能使石头变为鸡子，因为二者的根据是不同的。各国人民之间的互相影响是时常存在的。在资本主义时代，特别是在帝国主义和无产阶级革命的时代，各国在政治上、经济上和文化上的互相影响和互相激动，是极其巨大的。十月社会主义革命不只是开创了俄国历史的新纪元，而且开创了世界历史的新纪元，影响到世界各国内部的变化，同样地而且还特别深刻地影响到中国内部的变化，但是这种变化是通过了各国内部和中国内部自己的规律性而起的。两军相争，一胜一败，所以胜败，皆决于内因。胜者或因其强，或因其指挥无误，败者或因其弱，或因其指挥失宜，外因通过内因而引起作用。一九二七年中国大资产阶级战败了无产阶级，是通过中国无产阶级内部的（中国共产党内部的）机会主义而起作用的。当着我们清算了这种机会主义的时候，中国革命就重新发展了。后来，中国革命又受了敌人的严重的打击，是因为我们党内产生了冒险主义。当着我们清算了这种冒险主义的时候，我们的事业就又重新发展了。由此看来，一个政党要引导革命到胜利，必须依靠自己政治路线的正确和组织上的巩固。","language":"中文","translation":false},{"id":"contradiction-1-9","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"辩证法的宇宙观，不论在中国，在欧洲，在古代就产生了。但是古代的辩证法带着自发的朴素的性质，根据当时的社会历史条件，还不可能有完备的理论，因而不能完全解释宇宙，后来就被形而上学所代替。生活在十八世纪末和十九世纪初期的德国著名哲学家黑格尔，对于辩证法曾经给了很重要的贡献，但是他的辩证法却是唯心的辩证法。直到无产阶级运动的伟大的活动家马克思和恩格斯综合了人类认识史的积极的成果，特别是批判地吸取了黑格尔的辩证法的合理的部分，创造了辩证唯物论和历史唯物论这个伟大的理论，才在人类认识史上起了一个空前的大革命。后来，经过列宁和斯大林，又发展了这个伟大的理论。这个理论一经传到中国来，就在中国思想界引起了极大的变化。","language":"中文","translation":false},{"id":"contradiction-1-10","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"这个辩证法的宇宙观，主要地就是教导人们要善于去观察和分析各种事物的矛盾的运动，并根据这种分析，指出解决矛盾的方法。因此，具体地了解事物矛盾这一个法则，对于我们是非常重要的。","language":"中文","translation":false},{"id":"contradiction-1-11","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"为了叙述的便利起见，我在这里先说矛盾的普遍性，再说矛盾的特殊性。这是因为马克思主义的伟大的创造者和继承者马克思、恩格斯、列宁、斯大林他们发现了唯物辩证法的宇宙观，已经把唯物辩证法应用在人类历史的分析和自然历史的分析的许多方面，应用在社会的变革和自然的变革（例如在苏联）的许多方面，获得了极其伟大的成功，矛盾的普遍性已经被很多人所承认，因此，关于这个问题只需要很少的话就可以说明白；而关于矛盾的特殊性的问题，则还有很多的同志，特别是教条主义者，弄不清楚。他们不了解矛盾的普遍性即寓于矛盾的特殊性之中。他们也不了解研究当前具体事物的矛盾的特殊性，对于我们指导革命实践的发展有何等重要的意义。因此，关于矛盾的特殊性的问题应当着重地加以研究，并用足够的篇幅加以说明。为了这个缘故，当着我们分析事物矛盾的法则的时候，我们就先来分析矛盾的普遍性的问题，然后再着重地分析矛盾的特殊性的问题，最后仍归到矛盾的普遍性的问题。","language":"中文","translation":false},{"id":"contradiction-1-12","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"矛盾的普遍性或绝对性这个问题有两方面的意义。其一是说，矛盾存在于一切事物的发展过程中；其二是说，每一事物的发展过程中存在着自始至终的矛盾运动。","language":"中文","translation":false},{"id":"contradiction-1-13","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"恩格斯说：“运动本身就是矛盾。”[6]列宁对于对立统一法则所下的定义，说它就是“承认（发现）自然界（精神和社会两者也在内）的一切现象和过程都含有互相矛盾、互相排斥、互相对立的趋向”[7]。这些意见是对的吗？是对的。一切事物中包含的矛盾方面的相互依赖和相互斗争，决定一切事物的生命，推动一切事物的发展。没有什么事物是不包含矛盾的，没有矛盾就没有世界。","language":"中文","translation":false},{"id":"contradiction-1-14","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"矛盾是简单的运动形式（例如机械性的运动）的基础，更是复杂的运动形式的基础。","language":"中文","translation":false},{"id":"contradiction-1-15","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"恩格斯这样说明过矛盾的普遍性：“如果简单的机械的移动本身包含着矛盾，那末，物质的更高的运动形式，特别是有机生命及其发展，就更加包含着矛盾。……生命首先就在于：生物在每一个瞬间是它自身，但却又是别的什么。所以，生命也是存在于物体和过程本身中的不断地自行产生并自行解决的矛盾；这一矛盾一停止，生命亦即停止，于是死就来到。同样，我们看到了，在思维的范围以内我们也不能避免矛盾，并且我们看到了，例如，人的内部无限的认识能力与此种认识能力仅在外部被局限的而且认识上也被局限的个别人们身上的实际的实现二者之间的矛盾，是在人类世代的无穷的——至少对于我们，实际上是无穷的——连续系列之中，是在无穷的前进运动之中解决的。”","language":"中文","translation":false},{"id":"contradiction-1-16","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"“高等数学的主要基础之一，就是矛盾……”","language":"中文","translation":false},{"id":"contradiction-1-17","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"“就是初等数学，也充满着矛盾。……”[8]","language":"中文","translation":false},{"id":"contradiction-1-18","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"列宁也这样说明过矛盾的普遍性：“在数学中，正和负，微分和积分。","language":"中文","translation":false},{"id":"contradiction-1-19","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在力学中，作用和反作用。","language":"中文","translation":false},{"id":"contradiction-1-20","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在物理学中，阳电和阴电。","language":"中文","translation":false},{"id":"contradiction-1-21","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在化学中，原子的化合和分解。","language":"中文","translation":false},{"id":"contradiction-1-22","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在社会科学中，阶级斗争。”[9]","language":"中文","translation":false},{"id":"contradiction-1-23","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"战争中的攻守，进退，胜败，都是矛盾着的现象。失去一方，他方就不存在。双方斗争而又联结，组成了战争的总体，推动了战争的发展，解决了战争的问题。","language":"中文","translation":false},{"id":"contradiction-1-24","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"人的概念的每一差异，都应把它看作是客观矛盾的反映。客观矛盾反映入主观的思想，组成了概念的矛盾运动，推动了思想的发展，不断地解决了人们的思想问题。","language":"中文","translation":false},{"id":"contradiction-1-25","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"党内不同思想的对立和斗争是经常发生的，这是社会的阶级矛盾和新旧事物的矛盾在党内的反映。党内如果没有矛盾和解决矛盾的思想斗争，党的生命也就停止了。","language":"中文","translation":false},{"id":"contradiction-1-26","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"由此看来，不论是简单的运动形式，或复杂的运动形式，不论是客观现象，或思想现象，矛盾是普遍地存在着，矛盾存在于一切过程中，这一点已经弄清楚了。但是每一过程的开始阶段，是否也有矛盾存在呢？是否每一事物的发展过程具有自始至终的矛盾运动呢？","language":"中文","translation":false},{"id":"contradiction-1-27","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"从苏联哲学界批判德波林学派的文章中看出，德波林学派有这样一种见解，他们认为矛盾不是一开始就在过程中出现，须待过程发展到一定的阶段才出现。那末，在那一时间以前，过程发展的原因不是由于内部的原因，而是由于外部的原因了。这样，德波林回到形而上学的外因论和机械论去了。拿这种见解去分析具体的问题，他们就看见在苏联条件下富农和一般农民之间只有差异，并无矛盾，完全同意了布哈林的意见。在分析法国革命时，他们就认为在革命前，工农资产阶级合组的第三等级中，也只有差异，并无矛盾。德波林学派这类见解是反马克思主义的。他们不知道世界上的每一差异中就已经包含着矛盾，差异就是矛盾。劳资之间，从两阶级发生的时候起，就是互相矛盾的，仅仅还没有激化而已。工农之间，即使在苏联的社会条件下，也有差异，它们的差异就是矛盾，仅仅不会激化成为对抗，不取阶级斗争的形态，不同于劳资间的矛盾；它们在社会主义建设中形成巩固的联盟，并在由社会主义走向共产主义的发展过程中逐渐地解决这个矛盾。这是矛盾的差别性的问题，不是矛盾的有无的问题。矛盾是普遍的、绝对的，存在于事物发展的一切过程中，又贯串于一切过程的始终。","language":"中文","translation":false},{"id":"contradiction-1-28","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"新过程的发生是什么呢？这是旧的统一和组成此统一的对立成分让位于新的统一和组成此统一的对立成分，于是新过程就代替旧过程而发生。旧过程完结了，新过程发生了。新过程又包含着新矛盾，开始它自己的矛盾发展史。","language":"中文","translation":false},{"id":"contradiction-1-29","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"事物发展过程的自始至终的矛盾运动，列宁指出马克思在《资本论》中模范地作了这样的分析。这是研究任何事物发展过程所必须应用的方法。列宁自己也正确地应用了它，贯彻于他的全部著作中。","language":"中文","translation":false},{"id":"contradiction-1-30","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"“马克思在《资本论》中，首先分析的是资产阶级社会（商品社会）里最简单的、最普通的、最基本的、最常见的、最平常的、碰到亿万次的关系——商品交换。这一分析在这个最简单的现象之中（资产阶级社会的这个‘细胞’之中）暴露了现代社会的一切矛盾（以及一切矛盾的胚芽）。往后的叙述又向我们表明了这些矛盾和这个社会各个部分总和的自始至终的发展（增长与运动两者）。”","language":"中文","translation":false},{"id":"contradiction-1-31","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"列宁说了上面的话之后，接着说道：“这应该是一般辩证法的……叙述（以及研究）方法。”[10]","language":"中文","translation":false},{"id":"contradiction-1-32","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"中国共产党人必须学会这个方法，才能正确地分析中国革命的历史和现状，并推断革命的将来。","language":"中文","translation":false},{"id":"contradiction-1-33","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"矛盾存在于一切事物发展的过程中，矛盾贯串于每一事物发展过程的始终，这是矛盾的普遍性和绝对性，前面已经说过了。现在来说矛盾的特殊性和相对性。","language":"中文","translation":false},{"id":"contradiction-1-34","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"这个问题，应从几种情形中去研究。","language":"中文","translation":false},{"id":"contradiction-1-35","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"首先是各种物质运动形式中的矛盾，都带特殊性。人的认识物质，就是认识物质的运动形式，因为除了运动的物质以外，世界上什么也没有，而物质的运动则必取一定的形式。对于物质的每一种运动形式，必须注意它和其它各种运动形式的共同点。但是，尤其重要的，成为我们认识事物的基础的东西，则是必须注意它的特殊点，就是说，注意它和其它运动形式的质的区别。只有注意了这一点，才有可能区别事物。任何运动形式，其内部都包含着本身特殊的矛盾。这种特殊的矛盾，就构成一事物区别于他事物的特殊的本质。这就是世界上诸种事物所以有千差万别的内在的原因，或者叫做根据。自然界存在着许多的运动形式，机械运动、发声、发光、发热、电流、化分、化合等等都是。所有这些物质的运动形式，都是互相依存的，又是本质上互相区别的。每一物质的运动形式所具有的特殊的本质，为它自己的特殊的矛盾所规定。这种情形，不但在自然界中存在着，在社会现象和思想现象中也是同样地存在着。每一种社会形式和思想形式，都有它的特殊的矛盾和特殊的本质。","language":"中文","translation":false},{"id":"contradiction-1-36","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"科学研究的区分，就是根据科学对象所具有的特殊的矛盾性。因此，对于某一现象的领域所特有的某一种矛盾的研究，就构成某一门科学的对象。例如，数学中的正数和负数，机械学中的作用和反作用，物理学中的阴电和阳电，化学中的化分和化合，社会科学中的生产力和生产关系、阶级和阶级的互相斗争，军事学中的攻击和防御，哲学中的唯心论和唯物论、形而上学观和辩证法观等等，都是因为具有特殊的矛盾和特殊的本质，才构成了不同的科学研究的对象。固然，如果不认识矛盾的普遍性，就无从发现事物运动发展的普遍的原因或普遍的根据；但是，如果不研究矛盾的特殊性，就无从确定一事物不同于他事物的特殊的本质，就无从发现事物运动发展的特殊的原因，或特殊的根据，也就无从辨别事物，无从区分科学研究的领域。","language":"中文","translation":false},{"id":"contradiction-1-37","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"就人类认识运动的秩序说来，总是由认识个别的和特殊的事物，逐步地扩大到认识一般的事物。人们总是首先认识了许多不同事物的特殊的本质，然后才有可能更进一步地进行概括工作，认识诸种事物的共同的本质。当着人们已经认识了这种共同的本质以后，就以这种共同的认识为指导，继续地向着尚未研究过的或者尚未深入地研究过的各种具体的事物进行研究，找出其特殊的本质，这样才可以补充、丰富和发展这种共同的本质的认识，而使这种共同的本质的认识不致变成枯槁的和僵死的东西。这是两个认识的过程：一个是由特殊到一般，一个是由一般到特殊。人类的认识总是这样循环往复地进行的，而每一次的循环（只要是严格地按照科学的方法）都可能使人类的认识提高一步，使人类的认识不断地深化。我们的教条主义者在这个问题上的错误，就是，一方面，不懂得必须研究矛盾的特殊性，认识各别事物的特殊的本质，才有可能充分地认识矛盾的普遍性，充分地认识诸种事物的共同的本质；另一方面，不懂得在我们认识了事物的共同的本质以后，还必须继续研究那些尚未深入地研究过的或者新冒出来的具体的事物。我们的教条主义者是懒汉，他们拒绝对于具体事物做任何艰苦的研究工作，他们把一般真理看成是凭空出现的东西，把它变成为人们所不能够捉摸的纯粹抽象的公式，完全否认了并且颠倒了这个人类认识真理的正常秩序。他们也不懂得人类认识的两个过程的互相联结——由特殊到一般，又由一般到特殊，他们完全不懂得马克思主义的认识论。","language":"中文","translation":false},{"id":"contradiction-1-38","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"不但要研究每一个大系统的物质运动形式的特殊的矛盾性及其所规定的本质，而且要研究每一个物质运动形式在其发展长途中的每一个过程的特殊的矛盾及其本质。一切运动形式的每一个实在的非臆造的发展过程内，都是不同质的。我们的研究工作必须着重这一点，而且必须从这一点开始。","language":"中文","translation":false},{"id":"contradiction-1-39","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"不同质的矛盾，只有用不同质的方法才能解决。例如，无产阶级和资产阶级的矛盾，用社会主义革命的方法去解决；人民大众和封建制度的矛盾，用民主革命的方法去解决；殖民地和帝国主义的矛盾，用民族革命战争的方法去解决；在社会主义社会中工人阶级和农民阶级的矛盾，用农业集体化和农业机械化的方法去解决；共产党内的矛盾，用批评和自我批评的方法去解决；社会和自然的矛盾，用发展生产力的方法去解决。过程变化，旧过程和旧矛盾消灭，新过程和新矛盾发生，解决矛盾的方法也因之而不同。俄国的二月革命和十月革命所解决的矛盾及其所用以解决矛盾的方法是根本上不相同的。用不同的方法去解决不同的矛盾，这是马克思列宁主义者必须严格地遵守的一个原则。教条主义者不遵守这个原则，他们不了解诸种革命情况的区别，因而也不了解应当用不同的方法去解决不同的矛盾，而只是千篇一律地使用一种自以为不可改变的公式到处硬套，这就只能使革命遭受挫折，或者将本来做得好的事情弄得很坏。","language":"中文","translation":false},{"id":"contradiction-1-40","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"为要暴露事物发展过程中的矛盾在其总体上、在其相互联结上的特殊性，就是说暴露事物发展过程的本质，就必须暴露过程中矛盾各方面的特殊性，否则暴露过程的本质成为不可能，这也是我们作研究工作时必须十分注意的。","language":"中文","translation":false},{"id":"contradiction-1-41","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"一个大的事物，在其发展过程中，包含着许多的矛盾。例如，在中国资产阶级民主革命过程中，有中国社会各被压迫阶级和帝国主义的矛盾，有人民大众和封建制度的矛盾，有无产阶级和资产阶级的矛盾，有农民及城市小资产阶级和资产阶级的矛盾，有各个反动的统治集团之间的矛盾等等，情形是非常复杂的。这些矛盾，不但各各有其特殊性，不能一律看待，而且每一矛盾的两方面，又各各有其特点，也是不能一律看待的。我们从事中国革命的人，不但要在各个矛盾的总体上，即矛盾的相互联结上，了解其特殊性，而且只有从矛盾的各个方面着手研究，才有可能了解其总体。所谓了解矛盾的各个方面，就是了解它们每一方面各占何等特定的地位，各用何种具体形式和对方发生互相依存又互相矛盾的关系，在互相依存又互相矛盾中，以及依存破裂后，又各用何种具体的方法和对方作斗争。研究这些问题，是十分重要的事情。列宁说：马克思主义的最本质的东西，马克思主义的活的灵魂，就在于具体地分析具体的情况[11]。就是说的这个意思。我们的教条主义者违背列宁的指示，从来不用脑筋具体地分析任何事物，做起文章或演说来，总是空洞无物的八股调，在我们党内造成了一种极坏的作风。","language":"中文","translation":false},{"id":"contradiction-1-42","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"研究问题，忌带主观性、片面性和表面性。所谓主观性，就是不知道客观地看问题，也就是不知道用唯物的观点去看问题。这一点，我在《实践论》一文中已经说过了。所谓片面性，就是不知道全面地看问题。例如：只了解中国一方、不了解日本一方，只了解共产党一方、不了解国民党一方，只了解无产阶级一方、不了解资产阶级一方，只了解农民一方、不了解地主一方，只了解顺利情形一方、不了解困难情形一方，只了解过去一方、不了解将来一方，只了解个体一方、不了解总体一方，只了解缺点一方、不了解成绩一方，只了解原告一方、不了解被告一方，只了解革命的秘密工作一方、不了解革命的公开工作一方，如此等等。一句话，不了解矛盾各方的特点。这就叫做片面地看问题。或者叫做只看见局部，不看见全体，只看见树木，不看见森林。这样，是不能找出解决矛盾的方法的，是不能完成革命任务的，是不能做好所任工作的，是不能正确地发展党内的思想斗争的。孙子论军事说：“知彼知己，百战不殆。”[12]他说的是作战的双方。唐朝人魏征说过：“兼听则明，偏信则暗。”[13]也懂得片面性不对。可是我们的同志看问题，往往带片面性，这样的人就往往碰钉子。《水浒传》上宋江三打祝家庄[14]，两次都因情况不明，方法不对，打了败仗。后来改变方法，从调查情形入手，于是熟悉了盘陀路，拆散了李家庄、扈家庄和祝家庄的联盟，并且布置了藏在敌人营盘里的伏兵，用了和外国故事中所说木马计[15]相像的方法，第三次就打了胜仗。《水浒传》上有很多唯物辩证法的事例，这个三打祝家庄，算是最好的一个。列宁说：“要真正地认识对象，就必须把握和研究它的一切方面、一切联系和‘媒介’。我们决不会完全地作到这一点，可是要求全面性，将使我们防止错误，防止僵化。”[16]我们应该记得他的话。表面性，是对矛盾总体和矛盾各方的特点都不去看，否认深入事物里面精细地研究矛盾特点的必要，仅仅站在那里远远地望一望，粗枝大叶地看到一点矛盾的形相，就想动手去解决矛盾（答复问题、解决纠纷、处理工作、指挥战争）。这样的做法，没有不出乱子的。中国的教条主义和经验主义的同志们所以犯错误，就是因为他们看事物的方法是主观的、片面的和表面的。片面性、表面性也是主观性，因为一切客观事物本来是互相联系的和具有内部规律的，人们不去如实地反映这些情况，而只是片面地或表面地去看它们，不认识事物的互相联系，不认识事物的内部规律，所以这种方法是主观主义的。","language":"中文","translation":false},{"id":"contradiction-1-43","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"不但事物发展的全过程中的矛盾运动，在其相互联结上，在其各方情况上，我们必须注意其特点，而且在过程发展的各个阶段中，也有其特点，也必须注意。","language":"中文","translation":false},{"id":"contradiction-1-44","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"事物发展过程的根本矛盾及为此根本矛盾所规定的过程的本质，非到过程完结之日，是不会消灭的；但是事物发展的长过程中的各个发展的阶段，情形又往往互相区别。这是因为事物发展过程的根本矛盾的性质和过程的本质虽然没有变化，但是根本矛盾在长过程中的各个发展阶段上采取了逐渐激化的形式。并且，被根本矛盾所规定或影响的许多大小矛盾中，有些是激化了，有些是暂时地或局部地解决了，或者缓和了，又有些是发生了，因此，过程就显出阶段性来。如果人们不去注意事物发展过程中的阶段性，人们就不能适当地处理事物的矛盾。","language":"中文","translation":false},{"id":"contradiction-1-45","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"例如，自由竞争时代的资本主义发展为帝国主义，这时，无产阶级和资产阶级这两个根本矛盾着的阶级的性质和这个社会的资本主义的本质，并没有变化；但是，两阶级的矛盾激化了，独占资本和自由资本之间的矛盾发生了，宗主国和殖民地的矛盾激化了，各资本主义国家间的矛盾即由各国发展不平衡的状态而引起的矛盾特别尖锐地表现出来了，因此形成了资本主义的特殊阶段，形成了帝国主义阶段。列宁主义之所以成为帝国主义和无产阶级革命时代的马克思主义，就是因为列宁和斯大林正确地说明了这些矛盾，并正确地作出了解决这些矛盾的无产阶级革命的理论和策略。","language":"中文","translation":false},{"id":"contradiction-1-46","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"拿从辛亥革命[17]开始的中国资产阶级民主革命过程的情形来看，也有了若干特殊阶段。特别是在资产阶级领导时期的革命和在无产阶级领导时期的革命，区别为两个很大不同的历史阶段。这就是：由于无产阶级的领导，根本地改变了革命的面貌，引出了阶级关系的新调度，农民革命的大发动，反帝国主义和反封建主义的革命彻底性，由民主革命转变到社会主义革命的可能性，等等。所有这些，都是在资产阶级领导革命时期不可能出现的。虽然整个过程中根本矛盾的性质，过程之反帝反封建的民主革命的性质（其反面是半殖民地半封建的性质），并没有变化，但是，在这长时间中，经过了辛亥革命失败和北洋军阀统治，第一次民族统一战线的建立和一九二四年至一九二七年的革命，统一战线破裂和资产阶级转入反革命，新的军阀战争，土地革命战争，第二次民族统一战线建立和抗日战争等等大事变，二十多年间经过了几个发展阶段。在这些阶段中，包含着有些矛盾激化了（例如土地革命战争和日本侵入东北四省[18]），有些矛盾部分地或暂时地解决了（例如北洋军阀的被消灭，我们没收了地主的土地），有些矛盾重新发生了（例如新军阀之间的斗争，南方各革命根据地丧失后地主又重新收回土地）等等特殊的情形。","language":"中文","translation":false},{"id":"contradiction-1-47","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"研究事物发展过程中的各个发展阶段上的矛盾的特殊性，不但必须在其联结上、在其总体上去看，而且必须从各个阶段中矛盾的各个方面去看。","language":"中文","translation":false},{"id":"contradiction-1-48","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"例如国共两党。国民党方面，在第一次统一战线时期，因为它实行了孙中山的联俄、联共、援助工农的三大政策，所以它是革命的、有朝气的，它是各阶级的民主革命的联盟。一九二七年以后，国民党变到了与此相反的方面，成了地主和大资产阶级的反动集团。一九三六年十二月西安事变[19]后又开始向停止内战、联合共产党共同反对日本帝国主义这个方面转变。这就是国民党在三个阶段上的特点。形成这些特点，当然有种种的原因。中国共产党方面，在第一次统一战线时期，它是幼年的党，它英勇地领导了一九二四年至一九二七年的革命；但在对于革命的性质、任务和方法的认识方面，却表现了它的幼年性，因此在这次革命的后期所发生的陈独秀主义[20]能够起作用，使这次革命遭受了失败。一九二七年以后，它又英勇地领导了土地革命战争，创立了革命的军队和革命的根据地，但是它也犯过冒险主义的错误，使军队和根据地都受了很大的损失。一九三五年以后，它又纠正了冒险主义的错误，领导了新的抗日的统一战线，这个伟大的斗争现在正在发展。在这个阶段上，共产党是一个经过了两次革命的考验、有了丰富的经验的党。这些就是中国共产党在三个阶段上的特点。形成这些特点也有种种的原因。不研究这些特点，就不能了解两党在各个发展阶段上的特殊的相互关系：统一战线的建立，统一战线的破裂，再一个统一战线的建立。而要研究两党的种种特点，更根本的就必须研究这两党的阶级基础以及因此在各个时期所形成的它们和其它方面的矛盾的对立。例如，国民党在它第一次联合共产党的时期，一方面有和国外帝国主义的矛盾，因而它反对帝国主义；另一方面有和国内人民大众的矛盾，它在口头上虽然允许给予劳动人民以许多的利益，但在实际上则只给予很少的利益，或者简直什么也不给。在它进行反共战争的时期，则和帝国主义、封建主义合作反对人民大众，一笔勾销了人民大众原来在革命中所争得的一切利益，激化了它和人民大众的矛盾。现在抗日时期，国民党和日本帝国主义有矛盾，它一面要联合共产党，同时它对共产党和国内人民并不放松其斗争和压迫。共产党则无论在哪一时期，均和人民大众站在一道，反对帝国主义和封建主义；但在现在的抗日时期，由于国民党表示抗日，它对国民党和国内封建势力，也就采取了缓和的政策。由于这些情况，所以或者造成了两党的联合，或者造成了两党的斗争，而且即使在两党联合的时期也有又联合又斗争的复杂的情况。如果我们不去研究这些矛盾方面的特点，我们就不但不能了解这两个党各各和其它方面的关系，也不能了解两党之间的相互关系。","language":"中文","translation":false},{"id":"contradiction-1-49","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"由此看来，不论研究何种矛盾的特性——各个物质运动形式的矛盾，各个运动形式在各个发展过程中的矛盾，各个发展过程的矛盾的各方面，各个发展过程在其各个发展阶段上的矛盾以及各个发展阶段上的矛盾的各方面，研究所有这些矛盾的特性，都不能带主观随意性，必须对它们实行具体的分析。离开具体的分析，就不能认识任何矛盾的特性。我们必须时刻记得列宁的话：对于具体的事物作具体的分析。","language":"中文","translation":false},{"id":"contradiction-1-50","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"这种具体的分析，马克思、恩格斯首先给了我们以很好的模范。","language":"中文","translation":false},{"id":"contradiction-1-51","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"当马克思、恩格斯把这事物矛盾的法则应用到社会历史过程的研究的时候，他们看出生产力和生产关系之间的矛盾，看出剥削阶级和被剥削阶级之间的矛盾以及由于这些矛盾所产生的经济基础和政治及思想等上层建筑之间的矛盾，而这些矛盾如何不可避免地会在各种不同的阶级社会中，引出各种不同的社会革命。","language":"中文","translation":false},{"id":"contradiction-1-52","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"马克思把这一法则应用到资本主义社会经济结构的研究的时候，他看出这一社会的基本矛盾在于生产的社会性和占有制的私人性之间的矛盾。这个矛盾表现于在各别企业中的生产的有组织性和在全社会中的生产的无组织性之间的矛盾。这个矛盾的阶级表现则是资产阶级和无产阶级之间的矛盾。","language":"中文","translation":false},{"id":"contradiction-1-53","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"由于事物范围的极其广大，发展的无限性，所以，在一定场合为普遍性的东西，而在另一一定场合则变为特殊性。反之，在一定场合为特殊性的东西，而在另一一定场合则变为普遍性。资本主义制度所包含的生产社会化和生产资料私人占有制的矛盾，是所有有资本主义的存在和发展的各国所共有的东西，对于资本主义说来，这是矛盾的普遍性。但是资本主义的这种矛盾，乃是一般阶级社会发展在一定历史阶段上的东西，对于一般阶级社会中的生产力和生产关系的矛盾说来，这是矛盾的特殊性。然而，当着马克思把资本主义社会这一切矛盾的特殊性解剖出来之后，同时也就更进一步地、更充分地、更完全地把一般阶级社会中这个生产力和生产关系的矛盾的普遍性阐发出来了。","language":"中文","translation":false},{"id":"contradiction-1-54","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"由于特殊的事物是和普遍的事物联结的，由于每一个事物内部不但包含了矛盾的特殊性，而且包含了矛盾的普遍性，普遍性即存在于特殊性之中，所以，当着我们研究一定事物的时候，就应当去发现这两方面及其互相联结，发现一事物内部的特殊性和普遍性的两方面及其互相联结，发现一事物和它以外的许多事物的互相联结。斯大林在他的名著《论列宁主义基础》一书中说明列宁主义的历史根源的时候，他分析了列宁主义所由产生的国际环境，分析了在帝国主义条件下已经发展到极点的资本主义的诸矛盾，以及这些矛盾使无产阶级革命成为直接实践的问题，并造成了直接冲击资本主义的良好的条件。不但如此，他又分析了为什么俄国成为列宁主义的策源地，分析了沙皇俄国当时是帝国主义一切矛盾的集合点以及俄国无产阶级所以能够成为国际的革命无产阶级的先锋队的原因。这样，斯大林分析了帝国主义的矛盾的普遍性，说明列宁主义是帝国主义和无产阶级革命时代的马克思主义；又分析了沙俄帝国主义在这一般矛盾中所具有的特殊性，说明俄国成了无产阶级革命理论和策略的故乡，而在这种特殊性中间就包含了矛盾的普遍性。斯大林的这种分析，给我们提供了认识矛盾的特殊性和普遍性及其互相联结的模范。","language":"中文","translation":false},{"id":"contradiction-1-55","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"马克思和恩格斯，同样地列宁和斯大林，他们对于应用辩证法到客观现象的研究的时候，总是指导人们不要带上任何的主观随意性，而必须从客观的实际运动所包含的具体的条件，去看出这些现象中的具体的矛盾、矛盾各方面的具体的地位以及矛盾的具体的相互关系。我们的教条主义者因为没有这种研究态度，所以弄得一无是处。我们必须以教条主义的失败为鉴戒，学会这种研究态度，舍此没有第二种研究法。","language":"中文","translation":false},{"id":"contradiction-1-56","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"矛盾的普遍性和矛盾的特殊性的关系，就是矛盾的共性和个性的关系。其共性是矛盾存在于一切过程中，并贯串于一切过程的始终，矛盾即是运动，即是事物，即是过程，也即是思想。否认事物的矛盾就是否认了一切。这是共通的道理，古今中外，概莫能外。所以它是共性，是绝对性。然而这种共性，即包含于一切个性之中，无个性即无共性。假如除去一切个性，还有什么共性呢？因为矛盾的各各特殊，所以造成了个性。一切个性都是有条件地暂时地存在的，所以是相对的。","language":"中文","translation":false},{"id":"contradiction-1-57","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"这一共性个性、绝对相对的道理，是关于事物矛盾的问题的精髓，不懂得它，就等于抛弃了辩证法。","language":"中文","translation":false},{"id":"contradiction-1-58","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"四 主要的矛盾和主要的矛盾方面","language":"中文","translation":false},{"id":"contradiction-1-59","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在矛盾特殊性的问题中，还有两种情形必须特别地提出来加以分析，这就是主要的矛盾和主要的矛盾方面。","language":"中文","translation":false},{"id":"contradiction-1-60","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在复杂的事物的发展过程中，有许多的矛盾存在，其中必有一种是主要的矛盾，由于它的存在和发展规定或影响着其它矛盾的存在和发展。","language":"中文","translation":false},{"id":"contradiction-1-61","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"例如在资本主义社会中，无产阶级和资产阶级这两个矛盾着的力量是主要的矛盾；其它的矛盾力量，例如，残存的封建阶级和资产阶级的矛盾，农民小资产者和资产阶级的矛盾，无产阶级和农民小资产者的矛盾，自由资产阶级和垄断资产阶级的矛盾，资产阶级的民主主义和资产阶级的法西斯主义的矛盾，资本主义国家相互间的矛盾，帝国主义和殖民地的矛盾，以及其它的矛盾，都为这个主要的矛盾力量所规定、所影响。","language":"中文","translation":false},{"id":"contradiction-1-62","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"半殖民地的国家如中国，其主要矛盾和非主要矛盾的关系呈现着复杂的情况。","language":"中文","translation":false},{"id":"contradiction-1-63","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"当着帝国主义向这种国家举行侵略战争的时候，这种国家的内部各阶级，除开一些叛国分子以外，能够暂时地团结起来举行民族战争去反对帝国主义。这时，帝国主义和这种国家之间的矛盾成为主要的矛盾，而这种国家内部各阶级的一切矛盾（包括封建制度和人民大众之间这个主要矛盾在内），便都暂时地降到次要和服从的地位。中国一八四○年的鸦片战争[21]，一八九四年的中日战争[22]，一九○○年的义和团战争[23]和目前的中日战争，都有这种情形。","language":"中文","translation":false},{"id":"contradiction-1-64","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"然而在另一种情形之下，则矛盾的地位起了变化。当着帝国主义不是用战争压迫而是用政治、经济、文化等比较温和的形式进行压迫的时候，半殖民地国家的统治阶级就会向帝国主义投降，二者结成同盟，共同压迫人民大众。这种时候，人民大众往往采取国内战争的形式，去反对帝国主义和封建阶级的同盟，而帝国主义则往往采取间接的方式去援助半殖民地国家的反动派压迫人民，而不采取直接行动，显出了内部矛盾的特别尖锐性。中国的辛亥革命战争，一九二四年至一九二七年的革命战争，一九二七年以后的十年土地革命战争，都有这种情形。还有半殖民地国家各个反动的统治集团之间的内战，例如在中国的军阀战争，也属于这一类。","language":"中文","translation":false},{"id":"contradiction-1-65","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"当着国内革命战争发展到从根本上威胁帝国主义及其走狗国内反动派的存在的时候，帝国主义就往往采取上述方法以外的方法，企图维持其统治：或者分化革命阵线的内部，或者直接出兵援助国内反动派。这时，外国帝国主义和国内反动派完全公开地站在一个极端，人民大众则站在另一极端，成为一个主要矛盾，而规定或影响其它矛盾的发展状态。十月革命后各资本主义国家援助俄国反动派，是武装干涉的例子。一九二七年的蒋介石的叛变，是分化革命阵线的例子。","language":"中文","translation":false},{"id":"contradiction-1-66","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"然而不管怎样，过程发展的各个阶段中，只有一种主要的矛盾起着领导的作用，是完全没有疑义的。","language":"中文","translation":false},{"id":"contradiction-1-67","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"由此可知，任何过程如果有多数矛盾存在的话，其中必定有一种是主要的，起着领导的、决定的作用，其它则处于次要和服从的地位。因此，研究任何过程，如果是存在着两个以上矛盾的复杂过程的话，就要用全力找出它的主要矛盾。捉住了这个主要矛盾，一切问题就迎刃而解了。这是马克思研究资本主义社会告诉我们的方法。列宁和斯大林研究帝国主义和资本主义总危机的时候，列宁和斯大林研究苏联经济的时候，也告诉了这种方法。万千的学问家和实行家，不懂得这种方法，结果如堕烟海，找不到中心，也就找不到解决矛盾的方法。","language":"中文","translation":false},{"id":"contradiction-1-68","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"不能把过程中所有的矛盾平均看待，必须把它们区别为主要的和次要的两类，着重于捉住主要的矛盾，已如上述。但是在各种矛盾之中，不论是主要的或次要的，矛盾着的两个方面，又是否可以平均看待呢？也是不可以的。无论什么矛盾，矛盾的诸方面，其发展是不平衡的。有时候似乎势均力敌，然而这只是暂时的和相对的情形，基本的形态则是不平衡。矛盾着的两方面中，必有一方面是主要的，他方面是次要的。其主要的方面，即所谓矛盾起主导作用的方面。事物的性质，主要地是由取得支配地位的矛盾的主要方面所规定的。","language":"中文","translation":false},{"id":"contradiction-1-69","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"然而这种情形不是固定的，矛盾的主要和非主要的方面互相转化着，事物的性质也就随着起变化。在矛盾发展的一定过程或一定阶段上，主要方面属于甲方，非主要方面属于乙方；到了另一发展阶段或另一发展过程时，就互易其位置，这是依靠事物发展中矛盾双方斗争的力量的增减程度来决定的。","language":"中文","translation":false},{"id":"contradiction-1-70","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"我们常常说“新陈代谢”这句话。新陈代谢是宇宙间普遍的永远不可抵抗的规律。依事物本身的性质和条件，经过不同的飞跃形式，一事物转化为他事物，就是新陈代谢的过程。任何事物的内部都有其新旧两个方面的矛盾，形成为一系列的曲折的斗争。斗争的结果，新的方面由小变大，上升为支配的东西；旧的方面则由大变小，变成逐步归于灭亡的东西。而一当新的方面对于旧的方面取得支配地位的时候，旧事物的性质就变化为新事物的性质。由此可见，事物的性质主要地是由取得支配地位的矛盾的主要方面所规定的。取得支配地位的矛盾的主要方面起了变化，事物的性质也就随着起变化。","language":"中文","translation":false},{"id":"contradiction-1-71","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在资本主义社会中，资本主义已从旧的封建主义社会时代的附庸地位，转化成了取得支配地位的力量，社会的性质也就由封建主义的变为资本主义的。在新的资本主义社会时代，封建势力则由原来处在支配地位的力量转化为附庸的力量，随着也就逐步地归于消灭了，例如英法诸国就是如此。随着生产力的发展，资产阶级由新的起进步作用的阶级，转化为旧的起反动作用的阶级，以至于最后被无产阶级所推翻，而转化为私有的生产资料被剥夺和失去权力的阶级，这个阶级也就要逐步归于消灭了。人数比资产阶级多得多、并和资产阶级同时生长、但被资产阶级统治着的无产阶级，是一个新的力量，它由初期的附属于资产阶级的地位，逐步地壮大起来，成为独立的和在历史上起主导作用的阶级，以至最后夺取政权成为统治阶级。这时，社会的性质，就由旧的资本主义的社会转化成了新的社会主义的社会。这就是苏联已经走过和一切其它国家必然要走的道路。","language":"中文","translation":false},{"id":"contradiction-1-72","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"就中国的情形来说，帝国主义处在形成半殖民地这种矛盾的主要地位，压迫中国人民，中国则由独立国变为半殖民地。然而事情必然会变化，在双方斗争的局势中，中国人民在无产阶级领导之下所生长起来的力量必然会把中国由半殖民地变为独立国，而帝国主义则将被打倒，旧中国必然要变为新中国。","language":"中文","translation":false},{"id":"contradiction-1-73","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"旧中国变为新中国，还包含着国内旧的封建势力和新的人民势力之间的情况的变化。旧的封建地主阶级将被打倒，由统治者变为被统治者，这个阶级也就会要逐步归于消灭。人民则将在无产阶级领导之下，由被统治者变为统治者。这时，中国社会的性质就会起变化，由旧的半殖民地和半封建的社会变为新的民主的社会。","language":"中文","translation":false},{"id":"contradiction-1-74","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"这种互相转化的事情，过去已有经验。统治中国将近三百年的清朝帝国，曾在辛亥革命时期被打倒；而孙中山领导的革命同盟会，则曾经一度取得了胜利。在一九二四年至一九二七年的革命战争中，共产党和国民党联合的南方革命势力，曾经由弱小的力量变得强大起来，取得了北伐的胜利；而称雄一时的北洋军阀则被打倒了。一九二七年，共产党领导的人民力量，受了国民党反动势力的打击，变得很小了；但因肃清了自己内部的机会主义，就又逐步地壮大起来。在共产党领导的革命根据地内，农民由被统治者转化为统治者，地主则作了相反的转化。世界上总是这样以新的代替旧的，总是这样新陈代谢、除旧布新或推陈出新的。","language":"中文","translation":false},{"id":"contradiction-1-75","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"革命斗争中的某些时候，困难条件超过顺利条件，在这种时候，困难是矛盾的主要方面，顺利是其次要方面。然而由于革命党人的努力，能够逐步地克服困难，开展顺利的新局面，困难的局面让位于顺利的局面。一九二七年中国革命失败后的情形，中国红军在长征[24]中的情形，都是如此。现在的中日战争，中国又处在困难地位，但是我们能够改变这种情况，使中日双方的情况发生根本的变化。在相反的情形之下，顺利也能转化为困难，如果是革命党人犯了错误的话。一九二四年至一九二七年的革命的胜利，变为失败了。一九二七年以后在南方各省发展起来的革命根据地，至一九三四年都失败了。","language":"中文","translation":false},{"id":"contradiction-1-76","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"研究学问的时候，由不知到知的矛盾也是如此。当着我们刚才开始研究马克思主义的时候，对于马克思主义的无知或知之不多的情况，和马克思主义的知识之间，互相矛盾着。然而由于努力学习，可以由无知转化为有知，由知之不多转化为知之甚多，由对于马克思主义的盲目性改变为能够自由运用马克思主义。","language":"中文","translation":false},{"id":"contradiction-1-77","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"有人觉得有些矛盾并不是这样。例如，生产力和生产关系的矛盾，生产力是主要的；理论和实践的矛盾，实践是主要的；经济基础和上层建筑的矛盾，经济基础是主要的：它们的地位并不互相转化。这是机械唯物论的见解，不是辩证唯物论的见解。诚然，生产力、实践、经济基础，一般地表现为主要的决定的作用，谁不承认这一点，谁就不是唯物论者。然而，生产关系、理论、上层建筑这些方面，在一定条件之下，又转过来表现其为主要的决定的作用，这也是必须承认的。当着不变更生产关系，生产力就不能发展的时候，生产关系的变更就起了主要的决定的作用。当着如同列宁所说“没有革命的理论，就不会有革命的运动”[25]的时候，革命理论的创立和提倡就起了主要的决定的作用。当着某一件事情（任何事情都是一样）要做，但是还没有方针、方法、计划或政策的时候，确定方针、方法、计划或政策，也就是主要的决定的东西。当着政治文化等等上层建筑阻碍着经济基础的发展的时候，对于政治上和文化上的革新就成为主要的决定的东西了。我们这样说，是否违反了唯物论呢？没有。因为我们承认总的历史发展中是物质的东西决定精神的东西，是社会的存在决定社会的意识；但是同时又承认而且必须承认精神的东西的反作用，社会意识对于社会存在的反作用，上层建筑对于经济基础的反作用。这不是违反唯物论，正是避免了机械唯物论，坚持了辩证唯物论。","language":"中文","translation":false},{"id":"contradiction-1-78","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在研究矛盾特殊性的问题中，如果不研究过程中主要的矛盾和非主要的矛盾以及矛盾之主要的方面和非主要的方面这两种情形，也就是说不研究这两种矛盾情况的差别性，那就将陷入抽象的研究，不能具体地懂得矛盾的情况，因而也就不能找出解决矛盾的正确的方法。这两种矛盾情况的差别性或特殊性，都是矛盾力量的不平衡性。世界上没有绝对地平衡发展的东西，我们必须反对平衡论，或均衡论。同时，这种具体的矛盾状况，以及矛盾的主要方面和非主要方面在发展过程中的变化，正是表现出新事物代替旧事物的力量。对于矛盾的各种不平衡情况的研究，对于主要的矛盾和非主要的矛盾、主要的矛盾方面和非主要的矛盾方面的研究，成为革命政党正确地决定其政治上和军事上的战略战术方针的重要方法之一，是一切共产党人都应当注意的。","language":"中文","translation":false},{"id":"contradiction-1-79","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"五 矛盾诸方面的同一性和斗争性","language":"中文","translation":false},{"id":"contradiction-1-80","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在懂得了矛盾的普遍性和特殊性的问题之后，我们必须进而研究矛盾诸方面的同一性和斗争性的问题。","language":"中文","translation":false},{"id":"contradiction-1-81","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"同一性、统一性、一致性、互相渗透、互相贯通、互相依赖（或依存）、互相联结或互相合作，这些不同的名词都是一个意思，说的是如下两种情形：第一、事物发展过程中的每一种矛盾的两个方面，各以和它对立着的方面为自己存在的前提，双方共处于一个统一体中；第二、矛盾着的双方，依据一定的条件，各向着其相反的方面转化。这些就是所谓同一性。","language":"中文","translation":false},{"id":"contradiction-1-82","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"列宁说：“辩证法是这样的一种学说：它研究对立怎样能够是同一的，又怎样成为同一的（怎样变成同一的），——在怎样的条件之下它们互相转化，成为同一的，——为什么人的头脑不应当把这些对立看作死的、凝固的东西，而应当看作生动的、有条件的、可变动的、互相转化的东西。”[26]","language":"中文","translation":false},{"id":"contradiction-1-83","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"列宁这段话是什么意思呢？","language":"中文","translation":false},{"id":"contradiction-1-84","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"一切过程中矛盾着的各方面，本来是互相排斥、互相斗争、互相对立的。世界上一切事物的过程里和人们的思想里，都包含着这样带矛盾性的方面，无一例外。单纯的过程只有一对矛盾，复杂的过程则有一对以上的矛盾。各对矛盾之间，又互相成为矛盾。这样地组成客观世界的一切事物和人们的思想，并推使它们发生运动。","language":"中文","translation":false},{"id":"contradiction-1-85","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"如此说来，只是极不同一，极不统一，怎样又说是同一或统一呢？","language":"中文","translation":false},{"id":"contradiction-1-86","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"原来矛盾着的各方面，不能孤立地存在。假如没有和它作对的矛盾的一方，它自己这一方就失去了存在的条件。试想一切矛盾着的事物或人们心中矛盾着的概念，任何一方面能够独立地存在吗？没有生，死就不见；没有死，生也不见。没有上，无所谓下；没有下，也无所谓上。没有祸，无所谓福；没有福，也无所谓祸。没有顺利，无所谓困难；没有困难，也无所谓顺利。没有地主，就没有佃农；没有佃农，也就没有地主。没有资产阶级，就没有无产阶级；没有无产阶级，也就没有资产阶级。没有帝国主义的民族压迫，就没有殖民地和半殖民地；没有殖民地和半殖民地，也就没有帝国主义的民族压迫。一切对立的成分都是这样，因一定的条件，一面互相对立，一面又互相联结、互相贯通、互相渗透、互相依赖，这种性质，叫做同一性。一切矛盾着的方面都因一定条件具备着不同一性，所以称为矛盾。然而又具备着同一性，所以互相联结。列宁所谓辩证法研究“对立怎样能够是同一的”，就是说的这种情形。怎样能够呢？因为互为存在的条件。这是同一性的第一种意义。","language":"中文","translation":false},{"id":"contradiction-1-87","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"然而单说了矛盾双方互为存在的条件，双方之间有同一性，因而能够共处于一个统一体中，这样就够了吗？还不够。事情不是矛盾双方互相依存就完了，更重要的，还在于矛盾着的事物的互相转化。这就是说，事物内部矛盾着的两方面，因为一定的条件而各向着和自己相反的方面转化了去，向着它的对立方面所处的地位转化了去。这就是矛盾的同一性的第二种意义。","language":"中文","translation":false},{"id":"contradiction-1-88","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"为什么这里也有同一性呢？你们看，被统治的无产阶级经过革命转化为统治者，原来是统治者的资产阶级却转化为被统治者，转化到对方原来所占的地位。苏联已经是这样做了，全世界也将要这样做。试问其间没有在一定条件之下的联系和同一性，如何能够发生这样的变化呢？","language":"中文","translation":false},{"id":"contradiction-1-89","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"曾在中国近代历史的一定阶段上起过某种积极作用的国民党，因为它的固有的阶级性和帝国主义的引诱（这些就是条件），在一九二七年以后转化为反革命，又由于中日矛盾的尖锐化和共产党的统一战线政策（这些就是条件），而被迫着赞成抗日。矛盾着的东西这一个变到那一个，其间包含了一定的同一性。","language":"中文","translation":false},{"id":"contradiction-1-90","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"我们实行过的土地革命，已经是并且还将是这样的过程，拥有土地的地主阶级转化为失掉土地的阶级，而曾经是失掉土地的农民却转化为取得土地的小私有者。有无、得失之间，因一定条件而互相联结，二者具有同一性。在社会主义条件之下，农民的私有制又将转化为社会主义农业的公有制，苏联已经这样做了，全世界将来也会这样做。私产和公产之间有一条由此达彼的桥梁，哲学上名之曰同一性，或互相转化、互相渗透。","language":"中文","translation":false},{"id":"contradiction-1-91","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"巩固无产阶级的专政或人民的专政，正是准备着取消这种专政，走到消灭任何国家制度的更高阶段去的条件。建立和发展共产党，正是准备着消灭共产党和一切政党制度的条件。建立共产党领导的革命军，进行革命战争，正是准备着永远消灭战争的条件。这许多相反的东西，同时却是相成的东西。","language":"中文","translation":false},{"id":"contradiction-1-92","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"大家知道，战争与和平是互相转化的。战争转化为和平，例如第一次世界大战转化为战后的和平，中国的内战现在也停止了，出现了国内的和平。和平转化为战争，例如一九二七年的国共合作转化为战争，现在的世界和平局面也可能转化为第二次世界大战。为什么是这样？因为在阶级社会中战争与和平这样矛盾着的事物，在一定条件下具备着同一性。","language":"中文","translation":false},{"id":"contradiction-1-93","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"一切矛盾着的东西，互相联系着，不但在一定条件之下共处于一个统一体中，而且在一定条件之下互相转化，这就是矛盾的同一性的全部意义。列宁所谓“怎样成为同一的（怎样变成同一的），——在怎样的条件之下它们互相转化，成为同一的”，就是这个意思。","language":"中文","translation":false},{"id":"contradiction-1-94","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"“为什么人的头脑不应当把这些对立看作死的、凝固的东西，而应当看作生动的、有条件的、可变动的、互相转化的东西”呢？因为客观事物本来是如此的。客观事物中矛盾着的诸方面的统一或同一性，本来不是死的、凝固的，而是生动的、有条件的、可变动的、暂时的、相对的东西，一切矛盾都依一定条件向它们的反面转化着。这种情况，反映在人们的思想里，就成了马克思主义的唯物辩证法的宇宙观。只有现在的和历史上的反动的统治阶级以及为他们服务的形而上学，不是把对立的事物当作生动的、有条件的、可变动的、互相转化的东西去看，而是当作死的、凝固的东西去看，并且把这种错误的看法到处宣传，迷惑人民群众，以达其继续统治的目的。共产党人的任务就在于揭露反动派和形而上学的错误思想，宣传事物的本来的辩证法，促成事物的转化，达到革命的目的。","language":"中文","translation":false},{"id":"contradiction-1-95","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"所谓矛盾在一定条件下的同一性，就是说，我们所说的矛盾乃是现实的矛盾，具体的矛盾，而矛盾的互相转化也是现实的、具体的。神话中的许多变化，例如《山海经》中所说的“夸父追日”[27]，《淮南子》中所说的“羿射九日”[28]，《西游记》中所说的孙悟空七十二变[29]和《聊斋志异》[30]中的许多鬼狐变人的故事等等，这种神话中所说的矛盾的互相变化，乃是无数复杂的现实矛盾的互相变化对于人们所引起的一种幼稚的、想象的、主观幻想的变化，并不是具体的矛盾所表现出来的具体的变化。马克思说：“任何神话都是用想象和借助想象以征服自然力，支配自然力，把自然力加以形象化；因而，随着这些自然力之实际上被支配，神话也就消失了。”[31]这种神话中的（还有童话中的）千变万化的故事，虽然因为它们想象出人们征服自然力等等，而能够吸引人们的喜欢，并且最好的神话具有“永久的魅力”[32]（马克思），但神话并不是根据具体的矛盾之一定的条件而构成的，所以它们并不是现实之科学的反映。这就是说，神话或童话中矛盾构成的诸方面，并不是具体的同一性，只是幻想的同一性。科学地反映现实变化的同一性的，就是马克思主义的辩证法。","language":"中文","translation":false},{"id":"contradiction-1-96","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"为什么鸡蛋能够转化为鸡子，而石头不能够转化为鸡子呢？为什么战争与和平有同一性，而战争与石头却没有同一性呢？为什么人能生人不能生出其它的东西呢？没有别的，就是因为矛盾的同一性要在一定的必要的条件之下。缺乏一定的必要的条件，就没有任何的同一性。","language":"中文","translation":false},{"id":"contradiction-1-97","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"为什么俄国在一九一七年二月的资产阶级民主革命和同年十月的无产阶级社会主义革命直接地联系着，而法国资产阶级革命没有直接地联系于社会主义的革命，一八七一年的巴黎公社终于失败了呢？为什么蒙古和中亚细亚的游牧制度又直接地和社会主义联系了呢？为什么中国的革命可以避免资本主义的前途，可以和社会主义直接联系起来，不要再走西方国家的历史老路，不要经过一个资产阶级专政的时期呢？没有别的，都是由于当时的具体条件。一定的必要的条件具备了，事物发展的过程就发生一定的矛盾，而且这种或这些矛盾互相依存，又互相转化，否则，一切都不可能。","language":"中文","translation":false},{"id":"contradiction-1-98","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"同一性的问题如此。那末，什么是斗争性呢？同一性和斗争性的关系是怎样的呢？","language":"中文","translation":false},{"id":"contradiction-1-99","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"列宁说：“对立的统一（一致、同一、合一），是有条件的、一时的、暂存的、相对的。互相排斥的对立的斗争则是绝对的，正如发展、运动是绝对的一样。”[33]","language":"中文","translation":false},{"id":"contradiction-1-100","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"列宁这段话是什么意思呢？","language":"中文","translation":false},{"id":"contradiction-1-101","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"一切过程都有始有终，一切过程都转化为它们的对立物。一切过程的常住性是相对的，但是一种过程转化为他种过程的这种变动性则是绝对的。","language":"中文","translation":false},{"id":"contradiction-1-102","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"无论什么事物的运动都采取两种状态，相对地静止的状态和显着地变动的状态。两种状态的运动都是由事物内部包含的两个矛盾着的因素互相斗争所引起的。当着事物的运动在第一种状态的时候，它只有数量的变化，没有性质的变化，所以显出好似静止的面貌。当着事物的运动在第二种状态的时候，它已由第一种状态中的数量的变化达到了某一个最高点，引起了统一物的分解，发生了性质的变化，所以显出显着地变化的面貌。我们在日常生活中所看见的统一、团结、联合、调和、均势、相持、僵局、静止、有常、平衡、凝聚、吸引等等，都是事物处在量变状态中所显现的面貌。而统一物的分解，团结、联合、调和、均势、相持、僵局、静止、有常、平衡、凝聚、吸引等等状态的破坏，变到相反的状态，便都是事物在质变状态中、在一种过程过渡到他种过程的变化中所显现的面貌。事物总是不断地由第一种状态转化为第二种状态，而矛盾的斗争则存在于两种状态中，并经过第二种状态而达到矛盾的解决。所以说，对立的统一是有条件的、暂时的、相对的，而对立的互相排除的斗争则是绝对的。","language":"中文","translation":false},{"id":"contradiction-1-103","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"前面我们曾经说，两个相反的东西中间有同一性，所以二者能够共处于一个统一体中，又能够互相转化，这是说的条件性，即是说在一定条件之下，矛盾的东西能够统一起来，又能够互相转化；无此一定条件，就不能成为矛盾，不能共居，也不能转化。由于一定的条件才构成了矛盾的同一性，所以说同一性是有条件的、相对的。这里我们又说，矛盾的斗争贯串于过程的始终，并使一过程向着他过程转化，矛盾的斗争无所不在，所以说矛盾的斗争性是无条件的、绝对的。","language":"中文","translation":false},{"id":"contradiction-1-104","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"有条件的相对的同一性和无条件的绝对的斗争性相结合，构成了一切事物的矛盾运动。","language":"中文","translation":false},{"id":"contradiction-1-105","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"我们中国人常说：“相反相成。”[34]就是说相反的东西有同一性。这句话是辩证法的，是违反形而上学的。“相反”就是说两个矛盾方面的互相排斥，或互相斗争。“相成”就是说在一定条件之下两个矛盾方面互相联结起来，获得了同一性。而斗争性即寓于同一性之中，没有斗争性就没有同一性。","language":"中文","translation":false},{"id":"contradiction-1-106","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在同一性中存在着斗争性，在特殊性中存在着普遍性，在个性中存在着共性。拿列宁的话来说，叫做“在相对的东西里面有着绝对的东西”[35]。","language":"中文","translation":false},{"id":"contradiction-1-107","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在矛盾的斗争性的问题中，包含着对抗是什么的问题。我们回答道：对抗是矛盾斗争的一种形式，而不是矛盾斗争的一切形式。","language":"中文","translation":false},{"id":"contradiction-1-108","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"在人类历史中，存在着阶级的对抗，这是矛盾斗争的一种特殊的表现。剥削阶级和被剥削阶级之间的矛盾，无论在奴隶社会也好，封建社会也好，资本主义社会也好，互相矛盾着的两阶级，长期地并存于一个社会中，它们互相斗争着，但要待两阶级的矛盾发展到了一定的阶段的时候，双方才取外部对抗的形式，发展为革命。阶级社会中，由和平向战争的转化，也是如此。","language":"中文","translation":false},{"id":"contradiction-1-109","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"炸弹在未爆炸的时候，是矛盾物因一定条件共居于一个统一体中的时候。待至新的条件（发火）出现，才发生了爆炸。自然界中一切到了最后要采取外部冲突形式去解决旧矛盾产生新事物的现象，都有与此相仿佛的情形。","language":"中文","translation":false},{"id":"contradiction-1-110","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"认识这种情形，极为重要。它使我们懂得，在阶级社会中，革命和革命战争是不可避免的，舍此不能完成社会发展的飞跃，不能推翻反动的统治阶级，而使人民获得政权。共产党人必须揭露反动派所谓社会革命是不必要的和不可能的等等欺骗的宣传，坚持马克思列宁主义的社会革命论，使人民懂得，这不但是完全必要的，而且是完全可能的，整个人类的历史和苏联的胜利，都证明了这个科学的真理。","language":"中文","translation":false},{"id":"contradiction-1-111","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"但是我们必须具体地研究各种矛盾斗争的情况，不应当将上面所说的公式不适当地套在一切事物的身上。矛盾和斗争是普遍的、绝对的，但是解决矛盾的方法，即斗争的形式，则因矛盾的性质不同而不相同。有些矛盾具有公开的对抗性，有些矛盾则不是这样。根据事物的具体发展，有些矛盾是由原来还非对抗性的，而发展成为对抗性的；也有些矛盾则由原来是对抗性的，而发展成为非对抗性的。","language":"中文","translation":false},{"id":"contradiction-1-112","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"共产党内正确思想和错误思想的矛盾，如前所说，在阶级存在的时候，这是阶级矛盾对于党内的反映。这种矛盾，在开始的时候，或在个别的问题上，并不一定马上表现为对抗性的。但随着阶级斗争的发展，这种矛盾也就可能发展为对抗性的。苏联共产党的历史告诉我们：列宁、斯大林的正确思想和托洛茨基、布哈林等人的错误思想的矛盾，在开始的时候还没有表现为对抗的形式，但随后就发展为对抗的了。中国共产党的历史也有过这样的情形。我们党内许多同志的正确思想和陈独秀、张国焘[36]等人的错误思想的矛盾，在开始的时候也没有表现为对抗的形式，但随后就发展为对抗的了。目前我们党内的正确思想和错误思想的矛盾，没有表现为对抗的形式，如果犯错误的同志能够改正自己的错误，那就不会发展为对抗性的东西。因此，党一方面必须对于错误思想进行严肃的斗争，另方面又必须充分地给犯错误的同志留有自己觉悟的机会。在这样的情况下，过火的斗争，显然是不适当的。但如果犯错误的人坚持错误，并扩大下去，这种矛盾也就存在着发展为对抗性的东西的可能性。","language":"中文","translation":false},{"id":"contradiction-1-113","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"经济上城市和乡村的矛盾，在资本主义社会里面（那里资产阶级统治的城市残酷地掠夺乡村），在中国的国民党统治区域里面（那里外国帝国主义和本国买办大资产阶级所统治的城市极野蛮地掠夺乡村），那是极其对抗的矛盾。但在社会主义国家里面，在我们的革命根据地里面，这种对抗的矛盾就变为非对抗的矛盾，而当到达共产主义社会的时候，这种矛盾就会消灭。","language":"中文","translation":false},{"id":"contradiction-1-114","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"列宁说：“对抗和矛盾断然不同。在社会主义下，对抗消灭了，矛盾存在着。”[37]这就是说，对抗只是矛盾斗争的一种形式，而不是它的一切形式，不能到处套用这个公式。","language":"中文","translation":false},{"id":"contradiction-1-115","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"说到这里，我们可以总起来说几句。事物矛盾的法则，即对立统一的法则，是自然和社会的根本法则，因而也是思维的根本法则。它是和形而上学的宇宙观相反的。它对于人类的认识史是一个大革命。按照辩证唯物论的观点看来，矛盾存在于一切客观事物和主观思维的过程中，矛盾贯串于一切过程的始终，这是矛盾的普遍性和绝对性。矛盾着的事物及其每一个侧面各有其特点，这是矛盾的特殊性和相对性。矛盾着的事物依一定的条件有同一性，因此能够共居于一个统一体中，又能够互相转化到相反的方面去，这又是矛盾的特殊性和相对性。然而矛盾的斗争则是不断的，不管在它们共居的时候，或者在它们互相转化的时候，都有斗争的存在，尤其是在它们互相转化的时候，斗争的表现更为显着，这又是矛盾的普遍性和绝对性。当着我们研究矛盾的特殊性和相对性的时候，要注意矛盾和矛盾方面的主要的和非主要的区别；当着我们研究矛盾的普遍性和斗争性的时候，要注意矛盾的各种不同的斗争形式的区别。否则就要犯错误。如果我们经过研究真正懂得了上述这些要点，我们就能够击破违反马克思列宁主义基本原则的不利于我们的革命事业的那些教条主义的思想；也能够使有经验的同志们整理自己的经验，使之带上原则性，而避免重复经验主义的错误。这些，就是我们研究矛盾法则的一些简单的结论。","language":"中文","translation":false},{"id":"contradiction-1-116","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[1] 见列宁《黑格尔〈哲学史讲演录〉一书摘要》（《列宁全集》第55卷，人民出版社1990年版，第213页）。","language":"中文","translation":false},{"id":"contradiction-1-117","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[2] 参见列宁《谈谈辩证法问题》：“统一物之分为两个部分以及对它的矛盾着的部分的认识……，是辩证法的实质（是辩证法的‘本质’之一，是它的基本的特点或特征之一，甚至可说是它的最基本的特点或特征）。”并参见《黑格尔〈逻辑学〉一书摘要》中关于“辩证法的要素”部分：“可以把辩证法简要地规定为关于对立面的统一的学说。这样就会抓住辩证法的核心，可是这需要说明和发挥。”（《列宁全集》第55卷，人民出版社1990年版，第305、192页）","language":"中文","translation":false},{"id":"contradiction-1-118","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[3] 德波林（一八八一——一九六三），苏联哲学家。一九二九年当选为苏联科学院院士。三十年代初，苏联哲学界发动对德波林学派的批判，认为他们犯了理论脱离实践、哲学脱离政治等唯心主义性质的错误。","language":"中文","translation":false},{"id":"contradiction-1-119","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[4] 见列宁《谈谈辩证法问题》。新的译文是：“有两种基本的（或两种可能的？或两种在历史上常见的？）发展（进化）观点：认为发展是减少和增加，是重复；以及认为发展是对立面的统一（统一物之分为两个互相排斥的对立面以及它们之间的相互关系）。”（《列宁全集》第55卷，人民出版社1990年版，第306页）","language":"中文","translation":false},{"id":"contradiction-1-120","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[5] 见《汉书•董仲舒传》。董仲舒（公元前一七九——前一○四）是孔子学派在西汉的主要代表，他曾经对汉武帝说：“道之大原出于天，天不变，道亦不变。”“道”是中国古代哲学家的通用语，它的意义是“道路”或“道理”，可作“法则”或“规律”解说。","language":"中文","translation":false},{"id":"contradiction-1-121","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[6] 见恩格斯《反杜林论》第一编第十二节《辩证法。量和质》（《马克思恩格斯选集》第3卷，人民出版社1972年版，第160页）。","language":"中文","translation":false},{"id":"contradiction-1-122","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[7] 见列宁《谈谈辩证法问题》。新的译文是：“承认（发现）自然界的（也包括精神的和社会的）一切现象和过程具有矛盾着的、相互排斥的、对立的倾向。”（《列宁全集》第55卷，人民出版社1990年版，第306页）","language":"中文","translation":false},{"id":"contradiction-1-123","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[8] 以上所引恩格斯的三段话，均见恩格斯《反杜林论》第一编第十二节《辩证法。量和质》。其中第二段“高等数学的主要基础之一，就是矛盾……”，《反杜林论》中的原文是：“我们已经提到，高等数学的主要基础之一是这样一个矛盾：在一定条件下直线和曲线应当是一回事。高等数学还有另一个矛盾：在我们眼前相交的线，只要离开交点五六厘米，就应当认为是平行的、即使无限延长也不会相交的线。可是，高等数学利用这些和其它一些更加尖锐的矛盾获得了不仅是正确的、而且是初等数学所完全不能达到的成果。”（《马克思恩格斯选集》第3卷，人民出版社1972年版，第160—161页）","language":"中文","translation":false},{"id":"contradiction-1-124","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[9] 见列宁《谈谈辩证法问题》（《列宁全集》第55卷，人民出版社1990年版，第305—306页）。","language":"中文","translation":false},{"id":"contradiction-1-125","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[10] 见列宁《谈谈辩证法问题》（《列宁全集》第55卷，人民出版社1990年版，第307页）。","language":"中文","translation":false},{"id":"contradiction-1-126","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[11] 参见本卷《中国革命战争的战略问题》注〔11〕。","language":"中文","translation":false},{"id":"contradiction-1-127","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[12] 见《孙子•谋攻》。","language":"中文","translation":false},{"id":"contradiction-1-128","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[13] 魏征（五八○——六四三），唐代初期的政治活动家和历史学家。本文引语见《资治通鉴》卷一百九十二。","language":"中文","translation":false},{"id":"contradiction-1-129","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[14] 《水浒传》是中国描写农民战争的著名小说。宋江是这部小说中农民武装的主要领袖。祝家庄在农民武装根据地梁山泊的附近，这个庄的统治者祝朝奉，是一个大恶霸地主。","language":"中文","translation":false},{"id":"contradiction-1-130","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[15] 木马计是希腊神话中的一个著名故事。据传说，古希腊人攻打特洛伊城，很久打不下来。后来，他们伪装撤退，在城下营房中留下了一匹腹内藏有一批勇士的大木马。特洛伊人不知道这是敌人的计策，把木马作为战利品拉进城去。深夜，勇士们走出木马，利用特洛伊人毫无戒备的时机，配合城外的军队，迅速地夺取了特洛伊城。","language":"中文","translation":false},{"id":"contradiction-1-131","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[16] 见列宁《再论工会、目前局势及托洛茨基同志和布哈林同志的错误》。新的译文是：“要真正地认识事物，就必须把握住、研究清楚它的一切方面、一切联系和‘中介’。我们永远也不会完全做到这一点，但是，全面性这一要求可以使我们防止犯错误和防止僵化。”（《列宁全集》第40卷，人民出版社1986年版，第291页）","language":"中文","translation":false},{"id":"contradiction-1-132","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[17] 见本卷《湖南农民运动考察报告》注〔3〕。","language":"中文","translation":false},{"id":"contradiction-1-133","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[18] 见本卷《论反对日本帝国主义的策略》注〔5〕。","language":"中文","translation":false},{"id":"contradiction-1-134","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[19] 参见本卷《关于蒋介石声明的声明》注〔1〕。","language":"中文","translation":false},{"id":"contradiction-1-135","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[20] 见本卷《中国革命战争的战略问题》注〔4〕。","language":"中文","translation":false},{"id":"contradiction-1-136","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[21] 见本卷《论反对日本帝国主义的策略》注〔35〕。","language":"中文","translation":false},{"id":"contradiction-1-137","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[22] 一八九四年（甲午年）发生的中日战争，也称甲午战争。这次战争是日本军国主义者蓄意挑起的。日本军队先向朝鲜发动侵略并对中国的陆海军进行挑衅，继即大举侵入中国的东北。在战争中，中国军队曾经英勇作战，但是由于清朝政府的腐败以及缺乏坚决反对侵略的准备，中国方面遭到了失败。一八九五年，清朝政府和日本订立了可耻的马关条约，这个条约的主要内容是：中国割让台湾全岛及所有附属各岛屿、澎湖列岛和辽东半岛（后来在俄、德、法三国干涉下，日本同意由清政府偿付白银三千万两“赎还”该半岛），赔偿军费银二万万两，允许日本人在中国通商口岸开设工厂，开辟沙市、重庆、苏州、杭州等地为商埠。","language":"中文","translation":false},{"id":"contradiction-1-138","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[23] 见本卷《论反对日本帝国主义的策略》注〔37〕。","language":"中文","translation":false},{"id":"contradiction-1-139","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[24] 参见本卷《论反对日本帝国主义的策略》注〔22〕。","language":"中文","translation":false},{"id":"contradiction-1-140","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[25] 见列宁《俄国社会民主党人的任务》（《列宁全集》第2卷，人民出版社1984年版，第443页）；并见列宁《怎么办？》第一章第四节（《列宁全集》第6卷，人民出版社1986年版，第23页）。","language":"中文","translation":false},{"id":"contradiction-1-141","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[26] 见列宁《黑格尔〈逻辑学〉一书摘要》。新的译文是：“辩证法是一种学说，它研究对立面怎样才能够同一，是怎样（怎样成为）同一的——在什么条件下它们是相互转化而同一的，——为什么人的头脑不应该把这些对立面看作僵死的、凝固的东西，而应该看作活生生的、有条件的、活动的、彼此转化的东西。”（《列宁全集》第55卷，人民出版社1990年版，第90页）","language":"中文","translation":false},{"id":"contradiction-1-142","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[27] 《山海经》是一部中国古代地理著作，其中记载了不少远古的神话传说。夸父是《山海经•海外北经》上记载的一个神人。据说：“夸父与日逐走。入日，渴欲得饮，饮于河渭。河渭不足，北饮大泽。未至，道渴而死。弃其杖，化为邓林。”","language":"中文","translation":false},{"id":"contradiction-1-143","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[28] 羿是中国古代传说中的英雄，“射日”是关于他善射的著名故事。据西汉淮南王刘安（公元前二世纪人）及其门客所著《淮南子》一书说：“尧之时，十日并出，焦禾稼，杀草木，而民无所食。猰豸、凿齿、九婴、大风、封狶、修蛇，皆为民害。尧乃使羿……上射十日而下杀猰豸。……万民皆喜。”东汉著作家王逸（公元二世纪人）关于屈原诗篇《天问》的注释说：“淮南言，尧时十日并出，草木焦枯。尧命羿仰射十日，中其九日……留其一日。”","language":"中文","translation":false},{"id":"contradiction-1-144","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[29] 《西游记》是明代作家吴承恩着的一部神话小说。孙悟空是书中的主角。他是一个神猴，有七十二变的法术，能够随意变成各式各样的鸟兽虫鱼草木器物或者人形。","language":"中文","translation":false},{"id":"contradiction-1-145","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[30] 《聊斋志异》是清代文学家蒲松龄着的短篇小说集，大部分是叙述神仙狐鬼的故事。","language":"中文","translation":false},{"id":"contradiction-1-146","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[31] 见马克思《〈政治经济学批判〉导言》（《马克思恩格斯选集》第2卷，人民出版社1972年版，第113页）。","language":"中文","translation":false},{"id":"contradiction-1-147","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[32] 见马克思《〈政治经济学批判〉导言》（《马克思恩格斯选集》第2卷，人民出版社1972年版，第114页）。","language":"中文","translation":false},{"id":"contradiction-1-148","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[33] 见列宁《谈谈辩证法问题》。新的译文是：“对立面的统一（一致、同一、均势）是有条件的、暂时的、易逝的、相对的。相互排斥的对立面的斗争是绝对的，正如发展、运动是绝对的一样。”（《列宁全集》第55卷，人民出版社1990年版，第306页）","language":"中文","translation":false},{"id":"contradiction-1-149","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[34] 见东汉著名史学家班固（三二——九二）所著《汉书•艺文志》，原文是：“诸子十家，其可观者，九家而已。皆起于王道既微，诸侯力政，时君世主，好恶殊方。是以九家之术，蜂出并作，各引一端，崇其所善，以此驰说，取合诸侯。其言虽殊，辟犹水火，相灭亦相生也。仁之与义，敬之与和，相反而皆相成也。”","language":"中文","translation":false},{"id":"contradiction-1-150","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[35] 见列宁《谈谈辩证法问题》。新的译文是：“相对中有绝对。”（《列宁全集》第55卷，人民出版社1990年版，第307页）","language":"中文","translation":false},{"id":"contradiction-1-151","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[36] 见本卷《论反对日本帝国主义的策略》注〔24〕。","language":"中文","translation":false},{"id":"contradiction-1-152","author":"毛泽东","title":"矛盾论","location":"矛盾论（一九三七年八月）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193708.htm","text":"[37] 见列宁《在尼•布哈林〈过渡时期经济学〉一书上作的批注和评论》（《列宁全集》第60卷，人民出版社1990年版，第282页）。","language":"中文","translation":false},{"id":"protracted-war-1-1","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"中文马克思主义文库 -> 毛泽东","language":"中文","translation":false},{"id":"protracted-war-1-2","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"* 这是毛泽东一九三八年五月二十六日至六月三日在延安抗日战争研究会的讲演。","language":"中文","translation":false},{"id":"protracted-war-1-3","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一）伟大抗日战争的一周年纪念，七月七日，快要到了。全民族的力量团结起来，坚持抗战，坚持统一战线，同敌人作英勇的战争，快一年了。这个战争，在东方历史上是空前的，在世界历史上也将是伟大的，全世界人民都关心这个战争。身受战争灾难、为着自己民族的生存而奋斗的每一个中国人，无日不在渴望战争的胜利。然而战争的过程究竟会要怎么样？能胜利还是不能胜利？能速胜还是不能速胜？很多人都说持久战，但是为什么是持久战？怎样进行持久战？很多人都说最后胜利，但是为什么会有最后胜利？怎样争取最后胜利？这些问题，不是每个人都解决了的，甚至是大多数人至今没有解决的。于是失败主义的亡国论者跑出来向人们说：中国会亡，最后胜利不是中国的。某些性急的朋友们也跑出来向人们说：中国很快就能战胜，无需乎费大气力。这些议论究竟对不对呢？我们一向都说：这些议论是不对的。可是我们说的，还没有为大多数人所了解。一半因为我们的宣传解释工作还不够，一半也因为客观事变的发展还没有完全暴露其固有的性质，还没有将其面貌鲜明地摆在人们之前，使人们无从看出其整个的趋势和前途，因而无从决定自己的整套的方针和做法。现在好了，抗战十个月的经验，尽够击破毫无根据的亡国论，也尽够说服急性朋友们的速胜论了。在这种情形下，很多人要求做个总结性的解释。尤其是对持久战，有亡国论和速胜论的反对意见，也有空洞无物的了解。“卢沟桥事变[1]以来，四万万人一齐努力，最后胜利是中国的。”这样一种公式，在广大的人们中流行着。这个公式是对的，但有加以充实的必要。抗日战争和统一战线之所以能够坚持，是由于许多的因素：全国党派，从共产党到国民党；全国人民，从工人农民到资产阶级；全国军队，从主力军到游击队；国际方面，从社会主义国家到各国爱好正义的人民；敌国方面，从某些国内反战的人民到前线反战的兵士。总而言之，所有这些因素，在我们的抗战中都尽了他们各种程度的努力。每一个有良心的人，都应向他们表示敬意。我们共产党人，同其它抗战党派和全国人民一道，唯一的方向，是努力团结一切力量，战胜万恶的日寇。今年七月一日，是中国共产党建立的十七周年纪念日。为了使每个共产党员在抗日战争中能够尽其更好和更大的努力，也有着重地研究持久战的必要。因此，我的讲演就来研究持久战。和持久战这个题目有关的问题，我都准备说到；但是不能一切都说到，因为一切的东西，不是在一个讲演中完全说得了的。","language":"中文","translation":false},{"id":"protracted-war-1-4","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二）抗战十个月以来，一切经验都证明下述两种观点的不对：一种是中国必亡论，一种是中国速胜论。前者产生妥协倾向，后者产生轻敌倾向。他们看问题的方法都是主观的和片面的，一句话，非科学的。","language":"中文","translation":false},{"id":"protracted-war-1-5","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三）抗战以前，存在着许多亡国论的议论。例如说：“中国武器不如人，战必败。”“如果抗战，必会作阿比西尼亚[2]。”抗战以后，公开的亡国论没有了，但暗地是有的，而且很多。例如妥协的空气时起时伏，主张妥协者的根据就是“再战必亡”[3]。有个学生从湖南写信来说：“在乡下一切都感到困难。单独一个人作宣传工作，只好随时随地找人谈话。对象都不是无知无识的愚民，他们多少也懂得一点，他们对我的谈话很有兴趣。可是碰了我那几位亲戚，他们总说：‘中国打不胜，会亡。’讨厌极了。好在他们还不去宣传，不然真糟。农民对他们的信仰当然要大些啊！”这类中国必亡论者，是妥协倾向的社会基础。这类人中国各地都有，因此，抗日阵线中随时可能发生的妥协问题，恐怕终战争之局也不会消灭的。当此徐州失守武汉紧张的时候，给这种亡国论痛驳一驳，我想不是无益的。","language":"中文","translation":false},{"id":"protracted-war-1-6","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四）抗战十个月以来，各种表现急性病的意见也发生了。例如在抗战初起时，许多人有一种毫无根据的乐观倾向，他们把日本估计过低，甚至以为日本不能打到山西。有些人轻视抗日战争中游击战争的战略地位，他们对于“在全体上，运动战是主要的，游击战是辅助的；在部分上，游击战是主要的，运动战是辅助的”这个提法，表示怀疑。他们不赞成八路军这样的战略方针：“基本的是游击战，但不放松有利条件下的运动战。”认为这是“机械的”观点[4]。上海战争时，有些人说：“只要打三个月，国际局势一定变化，苏联一定出兵，战争就可解决。”把抗战的前途主要地寄托在外国援助上面[5]。台儿庄胜利[6]之后，有些人主张徐州战役[7]应是“准决战”，说过去的持久战方针应该改变。说什么“这一战，就是敌人的最后挣扎”，“我们胜了，日阀就在精神上失了立场，只有静候末日审判”[8]。平型关一个胜仗，冲昏了一些人的头脑；台儿庄再一个胜仗，冲昏了更多的人的头脑。于是敌人是否进攻武汉，成为疑问了。许多人以为：“不一定”；许多人以为：“断不会”。这样的疑问可以牵涉到一切重大的问题。例如说：抗日力量是否够了呢？回答可以是肯定的，因为现在的力量已使敌人不能再进攻，还要增加力量干什么呢？例如说：巩固和扩大抗日民族统一战线的口号是否依然正确呢？回答可以是否定的，因为统一战线的现时状态已够打退敌人，还要什么巩固和扩大呢？例如说：国际外交和国际宣传工作是否还应该加紧呢？回答也可以是否定的。例如说：改革军队制度，改革政治制度，发展民众运动，厉行国防教育，镇压汉奸托派[9]，发展军事工业，改良人民生活，是否应该认真去做呢？例如说：保卫武汉、保卫广州、保卫西北和猛烈发展敌后游击战争的口号，是否依然正确呢？回答都可以是否定的。甚至某些人在战争形势稍为好转的时候，就准备在国共两党之间加紧磨擦一下，把对外的眼光转到对内。这种情况，差不多每一个较大的胜仗之后，或敌人进攻暂时停顿之时，都要发生。所有上述一切，我们叫它做政治上军事上的近视眼。这些话，讲起来好像有道理，实际上是毫无根据、似是而非的空谈。扫除这些空谈，对于进行胜利的抗日战争，应该是有好处的。","language":"中文","translation":false},{"id":"protracted-war-1-7","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五）于是问题是：中国会亡吗？答复：不会亡，最后胜利是中国的。中国能够速胜吗？答复：不能速胜，抗日战争是持久战。","language":"中文","translation":false},{"id":"protracted-war-1-8","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六）这些问题的主要论点，还在两年之前我们就一般地指出了。还在一九三六年七月十六日，即在西安事变前五个月，卢沟桥事变前十二个月，我同美国记者斯诺先生的谈话中，就已经一般地估计了中日战争的形势，并提出了争取胜利的各种方针。为备忘计，不妨抄录几段如下：","language":"中文","translation":false},{"id":"protracted-war-1-9","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"问：在什么条件下，中国能战胜并消灭日本帝国主义的实力呢？","language":"中文","translation":false},{"id":"protracted-war-1-10","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"答：要有三个条件：第一是中国抗日统一战线的完成；第二是国际抗日统一战线的完成；第三是日本国内人民和日本殖民地人民的革命运动的兴起。就中国人民的立场来说，三个条件中，中国人民的大联合是主要的。","language":"中文","translation":false},{"id":"protracted-war-1-11","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"问：你想，这个战争要延长多久呢？","language":"中文","translation":false},{"id":"protracted-war-1-12","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"答：要看中国抗日统一战线的实力和中日两国其它许多决定的因素如何而定。即是说，除了主要地看中国自己的力量之外，国际间所给中国的援助和日本国内革命的援助也很有关系。如果中国抗日统一战线有力地发展起来，横的方面和纵的方面都有效地组织起来，如果认清日本帝国主义威胁他们自己利益的各国政府和各国人民能给中国以必要的援助，如果日本的革命起来得快，则这次战争将迅速结束，中国将迅速胜利。如果这些条件不能很快实现，战争就要延长。但结果还是一样，日本必败，中国必胜。只是牺牲会大，要经过一个很痛苦的时期。","language":"中文","translation":false},{"id":"protracted-war-1-13","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"问：从政治上和军事上来看，你以为这个战争的前途会要如何发展？","language":"中文","translation":false},{"id":"protracted-war-1-14","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"答：日本的大陆政策已经确定了，那些以为同日本妥协，再牺牲一些中国的领土主权就能够停止日本进攻的人们，他们的想法只是一种幻想。我们确切地知道，就是扬子江下游和南方各港口，都已经包括在日本帝国主义的大陆政策之内。并且日本还想占领菲律宾、暹罗、越南、马来半岛和荷属东印度，把外国和中国切开，独占西南太平洋。这又是日本的海洋政策。在这样的时期，中国无疑地要处于极端困难的地位。可是大多数中国人相信，这种困难是能够克服的；只有各大商埠的富人是失败论者，因为他们害怕损失财产。有许多人想，一旦中国海岸被日本封锁，中国就不能继续作战。这是废话。为反驳他们，我们不妨举出红军的战争史。在抗日战争中，中国所占的优势，比内战时红军的地位强得多。中国是一个庞大的国家，就是日本能占领中国一万万至二万万人口的区域，我们离战败还很远呢。我们仍然有很大的力量同日本作战，而日本在整个战争中须得时时在其后方作防御战。中国经济的不统一、不平衡，对于抗日战争反为有利。例如将上海和中国其它地方割断，对于中国的损害，绝没有将纽约和美国其它地方割断对于美国的损害那样严重。日本就是把中国沿海封锁，中国的西北、西南和西部，它是无法封锁的。所以问题的中心点还是中国全体人民团结起来，树立举国一致的抗日阵线。这是我们早就提出了的。","language":"中文","translation":false},{"id":"protracted-war-1-15","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"问：假如战争拖得很长，日本没有完全战败，共产党能否同意讲和，并承认日本统治东北？","language":"中文","translation":false},{"id":"protracted-war-1-16","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"答：不能。中国共产党和全国人民一样，不容许日本保留中国的寸土。","language":"中文","translation":false},{"id":"protracted-war-1-17","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"问：照你的意见，这次解放战争，主要的战略方针是什么？","language":"中文","translation":false},{"id":"protracted-war-1-18","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"答：我们的战略方针，应该是使用我们的主力在很长的变动不定的战线上作战。中国军队要胜利，必须在广阔的战场上进行高度的运动战，迅速地前进和迅速地后退，迅速地集中和迅速地分散。这就是大规模的运动战，而不是深沟高垒、层层设防、专靠防御工事的阵地战。这并不是说要放弃一切重要的军事地点，对于这些地点，只要有利，就应配置阵地战。但是转换全局的战略方针，必然要是运动战。阵地战虽也必需，但是属于辅助性质的第二种的方针。在地理上，战场这样广大，我们作最有效的运动战，是可能的。日军遇到我军的猛烈活动，必得谨慎。他们的战争机构很笨重，行动很慢，效力有限。如果我们集中兵力在一个狭小的阵地上作消耗战的抵抗，将使我军失掉地理上和经济组织上的有利条件，犯阿比西尼亚的错误。战争的前期，我们要避免一切大的决战，要先用运动战逐渐地破坏敌人军队的精神和战斗力。","language":"中文","translation":false},{"id":"protracted-war-1-19","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"除了调动有训练的军队进行运动战之外，还要在农民中组织很多的游击队。须知东三省的抗日义勇军，仅仅是表示了全国农民所能动员抗战的潜伏力量的一小部分。中国农民有很大的潜伏力，只要组织和指挥得当，能使日本军队一天忙碌二十四小时，使之疲于奔命。必须记住这个战争是在中国打的，这就是说，日军要完全被敌对的中国人所包围；日军要被迫运来他们所需的军用品，而且要自己看守；他们要用重兵去保护交通线，时时谨防袭击；另外，还要有一大部力量驻扎满洲和日本内地。","language":"中文","translation":false},{"id":"protracted-war-1-20","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"在战争的过程中，中国能俘虏许多的日本兵，夺取许多的武器弹药来武装自己；同时，争取外国的援助，使中国军队的装备逐渐加强起来。因此，中国能够在战争的后期从事阵地战，对于日本的占领地进行阵地的攻击。这样，日本在中国抗战的长期消耗下，它的经济行将崩溃；在无数战争的消磨中，它的士气行将颓靡。中国方面，则抗战的潜伏力一天一天地奔腾高涨，大批的革命民众不断地倾注到前线去，为自由而战争。所有这些因素和其它的因素配合起来，就使我们能够对日本占领地的堡垒和根据地，作最后的致命的攻击，驱逐日本侵略军出中国。（斯诺：《西北印象记》）","language":"中文","translation":false},{"id":"protracted-war-1-21","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"抗战十个月的经验，证明上述论点的正确，以后也还将继续证明它。","language":"中文","translation":false},{"id":"protracted-war-1-22","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七）还在卢沟桥事变发生后一个多月，即一九三七年八月二十五日，中国共产党中央就在它的《关于目前形势与党的任务的决定》中，清楚地指出：","language":"中文","translation":false},{"id":"protracted-war-1-23","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"卢沟桥的挑战和平津的占领，不过是日寇大举进攻中国本部的开始。日寇已经开始了全国的战时动员。他们的所谓“不求扩大”的宣传，不过是掩护其进攻的烟幕弹。","language":"中文","translation":false},{"id":"protracted-war-1-24","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"七月七日卢沟桥的抗战，已经成了中国全国性抗战的起点。","language":"中文","translation":false},{"id":"protracted-war-1-25","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"中国的政治形势从此开始了一个新阶段，这就是实行抗战的阶段。抗战的准备阶段已经过去了。这一阶段的最中心的任务是：动员一切力量争取抗战的胜利。","language":"中文","translation":false},{"id":"protracted-war-1-26","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"争取抗战胜利的中心关键，在使已经发动的抗战发展为全面的全民族的抗战。只有这种全面的全民族的抗战，才能使抗战得到最后的胜利。","language":"中文","translation":false},{"id":"protracted-war-1-27","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"由于当前的抗战还存在着严重的弱点，所以在今后的抗战过程中，可能发生许多挫败、退却，内部的分化、叛变，暂时和局部的妥协等不利的情况。因此，应该看到这一抗战是艰苦的持久战。但我们相信，已经发动的抗战，必将因为我党和全国人民的努力，冲破一切障碍物而继续地前进和发展。","language":"中文","translation":false},{"id":"protracted-war-1-28","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"抗战十个月的经验，同样证明了上述论点的正确，以后也还将继续证明它。","language":"中文","translation":false},{"id":"protracted-war-1-29","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八）战争问题中的唯心论和机械论的倾向，是一切错误观点的认识论上的根源。他们看问题的方法是主观的和片面的。或者是毫无根据地纯主观地说一顿；或者是只根据问题的一侧面、一时候的表现，也同样主观地把它夸大起来，当作全体看。但是人们的错误观点可分为两类：一类是根本的错误，带一贯性，这是难于纠正的；另一类是偶然的错误，带暂时性，这是易于纠正的。但既同为错误，就都有纠正的必要。因此，反对战争问题中的唯心论和机械论的倾向，采用客观的观点和全面的观点去考察战争，才能使战争问题得出正确的结论。","language":"中文","translation":false},{"id":"protracted-war-1-30","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九）抗日战争为什么是持久战？最后胜利为什么是中国的呢？根据在什么地方呢？","language":"中文","translation":false},{"id":"protracted-war-1-31","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"中日战争不是任何别的战争，乃是半殖民地半封建的中国和帝国主义的日本之间在二十世纪三十年代进行的一个决死的战争。全部问题的根据就在这里。分别地说来，战争的双方有如下互相反对的许多特点。","language":"中文","translation":false},{"id":"protracted-war-1-32","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○）日本方面：第一，它是一个强的帝国主义国家，它的军力、经济力和政治组织力在东方是一等的，在世界也是五六个著名帝国主义国家中的一个。这是日本侵略战争的基本条件，战争的不可避免和中国的不能速胜，就建立在这个日本国家的帝国主义制度及其强的军力、经济力和政治组织力上面。然而第二，由于日本社会经济的帝国主义性，就产生了日本战争的帝国主义性，它的战争是退步的和野蛮的。时至二十世纪三十年代的日本帝国主义，由于内外矛盾，不但使得它不得不举行空前大规模的冒险战争，而且使得它临到最后崩溃的前夜。从社会行程说来，日本已不是兴旺的国家，战争不能达到日本统治阶级所期求的兴旺，而将达到它所期求的反面——日本帝国主义的死亡。这就是所谓日本战争的退步性。跟着这个退步性，加上日本又是一个带军事封建性的帝国主义这一特点，就产生了它的战争的特殊的野蛮性。这样就要最大地激起它国内的阶级对立、日本民族和中国民族的对立、日本和世界大多数国家的对立。日本战争的退步性和野蛮性是日本战争必然失败的主要根据。还不止此，第三，日本战争虽是在其强的军力、经济力和政治组织力的基础之上进行的，但同时又是在其先天不足的基础之上进行的。日本的军力、经济力和政治组织力虽强，但这些力量之量的方面不足。日本国度比较地小，其人力、军力、财力、物力均感缺乏，经不起长期的战争。日本统治者想从战争中解决这个困难问题，但同样，将达到其所期求的反面，这就是说，它为解决这个困难问题而发动战争，结果将因战争而增加困难，战争将连它原有的东西也消耗掉。最后，第四，日本虽能得到国际法西斯国家的援助，但同时，却又不能不遇到一个超过其国际援助力量的国际反对力量。这后一种力量将逐渐地增长，终究不但将把前者的援助力量抵消，并将施其压力于日本自身。这是失道寡助的规律，是从日本战争的本性产生出来的。总起来说，日本的长处是其战争力量之强，而其短处则在其战争本质的退步性、野蛮性，在其人力、物力之不足，在其国际形势之寡助。这些就是日本方面的特点。","language":"中文","translation":false},{"id":"protracted-war-1-33","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一）中国方面：第一，我们是一个半殖民地半封建的国家。从鸦片战争[10]，太平天国[11]，戊戌维新[12]，辛亥革命[13]，直至北伐战争，一切为解除半殖民地半封建地位的革命的或改良的运动，都遭到了严重的挫折，因此依然保留下这个半殖民地半封建的地位。我们依然是一个弱国，我们在军力、经济力和政治组织力各方面都显得不如敌人。战争之不可避免和中国之不能速胜，又在这个方面有其基础。然而第二，中国近百年的解放运动积累到了今日，已经不同于任何历史时期。各种内外反对力量虽给了解放运动以严重挫折，同时却锻炼了中国人民。今日中国的军事、经济、政治、文化虽不如日本之强，但在中国自己比较起来，却有了比任何一个历史时期更为进步的因素。中国共产党及其领导下的军队，就是这种进步因素的代表。中国今天的解放战争，就是在这种进步的基础上得到了持久战和最后胜利的可能性。中国是如日方升的国家，这同日本帝国主义的没落状态恰是相反的对照。中国的战争是进步的，从这种进步性，就产生了中国战争的正义性。因为这个战争是正义的，就能唤起全国的团结，激起敌国人民的同情，争取世界多数国家的援助。第三，中国又是一个很大的国家，地大、物博、人多、兵多，能够支持长期的战争，这同日本又是一个相反的对比。最后，第四，由于中国战争的进步性、正义性而产生出来的国际广大援助，同日本的失道寡助又恰恰相反。总起来说，中国的短处是战争力量之弱，而其长处则在其战争本质的进步性和正义性，在其是一个大国家，在其国际形势之多助。这些都是中国的特点。","language":"中文","translation":false},{"id":"protracted-war-1-34","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一二）这样看来，日本的军力、经济力和政治组织力是强的，但其战争是退步的、野蛮的，人力、物力又不充足，国际形势又处于不利。中国反是，军力、经济力和政治组织力是比较地弱的，然而正处于进步的时代，其战争是进步的和正义的，又有大国这个条件足以支持持久战，世界的多数国家是会要援助中国的。——这些，就是中日战争互相矛盾着的基本特点。这些特点，规定了和规定着双方一切政治上的政策和军事上的战略战术，规定了和规定着战争的持久性和最后胜利属于中国而不属于日本。战争就是这些特点的比赛。这些特点在战争过程中将各依其本性发生变化，一切东西就都从这里发生出来。这些特点是事实上存在的，不是虚造骗人的；是战争的全部基本要素，不是残缺不全的片段；是贯彻于双方一切大小问题和一切作战阶段之中的，不是可有可无的。观察中日战争如果忘记了这些特点，那就必然要弄错；即使某些意见一时有人相信，似乎不错，但战争的经过必将证明它们是错的。我们现在就根据这些特点来说明我们所要说的一切问题。","language":"中文","translation":false},{"id":"protracted-war-1-35","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一三）亡国论者看到敌我强弱对比一个因素，从前就说“抗战必亡”，现在又说“再战必亡”。如果我们仅仅说，敌人虽强，但是小国，中国虽弱，但是大国，是不足以折服他们的。他们可以搬出元朝灭宋、清朝灭明的历史证据，证明小而强的国家能够灭亡大而弱的国家，而且是落后的灭亡进步的。如果我们说，这是古代，不足为据，他们又可以搬出英灭印度的事实，证明小而强的资本主义国家能够灭亡大而弱的落后国家。所以还须提出其它的根据，才能把一切亡国论者的口封住，使他们心服，而使一切从事宣传工作的人们得到充足的论据去说服还不明白和还不坚定的人们，巩固其抗战的信心。","language":"中文","translation":false},{"id":"protracted-war-1-36","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一四）这应该提出的根据是什么呢？就是时代的特点。这个特点的具体反映是日本的退步和寡助，中国的进步和多助。","language":"中文","translation":false},{"id":"protracted-war-1-37","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一五）我们的战争不是任何别的战争，乃是中日两国在二十世纪三十年代进行的战争。在我们的敌人方面，首先，它是快要死亡的帝国主义，它已处于退步时代，不但和英灭印度时期英国还处于资本主义的进步时代不相同，就是和二十年前第一次世界大战时的日本也不相同。此次战争发动于世界帝国主义首先是法西斯国家大崩溃的前夜，敌人也正是为了这一点才举行这个带最后挣扎性的冒险战争。所以，战争的结果，灭亡的不会是中国而是日本帝国主义的统治集团，这是无可逃避的必然性。再则，当日本举行战争的时候，正是世界各国或者已经遭遇战争或者快要遭遇战争的时候，大家都正在或准备着为反抗野蛮侵略而战，中国这个国家又是同世界多数国家和多数人民利害相关的，这就是日本已经引起并还要加深地引起世界多数国家和多数人民的反对的根源。","language":"中文","translation":false},{"id":"protracted-war-1-38","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一六）中国方面呢？它已经不能和别的任何历史时期相比较。半殖民地和半封建社会是它的特点，所以被称为弱国。但是在同时，它又处于历史上进步的时代，这就是足以战胜日本的主要根据。所谓抗日战争是进步的，不是说普通一般的进步，不是说阿比西尼亚抗意战争的那种进步，也不是说太平天国或辛亥革命的那种进步，而是说今天中国的进步。今天中国的进步在什么地方呢？在于它已经不是完全的封建国家，已经有了资本主义，有了资产阶级和无产阶级，有了已经觉悟或正在觉悟的广大人民，有了共产党，有了政治上进步的军队即共产党领导的中国红军，有了数十年革命的传统经验，特别是中国共产党成立以来的十七年的经验。这些经验，教育了中国的人民，教育了中国的政党，今天恰好作了团结抗日的基础。如果说，在俄国，没有一九○五年的经验就不会有一九一七年的胜利；那末，我们也可以说，如果没有十七年以来的经验，也将不会有抗日的胜利。这是国内的条件。","language":"中文","translation":false},{"id":"protracted-war-1-39","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"国际的条件，使得中国在战争中不是孤立的，这一点也是历史上空前的东西。历史上不论中国的战争也罢，印度的战争也罢，都是孤立的。惟独今天遇到世界上已经发生或正在发生的空前广大和空前深刻的人民运动及其对于中国的援助。俄国一九一七年的革命也遇到世界的援助，俄国的工人和农民因此胜利了，但那个援助的规模还没有今天广大，性质也没有今天深刻。今天的世界的人民运动，正在以空前的大规模和空前的深刻性发展着。苏联的存在，更是今天国际政治上十分重要的因素，它必然以极大的热忱援助中国，这一现象，是二十年前完全没有的。所有这些，造成了和造成着为中国最后胜利所不可缺少的重要的条件。大量的直接的援助，目前虽然还没有，尚有待于来日，但是中国有进步和大国的条件，能够延长战争的时间，促进并等候国际的援助。","language":"中文","translation":false},{"id":"protracted-war-1-40","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一七）加上日本是小国，地小、物少、人少、兵少，中国是大国，地大、物博、人多、兵多这一个条件，于是在强弱对比之外，就还有小国、退步、寡助和大国、进步、多助的对比，这就是中国决不会亡的根据。强弱对比虽然规定了日本能够在中国有一定时期和一定程度的横行，中国不可避免地要走一段艰难的路程，抗日战争是持久战而不是速决战；然而小国、退步、寡助和大国、进步、多助的对比，又规定了日本不能横行到底，必然要遭到最后的失败，中国决不会亡，必然要取得最后的胜利。","language":"中文","translation":false},{"id":"protracted-war-1-41","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一八）阿比西尼亚为什么灭亡了呢？第一，它不但是弱国，而且是小国。第二，它不如中国进步，它是一个古老的奴隶制到农奴制的国家，没有资本主义，没有资产阶级政党，更没有共产党，没有中国这样的军队，更没有如同八路军这样的军队。第三，它不能等候国际的援助，它的战争是孤立的。第四，这是主要的，抗意战争领导方面有错误。阿比西尼亚因此灭亡了。然而阿比西尼亚还有相当广大的游击战争存在，如能坚持下去，是可以在未来的世界变动中据以恢复其祖国的。","language":"中文","translation":false},{"id":"protracted-war-1-42","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一九）如果亡国论者搬出中国近代解放运动的失败史来证明“抗战必亡”和“再战必亡”的话，那我们的答复也是时代不同一句话。中国本身、日本内部、国际环境都和过去不相同。日本比过去更强了，中国的半殖民地和半封建地位依然未变，力量依然颇弱，这一点是严重的情形。日本暂时还能控制其国内的人民，也还能利用国际间的矛盾作为其侵华的工具，这些都是事实。然而在长期的战争过程中，必然要发生相反的变化。这一点现在还不是事实，但是将来必然要成为事实的。这一点，亡国论者就抛弃不顾了。中国呢？不但现在已有新的人、新的政党、新的军队和新的抗日政策，和十余年以前有很大的不同，而且这些都必然会向前发展。虽然历史上的解放运动屡次遭受挫折，使中国不能积蓄更大的力量用于今日的抗日战争——这是非常可痛惜的历史的教训，从今以后，再也不要自己摧残任何的革命力量了——然而就在既存的基础上，加上广大的努力，必能逐渐前进，加强抗战的力量。伟大的抗日民族统一战线，就是这种努力的总方向。国际援助一方面，眼前虽然还看不见大量的和直接的，但是国际局面根本已和过去两样，大量和直接的援助正在酝酿中。中国近代无数解放运动的失败都有其客观和主观的原因，都不能比拟今天的情况。在今天，虽然存在着许多困难条件，规定了抗日战争是艰难的战争，例如敌人之强，我们之弱，敌人的困难还刚在开始，我们的进步还很不够，如此等等，然而战胜敌人的有利条件是很多的，只须加上主观的努力，就能克服困难而争取胜利。这些有利条件，历史上没有一个时候可和今天比拟，这就是抗日战争必不会和历史上的解放运动同归失败的理由。","language":"中文","translation":false},{"id":"protracted-war-1-43","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"妥协还是抗战？腐败还是进步？","language":"中文","translation":false},{"id":"protracted-war-1-44","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二○）亡国论之没有根据，俱如上述。但是另有许多人，并非亡国论者，他们是爱国志士，却对时局怀抱甚深的忧虑。他们的问题有两个：一是惧怕对日妥协，一是怀疑政治不能进步。这两个可忧虑的问题在广大的人们中间议论着，找不到解决的基点。我们现在就来研究这两个问题。","language":"中文","translation":false},{"id":"protracted-war-1-45","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二一）前头说过，妥协的问题是有其社会根源的，这个社会根源存在，妥协问题就不会不发生。但妥协是不会成功的。要证明这一点，仍不外向日本、中国、国际三方面找根据。第一是日本方面。还在抗战初起时，我们就估计有一种酝酿妥协空气的时机会要到来，那就是在敌人占领华北和江浙之后，可能出以劝降手段。后来果然来了这一手；但是危机随即过去，原因之一是敌人采取了普遍的野蛮政策，实行公开的掠夺。中国降了，任何人都要做亡国奴。敌人的这一掠夺的即灭亡中国的政策，分为物质的和精神的两方面，都是普遍地施之于中国人的；不但是对下层民众，而且是对上层成分，——当然对后者稍为客气些，但也只有程度之别，并无原则之分。大体上，敌人是将东三省的老办法移植于内地。在物质上，掠夺普通人民的衣食，使广大人民啼饥号寒；掠夺生产工具，使中国民族工业归于毁灭和奴役化。在精神上，摧残中国人民的民族意识。在太阳旗下，每个中国人只能当顺民，做牛马，不许有一丝一毫的中国气。敌人的这一野蛮政策，还要施之于更深的内地。他的胃口很旺，不愿停止战争。一九三八年一月十六日日本内阁宣言的方针[14]，至今坚决执行，也不能不执行，这就激怒了一切阶层的中国人。这是根据敌人战争的退步性野蛮性而来的，“在劫难逃”，于是形成了绝对的敌对。估计到某种时机，敌之劝降手段又将出现，某些亡国论者又将蠕蠕而动，而且难免勾结某些国际成分（英、美、法内部都有这种人，特别是英国的上层分子），狼狈为奸。但是大势所趋，是降不了的，日本战争的坚决性和特殊的野蛮性，规定了这个问题的一方面。","language":"中文","translation":false},{"id":"protracted-war-1-46","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二二）第二是中国方面。中国坚持抗战的因素有三个：其一，共产党，这是领导人民抗日的可靠力量。又其一，国民党，因其是依靠英美的，英美不叫它投降，它也就不会投降。又其一，别的党派，大多数是反对妥协、拥护抗战的。这三者互相团结，谁要妥协就是站在汉奸方面，人人得而诛之。一切不愿当汉奸的人，就不能不团结起来坚持抗战到底，妥协就实际上难于成功。","language":"中文","translation":false},{"id":"protracted-war-1-47","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二三）第三是国际方面。除日本的盟友和各资本主义国家的上层分子中的某些成分外，其余都不利于中国妥协而利于中国抗战。这一因素影响到中国的希望。今天全国人民有一种希望，认为国际力量必将逐渐增强地援助中国。这种希望不是空的；特别是苏联的存在，鼓舞了中国的抗战。空前强大的社会主义的苏联，它和中国是历来休戚相关的。苏联和一切资本主义国家的上层成分之唯利是图者根本相反，它是以援助一切弱小民族和革命战争为其职志的。中国战争之非孤立性，不但一般地建立在整个国际的援助上，而且特殊地建立在苏联的援助上。中苏两国是地理接近的，这一点加重了日本的危机，便利了中国的抗战。中日两国地理接近，加重了中国抗战的困难。然而中苏的地理接近，却是中国抗战的有利条件。","language":"中文","translation":false},{"id":"protracted-war-1-48","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二四）由此可作结论：妥协的危机是存在的，但是能够克服。因为敌人的政策即使可作某种程度的改变，但其根本改变是不可能的。中国内部有妥协的社会根源，但是反对妥协的占大多数。国际力量也有一部分赞助妥协，但是主要的力量赞助抗战。这三种因素结合起来，就能克服妥协危机，坚持抗战到底。","language":"中文","translation":false},{"id":"protracted-war-1-49","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二五）现在来答复第二个问题。国内政治的改进，是和抗战的坚持不能分离的。政治越改进，抗战越能坚持；抗战越坚持，政治就越能改进。但是基本上依赖于坚持抗战。国民党的各方面的不良现象是严重地存在着，这些不合理因素的历史积累，使得广大爱国志士发生很大的忧虑和烦闷。但是抗战的经验已经证明，十个月的中国人民的进步抵得上过去多少年的进步，并无使人悲观的根据。历史积累下来的腐败现象，虽然很严重地阻碍着人民抗战力量增长的速度，减少了战争的胜利，招致了战争的损失，但是中国、日本和世界的大局，不容许中国人民不进步。由于阻碍进步的因素即腐败现象之存在，这种进步是缓慢的。进步和进步的缓慢是目前时局的两个特点，后一个特点和战争的迫切要求很不相称，这就是使得爱国志士们大为发愁的地方。然而我们是在革命战争中，革命战争是一种抗毒素，它不但将排除敌人的毒焰，也将清洗自己的污浊。凡属正义的革命的战争，其力量是很大的，它能改造很多事物，或为改造事物开辟道路。中日战争将改造中日两国；只要中国坚持抗战和坚持统一战线，就一定能把旧日本化为新日本，把旧中国化为新中国，中日两国的人和物都将在这次战争中和战争后获得改造。我们把抗战和建国联系起来看，是正当的。说日本也能获得改造，是说日本统治者的侵略战争将走到失败，有引起日本人民革命之可能。日本人民革命胜利之日，就是日本改造之时。这和中国的抗战密切地联系着，这一个前途是应该看到的。","language":"中文","translation":false},{"id":"protracted-war-1-50","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"亡国论是不对的，速胜论也是不对的","language":"中文","translation":false},{"id":"protracted-war-1-51","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二六）我们已把强弱、大小、进步退步、多助寡助几个敌我之间矛盾着的基本特点，作了比较研究，批驳了亡国论，答复了为什么不易妥协和为什么政治可能进步的问题。亡国论者看重了强弱一个矛盾，把它夸大起来作为全部问题的论据，而忽略了其它的矛盾。他们只提强弱对比一点，是他们的片面性；他们将此片面的东西夸大起来看成全体，又是他们的主观性。所以在全体说来，他们是没有根据的，是错误的。那些并非亡国论者，也不是一贯的悲观主义者，仅为一时候和一局部的敌我强弱情况或国内腐败现象所迷惑，而一时地发生悲观心理的人们，我们也得向他们指出，他们的观点的来源也是片面性和主观性的倾向。但是他们的改正较容易，只要一提醒就会明白，因为他们是爱国志士，他们的错误是一时的。","language":"中文","translation":false},{"id":"protracted-war-1-52","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二七）然而速胜论者也是不对的。他们或则根本忘记了强弱这个矛盾，而单单记起了其它矛盾；或则对于中国的长处，夸大得离开了真实情况，变成另一种样子；或则拿一时一地的强弱现象代替了全体中的强弱现象，一叶障目，不见泰山，而自以为是。总之，他们没有勇气承认敌强我弱这件事实。他们常常抹杀这一点，因此抹杀了真理的一方面。他们又没有勇气承认自己长处之有限性，因而抹杀了真理的又一方面。由此犯出或大或小的错误来，这里也是主观性和片面性作怪。这些朋友们的心是好的，他们也是爱国志士。但是“先生之志则大矣”，先生的看法则不对，照了做去，一定碰壁。因为估计不符合真相，行动就无法达到目的；勉强行去，败军亡国，结果和失败主义者没有两样。所以也是要不得的。","language":"中文","translation":false},{"id":"protracted-war-1-53","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二八）我们是否否认亡国危险呢？不否认的。我们承认在中国面前摆着解放和亡国两个可能的前途，两者在猛烈地斗争中。我们的任务在于实现解放而避免亡国。实现解放的条件，基本的是中国的进步，同时，加上敌人的困难和世界的援助。我们和亡国论者不同，我们客观地而且全面地承认亡国和解放两个可能同时存在，着重指出解放的可能占优势及达到解放的条件，并为争取这些条件而努力。亡国论者则主观地和片面地只承认亡国一个可能性，否认解放的可能性，更不会指出解放的条件和为争取这些条件而努力。我们对于妥协倾向和腐败现象也是承认的，但是我们还看到其它倾向和其它现象，并指出二者之中后者对于前者将逐步地占优势，二者在猛烈地斗争着；并指出后者实现的条件，为克服妥协倾向和转变腐败现象而努力。因此，我们并不悲观，而悲观的人们则与此相反。","language":"中文","translation":false},{"id":"protracted-war-1-54","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（二九）我们也不是不喜欢速胜，谁也赞成明天一个早上就把“鬼子”赶出去。但是我们指出，没有一定的条件，速胜只存在于头脑之中，客观上是不存在的，只是幻想和假道理。因此，我们客观地并全面地估计到一切敌我情况，指出只有战略的持久战才是争取最后胜利的唯一途径，而排斥毫无根据的速胜论。我们主张为着争取最后胜利所必要的一切条件而努力，条件多具备一分，早具备一日，胜利的把握就多一分，胜利的时间就早一日。我们认为只有这样才能缩短战争的过程，而排斥贪便宜尚空谈的速胜论。","language":"中文","translation":false},{"id":"protracted-war-1-55","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三○）现在我们来把持久战问题研究一下。“为什么是持久战”这一个问题，只有依据全部敌我对比的基本因素，才能得出正确的回答。例如单说敌人是帝国主义的强国，我们是半殖民地半封建的弱国，就有陷入亡国论的危险。因为单纯地以弱敌强，无论在理论上，在实际上，都不能产生持久的结果。单是大小或单是进步退步、多助寡助，也是一样。大并小、小并大的事都是常有的。进步的国家或事物，如果力量不强，常有被大而退步的国家或事物所灭亡者。多助寡助是重要因素，但是附随因素，依敌我本身的基本因素如何而定其作用的大小。因此，我们说抗日战争是持久战，是从全部敌我因素的相互关系产生的结论。敌强我弱，我有灭亡的危险。但敌尚有其它缺点，我尚有其它优点。敌之优点可因我之努力而使之削弱，其缺点亦可因我之努力而使之扩大。我方反是，我之优点可因我之努力而加强，缺点则因我之努力而克服。所以我能最后胜利，避免灭亡，敌则将最后失败，而不能避免整个帝国主义制度的崩溃。","language":"中文","translation":false},{"id":"protracted-war-1-56","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三一）既然敌之优点只有一个，余皆缺点，我之缺点只有一个，余皆优点，为什么不能得出平衡结果，反而造成了现时敌之优势我之劣势呢？很明显的，不能这样形式地看问题。事情是现时敌我强弱的程度悬殊太大，敌之缺点一时还没有也不能发展到足以减杀其强的因素之必要的程度，我之优点一时也没有且不能发展到足以补充其弱的因素之必要的程度，所以平衡不能出现，而出现的是不平衡。","language":"中文","translation":false},{"id":"protracted-war-1-57","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三二）敌强我弱，敌是优势而我是劣势，这种情况，虽因我之坚持抗战和坚持统一战线的努力而有所变化，但是还没有产生基本的变化。所以，在战争的一定阶段上，敌能得到一定程度的胜利，我则将遭到一定程度的失败。然而敌我都只限于这一定阶段内一定程度上的胜或败，不能超过而至于全胜或全败，这是什么缘故呢？因为一则敌强我弱之原来状况就是相对的，不是绝对的；二则由于我之坚持抗战和坚持统一战线的努力，更加造成这种相对的形势。拿原来状况来说，敌虽强，但敌之强已为其它不利的因素所减杀，不过此时还没有减杀到足以破坏敌之优势的必要的程度；我虽弱，但我之弱已为其它有利的因素所补充，不过此时还没有补充到足以改变我之劣势的必要的程度。于是形成敌是相对的强，我是相对的弱；敌是相对的优势，我是相对的劣势。双方的强弱优劣原来都不是绝对的，加以战争过程中我之坚持抗战和坚持统一战线的努力，更加变化了敌我原来强弱优劣的形势，因而敌我只限于一定阶段内的一定程度上的胜或败，造成了持久战的局面。","language":"中文","translation":false},{"id":"protracted-war-1-58","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三三）然而情况是继续变化的。战争过程中，只要我能运用正确的军事的和政治的策略，不犯原则的错误，竭尽最善的努力，敌之不利因素和我之有利因素均将随战争之延长而发展，必能继续改变着敌我强弱的原来程度，继续变化着敌我的优劣形势。到了新的一定阶段时，就将发生强弱程度上和优劣形势上的大变化，而达到敌败我胜的结果。","language":"中文","translation":false},{"id":"protracted-war-1-59","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三四）目前敌尚能勉强利用其强的因素，我之抗战尚未给他以基本的削弱。其人力、物力不足的因素尚不足以阻止其进攻，反之，尚足以维持其进攻到一定的程度。其足以加剧本国阶级对立和中国民族反抗的因素，即战争之退步性和野蛮性一因素，亦尚未造成足以根本妨碍其进攻的情况。敌人的国际孤立的因素也方在变化发展之中，还没有达到完全的孤立。许多表示助我的国家的军火资本家和战争原料资本家，尚在唯利是图地供给日本以大量的战争物资[15]，他们的政府[16]亦尚不愿和苏联一道用实际方法制裁日本。这一切，规定了我之抗战不能速胜，而只能是持久战。中国方面，弱的因素表现在军事、经济、政治、文化各方面的，虽在十个月抗战中有了某种程度的进步，但距离足以阻止敌之进攻及准备我之反攻的必要的程度，还远得很。且在量的方面，又不得不有所减弱。其各种有利因素，虽然都在起积极作用，但达到足以停止敌之进攻及准备我之反攻的程度则尚有待于巨大的努力。在国内，克服腐败现象，增加进步速度；在国外，克服助日势力，增加反日势力，尚非目前的现实。这一切，又规定了战争不能速胜，而只能是持久战。","language":"中文","translation":false},{"id":"protracted-war-1-60","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三五）中日战争既然是持久战，最后胜利又将是属于中国的，那末，就可以合理地设想，这种持久战，将具体地表现于三个阶段之中。第一个阶段，是敌之战略进攻、我之战略防御的时期。第二个阶段，是敌之战略保守、我之准备反攻的时期。第三个阶段，是我之战略反攻、敌之战略退却的时期。三个阶段的具体情况不能预断，但依目前条件来看，战争趋势中的某些大端是可以指出的。客观现实的行程将是异常丰富和曲折变化的，谁也不能造出一本中日战争的“流年”来；然而给战争趋势描画一个轮廓，却为战略指导所必需。所以，尽管描画的东西不能尽合将来的事实，而将为事实所校正，但是为着坚定地有目的地进行持久战的战略指导起见，描画轮廓的事仍然是需要的。","language":"中文","translation":false},{"id":"protracted-war-1-61","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三六）第一阶段，现在还未完结。敌之企图是攻占广州、武汉、兰州三点，并把三点联系起来。敌欲达此目的，至少出五十个师团，约一百五十万兵员，时间一年半至两年，用费将在一百万万日元以上。敌人如此深入，其困难是非常之大的，其后果将不堪设想。至欲完全占领粤汉铁路和西兰公路，将经历非常危险的战争，未必尽能达其企图。但是我们的作战计划，应把敌人可能占领三点甚至三点以外之某些部分地区并可能互相联系起来作为一种基础，部署持久战，即令敌如此做，我也有应付之方。这一阶段我所采取的战争形式，主要的是运动战，而以游击战和阵地战辅助之。阵地战虽在此阶段之第一期，由于国民党军事当局的主观错误把它放在主要地位，但从全阶段看，仍然是辅助的。此阶段中，中国已经结成了广大的统一战线，实现了空前的团结。敌虽已经采用过并且还将采用卑鄙无耻的劝降手段，企图不费大力实现其速决计划，整个地征服中国，但是过去的已经失败，今后的也难成功。此阶段中，中国虽有颇大的损失，但是同时却有颇大的进步，这种进步就成为第二阶段继续抗战的主要基础。此阶段中，苏联对于我国已经有了大量的援助。敌人方面，士气已开始表现颓靡，敌人陆军进攻的锐气，此阶段的中期已不如初期，末期将更不如初期。敌之财政和经济已开始表现其竭蹶状态，人民和士兵的厌战情绪已开始发生，战争指导集团的内部已开始表现其“战争的烦闷”，生长着对于战争前途的悲观。","language":"中文","translation":false},{"id":"protracted-war-1-62","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三七）第二阶段，可以名之曰战略的相持阶段。第一阶段之末尾，由于敌之兵力不足和我之坚强抵抗，敌人将不得不决定在一定限度上的战略进攻终点，到达此终点以后，即停止其战略进攻，转入保守占领地的阶段。此阶段内，敌之企图是保守占领地，以组织伪政府的欺骗办法据之为己有，而从中国人民身上尽量搜括东西，但是在他的面前又遇着顽强的游击战争。游击战争在第一阶段中乘着敌后空虚将有一个普遍的发展，建立许多根据地，基本上威胁到敌人占领地的保守，因此第二阶段仍将有广大的战争。此阶段中我之作战形式主要的是游击战，而以运动战辅助之。此时中国尚能保有大量的正规军，不过一方面因敌在其占领的大城市和大道中取战略守势，一方面因中国技术条件一时未能完备，尚难迅即举行战略反攻。除正面防御部队外，我军将大量地转入敌后，比较地分散配置，依托一切敌人未占区域，配合民众武装，向敌人占领地作广泛的和猛烈的游击战争，并尽可能地调动敌人于运动战中消灭之，如同现在山西的榜样。此阶段的战争是残酷的，地方将遇到严重的破坏。但是游击战争能够胜利，做得好，可能使敌只能保守占领地三分之一左右的区域，三分之二左右仍然是我们的，这就是敌人的大失败，中国的大胜利。那时，整个敌人占领地将分为三种地区：第一种是敌人的根据地，第二种是游击战争的根据地，第三种是双方争夺的游击区。这个阶段的时间的长短，依敌我力量增减变化的程度如何及国际形势变动如何而定，大体上我们要准备付给较长的时间，要熬得过这段艰难的路程。这将是中国很痛苦的时期，经济困难和汉奸捣乱将是两个很大的问题。敌人将大肆其破坏中国统一战线的活动，一切敌之占领地的汉奸组织将合流组成所谓“统一政府”。我们内部，因大城市的丧失和战争的困难，动摇分子将大倡其妥协论，悲观情绪将严重地增长。此时我们的任务，在于动员全国民众，齐心一致，绝不动摇地坚持战争，把统一战线扩大和巩固起来，排除一切悲观主义和妥协论，提倡艰苦斗争，实行新的战时政策，熬过这一段艰难的路程。此阶段内，必须号召全国坚决地维持一个统一政府，反对分裂，有计划地增强作战技术，改造军队，动员全民，准备反攻。此阶段中，国际形势将变到更于日本不利，虽可能有张伯伦[17]一类的迁就所谓“既成事实”的“现实主义”的调头出现，但主要的国际势力将变到进一步地援助中国。日本威胁南洋和威胁西伯利亚，将较之过去更加严重，甚至爆发新的战争。敌人方面，陷在中国泥潭中的几十个师团抽不出去。广大的游击战争和人民抗日运动将疲惫这一大批日本军，一方面大量地消耗之，又一方面进一步地增长其思乡厌战直至反战的心理，从精神上瓦解这个军队。日本在中国的掠夺虽然不能说它绝对不能有所成就，但是日本资本缺乏，又困于游击战争，急遽的大量的成就是不可能的。这个第二阶段是整个战争的过渡阶段，也将是最困难的时期，然而它是转变的枢纽。中国将变为独立国，还是沦为殖民地，不决定于第一阶段大城市之是否丧失，而决定于第二阶段全民族努力的程度。如能坚持抗战，坚持统一战线和坚持持久战，中国将在此阶段中获得转弱为强的力量。中国抗战的三幕戏，这是第二幕。由于全体演员的努力，最精彩的结幕便能很好地演出来。","language":"中文","translation":false},{"id":"protracted-war-1-63","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三八）第三阶段，是收复失地的反攻阶段。收复失地，主要地依靠中国自己在前阶段中准备着的和在本阶段中继续地生长着的力量。然而单只自己的力量还是不够的，还须依靠国际力量和敌国内部变化的援助，否则是不能胜利的，因此加重了中国的国际宣传和外交工作的任务。这个阶段，战争已不是战略防御，而将变为战略反攻了，在现象上，并将表现为战略进攻；已不是战略内线，而将逐渐地变为战略外线。直至打到鸭绿江边，才算结束了这个战争。第三阶段是持久战的最后阶段，所谓坚持战争到底，就是要走完这个阶段的全程。这个阶段我所采取的主要的战争形式仍将是运动战，但是阵地战将提到重要地位。如果说，第一阶段的阵地防御，由于当时的条件，不能看作重要的，那末，第三阶段的阵地攻击，由于条件的改变和任务的需要，将变成颇为重要的。此阶段内的游击战，仍将辅助运动战和阵地战而起其战略配合的作用，和第二阶段之变为主要形式者不相同。","language":"中文","translation":false},{"id":"protracted-war-1-64","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（三九）这样看来，战争的长期性和随之而来的残酷性，是明显的。敌人不能整个地吞并中国，但是能够相当长期地占领中国的许多地方。中国也不能迅速地驱逐日本，但是大部分的土地将依然是中国的。最后是敌败我胜，但是必须经过一段艰难的路程。","language":"中文","translation":false},{"id":"protracted-war-1-65","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四○）中国人民在这样长期和残酷的战争中间，将受到很好的锻炼。参加战争的各政党也将受到锻炼和考验。统一战线必须坚持下去；只有坚持统一战线，才能坚持战争；只有坚持统一战线和坚持战争，才能有最后胜利。果然是这样，一切困难就能够克服。跨过战争的艰难路程之后，胜利的坦途就到来了，这是战争的自然逻辑。","language":"中文","translation":false},{"id":"protracted-war-1-66","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四一）三个阶段中，敌我力量的变化将循着下述的道路前进。第一阶段敌是优势，我是劣势。我之这种劣势，须估计抗战以前到这一阶段末尾，有两种不同的变化。第一种是向下的。中国原来的劣势，经过第一阶段的消耗将更为严重，这就是土地、人口、经济力量、军事力量和文化机关等的减缩。第一阶段的末尾，也许要减缩到相当大的程度，特别是经济方面。这一点，将被人利用作为亡国论和妥协论的根据。然而必须看到第二种变化，即向上的变化。这就是战争中的经验，军队的进步，政治的进步，人民的动员，文化的新方向的发展，游击战争的出现，国际援助的增长等等。在第一阶段，向下的东西是旧的量和质，主要地表现在量上。向上的东西是新的量和质，主要地表现在质上。这第二种变化，就给了我们以能够持久和最后胜利的根据。","language":"中文","translation":false},{"id":"protracted-war-1-67","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四二）第一阶段中，敌人方面也有两种变化。第一种是向下的，表现在：几十万人的伤亡，武器和弹药的消耗，士气的颓靡，国内人心的不满，贸易的缩减，一百万万日元以上的支出，国际舆论的责备等等方面。这个方面，又给予我们以能够持久和最后胜利的根据。然而也要估计到敌人的第二种变化，即向上的变化。那就是他扩大了领土、人口和资源。在这点上面，又产生我们的抗战是持久战而不能速胜的根据，同时也将被一些人利用作为亡国论和妥协论的根据。但是我们必须估计敌人这种向上变化的暂时性和局部性。敌人是行将崩溃的帝国主义者，他占领中国的土地是暂时的。中国游击战争的猛烈发展，将使他的占领区实际上限制在狭小的地带。而且，敌人对中国土地的占领又产生了和加深了日本同外国的矛盾。再则，根据东三省的经验，日本在相当长的时间内，一般地只能是支出资本时期，不能是收获时期。所有这些，又是我们击破亡国论和妥协论而建立持久论和最后胜利论的根据。","language":"中文","translation":false},{"id":"protracted-war-1-68","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四三）第二阶段，上述双方的变化将继续发展，具体的情形不能预断，但是大体上将是日本继续向下，中国继续向上[18]。例如日本的军力、财力大量地消耗于中国的游击战争，国内人心更加不满，士气更加颓靡，国际更感孤立。中国则政治、军事、文化和人民动员将更加进步，游击战争更加发展，经济方面也将依凭内地的小工业和广大的农业而有某种程度的新发展，国际援助将逐渐地增进，将比现在的情况大为改观。这个第二阶段，也许将经过相当长的时间。在这个时间内，敌我力量对比将发生巨大的相反的变化，中国将逐渐上升，日本则逐渐下降。那时中国将脱出劣势，日本则脱出优势，先走到平衡的地位，再走到优劣相反的地位。然后中国大体上将完成战略反攻的准备而走到实行反攻、驱敌出国的阶段。应该重复地指出：所谓变劣势为优势和完成反攻准备，是包括中国自己力量的增长、日本困难的增长和国际援助的增长在内的，总合这些力量就能形成中国的优势，完成反攻的准备。","language":"中文","translation":false},{"id":"protracted-war-1-69","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四四）根据中国政治和经济不平衡的状态，第三阶段的战略反攻，在其前一时期将不是全国整齐划一的姿态，而是带地域性的和此起彼落的姿态。敌人采用各种分化手段破裂中国统一战线的企图，此阶段中并不会减弱，因此，中国内部团结的任务更加重要，务不令内部不调致战略反攻半途而废。此时期中，国际形势将变到大有利于中国。中国的任务，就在于利用这种国际形势取得自己的彻底解放，建立独立的民主国家，同时也就是帮助世界的反法西斯运动。","language":"中文","translation":false},{"id":"protracted-war-1-70","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四五）中国由劣势到平衡到优势，日本由优势到平衡到劣势，中国由防御到相持到反攻，日本由进攻到保守到退却——这就是中日战争的过程，中日战争的必然趋势。","language":"中文","translation":false},{"id":"protracted-war-1-71","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四六）于是问题和结论是：中国会亡吗？答复：不会亡，最后胜利是中国的。中国能够速胜吗？答复：不能速胜，必须是持久战。这个结论是正确的吗？我以为是正确的。","language":"中文","translation":false},{"id":"protracted-war-1-72","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四七）讲到这里，亡国论和妥协论者又将跑出来说：中国由劣势到平衡，需要有同日本相等的军力和经济力；由平衡到优势，需要有超过日本的军力和经济力；然而这是不可能的，因此上述结论是不正确的。","language":"中文","translation":false},{"id":"protracted-war-1-73","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四八）这就是所谓“唯武器论”，是战争问题中的机械论，是主观地和片面地看问题的意见。我们的意见与此相反，不但看到武器，而且看到人力。武器是战争的重要的因素，但不是决定的因素，决定的因素是人不是物。力量对比不但是军力和经济力的对比，而且是人力和人心的对比。军力和经济力是要人去掌握的。如果中国人的大多数、日本人的大多数、世界各国人的大多数是站在抗日战争方面的话，那末，日本少数人强制地掌握着的军力和经济力，还能算是优势吗？它不是优势，那末，掌握比较劣势的军力和经济力的中国，不就成了优势吗？没有疑义，中国只要坚持抗战和坚持统一战线，其军力和经济力是能够逐渐地加强的。而我们的敌人，经过长期战争和内外矛盾的削弱，其军力和经济力又必然要起相反的变化。在这种情况下，难道中国也不能变成优势吗？还不止此，目前我们不能把别国的军力和经济力大量地公开地算作自己方面的力量，难道将来也不能吗？如果日本的敌人不止中国一个，如果将来有一国或几国以其相当大量的军力和经济力公开地防御或攻击日本，公开地援助我们，那末，优势不更在我们一方面吗？日本是小国，其战争是退步的和野蛮的，其国际地位将益处于孤立；中国是大国，其战争是进步的和正义的，其国际地位将益处于多助。所有这些，经过长期发展，难道还不能使敌我优劣的形势确定地发生变化吗？","language":"中文","translation":false},{"id":"protracted-war-1-74","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（四九）速胜论者则不知道战争是力量的竞赛，在战争双方的力量对比没有起一定的变化以前，就要举行战略的决战，就想提前到达解放之路，也是没有根据的。其意见实行起来，一定不免于碰壁。或者只是空谈快意，并不准备真正去做。最后则是事实先生跑将出来，给这些空谈家一瓢冷水，证明他们不过是一些贪便宜、想少费气力多得收成的空谈主义者。这种空谈主义过去和现在已经存在，但是还不算很多，战争发展到相持阶段和反攻阶段时，空谈主义可能多起来。但是在同时，如果第一阶段中国损失较大，第二阶段时间拖得很长，亡国论和妥协论更将大大地流行。所以我们的火力，应该主要地向着亡国论和妥协论方面，而以次要的火力，反对空谈主义的速胜论。","language":"中文","translation":false},{"id":"protracted-war-1-75","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五○）战争的长期性是确定了的，但是战争究将经过多少年月则谁也不能预断，这个完全要看敌我力量变化的程度才能决定。一切想要缩短战争时间的人们，惟有努力于增加自己力量减少敌人力量之一法。具体地说，惟有努力于作战多打胜仗，消耗敌人的军队，努力于发展游击战争，使敌之占领地限制于最小的范围，努力于巩固和扩大统一战线，团结全国力量，努力于建设新军和发展新的军事工业，努力于推动政治、经济和文化的进步，努力于工、农、商、学各界人民的动员，努力于瓦解敌军和争取敌军的士兵，努力于国际宣传争取国际的援助，努力于争取日本的人民及其它被压迫民族的援助，做了这一切，才能缩短战争的时间，此外不能有任何取巧图便的法门。","language":"中文","translation":false},{"id":"protracted-war-1-76","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五一）我们可以断言，持久战的抗日战争，将在人类战争史中表现为光荣的特殊的一页。犬牙交错的战争形态，就是颇为特殊的一点，这是由于日本的野蛮和兵力不足，中国的进步和土地广大这些矛盾因素产生出来的。犬牙交错的战争，在历史上也是有过的，俄国十月革命后的三年内战，就有过这种情形。但其在中国的特点，是其特殊的长期性和广大性，这将是突破历史纪录的东西。这种犬牙交错的形态，表现在下述的几种情况上。","language":"中文","translation":false},{"id":"protracted-war-1-77","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五二）内线和外线——抗日战争是整个处于内线作战的地位的；但是主力军和游击队的关系，则是主力军在内线，游击队在外线，形成夹攻敌人的奇观。各游击区的关系亦然。各个游击区都以自己为内线，而以其它各区为外线，又形成了很多夹攻敌人的火线。在战争的第一阶段，战略上内线作战的正规军是后退的，但是战略上外线作战的游击队则将广泛地向着敌人后方大踏步前进，第二阶段将更加猛烈地前进，形成了后退和前进的奇异形态。","language":"中文","translation":false},{"id":"protracted-war-1-78","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五三）有后方和无后方——利用国家的总后方，而把作战线伸至敌人占领地之最后限界的，是主力军。脱离总后方，而把作战线伸至敌后的，是游击队。但在每一游击区中，仍自有其小规模的后方，并依以建立非固定的作战线。和这个区别的，是每一游击区派遣出去向该区敌后临时活动的游击队，他们不但没有后方，也没有作战线。“无后方的作战”，是新时代中领土广大、人民进步、有先进政党和先进军队的情况之下的革命战争的特点，没有可怕而有大利，不应怀疑而应提倡。","language":"中文","translation":false},{"id":"protracted-war-1-79","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五四）包围和反包围——从整个战争看来，由于敌之战略进攻和外线作战，我处战略防御和内线作战地位，无疑我是在敌之战略包围中。这是敌对于我之第一种包围。由于我以数量上优势的兵力，对于从战略上的外线分数路向我前进之敌，采取战役和战斗上的外线作战方针，就可以把各路分进之敌的一路或几路放在我之包围中。这是我对于敌之第一种反包围。再从敌后游击战争的根据地看来，每一孤立的根据地都处于敌之四面或三面包围中，前者例如五台山，后者例如晋西北。这是敌对于我之第二种包围。但若将各个游击根据地联系起来看，并将各个游击根据地和正规军的阵地也联系起来看，我又把许多敌人都包围起来，例如在山西，我已三面包围了同蒲路（路之东西两侧及南端），四面包围了太原城；河北、山东等省也有许多这样的包围。这又是我对于敌之第二种反包围。这样，敌我各有加于对方的两种包围，大体上好似下围棋一样，敌对于我我对于敌之战役和战斗的作战，好似吃子，敌的据点（例如太原）和我之游击根据地（例如五台山），好似做眼。如果把世界性的围棋也算在内，那就还有第三种敌我包围，这就是侵略阵线与和平阵线的关系。敌以前者来包围中、苏、法、捷等国，我以后者反包围德、日、意。但是我之包围好似如来佛的手掌，它将化成一座横亘宇宙的五行山，把这几个新式孙悟空——法西斯侵略主义者，最后压倒在山底下，永世也不得翻身[19]。如果我能在外交上建立太平洋反日阵线，把中国作为一个战略单位，又把苏联及其它可能的国家也各作为一个战略单位，又把日本人民运动也作为一个战略单位，形成一个使法西斯孙悟空无处逃跑的天罗地网，那就是敌人死亡之时了。实际上，日本帝国主义完全打倒之日，必是这个天罗地网大体布成之时。这丝毫也不是笑话，而是战争的必然的趋势。","language":"中文","translation":false},{"id":"protracted-war-1-80","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五五）大块和小块——一种可能，是敌占地区将占中国本部之大半，而中国本部完整的区域只占一小半。这是一种情形。但是敌占大半中，除东三省等地外，实际只能占领大城市、大道和某些平地，依重要性说是一等的，依面积和人口来说可能只是敌占区中之小半，而普遍地发展的游击区，反居其大半。这又是一种情形。如果超越本部的范围，而把蒙古、新疆、青海、西藏算了进来，则在面积上中国未失地区仍然是大半，而敌占地区包括东三省在内，也只是小半。这又是一种情形。完整区域当然是重要的，应集大力去经营，不但政治、军事、经济等方面，文化方面也要紧。敌人已将我们过去的文化中心变为文化落后区域，而我们则要将过去的文化落后区域变为文化中心。同时，敌后广大游击区的经营也是非常之要紧的，也应把它们的各方面发展起来，也应发展其文化工作。总起来看，中国将是大块的乡村变为进步和光明的地区，而小块的敌占区，尤其是大城市，将暂时地变为落后和黑暗的地区。","language":"中文","translation":false},{"id":"protracted-war-1-81","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五六）这样看来，长期而又广大的抗日战争，是军事、政治、经济、文化各方面犬牙交错的战争，这是战争史上的奇观，中华民族的壮举，惊天动地的伟业。这个战争，不但将影响到中日两国，大大推动两国的进步，而且将影响到世界，推动各国首先是印度等被压迫民族的进步。全中国人都应自觉地投入这个犬牙交错的战争中去，这就是中华民族自求解放的战争形态，是半殖民地大国在二十世纪三十和四十年代举行的解放战争的特殊的形态。","language":"中文","translation":false},{"id":"protracted-war-1-82","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五七）中国抗日战争的持久性同争取中国和世界的永久和平，是不能分离的。没有任何一个历史时期像今天一样，战争是接近于永久和平的。由于阶级的出现，几千年来人类的生活中充满了战争，每一个民族都不知打了几多仗，或在民族集团之内打，或在民族集团之间打。打到资本主义社会的帝国主义时期，仗就打得特别广大和特别残酷。二十年前的第一次帝国主义大战，在过去历史上是空前的，但还不是绝后的战争。只有目前开始了的战争，接近于最后战争，就是说，接近于人类的永久和平。目前世界上已有三分之一的人口进入了战争，你们看，一个意大利，又一个日本，一个阿比西尼亚，又一个西班牙，再一个中国。参加战争的这些国家共有差不多六万万人口，几乎占了全世界总人口的三分之一。目前的战争的特点是无间断和接近永久和平的性质。为什么无间断？意大利同阿比西尼亚打了之后，接着意大利同西班牙打，德国也搭了股份，接着日本又同中国打。还要接着谁呢？无疑地要接着希特勒同各大国打。“法西斯主义就是战争”[20]，一点也不错。目前的战争发展到世界大战之间，是不会间断的，人类的战争灾难不可避免。为什么又说这次战争接近于永久和平？这次战争是在第一次世界大战所已开始的世界资本主义总危机发展的基础上发生的，由于这种总危机，逼使各资本主义国家走入新的战争，首先逼使各法西斯国家从事于新战争的冒险。我们可以预见这次战争的结果，将不是资本主义的获救，而是它的走向崩溃。这次战争，将比二十年前的战争更大，更残酷，一切民族将无可避免地卷入进去，战争时间将拖得很长，人类将遭受很大的痛苦。但是由于苏联的存在和世界人民觉悟程度的提高，这次战争中无疑将出现伟大的革命战争，用以反对一切反革命战争，而使这次战争带着为永久和平而战的性质。即使尔后尚有一个战争时期，但是已离世界的永久和平不远了。人类一经消灭了资本主义，便到达永久和平的时代，那时候便再也不要战争了。那时将不要军队，也不要兵船，不要军用飞机，也不要毒气。从此以后，人类将亿万斯年看不见战争。已经开始了的革命的战争，是这个为永久和平而战的战争的一部分。占着五万万以上人口的中日两国之间的战争，在这个战争中将占着重要的地位，中华民族的解放将从这个战争中得来。将来的被解放了的新中国，是和将来的被解放了的新世界不能分离的。因此，我们的抗日战争包含着为争取永久和平而战的性质。","language":"中文","translation":false},{"id":"protracted-war-1-83","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五八）历史上的战争分为两类，一类是正义的，一类是非正义的。一切进步的战争都是正义的，一切阻碍进步的战争都是非正义的。我们共产党人反对一切阻碍进步的非正义的战争，但是不反对进步的正义的战争。对于后一类战争，我们共产党人不但不反对，而且积极地参加。前一类战争，例如第一次世界大战，双方都是为着帝国主义利益而战，所以全世界的共产党人坚决地反对那一次战争。反对的方法，在战争未爆发前，极力阻止其爆发；既爆发后，只要有可能，就用战争反对战争，用正义战争反对非正义战争。日本的战争是阻碍进步的非正义的战争，全世界人民包括日本人民在内，都应该反对，也正在反对。我们中国，则从人民到政府，从共产党到国民党，一律举起了义旗，进行了反侵略的民族革命战争。我们的战争是神圣的、正义的，是进步的、求和平的。不但求一国的和平，而且求世界的和平，不但求一时的和平，而且求永久的和平。欲达此目的，便须决一死战，便须准备着一切牺牲，坚持到底，不达目的，决不停止。牺牲虽大，时间虽长，但是永久和平和永久光明的新世界，已经鲜明地摆在我们的前面。我们从事战争的信念，便建立在这个争取永久和平和永久光明的新中国和新世界的上面。法西斯主义和帝国主义要把战争延长到无尽期，我们则要把战争在一个不很久远的将来给以结束。为了这个目的，人类大多数应该拿出极大的努力。四亿五千万的中国人占了全人类的四分之一，如果能够一齐努力，打倒了日本帝国主义，创造了自由平等的新中国，对于争取全世界永久和平的贡献，无疑地是非常伟大的。这种希望不是空的，全世界社会经济的行程已经接近了这一点，只须加上多数人的努力，几十年工夫一定可以达到目的。","language":"中文","translation":false},{"id":"protracted-war-1-84","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（五九）以上说的，都是说明为什么是持久战和为什么最后胜利是中国的，大体上都是说的“是什么”和“不是什么”。以下，将转到研究“怎样做”和“不怎样做”的问题上。怎样进行持久战和怎样争取最后胜利？这就是以下要答复的问题。为了这个，我们将依次说明下列的问题：能动性在战争中，战争和政治，抗战的政治动员，战争的目的，防御中的进攻，持久中的速决，内线中的外线，主动性，灵活性，计划性，运动战，游击战，阵地战，歼灭战，消耗战，乘敌之隙的可能性，抗日战争的决战问题，兵民是胜利之本。我们现在就从能动性问题说起吧。","language":"中文","translation":false},{"id":"protracted-war-1-85","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六○）我们反对主观地看问题，说的是一个人的思想，不根据和不符合于客观事实，是空想，是假道理，如果照了做去，就要失败，故须反对它。但是一切事情是要人做的，持久战和最后胜利没有人做就不会出现。做就必须先有人根据客观事实，引出思想、道理、意见，提出计划、方针、政策、战略、战术，方能做得好。思想等等是主观的东西，做或行动是主观见之于客观的东西，都是人类特殊的能动性。这种能动性，我们名之曰“自觉的能动性”，是人之所以区别于物的特点。一切根据和符合于客观事实的思想是正确的思想，一切根据于正确思想的做或行动是正确的行动。我们必须发扬这样的思想和行动，必须发扬这种自觉的能动性。抗日战争是要赶走帝国主义，变旧中国为新中国，必须动员全中国人民，统统发扬其抗日的自觉的能动性，才能达到目的。坐着不动，只有被灭亡，没有持久战，也没有最后胜利。","language":"中文","translation":false},{"id":"protracted-war-1-86","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六一）自觉的能动性是人类的特点。人类在战争中强烈地表现出这样的特点。战争的胜负，固然决定于双方军事、政治、经济、地理、战争性质、国际援助诸条件，然而不仅仅决定于这些；仅有这些，还只是有了胜负的可能性，它本身没有分胜负。要分胜负，还须加上主观的努力，这就是指导战争和实行战争，这就是战争中的自觉的能动性。","language":"中文","translation":false},{"id":"protracted-war-1-87","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六二）指导战争的人们不能超越客观条件许可的限度期求战争的胜利，然而可以而且必须在客观条件的限度之内，能动地争取战争的胜利。战争指挥员活动的舞台，必须建筑在客观条件的许可之上，然而他们凭借这个舞台，却可以导演出很多有声有色、威武雄壮的戏剧来。在既定的客观物质的基础之上，抗日战争的指挥员就要发挥他们的威力，提挈全军，去打倒那些民族的敌人，改变我们这个被侵略被压迫的社会国家的状态，造成自由平等的新中国，这里就用得着而且必须用我们的主观指导的能力。我们不赞成任何一个抗日战争的指挥员，离开客观条件，变为乱撞乱碰的鲁莽家，但是我们必须提倡每个抗日战争的指挥员变为勇敢而明智的将军。他们不但要有压倒敌人的勇气，而且要有驾驭整个战争变化发展的能力。指挥员在战争的大海中游泳，他们要不使自己沉没，而要使自己决定地有步骤地到达彼岸。作为战争指导规律的战略战术，就是战争大海中的游泳术。","language":"中文","translation":false},{"id":"protracted-war-1-88","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六三）“战争是政治的继续”，在这点上说，战争就是政治，战争本身就是政治性质的行动，从古以来没有不带政治性的战争。抗日战争是全民族的革命战争，它的胜利，离不开战争的政治目的——驱逐日本帝国主义、建立自由平等的新中国，离不开坚持抗战和坚持统一战线的总方针，离不开全国人民的动员，离不开官兵一致、军民一致和瓦解敌军等项政治原则，离不开统一战线政策的良好执行，离不开文化的动员，离不开争取国际力量和敌国人民援助的努力。一句话，战争一刻也离不了政治。抗日军人中，如有轻视政治的倾向，把战争孤立起来，变为战争绝对主义者，那是错误的，应加纠正。","language":"中文","translation":false},{"id":"protracted-war-1-89","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六四）但是战争有其特殊性，在这点上说，战争不即等于一般的政治。“战争是政治的特殊手段的继续”[21]。政治发展到一定的阶段，再也不能照旧前进，于是爆发了战争，用以扫除政治道路上的障碍。例如中国的半独立地位，是日本帝国主义政治发展的障碍，日本要扫除它，所以发动了侵略战争。中国呢？帝国主义压迫，早就是中国资产阶级民主革命的障碍，所以有了很多次的解放战争，企图扫除这个障碍。日本现在用战争来压迫，要完全断绝中国革命的进路，所以不得不举行抗日战争，决心要扫除这个障碍。障碍既除，政治的目的达到，战争结束。障碍没有扫除得干净，战争仍须继续进行，以求贯彻。例如抗日的任务未完，有想求妥协的，必不成功；因为即使因某种缘故妥协了，但是战争仍要起来，广大人民必定不服，必要继续战争，贯彻战争的政治目的。因此可以说，政治是不流血的战争，战争是流血的政治。","language":"中文","translation":false},{"id":"protracted-war-1-90","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六五）基于战争的特殊性，就有战争的一套特殊组织，一套特殊方法，一种特殊过程。这组织，就是军队及其附随的一切东西。这方法，就是指导战争的战略战术。这过程，就是敌对的军队互相使用有利于己不利于敌的战略战术从事攻击或防御的一种特殊的社会活动形态。因此，战争的经验是特殊的。一切参加战争的人们，必须脱出寻常习惯，而习惯于战争，方能争取战争的胜利。","language":"中文","translation":false},{"id":"protracted-war-1-91","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六六）如此伟大的民族革命战争，没有普遍和深入的政治动员，是不能胜利的。抗日以前，没有抗日的政治动员，这是中国的大缺陷，已经输了敌人一着。抗日以后，政治动员也非常之不普遍，更不说深入。人民的大多数，是从敌人的炮火和飞机炸弹那里听到消息的。这也是一种动员，但这是敌人替我们做的，不是我们自己做的。偏远地区听不到炮声的人们，至今还是静悄悄地在那里过活。这种情形必须改变，不然，拚死活的战争就得不到胜利。决不可以再输敌人一着，相反，要大大地发挥这一着去制胜敌人。这一着是关系绝大的；武器等等不如人尚在其次，这一着实在是头等重要。动员了全国的老百姓，就造成了陷敌于灭顶之灾的汪洋大海，造成了弥补武器等等缺陷的补救条件，造成了克服一切战争困难的前提。要胜利，就要坚持抗战，坚持统一战线，坚持持久战。然而一切这些，离不开动员老百姓。要胜利又忽视政治动员，叫做“南其辕而北其辙”，结果必然取消了胜利。","language":"中文","translation":false},{"id":"protracted-war-1-92","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六七）什么是政治动员呢？首先是把战争的政治目的告诉军队和人民。必须使每个士兵每个人民都明白为什么要打仗，打仗和他们有什么关系。抗日战争的政治目的是“驱逐日本帝国主义，建立自由平等的新中国”，必须把这个目的告诉一切军民人等，方能造成抗日的热潮，使几万万人齐心一致，贡献一切给战争。其次，单单说明目的还不够，还要说明达到此目的的步骤和政策，就是说，要有一个政治纲领。现在已经有了《抗日救国十大纲领》[22]，又有了一个《抗战建国纲领》[23]，应把它们普及于军队和人民，并动员所有的军队和人民实行起来。没有一个明确的具体的政治纲领，是不能动员全军全民抗日到底的。其次，怎样去动员？靠口说，靠传单布告，靠报纸书册，靠戏剧电影，靠学校，靠民众团体，靠干部人员。现在国民党统治地区有的一些，沧海一粟，而且方法不合民众口味，神气和民众隔膜，必须切实地改一改。其次，不是一次动员就够了，抗日战争的政治动员是经常的。不是将政治纲领背诵给老百姓听，这样的背诵是没有人听的；要联系战争发展的情况，联系士兵和老百姓的生活，把战争的政治动员，变成经常的运动。这是一件绝大的事，战争首先要靠它取得胜利。","language":"中文","translation":false},{"id":"protracted-war-1-93","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六八）这里不是说战争的政治目的，抗日战争的政治目的是“驱逐日本帝国主义，建立自由平等的新中国”，前面已经说过了。这里说的，是作为人类流血的政治的所谓战争，两军相杀的战争，它的根本目的是什么。战争的目的不是别的，就是“保存自己，消灭敌人”（消灭敌人，就是解除敌人的武装，也就是所谓“剥夺敌人的抵抗力”，不是要完全消灭其肉体）。古代战争，用矛用盾：矛是进攻的，为了消灭敌人；盾是防御的，为了保存自己。直到今天的武器，还是这二者的继续。轰炸机、机关枪、远射程炮、毒气，是矛的发展；防空掩蔽部、钢盔、水泥工事、防毒面具，是盾的发展。坦克，是矛盾二者结合为一的新式武器。进攻，是消灭敌人的主要手段，但防御也是不能废的。进攻，是直接为了消灭敌人的，同时也是为了保存自己，因为如不消灭敌人，则自己将被消灭。防御，是直接为了保存自己的，但同时也是辅助进攻或准备转入进攻的一种手段。退却，属于防御一类，是防御的继续；而追击，则是进攻的继续。应该指出：战争目的中，消灭敌人是主要的，保存自己是第二位的，因为只有大量地消灭敌人，才能有效地保存自己。因此，作为消灭敌人之主要手段的进攻是主要的，而作为消灭敌人之辅助手段和作为保存自己之一种手段的防御，是第二位的。战争实际中，虽有许多时候以防御为主，而在其余时候以进攻为主，然而通战争的全体来看，进攻仍然是主要的。","language":"中文","translation":false},{"id":"protracted-war-1-94","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（六九）怎样解释战争中提倡勇敢牺牲呢？岂非与“保存自己”相矛盾？不相矛盾，是相反相成的。战争是流血的政治，是要付代价的，有时是极大的代价。部分的暂时的牺牲（不保存），为了全体的永久的保存。我们说，基本上为着消灭敌人的进攻手段中，同时也含了保存自己的作用，理由就在这里。防御必须同时有进攻，而不应是单纯的防御，也是这个道理。","language":"中文","translation":false},{"id":"protracted-war-1-95","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七○）保存自己消灭敌人这个战争的目的，就是战争的本质，就是一切战争行动的根据，从技术行动起，到战略行动止，都是贯彻这个本质的。战争目的，是战争的基本原则，一切技术的、战术的、战役的、战略的原理原则，一点也离不开它。射击原则的“荫蔽身体，发扬火力”是什么意思呢？前者为了保存自己，后者为了消灭敌人。因为前者，于是利用地形地物，采取跃进运动，疏开队形，种种方法都发生了。因为后者，于是扫清射界，组织火网，种种方法也发生了。战术上的突击队、钳制队、预备队，第一种为了消灭敌人，第二种为了保存自己，第三种准备依情况使用于两个目的——或者增援突击队，或者作为追击队，都是为了消灭敌人；或者增援钳制队，或者作为掩护队，都是为了保存自己。照这样，一切技术、战术、战役、战略原则，一切技术、战术、战役、战略行动，一点也离不开战争的目的，它普及于战争的全体，贯彻于战争的始终。","language":"中文","translation":false},{"id":"protracted-war-1-96","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七一）抗日战争的各级指导者，不能离开中日两国之间各种互相对立的基本因素去指导战争，也不能离开这个战争目的去指导战争。两国之间各种互相对立的基本因素展开于战争的行动中，就变成互相为了保存自己消灭敌人而斗争。我们的战争，在于力求每战争取不论大小的胜利，在于力求每战解除敌人一部分武装，损伤敌人一部分人马器物。把这些部分地消灭敌人的成绩积累起来，成为大的战略胜利，达到最后驱敌出国，保卫祖国，建设新中国的政治目的。","language":"中文","translation":false},{"id":"protracted-war-1-97","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"防御中的进攻，持久中的速决，内线中的外线","language":"中文","translation":false},{"id":"protracted-war-1-98","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七二）现在来研究抗日战争中的具体的战略方针。我们已说过了，抗日的战略方针是持久战，是的，这是完全对的。但这是一般的方针，还不是具体的方针。怎样具体地进行持久战呢？这就是我们现在要讨论的问题。我们的答复是：在第一和第二阶段即敌之进攻和保守阶段中，应该是战略防御中的战役和战斗的进攻战，战略持久中的战役和战斗的速决战，战略内线中的战役和战斗的外线作战。在第三阶段中，应该是战略的反攻战。","language":"中文","translation":false},{"id":"protracted-war-1-99","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七三）由于日本是帝国主义的强国，我们是半殖民地半封建的弱国，日本是采取战略进攻方针的，我们则居于战略防御地位。日本企图采取战略的速决战，我们应自觉地采取战略的持久战。日本用其战斗力颇强的几十个师团的陆军（目前已到了三十个师团）和一部分海军，从陆海两面包围和封锁中国，又用空军轰炸中国。目前日本的陆军已占领从包头到杭州的长阵线，海军则到了福建广东，形成了大范围的外线作战。我们则处于内线作战地位。所有这些，都是由敌强我弱这个特点造成的。这是一方面的情形。","language":"中文","translation":false},{"id":"protracted-war-1-100","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七四）然而在另一方面，则适得其反。日本虽强，但兵力不足。中国虽弱，但地大、人多、兵多。这里就产生了两个重要的结果。第一，敌以少兵临大国，就只能占领一部分大城市、大道和某些平地。由是，在其占领区域，则空出了广大地面无法占领，这就给了中国游击战争以广大活动的地盘。在全国，即使敌能占领广州、武汉、兰州之线及其附近的地区，但以外的地区是难于占领的，这就给了中国以进行持久战和争取最后胜利的总后方和中枢根据地。第二，敌以少兵临多兵，便处于多兵的包围中。敌分路向我进攻，敌处战略外线，我处战略内线，敌是战略进攻，我是战略防御，看起来我是很不利的。然而我可以利用地广和兵多两个长处，不作死守的阵地战，采用灵活的运动战，以几个师对他一个师，几万人对他一万人，几路对他一路，从战场的外线，突然包围其一路而攻击之。于是敌之战略作战上的外线和进攻，在战役和战斗的作战上，就不得不变成内线和防御。我之战略作战上的内线和防御，在战役和战斗的作战上就变成了外线和进攻。对其一路如此，对其它路也是如此。以上两点，都是从敌小我大这一特点发生的。又由于敌兵虽少，乃是强兵（武器和人员的教养程度），我兵虽多，乃是弱兵（也仅是武器和人员的教养程度，不是士气），因此，在战役和战斗的作战上，我不但应以多兵打少兵，从外线打内线，还须采取速决战的方针。为了实行速决，一般应不打驻止中之敌，而打运动中之敌。我预将大兵荫蔽集结于敌必经通路之侧，乘敌运动之际，突然前进，包围而攻击之，打他一个措手不及，迅速解决战斗。打得好，可能全部或大部或一部消灭他；打不好，也给他一个大的杀伤。一战如此，他战皆然。不说多了，每个月打得一个较大的胜仗，如像平型关台儿庄一类的，就能大大地沮丧敌人的精神，振起我军的士气，号召世界的声援。这样，我之战略的持久战，到战场作战就变成速决战了。敌之战略的速决战，经过许多战役和战斗的败仗，就不得不改为持久战。","language":"中文","translation":false},{"id":"protracted-war-1-101","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七五）上述这样的战役和战斗的作战方针，一句话说完，就是：“外线的速决的进攻战”。这对于我之战略方针“内线的持久的防御战”说来，是相反的；然而，又恰是实现这样的战略方针之必要的方针。如果战役和战斗方针也同样是“内线的持久的防御战”，例如抗战初起时期之所为，那就完全不适合敌小我大、敌强我弱这两种情况，那就决然达不到战略目的，达不到总的持久战，而将为敌人所击败。所以，我们历来主张全国组成若干个大的野战兵团，其兵力针对着敌人每个野战兵团之兵力而二倍之、三倍之或四倍之，采用上述方针，与敌周旋于广大战场之上。这种方针，不但是正规战争用得着，游击战争也用得着，而且必须要用它。不但适用于战争的某一阶段，而且适用于战争的全过程。战略反攻阶段，我之技术条件增强，以弱敌强这种情况即使完全没有了，我仍用多兵从外线采取速决的进攻战，就更能收大批俘获的成效。例如我用两个或三个或四个机械化的师对敌一个机械化的师，更能确定地消灭这个师。几个大汉打一个大汉之容易打胜，这是常识中包含的真理。","language":"中文","translation":false},{"id":"protracted-war-1-102","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七六）如果我们坚决地采取了战场作战的“外线的速决的进攻战”，就不但在战场上改变着敌我之间的强弱优劣形势，而且将逐渐地变化着总的形势。在战场上，因为我是进攻，敌是防御；我是多兵处外线，敌是少兵处内线；我是速决，敌虽企图持久待援，但不能由他作主；于是在敌人方面，强者就变成了弱者，优势就变成了劣势；我军方面反之，弱者变成了强者，劣势变成了优势。在打了许多这样的胜仗之后，总的敌我形势便将引起变化。这就是说，集合了许多战场作战的外线的速决的进攻战的胜利以后，就逐渐地增强了自己，削弱了敌人，于是总的强弱优劣形势，就不能不受其影响而发生变化。到那时，配合着我们自己的其它条件，再配合着敌人内部的变动和国际上的有利形势，就能使敌我总的形势走到平衡，再由平衡走到我优敌劣。那时，就是我们实行反攻驱敌出国的时机了。","language":"中文","translation":false},{"id":"protracted-war-1-103","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七七）战争是力量的竞赛，但力量在战争过程中变化其原来的形态。在这里，主观的努力，多打胜仗，少犯错误，是决定的因素。客观因素具备着这种变化的可能性，但实现这种可能性，就需要正确的方针和主观的努力。这时候，主观作用是决定的了。","language":"中文","translation":false},{"id":"protracted-war-1-104","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七八）上面说过的战役和战斗的外线的速决的进攻战，中心点在于一个进攻；外线是说的进攻的范围，速决是说的进攻的时间，所以叫它做“外线的速决的进攻战”。这是实行持久战的最好的方针，也即是所谓运动战的方针。但是这个方针实行起来，离不了主动性、灵活性和计划性。我们现在就来研究这三个问题。","language":"中文","translation":false},{"id":"protracted-war-1-105","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（七九）前面已说过了自觉的能动性，为什么又说主动性呢？自觉的能动性，说的是自觉的活动和努力，是人之所以区别于物的特点，这种人的特点，特别强烈地表现于战争中，这些是前面说过了的。这里说的主动性，说的是军队行动的自由权，是用以区别于被迫处于不自由状态的。行动自由是军队的命脉，失了这种自由，军队就接近于被打败或被消灭。一个士兵被缴械，是这个士兵失了行动自由被迫处于被动地位的结果。一个军队的战败，也是一样。为此缘故，战争的双方，都力争主动，力避被动。我们提出的外线的速决的进攻战，以及为了实现这种进攻战的灵活性、计划性，可以说都是为了争取主动权，以便逼敌处于被动地位，达到保存自己消灭敌人之目的。但主动或被动是和战争力量的优势或劣势分不开的。因而也是和主观指导的正确或错误分不开的。此外，也还有利用敌人的错觉和不意来争取自己主动和逼敌处于被动的情形。下面就来分析这几点。","language":"中文","translation":false},{"id":"protracted-war-1-106","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八○）主动是和战争力量的优势不能分离的，而被动则和战争力量的劣势分不开。战争力量的优势或劣势，是主动或被动的客观基础。战略的主动地位，自然以战略的进攻战为较能掌握和发挥，然而贯彻始终和普及各地的主动地位，即绝对的主动权，只有以绝对优势对绝对劣势才有可能。一个身体壮健者和一个重病患者角斗，前者便有绝对的主动权。如果日本没有许多不可克服的矛盾，例如它能一下出几百万至一千万大兵，财源比现在多过几倍，又没有民众和外国的敌对，又不实行野蛮政策招致中国人民拚死命反抗，那它便能保持一种绝对的优势，它便有一种贯彻始终和普及各地的绝对的主动权。但在历史上，这类绝对优势的事情，在战争和战役的结局是存在的，战争和战役的开头则少见。例如在第一次世界大战中，德国屈服的前夜，这时协约国变成了绝对优势，德国则变成了绝对劣势，结果德国失败，协约国获胜，这是战争结局存在着绝对的优势和劣势之例。又如台儿庄胜利的前夜，这时当地孤立的日军经过苦战之后，已处于绝对的劣势，我军则造成了绝对的优势，结果敌败我胜，这是战役结局存在着绝对的优势和劣势之例。战争或战役也有以相对的优劣或平衡状态而结局的，那时，在战争则出现妥协，在战役则出现对峙。但一般是以绝对的优劣而分胜负居多数。所有这些，都是战争或战役的结局，而非战争或战役的开头。中日战争的最后结局，可以预断，日本将以绝对劣势而失败，中国将以绝对优势而获胜；但是在目前，则双方的优劣都不是绝对的而是相对的。日本因其具有强的军力、经济力和政治组织力这个有利因素，对于我们弱的军力、经济力和政治组织力，占了优势，因而造成了它的主动权的基础。但是因为它的军力等等数量不多，又有其它许多不利因素，它的优势便为它自己的矛盾所减杀。及到中国，又碰到了中国的地大、人多、兵多和坚强的民族抗战，它的优势再为之减杀。于是在总的方面，它的地位就变成一种相对的优势，因而其主动权的发挥和维持就受了限制，也成了相对的东西。中国方面，虽然在力量的强度上是劣势，因此造成了战略上的某种被动姿态，但是在地理、人口和兵员的数量上，并且又在人民和军队的敌忾心和士气上，却处于优势，这种优势再加上其它的有利因素，便减杀了自己军力、经济力等的劣势的程度，使之变为战略上的相对的劣势。因而也减少了被动的程度，仅处于战略上的相对的被动地位。然而被动总是不利的，必须力求脱离它。军事上的办法，就是坚决地实行外线的速决的进攻战和发动敌后的游击战争，在战役的运动战和游击战中取得许多局部的压倒敌人的优势和主动地位。通过这样许多战役的局部优势和局部主动地位，就能逐渐地造成战略的优势和战略的主动地位，战略的劣势和被动地位就能脱出了。这就是主动和被动之间、优势和劣势之间的相互关系。","language":"中文","translation":false},{"id":"protracted-war-1-107","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八一）由此也就可以明白主动或被动和主观指导之间的关系。如上所述，我之相对的战略劣势和战略被动地位，是能够脱出的，方法就是人工地造成我们许多的局部优势和局部主动地位，去剥夺敌人的许多局部优势和局部主动地位，把他抛入劣势和被动。把这些局部的东西集合起来，就成了我们的战略优势和战略主动，敌人的战略劣势和战略被动。这样的转变，依靠主观上的正确指导。为什么呢？我要优势和主动，敌人也要这个，从这点上看，战争就是两军指挥员以军力财力等项物质基础作地盘，互争优势和主动的主观能力的竞赛。竞赛结果，有胜有败，除了客观物质条件的比较外，胜者必由于主观指挥的正确，败者必由于主观指挥的错误。我们承认战争现象是较之任何别的社会现象更难捉摸，更少确实性，即更带所谓“盖然性”。但战争不是神物，仍是世间的一种必然运动，因此，孙子的规律，“知彼知己，百战不殆”[24]，仍是科学的真理。错误由于对彼己的无知，战争的特性也使人们在许多的场合无法全知彼己，因此产生了战争情况和战争行动的不确实性，产生了错误和失败。然而不管怎样的战争情况和战争行动，知其大略，知其要点，是可能的。先之以各种侦察手段，继之以指挥员的聪明的推论和判断，减少错误，实现一般的正确指导，是做得到的。我们有了这个“一般地正确的指导”做武器，就能多打胜仗，就能变劣势为优势，变被动为主动。这是主动或被动和主观指导的正确与否之间的关系。","language":"中文","translation":false},{"id":"protracted-war-1-108","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八二）主观指导的正确与否，影响到优势劣势和主动被动的变化，观于强大之军打败仗、弱小之军打胜仗的历史事实而益信。中外历史上这类事情是多得很的。中国如晋楚城濮之战[25]，楚汉成皋之战[26]，韩信破赵之战[27]，新汉昆阳之战[28]，袁曹官渡之战[29]，吴魏赤壁之战[30]，吴蜀彝陵之战[31]，秦晋淝水之战[32]等等，外国如拿破仑的多数战役[33]，十月革命后的苏联内战，都是以少击众，以劣势对优势而获胜。都是先以自己局部的优势和主动，向着敌人局部的劣势和被动，一战而胜，再及其余，各个击破，全局因而转成了优势，转成了主动。在原占优势和主动之敌则反是；由于其主观错误和内部矛盾，可以将其很好的或较好的优势和主动地位，完全丧失，化为败军之将，亡国之君。由此可知，战争力量的优劣本身，固然是决定主动或被动的客观基础，但还不是主动或被动的现实事物，必待经过斗争，经过主观能力的竞赛，方才出现事实上的主动或被动。在斗争中，由于主观指导的正确或错误，可以化劣势为优势，化被动为主动；也可以化优势为劣势，化主动为被动。一切统治王朝打不赢革命军，可见单是某种优势还没有确定主动地位，更没有确定最后胜利。主动和胜利，是可以根据真实的情况，经过主观能力的活跃，取得一定的条件，而由劣势和被动者从优势和主动者手里夺取过来的。","language":"中文","translation":false},{"id":"protracted-war-1-109","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八三）错觉和不意，可以丧失优势和主动。因而有计划地造成敌人的错觉，给以不意的攻击，是造成优势和夺取主动的方法，而且是重要的方法。错觉是什么呢？“八公山上，草木皆兵”[34]，是错觉之一例。“声东击西”，是造成敌人错觉之一法。在优越的民众条件具备，足以封锁消息时，采用各种欺骗敌人的方法，常能有效地陷敌于判断错误和行动错误的苦境，因而丧失其优势和主动。“兵不厌诈”，就是指的这件事情。什么是不意？就是无准备。优势而无准备，不是真正的优势，也没有主动。懂得这一点，劣势而有准备之军，常可对敌举行不意的攻势，把优势者打败。我们说运动之敌好打，就是因为敌在不意即无准备中。这两件事——造成敌人的错觉和出以不意的攻击，即是以战争的不确实性给予敌人，而给自己以尽可能大的确实性，用以争取我之优势和主动，争取我之胜利。要做到这些，先决条件是优越的民众组织。因此，发动所有一切反对敌人的老百姓，一律武装起来，对敌进行广泛的袭击，同时即用以封锁消息，掩护我军，使敌无从知道我军将在什么地方什么时候去攻击他，造成他的错觉和不意的客观基础，是非常之重要的。过去土地革命战争时代的中国红军，以弱小的军力而常打胜仗，得力于组织起来和武装起来了的民众是非常之大的。民族战争照规矩应比土地革命战争更能获得广大民众的援助；可是因为历史的错误[35]，民众是散的，不但仓卒难为我用，且时为敌人所利用。只有坚决地广泛地发动全体的民众，方能在战争的一切需要上给以无穷无尽的供给。在这个给敌以错觉和给敌以不意以便战而胜之的战争方法上，也就一定能起大的作用。我们不是宋襄公，不要那种蠢猪式的仁义道德[36]。我们要把敌人的眼睛和耳朵尽可能地封住，使他们变成瞎子和聋子，要把他们的指挥员的心尽可能地弄得混乱些，使他们变成疯子，用以争取自己的胜利。所有这些，也都是主动或被动和主观指导之间的相互关系。战胜日本是少不了这种主观指导的。","language":"中文","translation":false},{"id":"protracted-war-1-110","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八四）大抵日本在其进攻阶段中，因其军力之强和利用我之主观上的历史错误和现时错误，它是一般地处于主动地位的。但是这种主动，已随其本身带着许多不利因素及其在战争中也犯了些主观错误（详论见后），与乎我方具备着许多有利因素，而开始了部分的减弱。敌之在台儿庄失败和山西困处，就是显证。我在敌后游击战争的广大发展，则使其占领地的守军完全处于被动地位。虽则敌人此时还在其主动的战略进攻中，但他的主动将随其战略进攻的停止而结束。敌之兵力不足，没有可能作无限制的进攻，这是他不能继续保持主动地位的第一个根源。我之战役的进攻战，在敌后的游击战争及其它条件，这是他不能不停止进攻于一定限度和不能继续保持主动地位的第二个根源。苏联的存在及其它国际变化，是第三个根源。由此可见，敌人的主动地位是有限制的，也是能够破坏的。中国如能在作战方法上坚持主力军的战役和战斗的进攻战，猛烈地发展敌后的游击战争，并从政治上大大地发动民众，我之战略主动地位便能逐渐树立起来。","language":"中文","translation":false},{"id":"protracted-war-1-111","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八五）现在来说灵活性。灵活性是什么呢？就是具体地实现主动性于作战中的东西，就是灵活地使用兵力。灵活地使用兵力这件事，是战争指挥的中心任务，也是最不容易做好的。战争的事业，除了组织和教育军队，组织和教育人民等项之外，就是使用军队于战斗，而一切都是为了战斗的胜利。组织军队等等固然困难，但使用军队则更加困难，特别是在以弱敌强的情况之中。做这件事需要极大的主观能力，需要克服战争特性中的纷乱、黑暗和不确实性，而从其中找出条理、光明和确实性来，方能实现指挥上的灵活性。","language":"中文","translation":false},{"id":"protracted-war-1-112","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八六）抗日战争战场作战的基本方针，是外线的速决的进攻战。执行这个方针，有兵力的分散和集中、分进和合击、攻击和防御、突击和钳制、包围和迂回、前进和后退种种的战术或方法。懂得这些战术是容易的，灵活地使用和变换这些战术，就不容易了。这里有时机、地点、部队三个关节。不得其时，不得其地，不得于部队之情况，都将不能取胜。例如进攻某一运动中之敌，打早了，暴露了自己，给了敌人以预防条件；打迟了，敌已集中驻止，变为啃硬骨头。这就是时机问题。突击点选在左翼，恰当敌之弱点，容易取胜；选在右翼，碰在敌人的钉子上，不能奏效。这就是地点问题。以我之某一部队执行某种任务，容易取胜；以另一部队执行同样任务，难于收效。这就是部队情况问题。不但使用战术，还须变换战术。攻击变为防御，防御变为攻击，前进变为后退，后退变为前进，钳制队变为突击队，突击队变为钳制队，以及包围迂回等等之互相变换，依据敌我部队、敌我地形的情况，及时地恰当地给以变换，是灵活性的指挥之重要任务。战斗指挥如此，战役和战略指挥也是如此。","language":"中文","translation":false},{"id":"protracted-war-1-113","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八七）古人所谓“运用之妙，存乎一心”[37]，这个“妙”，我们叫做灵活性，这是聪明的指挥员的出产品。灵活不是妄动，妄动是应该拒绝的。灵活，是聪明的指挥员，基于客观情况，“审时度势”（这个势，包括敌势、我势、地势等项）而采取及时的和恰当的处置方法的一种才能，即是所谓“运用之妙”。基于这种运用之妙，外线的速决的进攻战就能较多地取得胜利，就能转变敌我优劣形势，就能实现我对于敌的主动权，就能压倒敌人而击破之，而最后胜利就属于我们了。","language":"中文","translation":false},{"id":"protracted-war-1-114","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八八）现在来说计划性。由于战争所特有的不确实性，实现计划性于战争，较之实现计划性于别的事业，是要困难得多的。然而，“凡事预则立，不预则废”[38]，没有事先的计划和准备，就不能获得战争的胜利。战争没有绝对的确实性，但不是没有某种程度的相对的确实性。我之一方是比较地确实的。敌之一方很不确实，但也有朕兆〔注：现通常写为“征兆”。——中文马克思主义文库〕可寻，有端倪可察，有前后现象可供思索。这就构成了所谓某种程度的相对的确实性，战争的计划性就有了客观基础。近代技术（有线电、无线电、飞机、汽车、铁道、轮船等）的发达，又使战争的计划性增大了可能。但由于战争只有程度颇低和时间颇暂的确实性，战争的计划性就很难完全和固定，它随战争的运动（或流动，或推移）而运动，且依战争范围的大小而有程度的不同。战术计划，例如小兵团和小部队的攻击或防御计划，常须一日数变。战役计划，即大兵团的行动计划，大体能终战役之局，但在该战役内，部分的改变是常有的，全部的改变也间或有之。战略计划，是基于战争双方总的情况而来的，有更大的固定的程度，但也只在一定的战略阶段内适用，战争向着新的阶段推移，战略计划便须改变。战术、战役和战略计划之各依其范围和情况而确定而改变，是战争指挥的重要关节，也即是战争灵活性的具体的实施，也即是实际的运用之妙。抗日战争的各级指挥员，对此应当加以注意。","language":"中文","translation":false},{"id":"protracted-war-1-115","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（八九）有些人，基于战争的流动性，就从根本上否认战争计划或战争方针之相对的固定性，说这样的计划或方针是“机械的”东西。这种意见是错误的。如上条所述，我们完全承认：由于战争情况之只有相对的确实性和战争是迅速地向前流动的（或运动的，推移的），战争的计划或方针，也只应给以相对的固定性，必须根据情况的变化和战争的流动而适时地加以更换或修改，不这样做，我们就变成机械主义者。然而决不能否认一定时间内的相对地固定的战争计划或方针；否认了这点，就否认了一切，连战争本身，连说话的人，都否认了。由于战争的情况和行动都有其相对的固定性，因而应之而生的战争计划或方针，也就必须拿相对的固定性赋予它。例如，由于华北战争的情况和八路军分散作战的行动有其在一定阶段内的固定性，因而在这一定阶段内赋予相对的固定性于八路军的“基本的是游击战，但不放松有利条件下的运动战”这种战略的作战方针，是完全必要的。战役方针，较之上述战略方针适用的时间要短促些，战术方针更加短促，然而都有其一定时间的固定性。否认了这点，战争就无从着手，成为毫无定见，这也不是、那也不是，或者这也是、那也是的战争相对主义了。没有人否认，就是在某一一定时间内适用的方针，它也是在流动的，没有这种流动，就不会有这一方针的废止和另一方针的采用。然而这种流动是有限制的，即流动于执行这一方针的各种不同的战争行动的范围中，而不是这一方针的根本性质的流动，即是说，是数的流动，不是质的流动。这种根本性质，在一定时间内是决不流动的，我们所谓一定时间内的相对的固定性，就是指的这一点。在绝对流动的整个战争长河中有其各个特定阶段上的相对的固定性——这就是我们对于战争计划或战争方针的根本性质的意见。","language":"中文","translation":false},{"id":"protracted-war-1-116","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九○）在说过了战略上的内线的持久的防御战和战役战斗上的外线的速决的进攻战，又说过了主动性、灵活性和计划性之后，我们可以总起来说几句。抗日战争应该是有计划的。战争计划即战略战术的具体运用，要带灵活性，使之能适应战争的情况。要处处照顾化劣势为优势，化被动为主动，以便改变敌我之间的形势。而一切这些，都表现于战役和战斗上的外线的速决的进攻战，同时也就表现于战略上的内线的持久的防御战之中。","language":"中文","translation":false},{"id":"protracted-war-1-117","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九一）作为战争内容的战略内线、战略持久、战略防御中的战役和战斗上的外线的速决的进攻战，在战争形式上就表现为运动战。运动战，就是正规兵团在长的战线和大的战区上面，从事于战役和战斗上的外线的速决的进攻战的形式。同时，也把为了便利于执行这种进攻战而在某些必要时机执行着的所谓“运动性的防御”包括在内，并且也把起辅助作用的阵地攻击和阵地防御包括在内。它的特点是：正规兵团，战役和战斗的优势兵力，进攻性和流动性。","language":"中文","translation":false},{"id":"protracted-war-1-118","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九二）中国版图广大，兵员众多，但军队的技术和教养不足；敌人则兵力不足，但技术和教养比较优良。在此种情形下，无疑地应以进攻的运动战为主要的作战形式，而以其它形式辅助之，组成整个的运动战。在这里，要反对所谓“有退无进”的逃跑主义，同时也要反对所谓“有进无退”的拚命主义。","language":"中文","translation":false},{"id":"protracted-war-1-119","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九三）运动战的特点之一，是其流动性，不但许可而且要求野战军的大踏步的前进和后退。然而，这和韩复榘式的逃跑主义[39]是没有相同之点的。战争的基本要求是：消灭敌人；其另一要求是：保存自己。保存自己的目的，在于消灭敌人；而消灭敌人，又是保存自己的最有效的手段。因此，运动战决不能被韩复榘一类人所借口，决不是只有向后的运动，没有向前的运动；这样的“运动”，否定了运动战的基本的进攻性，实行的结果，中国虽大，也是要被“运动”掉的。","language":"中文","translation":false},{"id":"protracted-war-1-120","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九四）然而另一种思想也是不对的，即所谓有进无退的拚命主义。我们主张以战役和战斗上的外线的速决的进攻战为内容的运动战，其中包括了辅助作用的阵地战，又包括了“运动性的防御”和退却，没有这些，运动战便不能充分地执行。拚命主义是军事上的近视眼，其根源常是惧怕丧失土地。拚命主义者不知道运动战的特点之一是其流动性，不但许可而且要求野战军的大踏步的进退。积极方面，为了陷敌于不利而利于我之作战，常常要求敌人在运动中，并要求有利于我之许多条件，例如有利的地形、好打的敌情、能封锁消息的居民、敌人的疲劳和不意等。这就要求敌人的前进，虽暂时地丧失部分土地而不惜。因为暂时地部分地丧失土地，是全部地永久地保存土地和恢复土地的代价。消极方面，凡被迫处于不利地位，根本上危及军力的保存时，应该勇敢地退却，以便保存军力，在新的时机中再行打击敌人。拚命主义者不知此理，明明已处于确定了的不利情况，还要争一城一地的得失，结果不但城和地俱失，军力也不能保存。我们历来主张“诱敌深入”，就是因为这是战略防御中弱军对强军作战的最有效的军事政策。","language":"中文","translation":false},{"id":"protracted-war-1-121","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九五）抗日战争的作战形式中，主要的是运动战，其次就要算游击战了。我们说，整个战争中，运动战是主要的，游击战是辅助的，说的是解决战争的命运，主要是依靠正规战，尤其是其中的运动战，游击战不能担负这种解决战争命运的主要的责任。但这不是说：游击战在抗日战争中的战略地位不重要。游击战在整个抗日战争中的战略地位，仅仅次于运动战，因为没有游击战的辅助，也就不能战胜敌人。这样说，是包括了游击战向运动战发展这一个战略任务在内的。长期的残酷的战争中间，游击战不停止于原来地位，它将把自己提高到运动战。这样，游击战的战略作用就有两方面：一是辅助正规战，一是把自己也变为正规战。至于就游击战在中国抗日战争中的空前广大和空前持久的意义说来，它的战略地位是更加不能轻视的了。因此，在中国，游击战的本身，不只有战术问题，还有它的特殊的战略问题。这个问题，我在《抗日游击战争的战略问题》一文里面已经说到了。前面说过，抗日战争三个战略阶段的作战形式，第一阶段，运动战是主要的，游击战和阵地战是辅助的。第二阶段，则游击战将升到主要地位，而以运动战和阵地战辅助之。第三阶段，运动战再升为主要形式，而辅之以阵地战和游击战。但这个第三阶段的运动战，已不全是由原来的正规军负担，而将由原来的游击军从游击战提高到运动战去担负其一部分，也许是相当重要的一部分。从三个阶段来看，中国抗日战争中的游击战，决不是可有可无的。它将在人类战争史上演出空前伟大的一幕。为此缘故，在全国的数百万正规军中间，至少指定数十万人，分散于所有一切敌占地区，发动和配合民众武装，从事游击战争，是完全必要的。被指定的军队，要自觉地负担这种神圣任务，不要以为少打大仗，一时显得不像民族英雄，降低了资格，这种想法是错误的。游击战争没有正规战争那样迅速的成效和显赫的名声，但是“路遥知马力，事久见人心”，在长期和残酷的战争中，游击战争将表现其很大的威力，实在是非同小可的事业。并且正规军分散作游击战，集合起来又可作运动战，八路军就是这样做的。八路军的方针是：“基本的是游击战，但不放松有利条件下的运动战。”这个方针是完全正确的，反对这个方针的人们的观点是不正确的。","language":"中文","translation":false},{"id":"protracted-war-1-122","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九六）防御的和攻击的阵地战，在中国今天的技术条件下，一般都不能执行，这也就是我们表现弱的地方。再则敌人又利用中国土地广大一点，回避我们的阵地设施。因此阵地战就不能用为重要手段，更不待说用为主要手段。然而在战争的第一第二两阶段中，包括于运动战范围，而在战役作战上起其辅助作用的局部的阵地战，是可能的和必要的。为着节节抵抗以求消耗敌人和争取余裕时间之目的，而采取半阵地性的所谓“运动性的防御”，更是属于运动战的必要部分。中国须努力增加新式武器，以便在战略反攻阶段中能够充分地执行阵地攻击的任务。战略反攻阶段，无疑地将提高阵地战的地位，因为那时敌人将坚守阵地，没有我之有力的阵地攻击以配合运动战，将不能达到收复失地之目的。虽然如此，第三阶段中，我们仍须力争以运动战为战争的主要形式。因为战争的领导艺术和人的活跃性，临到像第一次世界大战的中期以后西欧地区那样的阵地战，就死了一大半。然而在广大版图的中国境内作战，在相当长的时间内中国方面又还保存着技术贫弱这种情况，“把战争从壕沟里解放”的事，就自然出现。就在第三阶段，中国技术条件虽已增进，但仍不见得能够超过敌人，这样也就被逼着非努力讲求高度的运动战，不能达到最后胜利之目的。这样，整个抗日战争中，中国将不会以阵地战为主要形式，主要和重要的形式是运动战和游击战。在这些战争形式中，战争的领导艺术和人的活跃性能够得到充分地发挥的机会，这又是我们不幸中的幸事啊！","language":"中文","translation":false},{"id":"protracted-war-1-123","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九七）前头说过，战争本质即战争目的，是保存自己，消灭敌人。然而达此目的的战争形式，有运动战、阵地战、游击战三种，实现时的效果就有程度的不同，因而一般地有所谓消耗战和歼灭战之别。","language":"中文","translation":false},{"id":"protracted-war-1-124","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（九八）我们首先可以说，抗日战争是消耗战，同时又是歼灭战。为什么？敌之强的因素尚在发挥，战略上的优势和主动依然存在，没有战役和战斗的歼灭战，就不能有效地迅速地减杀其强的因素，破坏其优势和主动。我之弱的因素也依然存在，战略上的劣势和被动还未脱离，为了争取时间，加强国内国际条件，改变自己的不利状态，没有战役和战斗的歼灭战，也不能成功。因此，战役的歼灭战是达到战略的消耗战之目的的手段。在这点上说，歼灭战就是消耗战。中国之能够进行持久战，用歼灭达到消耗是主要的手段。（九九）但达到战略消耗目的的，还有战役的消耗战。大抵运动战是执行歼灭任务的，阵地战是执行消耗任务的，游击战是执行消耗任务同时又执行歼灭任务的，三者互有区别。在这点上说，歼灭战不同于消耗战。战役的消耗战，是辅助的，但也是持久作战所需要的。","language":"中文","translation":false},{"id":"protracted-war-1-125","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○○）从理论上和需要上说来，中国在防御阶段中，应该利用运动战之主要的歼灭性，游击战之部分的歼灭性，加上辅助性质的阵地战之主要的消耗性和游击战之部分的消耗性，用以达到大量消耗敌人的战略目的。在相持阶段中，继续利用游击战和运动战的歼灭性和消耗性，再行大量地消耗敌人。所有这些，都是为了使战局持久，逐渐地转变敌我形势，准备反攻的条件。战略反攻时，继续用歼灭达到消耗，以便最后地驱逐敌人。","language":"中文","translation":false},{"id":"protracted-war-1-126","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○一）但是在事实上，十个月的经验是，许多甚至多数的运动战战役，打成了消耗战；游击战之应有的歼灭作用，在某些地区，也还未提到应有的程度。这种情况的好处是，无论如何我们总算消耗了敌人，对于持久作战和最后胜利有其意义，我们的血不是白流的。然而缺点是：一则消耗敌人的不足；二则我们自己不免消耗的较多，缴获的较少。虽然应该承认这种情况的客观原因，即敌我技术和兵员教养程度的不同，然而在理论上和实际上，无论如何也应该提倡主力军在一切有利场合努力地执行歼灭战。游击队虽然为了执行许多具体任务，例如破坏和扰乱等，不能不进行单纯的消耗战，然而仍须提倡并努力实行在战役和战斗之一切有利场合的歼灭性的作战，以达既能大量消耗敌人又能大量补充自己之目的。","language":"中文","translation":false},{"id":"protracted-war-1-127","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○二）外线的速决的进攻战之所谓外线，所谓速决，所谓进攻，与乎运动战之所谓运动，在战斗形式上，主要地就是采用包围和迂回战术，因而便须集中优势兵力。所以，集中兵力，采用包围迂回战术，是实施运动战即外线的速决的进攻战之必要条件。然而一切这些，都是为着歼灭敌人之目的。","language":"中文","translation":false},{"id":"protracted-war-1-128","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○三）日本军队的长处，不但在其武器，还在其官兵的教养——其组织性，其因过去没有打过败仗而形成的自信心，其对天皇和对鬼神的迷信，其骄慢自尊，其对中国人的轻视等等特点；这是日本军阀多年的武断教育和日本的民族习惯造成的。我军对之杀伤甚多、俘虏甚少的现象，主要原因在此。这一点，过去许多人是估计不足的。这种东西的破坏，需要一个长的过程。首先需要我们重视这一特点，然后耐心地有计划地从政治上、国际宣传上、日本人民运动上多方面地向着这一点进行工作；而军事上的歼灭战，也是方法之一。在这里，悲观主义者可以据之引向亡国论，消极的军事家又可以据之反对歼灭战。我们则相反，我们认为日本军队的这种长处是可以破坏的，并且已在开始破坏中。破坏的方法，主要的是政治上的争取。对于日本士兵，不是侮辱其自尊心，而是了解和顺导他们的这种自尊心，从宽待俘虏的方法，引导他们了解日本统治者之反人民的侵略主义。另一方面，则是在他们面前表示中国军队和中国人民不可屈服的精神和英勇顽强的战斗力，这就是给以歼灭战的打击。在作战上讲，十个月的经验证明歼灭是可能的，平型关、台儿庄等战役就是明证。日本军心已在开始动摇，士兵不了解战争目的，陷于中国军队和中国人民的包围中，冲锋的勇气远弱于中国兵等等，都是有利于我之进行歼灭战的客观的条件，这些条件并将随着战争之持久而日益发展起来。在以歼灭战破坏敌军的气焰这一点上讲，歼灭又是缩短战争过程提早解放日本士兵和日本人民的条件之一。世界上只有猫和猫做朋友的事，而没有猫和老鼠做朋友的事。","language":"中文","translation":false},{"id":"protracted-war-1-129","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○四）另一方面，应该承认在技术和兵员教养的程度上，现时我们不及敌人。因而最高限度的歼灭，例如全部或大部俘获的事，在许多场合特别是在平原地带的战斗中，是困难的。速胜论者在这点上面的过分要求，也属不对。抗日战争的正确要求应该是：尽可能的歼灭战。在一切有利的场合，每战集中优势兵力，采用包围迂回战术——不能包围其全部也包围其一部，不能俘获所包围之全部也俘获所包围之一部，不能俘获所包围之一部也大量杀伤所包围之一部。而在一切不利于执行歼灭战的场合，则执行消耗战。对于前者，用集中兵力的原则；对于后者，用分散兵力的原则。在战役的指挥关系上，对于前者，用集中指挥的原则；对于后者，用分散指挥的原则。这些，就是抗日战争战场作战的基本方针。","language":"中文","translation":false},{"id":"protracted-war-1-130","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○五）关于敌之可胜，就是在敌人的指挥方面也有其基础。自古无不犯错误的将军，敌人之有岔子可寻，正如我们自己也难免出岔子，乘敌之隙的可能性是存在的。从战略和战役上说来，敌人在十个月侵略战争中，已经犯了许多错误。计其大者有五。一是逐渐增加兵力。这是由于敌人对中国估计不足而来的，也有他自己兵力不足的原因。敌人一向看不起我们，东四省[40]得了便宜之后，加之以冀东、察北的占领，这些都算作敌人的战略侦察。他们得来的结论是：一盘散沙。据此以为中国不值一打，而定出所谓“速决”的计划，少少出点兵力，企图吓溃我们。十个月来，中国这样大的团结和这样大的抵抗力，他们是没有料到的，他们把中国已处于进步时代，中国已存在着先进的党派、先进的军队和先进的人民这一点忘掉了。及至不行，就逐渐增兵，由十几个师团一次又一次地增至三十个。再要前进，非再增不可。但由于同苏联对立，又由于人财先天不足，所以日本的最大的出兵数和最后的进攻点都不得不受一定的限制。二是没有主攻方向。台儿庄战役以前，敌在华中、华北大体上是平分兵力的，两方内部又各自平分。例如华北，在津浦、平汉、同蒲三路平分兵力，每路伤亡了一些，占领地驻守了一些，再前进就没有兵了。台儿庄败仗后，总结了教训，把主力集中徐州方向，这个错误算是暂时地改了一下。三是没有战略协同。敌之华中、华北两集团中，每一集团内部是大体协同的，但两集团间则很不协同。津浦南段打小蚌埠时，北段不动；北段打台儿庄时，南段不动。两处都触了霉头之后，于是陆军大臣来巡视了，参谋总长来指挥了，算是暂时地协调了一下。日本地主资产阶级和军阀内部存在着颇为严重的矛盾，这种矛盾正在向前发展着，战争的不协同是其具体表现之一。四是失去战略时机。这点显着地表现在南京、太原两地占领后的停顿，主要的是因为兵力不足，没有战略追击队。五是包围多歼灭少。台儿庄战役以前，上海、南京、沧州、保定、南口、忻口、临汾诸役，击破者多，俘获者少，表现其指挥的笨拙。这五个——逐渐增加兵力，没有主攻方向，没有战略协同，失去时机，包围多歼灭少，是台儿庄战役以前日本指挥的不行之点。台儿庄战役以后，虽已改了一些，然根据其兵力不足和内部矛盾诸因素，求不重犯错误是不可能的。且得之于此者，又失之于彼。例如，将华北兵力集中于徐州，华北占领地就出了大空隙，给予游击战争以放手发展的机会。以上是敌人自己弄错，不是我们使之错的。我们方面，尚可有意地制造敌之错误，即用自己聪明而有效的动作，在有组织的民众掩护之下，造成敌人错觉，调动敌人就我范围，例如声东击西之类，这件事的可能性前面已经说过了。所有这些，都说明：我之战争胜利又可在敌之指挥上面找到某种根源。虽然我们不应把这点作为我之战略计划的重要基础，相反，我之计划宁可放在敌人少犯错误的假定上，才是可靠的做法。而且我乘敌隙，敌也可以乘我之隙，少授敌以可寻之隙，又是我们指挥方面的任务。然而敌之指挥错误，是事实上已经存在过，并且还要发生的，又可因我之努力制造出来的，都足供我之利用，抗日将军们应该极力地捉住它。敌人的战略战役指挥许多不行，但其战斗指挥，即部队战术和小兵团战术，却颇有高明之处，这一点我们应该向他学习。","language":"中文","translation":false},{"id":"protracted-war-1-131","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○六）抗日战争中的决战问题应分为三类：一切有把握的战役和战斗应坚决地进行决战，一切无把握的战役和战斗应避免决战，赌国家命运的战略决战应根本避免。抗日战争不同于其它许多战争的特点，又表现在这个决战问题上。在第一第二阶段，敌强我弱，敌之要求在于我集中主力与之决战。我之要求则相反，在选择有利条件，集中优势兵力，与之作有把握的战役和战斗上的决战，例如平型关、台儿庄以及许多的其它战斗；而避免在不利条件下的无把握的决战，例如彰德等地战役所采的方针。拚国家命运的战略的决战则根本不干，例如最近之徐州撤退。这样就破坏了敌之“速决”计划，不得不跟了我们干持久战。这种方针，在领土狭小的国家是做不到的，在政治太落后了的国家也难做到。我们是大国，又处进步时代，这点是可以做到的。如果避免了战略的决战，“留得青山在，不愁没柴烧”，虽然丧失若干土地，还有广大的回旋余地，可以促进并等候国内的进步、国际的增援和敌人的内溃，这是抗日战争的上策。急性病的速胜论者熬不过持久战的艰难路程，企图速胜，一到形势稍为好转，就吹起了战略决战的声浪，如果照了干去，整个的抗战要吃大亏，持久战为之葬送，恰恰中了敌人的毒计，实在是下策。不决战就须放弃土地，这是没有疑问的，在无可避免的情况下（也仅仅是在这种情况下），只好勇敢地放弃。情况到了这种时候，丝毫也不应留恋，这是以土地换时间的正确的政策。历史上，俄国以避免决战，执行了勇敢的退却，战胜了威震一时的拿破仑[41]。中国现在也应这样干。","language":"中文","translation":false},{"id":"protracted-war-1-132","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○七）不怕人家骂“不抵抗”吗？不怕的。根本不战，与敌妥协，这是不抵抗主义，不但应该骂，而且完全不许可的。坚决抗战，但为避开敌人毒计，不使我军主力丧于敌人一击之下，影响到抗战的继续，一句话，避免亡国，是完全必需的。在这上面发生怀疑，是战争问题上的近视眼，结果一定和亡国论者走到一伙去。我们曾经批评了所谓“有进无退”的拚命主义，就是因为这种拚命主义如果成为一般的风气，其结果就有使抗战不能继续，最后引向亡国的危险。","language":"中文","translation":false},{"id":"protracted-war-1-133","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○八）我们主张一切有利条件下的决战，不论是战斗的和大小战役的，在这上面不容许任何的消极。给敌以歼灭和给敌以消耗，只有这种决战才能达到目的，每个抗日军人均须坚决地去做。为此目的，部分的相当大量的牺牲是必要的，避免任何牺牲的观点是懦夫和恐日病患者的观点，必须给以坚决的反对。李服膺、韩复榘等逃跑主义者的被杀，是杀得对的。在战争中提倡勇敢牺牲英勇向前的精神和动作，是在正确的作战计划下绝对必要的东西，是同持久战和最后胜利不能分离的。我们曾经严厉地指斥了所谓“有退无进”的逃跑主义，拥护严格纪律的执行，就是因为只有这种在正确计划下的英勇决战，才能战胜强敌；而逃跑主义，则是亡国论的直接支持者。","language":"中文","translation":false},{"id":"protracted-war-1-134","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一○九）英勇战斗于前，又放弃土地于后，不是自相矛盾吗？这些英勇战斗者的血，不是白流了吗？这是非常不妥当的发问。吃饭于前，又拉屎于后，不是白吃了吗？睡觉于前，又起床于后，不是白睡了吗？可不可以这样提出问题呢？我想是不可以的。吃饭就一直吃下去，睡觉就一直睡下去，英勇战斗就一直打到鸭绿江，这是主观主义和形式主义的幻想，在实际生活里是不存在的。谁人不知，为争取时间和准备反攻而流血战斗，某些土地虽仍不免于放弃，时间却争取了，给敌以歼灭和给敌以消耗的目的却达到了，自己的战斗经验却取得了，没有起来的人民却起来了，国际地位却增长了。这种血是白流的吗？一点也不是白流的。放弃土地是为了保存军力，也正是为了保存土地；因为如不在不利条件下放弃部分的土地，盲目地举行绝无把握的决战，结果丧失军力之后，必随之以丧失全部的土地，更说不到什么恢复失地了。资本家做生意要有本钱，全部破产之后，就不算什么资本家。赌汉也要赌本，孤注一掷，不幸不中，就无从再赌。事物是往返曲折的，不是径情直遂的，战争也是一样，只有形式主义者想不通这个道理。","language":"中文","translation":false},{"id":"protracted-war-1-135","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一○）我想，即在战略反攻阶段的决战亦然。那时虽然敌处劣势，我处优势，然而仍适用“执行有利决战，避免不利决战”的原则，直至打到鸭绿江边，都是如此。这样，我可始终立于主动，一切敌人的“挑战书”，旁人的“激将法”，都应束之高阁，置之不理，丝毫也不为其所动。抗日将军们要有这样的坚定性，才算是勇敢而明智的将军。那些“一触即跳”的人们，是不足以语此的。第一阶段我处于某种程度的战略被动，然在一切战役上也应是主动的，尔后任何阶段都应是主动。我们是持久论和最后胜利论者，不是赌汉们那样的孤注一掷论者。","language":"中文","translation":false},{"id":"protracted-war-1-136","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一一）日本帝国主义处在革命的中国面前，是决不放松其进攻和镇压的，它的帝国主义本质规定了这一点。中国不抵抗，日本就不费一弹安然占领中国，东四省的丧失，就是前例。中国若抵抗，日本就向着这种抵抗力压迫，直至它的压力无法超过中国的抵抗力才停止，这是必然的规律。日本地主资产阶级的野心是很大的，为了南攻南洋群岛，北攻西伯利亚起见，采取中间突破的方针，先打中国。那些认为日本将在占领华北、江浙一带以后适可而止的人，完全没有看到发展到了新阶段迫近了死亡界线的日本帝国主义，已经和历史上的日本不相同了。我们说，日本的出兵数和进攻点有一定的限制，是说：在日本一方面，在其力量基础上，为了还要举行别方面的进攻并防御另一方面的敌人，只能拿出一定程度的力量打中国打到它力所能及的限度为止；在中国一方面，又表现了自己的进步和顽强的抵抗力，不能设想只有日本猛攻，中国没有必要的抵抗力。日本不能占领全中国，然而在它一切力所能及的地区，它将不遗余力地镇压中国的反抗，直至日本的内外条件使日本帝国主义发生了进入坟墓的直接危机之前，它是不会停止这种镇压的。日本国内的政治只有两个出路：或者整个当权阶级迅速崩溃，政权交给人民，战争因而结束，但暂时无此可能；或者地主资产阶级日益法西斯化，把战争支持到自己崩溃的一天，日本走的正是这条路。除此没有第三条路。那些希望日本资产阶级中和派出来停止战争的，仅仅是一种幻想而已。日本的资产阶级中和派，已经作了地主和金融寡头的俘虏，这是多年来日本政治的实际。日本打了中国之后，如果中国的抗战还没有给日本以致命的打击，日本还有足够力量的话，它一定还要打南洋或西伯利亚，甚或两处都打。欧洲战争一起来，它就会干这一手；日本统治者的如意算盘是打得非常之大的。当然存在这种可能：由于苏联的强大，由于日本在中国战争中的大大削弱，它不得不停止进攻西伯利亚的原来计划，而对之采取根本的守势。然而在出现了这种情形之时，不是日本进攻中国的放松，反而是它进攻中国的加紧，因为那时它只剩下了向弱者吞剥的一条路。那时中国的坚持抗战、坚持统一战线和坚持持久战的任务，就更加显得严重，更加不能丝毫懈气。","language":"中文","translation":false},{"id":"protracted-war-1-137","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一二）在这种情况下，中国制胜日本的主要条件，是全国的团结和各方面较之过去有十百倍的进步。中国已处于进步的时代，并已有了伟大的团结，但是目前的程度还非常之不够。日本占地如此之广，一方面由于日本之强，一方面则由于中国之弱；而这种弱，完全是百年来尤其是近十年来各种历史错误积累下来的结果，使得中国的进步因素限制在今天的状态。现在要战胜这样一个强敌，非有长期的广大的努力是不可能的。应该努力的事情很多，我这里只说最根本的两方面：军队和人民的进步。","language":"中文","translation":false},{"id":"protracted-war-1-138","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一三）革新军制离不了现代化，把技术条件增强起来，没有这一点，是不能把敌人赶过鸭绿江的。军队的使用需要进步的灵活的战略战术，没有这一点，也是不能胜利的。然而军队的基础在士兵，没有进步的政治精神贯注于军队之中，没有进步的政治工作去执行这种贯注，就不能达到真正的官长和士兵的一致，就不能激发官兵最大限度的抗战热忱，一切技术和战术就不能得着最好的基础去发挥它们应有的效力。我们说日本技术条件虽优，但它终必失败，除了我们给以歼灭和消耗的打击外，就是它的军心终必随着我们的打击而动摇，武器和兵员结合不稳。我们相反，抗日战争的政治目的是官兵一致的。在这上面，就有了一切抗日军队的政治工作的基础。军队应实行一定限度的民主化，主要地是废除封建主义的打骂制度和官兵生活同甘苦。这样一来，官兵一致的目的就达到了，军队就增加了绝大的战斗力，长期的残酷的战争就不患不能支持。","language":"中文","translation":false},{"id":"protracted-war-1-139","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一四）战争的伟力之最深厚的根源，存在于民众之中。日本敢于欺负我们，主要的原因在于中国民众的无组织状态。克服了这一缺点，就把日本侵略者置于我们数万万站起来了的人民之前，使它像一匹野牛冲入火阵，我们一声唤也要把它吓一大跳，这匹野牛就非烧死不可。我们方面，军队须有源源不绝的补充，现在下面胡干的“捉兵法”、“买兵法”[42]，亟须禁止，改为广泛的热烈的政治动员，这样，要几百万人当兵都是容易的。抗日的财源十分困难，动员了民众，则财政也不成问题，岂有如此广土众民的国家而患财穷之理？军队须和民众打成一片，使军队在民众眼睛中看成是自己的军队，这个军队便无敌于天下，个把日本帝国主义是不够打的。","language":"中文","translation":false},{"id":"protracted-war-1-140","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一五）很多人对于官兵关系、军民关系弄不好，以为是方法不对，我总告诉他们是根本态度（或根本宗旨）问题，这态度就是尊重士兵和尊重人民。从这态度出发，于是有各种的政策、方法、方式。离了这态度，政策、方法、方式也一定是错的，官兵之间、军民之间的关系便决然弄不好。军队政治工作的三大原则：第一是官兵一致，第二是军民一致，第三是瓦解敌军。这些原则要实行有效，都须从尊重士兵、尊重人民和尊重已经放下武器的敌军俘虏的人格这种根本态度出发。那些认为不是根本态度问题而是技术问题的人，实在是想错了，应该加以改正才对。","language":"中文","translation":false},{"id":"protracted-war-1-141","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一六）当此保卫武汉等地成为紧急任务之时，发动全军全民的全部积极性来支持战争，是十分严重的任务。保卫武汉等地的任务，毫无疑义必须认真地提出和执行。然而究竟能否确定地保卫不失，不决定于主观的愿望，而决定于具体的条件。政治上动员全军全民起来奋斗，是最重要的具体的条件之一。不努力于争取一切必要的条件，甚至必要条件有一不备，势必重蹈南京等地失陷之覆辙。中国的马德里在什么地方，看什么地方具备马德里的条件。过去是没有过一个马德里的，今后应该争取几个，然而全看条件如何。条件中的最基本条件，是全军全民的广大的政治动员。","language":"中文","translation":false},{"id":"protracted-war-1-142","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一七）在一切工作中，应该坚持抗日民族统一战线的总方针。因为只有这种方针才能坚持抗战，坚持持久战，才能普遍地深入地改善官兵关系、军民关系，才能发动全军全民的全部积极性，为保卫一切未失地区、恢复一切已失地区而战，才能争取最后胜利。","language":"中文","translation":false},{"id":"protracted-war-1-143","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一八）这个政治上动员军民的问题，实在太重要了。我们之所以不惜反反复复地说到这一点，实在是没有这一点就没有胜利。没有许多别的必要的东西固然也没有胜利，然而这是胜利的最基本的条件。抗日民族统一战线是全军全民的统一战线，决不仅仅是几个党派的党部和党员们的统一战线；动员全军全民参加统一战线，才是发起抗日民族统一战线的根本目的。","language":"中文","translation":false},{"id":"protracted-war-1-144","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一一九）结论是什么呢？结论就是：“在什么条件下，中国能战胜并消灭日本帝国主义的实力呢？要有三个条件：第一是中国抗日统一战线的完成；第二是国际抗日统一战线的完成；第三是日本国内人民和日本殖民地人民的革命运动的兴起。就中国人民的立场来说，三个条件中，中国人民的大联合是主要的。”“这个战争要延长多久呢？要看中国抗日统一战线的实力和中日两国其它许多决定的因素如何而定。”“如果这些条件不能很快实现，战争就要延长。但结果还是一样，日本必败，中国必胜。只是牺牲会大，要经过一个很痛苦的时期。”“我们的战略方针，应该是使用我们的主力在很长的变动不定的战线上作战。中国军队要胜利，必须在广阔的战场上进行高度的运动战。”“除了调动有训练的军队进行运动战之外，还要在农民中组织很多的游击队。”“在战争的过程中……使中国军队的装备逐渐加强起来。因此，中国能够在战争的后期从事阵地战，对于日本的占领地进行阵地的攻击。这样，日本在中国抗战的长期消耗下，它的经济行将崩溃；在无数战争的消磨中，它的士气行将颓靡。中国方面，则抗战的潜伏力一天一天地奔腾高涨，大批的革命民众不断地倾注到前线去，为自由而战争。所有这些因素和其它的因素配合起来，就使我们能够对日本占领地的堡垒和根据地，作最后的致命的攻击，驱逐日本侵略军出中国。”（一九三六年七月与斯诺谈话）“中国的政治形势从此开始了一个新阶段，……这一阶段的最中心的任务是：动员一切力量争取抗战的胜利。”“争取抗战胜利的中心关键，在使已经发动的抗战发展为全面的全民族的抗战。只有这种全面的全民族的抗战，才能使抗战得到最后的胜利。”“由于当前的抗战还存在着严重的弱点，所以在今后的抗战过程中，可能发生许多挫败、退却，内部的分化、叛变，暂时和局部的妥协等不利的情况。因此，应该看到这一抗战是艰苦的持久战。但我们相信，已经发动的抗战，必将因为我党和全国人民的努力，冲破一切障碍物而继续地前进和发展。”（一九三七年八月《中共中央关于目前形势与党的任务的决定》）这些就是结论。亡国论者看敌人如神物，看自己如草芥，速胜论者看敌人如草芥，看自己如神物，这些都是错误的。我们的意见相反：抗日战争是持久战，最后胜利是中国的——这就是我们的结论。","language":"中文","translation":false},{"id":"protracted-war-1-145","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"（一二○）我的讲演至此为止。伟大的抗日战争正在开展，很多人希望总结经验，以便争取全部的胜利。我所说的，只是十个月经验中的一般的东西，也算一个总结吧。这个问题值得引起广大的注意和讨论，我所说的只是一个概论，希望诸位研究讨论，给以指正和补充。","language":"中文","translation":false},{"id":"protracted-war-1-146","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[1] 见本卷《反对日本进攻的方针、办法和前途》注〔1〕。","language":"中文","translation":false},{"id":"protracted-war-1-147","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[2] 见本书第一卷《中国革命战争的战略问题》注〔45〕。","language":"中文","translation":false},{"id":"protracted-war-1-148","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[3] 这种亡国论是国民党内部分领导人的意见。他们是不愿意抗日的，后来抗日是被迫的。卢沟桥事变以后，蒋介石一派参加抗日了，汪精卫一派就代表了亡国论，并准备投降日本，后来果然投降了。但是亡国论思想不但是在国民党内存在着，在某些中层社会中甚至在一部分落后的劳动人民中也曾经发生影响。这是因为国民党政府腐败无能，在抗日战争中节节失败，而日军则长驱直进，在战争的第一年中就侵占了华北和华中的大片土地，因而在一部分落后的人民中产生了严重的悲观情绪。","language":"中文","translation":false},{"id":"protracted-war-1-149","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[4] 以上这些意见，都是共产党内的。在抗日战争的头半年内，党内存在着一种轻敌的倾向，认为日本不值一打。其根据并不是因为他们感觉自己的力量很大，他们知道共产党领导的军队和民众的有组织的力量在当时还是很小的；而是因为国民党抗日了，他们感觉国民党有很大的力量，可以有效地打击日本。他们只看见国民党暂时抗日的一面，忘记了国民党反动和腐败的一面，因而造成了错误的估计。","language":"中文","translation":false},{"id":"protracted-war-1-150","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[5] 这是蒋介石等人的意见。蒋介石国民党既已被迫抗战，他们就一心希望外国的迅速援助，不相信自己的力量，更不相信人民的力量。","language":"中文","translation":false},{"id":"protracted-war-1-151","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[6] 一九三八年三月下旬至四月上旬，中国军队和日本侵略军在台儿庄（今属山东省枣庄市）一带进行过一次会战。在这次会战中，中国军队击败日军第五、第十两个精锐师团，取得了会战的胜利。","language":"中文","translation":false},{"id":"protracted-war-1-152","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[7] 徐州战役是中国军队同日本侵略军在以徐州为中心的广大地区进行的一次战役。从一九三七年十二月起，华北、华中的日军分南北两线沿津浦铁路和台潍（台儿庄至潍县）公路进犯徐州外围地区。一九三八年四月上旬，中国军队在取得台儿庄会战的胜利后，继续向鲁南增兵，在徐州附近集结了约六十万的兵力；而日军在台儿庄遭到挫败以后，从四月上旬开始调集南北两线兵力二十多万人，对徐州进行迂回包围。中国军队在日军夹击和包围下，分路向豫皖边突围。五月十九日，徐州被日军占领。","language":"中文","translation":false},{"id":"protracted-war-1-153","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[8] 这是当时《大公报》在一九三八年四月二十五日和二十六日社评中提出的意见。他们从一种侥幸心理出发，希望用几个台儿庄一类的胜仗就能打败日本，免得在持久战中动员人民力量，危及自己阶级的安全。当时国民党统治集团内普遍有这种侥幸心理。","language":"中文","translation":false},{"id":"protracted-war-1-154","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[9] 参见本书第一卷《论反对日本帝国主义的策略》注〔33〕。抗日战争时期，托派在宣传上主张抗日，但是攻击中国共产党的抗日民族统一战线政策。把托派与汉奸相提并论，是由于当时在共产国际内流行着中国托派与日本帝国主义间谍组织有关的错误论断所造成的。","language":"中文","translation":false},{"id":"protracted-war-1-155","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[10] 见本书第一卷《论反对日本帝国主义的策略》注〔35〕。","language":"中文","translation":false},{"id":"protracted-war-1-156","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[11] 见本书第一卷《论反对日本帝国主义的策略》注〔36〕。","language":"中文","translation":false},{"id":"protracted-war-1-157","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[12] 戊戌维新也称戊戌变法，是一八九八年（戊戌年）发生的维新运动。当时，中国面临被帝国主义列强瓜分的严重危机。康有为、梁启超、谭嗣同等人，在清朝光绪皇帝的支持下，企图通过自上而下的变法维新，逐步地在中国推行地主阶级和资产阶级联合统治的君主立宪制度，发展民族资本主义，以挽救民族危亡。但是，这个运动缺乏人民群众的基础，又遭到以慈禧太后为首的顽固派的坚决反对。变法三个多月以后，慈禧太后发动政变，幽禁光绪皇帝，杀害谭嗣同等六人，变法遭到失败。","language":"中文","translation":false},{"id":"protracted-war-1-158","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[13] 见本书第一卷《湖南农民运动考察报告》注〔3〕。","language":"中文","translation":false},{"id":"protracted-war-1-159","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[14] 一九三八年一月十六日，日本近卫内阁发表声明，宣布以武力灭亡中国的方针；同时宣称由于国民党政府仍在“策划抗战”，日本政府决定在中国扶植新的傀儡政权，“今后将不以国民政府为对手”。","language":"中文","translation":false},{"id":"protracted-war-1-160","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[15] 这里主要是指美国。自一九三七年到一九四○年，美国每年输入日本的物资占日本全部进口额的三分之一以上，其中战争物资占一半以上。","language":"中文","translation":false},{"id":"protracted-war-1-161","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[16] 指英、美、法等帝国主义国家的政府。","language":"中文","translation":false},{"id":"protracted-war-1-162","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[17] 张伯伦（一八六九——一九四○），英国保守党领袖。一九三七年至一九四○年任英国首相。他主张迁就德、意、日法西斯对中国、埃塞俄比亚、西班牙、奥地利和捷克斯洛伐克等国家的侵略，实行妥协政策。","language":"中文","translation":false},{"id":"protracted-war-1-163","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[18] 毛泽东在这里所预言的抗日战争相持阶段中中国方面可能的向上变化，在中国共产党领导下的抗日根据地是完全实现了。在国民党统治区，则因为以蒋介石为首的统治集团消极抗日、积极反共反人民，不但没有向上变化，反而向下变化了。因为这样，也激起了广大人民的反抗和觉悟。参见本书第三卷《论联合政府》第三部分关于这一切事实的分析。","language":"中文","translation":false},{"id":"protracted-war-1-164","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[19] 这个比喻里所引用的神话故事，见明朝吴承恩所著的《西游记》第七回。这个神话故事说，孙悟空本是个猴子，他能够一个筋斗翻十万八千里，但是，他站在如来佛的手心上尽力翻筋斗，总是翻不出去。如来佛翻掌一扑，将五个手指化作五行山，把他压住。","language":"中文","translation":false},{"id":"protracted-war-1-165","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[20] 一九三五年八月，季米特洛夫在共产国际第七次代表大会上所作的报告中说：“法西斯是肆无忌惮的沙文主义和侵略战争。”一九三七年七月，他又发表了题为《法西斯主义就是战争》的论文。","language":"中文","translation":false},{"id":"protracted-war-1-166","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[21] 参见列宁《第二国际的破产》和《社会主义与战争》（《列宁全集》第26卷，人民出版社1988年版，第235、327页）。","language":"中文","translation":false},{"id":"protracted-war-1-167","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[22] 见本卷《为动员一切力量争取抗战胜利而斗争》。","language":"中文","translation":false},{"id":"protracted-war-1-168","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[23] 见本卷《陕甘宁边区政府、第八路军后方留守处布告》注〔3〕。","language":"中文","translation":false},{"id":"protracted-war-1-169","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[24] 见《孙子•谋攻》。","language":"中文","translation":false},{"id":"protracted-war-1-170","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[25] 城濮在今山东省鄄城县西南。公元前六三二年，晋楚两国大战于此。战争开始时，楚军占优势。晋军退却九十里，到达城濮一带，先选择楚军力量薄弱的右翼，给以严重的打击。然后，再集中优势兵力击溃了楚军的左翼。楚军终于大败而退。","language":"中文","translation":false},{"id":"protracted-war-1-171","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[26] 见本书第一卷《中国革命战争的战略问题》注〔31〕。","language":"中文","translation":false},{"id":"protracted-war-1-172","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[27] 公元前二○四年，汉将韩信率部与赵王歇大战于井陉（在今河北省井陉县）。赵军号称二十万，数倍于汉军。韩信背水为阵，率军奋战；同时，遣兵袭占赵军防御薄弱的后方，使其腹背受敌，遂大破赵军。","language":"中文","translation":false},{"id":"protracted-war-1-173","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[28] 见本书第一卷《中国革命战争的战略问题》注〔32〕。","language":"中文","translation":false},{"id":"protracted-war-1-174","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[29] 见本书第一卷《中国革命战争的战略问题》注〔33〕。","language":"中文","translation":false},{"id":"protracted-war-1-175","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[30] 见本书第一卷《中国革命战争的战略问题》注〔34〕。","language":"中文","translation":false},{"id":"protracted-war-1-176","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[31] 见本书第一卷《中国革命战争的战略问题》注〔35〕。","language":"中文","translation":false},{"id":"protracted-war-1-177","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":177,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[32] 见本书第一卷《中国革命战争的战略问题》注〔36〕。","language":"中文","translation":false},{"id":"protracted-war-1-178","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":178,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[33] 十八世纪末十九世纪初，法国的拿破仑曾与英、普、奥、俄以及欧洲其它很多国家作战。在多次战争中，拿破仑的部队在数量上都不如他的敌人，但都得到了胜利。","language":"中文","translation":false},{"id":"protracted-war-1-179","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":179,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[34] 公元三八三年，秦王苻坚出兵攻晋。他依仗优势兵力，非常轻视晋军。晋军打败了秦军的前锋，从水陆两路继续前进，隔淝水同秦军对峙。苻坚登寿阳城（今安徽省寿县）瞭望，见晋兵布阵严整，又望见八公山上的草木，以为都是晋兵，觉得是遇到了劲敌，开始有惧色。随后在淝水决战中，强大的秦军终于被晋军打败。","language":"中文","translation":false},{"id":"protracted-war-1-180","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":180,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[35] 蒋介石、汪精卫等在一九二七年背叛革命以后，进行十年的反人民战争，同时又在国民党统治区实行法西斯统治。这就使得中国人民没有可能广泛地组织起来。这个历史错误是应该由蒋介石为首的国民党反动派负责的。","language":"中文","translation":false},{"id":"protracted-war-1-181","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":181,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[36] 宋襄公是公元前七世纪春秋时代宋国的国君。公元前六三八年宋国与强大的楚国作战，宋兵已经排列成阵，楚兵正在渡河。宋国有一个官员认为楚兵多宋兵少，主张利用楚兵渡河未毕的时机出击。但宋襄公说：不可，因为君子不乘别人困难的时候去攻打人家。楚兵渡河以后，还未排列成阵，宋国官员又请求出击。宋襄公又说：不可，因为君子不攻击不成阵势的队伍。一直等到楚兵准备好了以后，宋襄公才下令出击。结果宋国大败，宋襄公自己也受了伤。","language":"中文","translation":false},{"id":"protracted-war-1-182","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":182,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[37] 见《宋史•岳飞传》。","language":"中文","translation":false},{"id":"protracted-war-1-183","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":183,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[38] 见《礼记•中庸》。","language":"中文","translation":false},{"id":"protracted-war-1-184","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":184,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[39] 一九三七年日本侵略军在占领北平、天津以后，不久即分兵沿津浦铁路南下，进攻山东省。多年统治山东的国民党军阀韩复榘不战而逃。在一九三七年十二月下旬至一九三八年一月上旬的十多天里，他就放弃了山东中部和西南部的大片国土，从济南一直逃到山东、河南的边境。","language":"中文","translation":false},{"id":"protracted-war-1-185","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":185,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[40] 见本书第一卷《论反对日本帝国主义的策略》注〔5〕。","language":"中文","translation":false},{"id":"protracted-war-1-186","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":186,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[41] 一八一二年，拿破仑以五十万大军进攻俄国。当时俄军只有二十万人左右。为了避免不利于自己的决战，俄军实行战略退却，一直到放弃和焚毁了莫斯科。拿破仑的军队在深入俄国国土以后，遭到了俄国广大军民的坚决反抗，陷于饥寒困苦、后路被切断、四面被包围的绝境，最后不得不从莫斯科撤退。这时，俄军乘机大举反攻，拿破仑军仅剩二万余人逃离俄国国境。","language":"中文","translation":false},{"id":"protracted-war-1-187","author":"毛泽东","title":"论持久战","location":"论持久战（一九三八年五月）","page":1,"paragraph":187,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-193805b.htm","text":"[42] 国民党政府扩军的一种办法，是派军警四处捉拿人民去当兵，捉来的兵用绳捆索绑，形同囚犯。略为有钱的人，就向国民党政府的官吏行贿，出钱买人代替。","language":"中文","translation":false},{"id":"new-democracy-1-1","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中文马克思主义文库 -> 毛泽东","language":"中文","translation":false},{"id":"new-democracy-1-2","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"* 这是毛泽东一九四○年一月九日在陕甘宁边区文化协会第一次代表大会上的讲演，原题为《新民主主义的政治与新民主主义的文化》，载于一九四○年二月十五日延安出版的《中国文化》创刊号。同年二月二十日在延安出版的《解放》第九十八、九十九期合刊登载时，题目改为《新民主主义论》。","language":"中文","translation":false},{"id":"new-democracy-1-3","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"抗战以来，全国人民有一种欣欣向荣的气象，大家以为有了出路，愁眉锁眼的姿态为之一扫。但是近来的妥协空气，反共声浪，忽又甚嚣尘上，又把全国人民打入闷葫芦里了。特别是文化人和青年学生，感觉锐敏，首当其冲。于是怎么办，中国向何处去，又成为问题了。因此，趁着《中国文化》[1]的出版，说明一下中国政治和中国文化的动向问题，或者也是有益的。对于文化问题，我是门外汉，想研究一下，也方在开始。好在延安许多同志已有详尽的文章，我的粗枝大叶的东西，就当作一番开台锣鼓好了。对于全国先进的文化工作者，我们的东西，只当作引玉之砖，千虑之一得，希望共同讨论，得出正确结论，来适应我们民族的需要。科学的态度是“实事求是”，“自以为是”和“好为人师”那样狂妄的态度是决不能解决问题的。我们民族的灾难深重极了，惟有科学的态度和负责的精神，能够引导我们民族到解放之路。真理只有一个，而究竟谁发现了真理，不依靠主观的夸张，而依靠客观的实践。只有千百万人民的革命实践，才是检验真理的尺度。我想，这可以算作《中国文化》出版的态度。","language":"中文","translation":false},{"id":"new-democracy-1-4","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"二 我们要建立一个新中国","language":"中文","translation":false},{"id":"new-democracy-1-5","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"我们共产党人，多年以来，不但为中国的政治革命和经济革命而奋斗，而且为中国的文化革命而奋斗；一切这些的目的，在于建设一个中华民族的新社会和新国家。在这个新社会和新国家中，不但有新政治、新经济，而且有新文化。这就是说，我们不但要把一个政治上受压迫、经济上受剥削的中国，变为一个政治上自由和经济上繁荣的中国，而且要把一个被旧文化统治因而愚昧落后的中国，变为一个被新文化统治因而文明先进的中国。一句话，我们要建立一个新中国。建立中华民族的新文化，这就是我们在文化领域中的目的。","language":"中文","translation":false},{"id":"new-democracy-1-6","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"我们要建立中华民族的新文化，但是这种新文化究竟是一种什么样子的文化呢？","language":"中文","translation":false},{"id":"new-democracy-1-7","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一定的文化（当作观念形态的文化）是一定社会的政治和经济的反映，又给予伟大影响和作用于一定社会的政治和经济；而经济是基础，政治则是经济的集中的表现[2]。这是我们对于文化和政治、经济的关系及政治和经济的关系的基本观点。那末，一定形态的政治和经济是首先决定那一定形态的文化的；然后，那一定形态的文化又才给予影响和作用于一定形态的政治和经济。马克思说：“不是人们的意识决定人们的存在，而是人们的社会存在决定人们的意识。”[3]他又说：“从来的哲学家只是各式各样地说明世界，但是重要的乃在于改造世界。”[4]这是自有人类历史以来第一次正确地解决意识和存在关系问题的科学的规定，而为后来列宁所深刻地发挥了的能动的革命的反映论之基本的观点。我们讨论中国文化问题，不能忘记这个基本观点。","language":"中文","translation":false},{"id":"new-democracy-1-8","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这样说来，问题是很清楚的，我们要革除的那种中华民族旧文化中的反动成分，它是不能离开中华民族的旧政治和旧经济的；而我们要建立的这种中华民族的新文化，它也不能离开中华民族的新政治和新经济。中华民族的旧政治和旧经济，乃是中华民族的旧文化的根据；而中华民族的新政治和新经济，乃是中华民族的新文化的根据。","language":"中文","translation":false},{"id":"new-democracy-1-9","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"所谓中华民族的旧政治和旧经济是什么？而所谓中华民族的旧文化又是什么？","language":"中文","translation":false},{"id":"new-democracy-1-10","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"自周秦以来，中国是一个封建社会，其政治是封建的政治，其经济是封建的经济。而为这种政治和经济之反映的占统治地位的文化，则是封建的文化。","language":"中文","translation":false},{"id":"new-democracy-1-11","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"自外国资本主义侵略中国，中国社会又逐渐地生长了资本主义因素以来，中国已逐渐地变成了一个殖民地、半殖民地、半封建的社会。现在的中国，在日本占领区，是殖民地社会；在国民党统治区，基本上也还是一个半殖民地社会；而不论在日本占领区和国民党统治区，都是封建半封建制度占优势的社会。这就是现时中国社会的性质，这就是现时中国的国情。作为统治的东西来说，这种社会的政治是殖民地、半殖民地、半封建的政治，其经济是殖民地、半殖民地、半封建的经济，而为这种政治和经济之反映的占统治地位的文化，则是殖民地、半殖民地、半封建的文化。","language":"中文","translation":false},{"id":"new-democracy-1-12","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这些统治的政治、经济和文化形态，就是我们革命的对象。我们要革除的，就是这种殖民地、半殖民地、半封建的旧政治、旧经济和那为这种旧政治、旧经济服务的旧文化。而我们要建立起来的，则是与此相反的东西，乃是中华民族的新政治、新经济和新文化。","language":"中文","translation":false},{"id":"new-democracy-1-13","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"那末，什么是中华民族的新政治、新经济，又什么是中华民族的新文化呢？","language":"中文","translation":false},{"id":"new-democracy-1-14","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中国革命的历史进程，必须分为两步，其第一步是民主主义的革命，其第二步是社会主义的革命，这是性质不同的两个革命过程。而所谓民主主义，现在已不是旧范畴的民主主义，已不是旧民主主义，而是新范畴的民主主义，而是新民主主义。","language":"中文","translation":false},{"id":"new-democracy-1-15","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"由此可以断言，所谓中华民族的新政治，就是新民主主义的政治；所谓中华民族的新经济，就是新民主主义的经济；所谓中华民族的新文化，就是新民主主义的文化。","language":"中文","translation":false},{"id":"new-democracy-1-16","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这就是现时中国革命的历史特点。在中国从事革命的一切党派，一切人们，谁不懂得这个历史特点，谁就不能指导这个革命和进行这个革命到胜利，谁就会被人民抛弃，变为向隅而泣的可怜虫。","language":"中文","translation":false},{"id":"new-democracy-1-17","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"四 中国革命是世界革命的一部分","language":"中文","translation":false},{"id":"new-democracy-1-18","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中国革命的历史特点是分为民主主义和社会主义两个步骤，而其第一步现在已不是一般的民主主义，而是中国式的、特殊的、新式的民主主义，而是新民主主义。那末，这个历史特点是怎样形成的呢？它是一百年来就有了的，还是后来才发生的呢？","language":"中文","translation":false},{"id":"new-democracy-1-19","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"只要研究一下中国的和世界的历史发展，就知道这个历史特点，并不是从鸦片战争[5]以来就有了的，而是在后来，在第一次帝国主义世界大战和俄国十月革命之后，才形成的。我们现在就来研究这个形成过程。","language":"中文","translation":false},{"id":"new-democracy-1-20","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"很清楚的，中国现时社会的性质，既然是殖民地、半殖民地、半封建的性质，它就决定了中国革命必须分为两个步骤。第一步，改变这个殖民地、半殖民地、半封建的社会形态，使之变成一个独立的民主主义的社会。第二步，使革命向前发展，建立一个社会主义的社会。中国现时的革命，是在走第一步。","language":"中文","translation":false},{"id":"new-democracy-1-21","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这个第一步的准备阶段，还是自从一八四○年鸦片战争以来，即中国社会开始由封建社会改变为半殖民地半封建社会以来，就开始了的。中经太平天国运动[6]、中法战争[7]、中日战争[8]、戊戌变法[9]、辛亥革命[10]、五四运动[11]、北伐战争、土地革命战争、直到今天的抗日战争，这样许多个别的阶段，费去了整整一百年工夫，从某一点上说来，都是实行这第一步，都是中国人民在不同的时间中和不同的程度上实行这第一步，实行反对帝国主义和封建势力，为了建立一个独立的民主主义的社会而斗争，为了完成第一个革命而斗争。而辛亥革命，则是在比较更完全的意义上开始了这个革命。这个革命，按其社会性质说来，是资产阶级民主主义的革命，不是无产阶级社会主义的革命。这个革命，现在还未完成，还须付与很大的气力，这是因为这个革命的敌人，直到现在，还是非常强大的缘故。孙中山先生说的“革命尚未成功，同志仍须努力”，就是指的这种资产阶级民主主义的革命。","language":"中文","translation":false},{"id":"new-democracy-1-22","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"然而中国资产阶级民主主义革命，自从一九一四年爆发第一次帝国主义世界大战和一九一七年俄国十月革命在地球六分之一的土地上建立了社会主义国家以来，起了一个变化。","language":"中文","translation":false},{"id":"new-democracy-1-23","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在这以前，中国资产阶级民主主义革命，是属于旧的世界资产阶级民主主义革命的范畴之内的，是属于旧的世界资产阶级民主主义革命的一部分。","language":"中文","translation":false},{"id":"new-democracy-1-24","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在这以后，中国资产阶级民主主义革命，却改变为属于新的资产阶级民主主义革命的范畴，而在革命的阵线上说来，则属于世界无产阶级社会主义革命的一部分了。","language":"中文","translation":false},{"id":"new-democracy-1-25","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"为什么呢？因为第一次帝国主义世界大战和第一次胜利的社会主义十月革命，改变了整个世界历史的方向，划分了整个世界历史的时代。","language":"中文","translation":false},{"id":"new-democracy-1-26","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在世界资本主义战线已在地球的一角（这一角占全世界六分之一的土地）崩溃，而在其余的角上又已经充分显露其腐朽性的时代，在这些尚存的资本主义部分非更加依赖殖民地半殖民地便不能过活的时代，在社会主义国家已经建立并宣布它愿意为了扶助一切殖民地半殖民地的解放运动而斗争的时代，在各个资本主义国家的无产阶级一天一天从社会帝国主义的社会民主党的影响下面解放出来并宣布他们赞助殖民地半殖民地解放运动的时代，在这种时代，任何殖民地半殖民地国家，如果发生了反对帝国主义，即反对国际资产阶级、反对国际资本主义的革命，它就不再是属于旧的世界资产阶级民主主义革命的范畴，而属于新的范畴了；它就不再是旧的资产阶级和资本主义的世界革命的一部分，而是新的世界革命的一部分，即无产阶级社会主义世界革命的一部分了。这种革命的殖民地半殖民地，已经不能当作世界资本主义反革命战线的同盟军，而改变为世界社会主义革命战线的同盟军了。","language":"中文","translation":false},{"id":"new-democracy-1-27","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种殖民地半殖民地革命的第一阶段，第一步，虽然按其社会性质，基本上依然还是资产阶级民主主义的，它的客观要求，是为资本主义的发展扫清道路；然而这种革命，已经不是旧的、被资产阶级领导的、以建立资本主义的社会和资产阶级专政的国家为目的的革命，而是新的、被无产阶级领导的、以在第一阶段上建立新民主主义的社会和建立各个革命阶级联合专政的国家为目的的革命。因此，这种革命又恰是为社会主义的发展扫清更广大的道路。这种革命，在其进行中，因为敌情和同盟军的变化，又分为若干的阶段，然而其基本性质是没有变化的。","language":"中文","translation":false},{"id":"new-democracy-1-28","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种革命，是彻底打击帝国主义的，因此它不为帝国主义所容许，而为帝国主义所反对。但是它却为社会主义所容许，而为社会主义的国家和社会主义的国际无产阶级所援助。","language":"中文","translation":false},{"id":"new-democracy-1-29","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"因此，这种革命，就不能不变成无产阶级社会主义世界革命的一部分。","language":"中文","translation":false},{"id":"new-democracy-1-30","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"“中国革命是世界革命的一部分”，这一正确的命题，还是在一九二四年至一九二七年的中国第一次大革命时期，就提出了的。这是中国共产党人提出，而为当时一切参加反帝反封建斗争的人们所赞成的。不过那时这一理论的意义还没有发挥，以致人们还只是模糊地认识这个问题。","language":"中文","translation":false},{"id":"new-democracy-1-31","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种“世界革命”，已不是旧的世界革命，旧的资产阶级世界革命早已完结了；而是新的世界革命，而是社会主义的世界革命。同样，这种“一部分”，已经不是旧的资产阶级革命的一部分，而是新的社会主义革命的一部分。这是一个绝大的变化，这是自有世界历史和中国历史以来无可比拟的大变化。","language":"中文","translation":false},{"id":"new-democracy-1-32","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中国共产党人提出的这一正确的命题，是根据斯大林的理论的。","language":"中文","translation":false},{"id":"new-democracy-1-33","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"斯大林还在一九一八年所作十月革命一周年纪念的论文时，就说道：","language":"中文","translation":false},{"id":"new-democracy-1-34","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"“十月革命的伟大的世界意义，主要的是：第一，它扩大了民族问题的范围，把它从欧洲反对民族压迫的斗争的局部问题，变为各被压迫民族、各殖民地及半殖民地从帝国主义之下解放出来的总问题；第二，它给这一解放开辟了广大的可能性和现实的道路，这就大大地促进了西方和东方的被压迫民族的解放事业，把他们吸引到胜利的反帝国主义斗争的巨流中去；第三，它从而在社会主义的西方和被奴役的东方之间架起了一道桥梁，建立了一条从西方无产者经过俄国革命到东方被压迫民族的新的反对世界帝国主义的革命战线。”[12]","language":"中文","translation":false},{"id":"new-democracy-1-35","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"从这篇文章以后，斯大林曾经多次地发挥了关于论述殖民地半殖民地的革命脱离了旧范畴，改变成了无产阶级社会主义革命一部分的理论。解释得最清楚明确的，是斯大林在一九二五年六月三十日发表的同当时南斯拉夫的民族主义者争论的文章。这篇文章载在张仲实译的《斯大林论民族问题》一书上面，题目叫做《再论民族问题》。其中有这么一段：","language":"中文","translation":false},{"id":"new-democracy-1-36","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"“舍米契引证了斯大林在一九一二年年底所著《马克思主义与民族问题》那本小册子中的一个地方。那里曾说：‘在上升的资本主义的条件之下，民族的斗争是资产阶级相互之间的斗争。’显然，他企图以此来暗示他给当前历史条件下的民族运动的社会意义所下的定义是正确的。然而，斯大林那本小册子是在帝国主义战争以前写的，那时候民族问题在马克思主义者看来还不是一个具有全世界意义的问题，那时候马克思主义者关于民族自决权的基本要求不是当作无产阶级革命的一部分，而是当作资产阶级民主革命的一部分。自那时候起，国际形势已经根本地改变了，战争和俄国十月革命已把民族问题从资产阶级民主革命的一部分变成了无产阶级社会主义革命的一部分了，——要是看不清这一点，那就未免太可笑了。列宁还在一九一六年十月间，就在他的《民族自决权讨论的总结》一文中说过，民族问题中关于民族自决权的基本点，已不再是一般民主运动的一部分，它已经变成一般无产阶级的、社会主义革命的一个构成部分了。列宁以及俄国共产主义的其它代表者关于民族问题的以后的一些著作，我就不用讲了。现在，当我们由于新的历史环境而进入于一个新的时代——无产阶级革命的时代，舍米契在这一切以后却引证斯大林在俄国资产阶级民主革命时期所写的那本小册子中的一个地方，这能有什么意义呢？它只能有这样一个意义，就是舍米契是离开时间和空间，不顾到活的历史环境来引证的，因而违反了辩证法的最基本的要求，没有考虑到在某一个历史环境下是正确的东西在另一个历史环境下就可以成为不正确的。”","language":"中文","translation":false},{"id":"new-democracy-1-37","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"由此可见，有两种世界革命，第一种是属于资产阶级和资本主义范畴的世界革命。这种世界革命的时期早已过去了，还在一九一四年第一次帝国主义世界大战爆发之时，尤其是在一九一七年俄国十月革命之时，就告终结了。从此以后，开始了第二种世界革命，即无产阶级的社会主义的世界革命。这种革命，以资本主义国家的无产阶级为主力军，以殖民地半殖民地的被压迫民族为同盟军。不管被压迫民族中间参加革命的阶级、党派或个人，是何种的阶级、党派或个人，又不管他们意识着这一点与否，他们主观上了解了这一点与否，只要他们反对帝国主义，他们的革命，就成了无产阶级社会主义世界革命的一部分，他们就成了无产阶级社会主义世界革命的同盟军。","language":"中文","translation":false},{"id":"new-democracy-1-38","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中国革命到了今天，它的意义更加增大了。在今天，是在由于资本主义的经济危机和政治危机已经一天一天把世界拖进第二次世界大战的时候；是在苏联已经到了由社会主义到共产主义的过渡期，有能力领导和援助全世界无产阶级和被压迫民族，反抗帝国主义战争，打击资本主义反动的时候；是在各资本主义国家的无产阶级正在准备打倒资本主义、实现社会主义的时候；是在中国无产阶级、农民阶级、知识分子和其它小资产阶级在中国共产党的领导之下，已经形成了一个伟大的独立的政治力量的时候。在今天，我们是处在这种时候，那末，应该不应该估计中国革命的世界意义是更加增大了呢？我想是应该的。中国革命是世界革命的伟大的一部分。","language":"中文","translation":false},{"id":"new-democracy-1-39","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这个中国革命的第一阶段（其中又分为许多小阶段），其社会性质是新式的资产阶级民主主义的革命，还不是无产阶级社会主义的革命，但早已成了无产阶级社会主义的世界革命的一部分，现在则更成了这种世界革命的伟大的一部分，成了这种世界革命的伟大的同盟军。这个革命的第一步、第一阶段，决不是也不能建立中国资产阶级专政的资本主义的社会，而是要建立以中国无产阶级为首领的中国各个革命阶级联合专政的新民主主义的社会，以完结其第一阶段。然后，再使之发展到第二阶段，以建立中国社会主义的社会。","language":"中文","translation":false},{"id":"new-democracy-1-40","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这就是现时中国革命的最基本的特点，这就是二十年来（从一九一九年五四运动算起）的新的革命过程，这就是现时中国革命的生动的具体的内容。","language":"中文","translation":false},{"id":"new-democracy-1-41","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中国革命分为两个历史阶段，而其第一阶段是新民主主义的革命，这是中国革命的新的历史特点。这个新的特点具体地表现在中国内部的政治关系和经济关系上又是怎样的呢？下面我们就来说明这种情形。","language":"中文","translation":false},{"id":"new-democracy-1-42","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在一九一九年五四运动以前（五四运动发生于一九一四年第一次帝国主义大战和一九一七年俄国十月革命之后），中国资产阶级民主革命的政治指导者是中国的小资产阶级和资产阶级（他们的知识分子）。这时，中国无产阶级还没有当作一个觉悟了的独立的阶级力量登上政治的舞台，还是当作小资产阶级和资产阶级的追随者参加了革命。例如辛亥革命时的无产阶级，就是这样的阶级。","language":"中文","translation":false},{"id":"new-democracy-1-43","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在五四运动以后，虽然中国民族资产阶级继续参加了革命，但是中国资产阶级民主革命的政治指导者，已经不是属于中国资产阶级，而是属于中国无产阶级了。这时，中国无产阶级，由于自己的长成和俄国革命的影响，已经迅速地变成了一个觉悟了的独立的政治力量了。打倒帝国主义的口号和整个中国资产阶级民主革命的彻底的纲领，是中国共产党提出的；而土地革命的实行，则是中国共产党单独进行的。","language":"中文","translation":false},{"id":"new-democracy-1-44","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"由于中国民族资产阶级是殖民地半殖民地国家的资产阶级，是受帝国主义压迫的，所以，虽然处在帝国主义时代，他们也还是在一定时期中和一定程度上，保存着反对外国帝国主义和反对本国官僚军阀政府（这后者，例如在辛亥革命时期和北伐战争时期）的革命性，可以同无产阶级、小资产阶级联合起来，反对它们所愿意反对的敌人。这是中国资产阶级和旧俄帝国的资产阶级的不同之点。在旧俄帝国，因为它已经是一个军事封建的帝国主义，是侵略别人的，所以俄国的资产阶级没有什么革命性。在那里，无产阶级的任务，是反对资产阶级，而不是联合它。在中国，因为它是殖民地半殖民地，是被人侵略的，所以中国民族资产阶级还有在一定时期中和一定程度上的革命性。在这里，无产阶级的任务，在于不忽视民族资产阶级的这种革命性，而和他们建立反帝国主义和反官僚军阀政府的统一战线。","language":"中文","translation":false},{"id":"new-democracy-1-45","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"但同时，也即是由于他们是殖民地半殖民地的资产阶级，他们在经济上和政治上是异常软弱的，他们又保存了另一种性质，即对于革命敌人的妥协性。中国的民族资产阶级，即使在革命时，也不愿意同帝国主义完全分裂，并且他们同农村中的地租剥削有密切联系，因此，他们就不愿和不能彻底推翻帝国主义，更加不愿和更加不能彻底推翻封建势力。这样，中国资产阶级民主革命的两个基本问题，两大基本任务，中国民族资产阶级都不能解决。至于中国的大资产阶级，以国民党为代表，在一九二七年至一九三七年这一个长的时期内，一直是投入帝国主义的怀抱，并和封建势力结成同盟，反对革命人民的。中国的民族资产阶级也曾在一九二七年及其以后的一个时期内一度附和过反革命。在抗日战争中，大资产阶级的一部分，以汪精卫[13]为代表，又已投降敌人，表示了大资产阶级的新的叛变。这又是中国资产阶级同历史上欧美各国的资产阶级特别是法国的资产阶级的不同之点。在欧美各国，特别在法国，当它们还在革命时代，那里的资产阶级革命是比较彻底的；在中国，资产阶级则连这点彻底性都没有。","language":"中文","translation":false},{"id":"new-democracy-1-46","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一方面——参加革命的可能性，又一方面——对革命敌人的妥协性，这就是中国资产阶级“一身而二任焉”的两面性。这种两面性，就是欧美历史上的资产阶级，也是同具的。大敌当前，他们要联合工农反对敌人；工农觉悟，他们又联合敌人反对工农。这是世界各国资产阶级的一般规律，不过中国资产阶级的这个特点更加突出罢了。","language":"中文","translation":false},{"id":"new-democracy-1-47","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在中国，事情非常明白，谁能领导人民推翻帝国主义和封建势力，谁就能取得人民的信仰，因为人民的死敌是帝国主义和封建势力、而特别是帝国主义的缘故。在今日，谁能领导人民驱逐日本帝国主义，并实施民主政治，谁就是人民的救星。历史已经证明：中国资产阶级是不能尽此责任的，这个责任就不得不落在无产阶级的肩上了。","language":"中文","translation":false},{"id":"new-democracy-1-48","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"所以，无论如何，中国无产阶级、农民、知识分子和其它小资产阶级，乃是决定国家命运的基本势力。这些阶级，或者已经觉悟，或者正在觉悟起来，他们必然要成为中华民主共和国的国家构成和政权构成的基本部分，而无产阶级则是领导的力量。现在所要建立的中华民主共和国，只能是在无产阶级领导下的一切反帝反封建的人们联合专政的民主共和国，这就是新民主主义的共和国，也就是真正革命的三大政策的新三民主义共和国。","language":"中文","translation":false},{"id":"new-democracy-1-49","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种新民主主义共和国，一方面和旧形式的、欧美式的、资产阶级专政的、资本主义的共和国相区别，那是旧民主主义的共和国，那种共和国已经过时了；另一方面，也和苏联式的、无产阶级专政的、社会主义的共和国相区别，那种社会主义的共和国已经在苏联兴盛起来，并且还要在各资本主义国家建立起来，无疑将成为一切工业先进国家的国家构成和政权构成的统治形式；但是那种共和国，在一定的历史时期中，还不适用于殖民地半殖民地国家的革命。因此，一切殖民地半殖民地国家的革命，在一定历史时期中所采取的国家形式，只能是第三种形式，这就是所谓新民主主义共和国。这是一定历史时期的形式，因而是过渡的形式，但是不可移易的必要的形式。","language":"中文","translation":false},{"id":"new-democracy-1-50","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"因此，全世界多种多样的国家体制中，按其政权的阶级性质来划分，基本地不外乎这三种：（甲）资产阶级专政的共和国；（乙）无产阶级专政的共和国；（丙）几个革命阶级联合专政的共和国。","language":"中文","translation":false},{"id":"new-democracy-1-51","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第一种，是旧民主主义的国家。在今天，在第二次帝国主义战争爆发之后，许多资本主义国家已经没有民主气息，已经转变或即将转变为资产阶级的血腥的军事专政了。某些地主和资产阶级联合专政的国家，可以附在这一类。","language":"中文","translation":false},{"id":"new-democracy-1-52","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第二种，除苏联外，正在各资本主义国家中酝酿着。将来要成为一定时期中的世界统治形式。","language":"中文","translation":false},{"id":"new-democracy-1-53","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第三种，殖民地半殖民地国家的革命所采取的过渡的国家形式。各个殖民地半殖民地国家的革命必然会有某些不同特点，但这是大同中的小异。只要是殖民地或半殖民地的革命，其国家构成和政权构成，基本上必然相同，即几个反对帝国主义的阶级联合起来共同专政的新民主主义的国家。在今天的中国，这种新民主主义的国家形式，就是抗日统一战线的形式。它是抗日的，反对帝国主义的；又是几个革命阶级联合的，统一战线的。但可惜，抗战许久了，除了共产党领导下的抗日民主根据地外，大部分地区关于国家民主化的工作基本上还未着手，日本帝国主义就利用这个最根本的弱点，大踏步地打了进来；再不变计，民族的命运是非常危险的。","language":"中文","translation":false},{"id":"new-democracy-1-54","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这里所谈的是“国体”问题。这个国体问题，从前清末年起，闹了几十年还没有闹清楚。其实，它只是指的一个问题，就是社会各阶级在国家中的地位。资产阶级总是隐瞒这种阶级地位，而用“国民”的名词达到其一阶级专政的实际。这种隐瞒，对于革命的人民，毫无利益，应该为之清楚地指明。“国民”这个名词是可用的，但是国民不包括反革命分子，不包括汉奸。一切革命的阶级对于反革命汉奸们的专政，这就是我们现在所要的国家。","language":"中文","translation":false},{"id":"new-democracy-1-55","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"“近世各国所谓民权制度，往往为资产阶级所专有，适成为压迫平民之工具。若国民党之民权主义，则为一般平民所共有，非少数人所得而私也。”这是一九二四年在国共合作的国民党的第一次全国代表大会宣言中的庄严的声明。十六年来，国民党自己违背了这个声明，以致造成今天这样国难深重的局面。这是国民党一个绝大的错误，我们希望它在抗日的洗礼中改正这个错误。","language":"中文","translation":false},{"id":"new-democracy-1-56","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"至于还有所谓“政体”问题，那是指的政权构成的形式问题，指的一定的社会阶级取何种形式去组织那反对敌人保护自己的政权机关。没有适当形式的政权机关，就不能代表国家。中国现在可以采取全国人民代表大会、省人民代表大会、县人民代表大会、区人民代表大会直到乡人民代表大会的系统，并由各级代表大会选举政府。但必须实行无男女、信仰、财产、教育等差别的真正普遍平等的选举制，才能适合于各革命阶级在国家中的地位，适合于表现民意和指挥革命斗争，适合于新民主主义的精神。这种制度即是民主集中制。只有民主集中制的政府，才能充分地发挥一切革命人民的意志，也才能最有力量地去反对革命的敌人。“非少数人所得而私”的精神，必须表现在政府和军队的组成中，如果没有真正的民主制度，就不能达到这个目的，就叫做政体和国体不相适应。","language":"中文","translation":false},{"id":"new-democracy-1-57","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"国体——各革命阶级联合专政。政体——民主集中制。这就是新民主主义的政治，这就是新民主主义的共和国，这就是抗日统一战线的共和国，这就是三大政策的新三民主义的共和国，这就是名副其实的中华民国。我们现在虽有中华民国之名，尚无中华民国之实，循名责实，这就是今天的工作。","language":"中文","translation":false},{"id":"new-democracy-1-58","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这就是革命的中国、抗日的中国所应该建立和决不可不建立的内部政治关系，这就是今天“建国”工作的唯一正确的方向。","language":"中文","translation":false},{"id":"new-democracy-1-59","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在中国建立这样的共和国，它在政治上必须是新民主主义的，在经济上也必须是新民主主义的。","language":"中文","translation":false},{"id":"new-democracy-1-60","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"大银行、大工业、大商业，归这个共和国的国家所有。“凡本国人及外国人之企业，或有独占的性质，或规模过大为私人之力所不能办者，如银行、铁道、航路之属，由国家经营管理之，使私有资本制度不能操纵国民之生计，此则节制资本之要旨也。”这也是国共合作的国民党的第一次全国代表大会宣言中的庄严的声明，这就是新民主主义共和国的经济构成的正确的方针。在无产阶级领导下的新民主主义共和国的国营经济是社会主义的性质，是整个国民经济的领导力量，但这个共和国并不没收其它资本主义的私有财产，并不禁止“不能操纵国民生计”的资本主义生产的发展，这是因为中国经济还十分落后的缘故。","language":"中文","translation":false},{"id":"new-democracy-1-61","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这个共和国将采取某种必要的方法，没收地主的土地，分配给无地和少地的农民，实行中山先生“耕者有其田”的口号，扫除农村中的封建关系，把土地变为农民的私产。农村的富农经济，也是容许其存在的。这就是“平均地权”的方针。这个方针的正确的口号，就是“耕者有其田”。在这个阶段上，一般地还不是建立社会主义的农业，但在“耕者有其田”的基础上所发展起来的各种合作经济，也具有社会主义的因素。","language":"中文","translation":false},{"id":"new-democracy-1-62","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中国的经济，一定要走“节制资本”和“平均地权”的路，决不能是“少数人所得而私”，决不能让少数资本家少数地主“操纵国民生计”，决不能建立欧美式的资本主义社会，也决不能还是旧的半封建社会。谁要是敢于违反这个方向，他就一定达不到目的，他就自己要碰破头的。","language":"中文","translation":false},{"id":"new-democracy-1-63","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这就是革命的中国、抗日的中国应该建立和必然要建立的内部经济关系。","language":"中文","translation":false},{"id":"new-democracy-1-64","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这样的经济，就是新民主主义的经济。","language":"中文","translation":false},{"id":"new-democracy-1-65","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"而新民主主义的政治，就是这种新民主主义经济的集中的表现。","language":"中文","translation":false},{"id":"new-democracy-1-66","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种新民主主义政治和新民主主义经济的共和国，是全国百分之九十以上的人民都赞成的，舍此没有第二条路走。","language":"中文","translation":false},{"id":"new-democracy-1-67","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"走建立资产阶级专政的资本主义社会之路吗？诚然，这是欧美资产阶级走过的老路，但无如国际国内的环境，都不容许中国这样做。","language":"中文","translation":false},{"id":"new-democracy-1-68","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"依国际环境说，这条路是走不通的。现在的国际环境，从基本上说来，是资本主义和社会主义斗争的环境，是资本主义向下没落，社会主义向上生长的环境。要在中国建立资产阶级专政的资本主义社会，首先是国际资本主义即帝国主义不容许。帝国主义侵略中国，反对中国独立，反对中国发展资本主义的历史，就是中国的近代史。历来中国革命的失败，都是被帝国主义绞杀的，无数革命的先烈，为此而抱终天之恨。现在是一个强大的日本帝国主义打了进来，它是要把中国变成殖民地的；现在是日本在中国发展它的资本主义，却不是什么中国发展资本主义；现在是日本资产阶级在中国专政，却不是什么中国资产阶级专政。不错，现在是帝国主义最后挣扎的时期，它快要死了，“帝国主义是垂死的资本主义”[14]。但是正因为它快要死了，它就更加依赖殖民地半殖民地过活，决不容许任何殖民地半殖民地建立什么资产阶级专政的资本主义社会。正因为日本帝国主义陷在严重的经济危机和政治危机的深坑之中，就是说，它快要死了，它就一定要打中国，一定要把中国变为殖民地，它就断绝了中国建立资产阶级专政和发展民族资本主义的路。","language":"中文","translation":false},{"id":"new-democracy-1-69","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"其次，是社会主义不容许。这个世界上，所有帝国主义都是我们的敌人，中国要独立，决不能离开社会主义国家和国际无产阶级的援助。这就是说，不能离开苏联的援助，不能离开日本和英、美、法、德、意各国无产阶级在其本国进行反资本主义斗争的援助。虽然不能说，中国革命的胜利一定要在日本和英、美、法、德、意各国或其中一二国的革命胜利之后，但须加上它们的力量才能胜利，这是没有疑义的。尤其是苏联的援助，是抗战最后胜利决不可少的条件。拒绝苏联的援助，革命就要失败，一九二七年以后反苏运动[15]的教训，不是异常明显的吗？现在的世界，是处在革命和战争的新时代，是资本主义决然死灭和社会主义决然兴盛的时代。在这种情形下，要在中国反帝反封建胜利之后，再建立资产阶级专政的资本主义社会，岂非是完全的梦呓？","language":"中文","translation":false},{"id":"new-democracy-1-70","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"如果说，由于特殊条件（资产阶级战胜了希腊的侵略，无产阶级的力量太薄弱），在第一次帝国主义大战和十月革命之后，还有过一个基马尔式的小小的资产阶级专政的土耳其[16]，那末，在第二次世界大战和苏联已经完成社会主义建设之后，就决不会再有一个土耳其，尤其决不容许有一个四亿五千万人口的土耳其。由于中国的特殊条件（资产阶级的软弱和妥协性，无产阶级的强大和革命彻底性），中国从来也没有过土耳其的那种便宜事情。一九二七年中国第一次大革命失败之后，中国的资产阶级分子不是曾经高唱过什么基马尔主义吗？然而中国的基马尔在何处？中国的资产阶级专政和资本主义社会又在何处呢？何况所谓基马尔的土耳其，最后也不能不投入英法帝国主义的怀抱，一天一天变成了半殖民地，变成了帝国主义反动世界的一部分。处在今天的国际环境中，殖民地半殖民地的任何英雄好汉们，要就是站在帝国主义战线方面，变为世界反革命力量的一部分；要就是站在反帝国主义战线方面，变为世界革命力量的一部分。二者必居其一，其它的道路是没有的[17]。","language":"中文","translation":false},{"id":"new-democracy-1-71","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"依国内环境说，中国资产阶级应该获得了必要的教训。中国资产阶级，以大资产阶级为首，在一九二七年的革命刚刚由于无产阶级、农民和其它小资产阶级的力量而得到胜利之际，他们就一脚踢开了这些人民大众，独占革命的果实，而和帝国主义及封建势力结成了反革命联盟，并且费了九牛二虎之力，举行了十年的“剿共”战争。然而结果又怎么样呢？现在是当一个强大敌人深入国土、抗日战争已打了两年之后，难道还想抄袭欧美资产阶级已经过时了的老章程吗？过去的“剿共十年”并没有“剿”出什么资产阶级专政的资本主义社会，难道还想再来试一次吗？不错，“剿共十年”“剿”出了一个“一党专政”，但这乃是半殖民地半封建的专政。而在“剿共”四年（一九二七年至一九三一年的“九一八”）之后，就已经“剿”出了一个“满洲国”；再加六年，至一九三七年，就把一个日本帝国主义“剿”进中国本部来了。如果有人还想从今日起，再“剿”十年，那就已经是新的“剿共”典型，同旧的多少有点区别。但是这种新的“剿共”事业，不是已经有人捷足先登、奋勇担负起来了吗？这个人就是汪精卫，他已经是大名鼎鼎的新式反共人物了。谁要加进他那一伙去，那是行的，但是什么资产阶级专政呀，资本主义社会呀，基马尔主义呀，现代国家呀，一党专政呀，一个主义呀，等等花腔，岂非更加不好意思唱了吗？如果不入汪精卫一伙，要入抗日一伙，又想于抗日胜利之后，一脚踢开抗日人民，自己独占抗日成果，来一个“一党专政万岁”，又岂非近于做梦吗？抗日，抗日，是谁之力？离了工人、农民和其它小资产阶级，你就不能走动一步。谁还敢于去踢他们，谁就要变为粉碎，这又岂非成了常识范围里的东西了吗？但是中国资产阶级顽固派（我说的是顽固派），二十年来，似乎并没有得到什么教训。不见他们还在那里高叫什么“限共”、“溶共”、“反共”吗？不见他们一个《限制异党活动办法》之后，再来一个《异党问题处理办法》，再来一个《处理异党问题实施方案》[18]吗？好家伙，这样地“限制”和“处理”下去，不知他们准备置民族命运于何地，也不知他们准备置其自身于何地？我们诚心诚意地奉劝这些先生们，你们也应该睁开眼睛看一看中国和世界，看一看国内和国外，看一看现在是什么样子，不要再重复你们的错误了。再错下去，民族命运固然遭殃，我看你们自己的事情也不大好办。这是断然的，一定的，确实的，中国资产阶级顽固派如不觉悟，他们的事情是并不美妙的，他们将得到一个自寻死路的前途。所以我们希望中国的抗日统一战线坚持下去，不是一家独霸而是大家合作，把抗日的事业弄个胜利，才是上策，否则一概是下策。这是我们共产党人的衷心劝告，“勿谓言之不预也”。","language":"中文","translation":false},{"id":"new-democracy-1-72","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"中国有一句老话：“有饭大家吃。”这是很有道理的。既然有敌大家打，就应该有饭大家吃，有事大家做，有书大家读。那种“一人独吞”、“人莫予毒”的派头，不过是封建主的老戏法，拿到二十世纪四十年代来，到底是行不通的。","language":"中文","translation":false},{"id":"new-democracy-1-73","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"我们共产党人对于一切革命的人们，是决不排斥的，我们将和所有愿意抗日到底的阶级、阶层、政党、政团以及个人，坚持统一战线，实行长期合作。但人家要排斥共产党，那是不行的；人家要分裂统一战线，那是不行的。中国必须抗战下去，团结下去，进步下去；谁要投降，要分裂，要倒退，我们是不能容忍的。","language":"中文","translation":false},{"id":"new-democracy-1-74","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"不走资产阶级专政的资本主义的路，是否就可以走无产阶级专政的社会主义的路呢？","language":"中文","translation":false},{"id":"new-democracy-1-75","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"没有问题，现在的革命是第一步，将来要发展到第二步，发展到社会主义。中国也只有进到社会主义时代才是真正幸福的时代。但是现在还不是实行社会主义的时候。中国现在的革命任务是反帝反封建的任务，这个任务没有完成以前，社会主义是谈不到的。中国革命不能不做两步走，第一步是新民主主义，第二步才是社会主义。而且第一步的时间是相当地长，决不是一朝一夕所能成就的。我们不是空想家，我们不能离开当前的实际条件。","language":"中文","translation":false},{"id":"new-democracy-1-76","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"有些恶意的宣传家，故意混淆这两个不同的革命阶段，提倡所谓“一次革命论”，用以证明什么革命都包举在三民主义里面了，共产主义就失了存在的理由；用这种“理论”，起劲地反对共产主义和共产党，反对八路军新四军和陕甘宁边区。其目的，是想根本消灭任何革命，反对资产阶级民主革命的彻底性，反对抗日的彻底性，而为投降日寇准备舆论。这种情形，是日本帝国主义有计划地造成的。因为日本帝国主义在占领武汉后，知道单用武力不能屈服中国，乃着手于政治进攻和经济引诱。所谓政治进攻，就是在抗日阵线中诱惑动摇分子，分裂统一战线，破坏国共合作。所谓经济引诱，就是所谓“合办实业”。在华中华南，日寇允许中国资本家投资百分之五十一，日资占百分之四十九；在华北，日寇允许中国资本家投资百分之四十九，日资占百分之五十一。日寇并允许将各中国资本家原有产业，发还他们，折合计算，充作资本。这样一来，一些丧尽天良的资本家，就见利忘义，跃跃欲试。一部分资本家，以汪精卫为代表，已经投降了。再一部分资本家，躲在抗日阵线内的，也想跑去。但是他们做贼心虚，怕共产党阻挡他们的去路，更怕老百姓骂汉奸。于是打伙儿地开了个会，决议：事先要在文化界舆论界准备一下。计策已定，事不宜迟，于是雇上几个玄学鬼[19]，再加几名托洛茨基，摇动笔杆枪，就乱唤乱叫、乱打乱刺了一顿。于是什么“一次革命论”呀，共产主义不适合中国国情呀，共产党在中国没有存在之必要呀，八路军新四军破坏抗日、游而不击呀，陕甘宁边区是封建割据呀，共产党不听话、不统一、有阴谋、要捣乱呀，来这么一套，骗那些不知世事的人，以便时机一到，资本家们就很有理由地去拿百分之四十九或五十一，而把全民族的利益一概卖给敌人。这个叫做偷梁换柱，实行投降之前的思想准备或舆论准备。这班先生们，像煞有介事地提倡“一次革命论”，反对共产主义和共产党，却原来不为别的，专为百分之四十九或五十一，其用心亦良苦矣。“一次革命论”者，不要革命论也，这就是问题的本质。","language":"中文","translation":false},{"id":"new-democracy-1-77","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"但是还有另外一些人，他们似乎并无恶意，也迷惑于所谓“一次革命论”，迷惑于所谓“举政治革命与社会革命毕其功于一役”的纯主观的想头；而不知革命有阶段之分，只能由一个革命到另一个革命，无所谓“毕其功于一役”。这种观点，混淆革命的步骤，降低对于当前任务的努力，也是很有害的。如果说，两个革命阶段中，第一个为第二个准备条件，而两个阶段必须衔接，不容横插一个资产阶级专政的阶段，这是正确的，这是马克思主义的革命发展论。如果说，民主革命没有自己的一定任务，没有自己的一定时间，而可以把只能在另一个时间去完成的另一任务，例如社会主义的任务，合并在民主主义任务上面去完成，这个叫做“毕其功于一役”，那就是空想，而为真正的革命者所不取的。","language":"中文","translation":false},{"id":"new-democracy-1-78","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"于是资产阶级顽固派就跑出来说：好，你们共产党既然把社会主义社会制度推到后一个阶段去了，你们既然又宣称“三民主义为中国今日之必需，本党愿为其彻底实现而奋斗”[20]，那末，就把共产主义暂时收起好了。这种议论，在所谓“一个主义”的标题之下，已经变成了狂妄的叫嚣。这种叫嚣，其本质就是顽固分子们的资产阶级专制主义。但为了客气一点，叫它作毫无常识，也是可以的。","language":"中文","translation":false},{"id":"new-democracy-1-79","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"共产主义是无产阶级的整个思想体系，同时又是一种新的社会制度。这种思想体系和社会制度，是区别于任何别的思想体系和任何别的社会制度的，是自有人类历史以来，最完全最进步最革命最合理的。封建主义的思想体系和社会制度，是进了历史博物馆的东西了。资本主义的思想体系和社会制度，已有一部分进了博物馆（在苏联）；其余部分，也已“日薄西山，气息奄奄，人命危浅，朝不虑夕”，快进博物馆了。惟独共产主义的思想体系和社会制度，正以排山倒海之势，雷霆万钧之力，磅礴于全世界，而葆其美妙之青春。中国自有科学的共产主义以来，人们的眼界是提高了，中国革命也改变了面目。中国的民主革命，没有共产主义去指导是决不能成功的，更不必说革命的后一阶段了。这也就是资产阶级顽固派为什么要那样叫嚣和要求“收起”它的原因。其实，这是“收起”不得的，一收起，中国就会亡国。现在的世界，依靠共产主义做救星；现在的中国，也正是这样。","language":"中文","translation":false},{"id":"new-democracy-1-80","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"谁人不知，关于社会制度的主张，共产党是有现在的纲领和将来的纲领，或最低纲领和最高纲领两部分的。在现在，新民主主义，在将来，社会主义，这是有机构成的两部分，而为整个共产主义思想体系所指导的。因为共产党的最低纲领和三民主义的政治原则基本上相同，就狂叫“收起”共产主义，岂非荒谬绝伦之至？在共产党人，正因三民主义的政治原则有和自己的最低纲领基本上相同之点，所以才有可能承认“三民主义为抗日统一战线的政治基础”，才有可能承认“三民主义为中国今日之必需，本党愿为其彻底实现而奋斗”，否则就没有这种可能了。这是共产主义和三民主义在民主革命阶段上的统一战线，孙中山所谓“共产主义是三民主义的好朋友”[21]，也正是指的这种统一战线。否认共产主义，实际上就是否认统一战线。顽固派也正是要奉行其一党主义，否认统一战线，才造出那些否认共产主义的荒谬说法来。","language":"中文","translation":false},{"id":"new-democracy-1-81","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"“一个主义”也不通。在阶级存在的条件之下，有多少阶级就有多少主义，甚至一个阶级的各集团中还各有各的主义。现在封建阶级有封建主义，资产阶级有资本主义，佛教徒有佛教主义，基督徒有基督主义，农民有多神主义，近年还有人提倡什么基马尔主义，法西斯主义，唯生主义[22]，“按劳分配主义”[23]，为什么无产阶级不可以有一个共产主义呢？既然是数不清的主义，为什么见了共产主义就高叫“收起”呢？讲实在话，“收起”是不行的，还是比赛吧。谁把共产主义比输了，我们共产党人自认晦气。如若不然，那所谓“一个主义”的反民权主义的作风，还是早些“收起”吧！","language":"中文","translation":false},{"id":"new-democracy-1-82","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"为了免除误会，并使顽固派开开眼界起见，关于三民主义和共产主义的异同，有清楚指明之必要。","language":"中文","translation":false},{"id":"new-democracy-1-83","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"三民主义和共产主义两个主义比较起来，有相同的部分，也有不同的部分。","language":"中文","translation":false},{"id":"new-democracy-1-84","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第一，相同部分。这就是两个主义在中国资产阶级民主革命阶段上的基本政纲。一九二四年孙中山重新解释的三民主义中的革命的民族主义、民权主义和民生主义这三个政治原则，同共产主义在中国民主革命阶段的政纲，基本上是相同的。由于这些相同，并由于三民主义见之实行，就有两个主义两个党的统一战线。忽视这一方面，是错误的。","language":"中文","translation":false},{"id":"new-democracy-1-85","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第二，不同部分。则有：（一）民主革命阶段上一部分纲领的不相同。共产主义的全部民主革命政纲中有彻底实现人民权力、八小时工作制和彻底的土地革命纲领，三民主义则没有这些部分。如果它不补足这些，并且准备实行起来，那对于民主政纲就只是基本上相同，不能说完全相同。（二）有无社会主义革命阶段的不同。共产主义于民主革命阶段之外，还有一个社会主义革命阶段，因此，于最低纲领之外，还有一个最高纲领，即实现社会主义和共产主义社会制度的纲领。三民主义则只有民主革命阶段，没有社会主义革命阶段，因此它就只有最低纲领，没有最高纲领，即没有建立社会主义和共产主义社会制度的纲领。（三）宇宙观的不同。共产主义的宇宙观是辩证唯物论和历史唯物论，三民主义的宇宙观则是所谓民生史观，实质上是二元论或唯心论，二者是相反的。（四）革命彻底性的不同。共产主义者是理论和实践一致的，即有革命彻底性。三民主义者除了那些最忠实于革命和真理的人们之外，是理论和实践不一致的，讲的和做的互相矛盾，即没有革命彻底性。上述这些，都是两者的不同部分。由于这些不同，共产主义者和三民主义者之间就有了差别。忽视这种差别，只看见统一方面，不看见矛盾方面，无疑是非常错误的。","language":"中文","translation":false},{"id":"new-democracy-1-86","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"明白了这些之后，就可以明白，资产阶级顽固派要求“收起”共产主义，这是什么意思呢？不是资产阶级的专制主义，就是毫无常识了。","language":"中文","translation":false},{"id":"new-democracy-1-87","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一○ 旧三民主义和新三民主义","language":"中文","translation":false},{"id":"new-democracy-1-88","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"资产阶级顽固派完全不知道历史的变化，其知识的贫乏几等于零。他们既不知道共产主义和三民主义的区别，也不知道新三民主义和旧三民主义的区别。","language":"中文","translation":false},{"id":"new-democracy-1-89","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"我们共产党人承认“三民主义为抗日民族统一战线的政治基础”，承认“三民主义为中国今日之必需，本党愿为其彻底实现而奋斗”，承认共产主义的最低纲领和三民主义的政治原则基本上相同。但是这种三民主义是什么三民主义呢？这种三民主义不是任何别的三民主义，乃是孙中山先生在《中国国民党第一次全国代表大会宣言》中所重新解释的三民主义。我愿顽固派先生们，于其“限共”、“溶共”、“反共”等工作洋洋得意之余，也去翻阅一下这个宣言。原来孙中山先生在这个宣言中说道：“国民党之三民主义，其真释具如此。”就可知只有这种三民主义，才是真三民主义，其它都是伪三民主义。只有《中国国民党第一次全国代表大会宣言》里对于三民主义的解释才是“真释”，其它一切都是伪释。这大概不是共产党“造谣”吧，这篇宣言的通过，我和很多的国民党员都是亲眼看见的。","language":"中文","translation":false},{"id":"new-democracy-1-90","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这篇宣言，区分了三民主义的两个历史时代。在这以前，三民主义是旧范畴的三民主义，是旧的半殖民地资产阶级民主革命的三民主义，是旧民主主义的三民主义，是旧三民主义。","language":"中文","translation":false},{"id":"new-democracy-1-91","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在这以后，三民主义是新范畴的三民主义，是新的半殖民地资产阶级民主革命的三民主义，是新民主主义的三民主义，是新三民主义。只有这种三民主义，才是新时期的革命的三民主义。","language":"中文","translation":false},{"id":"new-democracy-1-92","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种新时期的革命的三民主义，新三民主义或真三民主义，是联俄、联共、扶助农工三大政策的三民主义。没有三大政策，或三大政策缺一，在新时期中，就都是伪三民主义，或半三民主义。","language":"中文","translation":false},{"id":"new-democracy-1-93","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第一，革命的三民主义，新三民主义，或真三民主义，必须是联俄的三民主义。现在的事情非常明白，如果没有联俄政策，不同社会主义国家联合，那就必然是联帝政策，必然同帝国主义联合。不见一九二七年之后，就已经有过这种情形吗？社会主义的苏联和帝国主义之间的斗争一经进一步尖锐化，中国不站在这方面，就要站在那方面，这是必然的趋势。难道不可以不偏不倚吗？这是梦想。全地球都要卷进这两个战线中去，在今后的世界中，“中立”只是骗人的名词。何况中国是在同一个深入国土的帝国主义奋斗，没有苏联帮助，就休想最后胜利。如果舍联俄而联帝，那就必须将“革命”二字取消，变成反动的三民主义。归根结底，没有“中立”的三民主义，只有革命的或反革命的三民主义。如果照汪精卫从前的话，来一个“夹攻中的奋斗”[24]，来一个“夹攻中奋斗”的三民主义，岂不勇矣哉？但可惜连发明人汪精卫也放弃（或“收起”）了这种三民主义，他现在改取了联帝的三民主义。如果说帝亦有东帝西帝之分，他联的是东帝，我和他相反，联一批西帝，东向而击，又岂不革命矣哉？但无如西帝们要反苏反共，你联它们，它们就要请你北向而击，你革命也革不成。所有这些情形，就规定了革命的三民主义，新三民主义，或真三民主义，必须是联俄的三民主义，决不能是同帝国主义联合反俄的三民主义。","language":"中文","translation":false},{"id":"new-democracy-1-94","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第二，革命的三民主义，新三民主义，或真三民主义，必须是联共的三民主义。如不联共，就要反共。反共是日本帝国主义和汪精卫的政策，你也要反共，那很好，他们就请你加入他们的反共公司。但这岂非有点当汉奸的嫌疑吗？我不跟日本走，单跟别国走。那也滑稽。不管你跟谁走，只要反共，你就是汉奸，因为你不能再抗日。我独立反共。那是梦话。岂有殖民地半殖民地的好汉们，能够不靠帝国主义之力，干得出如此反革命大事吗？昔日差不多动员了全世界帝国主义的气力反了十年之久还没有反了的共，今日忽能“独立”反之吗？听说外边某些人有这么一句话：“反共好，反不了。”如果传言非虚，那末，这句话只有一半是错的，“反共”有什么“好”呢？却有一半是对的，“反共”真是“反不了”。其原因，基本上不在于“共”而在于老百姓，因为老百姓欢喜“共”，却不欢喜“反”。老百姓是决不容情的，在一个民族敌人深入国土之时，你要反共，他们就要了你的命。这是一定的，谁要反共谁就要准备变成齑粉。如果没有决心准备变自己为齑粉的话，那就确实以不反为妙。这是我们向一切反共英雄们的诚恳的劝告。因之清楚而又清楚，今日的三民主义，必须是联共的三民主义，否则，三民主义就要灭亡。这是三民主义的存亡问题。联共则三民主义存，反共则三民主义亡，谁能证明其不然呢？","language":"中文","translation":false},{"id":"new-democracy-1-95","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第三，革命的三民主义，新三民主义，或真三民主义，必须是农工政策的三民主义。不要农工政策，不真心实意地扶助农工，不实行《总理遗嘱》上的“唤起民众”，那就是准备革命失败，也就是准备自己失败。斯大林说：“所谓民族问题，实质上就是农民问题。”[25]这就是说，中国的革命实质上是农民革命，现在的抗日，实质上是农民的抗日。新民主主义的政治，实质上就是授权给农民。新三民主义，真三民主义，实质上就是农民革命主义。大众文化，实质上就是提高农民文化。抗日战争，实质上就是农民战争。现在是“上山主义”[26]的时候，大家开会、办事、上课、出报、着书、演剧，都在山头上，实质上都是为的农民。抗日的一切，生活的一切，实质上都是农民所给。说“实质上”，就是说基本上，并非忽视其它部分，这是斯大林自己解释过了的。中国有百分之八十的人口是农民，这是小学生的常识。因此农民问题，就成了中国革命的基本问题，农民的力量，是中国革命的主要力量。农民之外，中国人口中第二个部分就是工人。中国有产业工人数百万，有手工业工人和农业工人数千万。没有各种工业工人，中国就不能生活，因为他们是工业经济的生产者。没有近代工业工人阶级，革命就不能胜利，因为他们是中国革命的领导者，他们最富于革命性。在这种情形下，革命的三民主义，新三民主义或真三民主义，必然是农工政策的三民主义。如果有什么一种三民主义，它是没有农工政策的，它是并不真心实意扶助农工，并不实行“唤起民众”的，那就一定会灭亡。","language":"中文","translation":false},{"id":"new-democracy-1-96","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"由此可知，离开联俄、联共、扶助农工三大政策的三民主义，是没有前途的。一切有良心的三民主义者，必须认真地考虑到这点。","language":"中文","translation":false},{"id":"new-democracy-1-97","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种三大政策的三民主义，革命的三民主义，新三民主义，真三民主义，是新民主主义的三民主义，是旧三民主义的发展，是孙中山先生的大功劳，是在中国革命作为社会主义世界革命一部分的时代产生的。只有这种三民主义，中国共产党才称之为“中国今日之必需”，才宣布“愿为其彻底实现而奋斗”。只有这种三民主义，才和中国共产党在民主革命阶段中的政纲，即其最低纲领，基本上相同。","language":"中文","translation":false},{"id":"new-democracy-1-98","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"至于旧三民主义，那是中国革命旧时期的产物。那时的俄国是帝国主义的俄国，当然不能有联俄政策；那时国内也没有共产党，当然不能有联共政策；那时工农运动也没有充分显露自己在政治上的重要性，尚不为人们所注意，当然就没有联合工农的政策。因此，一九二四年国民党改组以前的三民主义，乃是旧范畴的三民主义，乃是过时了的三民主义。如不把它发展到新三民主义，国民党就不能前进。聪明的孙中山看到了这一点，得了苏联和中国共产党的助力，把三民主义重新作了解释，遂获得了新的历史特点，建立了三民主义同共产主义的统一战线，建立了第一次国共合作，取得了全国人民的同情，举行了一九二四年至一九二七年的革命。","language":"中文","translation":false},{"id":"new-democracy-1-99","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"旧三民主义在旧时期内是革命的，它反映了旧时期的历史特点。但如果在新时期内，在新三民主义已经建立之后，还要翻那老套；在有了社会主义国家以后，要反对联俄；在有了共产党之后，要反对联共；在工农已经觉悟并显示了自己的政治威力之后，要反对农工政策；那末，它就是不识时务的反动的东西了。一九二七年以后的反动，就是这种不识时务的结果。语曰：“识时务者为俊杰。”我愿今日的三民主义者记取此语。","language":"中文","translation":false},{"id":"new-democracy-1-100","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"如果是旧范畴的三民主义，那就同共产主义的最低纲领没有什么基本上相同之点，因为它是旧时期的，是过时了的。如果有什么一种三民主义，它要反俄、反共、反农工，那就是反动的三民主义，它不但和共产主义的最低纲领没有丝毫相同之点，而且是共产主义的敌人，一切都谈不上。这也是三民主义者应该慎重地考虑一番的。","language":"中文","translation":false},{"id":"new-democracy-1-101","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"但是无论如何，在反帝反封建的任务没有基本上完成以前，新三民主义是不会被一切有良心的人们放弃的。放弃它的只是那些汪精卫、李精卫之流。汪精卫、李精卫们尽管起劲地干什么反俄、反共、反农工的伪三民主义，自会有一班有良心的有正义感的人们继续拥护孙中山的真三民主义。如果说，一九二七年反动之后，还有许多真三民主义者继续为中国革命而奋斗，那末，在一个民族敌人深入国土的今天，这种人无疑将是成千成万的。我们共产党人将始终和一切真诚的三民主义者实行长期合作，除了汉奸和那班至死不变的反共分子外，我们是决不抛弃任何友人的。","language":"中文","translation":false},{"id":"new-democracy-1-102","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"上面，我们说明了中国政治在新时期中的历史特点，说明了新民主主义共和国问题。下面，我们就可以进到文化问题了。","language":"中文","translation":false},{"id":"new-democracy-1-103","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一定的文化是一定社会的政治和经济在观念形态上的反映。在中国，有帝国主义文化，这是反映帝国主义在政治上经济上统治或半统治中国的东西。这一部分文化，除了帝国主义在中国直接办理的文化机关之外，还有一些无耻的中国人也在提倡。一切包含奴化思想的文化，都属于这一类。在中国，又有半封建文化，这是反映半封建政治和半封建经济的东西，凡属主张尊孔读经、提倡旧礼教旧思想、反对新文化新思想的人们，都是这类文化的代表。帝国主义文化和半封建文化是非常亲热的两兄弟，它们结成文化上的反动同盟，反对中国的新文化。这类反动文化是替帝国主义和封建阶级服务的，是应该被打倒的东西。不把这种东西打倒，什么新文化都是建立不起来的。不破不立，不塞不流，不止不行，它们之间的斗争是生死斗争。","language":"中文","translation":false},{"id":"new-democracy-1-104","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"至于新文化，则是在观念形态上反映新政治和新经济的东西，是替新政治新经济服务的。","language":"中文","translation":false},{"id":"new-democracy-1-105","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"如我们在第三节中已经提过的话，中国自从发生了资本主义经济以来，中国社会就逐渐改变了性质，它不是完全的封建社会了，变成了半封建社会，虽然封建经济还是占优势。这种资本主义经济，对于封建经济说来，它是新经济。同这种资本主义新经济同时发生和发展着的新政治力量，就是资产阶级、小资产阶级和无产阶级的政治力量。而在观念形态上作为这种新的经济力量和新的政治力量之反映并为它们服务的东西，就是新文化。没有资本主义经济，没有资产阶级、小资产阶级和无产阶级，没有这些阶级的政治力量，所谓新的观念形态，所谓新文化，是无从发生的。","language":"中文","translation":false},{"id":"new-democracy-1-106","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"新的政治力量，新的经济力量，新的文化力量，都是中国的革命力量，它们是反对旧政治旧经济旧文化的。这些旧东西是由两部分合成的，一部分是中国自己的半封建的政治经济文化，另一部分是帝国主义的政治经济文化，而以后者为盟主。所有这些，都是坏东西，都是应该彻底破坏的。中国社会的新旧斗争，就是人民大众（各革命阶级）的新势力和帝国主义及封建阶级的旧势力之间的斗争。这种新旧斗争，即是革命和反革命的斗争。这种斗争的时间，从鸦片战争算起，已经整整一百年了；从辛亥革命算起，也有了差不多三十年了。","language":"中文","translation":false},{"id":"new-democracy-1-107","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"但是如前所说，革命亦有新旧之分，在某一历史时期是新的东西，在另一历史时期就变为旧的了。在中国资产阶级民主革命的一百年中，分为前八十年和后二十年两个大段落。这两大段落中，各有一个基本的带历史性质的特点，即在前八十年，中国资产阶级民主革命是属于旧范畴的；而在后二十年，由于国际国内政治形势的变化，便属于新范畴了。旧民主主义——前八十年的特点。新民主主义——后二十年的特点。这种区别，在政治上如此，在文化上也是如此。","language":"中文","translation":false},{"id":"new-democracy-1-108","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在文化上如何表现这种区别呢？这就是我们要在下面说明的问题。","language":"中文","translation":false},{"id":"new-democracy-1-109","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一二 中国文化革命的历史特点","language":"中文","translation":false},{"id":"new-democracy-1-110","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在中国文化战线或思想战线上，“五四”以前和“五四”以后，构成了两个不同的历史时期。","language":"中文","translation":false},{"id":"new-democracy-1-111","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在“五四”以前，中国文化战线上的斗争，是资产阶级的新文化和封建阶级的旧文化的斗争。在“五四”以前，学校与科举之争[27]，新学与旧学之争，西学与中学之争，都带着这种性质。那时的所谓学校、新学、西学，基本上都是资产阶级代表们所需要的自然科学和资产阶级的社会政治学说（说基本上，是说那中间还夹杂了许多中国的封建余毒在内）。在当时，这种所谓新学的思想，有同中国封建思想作斗争的革命作用，是替旧时期的中国资产阶级民主革命服务的。可是，因为中国资产阶级的无力和世界已经进到帝国主义时代，这种资产阶级思想只能上阵打几个回合，就被外国帝国主义的奴化思想和中国封建主义的复古思想的反动同盟所打退了，被这个思想上的反动同盟军稍稍一反攻，所谓新学，就偃旗息鼓，宣告退却，失了灵魂，而只剩下它的躯壳了。旧的资产阶级民主主义文化，在帝国主义时代，已经腐化，已经无力了，它的失败是必然的。","language":"中文","translation":false},{"id":"new-democracy-1-112","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"“五四”以后则不然。在“五四”以后，中国产生了完全崭新的文化生力军，这就是中国共产党人所领导的共产主义的文化思想，即共产主义的宇宙观和社会革命论。五四运动是在一九一九年，中国共产党的成立和劳动运动的真正开始是在一九二一年，均在第一次世界大战和十月革命之后，即在民族问题和殖民地革命运动在世界上改变了过去面貌之时，在这里中国革命和世界革命的联系，是非常之显然的。由于中国政治生力军即中国无产阶级和中国共产党登上了中国的政治舞台，这个文化生力军，就以新的装束和新的武器，联合一切可能的同盟军，摆开了自己的阵势，向着帝国主义文化和封建文化展开了英勇的进攻。这支生力军在社会科学领域和文学艺术领域中，不论在哲学方面，在经济学方面，在政治学方面，在军事学方面，在历史学方面，在文学方面，在艺术方面（又不论是戏剧，是电影，是音乐，是雕刻，是绘画），都有了极大的发展。二十年来，这个文化新军的锋芒所向，从思想到形式（文字等），无不起了极大的革命。其声势之浩大，威力之猛烈，简直是所向无敌的。其动员之广大，超过中国任何历史时代。而鲁迅，就是这个文化新军的最伟大和最英勇的旗手。鲁迅是中国文化革命的主将，他不但是伟大的文学家，而且是伟大的思想家和伟大的革命家。鲁迅的骨头是最硬的，他没有丝毫的奴颜和媚骨，这是殖民地半殖民地人民最可宝贵的性格。鲁迅是在文化战线上，代表全民族的大多数，向着敌人冲锋陷阵的最正确、最勇敢、最坚决、最忠实、最热忱的空前的民族英雄。鲁迅的方向，就是中华民族新文化的方向。","language":"中文","translation":false},{"id":"new-democracy-1-113","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在“五四”以前，中国的新文化，是旧民主主义性质的文化，属于世界资产阶级的资本主义的文化革命的一部分。在“五四”以后，中国的新文化，却是新民主主义性质的文化，属于世界无产阶级的社会主义的文化革命的一部分。","language":"中文","translation":false},{"id":"new-democracy-1-114","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在“五四”以前，中国的新文化运动，中国的文化革命，是资产阶级领导的，他们还有领导作用。在“五四”以后，这个阶级的文化思想却比较它的政治上的东西还要落后，就绝无领导作用，至多在革命时期在一定程度上充当一个盟员，至于盟长资格，就不得不落在无产阶级文化思想的肩上。这是铁一般的事实，谁也否认不了的。","language":"中文","translation":false},{"id":"new-democracy-1-115","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"所谓新民主主义的文化，就是人民大众反帝反封建的文化；在今日，就是抗日统一战线的文化。这种文化，只能由无产阶级的文化思想即共产主义思想去领导，任何别的阶级的文化思想都是不能领导了的。所谓新民主主义的文化，一句话，就是无产阶级领导的人民大众的反帝反封建的文化。","language":"中文","translation":false},{"id":"new-democracy-1-116","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"文化革命是在观念形态上反映政治革命和经济革命，并为它们服务的。在中国，文化革命，和政治革命同样，有一个统一战线。","language":"中文","translation":false},{"id":"new-democracy-1-117","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种文化革命的统一战线，二十年来，分为四个时期。第一个时期是一九一九年到一九二一年的两年，第二个时期是一九二一年到一九二七年的六年，第三个时期是一九二七年到一九三七年的十年，第四个时期是一九三七年到现在的三年。","language":"中文","translation":false},{"id":"new-democracy-1-118","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第一个时期是一九一九年五四运动到一九二一年中国共产党成立。这一时期中以五四运动为主要的标志。","language":"中文","translation":false},{"id":"new-democracy-1-119","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"五四运动是反帝国主义的运动，又是反封建的运动。五四运动的杰出的历史意义，在于它带着为辛亥革命还不曾有的姿态，这就是彻底地不妥协地反帝国主义和彻底地不妥协地反封建主义。五四运动所以具有这种性质，是在当时中国的资本主义经济已有进一步的发展，当时中国的革命知识分子眼见得俄、德、奥三大帝国主义国家已经瓦解，英、法两大帝国主义国家已经受伤，而俄国无产阶级已经建立了社会主义国家，德、奥（匈牙利）、意三国无产阶级在革命中，因而发生了中国民族解放的新希望。五四运动是在当时世界革命号召之下，是在俄国革命号召之下，是在列宁号召之下发生的。五四运动是当时无产阶级世界革命的一部分。五四运动时期虽然还没有中国共产党，但是已经有了大批的赞成俄国革命的具有初步共产主义思想的知识分子。五四运动，在其开始，是共产主义的知识分子、革命的小资产阶级知识分子和资产阶级知识分子（他们是当时运动中的右翼）三部分人的统一战线的革命运动。它的弱点，就在只限于知识分子，没有工人农民参加。但发展到六三运动[28]时，就不但是知识分子，而且有广大的无产阶级、小资产阶级和资产阶级参加，成了全国范围的革命运动了。五四运动所进行的文化革命则是彻底地反对封建文化的运动，自有中国历史以来，还没有过这样伟大而彻底的文化革命。当时以反对旧道德提倡新道德、反对旧文学提倡新文学为文化革命的两大旗帜，立下了伟大的功劳。这个文化运动，当时还没有可能普及到工农群众中去。它提出了“平民文学”口号，但是当时的所谓“平民”，实际上还只能限于城市小资产阶级和资产阶级的知识分子，即所谓市民阶级的知识分子。五四运动是在思想上和干部上准备了一九二一年中国共产党的成立，又准备了五卅运动[29]和北伐战争。当时的资产阶级知识分子，是五四运动的右翼，到了第二个时期，他们中间的大部分就和敌人妥协，站在反动方面了。","language":"中文","translation":false},{"id":"new-democracy-1-120","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第二个时期，以中国共产党的成立和五卅运动、北伐战争为标志，继续了并发展了五四运动时三个阶级的统一战线，吸引了农民阶级加入，并且在政治上形成了这个各阶级的统一战线，这就是第一次国共两党的合作。孙中山先生之所以伟大，不但因为他领导了伟大的辛亥革命（虽然是旧时期的民主革命），而且因为他能够“适乎世界之潮流，合乎人群之需要”，提出了联俄、联共、扶助农工三大革命政策，对三民主义作了新的解释，树立了三大政策的新三民主义。在这以前，三民主义是和教育界、学术界、青年界没有多大联系的，因为它没有提出反帝国主义的口号，也没有提出反封建社会制度和反封建文化思想的口号。在这以前，它是旧三民主义，这种三民主义是被人们看成为一部分人为了夺取政府权力，即是说为了做官，而临时应用的旗帜，看成为纯粹政治活动的旗帜。在这以后，出现了三大政策的新三民主义。由于国共两党的合作，由于两党革命党员的努力，这种新三民主义便被推广到了全中国，推广到了一部分教育界、学术界和广大青年学生之中。这完全是因为原来的三民主义发展成了反帝反封建的三大政策的新民主主义的三民主义之故；没有这一发展，三民主义思想的传播是不可能的。","language":"中文","translation":false},{"id":"new-democracy-1-121","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在这一时期中，这种革命的三民主义，成了国共两党和各个革命阶级的统一战线的政治基础，“共产主义是三民主义的好朋友”，两个主义结成了统一战线。以阶级论，则是无产阶级、农民阶级、城市小资产阶级、资产阶级的统一战线。那时，以共产党的《向导周报》[30]，国民党的上海《民国日报》[31]及各地报纸为阵地，曾经共同宣传了反帝国主义的主张，共同反对了尊孔读经的封建教育，共同反对了封建古装的旧文学和文言文，提倡了以反帝反封建为内容的新文学和白话文。在广东战争和北伐战争中，曾经在中国军队中灌输了反帝反封建的思想，改造了中国的军队。在千百万农民群众中，提出了打倒贪官污吏打倒土豪劣绅的口号，掀起了伟大的农民革命斗争。由于这些，再由于苏联的援助，就取得了北伐的胜利。但是大资产阶级一经爬上了政权，就立即结束了这次革命，转入了新的政治局面。","language":"中文","translation":false},{"id":"new-democracy-1-122","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第三个时期是一九二七年至一九三七年的新的革命时期。因为在前一时期的末期，革命营垒中发生了变化，中国大资产阶级转到了帝国主义和封建势力的反革命营垒，民族资产阶级也附和了大资产阶级，革命营垒中原有的四个阶级，这时剩下了三个，剩下了无产阶级、农民阶级和其它小资产阶级（包括革命知识分子），所以这时候，中国革命就不得不进入一个新的时期，而由中国共产党单独地领导群众进行这个革命。这一时期，是一方面反革命的“围剿”，又一方面革命深入的时期。这时有两种反革命的“围剿”：军事“围剿”和文化“围剿”。也有两种革命深入：农村革命深入和文化革命深入。这两种“围剿”，在帝国主义策动之下，曾经动员了全中国和全世界的反革命力量，其时间延长至十年之久，其残酷是举世未有的，杀戮了几十万共产党员和青年学生，摧残了几百万工人农民。从当事者看来，似乎以为共产主义和共产党是一定可以“剿尽杀绝”的了。但结果却相反，两种“围剿”都惨败了。作为军事“围剿”的结果的东西，是红军的北上抗日；作为文化“围剿”的结果的东西，是一九三五年“一二九”青年革命运动的爆发。而作为这两种“围剿”之共同结果的东西，则是全国人民的觉悟。这三者都是积极的结果。其中最奇怪的，是共产党在国民党统治区域内的一切文化机关中处于毫无抵抗力的地位，为什么文化“围剿”也一败涂地了？这还不可以深长思之吗？而共产主义者的鲁迅，却正在这一“围剿”中成了中国文化革命的伟人。","language":"中文","translation":false},{"id":"new-democracy-1-123","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"反革命“围剿”的消极的结果，则是日本帝国主义打进来了。这就是为什么全国人民至今还是非常痛恨那十年反共的最大原因。","language":"中文","translation":false},{"id":"new-democracy-1-124","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这一时期的斗争，在革命方面，是坚持了人民大众反帝反封建的新民主主义和新三民主义；在反革命方面，则是在帝国主义指挥下的地主阶级和大资产阶级联盟的专制主义。这种专制主义，在政治上，在文化上，腰斩了孙中山的三大政策，腰斩了他的新三民主义，造成了中华民族的深重的灾难。","language":"中文","translation":false},{"id":"new-democracy-1-125","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"第四个时期就是现在的抗日战争时期。在中国革命的曲线运动中，又来了一次四个阶级的统一战线，但是范围更放大了，上层阶级包括了很多统治者，中层阶级包括了民族资产阶级和小资产阶级，下层阶级包括了一切无产者，全国各阶层都成了盟员，坚决地反抗了日本帝国主义。这个时期的第一阶段，是在武汉失陷以前。这时全国各方面是欣欣向荣的，政治上有民主化的趋势，文化上有较普遍的动员。武汉失陷以后，为第二阶段，政治情况发生了许多变化，大资产阶级的一部分，投降了敌人，其另一部分也想早日结束抗战。在文化方面，反映这种情况，就出现了叶青、张君劢等人的反动和言论出版的不自由。","language":"中文","translation":false},{"id":"new-democracy-1-126","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"为了克服这种危机，必须同一切反抗战、反团结、反进步的思想进行坚决的斗争，不击破这些反动思想，抗战的胜利是无望的。这一斗争的前途如何？这是全国人民心目中的大问题。依据国内国际条件，不论抗战路程上有多少困难，中国人民总是要胜利的。全部中国史中，五四运动以后二十年的进步，不但赛过了以前的八十年，简直赛过了以前的几千年。假如再有二十年的工夫，中国的进步将到何地，不是可以想得到的吗？一切内外黑暗势力的猖獗，造成了民族的灾难；但是这种猖獗，不但表示了这些黑暗势力的还有力量，而且表示了它们的最后挣扎，表示了人民大众逐渐接近了胜利。这在中国是如此，在整个东方也是如此，在世界也是如此。","language":"中文","translation":false},{"id":"new-democracy-1-127","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一四 文化性质问题上的偏向","language":"中文","translation":false},{"id":"new-democracy-1-128","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一切新的东西都是从艰苦斗争中锻炼出来的。新文化也是这样，二十年中有三个曲折，走了一个“之”字，一切好的坏的东西都考验出来了。","language":"中文","translation":false},{"id":"new-democracy-1-129","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"资产阶级顽固派，在文化问题上，和他们在政权问题上一样，是完全错误的。他们不知道中国新时期的历史特点，他们不承认人民大众的新民主主义的文化。他们的出发点是资产阶级专制主义，在文化上就是资产阶级的文化专制主义。一部分所谓欧美派的文化人[32]（我说的是一部分），他们曾经实际赞助过国民党政府的文化“剿共”，现在似乎又在赞助什么“限共”、“溶共”政策。他们不愿工农在政治上抬头，也不愿工农在文化上抬头。资产阶级顽固派的这条文化专制主义的路是走不通的，它同政权问题一样，没有国内国际的条件。因此，这种文化专制主义，也还是“收起”为妙。","language":"中文","translation":false},{"id":"new-democracy-1-130","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"当作国民文化的方针来说，居于指导地位的是共产主义的思想，并且我们应当努力在工人阶级中宣传社会主义和共产主义，并适当地有步骤地用社会主义教育农民及其它群众。但整个的国民文化，现在也还不是社会主义的。","language":"中文","translation":false},{"id":"new-democracy-1-131","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"新民主主义的政治、经济、文化，由于其都是无产阶级领导的缘故，就都具有社会主义的因素，并且不是普通的因素，而是起决定作用的因素。但是就整个政治情况、整个经济情况和整个文化情况说来，却还不是社会主义的，而是新民主主义的。因为在现阶段革命的基本任务主要地是反对外国的帝国主义和本国的封建主义，是资产阶级民主主义的革命，还不是以推翻资本主义为目标的社会主义的革命。就国民文化领域来说，如果以为现在的整个国民文化就是或应该是社会主义的国民文化，这是不对的。这是把共产主义思想体系的宣传，当作了当前行动纲领的实践；把用共产主义的立场和方法去观察问题、研究学问、处理工作、训练干部，当作了中国民主革命阶段上整个的国民教育和国民文化的方针。以社会主义为内容的国民文化必须是反映社会主义的政治和经济的。我们在政治上经济上有社会主义的因素，反映到我们的国民文化也有社会主义的因素；但就整个社会来说，我们现在还没有形成这种整个的社会主义的政治和经济，所以还不能有这种整个的社会主义的国民文化。由于现时的中国革命是世界无产阶级社会主义革命的一部分，因而现时的中国新文化也是世界无产阶级社会主义新文化的一部分，是它的一个伟大的同盟军；这种一部分，虽则包含社会主义文化的重大因素，但是就整个国民文化来说，还不是完全以社会主义文化的资格去参加，而是以人民大众反帝反封建的新民主主义文化的资格去参加的。由于现时中国革命不能离开中国无产阶级的领导，因而现时的中国新文化也不能离开中国无产阶级文化思想的领导，即不能离开共产主义思想的领导。但是这种领导，在现阶段是领导人民大众去作反帝反封建的政治革命和文化革命，所以现在整个新的国民文化的内容还是新民主主义的，不是社会主义的。","language":"中文","translation":false},{"id":"new-democracy-1-132","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"在现时，毫无疑义，应该扩大共产主义思想的宣传，加紧马克思列宁主义的学习，没有这种宣传和学习，不但不能引导中国革命到将来的社会主义阶段上去，而且也不能指导现时的民主革命达到胜利。但是我们既应把对于共产主义的思想体系和社会制度的宣传，同对于新民主主义的行动纲领的实践区别开来；又应把作为观察问题、研究学问、处理工作、训练干部的共产主义的理论和方法，同作为整个国民文化的新民主主义的方针区别开来。把二者混为一谈，无疑是很不适当的。","language":"中文","translation":false},{"id":"new-democracy-1-133","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"由此可知，现阶段上中国新的国民文化的内容，既不是资产阶级的文化专制主义，又不是单纯的无产阶级的社会主义，而是以无产阶级社会主义文化思想为领导的人民大众反帝反封建的新民主主义。","language":"中文","translation":false},{"id":"new-democracy-1-134","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"一五 民族的科学的大众的文化","language":"中文","translation":false},{"id":"new-democracy-1-135","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种新民主主义的文化是民族的。它是反对帝国主义压迫，主张中华民族的尊严和独立的。它是我们这个民族的，带有我们民族的特性。它同一切别的民族的社会主义文化和新民主主义文化相联合，建立互相吸收和互相发展的关系，共同形成世界的新文化；但是决不能和任何别的民族的帝国主义反动文化相联合，因为我们的文化是革命的民族文化。中国应该大量吸收外国的进步文化，作为自己文化食粮的原料，这种工作过去还做得很不够。这不但是当前的社会主义文化和新民主主义文化，还有外国的古代文化，例如各资本主义国家启蒙时代的文化，凡属我们今天用得着的东西，都应该吸收。但是一切外国的东西，如同我们对于食物一样，必须经过自己的口腔咀嚼和胃肠运动，送进唾液胃液肠液，把它分解为精华和糟粕两部分，然后排泄其糟粕，吸收其精华，才能对我们的身体有益，决不能生吞活剥地毫无批判地吸收。所谓“全盘西化”[33]的主张，乃是一种错误的观点。形式主义地吸收外国的东西，在中国过去是吃过大亏的。中国共产主义者对于马克思主义在中国的应用也是这样，必须将马克思主义的普遍真理和中国革命的具体实践完全地恰当地统一起来，就是说，和民族的特点相结合，经过一定的民族形式，才有用处，决不能主观地公式地应用它。公式的马克思主义者，只是对于马克思主义和中国革命开玩笑，在中国革命队伍中是没有他们的位置的。中国文化应有自己的形式，这就是民族形式。民族的形式，新民主主义的内容——这就是我们今天的新文化。","language":"中文","translation":false},{"id":"new-democracy-1-136","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种新民主主义的文化是科学的。它是反对一切封建思想和迷信思想，主张实事求是，主张客观真理，主张理论和实践一致的。在这点上，中国无产阶级的科学思想能够和中国还有进步性的资产阶级的唯物论者和自然科学家，建立反帝反封建反迷信的统一战线；但是决不能和任何反动的唯心论建立统一战线。共产党员可以和某些唯心论者甚至宗教徒建立在政治行动上的反帝反封建的统一战线，但是决不能赞同他们的唯心论或宗教教义。中国的长期封建社会中，创造了灿烂的古代文化。清理古代文化的发展过程，剔除其封建性的糟粕，吸收其民主性的精华，是发展民族新文化提高民族自信心的必要条件；但是决不能无批判地兼收并蓄。必须将古代封建统治阶级的一切腐朽的东西和古代优秀的人民文化即多少带有民主性和革命性的东西区别开来。中国现时的新政治新经济是从古代的旧政治旧经济发展而来的，中国现时的新文化也是从古代的旧文化发展而来，因此，我们必须尊重自己的历史，决不能割断历史。但是这种尊重，是给历史以一定的科学的地位，是尊重历史的辩证法的发展，而不是颂古非今，不是赞扬任何封建的毒素。对于人民群众和青年学生，主要地不是要引导他们向后看，而是要引导他们向前看。","language":"中文","translation":false},{"id":"new-democracy-1-137","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"这种新民主主义的文化是大众的，因而即是民主的。它应为全民族中百分之九十以上的工农劳苦民众服务，并逐渐成为他们的文化。要把教育革命干部的知识和教育革命大众的知识在程度上互相区别又互相联结起来，把提高和普及互相区别又互相联结起来。革命文化，对于人民大众，是革命的有力武器。革命文化，在革命前，是革命的思想准备；在革命中，是革命总战线中的一条必要和重要的战线。而革命的文化工作者，就是这个文化战线上的各级指挥员。“没有革命的理论，就不会有革命的运动”[34]，可见革命的文化运动对于革命的实践运动具有何等的重要性。而这种文化运动和实践运动，都是群众的。因此，一切进步的文化工作者，在抗日战争中，应有自己的文化军队，这个军队就是人民大众。革命的文化人而不接近民众，就是“无兵司令”，他的火力就打不倒敌人。为达此目的，文字必须在一定条件下加以改革，言语必须接近民众，须知民众就是革命文化的无限丰富的源泉。","language":"中文","translation":false},{"id":"new-democracy-1-138","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"民族的科学的大众的文化，就是人民大众反帝反封建的文化，就是新民主主义的文化，就是中华民族的新文化。","language":"中文","translation":false},{"id":"new-democracy-1-139","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"新民主主义的政治、新民主主义的经济和新民主主义的文化相结合，这就是新民主主义共和国，这就是名副其实的中华民国，这就是我们要造成的新中国。","language":"中文","translation":false},{"id":"new-democracy-1-140","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"新中国站在每个人民的面前，我们应该迎接它。","language":"中文","translation":false},{"id":"new-democracy-1-141","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"新中国航船的桅顶已经冒出地平线了，我们应该拍掌欢迎它。","language":"中文","translation":false},{"id":"new-democracy-1-142","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"举起你的双手吧，新中国是我们的。","language":"中文","translation":false},{"id":"new-democracy-1-143","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[1]《中国文化》是一九四○年二月在延安创刊的杂志，一九四一年八月终刊。","language":"中文","translation":false},{"id":"new-democracy-1-144","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[2]“政治是经济的最集中的表现”一语，见列宁《论工会、目前局势及托洛茨基同志的错误》（《列宁全集》第40卷，人民出版社1986年版，第212页）。","language":"中文","translation":false},{"id":"new-democracy-1-145","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[3] 见马克思《〈政治经济学批判〉序言》（《马克思恩格斯选集》第2卷，人民出版社1972年版，第82页）。","language":"中文","translation":false},{"id":"new-democracy-1-146","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[4] 见马克思《关于费尔巴哈的提纲》。新的译文是：“哲学家们只是用不同的方式解释世界，而问题在于改变世界。”（《马克思恩格斯选集》第1卷，人民出版社1972年版，第19页）","language":"中文","translation":false},{"id":"new-democracy-1-147","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[5] 见本书第一卷《论反对日本帝国主义的策略》注〔35〕。","language":"中文","translation":false},{"id":"new-democracy-1-148","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[6] 见本书第一卷《论反对日本帝国主义的策略》注〔36〕。","language":"中文","translation":false},{"id":"new-democracy-1-149","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[7] 见本卷《中国革命和中国共产党》注〔19〕。","language":"中文","translation":false},{"id":"new-democracy-1-150","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[8] 见本书第一卷《矛盾论》注〔22〕。","language":"中文","translation":false},{"id":"new-democracy-1-151","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[9] 见本卷《论持久战》注〔12〕。","language":"中文","translation":false},{"id":"new-democracy-1-152","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[10] 见本书第一卷《湖南农民运动考察报告》注〔3〕。","language":"中文","translation":false},{"id":"new-democracy-1-153","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[11] 见本书第一卷《实践论》注〔6〕。","language":"中文","translation":false},{"id":"new-democracy-1-154","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[12] 见斯大林《十月革命和民族问题》（《斯大林选集》上卷，人民出版社1979年版，第126页）。","language":"中文","translation":false},{"id":"new-democracy-1-155","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[13] 见本书第一卷《论反对日本帝国主义的策略》注〔31〕。","language":"中文","translation":false},{"id":"new-democracy-1-156","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[14] 参见列宁《帝国主义是资本主义的最高阶段》（《列宁全集》第27卷，人民出版社1990年版，第437页）。","language":"中文","translation":false},{"id":"new-democracy-1-157","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[15] 指蒋介石叛变革命以后国民党政府所进行的一系列的反苏运动：一九二七年十二月十三日国民党反动派枪杀广州苏联副领事；同月十四日南京国民党政府下“绝俄令”，不承认各省苏联领事，勒令各省苏联商业机构停止营业。一九二九年七月蒋介石又受帝国主义的唆使，在东北向苏联挑衅，不久引起军事冲突。","language":"中文","translation":false},{"id":"new-democracy-1-158","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[16] 基马尔，又译凯末尔（一八八一——一九三八），第一次世界大战后土耳其民族商业资产阶级的代表。在第一次世界大战后，英帝国主义指使希腊对土耳其进行武装侵略，土耳其人民得到苏俄的援助，于一九二二年战胜了希腊军队。一九二三年土耳其建立了资产阶级专政的共和国，基马尔被选为总统。","language":"中文","translation":false},{"id":"new-democracy-1-159","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[17] 一九五八年九月二日，毛泽东在同巴西记者马罗金和杜特列夫人谈话时对这个观点作了修正。他指出：在《新民主主义论》中讲到，第二次世界大战爆发以后，殖民地和半殖民地的资产阶级，要就是站在帝国主义战线方面，要就是站在反帝国主义战线方面，没有其它的道路。事实上，这种观点只适合于一部分国家。对于印度、印度尼西亚、阿拉伯联合共和国（按：阿拉伯联合共和国，一九五八年由埃及同叙利亚合并组成。一九六一年叙利亚脱离阿联，成立阿拉伯叙利亚共和国。一九七一年阿联改名为阿拉伯埃及共和国）等国家却不适用，它们是民族主义国家。拉丁美洲也有许多这样的国家。这些国家既不站在帝国主义的一边，也不站在社会主义的一边，而站在中立的立场，不参加双方的集团，这是适合于它们现时的情况的。","language":"中文","translation":false},{"id":"new-democracy-1-160","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[18] 见本卷《必须制裁反动派》注〔5〕。","language":"中文","translation":false},{"id":"new-democracy-1-161","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[19] 毛泽东在这里是指张君劢及其一伙。张君劢在五四运动后宣扬一种自称为“新玄学”的唯心主义的哲学思想，提倡自孔孟以至宋明理学的所谓“精神文明”，同时又鼓吹“自由意志”，一九二三年引起了一场“科学与玄学”的争论，当时张君劢被称为“玄学鬼”。一九三八年十二月，他经蒋介石授意，发表《致毛泽东先生一封公开信》，主张取消八路军、新四军及陕甘宁边区，要求“将马克思主义暂搁一边”，为蒋介石张目。","language":"中文","translation":false},{"id":"new-democracy-1-162","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[20] 见一九三七年九月二十二日发表的《中共中央为公布国共合作宣言》。","language":"中文","translation":false},{"id":"new-democracy-1-163","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[21] 见一九二四年孙中山《三民主义•民生主义》第二讲（《孙中山全集》第9卷，中华书局1986年版，第386页）。","language":"中文","translation":false},{"id":"new-democracy-1-164","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[22] 一九三三年，国民党中央组织部部长陈立夫发表《唯生论》一书，宣扬宇宙的实质是“生命之流”，万物的根本问题在于“求生”，用来反对阶级斗争的学说；并认为宇宙万物各有一个重心，以人类社会现象来说，就是只能有一个领袖，否则就无法维持其均衡和生存。这种唯生主义的理论是为国民党反动派实行法西斯专政服务的。","language":"中文","translation":false},{"id":"new-democracy-1-165","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[23] 山西军阀阎锡山曾标榜过“按劳分配”的口号。其主要内容是：用军事方法强迫劳动人民在村公所控制的固定份地上，或官办的工厂、商店里，从事农奴式的劳动，只将很小一部分劳动果实，按劳动情况分配给劳动者。","language":"中文","translation":false},{"id":"new-democracy-1-166","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[24] 汪精卫在一九二七年叛变革命之后不久写过一篇东西，题为《夹攻之奋斗》（载1927年7月25日《汉口民国日报》）。","language":"中文","translation":false},{"id":"new-democracy-1-167","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[25] 一九二五年三月三十日，斯大林在共产国际执行委员会南斯拉夫委员会会议上的演讲《论南斯拉夫的民族问题》中说：“……农民是民族运动的主力军，没有农民这支军队，就没有而且也不可能有声势浩大的民族运动。所谓民族问题实质上是农民问题，正是指这一点说的。”（《斯大林全集》第7卷，人民出版社1958年版，第61页）","language":"中文","translation":false},{"id":"new-democracy-1-168","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[26] 在中国共产党内，曾经有些教条主义者讥笑毛泽东注重农村革命根据地为“上山主义”。毛泽东在这里是用教条主义者的这句讽刺话，说明农村革命根据地的伟大作用。","language":"中文","translation":false},{"id":"new-democracy-1-169","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[27] “学校”指当时效法欧美资本主义国家的教育制度。“科举”指中国原有的封建考试制度。十九世纪末，中国提倡“维新”的知识分子主张废除科举，兴办学校；封建顽固派竭力反对这种主张。","language":"中文","translation":false},{"id":"new-democracy-1-170","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[28] 一九一九年的五四爱国运动，至六月初转入一个新的阶段，以六月三日北京学生反抗军警镇压，集会讲演开始，由学生的罢课，发展到上海、南京、天津、杭州、武汉、九江及山东、安徽各地的工人罢工，商人罢市。五四运动至此遂成为有无产阶级、城市小资产阶级和民族资产阶级参加的广大群众运动。","language":"中文","translation":false},{"id":"new-democracy-1-171","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[29] 见本书第一卷《中国社会各阶级的分析》注〔9〕。","language":"中文","translation":false},{"id":"new-democracy-1-172","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[30] 《向导》周报是中共中央的机关报，一九二二年九月十三日在上海创刊，一九二七年七月十八日在武汉终刊。","language":"中文","translation":false},{"id":"new-democracy-1-173","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[31] 上海《民国日报》于一九一六年一月创刊，国民党一大后正式成为国民党的机关报。在中国共产党的影响和国民党左派的努力下，曾经宣传过反对帝国主义和反对封建主义的主张。一九二五年十一月以后，曾被西山会议派把持，成为国民党右派的报纸。一九四七年停刊。","language":"中文","translation":false},{"id":"new-democracy-1-174","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[32] 毛泽东在这里所说的一部分欧美派文化人是指以胡适等为代表的一些人物。","language":"中文","translation":false},{"id":"new-democracy-1-175","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[33] 所谓“全盘西化”，是一部分资产阶级学者的主张。他们主张中国一切东西都要完全模仿欧美资本主义国家。","language":"中文","translation":false},{"id":"new-democracy-1-176","author":"毛泽东","title":"新民主主义论","location":"新民主主义论（一九四○年一月）","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-194001.htm","text":"[34] 见列宁《俄国社会民主党人的任务》（《列宁全集》第2卷，人民出版社1984年版，第443页）；并见列宁《怎么办？》第一章第四节（《列宁全集》第6卷，人民出版社1986年版，第23页）。","language":"中文","translation":false},{"id":"serve-people-1-1","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"中文马克思主义文库 -> 毛泽东","language":"中文","translation":false},{"id":"serve-people-1-2","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"* 这是毛泽东在中共中央警备团追悼张思德的会上的讲演。","language":"中文","translation":false},{"id":"serve-people-1-3","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"我们的共产党和共产党所领导的八路军、新四军，是革命的队伍。我们这个队伍完全是为着解放人民的，是彻底地为人民的利益工作的。张思德[1]同志就是我们这个队伍中的一个同志。","language":"中文","translation":false},{"id":"serve-people-1-4","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"人总是要死的，但死的意义有不同。中国古时候有个文学家叫做司马迁的说过：“人固有一死，或重于泰山，或轻于鸿毛。”[2]为人民利益而死，就比泰山还重；替法西斯卖力，替剥削人民和压迫人民的人去死，就比鸿毛还轻。张思德同志是为人民利益而死的，他的死是比泰山还要重的。","language":"中文","translation":false},{"id":"serve-people-1-5","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"因为我们是为人民服务的，所以，我们如果有缺点，就不怕别人批评指出。不管是什么人，谁向我们指出都行。只要你说得对，我们就改正。你说的办法对人民有好处，我们就照你的办。“精兵简政”这一条意见，就是党外人士李鼎铭[3]先生提出来的；他提得好，对人民有好处，我们就采用了。只要我们为人民的利益坚持好的，为人民的利益改正错的，我们这个队伍就一定会兴旺起来。","language":"中文","translation":false},{"id":"serve-people-1-6","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"我们都是来自五湖四海，为了一个共同的革命目标，走到一起来了。我们还要和全国大多数人民走这一条路。我们今天已经领导着有九千一百万人口的根据地[4]，但是还不够，还要更大些，才能取得全民族的解放。我们的同志在困难的时候，要看到成绩，要看到光明，要提高我们的勇气。中国人民正在受难，我们有责任解救他们，我们要努力奋斗。要奋斗就会有牺牲，死人的事是经常发生的。但是我们想到人民的利益，想到大多数人民的痛苦，我们为人民而死，就是死得其所。不过，我们应当尽量地减少那些不必要的牺牲。我们的干部要关心每一个战士，一切革命队伍的人都要互相关心，互相爱护，互相帮助。","language":"中文","translation":false},{"id":"serve-people-1-7","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"今后我们的队伍里，不管死了谁，不管是炊事员，是战士，只要他是做过一些有益的工作的，我们都要给他送葬，开追悼会。这要成为一个制度。这个方法也要介绍到老百姓那里去。村上的人死了，开个追悼会。用这样的方法，寄托我们的哀思，使整个人民团结起来。","language":"中文","translation":false},{"id":"serve-people-1-8","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"[1] 张思德，四川仪陇人，中央警备团的战士。他在一九三三年参加红军，经历长征，负过伤，是一个忠实为人民服务的共产党员。一九四四年九月五日在陕北安塞县山中烧炭，因炭窑崩塌而牺牲。","language":"中文","translation":false},{"id":"serve-people-1-9","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"[2] 司马迁，中国西汉时期著名的文学家和历史学家，着有《史记》一百三十篇。此处引语见《汉书•司马迁传》中的《报任少卿书》，原文是：“人固有一死，死有重于泰山，或轻于鸿毛。”","language":"中文","translation":false},{"id":"serve-people-1-10","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"[3] 李鼎铭（一八八一——一九四七），陕西米脂人，开明绅士。他在一九四一年十一月陕甘宁边区第二届参议会上提出“精兵简政”的提案，并在这次会议上当选为陕甘宁边区政府副主席。","language":"中文","translation":false},{"id":"serve-people-1-11","author":"毛泽东","title":"为人民服务","location":"为人民服务（一九四四年九月八日）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/maozedong/marxist.org-chinese-mao-19440908.htm","text":"[4] 这是指当时陕甘宁边区和华北、华中、华南各抗日根据地所拥有的人口的总数。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-1","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中文马克思主义文库 -> 恩维尔·霍查 -> 《帝国主义与革命》（1978）","language":"中文","translation":false},{"id":"hoxha-imperialism-1-2","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"第一章 帝国主义和现代修正主义的策略","language":"中文","translation":false},{"id":"hoxha-imperialism-1-3","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"↘ 苏联社会帝国主义的战略","language":"中文","translation":false},{"id":"hoxha-imperialism-1-4","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"↘ 中国社会帝国主义的战略","language":"中文","translation":false},{"id":"hoxha-imperialism-1-5","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"↘ 在帝国主义和社会帝国主义的全球战略中，铁托主义和其他修正主义思潮的作用","language":"中文","translation":false},{"id":"hoxha-imperialism-1-6","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"↘ 革命——战胜无产阶级和人民的敌人阴谋诡计的唯一武器","language":"中文","translation":false},{"id":"hoxha-imperialism-1-7","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在分析当前国际形势和世界革命运动的情况后,阿尔巴尼亚劳动党的第七次全国代表大会指出帝国主义和现代修正主义对各民族革命和解放运动带来的危机，强调对它们无情的打击和对全球马列主义运动的积极支持之必要性。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-8","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这些问题之所以具有重要意义，是因为社会主义建设、加强无产阶级专政和保卫祖国的斗争，都离不开国际形势和世界发展的总进程。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-9","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"今天，奴役和剥削无产阶级人民的代表----美帝及其走狗、苏联社会帝国主义、中国社会帝国主义、大资产阶级和大反动派等黑暗势力奴役和剥削无产阶级人民的代表，已经起来反对和正在同马列主义作斗争。社会民主主义、现代修正主义等反革命思潮和许多其他反革命思潮，也都起来反对我们的革命思想。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-10","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"我们同一切敌人的斗争，必须以马列主义理论和世界无产阶级运动为基础。如果我们正确地辩证地分析国际局势，分析正在发生的事件，正确地分析各种相互矛盾和斗争的社会力量的目标和目的，我们在理论方面的斗争就会取得成功。科学分析国际形势，明确革命斗争的战略，有助于我们在不同的情况下确定正确的策略，从而赢得一场又一场的战斗。这就是我们党一贯的作风。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-11","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"社会主义同资本主义进行斗争，世界无产阶级同资本主义、资产阶级进行残酷的、持续的斗争，世界人民同内外压迫者进行斗争。世界无产阶级是在马列主义思想指导下进行斗争的，马列主义思想说明了世界无产阶级进行斗争的必要性，并动员了斗争中的各种力量。这就是为什么资本主义和帝国主义总是组织起来同马克思、恩格斯、列宁和斯大林的理论进行艰苦的斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-12","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"马克思发现了社会发展和革命变革的规律，社会从低级形态向高级形态过渡的规律。他对生产资料的私有制、资本主义的分配方式和资本主义攫取的剩余价值进行了科学的分析。他创立了科学的阶级理论和阶级斗争理论，明确了无产阶级推翻资产阶级、消灭资本主义制度、建立无产阶级专政、建设社会主义社会的斗争道路。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-13","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"世界各国的反动理论家都在千方百计地诋毁马克思的理论，诋毁它、歪曲它、反对它。但是，这一理论，作为一门真正的科学，已经成功地在进步人类思想中占主要地位，成为无产阶级和人民战胜敌人的有力武器。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-14","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"列宁把马克思主义理论应用并加以发展，给无产阶级及其先锋队马列主义政党提出了关于帝国主义和无产阶级革命条件的科学理论。列宁不仅在理论上而且在实践中发展了马克思主义。凭借马克思主义，他领导布尔什维克革命并取得了胜利。列宁的工作由斯大林进一步发展起来。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-15","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"伟大的十月革命的胜利，对帝国主义，对整个世界资本主义制度，做出了首次毁灭性的打击。它标志着资本主义普遍危机的开始，这场危机变得越来越严重。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-16","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"苏维埃国家的建立和巩固是一个巨大的胜利，它向无产阶级和人民表明，他们所面临的敌人----资本主义和帝国主义，是可以被征服和消灭的。苏联就是活生生的例子。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-17","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"世界帝国主义和资本主义联盟对他们在俄国十月革命中的失败感到愤怒，加强了政治、经济和军事压的手段，来对抗新的无产阶级国家和全世界马列主义思想的传播。帝国主义、反动资产阶级、欧洲和世界社会民主主义，连同资本主义的其他党派，挑起了对苏联的战争[1]。意大利和日本法西斯伴随着狂热，也挑起了第二次世界大战。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-18","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但是，在这场战争中，社会主义和马列主义的生命力得到了更加明显的证明，马列主义取得了胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-19","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"战胜法西斯后，世界发生了有利于社会主义的巨变。欧洲和亚洲建立了新的社会主义国家。以苏联为首的社会主义阵营诞生了。这是社会主义和马列主义的又一次伟大胜利，是资本主义和帝国主义的又一次巨大失败。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-20","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"资本主义制度在第二次世界大战后受到严重动摇，其平衡完全被打乱。德国、日本和意大利在战争中败北，经济一蹶不振。他们失去了以前占据的政治和军事地位。虽然在战争中取得了胜利，但是其他帝国主义国家，如英国和法国，在经济上和军事上都受到了极大的削弱，它们作为大国的作用已大大下降。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-21","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"随着殖民制度的崩溃，资本主义的普遍危机进一步加深。由于这种崩溃，出现了一系列新的民族国家，而在那些仍然是殖民地或半殖民地的国家，反对帝国主义枷锁的解放运动却在发展。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-22","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这些变化为世界范围内社会主义的胜利创造了极其有利的条件。由于严重的经济政治危机和人民群众日益增长的不满情绪，许多资本主义国家处于革命爆发的边缘。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-23","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在这种极其严重危急的情况下，美帝向他们伸出了援助之手。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-24","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"与其他帝国主义列强不同，美国在战争中变得更加强大。它不仅没有受到损害，反而积累了巨大的财富，极大地提高了它的经济和军事潜力，以及它的技术科学基础。这个帝国主义以人民的鲜血为养料，成为整个资本主义世界的唯一领导。美帝动员所有资本主义世界的反动势力去拯救资本主义旧秩序和镇压任何革命和民族解放运动，使它们濒临绝迹，破坏社会主义阵营和人民民主，恢复苏联的资本主义，在世界各地建立起霸权。为了达到它的目标，美帝连同世界资本，发动了它庞大的官僚机构和军事机器，它的巨大的经济、技术和财政潜力，它的一切人力。美帝帮助破碎的欧洲和日本资本主义的政治、经济和军事复苏，并取代崩溃的殖民制度，建立了一个新的剥削和掠夺制度——新殖民主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-25","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美帝发动了它的许多宣传人员、哲学家、经济学家、社会学家、作家等，开始了反对马列主义、共产主义、苏联和欧亚其他社会主义国家的疯狂运动。与此同时，美帝实行了公开的侵略政策。在美国，生活的每一个领域，经济、政治、意识形态、军队和科学，都被战争狂热、军事化和反共产主义所席卷。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-26","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"为了战胜社会主义，为了镇压革命解放运动，为了同马列主义理论的巨大影响作斗争，为了确立它在世界上的霸权地位，美帝采取了两条道路。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-27","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"首先是侵略和武装干预。美帝建立了北大西洋公约组织[2]、东南亚条约组织[3]等侵略军事集团，大量驻军在许多外国的领土上，在各个大陆上建立军事基地，并建立了强大的海军舰队，部署在整个海洋。为了打击镇压革命，他们在希腊、朝鲜、越南和其他地方进行了军事干预。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-28","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"二是对社会主义国家和共产党、工人党进行思想上的侵略和颠覆，使这些国家和党被和平演变。在这个方向上，美帝和世界资本作为一个整体，使用了强大的宣传手段和对意识形态的分散。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-29","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但是，战后正在复苏的美帝和世界资本主义，却面临着一个强大的敌人:以苏联为首的社会主义阵营，世界无产阶级和爱好自由的人民。因此，他们必须非常小心地对待这个由正确和明确的政策所指导的巨大的力量，由一种胜利的意识形态所指导的力量，这种意识形态已经越来越抓住工人、革命者和进步分子的内心和思想。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-30","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"尽管美帝和世界各国为镇压和消灭无产阶级革命运动和人民解放斗争作出了种种手段，但是他们的力量仍在不断增强和壮大。在斯大林的领导下，苏联很快地抚平了战争的创伤，在经济、科技等各个领域都取得了飞速的进步。在人民民主国家，社会主义的地位正在巩固。共产党和反帝民主运动正在在群众中扩大影响。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-31","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在这种情况下，世界帝国主义和资本主义利用现代修正主义来反对社会主义和人民解放运动，南斯拉夫成为了第一个。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-32","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫，一个被称为人民民主的国家，站出来反对苏联，并与之发生公开的意识形态和政治冲突，这对世界资本主义来说是一个幸运的消息，因为在社会主义阵营中有一个成员国背叛了。世界资本主义对这一事件给予了极大的宣传，帮助它与社会主义和革命作斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-33","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但是，铁托分子的背叛，虽然对革命和社会主义事业造成了极大的损害，但却没有像资产阶级和反动分子所希望的那样，成功分裂社会主义阵营和共产主义运动。全世界的共产主义者和革命家都严厉地谴责了这种背叛行径，指出了铁托主义作为帝国主义的走狗反对共产主义所构成的威胁。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-34","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"正是赫鲁晓夫修正主义者在斯大林死后夺取了苏联的政权，在世界资本主义反对社会主义、革命和马列主义的斗争中，为世界资本主义做出了最大的“贡献”。赫鲁晓夫修正主义集团的出现，是第二次世界大战后帝国主义在政治和意识形态上的策略实现的最大胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-35","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"反革命分子篡夺苏联使美帝和资本主义世界欢欣鼓舞,因为最强大的社会主义国家,革命和人民解放运动的堡垒,在理论和实践中放弃了社会主义和马列主义道路,并易以反革命和资本主义作为基础。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-36","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"苏联的大转变导致了社会主义阵营和国际共产主义运动的分裂。它是影响现代修正主义在许多共产党中传播并产生负面影响的主要因素之一。赫鲁晓夫修正主义思潮严重损害了世界革命事业和社会主义事业。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-37","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"真正的马列主义者和革命力量与赫鲁晓夫修正主义之间展开了一场激烈的斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-38","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"从一开始,阿尔巴尼亚劳动党高举无情地、有原则地与苏联修正主义及其追随者斗争的旗帜,勇敢地捍卫了带来社会主义和人民解放的马列主义,就像与南斯拉夫的修正主义坚决斗争那样。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-39","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在全世界，真正的马列主义者和革命者也起来反对赫鲁晓夫的背叛。各国无产阶级革命队伍中出现了新的马列主义政党，担负着领导工人阶级和人民反对资产阶级、帝国主义和现代修正主义斗争的重任。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-40","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"帝国主义和修正主义最终消灭社会主义、消灭真正的国际共产主义运动和粉碎人民斗争的希望没有实现。赫鲁晓夫修正主义者很快就显露出他们的反马克思主义和反革命特征。人民看到苏联已经变成了一个帝国主义超级大国，同美国争夺世界霸权，并同美帝一道，成为革命、社会主义和世界人民的另一个大敌。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-41","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"另一方面,严峻的经济、金融、意识形态和政治危机席卷了整个资本主义和修正主义的世界,不仅清清楚楚展示了资本主义制度的进一步衰减及其不变的压迫和剥削的本质，同时也暴露出了美化资本主义秩序的所有现代修正主义者的蛊惑人心和虚伪。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-42","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但当全世界革命运动的发展和团结起来,当资本主义陷入了越来越紧的枷锁中，当赫鲁晓夫修正主义和现代修正主义的嘴脸暴露在无产阶级和人民的面前时，中国修正主义公然出现在世界舞台上，扼杀和破坏无产阶级和人民的革命斗争，成为美帝和国际大资产阶级的亲密盟友。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-43","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"当前，世界形势十分复杂。今天在国际舞台上活动的是各种帝国主义和社会帝国主义势力，它们一方面在同革命和人民自由作斗争，另一方面又在市场、势力范围和霸权问题上相互竞争和冲突。现在,除了美苏对抗以统治世界，还有中国社会帝国主义的扩张需求，日本军国主义的掠夺野心,西德帝国主义为至关重要的国际地位而奋起，欧洲共同市场[4]的激烈的竞争，这使它的眼睛转向了旧的殖民地。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-44","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这些因素进一步加剧了资本主义和修正主义世界的矛盾。同时,革命的前途和人民的解放并没有因铁托，中国，苏联修正主义的背叛而殆尽。恰恰相反,现在暂时的挫折后，革命正处于一个新的飞跃时期的边缘。它一定会沿着历史为它确定的道路向前迈进，并将在世界范围内取得胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-45","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"帝国主义、资本主义、修正主义在无产阶级和人民的无情报复面前是无法挽救的。没有什么能把他们从深刻的对立矛盾和无休止的危机、革命以及他们不可避免的灭亡中拯救出来。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-46","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"帝国主义正是在这种情况下，为了逃避即将到来的灾难，寻求新的道路，建立出新的战略和对策。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-47","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美帝和其他资本主义国家为了维护它们在世界上的霸权，为了保住资本主义和新殖民主义制度，为了以尽可能少的损失摆脱他们所掌握的大危机，进行了抵抗，并正在进行抵抗。他们曾努力并正在努力阻止人民和无产阶级实现他们解放的革命愿望。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-48","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在实现这些目标的抵抗中，在政治、经济和军事上占主导地位的美帝发挥了主要作用。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-49","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"革命与人民的敌人想造成这样一种印象，即由于世界上发生的变化和社会主义所遭受的失败，产生了与过去完全不同的情况。因此尽管它们彼此之间有着激烈的矛盾,美帝和世界资本主义-资产阶级,苏联社会帝国主义、中国社会帝国主义、现代修正主义、社会民主主义寻求妥协,制造一个“新社会”,使资本主义制度继续运作,避免革命,继续以新的方式方法压迫和剥削人民。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-50","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"帝国主义和资本主义已经认识到，他们现在不能再用以前的方法剥削世界人民了，因此，只要他们的制度不受威胁，他们就作出一些让步，以便把人民群众束缚起来，而这些让步是不会对他们造成伤害的。他们希望分配给那些他们已经建立了影响力的国家和小集团投资和信贷，来实现这一目标；或者通过武器，即要么直接参与战争，要么煽动一个国家反对另一个国家。局部战争使那些落入局部战争陷阱的国家更加受制于世界资本的霸权。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-51","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"西方和东方所有为世界资本服务的“理论家”都在努力为这个“新社会”寻找公式。目前他们找到了新的公式。苏联的资本主义修正主义社会是一个堕落的社会，他们在南斯拉夫的资本主义“自治”制度[5]和一些所谓的“第三世界”的社会主义倾向的政权中发现了这种形式。他们正在努力寻找一种资本主义的“新社会”------这种“新社会”也在中国的变体中-----目前正在逐渐形成。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-52","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"卡特总统在1977年5月22日发表了一个对外政策演说。他提出了一个据说是美国的新政策的概要,很明显在现状下，“新政策”的一般和基本的特征是超级大国应对无产阶级革命和民族解放战争一种对抗手段----由那些渴望从全球大资本的轭中，尤其是美帝和苏联修正主义的轭中将自己解放出来人们所发动的革命。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-53","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"正如我们前面所指出的，资本主义世界正在寻找一条走出深渊的道路，即使只是暂时的。当然，美帝正在努力寻找出路，并找寻可能的机会来与苏联社会帝国主义、北约盟国、中国以及其他工业化资本主义国家进行协调。卡特呼吁东方、西方和欧佩克[6]成员国共同努力，有效地帮助较贫穷的国家。美帝试图把这种合作表现为战争的唯一替代品、停止战争的唯一途径。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-54","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"卡特在演讲中表示，今天“我们已经从对共产主义的持续恐惧中解放出来，这种恐惧曾一度导致我们拥抱每一个被同样恐惧困扰的独裁者”。当然,当卡特—我们时代最血腥的帝国主义的忠实代表—讲出“摆脱了共产主义的恐惧”时,他指的是那些像南斯拉夫式、赫鲁晓夫式、中国式的共产主义----只是披着一层共产主义的皮。但资本主义-资产阶级还没有,也永远不会丧失对真正的共产主义的恐惧。相反，帝国主义和社会帝国主义总是害怕真正的共产主义，而且他们将更害怕共产主义。正是这种恐惧和畏缩，促使帝国主义和修正主义互相投入对方的怀抱，互相协调，寻求最适当的形式，以便延长它们的压迫和剥削统治的存在。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-55","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在这些深深的经济、政治和军事危机笼罩的时刻，美帝试图巩固帝国主义的胜利，通过苏联现代修正主义、前人民民主国家和中国的背叛来获利，并使它们成为阻止无产阶级和人民革命解放斗争的一堵屏障。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-56","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美国总统还承认，过去，出于对共产主义的恐惧，资本家和帝国主义者拥护和支持法西斯独裁者，如墨索里尼、希特勒、裕仁、佛朗哥等。法西斯是资本主义、资产阶级和世界帝国主义反对列宁、斯大林时期的苏联和世界无产阶级革命的最终武器。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-57","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美国总统满怀信心地宣称，共产主义(即修正主义)国家已经改变了它们的面貌，在这一点上他坚信自己没有错。他说:“这个体系不可能永远不变。”当然，他混淆了修正主义的背叛与真正的社会主义和共产主义。美帝认为赫鲁晓夫的苏联制度是世界资本主义的胜利，并由此推断，与苏联发生冲突的威胁已不那么强烈，尽管它并不否认与苏联之间存在着争夺霸权的矛盾和竞争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-58","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"卡特表示，美国政府将尽一切努力维持现状。换句话说，这意味着美帝和其他帝国主义国家将努力维护和巩固自己的地位，在这种现状下，他们希望通过共同努力，与友好国家和盟国一道，能够解决可能存在的分歧，而事实上，确实奏效了。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-59","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"最后，卡特说，“美国的政策必须建立在一个新的、更广泛的全球、地区和双边利益的基础上”。在分析了这种新的、更广泛的全球、地区和双边利益的“不同要素组合体”之后，他重申,“美国将会以它对北约所有的承诺为荣,北约必须是一个强大的组织,因为美国与大工业化民主国家联盟是必不可少的，它保护了我们共同的价值，正因此我们更应该为争取更好的生活而奋斗。”","language":"中文","translation":false},{"id":"hoxha-imperialism-1-60","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"可见，美国也正在同苏联现代修正主义者、中国修正主义者和“工业化的大民主国家”一道，努力创造一个“新现实”，一个“新世界”。换句话说，美国正在通过煽动，使其政策适应新的局势。为了保持现状，阻止苏联霸权主义的前进，削弱苏联社会帝国主义和赢取中国,它越来越致力于帝国主义阵营建设；为了平息无产阶级的革命斗争，美国必须做出一些虚假的政治让步。但在军事问题上的让步则一点没有，在使国家和人民处于奴役和控制之下的政策中，在利用其他国家的财富来支持自己的工业化的政策中，没有任何让步。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-61","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这是美国的新政策。我们清楚地看到，这绝不是一项新的政策，而是一项旧的掠夺性帝国主义、新殖民主义、残酷剥削人民及其财富的奴役政策，一项镇压革命和民族解放战争的政策。美帝现在要给这一旧的、永久的政策涂上一层据说是新的、崭新的油漆，使反革命分子，不论是否当权，都有武器来对付共产主义-----使无产阶级进行解放斗争的思想。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-62","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"与中国的资本主义和修正主义的“三个世界”理论相反，美帝仍然在进攻。它正在努力维护它的旧联盟，并创造对它自己有利和对苏联社会帝国主义或任何其他可能威胁到美帝力量的人不利的新联盟。特别引人注目的是它正在努力增强北约实力，北约一直是并仍然是一个扮演积极角色的政治和军事组织。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-63","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美国在其所有战略行动中没有使其与苏联的关系恶化到一定程度，而是继续与苏联进行战略武器限制谈判[7]，尽管卡特曾表示，美国将继续生产中子弹。尽管如此，在美国和苏联之间存在着维持现状的明显趋势。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-64","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"当然,美国和北约正在努力维持这种与苏联的现状,与此同时,他们有矛盾，但这些矛盾还没有达到足以证明中国有关欧洲战争迫在眉睫的论调是正确的程度。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-65","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"目前，美帝正在支持中国，使中国在军事上和经济上都更加强大。美国资本正大举涌入中国。在中国，不仅是主要的美国银行，还有美国政府，都在通过信贷进行大规模投资。美国正在大打中国牌，但同时也在两面下注。与此同时，它也在继续打出日本的牌。美国本身和日本之间想要细水长流般的和睦,希望他们之间的援助是相互的，这样，按照美国的目标，日本将得到加强，成为远东太平洋、东南亚的一个以色列，如果有必要，在时机成熟时，最终在与中国的对抗中也会成为以色列。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-66","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这就是中国与日本签订《友好条约》[8]的情况。但是，从许多角度来看，这个条约已经开始对世界的命运产生重大的危险和丑恶的影响，将来也会如此，因为密切的经济和军事合作将在日本和中国之间建立,创建单独的和联合势力范围将作为其目标,尤其是在亚洲、澳大利亚和整个太平洋地区。当然，这种合作将在同美国结盟和反对苏联社会帝国主义宣传战的阴影下建立。中日同盟的主要目的是遏制和削弱苏联，把它从西伯利亚、蒙古和其他地方驱逐出去，消除它在整个亚洲和大洋洲以及对所有东南亚国家联盟[9]成员国的影响。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-67","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这是美帝的战略，同时也是中国帝国主义和日本军国主义的战略。美国将尽力协助中国和日本，使它们处于它的指导下，加强与它们的联盟，并把它们丢向苏联对抗前线。但还有一种可能性,也许有朝一日，中国和日本追求的帝国主义和军国主义精神所奉行的邪恶、虚伪、建立帝国和无原则的政策,将使他们掉过头来反对帮助他们恢复的超级大国,就像德国在过去所做的那样,当它们成为可怕的法西斯强国时,会攻击美国的盟友，甚至与后者开战，就像希特勒时期德国那样。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-68","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美国将努力在中国力量和正在崛起的日本力量之间保持平衡。但某一个晴朗的早晨，这种平衡将从它的掌握中溜走，中日帝国主义-军国主义联盟将成为一个不仅是苏联,还有美国本身的威胁,因为中国和日本这两个亚洲帝国主义大国的利益，集中在它们在亚洲和其他地方的统治目标上，集中在削弱美帝和苏联社会帝国主义的目标上。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-69","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在北约中，美国占有主导地位，具有强大的军事、政治和经济影响力。然而，尽管它是统一的，在北约内部，从其各成员国的影响和一个国家在其他国家眼中的存在的观点出发，已经开始出现分化。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-70","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在本组织内，德意志联邦共和国一年比一年强大。它的经济和政治力量以及武器贸易都超出了欧洲共同市场的范围。现在我们可以说，西德的政策具有极权主义法西斯复仇主义的特点，谋求建立自己的势力范围。当然，这既不适合英国，也不适合法国，这是美国最初在北约的两个主要伙伴。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-71","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"西德寻求两个德国国家的统一,以创建一个强大的具有极深的军事潜力的国家，这将会威胁到苏联社会帝国主义，如果发生全面的战争，再与日本和中国结盟，就可能成为整个世界的威胁。它与中国的关系尤其密切。在欧洲国家中，它在与中国的贸易往来中占有主要地位。西德是欧洲最大、最强大的对华信贷、技术和现代武器供应商。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-72","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"英法两国对中国也很感兴趣，因此正在发展与中国的关系。然而，中国对波恩[10]更感兴趣。这让英国和法国感到担忧，因为变得更加强大后，德意志联邦共和国可能会比北约和欧洲共同市场的其他伙伴更具统治力。因此，我们注意到，英国和法国政府都谈到了与中国的友谊和关系，但他们也没有忘记强调，他们也想进一步发展与苏联的经济和友好关系。波恩也这么说，但它正在迅速发展与把自己视作苏联主要敌人的中国的关系。施特劳斯[11]周围的法西斯集团，希特勒时代的将军，波恩真正强大的复仇主义者，公开宣称自己是中国最亲密的盟友。因此，中国并不像法国和英国那样看待联邦德国。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-73","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"赫鲁晓夫在夺取了苏联的国家政权后，就把消灭无产阶级专政、恢复资本主义和把苏联变成帝国主义超级大国作为他的主要目标。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-74","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在斯大林死后，巩固了自己的地位以后,赫鲁晓夫和周围的组织首先发动攻击马列主义意识形态和开始通过攻击斯大林，把世界资本主义-资产阶级长期以来捏造的一切污蔑都指摘到他身上方法来废黜列宁主义。因此，赫鲁晓夫成为反对马列主义意识形态和苏联革命的资本主义愿望的代言人和执行者。他们开始有系统地清算苏联的整个社会主义结构，他们将苏维埃制度自由化，来把无产阶级专政的国家改造成资产阶级国家，把社会主义经济文化改造成资本主义经济文化。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-75","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"苏联从一个修正主义国家变成了一个社会帝国主义国家，建立了自己的战略和战术。赫鲁晓夫制定了一项政策，使他们能够用列宁主义的措辞来掩饰他们的一切活动。他们把自己的修正主义思想加以修饰，把它当作新时期的马列主义来欺骗无产阶级和人民。因此，他们可以告诉国内外的共产主义者，“在世界发展的新的政治、意识形态和经济条件下，苏联的革命正在继续。”,这场革命不仅在那里被宣传成继续，而且据他们说这个国家正在进入建设一个没有阶级的共产主义社会的阶段，在这个阶段，党和国家会消亡。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-76","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"共产党被剥夺了工人阶级先锋队的身份，被剥夺了国家和社会唯一的政治领导机构的身份，变成了一个由官僚和克格勃[12]控制的政党。苏联修正主义者把他们的党称为“全体人民的党”，把它缩小到不再是工人阶级的党，而是新苏维埃资产阶级的党。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-77","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"另一方面，苏联修正主义者把赫鲁晓夫的和平共处作为国际共产主义运动的总路线，把“同美帝的和平竞争”作为社会主义在苏联和其他国家取得胜利的道路。他们还宣布，无产阶级革命已经进入了一个新阶段，变成还可以通过无产阶级通过暴力夺取国家政权以外的其他方式取得胜利。他们认为，国家权力可以通过改革，以和平、议会和民主的方式获得。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-78","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"赫 鲁晓夫修正主义者以列宁和布尔什维克党的名义为赌注，竭尽全力将他们的反马克思主义路线，即在所有领域对马列主义理论的修正，强加给世界上所有的共产党。他们要全世界的共产党和工人党采取这种修正主义路线，把自己变成反革命的政党，变成资产阶级专政的盲目工具，为资本主义服务。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-79","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但这并没有完全达到他们的期望。首先也是最重要的原因是，阿尔巴尼亚劳动党在一贯执行马列主义和捍卫其纯洁性方面仍然毫不动摇。在这些时刻，也有一些其他的党，不是纯粹出于马列主义的原因，动摇了，没有完全接受赫鲁晓夫的方针，而有些党不情愿地接受了，但后来还是服从了。当时，中国共产党也反对赫鲁晓夫主义，但事实表明，它的出发点和目的与促使阿尔巴尼亚劳动党投身反对赫鲁晓夫修正主义的斗争的出发点和目的完全相反。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-80","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"随着赫鲁晓夫为代表的修正主义者掌权，他们也为自己的外交政策制定了纲领。同美帝一样，苏联的社会帝国主义也以扩张和霸权主义为外交政策基础，方法为军备竞赛、高压和讹诈，以及军事、经济和意识形态的侵略。这一政策的目的是建立社会帝国主义对全世界的统治。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-81","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在东欧国家，苏联正在实施典型的新殖民主义政策。这些国家的经济已变成苏联经济的附属物。《华沙条约》[13]服务于苏联，使这些国家处于它的控制之下，使它能够在那里驻扎大量军队，这与占领没有什么不同。《华沙条约》是为苏联社会帝国主义的高压、勒索和武装干涉政策服务的侵略军事条约。修正主义-帝国主义关于“社会主义共同体”、“社会主义分工”、“有限主权”、“社会主义经济一体化”等理论也服务于这种新殖民主义政策。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-82","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但是苏联的社会帝国主义并不满足于它对附庸国的统治。同其他帝国主义国家一样，苏联现在正在争取新的市场，争取势力范围，在各国投资，垄断原料来源，在非洲、亚洲、拉丁美洲和其他地方扩展其新殖民主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-83","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"苏联的社会帝国主义有一个完整的战略计划，包括一系列的经济、政治、思想和军事活动，目的是扩大它的扩张和霸权主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-84","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"与此同时，苏联的修正主义者正在用与美帝完全相同的手段和方法来破坏人民的革命和解放战争。通常，社会帝国主义者通过他们的工具——修正主义政党来运作。但是,根据场合和情况,他们还试图贿赂不发达国家的统治集团，提供奴役经济的“援助”，以便在这些国家立足，煽动不同派系之间的武装冲突，支持一方或另一方，组织阴谋和暴动，使亲苏联政权掌权，甚至采取直接军事干预， 像在古巴，在安哥拉、埃塞俄比亚、和其他地方一样。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-85","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"苏联社会帝国主义以援助和支持革命力量、革命和社会主义建设为借口，进行干涉和霸权主义、新殖民主义的活动。实际上，他们帮助反革命。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-86","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"修正主义苏联试图通过把自己表现为一个奉行列宁主义和国际主义政策的国家，作为新的民族国家、不发达国家的盟友、朋友和捍卫者等面貌，开辟实现其扩张主义、新殖民主义计划的道路。苏联修正主义者鼓吹通过与苏联和所谓的社会主义共同体建立联系，这些国家在自由和独立的道路上，甚至在社会主义的道路上，都能取得成功。他们宣称这是“当今世界发展的主要动力”。这就是为什么他们还炮制了“非资本主义发展道路”“社会主义倾向国家”等理论。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-87","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"苏联社会帝国主义的战略，不管他们装什么样子，都与社会主义和列宁主义毫无共同之处。这是一个掠夺性帝国主义国家的战略，它想把它的霸权和统治扩展到所有大陆上的所有国家。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-88","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"修正主义苏联所奉行的这种霸权主义和新殖民主义政策，必然与美国所奉行的和中国也已开始实行的政策发生冲突。这是帝国主义者在世界分裂斗争中的利益冲突。正是这些利益瓜葛,让一个超级大国对抗另一个超级大国,推动它们使用所有的力量和手段处理削弱其竞争对手或竞争对手们,尽管冲突尚未恶化到武装冲突的程度。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-89","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"种种发生的事件和事实越来越清楚地表明，中国正在越来越深地陷入修正主义、资本主义和帝国主义的泥潭。在这条道路上，它正在努力实现自己国家层面的一系列战略目标。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-90","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在国家层面上，中国社会帝国主义设定的任务为消除一切解放后可能会采取的社会主义性质的元素，并确立基层和上层的资本主义制度，通过在本世纪末实现所谓的工业，农业，军队和科学的“四个现代化”，来成为资本主义强国。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-91","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国社会帝国主义者正在努力建立一个国家内部组织机关，以确保中国新老走资本主义的资产阶级对中国人民的统治。中国修正主义企图以法西斯主义的方式，通过棍棒和压迫来建立这个组织和这种统治。它正在努力在军队和基层群众之间建立统一关系，以便后者为这支压迫人民的军队服务。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-92","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"最引起中国领导人注意并可能在中国实施的形式和方法是铁托分子的形态和方法，特别是南斯拉夫的“自治”制度。中国各部门和各界人士组成的许多委员会和代表团都被派去实地研究这一制度和南斯拉夫资本主义式的“社会主义”大体的经验。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-93","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这一制度的实施和实践已经起步。然而，另一方面，中国的修正主义领导人不可能不看到铁托“自治”的失败，不可能不考虑到他们的国家的情况与南斯拉夫的情况完全不同。除此之外，他们还认为有必要借鉴资本主义的许多形式和方法，他们认为这些形式和方法在美国、西德、日本和其他资产阶级国家已经证明了它们的“有效性”。显然，中国正在建立和发展的资本主义制度将是各种修正主义、资本主义和中国传统形式方法的混合体。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-94","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国修正主义要成为资本主义大国，需要一段和平时期。中国共产党第十一次全国代表大会[14]的召开，就是与这种必要性相联系的。确保这样的秩序。一方面要求建立法西斯独裁式的资本主义制度，另一方面，中国党和国家历来存在的对立集团之间的相互和平与妥协，也必须毫不动摇地保持下去。时间将告诉我们，这种秩序与和平将在多大程度上得到保证。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-95","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在把中国变成超级大国的政策中，中国领导人的目标是从美帝以及作为美国盟友的发达资本主义国家中获得经济和军事利益。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-96","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"执行这一政策的中国在资本主义世界引起了浓厚的兴趣，特别是在美帝方面，它认为中国的这一政策是对其维护资本主义和帝国主义、加强新殖民主义、镇压革命和扼杀社会主义以及削弱其对手苏联的战略的极大支持。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-97","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"正如卡特所宣称的，美帝想要与中国紧密合作。他强调：“我们认为美中关系是我们全球政策的核心要素，中国是维护和平的关键力量。”中国主张同美国尽可能密切地和平共处。有了这些观点和立场，中国就可以同那些以美帝为基础的资产阶级资本主义国家站在一起了。中国向帝国主义的转变，同苏联和以前的其他社会主义国家一样，正日益成为现实。甚至帝国主义者自己也看到了这一点，他们为这一“新现实”感到高兴，宣布“美国、苏联和中国意识形态冲突分裂相比50年代正在越来越不尖锐，世界越来越需要超级大国之间的合作……”","language":"中文","translation":false},{"id":"hoxha-imperialism-1-98","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美帝就像卡特总统宣布的那样，愿意向中国提供力所能及的援助，帮助中国加强经济建设和军队建设。他们在拍中国修正主义领导人的马屁，因为中国的战略是对美帝霸权目标的重要援助。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-99","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国赞赏美国反对修正主义苏联的观点和行动，因为他们想要表明他们是为革命服务的，是为了削弱世界上最危险的大国苏联。就美国而言，美帝也赞赏中国反对修正主义苏联的观点和行动，因为正如卡特最亲密的合作者之一所言,“中苏冲突创造了一个更多元化的全球结构”,美帝更喜欢它，并认为这与它的“世界应该如何组织”的概念相一致，或者换句话说，其他国家应该如何被煽动去互相残杀，以使美国更容易统治世界的概念。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-100","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国的实用主义和唯利是图的政策，使其成为美帝的盟友，并把苏联社会帝国主义作为主要的敌人和威胁。今后，从逻辑上讲，当中国意识到它已经达到了削弱苏联社会帝国主义的目标时，当它看到美帝越来越强大时——因为它需要依靠一个帝国主义去攻击另一个帝国主义——它就会站在另一边继续斗争。在这种情况下，美帝对中国来说可能变得更危险，而中国就必然自动改变其以前的立场。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-101","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这是符合实际的。1956年中国共产党第八次全国代表大会上，中国修正主义者把美帝视为主要威胁。后来，在1969年4月召开的第九次全国代表大会上，他们宣布美帝和苏联社会帝国主义------两个超级大国构成了主要的威胁。后来，在1973年8月召开的第十次全国代表大会和第十一次全国代表大会，他们宣布只有苏联是主要敌人。这样的摇摆不定，这样实用主义地实行政策，如果中国共产党在第十二次或第十三次全国代表大会上站出来支持苏联社会帝国主义，并宣布美帝为主要敌人，也并非不可能。这样的状况将继续,直到中国达到了其成为资本主义世界强国的目标。如果是这样，中国将在国际舞台上扮演什么角色?它的作用永远不是革命的，而是倒退的，反革命的。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-102","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国外交政策的一个重要方面是与日本结盟。正如我们上文所指出的，这两个国家之间的种族主义联盟最近签署了《中日友好条约》，其目的是实现中日共同统治亚洲、东盟国家和大洋洲的战略计划。中国的修正主义者需要这个条约，需要和日本的友谊，这样他们就可以和日本的军国主义分子一起对抗苏联的社会帝国主义，并寻找机会消灭它及其在亚洲的影响。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-103","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":103,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但中国也希望利用与日本的关系获得信贷，从日本进口设备、技术和武器，以实现自己的大国抱负。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-104","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":104,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国十分重视同日本的全面经济合作，一半以上的对外贸易是与日本进行的。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-105","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":105,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"为了实施扩张主义政策，社会帝国主义的中国正在努力扩大其在亚洲的影响力。目前它在印度没有任何影响，因为在印度，美国和苏联在未来可能带来的变化与结盟的背景下，有着各自的和共同的利益。现在，中国希望同印度开始改善外交关系。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-106","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":106,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但是印度对西藏有很大的野心。印度将试图清除中国在巴基斯坦可能拥有的那一点点影响力，因为巴基斯坦处于伊朗和阿富汗两侧的战略位置。美帝在中东石油产区占主导地位，围绕此处的竞争始于此。中国很难在那里立足。中国将奉行一项违背阿拉伯人民利益、支持美国利益的政策，直到它变得强大为止。与此同时，中国将帮助美国与伊朗、沙特阿拉伯等国家一道，在这一对美欧帝国主义至关重要的地区建立一道强大的屏障，阻止苏联在政治、经济和军事上渗透进来。为了实现这一目标，中国社会帝国主义者正把目光投向西欧。他们的目标是使西欧与苏联的社会帝国主义作斗争。这就是为什么他们以各种方式支持北约、欧洲国家联盟与美国的欧洲共同市场和“欧洲联盟”。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-107","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":107,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在其战略计划中，社会帝国主义中国的目标是将其影响力和霸权扩展到它所称的“第三世界”国家。“第三世界”理论对中国具有重要意义。毛泽东不是以梦想家的身份宣扬这一 \"理论\"，而是有明确的霸权主义目的，即中国应称霸世界。他的继任者都遵循和毛泽东、周恩来相同的战略。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-108","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":108,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国的战略雄心也延伸到了所谓的“不结盟世界”[15]，这是铁托主义所提倡的。这些“世界”之间没有区别，互相重叠着。很难区分哪些国家属于第三世界，它们与“不结盟国家”的区别是什么，哪些国家属于“不结盟国家”，它们与“第三世界”的区别又是什么。因此，无论它们被称为什么，它们都是相同的国家。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-109","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":109,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这就是为什么中国领导人如此重视与铁托和南斯拉夫在思想、政治、经济和军事等各领域保持非常友好的党和国家关系的原因之一。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-110","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":110,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国修正主义者和南斯拉夫修正主义者的共同意见并不妨碍他们利用这种友好关系，达成自己的特殊目的。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-111","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":111,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"铁托正试图利用华国锋声明出的一系列观点：南斯拉夫共产党对于马列主义的忠诚、南斯拉夫民族自治政策的社会主义性质和铁托据称在践行马列主义的内外政策；来表明：铁托暴露出的反马列主义和修正主义,只不过是斯大林主义者的诽谤——而在此基础上,他正在寻求在国际上建立自己的声誉。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-112","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":112,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"华国锋方面，他利用与南斯拉夫的关系在赋予所谓的中国向欧洲开放的政策。中国修正主义者还试图利用与声称是不结盟运动的领导的铁托分子之间的友谊，将其作为渗透到“不结盟国家”并在那里建立统治地位的重要渠道。华国锋访问南斯拉夫时,华国锋把不结盟运动吹上了天，说它是“世界人民反对帝国主义、殖民主义和霸权主义斗争中举足轻重的力量”，这不是没有不可告人的目的的。他对这场运动和铁托赞不绝口，因为他梦想着控制这场运动，使北京成为它的中心。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-113","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":113,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"中国社会帝国主义的政策，从各方面看，都是一个帝国主义大国的政策，是反革命和战争的政策，人民会越来越憎恶它，反对它，越来越猛烈地与它斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-114","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":114,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"我们上面谈到的帝国主义超级大国，仍然是帝国主义和战争贩子，就算今天不拖入，明天也会把世界拖入一场毁灭性的核战争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-115","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":115,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"美帝正努力把它的钩喙更深地刺入其他民族的经济中，而苏联社会帝国主义刚刚开始伸出","language":"中文","translation":false},{"id":"hoxha-imperialism-1-116","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":116,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"它的爪牙，试图让它们在其他国家植根，只为创建和巩固自己的新殖民主义和帝国主义的基业。但还有“欧洲联盟”，它通过北约与美国联系在一起，它有个别的、而不是集中的帝国主义倾向。另一方面，中国也加入了成为超级大国的行列，日本军国主义也站了出来。这两种帝国主义正在结成联盟，以便形成一种反对其他帝国主义的帝国主义力量。在这种情况下，世界大战的危险就更大了。目前它们的之间的联盟是存在的，它们将会改变方向，而不是其内容(译者注：意思应是这些帝国主义的联盟形式无论怎么变化，本质是不变的)。帝国主义国家在联合国和由帝国主义组织的各种国际会议上滔滔不绝地讲裁军的漂亮话，很蛊惑人心。可他们制造并保护其对战略武器的垄断，并大规模贩运武器，不是为了保障各国的和平与安全，而是为了牟取暴利，镇压革命和人民，发动侵略战争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-117","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":117,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"“各资产阶级国家在疯狂地扩充军备和重整军备。为了什么呢？当然不是为了闲谈，而是为了战争。战争是帝国主义者所需要的，因为它是重分世界，重分销售市场、原料产地和投资场所的唯一手段。”（出自《联共（布）中央委员会向第十六次代表大会的政治报告》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-1-118","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":118,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"超级大国之间的竞争正把它们推向战争，它们必然会在“第三世界”、“不结盟”或“发展中国家”之间挑起许多局部战争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-119","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":119,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"卡特总统表示，战争只可能发生在地球的两个地方，中东和非洲。原因很明显：因为目前正是在世界的这两个地区，美国可获得极大利益。中东有石油，而在富裕的非洲，发展新殖民主义的经济和战略利益的超级大国之间在市场和势力范围的划分上发生了冲突，因为他们试图维护和巩固自己的地位和获得新的更高的地位。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-120","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":120,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"然而，除了中东和非洲以外，还有其他超级大国的利益发生冲突的地区，比如东南亚。美国、苏联以及中国都在努力建立各自的势力范围，瓜分市场。这也引起了冲突，这些冲突有时变成局部战争，这些战争的目的不是解放人民，而是建立或取代代表地方资本的统治集团，这些集团有时是倚仗着一个超级大国，有时是倚仗着另一个超级大国。苏联社会帝国主义和美帝是人民不信任的两个怪物。同样，人民也不信任中国。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-121","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":121,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"当超级大国无法通过经济、意识形态和外交手段实现其掠夺性利益时，当矛盾恶化到最严重的程度时，当协议和改革时证明无法解决这些矛盾时，于是他们之间的战争开始了。人民将会在战争中血流成河，因此，他们必须竭尽全力，不让自己被蒙骗，破坏和干扰帝国主义间的掠夺性战争，使它不具有世界性的规模，如果他们无法实现这一目标，就发动解放战争，并取得胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-122","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":122,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在帝国主义和社会帝国主义的全球战略中，铁托主义和其他修正主义思潮的作用","language":"中文","translation":false},{"id":"hoxha-imperialism-1-123","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":123,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"（注：“在帝国主义……”这一段关于铁托的部分参考了b站斯霍之声译文，在此表示真诚感谢）","language":"中文","translation":false},{"id":"hoxha-imperialism-1-124","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":124,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在帝国主义和社会帝国主义、世界资本主义和反动派对革命、社会主义和人民进行的野蛮镇压中，他们得到了各派别的现代修正主义者的支持。这些叛徒和背信弃义者，从内部破坏、分裂和阻碍无产阶级的努力和人民摆脱社会和民族束缚的斗争，协助帝国主义执行它的全球战略。现代修正主义者开始诋毁和歪曲马列主义，混淆人民的思想，使人民脱离革命斗争，帮助资本，维护和延续资本的压迫和剥削制度。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-125","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":125,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在这场重大而危险的反革命赌博中，南斯拉夫的铁托修正主义者同我们上面提到的苏联修正主义者和中国修正主义者一样，发挥着头等重要的作用。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-126","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":126,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"铁托主义是资本主义的旧工具，是帝国主义资产阶级反对社会主义和解放运动时最喜欢的武器。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-127","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":127,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫人民为了自由、民主和社会主义，牺牲自己同纳粹-法西斯侵略者斗争。他们成功地解放了自己的国家，但没有能够在社会主义道路上继续革命。铁托为首的南斯拉夫修正主义领导集团，长期以来一直通过情报部门开展秘密工作，并且在战争期间，假装保留了第三国际下属党的特征，但实际上其还有其他不可告人的目的，这与马列主义和南斯拉夫人民在南斯拉夫建立真正的社会主义社会的愿望背道而驰。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-128","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":128,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫共产党上台后，继承了许多具有反马列主义的错误。第二次世界大战后，它表现出明显的民族沙文主义特征，这种特征早在战争时期就已显现出来。这些特点在它背离马列主义意识形态、对苏联和斯大林的态度、对阿尔巴尼亚的沙文主义式的立场和行动等方面显而易见。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-129","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":129,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫建立的人民民主制度是暂时的。它并不适合当权派，尽管这个派别继续自称 \"马克思主义\"。铁托等人不赞成社会主义建设，不赞成以马列主义理论为指导的南斯拉夫共产党，不接受无产阶级专政。这就是共产党和工人党情报局与南斯拉夫共产党之间爆发冲突的根源。这是马列主义和修正主义之间的意识形态冲突，而不是修正主义者宣称的所谓\"过度干涉\"之间的冲突。斯大林捍卫了马列主义理论的纯洁性，铁托却保护了现代修正主义的偏离主义（deviationist）、修正主义、反马克思主义倾向，追随第二次世界大战前夕和第二次世界大战期间活跃的白劳德[16]和其他机会主义者的脚步。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-130","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":130,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在解放初期，南斯拉夫领导人假装以苏联社会主义建设为榜样，并宣称在南斯拉夫建立了所谓的社会主义。这样做是为了欺骗已经浴血奋战，并渴望真正社会主义的南斯拉夫人民。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-131","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":131,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"事实上，铁托分子不代表，也不可能代表社会主义的社会制度和苏维埃国家的组织形式，因为铁托是资本主义制度的代表，是资产阶级民主国家的代表，他的集团掌握着政权。这个国家的目的是为了创造一种\"社会主义已在南斯拉夫建立\"的观念，这是一种“带有人性面孔的”的“特定的”社会主义，也就是说，这种社会主义就是这样一种“社会主义”——其他社会主义国家的第五纵队，一切都是英美帝和铁托集团精心策划和协调好的。因此，南斯拉夫修正主义者玩帝国主义和世界资本主义的游戏，并与之妥协，从而使自己与苏联对立。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-132","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":132,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"从反法西斯民族解放战争时期开始，为了追求他们的旧制度，英国和随后的美帝不仅帮助铁托与苏联决裂，而且还开展了破坏苏联的行为，特别是努力将其他人民民主国家从社会主义阵营中分离出来，以便将苏联与所有这些国家隔离开来，并将它们与西方联合起来。这是世界资本主义及其代理人——铁托主义的政策。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-133","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":133,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"狂热的反共老手丘吉尔直接地以个人身份参与来确保铁托和他的团体为资本主义服务。在战争期间，他派出了他最信任的朋友，正如英国领导人所说的，以及后来他自己的儿子，来担任铁托的工作人员。最终，他自己在1944年5月在意大利那不勒斯与铁托会晤，以确保铁托不会耍花招。在他的回忆录中，丘吉尔写道，在与铁托的会谈中，后者表示愿意之后发表一份公开声明，称“战后南斯拉夫不会建立共产主义”。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-134","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":134,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"铁托以巨大的精力为他的主人服务，丘吉尔赞美了他的\"伟大\"的服务，并告诉他：“现在我明白你是对的，所以我和你在一起，我比以前更喜欢你”。这就好像一个情人对他的爱说出的最温暖的誓言。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-135","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":135,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"几乎在南斯拉夫同苏联和人民民主国家完全决裂之前，帝国主义，特别是美帝，向南斯拉夫提供了大量的经济、政治、思想和军事援助，这种援助后来变得更加频繁。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-136","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":136,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"提供这种援助的条件是该国要走资本主义道路。帝国主义、资产阶级并不反对南斯拉夫继续披着社会主义的皮，相反，南斯拉夫应该保持其外在的社会主义色彩，因为这样它将成为反对社会主义和解放运动的一个更有效的武器，这很符合南斯拉夫的利益。这种“社会主义”不仅与列宁和斯大林所设想和实践的社会主义有根本上的不同，甚至会站出来反对列斯的社会主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-137","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":137,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在相当短的时间内，南斯拉夫成为美帝的“社会主义”喉舌，是一个协助世界资本的间谍破坏机构。从1948年到今天，铁托主义的特点是狂热地反对马列主义，在世界各地组织宣传运动，将南斯拉夫体系假装成为“真正的社会主义”秩序，“新社会” ，一种“不结盟社会主义”，不再像列宁和斯大林在苏联建立的社会主义，而是一种“带有人性面孔”的社会主义，这是世界上第一次尝试并且正在产生“辉煌的成果”。这种宣传的最终目的是引导世界各地争取自由和独立的人民和进步力量走到一条死胡同。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-138","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":138,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫修正主义者采取托派和其他受资本主义、资产阶级鼓励的无政府主义分子在列宁时期于苏联采取的治国方式，目的是破坏那里的社会主义建设。铁托在谈到建设社会主义的时候，采取了这些形式，以完全歪曲马列主义的工农业建设原则。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-139","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":139,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫各共和国具有行政和组织政治领导的特点，以致民主集中制被消灭，南斯拉夫共产党的作用变得无足轻重。南斯拉夫共产党改名为“南斯拉夫共产主义联盟”，看起来像一个马克思主义的名字，但在内容、形式、能力和目标上都是反马克思主义的。联盟成为一个没有骨气的前锋，被剥夺了马列主义政党的特征，保留旧的形式,但不再扮演工人阶级的先锋队角色,不再是领导联邦共和国的政治力量。但是，根据铁托修正主义者的说法，南共盟据称只需承担一般的“教育”功能。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-140","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":140,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"铁托集团的领导层将南共盟置于国家安全管理局[17]的控制之下，将其变为情报机关的隶属，变为法西斯斯组织，并将国家变为法西斯专政。我们完全清楚这些活动的巨大危险，因为科奇·佐治[18]，被铁托集团收买的代理人，试图在阿尔巴尼亚实现同样的目标。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-141","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":141,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"铁托、兰科维奇[19]和他们的机构完全清算了任何可能具有社会主义真正色彩的事物。铁托主义对那些企图消灭这个机构、这个资本主义修正主义组织的内部分子进行了激烈的镇压，并反对在国外进行的一切旨在揭露这个冒充社会主义政权本质的马列主义宣传。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-142","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":142,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"铁托集团迅速放弃了早期开始的农业集体化，建立了资本主义国营农场，鼓励在农村发展私有制，允许土地自由买卖，恢复了富农分子的名誉，把土地抛向私人市场，使资本主义势力在城镇中繁荣发展，并进行了第一轮加强资本主义经济方向的改革。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-143","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":143,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"与此同时，铁托资产阶级正在寻找一种“新的”形式来伪装南斯拉夫的资本主义制度，这种形式被发明出来，他们称之为南斯拉夫的“社会主义自治制度”。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-144","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":144,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"他们将这个制度披上“马列主义”的外衣，声称这种制度是最真实的社会主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-145","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":145,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"起初，“自治”作为一种经济制度出现，之后扩展到国家组织领域和该国所有其他生活领域。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-146","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":146,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫“自治”的理论和实践，是对马列主义学说和社会主义建设的普遍规律公然否定。 “自治”的经济和政治制度是资产阶级专政的一种无政府-工团主义形式，在它统治下的南斯拉夫，依赖于国际资本。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-147","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":147,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"“自治”制度，具有民主集中制的消灭、国家统一管理的作用的消灭、无政府主义的联邦制、\"反国家\"意识形态等典型特征，带来了永久性的经济、政治和意识形态领域的混乱，带来了各共和国、各地区的薄弱而不平等的发展，巨大的社会阶级差异，民族仇恨与压迫，以及精神生活的堕落。它带来了工人阶级的巨大分裂，让他们的不同分支进行恶性竞争，促进了资产阶级小团体、地方民族主义和个人主义的发展。南斯拉夫的工人阶级不仅没有在国家和社会中发挥支配性作用，“自治”制度反而使其处于甚至无法捍卫自己的一般利益的状况下，使其丧失了作为一个紧密联合的阶级进行行动的可能。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-148","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":148,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"从资本主义世界，特别是从美帝，大量的资本以投资、信贷和贷款的形式涌入南斯拉夫。正是这种资本构成了南斯拉夫资本主义发展的物质基础。仅其负债就超过110亿美元。南斯拉夫从美国获得了70多亿美元的信贷。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-149","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":149,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"尽管铁托分子领导人从国外得到了许多荣誉，但南斯拉夫人民并没有享受，也没有享受到这种有特色的“社会主义”的“辉煌成果”。相反，南斯拉夫存在着政治和意识形态领域的混乱。造成国内大规模失业和大量劳工移居国外的制度在盛行，这使南斯拉夫完全依赖帝国主义列强。南斯拉夫人民正在被疯狂剥削，以符合当权阶级和在该国投资的所有帝国主义列强的利益。南斯拉夫领导者并不关心物价每天都在上涨，工人阶级的贫困不断增加，国家不仅债台高筑，而且还深深卷入资本主义世界的巨大危机中。南斯拉夫只有有限的独立和主权，因为抛开外在因素，它本身完全没有经济潜力。它的大部分资产存在于与各种外国资本主义企业和国家的共同所有权中，因此必然会遭受危机和外国剥削的破坏性影响。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-150","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":150,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"但是，世界资本主义给南斯拉夫的“自治”制度提供了如此巨大的政治和财政支持，世界资本主义给予南斯拉夫“自治”这样巨大的政治和财政支持，并与铁托的宣传协调一致，将这一制度作为“社会主义建设的新形式”向全球各国进行宣传，这并非偶然。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-151","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":151,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"这样做是因为南斯拉夫的“自治”形式提供了一种从思想上政治上颠覆和破坏无产阶级和人民革命解放运动的方式，为帝国主义的政治和经济渗透开辟了道路。帝国主义和资产阶级希望将自治作为不同国家的后备制度，资本主义牺牲人民的利益，努力寻找各种形式的政府，以便延长资本主义的寿命。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-152","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":152,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"南斯拉夫的“不结盟”理论和实践，使帝国主义者们受益匪浅，因为这些理论和实践帮助帝国主义者更好地欺骗人民。这既符合帝国主义者的利益，也符合社会帝国主义者的利益，因为这有助于他们在“不结盟国家”中树立和增强自己的影响，把爱好自由的人民从民族解放和无产阶级革命的道路上引开。因此,卡特、勃列日涅夫和华国锋,大肆赞扬铁托分子的“不结盟”政策，并试图利用这一政策达到自己的目的。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-153","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":153,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"铁托主义一直是帝国主义、资产阶级的武器，是扑灭革命火焰的“灭火器”。它与现代修正主义是一脉相承的，目标是一致的，在意识形态上是统一的。他们同马列主义、革命和社会主义作斗争的方法、形式和策略是不同的，但是反革命的目的是相同的。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-154","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":154,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"在资产阶级和反动派镇压无产阶级和人民革命斗争的猖狂行动中，欧洲的修正主义政党和其他大陆各国的修正主义政党，首当其冲，不遗余力地为虎作伥。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-155","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":155,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"西欧国家的修正主义政党正在努力编造一种关于“新社会”的理论，他们标榜为是社会主义类型的，这将通过“体制改革”以及与社会民主党、甚至右翼政党的紧密合作来实现。他们认为，这个“新社会”将通过“社会改革”、“社会和平”、“议会道路”和与资产阶级政党的“历史性妥协”，建立在新的基础之上。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-156","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":156,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"欧洲修正主义政党，如意大利、法国和西班牙的修正主义政党，以及紧随其后的所有其他西方修正主义政党，都否认列宁主义、阶级斗争、革命和无产阶级专政。他们都走上了同资产阶级妥协的道路。他们将这条反马克思主义路线命名为“欧洲共产主义”[20]。“欧洲共产主义”是一种新的伪共产主义思潮，它既反对也不反对苏联的修正主义集团。这种摇摆不定的立场可以用他们的目标来解释，即与欧洲社会民主主义和在欧洲大锅中“沸腾着的”各种观点共存。“欧洲共产主义者”可以团结任何一个人----除了那些为革命的胜利和马列主义思想的纯洁性而斗争的人。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-157","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":157,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"一切修正主义、机会主义和社会民主主义思潮都在不遗余力地帮助超级大国进行他们的罪恶活动，镇压革命和人民。所有这些思潮支持资产阶级所谓的改良只有一个目的：通过对革命设置一千零一个物质、政治和意识形态障碍来扼杀革命。他们正在努力使迷惑和分裂无产阶级及其盟，因为他们知道，由于派系斗争而分散和分裂，后者将无法在国内或国际上建立意识形态、政治和军事上的统一，而这种统一对于对抗世界资本主义腐朽的攻击是必不可少的。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-158","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":158,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"现代修正主义与社会民主主义的联盟害怕法西斯主义的出现，特别是在某些受到极右势力威胁的国家。为了避免法西斯专政，修正主义者和社会民主主义者努力在人民群众、无产阶级和资本主义、资产阶级这两个对立面中“缓和”矛盾，“减弱”阶级斗争。因此，为了确保“社会和平”，这些联盟的主体不得不相互让步，同资本主义-资产阶级达成妥协，就某种双方都能接受的政体达成协议。因此，在资本主义-资产阶级及其政党公开继续同共产主义作斗争的同时，修正主义政党却竭力歪曲革命的指导思想马列主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-159","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":159,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"改良主义工会，特别是受过教育和训练的工会，他们与统治阶级妥协，只为了经济利益而罢工，而不是为了政治要求和无产阶级夺取国家政权的目的而罢工，工会已成为欧洲修正主义政党的中坚力量。当然，他们讨价还价的目的是在需求和出价之间取得平衡——一方乞求施舍，另一方决定施舍的规模。改革主义工会和修正主义政党，以及拥有政党、国家权力和工会的统治阶级，都受到革命、无产阶级及其真正的马列主义政党的威胁。因此，他们在寻求一种反动的妥协，一种不可能在所有资本主义国家都一样的解决办法------原因是各个国家的资本的力量不同，危机的深度不同，内部矛盾的程度也不同。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-160","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":160,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"革命——战胜无产阶级和人民的敌人阴谋诡计的唯一武器","language":"中文","translation":false},{"id":"hoxha-imperialism-1-161","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":161,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"一切敌人，帝国主义者、社会主义帝国主义者和各种修正主义者，无论联合起来还是单独地，都在进行斗争，误导进步的人民，败坏马列主义的名誉-----特别是歪曲列宁主义的革命理论，镇压革命和一切形式的人民抵抗和民族解放斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-162","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":162,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"马列主义的敌人有充足的战斗力，但是革命的力量也十分强大。这些力量同敌人进行着煽动、抵抗和斗争等活动，破坏了资本主义世界和反动派们的安定，使他们的生活举步维艰。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-163","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":163,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"“一个幽灵，共产主义的幽灵，在欧洲大陆徘徊。为了对这个幽灵进行神圣的围剿，旧欧洲的一切势力，……都联合起来了。”（出自《共产党宣言》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-1-164","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":164,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"马克思恩格斯的这一论断至今仍然有效。帝国主义,社会帝国主义和现代修正主义认为共产主义带来的危机已被消灭,因为它们认为革命因修正主义的背叛而遭受的沉重打击的是无可救药的,他们低估了马列主义的力量,高估他们所拥有的物质、压倒性的的军事和经济潜力。这只是他们的痴心妄想。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-165","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":165,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"世界无产阶级正在集结力量。无产阶级和爱好自由的人民，从他们自己的切身体会中，对铁托分子、赫鲁晓夫派、中国人、“西欧共产主义者”和其他现代修正主义者的背信弃义，日益有了更清楚的认识。时间是为革命而工作，为社会主义而工作，而不是为资产阶级和帝国主义工作，不是为现代修正主义和反动派工作。革命的火焰在世界上每一个角落的被压迫人民的心中燃烧，他们要获得真正的自由、民主和主权，要把权力掌握在自己手中，要走上社会主义道路，消灭帝国主义和它的仆从。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-166","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":166,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"列宁时代的现象------脱离第二国际之后，创立了新的马列主义政党，今天仍在发生。修正主义的背叛，在任何地方都必然导致真正的共产主义政党的建立和加强，这些政党高举起马列主义和革命的旗帜，而修正主义者却拒绝这些旗帜，把这些旗帜践踏在泥中。他们把反对光荣的列宁主义革命战略和伟大的马列主义理论的重担，交给了他们计划的世界帝国主义和修正主义全球战略。这样，使人民群众充分认识到斗争的目标和正确道路，充分认识到斗争所必需的牺牲，团结、组织、领导和带领人民群众走向胜利的重任，就落在真正的马克思主义政党的肩上。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-167","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":167,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"我们马列主义者,站在一场伟大的斗争中的前沿。这场斗争由当今的无产阶级和渴望自由的被压迫人民发动,一方面,对抗野蛮贪婪的帝国主义,另一方面,这也要求在战斗中必须彻底了解共同敌人或不同国家中的个别敌人使用的目标、策略、方法和形式。如果我们不能坚定地忠于马列主义，我们就不能对这些明察秋毫。我们必须看到在目前的情况下，资本主义世界的链条上有一系列薄弱环节，将来也会有薄弱环节，在这种情况下，革命者和人民必须进行不断的活动，进行不屈不挠和勇敢的、有组织的斗争，一个接一个地打破这些环节。当然，这需要工作、奋斗、牺牲和自我否定。勇敢的个人和人民，在革命利益的激励下，能够而且必将直面帝国主义、社会主义和反动派的互相联系的强大威胁，建立新的共产主义联盟，并寻求摆脱困境的出路。正是革命者、马列主义者、各大洲各国人民的不懈斗争，才给反动势力造成了困难的局面。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-168","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":168,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"世界各地的共产党人都没有理由害怕一段时间以来在革命思想中占主导地位的毫无根据的谬见。共产党员必须争取那些犯错误的人，尽最大努力帮助他们改过自新，当然不能自己陷入机会主义。原则斗争的过程中,一开始会有一些人摇摆不定,但是,只有犹豫不决的人才会动摇，而在坚决正确地运用马列主义理论的人之间，在正确认识自己国家、世界无产阶级和革命的利益的人之间，不会发生动摇。不过，当动摇的人看到同志们坚持马列主义的革命主张，他们的斗争性就会进一步加强。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-169","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":169,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"如果马列主义根据目前的国际条件和各国的国情，被正确地、坚定地运用，如果他们不断地加强各民族无产阶级的统一，在残酷地反对帝国主义和一切派别的现代修正主义的斗争中，他们一定能够克服他们在道路上所遇到的一切困难，不管这些困难有多大。马列主义及其不朽的原则，如果运用得当，将无法逆转地将世界资本主义埋入坟墓，带来无产阶级专政的胜利，从而使工人阶级建设社会主义，走向共产主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-170","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":170,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[1] 译者注：应指苏俄国内战争","language":"中文","translation":false},{"id":"hoxha-imperialism-1-171","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":171,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[2] 译者注：北大西洋公约组织，简称NATO，二战后西方阵营的反苏反共军事战略同盟，1949年在华盛顿签署协定成立。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-172","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":172,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[3] 译者注：东南亚条约组织，简称SEATO，于1955年2月19日在泰国曼谷正式成立的反共集体防卫组织，1977年6月30日解散。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-173","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":173,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[4] 译者注：即欧洲经济共同体","language":"中文","translation":false},{"id":"hoxha-imperialism-1-174","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":174,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[5] 译者注：南斯拉夫社会主义自治制度，1950 年开始南斯拉夫在工人自治基础上逐步确立的政治经济和社会发展的根本制度，反修正主义者认为这是复辟资本主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-175","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":175,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[6] 译者注：石油输出国组织，简称“欧佩克”，石油生产国为协调成员国石油政策、反对西方石油垄断资本的剥削和控制而建立的国际组织，1960年9月成立。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-176","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":176,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[7] 译者注：战略武器限制谈判，简称SALT，指在美苏两国之间举行的一系列谈判会议，意在达成双方的削减和限制进攻性战略武器。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-177","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":177,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[8] 译者注：1978年8月12日，《中华人民共和国和日本国和平友好条约》在北京签字，华国锋、邓小平、廖承志出席，黄华和日本外务大臣圆田直分别代表本国在条约上签字。条约简称《中日和平友好条约》或“中日友好条约”。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-178","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":178,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[9] 译者注：1967年8月7－8日，印度尼西亚、泰国、新加坡、菲律宾四国外长和马来西亚副总理在曼谷举行会议，发表了《曼谷宣言》（《东南亚国家联盟成立宣言》），正式宣告东南亚国家联盟成立。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-179","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":179,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[10] 译者注：西德的首都","language":"中文","translation":false},{"id":"hoxha-imperialism-1-180","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":180,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[11] 译者注：似指弗朗茨·约瑟夫·施特劳斯，1915－1988，西德右翼政客，巴伐利亚基督教社会联盟主席。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-181","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":181,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[12] 译者注：国家安全委员会（KGB），1954年3月改组而来，是臭名昭著的苏联情报机关。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-182","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":182,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[13] 译者注：1955年西德加入北约后，欧洲社会主义阵营国家（包括东德）签署了《华沙公约》，该条约由原苏联领导人赫鲁晓夫起草，1955年5月14日在波兰首都华沙签署。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-183","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":183,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[14] 译者注：中共十一大于1977年8月12日至18日在北京举行，进一步揭批了所谓“四人帮”的罪行，并重申在本世纪内把中国建设成为社会主义现代化强国是新时期党的根本任务。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-184","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":184,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[15] 译者注：不结盟国家是参加不结盟会议的国家。1956年铁托、纳赛尔和尼赫鲁在南斯拉夫会谈后的联合声明中提出不结盟的主张。1961年在贝尔格莱德召开的第一次不结盟国家首脑会议，标志不结盟运动正式形成。不结盟运动的宗旨是：主张执行独立自主、和平、中立的政策，拒绝同任何大国结盟；加强成员国的团结和协商;支持民族解放运动；反对殖民主义、种族主义、犹太复国主义、帝国主义和霸权主义；主张国际关系民主化和建立新的国际经济秩序。但实践中，这些宗旨完全落空。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-185","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":185,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[16] 译者注：白劳德（Earl·Browder），1891——1973，1934年任美国共产党中央总书记，1935～1940年任第三国际执行委员会委员。任上推行一条右倾机会主义道路，1944 年5月在美共第十二次全国代表大会上宣布解散美国共产党，另立美国共产主义政治协会，自任会长。1946年2月，威廉·福斯特重建的美共将其开除出党。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-186","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":186,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[17] 译者注：南斯拉夫国家安全局（UDBA）,1946年由兰科维奇改组的情报组织，拥有庞大的秘密警察网络。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-187","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":187,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[18] 译者注：克奇·佐治（Koçi·Xoxe），前阿尔巴尼亚劳动党中央政治局委员、中央组织书记、部长会议副主席兼内务部长。1937年成为阿尔巴尼亚共产党领导人，受到南斯拉夫支持。在苏联、阿尔巴尼亚与南斯拉夫决裂后，1948年因被当作“铁托集团的代理人”而开除出党。1949年以“企图并实行以暴力夺取国家政权”被判处绞刑。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-188","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":188,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[19] 译者注：兰科维奇（Aleksander Rankovic）1902——1983，前南斯拉夫党和国家主要领导人。南斯拉夫共产党中央政治局委员、南斯拉夫共产主义者联盟中央执行委员会委员、中央书记处书记、南斯拉夫联邦人民共和国联邦执行委员会副主席兼内务部长、南斯拉夫社会主义联邦共和国副总统。1966年9月14日，被塞共盟开除出党，同年10月南共盟八届五中全会通过将兰科维奇开除出南共盟的决定。","language":"中文","translation":false},{"id":"hoxha-imperialism-1-189","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第一章 帝国主义和现代修正主义的策略","page":1,"paragraph":189,"url":"https://www.marxists.org/chinese/hoxha/1978/02-01.htm","text":"[20] 译者注：欧洲共产主义（Eurocommunism），由欧洲旧共产党推行的一种类似社会民主主义的意识形态，1975年7月意共与西共举行双边会谈并发表宣言,同年11月意共与法共会谈并发表共同声明，被认为是欧洲共产主义正式形成的标志。1977年 3月，意共、法共、西共领导人在马德里会晤,通过《在民主、自由中实现社会主义》的纲领，被称作“欧洲共产主义的宣言”。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-1","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":1,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中文马克思主义文库 -> 恩维尔·霍查 -> 《帝国主义与革命》（1978）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-2","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":2,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","language":"中文","translation":false},{"id":"hoxha-imperialism-2-3","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":3,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在当前形势下，赫鲁晓夫分子、铁托分子、“欧洲共产主义者”、中国修正主义者等反马克思主义思潮以形势变化为借口攻击革命和人民解放事业，这种情况下，深入研究列宁有关帝国主义的著作具有头等重要的意义。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-4","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":4,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"我们必须回到这些著作上来，对列宁天才的著作提出的帝国主义----即资本主义的最高阶段，进行十分深入而细致的研究。仔细研究这部著作，我们就可以看到修正主义者们以及为他们一员的中国领导人是怎样歪曲列宁主义的帝国主义思想的，是怎样理解帝国主义的目的、战略和策略的。他们的著作、宣言、立场和行动表明，他们对帝国主义性质的看法是完全错误的，他们是站在反革命和反马克思主义的立场上观察帝国主义的。第二国际的各党派和他们的思想家考茨基及其同伙也是如此，列宁对他们进行了无情的揭露。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-5","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":5,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"如果我们认真研究列宁的这些著作，忠实地坚持他天才的分析和结论，我们就可以看到，在当下，帝国主义完全保留着列宁描述的相同的特点，这样，列宁主义把我们的时代定义为帝国主义和无产阶级革命的时代，是无可动摇的，而这种情况下，革命的胜利也是必然的。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-6","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":6,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"众所周知，列宁从生产、资本集中和垄断这几个方面开始分析帝国主义。今天，同样，只有在列宁主义对帝国主义的分析之基础上，才能正确、科学地分析生产和资本的集中与垄断现象。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-7","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":7,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"当今资本主义的一个特点是生产资料和资本的日益集中，这导致了实力强大的企业兼并或吸收小企业。其结果是，劳动力大量集中在大型托拉斯和康采恩手里。这些企业还把巨大的生产力和不可估量的能源和原材料集中在它们手中。目前，大型资本主义企业也在利用核能和最新的技术，这些技术的所有权完全归于这些企业。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-8","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":8,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"这些大企业组织具有民族性和国际性的特点。在他们自己的国家内，他们弄垮了大多数小企业主或实业家，而在国际上，他们已成长为巨大的康采恩，垄断许多国家的包括工业、农业、建筑、交通等各个部门。无论这些康采恩延伸到哪里，无论生产被少数千万富翁和资本家集中在什么地方，小企业主和实业家被清算的趋势都会变得越来越普遍和明显。这就又导致垄断进一步加强。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-9","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":9,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“这种从竞争到垄断的转变，”列宁说，“不说是最新资本主义经济中最重要的现象，也是最重要的现象之一……”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-10","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":10,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"谈到帝国主义的这一特点，他补充说，","language":"中文","translation":false},{"id":"hoxha-imperialism-2-11","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":11,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“……而生产集中产生垄断，则是现阶段资本主义发展的一般的和基本的规律。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-12","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":12,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"资本主义在当今条件下的发展，充分印证了列宁的上述结论。垄断已成为当今社会最典型、最普遍的现象，它决定了帝国主义的面貌和经济本质。在美国、德意志联邦共和国、英国、日本、法国等帝国主义国家，生产的集中程度达到了空前的程度。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-13","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":13,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"例如，1976年，美国有近1700万人，占就业人口的20%以上，受雇于美国最大的500家公司。百分之六十六的商品来自这些公司。列宁写《帝国主义是资本主义的最高阶段》的时候，资本主义世界上只有一家美国大公司，那就是“美国钢铁公司”，股票资本总和超过10亿美元，而1976年价值达到亿万美元的公司数目大约是350家。1975年的时候，通用汽车公司，这个超级垄断企业，总资本超过220亿美元，剥削了近80万名工人；接下来是新泽西州的垄断企业标准石油公司，该公司主导着美国和其他国家的石油工业，剥削了70多万工人；在汽车工业中有三大垄断企业，占该部门产量的90%以上;在航空和钢铁行业，四家大公司分别占到65%和47%的产量。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-14","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":14,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"同样的过程已经并且正在其他帝国主义国家中发生。在德意志联邦共和国，13%的企业集中了全国50%的生产和40%的劳动力。在英国，50家大型垄断企业主宰着一切。英国钢铁公司钢铁产量占全国钢铁产量的90%以上。在法国，两家公司将四分之三的钢铁生产集中在他们手中，四家企业拥有全部的汽车生产，而另外四家控制着石油产品的全部产量。在日本，十家大型黑色冶金公司(译者注：黑色冶金工业指铁（也包括锰、铬、钛和钒）和铁合金的生产)生产全部生铁和四分之三以上的钢铁，而八家公司垄断了有色冶金。其他行业和部门也一样。(资料来源：《统计月报》，联合国，1977年;《统计年鉴》，1976年;美国《财富》杂志，1976年；等等)","language":"中文","translation":false},{"id":"hoxha-imperialism-2-15","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":15,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在这些国家仍然存在的中小企业直接依赖于垄断者。他们接受垄断者的命令并为他们工作;并从他们那里获得信贷和原材料、技术等。实际上，它们已成为垄断企业的附属物。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-16","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":16,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"生产和资本的集中造成了无技术差别的巨大垄断，这在今天是普遍存在的。企业及其工业生产、建筑、运输、贸易、服务、基础设施等全部分支部门，都在这些巨大的“联合企业”垄断下运作。从儿童玩具到洲际导弹，他们生产一切。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-17","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":17,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"资本的集中和垄断已经增加和正在不断增加的经济实力，创造了一个这样的情况：竞争的受害者不仅是“小婴儿”----也就是过去典型的非垄断企业，甚至可能波及到大型金融企业和集团。由于垄断企业对高垄断利润的贪得无厌和竞争的极度激烈，在过去二十年中，这一进程已经取得了巨大的成效。今天资本主义世界的并购规模是二战前的7到10倍。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-18","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":18,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"工业、贸易、农业和银行企业的联合与合并导致了新形式的垄断与大型工商型或实业型公司的创立，这种形式不仅在西方资本主义国家，也在苏联、捷克斯洛伐克、南斯拉夫和其他修正主义国家得到了广泛的应用。过去，垄断者是在其他独立公司的帮助下进行货物运输和联合销售，而今天，垄断者控制着生产、运输和销售。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-19","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":19,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"垄断者不仅试图消除被其控制的企业之间的竞争，而且还扩大了他们的魔爪，垄断所有的原材料资源，垄断所有富含铁、煤、铜、铀等重要矿产的地区。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-20","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":20,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"特别是在第二次世界大战后，随着国家垄断资本主义涉及领域的扩大和发展，生产和资本的集中呈现出巨大的规模。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-21","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":21,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"国家垄断资本主义是指国家机器服从于垄断和垄断在国家经济、政治和社会生活中完全统治的确立。这样，国家为了金融寡头的利益，直接干预经济，通过剥削全体劳动人民，保证当权阶级的最大利益，并扼杀革命和人民的解放斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-22","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":22,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"国家垄断财产作为国家垄断资本主义最具特色的基本要素，并不代表一个资本家或一群资本家的财产，而是代表资本主义国家的财产，资产阶级政权的财产。在各个帝国主义国家，国家垄断的资本主义部门占总产量的20%至30%。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-23","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":23,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"国家垄断资本主义代表着生产和资本的最高集中阶段，是今天在苏联和其他修正主义国家普遍存在的财产的主要形式。这种国家垄断资本主义是为当权的新资产阶级服务的。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-24","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":24,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在中国,通过一系列的改革,例如确立在企业中以利润挂帅，在组织、管理和报酬方面运用资本主义方式，建立经济特区、类似于苏联、南斯拉夫和日本的托拉斯和联合企业，向外国资本敞开大门，与外国垄断企业建立直接联系，等等，经济呈现出国家垄断资本主义的典型形式。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-25","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":25,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"目前，在资本主义和修正主义世界中，生产和资本的集中垄断已达到国家级水平。欧洲共同市场、经互会[1]等代表着各帝国主义列强垄断的联盟，实际上也推动和实现了这一趋势。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-26","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":26,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在分析国际垄断的形式时，列宁谈到了卡特尔和辛迪加。在生产和资本高度集中的今天，垄断资产阶级也找到了剥削劳动人民的其他形式，即跨国公司。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-27","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":27,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"从外表上看，这些公司试图给人一种它们由许多国家的资本家共同拥有的印象。事实上，跨国公司虽然在许多国家开展业务，但就其资本和控制权而言，跨国公司主要属于一个国家。他们通过吸收当地大大小小的公司来进行越来越大的扩张，而这些公司根本无法应对残酷的竞争。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-28","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":28,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"跨国公司设立子公司，并将其企业扩展到那些利润前景似乎最稳定的国家。例如，美国跨国公司“福特”在其他国家建立了20家大型工厂，雇佣了10万名不同国籍的工人。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-29","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":29,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"跨国公司与资产阶级国家之间有着密切的联系并相互依存，这是建立在跨国公司剥削阶级性质的基础上的。资本主义国家将其作为一种工具，为其在国内和国际上的统治与扩张的目标服务。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-30","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":30,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"由于跨国公司经济上的主要作用和在整个国家生活中所起的重要作用，一些跨国公司单独构成了一股强大的经济力量，许多情况下，它相当于甚至超过几个发达资本主义国家的预算或生产总和。美国最大的跨国公司之一“通用汽车公司”的产量，比荷兰、比利时和瑞士的工业产量加起来还要多。他们进行干预，以确保自己在经营所在国享有特殊优惠和特权。例如，1975年，美国电子产业主们要求墨西哥政府改变其规定了一些保护措施的《劳工法》，否则他们将把产业转移到哥斯达黎加，并为了施加压力，关闭了许多工厂，解雇了近12000名墨西哥工人。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-31","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":31,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"跨国公司是帝国主义的杠杆，是帝国主义扩张的主要形式之一。它们是新殖民主义的支柱，并影响到它们遍及的国家主权和独立。为了打开他们的统治之路，这些公司不惜犯罪，从策划阴谋和扰乱经济，到直接收买高级官员、政治和工会领导人，等等。被隐蔽的丑闻提供了充分的证据。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-32","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":32,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"许多跨国公司已经在修正主义国家建立了自己的公司，并开展业务。他们也开始渗透到中国。生产与资本的集中和垄断是今天资本主义世界的特点，并导致了生产的广泛社会化，但这丝毫没有改变帝国主义的剥削性质。相反，它们增加并加剧了对劳动人民的压迫，使他们越来越贫穷。这些现象充分证明了列宁的论点，即在生产和资本集中于帝国主义的条件下，","language":"中文","translation":false},{"id":"hoxha-imperialism-2-33","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":33,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“生产的社会化有了巨大的进展。”但仍然，“生产社会化了，但是占有仍然是私人的。社会化的生产资料仍旧是少数人的私有财产。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-34","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":34,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"垄断企业和跨国公司仍然是无产阶级和人民的大敌。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-35","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":35,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"我们这个时代生产和资本集中过程的强化，进一步加剧了资本主义的基本矛盾：生产的社会性与占有的私人性的矛盾，以及其他种种矛盾。今天，正如过去一样，从野蛮剥削工人中获得的巨额收入和超额利润被少数资本主义巨头所侵吞。同样，工业的各个联合部门所配备的生产资料是资本家的私有财产，而工人阶级仍然是生产资料所有者的奴隶，其劳动力也仍然是市场的一部分现在，大的资本主义企业不再仅仅剥削几十上百的工人，而是剥削成千上万的工人。由于资本主义对这支庞大的劳动力大军的无情剥削，仅1976年美国企业就攫取了超过1000亿美元的剩余价值，而1960年这一数字为440亿美元。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-36","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":36,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁揭露了第二国际的机会主义者----他们鼓吹有可能消除资本主义中由于垄断的出现和发展而产生的对立矛盾。他以科学的论据证明，垄断作为对劳动的压迫和剥削以及帮助私人占有劳动成果的工具，使资本主义的矛盾更加尖锐。资本主义制度的上层建筑是建立在垄断者统治的基础上的。这个上层建筑在国内和国际层面上维护并代表着垄断企业的掠夺性利益。垄断者支配着国家内部和外部政策、经济、社会、军事和其他政策。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-37","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":37,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"当今生产和资本集中的现实，也暴露了社会民主主义者、形形色色的现代修正主义者和机会主义者以及他们的领袖的那一套说教有多么可笑：所谓“国家垄断资本主义的资产、托拉斯等可以和平地转化为社会主义经济，今天的垄断资本主义将逐步融入社会主义”。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-38","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":38,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁教导我们，生产和资本的集中，也是货币资本更加集中的基础，它集中在大银行手中，使金融资本诞生和发展。在资本主义的发展过程中，银行与垄断企业一起，也得到了巨大的发展，不仅吸收了垄断企业和康采恩的货币资本，还一并吸收了小企业和投资者的资金。这样，那些掌握在资本家手中并为他们服务的银行就成为了主要开展金融手段者。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-39","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":39,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"大企业、卡特尔和垄断集团为了吞并小企业而进行的同样进程也在对小银行一个接一个的清算中发生。为此，正如大企业创造了垄断一样，大银行也创造了银行业康采恩。在过去二十年中，这一现象已经占据了巨大的比例(译注：这里没有说明是在什么地方占据比例，但根据语意，意思很可能是在经济界中，即清算十分猖獗)，今天，它仍然非常迅速地继续增长。今天的合并和收购的一个显著特征是，不仅小银行，而且中型和相对较大的银行遭到这种待遇。造成这一现象的原因是资本主义再生产矛盾的日益严重，竞争斗争的扩大和资本主义世界金融和货币体系的严重危机。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-40","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":40,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"26家大型金融集团在美国占据主导地位。其中最大的是摩根集团，拥有20家大银行、保险公司等，占据着900亿美元的股本。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-41","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":41,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"其他主要资本主义国家的银行资本集中和垄断的程度也很高。在西德，70家大银行中的3家拥有超过58%的银行资产。在英国，所有的银行活动都由四家银行控制，这四家银行被称为“四巨头”。日本和法国的银行资本集中度也很高。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-42","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":42,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁证明了银行资本与工业资本是相互联系的。起初，银行对他们借给实业家的贷款的命运很关切。为了确保接受信贷的实业家之间达成协议，避免彼此竞争，银行会进行调解工作，因为银行本身也会受到竞争的影响。这是银行与工业资本联锁的第一步。随着生产和货币资本的不断集中，银行成为生产企业的直接投资者，设立股份制公司。这样，银行资本就渗透到工业、建筑、农业、交通运输、流通领域等各个领域。对这些企业来说，它们购买大量股票，成为银行的参股者。今天，银行和垄断企业的董事都是彼此理事会的成员，从而形成了列宁所说的“私有联盟”。由此产生的金融资本包括各种各样的资本：工业资本、货币资本和商品资本。列宁在描述这个过程时说：","language":"中文","translation":false},{"id":"hoxha-imperialism-2-43","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":43,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“生产的集中；从集中生长起来的垄断；银行和工业日益融合或者说长合在一起，--这就是金融资本产生的历史和这一概念的内容。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-44","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":44,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"虽然自第二次世界大战以来，金融资本有所增加，并经历了结构上的变化，但它的目标仍然与它一直以来的目标完全相同，即通过剥削国内外广大劳动人民来获取最大限度的利润。近年来，主要资本主义国家的保险公司大幅增加，成为银行的竞争对手，它们也扮演着同样的角色。例如，在美国，1970年与1950年相比，银行资产增加了3.5倍，而同期保险公司的资产增加了6.5倍。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-45","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":45,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"通过掠夺人民积累的资产，这些公司得以向垄断企业提供高达数亿美元的巨额资金。这样，保险公司就与工业与银行业的垄断企业进行合并、联动，成为金融资本的有机组成部分。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-46","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":46,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"垄断资产阶级在对利润的贪得无厌驱使下，把工人养老基金、人民储蓄等一切暂时可用的货币手段都变成资本。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-47","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":47,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"集中的金融资本不仅从康采恩、小实业家等吸收的资金所产生的利润中，而且还从发行证券和提供贷款中获得异常巨大的收入。就像储蓄存款一样，在发行证券和提供贷款中，只有一小部分利润流向了贷款人，而银行本身从这些活动中赚取了巨额利润，通过这些活动，它增加了自己的资本和投资，当然，这就为金融资本创造了源源不断的额外利润。金融资本主要投资工业，但它也将其投机网络扩展到其他地方，如土地、铁路和其他分支机构和部门。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-48","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":48,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"银行确实有可能提供大量的信贷，这是生产高度集中和垄断统治所需要的。这样，就为大垄断联合企业在国内外加紧对劳动群众的野蛮剥削，以保证其最大利润创造了有利的条件。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-49","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":49,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"随着资本主义在苏联和其他修正主义国家的复辟，那里的银行呈现出垄断的所有特征。在这些国家，银行为剥削国内外广大劳动人民服务，就像在所有其他资本主义国家一样。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-50","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":50,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"近年来，在资本主义国家和修正主义国家，顾客购买消费品，特别是耐用消费品的分期付款贸易额迅速增长。这种信贷的提供保证了资产阶级市场的商品销售，资本家从高利率中获得了巨大的利润，而债务人则被债权人和资本主义公司束缚着手脚。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-51","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":51,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"银行和借贷机构对劳动人民的借款和其他劳动人民承担的债务，目前已大大增加。仅在美国，1976年人民从这种信贷中所欠的债务已达到1670亿美元，而1945年只有60亿美元，而在德意志联邦共和国，人民的债务已超过460亿马克。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-52","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":52,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"银行资本的日益集中和垄断，导致金融寡头对政治经济的统治日益加强，并利用一系列的形式和方法，增加了广大劳动人民的经济束缚、贫困和苦难。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-53","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":53,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"金融资本的发展使一小群有权势的工业资本家和银行家不仅积累了大量的财富，而且集中了真正的经济和政治力量——使整个国家的人民都能感受到的力量。这些无所不能的人是垄断企业和银行的领导者，构成了所谓的金融寡头。从大公司现在已经转变为股东公司，甚至一些工人也可能持有一些象征性的股份的事实出发，资本主义的辩护士们声称，资本现在已经丧失了马克思论证“资本”或列宁分析帝国主义时期带有的那种私人性，转而成为了全民的资产。但这是无稽之谈。今天，同过去一样，强大的私营工业——金融集团控制着帝国主义国家：美国有洛克菲勒家族、摩根家族、杜邦家族、梅隆家族、福特家族、芝加哥、德克萨斯、加利福尼亚等集团;英国有罗斯柴尔德家族、贝林家族、塞缪尔家族等金融集团；西德有克虏伯、西门子、曼内斯曼、蒂森、格林等;意大利有菲亚特、阿尔法-罗密欧、蒙迪森、奥利维蒂等；法国有众多大家族；等等。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-54","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":54,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"金融寡头作为工业资本和金融资本的拥有者，在整个国家生活中确立了对经济和政治的统治。他们甚至将国家机构隶属于自己，将它转变为手中的工具，为自己的利益服务。金融寡头解散、认命政府，决定国内政策与外交政策。在国内生活中，金融寡头同反动势力和维护其政治和经济力量的所有政治、思想、教育和文化制度相联系，而在外交政策上，它又保护与支持一切保守和反动势力，这些势力支持它，为它的垄断扩张开辟道路，为维护和巩固资本主义而斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-55","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":55,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"金融寡头，毫不犹豫地利用各种手段来确保自己的统治地位，在各个领域建立起政治权威。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-56","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":56,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“……金融资本，”列宁说：“带有统治的趋向而不是自由的趋向。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-57","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":57,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"今天的情况证明，垄断资产阶级的压迫，到处都在加剧。在这个基础上，无产阶级和资产阶级的矛盾日益加深。同时，经济和金融的扩张，伴随着政治和军事的扩张，进一步加剧了人民与帝国主义的矛盾，以及帝国主义列强之间的矛盾。中国修正主义者当下的宣传忽视了这一不可否认的客观现实。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-58","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":58,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"银行资本的集中和垄断不只发生在一个国家，还会发生在几个资本主义国家，或资本主义国家和修正主义国家中。欧洲共同市场的联合银行，世界经济合作组织的国际银行，以及经互会的投资银行就具有这种性质。同样，西德-波兰银行或英-罗马尼亚银行、法-罗马尼亚银行或英-匈牙利银行、美-南斯拉夫银行、英-南斯拉夫银行以及其他银行公司的合并，都是资本主义类型的银行联盟。苏联在许多资本主义国家开设了很多银行，这些银行无论在苏黎世、伦敦、巴黎、非洲、拉丁美洲还是其他地方，都成为资本主义银行的竞争对手和合作伙伴。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-59","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":59,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国也被越来越深地卷入资本主义银行一体化进程的漩涡。除了自己设在香港、澳门和新加坡的银行，明天中国还将在日本、美国和其他地方设立银行。与此同时，它正允许帝国主义列强的银行渗透入中国。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-60","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":60,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁强调，当下资本主义的特点是资本输出，今天帝国主义的这种经济特点得到了进一步的发展和加强。今天世界上最大的资本输出国有美国、日本、苏联、联邦德国、英国和法国。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-61","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":61,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在一段时期内，美国、英国、法国和德国等工业发达的国家向外输出资本，这些国家从殖民地吸走了地上和地下的财富。后来，由于战争及危机的影响，英、法、德等帝国主义列强在经济上受到削弱，而美帝则使自己富强起来，成为超级大国。在第二次世界大战后的形势下，美国资本的大量出口对其他资本主义列强是十分有害的。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-62","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":62,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"今天，美国资本以投资、信贷、贷款、合资公司合作或设立大型工业公司的形式输入到任何国家，甚至是工业化国家。美帝垄断资本投资于欠发达国家和贫困国家，因为这些国家的生产成本低，而劳动人民的剥削程度高。它投资是为了获得原材料，垄断市场，销售工业产品。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-63","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":63,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"众所周知，资本主义国家的发展是不均衡的，因此，美国和其他国家的大垄断企业与公司恰恰会向那些需要投资和技术来支持经济发展的国家出口资本。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-64","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":64,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"资本在这些地方的投入为金融康采恩和垄断企业带来了丰厚的利润，这是因为由于在贫穷、不发达的国家，土地非常便宜，大片的土地，连同土地蕴含的财富，可以用很少的钱买到。劳动力也很便宜，因为处于饥饿边缘的人们被迫以极低的工资工作。据计算，帝国主义列强在这些国家每投资一美元，就能获利五美元。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-65","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":65,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"根据美国官方数据，仅在1971年至1975年期间，美国对新成立国家的直接投资就达到65亿美元，而同期在这些国家的利润接近300亿美元。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-66","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":66,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"帝国主义列强为了掩饰资本的输出，也采取提供信贷的做法。通过这些所谓的信贷或援助，资本主义的大康采恩和其所属国家给受援国和人民施加上沉重的压力，使他们被控制。对不发达国家的“援助”或信贷，既来自于对这些国家财富的掠夺，也来自于对发达国家劳动群众的剥削，并且会给予不发达国家的富人。换句话说，这意味着，例如美国的大型垄断企业，从美国人民和其他国家人民的汗水中获利，当他们输出资本和发放贷款时，这些恰恰代表的是这些国家人民的汗水和鲜血。另一方面，这些垄断巨头为所谓的第三世界国家提供的信贷，实际上都用在了这些国家封建资产阶级的统治上。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-67","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":67,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"新成立的国家所得到的信贷是其人民脖子上戴着的帝国主义锁链的一环。统计数据显示，这些国家的债务每五年翻一番。欠发达国家欠帝国主义列强的债务从1955年的近85亿美元增长到1977年的1500多亿美元。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-68","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":68,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"世界资本主义为了自身的利益发展科技和专业，以便从地下资源的发现、农业的集约化等方面获得成倍的利润。所有这些技术，科技革命本身，以及新的经济剥削方法，都是为帝国主义，为资本主义垄断而服务，而不是为人民服务的。资本主义从来不会在没有事先计算好自己将获得的利润之前，就进行投资、提供贷款或向其他国家输出资本。在资本主义和修正主义世界到处伸展开蜘蛛网的大垄断企业和大银行，除非被提供有关开采一个矿场、土地、从沙漠中开采石油或水等等收入的具体数据，否则永远不会给予信贷。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-69","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":69,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"还有其他形式的信贷，比如那些伪社会主义国家所实行的信货，而这些国家试图掩盖他们所走的资本主义道路。这些是以贸易信贷形式提供的大额信贷，当然，这些信贷必须在短时间内偿还。这些给受援国的信贷是由许多资本主义国家共同提供的，这些国家事先计算了它们将从受援国获得的经济和政治利益，同时考虑到受援国的经济潜力和支付能力。资本家决不为社会主义的建设提供信贷。他们只会提供信贷来破坏社会主义。因此，真正的社会主义国家绝不接受资本主义国家、资产阶级或修正主义国家的任何形式的信贷。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-70","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":70,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"和赫鲁晓夫的苏联修正主义一样，中国的修正主义者也使用了许多“列宁主义”、“革命性”的口号、语录和短语，但他们真实行动是反动的、反革命的。中国领导人甚至试图表现出他们机会主义的对帝国主义国家的政策，以及与帝国主义国家的关系，仿佛他们是为了社会主义的利益。这些修正主义者利用这种伪装，目的是把无产阶级群众和人民蒙在鼓里，这样他们就不会把不满转化为进行革命的有力武器。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-71","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":71,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"让我们以国家的经济建设问题为例，依靠自己的力量发展社会主义经济，这个原则是正确的。每一个独立的、不稳定的、主权的社会主义国家必须动员所有人，并正确制定其经济政策，必须采取一切措施，对国家的所有财富进行适当和最合理的利用，并节俭地管理这些财富，必须为了本国人民的利益而增加财富，并且绝不允许他人对其进行掠夺。这是每一个社会主义国家的基本大方向，外国和其他社会主义国家的援助是相辅相成的。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-72","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":72,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"两个社会主义国家所达成的信货协议具有截然不同的性质。这些信贷构成了无私的国际主义援助。国际主义援助不产生资本主义，不使人民群众贫困，相反，它有利于发展工农业，有利于工农业的协调，有利于改善劳动群众的生活，有利于加强社会主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-73","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":73,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"首先，经济发达的社会主义国家应该帮助其他社会主义国家。这并不意味着社会主义国家就不应该同其他非社会主义国家发展关系。但是，这些关系必须是建立在共同利益基础上的经济关系，决不能使社会主义国家或任何其他非社会主义国家的经济依赖于更强大的国家。如果国家间的这种关系是建立在大国剥削弱小国家的基础上的，那么就必须拒绝这种“援助”，因为它变成了奴役。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-74","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":74,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁说，金融资本已经在世界上所有的国家撒网。资本家的垄断企业、卡特尔和财辛迪加是有系统地运作的，他们首先占领自己国家的内部市场，控制工农业，奴役工人阶级和其他劳动人民，赚取超额利润，然后争取一切可能性去垄断世界各地的市场。金融资本对此起着直接作用。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-75","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":75,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"今天，我们看到，这完全符合列宁关于帝国主义是资本主义的最后阶段的学说，两个超级大国，美帝和苏联社会帝国主义，为了占领市场，正在争夺世界的分配权。例如，石油问题在世界各地都很严重，它首要是美国大垄断企业的领域，但英国、荷兰和其他石油公司也参与其中。美国人正在石油问题上耍花招，以便完全垄断它。他们在沙特阿拉伯、伊朗等产油国投入了大量资金，建立了大规模的设备，并通过向国王、酋长和伊玛目行贿巨额美元，将这些国家的统治集团控制起来。这些国家的财阀允许石油生产国的统治者在美国、英国和其他地方投资，甚至购买各种垄断公司的股票，以及豪华酒店、工厂等。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-76","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":76,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"例如，沙特阿拉伯是一个半封建国家，在那里贫穷和蒙昧横行，尽管它每年能开采出4.2亿吨石油，但工农群众生活在贫困之中，而国王和大地主阶层仅在华尔街银行就存入了400多亿美元。科威特、阿拉伯联合酋长国和其他地方的情况也一样。这些统治集团向帝国主义列强作出各种让步，掠夺他们所统治国家人民的资产，目的是为他们自己谋取利益。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-77","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":77,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"石油生产国所作的投资属于统治集团的财产，当然，这些集团的资本与美国或英国资本在很小的规模上构成了一个联盟。从表面上看，石油生产国的统治集团似乎与美、英、法帝国主义有某种投资伙伴关系，据称还影响着后者的经济。事实上，情况恰恰相反。美帝和其他帝国主义者得到的利润，与分配给这些集团的利润相比，是十分巨大的。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-78","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":78,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"这是当今新殖民主义的一个特点，它为了能够最大限度地利用一些国家的财富，谨慎地向资产阶级资本主义统治集团、封建统治集团让步，当然，不损害自己的利益。这个例子证实了列宁论点的正确性，即各国资产阶级的利益可以很容易地相互关联，正如私人垄断企业的利益可以与国家垄断企业的利益相互联系一样。大型垄断企业也可能与实力较弱但控制大量资产的垄断企业合并，尤其是控制铁、铬、铜、铀等地下资源的垄断企业。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-79","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":79,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"政府贷款、信贷和援助已成为当今资本输出最广泛的形式之一。特别是苏联和其他修正主义国家也在实行这种输出。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-80","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":80,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"除了榨取资本主义利润，这些信贷、“援助”和贷款也有政治目的。给予这些国家信贷旨在支持和巩固特定集团的政治和经济权力，而这些集团会保卫债权国的经济、政治和军事利益。由于各国政府之间缔结了关于这种信贷的协定，这些协定使债务国对债权国的经济和政治依赖更加严重。这种资本输出形式的一个经典例子是“马歇尔计划”[2]，它在第二次世界大战之后成为美国在西欧国家政治和军事扩张的经济基础。苏联修正主义者所谓的援助，据称是为印度、伊拉克和其他国家的经济发展和建立国营工业部门而提供，其性质是相同的。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-81","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":81,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"目前，美帝、苏联社会帝国主义和工业化资本主义国家已经达到了从资本积累中获取的利润极速增长的发展阶段。资本的积累创造了巨大的利润，这些利润进入了垄断者——即金融寡头的口袋，他们不把这些收入用来为贫困的劳动人民服务，而是把它们输出到那些可能给他们带来更大利润的国家。这些国家被中国称为“第三世界”。然而，他们也在发达资本主义国家进行这类投资。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-82","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":82,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"有关美国资本渗透到欧洲的过程及其政治和经济目标，人们已经写了很多书。美国作家杰弗里·欧文[3]在书中对这一点给出了明确的描述。在“国际公司”一章的开头，他说美国对外投资的发展是基于这样一个概念，即美国公司代表的不是拥有海外利益的公司，而是国际公司。这些公司的总部设在美国。这意味着，美国各大公司不仅要考虑覆盖自己的国家，满足美国国内工业和客户的需要，还要考虑把网撒到国外。这些公司把他们的“过剩资本”投资到其他国家，以获得更大的利润。像“纽约标准石油公司美孚”、“新泽西标准石油公司”等巨头公司，近一半的利润来自于对外国的掠夺和剥削。大约500家公司每年在国外获得大约100亿美元的利润。在国外投资的这类企业有3000多家。这就是“跨国公司”、“国际资本主义”等公式和术语在新闻和银行业务中的日常应用。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-83","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":83,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"杰弗里·欧文说，1929年，超过1300家欧洲公司被美国公司拥有或控制。这是美国进军欧洲工业的第一阶段。当时愈演愈烈的第二次世界大战的压力，暂时阻止了美国资本的入侵。从1929年到1946年，美国公司在世界其他国家的直接投资额从7500万美元下降到7200万美元。然而，在第二次世界大战之后，1950年，美国在海外的投资增加到11.2亿美元，其中一半集中在拉丁美洲国家和加拿大。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-84","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":84,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在拉丁美洲的投资是为了开发这些原材料：石油、铜、铁矿石、铝土矿以及香蕉和其他农产品。在加拿大，他们主要从事采矿和石油，由于邻近和其他有利于渗透的条件，它们被大规模开发。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-85","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":85,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"20世纪50年代的欧洲也成为美国投资的另一个重要目标。他们在欧洲大陆的通讯、大规模生产产品和复杂设备方面的投资迅速扩大。伴随着投资，美国商品和产品大量涌入。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-86","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":86,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"作者指出，第二次世界大战后资本主义市场的形势给美国投资带来了更大的推动力。以下是这些海外投资增加的数字：1946年，这些投资总额为72亿美元，然后在1950年开始增加到112亿美元，1964年增加到443亿美元，1977年增加到600多亿美元。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-87","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":87,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"美国公司不断将业务扩展到世界范围，使得它们与当地公司的竞争更加激烈，也增加了当地公司对美国巨头统治的恐惧。这一问题在不发达国家更为严重，在这些国家，美国公司控制着工业的主要部门，并在这些国家的国民经济中发挥着重要的影响。换句话说，这些庞大的美国公司控制着当地的经济和政府，实际上他们就在经营这些经济和政府。美国石油公司和墨西哥政府之间旷日持久的斗争是众所周知的，直到1938年墨西哥政府的反对政策崩溃才结束。英国石油垄断企业与伊朗政府之间也产生了类似的斗争，导致摩萨台[4]被推翻。这种毁灭性的冲突一直在进行，并以美国大型托拉斯的胜利而告终。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-88","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":88,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"大型石油公司的业务遍及全球。对他们来说，完全控制这个分支的所有资本和生产，控制他们投资的国家的政府等等，已经成为正常而必要的，因为，如果它们缺乏这些因素，那么在协调它们在世界范围内的活动上就会出现困难。这就是为什么外国大公司反对当地资本家努力争取比美国投资者或其他帝国主义国家允许的利润份额更大的份额。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-89","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":89,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在欧洲、加拿大、亚洲、非洲和其他地方的美国公司造成了这样一种局面——它们实际上已经控制了许多国家的经济。这些国家的政府非常害怕美国，因为美国使自己已经成为了欧洲经济的领导者，正如它在军事方面所做的那样。因此，欧洲的工业化资本主义国家试图阻止已经并正在越来越多地涌入这些国家的美国资本的入侵。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-90","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":90,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国领导人声称，自19世纪以来，工业化欧洲国家正在美国进行更多的投资。但是，众所周知，欧洲资本在美国的投资主要以证券、股票、债券、存款等形式进行，而美国在欧洲的投资在欧洲经济最重要的部门中占有主导地位。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-91","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":91,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"杰弗里·欧文竭力为美国增加投资而辩护，他声称欧洲国家希望并正在努力发展以科学为基础的产业，例如电子和计算机产业。这些产业在一定程度上促进了这些国家的技术进步、出口增长和整体经济增长。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-92","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":92,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"但是美国公司在这个领域比他们的欧洲竞争对手更先进，他们为了自己的利益，控制科技的进步。例如，在计算机制造方面，两家欧洲公司建立了密切的联系，以保护自己免受美国IBM的竞争——美国IBM控制着美国70%以上的市场，甚至更大的世界市场份额。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-93","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":93,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"同样，美国大公司有可能与当地企业成立合资企业。为了掩饰他们的剥削，许多公司避免拥有百分之百的子公司所有权，并在49% - 51%或各50%的共同投资基础上设立公司。这就是美国人在日本的做法，也是他们在宣称自己在自食其力建设社会主义的南斯拉夫的做法。而实际上，铁托分子在经济上分裂南斯拉夫，分给美国和其他工业发达国家的大公司。这样做也限制了南斯拉夫的自由和独立。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-94","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":94,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"许多美国大公司，如“通用汽车”、“福特”、“克莱斯勒”、“通用电气”等，实际上都有百分之百拥有其外国子公司的倾向。然而，欧文认为，这些子公司永远不会忘记国有化带来的问题，它们对此的回答是，“这不是与当地投资者一起设立公司的问题，而是鼓励国际投资者去持有母公司的股份的问题”。这就是资本主义的“国际”概念，尤其是“通用汽车”是这一概念的狂热拥护者。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-95","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":95,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"美帝资本或美国工业机构的这些倾向——投资于美国以外的地方，以便建立殖民地、实现帝国梦，只是少数几个事实，这些事实清楚地说明，尽管中国修正主义者掩饰，但美帝丝毫没有被削弱。相反，它已经变得更加强大，在外国获得了很大的优惠，并且经营着许多重要的经济部门。它也给其他国家的政府造成了无数的困难，经常在这些国家制定法律，并控制和指导许多政府。当然，这个过程有起有落，但总趋势并不表明美帝的衰落。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-96","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":96,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"我们现在处在另一个超级大国苏联社会帝国主义正在输出其资本，并渴望剥削不同民族的时代。这个超级大国输出的资本来自于苏联创造的剩余价值，苏联已经转型为资本主义国家。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-97","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":97,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"资本主义的恢复导致了当今苏联社会的两极分化，一小部分人统治和剥削了绝大多数人。现在，由官僚、技术官僚和上层创造性知识分子组成的阶层已经被创造出来，并以一个独立的资产阶级剥削阶级的形式出现，这个阶级从对工人阶级和广大劳动群众的野蛮剥削中攫取和瓜分剩余价值。与古典资本主义国家不同，古典资本主义国家的剩余价值是按每个资本家的资本总额的比例分配的，而在苏联和其他修正主义国家，它是根据上层资产阶级在国家中的地位、经济地位、科学地位、文化地位等来分配的。高工资、经常性奖金、专项奖金、奖项刺激、优惠待遇等，已经形成了从劳动人民的血汗中榨取剩余价值的一整套制度。代表“集体资本家”的阶层通过一系列法律法规来保护这种掠夺，这些法律法规保证了资本主义的压迫和剥削。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-98","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":98,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"苏联经济现在已经融入了世界资本主义体系。在美、德、日等资本深入苏联的同时，苏联资本也在向其他国家输出，并以各种形式与当地资本融合。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-99","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":99,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"众所周知，苏联首先在经济上剥削卫星国。但是现在它正在与其他资本主义国家竞争和争夺市场、投资领域，以便掠夺原材料，在世界贸易中维护新殖民主义法律等等。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-100","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":100,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"苏联新资产阶级一心想要扩大自己的霸权，便输出资本，但在这里，它不仅要面对强大的美帝的竞争，还要面对日本、英国、西德、法国等发达资本主义国家的竞争。这些国家为了谋取暴利，不仅向非洲、亚洲和拉丁美洲输出资本，而且向修正主义苏联监视下的东欧国家输出资本，甚至向苏联本身输出资本。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-101","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":101,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"所谓社会主义国家的统治集团，如苏联、捷克斯洛伐克、波兰等，以及现在的中国，都允许外国资本进入他们的国家，因为这些资本是为统治集团服务的，但同时也给人民带来沉重的负担。经互会成员债台高筑。他们欠西方国家的债务高达500亿美元。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-102","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":102,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"南斯拉夫是第一批允许外国资本进入其经济领域的修正主义国家之一。首先，南斯拉夫获得信贷，然后购买特许，之后转向成立合资企业。在南斯拉夫，1967年通过了一项法律，允许设立合资企业，其中49%的资本由外国公司拥有。1977年，南斯拉夫有170家这样的企业。南斯拉夫为资本主义公司的活动提供了最有利的条件，确保了利润的最大化。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-103","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":103,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"南斯拉夫的现象证明，外国资本在南斯拉夫的投资是使南斯拉夫成为资本主义国家的决定性因素之一。美国和其他富有的资本主义国家在这些投资中没有任何损失。相反，他们获得了巨额利润，同时增加了南斯拉夫工人阶级和农民的痛苦。列宁说过，资本的输出是剥削世界上大多数民族和国家的坚实基础，因为资本主义只寄生于少数非常富有的国家。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-104","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":104,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"资本主义国家也将在中国获得巨额利润。我们看到，美国、日本、西德和其他国家的资本正以数十亿美元的规模涌入中国。中国与日本签署了联合开发长江油田和电力资源的协议，与德国人就煤矿等的建设达成协议，等等。在中国进行的和将要进行的投资必将给外国资本家带来可观的利润，但同时也会加强资本主义在中国的基础。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-105","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":105,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"一个资本主义国家向另一个资本主义国家或修正主义国家输出资本，无论给予或接受资本的国家是大是小，始终是资本剥削人民的一种形式。这种剥削导致受援国在经济和政治上的依赖。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-106","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":106,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁指出，垄断企业在占领国内市场后，为了重新划分和占领世界工业产品和原材料市场，会进行经济斗争。激烈的竞争及对利润的贪婪促使不同国家的垄断者达成临时协议，相互结盟5合并，以分割国际产品市场和原料市场。发达资本主义国家即使拥有原材料和能源储备，也会把矛头指向其他国家，因为这些国家的生产成本比它们自己的国家低，尤其是工人的工资更是低了好几倍。为争夺石油资源和市场而进行的斗争是臭名昭著的。这场斗争的结果是几十上百家私营企业和公司破产，而国际石油卡特尔，包括七大垄断企业(五个美国的，一个英国的，一个英国和荷兰的，有臭名昭著的埃索、德士古、壳牌等等),成功控制了西方资本主义国家60%以上的石油开采和石油销售，以及54%的石油加工产业。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-107","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":107,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"今天，铜、锡、铀和其他有价值的战略矿产也有类似的资源和市场划分。许多老牌殖民主义国家，如英国和法国，都与前殖民地签订了特别的、所谓优惠的合作协议等等，这确保了它们享有几乎排外的经济和商业特权。所谓的美元地区、英镑地区、法郎地区或卢布地区表明世界上垄断者和各帝国主义国家之间存在着经济上的分裂。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-108","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":108,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"美帝、苏联社会帝国主义和其他帝国主义列强通过与这些国家进行的歧视性和不平等的贸易，以不同的方式确保了利润的最大化。今天除了欧佩克国家以外的发展中国家，就有大约340亿美元的借方余额。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-109","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":109,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在当前条件下，尤其是在这经济危机的情况下，垄断企业还与资本主义国家政府就生产配额、价格、市场等问题达成直接协议。欧洲共同体、经互会等组织的存在，也是当今世界经济分化的明显证据。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-110","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":110,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"世界的这种经济分工、垄断的统治、垄断对其他国家生活和经济发展的支配，使劳动力和资本的矛盾、人民和帝国主义的矛盾、帝国主义内部的矛盾更加严重。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-111","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":111,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国的“三个世界”理论，试图调和“第三世界”、“第二世界”和美帝，与这一现实是格格不入的是，它不希望看到美国、英国、德国、日本、法国和其他垄断者对中国称作的“第三世界”的无情进攻正在增加各国人民对一切帝国主义和霸权主义列强的抵抗，扩大各国人民进行不可调和斗争的客观条件。另一方面，帝国主义列强发展的不平衡，是资本主义发展的客观规律，促使它们在世界各地谋求经济扩张的过程中相互竞争、磨擦。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-112","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":112,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国的\"三个世界\"理论力图调和这些矛盾，并恰恰提倡社会民主主义和各种色彩的修正主义者长期以来所鼓吹的，是对列宁主义战略的公然反对，列宁主义战略不但不否认这些矛盾，而且旨在激化这些矛盾，为无产阶级革命和人民解放做铺垫。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-113","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":113,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁在分析帝国主义时指出，随着垄断前资本主义过渡到它的最高和最后阶段，即帝国主义阶段，世界各大帝国主义列强之间的领土分割就完成了。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-114","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":114,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“……应当说，我们所考察的这个时期的特点是世界瓜分完毕。所谓完毕，并不是说不可能重新瓜分了?----相反，重新瓜分是可能的，并且是不可避免的——，而是说在资本主义各国的殖民政策之下，我们这个行星上无主的土地都被霸占完了。世界已第一次被瓜分完毕，所以以后只能是重新瓜分，也就是从一个“主人”转归另一个“主人”，而不是从无主的变为“有主的”……”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-115","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":115,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"自第二次世界大战以来，在物质、经济、政治和意识形态上剥削世界大多数人民的旧的古典殖民主义已经转变为一种新的殖民主义。这种新殖民主义包括一整套系统的经济、政治、军事和意识形态的措施，帝国主义建立它们的目的是维护其统治，确保能政治控制和经济剥削前殖民地和其他许多国家,而本身适应战后涌现的新条件。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-116","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":116,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"战争结束后，帝国主义国家法国、英国、意大利、德国、日本和美国都无力以武力维持战前的局面。例如，法国不能再象过去那样维持摩洛哥、阿尔及利亚、突尼斯和其他非洲国家殖民地地位。英国、意大利和其他帝国主义也是如此。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-117","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":117,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"第二次世界大战使世界上的力量比例发生了根本性的变化。它导致了法西斯列强的失败，但也极大地削弱了旧殖民主义列强，动摇了它们的根基。在任何地方，甚至在没有卷入这场旋风的国家，反法西斯战争都引起了民族解放的问题。前殖民国家的人民为了摆脱法西斯的枷锁，同反法西斯联盟国家一起参加了战争，他们不能再回到殖民的奴役中去，也不能再容忍这种奴役。苏联对纳粹主义的胜利，社会主义阵营的建立，中国的解放，极大地推动了人民民族意识的觉醒和解放斗争。殖民地的广大人民群众逐渐认识到必须改变过去的状况。解放战争在印度支那、北非和其他地方爆发。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-118","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":118,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在这种形势的逼迫下，许多殖民主义国家认识到，不给予任何自由和独立的对殖民地旧的剥削和管理方法已经过时。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-119","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":119,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"殖民帝国主义列强得出这一结论，不是因为他们的民主感情，也不是因为他们想给人民自由，而是因为殖民地人民的压力，以及这些列强在军事上、经济上、政治上和意识形态上都过于虚弱，不能维系旧的殖民主义。但是，法国、英国、意大利、美国和其他帝国主义国家不愿放弃对这些民族和国家的剥削。在目前的情况下，每一个帝国主义列强都被迫给予这些民族自治权，或答应他们在一段时间后获得自由和独立。在此期间,据称，他们允许建立独立政府的思想并为此在当地培训干部，实际上他们真正目的是准备其他新形式的帝国主义剥削和新殖民主义，同时在这些国家和人民中间制造一种假象：他们赢得了自由。这是战后世界帝国主义遭受大败的阶段，是帝国主义殖民制度危机更加突出的时期。在资本主义衰亡的这个时期，由于第二次世界大战削弱了帝国主义，美国抓住了这一机会，使名义上变得自由和独立的殖民地人民遭受了更严重的新剥削。它把帝国主义的势力扩展到其他已经在某种程度上被削弱了的帝国主义列强的前殖民地上。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-120","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":120,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"尽管他们赢得了那种形式的“独立”和自由的承认，由于帝国主义不愿勉强承认这些，许多前殖民地人民被迫拿起武器。特别是法国帝国主义者，即使在战争之后，仍然试图维护法国的力量，或者说是威严。因此，阿尔及利亚、越南和许多其他国家的人民开始了争取解放的长期斗争，并且最终取得了胜利。在这里，我们不会详细讨论他们是如何实现这一目标的，哪种社会力量去进行斗争的，等等。事实是旧的法英帝国主义被削弱了。列宁关于帝国主义正在衰落，旧的资本主义-帝国主义社会正在被革命运动与受欺压受奴役人民热爱自由的愿望所侵蚀的论点得到了证实。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-121","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":121,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在此期间美帝壮大起来，扩大了美元区，将法郎和英镑地区的领土置于其控制之下，而且,为了保护其建立在对人民最大化剥削基础上的霸权帝国主义力量，它在世界上许多名义上已获得自由和独立的国家建立了许多军事基地和亲美政治集团。当然，这种剥削也与结构和上层建筑的一系列变化有关。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-122","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":122,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"金融资本也创造了自己独特的意识形态，它在剥削无产阶级和征服世界的方面还要优于金融资本。金融资本确立了对人民的统治，并以各种粉饰太平的假自由、假独立的形式以及建立了一些所谓的民主党派等来为这种统治辩护。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-123","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":123,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"随着银行和跨国公司的创立，以及美国资本的投资，美国固有的、堕落的生活方式也被输出。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-124","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":124,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"帝国主义列强的资本输出创造了殖民地，今天，这些殖民地就是新殖民主义统治的国家。这些国家有所谓的独立，但只是形式上的独立，换句话说，现在和过去一样，同样的资本输出过程正在进行，虽然形式不同，但却有“甜言蜜语”的解释和宣传。对这些国家人民的无情剥削没有改变，甚至变得更加残酷；对自然资源的掠夺还在继续。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-125","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":125,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"我们这个时代最大的新殖民主义力量是美国。在1973年至1975年的三年内，美国在前殖民地、未独立或半独立国家的政府与私人资本的投资占最发达的资本主义和修正主义国家在这些地区总投资的36%左右。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-126","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":126,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"帝国主义列强与前殖民地国家之间的经济、政治、军事条约和协定，都是帝国主义为使这些国家处于奴役状态而装备的武器。列宁强调：","language":"中文","translation":false},{"id":"hoxha-imperialism-2-127","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":127,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“……必须向一切国家、特别是落后国家的最广大的劳动群众不断地说明和揭露帝国主义列强一贯进行的欺骗，即打着建立政治上独立的国家的幌子，来建立在经济、财政和军事方面都完全依赖于它们的国家。”（出自《为共产国际第二次代表大会准备的文件》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-128","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":128,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"这句话在今天和过去一样有效。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-129","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":129,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"为了保持对人民的统治，美帝，苏联社会帝国主义和或新或旧的其他帝国主义列强在邻国之间，或在某一国家内的不同社会群体之间，煽动任何可能的冲突，然后,以法官或者一方或另一方的支持者的角色，干涉别国内政，并为他们在那里的经济、政治和军事存在辩护。事实表明，每当超级大国干涉别国人民的内政时，这些问题就得不到解决，其结果就是帝国主义和社会帝国主义在这些国家的地位得到巩固。中东局势、索马里与埃塞俄比亚冲突、柬埔寨越南战争[5]等就是明证。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-130","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":130,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"美国、苏联和所有其他资本主义国家连同它们的投资在争取市场和势力范围时，也巩固了它们在接受这些投资的国家中的地位。这就导致了不同资本主义国家之间的摩擦，也导致了不相关、不相互依存的重大问题之间的摩擦。这些摩擦引发了局部战争，甚至可能导致全面战争。列宁主义告诉我们，由于这些原因而爆发的战争，无论是局部的还是普遍的，都是掠夺性的，而不是解放性质的。只有当人民起来反对外国侵略者的时候，只有当他们起来反对与帝国主义、社会帝国主义和世界资本紧密联系在一起的地方资产阶级的时候，这才是一场正义的解放战争。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-131","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":131,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"世界大资本的代表们正津津乐道地谈论着对现有国际经济关系体系进行修正的必要性，以及建立“新的世界经济秩序”的必要性，中国领导人也支持这一观点。他们认为，这种新的经济秩序将成为“全球团结的基础”。就苏联修正主义者而言，他们则谈论要建立所谓的国际经济关系新结构。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-132","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":132,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"这些都是帝国主义和新殖民主义列强所做的努力与制定的计划，它们要使新殖民主义继续存在，延长它的寿命，并保持它们对人民的压迫和掠夺。但是资本主义和帝国主义的发展规律，既不服从资产阶级和修正主义者的愿望，也不服从他们发明的理论。正如列宁所说，坚持不懈地反对殖民主义和新殖民主义，进行革命，才是解决这些矛盾的出路。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-133","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":133,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁在分析帝国主义的基本经济特征时，也明确了它在历史上的地位。他强调，帝国主义不仅是资本主义的最高阶段，而且是资本主义的最后阶段，无产阶级革命的前夜。列宁指出：","language":"中文","translation":false},{"id":"hoxha-imperialism-2-134","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":134,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“帝国主义是资本主义的特殊历史阶段……是(1)垄断资本主义;(2)寄生或腐朽的资本主义；(3)垂死的资本主义。”（出自《帝国主义和社会主义运动中的分裂》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-135","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":135,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"当今资本主义世界的现实充分证实了这一结论。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-136","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":136,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"正如列宁所证明的那样，帝国主义的一切社会经济弊病的经济基础是垄断。垄断对克服资本主义经济矛盾无能为力。列宁把帝国主义的寄生和衰亡同垄断者抑制生产力的发展、深化各部门与国民经济的不协调发展、不充分利用人和物质的生产能力的倾向有机地联系起来，同阻碍科学技术新发展应用于造福人民群众和整个社会进步的趋势有机联系起来。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-137","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":137,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"对利润的贪婪和竞争，迫使垄断企业在生产过程中投资先进技术。但在帝国主义发展的整个历史进程中，其主要趋势是发展不平衡和制约发展。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-138","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":138,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"例如，在美国，工业领域，特别是战争工业的研究和科学发展的开支从1950年的20亿美元增加到1965年的近110亿美元和1972年的约300亿美元。大公司经常在科学研究中遇到困难，但是一旦发现了什么，他们就买下专利并雇佣合格的工作者；然而，只有它们的自身利益需求时，他们才会应用这项研究。自然，发展和技术革命领域吸引了更大的投资兴趣，因为它们提供了更大的盈利可能性。军工行业位居榜首，因为它的利润率是最高的。例如，1964年，美国在航空和导弹领域的科学研究上投资了35.65亿美元。同年，10.00537亿美元投资在电子和电信行业,1.96亿美元投资于化工行业,1.36亿美元投资于机械制造行业,1.74亿美元投资在汽车行业,1.72亿美元投资在科学仪器上，3800万美元投资于橡胶行业,800万美元投资在石油工业上，900万美元投资在在甲烷工业，等等。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-139","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":139,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在今天的条件下，经济的军事化作为帝国主义衰亡的表现，已成为所有资本主义和修正主义国家的典型特点。但是，经济的军事化进程已达到空前的程度，特别是在美国和苏联。双方直接军事开支已增长到天文数字，达到每年2400多亿美元。美国和苏联在其霸权主义和统治世界的政策中，也在广泛地利用武器贸易，这是帝国主义衰落的另一个明显表现。他们每年出售价值200多亿美元的武器。其他帝国主义国家，如英国、西德、法国、意大利等，也从事军火买卖。这种帝国主义贸易的常客是智利、巴西、阿根廷、以色列、西班牙、韩国、罗得西亚、南非联邦等国的反动法西斯集团。这些客户中还包括那些拥有丰富战略原料或石油的国家，帝国主义向这些国家提供武器作为诱饵，诱使它们允许帝国主义掠夺它们的财富。生产过剩经济危机的日益频繁爆发，清楚地证明了当今垄断资本主义的衰落和寄生性质。危机的爆发，现在已经日趋严重，证明了马克思主义关于生产和消费的无政府性、自发性和非均衡性的理论的正确性，驳斥了资产阶级关于资本主义发展“无危机”、或是资本主义向“受管制的资本主义”转变的“理论”。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-140","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":140,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"马克思发现的资本主义积累的一般规律，即劳动人民的贫困程度一步步加深，一方面，资本家的利润却不断增加，另一方面，这种贫困程度的加深在今天的资本主义社会中正在发挥出越来越大的影响。社会向无产阶级和只有很有限人数的资产阶级分化的进程正在深化。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-141","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":141,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"今天的帝国主义制度，拥有更大的经济上的可能性去腐化无产阶级的上层，即工人贵族阶级，因而把工人贵族阶级的人数增加到非常大的比例。金融寡头今天正在广泛地利用这种工人贵族来统治，欺骗和迷惑无产阶级，抑制他们的革命热情。列宁称为在言辞上为社会主义者，在行动上为帝国主义者的人通常就是从这种工人贵族中产生的。社会民主主义、“资产阶级工人党”、工会的机会主义领导人、现代修正主义者等等，都属于列宁描述的范畴。列宁强调，帝国主义是同机会主义联系在一起的，机会主义者是帮助维护和加强帝国主义的。他说：“在这方面最危险的是这样一些人，他们不愿意了解：反对帝国主义的斗争，如果不同反对机会主义的斗争密切联系起来，就是空话和谎言。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-142","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":142,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"帝国主义的衰亡也明显地表现在各个领域——特别是政治和社会领域——的反应的增长和加强上。实践证明，当垄断资产阶级看到阶级斗争日益激烈的时候，它就把一切伪装起来，把工人阶级、群众甚至他们流血所赢得的少数权利都否认了。世界上许多国家建立的法西斯政权和独裁就是这方面的证据。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-143","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":143,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"所有这种腐朽的、处于混乱状态的制度都是由庞大的禁卫军、动员和武装到牙齿的大批警察所支撑的。所有这些军队和警察部队的行动都是为了防止或镇压任何超出由统治阶级制定的一系列法律所规定的限度的抵抗。军队干部和其他充当打手的干部生活富裕，工资丰厚。例如，在意大利，你只听到人们谈论军队、警察、宪兵，谈论被授勋但也被杀害的安全人员。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-144","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":144,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在这种资产阶级国家普遍存在的十分混乱的情况下，强盗主义已经发展起来，并且蔓延开来，这是资本主义秩序本身所孕育的。这是它的堕落的表现，是资产阶级压迫剥削制度所引起的绝望和混乱的反映。资产阶级竭力防止那些给资产阶级国家带来麻烦和烦恼的强盗行为。但它却利用和煽动黑社会来恐吓挣扎于贫困中的广大劳动群众。在许多资本主义国家，犯罪已成为一种产业，从抢劫银行和商店扩展到绑架别人，并索要大笔赎金。在一些国家，黑社会组织成不同的集团。这些团体的名字往往带有“革命”或“共产主义”的意思。资产阶级允许他们自由行动，以便为法西斯政变的发生作好准备，并为其进行辩护。为了败坏革命和社会主义的名声，这种强盗活动被宣传得好像是由所谓的反对资产阶级秩序的“共产主义集团”进行的。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-145","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":145,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"作为结论,我们可以说，整个帝国主义、美帝、苏联社会帝国主义和其他帝国主义在当前形势下，任何形式的帝国主义都处于被削弱和腐朽的阶段，旧社会将被革命推翻，取而代之的是一个新社会，社会主义社会。新的社会主义社会存在并将扩展,它将发展,尽管苏联修正主义者在苏联背叛了社会主义，尽管机会主义在中国盛行，一种新的社会帝国主义正在那里兴起，尽管资本主义已经在旧的人民民主国家得到恢复，但还是取得了进展。社会主义将走自己的道路，通过斗争和努力战胜世界帝国主义和资本主义，但绝不能像赫鲁晓夫和所有修正主义者所鼓吹的那样，通过改革和和平的议会道路来完成，坚持列宁主义的帝国主义和无产阶级革命理论，不走今天修正主义理论的歪门邪道，即国家垄断资本主义是资本主义的一个特殊的新阶段，是“资本主义怀中社会主义成分的诞生”，就一定能取得胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-146","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":146,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"从列宁对帝国主义的本质及其在历史上的地位下的定论来看，由于内部矛盾侵蚀和人民解放的革命斗争，整个世界帝国主义作为一种社会体系不再有不可分割的权利去支配它曾经拥有的一切。这是历史的辩证法，它证实了马列主义关于帝国主义正在衰落、腐朽的论点。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-147","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":147,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"资本主义和帝国主义的衰落是当今世界历史的主流。马克思、列宁是在具体事实、历史事件和唯物辩证法的基础上论证这一点的。反对帝国主义的国家联合起来的趋势也导致了帝国主义的削弱。但是，中国对后一种倾向绝对化，不作必要的区分，不研究具体情况，没有走上正确的道路。一边宣称美帝正在衰落，不如苏联社会帝国主义强大，一边又在赞扬第三世界。中国领导人作为时代的主要动力，实际上是在鼓励对资产阶级的投降和服从。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-148","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":148,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"人民需要解放，这是事实，但是他们只有通过斗争、通过努力和由军事领导者领导才能得到解放。马克思、恩格斯、列宁和斯大林教导我们，这种领导是每个国家的无产阶级。但是，无产阶级和它的马列主义政党，必须从革命的准备和实行出发，进行彻底的政治、经济和军事分析，权衡利弊，作出决定，制定适当的战略和战术。如果像中国人那样忘记了革命，无论是分析、行动、战略，还是战术，","language":"中文","translation":false},{"id":"hoxha-imperialism-2-149","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":149,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"我们不能对任何帝国主义抱有任何幻想，不管它是强大还是弱小。帝国主义从其本质上创造了经济和政治扩张、发动战争的条件，因为它本质上是剥削性的、侵略性的。因此，欺骗想要解放的人民群众以“三个世界”等修正主义理论为指导就能实现解放，就是对人民和革命犯罪。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-150","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":150,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"正如列宁所教导我们的，我们的时代是帝国主义和无产阶级革命的时代。我们马列主义者必须从这一点上认识到，我们必须同世界帝国主义，同一切帝国主义，同一切资本主义势力作斗争——这些势力竭尽全力剥削无产阶级和人民。我们强调列宁主义的论点，即革命现在是大势所趋。世界正在走向一个新的社会，那就是社会主义社会。世界资本主义、帝国主义和社会帝国主义将更加腐朽，并将通过革命走向灭亡。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-151","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":151,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁教导我们，必须同帝国主义斗争到底，必须从广义上批评帝国主义，并且要使被压迫的阶级起来反对帝国主义的政策，反对资产阶级的政策。马列主义对帝国主义今天发展的分析清楚地表明，列宁关于帝国主义和革命的性质和特点的分析和结论是无可动摇的。一切机会主义者，从社会民主党人到赫鲁晓夫主义者和中国修正主义者，企图歪曲列宁主义关于帝国主义的论点，都是反革命的。他们的目的是否定革命，美化帝国主义，延长资本主义的寿命。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-152","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":152,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"当列宁揭露帝国主义及其辩护者伯恩施坦、考茨基、希法亭和第二国际的所有其他机会主义者时，他指出：","language":"中文","translation":false},{"id":"hoxha-imperialism-2-153","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":153,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“帝国主义的意识形态也渗透到工人阶级里面去了。工人阶级和其他阶级之间并没有隔着一道万里长城。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-154","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":154,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"然而不幸的是，甚至“万里长城”现在也被攻破了，帝国主义的宣传和意识形态已经渗透到中国。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-155","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":155,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国的机会主义者一点也不具有独创性。追随考茨基及其共犯的道路，他们也在美化帝国主义，特别是美帝，把美帝说成是正在退却的帝国主义，人民应当依靠美帝来抵御苏联社会帝国主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-156","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":156,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国修正主义者的“理论”与考茨基的“理论”有着明显的相似之处。考茨基试图通过歪曲马克思主义关于资本主义发展的理论，来捍卫帝国主义的殖民政策，掩盖帝国主义的剥削和扩张。今天，中国领导人也在这样做，他们为了支持美帝及其新殖民主义政策，炮制了据称是基于马克思或列宁的荒谬理论。然而，用列宁的话来说，中国的“理论”是陷入修正主义和机会主义的泥潭。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-157","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":157,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"考茨基的理论传播了一种错觉，即在垄断资本主义条件下，存在另一种非兼并主义政策的可能性。在这方面，列宁强调：","language":"中文","translation":false},{"id":"hoxha-imperialism-2-158","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":158,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“关键在于考茨基把帝国主义的政治同它的经济割裂开了，把兼并解释为金融资本‘比较爱好的’政策，并且拿同一金融资本基础上的另一种似乎可能有的资产阶级政策和它对立。照这样说来，经济上的垄断是可以同政治上的非垄断、非暴力、非掠夺的行动方式相容的。照这样说来，瓜分世界领土（这种瓜分恰巧是在金融资本时代完成的并成了最大的资本主义国家现在互相竞争的特殊形式的基础）也是可以同非帝国主义的政策相容的。这样一来，就不是暴露资本主义最新阶段最根本的矛盾的深刻性，而是掩饰、缓和这些矛盾；这样一来，就不是马克思主义，而是资产阶级改良主义。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-159","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":159,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国的修正主义者忽视了垄断、金融资本在美国经济领域占主导地位的事实，也忽视了正是这些主宰着美国的内政和外交政策，他们谈论的是一种不再寻求扩张、实际上正在退却的和平帝国主义。“忘记”斯大林关于现代资本主义基本经济法的主要特征和要求的阐述：","language":"中文","translation":false},{"id":"hoxha-imperialism-2-160","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":160,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“……用剥削本国大多数居民并使他们破产和贫困的办法，用奴役和不断掠夺其他国家人民、特别是落后国家人民的办法，以及用旨在保证最高利润的战争和国民经济军事化的办法，来保证最大限度的资本主义利润。”（出自《苏联社会主义经济问题》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-161","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":161,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"因此，中国领导人的“新”理论表明，他们正在用新调子唱考茨基的老歌。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-162","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":162,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁在揭露想要对帝国主义列强在是否具有侵略性的基础上加以区分的第二国际的头目时，强调这一立场是反马克思主义的。这种态度迫使第二国际的各党派采取沙文主义的立场，公开背叛无产阶级和革命的事业。列宁说，在我们这个时代，卷入第一次世界大战的帝国主义国家无论是哪一方，都毫无疑问具有“更大的罪过”。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-163","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":163,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“现代民主派要保持其为民主派，”他说，“就只有不追随任何一个帝国主义资产阶级，只有说‘双方都同样坏’，只有希望每个国家的帝国主义资产阶级都失败。任何其他的决定，实际上都是民族自由主义的决定，同真正的国际观点毫无共同之点。”（出自《打着别人的旗帜》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-164","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":164,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"在目前的条件下,按照中国的论点，苏联的社会帝国主义比美国的帝国主义更具有侵略性，如果中国的论点被接受，这将导致对革命和对工人阶级的历史使命的公然背叛，从而走上第二国际的立场。这两个帝国主义超级大国同样代表着社会主义、人民自由独立和国家主权的主要敌人和危协。他们是世界资本主义的主要捍卫者。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-165","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":165,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"为了掩饰他们对人民的背叛，中国领导人表示，大垄断者与一些拥有巨额财富的国家之间的关系，造成了垄断者力量与人民之间甚至都能够避免冲突的局面。这是一个巨大的谬论,企图把残暴的帝国主义说成是温顺的，制造一种令人欢欣鼓舞的假象，即所谓的资本投资将为投资国人民创造福利，从而不再存在帝国主义者与这些国家人民之间的对立矛盾。现在被中国领导人鼓吹的这套理论,已经被帝国主义者捏造出来，目的是扩大它在世界各地的统治，并协助统治各国的反动集团压迫自己的人民，当卖国贼。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-166","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":166,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"这些“理论”以新的、改善了的形式重复了第二国际机会主义者的反动理论。第一次世界大战期间，列宁揭露了考茨基反马克思主义的超帝国主义论。考茨基声称，帝国主义可以通过各国资本家之间的协议来防止战争。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-167","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":167,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁在与考茨基的辩论中说：","language":"中文","translation":false},{"id":"hoxha-imperialism-2-168","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":168,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"“……资本主义现实中的（而不是英国牧师或德国‘马克思主义者’考茨基的庸俗的小市民幻想中的）‘国际帝国主义的’或‘超帝国主义的’联盟，不管形式如何，不管是一个帝国主义联盟去反对另一个帝国主义联盟，还是所有帝国主义大国结成一个总联盟，都不可避免地只会是两次战争之间的‘喘息’。”（出自《帝国主义是资本主义的最高阶段》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-2-169","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":169,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁的这些教导在当前中国修正主义者正在谈论和狂热地努力去建立一切法西斯主义和封建主义、资本主义和帝国主义国家和政权的一个联盟和一个巨大的世界统一战线，包括美国，来反对苏联社会帝国主义的时候，十分具有意义。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-170","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":170,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"列宁强调，帝国主义国家之间的联盟是可能的，但建立帝国主义国家联盟的唯一目的是共同粉碎革命和社会主义，共同掠夺殖民地和半殖民地国家。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-171","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":171,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中国的修正主义者，像第二国际修正主义者一样，把《共产党宣言》的口号“全世界无产者，联合起来!”，换成了反对苏联社会帝国主义的务实口号“团结一切可以团结的力量”。中国领导人提出的“三个世界”理论，没有从马列主义的阶级立场来分析帝国主义的历史发展，而是以一种扭曲的眼光来看待帝国主义，忽视了马克思列宁明确界定的当代矛盾。按照这个“理论”，“社会主义”中国同美帝和第二世界是统一的。也就是说，同其他帝国主义剥削人民，却又号召立志反对无论是美帝还是苏联社会帝国主义的世界帝国主义和资本主义的“第三世界”的人民团结起来，只反对苏联社会帝国主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-172","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":172,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"铁托的不结盟理论，也和“三个世界”理论一样反马克思主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-173","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":173,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"这两种“理论”是美苏两国帝国主义的火车所行驶的同一条铁路上的铁轨，这一列火车满载着从世界各国人民掠夺来的财富。铁托分子和中国修正主义者正试图在帝国主义和社会帝国主义的这列火车的货运车上开一些洞，这样一些石油、糖、几美元、几英镑、法郎或卢布就会漏出来。这两条横亘在被压迫人民背上的铁轨，是要把被压迫人民永远束缚起来的，这是两种和其他一切反马克思主义理论诸如托派的理论、无政府主义者的理论、布哈林主义者的理论、赫鲁晓夫主义者的理论以及陶里亚蒂[6]、卡里略[7]、马歇[8]的支持者推崇的理论等理论一样反动的理论。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-174","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":174,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"现实不断地证实列宁关于帝国主义天才的论断。资本主义已进入衰亡阶段。这种情况引起了人民的反抗，推动他们进行革命。人民反对帝国主义和资产阶级资本主义集团的斗争，正在以各种形式、不同程度地进行着。量变将不可避免地转变为质变。这将首先发生在那些处在资本主义链条上最薄弱环节的国家，在这些国家，工人阶级的意识和组织能力已达到很高的水平，对这一问题有深刻的政治和思想认识。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-175","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":175,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"帝国主义加强了对人民的野蛮镇压和剥削。但是，与此同时，世界各国人民越来越意识到，他们不能继续生活在资本主义社会中，资本主义社会工人阶级战后受到的压迫和剥削并不比战前少。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-176","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":176,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"尽管帝国主义及其走狗作了种种努力，但在建立对人民的霸权的斗争中，无论现在还是将来，都不会找到稳定的局面。由于要求解放的工人阶级和被压迫劳动人民群众意识在觉醒，以及帝国主义内部不可避免的矛盾，它不会找到稳定。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-177","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":177,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"人民看到,并且将会看得越来越清楚,世界帝国主义和资本主义并不仅仅基于两个超级大国的经济、军事、政治和意识形态力量，还建立在富人阶级的基础上，他们使自己国家的人民处于奴役、剥削和恐惧之下，因此他们不会奋起获得真正的自由和独立。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-178","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":178,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"世界各国人民的广大群众也开始认识到，必须推翻今天的资产阶级资本主义社会和世界帝国主义的剥削制度。对各国人民来说，这不仅仅停留在纸上谈兵的阶段，在许多国家他们已经拿起武器。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-179","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":179,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"因此，没有必要把世界分为三、四部分，分为“结盟”和“不结盟”，必须按照马列主义的学说，正确看待与解释宏大的客观历史进程。世界被一分为二，一个是资本主义的世界，另一个是社会主义的新世界，两个世界进行残酷的斗争。在这场斗争中，新的社会主义世界将取得胜利，旧的资本主义社会、资产阶级和帝国主义社会将被推翻。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-180","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":180,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"[1] 译者注：经济互助委员会（The Council for Mutual Economic Assistance），于1949年成立，总部设在莫斯科，是由苏联组织建立的一个由社会主义国家组成的政治经济合作组织。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-181","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":181,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"[2] 译者注：马歇尔计划（The Marshall Plan），官方名称为欧洲复兴计划（European Recovery Program），是第二次世界大战结束后，美国为了遏制苏联阵营，对被战争破坏的西欧各国，进行经济援助、协助重建的计划。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-182","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":182,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"[3] 译者注：杰弗里·欧文（Geoffrey Owen），美国经济评论家，长期担任伦敦《金融时报》的管理人员。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-183","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":183,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"[4] 译者注：摩萨台(Mossadeq)1882——1967，1951年至1953年间出任民选的伊朗首相，但在1953年被美国中央情报局策动的政变推翻。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-184","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":184,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"中东局势主要是以色列与阿拉伯各国的冲突；","language":"中文","translation":false},{"id":"hoxha-imperialism-2-185","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":185,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"索马里与埃塞俄比亚冲突，指欧加登战争，是1977年到1978年期间，发生在埃塞俄比亚欧加登地区，埃塞俄比亚和索马里之间的战争；","language":"中文","translation":false},{"id":"hoxha-imperialism-2-186","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":186,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"柬埔寨越南战争，是发生于1975年5月1日到1991年10月23日期间的一场战争。交战双方分别是越南社会主义共和国和民主柬埔寨。1975年5月，红色高棉指挥的部队进入了富国岛，后被越南军队驱离。此后两国不断发生边境冲突。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-187","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":187,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"[6] 译者注：陶里亚蒂（(Palmiro Togliatti），1893—1964，意共创始人之一及长期领导人、第三国际的活动家，1925年离开法西斯意大利后主要负责第三国际工作，1944年回国直接领导意共游击队，并以反法西斯团结为名向天民党和社会党妥协。后提出“结构改革论”，成为欧共主义的理论基础之一。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-188","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":188,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"[7] 译者注：卡里略（Santago Carrillo），1915——2012，西共领导人，早年参加工人社会党，长期从事青年工作。1936年任统一社会主义青年团总书记，同年6月加入共产党。内战失败后，流亡苏联，1960年1月当选为总书记。1975年——1976年与卡洛斯国王通过中介秘密谈判达成交易，1977年帮助王国政府安抚群众，巩固了君主立宪制政府。后成为欧共主义理论家之一。","language":"中文","translation":false},{"id":"hoxha-imperialism-2-189","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第二章 列宁主义关于帝国主义的理论仍保持完整有效性","page":2,"paragraph":189,"url":"https://www.marxists.org/chinese/hoxha/1978/02-02.htm","text":"[8] 译者注：马歇（Georges Marchais），1920——1997，法共领导人，1943年投身抵抗运动，1947年加入法共，从事工会运动。1972年法共二十大上当选为总书记。同年与社会党的密特朗签署共同政府纲领，促成左翼力量的联合。他主张根据法国特点向社会主义过渡，建立民主的、发扬法国自由和人权传统的社会主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-1","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":1,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中文马克思主义文库 -> 恩维尔·霍查 -> 《帝国主义与革命》（1978）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-2","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":2,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"↘ 我们必须捍卫和贯彻马克思列宁主义的革命学说","language":"中文","translation":false},{"id":"hoxha-imperialism-3-3","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":3,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"↘ 民族解放斗争——世界革命的组成部分","language":"中文","translation":false},{"id":"hoxha-imperialism-3-4","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":4,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"↘ 真正的革命号召无产阶级和民族为新世界，社会主义世界而奋起","language":"中文","translation":false},{"id":"hoxha-imperialism-3-5","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":5,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马克思以科学论证展示了摧毁资本主义社会、建设一个更加先进的社会——社会主义社会，之后过渡到共产主义社会的必要性。 列宁在《帝国主义是资本主义的最高阶段》一书中发展了马克思的思想，指出现在是帝国主义时代和无产阶级革命的时代。这是摧毁旧资本主义、殖民主义和帝国主义秩序的新时代，是无产阶级夺取国家政权、被压迫人民解放的新时代，是世界范围上社会主义胜利的时代。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-6","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":6,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这意味着今天我们生活在一个旧的剥削社会被取代的时代，这个旧社会对大多数人来说，对被压迫和受剥削的人来说是不能容忍的，而在新社会里，人对人的剥削一劳永逸地消除了。正是从这些基本学说和以马列主义对当今世界发展进程的分析中，我们党在第七次全国代表大会上提出了世界正处在革命和人民解放问题亟待解决的发展阶段的论断。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-7","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":7,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"无产阶级反对资产阶级的斗争，是一种持续的、残酷的斗争。两大社会力量对峙着。一边是资本主义帝国主义式的资产阶级，这是有史以来最凶残、最诡诈、最嗜血的阶级。另一边是无产阶级，这个阶级完全没有生产资料，被同时又是思想、创造、工作、生产最先进的社会阶级——资产阶级残酷地压迫和剥削，但却无法享受到劳动果实。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-8","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":8,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"每一个阶级都努力团结自己身边的力量，为自己的目标准备着：无产阶级，为社会和民族解放，为革命作准备；资产阶级，为保持统治，为镇压革命作准备。资产阶级把最不祥的、倒退的、罪恶的力量聚集在自己周围，无产阶级则努力争取一切革命的、进步的力量都站在自己一边。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-9","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":9,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义教导我们，无产阶级和资产阶级的斗争会不断地逐渐增长起来，并必将以无产阶级及其同盟者的胜利告终。但要使这场斗争取得胜利，就必须组织无产阶级，必须让他们有自己的先锋队，必须使广大人民群众认识到革命的必要性，领导他们夺取国家政权，建立自己的专政，建设社会主义、共产主义、无阶级社会。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-10","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":10,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"世界上有许多意图或好或坏的、头脑发热的人，他们认为革命可以在任何时候、任何时候、任何地点进行。但这些人错了。革命不能按照自己的意愿，在任何时间、任何地点进行。革命是在最薄弱的资本主义链条上爆发和进行的。革命要爆发和胜利，必须有适当的客观条件和主观条件，必须找到发动革命的有利时机。最主要的是，广大人民群众在革命开始的时候，必须决心准备把革命进行到底。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-11","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":11,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁强调革命是由各国人民独立进行的，不是靠输出的。这并不意味着马列主义者无论在哪里作战，都不应该感到他们是团结一致的，不应该以无产阶级国际主义的最纯粹的感情互相联系，不应当帮助其他国家无产阶级和人民争取解放的斗争。相反，所有共产党人，所有无产阶级，所有各国的革命力量，都有义务通过宣传、鼓动、物质援助，以他们的决心和无私为榜样，并通过坚持马列主义，帮助每一个国家和世界各地的革命。当然，这种援助的成功，首先取决于无产阶级和无产阶级政党的准备，取决于这个或那个国家革命斗争的发展。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-12","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":12,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马克思恩格斯在《共产党宣言》中指出，一个国家的无产阶级和人民的利益同全世界无产阶级和人民的利益是分不开的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-13","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":13,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"正如列宁教导我们和生活所证实的那样，革命在每个国家都会分别取得胜利。因此，这种胜利，首先取决于各国工人阶级及其革命党能否在具体条件下把马克思、恩格斯、列宁、斯大林的教诲落实到革命上来。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-14","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":14,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是，围绕着这些学说，特别是围绕着列宁主义革命理论，产生了许多混乱，埋下了很多“地雷”。铁托分子、苏联修正主义者、“欧洲共产主义者”、中国修正主义者和其他现代修正主义者，他们自作主张，在革命问题上误导人民，防止革命爆发。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-15","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":15,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"今天，在问题出现，需要解决的时候，马列主义者有责任驱散修正主义者制造的关于革命的迷雾，揭露他们的阴谋和对革命的蓄意歪曲，揭露他们的反革命、沙文主义、霸权主义意图，并保证马列主义关于革命的教导得到正确的理解和运用。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-16","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":16,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"我们必须捍卫和贯彻马列主义的革命学说","language":"中文","translation":false},{"id":"hoxha-imperialism-3-17","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":17,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义教导我们，并且经一切革命的经验证明：革命要爆发并取得胜利，必须要存在客观因素和主观因素。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-18","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":18,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁在他的《第二国际的破产》一书中阐述了这一学说，并在他的《共产主义运动中的“左派”幼稚病》一书和其他著作中对其进一步发展。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-19","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":19,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁把革命条件作为革命的客观因素，描述如下：","language":"中文","translation":false},{"id":"hoxha-imperialism-3-20","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":20,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"(1)统治阶级已经不可能照旧不变地维持自己的统治；‘上层’的这种或那种危机，统治阶级在政治上的危机，给被压迫阶级不满和愤慨的迸发造成突破口。要使革命到来，单是“下层不愿”照旧生活下去通常是不够的，还需要“上层不能”照旧生活下去。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-21","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":21,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"(2)被压迫阶级的贫困和苦难超乎寻常地加剧。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-22","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":22,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"(3)由于上述原因，群众积极性大大提高，这些群众在“和平”时期忍气吞声地受人掠夺，而在风暴时期，无论整个危机的环境，还是“上层”本身，都促使他们投身于独立的历史性行动。（出自《第二国际的破产》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-23","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":23,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是，并不是每一种革命情况都会引起革命，列宁说。他说，在许多情况下，像德国1860-1870年的革命条件，或俄国1859-1861年和1879-1880年的革命条件，都没有转变成革命，因为没有主观因素，即群众对革命的高觉悟和高准备程度。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-24","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":24,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“……革命阶级，”正如列宁所说，“能够发动足以摧毁（或打垮）旧政府的强大的革命群众行动，因为这种旧政府，如果不去‘推’它，即使在危机时代也决不会‘倒’的。”（出自《第二国际的破产》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-25","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":25,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在主观因素的准备上，正如列宁在早期著作中所写的那样，工人阶级革命党以及它对革命群众的领导、教育和动员起着决定性的作用。党要做到这一点：既要根据具体情况和人民群众的革命愿望和要求，制定正确的政治路线，又要通过大量的工作，包括集中进行深入的、在政治上深思熟虑过的革命活动，使无产阶级和劳动群众认识到自己的生活状况，认识到压迫和剥削，认识到资产阶级的野蛮法律，认识到革命作为推翻奴役秩序的手段之绝对必要性。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-26","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":26,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这样，贫困阶层就会非常激烈地反应，即使是富人，掌权的资产阶级，也会受到其他内外矛盾的动摇，也很难像以前那样继续支配。当这些条件得到满足，当客观因素和主观因素相互联系时，革命就不仅有可能爆发，而且有可能胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-27","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":27,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命者们总是对列宁的这些天才论断进行深入的思考，并且不仅动脑筋思考，还对条件进行了具体而全面的分析。他们的行动，是要保证他们永远不会被革命条件所惊扰，所以他们不会在决定性关头才发觉自己被缴了械，反而能够利用这些来准备和发动革命。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-28","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":28,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"对时局的分析能表明出什么？阿尔巴尼亚劳动党从列宁主义革命理论出发，认为当今世界形势总体上是革命的，许多国家的条件已经成熟，或者正在迅速成熟，而在其他国家，这一进程正在发展中。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-29","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":29,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"当我们说当前的局势是革命性的，我们意思是今天的世界正在走向大爆发。总的来说，现在的局势就像一座正在喷发的火山，一场猛烈的大火，一场在进行着压迫和剥削的上层统治者阶级中燃烧的大火。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-30","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":30,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"资本主义和修正主义世界正处于严重的经济和政治、金融和军事、思想和道德危机之中。当前的危机，动摇了资产阶级和修正主义秩序的整个结构和上层建筑，使资本主义制度的普遍危机更加深刻和尖锐。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-31","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":31,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这场危机的后果显然是非常严重和毁灭性的，特别是在经济领域。自1974年以来，第二次世界大战后最严重的经济危机变得不断恶化起来。它使工业生产下降了相当大的比例：日本下降了20%，英国下降了15%，美国下降了14%，法国和意大利下降了18%，德意志联邦共和国下降了10%。这场危机造成了十分严重的萧条。在许多资本主义国家，一些重要经济部门的闲置生产能力率已高达25%-40%，这种情况已持续多年。这就是为什么工业生产仍停滞不前。大量剩余货物仍无法售出。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-32","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":32,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"然而，尽管所有这些未售出商品仍处于存库状态，尽管许多生产力没有被发挥，但由于价格上涨，垄断企业的利润继续增加。物价每天都在上涨，而某些国家的通货膨胀率已经达到很高的水平。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-33","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":33,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"物价上涨，特别是通货膨胀，已经成为垄断企业和资本主义、修正主义国家手中的一种非常方便的手段，使工人阶级和其他劳动者承担起危机的沉重负担。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-34","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":34,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"以通货膨胀为借口，资本主义和资产阶级主导的修正主义国家增加劳动人民的所得税，停发工资，同时减少垄断者的利润税，使货币贬值，等等。这些措施是针对工人阶级和全体劳动者的。提高他们的被剥削的程度，降低他们的生活水平。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-35","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":35,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"旷日持久的经济危机恶化了工人阶级和农民群众的生存条件，使他们的生活更加艰难。失业率已经上升到以前很少见到的比例，而且已经成为资产阶级和修正主义社会的一大长期性溃疡。在资本主义修正主义世界里，有1.1亿人被抛弃在街头。仅在美国，失业人数就不少于700万至800万。今天，数以亿计的人生活在饥饿的边缘或者实际上就在挨饿中。亿万人因对明天的恐慌而饱受折磨。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-36","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":36,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"广大劳动人民的贫困与无保障，以及资本主义和资本主义式的修正主义政权实行的反动的、反人民的内外政策，使广大人民的不满情绪增加起来并不断增加。这种恶劣的情况激起了他们无法遏制的愤怒，这在罢工、抗议、示威、与资本主义和修正主义秩序的压迫者的冲突中以及许多事例——甚至是在真正的起义中表现出来。民众对统治他们的政权越来越怀有敌意。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-37","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":37,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在帝国主义、资本主义和修正主义国家，为了努力维护他们的利益最大化，在这种危急的情况下，帝国主义、资本主义和修正主义国家会做出种种虚假的承诺和提议，以安抚群众的不满和愤怒，使他们不想革命。与此同时，穷人越来越穷，富人越来越富，贫富差距越来越大，社会阶层差距越来越大，发达资本主义国家和不发达国家之间的差距越来越大。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-38","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":38,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"当前的危机还蔓延到政治生活，挑起了资本主义国家和修正主义国家统治集团的矛盾。这方面的明显证据是，政府危机大幅增加，执政者频繁更替。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-39","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":39,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"资产阶级和统治集团被迫越来越频繁地更换政府班子的走卒，以欺骗劳动人民，使他们相信，新的班子比旧的班子好，使他们确信，这场危机引发的责任以及无法摆脱危机的责任在于旧的班子，而新班子会改善情况，等等。整个骗局一直在大范围地进行，特别是在竞选活动中，被关于自由、民主等虚假口号所掩盖。同时，资本主义和修正主义国家的资产阶级正在强化其野蛮的暴力武器、军队、警察、特务、法院，以及对无产阶级的一切运动和努力采取专政手段的控制。今天，在资本主义和修正主义国家，资产阶级的暴力和限制民主权利的趋势越来越明显。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-40","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":40,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在资产阶级认为不能用“民主”的方法和手段来统治的时候，法西斯在国家生活中的发展和建立法西斯的准备的趋势越来越明显。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-41","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":41,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"经济金融和政治危机不仅笼罩着垄断企业、政府、政党和各国内部的实力，而且还笼罩着国际联盟、经济、政治和军事集团，如欧洲共同市场、经互会、欧洲共同体、北约和华约。这些联盟和集团的伙伴之间的矛盾、摩擦、竞争和争吵，越来越公开和粗暴地表现出来。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-42","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":42,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"超级大国和帝国主义列强的军备竞赛和全面备战，以及在中东、非洲之角、西撒哈拉、印度支那等地挑起局部战争，可以看作这场危机和他们摆脱危机企图的另一种表现。这种行动方向是为一个或另一个帝国主义国家的霸权主义和扩张主义计划服务的，它维持并发展了今天所占比例空前的军事工业和军火贸易。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-43","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":43,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是，所有这些政治和军事手段都只是治标不治本，它不能也不可能治愈资本主义修正主义制度的严重弊病。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-44","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":44,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"说到当今资本主义和修正主义世界的经济和政治危机，还必须加上前所未有的思想道德危机。在历史上任何一个时候都没有今天这样的思想混乱和道德败坏。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-45","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":45,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"历史上任何时候都没有今天这样变种千变万化的资产阶级理论，包装在各种世俗和宗教下的右派的、中间派的或“左派”的、古典的和现代的、公开反共的和标榜自己是共产主义和马克思主义的。在其他任何时候，都没有出现过这样的道德败坏，这样堕落的生活方式，或是这样巨大的精神压抑。资产阶级和修正主义的理论，费了很大劲建立起来，并被吹嘘为将人民从旧社会的罪恶中拯救出来的指南，例如：“资本主义最终稳定论”、“人民资本主义”、“消费型社会”、“后工业社会”、“防范危机”、“技术革命”、“和平共处”、“没有军队、武器和战争的世界”、“带有人性面孔的社会主义”[1]等等，现在基础都被动摇了。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-46","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":46,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"总危机的方方面面，不仅在南斯拉夫——危机的后果更为明显的国家，而且在社会帝国主义的苏联和其他修正主义国家，都可以看到。这些国家到处都在加紧压迫和剥削，都在遭受资本主义的弊病，都在遭受领导人和上层集团因权力和特殊利益而引起的争吵和冲突；到处都是人民群众的不满和愤怒。因此，这些国家也存在着革命的巨大可能性。革命的规律在那里和在其他资本主义国家里是一样的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-47","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":47,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"正是这种资本主义大危机的形势，正是这种趋势的不断加深，使我们得出这样的结论：革命形势已经包围或者正在包围大多数资本主义国家和修正主义国家，因此，革命将成为常态。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-48","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":48,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"资产阶级和修正主义者在危机的压力越来越大的情况下，在他们对革命会失败的预言和扼杀革命的伎俩所遭受的落空和挫败中，他们正在企图寻找新的权宜之计，编造其他的欺骗性理论。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-49","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":49,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"今天，现代修正主义者高举看保卫资本主义制度、压迫和剥削人民、分裂革命和解放运动——总体上讲，欺骗群众的旗帜。但是，他们也会和过去的社会民主主义者和一切机会主义者一样，遭受同样的命运——变成资产阶级纯粹的狗腿子。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-50","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":50,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在当前严重的经济、政治、思想危机的形势下，资产阶级要求修正主义奴才更加公开地出来支持它。这迫使他们越来越多地脱下伪装，同时也变得越来越不可信。列宁说：","language":"中文","translation":false},{"id":"hoxha-imperialism-3-51","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":51,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“机会主义者是反对无产阶级革命的资产阶级分子。这些人在和平时期呆在工人政党内部，偷偷做着资产阶级的工作，而在危机时期，立刻就成为联合一致的整个资产阶级的(从保守的到最激进的和民主--的，从自由主义的到宗教的和僧侣的)公开同盟者。”（出自《以后怎么办?》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-52","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":52,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁的这一科学论断，在现代修正主义者为今天危机四伏的资本主义制度所做的贡献中得到了充分的证明。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-53","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":53,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"以意大利，一个典型的反映资本主义在其基础和上层建筑中衰败的国家为例。从第二次世界大战结束到现在，基督教民主派、大资产阶级政党、教会聚集了一切宗教反动资产阶级和右翼分子在意大利执政。他们的政府正在统治一个处于破产状态的国家。从1945年至今，资产阶级上层一直处于一场严重的危机之中，在这一时期内，先后有40个左右的政府，如“单色”天主教民主党政府、“双色”天主教民主党-社会党联合政府、“三色”天主教民主党-社会党-民社党联合政府[2]、“中左翼”政府、“中右翼”政府等。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-54","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":54,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"意大利深刻的政府危机反映了国内普遍处于危机的局面，且从中找不到出路。争吵、冲突、政治谋杀和丑闻越来越频繁，如罢免利昂纳总统[3]、杀害天主教民主党党首莫罗等[4]，都是危机的后果。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-55","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":55,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"意大利已成为美国的桥头堡。其破产的经济已落入美帝的魔掌，也与欧洲经济共同体联系在一起，而它是欧洲经济共同体分量最轻的成员。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-56","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":56,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"由于这种情况，意大利广大劳动群众变得一贫如洗，而且在加剧。意大利是欧洲共同体国家中失业率最高的国家。意大利是劳动力输出最多的国家，经济的进口要远远大于出口。欧洲经济共同体成员国，特别是西德和法国，通过限制从意大利购买食品，造成了意大利农业的困境。意大利黄油、牛奶和水果的出口价格急剧下降，而该国的生活成本却变得极高。意大利已经成为一个大罢工的国家，从重、轻工业到运输业，从邮递员到航空公司职员，甚至警察都参加了罢工。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-57","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":57,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在这种人民强烈不满的情况下，当群众和革命的利益要求将无产阶级和全体人民的这种巨大不满，转化为反对反动资产阶级和它准备发动的法西斯式进攻的斗争中去时，意大利的修正主义者和改良派工会、全体工人贵族、以及中国“三个世界”理论的支持者，都在充当救火队员，扑灭革命的火焰，维护资产阶级统治秩序。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-58","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":58,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"从法西斯党到贝林格[5]的修正主义政党，所有政党都在捍卫这个腐朽的资产阶级秩序。意大利修正主义党与资产阶级联合，正是为了保持这已经被动摇根基的资产阶级秩序继续掌握着权力。它试图通过传播它正在拥护和应用适用于本国国情的马克思主义的谎言，来削弱和压制意大利无产阶级的革命动力。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-59","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":59,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"贝林格不仅早就与天主教民主党进行了谈判，甚至还与他们达成了协议，事实上，在没有正式参与政府的幌子下，在许多问题上，他是与他们一起统治的。意大利修正主义者对由意大利议会多数的五个政党达成的政府计划大肆鼓吹，他们认为这是一个“重要的胜利”，是意大利的“新政治阶段”。但贝林格所说的这个政治阶段，是将修正主义政党纳入意大利资本的计划中去。贝林格将此描述为一个严肃、现实和不可忽视的协议。他声称，这项协议不仅在政党之间的政治关系中，而且在国家的整个、经济、社会和国家生活中将带来真正的变化。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-60","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":60,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，意大利修正主义者走的正是列宁为不同的机会主义者所预言的道路，他们寻求与资本联盟，以阻挠群众的革命运动。有了这样的联合，他们认为自己已经走上了通过多元主义走向社会主义的道路。显然，这不过是一场梦，意大利参议院院长阿明托雷·范范尼[6]把五个政党之间的这项协议描述为一个梦，一点也不错。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-61","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":61,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这是意大利修正主义者的一个梦想，而资本力量那边这样做绝不是因为做梦，而是一个深思熟虑后的行动，目的是要清算意大利的共产主义思想，阻挠意大利人民和无产阶级的主张，镇压他们为建设新社会而进行的革命斗争。意大利修正主义者现在得到了一些面包屑作为施舍，但是，他们却还声称政府需要修正主义政党的参与，他们试图把这个政党完全带入政府，就像一条鱼进入鱼群一样。总之，意大利修正主义政党正试图完全卷入意大利垄断资本的反动混乱之中。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-62","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":62,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"贝林格的党在意识形态上是一个彻底堕落的政党，带着一个完全的改良主义、议会路线、社民式纲领。它支持伪民主宪法建立的秩序——这个伪民主宪法本身就是由陶里亚蒂领导的意大利“共产主义者”也参与制定的。正是在这部宪法之下，反动资产阶级和神职人员在过去30年制定意大利的法律， 压迫无产阶级和广大人民群众。所谓的意大利共产主义者却认为这种压迫是公正的，符合宪法。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-63","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":63,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"不论在议会内还是议会外，意大利修正主义党和资产阶级其他政党，以天主教民主党为首，通过新闻机关、电视台和广播电台，实行着一种肆无忌惮地蛊惑意大利民众的政策，以削弱无产阶级的革命意志和劳动群众的政治觉悟，使其日益混乱、瓦解。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-64","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":64,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"意大利的反动派和教会非常需要所有这些活动。意大利修正主义党试图压制无产阶级领导的人民群众革命运动，以阻止革命，帮助资产阶级走出困境，避免现存秩序被推翻。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-65","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":65,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"再举一个例子，西班牙。佛朗哥死后，胡安·卡洛斯国王[7]掌权。他是西班牙大资产阶级的代表，西班牙大资产阶级看到法西斯政权在长期统治期间使国家陷入严重危机，得出了西班牙不能再像佛朗哥时代那样被统治的结论。因此，必须在政府形式上作出某些改变，佛朗哥声名狼藉的长枪党不能再继续掌权。经过一系列的政府首脑更迭，新国王最信任的人，改良的佛朗哥主义延续者，掌权了。西班牙爆发了前所未有的示威和罢工。通过它们，人们要求改变，自然不是已发生的这种“改变”，而是深刻和彻底的改变。那里的罢工、示威和冲突没有停止，仍在继续。人民群众要求自由和权利，要求不同民族的自治。在这种情况下，为了将群众起义带入歧途，胡安·卡洛斯政府还将伊巴露丽[8]—卡里略(Ibarruri—Carrillo)的修正主义政党合法化。这个政党的首脑已经变成了西班牙君主政体的顺从的奴仆，变成了工贼，阻止了在现有形势下建立起来的革命大潮，并与资产阶级联合起来，镇压一切具有西班牙战争革命思想的分子和西班牙共和国的仰慕者。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-66","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":66,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在这里，我们也看到西班牙修正主义政党的救火队角色，与意大利修正主义政党扮演的角色相同，尽管它的力量比后者要小。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-67","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":67,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"法国、日本、美国、英国、葡萄牙等资本主义国家的修正主义政党，在维护资产阶级秩序方面，也起着类似的作用，使资产阶级秩序能够克服危机和革命的局面，使无产阶级和其他受压迫和剥削的群众陷于混乱和瘫痪中，使他们越来越清楚地认识到，生活在“消费社会”和其他剥削社会是不可能的，他们正在上升到对资本主义的政治和经济秩序的反抗中。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-68","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":68,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"修正主义政党极为敌视列宁主义，这意味着他们对革命持敌对态度，因为正是列宁把无产阶级革命的理论阐述得淋漓尽致，并在俄国付诸实践。在这一理论的基础上，社会主义革命在阿尔巴尼亚等国取得了胜利。列宁主义理论处处昭示着革命胜利的道路，揭示了反革命修正主义关于通过议会道路和平过渡到社会主义的理论是没有价值的，他们并没有没有摧毁资产阶级国家机器，事实上，根据他们的说法，甚至是和平过渡，也不需要无产阶级及其先锋队的领导，不需要无产阶级的专政。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-69","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":69,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"正是在这样一个非常革命的时刻，在资本主义链条最薄弱的环节，在极有可能爆发革命的时候，在极有必要提高无产阶级的阶级觉悟、准备主观因素、树立指明了无产阶级和其他被压迫群众夺取国家权力的真正道路的马列主义理论之正确性和普遍性的时候，资产阶级在对付和避免革命的过程中，修正主义起到了不可估量的作用。这就是为什么资产阶级千方百计地争取受其影响的修正主义政党和工会参加反对革命和共产主义的斗争。这正是美帝、世界资本主义和各国资产阶级的全部路线所要达到的目的。资产阶级希望修正主义政党公开地、完全地为资本服务，带着“共产主义”的色彩来运作，宣称自己为了改变现状而斗争，以建立一个新的混合社会，在这个社会里，不仅有统治阶级和富裕阶级，而且据说还有较贫穷的阶级，都将有自己的发言权，由修正主义的“共产党”和社会党冒充自己的代表和拥护者。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-70","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":70,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"当权的修正主义者，特别是南斯拉夫的修正主义者、苏联的修正主义者和中国的修正主义者，正在世界资本主义遏制和消灭革命的斗争中发挥着巨大的作用。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-71","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":71,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"南斯拉夫修正主义者被宣布为列宁主义的敌人。他们是否定十月革命所体现的、列宁主义革命理论所反映的社会主义革命规律普遍性的最热烈的鼓吹者。他们鼓吹说，今天的世界是自发地走向社会主义的，所以不需要革命，不需要阶级斗争等。南斯拉夫修正主义者把他们的资本主义式“自治”制度作为真正社会主义的典范，声称它是对付“斯大林主义”的“罪恶”和对付资本主义罪恶的灵丹妙药。他们认为，这一制度的建立，不需要暴力革命，不需要无产阶级专政，不需要社会主义国家所有制，不需要民主集中制。“自治”可以通过各级统治圈子之间、雇主和工人之间、政府和财产所有者之间的协议和合作悄悄地建立起来。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-72","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":72,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"正是因为南斯拉夫修正主义是列宁主义的敌人，破坏了革命，国际资本主义，特别是美帝才“慷慨”地向南斯拉夫提供了财政、物质、政治和意识形态上的援助。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-73","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":73,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"换言之，苏联修正主义者并不排斥列宁主义和列宁主义的革命理论，而是用反革命的立场和活动，在实践中同列宁主义和列宁主义的革命理论作斗争。他们对无产阶级革命的恐惧丝毫不亚于美帝和任何其他国家的资产阶级，因为在他们自己的国家，革命将他们从王位上推翻，剥夺他们的权力和阶级特权，而在其他国家，革命破坏了他们统治世界的战略计划。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-74","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":74,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"他们企图把自己描绘成十月革命的接班人，列宁主义的追随者，以欺骗苏联和其他国家的无产阶级和劳动群众。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-75","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":75,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"他们谈论“发达社会主义”[9]和“向共产主义过渡”，是为了把国内工人群众反对修正主义统治的任何不满、反抗和革命运动，作为“反革命”、“反社会主义”的行为加以镇压。在他们的国家之外，他们用“列宁主义”词句掩盖他们的反马列主义的理论和实践，为社会帝国主义的扩张和霸权计划打开了道路。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-76","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":76,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"苏联修正主义认为，当前发达资本主义国家的暴力革命是非常危险的，在他们看来，任何一次革命爆发，都可能演变成一场毁灭人类的热核世界大战。因此，他们建议在和平道路上革命，把议会“从资产阶级民主机关转变为劳动人民民主机关”作为今天最合适的道路。他们还提出“缓和”——所谓缓和紧张局势，宣称这是当今世界发展的大趋势，并将导致革命在世界范围内和平胜利——以此达到服务于苏联外交政策的目的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-77","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":77,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"为了蛊惑人心，他们并不否认无产阶级专政，实际上，在理论上，他们是出来为它辩护的，说在具体的情况下，甚至可以使用暴力革命。但是他们需要这些宣传，特别是为他们在一个国家或另一个国家组织的阴谋和武装政变——以便在那里建立亲苏的反动政权和集团，把民族解放运动从正确的道路上引开，并把他们置于霸权之下等等——来辩护。现在修正主义中国也变成一个狂热的革命灭火器。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-78","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":78,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国修正主义者整个内外政策都是针对革命的，因为革命打乱了他们使中国成为帝国主义超级大国的战略。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-79","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":79,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在中国，修正主义领导层正在野蛮地镇压工人阶级和其他劳动群众反对其资产阶级反革命立场和行动的任何革命爆发。它千方百计地掩盖当今时代的矛盾，特别是劳动和资本的矛盾，无产阶级和资产阶级的矛盾。中国修正主义者说，当今世界只有一个矛盾，就是两个超级大国之间的矛盾，他们把这个矛盾表现为美国连同世界上所有其他国家和苏联社会帝国主义之间的矛盾。他们根据这一杜撰的论断，号召各国无产阶级和人民同本国资产阶级团结起来，保卫祖国和民族独立，反对苏联社会帝国主义带来的危险。中国修正主义者以此向群众宣传放弃革命和解放斗争的思想。对中国修正主义者来说，无产阶级和民族解放革命问题根本不是现在的问题，也因为，在他们看来，世界上没有处在合适的革命时机中的地方。因此，他们建议无产阶级把自己关在图书馆里学习理论，因为革命行动的时机还没有到来。在这种情况下，中国修正主义的政策是多么的敌对和反革命，分裂马列主义运动，阻碍工人阶级在反对资本方面的统一。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-80","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":80,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国的媒体，以及中国领导人的讲话，完全没有提到大规模的示威和罢工——今天全体无产阶级都在不同的资本主义国家组织起来了。这是因为他们不想鼓动群众的反抗，是因为他们不想无产阶级利用这些时机同压迫和剥削作斗争。他们那“国家要独立，民族要解放，人民要革命”的虚张声势的口号，听起来多么虚伪！","language":"中文","translation":false},{"id":"hoxha-imperialism-3-81","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":81,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国修正主义的主张不仅仅是当今世界上革命形势不成熟的主张，相反，更是要求无产阶级与马列主义政党袖手旁观，不采取任何革命行动，不为革命做任何准备。很久以前，在共产国际第二次代表大会上，列宁就批评了意大利塞拉蒂的这种投降主义观点，他认为没有革命时机，就不应该采取革命行动。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-82","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":82,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁说：“社会党人不愿意象我们那样在任何形势下都进行工作，就是说不愿意进行革命工作，社会党人和共产党人的差别就在这里。”（出自《 关于加入共产国际的条件的发言》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-83","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":83,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁的这种批评，对于中国现代修正主义者和其他一切反对无产阶级和其他劳动群众的革命行动的修正主义者——比如社会民主主义者，也是一记沉重的耳光。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-84","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":84,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁称考茨基为叛徒，因为“……他完全歪曲了马克思的学说，把它篡改成了机会主义，‘口头上承认革命而实际上背弃革命’。”（出自《无产阶级革命和叛徒考茨基》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-85","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":85,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国修正主义领导人比考茨基走得更远。他们甚至不承认革命的必要性。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-86","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":86,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这一反动路线，深刻地说明了中国修正主义领导层的反革命政策和态度。中国修正主义领导层千方百计地同美帝和其他发达资本主义国家结成联盟，进行合作，并支持欧洲共同市场和北约。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-87","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":87,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"通过同美帝（美帝同苏联社会帝国主义一起，是无产阶级和人民最凶残的压迫者和剥削者，是他们的死敌——原注），其他帝国主义统治者和世界最黑暗的反动派结成联盟，谋求团结，并要求欧洲国家的无产阶级和其他发达资本主义国家的无产阶级弯腰屈从于资产阶级的压迫，中国修正主义者自己同时也参加了这种压迫，同世界资本主义世界联合起来，反对革命、反对社会主义、反对人民解放。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-88","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":88,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"可以看到，世界资本主义以现代修正主义和他们的一切工具，正在各方面展开激烈的、多方面的斗争，以阻止革命的爆发。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-89","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":89,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"他们正以强大而主要的力量克服危机，缓和或平息革命局势，以防止自己被拖入革命中。但是，危机和革命形势是客观存在的现象，不取决于资本家、修正主义者和其他任何人的意志和愿望。只有消灭了必然产生压迫剥削的资本主义秩序，才能避免这些现象。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-90","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":90,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"帝国主义者、其他资本家和修正主义者都知道，革命不是在危机和革命形势下自发爆发的。因此，他们将注意力和主要打击集中在主观因素上。一方面，他们努力愚弄和欺骗无产阶级、其他劳动群众和人民，使他们不会自觉地意识到革命的必要性，团结起来，组织起来；另一方面，他们为了消灭国际马列主义运动而斗争，阻止它的建立、发展和增强力量，使之不成为革命的强大政治领导力量，使真正的马列主义政党不能够获得团结、组织、动员、领导群众革命和取得革命胜利的政治和思想能力。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-91","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":91,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是，无论帝国主义者、资本家、修正主义者和反动派怎样挣扎，他们都不能阻止历史的车轮滚滚向前。他们的挣扎，是同无产阶级和热爱自由的人民的革命斗争和斗争相抗争的，而现代修正主义者，同过去的社会民主主义者和一切机会主义者，同资产阶级和帝国主义的一切走狗，会遭到同样的命运。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-92","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":92,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"民族解放斗争——世界革命的组成部分","language":"中文","translation":false},{"id":"hoxha-imperialism-3-93","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":93,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"我们讲革命，不只是指社会主义革命。在由革命从资本主义向社会主义过渡的当今时代，各国人民的解放斗争、民族民主革命、反帝革命、民族解放运动，也是列宁和斯大林所解释的世界无产阶级革命这一革命进程的组成部分。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-94","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":94,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"斯大林说：“列宁主义已经证明……民族问题只有和无产阶级革命相联系并在无产阶级革命的基础上 才能得到解决，西方革命必须同殖民地和附属国反帝解放运动结成革命的联盟才能取得胜利。民族问题是无产阶级革命总问题的一部分，是无产阶级专政问题的一部分”（出自《论列宁主义基础》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-95","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":95,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这种联系在今天变得更加清楚与自然，因为随着旧殖民制度的崩溃，大多数人民通过建立自己的民族国家，朝着独立迈出了一大步，而在这一步之后，他们又渴望走得更远。他们希望清算新殖民主义制度，消除对帝国主义的依赖和外国资本的剥削。他们想要完全的主权和经济政治独立。现在已经证明，这样的愿望是可以实现的，只有消除外国人任何统治和对外国的依赖，消除当地资产阶级和大地主统治者的压迫和剥削，才能实现这些目标。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-96","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":96,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，民族民主革命、反帝运动、民族解放运动同社会主义革命的联系和交织，是因为这些革命通过打击无产阶级和各国人民的共同敌人——帝国主义和反动派，也为社会的伟大变革铺平了道路，有助于社会主义革命的胜利。反之，通过打击帝国主义与资产阶级，破坏其经济和政治地位，社会主义革命为民族解放运动的胜利创造了有利条件。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-97","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":97,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"阿尔巴尼亚劳动党就是这样看待革命问题的。它是从马列主义立场看待的。这就是为什么它全力支持和协助热爱自由的人民反对帝国主义、苏联社会帝国主义和其他帝国主义列强，反对新殖民主义的正义斗争，因为这些斗争有助于破坏帝国主义的共同目标和资本主义制度，推动社会主义在世界范围内的胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-98","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":98,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，当我们得出革命是提上议事日程要去解决的问题的结论时，我们不仅要想到社会主义革命，而且要想到反帝的民主革命。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-99","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":99,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命形势的成熟程度，革命的性质和发展，不可能是所有国家都一样的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-100","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":100,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这取决于每个国家的具体历史条件、经济社会发展阶段、阶级比例、无产阶级和被压迫群众的情况和组织水平、外国势力对不同国家的干涉程度等，革命的具体问题很多，非常复杂。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-101","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":101,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"目前，关于非洲、亚洲、拉丁美洲的局势，以及那里革命的开展，人们议论纷纷。中国领导人把这些国家的革命、独立和民族解放问题放在全球的高度，好像可以通过整个“第三世界”的国家、阶级、政府等等的统一来解决，而忽略了个别国家和地区的具体情况和问题。这种形而上学的观点表明，中国领导人实际上反对非洲、亚洲、拉丁美洲人民的革命和解放，主张维持现状，维护帝国主义和新殖民主义在这些国家的统治。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-102","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":102,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"我们也要谈解放非洲、亚洲、拉丁美洲、阿拉伯和其他民族的问题。这些民族有许多共同的问题必须去解决，但每一个民族也有非常复杂的具体问题。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-103","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":103,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这些民族的总的共同任务，是消灭一切外国的枷锁、帝国主义、殖民主义、新殖民主义和地方资产阶级的压迫。非洲、拉丁美洲、亚洲和其他地方的这些民族对外国的枷锁，以及对当地资产阶级或地主资产阶级统治集团的枷锁充满愤怒和仇恨——他们投靠了美帝、苏联社会帝国主义者或其他帝国主义者”。这些民族现在已经觉醒，不能再容忍掠夺他们的财富、汗水和鲜血，也不能再适应他们的经济生活、社会生活和文化生活落后。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-104","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":104,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这些人民有许多共同的利益，也有许多共同的问题，在同美帝和苏联社会帝国主义作斗争，同革命和民族与社会解放的主要敌人作斗争，同资产阶级和反动派作斗争的基础上，必须团结起来。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-105","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":105,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"反对以色列——美帝最嗜血的工具——已经成为阿拉伯人民前进的一大绊脚石，这是所有阿拉伯人民的共同问题。然而，在实践中，并非所有的阿拉伯国家都对他们应该是否要共同对付以色列和这种对付共同敌人的斗争应该具有的性质持一种看法。他们中的一些人常常从狭隘的民族主义角度看待这场斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-106","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":106,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"我们不能同意这样的立场。我们坚持我们的立场，即以色列必须撤回自己的老巢，放弃对阿拉伯国家的沙文主义、挑衅、进攻和侵略态度与行动。我们要求以色列放弃阿拉伯人的领土，要求巴勒斯坦人获得他们所有的民族权利，但我们决不能接受以色列人民应该被消灭。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-107","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":107,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"阿拉伯各国人民为彻底摆脱帝国主义和社会帝国主义的束缚、为加强其自由和主权所作的努力，也是所有这些人民的共同问题。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-108","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":108,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是，每一个阿拉伯民族都有自己的特点，都有不同于其他民族的具体问题，这些问题产生于其社会经济发展、文化水平、国家组织、实现的自由和主权水平，以及其中许多民族宗族和部落的统一问题等。把所有这些不同的因素放在一起，要求所有这些国家必须以同样的方式同时解决自由、独立、民主和社会主义问题，这是不可能的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-109","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":109,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在那些资产阶级利益最大的阿拉伯国家，各帝国主义者投入了相当大的资金开发自然资产和剥削人民。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-110","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":110,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"为了实现这一目标，必须为殖民者和被殖民者创造某些工作条件。在自然资产最丰富、殖民者利益最大的地方，对人民和人民财富的剥削也更为密集。当然，资产的开发也带来了一定的发展，但这不能看作是一个国家经济的全面、协调发展。殖民者资助和帮助主要部落的首领，他们把自己的灵魂和人民的财富出卖给帝国主义占领者。作为回报，他们从殖民者的巨额利润中得到了一小部分。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-111","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":111,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"根据奴役他们的国家的情况和权力，有这些利润和外国赞助人的帮助下，部落首领在殖民地国家的支持和控制下建立了某种据称独立的国家。这样，在殖民者的帮助下，部落首领就变成了富有的资产阶级酋长阶层，他们把领土连同他们的人民一起卖了，一无所知地把人民置于外国殖民者和他们自己人的双重奴役之下。于是，大资产阶级、大地主、中世纪君王、奴隶、租界里的无产阶级，在阿拉伯国家就形成了，互相对峙。上层阶级利用外国剥削者给予他们的金钱和利润，接受了欧美资产阶级的生活方式。他们的儿子甚至上过殖民者的学校，在那里获得了一些西方文化。他们自诩为人民文化的代表，但事实上，他们受过训练，使劳动群众处于奴役之中，使殖民者继续对劳动群众进行残酷剥削。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-112","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":112,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"拥有更多财富的阿拉伯国家发展得更快，不那么富裕的阿拉伯国家发展得更慢，而贫穷的阿拉伯国家发展水平仍然很低。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-113","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":113,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"有一个适合于实行完全压迫的组织，也有武装力量在他们手中，这样，殖民主义，封建君主的国家政权和拥有大片土地的资产阶级，把任何反抗的企图，任何要求，甚至一些非常有限的经济权利，都消灭在萌芽状态，更不用说政治要求和革命了。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-114","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":114,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在当今阿拉伯国家的发展中，并不是所有的阿拉伯国家都面临着同样的问题。例如，沙特阿拉伯国王有着与波斯湾的埃米尔不同的问题，对经济、政治、组织和军事问题的看法也不同于他们——波斯湾的埃米尔从另一个角度和不同的范围看待这些问题。同样，伊拉克、叙利亚、埃及、利比亚、突尼斯、阿尔及利亚、摩洛哥、毛里塔尼亚等这些国家都从不同的角度看待自己的问题。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-115","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":115,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，当我们谈到阿拉伯各国人民时，我们得出的结论是，尽管他们有许多共同利益，但他们的问题并不完全相同，在一个国家不能像在另一个国家那样以同样的方式解决。同样，我们不能说在这些国家之间存在一个联盟和一个关于解决共同问题的单一意见。每个阿拉伯国家的问题都是不同的，这不仅是因为一个国家或另一个国家的政府立场不同，而且还因为殖民国家和新殖民国家的态度，这些国家仍然在大多数阿拉伯国家制定法律。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-116","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":116,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"关于阿拉伯各国人民的言论也适用于非洲大陆的人民。非洲是一个由具有古老文化的民族组成的多元体。每个非洲民族都有自己的文化、习俗和生活方式，由于众所周知的原因，这些文化、习俗和生活方式虽然有些不同，但都处于非常落后的阶段。大多数这些民族的觉醒只是最近才开始。在法律上，非洲各国人民普遍赢得了自由和独立。但是，真正的自由和独立是谈不上的，因为大多数国家仍然处于殖民地或新殖民地状态。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-117","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":117,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这些国家中有许多是由旧部落的首领统治的，他们夺取了权力，依赖于旧殖民主义者，或者是美帝和苏联社会帝国主义者。现阶段这些国家的施政方法除了存在着明显的殖民主义痕迹外，不是也不可能是其他状态。帝国主义者通过他们的康采恩再一次统治了大多数非洲国家，他们的资本投资于工业、银行等。这些国家的绝大多数财富继续流向大国。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-118","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":118,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"一些非洲国家曾为他们今天享有的自由和独立而战，而另一些国家则没有战斗就获得了自由和独立。英、法等殖民者在非洲殖民统治期间，压迫各国人民，但也创造了一个民族资产阶级，或多或少受到西方教育，这些国家今天的领导人，也是从这个资产阶级中产生的，其中有许多反帝分子，是争取本国独立的斗士，但大多数人不是忠于旧殖民者，以便在正式废除殖民主义之后与他们保持密切关系，就是对美帝、苏联社会帝国主义有经济和政治上的依赖。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-119","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":119,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"殖民者过去没有进行大规模投资。例如，在利比亚、突尼斯、埃及等国，情况就是这样。然而，殖民者榨干了所有这些国家的财富，夺取了大片土地，在一些特殊的工业部门，例如在原材料的提取和加工部门，发展了决不在少数的无产阶级。他们还把大量工人吸引到大国，例如法国，还有英国，作为在殖民者矿山和工厂工作的廉价劳动力。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-120","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":120,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在非洲其他地区，特别是在黑非洲，工业发展仍然比较落后。这个地区的所有国家都被瓜分了，特别是在法国、英国、比利时和葡萄牙手里。很久以前人们在那里发现了大量地下财富，如钻石、铁、铜、金、锡等，并在那里建立了开采和加工矿物的工业。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-121","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":121,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在许多非洲国家，殖民者建造了大型而典型的殖民者城市；过着令人难以置信的生活。现在，一方面，当地的大资产阶级及其财富在那里不断增长和发展，另一方面，广大劳动人民群众的贫困状况更加严重。这些国家在文化上取得了一定程度的发展，但更具有欧洲特色。当地文化还没有发展起来。它一般仍停留在部落所达到的阶段，在部落之外，在有高耸的摩天大楼的中心区没有被代表出来。这是因为，在殖民者生活着的大的中心区之外，赤裸裸的苦难和极端的贫困，饥饿，疾病，无知和对人民无情的剥削，在文化这个词的全部意义上，显得至高无上。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-122","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":122,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"由于殖民战争、野蛮的种族迫害和对非洲黑人贩卖，非洲人口在文化和经济上仍然不发达，数量不断减少，这些黑人被送到欧洲大都市、美国和其他国家，像动物一样在棉花种植园和其他农场工作，以及做着工业和建筑业最重的工作。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-123","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":123,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"由于这些原因，非洲人民面前仍有一场很大的斗争。这是一场非常复杂的斗争，由于各国的经济、文化和教育发展状况、政治觉悟程度、不同信仰的巨大影响如基督教和穆斯林、异教徒思想等不同宗教以及旧的异教徒信仰等对人民群众施加着压力，各国的斗争将是不同的。由于许多国家实际上处于新殖民主义和民族资产阶级集团的联合统治之下，这场斗争变得更加困难。那里的法律是由那些强大的资本主义-帝国主义国家制定的，这些国家对统治集团进行补贴或控制，当新殖民主义者的利益需要或当这些利益的平衡受到破坏时，他们就建立或废除这些集团。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-124","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":124,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"大地主、反动资产阶级、帝国主义者和新殖民主义者所奉行的政策，是要使非洲人民长期处于愚昧和束缚之中，阻碍他们的社会、政治和思想发展，阻碍他们争取这些权利的斗争。现在我们看到，那些过去统治这些人民的帝国主义者，以及其他新帝国主义者，正试图通过干涉人民内部事务的各种可能方式，来渗透入非洲大陆。因此，帝国主义者之间、大多数国家的人民和帝国主义的资产阶级领导人之间、人民和新殖民者之间的矛盾日趋严重。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-125","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":125,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"人民必须利用这些矛盾，既要深化矛盾，又要从中受益。但是，只有无产阶级、贫苦农民、一切被压迫者和奴隶联合起来，反对帝国主义和新殖民主义、反对大民族资产阶级、大地主及其整个制度的坚决斗争，才能达到这个目的。在这场斗争中，那些渴望看到自己的国家在发展道路上自由独立前进的进步人士和民主人士、革命青年和爱国知识分子将承担一种特殊的角色。只有通过他们不断地、有组织地斗争，才能使国内外压迫者、剥削者和政府的日子变得困难。这种情况将根据每个非洲国家的具体情况而准备好。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-126","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":126,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"英美帝没有给非洲人民任何自由。例如，每个人都能看到南非正在发生的事情。白人种族主义者，英国资本家，剥削者，在那里统治着，野蛮地压迫着这个弱肉强食的国家的有色人种。非洲的许多其他国家被美国、英国、法国、比利时和其他旧殖民主义者和帝国主义者的康采恩和资本所支配，这些国家的实力有所减弱，但他们仍然掌握着这些国家经济的钥匙。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-127","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":127,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"亚洲各国人民也走过了一条充满苦难和艰辛、残酷的受帝国主义压迫和剥削的道路。在第二次世界大战前夕，这个大陆（除了苏联亚洲部分以外）人口的十分之九处于欧洲、日本和美帝国主义列强的殖民和半殖民压迫与剥削的状态。仅英国一个国家，其殖民地就达563.5万平方公里，居住者4.2亿多人。对亚洲绝大多数国家的殖民压迫剥削使它们处于明显的社会经济文化落后和赤贫状态。它们只是帝国主义大都市石油、煤炭、铬、锰、镁、锡、橡胶等原材料的来源。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-128","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":128,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"战后，亚洲的殖民秩序也被打破了。殖民地国家建立了独立的民族国家。这些国家大多是通过人民群众对殖民主义者和日本侵略者发动的血腥战争取得建国的胜利的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-129","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":129,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国人民的解放战争，使中国从日本帝国主义统治下解放出来，使蒋介石反动势力溃败，民主革命取得了胜利，这对于亚洲殖民主义的崩溃具有特别重要的意义。有一段时间，在中国这样一个大国的胜利，对亚洲人民和受帝国主义列强统治或依靠帝国主义列强的其他国家的人民的解放斗争，产生了广泛的影响。但由于建国后中国领导人的路线，这种影响逐渐减弱。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-130","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":130,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国领导人宣布中国已经走上了社会主义发展道路。世界革命者和热爱自由的人民希望并期待中国成为社会主义和世界革命的强大堡垒，他们热烈欢迎这一宣言。但他们的愿景和希望没有实现。虽然人们很难相信，但中国的现实和其十分混乱的局面表明，中国没有走社会主义道路。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-131","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":131,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"与此同时，亚洲人民的斗争并没有随着殖民主义的破坏而结束。英国、法国、荷兰和其他殖民主义者虽然被迫承认前殖民地国家的独立，但他们希望保留在这些国家的经济和政治地位，以便继续以其他的，新殖民主义的形式进行统治和剥削。美国渗透到亚洲，特别是远东、东南亚和太平洋诸岛，使局势变得非常严重。这一地区对美帝的经济和军事战略意义重大。它建立了大型军事基地，并在那里部署了强大的舰队。与此同时，美国资本也牢牢地将该地区各国的经济拖入了血迹斑斑的魔爪。与此同时，美帝为镇压亚洲国家的民族解放运动，进行了大规模的军事行动、分裂活动和间谍活动。他们成功地把朝鲜和越南一分为二[10]，在这两个国家的南部建立了反动的傀儡政权。亚洲许多前殖民地和半殖民地国家建立了亲帝国主义的地主资产阶级政权。这样，中世纪的奴隶制，王公、国王、酋长、武士和现代化的资本主义绅士的野蛮统治就保存在那里。这些政权又把自己的国家卖给帝国主义，特别是卖给美帝，极大地阻碍了这些国家的社会经济和文化发展。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-132","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":132,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在这种情况下，在帝国主义和地主资产阶级的沉重枷锁下又一次苦不堪言的亚洲人民，不能放下武器，必须继续争取解放以摆脱这种枷锁。总的来说，这场斗争是由共产党领导的。无论这些党在哪里成功地同群众建立了良好的联系，使之认识到战争的解放目标，动员和组织他们进行革命武装斗争，它们都取得了积极的成果。印度支那人民，特别是越南人民，战胜美帝及其地主资产阶级傀儡的历史性胜利，向全世界表明，人民和无论大小的国家，当他们决心为自由和独立作出任何牺牲，无私斗争到底时，帝国主义，即使是像美国这样的超级大国，有着强大的经济和军事潜力，有着一切现代战争手段来镇压解放运动，也不能征服他们。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-133","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":133,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"解放武装斗争已经展开，而且仍在亚洲许多其他国家进行，如缅甸、马来西亚、菲律宾、印度尼西亚和其他地方。如果不是因为中国的反马克思主义的、沙文主义的立场和干涉，导致了革命力量和共产党领导的力量分裂和丧失，这些斗争一定会取得更大的成功和胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-134","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":134,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"一方面，中国领导人宣布支持这些国家的解放战争，另一方面，他们又支持反动政权，以赞歌和数不清的荣誉欢迎和款待这些政权的头子。他们一贯奉行把亚洲国家的解放运动服从于自己的务实政策和霸权利益的战略和手段。他们总是给革命力量和革命领导人施加压力，要把这个政策强加于他们。他们从来没有真正关心亚洲各国人民解放和革命的问题，只关心实现沙文主义的野心。他们没有帮助这些人民，反而阻碍了他们。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-135","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":135,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"亚洲的革命和解放斗争问题，从来没有像现在这样那么有力、那么迫切地要求解决，从来没有比现在更复杂、更难解决。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-136","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":136,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这种复杂化和这些困难主要来自美帝的目的和活动，也来自苏联和中国的修正主义者、社会帝国主义者的反马克思主义、反大众、霸权主义和扩张主义的目的和活动。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-137","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":137,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"美国认为亚洲的战略、经济和军事地位对其帝国主义利益极为重要，因此，它的目标和主要目的是维护和加强其在亚洲的战略、经济和军事地位。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-138","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":138,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"苏联也在千方百计、全力以赴地争取扩大在亚洲已经占据的位置。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-139","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":139,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国则公开显示了自己要成为亚洲国家统治者的姿态，为此，中国与美国，特别是与日本结盟，并直接反对苏联。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-140","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":140,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"日本也有统治亚洲的野心，这是日本帝国主义的老野心。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-141","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":141,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这就是为什么苏联如此害怕中日同盟，并且如此强烈地反对它。但美帝也不希望这一同盟如此稳固，以致超出了可能侵犯美国利益的限度，尽管它鼓励并“祝福”中日两国签署条约，因为这一条约可能遏制苏联的扩张，而苏联的扩张有损于美国统治。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-142","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":142,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"印度作为一个大国——也有野心想成为一个在亚洲拥有原子弹和巨大影响力的大国——正发挥着特殊作用，特别是涉及到它处在美国和苏联这两个帝国主义超级大国在印度洋、波斯湾及其东部和北部边界扩张利益的节点上的战略地位。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-143","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":143,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"英国帝国主义也没有放弃统治亚洲国家的目的。某些资本主义帝国主义国家也有类似的目的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-144","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":144,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这就是为什么亚洲成为当今帝国主义之间激烈最竞争的地区之一，并因此他们在那里创造了许多危险的世界灾难的温床，使各国人民将为此付出代价。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-145","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":145,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"为了平息亚洲各国的革命和解放斗争，为了为其霸权主义和扩张主义计划开辟道路，苏、中修正主义者处于激烈的竞争中，一直从事着分裂和摧毁这些国家的共产党队伍以及热爱自由的革命力量的肮脏工作。这个工作使印尼共产党[11]遭受灾难，印度共产党[12]走向分裂和灭亡等事件的主要原因之一，他们主张无产阶级和广大人民群众同当地反动资产阶级联合统一，而同时苏中都在为自己的目的争取这个当地统治资产阶级的友谊。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-146","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":146,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"苏、中社会帝国主义从霸权主义和扩张主义的立场和野心出发，对亚洲各国的干涉，使这些民族的解放运动面临极大的危险，甚至直接危及越南、柬埔寨和老挝[13]解放战争的胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-147","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":147,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党领导的亚洲国家革命和热爱自由的力量，必须正视和消除帝国主义赞助人武装起来的当地反动派所带来的危险，以及分裂和破坏活动所带来的危险和苏中国修正主义正主义者的霸权主义和扩张主义计划。他们还必须摆脱一系列旧的反动的、神秘的、佛教的、婆罗门教的和其他宗教思想和观念，这些思想和观念阻碍了解放运动。也要从根本上防止“新”的反动思想和观念，如赫鲁晓夫修正主义、毛主义和其他同反动理论一样的迷惑和欺骗群众的思想，否则将剥夺他们的战斗阶级精神，使他们走上错误和无望的道路。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-148","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":148,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"摆在亚洲各国人民面前的解放斗争，确实是困难的，有许多障碍，但是从来没有，也永远不会存在容易的、没有大的困难和必须克服的障碍、不需要流血、不需要付出许多牺牲来换取最终的胜利的解放斗争和革命。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-149","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":149,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"总的来说，拉美国家的资本主义发展水平高于非洲和亚洲国家。但拉美国家对外资的依赖程度不低于绝大多数非洲和亚洲国家。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-150","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":150,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"与非洲和亚洲国家不同，自19世纪上半叶以来，由于拉丁美洲各国人民反对西班牙和葡萄牙殖民者的解放斗争，拉丁美洲大多数国家早就独立了。如果这些国家在摆脱西班牙或葡萄牙殖民的束缚之后，没有再次受到英国、法国、德国、美国和其他外国资本的半殖民束缚，它们将取得更大的进步。本世纪初以前，英国殖民者才是这个大陆的主人。他们从这些国家掠夺了大量的原材料，建造了港口、铁路、发电站，以专门为特许公司服务，并在那里交易英国生产的工业品。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-151","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":151,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这种情况改变了，但不利于拉丁美洲人民，因为美国在其帝国主义发展阶段渗透进了拉丁美洲。美帝利用“门罗主义”所叫嚣的“美国为美洲人民服务”[14]的口号，来确立其对整个西半球的不可分割的统治。美国对本半球的经济渗透是通过军事力量、政治勒索以及美元外交手段，通过大棒和胡萝卜进行的。因此，在1930年，美国和英国资本在拉丁美洲的投资是平等的，而在第二次世界大战之后，美国成为了这个地区经济的真正主人。它的大型垄断企业控制了拉丁美洲的主要经济部门。该大陆各国成为美帝“隐形”帝国的一部分，美帝开始在所有这些国家制定法律，任命和罢免国家元首和政府首脑，规定其内外经济和军事政策。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-152","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":152,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"美国的垄断公司通过开采丰富的自然资源和从拉丁美洲人民的辛劳、汗水和鲜血中获得了惊人的利润：在这个大陆的各个国家投资的每一美元，他们就获得了4-5美元的利润。这种情况一直持续到今天。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-153","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":153,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"尽管帝国主义国家在拉美的资本投资导致了一些现代工业的建立，特别是采掘业以及轻工业和食品加工业，但这些投资对拉美国家的总体经济发展造成了很大的阻碍。帝国主义国家的垄断和新殖民主义政策使这些国家的经济发展呈现出扭曲的、片面的形式和单一的文化特征，把它们简单地变成了原材料的专门供应商：委内瑞拉—石油、玻利维亚—锡、智利—铜、巴西和哥伦比亚—咖啡、古巴、海地和多米尼加共和国—糖，乌拉圭和阿根廷—畜产品，厄瓜多尔—香蕉，等等。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-154","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":154,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这种片面性使这些国家的经济完全不稳定，完全不能迅速、全面地发展，完全受资本主义世界市场价格变化和波动的支配，美国和其他资本主义国家的任何生产下降和任何经济危机的显现，都必然会对拉丁美洲国家的经济产生消极的、甚至更严重的影响。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-155","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":155,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"第二次世界大战后，帝国主义巨头开始对工业、采矿、农业等各个部门进行大规模直接投资，收购民族企业等。他们扩大了对整个生产部门的控制，把拉丁美洲国家的掠夺提高到最大限度。同时，他们鼓励以高利率提供贷款和融资，从而使这些国家更紧密地受到外国的控制——首先是美国的统治。仅巴西就向外国银行借了近400亿美元的债务，而墨西哥有将近300亿美元的债务。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-156","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":156,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"拉丁美洲的资本主义发展总体上是落后的，也是因为还有许多未完全丧失封建性质的大庄园残余，这就是为什么在一些拉丁美洲国家，就像亚洲和非洲那样，非常明显地落后。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-157","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":157,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在拉丁美洲国家，已经形成了一个寡头，一个依赖着帝国主义的经济政策和帝国主义的直接干涉的，非常强大的的大垄断资产阶级，它和大地主一起掌握着国家权力，并且总是在美帝的支持下，和美帝一起，残酷地压迫和剥削工人阶级、农民和生活在赤贫中的其他劳动阶层。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-158","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":158,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这一发展也造就了数量相当大的工业无产阶级，它同农业无产阶级、建筑业和服务业的工人一起，占人口的近一半，不像非洲和亚洲——在大多数亚非国家，工人阶级数量都很小。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-159","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":159,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"除此之外，在拉丁美洲，从阶级中脱颖而出的农民和工人阶级，在不断争取自由、土地、工作和面包的斗争中获得了丰富的武装革命传统，这种传统在反对地方寡头、外国垄断和美帝的斗争中得到了进一步发展。拉丁美洲人民是最为反抗国内外压迫者和剥削者的民族之一，他们的斗争和流血最多。在这些斗争中，他们取得了好几次的胜利，胜利还不小，但任何一个拉丁美洲国家仍然没有取得民主自由、消灭剥削、确保国家独立和主权的彻底胜利。拉丁美洲人民对古巴人民的胜利怀有许多希望，抱有许多幻想，这成为他们摆脱当地资本主义和地主统治者以及美帝束缚的斗争的鼓舞和动力。然而，当他们看到卡斯特罗的古巴不是向在社会主义道路上发展，而是在向修正主义-资本主义道路上发展时，这些希望和这种激励很快就消失了，当古巴成为苏联社会帝国主义的附庸和雇佣兵时，这种希望和激励更迅速地消失了。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-160","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":160,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在今天的拉丁美洲，就像在所有大陆一样，情况是复杂的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-161","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":161,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在这些国家中，大多数条件都是革命性的，推翻资产阶级和地主的统治和消灭对帝国主义的依赖的革命已提上了日程。当然，由于每个国家或国家集团的特殊情况和问题、社会经济发展水平的不同、对帝国主义或社会帝国主义的依赖程度的不同、温和派的多少、法西斯分子的多少、资产阶级政权的强大等已知原因，这些革命不可能在任何地方都有相同的性质、相同的发展过程和相同的解决办法，但有一点显然是必要的，那就是反帝、民主和社会主义的革命任务紧密地联系在一起，比非洲和亚洲许多国家更加紧密。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-162","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":162,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"拉丁美洲在革命主观要素的准备方面也有许多优势，因为广大人民群众的觉悟和准备程度比较高，愿意同国内外的压迫和剥削作斗争，争取自由、民主和社会主义。然而，不仅是帝国主义者，特别是美帝，加上地方的反动派，还有地方的修正主义者和资本主义的其他机会主义走狗，以及苏联修正主义者和中国修正主义者，都在极力阻挠、迷惑和反对这要素的充分准备。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-163","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":163,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"坚持把拉丁美洲作为其专属领土的政策并从中获取巨大的超常利润的美帝，正在用一切手段——军事力量、特务、煽动和欺骗——来阻止任何其他帝国主义在那里占主导地位，并确保革命不会在这些国家爆发和胜利。因此，它既要维持拉丁美洲国家对美国的完全依赖，又要维持这些国家的资产阶级地主统治秩序。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-164","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":164,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"为此，美国手中的一个重要武器是所谓的美洲国家组织，它由美国总统、五角大楼和国务院指挥。这个组织的《宪章》[15]赋予美国以任何方式、任何手段、甚至军事手段进行干预的权利，以维持拉丁美洲国家的国内外现状。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-165","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":165,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"同时，美国的大垄断企业通过组建以美国为中心、由美国控制的跨国垄断公司，并大量利用国家资本，完善了在这些国家的剥削方式，通过这些方式，他们也确保了对地方政府和国家机构的控制。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-166","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":166,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是，美国所采用的这些和许多其他手段并不能解决严重的经济和政治危机所产生的问题，而这场危机也使拉丁美洲国家陷入困境。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-167","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":167,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"既然地方资本家和地主不依赖于美帝，不得到美帝的支持就不可能存在，那么革命作为国家和社会解放的唯一不可缺少的手段，在这些国家的无产阶级、劳动农民、进步知识分子和青年群众的意识中的深度和广度就越来越加强。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-168","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":168,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"为了避免革命，美帝和地方资本家主要采取两种方法。一种是当他们看到自己的地位受到更加直接的威胁时，便通过“军事公告”（军事政变）建立军事法西斯政权。这就是他们在巴西、智利、乌拉圭、玻利维亚和其他地方所做的。另一种方法是，在委内瑞拉、墨西哥，或者像现在在巴西所做的那样，组织在基本的自由权方面具有明显局限和巨大差距的民主资产阶级政权，试图以此缓和革命的紧张局势，给人留下更深刻的印象——这些国家的资产阶级，以及美国政府及其总统（更加突出）关心人权问题。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-169","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":169,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是，这种手段和伎俩不能解决危机问题，不能避免革命局面，不能把革命从议事日程上抹去。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-170","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":170,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"拉美国家的无产阶级和一切革命力量都面临着非常重要的革命任务。为了完成这样的任务——即进行革命，争取民族的完全独立，建立民主、自由和社会主义，他们必须在许多方面进行斗争，去反对地方资产阶级和大地主寡头，反对美帝，反对各种资本的走狗，帝国主义和社会帝国主义，如亲苏联和卡斯特罗的修正主义者、亲中国的修正主义者、托洛茨基主义者等。他们不仅要对付各种各样躲在阴暗面的机会主义者和修正主义者的分裂活动，而且要摆脱一些已经成为一种传统的盲动主义、游击主义[16]、冒险主义的观念和做法所表现出来的小资产阶级作风，这与真正的革命没有什么共同点，反而造成了极大的破坏。然而，这个问题需要仔细处理。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-171","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":171,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"就拉丁美洲各国人民的好战传统而言，积极的革命方面占主导地位。它是革命准备和发展中必须最大限度地利用和尽可能广泛地利用的一个非常重要的因素，同时赋予传统新的内容，不受消极的游击主义因素的影响。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-172","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":172,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"工人阶级的马列主义政党在执行这些伟大的任务中起着决定性的作用。现在，拉丁美洲几乎每个国家都成立了这样的政党，而且大多数政党都在为无产阶级和人民群众的革命准备工作中迈出了重要的一步。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-173","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":173,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在反对修正主义和其他机会主义，反对资产阶级和帝国主义的一切走狗，反对卡斯特罗主义、赫鲁晓夫主义、托洛茨基主义、“三个世界”理论以及其他诸如此类的观点和做法的不可调和的斗争中，他们制定了正确的政治路线，在实践这条路线的斗争中积累了充分的经验，成为过去一切革命传统的继承者，以进一步利用和发展这条路线，使之有利于工人运动、民族解放运动和革命中群众基础的准备和提高。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-174","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":174,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"今天的革命形势使得这些政党必须尽可能地保持最密切的联系，相互协商，能够从彼此的经验中获得最大的利益，并协调他们在共同反对反动资产阶级和帝国主义，反对苏联、中国和其他现代修正主义的共同问题上，以及革命中出现的所有问题上的立场和行动。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-175","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":175,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"现在各国人民已经觉醒，拒绝再生活在帝国主义和殖民主义的枷锁之下，现在他们要求自由、独立、发展和进步，对外国和国内的压迫者充满愤怒，现在非洲、拉丁美洲和亚洲已经成为一个沸腾的大熔炉，新老殖民主义者发现，很难通过以前的方法和形式来统治和剥削这些国家的人民——如果这些方法和形式还管用的话。他们除了掠夺和剥削这些民族的财富、辛劳和鲜血， 一无是处。这就是为什么他们要努力寻找欺骗、掠夺、剥削的新方法、新形式，做一些施舍——这些施舍仍然不利于群众，而利于资产阶级的地主统治阶级。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-176","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":176,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"同时，这个问题变得更加复杂，因为苏联社会帝国主义很早以前就开始在前殖民地和半殖民地越来越深入地渗透和巩固自己，而且社会帝国主义的中国也开始狂热地努力以进入那里。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-177","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":177,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"修正主义苏联打着所谓的列宁主义民族解放斗争援助政策的幌子进行扩张主义干涉，冒充这些国家和民族的天然盟友。苏联修正主义者利用和传播社会主义色彩的口号，作为渗透非洲和其他地区的一种手段，目的是欺骗那些渴望解放自己、消除压迫和剥削、知道实现民族和社会解放的唯一道路是社会主义的民族。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-178","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":178,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"苏联也让它的盟友，或者更准确的说，让它的卫星国参与干涉。我们在非洲具体地看到了这一点：苏联社会帝国主义及其古巴雇佣军以协助革命为借口进行干预。这是个谎言。他们的干预不过是一种旨在占领市场和奴役人民的殖民主义行动。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-179","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":179,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"苏联及其古巴雇佣军对安哥拉的干预就是这种性质的。他们从未有过协助安哥拉革命的丝毫意图，他们的目的过去是而且现在还是要把爪子伸进在葡萄牙殖民者被驱逐后赢得了一定独立的非洲国家。古巴雇佣军是苏联派遣的殖民军队，目的是占领非洲黑人国家的市场和战略地位，并从安哥拉继续到其他国家，使苏联的社会帝国主义者也能建立一个现代殖民帝国。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-180","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":180,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在苏联及其雇佣军帮助人民获得自由的幌子下，古巴装备着火炮和机关枪介入其他国家，声称要建设苏联和古巴都不存在的社会主义。这两个修正主义-资产阶级国家干预安哥拉，是为了帮助一个资本主义集团夺取政权，这与安哥拉人民为争取脱离葡萄牙殖民者，获得自由而斗争的目的背道而驰。阿戈什蒂纽·内图[17]在玩苏联的游戏，在反对另一派的斗争中，为了自己夺取政权，他号召苏联人帮助他。两个对立的安哥拉部族[18]之间的斗争没有任何的人民革命性质。他们之间的斗争是派系争夺权力的斗争。他们每一方都得到不同帝国主义国家的支持。阿戈什蒂纽·内图在这场比赛中获胜，而不是社会主义获胜。相反，追随别国的干涉，苏联在那里建立了新殖民主义。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-181","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":181,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"社会帝国主义的中国也在努力向前殖民地和半殖民地国家渗透。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-182","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":182,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"扎伊尔就是中国如何干预的一个例子。扎伊尔是一个由围绕蒙博托[19]的集团统治的国家，这个集团是非洲大陆上最富有、最嗜血的集团。在最近扎伊尔爆发的战斗中，摩洛哥谢里菲[20]王朝的摩洛哥人、法国空军和中国都向杀害帕特里斯·卢蒙巴[21]的凶手蒙博托提供援助。法国人提供的援助是可以理解的，因为他们的干预是为了捍卫他们在加丹加[22]的特许权和康采恩，同时也是为了保护他们的人，以及蒙博托和他的集团。但是中国修正主义者在加丹加想要什么？他们在那里协助谁？他们是否在帮助被蒙博托及其集团以及法国、比利时、美国和其他特许权持有者镇压的扎伊尔人民？或者，他们不是也在帮助嗜血的蒙博托集团吗？事实上，中国修正主义领导层并不是间接地，而是相当公开地协助这个集团。为了使这一援助更加具体、更加具有示范性，中国派出了外交部长黄华[23]以及军事专家和军事经济援助。因此，它采取了反马克思主义、反革命的方式。中国的干涉与摩洛哥国王哈桑[24]和法国的干涉具有完全相同的特点。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-183","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":183,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国的社会帝国主义不仅干涉扎伊尔的事务，而且还干涉非洲和其他大陆的民族和国家的事务，特别是干涉那些他们千方百计想要渗透进去的国家的事务，以便在那里建立经济、政治和战略基础。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-184","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":184,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"即使是美国也不敢像中国那样公开援助智利法西斯刽子手皮诺切特[25]。实际上，美国人并没有以这种方式帮助其他国家的反动统治者，尽管他们在那里有很大的利害关系。这并不意味着美帝正在放弃自己的利益。他们确实捍卫这些利益，非常有力地捍卫它们，但方式更微妙。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-185","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":185,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"所谓社会主义中国，就是以它所坚持的立场，违背各国人民、各国共产党、各国革命分子的利益和愿望，违背拉丁美洲一切进步人民的愿望。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-186","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":186,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国正在保护着统治各国人民的，用恐怖和其他手段压制革命、无产阶级和争取国家和社会解放的马列主义政党的努力的独裁者。有了这样的立场，中国就走上了反革命的道路。在马列主义的幌子下，它试图表明它是把革命的思想输出到各个国家，但事实上，中国正在输出反革命的思想。这样就帮助了美帝和法西斯当权集团。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-187","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":187,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"帝国主义和社会帝国主义列强也在同一程度上努力防止非洲、亚洲、拉丁美洲人民逐步发展革命斗争，反对他们的统治者和帝国主义者的压迫和野蛮剥削，这些统治者和帝国主义者一致，是在吸食他们的鲜血。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-188","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":188,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在社会经济发展水平低、依靠帝国主义和社会帝国主义列强的国家里，革命家、进步分子和爱国者的责任，是使人民认识到这种压迫和剥削，继而教育、动员和组织人民，使人民投入解放斗争，始终牢记革命是由广大人民群众、全民族进行的。为此，必须深入分析每一个国家的国内外形势，社会经济发展情况，阶级力量的比例，阶级之间的对立情况，人民和执政的反动集团之间的对立情况，人民和帝国主义国家之间的对立情况。在此基础上，得出正确的结论，即必须采取的步骤和必须使用的策略。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-189","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":189,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命力量所需要的，是精干的工作、决心和智慧，首要的是要深刻地认识到，只有把这一斗争同无产阶级事业、社会主义事业联系起来，他们国家的解放斗争才能取得真正的胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-190","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":190,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，每个国家的无产阶级都必须建立自己的革命党，革命党必须能够忠实地运用马克思、恩格斯、列宁、斯大林的教诲，把这些教诲同每个国家的情况，同每个单独个人的情况紧密地联系起来。这些政党中的每一个党都必须深刻地了解人民群众的心理和国家的经济、政治、思想、文化的发展，不能任性地、冒昧地行事，不能以布朗基主义[26]的作风行事，要坚持不懈地团结无产阶级的同盟者——广大的人民群众。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-191","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":191,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"各国革命家和人民群众要时刻做好准备，牢记反动资产阶级和当权的大地主、外国压迫者的行径和新殖民主义者的阴谋。这些都是革命分子和人民群众必须成熟地面对的重要因素，必须有健全的组织和革命策略。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-192","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":192,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"当然，不仅不能排除合作、协调和经验交流的联系，而且必须在各国革命力量和革命分子之间建立这种联系。因为他们有许多相似的条件，例如新殖民主义者和反动资产阶级的压迫和剥削，共同的文化，从这种压迫和剥削中解放出来的共同目标，所以事情会比较容易。他们共同的条件和利益，促使这些国家的革命进步分子进行协商，在行动中发展合作与协调，以对抗压迫他们的敌人的行动。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-193","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":193,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"从马列主义的立场审视新殖民统治下各民族的衰败状况，所有真正的革命者面临的任务是要给这些民族的革命和解放斗争提供无保留的支持和支持，使其不断前进，革命不断地建立起来，为了彻底的胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-194","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":194,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"真正的革命号召无产阶级和民族为新世界，社会主义世界而奋起","language":"中文","translation":false},{"id":"hoxha-imperialism-3-195","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":195,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"正如我们在前面所解释的，资本主义的危机正在日益加深。因此，无产阶级、被压迫阶级和民族拒绝再忍受剥削，要求改变生活，要求推翻资产阶级秩序，要求打倒新殖民主义和帝国主义。但这些愿望只有通过革命才能实现。不与内外阶级敌人发生冲突并进攻他们，就不可能取得胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-196","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":196,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"真正的工人阶级马列主义政党，作为革命的领导者，使无产阶级、劳动人民和人民觉醒，并在政治上、思想上和军事上为这些冲突做好准备。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-197","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":197,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党，所有革命者，无论数量怎样少，在人民心中树立形象，系统地组织群众，怀着巨大的关心和耐心，相信自己是一支强大的力量，能够推翻资本，夺取政权，为无产阶级和人民谋利益。这样的政党，不认为自己小，就对抗不了资产阶级政党的联合和他们形成的观点。革命家的任务是向广大人民群众证明，资产阶级创造的这种观点是错误的，必须消灭之，必须形成代表伟大变革力量的真正的革命观点。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-198","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":198,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党要顺利完成自己的使命，首先必须有革命性的战略战术，正确的政治路线，必须响应广大人民群众的利益和愿望，革命地解决问题，以及消灭资产阶级秩序与外国帝国主义统治现状的斗争任务。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-199","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":199,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义是赋予工人阶级革命党正确的政治路线，明确其战略目标和任务，并使其运用革命的策略和方法实现这些目标和任务的可能性的唯一科学。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-200","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":200,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在马列主义的启发下，按照国家具体的社会经济政治条件和国际形势，马列主义政党在任何时候，在革命的每一个阶段都知道如何定位自己，站在群众的前列，无论是民主的、民族的解放运动，还是社会主义革命。以马列主义、世界无产阶级革命实践和本国阶级斗争为基础的革命战略和正确的政治路线，使马列主义政党可以明确界定既定阶段的战略目标，确定谁是主要打击的首要内外敌人。无产阶级内外的同盟者是谁等等。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-201","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":201,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党的目的是推翻资本主义秩序，取得社会主义胜利，而当他们的国家面临着民主和反帝国主义的任务时，他们的目标是不断地发展它，把它推进到社会主义革命中，尽快地去实现履行社会主义的任务。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-202","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":202,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党的战略目标和实现这一目标的道路，完全不同于假共产主义者和工党的战略目标。不推翻资本主义的生产关系，摧毁旧的国家机器，整个资产阶级上层建筑和它的基础，前者就无法实现目标。他们坚持列宁的教诲：","language":"中文","translation":false},{"id":"hoxha-imperialism-3-203","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":203,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“革命就是无产阶级破坏‘管理机构’和整个国家机构，用武装工人组成的新机构来代替它。”（出自《国家与革命》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-204","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":204,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"后者鼓吹要维护旧的国家机器，尽管他们声称他们主张社会主义。他们认为，社会主义可以通过改良，通过议会道路，甚至使用旧的国家机器来建立。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-205","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":205,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"现在，许多所谓的共产党在捍卫现有资本主义秩序方面比公开的资产阶级政党更热心。例如，在西班牙一些资产阶级政党要求用共和政体取代胡安·卡洛斯的君主政体之际，伊巴露丽—卡里略（Ibarruri—Carillo）的修正主义政党却厚颜无耻地为君主政体辩护。同样，在各资产阶级政党不公开这么做的时候，贝林格的修正主义政党以意大利资本主义国家压迫性法律的狂热拥护者的面貌出现了，这些法律的目的是反对民主自由。中国修正主义者则指示资本主义国家中走中国路线的政党，必须同最军国主义的集团一起战斗，加强军队和资产阶级暴力机关的力量，宣称是保卫祖国，但实际上是镇压革命，如果革命爆发的话。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-206","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":206,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"资产阶级及其追随者，特别是现代修正主义者，企图破坏革命和解放运动，使资本主义和帝国主义的统治永久化，企图用各种方法迷惑和分裂革命力量，消除革命的敌人和朋友的区别。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-207","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":207,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"典型的是中国修正主义者的说教，他们把大垄断资产阶级、反动法西斯政权、北约和欧洲共同体，甚至美帝，当作无产阶级和被压迫人民的同盟。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-208","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":208,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"就马列主义政党而言，他们认为建立真正革命战略的绝对必要条件是在革命的发动力量和敌人之间建立一条清晰的分界，并明确地找出主要的内外敌人，正如斯大林指出的那样， 瞄准主要敌人，但也不能低估和忽视与其他敌人的战斗。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-209","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":209,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在我们这个时代，在帝国主义的情况下，革命的主要国内敌人，不仅在发达资本主义国家，而且在被压迫和不独立的国家，都是站在资本主义秩序的顶端，用一切手段，用暴力和压迫，用蛊惑和欺骗进行抵抗，维护统治和特权，扼杀和消灭任何哪怕只是轻微危害其国家权力和阶级利益的工人运动的地方大资产阶级。另一方面，在实际情况下","language":"中文","translation":false},{"id":"hoxha-imperialism-3-210","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":210,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命和人民的主要外敌是世界帝国主义，特别是帝国主义超级大国。像中国修正主义者所主张的那样，劝告和号召无产阶级和被压迫民族依靠一个超级大国同另一个超级大国作战，或者借为了捍卫民族自由和独立之名而同帝国主义列强结盟，不过是对革命事业的背叛。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-211","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":211,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"修正主义者把工人阶级在革命中的统治地位——革命战略的根本问题之一——作为他们的特殊攻击目标。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-212","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":212,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁写道：“马克思学说中的主要的一点，就是阐明了无产阶级作为社会主义社会创造者的世界历史作用。”（出自《马克思学说的历史命运》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-213","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":213,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"列宁把革命运动中对无产阶级统治地位的否定说成是改良主义最庸俗的表现。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-214","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":214,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在现代修正主义者中，有些人试图证明工人阶级已经去无产阶级化，并转化为企业的“共同管理者”，因此不再有需要无产阶级革命的地方，不需要一个与现存的社会秩序不同的社会秩序。还有人说，不只是工人，现在从事劳动和文化活动的人和所有的工薪阶层都是无产阶级，而且不仅工人阶级，社会其他阶级、阶层都对社会主义感兴趣。因此，他们认为，工人阶级在今天革命运动中的领导地位已经失去了意义。苏维埃修正主义者不否认工人阶级的领导作用，而在实践中却否定了它，因为他们剥夺了工人阶级领导的任何可能性。但即便在理论上，他们也消除了这种角色，因为他们捍卫声名狼藉的“全民党-全民国家”理论。中国修正主义者和实用主义者一样，有时把农民，有时把军队，有时把中小学生，等等，放在革命的首位，这是不合时宜的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-215","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":215,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"阿尔巴尼亚劳动党坚决捍卫马列主义的论点，认为工人阶级是社会发展的决定性力量，是世界革命变革的领导力量，是社会主义和共产主义社会的建设者。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-216","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":216,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"工人阶级仍然是社会的主要生产力，是最先进的阶级，是最关心民族解放、社会解放和最关心社会主义的阶级，是革命组织和斗争的优良传统的承载者。它拥有社会革命转型的唯一科学理论，以及自己战斗性的马列主义政党引领它为实现这一目标而奋斗。客观上，历史赋予它领导从资本主义向共产主义过渡的整个斗争的使命。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-217","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":217,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"新政权可以根据革命的具体情况和进入的不同时期，经历不同的阶段，取不同的名称，但是没有无产阶级专政的建立，革命就不可能向社会主义胜利方向发展。马列主义教导我们这一点，所有胜利的社会主义革命的经验也证明了这一点。因此，无论革命出现什么样的情况，马列主义政党都决不放弃建立无产阶级专政的目的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-218","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":218,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"形形色色的修正主义者，都无一例外地以某种方式否定建立无产阶级专政的必要性，因为他们反对革命，因为他们主张维护和延续资本主义秩序。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-219","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":219,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"无产阶级和马列主义政党与自己的同盟者一起作战。这也是革命战略中最重要的问题之一。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-220","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":220,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"贫农是无产阶级的天然的亲密盟友，这不仅与眼前的战略目标相联系，更是与长远和最终的战略目标相联系。城市劳动人民中的贫困阶层也是这样的同盟者。无产阶级同贫苦的农民和其他受压迫和剥削的劳动人民一道，是革命的主要动力。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-221","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":221,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"城市小资产阶级也可以而且应该成为同盟者，因为他们始终处于大资本的控制之下，面临着财产被完全没收的威胁。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-222","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":222,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"无产阶级还在努力斗争，使人民中的其他阶层和自己结成同盟，例如被国内外资本剥削的知识分子中的进步力量。在资本主义国家和修正主义国家，知识界的分量增加了。但是，尽管它的地位、性质和工作的作用发生了种种变化，但它本身并不能也永远不能构成一个阶级，也不能像各种修正主义者所说的那样，与工人阶级合并。因此，正如列宁所展示的和历史所证明的，知识分子不可能是一个独立的社会政治力量。它在社会中的地位和作用，是由它的社会经济地位和思想政治理念所决定的。无论这种立场和这种理念有多大的变化，知识分子永远不能取代工人阶级领导革命的作用。无产阶级的任务是争取知识分子中的进步派，使他们相信资本主义制度崩溃和社会主义胜利的必然性，使他们成为革命的同盟者。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-223","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":223,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在非洲、拉丁美洲、亚洲等社会经济发展不大、对外资依赖较多、民主和反帝的革命任务特别重要的国家，中农和中等资产阶级——同外国资本没有联系，且渴望一个独立发展的国家——也可以是无产阶级的盟友。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-224","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":224,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"把这一部分资产阶级同民主反帝革命结合起来，有赖于无产阶级的正确战略战术，有赖于工人阶级革命党的娴熟和智慧的手段。这样，无产阶级和它的党不仅可以说服小资产阶级，而且可以说服这种资产阶级，使他们把自己置于无产阶级的领导之下，起来消灭外国的统治，消灭野蛮的大资产阶级——帝国主义压迫和剥削人民，使他们士气低落，败坏他们纯洁的感情和几百年来的文化的工具。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-225","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":225,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"无产阶级要争取在革命某一阶段有志于实现战略目标的其他阶级和阶层的同盟，就必须同大资产阶级和其他反动派作斗争，对于其他问题也是一样。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-226","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":226,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"反动资产阶级和大地主预见了自己的失败，千方百计地把小资产阶级、农民阶级和进步知识分子拉到自己这边来，防止他们成为无产阶级的同盟者。他们甚至企图欺骗工人阶级本身，使革命不爆发，如果爆发的话，则保证革命不进行到底，而陷入泥沼或者掉头。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-227","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":227,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"无产阶级和马列主义的党尽一切可能实现盟友的团结，来对抗共同的敌人，如大资产阶级、大地主、帝国主义者和社会帝国主义者。还要防止农民阶级和小资产阶级成为大资本的储备军，以及防止就像德国希特勒、意大利墨索里尼和西班牙佛朗哥那样的法西斯专政。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-228","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":228,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党需保持谨慎和灵活的态度，尤其是对摇摆不定、可能或暂时的盟友，包括中等资产阶级中的各个阶层——他们以各种利益、传统和偏见，与资本主义和帝国主义世界联系在一起。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-229","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":229,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命的铁律就像其他地方一样，在修正主义者掌权的国家适用。在欧洲修正主义国家发展起来的新资产阶级的地位是什么？它渴望摆脱苏联资产阶级和社会帝国主义全面、野蛮的压迫，但双方有着根本的共同利益。离开苏联资产阶级，这些国家的资产阶级是不可能存在的。即使脱离这个野蛮的社会帝国主义的大资产阶级，也无疑很快就会受到西欧发达资本主义国家资产阶级和美帝的统治。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-230","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":230,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"同时，在经济、政治、军事上正在融入强大的苏联社会帝国主义国家的修正主义国家，除无产阶级外，还有其他阶层的人，因为受到新资产阶级的剥削和苏联社会帝国主义的统治而不满。为此，他们既痛恨自己国家的统治资产阶级，又痛恨俄国的霸权主义和新殖民主义。要唤醒这些国家的无产阶级，使他们认识到在战场上再次挺身而出的历史必要性，认识到为了再次进行无产阶级革命，为了重新建立无产阶级专政而投入推翻和击溃叛徒的斗争的历史必要性。必须建立新的马列主义政党，团结群众。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-231","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":231,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在坚持革命胜利的决定性因素是内部革命，即自己国家的无产阶级和人民的革命斗争，而外部因素是辅助和次要性质的原则时，马列主义政党丝毫不忽视或低估革命的外部盟友。同时，他们对外部（译注：霍查这里的语境应该是国家的内部或外部）盟友采取原则性的和灵活的立场，就像对待内部盟友一样。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-232","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":232,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"根据列宁和斯大林的教诲，立足于现有条件，他们看到了别果断无产阶级及其革命运动，世界被压迫人民的革命反帝运动和真正的社会主义国家在每个国家的革命运动中作为自然和可靠的外部同盟。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-233","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":233,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在某些特殊条件下，也可以创造出这样的情况：一个社会主义国家，一个反对帝国主义或社会帝国主义侵略的民族，会同几个资本主义国家处于统一战线上，与同一敌人作战，同第二次世界大战期间一样。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-234","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":234,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在这种情况下，确保革命的利益始终要牢记在心，决不因共同战线或与这些临时盟友结盟而被遗忘、蒙蔽或牺牲，确保这一战线或同盟本身不变成一种要达到的目标，是头等重要的。尤其重要的是，不要让这样的同盟干涉破坏革命，夺取革命的胜利。阿尔巴尼亚共产党在反法西斯民族解放战争年代对美、英同盟国的立场经验具有重要意义。这种立场对阿尔巴尼亚革命的命运是有益的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-235","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":235,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命长期战略与马列主义政党为实现革命目的和完成革命任务而采取的革命策略是分不开的。作为革命战略（译注：strategy，战略，用于全局性策划与指挥大规模作战的军事指挥的科学与艺术；tactic 策略：为达到一个目标所采取的一项应急措施）的一部分，为其服务，策略可能会根据革命潮流的起伏、具体的形势和条件而变化，但总是在革命战略和马列主义的原则范围内。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-236","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":236,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“策略领导层的任务，”斯大林说，“就是要掌握无产阶级的所有的斗争形式和组织形式，并确保他们被适当地使用，以使这些力量的关系得到战略成功所必须的最大化成果。”（出自《论列宁主义基础》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-237","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":237,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"真正的马列主义政党，虽然也采取巧妙的策略和斗争形式来推动革命事业，但始终忠实地坚持革命原则。他们拒绝和反对任何由于革命策略的缘故而放弃原则的倾向，他们是任何基于暂时情况而实行无原则的务实政策的最坚决的反对者——这是各色修正主义者全部活动的特征。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-238","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":238,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命永远是革命先锋队领导的群众的行为。因此，马列主义政党不能不以适当的形式集中精力关注群众的革命组织，立足于存在于每个国家的具体情况、国情和传统。如果党与群众不进行有组织的联系，那么唤醒、准备和动员他们进行革命斗争就是个空谈。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-239","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":239,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"正是由于这个原因，马列主义党非常重视自身领导下的群众组织的创建。当然，这不是一个容易解决的问题，尤其是今天，在这样一个各种各样的工会、合作社、文化的、科学的、青年的、妇女的和其他组织存在于所有资本主义和修正主义国家的时候。这些组织大多受资产阶级、修正主义者和教会的领导和影响。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-240","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":240,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"然而，正如列宁教导我们的那样，共产党员必须在群众所在的地方工作。因此，他们也不能不在资产阶级、社民主义者、修正主义者等领导和影响的群众组织中工作。马列主义者在这些地方工作，以破坏资产阶级和改革派的影响和领导，散布工人阶级革命党在群众中的影响，揭露这些组织领导人计划和活动的欺骗性，并给予群众活动反资本主义、反帝国主义、反修正主义的政治性质。通过他们在群众中进行的革命工作，也可以在这些组织中形成革命派别，这样确实可以创造接管这些组织的领导，使它们走上正确道路的可能性。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-241","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":241,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但无论如何，马列主义政党决不放弃建立自己领导下的群众革命组织的宗旨。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-242","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":242,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"最重要的群众组织是工会。总的说来，在今天的资本主义国家和修正主义国家，这些组织是为资产阶级、修正主义服务的，是为了使无产阶级和全体劳动群众继续受奴役。恩格斯在他那个时代说过，英国的工会已经从吓唬资产阶级的组织变成了为资本服务的组织。工会组织用千丝万缕、的奴役链条把工人束缚起来，这样，彼此孤立的工人反抗时，就很容易被镇压。机会主义的工会领袖工作，以使搞罢工或示威的一个乃至多个企业的工人的叛乱得到控制，并只呈现经济上的性质。工人贵族很努力地朝这个方向搞操纵活动。在资本主义国家，这种贵族在腐蚀、镇压、误导群众起义方面起着重要作用，长期以来成为平息革命火焰的消防队。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-243","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":243,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在今天所有的资本主义国家，主要修正主义政党都有自己的工会。这些工会现在团结起来，建立了密切的合作关系，以遏制无产阶级革命运动，在政治上和道德上腐化工人阶级。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-244","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":244,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"例如，在法国和意大利，修正主义政党的工会是强大的大工会。但是他们做什么呢？他们试图把无产阶级束缚起来，哄它入睡，当它变得愤怒和叛逆时，使它走上与老板谈判的道路，并用资本家超级利润的一些非常小的面包屑封住工人的嘴。他们所给的东西之后都会通过提高价格收回。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-245","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":245,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，要摆脱资本主义的束缚，各国无产阶级必须摆脱资产阶级和机会主义者控制的工会的束缚，摆脱任何一种社民和修正主义的组织或政党的束缚。所有这些组织都以各种方式支持自己的阶级，并试图制造一种错觉，即“他们是一股强大的力量”，他们是一道障碍，他们可以把自己强加于大资本家之上，宣称是为了无产阶级。这不过是个大骗局。无产阶级必须粉碎这些组织。但是怎么做呢？要消灭他们，必须同这些工会的领导作斗争，必须反对他们同资产阶级的奸诈联系，必须打破他们所要建立的“稳定”和“社会和平”，以及工会不时从事的所谓对有产阶级的反抗来掩饰的“和平”。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-246","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":246,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"为了从内部打击和逐渐毁坏工会，反对工会的不公正决定和行为，还有可能通过加入工会来摧毁工会。这种活动必须牵扯到工厂里最大、最有力量的工人群体。在每一种情况下，目的都必须是实现无产阶级的钢铁般的团结，不仅要同雇主斗争，而且还要同他们的代理人、工会老板斗争。工会领袖的一切叛卖分子，工会领导层和整个改良主义工会向着资产阶级的堕落，都被有力地揭露出来，使工人们从对这个领导层和这些工会的许多幻想中清醒过来。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-247","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":247,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在渗透现有工会的同时，马列主义者从未堕落到工团主义者、改良主义者、无政府工团主义者、修正主义者的立场——这些特征恰恰代表了这些工会的领导层。他们决不与工会领导层的修正主义者和其他资产阶级、机会主义政党合作。他们的目的是揭露今天资本主义国家和修正主义国家一切工会的资产阶级性质和反动作用，破坏这些组织，为建立真正的无产阶级工会开辟道路。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-248","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":248,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"青年组织对马列主义政党具有特殊的重要性。青年在革命运动中的作用历来很大。从本质上讲，青年标新而除旧，并显示出自己准备为一切进步的、革命的事业的胜利而斗争。然而，只凭自己，它无法找到正确的道路。只有工人阶级的党才能指明这条路。当青年人无穷的革命能量，同工人阶级和其他劳动群众的能量，联合起来消灭压迫和剥削，争取民族解放和社会解放时，就没有任何力量能够阻止革命的胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-249","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":249,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"然而，在今天的资本主义国家和修正主义国家，大多数青年人把精力用在了错误的方向上。他们受资产阶级和修正主义者的误导，常常转向冒险主义和无政府主义，或者陷入乌托邦和绝望，因为他们被弄得迷失方向，困惑不解，对未来，对实现政治、物质和精神要求的前景抱着悲观的看法。马列主义者十分重视青年人，试图启发他们，使他们相信青年人的需求和愿望只能在马列主义的指导下，在工人阶级和党的领导下才能实现。他们正在努力使青年人摆脱资产阶级和修正主义者的影响，摆脱“左派”、托派或无政府主义运动的影响，动员他们参加革命组织，使他们走上革命道路。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-250","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":250,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"真正的马列主义党和革命的共产主义者积极参加工人罢工和示威活动，进行政治斗争和示威游行，使资本主义、雇主、卡特尔、垄断者和工会领袖们的生活变得难以为继。在这广泛的活动中，无产阶级同资本主义秩序的武装力量的斗争，会更加经常和公开，但是从这些斗争中，无产阶级将学会更好地战斗。在斗争的过程中，也发现什么样的组织形式和革命斗争是可能的、正确的、适当的。俗话说：“不下水就不会游泳”。不采取罢工、示威的方式进行斗争，不积极地参加总的反资本主义的行动，就不能组织和加强争取最后胜利的斗争，就不能推翻资本主义秩序。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-251","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":251,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命的准备，不是像各种修正主义者那样光搞嘴上功夫，也不是像中国修正主义者那样提出“三个世界”这样的理论。它不能在和平的道路上取得胜利。列宁确实讲过在具体的例子中和平胜利的这种可能性，但他总是把主要精力放在革命暴力上，因为资产阶级从来没有主动投降过。国际工人运动和共产主义运动的历史，一些前社会主义国家和我们的社会主义国家革命发展和工人阶级胜利的历史，表明到目前为止，革命只有通过武装起义才能取得胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-252","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":252,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"革命武装暴动与军事政变毫无共同之处。前者的目的是彻底推翻旧政权，粉碎它的根基。后者没有，也不能导致压迫剥削秩序的推翻和帝国主义统治的覆灭。武装暴动是建立在广大人民群众的拥护基础上的，而政变则是不信任群众、脱离群众的表现。称自己为工人阶级的党的政党政策和活动中的盲动主义倾向，是与马列主义的背离。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-253","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":253,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"根据一个国家的具体情况和大局，武装起义可以是一个突然爆发的革命过程，也可以是一个更加持久的革命过程，但不能是像毛泽东主张的“持久人民战争”那样，没有远见的、无休止的革命过程。如果把马克思、恩格斯、列宁和斯大林关于革命武装起义的学说与毛泽东的人民战争理论相比较，那么这一理论的反马列主义、反科学性就变得明显了。马列主义关于武装起义的学说是建立在工人阶级和革命党领导下的城市斗争与农村斗争紧密结合的基础上的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-254","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":254,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"毛主义理论反对无产阶级在革命中的领导作用，认为农村是武装起义的唯一根据地，忽视了城镇劳动群众的武装斗争。它鼓吹农村必须包围被认为是反革命资产阶级根据地的城市。这是对工人阶级不信任的表现，是对工人阶级统治地位的否定。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-255","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":255,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"工人阶级革命党在坚定不移地坚持马列主义关于暴力革命的学说，将其作为普遍规律的同时，坚决反对冒险主义，从不轻浮地对待武装起义。它在一切条件和情况下，都不断地进行着革命斗争和各种形式的活动，为革命的决战，为用革命的暴力推翻资产阶级的统治，为自己和群众作准备。但只有革命形势完全成熟，才能把武装暴动直接提上日程，采取一切政治、思想、组织和军事措施，把武装暴动引到胜利上。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-256","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":256,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"宣传是马列主义政党为革命作好群众准备的有力手段，但必须是激情的、明确的、令人信服的。革命宣传如果仅仅是空谈惑众的话，是毫无价值的。只有深入的宣传，同生活实际问题、总的问题、地方性的问题紧密地联系起来，在广大群众中创造并鼓励主动的精神，才能在政治上和思想上教育无产阶级和其他劳动群众，让他们行动起来，为革命做准备。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-257","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":257,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"各国的资产阶级，除了军队、警察等可以使用的强大的武力手段外，应对无产阶级的斗争和活动也有广泛的经验。同样，它也有完整的宣传网络，包括新闻、广播、电视、电影、戏剧、音乐等，所有这些宣传都有使人腐化的力量，能够暂时地迷惑、歪曲和削弱无产阶级的努力和解放斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-258","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":258,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在所谓资产阶级民主国家中，也存在着民主自由的衡量标准，仅仅对资本主义进行正常的新闻宣传是不够的。各资产阶级和修正主义政党的报纸上，不断地叫嚣着，当然不是反对资产阶级的秩序，而是反对个人，反对那些企图在他们坐在一起牺牲人民来狼吞虎咽的饭桌上攫取超过自己那份蛋糕的人。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-259","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":259,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"宣传，特别是新的马列主义政党的报刊，面临着一个非常重大的任务：揭露资产阶级“民主”的虚伪性，撕开一切耍花招的面具，以及修正主义者和其他资本家走狗的蛊惑。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-260","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":260,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义的宣传和报刊，揭示赤裸裸的真理，展示通过革命进行社会和民族解放的道路，而资产阶级和修正主义的宣传和报刊欺骗人民，哄他们睡觉，使他们迷失方向，使群众脱离革命，把他们引到盲道上，使他们蒙受奴役。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-261","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":261,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"但是为了启迪群众，使他们相信工人阶级政党的政治路线是正确的，为革命作准备，光靠宣传是不够的。列宁说，为了准备革命，“……将是以群众本身的政治经验来消除各种可能产生的错误和幻想。”（出自《在全俄工兵代表苏维埃第一次代表大会上的讲话》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-262","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":262,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"宣传只有和革命行动一起进行，才能起作用，才能达到目的。没有行动，思想就会枯萎。这种活动不是也不可能是一种冒险，而是刻苦的斗争，是同阶级敌人的激烈冲突，是从简单到高级的斗争，是克服无数困难，接受革命要求的一切牺牲的斗争。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-263","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":263,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"真正的马列主义政党站在革命行动的前线，而不是末尾。对资本主义反动派巨大的力量——它们必须而且确实反对的——的斗争和努力的暂时效果有限的可能性，并不使他们气馁。它们教导党员要有勇气，要牢记，一个正确的、周密的、成熟的、坚决的行动，在看到和听到这些的群众中有着深刻的影响。共产党人这样做，群众就认识到，这场或那场革命的目的是为了无产阶级和被剥削者的利益。行动上的勇气和成熟是非常重要的，因为这样，一点一点地取得了进展，打下了基础，建立了革命的高潮。革命行动把工人阶级政党同群众联系起来，使他们走到群众的前列，使他们战胜了改良主义、修正主义政党。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-264","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":264,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“一步实际行动，”马克思说，“比一打纲领更重要。”（出自《哥达纲领批判》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-265","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":265,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"除了马列主义政党领导的革命力量之外，资本主义国家还有其他与警察、宪兵等斗争和冲突的力量。这些部队的许多行动和袭击都具有恐怖主义、冒险主义和无政府主义的特点。它们以各种颜色和标签呈现，并以各种意识形态为指导。这些行动通常是在受教唆以及受资本主义国家秘密组织的基金支援的，此外，目的是通过将这些行为归咎于马列主义政党来诋毁它们。法西斯分子或者资产阶级的特务，经常组织领导这些行动，企图利用无产阶级、中小学生和广大青年的不满、愤怒和勇气，使这些群众中涌现出的各种团体和运动参与到同真正的革命运动既没有共同点，又严重危害革命运动的行动中去，造成无产阶级正在退化，已经成为愚蠢的无产者的印象。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-266","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":266,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党要对这个问题足够重视，一方面，必须用自己的经验说服群众革命行动与恐怖主义和无政府主义的行动完全不同，另一方面，要争取被欺骗的人成为革命分子，让他们远离恐怖分子、无政府主义者的行列，远离法西斯分子、资产阶级特务。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-267","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":267,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党是革命的政党。与完全深陷于资产阶级合法性中的和“议会迷”的修正主义政党的理论和实践相反，他们没有把斗争简单地削减为合法斗争上去，也没有将合法斗争看作是他们的主要活动。在掌握着一切形式斗争的情况下，他们特别重视合法工作和非法工作的结合，并把非法工作放在第一位，作为推翻资产阶级的决定性因素和真正胜利保证。他们教育传授干部、党员和支持者，使他们懂得在合法和非法的条件下，如何聪明、熟练、果断地行动。但是，即使在艰深的秘密条件下，在避免向敌人暴露力量、保护革命组织不受敌人打击的情况下，马列主义政党也决不会把自己封闭起来，不削弱，也不打断与群众的联系，决不放弃在自身和客观条件允许的情况下利用各种合法可能性，来为革命事业服务。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-268","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":268,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在对走议会道路夺取权力的可能性不抱幻想的同时，马列主义政党也可以在特别有利的条件下，以宣传群众路线，揭露资产阶级政治秩序为唯一目的，考虑去参加地方议会选举、国会选举等合法活动。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-269","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":269,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在马列主义者的活动中，他们不担心用革命行动打破和违反资产阶级的宪法、法律、规章、规范和秩序。他们正在为破坏这个秩序，为革命做准备战斗。因此，马列主义政党要为自己和广大人民群众做好准备，以应对资产阶级在无产阶级和人民群众的革命行动中发动的反击。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-270","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":270,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"作为一个复杂的，有着广泛的社会基础，有着众多的阶级和政治力量参加的过程，在革命和解放运动发展的今天，无产阶级革命党面临在革命的这个阶段和那个阶段，在这些那些共同的问题上，同其他政党和政治组织的合作和共同战线的问题，并不少见。在这个问题上，正确的、有原则的，同时灵活的立场，并不搞机会主义和宗派主义，对于吸收、准备和动员群众进行革命和解放斗争，具有重要意义。在革命事业的利益需要和形势需要的情况下，马列主义政党不能且原则上不应反对同其他政党和力量的合作和共同战线。但是，马列主义政党从来没有把这看作是土著联盟，也没有把其本身看作目的，而是团结和发动群众斗争的手段。重要的是，在这些共同战线上，无产阶级政党决不能忘记无产阶级的阶级利益和斗争的最终目的，决不能溶解在共同战线中，而必须保持思想上的个性和政治上、组织上、军事上的独立性，必须争取在共同战线中发挥领导作用，在那里实行革命政策。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-271","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":271,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党要能够制定和运用革命的战略和策略以及正确的政治路线，知道如何在困难的情况下找到克敌的方向，克服障碍，就必须进行伟大而广泛的斗争，同时学习和吸收马列主义理论。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-272","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":272,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"资本主义国家的前共产党之所以变成修正主义政党，一个原因就是他们完全忽视了对马列主义的学习和吸收。马列主义只是作为一种装饰，变成了空话和口号，没有深深地植入党员的意识，没有成为党员血肉的一部分，没有成为行动的武器。为党员学习马列主义所做的那一小部分工作，只不过是为了使他熟悉一些老生常谈的公式，这足以使他称自己为共产主义者，感情用事地热爱共产主义，至于怎样、以什么方式实现共产主义，他一无所知，因为他没有被被教过。这些政党的领导人不缺言语，缺行动，生活在资产阶级的环境中，用自由主义和改良主义的思想感染了他们国家的无产阶级。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-273","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":273,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，修正主义政党向资产阶级的转变，是一种社民主义、机会主义的演变，它的领导人早就准备好了，这些领导所谓共产党的领导人实际上就是社民派、工人贵族。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-274","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":274,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义政党不能不记住负面教材，并从中吸取教训，必须在良好的基础上组织学习和吸收马列主义，始终把学习和革命行动联系起来。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-275","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":275,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"各国马列主义政党在无产阶级国际主义原则基础上的团结与合作，对于革命的准备工作具有特别重要的意义。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-276","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":276,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"在反对帝国主义和社会帝国主义，反对各种资产阶级和现代修正主义，反对赫鲁晓夫主义、铁托主义、“欧洲共产主义”、中国修正主义等方面，这种团结和合作将进一步扩大。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-277","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":277,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"修正主义者作为革命的敌人，用一切力量和手段同无产阶级国际主义作斗争，以便在世界无产阶级反对资产阶级和帝国主义的斗争中，从各国无产阶级手里夺取这一有力武器。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-278","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":278,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"不遵循无产阶级国际主义原则，不支持民族革命和解放斗争的中国共产党，同包括极右派和反动派在内的社会民主党派和资产阶级政党走上了和解友好的道路。同时，它正试图创建依赖于它并由它指挥的各种集团。它需要这样的集团，正是为了破坏真正的马列主义政党和那些致力于唤醒人民、鼓动人民进行革命以反对与超级大国有联系的统治集团的进步分子。这些自称为党，尾随中国路线的小集团，作为机会主义者，除了保卫和宣传华国锋、邓小平集团的修正主义理论和反革命行动外，什么也不做。这些团体完全没有自己的个性，没有按照马列主义理论进行斗争的决心。这些政党的主要口号，也是中国政策的基本口号，就是在目前的情况下，无产阶级的唯一根本任务和角色，就是保卫民族独立，宣称民族独立仅仅受到苏联社会帝国主义的威胁。他们几乎一个字一个字地重复着第二国际领袖们的口号，这些第二国际领袖放弃了革命事业，取而代之的是保卫资本主义家园的论调。列宁揭露了这种错误的反马克思主义的口号，即其不是为了保卫真正的独立，而是为了煽动帝国主义之间的战争。他对帝国主义集团之间的冲突，明确地解释了真正革命的立场。他写道：","language":"中文","translation":false},{"id":"hoxha-imperialism-3-279","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":279,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“如果这场战争是反动的帝国主义的战争，就是说，是由帝国主义的、强暴的、掠夺成性的反动资产阶级的两个世界集团进行的战争，那么任何一国的资产阶级（甚至小国的资产阶级）都成了掠夺的参加者，而我的任务，革命无产阶级的代表的任务，就是准备世界无产阶级革命，因为这是摆脱世界大厮杀惨祸的唯一出路……","language":"中文","translation":false},{"id":"hoxha-imperialism-3-280","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":280,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这才是国际主义，这才是国际主义者、革命工人、真正的社会主义者的任务。”（出自《无产阶级革命和叛徒考茨基》——译者注）","language":"中文","translation":false},{"id":"hoxha-imperialism-3-281","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":281,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"走中国路线的政党，以保卫民族独立的必要性为借口，成为资产阶级军队发展壮大的辩护者。他们号召劳动人民做顺从的士兵，同资产阶级联合起来，并且他们反对一切要削弱资本主义统治和剥削的这一主要武器的人。总之，他们希望无产阶级和劳动群众在帝国主义和社会帝国主义预备的掠夺性战争中充当炮灰。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-282","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":282,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"同时，这些中国人的附庸也成为他们认为是“捍卫独立”的主要因素的资产阶级资本主义国家制度，特别是北约、欧洲共同体等等的坚定捍卫者。和中国领导人一样，他们粉饰和美化了资本主义统治和扩张的这些支柱。他们正是在帮助那些实际上严重侵犯他们国家独立和主权的组织。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-283","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":283,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这些没有前途的群体的这些立场，正使他们走向同欧洲共产主义和资产阶级政党的合一，这是必然的，因为中国本身就是在号召无产阶级同资产阶级联合起来。这些伪马列主义者和马歇（当时的法共总书记——译者注）主义者之间已经没有任何区别了。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-284","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":284,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"马列主义者必须非常警惕现代修正主义者、社会民主主义者和伪马列主义者在无产阶级国际主义、无产阶级团结保卫和平等问题上使用的空话。当人们首先是在自己的国家自我牺牲地帮助和开展革命行动，创造真正的革命斗争局面时，这才是真正的无产阶级国际主义。同时，正如列宁所说，他们必须用宣传、同情心和物质援助，无一例外地支持各国的这种斗争和路线。他告诉我们，任何其他事情都是欺诈和马尼洛夫（此处霍查用《死魂灵》之典故，意指夸夸其谈——译者注）式的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-285","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":285,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"因此，我们必须非常警惕这种伪马克思主义、伪革命、伪国际主义的分子，不管是个人，还是小团体，还是实际上不是马列主义的，而是社会沙文主义、中派和小资产阶级的，自称马列主义的政党。所有这些拍着胸脯谈论无产阶级国际主义、保卫和平、改革等等的政党，都是为资本服务的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-286","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":286,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"中国修正主义者有时也谈论无产阶级国际主义，但他们站在民族主义和沙文主义立场上。中国领导人就是那些拍着胸脯，向上帝发誓拥护无产阶级国际主义，拥护和平，拥护无产阶级的斗争和主张，但实际上只会袖手旁观，用欺骗性的话分裂革命力量的人。马列主义政党所面临的重要任务是加强无产阶级国际主义，这种国际主义不论大小新旧，都必须在各党派中发展。他们必须加强团结，协调政治上的、思想上的和战斗上的行动。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-287","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":287,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"强调这一重要路线，是马列主义政党的首要任务，以便能够对世界资本主义及其奴役政策，以及它与苏联、铁托、中国、意大利、法国、西班牙和其他现代修正主义的阴谋、诡计和联盟发动正面攻击。强调这一路线，这些政党将建立一个强大的共同战线，并日益牢不可破。如果他们团结一致，共同打击反动派，揭露资本主义和现代修正主义为镇压革命、平息阶级斗争而以各种方式炮制的种种阴谋，他们的胜利是有保证的。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-288","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":288,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"我们马列主义者，无论工人在哪里，都要奋斗并号召他们同他们的宿敌作斗争，号召他们挣脱枷锁，进行革命，而不是像现代修正主义者所主张的那样服从于垄断者和资本家。马列主义者和真正的革命家的任务，是号召无产阶级和各民族为新世界、为他们的世界、为社会主义世界而奋斗。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-289","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":289,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“资本主义最终稳定论”、“人民资本主义”、“消费型社会”、“后工业社会”、“技术革命”、“防范危机”均为资产阶级首脑和其谋士炮制的学说和施政方针；","language":"中文","translation":false},{"id":"hoxha-imperialism-3-290","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":290,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“和平共处”、“没有军队、武器和战争的世界”为苏修在赫鲁晓夫时期提出的口号；","language":"中文","translation":false},{"id":"hoxha-imperialism-3-291","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":291,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"“带有人性面孔的社会主义”是南斯拉夫和欧共派的口号。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-292","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":292,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"1919年天主教民主党前身人民党成立，在法西斯统治时期被迫解散，1943年重建后成为意大利主要执政党；","language":"中文","translation":false},{"id":"hoxha-imperialism-3-293","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":293,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"1892年意大利社会党前身意大利劳工党成立，1895年改称现名，1922年被意大利法西斯取缔，1943年恢复公开活动，名为意大利无产阶级团结社会党。1944～1947年参加联合政府；","language":"中文","translation":false},{"id":"hoxha-imperialism-3-294","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":294,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"1947年意大利民社党从意大利社会党分裂出来。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-295","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":295,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"这三个党和陶里亚蒂领导的意共及其余一些小党如共和党等构成了意大利共和国的资产阶级秩序。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-296","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":296,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[3] 译者注：乔瓦尼·利昂纳（Giovanni Leone ），1908—2001，天民党人，1963年和1968年曾两度短暂出任意大利总理，1971年至1978年任意大利总统。1978年6月因被揭发有漏税等行为而辞职。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-297","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":297,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[4] 译者注：阿尔多·莫罗（Aldo Moro），1916——1978，天民党的重要领袖之一，两次出任意大利总理，1978年被极左组织红色旅绑架并于55天后杀害。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-298","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":298,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[5] 译者注：贝林格（Berlinguer Enrico)，1922——1984，1943年加入意共，1969年在意大利共产党第十二次代表大会上当选副总书记。1972年意共十三大起连任总书记。贝林格继承和发展了陶里亚蒂的右倾机会主义路线，先后提出历史性妥协和民主代替战略。是欧洲共产主义的倡导者之一。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-299","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":299,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[6] 译者注：阿明托雷·范范尼（Amintore Fanfani）1908——1999，天民党占主导地位长达三十多年的关键人物，历任意大利外交部长,，参议院议长和总理等职。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-300","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":300,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[7] 译者注：胡安·卡洛斯（Juan Carlos）1938—— ，1975年11月27日即位，成为西班牙王国的国王，是西班牙的国家元首，也是该国武装部队最高统帅。推动了西班牙向资产阶级民主制度的转型，2014年退位。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-301","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":301,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[8] 译者注：伊巴露丽（Ibárruri Dolores），1895——1989，1920年参与创立西班牙共产党，她常以“热情之花”为笔名宣传革命思想。1936年至1939年内战时期，她参与领导西班牙人民反对法西斯叛乱的斗争。内战失败后流亡苏联，1942年接替迪亚士任西共总书记，同年被选为共产国际执委会主席团成员，1960年起任西共名誉主席。1977年西班牙军事独裁者佛朗哥死后回国。后成为欧洲共产主义的支持者。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-302","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":302,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[9] 译者注：1967年11月3日,苏共领导勃列日涅夫在纪念十月革命五十周年的报告中宣布;发达的社会主义社会在苏联已经建成。他说,发达社会主义社会的建立,是苏联人民遵循列宁主义的方针,进行英勇和忘我劳动的结果。1971年他在苏共二十四大的报告中再一次宣布苏联建成了“发达的社会主义”。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-303","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":303,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"1945年日本投降后，朝鲜半岛以北纬38度线为界，分别由美苏两军接收。在美苏的各自支持下于1948年8月朝鲜半岛南部成立大韩民国（亦称南朝鲜或南韩），1948年9月朝鲜半岛北部成立朝鲜民主主义人民共和国（亦称北朝鲜或北韩）；","language":"中文","translation":false},{"id":"hoxha-imperialism-3-304","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":304,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"1945年的八月革命以来，北部的越南民主共和国被胡志明和越盟控制着，并开始作为一个独立的国家在国际社会上获得正式承认，首都在河内。南部则在保大帝皇帝的统治下成立越南国，通常被称为南越，首都在西贡。国际管制委员会成立以监督停火和实行日内瓦公约，其中包括定时举行越南普选。1956年，未能举行的选举结束了南北越的暂时分治，北部和南部都宣布独立，并展开冲突，并很快发展成越南战争。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-305","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":305,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[11] 译者注：印尼共产党，1914年东印度社会民主联盟成立，1920年加入第三国际。日本占领期间，一些党员投身于武装抗日斗争，一些青年党员与其他民族主义青年组织成员进行地下宣传活动 。1948年转为公开活动。1951艾地上台，在苏中两国的默许下推行和民族资产阶级代表人物苏加诺的统一战线政策，1965年9·30事件爆发，次年军事独裁者苏哈托禁止其存在，此后印尼共倒向苏联。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-306","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":306,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[12] 译者注：印度共产党，1920年成立共产主义小组，1933年12月建立全国性政党。1934年被宣布为非法。在第二次世界大战中支持英国反法西斯战争的立场，1942年获得合法地位。1946年7月在安得拉邦特仑甘纳地区开始了持续5年的农民武装斗争。1951年10月全国代表会议决定采取合法的议会斗争。1964年因路线之争公开分裂，以南布迪里巴德、孙达拉雅为首的一派另建印共（马），以党主席丹吉为首的一派仍沿用“印共”名称。此后两党又发生数轮分裂。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-307","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":307,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[13] 译者注：第二次世界大战结束后，在亚洲印支半岛发生了以越、老、柬三国以越南战场为主体的三次局部战争，印支三国人民击退了法帝和美帝的侵略，鼓舞了全世界人民的反抗，但三国领导人——首先是越南领导人被中、苏分化利用，陷入内斗和霸权主义的混乱中。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-308","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":308,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[14] 译者注：“门罗主义”，由1823年12月2日美国第5届总统J.门罗在国情咨文中提出，内容为：","language":"中文","translation":false},{"id":"hoxha-imperialism-3-309","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":309,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"（1）要求欧洲国家不在西半球殖民。这一原则不仅表示反对西欧国家对拉美的扩张，也反对俄国在北美西海岸的扩张；","language":"中文","translation":false},{"id":"hoxha-imperialism-3-310","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":310,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"（2）要求欧洲不干预美洲独立国家的事务；","language":"中文","translation":false},{"id":"hoxha-imperialism-3-311","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":311,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"（3）保证美国不干涉欧洲事务，包括欧洲现有的在美洲的殖民地的事务。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-312","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":312,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"并提出“美洲是美洲人的美洲”的口号；此举是美国对外扩张政策的重要标志。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-313","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":313,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[15] 译者注：美洲国家组织由美国和拉丁美洲的国家组成的区域性国际组织，其前身是美洲共和国国际联盟。成立于1890年4月14日，1948年在波哥大举行的第 9次泛美大会上改称现名。889年10月～1890年4月，美国同拉美17国在华盛顿举行第1次美洲国际会议，建立了“美洲共和国国际联盟”及其常设机构“美洲共和国商务局”。其在1948年通过，1951年正式生效的《波哥大宪章》，将原来的“美洲共和国联盟”改组为“美洲国家组织”；规定该组织的任务是巩固整个美洲大陆的“和平”与“安全”，安排共同行动以对付可能的“侵略”；对成员国间发生的政治、法律和经济问题寻求解决办法，等等。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-314","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":314,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[16] 译者注：原词foquist，衍生于西班牙语foquismo，似乎是卡斯特罗和格瓦拉创造出来的一种游击战理论。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-315","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":315,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[17] 译者注：阿戈什蒂纽·内图，Agostinho Neto，1922—1979，安哥拉人民解放运动党主席、安哥拉人民共和国第一任总统，作为安哥拉反殖民主义运动的创始人之一，两次被捕入狱、流放，越狱和逃亡。1962年当选为安人运主席，领导反葡武装斗争。1975年11月1日，安人运宣布成立安哥拉人民共和国，内图出任总统，宣布国家为一党制的社会主义国家。1976年内图领导的“安人运”，在苏联价值2亿美元武器的援助和万余名古巴军队的支持下，击溃“安解阵”部队，并将“安盟”部队逐出城市。使安哥拉成为在非洲的苏联模式桥头堡。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-316","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":316,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[18] 译者注：1975年，葡萄牙被迫承认安哥拉独立，但是美帝和白人南非扶植的安盟和安解阵对安人运开战，苏联和古巴则积极支持安人运反击，此后安哥拉爆发了长期的内战。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-317","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":317,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[19] 译者注：扎伊尔共和国，现名刚果民主共和国（刚果·金），1965年11月，国民军总司令蒙博托发动政变推翻卡萨武布总统，自任总统。蒙博托·塞塞·塞科，1930——1997，曾在比利时部队服役。1958年加入刚果民族运动党，1960年任陆军参谋长、晋升上校，同年在美国支持下发动军事政变，接管卢蒙巴政权，任国民军总司令，1965年再次发动政变推翻卡萨武布，自任总统，元帅。任内以“国有化”为借口，为自己的亲朋好友及亲信积累了大量财富。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-318","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":318,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[20] 译者注：谢里菲（Sherifian）王朝或者阿拉维（Alawiyya）王朝，摩洛哥阿拉伯人建立的伊斯兰教封建王朝(1666年～今)","language":"中文","translation":false},{"id":"hoxha-imperialism-3-319","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":319,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[21] 译者注：帕特里斯·卢蒙巴，1925——1961，1958年领导建立刚果（金）民族运动党，任主席。参加领导了1959年1月爆发的刚果人民反对比利时统治的民族独立斗争，被捕入狱。1960年6月刚果宣布独立后，任共和国总理兼国防部长。主张国家独立和统一，奉行反帝反殖和不结盟政策。1960年9月被军事政变推翻，后被捕遇害。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-320","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":320,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[22] 译者注：加丹加是中非高原的一部分，在刚果民主共和国东南部和赞比亚中北部，是世界闻名的铜矿带。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-321","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":321,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[23] 译者注：黄华，1913——2010，1976——1982任外交部长","language":"中文","translation":false},{"id":"hoxha-imperialism-3-322","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":322,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[24] 译者注：摩洛哥国王穆莱·哈桑，1929——1999，在法国获法律学位后，任王家武装部队司令（1955）和副首相（1960）。1961年在穆罕默德五世去世后继承王位。迄1963年他沿袭父王的独裁统治。1972年通过宪法，实行多党制，他于1974年开放党禁。在摩洛哥和阿尔及利亚之间关于西撒哈拉的斗争中，他宣传摩洛哥的领土要求，并于1975年11月发起10万非武装摩洛哥人的“绿色进军”，进入这一地区。1977年摩洛哥进行大选，支持他的人获得压倒多数的胜利。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-323","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":323,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[25] 译者注：皮诺切特（Augusto Pinochet），1915——2006，1951年完成学业后前往军校任教，1953年获少校军衔，1956年—1959年在厄瓜多尔从事学术研究工作，1960年出任智利陆军第七团团长，1963年出任战争学院副校长，1966年获上校军衔；1968年获准将军衔并出任第六师师长；1971年出任第二师师长并获得少将军衔；1972年出任陆军总参谋长；1973年8月出任智利陆军总司令，获上将军衔，同年9月11日发动军事政变夺权，政变后成立军事执政委员会并出任委员会主席，实行残酷的军事独裁并大力推进新自由主义改革。","language":"中文","translation":false},{"id":"hoxha-imperialism-3-324","author":"恩维尔·霍查","title":"帝国主义与革命·第一部分","location":"第三章 革命与人民","page":3,"paragraph":324,"url":"https://www.marxists.org/chinese/hoxha/1978/02-03.htm","text":"[26] 译者注：19世纪中期工人运动中的革命冒险主义的思潮。以法国布朗基为代表。主张依靠少数革命家的密谋活动来推翻资产阶级的统治，建立少数人的专政，从而过渡到共产主义。","language":"中文","translation":false},{"id":"zhou-unity-1-1","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"中文马克思主义文库 -> 周恩来","language":"中文","translation":false},{"id":"zhou-unity-1-2","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"团结广大人民群众一道前进","language":"中文","translation":false},{"id":"zhou-unity-1-3","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"（一九四九年四月二十二日）","language":"中文","translation":false},{"id":"zhou-unity-1-4","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"团结广大人民群众一道前进的问题，对党来说，就是党与非党人士合作的问题；对青年团来说，就是团员与非团员合作的问题。换句话说，也就是在广大人民中间，大家彼此怎样合作的问题。这是我们进行革命工作的一个很重要的问题。今天，我们要反对帝国主义和国内反动派，绝不是单靠共产党员、青年团员和干部所能做到的。今天，青年团员才二十万，连党员一共也不过三百万，比起全国人口四万万七千五百万来，这个数目是很小的，还没有达到百分之一。我们要带动全国人民前进，如果不同广大党外团外的人士合作，如何能做好呢！毛泽东同志在党的第七次全国代表大会上讲过，不要骄傲和急躁，要谦虚谨慎；同时，要团结广大的非党人士，要同党外人士合作。这几句话说起来容易，做起来就很难。党也好，团也好，过去都有这样一个不好的传统，就是一听说这个人是党员，是青年团员，就放心了，什么问题也没有了；一听说是非党员非团员，马上就另眼相看。这样来划一个鸿沟是非常危险的。因为不管是在工人中农民中和学生中，党员和团员总是少数，少数人自己划个小圈子把自己圈起来，用中国的古话来说，就叫“画地为牢”。","language":"中文","translation":false},{"id":"zhou-unity-1-5","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"有的同志以为党内的同志什么都好，其实并不如此。一个同志一旦入党，那只是他在组织上入了党，思想上还不一定完全入党。就拿我来说，我也是团员出身，后来转为党员的。我虽然有二十七八年的党龄了，还不是犯过许多错误，每次谈起来，总觉得自己对革命有所欠缺，总觉得工作做得不很好，不能满意。党内每个人都有长处，我们应该互相学习。党外人士也有许多长处，我们也应该向人家学习。每个党员都要长期锻炼，经过千锤百炼才能成钢，不是一下子就能成功的。首先在生活上思想上作风上需要长期的考验。所以，我们入党入团以后，要很好地学习，开展批评与自我批评，这样才能很好地前进。这是对党员团员起码的要求。党外团外的人，因为他们没有进党进团，当然有些事情不知道，比我们差一点，但并不是没有长处。比如在农村中，许多农民比我们勤劳勇敢，比我们有办法；在工厂中的广大工人，比我们能生产，比我们能创造；广大的劳动知识分子、学生，有的在许多方面比我们强。不过他们当中有些人觉悟得慢一点，或者一时还不愿意入党入团，我们要帮助他们，启发他们，把他们当作朋友看待，互相学习。不要因为他们不是党员团员就另眼看待，而一旦入党入团就什么都放心了，这种态度是幼稚的，这个毛病是青年人容易犯的。","language":"中文","translation":false},{"id":"zhou-unity-1-6","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"我们怎样解决这个问题呢？就是要在观念上，把党外凡是能够争取的、能够和我们合作的人士，当成党内干部一样来看待。我们先划一个最大的圈子，把亿万人民群众团结在一起，共同对付最反动的地主阶级和官僚资产阶级集团，孤立他们，反对他们，打倒他们。人民内部，当然还有不同的阶级和阶层，最跟我们接近的是工人、农民、学生和劳动知识分子，其次是小资产阶级，再次是民族资产阶级、开明士绅及其他爱国分子，我们要分别对待，争取他们，教育他们。共产党青年团要有这样的气概。我们今天是新中国的主人，不能讲起来是无产阶级领导的人民大众的政权，人民民主的国家，可是做起来却是一小圈圈人，不象个领导者，反倒象个孤立主义者，做的跟说的不一样。青年人一定要非常谦虚，不要骄傲，应该觉得自己差得很，事情还做得很少；同时，我们还要团结所有能够争取的人。这就是说，对自己应该自勉自励，应该严一点，对人家应该宽一点，“严以律己，宽以待人”。当然，这个宽不是没有原则的。我们首先是区别革命和反革命，对反革命不能存在任何幻想。我们这个大圈子，就是要把四万万七千五百万人中最反动的几万、几十万、百把万、几百万划出去。同时还要看到，这里边有许多人还可以改造，比如地富分子，一旦土地改革以后，经过三五年的教育、改造，他们是可以慢慢地改变的。当然，不是一下子能够做到，但是前途还是有希望的。我们要有步骤地去做，使他们参加生产，逐渐地改造成为新人，不是囫囵吞枣，一下子都混进来。但是，我们在精神上要有这样的气概，把他们都改造过来，领导起来。","language":"中文","translation":false},{"id":"zhou-unity-1-7","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"最近我们同国民党代表团〔440〕谈判。有的同志说，国民党代表团就那么几个人，费这样大的功夫，多麻烦！虽然是几个人，但是他们后边有一群。在他们影响下的军队、政府、党部里边的人以及公教人员，总有几百万，加上这些人家庭里的妻子儿女，就是千把万。对于这些人，他们讲的话比我们讲的影响更大一点。他们有代表性。争取几个头子就影响后边一批，有利于我们渡江，就是渡江以后也会发生作用。所以，对于反动营垒中可能分化出来的人物，要争取他们，教育他们，帮助他们。","language":"中文","translation":false},{"id":"zhou-unity-1-8","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"这样一想，我们就看得广了，不会把自己划在一个小圈子里边了。用这样的精神去做事情，才能团结更多的人和我们一道走，同时反过来，我们还跟他们学习。我们要知道，有不同的意见的人跟我们来讨论、争论，真理才能愈辩愈明。辩证法就它的希腊字源来说，意思就是进行论战，联共党史上不是也讲了这一件事情吗〔447〕？在历史上，许多哲学家、政治家也喜欢争辩。圣人都喜欢辩论，何况咱们后生小子乎！为了寻求真理，就要有争辩，就不能独断。什么叫独断？就是我说的话就对，人家说的话就不对，那还辩什么呢？你的意见是神圣不可侵犯的，那谁还跟你辩？即使自己有很多对的意见，但是还要听人家的意见，把人家的好意见吸取过来，思想才能更发展，辩证法就讲矛盾的统一，只有通过争辩，才能发现更多的真理。所以，青年人要学习，就要多听各方面的意见，然后加以集中。也有这样一种人，因为东听一句西听一句，把自己弄得惶惶无主，本来开始他还有主意，这样一听就失掉了主意。我们要听各方面的意见，但是还必须加以思考。一个人生着两个耳朵，能听话；生着两只眼睛，能看东西；生着两个鼻孔，能闻味。听话，能听正面的，也能听反面的；看颜色，能看白的，也能看黑的；闻味，能闻香的，也能闻臭的。所以，人体的机能也是合乎辩证规律的。我们必须听各方面的意见，辨别是非，从青年的时候起，就培养这样的思考力。还有这样的同志，见了党内的人和团内的人不怕，可是怕见生人，就象小姑娘一样。怕什么呢！我们应该去团结他们，教育他们，改造他们。有了这样的精神，在社会上才能团结更多的人一道前进。只有经常接近广大的群众，才能增加自己的勇气。一个人坐在房子里孤陋寡闻，这样不行，应该在千军万马中敢于与人家来往，说服教育人家，向人家学习，团结最广大的人们一道斗争，这样才算有勇气，这种人叫做有大勇。我们青年很需要养成这种作风。","language":"中文","translation":false},{"id":"zhou-unity-1-9","author":"周恩来","title":"团结广大人民群众一道前进","location":"团结广大人民群众一道前进（一九四九年四月二十二日）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/zhouenlai/056.htm","text":"＊这是在中国新民主主义青年团第一次全国代表大会上的报告第四部分的节录。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-1","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"中文马克思主义文库 -> 周恩来","language":"中文","translation":false},{"id":"zhou-intellectuals-1-2","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"（一九五一年九月二十九日）","language":"中文","translation":false},{"id":"zhou-intellectuals-1-3","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"北京大学教师学习会〔37〕和马校长〔38〕要我给他们做一个报告。我想，既然给北京大学讲，也就应该给别的大学讲。因此，我同教育部商量了一下，这个报告会就以北京大学为主，把北京、天津其他大学的教师和同学代表也请来了。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-4","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"我讲什么呢？做一般的政治报告吧，也许不适合大家的要求，因为大家正在进行思想改造的学习，这样的报告不是最需要的。既然在学习，就一定要下决心改造自己。因此，我想讲一讲关于知识分子的改造问题。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-5","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"讲到改造问题，我想还是先从自己讲起。我中学毕业后，名义上进了大学一年级，但是正赶上五四运动〔39〕，没有好好读书。我也到过日本、法国、德国，所谓留过学，但是从来没有进过这些国家的大学之门。所以，我是一个中等知识分子。今天在你们这些大知识分子、大学同学面前讲话，还有一点恐慌呢。不过，我总算是知识分子出身的，对知识分子的改造有一些体会，联系自己来谈这个问题，可能对大家有一点帮助，有一点参考作用，总不至于成为一种空论吧！","language":"中文","translation":false},{"id":"zhou-intellectuals-1-6","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"大家学习的目的是为了改造自己。我想，凡是要求学习的人，都应该有这样一个起码的认识。当然，改造需要时间，一下子要求很高、很快，这是急躁的，不合乎实际的。应该由浅入深，循序渐进。拿我个人来说，参加五四运动以来，已经三十多年了，也是不断地进步，不断地改造。也许有的同志会说：你现在担任了政府的领导，还要学习和改造吗？是的，我还要学习和改造。因为我不知道的事情还很多，没有明白的道理也很多，所以要不断地学习，不断地认识，这样才能够进步。三十年来，我尽管参加了革命，也在某些时候和某些部门做了一些负责的工作，但也犯过很多错误，栽过筋斗，碰过钉子。可是，我从不灰心，革命的信心和革命的乐观主义鼓舞了自己。这个力量是从广大人民中间得到的。我们应该有这样的态度和决心，即犯了错误，就检讨，认识错误的根源，在行动中改正错误。有了犯错误的经验，就可以少犯以至避免再犯同样的错误。当然不可能一次就改得好，犯了一次可能再犯，但总可以改正吧！犯了错误，不要当作包袱，要把它丢开。丢开了还不算，还应该公之于众，作自我批评。这不仅可以教育自己，同时也能帮助别人少犯这样的错误。也就是告诉别人：这类错误是可以改正的，只要认识了，同时又肯改，仍然是可以进步的。犯了错误，关起门来检讨是需要的，更需要的是到人民中去学习。一个人之所以犯错误，一方面是由于对理论、原则认识得不清楚，所以需要向进步的理论求教；另一方面是由于自己相信的那一点道理跟实际相矛盾，行不通，所以必须向广大群众求教，从实践中求得新的认识，发现新的道理。这样两方面结合起来，就有了力量，就行得通了，也就可以不犯或者少犯错误了。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-7","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"我讲这一段话，是为了使同志们在学习的过程中建立这样一个信心：只要决心改造自己，不论你是怎么样从旧社会过来的，都可以改造好。在座的同志多数在旧社会生活过较长时间，会带来很多旧的东西，要求一下子把旧的影响肃清，这是不可能的。只有在不断的斗争中，才能求得进步。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-8","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"下面讲几个大家在学习中可能遇到的问题，以及我对这些问题的认识。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-9","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"我们在学习和工作中，总有一个站在什么立场的问题。我们现在还不能说都已经站在工人阶级的立场上来看待一切问题、处理一切问题了。这不仅是你们诸位，就拿我来说，几十年以前就参加了共产党，是不是进了共产党之后工人阶级立场就那么清楚了呢？也许看书学习、写文章的时候是那样，但是到实践的时候，是不是办每一件事情都合乎工人阶级立场呢？认真检查起来，还是差得很远的。工人阶级立场不是从空中掉下来的，也不是自己封的，决定的关键是实践，只有实践才能证明是否合乎这样一个立场。例如，在第一次国内革命战争时期，我们把广大的中国人民组织起来了，首先是把工人、农民、学生和一部分军队组织到革命的潮流里，革命的力量推动他们前进。但是，到了一九二七年武汉时期，有些人在陈独秀〔40〕领导下，立场就很不稳了，跟着他犯了右倾机会主义的错误。这就说明他们没有坚定的工人阶级立场，受了当时反动阶级的影响。类似的例子还有。所以，立场问题不是一下子就能解决的。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-10","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"我国的知识分子，大部分是从地主阶级或资产阶级家庭出身的，不能要求他们一下子就能站到工人阶级立场上来。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-11","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"我的家庭是一个破产的封建家庭。我家原籍是浙江绍兴，后来祖父到江苏淮安做县知事，家也搬到淮安。我家虽然没有买土地，只有一幢房子，但仍然是封建官僚家庭，这样的家庭不能不影响我的思想。一个人幼年所受的影响，往往在他的思想上、生活作风上长期存在，说话或者写文章，如果不经过很冷静地思考，旧的东西常常会不自觉地流露出来。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-12","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"既然如此，要求知识分子一下子就有坚定的工人阶级立场，那是困难的，一定要有一个过程。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-13","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"一般的人开始最容易有一个民族观念、民族立场。因为中国是一个百年来受帝国主义侵略的半殖民地国家，所以容易使我们产生爱国的民族观念。例如，我小的时候读章太炎〔41〕先生发表在《国粹学报》〔42〕上的文章，当时虽然读不大懂，却启发了我的爱国的民族思想。中华民国成立以后，袁世凯〔43〕、北洋军阀〔6〕的专横卖国，更使我增加了爱国的思想，因而积极参加了反对“二十一条”〔44〕、反对中日军事协定〔45〕等爱国活动。我想很多人都有这样的过程。这是一个好的起点。知识分子有了爱国的思想、民族的思想，就可以从这个立场上前进。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-14","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"当然，这里面可能有危险性。假使从民族立场发展到国家主义〔46〕或狭隘的民族主义，对外侵略别的国家，对内压迫小的民族，那就走到邪路上去了。这种危险性虽然有，但于中国的知识分子来说，不是主要的方面。其原因在于中国是一个半殖民地半封建的国家，中华民族是受外国侵略、欺凌和压迫的，所以人们首先产生的是一种民族的反抗侵略的爱国主义。在这样一个具体的环境中，大多数知识分子的思想可以由民族思想、爱国思想发展到争取民族解放和为人民的思想。所以，知识分子初步有了这样的思想，应该受到欢迎。当然，我们也要防止产生国家主义或狭隘的民族主义的危险思想。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-15","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"在中国，国家主义是跟共产主义同时出现的。五四运动时的同辈们，今天在座的很多。大家知道，当时的少年中国学会〔47〕分成两派：以李大钊〔48〕、毛泽东同志为代表的一派，走向了共产主义；另外，曾琦〔49〕、李璜〔50〕、左舜生〔51〕等人又是一派，他们走向了国家主义，结果做了国民党的尾巴。这个尾巴做得也很可怜，因为在中国这个半殖民地的环境里，不可能出现土耳其式的基马尔主义〔52〕。狭隘的民族主义在中国是行不通的，只有极少数人玩弄那种货色，在大多数的知识分子中是生不了根的。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-16","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"一百多年来，帝国主义和中国的买办阶级、地主阶级勾结在一起，压在中国人民头上，形成一个半殖民地半封建的社会。毛主席在《论人民民主专政》中说，一百多年来，多少仁人志士想替中国人民找出路，如洪秀全〔53〕和孙中山的革命，严复〔54〕和康有为〔55〕的改良，在当时都是想把中国往前推进，但结果都失败了。中国既没有象法国大革命〔56〕那样把封建势力完全摧毁，也没有象日本那样发生了明治维新〔57〕。为什么？原因很清楚，各位教授先生最近参加土改〔10〕工作时看到了，中国的封建势力太大，地主和富农在中国农村中约占人口的十分之一。这些人散布在中国广大的土地上，压在农民头上，帝国主义就凭借着这些人统治中国。在中国的民族解放运动中，过去有些人企图走改良主义的道路，走旧的资产阶级革命的道路，但走不通，统统失败了，不能不找新的办法了。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-17","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"中国人民在第一次世界大战中更加觉醒了。俄国十月革命给了我们新的启示，使我们认识到要“走俄国人的路”。孙中山先生也提过“以俄为师”的口号。这样，中国第一次大革命就组织和发动起来了。许多知识分子从民族的立场进一步认识了人民的立场，觉悟到只有站在人民的立场上才能救中国，才最爱民族。因为封建经济束缚着中国广大农村的生产力，买办势力束缚着中国的民族工商业；国民党反动派集中代表了封建和买办势力，成为一种反动政治力量，他们依靠帝国主义，压在中国人民的头上。所以要求得民族解放，一定要有人民的立场，而不是只有笼统的民族观念。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-18","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"人民的立场，是不是进了共产党以后一下子就站稳了呢？不错，当着对敌斗争很激烈的时候，我们是很清楚的，对地主阶级、买办阶级和国民党反动派是坚决斗争的，这是站在了人民的立场。但是到抗日战争时期，我们要和国民党讲联合，共同对外，这时有一部分共产党员的人民立场就不那么明确了。你们从胡乔木同志著的《中国共产党的三十年》中可以看到，在抗日战争初期，毛主席坚决主张对国民党有联合有斗争，推动全面抗战，反对国民党不要人民的片面抗战，这是坚定的人民立场。但是有些共产党员，有时只注意联合的一面而忽略了斗争的一面，迁就了国民党，人民立场就不那么清楚了。一九三八年在武汉，曾发生过这样的错误。那时联合的工作是做了，但斗争不够。后来认识了这个错误，纠正了，到重庆、南京工作时就好一点了。这就是说，人民的立场，在共产党的领导人当中也不是一下子就完全站稳了的。大家看过毛主席《在延安文艺座谈会上的讲话》。那时在延安的文艺工作者读了很多书，又住过延安的学校，但还是有不少人没有站在人民的立场，所以毛主席在那篇讲话中就首先提出立场问题。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-19","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"现在，工人阶级有工人阶级的想法，农民阶级有农民阶级的想法，城市小资产阶级有城市小资产阶级的想法，资产阶级有资产阶级的想法，只要各个阶级存在，他们的不同立场就会存在。我们今天要求大家有一个共同的立场，这就是为绝大多数人民的最高利益着想的人民立场。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-20","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"由人民的立场再进一步站到工人阶级立场，那是更难的一件事。为什么要知识分子进一步站在工人阶级立场呢？因为工人阶级是最先进的，是为人民的，也是为民族的，将来要实现共产主义，使社会达到无阶级的境地。工人阶级的伟大就在于此。资产阶级不可能把所有的人都变成资本家。如果人人都当资本家，谁去做工人呢？如何积累资本呢？我参加共产党，最先就是这一句话说动了我，我也用这句话写过文章，向别人宣传过。为什么工人阶级是先进的？因为工人阶级可以使全世界的人都变成劳动者，使脑力劳动和体力劳动统一起来。工人阶级和共产党最本质的东西，是它能使全世界进到没有阶级、谁也不剥削谁的社会，别的阶级和政党都不能担当这个任务。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-21","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"对阶级立场问题，在知识分子中有几种认识。一种认识是：中国没有那么多的工人，产业工人不过三四百万，并且是从封建社会中生长起来的，或多或少地带有封建的影响，恐怕不会很强，怎么能领导全国呢？另外一种认识是：中国共产党里面，农民、知识分子出身的党员占很大的数目，怎么能代表工人阶级的立场和思想？是不是代表农民和小资产阶级的思想？还有一种认识是：知识分子加入共产党以后，实行党的口号、政策，他的一切就都站在工人阶级立场上了，就体现工人阶级的思想了。这三种想法都是错误的。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-22","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"我们认为，中国工人阶级尽管人数少，而且其中还有若干人受过封建的影响，但是只要积极工作，发展生产，跟世界上的工人运动的经验和先进理论相结合，这个力量就是无穷的。它是新生的力量，一定会发展壮大。一切新生的力量都是从小到大的。我们每一个人也是由幼年长大的，幼年的生长力是最强的。所以工人阶级在中国是有远大前途的。工人阶级能照顾全局的利益。将来在工人阶级领导下发展工商业，不仅对本阶级有好处，对农民有好处，对资产阶级、小资产阶级也有好处。为了更好地发展工商业，它要把重要的生产资料掌握在国家手里，逐步走入社会主义社会。也只有在工人阶级的领导下，根据它的思想，根据国家的物质条件和不断提高的生产能力，才可以使中国工业化，消灭阶级，实现共产主义。所以不能因为它人数少而忽视这个最可靠、最有希望、最大公无私的阶级。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-23","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"共产党内有大量的农民、小资产阶级出身的党员，他们能站稳工人阶级的立场吗？我认为，经过锻炼是可以站稳工人阶级立场的。工人阶级并不把它的立场私有，只要真正愿意接受它的思想，就可以站到它的立场上来。中国工人阶级也是从旧社会来的，不过跟知识分子不同，它经过现代化大生产的锻炼，体现了先进的思想和立场。知识分子的改造也要经过锻炼，经过学习，经过实践。知识分子到工厂去，到农村去，就是要学习工人阶级、劳动人民的思想和立场。这不仅是对党外知识分子说的，也包含党内的知识分子。梁漱溟〔58〕先生在一封信上说，过去认为共产党的领导人都是知识分子，党员很多是农民，大概你们是农民思想、小资产阶级思想吧？他这话有一半道理，就是一些共产党员如果不经过改造，是会有很多农民思想、小资产阶级思想的，但经过改造就会逐渐减少，工人阶级思想就会逐渐加多。毛泽东思想体现了中国工人阶级的伟大思想。即将出版的《毛泽东选集》第一卷，就是体现中国工人阶级思想的伟大著作。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-24","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"做了共产党员，是不是就一切都合乎工人阶级的立场和思想了呢？不是的。也许我们主观上觉得是为工人阶级了，但有时我们的工作犯了错误，实行的政策有了偏差，说明我们还不是真正站稳了工人阶级立场。这种情况是常有的。我们过去发生的右的或“左”的错误，就是离开了工人阶级立场对反动阶级迁就，或者是把自己这个阶级孤立起来。拿我个人来说，就有过多次这样的经验教训。正是因为有过这样的错误，才使自己受到更多的教育。工人阶级立场不是那么容易站稳的，需要长期地摸索、学习、锻炼。毛泽东思想是我们革命的指南针，但是单靠这个指南针还不行，还要有自己的革命实践。毛主席常说，任何一个人不经过自己的实践，碰过钉子，摔过跤，别人的经验对他总是作用甚小。自己实践的经验是最可宝贵的，最有用处的。所以共产党员也需要经过锻炼，而且是长期的锻炼。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-25","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"从民族立场进一步到人民立场，更进一步到工人阶级立场，大体上会有这么一个发展过程。要促进这个发展过程，推动知识分子的进步，防止这个过程中可能发生的各种偏差，逐步地解决立场问题。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-26","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"明确地认识了立场的发展过程，态度问题也就容易解决了。一个人生活在社会中，生活在世界上，对遇到的任何一件事情总会有一个态度。立场不同，态度也就不同。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-27","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"今天的世界上还有阶级存在，还有国家的对立。帝国主义侵略集团要统治全世界，尤其是美帝国主义，要把世界变成美国的世界。中国人民是深受美帝国主义帮助蒋介石大打内战之苦的，现在美帝国主义又侵入朝鲜，侵入我国的台湾。世界人民经过两次世界大战逐步觉醒了，社会主义国家和人民民主国家先后建立了，殖民地半殖民地国家的民族解放运动不断发展，帝国主义国家的人民也在逐步觉醒。全世界人民都不愿意再受帝国主义的剥削和侵略，不愿意再遭受战争的痛苦，要求持久和平。世界分成了两个阵线，这是客观形势发展的必然结果。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-28","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"对这样的世界形势，我们中国人民怎么能够不表明自己的态度呢？必须要有明确的态度。首先要分清敌我友，谁是我们的敌人，谁是我们的朋友。没有这样一个区分，那你是什么态度呢？难道你站到敌人方面去？当然，在中国还有站在敌人方面的反动分子、反革命残余分子，我们要肃清他们。但是，站在人民立场上的人，站在爱国的民族立场上的人，能不表明态度吗？所以，我们在学习时必须有敌我友的观点。全世界人民包含美国人民、日本人民在内都是我们的朋友，我们要争取他们。现在还被帝国主义欺压的殖民地半殖民地国家的政府，我们应该争取他们反对战争，赞成和平，即使是暂时的朋友，我们也要争取。一切国家，一切可以争取的政府，都应该争取，即使是中立，那怕是暂时的、在一个问题上的中立，对于人民来说也有好处。我们应该分清敌我友的界限。我们的敌人就是美帝国主义和它的同盟国家、帮凶国家的反动政府。我们的朋友遍及全世界，其中包含在某一个问题上一时的朋友。这样，我们人民的力量就壮大起来了。这是在国际上。在国内呢？这个问题已经清楚了。我们站在工人阶级立场上，首先应该巩固工农联盟，还要团结小资产阶级、民族资产阶级以及其他一切爱国分子。我们的敌人就是反动阶级，最集中地表现在国民党反动派残余集团上，还有一些反革命残余分子。在态度问题上，是不是还有保持中间的可能呢？应该说，基本上没有可能，尤其在国内更没有可能。因为胜败已经定下来了，人民已经当政了。难道今天还可能又站在蒋介石方面又站在中国人民方面吗？也许可以躲到香港去，但那是临时性的，最后态度总是要判明的。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-29","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"关于态度问题，我们历来主张靠自己觉悟。我举个例子，大家会清楚的。张伯苓〔59〕先生，晚年做了国民党政府的考试院长，重庆解放以后，开始有了觉悟，后悔了。以后他回到北京，又转到天津。他和我总算是师生关系了，也很接近，但是我丝毫没有勉强他写一个东西。以后他慢慢地认识了新中国，认识了人民中国的好处，开始跟我讲了一些他最赞成、最高兴的事，但是我仍然没有请他写个东西。我觉得一个人的进步要等他自觉地认识以后才最可靠。这样一耽搁，没想到他就年老病故了。临终前他写了一个遗嘱，大家可能在报上看到了。也许这是我的一个缺点，没有及早地帮助他提高觉悟。假使我知道他身体那样差，早一点提醒他一下，他也可能多一点进步表现，使人民对他有更多的谅解。这是我抱歉的地方。我再举一个例子：翁文灏〔60〕，大家也很熟悉，新华社宣布过他是战犯之一。但是他在欧洲表示愿意回到新中国来，无论如何也不愿意到美国去当教授。因为他有这样的表示，我们就欢迎他回来。他回来以后，有些朋友觉得他应该写一个声明，这样好使人民谅解他。但是我们仍然觉得不要太勉强，要他慢慢觉悟，自觉地写。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-30","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"真正的中间态度，基本上是不存在的，一个时期的动摇、怀疑是有可能的。有一种人他对新生事物要怀疑一下，观察一下，我觉得应该允许。怀疑并不等于对立。对立就是敌视新中国，这不能允许。在学习中，对某一个问题持怀疑的态度是可以的，因为真理并不是一下子就能被人们接受的。真理愈辩愈明，我们不怕怀疑。观察一下也是可以的。梁漱溟先生初到北京的时候跟我说，有些问题他要观察一下。他在这点上很直爽，我们也很尊重他，所以介绍他到各个地方去观察。他每次回来的确都有进步，这一点我们应该欢迎。他观察一个时期就提出一个新的认识，那很好嘛！观察不等于旁观，观察的态度是积极的，旁观的态度是消极的。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-31","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"还有一种态度是同情但不参加。这种人只是做到对中国革命表示同情，但是参加还要考虑考虑。这也是允许的。我们愿意等待，而且要耐心地等待。香港有许多人跟我们打过招呼，说他很同情新中国，但是他自己暂时还不能回来。我们绝不勉强。因为这里面还有客观的原因和主观的原因，我们应该谅解。","language":"中文","translation":false},{"id":"zhou-intellectuals-1-32","author":"周恩来","title":"关于知识分子的改造问题","location":"关于知识分子的改造问题（一九五一年九月二十九日）","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/zhouenlai/107.htm","text":"＊这是在北京、天津高等学校教师学习会上讲话的前两个问题。","language":"中文","translation":false},{"id":"zhou-peace-1-1","author":"周恩来","title":"和平共处五项原则","location":"和平共处五项原则（一九五三年十二月三十一日）","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/zhouenlai/113.htm","text":"中文马克思主义文库 -> 周恩来","language":"中文","translation":false},{"id":"zhou-peace-1-2","author":"周恩来","title":"和平共处五项原则","location":"和平共处五项原则（一九五三年十二月三十一日）","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/zhouenlai/113.htm","text":"（一九五三年十二月三十一日）","language":"中文","translation":false},{"id":"zhou-peace-1-3","author":"周恩来","title":"和平共处五项原则","location":"和平共处五项原则（一九五三年十二月三十一日）","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/zhouenlai/113.htm","text":"中印两国的谈判在今天，十二月的最后一天，开始了。我们说过要在一九五三年开始这一谈判，现在实现了。","language":"中文","translation":false},{"id":"zhou-peace-1-4","author":"周恩来","title":"和平共处五项原则","location":"和平共处五项原则（一九五三年十二月三十一日）","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/zhouenlai/113.htm","text":"我们相信，中印两国的关系会一天一天地好起来。某些成熟的、悬而未决的问题一定会顺利地解决的。新中国成立后就确立了处理中印两国关系的原则，那就是互相尊重领土主权、互不侵犯、互不干涉内政、平等互惠和和平共处的原则。","language":"中文","translation":false},{"id":"zhou-peace-1-5","author":"周恩来","title":"和平共处五项原则","location":"和平共处五项原则（一九五三年十二月三十一日）","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/zhouenlai/113.htm","text":"两个大国之间，特别是象中印这样两个接壤的大国之间，一定会有某些问题。只要根据这些原则，任何业已成熟的悬而未决的问题都可以拿出来谈。","language":"中文","translation":false},{"id":"zhou-peace-1-6","author":"周恩来","title":"和平共处五项原则","location":"和平共处五项原则（一九五三年十二月三十一日）","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/zhouenlai/113.htm","text":"＊中国政府代表团和印度政府代表团就中印两国在中国西藏地方的关系问题，于一九五三年十二月三十一日至一九五四年四月二十九日在北京举行了谈判。这是周恩来同志在谈判开始时同印度政府代表团谈话的一部分。这五项原则后来正式写入双方达成的《关于中国西藏地方和印度之间的通商和交通协定》的序言中。一九五四年六月下旬，周恩来同志访问了印度、缅甸。在中印和中缅会谈联合声明中，中印、中缅共同倡导了和平共处五项原则。","language":"中文","translation":false},{"id":"ho-colonialism-1-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-1-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"1914年以前，他们不过是些下贱的黑人、下贱的安南人，最多也不过是些只懂得为我们的统治老爷拉黄包车、挨鞭子的人而已。可是那一场“快活”的战争一爆发，他们就立刻变成了我们“仁慈”“贤厚”的官老爷们、甚至大小总督们的“宠儿”和“好朋友”了。真是平地一声雷，他们（土著）突地被安上一个顶崇高的称号：“保卫公理和自由的战士”。可是这个突如其来的荣誉，却使那些土著付出了一笔好大的代价。因为，为了保卫一个他们一点也不能享受到的“自由”和“公理”，他们却必须仓促地离开妻子、儿女、羊群和田地，而远涉重洋，到欧洲各战场去抛头颅、晒白骨。在远渡重洋的当儿，许多人就尝到水雷的奇妙表演，于是，他们便遨游海底，保卫龙王的祖国去了。另一些人则在诗情画意的巴尔干沙漠上丧了命，临死之前这样自问：“母国”是否要独霸土耳其王的后宫佳丽？（否则干嘛叫他们到这样遥远的地方送死？）还有一些人则在马恩河畔或在香槟区的沼泽地带英勇牺牲。他们用自己的鲜血染红了指挥官们脖子上的月桂花环，用白骨刻成了统帅们手中的司令杖。","language":"中文","translation":false},{"id":"ho-colonialism-1-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"最后，还有一些在后方可怕的兵工厂里整天辛苦劳作的人，尽管他们不用嗅到“蛮子”（Boches）们的毒气，可是却同样呼吸了法军的火药气，因而这些可怜的人，也是把肺叶一块块呕出来的，这和中毒气又有什么不同呢？","language":"中文","translation":false},{"id":"ho-colonialism-1-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"七十万土著到了法国，其中，有八万人永远不能看到祖国、故乡的太阳了。","language":"中文","translation":false},{"id":"ho-colonialism-1-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"有一位同行的朋友这样告诉我们：印度支那无产者，一贯受着各种各样苛捐杂税的巧取豪夺，官老爷们强迫他们购买白酒和鸦片，而自1915、1916年以来，他们又多受了一桩强拉“志愿军”的苦头。","language":"中文","translation":false},{"id":"ho-colonialism-1-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"几年来的变故，为那些在全印度支那进行大量搜刮人力的人制造了一个借口。被拉去的人都监禁在兵营里，他们被安上各种各样的名称，什么“民兵”、“专业工人”、“非专业工人”……等等。","language":"中文","translation":false},{"id":"ho-colonialism-1-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"根据有权在欧洲使用黄种人人力者的客观评论称，若与运载他们、养活他们的巨额支出比起来，这些人力的使用，可没有带来什么相应的结果。","language":"中文","translation":false},{"id":"ho-colonialism-1-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"后来，被当时人们叫做“招募志愿军”（这个名词包含着一个可怕的讽刺意义）的这桩搜刮人力的勾当，便带来了许多肆无忌惮的滥用权力的罪行。","language":"中文","translation":false},{"id":"ho-colonialism-1-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"招募志愿军的花招是这样进行的：那位“省皇帝”——在印度支那的每一位驻节官的确都是省皇帝——向他手下的官吏们下命令，务必在一定的时间里面，上缴足够的一定人数。官吏们就依照这道命令，任意想出一套办法。他们钻门子的办法，尤其是在搜刮金钱方面，应该说真的了不起。","language":"中文","translation":false},{"id":"ho-colonialism-1-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"最初，他们把一些健壮的、穷苦的人抓去，这些人就注定要牺牲了，他们是求救无门的；接着，才轮到大户的子弟。这些人中，若是有谁固执不从，那么，人家便会立刻乘机找他或是他的家庭的麻烦。如果必要的话，还可以把他关起来，直到他被迫决定在两条路中选它一条：“或者是当志愿军去，或者是拿出钱来。”","language":"中文","translation":false},{"id":"ho-colonialism-1-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"被拉者的情况如此，他们对这种强套在脖子上的“行业”当然说不上兴高采烈。因此，才踏进兵营里，他们就已准备伺机溜走。","language":"中文","translation":false},{"id":"ho-colonialism-1-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"另一些人，则认为自己无法摆脱命运多舛的簸弄，因而想尽办法，使自己身染痼疾。摧残身体最普遍的方法之一，是把各种各样的毒物，从生石灰到花柳病的毒脓都抹进眼睛里，使眼睛出脓害病。","language":"中文","translation":false},{"id":"ho-colonialism-1-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"虽然如此，但印度支那政府在许下给那些死里逃生的“志愿军”及“为祖国”而牺牲者颁赐和追赠品衔之后，仍在各号召书中如此大声宣扬：","language":"中文","translation":false},{"id":"ho-colonialism-1-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"“你们已经成群结队地去从军，毫不犹豫地离开你们多么亲爱的故乡。你们，是民兵的，都愿献出你们的血肉；是工人的，都愿献出自己劳动的双手。”","language":"中文","translation":false},{"id":"ho-colonialism-1-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"可是，既然安南人民真是如此踊跃地去当兵，那为什么被拉去的人，有的被绑着双手，解上省会，有的则在等着下轮船时，被关进西贡（Saigon）的一所中学堂，周围有法军看守，刺刀出鞘、子弹上膛呢？在柬埔寨（Cambodge）流血的示威，西贡、边和（Bienhoa）及其他地方的事变，是否表示着“成群结队”、“毫不犹豫”地欣然从军呢？","language":"中文","translation":false},{"id":"ho-colonialism-1-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"那些逃避兵役和开小差的事件（在后备军中占50%）都被武力镇压下去。他们的镇压引起了兵变，而兵变被摁进血泊里去。","language":"中文","translation":false},{"id":"ho-colonialism-1-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"在号召书中，印度支那政府并没有忘记提到这一点，就是说，为了不负政府一片“显著仁慈”和“仁厚”的好意，那么，“你们（即印度支那的士兵）必须懂得做人的道理，不应该有任何使人遗憾的事情发生”。","language":"中文","translation":false},{"id":"ho-colonialism-1-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"至于那位印度支那总指挥，则又有别有一种提防的办法：他用一种硝酸银的化学物，在每一名新兵的背上、手腕上刺上编号，任你怎么擦也擦不掉。","language":"中文","translation":false},{"id":"ho-colonialism-1-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"这里，像欧洲一样，一些人的穷困是另一些人的生财之道。那些佩肩章的专业军人，凭着他天大的好运气，被调来这里选募和组织新兵，他们是以能够越远、越久地避开欧洲的危险战场，就越心满意足的；那些承包伙食的老板，则从饿瘪了肚子的穷苦的新兵身上，大发横财；那些独揽物资供应者，则与募兵人员互相勾结，贪污舞弊。","language":"中文","translation":false},{"id":"ho-colonialism-1-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"除此之外，还加上另一种“志愿”，那便是志愿购买公债。推销公债的办法也不外如此，就是说，谁有油水可揩，就掏谁的腰包，哪个固执不听话，就先对他进行劝诱，劝诱不成，就来强硬的一手，直迫得他购了公债，方肯罢休。","language":"中文","translation":false},{"id":"ho-colonialism-1-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"在印度支那购买公债的人，多半不晓得它的什么财政规定，他们把购买公债看成是缴纳一种新的税务，而把公债券看成是一种纳税的收据。","language":"中文","translation":false},{"id":"ho-colonialism-1-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"现在，我们再看一看其他殖民地是怎么样进行招募志愿军的。","language":"中文","translation":false},{"id":"ho-colonialism-1-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"我们拿法属西非（Afrique-occidentale）来当例子吧：","language":"中文","translation":false},{"id":"ho-colonialism-1-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"这里，殖民主义的军官们，带兵到每个村落里去，把当地的长老抓了，强迫他立刻缴纳他们所要招募的一定的兵额。有一个军官，由于他想出一个办法，即把逃走者的亲人抓来虐待、拷打，使那些逃走了的塞内加尔（Sénégal）青年不得不又回来戴上殖民主义者的军帽，而被誉为有办法的人。这个家伙把老大爷、老大娘、孕妇、姑娘们都脱的精光，然后，把全部衣服都在他（她）们面前烧毁。这些受害者被反绑着双手，赤裸着身子，在鞭子不停地鞭策下，被迫快步跑过各个村落“示众”！有个身上背着孩子的大娘，她捣蒜般地叩头哀求，人们才允许给她解开一边手，好托住背上的孩子。在跑步中，两位老人因为饿得不行，昏倒下去；很多小姑娘因为受到这种野蛮行为的折磨，虽然还没到行经的年龄，却突然行经了；有位孕妇流产了，婴儿一出世就死掉了；另一个妇女则生了个瞎眼睛的娃娃。","language":"中文","translation":false},{"id":"ho-colonialism-1-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"拉壮丁的办法实在是应有尽有。","language":"中文","translation":false},{"id":"ho-colonialism-1-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"下面的这个办法算是特别迅速、省事：","language":"中文","translation":false},{"id":"ho-colonialism-1-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"他们用绳子在进出村子的要道两端一横，那么住在两根绳子中间的所有黑人，就被看成是正式从军了。","language":"中文","translation":false},{"id":"ho-colonialism-1-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"有位亲眼见证过这些事情的人，给我们这样写道：","language":"中文","translation":false},{"id":"ho-colonialism-1-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"“1925年3月3日晌午，鬼子兵把吕菲斯克（Rufisque）和达喀尔（Dakar）各个海港的要道包围起来，他们把所有在里面干活的人都抓起来。被抓的人好像对于去保卫文明这桩事儿不太感兴趣，于是，他们立刻被请上车子，并送进了监牢。他们必须呆在那儿，直到改变了主意之后，人们才从监牢里面把他们送到兵营去。","language":"中文","translation":false},{"id":"ho-colonialism-1-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"在兵营里，当他们参加了一些充满着‘爱国精神’的仪式之后，二十九名志愿军被宣传为是即将到来的最后战役的英雄……。而现在，他们都热衷于要把鲁尔区拿下来献给‘母国’。","language":"中文","translation":false},{"id":"ho-colonialism-1-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"可是，根据曾经熟识他们的芒让将军（Mangin）称，他们不过是些‘活不到冬天’的军队。”","language":"中文","translation":false},{"id":"ho-colonialism-1-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"眼下，我们手里还有一封信，是达荷美（Dahomey）的一个土著寄来的。他原来是一名退伍军人，曾经在“为公理而战”中完成他的“义务”。把这封信摘录它一两段，便将揭穿一个事实，让大家看到，人们是怎么样保护“巴图阿拉们”（Batouala）的；同时，指出殖民地的统治者怎样捏造出土著的忠诚，以此去粉饰他们所有公开的演说词，并好作为雷吉斯曼（Régismans）、霍德（Hauser）之流写新闻的题材。","language":"中文","translation":false},{"id":"ho-colonialism-1-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"那封信是这样写的：“1915年，当达荷美总督尼弗拉老爷（Noufflard）下令强迫募兵的时候，我的家乡就被警察和民兵劫掠和烧光。在那一次烧毁中，我的全部财产丧失殆尽。虽然如此，我仍然被迫入伍。尽管我是那一次卑鄙侵犯的受难者，但在法国的战场上，我依然完成我的义务。我是在埃纳河战役（Aisne）受伤的。","language":"中文","translation":false},{"id":"ho-colonialism-1-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"现在，战争就将结束，我也就要回国，可是，我再没有房屋、没有任何一点财产了。","language":"中文","translation":false},{"id":"ho-colonialism-1-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"下面签名的是我的同乡，他们和我同一天被迫入伍，房屋财产也被抢光烧光。（附上七个人的签名）","language":"中文","translation":false},{"id":"ho-colonialism-1-36","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"在尼弗拉总督老爷的这种军事成绩下，还有很多受难者，可是我不知道他们的名字，所以今天不能写给你……”","language":"中文","translation":false},{"id":"ho-colonialism-1-37","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"真的，威廉皇帝的“蛮子”们，其残酷也不过如此而已。","language":"中文","translation":false},{"id":"ho-colonialism-1-38","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"当大炮吃腻了黑皮肉、黄皮肉之后，我们当局的亲切言语也突地中断了，而黑人和安南人，也就自然而然地又恢复为“下贱的种族”了……","language":"中文","translation":false},{"id":"ho-colonialism-1-39","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"为了铭记安南兵的功劳，因此，在他们下轮船回国之前，在马赛（Marseille）那里，人家不是把他们所有的一切，如：他们刚自掏腰包买来的新衣服、钟表、各种各样的纪念品……都剥得精光吗？人家不是把他们交给一班禽兽去检查并无辜殴打吗？他们的食物不是像猪食一样吗？不是像猪一样给摆布在潮湿、空气不足、没有光线和床席的舱底吗？到了本土，他们受到一位知恩的官老爷的一篇如此爱国的演说词的“热烈欢迎”：“你们已经保卫了母国，这就好了！现在，我们再用不着你们。好，回去吧！”","language":"中文","translation":false},{"id":"ho-colonialism-1-40","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"这些“退伍军人”——说得更正确些，是剩下一把骨头的人——就这么在勇敢保卫“公理”和“正义”之后，带着形容枯槁之身，回到不知公理和正义为何物的殖民地制度下。","language":"中文","translation":false},{"id":"ho-colonialism-1-41","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"据印度支那各报刊的消息称，法国伤兵或死难者的妻子，都获得贩卖鸦片的营业执照。","language":"中文","translation":false},{"id":"ho-colonialism-1-42","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"这么一来，殖民地政府就在一件事情上，犯了两种无人道的罪行。一方面是，它们自己插手干着卑鄙的、毒害当地人民的行业，但仍不满足，它们还想把在这一次互相残杀中的那些可怜的受难者也拉进这个罪恶的深渊。另一方面，它们把被欺骗者的血肉和生命看得太不值钱了，它们满以为只要抛出一块烂骨头，就可以赔偿受难者的一只胳膊或她们亡夫的生命。","language":"中文","translation":false},{"id":"ho-colonialism-1-43","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"我们深信战争中的伤兵和寡妇，将会用脚踢开这一件肮脏的“礼物”，并鄙弃地唾骂它们，同时，我们还确信，文明的世界和善良的法国人民会站在我们的一边，并向那些为了搜刮民脂以饱私囊而毫不犹豫地毒害整个民族的殖民主义寡头提出控诉。","language":"中文","translation":false},{"id":"ho-colonialism-1-44","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"按照安南的习俗，每当村里有人死亡，乡亲们在磨谷舂米时，就都停止了歌声，不像往日那样。这是为了向死者的灵魂表示尊敬和对其家属志哀。可是人们以武力把所谓“现代文明”硬搬进我们的祖国，那还何必顾及这样的繁文缛节呢？请大家念一下登在《北圻日报》上的一则新闻就可全明白了：","language":"中文","translation":false},{"id":"ho-colonialism-1-45","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"为了给边和省阵亡的安南人建筑‘战士陵墓’，筹备一笔建筑资金，节日筹备委员会正在积极准备为大家贡献出一个绝妙的节目计划。","language":"中文","translation":false},{"id":"ho-colonialism-1-46","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"据说将有跳舞、集市、晚会等，总之，消遣的花样应有尽有，使谁都能够在为‘义举’而效劳中享受到‘盖世的快乐’。","language":"中文","translation":false},{"id":"ho-colonialism-1-47","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"驻扎在边和的飞行员曾经表示雅意，愿为这一联欢会助兴，同时，从现在起，筹备委员会可以肯定地宣布，西贡的高级官员也将莅临参加典礼，使节日更臻光彩、隆重。请允许我们向来参加盛会的西贡士女们报告一个消息：你们可以不必‘联欢’半途而回家进餐，因为筹备委员会已在这里安排好一个特别齐全的餐厅，烹饪技术精妙，任你胃口最难侍候的人，也将感到满意。","language":"中文","translation":false},{"id":"ho-colonialism-1-48","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"在将到来的正月二十一日，让我们每个人都到边和去吧，我们将参与勾魂摄魄的游艺，并有机会向边和的烈士家属表示我们感念到他们所受到的牺牲。”","language":"中文","translation":false},{"id":"ho-colonialism-1-49","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"果真的，什么样的时代，就有什么样的风俗。","language":"中文","translation":false},{"id":"ho-colonialism-1-50","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"但这种风俗是多么古怪啊！","language":"中文","translation":false},{"id":"ho-colonialism-1-51","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"有人还给我们念了下面这样的一封信：","language":"中文","translation":false},{"id":"ho-colonialism-1-52","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"……如果说，天下有过这样痛心而又荒唐的古怪事，那么，一定是强迫一个历来忍受着各种各样不公平、不正义的民族去参加‘公理’和‘正义’的大捷的联欢。而我们这里，就是这样做的！关于这个城市在11月11日那一天的各种节日的‘公共游艺’，我想不必向你赘述了，因为不论什么时候、什么地方都不过如此而已，提灯游行、放焰火、阅兵、总督府里的跳舞、赛花车、为国家募捐、广告、读演说词、宴会等。总之，在这出滑稽戏中，只有一件事——从人情方面说是值得注意的事——还叫我记得：像所有的地方一样，西贡人挺喜欢看电影，所以巴拉斯旅馆门前，就聚集了密密麻麻的人群，他们围看银幕上相继放映的‘滑稽大王卓别林’、‘阿飞’和‘光荣的丘八’。群众堵塞了交通，挤满了旅馆的前廊。这时候，旅馆的老板却不叫人们这样站在他店前的廊下，他挥舞着鞭子，没头没脸地抽打群众。老板娘也出来帮一手，尽往人多处打过去。也不知怎么的，几个眼明手快的小伙子一伸手，就把老板娘的鞭子‘抢’过去了。引得在场的人都哈哈大笑起来。老板怒冲冲的赶过来支援他的女人。这一回，他拿出一根手杖，雄赳赳地、不停地往人们头上打下来，这只手打累了就换那一只手。这些‘乡下人’被迫退下了马路，可是他还不饶人，沉迷在‘胜利’之中，这位‘可敬的法国人’又勇猛地赶过马路，把粗大的手杖，继续往那些可怜的土著头上、肩上、背上劈头盖脑地打下去。有个小孩子被抓到，立刻就被他结结实实地揍了一顿。”","language":"中文","translation":false},{"id":"ho-colonialism-1-53","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"当利奥泰元帅（Lyautey）一抵达卡萨布兰卡（Casablanca）后，他就对摩洛哥（Maroc）的法国占领军宣读了如下一道命令：","language":"中文","translation":false},{"id":"ho-colonialism-1-54","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"“法兰西共和国政府授予我最高军事荣誉，皆因诸位九年来无私贡献出血肉和牺牲的决心。现在，我们就将展开一次战役，以便完全平定摩洛哥，这是为了一个国家的忠实居民的共同利益，也是为了宗主国实现永久和平……。”","language":"中文","translation":false},{"id":"ho-colonialism-1-55","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"可是就在当天（4月14日），又有如下的一篇通告：","language":"中文","translation":false},{"id":"ho-colonialism-1-56","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"“在巴比特-哈尔巴（Babet-Harba）与贝尼布泽特部落（Beni Bou Zert）的交战中，我军阵亡二十九人，伤十一人。”","language":"中文","translation":false},{"id":"ho-colonialism-1-57","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"当人们想到必须用一百五十万劳动人民的血肉，才能造就六根“金杆”的元帅权杖时，那么二十九个无名小卒的死亡，比起元帅、总督老爷雄浑的言词来，又算得了什么！可是，那个民族自决权，整个四年来为它而互相残杀的民族自决权，老爷们却把它放到哪儿去了呢？老爷们的开化办法实在是稀奇古怪：要人家过文明的生活，却必须把人家先杀掉再说！","language":"中文","translation":false},{"id":"ho-colonialism-1-58","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"此刻，海防（Haïphong）的水手们也举行了罢工。星期四那天（8月15日）两艘运载安南民兵的海轮，即将起锚，前往叙利亚。","language":"中文","translation":false},{"id":"ho-colonialism-1-59","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"水手们不肯去，理由是，人家不用印度支那币（Piastre）给他们发饷。按照市价，印度支那币和法郎的汇兑率是一比十法郎，而不是两个半法郎。但是各航运公司却肆无忌惮地贪污，他们准备以法郎给水手们发饷，而不是像给职员那样用印度支那币发饷。","language":"中文","translation":false},{"id":"ho-colonialism-1-60","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"人家立即把所有的水手都从船上撵到岸上，然后把他们全抓起来。","language":"中文","translation":false},{"id":"ho-colonialism-1-61","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"可见黄皮肤水手的遭遇并不比黑皮肤水手的强。","language":"中文","translation":false},{"id":"ho-colonialism-1-62","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"我们极力反对把安南军队送到叙利亚去。是不是执政当局以为我们这些苦命的黄种弟兄，从1914到1918年以来，他们在各个“为文明和公理而战”的战场上，给杀得还不够呢？","language":"中文","translation":false},{"id":"ho-colonialism-1-63","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"我们的各位光荣的军人，习惯以踢屁股和鞭笞去“教育”土著。","language":"中文","translation":false},{"id":"ho-colonialism-1-64","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"可怜的纳洪（Nahon）就曾经被杀了两次，第一次是被维达尔上尉（Vidart）杀死的，第二次却是被一个专管验尸的、带着军医肩章的庸医杀的；这个家伙为了给他的朋友——凶手——开脱，便把纳洪的脑袋盗窃和埋藏起来，以便灭迹。呜呼！纳洪！可是在殖民地军阀手下遭殃的，又岂是纳洪一人而已！我们的一个同行朋友——他住在殖民地里——曾经告诉我另一个受难者的故事：","language":"中文","translation":false},{"id":"ho-colonialism-1-65","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"“这一回，事情发生在梅戎加雷（Maison-Carrée）的第五步兵团里。","language":"中文","translation":false},{"id":"ho-colonialism-1-66","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"受难者是一个年轻的士兵，他家在特内斯（Ténès），名叫泰里埃（Terrier），是1921年入伍的那一批青年之一。","language":"中文","translation":false},{"id":"ho-colonialism-1-67","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"其死亡过程尤为惨痛。8月5日，泰里埃前往团部医院去要点泻药，人家给他泻药，或者更确切地说，给了一种他以为是泻药的东西。他喝了药，几小时之后，肚痛得厉害，身体痉挛、打滚，接着就断了气。","language":"中文","translation":false},{"id":"ho-colonialism-1-68","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"泰里埃的父亲接到一封电报，通知他说他的独生子死了，并定于明天——星期天送殡。在这封电报里面，没有附带半句解释和安慰的话。","language":"中文","translation":false},{"id":"ho-colonialism-1-69","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"泰里埃的父亲悲痛已极，立刻到阿尔及尔去，并且找到了第五步兵团。在那里，他获知孩子的尸体放在梅若医院（hôpital Maillot）中。——为什么泰里埃的尸体给送到那里去呢？按照惯例，谁死了都得验尸的，是不是人家为了使泰里埃的尸体免于检验，所以把他送进医院去，借口病人是被送进医院后‘断了气’的？","language":"中文","translation":false},{"id":"ho-colonialism-1-70","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"到了医院，这位穷苦的父亲要求进医院看他孩子的尸体，人家告诉他：‘等着吧。’","language":"中文","translation":false},{"id":"ho-colonialism-1-71","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"等了好久，一名少校军医才出来告诉他，验尸结果没发现任何可疑的痕迹。说完，任由老人呆在那里，不允许他进去看望孩子的尸体。","language":"中文","translation":false},{"id":"ho-colonialism-1-72","author":"胡志明","title":"法国殖民制度的罪状","location":"第一章 血税","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/01.htm","text":"据最后的消息称，泰里埃的父亲好像曾到第五步兵团的上校指挥官那里去，打听泰里埃死亡的原因。这位指挥官告诉他说，他孩子是中毒死的！”","language":"中文","translation":false},{"id":"ho-colonialism-2-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-2-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"据前法国殖民地部部长、法国急进党党员、我们的可敬的萨罗老爷（Sarraut）说，他是土著的仁慈的父亲，他很爱安南人民，同时，也很受到安南人民的爱戴。","language":"中文","translation":false},{"id":"ho-colonialism-2-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"为了把大法兰西的文明传授给安南人民，我们的老爷——一名罪恶的魁首，是一个不择手段，连最下流、最卑鄙的手段都会干出来的人。这就是证据：萨罗老爷以印度支那总督的名义，给他的僚属寄了一封信，目的是为了塞满他自己和那些殖民地强盗的贪婪的口袋。那封信这样写：","language":"中文","translation":false},{"id":"ho-colonialism-2-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"我郑重地要求您，根据印度支那专卖总局局长的指示，尽力帮助专卖局增设贩卖鸦片和白酒的代理公司。","language":"中文","translation":false},{"id":"ho-colonialism-2-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"为使事情进行得顺利，谨寄给您一张列明必须设立代理公司的各乡名单。这些乡至今多半还完全没有鸦片和白酒。","language":"中文","translation":false},{"id":"ho-colonialism-2-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"通过那些高棉官员和乡长，您可以用您巨大的影响，使当地的小商贩看到多卖些白酒和鸦片是很能够赚钱的。","language":"中文","translation":false},{"id":"ho-colonialism-2-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"至于我们这方面，就让专卖局的职员在出差视察的时候，想办法设立零售店。如果驻节官先生需要等运动了地方官员之后，才让他们出巡，他们也将乐意等待。对此，我提议您乐意地告诉我。","language":"中文","translation":false},{"id":"ho-colonialism-2-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"只有我们同心协力，为了国库和最高利益，配合得紧密和连续不断，那么，我们才能够获得美满的结果。","language":"中文","translation":false},{"id":"ho-colonialism-2-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"当时，在一千个村落里面，就有一千五百间贩卖鸦片和白酒的商店，而学校却只有那么十所而已。在没有这一封著名的书信之前，人家就已每年往一百二十万人（包括男女老少在内）的肚里灌入二百二十万或二百四十万公升的白酒。这可不算少呀！","language":"中文","translation":false},{"id":"ho-colonialism-2-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"在垄断资本的眼中，印度支那如同一只被捆绑的雄鹿，在贪婪秃鹫的利喙下奄奄一息。","language":"中文","translation":false},{"id":"ho-colonialism-2-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"在白酒专卖公司中拥有股份的人，很多是印度支那最有势力的人物。所有统治部门在股份公司中都有其头面人物的代表。这些大官对公司多半很有好处，这是不容置辩的。","language":"中文","translation":false},{"id":"ho-colonialism-2-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"为了解决公司与人民的纠纷案件，司法部门的代表计有：","language":"中文","translation":false},{"id":"ho-colonialism-2-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"为了镇压反对专卖制度而可能发生的事变，军事部门的七名代表是：","language":"中文","translation":false},{"id":"ho-colonialism-2-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"行政部门的参加对经营的收获最具有保证：","language":"中文","translation":false},{"id":"ho-colonialism-2-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"最后是可尊敬的克莱门特老爷（Clémentel）——多姆山省（Puy-de-Dôme）议员。","language":"中文","translation":false},{"id":"ho-colonialism-2-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"在马赛举行的殖民地博览会（Exposition coloniale de Marseille）中，萨罗老爷曾经大声疾呼：“法兰西应该往这儿看，并应该以此而自豪！”果真如此。那些冷淡的突尼斯骆驼仁兄正在威武的西非鳄鱼老弟旁边打呵欠；那些可爱的马达加斯加鳄鱼老弟们，正和几头大模大样的印度支那水牛阿姐亲密地谈心，真的，从来没有过这样亲切的融洽。而传说中的马赛旧港（Vieux-Port）沙丁鱼姑娘，面对着殖民地兽类这样和平的涌现，她以一位好心肠的主妇，站着露出了可爱的笑容。","language":"中文","translation":false},{"id":"ho-colonialism-2-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"来参观的人，以饶有趣味的心情看着某一位总督的带有历史性的沙发；看着统使大人达尔斯（Darles）的一把剑，这把剑曾用来戳刺北圻（Tonkin）犯人的大腿；看着行政官老爷布鲁尔（Bruère）的一束火把，这一束火把曾经将胡阿萨（Houassas）的二百多名土著活活烤死。","language":"中文","translation":false},{"id":"ho-colonialism-2-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"喀麦隆馆（Cameroun）特别引起人们的注意。这里，在一块木板上写着如下几句爱国的标语：","language":"中文","translation":false},{"id":"ho-colonialism-2-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"“以前德国人向喀麦隆输入了很多酒。现在，法国人则在这里禁酒！”","language":"中文","translation":false},{"id":"ho-colonialism-2-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"可是，有一双机灵的手，在那块木板下面，贴上了萨罗老爷的公函，正是这封信指示他的下属应该在安南的各乡村，增设贩卖鸦片和白酒的代理公司。同时，附上批语：","language":"中文","translation":false},{"id":"ho-colonialism-2-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"“可是在安南呢，那儿的一千个村落里，就有一千五百间鸦片、白酒专卖局和那么十所学校呀！”","language":"中文","translation":false},{"id":"ho-colonialism-2-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"这是一名官员在山西省（Sontây）——北圻的一个省份——当地方长官之后的一件满有意思的故事。","language":"中文","translation":false},{"id":"ho-colonialism-2-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"这个省人口约有二十万。可是当必须增加白酒的销售量时，该省人口就像闪电一样快地骤增到二十三万。但这二十三万人依然喝得太少，所以山西省的驻节官大人就忙忙碌碌花了整整一年，终于把白酒的销售量增到五十六万公升。","language":"中文","translation":false},{"id":"ho-colonialism-2-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"我们的大人马上开了官，而且还获得奖励。","language":"中文","translation":false},{"id":"ho-colonialism-2-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"C先生说，有另一名驻节官把上级的一封信给他看，信里面有一段是这样写的：“按照人口平均计算，X府的白酒销售量已经比Z府的下降了。你可曾想到必须采用什么措施，以便为其它地方做出榜样？”驻节官被如此间接的警告之后，马上召集该府的豪绅，向他们分析，他们的白酒销售量这样少，原因是他们自己酿酒。为求得平安无事，各乡立刻按照人口买足规定数量的白酒（就是说，办事处为他们规定了应喝的数量）。","language":"中文","translation":false},{"id":"ho-colonialism-2-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"人家已经实实在在规定——不管合法不合法——每一个土著在一年中应喝的酒量。而每当人家说到每一个土著时，请不要以为人家只算的是成年人，而是算全部人口——从老大爷、妇女、孩子、直到吃奶的婴儿，这些人名下的酒，人家强迫他们的亲朋替他们喝下去。代喝的酒不只是一公升，而是两三公升。","language":"中文","translation":false},{"id":"ho-colonialism-2-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"有位北圻某乡的人，在恫吓之下，被迫必须喝酒。他曾向法国官老爷申诉：“我们连饭都没得吃呢。”","language":"中文","translation":false},{"id":"ho-colonialism-2-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"官老爷说：“你们一天惯吃三餐，现在只有减掉一餐，必要的话，就减它一餐半，以便能够购买国家的白酒。这不就行了。”","language":"中文","translation":false},{"id":"ho-colonialism-2-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"过去土著惯于随便拿个酒瓶去买酒，目的是为了能够少买一些。可是现在人家对酒瓶却规定了一定的容量，买酒的酒瓶的容量必须是一公升或半公升。安南人喜欢喝的是从二十到二十二度的酒，而现在，人家强迫他们喝的酒是从四十到四十五度的。过去他们喝的酒是用上等原料，用最好的米酿成的，味虽辣但甘甜可口；而今天，人家硬倒进他们口里的酒却是用便宜的大米，加上化学药剂酿成的，味道很难叫人喜爱。","language":"中文","translation":false},{"id":"ho-colonialism-2-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"专卖公司的老板们曾经发出一个通知，要他们的职员把水搀进酒里：在每一百公升酒里面，搀进八公升冷水。","language":"中文","translation":false},{"id":"ho-colonialism-2-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"这么算起来，全印度支那每天售出五万公升白酒，其中就搀进了冷水四千公升，每公升市价三角钱，每天四千公升就是一千二百元。而一个月则达三万六千元。这么一来，单只冷水，专卖公司每年就获得四十三万二千元，即四百万法郎的利润。","language":"中文","translation":false},{"id":"ho-colonialism-2-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"这么看来，就可以知道专卖者们在印度支那所售的白酒度数和味道，并不为印度支那人所喜爱，因此，人们就强迫他们购买。","language":"中文","translation":false},{"id":"ho-colonialism-2-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第二章 毒害土著","page":2,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/02.htm","text":"政府经常有紧急的开支，必须为总督府不断增长的经费付款；必须为借贷一项支出巨款；必须建设军事工程；为了供奉一大群硬从巴黎派来的公务员，即使没有实在的职务，也必须制定一项新的薪金科目。因此，政府想尽办法催促它的公务人员——从驻节官到最低级的执行人员——必须强迫人民多购买白酒。","language":"中文","translation":false},{"id":"ho-colonialism-3-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-3-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"（五）热雷米·勒梅尔老爷","language":"中文","translation":false},{"id":"ho-colonialism-3-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"富尔纳（Fourn）是达荷美的总督老爷。他的统治，“出色”得叫无论哪一个土著都对他怨恨已久。为了平息不满，人家就假情假意地派来了一位督察。这位督察“认真”检查一番后，竟连民众的申诉书都不看就卷起包袱溜之大吉了。","language":"中文","translation":false},{"id":"ho-colonialism-3-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"关于这个问题，我们收到从波多诺伏（Porto-Novo）的“法兰西—穆斯林行动委员会”寄来的一封信。信里有如下主要的几段：","language":"中文","translation":false},{"id":"ho-colonialism-3-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"“在法国人还没到达荷美之前，不论在什么环境下，波多诺伏很久以来就有一位被称作‘伊玛目’（Iman）的穆斯林领袖，他专管穆斯林团体的财产及料理祭祀事宜。","language":"中文","translation":false},{"id":"ho-colonialism-3-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"按照惯例，穆斯林伊玛目应由选民会议选出。选民会议在那些虔诚的、德高望重而又当过多年副职的人中，选出伊玛目。尤其是，在职的伊玛目，在他逝世之前，将提出意见，荐举一位够资格的副职以承继自己的职位。","language":"中文","translation":false},{"id":"ho-colonialism-3-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"这时候，伊玛目的意见是一个决定性的意见。","language":"中文","translation":false},{"id":"ho-colonialism-3-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"前任伊玛目卡苏穆（Cassoumou）在逝世之前，指定副手萨鲁库（Saroukou）为继位人。选民会议和大多数穆斯林都表示赞成。","language":"中文","translation":false},{"id":"ho-colonialism-3-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"卡苏穆逝世之后，照例应该是萨鲁库当选为伊玛目。可是伊格纳西奥·帕拉伊索（Ignacio Paraiso）这个东西，却凭借总督老爷的势力一意孤行，阻挠萨鲁库当选，同时，强迫穆斯林必须承认拉瓦尼·柯索科（Lawani Kossoko）那个家伙（他的朋友）为伊玛目。而柯索科和他都只是在口头上信奉穆斯林。","language":"中文","translation":false},{"id":"ho-colonialism-3-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"帕拉伊索看到穆斯林选民会议和多数选民起来反对非法推举柯索科一事，他马上拜托最高首领胡吉（Houdji）出面干涉。胡吉信奉的是与穆斯林迥异的拜物教。他倚仗政府势力，强举拉瓦尼·柯索科为伊玛目，完全不考虑穆斯林的愿望。","language":"中文","translation":false},{"id":"ho-colonialism-3-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"再说，如果拉瓦尼·柯索科是一个善良的穆斯林，那我们对这种‘推举’，也就姑且装聋作哑，无奈柯索科却是一个世间罕见的恶棍。我们这么说是有凭据的：","language":"中文","translation":false},{"id":"ho-colonialism-3-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"柯索科来自英属尼日利亚的拉各斯（Lagos），他是英帝国主义殖民地的人，因为在尼日利亚犯了杀人罪及其它许多罪恶，所以被英国殖民地当局通缉。","language":"中文","translation":false},{"id":"ho-colonialism-3-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"当时的达荷美总督老爷立即收容了这个英国殖民地的不法之徒，同时，还给他赏功似的派他到沿湖各乡，如阿弗托努（Affotonou）、阿盖盖（Aguégué）、阿格布兰坎坦（Agblankantan）等乡去当酋长。今天，这一带的人民，对他的卑劣和罪行，无不触目惊心和叫苦连天。","language":"中文","translation":false},{"id":"ho-colonialism-3-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"我们在属波多诺伏市的阿克帕萨（Akpassa）有一座清真寺。法国殖民地政权摧毁了这座清真寺，将其变作公共场所。对此，当局赔偿我们五千法郎。","language":"中文","translation":false},{"id":"ho-colonialism-3-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"赔款不足重建一座新清真寺。我们独自展开了一次募捐，得款二万二千法郎。在采购物资和支付工钱的小组委员会中，有帕拉伊索的一份儿。","language":"中文","translation":false},{"id":"ho-colonialism-3-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"副伊玛目比西里乌（Bissiriou）则掌管保险箱的钥匙。在他去世后，帕拉伊索立刻掌握了保险箱的钥匙，他利用这个地位，贪污了公款二千七百七十五法郎。采购物资小组委员会被迫只好把他撤职。","language":"中文","translation":false},{"id":"ho-colonialism-3-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"帕拉伊索恼羞成怒，立刻向总督老爷求援。于是总督老爷马上施行了一些对付我们的独裁措施，阻挠我们重建清真寺。","language":"中文","translation":false},{"id":"ho-colonialism-3-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"总督老爷在违反教规推举柯索科为伊玛目一事中，已经当了帕拉伊索的帮凶。由于帕拉伊索的阴谋，现在波多诺伏的穆斯林已经分成两派。这种情形，伤害了穆斯林的团结、伤害了我们的自由传教，和引起了大混乱的局面。”","language":"中文","translation":false},{"id":"ho-colonialism-3-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"下面是摘自伯纳德上校（Colonel Bernard）在1922年12月6日寄给《法兰西共和国报》一信中的几段文章。伯纳德上校是谁？——请放心，部长老爷，这位上校可不是个共产党人。那封信这样写：","language":"中文","translation":false},{"id":"ho-colonialism-3-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"“印度支那出口货的数字，不但正处于停滞之中，而且甚至仍在减少。1914年，印度支那出口蚕丝四万五千公斤、玉米九万九千吨、茶叶四百八十吨；而去年出口的蚕丝只有一万五千公斤、玉米三万二千吨、茶叶一百五十六吨而已。","language":"中文","translation":false},{"id":"ho-colonialism-3-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"人们还以为，目前印度支那政府正积极地进行着一些开发殖民地所必须的巨大工程。可是，从1914年至今，他们从没有铺设过一公里铁路，或开垦过一公顷荒地。十几年前，萨罗先生曾经向政府呈请通过一项建设计划，这项计划包括：铺设一条从荣市到东河（Vinh-Dôngha）的铁路，四个大型农田水利系统。五年多以来，所有这些工程都停了下来，借口是没有经费。可是，就在这一段时间里，印度支那政府却拿出六千五百万元（即四亿五千万法郎）去兴建大马路和官邸。请法格先生（Faget）想一想这个数字吧！兴修了小汽车跑的马路，这些马路却从没有运输过任何一吨货物；为了给那些不计其数的公务员——他们像热带茂密的树木一样正繁殖着——建筑官邸和公署，而花掉了近五亿法郎，可是，与此同时，那些被认为最需要、并且获得参议院通过的工程，却被搁置起来。","language":"中文","translation":false},{"id":"ho-colonialism-3-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"可是，请别以为人家有意要在印度支那改变什么方式。——为了完成1912年的计划，朗先生（Long）曾经向参议院申请允许发行公债。现在，他又作第二次发行公债的申请。目前，那些指挥开发印度支那的人，看起来已安了这样的心，如果人家不预先给他们贷款的话，他们是不会干出任何一件实在有益的事的。至于在战时或战后所积累的金钱，则如果参议院不使他们规规矩矩的话，他们是随时准备手一扬就把金钱抛到窗外去的。”","language":"中文","translation":false},{"id":"ho-colonialism-3-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"马达加斯加总督加尔比老爷（Garbit）刚回法国去。像所有同僚一样，这位老爷对“他的”殖民地的进步、富饶、忠诚、安居乐业、有秩序、有这个草案、那个计划……等等陈词滥调极为满意。这是每一位特命全权总督老爷的一个千秋万载、永恒不变的标准行囊，如今又被加尔比殷勤地展示给围观的观众们……。而在所有这一切老生常谈的吹嘘的手段上，加尔比老爷还极其巧妙地耍了另一套诡诈的花招（或者说，学了别人的诡诈花招），这一个诡诈的花招果然精妙无比，那就是所谓“开拓殖民地”。让我们欢迎刚回来的总督老爷吧，并允许我们这样询问阁下：","language":"中文","translation":false},{"id":"ho-colonialism-3-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"“据说殖民地部检察团的肥皂不太能够洗白总督老爷的头和润滑出一条安全通道，以便有朝一日，总督老爷在这方面失足好滚回宗主国去，并永远地、一生一世地呆在宗主国？","language":"中文","translation":false},{"id":"ho-colonialism-3-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"据说总督老爷的几名能干的走狗，为了挽救老爷的面子，而给老爷办了一席饯别酒宴？据说他们为了拉人凑数跑得浑身大汗，因为除了酒席筹备者外，连一个无聊鬼也不来参加宴会？","language":"中文","translation":false},{"id":"ho-colonialism-3-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"据说总督老爷的爪牙们准备呈文申请，要求再派他们所爱慕的总督老爷回来？可是又不敢把呈文公开，因为怕有什么指控的状子起诉？","language":"中文","translation":false},{"id":"ho-colonialism-3-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"最后，据说当地人民曾经对阁下说出了这样亲昵的临别赠言：‘得了吧，加尔比老弟！但愿永不相见！’”","language":"中文","translation":false},{"id":"ho-colonialism-3-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"“幸福”的是，二千万安南人民的命运掌握在马夏尔·梅林老爷（Martial Merlin）的手里。","language":"中文","translation":false},{"id":"ho-colonialism-3-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"你们将会问我：“这梅林老爷是谁呀？”他是这样一位老爷：曾经在甘比尔群岛（Iles Gambier）当过行政官老爷，后来，任法属西非副总督，最后，在那里升任总督；这位老爷在他自己的一生中，拿出三十六年的工夫，把法兰西的“文明恩泽”塞进土著的脑袋。","language":"中文","translation":false},{"id":"ho-colonialism-3-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"或许您会说，让一个对印度支那一无所知的人来统治这片土地，这简直是荒唐的印度支那滑稽戏吧！","language":"中文","translation":false},{"id":"ho-colonialism-3-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"没错！这是一种时髦的派头，有一位同行的朋友告诉我们说：在殖民地部里，任西非司司长的是前印度支那的一名行政官；相反地，前西非的一位统治老爷却负责赤道非洲司的职务；研究有关马达加斯加的各项问题却交给来自苏丹（Soudan）的一位官员负责；至于在殖民地博览会中，代表喀麦隆的人却又是一位从未到过喀麦隆的官员。","language":"中文","translation":false},{"id":"ho-colonialism-3-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"所以，在到印度支那去开化印度支那人之前，梅林就决定开始把那些死在法兰西的印度支那人——那些为“祖国”、为“公理”、为“文明”等等而死的人呀！——进行开化。","language":"中文","translation":false},{"id":"ho-colonialism-3-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"对那些“伟人们”来说，在乱葬岗里打哈哈，倒是一种乐趣，可是毕竟独乐乐不如众乐乐吧。为此，梅林大人就向那些受资助的安南留学生下了命令，要他们必须跟着大人到马恩河畔（Nogent-sur-Marne）的公墓去，在那里，在梅林老爷隆重的见证下，他们将宣读一篇演说词。可是在宣读演说词之前，必须先把它呈给总督大人检阅。他们已经照这么办了。总督大人检阅之后，认为演说词过激了，于是乎就把它撇掉，另换了一篇由大人亲手拟定提纲的演说词。","language":"中文","translation":false},{"id":"ho-colonialism-3-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"这一篇官方酱料烹制的演说自然充满了扑鼻的“赤胆忠心”。","language":"中文","translation":false},{"id":"ho-colonialism-3-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"如果死去的人真能如通灵者所言能开口说话，那么，葬在诺让（Nogent）的安南亡魂，一定会这么说：“总督大人呵！感……谢大人……可是请大人给我……滚蛋！”","language":"中文","translation":false},{"id":"ho-colonialism-3-36","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":36,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"（五）热雷米·勒梅尔老爷","language":"中文","translation":false},{"id":"ho-colonialism-3-37","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":37,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"我们在《殖民地年鉴》（Annales Coloniales）中读到下面这一消息：","language":"中文","translation":false},{"id":"ho-colonialism-3-38","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":38,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"“我们获悉前殖民地总督、前印度法属领地议员热雷米·勒梅尔（jérémie lemaire）正被法庭起诉。此人曾任某银行董事长，该行由弗雷佐尔先生（Frezouls）任常务董事，两年前宣告破产。","language":"中文","translation":false},{"id":"ho-colonialism-3-39","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":39,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"这便是那名无赖在功名路上的完美收官。”","language":"中文","translation":false},{"id":"ho-colonialism-3-40","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":40,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"呵！呵！这么说来，在高贵的殖民地的总督和议员群中，也有无赖之徒啦？谁能想得到呀！","language":"中文","translation":false},{"id":"ho-colonialism-3-41","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":41,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"乌特雷老爷（Outrey）是位自称“北圻议员”的人物（其“北圻血统”堪比皮·洛蒂（P.Loti）自称土耳其人般可信）。他一面在议院高谈阔论，一面在西贡大搞投机。作为议员，他定期领取津贴；作为殖民者，却常年拖欠税款。这位“廉洁”的人民代表坐拥着两千公顷的特许地，十五年来，从没有纳过一个铜板的税。当税务局要求他照法律纳税时，他回答说：去**的。因为他是一位议员，所以人家不敢碰他一根毫毛。","language":"中文","translation":false},{"id":"ho-colonialism-3-42","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":42,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"就是这一位乌特雷老爷，有过一段时间，他曾担任过法属北圻统使的要职。","language":"中文","translation":false},{"id":"ho-colonialism-3-43","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":43,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"北圻是由一名统使统治的，而统使是由法国总统委任的。为了完成自己的“崇高”任务，这一名高级官员，凭借着一个所谓的殖民地议会（包括有法国人和安南人）。这个议会最重要的职权之一是通过殖民地每年的财政预算。请允许我们说句老实话吧，这一项财政收入的来源是安南人民所缴纳的各项直接或间接税，支出的款项，在原则上（从来就没有在实际上）必须是为有利于安南人民的公益事业。总之，安南人民的权利就托付在这个殖民地议会里。可是在这个宝贵的殖民地议会里，法国人却比安南人多——法国人十八名（其中十二名代表是选举选出的，另外六名则是各公司、商务处、农业处……的代表），安南人六名。就算你每次都全数出席吧，可是安南人的六票，有什么本事能反对法国人的十八票呢？因此，政府可以任意做它的预算，因为所有的预算都可以肯定地看作预先获得了通过。","language":"中文","translation":false},{"id":"ho-colonialism-3-44","author":"胡志明","title":"法国殖民制度的罪状","location":"第三章 总督老爷们","page":3,"paragraph":44,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/03.htm","text":"事情几乎一直是这样进行的。因此，1905年，乌特雷统使老爷、现在是北圻的法国人议员，就以这种办法，把土地税增加了百分之百。增税之前，土地税本来就已经太重了。这一让乌特雷在安南人记忆里“永垂不朽”的壮举，导致当时殖民地议会的全体安南人代表总辞职！——有什么要紧！乌特雷直接指定新人选强加给安南选民。投票之前，乌特雷的一名爪牙——边和省的统治官员马斯佩罗（Maspero），不是把该省的全体选民都监视起来，不让他们和候选人接触吗？人家用惩罚来恫吓他们，强迫他们要投裴世甘（Buï thê Kâm）——乌特雷所指定的候选人——的票；同时，阻止选民，不让他们再选那一位刚辞职的代表怀氏（Hoài），因为他竟不识相地违逆乌特雷的意旨办事。","language":"中文","translation":false},{"id":"ho-colonialism-4-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-4-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"（三）布迪诺、博杜安和其他高贵的老爷们","language":"中文","translation":false},{"id":"ho-colonialism-4-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"你们是知道的，一直以来，各殖民地被称为海外的法兰西，而这些海外法兰西的法兰西人，则全是些安南人、马尔加什人（Malgaches），或某某族人等。因此，什么事情在这边认为对的，那边就认为不对；或是那边被允许的事，这边却被禁止。比如：在殖民地，所有的法国人都被允许用鸦片毒害土著，他们的鸦片卖得越多就越受到人家的敬重；但在法国本土，如果你胆敢卖一卖这种毒品，你就会立刻被抓起来。在法国，高级公务员可以随意穿着内衣上街去；而在殖民地，即便是贵为王子也被禁止穿着民族服装，即使是在自己家中养病时也不例外。","language":"中文","translation":false},{"id":"ho-colonialism-4-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"已故的突尼斯贝伊（bey de Tunis）抱病在床，因此穿着睡衣接待了总督老爷。这已是太岂有此理了，但更糟糕的是，贝伊的两个孙子，竟忘记向总督老爷行礼。这么一来，两天后——正好够他们反省的时间——总督大人便穿起戎服带着骑兵卫队到王宫去，强迫贝伊向他道歉。——这才是真理呀！当一个人贵为贝伊却受着某位“圣徒老爷”（无论是圣父、圣子还是圣灵）的保护时，他就连生病的权利都没有。至于这些土著的“小猴子”们就更要明白：你们既然生在民主制度的温暖卵翼下成长，你们就不该玩耍、欢笑或打闹，而应该好好学习循规蹈矩的磕头呀！","language":"中文","translation":false},{"id":"ho-colonialism-4-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"印度支那也像其它各殖民地一样，有不少“保护老爷”，他们常常喜欢用拳脚教育那些行礼不够迅速的土著。但动用武装部队强迫儿童行礼的，倒还前所未闻。当然，毕竟不是谁都是总督老爷嘛！","language":"中文","translation":false},{"id":"ho-colonialism-4-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"尽管这一“严重的事件”已经在议院的讲坛上被揭露了，并照普恩加莱老爷（Poincaré）的话说，它可能损害了法兰西的威信，但如果我们指摘圣特总督老爷（Saint）为“失败主义者”的话，那我们也就太忘恩负义了；而且多亏了这一次友好、天真且和平的示范，从此之后，土著们也终于学会了如何向“白人兄弟”行礼。在这之前，记得米勒兰老爷（Millerand）到非洲访问时，土著们为了表示对这位保护国元首的诚挚爱戴，他们就曾特意把衬衣拉在裤子外面来行礼。","language":"中文","translation":false},{"id":"ho-colonialism-4-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"不久前，《人权手册》（Les Cahiers des Droits de l'Homme）刊登了该会主席费迪南·比松（Ferdinand Buisson）致殖民地部部长萨罗老爷的一封信，其中提到了1917年的太原起义（révolte de Thaï Nguyên）及其镇压行动。","language":"中文","translation":false},{"id":"ho-colonialism-4-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"这封信明确指出：太原省统使达尔勒老爷（Darles）应负的责任——正因为达尔勒老爷的贪污，才引发了这场起义。西贡法庭也于1917年对他判定了罪状。","language":"中文","translation":false},{"id":"ho-colonialism-4-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"可是，谁想得到达尔勒老爷却没有受到任何行政处分。相反地，他还被举为西贡市议会的议员。至于法庭对他的惩罚，则很可笑：仅仅交纳二百法郎的罚款。","language":"中文","translation":false},{"id":"ho-colonialism-4-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"这位达尔勒老爷果然是一位有才干的统治者。他的统治本领，是当他还在拉丁区（Quartier latin）卖稀粥时就学会的。","language":"中文","translation":false},{"id":"ho-colonialism-4-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"当年，达尔勒老爷正在倾家荡产和负债累累的当儿，却依靠了一位有势力的政客的抬举，被派到印度支那，充当一名统治官员。","language":"中文","translation":false},{"id":"ho-colonialism-4-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"如今，他俨然成为坐拥数万人口的一省之长了，并且还被授以绝对权力。他既是省长又是乡长，既是审判官又是书记官和督税官，总之，一切权力，全在他掌握之中。关于对土著的案件审判、税务、所有权、生命和财产，公务人员的权利，里长、正总的选举等，总而言之，全省命运都付托于这位昔日卖粥仁兄的手里。","language":"中文","translation":false},{"id":"ho-colonialism-4-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"在巴黎时，没有办法以剥削顾客而致富；到北圻之后，他便想办法捞回油水，以肆意逮捕、监禁和陷害安南人的专横手段，去夺取他们的财产。","language":"中文","translation":false},{"id":"ho-colonialism-4-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"以下二三事，说出了这位可贵的统治老爷的独裁统治，而这便是法兰西共和母国为了开化我们而雅意派来的老爷。","language":"中文","translation":false},{"id":"ho-colonialism-4-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"一些土著“志愿军”（！）被调到省会去补充炮手，所以他们必须检查体格。因为文盲和畏怯，因而回禀迟钝笨拙，统使大人便喝叱、咒骂、拳打脚踢，木棍儿没头没脸地打下来。","language":"中文","translation":false},{"id":"ho-colonialism-4-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"还有一回，因为三名蓝带兵（miliciens）放跑了一名囚犯，达尔勒老爷便极其残忍地殴打了这几名士兵。他捶打他们，抓住他们的头发，把他们拖在地上，并且拿他们的脑袋撞击法院的墙壁。","language":"中文","translation":false},{"id":"ho-colonialism-4-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"当他们审问犯人的口供时，达尔勒老爷以官老爷的佩剑刺进犯人的大腿，有些犯人回到牢里时，便不省人事地倒下去。","language":"中文","translation":false},{"id":"ho-colonialism-4-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"一群衣衫褴褛的、瘦削的、饥饿的犯人，他们在天蒙蒙亮的时候就被拉了起来。他们的脖子扣上枷、脚下镣锁锒铛，这个人的脚和另一个人的脚绑在一起，他们在一条刚铺上鹅卵石的路上拉着一辆巨大的压路机。他们已是筋疲力尽了，在烈日如焚底下，吃力地拉动那笨重的压路机。蓦地里，统使老爷来到，按照常例，老爷随身带着一根粗大的哭丧棒，接着，他突然无故地冲进那苦难的人群，以不可想象的残忍和野蛮，没头没脑地殴打他们，边打边骂，骂他们是懒惰的东西。","language":"中文","translation":false},{"id":"ho-colonialism-4-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"有一天，我们的这位文明传播者在责骂一位欧洲籍职员之后，不知该把怒气发泄在谁的头上，于是他便在案头拿起一把铁尺，把一个与事情毫不相关的安南籍文书的两个指头砸碎了。","language":"中文","translation":false},{"id":"ho-colonialism-4-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"另一天，官老爷用牛筋鞭子，就在一名土著上士的下属面前，往上士脸上抽打。","language":"中文","translation":false},{"id":"ho-colonialism-4-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"又有一回，有几名兵士违背了官老爷的意旨，官老爷立刻把他们活埋，当土盖到他们的脖子上奄奄一息时，才把他们挖出来。","language":"中文","translation":false},{"id":"ho-colonialism-4-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"每逢官老爷到有民夫干活的公路上去视察时，被官老爷用铁铲、锄杆打跛了腿的，为数总有半打。这些筑路的民夫全是被强拉来干活的，每天的工钱只有一两个铜板，如果哪一天他们不去服役时，就必须以十五个铜板缴纳免役费。","language":"中文","translation":false},{"id":"ho-colonialism-4-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"有一回，在一个工地上，官老爷从一名哨兵手里抢过一杆枪去打一名犯人。犯人闪开了，官老爷就以这杆枪，转过来揍那名士兵。官太太——堪配官老爷的贤夫人——也立刻参加进来，打了犯人、罚了士兵，直至过了瘾才罢休。","language":"中文","translation":false},{"id":"ho-colonialism-4-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"有人曾经看见，这位统使老爷用哭丧棒把一名上士的眼珠都打得突了出来。这位大人还干出很多其他“崇高”的事情，可是在这里，恕我们没有办法讲得完。","language":"中文","translation":false},{"id":"ho-colonialism-4-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"所有这些事情，每个人——包括他的上级，即总督老爷、钦使老爷、统使老爷在内——都听到、看到。为了奖励他这种“坚决”的精神和极其“共和的美德”，这几位老爷们，竟不遗余力地提升他。","language":"中文","translation":false},{"id":"ho-colonialism-4-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"（三）布迪诺、博杜安和其他高贵的老爷们","language":"中文","translation":false},{"id":"ho-colonialism-4-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"不管展览会如何热闹，不管演说词如何华丽，不管帝王怎样出巡，不管报纸的文章如何宏大，印度支那的情况仍然不妙。","language":"中文","translation":false},{"id":"ho-colonialism-4-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"廉正的统使老爷拉农（Lanon）刚离开被告席，新丑闻又接踵而至。","language":"中文","translation":false},{"id":"ho-colonialism-4-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"首先，是布迪诺案件（Boudineau）。布迪诺是一位典型的“文明传播者”，是一位贪婪的统治老爷。在他的各个被控告的案件中，我们摘录了如下事件：","language":"中文","translation":false},{"id":"ho-colonialism-4-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"新安乡（Tânan）是一个驻有区公所的地方，该乡曾经拨出公款，并又向外贷款，以便建设一所发电厂。这项事业原本收益颇丰，村财政收入远超支出。不但如此，村内建筑和街道还能享受免费照明。","language":"中文","translation":false},{"id":"ho-colonialism-4-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"可是突然，这一位颇聪明的统治老爷——布迪诺先生不知怎样巧妙地钻营，迫使新安乡将企业无偿转让给承包商，结果村民反倒要为街灯付费。如今，新安乡不得不花费数万公款去赎回本属于自己的发电厂。这桩事简直妙得像一篇小说似的，将这位统治老爷的狡诈聪明和无耻嘴脸展现得淋漓尽致。","language":"中文","translation":false},{"id":"ho-colonialism-4-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"使舆论哗然的第二个案件是泰阿尔案件（Théard）。一位印度支那的同行对这个案件这样写道：","language":"中文","translation":false},{"id":"ho-colonialism-4-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"“我们正生活在一种实在……实在很不平凡的气氛里：布迪诺案件、卢诺案件（Luno）未了，泰阿尔案件就又接踵而至。","language":"中文","translation":false},{"id":"ho-colonialism-4-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"泰阿尔老爷是一位出色的工程师，是海防一间法国大洋行的经理。他去找海关主任斯卡拉老爷（Scala），并预先送给他一万美金的茶钱，以便同政府签订一个贩卖鸦片的合同。泰阿尔老爷所以敢于这样做，必然有充分的特别理由，使他认为这种勾搭是没有什么不平常的。如此说来，在印度支那的政界中，贿赂已是常态了。但凡掌权者都在权钱交易中中饱私囊，却让公众利益付出惨重代价。”","language":"中文","translation":false},{"id":"ho-colonialism-4-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第四章 殖民地的老爷们","page":4,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/04.htm","text":"如果太原的嗜血统使达尔勒老爷能当上西贡市议会议员，而博杜安老爷（Baudoin）——瓦伦法官（Waren）正焦急地等着审讯他——能出任印度支那代理总督的话，那么，对于泰阿尔和布迪诺老爷之流，至少该给他们别上勋章才算公平呀！","language":"中文","translation":false},{"id":"ho-colonialism-5-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-5-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"请问在印度支那总督府的密探局里，不是有一个法国人名叫C某的吗？不就是这一个C某在富川（Phuxuyên）“公干”之时，曾经强迫那里的安南人必须称他为“大人”，并对那些没有快快当当这样称呼他的人，给予残暴的殴打吗？不也就是这一个C某鸡奸了一名侍卫兵吗？原来，在印度支那这个“天堂”里，人家是有权为所欲为的呀！","language":"中文","translation":false},{"id":"ho-colonialism-5-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"1922年12月间，在西贡有一名法国警察中士，在酩酊大醉中，闯进一个土著的家里，重伤该家二人，其中有一个是妇女。","language":"中文","translation":false},{"id":"ho-colonialism-5-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"当预审推事问供时，这一名警察供述：他啥也记不清了，同时还狡辩说，他没有喝醉。","language":"中文","translation":false},{"id":"ho-colonialism-5-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"相反地，各位证人，其中有一名欧洲人，却确认在这一凄惨的案件发生时，这位负责治安的人员，果真处在失常的状态中。","language":"中文","translation":false},{"id":"ho-colonialism-5-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"其实，醉或是癫都无所谓，我们恳切地希望这一位文明传播者的勇敢行动能够获得勋章。","language":"中文","translation":false},{"id":"ho-colonialism-5-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在殖民地，只要你有白色皮肤，那你就是高贵的人，就属于上等人种。为了维持这一体统，即使是最低级的海关人员，最少也有一个佣人，一个“仆役”，常常是用一个“兼理一切杂活的奶妈”。","language":"中文","translation":false},{"id":"ho-colonialism-5-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"殖民地国家的佣人很听使唤，同时工钱又很低，因此，有很多殖民地公务人员到法国去休假或退休，都连佣人也带去，就像住在瑟堡市卡诺街的让·德·姆…里尼老爷（Jean Le M...rigny）一样。他从印度支那回去，就带了一名仆役，每月工钱三十五法郎。不用说你们也知道，这一名仆役被强迫着从天蒙蒙亮一直忙到深夜。在那个家里，没有星期天也没有任何节日。再者，人家给他吃得很差，住得很坏。","language":"中文","translation":false},{"id":"ho-colonialism-5-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有一天，让·德·姆…里尼老爷要把这一名“被保护者”送到乡下去锄地。他不肯去，因为在这之前，他曾经尝过这位高贵主人在乡下的“幸福生活”的味道了。","language":"中文","translation":false},{"id":"ho-colonialism-5-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这位“老文明传播者”立刻恼火起来，老爷把他结结实实揍了一顿，并且把他赶出门外。尽管这名土著多次央求，但让·德·姆…里尼老爷仍然不肯把他的一些私人物品如衣服、箱子、钱币等还给他。突然被赶出去，不懂法语，空着两手，没有亲友，无依无靠，现在，他正处于极其穷苦的境地中。","language":"中文","translation":false},{"id":"ho-colonialism-5-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"殖民地的公务人员是造成殖民地物价昂贵的灾难的主要原因。要想知道这种寄生性的灾难怎样加重了财政负担，就是说，怎样加重了劳动人民的负担，请读读如下的数字：","language":"中文","translation":false},{"id":"ho-colonialism-5-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"英属印度，三亿二千五百万人口，欧洲籍的公务员是四千八百九十八名。","language":"中文","translation":false},{"id":"ho-colonialism-5-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"法属印度支那，一千五百万人口，欧洲籍的公务员是四千三百名。","language":"中文","translation":false},{"id":"ho-colonialism-5-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这就是说，在英国属地里，每六万六千一百五十人中，有欧洲籍的公务员一名；而在法国属地里，只三千四百九十人中，就有一名欧洲籍的公务员。","language":"中文","translation":false},{"id":"ho-colonialism-5-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在印度，关税部门有欧洲籍的公务员二百四十名。","language":"中文","translation":false},{"id":"ho-colonialism-5-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在印度支那，同样的部门却有欧洲籍的公务员一千一百名。","language":"中文","translation":false},{"id":"ho-colonialism-5-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在印度，邮局有二万六千所，欧洲籍的公务员二百六十八名。","language":"中文","translation":false},{"id":"ho-colonialism-5-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在印度支那，邮局只有三百三十所，欧洲籍的公务员却有三百四十名。","language":"中文","translation":false},{"id":"ho-colonialism-5-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"为什么这类吃预算的人在印度支那竟如此之多呢？因为殖民地是人间的天堂呀！在那里，除了一两个极其罕有的场合之外，其他全是宗主国各政治、财政、新闻等部门所吐出来的渣滓，它们在印度支那找到了繁殖的肥沃土壤……。让我们从头号人物——总督老爷讲起吧。关于这个问题，有一个无私的法国殖民者曾经这样写道：“各位总督老爷到北圻去的唯一目的是：为他的朋友、子弟、亲属和那些在选举时能为自己的靠山进行运动的人，安插位置，而他们常常是些负债累累、被债主追逼的人，对于他们来说，一定要有钱才行……。”","language":"中文","translation":false},{"id":"ho-colonialism-5-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"对于那些想写作殖民地的“辉煌开化史”的尊贵作家们来说，那场被称为为公理和正义的战争，将是一个无穷无尽的史料泉源。阿尔贝特·萨罗老爷在兴高采烈地雄辩之时，曾经这么说：“曾经把我们引向胜利和把我们的旗帜插遍亚洲、非洲而受到法兰西舆论歌颂其光辉战绩的大多数将领，他们主要是在征服殖民地的战斗中获得了锻炼。”","language":"中文","translation":false},{"id":"ho-colonialism-5-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"“不知道是不是魔鬼在日内瓦作祟？”《日内瓦报》曾经这样揭穿——内容是坦率的，就是言词略欠和气——说：“法兰西共和国政府为了捞回1870年的失败而找寻殖民地；法国人把征服殖民地看成是他们在欧洲不得志的一种补偿；法国军人幸运地获得在那些容易打胜仗的战役中逞能的机会。”","language":"中文","translation":false},{"id":"ho-colonialism-5-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"听了这样权威的证实之后，而你还一味不肯相信征服殖民地只是一种“文明的使命”和“地地道道的人道行为”的话，那就算了！","language":"中文","translation":false},{"id":"ho-colonialism-5-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"（一）吉诺多老爷（Guinaudeau）失窃五千法郎。为了迫使为他干活的土著们招认，这一位好心肠的主人和伟大的文明传播者就给他们上电刑讯问。可是后来，人家查出了做贼的并不是土著们，而却是另一位文明传播者——吉诺多老爷的小少爷！尽管如此，吉诺多老爷仍然平安无事，而八名为他干活的土著直到现在还躺在医院里。","language":"中文","translation":false},{"id":"ho-colonialism-5-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"（二）沃拉尔老爷（Vollard）——一位文明传播者兼商人，他没有按期把工资发给那些土著工人。有一名土著就托一个监工向他的主人要回所欠的工资。沃拉尔老爷立刻把一张纸条交给监工，上面写着如下几个字：“告诉那个猪猡，他只配吃屎。”","language":"中文","translation":false},{"id":"ho-colonialism-5-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这桩事情发生于1923年的突尼斯，恰好是米勒兰总统老爷来此视察的时候。","language":"中文","translation":false},{"id":"ho-colonialism-5-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"当人们有一副白色皮肤的时候，那他就俨然是一位文明传播者。而当他已经是一位文明传播者的时候，那么，不论他干出了什么野蛮的事情来，他仍然是一个比较文明的人。","language":"中文","translation":false},{"id":"ho-colonialism-5-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"比如，北圻公共工程局的某位监工老爷，就强迫那些在路上碰见他的安南人，必须按照一个战败的民族对战胜的民族的仪式，向他拜揖。","language":"中文","translation":false},{"id":"ho-colonialism-5-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有一天，一个土著文书从下班途中正读着小说，当看到诙谐的一段，他不禁笑起来。恰在这时候，这位监工老爷经过。他立刻发起火来：其一，这名土著竟沉迷小说，没看见老爷、没向老爷拜揖；其二，身为土著竟敢白人面前发笑。这么一来，我们这位文明传播者就把文书拉过来，问清姓名后竟问文书想不想吃一记耳光。文书自然拒绝了这种太过豪爽的礼物，并且对这样一种平地起风波的事情表示愕然。这位监工老爷就二话不说，揪住这名土著的衣领，拉他去见省长老爷。","language":"中文","translation":false},{"id":"ho-colonialism-5-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"还是这位监工老爷，借口“整顿道路沿线景观”为由，勒令马路两旁的居民必须在他所规定的时间内迁居、砍树和铲平园地，违者就将受到处罚。","language":"中文","translation":false},{"id":"ho-colonialism-5-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"事情如此，而人们对各殖民地的人民老喊不平为什么还感到愕然呢？","language":"中文","translation":false},{"id":"ho-colonialism-5-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"不仅各位总督、统使为所欲为，而且连海关、警察局的人员以至所有有一点权力在手的人，都使用权力和滥用权力去为非作歹，因为他们知道一定不会受到什么处罚的。","language":"中文","translation":false},{"id":"ho-colonialism-5-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"北圻的宣光省（Tuyên Quang）的一名警长，就曾经把一名土著打折了胳膊。","language":"中文","translation":false},{"id":"ho-colonialism-5-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"北圻的大叻（Dalat）的另一名警长，则发明了一种“绝妙”的买卖，我们讲述出来，并谨献给尊贵的迪奥尔（Dior）和萨罗老爷。一天，警长老爷需要木板，他叫士兵到街上去买。其实话只是这么说而已，警长老爷哪里会拿钱给他们去买。尽管如此，士兵还是上街去了。他走进店里，选好木板就想带走，当然是没有给钱。卖木材的说，如果不给钱就不能把木板带走。士兵回去，把那名商人奇怪的要求向他的法国老爷禀告。","language":"中文","translation":false},{"id":"ho-colonialism-5-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"警长老爷大怒，立刻派出三名带枪的士兵去逮捕那大胆的木材商人。木材商人正害病，不肯走。士兵回来向警长报告。警长老爷就越加暴跳如雷，他立即加派三名士兵，和前三名士兵一起去抓那名顽固的商人，并严令不管死活，都必须把他捉到。","language":"中文","translation":false},{"id":"ho-colonialism-5-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这一群武装的士兵包围了木材商店，并且就要执行警长的命令。","language":"中文","translation":false},{"id":"ho-colonialism-5-36","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":36,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这时候，有个法国商人进来干涉，他袒护土著木材商，并写信给警长。可是这一位莫里斯·朗（Maurice Long）总督老爷的“坚强助手”，却仍然不肯收回对木材商人的“传唤令”，并且告诉他说，如果他不来，就将碰到很多极其不利的事情。","language":"中文","translation":false},{"id":"ho-colonialism-5-37","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":37,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这个土著木材商被迫抛掉生意，离开家园、故乡，远走他方，以避开那位法国官老爷的“开化”怒气。","language":"中文","translation":false},{"id":"ho-colonialism-5-38","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":38,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"七个倒霉的安南人正划着一条长长的、单薄的小艇，小艇既顺着水，而且又有七把桨，所以像一艘汽艇似地疾速前进。隐没在老树丛后面的税关人员的船，刚从小河沟冒出来，法兰西的国旗在船尾飘扬。税关船上的一名水手喊着要小艇停下来。小艇上的人因为听不懂，所以还是往前划。法国税关人员的船走得很慢，因此赶不上。于是温彻斯特步枪便开火了。砰！砰！一个正在划艇的人惨叫一声，就倒了下去。砰！又有一个人倒了下去。这时候，另一个欧洲人——经营砖瓦业——也恰好坐着小艇来到，他立刻在河道转弯处对“海盗们”进行突击。砰！砰！砰！果然是名神枪手！三发子弹，三条人命。小艇沉没在河沟里，死里逃生的只有两个人……。","language":"中文","translation":false},{"id":"ho-colonialism-5-39","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":39,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"另一天，仍然是这名税关人员和六名武装水手，看见一个穷苦的人躲在池里。这个人把身体埋在泥塘中，用一支竹管呼吸，竹管的一端含在口里，另一端冒出水面，上面用睡莲叶密密遮住。这名税关人员立刻把这个“海盗”抓起来砍掉脑袋，并把人头带回统使老爷的官邸去。其实，这个人因为看见很多陌生人闯进乡村，面目狰狞，身上带满子弹袋和插着手枪，手里还紧紧握着步枪，他由于过度恐惧而躲藏起来。所谓“强盗”者，只不过是一个普通的乡下人而已。这一群税关人员走进村里的各间破烂茅屋，发现了三个子弹壳、一些糕饼和一把伐木的斧头。如此看来，这个村子无疑是一个造反和接济敌人的村子了！","language":"中文","translation":false},{"id":"ho-colonialism-5-40","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":40,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一个刚从法国过来的年轻军官，到了一个村子，看见村舍静悄悄的，群众都聚集在庙堂的周围。这家伙以为自己已经落进了伏击圈里，就向这些无辜的人群扫射。其实，群众正聚在一块拜神呢。他们被扫射，遂惊慌四散。那名军官还一边追一边杀人。","language":"中文","translation":false},{"id":"ho-colonialism-5-41","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":41,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一个“老北圻”说：“当我搭着一艘大商家的商轮到北圻的时候，你们可知道安南人的一条生命值多少钱？真的，不值一个铜板。","language":"中文","translation":false},{"id":"ho-colonialism-5-42","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":42,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"嗨！我还记得，当我们搭船沿着红河（Fleuve Rouge）逆流而上的时候，人家拿苦艾酒出来打赌，在船上用十发子弹打岸上的安南人，看谁打中的最多，谁就获胜。","language":"中文","translation":false},{"id":"ho-colonialism-5-43","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":43,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有些人带枪去抓人，夺取船只，勒索赎金。","language":"中文","translation":false},{"id":"ho-colonialism-5-44","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":44,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一连海军陆战队行军到了永尚（Vinh Thuong）。按照礼节，地方官员要排列士兵、仪仗队出来迎接。该连的情报队长看见这个情形，命令队员向他们开枪，结果使多人丧命。","language":"中文","translation":false},{"id":"ho-colonialism-5-45","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":45,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"当一个作乱的人逃匿起来，抓不到的时候，人家就把整个村落都烧毁，比如说，人家就是这样把兴化（Hung Hoa）周围的一带地方夷为平地的。","language":"中文","translation":false},{"id":"ho-colonialism-5-46","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":46,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在一条偏僻的路上，人家看见一个安南人，挑着两担花生，正乜乜倒倒地走着。看见我们走到，他并不逃避。人家就立刻把他抓起来并崩掉。","language":"中文","translation":false},{"id":"ho-colonialism-5-47","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":47,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"人家整天拿着木棒或刀把，揍安南人，强迫他们干活。","language":"中文","translation":false},{"id":"ho-colonialism-5-48","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":48,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"安南人是很善良、很驯顺的，但尽管如此，人家还只是以踢屁股去和他们讲话。","language":"中文","translation":false},{"id":"ho-colonialism-5-49","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":49,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"我们把安南的爱国者看成是强盗。比如上士阿云（Đội Văn），他是一个反对统治、战斗了好几年的爱国者，在河内（Hanoï）被斩首，首级拿到北宁（Bac Ninh）去示众，尸体抛进红河。","language":"中文","translation":false},{"id":"ho-colonialism-5-50","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":50,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"宋维新（Tống Duy Tân）在漫长的十年的绝望战斗之后，也被捕和被斩首。","language":"中文","translation":false},{"id":"ho-colonialism-5-51","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":51,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"潘廷逢（Phan Đình Phùng）——一位大官，他在抗法十年后，死在深林中。他虽然死了，但我们仍不饶恕他。人们到森林里去挖他的坟墓，把他的尸骸扔掉。人家甚至对那些安息在墓中的死人也报起仇来。","language":"中文","translation":false},{"id":"ho-colonialism-5-52","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":52,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在广治省（Quang Tri），一个喝醉了酒的法国籍护路下士，用枪把一个坐在象背上的安南人‘打下’来，这个人的罪名，只是听不见或听不懂他的命令而已。","language":"中文","translation":false},{"id":"ho-colonialism-5-53","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":53,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在巴地市（Baria）的一名税关人员，他也喝醉了酒，抡起一根木棒，猛击他属下的一名安南水手的脾脏，这个人当场毙命。","language":"中文","translation":false},{"id":"ho-colonialism-5-54","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":54,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在大叻的一个法国承包商，他杀死了一名安南蓝带兵。也是在这个地方，有另外一位文明传播者，把一名土著木匠打得抱病而终。","language":"中文","translation":false},{"id":"ho-colonialism-5-55","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":55,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有一名承包商强迫工人站在水里，日夜挖一个地窖。很多工人都累死了，剩下的起来罢工。为了逼着他们出来干活，这名承包商就亲自去放火烧毁罢工者的房屋，整个村落就在黑夜中熊熊燃烧起来。","language":"中文","translation":false},{"id":"ho-colonialism-5-56","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":56,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一名炮兵准尉半夜里到了一家丈夫外出的安南女人的家里，女的不肯接待他，他就恼火起来，把她的家烧了。当然，这个可怜的女人是极其惊骇的。","language":"中文","translation":false},{"id":"ho-colonialism-5-57","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":57,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一个中尉讨了很多老婆，他曾经把一个少妇击倒在地上，用藤鞭活活把她抽死，只因为她不肯嫁给他。","language":"中文","translation":false},{"id":"ho-colonialism-5-58","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":58,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"海军兵工厂的一名职员，是这样杀死一个安南铁路人员的：在残酷地拷打了那个铁路人员之后，把他推进一堆红灼灼的火炭上。”","language":"中文","translation":false},{"id":"ho-colonialism-5-59","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":59,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"维涅·多克顿先生（Vigné d'Octon）这样写道：世界上没有哪个战败的民族，像各殖民地的民族那样被镇压和虐待。","language":"中文","translation":false},{"id":"ho-colonialism-5-60","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":60,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"另外一位旅行家写道：“殖民地的生活，只能使个人的传统的劣根性发展而已。对于那些尝过战争味道的人来说，那么，殖民地的生活就更使他们没有什么道德意识，他们堕落、不肖和恶毒；对那些市侩和其他的冒险分子来说，就更使他们习惯于窃夺和搜刮了。在法国本土，很少有机会干这些勾当，再说，警察是更可怕的！在这里，那些家伙经常是在一只船上或一两个村落中，独自面对着五、六个土著人，因此，就比欧洲人在市场上更有条件进行窃夺和搜刮；同时，对那些反抗他们的农民，就对待得更加残忍了。”","language":"中文","translation":false},{"id":"ho-colonialism-5-61","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":61,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"又有一位旅行家说：所有法国人，当他们踏上殖民地的时候，就都这样想：安南人是低等人，必须做他们的奴隶。他们把安南人看成是一些必须用鞭子去指挥的牲口。所有的人都惯于自以为是属于一个享有特权的新贵族阶级。不管是士兵或是殖民者，他们都认为自己与土著之间的关系，除了主人和奴仆的关系之外，别无其他关系。在他们看来，好像仆役就是全体“黄种人”的代表。应该听听那些在印度支那的法国人谈论“黄种人”，才看得出他们多么愚蠢的轻蔑！应该看看一个欧洲人怎样对待土著，才知道这些家伙竟粗野鲁莽到这个地步！","language":"中文","translation":false},{"id":"ho-colonialism-5-62","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":62,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"征服者非常关心被征服者的服从和恭敬态度。安南人不论在城市或农村，都被迫必须在欧洲人的面前脱帽致敬。","language":"中文","translation":false},{"id":"ho-colonialism-5-63","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":63,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有一名暗探，对那些不称他为大人的安南人，都残忍地殴打。有一名税关人员下令，走过他门口的人都必须脱帽或下车。有一天，这位文明传播者，残忍地殴打一个安南妇女，因为这个女人虽然向他致敬，可是却没有称他为“大人”。这个女人正怀孕，那名税关人员往她肚子上猛踢了一脚，害得她流产，几天后就死掉了。","language":"中文","translation":false},{"id":"ho-colonialism-5-64","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":64,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"各位保护老爷强迫安南人必须尊敬他们，必须驯顺、听话、礼貌，可是相反地，各位官老爷却像一位访问印度支那的作家所说的：“我们做尽了可恶的勾当，使谁都忍受不了。”这位作家还这样说：“在欧洲，黄种人被视为狡诈的代名词。虽然如此，但我们白种人也很少注意表示出自己是诚实和正直的。”","language":"中文","translation":false},{"id":"ho-colonialism-5-65","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":65,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"当那些僧侣在礼拜的时候，有些军官走去揪他们的胡子。在一辆客车上，有个法国少爷痛打一名安南公务员，因为他不肯让出座位，尽管那个少爷到得晚。","language":"中文","translation":false},{"id":"ho-colonialism-5-66","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":66,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一位印度支那总督刚回到马赛，人家请他赴宴，并向他提议，让正在马赛的几位安南官员也参加宴会。总督这样回答：“如果你们请那些安南官员参加宴会，那么，请允许我也把我的仆役带来。”","language":"中文","translation":false},{"id":"ho-colonialism-5-67","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":67,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"让我们在这里摘录一个殖民地军人出差日记的片断吧：","language":"中文","translation":false},{"id":"ho-colonialism-5-68","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":68,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"“当‘北圻’轮的旅客们正消遣、游乐的时候，轮船下面有几只卖水果、螺蚌的小艇。那些卖东西的安南人把篮子挂在竹竿头上，一直举到我们的手边。我们只费神挑选东西而已。照理应该给钱，可是人家却很有礼貌地把烟嘴、裤钮、烟屁股等东西放进篮里（这么做，也许是要教育那些土著做生意的诚实德行呢！）。有时候，是闹着玩罢了，一个伙夫把一桶开水泼到那些穷苦的小贩的背上。立刻，惨叫和划着艇儿避开的桨声乱成一片，小艇乒乒乓乓地互相碰撞。就在我的下面，一个被泼中开水的安南人，从头到脚都被烫伤了，他发狂地要跳下海去。他的父亲不顾一切危险，放下船桨，冲过去把他抱紧，逼他在船底上躺下。闪电般的搏斗刚一结束，另一桶开水，又从一只熟练的手里泼下来，这一回就轮到做父亲的被烫熟了。我看到那个老头子在船里翻滚挣扎，皮肤滚脱了，露出血红的肌肉，他像野兽一样嚎叫。可是这种景象却使我们发笑，我们认为这是怪有趣的事情。我们真是具备了一个殖民者的心灵了！”","language":"中文","translation":false},{"id":"ho-colonialism-5-69","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":69,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在另外一页，那个军人这样写道：","language":"中文","translation":false},{"id":"ho-colonialism-5-70","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":70,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"“我在北圻的这一段时间里，没有哪个星期不看见几个头颅落地的。","language":"中文","translation":false},{"id":"ho-colonialism-5-71","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":71,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在这些情境中，我只记着一点，就是我们比强盗还更恶毒和野蛮。为什么我们对那些即将处以死刑的人还施用这样凶恶的刑器？为什么要用这些肉刑？为什么要把一群群的犯人押着走遍乡村去示众？”","language":"中文","translation":false},{"id":"ho-colonialism-5-72","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":72,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"前印度支那总督保罗·杜美老爷（Paul Doumer）曾经在法国下议院郑重地作了如下的发言：“我非常了解殖民地的警察。而且，我还让警察的人数有所增加，因为我认为警察的力量会保证土著避免受到可能由一些殖民者所带来的欺凌。警察深受土著的爱戴。”","language":"中文","translation":false},{"id":"ho-colonialism-5-73","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":73,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"让我们看一看警察老爷是怎样制造出“人民的好感”的。我们应该说句老实话，这些老爷们对待地痞、流氓，从来总是和善、宽宏的，这是显然不容置辩的事情。可是对于那些善良的土著，那又是另外一回事了。我们也不必提起1916年发生在西贡中央监狱的伤心故事，当年，警察老爷们由于热心爱国，胡乱把人抓进监牢里，后来，无数无罪的人民都被判决和行刑。这些安南人的鲜血染红了坟墓平原（Plaine des Tombeaux），纵然时间会把它冲淡，可是那些年老的母亲，那些寡妇、孤儿心头的创伤，却永远不能医好。制造这些惨案的罪魁——而警察是他们卑鄙的工具——却从来没有被提起公诉，也从来不被惩治。现在，我只提出一两桩特别的事件：","language":"中文","translation":false},{"id":"ho-colonialism-5-74","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":74,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"北圻有一名警察署长，他整天沿着各条沟渠巡视，说是为检查沟渠的卫生。只要看见沟渠的水面上虽只有那么一根水草，他就不问青红皂白，立刻惩治附近的居民和胡乱罚款。","language":"中文","translation":false},{"id":"ho-colonialism-5-75","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":75,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"在南部西区，每条小河都设有一个警察站，检查来往的船只，不许船只开快，不许阻碍交通，目的是避免在小河沟里发生事故。可是，设立一个警察站，那就好比树立了一座发出各种妨害交通违警案和罚款案的闸门。来往于各个警察站的船只几乎都被罚款一至二元。这就是说，除了政府堆压在头上的各种杂税之外，黎民还必须多负一层“亲爱的”警察老爷的河流税。所以说，安南人民真是幸福，太幸福了！","language":"中文","translation":false},{"id":"ho-colonialism-5-76","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":76,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"除了对那些最得力的人予以一般的提升之外，听说各位警察老爷还享有20%的罚款分红！这是多美好的制度呵！","language":"中文","translation":false},{"id":"ho-colonialism-5-77","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":77,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一张当地的报纸这样说：“土著不再喜欢法国的警察，因为法国警察经常是善良人民的一个祸根。”","language":"中文","translation":false},{"id":"ho-colonialism-5-78","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":78,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有一个叫做普尔西尼翁（Pourcignon）的家伙，看见一个安南人居然敢好奇地、大胆地望了他几秒钟，他就恶狠狠地跳过去打那个安南人，并对他的脑袋放了一枪，结果了他的生命。","language":"中文","translation":false},{"id":"ho-colonialism-5-79","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":79,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"北圻有个法国铁路人员，用藤鞭子鞭打一个里长，鞭打之后，还把他关进狗舍里。","language":"中文","translation":false},{"id":"ho-colonialism-5-80","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":80,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"贝克老爷（Beck）一拳打碎了他的车夫的脑袋。","language":"中文","translation":false},{"id":"ho-colonialism-5-81","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":81,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"承包商布雷老爷（Brès）曾经绑住一个安南人的双手，放狗撕咬，后来，就活活把他踢死。","language":"中文","translation":false},{"id":"ho-colonialism-5-82","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":82,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"税务员德菲斯老爷（Deffis），向他仆人的肾脏猛踢了一脚，使他当场毙命。","language":"中文","translation":false},{"id":"ho-colonialism-5-83","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":83,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"机械师亨利（Henry），老爷听见街上有嘈杂的声音，他刚一打开门，就有一个安南妇女闯进来，后面有个男子正追过来，亨利以为这个被追的妇女是自己的“情妇”，他立刻随手拿过一枝猎枪，打了一响，那个男子当场倒下去死了。","language":"中文","translation":false},{"id":"ho-colonialism-5-84","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":84,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有个法国人把他的马儿拴在一个马棚中，里面关着一匹土著的雌马。他的马匹受惊扬蹄，于是法国人勃然大怒，立刻把那个土著打得口鼻出血，后来还把这个人吊在楼梯上。","language":"中文","translation":false},{"id":"ho-colonialism-5-85","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":85,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一位传教士（是的，是上帝仁慈的门徒）怀疑修道士学校里的一名土著学生偷了他一千元，立刻把他捆起来，吊上屋梁打。这个可怜的学生昏厥过去。他们就把他放下来，当他清醒过来的时候，就又把他吊上去拷问。他被打得快要死了，恐怕今天已经死去。","language":"中文","translation":false},{"id":"ho-colonialism-5-86","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":86,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"法庭对这些人，这些文明传播者有没有惩罚呢？","language":"中文","translation":false},{"id":"ho-colonialism-5-87","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":87,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有些是宣判无罪，其他的则一根毫毛也没有动过。","language":"中文","translation":false},{"id":"ho-colonialism-5-88","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":88,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"有个法殖民者窥见三名土著赶着羊儿到他的橄榄园里去吃草。他叫妻子把枪拿出来。他在丛林里窥伺，放了三枪，使三个人重伤。","language":"中文","translation":false},{"id":"ho-colonialism-5-89","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":89,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"另一位殖民者，他雇佣两名土著工人，名叫阿姆杜尼（Amdouni）和本·贝尔希尔（Ben Belkhir）。这两个人好像偷采过他一两串葡萄。那位殖民者就立刻把他们两人喊来，接着，就用一条牛筋做的鞭子，不停地抽打他们，直到他们昏迷不省人事。当这两个人醒过来的时候，我们的保护大人就立刻叫人捆住他们的手肘，并且吊上去。尽管这两个穷苦的人已经昏迷不省人事，可是拷打仍然延续了四个小时，一直等到隔壁有人反对才罢手。抬进医院的时候，每人被锯掉了一只手掌，另一只手掌还不知道能不能够挽救！","language":"中文","translation":false},{"id":"ho-colonialism-5-90","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":90,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"一个五十岁的安南人黎文泰（Lê Van Taï），在北圻铁路局干了二十五年，被一名法国职员杀死。事情的始末如下：","language":"中文","translation":false},{"id":"ho-colonialism-5-91","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":91,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"黎文泰指挥他属下的四个助手干活。他们的任务是，当火车将要开过来的时候把桥放下让火车通过，然后把桥吊起来让船只往来。按照规定，在火车开过之前十分钟就必须把桥放下。","language":"中文","translation":false},{"id":"ho-colonialism-5-92","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":92,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"4月2日，16点30分的时候，他们中有一个人刚把桥放好并挂上了信号，就在这时候，有一艘公家汽艇开到，艇上坐着一个打猎回来的海军兵工厂的职员。汽艇鸣起笛来。那个当地人员立刻走到桥的中间，摇着红旗，向汽艇上的人报告，火车即将开过。于是汽艇泊在桥墩边，那法国职员跳上岸来，怒冲冲地走向那个安南人。这个乖觉的安南人往黎文泰——他的“长官”——的家逃避。那职员拿石头扔他，并追上去。黎文泰听到人声嘈杂，便立刻走出来迎接这一位文明的代表，这名代表立刻叫骂：“你这畜生！为何不开桥？”黎文泰原来就不懂法语，他只知道指向红灯来回答他。这简单的动作，使朗老爷的同事火起来了。他不分青红皂白，向黎文泰扑过去，在“揍了一顿”之后，他把黎文泰推进旁边的一个红火的炭堆里。","language":"中文","translation":false},{"id":"ho-colonialism-5-93","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":93,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这名守桥的安南人全身被严重烧伤，必须送到医院去。黎文泰在经过六天极其痛苦的挣扎之后，已死在医院里。","language":"中文","translation":false},{"id":"ho-colonialism-5-94","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":94,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"那位职员仍然无事，他一点也不用担心。就当人们在马赛展览粉饰了的印度支那的繁荣景象时，安南人民却正在饿死。在这边，人家歌颂着殖民地人民的“忠诚”，而在那一边，却在杀人！","language":"中文","translation":false},{"id":"ho-colonialism-5-95","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":95,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"当安南人民的生命被看成像狗一样不值一文钱的时候，莱因哈特（Reinhart）总督察老爷只因为胳膊上擦破了一小块皮，就领到了十二万法郎的赔款。","language":"中文","translation":false},{"id":"ho-colonialism-5-96","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":96,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"用大炮“开化”摩洛哥人的事业仍在继续。","language":"中文","translation":false},{"id":"ho-colonialism-5-97","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":97,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"驻扎在塞塔特（Settat）的朱阿夫兵（zouaves）指挥官向他的士兵这样训示：“我们应该把那些野蛮人全部消灭。摩洛哥的土地、矿产和农产都非常丰富。我们——法兰西人，文明的人——到这里有两个目的：一是开化这个地方，二是发财。”","language":"中文","translation":false},{"id":"ho-colonialism-5-98","author":"胡志明","title":"法国殖民制度的罪状","location":"第五章 文明传播者们","page":5,"paragraph":98,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/05.htm","text":"这一名指挥官说得对，特别是他老实地招认了人们到殖民地去是为了掠夺土著。因此，在十五年的保护下，37.9万公顷田地就落入欧洲人的手里，其中，36.8万公顷归法国文明传播者们所有。摩洛哥的面积有81.5万平方公里，假如这样的开化继续下去，再不多几年，穷苦的摩洛哥朋友，将不能在自己的祖国找到一寸能够不受殖民主义者剥削和奴役的土地去过活和耕作。","language":"中文","translation":false},{"id":"ho-colonialism-6-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-6-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"第六章 国家机构的贪污舞弊","language":"中文","translation":false},{"id":"ho-colonialism-6-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"拿北圻的财政预算来说，1911年是五百五十六万一千六百八十元（一千二百七十九万一千法郎），1912年是七百三十二万一千八百一十七元（一千六百八十四万法郎），1922年，财政预算跃增至一千二百八十二万一千三百二十五元（九千六百一十六万九千法郎）。只这么简单地一算，我们就看得出在1911年和1922年之间，这个殖民地的财政预算差额是八千三百三十七万八千法郎（那两年的印度支那币对法郎的汇兑率是1：2.25和1：7.5）。这笔钱花到哪儿去啦？花到公务人员的开支上去罢了，因为这些开支已经几乎百分之百地吞没了收入总额。","language":"中文","translation":false},{"id":"ho-colonialism-6-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"接着是把可怜的安南人民用血泪换来的金钱，一笔又一笔疯狂地挥霍掉。现在，我们还不知道安南皇帝圣上到法国去游玩花了多少钱，可是我们知道单为了等待黄道吉日，好让这位“竹龙天子”（Dragon en bambou）御驾下船，人家就已经赔偿了“波尔托斯号”邮轮（paquebot Porthos）停泊四天的费用，每天是十万法郎（就是说一共四十万法郎）。船费四十万法郎，招待费二十四万法郎（还没有把监视旅法安南人的警察费算在内）。为了支付向皇上和部长大人举枪致敬的安南蓝带兵在马赛的饭钱，又支出了七万七千六百法郎。","language":"中文","translation":false},{"id":"ho-colonialism-6-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"因为谈到马赛，所以让我们顺便算一算看，在那儿举行的殖民地展览会已经花了我们多少钱。首先，除了宗主国的达官贵人之外，人家还从各殖民地邀请了三十名高级官员，这些东西，除了每天在卡讷比耶大街（la Cannebière）恣意挥霍之外，还同时领到殖民地和展览会的津贴费。光是印度支那就为这一场展览付出了一千二百万法郎。而且你们可曾知道，这些钱人家是怎么花的？例如：为了搞出一个吴哥窟（Angkor）的模型，就花掉三千立方米的木材，每立方米市价是四百至五百法郎，总共花了一百二十万至一百五十万法郎。","language":"中文","translation":false},{"id":"ho-colonialism-6-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"还有很多其它的花费。为了迎送总督老爷，光用各种汽车和高级轿车仍然不够，这些老爷必须有特别的专车，布置这些专车就花了国库十二万五千二百五十法郎。","language":"中文","translation":false},{"id":"ho-colonialism-6-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"印度支那经济部门在十一个月的活动中，就亏耗了印度支那的公款四十六万四千法郎。","language":"中文","translation":false},{"id":"ho-colonialism-6-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"在培养未来的“文明传播者”的殖民地学校里，聘请了四十名各种各样的教授，教导三十至三十五名学员。这就不知要花费掉多少万法郎。","language":"中文","translation":false},{"id":"ho-colonialism-6-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"经常视察各殖民地的防守工事，每年花费了财政预算七十五万八千一百六十八法郎。可是，这些视察大员却从没有离开过巴黎，而且老爷们对各殖民地的了解，也不会比对月亮的了解多些。","language":"中文","translation":false},{"id":"ho-colonialism-6-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"如果我们再看一看其它的殖民地，那么不论在哪里，我们都看到这样的一种弊害：为了迎接一个半正式的“经济”代表团，马提尼克（Martinique）的金库就“少去了”四十万法郎。在十年里面，摩洛哥的财政预算从一千七百万跃增至二亿九千万法郎，尽管人家已经削减了可能给摩洛哥土著带来某些好处的开支的30%。","language":"中文","translation":false},{"id":"ho-colonialism-6-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"一位从殖民地访问回来的前议员老爷曾经这样叫嚷：“如果把殖民地官员和拦路打劫的强盗相比，那么，强盗还算得是善良的人！”尽管薪俸很多（一名新任用的法国人干事，就算他是个目不识丁的人吧，最少也有二百元，就是说二千法郎），可是这些老爷们却从未感到过满足，他们还是用尽办法想多捞些油水。","language":"中文","translation":false},{"id":"ho-colonialism-6-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"人家还为那些薪俸过于“低微”（就是说从四万到十万法郎）的统使老爷或其他在职的统治官老爷的少爷们发助学金。","language":"中文","translation":false},{"id":"ho-colonialism-6-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"可以说，殖民地议会的各次会议，只是为了讨论更有计划地抢夺公款而已。光是议会的某一位主席，就承包了价值二百万元的工程。某位内政局长老爷——议会中的政府代表，就曾经申请把自己的薪俸增加一倍，并获得议会的通过。第三位承包修筑一条公路，修筑事宜拖了一年又一年，没有谁去检查，这桩事每年都均等地给他带来一笔油水。第四位被荐入印度支那公务员医院，任职大夫，这可是一个肥缺。第五位被委任为城市各办事处的医生。第六位负责供应政府的文具用品和印刷文件，等等。","language":"中文","translation":false},{"id":"ho-colonialism-6-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"如果保险箱里的钱略有减少，那么，人家也不难把钱弄满。他们使用权力通知土著说，政府需要一笔款项，接着，就给各乡分摊应交的捐款。各乡慌忙遵令，免得立遭惩罚。","language":"中文","translation":false},{"id":"ho-colonialism-6-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"当统使老爷有所花费的时候，他就发行各种奖状和颁发品衔。人家这样说过，某省卖品衔，就获得一万零六百二十法郎。而这种事情并不少见。","language":"中文","translation":false},{"id":"ho-colonialism-6-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"我们的钦使老爷中有一位，因为提前几个月花光了汽艇费，钦使老爷立刻要公家偿还他不知道哪一次礼仪的各项开支，据说是他曾经请皇室驾幸汽艇。","language":"中文","translation":false},{"id":"ho-colonialism-6-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"这些文明与民主的推销员，果然长于钻营的手法。","language":"中文","translation":false},{"id":"ho-colonialism-6-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"有一天，一位前印度支那总督老爷坦白地招认说：印度支那到处都是一些大量糟蹋财政预算但却啥也不干的公务员。","language":"中文","translation":false},{"id":"ho-colonialism-6-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"一个殖民者这样写道：半数以上的公务员，纵然是一省之长，或是其他的什么官员，都不具备可以取得这样广泛的惊人的权力的资格。","language":"中文","translation":false},{"id":"ho-colonialism-6-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"他们那一班家伙，就只有挥金如土地挥霍公款的本事。至于穷苦的安南人，就只有挺起腰板上缴的份儿。他们不但要负担这些无能的官员的薪俸，并且还要为一些没有职务的官员的薪俸拿出钱来。19……年，就是这样子花光了二十五万法郎。","language":"中文","translation":false},{"id":"ho-colonialism-6-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"每一位大人的一次迁移，人家就得布置整整一艘战舰，布置的费用就花了二十五万法郎，而这还没有把每一次迁移的零星支出八万法郎算在内呢！","language":"中文","translation":false},{"id":"ho-colonialism-6-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"总督老爷对他在西贡和河内的豪华别墅还不满意，而必须在海滨多建一座避暑的别墅。这就又要印度支那的预算挺起腰板去“负担”了。","language":"中文","translation":false},{"id":"ho-colonialism-6-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"19……年，有一名显贵的外宾到西贡来，总督老爷便立刻以亲王规格迎接他。接待的四天，便是狂欢盛宴、豪饮香槟的四天。而可怜的北圻就必须支付七万五千法郎。","language":"中文","translation":false},{"id":"ho-colonialism-6-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"统治老爷全是些小皇帝。他们想把什么东西都弄得奢侈华丽，他们说，唯有如此，才能在土著中提高自己的威信。某位统使老爷就曾成立了一支侍候他的侍卫马队，不论到哪儿，这一支马队总是护送着他。所有的公署都有六到十一匹马和五、六辆各式各样的气派的车子。除了这些绰绰有余的交通工具之外，人家还购置了一些华丽的汽车，花费了成万元公款。有位统使还养了整整一厩竞赛用的马。","language":"中文","translation":false},{"id":"ho-colonialism-6-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"这些人的房钱、桌椅、水电费，自有政府支付，除此之外，他们的车夫、司机、马夫、园丁，总之，他们内外的所有的仆人，全由政府支付工资。","language":"中文","translation":false},{"id":"ho-colonialism-6-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"这些幸运的老爷们的各项文化消遣开支，也都由政府清偿。某位统治老爷就曾在预算中列出取暖费九百元，买报费一千七百元！另一位耍了一下会计花招，把购买的衣架、钢琴和官太太的各种首饰，变成了修葺公署的物料，或是一项诸如此类的支出，堂而皇之记入国家预算！","language":"中文","translation":false},{"id":"ho-colonialism-6-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"纵然以前他们是卖粥的，或是学校里的学监，一旦来到殖民地，我们的各位文明传播者，便过着王公般的生活。有位统使老爷，叫五、六名蓝带兵为他牧羊。有的老爷，则叫有雕刻技能的士兵，坐下来为他雕刻些小巧玲珑的佛像，或用樟木制作很别致的箱子。","language":"中文","translation":false},{"id":"ho-colonialism-6-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"按规定，一名监兵只能用一名勤务兵，可是人家这样叙述道：有位监兵老爷曾经使用一名上士当他的管家、一名厨师、二名厨师的助手、三名仆役、一名近侍、三名园丁、一名车夫、一名马夫。","language":"中文","translation":false},{"id":"ho-colonialism-6-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"还有官太太，则使用一名裁缝、二名洗衣工人、一名刺绣工人、一名编织工人。","language":"中文","translation":false},{"id":"ho-colonialism-6-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"至于少爷，则有一名仆役，寸步不离地服侍他。","language":"中文","translation":false},{"id":"ho-colonialism-6-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第六章 国家机构的贪污舞弊","page":6,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/06.htm","text":"有一个亲眼看见的人这样说，在某位统治老爷家的一顿饭——只是便饭而不是什么宴会，每一位用餐者的背后都站着一名兵士，等待搬换碟子或上菜。而且餐厅里所有服侍的兵士，都由一名军士长指挥。","language":"中文","translation":false},{"id":"ho-colonialism-7-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-7-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“法国殖民主义寡头在掠夺了肥沃的田地之后，向那些贫瘠的土地征收的各种无理的税，百倍于封建时期的田税。”","language":"中文","translation":false},{"id":"ho-colonialism-7-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"当这个国家未被占领之前，各乡的田税，公私一律，人家都根据各种作物，把田地分成等级。每亩田的税率只从五角到一元，而每亩地则从一角二分到一元四角。“亩”是耕作的单位面积，每一边是一百五十尺。尺的长短不一定，要看是什么地方，有的一尺是四十二厘米，有的是四十七厘米，有的是六十四厘米。因此，每亩的面积就跟着地区的不同而互有不同：有些地方相等于三千九百七十平方米，有的是四千九百平方米，有的是六千二百平方米。","language":"中文","translation":false},{"id":"ho-colonialism-7-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"为了增加政府的收入，人家以一把四十厘米的尺作为测量的标准。这把尺比所有各种常用的尺都要短，所以，每亩的面积是三千六百平方米。以这种办法，田税的增加比例就跟着省份而不同，有的地方增加了十二分之一，有的增加了三分之一，最倒霉的地方竟增加了三分之二。","language":"中文","translation":false},{"id":"ho-colonialism-7-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"从1890年至1896年，直接税加了一倍，从1896年至1898年，这项税收又增加了50%。增加赋税的乡村都咬紧牙关苦挨。要不，向哪里申诉呢？征收得逞，统使老爷们就越加横征暴敛。许多法国人认为各乡这样乖乖地唯命是从，说明税额没有什么过分之处！","language":"中文","translation":false},{"id":"ho-colonialism-7-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"人头税从一角四分增到二元五角。那些尚未到纳税年龄的人，就是说，在十八岁以下的人，以前不用纳什么税，现在每人必须缴纳三角钱，就是说，比过去的壮丁人头税还多了一倍。","language":"中文","translation":false},{"id":"ho-colonialism-7-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"根据北圻统使1919年12月11日的法令，所有自十八岁至六十岁的土著，必须一律缴纳人头税二元五角钱。","language":"中文","translation":false},{"id":"ho-colonialism-7-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"安南人被迫必须把人头税税证随时带在身上，碰到有谁查问，就必须呈验。忘记带在身上或把证件丢失者，将被监禁。","language":"中文","translation":false},{"id":"ho-colonialism-7-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"为了弥补印度支那币贬值的差额，杜美总督老爷只须做一件简简单单的事，把纳税的人数增加就得了。","language":"中文","translation":false},{"id":"ho-colonialism-7-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"每年，人家早就分摊好每乡应缴纳一定的赋率额和一定的、各种等级的田税。要花更多的钱吗？那么，人家就任意修改数学。尽管是在年中，但人家强迫各乡必须纳足比年头已经规定的更多的壮丁税和田税。所以，北圻南定省只有十二万公顷田地，可是在新的统计表里却写成十二万二千公顷。这么一来，安南人民就必须为不存在地面上的田地缴纳一笔田税！叫屈吧，也没有谁去听你的！","language":"中文","translation":false},{"id":"ho-colonialism-7-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"沉重的税务不但压弯了你的腰，而且还经常改动。","language":"中文","translation":false},{"id":"ho-colonialism-7-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"一些商品流通税也有这种情形。再说，这样征税是不是公平呢？人家已经发给了一百五十公斤烟草的流通执照，在这之后，当这批烟草转到另一位顾主手里，或拿出来卖给三、四位顾客的时候，人家就多方摆弄，务使在同一件货物身上，能够抽取多次的税。税关老爷，则为所欲为，毫无法纪。因此，安南人很怕税关那一伙人。远远望见税关人员，他们就把挑在肩上的一整筐白盐、槟榔或是烟草抛弃在路上。宁愿这样抛弃掉，也不愿去纳各种各样老是纳不完的税。有些地方，人民被迫只好拔掉烟草、砍掉槟榔，以避免缴纳新税的麻烦。","language":"中文","translation":false},{"id":"ho-colonialism-7-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在琅勃拉邦（Louang-Prabang），有许多可怜的妇女，只因为无力纳税这个罪名，而必须带着锁链去打扫街道。","language":"中文","translation":false},{"id":"ho-colonialism-7-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"北圻北宁省（Bac-Ninh）的庄稼被涝灾所摧残，但仍须纳税五十万元。","language":"中文","translation":false},{"id":"ho-colonialism-7-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"你们已经听到印度支那莫里斯·朗老爷、殖民地部部长阿尔贝特·萨罗老爷和他们的报纸——他们至公无私的报纸，吹嘘印度支那公债的胜利。当然，他们是尽力避免谈采用了什么措施去取得这样的胜利的。他们怕泄漏了行家的秘诀，其实，这也是情有可原的。而这个秘诀是这样的：首先，他们用公债的利息去勾引那些天真的人，眼看这种手法没有什么苗头，他们就立刻强迫各乡必须卖掉公田，去买公债。这样还不够，他们又马上召来一些有油水的人，先交给每人一张收条，这么一来，这些人就只好四处奔走，凑足收条上写好的款子，拿去上缴。因为政府的保险箱深渊无底，而土著工商业家上缴的数字却有限，因此，这一笔强迫的借款对这些人来说，仍然不足塞满那一个深渊无底的保险箱。所以，那个惯于借钱的政府，就向那些已经被借得最多的人伸手要钱：他们强迫二、三、四个或者更多一些的穷人合买一张公债券。","language":"中文","translation":false},{"id":"ho-colonialism-7-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"下面这个例子说明了统治老爷们从土著的奥黛（caïao）里扒钱的惯用手法。","language":"中文","translation":false},{"id":"ho-colonialism-7-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"西区某省，在发行公债的前几个星期，省长召集了该省所有的正总。当翻译员把官老爷关于购买公债手续的晓谕翻译了之后，官老爷作出如下的结论：","language":"中文","translation":false},{"id":"ho-colonialism-7-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“就是这样。我的任务是解释，好让各位了解。现在你们签名买吧！”","language":"中文","translation":false},{"id":"ho-colonialism-7-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"说毕，这位高贵的“官大人”就转过头来，问他旁边的一名正总说：","language":"中文","translation":false},{"id":"ho-colonialism-7-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“那么，你能够买多少？”","language":"中文","translation":false},{"id":"ho-colonialism-7-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"可怜这位正总，突然被问，所以吞吞吐吐地说，因为还没有和总民接触，不知道他们的能力如何，所以还不能立刻说出购买多少公债的数字。","language":"中文","translation":false},{"id":"ho-colonialism-7-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“住口，你不配做正总！我把你革职！”","language":"中文","translation":false},{"id":"ho-colonialism-7-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"公债发行了。南圻统使老爷到各地视察，他停在一个省会，询问公债卖了多少。人家向他报告:","language":"中文","translation":false},{"id":"ho-colonialism-7-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"这个数字仿佛叫统使老爷不满意。因为这个省是南圻西区最富饶的一个省份。再说，在以前发行的各次公债中，这个省份购买的公债，不是都比这个数字多嘛。","language":"中文","translation":false},{"id":"ho-colonialism-7-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"统使老爷走了，参办老爷决定必须到全省去鼓动一番。参办老爷拜访了所有有枪的大户，强迫每个人必须按他的规定购买一些公债。为了让他们知道这不是开玩笑的，官老爷把他们的枪没收起来：","language":"中文","translation":false},{"id":"ho-colonialism-7-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“你要知道，如果你死赖不买，就别想老爷还你的枪！”","language":"中文","translation":false},{"id":"ho-colonialism-7-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"这么一来，就没有谁敢赖着不买了。","language":"中文","translation":false},{"id":"ho-colonialism-7-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"应该在这里顺便提到，就是这一位统治老爷，曾经支出三万块钱，修筑一条九公里长的公路，现在这条公路的路基已坍塌进附近的运河。但愿那条贯穿着印度支那的铁路，会比这公路有更好的命运。","language":"中文","translation":false},{"id":"ho-colonialism-7-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"人们正修建一座佛塔，工人全部是囚犯，由一个乡绅差遣。工人名单和每天的工票都填写得清清楚楚，承包经费也支付完毕。可是，这笔款子却塞进了统使老爷的腰包。","language":"中文","translation":false},{"id":"ho-colonialism-7-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"统使老爷最近还获得勋章呢！人们要进行募捐来庆祝这件授勋的事儿。所有的职员、干事、里长的捐献数额，事先已作出规定，最少是六元。收入总共是一万元。这个勋章是太值钱了！","language":"中文","translation":false},{"id":"ho-colonialism-7-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"批准承包供应搭几座木桥和建几间乡村学校的物资，也给我们这位清廉的统使老爷带来了一份二千元的薄礼。","language":"中文","translation":false},{"id":"ho-colonialism-7-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"给牛打烙印原是免费的，但是，统使老爷却准许打烙者每头收费五角至五元。礼尚往来，这班家伙每月也向老爷上缴二百元。","language":"中文","translation":false},{"id":"ho-colonialism-7-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"诡诈地分定田地等级，这位官老爷——人家刚给他别上勋章呢——又扒进四千元。","language":"中文","translation":false},{"id":"ho-colonialism-7-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"批准非法征收几公顷土地，官老爷的银柜又多了二千元。","language":"中文","translation":false},{"id":"ho-colonialism-7-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"作为一个文明传播者、爱国者、彻底主义者，统使老爷很懂得最有成效地利用胜利公债——记住，每一次大捷都发行一次公债券，而且，每一年都有那么一次大捷。1920年发行的公债中，有几个村子一共买了五万五千九百法郎的公债券。当时的汇兑率是一元等于十点二五法郎，这样，他们共付出了五千四百六十六元。1921年货币贬值，一元仅兑六法郎。那时统使老爷便慷慨地掏出五千四百六十六元还给各村，把公债券收为己有。后来印度支那市值回升，老爷一下就捞到了九千三百二十五元。","language":"中文","translation":false},{"id":"ho-colonialism-7-36","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":36,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"下面的消息我们摘自1921年12月22日法国《公报》：","language":"中文","translation":false},{"id":"ho-colonialism-7-37","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":37,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“在战争期间，许多非洲士兵曾给家庭邮寄汇票，日后合算起来成为一笔颇大的款子。但是，这些汇票从未送到收票者的手里。”","language":"中文","translation":false},{"id":"ho-colonialism-7-38","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":38,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"一位同行最近也告诉了我们一个类似的“现象”。这一回，事情发生于留尼汪岛（la Réunion）。几个月来，岛上人民没有收到寄给他们的任何邮件。报纸报道：","language":"中文","translation":false},{"id":"ho-colonialism-7-39","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":39,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“这个现象使得邮寄者和没有收到邮件者都感到惊奇。","language":"中文","translation":false},{"id":"ho-colonialism-7-40","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":40,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"许多人进行起诉。调查才刚开始，上述的神秘案件马上便一清二楚，同时还发现了一系列长期来周密的偷窃行为，真是令人五体投地。","language":"中文","translation":false},{"id":"ho-colonialism-7-41","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":41,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"人们逮捕了一个职员，又一个职员，然后轮到主任，最后，在全体职员都给戴上手铐后，邮电局局长也跟着大伙共赴铁窗。","language":"中文","translation":false},{"id":"ho-colonialism-7-42","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":42,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"每天的调查总带来一些新事件的真相。偷窃的邮件总值十二万五千法郎。会计收据全是伪造的。瞒报的账目乱七八糟，甚至要花半年的时间才能核实。","language":"中文","translation":false},{"id":"ho-colonialism-7-43","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":43,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在某些部门中，有时可能有个别品行不端的职员，但是很少会有整个部门从上而下都犯了偷窃的毛病，更令人费解的是，为什么这一伙窃贼竟能横行几年而又平安无事。”","language":"中文","translation":false},{"id":"ho-colonialism-7-44","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":44,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"国会正在讨论关于军事航空部门经费预算的法令草案。对于这一项经费，各个属地，就是说，土著们要勒紧腰带来承担（印度支那三十七万五千法郎，西非十万法郎）。在讨论时，阿尔及利亚议员莫里诺（Morinaud）曾经这样说：","language":"中文","translation":false},{"id":"ho-colonialism-7-45","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":45,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"“对于英勇的、立过显赫战功的法国人来说，曾经受到许多的歌颂，在这些歌颂之中，英国《泰晤士报》曾经认为那是神妙的战功。趁这个机会，诸位，请你们允许我继上述的赞颂，来表达我们大家对那些英勇的法国人的钦佩。同时，我们也应钦佩雪铁龙先生（Citroën）——一位无私的工业家，曾经毫不犹豫地在财政和技术上给他们以帮助。（掌声）","language":"中文","translation":false},{"id":"ho-colonialism-7-46","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":46,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在那伟大的事件之后发生了什么事情呢？那就是，设立在阿尔及利亚南部的各个据点，立刻订购了那些无与伦比的交通工具用于撒哈拉沙漠，而人们管它叫履带汽车。","language":"中文","translation":false},{"id":"ho-colonialism-7-47","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":47,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"图古尔特据点（Touggourt）和瓦尔格拉据点（Ouargla）最近订购了两辆——这个消息是阿尔及利亚总督刚告诉我的。","language":"中文","translation":false},{"id":"ho-colonialism-7-48","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":48,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"我们的其它据点当然也将及早购置那些东西。","language":"中文","translation":false},{"id":"ho-colonialism-7-49","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":49,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在短时间内，我们必须再设立四、五个新的据点，以便建成一个连成一线的据点群，约莫距离二百公里就有一个据点。","language":"中文","translation":false},{"id":"ho-colonialism-7-50","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":50,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"新的据点就要建立，同时新据点也将要订购履带车。这么一来，在撒哈拉所有的据点将能相互联络而不会有任何困难。各个据点也将保证彼此间的军需、粮食的输送能够更加方便。他们也能够经常收到书信。（掌声）”（摘自1923年元月22日《公报》）","language":"中文","translation":false},{"id":"ho-colonialism-7-51","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":51,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"人民不仅要为一些欧洲人举步舒适而去当伕役修筑统使公署四周的道路，而且统使老爷还随意强迫他们做其它更为繁重的活儿。","language":"中文","translation":false},{"id":"ho-colonialism-7-52","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":52,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"一听到殖民地部部长将来印度支那访问，人们便马上调集了一万民夫去抢修V.L路，使部长老爷能及时主持修成仪式。","language":"中文","translation":false},{"id":"ho-colonialism-7-53","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":53,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"18……年夏天，在饥荒摧残中圻中部之前的一段时间中，人家抓了一万民夫前去开挖河道，由当地的里长押解。到了地点，这支人数庞大的人群中，有许多人却无事可做。正当农务比任何时候都更需要他们的双手的时候，而人家仍要他们一个月又一个月地呆在那里。但这儿也必须看到的是，当人民遭受灾祸的时候，人家从没有调集过这么多的人力。18……年底，要是人家能从岘港（Tourane）起，给各个饥荒地区组织连续的赈灾运输线的话，那么，中圻的大多数饥民可免致冤死；而去挖河的一万服役民夫，在一个月内就可给各个受饥省份输送二千吨大米了。","language":"中文","translation":false},{"id":"ho-colonialism-7-54","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":54,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"岘港、镇宁（Tran-Ninh）和爱劳（Ai-Lao）等地公路的修筑，在大家心中留下不知多少痛苦的记忆。民夫要徒步走几百公里才到达工地。到了那儿，他们要钻进可怜的茅棚中住宿。没有丝毫卫生设备，也没有任何医疗组织。沿途没有歇脚处，也没有暂时寄宿的地方。他们只领到一份食不果腹的饭团和一些鱼干，渴了就喝那些山沟里的可怕的毒水。疾病、劳苦、残忍的折磨，使得工地上的死亡极为可怖。","language":"中文","translation":false},{"id":"ho-colonialism-7-55","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":55,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"如果人家不强迫人民去服劳役，就要征集他们去服伕役，两者之间的唯一的区别是，服劳役有期限，而服伕役则没有期限。这两种服役方式都是为解决全部的需求：海关要运载食盐时就征用船只；要修建仓库时就征集工人，甚至还乘机征用建筑材料。","language":"中文","translation":false},{"id":"ho-colonialism-7-56","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":56,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"特别是对民夫的征集，显然是一种恶劣的、变相的流放。人家不顾农时，连庙会、拜祭节日也在所不顾，逐村地驱迫全村人民到工地去。能重返家乡的人很少。再说，人家又何曾有过任何措施把民夫遣送回乡呢！","language":"中文","translation":false},{"id":"ho-colonialism-7-57","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":57,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"沿途尽是深林毒水，前头是死神等待的地方。整批整批的民夫都缺乏米粮，时常整天得不到一粒饭下肚。服劳役以及服伕役的民夫经常成批逃走，或者起来反抗，每当这样，他们总受到押解官兵的恐怖镇压，因而尸体遍陈路边。","language":"中文","translation":false},{"id":"ho-colonialism-7-58","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":58,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"兰比安（Langbian）统治当局接到了抓夫命令，执行命令时，人家把正在码头打工的土著全部抓起来，捆绑好后推下船去。","language":"中文","translation":false},{"id":"ho-colonialism-7-59","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":59,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"贫苦的老挝（Laos）土著，经常生活在生怕被拉去服劳役的惴惴不安的境况中。每当官兵前去抓夫时，只看到空空荡荡的房子，因为他们早就抛弃家园溜走了。","language":"中文","translation":false},{"id":"ho-colonialism-7-60","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":60,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"土龙木（Thudaumot）的统治老爷需要一台压路机，怎么办呢？老爷便同一家正需要廉价人工的承包公司商量。这家公司出钱买了一台价值一万三千五百法郎的压路机送给官老爷。统治大人便立刻强迫人民替那家公司服劳役，以抵偿购买压路机的款项，每一日工的代价是半个法郎。一连三年，土龙木人民要服从那家公司的差遣，要以服劳役来清还官老爷为修葺自己的花园而购买的压路机的款项。","language":"中文","translation":false},{"id":"ho-colonialism-7-61","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":61,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在另外一个省份，民夫干完一天的劳役后，还要无偿地在一公里长的路上挑石子，用以修筑统使公署的围墙。","language":"中文","translation":false},{"id":"ho-colonialism-7-62","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":62,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"这样，就是说，不论在什么时候，安南人民随时都可以被抓去和被迫做最辛苦的活儿，而饭又吃不饱，工钱却十分低廉，他们受到无限期的征集，然后被抛送到远离故乡几百公里外的地方去。","language":"中文","translation":false},{"id":"ho-colonialism-7-63","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":63,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"一般来说，安南人都要咬紧牙关来承受法国的保护恩德。另一方面来说，安南农民更要咬紧牙关承受这种更为悲惨的保护：作为安南人，他们受压迫；作为农民，他们被抢夺。正是他们要服一切的劳役，正是他们以劳动的果实供给那伙寄生者、文明传播者以及其他之流享受。当他们的刽子手过得惬意的时候，而他们却要过着贫困的生活，一旦失收就要饿死。这是因为他们受到国家的、新型的封建势力的、教会的、各方面的以及各种方式的盗窃。过去，根据安南的制度则把田地按优劣分等级，赋税也是按等级来收的。但是，在现在的殖民地制度下，所有上述一切都改变了。需要捞钱的时候，法国统治老爷们只需动手把田地等级改一改就行了。只要它们挥动神妙的一笔，就会把一片瘠地变成良田。","language":"中文","translation":false},{"id":"ho-colonialism-7-64","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":64,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"这样还不够，人家还通过缩短度量工具，虚加田地面积。就这样，赋税立即增加，有些地方增加三分之一，有些地方增加三分之二。虽是这样，仍不能满足保护当局的深渊无底的欲望，因而赋税还逐年增加。例如，从1890年到1896年，赋税增加了一倍。从1896年到1898年又增加了一半，而且老是这样的不断的增加着。安南人的骨髓让人家不断的吸吮，而我们的保护老爷们也吃惯了甜头，一味玩着剥削的花招。","language":"中文","translation":false},{"id":"ho-colonialism-7-65","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":65,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"1895年，北圻某省的统使，曾经没收了某乡的大片田地，转让给另一个信奉天主教的乡村。那些失去田地的人要是上诉，就被抓去坐牢。你们别以为这个不顾廉耻的统治制度仅止于此。它们还强迫那些倒霉的失去田地的人要一直纳税到1910年，尽管他们的田地早在1895年就给抢夺去了。","language":"中文","translation":false},{"id":"ho-colonialism-7-66","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":66,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"继行政盗窃之后，又轮到那伙庄园主进行盗窃。那些仅凭大肚皮和白皮肤就能获得土地的欧洲人，动辄就能分给一块经常超过二万公顷的广阔无垠的庄园。","language":"中文","translation":false},{"id":"ho-colonialism-7-67","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":67,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"这些庄园多数是通过公开的盗窃建立起来的。在被侵略时期，像1870年的阿尔萨斯人一样，安南农民抛弃了自己的田园疏散到还有自由的地区。当他们回来的时候，他们的田园早已变成“庄园”了。无数的村庄就这样被抢夺去，而土著也从而陷入要为那伙新型的封建主卖力的境况中，这班家伙的掠夺有时占收成的百分之九十。","language":"中文","translation":false},{"id":"ho-colonialism-7-68","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":68,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"借口鼓励对殖民地的开垦，人家给许多大庄园主免除缴纳田地税。","language":"中文","translation":false},{"id":"ho-colonialism-7-69","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":69,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"无偿地拿到田地以后，庄园主们还不花一钱或者几乎是不花一钱地找到工人。统治老爷们给他们押来一批苦役囚犯作无偿的干活，或者依仗权力，以饿死人的工资招募来一些工人。要是来做工的人数不足或不愿意做工，人家就使用武力；庄园主们把村的里长们抓来，扼住他们的喉咙，虐打他们，直至这些倒霉的人在关于交出需要的工人数额的保证书上签了名才罢休。","language":"中文","translation":false},{"id":"ho-colonialism-7-70","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":70,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在这个尘世间的势力的一边，还有挽救灵魂之辈，这些“圣人”在向安南人宣传安贫之道的同时，也念念不忘拿土著的血汗来发财致富。在南圻，仅圣使会（Sainte Mission apostolique）就占有本区的五分之一的田地。虽然《圣经》中没有传授抢夺田地的手段，可是也极其简单：这就是向农民放高利贷和向农民索贿的手段。教会利用歉收的时候给农民贷款，并强迫他们以田地作抵押。由于重利盘剥，因此安南人不能按时清还债务，他们所抵押的田地，就这样落到教会的手里去了。","language":"中文","translation":false},{"id":"ho-colonialism-7-71","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":71,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"母国把印度支那的命运交托给那伙大大小小的统治老爷们，一般来说，他们都是些愚蠢和无赖之徒。教会只要掌握到对统治老爷们的名誉地位具有影响的有关私生活的一些秘密材料，就可以使官老爷们提心吊胆，并听从教会的意图。正是这样，一位总督老爷曾把土著的七千公顷河岸地割给教会。这么一来，这些土著瞬间沦为乞丐。","language":"中文","translation":false},{"id":"ho-colonialism-7-72","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":72,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"透过这些片段，我们可以看到，在民主的幌子下，法兰西帝国主义带到安南的是一整套中古时代的可诅咒的制度（包括盐税制度），安南农民既在资本主义文明的刺刀下，又在娼妓一般的教会的十字架下活活受罪。","language":"中文","translation":false},{"id":"ho-colonialism-7-73","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":73,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"阿尔及利亚发生了饥馑。接着，突尼斯也受到饥馑的摧残。为消除这个情况，政府拘禁了大批饥民。为使“饥民”们不要把监牢看成是疗养所，人家什么东西也不给他们吃。因此，许多人在被监禁期间饿死了。在埃尔吉里亚（El Ghiria）的山洞中，许多饿得发疯的人，不得不把一头死了许多天的骡子拿来充饥。","language":"中文","translation":false},{"id":"ho-colonialism-7-74","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":74,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在贝贾（Béjà），佃农（Khammés）要同乌鸦抢夺动物残骸吃。","language":"中文","translation":false},{"id":"ho-colonialism-7-75","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":75,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在苏克阿尔巴（Souk El Arba），在吉达（Ghida），在瓦德米尔兹（Oued Milze），每天都有几十名土著饿死。","language":"中文","translation":false},{"id":"ho-colonialism-7-76","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":76,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"伴随着饥荒，斑疹伤寒在多地爆发，并持续蔓延着。","language":"中文","translation":false},{"id":"ho-colonialism-7-77","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":77,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"为了掩饰那杀人的剥削制度的丑恶，殖民地资本主义经常以所谓“博爱”、“平等”等理想的格言来装点那腐朽的招牌。","language":"中文","translation":false},{"id":"ho-colonialism-7-78","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":78,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在同一个工厂做同样的工，白人工人领取的工资大大高过其他肤色的工人。","language":"中文","translation":false},{"id":"ho-colonialism-7-79","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":79,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"在各机关中，土著即使工作多年，即使工作很熟练，仍旧是领取一笔会饿死人的工资，但是一个白人虽然刚来工作，工作量少，反而领取更多的工资。","language":"中文","translation":false},{"id":"ho-colonialism-7-80","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":80,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"有一些土著青年曾在宗主国各个大学念过书，并且考取了医学博士或法学学士，可是，仍不能在自己的国家搞自己的专业，如果不加入法国国籍的话。大家知道，一个土著要加入法国国籍是多么困难和耻辱啊！","language":"中文","translation":false},{"id":"ho-colonialism-7-81","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":81,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"土著当兵，要抛弃田园庐舍，登记为“志愿兵”，他们已经尝到了那种美妙的“平等”的味儿了。","language":"中文","translation":false},{"id":"ho-colonialism-7-82","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":82,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"同样是一个级别，白人军官几乎任何时候都被看作是土著军官的上级。这个“种族-军阶”等级的区别待遇制度，在白人士兵和不同肤色士兵同搭火车或轮船的时候更为显著。","language":"中文","translation":false},{"id":"ho-colonialism-7-83","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":83,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"一个土著，怎样才能加入法国国籍呢？","language":"中文","translation":false},{"id":"ho-colonialism-7-84","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":84,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"1915年3月25日颁布的关于殖民地人民加入法国国籍的法令曾经规定如下：","language":"中文","translation":false},{"id":"ho-colonialism-7-85","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":85,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"第一条：凡居住在法国的保护国的殖民地人民，年龄在二十一岁以上，原籍不是阿尔及利亚、突尼斯或摩洛哥，并且曾经在法国本土、阿尔及利亚或者法国的保护地居住者，具备下列条件中之一条，就可以享受到法国公民的权利：","language":"中文","translation":false},{"id":"ho-colonialism-7-86","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":86,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"（一）曾经获得荣誉军团勋章或者在法令规定的大学和高等专业学校毕业者。","language":"中文","translation":false},{"id":"ho-colonialism-7-87","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":87,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"（二）在开拓殖民地或服务于法国利益中立过大功者。","language":"中文","translation":false},{"id":"ho-colonialism-7-88","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":88,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"（三）曾经在法国军队中服役并且担任过军官或下级军官职务，或者曾获得军功勋章者。","language":"中文","translation":false},{"id":"ho-colonialism-7-89","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":89,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"（四）已娶法国妻子并且在法国本土居住期满一年者。","language":"中文","translation":false},{"id":"ho-colonialism-7-90","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":90,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"（五）曾经在上述地区居住十年，并且在相当程度上通晓法语者。","language":"中文","translation":false},{"id":"ho-colonialism-7-91","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":91,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"这条法令虽然还有欠缺，但是，如果能够真正执行倒还算好。但是，不，官员老爷们哪里会理睬法律，他们倒像是一伙挑剔的傻瓜，偏要那些申请加入法国国籍的人书面回答如下的问题：","language":"中文","translation":false},{"id":"ho-colonialism-7-92","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":92,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"A——你的夫人和孩子会说法国话吗？","language":"中文","translation":false},{"id":"ho-colonialism-7-93","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":93,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"B——她们都穿欧洲服装吗？","language":"中文","translation":false},{"id":"ho-colonialism-7-94","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":94,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"C——你的家里有桌子、衣橱吗？","language":"中文","translation":false},{"id":"ho-colonialism-7-95","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":95,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"E——你进餐时是在桌子上还是在草席上？","language":"中文","translation":false},{"id":"ho-colonialism-7-96","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":96,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"F——你吃的是什么东西？","language":"中文","translation":false},{"id":"ho-colonialism-7-97","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":97,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"G——你吃米饭还是吃面包？","language":"中文","translation":false},{"id":"ho-colonialism-7-98","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":98,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"I——你的妻子有财产吗？","language":"中文","translation":false},{"id":"ho-colonialism-7-99","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":99,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"J——你每年平均收入多少？","language":"中文","translation":false},{"id":"ho-colonialism-7-100","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":100,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"L——你参加过什么会社？","language":"中文","translation":false},{"id":"ho-colonialism-7-101","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":101,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"M——你在这个会社里担任什么职务？","language":"中文","translation":false},{"id":"ho-colonialism-7-102","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":102,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"N——对土著的制度既好又仁慈，那么，你为什么要请求加入法国国籍？是不是为了当官？或者是为了更高的地位？或者是为了淘金探矿？","language":"中文","translation":false},{"id":"ho-colonialism-7-103","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":103,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"O——你最要好的朋友是些什么人？","language":"中文","translation":false},{"id":"ho-colonialism-7-104","author":"胡志明","title":"法国殖民制度的罪状","location":"第七章 剥削土著","page":7,"paragraph":104,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/07.htm","text":"只欠一条老爷们还未提问的是：你的老婆有没有给你戴绿帽子？！","language":"中文","translation":false},{"id":"ho-colonialism-8-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-8-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"人们曾经强迫芽庄（Nha Trang，属中圻）监牢的犯人要干吃，即只吃饭而不得喝水，这是不是如萨罗先生多次宣称的那样是因为人道主义精神太高呢？人们把碘酒涂在犯人的鼻子上，是否为了他们一旦越狱逃走容易认出来？","language":"中文","translation":false},{"id":"ho-colonialism-8-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"1921年7月13日在马达加斯加出版的《独立报》（L'Indépendant），曾刊登一篇关于预防“鼠疫”的方法的详细报道，我们摘录其中一段如后：","language":"中文","translation":false},{"id":"ho-colonialism-8-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"“无数茅屋给烧掉了，其中有加利埃尼街（rue Galliéni）上的拉哥多曼加（Rakotomanga）的颇漂亮的房子，也在星期一那天给烧毁了。德罗（Desraux）先生的房子却免受同样的命运，算起来这个房子和全部家私太值钱了（五万法郎），因此，当局决定不予烧掉，只进行消毒除秽，并在一段长时间——大概是半年而已——禁止居住。”","language":"中文","translation":false},{"id":"ho-colonialism-8-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"请允许我们补充说，德罗先生是法国公民，而拉哥多曼加先生则是土著。我们还要提请读者记住的是，制定1841号法令，对所有的法国公民也是适用的。","language":"中文","translation":false},{"id":"ho-colonialism-8-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"也是在马达加斯加，在法国殖民主义者德拉罗什（Delaroche）的庄园里，六个土著以不纳税的罪名被抓去了。在法庭前，被告者供说，庄园主德拉罗什曾向他们保证：","language":"中文","translation":false},{"id":"ho-colonialism-8-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"（二）替他们申请免赋役；","language":"中文","translation":false},{"id":"ho-colonialism-8-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"（三）每三十天付给他们工资十法郎。","language":"中文","translation":false},{"id":"ho-colonialism-8-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"必须注意的是，庄园主每周仅雇他们打一天工而已。","language":"中文","translation":false},{"id":"ho-colonialism-8-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"要维持生活，他们要替住在庄园附近的一些马尔加什人打工。另一方面，德拉罗什先生不但不践约，不替他们纳税，而且还把他们托他代为缴税的钱也含糊过去了。","language":"中文","translation":false},{"id":"ho-colonialism-8-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"多么难能可贵呀，这一回，政府要进行调查。但是读者且看……","language":"中文","translation":false},{"id":"ho-colonialism-8-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"在马哈努鲁（Mahanoro）的农业行业公会——而德拉罗什先生准会是个会员——获悉后，立即打电报给总督老爷，抗议警察不合时宜地侵犯了德拉罗什先生的庄园，并且要求以胆敢揭发一个法国人对几个土著的不干不净的事端的罪名，来惩罚警长。","language":"中文","translation":false},{"id":"ho-colonialism-8-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"为了不愿替自己“找麻烦”，总督老爷干脆利落地压下了这桩丑闻。","language":"中文","translation":false},{"id":"ho-colonialism-8-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"里尔（Lille）的军事法庭最近判处一名德国军官冯·舍文（Von Scheven）以二十年苦役徒刑，因为在德军占领期间，他曾用皮鞭鞭挞龙克（Roncq）的土著。","language":"中文","translation":false},{"id":"ho-colonialism-8-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"至于在印度支那，这位法国人曾用手枪打爆了一个安南人的脑袋；那位法国职员曾把一个北圻人野蛮地捶打后关进狗笼；这位法国承包商放狗撕咬一个南圻人，然后把他杀死；那位法国机师用猎枪“干掉”一个安南人；这位法国海军人员把一个守桥者推进正燃烧的煤堆而烧死，等等，等等，那又为什么所有这些家伙倒没有受到惩治呢？","language":"中文","translation":false},{"id":"ho-colonialism-8-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"至于在阿尔及利亚的几位法国少爷把一个十三岁的土著孩子加以拳打脚踢后，再把他插在围绕着“战胜树”的一排尖枪中的一枝尖枪上，为什么只罚这些少爷们坐八天牢，而且还得到缓刑呢？","language":"中文","translation":false},{"id":"ho-colonialism-8-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"还有，为什么那位下级军官殴打了纳洪，又把他杀死了，仍然没有谁动一动那位军官的一根毫毛？","language":"中文","translation":false},{"id":"ho-colonialism-8-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"诚然，安南和阿尔及利亚是被占领地，正如龙格一样，但是，在各属地的法国人诚非“日耳曼蛮子”，因而，同一的事件，要是“蛮子”干出来，那就是罪恶，但如果是法国人干出来，那倒是个文明的行为了！而且，安南佬和阿尔及利亚佬哪能算是人！？他们都是些下贱的“乡下佬”，是些肮脏的“小羔羊”。对于此辈，岂有公理可言哉！","language":"中文","translation":false},{"id":"ho-colonialism-8-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"那个顶幽默的维涅·多克顿先生真不错，他这么写道：“对土著讲法律、公理吗？算了吧！只有手杖、短枪、步枪，才同这些虫豸相称！”","language":"中文","translation":false},{"id":"ho-colonialism-8-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"在强加给土著头上的十分齐全的刑罚仓库里，人们会见到有些案件罚款从二百到三千元。","language":"中文","translation":false},{"id":"ho-colonialism-8-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"杜美老爷心知肚明，安南人根本无力支付如此巨款。但是，这位“精明人”为想捞钱捞到底，因此，他已预先规定：乡邻将连带要对罪犯负责任（第四条）。","language":"中文","translation":false},{"id":"ho-colonialism-8-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"也许你会说，要对整个村子起诉，总得证明其与罪犯共谋吧。","language":"中文","translation":false},{"id":"ho-colonialism-8-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"不是的，对于第四条则用不着这么做。哪一个村子不懂得杜绝人们犯罪的方法，则这个村子要与犯人一起承担责任。","language":"中文","translation":false},{"id":"ho-colonialism-8-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"这个第四条真的是古怪、毒辣，因为只要有了包税商的爪牙们——这些家伙被收买来告发犯罪行为，越多越好——供出本村不曾作出任何措施来制止各种犯法行为，那就够了。","language":"中文","translation":false},{"id":"ho-colonialism-8-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"法令中第三条规定了关于记录各犯罪案件的方式，而这班包税商的爪牙们是有权做记录的。","language":"中文","translation":false},{"id":"ho-colonialism-8-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"但是，关于这一项却有点不顺手。这班爪牙通常是没有文化的笨蛋，所做的案件记录不合格式。人家克服这个困难的方法是指派省会海关署的职员，根据上述包税商爪牙的报告来做记录。","language":"中文","translation":false},{"id":"ho-colonialism-8-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"印度支那是一位受宠爱的姑娘，配作法兰西母国的孩子。母亲有什么，孩子也有什么：印度支那也有政府、有债务、有法庭，甚至也有叛乱阴谋。下面我们只谈最后的两种：","language":"中文","translation":false},{"id":"ho-colonialism-8-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"公理通常以一个一手拿天平，一手握利剑的威严妇人作为象征。由于从法国到印度支那路途过于遥远，因为路远以至于到了印度支那的时候天平就失去了平衡，天平盘溶化成一些鸦片烟枪或变成一些劣酒酒瓶，因而那位可怜的公理妇人手里仅剩下一把剑用来屠杀了。她甚至连那些无辜者都屠杀，尤其爱斩杀无辜者。","language":"中文","translation":false},{"id":"ho-colonialism-8-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"至于叛乱阴谋，那又是另一回事。","language":"中文","translation":false},{"id":"ho-colonialism-8-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"我们不必重提1908年和1916年尽人皆知的事变，这些事变使得受法国保护的无数人民，在断头台上、监牢中和流放地享受开化的恩泽。这些叛乱事件已过去太久了，它只是永远烙在土著的记忆里而已。","language":"中文","translation":false},{"id":"ho-colonialism-8-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"我们只谈新近发生的事件。因为在母国发生了布尔什维克的叛乱，震动了舆论，因此在印度支那的殖民主义者——像寓言中所说的青蛙一样——也想自己有个叛乱事件，老爷们于是用力鼓胀肚皮，并且最后也捏造出一个事件来。","language":"中文","translation":false},{"id":"ho-colonialism-8-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"一位法国大官（禀告老爷，是大法兰西的统使呢）、一位知县和一位里长曾经接受制造这个事件的任务。","language":"中文","translation":false},{"id":"ho-colonialism-8-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"这个行政“三位一体”造谣说一批叛乱分子已经埋下了二百五十颗炸弹，以便炸毁北圻全境。","language":"中文","translation":false},{"id":"ho-colonialism-8-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"但是在2月16日，河内市检察委员会却认为，绝对没有任何证据可作出存在一个备有破坏武器的革命组织的结论；不但这样，它还宣称，这个阴谋叛乱事件，不外是一些政府官员为了要捞取奖赏而制造出来的具有挑衅性质的假案件而已。","language":"中文","translation":false},{"id":"ho-colonialism-8-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"朋友，也许你认为在法庭这样宣布以后，被监禁的安南人将得到释放了。不！无论如何也得保持征服者的威信呀！为此，人们不仅给那些善于捏造案件之辈授予勋章，而且还判处十二个安南人坐两年到五年牢，这些人大多数是汉学家。在囚禁他们的狱门上，人们看到这样的字样：自由、平等、博爱——当然是用法文写的。","language":"中文","translation":false},{"id":"ho-colonialism-8-36","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":36,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"于是乎那些所谓亲土著的报纸慌忙歌颂一番这个光明正大的事件——公理的谐剧！","language":"中文","translation":false},{"id":"ho-colonialism-8-37","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":37,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"请读一读《殖民地消息报》（Dépêche coloniale）——以反安南主义夺标的报纸：","language":"中文","translation":false},{"id":"ho-colonialism-8-38","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":38,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"“法国法庭已经宣判，半数被告得到释放，其余判处轻刑。犯人都是些汉学老学究，犯了抒写不三不四的感兴诗来歌颂自由之罪。”","language":"中文","translation":false},{"id":"ho-colonialism-8-39","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":39,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"读者看见了吧，对于安南人来说，歌颂自由倒是一种罪恶，因而人们把他们抓去坐五年牢也仅仅是因为歌颂了自由而已！","language":"中文","translation":false},{"id":"ho-colonialism-8-40","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":40,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"也是上述报纸接着写道：“我们应当感到高兴，当看到我们的法官、陪审官的那篇大公无私的判决书……。”","language":"中文","translation":false},{"id":"ho-colonialism-8-41","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":41,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"《殖民地消息报》并且还高兴地提起法国法庭对于永安（Vinh-Yên）叛乱案的绝等无私的判决。这家报纸写道：“在巴黎的安南人以及他们国内的同胞都表示信任我们的法官，并且宣称法庭判处得对，案件这样判决使他们完全满意。”——得了吧，普武维尔老爷（Pouvourville），阁下扯得谎未免也太离谱啦！","language":"中文","translation":false},{"id":"ho-colonialism-8-42","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":42,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"《法属印度支那报》（France-Indochine）的报道了如下事件：","language":"中文","translation":false},{"id":"ho-colonialism-8-43","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":43,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"“前几天，索瓦热公司（maison Sauvage）报告密探局说，公司失窃约一吨铁材。密探局接到报告后当即进行调查，以便抓捕窃贼，同时我们高兴地获悉一位警探在几个安南人员的协助下已经抓到那伙窃贼及其同谋者。","language":"中文","translation":false},{"id":"ho-colonialism-8-44","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":44,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"索瓦热公司管理员S先生和见习机工陈文禄（Tran-van-Loc）、陈文舍（Tran-van-Xa）等辈以偷窃和串通的罪名被押往法庭。”","language":"中文","translation":false},{"id":"ho-colonialism-8-45","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":45,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"读者是否留意到，我们的同业者是多么的仔细入微吗？提到法国贼老爷索瓦热公司管理员的时候，人们不提其姓名，而代之以几个省略号。高等民族的威信，无论如何也应首先加以维护。但是提到安南贼子的时候，人们就列姓道名，并且不称为先生，而称之为“等辈”了。","language":"中文","translation":false},{"id":"ho-colonialism-8-46","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":46,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"1922年10月10日，政府颁布对殖民地法官的重大嘉奖晋升令。在获擢升的名单里，我们注意到卢卡斯（Lucas）和瓦布兰（Wabrand）两位老爷。","language":"中文","translation":false},{"id":"ho-colonialism-8-47","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":47,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"有必要提及这两位法官的简历。","language":"中文","translation":false},{"id":"ho-colonialism-8-48","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":48,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"卢卡斯老爷在法属西非任副检察官的时候，他同那些使得多哥（Togo）舆论哗然的各个案件有着关联。在发给报界的一份公报中，殖民地部部长也不得不承认：“在调查中发现，关于卢卡斯先生在该案件中的参与行为，将使他要承担部分极重大的责任。”","language":"中文","translation":false},{"id":"ho-colonialism-8-49","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":49,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"也许为了奖励这部分极重大的责任，因而现在人们提拔他担任法属赤道非洲（A.E.F.）上诉法院院长。","language":"中文","translation":false},{"id":"ho-colonialism-8-50","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":50,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"至于瓦布兰老爷的简历则比较简单些，并且没有那么显赫。1920年，一个名叫迪尔格里（Durgrie）的法国人——康康（Kankan，属几内亚）佩里萨克公司（maison de commerce Peyrissac）的职员——去打猎。一只鸟儿被他打中，掉到河里。这时，刚好一个土著孩子经过。迪尔格里揪住孩子抛进河里，要他把鸟儿捞起来。水又深，浪又大，小孩子不会游泳，终于溺死了。这孩子的父母进行控告。郡军队的少校指挥官召见迪尔格里，迪尔格里答应给孩子的父母赔偿一百法郎。","language":"中文","translation":false},{"id":"ho-colonialism-8-51","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":51,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"孩子的父母不肯接受这种卑鄙的处理。少校一怒之下，便站在自己的同胞，即那个杀人犯一边，恐吓要把孩子的父母抓去坐牢，要是他们还继续控告杀人犯的话。于是他把案件搁了下来。","language":"中文","translation":false},{"id":"ho-colonialism-8-52","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":52,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"但是，一封匿名信曾就这个案件向达喀尔高等检察官告发。高等检察官派遣检察官瓦布兰前去调查。瓦布兰来到康康，睡在车站站长的家里，到第二天便同少校的副手拉瓦利埃·德库赞（de Cousin de Lavallière）玩了一天。第三天早上，瓦布兰什么也不曾调查，便启程回去了。虽是这样，瓦布兰却作出结论说，那封匿名的信是诬告。殖民地联合会（Union intercoloniale）于1921年12月22日曾就这个案件向人权协会报告。但也许人权协会认为这不是什么震动舆论的事情，因而并不为此操心。","language":"中文","translation":false},{"id":"ho-colonialism-8-53","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":53,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"自从在康康游玩回来后，瓦布兰仍然安坐在原来的职位上等待升官，并且不时收到他的朋友拉瓦利埃·德库赞送来的鸡和一袋袋马铃薯。读者看到了吧，瓦布兰老爷实在值得提拔和被委任为达喀尔的检察官呀！","language":"中文","translation":false},{"id":"ho-colonialism-8-54","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":54,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"把那种高超的文明交给达尔勒、博杜安、瓦布兰、卢卡斯等老爷掌握，实在是最妙不过，至于土著的命运则更不消说了！","language":"中文","translation":false},{"id":"ho-colonialism-8-55","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":55,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"法庭最近以收藏、转运和出售一公斤鸦片的罪名，判处费尔南·埃斯兰（Fernand Esselin）和寡妇叶尔（veuve Gère）每人十三个月徒刑，乔治·科尔迪耶（Georges Cordier）十个月徒刑。","language":"中文","translation":false},{"id":"ho-colonialism-8-56","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":56,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"好极了！初步计算就足以看到，一公斤鸦片便等于三十六个月的徒刑！","language":"中文","translation":false},{"id":"ho-colonialism-8-57","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":57,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"如果法律真像人们所常说的那样是人人平等的话，那么，印度支那总督萨罗老爷恐怕需要长生不老才能服完他的刑期。因为每一年都要判处他五百四十万个月的徒刑，原因是他每年都要向安南人倾销十五万多公斤鸦片。","language":"中文","translation":false},{"id":"ho-colonialism-8-58","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":58,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"他们对于始终无法剿灭的著名义军领袖黄花探先生（Dê Tham）束手无策，无论是暗杀、投毒还是爆破都未能得逞，于是殖民当局竟把他父母的坟墓掘起，把骸骨抛到河里去。","language":"中文","translation":false},{"id":"ho-colonialism-8-59","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":59,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"在中圻南区各次游行示威发生以后，许多文绅被判处死刑和流放。其中有进士陈贵哈先生（Tranqui-Cap），他是一个人人敬佩的清高的汉学家。陈先生是在给学生讲课的时候给抓去的。不经过任何审讯，就在他被抓去二十四小时之后被人家杀头。他的尸体，政府也不肯交还其亲人。","language":"中文","translation":false},{"id":"ho-colonialism-8-60","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":60,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"在海阳省（Haï-duong），只因发生了一场没有伤亡的骚动，就这样人家不用经过任何审讯就使六十四颗头颅落了地。","language":"中文","translation":false},{"id":"ho-colonialism-8-61","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":61,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"在对河内的散兵（tirailleurs）执刑时，政府押解他们的父母妻儿来到法场，要他们亲眼看到自己的骨肉亲人被杀害的情景。为了要留下个长久的恐怖印象，要“教育民众”，他们重复干出了十八世纪时人们在英国所干出的勾当，即把战败的詹姆斯党人（Jacobites）的头颅插在木桩尖上，沿着伦敦桥（pont de Londres）和金融城（Cité）街区摆着。在河内市各大街道沿途上，被杀死的士兵的头颅，也在许多竹竿上皱眉苦脸、整周地摆着。","language":"中文","translation":false},{"id":"ho-colonialism-8-62","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":62,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"1908年，中部人民因受不了说不尽的捐税和虐待的压迫，因而举行了游行示威。各次游行示威的进行都是和平的。但当局却倾尽全力加以镇压。被杀头的人数以百计，被流放的人难以计算。","language":"中文","translation":false},{"id":"ho-colonialism-8-63","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":63,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"人们还千方百计地来武装安南人，以安南人制安南人，同时奖励背叛行为。","language":"中文","translation":false},{"id":"ho-colonialism-8-64","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":64,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"哪一个乡辖地区里发生了骚动，人们就宣布那一个乡要负责任。哪一个乡让爱国者寄居，那一个乡就要受到处罚。为要迫使乡里告发，人们采用的唯一和简单的方法是，把乡绅、里长们召来问话，哪一个不供，人们立刻把他枪决。就这样，在约两周中，一个监兵官员就杀死了七十五位乡绅。","language":"中文","translation":false},{"id":"ho-colonialism-8-65","author":"胡志明","title":"法国殖民制度的罪状","location":"第八章 公理","page":8,"paragraph":65,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/08.htm","text":"人们从来不把正在进行绝望战斗的爱国者同城市里的流氓、凶手区别开来。为了扑灭人民的反抗，人们找不出更好的办法来，只能把“绥靖”工作交给一班卖国的叛徒。因此，一队队穷凶极恶的狗腿子，深入到红河三角洲（Delta）、平顺（Binh-thuan）和义静地区（Nghê-Tinh）进行扫荡，——这般可憎的恐怖形象，即使万世以后仍不会泯灭。","language":"中文","translation":false},{"id":"ho-colonialism-9-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-9-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"垄断资本家不但用劣酒和鸦片来麻醉安南人民，他们还施行了彻底的愚民政策，企图蒙蔽法国的舆论，借以在殖民地任意剥削。","language":"中文","translation":false},{"id":"ho-colonialism-9-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"因此，根据1898年的法令，印度支那的报刊在付印前要接受检查。","language":"中文","translation":false},{"id":"ho-colonialism-9-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"法令规定：“关于某一报纸或定期出版物的发行，不论其用何种文字，都可以根据总督的决定而被禁止。","language":"中文","translation":false},{"id":"ho-colonialism-9-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"如未取得总督的许可，任何安南文报纸均不得出版。取得许可证的条件是，报纸刊登的原稿必须经过总督的审阅批准。许可证随时均可撤销。","language":"中文","translation":false},{"id":"ho-colonialism-9-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"各种歌曲、图片、图画的展览或发行，如有损害到当局的尊严者，将受到惩治。”","language":"中文","translation":false},{"id":"ho-colonialism-9-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"读者可看到，殖民地的审查女神手拿剪刀是多么熟练呀！","language":"中文","translation":false},{"id":"ho-colonialism-9-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"正是通过这种检查方法，印度支那政府可以掩盖一切肮脏的东西，和任意滥用权力。","language":"中文","translation":false},{"id":"ho-colonialism-9-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"在西贡市议会的选举中，总督老爷竟禁止三位安南文报纸主编刊登关于南圻各城市议会选举条例规定的法令。他们是候选人，但是他们的报纸却被严禁不得刊登同他们的政纲有关联的稿件，不管是直接的还是间接的。因为安南人无权举行超过二十人的集会，而选民人数却达三千人，因此候选人只得逐个地同选民会见。与此同时，总督老爷还通知其他各报说，凡是谈到殖民地议会和乡议会的选举的文章、专栏、标题以及影射的词句，检查局将不客气地剪掉。一张安南文报纸译登了关于惩治在选举中进行收买行为的法令，这篇东西立刻被剪去。同时，总督老爷还公然召集选民代表来到他的办公室，传令他们要投和鼓动选民投那些最得到他好感的人的票。","language":"中文","translation":false},{"id":"ho-colonialism-9-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"审查女神的卑鄙之手不但压住安南文书报，它还伸到私人信件以及那些不愿歌颂殖民地大老爷们功德的法文报纸。南圻邮电局和密探局（这个局的局长是阿尔贝特·萨罗老爷的女婿）接到命令，无论如何不得让各种信件、文章等寄到刚在巴黎出版的《穷苦人报》（Le Paria）或者让这家报纸的东西偷寄出来。","language":"中文","translation":false},{"id":"ho-colonialism-9-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"一个过去在法国军队中的马尔加什志愿兵，参加过世界大战，并且娶了法国妻子，已被驱逐出自己的祖国并被判处五年流放，只因为他给《穷苦人报》和法国的几家报纸写文章，指责在本国的法国统治老爷们的腐败。","language":"中文","translation":false},{"id":"ho-colonialism-9-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"印度支那人民要求增办学校，因为学校严重缺乏。每年，在新学期开始时，许多家长要四处奔走，多方向权贵们讨情，甚至有时宁愿缴纳双倍的寄宿费，仍然找不到让子弟上学的地方。因而，成千上万的孩子们因缺乏学校而甘受愚昧。","language":"中文","translation":false},{"id":"ho-colonialism-9-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"我还记得我的一位表哥渴望得到坐在学校读书椅上的“艳福”的故事。他寻尽了门路，曾给钦使老爷、省统监老爷、学监老爷、法属安南小学校长老爷等呈上了一份又一份的申请书。当然喽，谁也没理睬他。一天，他壮着胆子，拿着申请书来到前些时候我曾幸运地念过书的学校，向负责该校的“法国校长大人”请求，“校长大人”看到他胆子竟这么大，于是便怒气冲冲，叱喝道：“谁允许你到这儿来？”然后在全班学生愕然的目光下，把申请书撕成碎片。","language":"中文","translation":false},{"id":"ho-colonialism-9-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"人们说，财政预算不允许政府开办新的学校。未必尽然。在南圻的一千二百万元预算中，就有一千万元已自行钻进官老爷们的腰包去了。","language":"中文","translation":false},{"id":"ho-colonialism-9-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"此外，殖民地政府还千方百计地阻挠安南青年到宗主国留学，恐怕他们被传染上“布尔什维克病毒”。1921年6月20日的《印度支那公共教育令》第五百条（附则）中曾就有关印度支那的学校作了如下的规定：","language":"中文","translation":false},{"id":"ho-colonialism-9-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"“任何欲赴法国本土继续学业的土著臣民或被保护民，必须取得总督的批准。总督将在当地首长和学监提供意见之后作出决定。","language":"中文","translation":false},{"id":"ho-colonialism-9-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"启程之前，本人要到学政部门申取学历表，贴上照片，注明本人的身份、履历和父母的地址，同时要写明曾经在哪一所学校念过书，考取了什么文凭，已经拿到哪些奖学金或补助金，并写明在法国的保证人的地址。这份学历表必须得到总督的证实。","language":"中文","translation":false},{"id":"ho-colonialism-9-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"留学法国的本地人的有关档案，将保存于印度支那学政部门。”","language":"中文","translation":false},{"id":"ho-colonialism-9-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"“愚其民以易于治之”，这是咱们的各个殖民地统治当局最爱采用的政策。","language":"中文","translation":false},{"id":"ho-colonialism-9-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"《人道报》（L'Humanité）曾报道说，那场“正义的战争”结束已经四年了，可是在马达加斯加，信件还受到严格的检查。","language":"中文","translation":false},{"id":"ho-colonialism-9-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"在印度支那也是一模一样，没有什么值得马达加斯加忌妒的。我们提到《穷苦人报》就是一个例子。","language":"中文","translation":false},{"id":"ho-colonialism-9-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"这似乎是偶然引起的，滥用职权的事件是刚巧在那位骗子博杜安统使和他的得力助手——阿尔贝特·萨罗的女婿兼特务头子——来到西贡的时候发生的。","language":"中文","translation":false},{"id":"ho-colonialism-9-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"另一方面，政府仍然继续阻截信件，检查私人信件。当人们明目张胆地对土著进行杀人打劫的时候，土著就连互相通信的起码权利也享受不到！这种对个人自由权的侵犯，给专制制度，给正在统治各殖民地的卑鄙的特务制度又涂上了一个污点。","language":"中文","translation":false},{"id":"ho-colonialism-9-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"印度支那政府对《穷苦人报》进行破坏；法属西非政府禁止进口美国黑人所办的各种报纸；突尼斯政府把《未来社会报》（L'Avenir social）主编驱逐出境；利奥泰老爷把《摩洛哥黄蜂报》（La Guêpe Marocaine）主编赶出摩洛哥（他们只给他一个小时来收拾行李）。","language":"中文","translation":false},{"id":"ho-colonialism-9-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"河内博览会开幕的当天，在印度支那代理总督博杜安老爷参观各展览室的时候，一帮密探人员闯进了某展览室，把《印度支那机警报》（l'Argus Indochinois）展出的漫画集没收了，原因是这家报纸的批评和讽刺使得执政的当权者感到不舒服。","language":"中文","translation":false},{"id":"ho-colonialism-9-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第九章 愚民政策","page":9,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/09.htm","text":"这家报纸的主编克莱门蒂（Clémenti）先生已经被逮捕和监禁。","language":"中文","translation":false},{"id":"ho-colonialism-10-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-10-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"在平定时期，上帝的使者们仍不愿减少其活动，正如歹徒在房子失火人们惊慌失措的时候，伺机混进去打劫一样，咱们的教士也乘别的国家在经受侵略战争之后一片混乱的时候来……为上帝服务。有的神父透露教徒忏悔时的秘密，把安南爱国者交给那伙战胜者去枪杀。其他的神父则分头深入各地去招引被迫入教的教徒。有一个牧师“赤着脚，裤筒卷到屁股后，身上背着一个装满子弹的皮袋，肩上背着步枪，腰边插着手枪，带领着一伙装备着木槊、尖刀、土枪的教徒。这就是在我们军队的掩护下，由神父带领，闯进非教徒的村庄，即神父向当局报告的那些叛徒的村庄，所进行的武装传教”。","language":"中文","translation":false},{"id":"ho-colonialism-10-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"在攻占北京的一仗中，樊国梁主教（Favier）一个人，就曾获得过荣誉军团勋章，并将共达六十万法郎的赃财塞进自己的腰包。一位目击者这样叙述：“在樊国梁主教的指挥下，一队汽车和马车驶到了礼亲王的王府门前，三、四百教民以及许多法国步兵和水兵护送着车队，为了上帝，他们当起了搬运工的角色！……事后，每一个士兵都收到了由圣云先会（Congrégation de Saint-Vincent de Paul）支付的一张二百法郎的支票。”在一篇报告里，我们看到了这样的应有的判处：“由樊国梁主教指挥的集体打劫，是一个使纪律在无形中瓦解的坏榜样。”","language":"中文","translation":false},{"id":"ho-colonialism-10-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"当然，不是只有一个樊国梁主教是这么进行传教的。他的竞争者还有不少的呢。人们这样陈述：“宵禁令一下，那些教士便带着兵士来到他们所熟悉的藏有金条的银行老板的家里，他们领着一班门徒或者是刚入教的中国人，以一面帮助教士抢劫自己的同胞、一面为神父捞钱供奉上帝的方法，来表达这些人信教的虔诚。”","language":"中文","translation":false},{"id":"ho-colonialism-10-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"这个仁慈宗教的得意门徒们的魔鬼行为，真是罄竹难书。我们现在只再提提几个事件。某教区神父把一个土著孩子关起来后，拿棍子打他和把他绑在柱子上，当这个孩子的欧洲籍主人来请求把孩子领回的时候，神父还把他推倒，恐吓要枪毙他。另一个神父为了赚三百法郎，把一个信教的安南少女卖给一个欧洲人。另外一个神父把修士学校的一个学生打得死去活来。这个受难者的乡亲们对此十分愤怒，在等待上帝的公理时，他们上书控告这位暴虐者——对不起，我想说的是尊敬的主教——，而世俗的公理却这样恐吓这些天真的控告者说：“孩子们，要当心！别生事，不然就会……”M主教不是曾经宣布过，学问是对安南人的一个危险吗？还有P主教不是说过，当上帝使藤树生在安南人屁股上的时候，上帝不就自有深意吗？","language":"中文","translation":false},{"id":"ho-colonialism-10-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"要是真的有天堂，那么，天堂可没有那么多的地方来容纳在殖民地的那些勇敢的圣徒们！而且，要是那位不幸在十字架上牺牲了的上帝能够再回到这个人世间，当他看到自己的“虔诚的门徒”是这样实现他的苦修德行的：暹罗教会占有全国土地面积的三分之一；南圻教会占有南圻土地面积的五分之一；北圻教会仅在河内就占有四分之一的土地，并且还有一笔价值一千万法郎的 小小资金，相信上帝将会感到十分厌烦。不用说大家都会知道，这份财产的绝大部分，教会是用不可告人的方法凑起来的。","language":"中文","translation":false},{"id":"ho-colonialism-10-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"B大校写道：“殖民者要依靠国家的帮助才能做到的事情，教士们则不用国家的帮助也能做到。在庄园主的土地的一旁，出现了教会的领土。不久之后，没有任何一块土地可以让安南人来建房子、耕种和生活，要是他们不肯当农奴的话！”","language":"中文","translation":false},{"id":"ho-colonialism-10-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"上帝至善全能。作为最高的造物主，上帝亲手创造了所谓高等民族来骑在也由自己创造的低等民族的背上。因此，所有的开化队，无论是到安的列斯，到马达加斯加，到塔希提或者到印度支那，都拖着一个所谓“传播福音”的传教队。例如，大家知道，法国政府征服北圻的决定，是由于受了殖民地主教的唆使，并且得到拿破仑三世的王后的赞助。而那些神父之流已经做了些什么勾当呢？他们利用了安南人的好客心，偷窃军事情报和绘画工事地图给远征的将军们。用拉丁语来说这些勾当是“神圣使命”，如按一般话来说那就是间谍。","language":"中文","translation":false},{"id":"ho-colonialism-10-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"安邺（Garnier）之辈、李维业（Rivière）之辈和他们的同伙们，不熟悉当地情况，不懂得当地语言，教士们就给他们当翻译和向导。在担任上述角色的时候，圣徒们不放过任何一个机会来实现上帝的仁慈之道。有的神父命令士兵说：“把这个村子烧掉，因为它不向咱们缴税”，或者说：“饶恕这个村子吧，它已向咱们屈服了”。这里的“咱们”，就是指教会。","language":"中文","translation":false},{"id":"ho-colonialism-10-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"殖民地的教会不仅有挑起殖民地战争的任务，而且正是教会想延长冲突，还主张打到底而不要“过早”和淡。黎峨海军上将（Genouilly）曾向海军部这样报告：“我想设法同安南当局接洽，以便签订和约，但是各教士给我们制造了许多障碍……同安南人签订和约，即使对我们怎样有利，也不能满足他们的欲望。他们只想攻占整个国家，并且推倒在位的皇朝。佩尔兰主教（Pellerin）曾经多次这样公开地说，而且这也是勒费弗尔主教（Lefèvre）的意见。”","language":"中文","translation":false},{"id":"ho-colonialism-10-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"这是不是因为教士们爱国？不！因为都督的信的后一段清楚地写道：“在印度支那活动的教士们，为了自己的目的而不顾法国的利益。”","language":"中文","translation":false},{"id":"ho-colonialism-10-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"下列的事件将给上述的意见作证明：","language":"中文","translation":false},{"id":"ho-colonialism-10-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"咸宜皇帝（Hàm-Nghi）离开了被法军占领的京都，他率义军包围由教民防守的一个村庄，其中有六个教士。一个法国将军闻讯以后，马上便同某神父商讨借船以便调军队去解围。神父拒绝了，他说船只都到远海打渔去了，三四天后才回来。这位将军经过调查后才知道原来是神父故意把船只分散，使援兵不能去解围。于是将军把神父叫来，说：“要是再过六小时还没有船的话，我就要枪毙你！”船马上就有了，将军向尊敬的神父问道：“为什么您要欺骗我们？”“将军，要是等到教士们被杀死之后你才到，那么，我们将有六个殉道者可以封为圣人了。”","language":"中文","translation":false},{"id":"ho-colonialism-10-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第十章 教会","page":10,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/10.htm","text":"瞧吧，“神父”们每天都在不断努力去做这样的传教工作，而且什么时候都是打着上帝的旗号。","language":"中文","translation":false},{"id":"ho-colonialism-11-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-11-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"第十一章 殖民地妇女的痛苦","language":"中文","translation":false},{"id":"ho-colonialism-11-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"谁读了这几页都会看到，安南妇女得到了我们的“文明传播者”什么样的“保护”。无论在什么地方，妇女们都不能免受侵略者的暴虐行为：在街上，在家里，在集市上或农村里，她们到处都碰到统治老爷、军官、军警、海关人员和车站职员们的残暴行为。骂安南妇女是娼妓、是猴子，这对于法国人说来是一件平常的事情。甚至在西贡——人们称它为法国城——的菜市场上，那些维持秩序的人也肆意地用牛筋鞭、警棍击打本地妇女，强迫她们让开路，免得街道拥挤。","language":"中文","translation":false},{"id":"ho-colonialism-11-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"这些令人痛心的事情，我们是永远也说不完的，但是，我们希望上述的事情足以使宗主国的妇女们看到，安南妇女是怎样在痛苦和压迫的境况中挣扎的。现在，我们且看其他殖民地的妇女——也是在母国的保护下——是否比较得到尊重。","language":"中文","translation":false},{"id":"ho-colonialism-11-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在费迪姆扎拉（Fedi-M Zala，属阿尔及利亚），以偷窃的罪名判处一个本地人坐一年牢。他越狱逃走了。人家派遣一股军警，由一名中尉指挥，把越狱者的村庄包围住。军警进行十分严格的搜查，但是搜查不出越狱者。他们于是把他的家中和他亲戚家中的三十五个妇女集中起来。在这三十五人中，有才十二岁的女孩子，七十岁的老大娘，有怀孕的妇人，也有正给婴儿哺乳的母亲。这时候，统治老爷也刚刚到来。在他和中尉的许诺眼色下，每一个士兵蹂躏一个女人。村庄里的豪绅和村长也被拉来共睹这一景象。人家说这是要让土著牢牢记住以存畏惧之心。","language":"中文","translation":false},{"id":"ho-colonialism-11-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"事后，他们捣毁房子，抢夺牲畜，把被强奸了的妇女关在一个房子里，让这伙刽子手监视和继续奸污，一直延续了一个多月。","language":"中文","translation":false},{"id":"ho-colonialism-11-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"人们说：“殖民地制度是强盗的制度。”我们补充说：是强奸妇女和杀人的制度。","language":"中文","translation":false},{"id":"ho-colonialism-11-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在题为《殖民地的强盗们》的文章里，维克多·梅里克（Victor Méric）先生曾给我们叙述了某殖民地的一个统治老爷的一桩难以想象的恶毒行为，他曾经把树胶灌进一个黑人妇女的生殖器官中。后来，他又强迫她顶着一块大石头站在烈日下，一直到死去。","language":"中文","translation":false},{"id":"ho-colonialism-11-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"这名淫暴的官员现在又在另一个郡里继续创造他的“业绩”。","language":"中文","translation":false},{"id":"ho-colonialism-11-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"倒霉的是，这些可耻的事件偏偏却是在统治当局御用报纸经常吹嘘为“海外法国”的地方司空见惯。","language":"中文","translation":false},{"id":"ho-colonialism-11-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"1922年3月，巴椥（Baria，属南圻）海关的一个职员，把一个以挑盐为生的安南妇女打得奄奄一息，借口是她在他们门前喧闹，打扰了他的午睡。更妙的是，这个女人还受到被解雇的恐吓，要是她作任何控诉的话。","language":"中文","translation":false},{"id":"ho-colonialism-11-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"到4月份，另一个海关人员前来接任，他也以自己的暴行而同他的前任同僚堪相匹敌。","language":"中文","translation":false},{"id":"ho-colonialism-11-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"一位也是以挑盐为生的安南老大娘，因为被克扣工钱而同工头的老婆发生口角。工头的老婆向这位海关职员告状，他不问青红皂白，便给盐工老大娘刮了两个重重的耳光，当老大娘俯身去拾起草笠的时候，这位文明传播者又对准老大娘的腹部用力地踢了一脚，使她吐了一地鲜血。","language":"中文","translation":false},{"id":"ho-colonialism-11-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"老大娘昏倒不省人事。按理说这时必须把老大娘扶起才是，但是，萨罗老爷的这个同事却把里长召来，命令他把受伤者移到别的地方去。里长拒绝不从。这个海关职员便把受伤者的丈夫——他是一个双目失明的人——召来，命令他把老伴领回去。","language":"中文","translation":false},{"id":"ho-colonialism-11-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"我可以向读者们打赌，瞧着吧，这两个南圻海关职员一定会安然无事，就像他们的同事——在非洲的某位统治老爷一样。他们甚至还会官运亨通呢！","language":"中文","translation":false},{"id":"ho-colonialism-11-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"饿着肚皮的阿尔及利亚孩子，为了糊口，那些六、七岁的男孩要去擦皮鞋，或者替那些买菜的人提菜篮。","language":"中文","translation":false},{"id":"ho-colonialism-11-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"殖民地的开化政府认为这些穷孩子赚的钱太多了。政府强迫孩子们要买一本职业手册，同时，每月要缴纳一个半到两个法郎的营业税。","language":"中文","translation":false},{"id":"ho-colonialism-11-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"宗主国的工人们！你们正在反对无理的工资税，你们对那种向孩子们勒索的卑鄙的税收又有些什么想法呢？","language":"中文","translation":false},{"id":"ho-colonialism-11-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"战前，在马提尼克，一吨食糖售价二百八十法郎，一百公升罗姆酒售价三十五法郎。","language":"中文","translation":false},{"id":"ho-colonialism-11-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"现在糖价是三千法郎，罗姆酒是四百法郎。","language":"中文","translation":false},{"id":"ho-colonialism-11-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"这样，老板们赚了1,000%。","language":"中文","translation":false},{"id":"ho-colonialism-11-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"战前工人日薪是三法郎，现在是三点七五法郎到四法郎。","language":"中文","translation":false},{"id":"ho-colonialism-11-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"这样，工人的工资增加不到30%。","language":"中文","translation":false},{"id":"ho-colonialism-11-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在这个期间，生活指数最少上升了300%；要是你再把法郎的贬值加到上述的不合理的差距里去，那么，你就会看到，本地工人生活的困苦是达到怎样的程度了。","language":"中文","translation":false},{"id":"ho-colonialism-11-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"1923年2月，由于老板不肯增加工资，工人举行了罢工。","language":"中文","translation":false},{"id":"ho-colonialism-11-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"正如在各地一样，尤其是在各殖民地，使工人流血老板们是从不犹豫的。因此在这次罢工中，有两位马提尼克青年，一个十八岁和一个十九岁，遭到了卑鄙的杀害。","language":"中文","translation":false},{"id":"ho-colonialism-11-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"凶暴的老板们连小孩子和妇女都不放过。1923年5月出版的《穷苦人报》，曾报道了如下的事件：","language":"中文","translation":false},{"id":"ho-colonialism-11-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"“当局对待劳动人民是极其不公道的。谁不依照老板规定的工钱做工都被起诉，被军警拘禁和搜查。在各处，军警都以敌对态度对待劳苦人民。","language":"中文","translation":false},{"id":"ho-colonialism-11-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"例如某天，两名军警来到德里尼蝶医院把一名叫吕巴英的妇女抓去。这位妇女于2月9日在北蒂雅的枪击事件中两腿多处中弹，他们的借口是‘她以恐吓和行动违反了劳动自由权’。","language":"中文","translation":false},{"id":"ho-colonialism-11-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"但是，可以肯定的是，这位可怜的妇女走不动，可是军警仍要押解她徒步走三十二公里到初审法官那里去。","language":"中文","translation":false},{"id":"ho-colonialism-11-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在她被捕的期间，呆在三十二公里外的福特法兰萨的医生已经有五、六天没有来为她医治。","language":"中文","translation":false},{"id":"ho-colonialism-11-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"那么，谁来证明让病人出院呢？因为这位被拘禁的有三个孩子的母亲仍说自己还没痊愈，不能走动。","language":"中文","translation":false},{"id":"ho-colonialism-11-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在各殖民地中发生过的无数骇人和不公道的事件中我再提提这样一件事：","language":"中文","translation":false},{"id":"ho-colonialism-11-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在罢工运动中，在一些企业里，那些‘得到选用’的人，被迫在军警和水兵的监督下做工，正如生活在奴隶时代一样。”","language":"中文","translation":false},{"id":"ho-colonialism-11-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"我们在一张报纸上读到这样的消息：","language":"中文","translation":false},{"id":"ho-colonialism-11-36","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":36,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"“在君士坦丁堡，一群群的妇女到处行乞。她们中有一人饿死在英根达拉桥边，手里还抱着孩子。","language":"中文","translation":false},{"id":"ho-colonialism-11-37","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":37,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"从波加里到仁法，数不清的老人、小孩子和手抱着婴儿的妇女，围着列车乞讨。","language":"中文","translation":false},{"id":"ho-colonialism-11-38","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":38,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"他们只剩下一副骨头架子，衣服褴褛。人们禁止他们到车站转来转去。”","language":"中文","translation":false},{"id":"ho-colonialism-11-39","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":39,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"当我们看到以一位贤慧的妇女作象征，在自由、公理等许多不同的幌子下，得到豪华、风雅的著名人物竭力粉饰的文明，却以极其卑鄙的血腥手段来对待殖民地妇女，并无耻地侵犯她们的风俗习惯、贞节和生活的时候，真是一件令人痛心的讽刺。","language":"中文","translation":false},{"id":"ho-colonialism-11-40","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":40,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在殖民地的荒淫残暴之风是个普遍的现象，而且其残暴的程度是难以想象的。在这里，我们姑且提出毫无偏心的人所追述的他们目睹耳闻的一两件事，让西方的姐妹们知道那个所谓“开化的使命”的价值是怎么一回事，同时深切了解殖民地的姐妹们的痛苦。","language":"中文","translation":false},{"id":"ho-colonialism-11-41","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":41,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"一个住在殖民地的人追述说：“当那班丘八来到的时候，民众都逃走了，留下来的只有两位老大爷、一个少女和一个正给婴儿喂奶、手边牵着一个八岁女孩子的少妇。丘八们勒索金钱、酒和鸦片。因为大家都不懂法语，他们便恼火了，用枪托揍一位老大爷，另一位老大爷被两个士兵——当他们来到的时候已经烂醉如泥——抛进火堆里烧了几个钟头借以取乐。在这同时，另外一些士兵强奸了那两个女人和那个女孩子。事后，他们把那个少女按倒在地上，绑住她并把碎布塞进她的口里，然后一个士兵用刺刀刺进她的肚子，砍断了她的手指取下戒指，又割断了她的头抢去项圈。","language":"中文","translation":false},{"id":"ho-colonialism-11-42","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":42,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在原是盐田的平坦的地上：横陈着三具尸体：女孩子被剥得赤身裸体，少女被剖开肚子，僵硬的左手紧紧握着拳头指着无情的天空。还有老大爷的尸体真是可怕，他也是光赤着身子，但是由于被烧焦了，再也不能认出他的面目，脂肪流满地，已经凝结了，肚皮膨胀，焦黄发光，好像烧猪的皮一样。”","language":"中文","translation":false},{"id":"ho-colonialism-11-43","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":43,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在攻占新市（Cho-moï，属北圻）的那天晚上，非洲营的一个军官看到一个俘虏身体健壮，没有什么伤痕，第二天这个军官便看到他被烧死了，满身流着油脂，肚皮胀起，焦黄发光。原来昨天晚上一伙士兵把他拉去烧死，另一伙士兵则蹂躏一个女人。","language":"中文","translation":false},{"id":"ho-colonialism-11-44","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":44,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"一个士兵逼迫一个安南妇女献身给他的狗儿。她不肯，士兵立刻对准她的肚子刺了一刀，当场死掉。","language":"中文","translation":false},{"id":"ho-colonialism-11-45","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":45,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"“某一节日，闯来一名兴致勃勃的士兵，无缘无故地把一位安南老妇人刺死。","language":"中文","translation":false},{"id":"ho-colonialism-11-46","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":46,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"一个种植园的士兵看见一群男女在十点钟的时候走进他的园子。他们都是善良的菜农，好奇地想进园子里看一看。那个士兵拿起猎枪对他们射击，打死了两个少女。","language":"中文","translation":false},{"id":"ho-colonialism-11-47","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":47,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"一个海关人员想进一个本地人的屋子，屋主不同意，他就放火烧屋子，屋主的妻子给烟火熏着，为了避免烧死，她领着孩子逃到屋子外面，被他打断了脚骨。”","language":"中文","translation":false},{"id":"ho-colonialism-11-48","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":48,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"侵略者的野蛮残暴真是无法计算的。他们精密的嗜好杀戮的文明，越助长他们想象的发展，他们就越是冷酷残暴。","language":"中文","translation":false},{"id":"ho-colonialism-11-49","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":49,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"他们不但对田地、对男子、对牲畜征收沉重的赋税，而且还把这种“恩惠”布施在妇女的身上：","language":"中文","translation":false},{"id":"ho-colonialism-11-50","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":50,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"“许许多多贫苦的本地妇女，被迫带上了沉重的脚镣去打扫街道，只因为犯了没钱纳税之罪。”","language":"中文","translation":false},{"id":"ho-colonialism-11-51","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":51,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在文明传播者们为了改良安南人种、引领其走向进步（？）所做的诸多努力中，必须提起强迫贩卖白酒的事情，围绕卖酒所发生的专横事件说也说不完。酒是一种可加泡制的毒药，一滴滴地帮助人们把那味“民主”生吞下去。","language":"中文","translation":false},{"id":"ho-colonialism-11-52","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":52,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"上面我们曾经详细地指出，那个罪恶昭彰的印度支那政府是怎样的纵容它们的奴仆们强迫那些不喝酒的妇孺也要买酒，以便使那班垄断寡头发财致富。为使垄断寡头们称心如意，人家还订出有关惩治私自酿制和贩卖酒的法令，人家在本地人的头上套了一大堆各种刑罚；人家给海关人员发配武器，这班家伙有权随时闯进老百姓的庄园和房子里去。","language":"中文","translation":false},{"id":"ho-colonialism-11-53","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":53,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"“当看到了军警把一批一批老大爷、孕妇和小孩，每两个人一对绑在一起，押解到河内市或海防市，以关于违反商业税的罪名加以审讯的时候，我们觉得惊奇——实在也值得惊奇。”","language":"中文","translation":false},{"id":"ho-colonialism-11-54","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":54,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"但是，这同各省，尤其是同中圻各省比较，只是小巫见大巫。","language":"中文","translation":false},{"id":"ho-colonialism-11-55","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":55,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"那里的统使老爷还把男女老少整批的加以判处和监禁。","language":"中文","translation":false},{"id":"ho-colonialism-11-56","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":56,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"上述一段文章的作者这样描写了站在牢门外面的亲人们：“老大爷、妇女、小孩子，所有这些人都很肮脏，衣服褴褛，形容憔悴，由于发烧而双目通红，小孩子则因赶不上而被拖着走。这些精疲力竭的人带着各种各样的东西，如帽子、破衣服、饭团、各种菜肴，以便偷偷送给被告者——他们是父亲，是丈夫，是养活家庭的人，几乎全是站在外面的人的一家之长。”","language":"中文","translation":false},{"id":"ho-colonialism-11-57","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":57,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"无论怎样描写，也不能把真实景象通通说出来。从来没有哪一个国家，哪一个时代，人们会这样野蛮和粗暴地侵犯做人的一切权利。","language":"中文","translation":false},{"id":"ho-colonialism-11-58","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":58,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"海关人员不仅经常搜查住宅，而且还搜查本地人的身体，不论是男的还是女的！他们闯进本地人的家里，要女人在他们的面前脱光衣服，而且当她们像蚕蛹一样一丝不挂的时候，他们甚至玩弄最下流的把戏，把海关图章盖在她们的身上。","language":"中文","translation":false},{"id":"ho-colonialism-11-59","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":59,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"啊！法国的母亲、妻子、姐妹们，你们有什么感想呢？而且你们，法国的儿女、丈夫、兄弟们，你们有什么感觉呢？是否那就是法国人的礼仪已经被“殖民化”了呢？","language":"中文","translation":false},{"id":"ho-colonialism-11-60","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":60,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"安南人对新学的爱好，也使得保护政府害了怕。因此，政府把各个乡村学校关闭，把学校改成军官们的马棚，开除学生，监禁教员。一个本地女教员被押解到省会，脖子被套上枷锁，光着头让烈日曝晒。","language":"中文","translation":false},{"id":"ho-colonialism-11-61","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":61,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"一个炮兵准尉半夜三更来到一个安南妇女的家里，只因为她不肯接待他，就把她的房子烧掉了。","language":"中文","translation":false},{"id":"ho-colonialism-11-62","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":62,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"一个已有许多老婆的中尉把一个安南少女击倒，并且用鞭子把她鞭死，只因为她不肯嫁给他。","language":"中文","translation":false},{"id":"ho-colonialism-11-63","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":63,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"另一位军官曾以狗彘一般的行动奸淫一个女孩子。虽被起诉，但高级刑事法庭却宣判他无罪，因为那个女孩子是安南人。","language":"中文","translation":false},{"id":"ho-colonialism-11-64","author":"胡志明","title":"法国殖民制度的罪状","location":"第十一章 殖民地妇女的痛苦","page":11,"paragraph":64,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/11.htm","text":"在我们的统治当局在各地一有开口的机会，而且在那些无所事事的人坐下洗耳恭听时所作的演说和报告中，老是说只有野蛮的德国是帝国主义、军国主义；至于法国，他们所代表的那个和平、人道的法国，共和民主的法国，却不是帝国主义，也不是军国主义。啊！哪是什么帝国主义和军国主义呢？如果是那些掌权者派遣军队——他们是工人的子弟或者是工人——去杀害其他国家的工人，那么，这不外是教导这些人懂得“文明”的生活罢了！","language":"中文","translation":false},{"id":"ho-colonialism-12-1","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-12-2","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（四）俄国革命与殖民地民族","language":"中文","translation":false},{"id":"ho-colonialism-12-3","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（五）殖民地的无产者和农民兄弟们！","language":"中文","translation":false},{"id":"ho-colonialism-12-4","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（六）农民国际给殖民地国家劳动农民的号召书","language":"中文","translation":false},{"id":"ho-colonialism-12-5","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（七）殖民地的行业工会的组织","language":"中文","translation":false},{"id":"ho-colonialism-12-6","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"1922年11月，堤岸（Cholon，属南圻）六百名染布工人被降低工资，坚决举行了罢工。","language":"中文","translation":false},{"id":"ho-colonialism-12-7","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"各处都发生资本家的反扑，同时，各处的工人阶级都开始认识到了自己的力量和能力。","language":"中文","translation":false},{"id":"ho-colonialism-12-8","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"要是那些贫苦的殖民地工人，过去很容易听从差使和奴役，没有得到政治教育，没有得到组织，而现在要集合起来——由于求生的本能，要是能够这样说的话——并且进行反对资本家的苛求，那是由于他们的境况太贫困，而贫困的程度使得欧洲的人们难以想象得到。这种斗争运动第一次在殖民地燃烧起来了。我们必须记得这个时代的信号，同时我们在宗主国的工人不要忘记我们的责任是：不仅在言词上表示对那些阶级兄弟的团结情谊，而且还要提高他们的觉悟，以组织观念和组织工作的方法教育他们。","language":"中文","translation":false},{"id":"ho-colonialism-12-9","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"法国资产阶级因本国工人阶级已经觉醒而感到担心，它们想办法利用各个殖民地来巩固其岌岌可危的统治。它们在那里为它们的工厂搜刮原料，并且搜罗人力来反对革命。在巴黎和各省的资产阶级报纸经常以整版篇幅作为殖民地专栏。各将领和议员们周游全国去作有关殖民地的演讲。那些“道德”的大手笔和专事吹牛皮的大人先生们，找不出足够的理由来歌颂一番土著的忠诚以及“自家的”开化恩德。","language":"中文","translation":false},{"id":"ho-colonialism-12-10","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"有时候这些大人先生们竟然厚颜无耻地把英国人在殖民地的抢夺和它们自己的“崇高”事业来作比较，他们认为英国人的政策是“残忍的方法”或者是“粗暴的态度”，并且肯定说，法国人的做法是充满正义和温和的！","language":"中文","translation":false},{"id":"ho-colonialism-12-11","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"只要看一看各个殖民地，就可以清楚地看到那些开化事业是多么的“美丽和温和”了。","language":"中文","translation":false},{"id":"ho-colonialism-12-12","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"在达荷美，人们把对于本地人原来已经很重的赋税增加了。人们强迫青年抛弃家园去当个“文明的保卫者”。人们禁止土著存有用以自卫和对付经常破坏庄稼的野兽的武器。教育、医药卫生，啥都没有。反之，人们不择手段地强迫“获得保护”的达荷美人要甘受作为土著的痛苦命运，忍受那个把人贬入动物行列的，和玷辱了所谓文明世界的制度。土著再也不能忍受，被迫站了起来。于是，血腥的镇压进行了。人们采用了坚决的措施，人们送来了军队、机关枪、迫击炮和战舰，人们颁布了戒严令。人们大肆逮捕和把大批的人囚禁起来。看，开化事业的仁慈性就是这样的！","language":"中文","translation":false},{"id":"ho-colonialism-12-13","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"当权者都这么宣扬，说什么叙利亚人民十分满意古尔戈（Gouraud）将军的统治。但是下列事情却证明完全相反：","language":"中文","translation":false},{"id":"ho-colonialism-12-14","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"1922年3月，穆斯塔法·凯末尔（Mustapha Kemal）来到梅特辛（Messine），叙利亚的穆斯林建了一个牌楼迎接他。牌楼上插着写满口号的黑旗：“土耳其和阿拉伯兄弟般地团结起来”、“不要忘记叙利亚兄弟们”、“解放我们”，等等。","language":"中文","translation":false},{"id":"ho-colonialism-12-15","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"穆斯塔法·凯末尔的访问阿达纳（Adana），引起了多次的激烈的游行示威。安塔基亚（Antioche）和亚历山大勒塔（Alexandrette）的复国运动者一连两天举着黑旗上街游行，并且高呼反对法国托管制度的口号。","language":"中文","translation":false},{"id":"ho-colonialism-12-16","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"为了答复叙利亚复国主义者代表团的呼吁，听说穆斯塔法·凯末尔曾经说道：“像叙利亚这么一个具有悠久文化的国家，绝不可能掌握在外国的手里。”","language":"中文","translation":false},{"id":"ho-colonialism-12-17","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"法国殖民主义者不曾改变它们的“分而治之”的格言。正因为这样，安南过去原是属于同一血统、同一风俗习惯、同一历史、同一传统、同一语言的国家，却被法国殖民者分裂成几片。它们企图利用这种巧妙的分割来削弱安南人民的骨肉团结的精神，并在兄弟骨肉之间制造冲突的根苗。在唆使他们互相倾轧之间，它们又人为地把这些成员和老挝、柬埔寨硬凑起来，以便成立一个“联邦”，称之为印度支那联邦。","language":"中文","translation":false},{"id":"ho-colonialism-12-18","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"在各个新的殖民地里，人们也采用了上述的策略。在把叙利亚国土分割成“几个国家”之后，驻扎在贝鲁特（Beyrouth）的法国高级专员又决定成立一个叙利亚“联邦”，包括阿勒颇（Alep）、大马士革（Damas）和阿拉维（Alaouites）等“国家”。人们给这个联邦想出了一面国旗，正如对安南国旗一样，人们不会忘记在接近旗杆的一角上给它贴上一块“保护旗”。1922年12月11日是个“隆重”的节日，那一面旗帜首次在阿勒颇的联邦局上挂了起来。","language":"中文","translation":false},{"id":"ho-colonialism-12-19","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"在这个仪式上，许多当权者都致祝词。联邦主席苏卜希·巴拉卡特（Soubhi Barakat）说了些什么“广阔的保护国”，什么“真诚的向导者”，什么“百战百胜的将军”，以及一大堆其他的话。代理高级专员罗贝尔·德·卡伊（Robert de Caix）也读了一篇洋洋大观的演说词。除了谈到其他一些事情之外，这位高级专员还再三提到“自主的叙利亚民族，不是从摇篮时代就得到法国守护的第一个民族”，等等。但是，所有这些空空洞洞的言词也是欺骗不了任何人的。在洛桑会议上，负有为叙利亚的真正独立和统一的斗争使命的叙利亚—巴勒斯坦代表团，曾经发出抗议书。这份抗议书已刊登在《东方论坛报》（Tribune d'Orient）上，我们高兴地把它抄录于下：","language":"中文","translation":false},{"id":"ho-colonialism-12-20","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"正当人们努力为由色佛尔条约引起的近东问题而缝补裂痕的时候，同时，正当阿拉伯民族因自愿牺牲太多而蒙受由上述条约造成的最直接的灾难的时候，在诸位的会议——旨在建立稳固和持久和平而召开的会议——席上，人们仍然没有注意听取从各个地区来的阿拉伯民族代表们的声音。","language":"中文","translation":false},{"id":"ho-colonialism-12-21","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":21,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"但是，法国统治当局却正好选择这个时候来作为隆重地结束它们四、五年以来对叙利亚进行殖民地化的事业：它们把象征着永远奴役的一块三色旗加在所谓叙利亚联邦的国旗上。这样，人们就再一次地取消了协约国的声明，取消了英国以协约国的名义同阿拉伯民族签订的条约中的保证，同时连法国统治当局所宣称的保证给不幸的叙利亚以独立的诺言也取消了。叙利亚有足够的资格来尽早取得独立和完全独立，这个资格是谁也不能否认的，同时这个资格也不逊于东方和西方的任何一个国家。但是，叙利亚却不能取得有自己单独的国旗的准许。叙利亚被迫要在自己的国旗上贴上那块三色旗子来作为被托管——变相的吞并——的标志。","language":"中文","translation":false},{"id":"ho-colonialism-12-22","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":22,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"主席阁下，我们一贯反对托管制度；我们从来都不承认托管制度；今天我们更加极力反对把象征托管制度的标志附加在我们的国旗上。","language":"中文","translation":false},{"id":"ho-colonialism-12-23","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":23,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"所有各列强，包括那些强大不亚于法国的国家，它们从来也没有采用这种可耻的方法来对待它们的最落后的殖民地。","language":"中文","translation":false},{"id":"ho-colonialism-12-24","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":24,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"国联宪章明确规定了托管制度的暂时性质（第二十二条第四节）。那么，法国负责当局根据什么法理来强迫一个它们曾经许诺引导它走向独立的国家，要接受法国的旗帜？当它的独立也在国联宪章中得到承认的时候。","language":"中文","translation":false},{"id":"ho-colonialism-12-25","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":25,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"阁下，我们郑重地要求你考虑我们所提出的抗议，我们要再一次提起的是，我们最恳切的愿望是，我们的正当要求将在会议上得到维护。","language":"中文","translation":false},{"id":"ho-colonialism-12-26","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":26,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"叙利亚—巴勒斯坦代表团团长","language":"中文","translation":false},{"id":"ho-colonialism-12-27","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":27,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"总书记埃米尔·谢基卜·阿尔斯兰（Emir Chékib Arslan）（代签）”","language":"中文","translation":false},{"id":"ho-colonialism-12-28","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":28,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"此外，哈马（Hama）群众，其中有许多人是公务员、律师、教员、新闻工作者、商人，曾经写信给法国总理，下面是主要的几段：","language":"中文","translation":false},{"id":"ho-colonialism-12-29","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":29,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"“总理阁下，我们荣幸地向你表达我们的要求，同时我们对那个议会的敌对的反应表示抗议，我们认为，这种反应违反了我们的利益和全叙利亚的利益：","language":"中文","translation":false},{"id":"ho-colonialism-12-30","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":30,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（一）那个联邦议会不是由人民选出的。因此，那个议会的议员们没有任何资格当全民的代表，他们也不能反映全民的意志。","language":"中文","translation":false},{"id":"ho-colonialism-12-31","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":31,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（二）那个议会是没有任何权力的，它被约束只能讨论那些人们向议会提交的问题，因而甚至有关全民生死存亡的问题，议会只字也不能提及。再者，议会的决议必须交付高级专员，而高级专员可以随意实施或撤销。","language":"中文","translation":false},{"id":"ho-colonialism-12-32","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":32,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（三）该议会的基层机构也不稳当，因为每一个地区只有一个代表，尽管各个地区之间的人口数额是不相等的。而且还怪诞的是，议会不按照多数决定，每当讨论中有一个不同的意见时，那么，表决只能看作是没有价值的，同时，问题必须提交高级专员作出决定。","language":"中文","translation":false},{"id":"ho-colonialism-12-33","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":33,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（四）人们宣传说，这个议会是在统一的道路上前进的一步；其实它是对统一的否定，甚至连叙利亚的国家资格也否定了。原因是这个议会只是一个被指定的议会，它完全不能代表全民的意志，它甚至还违反了全民的意志。因为在世界上它被认为是表达民族愿望的机关，而人们却有理由以它来拒绝民族的正当要求。","language":"中文","translation":false},{"id":"ho-colonialism-12-34","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":34,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"至于我们的愿望，可以提出如下：","language":"中文","translation":false},{"id":"ho-colonialism-12-35","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":35,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"甲、承认叙利亚的真正的独立和领土的完整。","language":"中文","translation":false},{"id":"ho-colonialism-12-36","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":36,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"乙、在完成正在进行中的人口调查以后，在普选的基础上进行国会的总选举。国会将起草宪法和决定国家的政体。国会将在1922年底，即联邦议会召开会议的时候召开。","language":"中文","translation":false},{"id":"ho-colonialism-12-37","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":37,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"丙、成立一个向国会负责的政府，同时国会要有充分的立法权。","language":"中文","translation":false},{"id":"ho-colonialism-12-38","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":38,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"这样才真正符合哈马人民的愿望，同时才真正符合叙利亚绝大多数人民的愿望。”","language":"中文","translation":false},{"id":"ho-colonialism-12-39","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":39,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"这本小册子正在编写的时候，在许多殖民地发生了许多严重的事件。例如，由一个安南人在广州投掷的炸弹爆炸案，安的列斯群岛的爆炸案，瓜德罗普（Guadeloupe）的流血的罢工事件，大马士革的流了不少血的游行示威，比塞大（Bizerte）和哈马姆利夫（Hammanlif）的罢工事件，以及突尼斯的沸腾的情势。","language":"中文","translation":false},{"id":"ho-colonialism-12-40","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":40,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（四）俄国革命与殖民地民族","language":"中文","translation":false},{"id":"ho-colonialism-12-41","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":41,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"资本主义像一条蚂蟥似的，一个吸盘吸住本国的无产阶级，另一个吸盘吸住殖民地的无产阶级。如果人们要杀死这个东西，人们必须同时割掉这两个吸盘。要是人们只割掉一个吸盘，另一个吸盘仍然能够吮吸无产阶级的血液，它仍然继续生存下去，同时被割掉的吸盘又将重新长出来。","language":"中文","translation":false},{"id":"ho-colonialism-12-42","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":42,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"俄国革命极其清楚地了解到这一点。因而它不满足于宣读一些空洞无物的演说词，和提出一些人道主义的决议来支持各个被压迫的民族，俄国革命教导他们的是起来作斗争。俄国革命在精神上和物质上帮助他们，正如列宁在他的关于殖民地问题的论文中所宣布的一样。俄国革命已召开了巴库大会，二十一个东方民族派遣代表出席了这个大会。西方的各个工人政党的代表也参加了大会。这在历史上是第一次，西方的侵略国家的无产阶级和东方的被侵略国家的无产阶级已经亲切地手携着手，共同找出用以反对共同敌人——资本主义的有效的斗争方法。","language":"中文","translation":false},{"id":"ho-colonialism-12-43","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":43,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"在这个历史性的大会之后，革命的俄国虽然在国内外遇到了许多困难，但仍毫不迟疑地帮助那些在英勇和胜利的革命中觉醒了的被压迫民族。它最先做的工作之一是成立东方大学。","language":"中文","translation":false},{"id":"ho-colonialism-12-44","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":44,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"东方大学现有一千零二十五名学员，其中有一百五十一名女学员。在全部学员中，有八百九十五人是共产党党员。学员们的社会成分如下：五百四十七人是农民，二百六十五人是工人，二百一十人是知识分子。此外还有七十五名十岁到十六岁的少年学员。","language":"中文","translation":false},{"id":"ho-colonialism-12-45","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":45,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"有一百五十位教师负责讲授关于社会科学、数学、历史唯物论、工人运动史、生物学、革命史和政治经济学等。在课室里，六十个不同民族的青年们彼此亲爱地团结在一起。","language":"中文","translation":false},{"id":"ho-colonialism-12-46","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":46,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"东方大学有十座大楼给学员住宿，另有一电影院，每逢星期四和星期天免费招待学员，其他日子则交由外人经营。还有两个拥有四万七千本书的图书馆，用以培养年轻的革命者的思想和帮助他们深入自己的研究工作。每个民族结合在一起，独自成立一个包括有他们本国文字的书报图书室。阅览室有足够的报纸，由学员们自己布置得很美观。","language":"中文","translation":false},{"id":"ho-colonialism-12-47","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":47,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"学员们也出只有单独一面的报，贴在阅览室门前的一块大木板上。生病的人可以进学校的医院治疗。在克里米亚（Crimée）为刚病好的人建立了一个疗养所。苏维埃政府赠给学校两个拥有九幢房子的夏令营。每一个营有一个畜牧场用以进行畜牧业的研究。农场的书记同志忍不住自豪地对我说：“我们已经有三十头奶牛和五十头猪。”夏令营还有一百公顷土地让学员们自己种植。在暑假期间，学员们在工作和实习之余还去帮助农民们干活。","language":"中文","translation":false},{"id":"ho-colonialism-12-48","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":48,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"这里顺便补充一点，这两个夏令营中的一个，过去是属于某大公的采邑。怪有趣的是，我们看到红旗在带有贵族徽号的塔顶上飘扬，和看到朝鲜或亚美尼亚的青年农民毫无拘束地在大公殿下的礼殿上嬉戏。","language":"中文","translation":false},{"id":"ho-colonialism-12-49","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":49,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"学员们的膳食、衣服和住宿全部免费。每月每人还领到五个金卢布作零用。","language":"中文","translation":false},{"id":"ho-colonialism-12-50","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":50,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"为使学员们获得有关教养孩子的基本知识，学校还承担支援一个育儿所和一个拥有六十个婴儿的模范托儿所的任务。","language":"中文","translation":false},{"id":"ho-colonialism-12-51","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":51,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"每年，学校的开支达到五十一万六千金卢布。","language":"中文","translation":false},{"id":"ho-colonialism-12-52","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":52,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"学校里的六十二个民族的代表成立了一个“公社”。公社主席和干事每三个月一届，由全体投票选出。一个学员代表参加经济和行政管理。所有的学员都轮流做炊事、图书馆、俱乐部等工作。所有一切争执和“违法”都由学员选出的法庭在全体同志的面前处理。每一周，公社召开一次会议，讨论世界政治和经济形势。间或举行一些集会和晚会，有学员中的临时演员的助兴，使大家能欣赏来自四面八方的遥远地区的丰富多彩的文学艺术。","language":"中文","translation":false},{"id":"ho-colonialism-12-53","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":53,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"布尔什维克党人的最突出的“野蛮”表现是，他们不但把那些“下贱”的殖民地土著当兄弟看待，而且还让他们参加苏俄的政治生活。这些学员们，当在自己的祖国的时候，他们是些“被统治的人”，是些“被保护的人”，就是说，是些除了只有纳税的义务之外再也没有任何权利的人，是些一向不能开口对国事提供意见的人，是些不能讨论政治的人，那么，他们现在能够参加普选，以选出自己的代表参加各个苏维埃。我希望我的那些现在还在殖民地要求转换国籍而老得不到批准的兄弟们，且把资产阶级民主和无产阶级民主来比较一下看！","language":"中文","translation":false},{"id":"ho-colonialism-12-54","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":54,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"所有的学员都曾经亲受痛苦并且看见过痛苦的景象。他们大家都在“崇高的开化的文明”下生活过，都曾经遭受过外国资本主义的压迫和剥削。因此，他们都勤奋和用心学习。他们非常活跃和严肃。他们不像在巴黎、牛津或柏林留学的东方青年那样的游荡和放纵。我们可以毫不夸张地说，东方大学在自己的屋檐下，哺育着各个殖民地民族的整个前途。","language":"中文","translation":false},{"id":"ho-colonialism-12-55","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":55,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"近东和远东地区，从叙利亚到朝鲜——我们仅指殖民地和半殖民地——算起来有一千五百多万平方公里的面积，以及十二亿以上的人口。这个广大的地区正处在资本帝国主义的统治桎梏下。虽然他们的数量照理是能够使他们强有力的，但是这些被压迫的民族仍然不能真正地站起来进行自我解放，因为他们还没有认识到民族团结和国际团结的价值。他们还没有缺乏像欧洲各个民族那样的国际联系。他们具有强大的力量，但他们却还没有看到，东方大学的建立标志着一个新的纪元，并且把各个殖民地的聪明的、活跃的青年集合起来，正进行着伟大的工作，那就是：","language":"中文","translation":false},{"id":"ho-colonialism-12-56","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":56,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"甲、教育这些未来的战士们掌握阶级斗争的原理，而一方面因民族斗争，另一方面因家长制度的习俗使这个原理在他们的头脑中模糊和混乱。","language":"中文","translation":false},{"id":"ho-colonialism-12-57","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":57,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"乙、使殖民地人民的先锋队同西方的无产阶级紧密接触，为日后的真正合作铺砌道路；只有这种合作才能保证世界工人阶级取得最后的胜利。","language":"中文","translation":false},{"id":"ho-colonialism-12-58","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":58,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"丙、使殖民地各个民族——向来彼此涣散——更加相互了解和相互团结，由此，为日后东方各国间的联合奠下基础。这个联合是无产阶级革命的臂膀之一。","language":"中文","translation":false},{"id":"ho-colonialism-12-59","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":59,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"丁、给拥有殖民地的资本主义国家的无产阶级，为他们的被压迫的兄弟可能和应该做的事情树立了一个榜样。","language":"中文","translation":false},{"id":"ho-colonialism-12-60","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":60,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（五）殖民地的无产者和农民兄弟们！","language":"中文","translation":false},{"id":"ho-colonialism-12-61","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":61,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"“世界的大流血使得殖民地的上百万的无产者和农民睁开眼来，看到了自己的极其痛苦的生活环境。一连串激烈的革命暴动——但还没有得到组织起来——在战争结束的时候爆发了。为争取更美好的前途而进行斗争的、不可阻遏的汹涌澎湃的自发力量，是由当地的民族资产阶级所组织和领导的。在战争时期成长起来的民族资产阶级，再不愿处在帝国主义的魔爪下了，也不愿再让它们在对‘自己的工人和农民’的剥削中占有最大的部分。年轻的殖民地民族资产阶级的民族解放斗争口号，得到了印度、埃及和土耳其等国的劳动人民的热烈欢迎和大力拥护。","language":"中文","translation":false},{"id":"ho-colonialism-12-62","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":62,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"共产国际为反对世界各地的垄断资本主义集团而进行不断的斗争。","language":"中文","translation":false},{"id":"ho-colonialism-12-63","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":63,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"共产国际哪能够对各殖民地和半殖民地的民族解放运动充耳不闻？","language":"中文","translation":false},{"id":"ho-colonialism-12-64","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":64,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"共产国际公开声明自己支持这一斗争，帮助这一斗争，和为忠于自己的任务，仍将继续支持这一斗争。”（摘自第三国际执行委员会声明）","language":"中文","translation":false},{"id":"ho-colonialism-12-65","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":65,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（六）农民国际给殖民地国家劳动农民的号召书","language":"中文","translation":false},{"id":"ho-colonialism-12-66","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":66,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"农民国际最近在莫斯科召开首次会议，发表了如下的号召书，用以表示自己对各殖民地劳动农民的关心：","language":"中文","translation":false},{"id":"ho-colonialism-12-67","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":67,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"“各殖民地的劳动农民兄弟们！","language":"中文","translation":false},{"id":"ho-colonialism-12-68","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":68,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"殖民地的农民兄弟们，你们是现代的奴隶：成百万的兄弟在新旧大陆的田野上、草原上和山林中，正在外国资本家和本国地主的双重压迫下痛苦呻吟着。","language":"中文","translation":false},{"id":"ho-colonialism-12-69","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":69,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"为成立一个前所未有的农民的斗争组织而首次在莫斯科召开的世界农民大会，号召兄弟们提高本身的阶级意识，并且参加到会，使大会的队伍日益壮大。","language":"中文","translation":false},{"id":"ho-colonialism-12-70","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":70,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"由于每天干活时间太长，由于饥饿贫困，由于明天的生活没有保证，你们比宗主国的农民痛苦得多。","language":"中文","translation":false},{"id":"ho-colonialism-12-71","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":71,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"你们经常像当苦役一般的被强迫劳动，被迫担挑搬运以至丧生，或者被迫去服无限期的伕役。","language":"中文","translation":false},{"id":"ho-colonialism-12-72","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":72,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"贪婪残暴的资本主义使你们陷入愚昧之中，在思想方面奴役你们，又用酒和鸦片来腐蚀你们的种族。","language":"中文","translation":false},{"id":"ho-colonialism-12-73","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":73,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"资本帝国主义所制造的殖民地制度，使你们丧失了个人的一切自由权利，丧失了所有政治的和社会的权利，因此，你们已被贬入运输货物的牲畜的同一行列。","language":"中文","translation":false},{"id":"ho-colonialism-12-74","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":74,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"资本家并不满足于把你们置于破产的贫困境地，还强迫你们抛弃田园庐舍去充当炮灰，投入兄弟相残的战争中，去攻打其他地区的人民或者去反对宗主国的农民和工人。","language":"中文","translation":false},{"id":"ho-colonialism-12-75","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":75,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"把你们的行动和我们的行动配合起来，让我们为共同的解放事业而共同斗争！","language":"中文","translation":false},{"id":"ho-colonialism-12-76","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":76,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"殖民地解放斗争事业成功万岁！","language":"中文","translation":false},{"id":"ho-colonialism-12-77","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":77,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"（七）殖民地的行业工会的组织","language":"中文","translation":false},{"id":"ho-colonialism-12-78","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":78,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"摘自赤色职工国际中央执行委员会1923年6月23日会议记录：","language":"中文","translation":false},{"id":"ho-colonialism-12-79","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":79,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"殖民地的行业工会的斗争问题","language":"中文","translation":false},{"id":"ho-colonialism-12-80","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":80,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"现代帝国主义建立在对各殖民地和半殖民地成百万劳动者剥削的基础上。因此，只有当我们破坏了它的基础的时候，帝国主义才会完全和永远崩溃瓦解。基于这一观点，在各个殖民地组织行业工会，就具有特别的重要性。但是赤色职工国际会员在埃及、突尼斯以及其他处在法国帝国主义铁蹄下的国家却没有什么作为。法国殖民地的各个工人团体和法国的各个工人团体间的联系仅是偶然的事，还没有系统的活动。显然，要是我们不能争取殖民地的群众，我们就没有足够的力量来破坏帝国主义的机构。目前的迫切工作是展开广泛的宣传运动，以便在殖民地成立行业工会和发展那些很久以来就有了初步基础的行业工会。此外，我们必须对各国和各民族的劳动者表示真正的阶级友爱，以克服殖民地劳动者对现在还是统治民族的工人阶级的疑忌。殖民地各行业工会和宗主国各行业工会之间的组织联系，只可能是在殖民地进行长期工作过程中带来的结果。","language":"中文","translation":false},{"id":"ho-colonialism-12-81","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":81,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"不要忘记殖民地劳动者，必须对他们的各个组织给予帮助，向宗主国政府对殖民地的压迫进行斗争，这是所有的革命行业工会，尤其是那些本国资产阶级压迫和剥削殖民地、半殖民地的国家的行业工会的最迫切的任务。","language":"中文","translation":false},{"id":"ho-colonialism-12-82","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":82,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"殖民地联合会（所有殖民地人民的团体）的宣言：","language":"中文","translation":false},{"id":"ho-colonialism-12-83","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":83,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"“各殖民地的兄弟们！1914年，为了要对付严重的危机，统治者们回过头来找你们，并且要求你们作出牺牲来挽救一个他们所谓是你们的祖国，但其实只是压迫和统治你们的祖国。","language":"中文","translation":false},{"id":"ho-colonialism-12-84","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":84,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"为了使你们不再犹豫，他们不会忘记掏出一些所谓要是和他们合作就能获得享受的权利来引诱你们。但当暴风雨过去了，一切还是照旧，你们仍然生活在有着各种特殊法律的殖民地制度下，完全缺乏各种同人格密切相关的权利，如结社和集会的自由权、言论自由权、在全国来往的自由权等。这是在政治方面。","language":"中文","translation":false},{"id":"ho-colonialism-12-85","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":85,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"在经济方面，你们仍要承受人头税、伕役这两项沉重的负担，完全违背了民意；同时又要纳盐税，又要受酒和鸦片的毒害，被强迫消费酒和鸦片，例如在印度支那；被强迫去值夜来保卫殖民寡头的财产，例如在阿尔及利亚。","language":"中文","translation":false},{"id":"ho-colonialism-12-86","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":86,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"做同样的工，但你们的工资却比白人同业者少。","language":"中文","translation":false},{"id":"ho-colonialism-12-87","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":87,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"总之，人们什么都许诺，但现在大家都看到那些都是骗人的谎话。","language":"中文","translation":false},{"id":"ho-colonialism-12-88","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":88,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"要怎样做我们才能获得解放？","language":"中文","translation":false},{"id":"ho-colonialism-12-89","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":89,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"请允许我们依照马克思的话对你们说，只有自己起来斗争，才有希望获得解放。","language":"中文","translation":false},{"id":"ho-colonialism-12-90","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":90,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"殖民地联合会的成立，为的是在这个任务中给你们以帮助。","language":"中文","translation":false},{"id":"ho-colonialism-12-91","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":91,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"在对我们表示同情的法国同志的帮助下，联合会把所有旅居在法国的殖民地的人们集合起来。","language":"中文","translation":false},{"id":"ho-colonialism-12-92","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":92,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"活动方法：为了完成这一正当的工作，联合会决定以报刊和言论把问题公之于舆论（组织座谈会、集会，通过议员朋友们在议会讲坛上把问题提出来），同时运用所有各种可以运用的条件。","language":"中文","translation":false},{"id":"ho-colonialism-12-93","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":93,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"宗主国的受压迫的朋友们！你们本国的资产阶级欺骗了你们，把你们当作侵略我们国土的工具。今天，你们本国的资产阶级仍采用这种狡诈的政策，又想利用我们来镇压你们为争取自我解放所作的一切努力。","language":"中文","translation":false},{"id":"ho-colonialism-12-94","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":94,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"面对资本主义和帝国主义，我们的利益是一致的；你们应记取马克思的号召：","language":"中文","translation":false},{"id":"ho-colonialism-12-95","author":"胡志明","title":"法国殖民制度的罪状","location":"第十二章 奴隶觉醒","page":12,"paragraph":95,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/12.htm","text":"‘全世界无产者，联合起来！’","language":"中文","translation":false},{"id":"ho-colonialism-13-1","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":1,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"中文马克思主义文库 -> 参考图书·阶级斗争文献 -> 胡志明《法国殖民制度的罪状》（1924）","language":"中文","translation":false},{"id":"ho-colonialism-13-2","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":2,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"印度支那前总督保罗·杜美曾写道：“当法国人到印度支那时，安南民族已成熟到准备好了做奴隶。”从那时候起到现在，半个多世纪过去了。在这个时间里，许多非常变故使世界起了巨大的变化：日本已站在世界各强国的前列；中国掀起了革命；俄国已把暴君撵走，变成无产阶级共和国；一阵强烈的解放风暴使各被压迫民族奋起；爱尔兰、埃及、朝鲜、印度，所有过去被战败今天是奴隶的人，正为争取明天的独立而进行勇敢的斗争，只有安南人则仍旧：准备好了做奴隶。","language":"中文","translation":false},{"id":"ho-colonialism-13-3","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":3,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"请听听在为宴请乌特雷、瓦吕德（Valude）及其党羽而设的二百人盛筵中安南客人令人作呕的发言。这位安南仁兄为了嗅到这些“民族联盟”老爷们的臭袜子，不惜付出八十五法郎以求一顿猪食！他这么说：","language":"中文","translation":false},{"id":"ho-colonialism-13-4","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":4,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"“我荣幸地代表在座各位表达我们对各位一片最大的尊敬、兴奋和感恩之心。在我们钦佩的眼光中，你们是光荣的大法兰西政府的真正代表者。","language":"中文","translation":false},{"id":"ho-colonialism-13-5","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":5,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"我找不出任何词句能确切说出我们内心深处的感想，但是，各位先生，请各位相信我们对护持我们的大法国，保护我们的大法国，不分肤色、种族，把我们看做子弟的大法国的敬爱、忠诚和尊敬。","language":"中文","translation":false},{"id":"ho-colonialism-13-6","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":6,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"我们每个人都亲眼看到至尊的政府和大法国的代表们，正确、英明地采取宽宏和民主的法律，赐给了印度支那的全部恩惠。”","language":"中文","translation":false},{"id":"ho-colonialism-13-7","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":7,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"在西贡检察院办事的法律科进士、政治经济科进士N.K.V.先生，在朗总督的殡仪中肯定地说，如果可以代表全体印度支那人民发表意见的话，那么，他对总督老爷给予安南民族的全部恩德，将感激涕零地说出至衷的感谢。接着，N.K.V.先生提高嗓子说：","language":"中文","translation":false},{"id":"ho-colonialism-13-8","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":8,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"“那些沾受您的宽宏政策的人，今天能和保护国的代表们一起参与建设日益强盛的印度支那，他们已经感受了您的深恩并崇敬地把您的容貌深深记住。您最操心的是经济问题。您想给印度支那以充分的经济设备使之变成第二个法国，一个在远东的强大的法国，大法兰西共和国的一部分！","language":"中文","translation":false},{"id":"ho-colonialism-13-9","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":9,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"您已经倾心尽力于您的使命，去开化一个在前进的道路上由于历史和气候等许多条件而停滞下来的民族。您是独一无二的进步战士，是文明的使者……”","language":"中文","translation":false},{"id":"ho-colonialism-13-10","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":10,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"还有在法国的印度支那人会会长——工程师高文生先生（CaovanSen），则说朗老爷过早的死去，是印度支那的一个沉痛的哀丧。于是他以如下的话来结束他的祭文：","language":"中文","translation":false},{"id":"ho-colonialism-13-11","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":11,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"“总督老爷阁下，我们真诚地为您的离去而哀哭，对我们所有的人来说，您是一位像慈父般仁厚的主人。”","language":"中文","translation":false},{"id":"ho-colonialism-13-12","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":12,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"关于这些事，我且做结论，如果所有的安南人真的都像这伙由法国政府打扮出来的傀儡那样卑躬屈节，那么，安南人注定要做奴才也是活该！","language":"中文","translation":false},{"id":"ho-colonialism-13-13","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":13,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"我们的青年还必须知道，中国青年目前在法国有二千多人，在欧洲和美洲约五万人，他们几乎全部都是在国内毕了业的，而他们现在却是工读生。至于我们，我们有助学金的大学生和自费的大学生，靠着政府的财政或父母的钱（糟的是这两个来源任何时候都不枯竭），他们用一半的时间玩台球，用剩下的一半时间的一半到各处嬉游；剩下多少时间（很少时候能剩下）才用于大学、中学中的学习。可是中国工读生，除了旨在谋求真正地改变祖国的经济基础外，就再没有其他的目的了；他们的座右铭是“靠劳动生活，在劳动中学习”。","language":"中文","translation":false},{"id":"ho-colonialism-13-14","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":14,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"他们已经这样做：当踏上他国的国土时，所有有同样能力和同学一科的人，都聚合成小组以便向老板们请求工作做。在被吸收进工场或工厂时，当然他们首先要学做工，然后才变成工人。大部分人出身于富有家庭，养尊处优，现在要做繁重的劳工也感到辛苦。假如他们没有决心，没有强烈进取的精神要素，那么，大多数人的学业早已半途而废了。可是直到现在，全部仍在继续做工。第二个障碍是语言不通。由于他们懂得使用近乎是我们远东人所特有的一种本能——观察力，已克服了这一障碍。如果老板的话他们听不懂或懂得很吃力，他们就细心注视老板给他们指点的动作。","language":"中文","translation":false},{"id":"ho-colonialism-13-15","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":15,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"他们没有赚到许多的钱。微薄的工资，他们首先要计算好怎样足以生活。他们并且认为不向政府要钱，不向家庭要钱是一种光荣。最后，根据赚得的钱，他们分出一部分投入他们所设立的互助资金。互助资金有两个目的：一、接济有医生证明书的生病的留学生和有老板证明书的失业的留学生。二、给学艺刚完毕的朋友补助一年的生活费，帮助他们补习业务。","language":"中文","translation":false},{"id":"ho-colonialism-13-16","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":16,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"在哪个国家读书，他们就在那里出版一张报纸（往往是由工读生和工人合办的）。这张报纸用汉文写，报告祖国的消息和刊登世界上的重要时事问题等。报上辟有给读者交换经验和见闻，对学艺有助益的一栏，互报每人学习的结果，刊登互相劝导、动员的文章。白天他们做工，夜里他们学习。","language":"中文","translation":false},{"id":"ho-colonialism-13-17","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":17,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"能这样坚持，有决心和团结，我们的青年小伙子们一定能达到目的。以一支勇敢的、值得钦佩的五万人的队伍，在有纪律和现代化技术的培养下，再不多久，中国将在世界各工业、商业强国之间占下一个位置。","language":"中文","translation":false},{"id":"ho-colonialism-13-18","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":18,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"在印度支那，我们有着一个民族所必须具备的一切，如海港、矿山、广阔的田野、无际的森林；我们有善于劳动和辛勤的人民。","language":"中文","translation":false},{"id":"ho-colonialism-13-19","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":19,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"可是我们缺乏组织和缺乏进行组织的人！因此我们的工业和商业等于零。那么，我们的青年做了什么呢？说起来真闷气，太闷气了：他们什么也没做。没有条件的青年，不敢离开家乡；有条件的人又太懒惰了；至于出国的人则只是为满足年轻人的好奇心罢了！","language":"中文","translation":false},{"id":"ho-colonialism-13-20","author":"胡志明","title":"法国殖民制度的罪状","location":"附录：寄给安南青年","page":13,"paragraph":20,"url":"https://www.marxists.org/chinese/reference-books/ho-chi-minh-1924/13.htm","text":"可怜的印度支那！如果您那未老先衰的青年一代再不奋起重生，您将走向灭亡！","language":"中文","translation":false},{"id":"che-guerrilla-1-1","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"中文马克思主义文库 -> 切·格瓦拉 -> 《游击战》（1960）","language":"中文","translation":false},{"id":"che-guerrilla-1-2","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"本书是为献给卡米洛·西恩富戈斯而写的。他本应阅读和修改它，可是，他的命运已阻止他这样做了！这里的几行字和下面的章节都可以作为起义军对它的伟大司令员、发起古巴革命的游击队最伟大的首领、完美的革命家和亲密朋友的怀念。","language":"中文","translation":false},{"id":"che-guerrilla-1-3","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"卡米洛是我们身经百战的战友，是菲德尔在战争的困难时刻所信赖的同志，而且是富有自我牺牲精神的战士。他总是把牺牲精神作为考验自己的品格和锻炼部队素质的一种手段。我相信，他会赞成这本书的。因为我们在书中总结了游击战的经验，而这些经验都是我们游击生活本身的产物。但卡米洛将其气质、智慧和勇敢的基本生命力赋予了我们在这里所表达的一切。他的这些品质，历史上只有少数人物才能达到这样的高度。","language":"中文","translation":false},{"id":"che-guerrilla-1-4","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"但是，我们不应把卡米洛看作是一个孤单的英雄，仅凭他天才的冲动就作出了惊天动地的功绩，而应该把他看作是人民本身的一分子。人民过去培育卡米洛，正如现在培育许多英雄、烈士和领导人一样，是经过在严酷条件下所进行的战斗反复挑选出来的。","language":"中文","translation":false},{"id":"che-guerrilla-1-5","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"我不知道卡米洛是不是晓得丹东关于革命运动的名言：“勇敢，勇敢，更勇敢。”但不管怎样，他以自己的行动实践了这句名言；不仅如此，他还给游击队员增添了其他一些必要条件的要素：能正确而迅速地分析当时形势，对未来所要解决的问题能事先加以深思熟虑。","language":"中文","translation":false},{"id":"che-guerrilla-1-6","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"虽然本文是作为我个人和全民族对我们英雄的悼文，但我并不想把它写成传记或描述他的动人事迹。卡米洛有很多动人事迹，他的一生自然地谱写了千百篇。这是因为他的个性特点就是性格开朗和尊敬人民相结合，而正是这一点有时会被人遗忘，或未被人所理解，也正是这一点使他所固有的一切都打上了卡米洛的烙印。很少有人在自己的每个行动上能够留下这样可贵的标记。菲德尔曾经说过：卡米洛役有书本知识，但却具有人民的天生智慧。人民在千万人中间把他挑选出来，要他担任要职，而他就怀着勇敢突击的精神、刚直和机智的品质以及无比的忠诚走上了岗位。","language":"中文","translation":false},{"id":"che-guerrilla-1-7","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"卡米洛的忠诚好象是对宗教信仰那样的虔诚。他既忠于菲德尔本人（因为菲德尔无与伦比地体现着人民的意志），也忠于他的人民。人民和菲德尔肩并肩地前进，这位不可战胜的游击队员的忠诚也与日俱增。","language":"中文","translation":false},{"id":"che-guerrilla-1-8","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"也许可以更确切地问：谁消灭了他的肉体？因为象他这样的人，其生命是会继续活在人间的，只要人民不愿他死去，他的生命是不会结束的。","language":"中文","translation":false},{"id":"che-guerrilla-1-9","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"是敌人杀害了他。敌人之所以杀害他，是因为想要他死亡。但他的死又是因为没有安全的飞机，飞行员没有掌握一切必要的经验，同时因为他工作很忙，想快点抵达哈瓦那……而且，他自己的性格也是他致死的原因。卡米洛素来不把危险放在眼里，他把危险当作儿戏，戏弄它，嘲笑它，逗引它，操纵它。在这位游击战士的思想中，没有什么阴影可以阻止他的行动或改变他的既定路线。","language":"中文","translation":false},{"id":"che-guerrilla-1-10","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"正当全体人民熟识他，赞美他，敬爱他的时候，他死了。他可能在早些时候死去，要是这样，他的历史就只能是一个游击队司令员的简单历史。菲德尔说过，我们将有许多卡米洛。我还可以说，我们已有了许多卡米洛，他们在卡米洛所走完的这个光辉历史阶段而载入史册之前都已献出了生命。卡米洛和其他卡米洛（死去的和未来的卡米洛）都是人民力量的象征，也是一个民族所能作出贡献的最高表现，即这个民族准备用战争来捍卫它最纯洁的理想，并对于实现其最崇高的目标抱有毫不动摇的信心。","language":"中文","translation":false},{"id":"che-guerrilla-1-11","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"我们不准备用固定的条条框框来描写我们的卡米洛，也就是说，我们不想把他毁掉。关于他，就让我们概括地谈这些吧。我们没有精细地修饰他那本来就没有定型的社会经济思想。但是，我们应该强调指出，在这次解放战争中，没有一个战士能够与之相比。他是个完美的革命家，人民的好儿子，又是古巴民族为解放自己而发动这次革命的巨匠。他的头脑中从来没有闪现过疲倦或沮丧的阴影，那怕是最轻微的阴影。卡米洛作为一个游击队员，永远是我们天天回忆的对象。就是他，无论做这件事或那件事，都做出了\"卡米洛式的业绩\"；就是他，在古巴革命史上打下了清晰的、不可磨灭的烙印；就是他，屹立在一切已故的和未来的革命家的行列之中。","language":"中文","translation":false},{"id":"che-guerrilla-1-12","author":"切·格瓦拉","title":"游击战","location":"献给卡米洛","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/guevara/1960/00.htm","text":"在卡米洛的不断革新和永垂不朽的精神中，卡米洛是人民的象征。","language":"中文","translation":false},{"id":"che-guerrilla-2-1","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":1,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"中文马克思主义文库 -> 切·格瓦拉 -> 《游击战》（1960）","language":"中文","translation":false},{"id":"che-guerrilla-2-2","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":2,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"第一章 游击战的一般原则","language":"中文","translation":false},{"id":"che-guerrilla-2-3","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":3,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"古巴人民反对巴蒂斯塔独裁政权的武装斗争已经取得了胜利。这一胜利，除了被全世界的新闻记者描述为史诗般的胜利之外，它还改变了那些对拉丁美洲人民群众的行为的旧观念，清楚地显示了人民通过游击战从野蛮政府的统治下解放自己的能力。","language":"中文","translation":false},{"id":"che-guerrilla-2-4","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":4,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"我们认为，古巴革命对美洲革命运动的方式作出了三个基本贡献，这就是：","language":"中文","translation":false},{"id":"che-guerrilla-2-5","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":5,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"1．人民力量可以战胜反动军队；","language":"中文","translation":false},{"id":"che-guerrilla-2-6","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":6,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"2．并不一定要等待一切革命条件都成熟，起义中心可以创造这些条件；","language":"中文","translation":false},{"id":"che-guerrilla-2-7","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":7,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"3．在不发达的美洲，武装斗争的战场基本上应该是农村。","language":"中文","translation":false},{"id":"che-guerrilla-2-8","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":8,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在这三个贡献中，前两个是同那些革命家或假革命家所采取的无为主义［注：无为主义，宿命论者所持的对生活抱着冷淡、消极、神秘静规的态度。无为主义的唯心和宗教宣传，引诱人们放弃为改善社会生活条件而进行的斗争。——译者］的态度相抵触的，因为他们躲起来，借口说什么反抗职业军队是万万办不到的，以此来掩饰自己的无所作为。还有些人坐等一切必要的主客观条件自然形成，而不去努力争取。这两条不容置疑的真理，今天大家都清楚了，但过去在古巴争论过，现在可能还在美洲争论着。","language":"中文","translation":false},{"id":"che-guerrilla-2-9","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":9,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"当然谈到革命条件，不能认为都是在游击中心的推动力下创造出来的。但必须随时想到，使第一个游击中心可能建立起来并得到巩固的最起码的必要条件是存在的。就是说，要向人民明确指出，在合法斗争的和平环境中，不可能坚持争取社会权利的斗争，因为和平恰恰使被那些保持其政权而违反所制定的法律的压迫者所破坏的。","language":"中文","translation":false},{"id":"che-guerrilla-2-10","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":10,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在这种情况下，人民的不满情绪日趋表面化，激起日益强烈的反响，形成反抗状态。在某个时刻，由于当局的态度而引起的斗争爆发时，这种反抗就具体化了。","language":"中文","translation":false},{"id":"che-guerrilla-2-11","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":11,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"如果某一个政府是通过人民选举的形式上台的，不管这种选举是不是一种骗局，但至少表面上还能维持宪法的合法性，那末，在这个时候，在没有用尽一切可以利用的合法斗争手段之前，游击队是不可能产生的。","language":"中文","translation":false},{"id":"che-guerrilla-2-12","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":12,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"第三个贡献基本上是属于战略性的。它应该引起这些人的注意：他们抱着教条主义的观点，妄图把群众斗争集中于城市运动，而完全忘记了农民群众广泛参与美洲所有不发达国家的生活这一事实。这并不是轻视有组织的工人群众的斗争，而只是以现实主义的观点来分析在比较困难的情况下武装斗争的各种可能性。因为在城市里，用来装饰国家宪法门面的各项权利保障已告废止或被置之不理。在这种情况下，工人运动势必要转入地下，他们没有武器，冒着巨大危险，处于非法状态，在广阔的农村，在居民有武装的游击队的支持和在镇压的军队不能到达的地方，形势就不是这样困难了。","language":"中文","translation":false},{"id":"che-guerrilla-2-13","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":13,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"对于从古巴革命经验中所得出的上述三各结论，我们在后面再作详细分析；在这里，我们之所以把这些结论放在本书的开头，是因为把它们看作我们古巴革命的基本贡献。","language":"中文","translation":false},{"id":"che-guerrilla-2-14","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":14,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击战是人民争取解放的斗争的基础，虽然争取解放的根本愿望永远是一样的，但却有许多不同的特征和侧面。显然（论述这个题目的作者们对此已经说得很多了）战争是符合一定的科学规律的，谁要违反这些规律，谁就要遭到失败。游击战争，作为战争的一个阶段，必须受到所有这些规律的支配；但就其特殊性来说，又具有一系列其本身附带的规律，而这些规律又是为把游击战向前推进所必须遵循的。当然，每个国家不同的地理条件和社会条件，决定着游击战要采用不同的方法和形式，但游击战的根本规律对其本身的任何战斗都是普遍适用的。","language":"中文","translation":false},{"id":"che-guerrilla-2-15","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":15,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"现在，我们的任务就是找出游击战所依据的基础，找出谋求解放的人民所应遵守的规则，把我们的经验加以条理化，上升为理论并进行推广，作为别国人民的借鉴。","language":"中文","translation":false},{"id":"che-guerrilla-2-16","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":16,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"首先必须确定，谁是游击战中的战斗员？一方面，我们面对着的，是压迫者的核心政权和它的支柱--职业军队。这些军队装备良好，训练有素，往往得到外国的支持，得到为这个压迫者的核心政权职务的小官僚仆从集团的支持。另一方面，则是全国或有关地区的人民。必须强调指出，游击战争是群众的战争，是人民的战争：游击队，作为一个武装的核心，是人民的战斗先锋队，它的强大力量来源于人民群众。即使游击队的武器装备劣于敌军，但绝不能认为在人数上少于他们。因此，当自己处在人多武器少的情况下，为了对付镇压，必须采取游击战这种方式。","language":"中文","translation":false},{"id":"che-guerrilla-2-17","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":17,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"所以，游击队要得到当地居民的全力支援，这是绝对必需的条件。很明显，就拿在一个地区活动的土匪来说吧，他们也具有游击队的一切特点：团结一致、尊敬首领、勇敢、熟识地形、甚至往往精通战术。但所缺少的，恰恰是人民的支持。所以，这帮土匪就不可避免地要被治安部队捕获或消灭。","language":"中文","translation":false},{"id":"che-guerrilla-2-18","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":18,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"我们分析了游击队的活动方式和作战形式，了解了它的群众基础之后，剩下的就是这样一个问题；游击队员为什么要作战？我们应该得出的必然结论是：游击队员是社会的改革者，他们响应人民愤怒反抗压迫者的呼声，拿起武器，为改变那个使手无寸铁的兄弟受侮辱受苦难的旧制度而斗争；他们反对一定时期统治制度特定的现状，并全力以赴地（只要环境许可）打破这一制度的框框。当我们更深入一步分析游击战的战术时，便可以看到，游击队员应当完全熟悉其所处的地形、进攻和退却的道路、迅速运动的各种可能性、人民提供支援的情况，自然，也要熟悉隐蔽的地方。这一切表明，游击队员要在人口稀少的农村地区进行活动。而在这些地区，人民谋求自身权利的斗争主要地、甚至几乎唯一地是旨在改变土地占有的社会结构，也就是说，游击队员首先是农业的革命者。他们代表广大农民群众的愿望：占有土地、生产资料、耕畜，以及长期来所渴望和构成他们的生活同时也将他们葬身之所的一切东西。","language":"中文","translation":false},{"id":"che-guerrilla-2-19","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":19,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"就对游击战的通常理解来说，应有两种不同的类型。一种是大规模正规军作战的补充形式，象苏联乌克兰游击战的情况那样。对于这种类型的游击战，本文不作分析。我们感兴趣的是另一种游击战：在反对现存政权--不管是不是殖民地性质的--的斗争中逐渐成长的一支武装队伍，它作为唯一的基础建立起来并在农村环境中逐步发展壮大的情况。在这种情况下，无论鼓舞斗志的思想基础是什么，游击队的经济基础却是建立在农民渴望占有土地之上的。","language":"中文","translation":false},{"id":"che-guerrilla-2-20","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":20,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"毛的中国以南方工人组织的萌芽而开始，但遭到摧残并几乎被消灭。只是在长征到达延安后，立足于农村并实现了基本权益--土地改革的时候，革命才取得稳定并开始上升。在印度支那，胡志明的斗争是以法国殖民主义压迫下种植稻谷的农民为基础的。他依靠这支力量，逐步发展壮大，终于打败法国殖民主义者。在上述两种情况中，都有一个反抗日本侵略的爱国战争的共同插曲，但土地斗争这一经济基础，却始终没有消失。在阿尔及利亚，阿拉伯民族主义的伟大思想，在其经济方面，就是反对上百万法国殖民者霸占阿尔及利亚几乎全部的可耕地。在其他国家里，如在波多黎各，海岛上的特殊条件从不允许有游击队的萌芽出现，那里的农民天天受到歧视，而其深受伤害的民族主义精神基本上就是他们（虽然许多场合已经无产阶级化了）渴望夺回被美国侵略者强行霸占的土地。正是这个中心思想推动了（尽管反响不同）在巴东部庄园的小庄园主，农民和农奴的联合。为持续三十年的解放战争中为保卫土地所有权而共同斗争。","language":"中文","translation":false},{"id":"che-guerrilla-2-21","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":21,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"既然上述特点使游击战成为战争的一种类型，又考虑到游击战随着游击队能力的增强可能发展成为阵地战这一因素，所以应当认为游击战是阵地战的雏形和草图，而既然又可能扩大游击战，改变战斗类型直至成为常规战争，那么同样有可能在每个不同的战役、战斗和前哨遭遇战之中打败敌人。因此，一个基本原则是：无论是战役或大小战斗，决部打无把握取胜之仗。有一种令人讨厌的说法：“游击队员是战争的耶稣会分子［注：耶稣会是一种教派的名称，1534为西班牙人洛约拉创立。耶稣会分子，在欧洲已成为“奸诈者”、“阴险者”的同义语。——译者］”。这句话是指一种特性：偷袭、突击、夜战。这些显然都是游击战的主要因素。自然，这种特殊的耶稣会的手段，是形势逼出来的，形势有时强迫他们作出这样的决定。而这种决定是和某些人企图使我们相信战争使按照浪漫主义和体育运动的方式进行这一概念不同的。","language":"中文","translation":false},{"id":"che-guerrilla-2-22","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":22,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"战争永远是作战双方力图消灭对方的一种斗争。因此，双方除诉诸武力以外，还采用一切欺骗的方法和可能采取的一切手段，以达到消灭对方的目的。战略和战术都是代表作战一方的目标以及实现其目标的方法的，而这种方法就是伺机利用敌方的一切弱点。在阵地战中，如果把大兵团的每个排的行动分开来，就可以看到它每一个单独的战斗也都具有游击战同样的特点：有偷袭、有夜战、有突击；如果没有这样做，也只是因为对方已有戒备使人无机可乘。但因为游击队是一支绝对独立的小分队，又拥有敌人所不能控制的广阔地带，所以，它常常能够以袭击的方式保证上述任务的完成，而这样做，乃是游击队的职责。","language":"中文","translation":false},{"id":"che-guerrilla-2-23","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":23,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"有人轻蔑地称游击战是“打了就跑”。游击战正是这样。打了就跑，等待，窥探，再打了就跑，如此循环往复，不让敌人有喘息之机。这一切似乎是消极的，然而，这种退却、却不正面作战等特点，都来自于游击战的总战略，而游击战的总战略同其他任何战争的总战略一样，其最终目的，都是要赢得胜利，消灭敌人。","language":"中文","translation":false},{"id":"che-guerrilla-2-24","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":24,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"很明显，游击战是战争的一个阶段，单靠它本身不可能取得胜利。游击战又是一个战争的初级阶段，要逐步扩充和发展，直到游击队在其不断壮大中具备正规军的特征。到那时候，它就会作好准备，以便给敌人毁灭性的打击而夺取胜利。战争的胜利永远是正规军的产物，虽然正规军起源于游击队。","language":"中文","translation":false},{"id":"che-guerrilla-2-25","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":25,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"然而，正象一个师长在近代战争中不应该在士兵的前头牺牲生命一样，游击队员作为指挥自己的将领，也不该在每次战役中牺牲自己。游击队员随时准备献出自己的生命，但是，每一个游击队员不是为了捍卫一种理想，而是为了把这种理想变成为现实才随时准备牺牲的，这正是游击战的积极因素。一小队人，即广大人民群众所支持的武装先锋队，看到比当前的战术目标还要远的将来，坚定不移地要达到一个理想，建立一个新社会，砸烂旧社会的枷锁，最后取得为之而奋战的社会正义，这确实是个奇迹。","language":"中文","translation":false},{"id":"che-guerrilla-2-26","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":26,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"一切藐视游击队的言论，经过这样分析之后，就看出了游击队的真正的伟大，即其追求的目的的伟大。因为很清楚，人们并没有谈及实现这个目的所采用的迂回曲折的方式；他们那种战斗姿态，在任何时刻都不会有所逊色的战斗姿态，他们在对待最终目标的一些重大问题上所表现出来的不屈不桡的精神，也同样都是游击队的伟大所在。","language":"中文","translation":false},{"id":"che-guerrilla-2-27","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":27,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在战争术语中，所谓战略，就是分析所要实现的目标，研究军事总形势和如何达到这些目标的总形式。","language":"中文","translation":false},{"id":"che-guerrilla-2-28","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":28,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"从游击战的观点来看，为了在战略上进行正确的判断，就必须着重分析敌人将采用什么样的活动方式。战争的最终目的是彻底消灭敌方理想。如果这种看法对某个时期来讲是正确的，那么，游击战这种内战形式，就是个最好的例子：敌人力图全部歼灭游击队的成员；相反，游击队员则应分析敌方凭借什么手段来达到这个目的，分析敌军人力、机动性、民援、武器装备和指挥能力等方面的情况。应根据这种研究来制定我们的战略，同时始终不忘最终目的在于消灭敌军。","language":"中文","translation":false},{"id":"che-guerrilla-2-29","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":29,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"有几个基本方面需要研究，例如：武器装备及利用这些武器装备的方式；精确分析在游击战中坦克、飞机的效果；分析敌人使用何种武器弹药及其行动规律，因为游击队最重要的给养正是来源于敌人的武器装备。如果有选择武器的机会，最好选择和敌人所使用的类型相同的武器，因为游击队最大的危险，就是缺乏武器弹药，而武器弹药是应该由敌方供给的。","language":"中文","translation":false},{"id":"che-guerrilla-2-30","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":30,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"研究了这些情况并且确定和分析了所要达到的目的之后，就应该进一步研究实现最终目标的一系列步骤。这些步骤是可以预先制定的，但在斗争过程中要不断加以修改，使之适应可能出现的未能预见到的一系列情况。","language":"中文","translation":false},{"id":"che-guerrilla-2-31","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":31,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"开始的时候，对游击队员来说，最重要的是不让人消灭。一支游击队（或各种不同类型的游击队）的成员，逐步地、越来越易于做到的，就是适应游击生活方式，并且使逃避和摆脱跟踪之敌等项行动成为一种日常的（因而也是简便的）行动。达到了这个目的，又占据了敌人无法到达的阵地，或者力量已增长到足以阻止敌人进攻之后，就应着手逐步削弱敌方力量。刚开始，要在离敌人猖狂反对游击战的斗争地点最近的地区削弱敌人；随后，向敌占区纵深推进，袭击其交通线；接着，袭击或扰乱其作战基地和中心基地，在游击队力所能及的范围内向敌人展开全面进攻。","language":"中文","translation":false},{"id":"che-guerrilla-2-32","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":32,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"袭击应是经常性的。不让在作战区的敌军有睡觉的机会，要有步骤地袭击和摧毁敌岗哨，使敌人每时每刻都感到他们处在严密的包围之中。在密林和岗峦起伏的地区，白天开展活动；在平原或敌人巡逻队易于窜犯的地区，夜间发动攻击。为此，需要有人民绝对的配合和对地形的完全熟悉。这两个条件对游击队员每一分钟的生存都是必不可少的。因此，要在作战区建立研究机构，在未来的作战区也要建立研究机构。与此同时，还必须积极地去做群众工作，向他们说明革命的原因、革命的目的，并宣传这样一个无可争辩的真理：谁反对人民，谁就一定要失败。谁不懂得这一不容置疑的真理，谁就不能当游击队员。","language":"中文","translation":false},{"id":"che-guerrilla-2-33","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":33,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"这项群众工作，开始的时候，应着重于保密教育，就是说，在游击队活动地区，要求每个农民和其他社会成员，对所见所闻保守机密，不要乱说。接着，争取最靠拢革命的农民的支援。然后，利用这些人在他们所熟悉的地区做联络、运送给养或武器以及充当向导等项工作。再后，游击队的工作就可以伸展到工矿区等有组织的群众活动方面去，其最终结果便是群众性的总罢工。","language":"中文","translation":false},{"id":"che-guerrilla-2-34","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":34,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"罢工是内战中一个极为重要的因素。但发动罢工则需要一系列条件，而这些条件不是经常存在的，也很少是自发产生。所以，必须创造这些必要的条件。这种创造要建立在这些基础之上：解释革命的原因，说明是有力量的，而且是可以大有作为的。","language":"中文","translation":false},{"id":"che-guerrilla-2-35","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":35,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"也可以使用一些在完成危险性较少的任务中表现突出、战斗能力相近的人组成的小组来从事破坏工作。破坏工作是游击队的另一种震撼敌人的武器，它可以使整个敌军瘫痪，可以使一个区的工业生产停顿，可以使整个城市的居民停止工作，没有电，没有水，没有任何交通往来，除非在一定时间内和走某条指定的道路，否则就不能冒险出城。如果做到了这一切，敌人的精神状态就逐渐颓废，他们军队的士气就日渐低落。待果子成熟，在适当时机，就可以摘取。","language":"中文","translation":false},{"id":"che-guerrilla-2-36","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":36,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"这一切使以假定游击队的活动地区已经扩大为前提的，但游击队的活动地区决不应过于扩大。应当始终保持一个牢固的作战基地，并在战争过程中不断地巩固它。应当采取措施教育该地区的人民，加强对顽敌斗争的措施，并且改进该地区内一切纯粹的防御体系，如战壕、坑道以及交通线等。","language":"中文","translation":false},{"id":"che-guerrilla-2-37","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":37,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"当游击队在武器和人数上已相当强大的时候，就应该去组织新的纵队。如同一个蜂窠那样，到一定时候，就放出一个新的蜂王，带着部分蜜蜂飞到另一个地区去。原来的那个母窠同最有名的游击队首长一起，留在危险性较小的地区，而新的纵队则打进敌占区去，并按照这个公式循环下去。","language":"中文","translation":false},{"id":"che-guerrilla-2-38","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":38,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"有时候，各游击纵队控制的地区太小，没有回旋余地，而当他们向戒备森严的敌占区挺进的时候，又必须抗击强敌。在这种情况下，各纵队就要集结起来，组成一个密集的战线，打阵地战即开展正规军所进行的那种战争。但是，最先的一支游击队不能离开老基地，应当组织新的游击纵队打入敌后。这些新的纵队要以最早的纵队原先在其他区域内采用的那种方式进行活动，并逐步深入敌区，直至占领之。","language":"中文","translation":false},{"id":"che-guerrilla-2-39","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":39,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击队就是这样地展开进攻，包围敌据点，打垮敌人的增援，迎接全国范围内日益高涨的群众运动，达到战争的最后目标：胜利。","language":"中文","translation":false},{"id":"che-guerrilla-2-40","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":40,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在军事术语中，战术就是实现重大战略目标的实践方法。","language":"中文","translation":false},{"id":"che-guerrilla-2-41","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":41,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"战术，一方面，它是战略的一种补充；另一方面它又是战略的一种规则。战术手段比战略的最终目标有更大的可变性和灵活性，因为战术手段要符合斗争每一阶段的要求。有整个战争过程中不变的战术目标，也有不断变化的战术目标。首先应当考虑的，就是要使游击队的活动适应敌人的活动。","language":"中文","translation":false},{"id":"che-guerrilla-2-42","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":42,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击队的一个基本特点，就是它的机动性。如果有必要，就能在几分钟内远离一定的战场，在几小时内远离作战的地区，还能不断改变战线，避开任何形式的包围。就游击战的某些时刻而言，游击队要特别注意避开包围，这种包围是敌人迫使游击队进行可能很不利的决战的唯一形式。游击队也要注意组织反包围（估计某些游击小队被敌人包围了，这些包围游击小队之敌，马上又受到比他们数量更多的游击队包围，或者游击小队据守在某一安全地带作为诱饵，等增援之敌和给养到达，就全部包围并设法歼灭之）。游击队机动性这个特点很象一种称为“小步舞”的舞蹈特点：游击队包围一个敌人阵地，譬如说，包围一支在运动中的敌军，游击队从四面把这支敌军紧紧包围，但每个方向只有五六个游击战士，最好相隔远些，以免受反包围。任何一个点发起战斗，敌军必然向这个点冲去。这时，这个点的战士可向后撤，但始终与敌人保持能看得见的距离。于是另一点也向敌人开火，敌人又向那个点扑去，而那个点的战士也照此办理。这样，所有各个点依次循环往复，就可以钳制住这支敌军，使他们消耗大量弹药，削弱他们的士气，而游击队则不至于有重大危险。","language":"中文","translation":false},{"id":"che-guerrilla-2-43","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":43,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"这种方法，也应该使用在夜袭方面。夜袭采用这种方法更容易接近敌人，更富于进攻性，因为在这种情况下敌人对我的包围要困难得多。就是说，夜袭是游击战的另一个重要特点，它便于接近所要进攻的敌人阵地，而且也便于在陌生的、有被告密危险的地区活动。自然，因为游击队人数少，就更十分需要时常采用袭击的方法。夜袭的最大的优点是能使敌人遭受伤亡而自己不受损失，因为这和以十对百而双方各损一人的那种战斗不同。在那种战斗中，敌方伤亡一人随时可以得到补充，而且只占百分之一；游击队伤亡一人，则需要较长时间才能得到补充，因为一个游击队员是要经过精心培养的，而且伤亡一人相当于损失整个战斗力的百分之十。","language":"中文","translation":false},{"id":"che-guerrilla-2-44","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":44,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"如果一个游击队员阵亡了，我们决不应该把他的武器弹药丢掉，武器弹药是战斗中极宝贵的东西。一个战友倒下了，别人就立即拣起他的武器弹药，这是游击队员的责任。弹药，爱护弹药和有计划地使用弹药，正是游击战的另一个特点。在反动的正规军和游击队的任何一次战斗中，都可以根据他们的火力辨别出哪是敌方，哪是我方：反动的正规军火力高度密集，而游击队则进行单发和准确的射击。","language":"中文","translation":false},{"id":"che-guerrilla-2-45","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":45,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"有一次，我们的一个英雄（现已牺牲）须用自己的机关枪进行约五分钟的连发射击，以阻止敌人的前进。这件事情当时在我们队伍中引起了相当大的混乱，因为根据射击的速度断定这个主要阵地是被敌人占领了。因为防御阵地的重要而不顾节约子弹，这种情况是很少有过的。","language":"中文","translation":false},{"id":"che-guerrilla-2-46","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":46,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击队的另一个基本特点是灵活性，能适应任何环境并把战斗中的一切意外转化为有利于自己的因素。在如何作战的问题上，游击队不受旧式战争条规的束缚，在战斗的每时每刻都在创造自己的打法，不断地袭击敌人。","language":"中文","translation":false},{"id":"che-guerrilla-2-47","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":47,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"首先，只能有一种机动性的阵地，就是一些敌人不能通过的特殊地区，一种钳制敌人的地区。经常可以看到这样一种情况：敌人向我袭击，顺利地通过障碍，缓慢向前推进，但突然碰到铁壁般的阻挡，不能继续前进。这是因为游击队对地形经过周密研究之后而设置的防御阵地，是不可攻克的。不需要计算有多少敌兵来进攻，只需要计算要多少游击队员来防守它，而防守人数一旦确定了，就可以抵御整营的敌军，即使不说永远能获胜，也可以说几乎永远能获胜。游击队领导人的重要职责，是恰当地选择时机和将要坚守的阵地。","language":"中文","translation":false},{"id":"che-guerrilla-2-48","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":48,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击队的进攻形式也是不同的：开始时出其不意，雷霆万钧，毫不容情，然后突然转入一个完全沉寂状态。残存的敌人，认为游击队已经走了，慢慢地平静下来，开始放心了，恢复兵营或被围城市内部的正常生活。突然，一次新的与上次特点相同的进攻，在另一个地方爆发了。与此同时，游击队的主力则在等候敌人可能增援的部队；或者，守卫敌人兵营的岗哨突然受到袭击后，又被占领了，继而整个兵营落入游击队之手。主要的就是突袭和进攻快速。","language":"中文","translation":false},{"id":"che-guerrilla-2-49","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":49,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"破坏活动很重要。但必须把破坏活动这种战争中极有效的革命手段与恐怖主义（即那种不考虑后果的、一般效能极低的手段）明确地区别开来。因为恐怖主义往往使无辜的人们枉受伤害，使许多对革命来说非常宝贵的生命白白损失。然而，恐怖手段在用于处决敌军中某些臭名昭著、凶狠残暴、恶贯满盈的指挥官时，也应被看作是一个重要的因素。鉴于这些坏家伙的一系列罪行，消灭他们是有好处的。但决不能对那些小人物妄加杀戮，因为这样做就会招致敌人的疯狂镇压。","language":"中文","translation":false},{"id":"che-guerrilla-2-50","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":50,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在对恐怖主义的评价问题上，有一个争论的焦点。许多人认为，采用恐怖手段会加剧警察的镇压，同时会阻碍同群众多少带有合法性的或半公开的一切联系，并使群众不能在某一必要的时刻进行联合行动。这个论点就其本身而言是正确的，但也有这样一种情况：在内战时期，反动政权在某些城镇所进行的镇压已达到如此残酷的程度，以致一切合法活动实际上已被取缔，而群众的活动如果没有武装的支持也是不可能进行的。因此，采用这种恐怖手段，应特别慎重，并应分析可能给革命带来哪些一般性的有利后果。总而言之，破坏活动，如果掌握得好，则永远是一种极其有效的手段。不应该搞对生产资料方面无益的破坏。这种破坏会使城镇的某一部门陷于瘫痪，也就是说，使人们失业，但不能使整个社会的正常生活处于瘫痪状态。破坏一个饮料厂，那是滑稽可笑的，但破坏一个发电站，这是绝对正确和可取的。在前一种情况下，会开除几个工人，但不能改变工业生活的节奏；在后一种情况下，也会开除一些工人，但可以使整个区的生活完全瘫痪，这种破坏活动是完全正确的。关于破坏活动的技术问题，我们下文还要谈到。","language":"中文","translation":false},{"id":"che-guerrilla-2-51","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":51,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"飞机是敌军最喜爱的一种武器，他们力图使之成为当代一种决定性的武器。然而，当游击队还处于初级阶段，人数很少，出没于陡峭的山区，飞机就不起任何作用。飞机的作用在于系统地摧毁已结成的、看得见的防线；组成这种防线，需要集中大批人员，而这种情况在游击战中是不可能有的。对于在平原或开阔地区行军，飞机也起作用，但夜行军就很容易避免这个问题了。","language":"中文","translation":false},{"id":"che-guerrilla-2-52","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":52,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"敌人的最大弱点之一，在于公路和铁路的运输。对于一条运输线，一条公路，一条铁路，每一米都要加以守卫，这实际上是不可能的。可以在任何地方放一包适量的炸药，就能把道路毁坏，也能同时颠覆通过的车辆；除炸毁道路之外，还可使敌人在人力和物力上遭受巨大损失。","language":"中文","translation":false},{"id":"che-guerrilla-2-53","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":53,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"炸药的来源是多方面的：可以从别的地区带来，也可以利用敌人扔下来的炸弹（因为扔下来的炸弹不一定都爆炸），还可以在秘密实验室里以及游击区内制造。引爆技术是多种多样的，因为炸药的生产也取决于游击队的种种条件。","language":"中文","translation":false},{"id":"che-guerrilla-2-54","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":54,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"我们在自己的实验室里，制造了一种用作雷管的火药，并研制了一些引爆装置，使这些定时地雷爆炸。其中效果最好的，是电发雷。我们爆炸成功的第一个地雷，却是敌机扔下来的炸弹。我们在这颗炸弹里放进几个雷管，再配上一枝猎枪，猎枪的扳机由一根绳索牵引着。当敌人的一辆军车开过来时，我们便拉动扳机，于是炸弹就爆炸了。","language":"中文","translation":false},{"id":"che-guerrilla-2-55","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":55,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"这项技术可以日月日臻完善，以至达到达到极高的水平。据悉：在阿尔及利亚，现在用于对付法国殖民地统治的。有一种遥控雷，即远离埋雷地点用无线电遥控系统引爆的一种地雷。","language":"中文","translation":false},{"id":"che-guerrilla-2-56","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":56,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"使地雷爆炸和消灭残敌而在各条道路上打伏击战这项技术，是补充弹药武器的最有效的方法。惊惶失措的敌人，不会开枪放炮，也来不及逃跑，我们只要耗费少量弹药就会取得可观的战果。","language":"中文","translation":false},{"id":"che-guerrilla-2-57","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":57,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"敌人不断受到打击，也会逐步改变自己的战术。他们出动的，不是零星的车辆，而是真正的车队。然而，如果很好地选择地形，把车队一段段地切开，集中力量打一辆车，那么，也可以得到同样的战果。在这样的情况下，应当随时注意到游击战的几个主要因素：绝对熟悉地形，准备退路并加以守卫，熟悉并监视敌人可能潜来进犯的一切岔道；熟悉当地居民，取得他们的全面支援，如给养、运输、临时和长期掩护需要留下的伤员；在某一作战地点提供足够的人员以及拥有机动性非常强而又尽可能多的后备队员。","language":"中文","translation":false},{"id":"che-guerrilla-2-58","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":58,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"如果这一切必要的战术条件都具备了，那末袭击敌人交通线，就会产生显著的效果。","language":"中文","translation":false},{"id":"che-guerrilla-2-59","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":59,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击战术的一个基本方面，就是如何对待当地一切居民的态度问题。如何对待敌人，同样也是个重要问题。这里要遵循的准则应该是，进攻时绝对不讲宽容，对待那些从事告密和杀人行凶的坏分子绝对不讲宽容；但对于那些履行或自以为在履行军事义务而打仗的敌军士兵则尽可能采用宽大的办法。在没有相当大的作战基地，没有巩固的作战地区的情况下，不收俘虏是个好办法，要释放他们；对敌伤兵，应就战时所能做到的一切给予护理。对待老百姓，则应十分尊重他们的一切传统习惯和风土人情，用事实来有效地表明游击队在道德上优于反动军队。除特殊情况外，不应不给罪犯赎罪机会就予以处决。","language":"中文","translation":false},{"id":"che-guerrilla-2-60","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":60,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"如上所述，游击战并不总是在最有利于施展其战术的地形上进行的。但如果是这种情况，就是说，如果游击队处在敌人难于进犯的区域（有稠密的森林，道路崎岖的山地，不可穿越的荒原或招泽地区），那末，它的总战术应始终不变，并且应以游击战的基本原则为基础。","language":"中文","translation":false},{"id":"che-guerrilla-2-61","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":61,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"一个值得注意的要点是同敌人接触的方式问题。如果所处地区的地形如此复杂，如此难于跋涉而使得敌正规部队在任何时候都不能到达，那么，游击队就应该把队伍推进到敌正规部队能够到达的地区，推进到可以开展战斗的地区。","language":"中文","translation":false},{"id":"che-guerrilla-2-62","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":62,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击队到这个地区站稳脚跟以后不久，就应立即进行战斗，应经常走出自己隐蔽的驻地去战斗。这时，游击队的流动无须象在不利地形上那样频繁，它需要适应敌人的情况，但也没有必要象在敌人能迅速集结大量兵力的地方那样频繁转移。在这种情况下，夜战也就不那么重要了；在许多场合，可以白天作战。尤其是白天运动，都是在敌人地面和空中监视下进行的。同时，还可以坚持历时更长的战斗(特别是在山岭上)，可以用少数人进行长时间的战斗而且很可能挡住敌人的援军，使他们无法到达战场。","language":"中文","translation":false},{"id":"che-guerrilla-2-63","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":63,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"虽然游击队决不应忘记的一个明显道理，就是监视敌人可能窜犯的通路，但游击队的进攻能力还是很大的（因为敌人本身也很难得到援兵），它可以更紧地围攻敌人，更直接地向敌人袭击，更能从正面和在更长时间里打击敌人，虽然这一切都受到一系列条件的限制，例如弹药数量的限制。","language":"中文","translation":false},{"id":"che-guerrilla-2-64","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":64,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在有利地形上，特别是在山区作战，虽然有这么多优点，但也有一个缺点，这就是很难在一次战斗中得到大量武器弹药，因为在这些地区的敌人戒备森严（游击队员决不能忘记弹药和武器的给养应是来自敌人方面）。但游击队在有利地形的区域比在不利地形的区域能够更快地站稳脚跟，驻扎下来，也就是说，可以组织一个能打阵地战的中心，在那里适当构筑一些防空工事或防止远射程炮火袭击的工事，创办一些急需的小型工业，设立医院、学校、训练所以及百货商店、宣传机关等等。","language":"中文","translation":false},{"id":"che-guerrilla-2-65","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":65,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在这种情况下，游击队的人数可以大大地增加，甚至可以有一些非战斗人员，对他们进行一系列的训练工作，使受训人员学会使用可能落到游击队手中的武器。","language":"中文","translation":false},{"id":"che-guerrilla-2-66","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":66,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"一支游击队可以有多少人数，这是个极其灵活的计算课题。因为这取决于所在区域的大小、供应的难易、从别的地区受压迫的群众逃来多少、实有的武器数量、游击队本身的需要等等。但是，不管怎样，游击队完全可以站住脚，也会随着新战士的加入而发展壮大起来。","language":"中文","translation":false},{"id":"che-guerrilla-2-67","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":67,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击队活动范围的大小，可以按毗邻地区游击队的条件和作战情况所能允许的程度而定。整个活动范围以从作战地点到游击安全区所需的时间为度，就是说，按夜里行军所需要的时间来计算，不能到距离最起码的安全地点五六小时路程以外的地区去作战。因为，从游击安全区派出的游击小分队通过不断地削弱敌占区，自然能够扩大自己的活动范围。","language":"中文","translation":false},{"id":"che-guerrilla-2-68","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":68,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在有利地形作战中最受欢迎的武器，就是射程远而耗弹少的武器。它是一种自动或半自动武器。在美国市场上所有的步枪，机关枪中，最值得推荐的是一种叫做\"加仑\"的M-1式自动步枪。但这种枪应由有一定经验的人使用，因为它有一个缺点，就是消耗弹药太多。也可以使用一种半重型的武器，如装有三脚架的机枪。在有利地形内作战，对这种武器和使用这种武器的人来说，都更安全。但它永远只能用作牵制，决不应用来进攻。","language":"中文","translation":false},{"id":"che-guerrilla-2-69","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":69,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"一个二十五人的游击队，其武器的理想组合是：十到十五支单发步枪，约十支自动武器，其中除\"加仑\"枪和手提机枪若干挺外，应有携带方便和轻巧的武器，如勃朗宁式手提机枪或最新式的比利时的FAL自动步枪和M-14式自动步枪。在手提机枪中，最可取的是那种能装很多子弹的九毫米口径的机枪，而且它的构造简单更值得推荐，因为调换零件方便。所有这些武器都要与敌人使用的武器相同，因为敌人用的弹药，就是我们缴获敌人这些武器时要用的弹药。敌人能用的重型武器，我们实际上是不能用的。飞机看不到东西，不起作用，坦克和大炮，由于这些地区行进困难，也很少用得上。","language":"中文","translation":false},{"id":"che-guerrilla-2-70","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":70,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"给养是非常重要的环节。一般地说，闭塞的地区，正因为闭塞，也就带来了困难。因为农民少，所以直接提供的农畜产品也就少，为了能经常备有最低限度的食粮，以应不时之需，必须保持稳定的补给线。","language":"中文","translation":false},{"id":"che-guerrilla-2-71","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":71,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在这样的作战区域，大规模的破坏活动，一般说来，可能性是不大的。如上所述，因为地区闭塞，可以被直接进行破坏的建筑物、电话线、自来水总管等等是很少的。","language":"中文","translation":false},{"id":"che-guerrilla-2-72","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":72,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"为了运输给养，重要的是要有牲口。对于在坎坷不平的地区来说，最好的牲口是骡子。应当有合适的、能提供丰富饲料的放牧场。骡子这种牲口，能通过极不平坦的、别的牲口无法通过的地带。在最困难的情况下，需用人力运输。每个人可以背二十五公斤东西，连续走好几个小时甚至连续走好几天。","language":"中文","translation":false},{"id":"che-guerrilla-2-73","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":73,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"对外的交通线路需要有完全可靠的人组成一系列联络点。这些联络点要能够储存物品，能在一定的时候掩护交通员；此外，还可以逐步建立对内的通讯联络网，联络网的范围大小看游击队发展到什么程度而定。过去在古巴革命战争中，前方某些作战区架设了一些许多公里长的电话线，修建了道路，并经常设有通信站，能尽快地向所有地区通报。","language":"中文","translation":false},{"id":"che-guerrilla-2-74","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":74,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"然而，还有在古巴革命战争中未曾应用的、但完全可以应用的其他一系列手段，例如：烽火信号、阳光镜信号以及军用通信鸽。","language":"中文","translation":false},{"id":"che-guerrilla-2-75","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":75,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"游击队迫切要做的事是保养好武器，搞到弹药，而特别需要足够的鞋子。在这个时候，工厂首先应致力于这些方面的生产。制鞋厂，在开始的时候，可以是个给旧鞋钉鞋掌的修理工场。然后，对工作进行组织安排，逐渐建成平均日产量高的各种制鞋厂。制造火药使相当简单的，有一个小型实验室，从外地搞来必要的材料，就能够造很多。布雷区是对敌人的严重威胁，可以大面积地布雷，一次就能埋葬数以百计的敌人。","language":"中文","translation":false},{"id":"che-guerrilla-2-76","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":76,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"在这样的地形上作战，就是说在不太崎岖、没有森林、道路四通八达的地区作战，应当遵循游击战的一切基本原则，要改变的，只是贯彻这些原则的形式。要改变的，也许可以说，只是游击战的量的变化，而不是质的变化。譬如，要执行和在有利地形上相同的战斗命令，游击战在不利地形上机动性应特别大。袭击（以夜袭为宜）应该是极其迅速的，几乎是爆炸性的，而撤退不仅要敏捷，而且要撤往原来出发地点之外的地区，尽量远离袭击区。要经常这样想：决没有反动军队所不能到达而游击队可以藏身的地方。","language":"中文","translation":false},{"id":"che-guerrilla-2-77","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":77,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"一个人在夜间可以步行三十到五十公里。但也可以在凌晨行军，除非战区没有被我完全掌握。或者有这样的危险，就是当地居民看见游击队走过，便把游击队的情况、发现的地点和行军的方向报告给尾追的敌人。如果是这种情况，最好还是夜间行动，在战斗打响前后，尽量保持高度的沉默，战斗应该选择在上半夜进行。但也可能打错算盘，因为有时下半夜反而更好。决不应让敌人掌握我方的战斗规律，应当不断地变换作战地点、时间和方式。","language":"中文","translation":false},{"id":"che-guerrilla-2-78","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":78,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"我们已经说过，行动不能迟缓而要迅速，必须在几分钟之内取得很大效果，然后马上撤退。使用的武器也不应和在有利地形的区域所使用的武器相同，最好有数量较多的自动武器；在夜袭中起决定因素的并不是瞄准，而是火力的集中。近距离射击的自动武器愈多，杀伤敌人的可能性就愈大。","language":"中文","translation":false},{"id":"che-guerrilla-2-79","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":79,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"此外，用地雷破坏道路和桥梁，是不容忽视的十分重要的因素。用地雷爆破攻打，其不足之处是不能持续，因而它的进攻性就大为减弱，但是地雷爆破的威力巨大猛烈，而且还可以配合使用各种武器，如前面讲过的那种地雷和猎枪。对于一般用作运送军队的满载敌兵的敞篷车，以及对于那些没有特别防护设备的象公共汽车之类的篷车，猎枪是一种使敌生畏的武器。一支装满霰弹的猎枪，就能大显神通。这并不是游击战的秘密，猎枪在大规模的战争中也在应用。美国人就曾有过猎枪队，配备了带刺刀的优质猎枪，专门袭击对方的机枪巢。","language":"中文","translation":false},{"id":"che-guerrilla-2-80","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":80,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"有一个要说明的重要问题，就是弹药问题。我们的弹药几乎总是从敌人那里夺来的。因此，要袭击的地方应当是有绝对把握可以补充所耗弹药的地方，除非安全地带有大量弹药可以补给。换言之，如果必须耗费全部弹药而又得不到补充的话，那就不应冒险进行歼灭这支敌军的战斗。在游击战的战术中，赖以维持战斗的基本军用物资的供应，永远是个值得重视的严重问题。所以，除某些武器（指它们的弹药可以在本地区内或城市内搞到的）如左轮枪或猎枪之外，应当相应地使用敌人所用的那种武器。","language":"中文","translation":false},{"id":"che-guerrilla-2-81","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":81,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"一支在不利地形上作战的游击队，其人数不得超过十至十五人。随时注意控制一个单独的战斗集体的组成人数，是一个非常重要的问题。十个、十二个、十五个人什么地方都能隐蔽，同时能给敌人以强有力的反击，并可互相支援；四五个人也许太少，但如果超过十个，那么在驻地或行军途中被敌人发现的可能性就大得多。","language":"中文","translation":false},{"id":"che-guerrilla-2-82","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":82,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"应当记住，一支游击队行军的速度等于其中一个走得最慢的队员的速度。二十、三十或四十个人的行军速度要和十个人的行军速度一样，是很困难的。一个在平原上作战的游击队员，基本上应是个赛跑运动员。平原是最能体现打了就跑的地方。平原游击队如果没有可以进行坚决反抗的安全地带的话，碰到的最大的困难，就是会很快被敌人包围。因此，在整个战斗过程中的一个相当长的时间内，它需要在绝密的条件下度过。所以，不管是哪一个居民，未经充分考察，不能予以信任。敌人的镇压如此疯狂，如此残暴（在一般情况下不仅祸及家长，而且往往牵累妇孺），以致那些意志不太坚定的人随时可能发生动摇并且向敌人泄露和指明游击队的所在地及其动向，从而使敌人立即来个包围，给游击队带来严重的（即使不一定是毁灭性的）恶果。当形势的发展，武器的积聚，人民反抗情绪的高涨等使游击队人数已有相当增长的时候，游击队应当分散，必要时可以集中起来进行袭击。但袭击后，应随即仍按原来分成的十个、十二个或十五个人的小队，再分散到原来的地区去。","language":"中文","translation":false},{"id":"che-guerrilla-2-83","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":83,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"各支游击队完全可以各自组成正规军，成立一个统一的指挥部，要尊重和服从这个指挥部，但无须集中起来。因此，十分重要的是挑选各游击队队长，并保证他们个人能在思想上向全区的最高首长负责。","language":"中文","translation":false},{"id":"che-guerrilla-2-84","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":84,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"火箭筒是游击队所能够使用的一种重型武器。由于携带和操作都很方便，它有很大的使用价值。目前，反坦克枪榴弹可以代替它。当然，火箭筒是要从敌人手里夺过来的一种武器；它用来打装甲车以至无装甲的运兵车辆，迅速攻取驻军少的小兵营是理想的。但必须指出，火箭筒的榴弹每人最多只能带三个，而且还要花相当大的气力。","language":"中文","translation":false},{"id":"che-guerrilla-2-85","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":85,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"对于从敌人方面缴获的重型武器，当然每件都应好好爱惜。但有些武器，如三脚架机枪、五十毫米口径的重型机关炮等，缴获后，在使用时偶然丢失，是可以允许的。就是说，不可以在我们本节所述的这样不利的条件下，只为了保护一挺重机枪或其他重型装备而进行战斗。重型武器只作一般性的使用，到战术上需要的时刻，就可以把它抛弃在阵地上。过去，在我们解放战争中，丢下武器就是莫大的犯罪，尽管现在我们说明那种特殊情况不能构成犯罪行为的原因，但决不允许把这种情况作为借口。游击队员在不利地形上使用的武器，是一个人随身携带的快速武器。","language":"中文","translation":false},{"id":"che-guerrilla-2-86","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":86,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"出入方便的地区的特点，一般说来就是可以居住和农民相当集中，这就大大地便利于游击队的给养。游击队有了可靠的人，取得了与城镇粮食代销站的联系，就可以很好地维持下去，而不需要把很多时间和金钱花在漫长的和危险的交通线上。在这里，还要强调一下，人数越少，越容易搞到粮食。主要的给养，如吊床、毯子、雨布，蚊帐、鞋子，药品和食品都可以直接在这个地区找到，因为这些东西都是当地居民的日用品。","language":"中文","translation":false},{"id":"che-guerrilla-2-87","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":87,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"通讯人数多，通讯的渠道就多，从这个意义上来说，这个地区的通讯联络要容易得多，但就进行远距离通讯所必需的安全来说，通讯联络就要困难得多；因为远距离通讯必需有许多可以信赖的联络点，而且经常穿越敌占区的交通员随时有被捕的危险。如果不是很重要的通信，应当采用口头形式进行，如属重要，则必须用书面和密码的形式进行。因为经验表明，口头传信，你传给我我传给他，结果把原来的通讯内容弄得面目全非。","language":"中文","translation":false},{"id":"che-guerrilla-2-88","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":88,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"根据上述理由，游击队除了考虑到在这种地区搞工业生产极端的困难之外，还要考虑到这种工业并不太重要。我们既不能建造制鞋厂，也不能建造兵工厂。实际上，我们只应建造一些隐蔽得很好的小工场，装填猎枪子弹，搞些土造地雷、爆炸物，一句话，就是用土办法造一些适用于当时需要的东西。不过，也可以依靠当地一切有友好关系的工厂生产所必需的东西。","language":"中文","translation":false},{"id":"che-guerrilla-2-89","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":89,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"从上面所说的情况中，合乎逻辑地得出两个结论。","language":"中文","translation":false},{"id":"che-guerrilla-2-90","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":90,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"一个结论是：游击队的驻扎条件是同当地生产发展的程度成反比的。凡对人们生活有利的环境和便利的条件，都吸引人们在那里安家落户，而对游击队则完全相反。凡对人们生活越便利的地方，就是游击队员越要过那种极不稳定的、流动生活的地方。这是因为它们实际上是受着同一个原则支配的。本节的标题之所以叫做\"不利地形上的作战\"，正是因为通讯发达、大小城镇较多、居民大量集中、车辆四通八达等等造成人们生活便利的一切条件，而把游击队置于极为不利的境地。","language":"中文","translation":false},{"id":"che-guerrilla-2-91","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":91,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"第二个结论是：如果伴随游击队的工作而来的必然是极端重要的群众工作的话，那么，游击队在不利地形区域，即在敌人一袭击就会引起极大灾难的区域的群众工作，就更为重要。应该在那里不断进行宣传教育工作，不断争取工人、当地农民以及当地可能有的其他一些阶级的联合，以求达到适合游击队要求的内部阵线的完全统一。在这项群众工作中，在涉及游击队同当地居民关系的这项经常性的群众工作中，也应当注意到个别的顽固敌人，他们一旦构成危险，就要毫不犹豫地把他们消灭。在这点上，游击队应该决不手软，决不能让敌人在不安全地带内的作战区中存在。","language":"中文","translation":false},{"id":"che-guerrilla-2-92","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":92,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"如果有时游击战逼近城市而打入城郊地区，环境又比较安全可以驻扎下来，那么，这时就应给游击队以专门性的教育，说得更确切一点，应对它进行特殊的组织。","language":"中文","translation":false},{"id":"che-guerrilla-2-93","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":93,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"必须明确，城郊游击队决不能自发地产生。它的产生必需是在创造了使它能够存在的某些必要条件之后。这种情况本身表明，城郊游击队将直接受其他地区的游击队负责人所指挥。因此，城郊游击队的行动，不是独立地进行的，而是按照预定的战略计划、以这样的方式来进行的，即它的行动应有助于其他地区较大的游击队的活动，应特别有助于某一策略的顺利实施，而它的活动范围不能象其他区域的游击队那样广阔。这就是说，城郊游击队不能自动去选择这样那样的行动；或去切断电话线路，或到别处去进行破坏，或到道路上去袭击敌军巡逻队等等，而只能不折不扣地执行指定的任务。如果它的任务是砍断电线杆，切断供电线、地下排水管道、铁路线、自来水总管等，那么它也就只能限于彻底地完成这些任务。","language":"中文","translation":false},{"id":"che-guerrilla-2-94","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":94,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"城郊游击队的人数不得超过四五人。限制人数很重要，因为它所处的地区应被看作是异常不利的地区，在那里敌人的防守要严密得多，随时被镇压和被告发的可能性也大大地增加了。必须把这样的事实看作是严重的情况：城郊游击队不能离作战的地方太远；然而，它应该把离开作战地点较近这一点同迅速行动、迅速转移这三者结合起来，在白天处于完全隐蔽的状态。这是一支名副其实的夜战游击队，在起义力量发展到足以包围城市，而这支游击队已作为一个积极的战斗单位参加攻城战之前，它是不可能改变自己的作战方式的。","language":"中文","translation":false},{"id":"che-guerrilla-2-95","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":95,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"城郊游击队的主要素质，就是纪律严明(其纪律严明也许是其他游击队所不能比拟的)以及严守机密。他们只能靠两三户有友好关系的人家供给粮食。在这样的情况下，一旦受围就等于死亡，这是几乎可以肯定的。此外，他们的武器也不同于其他游击队的武器，只属个人自卫的、便于迅速撤退和安全隐蔽的武韶。他们只应有一支卡宾枪或一两支可折的小型猎枪，而其余的队员最好是用手枪。","language":"中文","translation":false},{"id":"che-guerrilla-2-96","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":96,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"他们除对敌军个别一两个人或对敌军密探进行袭击外，决不能采取其他的武装行动，而应集中进行有计划的破坏活动。","language":"中文","translation":false},{"id":"che-guerrilla-2-97","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":97,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"为此，他们必须配备有各式各样的工具，必须有合适的锯子、大量的炸药、鹤嘴锄、铲子、起铁轨用的工具，总之，必须有全套搞破坏用的器械，平时藏在可靠的地方，要用时随手可以拿到。","language":"中文","translation":false},{"id":"che-guerrilla-2-98","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":98,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"如果城郊游击队不止有一支，那么它们就应受一个领导人指挥。这个领导人则通过经受考验而忠实可靠的平民作交通员，领导必要的工作。在某种情况下，城郊游击队可以从事和平时的那种工作，但这样做是很困难的。因为他们具有军队的特色，又处在本节所讲的这种不利条件下，实际上已处在非法地位。","language":"中文","translation":false},{"id":"che-guerrilla-2-99","author":"切·格瓦拉","title":"游击战","location":"第一章 游击战的一般原则","page":2,"paragraph":99,"url":"https://www.marxists.org/chinese/guevara/1960/01.htm","text":"城郊游击战一直不被人重视，但它却是非常重要的。搞好这种工作，把工作扩展到广阔的地区，就会使这个地区的商业和工业几乎全部陷于瘫痪，就会使整个城市居民处于这样一种状态：忐忑不安，忧心如焚，几乎渴望暴动的爆发，以摆脱这种处境。如果从游击战一开始，就想到未来的发展可能并逐步培训一些专门从事城郊游击战的人材，那么，就能保证速度更高的行动，从而也就会减少牺牲而赢得民族解放的宝贵时间。","language":"中文","translation":false},{"id":"che-guerrilla-3-1","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":1,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"中文马克思主义文库 -> 切·格瓦拉 -> 《游击战》（1960）","language":"中文","translation":false},{"id":"che-guerrilla-3-2","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":2,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一、游击队员——社会改革者","language":"中文","translation":false},{"id":"che-guerrilla-3-3","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":3,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"五、游击战的开始、发展和终结","language":"中文","translation":false},{"id":"che-guerrilla-3-4","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":4,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一、游击队员——社会改革者","language":"中文","translation":false},{"id":"che-guerrilla-3-5","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":5,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"我们在上面说过，游击队员是以人民解放事业为己任的战士。他们在为人民的解放使尽了各种和平手段以后，便不得不开始另一种形式的斗争，而成为战斗人民的武装先锋队。他们在一开始进行这种斗争时，就已带着粉碎不合理的旧秩序的意图，因而或多或少隐藏着用某种新秩序来代替旧秩序的意图。","language":"中文","translation":false},{"id":"che-guerrilla-3-6","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":6,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"我们也说过，在整个美洲，至少在美洲的几乎所有经济不发达国家的目前情况下，对开展斗争具有理想条件的地区是农业区。因此，游击队发起的争取社会权利的斗争基础便是改变土地所有制。","language":"中文","translation":false},{"id":"che-guerrilla-3-7","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":7,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"这整个时期中的斗争旗帜，是土地改革。在开始的时候，这面旗帜可能或者不完全可能按照自己的主张和规定的范围树立起来，或者只能涉及农民经年累月所渴望得到的正在耕种或想要耕种的土地问题。","language":"中文","translation":false},{"id":"che-guerrilla-3-8","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":8,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"实现土地改革所需要的条件，取决于游击斗争开始前存在的条件以及游击斗争的社会深度。但是，游击队员作为人民先锋队有觉悟的分子，应有-种使他们获得想个真正立志于改革的教士一样的品德。除战争困难环境造成的艰苦之外，还要加上因严厉的自我克制而产生的那种艰苦，这种自我克制会制止在环境许可的情况下可能犯的罪过和失足行为，所以，游击队员应是一个禁欲主义者。","language":"中文","translation":false},{"id":"che-guerrilla-3-9","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":9,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"至于社会关系，要随战争的发展而改变。在刚刚开始这方面工作的时候，游击队甚至不能指望在当地的社会结构上发生任何变化。","language":"中文","translation":false},{"id":"che-guerrilla-3-10","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":10,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"不能用现款购买的商品，可以用债券的形式来支付。一有机会就把债券兑现。","language":"中文","translation":false},{"id":"che-guerrilla-3-11","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":11,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"对于农民，必须经常在技术、经济、道德和文化方面给予帮助。在游击战发展初期，游击队就是降临到当地的保护天使，是来永远帮助穷人的；而对于富人，也尽可能少加骚扰。但随着游击战的发展，矛盾就日益尖锐起来，终于有一天，许多原来对革命尚抱好感的人会站到一个截然相反的立场上去，并在反对人民武装力量的战斗中迈出第一步。在这个时刻，游击队应该采取行动，成为人民事业的旗手，要依法惩办任何叛变行为。各战区的私人财产应该发挥它们的社会作用，就是说，凡属维持一个富裕家庭所多余的土地和牲畜，一律收归人民所有，并作出公平合理的分配。","language":"中文","translation":false},{"id":"che-guerrilla-3-12","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":12,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"应该永远尊重财产所有者对其用于社会公益的财产享有收受现款报酬的权利。但这项现款报酬是以债券的形式支付的(这种债券，我们的老师巴约将军在谈到债务人和债权人的关系时，把它叫做“信用券”)。","language":"中文","translation":false},{"id":"che-guerrilla-3-13","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":13,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"凡属臭名昭著、明目张胆的革命敌人所有的土地、财物或工厂，均应立即由革命武装力量接管。并在利用这种战斗热情(这时人们兄弟般的友爱达到空前的高度)，把当地居民所能够接受的各项合作社事业推向前进。","language":"中文","translation":false},{"id":"che-guerrilla-3-14","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":14,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员作为社会的改革者，不仅应在自己的生活上起模范作用，而且应在解决思想问题上经常起指导作用。他们用以指导人们的，是他们所知的、在某个时期所要做的以及在战争岁月里所学到的一切。战争的岁月给游击队员的思想以有利的影响，而随着游击队的武装业已显示出自己的威力，随着当地人民的状况业已体现游击队的精神，成为游击队生活的一部分的时候，游击队员就更加激进了。同时，他们也懂得了一系列变革的正义性和迫切需要性；对这些变革的重要意义，从前他们只是从理论上了解的，而在大多数场合对其实际的迫切意义是不清楚的。","language":"中文","translation":false},{"id":"che-guerrilla-3-15","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":15,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"这种情况是经常发生的，因为游击战的倡导者，或者更确切地说，游击战的领导者，并不是每日在田地上弯腰劳动的农民，而是懂得必须改变农民的社会待遇，但大多数却未尝受过这种待遇之苦的人们。于是，就出现一种真正互相作用的情况(我在这里推广古巴的经验并以这个经验为出发点)：游击战的领导者用事实向人民表明武装斗争的重要意义，而人民就奋起斗争，向这些领导者表明有必要实现上述变革。游击队员和人民之间的这种互相作用的结果，导致革命的不断激化，增强了运动的革命特色，从而使运动具有全国性的规模。","language":"中文","translation":false},{"id":"che-guerrilla-3-16","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":16,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"上文已简略地谈到游击队员的生活和特点，要求游击队员在体质上、思想上和道德品质上都具有能适应这种生活并能彻底完成所赋予的任务的一系列条件。","language":"中文","translation":false},{"id":"che-guerrilla-3-17","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":17,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"第一个要提出的问题是：游击队员应该是怎样的人？回答应是：游击队员最好是本地人。因为本地人在当地有可以投靠的亲友，因为他们土生土长，对本地地形熟悉--熟悉地形是游击战的重要因素之一--还因为他们习惯于那里所经历的变化，那就能做出较好的工作，更不用说，他们还会把为保卫自己的家园或为改变危及其所在天地的社会制度而迸发出来的那股热情倾注到整个工作中去了。","language":"中文","translation":false},{"id":"che-guerrilla-3-18","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":18,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员是夜战的战士。谈到这一点叫也应该谈谈他们所具有的夜间作战的种种特点。他们应当神出鬼没，在通过平原或山地向战斗地点进发时而不被人发觉行踪，在扑向敌人时，要利用出其不意这一游击战中特别要强调的因素。出其不意的袭击造成敌人一片慌乱之后，应毫不留情地投入战斗。这时，决不容许自己队伍中有丝毫懦弱的表现，应该尽量利用敌方任何怯懦之机。旋风般白天而降，摧毁一切，若非策略上的需要，决不让敌人有喘息之机；处决应受处决的人；造成敌军恐怖的心理状态，但同时优待已无自卫能力的战败者，也要尊重死者。","language":"中文","translation":false},{"id":"che-guerrilla-3-19","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":19,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"敌军伤兵应受到格外尊重，应尽可能予以治疗--过去干尽坏事、应按历史罪行处理者例外。决不能带着俘虏走，除非已有敌军难于攻克的巩固的作战基地；否则，这些俘虏就会成为十分危险的祸害，威胁当地居民和游击队本身的安全，因为他们一旦逃跑，就会向原来的敌军提供情报。所以，若非罪大恶极者，一律训话后予以释放。","language":"中文","translation":false},{"id":"che-guerrilla-3-20","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":20,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员，必要时应冒生命危险。他应随时准备在紧要关头毫不犹豫地献出自己的生命，但同时又要机智谨慎，决不作无谓的牺牲。游击队应采取一切可能的戒备，以避免不幸的结局或被消灭。为此，在整个战斗中极端重要的是全面监视增援之敌可能通过的地点，这样做的目的也是预防受围。敌军包围所造成的恶果，往往在肉体上并不那么严重；而在士气方面，则往往造成对斗争胜利的可能性完全丧失信心。","language":"中文","translation":false},{"id":"che-guerrilla-3-21","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":21,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"然而，游击队员应是大无畏的。他应正确分析每一行动中存在的危险性和可能性，对任何环境永远抱乐观主义的态度，并且即使在对有利和不利条件的分析得不出值得重视的肯定结果的时刻，也能作出有利的决策。","language":"中文","translation":false},{"id":"che-guerrilla-3-22","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":22,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"为使游击队员能在战斗的和敌人活动的环境下生存下来，需要有一定程度的适应性，能适应他所生活的环境，同它浑然成为一体，尽可能利用它为自己服务。与此同时，还要有敏锐的思考力和当机立断的创造力，能按其决定性行动的前进步伐改变事物发展的进程。","language":"中文","translation":false},{"id":"che-guerrilla-3-23","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":23,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"人民军队的这种适应性和创造力能粉碎敌人的一切预谋，能制止敌正规军突然的冲击。","language":"中文","translation":false},{"id":"che-guerrilla-3-24","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":24,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员决不应让一个受伤的战友落到敌军手中，因为如果这样，这个战友的命运几乎可以肯定是白白送死。所以，无论花什么代价，都应把他从战场上撒下来，转移到安全的地方去。为了完成这个任务，应不怕极度的疲劳，甘冒最大的危险。游击队员应是一个不同寻常的战友。","language":"中文","translation":false},{"id":"che-guerrilla-3-25","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":25,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"同时，游击队员又是守口如瓶的人，对于所见所闻，都应严守机密，只有自己知道；即使对自己的战友，也从不多说一句话。因为敌人随时随地竭力想把他们的人打到游击队组织内部来刺探游击队的计划、地点和生存的手段。","language":"中文","translation":false},{"id":"che-guerrilla-3-26","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":26,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"除上述的道德品质外，游击队员还应有一系列极重要的体质上的特点。他必须是不知疲倦的人，在疲劳似乎已达到不能忍受的时刻，还能具有超人的精力。他必须始终精神焕发，这来自坚定不移的信念，正是这种信念使他再迈出一步，当然不是最后的一步，于是一步又一步地直至到达首长指定的地点为止。","language":"中文","translation":false},{"id":"che-guerrilla-3-27","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":27,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员应能极度茹苦含辛，不仅能随时忍受缺粮、缺水、缺衣、缺住房的艰苦，而且还要忍受病、伤的痛苦。往往挂了彩，没有外科医生来动大手术，而只是靠大自然的作用来治疗。也只能够这样，因为在大多数情况下，离开游击区去治疗病伤，就会被敌人杀害。","language":"中文","translation":false},{"id":"che-guerrilla-3-28","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":28,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"为实现这些条件的要求，游击队员又需要有钢铁般的体质，而这种体质能使他经受这一切艰苦而不致病倒，并把他那种被追捕的野兽般的生活变成增强体质的另一要素，以便在自然适应能力的帮助之下好象自己也变成战斗所在地本身的一部分。","language":"中文","translation":false},{"id":"che-guerrilla-3-29","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":29,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"所有这些看法使我们不禁要问：游击队员理想的年龄是多大？这个界限是很难定的，由于一系列社会的以至个人的特点，这个年龄有很大的伸缩性。例如，农民比城里人耐劳的能力要强得多。城里人，如果是习惯体育锻炼和讲究生活卫生的，就比一辈子坐办公室的人要耐劳得多。但是，一般地说，一个游击队员的年龄，在游击队完全处于流动阶段，最高不应超过四十岁，除了若干例外情况，特别是农民中间的例外情况。我们古巴革命斗争的一位英雄，克雷森西奥·佩雷斯司令员上马埃斯特腊山打游击时，年已六十五岁。当时在我们的队伍中他是最有用的人材之一。","language":"中文","translation":false},{"id":"che-guerrilla-3-30","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":30,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"我们还要问，是否有必要考虑游击队的社会成分问题。有人说，游击队的社会成分应该同作战中心区的社会成分相适应，换言之，游击队的战斗主体应该是农民。很明显，农民是最好的战斗员，但这决不是说排斥居民中的其他成分，不让他们有机会为正义事业而斗争。此外，在成分问题上，允许有个别的例外，也是十分重要的。","language":"中文","translation":false},{"id":"che-guerrilla-3-31","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":31,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"还没有明确规定游击队员最低的年龄。我们认为，除非常特殊的情况外，不能吸收十六岁以下的人参加。一般说来，这些人几乎还是孩子，经历不多，在战斗中经受不住要碰到的艰难、残酷和痛苦的折磨。","language":"中文","translation":false},{"id":"che-guerrilla-3-32","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":32,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员最恰当的年龄可以说是在二十五岁到三十五岁之间。在这个年龄内，大家都已确定了生活道路，凡是抛开自己的家庭子女和一切而参加游击队的人，都已好好考虑过要肩负的责任并为此下决心不后退一步。在孩子中，当然也由达到我们起义军那样高度素养的战士这种特殊情况，但这不是正常的情况。即使其中有一个具备优秀战士的条件，那末其中就会有几十个在长期中给游击队造成危险障碍而需要送回家去的人。","language":"中文","translation":false},{"id":"che-guerrilla-3-33","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":33,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员，我们已经说过，是象蜗牛一样把全部“家当”背在身上的战士。因此，他必须把背包收拾到这样的地步：使最少的用具发挥最大的作用，只带必不可少的东西。但是，即使经历千难万险，也要把这些东西作为基本物件保留住，只有在极端不利的情况下方可丢弃。","language":"中文","translation":false},{"id":"che-guerrilla-3-34","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":34,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"正因为这样，游击队员的军火也仅仅是-些能随身携带的。补充军火，特别是补充子弹非常困难。所以，子弹不得弄潮，要经常检查，一颗颗地数清楚，以免丢失，这就成了一项行动的准则。枪枝要经常保持清洁，经常上油，保持枪筒闪光发亮。凡是没有把军火保持在这种状态的人，每个小队的负责人都应给予一定的处分。","language":"中文","translation":false},{"id":"che-guerrilla-3-35","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":35,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"凡具有如此忠诚和坚定的高尚品质因而能在上述那样不利条件下活动的人，都必须具有一种理想。这种理想是简单的、朴素的、没有奢望，一般也并不好高骛远，但这种理想却是那样坚定，那样明确，以致为它献出生命而毫不犹豫。几乎所有出身于农民的人，他们的理想都是要求获得自己的一块耕地和享受公平的社会待遇的权利；出身于工人的人，他们的理想是要求有工作、领取合理工资以及也享受公平的社会待遇的权利：而来自学生和教职员中的人则抱着象争取自由之类的较为抽象的理想。","language":"中文","translation":false},{"id":"che-guerrilla-3-36","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":36,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"讲到这一切，我们不禁要问：游击队员是怎样生活的?它的正常生活便是行军。让我们举森林地带的山区游击队员为例。我们假设他们不断受到敌人的追击。在这样的情况下，这支游击队白天不断转移阵地，无法吃东西；黑夜来临了，才在一块林中空地上，一个水泉边，按照老习惯扎下营来，集合各个小队共进晚餐。入夜便就地取材，燃起篝火。","language":"中文","translation":false},{"id":"che-guerrilla-3-37","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":37,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员是什么时候能吃就吃，能吃多少就吃多少的。有时，一大堆口粮一下子就绐战士们吃光了；有时，他们两三天不进食，工作能力却毫不减退。","language":"中文","translation":false},{"id":"che-guerrilla-3-38","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":38,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"他们露天宿营，睡吊床，吊床上空遮一块与床大小相当的尼龙雨布，吊床下面就是背包、枪枝和子弹，即游击队员的宝贝。有的地方，敌人有可能突然发起袭击，睡觉就不好脱鞋子。鞋子也是游击队员的珍宝。谁有一双鞋子，就可以保证在非常紧张的环境中顺利地生存下去。","language":"中文","translation":false},{"id":"che-guerrilla-3-39","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":39,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"就这样一天天过去，不靠近任何村镇，不同任何事先没建立关系的人接头，生活在山峦起伏荒无人烟的地带，忍饥挨饿，有时受渴，忍受严寒酷暑，连续行军则汗流浃背，汗水干了又湿，湿了又干，而没有可能搞搞清洁卫生（尽管这也象在所有情况下一样都要靠个人自己妥善安排）。","language":"中文","translation":false},{"id":"che-guerrilla-3-40","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":40,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在古巴革命战争过程中，有一次，我们在十分不利的情况下度过了好多天，又在烈日下战斗了两小时四十五分钟，然后行军十六公里进入乌维罗村。该村地处海滨，但当时气温很高，骄阳似火，我们身上散发着一种特殊的臭味，谁靠近我们都要退避三舍。但我们的嗅觉完全适应于这种生活，连游击队员们的吊床都可以根据每个人特有的气味辨别出来。","language":"中文","translation":false},{"id":"che-guerrilla-3-41","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":41,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在上述情况下，宿营用物应该是容易拆除的，不应留下会泄露情况的任何痕迹；应采取极端严密的警戒措施；每十个人睡觉，就应有一两个人值班，要不断地换岗，对宿营地的各处进口都应严加警戒。","language":"中文","translation":false},{"id":"che-guerrilla-3-42","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":42,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"野营生活教会他们许多做饭的技巧：怎样很快把饭做好，怎样用山上采摘来的小东西作调味，怎样发明一些小菜来换换花样（其中主要是用根茎类植物、谷物、食盐、一点动植物油，很个别的情况下有块打来的野兽肉），这都是指游击队在热带地区活动的情况。","language":"中文","translation":false},{"id":"che-guerrilla-3-43","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":43,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在战斗生活的内容中，最有趣的、能引起大家喜悦、使大家精神焕发继续前进的事情便是战斗。战斗，是游击队生活的最高潮，它往往发生在一个防守薄弱、能够一举消灭的敌驻营地被发现并经过侦察以后的某一适当时刻，或者发生在敌军部队直接向解放武装力量占领的区域进犯的时刻。这两种情形是不同的。","language":"中文","translation":false},{"id":"che-guerrilla-3-44","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":44,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"攻打敌驻营地的战斗是总体战，而且重点是打来解围的援敌，因为阵地设防之敌永远不是游击队员所喜爱的猎物，而在运动中的敌人，由于他们异常紧张、不熟悉地形、草木皆兵，又没有可供防御的自然掩蔽物，所以是理想的猎物。凡是筑了工事，又有强大武器可击退进攻的人，无论情况怎么糟，同那一长串的行军队伍的处境相比较，永远是不问的。因为行军中的队伍突然在两三处遭到袭击，就被切成一段一段。进攻者若不能把它围住并全部吃掉的话，不要等到被进攻者进行反击。进攻者就已经溜之大吉了。","language":"中文","translation":false},{"id":"che-guerrilla-3-45","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":45,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"如果通过断粮、断水或直接出击都不能把设有工事防御的敌驻营地拿下来，在粉碎了前来解围之援敌，突破包围，并已取得成果，那么游击队就应该撤退。如果游击队过弱而前来增援之敌过强，游击队应集中力量打其前卫。不管结果怎样，必须特别致力于打前卫，因为打它几次以后，敌军土兵就知道，在前头的人几乎总是要送命的，那么谁也不愿走在前面，而这种违抗命令的行动甚至会引起真正的哗变。为此，应当经常打其前卫，当然，除打其前卫之外，也可以打其他任何的部位。","language":"中文","translation":false},{"id":"che-guerrilla-3-46","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":46,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员完成任务和适应环境的顺利程度，或多或少取决于游击队员的装备程度。游击队员，虽是组成战斗集体的不可分割的部分，但有个人行动的特点。因此，每个人在自己的背包里应携带维持单独生活一个时期所必需的食物和日常“家当”。","language":"中文","translation":false},{"id":"che-guerrilla-3-47","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":47,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在讲到装备时，我们主要讲在游击战刚开始时，一个人处于地势崎岖，经常下雨，天气较冷，后有追兵的情况下所能携带的东西，也就是说我们处于古巴解放战争刚开始阶段所带的东西。","language":"中文","translation":false},{"id":"che-guerrilla-3-48","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":48,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一个游击队员的装备可分为主要的和次要的两类。主要的一类中有吊床。有了吊床，就可以得到适当的休息，再说，拴吊床的两棵树随时都可以找到，如果要睡在地上，吊床还可以作睡垫用。只要是下雨或地方潮湿（在热带山区是常有的现象），吊床对于睡觉就是必不可少的东西。一块尼龙雨布是吊床的附属品，尼龙布的大小以能遮盖住吊床为度。尼龙布的四只角系四根绳子，当中再穿一根绳子，两端系在绑吊床的那两棵树上。尼龙布中间的这根绳子，下雨时，就起到排水的作用。而它四只角的绳矛则系结在附近的灌木上，便形成为一个小小的帐篷。","language":"中文","translation":false},{"id":"che-guerrilla-3-49","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":49,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"毯子是不可缺少的，因为在山上一到夜里就很冷。也必需有件大衣，以防气温剧变。衣服是长裤和粗制衬衣（不管是否制服）。应有尽量结实的鞋子，鞋子是主要的用品之一，应留有后备，因为没有鞋子行军就非常困难。","language":"中文","translation":false},{"id":"che-guerrilla-3-50","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":50,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"因为游击队员把他的全部“家当”都打在背包里背在身上，所以背包就相当重要。最原始的背包可以用个随便什么口袋配上两只把手就成了；把手用麻绳做，但最好用市场上出售的帆布来做或者由皮匠做。除了全队带的或全队在休息的地方吃的食品之外，每个人自己还应随时带有个人的食品。必需的食品中最主要的有：人体的脂肪消耗所需要的动植物油、罐头食品（不到找不着东西煮来吃或罐头过多已影响行军的时候，不得动用），营养丰富的鱼罐头、炼乳（一种很好的营养品，特别是糖分多且美味可口）；也可以带奶粉；食糖也是必需品之一，食盐也是必需品，没有盐可就苦了。有些东西可作调味品，最通常的是用洋葱和大蒜，当然也可根据当地特点用其他东西。关于装备的主要种类，我们就讲这些。","language":"中文","translation":false},{"id":"che-guerrilla-3-51","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":51,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员应该带盘子，勺子和可作多种用途的猎刀。盘子可以是野外用的那种，也可以是一种饭锅或马口铁罐，用来烧肉以至烧芋头、土豆，或泡茶和咖啡。","language":"中文","translation":false},{"id":"che-guerrilla-3-52","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":52,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"保养枪枝要用特种油。油（如果没有特种油，缝纫机油也很好）应妥善使用。应常备有擦枪用的小布或呢绒布和擦枪筒的通条；应当经常地揩擦枪枝。应有标准的子弹带，也可按实际可能自己做，不过要做得相当好，不让一颗子弹丢失。子弹是战斗的基础；没有子弹，其他一切都是空的，所以应该象爱护金子一样爱护子弹。","language":"中文","translation":false},{"id":"che-guerrilla-3-53","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":53,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"每人应该带一只军用水壶或水瓶，因为需要大量喝水，而且水不一定能够随时找到。在药物方面，应该带常用药，如青霉素或其他种类的抗菌素；特别是口服的、密封得很好的镇痛解热药（如阿司匹林）以及适于治疗当地常见病的药品：抗疟片、治痢疾的磺胺、抗寄生虫药等，总之是符合当地特点的药物。有猛兽出没的地方，宜带适当的血浆，其余的医药配备应是外科方面的。此外，个人还应带治疗小毛病的小药包。","language":"中文","translation":false},{"id":"che-guerrilla-3-54","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":54,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员日常生活中的一项十分重要的补充，便是抽烟。既然歇下来的时候抽抽烟最能解除游击队员的寂寞，那就不管抽的是烟叶、雪茄烟或用烟斗吸的烟丝了。烟斗很有用处，烟斗可以在缺烟的情况下充分利用整支香烟或雪茄烟头。火柴最重要，不仅用来点烟，而且也用来点火。火是森林雨季的一个严重问题。最好带火柴和打火机，如果打火机没有油了，那火柴就可以代替。","language":"中文","translation":false},{"id":"che-guerrilla-3-55","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":55,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员应带肥皂。肥皂不仅可供个人卫生用，也可洗涤碗盘，因为碗盘肮脏，把发霉的东西连同新鲜的食物一起吃进而引起肠道感染或剧痛是经常发生的。有了上述的一切装备，游击队员就可以在森林中，在任何不利的条件下，安全地度过为避免任何险恶情况所必需的日子。","language":"中文","translation":false},{"id":"che-guerrilla-3-56","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":56,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"有些附带品，有时用得着，有时就成了累赘，不过总的来说，还是有很大用处的。指南针就是其中之一，尽管在某一地区，开始时常常用作确定方向的辅助物，但随着对地形的熟悉，也就逐渐用不上了，另外，在山区使用这个工具就很根难，因为它所指示的走向。对于从一地到另一地来说，虽然是直线，但往往被无法排除的障碍所隔断，所以并非总是很理想的。另一个有用的东西，就是雨天用来遮盖所有装备的一块优质尼龙布。应该记住，在热带地区，有几个月份经常下雨，而雨水则是游击队员装备（不论食品、军火、药品、纸张或衣服）的冤家对头。","language":"中文","translation":false},{"id":"che-guerrilla-3-57","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":57,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"可以带更换的衣服，不过一般说来，这会给新队员增加负担。通常最多就是带一条长裤，而不带内衣和毛巾之类的其他东西。因为游击生活表明，背着背包走来走去，就需要体力，而且逐渐会把作用不大的东西甩掉。","language":"中文","translation":false},{"id":"che-guerrilla-3-58","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":58,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一块既可用来洗涤碗盘又可作个人卫生用的肥皂一把牙刷、一支牙膏，这都是整洁用的附带东西。最好还带些书籍让队员们相互传阅：过去的英雄传记、历史或经济地理（最好是关于本国的）以及某些一般性的书籍，目的在于提高战士的文化水平，并使他们少去打牌、下棋或用其他方式来消磨时间。在游击队员的生活中，有时时间太多了。","language":"中文","translation":false},{"id":"che-guerrilla-3-59","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":59,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"只要背包里有空隙的地方，就要装上吃的东西，除非当地的条件极有利于找到食品。可以带些好吃的东西或次要的食品作为主要食物的补充。饼干便是其中的一种，尽管占地方多些而且容易压碎。在茂密的森林中，带把砍刀是有用处的。在十分潮湿的地区，带瓶汽油或弄些松树之类有树脂的木柴，这样，在需要时，即使柴火湿也能靠这些东西把火点着。","language":"中文","translation":false},{"id":"che-guerrilla-3-60","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":60,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"笔记簿应是游击队员日常的附带品，作记录资料、对外发信以及与其他游击队通讯联络之用；还要有铅笔或钢笔。手头应经常有几段细绳或粗绳，其用处很广，还要带缝补衣服用的针线和纽扣。带这种装备的游击队员把结结实实的全部“家当”背在自己身上，是相当重的，但足以保证在野营的艰苦活动中过得比较舒适。","language":"中文","translation":false},{"id":"che-guerrilla-3-61","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":61,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队不能按照死板的模式来进行组织。由于要适应所处的环境，所以就有许多不同的形式。为了阐述方便起见，假设我们的经验具有普遍的意义，但要时刻注意，在推广这一经验时要随时留有余地，可能还有另一种更适合于各武装组织特点的推广经验方式。","language":"中文","translation":false},{"id":"che-guerrilla-3-62","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":62,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队的人数是个最难确定的问题。人数有不同，部队的组成有不同，这些我们已经说过了。让我们假设一支游击队，处在有利地形，在山区，条件不象经常要转移那样坏，但也不象有了作战基地那样好。一支处在这样情况下的武装组织，作为一个战斗单位，不得超过一百五十人，这个数字已经是相当大的了，理想的是一百人左右。这是一个纵队，由一个少校（仍按古巴军衔）指挥。应该强调一下，在我们古巴革命战争中取消了下士和中士的军衔，因为这些东西被认为是暴政的象征。","language":"中文","translation":false},{"id":"che-guerrilla-3-63","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":63,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"从上述前提出发，一个少校指挥一百到一百五十人的整个纵队，可以由三十或四十人组成几个小队，有几个小队就设几个上尉。上尉的职责就是带领和团结他的小队，使它几乎永远团结一致地战斗，并负责小队的给养分配和一般的组织工作。在游击战中，班是个实战单位。每个班约八至十二人，有一个中尉；中尉对本班履行类似上尉的职能，但必须经常听从上尉的指挥。","language":"中文","translation":false},{"id":"che-guerrilla-3-64","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":64,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"由于要分成小单位进行活动，游击队作战的趋势就是以一个班为一个真正的作战单位。要在上述条件下作战而不失散，一个班最多只能有八至十人；因而，这班人在自己班长的指挥下活动，即使在一条战线上往往也脱离上尉的指挥（特殊情况除外）。永远不该做的事情，就是把一个作战单位拆散，而且在没有战斗的时候仍旧保持拆散状态。每个班、每个小队都应指定各自的领导接班人，如果班长、小队长倒下，就可以接替上去，接班人应是受过充分锻炼的能立即胜任新职务的人。","language":"中文","translation":false},{"id":"che-guerrilla-3-65","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":65,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"这支队伍的一个基本问题，是给养问题。这支队伍的官兵应享受同等待遇。给养之所以极端重要，不仅是因为长期缺乏营养，而且也是由于每天只能分一次。部队对公平十分敏感，对每日的给养总是斤斤计较的，所以，决不应对任何人有所偏袒。若有机会在整个纵队分配食品，那就应订出一条分配规则，并严格按照这条规则办事，同时还要重视分配给每人的食品的数量和质量。在分配衣服问题上，情形就不同了。衣服是属于个人使用的东西，在这方面应首先考虑两个情况；第一，申请人的需要（需要量几乎总是超过衣服分配量的）；第二，他们每人参加斗争的时间和功绩。全队人员参军时间和功绩很难记得清楚，应有专人负责填表记录，并经纵队负责人直接审核。偶然得到的、非集体使用的用品分配情况与此完全相同。烟叶和雪茄烟也应按人人平等这条普通准则来分配。","language":"中文","translation":false},{"id":"che-guerrilla-3-66","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":66,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"这项分配工作应有专人负责办理。这些人最好是直属司令部的。司令部负责很重要的行政、联络任务以及其他一切必须完成的特殊任务等。应让较有才智的军官参加司令部工作，而到司令部工作的士兵应是那种机灵的、最富有牺牲精神的战士，因为在大多数场合对他们的要求比对全队其他官兵的要求要严格得多；然而，他们在食品分配问题上却又不得享有任何特权。","language":"中文","translation":false},{"id":"che-guerrilla-3-67","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":67,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"除每个游击队员自己要带的整套装备外，还有许多全队性的集体装备需要平均分担。为此，可以采取两个解决办法（但都取决于部队非武装人员的数量）。一个办法是：把一切物品，如医药、外科或牙科医疗器械、多余的食品、衣服、一般器具、重型军事装备等，平均分配给各小队，由各小队负责保护。每个上尉把东西分到各班，每个班长再把东西分到个人。另一个解决办法是：如果不是全队人员都有武器，那就组成专门负责运输的班或小队。这种做法颇有好处，非武装人员不需要背枪和看管枪枝，就可以多背点东西，这就大大减轻携带武器的战士的负担；这样做法不大会有丢失东西的危险，因为东西比较集中。同时，可以答应将来发枪给背东西的战士作为一种奖励，便能激励他们背得多些，背得好些，表现出更大的热情。这些负责运输的班或小队行军时走在队伍的最后，并与全队其他的班、小队承担同样的义务和享受同等的待遇。","language":"中文","translation":false},{"id":"che-guerrilla-3-68","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":68,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"纵队执行的任务随纵队活动的变化而有所不同。若在营地驻扎下来，就应有专门的警卫小组。警卫小组应由受过战斗考验、经过专门训练的人组成，对其警卫任务应予以一定的奖励：一般是给他们某种独立性或把全队分配后某些多余的点心或烟草分发给他们。譬如，若一百人有一百十五包香烟，那么，多余的十五包就应分配给他们。前卫队和后卫队与部队其他部分完全不同，站岗放哨是他们的主要任务；但其余的每个小队也应有自己的警卫任务。放哨放得离营地愈远（特别是在自由区），各队的安全性就愈大。","language":"中文","translation":false},{"id":"che-guerrilla-3-69","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":69,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"宿营地点应选择高地，白天能控制广阔地带，夜里敌人也难于接近。如果要驻扎几天，则宜构筑防御工事万一受到袭击，可以很好作战。这种工事在游击队撤离时可以拆除，或者，如果形势已不需要完全掩盖纵队的行踪的话，则无须拆除。","language":"中文","translation":false},{"id":"che-guerrilla-3-70","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":70,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"常驻营地的防御工事应不断加以完善。应当记住，在山区，在经我适当选择的地形上，敌人所能使用的唯一有效的重型武器，便是迫击炮。利用当地的材料如木材、石头等搭起适当的防护顶，这就成了完善的掩蔽所，能够阻挡敌军的逼近而保护自己免受炮弹的轰击。","language":"中文","translation":false},{"id":"che-guerrilla-3-71","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":71,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在驻营地维持纪律是十分重要的。纪律应具有教育的性质，让游击队员们按时就寝，按时起床，制止没有公益的、涣散部队精神的娱乐，禁止酗酒等等。这些任务由内部秩序委员会执行，这个委员会是经过选择由最有革命功劳的战士组成的；它还有另一个任务，就是制止在那些从远处望得见的地方生火或尚未入夜便升起烟柱等行为，在纵队撤离时，如果要对行踪绝对保密，还要监督营地的清理工作。","language":"中文","translation":false},{"id":"che-guerrilla-3-72","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":72,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"要特别留心篝火。篝火的痕迹存留的时间长，所以要用土盖上，还要把废纸、空罐头和残羹剩饭统统埋起来。行军时，全队应保持肃静。命令是甩手势或耳语一个个地传到最后一人的。如果游击队是在陌生地区由自己开辟道路或由向导带路前进的，那么，前卫队应当按地形的特点走在前头一百米或二百米，或更远一点。在可能走错路的地方，在叉路口上留下一人等后面一个人来，如此一个一个接替，直到后卫队的最后一个人到达为止。后卫队也稍微落在部队后面一点，监视后面的道路，尽量消除部队走过的足迹。如果有可能引起危险的支路，则每条支路必须有小组进行监视，直到最后一个人走过去为止。专门由一个小队派出这样的小组，较为实际，虽然也可以由每个小队负责把监视哨移交给后续的小队，已交班的小组重新归队，这样一直等到全队走过为止。","language":"中文","translation":false},{"id":"che-guerrilla-3-73","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":73,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"行军不仅要步调一致，秩序井然，而且要始终保持下去。很清楚，第一小队是前卫队，其后接第二小队，中间是第三小队（可能是指挥部），然后第四小队，以及后卫队或叫第五小队，或按构成全队的小队数而定，但次序始终不变。夜行军要保持高度肃静，每人之间的距离要缩短，以免掉队迷路以致被迫放声讲话或点火的危险。火光是游击队员夜间的最大危险。","language":"中文","translation":false},{"id":"che-guerrilla-3-74","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":74,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"然而，如果上述行军是以袭击为目的的，那么，在到达某一指定地点（任务完成后统统要撤到那里）时，就把多余的负荷，如背包、饭锅等物卸下来，每个小队只带武器和军事装备继续前进。袭击点应事先有可靠的人调查过；他们事先接通关系，带来有关敌人警卫队、敌兵营的方位及守营人数等情报。于是制定明确的袭击计划，部署兵力，始终要考虑把全队精干部分用于牵制援敌。如果袭击敌兵营是牵制敌人，目的在于吸引援敌，以便在其必经的而易于埋伏的地方伏击之，那末，袭击敌兵营之后，应迅速派人向指挥部报告战果，看是否需要撤除伏击圈以防敌军从背后攻击。但不管怎样，在进行包围或直接出击时，在通往战斗地点的各条道路上始终都应有人站岗放哨。","language":"中文","translation":false},{"id":"che-guerrilla-3-75","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":75,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"黑夜里最宜用直接出击方式。如果游击队有足够的精力和胆量又不冒很大危险，就可以直接攻打敌军的营房。","language":"中文","translation":false},{"id":"che-guerrilla-3-76","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":76,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"包围敌人以后，就只有等待时机，逐步构筑战壕向敌收缩包围圈，用各种办法扰乱他们，特别是用火力迫使他们出来。在相当接近敌人时，“莫洛托夫鸡尾酒”［注：即汽油燃烧瓶。——译者］是非常有效的武器。如果“莫洛托夫大鸡尾酒”还投掷不到，可以用加特殊装置的猎枪发射。在古巴革命战争中，我们把这种武器叫做M-16。M-16的构成是：口径十六毫米可折猎枪装上两只撑脚，连同枪托构成三脚架，角度大约是四十五度；把前面两只撑脚向前或向后移动就可改变角度；给猎枪装上一只开口弹筒，在装弹筒之前把筒内全部霰弹取净，给它安上一支圆的木棍，越圆越好，与弹筒内壁紧紧吻合；这支木棍伸出在枪筒外面起投掷器的作用，棍的顶端加上一个合金装置，装置的底部有个橡皮垫起缓冲作用；然后在这个装置上放上汽油燃烧瓶。这种装置能把点燃的燃烧瓶投射到一百米或一百米以外的地方，而且命中率相当高。对于被包围的有许多木头建筑物或有易燃物质之敌，这是一种理想的武器，对在坷坎地带反击坦克，也是一种理想的武器。","language":"中文","translation":false},{"id":"che-guerrilla-3-77","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":77,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"图1 “莫洛托夫鸡尾酒”和猎枪装配图","language":"中文","translation":false},{"id":"che-guerrilla-3-78","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":78,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一旦胜利完成包围任务或达到既定目的而解除包围之后，各小队按次序撤到原来放背包的地方，恢复正常的生活。","language":"中文","translation":false},{"id":"che-guerrilla-3-79","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":79,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队员在这个阶段过的流动生活，使他们之间产生了亲密的友谊，但有时也使他们班与班，小队与小队之间发生危险的争功现象。如果不是引导得法，把这种现象变为有益的竞赛，那就会有破坏纵队团结的危险。最好从战斗初期就对游击队员进行教育，向他们阐明斗争的社会意义和他们的责任，旨在澄清他们的思想；并且对他们进行道德方面的教育，以便锻炼他们的性格，使得所获得的每一项经验成为新的取胜的武器，而不是成为争取生存的一种最普通的辅助物。","language":"中文","translation":false},{"id":"che-guerrilla-3-80","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":80,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"榜样是巨大的教育因素之一。因此，游击队指挥员应经常在战斗生活中作出光明磊落，富于牺牲精神的榜样。战士的提升应以勇敢、才能和牺牲精神这三者为依据，没有完全具备这三个必要条件的，就不能担任负责工作，否则，说不定什么时候会闹出乱子来。","language":"中文","translation":false},{"id":"che-guerrilla-3-81","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":81,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一个游击队员的品行如何，从他走到老百姓家里要东西的时候就可以看得出来。当地居民根据游击队要求派公差，要求粮食和某项必需品的方式以及为达到目的所使用的方法，就可以得出游击队是好还是坏的结论。对于这些问题，指挥员应当非常慎重，要对战士详细说明，给以应有的重要地位，也应以身作则进行教育。如果是进入城镇，应禁止喝酒，要事先通告部队，为部队作出遵守纪律的卓越榜样，并对城镇的进出口始终进行警戒。","language":"中文","translation":false},{"id":"che-guerrilla-3-82","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":82,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队的组织性、战斗力、英勇气概以及精神面貌都应受到被敌包围的战火考验。被围是游击战最危险的形势。在我们游击队员过去革命战争的行话中，把吓得要死的人那种惊惶的面孔叫做“被围攻者的面孔”。旧政权的头目们嚣张地把他们的进犯叫做“围剿”。然而，对于思想感情上同自己的指挥员一致又非常熟悉地形的游击队来说，这并不是什么了不起的问题。只要步步为营，避开敌人的锋芒，避开敌人重型武器的袭击，等到黑夜--这个游击队员的天然盟友--来临，就可去进行侦察，选择一条稳妥的道路，使用最恰当的突围办法，保持绝对的肃静，悄悄地溜之大吉。在上述的情况下，敌人要在黑夜里阻止一小队人突围，那是很难办到的。","language":"中文","translation":false},{"id":"che-guerrilla-3-83","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":83,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"战斗是游击队生活中最重要的事情，它在整个斗争发展过程中只占短暂的时间，然而这种关键性的短暂时间却具有特别重要的意义，因为每次小的接触，对于游击队员来说，都是一次带有根本性质的战斗。","language":"中文","translation":false},{"id":"che-guerrilla-3-84","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":84,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"前面我们说过，进攻一定要有胜利的把握。除了运用游击战在进攻时的战术这些一般特点外，还应指出每次战斗行动可能产生的不同特点。为了叙述方便，我们首先举有利地形上的战斗为例，因为这种形式的战斗实际上是游击战起源的标准形式，同时又是游击战取得实战经验来解决实战问题以前必须掌握的原则的一个方面。至于平原游击战，则永远是游击战发展壮大及其所处的环境巩固发展的结果，而伴随这种结果而来的，便是进行平原游击战的人们经验的积累，从而是这种经验的应用。","language":"中文","translation":false},{"id":"che-guerrilla-3-85","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":85,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在游击战的最初阶段，敌军部队会深入起义区。这时，针对敌军的兵力情况可以采取两种不同的袭击方式。一种是，用几个月的时间，有步骤地削弱敌人的进攻力量，并随着时间的推移逐步采用第二种形式：打击进犯敌军的前卫邵队。对敌军不利的地形起到阻碍他们前进的作用，因为他们要用相当的力量来防卫其侧翼，因此，敌军前卫队又必须有尖刀班，在向我纵深推进的时候，让尖刀班冒生命危险以保卫其后续部队的安全。游击队在没有足够的兵力，没有后备兵员而且敌人又很强的情况下，无论如何要歼灭敌人的尖刀班。方法是很简单的，只要配合得好。当敌前卫队尖刀班出现在我预先确定的地段（尽可能险陡）时，让他们进来，然后给予毁灭性的打击。这时，应另派一个小组去阻击敌军的后续部队，好让我们的人去收拾敌尖刀班留下的武器、弹药和装备。每个游击队员必须时刻牢记：游击队的武器来源于敌人；除特殊情况外，决不打无军火补充之仗。","language":"中文","translation":false},{"id":"che-guerrilla-3-86","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":86,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"如果游击队的实力足以全部包围敌军整个部队，那就包围之，或至少给这支敌军造成被围的印象。在这种情况下；我军前卫队要有强大的实力和构筑坚固的战壕，能够抵御敌军正面的猛扑（当然要把敌之进攻力量和士气估计在内）。当敌军被阻于某一特定地带时，我后卫部队便在敌军背后出现，发起进攻。由于所选择的地形使敌人难于侧翼运动，所以就易于布置狙击手，使也许八倍或十倍于我的敌军陷于火力圈之中。这时，只要还有足够的力量，便应控制各条来路，进行伏击，以牵制增援之敌。包围圈要逐渐（尤其是到黑夜）收缩；游击队员熟悉战地，而进犯的敌军则不熟悉，游击队员在黑夜越战越强，而敌人在黑暗中则越打越害怕。","language":"中文","translation":false},{"id":"che-guerrilla-3-87","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":87,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"用这种方法较易于全歼敌军或予以重创，以致使这支敌军不能重返战场，或要很长时间才能恢复元气。","language":"中文","translation":false},{"id":"che-guerrilla-3-88","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":88,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"如果游击队的力量还很小而又想阻止或击退敌军前进，那就应分成两至十人为一组的射手小组，从四面包围敌军。这种形式的战斗，比如说，是从右翼开始的，那么敌人必然倾全力于右翼并向它猛扑，正在这时，左翼又开火了，敌人又转向左翼；然后后卫或前卫又开火了，就这样轮番地打下去。这样做，游击队弹药消耗极少，却能使一支进犯的敌军不断受到威胁。","language":"中文","translation":false},{"id":"che-guerrilla-3-89","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":89,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"袭击敌军车队或敌军阵地的技术要适应作战地点的条件。但一般应保证，对一个被我包围的地方的第一次攻击是夜间突击某一个前哨。派有经验的人去袭击敌人阵地，很容易就打下来，其原因就是依靠攻其无备这个条件。对一次正常的包围来说，在敌人可能突围逃窜的地方只派少数人控制，而敌人可能来增援的通路则埋下伏兵来保卫。伏兵应这样配置：当第一道埋伏被突破以后。就散开或索性后搬，留下第二道伏兵，就这样一道道地伏击下去。但如果没有出其不意攻其无备这个因素存在，拿下敌营房这个意图是否能胜利实现，取决于游击队的包围力量是否能制止敌之增援。在这种情况下，敌人方面往往有大炮、迫击炮、飞机以及坦克的支援。但在有利于游击队的地形上，坦克这种武器是无足轻重的；它需要越过狭隘的道路，并容易被地雷炸毁。一般说来，这种列队前进的车辆，在这里就丧失进攻能力，因为它们要一辆跟着一辆走，充其量两辆、两辆并排前进。反坦克最好的、最可靠的武器，是地雷。但是在白刃战中，易于在崎岖地带使用的“莫洛托夫鸡尾酒”，是一种特别有效的武器，姑且不说火箭筒了。火箭筒对于游击队来说，是一种有决定性意义的武器，但很难搞到，至少在游击战初期难于搞到。对付迫击炮，可以采用战壕加护顶的办法。迫击炮用来轰击被围点威力巨大，但反过来，对付游动的围攻，如果不用大量排炮，那么它的威力就会降低。炮兵在游击战中作用不很大，因为它要安置在便于通行的地方，而且看不到游动的目标。飞机是敌军的主要武器，但攻击力也很有限，因为飞机的唯一目标是小小的战壕，而这些战壕一般又都构筑在看不见的地方。飞机可以投掷爆炸力很强的炸弹或凝固汽油弹，然而这些东西与其说是真正的危险，不如说是真正的缺陷。而且当我们尽量逼近敌军防线的时候，飞机就很难有效地袭击我们前卫的这些尖兵。","language":"中文","translation":false},{"id":"che-guerrilla-3-90","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":90,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"当包围用木料建筑的或易燃物建筑的敌营房时，如能到达近距离的地方，那么上述的“莫洛托夫鸡尾酒”就是一种极为重要的武器。如果是较远的距离，那么也可以用十六毫米猎枪（如上文所述）来发射已点燃导火线的燃烧瓶。","language":"中文","translation":false},{"id":"che-guerrilla-3-91","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":91,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在使用的各种地雷中，效能最高的（但其技术要求并不是经常能够达到），便是遥控雷。但是，触发雷、延期雷，尤其是拉线电发雷都非常有效，而且在山路上对人民武装来说几乎是不可攻克的防御力量。","language":"中文","translation":false},{"id":"che-guerrilla-3-92","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":92,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一种很好的防装甲车的方法，就是在路上挖掘有一定倾斜度的深沟，使坦克陷进容易，爬出来困难，就象下面这幅图那样，而且容易伪装，使敌人不易发现，尤其是在敌人夜间进犯或因游击队的抵抗不能指挥步兵走在坦克前面时。","language":"中文","translation":false},{"id":"che-guerrilla-3-93","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":93,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在不全是崎岖不平的地区内，敌人进犯的另一种普通方式，就是使用大体上是敞篷的卡车。敌军总是让一些装甲车开路，然后再开来运载步兵的卡车。这时，游击队可以根据自己的力量，将全队包围或把车队一段段切开，袭击其中的某一辆卡车，同时用地雷爆炸。在这种场合，行动要迅速，夺取敌军死者的武器后就撤退。若条件允许，可以进行全面包围，则如前面所述，遵循全面包围的一般规则包围之。","language":"中文","translation":false},{"id":"che-guerrilla-3-94","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":94,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"对于袭击敞篷卡车，有一种很重要的、可以发挥全部效能的武器，这便是猎枪。一支口径十六毫米的、装满霰弹的猎枪，其杀伤范围达十米，几乎是卡车的全部面积，可以同时把车上的人打死一些，打伤一些，给敌人造成莫大的慌乱。在这种场合，如果有手榴弹，那也是极好的武器。","language":"中文","translation":false},{"id":"che-guerrilla-3-95","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":95,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"对上述所有的袭击来说，最基本的是攻其无备。因为游击战术的主要特点之一，就是在于攻其无备，至少在打响第一枪的时刻是这样。如果当地农民知道有游击队出现，那就不可能做攻其无备。正因为这样，所以有关袭击的各项活动都应在黑夜进行。只有那些经过考验证明善守机密，忠诚可靠的人，才可以知道这些活动，从事联络工作。游击队员出发时背包应装满粮食，以便能在伏击的地方度过两天、三天或四天。","language":"中文","translation":false},{"id":"che-guerrilla-3-96","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":96,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"决不可过分相信农民能慎重保密，这首先是因为农民有一种爱说话、爱同家属或知己说长道短的习惯。其次是因为敌军士兵在战败后自然要对当地居民采取野蛮手段，在居民中制造恐怖；而在这种气氛下，一些要保命的人就会被迫说出不应该说的话，泄漏有关游击队的重要消息。","language":"中文","translation":false},{"id":"che-guerrilla-3-97","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":97,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一般说来，游击队选择的伏击地点，应当距离它的常驻营地至少有一天的路程。这是因为敌人对游击队的常驻营地总是多少知道一点的。","language":"中文","translation":false},{"id":"che-guerrilla-3-98","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":98,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"前面我们说过，在战斗中只要根据射击的方式便能分辨作战的双方：一方枪声猛烈而密集，是敌军散兵线的火力（他们弹药充足，惯于滥放枪炮）；另一方的枪声是有秩序的、单响的，这是游击队的火力。游击队员懂得每颗子弹的价值，使用起来非常节约，决不虚发一枪。同时，也决不为了节约弹药而放掉一个敌人或使我之伏击不能充分发挥效力。但他要预先把弹药计算好，在什么情况下可以使用，什么情况下应当控制使用。","language":"中文","translation":false},{"id":"che-guerrilla-3-99","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":99,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"弹药是游击队员的一个大问题。游击队经常可以搞到武器，而且一旦弄到就不会丢失，但是弹药却要逐渐打光，而且一般都是武器连同其弹药一起缴获的，从来没有或很少有单独缴获弹药的。每支缴来的武器只有供它本身使用的弹药，而没有多余的弹药供其他枪枝使用。所以，节约弹药是游击战的基本战术原则。","language":"中文","translation":false},{"id":"che-guerrilla-3-100","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":100,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"一个以当领导而自豪的游击队指挥员，决不能忽视部队的撤退。撤退应当及时，利落，要能抢救出游击队的全部辎重，不管是伤员、背包、弹药等都要统统撤出来，而决不能让队伍在撤退途中遭到意外袭击，更不容许荒唐到让队伍受到包围。","language":"中文","translation":false},{"id":"che-guerrilla-3-101","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":101,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"为此，在选作撤退的道路上，对敌人可能派遣部队向我包围的一切地方，都应当严密警戒，并必须有一个传递消息的系统；若遇敌人妄图向我包围，便可迅速地通知全体战友。","language":"中文","translation":false},{"id":"che-guerrilla-3-102","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":102,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在战斗中一定要有非武装人员，让他们负责收拾伤员或牺牲同志的枪枝和原属敌俘的枪枝，照管战俘，运送伤员，传递信件。此外，还要有一个组织良好的通讯队，铁腿、认真、受过考验、能在最短时间内把必要的通知送到。","language":"中文","translation":false},{"id":"che-guerrilla-3-103","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":103,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"武装人员身边所需的非武装人员的数量，是个十分相对的数字，但可以考虑给每十个武装人员配备两三个非武装人员。他们参加战斗，在后卫队从事各项必要的工作，保卫后撤阵地或传递信件（如上文所说）。","language":"中文","translation":false},{"id":"che-guerrilla-3-104","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":104,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"当游击队进行防御性战争的时候，也就是说当游击队坚守阵地，阻止敌军通过某一特定地区的时候，这就成为阵地战。但这种阵地战一开始的时候，也应始终带着出其不意的色彩。在这种场合，构筑战壕和其他一系列防御体系，是很容易被当地农民看到的，所以，一定要使农民留在友邻区内。一般说来，在这种阵地战中，反动政府会对该地区进行封锁，而没有走的农民必须到非游击活动区的商店去购买必要的食品。这些农民在关键时刻（正如我们所说的那样），他们走出这个地区，便会有意无意地向敌军走漏消息，这是十分危险的。在这情况下，焦土政策应成为游击队的战略基础。","language":"中文","translation":false},{"id":"che-guerrilla-3-105","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":105,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"然而，应该构筑成这样的防御工事和整个防御系统：只要敌军前卫队一到，就使它陷入我埋伏圈之中。在每次战斗中给敌前卫队的人造成总不免要送死这样一种心理状态，是十分重要的。因为如果敌军内部这种心理作用日益强烈，那么到了一定的时候，谁也不愿意充当前卫了。显然，一支部队没有前卫便不能动弹，所以又不得不有人充当前卫。","language":"中文","translation":false},{"id":"che-guerrilla-3-106","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":106,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"此外，如果认为适宜，还可以对敌进行包围战，侧翼袭击，牵制敌军或索性正面阻击。但在这样的情况下，凡易于被敌军用作侧翼进攻的地方，都应当加强防御工事。","language":"中文","translation":false},{"id":"che-guerrilla-3-107","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":107,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"显然，这说明要有比在前面说过的战斗更多的人员和武器，因为很清楚，敌人从四面八方封锁，可能突然进犯的道路又是那么多，所以游击队需要的人员就多了。这里，应当增加使用陷阱以及反装甲车的所有办法，并对永久性的因而也就容易被发现的战壕尽可能予以加强。一般说来，在这种防御战中，只要命令一下，就是死守防御阵地，并且必须最大限度地确保每个守卫阵地的战士的生命安全。","language":"中文","translation":false},{"id":"che-guerrilla-3-108","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":108,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"作远距离观察的战壕愈隐蔽愈好，特别是最好给它造个保护顶，以防迫击炮的轰击。六十·一或八十六毫米野战迫击炮打不穿一个好的、就地取材搭起来的简易护顶。这种护顶可用一层木头、泥土和石头筑成，再用一层东西伪装起来，使敌人看不见。一定要设一个出口，以便防守的人在情况危急时能出来而不至有很大的生命危险。","language":"中文","translation":false},{"id":"che-guerrilla-3-109","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":109,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"下图便是我们在马埃斯特腊山区的防御工事形式，它们有效地保护了我们兔受迫击炮的轰击。","language":"中文","translation":false},{"id":"che-guerrilla-3-110","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":110,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"上面的概述清楚地表明，固定的火线是不存在的。火线是个多少带点理论性的东西，因为它是在某一高潮时刻发生的，而又是非常灵活的、双方都可以渗透的东西。真正存在的是广大的“无人地带”，然而，游击战“无人地带”的特点，却是有老百姓的，而且老百姓是以某种方式同作战双方的某一方合作，当然大多数是同起义队伍这一方合作的。不能把老百姓从整个地区大批地赶走，因为要是这样做了，向大批居民提供食粮，这对作战的任何一方都会产生粮食供应问题。这种“无人地带”是敌军（一般在白天）和游击队（在黑夜）经常来的地方。游击队在这里找到了自己部队给养的十分重要的基地。为此，游击队在政治上必须加强整顿，并经常建立同农民和商人的良好关系。","language":"中文","translation":false},{"id":"che-guerrilla-3-111","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":111,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在游击战中，非直接参战的人员（即不携带武器的人员）的工作，是极为重要的。我们指出过关于作战地区通讯联络的某些特点，但通讯是游击队组织内部的一个机构。对最远的指挥部（如果有指挥部的话），或最远的游击小组的通讯联络应做到这样的地步：利用当地最简捷的方法，随时把信息从一地区送到另一地区；这个通讯系统不但应当在易防守地带（即有利地形区）有效，而且应当在不利地形区也同样起作用。有些情况是不能做到的，比如说，就不允许游击队在不利地形区域活动时，拥有现代化通讯联络系统，如电报机、公路等等；除非使用无线电报，因为无线电报是不可能被破坏的。但这种无线电报机只是使用无线电系统的防守严密的敌警备队才有，所以，如果这种无线电报机落到游击队手中，就必须改变密码和频率，这有时是相当麻烦的。","language":"中文","translation":false},{"id":"che-guerrilla-3-112","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":112,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"所有这些情况，都是我们追述古巴解放战争时发生的情形。有关敌人活动的每天的可靠情报，靠情报人员的报告而得到充实。所以，情报系统应该好好研究，细细琢磨，对情报人员要极其慎重挑选。在这种情况下，一个“反间谍”造成的损失是巨大的，但损失还不是最大；一个不确切的情报，突然造成的损失才是最大的，不管它是夸大了危险或缩小了危险，但危险是很难缩小的。农村的人对危险有扩大和夸张的普遍倾向，他们的幻觉产生各种妖魔鬼怪，一旦看到敌人一个排、一支巡逻队，就看成是千军万马，草木皆兵了。此外，情报人员应尽可能在表面上持中立的态度，使敌人察觉不到他们同游击队的种种联系。这项任务并不象想象的那么困难，通过战争可以找到许多人：商人、教职员，以至宗教界人士，都可以给这项任务以帮助，及时提供情报。","language":"中文","translation":false},{"id":"che-guerrilla-3-113","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":113,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"游击队获得情报和敌人掌握情报这两者之间有着明显的不同，这是游击战的最重要的特征之一。敌人需要穿越完全敌对的区域，遭到农民的冷遇；而游击队是农民的保卫者，家家户户都有自己的朋友甚至亲人，他们通过通讯联络系统把情报不断送进到游击队中央总部或本区的游击组织。","language":"中文","translation":false},{"id":"che-guerrilla-3-114","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":114,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"当敌军窜犯已暴露的游击地区时候，那里的全体农民响应人民的事业，便发生一个严重的问题，就是大多数农民愿意抛开自己的儿女，自己的事务，同人民军队一起撤退。一些农民要带着全家走；另一些农民则要留下来等待事态的发展。敌人向游击区进犯所引起的最严重的困难，就是有大量人家处于饥寒交迫以至危险绝望的境地。游击队应当尽量给他们支援，但必须防止他们由于远离自己的家乡逃到生疏的地区去可能遭到意外的不幸，防止他们在这种场合往往会遭遇到的灾祸。","language":"中文","translation":false},{"id":"che-guerrilla-3-115","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":115,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"要进行什么“式样的镇压”这一点人民的敌人是不会讲的。在每个地区，根据社会、历史和经济的不同状况，人民的敌人进行犯罪活动的残酷程度也是不一样的（虽然他们用来镇压的一般方法始终一样）。有的地方，人们逃难到游击区而把家眷留在家里，但这没有引起敌人很大的反应；有的地方，这样做的人，其个人财产就会被烧毁或充公；还有的地方，人外逃，而家中老小全部惨遭杀害。当然，游击队应该按照当地（或某一国家）同敌人作战所掌握的规律，对将要受到敌军蹂躏的农民事先进行妥善的安排和组织。","language":"中文","translation":false},{"id":"che-guerrilla-3-116","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":116,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"显然，必须作好准备把敌军从为害地区内赶走，这时，就要着重地搞敌人的给养方面，完全切断其交通线，出动小股力量粉碎他们取得补给的意图或迫使他们在这方面付出巨大的人力。","language":"中文","translation":false},{"id":"che-guerrilla-3-117","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":117,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"在上述战斗的各种情况下，无论在什么地方，战斗一方的一个十分重要的因素，便是正确使用后备兵员。游击队，就其特点说来，能够拥有后备兵员的情况是很少的，因为它经常进行战斗，而在战斗中没有一个人不是有所安排和使用的。但是，根据游击队的特点，无论在这个或那个地方游击队都必须拥有后备力量，以应付意外事件，钳制敌人的反扑或在某一关头起决定战局的作用。为此，游击队可以根据它的组织情况和某个时期的特点和可能，建立一个“王牌”小队，哪里最危险，就让它到哪里去；这个小队可以命名为“敢死队”或其他什么名称均可，只要它实际上能完成这个名称所赋予的使命。“敢死队”应出没在一切有决定性战斗的地方：对敌人前卫队进行突然袭击，保卫最薄弱、最危险的地点，总之，出现在敌军威胁到突破火线的任何地段。加入这个小队，应当是完全志愿的，而且对加入这个小队的人来说，应几乎象得到一次奖赏一样。随着时间的推移，“敢死队”终将成为任何一支游击队的宝贝，而荣获‘敢死队员”称号的游击队员会深受全体战友的敬佩和爱戴。","language":"中文","translation":false},{"id":"che-guerrilla-3-118","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":118,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"五、游击战的开始、发展和终结","language":"中文","translation":false},{"id":"che-guerrilla-3-119","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":119,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"关于游击战，我们已经说得太多了。那末，现在我们来说说关于游击战合乎理想的发展。假设它诞生时只有一个组织，处在地形有利的地区。我们的叙述就从这里开始。","language":"中文","translation":false},{"id":"che-guerrilla-3-120","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":120,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"换言之，我们把古巴的经验再次进行抽象的概括。开始时，只有一小队人，多少有些武器，人员成分也比较单纯，差不多只隐蔽在山峦起伏、有稠密森林的地区，同农民很少接触。它进行了几次成功的奇袭，名声就传开了，于是千些被剥夺了土地或为保卫自己的土地而斗争的农民以及其它阶级的有理想的青年来参加游击队。这支小小的游击队胆量大了，便出没在没有局面点的区域，同当地群众接触也多了。它又进行几次袭击，总是打了就跑；它还突然地同敌军某部队展开一次战斗并歼灭其前卫队，人们又陆续加入游击队。游击队人数增加了，但仍然完全保留原来那样一个组织形式，只是无须那样小心翼翼，而且也敢于在居民点更多的区域活动了。","language":"中文","translation":false},{"id":"che-guerrilla-3-121","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":121,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"不久，这支游击队可以扎下历时几天的临时营地：只要听到敌军迫近或受敌机轰炸或仅仅是怀疑有那样的危险，就立即拔营离去。随着群众工作的开展，游击队人数继续增加；群众工作逐步使每个农民都成为解放战争的积极参加者。终于有一天，选到了一块敌人难于到达的地方，安营扎寨，建立起头一批小型的工厂：制鞋厂、卷烟厂、缝纫工场、兵工厂、面包房、医院、电台（如果可能有的话）、印刷所等等。","language":"中文","translation":false},{"id":"che-guerrilla-3-122","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":122,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"于是，游击队就有了新的组织、新的机构。它是伟大运动的首脑、具有政府一切特征的小型政府。建立法院审判案件，颁布法律（如果可能），并继续对农民群众进行宣传教育，也对工人群众（如果附近有的话）进行宣传教育工作，吸引他们参加革命事业。敌军发动一些进攻，但被打垮了，游击队拥有的枪枝数量增加了，因而人数也增加了。但到了一定时候，它的活动范围如果没有按人数增加的比例而相应扩大，那么在这个时候，它就把适当的力量（一个纵队、一个小队等等）分出来，派到另一个地区去战斗。","language":"中文","translation":false},{"id":"che-guerrilla-3-123","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":123,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"这支新的游击队伍到那里去工作，尽管其工作特点有所书同，然而是按照自己带去的经验，按照各支游击部队渗透到各战区所得的普遍经验而开始工作的。与此同时，中央总部不断壮大，它得到来自远方各处的粮食、有时是枪枝这种物质支援；人员也不断增加。总部以颁布法令来继续进行政府的各项管理工作；建立各种学校，对新兵进行教育和训练。各级指挥员则随着战争的发展逐渐掌握战争的知识，而他们的指挥能力也伴随其所负责的部队数量和质量的增长和提高而不断地得到增长和提高。","language":"中文","translation":false},{"id":"che-guerrilla-3-124","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":124,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"到了一定的时候，如果还有远的地区，那么又要派出新的纵队把已获得的先进经验带到那里去，如此继续循环不已。","language":"中文","translation":false},{"id":"che-guerrilla-3-125","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":125,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"但这时候还会有敌占区，即对开展游击战不利的地区。可以派小分队到那里去袭击公路，炸毁桥梁，埋置地雷，制造不安气氛。随着战争本身的变迁，运动也继续发展；大量的群众工作使得这些游击力量在这个不利地形区的活动较为自如了。于是，就进入游击战的最后阶段--城郊地区的游击战。","language":"中文","translation":false},{"id":"che-guerrilla-3-126","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":126,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"破坏活动在这个地区大大地扩展。整个区的生活陷于瘫痪，这个区就被我占领了。于是又向另外几个区发展，与敌军展开固定战线的战斗，可以向他们夺取重型武器（甚至坦克），战斗双方的力量均衡了。当游击队从局部胜利转变到最终胜利时，敌人就垮台了，就是说，迫使敌人在游击队所安排的条件下接受战斗，于是他们就被歼灭或举手投降。","language":"中文","translation":false},{"id":"che-guerrilla-3-127","author":"切·格瓦拉","title":"游击战","location":"第二章 游击队","page":3,"paragraph":127,"url":"https://www.marxists.org/chinese/guevara/1960/02.htm","text":"这就是过去古巴革命战争各个阶段的简要情况，但其内容大体上具有普遍意义。只不过在别的国家里并不一定具备象我们解放战争中人民、形势和领袖这三者那样密切的配合。更不用说，菲德尔·卡斯特罗集中表现了一个军事家和政治家的卓越才能。我们的登陆、我们的斗争和我们的胜利都归功于他的远见卓识。当然，我们不能说，没有他，人民就不能胜利；但我们可以说，没有他，人民的这次胜利就要付出更大的代价，而且效果也不会这样圆满。","language":"中文","translation":false},{"id":"che-guerrilla-4-1","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":1,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"中文马克思主义文库 -> 切·格瓦拉 -> 《游击战》（1960）","language":"中文","translation":false},{"id":"che-guerrilla-4-2","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":2,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"正确解决给养是游击战争的一个根本性问题。凡在一地活动的游击队必须依靠当地的物产而生活，同时也必须使当地的农民--向游击队提供物品的人们--能生活。因为在艰苦的游击战争时期，尤其是初期，游击队不可能抽出力量来搞自己的给养，更不要说，在镇压部队随时可以进入活动的地区里，这样的给养是容易被敌军找到和破坏的。所以，在最初阶段，游击队的给养总是取之于当地的。","language":"中文","translation":false},{"id":"che-guerrilla-4-3","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":3,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"随着游击战形势的发展，游击队必须有来自战线或战区以外的给养。起初，游击队的生活只能是依靠农民所生产的东西；也可以到杂货店去购买一些东西，但决不会有自己的补给线，因为没有地盘能建立这样的补给线。补给线和食品店的建立是以游击战争的发展为条件的。","language":"中文","translation":false},{"id":"che-guerrilla-4-4","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":4,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"首先，游击队要赢得当地居民的绝对信任。要取得这种信任，游击队应对他们的问题采取积极态度，经常给予帮助和指导，保护他们的利益和惩办坏人。这些坏人妄图利用当地混乱时刻横行霸道，驱逐农民，夺占他们的产品，放高利贷，等等。我们的路线应是温和的，同时又是强硬的。对待一切革命运动的真诚同情分子，采用温和与自然协作的办法；而对于直接攻击革命运动，挑拨离间，或向敌军提供重要情报者，则采用严厉强硬的手段。","language":"中文","translation":false},{"id":"che-guerrilla-4-5","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":5,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"游击队会逐步熟悉当地的情况，从而能够更加便利地进行活动。应该遵守的基本原则是：从友人那里拿来的一切货物，一定要付给代价。这些货物可以是当地的土产或商店出售的物品。这些货物经常是赠送的，但是，有的时候农民的经济情况使他们无力赠送。有的时候为了战争的需要，游击队被迫闯入粮店或食品商店，但无法付款，理由很简单，因为无钱可付。在这种情况下，游击队一定要给商人以债券，即债款证明，也就是上文已说过的“信用券”。这种办法最好是对解放区以外的人们实施，所以遇到这样情况，要尽可能早一些付还或部分偿还欠款。当形势发展到足以在敌军统治区之外能长久保持一块地区时，可以进行集体种植。在那里，农民为游击队耕种。这样，就能确保一个经常性的妥善的农产品给养来源。","language":"中文","translation":false},{"id":"che-guerrilla-4-6","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":6,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"如果游击队的志愿兵人数大大超过了所需要的人数，又没有武器，而且政治形势也不容许派遣这些人到敌占区去，在这种情况下，起义军可以叫他们和其他人员去收集农产品，用以保证给养；并填写他们的履历表，以便使他们今后转正为战斗员。然而，最好还是由农民直接去耕种，因为他们更善于农活，劳动热情更高，收效也更大。当条件更加成熟时，可以购买全部农产品，并根据各类产品的情况，或存放在农村，或存放在商店，以供游击队之用。","language":"中文","translation":false},{"id":"che-guerrilla-4-7","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":7,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在负责供应军队兼顾农村居民的机构建立以后，为办理农民之间交换产品的工作，就要把所有的粮食集中在这些机构中，游击队成为他们产品交换的中间人。","language":"中文","translation":false},{"id":"che-guerrilla-4-8","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":8,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"如果形势发展得更好，在游击区内可以确定各种税收，这些税收尽可能不要太重，特别是不能伤害小生产者。首先应该注意农民阶级和游击队之间的关系，因为游击队本身就是来自这个阶级的。","language":"中文","translation":false},{"id":"che-guerrilla-4-9","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":9,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在某些情况下，捐税可以用现款支付；而在其他情况下，则要用实物支付，用以扩充给养。肉类是必需品之一。必须保证肉类的生产和储藏。如果没有安全的地区，就可由表面上与游击队毫无关系的农民来建立农场，饲养母鸡、山羊、猪等。所有这些牲畜是购买来的，或直接从大地主那里没收来的。在有大庄园的地区里，往往有大量的牲畜。可把它们宰了腌起来，这样储藏的肉类可供长期食用。","language":"中文","translation":false},{"id":"che-guerrilla-4-10","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":10,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"这样，还可以得到畜皮，用以发展初步的皮革工业，为制鞋业提供原料。鞋子是游击战争的基本用品之一。游击队的食品在很大程度上依赖当地产品，但是一般说来，那些必不可少的食品是肉类、食盐、蔬菜、薯类或谷物。基本食品总是由农民生产的。在古巴奥连特省的山区，基本食品是芋头；在墨西哥、中美洲或秘鲁山区，是玉米；在秘鲁还有土豆；在有些地区如阿根廷，基本食品是肉类；其他地区则是小麦。必须始终保证部队有基本食品和油脂的给养，无论是动物油还是植物油，都能使基本食品更加好吃。","language":"中文","translation":false},{"id":"che-guerrilla-4-11","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":11,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"食盐是做菜必不可少的东西。当游击队的驻地在近海靠海的时候，必须马上建立小型晒盐场，以确保一定盐产量供应部队，还经常要有剩余。请记得，对于上述只能生产某些食品得农村地区，敌人容易进行包围，并使它处于极端贫困的境地。为了防备这种情况，最好是依靠农民组织和一般民众组织。要保证当地居民能有最低限度的供应品，使他们在最艰苦的斗争时刻，至少能够生活下去。应该力图尽快地拥有充足的不易霉烂的食品，例如玉米、小麦、稻米等谷物，因为这些谷物能储藏相当长时间，还要储藏面粉、食盐、砂糖及各种罐头食品；同时也要种植必要的农作物。","language":"中文","translation":false},{"id":"che-guerrilla-4-12","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":12,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在当地驻军的粮食给养问题获得解决的时候，仍需大量的其他物品，如制鞋所需的皮革(如果还不能建立硝皮工业以满足当地需要的话)，做衣服所需的布匹以及其他用品；出版报纸所需的纸张、油墨、印刷机、油印机和其他一切工具。","language":"中文","translation":false},{"id":"che-guerrilla-4-13","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":13,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"总之，随着各个游击队逐步建成和其组织程度逐步复杂化，需取于外界的东西也日益增多。为了满足这种需要，必须充分发挥各补给线的作用。而这些补给线，基本上是由对游击队友好的农民构成的。补给线有两头，也就是说，一头在游击阵线内，另一头在城市中。它从游击区出发，穿过一切许可物资通过的地方。农民渐渐习惯于这种运输的危险(分成小组，他们会干得更加出色)，不冒极大的危险就能把所需要的物资运送到指定地点。按照当地的情况，用骡子一类的牲口，或用卡车运输，这种运输可在夜间进行，这样，给养工作就能很好地进行。但必须考虑到，这种补给线是在作战地区附近的。","language":"中文","translation":false},{"id":"che-guerrilla-4-14","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":14,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"还必须组织一条来自远方地区的补给线。这些远方地区应提供必要的现款来采购物品以及提供在村镇和地方城市搞不到的工具。这样的补给线必须靠采用秘密债券使游击战争的同情者直接捐赠的办法来加强。对于负责运输的人员，一定要经常严格监督，当他们没有按照起码道德标准办事情的时候，对他们要严肃追究责任。采购付款，可用现钱；而当游击队离开他们作战根据地，闯入新地区活动的时候，也可使用“信用券”付款。在这种情况下，除了从随便哪一个商人那里拿取货物之外，没有其他办法。而这个商人也只能靠游击队的信用，看它是否有可能偿还这笔账目。","language":"中文","translation":false},{"id":"che-guerrilla-4-15","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":15,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在所有这些经过农村的补给线上，必需有一系列人家作为落脚点或中间站，在那里，白天人们把货物隐藏起来，到夜间，继续搬运。这些人家只有直接负责办理给养的人才能知道，并尽量使他们家庭成员少知道转运之事，尽管他们都是游击队较信任的人们。","language":"中文","translation":false},{"id":"che-guerrilla-4-16","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":16,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"骡子是这种运输工作最有用的牲口之一。骡子具有难以置信的吃苦耐劳的能力，能穿过最崎岖的地带，能驮上一百多公斤货物一天又一天地行走，而且对饲料的要求不高，所以骡子是最理想的运输牲口。骡子应该装上完整的铁蹄，内行的赶强人应尽量地照顾它。这样，游击队就能拥有非常有用的真正的四脚队伍。但是，在许多悄况下，尽管骡子能吃苦耐劳，有承受繁重劳动的能力，但是在极难通过的特殊地方，也不得不把骡子驮的货物卸下来。为了避免这种情况，就要有一个小组负责修路，以便让骡子通过。如果所有这些条件都已具备，能恰当地组织给养，并且起义军与农民保持最好的关系，那么对整个游击队来说，就有一条有效而持久的补给线了。","language":"中文","translation":false},{"id":"che-guerrilla-4-17","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":17,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"起义运动的民政组织，无论在内部战线上或外部战线上都是很重要的。当然，内部战线和外部战线有很不相同的特点，其职能也同样如此，即使它们在同一名称之下也有所不同。例如，收税这一项工作，在外部战线所能做的与在内部战线所能做的就有不同；宣传工作，给养工作也都不一样。让我们先从内部战线的工作谈起。","language":"中文","translation":false},{"id":"che-guerrilla-4-18","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":18,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"所谓“内部战线”，我们已经说过，它至少是相对地已由解放武装力量控制的地区，也可认为是有利于开展游击战的地区。因为如果没有这些条例，也就是说，如果游击队是在不利地区开展游击战争，那么游击队组织只能在广度方面而不是在深度方面得到发展。游击队可以逐步开辟一些新的地区，但不会有内部组织，因为这样的地区，容易被敌军渗透。在内部战线，我们可以有一系列组织，它们各自执行特殊任务，使民政工作办得更好。宣传工作一般地是直接属于部队的，但是也可在部队监督之下从部队分出去。(总而言之，这一点是非常重要，我们将另行讨论。)收税工作是属于民政组织和属于一般农民组织的，如果有工人的话，同样属于工人组织，不过这两个组织要归一个局管辖。","language":"中文","translation":false},{"id":"che-guerrilla-4-19","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":19,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"如前一章已说明的那样，可通过各种途径而获得税收；直接税和间接税，直接捐献和没收财，所有这一切都将大大充实游击部队的给养。","language":"中文","translation":false},{"id":"che-guerrilla-4-20","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":20,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"必须非常重视的一点是，游击队无论如何不应该以直接行动损害当地的剂益，虽然由于敌人包围所造成的损害我们负有间接责任，敌人会利用这点来反复进行宣传。正是由于这个情况，决不应该制造与当地农民冲突的直接原因。例如不应该明文规定禁止解放区的农民到外区去出售他们的产品；遇到临时的非常情况时，那应另作别论，即使如此，也应把原因向农民解释清楚。对于游击队的每一个行动，一定要由必要的宣传部门说明这一行动的理由。一般地说，如果一个农民有自己的子女、父母兄弟或亲戚在游击队里，那么这个农民就比较容易了解游击队的行动，并把这种行动看作为自己的事情。","language":"中文","translation":false},{"id":"che-guerrilla-4-21","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":21,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"既然与农民的关系是如此重要，就应该建立一些组织加以指导和管理。这些组织不仅仅限于在解放区，而且还要与附近的地方有联系。正是通过这些联系，游击队可以渗透到整个地区，以便将来扩大游击阵线。农民逐渐散播革命种子，进行口头和书面宣传，讲述在其他地区人民是怎样生活的，宣传已颁布的保护小农的法令以及宣传起义军的牺牲精神。总之，这一切为支援起义军造成了必要的气氛。","language":"中文","translation":false},{"id":"che-guerrilla-4-22","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":22,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"各农民组织也应建立一定形式的联系，这种联系使得游击队能随时调节农产品，能通过一些比较公道的中间人和农民阶级中较老实的人，把产品销售到敌占区。在这种情况下，一方面中间商人对革命事业有好感，因而他们可以不顾危险；另一方面因为他们热衷于追求金钱，这就驱使他们去利用危险来达到获利的目的。","language":"中文","translation":false},{"id":"che-guerrilla-4-23","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":23,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在谈到给养问题的时候，我们已经提到筑路部门的重要性。当游击战争已发展到一定程度时。已有几个比较固定的中心点，就不必象没有驻地在而在各地区流动了。那时应修筑一系列道路，从只可通过一头骡子的羊肠小道到可通汽车的宽阔大路。但这样做时必须考虑到起义军的组织能力和敌人进攻的能力，考虑到敌人可以破坏这些道路，甚至可以利用这些由我们修筑的道路，轻而易举地攻入我们的驻地。因此，筑路应该按照下面基本的原则进行：筑路的地区只能是在那些不筑路就无法运输给养的地区，而且只能在游击队已有把握打退敌人进攻、保持自己阵地的情况下修筑。如果筑路是为了联系一些地点使交通更为方便，而这些路又不是那么重要，修筑时也不会引起危险，那可另作别论。","language":"中文","translation":false},{"id":"che-guerrilla-4-24","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":24,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"此外，还可以开辟其他通讯线路。其中一条很重要的通讯线路就是电话线，可以把它敷设在山上，其方便之处是可以把山上的树木作为电线杆，其优点是不容易被敌人从高处的了望哨所发现。并且这个电话敷设网的所在地也是敌人不可能到达的地方。","language":"中文","translation":false},{"id":"che-guerrilla-4-25","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":25,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"司法部门或司法、革命法律和行政的中央部门，是有了自己区域的游击队的极重要的机关之一。这个机关应由熟悉国家法律的人员负责，如果他们能从司法观点了解当地的需要，那就更好了。他们可逐渐颁发一系列法令和条例，帮助在游击区内的农民生活正常化、制度化。","language":"中文","translation":false},{"id":"che-guerrilla-4-26","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":26,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"例如，根据我们古巴战争的经验，我们制定了一部刑事法典，一部民事法典；制定了对农民的供应条例，土改条例。随后，制定了几条法律，用以惩办那些切望在几天后举行的全国选举中当选的人；还制定了马埃斯特腊山区的土地改革法。此外，司法部还负责各游击纵队的会计事务，负责解决它们的钱款问题，有时还直接参与它们的给养事务。","language":"中文","translation":false},{"id":"che-guerrilla-4-27","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":27,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"我们所介绍的这一切都是有灵活性的。它的依据就是在特定的地区内在一定地理历史条件下所取得的生动经验，所以在地理、历史和社会条件不同的其他地区，应该按照那里的经验，对上述的内容加以修改。","language":"中文","translation":false},{"id":"che-guerrilla-4-28","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":28,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"除了司法工作以外，还必须非常注意游击区内的一般卫生工作，这个工作应通过能给全体农民以尽量完备的医疗的各个总医院，即各个中央军医院来做。在这种情况下，是否能够提供适当的医疗条件，也取决于革命所获得的成就。民众医院和民众一般卫生工作是直接与起义军联系的，其职务由起义军的军官和士兵负责。他们执行双重任务：一方面治疗民众的疾病，另一方面指导民众增强健康，因为处在这样条件下的居民，其卫生方面的严重问题，在于他们完全不懂得最起码的卫生知识，因而使他们卫生方面的不良情况更加严重了。","language":"中文","translation":false},{"id":"che-guerrilla-4-29","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":29,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"我已经说过，税收工作也是属于司法总部的。","language":"中文","translation":false},{"id":"che-guerrilla-4-30","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":30,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"商店是很重要的。一旦游击队建立了一块可以开始定居的地方，就应立即开设尽量整齐的商店，逐步加强对商品的最起码的保管，尤其要为以后对商品的公平分配加强监督，这是改变过去不公平分配的唯一方法。","language":"中文","translation":false},{"id":"che-guerrilla-4-31","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":31,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在外部战线上所进行的工作，无论是工作性质和工作量都有所同。例如宣传工作，应是全国范围的，带有指导性的，宣传游击队员所获得的胜利，号召工人和农民参加群众的现实斗争；如果在外部战线上有取得了胜利的消息，也应予以报导。外部战线上的税收工作是完全秘密的，必须小心谨慎地进行，最基层的收税员和游击队税局出纳员之间的联系应完全隔断。","language":"中文","translation":false},{"id":"che-guerrilla-4-32","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":32,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"税局这个机构应分布在能构成一个整体的各地区里。这些地区可以是一些省、一些州、一些城市、或一些村庄，这都取决于运动的规模。在所有这些地方，应有一个财政委员会，负责决定税收的方针。最初可以通过债券或直接捐献的办法搞到钱款；而当游击战争处在深入阶段，就可以征税，因为那时工厂主慑于起义军的强大威力，就会不得不交纳税款。给养工作应符合游击队提出的需要，并且把各种商品组成有机的联系，这样，最普通的商品就可从附近地区获得，而那些真正稀少的货物或其他地区难以弄到的货物就到大城市去采购。然而要不断设法使这种联系尽可能在最小范围内进行，只让极少数人知道这回事，这样就能够有较充足的时间完成他们的使命。","language":"中文","translation":false},{"id":"che-guerrilla-4-33","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":33,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"破坏工作应由外部战线民政组织进行指导，并取得总司令部的配合。在特殊情况下，是否采用暗杀手段，要加以分析。一般说来，我们认为暗杀活动是消极的，但用以消灭个别由于反人民的暴行和残酷镇压手段而罪恶昭彰的坏人，可作为例外。我们古巴斗争的经验表明，有许多优秀同志的生命原是可以保存的，但是为了执行意义不大的任务而有时牺牲于敌人报复的枪弹之下。他们付出的代价和他们执行任务所得的结果是根本不能相比的。所以不应当采用不分青红皂白的暗杀恐怖手段。我们赞成团结群众的办法，向群众灌输革命思想，使他们逐步成熟起来，以便在一定时刻，在武装力量的支持下他们能够动员起来，以决定有利于革命的均势。","language":"中文","translation":false},{"id":"che-guerrilla-4-34","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":34,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"因此，必须依靠专业工人和农民的群众组织。它们在各自组织内的群众之间，散播革命种子，让他们宣讲起义军的刊物，指出事物的真相，因为革命宣传工作的特征之一就在于它的真实性。这样，逐步地争取群众，并在他们中间选择工作优秀的人，吸收他们参加起义军，或使之担当很重大的任务。","language":"中文","translation":false},{"id":"che-guerrilla-4-35","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":35,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"这就是我们所勾划的在人民斗争时刻的游击区内外民政组织的一幅草图。有可能使之达到最完美的地步。再重复一遍，我所说的是我们古巴的经验。新的经验可能使这些观点改变和完善。我们所提供的是一幅草图，而不是一部圣经。","language":"中文","translation":false},{"id":"che-guerrilla-4-36","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":36,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在革命发展的全过程中，妇女所能起的作用是非常重要的。应当强调这一点，因为在我们这些国家里，由于殖民思想作怪，低估妇女的作用，因而她们处在真正被歧视和不利的地位。","language":"中文","translation":false},{"id":"che-guerrilla-4-37","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":37,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"妇女能做较困难的工作，能和男人并肩战斗，在部队中并没有造成象某些人想象的所谓男女两性关系的冲突。","language":"中文","translation":false},{"id":"che-guerrilla-4-38","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":38,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在严格的战斗生活中，妇女是具有自己特性的战友，她们能做同男人一样的工作。她们也能战斗，在体力上虽然比男人弱，但是战斗力并不比男人差。她们能执行男人在一定时刻所执行的各种战斗任务。她们在古巴斗争的某些时刻发挥了显著的作用。","language":"中文","translation":false},{"id":"che-guerrilla-4-39","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":39,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"当然，女战斗员人数较少。有些时候，游击队为了整顿内部战线，要力求削减那些体质较差的战斗员。在这种时刻，妇女可以调去做大量的特殊工作，其中最重要的工作之一，也许是最重要的工作，就是在各种部队之间的通讯联系工作，尤其是驻在敌区内的部队之间的通讯联系工作。运送货物，传递消息，转送钱款以及小型的但有重大意义的东西，应该委托那些游击队绝对信任的妇女办理。她们会千方百计地去完成这些运送工作。应该看到，不管反动派如何野蛮镇压，也不管搜查如何严厉，与男人相比，妇女的遭遇总是要稍微好一些，她们能够把所带的消息或重要的机密信件送到目的地。","language":"中文","translation":false},{"id":"che-guerrilla-4-40","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":40,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"作为普通的通讯员，无论是口头的或书面的传递，妇女总比男人能更自由地执行她们的任务，因为她们较少引起敌方士兵的注意，同时也使敌方士兵有减轻危险的感觉。敌人之所以常常干出野蛮行动，是因为害怕陌生人对他进行袭击，游击队的行动方式往往就是这样。","language":"中文","translation":false},{"id":"che-guerrilla-4-41","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":41,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"妇女可以担任那些被隔开的部队之间的联络工作，她们可以把信件传递到战线以外甚至国外，她们甚至还能把一些体积不大的东西如子弹藏在特制的腰带里，束在裙子里面运送出去。在这时期，妇女也可以担任她们习惯做的日常炊事工作。对于生活在极端艰苦的条件下的战士来说能吃到美味可口的饭莱，一定会感到十分高兴(游击战争中的战士所受的最大痛苦之一，就是吃一种有粘性的、冷的、完全无味的干食品)。女炊事员可大大改善部队的伙食；此外，妇女也能安心做这些家务工作。因为游击队中所碰到的问题之一，就是担负日常平凡工作的男战士瞧不起这类工作，经常想丢下这类工作去参加积极战斗的部队。","language":"中文","translation":false},{"id":"che-guerrilla-4-42","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":42,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"妇女另一项重要任务是进行初级教育和革命理论教育，教育的主要对象是当地农民，但也可以是革命战士。学校是民政组织一部分，基本上应有妇女担任教师，因为她们对儿童有更大的热情，也能博得儿童对她们的好感。此外，当游击战线已经巩固并有了一个后方的时候，社会调查工作也可由妇女来做。她们对当地各种经济和社会弊病进行调查，以便在可能范围内消除这些弊病。","language":"中文","translation":false},{"id":"che-guerrilla-4-43","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":43,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在卫生工作方面，妇女无沦是当护士还是当医生，都能发挥重要的作用。她们比那些粗鲁的男战友具有无限的温柔。当伤病员丧失战斗能力，忍受着艰难的生活，也许忍受着极大的痛苦，并冒着游击战本身所具有的许多危险的时候，这种女性的温柔是十分可贵的。","language":"中文","translation":false},{"id":"che-guerrilla-4-44","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":44,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"如果游击队已经到达建立小型战争工业的阶段，妇女也能在这里工作，特别是在缝制军服工作方面。这种工作在拉丁美洲国家里一向是妇女的传统职务。用一台普通的缝纫机和几件衣服样品，她们就能干得很出色。在民政组织的其他工作中，妇女也能给予帮助，并能完全顶替男人。在缺少人员携带武器的情况下，妇女还应携带武器，虽然这在游击队生活中是非常罕见的事情。","language":"中文","translation":false},{"id":"che-guerrilla-4-45","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":45,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"对队伍中的男女战土必须经常给予适当的教育，为的是要避免一切不规矩的行为，这些行为能使部队的风纪受到腐蚀。但是，按照游击队法律的简单规定，应该准许无婚约的男女故士谈恋爱或结婚，在山区过夫妻生活。","language":"中文","translation":false},{"id":"che-guerrilla-4-46","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":46,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"游击队员所碰到的严重问题之一，就是难以避免生活中会出现的一切事情，特别是难以避免负伤和生病，而这类事情在游击战争中是常常碰到的。在游击队里，医生执行非常重要的任务，严格地讲，他不仅仅是起挽救生命的作用(因为，在很多情况下，由于携带的药品和器材极少，他的医疗技术就不那么重要)，而且他还有从精神上鼓励伤病员的任务，要使伤病员感到在他身边有人用全力在减轻他的痛苦，要使伤病员确信这个人会留在他身边，直到把他的病治好或脱离危险为止。","language":"中文","translation":false},{"id":"che-guerrilla-4-47","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":47,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"游击队的医疗机构的组成，在很大程度上取决于它的历史发展阶段。它可以建立三种类型的医疗机构，以适应各种生活方式。","language":"中文","translation":false},{"id":"che-guerrilla-4-48","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":48,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在游击队历史发展中，有一个最初的流动阶段。在这个阶段，如有医生的话，他始终跟随着游击队员。由于他是游击队里的成员，就必须做游击队员应做的一切工作，甚至包括战斗，他肩负着繁重的抢救生命的工作，有些病症经过适当治疗是可以挽救生命的，但因缺乏医疗手段，有时就没有希望完成这个任务。在这一阶段，医生对部队有较大的影响，他对部队精神面貌起着较重要的作用。在游击队这个发展时期，医生充分发挥了真正传教士的作用，他身上背有一只空空的行军包，仿佛带着为伤病员所需的安慰。一片普通的阿司匹林，出自富有同情心的医生的友谊之手，对痛苦的伤病员来说，具有无可估价的意义。因此，在初期骱段，医生应是充满革命理想的人，因为与部队里其他人相比，他对部队的宣传鼓动会产生更大的效力。","language":"中文","translation":false},{"id":"che-guerrilla-4-49","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":49,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"随着游击战争正常的发展，游击队进入了另一个阶段，我们把它称之为“半流动阶段”。在这一阶段，已有了驻营地，至少是游击部队可常去的驻营地；还有完全可信赖的友好人家，在那里可以保藏东西，甚至可以留下伤病员。于是部队定居的倾向越来越明显。到了这个时期，医生的任务已不象初期阶段那么繁重劳累，他的行军包里已有一套急救的外科设备，甚至有更完善的设备，他可在友好人家较安静地进行手术。伤病员可以留给农民照顾，这些农民会热情地护理他们。游击队还可能拥有保藏在适当地方的多种药品，按照当地的情况，把这些药品编好目录，或尽可能地编好目录。在这半流动阶段里，如能建立为敌人绝对进不去的地区，就可以设立医院或医疗站，伤病员可以去那里进行治疗。","language":"中文","translation":false},{"id":"che-guerrilla-4-50","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":50,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"到了第三阶段，当游击队已有了为敌人攻不破的地区的时候，就可以建立一个真正的医疗机构。在其尽可能完善的阶段里，这个医疗机构可有三个不同类型的医疗站。在战斗的前线，应有一个医生，这个医生是战士，是部队里最受爱戴的成员，他也能参加战斗，他不一定要精通医道，我这样说，使因为那时，他首要的工作是安慰和安排伤病员，真正的医疗工作要到后方医院去做。应让一个称职的外科医生牺牲在火线上。","language":"中文","translation":false},{"id":"che-guerrilla-4-51","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":51,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"既然游击队有了医疗机构，当一个战士在第一线上倒下时，就应该有担架队把他送到第一医疗站。如果没有担架队，他的战友们应担负起这项任务。在不平坦的地区转运伤员，是一项极其困难的工作，也是一个战士可能经历的最不幸的、最难对付的事情之一。转运伤员也许比任何严重的伤势更沉痛，因为伤员的惨状会引起战士们精神上更难受的痛苦，同时也会影响部队战土的自我牺牲精神。根据地形的特点，转运伤员可采用多种方式。但是，在那些适合于游击战争的不平坦的森林地区，由于道路狭窄，人只能一个跟一个通过，在这种情况下，转运伤员的办法最好是先把伤员放在吊床内，然后挂在一根长木棍上，由两个人抬着走。","language":"中文","translation":false},{"id":"che-guerrilla-4-52","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":52,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"战士们轮流抬伤员，一前一后地走着，但是抬的人得很快就把这副重担让给另外两位战友，因为肩膀压得难受，体力逐渐消耗，同时还要考虑到他们抬的担子不仅分量相当重，而且还要抬得小心。","language":"中文","translation":false},{"id":"che-guerrilla-4-53","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":53,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"伤员经过第一医疗站以后，到达第二医疗站，伤情报告亦随之转来。在第二医疗站就部队可能范围之内设有外科医生和专家，可为伤员进行一切必要的和较大的手术来抢救或维持伤员的生命。这就是第二医疗站。此后，转到第三医疗站，那里有设备条件较好的医院，可以对危害当地居民的疾病产生的原因及其后果进行直接调查。第三医疗站的医院，与定居生活相适应，它们不仅是休养的地方和进行不十分紧迫的手术的场所，而且是联系当地老百姓和指导他们卫生工作的机构。还应建立诊疗所，使每人都能得到适当检查和治疗。第三医疗站的医院，按照民政组织的供应能力，可有一系列方便的工作条件，包括能进行化验诊断和X光透视。","language":"中文","translation":false},{"id":"che-guerrilla-4-54","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":54,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"其他有用的人员是医生的助理员，一般说来，这些助理员是具有一定本领、一定文化知识、身体强壮的青年人。他们不拿武器，一部分是因为他们是医务人员，大部分是因为没有足够数量的武器分配给所有想拿起武器的人。这些助理员的任务是负责携带大部分药品、若干担架或吊床，这些都必须按照具体情况而定。一旦发生战斗，他们还须护理伤员。","language":"中文","translation":false},{"id":"che-guerrilla-4-55","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":55,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"一些必要的药品应该通过同敌后卫生组织的联系获得。虽然在某些情况下，也可从国际红十字会那里得到，但是不应该依赖这种可能性；在游击战争的最初阶段更不要去指望这种可能性。游击队应组织一个机构，保证在危险时刻迅速地把必要的药品运来并逐步把它供给急需药品的各个医院(无论军医院或民众医院)，保证其医疗工作的进行。此外，还应同附近地方上的医务人员取得联系，他们能替某些伤员进行手术，因为这些手术是超出游击队医务人员的能力和设备的范围的。","language":"中文","translation":false},{"id":"che-guerrilla-4-56","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":56,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"游击战争需要具有不同特点的医务工作者。第一阶段所需的是医生兼战斗员，也就是部队中的一员，随着游击队活动的复杂化和它的一系列附属机关的设立，这个医生兼战斗员的职能就逐步完成。对游击队来说，有普通的外科医生已是很理想的事了。要是有一个麻醉师那就更好了。尽管现在几乎所有的手术都使用以“氯普吗嗉”和硫喷妥钠这两种药为主的吸入麻醉剂；这种麻醉剂使用方便，又容易获得和保存。除了普通外科医生外矫形科医生是很有用的，因为一些人由于事故骨折，也有些人经常由于子弹打中了四肢而骨折。诊疗所也有医治农民群众疾病的任务。因为一般说来，游击队员的病症很容易诊断，随便哪一个医生就能办到，而最困难的是诊断由于缺乏营养而引起的疾病。","language":"中文","translation":false},{"id":"che-guerrilla-4-57","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":57,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在游击队大为发展的阶段里，如果有良好的医院，应有化验员，以便进行系统全面的工作。应向游击队所需要的各种医务人员发出号召，他们很容易响应这种号召，来提供帮助。需要各种专业医务人员，外科医生是十分有用的，牙科医生也同样如此。应号召牙科医生，要他们带一些乡村用的简易器械和一部乡村用的旋床来参加游击队，有了这些东西，他们便能工作和进行其他一切必要的修理。","language":"中文","translation":false},{"id":"che-guerrilla-4-58","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":58,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"破坏工作是进行游击战争的人民所使用的一种非常宝贵的手段。负责破坏工作的组织应直接属于民政部门或秘密工作部门，因为破坏工作只能在革命军队控制的区域以外进行，这是理所当然的。但这个组织应受游击队参谋部的直接指挥和领导，参谋都负责决定重点破坏哪些工业，哪些交通线。哪些目标等。","language":"中文","translation":false},{"id":"che-guerrilla-4-59","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":59,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"破坏工作完全不同于恐怖主义。恐怖主义和暗杀也是完全不相同的。我们坦率地认为，恐怖主义是一种消极的手段，它决不会产生预期的结果，反而会把人们推到一定的革命运动的对立面，并使行动者的生命损失大大超过所获得的利益。相反，暗杀是正当得行动，尽管也只能在经过慎重选择的特定情况下进行。例如，在需要消灭一个反动头子的时候就必须这样干。游击队不能也不应该做的事，是让一个经过专门训练的，坚强勇敢的战士去暗杀一个微不足道的凶手；后者的被杀可能引起敌人的报复，对参与这件事的全部革命分子和其他人员大肆屠杀。","language":"中文","translation":false},{"id":"che-guerrilla-4-60","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":60,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"破坏工作可以分为两类：一类是在全国范围内就一定的目标进行破坏，另一类是在战线附近进行破坏。全国性的破坏工作基本上应该是破坏交通线。每一种交通线都可采用不同的方式来破坏，各种类型交通线都是可以破坏的。例如，电线杆就很容易被毁坏掉，在夜间，把它们几乎全部锯断，仍看不出有倒下来的危险。只要把一根电线杆踢倒，其他所有被锯过的电线杆马上都被拖倒，大片地区的灯就熄灭了。","language":"中文","translation":false},{"id":"che-guerrilla-4-61","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":61,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"也可以袭击桥梁，把它们炸毁。至于铁桥，如果没有炸药，可用氢氧吹管使之完全倒塌。一座钢铁建造的吊桥，可割断其大梁和支撑桥架的上梁。一旦用氢氧吹管割断了这两根大梁后，就走到它另一端，把它相应部分也割断，这样，这座铁桥就完全向一边倾倒、扭歪而被破坏了。这是在没有火药的情况下破坏铁桥最有效的方法。根据游击队的实力，也应该破坏铁路、道路和小桥，有时还要炸毁列车。","language":"中文","translation":false},{"id":"che-guerrilla-4-62","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":62,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在关键时刻，每个地区的重要工厂也要破坏，为此需要用小分队。在这种糟况下，对问题要有全局观念，要确实符合这样一个原则，即不是决定性时刻，决不能破坏工人劳动场所，否则就会造成大批工人失业和挨饿的后果。反动政府的代理人的工厂一定要破坏(在这样做的时候，要向工人说明这个破坏工作的必要性)，如果这一破坏行动所产生的社会后果非常严重，那么就另作别论。","language":"中文","translation":false},{"id":"che-guerrilla-4-63","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":63,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"我们坚持必须破坏交通要道的原则。敌军在较平坦的地区内对付起义军的强大武器，就是快速交通。所以我们必须不断地去毁坏这个武器，切断铁路的桥梁、排水管系统、电灯、电话线和自来水总管。总之，要破坏一切为现代正常生活所必需的东西。","language":"中文","translation":false},{"id":"che-guerrilla-4-64","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":64,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在战线的附近地区内，破坏工作也应照此办理，但要更大胆，更精心，更经常。为此，要依靠得力的助手，如游击队的快速巡逻队，他们能进入这些地带，协助民政组织的成员完成这项任务。在这里，破坏交通的工作也得放在优先的地位，还要经常不断地进行。此外，要毁掉所有能为敌军供给必需品的工厂和生产场所，因为敌军就是靠这些必需品来维持它对人民军队的进攻活动的。","language":"中文","translation":false},{"id":"che-guerrilla-4-65","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":65,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"要坚持夺取敌人的商品物资，尽可能切断敌人的给养线。如有必要，要恐吓那些企图把农畜产品出售给敌军的大地主；要烧毁通过公路的车辆，并用这些车辆封锁公路；在每次破坏活动中，游击小队要与某些交叉路口保持一定的距离，因为这些交叉路口与敌军经常有联系，一定要遵守“打了就跑”的原则。在那里，不必进行认真的抵抗，只要向敌人表明：在进行破坏活动的地方，有游击队的武装力量，他们准备战斗，并迫使敌人带上大量部队小心翼翼地进去，或者不去。","language":"中文","translation":false},{"id":"che-guerrilla-4-66","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":66,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"这样，靠近游击区一带得所有城市就会逐渐陷入瘫痪状态。","language":"中文","translation":false},{"id":"che-guerrilla-4-67","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":67,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"从游击部队全局来看，战争工业是长期发展过程的产物。还应当指出，这种工业要在有利于游击战争的地理区域之内。在游击队已有几块解放区而敌军又对解放区的给养进行严密封锁的时候，就应该组织各种必要的部门，这一点我们已经谈过。关于工业部门，应有两种基本工业，制鞋工场，制革工场就是其中之一。在森杯地区，在崎岖不平乱石成堆、荆棘丛生的地方，部队没有鞋子就不能行走。在这种条件下行军是很困难的，只有那里的部分本地人才能赤脚走路，其他人走路都必须穿鞋。制鞋工场分为两部分：一部分是修补损坏的鞋子，另一部分是制作粗糙的鞋子。应有制鞋工场的一整套小工具。在这些地区，这样的工具是很容易搞到的，从而就可建立有许多人参加劳动的手工工业。制革工场应始终是制鞋工场的附属部分，在制革工场里，可产生部队所需的各种用品，例如用帆布或皮革制的子弹带、背包和其他东西。这些用品，虽然不是非常重要，却为部队生活提供很多方便，也使人感到这个部队是自给自足和自谋福利的。","language":"中文","translation":false},{"id":"che-guerrilla-4-68","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":68,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"为了游击队内部各种小型机构的需要，另一种基本工业就是建造军火。它同样有几种职能：检修损坏的零件、各种枪支和其他一些武器；生产群众发明的一些战斗武器，制造和管理各种地雷。当具备良好的条件时，应添置设备，制造火药。如果军火工场除制造一些武器零件外还能在解放区内制造爆炸物，那么它就可以作出出色的成就。爆炸物是非常重要的，因为适当地使用地雷，就可使敌军公路交通完全陷于瘫痪。","language":"中文","translation":false},{"id":"che-guerrilla-4-69","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":69,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"其他一系列工业，也有它的重要作用。例如，打铁工场和白铁工场。在打铁工场里，制造骡子的装备用具和铁蹄。在白铁工场里，制造各种黄铜用具，重要的用具有饭盆，特别是军用水壶。附属白铁工场的，有一个熔炼车间。熔炼各种软金属，可制造手榴弹，配上特殊的零件，可为部队提供重要武器。还应有一般性修理和建造的技术设备，可进行多种多样的冶炼；在军营里称之为“服务炮台”(Bateria dc servicio)。在这方面，它或多或少地成了服务炮台，负责满足各种需要，而没有官僚主义的气息。","language":"中文","translation":false},{"id":"che-guerrilla-4-70","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":70,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"关于通讯联络工作也应有一个机构负责。这个机构不仅负责对外的宣传工作，如广播电台，而且要负责电话和各种途径的通讯。要依靠必要的民政组织来有效地完成它的使命。切切记住：我们是处在战争时期，我们可能受到敌人攻击，有时候许多人的生命取决于及时的通讯。","language":"中文","translation":false},{"id":"che-guerrilla-4-71","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":71,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"为了满足部队的需要，应有卷烟厂，向经过选择的地区采购烟叶，运到解放区，在那里制造为战士消费的各种烟卷。另一种很重要的工业就是硝皮业。所有这些工场都是简易的，在任何适合于游击战争形势的地方都完全可以兴建。硝皮工场需要一些小型水泥建筑物，尤其需要大量的盐，但是有了熟皮作原料，就给制鞋业提供了极大的方便。盐应在游击区内生产，并大量储存。要生产盐，必须到含盐量很大的地方去晒盐。海水是生产盐的最好来源，还可能有其他来源。无需滤净盐中其他杂志，只要能用就行，虽然一开始盐的味道不好。","language":"中文","translation":false},{"id":"che-guerrilla-4-72","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":72,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"肉类要用风干腌肉的方法保藏起来。这个方法相当简便。在部队处在极端困难的形势下，咸肉可以拯救好多人的生命。肉类可以用盐腌在大木桶里，这样可以保存相当长的时间，可以对付任何外界形势的变化。","language":"中文","translation":false},{"id":"che-guerrilla-4-73","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":73,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"传播革命思想应通过必要的传播方法，尽量深入地进行。宣传工作要有全套设备，要有一个机构专门负责。为了使宣传工作在全国范围内进行，这个机构应该具有两种类型，并且应该完善，也就是说，对外，有全国性的民政组织，对内，有游击部队内部组织。这两种宣传组织的工作是紧密结合在一起的，为了使它们协调起来，应有一个统一的领导组织。","language":"中文","translation":false},{"id":"che-guerrilla-4-74","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":74,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"解放区之外的民政组织所进行的全国性宣传工作应采用发行报纸、散发战报、张贴传单等形式来进行。在比较重要的报纸上，应刊载关于国家的一般情况，向公众报导游击部队确切的情况，报导要始终注意实事求是这一基本原则，从而逐渐达到对人民有利的结果。除了这些一般性刊物以外，对各阶层居民，还应有其他针对性的刊物。农民刊物应对农民阶级报导他们在所有解放区内的农民的消息，报导解放区的农民已尝到了革命甜头的事例。通过这种方式，宣传农民的要求和愿望。工人报纸也应具有同样的特点，所不同的就是这类报纸不一定会有解放区工人阶级进行战斗的消息，因为很可能在最初阶段，在进行游击战争的范围内，还没有工人组织。","language":"中文","translation":false},{"id":"che-guerrilla-4-75","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":75,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"报纸应该阐明革命运动的各种伟大口号，如在适当时机举行总罢工的口号、支援起义军的口号、团结的口号等等。还可以出版有关革命活动的其他报纸，例如阐明古巴岛上在游击队内非直接参战人员的任务，虽然是非战斗员，但他们担负着破坏、扰敌等活动。宣传机构还可以出版一些针对敌方士兵的报纸，宣传他们所不知道的事情。宣传运动现状的战报和传单是非常有用的。","language":"中文","translation":false},{"id":"che-guerrilla-4-76","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":76,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在游击区内所进行的宣传，效果更好。这种宣传是针对游击区本地人的，偏重宣传革命思想，从理论上说明他们所知道的起义的重要性。在游击区里，除了广播电台外，还有农民的报纸，游击部队的中央机关报，各种战报和布告。","language":"中文","translation":false},{"id":"che-guerrilla-4-77","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":77,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"通过电台广播，解释各种问题，讲解防御空袭的方法，告知敌机经过的路线，指示众所熟知的飞机名称。全固性的宣传也要靠前面提到的各种类型的报纸，但要报导为一般读者所感兴趣的一系列事实和战役。这些消息要比别人报导得更加及时，更加确切。关于国际新闻，只限于或几乎只限于评论那些和解放战争直接有关的事件。","language":"中文","translation":false},{"id":"che-guerrilla-4-78","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":78,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"最有效的宣传方式是电台广播。不管什么情况，它能较自由地对全国进行宣传，触及人们的心灵，打动他们的感情。电台是一种非常重要的宣传工具。当战斗的激情或多或少触动着一个地区或一个国家每一个人的心弦的时刻，电台广播的热情奔放的鼓动性言词，就会提高这种战斗的激情，并把这种激情感染给未来的战斗者。电台对人们进行宣讲、教导和鼓励，使他们确定今后对朋友和敌人所采取的立场。但是电台宣传应遵循人民的宣传这一基本原则，即宣传要真实。说老实话，即使只说了几句老实话，也要比说得天花乱坠的大量谎话要好得多。电台要首先广播关于战斗、交锋、敌人杀害我方人员等真实动人的消息，此外，对老百姓还要作理论上的指导，切实的教育；有时还可以广播革命领导人的讲话。","language":"中文","translation":false},{"id":"che-guerrilla-4-79","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":79,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"革命运动的主要报纸要以国内一个英雄式的人物的名字来命名，从而使人们回想起某种伟大的统一的事业。我们认为这样做是很有用的。在报纸的社论中，必须经常说明这个武装革命运动的趋向，逐步使大家认识全国的重大问题。报纸还应开辟一些量能使读者感到兴趣的专栏。","language":"中文","translation":false},{"id":"che-guerrilla-4-80","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":80,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"“知彼知己，百战不殆”，这句中国格言对于游击战争犹如圣经上的赞美诗一样有用。再没有什么能比正确的情报给予游击部队更大的帮助了。情报有当地居民自动提供的，他们把这里或那里发生的情况报告给他们的友好部队，他们的同盟者，但这种情报还应该经过仔细整理。如前面已经谈到过的，应该设立邮局，驿站等，设立这些机构，在游击区内是为了必要的联系；在游击区外是为了取得货物。但是情报基本上必须与敌军战线直接接触得来，男女情报人员应打进那里去，尤其是妇女，要经常与敌方士兵接触，慢慢地大打听可以打听到的消息。还必须建立联络制度，使情报人员穿过敌人封锁线进入游击区时能畅通无阻。","language":"中文","translation":false},{"id":"che-guerrilla-4-81","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":81,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"如果情报工作做得好，又有精明能干的情报人员，那么在起义军驻营地里就能比较安心地睡觉了。","language":"中文","translation":false},{"id":"che-guerrilla-4-82","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":82,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"我已说过，情报工作，作为游击队的基本战线应包括敌军的第一火线或者与“无人地带”最接近的敌人军营。但是随着游击队不断的发展，情报工作也应逐步发展，逐步增长它的能力，以便能侦察到敌军在其后方所进行的更大规模的更广泛的调动情况。在游击队已控制或已去过的地方，那里的居民都是游击队的情报人员。但是为了搞到情报最好有自己专门的情报人员，因为不能完全相信农民的话，他们话里有夸大的成分，而且他们也不大习惯准确地使用战争术语。如果把群众协助提供情报的各种自发形式加以组织或指导，情报机构不仅可成为游击部队非常重要的助手，而且可成为反攻的支柱，例如派出“制造恐惧气氛”的人员，把气馁沮丧的消息传到敌方士兵中间去，乔装成他们的人，在敌人部队中间制造不安定的和恐惧的气氛。在这里，灵活机动性这一基本战术能发挥到最高限度。当我们确切地知道了敌人队伍的进攻方向之后，我们就能很容易避开敌军锐气，或者在出其不意的地方对敌军进行突然袭击。","language":"中文","translation":false},{"id":"che-guerrilla-4-83","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":83,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"解放战士的训练基本上就是游击队本身的生活；没有一个游击队领导人不是从每天使用各种武器中学会了他的困难工作。一个游击队员能和一些战友生活在一起，他们教他使用各种武器、辨认方向，教他如何对待老百姓、如何打仗等等；但是游击队宝贵的时间不应用在或消耗在系统的教育训练上。只有在有了广大的解放区之后，在需要大量人员来执行战斗任务时才能进行系统的教育训练，因而设立新兵训练学校。","language":"中文","translation":false},{"id":"che-guerrilla-4-84","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":84,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"新兵训练学校在这个时候执行着一项极为重要的任务，即训练新兵。新兵是没有经过大熔炉——游击队极端艰苦的战斗生活考验的。起初，艰苦的生活使这些新兵成为真正精干的战士；在经过多次极其困难的考验之后，他们才能加入这支神出鬼没的“叫化子部队”。体力方面的训练基本上有两种：一种是训练适应小队出击的敏捷动作，敏捷的进攻和退却，另一种是训练急行军，不顾疲劳，使新兵逐步锻炼出过硬本领，以适应这种生活。特别要习惯过露天生活，要经受大自然各种恶劣气候的袭击，就象在游击战争所遇到的那样。","language":"中文","translation":false},{"id":"che-guerrilla-4-85","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":85,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"新兵训练学校应配备负责自给的工作人员。为此，要有饲养场、农场、菜园、畜牧场，以及所需要的一切，为的是不加重游击队的总开支。学员可轮流担负给养工作，也可以把那些表现不好的人派去作为惩罚，或者干脆把自愿去的人派去种菜养牛马。","language":"中文","translation":false},{"id":"che-guerrilla-4-86","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":86,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"这种惩罚方式要依据训练学校所在地的具体情况而定。我们认为把自愿者派到那里去，并以行为恶劣或学习打仗态度不端正的人来补足必要的劳动力，这个原则很好。","language":"中文","translation":false},{"id":"che-guerrilla-4-87","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":87,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"训练学校应有一个小卫生室，根据可能，配上一个医生或男卫生员，尽一切可能照顾好新兵。","language":"中文","translation":false},{"id":"che-guerrilla-4-88","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":88,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"射击是新兵的基本学习项目。在这一点上，游击队员应受到很好的培养和训练，要尽一切可能来减少弹药的浪费。可以从“射击预习”开始训练。象在附图里所看到的那样，把来福枪放稳在木架子上，新兵拿稳枪，瞄准好在一定距离上的目标。目标设在射击场的底端，可以左右移动。如果三次射击都打中在同一点上，那就是优秀的。只要有一点点可能，就可以开始用口径二十二毫米的小来福枪进行射击练习，在这种场合，小来福枪是很有用的。在特殊的情况下，有多余的弹药或迫切需要训练战士，可以给他们实弹射击的机会。","language":"中文","translation":false},{"id":"che-guerrilla-4-89","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":89,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"新兵训练学校最重要的训练课目之一就是防空。我们把它当作基本课目，在世界其他地方这样的课目可能有，也可能没有。敌机从上空完全可以看清我们的训练学校，所以每天总有一两次对学校进行轰炸。学员们对付这种不断轰炸的方式实际上就奠定了这些年青人可成为战争中良好战士的基础。","language":"中文","translation":false},{"id":"che-guerrilla-4-90","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":90,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"新兵训练的一个重要组成部分，也是决不可忽视的部分，就是思想教育。思想教育之所以重要，是因为来参加游击队的人们对于他们为什么要来参加游击队这一点，没有明确的观念，而对自由、新闻自由等只有一种完全模糊的观念，根本没有任何理性的认识。因此，要用较多的时间，较为细心地进行思想教育。在思想教育的过程中，要给予他们本国历史的基础知识，讲清引起每次历史事件的经济原因和其他事实；还要给他们讲解民族英雄及其反抗某种不合理制度的方式。然后，还要对全国形势和地方形势进行分析，编成简明小册子，以供起义军战斗员很好学习，为以后事态的发展描绘一个轮廓。","language":"中文","translation":false},{"id":"che-guerrilla-4-91","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":91,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"此外，要有一所教员训练所，在那里可商定所选的课本，交流每个教员在教学方面所能提供的经验。","language":"中文","translation":false},{"id":"che-guerrilla-4-92","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":92,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"要时时刻刻提倡读书，努力选择好书籍，使大家不至于把时间浪费在毫无意义的事情上，要逐渐协助新兵接触文化，关心国家大事。学员内心逐步产生的求知欲望或令人不安的周围客观形势的逼迫，都能推动学员们由浅入深地去阅读书刊。经过努力，会逐渐达到这种地步。新兵训练学校通过它的日常工作将会逐步证实：凡经过它训练的人员，他们分析问题的能力和遵守严格纪律的程度都会大大胜过部队其他人员。纪律教育也是新兵训练学校基本教育课目之一。","language":"中文","translation":false},{"id":"che-guerrilla-4-93","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":93,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"内部的纪律应完全采取以理服人的办法，而决不能机械地执行。这样，在战斗时刻，纪律就会产生巨大的效果。","language":"中文","translation":false},{"id":"che-guerrilla-4-94","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":94,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"我们已经看到，游击队形式的革命军队，无论在什么地区作战，都必须拥有一个非武装组织来提供一系列极其重要的支援以完成它的使命。那时我们就会看到整个非武装组织都向军队集中，来向它所提供最大限度的援助。因为很清楚，武装斗争是赢得胜利的主要因素。","language":"中文","translation":false},{"id":"che-guerrilla-4-95","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":95,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"军事组织应建立在有一个首长的基础上，就古巴的经验来说，是建立在司令部的基础上。总司令任命各地或各区的司令员，而这些司令员有权管辖他活动的地区，任命纵队司令员以及下级军官。","language":"中文","translation":false},{"id":"che-guerrilla-4-96","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":96,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"总司令下面设区司令员。也就是说，一个区司令员统率若干纵队，各纵队司令员都归他指挥，其编制大小按具体情况而定。区司令员以下，有纵队司令员，小队长和班长。在古巴游击队的组织中，班长是最低一级军官，这就是说士兵提升起来便是班长。","language":"中文","translation":false},{"id":"che-guerrilla-4-97","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":97,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"上面所说的，并不是典范，而是实际情况的写照，只是说明这个武装组织在一个国家是怎样活动的，是怎样战胜了一支组织装备相当良好的反动军队的。这决不是典范，我们这次所说的比在其他场合说的更少典范。这里只是说明古巴革命是怎样逐步发生，发展起来的，一支武装力量是怎样组织起来的。总之，军衔本身并不那么重要，具有重要意义的是：决不要把军衔授予与实际战斗能力不相称的人，决不要把军衔授予违法乱纪的人以及没有经过生死考验和战斗考验的人。","language":"中文","translation":false},{"id":"che-guerrilla-4-98","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":98,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"我们在上面所讲的是一支已经进行严肃战斗的重要军队的情况，而不是游击队的初期形象。在初期，游击队的领导人要什么军衔都行，事实上他指挥的只不过是一个小组的人数而已。","language":"中文","translation":false},{"id":"che-guerrilla-4-99","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":99,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"军事组织的全部措施中，最重要的措施之一就是纪律处分。纪律应是游击队的活动基础之一(这一点必须反复强调)。我们前面已指出，纪律应是从内心的信仰中所产生的力量，是完全有道理作为依据的力量，由此涌现出自觉遵守纪律的人。谁破坏纪律，谁就一定要受到处分，不管他是什么级别的人，都要给予严厉处分，并且这种处分一定要使他感到痛苦。","language":"中文","translation":false},{"id":"che-guerrilla-4-100","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":100,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"这样做很重要，因为一个游击队员的痛苦与兵营内的一个战士的痛苦是不一样的。在游击队里，把违反纪律的战士禁闭十天，对他来说是一次非常好的休息。在十天时间内，他要做的唯一事情就是吃饭，他无需行军，无需做工，无需站岗，要睡就睡，休息休息、看看书报等等。由此可见，把剥夺自由作为处分的办法，在游击队里是不适宜的。","language":"中文","translation":false},{"id":"che-guerrilla-4-101","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":101,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"有这样的情况：违反纪律的人战斗情绪很高，他的自尊心也相当大，剥夺他携带枪枝的权利，倒能起积极作用，对违反纪律的人是一种真正的处分。遇到这种情况，执行这样的处分是合适的。","language":"中文","translation":false},{"id":"che-guerrilla-4-102","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":102,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"下面一件令人伤心的事件可资证明：那是在进攻拉斯维利亚斯省的一座城市的时候，在战斗的最后几天中，我们碰到一位战士睡在沙发上，当时别人正在攻打城中几个阵地。这位违反纪律的战士受到质问时说，他睡在那里是因为他的武器被收走了。于是我们就告诉他，他不应采取这样的态度，他受处分是因为他不小心，枪走了火；并告诉他想要取回他的武器，只有到战斗第一线去。","language":"中文","translation":false},{"id":"che-guerrilla-4-103","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":103,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"过了几天，我们对圣克拉腊城发动了最后一次攻击，当战斗打响的时候，我们正在访问野战医院。有一位：临死的伤员向我们伸出了手，并向我提起上面所讲的那件事，并且肯定地说，他已经能够重新得到他的武器，并获得了携带武器的权利。说完，他就死去。","language":"中文","translation":false},{"id":"che-guerrilla-4-104","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":104,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"这就是我们军队在连续不断的武装斗争所达到的革命精神的高度。这种精神在战斗初期是不会有的，因为那时仍有许多害怕心理。许多阻碍革命影响的主观思潮。但是，通过工作，通过榜样的不断的启发，终于获得了这种革命精神。","language":"中文","translation":false},{"id":"che-guerrilla-4-105","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":105,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"处分也可采用通宵站岗和强行军的办法。但强行军有严重的缺点，没有实际效果，它只是为了单纯的处分，这不仅使违反纪律的人精疲力竭，而且使看守他的战士也疲劳不堪。通宵站岗也有不方便的地方，因为这种办法也得派人看守受处分的人——缺乏革命思想的士兵。","language":"中文","translation":false},{"id":"che-guerrilla-4-106","author":"切·格瓦拉","title":"游击战","location":"第三章 游击阵线的组织","page":4,"paragraph":106,"url":"https://www.marxists.org/chinese/guevara/1960/03.htm","text":"在我直接指挥的部队里，对违反纪律的人均采用禁闭。对违反纪律较轻者不给可口的食物或香烟；对违反纪律较重者，在一定时间内不给饭吃。这种处分办法虽然可怕，但效果良好，不过只在很特殊的情况下才使用。","language":"中文","translation":false},{"id":"che-guerrilla-5-1","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":1,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"中文马克思主义文库 -> 切·格瓦拉 -> 《游击战》（1960）","language":"中文","translation":false},{"id":"che-guerrilla-5-2","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":2,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"一、游击队初期的秘密组织","language":"中文","translation":false},{"id":"che-guerrilla-5-3","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":3,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"三、分析古巴现在和未来的形势","language":"中文","translation":false},{"id":"che-guerrilla-5-4","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":4,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"一、游击队初期的秘密组织","language":"中文","translation":false},{"id":"che-guerrilla-5-5","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":5,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"游击战争遵循从一般战争中得来的一系列规律和它本身所特有的规律。但是，如果真正想从另外一个国家或从本国边远地区打响一场游击战争的话，很明显，就必须从秘密工作开始。这项秘密工作是由少数创始人来进行的，而且与人民的行动无联系。如果游击运动是通过一批人反抗任何压迫的自发行动而诞生的，那么很可能只需要进一步组织这支游击队的领导核心，以防它被消灭。但是，一般说来，游击战争是经过思想准备而开始的，是由某个有威信的领导人物为了拯救他的人民而发动起来的。这位领导人物起初应在某一外国、在艰难的条件下进行工作。","language":"中文","translation":false},{"id":"che-guerrilla-5-6","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":6,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"最近一个时期，几乎所有旨在反独裁的人民运动，都有准备不足这个根本缺点。就我们上面所谈的情况而言，一般都没有遵循秘密活动的规则，这些规则要求工作极端机密和小心谨慎。最常见的情况是：本国反动政府对地下小组或若干地下小组的种种打算，早有所闻。反动政府得到这些情报是通过它的特务机关、利用地下小组本身轻率的暴露或在某些情况下利用地下小组的直接宣布。例如我们搞的登陆活动是由菲德尔·卡斯特罗用下面这句话来宣布的：“1956年我们要做自由人，否则就成为殉难者。”","language":"中文","translation":false},{"id":"che-guerrilla-5-7","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":7,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"这就是说，游击运动的建立的基础，第一必须是绝对的秘密，使敌人完全得不到情报。第二必须挑选人员，这一点也很重要。挑选人员，有时很容易办到，有时很难办到，因此必须依靠容易找到的流亡国外多年的人员。他们有的一听到号召就自动来报到，有的只是懂得一点参加解放祖国斗争是他们的义务等等，然而缺乏对每个人进行全面审查所必需的依据。虽然如此，即使可能有敌方分子打进来，由于上述可能会泄漏机密的人员是不能宽恕的。因此在开始游击活动之前，凡参加游击活动的人都应集中在只有一两人知道的秘密地点，由他们的头头严密监视，使他们不得和周围有任何接触。在必须去进行预定的训练，或者只是为了避开警察，而把人员集中起来准备出发的时候，一定要始终使一切新参加的来历不十分清楚的人远离这些机密要地。","language":"中文","translation":false},{"id":"che-guerrilla-5-8","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":8,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"处在地下活动的情况下，除了非知道不可的事情，其余事情谁都不应该知道，也决不在任何人面前谈论。在上述人员集中以后，必须控制来往信件，从而完全掌握每个人员与外界接触的情况。不允许任何人单独生活，甚至不允许单独外出，应该采取一切措施避免未来的解放军战士与外界有任何性质的个人接触。这里，应该着重指出妇女这一因素，在战斗中，妇女起积极作用，而在这种情况下则往往起消极作用。大家知道，青年男子，在远离他们习惯了的生活环境时，即使处在特姝精神状态之下他们也有追逐女人的弱点。而独裁者是很了解青年人的这个弱点的，因此，他们妄图把女特务打到我们队伍中来。有时候，这些女人和她们上司的两性关系是明显的，几乎是不知羞耻的；有时候，这种两性关系是极难发觉的。因此必须阻止游击队员与女人的联系。","language":"中文","translation":false},{"id":"che-guerrilla-5-9","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":9,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"处于秘密状态准备战斗的革命者，应是一个完全的禁欲主义者。与遵守纪律一样，这一点也用来检验一个革命者的一种品质，这种品质是将来当领导的根据。如果有人屡次无视上级的命令而和女人接触，发生不准许的朋友关系等，应立即把他调离开。理由很简单，他破坏了革命纪律，这里且不说他这种接触的潜在危险。","language":"中文","translation":false},{"id":"che-guerrilla-5-10","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":10,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"决不应该把某个政府(或对游击队友好的，或对游击队掉以轻心的)无条件的援助当作在其国土上活动的基础；而是应该经常认真对待形势，就象是在完全敌对的地区一样。当然，在这方面也可能会有一些例外，但是这些例外恰恰证实了一般的规则。","language":"中文","translation":false},{"id":"che-guerrilla-5-11","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":11,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"这里，无法确定要多少人才能进行游击战争。这要取决于具体情况，而具体情况是这样的复杂和多变，要确定一个固定的人数实际上是不可能的。这里只能谈谈游击战争开始时所需要的最低限度的人数。考虑到虽然经过极严格挑选，但自然还会有开小差的和体质差的人，我认为一支基本队伍拥有的人数应是三十人到五十人。不管美洲哪一个国家，只要有有利于作战的地形、有严重的土地问题、有怨声载道的民情等等，上述这个人数就足以在那里发动一场武装斗争。","language":"中文","translation":false},{"id":"che-guerrilla-5-12","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":12,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"游击队使用的武器，应是敌人所使用的同一类型的武器，这一点已经说过。由于在原则上总是认为所有政府对于在其领土内发起的游击行动都是抱敌对态度的，每支核心队伍大体上不应超过五十人到一百人。我们并不反对五百人开始游击战争，但是这五百人决不应该集中在一起。首先是因为人数众多，容易引人注目，其次，如果有什么背叛、干扰、泄密之类事情发生，就会全军覆没；何况要同时占领几个地方也是比较困难的。","language":"中文","translation":false},{"id":"che-guerrilla-5-13","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":13,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"游击队的中心会址大体上能让大家都知道，流亡国外而已参加游击队的人可到那里举行各种会议。但游击队长们只能个别地分散去出席会议，在那里不要留下会招来麻烦的文件。队长们开会和居住的地方要尽可能多一些，而且要更隐蔽。储藏武器的仓库，应该绝对保密，只许一两个人知道；如有可能，武器仓库应分散在几个地方。","language":"中文","translation":false},{"id":"che-guerrilla-5-14","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":14,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"枪枝弹药应该只在游击行动开始之前发到那些即将使用它的游击队员的手里。这样在游击队员受训练的时候，即使有敌军的围剿，也可避免人员被捕、枪枝损失的情况，因为这些枪枝极难搞到；其费用，人民军队是无力支付的。","language":"中文","translation":false},{"id":"che-guerrilla-5-15","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":15,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"另一个必需重视的因素，就是要训练游击队准备进行极为艰苦的战斗。游击队应有严格的纪律、高昂的土气，完全明确所要执行的任务；不虚张声势，不空想，没有轻易取胜的侥幸心理。战斗将是艰难的，长期的；游击队可能受到挫折，可能处于被消灭的边缘。只有它的崇高精神，它的纪律性，它的获得最后胜利的信心以及领袖的特殊的才干，才能战胜一切。这是我们古巴的经验。当初由于在古巴具备了所有这些条件，又有菲德尔·卡斯特罗的领导，我们十二人才能创建了已经组织起来的游击队的核心。","language":"中文","translation":false},{"id":"che-guerrilla-5-16","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":16,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"除了思想上和精神上的准备之外，还必须进行体力上的严格训练。很明显游击队要选择山区或荒野地区来开展活动；在任何情况下，游击队的基本活动就是行军。动作要迅速，要不怕疲劳。所谓有效的训练就是日以继夜，日复一日的艰苦行军，并逐步增加这种行军，要拿出最后一点力气来进行这种行军，而且还要进行速度竞赛。速度和耐力是首批核心游击队员的基本功。此外，要给予他们一系列的理论知识，如辨别方向，查看地图，进行各种破坏活动的方法。如有可能，要进行有关使用枪枝、各种射击的训练，尤其是远距离打靶的训练；使用子弹的各种方式，也要多方予以指导。","language":"中文","translation":false},{"id":"che-guerrilla-5-17","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":17,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"每个游击队员都必须把节省弹药当作几乎是信条来执行，直到使用最后一颗子弹电要如此。如果上述各项都做到了，游击队就能很容易完成它的使命。","language":"中文","translation":false},{"id":"che-guerrilla-5-18","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":18,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"如果没有全面地彻底地摧毁维持旧政权的军队，那么，自然就不会取得决定性的胜利。而且要有步骤地打碎维护旧政权的一切机构。鉴于本书是一本有关游击队的手册，我们只谈在发生战争和敌人侵犯新政权的情况下保卫国家的任务。","language":"中文","translation":false},{"id":"che-guerrilla-5-19","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":19,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"我们所碰到的第一件事情就是所谓世界舆论——美国和其他垄断资本国家的各类“严肃的报刊”、各家“公正的”通讯社——开始攻击我们这个解放了的国家，攻击它蓄谋侵犯别国，攻击它那些符合人民正当要求的法律也是蓄谋的、咄咄逼人的。因此，我们决不许可有旧军队的框框，也不许可旧日军人参加我们的军队。因为他们的军阀主义、机械服从，军人的旧义务观念、旧纪律观念、旧道德观念等，都不是一举就能肃清其影响的。更何况胜利的、有战争经验的、高尚的、善良的但几乎缺少起码的文化基础知识的游击队员是很难同战败的旧军人生活在一起的，因为这些旧军人自以为有军事知识，如他们自以为长与某种作战武器，懂得数学，熟悉设防工程、后勤业务等等，而对无文化的游击队员十分仇视。","language":"中文","translation":false},{"id":"che-guerrilla-5-20","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":20,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"当然，在这些军人中间，会有少数例外，他们与过去的一切旧东西完全决裂，怀着绝对合作的精神参加了新军队。若是这样，这些人就加倍有用，因为他们热爱人民的事业，就能运用他们的专门知识，促进新的人民军队的建设。一事物应为另一事物所代替，这就是说，旧军队被粉碎了，旧军事机构被瓦解了，新的军队，新的军事机构应立即取而代之。值得指出，游击队的原来的组织结构，它的分散的、带有某种考迪罗主义［注：音译，意为首领，引伸为独裁者。拉丁美洲一些国家的军人以暴力攫取政权的独裁统治被称为考迪罗主义。——译者］倾向的、毫无计划的情况是可以改变的。但有一点要特别强调指出，这种改变必须从游击队的军事行动观念出发，给人民军队以有组织的形式，这就是说，要根据游击部队的要求，给人民军队建立一套合适的体制。不应该重犯我们在最初几个月中所犯过的错误，就是企图把原来组织的这一套军纪和组织形式硬加给新的人民军队身上。这可能会引起极大的混乱，导致无组织状态。","language":"中文","translation":false},{"id":"che-guerrilla-5-21","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":21,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"在目前，应该为人民军队必须开展的新的保卫战开始作准备。这支人民军队已习惯于在统一准则下的独立指挥，能很灵活地调用下属各部队。现在这支军队立即会碰到两个问题，一个问题是，在胜利的高潮中，最终很可能会有成千上万的革命者加入革命队伍，其中好的坏的都会有，为此，必须对他们进行严格的游击队生活的锻炼，抓紧进行革命思想教育。革命思想教育是统一人民军队思想的需要，是现在和将来国家安全的基础。另一个问题是适应新组织形式时所遇到的困难。","language":"中文","translation":false},{"id":"che-guerrilla-5-22","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":22,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"必须立即设立一个机构，负责把革命新道理传描到整个部队中去。向来自人民中间的士兵、农民、工人宣传革命事业的正义性和真理性，解释有哪些革命目标，为什么要进行革命斗争，为什么许多同志未能看到胜利而牺牲了。结合这种强有力的革命思想教育，也要加强初级文化教育，可以先从扫盲着手，然后逐步把革命军队改造成为具有高度技术基础、可靠思想方法和强大战斗力的队伍。","language":"中文","translation":false},{"id":"che-guerrilla-5-23","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":23,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"培养这三种品质，需要有一个过程。在这以后，军事机构就可以逐步完善，使老战士，经过专门训练班，成为职业军人，他们每年对人民进行军事训练，所采用的方法或是义务兵役制，或是志愿兵役制。这取决于每一国家的具体情况，不能强求一律。","language":"中文","translation":false},{"id":"che-guerrilla-5-24","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":24,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"1959年底和1960年初，古巴遇到了当今世界外国侵略的威胁，对于这个明显的敌人，古巴作了分析、估计，并无畏地等待着它。面对这样具体的事实，下面就谈谈起义军领导对于在古巴情况下要采取的政策的看法。这就是说，这并不是把我们已做的事变为理论条条，以便让大家知道，而是总结别人已做的事，以便把它应用于我们的国防上。","language":"中文","translation":false},{"id":"che-guerrilla-5-25","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":25,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"因为我们要总结古巴的情况，对美洲的现实情况提出我们的设想以及促使它向前发展，所以我们把下面的分析作为结束语。","language":"中文","translation":false},{"id":"che-guerrilla-5-26","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":26,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"三、分析古巴现在和未来的形势","language":"中文","translation":false},{"id":"che-guerrilla-5-27","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":27,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"从古巴独裁者逃亡之后，已过去一年多了；他的逃亡是古巴人民进行长期武装斗争和非武装斗争的必然结果。革命政府在社会、经济、政治领域内所取得的成就是巨大的，然而还必须进行恰如其分的分析，并且还必须向人民讲明我们古巴革命的确切规模。这是因为我国革命基本上是土地革命，但是由于工人、中间阶级人士的热烈参加，目前还有工商业人士的支持，这个革命在美洲大陆，甚至在世界上都有重大意义。古巴人民以坚定不移的决心保卫着这个革命，而这个革命的特点又使它更富有生气。","language":"中文","translation":false},{"id":"che-guerrilla-5-28","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":28,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"对于已颁布的一系列无疑是有利于人民的法令，我们不准备进行综合性的哪怕是很扼要的论述。只要对其中几条法令给予必要的强调，同时指明国家如何关心古巴人民的需要，逐步而必要地颁布一系列法令，只要指明这些法令的逻辑联系就足够了。","language":"中文","translation":false},{"id":"che-guerrilla-5-29","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":29,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"对于我国寄生阶级欲望的第一次引人注意的打击，就是迅速地接二连三地颁布了租赁法、电费减价、清查电话公司以及随之降低电话费等法令。有些人曾企图把留有大胡子这个唯一特点的菲德尔·卡斯特罗和进行这次革命的人看作为旧式政客，或看作为容易被操纵的傻瓜。现在这些人开始怀疑，古巴人民内心深处是否已产生更为深刻的东西，他们的特权是否处于被剥夺的危险时刻。他们开始用“共产主义”这个名词攻击革命领导人和胜利的游击队员；结果，按照对立的辩证法的观点，“反共产主义”这个名词开始把所有那些对革命不满的家伙和被剥夺了特权的家伙纠集在一起。","language":"中文","translation":false},{"id":"che-guerrilla-5-30","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":30,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"地产法或分期付款法在重利盘剥的资本家中间逐步引起了不安。但是，这些法令只不过是对反动派所进行的一些小战役；他们想：好吧!一切都是可能的，菲德尔·卡斯特罗“这个疯小子”可能由于杜波依斯(Dubois)或波特(Porter)的规劝而有所转变，会走上“民主”的道路。应该寄希望于未来。","language":"中文","translation":false},{"id":"che-guerrilla-5-31","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":31,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"土地改革法引起了巨大的震动。大部分受到影响的人已看清楚了。反动派的代言人加斯东·巴克罗(Gaston Baquero)比他们更早地看清了这一点，他曾确切地指出将要发生的事变，并隐退到西班牙独裁统治下的最安静的角落里去了。那时，还有人这样想“法令总归是法令”，其他政府也曾颁布过一些理论上对人民有好处的法令；但是执行这些法令却是另一回事了。起初，一些人以长者冷漠或怜悯的态度来看待这个顽皮的、惹人麻烦的孩子——全国土地改革委员金(它的简称INRA是大家所熟悉的)。这些人是站在天赋的社会学和可敬的公众财政理论高度上来看待土地改革委员会的，而无文化的，思想荒谬的游击队员是无法攀登这个高度的。但是，全国土地改革委员会象拖拉机和坦克那样前进。同时它确是拖拉机和坦克，其辙迹所及之处，把一切大庄园的围栅压得粉碎，从而建立了新的土地所有制的社会关系。古巴的土地改革带着一些重要特点出现在美洲大地上。是的，古巴的土地改革是反封建的，在古巴的情况下，它铲除了大庄园制度，废除了种种缴付实物地租的契约，消除了在我国农业生产中，主要是在咖啡、烟草生产中所存在的奴隶制关系。另外，古巴的土地改革也是反资本主义的，它要打破垄断资本对农村的压力；因为由于这种压力，农民无法单独地或集体地在自己土地上辛勤劳动而不必畏惧债主即土地主。古巴的土地改革还有这样的特点：从一开始就向农民和农业工人保证，给他们土地，派专门人员和提供机器设备给他们以必要的技术援助，由全国土地改革委员会或国家代理银行提供信贷给他们以经济援助。此外，“人民商店协会”给他们以巨大的支持；这种“人民商店协会”在奥连特省已有很大的发展，在其他各省正在发展过程中。在那些地方，国营商店已代替了过去的敲竹杠的中间商，买卖公平，价格合理。","language":"中文","translation":false},{"id":"che-guerrilla-5-32","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":32,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"古巴的土地改革与美洲其他三次大的土地改革(即在墨西哥、危地马拉、玻利维亚所进行的土地改革)相比，看来最重要的不同点是：毫不犹豫，毫不妥协，决心把土地改革进行到底。整个古巴的土地改革只尊重人民的权利，而不尊重别的什么人的权利，也不只针对某一阶级或某一国籍的人，因为无论对待美国的联合果品公司或金氏牧场，还是对待本国的大庄园主，都用这个土地改革法来衡量 。","language":"中文","translation":false},{"id":"che-guerrilla-5-33","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":33,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"在这种情况下，古巴极为重要的农产品的生产，如稻米。油料作物和棉花都得到了很大的发展，并已成为生产计划的重点。但是古巴政府并不以此为满足，它要收回一切被掠夺的古巴财富。古巴富饶的地下资源，是垄断资本家争夺的舞台、抢劫的场所。我们用石油法实际上已把它收归国有了。石油法，正如革命政府所颁布的土地改革法和其他各项法令一样，都是符合古巴的正当需要的，也是符合古巴人民刻不容缓的迫切愿望的。古巴人民希望自由，希望成为国家经济的主人，希望繁荣和达到越来越高的社会发展的目标。正因为如此，古巴才成了石油垄断集团所害怕的美洲大陆上的一个榜样。石油垄断集团的这种害怕不是由于古巴直接给他们造成重大的损失，因为没有任何理由要把古巴看成是宝贵的燃料中心，即使它很有希望能满足本国的需要。相反，垄断集团所害怕的则是古巴的法令给美洲的兄弟人民所作出的活生生的榜样。许多美洲兄弟是这些垄断集团掠夺的对象；而另一些兄弟人民则被推向内战，以满足这些托拉斯集团的欲望和需要。同时古巴的榜样也向美洲各国表明这样做的可能性，指出应该考虑这样做的确切时间。大垄断资本集团也忧心忡忡地看着古巴，因为这个加勒比海的小小岛国不仅敢于向福斯特·杜勒斯先生的后继人——联合果品公司清算其巨额资产，而且还打击了洛克菲勒先生的石油帝国。同时使荷英壳牌石油垄断集团也尝到了古巴人民革命给予的滋味。","language":"中文","translation":false},{"id":"che-guerrilla-5-34","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":34,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"一些人企图用武力威胁；用空中袭击，用别的什么制裁办法迫使古巴人民屈服，古巴人民就用土地法、矿业法来回答他们。有人说矿业法和土地法同样重要。一般说，矿业法在我国经济中尚未达到如此重要地位。但是现在出现了另一个新现象：占全部出口产品税百分之二十五应由把我国矿石出售给外国的那些公司缴纳(现在这些公司除了在我国土地上留下一个矿坑之外，还算是留了一些税款)，这笔税收额不仅增加了古巴的财富，而且相对地还增强了加拿大垄断资本家对开发我国镍矿的[美国]资本家的竞争力量。清算了大庄园制的古巴革命，就是这样限制了外国垄断资本家的利润，限制了外国中间商和从事进口贸易的寄生资本家的利润。古巴革命在美洲提出了一项新的政策，同时它也敢于打破矿业巨头的垄断资本的现状，至少使其中一位矿业巨头陷入困难境地。这就意味着再一次强烈地提请最大垄断资本国家的邻居们的注意，而且也在全美洲引起了反响。古巴革命还打破了新闻事业中的一切障碍，使古巴革命的真理非常迅速地传播到渴望美好生活的美洲人民群众之中。古巴是新兴民族的象征，菲德尔·卡斯特罗是解放事业的象征。","language":"中文","translation":false},{"id":"che-guerrilla-5-35","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":35,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"象是一条普通的万有引力定律在起作用那样，古巴这个面积十一万四千平方公里、人口六百五十万的小岛国担负起美洲反殖民主义斗争的领导；由于美洲存在着十分严重的动摇犹豫之状，这就使得古巴站到了英雄的、光荣的和危险的前哨阵地。在殖民地的美洲，那些经济比较发达的国家，那些与外国垄断资本进行连续不断的有时甚至是激烈的无情情斗争而艰难发展本国资本主义的国家，逐步地让位于这个小小的新兴的自由强国，因为这些国家的政府没有足够的力量把反殖民主义的斗争进行到底。这个斗争既不是简单的，没有危险的，也不是没有困难的，它需要全体人民作为后盾，需要高尚的理想和牺牲的精神，才能把这种斗争进行到底。我们在几乎孤立无援的情况下，在美洲进行这种反殖民主义的斗争。过去曾有些小国想站在这个前哨的阵地上。危地马拉，以自由之鸟“格查尔”(关进笼子即死的一种鸟)作为象征的危地马拉、印第安人特库姆·乌曼(Tecum Uman)［注：16世纪印第安基切人的一个国王。在西班牙殖民主义者征服拉丁美洲的时候，他带领基切人奋起反抗，最后被西班牙殖民主义者杀害。——译者］的危地马拉，在殖民主义者直接进攻面前倒下了。玻利维亚、美洲独立运动的前驱莫里略的玻利维亚，在斗争的巨大困难面前屈服了，虽然它在以下三方面所作的事情基本上为古巴革命树立了榜样：废除原有军队，进行土地改革和矿业国有化——矿业是玻利维亚的最大财富资源，也是它的悲剧的最大根源。","language":"中文","translation":false},{"id":"che-guerrilla-5-36","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":36,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"古巴知道这些以前的榜样，了解它们的失败和困难，但也懂得它现在正处于世界新时代的黎明时刻，亚非人民的民族斗争浪潮冲垮了殖民主义的基石。世界人民要团结，这不是由于他们的宗教、风俗、愿望或种族亲疏的原因，而是由于他们的社会经济条件相同，由于他们要求进步和复兴的渴望相同所促成的。亚洲和非洲已在万隆会议上携起手来。现在，亚洲和非洲，通过古巴，即通过哈瓦那，终于和殖民地的印第安美洲携起手来了。","language":"中文","translation":false},{"id":"che-guerrilla-5-37","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":37,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"另一方面，在各国人民斗争面前，殖民主义强国不得不让出它们的地盘。比利时和荷兰已成为描绘殖民帝国的两幅漫画；德意志和意大利丧失了它们的殖民地；法国在一场已失败的殖民战争的痛苦中挣扎；老奸巨猾的善于施展外交手腕的英国放弃了它在殖民地的政治统治而保持了它的经济联系。","language":"中文","translation":false},{"id":"che-guerrilla-5-38","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":38,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"在那些已经开始独立生活的国家中，美国资本主义替代了某些老牌殖民资本主义，但是它知道这是不会长久的，在这些新兴国家里，它的投机金融资本家并没有真正扎下根：他们能象章鱼那样吸吮，但是却不能象章鱼那样使用它的巨大触角把东西紧紧缠住。帝国的鹰爪已被锉平。殖民主义在世界的这些地方已经死亡，或正处在自然死亡的过程中。","language":"中文","translation":false},{"id":"che-guerrilla-5-39","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":39,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"美洲则是另一种情况。英国狮子早已把它贪吃的嘴巴从我们美洲缩了回去；而年轻的、彬彬有礼的美国资本家们，则把英国的俱乐部变成了“民主”的俱乐部，把它的至高无上的统治强加给拉丁美洲二十个共和国的头上。","language":"中文","translation":false},{"id":"che-guerrilla-5-40","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":40,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"这就是美国垄断集团的殖民领地，美国的“后院”，这也是它们现在所以能活着和可能活着的理由。如果拉丁美洲各国人民，象古巴那样，举起庄严的旗帜，垄断资本家就要发抖，不得不屈服于政治经济的新局面，屈服于利润大为减少的新局面。垄断资本家是不喜欢削减他们的利润的。古巴的榜样——国家和国际尊严的“坏榜样”——正在美洲各国广为传播。每当一个被压迫民族发出解放的呼声时，古巴就要挨骂。在一定程度上，古巴是应该挨骂的，因为古巴指明了一条反对所谓不可战胜的军队的人民武装斗争道路，指明了一条消耗并粉碎敌人于他们基地之外的农村斗争道路。总之，指出了一条庄严的道路。","language":"中文","translation":false},{"id":"che-guerrilla-5-41","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":41,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"古巴是个坏榜样，是个很坏的榜样。当这个坏榜样站稳脚跟并不顾危险奋勇向前的时候，垄断资本家就睡不安宁了。他们的代言人叫嚷：必须摧毁古巴！披着议员外衣的垄断资本家的走狗们狂吠：得管管这个“共产主义”桥头堡！托拉斯的最狡猾的辩护士说:“古巴的形势使我们深感不安。”但是，我们知道他们是想说：“必须破坏古巴的形势。”","language":"中文","translation":false},{"id":"che-guerrilla-5-42","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":42,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"那么，要摧毁这个坏榜样，有哪些可能采用的侵略手段呢?其中之一，我们称之为纯经济侵略。美国银行和贷款者对古巴商人、各银行以及古巴国家银行限制贷款。这个办法不但在美国实行，而且还通过它的伙伴使西欧各国也这样做。但是，仅仅这样做还是不够的。","language":"中文","translation":false},{"id":"che-guerrilla-5-43","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":43,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"不给贷款的办法最初严重地影响了古巴的经济。但是古巴马上对经济进行重新调整，使贸易收支达到平衡，使受损害的古巴习惯于按日安排生活。必须继续[给古巴经济]施加压力。古巴的砂糖出口额开始不稳定，经过了上升、下降，再下降、又回升的过程。垄断资本家的各个代办处的计算机迅速地算出各种账目，最后得出结论：减少古巴糖的出口额是非常危险的，取消它更是不可能。为什么非常危险呢?因为这种做法，不仅可能是失策，而且还很容易引起十个至十五个供应砂糖的国家出口更多砂糖的欲望，在它们中间引起极大的不安，因为它们一直认为自己拥有多出口砂糖的权利。为什么取消它更是不可能呢?因为古巴是美国的最大的、最有效的、最廉价的砂糖供应者，又因为直接与古巴砂糖生产和贸易相联系的百分之六十的利润是归美国的。另外，贸易差额一向是有利于美国的，谁不出售，谁就不能买进，而且还可能作出破坏协定的坏榜样。但是问题并不到此为止。美国又以“赠送”的名义，付给每公斤古巴砂糖的价格比世界市场的价格高出三美分左右，这是由于美国不能生产廉价砂糖的结果。高工资和土地生产率低使这个大国不能生产跟古巴糖价一样的砂糖。然而，它们依靠这种用较高价格收购古巴砂糖的办法，把损人利己的协定不仅强加给古巴，而且强加给其他国家。所以不可能取消古巴的砂糖出口额。","language":"中文","translation":false},{"id":"che-guerrilla-5-44","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":44,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"垄断集团会不会把炸毁甘蔗田以减少砂糖生产作为一种变相的经济侵略手段呢?我们没有把这种可能性看得很严重。我们倒认为他们轰炸甘蔗田的目的是为了使人们不相信革命政府的强大(美国雇佣军的碎尸的脏血只不过染污古巴一二间房子而已，如果这也算是一种政策，那么大规模地轰炸起义军又怎么说呢？）。","language":"中文","translation":false},{"id":"che-guerrilla-5-45","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":45,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"古巴经济还有其他一些薄弱环节会受到压力，原料的供应，例如棉花的供应。但是大家知道得很清楚，世界上棉花生产是过剩的，这种困难是暂时的。燃料呢？这是必须引起注意的问题，一个国家没有燃料就会瘫痪，而古巴所产的石油是很少的。古巴有一些煤焦油可利用来烧锅炉，还有一些酒精，在关键时刻，可用来发动车辆。但是世界上出产很多石油，埃及会出售石油，苏联会出售石油，也许不久伊拉克也会出售石油。由此可见，敌人的单纯经济战略是起不了作用的。","language":"中文","translation":false},{"id":"che-guerrilla-5-46","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":46,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"除了这些经济压力之外，美国还有可能利用某个“囊中之强国”，例如多米尼加，进行某些干涉。这种干涉可能引起一点麻烦，但联合国最终会出来干涉，不过不会有什么具体结果。","language":"中文","translation":false},{"id":"che-guerrilla-5-47","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":47,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"美洲国家组织所奉行的新政策，意外地造成了危险的干涉先例。垄断资本家利用特鲁希略［注：特鲁希略（1891-1961年），多米尼加共和国的独裁者。从1930年起美国扶植特鲁希略家族统治多米尼加共和国达三十年。——译者］的陈腐借口，心安理得地建筑他们侵略的桥梁。可悲的是，委内瑞拉的民主使我们处于不得不拒绝对特鲁希略进行干涉的困境。这对于美洲大陆的海盗们是帮了何等的大忙啊！","language":"中文","translation":false},{"id":"che-guerrilla-5-48","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":48,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"在几种新的侵略可能性中，还包括暗杀，从肉体上消灭老“疯小子”——菲德尔·卡斯特罗，他已成了垄断资本家的眼中钉。自然，他们也会采取措施来消灭另外两名危险的“国际特务”劳尔·卡斯特罗和本书作者。这是他们梦寐以求的解决办法，如果能顺利地同时干掉这三位或至少干掉其首脑，这对反动派是很有好处的（但是，垄断资本家先生及其走狗们，不要忘了我们的人民，不要忘了威力无比的人民。人民对于这类罪恶，会感到极端愤怒，一定会给予那些直接或间接参与暗杀各级革命领导人的坏蛋以坚决的镇压。任何情况，任何人都阻止不了人民的行动）。","language":"中文","translation":false},{"id":"che-guerrilla-5-49","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":49,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"可能会有另一个危地马拉事件，这就是对古巴的军火供应施加压力，迫使古巴向共产主义国家购买军火，借此对古巴进行更凶恶的咒骂。可能会产生一些效果，他们可以我们当作“共产主义者”来攻击，但不能把我们当作傻瓜来消灭，我们政府里有人这样说。","language":"中文","translation":false},{"id":"che-guerrilla-5-50","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":50,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"由于垄断集团直接侵略的必要性越来越清楚，国际商业机器公司的计算机将对各种可能性进行计算和研究。目前，我们可能会碰到类似西班牙的事件。所谓类似西班牙的事件就是借用一些流亡分子，在志愿兵的支持下进行入侵；志愿兵自然是某一大国的雇佣兵或干脆就是这个大国的士兵，他们得到海军和空军的大力支援。我们说，他们之所以得到海、空军大力的配合，其目的是为了使入侵成功。也有可能，由一个国家如多米尼加直接侵犯，它派遣一些士兵——我们的兄弟和许多雇佣兵到我们海滩来卖命，以挑起战争，从而使垄断集团的清白无辜的祖国被迫宣布说，它们是不愿意干涉弟兄之间“悲惨的”残杀的；说它们要做的只是要阻止这场不幸的战争，把它限止于目前的范围内。然后，它们用主力舰、巡洋舰、驱逐舰、航空母舰、潜水艇、扫雷艇、鱼雷艇以及飞机，对美洲这一部分的空中和海面进行监视。可能会发生这样的情况：当热衷于美洲大陆和平的卫土们，不准许任何一只船载运任何货物驶向古巴的时候，驶向特鲁希略的不幸国家的一些船只、或许多船只、或全部船只却能“逃过”上述“铁一般”的监视。他们也可能通过某个有点“名气”的美洲组织进行干预，来结束“共产主义”在我们这个岛国上所发动的‘疯狂的战争”。或者，如果这个有点“名气”的美洲组织不起作用，那么他们就会假借它的名义，借口维护和平和保卫美国公民的利益直进行干涉，从而制造另一个朝鲜事件。","language":"中文","translation":false},{"id":"che-guerrilla-5-51","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":51,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"也许侵略的第一步不是针对我们而是针对委内瑞拉共和国的合法政府，以肃清美洲大陆上支持我们的最后一个据点。如果发生这样的情况，反殖民主义斗争的中心就可能从古巴转移到博利瓦尔的伟大祖国。那时，委内瑞拉的人民就会挺身而出，奋起保卫他们的自由。因为他们知道，他们正在进行最后的决战，失败了就会出现最黑暗的暴政；胜利了就会有美洲光辉的前程。人民斗争的洪流一定能冲破我们受奴役的姊妹国家已成为垄断集团墓地的平静。","language":"中文","translation":false},{"id":"che-guerrilla-5-52","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":52,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"可以引证很多情况说明敌人不能取胜，但是有两个基本情况可以说明：第一是外部情况，就是我们处在1960年的情况，这个年代是不发达国家的年代，自由人民的年代，又是尚未为掌握生杀大权者所统治的儿百万人民的呼声最终会得到永远尊重的年代。其次，更为重要的情况是一支六百万古巴人的队伍将拿起武器，团结一致，保卫他们的领土与革命。在这个战场上，部队只不过是武装起来的人民的一部分。如果这支部队在正面斗争中被打败了，那么还会有几百支游击部队，在中央统一领导和能动地指挥下，将在国内每一个角落里进行战斗。在城市里，工人们在自己工厂或工作场所奋起杀敌；在农村，农民们在每株棕榈树后或在革命给予他们新式机械犁犁过的每块土地上消灭侵略者。","language":"中文","translation":false},{"id":"che-guerrilla-5-53","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":53,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"从世界范围来说，还有国际声援，它将筑起由千百万人的胸膛组成的抗议侵略的长城。垄断集团将会看到自己腐朽的支柱怎样受到动摇，几个通讯社所编造的弥天大谎怎么象蜘蛛网似地被狂风刮走。但是，假定他们还是敢于冒天下之大不韪，那么我们在这里又该怎么办呢？","language":"中文","translation":false},{"id":"che-guerrilla-5-54","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":54,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"因为我们海岛的地位容易被攻破，我们的空军和海军力量十分单薄，我们没有重型武器，所以我们显然要做的第一件事情就是把游击战争的原则坚定地贯彻到保卫祖国的斗争中去。","language":"中文","translation":false},{"id":"che-guerrilla-5-55","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":55,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"我们的地面部队将以古巴革命的儿女们在这些光荣的历史年代里所能表现出的毅力、决心和热情来进行战斗。但是，即使遇到最糟糕的情况，即使在战斗的前线我们整个军队组织被打散，我们也要保持我们各个战斗单位。换句话说，在敌军集结大量兵力打散我们军队的情况下，应立即把它化成一支游击队。这支游击队具有很大的能动性，其纵队一级首长有巨大的指挥权；但是它听从设在国内某一地点的中央指挥部的指挥，而中央指挥部要及时发布命令，确定在各种情况下一般的战略方针。","language":"中文","translation":false},{"id":"che-guerrilla-5-56","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":56,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"山岭地带可能是人民有组织的武装先锋队（即起义军）最后保卫的据点，但是战斗必定由后方的大部队（即全体人民）在人民的每座住宅里、每条道路上、每座小山上、每寸国土上继续打下去。下面我们将要谈谈人民如何训练和武装的问题。","language":"中文","translation":false},{"id":"che-guerrilla-5-57","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":57,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"鉴于我们的步兵没有重型武器，我们一定要在反坦克和防空袭方面集中力量。除了迫击炮之外，大量的地雷、反坦克火箭筒、或反坦克榴弹以及活动性能很强的高射炮就是我们唯一的具有一定威力的武器。配有自动武器的老步兵，懂得弹药的意义，会爱惜地使用它们。我们特别辎重队甚至极其困难得情况下，也保持有后备弹药，它们会跟随我们的每支部队前进。","language":"中文","translation":false},{"id":"che-guerrilla-5-58","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":58,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"在敌人这种侵犯的初期，我们的空军可能会遭到较大的打击。因为我们估计到入侵的是头等强国，或者是由这个强国暗地里和公开地支持的某个小强国的雇佣军。如上所说，我们的空军可能被摧毁或几乎被摧毁，剩下的只有侦察机和联络机，特别是直升飞机，以供较小规模的军事行动之用。","language":"中文","translation":false},{"id":"che-guerrilla-5-59","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":59,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"我们海军的结构也要适应于这种流动的战略。我们的小快艇不但行动要非常迅速，而且尽量不让敌人发现；只有在这种情况下，象过去那样，使敌军感到失望的事情是它一直碰不到什么坚实的东西可以攻击。它所碰到的一切都是软绵绵的、滑溜溜的、打不进的、往后退的东西。这样的东西不构成一条坚实的战线，但是却从各个角度杀伤敌人。","language":"中文","translation":false},{"id":"che-guerrilla-5-60","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":60,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"人民的军队，作好了准备，即使在一次正面战斗中失败以后也不溃散，要打垮这样的军队是不容易的。在人民军队的周围团结着农民和工人这两支伟大的人民群众队伍。农民在比那尔德里奥附近阻击一小股匪徒的抢劫中显示了他们的力量。大多数的农民将在本地受训，但是，小队长以上的军官要象现在他们在接受的训练一样，在我们军事基地内接受训练。受训之后，把他们派到全国已经划分成的三十个农业发展的地区，以便建立三十个农村的斗争中心。这些斗争中心负责最大限度地保卫他们的土地、他们的社会成果，他们的新建房子、他们的运河、他们的堤坝、他们的丰收成果、他们的独立地位，一句话，保卫他们的生存权利。","language":"中文","translation":false},{"id":"che-guerrilla-5-61","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":61,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"在开始，农民对于敌军任何的侵犯，都会给予坚决的抵抗，但是如果敌军的力量太强，农民的力量应分散开来。每个农民，在白天是和平的种田人，而在夜间是可怕的游击队员，狠狠打击敌军的力量。工人也是这样，他们中间的优秀分子将受到训练，来领导他们的同志，并对他们进行国防教育。但是，每个社会成员，都有几项不同的任务。农民从事典型的游击战争，他应该成为优秀的射击手，学会善于利用各种不利的地形，学会神出鬼没。工人的有利条件是处在象一座现代化城市那样巨大的高效力的堡垒里，不利的条件是工人难于流动。工人首先要学会用车辆、家具、工具筑成的街垒堵塞街道；要学会把街区当作大堡垒来使用，在墙上打开洞口，使各座房子联通起来；要学会使用可怕的自卫武器——“莫洛托夫鸡尾酒”，还要学会从现代化城市的楼房的无数门窗口上配置火力点。","language":"中文","translation":false},{"id":"che-guerrilla-5-62","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":62,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"由于得到国家警察和负责保卫城市的武装部队的支援，工人群众将组成一支强大的军队，但是它可能付出极大的牺牲。不能设想在这种情况下，城市斗争会有农村斗争那么方便和灵活。在城市的人民斗争中，很多人，或者说我们中间很多人会牺牲。敌人会使用坦克，如果人民善于对付坦克的弱点而且不害怕它们，那么敌人的坦克会很快地被摧毁，但得付出牺牲。","language":"中文","translation":false},{"id":"che-guerrilla-5-63","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":63,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"也存在着与工人农民的组织相似的民众组织。首先是由起义军领导和协助的学生民兵（起义军将拥有优秀的青年学生）；还有一般青年组织，其组成形式也是相同的；还有妇女组织，她们会给其他人以巨大的鼓舞，她们能协助男战友们担负起做饭、护理伤员、安慰即将死去的同志、洗涤等重要的工作。总之，妇女们向男战友们表明：在革命困难时刻她们是始终和他们站在一起的。所有这一切都是通过对群众进行广泛的组织工作和耐心的全面教育而取得的。这种教育从基础知识开始，或在这方面打下基础，但其中心点应该从道理上真实地阐明革命事业。","language":"中文","translation":false},{"id":"che-guerrilla-5-64","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":64,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"在每次会议上，在每次代表大会上，在革命人员开会交谈问题的每个场所，都应该对革命法律进行议论，讲解和研究。此外，对领导人的讲话，特别是对我们无可争辩的领袖的讲话也应该经常进行学习，讲解和讨论，以便引导群众前进。我们的总理经常发表出色的通俗的讲话，大家应集中起来听，在农村可通过无线电广播，在技术没备较先进的地方则可利用电视广播。","language":"中文","translation":false},{"id":"che-guerrilla-5-65","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":65,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"人民应经常关心政治，这就是说，人民应经常关心那些反映他们愿望的法律、命令和决议。对于一切反对革命的表现应经常保持革命的警惕；在道德监督方面，如有可能，对革命群众要比对不革命者或旁观者应更严格。任何革命者，不管他是处在什么地位，也不管从什么观点来说，只要在道德方面犯了严重过错，我们决不因为他是革命者而对他宽恕。不这样，就会使革命走上机会主义的危险道路。然而他是革命者这一事实可能构成减轻处分的理由，而在处分他的时候，也可能总是提出他以前的功劳，不过，他所犯的严重过错本身，则一定要受到处分。","language":"中文","translation":false},{"id":"che-guerrilla-5-66","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":66,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"应该鼓励热爱劳动，特别是集体劳动和为了集体利益的劳动。应大大发展志愿劳动突击队，修建公路、桥梁、码头、堤坝、学生城，使他们不断地团睁起来，用实际行动来表示他们对革命的热爱。","language":"中文","translation":false},{"id":"che-guerrilla-5-67","author":"切·格瓦拉","title":"游击战","location":"第四章 附录","page":5,"paragraph":67,"url":"https://www.marxists.org/chinese/guevara/1960/04.htm","text":"一支与人民打成一片的军队，一支来自工农并与他们休戚相关的军队，一支掌握特殊军事技术的军队，一支在思想上准备应付最坏事变的军队是不可战胜的。如果我们永垂不朽的卡米洛讲的“部队是穿上军装的人民”这句名言更深入军民之心的话，那么我们的军队就更加是不可战胜的了。因此，正因为这一切，尽管垄断集团要消灭古巴这个“坏榜样”，但是我们的未来却会比任何时候更加光辉灿烂。","language":"中文","translation":false},{"id":"che-socialism-man-1-1","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"中文马克思主义文库 -> 切·格瓦拉","language":"中文","translation":false},{"id":"che-socialism-man-1-2","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"（1965年4月11日发表于《绿橄榄》杂志，中译文原载《黑板报文艺》，2000年4月）","language":"中文","translation":false},{"id":"che-socialism-man-1-3","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"《绿橄榄》杂志注：格瓦拉少校这篇专门写给乌拉圭《前进》周刊的文章，论及一系列有关社会主义建设和新人培养的问题，我们的读者对阅读与研究这篇文章一定很感兴趣。","language":"中文","translation":false},{"id":"che-socialism-man-1-4","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"乌拉圭蒙得维的亚，林空街557号《前进》周刊","language":"中文","translation":false},{"id":"che-socialism-man-1-5","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这篇文章，我是在旅行非洲期间写成的，目的是要履行我的诺言，虽然履行的时间晚了些。我打算照文章的标题来谈。我想这对乌拉圭读者来说，是有意义的。","language":"中文","translation":false},{"id":"che-socialism-man-1-6","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"常常听到资本主义的代言人举出一个论据来对社会主义进行思想斗争，这个论据就是说，我们的这个社会制度以及我们所处的社会主义建设时期，其特点就是为了国家而否定个人。我不打算单纯从理论上批驳这一理论，我只想确定一下古巴所正经历的事实，再加上一些一般性的议论。我要扼要地谈一下我们在取得政权之前和之后革命斗争的历史。","language":"中文","translation":false},{"id":"che-socialism-man-1-7","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"如众周知，以1959年1月1日为最高峰的革命行动，它开始的准确日子，是1953年7月26日，由菲德尔·卡斯特罗领导的一批人在这一天的拂晓，袭击了奥边特省的“蒙卡达”兵营。这次袭击失败了，失败又变成为灾难，幸存者被关到了监狱里，他们得到大赦之后，又重新开始了革命斗争。","language":"中文","translation":false},{"id":"che-socialism-man-1-8","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这个过程只具有社会主义萌芽，在过程中，人是基本因素。靠的就是人，单独一个个的人，具体的，有名有姓的人，而任何的成败，就取决于人的行动能力。","language":"中文","translation":false},{"id":"che-socialism-man-1-9","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"到了游击斗争阶段。这个斗争是在两个不同的范围中展开的：一个范围是人民，是仍有待于动员的，熟睡中的群众，另一个范围就是他们的先锋，即游击队，这是动员（人民）的动力，是革命意识与战斗热情的产生者，这支先锋队成了一种触媒剂，为胜利创造了必要的主观条件。同样地在这支先锋队中，在我们思想无产阶级化过程的范围内，在我们的习惯头脑发生的革命的范围内，人也是基本的因素。在革命力量中取得了某种高级地位的每一位马埃斯特腊山区战士，都有一整段杰出行动的历史。他是靠这些行动而取得自己的地位的。","language":"中文","translation":false},{"id":"che-socialism-man-1-10","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"那是第一个英雄的时代，当时大家都争先恐后地担负责任更重，危险更大的职责，唯一得到的补偿就是义务的履行。在我们的革命教育工作中，我们常常反复提到这个富有教育意义的题目。当时我们的战士们的行为隐约显露出了未来的人的形象。","language":"中文","translation":false},{"id":"che-socialism-man-1-11","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在我们的历史的另一些场合，曾重复发生了完全献身于革命事业的事例。在十月危机期间或是在“弗洛拉”飓风的日子里，我们看到全体人民作出了罕见的勇敢牺牲的行动。找到办法来把这种英勇表现在日常生活中永久固定下来，是我们在意识形态方面的基本任务之一。","language":"中文","translation":false},{"id":"che-socialism-man-1-12","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"1959年1月，成立了有爱国资产阶级数名成员参加的革命政府，起义军的存在，作为基本的实力因素，是政权的保证。","language":"中文","translation":false},{"id":"che-socialism-man-1-13","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"接着，发生了严重的矛盾，这些矛盾在1959年2月初步获得了解决，当时菲德尔·卡斯特罗就任总理，统率了政府。到同年7月，当乌鲁蒂亚总统在群众压力下辞职的时候，上述过程大致到了最高峰。","language":"中文","translation":false},{"id":"che-socialism-man-1-14","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"到这时候，在古巴革命的历史中，就明明确确地出现了一个日后不断地一再出现的人物：群众。","language":"中文","translation":false},{"id":"che-socialism-man-1-15","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这个多方面的人物，并不如某些人所说的那样是一批同属一个范畴（而且是被一个硬建立起来的制度拉平到同一范畴之中）的分子的总和，像一群驯服的羊们。的确，他们毫不动摇地追随自己的领导人，主要是追随菲德尔·卡斯特罗，但是他所取得的信任，其程度是与他充分代表人民的愿望和要求相符合的，与他为了履行自己作的诺言而进行的真诚斗争相符合的。","language":"中文","translation":false},{"id":"che-socialism-man-1-16","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"群众参加了土地改革和管理国营企业的艰巨工作；经历了吉隆滩英勇的斗争；在反对各种由中央情报局武装起来的匪帮的斗争中受到的锻炼；在十月危机中经历了当代最重大的一次关头，而且今天继续在为建设社会主义而工作。","language":"中文","translation":false},{"id":"che-socialism-man-1-17","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"从表面上看来，那批说什么个人被国家压倒的人们，也许似乎言之成理；理论所规定的任务，无论是经济方面的，文化方面的，国防方面的，体育方面的，群众都以无比的热情和纪律来执行。倡议一般来自菲德尔或是革命的最高司令员，然后向群众解释，由群众加以接受。另外一些时候，党和政府吸收一些局部的经验，通过同样的程度加以推广。","language":"中文","translation":false},{"id":"che-socialism-man-1-18","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"但是有时国家是会犯错误的。当犯这样的错误的时候，就可以看到，由于组成集体的每一个分子热情的减低，整个集体的热情也减低了，工作就停顿，一直缩小到举足轻重的程度；这就到了要纠正的时候了。1962年，由于阿尼瓦尔·埃斯卡兰特所强加于党的宗派主义政策，就发生了这样的事。","language":"中文","translation":false},{"id":"che-socialism-man-1-19","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"菲德尔和群众之间的辩证统一","language":"中文","translation":false},{"id":"che-socialism-man-1-20","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"显然，光是有一套系统，是不足以保证一系列的明智措施的，还缺了一种组织得更加完善的同群众的联系。对这一点，我们在今后的年代中必须加以改善，但是，在来自政府上层的倡议方面，我们目前采用的是一种几乎凭直觉的方法，探听对已提出的问题的反应。","language":"中文","translation":false},{"id":"che-socialism-man-1-21","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在这方面做得到家的是菲德尔，只有亲眼看他怎样干，才能对他特殊的同人民打成一片的办法作出评价。在大规模的集会上，可以看到一种类似共振的现象，两个振幅彼此引起振动。菲德尔和群众在对话中发生振动，振动的力量越来越强，一直到最后发展到最高峰就以我们斗争与胜利的口号来猛然结束。","language":"中文","translation":false},{"id":"che-socialism-man-1-22","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"一个没有体会过革命经验的人，很难理解个人与群众之间的这种密切的辩证的统一，而作为许多个人的集合体的群众，又同领导人相联系。","language":"中文","translation":false},{"id":"che-socialism-man-1-23","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在资本主义下，有时也可以看到这种现象，这是在出现了一些有动员人民的本领的政治家的时候，但是，除非这是一个真正的社会性运动（如果这样，用资本主义这个名词就完全适当了），否则，运动的寿命也就同推动运动的人的寿命一样短，或者是只能维持到人民的幻想一样短，或者是只能维持到人民的幻想由于碰到资本主义社会的严酷现实而幻灭的时候为止。在这样的社会里，人受到一种冷酷的安排所左右，这种安排通常是超出他所能理解的范围之外的。已经异化出来的个人，有一条看不到的济带把他同整个社会联结起来，这就是价值规律。这个规律对所有各方面的生活起作用，划定着各方面生活的道路与目标。","language":"中文","translation":false},{"id":"che-socialism-man-1-24","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"一般人看不到的，盲目的资本主义规律，对个人起著作用，而个人却觉察不到。他只看到前面是无边无际的广阔天地。资本主义宣传也把情形描写成这个样子，企图从洛克菲勒的事例（不管是否属实）中引申出一个有关种种飞黄腾达的可能性的教导。至于这要积累多少人的贫困，才能出现一个这样的事例，究竟一个人发这样的一笔大财，它本身就也并不总是有可能把这些概念弄清楚。（本来这里也可以探讨一下帝国主国家的工人如何由于在剥削附属国当中有所参与而在逐渐丧失自己的国际精神，这种情况同时又如何在磨掉本国群众的斗争精神，但是这个题目已超出本文意图之外。）","language":"中文","translation":false},{"id":"che-socialism-man-1-25","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"无论如何，道路被说成是虽有障碍，但从外面看来，一个人只要有必要的品质，就可以克服这些障碍，达到自己的目的。奖赏遥遥在望；道路是孤单的。而且，这是狼与狼之间的赛跑；唯有靠别人的失败，自己才能达到目标。","language":"中文","translation":false},{"id":"che-socialism-man-1-26","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"现在，我试说明，在社会主义建设这出奇怪而动人心魄的戏剧中，作为它的个人，他的既是单独的人又是集体的一员的双重身份，是怎样的。","language":"中文","translation":false},{"id":"che-socialism-man-1-27","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我认为，应该干脆承认他是不完善的，是非制成品。昔日的包袱转移到了现在个人意识当中，必须不断地进行工作，来根除这些包袱。","language":"中文","translation":false},{"id":"che-socialism-man-1-28","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这个过程是双重的，一方面是社会以自己的直接间接教育起著作用，另一方面个人又经历着一个自觉的自我教育过程。","language":"中文","translation":false},{"id":"che-socialism-man-1-29","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"正在形成中的社会，不得不同过去的东西进行艰苦的比赛。过去的东西不仅反映在个人的意识当中，表现为那种一贯以把个人孤立起来为方针的教育的残余，而且也反映这个仍然保存商品关系的过渡时期本身的性质。商品是资本主义社会的经济细胞；只要商品存在，它的影响就一定在生产的组织中以及最后在意识中反映出来。","language":"中文","translation":false},{"id":"che-socialism-man-1-30","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"马克思的公式，把过渡时期理解为资本主义制度被它本身的矛盾炸碎而发生突变的结果；后来，在实际上，人们看到了某些像脆弱枝干那样的国家脱离了帝国主义的大树，这种现象，是列宁所预见到的。在这些国家里，资本主义的发展，达到了足以以某种方式表现出自己对人民的影响的程度，但是，并不是它本身的矛盾到了山穷水尽的地步从而把这个制度炸掉。反对外国压迫者的解放斗争，由于一些像战争那样的外来因素而造成的贫困（特权阶级则把贫困的后果转嫁到被剥削者身上），以推翻新殖民主义政权为使命的解放运动，这些都是通常的促发因素。其余部分，则由自觉的行动来完成。","language":"中文","translation":false},{"id":"che-socialism-man-1-31","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"不做出牺牲的迅速转变是不可能的","language":"中文","translation":false},{"id":"che-socialism-man-1-32","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在这些国家里，还没有进行社会劳动的全面教育，财富还远没有通过简单的占有过程为群众所掌握。一方面是不发达状态，另的一方，又是资金通常向“文明的”国家外逃，这就使得迅速而不带牺牲的转变成为不可能。要建设经济基础，还有一大段路要走……在达到这样的地步之前，先经过一段很长的中途，在这段路途上，各种道路一次又是一次地彼此交叉，很不容易觉察到是什么时候走错了路。同时，经过改动了的经济基础，对觉悟的发展又起了破坏作用。要建设共产主义，那就要在缔造物质基础的同时缔造新人。因此，正确地选择动员群众的工具，同时也不要忘记正确地利用物质刺激，道德是社会性的物质刺激。","language":"中文","translation":false},{"id":"che-socialism-man-1-33","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"社会应该成为一个巨大的学校","language":"中文","translation":false},{"id":"che-socialism-man-1-34","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们前面已经说过，在极端危险的时刻，加强精神鼓励是容易做到的，要把这个保持下去，就必须发展一种使良好的质量达至新的范畴的觉悟。整个社会应该变成为一个巨大的学校。","language":"中文","translation":false},{"id":"che-socialism-man-1-35","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这种现象，大体上类似于资本主义意识形成过程的初期。资本主义靠的是强力，但它也对人们进行这个制度的教育。担任直接宣传工作的人们解释说，阶级制度无论是神授的阶级制度，或是由于大自然的机械力量而规定下来的阶级制度，都是不可避免的。这样来安抚受压迫的群众，使他们觉得对于压迫他们的祸害进行斗争是不可能的。然后又给他们一个希望，而这一点，就不同于昔日那些不留给人任何可能的出路的门阀。","language":"中文","translation":false},{"id":"che-socialism-man-1-36","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"对于某些人来说，门阀的公式将要继续保持其效力；乖乖听活，奖赏就是；在死后能到另外一些美妙的世界去。在那边，好人能得到奖赏，这就保持了老一辈的传统。对于另外一些人来说，奖赏就是某新身份；阶级的区分是注定不可避免的了，但是个人可能通过自己的劳动和能动性等等来摆脱他本来所属的阶级。这种过程，以及为了飞黄腾达而进行的自我教育，都必然是十分虚伪的；这是别有用心地把谎言说成真理。","language":"中文","translation":false},{"id":"che-socialism-man-1-37","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在我们这里直接教育就更加重要得多，解释能说服人是因为这是真话；不必借助于遁辞。这件事是由国家的教育机构按照一般文化水平，技术水平与思想水平，通过一些像教育部与党的宣传机关这样的机构来进行的。教育在于引导群众，使群众的新态度趋于变成习惯，群众逐步接受了它；而对还没有教好的人施加奋力。这是教育群众的间接的方法，这方法同前面一个方法是一样地有力量。","language":"中文","translation":false},{"id":"che-socialism-man-1-38","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"但是，过程是自觉的；个人不断地受到社会政权的影响，觉察到自己对这个社会并不完全适应，在间接教育这一压力的影响下，他设法使自己适应一个他觉得是正确的局面，而在此之前，由于是这种局面发展得不够，使得末曾这样做。现在他在自我教育。","language":"中文","translation":false},{"id":"che-socialism-man-1-39","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在这个社会主义建设时期，可以看到正在诞生的新人。他的形象还没有完成；也恐怕永远完成不了。因为这个过程是同新的经济形式的发展平行地前进的。且不说那些由于缺乏教育而趋于走孤立的道路，趋向于自行满足自己的野心的人们，甚至在这个共同前进的总形势之中，也有一些人，他们日益意识到有必要投身到社会中去，意识到自己作为社会的动力而占据的重要地位。","language":"中文","translation":false},{"id":"che-socialism-man-1-40","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"他们已经不是完全孤零零地通过羊肠小道向着遥远的希望前进了。他们跟随着自己的党，先进工人，先进分子组成的先锋队，这支先锋队同群众联系着，同他们密切地打成一片。先锋队的目光注视着未来，也注视着未来的奖赏，但这个奖赏已经不是表现为某种个人的东西了；奖赏就是一个新社会，在这个社会中，人们将具有另外不同的特点。这个社会就是共产主义的社会。","language":"中文","translation":false},{"id":"che-socialism-man-1-41","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"道路是漫长并充满着困难的。有时由于路走偏了，要回头走；有时我们由于走得太狭而离开了群众；有时我们由于走得慢了而感觉到跟着我们的人们紧挨我们身边呼出的气息。我们凭自己革命者的雄心壮志，设法尽可能走得快些，在前面开路，但是我们懂得我们必须从群众中吸取营养，而唯有我们作出榜样来鼓舞他们，他们才能更快地前进。","language":"中文","translation":false},{"id":"che-socialism-man-1-42","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"尽管重视了精神鼓励，但人们分成为两个主要的集团（当然这里还不包括那些由于这种或那种原因不参加社会主义建设的一部分人）的这一事实，就表明了社会觉悟的发展还不够。先进集团在意识形态上比群众先进；群众对新事物有认识，但认识还不够。前一种人身上发生质变，使他们能以先锋的身份去作牺牲，而后一种人则只能隐隐约约看到事物，需要对他们加以鼓励和施加一定程度的压力；无产阶级专政不仅仅是施加在被打败的阶级身上，而且也施加在胜利的了阶级的个人身上。","language":"中文","translation":false},{"id":"che-socialism-man-1-43","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这一切，为了能彻底成功，就需要一系列的程序，即革命法则。同正在向着未来进军的广大群众的形象相符的法制化这个概念，就是要有和谐配合的一整套渠道，阶梯，水坝，擦满了润滑油的器具，来实行这一进军，来自然而然地选择应走在前列的人，并对那些完成了任务的人和那些侵犯正在建设中的社会的人实行奖励或惩罚。","language":"中文","translation":false},{"id":"che-socialism-man-1-44","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"政府和集团之间达到完全一致","language":"中文","translation":false},{"id":"che-socialism-man-1-45","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"革命的这种法制状态还没有达到。我们在寻找某些新的办法来使得政府与整个集体之间达到尽善尽美的一致。这种一致要符合社会主义建设的特殊条件，并尽可能避免那些转移到正在形成中的社会中来的资产阶级社会法制（例如立法议会）。已经进行了某些旨在进一步创造革命法制状态的试验，但并没有操之过急。我们已遇到的最大的障碍，是生怕任何形式上的东西使得我们脱离群众和个人，使得我们忽略最后与最重要的一个革命志向：使人摆脱其异化状态。","language":"中文","translation":false},{"id":"che-socialism-man-1-46","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"虽然还缺乏制度（这是应该逐步克服的），现在群众已经作为许多为同一事业而斗争的个人组成的觉悟的集体，而在创造着历史。在社会主义下，人虽然表面看来是标准划一的，但却是更加完全的；尽管缺少完善的一套办法来保证，但人有了无限的大得多的可能来表现自己，使自己在社会机关当中能被人感觉到。","language":"中文","translation":false},{"id":"che-socialism-man-1-47","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这必须使他进一步自觉地以单独或集体的方式参加一切领导与生产的机构，而且使他把这一点同对技术与思想教育的必要性的认识联系起来，从而使他感觉到这几件事是密切相关的，是齐头并进的，这样，他就会充分意识到自己的社会地位，这就等于说；他把异化的枷锁打破了，他作为人来说，是充分完成了。","language":"中文","translation":false},{"id":"che-socialism-man-1-48","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这将具体表现为通过解放了的劳动来恢复他的天性，通过文化和艺术来表现他本身的人类地位。","language":"中文","translation":false},{"id":"che-socialism-man-1-49","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"为了发展他的正确性，劳动必须具有新的地位；作为商品的人不复存在，建立起一个按每人履行社会义务的情况而分配的制度。生产资料属于社会，机关不过是义务时所在的战壕。人开始把自己的思想从不得不通过劳动来满足自己的动物性需要的这一讨厌的事实中解放出来。他开始在自己的工作中看到自己的肖像，开始在创造出来的物品中，在实现了的劳动中理解到自己作为人的伟大。这已经不意味着他要把自己生命的一部分作为售出了的，不再归他所有的劳动力而留下来，而是意味着他从自身引申出了新的东西，对把他反映在内的共同生活作出贡献，意味着履行他的社会义务。","language":"中文","translation":false},{"id":"che-socialism-man-1-50","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们尽量使劳动能带上这种社会义务的新性质，一方面把它同技术的发展结合起来（这将为更大的自由创造条件），另一方面把它同自愿劳动结合起来，因为马克思主义认为，当人不是物质上的需要强迫把自己作为商品出售时，他就是真正达到了自己充分的人类地位。","language":"中文","translation":false},{"id":"che-socialism-man-1-51","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"当然，劳动中还有强制的方面，尽管这是自愿的劳动；人还没有把自己周围的一切强制力量变成为社会性质的条件反射，他往往还是在环境地的压力（菲德尔称之为道义上的强制）下产生的。他还没有能够不受社会环境直接压力（但社会环境通过新的风尚与他相联系）而对自己的工作实行精神上的彻底再创造。做到这一点，那就是共产主义了。","language":"中文","translation":false},{"id":"che-socialism-man-1-52","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":52,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"变化，在意识当中，并不是自动发生的，正如在经济中也不是自动发生的一样，变动是缓慢的；有些时候会加速，有些时候会停顿，甚至会倒退。","language":"中文","translation":false},{"id":"che-socialism-man-1-53","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":53,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"共产主义的第一个过渡时期","language":"中文","translation":false},{"id":"che-socialism-man-1-54","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":54,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"此外，正如我们前面所指出的，我们必须认为，我们所面对着的，并不是马克思在《哥达纲领批判》中所看到的阶段；这是共产主义的第一个过渡时期或者说，是社会主义建设时期。这个时期，而是在激烈的阶级斗争中进行的。它内部有资本主义因素，这些因素模糊了对它的本质的彻底认识。","language":"中文","translation":false},{"id":"che-socialism-man-1-55","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":55,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"如果除了这一点，再加之以烦琐哲学妨碍了马克思主义哲学的发展，妨碍了对这个时期进行有系统的探讨，使得这时期的政治经济学没有发展，那么，我们就必须同意；我们还处在襁褓中，必须大力研究这个时期的各个主要特点，才能制定出更加有用的经济与政治理论。","language":"中文","translation":false},{"id":"che-socialism-man-1-56","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":56,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"产生出来的理论，必将注重建设的两大支柱：新人的培养成和技术的发展。在两方面，都有许多事待我们去做，但是，如果对技术为根本基础这一点认识不足，那就更不可以原谅，因为这里的总是不要盲目地前进，而是要在相当一段过程中循着世界最先进的国家所已经开辟了的道路前进。因此，菲德尔才这样再三强调我们全体人民尤其是他们的先锋队的技术科学培养。","language":"中文","translation":false},{"id":"che-socialism-man-1-57","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":57,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"物质需要和精神需要之间的划分","language":"中文","translation":false},{"id":"che-socialism-man-1-58","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":58,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在进行非生产活动的思想领域，物质需要和精神需要之间的划分更为容易看出。自古以来，人便力图通过文化与艺术来摆脱自己的异化状态。他在自己以商品的身份活动的8小时或更多的小时中，是死人，然后才在自己的精神消遣中复活。但是这种药剂，本身又带了同一病症的细菌；他是孤零零地设法同大自然融合的。他护卫着自己受到环境压抑的个性，他是作为一个统一的，以保持自己清白为目的的个体，而对于美学思想作出反应。","language":"中文","translation":false},{"id":"che-socialism-man-1-59","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":59,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这只是一种逃避的企图。价值法则已经不仅仅是生产关系的反映了；垄断资本家用错综复杂的脚手架把这个规律包围住，把它就变成一个驯服的奴隶，虽然他们所采用的方法是纯粹凭经验不自觉地产生的。上层建筑规定一种艺术，艺术家就要受这种艺术的教育。反叛者被机器统治着，只有非凡的天才，才能创造出自己本身的事业。其余的人，或者成为变相奴化的受雇者，或者被粉碎。","language":"中文","translation":false},{"id":"che-socialism-man-1-60","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":60,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"人们发明了艺术探讨，把它说成是自由的表征，但是这种“自由”有它的限度，这个限度，在碰到之前，也就是说，在人及其异化的现实总问题提出来之前，是觉察不到的。无谓的苦闷和庸俗的娱乐，成为让人类的不安心理发泄出去的便利的门阀；把艺术当作暴露的武器的这一想法，受到反对。","language":"中文","translation":false},{"id":"che-socialism-man-1-61","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":61,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"如果遵守这一套做法的规则，就可以得到一切荣誉，也就是一只猴子在耍把戏时可以得到的荣誉。条件就是不要试图逃出牢笼。","language":"中文","translation":false},{"id":"che-socialism-man-1-62","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":62,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"艺术探讨得到了进一步的推动","language":"中文","translation":false},{"id":"che-socialism-man-1-63","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":63,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"当革命取得政权的时候，那批已完全被驯化的人们就纷纷外逃，而其余的人，不论是否革命者，都看到了一条新的道路。艺术探讨得到了进一步的推动。但是，各种道路已经大体上划定了，自由这个字眼，背后隐藏了逃避的这一概念的真义。这种态度，甚至往往保持在革命者身上，这是资产阶级唯心主义在意识中的反映。","language":"中文","translation":false},{"id":"che-socialism-man-1-64","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":64,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在曾经经历过类似道路的国家里，曾企图以一种过分的教条主义来反对这些倾向。文化常识几乎变成一种禁忌，宣布了文化要求的总和就是形式上准确地认识自然界，而这种认识，又进一步变为对于愿意展示的社会现实的机械认识，这就是正在企图创立的一个几乎没有冲突和矛盾的理想社会。","language":"中文","translation":false},{"id":"che-socialism-man-1-65","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":65,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"社会主义是年轻的，有错误。我们革命者往往缺乏必要的知识和组织来承担一个任务，即以不同于常规的方法来培养新的人，常规方法是受到形成这些方法的那个社会的影响的（这就又一次提出了形式与内容的关系问题）。思想混乱是很厉害的，物质建设的问题缠住了我们。没有拥有巨大权威而又同时拥有巨大革命权威的艺术家。党的人应该把这一任务担负起来，力求达到主要目的；教育人民。","language":"中文","translation":false},{"id":"che-socialism-man-1-66","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":66,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在上世纪艺术基础上的社会主义现实主义","language":"中文","translation":false},{"id":"che-socialism-man-1-67","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":67,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"干部们懂得的东西，就是人人懂得的。取消了真正的艺术探讨，把文化常识的问题归结为掌握社会主义的现在和已经死亡的过去（正因为它是已死亡的，所以又不是危险的）。就这样，在上世纪艺术的基础上，诞生了社会主义现实主义。","language":"中文","translation":false},{"id":"che-socialism-man-1-68","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":68,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"但是19世纪的现实主义艺术也是有阶级性的，它的资本主义性也许比20世纪的这种颓废艺术（它流露了异化的人的苦闷）更为纯粹。文化上的资本主义已经起完了自己的全部作用，它只剩一个发臭的尸体广告；在艺术上，这就是它今天的颓废。但是为什么社会主义现实主义的僵化形式当中寻找唯一有效的药方不可呢？拿“自由”来同社会主义现实主义相对立是不可能的，因为这个自由还不存在，它唯有到了新社会充分发展了之后才存在；但是，不要从不顾三七二十一的现实主义的教皇宝座上谴责19世纪下半叶以后的一切艺术形式，因为这样就会陷于复古的普鲁东主义错误，硬要把生在今天，建设在今天的人的艺术表现穿上一件紧身衣。","language":"中文","translation":false},{"id":"che-socialism-man-1-69","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":69,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"缺少的是：要发展一套意识文化手段，使探讨能够进行，清除杂草（这些杂草，在国家当前这一肥沃土地上，是很容易繁殖的）。","language":"中文","translation":false},{"id":"che-socialism-man-1-70","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":70,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在我国，现实主义机械论的错误没有发生，但却的确发生了相反的错误。这是由于没有认识到创造新人，这样的人不应代表19世纪的思想，但也不应代表我们这个没落的，病态的世纪思想。我们要创造的是21世纪的人，虽然这只是一主观的，没有系统化的愿望。这正是我们研究与努力的重点之一，等到我们在理论基础上取得具体的成就，或是相反的在我们的具体调查的基础上得出广泛的理论结论。我们就会对马克思列宁主义，对人类的事业作出宝贵的贡献。","language":"中文","translation":false},{"id":"che-socialism-man-1-71","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":71,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"由于反对19世纪那样的人，产生了一个反作用。使我们重犯20世纪的颓废主义；这不是一个太严重的错误，但我们必须克服这个错误，不然的话就会为修正主义开辟广阔的渠道。","language":"中文","translation":false},{"id":"che-socialism-man-1-72","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":72,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"广大群众在发展，新的思想在社会中得到充分的推动，全体社会成员一个不漏地全面发展的物质条件使得工作更为有收获。现在是斗争的时代；未来是我们的。","language":"中文","translation":false},{"id":"che-socialism-man-1-73","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":73,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"总之，我们许多知识分子和艺术家的过错，就是在于他们的老毛病，他们不是真正革命的，我们可以在榆树上接枝，使它长出梨子，但是同时又必须栽种梨树。新的时代将不会有这个老毛病。文化领域和表达的机会越是广大，出现非凡超众的艺术家的可能性就会越大。我们的任务是体现在这一代由于自己的冲突而离开了常态的人，不要变坏，也不要把下一代带坏。我们不应该创造出一些对官方思想百依百顺的领工薪者和靠（国家）预算生活，运用引号中的自由的“领奖学金者”。将有革命者到来，以人民的真正声音高唱新人的歌。","language":"中文","translation":false},{"id":"che-socialism-man-1-74","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":74,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在我们社会里青年和党起着巨大的作用。","language":"中文","translation":false},{"id":"che-socialism-man-1-75","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":75,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"特别重要的是青年，因为他们是一块可以塑捏的粘土，拿这块粘土，可以建设不带任何昔日包袱的新人。他们受到一种同我们的志向和目标一致的教育。他们受的教育日益完整。我们从一开始时就没有忘记把他们吸引到工作中来。我们的奖学金学生在假期或者晨学习的同时参加体力劳动。劳动在某些场合是一个奖赏，在另一场合是一件教育工具，但无论在任何场合都不是惩罚的工具。新生的一代正在诞生。","language":"中文","translation":false},{"id":"che-socialism-man-1-76","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":76,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"党是先锋组织。最优秀的劳动者被同伴们推荐参加党。党员是占少数的，但由于自己干部的质量而享有巨大的威信。我们的希望是使党成为群众性的党，但这要到群众达到了先锋队的发展水平的时候也就是说，要到群众受到了充分的共产主义教育的时候。工作就是以这个教育为主旨的党是活生生的榜样；党的干部必须作出勤劳与牺牲的榜样；他们必须通过自己的行动，要把对建设中的困难，对阶级敌人，对昔日的脓疮，对帝国主义进行的多年艰苦斗争，贯彻到群众中去，贯彻到完成革命任务中去。","language":"中文","translation":false},{"id":"che-socialism-man-1-77","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":77,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我现在想解释一下杰出人物，作为创造历史的群众领导者的个人作用问题。","language":"中文","translation":false},{"id":"che-socialism-man-1-78","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":78,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"菲德尔在最初的岁月里推动了革命，一贯给了革命以领导，规定了革命的基调，但是，有相当一批革命者沿着同这位最高领袖相同的方向发展，有大批群众由于跟随自己的领导人而跟随着他们；群众之所以依赖他们，是因为他们善于代表了群众的愿望。","language":"中文","translation":false},{"id":"che-socialism-man-1-79","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":79,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"问题不在于有多少公斤的肉吃，一年能到海滩去玩多少次，也不在于凭目前的工资能够买多少进口的好东西。问题恰恰在于使个人感到自己更加充实，内部更加丰富，负有更大的责任。","language":"中文","translation":false},{"id":"che-socialism-man-1-80","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":80,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们国家的每个人，知道自己所处的光荣时代是一个牺牲的时代，懂得牺牲。最初一批人在马埃斯特腊山和战斗过的一切地方懂得了牺牲；后来我们在全古巴都懂得了牺牲。古巴是美洲的先锋，它必须作出牺牲，因为它占有先锋的位置，因为它向拉丁美洲的群众指出了取得长度自由的道路。","language":"中文","translation":false},{"id":"che-socialism-man-1-81","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":81,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在国内，领导人必须起自己的先锋作用，应该十分坦率地说，在一场要求人们贡献出一切，勤勤恳恳而不给人以取得任何物质报酬的希望的革命当中，先进革命者的任务，是既壮伟大而又痛苦的。","language":"中文","translation":false},{"id":"che-socialism-man-1-82","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":82,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"请允许我告诉你，哪怕听起来有受人嘲笑的危险，真正的革命者是以强烈的爱感为指南的。不可能想象一个真正的革命者不是以强烈的爱感为指南的，不可能想象一个真正的革命者没有这种质量。也许这是领导人要过的大关之一；他必须把慷慨激昂的精神同总代表的头脑结合起来，在作出痛心的决定时一条筋肉也不挛动。我们的革命者必须把这种对人民对最神圣的事业的爱理想化，使这种爱成为统一不可分割的爱。他们不应抱着一点点日常的感情，下降到一般人都能做到的那个水平。","language":"中文","translation":false},{"id":"che-socialism-man-1-83","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":83,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"革命的领导人，他们的孩子在呀呀学语时不是先学会叫爸爸；他们的妻子也成了他们为了实现革命而在生活中作茧自缚付出的总牺牲的一部分；他们交朋友的范围，严格地局限于革命的同志。此外再也没别的生活了。","language":"中文","translation":false},{"id":"che-socialism-man-1-84","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":84,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在这种情况下必须有强烈的人道感，强烈的正义感，才不至于陷到脱离群众的状态中去，天天都必须奋斗，来使得这种对活着的人类的爱变为具体的事实，变成为起示范和动员作用的行动。","language":"中文","translation":false},{"id":"che-socialism-man-1-85","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":85,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"在自己党内作为革命的思想发动机的革命者，一生就消磨在这种川流不息的活动中，这种活动归宿只不过是死亡，除非在世界范围内都实现了建设。如果当最急迫的任务在局部范围已经完成的时候他的革命热情就不再是一支促进的力量，而会陷入一种小康的冬眠状态，这时我们的敌人帝国主义就会加以利用，占据阵地。无产阶级国际主义是一个义务，但同时也是一个革命的必要。我们就是这样教育“我们人民的”。","language":"中文","translation":false},{"id":"che-socialism-man-1-86","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":86,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"当然，在目前情况下，存在着一些危险。不单有教条主义的危险，不单是有伟大任务当中把同群众的关系僵化起来的危险；而且也有陷进弱点之中的危险。如果一个人认为由于他一个儿子缺乏某种东西，由于孩子的鞋破了，由于他家里缺了某件必要的东西，他就因此分心而不能集中力精力来把整个生命用于革命，那么，他就是在这个理由的掩护下让一些将来可能发展为腐化的细菌侵蚀进来。","language":"中文","translation":false},{"id":"che-socialism-man-1-87","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":87,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"拿我们来说，我们认为，一般人的孩子有什么和缺什么，我们的孩子也应该有什么和缺什么；我们的家庭应为此而努力，革命是通过人来进行的，而人则应该天天锻炼自己的革命精神。","language":"中文","translation":false},{"id":"che-socialism-man-1-88","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":88,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们就是这样前进的。走在这支浩荡队伍之前的是菲德尔（我们这样说时并不难为情也不胆怯），紧接着是党最优秀的干部，再紧接着靠得这样近，使人感觉到他们的巨大力量的是全体人民；这一副由个人组成的牢固的骨架，朝着共同的目标前进；这些个人已经认识到应该做什么；这些人为了走出必然的王国并进入自由的王国而斗争。","language":"中文","translation":false},{"id":"che-socialism-man-1-89","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":89,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"这一大群人排起队来；排列的队形同对这一排队的必要性的认识相适应；他们已经不是一支零散的力量，不再像手榴弹碎片那样分成千百片飞散四方，每一碎片都与同类进行猛烈的竞争，千方百计设法夺得一个地位，以便能在对付朝不保夕的未来时有所依托。","language":"中文","translation":false},{"id":"che-socialism-man-1-90","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":90,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们知道，我们面前还有牺牲，我们为了把整个国家建成先锋队这一英雄事业，必须付出代价。我们第一个人都准确无误地贡献出自己的一份牺牲，深知我们所取得的奖赏，就是从履行义务中得到的满足，深知我们正在同所有人一起，朝着地平在线显现的新人前进。","language":"中文","translation":false},{"id":"che-socialism-man-1-91","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":91,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"因为我们更加全面，所以更加自由","language":"中文","translation":false},{"id":"che-socialism-man-1-92","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":92,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"请允许我试作下列结论：我们社会主义者更加自由，因为我们更加全面；我们更加全面，因为我们更加自由。","language":"中文","translation":false},{"id":"che-socialism-man-1-93","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":93,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们的自由已经形成了它的骨骼，只欠蛋白质和衣服；我们要创造这些。","language":"中文","translation":false},{"id":"che-socialism-man-1-94","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":94,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们的自由和它每天的依托，带有血的色，充满了牺牲。","language":"中文","translation":false},{"id":"che-socialism-man-1-95","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":95,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们的牺牲是自觉的；这是为了我们所建设的自由已缴纳的费用。","language":"中文","translation":false},{"id":"che-socialism-man-1-96","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":96,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"道路是漫长的，而且部分地是不可预知的；我们懂得我们的局恨性。我们要造就出21世纪的人；我们自己来造就。","language":"中文","translation":false},{"id":"che-socialism-man-1-97","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":97,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们将在每天的行动中锻炼自己，创造出具有新技术的新人。","language":"中文","translation":false},{"id":"che-socialism-man-1-98","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":98,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"个人当他体现人民最高的品德和希望，而不是离开道路时，他就起动员与领导的作用。开辟道路时，他就起动员与领导的作用。","language":"中文","translation":false},{"id":"che-socialism-man-1-99","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":99,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"开辟道路是先进的一批人，是好人当中的最优秀者，它就是党。","language":"中文","translation":false},{"id":"che-socialism-man-1-100","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":100,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"我们事业的基本材料是青年；我们把希望寄托在他们身上，我们培养他们从我们手中把旗帜接过去。","language":"中文","translation":false},{"id":"che-socialism-man-1-101","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":101,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"如果这封呀呀学语的信能说明一些问题的话，它就完成了我寄这封信的使命了。","language":"中文","translation":false},{"id":"che-socialism-man-1-102","author":"切·格瓦拉","title":"古巴的社会主义和人","location":"切·格瓦拉：古巴的社会主义和人","page":1,"paragraph":102,"url":"https://www.marxists.org/chinese/guevara/marxist.org-chinese-che-19650411.htm","text":"请接受我们礼节上的问候，像一次握手或一声寒暄那样。","language":"中文","translation":false},{"id":"communism-abc-1-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-1-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"我们设想，《共产主义ABC》应当是共产主义知识的初级课本。宣传鼓动人员的日常经验使我们深信，现在迫切需要这样一种“课本”。新队伍一批批来到我们这里。师资力量痛感不足，而象党校这样的机构甚至连教材都没有。原有的马克思主义文献，象《爱尔福特纲领》之类，大部分显然很不合用，而对许多新问题的解答由于散登在各种杂志和小册子里，查起来也很不方便。","language":"中文","translation":false},{"id":"communism-abc-1-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"因此我们决心来填补当前的这个空白。我们把这本《ABC》视为党校必读的教科书，但也力求写得使每一个想了解我党纲领的工人或农民便于自学。","language":"中文","translation":false},{"id":"communism-abc-1-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"凡是得到本书的同志必须读完它，以确立关于共产主义的目标和任务的概念。因为本书写法与纲领原文的叙述顺序是相同的，为了方便读者，纲领原文分段附在书后，纲领中的每段话都与书中加上了标号的几个解释段落相对应。还编了一个质疑索引，以便查找要查的词汇。","language":"中文","translation":false},{"id":"communism-abc-1-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"主要资料是用普通铅字排印的，较为详细的说明、事例和数字等等也用同号铅字，但略有区别，即行间空隔稍宽一点。这些材料主要供工人同志使用，因为他们只能靠自学，没有时间和机会立即查事实性的资料。","language":"中文","translation":false},{"id":"communism-abc-1-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"每章附有参考书目，供深入研究者使用。","language":"中文","translation":false},{"id":"communism-abc-1-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"作者深知，书中会有许多缺点，因为它是抽空“挤时间”写的。共产党人总是不得不在异乎寻常的条件下从事写作。本书在这方面是一个有趣的例子：原稿在莫斯科委员会被炸时几乎毁掉（与二位作者一起）……不过，尽管本书有各种缺点，我们仍然认为需要将它尽快出版。我们只请同志们把在实践中所发现的问题告诉我们。","language":"中文","translation":false},{"id":"communism-abc-1-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"整个理论（第一）部分，第二部分开头以及论苏维埃政权、论工业组织和保健组织等章节都是布哈林写的；其余章节是由普列奥布拉任斯基写的。但不言而喻，我们两人彼此都负全责。","language":"中文","translation":false},{"id":"communism-abc-1-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"前言","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/01.htm","text":"我们这本书的书名（《ABC》）是根据我们给自己所提出的任务而定的。如果我们的书能对初学同志和工人宣传员有所帮助，那么，我们写这本书就总算没有白写。","language":"中文","translation":false},{"id":"communism-abc-2-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-2-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"· 第二节 我们的旧纲领是怎样的","language":"中文","translation":false},{"id":"communism-abc-2-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"· 第三节 为什么要改用新纲领","language":"中文","translation":false},{"id":"communism-abc-2-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"· 第四节 我们的纲领的意义","language":"中文","translation":false},{"id":"communism-abc-2-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"· 第五节 我们的纲领的科学性质","language":"中文","translation":false},{"id":"communism-abc-2-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"任何一个政党都要达到一定的目标。不论是地主或资本家的政党，不论是工人或农民的政党，都无一例外。任何一个政党必须有自己的目标，否则，就不成其为政党。如果这是一个维护地主利益的政党，那么，它就实现地主的目标：如何掌握土地，如何束缚农民，如何高价出售自己庄园的粮食，廉价雇佣长工或 榨取高额地租。如果这是资本家和工厂主的政党，那么，它同样也会有自己的目标：取得廉价劳动力，驯服工厂工人，寻求能以高价购买其产品的买主，赚取更多的利润，迫使工人为此而更多地干活，而主要的是设法使工人根本不考虑新制度，让他们以为：老板历来都有，今后也将永远存在。这些就是工厂主的目标。不言而喻，工人和农民的目标则完全不同，因为他们的利益完全不同。人们过去说：“俄国人好过了，德国人就要死亡。”其实，更确切的说法是：“工人好过了，地主和资本家就要死亡。”这就是说：工人、资本家和地主各有各的难处。但不是每一个地主都能想出什么是他们整治庄稼人的好办法。有的人总是喝得醉气醺醺，甚至对管家的禀报都不予理睬。工人和农民的情况也类似这样。有的说：“得啦，我们凑合过吧，我们少管闲事。我们的祖先从前怎样生活，我们也就怎样生活。”这些人什么也不参加，甚至不懂自己的切身利益。与此相反，那些想更好地维护自己利益的人则组织成为政党。可见，加入政党的不是整个阶级，而是本阶级最优秀最积极的部分，由这部分人率领其他人前进。参加工人政党（布尔什维克共产党）的是优秀工人和贫农；参加地主和资本家政党（“立宪民主党”，“人民自由党”）的，是那些最有能力的地主、资本家及其奴仆：律师、教授、军官、将军，等等。可见，每个政党都代表着本阶级最有觉悟的部分。所以，组成政党的地主或资本家比没有组织起来的人能更有成效地对付工人和农民。同样，入了党的工人也能比非党工人更有成效地同资本家和地主进行斗争。因为他周密考虑了工人阶级的目标和利益，知道怎样去实现它们，什么样的办法最简便易行。","language":"中文","translation":false},{"id":"communism-abc-2-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"政党为维护本阶级利益而力求达到的全部目标也就是党的纲领。就是说，纲领所写明的，是某个阶级应当去争取的东西。共产党的纲领所宣布的是工人和贫农应当去争取的东西。任何一个政党最重要的就是纲领。通常只要看一下纲领，就可以知道这个政党是维护谁的利益。","language":"中文","translation":false},{"id":"communism-abc-2-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"第二节 我们的旧纲领是怎样的","language":"中文","translation":false},{"id":"communism-abc-2-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"我们现在的纲领是在1919年3月底由党的第八次代表大会通过的。在此以前，没有成文的明确纲领。只有一个在1903年由党的第二次大会制定的旧纲领。在拟订这个纲领时，布尔什维克和孟什维克还同在一个党内，他们的纲领是共同性的。工人阶级当时还刚刚处在组织形成阶段。工厂非常少。甚至人们对工人阶级在我国是否成长起来这一点都有争论。“民粹派”（现在社会革命党人的先驱）认为，工人阶级在俄国注定是发展不起来的，工厂在我国不会有大发展。马克思主义者[1]——社会民主党人（既包括后来的布尔什维克，也包括后来的孟什维克）——则与此相反，认为在俄国，正如在其他国家一样，工人阶级将会壮大起来，成为革命的主力。实际生活表明，民粹派的意见是错误的，而社会民主党人的观点是正确的。不过，当社会民主党在第二次代表大会上制订自己的纲领（参加起草的有列宁和普列汉诺夫）时，工人阶级的力量仍然很弱。正因为如此，谁也没有想到将来可以直接走向推翻资产阶级的道路。当时只要能够推翻沙皇制度，为工农及其他人争得结社自由，实行八小时工作制，对地主稍加约束，就算不错了。至于建立长期的工人政权，立即剥夺资产阶级的工厂，还没有人想过。我们1903年的旧纲领就是这样。","language":"中文","translation":false},{"id":"communism-abc-2-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"第三节 为什么要改用新纲领","language":"中文","translation":false},{"id":"communism-abc-2-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"从那时起过了很长时间，一直到十月革命为止，情况发生了很大变化。俄国的大工业在此期间有了巨大的发展，工人阶级也随着壮大起来。它在1905年的革命中就显示了威力。而到第二次革命（1917年）时情况就明显了，只有在工人阶级取得胜利的时候，革命才能胜利。但是这时工人阶级已经不能满足于它在1905年会感到满足的东西。这时它已经很成熟，必然会要求没收工厂，建立工人政权和治服资本家阶级。这就是说，从制订第一个纲领以来，俄国内部关系已经发生了根本变化。但是，更重要的是，外部关系也同样发生了很大变化。整个欧洲在1905年“平安无事”。每一个明白事理的人在1917年都能看到，在世界大战的基础上正孕育着一场行将到来的世界革命。在1905年，继俄国革命之后，只是奥地利工人运动和东方的波斯、土耳其和中国等落后国家的革命运动略有进展。在1917年的俄国革命以后，则不但爆发了东方革命，而且西方工人阶级也在打倒资本的旗帜下奋起进行斗争。可见，无论是国内形势或国外形势，现在都与1903年不同。如果工人阶级政党再把1903年的纲领用于情况完全改变了的1917——1919年，那是非常可笑的。当孟什维克指责我们“背弃了”我们的旧纲领，从而背弃了马克思学说时，我们反驳说：马克思的学说正在于它的纲领不是从脑子里凭空想出来的，而是从实际生活中产生出来的。如果实际生活发生了巨大变化，纲领就不能一成不变。冬天人要穿皮大衣，夏天只有疯子才穿它。在政治上情况也是一样。马克思教导的恰恰在于始终都要细心观察实际生活状况，并采取符合它们的行动。不能因此就认为我们应当象太太们换手套一样来改变自己的信念。工人阶级最重要的目标是实现共产主义制度。而这个目标是它的长远目标。自然，由于它离这个目标很远，它提出的要求也将是各种各样的。工人阶级在专制制度下被赶入地下，它的政党象罪犯的党一样备受迫害。现在工人阶级掌握政权，它的党是执政党。当然，只有完全无知的人才会坚持把1903年的纲领应用于今天。","language":"中文","translation":false},{"id":"communism-abc-2-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"总之，俄国内部实际生活条件的变化和整个国际形势的变化，引起了修改我们的纲领的必要性。","language":"中文","translation":false},{"id":"communism-abc-2-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"第四节 我们的纲领的意义","language":"中文","translation":false},{"id":"communism-abc-2-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"我们的新纲领即莫斯科纲领是已执政许多时间的工人阶级政党的第一个纲领。因此，我们党在这里应当考虑工人阶级在管理和建设新生活事业中所积累的全部经验。这不仅对我们俄国工人阶级和俄国农村贫农很重要，而且对外国同志也很重要。因为不仅我们自己，而且整个国际无产阶级都要从我们的成功和失败、错误和失算中学习。因此，在我们的纲领中不仅有我们党想要实现的东西，而且还包括部分已经实现了的东西。对于我们每一个党员来说，应当熟悉我们纲领的全部条文。纲领是每个党支部和每个同志最重要的行动准则。要知道，只有“赞成”纲领即承认纲领正确的人才能成为党员。而要承认它正确，就只有去了解它。当然，有很多人没有见过任何纲领，他们混进了党，向共产主义宣誓，是由于他们想多弄到几块面包，或者获得一个优厚的职位。我们不需要这样的共产党员，因为他们只会带来害处。谁不懂得纲领，谁就不能成为真正的布尔什维克式的共产党员。每一个有觉悟的俄国工人和贫农应当懂得我们党的纲领。每一个外国无产者应当细心的研究它，以便利用俄国革命的经验。","language":"中文","translation":false},{"id":"communism-abc-2-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"第五节 我们的纲领的科学性质","language":"中文","translation":false},{"id":"communism-abc-2-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"我们已经说过，纲领决不是从脑子里臆想出来的，而应是从实际生活中提炼出来的。在马克思以前，有些维护过工人阶级利益的人常常用神话里的情景来描绘未来的天堂，可是却不问问自己是否能够达到这一目的，他们看不到工人阶级和贫民应走的正确道路。马克思教导人们的则不是这样。他研究了迄今仍在全世界占统治地位的不公正的和野蛮的坏制度，考察了这种制度的构成情况。马克思在考察工厂主和地主占统治地位、而工农受压迫的资本主义制度时，正如我们着手考察某种机器——比方说，手表——一样。比方说，我们发现在表中有两个小齿轮咬合不好，随着每一次转动，它们磨损得越来越厉害。于是，我们可以说，这个表要坏了，要停了。马克思考察的不是钟表，而是资本主义社会。他研究它，研究资本统治下的实际生活。结果，他在这种研究的基础上看清了资本本身正在为自己掘墓，这架机器即将崩溃。它将因工人的不可避免的起义而毁灭，工人将按照自己的面貌改造整个世界。","language":"中文","translation":false},{"id":"communism-abc-2-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"马克思嘱咐自己的全体学生，首先要如实地研究真实的生活，只有这样做，才能制订正确的纲领。因此，在纲领开头叙述资本的统治是不恰当的。","language":"中文","translation":false},{"id":"communism-abc-2-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"现在，资本在俄国统治已被推翻。马克思所作的预言，正在我们眼前变成现实。旧制度正在崩溃。国王和皇帝的桂冠纷纷落地。工人到处在进行革命，到处在建立苏维埃政权。要正确地理解已经发生的事件的原因，就需要很好地了解什么是资本主义制度。这样，我们就会看出，它们要被推翻。如果我们意识到，旧的一去不复返，工人的胜利有了保证，那么，我们就能力量倍增和满怀信心地去为建立新的劳动制度而斗争。","language":"中文","translation":false},{"id":"communism-abc-2-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"书目：（1）1917年四月代表会议记录。（2）关于党纲修改的材料。（3）《斯巴达克》杂志第4——9期，布哈林和斯米尔诺夫的文章。（4）《启蒙》杂志1917年第1——2期，尼·列宁的文章。（5）第八次代表大会记录。关于马克思主义纲领的科学性问题，请看有关科学社会主义文献：哥卢勃科夫《空想社会主义和科学社会主义》。弗·恩格斯《社会主义从空想到科学的发展》。马克思和恩格斯《共产党宣言》。要了解纲领的一般性质，请看布哈林的小册子《布尔什维克共产党的纲领》。在这类文献中，只有最近哥卢勃科夫的小册子在某种程度上是通俗易懂的。其他的著作读起来比较困难。","language":"中文","translation":false},{"id":"communism-abc-2-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 我们的纲领","page":2,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/02.htm","text":"[1] 马克思主义者——伟大的学者和工人领袖卡尔·马克思的学生。","language":"中文","translation":false},{"id":"communism-abc-3-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-3-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"· 第 六 节 商品经济","language":"中文","translation":false},{"id":"communism-abc-3-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"· 第 七 节 资本家阶级对生产资料的垄断","language":"中文","translation":false},{"id":"communism-abc-3-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"· 第 八 节 雇佣劳动","language":"中文","translation":false},{"id":"communism-abc-3-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"· 第 九 节 资本主义生产关系","language":"中文","translation":false},{"id":"communism-abc-3-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"· 第 十 节 对劳动力的剥削","language":"中文","translation":false},{"id":"communism-abc-3-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"· 第十二节 资本主义国家","language":"中文","translation":false},{"id":"communism-abc-3-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"· 第十三节 资本主义制度的基本矛盾","language":"中文","translation":false},{"id":"communism-abc-3-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"假如我们仔细观察资本统治下的经济是如何进行的，那么，首先就会看到这里在生产商品。有人会问：这究竟有什么奥妙呢？这里的奥妙就在于，商品并不是简单的一般产品，而是为市场生产的产品。","language":"中文","translation":false},{"id":"communism-abc-3-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"当产品是为了生产者个人使用而生产的，它就不是商品。如果农民种黑麦，从下种、收割，然后到脱粒、磨粉和烤成面包都是为了自己食用，那这些面包就绝不是商品，它仅仅是面包而已。这些面包只有在人们开始拿它进行买卖的时候，也就是说，是为了购买者、为了市场而被生产的时候，它才成为商品。因为谁买了它，它就是谁的。","language":"中文","translation":false},{"id":"communism-abc-3-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在资本主义制度下，一切商品都是为市场生产，所以一切产品都是商品。每一个工厂或作坊通常只生产某一种产品，任何人一看就会明白，这里产品不是为了自己生产的。譬如，殡仪馆老板的作坊所制作的许多棺材，显然不是为他自己和家人准备的，而是拿到市场去卖的。再譬如，工厂主制造蓖麻油，显而易见，即使他天天需要泻肚子，他所服用的也只不过是他工厂里制出的极小部分。在资本主义制度下，不论拿哪一种产品为例，情况都不外如此。","language":"中文","translation":false},{"id":"communism-abc-3-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"纽扣厂制造纽扣，然而，生产这些成千上万的纽扣，不是为了把它们缝在纽扣厂厂主的背心上，而是为了出售。在资本主义社会里，一切产品都是为市场生产的；无论是手套、香肠、书籍、鞋油、机器，还是烧酒、面包、皮靴、枪支等等，总而言之，一切产品全都在其内。","language":"中文","translation":false},{"id":"communism-abc-3-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"商品经济必须以私有制为前提。生产商品的手工业者有自己的作坊和工具；工厂主有自己的工厂，包括所有厂房、机器和其他资产。只要有私有制和商品经济，就总会有争夺买主的斗争或卖主之间的竞争。即使没有工厂主和大资本家，而只有一些劳动手工业者，那在这些手工业者之间也会为争夺买主而进行斗争。谁最壮实、最强悍，谁有最好的工具，并且工于心计，特别是谁最能攒钱，谁就总是能占上风，能为自己争得买主，挤垮其他手工业者，自己飞黄腾达。这就是说，小生产所有制和以它为基础的商品经济已含有大生产所有制的萌芽和使很多小生产者破产的因素。","language":"中文","translation":false},{"id":"communism-abc-3-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"因此，资本主义制度的第一个特征就是商品经济，即为市场而生产的经济。","language":"中文","translation":false},{"id":"communism-abc-3-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"第 七 节 资本家阶级对生产资料的垄断","language":"中文","translation":false},{"id":"communism-abc-3-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"只用商品经济一个特征来说明资本主义还不够。可以有这样的商品经济，其中没有任何资本家：例如，劳动手工业者的经济。他们为市场生产，出卖自己的产品，他们这些产品自然是商品，因而全部生产也就是商品生产。然而，这还不是资本主义生产，内不过是简单的商品生产。要使简单商品生产转变为资本主义生产，一方面，必须使生产资料（工具、机器、厂房、土地等等）变为少数富人-资本家阶级的私有财产，另一方面，使大批的独立手工业者和农民破产，并沦为工人。","language":"中文","translation":false},{"id":"communism-abc-3-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"我们已经看到，简单的商品经济本身包含有使一部分人破产，另一部分人发财的萌芽。这已被事实所证明。在世界各国，大部分的劳动手工业者和小业主已经破产。谁破了产，谁最后就只有卖掉自己的“工具”，由小业主变为除了双手之外一无所有的人。而那些比较富的人就变得更富了，他们改建、扩大自己的作坊，安装更好的机床，然后再添置机器，开始招雇很多工人，使自己变成工厂主。","language":"中文","translation":false},{"id":"communism-abc-3-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"凡生产所需要的一切，如厂房、机器、原料、货仓、商店、房屋、工厂、矿山、铁路、轮船、土地，总之，凡是生产上不可缺少的一切，渐渐地都落到这些富翁的手里。这一切生产资料都成了资本家阶级的独有财产（或者象人们所说的，被资本家阶级所“垄断”）。一小撮富翁占有一切；广大的穷苦人只有一双劳动的手。资本家阶级对生产资料的这种垄断，是资本主义制度的第二个特征。","language":"中文","translation":false},{"id":"communism-abc-3-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"多数人的阶级，即那些没有任何财产的人变成了资本的雇佣工人。事实上破产的农民或手工业者还有什么好干的呢？他们不是被资本家-地主招雇去当长工，就是流入城市受雇于工厂。其他的出路是没有的。这样就产生了资本主义制度的第三个特征——雇佣劳动。","language":"中文","translation":false},{"id":"communism-abc-3-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"什么是雇佣劳动？在以前有农奴或奴隶的时候，第一个农奴或奴隶是可以被买卖的。这些人连同他们的皮肤、头发、脚和手都是老爷的私有财产。老爷在马厩里打死他的奴隶，就好象，譬如说，喝醉酒以后打碎一把椅子一样。农奴和奴隶只是普通的什物。在古罗马，老爷在生产上所需要的财产是这样分的：“哑吧工具”（什物），“半哑吧工具”（役畜、羊、母牛，公牛等等，一句话，就是能叫出声的牲畜）和“会说话的工具”（奴隶、人）。不论是铁锹，是牛，还是奴隶，在老爷看来都同样是工具，他可以随意买、卖、毁掉和打死。","language":"中文","translation":false},{"id":"communism-abc-3-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在雇佣劳动的情况下，人本身是不能被买卖的。能够买卖的，只是他的劳动力，不是人本身，而是人的劳动能力。雇佣工人的人身是自由的。工厂主不能在马厩里鞭打他，或者把他卖给自己的邻居，或者用他去换一只猎狗，而这在农奴制时代是可以的。工人本身仅仅是被雇用。看起来甚至资本家和工人似乎是平等的，譬如，工厂主老爷们总是这样说：“不愿意吗？那就别干，谁也不强迫你。”他们甚至断言，是他们养活了工人，给工人工作做。","language":"中文","translation":false},{"id":"communism-abc-3-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"事实上，工人和资本家显然处于完全不同的地位。工人被一条饥饿的锁链拴住，饥饿使他们不得不受人雇用，也就是出卖自己的劳动力。对于工人来说，他们没有其他出路，丝毫没有选择的余地。工人不可能赤手空拳地从事“自己的”生产；试想一下，没有机器和工具能炼钢、织布、造火车吗？在资本主义制度下，甚至所有的土地都掌握在私人手里，因而工人无处可以谋生。工人有出卖劳动力的自由，资本家有购买劳动力的自由，资本家和工人是“平等的”——这一切，实际上是一条迫使工人为资本家劳动的饥饿锁链。","language":"中文","translation":false},{"id":"communism-abc-3-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"由此可见，雇佣劳动的实质是出卖劳动力，或者说是把劳动力变为商品。在前面说过的简单商品经济中，在市场上可以看到牛奶、面包、布匹、皮鞋等等，但不可能看到劳动力。那时劳动力是不出卖的。劳动力的所有者、手工业者，除了劳动力之外，还拥有房屋和工具。他们自己劳动、从事自己的劳动经营，即在自己的经营中使用他们自己的劳动力。","language":"中文","translation":false},{"id":"communism-abc-3-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在资本主义制度下则完全是另一种情形。在这里，做工的人没有生产资料，他们不可能在自己的经营中使用自己的劳动力。为了不致饿死，他们就必须把劳动力出卖给资本家。因此，在卖棉花、干酪或机器的市场之外，也有一个劳动市场，无产者、即雇佣工人，在这里出卖自己的劳动力。所以，资本主义经济与简单商品经济的区别，就在于在资本主义经济中，劳动力本身也成为商品。","language":"中文","translation":false},{"id":"communism-abc-3-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"因此，雇佣劳动是资本主义制度的第三个特征。","language":"中文","translation":false},{"id":"communism-abc-3-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"第 九 节 资本主义生产关系","language":"中文","translation":false},{"id":"communism-abc-3-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本主义制度的三个特征是：为市场生产（商品生产）；资本家阶级对生产资料的垄断；雇佣劳动，即建立在出卖劳动力基础上的劳动。","language":"中文","translation":false},{"id":"communism-abc-3-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"这些特征涉及到人们在产品生产和分配中的相互关系问题。当人们说“商品经济”或者“为市场生产”的时候，是指什么呢？这是说，人们互为对方劳动，但是，每个人在其经济中是只为市场生产，事先并不知道谁要购买他的商品。假设说，我们这里有一个手工业者伊万诺夫和一个农民西多罗夫，手工业者伊万诺夫把他做好的皮鞋拿到市场上，卖给西多罗夫，又用得到的钱从西多罗夫那里买了面包。当伊万诺夫来到市场时，他并不知道在那里会碰到西多罗夫，而西多罗夫也不知道在那里会碰到伊万诺夫，这两个人都不过是到市场来。当伊万诺夫买了面包，而西多罗夫买了皮鞋的时候，才发生了西多罗夫为伊万诺夫做工，而伊万诺夫为西多罗夫做工这样的事，只是这不会一下子看出来。市场上的熙熙攘攘的人群向人们掩盖了他们相互为对方做工，谁离开谁都有不能活这个实质。在商品经济的情况下，人们互为对方劳动，但是，是无组织地、各自独立的，他们自己并不知道相互间的需要量是多少。所以，人们在商品生产中是以一种特殊的方式被分开，并且又互相处在一定的关系中。这里所说的就是人与人之间的关系。","language":"中文","translation":false},{"id":"communism-abc-3-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"当谈到“生产资料的垄断”或者“雇佣劳动”时，同样也是说的人与人之间的关系。这种“垄断”事实上是什么意思呢？这里的意思就是说，人们的劳动是在这样一种条件下进行的：这些做工的人是用别人的生产资料进行劳动；劳动者得听从于这些生产资料的所有者，即资本家的，等等。一句话，这里说的也是人们在生产产品时，相互处于什么样的关系。人与人在生产时（在生产过程中）所处的这种关系就叫做生产关系。","language":"中文","translation":false},{"id":"communism-abc-3-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"不难看出，生产关系绝不是永远一样的。在远古时代，人们曾经生活在小公社中，一起共同劳动（打猎、捕鱼、摘野果和挖菜根），然后大家彼此平分。这是一种生产关系。在奴隶制时代，是另一种生产关系。在资本主义制度下，则又是一种，其余以此类推。可见。存在着各种形式的生产关系。生产关系的这些形式，就叫做社会的经济构成（结构）或者生产方式。","language":"中文","translation":false},{"id":"communism-abc-3-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"“资本主义的生产关系”，即“资本主义的社会结构”，或者说，“资本主义的生产方式”——这就是在商品经济的情况下，在一小撮资本家垄断生产资料和工人阶级的雇佣劳动的情况下，人与人之间的关系。","language":"中文","translation":false},{"id":"communism-abc-3-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"第 十 节 对劳动力的剥削","language":"中文","translation":false},{"id":"communism-abc-3-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"有一个问题：资本家阶级为什么要雇佣工人？任何人都知道，这绝不是因工厂主愿意养活饥饿的工人，而是因为他们要从工人身上榨取利润。为了利润，工厂主才兴建自己的工厂，为了利润，才雇佣工人，为了利润，他们到处探寻能高价出售商品的地方。利润成了他们一切盘算的动机。这也是资本主义社会非常有趣的特点。在这里，并不是社会本身生产它所需要的和有用的商品，而是资本家阶级强迫工人去生产那些能卖更大价钱，能获取更大利润的商品。例如，烧酒是很有害的东西，酒精本来可以只为工业和医药上的应用目的而生产。然而，全世界的资本家却在拼命地生产酒精。为什么？因为从人民的狂饮中能获得更大的利润。","language":"中文","translation":false},{"id":"communism-abc-3-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"可是，我们需要弄清楚，资本家是怎样得到这些利润的。为此，我们要更详细地分析这个问题。资本家只有在卖掉他工厂里生产的商品之后，才能获得货币形式的利润。卖掉自己的商品他能得多少钱呢？这取决于商品的价格。现在又产生一个问题：这个价格是由什么决定的？为什么一种商品价格高，另一种商品价格低呢？不难发现，如果任何一种生产引进了新的机器，那里的劳动就变得更有成效了，或者象人们说的那样，变得更有生产效率，那么，商品的价格就会降低。反之，如果生产困难，生产的商品少，劳动成效低或是生产效率不高，那么商品的价格就会提高[1]。为制造一种商品，社会平均需要花费的劳动多，商品的价格就高；花费的劳动少，价格就低。在中等技术水平的情况下（就是说，不是用最好的，也不是用最坏的机器和工具），商品生产花费的社会劳动量称为这种商品的价值。现在我们可以看出，价格取决于价值。实际上，价格有时高于价值，有时低于价值，但是，为了简便起见，我们可以认价格和价值是一个东西。","language":"中文","translation":false},{"id":"communism-abc-3-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"现在让我们回想一下我们说过的雇用工人问题。雇用工人——这是用来出售的一种特殊商品，其名称就叫做劳动力。既然劳动力成为商品，那么，一切对商品适用的东西，对劳动力也适用。俗语说，“既是名为蘑菇，就应听人采食”。资本家在雇用一个工人时，他就把工人的劳动力价格（或者简单地叫劳动力价值）付给工人。这个价值是由什么决定的呢？我们知道，一切商品的价值，取决于在生产它们时所花费的劳动量。这一点也适用于劳动力。","language":"中文","translation":false},{"id":"communism-abc-3-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"但是，劳动力是怎样生产的呢？要知道劳动力不是在工厂里生产的，因为它不是麻布、不是鞋油、也不是机器。这究竟怎样理解呢？要明白是怎么回事，只要看一下资本主义制度下的真实生活就行了。现在这样假设：工人们刚刚结束了工作。他们精疲力竭，已不能再做工了。他们的劳动力几乎消耗完了。要恢复他们的劳动力，需要什么呢？需要吃喝、休息、睡觉，维持他的身体，以便“恢复自己的精力”。只有这样，才会有继续做工的可能和能力，或者说才会有劳动力。就是说，食品、衣服、住房等等，一句话，工人的消费就是劳动力的生产。另外，如果是受过专门训练的工人，这里还包括有象学习费这样的一些费用，等等。","language":"中文","translation":false},{"id":"communism-abc-3-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"工人阶级为了恢复自己的劳动力所消费的一切都具有价值。所以，消费品的价值，以及学习费用就构成了劳动力的价值。不同的商品具有不同的价值。同样，不同类型的劳动力也具有不同的价值。地形测绘员的劳动力价值是一种，而粗活工人的劳动力价值则是另一种。","language":"中文","translation":false},{"id":"communism-abc-3-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"现在，我们再回头看看工厂。资本家购买原料、工厂用的燃料、机器、机油和其他必需物品；然后他购买劳动力，即“雇用工人”。这一切他都付了现钱。生产开始了。工人在做工，机器在转动，燃料在燃烧，机油在消耗，厂房在损坏，劳动力在消耗。但是，从工厂里造出了一种新的商品。这种商品象所有的商品一样，具有价值。这个价值是多少呢？第一，它包含已消耗的生产资料的价值，这里包括：使用的原材料，消耗的燃料，机器的磨损部分等等。这一切现在都算进商品的价值。第二，再加上工人的劳动。如果三十名工人花费了三十个小时制出了一件商品，那么，他们就是花费了九百个工作小时，就是说，出产的商品的总价值是由消耗的材料的价值（比方说，这个价值等于六百个小时）和工人用自己劳动增加的新价值（九百小时）构成的，也就是（六百加九百）等于一千五百工作小时。","language":"中文","translation":false},{"id":"communism-abc-3-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"但是，资本家自己为这个商品究竟付出了多少呢？他已全部支付了原料的费用，就是说，他已支付了与六百个工作小时的价值相等的全部款额。但是劳动力的费用呢？他是否全部支付了九百个小时呢？整个事情的谜正在于此。根据我们的假设，他支付了工作日的劳动力的全部价值。如果三十名工人工作了三十个小时，每天十小时，共三天，那么，工厂主付给他们的，只是这几天为恢复他们的劳动力所必需的钱。这笔钱是多少？答案是清楚的：它大大少于九百小时。为什么呢？因为维持我的劳动力而需要的劳动量是一回事，我能够达到的劳动量度则是另一回事。我一天工作十小时。而每天我所需要的吃、穿等等，仅仅等于五小时的价值。就是说，我的劳动，比起为维持我的劳动力而进行的劳动要更多。譬如说，在我们举的例子中，工人们三天内为吃、穿等所花掉的产品价值是四百五十个小时，而他们提供了九百个小时的劳动，其余的四百五十个小时就归资本家了。这四百五十个小时就是他的利润来源。实际上，正如我们所见，对于资本家来说，商品的价值等于一千零五十小时（六百加四百五十），而他却以一千五百小时（六百加九百）的价值出卖商品；其中的四百五十小时就是劳动力所创造的剩余价值。可见，工人的二分之一劳动时间（在十小时工作日的情况下，有五个小时）是为抵偿他们自己的消费，而另外的二分之一劳动时间，则完全是为资本家。","language":"中文","translation":false},{"id":"communism-abc-3-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"我们现在看一下整个社会。要知道，我们对个别工厂主，或者个别工人干什么并不感兴趣。我们感兴趣的是，资本主义社会——这台巨大的机器是如何构成的。资本家阶级雇用人数众多的工人阶级。亿万工人在几百万个工厂、矿山、森林、田野里，象蚂蚁一般地劳动。资本家付给他们工资，也就是他们的劳动力的价值，以便不断恢复其劳动力好继续为资本家服务。但是，工人阶级通过自己的劳动不仅养活自己，而且创造上层阶级的收入，创造剩余价值。这些剩余价值通过千百条渠道流入统治者的腰包。其中：一部分归资本家本人——这是企业主的利润；一部分归地主，归土地所有者；一部分以税收的形式归资本主义国家；一部分归商人、小贩、小店主、教堂、妓院、演员和小丑、资产阶级下流作家等等。资本主义制度所滋生的一切寄生虫，都凭借这些剩余价值而生活。","language":"中文","translation":false},{"id":"communism-abc-3-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"但是，还有一部分剩余价值被资本家重新投放到事业中去。他们把它归入自己的资本中，使资本增加了。他们扩大自己的企业，雇用更多的工人，添置更好的机器。更多的工人给他们创造更多的剩余价值。资本家的企业再次发展和扩大。这样，随着每一次的循环，剩余价值不断积累，资本也就越来越大。通过从工人阶级身上榨取剩余价值，剥削工人阶级，资本的数量才不断地增加。","language":"中文","translation":false},{"id":"communism-abc-3-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"现在我们已经清楚地看到了什么是资本了。首先，资本，不论其形式是货币，是机器、原料、厂房，还是制成的商品，都具有一定的价值。但是这种价值是用来为生产新的价值，生产剩余价值服务的。资本是生产剩余价值的价值。资本主义生产是剩余价值的生产。","language":"中文","translation":false},{"id":"communism-abc-3-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在资本主义社会，机器和厂房都是资本。但是，机器和厂房是否永远都是资本呢？当然不会。如果整个社会的经济都是协作经济，如果它是为自己而生产的，那么，不论是机器，还是原料，都不能算是资本，因为它们不是为少数富人榨取利润的工具。这就是说，机器只有在被资本家阶级私人占有时，并被作为剥削雇佣劳动和生产剩余 价值的条件时，才成为资本。在这里，价值的形式并不重要；这种价值可能表现为金币形式，也可能表现为纸币形式，工人用它们来做工，也可能表现为原料的形式，工人们用它们制造出商品，也可能表现为制成的商品的形式，以后再把它卖掉。但是既然这种价值是用于生产剩余价值的，所以它就是资本。","language":"中文","translation":false},{"id":"communism-abc-3-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本常常脱掉一种外壳和穿上另一种外壳。确实如此，我们且看这一过程是怎样完成的。","language":"中文","translation":false},{"id":"communism-abc-3-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"1．资本家还没有买到劳动力和生产资料。但是，他极希望雇用工人、置备机器、弄到上等的原料和煤炭，以便能够开工生产，等等，暂时他手里除了钱之外，还什么都没有。在这里，资本表现为货币形式。","language":"中文","translation":false},{"id":"communism-abc-3-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"2．资本家带着这笔钱来到市场（自然不是他自己去；为此有电话和电报，许许多多的奴仆等等）。在这里购买了生产资料和劳动力。资本家回到工厂，钱是没有了，但是却有了工人、机器、原料、燃料。现在所有这些东西已经不是商品了。它们不再是商品，因为不再把它们拿到市场去出卖了。钱变成了生产资料和劳动力，货币的形式去掉了，现在，出现在我们面前的是工业资本的形式。","language":"中文","translation":false},{"id":"communism-abc-3-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"接着开始工作。机器开动了，轮子旋转起来，操纵杆在来回搬动，男女工人汗如雨下，机器在磨损，原料在消耗，劳动力在耗尽。于是，","language":"中文","translation":false},{"id":"communism-abc-3-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"3．所有这些原料，机器的磨损部分，提供劳动的劳动力，慢慢地变成了一堆堆商品。这里资本又脱离了工厂原有的实物形式，而以一堆商品形式出现。这就是商品形式的资本。然而，经过生产之后，资本不但改变了自己的外形，而且还增加了自己的价值。因为在生产中，又多出了剩余价值。","language":"中文","translation":false},{"id":"communism-abc-3-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"4．但是，资本家强迫生产商品并不是为了自己使用，而是为了市场，为了出卖。堆积在他的工厂仓库里的货物一定要卖出去。起初，资本家是以买主的身份到市场去。现在，他应当以卖主的身份去。起初，他手里拿的是钱，他想得到的是商品（生产资料）。现在，他手里拿的是商品，他想得到的是钱。一旦他的商品被卖掉了，那么，资本就从它的商品形式再次跳到货币形式。然而，资本家得到的货币数量，已经不同于他当初付出去的数量了，因为外加了整个剩余价值的数量。","language":"中文","translation":false},{"id":"communism-abc-3-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本的运动并没有到此结束。增加了的资本再次周转，获得了更大数量的剩余价值。这些剩余价值的一定部分并入资本，又开始新的周转，如此等等。资本象一个雪球，越滚越大，随着每一次的滚动，剩余价值越来越多。这就是说，资本主义生产不断地发展和扩大。","language":"中文","translation":false},{"id":"communism-abc-3-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本就是这样从工人阶级身上榨取剩余价值和到处扩散的。资本之所以能迅速增长，是因为其特殊的属性。当然，一个阶级剥削另一个阶级的现象以前就有了。可是我们拿农奴制时的地主或奴隶制时的奴隶主为例。他们骑在他们的农奴和奴隶的头上作威作福。农奴和奴隶生产的一切东西都被地主、奴隶主自己，或被他们的仆从和大量的食客吃光、喝掉和穿光了。那时商品生产还很不发达，商品也没有地方去卖。就是说，如果地主或奴隶主强迫自己的农奴和奴隶生产出堆积如山的面包、肉、鱼等等，那么，他们的这些东西就会烂掉。那时的生产只以地主及其奴仆们的肚皮需要为限。而在资本主义制度下则完全是另一种情形。这里的生产不是为了满足需要，而是为了利润。这里生产商品，是为了出卖，为了赚钱，为了积累利润。利润越多越好。因此，资本家阶级疯狂地追求利润。这种欲望是无止境的。它是资本主义生产的轴心，是主要的推动力。","language":"中文","translation":false},{"id":"communism-abc-3-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"我们知道，资本主义国家是建立在剥削工人阶级的基础之上的。少数人占有一切，而大多数人一无所有。资本家发命令，工人俯首听命。资本家剥削，工人被剥削。资本主义社会的全部实质也就在于这种无情的、不断加重的剥削。","language":"中文","translation":false},{"id":"communism-abc-3-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本主义生产——这是一台榨取剩余价值的压缩机。","language":"中文","translation":false},{"id":"communism-abc-3-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"这台压缩机暂且是怎样维持下去的呢？工人们怎能忍受这种状况呢？","language":"中文","translation":false},{"id":"communism-abc-3-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"要立即回答这个问题是很困难的。但是，一般说来问题有两个原因：第一、资本家掌握有组织和暴力；第二、资产阶级时常控制着工人阶级的大脑。","language":"中文","translation":false},{"id":"communism-abc-3-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在这方面，国家组织是资产阶级最可靠的工具。在所有资本主义国家里，国家都有无非是雇主的联盟。我们可以拿随便一个国家为例，不管英国或美国，法国或日本，充当部长、高级官员、议员的，总是那些资本家、地主、工厂主、银行家及其忠实的、享受高薪的、死心塌地为他们服务的奴仆，其中有律师、银行经理、教授、将军、高级僧侣和主教。","language":"中文","translation":false},{"id":"communism-abc-3-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"隶属于资产阶级的这些人的联盟，囊裹着整个版土，并把它死死抓在自己手里。这个联盟也就叫做国家。资产阶级的这个组织有两个目的：主要的目的是镇压工人的骚动和起义，保证安稳地从工人阶级身上榨取剩余价值，促进资本主义生产方式的巩固；第二个任务是同别的组织（即其他资产阶级国家）为瓜分榨取来的剩余价值而争斗。总之，资本主义国家是保护剥削制度的雇主联盟。资本的利益，只有资本的利益——才是这个强盗联盟的全部活动的准则。","language":"中文","translation":false},{"id":"communism-abc-3-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"对于资产阶级国家的这种看法，可能有人提出这样的异议，你们说国家的出发点完全是为了资本的利益。可是请看，所有的资本主义国家都有工厂法，该法禁止或限制童工劳动，比以前缩短了工作日等等；例如，在德国，还有在威廉二世时，工人的国家保险就相当不坏了；在英国，正是好战的资产阶级首相劳合-乔治建立了保险金和老年人的退休金制度，在所有资产阶级国家中都为工人修建了各种医院和诊疗所；建筑起不论富人还是穷人都能享用的铁路；城市中安装了自来水设备、修筑了下水管道等等。这些东西所有的人都能享用。还有人说，这就意味着，即使在那些资本统治地位的地方，国家也仍然不只是着眼于资本的利益，而且也着眼于工人的利益。国家甚至有时对那些违反工厂法的工厂主处以罚款。","language":"中文","translation":false},{"id":"communism-abc-3-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"这种异议是错误的。道理如下。确实，资产阶级政权可能有时颁布对工人阶级也有利的法律和命令。然而，这样做是为了资产阶级自身的利益。千真万确。我们举铁路为例。工人们也乘坐火车，所以铁路也有利于工人。但是，建筑铁路并不是为了工人、商人、工厂主需要铁路，是为了运输他们的商品，转运货物、调动军队，运送工人等等。资本需要铁路——它是出自自身的利益。铁路固然对工人也有利，但是，资本主义国家建筑铁路并不是由于这个原因。我们再拿城市卫生，即所谓“城市公用事业”和医院为例。在这里，资产阶级也关心到了工人住宅。的确，同市中心的资产阶级住宅相比，城边的工人区很肮脏，一片荒凉，疾病丛生等等。但是，资产阶级毕竟还是做了一些事情。为什么？因为否则疾病和瘟疫就会漫延全城，连资产阶级自己也会被传染。可见，在这里，资产阶级国家及其市政机关根据的是资产阶级自己的利益。再举一个例子。","language":"中文","translation":false},{"id":"communism-abc-3-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"法国近几十年来，工人从资产阶级那里学会了人工节制生育：或者完全不生孩子，或者不多于两个。工人们极端贫困。以致很难或者根本不可能养活大的家庭。结果，法国的人口几乎没有增长。法国资产阶级感到兵员不足了。它大声疾呼：“民族要灭亡了！德国人口增长比我们快！他们的士兵要比我们多！”顺便说说，即使参军的那些士兵，也是一年比一年糟糕：身材矮小，肺部虚弱，气力单薄。于是资产阶级“顿时慷慨起来”：亲自起来坚决主张为工人阶级进行某些改善，使之恢复一下元气，多生一些孩子。要知道，如果把母鸡杀了，那它就再也不会生蛋了。","language":"中文","translation":false},{"id":"communism-abc-3-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"从所有这些例子看，资产阶级本身虽然采取了一些有益于工人的措施，但这里却是从自己的利益出发的。常常也有另外一些情况，即这些有益的措施是资产阶级国家在工人阶级的压力下被迫采取的。这样的法律多得很，几乎所有的“工厂法”都是通过这种方式——工人的威胁行动，——得来的。英国每一次缩短工作日——到十小时——是在工人的逼迫下达到的。俄国第一批工厂法，是沙皇政府在工人骚动和罢工的要挟下颁布的。这里，这个工人阶级的敌人的国家，即这个雇主的组织，出于自己的利益盘算着：“与其明天退让两步，或者拿自家性命冒险，倒不如今天先退让一步的好。”工厂主也完全如此，他向罢工者让步，并给工人多加几个微不足道的戈比，这样他仍然还是工厂主；资产阶级国家也完全如此，在工人骚动的威胁下，它会抛出几根小骨头，但这丝毫不会改变它的资产阶级性质。","language":"中文","translation":false},{"id":"communism-abc-3-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本主义国家不仅是资产阶级最大和最强有力的组织，同时也是最复杂的组织。它拥有数量众多的部门，它的触角通过这些部门伸向四面八方。所有这一切，主要目的就是为了保护、加强和扩大对工人阶级的剥削。为了对付工人阶级，还备有暴力工具和精神奴化工具，这些东西也就组成了资产阶级国家最重要的机关。","language":"中文","translation":false},{"id":"communism-abc-3-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在暴力工具中首先必须指出的是军队、警察和宪兵、监狱和法庭，以及它们的各式各样的附属机构：特务、奸细、工贼组织和雇用刺客的组织等等。","language":"中文","translation":false},{"id":"communism-abc-3-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在资本主义国家，军队是按照一种特殊的方法组建的。最上层是军官团——“佩带金肩章的人”。他们是由贵族地主的、大资产阶级的和部分知识分子的子弟组成。这是些无产阶级的凶恶的阶级敌人，这些人从小就在特设的学校里（我国是在武备中学和士官学校）学习：如何打士兵的嘴巴，如何保护“礼服的荣誉”，也就是说，使士兵完全成为奴隶和任意支使的小卒。贵族、地主和大资产阶级中的怙恶不悛的分子成了佩有官衔、勋章和缓带的将帅。","language":"中文","translation":false},{"id":"communism-abc-3-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"一般军官也不是穷人出身。他们把所有士兵群众都控制在自己手里。士兵被训练成不问他们是为什么打仗，而只会按“长官的眼神”行事的人。这样的军队，首先就是用来镇压工人的。","language":"中文","translation":false},{"id":"communism-abc-3-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在俄国，沙皇的军队不止一次地充当了镇压工农的工具。在亚历山大二世时，农民还没有被解放以前，发生了很多次农民暴动，都被军队镇压了。在1905年军队镇压了莫斯科起义的工人；它在波罗的海沿岸边疆区、高加索、西伯利亚进行了讨伐性的远征；1906——1908年，它为了保护地主的财产等等，镇压了农民反抗地主的暴动。战争期间，军队开枪射杀了伊万诺沃-沃兹涅先斯克和科斯特罗马等地的工人。军官和将军在各地尤其作恶多端。在外国也是这样的情况。在德国，资本主义国家的军队也是杀害工人的刽子手。第一次水兵起义就是被军队镇压下去的。柏林、汉堡、慕尼黑，以及遍及全德国的工人起义均被军队镇压。在法国，军队曾不止一次枪杀罢工者，现在又在枪杀工人和俄国的革命士兵。在英国，仅仅最近一个时期，军队就把爱尔兰的工人、半奴隶的埃及人和印度人的起义多次置于血泊之中，并捣毁了英国本土的工人集会。在瑞士，每一次罢工，机枪队和所谓民警队（瑞士军队）都动员起来；这批民警队不止一次地向无产者们开枪。在美国，军队常常把整个工人住宅区放火烧光，夷为平地（例如，在科罗拉多的罢工时期）。资本主义国家的军队现在正合伙扼杀俄国、匈牙利、巴尔干、德国等地的工人革命，镇压全世界的起义。","language":"中文","translation":false},{"id":"communism-abc-3-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"警察和宪兵。资本主义国家除了普通的军队以外，还有一支精选的骗子军队和受过特别训练的部队，专门用于对付工人。不错，这些机关（例如，警察局）也有其同盗贼斗争和保护所谓“公民人身和财产安全”的任务；可是，资本家的国家豢养它们，同时也是为了捕捉、迫害和惩办那些心怀不满的工人。在俄国，警士是地主和沙皇最可靠的保卫者。在所有资本主义国家，特别凶恶的是秘密警察（“政治警察”，我们称为暗探局）和宪兵团。和它们一起工作的全体人员有侦探、奸细、秘密间谍、工贼等等。","language":"中文","translation":false},{"id":"communism-abc-3-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"在这方面，美国秘密警察的手段是很值得注意的。他们同无数的私人或者半官方的“侦探局”联系在一起。纳特·平克顿的著名奇遇，实际上是向工人进攻。密探常常把炸弹偷偷塞给工人领袖，并煽动他们去暗杀资本家等等。同时这些密探经常招募大批工贼（在美国被称为破坏罢工者）和武装的暴徒，遇有机会就去杀害罢工工人。这伙暴徒充当美国资本家的“民主”国家的走狗，他们什么卑鄙行为都会干得出来！","language":"中文","translation":false},{"id":"communism-abc-3-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资产阶级国家的法庭是资产阶级自卫的工具；它首先为了镇压那些企图危害资本家所有制和资本主义制度的人。这种法庭判决李卜克内西服苦役，并宣告杀害李卜克内西的凶手无罪。和资产阶级国家的刽子手一样，国家监狱部门也是搞这种镇压的。它们的刀刃不是对着富人，而是对着穷人。","language":"中文","translation":false},{"id":"communism-abc-3-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"这就是资产阶级国家专门直接残暴镇压工人阶级的部门。","language":"中文","translation":false},{"id":"communism-abc-3-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本家国家掌握着各种用来对工人阶级实行精神奴役的工具，其中应该指出的有三点：国立学校、国立教堂，以及国家或由国家扶持的出版事业。","language":"中文","translation":false},{"id":"communism-abc-3-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资产阶级完全懂得，单凭赤裸裸的暴力是制服不了工人群众的，还需要一张巧妙的蛛网从各方面把工人的头脑束缚住。资产阶级国家把工人看作役畜一般：必须叫这头役畜干活，但不能叫它咬人。因此，不但要在它咬人的时候抽打它和枪毙它，而且要训练它，就象动物园的专门人员驯化野兽一样。资本家国家同样培养了一批从事愚弄、麻醉和驯化无产阶级的专家，如，资产阶级教师和教授、牧师和主教，资产阶级的文痞和办报人。在学校里，这些专家教育儿童从小就养成拭目以对资本的服从心理，鄙视和憎恨“暴乱分子”；向孩子们讲述各种诽谤革命和革命运动的故事，赞扬沙皇、国王和工业家等等；领取国家薪水的教堂牧师向人们宣扬的圣训是：“一切权力来自上帝”；资产阶级报纸天天都在人们耳边灌输资产阶级的谎言（资本主义国家通常禁止出版工人的报纸）。在这种情况下，难道工人能轻易地跳出这个泥坑吗？一个德国帝国主义强盗写道：“我们不但需要士兵的又脚，而且需要他们的心灵。”资产阶级国家正力图把工人阶级训练成驯服的牲畜，要他们就象马那样干活，既能生产剩余价值，又能安分守己。","language":"中文","translation":false},{"id":"communism-abc-3-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本主义制度就是这样保证自身的进程的。剥削的机器不停地转动。不断地从工人阶级身上榨取剩余价值。而资本主义国家则站在保卫者的岗位上，时刻监视和提防着雇佣奴隶的暴动。","language":"中文","translation":false},{"id":"communism-abc-3-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"第十三节 资本主义制度的基本矛盾","language":"中文","translation":false},{"id":"communism-abc-3-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"现在有必要看一看，资本主义社会即资产阶级社会的结构究竟好还是不好。任何一件东西，只有在它的各个部分都互相配合得十分严密时，才是坚实和完好的。我们拿钟表的机械为例。只有每一个齿轮互相咬合得在一起时，表才能准确无误地走动。","language":"中文","translation":false},{"id":"communism-abc-3-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"现在来看一下资本主义社会。在这里，我们不难发现，这个资本主义社会在结构上远不是象想象的那样坚固。相反，它包含着巨大的矛盾，有着巨大的裂痕。首先，资本主义制度下缺乏有组织的产品生产和分配，只有“生产的无政府状态”。这是什么意思？这就是说，每一个企业家、资本家（或资本家同盟）在生产商品时是互不通气的。工厂主强迫工人生产不是看整个社会需要什么，而仅仅是盘算着获取更多的利润和在市场上打败自己的竞争者。因此有时商品生产得过多（当然说的是战前时期），找不到销路（工人买不起，因为没有足够的钱）。于是就出现危机：工厂倒闭，工人流落街头。生产的无政府状态也引起了市场的斗争：每一个人都想夺走别人的所有买主，把他们引诱过来，自己独占市场。这种竞争采取了各种各样的形式，从两个工厂主之间的斗争开始，一直到资本主义各国为在全世界瓜分市场而发动世界大战为止。这里，资本主义社会的一些组成部分不但相互牵扯着，而且相互直接冲突着。","language":"中文","translation":false},{"id":"communism-abc-3-77","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":77,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"因此，生产的无政府状态是资本主义第一个基本的不协调性，这一点已在危机、竞争和战争上表现出来。","language":"中文","translation":false},{"id":"communism-abc-3-78","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":78,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本主义社会第二个基本的不协调性是它的阶级结构。要知道，资本主义社会实质上不是一个社会，而是两个社会：一个是资本家，另一个是工人和贫民。二者处于经常的、不可调和的、无休止的敌对之中，这种敌对叫做阶级斗争。在这里，我们又一次看到，资本主义社会各种不同部分不但互不配合，反而彼此处于不断的冲突之中。","language":"中文","translation":false},{"id":"communism-abc-3-79","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":79,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"资本主义不会毁灭？对这个问题的回答取决于这样一点。我们在研究资本主义的发展时，即在研究资本主义如何随着时间的推移而变化时，如果我们发现它的不协调性变得越来越少，那我们就可以祝它还能长命百岁；相反，如果我们发现随着时间的推移，资本主义社会的某些部分不可避免地、越来越剧烈地互相排挤，这个社会里的裂痕将不可避免地变为深不可测的鸿沟，那我们变可以祝它“寿终正寝”了。","language":"中文","translation":false},{"id":"communism-abc-3-80","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":80,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"这就是说，必须研究资本主义发展的问题。","language":"中文","translation":false},{"id":"communism-abc-3-81","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":81,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"第一章书目：亚·波格丹诺夫《经济学简明教程》。卡·考茨基《卡尔·马克思的经济学说》，《爱尔福特纲领》。尼·列宁《国家与革命》。弗·恩格斯《家庭、私有制和国家的起源》，《社会主义从空想到科学的发展》。","language":"中文","translation":false},{"id":"communism-abc-3-82","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第一章 资本主义制度","page":3,"paragraph":82,"url":"https://www.marxists.org/chinese/bukharin/1919/03.htm","text":"[1] 在这里，我们没有谈价格变动对货币的依赖性，不管货币是多是少，是金币还是纸币。这些变动可能很大，但这样一来它就会立刻影响一切商品，而这一点并不能解释一种商品和另一种商品在价格上的区别。例如，发行大量的纸币会使各地的物价暴涨。但是，这种普遍的物价昂贵并不能说明为什么这一种商品比那一种商品贵。","language":"中文","translation":false},{"id":"communism-abc-4-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-4-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"第二章 资本主义制度的发展","language":"中文","translation":false},{"id":"communism-abc-4-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"· 第十四节 小生产与大生产的斗争","language":"中文","translation":false},{"id":"communism-abc-4-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"· 第十五节 无产阶级的依附地位，劳动后备军，女工和童工劳动","language":"中文","translation":false},{"id":"communism-abc-4-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"· 第十六节 生产的无政府状态，竞争，危机","language":"中文","translation":false},{"id":"communism-abc-4-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"· 第十七节 资本主义的发展和阶级（阶级矛盾的尖锐化）","language":"中文","translation":false},{"id":"communism-abc-4-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"· 第十八节 资本的积聚和集中是共产主义的条件","language":"中文","translation":false},{"id":"communism-abc-4-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"第十四节 小生产与大生产的斗争","language":"中文","translation":false},{"id":"communism-abc-4-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"（一）小生产和大生产在工业中的斗争。拥有上万名工人和设有巨大而奇异的机器的大工厂并不是一向就有的。它们的出现是逐渐的，并且在几乎完全破产的手工业和小工业的残骸上发展起来的。要明白为什么会发生这种情况，首先必须注意到这样一种情况，即在私有制和商品经济的条件下，争夺买主的斗争即竞争是不可避免的。在这场斗争中谁能得胜呢？谁能把买主拉到自己一边，并且使他离开自己的竞争者（对手），谁就是胜利者。而要能把买主拉到自己一边，主要靠的是使自己的商品价格更加便宜[1]。而谁又能以更便宜的价格出卖商品呢？这就是需要首先回答的问题。很明显，大工厂主比小工厂主或手工业者能以更便宜的价格出卖商品，因为他的商品价值比较低。大生产在这里具有大量的优越性。首先，大生产的优越性在于，企业资本家能够装备较好的机器，使用较好的工具和各种器械。手工业者、小业主的日子很难过，一般都用手摇机床干活，他们连想都不敢想那些先进的大机器，因为他们没有添置机器的这笔钱。小资本家也同样没有力量采用最新式的机器。因此，企业越大，技术就越完备，劳动就越有成效，厂主在制造每一件商品上的花费也就越少。","language":"中文","translation":false},{"id":"communism-abc-4-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在美国和德国的大工厂里，甚至有自己的科学实验室，经常进行各种新的发明，并且把科学同生产结合起来。这些发明属于本企业的秘密，只供本企业享用。在小生产和手工劳动的情况下，几乎事件产品都是由同一个工人来做；在用机器劳动和很多工人的情况下，一个工人只做产品的一部分，另一个工人做第二部分，第三个做第三部分，等等。这样，工作进展就会大大加快（这就叫分工）。这方面的优越性如何，在1898年的一份美国的调查材料中已早有说明。下面就是这份材料。制造十个犁。手工方式制做：总共用两个工人，干十一种不同的工作，共用了一千一百八十个小时，得到五十四美元。用机器制做同样的东西，有五十二个工人，分九十七种工作（工人愈多，工作的分类就越多）：工作了三十七个小时二十八分钟，得到七点九美元（可见时间花费少得多，劳动价值也便宜得多）。制造一百个钟表齿轮。手工方式制做：有十四个工人，分四百五十三种工作，用了三十四万一千八百六十六个小时，得到八万零八百二十二美元。机器制做：有十个工人，分一千零三十八种工作，用了八千三百四十三小时，得到一千七百九十九美元。织五百码方格布。手工方式：有三个工人，分十九道工序（不同的工作），用了七千五百三十四个小时，得到一百三十五点六美元。用机器：有二百五十二个工人，分四十三道工序，用了八十四小时，得到六点八一美元。这类的例子是可以举出很多的。除此之外，很多生产部门，如机车、战舰的制造和采矿业等等，只有依靠高度的技术才能管理，这是小企业主和手工业者所完全办不到的。","language":"中文","translation":false},{"id":"communism-abc-4-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"大生产在各方面都能节省，如厂房、机器、原料、照明和取暖、劳动力、废物利用等等。确实，我们假设以一千个小作坊和一个与这些小作坊生产能力相等的大工厂来比较，建设一座大而好的厂房要比建一千座小的要容易；原料分散在一千个小作坊里损耗就比较大（丢失、浪费等等）；一个大工厂的照明和取暖比一千个小屋子更容易解决；诸如收拾、打扫、守卫、维修等等也比较容易。一句话，大工厂里在各方面都比较经济节省。","language":"中文","translation":false},{"id":"communism-abc-4-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在购买原材料和生产上所必需的一切物品时，大经济也处在有利的地位。按批发价购买商品比较便宜，而且质量更优良；况且大工厂主很了解市场，知道在哪里购买更便宜。同样，小企业在出卖它的商品时总是吃亏。大工厂主不但很了解什么地方能高价出售（为了这个目的，他拥有自己的跑外代表，他经常与交易所打交道，在这儿收集各种商品销路的情报，他几乎与全世界都有联系）；除此之外，他还能够等待时机。譬如，如果他的商品现在价格低，他可以把这种商品放在仓库里存起来，等价格上涨以后再拿出来卖。小业主就不可能这样做。他靠卖东西为生。他一卖掉商品，就立即拿所得到的钱来维持生活，因为他没有剩余。所以他无论如何也必须把商品卖掉，否则他就要饿死。很清楚，他会因此而受到很大的损失。","language":"中文","translation":false},{"id":"communism-abc-4-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"此外，大生产还具有一个优越性：信贷。如果大企业家急需要钱的话，他随时都能借到。无论哪家银行总是愿意把钱借给“名牌”企业，并且要的利息也比较低。而对微不足道的小业主却几乎没有人信得过。即使信得过，那利息也高得出奇。这就使小生产者很容易落入高利贷者的魔爪。","language":"中文","translation":false},{"id":"communism-abc-4-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"大经济所具有的这些优越性告诉我们，为什么小生产在资本主义社会不可避免地要破产。大资本战胜了它、夺走了买主、使它破了产，使它的主人变为无产者或流浪汉。当然在很多情况下，小业主仍在继续为争取生存而奔波。他使尽自己全身力量，亲自工作，并强迫他的工人和家里人拼命劳动，但结果还是不得不向资本让位。经常可以看到，表面上好象是一个独立的小业主，实际上却完全依赖于大资本家，为大资本家工作，没有大资本家，他寸步难行。小生产者时常依附于高利贷者，他仅仅在表面上是独立的，而实际上是在为这个贪残的剥削者工作；或者依附于购买他的商品的收购商；或者依附于他所为之工作的商店（这里，他的独立也仅仅是表面的，实际上，他已经成为那个大商店资本家的雇佣工人）；常常是资本家向他提供原料，也有时提供原料和工具（我国的手工业者经常遇到这种情况）；从这里已经完全清楚地看到，手工业者已成为资本的名符其实的附庸；还有另外一些依附于资本的形式，在一些大企业附近，有时设立一些小修理作坊，在这种情况下，它们无非是工厂的一个小小螺丝钉——仅此而已。在这里，它们只在表面上是独立的。有时可以看到，破了产的小业主、小手工业者、小商人、小资本家，从一个生产部门或商业部门被赶出来，又转到另一个大资本的势力还不很强大的部门中去。特别是破了产的业主常常变为小商贩，等等。大资本就是这样一步一步地、从各方面把小生产排挤掉。雇用几千、甚至几万工人的巨大企业在增加。大资本越来越成为世界的主宰者。个体劳动所有制日渐消失，为大资本所有制所取而代之。","language":"中文","translation":false},{"id":"communism-abc-4-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"俄国小生产的败落，可以用手工业者为例说明。有些手工业者用自己的原料生产产品（熟制毛皮匠、编筐工人等等）并把产品卖给别人。后来，手工业者开始为固定的（只为一个）资本家（莫斯科的制帽商、玩具制造商、鬃制品制造商等等）干活。再往后，他就从他的定货人那里领取原料，并正式陷入依附地位（巴甫洛夫的制锁匠、布尔马基诺的钳工）。最后，他按件数从定货人那里领取工钱（例如，特维尔的制钉工、基姆雷制鞋匠、马卡里耶夫的编席工、巴甫洛夫的制刀匠）。手工织布工也陷入了这种依附地位。在英国，处在灭亡状态的小生产得到了一个“血汗制度”的外号——它的处境十分艰难在德国，从1882至1895年这段时间，小企业的数量减少了百分之八点六，中等企业（拥有六至五十个工人）增加了百分之六十四点一，而大企业增加了百分之九十。从那时起，大量的中等企业也被挤垮了。在俄国，工厂也在相当迅速地挤垮手工业者。俄国最重要的生产部门之一是纺织（织布）业。如果我们把棉纺业中的工厂工人人数和该行业中手工业者的人数的变化加以比较，那我们就可以看出工厂排挤手工业者的速度该有多快了。请看下面的数字：","language":"中文","translation":false},{"id":"communism-abc-4-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"1866年，在棉纺织工业中，工厂工人与手工业者的人数是一百与七十之比，而到1894-1895年，就已经不是七十，而是八了。在俄国，大生产的发展得到了加强是因为外国资本一下子建了一些大企业。到了1902年，大企业的工人人数几乎占整个产业工人的一半（百分之四十）。","language":"中文","translation":false},{"id":"communism-abc-4-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"1903年，雇用一百个以上的工厂，在俄国欧洲部分占所有工厂总数的百分之十七，而工人人数占所有工厂工人人数的百分之七十六点六。","language":"中文","translation":false},{"id":"communism-abc-4-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"各国大生产的胜利带来了小生产者的痛苦。有时整个区和整个职业都差不多灭绝了（例如，德国的西西里亚的织布工、印度的织布工等等）。","language":"中文","translation":false},{"id":"communism-abc-4-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"（二）小生产和大生产在农业中的斗争。在资本主义制度下，在农业中也有象在工业中进行的那种小生产和大生产的斗争。有象资本家经营自己的工厂那样经营自己的庄园的地主，有大富农、中农、自己经常到外边或者给地主和富农打短工的贫农，还有雇农——这一切都象工业中有大资本家、中等工厂主、手工业者和雇佣工人一样。在农村也和城市里一样，大地产总比小地产组织得完善。","language":"中文","translation":false},{"id":"communism-abc-4-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"大农场主可以运用先进技术。使用农业机器（电犁、蒸汽犁、收割机、割草机、割捆机、播种机、脱粒机、蒸汽脱粒机等等）对于小农业主和农民来说，往往几乎是根本办不到的。小作坊的手工业者没有必要添置昂贵的机器（他也没有钱买，就是买了也得不偿失），同样，农民也不会买蒸汽犁，即使他买了也用不上，因为要赚回买这种大机器的本钱，需要很多土地，而不是那种仅仅养活一只鸡的一小块地方。","language":"中文","translation":false},{"id":"communism-abc-4-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"能否充分地利用机器和工具，取决于土地的数量。一架马拉的犁，需有三十公顷（一公顷等于十分之九俄亩）土地，才能很好地得到利用；条播机、收割机、脱粒机——需有七十公顷；蒸汽脱粒机——需有二百五十公顷；蒸汽犁——需有一千公顷。现在，有的地方已使用电力机器耕作，但也同样需要有大的农场才行。","language":"中文","translation":false},{"id":"communism-abc-4-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"灌溉、沼泽地的排水、挖渠（安装粘陶瓷排水管道），敷设田间铁路、公路等等，多半只有大农场主才能办到。大农场和工业中的情形一样，在工具、材料、劳动力、取暖、照明等等方面都比较节省。","language":"中文","translation":false},{"id":"communism-abc-4-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在大农场里，每俄亩土地所需的田间小道、栅栏和篱笆也将会少些，掉落在田间小道上的种子也会少些。","language":"中文","translation":false},{"id":"communism-abc-4-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"除此之外，大农场主可以雇用农艺师，完全按照正规办法经营自己的农业。","language":"中文","translation":false},{"id":"communism-abc-4-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在贸易和贷款方面，情况也和工业一样：大农场主比较了解市场，他能够等待时机，能比较便宜地购买所必需的一切，比较贵地出卖自己的产品。小农户只剩下一条路：拼出全身的力气奋斗。小农业只有通过紧张劳动、减少自己的消费和节衣缩食的办法来维持生活。在资本主义统治下，也只有这样它才能幸存下来。还有一种东西对小农户的破坏性更大，那就是沉重的赋税。资本主义国家把巨大的负担加给小农户：只要回想一下沙皇时代加给农民的赋税，也就明白了，——任你倾家荡产，税是非交不可的。","language":"中文","translation":false},{"id":"communism-abc-4-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"一般可以说，农业中的小生产比工业中的小生产生命力要强一些。城市中的手工业者和小企业主灭亡得相当快，而各国农村农民经济的根基还稍微牢固一些。但是，这里也同样的出现了大部分人的贫困化。只是常常不那么明显。有时从土地数量上看，农场似乎并不大，而实际上，它却大得很，投资既多，雇的工人数量又很可观（例如，大城市附近的菜园主）。有时相反，有很多农户，看起来似乎是完全独立的，而实际上他们差不多等于雇佣工人：他们或是受雇在邻人的庄园里干活，或是去打短工，或是到城里做工。在各国农民中发生的一切，也和在手工业者中发生的一切一样。他们中一少部分人成为富农-土豪（店主、高利贷者，这些人逐渐增大自己的地产）；其余的人或者坚持着，或者最终破产：卖掉牛马，成为无马农民；后来份地也不见了，于是就完全流落到城市，或者成为雇农。无马农民变为雇佣工人，雇用工人的富农-土豪变为地主或资本家。","language":"中文","translation":false},{"id":"communism-abc-4-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"这样，在农业中大量的土地、工具、机器、牲畜都掌握在少数最大的资本家-地主手里，而千百万工人都为他们干活，千百万农民得依附于他们。","language":"中文","translation":false},{"id":"communism-abc-4-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在资本最发达的美国，有一些巨大的庄园，那里的工作和工厂一样。象工厂只生产某一种产品一样，这里的情形也是如此。有的大片田地种满了草莓，或者种满了果树；有专门的家禽业；在种植小麦的地方是使用机器劳动。很多部门都集中在少数人手里。例如，有“雏鸡大王”（几乎一切雏鸡的生产都集中在这个资本家手里），“鸡蛋大王”等等。","language":"中文","translation":false},{"id":"communism-abc-4-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"第十五节 无产阶级的依附地位，劳动后备军，女工和童工劳动","language":"中文","translation":false},{"id":"communism-abc-4-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在资本主义制度下，越来越多的人变成雇佣工人。破产的手工业者、农民、商人、破了产的中等资本家——一句话，一切被抛弃的人，一切被大资本打倒了的人，都被抛进无产阶级的行列。随着财富不断地集中在少数资本家手里，人民群众日益成为他们的雇佣奴隶。","language":"中文","translation":false},{"id":"communism-abc-4-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"由于中间阶层和中等阶级不断破产，工人的数量总是多于资本的需要。这样，资本就把工人拴住了。他必须为资本家干活。他要是不愿意，资本家可以找到千百个其他人。","language":"中文","translation":false},{"id":"communism-abc-4-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"但是，这种对资本的依附地位的日益加深还有其他方面的原因，不单单是由于各居民阶层的破产。资本对工人的统治不断加强，还因为资本经常裁剪它所多余的工人，并用这些工人来为它建立起一批后备的劳动力。这是怎样发生的呢？情况是这样的。前面我们已经看到，每一个工厂主都在努力为自己降低商品价值。正因为如此，他们不断引进机器。但是，这种机器常常是取代了工人，使一部分工人成为多余的人。引进机器，这就是说，一部分工人要被解雇。这些人由工厂的在业工人变为失业者。而由于引进新机器的做法处处都在采用，不是在这个生产部门，就是在那个生产部门，所以显然在资本主义制度下也就始终存在着失业。要知道，资本家关心的并不是让所有人都有工作，或是把商品提供给所有人，而是要榨取更多的利润。所以他们自然就要把那些已经不能象过去那样为他们带来利润的工人抛向街头。","language":"中文","translation":false},{"id":"communism-abc-4-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在所有资本主义国家，我们也确实看到，大城市里经常有着大量的失业者。这里，无论是中国工人，还是日本工人，都是从遥远的地方来找工作的破产的农民，还有刚刚流落到城市的农村青少年，以及从前的小店主和手工业者；但是，在这里我们也能看到在工厂干了很久的冶金工人、印刷工人或纺织工人，他们是由于引进了新机器而被赶出工厂的。这些人加在一起就构成了资本的后备劳动力的来源，或是象马克思所说的产业后备军。劳动后备军的存在，经常性的失业使资本家有可能加强工人阶级的依附地位和对工人阶级的压迫。资本利用机器从一部分工人身上榨取比从前更多的金钱；另一部分工人却因此而被抛弃街头。而被抛弃街头的工人又成了资本家手里的鞭子，用来驱使在业的工人。","language":"中文","translation":false},{"id":"communism-abc-4-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"产业后备军造成了人们的极端野蛮、贫困、饥饿、死亡甚至犯罪的现象。那些多年的不能找工作的人，逐渐变成了酒鬼，沦为流浪汉、乞丐等等。在一些大城市——伦敦、纽约、汉堡、柏林、巴黎——都有一整片住满了这类失业者的街区。在莫斯科，希牡丹罗夫市场就属于这类地方。这里正在形成一个新的阶层，他们已经脱离劳动，已不再是无产阶级了。这种资本主义社会的产物叫做流氓无产阶级（无赖无产阶级）。","language":"中文","translation":false},{"id":"communism-abc-4-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"机器的使用还产生了一种女工和童工劳动，这种劳动更便宜，因而对资本家也更有利。过去，在出现机器以前，工作需要有特殊的技能，有时甚至要经过长时间的学习。而现在连小孩子也可以使用某些机器干活，只要还未傻到不会挥手或动脚的程度就行。因此，在机器出现以后采用女工和童工劳动的做法越来越广泛。女工和童工不能象男工人那样反抗资本家。他们比较驯服，更不敢反抗，常常相信牧师和上司对他们所说的一切。所以工厂主常用女工代替男工，并强迫童工用自己的血汗铸成作为他的利润的金币。","language":"中文","translation":false},{"id":"communism-abc-4-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"1913年，女职工数量如下：法国——六百八十万，德国——九百四十万，奥匈帝国——八百二十万，意大利——五百七十万，比利时——九十三万，美国——八百万，英格兰和威尔士——六百万。俄国女工的数量经常不断地增加。1900年，女工占整个工厂男妇工人的百分之二十五（即四分之一），1908年占百分之三十一，几乎是三分之一，1912年占百分之四十五；在有些生产部门女工占大多数。例如，在纺织部门，1912年八十七万工人中女工是四十五万三千，即一半还多（超过百分之五十二）。在战争年代里，女工的数量大大增加。至于童工，尽管受到禁止，但在很多地方仍很盛行。在最发达的资本主义国家——美国，童工劳动可以说比比皆是。","language":"中文","translation":false},{"id":"communism-abc-4-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"这样一来，工人的家庭解体了。既然妻子，有时连孩子都在工厂，那还有什么家庭生活可言呢！","language":"中文","translation":false},{"id":"communism-abc-4-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"既然妇女进了工厂，成为女工，那她们就和男人一样时时感受到失业的威胁。资本家也同样会把她们赶出门外；她们也在加入产业后备军的行列；她们和男人一样也会沉沦到社会最底层。由此就出现了卖淫，即妇女把自己出卖给街上的陌生的男人。没有吃的，没有工作，到处被人轰赶；即使有工作，收入也很可怜，这就使她们不得不间或出卖自己的肉体。后来这种新行当便成了习以为常的事情。职业娼妓阶层就是这样形成的。","language":"中文","translation":false},{"id":"communism-abc-4-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在一些大城市，娼妓占有很大的数量。象汉堡和伦敦这样的城市，有数以万计这种不幸的妇女。资本家建立了一些大型的，以资本主义方式经营的妓院，妓女们成了利润和发财的源泉。有一种贩卖白种女奴的广泛的国际商业。这种商业的中心是阿根廷（在南美洲）的城市。极其恶劣的是在所有欧洲和美洲的城市里盛行着幼女卖淫的现象。","language":"中文","translation":false},{"id":"communism-abc-4-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"因此，在资本主义社会，随着发明出越来越好的机器、建设越来越大的工厂和商品数量越来越增加，也就越发加深了资本的压迫、产业后备军的贫困和灾难、以及工人阶级对其剥削者的依附地位。","language":"中文","translation":false},{"id":"communism-abc-4-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"假如不存在私有制，一切都是共同使用，那就完全是另一回事了。那时，人们会直接缩短的劳动日，爱惜自己的体力，节省自己的劳动，关心自己的休息。而当资本家引起机器的时候，他关心的是利润：他没有必要缩短劳动日，这只会使他遭受损失。资本家使用机器不是为了解放人，而是为了使人沦为奴隶。","language":"中文","translation":false},{"id":"communism-abc-4-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"随着资本主义的发展，越来越多的资本用于机器设备、各种装置、宽阔的厂房、巨大的高炉等等；而用于雇用工人的资本反而越来越少。从前手工业劳动时，用于手摇车床和其他工具的费用并不大；几乎全部资本用于雇用工人。现在正相反：绝大部分用于添置各种机器设备，而这就是说，对劳动力需求的增加，不象破产者的数量增加得那样快，这些破产者都变成了无产者。在资本主义制度下，技术越发达，资本对工人的压迫越重，因为越难找到工作，生活就越艰难。","language":"中文","translation":false},{"id":"communism-abc-4-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"第十六节 生产的无政府状态，竞争，危机","language":"中文","translation":false},{"id":"communism-abc-4-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"工人阶级的灾难随着技术的发展而不断加重。在资本主义制度下，技术不是为公众带来好处，而是为资本家带来利润，给很多工人带来失业和破产。但是这些灾难的加重也还有其他的原因。","language":"中文","translation":false},{"id":"communism-abc-4-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"前面我们已经知道，资本主义社会的结构很糟糕。私有制占统治地位，没有任何总的计划。每一个工厂主在经营自己的事业上自行其是。他要同其他人争取买主，同他们“竞争”。","language":"中文","translation":false},{"id":"communism-abc-4-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"现在产生了一个问题，随着资本主义的发展，这种斗争是缓和了还是加强了。","language":"中文","translation":false},{"id":"communism-abc-4-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"初看起来，可能觉得这种斗争缓和了。的确，资本家变得越来越少；大的吞并了小的；过去上万个不同的企业主互相斗争——竞争很残酷；现在这些竞争对手少了——斗争变得不那么尖锐了。说是可以这样说，但实际上并不是这样。事实上情况恰恰相反。不错，竞争对手是减少了。但是每一个竞争对手变得比以前的竞争对手更强大和更有力了。他们的斗争比过去变得不是少了，而是多了，不是更平静了，而是更残酷了。一旦整个国家由少数几个资本家主宰着，那这些资本主义国家就会互相打起来。这种情况最后还是发生了。现在竞争是在资本家大财团之间，在它们的国家之间进行。在这里，它们的斗争不但靠低廉的价格，而且还靠诉诸武力。就是说，随着资本主义的发展，竞争仅仅是在竞争者的数量方面减少了，然而它的残酷和破坏程度却越来越加深了[2]。","language":"中文","translation":false},{"id":"communism-abc-4-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"还有一种现象必须指出：这里是所谓的危机。这些危机是什么样子？表现在哪里？事情是这样的。有一天人们忽然发现生产出的各种商品过了量。价格跌落，可是商品却无销路。仓库里各种各样的产品堆积如山，可就是卖不出去，因为没有买主。当然有很多饥饿的工人，但是他们所得无几，他们能买的东西，几乎一点也不能超过他们平时所购买的数量。于是破产开始了。在一种生产部门中首先是小型和中型企业支持不住而破产、倒闭；接着是更大些的企业。然而这一生产部门本来是从另一个工业部门购买商品的，而另一个部门又是向另一别的部门购买商品的。譬如说，成衣企业向制呢企业购买呢子，而制呢企业又向生产毛的企业购买毛等等。成衣企业破产了，就是说根本没有人再向制呢商购买呢子了——制呢工厂开始破产，紧接着生产毛的部门也遭到了同样的命运。各处的工厂开始倒闭，成千上万的工人流落街头，失的人数增加到难以置信的程度，工人的生活变得比平时更加糟糕。而生产出的商品却很多。仓库都要被撑破了。大战以前常常是这样：工业是蒸蒸日上的，工厂主的事业发展得很可观；后来，突然——倒闭、破产、失业；紧接着是事业停滞；再往后又重新好转，接着又十分顺利地发展；然后再一次倒闭……这就是俗话所说的“周而复始”。","language":"中文","translation":false},{"id":"communism-abc-4-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"人们因为财富而变成了乞丐，这种奇怪的状况说明了什么？","language":"中文","translation":false},{"id":"communism-abc-4-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"对于这个问题，不是那么简单就能回答的。然而却必须回答这个问题。","language":"中文","translation":false},{"id":"communism-abc-4-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"我们从上面已经看到，在资本主义社会，混乱状态，即通常所说的生产的无政府状态占统治地位。每一个企业主和工厂主都按照自己的意愿进行生产，自己对自己负责。毫无疑问，在这种情况下商品生产过多（商品过剩）的问题迟早会发生。如果生产出来的东西是产品而不是商品，即当生产不是为了市场的时候，生产过剩不是什么危险的事。而在商品生产的情况下则完全是另一回事。在这里，任何一个工厂主为了购买继续生产所需要的商品，首先必须卖掉自己的商品。一旦一个地方由于生产混乱而使机器停转了，那么这种情况立刻就会由这一部门影响到另一部门——普遍的危机爆发了。","language":"中文","translation":false},{"id":"communism-abc-4-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"这些危机具有很大的破坏性。大批商品毁掉了。小生产的残余就象被铁扫帚扫过一样。部分大企业也破产了。所有企业都很难站得住脚。","language":"中文","translation":false},{"id":"communism-abc-4-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"当然，危机的主要灾难是落到工人阶级的身上。","language":"中文","translation":false},{"id":"communism-abc-4-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"一些工厂完全倒闭，另一些则压缩了生产，每周只有几天工作，还有一些暂时关闭。失业的人数不断增加。产业后备军扩大了。与此同时，工人阶级的贫困和遭受的压迫也随之加深了。在危机期间，工人阶级本来就很困难的境况更加恶化了。","language":"中文","translation":false},{"id":"communism-abc-4-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"以1907——1910年席卷欧美（即整个资本主义世界）的危机的资料为例。在美国，工会会员中失业人数增加的情况为：1907年6月——百分之八点一，10月——百分之十八点五，11月——百分之二十二，12月——百分之三十二点七（在建筑工业中——百分之四十二，在成衣业——百分之四十三点六，在烟草业中甚至达百分之五十五）；一般性的失业（不光计算有组织的工人）当然还要更多。在英国，1907年夏天失业的百分比是百分之三点四至百分之四；11月增加到百分之五，12月——百分之六点一；1908年6月达到百分之八点二；在德国，到1908年1月，失业的百分比比前几年增加了一倍多。其他国家的情况也同样如此。","language":"中文","translation":false},{"id":"communism-abc-4-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"至于压缩生产，例如，美国的熔铁量由1907年的二千六百万吨降到1908年的一千六百万吨（一吨是六十一普特）。","language":"中文","translation":false},{"id":"communism-abc-4-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"危机期间商品价格下跌。那时，资本家先生们为了利润不受损失，便采取破坏性的方式。例如在美国他们把一些高炉熄灭了。更有意思的是巴西的咖啡种植园主们的行动。为了保持咖啡的高价，他们把成袋的咖啡扔进大海。现在全世界都感到了饥饿和产品缺乏之苦。这种饥饿和产品缺乏都是资本主义战争的结果，都是进行毁灭性战争的资本主义造成的。在和平时期，资本主义被多余的产品压得喘不过气，但是这些产品也不是卖给工人的，因为工人的口袋空空如也。工人从这些多余产品中只能得到一样东西：失业及其各种灾祸。","language":"中文","translation":false},{"id":"communism-abc-4-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"第十七节 资本主义的发展和阶级（阶级矛盾的尖锐化）","language":"中文","translation":false},{"id":"communism-abc-4-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"我们看到，资本主义社会有两个主要矛盾，两个主要缺点：第一，它是“无政府的”（它的无组织性）；第二，它实际上是由两个敌对的社会（阶级）组成的。我们还看到，随着资本主义的发展，通过竞争表现出来的生产的无政府状态使一切更加尖锐，更加不协调和更带有破坏性。在这里，社会的不协调性不是减小了，而是扩大了。社会分成两部分，即分成阶级的现象也同样如此。随着资本主义的发展，这种阶级之间的分化和裂痕同样不是缩小，而是扩大了。在这一头——资本家那里聚积着地球上的一切财富，在另一头——被压迫阶级那里聚积着一切贫困、痛苦和眼泪。产业后备军产生了一个蜕化、粗野、彻底贫困化了的社会阶层。即使那些有工作的人的生活同资本家也越来越不一样。无产阶级和资产阶级之间的差别日益扩大。过去，有一些中小资本家，他们当中很多人同工人比较接近，生活比工人略好些。现在则完全不同了。那些大老爷过着从前任何人作梦也没有想到的生活。不错，随着资本主义的发展，工人的生活总的来说有所改善；二十世纪前夕总的来说工资有所增加。但在同一时期内，资本家的利润增加得更快。现在工人群众和资本家的差别真是一个天上，一个地下。资本家，这完全是另一种人，真是高不可攀。资本主义愈发达，一小撮最富有的资本家升得就愈高，横在这一小撮无冕皇帝和千百万沦为奴隶的无产者之间的鸿沟也就愈深。","language":"中文","translation":false},{"id":"communism-abc-4-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"我们说过，工人的工资固然增加了，但是利润增加得更快，因此，两个阶级之间的差距也扩大了。然而从二十世纪开始，工资不但没有增加，反而下降了；但在同一时期内，利润却空前增加。就是说，尤其在最近一个时期，社会的不平等现象极其迅速地加剧了。","language":"中文","translation":false},{"id":"communism-abc-4-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"十分明显，既然这种不平等现象越来越严重，那么它迟早会导致工人同资本家的冲突。假如他们之间的差别减少了，假如工人的状况越来越接近于资本家，那当然会是“平安无事，谢天谢地”。可是事情并非如此，在资本主义社会里，工人同资本家不是日益接近，而是离得越来越远。这也就意味着无产阶级和资产阶级之间的阶级斗争必然要尖锐化。","language":"中文","translation":false},{"id":"communism-abc-4-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"资产阶级学者们极力反对这种观点。他们想证明，在资本主义社会里，工人将生活得越来越好。右派社会党人也跟在他们后边鼓吹这种论点。无论是前者，还是后者，都断言工人会逐渐地富起来，自己也会变成资本家。当然，这一切都纯属谎言。实际上，与资本家的状况相比较，工人的状况变得越来越恶劣。以最发达的资本主义国家美国为例。假设我们以1890——1899年期间的工资购买力（即消费品的价格计算，工人能够买多少消费品）为一百，那么工资购买力逐年的变化为：1890年——九十八点六；1895年——一百点六；1900年——一百零三；1905年——一百零一点四；1907年——一百零一点五。这就是说，工阶级的生活水平几乎没有提高，整个这段时间几乎是停滞不动的。工人在1907年能购买的食品、衣服和其他消费品，和他在1890年所能购买的差不多，只稍微有增加（百分之三）。而在同一时期内，美国的亿万富翁（一些最大的工业主）榨取了巨额利润，他们所得到的大量剩余价值大幅度地增加了。显然，资本家的生活水平，他们的骄奢、纵欲享乐等等，提高了好几倍。","language":"中文","translation":false},{"id":"communism-abc-4-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"阶级斗争基于资产阶级和无产阶级之间的利益矛盾。这种利益实质上是不可调和的，正象狼和羊的利益是不可调和的一样。","language":"中文","translation":false},{"id":"communism-abc-4-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"任何人都不难了解，资本家的利益是使工人的工作时间尽可能长，而付给他们的工资尽可能少；相反，工人的利益是工作尽可能少而工资尽可能多。所以毫不奇怪，工人阶级自产生时起，它为争取提高工资和缩短工作日进行的斗争就开始了。","language":"中文","translation":false},{"id":"communism-abc-4-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"这种斗争从来没有间断过，从来没有平息过。但这种斗争并不仅仅局限于为了多得几块钱。在一切地方，只要那里有资本主义制度，工人群众都坚信必须消灭资本主义本身。工人们开始思索，怎样才能用一种公平的、劳动的、平等友爱的制度来代替这可恨的制度。这样就产生了工人阶级的共产主义运动。","language":"中文","translation":false},{"id":"communism-abc-4-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"工人阶级的斗争不止一次地遭到很多挫折。但是，资本主义制度本身已蕴藏着无产阶级的最终胜利。为什么？因为资本主义的发展意味着把最广大阶层的人民变为无产者。大资本的胜利就是手工业者、小商人、农民的破产；它不断地扩大雇佣工人的队伍。无产阶级随着资本主义的每一步发展不断地扩大自己的人数。无产阶级就象一个巨大的多头蛇式的怪物；砍掉一个头，又长出另外十个。当资产阶级镇压了工人起义时，它就巩固了资本主义制度。但是这种资本主义制度的发展使几万、几百万小业主和农民破产；把他们抛在资本家的铁蹄之下，从而使资本主义制度的敌人即无产阶级的人数增加了。但是，工人阶级不仅从数量上变得强大了，除此之外，它还越来越团结。为什么？因为随着资本主义的发展，大工厂增加了。而每一个工厂里聚集着几千名，有时几万名工人。这些工人在一起并肩地劳动着。他们看到了资本家老板是怎样在剥削他们。他们看到了工人与工人都有是朋友和同志。联合在一个工厂里的无产者在各自的工作中养成了共同行动的习惯。他们之间最容易取得一致意见。所以说随着资本主义的发展，工人阶级不但人数增加了，而且团结性也更加提高了。","language":"中文","translation":false},{"id":"communism-abc-4-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"大工厂增加得越快，资本主义发展得越快，城乡手工业者和农民破产得也就越快。这就造成了人口在数百万以上的大城市的迅速发展。结果在相对不大的空间里——在大城市里——集结了巨大数量的居民，在这些居民当中，工厂的无产阶级占最大多数。他们栖身于拥挤、肮脏、烟气腾腾的街区里，而一小撮掌握一切的老板却住在豪华的私邸。这一小撮人的人数变得越来越少。工人的人数则变得越来越多，他们团结得也越来越紧密。","language":"中文","translation":false},{"id":"communism-abc-4-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"在这种情况下，斗争不可避免的尖锐化必定以工人阶级的胜利而告结束。不管资产阶级玩弄什么诡计，工人阶级迟早会同资产阶级发生激烈的冲突，把它从宝座上推下去，砸毁资产阶级的强盗国家，并建立自己新的、劳动的、共产主义的制度。因此，资本主义在其自身的发展中不可避免地要引起无产阶级的共产主义革命。","language":"中文","translation":false},{"id":"communism-abc-4-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"无产阶级反对资产阶级斗争有各种各样的形式。在这场斗争中产生了三种主要形式的工人组织，这就是：按照职业把工人联合起来的工会；合作社，主要是以摆脱经纪人-商人为目的的消费合作社；最后是工人阶级的政党（社会党、社会民主党、共产党），这些政党在自己的纲领中写的是要为工人阶级的政权而斗争。阶级之间的斗争越尖锐，工人运动的一切形式越应在一个共同的目标——推翻资产阶级统治上联合起来。那些对事物持正确态度的工人运动的领袖始终认为，必须在一切工人组织中实行紧密的团结和合作。例如，他们说，工会和无产阶级政党之间的行动统一是很必要的，所以工会在政治态度上不能是“中立的”（即在政治上漠不关心），而应当和工人阶级的政党共同前进。","language":"中文","translation":false},{"id":"communism-abc-4-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"最近一个时期的工人运动中又出现了几种新的形式，其中主要的是工人代表苏维埃。关于这一点，我们以后在本书的很多地方都将谈到。","language":"中文","translation":false},{"id":"communism-abc-4-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"因此，我们从资本主义制度发展的观察中可以准确无误地作出如下判断：资本家的数量减少了，但他们却变得更富有，更有势力；工人的数量越来越增加，同时他们的团结也越来越增强了，尽管发展还不平衡；工人和资本家之间的差别越来越大。所以资本主义的发展导致了这两个阶级的不可避免的冲突，也就是导致了共产主义革命。","language":"中文","translation":false},{"id":"communism-abc-4-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"第十八节 资本的积聚和集中是共产主义的条件","language":"中文","translation":false},{"id":"communism-abc-4-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"正如我们所看到的那样，资本主义正在自己为自己挖掘坟墓，因为它造就了自己的掘墓人——无产者，并且它越发展，它树的死敌数量就越多，越使他们联合起来反对自己。然而，资本主义不仅增加了自己的敌人，它还为社会生产的新组织，为新的协作的、共产主义的经济准备了基础。为什么这样说呢？我们现在就回答这个问题。","language":"中文","translation":false},{"id":"communism-abc-4-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"我们在前面已经看到（参看第十一节《资本》），资本在不断地扩大它的数量。资本家把从工人身上榨取的一部分剩余价值并入他的资本。因此资本不断增多。而资本增多就意味着可以扩大生产。这种资本的增加，资本这种在一部分人手里扩充就称为资本的积累或资本的积聚。","language":"中文","translation":false},{"id":"communism-abc-4-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"我们也乍到（参看第十四节《小生产和大生产的斗争》），随着资本主义的发展，中小生产灭亡了：中小工业主和商人都破了产，更有用说手工业者——他们都被大资本家吃掉了。这些中小资本家过去所有的资本都从他们手里消逝了，并且通过各种途径汇集到大剥削者的手里。这些大剥削者手里的资本增加了，因为别人手里的资本都流失了。这样资本就由过去分散在各种人手里而汇集到少数人手里了。现在，小资本家破产之后，这些资本便被那些在斗争中获胜了的人所掌握。这种从前处在分散状态中的资本的汇集，就称为资本的集中。","language":"中文","translation":false},{"id":"communism-abc-4-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"资本的积聚和集中，也就是资本汇集在少数人手里，还并不意味着生产的积聚和集中。假设，资本家用积累的剩余价值买下了邻居的小工厂，并且象过去一样让它继续生产。这里积累是完成了，而生产还照旧进行。但一般的情况并不是这样。在实际生活中，通常的情况（因为这样做对资本家有好处）是资本家对原有的生产进行改造，合并扩大生产，并且扩建原有的工厂。这样不但扩大了资本，而且生产本身也扩大了。生产变得巨大了，添置了大量机器，把数千名工人联合在一起。往往会发生这样的情况，十来个大工厂就能满足全国的商品需要。实质上这里工人在为整个社会生产，就是说，劳动已经社会化了。而支配权和利润则归资本家所有。","language":"中文","translation":false},{"id":"communism-abc-4-77","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":77,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"这种生产的集中和积聚也使得无产阶级革命之后的真正的协作生产成为可能。","language":"中文","translation":false},{"id":"communism-abc-4-78","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":78,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"的确，假如没有这种生产的集中，假如无产阶级掌握了政权，而生产还是零星分散在仅有两、三个人做工的几十万个小作坊里，那就没有任何可能把这些小作坊组织起来，并把它们纳入社会化的轨道。资本主义愈发达，生产愈集中，无产阶级在取得胜利之后就愈易掌握它。","language":"中文","translation":false},{"id":"communism-abc-4-79","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":79,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"这就是说，资本主义的发展不但造就了资本主义的敌人，不但导致共产主义革命，而且还奠定了实现共产主义制度的经济基础。","language":"中文","translation":false},{"id":"communism-abc-4-80","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":80,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"第二章书目：除了和第一章书目的那些书以外，还有：亚·波格丹诺夫和伊·斯切潘诺夫《政治经济学教程》第二卷第二分册（工业资本的时代）。马克思和恩格斯《共产党宣言》。杰克·伦敦《在帝国主义的压迫下》。关于土地问题，参看：卡尔·考茨基《土地问题》。尼·列宁《土地问题和马克思的批评家》。卡尔·考茨基《社会主义和农业（答爱·大卫）》。弗·伊林（列宁）《关于农业中资本主义发展规律的新材料（美国）》。弗·伊林（列宁）《俄国资本主义的发展》。克尔日维茨基《土地问题》。帕尔乌斯《世界市场和农业危机》。","language":"中文","translation":false},{"id":"communism-abc-4-81","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第二章 资本主义制度的发展","page":4,"paragraph":81,"url":"https://www.marxists.org/chinese/bukharin/1919/04.htm","text":"[1] 这里指大战以前。在战争破坏之后，不是卖主招徕买主，而是买主巴结卖主。 [2] 详细情况可参看帝国主义战争一章。","language":"中文","translation":false},{"id":"communism-abc-5-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-5-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第三章 共产主义和无产阶级专政","language":"中文","translation":false},{"id":"communism-abc-5-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"· 第 十九 节 共产主义制的特征，共产主义制度下的生产","language":"中文","translation":false},{"id":"communism-abc-5-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"· 第 二十 节 共产主义制度下的分配","language":"中文","translation":false},{"id":"communism-abc-5-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"· 第二十一节 共产主义制度下的管理","language":"中文","translation":false},{"id":"communism-abc-5-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"· 第二十二节 共产主义制度下的生产力的发展（共产主义的优越性）","language":"中文","translation":false},{"id":"communism-abc-5-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"· 第二十三节 无产阶级专政","language":"中文","translation":false},{"id":"communism-abc-5-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"· 第二十四节 夺取政权","language":"中文","translation":false},{"id":"communism-abc-5-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"· 第二十五节 资本主义社会的共产党和阶级","language":"中文","translation":false},{"id":"communism-abc-5-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第十九节 共产主义制的特征","language":"中文","translation":false},{"id":"communism-abc-5-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"我们看到，资本主义制度为什么必然要崩溃（而现在它正在我们面前崩溃）。它之所以要崩溃是因为它有两个基本矛盾：一方面是生产的无政府状态，它导致了竞争、危机和战争；另一方面是社会的阶级性，社会的一部分人同社会的另一部分人处于、而且也不能处于势不两立的敌对状态（阶级斗争）。资本主义社会是一部结构很糟的机器，其中的一部分经常紧扣着另一部分（参看第十三节《资本主义制度的基本矛盾》）。所以这部机器迟早不可避免地要毁掉。","language":"中文","translation":false},{"id":"communism-abc-5-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"显然，新社会应当是这样的一种社会，它的结构将比资本主义坚固得多，既然资本主义的基本矛盾会把资本主义炸得粉碎，那么在这个资本主义的废墟上必然出现没有旧社会所固有的那些矛盾的社会。就是说，共产主义生产方式的特点应当有发下几点：1、它应当是有组织的社会；它不应当有生产的无政府状态、私人企业主的竞争、战争和危机；2、它应当是无阶级的社会，它不应当是由互相永远敌对的两部分人组成，它不能是一个阶级剥削另一个阶级的社会。而这样的无阶级的和全部生产是有组织的社会，只可能是协作的、劳动的、共产主义的社会。","language":"中文","translation":false},{"id":"communism-abc-5-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"我们现在比较详细地研究一下这个社会。","language":"中文","translation":false},{"id":"communism-abc-5-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"共产主义社会的基础应当是生产资料和流通手段的公有制。这就是说，机器、装备、机车、轮船、厂房、仓库、大粮仓、矿山、电报、电话、土地和耕畜——这一切都归社会占有。不是个别资本家，不是个别财团占有这些资料，而是全社会占有。全社会是什么意思呢？这就是说，甚至不是一个阶级是占有者，而是组成社会的所有的人都是占有者。在这种条件下，社会变为巨大的劳动协作组合。这里没有任何生产的分散和任何无政府状态。相反地，正是在这种制度下，全部生产都是有组织的生产，其中任何一个企业也不会同另一个企业进行斗争和竞争，因为一切工厂、矿山和其他设施在这里好象是一个包括全部国民经济的全民大工厂下面设的分厂。不用说，这种巨大的组织要有共同的生产计划。如果所有工厂和整个农业都成为一个巨大的劳动组合，自然在这里一切都应当计算好：不同工业部门之间的劳动力怎样分配，它们需要生产什么产品和生产多少，技术力量往哪里使用，等等，——这一切都需要预先，哪怕是大体上计算好，并按照这种计算行动。正是在这一点上表现出共产主义生产的组织性。没有共同的计划和共同的领导，没有准确的统计和计算，就没有任何组织。在共产主义制度下，这样的计划是有的。","language":"中文","translation":false},{"id":"communism-abc-5-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"但是，只有组织性是不够的。这里问题的实质还在于这个组织是社会全体成员的协作组织。除了组织性以外，共产主义制度还有一个特点就是，它消灭剥削，它消灭社会的阶级划分。要知道，也可以设想生产是按照这样的方式组织的：少数资本家占有一切，然而是共同占有的；生产是有组织的，资本家同资本家不角逐、不竞争，而是共同地从变为半奴隶的工人身上榨取剩余劳动。这里有组织，但是也有一个阶级对另一个阶级的剥削。这里有生产资料的公有制，但这只是一个阶级，即剥削阶级的公有制。因此这决不是共产主义，尽管这里也有生产组织。这种社会组织可能只消除了一个基本矛盾：生产的无政府状态。但是，它却加剧了资本主义的另一个基本矛盾：社会划分为两个斗争的部分；阶级斗争还更加尖锐化。这个社会只是在一个方面是有组织的；但是它在另一方面，即在阶级是彻底分裂的。共产主义不仅组织生产，而且要把人们从一些人压迫另一些人的状态下解放出来，它在自己的各个方面都是有组织的。","language":"中文","translation":false},{"id":"communism-abc-5-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"共产主义生产的协作性质还表现在对这种生产进行组织的一切细节上。例如，在共产主义制度下，不会永久不变的工厂管理者或一辈子从事某一种劳动的人。要知道，现在是这样的：如果一个人是皮鞋匠，那他一辈子缝制鞋子，除了鞋楦，他什么也看不到；如果这是一个烤大馅饼的人，那他就一辈子烤大馅饼；如果这个人是工厂厂长，那他就总是在进行管理和发号施令；如果他是一个普通工人，他就一辈子执行别人的吩咐和安排。在共产主义社会中没有任何诸如此类的现象。在这里，所有的人=都受过多方面的教育并熟悉各种生产：今天我做管理工作，计算下一个月需要生产多少毡靴或长圆形白面包；明天我在肥皂厂作工，过一星期，可能在公共温室工作，再过三天，可能在电站工作。当社会的一切成员都受到应有的教育的时候，这将是可能的。","language":"中文","translation":false},{"id":"communism-abc-5-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第二十节 共产主义制度下的分配","language":"中文","translation":false},{"id":"communism-abc-5-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"共产主义的生产方式不是为市场生产，而是为自己的需要进行生产。不过这里为自己生产的不是单个业主，也不是单个的农民，而是整个这个巨大的劳动组合。就是说，这里没有商品，只有产品。这些生产的产品不是用来互相交换；不是用于买卖。它们只是存入公共的仓库，然后，谁需要，谁就去拿。因而，这里将不需要货币。有的人会问：那怎么行呢？要是这样做，有的人就会拿得太多，而别的人又会拿得太少。这样分配产品能有什么好处呢？这里必须就此说几句。在初期，大概在几十年时间，当然必须建立各种规章，例如，领取生产品只能凭劳动手册上的登记或出示劳动券。以后当共产主义社会完全巩固和发达起来，这些也就都不需要了。任何产品都将非常丰富，一切创伤都早已治愈，每个人都可以得到他所需要的东西。人们没有丝毫兴趣拿取比他所需要的更多的东西。例如，要知道，现在在电车上谁也不想要买三个座位的票，自己坐一个，而让其他两个空着，因为没有这种需要。将来对一切产品都是如此：一个人需要多少，他就从公共仓库里拿取多少，丝毫也不多拿。他也没有兴趣卖掉多余的产品，因为既然每个人都可以去拿，所以那时货币就没有价值了。这就是说，在共产主义社会开始时，产品大概要根据劳动来分配，而以后，那就要直接按公民同志的需要来分配了。","language":"中文","translation":false},{"id":"communism-abc-5-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"常常有人说，在未来的社会里，将实现每一个人领取自己全部劳动产品的权利：生产什么，就领取什么。这是不对的。并且任何时候也不可能完全实现。为什么？因为如果大家都领取各自生产的产品，那生产就永远不可能前进、扩大和改进。生产出的东西总要有一部分用于生产的扩大和改进。假如我们把生产的一切全都用于吃和穿，那就不可能生产机器，因为机器既不能吃，也不能穿。任何人都知道，生活是随着机器的增加和改进而得到改善的，机器将生产得越来越多。这就意味着包含在制造机器里的那一部分劳动是不能归还给劳动者本人。就是说任何时候都不可能使每一个人都能全部领取自己的劳动产品。而且这也是完全不必要的。在使用良好的机器的条件下，不这样做，生产也能满足全部需要。","language":"中文","translation":false},{"id":"communism-abc-5-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"这样，在初期，产品将是按劳分配（虽然不是按“劳动的全部产品”），而以后就可以充分地按需分配了。因为所有东西都极大地丰富了。","language":"中文","translation":false},{"id":"communism-abc-5-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第二十一节 共产主义制度下的管理","language":"中文","translation":false},{"id":"communism-abc-5-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"在共产主义社会将不存在阶级了。既然在这个社会里没有阶级，那就意味着在这个社会里也将没有任何国家了。我们在前面已经说过，国家是阶级的统治组织；国家从来就是使一个阶级反对另一个阶级：如果国家是无产阶级的，那它就是旨在反对资产阶级。在共产主义制度下，地主、资本家、雇佣工人都不存在了，只存在普通人——同志。阶级没有了，阶级斗争也没有了，阶级组织也就不存在了。因而也不存在国家了：国家在这里已无必要，因为阶级斗争没有了，不需要对任何人进行约束，也没有任何人去干这种事。","language":"中文","translation":false},{"id":"communism-abc-5-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"然而有人会问我们，这样庞大的组织没有任何管理能行吗？谁来制定社会生产的计划？谁来分配劳动力？谁来统计社会收支？一句话，谁来维持整个秩序呢？","language":"中文","translation":false},{"id":"communism-abc-5-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"回答这个问题是不难的。主要的领导将是各种形式的计算所，或者统计（计算）局。那里每天都将对整个生产及其需要进行计算：将指示哪里需要增加劳动力，哪里需要减少劳动力，工作多少。由于大家都将从小就习惯于共同劳动，并懂得劳动的需要，也懂得当一切都顺利地按照既定的计划去进行时，生活就最容易，那么大家也就会按照这些统计局的指示去工作。在这里不需要专门的部长、警察、监狱、法律、法令，——什么也不需要。在这里人们将看着计算表，并根据它进行工作，就象在乐队里大家都看着指挥进行演奏一样。","language":"中文","translation":false},{"id":"communism-abc-5-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"这就是说，这里任何形式的国家也没有。这里没有任何居于其他阶级之上的集团和阶级。况且，在这些计算局里工作的，今天是这一些人，而明天又会是另一些人。官僚制度，固定的官吏必将消失，国家必将消亡。","language":"中文","translation":false},{"id":"communism-abc-5-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"当然，这将是在发达的、巩固的共产主义制度下，在无产阶级完全的和彻底的胜利之后，而且不是在胜利之后很快就会这样。要知道，工人阶级必须长期地同自己的敌人进行斗争，然后同一切旧的残余即懒惰、松懈、犯罪行为和需要经过很长时间才能扫除干净的老爷习气进行斗争。这需要在完全新的条件下成长起来的两三代人的时间，一直到不再需要工人国家用法律、惩处和镇压的办法来消除资本主义时期的各种残余时为止。但是如果说在这方面工人国家是需要的，那么在发达的制度下，当资本主义残余消灭了的时候，无产阶级的国家政权也就消亡了。无产阶级自己将同其他阶层融合在一起，因为所有的人都将渐渐地开始被吸引到共同劳动的工作中来，而经过几十年之后就将会出现完全不同的土地、不同的人民和不同的风尚。","language":"中文","translation":false},{"id":"communism-abc-5-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第二十二节 共产主义制度下的生产力的发展","language":"中文","translation":false},{"id":"communism-abc-5-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"当共产主义制度取得胜利并医治好所有的创伤的时候，它就会迅速地推动生产力的发展。生产力之所以能得到飞速发展，是由于下列原因。第一，人类用在阶级斗争上的巨大精力被解脱出来。可以想一想，如今在政治、罢工、起义、镇压起义、法院、警察、国家政权，以及在每天应付各个方面的事务上，不知耗费了多少精力和劳动！","language":"中文","translation":false},{"id":"communism-abc-5-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"阶级斗争消耗了大量的人力和财力。所有这些力量都会被解放出来，因为，人们那时将不再互相斗争了。这些被解放出来的力量将用于生产劳动。第二，在竞争、危机和战争中会遭到破坏或耗费的力量和资金将保存下来。即使只计算用于各类战争的费用，那么这也将是一笔极其巨大的数额。而卖主之间、买主之间以及卖主与买主之间的斗争所用去的社会开支不知有多少！在危机中不知有多少财富被白白毁掉！生产的无组织和无秩序，不知要造成多少不必要的花费！所有这些被白白用掉的力量，在共产主义社会都会被保存下来。第三，组织性和适当的计划不但可以防止多余的开销（这里要说明一下，大生产总是很经济的），而且有利于改进各种技术方面的事宜：使生产在一些最大的工厂里进行，采用最好的技术方法。要知道，在资本主义制度下，甚至使用机器也是有一定限度的。只有在廉价劳动力不足的时候，资本家才使用机器。如果有廉价的劳动力，那么，资本家就用不着使用机器，因为没有机器，资本家也能赚大钱。只有在机器节省了价钱高的劳动力的时候，资本家才认为机器是需要的。而因为在资本主义制度的一般情况下，劳动力是低廉的，所以工人阶级这种糟糕的状况是阻碍技术改进的原因。这一点在农业上表现得特别清楚。农业劳动力总是低廉的，因此，机器劳动的发展非常缓慢。在共产主义社会关心的不是利润，而是劳动者本身。在那里，任何改进都将立即推广和实施。它不会受到资本主义的束缚。技术发明在共产主义制度下也将蓬勃发展。因为人们将受到良好的教育，那些在资本主义制度下穷困潦倒的人（如那些有才干的工人），也将有充分的机会发挥自己的才能。","language":"中文","translation":false},{"id":"communism-abc-5-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"在共产主义社会里，寄生生活，就是说现存的那些游手好闲、专靠别人生活的寄生虫也将消失。那些在资本主义社会里供资本家用于挥霍、大吃大喝的费用在共产主义社会将被用于生产需要；资本家及其侍从和奴仆、牧师、妓女等等也将消失，社会的一切成员都将从事生产劳动。","language":"中文","translation":false},{"id":"communism-abc-5-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"共产主义的生产方式将意味着生产力的巨大发展。这就是说，共产主义社会的每一个工作人员付出劳动将比以前减少。工作日将越来越缩短，人们将更多地从自然界的束缚中解放出来。既然人们在谋取衣食方面花费的时间少了，那就意味着他们将有更多的时间用于精神上的发展。人类的文化将达到前所未有的高度，同时它将是真正的人类文化，而不是阶级文化。随着人压迫人现象的消失，自然界的压迫也将消失。人类在这里开始过着真正有理性的，而不是兽性的生活。","language":"中文","translation":false},{"id":"communism-abc-5-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"共产主义的反对者们总是把共产主义描绘成平均分配。他们说，共产党人想把一切都夺走，然后再平均分配，包括土地和其他生产资料，以及消费资料。没有什么比这种观点更荒谬的了。首先，这种普遍的重新分配是不可能的。因为可以平分土地、耕畜、货币，然而绝不能平分铁路、机器、轮船、复杂的设备。这是第一。第二，平分不但不会带来什么好处，反而会使人类倒退。这种平分意味着会形成大量的小私有者。而我们已经知道，从小私有制和小私有者的竞争中产了大私有制。就是说，如果实现了普遍的重新分配，那历史又要重演，人们又要重复那个说了又说的故事。","language":"中文","translation":false},{"id":"communism-abc-5-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"无产阶级的共产主义（或无产阶级的社会主义）是大型的、协作的、统一的经济。它是从资本主义社会的整个发展和无产阶级在这个社会中的地位里产生出来的。需要把它和下列几种情况区别开来：","language":"中文","translation":false},{"id":"communism-abc-5-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"（1）流氓无产阶级的社会主义（无政府主义）。无政府主义者指责共产党人说，似乎共产主义在未来的社会里还保留国家政权。我们知道，这是不对的。真正的区别在于，无政府主义者更多注意的是分配，而不是生产组织；他们所想象的这种生产组织，不是巨大的协作经济，而是大量小型的“自由的”、自治的公社。显然，这种制度不能使人类从大自然的压迫下解放出来；它的生产力发展甚至都达不到资本主义制度下所能达到的那种限度。这是因为无政府主义不是使生产合并扩大，而是使生产分散化小。所以无政府主义者在实践上常常倾向于瓜分消费品，并反对组织大生产，这是毫不奇怪的，而是所谓流氓无产阶级的即无赖无产阶级的。这个阶级在资本主义制度下生活很苦，但是却不能做任何独立的创造性工作。","language":"中文","translation":false},{"id":"communism-abc-5-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"（2）小市民的（城市小资产阶级的）社会主义。它依靠的不是无产阶级，而是破产者的手工业者、小市民，部分地依靠知识分子。它反对大资本，但为的是小企业活动的“自由”。它多半主张资产阶级民主，反对社会主义革命，希望通过“和平途径”来达到自己的理想，如通过发展合作社、劳动组合、联合手工业者等等办法。我国很大一部分城市社会革命党的合作社就属于这种类型。在资本主义制度下，这些合作社企业逐渐退化成为一般的资本主义组织，而这些合作社的举办人本身同纯粹的资产者几乎没有什么区别。","language":"中文","translation":false},{"id":"communism-abc-5-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"（3）农业-农民社会主义。这种社会主义具有各种各样的形式，有时近似农村无政府主义。它的最大的特点是，它从来就是把社会主义想象为大经济，非常近似于主张瓜分和均分的思想；他们与无政府主义的区别主要在于要求有牢固的政权，以保卫自己反对地主，同时也反对无产阶级；社会革命党的“土地社会主义化”就是这样的“社会主义”，这种“土地社会主义化”想永远巩固小生产，害怕无产阶级，害怕整个国民经济变为大型的协作统一体。此外，在某些农民阶层中还有一些其他型式的社会主义，它们更多地接近于无政府主义，不承认国家政权，但是带有和平的性质（如教派共产主义，反正教仪式的教徒等等）。农业-农民的情绪只有在多年以后，当农民群众懂得了大经济的一切优越性（关于这一点，我们下面还要多次提到）的时候，才能够铲除。","language":"中文","translation":false},{"id":"communism-abc-5-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"（4）奴隶主和大资本家的所谓社会主义。实际上，这里连社会主义的影子也谈不上。如果说上述三派的“社会主义”里还有那么一点迹象，如果说它们还是反对压迫的，那么，在这里，有的只是空话，是以欺骗手段来混淆视听。资产阶级学者曾使这种子观点风行一时，而妥协派的社会主义者们也和他们唱一个调子（其中包括考茨基之流在内）。例如，古希腊哲学家柏拉图的“共产主义”就是这样。其含义就是，奴隶主的组织“合伙地”和“共同地”剥削无权利的奴隶大众。在奴隶主之间是完全的平等和普遍的一律。奴隶们则一无所有：他们变成了牲畜。十分明白，这里没有一点社会主义的气味。现在有一些资产阶级教授也在“国家社会主义”的招牌下鼓吹这类“社会主义”，其唯一的区别就是变为奴隶的是现代无产阶级，而代替奴隶主的是高高在上的大资本家。事实上，这里一点社会主义的影子也没有，有的只是国家的、苦役式的资本主义（关于这一点，下面还要谈）。","language":"中文","translation":false},{"id":"communism-abc-5-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"小市民的、农民的和流氓无产阶级的社会主义有一个共同的特点：所有这些非无产阶级的社会主义形式，都不考虑发展的实际进程。发展的进程是在引向生产的扩大。而他们的一切却是以小生产为基础的。所以，这种社会主义无非是一种根本不可能实现的“乌托邦”空想。","language":"中文","translation":false},{"id":"communism-abc-5-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第二十三节 无产阶级专政","language":"中文","translation":false},{"id":"communism-abc-5-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"为了实现共产主义制度，无产阶级必须掌握全部政权和全部武力。如果它不掌握这种力量，如果它在一段时间不成为统治阶级，那它就不可能推翻旧世界。不言而喻，不经过战斗，资产阶级是不会交出自己的阵地的。要知道，对资产阶级来说，共产主义意味着丧失从前的强权地位，丧失榨取工人血汗的“自由”，丧失获得利润、利息、地租等等的权利。因此，无产阶级的共产主义革命，社会的共产主义改造会遇到剥削者的疯狂斗争和反抗。由于这种反抗必然会是很大的，所以工人的，即无产阶级的政权应当是工人专政。“专政”意味着特别严厉的管理方式和对敌人的坚决镇压。在这种情况下，根本谈不上一切人的“自由”，这是完全可以理解的。无产阶级专政同资产阶级的自由是势不两立的。这种专政之所以需要，是为了剥夺资产阶级的自由，捆住它的手脚，使它不能进行反对革命无产阶级的斗争。资产阶级的反抗越激烈，它越疯狂地施展自己的力量，它越危险，那么，无产阶级专政就应当越严厉和越无情，甚至必要时对采取恐怖手段也在所不辞。只有彻底镇压了剥削者，只有当他们不再反抗的时候，只有当他们不存在对工人阶级捣乱的任何可能性的时候，无产阶级专政才会日益缓和；同时从前的资产阶级将渐渐地同无产阶级打成一片，工人国家将逐渐消亡；而整个社会将变为没有任何阶级的共产主义社会。","language":"中文","translation":false},{"id":"communism-abc-5-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"在无产阶级专政这个暂时的机构下，生产资料实质上不是一无例外地属于整个社会，而是只属于无产阶级，属于它的国家组织所有。在这里，工人阶级即人口的大多数暂时垄断全部生产资料。因此，在这里，还不完全是共产主义的生产关系。这里还有社会划分为阶级的现象；这里还有统治阶级（无产阶级）；这里有这个新阶级对全部生产资料的垄断；这里有镇压敌人的国家政权（无产阶级政权）。但是，随着过去的资本家、地主、银行家、将军和主教的反抗遭到镇压，无产阶级专政的制度将不经过任何革命而转入共产主义。","language":"中文","translation":false},{"id":"communism-abc-5-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"无产阶级专政不仅是镇压敌人的工具，而且是经济变革的杠杆。要知道，这种变革必须以生产资料公有制来代替私有制；它必须没收（“剥夺”）资产阶级的生产资料和流通手段。谁将干这件事情而且应该干这件事情呢？很清楚，不是个别人，哪怕他是无产阶级出身的人。如果是个别人或者即使是个别集团来干这件事情，那么，在最好的情况下也只会是瓜分，而在坏的情况下简直就会变成掠夺。因此，很显然，必须由有组织的无产阶级力量来剥夺资产阶级。而这种有组织的力量就是专政的工人国家。","language":"中文","translation":false},{"id":"communism-abc-5-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"对无产阶级专政的非难来自各个方面。首先是无政府主义者。他们说他们反对任何政权和任何国家，然而布尔什维克共产党人却维护苏维埃政权。任何政权都是暴力和对自由压制。所以应当推翻布尔什维克和苏维埃政权即无产阶级专政。任何专政都是不需要的，任何国家也是不需要的。这就是无政府主义者的论断。他们的反对意见只是从表面看来很革命。实际上，无政府主义者不是比我们布尔什维克更左，而是更右。实际上我们为什么需要专政呢？是为了有组织地彻底打垮资产阶级的统治，是为了用暴力对付无产阶级的敌人（我们公开地说出这一点）。无产阶级专政就是无产阶级手中的一把斧子。谁反对它，谁就是害怕坚决的行动，谁就是害怕得罪资产阶级，谁就不是革命者。当我们完全战胜资产阶级的时候，我们就将不再需要任何无产阶级专政。但是，当存在你死我活的斗争时，工人阶级的神圣职责就在于坚决镇压自己的敌人。在共产主义和资本主义之间必定有一个无产阶级专政的时代。其次，反对专政的还有社会民主党人，其中包括孟什维克。这些先生完全忘记了他们自己曾经写过的东西。在我们同孟什维克一起制定的旧纲领中曾直截了当地指出：“社会革命的必要条件就是无产阶级专政，即由无产阶级夺取政权来镇压者的一切反抗。”孟什维克也认可了（在口头上）这一点，可是，当见诸于行动的时候，他们就开始为资产阶级的自由遭到破坏，为资产阶级的报纸被查封，为“布尔什维克的恐怖”等等而大喊大叫。其实当时连普列汉诺夫也极其赞同对资产阶级采取的无情的措施，说我们可以剥夺资产阶级的选举权等等。现在这一切都被转入资产阶级阵营的孟什维克置于脑后。","language":"中文","translation":false},{"id":"communism-abc-5-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"最后，有许多人从道德方面责难我们。他们说，我们的论断象野蛮的霍屯督人一样。霍屯督人说：“我偷邻居的妻子是好事；他偷我的妻子是坏事。”他们说，布尔什维克同野蛮人毫无区别，因为布尔什维克说：“资产阶级对无产阶级施行暴力是坏事；无产阶级对资产阶级施行暴力是好事。”","language":"中文","translation":false},{"id":"communism-abc-5-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"提出责难的人一点也不了解所谈论的问题。他们谈到霍屯督人，其实那是两个同样的人，他们根据同一理由互偷对方的妻子。然而，无产阶级和资产阶级不是两个同样的阶级。无产阶级是人数众多的阶级，资产阶级是一小撮人。无产阶级为争取全人类的解放而斗争，资产阶级为保护为保存压迫、战争和剥削而斗争；无产阶级为共产主义而斗争，资产阶级为保存资本主义而斗争。如果资本主义和共产主义是同一制度，那么，资产阶级和无产阶级就象两个霍屯督人。而现在只有无产阶级为建立新制度而斗争；凡是帮助它进行这场斗争的事都是有益的；凡是有碍这一斗争的都是有害的。","language":"中文","translation":false},{"id":"communism-abc-5-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"无产阶级以夺取国家政权的办法来实现自己的专政。然而什么是夺取政权呢？很多人认为，为夺取资产阶级的政权就象把皮球从一个口袋里拿出来放进另一个口袋里一样。原先这个政权在资产阶级手里，后来无产阶级赶走了这个资产阶级，并把它手里的政权拿来归为已有。不是建立新政权，而是把旧政权抓在自己手里。","language":"中文","translation":false},{"id":"communism-abc-5-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"这种观点完全不对，只要仔细地想一想，就能看出它错在哪里。","language":"中文","translation":false},{"id":"communism-abc-5-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"国家政权是一种组织。资产阶级的国家政权是资产阶级的组织，在这个组织里，所有的人都是按一定的方式挑选出来的：在军队里，将军是从上层的富人中挑选，在行政机关等等部门里，部长是从富人中挑选的。无产阶级在为政权而斗争的时候是反对谁呢？首先就是反对这个资产阶级组织。既然无产阶级反对这个组织，那就是说，其任务就是要打击这个组织，摧毁这个组织。而既然国家的主要力量在于军队，所以要战胜资产阶级首先就必须瓦解和摧毁资产阶级的军队。德国共产党人没有能够推翻谢德曼和诺斯克的政府，就是因为没有摧毁它的白卫军。如果敌人的军队完好无损，革命就不可能胜利；革命的胜利，也就是资产阶级军队的瓦解和崩溃。因此可以说，对沙皇专制的胜利，就意味着沙皇国家和军队的局部摧毁和瓦解；而十月革命的胜利，则意味着临时政府的国家组织和克伦斯基的军队的彻底摧毁和瓦解。","language":"中文","translation":false},{"id":"communism-abc-5-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"革命就是这样摧毁旧的政权和建立新的、不同于过去那样的政权。当然，也有一些旧政权的组成部分进入这个新政权，但是，它们是按照另一种方式来安排的。","language":"中文","translation":false},{"id":"communism-abc-5-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"就是说，夺取国家政权不是夺取原有的那个组织，而是建立另外的组织，即在斗争中获得胜利的阶级的组织。","language":"中文","translation":false},{"id":"communism-abc-5-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"这个问题具有巨大的实际意义。例如，有人指责德国的布尔什维克（就象曾经指责俄国的布尔什维克一样），说他们瓦解军队，促使纪律松弛、不服从官长等等。很多人至今还觉得这种指责很可怕。其实这并没有什么可怕。就是应当瓦解那些遵照军官和资产者的命令来反对工人的军队，哪怕他们是自己的同乡。否则就会葬送革命。就是说，瓦解资产阶级军队并没有什么可怕的，革命者应当把摧毁资产阶级的国家机构看作是自己的功绩。在资产阶级的纪律没有受到破坏的地方，资产阶级是不可能战胜的。绝不能又想打倒它，同时又怕刺伤它。","language":"中文","translation":false},{"id":"communism-abc-5-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第二十五节 资本主义社会的共产党和阶级","language":"中文","translation":false},{"id":"communism-abc-5-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"无产阶级要想在一个国家获得胜利，它就需要团结起来和组织起来，需要拥有自己的共产党，这个党要能够清楚地看到资本主义的发展趋向，要能懂得工人阶级的真实状况和真正利益，要能解释这种状况并能参加战斗和领导战斗。任何一个政党在任何时候和在任何地方都不能使本阶级的所有成员一个不漏地都加入到自己的行列中来，因为任何一个阶级从来也没有达到这样的觉悟程度。通常加入党的都是阶级中最“先进的”分子，这些人最能正确认识本阶级的利益，在斗争中最勇敢、最坚毅和最顽强。因此，党在自己的人员数量上，总是大大少于它所捍卫其利益的那个阶级的人数。但是由于党捍卫的正是这些已被正确认识了的利益，所以党通常起着领导作用。它们率领着整个阶级，而争取政权的阶级斗争也就表现为政党争取政权的斗争。为了搞清政党的性质，需要分析资本主义社会各个不同阶级的状况。从这个状况中产生出一定的阶级利益，而对这些利益的捍卫，正如我们所看到的，就决定了政党的实质。","language":"中文","translation":false},{"id":"communism-abc-5-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"地主-土地占有者。在资本主义发展的初期，他们的经济是以农民的半奴隶制劳动为基础的。他们把土地出租给农民，以此收取实物（例如，对分制劳动，在地主的庄园里劳动等等）或金钱。这种地主阶级关心的是不要让农民到城里去，它反对任何新事物，希望继续在农村保持落后的半奴隶制关系，所以它反对发展工业。这种地主拥有世袭的贵族庄园，他们本人多半不经营自己的农庄，而是骑在农民背上过着寄生生活。与这种状况相适应，地主的政党过去和现在始终是最黑暗的反动势力的支柱。这些政党希望在各地恢复旧秩序，维护地主的统治，地主的沙皇（君主），巩固“达官贵人”的优势，使农民和工人处于完全的奴隶地位。这就是人们所说的保守政党，或者更精确地说是反动政党。由于从来军人都出身于贵族地主，所以毫不奇怪，地主的政党和陆海军将军是最有交情的。世界各国都有这种情形。","language":"中文","translation":false},{"id":"communism-abc-5-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"普鲁士“容克阶级”（在德国把大地主称为容克）可以作为这种范例，军官团都来自容克阶级，而我们俄国的贵族，即所谓的野蛮地主或杜马代表——马尔柯夫第二、克鲁平斯基之类的“死硬派”也在此列。如果以沙皇的国务会议为例，那么可以看出，它的绝大部分成员恰恰是由这个地主阶级的代表组成。古老世袭的大地主一般都拥有各种不同的爵位，例如公爵、伯爵等等：他们都是曾拥有几千名农奴的祖先的继承者。俄国的地主政党有：俄罗斯人民同盟、“民族主义派”（以克鲁平斯基为首）、右派十月党人等等。","language":"中文","translation":false},{"id":"communism-abc-5-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"资本主义的资产阶级，它所关心的是要从正在发展的“本国工业”中获取更高的利润，也就是从工人阶级身上榨取更多的剩余价值。显然，它的利益和地主的利益并不完全一致。一旦资本侵入到农村，它就会破坏那里的旧关系；它会把农民从农村拉到城市里去，形成了城市里的庞大的无产阶级，并引起了农村新的需求；狂暴的“工匠”纷纷出现，从前温顺的农民开始“不安分”了。因此，所有这一切新事物都不合地主死硬派的心意。相反，资本主义的资产阶级却从中看到了自己的亨通的迹象。从农村吸引到城市里的工人越多，为资本家服务的雇佣劳动力就越多，劳动力的价钱也就越便宜；农村破产得越厉害，越是有更多的小业主停止生产自己需要的各种产品，他们就越是需要从大工厂主那里购买这一切；就是说，农村为自己的需要而生产一切的旧关系消失得越快，工厂商品的销售市场就越大，资本家阶级的利润就越高。","language":"中文","translation":false},{"id":"communism-abc-5-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"所以资本家阶级对老的地主提出抱怨（还有地主兼资本家，他们自己依靠雇佣劳动和机器经营自己的农庄；他们在自身的利益上更接近于资产阶级，并且一般都加入大资产阶级的政党）。但是，当然资产阶级的主要斗争是反对工人阶级。当工人阶级的斗争只是反对地主和很少反对资产阶级的时候，资产阶级是以非常赞许的眼光看待工人斗争的（例如，1904——1905年10月以前）。而当工人阶级实现自己的共产主义利益，并起来反对资产阶级的时候，资产阶级就联合起地主共同反对工人了。现在，全世界资本主义资产阶级政党（所谓的自由党）都在向革命的无产阶级进行疯狂的斗争，并正在组织一个总的反革命的政治参谋部。","language":"中文","translation":false},{"id":"communism-abc-5-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"在俄国，人民自由党或所谓“立宪民主党”，还有几乎消失了的“十月党”，就是这样的政党。工业资产阶级、资本主义地主、银行家，以及他们的卫士——大知识分子（教授、待遇优厚的律师和作家、工厂厂长），——组成了这个党的核心。1905年，这个党曾抱怨专制制度，但已经有些害怕工农了；二月革命以后，它就站到了所有反对工人阶级政党（布尔什维克共产党）的党派的最前列。1918年和1919年，立宪民主党领导了所有反对苏维埃政权的阴谋活动，参加了邓尼金和高尔察克将军的政府。总之，它成了黑暗反动势力的首领，并彻底和地主政党同流合污了。之所以发生这种情况，是因为在工人阶级的压力，大私有者们的所有派别集团都联合成一个黑暗的营垒，而为首的就是其中那个能量最大的党。","language":"中文","translation":false},{"id":"communism-abc-5-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"城市小资产阶级和小知识分子。这里包括手工业者、小店主、小公务员和小官吏。实质上这不是一个阶级，而是相当混杂的一部分人。所有这些人多少都受到资本的剥削，他们的工作常常超出了他们力所能及的程度。其中很多人在资本主义发展的过程中被毁灭了。然而，他们的劳动条件使他们大部分人都意识不到在资本主义制度下自己的状况是毫无希望的。以手工业者为例，他们象牛一样勤劳。资本运用种种方式剥削他们：高利贷者剥削他们；再者譬如，他们为之工作的商店也剥削他们，等等。但是手工业者却仍然觉得自己是“业主”：他们使用自己的工具劳动，他们表面上是“独立的”（虽然实际上他们周身被缠在资本主义的蜘蛛网上）；他们还希望自己“出人头地”（他们常常想：“一旦事业好转，我就可以为自己买这个买那个。”）；他们竭力不与工人接近，他们效仿的榜样不是工人，而是大业主，因为他们一心想成为这样的业主。所以说，尽管他穷得象教堂里的老鼠，但他们对待自己的剥削者却往往要比待工人阶级还要亲。小资产阶级政党常常打着“激进党”、“共和党”的旗号，有时也打着“社会党”的旗号（参看第二十二节）。要改变小业主的错误的立场是很难的：这不是他们的“罪过”，‘而是他们的不幸。","language":"中文","translation":false},{"id":"communism-abc-5-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"在俄国，小资产阶级政党比任何地方的小资产阶级政党都更善于给自己戴上社会主义的假面具。“人民社会党”、“社会民主党”部分孟什维克就是这样。不过，需要指出的是，社会革命党主要是力图依靠农村中的中农和富农分子。","language":"中文","translation":false},{"id":"communism-abc-5-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"农民。农村中农民所处的地位与城市里的小资产阶级很相似。他们实质上也不是一个阶级，因为他们在资本主义制度下，总是不断地分化到各个阶级中去。在任何一个村落里，经常有一些农民外出谋生，随后完全变成为无产者。另有一些人则爬上了富农的地位。农民中的中等分子，即所谓的中农，情况也很不稳定：一部分中农破产了，成为无马的农民，以后又成为雇农，成为作坊、工厂的工人；另一部分人时来运转，“成了事”，变为富人，成为“善于经营的农夫”，自己雇用工人，购置机器，一句话，成为企业主-资本家。所以可以说农民不是一个阶级。在农民中至少应当区分出三部分人：富农或剥削雇佣劳动的农业资产阶级；自己进行劳动，但不剥削雇佣劳动的中农；最后，半无产者和无产者。","language":"中文","translation":false},{"id":"communism-abc-5-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"不难理解，所有这些人由于他们的地位不同，所以对无产阶级和资产阶级之间的阶级斗争的看法也不同。富农一般是和资产阶级结盟，甚至常常和地主结盟（例如，在德国，所谓的“大农”和牧师及地主共同加入同一个组织；在瑞士、奥地利以及法国部分地区也是这种情况；在俄国，富农在1918年就已经开始支持所有的反革命阴谋）。半无产者和无产者阶层在他们同资产阶级和富农的斗争中自然支持工人。至于中农，这里情况要复杂得多。","language":"中文","translation":false},{"id":"communism-abc-5-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"假如中农能够很快明白，在资本主义制度下他们大多数人是没有出路的，只有少数人能挤进富农的行列，而其余的人则注定要过着半乞丐式的生活，那么他们就会坚决彻底支持工人。然而他们的不幸正在于他们同手工业者和一般城市小资产阶级的情况一样。每一个中农内心里都想出人头地、想发财致富。但另一方面，资本家、高利贷者、地主、富农又压迫他们。所以中农大多数在无产阶级和资产阶级之间摇来摆去。他们无论如何也不能完全站到工人的立场上来；但同时他们怕地主比怕火还厉害。","language":"中文","translation":false},{"id":"communism-abc-5-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"在我们俄国可以特别清楚地看到这种情况；中农支持工人反对地主富农；但事后又常常担心，要是实行“共产”，是否更坏，于是又去反对工人：富农对他们的引诱常常得逞；而当重新出现了地主（邓尼金、高尔察克）的危险时，他们又开始去支持工人。","language":"中文","translation":false},{"id":"communism-abc-5-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"这种情况也影响到政党的斗争。中农有时拥护工人政党（布尔什维克共产党），有时拥护富农和大农的政党——社会革命党。","language":"中文","translation":false},{"id":"communism-abc-5-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"工人阶级（无产阶级）是“除了他们的锁链以外而一无所失”的阶级。它不但受资本家的剥削，而且正如我们已经看到的那样，资本主义发展的过程使工人阶级团结起来，成为一股团结一致的，习惯于共同劳动和共同斗争的重要力量。所以工人阶级是资本主义社会中最先进的阶级。所以，只要有可能存在，工人阶级的政党就是最先进的、最革命的政党。","language":"中文","translation":false},{"id":"communism-abc-5-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"这个党的目标自然是共产主义革命。为了这个目标，无产阶级政党应该是毫不妥协的。它的任务不是和资产阶级讨价还价，而是推翻资产阶级，镇压资产阶级的反抗。它——这个政党——应该“揭露剥削者的利益和被剥削者的利益之间的不可调和的对立性（我们旧的纲领就是这样说的，孟什维克也是签了字的；可惜，他们完全忘记了这一点，而和资产阶级接吻去了）。","language":"中文","translation":false},{"id":"communism-abc-5-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"然而我们党对小资产阶级、城市非无产阶级的贫农和中农应该采取什么样的态度呢？","language":"中文","translation":false},{"id":"communism-abc-5-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"根据以上所说，我们的态度是很清楚的。我们应该千方百计地证明和解释，在资本主义制度下希望过上美好的生活——这是欺人之谈或是自我欺骗。我们应该耐心地和经常地向中农解释，他们应该坚决地投入到无产阶级的营垒中来，不怕任何困难，和无产阶级一起奋斗；我们必须指出，如果资产阶级胜利了，只有富农会得到好处，他们会变成新的地主。总而言之，我们应该号召所有的劳动人民同无产阶级团结一致，使所有的劳动人民转到工人阶级的观点上来。小资产阶级和中农充满着偏见，这些偏见是由他们的生活条件所造成的。我们的责任就是要揭露事物的真实状况：手工业者和劳动农民的状况在资本主义制度下，地主——老的（来自贵族）或者新的（来自富农）总是骑在他们的脖子上；只有在无产阶级胜利和巩固的条件下才能以新的方式改造生活。然而，无产阶级要想取得胜利，那就必须要有自己的组织、要有一个强有力的、团结的和坚决的党，所以我们应该号召所有那些向往这种新生活并学会按无产阶级思考方式和斗争的劳动人民加入我们的队伍。","language":"中文","translation":false},{"id":"communism-abc-5-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"从德国和俄国的例子可以看出，一个团结和战斗的共产党具有什么样的意义。德国无产阶级是很发达的。但是在战前却没有一个象俄国布尔什维克共产党这样的工人阶级的战斗政党。只是在战争期间卡尔·李卜克内西、罗莎·卢森堡同志等才开始组建单独的共产党。所以在1918年和1919年期间，尽管多次起义，德国工人却未能战胜资产阶级。在俄国就有一个这样不妥协的政党，这就是我们的政党。由于这样，俄国无产阶级就有了好的领导。正因为如此，尽管有各种各样的困难，俄国无产阶级却成了能够如此团结一致和如此迅速地取得胜利的第一个无产阶级。我们的党在这方面可以成为而且已经成为其他共产党的榜样。它的团结性和纪律性是遐迩皆知的。它确实是无产阶级革命的最有战斗性的、领导的党。","language":"中文","translation":false},{"id":"communism-abc-5-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第三章 共产主义和无产阶级专政","page":5,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/05.htm","text":"第三章书目：马克思和恩格斯《共产党宣言》。弗·伊林（列宁）《国家与革命》。格·普列汉诺夫《法国大革命一百周年》。亚·波格丹诺夫《经济学简明教程》。奥·倍倍尔《妇女和社会主义》（《未来国家》一章）。亚·波格丹诺夫《红星》（乌托邦）。科尔萨克《法律的社会和劳动的社会》（收在《现实主义世界概论》文集）。关于无政府主义，参看：斯·沃尔斯基《无政府主义的理论与实践》。叶·普列奥布拉任斯基《无政府主义和共产主义》。弗·巴扎罗夫《无政府主义的共产主义和马克思主义》。关于资本主义社会中的阶级，参看：卡·考茨基《阶级利益》。关于小资产阶级政党的特点，参看：马克思《路易·波拿巴的雾月十八日》。卡·马克思《德国的革命和反革命》，以及《法兰西内战》。","language":"中文","translation":false},{"id":"communism-abc-6-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-6-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"第四章 资本主义的发展如何导致共产主义革命","language":"中文","translation":false},{"id":"communism-abc-6-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"（帝国主义，战争和资本主义的崩溃）","language":"中文","translation":false},{"id":"communism-abc-6-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第二十六节 金融资本","language":"中文","translation":false},{"id":"communism-abc-6-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第二十七节 帝国主义","language":"中文","translation":false},{"id":"communism-abc-6-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第二十八节 军国主义","language":"中文","translation":false},{"id":"communism-abc-6-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第二十九节 帝国主义战争","language":"中文","translation":false},{"id":"communism-abc-6-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第 三十 节 国家资本主义和阶级","language":"中文","translation":false},{"id":"communism-abc-6-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第三十一节 资本主义的崩溃和工人阶级","language":"中文","translation":false},{"id":"communism-abc-6-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第三十二节 国内战争","language":"中文","translation":false},{"id":"communism-abc-6-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第三十三节 国内战争的形式及其耗费","language":"中文","translation":false},{"id":"communism-abc-6-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"· 第三十四节 全面解体还是共产主义","language":"中文","translation":false},{"id":"communism-abc-6-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"我们在上面看到，在各个企业之间经常不断地进行着争夺买主的残酷斗争，而在这个斗争中经常不断地取得胜利的是大企业主。由此就产生了这样一种情况：小业主纷纷毁灭和破产，而资本和整个生产集中在大资本家的手中（资本的积聚和集中）。到上一世纪八十年代，资本已经集中得相当可观了。还出现了大量的股份公司或“合营公司”来代替以前的单个企业主；不用说，这些“合营公司”也是资本家的公司。它们的用意是什么呢？它们是怎样出现的呢？回答是不困难的。在这以前，每一个新企业都必须一下子就拥有一笔很可观的资本。如果创办起一个资本不足的企业，那么这个企业极少有可能生存下去，因为势力强大和资本雄厚的竞争者即地工厂主会从四面八方把它包围起来。这就是说，一个新企业要想生存下去，要想不毁灭，而相反取得繁荣，那就必须一开始就建立在很大的规模上。而企业要想在很大的规模上创办起来，那只有立即为此筹措一笔数目很大的资本。股份公司正是由于这种需要而产生的。它的实质就在于，在这里，几个大资本家使用着小资本家的资本，甚至使用着一些非资本家（职员、农民、官吏等等）的小额储蓄。事情是这样的：每一个人付出自己的份额，即自己的“一股”或“几股”。他由此得到一张票证即“股票”，使他有权得到一定数量的收入。这样一来，一下子就从四面八方聚集起一笔数额很大的“股份资本”。","language":"中文","translation":false},{"id":"communism-abc-6-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"股份公司一出现，某些资产阶级学者和跟在他们身后的妥协派社会党人就开始说道，现在，一个新时代到来了：资本不再会引起一小撮资本家开始统治的局面了，相反地，每一个职员都能够用自己的储蓄购买股票因而也成为资本家了。说什么，资本变得愈来愈“民主”。最后资本家和工人之间的差别不经过任何革命就会消失。","language":"中文","translation":false},{"id":"communism-abc-6-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这一切都是纯粹的无稽之谈。实际上，情况完全相反。大资本家只不过是在利用小资本家达到自己的目的，资本集中的和比以前更快了，因为相互斗争的已经是巨大的股份企业了。","language":"中文","translation":false},{"id":"communism-abc-6-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"为什么大资本家-大股东事实上把小股东变成了自己的地地道道的奴仆，这是很容易理解的。小股东往往在外市，不能从几百里地以外地赶来参加股东大会。即便某些小股东赶来了，那他们也是没有组织的，象瞎狍一样乱撞一通，可是大股东是有组织的，总是执行着一个共同的计划，做他们想做的一切事情。经验证明，他们只要占有全部股份的三分之一，他们就足以成为整个企业的名副其实的和绝对的主人和支配者。","language":"中文","translation":false},{"id":"communism-abc-6-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"但是，资本的积聚和集中的发展并没有到此停止。近几十年来，出现了许多资本家财团即辛迪加（或卡特尔）和托拉斯代替个别企业主和个别股份公司。它们为什么会出现呢？这是一种什么组织呢？","language":"中文","translation":false},{"id":"communism-abc-6-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"我们假定，在某一个生产部门中，譬如说在织布或冶金部门中，小资本家已经消失了；只剩下五六家最大的企业，它们生产着几乎所有织布或冶金生产部门的商品。它们相互进行竞争，为此降低价格；因此所得的利润减少。现在我们假定，这些企业中有两家比其余各家势力更强和规模更大。这时它们就会把这种竞争进行到其余各家破产时为止。但是，假定它们的力量势均力敌：它们的生产规模一样，机器一样，工人数量大体一样，它们各自生产商品的费用也一样多。那时会出现什么样的结果呢？那时，谁也不会取得斗争的胜利，大家都同样精疲力竭，大家的利润都下降。于是资本家们就得出一个结论：我们为什么要彼此压低价格呢？联合起来共同掠夺公众岂不更好吗？要知道，只要我们联合起来，任何竞争都不会发生，全部商品在我们手中，我们就可以随意抬高价格。","language":"中文","translation":false},{"id":"communism-abc-6-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这样就产生了资本家财团即联合组织：辛迪加或托拉斯。辛迪加和托拉斯不同的地方在于：在组织辛迪加的时候，加入辛迪加的资本家们商定：不低于既定的价格出售商品，共同分配定货或者划分市场（你只在那里卖货，我只在这里卖货），等等。但是，在这里，辛迪加的董事会不能，譬如说关闭任何一个企业；每一个企业虽然加入财团，但是也还有一定程度的独立性。而在托拉斯的情况下，它们却联合得十分紧密，各个企业完全失去了自己的独立性：托拉斯的董事会可以关闭它，改组它，把它迁移到任何合适的地方，只要这样做对整个托拉斯有利，当然，这个企业的资本家仍会不断地处到自己的利润，甚至利润还在增多，但是，一切事情是由资本家紧密团结的财团即托拉斯主管的。","language":"中文","translation":false},{"id":"communism-abc-6-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"辛迪加和托拉斯几乎控制着全部市场。它们不害怕任何竞争，因为它们抑制了任何竞争。资本家的垄断即一个托拉斯的统治代替了竞争。[1]","language":"中文","translation":false},{"id":"communism-abc-6-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这样一来，资本的积聚和集中逐渐地消灭了竞争。竞争吞噬了自己。竞争发展得愈激烈，集中进行得就愈迅速，因为力量薄弱的资本家毁灭得更快了。结果，竞争引起的资本集中便消除了这种竞争。企业主垄断财团——辛迪加和托拉斯的统治代替了“自由竞赛”即自由竞争。","language":"中文","translation":false},{"id":"communism-abc-6-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"只要举几个例子便可以看出托拉斯和辛迪加的巨大势力。美国在1900年即二十世纪一开始，辛迪加生产所占比例是：纺织工业——百分之五十多，玻璃工业——百分之五十四，造纸工业——百分之六十，金属工业（钢铁除外）——百分之八十四，铁制件和钢铸件工业——百分之八十四，化学工业——百分之八十一，等等。不用说，现在辛迪加生产的比例会有更大的提高。实际上，现在辛迪加生产都集中在两个托拉斯手里：石油托拉斯和钢铁托拉斯；其余的都隶属于这两个托拉斯。德国在1913年之前，莱茵-威斯特伐利亚煤矿区（这有点象我国的顿涅茨矿区）的采煤量有百分之九十二点六是集中在一个辛迪加手里；钢铁辛迪加生产了几乎全国钢铁产品的一半；糖业托拉斯生产了国内销售额的百分之七十和国外销售额的百分之八十，等等。","language":"中文","translation":false},{"id":"communism-abc-6-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"俄国的许多部门也已经完全由辛迪加的老板们统治了。“煤炭”辛迪加的生产占整个顿涅茨煤矿产量的百分之六十；“五金”辛迪加联合了百分之八十八至九十三的生产企业。“屋顶制件公司”——百分之六十（瓦垄铁），“车厢公司”集中了十六个制造厂中的十四个厂，铜业辛迪加——百分之九十，糖业辛迪加——整个糖业生产（百分之百），等等。根据一位瑞士学者的统计，到二十世纪初，整个世界资本的一半已经掌握在辛迪加和托拉斯手里。","language":"中文","translation":false},{"id":"communism-abc-6-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"辛迪加和托拉斯不仅集中了同类的企业，而且愈来愈经常地出现同时包括几个生产部门的托拉斯。这是怎样产生的呢？","language":"中文","translation":false},{"id":"communism-abc-6-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"一切生产部门相互间首先是由买卖关系联结起来的。我们以铁矿石和煤生产为例。这里所生产的产品是炼铁厂和冶金厂的原料；而这些工厂——譬如说——还制造机器；这些机器是作为许多其他部门的生产资料，等等，等等。现在假定，我们这里有一家炼铁厂。它购买铁矿石和煤。就是说，它关心的是廉价买进铁矿石和煤。而如果矿石和煤是掌握在另一个辛迪加手中，这时该当如何呢？这时，一个辛迪加和另一个辛迪加之间就要展开斗争，结局或者是其中一个辛迪加取得胜利，或者是两者合并起来。无论是在前一种情况下或是在后一种情况下，都会产生把两个生产部门联合起来的新的辛迪加。不言而喻，这种联合可能不仅是两个部门，而且可能是三个以至十个部门。这种企业叫做综合（或“联合”）企业。","language":"中文","translation":false},{"id":"communism-abc-6-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这样一来，辛迪加和托拉斯不仅把个别部门组织起来，而且把不同类的生产结合在一个组织中，把一个生产部门同另一个、第三个、第四个……生产部门联合起来。以前，在一切生产部门中，企业主是彼此独立的，而全部生产分为几十万个小工场。到二十世纪初，这种生产已经集中在把很多生产部门组织起来的一些规模极其庞大的大托拉斯之中了。","language":"中文","translation":false},{"id":"communism-abc-6-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"各个生产部门之间的联系，不仅仅是通过建立“联合”企业的途径产生的。这里需要谈一谈比这种联合企业更重要的一种现象。这种现象就是银行的统治。","language":"中文","translation":false},{"id":"communism-abc-6-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"首先应当谈一谈这些银行。","language":"中文","translation":false},{"id":"communism-abc-6-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"我们已经看到，当资本的积聚和集中高度发展的时候，为了能够一下子建立起大规模的新企业，就出现了对资本的需要。这种需要也就是出现股份公司的原因。就是说，创办新企业需要数额愈来愈多的资本。","language":"中文","translation":false},{"id":"communism-abc-6-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"另一方面，我们看一看资本家怎样处理他获得的利润的。我们知道，他把一部分利润用于吃喝穿戴，一句话，花在自己身上，而另一部分则“积聚起来”。试问：他是怎样使用这笔钱的呢？他是不是随时都能够扩大自己的生产，把这一部分利润用到事业上去呢？不，不能够。其原因如下述。要知道，钱是不断地零散地到他手里的。卖掉一批商品，就有一笔钱进入钱柜，再卖一批商品，又得到一笔钱。显然，要用它们扩充企业，那是需要相当数额的。就是说，比方要购买新机器，在进款没有达到必要数额的时候，就需要等一等。而在这以前呢？在这以前，钱是不能利用的。钱不免要被闲置起来。不是一个或两个资本家的情况是这样，而在不同的时期所有的资本家都是这样，经常有一些游资。可是，在上面我们看到，存在着对资本的需求。一方面闲置着一笔笔剩余的钱，另一方面存在着对资本的需求。资本集中愈快，对大笔资本的需要就愈多，而游资的数目也就愈大。正是这种状况提高了银行的作用。为了不让钱空放着，资本家便把钱存入银行，而银行则把这些钱贷给那些需要钱来扩大旧企业或创办新企业的资本家。一些工业家把钱存入银行，银行把这些钱贷给另一些工业家。这些工业家用借到的资本去榨取剩余价值；剩余价值的一部分偿还银行；而银行则把所得的一部分付给存款人，一部分作为银行利润留给自己。整个机器便是这样一直转动着。","language":"中文","translation":false},{"id":"communism-abc-6-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"现在可以明白，为什么在资本主义统治的最近一个时期，银行的作用、它的意义、它的活动发展到空前的程度。银行吸收到数额愈来愈大的资本。银行也愈来愈多地把资本投入工业。银行资本经常地在工业中“活动”，它自己也日益成为工业资本。工业开始依赖银行，银行用资本来维持和供养工业。银行资本和工业资本结合起来。这种资本就叫做金融资本。就是说，金融资本是同工业资本结合起来的银行资本。","language":"中文","translation":false},{"id":"communism-abc-6-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"金融资本能通过银行在更大的规模上把所有的工业部门都联合起来，这是联合企业所比不了的，为什么呢？","language":"中文","translation":false},{"id":"communism-abc-6-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"假定说，我们前面有一家大银行。这家大银行把资本不是贷给（或者说“提供资金给”）一个企业，而是贷给很多企业或许多辛迪加。这样，它关心的事就是它们彼此不要吵架；它把它们联合起来，它实行的政策是要不断地把这些企业联合成一个整体，置于自己的领导之下，即银行的领导之下；银行开始统辖整个工业，统辖一系列的生产部门：银行的心腹人被任命为托拉斯、辛迪加、各企业的经理。","language":"中文","translation":false},{"id":"communism-abc-6-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"最后会出现这样一种局面：全国的工业联合为辛迪加、托拉斯、联合企业；所有这些都是由银行联合起来的；控制整个工业的一小撮最大的银行家左右全部经济生活，而国家政权则完全执行这些银行家和辛迪加大王的意志。","language":"中文","translation":false},{"id":"communism-abc-6-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"从美国的一个例子就可以非常清楚地看出这一点。美国威尔逊的“民主”政府是美国托拉斯的真正傀儡。议会只是通过那些在辛迪加老板和银行家的幕后的会议上早已决定的提案。托拉斯花费巨额金钱去贿买议员，进行选举活动等等。一个美国作家（迈尔斯）报道说：1904年“王惠”保险公司托拉斯用于贿买花费了三亿六千四百二十五万四千美元，“公平”——一亿七千二百六十九万八千美元，“纽约”——二亿零四百零一万九千美元，等等。威尔逊的女婿、财政部长麦卡杜就是一个大银行家和辛迪加老板。参议员、部长、议员——都是大托拉斯的职员或是股东。国家政权、“自由共和国”——这无非是勒索群众的一个事务场所。","language":"中文","translation":false},{"id":"communism-abc-6-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"因此，我们可以说，在金融资本的统治下，资本主义国家本身完全变为规模巨大的联合托拉斯，银行是它的首脑，资产阶级国家政权是它的执行委员会。美国、英国、法国、德国等等无非是一些国家资本主义托拉斯，是剥削和统治千百万工人、雇佣奴隶的辛迪加老板和银行家的强大组织。","language":"中文","translation":false},{"id":"communism-abc-6-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在个别国家里，金融资本在一定程度上能消除资本主义生产的无政府状态。相互争斗的各个企业不见了，一切都联合为国家资本主义托拉斯。","language":"中文","translation":false},{"id":"communism-abc-6-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"可是，那时资本主义的基本矛盾之一会是怎样的呢？要知道，我们不止一次地说过，资本主义是一定要垮台的，因为资本主义没有组织性，因为资本主义存在着阶级革命。但是，如果两个矛盾（见第十三节）中的一个矛盾消灭了，那么，关于资本主义灭亡的预言是不是没有根据了呢？","language":"中文","translation":false},{"id":"communism-abc-6-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这正是我们现在所探讨的主要之点，实际上生产的无政府状态和竞争并没有消除，或者说得更清楚些，它在一个地方消除了，而在另一个地方更尖锐地表现出来。我们现在就来详细地说明这个问题。","language":"中文","translation":false},{"id":"communism-abc-6-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"现在的资本主义是世界资本主义。一切国家都互相联系着：互相有买卖关系。现在地球上没有一块地方不受资本统治，没有一个国家可以自己生产所有的东西。","language":"中文","translation":false},{"id":"communism-abc-6-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"许多产品只能出产在一定的地区：寒带国家长不出橙子，地下不蕴藏铁矿的地方不可能采掘铁矿石。咖啡、可可、橡胶只出产在热带国家。棉花产在美国、印度、埃及、土耳其斯坦等地。从那些地方运往世界各地。英国、德国、美国、奥地利、俄国拥有煤矿；但是，例如意大利就没有煤，因而意大利完全依赖英国或德国的煤，如此等等。美国、印度、俄国、罗马尼亚向世界各国输出小麦。","language":"中文","translation":false},{"id":"communism-abc-6-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"另一方面，一些国家在自己的发展上远远走在前面，另一些国家则落在后面。所以，各种各样城市工业品由先进国家向落后国家抛售：向全世界供应铁制品的主要是英国、美国和德国；供应化学产品的首先是德国。","language":"中文","translation":false},{"id":"communism-abc-6-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这样，一个国家依赖另一个国家，向另一个国家购买或出卖产品。这种依赖关系可能达到什么程度，从英国的例子可以看出来。英国所需要的全部粮食的四分之三到五分之四，所需要的肉类数量的一半要靠输入，而它的工业品大部分却要输出国外。","language":"中文","translation":false},{"id":"communism-abc-6-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"现在我们提出这样的问题：金融资本能否消除世界市场上的竞争呢？它能否用各国资本家实行联合的办法建立起一个世界组织呢？这里一眼就可以看出，不能。在单个国家内，生产无政府和竞争所以能或多或少地停止下来，是因为各个最大的企业主联合为国家资本主义托拉斯。但是，各个国家资本主义托拉斯彼此之间的搏斗更加激烈了。要知道，在资本集中的情况下，情况总是这样的：当弱者毁灭的时候，竞争者的数目自然就会减少，因为只剩下强者；但是，这些强者又进行大规模的搏斗；最后托拉斯之间的斗争就会开始代替各个工厂主之间的竞争。托拉斯的数量当然比工厂主的数量少。但是，这里斗争的规模、激烈程度和破坏性却更大。而当一个国家的资本家把一切小资本挤垮而组织成为一个国家资本主义托拉斯的时候，那时竞争者的数目就更加缩减。但是，这些竞争者都是力量强大的资本主义大国。它们的竞争带来了空前未有的耗费和毁坏。因为，国家资本主义托拉斯的竞争在“和平”时期表现为军备竞赛，而最后则表现为毁灭性的战争。","language":"中文","translation":false},{"id":"communism-abc-6-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"可见，在单个国家里金融资本消灭了竞争，但是它在一定时期使这些国家彼此之间的竞争变得极端残酷。","language":"中文","translation":false},{"id":"communism-abc-6-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这是怎么发生的呢？为什么资本主义国家之间的这种竞争最终会导致掠夺政策，导致战争呢？为什么这种竞争不可能是和平的竞争呢？要知道，当两个工厂主彼此竞争的时候，他们不是拔刀相见，而是在和平斗争中争夺对方的买主。为什么世界市场上的竞争会成为如此残酷的和武力的竞争呢？对所有这些问题，需要给予详尽的答复。","language":"中文","translation":false},{"id":"communism-abc-6-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这里首先需要看一看，随着自由竞争盛行的旧资本主义向金融资本左右一切的新资本主义的过渡，资产阶级的政策应该发生怎样的改变。","language":"中文","translation":false},{"id":"communism-abc-6-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"我们从所谓的关税政策谈起。在国与国之间的斗争中，保护本国资本家的资产阶级政权，早就想出了关税这种斗争手段。比如说，如果俄国织布工厂的厂主害怕他们的英国或德国竞争者往俄国输出他们的商品，并使俄国的价格降低，那时，准备效劳的政府就对英国和德国的布匹课以关税。这自然就使外国商品难于进入俄国。工厂主们通常说，为了保护本国工业，关税是需要的。可是，如果现在仔细看一看不同的国家，那么，立即就可以看出，“这里是别有用意的”。事实上，近几十年来，提高关税的呼声最高和课税最重的是以美国为首的最强大国家的资本家。难道外国竞争者会欺负他们吗？“你是台柱子，谁能欺负你呢？是你欺负了别人！”","language":"中文","translation":false},{"id":"communism-abc-6-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"究竟是怎么一回事呢？事情原来是这样的。假定说，在某个国家里，织布生产是由织布业辛迪加或托拉斯垄断的。如果实行关税，那会怎样呢？那时，这个国家的组织辛迪加的资本家们就可以一箭双雕：第一，他们避开了外国的竞争；第二，他们可以不冒任何风险地把自己的商品价格几乎提高到关税所提高的程度。假定说，一俄尺布的关税提高了一卢布。那时，织布业辛迪加就可以大胆地把自己织出的每俄尺布再抬价一卢布或九十戈比。如果没有辛迪加，那么国内资本家之间的竞争就会立即使价格降低，如果辛迪加统治一切，那么它就可以放心大胆地加价：外国人进不来，因为关税壁垒加高了，而自己家里又没有竞争者。辛迪加的国家从关税中获得收入，而辛迪加本身从加价中得到额外利润。这种事情只有当存在辛迪加或托拉斯时才是可能的。但是，事情并不限于此。辛迪加老板由于掌握着这种附加利润，就可能向其他国家输出自己的商品，并在那里亏本出售，只要能够在异国挤走自己的竞争者就行。他们也是这样做的。例如，大家知道，俄国糖业辛迪加在俄国保持比较高的糖价，而在英国却卖得极其便宜只是为了能够在那里打垮自己的竞争者。甚至出现过这样的传闻：在英国用俄国糖来喂猪。这就是说，辛迪加利用关税可以尽力掠夺自己的同胞，以便把外国买主控制在自己手里。","language":"中文","translation":false},{"id":"communism-abc-6-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"从这一切产生重大的后果。实际上，现在可以清楚地看出，对辛迪加来说，可供剪毛和圈囿在关税界限之内的绵羊越多，额外利润就越多。如果关税界限包括的地域不大，那么所得利润就不会多。相反地，如果关税界限包括了人口众多的大量土地，那么就有利可图。那时额外利润就会很多，那时就可以大胆地在世界市场上活动，那时就有获得巨大成功的希望。但是关税的界限通常也就是国界，那么怎样来扩大这个国界呢？这意味着什么呢？这就意味着夺取一块别国的土地，把这块土地归为自己，把它划入自己的疆界，纳入自己的国家联邦。而这也就是战争。就是说，辛迪加老板的统治必然同侵略战争联系在一起。每一个强盗式的资本国家都力图“扩大自己的疆界”，因为辛迪加老板的利益，金融资本的利益要求这样做。扩大疆界不外就是进行战争。","language":"中文","translation":false},{"id":"communism-abc-6-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"由此可见，辛迪加和托拉斯的关税政策是同其在世界市场上的政策紧密相联的，它导致极其激烈的冲突。但是，这里还有其他原因在发生作用并促进战争。","language":"中文","translation":false},{"id":"communism-abc-6-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"我们看到，随着生产的发展，剩余价值经常不断地积累起来。因此，在每一个发达的资本主义国家里，过剩资本不断地增多，和在落后国家里相比，这种资本获得的利润要少一些。国内的过剩资本越多，输出资本即把资本投放到另一个国家的欲望就越强烈。关税政策也在极大程度上助长这种欲望。的确，关税对输入商品是很大的阻碍。譬如说，如果俄国工厂主对德国商品课以很重的关税，德国工厂主往俄国销售自己的商品就比较困难（当然，我们说的是在工厂主统治下的俄国，而不是在苏维埃政权领导下的俄国）。","language":"中文","translation":false},{"id":"communism-abc-6-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"但是，如果他们销售商品出现困难，那他们还有另外一条出路：那时德国资本家便开始往俄国输出自己的资本；他们建立各种工厂，购买俄国企业的股票或投资创办新的企业。关税妨碍这样做吗？一点也不妨碍。相反地，不仅不妨碍，而且有帮助，并成为资本输入的香饵。这是因为这个德国资本家在俄国办有工厂，并且的加入“俄国”辛迪加，这样俄国关税就在帮助他获得超额利润：俄国关税在掠夺公众方面对他是有好处的，就象对他的俄国同行是有好处的一样。","language":"中文","translation":false},{"id":"communism-abc-6-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"资本从一个国家输出到另一个国家，不仅仅是在另一个国家中创办和维持企业。它往往是按一定的利息贷给另一个国家的（就是说，另一个国家增加自己的国债，成为前一个国家的债务国）。在这种情况下，债务国通常也不得不向贷出货币资本的那个国家的企业主借各种借款（特别是军事借款）。于是，大量资本从一个国家流入另一个国家，一部分用于企业和工程，一部分成为国债。在金融资本统治下，资本输出（出口）达到惊人的程度。","language":"中文","translation":false},{"id":"communism-abc-6-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"我们引一些数字为例，这些数字现在看来已经过时了，但仍然可以告诉我们一些东西。法国到1902年在二十六个国家投资三百五十亿法郎，其中一半左右是贷款形式借给各国的。这笔钱很大一部分是投给俄国（一百亿）。顺便说一下，因此法国资产阶级非常痛恨我们废除了沙皇的债务和拒绝将其偿还给法国高利贷者。在1905年，输出的资本总额已经超过了四百亿。英国1911年在国外拥有约十六亿英镑（按战前的比值一英镑约为十卢布），如果算上英国的殖民地，那么，这个数目字就超过三十亿英镑。德国战前在国外拥有大约三百五十亿马克，等等。总之，每个资本主义国家输出巨额资本，都是为了借此掠夺别国人民。","language":"中文","translation":false},{"id":"communism-abc-6-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"资本输出会造成严重的后果。显然，各强国开始争夺它们想输出资本的那些地域或小国。而这里应当注意的地方恰恰就是这一点。当资本家往“别的”国家输出资本的时候，他们不是拿一批商品去冒险，而是拿为数几百万和几十亿的一大笔钱去冒险。不言而喻，因此他们产生强烈的欲望，要使他们投放这笔资本的小国完全受自己支配，强派自己的军队去保护这些资本。而这就是说，输出国家力图千方百计地把这些地方置于自己的国家政权的管辖之下，干脆强占这些地方，用武力加以吞并。由于各个强盗式的大国都袭击这些力量薄弱的地区，自然这些强盗最终必定会彼此发生冲突（而且已经发生了冲突）。这就是说，资本输出也导致了战争。","language":"中文","translation":false},{"id":"communism-abc-6-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"现在我们来看一看其他原因。不用说，随着实行辛迪加关税，争夺商品销售市场的斗争极度尖锐起来。从十九世纪末，可以运去自己的商品、没有任何资本家盘踞的自由土地几乎已经不存在了。诸如金属、羊毛、木材、煤炭、棉花等原料又大大涨价。最近整个时期都在发生争夺销售市场的疯狂角逐和争夺新的原料产地的斗争。资本家们四处寻找新的矿藏和新的市场，以便输出金属制品、布匹和其他商品，并掠夺新的“新鲜的”公众。从前，在一个国家中，往往只是几家公司在“和平地”竞争，关系不大，还处得下去。随着银行和托拉斯占据统治地位，情况自然就改变了。假定说，发现了新的铜矿。这些矿床立即就会被某一家银行或托拉斯控制起来。它把这些矿床完全攫为己有，开始独家占有它们。不会给其他国家的资本家留下分毫，真是“物从车上落，再也找不着”。不仅原料产地的情况是这样，销售市场的情况也是这样。假定说，一个外国资本渗入到某个遥远的殖民地。这里的商品销售马上就大规模地组织起来。通常依然是某家大公司把生意抓在自己手里，它立即开设自己的分公司，竭力通过对地方政权施加压力和使用各种各样的阴谋诡计来把全部销售业务夺到自己手中，加以垄断，而不容竞争者插手。这也是可以理解的，因为垄断资本即辛迪加和托拉斯是按辛迪圆满的方式行事的。这不是“过去的好时光”，这是垄断资本家强盗和敲诈勒索者的斗争。","language":"中文","translation":false},{"id":"communism-abc-6-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"因此，随着金融资本的发展，争夺销售市场和原料市场的斗争必然会尖锐起来，并引起最大规模的冲突。","language":"中文","translation":false},{"id":"communism-abc-6-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在十九世纪最后二十五年，几个大的强盗国家全力以赴地抢光了他人的、属于弱小民族的土地。从1876年至1914年，所谓的“大国”占据了大约二千五百万平方公里（一公里约等于一俄里）的土地；换句话说，他们抢劫到手的他人土地的总面积等于整个欧洲土地面积的两倍。整个世界已被几个大强盗瓜分完了，他们把所有的国家都变成了自己的殖民地、进贡者和奴隶。","language":"中文","translation":false},{"id":"communism-abc-6-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"请看几个例子。英国从1870年起在亚洲获得了俾路支、绚甸、塞浦路斯、北加里曼丹、威海卫、香港对面的一些地区，扩大了海峡殖民地，侵占了西奈半岛等等；在澳洲，它侵占了许多岛屿，新几内亚的东部、所罗门群岛的大部分、汤加岛等等；在非洲，它侵占了埃及、连同乌干达在内的苏丹、东非、“英属”索马里、桑给巴尔、奔巴岛；在战争中又并吞了两个布尔人的共和国、罗得西亚、“英属中非”，占据了尼日利亚等等一些地区。","language":"中文","translation":false},{"id":"communism-abc-6-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"法国从1870年起征服了安南、夺取了东京湾，并吞了老挝、突尼斯、科摩罗群岛、马达加斯加、撒哈拉沙漠的广大地区、苏丹、几内亚；获得了象牙海岸、达荷美、索马里等国的一些地方。结果，到二十世纪初，法国的殖民地几乎比法国本土大二十倍（英国的殖民地比英国本土大一百多倍）。","language":"中文","translation":false},{"id":"communism-abc-6-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"德国参与这种掠夺比较晚，大约从1884年开始，但是，在短短的时间内就已经抢夺了相当大的一片土地。","language":"中文","translation":false},{"id":"communism-abc-6-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"沙皇俄国也同样实行了大规模的掠夺政策，最后一个时期主要是在亚洲，它与从另一端着手掠夺的日本发生了冲突。","language":"中文","translation":false},{"id":"communism-abc-6-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"美国把美洲附近的很多岛屿攫为己有，然后开始在本大陆掠夺别国的财富。特别可恶的是它对墨西哥的掠夺政策。","language":"中文","translation":false},{"id":"communism-abc-6-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"总之，六大强国到1914年时，共拥有一千六百万平方公里的原有本国土和一百万平方公里的掠夺来的土地（殖民地）。","language":"中文","translation":false},{"id":"communism-abc-6-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这种抢劫者当然首先及于小国，即无力自卫和力量软弱的国家。它们最先毁灭。正如在工厂主和小手工业者之间的斗争中，这些小手工业者先于所有的人毁灭一样，大托拉斯国家，强盗式的有组织的大资本首先消灭了小国并使之隶属于自己。世界经济中的资本集中就是这样进行的：小国毁灭了，最大的强盗国家富足了，领土扩大了，势力增强了。","language":"中文","translation":false},{"id":"communism-abc-6-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"但是，当它们把全世界劫掠净尽的时候，当它们彼此之间的斗争加剧的时候，可以清楚地看出，强盗之间为重新分割世界而进行的大搏斗，余留下来的大强盗国家之间的你死我活的斗争就要开始了。","language":"中文","translation":false},{"id":"communism-abc-6-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"金融资本为争夺销售市场、原料市场和投资场所而实行的侵略政策就叫做帝国主义。帝国主义是由金融资本发展而来的。就象老虎不能吃草一样，金融资本过去和现在除了实行侵略、掠夺、暴力、战争的政策以外，不能实行另一种政策。每一个金融资本主义托拉斯国家实际上都想统治全世界，建立一个由战胜民族的一小撮资本家独霸的全球帝国。例如，英帝国主义者梦想建立一个统治全世界的“大不列颠”，由英国的辛迪加老板压榨黑人和俄罗斯人、德国人和中国人、印度人和亚美尼亚人，一句话，压榨千百万黑种人、黄种人、白种人和红种人奴隶。英国现在已经接近于这一目标。但是，劫掠得愈多，贪欲就愈大。其他国家也概莫能外。俄帝国主义者梦想建立一个“大德意志”，如此等等。“大”这个字的意思就是对其他一切国家进行卑鄙的掠夺。","language":"中文","translation":false},{"id":"communism-abc-6-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"由此可以清楚地看到，金融资本的统治必然会使全人类陷入血腥的深渊而使银行家和辛迪加老板得到好处，——这种战争不是保卫自己土地的战争，而是掠夺他人土地的战争，是战胜国的金融资本征服世界的战争。1914——1918年的第一次世界大战就是这种战争。","language":"中文","translation":false},{"id":"communism-abc-6-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"金融资本、银行家和辛迪加老板的统治还表现出一种引人注目的现象：军备费用，陆海空军的数量空前增加。这也是很自然的。过去，任何一个强盗头子都不敢梦想统治全世界。而现在，帝国主义者却认真地这样想了。从来还没有过这样强大的托拉斯国家之间的争斗。不言而喻，这些国家都相应地增加了这种争斗的武器，加强了它们的武装力量。列强不断地抢掠别国的财富，同时又经常环顾左右：邻国的强盗不会从后边咬我一口吧？因此，每一个强国必定要有军队，不仅对付殖民地和自己本国的工人，而且为了同劫掠中的伙伴作战。当一个强国采用了一种新式武器，别的强国也会马上急急忙忙赶上来，惟恐落后吃亏。于是开始了疯狂的军备竞赛：这一国追逐那一国。枪炮大王的大型企业和托拉斯，如普梯洛夫、克虏伯、阿姆斯特朗、维克斯等等，在不断发展。这些枪炮托拉斯赚取到巨额利润，同总参谋部勾结在一起，千方百计地火上浇油，使各种冲突更加激化。因为它们就是靠战争发财致富的。","language":"中文","translation":false},{"id":"communism-abc-6-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这就是战前资本主义社会的疯狂景象。各个托拉斯国家都在剑拔弩张，在陆地、水上和空中全都在为一场世界规模的大战作准备；陆海军费支出越来越被提到整个国家开支的首位上来。例如，英国1875年的军费支出为百分之三十八点六，也就是三分之一多一点，而在1907——1908年度就已经达百分之四十八点六，即差不多是整个国家开支的一半；美国1908年的军费支出是百分之五十六点九，即已超过了一半。其他国家也是如此。在所有大托拉斯国家里，“普鲁士军国主义”最为强盛。枪炮大王大发不义之财。而全世界则飞快地滑向最血腥的战争，滑向世界的帝国主义大战。","language":"中文","translation":false},{"id":"communism-abc-6-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"英德两国资产阶级的竞争是特别有趣的。从1912年起，德国每建造两艘装甲主力舰，英国就决定造三艘。1913年德国在北海大约有十七艘主力舰，英国有二十一艘；1916年德国有二十一艘；1916年德国有二十六艘，英国有三十六艘，等等。","language":"中文","translation":false},{"id":"communism-abc-6-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"陆海军军费支出的增加情况如下：","language":"中文","translation":false},{"id":"communism-abc-6-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"1888年 1908年 俄国 210 470 法国 300 415 德国 180 405 奥匈 100 200 意大利 75 120 英国 150 280 日本 7 90 美国 100 200","language":"中文","translation":false},{"id":"communism-abc-6-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在二十年[2]内军费支出增加了一倍，日本增加了十二倍。战争之前军备狂热更为变本加厉。法国1910年用于军需的开支是五亿零二百万卢布，1914年达到七亿四千万卢布；德国1906年是四亿七千八百万卢布，而1914年达到九亿四千三百万卢布，就是说八年间军费支出增加了一倍。英国军备费用增加得更厉害。1900年是四亿九千九百万卢布，1910年已经是六亿九千四百万卢布，而1914年达到了八亿零四百万卢布；1913年，英国单用于它的海军的支出就比各列强在1886年的海军支出总额还多；至于沙皇俄国，它在1892年用于军需的开支是二亿九千三百万卢布，1902年是四亿二千一百万卢布，1906年是五亿二千九百万卢布；1914年海军部的预算达到九亿七千五百万卢布。","language":"中文","translation":false},{"id":"communism-abc-6-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"军备支出耗费了大量的国民资金。例如，俄国为此花费了几乎整个费用支出的三分之一，而算上支付借款的利息就更多了。请看下面的数字：","language":"中文","translation":false},{"id":"communism-abc-6-77","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":77,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"沙皇俄国在每一百卢布中用于：","language":"中文","translation":false},{"id":"communism-abc-6-78","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":78,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"陆海军、还债 40卢布14戈比 国民教育 3卢布86戈比（仅占1/13！） 土地设施 4卢布6戈比（仅占1/10！） 管理、法院、外交、交通部门、商品和工业、财政等等 51卢布94戈比 总计 100卢布","language":"中文","translation":false},{"id":"communism-abc-6-79","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":79,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"其他国家的情形也是如此。我们拿“民主的”英国来说，1904年每一百卢布中用于：","language":"中文","translation":false},{"id":"communism-abc-6-80","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":80,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"陆军和海军 53卢布80戈比 共76卢布30戈比 偿还国债和借款利息 22卢布50戈比 民政机关 23卢布70戈比 总计 100卢布","language":"中文","translation":false},{"id":"communism-abc-6-81","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":81,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"第二十九节 帝国主义战争","language":"中文","translation":false},{"id":"communism-abc-6-82","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":82,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"从各“大国”实行的这种帝国主义政策中显然可以看出：迟早它们要发生冲突。十分明显，所有“大国”的这种掠夺政策正是战争的起因。现在只有傻瓜才相信，战争是由于塞尔维亚人打死了奥地利的皇太子或是德国进攻比利时而引起的。在战争初期，关于谁负有战争罪责问题，人们争论不休。德国资本家断言是俄国先进攻的，俄国商人则到处散布是德国先进攻的。英国人说，英国人说，英国打仗是为了保护受害的小比利时。在法国，人们用写文章、喊叫、唱歌来颂扬法国为保护英雄的比利时人民布表现出高尚行为。而与此同时，奥地利和德国散布说，奥地利和德国是为防止俄国哥萨克的进攻而进行神圣的自卫战争。","language":"中文","translation":false},{"id":"communism-abc-6-83","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":83,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"所有这些议论，自始自终都是欺骗劳动人民的谎言。资产阶级需要这种欺骗，为的是让士兵去打仗。资产阶级采用这种手法已不是第一次了。我们前边已经看到，辛迪加老板实行高关税，为的是掠夺自己的同胞，同时能更顺利地在别国市场上进行竞争。就是说，关税是他们的一种进攻手段。然而资产阶级却叫喊说，它要保护“本国工业”。关于战争的情况也是一样。帝国主义战争把世界置于金融资本的统治之下，其实质正在于在战争中它们全都是进攻者。现在这一点是再清楚不过了。沙皇的走狗说他们是“自卫”。可是，十月革命打开了内阁的秘密保险柜，证据确凿地说明，无论沙皇，还是克伦斯基都同英国人和法国人狼狈为奸，他们都进行了掠夺战争；他们想要攫取别国的君士但丁堡，洗劫土耳其和波斯，占领奥地利的加里西亚。现在这就象二二得四一样地明白了。","language":"中文","translation":false},{"id":"communism-abc-6-84","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":84,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"德国帝国主义者也彻底暴露了自己的真面目。只要回想一下布列斯特和约，回想一下他们在波兰、立陶苑、乌克兰、芬兰所干的掠夺行为就足够了。德国革命也有所揭露，我们现在确凿地知道德国为抢劫准备好了进攻，并梦想侵占几乎所有别国的殖民地和国土。","language":"中文","translation":false},{"id":"communism-abc-6-85","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":85,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"而“高尚的”协约国呢？它们现在已完全露出了马脚。它们利用凡尔赛人和约把德国抢劫一空，处以一千二百五十亿赔款，夺走了所有的舰队，并吞了所有的殖民地，攫取了几乎所有的机车，拉走了奶牛等等来作为对赔款的偿付，这样一来，自然谁也不再相信它们的高尚了。现在它们又从北方、从南方来掠夺俄国。这就是说，它们也是为了掠夺而作战。","language":"中文","translation":false},{"id":"communism-abc-6-86","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":86,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"所有这些，布尔什维克共产党人在战争的一开始就已经说过了。但那时很少有人相信。可是现在任何一个稍有头脑的人都看到了这一点。金融资本，这是一个贪婪的嗜血强盗，不论它是俄国的、德国的、法国的、日本的还是美国的。都是一路货色。","language":"中文","translation":false},{"id":"communism-abc-6-87","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":87,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"因此，谈论在帝国主义战争中这一些帝国主义者是有罪的，而另一些是无罪的；或者这一些帝国主义者是进攻的，而另一些是自卫的，这是荒唐可笑的。所有这些都是为了欺骗劳动人民而杜撰的。实际上，它们都有首先向弱小的殖民地人民发动了进攻，它们都抱有掠夺全世界和把全世界置于本国金融资本的统治之下的打算。","language":"中文","translation":false},{"id":"communism-abc-6-88","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":88,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"爆发的战争必定是世界战争。原因是很清楚的。因为我们知道，差不多全世界那时已被划分成地段，被各“大国”所瓜分，而列强彼此又联系在一起，处在同一个世界经济联系之中，所以战争波及到所有的人，波及到世界的两半球，这是毫不奇怪的。","language":"中文","translation":false},{"id":"communism-abc-6-89","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":89,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"英国、法国、意大利 、比利时、俄国、德国、奥匈、塞尔维亚、保加利亚、罗马尼亚、黑山、日本、中国，以及几十个其他小国——一句话，几乎所有的国家都被卷进了血的漩涡。地球上大约有十五亿人。这十五亿人都直接或间接地感受到了一小撮资本主义罪魁所带来的战争灾难。世界从来还没有见过在地球上有这样庞大的军队，这样可怕的杀人武器。世界上也从来没有见过这种资本势力。要知道，实际上英国和法国强迫为它们的财富去打仗的不仅有英国人和法国人，而且还有无数殖民地的黑种人、黄种人和其他人种的奴隶。“文明的”强盗几乎动用了吃人的野人，尽管这些野人也是受他们在意摆布的。所有这些都掩盖在最高尚的口号之下。","language":"中文","translation":false},{"id":"communism-abc-6-90","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":90,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"争夺殖民地的战争是1914年大战的前奏。这样的战争包括有：“文明的”列强远征中国；西美战争；1904年的俄日战争（为争夺朝鲜、旅顺、满洲等地）；1912年的意土战争（为争夺非洲的殖民地的黎波里）；二十世纪初的英布战争，当时“民主的”英国野蛮地扼杀了两个布尔共和国；战争有好几次的险些燃成大战火。为仅分非洲的领土险些引起英法战争（为争夺法索达），以后又险些引起德法战争（为争夺摩洛哥）；在同一时期为瓜分中亚细亚，沙皇俄国也几乎同英国交战。","language":"中文","translation":false},{"id":"communism-abc-6-91","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":91,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在第一次世界大战前夕，英国和德国为占有非洲、小亚细亚和巴尔干等地，发生了非常激烈的利益冲突。结果形成了这样的局势，指望从德国手里夺走亚尔萨斯—洛林的法国，想染指巴尔干和加里西亚的俄国都同英国站在一边了。强盗的德国帝国主义找到了奥匈为自己主要的同盟者。美帝国主义参战比较晚，因为它想在欧洲国家互相削弱之后坐收渔人之利。","language":"中文","translation":false},{"id":"communism-abc-6-92","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":92,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"除了军国主义以外，帝国主义列强之间最卑鄙的工具之一就是秘密外交。秘密外交采取秘密条约和阴谋手段，甚至不惜采取暗杀和爆炸等等。帝国主义战争的真正目的恰恰表现在那些秘密条约之中，一方面，是英国、法国和俄国之间有密约，另一方面，德国、奥匈、土耳其和保加利亚之间也有密约。在战争前夕，制造暗杀奥地利皇太子一事，大概协约国的秘密间谍不会不知道。但是，另一方面德国的外交丝毫也没有反对这件事，例如，德国帝国主义分子罗尔巴赫曾写道：“由于皇太子弗兰茨-斐迪兰被刺，反德大阴谋比预定的期限更早地找到了自己的结局，我们应当认为是一件好事。假若战争推迟两年，对于我们就困难得多。”只要能引起战争，德国挑衅分子甚至准备牺牲自己的王子；而英法俄的密探也决不会在暗杀之位王子面前表示手软。","language":"中文","translation":false},{"id":"communism-abc-6-93","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":93,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"第 三十 节 国家资本主义和阶级","language":"中文","translation":false},{"id":"communism-abc-6-94","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":94,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"进行帝国主义战争的特点不仅在于其规模和毁灭性后果，而且在于进行帝国主义战争的国家的整个经济都必定服从这事任务。从前资产阶级只要花钱就能够打仗。而世界战争的规模竟是那样巨大，交战国又是那样发达，以至于单单有钱是不够的。为了这场战争，要铸钢厂专门铸造一个比一个大的炮，要矿井采出的煤都用于战争，要使金属、布匹、皮料等等全部都用于战争。自然，在国家资本主义托拉斯中谁的生产和运输能更好地为战争服务，谁就有希望获胜。","language":"中文","translation":false},{"id":"communism-abc-6-95","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":95,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"究竟怎样才能达到这一点呢？很清楚，只有把全部生产集中起来才可能达到这一点。要想使生产顺利进行，就得组织得好，听军方即总参谋部的直接指示，准确地执行那些佩有带穗肩章和星形勋章的大人物的一切命令。","language":"中文","translation":false},{"id":"communism-abc-6-96","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":96,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"资产阶级怎样才能做到这一点呢？非常简单。为此，它必需把私人生产、各个私人辛迪加和托拉斯转交给它的资产阶级强盗国家来指挥。这在大战期间已经做到了。工业“动员起来了”，并且“军国主义化了”，也就是服从于国家和军事当局的指挥。有人会问：怎么回事？那时资产阶级不就失去收入了吗？要知道，那就是国有化。既然一切都交给了国家，那资产阶级干什么，它又怎么肯这样做呢？资产阶级却这样做了，这是事实。但是，这根本没有什么可奇怪的。因为在这里私人辛迪加反正不是交给工人国家，而是它们自己的帝国主义国家。而这又有什么可使资产阶级害怕的呢？它只不过是把财产从自己的这个口袋换到另一个口袋而已：财产绝不会的因此而有一点减少。","language":"中文","translation":false},{"id":"communism-abc-6-97","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":97,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"应当时刻记住国家的阶级性。国家不是什么超级的“第三势力”，而是彻头彻尾的阶级组织。如果是工人专政，这就是工人的组织。如果是资产阶级的统治，这就是那种象托拉斯或辛迪加一样的雇主的组织。","language":"中文","translation":false},{"id":"communism-abc-6-98","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":98,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"因此，资产阶级把私人辛迪加转交给自己的（不是无产阶级的，而是自己的强盗的、资本主义的）国家，它就等于没有失去任何东西。工厂主舒尔茨或者史密斯是从辛迪加的账房支取利润，还是从国家银行的钱柜里支取利润，那还不是完全一样吗？资产阶级没有受到一点损失。反而还得到了好处。它之所以处到了好处，是因为有了这种集中，军事机器的动作就更灵便，并且提高了在掠夺战争中获胜的可能性。","language":"中文","translation":false},{"id":"communism-abc-6-99","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":99,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"因而毫不奇怪，几乎所有资本主义国家在战时都开始用发展国家资本主义来代替私人辛迪加或托拉斯的资本主义。例如德国曾一度占了上风，并能够长时间地抵抗比自己强大得多的敌人的攻击，就是因为德国资产阶级把这种国家资本主义组织得很好的原故。","language":"中文","translation":false},{"id":"communism-abc-6-100","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":100,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"实现向国家资本主义过渡有各种方式，种种方法。最常见的是在生产和商业方面建立国家垄断制。这就是说，生产和商业变为国营，完全转到资产阶级国家手里。有时这种过渡不是一下子就完成的，而只是表现在某些部分里。这常常表现为由国家某一辛迪加或托拉斯的部分股票。","language":"中文","translation":false},{"id":"communism-abc-6-101","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":101,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"那时，这种企业就变成了半国营的、半私人的，资产阶级国家就在那里实行自己的政策。此外，甚至在那些还属于私人的企业里也实行了强制性的规章：譬如说，一些企业则必须按新法律向另一些企业购买商品，而这另一些企业则必须按一定的数量和规定的价格把商品卖给这些企业；国家还实行强制性的工作方法，指定材料等等，对所有的重要产品实行凭证供应制度。这样国家资本主义就发展起来，从而代替了私人资本主义。","language":"中文","translation":false},{"id":"communism-abc-6-102","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":102,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在国家资本主义制度下，资产阶级单独的组织被其统一的组织即资产阶级的国家所代替。例如，战前在资本主义国家里，除有资产阶级的国家组织以外，还有单独的辛迪加，托拉斯，企业主联合会，地主组织，资产阶级政党，资产阶级记者、学者、艺术家联合会，宗教协会，牧师联合会，青年白卫军团体，私人侦探局，等等。在国家资本主义制度下，所有这些单独的组织都同资产阶级国家融为一体，成为国家的分部，执行一个共同的计划，服从于“最高统帅部”：在矿井和工厂里人们所做的也就是总参谋部所要求做的；人们在报纸上发表的东西也就是总参谋部所要讲的；教堂里宣扬的也就是总参谋部的强盗们所需要的；人们画的、写的和唱的，都同一个总参谋部所吩咐的；发明机器、炮弹、武器、毒气，也都是总参谋部所需要的。因此，为了保证资产阶级的血腥而肮脏的赚钱生意，全部生活都“军国主义化了”。","language":"中文","translation":false},{"id":"communism-abc-6-103","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":103,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"国家资本主义意味着大资产阶级大大加强。犹如在工人专政下，在工人国家里，苏维埃政权、工会、共产党等等愈是齐心协力地合作，工人阶级就愈是有力量一样，在资产阶级专政下，所有的资产阶级组织彼此之间联系得愈是紧密，资产阶级也就愈有力量 。国家资本主义把戏这些组织集中起来并使之变成为统一组织的机关，从助长了资本的巨大势力的发展。这正是资产阶级专政的杰作。","language":"中文","translation":false},{"id":"communism-abc-6-104","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":104,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"战争期间在所有大资本主义国家里都产生了国家资本主义。在沙皇俄国本来也在开始产生（军事工业委员会、垄断制等等）。但是后来，俄国资产阶级被革命吓坏了，害怕国家政权连同生产一起落到无产阶级手里。所以二月革命以后，它不但不努力组织生产，而且对生产实行破坏和怠工。","language":"中文","translation":false},{"id":"communism-abc-6-105","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":105,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"我们看到，国家资本主义丝毫也不废除剥削制度，只是加强了资产阶级的势力。然而德国的谢德曼分子和其他妥协分子竟然鼓吹说，这种苦役般的生活就是社会主义。他们说，既然一切都是国家的，那就意味着是社会主义了。他们没有看到，这里国家不是无产阶级的，而是属于无产阶级凶恶的死敌和刽子手的。","language":"中文","translation":false},{"id":"communism-abc-6-106","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":106,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"国家资本主义把资产阶级团结起来和组织起来，加强了它的力量，自然也就大大削弱了工人阶级。工人在国家资本主义制度下变成了强盗国家的白人奴隶。他们没有罢工的权利，他们被动员起来和军国主义化了，任何反对战争的人立即以叛国罪论处；在很多国家里废除了来往自由，不允许从一个企业转到另一个企业，等等。“自由的”雇佣工人变成了农奴，他们注定要在战场上不是为自己的事业，而是为敌人的事业去送死；命定要拼命地工作，不是为自己，也不是为同伴，更不是为了孩子们，而是为了他们自己的压迫者。","language":"中文","translation":false},{"id":"communism-abc-6-107","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":107,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"第三十一节 资本主义的崩溃和工人阶级","language":"中文","translation":false},{"id":"communism-abc-6-108","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":108,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"由此可见，战争在初期促进了资本主义经济的集中和组织。辛迪加、银行、托拉斯、联合企业没有做到的事，国家资本主义在开始加紧地去做。它建立了一套调节生产和分配的机关。这样它也就在更大的程度上为无产阶级掌握集中化的大生产奠定了基础。","language":"中文","translation":false},{"id":"communism-abc-6-109","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":109,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"可是战争给工人阶级带来了沉重的负担，必定要引起无产阶级群众的愤怒。首先，这场战争是历史上所不曾有过的一架绞肉机。死尸的生产快得令人难以置信。无产阶级在战场上不断被消灭。根据一些统计，仅仅到1917年3月1日以前，打死、打伤和失踪的人数已达二千五百万人；到1918年1月1日为止，被打死的约有八百万。假设一个人平均重量是三普特，这就是说，资本家从1914年8月至1918年1月生产了二千四百万普特腐烂的人肉。为了精确地计算出人的损失，需要加上几百万病员。单单一项梅毒在战争期间就发展到了闻所未闻的程度，几乎传染了整个人类。人们经过战争以后都变得极度瘦弱；最健康的和有劳动能力的人，全民族的精华都被消灭了。显然，首先遭殃的是工人阶级和农民。","language":"中文","translation":false},{"id":"communism-abc-6-110","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":110,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在各交战国的大中心城市里甚至出现了许许多多严重畸形的、四肢不全的残废人的市区：这些已完全毁容，只剩下脑袋壳，戴着假面具的不幸的残废人是资产阶级文明的活生生的证据。","language":"中文","translation":false},{"id":"communism-abc-6-111","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":111,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"然而无产阶级不仅是在野蛮的战争中被宰割。活着的人还肩负着异常沉重的负担。战争需要巨额的费用。工厂主得到了惊人的好处，即所谓的“战争利润”，而工人却被课以重税，以偿付战争的损耗。战争的费用确实高得可怕。1919年秋，法国财政部长在和会上宣布，战争使各交战国耗费了一万零五十亿法郎。甚至不是任何人都理解这种说法的意义。过去人们把这种数字当作计算星际之间距离的天文数字。而现在竟用来计算罪恶的屠杀费用。一万亿——这是一百万个百万。这就是资本家们发动的战争所耗费的钱财。根据其他方面的计算，战争的费用如下：","language":"中文","translation":false},{"id":"communism-abc-6-112","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":112,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"（单位：十亿卢布） 战争第一年的价值 91 战争第二年的价值 136.5 战争第三年的价值 204.7 战争第四年的前半年（1917年7月31日——12月31日）的价值 153.5 总计 585.7","language":"中文","translation":false},{"id":"communism-abc-6-113","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":113,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"当然，从那时以后战争的费用更是不断增加，而且达到了骇人听闻的程度。要偿付这些费用。需要很大一笔款额。于是十分自然，资本主义国家对工人阶级课以相应的重税：或者以直接税形式，或者以商品税的形式，或者——有时也从资产阶级那里收取一点——以爱国名义来提高商品价格的形式。物价飞涨。而工厂主、特别是为战争而服务的工厂主却捞取了前所未有的利润。","language":"中文","translation":false},{"id":"communism-abc-6-114","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":114,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"俄国的工厂主把自己的红利增加了一倍多，个别企业获取了前所未有的利息。请看数字：米尔佐也夫兄弟石油工业公司——百分之四十的红利；达尼舍夫斯基兄弟股份公司——百分之三十；卡尔法烟厂——百分之三十等等。在德国，1913——1914年间，四个部门（化学，炸药、钢铁、汽车）的企业中的纯利是一亿三千三百万，1915——1916年，已经达到二亿五千九百万，就是说，一年间增加了一倍，美国钢铁托拉斯1916年上半年的利润超过了1915年上半年利润的两倍。1917年同1915年相比，利润从九千八百万美元增加到四亿七千八百万！利润率经常达到百分之二百。这样的例子可以举出很多。银行的利率也同样大大地增加了。在战争中，小企业主破产了，贪残的大剥削者却大发横财，而无产阶级则处于赋税和物价飞涨的压榨之下。","language":"中文","translation":false},{"id":"communism-abc-6-115","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":115,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"战争时期生产的主要产品有：榴霰弹、手榴弹、炸药、大炮、装甲车、飞机、毒气弹、火药等等。这些东西的生产是大量的。在美国，甚至在火药厂的附近发展起许多新的城市。这些城市是匆忙建立的，工厂也是仓促建成的，它们常常会被炸得飞上了天：这都是赶制火药和大把捞钱的原故。制造军火的工厂主们自然也就获得了巨大的利润，他们的事业进行得十分顺利。然而对于人民来说情况却因此而变得越来越坏。因为，那些可供吃、穿的物品的生产日益减少。火药和子弹可以用于射击和爆炸，但是绝不可能用于吃、穿。而交战国的全部力量都用于生产火药和其他杀人武器。正当的、有益的生产却不断消失。劳动力去当兵，整个工业都为战争服务。实用的商品越来越少。其后果则是饥饿和物价昂贵。粮食缺乏，煤炭缺乏。一切实用的物品都缺乏，并且是世界性的饥荒和世界性的衰竭，这就是罪恶的帝国主义战争的主要后果。","language":"中文","translation":false},{"id":"communism-abc-6-116","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":116,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"请看几个不同国家的例子。","language":"中文","translation":false},{"id":"communism-abc-6-117","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":117,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"法国的农业生产在战争的头几年减产的情况如下：","language":"中文","translation":false},{"id":"communism-abc-6-118","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":118,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"单位：公担 1914年 1916年 粮食 42 272 600 15 300 500 块根作物 46 639 000 15 860 000 经济作物 59 429 000 20 448 000 蔬菜 —— 374 500","language":"中文","translation":false},{"id":"communism-abc-6-119","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":119,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"英国的铁矿储量消耗如下：","language":"中文","translation":false},{"id":"communism-abc-6-120","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":120,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"（1吨=61普特） 1912年年底 241千吨 1913年年底 138千吨 1914年年底 108千吨 1915年年底 113千吨 1916年年底 3千吨 1917年年底 0.6千吨","language":"中文","translation":false},{"id":"communism-abc-6-121","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":121,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"换句话说，铁矿储量到1917年年底已经耗尽了。","language":"中文","translation":false},{"id":"communism-abc-6-122","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":122,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"德国1913年的熔铁量是一千九百三十万吨；1916年已经只有一千三百三十万吨了；1917年——一千三百一十万吨；1918年——一千二百万吨，而1919年则更少了。","language":"中文","translation":false},{"id":"communism-abc-6-123","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":123,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"全世界工业极不景气的状况是由于缺煤矿所造成的。在欧洲，英国是煤炭的供应者。而英国到1918年中采煤量已经减少了百分之十三；1917年实用工业几乎没有煤：电机厂得到的煤比所需要的少六分之五，纺织企业——比战前少十一分之十。到凡尔赛“和”会时，几乎所有国家都处于可怕的煤炭危机之中：工厂因燃料不足而关闭，铁路运输也减少了。这样就出现了整个工业和运输业的大破坏。俄国也是同样的情形。1917年，战争已经使煤炭的情况糟透了。莫斯科地区每月需要一千二百万普特煤。克伦斯基政府只答应提供六百万（标准的一半）普特。而实际得到多少呢？1月——一百八十万普特，2月——一百三十万普特，3月——八十万普特。毫不奇怪，俄国的工业不“炸”自毁了，因为象全世界一样，资本主义的解体开始了。1917年（在克伦斯基的统治下），俄国关闭的工厂数目如下：","language":"中文","translation":false},{"id":"communism-abc-6-124","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":124,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"月 份 企 业 数 工 人 数 3月 74 6646 4月 55 2816 5月 108 8701 6月 125 38455 7月 206 47754","language":"中文","translation":false},{"id":"communism-abc-6-125","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":125,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"要了解由于商品的奇缺和大量发行纸币而引起的物价上涨，只要看一看受战争破坏最少的国家——英国就足够了。","language":"中文","translation":false},{"id":"communism-abc-6-126","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":126,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"下面就是五种主要产品（茶、糖、油、面包、肉）的平均价格：","language":"中文","translation":false},{"id":"communism-abc-6-127","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":127,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"茶、糖 面包、肉、油 1901——1905年平均价格 500 300 1914年7月底 579 350 1915年1月底 786 413 1916年1月底 946.5 465 1917年1月底 1310 561 1918年1月底 1221.5 681 1918年5月底 1247 777.5","language":"中文","translation":false},{"id":"communism-abc-6-128","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":128,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"战争期间，甚至英国的物价上涨了一倍多，而同一时期工资总共增长了百分之十八。就是说，物价上涨的速度比工人工资增长的速度快五倍。这就是英国的情况，而其他国家还要糟糕。特别是俄国的情况更坏，战争使国家破产，变成了一个衣不遮体、皮包骨头、向资本家老爷乞讨的老太婆。","language":"中文","translation":false},{"id":"communism-abc-6-129","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":129,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"甚至在受战争破坏最小的美国，从1913年至1918年，十五种主要产品的价格也上涨百分之一百六十，而工资在这期间仅仅增加百分之八十。","language":"中文","translation":false},{"id":"communism-abc-6-130","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":130,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"结果，由于没有煤，没有钢和其他一切必需品，军事生产也开始破产，世界各国除美国以外，都陷于极端贫困的境地：饥饿、破产、寒冷几乎遍及全球。十分清楚，所有这些灾难都极其严重地影响到工人阶级的状况，工人阶级曾试图反抗。但是战争把资产阶级强盗国家的全部力量都用来压迫工人阶级。工人阶级在世界各国——君主制国家和共和制国家——遭到了前所未有的迫害。工人不但被剥夺了罢工的权利，而且一有反抗就惨遭镇压。这样一来，资本主义的统治就引起了阶级之间的国内战争。","language":"中文","translation":false},{"id":"communism-abc-6-131","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":131,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"工人在战争期间遭受的迫害，在第三国际关于白色恐怖的决议中有很详细的描述，其中说：“战争一开始，统治阶级就使一千多万人死于沙场，使更多的人成为残废，并在国内建立了血腥的（资产阶级的）独裁制度。俄国沙皇政府枪杀和绞死工人，煸起排犹暴行，在国内进行窒息一切生灵的活动；奥地利帝国使乌克兰和捷克工人和农民的起义淹没在血泊中；英国资产阶级杀害了爱尔兰人民的优秀代表；德国帝国主义在国内兽性大作，革命海员是这帮助野兽的第一批牺牲者；在法国，不愿保卫法国银行家利益的俄国士兵惨遭枪杀；在美国，资产阶级对国际主义者用私刑加以杀害，叛处优秀的无产阶级代表人物以二十年苦役，枪杀罢工的工人。”","language":"中文","translation":false},{"id":"communism-abc-6-132","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":132,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"资本主义制度开始四分五裂了。生产的无政府状态引起了战争，战争又使阶级矛盾空前激化：于是战争引起革命。资本主义开始从两个基本方面（参看第十三节）倒垮。资本主义崩溃的时代到来了。","language":"中文","translation":false},{"id":"communism-abc-6-133","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":133,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"让我们更详细地看一看这种崩溃。","language":"中文","translation":false},{"id":"communism-abc-6-134","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":134,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"资本主义社会的一切部分都是按照同一个模式构成的：工厂组织得就象一个机关或者帝国主义军队的一个团：上层是发号施令的富人，下层是俯仰由人的穷人、工人和小职员；在这两层人之间是工程师、军士、中级职员。由此可见，资本主义社会的存在，只能是在工人士兵听命于地主将军或者军官，即贵族或资产阶级长孙的时候；只能是在机关里的听差服从于有钱的长官的时候；只能是在工厂的工人执行高薪的经理先生或者榨取工人剩余价值的厂主本人的命令的时候。但是，只要劳动群众意识到他们只是自己敌人手中随意支使的小卒，那系在士兵和将军，工人和工厂主之间的绳索就要开始挣断了。工人不再听从工厂主，士兵不再服从军官，小职员也不再听从自己有钱的长官了。富人统治穷人、资产阶级任意摆布无产阶级的旧纪律解体的时期来到了。这个时期必然一直延续到新的阶级——无产阶级使资产阶级服从于自己，迫使资产阶级为劳动人民服务，整顿好新的纪律的时候为止。","language":"中文","translation":false},{"id":"communism-abc-6-135","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":135,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"旧制度被破坏，而新制度还没有整顿好的这种混乱，只有随着无产阶级在国内战争中的完全胜利才会结束。","language":"中文","translation":false},{"id":"communism-abc-6-136","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":136,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"国内战争是当阶级斗争转变为革命时的一种激烈的阶级斗争。资产阶级各集团间为瓜分和重分世界的世界帝国主义战争通过资本的奴隶之手进行的。然而由于战争给工人带来了如此沉重的负担，这就使阶级斗争变为被压迫者反抗压迫者的国内战争，马克思把这种战争开始称为唯一正义的战争。","language":"中文","translation":false},{"id":"communism-abc-6-137","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":137,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"资本主义引起了国内战争，资产阶级国家之间的帝国主义战争变成了阶级之间的战争，这是十分自然的。还在战争一开始，即在1914年，当任何人还没有想过革命的时候，我们的党就预言过这一点。很清楚，战争加给工人阶级的前所未有的沉重负担激起了无产阶级的愤怒。而另一方面，很清楚，资产阶级不可能提供任何巩固的和平，因为这些掠夺者的各个集团之间存在着极其严重的利益冲突。","language":"中文","translation":false},{"id":"communism-abc-6-138","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":138,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这一切现在已完全被证实了。经过一段可怕的屠杀、兽行和野蛮的岁月之后，反抗压迫者的国内战争开始了。1917年2月和10月，俄国革命掀起了这种战争；芬兰革命，匈牙利革命，奥地利和德国革命继续了这种战争；以后其他国家的革命也开始了……而此时，资产阶级显然已不可能提供巩固的和平。协约国在1918年11月就已战胜了德国；而凡尔赛的掠夺和约只是经过好几个月以后才签订的；什么时候和约才会得到最后赞同——谁也不知道。大家都看到，这个凡尔赛和约是不牢靠的：和约签订之后，南斯拉夫人和意大利人，波兰人和捷克斯洛伐克人，波兰人和立陶苑人，拉脱维亚人和德国人彼此之间都打过仗。而随后，所有的资产阶级国家又一起进攻胜利了的俄罗斯工人共和国。这样，帝国主义战争就以国内战争而告终，无产阶级一定会成为国内战争的胜利者。","language":"中文","translation":false},{"id":"communism-abc-6-139","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":139,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"国内战争并不是某一个政党一时的心血来潮或某种偶然性：国内战争是革命的表现，革命是必定要发生的，因为帝国主义的掠夺战争最终擦亮了广大群众的眼睛。","language":"中文","translation":false},{"id":"communism-abc-6-140","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":140,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"如果认为可以有没有国内战争的革命，那就同认为可以有“和平的”革命是一样的。谁这样认为（例如叫喊国内战争有害论的孟什维克就是这样认为），谁就从马克思那里倒退到原始的社会主义者那里去了，这些人认为对工厂主可以规劝。这就等于用“爱抚”去劝告老虎吃青草，而不要去碰小牛。马克思是国内战争即无产阶级手持武器同资产阶级斗争的拥护者。关于巴黎公社（1871年巴黎工人的起义），马克思写道，公社社员们不够坚决。马克思在他写的第一国际的宣言中责备说：","language":"中文","translation":false},{"id":"communism-abc-6-141","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":141,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"“对市警不但没有予以应有的处置——解除武装或逮捕下狱，反而给他们洞开了巴黎城门，让他们逃到凡尔赛马去。对‘秩序人物’（所谓反革命分子）不仅毛发未动，而且容许他们巩固了在巴黎正中心的很多重要阵地。”[3]……“当梯也尔（法国的邓尼金）……发动了内战的时候，中央委员会竟坚决不肯把这个内战继续下去，因而犯了一个致命性的错误：本来应该立即向……凡尔赛进军，一举彻底消灭梯也尔及‘地主议会’的阴谋。中央委员会没有这样做，反而使秩序党能够在3月26日的公社选举中再次进行较量。”[4]在这里，马克思明确主张在内战中以武装粉碎白卫军。恩格斯也写道：“要是巴黎公社不依靠对付资产阶级的武装人民这个权威，它能支持一天以上吗？反过来说，难道我们没有理由责备公社把这个权威用得太少了吗？”恩格斯给革命下了这样的定义：“革命无疑是天下最权威的东西。革命就是一部分人用枪杆、刺刀、大炮强迫另一部分人接受自己的意志。”[5]","language":"中文","translation":false},{"id":"communism-abc-6-142","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":142,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"可见，社会主义的导师们对待革命是非常严肃的。他们懂得，无产阶级不能劝服资产阶级；懂得，无产阶级必须通过在运用“枪杆、刺刀和大炮”的内战中取得的胜利来强迫它接受自己的意志。。","language":"中文","translation":false},{"id":"communism-abc-6-143","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":143,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"国内战争使资本主义社会利益相反的阶级手握武器相互对抗。资本主义社会被分成两部分的情况，即实质上它至少是两个社会的这种情况，平时是被掩盖着的。为什么？因为奴隶对自己的主人只能默默地俯首听命。在国内战争时，这种沉默结束了，社会上被压迫的一部分人起来反抗压迫者了。不言而喻，在这种情况下，任何一种阶级之间的“和平共处”都是不可能的，因为军队分成了贵族、资产阶级、有钱的知识分子等等组成的白卫军和由工人与农民组成的红军。这样，工厂主和工人共聚一堂的任何立宪会议都不可能存在。因为当他们在大街上相互枪击的时候，他们怎么能“和平地”坐在立宪会议上呢？国内战争时期，是一个阶级对抗另一个阶级。因此，内战不是以这个阶级的完全胜利，就是以另一阶级的完全胜利而告终，而不是以妥协、以任何折中的办法告终。我们看到的俄国和其他国家（德国、匈牙利）国内战争的情形就完全证实了这一点：现在只能或是无产阶级的专政，或是资产阶级和将军们的专政。中间阶级及其政党（社会革命党、孟什维克等等）的政府只不过是向这一方或那一方过渡的桥梁而已。孟什维克帮助推翻了匈牙利的苏维埃政府，——立即出来代替这个政府的是一个所谓的“联盟”，后来又是旧的君主制度；立宪-社会革命党人当时成功地夺取了乌法、外伏尔加、西伯利亚，——但在二十四小时之内，他们就被以大资产阶级和大地主为靠山的高尔察克将军赶跑了。高尔察克自己用建立地主资产阶级的专政来代替了工农专政。","language":"中文","translation":false},{"id":"communism-abc-6-144","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":144,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"对敌人的决定性胜利和无产阶级专政的实现，——这就是世界上国内战争的必然结果。","language":"中文","translation":false},{"id":"communism-abc-6-145","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":145,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"第三十三节 国内战争的形式及其耗费","language":"中文","translation":false},{"id":"communism-abc-6-146","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":146,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"俄国革命开创了国内战争的时代。而俄国革命只是整个世界革命的表现、开始。革命在俄国比在其他国家开始得早，因为资本主义的瓦解在这里开始得早。俄国资产阶级和俄国地主梦想得到君士但丁堡和加里西亚，并同其他国家一起于1914年挑起了血腥的战争，但是由于其本身的虚弱和涣散，他们早早地就垮台了：崩溃出现得早，饥荒出现得也早。因此，正是在俄国无产阶级能比较容易地战胜自己的敌人，所以俄国无产阶级第一个取得了胜利，第一个实现了自己的专政。","language":"中文","translation":false},{"id":"communism-abc-6-147","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":147,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这绝不是说，俄国的共产主义革命是世界上最完备的革命，资本主义越不发达就越革命，国家就越接近共产主义。如果这样推论，那社会主义首先应在中国、波斯、土耳其等几乎根本没有无产阶级的国家里完全实现。而这样，马克思的全部学说也就是不正确的了。","language":"中文","translation":false},{"id":"communism-abc-6-148","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":148,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"谁这样推论，谁就是混淆了两个问题：一个是革命的开始，另一个是它的性质、它的“完备性”。革命在俄国开始得早，是由于我国资本主义的发展薄弱。但是正由于这种薄弱，由于我国是落后的国家，无产阶级占少数，有很多小商贩等等，我们组织公有的共产主义经济就很困难。在英国，革命会来得晚一些，但是，那里的无产阶级在取得胜利之后，组织共产主义会更快一些，因为无产阶级占绝大多数，它习惯于共同劳动，那里的生产无比集中。这就是说，革命在英国会开始得晚一些，但是它要比我国的革命更高一些，更完备一些。","language":"中文","translation":false},{"id":"communism-abc-6-149","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":149,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"很多人认为，国内战争之所以那样残酷，是由于俄罗斯的“亚细亚性”、俄国的落后性。西欧的革命反对派常常说，俄国盛行“亚细亚式的社会主义”，而文明国家的革命将会避免残酷性。但是，这显然是无稽之谈。在发达的资本主义国家里，资产阶级的反抗必定更强烈；在这样的国家里，知识分子（技术员、工程师、军官等等）同资本的联系更紧密，因此也就更仇视共产主义；就是说，这些国家的国内战争必然要比俄国的国内战争更激烈。确实，德国的革命也已经证明，那里的斗争采取了更多的流血形式。","language":"中文","translation":false},{"id":"communism-abc-6-150","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":150,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"抱怨布尔什维克恐怖的人忘记了，为了保护自己的钱财，资产阶级是不顾一切的。共产国际代表大会的决议曾就这一点说过：“当帝国主义战争已开始转变为国内战争，当它们的整个血腥制度已濒于灭亡的时候，这些人类历史上绝无仅有的穷凶极恶的统治阶级变得更加疯狂残暴……俄国的将军们，这个沙皇制度的活生生的体现者，他们在社会党叛徒的直接或间接支持下还在继续成批地枪杀工人。在社会革命党和孟什维克统治时期成千上万的工人和农民被投进监狱，将军们借口不听指挥而杀害整团的士兵。现在，克拉斯诺夫和邓尼金在协约国的大力资助下，为了杀掉‘十分之一’，打死和绞杀了成千上万的工人，在绞架上悬尸三天以儆效尤。在乌拉尔和伏尔加河流域，捷克斯洛伐克白匪砍掉被俘者的四肢，把他们投入伏尔加河，或实行活埋。在西伯利亚，沙皇的将军们杀死了成千的共产党人和无数的工人和农民。","language":"中文","translation":false},{"id":"communism-abc-6-151","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":151,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"德国和奥地利的资产者充分暴露了他们的野蛮，他们在乌克兰用铁制的流动绞架绞杀被他们掠夺一空的工人和农民、共产党人、他们自己的同胞——我们的奥地利和德国同志。在芬兰这个资产阶级民主主义的国家里，他们帮助芬兰资产者杀害了一万三千至一万四千名无产者，在监狱里折磨死一万五千人。在赫尔辛福斯，他们把妇女和儿童驱赶在自己前面，用以阻挡机枪的扫射。在他们的支持下，芬兰白匪军和瑞典走狗对被战胜的芬兰无产阶级进行了疯狂的捉弄。在塔墨尔福斯，他们强迫被叛死刑的妇女和儿童自挖墓穴。在维堡，他们杀害了几千名俄国男人、女人和儿童。","language":"中文","translation":false},{"id":"communism-abc-6-152","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":152,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"德国资产者和德国社会民主党人在国内对共产主义工人起义实行血腥镇压，野蛮地杀害了李卜克内西和卢森堡，屠杀斯巴达克工人，表明他们的反动狂已经达到了登峰造极的程度。集体和个人的白色恐怖——这就是资产阶级高举的一面旗帜。","language":"中文","translation":false},{"id":"communism-abc-6-153","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":153,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"其他各国的情况也是如此。在民主的瑞士，工人如果胆敢触犯资本主义法律，那就要受到惩治。在美国，隔离、私刑和电椅成为民主和自由最文雅的象征。在匈牙利和英国，在捷克和波兰。到处都是这种情况。资产阶级的刽子手们是没有任何羞耻可言的。他们为了巩固自己的统治而鼓吹沙文主义，对犹太人进行骇人听闻的摧残和蹂躏，远远超过了沙皇警察的排犹暴行……波兰反动的‘社会主义’流氓杀害了俄国红十字会的代表，这在垂死的资产阶级的食人罪恶和残暴行为中，只是沧海一粟。","language":"中文","translation":false},{"id":"communism-abc-6-154","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":154,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"随着国内战争的发展，战争也采取了一些新的形式。当各国的无产阶级都受到压迫时，他们就会把这场战争变成一种反对资产阶级国家政权的起义。但是现在无产阶级在某一国家获得了胜利并夺取了国家政权，在这种场合下会出现什么情况呢？那时，为无产阶级服务的就会有一个有组织的国家暴力，无产阶级军队，全部政权机关。那时，无产阶级就会同组织阴谋暴动的本国资产阶级进行斗争。但那时无产阶级是作为一个国家来同资产阶级国家进行斗争的。当无产阶级国家同资产阶级国家作斗争的时候，国内战争就采取了新的形式，即真正的阶级战争的形式；这里不单单是工人反抗资产阶级的起义，而是工人国家同资本的帝国主义国家进行正义的战争。这种战争不是为了掠夺别国，而是为了共产主义的胜利，为了工人阶级的专政。","language":"中文","translation":false},{"id":"communism-abc-6-155","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":155,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"实际情况正是如此。俄国十月革命之后，全世界各国的资本家（德国和法国的，美国的和日本的等等）对俄国苏维埃政权进行了全面的进攻。俄国革命的榜样对其他国家工人的影响愈大，整个国际资本就愈加紧密地联合起来反对革命，并企图建立资本家的强盗联盟来反对无产阶级。","language":"中文","translation":false},{"id":"communism-abc-6-156","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":156,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"根据狡猾奸诈的美国资本的首脑威尔逊的倡议，资本家们在所谓的凡尔赛和会上实现了这一企图。他们把这个强盗联盟称为“国际联盟”，即“各民族联盟”。实际上这不是各民族的联盟，而是各资本家及其国家政权的联盟。","language":"中文","translation":false},{"id":"communism-abc-6-157","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":157,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"这种联盟等于要建立一个世界大托拉斯来征服我们整个地球，剥削全世界，并且到处残酷地镇压工人阶级的愤懑和革命。关于这个联盟的成立是为了和平事业的说法纯属无稽之谈。它的真正目的有两个：无情地剥削全世界的无产阶级、所有的殖民地及殖民地奴隶，破坏正在发展的世界革命。","language":"中文","translation":false},{"id":"communism-abc-6-158","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":158,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在“国际联盟”中居领导地位的是在战争期间大发横财的美国。美国现在成了欧洲所有资产阶级国家的债权人。美国是有势力的，还因为它有原料、燃料和粮食。因此，美国想使所有其他强盗国家都归顺自己。它在“国际联盟”中的领导作用得到了保证。","language":"中文","translation":false},{"id":"communism-abc-6-159","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":159,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"有趣的是美国标准的强盗政策都冠以各种高尚的名称。它进行掠夺性战争打的是拯救人类、帮助弱小民族等等的旗号。支解欧洲，把欧洲分成十几个表面上“独立的”，但在实际上依附于美国的国家，这本来是对美国有利的。而这种利益却被戴上“民族自决”的高雅面具。资本主义的宪兵，即白卫军和警察，按照威尔逊的思想，本来是为了扼杀各地的革命，而名义上却说是为了惩罚“破坏和平”行为。1919年，所有帝国主义者突然摇身一变，都成了和平的爱好者，并开始嚎叫说，真正的帝国主义者和和平的敌人是布尔什维克。在这里，直接摧残革命者的活动都是在“和平”与“民主”的幌子下进行的。","language":"中文","translation":false},{"id":"communism-abc-6-160","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":160,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"“国际联盟”已经表明了自己是国际宪兵和刽子手。它的活动成员扼杀了匈牙利苏维埃共和国和斯洛伐克苏维埃共和国。它们时时刻刻都在摧残俄国无产阶级：英、美、日、法等国的军队同屠杀工人阶级的刽子手一起从北方、南方、西方和东方向俄国进攻。“国际联盟”甚至还唆使黑人奴隶来反对俄国和匈牙利工人（敖得萨、布达佩斯）。这个联盟卑鄙已极，例如，这帮戴手套的“文明”强盗掌握着一个“杀人犯同盟”，为首的就是那个所谓“西北政府”的头目尤登尼奇将军。“国际联盟”始终都在唆使芬兰、波兰等国攻击苏维埃俄国。借助各国的领事进行阴谋活动；指使奸细炸毁桥梁，用炸弹来杀害共产党人。无论多么卑鄙龌龊的勾当，“国际联盟”都干得出来。","language":"中文","translation":false},{"id":"communism-abc-6-161","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":161,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"无产阶级的进攻愈有力，资本家集团就愈加团结。1847年马克思和恩格斯在《共产党宣言》里写道：“一个幽灵，共产主义的幽灵，在欧洲徘徊。旧欧洲的一切势力，教皇和沙皇、梅特涅和基佐、法国的激进党人和德国的警察，都为驱除这个幽灵而结成了神圣同盟。”[6]从那时起已经过去了很多年。共产主义的幽灵已成为有血有肉的实体。反对它的已不仅仅是“旧欧洲”了，而是整个资本主义世界。然而，“国际联盟”不可能担负起它的两个任务：组织统一的世界经济托拉斯和扼杀世界各地的革命。甚至在各大国之间也没有完全的一致。美国在反对日本，这两大国都在继续扩充军备。如果认为战败的德国将对协约国那些“无私的”强盗怀有友好的感情，那简直是可笑的。就是说，这里仍然存在着裂痕。各小国在互相交战。但是，更重要的是很多殖民地发生了起义和战争，如在印度、埃及、爱尔兰等。被奴役的国家开始了反对它们的“文明的”欧洲奴役者的战争。有助于动摇和破坏世界帝国主义统治的殖民地的起义同无产阶级为反对帝国主义资产阶级而进行的国内的、阶级的战争联合起来。因此，帝国主义体系已摇摇欲坠，这一方面是由于遭到起义的无产阶级、无产阶级共和国的战争，以及受帝国主义奴役的民族的起义和战争的打击；另一方面是由于受到各资本主义大国之间的矛盾和不和的影响。全面混乱代替了“持久和平”；残酷的国内战争代替了对全世界无产阶级的征服。在这场国内战争中，无产阶级的力量发展了，而资产阶级的力量削弱了。战争必然以无产阶级的胜利而告终。","language":"中文","translation":false},{"id":"communism-abc-6-162","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":162,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"当然，无产阶级专政的胜利绝不是轻易得来的。国内战争如同任何其他战争一样，都要有人力和物力上的牺牲。任何革命都要付出这样的代价。所以，不言而喻，在国内战争初期，帝国主义战争所造成的破坏在某些地方会显得更加突出。十分清楚，如果优秀的工人不是在工作或生产，而是手持步枪在前线抵御地主和将军的进攻，那么，工厂的生活自然会因此而受到损失。显然，国内战争中的一切破坏都是有害的破坏。显然，在战争中死去的同志都是最宝贵的牺牲。但是，这在任何革命中都是不可避免的。在1789——1793年的法国资产阶级革命时期，即在资产阶级推翻法国地主的时候，国内战争带来了很大的破坏。但是，当战胜了地主贵族之后，法国有了突飞猛进的发展。","language":"中文","translation":false},{"id":"communism-abc-6-163","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":163,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"任何人都懂得，在象无产阶级世界革命这样大的革命中，由于要推翻若干世纪形成的压迫制度，革命的损耗是特别大的。我们知道，现在国内战争是世界规模的；它部分地变成了资产阶级国家反对无产阶级国家的战争。抵御帝国主义强盗的无产阶级国家进行的阶级战争，是真正神圣的战争。但是它要付出血的牺牲。这种战争范围愈广，牺牲就愈大，破坏也就愈惨重。","language":"中文","translation":false},{"id":"communism-abc-6-164","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":164,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"但是革命的损耗绝不是反对这场革命的证明。若干世纪形成的资本主义制度导致了可怕的帝国主义战争，血流成河。哪一种国内战争能同人类积累的全部财富所遭到的这种野蛮破坏和毁灭相比呢？很清楚，人类需要一劳永逸地消除资本主义。为此，经受一段国内战争的时间，为共产主义开辟道路是值得的，共产主义将治愈一切创伤，并推动人类社会的生产力迅速地向前发展。","language":"中文","translation":false},{"id":"communism-abc-6-165","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":165,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"第三十四节 全面解体还是共产主义","language":"中文","translation":false},{"id":"communism-abc-6-166","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":166,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"可见帝国主义战争已成为世界性的帝国主义战争，而基于同样的原因，正在发展着的革命也是世界性的。所有主要国家都相互联系着，所有国家都是世界经济的一部分，几乎所有的国家都卷入了战争，并由这场战争以一种特殊的形式联结在一起；战争在所有国家都造成了可怕的破坏，引起饥饿，使无产阶级遭到奴役；战争在世界各国引起了资本主义的日渐腐烂和解体，使军队和工厂里的棍棒纪律趋于瓦解；同时战争也必不可免地引起无产阶级的共产主义革命。","language":"中文","translation":false},{"id":"communism-abc-6-167","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":167,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"资本主义的解体和共产主义革命的发展既已开始，那就不可能停止。资本主义的崩溃开始了。任何想使人类社会停留在旧的资本主义轨道的企图都早已注定要遭到彻底的失败。这是因为无产阶级群众已经觉悟到，他们不能够，不愿意，也不再会为资本工作或为资本和殖民地的利益等等而互相残杀。现在已不可能在德国恢复威廉的军队。同样，军队里已不可能恢复帝国主义的纪律，给无产者士兵套上枷锁，使他们听命于地主-将军。同样，现在也已不可能做到恢复资本主义的劳动纪律，强迫工人为雇主、农民为地主干活。只有无产阶级才能建立新型的军队。只有工人阶级才能实行新型的劳动纪律。","language":"中文","translation":false},{"id":"communism-abc-6-168","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":168,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"因此，现在或者是全面解体，彻底混乱，血肉横飞，更加野蛮，毫无秩序和真正的无政府状态，或是共产主义，只能二者居一。在群众即将掌握自己政权的国家里，一切确立资本主义的企图都证实了这一点。不论芬兰资产阶级，还是匈牙利资产阶级，不论高尔察克、邓尼金，还是斯柯帕茨基都办不好经济事业，甚至不可能建立起他们自己的血腥制度。","language":"中文","translation":false},{"id":"communism-abc-6-169","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":169,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"人类的唯一出路是共产主义。由于只有无产阶级才能实现共产主义，所以现在无产阶级是全人类真正的救星，它将使全人类摆脱资本主义的灾祸，摆脱金融资本和帝国主义所带来的野蛮剥削、殖民政策、经常性的战争、饥饿、残暴和兽行。无产阶级伟大的历史作用就在这里。无产阶级在某些斗争中，甚至在某些国家里可能遭到失败。但是它的胜利是必然的，正象资产阶级的灭亡是必然的一样。","language":"中文","translation":false},{"id":"communism-abc-6-170","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":170,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"从上面所说的可以清楚地看到，一切主张恢复资本主义或者认为现在不是实现社会主义的时候的集团、阶级和政党，不管它们愿意不愿意、自觉或不自觉，实际上起了反革命、反动的作用。所有的社会妥协主义的政党都是如此。关于这一点，也可以参看下一章。","language":"中文","translation":false},{"id":"communism-abc-6-171","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":171,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"第四章书目：列·加米涅夫《帝国主义的经济制度》。尼·列宁《帝国主义是资本主义的最高阶段》。尼·布哈林《世界经济和帝国主义》。格·策彼罗维奇《俄国的辛迪加和托拉斯》。卢金（安东诺夫）《军国主义》。巴甫洛维奇《什么是帝国主义？》。巴甫洛维奇《伟大的铁路》，《军国主义和海霸政策》，《世界战争的结局》。鲁·希法亭的《金融资本》，该书读起来要困难一些，但却是主要的著作。","language":"中文","translation":false},{"id":"communism-abc-6-172","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":172,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"除此之外，还可以参看：卡·考茨基《夺取政权之路》。凯尔任策夫《英帝国主义》。洛佐夫斯基《铁和煤（争取亚尔萨斯-洛林的斗争）》。格·季诺维也夫《奥地利和世界战争》。波克罗夫斯基《战争时期的法国》。赫拉斯科夫《战争时期的英国》。米·卢利叶（拉林）《战胜国》，《战争的后果》。格·季诺维也夫《三国同盟和三国协约》。阿·洛莫夫《资本主义的瓦解和共产主义的组织》。恩·奥新斯基《社会主义的建设》（第一章）。","language":"中文","translation":false},{"id":"communism-abc-6-173","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":173,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"在文学书籍方面可以参考杰克·伦敦的长篇小说《铁蹄》。","language":"中文","translation":false},{"id":"communism-abc-6-174","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第四章 资本主义的发展如何导致共产主义革命（帝国主义，战争和资本主义的崩溃）","page":6,"paragraph":174,"url":"https://www.marxists.org/chinese/bukharin/1919/06.htm","text":"[1] “垄断”一词来源于希腊文，是国家、管理、统治的意思。我们这里的垄断就职是指国家对酒的垄断，即只有官家一家能够生产伏特加酒。但是，垄断可以不仅是针对伏特加酒，也可以针对一切物品；同时不仅有国家的垄断，而且还有私人工厂主的垄断。 [2] 原文为十三年，显然是错误的。参照了其他版本，现在这里改为二十年。——译者注 [3] 参看《马克思恩格斯选集》第2卷第367-368页。——译者注 [4] 参看《马克思恩格斯选集》第2卷第369页。——译者注 [5] 参看同上，第554页。——译者注 [6] 《马克思恩格斯选集》第1卷第250页。——译者注","language":"中文","translation":false},{"id":"communism-abc-7-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-7-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"无产阶级专政和共产主义建设","language":"中文","translation":false},{"id":"communism-abc-7-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"· 第四十一节 俄国的国际地位","language":"中文","translation":false},{"id":"communism-abc-7-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"· 第四十二节 俄国的大工业","language":"中文","translation":false},{"id":"communism-abc-7-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"· 第四十三节 帝国主义战争的恶果","language":"中文","translation":false},{"id":"communism-abc-7-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"· 第四十四节 国内战争和同世界帝国主义的斗争","language":"中文","translation":false},{"id":"communism-abc-7-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"· 第四十五节 国家的小资产阶级性，无产阶级缺乏大规模组织起来的习惯等等","language":"中文","translation":false},{"id":"communism-abc-7-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"第四十一节 俄国的国际地位","language":"中文","translation":false},{"id":"communism-abc-7-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"正如我们前面所指出的那样，共产主义变革的必要性首先是由于俄国非常有力地挤进世界经济体系这一事实而引起的。俄国仅仅是这个世界经济的一部分。这里会提出一个问题：既然俄国是一个落后国家，那俄国怎能过渡到共产主义制度呢？而要回答这个问题，首先需要指出革命的国际意义。无产阶级的革命现在只能是世界革命。它也正是这样发展的。欧洲不可避免地要过渡到无产阶级专政，而在这之后，则要过渡到共产主义。这样一来，如果德国、法国、英国都将过渡到无产阶级专政，那俄国怎么还能继续成为资本主义国家呢？事情很明显，俄国必定会被拉入社会主义。如果俄国在经济上和一些先进国家联合起来，成为一个国际的，或者哪怕仅仅成为一个欧洲的苏维埃共和国，那么它的落后性，它的工业发展比较薄弱等等，——所有这些缺点都将被它消除。诚然，在战争破坏和革命之后，整个欧洲将变得千疮百孔，虚弱不堪。但是，强大而发达的无产阶级经过若干年后一定能使强大的工业得到恢复，从而使落后的俄国也得到帮助。而另一方面，俄国是一个拥有丰富自然资源的国家：森林、煤、石油、铁矿、粮食——所有这一切，只要很好地加以组织，只要不打仗，就会十分充裕。这就是说，从我们这一方面，我们也可以用我们的原料帮助西方的同志。将来整个欧洲无产阶级掌握了政权，大家都会有足够发达的工业，而既然政权往无产阶级手中过渡终究是不可避免的，那么很明显，俄国工人阶级的任务就是要从自己方面为向共产主义过渡的事业尽可能多作出贡献。因此，正如我们在第一部分里所看到的那样，我们党十分明确地把尽快建设共产主义视为自己的任务。","language":"中文","translation":false},{"id":"communism-abc-7-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"第四十二节 俄国的大工业","language":"中文","translation":false},{"id":"communism-abc-7-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"另一方面，需要看到，我国的工业尽管小（同农业相比较），但却具有大的资本主义组织。在第一部分里，我们已经知道，我国一些最主要的资本主义生产部门有些拥有一万和一万名以上工人的企业。从1907年起，俄国的工业迅速集中，到处都是辛迪加和托拉斯。随着战争的爆发，资产阶级甚至要开始着手组织国家资本主义。而这只能证明这样一种思想，即尽管很困难，但仍然可以在全俄罗斯范围内组织和管理我们的工业。值得注意的是，右派社会革命党和孟什维克一方面整天叫嚷说社会主义在俄国是绝对不可能的，但另一方面他们却又始终主张国家对工业的调节和监督。只是他们认为，要这样做就需要使国家的全部政权归资产阶级所有，由资产阶级国家来实行“调节”和“监督”。换句话说，孟什维克和社会革命党人尽管标榜自己最富于爱国主义，但是他们所主张的却是普鲁士式的国家资本主义。然而，任何人都懂得，认为国家资本主义是可能的——这就是认为社会主义的经济组织也是可能的。事实上区别只在于：在一种情况下，经济是由资产阶级国家组织的，在另一种情况下，经济是由无产阶级国家组织的。如果我们的生产落后得连任何组织都谈不上，那自然也就不可能用国家资本主义方式来组织它。要知道，在没人大工业、而只有大量小业主的国家里，甚至不可能按国家资本主义的模式把这些小业主组织起来。我们非常清楚地知道，只有在资本集中到一定程度时，组织才是可能的。俄国资本已经达到了这样的集中程度。这一点甚至共产主义的反对者们也是承认的，因为他们认为工业的资产阶级“国家调节”是可能的。俄国国民经济的落后不在于没有大工厂，而在于整个工业同农业相比只是一小部分。因此，结论十分清楚：俄国无产阶级不管有多少困难，都必须按无产阶级方式来组织工业，并牢固地将它控制在自己手里，直至得到西方同志的援助。在农业中，需要组织一系列社会协作经济的据点。而当我们能够同西方的工业联合起来的时候，组织起来的共同的工业就能够迅速地把小生产者和农民吸引到共同的大协作组织里来。比如说，如果我们有由工人阶级组织起来的共同的欧洲工业，那么这种工业就能够向农村提供大量的城市产品。但是它向农村提供产品是通过有组织的途径进行的。不是通过以百万计的私商、买卖人和投机商，而是由国家工人仓库把产品分配给各个农村。那时农民自然也应该通过有组织的途径把自己的粮食拿来作为交换；农村将逐渐习惯于公共经济。然后它将进一步地参加到共同协作的大家庭中来。强大的和有组织的工业也将把农村吸引到公共生活中来。借助强大的工业可以很好地帮助农民，农民将亲身看到，按照新的方式生活会更加美好。","language":"中文","translation":false},{"id":"communism-abc-7-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"然而要达到这一切是很困难的，要把一切都安排好，要使生活走上新的轨道，还需要许多许多年的时间。为什么这样困难，下面将要讲到这一点。","language":"中文","translation":false},{"id":"communism-abc-7-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"第四十三节 帝国主义战争的恶果","language":"中文","translation":false},{"id":"communism-abc-7-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"在世界革命胜利之前，我们只能是单枪匹马地行动。工人阶级在1917年夺取政权以后接受下来的是一份破烂不堪的遗产。俄国成了一个完全破产和贫困的国家。","language":"中文","translation":false},{"id":"communism-abc-7-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"战争耗尽了一切力量。全国一半以上的工厂被迫为战争工作和为破坏事业浪费材料。在1915年一年里，整个“国民收入”一百一十五亿中为战争就用去了六十亿。到革命爆发之前，战争的严重后果已经明显暴露出来。冶金厂减产百分之四十，纺织厂——百分之二十；煤和钢铁生产开始迅速下降。从1917年3月1日至8月1日，倒闭了五百六十八家企业，流落街头的无产者超过十万人。国债增加到惊人的数目。国家的状况一月月、一天天越来越坏。","language":"中文","translation":false},{"id":"communism-abc-7-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"不言而喻，无产阶级在1917年10月夺取政权以后面临着异常困难的任务：在一个破产的国家里建设社会主义经济。在旧日的帝国主义战争结束时，遗留下来的烂摊子的情况变得更加严重了：光是复员我们的军队就支出了一笔极为巨大的费用；由于战争的破坏，运输业本来就摇摇欲坠和混乱不堪，这时就几乎彻底完蛋了，我们的铁路也几乎停顿。运什么东西都非常困难。生产和交通处于瘫痪状态。","language":"中文","translation":false},{"id":"communism-abc-7-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"但是这绝不能成为反对工人革命的理由。如果资产阶级继续掌权，它就会继续进行帝国主义战争，它就要继续付给法国人和英国人巨额利息，而最主要的——它会把全部费用转嫁给工人和农民。我国的贫困和衰竭定会更好地唤起无产阶级以新的方式去改造旧世界；必须更节省地和更有组织地消费原有的东西，必须把费用负担转嫁给资产阶级，必须尽一切力量和用无产阶级政权所掌握的一切手段来保护工人阶级。而这项必要的工作在几乎是超自然困难的条件下落到了革命的无产阶级身上：对帝国主义先生们留下来的烂摊子不得不加以收拾。","language":"中文","translation":false},{"id":"communism-abc-7-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"第四十四节 国内战争和同世界帝国主义的斗争","language":"中文","translation":false},{"id":"communism-abc-7-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"资产阶级总是千方百计地阻挠工人阶级组织生产和着手整个建设工作。从无产阶级胜利之时起，资产阶级就开始广泛地进行怠工：所有过去的大官吏、工程师、教员、银行职员以及他们过去的主人都开始用一切手段搞破坏；阴谋一个接着一个，白匪暴动一起接着一起。俄国资产阶级同捷克斯洛伐克人、同协约国、同德国人、同波兰人等等勾结起来，力图在连续不断的战争中扼杀俄国无产阶级。无产阶级应当建立强大的军队来抵抗全世界地主和资本家的进攻。全世界的帝国主义都在向俄国无产阶级展开猛烈的攻击。","language":"中文","translation":false},{"id":"communism-abc-7-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"不言而喻，无产阶级进行的战争尽管对于无产阶级来说是真正神圣的和真正解放的战争，但是这一战争毕竟要付出很大的代价。必需把工业中仅有的产品供应红军，把成千成千最优秀的工人-组织者送去参军等等。加上资产阶级几乎从一开始就成功地控制了经济方面的一些非常重要的据点。顿河的将军们使工人失去了顿涅茨的煤，英国人夺取了巴库的石油。产粮的乌克兰、西伯利亚、伏尔加河流域的部分地区常常被反革命分子侵占。因此，工人阶级不得不手持武器抵御无数敌人的进攻，而且要在缺乏最重要的生产资料的情况下（缺乏燃料和原料）建设自己的无产阶级经济。","language":"中文","translation":false},{"id":"communism-abc-7-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"这就是痛苦发展过程的原因；工人阶级必须彻底击溃自己的敌人。在没有彻底击溃敌人之前，工人阶级就不可能象应该做的那样来安排好新生活。","language":"中文","translation":false},{"id":"communism-abc-7-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"当然，资产阶级在同工人阶级的斗争中，为了能从经济上扼杀俄国无产阶级，是不惜一切的：它对无产阶级实行全面包围，俄国有好几年被封锁（从国外进口不了任何商品）；白匪在撤退时焚烧和毁坏了一切。例如海军上将高尔察克就烧毁了几千万普特的粮食，把伏尔加河船队烧掉了整整一半等等。资产阶级的反抗，资产阶级的疯狂斗争，世界帝国主义对它的帮助——这就是在工人阶级道路上的第二个主要障碍。","language":"中文","translation":false},{"id":"communism-abc-7-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"第四十五节 国家的小资产阶级性，","language":"中文","translation":false},{"id":"communism-abc-7-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"无产阶级缺乏大规模组织起来的习惯等等","language":"中文","translation":false},{"id":"communism-abc-7-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"我们在上面已经看到，我们的工业是相当集中的，因而可以提出关于工业的无产阶级国有化、关于把工业变为工人国家的财产和关于用新方式组织工业的问题。但是另一方面，我们的工业同整个国家的经济相比还很薄弱。我国人口的绝大多数不是城市人口，而是农业人口即农村人口。根据1897年的统计，我们有一千六百万城市人口和一亿零一百万农业人口（西伯利亚等地区计算在内，但不包括芬兰）。1913年，根据奥加诺夫斯基的材料，俄国的城市人口按整数计算是三千万，而农村人口是一亿四千万。可见，到1913年，城市人口约为农业人口的百分之十八。但是，要知道，远不是所有的城市人口都是产业无产阶级。这里还住着买卖人、工厂主、小资产阶级、知识分子——所有这些阶层，如果把他们加在一起，就有几百万人。诚然，在农村有过去的雇农、半无产者、贫农。他们是支持工人的。但是，他们的觉悟和组织性不很高。","language":"中文","translation":false},{"id":"communism-abc-7-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"俄罗斯人口很大的一个多数是小业主。虽然他们也在资本和地主的压迫下呻吟，但是他们习惯于单独的、自己私有的个体经济，一时很难适应于共同的事业，适应于建设共同的协作经济。大捞一把，损人肥己，只关心自己的事业——这种习气在每一个小业主身上是根深蒂固的，因此，即使不考虑其他方面的原因，在俄国建设共产主义的事业也是最艰难的事业。","language":"中文","translation":false},{"id":"communism-abc-7-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"我国的这种弱点也反映在工人阶级中。一般说来，工人阶级是具有革命、战斗精神的。但是，它也有落后的一面，即不习惯于组织。不是所有的工人都能象彼得堡的工人那样。还有许多落后的和不觉悟的工人，他们同样也不习惯于为大伙工作。很多工人还是不久以前才来到城市的。他们在很多方面的想法和农民一样，错误也是在一起犯的。","language":"中文","translation":false},{"id":"communism-abc-7-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"工人阶级本身的这些缺点会随着它进行自己的斗争和参加工作而逐渐消失。但是，不言而喻，这种情况也同样有碍于我们的任务的实现，但它绝不会使这些任务的实现成为不可能。","language":"中文","translation":false},{"id":"communism-abc-7-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"引言 俄国建设共产主义的条件","page":7,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/07-1.htm","text":"书目：《第八次代表大会会议记录》，主要是关于党纲的讨论，列宁和布哈林的发言，还有列宁关于苏维埃政权的任务的讲话（散见于各种不同的出版物中）。关于俄国的经济状况，参看：策彼罗维奇《俄国的辛迪加和托拉斯》。弗·巴·米柳亭《俄国现代经济的发展和无产阶级专政（1914—1918年）》。恩·奥新斯基《社会主义的建设》（这本书的第一章对战争的破坏使社会主义成为更加必要的这一点作了很好的论证）。","language":"中文","translation":false},{"id":"communism-abc-8-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-8-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第五章 第二国际和第三国际","language":"中文","translation":false},{"id":"communism-abc-8-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"· 第三十五节 工人运动的国际主义是共产主义革命胜利的条件","language":"中文","translation":false},{"id":"communism-abc-8-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"· 第三十六节 第二国际的崩溃及其原因","language":"中文","translation":false},{"id":"communism-abc-8-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"· 第三十七节 保卫祖国的口号和和平主义","language":"中文","translation":false},{"id":"communism-abc-8-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"· 第三十八节 社会沙文主义者","language":"中文","translation":false},{"id":"communism-abc-8-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"· 第三十九节 “中派”","language":"中文","translation":false},{"id":"communism-abc-8-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"· 第 四十 节 第三共产国际","language":"中文","translation":false},{"id":"communism-abc-8-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第三十五节 工人运动的国际主义","language":"中文","translation":false},{"id":"communism-abc-8-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"是共产主义革命胜利的条件","language":"中文","translation":false},{"id":"communism-abc-8-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"共产主义革命只有作为世界革命才能取得胜利。如果在某一个国家里工人掌握了政权，而在其他国家里工人阶级却心甘情愿地委身于资本，那么最终这个国家就会被那些大强盗国家所扼杀。在1917、1918和1919年，所有大国都试图扼杀苏维埃俄国；1919年，它们把苏维埃匈牙利扼杀了。但是，它们之所以未能把苏维埃俄国扼杀掉，是因为这些大国的国内情况使它们不得不考虑它们本国工人要求从俄国撤出军队的压力，不然它们自己就要垮台。这就是说，第一，如果一个国家的无产阶级专政没有其他国家工人的支持，基本身的存在就会受到威胁。第二，在工人仅仅在一个国家取得胜利的情况下，要进行经济建设，组织经济是非常困难的。这样的国家从国外得不到或几乎得不到任何东西，因为它遭到全面封锁。","language":"中文","translation":false},{"id":"communism-abc-8-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"既然共产主义的胜利必须有世界革命的胜利和工人之间的互相支持，那就是说，工人阶级的国际团结是胜利的必要条件。单独一个国家里的情况也是一样，如果每一个工人都依附于自己的雇主，那工人就不能赢得罢工的胜利；只有当各个不同工厂的工人互相支持，建立共同的组织并进行反对一切工厂主的共同斗争时，他们才能赢得这场罢工的胜利。生活在各个不同资产阶级国家的工人的情况也是一样。只有当他们团结起来共同前进，彼此之间不互相敌视，相反，各个不同国家的无产者联合起来，感到自己是有着同一利益的一个阶级的时候，他们才能取得胜利。只有互相充分信任，结成兄弟般的联盟，采取统一的革命行动来反对全世界资本，才能保证工人阶级的胜利。工人共产主义只有作为国际共产主义运动才能胜利。","language":"中文","translation":false},{"id":"communism-abc-8-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"人们早已认识到无产阶级国际性斗争的必要性。在上个世纪四十年代，1848年革命前夜，已经有了称之为“共产主义者同盟”的国际秘密组织。领导它的是马克思和恩格斯。在这个同盟的伦敦代表大会上，他们接受委托代表这个同盟起草了《宣言》。这样就出现了《共产党宣言》，无产阶级的伟大战士在《宣言》里第一次阐述了共产主义学说。","language":"中文","translation":false},{"id":"communism-abc-8-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"1864年，在马克思的领导下产生了“国际工人协会”，也就是现在人们所说的第一国际。在第一国际里有来自各个国家的很多工人运动领袖，但是，它的队伍还不够统一。此外，它还没有依靠广大工人群众，很象一个革命宣传的国际团体。在1871年巴黎工人起义（巴黎公社）时期，国际的会员参加了起义。在这之后，到处都开始了对国际支部的迫害。1874年，再加上马克思的拥护者和巴枯宁无政府主义者之间的内部斗争对国际的削弱，国际解散了。第一国际解散以后，社会主义政党开始在各个国家迅速发展起来。工业发展越快，这些政党的成长也就越迅速。相互支持成为十分强烈的需要，于是1889年各国社会主义政党的代表召开了国际社会主义代表大会。在这次大会上决定成立第二国际。第二国际实际上存在到1914年，战争宣告了它的结束。其原因下面将会谈到。","language":"中文","translation":false},{"id":"communism-abc-8-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"早在《共产党宣言》里，马克思就提出了“全世界无产者，联合起来！”的口号。马克思就这一点写道（这几行是《宣言》的结尾）：“共产党人不屑于隐瞒自己的观点和意图。他们公开宣布：他们的目的只有用暴力推翻全部现存的社会制度才能达到。让统治阶级在共产主义革命面前发抖吧。无产者在这个革命中失去的只是锁链。他们获得的将是整个世界。全世界无产者，联合起来！”[1]","language":"中文","translation":false},{"id":"communism-abc-8-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"由此可见，无产阶级的国际团结对于工人来说决不是装饰品或漂亮话，而是切身需要，没有它，工人阶级的事业就注定要毁灭。","language":"中文","translation":false},{"id":"communism-abc-8-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第三十六节 第二国际的崩溃及其原因","language":"中文","translation":false},{"id":"communism-abc-8-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"当1914年8月世界大战爆发的时候，世界各国的社会民主党，除了俄国、塞尔维亚以及后来的意大利的社会民主党以外，都转到了本国政府一边，并且亲自支持这场掠夺性的屠杀，而不是向战争宣战和发动工人进行起义。就在同一天，法国和德国的社会民主党议员在国会里投票赞成本国政府的战争拨款，从而发出了支持强盗政府的信号。社会党不去进行反对罪恶的资产阶级的总起义，反而各自站到“本国”资产阶级政府的旗帜之下。战争在社会党的直接支持下爆发了，社会党的领袖们背叛了社会主义和出卖了社会主义。第二国际从此就可耻地灭亡了。","language":"中文","translation":false},{"id":"communism-abc-8-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"有趣的是，一些社会党的机关报及其领袖们就在背叛前几天还在痛斥战争。例如，法国社会主义的叛徒古·爱尔威在他的《社会战争报》（他把该报又改名为《胜利报》）上写道：“为拯救皇帝的威望（尊严）而战！……为如此高尚的事业而死是多么快乐！”在战争前三天，法国社会党发表了反战宣言，而法国工团主义者在自己的报纸上呼吁：“工人们！如果你们不是胆小鬼……那就要起来抗议！”德国社会民主党召开了规模宏大的抗议集会。大家对于巴塞尔国际代表大会的决议还记忆犹新，决议中说，在战争的情况下，需要采取一切手段来“唤起民众”和加速资本主义的崩溃。然而就在第二天，还是这些政党及其领袖则又说必须“保卫祖国”（即本国资产阶级的强盗国家），而奥地利的《工人报》又断言说，需要保卫“德国的（！！）人类”。","language":"中文","translation":false},{"id":"communism-abc-8-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"要搞清第二国际为什么会崩溃和可耻地灭亡，就需要分析战前工人运动发展的情况。在这场冲突之前，欧洲各国和美国的资本主义都是靠疯狂掠夺殖民地而发展起来的。资本主义肮脏和血腥的一面主要就表现在这里。通过野蛮的剥削、掠夺、欺骗和暴力从殖民地人民身上不断榨取的财富，成为欧美金融资本豺狼的利润。哪一个国家资本主义托拉斯感到自己在世界市场上越强大越有势力，那它剥削殖民地所得的利润就越多。有了这种额外的利润，它付给自己雇佣奴隶的报酬可以略高于通常的工资。当然这不是付给所有的人，这只是付给“技术熟练的人”，即所谓受过训练的工人。因此，工人阶级中的这个阶层常常被资本收买过去。这个阶层开始这样盘算：“如果‘我们的’工业在非洲殖民地拥有市场，这就太好了，它将更好地发展，我们雇主的利润就要增加，我们也将得到一些。”资本家就是这样依靠殖民地掠夺收买一部分雇佣奴隶，豢养他们，把他们和自己的国家拴在一起。","language":"中文","translation":false},{"id":"communism-abc-8-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"对于这种现象，科学共产主义的创始人早已指出过。例如，弗·恩格斯在1882年给考茨基的信中曾这样写道：“您问我：英国工人对殖民政策的想法如何？这和他们对一般政策的想法一样。这里没有工人政党，有的只是保守党和自由激进党，而工人十分安然地同他们共享英国的殖民地垄断和英国在世界市场上的垄断权。”[2]","language":"中文","translation":false},{"id":"communism-abc-8-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"在这种土壤上，一种特别的下流无耻行为，工人对本国资产阶级的依恋，对资产阶级的奴性滋长起来。恩格斯在1889年写道：“这里最可恶的，就是那种已经深入工人肺腑的资产阶级式的‘体面’。……还有一种生来就对比自己‘更好’、‘更高’的等级表示尊敬的心理；这种东西已经存在这样久和这样根深蒂固，以致资产者要搞欺骗还相当容易。例如，我绝不相信约翰·白恩士在本阶级中享有的声望会比他在曼宁红衣主教、市长和一般资产者那里的声望更使他感到自豪。”[3]","language":"中文","translation":false},{"id":"communism-abc-8-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"工人群众不习惯而且也没有机会进行国际范围的大规模斗争。他们组织的全部活动多半都是在自己资产阶级国家里进行的。而这个“自己的”资产阶级以殖民地政策引诱工人阶级中的一部分，特别是工人阶级中的技术熟练阶层。那些过着某种殷实生活和习惯于“和平的”、“安定的”、“合法的”活动的工人组织的首领、工人官僚和议会代表都被诱惑上钩。我们已经说过，资本主义血腥的一面主要表现在殖民地。在欧洲本土和美国，工业发展很快，而与此同时，工人阶级本身的斗争多多少少是以和平方式进行的。从1871年起，就没有发生过什么大的革命（俄国除外），而从1848年起，在大多数国家里，所有人都习惯地认为，资本主义将继续和平地发展下去，甚至连那些经常谈论战争威胁的人自己也不大相信会有战争。一部分工人——其中也包括工人首领——越来越渗透这样一种思想：殖民政策对于工人阶级也有好处，工人阶级应当和本国资产阶级共同关心这种“全民事业”的繁荣昌盛。在这个基础上，小资产阶级群众也开始涌向社会民主党一边。例如，在德国就是这样，在社会民主党国会党团中有相当多的工人餐馆的店东、老板；1892年有四人（三十五人中），1905年有六人（八十一人中），1912年有十二人（一百一十人中）。","language":"中文","translation":false},{"id":"communism-abc-8-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"所以一旦到了关键时刻，依恋帝国主义强盗国家的心理就压倒了国际主义的团结精神，这是毫不奇怪的。","language":"中文","translation":false},{"id":"communism-abc-8-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"这样，国家资本主义大托拉斯的殖民政策和垄断地位在工人中，——特别是在工人阶级的“上层分子”中造成的依恋资产阶级帝国主义国家的心理也就成为第二国际破产的主要原因。","language":"中文","translation":false},{"id":"communism-abc-8-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"在工人运动史上，以前也常常出现过工人与自己的压迫者携手共进的情况。例如，在最初的发展阶段，工人和自己的雇主都围在同一张台子跟前工作，那时工人把自己的雇主的工厂几乎视为自己的工厂；在工人看来，雇主不是敌人，而是“提供工作的人”。只是随着时间的推移，各工厂的工人才开始互相联合起来反对所有的雇主。当一些大国变成“国家资本主义托拉斯”的时候，工人对于它们，就象从前对待个别雇主那样，也抱有依恋心理。","language":"中文","translation":false},{"id":"communism-abc-8-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"只是战争教育了工人，不应该站在自己资产阶级国家一边，而应该共同起来推翻这些资产阶级国家和走向无产阶级专政。","language":"中文","translation":false},{"id":"communism-abc-8-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第三十七节 保卫祖国的口号和和平主义","language":"中文","translation":false},{"id":"communism-abc-8-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"社会党和第二国际的领袖们以所谓需要“保卫祖国”来为自己背叛工人事业和工人阶级共同斗争的行为进行辩护。","language":"中文","translation":false},{"id":"communism-abc-8-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"我们已经看到，在帝国主义战争中这完全是胡说八道，因为在战争中任何一个大国都不是自卫，而在进攻别国。保卫祖国（资产阶级的）的口号纯属欺骗，这批领袖想以此来掩盖自己的叛卖行为。","language":"中文","translation":false},{"id":"communism-abc-8-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"但是，这里我们应该比较详细地来研究这个问题。","language":"中文","translation":false},{"id":"communism-abc-8-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"首先，什么是祖国？这个词的实际含义是什么？指的是讲同一语言的人们或者“民族”吗？不是的。因为，譬如说，我们拿沙皇俄国为例。当俄国资产阶级高喊保卫祖国的时候，它所指的绝不是一个民族，比如说大俄罗斯人生活在其内的那个地域；不，这里是指居住在俄国的各民族。实际上，这究竟指的是什么呢？指的不是别的，而是俄国资产阶级和地主的国家政权。主张让俄国工人去“保卫”这个政权（实际上不是保卫，而是把它的疆界扩大到君士但丁堡和克拉科夫）。当德国资产阶级叫喊保卫“祖国”时，这里指的又是什么呢？仍然是指德国的资产阶级政权，指扩大威廉的强盗国家的疆界。","language":"中文","translation":false},{"id":"communism-abc-8-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"在这里需要搞清楚，在资本主义制度下工人阶级有没有祖国。马克思在《共产党宣言》中回答了这个问题：“无产阶级没有祖国。”他是正确的。为什么？原因很简单，因为在资本主义制度下，他们没有政权，因为在资本主义制度下，一切都掌握在资产阶级手里，因为在资本主义制度下，国家——这是镇压工人阶级的工具，是压迫工人阶级的工具。我们已经知道，无产阶级的任务就是要摧毁资产阶级的国家，而绝不是要保卫它。只有当无产阶级夺取了国家政权，并成为国家的主人的时候，无产阶级才能有祖国。在那时——也只有在那时——无产阶级才会有祖国，也才会有责任来保卫它：因为在那时，它要保卫的是自己的政权和自己的事业，而不是自己的敌人的政权和自己的压迫者的强盗政策。","language":"中文","translation":false},{"id":"communism-abc-8-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"资产阶级从自己的利益出发非常了解这一切。下面的例子就是证明。当无产阶级在俄国夺取了政权以后，俄国资产阶级就开始起来反对俄国，而宁肯同任何人结成联盟：同德国人、日本人、美国人、英国人、同魔鬼及其祖母。为什么？因为资产阶级在俄国失去了政权，它在俄国失去了自己抢劫、掠夺、资产阶级剥削的祖国。它随时都准备摧毁无产阶级的俄国，即苏维埃政权。或者我们以匈牙利为例。当政权在资产阶级手里的时候，资产阶级就号召“保卫”它，但是随后不久，资产阶级就同罗马尼亚人、捷克斯洛伐克人、奥地利人，同协约国达成协议，共同起来扼杀无产阶级的匈牙利。这就是说，任何资产阶级都非常明白问题的所在。资产阶级自己本身，并以祖国为幌子让所有的公民都来巩固它的资产阶级政权，谁若不同意这样做，就以叛国罪论处，反之，资产阶级则邀集一切力量，肆无忌惮地摧毁无产阶级的祖国。","language":"中文","translation":false},{"id":"communism-abc-8-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"无产阶级应该向资产阶级学习：摧毁资产阶级的祖国，而不是去保卫或者扩大它；而对自己的祖国，要竭尽全力来保卫，直到流尽最后一滴血。","language":"中文","translation":false},{"id":"communism-abc-8-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"对这一切，有人可能会这样提出异议：你们不是承认殖民政策和帝国主义助长了大国的工业发展，工人阶级也因此而得到一点阔老餐桌上的残羹剩饭吗？这岂不是说，仍然需要保护和帮助自己的主人竞争吗？","language":"中文","translation":false},{"id":"communism-abc-8-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"完全不是这个意思。假设我们这里有两个工厂主：舒尔茨和彼得洛夫。他们在市场上互相叫骂。舒尔茨对自己的工人们说：“弟兄们！全力保护我！你们要尽可能地去破坏彼得洛夫的工厂，害死彼得洛夫本人以及他的工人等等。那时，我的工厂将大有作为，我打倒了彼得洛夫，我的事业将灿烂辉煌。我就可以给你增加半个卢布。”同样，彼得洛夫向自己的工人说的也是这一套。我们假定舒尔茨胜了。那时他最初可能会多给工人半个卢布。而以后，他会全部赚回去。如果工人想罢工，并向从前彼得洛夫的工人提出要求帮助，他们就要说：“怎么啦？你们把我们害得好苦，现在又来求我们了？趁早走开吧！”共同的罢工就搞不成了。工人分裂了，资本家就有了力量。现在，即在战胜了自己的竞争者之后，他就可以打击分裂了的工人了。舒尔茨的工人暂时得了半个卢布的好处，而接着却失去了一切，在国际斗争中情况也是一样。资产阶级国家是一种业主的联盟。当一个这样的联盟靠吃掉另一些联盟而发了财之后，它就可以来收买工人。第二国际的崩溃和工人运动的领袖们对社会主义的背叛正是因为这些领袖们决定“保卫”和增加从阔老们餐桌上掉下来的残羹剩饭。然而在战争期间，当工人由于这种背叛行为而被分裂的时候，全世界的资本就在工人身上压上了可怕的沉重负担。工人们看到自己受骗了，社会党的领袖们把他们廉价出卖了。社会主义就这样开始复活了。十分清楚，这种抗议首先是来自低薪和非熟练工人。工人贵族阶层（如各国的印刷工人）和老资格的领袖们还会长期地继续他们的叛卖行径。","language":"中文","translation":false},{"id":"communism-abc-8-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"除了保卫（资产阶级的）祖国的口号以外，所谓的和平主义也是欺骗和愚弄工人群众的一种手段。什么是和平主义呢？这是一种观点，这种观点认为在资本主义范围内，无须任何革命，无须任何无产阶级的起义等等，就会在地球上建立起永久的和平。只要建立起大国之间的仲裁法庭，废除秘密外交，解除武装，那怕开始只是裁减武装等等，一切就都会好起来。","language":"中文","translation":false},{"id":"communism-abc-8-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"和平主义（“和事老思想”）的根本错误在于它看不到资产阶级是不会去做象解除武装这类好事的。在帝国主义时代和内战时期，鼓吹解除武装完全是一种荒唐和愚蠢的举动。资产阶级将把自己很好地武装起来，而如果无产阶级将自己的武装解除，或者不去武装自己，那简直就等于自杀。和平主义口号对无产阶级的欺骗性就在这里。其目的是要转移工人阶级的注意力，不去为实现共产主义而进行武装斗争。","language":"中文","translation":false},{"id":"communism-abc-8-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"威尔逊的政策及其十四条可以说是和平主义的虚伪性的最好典范，这里假借高尚事物的名义，包括打着国联的幌子，进行世界性的掠夺和反对无产阶级的内战。和平主义者卑鄙到何等地步，从下面的一些例子中可以看出来：美国前总统塔夫脱是美国和平主义者同盟的创始人之一，同时是一个疯狂的帝国主义分子；著名的美国汽车工厂主福特组织了很多考察团到欧洲并散布和平主义。但是，因为他的企业都是为战争服务的，所以他同时又捞到了几亿美元。一位最有声望的和平主义者阿·弗里德，在他的《和平主义手册》（第2卷第149页）一书中把1900年帝国主义者联合进攻中国竟然看作是“各民族的兄弟情谊”。关于这一点，他是这样写的：“中国的事业证明了和平思想对当代事变的影响。它显示了军队的国际性联合。联军在一位欧洲的最高统帅的指挥下，作为世界力量出动了。我们，作为和平的朋友，认为这位世界的最高统帅（这就是威廉二世任命的瓦德西伯爵）只是一位世界国务活动家的先驱者，他将能够用和平的手段来实现我们的理想。”","language":"中文","translation":false},{"id":"communism-abc-8-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"赤裸裸的联合掠夺在这里被说成是“各民族的兄弟情谊”。这同给强盗的资本家同盟挂上“国际联盟”的招牌的做法是毫无区别的。","language":"中文","translation":false},{"id":"communism-abc-8-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第三十八节 社会沙文主义者","language":"中文","translation":false},{"id":"communism-abc-8-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"资产阶级每天都运用它们所有的书报、杂志和传单等等向群众散布骗人的口号，这些口号也成为社会主义叛徒们的口号。","language":"中文","translation":false},{"id":"communism-abc-8-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"差不多各国老的社会党都分裂成三派：公开的和无耻的叛徒——社会沙文主义者；隐蔽的和摇摆不定的叛徒——这就是所谓的“中派”；最后是那些没有背叛社会主义的人，后来由这些人组成了共产党。","language":"中文","translation":false},{"id":"communism-abc-8-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"差不多各国社会党的领袖都成了沙文主义者，这些人打着社会主义的旗帜鼓吹对人类的仇视，在保卫祖国的骗人口号下鼓励人们支持强盗的资产阶级国家，如，德国的谢德曼、诺斯克、艾伯特、大卫、海涅等等；英国的韩德逊；美国的罗索、赛米尔·龚帕斯（工会领袖）；法国的列诺得尔、阿尔贝·托马、茹尔·盖得和茹奥之类的工会领袖；俄国的普列汉诺夫、波特列索人、右派社会革命党人（布列什柯-布列什柯夫斯卡娅 、克伦斯基、切尔诺夫）和右派孟什维克（李伯尔、罗扎诺夫）；奥地利的伦纳、扎伊茨、维克多·阿德勒；匈牙利的加拉米、布欣盖尔等等。","language":"中文","translation":false},{"id":"communism-abc-8-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"他们人人都主张“保卫”资产阶级的祖国。但是他们中的很多人还公开拥护强盗政策，要别国割地和赔款，拥护掠夺殖民地（人们通常称他们为社会帝国主义者）。在整个战争期间，他们不仅对拨款投赞成票，而且动用全部宣传机器来支持战争。沙皇大臣赫沃斯托夫在俄国到处张贴普列汉诺夫的宣言。科尔尼洛夫将军任命普列汉诺夫为自己的内阁大臣。克伦斯基（社会革命党人）和策烈铁里（孟什维克）向人民隐瞒了沙皇的秘密条约；他们镇压了七月事变中的彼得堡无产阶级；社会革命党和右派孟什维克参加了高尔察克的政府，罗扎诺夫成了尤登尼奇的奸细。一句话，他们同整个资产阶级一样，主张支持掠夺成性的资产阶级祖国和赞成摧毁无产阶级的、苏维埃的祖国。法国的社会沙文主义者参加了强盗内阁（盖得、阿贝尔·托马）支持协约国的所有掠夺计划，主张扼杀俄国革命和派出军队镇压俄国工人；德国的社会沙文主义者还在威廉时代就参加了内阁（谢德曼），支持威廉扼杀芬兰革命，掠夺乌克兰和大俄罗斯；社会民主党的成员（在里加的温尼格）指挥了反对俄罗斯和拉脱维亚的工人的战斗；以后，他们杀害了李卜克内西和罗莎·卢森堡，以最残暴的和血腥的方式镇压柏林、莱比锡、汉堡、慕尼黑等地的共产主义工人们的起义。匈牙利的社会沙文主义者支持过当时的专制政府，以后又出卖了苏维埃共和国。一句话，在各国，他们证明自己是屠杀工人阶级的真正刽子手。","language":"中文","translation":false},{"id":"communism-abc-8-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"当普列汉诺夫还是革命者的时候，他在国外的《火星报》上曾写道：注定要实现社会主义的二十世纪，大概将会看到社会党人中的大分裂和他们之间的巨大而激烈的斗争。普列汉诺夫说，在二十世纪，大概就象1789—1793年的法国革命时期极端革命党（“山岳派“）同温和的、以后成为反革命的政党（“热月派”）进行内战一样，从前的志同道合者将开始互相反对，因为他们之中的一部分人将转到资产阶级一边。","language":"中文","translation":false},{"id":"communism-abc-8-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"普列汉诺夫的这一预言完全被证实了。只是他那时还不知道他自己将也成为叛徒。","language":"中文","translation":false},{"id":"communism-abc-8-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"因此，社会沙文主义者（也称他们是机会主义者，即真正的妥协主义者）变成了无产阶级公开的阶级敌人。在世界大革命时期，他们加入白党的行列反对红党；他们同将军、大资产阶级、地主走在一起。不言而喻，必须同他们进行无情的斗争，就象必须同资产阶级进行坚决的斗争一样，因为他们是资产阶级的代理人。","language":"中文","translation":false},{"id":"communism-abc-8-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"这些党企图扶持第二国际的残余，实质上只不过是“国际联盟”的一个办事处。这仅仅是资产阶级同无产阶级斗争的一个工具。","language":"中文","translation":false},{"id":"communism-abc-8-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"原来的社会党的另一批人组成了所谓的“中派”。这个派别之所以这样命名，是因为它动摇于共产主义者和社会沙文主义者两者之间。属于这一派别的有：在俄国——以马尔托夫为首的左派孟什维克；在德国——以考茨基和哈阿兹为首的“独立派”（独立社会民主党）；在法国——让·龙格集团；在美国——以希尔奎特为首的美国社会党；在英国——不列颠社会党的一部分和独立工党等等。","language":"中文","translation":false},{"id":"communism-abc-8-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"战争一开始，这些人就同所有的社会主义叛徒一起主张保卫祖国和反对革命。考茨基曾写道，最可怕的事就是“敌人的入侵“，并且说，只有战争过后才可以起来斗争。按照考茨基的意见，在战争期间国际是无法有所作为的。缔结“和约”之后，考茨基开始写道，现在一切都完了，也用不着幻想社会主义了。因此，这就是说，在战争期间不能进行斗争，因为不会有什么结果，必须将斗争推迟到和平时再说了，而在和平时期也不能进行斗争，因为战争使一切都耗尽了。任何人都可以看到，考茨基的理论是一种对无产阶级起腐蚀作用的、使人完全无所作为的说教，这简直是彻头彻尾的背叛。更恶劣的是，在革命时期，考茨基除了对布尔什维克进行疯狂中伤外，什么好事也未干。他忘记了马克思的学说，总是在进行反对无产阶级专政、反对恐怖等等的活动，他没有发觉正是他自己帮助了资产阶级的白色恐怖。他个人的希望——就是通常和平主义者的希望（仲裁法庭等等），这样他就同任何资产阶级的和平主义者沆瀣一气了。","language":"中文","translation":false},{"id":"communism-abc-8-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"我们这样重视考茨基，是因为他的理论可以使人对中派有一个概括的了解，尽管考茨基是“中派”的右翼。","language":"中文","translation":false},{"id":"communism-abc-8-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"“中派”的政策正在于它无所作为地在资产阶级和无产阶级之间跑来跑去，脚跟不稳，企图调和不可调和的东西，并在关键时刻背叛无产阶级。在俄国十月革命时期，俄国的中派（马尔托夫之流）对布尔什维克的暴力发出哀号，力图“调和”一切，从而在战斗中帮助了白匪，削弱了无产阶级的力量。孟什维克党甚至没有开除那些起着将军的密探和阴谋者作用的党员。在无产阶级困难的日子里，这个“中派”为了维护立宪会议而出来煽动罢工，反对无产阶级专政；在高尔察克进攻的时候，这些孟什维克中一部分人同资产阶级阴谋者同流合污，提出了停止国内战争的口号（孟什维克普列斯科夫）。在德国，“独立派”在柏林工人起义中扮演了叛徒的角色，正当战斗的时候，他们起来“主和”，因而促成了起义的失败；在独立派当中有很多人主张同谢德曼派合作。但最主要的是他们不宣传反对资产阶级的群众起义，而用和平主义的愿望来麻痹无产阶级。在法国和英国，“中派”虽然也“谴责”反革命，口头上抗议扼杀革命，但对群众的行动却表现出完全的无能。","language":"中文","translation":false},{"id":"communism-abc-8-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"现在，“中派”集团同社会沙文主义者一样有害。“中派分子”——或者称他们为“考茨基分子”——也企图复活第二国际这具僵尸，并要它同共产党人“和解”。很清楚，不同他们决裂和斗争，要战胜反革命是不可能的。","language":"中文","translation":false},{"id":"communism-abc-8-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"恢复第二国际的尝试是在强盗式的“国际联盟”的亲昵庇护下进行的。这是因为社会沙文主义者是正在崩溃的资本主义制度的真正的和最后的支柱。帝国主义战争之所以能够闹腾五年之久，只是因为一些社会党对社会主义实行了彻底的背叛和出卖。随后，当革命时期开始时，资产阶级就直接依靠它们，通过它们的手来扼杀无产阶级的运动。首先，社会党成为工人阶级推翻资本斗争中的主要障碍。在战争期间，每一个社会主义叛徒党都重复着资产阶级的谰言。凡尔赛和约之后，“国际联盟”成立了，第二国际的残余（即社会沙文主义者和中派）开始重复着实质上是“国际联盟”所发出的口号。“国际联盟”指责布尔什维克搞恐怖活动、破坏民主、是“红色帝国主义”；第二国际做的也是这一套。它不同帝国主义进行坚决斗争，而是支持帝国主义者的口号。正如各国的社会主义叛徒党是各国资产阶级政府的支柱一样 ，第二国际是最腐朽的“国际联盟”的支柱。","language":"中文","translation":false},{"id":"communism-abc-8-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第 四十 节 第三共产国际","language":"中文","translation":false},{"id":"communism-abc-8-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"正如我们所看到的，社会沙文主义者和“中派”在战争期间提出了保卫（资产阶级的）祖国的口号，即保卫无产阶级的敌人的国家组织的口号。由这个口号产生出另一个口号，即“国内和平”的口号，也就是竭尽一切可能服从资产阶级国家的口号。这一点是很明白的。既然普列汉诺夫或者谢德曼认为需要“保卫”沙皇和凯撒的祖国，那么，当然，他们一定要对工人们说，要避免做某些有害于保卫强盗国家的事。这就是说，譬如，不能罢工，更不用说举行反对罪恶的资产阶级的起义。社会主义的叛徒们的是这样判断的：首先要平定“外部敌人”，然后我们再等看看。普列汉诺夫在他的宣言里也这样宣称，既然沙皇俄国遭到了危险，那就不能罢工。其他国家的工人也是这样成了资产阶级的奴隶。但是，从战争开始起，一些正直的社会党人就已经看出，“保卫祖国”和“国内和平”会束缚住无产阶级的手脚，这些口号是对无产阶级的背叛。从一开始，布尔什维克党就看到了这一点，早在1914年它就声明说，需要的不是同罪恶的资产阶级讲国内和平，而是进行旨在反对资产阶级的国内战争，也就是革命。无产阶级的责任是：首先推翻本国的资产阶级，——这就是我们的党从战争一开始时的论断。在德国也出现了以卡尔·李克内西和罗莎·卢森堡为首的一批同志。他们自称为“国际”派，并且声明，无产阶级的国际团结高于一切。不久，卡尔·李克内西公开提出国内战争的口号，并起来号召工人阶级以武装起义反对资产阶级。这样就产生了德国的布尔什维克党——斯巴达克派。其他国家一些老的党也出现分裂。在瑞典出现了自己的布尔什维克派（即所谓“左派社会党”），在挪威“左派”掌握了全党。意大利社会党人始终表现很好。一句话，主张革命的那些党逐渐开始发展起来。在这个基础上，在瑞士出现了联合的尝试。在齐美尔瓦德和昆塔尔的两次会议（代表会议）上出现了建立第三国际的萌芽。但是很快就发现这里掺杂的进一些“中派”的嫌疑分子，这些人只能阻碍运动的发展。在“齐美尔瓦尔德的”国际联合组织内部产生了所谓以列宁同志为首的“齐美尔瓦尔德左派”。齐美尔瓦尔德左派主张坚决地行动，并严厉地批评了以考茨基为首的“中派”。","language":"中文","translation":false},{"id":"communism-abc-8-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"在俄国十月革命和建立了苏维埃政权以后，俄国就成为国际运动的主要场所。我们的党为了同社会主义叛徒划清界线和恢复老的、光荣的和战斗的名称，把自己称作共产党。在俄国革命的影响下，在其他一些国家也开始成立共产党。斯巴达克同盟改名为德国共产党；匈牙利成立了以原俄国战俘贝拉·库恩同志为首的共产党，奥地利、捷克、芬兰等国也都成立了共产党；后来法国也成立了共产党。在美国，“中派”把左派开除出党，于是被开除的人也组织了自己的战斗的共产党；在英国，共产党也于1919年秋诞生。总之，各地在同社会主义叛徒分裂以后，真正的革命的工人政党开始发展和壮大起来。这些党的产生实质上是新的共产国际的产生。1919年3月，在莫斯科克里姆林宫举行了第一次国际共产党代表大会，在这次大会上正式成立了第三共产国际。出席这次代表大会的有德国、俄国、奥地利、匈牙利、瑞典、挪威、芬兰等国家共产党人的代表，以及法国、美国和英国同志的代表。","language":"中文","translation":false},{"id":"communism-abc-8-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"代表大会采纳了德国和俄国共产党人提出的纲领，大会是在前所未有的友好气氛中进行的，它表明，无产阶级现在稳固地站立在工人专政、苏维埃政权和共产主义的旗帜之下。","language":"中文","translation":false},{"id":"communism-abc-8-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第三国际定名为共产国际，和早先以卡尔·马克思为首的共产主义者同盟一样。第三国际以其全部的工作证明，它是沿着马克思的足迹前进的，也就是沿着暴力推翻资本主义制度的革命道路前进的。毫不奇怪，国际无产阶级中一切富有朝气的、正直的、革命的事物都越来越多地与联合先进工人力量的新国际联系在一起。","language":"中文","translation":false},{"id":"communism-abc-8-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"共产国际在自己的名称上就已经证明，它同社会主义叛徒毫无共同之处。","language":"中文","translation":false},{"id":"communism-abc-8-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"马克思和恩格斯曾认为“社会民主主义者”这一名称用于革命的无产阶级的党是不正确的。“民主主义者”——这是指某种政权形式的拥护者。正如我们在前面已看到的，在未来的社会里不存在任何形式的国家，而在过渡时期则必然有工人专政。工人阶级的叛徒们不会走得比资产阶级共和国更远些。我们则要走向共产主义。","language":"中文","translation":false},{"id":"communism-abc-8-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"恩格斯曾在《共产党宣言》的序言里说过，社会主义一词意味着当时激进的知识分子中的运动，而共产主义才是纯粹的工人运动。我们所看到的正是这样。共产主义者依靠的只是工人，而社会主义叛徒所依靠的则是工人贵族、知识分子、小饭店和小店铺老板，依靠一般小资产阶级。","language":"中文","translation":false},{"id":"communism-abc-8-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"可见，共产国际在事实上是实行马克思的学说，并清除了学说中在资本主义“和平”发展时期所滋生的赘瘤。在共产国际的领导下，共产主义的伟大导师六十年前所宣传的学说现在正在得到实现。","language":"中文","translation":false},{"id":"communism-abc-8-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"第五章书目：列宁和季诺维也夫《社会主义和战争》。列宁和季诺维也夫《逆流》。格·季诺维也夫《战争和社会主义危机》第一部分和第二部分。尼·列宁《无产阶级革命和叛徒考茨基》。赫·哥尔特《帝国主义》。齐美尔瓦尔德宣言和齐美尔瓦德委员会公报。《共产国际》杂志。","language":"中文","translation":false},{"id":"communism-abc-8-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第五章 第二国际和第三国际","page":8,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/07.htm","text":"[1] 《马克思恩格斯选集》第1卷第285—286页。——译者注 [2] 参看《马克思恩格斯全集》第35卷第353页。——译者注 [3] 参看上同，第37卷第316页。——译者注","language":"中文","translation":false},{"id":"communism-abc-9-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-9-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第四十六节 苏维埃政权是无产阶级专政的形式","language":"中文","translation":false},{"id":"communism-abc-9-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第四十七节 无产阶级民主和资产阶级民主","language":"中文","translation":false},{"id":"communism-abc-9-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第四十八节 无产阶级专政的阶级性和暂时性","language":"中文","translation":false},{"id":"communism-abc-9-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第四十九节 实现工人阶级权利的物质条件","language":"中文","translation":false},{"id":"communism-abc-9-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第五 十 节 劳动者不分性别、宗教、种族一律平等","language":"中文","translation":false},{"id":"communism-abc-9-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第五十一节 国会制度和苏维埃制度","language":"中文","translation":false},{"id":"communism-abc-9-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第五十二节 军队和苏维埃政权","language":"中文","translation":false},{"id":"communism-abc-9-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第五十三节 无产阶级的领导作用","language":"中文","translation":false},{"id":"communism-abc-9-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"· 第五十四节 官僚制度和苏维埃政权","language":"中文","translation":false},{"id":"communism-abc-9-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第四十六节 苏维埃政权是无产阶级专政的形式","language":"中文","translation":false},{"id":"communism-abc-9-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"我们党第一个提出并实现了苏维埃政权的要求。在“全部政权归苏维埃！”的口号下，1917年发生了伟大的十月革命。在我们党提出这个口号以前，这个口号根本没有实现过。但是，这并不意味着它是“从头脑里”臆造出来的。相反，它产生了，它诞生于生活自身的深处。早在1905——1906年的革命中就产生了工人的阶级组织：工人代表苏维埃。在1917年的革命中这类组织的出现数不胜数：先是工人苏维埃，士兵苏维埃，后来又有农民苏维埃，象雨后春笋，几乎到处都纷纷出现。很清楚，这些以争取政权而斗争的机构的形式出现的苏维埃必然要成为政权机关。","language":"中文","translation":false},{"id":"communism-abc-9-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在1917年的俄国革命以前，很多人都在谈论无产阶级专政，但实际上他们并不知道这个无产阶级专政究竟会以什么样的形式实现。现在俄国革命找到了苏维埃政权这种形式。苏维埃政权实现了无产阶级的专政，无产阶级作为统治阶级参加自己的苏维埃，并且在农民的帮助下镇压资产阶级和地主的反抗。","language":"中文","translation":false},{"id":"communism-abc-9-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"以前很多人认为，无产阶级专政可能以所谓的“民主共和国”的形式出现，这个共和国应由立宪会议来建立，并由阶级的人民选举出的会议来管理。直到今天机会主义者和社会妥协主义者还在坚持这种意见，说什么只有立宪会议和民主共和国才能把国家从苦难的内战中解放出来。但是，实际生活证明事情恰恰相反。例如，在德国，1918年十一月革命之后曾建立了这样的共和国。然而，那里在1918年和整个1919年进行了流血的斗争。工人阶级在这场斗争中始终要求建立苏维埃政权。苏维埃政权的口号成为无产阶级真正的国际性口号。世界各国工人都在提这个口号，并把它同工人专政的口号联系起来。生活证明我们的要求是正确的，“全部政权归苏维埃！”这个口号不仅适用于我们俄国，而且适用于一切有无产阶级存在的国家。","language":"中文","translation":false},{"id":"communism-abc-9-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第四十七节 无产阶级民主和资产阶级民主","language":"中文","translation":false},{"id":"communism-abc-9-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"资产阶级民主共和国依靠的是普遍投票和所谓的“全民的”、“全民族的”、“超阶级的”意志。资产阶级民主共和国和立宪会议等等的拥护者们说我们违背了民族的意志。现在我们首先把这个问题搞清楚。","language":"中文","translation":false},{"id":"communism-abc-9-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"我们在本书的第一部分里已经知道，现代社会是由利益互相矛盾的阶级所组成的。这就是说，如果延长工作日对资产阶级有利，那么它对工人阶级就没有利，等等。阶级是不可能调和的，就象狼和羊是不可能调和的一样。狼喜欢吃羊，而羊则必需实行自卫。如果事情是这样（而且绝对是这样），那么试问：能否确定一种狼和羊的共同意志？是否能找到一个羊与狼的共同意志呢？任何一个有头脑的人都会说，这是无稽之谈。羊与狼的共同意志是不可能的。二者之中只可能有一个：或者是狼的意志，使被欺骗和被压迫的羊听从狼的摆布；或者是羊的意志，使狼不敢冒犯羊并把这批野兽打死。在这里不可能有任何中间道路可走。同样，很明显，关于阶级的情况也是一样。在现代社会里，阶级反对阶级，资产阶级反对无产阶级，无产阶级反对资产阶级。它们是势不两立的。它们之间能有什么资产阶级和工人的共同意志呢？很清楚，正象狼和羊的情况一样，资产阶级和工人不可能有共同愿望和志向。只能说或者是资产阶级的意志，它把自己的意志用各种方法强加给被压迫的多数人民；或者是无产阶级的意志；它把自己的意志强加给资产阶级。在国内战争和革命的时期，即在旧世界就要垮台的时候，谈论什么全阶级的意志和“全民族的利益”，那就更为荒唐。在这里，无产阶级想的是要改造世界，资产阶级想的则是要巩固旧的奴役制度。","language":"中文","translation":false},{"id":"communism-abc-9-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"资产阶级和无产阶级能有什么样的“共同”意志呢？很清楚，关于全民的意志这种说法如果是指一切阶级而言的，那就是欺骗。这样的共同意志是不存在的，而且也不可能存在。","language":"中文","translation":false},{"id":"communism-abc-9-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"但是，这种欺骗是资产阶级所需要的。资产阶级需要它是为了维护自己的统治。资产阶级是少数。它不能公开说是一小撮资本家在实行统治。因此它需要欺骗，说它是以“全体人民”、“一切阶级”、“全民族”等等诸如此类的名义实行统治。","language":"中文","translation":false},{"id":"communism-abc-9-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在“民主共和国”里是怎样实行这种欺骗的呢？无产阶级在这里受奴役的主要原因是它在经济上受奴役。哪怕在最民主的共和国里，工厂也都是掌握在资本家手里，土地掌握在资本家和地主手里。工人除了劳动的双手以外一无所有，贫苦农民只有微不足道的一小块土地。他们终生被迫在最恶劣的条件下工作，遭受自己主人的压迫。在文据上他们可以有很多东西，而在实际上——什么都没有。因为一切财富、资本的权利都掌握在他们敌人的手里。这就是所谓的资产阶级民主。","language":"中文","translation":false},{"id":"communism-abc-9-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"美国、瑞士、法国都是资产阶级共和国。但是，在所有这些国家里，都是最卑鄙的帝国主义分子、托拉斯和银行大王，即工人阶级最凶恶的敌人在掌权。最民主的共和国是1919年出现的德意志共和国及其国民会议。然而要知道，这是杀害卡尔·李卜克内西的刽子手的共和国。","language":"中文","translation":false},{"id":"communism-abc-9-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"苏维埃政权实行新的、完美得多的民主形式——无产阶级的民主。这种无产阶级民主的实质在于，它以生产资料转到劳动者手里为基础，也就是以削弱资产阶级为基础的；实行这种民主时，恰恰是过去被压迫的群众及其组织在变成为管理机关。在资本主义制度下也有工人和农民的组织；因而，在资产阶级民主共和国里它们也存在。但是，它们受到富人组织的排挤。相反，在无产阶级民主制度下富人没有财富了。而工人、农民-半无产者等等的群众性组织（苏维埃、工会、工厂委员会等等）则成为无产阶级国家政权的真正基础。在苏维埃宪法的第一条里规定：“俄国为工、兵、农代表苏维埃共和国。中央和地方的全部政权归这些苏维埃掌握。”","language":"中文","translation":false},{"id":"communism-abc-9-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"苏维埃民主不但不排除工人组织参加管理，而且相反地，它把这些组织变为管理机关。由于苏维埃和其他工农组织吸收了千百万劳动群众，所以苏维埃政权第一次发动起无数从前被遗忘的和在底层奔波的人们去执行新的任务。越来越多的人民群众、工人和贫农通过苏维埃、工会、工厂委员会参加到共同的工作中来。到处都是这样。在外省的小城镇和农村里，人们开始从事过去从未干过的管理和建设新生活的事业。苏维埃政权还通过这种办法来实行各地方的广泛的自治，吸收广大群众参加这项工作。","language":"中文","translation":false},{"id":"communism-abc-9-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"显而易见，我们党的任务就是大力发展这种新的、无产阶级的民主。我们应当努力使最广大的无产者和贫农阶层参加苏维埃政权机关里的工作。列宁同志早在革命以前出版的一本小册子里就正确地说过，我们的任务就是要使甚至每一个厨娘都学会管理国家。当然，这是一个非常困难的任务，在实现这一任务的道路上还有大量的障碍。这些障碍首先就是群众的文化水平不高。先进工人是一个比较精干的阶层。例如五金工人就是这样。但是也有落后阶层，农村就更不用说了。他们往往缺乏足够的主动性和首创精神，这样他们就可能使自己置身于事外。我们党的任务就是要不断地、一步一步地把这些阶层也吸引到共同的国家工作中来。当然，要使越来越多的阶层参加这一工作，只有通过提高他们的文化水平和组织性的办法，这同样也是党的任务。","language":"中文","translation":false},{"id":"communism-abc-9-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第四十八节 无产阶级专政的阶级性和暂时性","language":"中文","translation":false},{"id":"communism-abc-9-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"资产阶级总是以“全民事业”的伪装来掩盖自己的阶级统治。资产阶级作为一小撮寄生虫又怎能公开承认它把自己的阶级意志强加给全体人民呢？它怎能说国家里它的强盗联盟呢？它当然不能这样做。甚至当资产阶级打出血腥的将军独裁的旗帜时，它也会说这是“全民族的”事业。但是在所谓的“民主共和国”里，资产阶级对人民的欺骗手法则更是巧妙。在这里，资产阶级实行统治和实行独裁总是遵守着某些“看得见的”东西，如它每隔三至四年也给工人们一次投选票的权利，但是并不能让他们参加管理。然而资产阶级却高喊什么“全体人民”管理。","language":"中文","translation":false},{"id":"communism-abc-9-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"苏维埃政权在所有人面前公开承认自己的阶级性。它对自己是阶级的政权，苏维埃国家是穷人的专政这一点无需隐瞒。它甚至在名称上也突出了这一点；工农政府就是所说的苏维埃政权的政府。在宪法中，也就是在全俄苏维埃第三次代表大会制定的我们的苏维埃共和国的根本法中，直截了当指出：“全俄工、兵、农代表苏维埃第三次代表大会认为，目前在同剥削者进行决战的时刻，在任何一个政权机关中都不能让剥削者有立足之地。”这就是说，苏维埃政权不仅承认自己的阶级性，而且要坚决剥夺敌视无产阶级和农民的那些阶级的代表人物的选举权，并把他们从政权机关中清除出去。为什么苏维埃政权能够并且应当如此直言不讳呢？因为它是真正的劳动人民的政权，也就是大多数人的政权。它对自己是诞生于工人街区这一点无需隐瞒。相反，它越是突出自己的出身和作用，它就越能接近群众，越能顺利地同剥削者进行斗争。","language":"中文","translation":false},{"id":"communism-abc-9-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"但是这种情形不会永久地延续下去。问题的实质是需要镇压剥削者的反抗。一旦这些剥削者被镇压、被制服、变得规规矩矩；一旦他们得到了改造，并变成象其他人一样的劳动者，那么当然，任何“压制”就将越来越趋于消失，无产阶级专政也将逐渐消失。","language":"中文","translation":false},{"id":"communism-abc-9-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"这正如我国宪法中所说（见第2篇第5章）：“俄罗斯苏维埃联邦社会主义共和国宪法在当前过渡时期的基本任务是，建立城乡无产阶级和贫农的专政，即建立强大的全俄苏维埃政权，以便彻底镇压资产阶级，消灭人剥削人的现象，实现没有阶级区分和没有国家政权的社会主义。”我们党的任务就是由此而来的。党应当不断地揭露资产阶级一面给予工人以某些权利，而一面又使工人在物质上依附于雇主的种种欺骗行径。党的任务就是要运用无产阶级所拥有的全部手段来镇压剥削者。但与此同时，党的任务还在于，随着对剥削者及其奴仆的镇压，随着对这些人的“改造”，逐渐地削弱和废除那些原来使用的措施。我们假定，知识分子已靠近工人阶级，他们不再对工人阶级牢骚满腹，他们在自己的工作中已经完全站在工人阶级政权的一边，他们同无产阶级和睦相处。如果发生了这样的情况（当然，这只是时间问题），那么，我们就应该给这些知识分子以一切权利，接收他们加入我们的大家庭。当然，在全世界还在向无产阶级共和国进攻的日子里，谈论这种权利扩大还为时过尚早。但是我们应该不断地阐明，这一点将会实现，如果能更快地永远制止住剥削者反对共产主义的所有各种各样的企图，这一点就会实现得更快。这样，无产阶级的国家将逐渐地消亡，变成没有国家的、消灭了任何阶级区分的共产主义社会。","language":"中文","translation":false},{"id":"communism-abc-9-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第四十九节 实现工人阶级权利的物质条件","language":"中文","translation":false},{"id":"communism-abc-9-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"资产阶级民主最主要的骗局之一就是它只给予皮相的权利；法律条文上规定，工人可以完全自由地选举国会，他们拥有和雇主一样的权利（说什么“在法律面前人人平等”）；他们可以自由地结社、集会、出版任何报纸、书刊等等。有些人认为这就是“民主的本质”，并声称这里是一切人、全体人民、全体公民的民主，而不是象在苏维埃共和国那样。","language":"中文","translation":false},{"id":"communism-abc-9-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"首先需要说明，实际上这样的资产阶级民主并不存在。这是一百年前的事情，而现在资产阶级老爷们早已把它废除了。","language":"中文","translation":false},{"id":"communism-abc-9-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"美国在这方面是一个最好的例子。例如美国在战争期间公布了这样的法律：禁止辱骂总统；禁止辱骂盟国；禁止说美国和盟国参战具有卑鄙的物质动机；禁止宣传过早的和平；禁止公开谴责美国政府的政策；禁止称颂或赞扬德国；禁止宣传推翻现存制度，消灭私有制，阶级斗争等等。违者得被叛处三至二十年的苦役。一年期间因违犯这些条文而被捕的工人就有一千五百人左右。“世界产业工人联合会”整个工人组织均遭破坏，部分领导人被杀害。1917年夏天亚利桑那铜矿罢工可以说是所谓“罢工自由”的一个很好的例子。在这次罢工中，工人们遭到枪杀、鞭打，全身被涂上沥青；大批大批的工人家庭被迫出走，沦为乞丐。再以勒德洛（科罗拉多州）的洛克菲勒采煤场的罢工为例，当是洛克菲勒（银行家）的雇佣军枪杀和烧死了数百名男女工人。在美国，尽管国会是在普选的基础上选出来的，但是它却完全是按照托拉斯大王的命令行事；几乎所有的议员都被他们收买过去。一批无冕的皇帝控制着一切：洛克菲勒是银行、石油、粮食、牛奶大王；摩根是银行，铁路大王；施瓦勃是钢铁大王；；斯威夫特是肉类大王；杜邦是在战争中发了大财的火药大王。无须多说，洛克菲勒一小时就能得到一万美元（一美元按战前计算约等于两卢布）；他举行一次宴会就要花去一千一百万美元。有什么东西能抵挡得了这样的势力呢？施瓦勃和洛克菲勒一伙人就这样在“民主”的幌子下掌握着一切！","language":"中文","translation":false},{"id":"communism-abc-9-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"但是，即使实际上存在这样的民主，那么同苏维埃政权相比，它也分文不值。因为对于工人阶级来说，重要的不是要有纸上的权利，而是要有行使权利的可能性。而在资本的统治下这是不可能的，因为在这种制度下，全部财富都为资本家所有。即使根据法律条文规定工人可以举行集会，那他们也找不到场所。例如，由于大资本家的煽惑或者本人对工人的仇恨，所有的小饭店老板都不肯提供场地，结果事情只好罢休。再例如，工人想出版报纸，而且他们也有这个权利。但是要知道，为此需要金钱、纸张、办公地点、印刷厂等等。而所有这些东西都在资本家手里。资本家不提供，结果又是一场空：什么也做不成。靠工人赚的几个铜板是积攒不起多少钱的。结果资产阶级拥有几百万份的报纸，可以天天随心所欲地欺骗人民，而工人，虽然他们在法律条文上也有“权利”，但是实际上却什么也没有。","language":"中文","translation":false},{"id":"communism-abc-9-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"资产阶级民主下的工人“自由”的实质就在这里。这些自由只是停留在纸上，正如人们说的那样，它们是“形式上的”自由；实质上这里没有任何自由，因为这种自由是不可能实现的。这里的情况也和一切生活领域里的情况一样。按照资产阶级的学说，资本主义社会里的老板和工人是平等的，因为存在着“合同自由”；老板愿意雇用工人，工人可以愿意、也可以不愿意受雇。但是要知道，这只是写在纸上的！实际上老板既有钱又吃得饱，而工人既挨饿又受穷。他不得不受雇于人。这是一种什么样的平等呢？尽管纸上写有这种平等，但富人和穷人之间是不可能平等的。所以在资本统治下，“自由”实际上只是一纸空文。","language":"中文","translation":false},{"id":"communism-abc-9-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"相反，在苏维埃共和国，工人阶级的自由首先在于提供了实现自由的可能性。在俄罗斯苏维埃联邦社会主义共和国宪法中直截了当地指出（第2篇第5章）：","language":"中文","translation":false},{"id":"communism-abc-9-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"“第14条 为保障劳动者享有真正的发表意见的自由，俄罗斯苏维埃联邦社会主义共和国取消资本对出版物的控制，把出版报纸、书籍和一切其他印刷品所需要的各种技术设备和物资交给工人阶级和贫农支配，并保证这些出版物在全国自由传播。","language":"中文","translation":false},{"id":"communism-abc-9-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第15条 为保障劳动者享有真正的集会自由，俄罗斯俄罗斯苏维埃联邦社会主义共和国除承认苏维埃共和国公民享有自由集会、游行等等权利外，还把一切适合举行民众大会的场所，连同陈设、照明和取暖设备，交给工人阶级和贫农支配。","language":"中文","translation":false},{"id":"communism-abc-9-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第16条 为保障劳动者享有真正的结社自由，俄罗斯俄罗斯苏维埃联邦社会主义共和国摧毁了有产阶级的经济和政治权利，从而扫除了至今仍在资产阶级社会中阻挠工农享有结社和行动自由的一切障碍，并且尽可能在物质方面和其他方面协助工人和贫农联合组织起来。","language":"中文","translation":false},{"id":"communism-abc-9-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第17条 为保障劳动者真正能够获得知识，俄罗斯苏维埃联邦社会主义共和国的任务是使工人和贫农受到充分全面的免费教育。”","language":"中文","translation":false},{"id":"communism-abc-9-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"资产阶级民主的虚伪自由和无产阶级专政的真正自由之间的巨大差别就在这里。","language":"中文","translation":false},{"id":"communism-abc-9-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在这方面，苏维埃政权和我们的党做了很多事情。贵族的高楼大厦、剧院、印刷厂、纸张等等，——现在一切都属于工人组织和工人国家政权所有。我们今后的任务是要用一切方法帮助无产阶级和农民的落后阶层行使他们的权利。可以通过两种途径来做到这一点。一方面，我们应当沿着既定的道路不断前进，并且千方百计地扩大工人自由的物质条件。这就是说：尽可能寻找和新建一些新的场所，建立新的印刷厂、新盖工人文化宫等等。另一方面，就是要向落后阶层说明，由于愚昧落后和文化水平低，既有的条件还没有得到充分利用。","language":"中文","translation":false},{"id":"communism-abc-9-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第五十节 劳动者不分性别、宗教、种族一律平等","language":"中文","translation":false},{"id":"communism-abc-9-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"资产阶级民主口头上宣布了一系列自由，但对于被压迫者来说，这些自由是神秘莫测和高不可攀的。顺便说一句，资产阶级民主不止一次地宣扬人们不分性别、宗教、种族和民族一律平等。它夸口说，在资产阶级民主制度下，男人和女人，白种人、黄种人、欧洲人和亚洲人，佛教徒、基督教徒、犹太人等等一律平等。事实上，任何这样的平等资产阶级也没有实行过。相反，在帝国主义时代，到处都在拼命地强化种族压迫和民族压迫（关于这一点详见下一章）。甚至对妇女，资产阶级民主也从来没有实行过任何平等。妇女仍然是无权的生物和家畜，是供男人使用的床上用品。","language":"中文","translation":false},{"id":"communism-abc-9-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在资本主义社会里，女工特别受压迫，处在无权状态；她们在各个方面的权利，甚至比资产阶级允许男工所享有的那些少得可怜的权利还要少。妇女的议会选举权只在两、三个国家里存在；在财产继承方面，妇女只能得到最少的一份；在家庭关系方面，她们总是从属于丈夫，总是无辜受过；总之，在资产阶级民主下，到处都实行着一套酷似野蛮人的制度，对妻子就象一件东西，玩偶或者役畜一样，可以进行交换、买卖、处罚、或者偷窃。“母鸡不是鸟，老婆不是人”——在奴隶社会里就是这样认为的。这种状况对无产阶级极为不利。在本书的第一部分里我们已经知道，妇女在工人的总数当中占了很大一部分。不言而喻，如果无产阶级的两部分之间存在着不平等，那么，无产阶级的斗争也就会非常软弱无力。没有女性无产阶级的帮助，总的胜利是不可想象的，“劳动的解放”是不可想象的。因此，应该使男女两部分无产阶级成为完整的战斗的集体，并通过实行平等来使这个集团更加巩固，这就是工人阶级的利益所在。苏维埃政权第一次在生活的一切领域里实行这样的平等；在婚姻、家庭关系，政治权利等等方面，现在妇女同男子处处都是平等的。","language":"中文","translation":false},{"id":"communism-abc-9-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"党的任务是促进这种平等的实现。这里首先需要不断向广大劳动者阶层说明，奴役妇女对他们是非常有害的。甚至直到今天在工人当中还把妻子只看作是“老娘们”；在农村，当“老娘们”也起来从事公共事业的时候，常常遭到讥笑。在苏维埃共和国，妇女劳动者拥有同男子一样的权利，她们可以选举各级苏维埃和被选进苏维埃，可以担任任何委员的职务，在军队里，在国民经济中，在国家管理机关里，执行任何工作。","language":"中文","translation":false},{"id":"communism-abc-9-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"但是，我们的女工比男工落后得多。而且很多人也看不起她们。这里需要进行顽强的工作：在男子当中，要使他们不再给妇女劳动者“挡路”；在妇女当中，要让她们行使自己的权利，不胆怯，不腼腆。","language":"中文","translation":false},{"id":"communism-abc-9-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"要记住：我们应该使甚至每一个厨娘都学会管理国家。","language":"中文","translation":false},{"id":"communism-abc-9-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"我们在上面已经看到，最重要的不是把权利写在纸上，而是要有可能实现这些权利。如果妇女劳动者忙于家务劳动，跑市场，排长队，洗衣服，看孩子，被这些家务事忙得不可开交，她们还怎么能去行使自己的权利呢？","language":"中文","translation":false},{"id":"communism-abc-9-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"苏维埃政权和我们党的任务应当是设法减轻妇女劳动者的家务劳动，把她们从这种旧时的和落后的关系中解脱出来。组织设有中心洗衣站的家庭公社（不是在那里互相骂架，而是在那里过真正人的生活）；组织公共食堂；组织托儿所、幼儿园、运动场、儿童夏令营，开设具有儿童公共伙食的学校等等——有了这些就一定能减轻妇女的负担，使她们有可能从事一切男性无产者从事的事业。","language":"中文","translation":false},{"id":"communism-abc-9-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"当然，在破产和饥荒的日子里，很难把这件事做得尽善尽美。但是，党应当尽到一切可能，以便使女工也能参加公共的工作。","language":"中文","translation":false},{"id":"communism-abc-9-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"关于民族、种族平权等等需要看下一章。在这里，我们只引用我国宪法中有关这个问题的某些段落（第2篇第5章）：","language":"中文","translation":false},{"id":"communism-abc-9-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"“第20条 俄罗斯苏维埃联邦社会主义共和国从各国劳动者的团结出发，对于居住在俄罗斯共和国境内的外国人，只要他们从事劳动，属于工人阶级或属于不使用他们劳动的农民阶级，均给予俄国公民所享有的一切政治权利，并授权地方苏维埃不经过任何繁杂的手续，给予这些外国人以俄国公民权。","language":"中文","translation":false},{"id":"communism-abc-9-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第21条 俄罗斯苏维埃联邦社会主义共和国对于一切因政治罪名和宗教罪名而受到迫害的外国人，给予居住权。","language":"中文","translation":false},{"id":"communism-abc-9-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第22条 俄罗斯苏维埃联邦社会主义共和国承认一切公民不分种族和民族均享有平等的权利，同时宣布，凡是在这方面建立或容许某种特权或优待，以及压迫少数民族或限制其平等权利，都是违反共和国根本法的行为。”","language":"中文","translation":false},{"id":"communism-abc-9-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第五十一节 国会制度和苏维埃制度","language":"中文","translation":false},{"id":"communism-abc-9-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在一些资产阶级民主国家里，最高首脑机关是所谓的国会。这是一个通过某种方法选举出来的机构：有的国家，只有富人才能参加选举，有的国家，也准许部分穷人参加选举，有的国家，所有达到一定年龄的男子都可以参加选举，还有的国家，妇女也可以参加选举。","language":"中文","translation":false},{"id":"communism-abc-9-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"但是，甚至在那些根据普选权选举国会的地方，国会的首脑即多数人也都是资产阶级安插的人。为什么到处都是这样呢？读了我们前面所说的一切之后，这是不难理解的。我们看到，在国家占人口多数的工人享有发言权。但我们也看到，一切财富都在资本家手里，所有的报纸也都在他们手里，他们有集会的场所，有为他们效劳的画家、印刷厂、大量的纸张；宣传家们在从所有的讲坛替他们说话；我们也看到，穷苦工人整天疲于奔命，他们没有时间，也没有地方集会，资产阶级的钻营者、资产阶级的代理人（各种各样的律师、记者、演说家）在工人中间乱窜，他们提出一些似乎很体面的口号，对工人进行恭维笼络；我们看到，辛迪加老板甚至不惜花费巨大钱财来收买原先是正直的工人当选者，给他们地位，在报纸上对他们大事颂扬等等，等等。这样我们就会明白，为什么甚至在这样一些国会里大多数也都是资产阶级、金融资本、银行大王的秘密的或者公开的代理人。","language":"中文","translation":false},{"id":"communism-abc-9-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"因此，要选举劳动群众自己的人是很困难的。","language":"中文","translation":false},{"id":"communism-abc-9-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"而既然当选为国会议员，——那就一切都完了：那时他就看不起自己的选取民了，因为在三、四年之内，他是有保障的。他用不着他们了。他把自己出卖给各个方面。然而又不能罢免他，因为根据法律是不允许的。","language":"中文","translation":false},{"id":"communism-abc-9-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在资产阶级民主共和国的国会制度下，情况就是这样。在苏维埃共和国则完全是另一种情况。在这里，寄生虫——商人和工厂主，高级僧侣和地主，将军和富农——没有发言权。他们没有选举权，也没有被选举权。因此对于工人和贫民来说，选举是很简单和很容易的。而且在这以后，任何一个当选的苏维埃代表都能被他的工人选民罢免并由另外的人来接替他的位置。如果代表失职，背叛了自己的旗帜等等，他就可能被罢免。这种罢免权在任何地方也没有象在苏维埃共和国行使得这样广泛。","language":"中文","translation":false},{"id":"communism-abc-9-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在资产阶级共和国，国会是个“清谈馆”；议员们唯一要作的事情就是进行辩论和发表演说。真正的实际性的工作是由官员、部长们来做的。国会还批准法律并通过咨询来“监督”部长，投票表决政府提议。正如人们所说的那样，立法权在国会，而执行权却在内阁。因此，干事情的不是国会：国会和它的议员只限于清谈。在苏维埃制度下，情况完全不是这样。苏维埃代表大会是最上层的即最高的机关。宪法中指出：“全俄苏维埃代表大会是俄罗斯苏维埃联邦社会主义共和国的最高权力机关。”它一年至少应当举行两次会议；它要对自己的工作作出总结和通过适当法案，但是，代表大会的所有代表，这不是专业空谈家，而是做日常工作的“实干家”。在代表大会闭会期间，大会选出的中央执行委员会是最高权力机关。它同时既颁布法律，又“发布命令”；它既掌握执行的权利，也掌握立法的权利；它的分部是各人民委员部；它的委员分别在这些委员部里工作。所以，中面执行委员会是一个办事机构。","language":"中文","translation":false},{"id":"communism-abc-9-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"无论是中央执行委员会，还是任何其他的苏维埃机关都和很多群众性的工人组织有密切的联系，并依靠它们进行工作：苏维埃机关依靠共产党，依靠工会，依靠工厂委员会，依靠合作社。这些组织拥有几千万劳动者，他们都双手支持苏维埃政权。劳动群众通过这些组织真正参加国家的管理。工人的共产党或工会把自己信任的人派到各种岗位和担任各种职务。可见，优秀工人到那里去不只是说话，而是去管理。在所谓的民主共和国里根本没有这样的事。在那里，工人选取民只是投了选票，就万事大吉了。正如资产阶级对他们说的那样，他们完成了自己的“公民义务”，至于别的就用不着他多操心了。","language":"中文","translation":false},{"id":"communism-abc-9-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"这里是一场很大的骗局。为什么？仍然还是我们前面所知道的那个原因。在纸面上，似乎工人“参加了”什么，而实际上，他们完全与此无关；管理一切和决定一切的是一帮专门的、同群众没有联系的资产阶级官吏即所谓的官僚。管理机关脱离了群众，群众和它毫不相干。","language":"中文","translation":false},{"id":"communism-abc-9-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在十六或十七世纪以前，国家的官吏只是从贵族中委任。随着过渡到资本主义制度，出现了职业官吏。在现代，这种职业官吏主要是从所谓的知识分子当中招募，而上层官吏是由大资产阶级推荐的。甚至连那些小官吏也是用忠于强盗国家的特殊精神来培养的，其中最有才华的人都得到官衔、勋章、爵位，即所谓的“职务升迁”的机会。因此，在大多数情况下所有这些先生们身上都浸透着对“平民百姓”的鄙视心理。这些官吏的数量及其增加的情形是怎样的，可以从下列数字（我们引用奥尔舍夫斯基《官僚制度》一书中的数字）来判断：在奥地利，1874年官吏的数量约为二万七千人，1891年为三万六千人，1900年为十六万九千人；在法国，1891年这种公务官吏已经有一百五十万人（约占总人口的百分之四）；在英国，1891年约有一百万人（百分之二点六）；在美国，1890年约有七十五万人，等等。甚至资产阶级作家奥尔舍夫斯基也认为这个阶层有以下基本特性：刻板和保守；文牍主义；打官腔；琐碎。但是，在所有资本主义国家里恰恰是这些官吏在进行管理。我们重复一遍，高级官员主要是从大资产阶级和贵族地主圈子里招募的。在资产阶级掌握政权的资本主义社会里，事情也不可能不是这样。在苏维埃共和国，群众不但参加选举（而且选举的不是卖身投靠的律师，而是自己人），而且还参加管理，因为苏维埃和几十个其他的群众性工人组织都参加了这个管理。","language":"中文","translation":false},{"id":"communism-abc-9-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"至于苏维埃本身，连它们的选举本身也都考虑到同群众的联系。因为选举苏维埃不是按区域，而是按工作地点（按工厂等等），或者按所谓“生产单位”进行的。通过共同劳动而团结在一起的人们选举自己的委托人、自己的“代表”。","language":"中文","translation":false},{"id":"communism-abc-9-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"苏维埃政权就是这样实现无产阶级民主的，这是一种最高的、最民众化的民主形式。","language":"中文","translation":false},{"id":"communism-abc-9-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"党的下一步的任务是什么呢？总的路线是很清楚的：这就是要在越来越广阔的范围内实现无产阶级民主，使在职的公务人员（代表当选人等等）更接近群众；吸收越来越多的群众直接参加管理；最后，要让千百万人来监督自己的代表和他们的工作。公务人员应当尽可能广泛地负起责任和报告工作的情况。","language":"中文","translation":false},{"id":"communism-abc-9-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"这一切任务的实现需要进行巨大的工作。在这里会遇到大量的实际障碍。必须克服所有这些障碍，争取达到国家机关和积极建设共产主义的无产阶级和农村贫农群众的充分的、亲密无间的团结。","language":"中文","translation":false},{"id":"communism-abc-9-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第五十二节 军队和苏维埃政权","language":"中文","translation":false},{"id":"communism-abc-9-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"无产阶级的民主制和任何国家政权一样，拥有自己的武装力量，自己的陆军和海军。在资产阶级民主国家里，军队是镇压工人阶级的工具和保护资产阶级的钱包的工具。无产阶级的军队即苏维埃共和国的红军，是为无产阶级反对资产阶级的斗争的阶级目标服务的。所以资产阶级军队和无产阶级不管在本身的状况上还是在政治权利上，都有着深刻的区别。资产阶级只能撒谎说，它使自己的军队立于“政治之外”。事实上，它是在保卫“全民族利益”的旗号下，把军队变成自己强盗政治和反革命政治的工具。它竭力把军队和人民分开。它千方百计地阻挠士兵实现自己的政治权利。在苏维埃共和国则完全是另一种情况。第一，在这里，无产阶级公开声明，我们的军队是反对资产阶级的政治的阶级斗争的工具。第二，在这里，国家运用一切办法促进军队同人民打成一片；工人和红军战士共同组织自己的苏维埃（所以被称为“工人和红军士兵代表苏维埃”）。工人和红军战士上同一些学校，一起听课，出席集会，参加示威游行。工人和红军战士不止一次互赠战旗。在苏维埃国家里，国家不是别的，而是劳动者的伟大共和国，只要红军同革命的工人阶级的团结统一得到保证，就一定能取得对敌斗争的胜利。","language":"中文","translation":false},{"id":"communism-abc-9-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"工人阶级同军队，军队同工人阶级，越是打成一片，我们的战斗的革命力量就越巩固，很清楚，我们的党应该支持，发展和加强这种关系。经验已经证明了军队同无产阶级组织的关系对军队的影响。只要回想一下1919年夏季对高尔察克和同年秋季对邓尼金的反击就够了。这些反击之所以能获得胜利，就是因为党内、工会组织等等方面的工人同志帮助了军队，密切了同军队的关系，参加了军队的工作。因此，无产阶级的红军是真正的，而不是口头上的第一支人民军队，它是按照劳动者意愿建立起来的，为劳动者所组成，同劳动者保持着密不可分的关系，并且通过自己在苏维埃的代表管理着国家。它不是某种独立的东西，而是同样的工人阶级和在工人阶级领导下前进的农村贫农。它同后方的劳动者生活在一起。不断加强这种关系是我们党必须完成的任务。","language":"中文","translation":false},{"id":"communism-abc-9-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第五十三节 无产阶级的领导作用","language":"中文","translation":false},{"id":"communism-abc-9-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"我们的革命是一场共产主义革命，在这里，无产阶级起着先锋作用、领袖作用。无产阶级是最团结和最有组织的阶级。无产阶级是唯一的这样的一个阶级，在资本主义社会里，它的生活条件使它形成了正确的共产主义观点，给它指明了正确的目标和通向这个目标的正确的道路。因此，无产阶级是整个革命的领导者和领袖是毫不奇怪的。农民（中农，甚至一部分贫农）不止一次地表现过动摇。只有跟着无产阶级走，他们才能有所成就。反之，如果他们与无产阶级背道而驰，那就一定会受到某一个邓尼金、高尔察克或其他地主、资本家和将军的蹂躏。","language":"中文","translation":false},{"id":"communism-abc-9-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"无产阶级的这种领导作用、领导意义，甚至在我们的苏维埃宪法中也有反映。根据我国法律，无产阶级在政治权利上占有某些优势。例如，召开苏维埃代表大会规定城市工人的代表要比农民代表多。","language":"中文","translation":false},{"id":"communism-abc-9-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"宪法中有下列一些相应的条款：","language":"中文","translation":false},{"id":"communism-abc-9-77","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":77,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"“全俄苏维埃代表大会应由苏维埃代表大会和州苏维埃代表大会代表组成，市苏维埃选出的代表按每二万五千选民选举一人的比例产生，州苏维埃代表大会选出的代表按每十二万五千居民选举一人的比例产生。”（第3篇第6章第25条）","language":"中文","translation":false},{"id":"communism-abc-9-78","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":78,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"“各级地方苏维埃代表大会的组织方式如下：","language":"中文","translation":false},{"id":"communism-abc-9-79","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":79,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"1．省苏维埃代表大会由市苏维埃代表大会和县苏维埃代表大会代表组成。县苏维埃代表大会选出的代表按每二万五千居民选举一人的比例产生，市苏维埃选出的代表按每五千选民选举一人的比例产生，但是全省代表不得超过五百人。如果在省苏维埃大会召开之前刚召开了州苏维埃代表大会，则省苏维埃代表大会的代表由州苏维埃代表大会选举，其比例与县苏维埃代表大会产生代表的比例相同。","language":"中文","translation":false},{"id":"communism-abc-9-80","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":80,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"2．州（专区）苏维埃代表大会由市苏维埃代表和乡苏维埃代表大会代表组成。乡苏维埃代表大会选出的代表按每一万居民选举一人的比例产生，市苏维埃选举代表按每二千选民选举一人的比例产生，但是全州（专区）代表不得超过三百人。如果在州苏维埃大会召开之前刚召开了县苏维埃代表大会，则州苏维埃代表大会的代表由县苏维埃代表大会（而不是乡苏维埃代表大会）选举，其比例与乡苏维埃代表大会产生的比例相同。”（第3篇第10章第53条）","language":"中文","translation":false},{"id":"communism-abc-9-81","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":81,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"诚然，在城市里代表是按选民的比例产生，而在农村则按全体居民（这里不但有劳动者，而且包括富农、神父、农业资产阶级等等，同时还包括没有选举权的儿童）的比例产生的。这就是说，城市工人对农民的优势完全不是象初看起来的那样大。但是优势毕竟无疑是有的。","language":"中文","translation":false},{"id":"communism-abc-9-82","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":82,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"宪法上所确定的这种优势只反映在实际生活中存在的情况，即城市里团结起来的无产阶级领导着分散的农村群众。","language":"中文","translation":false},{"id":"communism-abc-9-83","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":83,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"我们党的任务是要首先阐明这种优势的暂时性。随着更多的落后农村群众受到教育，在他们在经验中确信工人路线的正确和益处之后，当他们感到他们不能和资产阶级同路，而只能和无产阶级同路的时候，不言而喻，这种不平等就会成为过去，因为那时在实际生活中不平等的现象也就不存在了。","language":"中文","translation":false},{"id":"communism-abc-9-84","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":84,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"我们党的责任就在于要运用无产阶级的这种优势，以便尽可能有力地影响农村，把先进工人同农民结合起来，从而使农村贫农受到革命教育。为工人阶级保留这些优势不是为了使它固步自封和与农村隔绝，相反，是为了工人阶级通过使用这些优势，通过它在苏维埃和整个国家管理机关中所占的很大的比重，使自己同农村联系起来，促进无产阶级同中农和贫农的同志式团结，并把他们从富农、神父、从前的地主的影响下解脱出来。","language":"中文","translation":false},{"id":"communism-abc-9-85","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":85,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第五十四节 官僚制度和苏维埃政权","language":"中文","translation":false},{"id":"communism-abc-9-86","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":86,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"苏维埃政权作为一个新阶级——无产阶级的政权，是在旧的资产阶级的政权的废墟上组织起来的。在无产阶级组织自己的政权之前，它摧毁了异己的、自己敌人的政权。在苏维埃政权的帮助下，它彻底粉碎和摧毁了旧国家的残余。无产阶级摧毁了旧的警察、侦察机关的残余，宪兵、沙皇资产阶级的法庭及其检查官和雇佣保镖；清理了大量旧的办公机构，废除了资产阶级内阁及其官员等等。在这里，无产阶级的目的是什么呢？我们党的总任务又是什么呢？我们党的总任务又是什么呢？关于这一点我们在前边，即在本书的第一部分里已经谈过。这个任务在于，要使群众本身来取代旧官吏的地位；要使全体劳动居民插手管理事业（轮流值勤，有些职务任期可以短些，有一些可以长一些）。但是我们在这里碰到一系列非常严重的困难。","language":"中文","translation":false},{"id":"communism-abc-9-87","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":87,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第一，城市里的落后阶层不发达、愚昧、胆怯、而农村则更甚。积极、活跃、勇敢、分析能力很强的“先进分子”只是人数不多的一个阶层。其他的阶层刚刚在起步赶上。但也有很多这样的人，他们还害怕担任工作，很多人还不了解自己的权利并且还没有感到自己是国家的主人。这也毫不奇怪。多少世纪来被宰割和被压迫的群众根本不可能由半野蛮状况一下子就转到管理国家上来。最初涌现出来的最先进的、最发达的阶层：例如彼得堡的工人就是这样，到处都可以遇见他们；他们常常是军队里的政委、工业的组织者、农村里的“执委”、宣传员、最高苏维埃机关成员、报告员。其余的群众也渐渐有所转变，涌现一批新人，他们代替了先前的人，并且自己也在慢慢学习。但是，不言而喻，文化水平普遍很低，这是一个很大的障碍。","language":"中文","translation":false},{"id":"communism-abc-9-88","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":88,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第二，缺乏管理技能。这甚至也涉及到一些优秀同志。要知道，工人阶级是第一次把政权掌握在自己手里的。它从来没有管理过，也从来没有学习过管理事业。相反，沙皇政府，包括古契柯夫-克伦斯基的短命政府在内，数十年来一直都竭力设法不让无产阶级参与这件事。因为资产阶级和地主的国家不是教育的组织，而镇压工人的组织。很清楚，现在，当工人阶级掌握了政权以后，它要在实践中学习，会不止一次地犯错误。它会在这些错误中吸取教训，然而它仍然会犯错误。","language":"中文","translation":false},{"id":"communism-abc-9-89","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":89,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第三，旧资产阶级专家。无产阶级不得不使用他们。无产阶级使他们服从于自己，强迫他们工作，挫败他们的怠工。无产阶级最终一定能按照自己的意愿把他们彻底改造过来。但这些人暂且还常常保持着一套自己的旧习惯和旧方法：看不起群众，脱离群众，自行其是，文牍主义、办事拖延等等，这些也传染给了我们的人。","language":"中文","translation":false},{"id":"communism-abc-9-90","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":90,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第四，吸收优秀力量入伍。在国内战争最艰苦的条件下，部队急需特别忠实、正直、勇敢的战士，这就不得不把自己最优秀的人派往前线工作。这样一来，后方原有的先进分子就越来越少。","language":"中文","translation":false},{"id":"communism-abc-9-91","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":91,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"所有这些情况给我们的工作造成了不可想象的困难，并且在某种程度上助长了苏维埃内部官僚主义的局部滋生。这对于无产阶级是一个很大的危险。无产阶级摧毁旧的官僚国家并不是为了使它从下面再发展起来。因此，我们党应该努力防止这种危险。要防止这种危险，只能靠吸收群众参加工作的办法。当然，最主要的，是要普遍提高工人和农民群众的文化水平，教育群众，发展文化教育事业。但与此同时，也必须采取一系列其他措施，我们党在这方面建议：","language":"中文","translation":false},{"id":"communism-abc-9-92","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":92,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"必须吸收苏维埃的每一个成员来完成国家管理方面的一定工作。苏维埃的每一个成员不但应该讨论一般措施，而且自己应该参加一项社会事业，也就是说，应该担任一项社会职务。","language":"中文","translation":false},{"id":"communism-abc-9-93","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":93,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"经常不断地变换工作。这就是说，一个同志应当过一定时间变换一个工作，并逐渐熟悉所有最主要的管理部门。他不应该成年都呆在同一个地方，因为那样他自己也就可能变成一个官僚；他应该在熟悉一个地方之后，再转到另一个地方。","language":"中文","translation":false},{"id":"communism-abc-9-94","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":94,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"最后，党建议把不断吸收全体劳动居民人人参加国家管理的工作当做工作的总方针。这一点实质上是我们的政治基础。我们在这方面已经采取了一些步骤。例如，在彼得堡曾经有上万名无产者参加了对资产阶级的搜查；几乎所有的工人居民都担负了保卫城市的责任；女工代替男人担负起民警工作。比如说，在苏维埃里，可以吸收非苏维埃的成员做助手，让这些人轮流视察执行委员会或各部门的工作；在工厂委员会和工会里也可以这样做，使全体工人都能轮流地担任这些工作。总之，我们应该通过这种或那种形式（哪种形式更为合适，这将由实践来证明）继续沿着巴黎公社的道路前进：简化管理事务，吸收群众参加，消灭各种各样的官僚主义。群众参加得愈广泛，无产阶级专政消亡得就越快。当所有的成年人和健康人都毫无例外地来参加管理的时候，任何官僚制度的最后残余就将消失。有了这一点，再加上反抗的资产阶级的消失，就将埋葬掉任何国家：人们管理的将不是人，而只是物：机器、建筑物、机车、仪器。这将是完全的共产主义制度。","language":"中文","translation":false},{"id":"communism-abc-9-95","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":95,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"在取得对帝国主义者的完全胜利之后，国家的消亡将会是特别快的。现在，在残酷的国内战争期间，我们还必须按照战争的轨道来建设我们的一切组织。因此，苏维埃政权的机构也如此进行了改组。有时甚至没有时间召开苏维埃会议。几乎所有的事情都照例是执行委员会决定。","language":"中文","translation":false},{"id":"communism-abc-9-96","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":96,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"这种现象是由于苏维埃共和国的战争状态造成的：我们这里不是一般的无产阶级专政，而是军事无产阶级专政：共和国是一座武装起来的营垒。当然，不会永远这样，一旦我们一切组织不再需要军事体制时，这种情况就将消失。","language":"中文","translation":false},{"id":"communism-abc-9-97","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第六章 苏维埃政权","page":9,"paragraph":97,"url":"https://www.marxists.org/chinese/bukharin/1919/08.htm","text":"第六章书目：尼·列宁（弗·伊里奇）《国家与革命》。尼·列宁《布尔什维克能保持政权吗？》。恩·奥新斯基《民主共和国还是苏维埃共和国》。尼·列宁《共产国际第一次代表大会通过的关于资产阶级和无产阶级民主的提纲》。尼·列宁《无产阶级革命和叛徒考茨基》。彼·伊·斯图契卡《俄罗斯苏维埃联邦社会主义共和国宪法问答》。普通通俗读物：布哈林《代议制的共和国还是苏维埃共和国》（小册子里专门的一章：《共产党人的纲领》）。卡尔宾斯基《什么是苏维埃政权》。卡尔宾斯基和拉皮斯《什么是苏维埃政权和如何建设这一政权》。","language":"中文","translation":false},{"id":"communism-abc-10-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-10-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"第七章 民族问题和共产主义","language":"中文","translation":false},{"id":"communism-abc-10-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"· 第五十五节 民族压迫","language":"中文","translation":false},{"id":"communism-abc-10-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"· 第五十六节 无产阶级的统一","language":"中文","translation":false},{"id":"communism-abc-10-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"· 第五十七节 产生民族仇恨的原因","language":"中文","translation":false},{"id":"communism-abc-10-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"· 第五十八节 民族平权和自决权；联邦","language":"中文","translation":false},{"id":"communism-abc-10-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"· 第五十九节 谁体现了“民族意志”","language":"中文","translation":false},{"id":"communism-abc-10-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"· 第 六十 节 排犹主义和无产阶级","language":"中文","translation":false},{"id":"communism-abc-10-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"民族压迫是人压迫人的现象之一。除了阶级隔阂之外，民族分离、民族敌视和仇恨也是分离人类的隔阂之一。","language":"中文","translation":false},{"id":"communism-abc-10-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"资产阶级为了自身的利益而采取的民族毒化方针是对无产阶级实行愚民政策和模糊它的阶级意识的方法之一。","language":"中文","translation":false},{"id":"communism-abc-10-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"让我们研究一下，为了共产主义事业的尽快胜利，自觉的无产阶级应该如何对待民族问题，应该如何解决这些问题。","language":"中文","translation":false},{"id":"communism-abc-10-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"民族或部族——这是具有共同语言和住在固定地域的人们的整体。也还有其他一些民族特征，但这是最主要的和最基本的[1]。","language":"中文","translation":false},{"id":"communism-abc-10-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"什么是民族压迫，最好举例来说明。沙皇政府迫害犹太人，不允许他们在俄国到处居住，不让他们担任国家公职，限制他们入学，制造排犹暴行等等。同样，政府也不允许乌克兰人在学校里用乌克兰语教育儿童，禁止用本民族语言出版报纸，同时不准国内任何一个民族能自由地决定是否愿意成为俄国国家的一员。","language":"中文","translation":false},{"id":"communism-abc-10-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"德国政府关闭了波兰的学校。奥国政府禁止使用捷克语言，强迫捷克人讲德语。英国资产阶级过去和现在都在欺侮非洲和亚洲的土著人，征服那些落后的、半开化的民族，对他们进行掠夺，并枪杀那些企图摆脱压迫的人。","language":"中文","translation":false},{"id":"communism-abc-10-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"总之，如果在一个国家里，一个民族享有一切权利，而另一个民族只享有部分权利，如果强迫弱小的民族并入强大的民族，并且不顾它的意愿，硬要它采用异族的语言、习俗等等，不允许它按自己的方式生活——这就是民族压迫和民族不平等。","language":"中文","translation":false},{"id":"communism-abc-10-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"第五十六节 无产阶级的统一","language":"中文","translation":false},{"id":"communism-abc-10-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"首先我们应该提出和解决一个最主要的和根本的问题：是否德国人、法国人、英国人、犹太人、中国人、鞑靼人，不管他们是属于哪一个阶级，一律都是俄国工人和农民的敌人？对于其他民族的人，是否只要他们说的是异族的语言，具有黑色或黄色皮肤，有着不同的风俗和习惯，就可以采取仇视和不信任的态度呢？显然，不可以，而且也不应该。德国工人、法国工人、黑人工人和俄国工人一样，也是无产阶级。不管各不同国家的工人说的是何种语言，他们所处的地位的实质都在于他们都受资本的剥削，在贫穷、受压迫和无权这一点上他们都是同志。","language":"中文","translation":false},{"id":"communism-abc-10-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"俄国的资本家用地道的俄国粗俗语言骂人，按照俄国方式打人的嘴巴，用真正的俄国皮鞭抽打罢工者，这样一来，俄国的工人是不是仅仅因为这一点就可以对本国的资本家更亲一些呢？当然不可以，就象德国工人不能只是因为德国的资本家在侮辱他们时用的是德国话和德国方式，就可以对本国的资本家更亲一些一样，全世界的工人在阶级上都是兄弟，都是各国资本家的敌人。","language":"中文","translation":false},{"id":"communism-abc-10-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"关于各国贫苦农民的情况也同样可以这样说。对于俄国农民——贫农和中农来说，匈牙利的半无产阶级、西西里和比利时的贫农要比自己的俄国富农-财主更为可亲和可贵，至于象普里什凯维奇和马尔柯夫一类的纯俄国的凶残地主，那就更不用说了。","language":"中文","translation":false},{"id":"communism-abc-10-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"但是全世界的工人不能仅仅满足于意识到他们都是阶级的兄弟，是受压迫和奴役的患难兄弟。如果他们只是在各自用自己的语言来咒骂自己的资本家，如果他们只是在互为对方擦眼泪和只是为了自己才在国内进行反对自己的敌人的斗争，那就很不好。受压迫和奴役的兄弟应该是在结成一个反对资本家的世界联盟这一点上成为兄弟。他们应该忘记妨碍他们的一切民族差别，团结成一个强大的联盟去进行旨在反对资本家的共同斗争。只有结成这种国际联盟，他们才能战胜世界资本。因此，还在七十多年以前，共产主义的奠基者马克思和恩格斯就在其著名的《共产党宣言》中提出了“全世界无产者，联合起来！”的伟大口号。","language":"中文","translation":false},{"id":"communism-abc-10-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"工人阶级必须克服所有的民族偏见和敌对情绪。这不仅是为了对资本进行全球进攻和取得彻底的胜利，而且也是为了组织统一的世界经济。不仅仅苏维埃俄国离不开顿涅茨的煤、巴库的石油、土耳其斯坦的棉花，而且整个欧洲也都离不开俄国的木材、苎麻、亚麻、白金和美国的粮食，意大利离不开英国的煤矿，英国离不开埃及的棉花，等等，等等。资产阶级组织不起世界经济，它在这方面遭到过失败。只有无产阶级才能建立起这样的经济。为此它应该提出这样的口号：整个世界及其全部财富属于整个劳动世界。但是这样的口号意味着德国工人完全放弃自己的民族财富，英国工人也完全放弃自己的财富，等等。如果在工业和农业国际化的道路上出现什么民族偏见和民族贪欲，那就要彻底把它搬掉，不管它是在多么动听的借口下出现的！","language":"中文","translation":false},{"id":"communism-abc-10-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"第五十七节 产生民族仇恨的原因","language":"中文","translation":false},{"id":"communism-abc-10-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"但是，只是对民族压迫和民族偏见宣战，只是宣布在反对资本的斗争中进行国际联合和结成业已胜利的无产阶级的世界经济联盟，对共产党人说来是不够的。还必须设法尽快地克服劳动群众中的各种民族沙文主义和利己主义、民族保守和自负以及民族猜疑心理。这是人类生活的野蛮时期和封建-资本主义时代实行的野蛮的民族毒化政策留下的一笔遗产，它象一座沉重的大山继续压在世界无产阶级的头上。","language":"中文","translation":false},{"id":"communism-abc-10-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"民族的不和与敌对情绪由来已久。曾经有过这样一段时期，各个部落不仅在为争夺土地和森林而相互残杀，并且干脆要把另一部落里的自己的同类吃掉。这一个民族对另一个民族、尤其是一个人种对另一个人种的野兽般的不信任和敌对心理，今天在各国的工人和农民当中继续存在着。随着世界性交流的发展，经济上的接近，在一块地域上不同民族的迁移和混合，特别是在各国工人共同的阶级斗争的基础上，这种部落性的敌对心理的残余将逐渐消失。但是如果在民族敌对心理中掺合进一些阶级利益上的矛盾，抑或只是这种矛盾的一点阴影，那么，这些民族敌对心理的残余就不仅不会减少，而且会变本加厉地爆发出来。","language":"中文","translation":false},{"id":"communism-abc-10-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"每个国家的资产阶级都剥削和压迫本国的无产阶级。但是它却尽一切努力向无产阶级证明，他们的敌人并不是资产阶级，而是他们周围的其他民族。德国资产阶级向本国的工人大声叫喊：揍法国人，揍英国人！英国资产阶级也在大声叫喊：揍德国人！特别是在最近时期，各国资产阶级都在开始大声叫喊：揍犹太人！所有这一切都是为了把工人阶级同自己的压迫者资本家进行阶级斗争转移到民族斗争上去。","language":"中文","translation":false},{"id":"communism-abc-10-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"但是，为了使工人放弃争取社会主义斗争，资产阶级并不满足于仅仅实行民族毒化政策。它企图从物质上鼓励工人去压迫别国的人民。在不久前的世界大战时期，德国资产阶级高喊着“德国、德国高于一切”（德国国歌），德国资产阶级的经济学家千方百计向本国工人证明，他们将从胜利，即从压迫和掠夺战败国的工人中赢得许多好处。资产阶级实际上在战前就在用掠夺殖民地和压迫落后、弱小民族得来的利润来贿买工人阶级的上层。以部分报酬最高的人为代表的先进欧洲国家的工人，接受了资本家的挑拨，力图使社会爱国主义者相信，既然他们参加了掠夺殖民地和半依附民族的行动，那么他们也是有祖国的。在资本主义制度下工人一变成爱国主义者，就会为了几文钱而出卖自己真正的祖国即社会主义，成为屠杀落后与弱小民族的刽子手。","language":"中文","translation":false},{"id":"communism-abc-10-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"第五十八节 民族平权和自决权；联邦","language":"中文","translation":false},{"id":"communism-abc-10-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"共产党宣布对任何人压迫人的现象进行无情的战斗，以最坚决的手段反对资本主义制度下不可避免的民族压迫。它尤其坚决和无情地反对工人阶级本身插手这种压迫的行为。但是，光是大国和强国的无产阶级拒绝参与本国资产阶级和贵族压迫其他民族的企图还是不够的。还应使被压迫民族的无产阶级不要对自己在压迫者国家的同志抱有不信任的感情。当捷克人受到奥地利的德国资产阶级的压迫时，捷克工人认为所有的德国人通通是自己的压迫者。波兰人受过我国的沙皇的压迫，但是波兰人民不是仅仅对俄国的沙皇、地主和资本家，而是对所有的俄国人，都表示不信任。为了从根本上消除被压迫民族的工人对压迫者民族的工人的任何不信任，不仅必须宣布，而且必须在实际上实行完全的民族平等。应该在语言、学校、宗教等等方面都实行这种平等。不仅如此，无产阶级应该实行充分的民族自决权，即给与任何民族的大多数劳动者以完全的可能来决定：这个民族是否愿意和其它民族留在一个国家的统一体内，它是愿意加入紧密自愿的国家联盟（联邦）还是愿意完全分离出来。","language":"中文","translation":false},{"id":"communism-abc-10-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"且慢，有的读者会问，难道共产党人能主张民族分离吗？那全体共产党人所追求的统一的世界性无产阶级国家还怎么搞得成呢？这里似乎有矛盾。","language":"中文","translation":false},{"id":"communism-abc-10-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"我们的回答是，这里没有任何矛盾。正是为了有利于尽快地达到全世界所有无产阶级完全统一，有时才必须同意一个民族与另一个民族的暂时分离。","language":"中文","translation":false},{"id":"communism-abc-10-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"让我们分析一下所有可能遇到的情况。","language":"中文","translation":false},{"id":"communism-abc-10-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"假定在加入统一德国的巴伐利亚宣告成立了苏维埃共和国，可是柏林却仍在由诺斯克和谢德曼的资产阶级专政统治着。在这种情况下，巴伐利亚的共产党人能否要求巴伐利亚的独立呢？不仅是巴伐利亚的共产党人，而且整个德国的共产党人都应该欢迎苏维埃巴伐利亚的分离，因为这种分离将不是与德国无产阶级的分离，而是与执政的德国资产阶级的压迫的分离。","language":"中文","translation":false},{"id":"communism-abc-10-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"现在再作一个相反的假定。整个德国，除了巴伐利亚之外，都宣告成立了苏维埃政权。巴伐利亚的资产阶级主张脱离苏维埃德国，而巴伐利亚的无产阶级则赞成与它联合。共产党人应该怎么办呢？很清楚，德国共产党人应该支持巴伐利亚的工人，并用武力镇压巴伐利亚资产阶级的分离企图。这并不是镇压巴伐利亚，而是镇压巴伐利亚的资产阶级。","language":"中文","translation":false},{"id":"communism-abc-10-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"假定在英国和在爱尔兰，即在压迫者国家和在被压迫者国家都宣告成立了苏维埃政权。又假定爱尔兰工人对英国工人是不信任的，因为许多世纪以来英国曾经压迫过这个国家的工人。假定他们想要完全脱离英国，而且这种脱离在经济上是有害的，在这种情况下英国共产党人应该怎么办呢？他们绝不能象英国资产阶级所做的那样，用强制手段把爱尔兰留在联盟内，他们应该为之提供充分的脱离的可能。为什么呢？","language":"中文","translation":false},{"id":"communism-abc-10-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"首先，这是为了能永远向爱尔兰工人证明，过去不是他们，而是他们的资产阶级压迫过爱尔兰，并以此来争得对自己的信任。","language":"中文","translation":false},{"id":"communism-abc-10-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"其次是为了使爱尔兰工人在实际中相信，他们作为一个小国而独立存在并无好处。为了使他们在实际中相信，只有同无产阶级的英国及其他无产阶级国家在国家和在经济上结成一个紧密的统一体，才能更好地组织生产。","language":"中文","translation":false},{"id":"communism-abc-10-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"再假定，某个处在资本主义制度下的民族希望脱离处在无产阶级制度下的民族，并且这个希望分离的民族的工人阶级大多数，或是相当部分也拥护分离。假定它不仅对资本家不抱信任，而且对曾经压迫它的资产阶级所在的那国家的工人也不信任。在这种情况下，最好也是让这些无产阶级单独和自己的资产阶级呆在一起，这样资产阶级就无法再向无产阶级张口闭口地说：这不是我，而是某个国家在压迫你们。工人阶级将会很快看到，资产阶级争取独立是为了能够独立地宰割本国的无产阶级。无产阶级还将会看到，毗邻苏维埃国家的无产阶级号召它加入联盟不是为了剥削它，也不是为了压迫它，而是为了和它一起从剥削和压迫中解放出来。","language":"中文","translation":false},{"id":"communism-abc-10-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"因此，尽管共产党人反对一个国家的无产阶级脱离另一个国家，特别是在这些国家在经济上有紧密联系的情况下，然而，它可以同意暂时性的分离，就象母亲会让小孩去接触一次火，以便他今后十次不会去随便碰它一样。","language":"中文","translation":false},{"id":"communism-abc-10-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"第五十九节 谁体现了“民族意志”","language":"中文","translation":false},{"id":"communism-abc-10-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"共产党承认民族的自决权直至分离权。但它认为，体现民族意志的是民族的大多数劳动者，而不是民族的资产阶级。因而正确的说法应该是，我们承认的不是民族的自决权，而是民族的大多数劳动者的自决权。至于对资产阶级，我们在内战和无产阶级专政时期不仅剥夺它的全部公民自由，而且也剥夺它在民族问题上的发言权。","language":"中文","translation":false},{"id":"communism-abc-10-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"有些民族处于非常或者最低的发展阶段，对待这样一些民族的自决权或分离权应该如何处理呢？有一些民族不仅没有无产阶级，而且也没有资产阶级，或者只有处于萌芽状态的资产阶级，对待这些民族又该采取什么态度呢？以我们的通古斯人、加尔梅克人、布里亚特人和许多殖民地的民族为例。比如说，如果这些民族要脱离更加文明的民族，或者甚至脱离已经实现了社会主义的民族，那该怎么办呢？这会不会是加强了野蛮而削弱了文明呢？","language":"中文","translation":false},{"id":"communism-abc-10-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"我们认为，如果在世界上一些先进的国家里实现了社会主义，落后与半开化的民族是十分容易自愿地与这些民族结成统一联盟的。对于掠夺殖民地并强迫它依附于自己的帝国主义资产阶级说来，它们害怕失去殖民地是有理由的。而无产阶级并不打算掠夺殖民地，无产阶级可以通过商品交换从这些殖民地获得自己所必需的原料，让土著人和落后民族按他们自己的愿望来安排自己的生活。","language":"中文","translation":false},{"id":"communism-abc-10-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"因此，为了结束各种形式的民族压迫和不平等，共产党提出了民族自决权的要求。","language":"中文","translation":false},{"id":"communism-abc-10-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"各国无产阶级都可以利用这种权利来达到消除民族主义和自愿加入联邦制联盟的目的。","language":"中文","translation":false},{"id":"communism-abc-10-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"等到联邦制联盟对于建立统一的世界经济已显得不足，并且大多数人从实际中也认识到这种不足时，就可以建立起一个统一的世界社会主义共和国。","language":"中文","translation":false},{"id":"communism-abc-10-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"只要我们注意一下资产阶级是如何提出和解决（或者常常是搞乱）民族问题的，我们就发现，对于民族问题，资产阶级在它的青春时期是用一种方法解决的，而在它的晚年和解体时期则又完全是用另一种方法解决的。","language":"中文","translation":false},{"id":"communism-abc-10-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"当资产阶级是被压迫阶级的时候，当以国王或沙皇为首的贵族掌握着政权的时候，当沙皇与国王把整个民族作为自己女儿的陪嫁的时候，资产阶级不仅在民族自由上说过好话，而且也真正试图实现这种自由，至少是自己的民族的自由。例如，当意大利臣服于奥地利君主国时，意大利的资产阶级领导了本国的解放运动，使意大利从异国的压迫下获得了解放，统一成为一个国家。当德国被分裂成为几十个小公国并受到拿破仑的蹂躏时，德国资产阶级从法国奴役者那里夺得了解放，并把德国统一成为一个大国。当推翻了路易十六专制的法国遭到欧洲其余君主制国家的进攻时，法国激进的资产阶级领导了保卫国家的战斗并创作了国歌——《马赛曲》。总而言之，无论在何处，被压迫民族的资产阶级都领导过民族解放斗争，创造了最丰富的民族文化，造就了一批天才横溢的作家、艺术家、诗人、哲学家。当资产阶级还是被压迫阶级时，情况就是这样。","language":"中文","translation":false},{"id":"communism-abc-10-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"为什么被压迫民族的资产阶级渴求解放呢？如果读一读资产阶级的诗人和艺术家的作品，如果说他们所说的话能使人相信，那是因为资产阶级反对任何的民族压迫，因为它主张每一个民族，甚至最小的民族都有自由和自决权。但事实上资产阶级当时是渴求从异国的压迫下获得解放，是想建立自己的资产阶级国家，是想在没有竞争者的情况独自掠夺本国的人民，攫取由本国工农劳动群众所创造的全部剩余价值。","language":"中文","translation":false},{"id":"communism-abc-10-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"任何一个资本主义国家的历史都证明了这一点。当资产阶级和本国人民一起受压迫时，它高喊着所有民族的自由，不容忍任何民族压迫。但是一旦资产阶级取得了政权并赶走了异国占领者，不管这是外国的贵族还是外国的资产阶级，它自己就会来压迫任何一个它可以从中获利的弱小民族。以丹东、罗伯斯比尔以及第一次革命时期其他著名活动家为代表的革命的法国资产阶级，曾号召世界上所有的民族推翻一切暴政，鲁日·德·李尔歌颂革命士兵的马赛曲，对所有被压迫的人民来说是亲切而平易的。但就是这个法国资产阶级（尽管是通过其他阶层）在拿破仑的率领下，甚至是在同一首马赛曲的号召下，镇压了西班牙、意大利、德国、奥地利的人民，并在整个拿破仑战争时期对这些国家的人民进行了掠夺。以席勒和他的“威廉·退尔”为代表的被压迫的德国资产阶级，曾经歌颂了人民反对异国暴政的斗争，然而就是这个以俾斯麦和毛奇为代表的资产阶级，夺去和强行兼并了法国的亚尔萨斯-洛林省，占领丹麦的什列斯维奇，压迫波兹南的波兰人等等。从奥地利贵族的压迫下解放出来的意大利资产阶级开始枪杀特黎波里被征服的贝都因人，亚得亚海沿岸的阿尔巴尼亚人和达尔马戚亚人，以及安纳托利亚的土耳其人。","language":"中文","translation":false},{"id":"communism-abc-10-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"为什么会屡次发生这样的事呢？为什么资产阶级处处都提出民族自由的要求，但是无论如何地却从来不曾付诸实现呢？","language":"中文","translation":false},{"id":"communism-abc-10-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"之所以发生这样的事情，是因为每一个从民族压迫下获得解放的资本主义国家都不可避免地力图进行扩张。任何一个资本主义国家的资产阶级都不满足于仅仅剥削本国的无产阶级，它需要世界各地的原料，因而它力图霸占殖民地，以便既能奴役当地的土著，又能毫无阻碍地把那里的原料拿来供应自己的工厂。它需要商品销售市场，它力图占领这些落后国家的市场，完全不顾及这些国家的人民及青年的、尚未成熟的资产阶级对此抱什么态度。它需要可以输入其剩余资本的国家，从当地的工人榨取利润，它奴役这些国家，在那里就象在自己的国家里一样为所欲为。如果在强占殖民地和对落后国家进行经济奴役的道路上遇到别国强大的资产阶级，问题就得用战争来解决，就象在欧洲仍然处于奴役状态，对它们来说只是换了另一个压迫者。但是，除此之外，在被奴役的国家中又增加了战败的德国、奥地利、保加利亚这些在战前曾是自由的国家。因此，资本主义制度的发展不仅不会减少受别国压迫的国家及其资产阶级的数目，而是恰恰相反，资本主义统治导致全面的民族压迫，全世界都受到在战争中获胜的那部分资本主义国家的统治。","language":"中文","translation":false},{"id":"communism-abc-10-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"第六十节 排犹主义和无产阶级","language":"中文","translation":false},{"id":"communism-abc-10-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"排犹主义，即迫害包括犹太人（还有阿拉伯人）在内的闪族，是属于一种最有害的民族残害形式。沙皇专制政府残害和摧残犹太人，是为了摆脱工农革命。“你穷，是因为犹太人掠夺你”——黑帮分子这样说，并千方百计地把被压迫的工农的不满不是引向反对地主和资产阶级，而是引向反对整个犹太民族。其实，犹太人，就象所有的民族一样，是分成不同阶级的，只有犹太人中的资产阶级才掠夺人民，而且掠夺的方式就和其他民族的资本家一样。而在犹太人居住生活的犹太族工人和手工业者经常都处于极端贫困的状态，甚至比俄国其他地区的工人还要贫困。","language":"中文","translation":false},{"id":"communism-abc-10-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"俄国资产阶级残害犹太人不仅是为了转移本国被剥削的工人的愤怒，而且是为了摆脱在贸易和工业上的竞争者。","language":"中文","translation":false},{"id":"communism-abc-10-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"结果，近年来各国资产阶级的排犹活动日益加强。各国资产阶级不仅是用这种方法与掠夺无产阶级的竞争者进行斗争，而且还在按照尼古拉二世的方法与日益临近的革命进行斗争。不久以前排犹主义在德国、英国和美国还不很流行。而现在，甚至英国的大臣们都在发表排犹主义的言论。这是一个可靠的信号，说明西方的资本主义制度已处于崩溃的前夕。资产阶级力图摆脱工人革命，所以就把路德希尔德和六德尔森们交出来听任革命处置。在俄国，排犹主义在二月革命时期沉寂了一阵，随后，与之相反，资产阶级与无产阶级的国内战争愈是尖锐，资产阶级的企图愈是无望，排犹主义就愈加剧烈。","language":"中文","translation":false},{"id":"communism-abc-10-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"所以这一切都证明，排犹主义是与社会主义作斗争的形式之一。如果工人或农民使自己受到阶级敌人的愚弄，那将是很糟糕的。","language":"中文","translation":false},{"id":"communism-abc-10-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"第七章书目：尼·列宁《论民族自决权》（刊登在《教育》杂志上的文章）。约·斯大林《马克思主义和民族问题》。尤·扎列夫斯基《民族问题与国际》。斯·彼得罗夫《关于犹太人的实情与谎言》。尤·考茨基《论犹太人》，奥·倍倍尔《排犹主义与无产阶级》。尤·斯切克洛夫《排犹主义的最后一言》。","language":"中文","translation":false},{"id":"communism-abc-10-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第七章 民族问题和共产主义","page":10,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/09.htm","text":"[1] 例如，犹太人过去曾有固定的地域和共同的语言，现在已没有地域，古犹太语也不是所有的人都能懂；吉卜赛人有自己的语言，但没有固定的地域。游牧的通古斯人在西伯利亚占有地域，但已忘记了自己的语言。","language":"中文","translation":false},{"id":"communism-abc-11-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-11-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第八章 共产党人在军事问题上的纲领","language":"中文","translation":false},{"id":"communism-abc-11-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十一节 我们在军事问题上的旧纲领","language":"中文","translation":false},{"id":"communism-abc-11-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十二节 红军的必要性及其阶级成分","language":"中文","translation":false},{"id":"communism-abc-11-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十三节 劳动者的普遍军事训练","language":"中文","translation":false},{"id":"communism-abc-11-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十四节 皮鞭下的纪律还是自觉的纪律","language":"中文","translation":false},{"id":"communism-abc-11-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十五节 政治委员和党支部","language":"中文","translation":false},{"id":"communism-abc-11-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十六节 红军的组合","language":"中文","translation":false},{"id":"communism-abc-11-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十七节 红军的指挥人员","language":"中文","translation":false},{"id":"communism-abc-11-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十八节 选举还是任命指挥人员","language":"中文","translation":false},{"id":"communism-abc-11-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"· 第六十九节 红军——暂时的军队","language":"中文","translation":false},{"id":"communism-abc-11-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十一节 我们在军事问题上的旧纲领","language":"中文","translation":false},{"id":"communism-abc-11-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"我们在第十二节中已经谈到资产阶级-地主国家的常备军是如何建成和为谁服务的。十分清楚，全世界的社会党人，其中包括俄国的社会民主党人，都提出了取消常备军的要求。同时，社会党人提出用普遍的人民武装来代替常备军，取消军官阶层，主张指挥人员由士兵自己选举。","language":"中文","translation":false},{"id":"communism-abc-11-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"现在，让我们看看共产党人应该如何来对待这些要求。","language":"中文","translation":false},{"id":"communism-abc-11-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"首先出现的问题是，上述纲领是为哪个社会提出来的——是为资产阶级社会还是为社会主义社会，或者是为争取社会主义而和资产阶级进行暂时的斗争？","language":"中文","translation":false},{"id":"communism-abc-11-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"应该说，参加第二国际的各国社会党本身并不明确它们是为哪个社会而提出自己的纲领的。然而多数认为是为了资产阶级社会。各国社会党人经常引用瑞士共和国的例子，因为那里没有常备军队，只存在着普遍民兵制。","language":"中文","translation":false},{"id":"communism-abc-11-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"问题十分清楚，在资产阶级社会里，特别是在阶级斗争日趋尖锐的时期，上述纲领是不可能实现的。取消兵营——这就意味着取消严格训练工人和农民并把他们变成屠杀自己的阶级兄弟的刽子手的地方。这就意味着取消唯一能把工人、农民训练成军队的地方，这支军队一旦资本家需要，就可以随时被派去同别国人民作战。取消军队阶层，这就意味着取消能够建立铁的纪律，迫使武装的人民服从资产阶级意志的教官。主张对指挥人员实行选举——这就意味着让武装的工农选出他们的自己人，而不是资产阶级的指挥部。这就意味着资产阶级可能制造出一支军队来推翻自己的统治。","language":"中文","translation":false},{"id":"communism-abc-11-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"欧洲资本主义的历史过去和现在都证明，在资本主义制度下，即在社会分为阶级和阶级斗争日益加深的情况下，社会党人所提出的军事纲领也是不可能实现的。这一斗争愈激烈，当权的资产阶级就愈是不主张武装全体人民，而相反，是要解除人民的武装，而把武装只留在可靠的白卫军手中。因此，如果以为在资产阶级统治下社会党人的军事纲领能够得到实现，那就只能是可悲的小资产阶级空想。","language":"中文","translation":false},{"id":"communism-abc-11-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"但是，是不是可以利用这一纲领来推翻资产阶级的统治呢？","language":"中文","translation":false},{"id":"communism-abc-11-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"那也不行。资产阶级为了提防企图剥夺其政权的工人阶级决不会同意把工人阶级武装起来。资产阶级只有在它认为有把握使来自人民的士兵顺从自己时，才会实行普遍的兵役制和把枪发给工人士兵。一旦人民奋起斗争，第一件要做的事便是解除人民的武装。所有老练的资产阶级政治家都明白这一点。相反，如果工人农民本身打算把自己武装起来，打算解除资产阶级的武装并夺取政权，那他们也决不会去要求普遍的全民武装。这就是说，即使在过渡时期，即在无产阶级为夺取政权而斗争的时期，旧的社会党人的军事纲领也是不可取的。它只是在一个非常短暂的时期为了瓦解现存的资产阶级军队=有可用之处。只是在其讲到要取消军官阶层并由士兵自己选举指挥人员那一部分有可用之处。实际上布尔什维克-共产党人在1917年也曾利用过旧纲领的这些要求。他们把将军-军官这根毒刺从沙皇和克伦斯基的军队中拔掉，从而使军队不再服从资本家-地主阶级。","language":"中文","translation":false},{"id":"communism-abc-11-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"相反，对于胜利了的社会主义社会来说，旧的军事纲领是完全适用的。当一系列国家的无产阶级都战胜了资产阶级并消灭了阶级时，那就可以实行普遍的人民武装。那时武装起来的将是所有的劳动人民，因为在胜利了的社会主义社会里，所有的人都将成为劳动者。那时就有可能取消所有各种各样的兵营。那时也就有可能实行指挥部门的选举，但在激烈的内战时期，除了某些偶然事例之外，选举对无产阶级军队是不会有什么好处的。","language":"中文","translation":false},{"id":"communism-abc-11-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"但是这里产生了一个十分自然的问题：在胜利了的社会主义国家里，什么人和为什么需要普遍的人民武装？要知道，国内的资产阶级已经被战胜，并且变成了劳动者，而社会主义国家之间也不会产生战争。这里必须记住一点，即社会主义不可能在全世界所有的国家同时取得胜利。某些国家在消灭阶级和实现社会主义方面会自然落在其他国家后面。已战胜了自己的资产阶级并把资产阶级变成为劳动者的国家需要做的或者是对那些尚未宣布成立无产阶级专政的资产阶级国家进行战争或准备进行战争，或者是对那些虽已宣布成立无产阶级专政，但和资产阶级的斗争尚未进行到底的国家的无产者给予武力上的帮助。","language":"中文","translation":false},{"id":"communism-abc-11-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十二节 红军的必要性及其阶级成分","language":"中文","translation":false},{"id":"communism-abc-11-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"加入第二国际的大多数社会党人认为，社会主义可以用在议会中赢得多数的办法来实现。这些人以这种苟且偷安的小市民的希望来自我陶醉，自然也就不会去考虑在争取社会主义斗争时期建立无产阶级军队的可能性和必要性。另一部分社会党人虽然认为=武装的暴力革命是不可避免的，但是看不到这场武装斗争的长期性，看不到欧洲可能会经历一段不只是社会主义革命，而且是社会主义战争的时期。因此，没有一个社会党人的纲领提出过要求建立红军，即武装的工农军队。俄国的工人阶级在世界上第一次创建了这样的军队[1]，因为是它第一个在世界上牢牢地掌握了国家政权，并抵御了本国资产阶级和全世界各资产阶级国家对这一政权的攻击。十分清楚，没有红军，俄国的工农就保持不住任何一项革命成果，就会被国外的反动势力所镇压。红军不可能建立在普遍兵役制的基础上。胜利了的无产阶级在斗争尚未结束的时期不能把枪杆子交给城市的资产阶级阶层或农村的富农上层分子。只能把不剥削他人劳动、关心工人革命胜利的劳动阶级的代表吸收入伍。只有城市无产者和农村贫农才能组成红军的核心和基础；只有使中农向这些群众靠拢才能使红军在其成分上成为全体劳动者的军队。至于资产阶级和富农，在无产阶级国家中他们只能在后方的后备军中服役。当然，这并不是说牢固的无产阶级在适当的时候不会强迫这些剥削者去射击他们在前线对面的白军伙伴，就象资产阶级通过自己的常备军强迫无产者向自己的阶级兄弟射击一样。","language":"中文","translation":false},{"id":"communism-abc-11-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"尽管资产阶级的常备军是建立在普遍兵役制的基础上的，并且看起来是全民的军队，但在实际上它却是阶级的军队。相反，无产阶级没有必要隐瞒自己军队的阶级性，就象它并不隐瞒自己军队的阶级性一样。红军是苏维埃国家的机构之一。一般说来，它是按照整个无产阶级专政的国家机构的形式建立的。例如，在根据苏维埃宪法的规定进行的苏维埃选举中，剥夺了该宪法应在经济和政治上予以打击的那些人的选举权，同样，也不允许红军在内战中应该予以粉碎的那些人加入红军。","language":"中文","translation":false},{"id":"communism-abc-11-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十三节 劳动者的普遍军事训练","language":"中文","translation":false},{"id":"communism-abc-11-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"俄罗斯苏维埃共和国对劳动者实行普遍军事训练，首先应当把兵营式的训练缩减到最低限度。工人和农民应该尽可能在不脱产的情况下学习军事。这样将大大减少军费开支并防止生产上的减产和破坏。工人和农民一方面可以在业余学习军事，把自己培养成为革命士兵，一方面可以使自己继续成为财富的生产者。","language":"中文","translation":false},{"id":"communism-abc-11-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"对劳动者进行普遍训练的第二个重要任务是，在每个城市和每个乡村都建立起一支无产阶级-农民后备军，以便在敌人逼近时随时都能拿起武器作战。俄国内战的经验证明，这些后备军对于社会主义战争的胜利具有十分重大的意义。例如从白匪手中夺回了红色首都的彼得堡工人后备军，乌拉尔和顿涅茨矿区的工人，奥伦堡、乌拉尔斯克、奥伦堡省的工人和农民就足以说明了这一点。","language":"中文","translation":false},{"id":"communism-abc-11-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十四节 皮鞭下的纪律还是自觉的纪律","language":"中文","translation":false},{"id":"communism-abc-11-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"帝国主义军队就其本质来说不可能有自觉的纪律。这个军队是由各种不同的阶级集团组成的。被强迫赶进资产阶级军营的工人、农民只要一开始认识到自己的利益，他们就一定不会自觉地去服从自己身戴金色肩章的教官的纪律，而是会自觉地去破坏这种纪律。因此资产阶级军队的纪律不可避免地成了棍棒的纪律，因此，鞭笞、各种各样的残酷折磨和集体性的枪决在资产阶级军队中并不是偶然现象，而是各种秩序、纪律和“军事教育”的基础。","language":"中文","translation":false},{"id":"communism-abc-11-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"相反，红军是由工人和农民所组成，是保护工人和农民利益的。在红军中，强制性越来越少，劳动者越来越能自觉地服从内战的纪律。红军的自觉程度愈高，红军和士兵也就愈加懂得，归根结蒂是整个劳动者阶级通过自己的国家及其军事指挥部在指挥他们。由此可见，红军的纪律就是少数人（士兵）服从多数劳动者的利益。每一项明智的决策都不是出自某一个指挥官及其独断专行，不是出自资产阶级少数人及其掠夺意图，而是出自整个工农共和国。因此，在红军中，对士兵进行政治教育，进行宣传鼓动，具有完全特殊的意义。","language":"中文","translation":false},{"id":"communism-abc-11-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十五节 政治委员和党支部","language":"中文","translation":false},{"id":"communism-abc-11-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"在俄罗斯苏维埃共和国，全体劳动者都享有通过苏维埃表达自己意志的权利，工人和农民把共产党员选进执行机构已有两年了。用资产阶级的话来说，共产党是按照群众的意志管理共和国的政党，因为没有任何一个政党能把胜利的工农革命领导到底。结果我们的党变成了某种巨大的无产阶级专政的执行委员会。因此，共产党员在红军中也起着领导的作用。政治委员是军队中体现无产阶级意志的向导，他们是由党和军事中心机关委派的。这一点决定了政治委员同部队的指挥机构和党支部的相互关系。共产党的支部是执政党的一个部分，而政治委员是全党的派出人员。由此产生了政治委员在部队中和在部队党支部中的领导作用。由此产生了他对指挥员的监督权利。他监督指挥人员，就象一个政治领导人监督具体工作的执行者一样。","language":"中文","translation":false},{"id":"communism-abc-11-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"支部的任务是向红军战士说明国内战争的意义以及个人利益服从全体劳动者利益的必要性。支部的任务是以自身的榜样来证明对革命的忠诚，并以此激励部队中的同志。支部每个成员都有监督自己和其他政治委员的共产党员行为，并可以通过更高的党组织或地位更高的政治委员同志采取必要的措施。只有这样，共产党才能在党员红军战士不违反全军纪律的情况下对全体党员进行全面的监督，防止所有党员滥用权利的行为。","language":"中文","translation":false},{"id":"communism-abc-11-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"除了支部和政治委员之外，对红军进行政治教育的还有师、军和方面军政治处以及后方军事委员部宣传鼓动处的一整套系统。俄罗斯无产阶级国家正在通过这些组织为自己的军队建立起一套强大的教育和组织机构，力图用最少的力量获得最大的效果。有了这一套机构，我们军队中的宣传教育工作就不会带有偶然性，而是带有系统性和计划性。读报纸、听大会报告和参加学校学习，正在成为每个红军战士享有的权利。","language":"中文","translation":false},{"id":"communism-abc-11-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"遗憾的是，上述组织没有能避免苏维埃政权中几乎所有大组织的通病：它们染上了官僚主义，它们既脱离群众，又脱离党，在实际上往往变成了懒惰无能的党的军事官员的避难所。必须同这种倾向进行坚决的斗争，这比起同一般苏维埃机构中的官僚主义和懒惰作风进行的斗争，更是当务之急，因为这场斗争的成败在某种程度上决定着我们的国内战争是否能很快取得胜利。","language":"中文","translation":false},{"id":"communism-abc-11-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"普遍训练应该把兵营训练压缩到最低限度，以便在将来完全取消红军的兵营。红军的组合应该逐渐同劳动者的生产组织一致起来，以便消除军队组织上的人为性。简单说来，情况是这样的：沙皇或资产阶级、地主国家的典型常备军是由属于各种不同阶级的人组成的，入伍的人硬性被迫脱离了自己自然的基地：工人脱离了工厂，农民脱离了村庄，职员脱离了企业，商人脱离了柜台。然后这些入伍的人被人为地集合到兵营和被分配到各个部队。对于资产阶级国家来说，割断入伍的无产者和农民同工厂和农村的一切联系是有利的，这样可以更容易地把他们变成压迫劳动者的盲目工具，可以更容易地迫使一个省的工人和农民去开枪射击另一个省的工人和农民。","language":"中文","translation":false},{"id":"communism-abc-11-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"共产党在红军建设上竭力采取完全相反的方法。尽管内战的环境有时使它不得不向旧式的建军方式让步，但在实际上它在尽力采取另一种方式。它力图使新组合起来的部队，比方说，连、营、团、旅，尽可能地和工厂与农村保持一致。换句话说，它力图把人为的军事组织建立在劳动者自然的生活组织的基础上，从而缩小人为的性质。用这样的办法组合起来的无产阶级部队会更加团结，生产方式本身使它们更有纪律性，不必更多地采取自上而下的强制性纪律。","language":"中文","translation":false},{"id":"communism-abc-11-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"建立一支坚强的、有觉悟的无产阶级干部队伍对于红军的建设具有巨大的意义。在象俄国这样一个农民占优势的国家里，无产阶级专政意味着少数无产阶级领导和组织多数农民（中农），使他们跟随着有组织的无产阶级前进，并在政治领导和建设中给他们以充分的信任。红军中的情况也完全如此，红军纪律性高不高，坚强不坚强，就要看红军中无产阶级和共产党骨干的坚强程度如何。收集骨干人材，正确地分配骨干，按适当的比例把他们配备到分散的，但人数要多得多的农民干部中去——这就是共产党在建设常胜的红军事业中的主要组织任务。","language":"中文","translation":false},{"id":"communism-abc-11-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十七节 红军的指挥人员","language":"中文","translation":false},{"id":"communism-abc-11-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"红军是在旧的沙皇的废墟上创建起来的。在十月革命中取得胜利的无产阶级并没有自己的红色的无产阶级军官。为了掌握和运用世界战争的经验来进行国内战争，为了掌握和运用被推翻的制度的军事技术经验来对自己的军队进行军事训练，无产阶级只能从下列三种方法当中选择一种：1、培养自己的红色指挥员，只允许他们担任指挥，让旧军官仅仅起教员的作用；2、将军队的指挥权交给旧军官，由政治委员进行相应的监督；3、两种办法同时采用。时间不等人，国内战争开始了，必须迅速建立并立即投入战斗。因而无产阶级政权只好采取第三种方法。着手建立了红色指挥员学校，这些学校培养的军官多数只能担任低级的指挥职务。与此同时在建设红军和指挥部方面大量起用了旧的军官。","language":"中文","translation":false},{"id":"communism-abc-11-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"起用旧军官带来了一系列极大的困难，这些困难直到现在也没有得到克服。这些军官可以分为三类：少数人多少是同情苏维埃政权的；还有少数人过去和现在都明确地站在无产阶级的阶级敌人一边，并且给敌人以积极的帮助；多数中级军官只要谁的势力大，就跟着谁走，他们为苏维埃政权服务，就象工人为购买劳动力的资本家服务一样。因此，摆在共产党面前的任务就是要充分利用对自己抱有同情态度的少数军官，采取一切非常的镇压措施来制止少数白卫军军官的破坏活动，牢牢地稳住在国内战争中在政治上守中立的中级军官，争取使他们在后方能认真工作和在前线忠实作战。","language":"中文","translation":false},{"id":"communism-abc-11-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"起用旧军官使我们在建设红军的事业中收到了巨大的成效。我们在这里吸取了资产阶级地主制度有益的军事技术知识。但是这种作法是极端危险的，因为这关系到后来指挥人员的大规模叛变和受欺骗与被出卖的红军战士的大量牺牲。","language":"中文","translation":false},{"id":"communism-abc-11-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"因此，共产党的主要任务首先是要加强培养真正的工农军队的指挥员——红色指挥员，在苏维埃政权创建的总部红色学院里加快对共产党员的培训工作。其次，要紧密地指导全体党的政治委员和全体党的军事干部团结起来对所有非党指挥人员进行有效的监督。","language":"中文","translation":false},{"id":"communism-abc-11-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十八节 选举还是任命指挥人员","language":"中文","translation":false},{"id":"communism-abc-11-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"在普遍兵役制基础上建立起来的资产阶级国家的军队，大部分是由工人和农民组成的，而管理军队的则是由出身于贵族和资产阶级的军官。我们在过去的旧纲领中提出要选举指挥人员，是为了要把军队的指挥权从剥削阶级的手中夺过来。这个要求考虑的是，政治权力保留在资产阶级手中，而军队则要实行民主化。当然，这个要求是行不通的，因为世界上任何资产阶级无论何时何地都不会不经过战斗而同意把自己的军事压迫机器交出来。但是对于反对军国主义和反对军官阶层的特权来说，选举指挥人员的要求是有巨大意义的，就同它对摧毁整个帝国主义的军队也有很大的意义一样。","language":"中文","translation":false},{"id":"communism-abc-11-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"相反，红军是属于无产阶级的。无产阶级通过由它自己选举出来的中央苏维埃机构对红军进行管理。无产阶级通过党的政治委员对军队实行层层管理，而无论是在前线还是后方，绝大多数政治委员都是从工人中选拔出来的。在这种情况下关于选举指挥人员的问题只是一个技术性的问题。现在全部问题的实质在于怎样做更有利，如何使得军队在当前的状况下更有战斗力：指挥人员是由下面选举好，还是由上面委派好。既然我们知道，我国红军中农民的人数占优势，红军必须忍受物资缺乏的困苦，由于接连两次战争，部队疲惫不堪，农民战士的自觉程度还很低，那就十分清楚，对指挥人员实行选举的办法只能瓦解我们的部队。当然，这并不排除这样的可能，即在个别志愿的、紧密团结和革命觉悟高的部队中，选举的原则可能不会有害处，因为那里选举出来的人往往就是想要委派的人。一般说来，选举指挥人员，尽管是一种理想，当前在实际上却是危险和有害的。而如果现在加入红军的劳动群众的水平都达到了实行选举已成为有益的和必要的那样的程度，那大概地球上就不会存在任何军队了。","language":"中文","translation":false},{"id":"communism-abc-11-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第六十九节 红军——暂时的军队","language":"中文","translation":false},{"id":"communism-abc-11-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"资产阶级认为，资本主义制度是人类社会的“自然的”制度，它的统治是永久性的，因而它的统治的工具即军队要建立得十分牢固，而且即使不是永恒的，那也要千秋万代地存在下去。无产阶级对自己的红军的看法则不同。红军是劳动者为了与资本家的白军进行斗争而建立的军队。红军产生于国内战争，而当这一战争胜利地结束之后，在消灭了阶级和无产阶级专政自行消亡以后，红军就将消失。资产阶级希望自己的军队是永恒的，因为这种永恒所反映的只是资产阶级制度的不可取代性。相反，工人阶级希望自己的产儿能够自然地和光荣地消亡，因为能够解散红军之日，就是共产主义制度取得彻底胜利之时。","language":"中文","translation":false},{"id":"communism-abc-11-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"共产党应该向自己的红军战士说明，如果红军战胜了资本的白卫军，那他们就是世界上最后一支军队的士兵。但是党也应该向所有参加红军建设的人，向所有成长起来的无产者农民干部说明，无产者成为军人是暂时的和出自于必需，只有生产领域才是他进行劳动的自然领域，绝不能因参加红军而形成某种长期脱离工业和农业的阶层。","language":"中文","translation":false},{"id":"communism-abc-11-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"当红军开始从无产阶级赤卫队建立时，孟什维克和社会革命党人就对共产党人极力进行中伤，说他们背叛了普遍人民武装的口号，说他们是在建立常备的阶级军队。红军不可能是永久的，因为很清楚，国内战争不可能永远延续下去。我们的军队是有阶级性的，这是因为阶级斗争已经达到了极其残酷的程度。只有那些不可救药的小市民空想家才会又承认阶级斗争，又反对阶级的军队。值得注意的是，在世界大战结束之后的时期，资产阶级本身并不认为有可能和有必要隐瞒自己的军队的阶级性。在这方面，德国、英国和法国常备军的命运是极其有教益的。德国立宪会议是通过普遍投票选举出来的。而支持立宪会议的却是诺斯克的志愿白卫军部队。在德国，阶级斗争极其残酷，资本主义社会的解体已经达到非常严重的程度，在这种情况下，建立在普遍兵役制基础上的军队已经不能成为资产阶级德国的支柱了。1919年在法国和英国，政府的支柱已不是通过普遍招募而建立起来并参加过世界大战的军队，而是志愿的白卫军部队，宪兵和警察。因此，不仅是俄国从1917年底开始，而且整个欧洲从1918年底开始，都明显地在取消普遍兵役制而转为采取阶级军队的制度。在这个时候俄国的社会主义叛徒-孟什维克和社会革命党人“反对”建立无产阶级的红军，而他们的西方伙伴诺斯克和谢德曼自己却在组织资产阶级的白军。由此可见，打着普遍人民武装和“民主”的旗号而反对建立无产阶级的阶级军队的斗争实际上是一场主张建立资产阶级的阶级军队的斗争。","language":"中文","translation":false},{"id":"communism-abc-11-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"至于说民兵，世界上所有资产阶级共和国中最民主的国家——瑞士的例子，对于这种民兵在阶级斗争激化时，会起什么变化，是一个很好的说明。瑞士的民兵在国内资产阶级的统治下同样变成了镇压无产阶级的工具，就象次等民主国家的任何一支常备军的情况一样。无论在任何地方，只要那里存在资本的政治和经济统治，“普遍人民武装”的命运莫不如此。","language":"中文","translation":false},{"id":"communism-abc-11-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"共产党主张的不是普遍的人民武装，而是劳动者的普遍武装。只有在除了劳动者而外不再有其他人的社会里，只有在无产阶级的社会里，才有可能存在普遍的人民武装。","language":"中文","translation":false},{"id":"communism-abc-11-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"第八章书目：几乎没有什么现成的文献。可参考托洛茨基在《真理报》和《消息报》上发表的文章，详见波德沃依斯基和巴甫洛维奇编《革命战争文选》。其中有列·托洛茨基《国际形势与红军》，列·托洛茨基《苏维埃政权与国际帝国主义》。格·季诺维也夫《我们的处境与建立红军的任务》，格·季诺维也夫《关于建立红军的演说》。叶·雅罗斯拉夫斯基《新的军队》。","language":"中文","translation":false},{"id":"communism-abc-11-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第八章 共产党人在军事问题上的纲领","page":11,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/10.htm","text":"[1] 我们在这里所谈的是真正的军队。至于说到红军的萌芽，那么1871年巴黎的工人和城市贫民所建立的巴黎公社的军队应该说是它的前身。","language":"中文","translation":false},{"id":"communism-abc-12-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-12-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"· 第 七十 节 资产阶级社会的法院","language":"中文","translation":false},{"id":"communism-abc-12-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"· 第七十一节 由劳动者选举法官","language":"中文","translation":false},{"id":"communism-abc-12-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"· 第七十二节 统一人民法院","language":"中文","translation":false},{"id":"communism-abc-12-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"· 第七十三节 革命法庭","language":"中文","translation":false},{"id":"communism-abc-12-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"· 第七十四节 无产阶级法院的惩罚措施","language":"中文","translation":false},{"id":"communism-abc-12-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"· 第七十五节 无产阶级法院的未来","language":"中文","translation":false},{"id":"communism-abc-12-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"第七十节 资产阶级社会的法院","language":"中文","translation":false},{"id":"communism-abc-12-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"资产阶级法院是资产阶级国家中为压迫和欺骗劳动群众服务的另一类机构。","language":"中文","translation":false},{"id":"communism-abc-12-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"这个令人肃然起敬的机关在判决中所遵循的是为剥削阶级利益而制定的法律。这样一来，无论法院的组成如何，它的决议是早已为一卷卷条款限定好了的，这些条款规定了资产阶级的各种特权和劳动群众的无权地位。","language":"中文","translation":false},{"id":"communism-abc-12-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"至于资产阶级法院的组织本身，它与资产阶级国家形式是完全一致的。有的地方，资产阶级国家不那么公开露骨，而在有的地方则不能不丢掉伪善来争得有利于统治阶级的判决，所以在那里，法官是由上面任命的，即使实行选举，那也只能由社会上享受特权的那一部分人来选举。相反，如果群众已经完全被资本所驯服，完全听命于资本，并把它的法律视为自己的法律，那么在某种程度上就可以允许劳动者本身当法官，就象可以允许他们把自己的剥削者及其奴才选进国会一样。这样就出现了有陪审官参加的法庭，由于有了这种法庭，就可以把有利于资本家的判决冒充为“人民自己的”判决。","language":"中文","translation":false},{"id":"communism-abc-12-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"第七十一节 由劳动者选举法官","language":"中文","translation":false},{"id":"communism-abc-12-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"第二国际社会党人的纲领中提出了由人民选举法官的要求。在无产阶级专政时期，这个要求同普选权或普遍的人民武装的要求一样，是不可能实现的和反动的。如果无产阶级掌握了政权，那就不能允许它的阶级敌人成为自己的法官。它不可能设想资本或大地产的代表会去维护消灭资本统治的法令。另外，许许多多的民事和刑事案件的审理都应根据新的、正在建设着的社会主义社会的精神进行。","language":"中文","translation":false},{"id":"communism-abc-12-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"因此，苏维埃政权不仅取消了全部为资本服务的、冒充民意的旧法院机构，而且建立了毫不掩饰自己的阶级性的新法院。过去剥削者少数阶级通过旧法院来审判劳动人民多数。无产阶级专政的法院则是劳动人民多数审判剥削者少数的法院。它就是这样建立起来的。法官只能由劳动者选举。法官也只能从劳动者当中选举产生。剥削者只有被审判的权利。","language":"中文","translation":false},{"id":"communism-abc-12-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"第七十二节 统一人民法院","language":"中文","translation":false},{"id":"communism-abc-12-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"在资本主义社会里，法院的组织是极其庞杂的。资产阶级律师十分自傲，认为有了一整套的诉讼审级，就可以保证完全公正的判决和把判决的错误减少到最低限度。实际上案件在经过各种诉讼审级审理之后，就会变得对有产阶级更加有利。有钱人可以请到大批律师，有充分的可能在更高一级的诉讼机关得到对自己有利的判决，而那些贫穷的原告人往往由于需要耗费大量的金钱不得不放弃诉讼。所谓案件通过各种诉讼审级的审理可以保证“公正的”判决，这只能说是可以保证判决符合剥削集团的利益。","language":"中文","translation":false},{"id":"communism-abc-12-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"无产阶级国家的统一人民法院把案件从起诉到最后判决所用的时间缩短到最低限度。在审理方面，拖延现象大大减少，如果说还存在，那也只是由于在无产阶级专政的最初年月整个苏维埃机构普遍不够完善的缘故。结果，对于居民中最穷苦落后的阶层来说，法院已不再是高不可攀的了，而且随着国内战争紧张时期的结束，随着共和国公民的相互关系日益稳固，法院会变得更加容易使人接近。罗马人曾经说过：“战争时期法律是保持缄默。”而在国内战争时期，有利于劳动人民的法律并没有保持缄默，人民法院一直都在工作，但是并不是所有的居民都已经了解到新法院的本质和认识到它的全部优点。","language":"中文","translation":false},{"id":"communism-abc-12-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"在摧毁旧社会和建设新社会的时期，人民法院的任务是很重大的。苏维埃的立法工作还跟不上生活的要求。资产阶级-地主制度的法律已被废除；无产阶级国家的法律只是定了一个大的框框，而且永远也不会写全。工人阶级并不想永久维持自己的统治，它不需要去搞那种卷帙浩繁的法律条款。工人阶级通过各种主要法令表达自己的意志，它可以委托劳动者选举出的人民法官在实际中去解释和运用这些法令。只是重要的在于，这些法院作出的判决要反映出同资本主义制度的习俗和心理的彻底决裂，人民法官要根据无产阶级和社会主义的良心，而不是资本主义的良心来处理案件。在摧毁各种旧关系、实现无产阶级权利的过程中，会产生无数的案件，人民法院通过对这些案件的处理，就可以把1917年十月革命所开始的和应深入到苏维埃共和国公民的全部相互关系中去的变革进行到底。另一方面，在审理大量与革命时期的条件无直接联系的居民刑事案件时，人民法院应该表现出革命无产阶级对待这一类罪行所采取的崭新的态度，并在采取的惩治措施上进行一次大的革命。","language":"中文","translation":false},{"id":"communism-abc-12-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"人民法院由选民选举和更换，应由每一个劳动者在其中轮流行使审判员的权利，共产党把这种法院看成是社会主义国家的常规法院。而在国内战争最严峻的时期，除了人民法院以外，还有必要设立革命法庭。革命法庭的任务在于迅速地和无情地惩治无产阶级革命的敌人。这种法庭是镇压剥削者的工具之一。就这一点来说，它如同赤卫队、红军和非常委员会一样，是无产阶级防御和进攻的机构。因此，革命法庭在组织上就不如人民法院民主。它是由苏维埃任命，而不是由劳动群众直接选举产生的。","language":"中文","translation":false},{"id":"communism-abc-12-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"第七十四节 无产阶级法院的惩罚措施","language":"中文","translation":false},{"id":"communism-abc-12-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"在和资本家的浴血奋战中，工人阶级不能拒绝对自己明显的敌人采取最高的惩罚措施。只要国内战争还在继续，就不可能取消死刑。但是如果将无产阶级法院和资产阶级反革命法院作一个纯客观的比较，那就会发现，工人阶级的法官比起资产阶级司法系统的刽子手来是非常温和的。只是在万不得已的情况下才会头判处死刑。在无产阶级专政最初几个月中所处理的一些诉讼案件就足以说明这一点。例如，彼得堡著名的普利什凯维奇当时只被革命法庭判处了两个星期的监禁。社会上新兴的进步阶级对自己的敌人总是宽宏大量，而垂死的阶级则总是心狠手辣，这一点在无产阶级法院的实践中也表现出来。","language":"中文","translation":false},{"id":"communism-abc-12-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"至于说无产阶级法院对不带有反革命性质的罪行所采取的惩罚，那么它和资产阶级法院的惩罚是有根本区别的。这是完全可以理解的。在资产阶级社会里，大部分犯罪都是因为侵犯了所有权，换句话说，都是与所有制联系在一起的。资产阶级国家自然就要对这些罪犯进行报复，所以这个社会所采取的惩罚也就表现为凶狠的所有主的形式的复仇行为。对于一些带有偶然性质的犯罪行为，或对于一些由于资本主义社会整个关系的不完善而产生的犯罪行为（由于家庭、爱情、酗酒、生活堕落、无知、社会本能受压制等等原因而造成的犯罪），在处置上也同样存在着不妥当的情况。无产阶级法院不得不同残存的资产阶级社会的土壤上产生的各种犯罪行为打交道。无产阶级法院不得不从旧制度那里把由这个旧制度培养出来的职业罪犯的骨干接受下来。但是报复对无产阶级法院来说是格格格不入的。它不会因为人们曾经在资产阶级社会里生活过而对人们进行报复。因此，我们的人民法院的判决现在就已经反映出司法制度的彻底革命。越来越经常地采用缓刑的办法：这是一种没有惩罚的惩罚，其主要目的在于防止犯罪行为的重演。运用舆论的谴责，——这种措施只有在无产阶级社会里，在社会自觉性和社会责任感提高的情况下才是有效的。沙皇制度下经常运用不劳动的监禁，这是一种强制性的寄生生活，现在这种现象正在由社会劳动所代替。一般地说，无产阶级法院力图用犯人参加强制性劳动的办法来补偿他们给社会造成的损害。最后，如果有的罪犯一再犯罪，甚至在刑满释放后仍会对其他公民的生命造成危险，法院就可以采取使罪犯与社会隔离的措施，但是仍然给予罪犯以改过自新的充分机会。","language":"中文","translation":false},{"id":"communism-abc-12-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"上面所列举的这些措施，标志着常用惩治办法的一种演进，就连一些优秀的资产阶级法学家多半也都表示赞成。然而，这种措施在资产阶级社会里只能属于幻想。只有胜利了的无产阶级才能将它们付诸实现。","language":"中文","translation":false},{"id":"communism-abc-12-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"第七十五节 无产阶级法院的未来","language":"中文","translation":false},{"id":"communism-abc-12-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"至于说到革命法庭，那么无产阶级法院的这种形式，同战胜了白卫军的红军、同非常委员会、同无产阶级在国内战争时期建立的一切机构一样，是没有任何前途的。随着无产阶级战胜反革命的资产阶级，这些机构就将不再有存在的必要。","language":"中文","translation":false},{"id":"communism-abc-12-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"相反，作为以选举办法产生的人民法院的形式出现的无产阶级法院，在内战结束后仍将继续存在，并将用很长的时间以自己的判决来斩断通过各种各样的形式出现的资产阶级社会的新茎。消灭阶级既不能消灭阶级心理（阶级心理总是比产生它的社会关系要存在得更为长久），也不能立即消灭各种阶级本能和习俗。此外，消灭阶级的过程本身可能时间会拖得非常久。把资产阶级变成劳动者和把农民变成社会主义社会的工作者不是一朝一夕就能实现的。尤其后面这个过程将会相当长，而且会孕育着许多带有司法性质的程序。同样，在完全实行共产主义分配之前，消费资料的私有制也是造成许多过失和犯罪的原因。最后，由个别人的个人主义引起的危害社会的罪行和各种侵犯社会利益的罪行和各种侵犯社会利益的罪行都将长期成为法院审理的对象。的确，那时法院将改变自己的性质；随着国家的消亡，它将逐渐变为表达社会舆论的机构，近似于同志审判会的性质，判决不是依靠强制手段来执行，而仅仅具有道德的意义。","language":"中文","translation":false},{"id":"communism-abc-12-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"第九章书目：共产主义有关资产阶级和无产阶级法院的文献几乎没有。可参考下列一些老的材料：卡·马克思《〈新莱茵报〉审判案：马克思的发言》。恩格斯《家庭、私有制和国家的起源》。拉萨尔《辩护词》，《工人阶层的思想》，《工人纲领》以及全集中的其他文章。恩格斯《反杜林论》中有关国家的部分。卡·考茨基《政治罪行的性质》。万-康《犯罪现象的经济因素》；格尔涅特《犯罪现象的社会因素》。","language":"中文","translation":false},{"id":"communism-abc-12-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第九章 无产阶级法院","page":12,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/11.htm","text":"现代的材料有：彼·斯图契卡《俄罗斯苏维埃联邦社会主义共和国宪法问答》，《人民法院》等。阿·哥伊赫巴尔格《人民需要什么样的法院》。彼得格勒苏维埃出版的有关法院的法令。","language":"中文","translation":false},{"id":"communism-abc-13-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-13-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第七十六节 资产阶级社会的学校","language":"中文","translation":false},{"id":"communism-abc-13-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第七十七节 共产主义的破坏任务","language":"中文","translation":false},{"id":"communism-abc-13-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第七十八节 学校——共产主义培养教育的工具","language":"中文","translation":false},{"id":"communism-abc-13-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第七十九节 学龄前的教育","language":"中文","translation":false},{"id":"communism-abc-13-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第 八十 节 统一劳动学校","language":"中文","translation":false},{"id":"communism-abc-13-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十一节 专业教育","language":"中文","translation":false},{"id":"communism-abc-13-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十二节 高等学校","language":"中文","translation":false},{"id":"communism-abc-13-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十三节 苏维埃学校和党校","language":"中文","translation":false},{"id":"communism-abc-13-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十四节 校外教育","language":"中文","translation":false},{"id":"communism-abc-13-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十五节 新的教育工作者","language":"中文","translation":false},{"id":"communism-abc-13-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十六节 劳动者的艺术科学宝藏","language":"中文","translation":false},{"id":"communism-abc-13-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十七节 国家的共产主义宣传","language":"中文","translation":false},{"id":"communism-abc-13-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"· 第八十八节 沙皇时期和苏维埃政权时期的人民教育","language":"中文","translation":false},{"id":"communism-abc-13-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第七十六节 资产阶级社会的学校","language":"中文","translation":false},{"id":"communism-abc-13-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在资产阶级社会里，学校执行着三个主要任务：1、用忠于和敬仰资本主义的精神来培养年青一代的劳动者。2、从统治阶级的青年中为劳动者培养“有教养的”教练人员。3、为资本主义生产服务，利用科学来发展技术和增加资本主义的利润。","language":"中文","translation":false},{"id":"communism-abc-13-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"为了完成第一任务，在学校同在资产阶级军队里一样，首先要建立一批相应的“国民教育军官”。资产阶级学校用来教育人民的教师，要接受一定的训练，要把自己培养成教练员式的人物。在学校里担任教学的只能是那些从资产阶级观点看来是可靠的教师。资产阶级教育部门监视着这一切，并且无情地把一切有害的分子，即社会主义分子驱逐出教师队伍。革命前的德国国民学校作为威廉皇帝兵营的一种补充提供了一个鲜明的范例，它证明地主和资产阶级能够成功地通过学校造就出资本的忠实的和盲目的奴隶。在资产阶级的初级学校里，教学是根据一定的、完全为资产阶级训练学生的目的服务的教学大纲进行的。所有的教科书也都是根据相应的精神编写的。甚至所有资产阶级的书籍也是为这一目的服务的，这些书籍的作者把资本主义制度看成是天然的、永恒的和一切制度中的最好的制度。这样一来，学生便不自觉地渗透了资产阶级的心理，也会跟着赞美各种各样的资产阶级道德：追名逐利，投机钻营，只顾个人的幸福等等。资产阶级教师通过自己对教规的讲授起了神职人员的作用，由于资本与教会是紧密联系在一起的，所以这些教规始终都是有产阶级的法规。[1]","language":"中文","translation":false},{"id":"communism-abc-13-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"资产阶级社会为了达到第二个目的，故意阻挠劳动者阶级接受中等和高等教育。中等教育。特别是高等教育的学习费用昂贵，劳动者是花不起的。","language":"中文","translation":false},{"id":"communism-abc-13-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"这种学习时间长达十几年，因而工人和农民是上不起学的。为了养家糊口，他们不得不让自己的孩子从小就到工厂或地里干活，或者是从事家务劳动。中等和高等学校实际上变成了资产阶级青年的学校。在这里统治阶级的青年受到培养，以便接替他们的父辈的剥削者的岗位或资产阶级国家官吏与技术人员的岗位。在这些学校里，教学带有严格的阶级性。如果说在数学、技术和自然科学方面，由于这些学科本身实质原因。这一点还不那么明显的话，那么在决定学生世界观的社会科学方面，这一点表现得却是十分清楚的。讲授资产阶级政治经济学是和讲授最完善的“击溃马克思”的方法同时进行的。社会学和历史学也是按纯资产阶级精神讲授的。法学史把资产阶级的权利说成是“人和公民”的自然权利，等等，等等。结果，高等和中等学校向资产阶级子弟讲授的一切就业是为了为资产阶级社会服务和维护整个资产阶级剥削制度所必须的东西。即使某些最有才华的劳动者子女进了高等学校，那资产阶级的学校机构也多半能成功地使他们脱离自己出身的阶级，使他们养成资产阶级的心理，最后利用劳动者的才华来压迫同一些劳动者。","language":"中文","translation":false},{"id":"communism-abc-13-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"至于第三个任务，资产阶级学校是用下列办法实现的。在阶级社会里，科学与劳动相脱离。科学不仅为有产阶级所享用，更有甚者，它成了一定的，范围很小的一部分人的职业。无论是科学教学还是科学研究都与劳动过程相脱离。为了把科学成果应用于生产，资本主义社会不得不建立一系列研究所来促进科学发明在技术上的应用，并建立一系列技术学校来使生产能够与“纯”科学，即脱离劳动的科学的成就保持同样的水平。与此同时，综合技术学校不仅为资本主义社会培养了精通技术的人材，而且还培养了对工人阶级进行监督和管理的人员。此外，为了加速商品流转过程，建立了各种各样的商业学校，商学院等。在所有这些组织中，一切与生产有关的东西都将保留，一切与资本主义生产有关的东西都应废除，一切促进科学技术发展的东西都将保留，科学与劳动分离的现象将被废止，技术知识的讲授将保留，脱离体力劳动而孤立地讲授技术知识的方法则应废止，在生产中应用科学的做法应该保留和扩大，在这种利用上设置的阻碍应该排除，因为资本利用科学是以科学在当时能为资本增加多少利润为前提的。","language":"中文","translation":false},{"id":"communism-abc-13-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第七十七节 共产主义的破坏任务","language":"中文","translation":false},{"id":"communism-abc-13-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"共产党在学校事务中，同在一切领域一样，不仅面临着建设任务，而且首先面临着破坏任务。应该立即把资产阶级社会学校系统中那些使学校变成资产阶级的阶级统治工具的东西破坏掉。","language":"中文","translation":false},{"id":"communism-abc-13-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在资产阶级社会里，高等学校是剥削阶级的财产，象那些漫漫无期的古典中学、实科学校、专科学校、中等武备学校等，都应该予以取消。","language":"中文","translation":false},{"id":"communism-abc-13-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"资产阶级学校的全体教学人员是为资产阶级的教育和欺骗事业服务的。应该毫不留情地把旧学校那些不能或不愿成为群众共产主义教育工具的教师驱逐出无产阶级学校。","language":"中文","translation":false},{"id":"communism-abc-13-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在旧学校中使用的是按资产阶级精神编写的教材，采取的是为资产阶级的阶级目的服务的教学方法。所有这一切在新学校中都应予以抛弃。","language":"中文","translation":false},{"id":"communism-abc-13-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"旧学校与宗教联系在一起，硬性规定讲授宗教课，必须作祈祷和去教学礼拜。新学校必须把宗教从学校里驱逐出去，不允许宗教以任何方式钻进校门，不允许某些落后家长以任何温和的形式把宗教引起学校。","language":"中文","translation":false},{"id":"communism-abc-13-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"旧高等学校建立起一个排他性的教授集团，即阻碍新的教学力量进入到大学里的学术行会；资产阶级教授的学术行会必须解散，大学讲坛应该成为一切有教学才能的人的场地。","language":"中文","translation":false},{"id":"communism-abc-13-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在沙皇制度下，用本族语言教学是犯禁的。俄语是法定的国家和学校语言。新学校要消除教育领域里的一切民族压迫影响，使得所有民族都能用本族语言进行教学。","language":"中文","translation":false},{"id":"communism-abc-13-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第七十八节 学校——共产主义培养教育的工具","language":"中文","translation":false},{"id":"communism-abc-13-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"资产阶级是全体居民的极少数。但是这并不妨碍它在利用其他阶级压迫机构的同时，也利用学校来按照自己的精神培养和训练千百万劳动者，以便将极少数人的观念和道德强加给居民的大多数。在资本主义国家，无产阶级和半无产阶级构成居民的大多数。在俄国，工人阶级在数量上占少数，而在政治上则是全体劳动者的斗争的领导者和组织者。因此很自然，工人阶级在把学校掌握到手中以后，首先就应该利用学校把劳动居民中其他阶层的共产主义觉悟提高到应有的高度。资产阶级利用学校对劳动者进行奴化教育。无产阶级则要利用学校清除奴化教育的影响，消灭劳动者思想中的一切精神奴役的残余。资产阶级依靠学校用资产阶级的精神的来培养无产阶级的子弟。新的、共产主义学校的任务在于用无产阶级的精神来教育资产阶级和小资产阶级出身的子弟。同在经济领域里苏维埃政权对生产工具实行国有化一样，在人们的精神和心理上，共产主义学校也应对资本主义社会进行同样的破坏和剥夺。必须增进人们对新的社会关系的认识。如果群众在精神生活的许多领域中两条腿继续站在资本主义社会及其偏见一边，那他们就很难去建设共产主义社会。新学校的任务在于使成年人的意识能跟上已经变了的社会关系，而更重要的在于培养年青一代，使他们自己的整个心理都立足于新的、共产主义社会。","language":"中文","translation":false},{"id":"communism-abc-13-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"下述有关学校工作的各种改革都是为这一目的服务的，这些改革有的已在实行，有的正在准备实行。","language":"中文","translation":false},{"id":"communism-abc-13-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第七十九节 学龄前的教育","language":"中文","translation":false},{"id":"communism-abc-13-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在资产阶级社会里，儿童即使不是完全地，至少也是在很大程度上被认为是自己父母的财产。当父母说到“我的女儿，我的儿子”时，这里不仅意味着存在血统关系，而且还意味着父母有教育自己子女的权利。从社会主义观点来看，这种权利是没有任何根据的。每一个并不属于他自己，而是属于社会——人类。只有由于社会的存在，个人才能够生存和发展。因此，儿童属于他赖以出生的社会，而不仅仅属于他自己的父母的那个“社会”。教育儿童的最首要的和根本的权利应属于社会。从这个观点来看，父母通过家庭教育以自己的局限性来影响儿童心里的要求，不仅应当予以拒绝，而且应当受到最无情的嘲笑。社会可以委托父母来教育孩子，但也可不委托，而且愈往后，委托父母教育儿女的理由就愈少，因为能教育儿童年的人比起能生育儿女的人毕竟是少数，在一百个母亲当中，可能只有一两个人有资格担任保育员。未来是属于社会教育的，社会教育是使社会主义社会有可能以最少的人力和财力来培养年青的一代。","language":"中文","translation":false},{"id":"communism-abc-13-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"但是，所以需要对儿童进行社会教育，不仅仅是出自单纯的教育学上的考虑，它还有着巨大的经济利益。实现社会教育，可以使千百万母亲腾出手来参加生产和提高自己的文化水平；她们将从使人变得目光短浅的家务劳动者和数不清的有关儿童家庭教育的琐事中解放出来。所以说苏维埃政权力求建立一系列机构来改善社会教育，逐步使它更普及。属于这类机构的幼儿园，忙于工作的工人和职员可以把自己的孩子送到那里去，把孩子托付给学龄前教育的专家们。托儿所，它和幼儿园一样，只是孩子们在那儿呆的时间更长，儿童保育院，在那里生活和受教育的儿童有的是永久脱离父母的，有的是在很长时期内脱离父母的。还有托儿站，这类机构专门抚育四岁以前的儿童，当父母上班时，孩子就可以送到那里照看。","language":"中文","translation":false},{"id":"communism-abc-13-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"共产党的任务在于，一方面，通过苏维埃的机关更快地发展学龄前儿童教育机构和改善这些机构的工作，另一方面，在父母中加强宣传工作，消除所谓家庭教育必不可少和有优越性的资产阶级和小市民的偏见，并通过苏维埃政权的优秀教育机构的范例来加强这一宣传。有时恰恰是因为保育院、托儿所和幼儿园等等机构办得不够令人满意而影响父母把自己的子女送到那里去。共产党的任务，特别是党的妇女工作部门的任务，在于号召父母们都来改进社会教育工作，其办法不是拒绝，而是争取把自己的孩子送到相应的机构里去，并由父母所在的组织对这些机构实行最广泛的监督。","language":"中文","translation":false},{"id":"communism-abc-13-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"学龄前的教育机构是为七岁以下的儿童设立的。下一步的培养和教育就应该是由学校来管。教育应该是义务性的，这和沙皇时期相比是一个很大的进步。教育应该是免费的，这更是一大进步，甚至那些最先进的资产阶级国家里的情况也比不了这一点，在那里，只有初级小学教育才是免费的。教育对所有的人都自然应当是平等的，这就取消了任何一部分居民在受教育方面所享受的特权。这种对所有人都是普遍平等的和对所有人都是义务的教育应该普及到从八岁至十七岁的所有青少年。","language":"中文","translation":false},{"id":"communism-abc-13-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"学校应该是统一的。这意味着，首先应该取消男女分校的现象，应当让男孩和女孩共同在一起受教育。这意味着，应该取消把学校分为互不联系，在教学大纲上相互脱节的初级、中级和高级学校的作法。这意味着，不应再把初级、中级和高级学校又为普通教育学校、专业学校或职业学校，分为普及学校和阶级-阶层学校。统一学校意味着一个统一的阶梯，社会主义共和国的每一个学生都能够而且必须通过这个阶梯，即从最低层——幼儿园起，到最高一层，即到所有的学生都必须接受的那一级的各种普通学校教育和各种综合技术教育止。","language":"中文","translation":false},{"id":"communism-abc-13-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"正如每一位读者所看到的那样，统一学校不仅是每个进步教育家的理想，而且是社会主义社会，即无产阶级的或力图变为无阶级的社会的唯一可能的学校模式。尽管资本主义社会的教育家也曾提出过这类学校的设想，但是统一学校只有社会主义才能实现。","language":"中文","translation":false},{"id":"communism-abc-13-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"社会主义共和国的学校应该是劳动的学校。这意味着，教育应该与劳动相结合，并且应该依靠劳动。这一点很重要，其中原因很多。首先是为了教学本身的效果。儿童最容易、最渴望和切实掌握到的知识不是从书本上或是从教师的讲授中得来的，而是用自己的双手从实践中得来的。只要立志于改造自然，就能比较容易地认识周围的自然界。教育与劳动相结合早在进步的资产阶级学校里就已有过。但是在资本主义制度下，它是不可能进行到底的，因为资本主义制度在有意识地培养社会寄生分子，使体力劳动和脑力劳动隔着一条不可逾越的鸿沟。","language":"中文","translation":false},{"id":"communism-abc-13-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"其次，劳动是出自儿童的纯体力发展及其各种才能的全面发展的需要。实践已经验证，在学校中花费在劳动上的时间，不但不会减少，而且相反，会增加儿童在掌握各种知识方面的成绩。","language":"中文","translation":false},{"id":"communism-abc-13-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"最后，对于共产主义社会来说，劳动学校是真正必要的。这个社会的每一个公民至少应该在大体上对每一种职业都有所了解。这个社会不会有任何排他性的行会、因循守旧的职业和在专业上不求进取的团体。甚至最有才能的学者同时也应该是一个心灵手巧的体力劳动者。共产主义社会对每个统一劳动学校的毕业生来说：“你可以不成为教授，但你必须成为价值的生产者”。儿童从在公园里作儿童游戏开始，应该转向劳动，无形中把这种劳动变成游戏的继续，这样，从一开始他就习惯地把劳动不是看成不愉快的必须或惩罚，而是看成能力的自然的、情不自禁的表现。劳动应该是一种需要，如同想要吃饭和喝水一样，这种需要应该在共产主义的学校中养成并得到发展。在共产主义社会里，随着这个社会的技术突飞猛进的发展，将不可避免地出现劳动力大规模地和迅速地从一些生产部门调到另一些生产部门的现象。例如，纺织工业中一旦出现某项发明，就可能需要减少纺织工人的数量，而增加种植棉花的工人等等。在这种情况下，在各职业之间就不免要进行劳动力的再分配，而这只有在共产主义社会的工作者不仅熟悉一种职业，而且熟悉一系列职业的条件下才能实现。资产阶级社会只能靠使用产业后备军，即靠使用经常性的失业者的办法来解决这个问题。共产主义社会没有失业军；任何一个感到劳动力不足的工业部门的后备力量在于其他部门的工作者有能力来补充这种不足。只有统一劳动学校才能培养出能够完成共产主义社会中各种职能的工作干部。","language":"中文","translation":false},{"id":"communism-abc-13-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"共和国的所有青少年在十七岁以前都必须进统一劳动学校学习，并在那里获得共产主义社会每一个公民所必需具备的理论和实践知识。但是教育不能到此为止。除了一般知识以外，还必须具备专业知识。","language":"中文","translation":false},{"id":"communism-abc-13-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"每一门必要的科学所包含的内容是很丰富的，以致每个人都绝不可能把所有的东西都掌握。统一劳动学校完全不排除专业教育。它只是把这种教育放在更高的阶段去进行。在统一劳动学校的第二阶段，即从学生十四岁到十七岁时，必然会发现学生们侧重于某些课程的倾向。就在这个阶段，在不妨碍劳动学校统一的教学大纲的条件下，不仅可以，而且必需根据学生的天资引导学生更踏实地去熟悉各种不同的科学。","language":"中文","translation":false},{"id":"communism-abc-13-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"但是真正的专业教育应该在十七岁以后开始。从另一种原因上来说，这个年龄也是一个界限。在十七岁以前，劳动学校的青年在更大程度上是一个学生，而不是工作者。在学校劳动的主要任务不是创造价值和增加国家的收入，而主要是受教育。在十七岁以后，学生就要变成一个工作者了。他应该把自己的那一份劳动，他制成的那份产品供献给人类的公社。他只有在首先完成他对社会的基本义务的前提下，才能够接受专业教育。因此，十七岁以上的青年通常只能在业余时间学习专业知识。随着技术的发展，工作日应该减少到八小时以下，这样一来，共产主义社会的每个成员便能有足够的时间来接受专业教育。在某些情况下，对于有特殊才干的人来说也可以有些例外，如果认为有社会必要，就可以让这些人暂时脱离几年劳动，或把他们的工作日比一般法定工作日缩短一些，以便让他们接受教育或从事科学研究。","language":"中文","translation":false},{"id":"communism-abc-13-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"现在还难以完全预见到共产主义制度下的高等专业学校具有什么样的性质。也许它们会多种多样，从长期或短期的训练班到综合技术学校和实验学校。在这里，教学与科学研究将同时进行，教授与大学生之间不再有任何界限。但是现在可以完全肯定地说，现在的大学及其现在的教授的职称是一种过时的设制。它们仍在继续教育那些读完了资产阶级旧式中学的青年。现在可以对这些大学进行改造，由另一些人来更新教授的组成，这些人可能够不上“资产阶级社会的博士”的资格，但是他们能成功地在社会科学教学方面进行彻底的革命，铲除资产阶级科学的最后一个避难所。可以改变学员的组成，使工人在大学的课堂里占优势，从而使自然科学和技术科学成为工人阶级的财产。吸收工人参加学习自然就会提出工人在学习期间由国家负担其生活费用的问题。有关这一切，在党纲关于国民教育的第三条中已有说明。","language":"中文","translation":false},{"id":"communism-abc-13-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第八十三节 苏维埃学校和党校","language":"中文","translation":false},{"id":"communism-abc-13-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"共产党掌握了政权以后，摧毁了沙皇的学校机构，这些机构即使在克伦斯基政府时期也几乎是神圣不可侵犯的。共产党在旧的阶级学校的废墟上开始建立统一劳动学校这一未来共产主义社会的正规劳动学校的萌芽。它力图把资产阶级高等学校里一切帮助资本统治的东西连根拔掉，把有产阶级统治时期所积累的知识变成全体劳动者的财产，以便着手建设共产主义社会的正规的高等学校。","language":"中文","translation":false},{"id":"communism-abc-13-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"但是，在资产阶级文化所拥有的全部科学中，没有哪一门科学是教导人们如何进行无产阶级革命的。在资产阶级建立的学校和现在人们开始为未来的共产主义社会建立的学校中，也没有哪一个学校是教育人们如何建设无产阶级的国家的。在从资本主义到共产主义的过渡时期，出现了一种特殊的学校，这种学校将为当前的革命和苏维埃机关建设服务。党-苏维埃学校就是为此目的服务的，这种学校在我们眼前是以一种短期的和十分偶然的训练班的形式出现的，它已经变成并且仍在继续变成培养党和苏维埃工作者的一种正常的设制。这是不可避免的。建设苏维埃国家是全新的、史无前例的事业。苏维埃机构的工作日益发展与完善，每一个苏维埃的工作者为了有成效地进行工作，必须了解前人已经获得的经验。党是通过全体工人参加苏维埃这种自学的办法来学习管理国家是不够的。必须把这方面的经验予以收集、整理和研究，使它成为参加苏维埃建设的所有工人的财产，以便使参加管理国家的每一批新的工人不再重复前人的错误，使他们能够不是从自己的错误中，而是从别人已经犯过的，国家已为之付出过代价的错误中学习。苏维埃工作学校应为此目的服务，它也正在这样做，因为我们共和国的全俄执行委员会已经有了中央苏维埃工作学校这样的常设学校。毫无疑问，在每个省城里很快也将建立起相应的学校。","language":"中文","translation":false},{"id":"communism-abc-13-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"至于说到共产主义的党校，它们在向共产主义实际过渡的时期正在从根本上改变自己的性质。它们将从依靠无产阶级的党的学校，从纯粹的政治学校变成社会共产主义改造学校，即变成国家学校。同时它们也正在变成国内战争的军事学院。只是由于有了这类学校，无产阶级才能够理解他们半自发、半不自觉地实行这场变革的意义和客观任务，因为过去他们眼前所见到的只是狭窄的具体任务，没有可能去观察整个改造的全部过程。党校不仅能够向无产阶级科学地阐明无产阶级革命的性质和最终目的，而且能够教会他们用最短的时期，以最小的代价，将这一革命进行到底。","language":"中文","translation":false},{"id":"communism-abc-13-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"沙皇制度有意识地使俄国大多数劳动人民处于无知和文盲的状况。苏维埃政权从专制制度那里接受下来的是人数众多的文盲，因此自然就要采取各种最果敢的措施来改变这种情况。为此，国民教育部门为成人中的文盲开办学校，并采取了一系列其他扫盲措施。但是，除了利用教育人民委员部的学校机构之外，共产党还应采取一切措施使群众都能参加到扫盲工作中来，由与教育工作有关的劳动群众选举产生的各级人民教育委员会必须为这一目的服务。为了这一目的，还要动员所有不识字的人。在共和国的许多地方都开始了这一动员，党组织应争取使这一工作在所有的地方按照一定的计划开展起来。","language":"中文","translation":false},{"id":"communism-abc-13-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"除了进行扫盲斗争之外，苏维埃政权还必须耗费大量的人力物力去帮助主要是成年人的自我教育。为止目的就要组织图书馆网，以满足劳动读者的需求，并在有一切可能的地建立人民文化馆、俱乐部和人民大学。电影院过去被用来作为腐蚀人民和使老板发财致富的工具，现在则逐渐地、尽管还不是那么很快地变成用社会主义精神宣传教育群众的工具。由于缩短了工作日，全体劳动人民都有可能进各种各样的学习班学习或参加对所有人开放的、免费的讲座。在将来，为了教育的目的，将有计划地组织劳动者通过休假期间的旅游活动来了解自己的国家和世界其他国家，这一点将有巨大的意义。将来，这种旅游活动对于加强各国劳动者的交往将起巨大的作用。","language":"中文","translation":false},{"id":"communism-abc-13-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第八十五节 新的教育工作者","language":"中文","translation":false},{"id":"communism-abc-13-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"苏维埃政权在学校改革上比起在其他领域里的改革或建设上取得了更大的成就。这不仅仅是因为苏维埃国家在人民教育方面所花费的预算比起最先进的资本主义国家要多得多。实现统一劳动学校的思想在很大程度上已由资产阶级社会的先进教师作了准备。俄国的部分优秀教师在苏维埃制度下正在部分地实现他们从纯教育学观点出发认为是本来必须实现的东西。在从资产阶级-地主制度投向苏维埃政权的学校工作者当中，有不少这样的人，他们过去和现在一般都是无产阶级革命的反对者，但是他们却是无产阶级在学校事业中进行的革命的拥护者。","language":"中文","translation":false},{"id":"communism-abc-13-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"然而，这种有利的情况一点也不会降低无产阶级国家对真正共产主义学校工作者的需求。在教师中，象在所有专家中的情况一样，只有微不足道的少数党员。共产主义的反对者却要多得多。而数量最多的是那些官气十足的工作者，他们准备为任何制度服务，肯于遵循任何纲领，但是他们更倾向于他们的父亲和爷爷遵循的纲领。因此，共产党面临着两项任务：一方面，把教师中的所有优秀分子动员起来，通过加强他们中间的工作，把他们培养成共产主义的工作干部；另一方面，从青年中培养完全新型的教育工作干部，让他们一开始就受到共产主义精神，其中包括受到共产主义学校纲领的精神的教育。","language":"中文","translation":false},{"id":"communism-abc-13-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第八十六节 劳动者的艺术科学宝藏","language":"中文","translation":false},{"id":"communism-abc-13-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在资本主义制度下，才能被视为其直接所有者的财产和发财致富的工具。在这个社会里，才能创造的成果是一种商品，可以按这种或那种价格出售，谁出的价钱高，它就归谁所有。具有巨大社会意义的、在本质上是一种集体创造的天才作品，可以被俄国的某个科鲁帕夫或是美国的摩根买去，他们有同样的权利或者把它加以篡改，或者予以毁掉。如果有那么一天著名的莫斯科商人特列奇亚科夫想起要烧掉自己的画廊，而不是把它交给莫斯科市，那么，根据资产阶级社会的法律，对他是不能追究社会责任的。由于艺术作品、珍本书和历史手稿等，可以自由买卖，结果这些东西绝大部分都不能为社会广大阶层所享用，而是成了剥削者阶层所专有的东西。","language":"中文","translation":false},{"id":"communism-abc-13-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"苏维埃共和国宣布所有艺术品、收藏品等，均属于社会的财产，并且要消除一切影响社会享用这些东西的障碍。为此，发布了旨在没收私有的大书库的命令，这样一来，这些书库也就成为社会的财产。","language":"中文","translation":false},{"id":"communism-abc-13-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"共产党还应该争取使国家政权在这方面采取更多的步骤。在书籍极端缺乏、出版和再版工作又不可能很快大量开展的情况下，必须进一步地限制这一方面的私有权，必须把各种书籍集中到公共图书馆、学校等地方去。","language":"中文","translation":false},{"id":"communism-abc-13-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"此外，为了有利于教育，为了使广大群众都能到剧院去观看演出，对所有剧院实行了国有化，从而间接地使戏剧、音乐和声乐艺术领域里的才能也实现了社会主义化。","language":"中文","translation":false},{"id":"communism-abc-13-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"这样一来，从前在剥削劳动群众的基础上用劳动群众的血汗和通过劳动群众创造的一切科学和艺术作品，现在又重新回到了其真正所有者的手中。","language":"中文","translation":false},{"id":"communism-abc-13-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第八十七节 国家的共产主义宣传","language":"中文","translation":false},{"id":"communism-abc-13-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在推翻了资本主义制度，并在其废墟上开始建立新的共产主义社会的时候，共产主义思想的宣传不能只是属于共产党的事情，不能仅仅依靠党的那一点有限的人力和物力。共产主义宣传对于整个正在改造的社会是必不可少的，它应该加速这个必然的过程，它应该向往往是不自觉地建设新事物的人们揭示他们所努力从事的工作的意义。因此，不仅无产阶级学校，而且整个 无产阶级国家机构都应该为共产主义的宣传事业服务。在军队里军事政治组织应该进行这种宣传，整个苏维埃机构也应该进行这种宣传。","language":"中文","translation":false},{"id":"communism-abc-13-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"国家出版社是国家宣传共产主义最有力的工具。全部纸张和印刷厂的国有化，使无产阶级国家有可能在纸张严重不足的情况下印刷出成百万份群众当时所急需的出版物。结果，国家出版社出版的全部印刷品不仅价格便宜，群众能买得起，而且逐渐有一些书籍、小册子、报纸和宣传画可以完全免费地提供给群众。国家的共产主义宣传正在最终变成消除过去时期毒化劳动者的资产阶级宣传的影响的手段，变成为社会主义社会的工作者建立新思想、新风尚和新世界观的强有力的工具。","language":"中文","translation":false},{"id":"communism-abc-13-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"第八十八节 沙皇时期和苏维埃政权时期的人民教育","language":"中文","translation":false},{"id":"communism-abc-13-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"国家用于人民教育的经费开支情况：","language":"中文","translation":false},{"id":"communism-abc-13-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"1891年22 810 260卢布 1911年27 833 000卢布 1916年195 624 000卢布 1917年339 834 678卢布 1918年2914 802 124卢布 1919年（上半年）3888 000 000卢布","language":"中文","translation":false},{"id":"communism-abc-13-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"由此可见，无产阶级掌握政权以后，用于人民教育经费很快就增加了将近八倍。","language":"中文","translation":false},{"id":"communism-abc-13-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"到1917年9月1日为止，全国（二十六个省）有三万八千三百八十七所初级学校。","language":"中文","translation":false},{"id":"communism-abc-13-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"1917——1918学年，共有五万二千二百七十四所初等学校，有四百一十三万八千九百八十二名学生。","language":"中文","translation":false},{"id":"communism-abc-13-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"1918——1919学年，将近有六万二千二百三十八所初等学校。","language":"中文","translation":false},{"id":"communism-abc-13-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"1917——1919学年，中等学校有一千八百三十所，而1918——1919年已发展到三千七百八十三所。","language":"中文","translation":false},{"id":"communism-abc-13-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在沙皇时期根本没有学龄前教育。苏维埃政权不得不从零开始组织这项工作。尽管不利的条件很多，到1919年10月1日，在三十一个省已建立起二千六百一十五所幼儿园、儿童游艺场和保育院，其中有十五万五千四百四十三名儿童。百分之二点五的三至五岁的儿童得到了照料。但在城市中得到照料的儿童已达到百分之十点一，而且这个数字还在不断增长。","language":"中文","translation":false},{"id":"communism-abc-13-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"关于劳动学校问题的书目：《俄罗斯苏维埃联邦社会主义共和国统一劳动学校章程》（1918年全俄中央执行委员会版）。《统一劳动学校——维·马·波兹涅尔的报告》（1919年全俄中央执行委员会版）。《劳动学校》，莫斯科工人代表苏维埃国民教育局公报。勃隆斯基《学校与工人阶级》，勃隆斯基《劳动与学校》，第一与第二部分。列维金《劳动学校》，列维金《社会教育学的国际问题》（泽伊杰尔，格·克尔申什捷伊涅尔等等）。克鲁普斯卡娅《人民教育和民主》。久伊《学校与社会》。沙列尔曼《劳动学校》，《在人民教师的实验室里》。加涅别尔格《教育学》，《学校中创造性工作》。《教育人民委员会部周刊》。《人民教育》（起初是作为全俄中央执行委员会《消息报》副刊出版的，从第十八期起开始独立发行，最后发行到五十一至五十二期，周刊中刊登了一系列有关劳动学校的文章）。《第一届全俄教育代表大会记录》（1919年教育人民委员部代表大会版）。","language":"中文","translation":false},{"id":"communism-abc-13-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"在非共产主义文献中可参考：","language":"中文","translation":false},{"id":"communism-abc-13-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"克尔申什捷伊涅尔《劳动学校的概念》，《劳动学校》（1918年莫斯科大家庭出版社第四版）。古尔利特《普及统一学校的问题》（国家出版社）。费利耶尔《在新学校里》（哥尔布诺夫-彼萨多夫出版社版）。维捷卡姆普《独立性与创造性》（哥尔布诺夫-彼萨多夫出版社版）。舒勒茨《社会民主党的学校改革》（国家出版社版）费多罗夫-哈特维希《劳动学校和集体主义》（1918年莫斯科人民教师出版社版）。扬茹尔《欧洲学校中的劳动创举》。（1918年莫斯科人民教师出版社版）。沙茨基《朝气蓬勃的生活》。明赫《未来学校》。","language":"中文","translation":false},{"id":"communism-abc-13-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十章 学校与共产主义","page":13,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/12.htm","text":"[1] 在俄国沙皇制度下，为了使人们顺从贵族国家的统治，与其说是对人民群众进行资产阶级—教会—沙皇“教育”，不如说是不允许进行任何教育。在这方面大名鼎鼎的黑暗主义者波别多诺斯采夫的“理论”是人们所熟悉的，他认为人民的愚昧是专制制度的重要支柱。","language":"中文","translation":false},{"id":"communism-abc-14-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-14-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"第十一章 宗教与共产主义","language":"中文","translation":false},{"id":"communism-abc-14-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"· 第八十九节 为什么宗教与共产主义是不相容的","language":"中文","translation":false},{"id":"communism-abc-14-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"· 第 九十 节 教会与国家分立","language":"中文","translation":false},{"id":"communism-abc-14-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"· 第九十一节 学校与教会分立","language":"中文","translation":false},{"id":"communism-abc-14-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"· 第九十二节 与群众的宗教偏见作斗争","language":"中文","translation":false},{"id":"communism-abc-14-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"第八十九节 为什么宗教与共产主义是不相容的","language":"中文","translation":false},{"id":"communism-abc-14-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"卡尔·马克思说过：“宗教是麻醉人民的鸦片。”共产党的任务就在于使这个真理为最广大的劳动群众所理解。党的任务就是要使所有的劳动群众，包括最落后的群众在内，坚信这一真理，即认识到宗教过去和现在，都始终是压迫者手中维护不平等现象、剥削和奴役劳动者的最强有力的工具之一。","language":"中文","translation":false},{"id":"communism-abc-14-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"某些觉悟不高的共产党员认为：“宗教并不妨碍我作一个共产党员，——我信仰上帝，同样也信仰共产主义。我对上帝的信仰并不妨碍我为无产阶级革命事业而奋斗。”","language":"中文","translation":false},{"id":"communism-abc-14-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"这种想法是完全错误的。宗教与共产主义无论在理论上还是在实践上都是不相容的。","language":"中文","translation":false},{"id":"communism-abc-14-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"每个共产党员都应该把各种社会现象（人与人之间的关系、革命、战争，等等）看作是一种根据一定的规律发展起来的现象。正是由于有了我们的伟大导师马克思和恩格斯建立的历史唯物主义理论，科学共产主义才能对社会发展的规律作出最为完整的阐明。根据这一理论，社会发展是不受任何超自然力影响的。不仅如此，同一理论还阐明，关于神和阴间力量的观念是在人类历史的一定阶段出现的，并将在一定阶段开始消失，因为它是一种幼稚的、在人的生活及其同自然界的斗争实践中得不到证明的观念。正是由于让人民处于愚昧和迷信奇异现象对掠夺阶级是有利的（解释这些奇异现象的钥匙就在人们自己的口袋里），所以宗教偏见才会如此长期地存在，甚至使一些非常聪明的人也大惑不解。","language":"中文","translation":false},{"id":"communism-abc-14-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"超自然力对整个自然界的变化不产生任何影响。人在同自然界的斗争中取得的成就，利用自然为自己造福，并且能对自然界的力量加以控制，这并不是由于信仰神和得到了神的帮助，而是由于他无视这种信仰，由于他在实践中，在所有严肃的事业上都始终是一个无神论者。科学共产主义是依靠自然科学的材料来理解自然界各种现象的，而这些材料同各种宗教的臆想是格格不入的。","language":"中文","translation":false},{"id":"communism-abc-14-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"共产主义与宗教信仰在实践上也是不相容的。共产党员的策略为自己的成员规定了一定的行动方式。而每一种宗教道德也为自己的信徒规定了一定的品行（例如，基督教的道德告诫人们：“如果有人打了你的右脸，那你就把你的左脸也伸给他”）。共产党的策略指示同宗教戒律之间多半有着不可调和的矛盾。抛弃了宗教戒律和按照党的指示行动的共产党员不再是信教者。自称共产党员的信教者，如果为了遵守宗教的戒律而违反党的指示，就不再是共产党员。","language":"中文","translation":false},{"id":"communism-abc-14-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"同宗教的斗争包括两个方面，每个共产党员应该对这两个方面严格加以区分：首先是与教会的斗争，教会是进行宗教宣传的特殊组织，让人民处于愚昧无知和笃信宗教的状态是出自教会本身的物质利益的需要。第二个方面是同大部分劳动群众中广泛传播的和根深蒂固的宗教偏见的斗争。","language":"中文","translation":false},{"id":"communism-abc-14-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"第 九十 节 教会与国家分立","language":"中文","translation":false},{"id":"communism-abc-14-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"根据基督教的教义，教会是由同一种信仰和圣礼等等联系起来的信教者组成的团体。在共产党人看来，教会是靠搜括信教者，靠保持信教者的愚昧无知而得到一定收入的人们结成的团体。这个团体与地主、资本家等等另一些剥削者的团体联系在一起，即与他们的国家联系在一起，它帮助国家压迫劳动者，同时也从国家那里得到帮助和支持。教会与国家的联系由来已久。教会与封建地主阶级国家的联系尤为密切。这是可以理解的，因为专制贵族国家依靠的是大土地所有制，而教会本身就是握有几百万俄亩土地的大地主。这两种势力不可避免地要联合起来共同对付劳动群众，并且结成联盟来加强自己对劳动群众的统治。在城市资产阶级同贵族进行斗争的时期，资产阶级一度猛烈地攻击过教会，因为教会是土地的占有者，资产阶级很想把这些土地攫为己有；因为教会是从劳动者身上搜括而来的收入的所有者和使用者，资产阶级对这些收入也同样垂涎三尺。这一斗争在一些国家曾经表现得十分尖锐（法国），而在另一些国家则表现得比较温和（英国、德国、俄国）。因此教会与国家分立的要求（这实际上意味着把国家用在教会的钱转交给资产阶级）早已由自由资产阶级和资产阶级民主派提出过。但是资产阶级在任何地方也未实现过这个要求。原因是工人阶级同资本家的斗争普遍开始加剧，抛弃这个多余的同盟者对资产阶级来说是不利的。资产阶级认为最好还是同教会讲和，把教会的祷告词买来准备同社会主义作斗争，利用教会对落后群众的影响来使这些群众继续保持对剥削者国家的逆来顺受的感情（“王权神授”）。","language":"中文","translation":false},{"id":"communism-abc-14-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"资产阶级在与教会的斗争中没有做到的事，由无产阶级国家做到了。苏维埃政权在俄国颁布的第一批法令之一就是教会与国家分立的法令。教会的全部土地均被没收，并转交给了劳动者，教会的全部资本都变成了劳动人民的财产。教会从沙皇制度那里得到的和在“社会主义者”克伦斯基政府时期继续顺利得到的一切收入都被没收。宗教被宣布为每个公民个人的事情。同时苏维埃政权反对以任何形式利用教会来巩固无产阶级统治的意图。","language":"中文","translation":false},{"id":"communism-abc-14-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"第九十一节 学校与教会分立","language":"中文","translation":false},{"id":"communism-abc-14-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"宗教宣传与学校教育合一是僧侣们用来加强教会的统治及其对群众的影响的第二个强有力的工具。人类的未来及其青年的命运被掌握在神父们的手中。在沙皇制度下，保持宗教狂热，保持愚昧和无知，被视为至关重要的国家大事。教规成为学校里最重要的课程。即使在学校里，专制制度和教会也是互相支持的。在学校中除了必须讲授宗教课程和必须做礼拜之外，教会还有更大的收获。它已开始把整个人民教育都抓到自己手中，因此，整个俄国到处都是教会学校。","language":"中文","translation":false},{"id":"communism-abc-14-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"由于学校和教会合为一体，青年们从很小的时候起就为宗教迷信所控制，根本不可能形成某种完整的世界观。对于同一个问题（例如关于地球起源的问题），宗教和科学给予的回答各有不同，于是学生们敏锐的头脑便变成了准确的知识和黑暗主义者的愚蠢思想进行搏斗的战场。","language":"中文","translation":false},{"id":"communism-abc-14-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"在许多国家里，教育青年不仅要忠于现存的制度，而且往往还要忠于已被推翻的专制-教会-贵族制度，例如在法国就是如此。甚至从资产阶级国家的观点来看这种宣传也是一种反革命的宣传。","language":"中文","translation":false},{"id":"communism-abc-14-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"资产阶级自由派在自己的纲领中也提出过学校与教会分立的要求。他们曾经进行斗争，要求在学校里用资产阶级道德课来代替宗教课，并关闭由教会和寺院开办的学校。但无论在何处这种斗争都未能进行到底。法国便是一个例子。二十年的时期里，法国历届资产阶级内阁都曾庄严地许诺说要解散所有的牧师协会（天主教的团体），没收它们的资本，禁止它们在学校的教学活动，但是最后每次都是以与天主教和解和妥协而告终。不久以前克列孟梭就曾提供过一个与教会的明显例子，此人一度曾是教会不共戴天的敌人，可是后来却号召忘掉敌意，并亲自为天主教的代表人物的爱国主义颁发了勋章。无论在剥削其他国家的斗争中（同德国的战争），还是在反对本国工人阶级的斗争中，资产阶级国家和教会是相互勾结，相互支持的。","language":"中文","translation":false},{"id":"communism-abc-14-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"资产阶级与教会的这种和解并不仅仅表现为资产阶级把自己旨在反对宗教的旧的战斗口号束之高阁和停止同宗教的斗争。不仅如此。资产阶级本身也愈来愈变成为一个“信教的阶级”。现代欧洲资产者的曾祖辈都是无神论者和自由思想者，都是教士和僧侣的死敌。到了祖辈和父辈就倒退了一步。尽管他们本身仍然是无神论者，不相信宗教的那一套，甚至把它当着笑料，但是他们认为有必要把这一套保持下来，不要解除人民的宗教牢笼。最后，他们现在的儿子辈不仅认为宗教的牢笼对于人民是必要的，而且连他们自己也堕入了这一牢笼。我们亲眼见到在十月革命之后，原先的自由资产阶级和资产阶级知识分子巨浪般地涌进了教堂，向他们早先讽刺嘲笑的那些东西顶礼膜拜。所有垂死阶级的命运都是如此，他们已走投无路，只有到宗教里去寻找“安慰”。","language":"中文","translation":false},{"id":"communism-abc-14-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"在欧洲尚未失去政权的资产阶级中间可以看到这种笃信宗教的倾向。但是，如果资产阶级开始信仰上帝和相信天国永生，那只是意味着，在地球上它们的死期已经来临了。","language":"中文","translation":false},{"id":"communism-abc-14-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"学校与教会分立在过去和现在都要引起工人和农民中的落后分子的反对。许多家长继续坚持要求学校把宗教课作为一种非必修课向自愿者开放。共产党坚决反对这类倒退的企图，允许在学校开设宣扬宗教黑暗势力的课程，哪怕是作为一种非必修课，那就意味着国家支持加强宗教偏见。那时教会就会直接出面支配现成的儿童课堂（把这些儿童集中到学校里来的目的恰恰是和宗教的任务对立的），支配属于国家的场所，这样一来，它就能继续在青年中散布宗教毒素，其范围之广，几乎和在学校与教会分立之前一样。","language":"中文","translation":false},{"id":"communism-abc-14-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"必须大力执行关于学校与教会分立的指令，无产阶级的国家不应对中世纪的落后势力作任何让步。在这个领域中已经作到的事情还太少，一些落后的父母仍然完全有可能用宗教邪说来摧残自己子女的心灵。苏维埃政权允许成年人的信仰自由。但是这种信仰自由在有些父母那里却变成了他们用过去教会毒害他们鸦片来毒害他们自己的子女的心灵的自由，父母们把自身的愚昧无知硬塞给自己的子女，把各种奇谈怪论当作真理，严重地妨碍了统一劳动学校的工作。把儿童从他们父母影响下解放出来是无产阶级国家的一个重要任务。根本的办法是对儿童实行充分的社会教育。但是在最近时期，我们不能仅限于把宗教宣传从学校里驱赶出去，我们还必须使学校主动地向家庭里的宗教宣传进攻，要加强儿童思想上的免疫力，使他们不受一些成年人仍然相信并当作真事加以宣传的宗教神话的影响。","language":"中文","translation":false},{"id":"communism-abc-14-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"第九十二节 与群众的宗教偏见作斗争","language":"中文","translation":false},{"id":"communism-abc-14-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"如果说无产阶级政权在实行教会与国家分立的和学校与教会分立的上工作进行得还比较容易和几乎没有造成什么病痛，那么同群众思想中根深蒂固的具有巨大生命力的宗教偏见作斗争，则是一件比较困难的事情。这场斗争是长期的，它需要巨大的毅力与耐心。我们的党纲就这个问题指出：“俄国共产党所遵循的信念是：只有在群众的所有社会经济活动中实现了计划性和自觉性，才能随之完全消除宗教偏见。”这些话是什么意思呢？","language":"中文","translation":false},{"id":"communism-abc-14-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"如果让整个社会生活环境促使群众的意识去超自然地解释周围的自然和社会现象，那就会使宗教宣传、信奉上帝和各种超自然力找到最为适宜的土壤。资本主义生产方式的环境恰恰对这一点很有利。在资本主义社会里，产品的生产和交换不是自觉的、按一定计划进行，而是自发进行的。市场主宰着生产者。谁也不知道生产的商品是过剩还是太少。生产者弄不清楚整个庞大而复杂的资本主义生产机构是如何运行的；为什么会忽然出现危机和失业；为什么商品的价格会时而上涨，时而下跌，等等。既然对社会上发生的这些现象的真正原因得不到解释，普通的工人就只求助于无所不知的“神的意志”。","language":"中文","translation":false},{"id":"communism-abc-14-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"相反，在有组织的共产主义社会里，生产和分配对于劳动者来说是没有任何秘密的。每个工作者不仅完成托付给他的那一部分社会劳动，而且他自己也参加制订总的生产计划，至少他完全了解这个计划。在整个社会生产的机构中没有任何秘密的、不可理解和意想不到的东西，因此各种迷信邪说也就根本没有立足之地。一个木匠制造了一张桌子，他完全清楚这张桌子是怎么出现的，他用不着到天上去寻找桌子的创造者，同样，共产主义社会的全体劳动者对于他们用集体的努力创造了什么和怎样创造的，心里是一清二楚的。","language":"中文","translation":false},{"id":"communism-abc-14-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"因此，建立和巩固社会主义制度的事实本身给宗教带来了致命的打击。而从社会主义过渡到共产主义，即从彻底击溃了资本主义的社会过渡到没有任何阶级划分和阶级斗争痕迹的社会，将导致一切宗教和一切迷信的自然死亡。","language":"中文","translation":false},{"id":"communism-abc-14-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"但是这决不意味着，在预言了宗教在将来要灭亡之后，我们就可以高枕无忧了。","language":"中文","translation":false},{"id":"communism-abc-14-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"现在特别应该大力加强对宗教偏见的严肃斗争，因为现在教会已经起着反革命组织的作用，它在竭力利用自己在群众中的宗教影响来引导群众对无产阶级专政进行政治斗争。受到教士庇护的东正教正在与君主制度结成联盟。因此，苏维埃政权现在就必须开展最广泛的反宗教宣传。为此可以举行专题讲座，组织辩论会，出版相应的文献，开展科学知识的普及活动。这些措施尽管很缓慢，不会短期凑效，但是一定会消除宗教的一切影响。不久以前在共和国的许多地方揭露了所谓“不朽的”干尸之迷，这是与教会进行斗争的一个很好的工具，它使整个宗教，特别是俄国东正教赖以生存的全部卑劣欺骗伎俩在包括信教者在内的广大群众面前得到了充分的暴露。","language":"中文","translation":false},{"id":"communism-abc-14-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"但是在与群众的宗教落后思想进行的斗争中，态度不仅应该坚决有力，而且应该小心谨慎。信教的群众对于一切侮辱自己感情的事是非常敏感的，因此不能强迫群众接受无神论，不能对于宗教仪式和崇拜对象采取粗暴和嘲弄的作法，否则不仅不能加速，而且会阻挠与宗教的斗争。被逼得无路可走的教会就会在群众中得到更大的同情，使群众又联想起他们早已遗忘了的宗教与保卫民族自由的联系，使排犹活动加强，使已经半死的意识形态的各种残余又活跃起来。","language":"中文","translation":false},{"id":"communism-abc-14-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"现在我们引用一些数字来说明沙皇政府用人民的金钱支持教会，人民本身把自己仅有的一点钱拿出来支持教会和神职人员积累财富的情况。","language":"中文","translation":false},{"id":"communism-abc-14-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"沙皇政府平均每年通过宗教院或其他途径提供给教会的拨款达五千万卢布（每一卢布相当于现在的一百卢布）。宗教院在银行里有七千万卢布存款，教堂和寺院有巨大的地产。1905年教堂有一百八十七万二千俄亩土地，寺院有七十四万俄亩土地。六个最富有的寺院有十八万二千俄亩土地。索洛维茨寺院有六万六千俄亩土地，萨罗夫寺院有两万六千俄亩土地，亚历山大涅瓦寺院有两万五千俄亩土地，等等。1903年彼得堡各教会和寺院在房产、店铺和地皮等等方面共有二百六十六笔收入。在莫斯科，房产收入有一千零五十四笔，还不包括三十二所旅馆的收入。在基辅，教会有一百一十四所房屋。还有总主教和大主教的布道收入。彼得堡总教主每年收入三十万卢布，莫斯科和基辅总主教各收入十万卢布，诺夫哥罗德的大主教收入三十一万卢布。","language":"中文","translation":false},{"id":"communism-abc-14-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"教会学校共计三万所，其中的学生达一百万人。在教育部各初级学校里有两万多名神学课教师在“工作”。","language":"中文","translation":false},{"id":"communism-abc-14-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"众所周知，沙皇专制制度把东正教教会当作占统治地位的唯一真正的教会加以支持。东正教从伊斯兰教徒（鞑靼人、巴什基尔人）、天主教徒（波兰人）、犹太人那里以赋税的形式搜括了数千万卢布，并用这些钱来证明除了东正教之外的一切其他宗教的虚伪性。在沙皇制度下，宗教压迫达到了最野蛮的程度。按宗教划分，俄国居民每一百人中有九名天主教徒，十一名伊斯兰教徒，五名基督教徒，四名犹太教徒和一名其他教徒。","language":"中文","translation":false},{"id":"communism-abc-14-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"至于东正教本身的队伍，它在1909年达到了如下的规模：","language":"中文","translation":false},{"id":"communism-abc-14-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"在俄国五万二千八百六十九所教堂里共计有：","language":"中文","translation":false},{"id":"communism-abc-14-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"在四百五十五所男修道院里有：","language":"中文","translation":false},{"id":"communism-abc-14-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"修道士 9987人 见习修道士 9582人","language":"中文","translation":false},{"id":"communism-abc-14-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"在四百一十八所女修道院里有：","language":"中文","translation":false},{"id":"communism-abc-14-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"修道士 14008人 见习修道士 46811人","language":"中文","translation":false},{"id":"communism-abc-14-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"在俄国结婚和不结婚的僧侣共有一十八万八千二百一十八人。","language":"中文","translation":false},{"id":"communism-abc-14-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"这仅仅是有关东正教的数字。信仰其他宗教的各个民族都有这样的寄生阶层。这些人本来可以通过体力劳动创造出大量财富，可是相反，他们却是在用维持人民愚昧落后来从他们身上获得大量的金钱。社会主义国家随着自己的经济机构的完善，要为僧侣及其他非劳动阶级安排劳动义务，把他们变为工人或农民。","language":"中文","translation":false},{"id":"communism-abc-14-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"在沙皇时期，国家拨给教会的经费每年有一千二百多万卢布是给城乡僧侣的（这就不难理解，为什么神父们反对教会与国家分立，因为这等于几千万卢布同他们的口袋分了家）。但是这还不仅仅是僧侣收入的一部分；圣礼收入、地租、教会资本的利息比上面那些收入要多得多。在俄国，谁也说不准僧侣们收入的确切数字。大约年收入为一亿五千万卢布，而那时每一卢布相当于现在的一百倍。直至现在，僧侣们有很大一部分收入仍然是从人民那里得来的。","language":"中文","translation":false},{"id":"communism-abc-14-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十一章 宗教与共产主义","page":14,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/13.htm","text":"第十一章书目：基利切夫斯基《僧侣们的财富和收入》。卢金（伊·安东诺夫）《教会与国家》。美尔古诺夫《过渡时期的教会与国家》。谢·米宁《宗教与共产主义》。伊·斯切潘诺夫《我们的上帝的起源》，《僧侣，他们的收入，他们的祈祷和诅咒》。亨·库诺夫《宗教和信仰上帝的起源》。卡·考茨基《最早的圣经故事来源》，《古代社会、犹太教和基督教》，《天主教教会和社会民主党》。奥·倍倍尔《基督教和社会主义》。施坦普费尔和王德威尔得《社会民主党和宗教》。拉法格《宗教信仰的起源》。斯·达尼洛夫《黑色的军队》。基尔维尔《社会民主党和基督教》。尼·布哈林《苏维埃共和国的教会与学校》。雅·布罗夫《信仰自由的法律意味着什么》。拉法格《关于无垢受胎的神话》。尼科尔斯基《耶稣和第一批基督村社》。维波尔《基督教的起源》。波克罗夫斯基《俄国历史》（尼科尔斯基的论文）。杰·别德内依《神父》。","language":"中文","translation":false},{"id":"communism-abc-15-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-15-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第九十三节 对资产阶级的剥夺和大工业的无产阶级国有化","language":"中文","translation":false},{"id":"communism-abc-15-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第九十四节 我们的目的是发展生产力","language":"中文","translation":false},{"id":"communism-abc-15-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第九十五节 有计划地组织经济","language":"中文","translation":false},{"id":"communism-abc-15-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第九十六节 扩大与其它国家的经济合作","language":"中文","translation":false},{"id":"communism-abc-15-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第九十七节 小工业和手工业组织","language":"中文","translation":false},{"id":"communism-abc-15-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第九十八节 工业组织与工会","language":"中文","translation":false},{"id":"communism-abc-15-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第九十九节 劳动力的利用","language":"中文","translation":false},{"id":"communism-abc-15-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第 一百 节 同志式的劳动纪律","language":"中文","translation":false},{"id":"communism-abc-15-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第一百零一节 利用资产阶级专家","language":"中文","translation":false},{"id":"communism-abc-15-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"· 第一百零二节 生产与科学的结合","language":"中文","translation":false},{"id":"communism-abc-15-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第九十三节 对资产阶级的剥夺","language":"中文","translation":false},{"id":"communism-abc-15-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"和大工业的无产阶级国有化","language":"中文","translation":false},{"id":"communism-abc-15-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"无产阶级和作为无产阶级专政机构的苏维埃政权的首要任务是，剥夺资产阶级的生产资料，或者如通常所说，剥夺资产阶级。不言而喻，这里所指的不是剥夺小生产，也不是剥夺手工业，而是剥夺大资产阶级的生产资料，把大生产纳入新的轨道，即按照新的方式去组织它。苏维埃政权能够以什么样的形式作到这一点呢？在第一部分里我们已经谈到，无产阶级所需要的不是把工厂分光和抢光，而是组织协作化的社会生产。显然，在无产阶级专政时期，要做到这一点，只能通过一种办法；只能用无产阶级国有化的办法，即把所有生产资料和流通数据转交给无产阶级国家这个工人阶级最大的组织的手里。","language":"中文","translation":false},{"id":"communism-abc-15-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"绝不能把资产阶级统治下的生产国有化和无产阶级统治下的生产国有化混为一谈。国有化意味着收归国有。但是，谁若只谈国家，而不问这个国家是哪能一个阶级的国家，那就意味着他对问题的实质一窍不通。当统治阶级的是资产阶级时，当这个资产阶级对自己的托拉斯和辛迪加实行国有化时，根本不会发生任何剥夺资产阶级的事情。资产阶级在这里只不过是把自己的财产从自己的一个口袋转移到另一个口袋而已。资产阶级把一切交给了自己当家作主的国家。资产阶级照旧是工人阶级的剥削者，工人阶级也照旧不是为自己，而是为自己的阶级敌人干活。这种国有化是资产阶级的国有化。它产生了我们在本书第一部分中说过的那种制度，即国家资本主义。在无产阶级统治下实行的国有化则完全是另一回事。那时工厂、交通工具等等都转到无产阶级政权手中，即转到不是老板的，而是工人的组织手中。所以，这里确实是在对资产阶级实行剥夺：资产阶级确实是在失去自己的财富、统治、势力和权力的基础。与此同时，剥削的基础也被消灭。无产阶级国家不能剥削无产阶级，因为这个国家是无产阶级自己的组织。一个人不能骑在自己背上走路。同样，无产阶级也不能自己剥削自己。在国家资本主义条件下，私人企业主不再单独存在，而是联合起来掠夺群众，这对于资产阶级说来一无所失。在实现了无产阶级国有化以后，工人不再是自己工厂的独立的主人，所有的工厂都属于整个的工人阶级，属于最大的工人组织即所说的苏维埃国家，这对于每个工厂的工人说来，也同样一无所失。","language":"中文","translation":false},{"id":"communism-abc-15-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"十月革命之后立即开始进行的对资产阶级的剥夺，已大体基本结束。在苏维埃俄国境内，全部运输业（铁路和水路运输）和将近百分之八十至九十的大工业已实现国有化。根据最高国民经济委员会工厂统计局的材料，到1919年9月，在三十个省内，已有三千三百三十个企业实现了国有化，这些企业有一百零一万二千名工人和两万七千名职员。这个数字统计得有些偏低，另有材料说已有大约四千个企业实现了国有化。在上述三千三百三十个企业中，一些最大的企业已经开工。下列材料就可以说明这一点。到1919年9月，已开工的企业为一千三百七十五个，其中的一千二百五十八个企业共拥有七十八万二千名工人和两万六千名职员。尽管工业的处境极端困难，一百万名工人中大约有八十万名工人在工作。关闭的企业为六百九十一个，共有十七万名工人，有一千二百四十八个企业还情况不明，这些企业共有五万七千名工人（这里所谈的都是比较小的企业）。","language":"中文","translation":false},{"id":"communism-abc-15-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"到1919年秋，各国有化企业由下列中央管理机构（“总局”和“中心”）归口领导：","language":"中文","translation":false},{"id":"communism-abc-15-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"一、 采掘工业（上面是矿业委员会）：","language":"中文","translation":false},{"id":"communism-abc-15-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1、 煤矿总局（煤炭工业总管理局）。","language":"中文","translation":false},{"id":"communism-abc-15-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"二、 金属工业（上面是最高国民经济委员会金属局）：","language":"中文","translation":false},{"id":"communism-abc-15-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1、 国家机器制造总局。","language":"中文","translation":false},{"id":"communism-abc-15-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"7、 卡卢什-梁赞总厂。","language":"中文","translation":false},{"id":"communism-abc-15-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"三、 电机工业（国营电机联合企业）。","language":"中文","translation":false},{"id":"communism-abc-15-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"四、 纺织工业（纺织总局）。","language":"中文","translation":false},{"id":"communism-abc-15-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"五、 化学工业（上面是最高国民经济委员会化学局）：","language":"中文","translation":false},{"id":"communism-abc-15-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"9、 石棉混凝土板中心。","language":"中文","translation":false},{"id":"communism-abc-15-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"六、 食品加工（最高国民经济委员会食品加工局）：","language":"中文","translation":false},{"id":"communism-abc-15-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"七、 木制品和木材采伐工业（林业总局）。","language":"中文","translation":false},{"id":"communism-abc-15-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"八、 印刷业（最高经济委员会印刷局）。","language":"中文","translation":false},{"id":"communism-abc-15-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"九、 “汽车组件中心”（汽车装配与修理）。","language":"中文","translation":false},{"id":"communism-abc-15-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"十、 “被服中心”（小型成衣店等等）。","language":"中文","translation":false},{"id":"communism-abc-15-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"十一、 废物利用等等（废物利用中心）。","language":"中文","translation":false},{"id":"communism-abc-15-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"十二、 水路运输（水运总局）。","language":"中文","translation":false},{"id":"communism-abc-15-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"十三、 建筑业及其它工程建筑（国家建筑工程委员会）。","language":"中文","translation":false},{"id":"communism-abc-15-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"十四、 军需采购（军需采购局——军需采购中心）。","language":"中文","translation":false},{"id":"communism-abc-15-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"十五、 物资搬运和贮藏（最高国民经济委员会物资运输局）。","language":"中文","translation":false},{"id":"communism-abc-15-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"剥夺资产阶级的工作基本完成，应该把这一工作进行到底。这是我们党应该完成的第一项任务。这里应该记住，我们不剥夺小私有者的财产。绝不允许对它实行国有化。第一，因为我们无法组织分散的小生产；第二，因为共产党不想也不应该欺压几百万小业主。他们走向社会主义应该根据他们的自愿，由他们自己决定，而不能靠采用武力剥夺的办法。在有小生产的地方特别应该记住这一点。","language":"中文","translation":false},{"id":"communism-abc-15-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"总之，把国有化的事业进行到底，这是我们对自己的第一个要求。","language":"中文","translation":false},{"id":"communism-abc-15-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第九十四节 我们的目的是发展生产力","language":"中文","translation":false},{"id":"communism-abc-15-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"全力发展生产力应该成为我们全部政策的基础。国家遭到的破坏是极端严重的，战后各种物品极端欠缺，以致于这个任务成了压倒一切的任务。生产更多的产品！多生产靴子、镰刀、铁桶、布匹、食盐、衣服、粮食等等，——这就是基本的任务。如何做到这一点呢？只有采取提高国家的生产力、增加生产的办法。任何别的出路是没有的。这里摆在我们面前最大的困难是来自国际反革命对我们的夹击，它想迫使我们半途而废，并把我们的人力、物力全部夺走。我们首先要从地主和资本家那里夺回石油和煤，其次是要正确地安排生产。这对我们来说是头等重要的大事。当工人阶级不是整个国家的主人的时候，它并不为这些事操心。现在工人阶级掌握了政权。它成了一切的主人。它为国家的命运负责，它肩负着全部任务的重担：把苏维埃共和国从饥饿、寒冷和经济崩溃的深渊中拯救出来。在工人阶级掌握政权以前，它的主要任务是破坏旧秩序。现在它的主要任务是建立新秩序。从前是由资产阶级组织生产，现在是无产阶级自己组织生产了。显然，在破坏最严重的时刻，无产阶级的全部思想都应该集中在组织工业和增加生产上。增加生产——这意味着提高工作效率，生产更多的产品，做好所有机关里的工作，天天出成果。说漂亮话的日子已经过去了，现在是艰苦工作的时期。我们的任务已经不是在莫斯科或彼得堡夺取任何权利，因为工人阶级掌握了这些权利并正在前线捍卫着这些权利。我们的任务就是要生产更多的钉子、马蹄铁、犁、锁、机器和大衣。为了在战争破坏过后不被饿死，为了能穿上衣服，为了使元气得到恢复，为了在建设新生活的道路上走得更快些，现在需要的就是这些。","language":"中文","translation":false},{"id":"communism-abc-15-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"关于增加生产的问题可以归结为以下一些问题：如何增加生产资料（机器、煤、原料）和劳动力的数量的问题；如何正确地组织生产的问题（如何计划整个经济，怎样把一种生产同另一种生产联系起来，需要建立什么样的生产管理机构，怎样更经济和更好地分配原料储备，怎样正确地分配劳动力等等）；如何争取更好地工作的问题，因为这取决于工作者本身（同志式的劳动纪律，同粗枝大叶、马虎了草、玩忽职守作斗争的问题）；最后，还有在生产中如何利用科学和有关专家的工作的问题。","language":"中文","translation":false},{"id":"communism-abc-15-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"所有这些问题都是十分重要的。我们现在应该在实际上真心地去解决这些问题。解决这些问题不是一个工厂的事情，也不是为了一个工厂，而是为了整整一个大国，这里是几百万的工人阶级和半无产者。","language":"中文","translation":false},{"id":"communism-abc-15-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"显然，在这里我们应该从一个观点出发，围绕着一个目标行动，这就是要提高整个国家的生产力。国家正在把自己的经济建立在新的共产主义劳动的基础上。","language":"中文","translation":false},{"id":"communism-abc-15-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"我们的敌人——社会革命党人、孟什维克、资产者等等对我们进行诽谤，说我们根本不是马克思主义者，我们的共产主义是消费主义，分配共产主义。他们说，布尔什维克从资产阶级身上扒下皮大衣，把资产阶级阶级赶出家门，把消费品分光，却不组织生产。这些诽谤一钱不值。人类社会的生产力是由生产资料和劳动者，即活人构成的。工人阶级是基本的生产力。机器、工具等等遭到破坏，问题还不算太大，因为有经验的工人是能修复一切的，尽管会遇到困难。如果这些活的生产力遭到破坏，如果工人们由于饥寒交迫而离开城市，远走他乡，如果工人阶级瓦解了，那就是另一回事了。所以，无论如何应该保存住工人阶级。在这里，有组织地剥夺消费数据是保存劳动力的一个条件。消费共产主义在这里实现我们当前的目的即组织生产的一个条件。资产阶级处处都想把战争的全部耗费和战争造成的一切灾难、饥饿、寒冷等等加到无产阶级身上。无产阶级为了自己的未来，则应该让资产阶级肩负战时的重担。但是我们的基本路线当然是组织生产力和发展生产力。","language":"中文","translation":false},{"id":"communism-abc-15-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第九十五节 有计划地组织经济","language":"中文","translation":false},{"id":"communism-abc-15-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"资本主义解体的时代留给无产阶级的遗产不仅是极少量的生产力，而且还有全面的混乱状态。俄国被搞得四分五裂，不同地区的相互联系中断了，各个区域之间的来往变得极为困难。在革命的影响下，工厂主动放弃了管理权，最初有些地方工厂简直处于无人负责的状态。后来开始了工人对企业的自发占领，因为工人已经不能再等待了，这种就地“国有化”甚至比十月革命还开始得早一些。任何人都很清楚，这实质上不是国有化，而是在这些企业工作过的工人对企业的无组织地占领；这种占领只是到后来才变为国有化。但是，起初，即使在十月革命以后，国有化的工作也显得杂乱无章。不言而喻，本来应该首先对那些最大的、设备最好的企业实行国有化，但这不是经常都能做到的。被国有化的往往是那些被主人扔下的、不能没有人照管的企业。但是常常也还有这样一些企业被国有化，这些企业的老板对工人的反对情绪是特别强烈的。显然，这类老板在内战时期是非常多的，同样也很清楚，这些企业当中往往有一些很糟糕的、毫无用处的企业。这类企业多得是，因为这些企业是在战争时期扩充起来的和为“国防”服务的，组织得很匆忙，在革命时期垮得也很快。所有这一切就更加助长了最初时期的混乱局面。","language":"中文","translation":false},{"id":"communism-abc-15-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在初期，苏维埃政权及其机构甚至对于究竟有多少家当都心中无数：不知道有多少企业，不知道有多少原料、燃料和商品储存，不知道有多大的生产能力，也就是说，没有计算过有多少被收归国有的企业能够进行生产。资产阶级一命呜呼了，但是它并没有给无产阶级留下详细的遗嘱。无产阶级“继承”了资产阶级的财富，但这是在残酷的内战中夺来的。显而易见，在最初阶段根本谈不上有什么统一的经济计划。旧的、资本主义的组织崩溃了；新的、社会主义的组织尚未形成。","language":"中文","translation":false},{"id":"communism-abc-15-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"然而，苏维埃政权的基本任务之一过去和现在都是要根据第一个总的国家计划把所有的经济活动统一起来。只有在这种条件下才能把全国的生产力保持在一个水平上，以便进一步使它向前发展。从本书的第一部分里我们已经知道，共产主义制度之所以好，是因为它能消除混乱，即消除资本主义制度的“无政府”状态。共产主义制度的基础正是应该奠定在这一点上。当然，如果认为在存在饥饿、寒冷，缺乏必要的燃料和原料的情况下，能够在短期内迅速地取得坚实的和良好的成果，那只能是一种滑稽可笑的想法。但是要知道，当房子还没有盖好和脚手架还没有拆除之前，人们总不能住房子的地基上，但是打地基毕竟还是需要的。建设共产主义社会的情况也同样如此。为它奠定基础，这就是组织工业，首先是按照总的国家计划把工业统一起来。","language":"中文","translation":false},{"id":"communism-abc-15-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在实践中完成这个任务首先是从统计开始的，就是说要搞清楚，无产阶级政权究竟拥有哪些东西，有多少储备，多少企业等；逐渐地在过去的单个的企业之间建立起联系；建立起中心供应机构（原料、燃料、必要的辅助材料的供应等等）；建立起地方和中央工业管理的机关网，有了这些机关，就能够制定出总的计划，并在全国实行这个计划。","language":"中文","translation":false},{"id":"communism-abc-15-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"如果我们从下往上看，管理工业的机构大体上是这样建立的。在每个工厂上面是工人委员会；通常这个管委会的成员有三分之二来自工人，即相应的工会成员，有三分之一是工程师，他们是在取得工人工会中央委员会同意的条件下确实的；某些不太大的企业由区管理局领导，区管理局隶属于地方国民经济委员会，而地方国民经济委员会又隶属于地方工人代表苏维埃；更大一些的企业则直接隶属于所谓的“总局”和“中心”。这些“总局”和“中心”是一种产业联合组织：例如“纺织中心”管理所有纺织工业，“制钉总局”管理钉子生产行业，“煤炭总局”管理煤炭的生产（参看本章第一节）。在国家资本主义制度下存在的是各个部门的国家托拉斯，而在我们这里存在的则是“总局”和“中心”。这些总局和中心的成员是由最高国民经济委员会主席团（下面将要谈到）和相应的产业工会中央委员会决定的；如果出现分歧，则由全俄工会中央理事会来代替这个产业工会，由它和最高国民经济委员会主席团一起来决定该“总局”的成员。通常受地方国民经济委员会经管的是一些不太大的企业。","language":"中文","translation":false},{"id":"communism-abc-15-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"“总局”和“中心”有的还根据近似的部门分组来建立。例如，建立了这样一些“总局”：国营机械制造总厂、铜业中心、金矿总局、制钉总局等等。","language":"中文","translation":false},{"id":"communism-abc-15-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"现以金属局所属各组的情况为例：","language":"中文","translation":false},{"id":"communism-abc-15-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第一组、“索尔莫夫-科洛姆纳”总厂1、索尔莫夫斯克工厂。 （国营机械制造总厂）……十七个工厂2、科洛姆纳工厂。 3、威·威克萨工厂。 4、维尔斯克工厂。 5、钢丝厂。 6、布舒耶夫斯基工厂。 第二组、焦炭-炼铁和铁制品总厂……三个工厂 第三组、卡卢什-梁赞炼铁总厂……九个工厂 第四组、马尔采夫总厂……六个工厂 第五组、铜业中心……十个工厂 第六组、汽车总厂……八个工厂等等","language":"中文","translation":false},{"id":"communism-abc-15-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（以上材料摘自金属委员会给最高国民经济委员会主席团的报告，该报告是由米柳亭同志提供的。）","language":"中文","translation":false},{"id":"communism-abc-15-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在“纺织中心”领导的纺织工业中，还有所谓的“联社”（特别是在棉纺织部门），它联合了一些生产半成品或成品的企业。","language":"中文","translation":false},{"id":"communism-abc-15-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"一般说来，这里的一切都远不是固定的，新的形式在不断产生，旧的形式在不断消亡。在当前也不可能是另外的情况，因为我们正处在一个瞬息万变的建设时期，而且条件很艰巨，今天我们有乌拉尔，明天可能就会失掉，今天我们还没有乌克兰，明天又可能拿回来。","language":"中文","translation":false},{"id":"communism-abc-15-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在这里，不仅单个部门联合起来了，而且这些部门彼此联合成为一个巨大的整体。自然，首先联合起来的是那些相互间有某些共同点的部门。例如，钉子的生产、机械的生产、铜和铜制品的生产等等都属于与金属有关的一类。这一类的总局都统一归最高国民经济委员会金属局管。这种局有好多个：有上面提到的金属局，有化工局、食品局、印刷局等等。在1919年秋天以前，这类局建立得相当多。在金属局里工作和起作用的主要是全俄五金工人工会中央委员会；五金工人很进步，很有水平，工作很出色，所以他们确实在这里做了许多工作；其它的局就要差一些。例如，化工局直到1919年秋天才刚刚开始有工人参加，因为在这之前他们甚至没有统一的工会。","language":"中文","translation":false},{"id":"communism-abc-15-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"所有的局都隶属于最高国民经济委员会；最高国民经济委员会由工会理事会和苏维埃全俄中央委员会的代表和人民委员组成，并设有主席团负责主持全部事务。这样，最高国民经济委员会就把全国的经济活动经管起来。它的责任首先是制定和实行统一的全国计划。","language":"中文","translation":false},{"id":"communism-abc-15-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"工人本身经过适当的组织就能提高企业的生产率，这一点，从五金工会在其中起决定性影响的国营金属总厂的活动中可看得很清楚。请看下面的一些数字：","language":"中文","translation":false},{"id":"communism-abc-15-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"共 生 产 车厢与机车备件军用装甲列车机车车盘车厢、糟车、等军用小平车转辙器 新制 修理 1918年（11-12月）两月24240普特 24477 —1480 1919年（1-6月）六个月94419普特 10 1911811040522 7543","language":"中文","translation":false},{"id":"communism-abc-15-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（此材料是由拉林同志提供的。）","language":"中文","translation":false},{"id":"communism-abc-15-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"生产时间多了两倍（两个月与六个月），但是产量却远远多于两倍。","language":"中文","translation":false},{"id":"communism-abc-15-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"只要加以组织（这一工作已慢慢开始在做），就可以更加有计划地把“总局”负责的供应工作搞好，并且把生产集中到供应情况最好的企业中去。后面这一点是整个计划所要求的。因为很清楚，与其在那些办得很糟、设备很差的企业里徒劳无益地苦干，不如集中全部力量去帮助那些最好的企业，这样事情会有利得多。当然，这里也必须考虑到燃料和原料普遍严重缺乏的情况。正因为如此，我们不得不有时把一些最大的工厂关掉（例如在纺织工业中），所以至今我们还经常看到生产局部破坏的情况发生。但是这种情况并不是由于缺乏组织工作，而主要是由于缺乏生产所必需的物资。","language":"中文","translation":false},{"id":"communism-abc-15-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"下面是一张有关燃料和原料储存的对比表，它同时也反映出在现有资源的统计上的某些进步：","language":"中文","translation":false},{"id":"communism-abc-15-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1、莫斯科近郊区和波罗维切斯克地区的煤炭……","language":"中文","translation":false},{"id":"communism-abc-15-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"2．木材（采购和储存）……","language":"中文","translation":false},{"id":"communism-abc-15-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"B．原料的采购和最高国民","language":"中文","translation":false},{"id":"communism-abc-15-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"6百50万普特（包括现已归回的土耳其斯坦）。","language":"中文","translation":false},{"id":"communism-abc-15-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"4千万普特（包括乌拉尔在内）（此材料摘自米柳亭同志的资料。）","language":"中文","translation":false},{"id":"communism-abc-15-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"从表中可以看到，某些方面已有所好转。同样也可以看到，最主要的困难是缺乏液体燃料（石油）。","language":"中文","translation":false},{"id":"communism-abc-15-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"生产的集中仍在照常进行。例如，国营金属总厂关闭了许多办得不好的企业，把生产集中在十六个较好的工厂里；电机工业在资本主义时期是分散的，现在已经联合成为一个整体；许多其它部门的情况也同样如此（如烟草工业、面包工业、果酱工业、纺织工业等等）。","language":"中文","translation":false},{"id":"communism-abc-15-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"正确地与节省地使用现有的人力和物力具有重大的意义。正如我们所见到的，在最初我们甚至对究竟有些什么都心中无数。大量仓库都被搞空了，储存的货物不断被盗，不知去向，根本谈不上正确地使用问题。但是现在事情正在好转，尽管困难很多。至少现在对许多东西的现存数量已大体心中有数了。（见上表）","language":"中文","translation":false},{"id":"communism-abc-15-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"自然，调整和组织经济的工作还远远不够完善。在许多机构里茫无头绪和杂乱无章仍占统治地位。各机构的工作还远未走上正轨。但是这套机构的架子已经打了起来。我们的任务就是要全面推进这一工作，其中包括要把国家的全部经济活动统一起来，订出统一的经济计划，实行生产的最高度集中，加强生产的组织性和管理机构的条理性，以及正确地利用国家的原料和所有的物资储备。","language":"中文","translation":false},{"id":"communism-abc-15-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第九十六节 扩大与其它国家的经济合作","language":"中文","translation":false},{"id":"communism-abc-15-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"我国对外关系的问题涉及到组织大工业的问题。苏维埃俄国四面八方都遭到封锁，这对于苏维埃俄国是一个巨大的打击。同其它国家断绝经济来往对我国的工业和整个经济有何影响，可以从下列数字中得到说明。","language":"中文","translation":false},{"id":"communism-abc-15-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"进口最多的是工业制品，四年之中（从1909年到1913年）共增加了百分之六十五。在同一时期，原料和半成品增加了百分之五十。这就是说，进口的重要性迅速增长。首先进口了机器、仪器、农业机械、化工产品、电器用品和其它生产资料。但是消费数据（纺织品、皮革制品等等）的进口额也在不断增加。","language":"中文","translation":false},{"id":"communism-abc-15-77","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":77,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"战争中止了与德国的一切联系。对苏维埃俄国的封锁也切断了和同盟国的所有来往。根据战前的统计，我们从国外进口的商品总额几乎达到十五亿卢布。封锁给我们带来的了多么大的损失是可想而知的。","language":"中文","translation":false},{"id":"communism-abc-15-78","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":78,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"因此，我们党的政策应该是，只要与我们的总任务并行不悖，就要竭力恢复与其它国家的经济来往。彻底战胜反革命是搞好这一工作最好的保证和最可靠的基础。","language":"中文","translation":false},{"id":"communism-abc-15-79","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":79,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"我们的另一项任务是与无产阶级取得胜利的国家建立相互的经济关系。在这里，我们的任务不仅是要与这些国家建立经济联系，而且还要尽可能地制定统一的经济计划。在德国无产阶级取得胜利以后，我们就可以建立统一的机构来实行两个苏维埃共和国的统一的经济政策：这个机构可以计算一下，有多少德国无产阶级的工业产品需要调拨到苏维埃俄国，有多少熟练（受过训练的）工人需要调到，比如说，俄国的机车制造厂去，而反过来，又有多少原料或黑麦需要调拨到德国。我们已经知道，欧洲要想最迅速摆脱破坏状态，就应把一些国家联合起来。自然，我们不能和资本主义国家合在一起。相反，我们能够而且必须和各苏维埃共和国结成紧密的经济联盟，实行统一的经济计划。实现经济上的无产阶级国际范围的生产集中——这就是我们的目的。","language":"中文","translation":false},{"id":"communism-abc-15-80","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":80,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第九十七节 小工业和手工业组织","language":"中文","translation":false},{"id":"communism-abc-15-81","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":81,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"我们知道，在俄国建设共产主义的重要困难之一是，俄国，象所有不发达的、落后的国家一样，基本上是一个小生产的国家。这主要指的是农业。但是在工业中也还有旧关系的残余：手工业者、工匠和小企业主有相当大的数量。根据战前的统计，在三十四个省内大约有一百七十万户有固定营业地点的手工业者（根据最高国民经济委员会利用委员会的材料。）","language":"中文","translation":false},{"id":"communism-abc-15-82","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":82,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1． 矿物业……66万4千户","language":"中文","translation":false},{"id":"communism-abc-15-83","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":83,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（陶器、砖瓦、制做磨盘和磨刀石、铜器、石灰）。","language":"中文","translation":false},{"id":"communism-abc-15-84","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":84,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"2． 木材业……46万7千9百户","language":"中文","translation":false},{"id":"communism-abc-15-85","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":85,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（蒲席——树皮纺织物；木桶、木槽；木制家俱；树皮鞋；雪撬、大车；篮子、藤制家俱；车轮、轮圈；木炭、煤焦油和沥青；木制餐勺；造船、放木排——共十八种行业）。","language":"中文","translation":false},{"id":"communism-abc-15-86","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":86,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"3． 五金业……13万5百户","language":"中文","translation":false},{"id":"communism-abc-15-87","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":87,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（锻铁——制钉、制斧；钳工制把手和刀子；精制钟表；铸造；门窗用五金件；水桶及烟囱）。","language":"中文","translation":false},{"id":"communism-abc-15-88","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":88,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"4． 纤维业……6万5千2百户","language":"中文","translation":false},{"id":"communism-abc-15-89","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":89,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（织布；毛毡；纱线；花边；头巾；网、绳索；呢绒；地毯；帽子；刷子等等——共十一种行业）。","language":"中文","translation":false},{"id":"communism-abc-15-90","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":90,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"5． 皮革业……20万8千3百户","language":"中文","translation":false},{"id":"communism-abc-15-91","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":91,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（制靴；熟制毛皮；制革；鞍具；皮大衣、手套；梳毛）。","language":"中文","translation":false},{"id":"communism-abc-15-92","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":92,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"6． 其它行业……18万5千4百户","language":"中文","translation":false},{"id":"communism-abc-15-93","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":93,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"据某些方面的统计，在战争时期，手工业者的数量减少到一百万户，尽管有许多工人由于战争的破坏而转到了手工业。这是由于手工业者为了寻找生路而流落他乡。整个说来，在沃洛格达、诺夫戈罗德等省，即在一些闹饥荒的省份，手工业者减少了百分之二十至二十五，相反，在库尔斯克、奥尔洛夫、辛比尔斯克、坦波夫等省则增加了百分之十五至二十。","language":"中文","translation":false},{"id":"communism-abc-15-94","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":94,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"摆在无产阶级面前的任务是：如何把这一大批小生产者纳入正在建设着的社会主义经济的总体系统中来。","language":"中文","translation":false},{"id":"communism-abc-15-95","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":95,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"首先，很清楚，这里不允许实行任何强制性的剥夺。不能用大棒把小生产者赶进社会主义王国。但是必须尽一切可能来使他们便于接受这种过渡，并认识到这种过渡的必要性和好处。如果为手工业者提供一定的条件，这一点是可以做到的。提供什么样的条件呢？通过什么样的途径呢？","language":"中文","translation":false},{"id":"communism-abc-15-96","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":96,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第一，要把手工业列入国家原料和燃料供应计划。实际上，如果手工业从无产阶级国家组织那里获得生产所必需的物资（原料和燃料），那它就会依赖于这些组织。从前，在资本主义制度下，经常是由采购商或工厂主为手工业者提供原料。手工业者处在依附于这些人的地位。但是，显而易见，这些采购商或工厂主“供应”手工业者是为了剥削目的。手工业者无非是为资本家干活的家庭工人。如果手工业者依赖的是无产阶级国家，那就业完全是另一回事了。无产阶级的、工人的国家不想、不会、也不可能剥削手工业者。它只是想帮助手工业者同所有其它的工人一起组织起来。它不会从手工业者那里榨取利润（它也不会从任何人那里榨取利润），而只是力求吸引手工业者及其组织参加到统一的工业劳动组织中来。依附于工厂主和采购商的手工业者，是为工厂主和采购商而劳动。他们是为这些人干活的牲口。依赖于无产阶级国家的手工业者是社会的工作者。所以，首先必须把手工业者纳入统一的供应计划。","language":"中文","translation":false},{"id":"communism-abc-15-97","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":97,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第二，国家必须在财政上支持手工业者。过去，在资本主义制度下，手工业者在资金方面也是依靠采购商——高利贷者。但是这些人支持手工业者就象用一根绳子吊着一个被绞死的人。他们以最野蛮的方式奴役这些手工业者，就象蜘蛛在吸尽他们的血液。无产阶级国家能够用钱来帮助手工业者，给他们以国家定货的任务，不扣任何利息，尤其是不要任何高利贷。","language":"中文","translation":false},{"id":"communism-abc-15-98","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":98,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第三，不言而喻，无产阶级国家应该以集中的方式向手工业者定货。无产阶级的国家政权向手工业者供应原材料、燃料、辅助材料，并且也尽可能地为他们提供工具，按照一定的计划向他们提出定货，这样一来就可以逐步地把手工业者纳入国家统一的生产计划。","language":"中文","translation":false},{"id":"communism-abc-15-99","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":99,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"由此可见，手工业者之所以能逐步地被吸收到统一的、建立在社会主义原则基础上的生产中来，原因不仅在于为他们供应了社会生产的产品，而且在于他们也是在直接地为无产阶级国家工作，同时是在按照无产阶级国家机关所规定的计划工作。","language":"中文","translation":false},{"id":"communism-abc-15-100","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":100,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第四，必须按上述方式在手工业者联合起来的条件下给予他们以支持，对那些联合起来并加入劳动组合、劳动协作社、生产合作社的手工业者要特别加以优待，尤其是对那些建立起这样的组织、正在由个体小生产向协作化的大生产过渡的手工业者，这一点是非常重要的。","language":"中文","translation":false},{"id":"communism-abc-15-101","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":101,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"每个小业主，手工业者也在内，内心深处总是憧憬着能成为一个大的业主，能“飞黄腾达”，然后开一家象样的具有雇佣工人的“买卖”。当在资本主义制度下劳动组合、协作社或合作社产生以后，其中一些最强有力的组织真正“退化”成为资本主义企业。在无产阶级专政时期是另一回事。资本主义在这里是没有出路的。因为这里是工人的国家政权，这个政权组织各种各样的联合团体，掌握着财政，主要是掌握着生产资料。过去有人认为劳动组合能把我们引向社会主义，那是很荒唐的：劳动组合在发展过程中不可避免地会变资本主义的协作社。现在我们有可能把它们吸收到工人的全国性的组织中来，所有这些联合组织都会有助于建设社会主义的事业。这并不因为手工业者本身向往共产主义（他们中的许多人，就象所有的小业主一样，都带有反共的偏见），而是因为现在已经形成了新的条件，过去的道路都已被堵死，已不存在了。","language":"中文","translation":false},{"id":"communism-abc-15-102","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":102,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"由于我们鼓励手工业者联合起来，所以我们就能促使他们很痛快地变成联合的、有组织的、“机械化的”社会大生产的工作者。","language":"中文","translation":false},{"id":"communism-abc-15-103","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":103,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"这方面的工作已经做过一些。例如在1919——1920年冬，已经分派了一系列的国家定货，其中二百万双毡靴，二百二十万双手套，许多针织品、树皮鞋、短皮袄等等。工作的实效也有了提高。1918——1919年的一个季度，到3月1日为止，只生产了三十万双毡靴（！）；而在1919——1920年的一个季度，到10——11月份为止，已生产了五十万双毡靴。","language":"中文","translation":false},{"id":"communism-abc-15-104","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":104,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"有计划地发放了预支款；配给了原料、煤油、灯具（照明用）、燃料。1918——1919年，组织了这样一些活动：召开了合作社组织代表会议，手工业者联合会（中央消费合作总社、中央分社、莫斯科分社、手工业制品经销社等等）与最高国民经济委员会手工业局的代表会议，制定了总的计划。手工业制品经销社（手工业和劳动组合商品生产销合作总社）是被纳入整个组织工作中的一个最大的手工业者的组织。它包括二十九个联合会，拥有一千三百零六个合作社，组织起六十三万一千八百六十户手工业者。供应工作直接由各总局或国民经济地方委员会担负。","language":"中文","translation":false},{"id":"communism-abc-15-105","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":105,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"应该指出，在苏维埃政权时期，联合会的数目增加得很快。","language":"中文","translation":false},{"id":"communism-abc-15-106","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":106,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"当然，究竟如何把苏维埃经济机构各个不同部分联系起来，这个问题还没有彻底解决；这里有许多事情变化得相当快。但是我们必须经常注意一点：要使机构更加健全，组织更加严密，全部行动更有计划。","language":"中文","translation":false},{"id":"communism-abc-15-107","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":107,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第九十八节 工业组织和工会","language":"中文","translation":false},{"id":"communism-abc-15-108","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":108,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在俄国，在组织和管理工业方面，最能适应新任务的机构就是工会。在资本主义制度下，起初按行业（有时甚至是按车间），后来按生产部门联合工人的工会，是与资本家进行斗争的工具，首先是进行经济斗争的工具。在斗争激烈的时期，它们和工人阶级的党——布尔什维克在一起，领导了对资本进行的总攻击。党、工会和苏维埃一起齐心协力地反对资本主义制度。在夺取政权以后，工会的作用自然应当有所改变。比如说，从前它们举行罢工来反对资本家。现在资本家作为统治阶级，作为老板，作为企业主，已经不存在了。过去工会的一个主要的作用是破坏工厂里实行的制度。1919年10月以后，自然也就出现了建立新秩序的时期。","language":"中文","translation":false},{"id":"communism-abc-15-109","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":109,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"组织生产——这是工会在无产阶级专政时期的主要任务，工会在其存在时间团结起广大的无产阶级群众。它们是最大的、同时是直接和生产相联系的无产阶级组织。此外，它们在俄国革命中完全支持无产阶级专政的观点。不难理解，在现实中管理工业，包括管理最重要的生产力即劳动力的工作，正是应该交给这样的组织。","language":"中文","translation":false},{"id":"communism-abc-15-110","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":110,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"工会与无产阶级的国家政权应该是一种什么关系呢？","language":"中文","translation":false},{"id":"communism-abc-15-111","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":111,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"可以回想一下，为了争取最大的成果，资产阶级是怎么做的。资产阶级建立了国家资本主义，并把自己所有的组织，首先是经济组织（辛迪加、托拉斯、财团）都集结到国家政权里来。无产阶级应把反对资本的斗争进行到最后胜利，它同样也必须集中起自己的组织。无产阶级有工人代表苏维埃——国家政权机关；有工会；有了合作社。很清楚，这些组织应该彼此紧密配合，同心协力地把工作搞好。这里产生了一个问题：所有的组织应该向哪一个组织靠拢呢？回答并不困难。必须挑选出一个最大的、最有力量的组织。而工人阶级的国家组织，即苏维埃政权也就是这样的组织。这就是说，无论是工会还是合作社都应该沿着把它们变成经济部门和国家政权机关的道路发展，也就是说沿着自己“国家化”的道路发展。","language":"中文","translation":false},{"id":"communism-abc-15-112","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":112,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"妥协主义政党总是把阶级斗争置于脑后，它们在无产阶级专政时期的工会问题上，持着所谓工会运动“独立”的观点。这些先生说：工会是阶级组织，因而它应该独立于国家政权之外。","language":"中文","translation":false},{"id":"communism-abc-15-113","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":113,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"这种以虚假的“阶级”观点伪装起来的骗局是不难看穿的。绝不能把“国家”与“阶级组织”对立起来，因为国家也同样是阶级的组织。孟什维克和其它人反对与工人国家的联系，从而反映了他们对工人国家的敌视，他们是站在资产阶级一边的。而且恰恰是他们拥护对于资产阶级国家的依赖。","language":"中文","translation":false},{"id":"communism-abc-15-114","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":114,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"他们常常谈论“官方”工会。但是现在官方是工人的官方。而孟什维克希望官方永远是资产阶级的。离开工人政权的独立性实际上就是依附于资产阶级。","language":"中文","translation":false},{"id":"communism-abc-15-115","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":115,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"摆在工会面前的新任务要求尽快地把这些工会变成大产业工会。因为很清楚，如果工会的任务是组织生产，那么工人就应该按企业和生产联合，而不是按车间和职业联合；换句话说，要完成新的任务就需要这样来组织工会，即使一个企业的所有工人和职员都参加同一个工会，而且在每个企业只能存在这一个工会。过去工会是这样建立的，即工人是按照细小的职业原则来联合的。如果说后来出现了按生产原则联合的要求，那也是混乱得很：比如说，五金工人工会不仅会接受金属加工工业的同伴入会，而且还接受任何五金工人入会，尽管这些人是在离得很远的生产部门中工作。当然，这对于组织生产是根本不适宜的，因为每一个企业和每一个部门都是一个有活力的组织；要把它组织起来，人们就必须去适应它，并通过相应的方式，即按照生产部门组织起来，把所有的工作人员都联合在一起（彼得堡五金工人的例子就是把过去的小工会联合成为大产业工会的例子。）","language":"中文","translation":false},{"id":"communism-abc-15-116","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":116,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"（1917年底到1918年初）","language":"中文","translation":false},{"id":"communism-abc-15-117","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":117,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1．五金工人工会及其分会（组成全俄五金工人工会局），只联合金属加工工业的工人。","language":"中文","translation":false},{"id":"communism-abc-15-118","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":118,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"4．焊接工人与气切工人工会","language":"中文","translation":false},{"id":"communism-abc-15-119","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":119,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"这样，大的、集中的产业工会便代替了根据细微的职业判别而形成的各种各样的分散的工会。我们党在这方面的任务就是要加速这种联合，促进产业工会的建立，以便把相应生产部门的全体劳动者都吸收到产业工会里去。","language":"中文","translation":false},{"id":"communism-abc-15-120","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":120,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"根据全俄工会中央理事会统计局的初步材料，工会会员的数量为：","language":"中文","translation":false},{"id":"communism-abc-15-121","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":121,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1917年上半年………………………………………………………………335938人","language":"中文","translation":false},{"id":"communism-abc-15-122","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":122,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1917年下半年………………………………………………………………943547人","language":"中文","translation":false},{"id":"communism-abc-15-123","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":123,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1918年上半年………………………………………………………………1649278人","language":"中文","translation":false},{"id":"communism-abc-15-124","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":124,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1918年下半年………………………………………………………………2250278人","language":"中文","translation":false},{"id":"communism-abc-15-125","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":125,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1919年上半年………………………………………………………………2825018人","language":"中文","translation":false},{"id":"communism-abc-15-126","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":126,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1919年上半年，三十一个全俄工会（铁路总会和水运总会除外）联合了二百八十万一千名会员（其余的人加入了地方工会）。如果再加上七十二万二千名铁路工会会员和将近二十万水运工会会员，工会会员总数可达到三百七十万人，他们隶属于三十三个中央一级工会；此外，还有许多非中央级的工会。统计局认为参加工会组织的人数总共有四百万人（包括被占领的省份），应该注意的是，有些工厂尽管停产，但那里的工人仍应继续认为是这些工厂的工人，并且可以继续作为会员。","language":"中文","translation":false},{"id":"communism-abc-15-127","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":127,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"根据苏维埃共和国的法律和既成的事实，工会（产业工会）是各级地方和中央工业管理机构的参加者。这就是说，无论在各委员部、国民经济委员会和国民经济最高委员会里，还是在各总局、中心和工厂工人管委会里，——总之，在所有的地方，工会都起着巨大的，甚至是决定性的作用。","language":"中文","translation":false},{"id":"communism-abc-15-128","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":128,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"但是，工会掌管生产的工作还远远没有结束。不少国民经济部门的工人还没有象应该做的那样，掌握起方向盘。特别应该提到的是，在某些“总局”和“中心”里，有一些胆大妄为的资产阶级专家经常摆出一副趾高气昂的样子，他们不肯抛弃自己那套组织经济的办法，指望“旧的黄金时代”重新来到，以便他们能迅速地将总局变成为资本主义的托拉斯。为了防止这种情况发生，必须使工会更加广泛深入地参加工业管理工作，直到整个国民经济这一统一整体都实际掌握在各级产业工会手中为止。","language":"中文","translation":false},{"id":"communism-abc-15-129","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":129,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在基层工业管理机构中，应该特别指出的是工厂委员会的活动。它实际上是相应产业工会所属工会的一个支部。工厂工人选举出来的工厂委员会掌管企业内部的事务，因为这些事务都牵涉到劳动力。这就是说，工厂委员会要管工人的“雇用”和解雇，关心家庭的生活保障、工资的发放、生产的定额和纪律等等。此外，工厂委员会对于广大工人群众来说还是出色的学习管理的初级学校。","language":"中文","translation":false},{"id":"communism-abc-15-130","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":130,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"因此，工会（产业工会）应该保证国家中央管理机关、国民经济以及广大群众之间的联系。","language":"中文","translation":false},{"id":"communism-abc-15-131","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":131,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"日益广泛地引导群众参加经济生活的管理，这是产业工会头等重要的和刻不容缓的任务。产业工会应该依靠工厂委员会，把几乎所有的劳动者都联合起来，造就出越来越多的生产组织者。在直接实践中（在工厂委员会，工厂管委会，国民经济委员会和总局等机构里）学习管理的活动和工会开展的专门教育工作（指导员训练班等等）就是为这一目的服务的。","language":"中文","translation":false},{"id":"communism-abc-15-132","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":132,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"吸收广大群众参加建设工作也是与苏维埃政权经济机构中的官僚主义进行斗争的最好手段。这种官僚主义有时发展到了极其严重的程度，特别是在工人很少，而“苏维埃职员”很多地方。官僚主义、文牍主义、衙门作风、粗暴武断、敷衍塞责、消极怠工，——这些现象在经济组织里屡见不鲜。只有提高基层工人的水平，才能根除这些现象。也只有这样才能在我们所有经济机构里真正建立起人民对工作的监督。","language":"中文","translation":false},{"id":"communism-abc-15-133","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":133,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第九十九节 劳动力的利用","language":"中文","translation":false},{"id":"communism-abc-15-134","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":134,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"正确地利用我们现有的劳动力对于我们的整个未来具有特别重要的意义。在生产资料已经陈旧，原料极其短缺的情况下，劳动力就是整个生产的基础，一切都取决于对劳动力的合理利用。总的说来，我们面临着这样一些任务：利用所有的人力；换句话说，把全部有劳动能力的人都利用起来，为他们安排工作，使他们有事情可做。应该记住：在我们的饥饿时期，每一个人不从事任何有益工作的人，都是社会的直接累赘。这样的人比比皆是。而不需要特别复杂的生产资料就能干得了的工作却多得是：例如，城市卫生工作，维护桥梁、公路、铁路，清理道路，修筑个别地方的防御工事，清扫营房和各种场所；在提供原料和燃料方面也有一系列的工作：如砍伐和运输木材，采掘泥炭等等。当然，这里困难很多：人也有，斧子也有，但是却没有东西给这些人吃，——于是砍伐木柴的事也就停了下来，等等。但是十分明显，只有把活的劳动力利用起来，我们才能度过这段困难时期。","language":"中文","translation":false},{"id":"communism-abc-15-135","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":135,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"这样，就提出了为完成某项社会工程而进行普遍动员的问题。在抢修防御工事时，很好地利用了平时闲散的劳动力。应当使这一工作经常化。普遍劳动义务制已经写入俄罗斯苏维埃联邦社会主义共和国宪法，然而这条规定在实际生活中还远远没有完全实现。这就是第一个问题即把劳动共和国所有劳动力都利用起来的问题。","language":"中文","translation":false},{"id":"communism-abc-15-136","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":136,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第二个问题是关于劳动力的分配和再分配问题。很清楚，劳动生产率的高低将取决于这些劳动力在不同地区和不同工作部门合理分配的程度。","language":"中文","translation":false},{"id":"communism-abc-15-137","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":137,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"劳动力的分配与调动要求在劳动力的统计方面进行大量的工作，如果真正做得正确和有计划的话。因为不计算一下究竟有多少人力，就不可能正确地分配人力。只有通过工会和在工会的参与下，苏维埃政权才能解决这一任务。","language":"中文","translation":false},{"id":"communism-abc-15-138","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":138,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第一百节 同志式的劳动纪律","language":"中文","translation":false},{"id":"communism-abc-15-139","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":139,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"一个国家的生产力的状况不仅取决于它有多少机器、工具、原料等等，而且取决于这个国家的劳动力。而现在，在生产资料特别少的情况下，劳动力的状况与活劳动便具有直接头等的意义。","language":"中文","translation":false},{"id":"communism-abc-15-140","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":140,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"资本主义生产方式对工人阶级实行严密控制，逼着他们为老板工作，强迫他们服从棍棒的纪律。","language":"中文","translation":false},{"id":"communism-abc-15-141","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":141,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"革命彻底冲破和废止了资本主义的这种劳动纪律，就象它在军队里破坏了帝国主义的的纪律并消除了士兵对沙皇将军的顺从一样。但是显然，没有新的纪律要想进行共产主义建设是不可能的。这里和军队里的情形是完全一样的。我们消灭了旧的军队。在一段时间里曾出现过“无政府主义”，秩序混乱，各行其是。但是我们在新的原则上，为了新的目的，建立了新的军队。这支军队掌握在无产阶级手里，与管理过旧军队的地主和资本家进行战斗。","language":"中文","translation":false},{"id":"communism-abc-15-142","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":142,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"“劳动大军”、工人阶级的情况也是这样。瓦解旧纪律的时期已经过去。正在开始安排新的、劳动者的同志式的纪律，执行和维护这一纪律的不是老板，也不是资本家的鞭子，而是工人自己的组织，即工厂委员会和工会。","language":"中文","translation":false},{"id":"communism-abc-15-143","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":143,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在组织生产时，必须注意工厂中的劳动组织。","language":"中文","translation":false},{"id":"communism-abc-15-144","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":144,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"所以，劳动者的同志式的纪律是组织整个生产和提高生产力的最重要的手段之一。","language":"中文","translation":false},{"id":"communism-abc-15-145","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":145,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"同志式的纪律应该同工人阶级的高度主动精神结合起来。这并不是说，工人应该坐等上面的命令，永远不要发挥主动首创精神；相反，任何生产改进，任何劳动组织新方法的发明等等都应该为自己开辟道路。工人中的落后阶层往往看不见指引工作方向的道路。但是这样的道路是有的。工人联合成工会，这些工会又管理着生产；工人们每天注视着工厂委员会和工厂工人管委会。只要积极肯干，不胆怯，而感觉到工人阶级现在是生活的主人，那么不管是什么事情都可以自下而上地通过工人组织办到。","language":"中文","translation":false},{"id":"communism-abc-15-146","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":146,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"劳动纪律应该依靠的是每一个工作者对本阶级的责任感，是使他们认识到粗枝大叶和纪律松弛是对全体工人的共同事业的犯罪。现在我们已经不存在作为统治阶级的资本家。工人现在不是为资本家，为高利贷者，为银行家劳动，而是为自己劳动。他们是在为自己做事情：他们建设属于劳动者所有的大厦。过去，在资本家统治下，考虑如何为资本家攒更多的钱并不是我们的任务。现在则不同了。对全体工人阶级负责的这种意识应该渗透到每个工人的灵魂。","language":"中文","translation":false},{"id":"communism-abc-15-147","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":147,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"最后，劳动纪律应该依靠最严格的相互监督。应该认识到，降低劳动生产率对于工人阶级的事业来说就是毁灭，不前进我们就将死亡，因此每一个同志都应该以主人翁的态度来监督这一从自然界取得生机的共同事业。要知道，劳动也是斗争，是同自然界的斗争。我们必须战胜这个自然界，用它来做衣服、燃料、面包。我们应当相互监督，就象在和阶级敌人——资本家、地主、将军们进行斗争的战线上那样，我们衡量着我们的成绩，注视着有谁在逃跑、叛变和出卖。谁背叛了工人的事业，谁就不是在帮助我们把工人阶级的大车从泥沆中拉出来，谁就是工人事业中的工贼。","language":"中文","translation":false},{"id":"communism-abc-15-148","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":148,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"自然，建立新的劳动纪律的工作要求在群众的再教育上大力进行工作。要知道，许多人还保留着奴隶式的心理和奴隶式的习惯。就象在军队里一样：沙皇一声令下——人们拔腿就走；可是一要捍卫自己的事业，反倒有些怵头。然而我们还是建立了军队，因为工人的先进阶层是很懂道理的，并且达到了自己的目的。如今在生产中也同样需要这样做。现在对工人进行再教育的工作更便于开展了，因为工人群众亲眼看到，并且通过每天的实践确信，他们的命运掌握在他们自己手中。特别是在某些建立了苏维埃政权以后又短时间出现过反革命政权的地方，群众得到的教训最深，例如乌拉尔、西伯利亚等地的情况就是如此。","language":"中文","translation":false},{"id":"communism-abc-15-149","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":149,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"先进的工人共产党员通过组织所谓共产主义星期六义务劳动在新的同志式的纪律方面树立了很好的榜样，他们进行了自愿的和无报酬的劳动，把劳动生产率比平时提高了许多倍。","language":"中文","translation":false},{"id":"communism-abc-15-150","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":150,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"列宁同志曾经把共产主义星期六义务劳动称作“伟大的创举”。第一批组织这种劳动的人是莫斯科的一些铁路员工——共产党员，从一开始就显示出生产率猛烈提高的情况。亚历山大罗夫斯克铁路所属的五个旋工四个小时内做了八十个小轴（生产率等于平常的百分之二百一十三），二十个粗工在同样的时间里收集了六百普特废旧材料和七十个各重三点五普特的车辆板弹簧（生产率等于平常的百分之三百）。事情就是由此开始的。后来星期六义务劳动传到了彼得堡，那里也立刻大规模地行动起来。","language":"中文","translation":false},{"id":"communism-abc-15-151","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":151,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"后来星期六义务劳动发展到了外省，并开始扩及到非党群众。莫斯科铁路员工的创举确实是伟大的，因为他们探索到了建立纪律的正确道路。","language":"中文","translation":false},{"id":"communism-abc-15-152","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":152,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"当然，建立新的劳动纪律而没有工会参加是不可想象的。不仅如此。正是应当由工会来推动这一工作，试行各种新的形式，寻找各种新的途径；因为所有这些工作都是新的、不寻常的，用老一套办法是行不通的。","language":"中文","translation":false},{"id":"communism-abc-15-153","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":153,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"从已得到运用并应该用一切方法加以发展和改善的措施中，我们党指出了以下几点：","language":"中文","translation":false},{"id":"communism-abc-15-154","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":154,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"1．建立报告制度；这一工作在我们这里还非常薄弱；可是没有报告制度则什么事情都组织不成，既无法考察，也无法监督，更不能发现罪恶的根源；","language":"中文","translation":false},{"id":"communism-abc-15-155","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":155,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"2．制订生产定额；这一工作同样也是在刚刚开始。资本家在自己的企业中制订生产定额是为了从工人身上榨取剩余价值；这种定额是由老板的机构制订的；在我们这里定额则是由工会即工人的组织来制订的并予以发展的。工人组织计算工作量时，既照顾到饥困与寒冷，也考虑到材料的缺乏与机器的不良状况。但是定额一经制定，谁要是完不成，那就不好了。我们应该树立职业的劳动荣誉感，每个工人应该把那些无故不对共同事业作出贡献的人，视为可耻的懒汉；","language":"中文","translation":false},{"id":"communism-abc-15-156","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":156,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"3．建立同志劳动审判会制度。这就是说，对每一个人不仅要实行同志监督，而且工作不好的还要追究责任。这里不是老板对他的雇佣奴隶追究责任，而且工人阶级及其组织对自己的个别成员追究责任。","language":"中文","translation":false},{"id":"communism-abc-15-157","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":157,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"还可以想出更多的措施。但所有这些措施目的只有一个：把劳动大军建设成为一支为新社会开辟道路的战斗队伍。","language":"中文","translation":false},{"id":"communism-abc-15-158","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":158,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第一百零一节 利用资产阶级专家","language":"中文","translation":false},{"id":"communism-abc-15-159","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":159,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"搞现代化的大生产，如果没有工程师、机械师、专家学者、研究人员和实践人员，那是不可想象的。这样的人在工人中间几乎是没有的，因为无论是地主沙皇政府还是资产阶级政府都没有给工人以学习机会。但是事业绝不能等待，我们只有一条出路：利用那些曾经死心塌地为资产阶级服过务的人。党清楚地知道，技术知识分子的这个阶层，以及过去的经理和资本主义的生产组织者，浸透了资产阶级思想。除此之外，在这个阶层里，有相当一部分人对我们极端敌视，随时都会把我们出卖给我们的阶级敌人。但不管怎样我们还是应该利用他们来为我们服务，因为没有别的什么人，没有别的选择。","language":"中文","translation":false},{"id":"communism-abc-15-160","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":160,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"这个阶层对无产阶级进行着激烈的斗争，首先是采取怠工的形式。苏维埃政权摧毁了这种怠工。其中有一部分人开始逐渐地转到我们一边，因为他们看到，工人阶级不仅破坏，而且也建设，他们看到，工人阶级的党根本不打算把俄国出卖给德国帝国主义；有些人开始想，资本主义在世界上似乎确实活不长了。这个阶层开始分裂了。无产阶级的任务就是不断加强这种分裂。","language":"中文","translation":false},{"id":"communism-abc-15-161","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":161,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"当然，不可能期望所有的“专家”都会忠于共产主义。如果以为这些同资产阶级有着千丝万缕联系的人会在短时间内改造过来，那是愚蠢的。但是在这里，无产阶级应该象一个能精打细算的老板那样行事，他需要这批人，他应该强迫这批人来为自己工作。","language":"中文","translation":false},{"id":"communism-abc-15-162","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":162,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"这里不得不采取这样的做法：给埋头工作的人以各种鼓励，不吝惜对他们的报酬——这是经济核算所要求的。但是对于反革命，对于反对无产阶级的斗争，对于背叛行为，对于怠工——那就要进行无情的镇压。无产阶级应该珍惜并学会珍惜真正忠实的工作者。但是它不能容许对它伤害，特别是现在，因为现在本来就在遭受着饥饿和千千万万的其它痛苦。","language":"中文","translation":false},{"id":"communism-abc-15-163","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":163,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"很清楚，必须要有严格的监督，特别是对过去的经理和资产阶级头面人物中的那些“专家”。这些人一再企图暗中破坏。在前线用来对付旧军官和将军的背叛行为的措施，在这里也同样是适用的。","language":"中文","translation":false},{"id":"communism-abc-15-164","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":164,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"另一方面，党必须与那些不正确的、过于简单化的观点进行斗争，这些观点认为，我们没有任何专家也完全可以过得去。这是蠢话。说这种话的人只能是那些极端自负而又不学无术的人，这些人从来不去认真考虑无产阶级现在所担负的任务。","language":"中文","translation":false},{"id":"communism-abc-15-165","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":165,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"无产阶级必须按照最新技术来组织当前的现代化生产。它必须努力做到这一点。当然，他需要造就、培养（而且已经在培养）一批自己的红色指挥员和技术员，就象它正在培养一批红色指挥员一样。但是时间不等人，这里只好利用现有的一切，同时采取措施来排除可能造成的危害，预防这种危害，并对那些异己分子的工作组织监督。","language":"中文","translation":false},{"id":"communism-abc-15-166","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":166,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"这里又产生了一个问题，即报酬的问题。共产主义力求报酬均等。但遗憾的是，我们不可能马上一步就跨进共产主义。我们还只是刚刚开始在向这个目标迈步。在这里我们应该遵循的仍然是简单的核算。","language":"中文","translation":false},{"id":"communism-abc-15-167","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":167,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"如果我们给这些“专家”以粗工的待遇，那对他们说来，作壮工、工程师、通信员和服务员都是无所谓的。要这些习惯于另一种生活的人好好工作，而又让他们处于这种环境，这是不明智的。最好是多给他们待遇，只是要能够出成果。在这里，无产阶级应该象一个机敏的老板那样：多给点钱。但回过头来可以使这些人好好工作，因为在当前没有他们我们还不行。","language":"中文","translation":false},{"id":"communism-abc-15-168","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":168,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"然而，十分清楚，我们的基本政策是要力求实行均等的报酬。在这方面苏维埃政权已经做了许多工作。过去高级职员（经理、总会计师、高级工程师-组织家、科学家、顾问等等）的报酬加上各种奖金要比粗工高几十倍；现在只高三倍。这就是说，从上述情况看，我们把这些阶级在待遇上的差别大大缩小了。","language":"中文","translation":false},{"id":"communism-abc-15-169","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":169,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"不同等级的工人之间的待遇也趋向拉平。根据施密特同志的材料，在1914年有百分之四点四三的工人日工资为五十戈比，但与此同时，也有日工资超过十卢布的工人（百分之零点零四）。由此可见，这里的工资的差别是，高工资是低工资的二十倍。当然，1914年领取日工资为十卢布的幸运儿是极少数，但毕竟还是有一些。1916年，日工资不到五十戈比的男工人占百分之零点五，而超过十卢布的为百分之一点一五。","language":"中文","translation":false},{"id":"communism-abc-15-170","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":170,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"现在，根据1919年秋天的决定，最低工资为一千二百卢布，最高工资为四千八百卢布，而后者涉及的只是“专家”。","language":"中文","translation":false},{"id":"communism-abc-15-171","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":171,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"苏维埃政权愈是巩固，一些技术知识分子便会愈快脱离 资产阶级而转到无产阶级方面来。而既然苏维埃政权的巩固是必不可免的，因而知识分子也必不可免地会象潮水般地涌来。不言而喻，把他们推开是没有道理的。相反，我们应该使他们在同志般协作的环境中为我们工作，使他们对我们的人熟悉起来，使他们在和我们共同的工作中改造成为我们的人。他们有许多偏见、成见和荒唐想法。但是在一定的条件下，他们能够和将会和我们协调一致。现在已经有一些人开始慢慢通过产业工会参加到我们的工作中来，对于新的环境逐渐习惯和熟悉起来，我们在这里的任务就是要帮助他们，接近那些愿意向我们靠拢的人。在产业工会里和通过产业工会，经过共同的组织工作，原先被资本主义分隔开的体力劳动者和脑力劳动者将重新接近起来。","language":"中文","translation":false},{"id":"communism-abc-15-172","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":172,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第一百零二节 生产与科学的结合","language":"中文","translation":false},{"id":"communism-abc-15-173","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":173,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"生产力的发展要求与科学相结合。资本主义大生产也曾大规模地把科学运用于生产。美国和德国的工厂都附设有专门的实验室：人们整天整天地坐在那里研究，发明各种各样的新方法、新仪器等等。所有这一切都是为了给私人资本家增加利润。现在我们应该从整个劳动社会的利益出发有组织地进行这一工作。过去发明家的发明都是保密的，所有这些东西都装进了企业主的口袋，供他们发财；现在我们的企业发明不会相互隐瞒了，而且会被推广到所有企业。","language":"中文","translation":false},{"id":"communism-abc-15-174","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":174,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"苏维埃政权在这方面采取了一系列的措施：建立了一系列科学技术和经济机构，组织了各种实验室和试验站；进行了许多科学调查与考察（明确提一下，已经发现了一些油叶岩矿和石油；发明了从锯末中提炼糖的方法等等。）；查清了共和国现有的科学力量并给他们安排了工作。","language":"中文","translation":false},{"id":"communism-abc-15-175","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":175,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"在这一工作中，从燃料到精密的科学仪器，我们还缺乏许多最必要的东西。但是我们必须清楚地认识到，这一工作是必需的，应当全力支持科学和同生产组织的进一步结合。共产主义就是正确地、合理的、因而也是科学地组织生产。因此我们必须用一切办法来解决科学组织生产的任务。","language":"中文","translation":false},{"id":"communism-abc-15-176","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十二章 工业组织","page":15,"paragraph":176,"url":"https://www.marxists.org/chinese/bukharin/1919/14.htm","text":"第十二章书目：恩·奥新斯基《社会主义建设》。弗·巴·米柳亭《经济发展与无产阶级专政》和1919年在《国民经济》杂志上发表的文章，第八次党代表大会的记录（对纲领的讨论），《资本主义的瓦解和共产主义建设》。伊·斯切潘诺夫《从工人监督到工人管理》。国民经济委员会第一次和第二次全俄代表大会档汇编。格·策彼罗维奇《辛迪加和托拉斯》。米·托姆斯基《俄国工会运动概论》，《共产国际》杂志上的论文，工会代表大会档汇编，《五金工人公报》上的文章。阿·哥尔茨曼《劳动定额》。列宁《伟大的创举》。","language":"中文","translation":false},{"id":"communism-abc-16-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-16-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百零三 节 俄国革命前的土地关系","language":"中文","translation":false},{"id":"communism-abc-16-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百零四 节 俄国革命后的土地关系","language":"中文","translation":false},{"id":"communism-abc-16-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百零五 节 为什么未来属于社会主义大经济","language":"中文","translation":false},{"id":"communism-abc-16-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百零六 节 国营农场","language":"中文","translation":false},{"id":"communism-abc-16-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百零七 节 城市农业","language":"中文","translation":false},{"id":"communism-abc-16-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百零八 节 公社与劳动组合","language":"中文","translation":false},{"id":"communism-abc-16-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百零九 节 土地共耕社","language":"中文","translation":false},{"id":"communism-abc-16-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第 一百一十 节 农业合作社","language":"中文","translation":false},{"id":"communism-abc-16-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第一百一十一节 国家耕种空闲土地，动员农业技术力量，","language":"中文","translation":false},{"id":"communism-abc-16-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第一百一十二节 帮助农民经济","language":"中文","translation":false},{"id":"communism-abc-16-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第一百一十三节 工业与农业的结合","language":"中文","translation":false},{"id":"communism-abc-16-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"· 第一百一十四节 共产党对待农民的策略","language":"中文","translation":false},{"id":"communism-abc-16-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百零三节 俄国革命前的土地关系","language":"中文","translation":false},{"id":"communism-abc-16-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"革命前，我国的农业主要是农民经济。十月革命以后，即在消灭了地主土地所有制后，我国的农业变成了几乎清一色的农民经济和几乎清一色的小经济。在这种条件下，共产党在为建立大集体经济而斗争的事业中必须克服极大的困难。但是这一斗争甚至在最困难的时期，即在最初时期就开始了，并已取得了某些成果。","language":"中文","translation":false},{"id":"communism-abc-16-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"为了弄清共产党人在俄国农村实现自己的纲领所处的环境和条件，这里列举一些材料来说明革命前我国的农业情况和革命给农业带来的变化情况。","language":"中文","translation":false},{"id":"communism-abc-16-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"革命前俄国欧洲部分的土地占有情况是这样的：","language":"中文","translation":false},{"id":"communism-abc-16-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"官地……………………………………………………138 086 168俄亩","language":"中文","translation":false},{"id":"communism-abc-16-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"农民的份地……………………………………………138 767 587俄亩","language":"中文","translation":false},{"id":"communism-abc-16-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"私产和公产……………………………………………118 338 688俄亩","language":"中文","translation":false},{"id":"communism-abc-16-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"几乎所有的官地都是林地或现在不宜耕作的土地。至于私产和公产，具体情况是这样的：","language":"中文","translation":false},{"id":"communism-abc-16-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"地主土地………………………………………………101 735 343俄亩","language":"中文","translation":false},{"id":"communism-abc-16-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"皇族土地…………………………………………………7 843 115俄亩","language":"中文","translation":false},{"id":"communism-abc-16-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"教堂土地…………………………………………………1 871 858俄亩","language":"中文","translation":false},{"id":"communism-abc-16-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"寺院土地……………………………………………………733 777俄亩","language":"中文","translation":false},{"id":"communism-abc-16-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"城市占用土地……………………………………………2 042 570俄亩","language":"中文","translation":false},{"id":"communism-abc-16-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"哥萨克军占用土地………………………………………3 459 240俄亩","language":"中文","translation":false},{"id":"communism-abc-16-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"其他土地……………………………………………………646 885俄亩","language":"中文","translation":false},{"id":"communism-abc-16-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"至于份地，根据1905年的统计，这些份地分配给了一千二百二十七万七千三百五十五户农民，即每户平均占地十一点三七俄亩。然而这仅仅是一个平均数，边疆区占的份地比较多（但不适于耕种），这就掩盖了中央省份多数农民地少的现象。实际上在过去构成我国农民多数的地主的农民，每户所占的平均份地为六点七俄亩。在某些省和县里，这个数字甚至还要低一半。到1916年，农户数目超过了一千五百万户（15492202户），而农民的土地使用面积却增加得很少。少地的农民大大增加了。","language":"中文","translation":false},{"id":"communism-abc-16-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"由于官地只有很少一部分适于耕种，农民要扩大自己使用面积就只能依靠占用上面所提到的“私产和公产”。","language":"中文","translation":false},{"id":"communism-abc-16-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在私产中，首先应该剥夺的是占据着五千三百一十六万九千〇八俄亩土地的地主、商人和富裕农民，以及资产阶级-富农类型的村社和协作社。占有二十俄亩以上土地的私人土地占有者总共拥有八千二百八十四万一千四百十三俄亩土地，协作社占有的土地为一千五百七十八万八千六百七十七俄亩。这就是农民革命首先应该打击的方向。至于说到公产，那首先应该将教堂、寺院和部分皇族土地分给农民。","language":"中文","translation":false},{"id":"communism-abc-16-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百零四节 俄国革命后的土地关系","language":"中文","translation":false},{"id":"communism-abc-16-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"革命前私人，首先是地主占有的土地有相当大的一部分都抵押出去。抵押出去的土地共计有六千万俄亩以上，折价三十四亿九千七百八十九万四千六百卢布。换句话说，地主土地的真正主人是俄国和外国的银行。正是由于这一点，以社会革命党为首的各妥协派政党一方面声撕力竭地叫嚷要将所有的土地无偿地交给农民，而在另一方面，当事情真正要兑现时，他们却又畏缩不前，把没收土地的事束之高阁。除了进行殊死的战争之外，共产党（布尔什维克）同资本没有任何瓜葛，只有共产党才能与妥协派抗衡，把旨在反对地主的农民革命支持到底。第二次苏维埃代表大会通过的和由共产党提出的土地法令使这一革命具有了法律效力。","language":"中文","translation":false},{"id":"communism-abc-16-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"根据这一法令和第三次代表大会通过的基本土地法，土地私有制宣布废除；共和国的全部土地都属于一切愿意用自己的劳动来耕种的人（土地的使用既不受民族，也不受国籍的限制）。土地以不超过劳动标准数量为限，按现有人口平均分配。后来，根据社会主义土地规划条例，宣布共和国的全部土地归整个工农国家所有，国家拥有土地的最高支配权。","language":"中文","translation":false},{"id":"communism-abc-16-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"由于这场以法律形式固定下来的土地革命，俄国的土地关系经历了根本的改革，直到现在还在继续不断地发生变化。","language":"中文","translation":false},{"id":"communism-abc-16-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"首先在整个大俄罗斯广阔的土地上完全废除了地主的和所有大的和中等的土地私有制。富农的土地已与中农拉平。","language":"中文","translation":false},{"id":"communism-abc-16-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"另一方面，贫农和土地最少的农民从富农和被毁坏的庄园那里得到了牲畜和农具，他们的土地使用面积已达到个人份地的平均水准。","language":"中文","translation":false},{"id":"communism-abc-16-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"至于各乡、县和省的份地拉平问题，这个问题还远没有完成，而且还要拖很长时间才能完成。","language":"中文","translation":false},{"id":"communism-abc-16-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"现在还不能对土地关系的革命进行总结，但是总的说来情况是这样的。几乎所有大的和中等的私人占有的耕地都已交给农民使用。","language":"中文","translation":false},{"id":"communism-abc-16-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"地主的土地都已得到耕种。苏维埃政权在自己手中仅仅保持着近二百万俄亩国营农场土地。农民还耕种了部分城市土地。所有教会、寺院的土地和部分皇族土地都转到农民手中。总的来说，有将近四千万俄亩的私人土地已归农民支配。","language":"中文","translation":false},{"id":"communism-abc-16-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"属于苏维埃国家支配的，除了国营农场和制糖厂的土地以外，还有几乎全部过去的官地和已收归国有的私人林场。","language":"中文","translation":false},{"id":"communism-abc-16-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"可见俄国共产党不得不在极不利的条件下为争取农业中的社会主义而奋斗。实际上归国家支配的大多数土地不适于耕种，国内大多数适于耕种的土地都掌握在独立的小农经济手中。","language":"中文","translation":false},{"id":"communism-abc-16-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"但是，尽管在俄国农业的社会主义化的条件很不利，尽管小资产阶级经济的抵抗很顽强，在农民的俄国，未来只能属于社会主义的大经济。","language":"中文","translation":false},{"id":"communism-abc-16-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百零五节 为什么未来属于社会主义大经济","language":"中文","translation":false},{"id":"communism-abc-16-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"资本主义大经济挤垮了小手工业和小农经济，而且的确，这种情况在工业比在农业发展更快、更明显。共产主义经济比资本主义经济更优越，更有成效。至于说比起小农经济，就更不在话下。如果说一俄磅比一所洛特尼克重，那么一普特又比一俄磅重，而一普特就要比一所洛特尼克更重。","language":"中文","translation":false},{"id":"communism-abc-16-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"现在必须以最一目了然的形式来证明所有这一切。","language":"中文","translation":false},{"id":"communism-abc-16-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"首先，在社会主义的农业中，对共和国的全部土地都应该加以划分，以便在各区、州和每块土地上根据土质的情况和特点，种植当地最适于生长的谷物、蔬菜和经济作物（亚麻、大麻、甜菜、向日葵等等）。这个问题应该由农业科学来确定。在我们的农民经济中经常却与此相反：在亚麻可以长得很好的地方去播种粮食，在可以种植小麦的地方却去种植黑麦，诸如此类的事屡屡出现。","language":"中文","translation":false},{"id":"communism-abc-16-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"即使在其他方面工作按老的方式进行，但只要在所有耕地面积的规划上都能实行总的科学计划，土地的生产量也还是可以提高的。","language":"中文","translation":false},{"id":"communism-abc-16-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"只有在中等和大型农场（大型农场比中等农场更容易）才能实行多区轮作制。实行作物轮作制的土地能得到巨大的收益。而我国农民由于实行三区轮作，每年都会将近三分之一的土地空闲起来。","language":"中文","translation":false},{"id":"communism-abc-16-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"农民都是单干户（土地很少），尤其在村社，土地都被分成块。在这样的情况下，要实行正确的作物轮作制和多区轮作制是不可能的。","language":"中文","translation":false},{"id":"communism-abc-16-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在大农场里，土地不会白白浪费在地段小路或地界上，相反，在整个俄国，我们的农民光是在地界这一项上每所就丢掉了几十万俄亩的土地……我们计算了一下，我国农民光是在这一项上每年就要丢掉六千万至八千万普特的粮食。","language":"中文","translation":false},{"id":"communism-abc-16-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"保持土壤肥力的主要源泉是肥料。大农场能够喂养较多的牛羊（即使马匹少一些也无妨），因而能够得到较多的粪肥。大农场在购买化肥上条件更有利，或者说他们自己也能制造某些种类的化肥。这对小农经济来说就很难做到。","language":"中文","translation":false},{"id":"communism-abc-16-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"要做到不误农时、深耕和尽可能地少花钱（即劳动消耗最少），是最不容易办到的。在这方面，小农经济比起社会主义大经济（甚至比起资本主义大经济）来就更无能为力。要花钱少、速度快和耕得深，就要使用拖拉机。但拖拉机是无法在农民的小块土地上工作的。而且使用单个的拖拉机比起一次使用八至十部拖拉机同时耕作就更不合算。","language":"中文","translation":false},{"id":"communism-abc-16-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在使用其他大型的，因而也是最节省劳动的机器方面，情况也是如此。只有大农场才能使用蒸汽脱粒机和蒸汽收割机。","language":"中文","translation":false},{"id":"communism-abc-16-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"最后，也只有在大农场中才能使农具得到最充分的利用。","language":"中文","translation":false},{"id":"communism-abc-16-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"例如，农具的充分利用情况为：","language":"中文","translation":false},{"id":"communism-abc-16-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"一部马拉犁可以耕种二十七俄亩地；","language":"中文","translation":false},{"id":"communism-abc-16-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"一部普通的播种机、收割机、脱粒机可以对付六十三俄亩土地；","language":"中文","translation":false},{"id":"communism-abc-16-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"一部蒸汽脱粒机可以为二百二十五俄亩土地的庄稼脱粒；","language":"中文","translation":false},{"id":"communism-abc-16-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"一部蒸汽犁可以耕九百俄亩地。","language":"中文","translation":false},{"id":"communism-abc-16-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"同时，在其他条件相同的情况下，光是应用蒸汽犁和拖拉机这一项就能使土地的收获量增加三分之一。","language":"中文","translation":false},{"id":"communism-abc-16-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"如果需要使用马来耕种，那么，在这里优势也是在大农场一边，因为在大农场里，每一匹马能耕作更大量的土地。椐计算，在大农场里耕作同样数量的土地需要的马少二分之一到三分之二。","language":"中文","translation":false},{"id":"communism-abc-16-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"只有大农场才能利用电。其次，几个大马厩和牛棚就可顶替一百个简陋的小马厩和小牛棚，一个大的厨房就可以顶替一百个简陋的小厨房，等等。","language":"中文","translation":false},{"id":"communism-abc-16-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"只有在大农场中，牲畜单栏饲养业才是最有利的。","language":"中文","translation":false},{"id":"communism-abc-16-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"但是最重要的节约是劳动力的节约，人们有可能减少二分之一至三分之二的农业劳动时间，而且不仅不降低，反而能提高土地的生产量二至三倍。例如：","language":"中文","translation":false},{"id":"communism-abc-16-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"根据1916年的最新统计，俄国全部播种面积为七千一百四十三万零八百俄亩。如果我们假设，所有这些土地一年翻耕一次（事实上每个农民都知道，这是不可能的），那么为了翻耕这些土地，农民必须动员全部劳力，即两千万人和全部耕畜。如果用拖拉机翻耕这些土地（拖拉机每天可耕地八至十俄亩，如果不间断地工作，那就更多）。那只要有一百万个劳动力就足够了。","language":"中文","translation":false},{"id":"communism-abc-16-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"比原来节约了百分之九十五[1]。","language":"中文","translation":false},{"id":"communism-abc-16-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"如果每一个单独的小厨房只能做出一百份午餐，那么改用一个大的公共农村食堂就可以做更大量的午餐，这样，一百名做饭的妇女就可以腾出九十名去做更为有益的工作，从而也就业减轻了其他人的劳动……","language":"中文","translation":false},{"id":"communism-abc-16-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"因此，共产党的任务就是要尽一切力量争取最完美的东西，即争取农业中的共产主义经济，因为共产主义经济可以使农村把小经济造成的人力物力的野蛮浪费，把它在土质上造成的野蛮破坏，把野蛮的亚细亚式的畜牧业，把野蛮的家庭厨房，统统排除掉。","language":"中文","translation":false},{"id":"communism-abc-16-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"共产党准备通过一些什么样的办法来达到这一伟大目的呢？办法有好几种。我们先从收效最快的办法谈起。","language":"中文","translation":false},{"id":"communism-abc-16-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"1917年农民夺取地主土地时，很多先进庄园都被毁坏了。本来这些庄园经营很出色，它们拥有经过挑选的良种牲畜和复杂的农业机器。但是也有一部分庄园由于苏维埃及时想到要予以保护而被挽救下来。这些受到苏维埃关照的庄园就获得了国营农场的称号。此外，还有一些庄园由于农民已经根据国营农场的标准得到了足够的份地，其土地不宜再完全分配给农民，所以这些庄园的土地也被划入了国营农场。","language":"中文","translation":false},{"id":"communism-abc-16-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"国营农场——这是建立典型的、具有许多优越性的社会主义大经济的唯一可能的源泉。只有通过国营农场，我们才能在事实上向农民证明大型集体化农业的全部优越性。","language":"中文","translation":false},{"id":"communism-abc-16-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在国营农场我们能实行正确的轮作制，并通过实践来证明三区轮作的缺点。","language":"中文","translation":false},{"id":"communism-abc-16-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"国营农场是唯一能够保护和繁殖良种牲畜的地点。我们只有通过国营农场的牲畜交配站才能逐步改善周围农民的牲畜的品种。","language":"中文","translation":false},{"id":"communism-abc-16-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在国营农场中最便于为农民建立示范田，并通过选种来改良种子。现在选取种机已经开始不仅为国营农场本身，而且也为周围的农民挑选谷物良种。","language":"中文","translation":false},{"id":"communism-abc-16-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在国营农场里办起了农业学校，经常举办农艺学讲座、农业展览等等。","language":"中文","translation":false},{"id":"communism-abc-16-77","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":77,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在国营农场，我们使用所有的农业机器，直至最复杂的机器。","language":"中文","translation":false},{"id":"communism-abc-16-78","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":78,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在国营农场建立了农具修配厂，最初这些厂只为农场本身的需要服务，后来的服务又扩大到周围的农村。","language":"中文","translation":false},{"id":"communism-abc-16-79","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":79,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"共产党的任务是，在一切有可能的地方，增加国营农场的数目及其土地的面积（尽可能不触犯农民经济的利益）。逐步把共和国内所有最珍贵的良种牲畜都收集到国营农场里来。要以最好的方法来进行农产品的技术加工。要消除官僚主义和经营不善的情况，因为有些国营农场已变成了地主的寺院，只为本单位的职工服务，不为苏维埃国家作任何贡献。要挑选出一批熟练工人队伍，这批工人要不仅能实行工人监督，而且能逐步转入实行工人管理，要使周围的所有农民都关心国营农场，吸收他们参加讨论国营农场的经济计划，并使他们把国营农场看成了是国家全体劳动居民的事业。到1919年秋天为止，国营农场的数目已达到三千五百三十六个，拥有二百一十七万俄亩适于耕种的土地（不带森林）。","language":"中文","translation":false},{"id":"communism-abc-16-80","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":80,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"可怕的粮食危机是战争和革命的自然后果，正确地安排城市的农业对于使城市无产阶级免于饿死有着巨大的意义。这种农业已开始组织起来并具有远大的前途。城市农业当前最迫切的任务是保证每个城市有足够的土地，以便顺利地建设大农场。革命前我们的城市拥有二百多万俄亩土地。这些土地有的用来建了房屋，有的用来作为牧场、公园或菜园，这些土地至今大部分仍归城市所有。但是其中有一部分或耕地现已归了农民。必须把这部分土地还给城市，不仅如此，而且必须没收城市周围的所有土地，因为这对于建立合理的和大规模的经济是必不可少的。","language":"中文","translation":false},{"id":"communism-abc-16-81","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":81,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"某些城市的苏维埃土地局还在1919年就已经把种菜的工作承担起来，并且收获了足够供应城市工人居民一年所需要的蔬菜。必须沿着这条道路走下去。必须使每一个城市拥有足够数量的菜地，以满足全体市民的蔬菜需要。必须使每一个城市都能拥有一个至少能为所有的病人和儿童提供所需牛奶的大牧场，并且还要有足够的饲料地。今后如果能把城市农业办好，就不仅能供应工人以土豆和白菜，而且还可以供给他们一些粮食（乔麦、黍子）。可以用自己的饲料来喂养所有城市的马匹，这样就能更顺利地实行运载行业的国有化。经验证明，上述纲领（因为它并没有妄想把所有城市居民的粮食供应都包下来）再用一年时间，除各共和国的首都以外，实际上在所有城市里都是可以实现的。","language":"中文","translation":false},{"id":"communism-abc-16-82","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":82,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"此外，城市国营农场还有两个方面的巨大意义。首先，它能使城市以垃圾、废物和粪便的形式提供的肥料得到最充分的利用。现在这种肥料的大部分都被白白丢掉。其次，它可以把工业和农业结合起来。最近几年，一部分城市居民可以参加农业工作，这并不会给工业造成损害，而且这一工作仅仅是在大城市的农业土地上进行的。","language":"中文","translation":false},{"id":"communism-abc-16-83","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":83,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"国营农场和城市农业不仅应该起示范农场的作用，而且应该对粮食危机的缓和产生最积极的影响。经验证明，在收获前的最紧张时刻，即当农民尚未开始或刚刚开始打谷时，是国营农场为粮食机构救了急。1918年和1919年新收成的第一批粮食都是来自国营农场。国营农场的这种作用今后还应该进一步加强。只要把国营农场的全部土地都利用起来，苏维埃共和国就可以得到将近半数的城市工人和职员所必需的粮食，从而大大减少自己对农民经济的依赖性。","language":"中文","translation":false},{"id":"communism-abc-16-84","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":84,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百零八节 公社与劳动组合","language":"中文","translation":false},{"id":"communism-abc-16-85","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":85,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"国营农场要想得到进一步的发展，只能依靠郊区现有的空地，或者依靠经过改造（即改造土壤，清除障碍，排水等等）才能用于耕种的官地。至于我国整个农业，那只有当农民经济开始走上社会主义化的道路时，农业才会变为社会主义的农业。在国营农场里农民将体会到集体经济的好处。他们只有联合成为公社或劳动组合才能得到这种好处。在资本主义社会里，小农经济向大经济的过渡通常是靠小私有者的破产和无产阶级化来实现的。在社会主义社会，首先是要通过把许许多多的小经济联合起来的办法，才能从小经济中产生出社会大经济。","language":"中文","translation":false},{"id":"communism-abc-16-86","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":86,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在农民中间，“劳动组合”与“公社”这两个词通常有着同样的意义。有许多公社被称为劳动组合，因为农民不喜欢公社这个名称，甚至在实践中公社已经建立起来的情况下他们也害怕使用这个名称。通常劳动组合与公社的区别在于，劳动组合仅仅是生产的联合（劳动中的协作），而公社则不仅是生产的，而且是消费的联合（即不仅在劳动方面协作，而且也在分配和消费方面协作）。","language":"中文","translation":false},{"id":"communism-abc-16-87","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":87,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在苏维埃俄国，公社和劳动组合的数量迅速增长。下面就是到1919年秋季为止的这方面的最新材料：","language":"中文","translation":false},{"id":"communism-abc-16-88","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":88,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"数量 适于耕种的土地面积 公社 1991 约15万俄亩 劳动组合 3698 约48万俄亩 土地共耕社 658","language":"中文","translation":false},{"id":"communism-abc-16-89","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":89,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"以上数字表明，成立公社与劳动组合的运动带有群众性，而且在不断发展扩大。但是这些数字也表明了这种联合形式的不足的一面。首先，公社的平均规模不大。我们看到的不是由小经济向大经济的过渡，而是向中等的和甚至是向低于中等的经济的过渡。因此，公社无法向自己的成员以及所有周围的居民证明大经济的一切好处。在只有几俄亩大的土地面积上不是所有的机器都能充分有利地得到利用，也不总是都能实行作物轮作。然而，即使联合成为中等经济所取得的成就也都有着巨大的意义。劳动分工的长处得到发挥，部分妇女从厨房劳动中解放出来有助于更快地完成所有的农活，有可能以较少的马匹来完成任务，所有的农活都能及时结束，土地耕种得更好，因此产量也比农民的小块土地高。","language":"中文","translation":false},{"id":"communism-abc-16-90","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":90,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"公社对劳动力的节约也在另一点上表现出来，即大部分公社已开始从事一系列非农业性质的劳动：建筑磨坊，开设手工业作坊，修理工场以及其他等等。","language":"中文","translation":false},{"id":"communism-abc-16-91","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":91,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"公社沿着社会主义道路前进的下一步骤只能是更进一步的联合。","language":"中文","translation":false},{"id":"communism-abc-16-92","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":92,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"要做到这一点，可以把两个相邻的公社合并起来，或者由公社从邻近农民协作组织那里接受几十户新成员，或者把一个或几个公社合并到邻近的国营农场去。","language":"中文","translation":false},{"id":"communism-abc-16-93","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":93,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"当前共产党在农村最重要的任务是要使所有的小农经济进入更高的阶段，首先是进入中等公社经济的阶段。可以有充分的根据作这样的设想，未来农村的生产力将主要是沿着这条道路发展。无产阶级国家不仅可以通过有计划的理论上和实践（国营农场）上的宣传，而且可以通过向正在成长的公社经济提供一切物质便利的办法（财政上的援助，种子、牲畜和农具的供应，农业技术指导）来加速这一过程。","language":"中文","translation":false},{"id":"communism-abc-16-94","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":94,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百零九节 土地共耕社","language":"中文","translation":false},{"id":"communism-abc-16-95","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":95,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"公社不仅是农民在劳动方面的联合组织，而且也是他们在分配和共同友好生活方面的最紧密的联合组织。劳动组合仅仅是在劳动方面的经常性联合组织，而土地的共耕社，这是比劳动组合更为松散的、更为随便的联合组织，也可以说它是一种临时性的组织。有的农村由于内部意见不一致，建立不起公社，由于同样的原因，也建立不起劳动组合，然而他们却能够做到土地共耕，尽管其成员彼此在其他方面没有任何联系。结果是一切照旧，但有一个非常重要的情况除外，即公共的土地不会被分成碎块，而是由村社来进行耕作。家家户户都有菜园，每户农民的全部财产都保留下来。只有机器和马匹要在一定的时间供全村使用。","language":"中文","translation":false},{"id":"communism-abc-16-96","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":96,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"中央执行委员会通过的社会主义土地规划条例已对集体经济最初阶段的这种情况有所说明。这种联合形式的好处是，每个农民除了劳动过程之外，在所有方面都保留有充分的行动自由，因而能比较容易地加入这种联合，而不会有失去自己的独立性的危险。共耕社已经显示了大量的优越性：消灭了耕地交错的现象，有可能实行多区轮作制，能充分地使用农具，在工作中实行分工，能对缺乏人力、农具和牲畜的家庭进行帮助，等等。","language":"中文","translation":false},{"id":"communism-abc-16-97","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":97,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"可以预料，土地共耕社这一集体经济的初级阶段，将在我国农村得到最广泛的发展。现有的材料说明，在1919年的农忙季节，这种耕作形式已经在一系列地区普及开来。一些大的村庄分成了几十个小的单位，实行土地共耕。有的时候，对部分公共的土地也用这种方式来耕作。","language":"中文","translation":false},{"id":"communism-abc-16-98","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":98,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百一十节 农业合作社","language":"中文","translation":false},{"id":"communism-abc-16-99","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":99,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"农民中加工各种不同的农产品的合作社还在革命以前就得到了广泛的发展。这里包括制造乾酪和奶制品的劳动组合，这种组织非常普遍，主要是在北方各省和伏尔加河上游非产粮地区。另外还有亚麻初加工、生产糖浆、干菜、压缩干草等等的劳动组合协作社。苏维埃政权对所有这些联合组织给予各种支持。共产党的任务是，鼓励农村的劳动阶层去组织这类合作社，扩大它们的规模，改善加工的方法，同时要同小资本暗自在劳动组合中抵制苏维埃政权和社会主义大经济的各种企图进行斗争。","language":"中文","translation":false},{"id":"communism-abc-16-100","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":100,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百一十一节 国家耕种空闲土地，","language":"中文","translation":false},{"id":"communism-abc-16-101","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":101,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"动员农业技术力量，租赁站，土壤改良，移民","language":"中文","translation":false},{"id":"communism-abc-16-102","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":102,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"由于战争造成的农业上的巨大破坏，经常使得有很大一部分土地得不到耕种。在城市和非产粮区粮食严重危机的情况下，无产阶级国家不能对土地的荒废漠不关心。因此苏维埃国家把耕种荒地的任务担负起来，不管这些土地原来是属于谁的。这一措施特别在那些国内战争打得最厉害的地区具有更有巨大的意义，因为在这里农村所有的富农往往扔下自己的土地随敌跑掉。另外国家还收割了被原主人抛弃或原主本身无力进行收割的庄稼，这一点也同样具有很大的意义。","language":"中文","translation":false},{"id":"communism-abc-16-103","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":103,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"只采取一系列彻底的和革命性的措施才能治理好完全遭到破坏的俄国农业。措施之一就是要动员农业技术力量，即宣布所有农学家进入现役军人的状态。俄国的农学家一向就很少。现在，由于我国面临着改造农业和提高农业生产力的巨大工作，农业技术力量就越感到不足。动员农业技术力量，这实质上就是使科学知识社会主义化，让国家更合理地来使用这些知识。","language":"中文","translation":false},{"id":"communism-abc-16-104","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":104,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"帝国主义战争使俄国没有可能从国外获得农业机器。我国的农业机器制造业一向不能满足国内的需求，许多机器包括几乎所有最贵重和最复杂的机器，我们往往是从德国、瑞典和美国进口的。同时，由于金属和燃料不足以及许多其他原因，我国机器制造厂的生产缩减到了最低限度。所有这一切就造成了农具的严重不足。一方面大量需要机器，另一方面无产阶级国家所拥有的机器储备又极少，在这种情况下，正确地分配和充分地使用农具，便具有巨大的意义。而在农具私有的情况下要做到这一点是不可能的，因为有的时候机器会在其所有者那里闲置不用，而与此同时，邻居们却又没有机器用来耕种或收割。","language":"中文","translation":false},{"id":"communism-abc-16-105","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":105,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"为了帮助农村中急需农具的阶层，为了使农具得到充分利用，必须使农具不为私人所有，应当通过租赁站把机器租给需要机器的农民使用，换句话说，就是要为农民指定一些农民具，并按一定的地区（村、乡、区）进行分配，不是出售给个别的农民，而是放在库房里，通过库房把农具提供给所有需要农具的人短期使用，并收一定数量的补偿费。这样的库房就称为租赁站。在那里农具得到保管，工作完了以后被收拾得井然有序，在组织良好的赁站里农具还能得到修理。租赁站现在已经出现并已开始工作，尽管数量还不多。苏维埃政权的任务应该是使指定给农村使用的全部农业机器，特别是所有复杂的机器，都尽可能地放到租赁站里去。这样就能保证农具在机器的整个工作阶段得到充分利用，更不用说还能帮助那些没有钱为自己购买机器的贫苦农民。应当把从富农那里没收来的农具都放到租赁站里去。归根结底，有了租赁站这一供应农具的广泛系统，就可以逐步地和准确地导致到最重要的农业生产工具的国有化，因而它不仅能给予农民经济以直接帮助，而且能促进农民经济的社会化。在俄国无产阶级政权的土地纲领中，土壤改良被放在非常重要的地位。苏维埃政权拥有几百万俄亩的土地，这些土地现在还不宜于耕种，但是只要稍加清理，把树根挖掉，把水排净，把水渠挖好（通过地下管道和沟渠排水），把人工灌溉等等搞好，这些土地就能变为良田。国营农场在现有或过去的耕地面积上扩大自己的面积是很有限的，但是我们年青的社会主义农业通过土壤改良的办法向大自然夺得的土地面积将是无限的。","language":"中文","translation":false},{"id":"communism-abc-16-106","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":106,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"改良土壤的工作是苏维埃政权所面临的一项最重要的社会工程，在这一工作中，首先应该利用社会上所有的寄生阶层。","language":"中文","translation":false},{"id":"communism-abc-16-107","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":107,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"移民政策。在我们的纲领里这一点没有写上，但是应该谈谈这一点，因为苏维埃政权迟早需要在实际中解决应该采取什么样的移民政策的问题。","language":"中文","translation":false},{"id":"communism-abc-16-108","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":108,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"尽管分了地主的土地，在一些省份现在仍然十分尖锐地感到土地不足。与此同时，在我们的边远地区还存在着大量的空闲土地。在不久的未来，将不可避免地要把人口从中央地区向边远地区转移。那时无产阶级国家的任务将不是为新地区的移民划分单独的地段进行小农经济，而是为他们准备共产主义大经济所必须的一切（公共建筑，计划用来进行多区轮作制经济所需要的公共的土地面积，复杂的机器，等等）。","language":"中文","translation":false},{"id":"communism-abc-16-109","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":109,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百一十二节 帮助农民经济","language":"中文","translation":false},{"id":"communism-abc-16-110","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":110,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"国营农场、公社和劳动组合以及上述的措施都能通过组织集体大经济的办法来提高农业劳动生产率和土地的收成。这条道路是直接通向目的地的一条唯一正确的捷径。但是无论我们在组织国营农场和公社方面取得多么大的成就，小农经济仍将长期存在，并且在相当长的时期内，无论在耕地面积方面还是在产量方面，都将是俄国农业的主要形式。这里产生的问题是如何帮助农民经济提高土地的生产量的问题，尽管它还要继续原封不动地保持着自己身上那层小资产阶级外壳。","language":"中文","translation":false},{"id":"communism-abc-16-111","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":111,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"我们的纲领拟定了一系列苏维埃政权能够实行的目的在于帮助农民经济的措施。下面就是这样的一些措施。","language":"中文","translation":false},{"id":"communism-abc-16-112","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":112,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"首先是帮助划分地段。现在我国农村中农民本身愈来愈不能忍受的主要灾难是，耕地交错和地块狭长。常常是一个村的土地紧靠着另一个村的菜园，或者相反，有的地段距离村子七至十俄里远，常常得到不到耕种。为了消除耕地交错和地块过长的现象，农民常常自发地要求搬家，力图改变这种已经过时的人口分布状况，因为在分配了地主的土地之后，这种状况已多半不适应新的土地分配情况了。既然要求迁居是同耕地交错和地块过长的现象进行斗争的一种形式，是进行文明经济的一个前提，既然农民在划分地段方面普遍需要帮助，那么苏维埃政权就应该派自己的土地测量和农业技术力量去帮助他们。","language":"中文","translation":false},{"id":"communism-abc-16-113","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":113,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"俄国农民播在地里的种子同他们送去磨粉的种子多半是一样的。然而在其他条件相同的情况下，如果播下的是经过挑选的种子，那么收成就会高得多。如果播下的是良种，收成就会更高。农民只有通过国家才能得到这种种子，因为只有国家才能从在国外购买的良种中或从保存在国营农场的少量良种储备中抽出一部分给农民。","language":"中文","translation":false},{"id":"communism-abc-16-114","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":114,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"农民的牲畜已经大大退化了。必须改良农民牲畜的品种。但是所有俄国仅存的良种牲畜现在都集中在国营农场和国营牧场里，或者属于国营畜牧业机构的财产。应当在每一个拥有良种牲畜的国营农场建立牲畜交配站，并给每一个区的牲畜交配站分配种畜，这样国家就能给已经衰落的农民畜牧业以极大的帮助。","language":"中文","translation":false},{"id":"communism-abc-16-115","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":115,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"我国绝大多数农民对一系列的最基本的和非常重要的农艺知识都缺乏了解。在这种情况下，传播农艺知识本身对于改善土地的耕作就一定会有很大的促进作用。要作到这点，可以组织苏维埃苏维埃的农学家在各区段的农学点上搞一些农艺讲座、短训班、示范田、农业展览会，出版一些通俗的农艺学书籍等等。","language":"中文","translation":false},{"id":"communism-abc-16-116","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":116,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"除了传播农艺学知识以外，苏维埃政权还应给予农民以直接的农艺学方面的帮助。虽然我国农学家非常缺乏，但是对农学家的动员已经收到了很好的效果，也就是说，过去几乎仅仅为地主经济服务的农学家，现在已经在为农民造福了。除此之外，苏维埃政权必须从农民当中大量培养农业人才。除了增加农业学习班和农业学校的数目之外，在目前最简便易行的办法是从公社和劳动组合中抽调一些最有才干的人进行专门培训，这样一来，这些人就会成为农民当中具有农学知识的先进阶层。","language":"中文","translation":false},{"id":"communism-abc-16-117","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":117,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"当前对于农民来说很重要的一点是要能够修理使用坏了的农具。在目前钢铁缺乏的情况下，任何小私人手工业作坊都担负不起所有必需的修理任务。只有国家才能以相应的规模组织这一工作，办法就是扩大国营农场的修配厂，有计划地建立为农民修理服务的作坊网。","language":"中文","translation":false},{"id":"communism-abc-16-118","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":118,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"农民有几百万俄亩的土地不适宜于耕种，但是要把这些土地改造成为适于耕种的土地是完全可能的。这一点之所以未能办到，一方面是因为这类工作常常不是一个村的力量所能办到的，另一方面，是因为农民不懂得改良土壤的方法。无产阶级国家如果能在这一方面给农民以帮助，那是特别重要的，而国家已经在这样做，尽管在许多地方国内战争还在继续。","language":"中文","translation":false},{"id":"communism-abc-16-119","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":119,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"从1901年到1910年每一俄亩土地的平均收获量如下：","language":"中文","translation":false},{"id":"communism-abc-16-120","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":120,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"由此可见，尽管俄国的土质比西方好，但是我国土地的收获量却处在最末位。我们每一俄亩土地所产的燕麦只相当于丹麦和比利时的七分之二；小麦只有丹麦的四分之一和德国与英国的三分之一；黑麦只有比利时的三分之一；甚至于土耳其每一俄亩所产的各种谷物都要比我国农民的耕地高出一倍。","language":"中文","translation":false},{"id":"communism-abc-16-121","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":121,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"还要补充说明的是，实际上俄国的农民土地的产量比表上所指出的还要低，因为平均产量是根据所有的土地计算而来的，其中包括地主的土地，而地主土地的产量比农民的土地要高出五分之一至一倍半。","language":"中文","translation":false},{"id":"communism-abc-16-122","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":122,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"因此，如果去掉古老的祖传的耕作方法，改用新的完善的方法，即使不增加土地的数量，农民也有可能使收获量比现在提高一倍至两倍。","language":"中文","translation":false},{"id":"communism-abc-16-123","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":123,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百一十三节 工业与农业的结合","language":"中文","translation":false},{"id":"communism-abc-16-124","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":124,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"工业与农业的分离和工业在整个社会经济过程中的作用的扩大，引起了城市的发展，而在资本主义的后期，这种发展完全是畸形的。所有农村中的优秀力量不断地从农村跑到城市。城市人口增长速度不仅比农村快，而且农村人口仍在外流。在许多资本主义国家，农业人口绝对减少。另一方面，某些城市发展到了惊人的规模。所有这一切无论给城市还是给农村都带来了极其有害的后果。其中一些最重要的后果是：农村变得人烟稀少，土地荒芜，农村脱离城市文化，城市居民脱离自然界和健康的农业劳动，结果城市居民体力迅速退化，许多加工农产品的生产盲目地迁到城市，城市只是从农村运走粮食，却不以肥料的形式归还农村，结果土壤的贫瘠现象十分严重，等等，等等。","language":"中文","translation":false},{"id":"communism-abc-16-125","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":125,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"使城市接近农村，使工业与农业结合，吸引工厂的工人参加农业劳动——这就是共产主义建设在这方面最近期的目的。现在正在开始把许多万俄亩国有土地划分给各工厂、机关和企业，正准备有计划和有组织地把城市工人调到国营农场，一些工厂在建立蔬菜基地，城市工人到郊区农村参加共产主义星期六义务劳动，动员苏维埃的职员去参加菜园的收获工作等等。","language":"中文","translation":false},{"id":"communism-abc-16-126","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":126,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"共产党在这方面今后还将采取更进一步的措施，因为它坚信，工业与农业的结合将会有广阔的前途，它将会使发展过于庞大和人口恶性膨胀的城市逐渐分散到农村去。","language":"中文","translation":false},{"id":"communism-abc-16-127","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":127,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第一百一十四节 共产党对待农民的策略","language":"中文","translation":false},{"id":"communism-abc-16-128","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":128,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"我们在我们的农业纲领中谈到了我们对农业的设想。现在我们要谈谈，我们准备如何实现我们的纲领，要依靠哪些阶层，打算用什么样的方法把农民的大多数吸引到自己方面来，或者至少要保持他们的中立。","language":"中文","translation":false},{"id":"communism-abc-16-129","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":129,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"在同地主的土地所有制进行的斗争中，全体农民，包括富农在内，都是拥护无产阶级的。正是由于这一点，十月革命迅速地取得了胜利，推翻了妄图把消灭地主土地所有制的斗争拖延下来的资产阶级临时政府。但是业已实行的所谓土地社会主义化和土地平分法却把富农阶级推到了反革命阵营一边。富农失去了革命前买来的部分土地，失去了他们原来享有的、从贫农的份地中租来的土地。他们失去了在捣毁地主庄园时所夺得的一切。最后，他们失去了使用雇佣劳动的可能。如果我们的革命只停留在资产阶级民主改革的范围内，富农阶级就肯定会取代地主的地位。富农就其本性来说是誓死仇视一切农业社会主义改造意图的一个阶级。相反，这个阶级所追求的是要推动我们的农业按照丹麦和美国资本主义农场的模式发展。如果不是因为有无产阶级政权和它的社会主义政策，那么在清除了地主的俄国土地上，中等资产阶级的农场就会极其迅速地发展起来，就会使用雇佣劳动，采取优良的土地耕作方法，何况这里又有大量的半无产者和农民阶层。富农怀着极其美妙的希望和预感参加了革命，然后又在甚至把他们在革命前所拥有的一切都输光了的情况下脱离了革命。富农在其未完全消灭以前，肯定要成为无产阶级国家及其土地政策势不两立的敌人，他们从苏维埃政权那里等来的也只能是对他们的反革命的企图的最无情的斗争。也不排除这样的可能性，即苏维埃政权可以有计划地对富农进行剥夺。动员他们参加社会性劳动，首先是参加农民和国家土地的土壤改良工作。","language":"中文","translation":false},{"id":"communism-abc-16-130","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":130,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"中农是俄国农民中的主要群众。在城市无产阶级的帮助下，中农获得了地主的土地，也只有在无产阶级的帮助下，他们才能冲破资本家-地主反革命的压力来保住这些土地。同样，只有无产阶级结成联盟，只有跟着无产阶级走，只有服从无产阶级的领导，中农才能摆脱世界资本的压迫，免受帝国主义强盗的掠夺，拒绝偿还沙皇和临时政府所欠下的数十亿债务。最后，只有同社会主义无产阶级结成联盟才能使他们摆脱贫穷、破产和无穷的痛苦，并从在任何情况下都注定要灭亡的小农经济过渡到最有利的、生产效率最高的大协作化经济。","language":"中文","translation":false},{"id":"communism-abc-16-131","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":131,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"相反，小私有者的灵魂却在促使中农一心想去和富农实行联合。特别是想到今后必须同城市的工人分享剩余的粮食，想到今后不可能通过交换很快得到城市里的工业品，这样就更加深了他们这种念头。因此，共产党应该努力使中农脱离富农，因为富农实际上是世界资本的走卒，他们想方设法要使农民失去自己在革命过程中所获得的一切。其次，我们的党应该十分清楚地向中农证明，诱使他们跟着富农和资产阶级走的只是一时的、短暂的利益，相反，更加长远、更加重要和更加根本的利益则要求中农要作为劳动者阶级同城市的无产阶级结成联盟。最后，在争取农业社会主义改造的斗争中，我们不应该用草率过激的措施来激怒中农，要尽力避免用强制办法把中农拉入公社和劳动组合。当前俄国共产主义的基本任务在于使工人和农民都各自根据自己的动机去粉碎反革命[2]。如果做到了这一点，那么农业社会主义改造便不会遇到任何不可逾越的障碍。至于农村的贫农，尽管这些无产者和半无产者阶层中的相当部分由于革命已不再存在，并在经济上提高了中农的水平，但是恰恰农村中的这一部分人仍然是无产阶级专政最坚决的基本力量。正是因为有了同贫农的联盟，苏维埃政权才能够给予富农一系列最严重的打击，并使中农脱离了富农。正是因为有了富于共产主义情绪的贫农，我们才能够在农村建立苏维埃的政权机构，并对农民进行第一批最重要的、具有决定意义的军事动员。最后，贫农直到现在也仍然是公社和劳动组合成员中的多数，并在帮助我们实行苏维埃政权的土地法令和其他各种法令。","language":"中文","translation":false},{"id":"communism-abc-16-132","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":132,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"共产党对待农村贫农的主要任务在于使贫农脱离由于解散了贫农委员会而陷入的分散状态。最好是能在生产的基础上把贫农团结起来，如果能有一种比较完善的农业生产方式把他们稳定下来，那他们在农村中的影响就会更加巩固。只要所有的贫农都加入到劳动组合或公社里去，上述的这一点是可以办到的。富农在农村中之所以有力量，是因为他们是一些能干的业主。富农经济是小资产阶级农民经济的精华。贫农如果参加到公社里去，就会成为比一般农民生产要更为完善的生产方式的代表，他们在经济上就会比中农甚至比富农更有力量。有了这样的经济基础，有了这样的公社社员对小业主的物质优势，就可以在农村里建立起贫农的专政。但是这并不是本来意义上的贫农专政，不是富农在贫农委员会时期所抱怨的那种“叫花子和懒汉”的统治，而富农在当时的抱怨不全是没有根据的。这将是劳动农村中比大多数人觉悟早两个世纪的先进阶层的统治。","language":"中文","translation":false},{"id":"communism-abc-16-133","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":133,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"但是要把全部贫农团结到公社里来是件非常困难的事情。近来是中农在纷纷不断地大量加入公社，特别是加入劳动组合。必须建立一系列的贫农职业联合组织，因为贫农本身还没有断绝同小农经济的联系。这种贫农联合组织应该把贫农委员会所未完成的对富农的斗争继续下去。贫农应该在互助的基础上联合起来，他们应该与国家在经济上取得联系，因为他们能够从国家那里得到一定的工作，并在优惠的条件下通过交换得到各种产品和取得各种经济上的支持。在俄国存在着大量的各种各样的贫农联合组织，但这些组织都带有地方性或者仅仅是些非常短暂的和偶然的组织，应该把这些组织团结成一个更大的单位。在一些不生产粮食而从事非农业劳动（提炼柏油和树脂，采集与存放木柴，加工各种木材等等）的省份里，贫农的联合组织将会有极远大的前途。","language":"中文","translation":false},{"id":"communism-abc-16-134","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":134,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"其次，共产党在贫农问题上的任务还在于要更紧密地把贫农与城市无产阶级联合起来，使之摆脱小资产阶级的习惯，放弃力图发展独立自主的巩固的个体经济的那种不切实际的幻想，要在一切有大批贫农存在的地方建立共产党支部和同情者小组。每一个贫农都应该成为公社社员。每一个公社社员都应该成为共产主义者。","language":"中文","translation":false},{"id":"communism-abc-16-135","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":135,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"第十三章书目：弗·恩格斯《法国和德国的农民问题》。列宁《土地问题和马克思的批评家》，《十九世纪末俄国的土地问题》。","language":"中文","translation":false},{"id":"communism-abc-16-136","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":136,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"革命后出版的通俗读物：热古尔《农业中的共产主义经济组织》。基伊《农村公社》。尼·美舍利亚科夫《关于农业公社》。叶·普列奥布拉任斯基《关于农业公社》。尤·拉林《农业都市化》。尼·美舍利亚科夫《土地国有化》。尼·列宁《在俄共第八次代表大会上关于对待中农态度的发言》。苏马托欣《让我们生活在公社中》。尼·列宁《为粮食而斗争》。","language":"中文","translation":false},{"id":"communism-abc-16-137","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":137,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"有许多小册子已经过时，这里不再列举。在米·凯尔任策夫的小册子《共产党员必读》里有较详细的目录。","language":"中文","translation":false},{"id":"communism-abc-16-138","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十三章 农业组织","page":16,"paragraph":138,"url":"https://www.marxists.org/chinese/bukharin/1919/15.htm","text":"[1] 当然，除了在拖拉机上工作的工人之外，还应当考虑到拖拉机场的修理工，制造拖拉机和提炼石油的工人等等，所有这些劳动力都应分别计算在每一俄亩土地上。这样一来，使用拖拉机的好处看起来要减少一些，但是实际上仍然是很大的。 [2] 我们在宣传号召农民积极参加国内战争时必须强调的是农民参加这一战争的动机。农民对于我们争取社会主义而斗争这一点是不感兴趣的，他们关心的是我们剥夺帝国主义剥削小私有者的可能性，不让地主或商人重新骑到农民的脖子上。","language":"中文","translation":false},{"id":"communism-abc-17-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-17-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"· 第一百一十五节 取消私人商业","language":"中文","translation":false},{"id":"communism-abc-17-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"· 第一百一十六节 消费公社","language":"中文","translation":false},{"id":"communism-abc-17-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"· 第一百一十七节 过去的合作社","language":"中文","translation":false},{"id":"communism-abc-17-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"· 第一百一十八节 现在的合作社","language":"中文","translation":false},{"id":"communism-abc-17-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"· 第一百一十九节 其他分配机构","language":"中文","translation":false},{"id":"communism-abc-17-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"第一百一十五节 取消私人商业","language":"中文","translation":false},{"id":"communism-abc-17-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"每一种生产方式都有一套相应的专门分配方式。随着资本主义生产工具所有制的消灭，苏维埃共和国不可避免地要和资本主义的分配机构，即和它的商业发生冲突，并且要逐步把它消灭掉。首先是没收了大型商业仓库。这一点之所以必要，原因还在于粮食危机尖锐和商品匮乏。我们把投机商藏起来准备卖高价的商品都分配给了劳动群众，这或多或少地缓和了十月革命后最初几周的危机。","language":"中文","translation":false},{"id":"communism-abc-17-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"但是商业仓库的国有化仅仅是第一步。随之而来的是实行大商业的国有化。这样做一方面是为了与投机商作斗争，为了对共和国现有的商品进行统计，另一方面也是为了把商品首先分配给劳动阶级。苏维埃政权不仅对粮食，而且对布匹以及一切生活日用品都实行了阶级定量分配。","language":"中文","translation":false},{"id":"communism-abc-17-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"不过，苏维埃政权如果采取另外一种做法也许会更有利：没收私商所储存的全部商品。按阶级定量进行分配，但不破坏商业机构本身，而相反，是对它加以利用，让它为我们服务。","language":"中文","translation":false},{"id":"communism-abc-17-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"实际上相当大的程度上也正是这样做的。商品是没收了，遗憾的是没收得太晚，以致大部分商品已换成了现金并被原主藏匿起来。所有的大商店都完全转到苏维埃政权手中，并在商业工会的协助下开始工作。只有企业的上层人物被停止了工作，这些人现在成了地地道道的寄生分子。的确，在过去，商品需要采购，得到处寻找，再进行交易。现在，无产阶级国家本身已成为国营工厂的商品的主要生产者，这样，如果国家再把商品拿来自己同自己交换，同时再养活着一群商人，那就是毫无意义的了。另一方面，既然已经实行了粮食垄断，那么在农民与国家、国家与消费者之间，商业中介人就完全是多余的了。他们既拿不出什么东西来诱使农民将粮食交给国家，又无处寻找粮食的买主，所以他们已毫无用处。","language":"中文","translation":false},{"id":"communism-abc-17-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"因此，既然无产阶级政权掌握了大量最重要的食品的生产，并且有相当一部分粮食是由自己的机关去采购，所以它就必须要有自己的分配机构。私人商业在这里是不会有什么作为的。","language":"中文","translation":false},{"id":"communism-abc-17-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"但是如何对待那些小的私人商业呢？这类商业从事的工作是分配独立小手工业生产的产品，苏维埃政权还没有掌握这部分生产。它还未能成为这些产品的独一无二的买主。有些产品要靠苏维埃的代理机构按照固定的价格来收购是办不到的，这些产品是由小商业在居民中实行分配（当然，价格很高），而对这些小商业又该采取什么态度呢？","language":"中文","translation":false},{"id":"communism-abc-17-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"这个问题无疑要比大商业的问题复杂得多，消灭大商业的问题是由剥夺所有的资本的这一事实预先决定了的。如果苏维埃政权不能通过自己的分配机构来代替小商业，那么单纯地禁止小商业是没有任何意义的。曾经有过这样的情况，一些地方苏维埃和革命委员会，特别是在一些清除了白卫军的地区，还未建立起自己的粮食机构，或者更重要的是，还未等这些机构那怕多少能保证居民的正常供应时，就禁止了自由贸易。结果是私商转入地下，价格提高了许多倍。只有在愈来愈多的产品通过国家的手供应给居民时，小商业才能随之逐步消灭。如果现在粮食人民委员会和活跃的苏哈列夫卡并存，那就会仅仅意味着一件事：在分配方面资本主义和社会主义之间的战争还要继续下去。现在这场战争是在小商业的阵地上进行，只有当国家政权变成小工业产品的主要买主时，或者说只有当国家政权本身变成这些产品的生产者时，这场战争才会结束。这里当然还不包括这类情况，即小私商在倒卖本来是属于粮食机关掌握的食品，也就是关系到同苏维埃分配机构里的盗窃行为和其他缺点作斗争的问题。总而言之，只要城市的大生产尚未恢复起来，只要居民主要消费品的供应工作不是在事实上由国家垄断组织来进行，小商业就会一直存在下去。","language":"中文","translation":false},{"id":"communism-abc-17-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"因此，尽管消灭分配中的所有各种各样的私人中介人是社会主义的目的，尽管随着时间的推移这个目的一定会达到，但是从近期来看，要完全消灭小商业机构是不可能的。","language":"中文","translation":false},{"id":"communism-abc-17-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"第一百一十六节 消费公社","language":"中文","translation":false},{"id":"communism-abc-17-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"既然居民需要的大部分食品是通过或者将通过国家的粮食机构来供应，那就应该有一套相应的社会主义分配机构。这些机构应该满足以下的要求：这些机构应该是集中的。这样可以保证最合理的和平均的分配。这样可以减少机构维持费用，在社会主义条件下，这些机构所需要的人力和财力总是比私人商业机构要少得多。社会主义分配机构的工作效率应该是最高的。这一点非常重要。必须使这些机构做到不仅它们本身向国家要求的人力和物力是最少的，而且它们能不额外多占用消费者一分钟的时间。否则就会造成整个社会人力物力的巨大浪费。在私人商业存在的条件下，消费者在资本主义经济的正常情况下，只要有了钱，任何时候都可以买到所需要的东西。社会主义机构在这方面不应该比私人商业更坏。然而，正因为这些机构非常集中，所以就很容易变成一架官僚主义十分严重和工作效率极其缓慢的机器，可能使许多商品在未到达消费者手中之前就已腐烂掉。应该怎样来建立这些机构呢？","language":"中文","translation":false},{"id":"communism-abc-17-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"苏维埃政权面临着两种出路：或者是重新建立一套分配机构，或者是把资本主义建立的全部分配机构利用起来，使它们为社会主义的分配目的服务。","language":"中文","translation":false},{"id":"communism-abc-17-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"苏维埃政权走的是第二条道路。苏维埃政权在一些必须建立自己的机构的地方，特别是在破坏了资本主义关系的最初时期，建立了自己的机构，与此同时，它也注意到了合作社，提出利用合作社的机构来进行产品分配。","language":"中文","translation":false},{"id":"communism-abc-17-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"第一百一十七节 过去的合作社","language":"中文","translation":false},{"id":"communism-abc-17-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"在资本主义制度下，合作组织的主要任务在于，使消费者摆脱商业中介人——投机商的剥削，把商业利润留在联合起来的消费者手中，保证为消费者提供优质产品，合作社组织或多或少地成功达到了这一目的，但这仅仅为的是自己的社员，即为的是社会的一部分人。至于说合作社的创办人关于借助于合作社来对资本主义进行和平改革的幼稚幻想，那么在这方面的实际情况是这样的：要说合作社有成就，这一点仅仅是在排挤小商业上表现得比较明显，但对于大商业则几乎不有触及到，它们本身反而享用了大商业为自己提供的便利。至于合作社的生产企业，它们在资本主义生产总的体系中所处的地位是根本微不足道的，对于资本主义工业发展的进程不起任何影响。总之，庞大的资本组织从不把合作社看成什么了不起的竞争者。只要有必要，它随时都完全有可能象掐死一只小猫似的在经济上把合作社干掉，因而它可以容许合作社的思想家们去安静地做自己的排挤资本主义的美梦，听任合作社的会计员为他们从小店主那里夺得的一点好外而狂喜不已。合作社本身完全适应了资本主义，并在其分配体系中占有一定的地位。它甚至对资本主义是有利的，因为它可以减少分配机构的费用，从而挤出一部分多余的商业资本投入工业。另一方面，由于合作社减少了小商品中介人的数量，并使消费者与资本主义大生产更加接近，所以就加速了商业中的商品流转，使货款能按照保证条件及时如数地得到偿还，最后使产业后备军处于更加绝望的境地，因为通常有相当一部分失业者都从工业转到小商业。除此以外，我们还要指出的是农民的合作社，许多调查材料都说明，这种合作社到处都在为殷实富裕的农民带来极大的利益，而对贫农却几乎没有什么帮助。就其阶级组成来说，消费合作社可分为工人合作社、农民合作社和城市普通公民合作社，即实质上是小资产阶级和官吏的合作社。工人合作社在总的合作组织网中往往是最左的，而在无产者的阶级组织网中又往往是最右的。在农民合作社中殷实的大农户说了算。在城市合作社里是小资产阶级知识分子占领导地位，他们扮演着整个合作组织的思想家的角色，他们宣称，在用合作社的面包和土豆来打击资本主义方面，合作社有着远大的前途。","language":"中文","translation":false},{"id":"communism-abc-17-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"俄国的十月无产阶级革命揭露了合作社的真正实质。除了部分工人合作社之外，所有其他合作社，特别是其中的知识分子和富农领导者，都对社会主义革命采取极其敌对的立场。西伯利亚的购销合作社和其他联合组织的合作社都明确地站在白卫军反革命一边，拥护让世界帝国主义势力来镇压苏维埃共和国的主张。","language":"中文","translation":false},{"id":"communism-abc-17-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"到1917年10月1日为止，俄国共计有六百一十二个合作社联合组织，这个数字看来比实际上要少一些，因为根据1918年1月1日以前的某些材料，估计可能有一千个这样的联合组织。到1918年1月1日为止，共有二百八十一个联合组织加入了中央合作总社。在二百六十九个联合组织中共计有三万八千六百零一个合作社，社员人数为一千三百六十九万四千一百九十六人。但是由于有的合作社同时加入两个至三个联合组织，因此俄国合作社的数目比实际上所说的数目要少些，社员的人数也同样如此。至于俄国合作社在工业方面的活动，那么在1918年所有的合作社和合作社联合组织共有四百六十九个企业，其中大部分为小企业。","language":"中文","translation":false},{"id":"communism-abc-17-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"第一百一十八节 现在的合作社","language":"中文","translation":false},{"id":"communism-abc-17-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"在资本主义统治下，合作社在其总的体系中起了一定的作用。在苏维埃政权时期，合作社的机构注定会或者逐渐与所有其他资本主义分配机构同时消亡，或者加入到社会主义分配体系中来，起国家分配机构的作用。合作社原先的主人——孟什维克、社会革命党人和各种高尔察克式的“社会党人”，都希望使合作社不依赖于无产阶级国家，即保证它以消亡的自由。相反，苏维埃政权从广大劳动群众，特别是从合作社劳动群众的实际利益出发，采取了另一种办法。苏维埃政权不会为知识分子合作社上层人物的情绪所左右，也不会因为这些上层人物的反革命意图而抛弃整个合作社机构，它力图不断地把合作社的分配机构纳入到自己的分配机构的总体系中来。它力图不是缩小，而是扩大合作社的活动范围。苏维埃政权和共产党在这里所面临的实际任务，总的来说可以归结如下：","language":"中文","translation":false},{"id":"communism-abc-17-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"一般资产阶级类型的合作社是投入一定股份的公民自愿组成的联合组织。通常合作社只为自己的社员服务，只有在无损于自己的社员的利益时，才可以向所有的居民出售产品。我们认为必须使所有的居民都合作化，使每个社会成员都加入某个合作社。只有在那时，通过合作社进行的分配才意味着是对全体居民的分配。","language":"中文","translation":false},{"id":"communism-abc-17-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"在消费合作社里，工作是在合作社的全体社员自治的基础上按部就班地进行的。（如果在实际上只是由几个理事在掌权，那只能是社员们自己的过失。合作社的章程规定，全体社员大会是合作社的主事人。）如果共和国的全体公民都参加到合作社中来，他们就有充分的可能对无产阶级国家的全部分配机构实行自下而上的监督。如果群众有了足够的主动性，他们就能对分配工作中形形色色的舞弊行为和官僚主义进行最坚决有效的斗争，从而使国家合作社组织的工作做得迅速和井然有序。由于这一点，由于消费者本身参加到分配工作中来，分配机关就从原来高居于群众之上的机关变成了群众自己的机关，这无疑有助于提高劳动者的共产主义觉悟和遵守同志式纪律的自觉性，并帮助群众了解整个社会主义社会的全部生产-分配机构的工作。其次，在全体居民都实行了合作化以后，必须使居民中的无产者阶层在合作社中起领导作用。在城市中要做到这一点，就要让城市工人更积极地参加合作社的活动，在选举中让共产主义的无产者在理事会里占多数，而更主要的是要把工人的合作社，而不是把普通公民的合作社变成城市消费公社。为了同一目的，还必须力求在合作社与工会之间，即在生产机构和分配机构之间建立紧密的联系。这种联系具有巨大的前途。随着时间的推移，国家的作用会缩小到一个中央统计局的作用，到那时，生产组织和分配组织之间的灵活多样的联系将具有特别得重要的意义。最后，共产党员必须作为团结一致的集体参加合作社的建设，并争取在其中起领导作用。","language":"中文","translation":false},{"id":"communism-abc-17-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"在农村必须把富农排挤出合作社的理事会，取消农村富裕阶层在分配上的各种特权，使农村合作社的机构掌握在贫农和有觉悟的中农手中。","language":"中文","translation":false},{"id":"communism-abc-17-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"第一百一十九节 其他分配机构","language":"中文","translation":false},{"id":"communism-abc-17-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"从十月革命的时候起，在俄国就出现了许多各种各样的由革命建立的分配机构。这些机构的中心就是粮食人民委员部及其在各省、县的所有分支机构。粮食机关过去和现在都有大量粮店和粮站作为自己的分配机构。在农村，有一个时期为了同合作社的分配相抗衡，贫农委员会曾起着分配者的作用，因为大部分合作社在分配所获得的食品多半都是照顾到富裕农民的利益，而贫农委员会则力求把从国家那里得到的食品拿出较多的部分交给贫农。大城市的住宅委员会和公社之家在分配方面起了很大的作用。除此之外，工会，特别是工厂委员会也从事过分配工作。","language":"中文","translation":false},{"id":"communism-abc-17-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十四章 分配组织","page":17,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/16.htm","text":"苏维埃政权的任务是要用一个统一的分配机构来代替这种多头绪的分配机构，或者把这些机构纳入到统一的总分配机构的环节中去。例如，住宅委员会和公社之家就起了良好的作用，它们使消费者能及时得到食品，而不必再成天地排长队。","language":"中文","translation":false},{"id":"communism-abc-18-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-18-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"第十五章 银行组织和货币流通","language":"中文","translation":false},{"id":"communism-abc-18-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"· 第 一百二十 节 银行国有化和统一人民银行；作为总会计处的银行","language":"中文","translation":false},{"id":"communism-abc-18-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"· 第一百二十一节 货币和货币制度的消亡","language":"中文","translation":false},{"id":"communism-abc-18-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"第一百二十节 银行国有化和统一人民银行；","language":"中文","translation":false},{"id":"communism-abc-18-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"关于什么是银行和在资本主义社会里银行起什么作用的问题，大部分工人在认识上都相当模糊。银行好象是一个巨大的柜子，富人都把自己的资本送到那里去。工人有了积蓄也往银行里存，他们也知道，存款会有利息，但有时存进私人银行的存款也会蚀掉，致使存款者破产。","language":"中文","translation":false},{"id":"communism-abc-18-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"首先，银行并不是什么钱柜。经常放在银行里的现金根本就没有多少。银行工作的本质决不是要作为一个供有积蓄的人使用的烧不坏的柜子。确实，银行里经常往来着几亿的存款，但是这些钱并不是放着不用的。集中在银行里的钱是在不断地投入流通。首先，这些钱被贷给企业主，企业主则开办工厂，剥削工人，并为所贷的款子给银行交付一部分利润（银行又将一部分自己的利润付给存款者）。其次，银行自己也用从存户那里得来的钱开办新的企业，或者为现有的企业提供资金。最后，银行还把钱贷给一些国家[1]，并从那里获得利息，即通过政府来掠夺这些国家的人民。则于银行是属于一小撮大的资本家的，所以归根结蒂银行的工作可以说是通过自己的资本和存户的资本来榨取剩余价值。","language":"中文","translation":false},{"id":"communism-abc-18-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"但是银行不仅仅是榨取工农剩余劳动的剥削者。它还具有其他意义。比如说假设我有钱将它存入银行，这就是说我有过某种商品，我已把它们卖掉，变成了货币。如果各银行经手的货币越来越多，整个社会的各种资本的数量不断增加，这就是说，有愈来愈多的价值在投入流通。货币——这是产品的证据，这是产品的一种身份证。根据整个货币的运动可以大致判断出产品的运动。因此，银行不可避免地会变成资本主义社会的某种统计局。","language":"中文","translation":false},{"id":"communism-abc-18-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"由此可以看出，银行在社会主义社会中能够起到何种作用，夺取了政权的无产阶级应该怎样来对待它。","language":"中文","translation":false},{"id":"communism-abc-18-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"在社会主义革命之后，或者更确切地说，在社会主义革命时期，工人阶级必须占领所有的银行，首先是国家中央银行。之所以必须这样，首先是为了要没收资产阶级的全部存款、资本家的全部有价证券和各种货币凭证。这一占领是给予资本主义剥削的心脏以直接的打击。","language":"中文","translation":false},{"id":"communism-abc-18-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"在十月革命时期和1917年12月我们正是这样做的，因而给了俄国资产阶级以毁灭性的打击。","language":"中文","translation":false},{"id":"communism-abc-18-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"无产阶级政权应该对待它所占领的银行呢？它应该利用资本家的银行组织中一切有价值的东西。即它应该保留银行，把它作为生产的统计机构和财政分配机构。首先应该使得银行事业全部国有化。这意味着，不仅从资产阶级那里夺取来的全部银行要变为无产阶级的国家机关，而且今后所有的银行业务都要由国家垄断。除了国家之外，任何人都不能开办银行。","language":"中文","translation":false},{"id":"communism-abc-18-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"其次，应该把所有的银行合并起来，把不需要的关掉，仅仅留下那些需要的银行，把它们作为苏维埃共和国统一银行的分行。","language":"中文","translation":false},{"id":"communism-abc-18-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"在统一人民银行里不需要资产阶级银行所惯用的那套各式各式各样的簿计方法和各式各样的银行业务，而是实行统一的和简单的核算方法。这样无产阶级国家就能做到心中有数，知道国家应该往哪儿投放多少资金，从哪儿又能得到多少资金。","language":"中文","translation":false},{"id":"communism-abc-18-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"但是，如果国家的全部收支都由国家的统一银行来核算，国家本身就会愈来愈变成统一的和巨大的国家经济机构的管理处，而到那时，银行又将怎样呢？","language":"中文","translation":false},{"id":"communism-abc-18-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"很明显，那时银行将变成某种经济企业的会计室式的机构。银行本身将逐渐消灭，并且如同我们的纲领中所谈到的那样，将变成共产主义社会的总会计处。","language":"中文","translation":false},{"id":"communism-abc-18-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"第一百二十一节 货币和货币制度的消亡","language":"中文","translation":false},{"id":"communism-abc-18-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"共产主义社会将不会有货币。在共产主义社会里每个工作者都为集体生产产品，但是他们并不需要领取什么凭证来说明他们为社会生产了产品，也就是说，不需要领取货币。同样，当他们需要从集体那里领取甚么东西时，他们也不必向社会支付任何货币。而在社会主义制度下，即在从资本主义到共产主义过渡的制度下，那就是另一回事了。在商品经济中货币不可避免地要产生并起作用。假如我是个皮鞋匠，我想得到一件上衣，我就得把自己的商品即皮靴先变成的货币即商品，通过这个商品，即利用这个商品来进行交换我就可以获得任何其他的商品，比方说我现在需要上衣。每一个商品生产者都是这样做的。在社会主义社会里商品经济仍将部分存在。","language":"中文","translation":false},{"id":"communism-abc-18-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"即使我们已成功地镇压了资产阶级的反抗，并把过去的统治阶级变成了劳动者，但是在我们这里也还保留着不是为集体而劳动的农民。每个农民都力求把自己剩余的产品卖给国家，用它来换取他所需要的工业品。农民仍将是商品制造者。农民无论同自己的邻居的帐目来往，还是同国家的帐目来往，都需要有货币，就象国家同尚未加入总的生产公社的所有社会成员的帐目来往需要货币一样。更有甚者，私人商业还在很大程度上存在着，苏维埃政权暂时还不可能完全用社会主义分配来取代它，这样就更不可能一下子就把货币消灭掉。最后，发行纸币可以代替税收，它可以使无产阶级国家有可能在极其困难的条件下维持下来，就这一点上来看，立即取消货币也是不利的。","language":"中文","translation":false},{"id":"communism-abc-18-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"但是社会主义是建设中的共产主义，是未建成的共产主义。随着建设成就的扩大，货币一定会逐步停止使用，可能国家总有一天要宣布取消货币的最后流通。这一点对于有效地消灭资产阶级的残余是特别重要的，否则资产阶级就会在这个宣布“不劳动者不得食”的社会里继续用他们私藏的货币来享用劳动阶级所创造的财富。","language":"中文","translation":false},{"id":"communism-abc-18-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"从社会主义革命一开始，货币就在逐渐失去它的意义。所有国有化的企业，就象一个大老板（这里指的就是无产阶级国家）开的企业一样，有一个共同的出纳处，它们彼此之间不需要用货币进行买卖。非现金结算在逐步实行。这样，货币就要从国民经济的许多领域被排挤出去。对农民来说，货币也同样会愈来愈失去自己的意义，商品交换将提到首位。甚至在私人同农民的交易中，货币也会愈来愈退到次要地位，买主只要用某种实物，比方说用衣服、衣料、餐具、家具等等就可以换来粮食。在工业失调引起商品交换的大幅度减少的情况下，国家就要实行大量的纸币，这也会促进货币的逐渐消灭。货币愈来愈贬值，这在实质上也就是它的自发消亡。","language":"中文","translation":false},{"id":"communism-abc-18-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"但是给予货币存在的打击最为严重的将会是实行预算手册和用产品来偿付工作者的劳动的办法。在劳动手册里将登记上工作者干了多少活，即国家应该付给他多少。根据这个手册他可以到消费品小店以领取产品的形式领取报酬。在这种制度下，不劳动的人用钱是什么也买不到的。但是只有在国家集中掌握了足够供应社会主义社会全部劳动者所需要的消费品时，这种办法才能实行。遭受破坏的工业得不到恢复和扩大，这种办法是不能实现的。","language":"中文","translation":false},{"id":"communism-abc-18-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"现在看来，取消货币流通的过程大体上就是这样。首先是在国有化企业（工厂、铁路、国营农场等等）内部产品交换领域里取消货币。然后是在国家同社会主义国家的工作者之间（即在苏苏维埃政权、职员和苏维埃企业的工人之间）的结算领域里取消货币。下一步是在国家与小生产（农民、手工业者）进行交易时取消货币，而代之以商品交换。再往后是在小经济内部的商品交换中取消货币，最后可能货币将与小经济一起同归于尽。","language":"中文","translation":false},{"id":"communism-abc-18-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"第十五章书目：几乎没有关于这个问题的文献，建议参看下列文献：尤·皮达可夫《无产阶级和银行》。索科里尼柯夫《关于银行国有化问题》。此外，在《经济生活报》和《国民经济》杂志中还有一些文章。","language":"中文","translation":false},{"id":"communism-abc-18-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十五章 银行组织和货币流通","page":18,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/17.htm","text":"[1] 例如我国的沙皇政府和克伦斯基政府对外国银行所欠的债务达一千六百多万卢布。","language":"中文","translation":false},{"id":"communism-abc-19-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-19-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"第十六章 无产阶级国家的财政","language":"中文","translation":false},{"id":"communism-abc-19-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"· 第一百二十二节 国家——寄生机关","language":"中文","translation":false},{"id":"communism-abc-19-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"· 第一百二十三节 无产阶级国家——生产机关","language":"中文","translation":false},{"id":"communism-abc-19-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"· 第一百二十四节 无产阶级国家的预算","language":"中文","translation":false},{"id":"communism-abc-19-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"第一百二十二节 国家——寄生机关","language":"中文","translation":false},{"id":"communism-abc-19-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"如上所说，国家，这个暴力的组织，是一个阶级统治另一个阶级的组织。既然整个资产阶级随着资本主义的发展愈来愈成为只知道消费而丝毫无助于生产的寄生虫阶段，那么关于站在受剥削的和愤怒的群众的对立的立场上去维护这些寄生虫的安宁和收入的资产阶级国家又该是怎样的呢？在警察、宪兵、常备军、司法机关、以及所有国家管理机关里，集中了相当大的一批人，其中没有哪一个人生产过一普特粮食，一俄尺布、一根针或一个别针。整个这个组织都是靠工人和农民提供的剩余产品生活。国家以各种直接的和间接的赋税形式来榨取这些剩余产品。例如，我国的沙皇政府就用这种办法从工农身上榨取了三十多亿金币（如果按现在的纸币和它的购买力折算，这将超过三千亿卢布，即相当于整个俄国全部货币的三倍多）。税收中只有很少一部分用于生产，例如用来建造铁路、公路、船舶、桥梁、国营工厂等等。","language":"中文","translation":false},{"id":"communism-abc-19-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"至于说无产阶级国家，那么在国内战争还在继续，资产阶级的反抗尚未被消灭的时期，这个国家部分地说来也是凌驾于生产之上的机关。无产阶级国家许多机关的劳动并不是创造新价值的劳动。相反，许多国家机关是依靠工农创造的产品来生活的。例如我们所有的军事机构和红军、管理机关、肃反机关等等就是这样。但是，无产阶级国家的特点恰恰不是表现在这一点上，即不是表现在这个国家同剥削者国家相类似的这一点上。无产阶级的特点在于这个组织正在逐渐由非生产的机构变成管理经济的组织。","language":"中文","translation":false},{"id":"communism-abc-19-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"第一百二十三节 无产阶级国家——生产机关","language":"中文","translation":false},{"id":"communism-abc-19-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"在卫国战争结束前很久，无产阶级国家就主要是在为产品的生产和分配服务。只要列举一下各中央和地方人民委员部的情况便可以清楚地看到这一点。苏维埃组织中最大的组织是最高国民经济委员会及其各分支机构。这是一种纯生产组织。其次是各人民委员部：粮食农业人民委员部、交通人民委员部、劳动人民委员部——这也是生产、分配或为劳动力服务的组织。再就是实行统一劳动学校大纲的国民教育人民委员部，这个部正在成为培养有知识的劳动力的组织。无产阶级国家的卫生人民委员部是保护劳动人民健康的机关（收容所、教养院等等）。甚至于管理人民委员部也变成了主要是帮助和领导地方的、特别是市政经济的组织。整个说来，无产阶级的国家机构变成了一个领导国民经济，并从各个方面和各个领域为它服务的巨大组织。研究一下苏维埃共和国的预算便可以很清楚地看到这一点。这里是一些最能说明问题的支出。","language":"中文","translation":false},{"id":"communism-abc-19-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"1919年上半年拨款的数目如下（以百万卢布为单位）：","language":"中文","translation":false},{"id":"communism-abc-19-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"从这些数字中我们可以看到，共和国的国防仍然耗费着大量的金钱。但如果去掉这种由于特殊环境造成的支出，那就可以非常清楚地看到，无产阶级国家十分之九的支出都是用于生产、管理生产、保证生产进一步发挥效能、保持劳动力的健康等等，这些都是纯经济性质的支出。","language":"中文","translation":false},{"id":"communism-abc-19-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"不仅如此，在共产主义星期六义务劳动里，无论是生产组织的工作者，还是红军战士和政委，都在为生产劳动尽自己的义务，尽管最初规模还不是很大。在1919年以前，世界上还没有任何一个国家的官员在经常地为这个国家修理火车头和装卸木柴。","language":"中文","translation":false},{"id":"communism-abc-19-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"第一百二十四节 无产阶级国家的预算","language":"中文","translation":false},{"id":"communism-abc-19-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"从上面我们看到，无产阶级国家的支出愈往后愈多地变成生产性的支出。有人会问，国家的收入来源是什么呢？","language":"中文","translation":false},{"id":"communism-abc-19-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"俄罗斯苏维埃共和国的财政状况可以大致地说明这个问题。","language":"中文","translation":false},{"id":"communism-abc-19-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"苏维埃政权在它存在的最初时期曾有某些特殊性质的收入，这些收入包括：在银行里没收下来的资产阶级的存款，旧政府遗留下来的国家现有资金，向资产阶级摊派的捐税，出售从私商和从农场没收来物品所获得的款项等等。但是，所有这些收入同必要的支出比较起来是非常少的。确实，某个时期向资本家摊派的捐税几乎是维持苏维埃生存的唯一源泉，但是对于中央政权来说，这笔钱帮不了任何大忙。另外，这个源泉不可能是永久性的，因为资产阶级确实被剥夺光了，或者在大多数情况下，把积蓄藏起来跑掉了。累进所得税过去和现在都没有很大的效果。既然这种税收牵涉到职工，那它就没有任何意义，因为国家以税收形式所得到的这笔钱是以薪金的形式支出的那笔钱的一部分。既然税收牵涉到城市资产阶级，那么由于资产阶级几乎已不正式存在，而且不公开地经营自己的本行业务，所以征税就变得极其困难，而且事实上这种税收也是微不足道的。征税工作在富裕农民当中进行得还比较顺利，但是要走上正轨，必须要有地方政权机关，主要是乡政机关支持的税务机关的经常性的和系统性的工作。但是从保证事情的顺利进行来看，这些机构都还没有很好地建立起来。至于中农，只要卫国战争还在继续，从政治上考虑，最好是不要向他们征税，以免把他们从无产阶级身边推开。原计划征收一百亿革命特别税的意图失败了，因为尽了极大的努力也只征收了不到二十亿。国家收入的主要来源只剩下印钞票了。既然用这些纸币还能够购买物品，所以发行纸币在实质上就是一种特殊形式的税收。这种发行纸币的办法会造成货币贬值，间接地导致对资产阶级货币资本的剥夺，使得资产阶级的购买力较之过去用这些货币所能买到的东西来看大为降低。自然，发行纸币不能长久地作为国家收入的来源，否则就会引起货币的全面崩溃。无产阶级国家所面临的问题是要把自己的收入建立在更加可靠的基础上。","language":"中文","translation":false},{"id":"communism-abc-19-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"生产本身就是这种可靠的基础。发行货币之所以还能够作为一种收入来源，那只是因为这种征税的方式不易被人察觉。同样，国家垄断的间接税也完全不易被人所注意。这种形式的国家收入在实质上是完全正确的。因为国家生产的任何产品的生产价值也都应该把生产管理费用包括在内。而这种管理也是由无产阶级国家来实现的。这实际上意味着，如果运输旅客每年要花费十亿卢布，那么国家就可以把运输费用定为这样一个数字，让国家能从旅客的运输中收回十二亿卢布。如果生产的全部布匹价值为五十亿卢布，那就可以把它的卖价定为六十亿卢布，等等。多出来的钱就可以用来维持国家的需要。当然，这种从垄断组织那里得来的收入不仅可以表现为货币，而且也可以表现为提出的一定数量的产品。","language":"中文","translation":false},{"id":"communism-abc-19-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"如果整个无产阶级国家变成了管理全部社会主义经济的机关，那么关于国家的维持费用的问题，即我们关于预算的老问题也就简单多了。问题无非是拨出一定数量的资金作为某种经济上的支出而已。","language":"中文","translation":false},{"id":"communism-abc-19-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"但是如果说国家预算问题会大大简化，那么另一个问题，即搞清楚有多大一部分产品可以用于消费，即可以在整个经济中消耗掉，却不是那么简单的事情。必须十分善于计算，有多少产品可以毫无保留地用于消费，有多少产品应该储存起来，有多少产品应该用于扩大再生产等等。","language":"中文","translation":false},{"id":"communism-abc-19-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"由此可见，随着国家作为一个寄生机关而被消灭，国家预算问题就将变成关于分配社会主义社会全部产品的总问题，因为国家预算将变成整个社会主义社会总的预算的极小的一部分。","language":"中文","translation":false},{"id":"communism-abc-19-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十六章 无产阶级国家的财政","page":19,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/18.htm","text":"关于这个问题几乎没有专门性的文献。可以参考阿·波嘉也夫《苏维埃政权的财政政策》一书。","language":"中文","translation":false},{"id":"communism-abc-20-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-20-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"第十七章 共产党人关于住宅问题的纲领","language":"中文","translation":false},{"id":"communism-abc-20-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"· 第一百二十五节 资本主义社会的住宅问题","language":"中文","translation":false},{"id":"communism-abc-20-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"· 第一百二十六节 无产阶级国家的住宅问题","language":"中文","translation":false},{"id":"communism-abc-20-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"第一百二十五节 资本主义社会的住宅问题","language":"中文","translation":false},{"id":"communism-abc-20-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"资产阶级的特权在任何地方都没有象在住宅方面表现得那样突出。各城市最好的房子都被资产阶级住着。所有最好的洁净宜人、花木繁茂的街道都有成为有产阶级的领地。相反，在所有的国家里，工人被驱赶到城市的边缘地区。他们被驱赶到那里，完全不是因为大部分工厂通常都座落到在城市的近郊，即使工厂位于市中心，这个工厂的工人也还是照样要住在拥挤不堪的市郊的工人区里。而那些企业主，尽管自己的企业是建在城市边缘地区，却照样要住在市中心。","language":"中文","translation":false},{"id":"communism-abc-20-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"资产阶级家庭住的都是单独的邸宅或带套间的住宅，房间的数目比其家庭的人数还多，并享有花园、浴室和各种生活舒适设备。","language":"中文","translation":false},{"id":"communism-abc-20-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"工人家庭都住在拥挤的地下室、独屋和狭小的套间里，或者常常是住在集体的工棚里，就象罪犯住在监狱的大牢里一样。工人劳动了一整天，肺里吸满了工厂的煤烟、锯末、刨屑和灰尘，又不得不整夜和五六他孩子一起睡在一间房子里。","language":"中文","translation":false},{"id":"communism-abc-20-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"毫不奇怪，统计学很快就发现，住在工人住宅区里的人死得很快，这些人劳动时间长，而且住房很狭窄，生活很艰苦。具体有这样一些材料。在英国，每年每千人中有二十二人死亡。在资产阶级住宅区死亡率下降到十七人，在工人住宅区提高到三十六，而在最贫穷的工人住宅区，死亡率增加到每千人为四十至五十人。在比利时的首都布鲁塞尔，工人住宅区的人们死亡率为二十九分之一，在条件良好的资产阶级住宅区里死亡率则为五十三分之一，也就是说，工人住宅区的死亡率几乎为资产阶级的住宅区的两倍。","language":"中文","translation":false},{"id":"communism-abc-20-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"住在明亮、干燥和温暖的住宅区里的资产者的平均寿命，比住在郊区的地下室和阁楼的人的平均寿命要长一半以上。","language":"中文","translation":false},{"id":"communism-abc-20-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"在布达佩斯，五岁以上的死者的平均寿命为：","language":"中文","translation":false},{"id":"communism-abc-20-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"每个房间住有1——2人的——47.16岁","language":"中文","translation":false},{"id":"communism-abc-20-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"每个房间住有2——5人的——39.51岁","language":"中文","translation":false},{"id":"communism-abc-20-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"每个房间住有5——10人的——37.1岁","language":"中文","translation":false},{"id":"communism-abc-20-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"每个房间住有10人以上的——32.03岁","language":"中文","translation":false},{"id":"communism-abc-20-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"工人子女的死亡率比资产阶级子女的死亡率要高得多。拿每个房间住有不超过一个人的资产阶级的住宅区和每个房间必须住三个人的住宅区相比，在周岁以前的儿童的死亡率上，前者要比后者少四分之三。资产阶级住宅区一岁至五岁的儿童的死亡率比工人住宅区要少一半。","language":"中文","translation":false},{"id":"communism-abc-20-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"但是，住在潮湿和闷热的住宅里的工人不仅比资产阶级平均早死十五年，而且他们还得为这种享受向资本家——房东交钱。连住在一个角落、地下室和阁楼里都要向房东交钱，更不用说住真正的房间或住宅了。不交钱——那就要被赶出门去。房租往往占去了工人收入的相当部分，约为工人每月收入的百分之十五到百分之二十五。在资本主义国家里，这种支出不仅从未减少过，而且还在不断增加。例如，在汉堡每一百马克的收入中（按战前的行情计算，每一马克相当于五十戈比）需要付出的房租是：","language":"中文","translation":false},{"id":"communism-abc-20-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"年收入900——1200马克者","language":"中文","translation":false},{"id":"communism-abc-20-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"年收入1200——1800马克者","language":"中文","translation":false},{"id":"communism-abc-20-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"年收入1800——2400马克者","language":"中文","translation":false},{"id":"communism-abc-20-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"年收入6000——9000马克者","language":"中文","translation":false},{"id":"communism-abc-20-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"年收入30000——60000马克者","language":"中文","translation":false},{"id":"communism-abc-20-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"年收入超过60000马克者","language":"中文","translation":false},{"id":"communism-abc-20-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"由此可见，收入越少，房租在收入中所占的百分比就越大，而且每年这一部分增加得就越快。相反，资产阶级在每一百卢布的收入中花在房租支出上的百分比几乎要少六分之五，而且这个百分比不但没有增加，反而减少。","language":"中文","translation":false},{"id":"communism-abc-20-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"第一百二十六节 无产阶级国家的住宅问题","language":"中文","translation":false},{"id":"communism-abc-20-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"无产阶级革命在住宅方面进行了彻底的改革。苏维埃政权将资产阶级的房屋收归国有，并根据不同的情况取消了工人所欠的房租，或降低了房屋的租金。现已开始制订并部分地实行了住在收归国有的房屋里的工人免交任何房租的计划。其次，在一些最大城市里，正在有计划地让住在地下室、破旧房屋和卫生条件很差的街区里的工人迁到资产阶级的独家住宅和中心街区的大房子里去。除此之外，还在开始有计划地向工人供应家具和一切生活用品。","language":"中文","translation":false},{"id":"communism-abc-20-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"共产党的任务是继续执行这项政策，改善住房事业，反对把收归国有的房屋闲置起来的现象，不允许这些房屋的修缮和清洁工作恶化下去，要维护好所有的电线、下水道、暖气等等设备。","language":"中文","translation":false},{"id":"communism-abc-20-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"苏维埃政权在把资本家的大房产全面收归国有的时候，并没有任何必要去触动小房产主（工人、职员或普通居民中的房产主）的利益。在一些省份曾出现过对一些不大的房屋也广泛收归国有的做法，结果造成了对这些收归国有的大小房屋的无人负责的现象，房屋开始毁坏，常常没有人愿意住进去，同时还在小房产主中间引起了对苏维埃政权的抱怨和不满情绪。","language":"中文","translation":false},{"id":"communism-abc-20-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"由于停止了新的建筑工程，苏维埃政权在城市面临着严重的住房危机，在这种情况下，苏维埃政权为了合理地分配所有公民的住房曾进行了大量的工作。各苏维埃房产局对城市中的空闲住房进行了登记，并按照一定的计划把住户们迁进这些住房。同时这些房产局还调查了每个大城市的所有房屋的数量和面积，并且对那些超过了住房标准的家庭和个人的住房面积进行了压缩。","language":"中文","translation":false},{"id":"communism-abc-20-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"随着卫国战争和生产破坏的结束，城市居民的人数开始大大增加。逃到农村的无产阶级陆续回到城市。农村的多余人口也不断来到城市。这样，苏维埃政权将面临着新的建筑工程问题，即满足共产主义社会住宅需求的建筑工程问题。至于哪一种类型的建筑好，是带有全套设备、花园、公共食堂等等的大房子好，还是设备完善的工人小住宅好，现在还很难说。不过有一点是很清楚的，住宅的规划不应同工业与农业结合的规划相抵触。它应该促使城市向城郊的农业地区发展，而不应该使几十万人和几百万人都密集在一个地方，使人们呼吸不到新鲜空气，远离大自然而过早地死去。","language":"中文","translation":false},{"id":"communism-abc-20-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十七章 共产党人关于住宅问题的纲领","page":20,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/19.htm","text":"第十七章书目：恩格斯《论住宅问题》。费捷罗维奇《工人的住所》。杰缅季耶夫《工厂，它对居民的利弊》。斯维特罗夫斯基《西方和俄国的住宅问题》。波克罗夫斯卡娅《英国工人住宅的改善》。","language":"中文","translation":false},{"id":"communism-abc-21-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-21-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第十八章 劳动保护和社会保护[1]","language":"中文","translation":false},{"id":"communism-abc-21-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第一百二十七节 什么是劳动保护","language":"中文","translation":false},{"id":"communism-abc-21-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第一百二十八节 劳动保护的主要方面","language":"中文","translation":false},{"id":"communism-abc-21-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第一百二十九节 俄国在劳动保护方面做了哪些事情","language":"中文","translation":false},{"id":"communism-abc-21-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第 一百三十 节 什么是社会保证","language":"中文","translation":false},{"id":"communism-abc-21-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第一百三十一节 社会保证的主要方面","language":"中文","translation":false},{"id":"communism-abc-21-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第一百三十二节 在社会保证方面做了哪些事情","language":"中文","translation":false},{"id":"communism-abc-21-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第一百三十三节 改善工人阶级状况的其他措施","language":"中文","translation":false},{"id":"communism-abc-21-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"· 第一百三十四节 党的今后任务","language":"中文","translation":false},{"id":"communism-abc-21-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百二十七节 什么是劳动保护","language":"中文","translation":false},{"id":"communism-abc-21-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"工人阶级之所以要为争取共产主义制度而斗争，是因为这个制度能使它摆脱剥削，并能把生产力发展到这样的高度，以致人们不再为生产最必要的物品而成天地疲于奔命。因此，工人阶级在自己走向共产主义的道路上取得的一切成就，实质上也就直接或间接地成为一种劳动保护，因为这些成就有助于劳动力状况的改善。以苏维埃共和国工人阶级的政治自由和作为统治阶级的工人阶级的状况为例，很明显，这种政治状况从劳动保护的意义上来说是前进了一步。关于工人阶级的一切成就也完全可以这样说。然而，应当把“劳动保护”的这种广义的概念同更为专门的概念区别开来。这里谈的不是工人阶级的一般状况，而是工人阶级在工厂、矿山里的状况，换句话说，是工人阶级在劳动本身过程当中的状况。确实，在工厂里的工作，机器那么多，而且常常四周充满有毒气体，是非常危险的。这种危险由于劳动时间过长而变得更加严重，因为劳动时间过长会使工人精疲力竭，注意力减弱，从而使工作事故增加。况且劳动时间过长本身就严重地有害于身体健康。","language":"中文","translation":false},{"id":"communism-abc-21-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"为了说明劳动者的状况同劳动环境和劳动条件的关系，实际上有了上面的那些例子就已经足够了。但是这里仍然有必要在这点上说得更为详细一些。","language":"中文","translation":false},{"id":"communism-abc-21-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"一、首先是关于“工伤事故”的问题。下面列举几个数字。在彼得堡的涅瓦造船厂有关工伤事故的统计如下：","language":"中文","translation":false},{"id":"communism-abc-21-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"每一千名工人中受害者的人数","language":"中文","translation":false},{"id":"communism-abc-21-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"工伤事故下降的原因主要是由于采取了许多特殊的措施，但即使是这样，一千名工人中仍有二百一十人受害，这是个巨大的数字。","language":"中文","translation":false},{"id":"communism-abc-21-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"工伤事故伤害的人数有时达到全部工人的百分之七十。据一位医生证明，在叶卡特林诺斯拉夫省，野外作业使得那里的地方医院变得就象战时的急救室一样。当然，工伤事故不仅在俄国有，而且在其他各地方也都有。在英国社会里，社会主义者麦唐纳曾引用过一个数据，说明在矿山死去的一千二百人中，有一千一百人的死因是因为资本家没有采取最起码的安全措施而造成的。","language":"中文","translation":false},{"id":"communism-abc-21-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"上述最后一个例子向我们表明，只要资本家愿意，工伤事故是可以大大减少的。但是，在资本家看来，花钱添置许多必要的设备是不上算的。","language":"中文","translation":false},{"id":"communism-abc-21-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"二、有害的劳动环境和由此而产生的职业病、死亡率等等，这是第二个主要问题。","language":"中文","translation":false},{"id":"communism-abc-21-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"以磷厂的情况为例。据拉扎烈夫的材料证明，俄国的这类工厂设备没有任何改进，只要在其中劳动五年就足以把人变为“活尸”。化工厂、玻璃厂、矿山等等的生产引起了一系列所谓的职业病。而在其他生产中也可以看到类似的现象：站着劳动的人会患静脉曲张，工人经常接触磷会造成颌骨损伤，另外还发现许多部门的工人都患有汞、砷中毒和肺结核（肺痨）等等现象。","language":"中文","translation":false},{"id":"communism-abc-21-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"英国每年每千人中死于肺结核的人数（1900——1902年）：","language":"中文","translation":false},{"id":"communism-abc-21-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"僧侣…………………………………………………………每千人中为55人","language":"中文","translation":false},{"id":"communism-abc-21-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"农业和畜牧业………………………………………………每千人中为76人","language":"中文","translation":false},{"id":"communism-abc-21-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"律师和公证人………………………………………………每千人中为92人","language":"中文","translation":false},{"id":"communism-abc-21-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"官员…………………………………………………………每千人中为129人","language":"中文","translation":false},{"id":"communism-abc-21-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"玻璃生产……………………………………………………每千人中为283人","language":"中文","translation":false},{"id":"communism-abc-21-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"陶瓷生产……………………………………………………每千人中为285人","language":"中文","translation":false},{"id":"communism-abc-21-28","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":28,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"排字工人……………………………………………………每千人中为300人","language":"中文","translation":false},{"id":"communism-abc-21-29","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":29,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"鬃毛业………………………………………………………每千人中为325人","language":"中文","translation":false},{"id":"communism-abc-21-30","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":30,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"刀叉生产……………………………………………………每千人中为583人","language":"中文","translation":false},{"id":"communism-abc-21-31","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":31,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"矿工………………………………………………………………579——816人","language":"中文","translation":false},{"id":"communism-abc-21-32","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":32,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"根据巴拉诺夫医生的材料，无产阶级中死于肺结核的比例是：","language":"中文","translation":false},{"id":"communism-abc-21-33","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":33,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"卷烟女工………………………………………………………63.4%","language":"中文","translation":false},{"id":"communism-abc-21-34","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":34,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"刻版工…………………………………………………………58.3%","language":"中文","translation":false},{"id":"communism-abc-21-35","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":35,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"排字工…………………………………………………………53.1%","language":"中文","translation":false},{"id":"communism-abc-21-36","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":36,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"成衣工…………………………………………………………50.9%","language":"中文","translation":false},{"id":"communism-abc-21-37","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":37,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"石刻工…………………………………………………………50.6%","language":"中文","translation":false},{"id":"communism-abc-21-38","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":38,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"钳工、车工、鞋匠、装订工、白铁工………………………46-47%","language":"中文","translation":false},{"id":"communism-abc-21-39","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":39,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"制盒工和细木工………………………………………………45-45.5%","language":"中文","translation":false},{"id":"communism-abc-21-40","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":40,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"根据德国的统计资料，在佐林根市的磨床工和五金工人中，肺结核病的死亡率比这个病的平均死亡率高出三倍。","language":"中文","translation":false},{"id":"communism-abc-21-41","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":41,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"三、由于恶劣的劳动条件，除了发生明显的疾病以外，工人阶级的机体也在全面退化。从征兵时发现淘汰率增长的现象里就可以看出这一点。肺弱和身矮小的人数在逐年增加，而且这类人在无产阶级中间比在其他居民阶层中间要多得多。在瑞士，身体有毛病的工人人数占整个参加体检人数的百分之三十九点五，而农村居民中身体有毛病的人数只占百分之二十五。在其他国家中也可以看到这一点。妇女的机体普遍退化，因而有些人完全丧失了生育能力。","language":"中文","translation":false},{"id":"communism-abc-21-42","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":42,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"任何人都可以看到，所有这一切通通都是和生产条件有关的。资产阶级根本不关心劳动保护，他们对劳动力采取惨无人道的政策：榨干了血汗以后便把人扔出门去了事。最“进步的”美国资本采取的也是这样的政策。在那里，工厂只招收身体健康的人，甚至从各个方面察看和触摸他们的肌肉。气力小的工人根本不允许进入这个国家，他们被认为是劣等牲口。但是在美国，工人能活到四十五岁的微乎其微。“资本”老爷用最先进的方法榨尽了工人们的全部血汗。","language":"中文","translation":false},{"id":"communism-abc-21-43","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":43,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"不言而喻，无产阶级专政第一次有可能把劳动保护真正提到日程上来。工人阶级最关心保护劳动力。它必须提出以最细心的态度来对待这种最宝贵和最重要的生产力的问题。共产主义制度不能建立在对人力的无意义的、罪恶的和有害的浪费的基础上，而应该建立在高度的目的在于保护这些人力的技术基础上。这就是为什么劳动保护在人类生活向共产主义过渡的时期具有如此重大意义的原因。","language":"中文","translation":false},{"id":"communism-abc-21-44","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":44,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"所以，劳动保护就意味着在有害于健康的生产条件下对劳动者的保护。","language":"中文","translation":false},{"id":"communism-abc-21-45","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":45,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百二十八节 劳动保护的主要方面","language":"中文","translation":false},{"id":"communism-abc-21-46","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":46,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"保护工人阶级，防止工人阶级机体退化、患病和死亡率提高等等的最重要的条件是实行正常的工作日。因而毫不奇怪，工人阶级总是把缩短工作日的斗争作为自己斗争的重点。工作日决定着人们的精力的消耗，这种消耗转化为产品，而在资本主义社会则转化为资本家的利润，因而资本家对延长工作日最为关心。工人过度地耗费自己的精力就会削弱继续劳动的能力：工人的“磨损”加快，身体日益衰弱，更容易得病并很快死去。过分延长的工作日是对人的精力的强盗式的掠夺，劳动保护的第一个方面就是确定正常的工作日。","language":"中文","translation":false},{"id":"communism-abc-21-47","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":47,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第二方面是保护工人阶级中体力比较弱的人。工人阶级并不仅仅由成年的男子组成。还包括老人、小孩、少年和各种年龄的妇女。显然，工人阶级中的各部分人对有害环境的抵抗力是各不相同的。有些事情成年男子做起来并不困难，也无损于自己的健康，但对于妇女可能是极其有害的（例如搬运重物），而对少年则可能是极度危险的。此外，妇女在生活中的某些时候需要特殊的保护（怀孕、分娩、哺乳期等等）。这就需要一些特殊的措施。这就是妇女和儿童的劳动保护。","language":"中文","translation":false},{"id":"communism-abc-21-48","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":48,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"最后，第三方面，工厂的技术和卫生设备是十分重要的。在同工伤事故、同生产的有害影响和劳动的恶劣条件（尘埃、光线暗、寒冷、过堂风、污秽等等）进行斗争方面可以而且应该做极大量的工作。","language":"中文","translation":false},{"id":"communism-abc-21-49","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":49,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"这就是“劳动保护”工作的三个主要方面。","language":"中文","translation":false},{"id":"communism-abc-21-50","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":50,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百二十九节 俄国在劳动保护方面做了哪些事情","language":"中文","translation":false},{"id":"communism-abc-21-51","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":51,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"无产阶级专政已经创造了充分的条件，使它可以完全实行所有社会党提出的那些要求。在这方面，世界上没有任何一个国家的法律比得上苏维埃共和国的法律。我们的事故尽管还很多，但是这并不是由于法律不好，而是由于我们的东西太少，许多东西都很缺乏。然而这一点，正如我们上面所看到的，是由于世界帝国主义反对我们的斗争，由于工人阶级的敌人——帝国主义之间的战争所造成的。","language":"中文","translation":false},{"id":"communism-abc-21-52","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":52,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"至于我们在劳动保护方面做了哪些工作和苏维埃共和国作了哪些法律规定，归结起来可以得出下面几种情况：","language":"中文","translation":false},{"id":"communism-abc-21-53","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":53,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"在这方面苏维埃政权实行了一系列的措施。","language":"中文","translation":false},{"id":"communism-abc-21-54","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":54,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"1、彻底实行八小时工作日，并以法律形式固定下来（妥协主义政府力图逃避这一点），对脑力和办公室的劳动则定为六小时工作日。","language":"中文","translation":false},{"id":"communism-abc-21-55","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":55,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"2、通常禁止加班，只是在特殊情况下才可以允许加班，但要限制时间，工资应该按一倍半计算。","language":"中文","translation":false},{"id":"communism-abc-21-56","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":56,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"3、把特别有害于健康的生产部门的工作日缩短，例如烟草部门缩短为七小时，煤气部门为六小时。","language":"中文","translation":false},{"id":"communism-abc-21-57","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":57,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"4、每周规定要有四十二小时的政党休息（因此把每星期六的工作日普遍缩短到六小时）。如果有谁星期日得不到休息，他就可以在一星期中的任何一天补休。","language":"中文","translation":false},{"id":"communism-abc-21-58","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":58,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"5、每个劳动者每年有一个月的休假，工资照付（根据劳动法典），在当前困难时期（1919年秋）休假定为两周。","language":"中文","translation":false},{"id":"communism-abc-21-59","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":59,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"6、对于在特别有害于健康的生产部门工作的人和教养院里的少年，额外多给两周的休假。","language":"中文","translation":false},{"id":"communism-abc-21-60","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":60,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"二、妇女和儿童的劳动保护。","language":"中文","translation":false},{"id":"communism-abc-21-61","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":61,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"1、通常禁止妇女做夜班、加班加点或做零工。","language":"中文","translation":false},{"id":"communism-abc-21-62","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":62,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"2、禁止招收未满十六岁的少年参加劳动。要把他们逐步从工作岗位上替下来（首先是从有害于健康的生产部门），同时要向他们提供物质保障，并安排他们上学。","language":"中文","translation":false},{"id":"communism-abc-21-63","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":63,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"3、缩短未成年的人的工作日（对留在工作岗位上的童工的工作日定为四小时。对于十六至十八岁的少年定为六小时）。","language":"中文","translation":false},{"id":"communism-abc-21-64","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":64,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"4、禁止所有未满十八岁的人加班加点、做夜班和做零工。","language":"中文","translation":false},{"id":"communism-abc-21-65","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":65,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"为作母亲的妇女的劳动保护专门实行了下列法律：","language":"中文","translation":false},{"id":"communism-abc-21-66","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":66,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"1、规定给所有的孕妇和产妇以补助金，包括女工本人和男工的妻子在内，在怀孕和生产时脱离劳动的整个期间，工资照付。","language":"中文","translation":false},{"id":"communism-abc-21-67","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":67,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"2、对从事体力劳动的孕妇，给予八周的产前假期，对从事脑力劳动和办公室外工作的孕妇给予六周的产前假。","language":"中文","translation":false},{"id":"communism-abc-21-68","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":68,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"3、对上述产妇分别给予六周和八周的产后假。","language":"中文","translation":false},{"id":"communism-abc-21-69","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":69,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"4、哺乳的女工在工作时每隔三小时有一次半小时的喂奶时间。","language":"中文","translation":false},{"id":"communism-abc-21-70","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":70,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"5、发给所有的母亲以七百二十卢布的婴儿护理用品补贴，在产后的九个月内，每天发给二十四卢布的婴儿伙食补助。","language":"中文","translation":false},{"id":"communism-abc-21-71","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":71,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"在已实行的措施中，有某些脱离“劳动法典”的做法。这些做法表现为，在非常时期，容许加班加点，但一年仅限五十天；允许十四岁至十六岁的少年参加劳动，限定工作日为四小时；暂时将为期一个月的休假改为两星期；夜班工作时间可以增加到七小时。","language":"中文","translation":false},{"id":"communism-abc-21-72","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":72,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"所有这些退一步的做法都是由于世界帝国主义势力对苏维埃共和国穷凶极恶的进攻所造成的极其困难的局势而产生的。","language":"中文","translation":false},{"id":"communism-abc-21-73","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":73,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"三、工厂的技术和卫生设备。","language":"中文","translation":false},{"id":"communism-abc-21-74","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":74,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"1、颁布了一系列旨在大大改进工厂劳动条件的有关技术安全、清洁和职业卫生的强制性决定。","language":"中文","translation":false},{"id":"communism-abc-21-75","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":75,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"2、在所有在害健康的生产部门要发给防尘、防瓦斯、防潮等等的专门服装。","language":"中文","translation":false},{"id":"communism-abc-21-76","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":76,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"3、给所有的工人发工作服，工作服是企业的财产，供工人们在劳动时使用。","language":"中文","translation":false},{"id":"communism-abc-21-77","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":77,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"4、为了真正实现在劳动保护方面的所有创举，建立了由广泛的工人代表会议选举出来的劳动检查院。对于某些劳动条件特殊或工作人员分散的工种（运输、建筑、农业等），由相应的联合会选举出专门的区段性的劳动检查院。","language":"中文","translation":false},{"id":"communism-abc-21-78","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":78,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"下面是较为详细的材料（截止于1919年8月1日）","language":"中文","translation":false},{"id":"communism-abc-21-79","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":79,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"检查员的职业 占总人数的百分比 占职业已查清的","language":"中文","translation":false},{"id":"communism-abc-21-80","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":80,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"总人数的百分比 工人…………112人 54.5% 62.5% 技师、技术员、绘图员…1人 10% 11.5% 职员（商业与办公室人员）……28人 13% 15.5% 医士……4人 2% 2% 药剂师……1人 0.5% 0.5% 教师……5人 2% 2.5% 大学生……4人 2% 2% 医生……5人 2.5% 2.5% 工程师……1人 0.5% 0.5% 法学家……1人 0.5% 0.5% 尚未查清者……28人 13%","language":"中文","translation":false},{"id":"communism-abc-21-81","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":81,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"和在这之前的那半年相比，工人的数量略有增加（由原来的47%增加到54.5%，从占已查清的总人数的60%增加到62.5%）；技师和技术员的百分比几乎未变（从10%增加到11%）；职员的人数有较大增加（从8%增加到13%）。大学生人数的比例减少了三分之二（从6%减到2%），绝对数量则减少了一半（从8%减到4%），其他小工种的人数几乎未变。","language":"中文","translation":false},{"id":"communism-abc-21-82","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":82,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"由此可见，我们确实有了一套真正的工人检查机构，无论从它的任务还是从它的成分来看，都是属于工人的。","language":"中文","translation":false},{"id":"communism-abc-21-83","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":83,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"然而，正是在工厂里的劳动保护方面还有许多事情需要去做。许多地方的劳动条件还相当恶劣，特别是一些落后的企业，那里的工人组织得很不好，自觉性和文化水平都很低。在这些角落里，一切或者几乎一切都仍然照旧。的确，要进行必要的改进往往是不可能的，因为这需要增添新的设备和装备。但是，如果把广大群众吸引到改善劳动环境的工作中来，那么即使不新添也还是可以做出不少的事情来。","language":"中文","translation":false},{"id":"communism-abc-21-84","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":84,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百三十节 什么是社会保证","language":"中文","translation":false},{"id":"communism-abc-21-85","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":85,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"正如我们所看到的，资本主义制度的目的就是从工人阶级身上榨取利润，雇佣工人即无产阶级无非是资本家追逐暴利的工具。一旦这个活的工具坏掉，或是变得不中用或成为多余，它马上就会象一只被挤干了的柠檬皮或鸡蛋壳一样，被无情地抛弃掉。资本对于失业的灾难、疾病、衰老、残废全然不管：它把大批大批的人赶出大门，甚至根本就没有想到要帮助他们，即使有所帮助，那也仅仅是帮助那些最忠于自己的人，即那些已被它榨取了全部脂膏的可靠的官员。","language":"中文","translation":false},{"id":"communism-abc-21-86","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":86,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"在苏维埃共和国，劳动者和贫民不是剥削的对象。但是这并不是说我们就没有巨大的灾难。我们的国家受尽了敌人的摧残。从四面八方遭到封锁，煤、石油和原料的供应均被切断，灾难是巨大的。不是资本家把工人抛出了工厂，而是由于缺乏燃料和原料，工厂有时不得不停工，这样就造成了人们的失业。这不是过去那种类型的失业，它完全是由于其他原因而产生的，但失业毕竟还是存在。帝国主义战争给我们留下了残废者和重伤号；我们大量的反革命的受害者；有老人、病人和儿童——所有这些人都应该得到关怀和资助。工人政府并不认为对所有这些人的帮助是施舍、恩赐或行善。帮助这些人，特别是帮助那些从劳动战线和红军队伍里下来的伤病员，是工人国家的直接义务。","language":"中文","translation":false},{"id":"communism-abc-21-87","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":87,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"我们的最终目的是要造成一种社会现象：所有的人，不管由于什么原因失去劳动能力而不能工作时，都能得到充分的保证：老人能有安静的晚年和舒适的生活；儿童能有他们童年所必需的一切；病人和残废者能生活在良好的、最适合于他们的环境中；身体疲劳和虚弱的人能得到如同过去最富有的资产者才能得到的治疗；人们不会再为想起“黑暗时代”而经常心惊胆寒。","language":"中文","translation":false},{"id":"communism-abc-21-88","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":88,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"当然，这一点同我们当前的状况大不一样。由于全世界强盗们的捣乱，我们现在成了一个贫穷的国家。我们连最普通的东西都没有：例如药品，帝国主义者不向我们出口，因为他们封锁我们……但是苏维埃政权有一点是毫不含糊的，那就是只要有可能去帮助那些丧失劳动能力的人和保障他们的生活，苏维埃政权是不会吝惜钱的。","language":"中文","translation":false},{"id":"communism-abc-21-89","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":89,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百三十一节 社会保证的主要方面","language":"中文","translation":false},{"id":"communism-abc-21-90","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":90,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"社会保证主要有两个方面。第一，对从事某种劳动的（体力的或脑力的）丧失劳动能力或失去工作的人给予保证。这里包括失业和丧失劳动能力的情况；有的是暂时的（疾病、受伤、怀孕、分娩），有的是长久的（残废、年老、长期的慢性病）。第二，对不是在工作中和生产中受害或丧失劳动能力的人给予保证。这里包括过去战争中的残废者、受伤的红军战士、红军战士的家属、反革命的受害者、各种自然灾害的受害者（火灾、水灾、流行病等等）。最后，对于其他的丧失劳动能力的人，即旧的社会制度和腐朽的社会关系的受害者，也必须给予关怀。属于这一类的人有乞丐、流浪者和无依无靠的人、有残疾的人（机体退化的人、疾呆者等等）。","language":"中文","translation":false},{"id":"communism-abc-21-91","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":91,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"此外，对遇有丧事的家庭也要给予帮助。","language":"中文","translation":false},{"id":"communism-abc-21-92","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":92,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"所有这些应该给予保证的人数量是相当大的。其中的第一类人（丧失劳动能力或失去了工作的，但这些人都是与生产有联系的）归劳动人民委员部管，该部实际上掌握在工会手里；第二类人由社会保证人民委员部管。","language":"中文","translation":false},{"id":"communism-abc-21-93","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":93,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百三十二节 在社会保证方面做了哪些事情","language":"中文","translation":false},{"id":"communism-abc-21-94","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":94,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"整个说来，苏维埃政权对于各种丧失了劳动能力的劳动者，其中包括失业者，都给予了保证，这在世界上是从未有过的。","language":"中文","translation":false},{"id":"communism-abc-21-95","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":95,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"对第一类受保证的人实行了如下措施：","language":"中文","translation":false},{"id":"communism-abc-21-96","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":96,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"1、所有从事“雇佣劳动”的人一律免交社会保险费。","language":"中文","translation":false},{"id":"communism-abc-21-97","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":97,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"2、所有企业主均被禁止插手社会保证和劳动保护组织的工作，所有这些机构都是在各工人组织代表选举的基础上产生的。","language":"中文","translation":false},{"id":"communism-abc-21-98","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":98,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"3、对各种丧失劳动能力和失业的人都给予保证。","language":"中文","translation":false},{"id":"communism-abc-21-99","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":99,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"4、劳动者的家庭成员遇有死亡情况时均给予保证。","language":"中文","translation":false},{"id":"communism-abc-21-100","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":100,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"5、劳动者在生病、受伤、检疫隔离和其他原因而暂时失去劳动能力时，工资照付。","language":"中文","translation":false},{"id":"communism-abc-21-101","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":101,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"6、对所有的劳动残废者，不管其残废的原因是什么（年老、伤残、职业病等等），不管其工龄有多长，均给予生活补助，数额每月为一千八百卢布（在莫斯科市区）。","language":"中文","translation":false},{"id":"communism-abc-21-102","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":102,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"7、发给丧葬费，劳动者的丧葬费为一千四百四十卢布，家属的丧葬费，视其年龄大小的不同，定为四百卢布至八百卢布。","language":"中文","translation":false},{"id":"communism-abc-21-103","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":103,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"8、在劳动者死亡的情况下，给予其家庭经抚恤金待遇，视其家庭人口多少，每月最多可发给一千二百卢布（在莫斯科市区）。","language":"中文","translation":false},{"id":"communism-abc-21-104","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":104,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"9、为了更合理地解决有关补助金的使用问题，在各劳动局内设有专门确定补助金用途的工人委员会。","language":"中文","translation":false},{"id":"communism-abc-21-105","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":105,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"10、各省设有由工人主持的鉴定局，由鉴定局来确定残废的等级。","language":"中文","translation":false},{"id":"communism-abc-21-106","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":106,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"11、各县设有由工人主持的监督委员会，专门对治疗情况和对病人进行检查和监督。","language":"中文","translation":false},{"id":"communism-abc-21-107","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":107,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"12、为了保证工作更接近于基层，在工人生活的各个地方建立了一些接受有关补助申请和发放补助金的点，在一些大企业里发放补助金的工作由企业本身负责。","language":"中文","translation":false},{"id":"communism-abc-21-108","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":108,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"13、取消补助金的期限。现在对病假的补助是发到本人痊愈为止，对丧失劳动能力的人的补助一直发到死。","language":"中文","translation":false},{"id":"communism-abc-21-109","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":109,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"14、对所有从事雇佣劳动的人，对手工业者和农民，都一律实行社会保证。","language":"中文","translation":false},{"id":"communism-abc-21-110","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":110,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"15、1919年下半年共和国用于工人和职员保证方面的拨款为五十亿卢布。","language":"中文","translation":false},{"id":"communism-abc-21-111","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":111,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"在第二类受保证的人中，特别重要的是对红军战士的家庭和对红军战士本人的保证。","language":"中文","translation":false},{"id":"communism-abc-21-112","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":112,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"红军战士——残废军人在完全丧失劳动能力（超过百分之六十）的情况下获得的残废金相当于他所在地区中等工资的数量；残废金的数额根据丧失劳动能力的程度来定（丧失劳动能力百分之十五至三十的，领取的数额可以定为工资的五分之一）；红军战士的土地应该得到代耕，并应供给播种材料；按其家庭没有劳动能力的成员的数量发给口粮；红军的家属免交房租，并发给粮食补助配给证；一旦红军战士死亡，其家中无劳动能力和生活无着的成员或获得抚恤金，如果家庭中有一个无劳动能力的成员，抚恤金的数额可定为该地区中等工资的百分之六十，如有三个或三个以上无劳动能力的成员，抚恤金的数额可定为中等工资的百分之百，等等，等等。","language":"中文","translation":false},{"id":"communism-abc-21-113","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":113,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"1919年上半年给予红军家属的补助金达到十二亿卢布，下半年又拨款三十五亿卢布。根据维诺库罗夫同志的材料，到1919年秋，已在约有四百五十万红军战士的家庭领得了补助金。","language":"中文","translation":false},{"id":"communism-abc-21-114","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":114,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"此外，从1919年7月4日到12月1日，还拨出了这样一些款项：","language":"中文","translation":false},{"id":"communism-abc-21-115","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":115,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"给各省的拨款………………………………………………25亿多卢布","language":"中文","translation":false},{"id":"communism-abc-21-116","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":116,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"支援农业的拨款……………………………………………2亿卢布","language":"中文","translation":false},{"id":"communism-abc-21-117","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":117,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"用于住房需要的拨款…………………………………………1.5亿卢布","language":"中文","translation":false},{"id":"communism-abc-21-118","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":118,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"红军战士的复员费……………………………………………1亿卢布","language":"中文","translation":false},{"id":"communism-abc-21-119","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":119,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"残废军人的补贴………………………………………………1.68亿卢布","language":"中文","translation":false},{"id":"communism-abc-21-120","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":120,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"社会保证工作中最严重的缺点之一是我们的机构工作不力：对需要得到保证的人进行的统计工作做得不好，没有很好地把钱送到各地方上去，社会保证人民委员部各机关中的工作拖拖拉拉等等。改善组织机构已成为我们党的一项必不可少的任务。","language":"中文","translation":false},{"id":"communism-abc-21-121","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":121,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百三十三节 改善工人阶级状况的其他措施","language":"中文","translation":false},{"id":"communism-abc-21-122","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":122,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"除了上述措施之外，劳动法汇编（法典）中所收入的一系列其他措施对于改善工人阶级的状况有着巨大的意义。这些措施的直接根据是：无产阶级是统治阶级，因而它所提出的要求要比所有社会纲领中所提出的要求走得更远。这些措施主要有三点：","language":"中文","translation":false},{"id":"communism-abc-21-123","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":123,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一，工人组织参与解决工人的雇用及解雇问题。这个问题由工厂委员会和工人管委会决定。","language":"中文","translation":false},{"id":"communism-abc-21-124","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":124,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第二，工资由国家来调整。这里最值得注意的是，工资率由工会拟定，并通过劳动人民委员部执行，该部实际上是由工会运动的代表组成的。","language":"中文","translation":false},{"id":"communism-abc-21-125","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":125,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第三，失业者的工作必须由苏维埃和工会下属的特别机构（即所谓的劳动力分配统计局）来负责安排。","language":"中文","translation":false},{"id":"communism-abc-21-126","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":126,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"这一切措施是与所有工人组织，首先是工会的统治地位密切相关的。","language":"中文","translation":false},{"id":"communism-abc-21-127","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":127,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第一百三十四节 党的今后任务","language":"中文","translation":false},{"id":"communism-abc-21-128","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":128,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"最重要的任务是尽可能彻底和广泛地实现苏维埃政权的法令和决定。常常有这样的情况，即现实和法令不一致，纸上说的是一回事，而在生活中看到的又是另一回事。要保证充分、准确和正确地实现所有的措施，首先要有得当的组织机构，通过这个机构使中央与地方，地方与中央结合起来。而要做到这一点，那就需要广泛地吸收群众本身来参加这一工作。为此目的，就必须：","language":"中文","translation":false},{"id":"communism-abc-21-129","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":129,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"1、加强组织和扩大劳动检查院的工作；必须把工人当中的新生力量不断吸收到这个组织中来；任何人都不会比工人更熟悉劳动条件，更能发现各种缺点，更能采取消除这些缺点的实际措施。","language":"中文","translation":false},{"id":"communism-abc-21-130","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":130,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"2、必须加强对小工业和家庭工业的检查。这种工业往往很容易被人忽略。可是恰恰在这里劳动条件是最恶劣的。工人检查院在这个领域里是大有可为的。","language":"中文","translation":false},{"id":"communism-abc-21-131","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":131,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"3、必须广泛开展各个领域里的劳动保护工作，其中包括建筑工人、水陆运输工人、女仆和农业工人的劳动保护工作。这些分散、难于组织的部门同样应当被纳入到总的规划中来。","language":"中文","translation":false},{"id":"communism-abc-21-132","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":132,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"4、必须彻底禁止吸收童工工作，并大大缩短未成年工的工作日。","language":"中文","translation":false},{"id":"communism-abc-21-133","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":133,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"从我们党的观点看来，作为劳动保护的基础的八小时的工作日，绝不是缩短劳动时间的最终极限。从这一观点看来，一种事先定好的界限是没有的。这里一切都取决于劳动生产率的状况。现在，一般生产下降的情况极其严重，并仍然继续遭到破坏，在这种情况下，工作日不可能象通常那样缩短；有时甚至（根据战争的发展状况等等）还可能增加。但是，只要一有可能，我们就将对所有的工人实行正常的六小时的工作制，如同现在对许多职员已经实行了的一样。","language":"中文","translation":false},{"id":"communism-abc-21-134","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":134,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"另一方面，为了提高劳动生产率和不断提高劳动力的质量，实行工资奖励制度是很有益的。","language":"中文","translation":false},{"id":"communism-abc-21-135","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":135,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"党在解决社会保证的总任务时，决不是从行善或鼓励寄生虫和懒汉的思想出发；帮助需要帮助的人，这是无产阶级政权的义务，就象帮助那些游手好闲的人回到劳动生活中去是它的义务一样。","language":"中文","translation":false},{"id":"communism-abc-21-136","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":136,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"第十八章书目：卡普隆《劳动保护及其机构》。马留金《通向共产主义光辉事业的道路》。黑尔费尔博士《无产阶级革命和无产阶级的社会保证》。普雷斯教授《什么是社会技术？》，《劳动通报》和社会保证人民委员部出版物中的文章。哥尔茨曼《冶金工业中的奖励制度》。","language":"中文","translation":false},{"id":"communism-abc-21-137","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十八章 劳动保护和社会保护","page":21,"paragraph":137,"url":"https://www.marxists.org/chinese/bukharin/1919/20.htm","text":"[1] 这一章是由布哈林写的。","language":"中文","translation":false},{"id":"communism-abc-22-1","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":1,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"中文马克思主义文库 -> 布哈林│普列奥布拉任斯基 -> 《共产主义ABC》（1919）","language":"中文","translation":false},{"id":"communism-abc-22-2","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":2,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"· 第一百三十五节 专门人民保健的必要性","language":"中文","translation":false},{"id":"communism-abc-22-3","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":3,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"· 第一百三十六节 医疗机构的国有化","language":"中文","translation":false},{"id":"communism-abc-22-4","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":4,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"· 第一百三十七节 医务人员的劳动义务制","language":"中文","translation":false},{"id":"communism-abc-22-5","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":5,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"· 第一百三十八节 近期人民保健事业的任务","language":"中文","translation":false},{"id":"communism-abc-22-6","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":6,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"第一百三十五节 专门人民保健的必要性","language":"中文","translation":false},{"id":"communism-abc-22-7","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":7,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"资本主义总是让工人阶级居住在充满了传染病的肮脏的街区里。只有资产阶级本身受到传染威胁时，他们才会采取某些措施来改善一下这些受雇佣奴隶所有街区的卫生状况。那是在1784年，英国国会忽然慷慨起来，开始关心起工人来，这是因为，特别国会委员会查清了以下一个事实：可怕的伤寒传染病是从工厂里传过来的。资本主义与其说是关心居民的保健事业，不如说害怕资本家自己本身会生病。","language":"中文","translation":false},{"id":"communism-abc-22-8","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":8,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"帝国主义战争的后果使广大工人阶级的状况大大恶化。整个条件，加上饥饿和寒冷等等，导致了大规模的流行病：霍乱、斑疹伤寒从四面八方向人民袭来，新的病种“西班牙流行性感冒”接连出现。“新”病种的出现明显地与战争有关。人们劳累疲惫和虚弱不堪的身体再也经受不起疾病摧残了。世界各国的死亡率在异常提高，并具有真正的灾难性。","language":"中文","translation":false},{"id":"communism-abc-22-9","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":9,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"但是战争还留下了另一份遗产：花柳病，其中包括梅毒，广泛蔓延。先是大量士兵染上了这种病，后来又把这种病带到了广大农村。","language":"中文","translation":false},{"id":"communism-abc-22-10","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":10,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"花柳病从来没有蔓延得象现在这样厉害。","language":"中文","translation":false},{"id":"communism-abc-22-11","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":11,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"所有这一切都要求在人民保健方面进行专门的工作。当然，在与疾病的斗争中，许多事情还要通过其他办法才能解决，例如，正确地解决生活中的住房问题具有巨大的意义，因为随着工人住房的改善，传染病的根源会自然消失；另外，劳动保护也具有同样巨大的意义，因为谁都知道，几乎一切都取决于居民的饮食和营养状况。如此等等。","language":"中文","translation":false},{"id":"communism-abc-22-12","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":12,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"但是这丝毫也不排除采取一系列专门的全社会范围的措施的必要性。","language":"中文","translation":false},{"id":"communism-abc-22-13","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":13,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"现在连最起码的生活条件都很糟糕，所以在同病害的斗争中就更加需要给予各种帮助。这样就十分迫切地需要建立一种专门的社会工作部门即人民保健工作部门。","language":"中文","translation":false},{"id":"communism-abc-22-14","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":14,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"第一百三十六节 医疗机构的国有化","language":"中文","translation":false},{"id":"communism-abc-22-15","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":15,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"资本主义社会的医疗工作系统也是按照资本主义方式建立起来的。私人医院，疗养院，休养所，水疗、电疗和光疗机构，药房，诊所等等，都是从追逐利润着眼的。其中绝大多数都是专门为治疗肥胖病、痛风症和资本主义社会统治阶级所特有的其他贵族病开设的。工人是去不了疗养院的，休养所也没有任何工人的份。","language":"中文","translation":false},{"id":"communism-abc-22-16","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":16,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"制药业也完全是为赚钱的目的服务的。所有这些机构在经济方面同其他企业没有任何区别。","language":"中文","translation":false},{"id":"communism-abc-22-17","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":17,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"必须使所有这些机构从为资本家的钱袋服务改为劳动人民服务。要达到这一点，第一步就要对这些机构实行国有化。","language":"中文","translation":false},{"id":"communism-abc-22-18","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":18,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"第一百三十七节 医务人员的劳动义务制","language":"中文","translation":false},{"id":"communism-abc-22-19","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":19,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"由于存在大量的流行病和需要迅速地将它扑灭，所以有计划地、有组织地和大规模地同这些流行病进行斗争的问题便成为当务之急。在医务人员的数量比较起来不很多的情况下，自然就十分必要对他们进行登记，并动员他们到同流行病作斗争的第一线上去。","language":"中文","translation":false},{"id":"communism-abc-22-20","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":20,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"由于采取了这样的措施，即由于把几乎全部的医务人员，从名教授到一年级大学生和医士都统统利用起来，最后终于杜绝了霍乱和斑疹伤寒这些最严重的流行病的蔓延。","language":"中文","translation":false},{"id":"communism-abc-22-21","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":21,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"然而，医务人员的劳动义务制不单单具有这种“消防的”意义。它同医疗机构的国有化一样，是未来有组织的社会卫生保健事业的萌芽之一。","language":"中文","translation":false},{"id":"communism-abc-22-22","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":22,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"第一百三十八节 近期人民保健事业的任务","language":"中文","translation":false},{"id":"communism-abc-22-23","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":23,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"在最必要的物品（医院的食品、药品、医疗设备和用具等等）严重不足的情况下，工作是极其困难的。这一工作可归结为三个主要方面，发展这些方面的工作是我们党的目的。","language":"中文","translation":false},{"id":"communism-abc-22-24","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":24,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"第一，坚决实行广泛的卫生措施。这里必须提到改善居住区的卫生状况：许多传染病就是通过肮脏的水井、沟渠、积水沆、恶臭的“垃圾场”、污水池等等蔓延的。保护地面、水和空气是公共健康的首要条件。其次，这里还涉及到根据科学卫生的原则管理公共饮食业的问题；在我们的食品储存如此贫乏的情况下，当前这是一个很难完成的任务；但是在公共食堂、儿童食堂、医院以及所有的公共场所，要使伙食合乎卫生要求现在是有条件的。必须进一步采取措施，防止传染病的发展；要对机关、私人住宅和学校进行卫生检查；对水要进行过滤，组织供应开水的工作和消毒的工作，对内衣必须进行消毒等等，等等。","language":"中文","translation":false},{"id":"communism-abc-22-25","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":25,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"第二，必须有计划地同所谓“社会性疾病”进行斗争，这些疾病都带有群众性，它们的产生有着深刻的社会原因。这类疾病首先有三种：结核病，这是由恶劣的劳动条件引起的，花柳病，主要是随着战争蔓延开的，最后是酒精中毒，患这种病的人有的是由于野蛮和粗犷，有的是由于寄生性的堕落。这些病不仅影响到我们这一代，而且对我们的后代也有极大的影响。人们面临着极其严重的威胁，而且特别可怕，因为现在人们身体都很虚弱，这些疾病的危害性特别大。","language":"中文","translation":false},{"id":"communism-abc-22-26","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":26,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"最后，第三，必须保证居民人人都可享用免费的医疗和药物帮助。现在的困难是药品极其缺乏。这种困难与其说是由于我们的生产遭到破坏，不如说是由于封锁造成的，因为“人道的”盟国不仅想通过切断我们的原料和燃料的来源，通过“瘦骨棱棱的饥饿之手”来掐死我们，而且想通过流行病的蔓延来扼杀我们。这里的问题要靠我们同世界帝国主义进行总的斗争来解决。","language":"中文","translation":false},{"id":"communism-abc-22-27","author":"布哈林、普列奥布拉任斯基","title":"共产主义ABC","location":"第十九章 人民保健","page":22,"paragraph":27,"url":"https://www.marxists.org/chinese/bukharin/1919/21.htm","text":"第十九章书目：谢马什柯《苏联医学基础》。林杰曼教授《与斑疹伤寒作斗争的措施》，《卫生人民委员部一年来的工作》文集。","language":"中文","translation":false},{"id":"mao-poetry-1-1","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":1,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"中文马克思主义文库 -> 毛泽东 -> 1968年汉版《毛泽东思想万岁》","language":"中文","translation":false},{"id":"mao-poetry-1-2","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":2,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"098)","language":"中文","translation":false},{"id":"mao-poetry-1-3","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":3,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"给自己诗词作的解释","language":"中文","translation":false},{"id":"mao-poetry-1-4","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":4,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"我的几首词发表后，注家蜂起，全是好心。一部分说对了，一部分说的不对。我有说明的责任。一九五八年在广州，见一九五八年刊本，天头甚宽，因而，写了下面一些字，谢注家兼谢读者。鲁迅在一九二七年在广州修改他的《古小说钩沉》后记中说道：“于时云海沉沉，星月澄碧餮蚊逞强，于在广州。”从那时到今天，三十一年了，大陆上的蚊灭得差不多了。当然革命尚未全成，同志们仍需努力。港台一带，餮蚊尚多，西方世界，餮蚊成阵。安得其全世界各民族千百万愚公，用他们自己的移山办法，把蚊阵一扫而空，岂不伟哉！","language":"中文","translation":false},{"id":"mao-poetry-1-5","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":5,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"试仿陆放翁曰：","language":"中文","translation":false},{"id":"mao-poetry-1-6","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":6,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"人类今天上太空，但悲不见五洲同。愚公尽扫餮蚊日，公祭毋忘告马翁。","language":"中文","translation":false},{"id":"mao-poetry-1-7","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":7,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"毛泽东一九五八年十二月二十一日上午十时","language":"中文","translation":false},{"id":"mao-poetry-1-8","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":8,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"沁园春.长沙","language":"中文","translation":false},{"id":"mao-poetry-1-9","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":9,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九二五年","language":"中文","translation":false},{"id":"mao-poetry-1-10","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":10,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"击水：（到中流击水，浪遏飞舟）","language":"中文","translation":false},{"id":"mao-poetry-1-11","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":11,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"游泳，那时初学，盛夏水涨，几死者数。一群入终于坚持到隆冬。犹在水中。当时有一篇忘记了。只记得两句：“自信人生两百年，会当击水三千里。”","language":"中文","translation":false},{"id":"mao-poetry-1-12","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":12,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"菩萨蛮.黄鹤楼","language":"中文","translation":false},{"id":"mao-poetry-1-13","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":13,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九二七年","language":"中文","translation":false},{"id":"mao-poetry-1-14","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":14,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"心潮：（把酒酌滔滔。心潮逐浪高）","language":"中文","translation":false},{"id":"mao-poetry-1-15","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":15,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九二七年大革命失败的前夕，心情苍凉，一时不知如何是好。这是那年春季。夏季八月七日，党的紧急会议决定武装斗争。从此才找到了出路。","language":"中文","translation":false},{"id":"mao-poetry-1-16","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":16,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"清平乐.会昌","language":"中文","translation":false},{"id":"mao-poetry-1-17","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":17,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九三四年夏","language":"中文","translation":false},{"id":"mao-poetry-1-18","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":18,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"踏遍青山人未老：（踏遍青山人未老，风景这边独好。）","language":"中文","translation":false},{"id":"mao-poetry-1-19","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":19,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九三四年形势危急。准备长征，心情又是郁闷的。这首清平乐与前面那首菩萨蛮一样，表露了同一的心情。","language":"中文","translation":false},{"id":"mao-poetry-1-20","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":20,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"忆泰娥.娄山关","language":"中文","translation":false},{"id":"mao-poetry-1-21","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":21,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九三五年","language":"中文","translation":false},{"id":"mao-poetry-1-22","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":22,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"万里长征，千回百折。胜少于困难不知多少倍。心情是沉郁的。过了岷山，豁然开朗，转到了反面，柳暗花明又一村了。以下几首反映了这种心情。","language":"中文","translation":false},{"id":"mao-poetry-1-23","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":23,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"七律.长征一九三五年十月","language":"中文","translation":false},{"id":"mao-poetry-1-24","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":24,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"水拍：（金沙水拍云崖暖，大渡桥横铁索寒）","language":"中文","translation":false},{"id":"mao-poetry-1-25","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":25,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"改水拍，这是一位不相识的朋友建议的。他说：不要一篇有两个“浪”字，是可以的。","language":"中文","translation":false},{"id":"mao-poetry-1-26","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":26,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"三军：（更喜岷山千里雪，三军过后尽开颜。）","language":"中文","translation":false},{"id":"mao-poetry-1-27","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":27,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"红军一方面军、二方面军、四方面军。不是陆海空三军，也不是古代晋国所谓上军，中军、下军的三军。","language":"中文","translation":false},{"id":"mao-poetry-1-28","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":28,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"念奴娇.昆仑","language":"中文","translation":false},{"id":"mao-poetry-1-29","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":29,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九三五年十月","language":"中文","translation":false},{"id":"mao-poetry-1-30","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":30,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"主题思想是反对帝国主义，不是别的。后一句：“一截留中国”改为“一截还东国”。忘记了日本人民是不对的。这样，英、美、日都涉及了。别的解释不合实际。","language":"中文","translation":false},{"id":"mao-poetry-1-31","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":31,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"清平乐.六盘山","language":"中文","translation":false},{"id":"mao-poetry-1-32","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":32,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九三五年十月","language":"中文","translation":false},{"id":"mao-poetry-1-33","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":33,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"苍龙：（今日长缨在手，何时缚住苍龙？）指蒋介石。不是日本人。因为当时全付精力要对付的是蒋不是日。","language":"中文","translation":false},{"id":"mao-poetry-1-34","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":34,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"沁园春.雪","language":"中文","translation":false},{"id":"mao-poetry-1-35","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":35,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九三六年二月","language":"中文","translation":false},{"id":"mao-poetry-1-36","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":36,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"反对封建主义，批判两千年来的封建主义的一个反动侧面。","language":"中文","translation":false},{"id":"mao-poetry-1-37","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":37,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"文釆、风骚、大雕，只能如此，须知这是写诗啊，难道可以咒骂这些人吗？别的解释是错误的。","language":"中文","translation":false},{"id":"mao-poetry-1-38","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":38,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"末三句，指无产阶级。","language":"中文","translation":false},{"id":"mao-poetry-1-39","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":39,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"七律.和柳亚子先生","language":"中文","translation":false},{"id":"mao-poetry-1-40","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":40,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九四九年四月二十九日","language":"中文","translation":false},{"id":"mao-poetry-1-41","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":41,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"三十一年：（三十一年还旧国。落花时节馈华章）","language":"中文","translation":false},{"id":"mao-poetry-1-42","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":42,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九一九年离开北京。一九四九年还北京。旧国之国：都城。不是Ltoho（国家）。也不是Country（首都）。","language":"中文","translation":false},{"id":"mao-poetry-1-43","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":43,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"浣溪纱.和柳亚子先生","language":"中文","translation":false},{"id":"mao-poetry-1-44","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":44,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九五○年十月","language":"中文","translation":false},{"id":"mao-poetry-1-45","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":45,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"乐奏：（万方乐奏有于阗）这里误置为“奏乐”。应改。（现版已改）","language":"中文","translation":false},{"id":"mao-poetry-1-46","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":46,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"水调歌头.游泳","language":"中文","translation":false},{"id":"mao-poetry-1-47","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":47,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"一九五六年六月","language":"中文","translation":false},{"id":"mao-poetry-1-48","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":48,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"长沙水：（才饮长沙水）民谣：“常德山山有德，长沙水水无沙”。所谓长沙水，在常德东。有一个有名的“白沙井”。","language":"中文","translation":false},{"id":"mao-poetry-1-49","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":49,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"武昌鱼：（又食武昌鱼）","language":"中文","translation":false},{"id":"mao-poetry-1-50","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":50,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"三国孙权一度从京口（镇江）迁都武昌。官僚、绅士、地主及富裕阶层不悦，反对迁都。造出口号云：“宁饮扬州（建业）水。不食武昌鱼”。那时的扬州人，心情如此。现在改变了。武昌鱼是颇有味道的。","language":"中文","translation":false},{"id":"mao-poetry-1-51","author":"毛泽东","title":"毛泽东诗词及本人说明","location":"给自己诗词作的解释","page":1,"paragraph":51,"url":"https://www.marxists.org/chinese/maozedong/1968/4-098.htm","text":"上一页 目录 下一页","language":"中文","translation":false}];
